#ifndef RINGBUF_H
#define RINGBUF_H

#include <stddef.h>

#define RINGBUF_CAP 64

typedef struct {
    int data[RINGBUF_CAP];
    size_t head;
    size_t tail;
    size_t size;
} ringbuf;

static inline void rb_init(ringbuf *rb) {
    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
}

static inline int rb_push(ringbuf *rb, int value) {
    if (rb->size == RINGBUF_CAP) return 0;
    rb->data[rb->tail] = value;
    rb->tail = (rb->tail + 1) % RINGBUF_CAP;
    rb->size++;
    return 1;
}

static inline int rb_pop(ringbuf *rb, int *out) {
    if (rb->size == 0) return 0;
    *out = rb->data[rb->head];
    rb->head = (rb->head + 1) % RINGBUF_CAP;
    rb->size--;
    return 1;
}

#endif

