        return None
    files = [f for f in os.listdir(directory) if f.endswith(('.py', '.sql'))]
    if not files:
        return None
    return max(files, key=lambda f: os.path.getmtime(os.path.join(directory, f)))

def main():
    mig_dir = sys.argv[1] if len(sys.argv) > 1 else 'migrations'
    newest = newest_migration(mig_dir)
    if newest is None:
        print('no migrations found', file=sys.stderr)
        return 0
    if newest.lower().startswith('head'):
        print('HEAD is newest')
        return 0
    print(f'unapplied? {newest}', file=sys.stderr)
    return 1

if __name__ == '__main__':
    sys.exit(main())

