        assert_eq!(slugify("Café  Crème"), "café-crème");
    }

    #[test]
    fn empty() {
        assert_eq!(slugify(""), "");
    }

    #[test]
    fn no_leading_or_trailing_dash() {
        assert_eq!(slugify("  --Hi There-- "), "hi-there");
    }
}

