import csv
import sys


def average_temp(path):
    values = []
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            raw = (row.get('temp') or '').strip()
            if not raw:
                continue
            try:
                values.append(float(raw))
            except ValueError:
                continue
    if not values:
        return None
    return sum(values) / len(values)


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else 'sensors.csv'
    avg = average_temp(path)
    if avg is None:
        print('no numeric temp values found')
        return 1
    print(f'{avg:.2f}')
    return 0


if __name__ == '__main__':
