import csv
import sys


def column_sums(path: str) -> dict:
    totals: dict[str, float] = {}
    counts: dict[str, int] = {}
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            for key, raw in row.items():
                if raw is None or raw.strip() == "":
                    continue
                try:
                    val = float(raw)
                except ValueError:
                    continue
                totals[key] = totals.get(key, 0.0) + val
                counts[key] = counts.get(key, 0) + 1
    return {k: totals[k] for k in totals}


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: python sums.py <file.csv>", file=sys.stderr)
        sys.exit(2)
    for name, total in column_sums(sys.argv[1]).items():
        print(f"{name}: {total:g}")

