use std::env;
use std::fs;

fn main() {
    let path = match env::args().nth(1) {
        Some(p) => p,
        None => {
            eprintln!("usage: topscores <file>");
            std::process::exit(2);
        }
    };
    let text = match fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {}: {}", path, e);
            std::process::exit(1);
        }
    };
    let mut best: Option<(String, i64)> = None;
    for line in text.lines() {
        let mut it = line.splitn(2, ',');
        let name = it.next().unwrap_or("").trim();
        let score = match it.next().and_then(|s| s.trim().parse::<i64>().ok()) {
            Some(v) => v,
            None => continue,
        };
        if name.is_empty() {
            continue;
        }
        if best.as_ref().map_or(true, |(_, b)| score > *b) {
            best = Some((name.to_string(), score));
        }
    }
    match best {
        Some((name, score)) => println!("{} {}", name, score),
        None => println!("no valid rows"),
    }
}

