size_t safe_copy(char *dst, const char *src, size_t cap) {
    if (cap == 0) return 0;
    size_t i = 0;
    while (i < cap - 1 && src[i] != '\0') {
        dst[i] = src[i];
        i++;
    }
    dst[i] = '\0';
    return i;
}

