It's declared at line 18, with `struct pb_field` following at line 29. Ownership isn't obvious from the header — `name` and `fields` are raw pointers, so whoever allocates the struct is responsible for freeing them.

int parse_header(const char *line, char *key, size_t klen, char *val, size_t vlen) {
    const char *colon = strchr(line, ':');
    if (!colon) return -1;
    size_t k = colon - line;
    if (k >= klen) return -1;
    memcpy(key, line, k);
    key[k] = '\0';
    const char *v = colon + 1;
    while (*v == ' ') v++;
    strncpy(val, v, vlen - 1);
    val[vlen - 1] = '\0';
    return 0;
}

