def find_dupes(pairs):
    seen = set()
    for key, _ in pairs:
        if key in seen:
            dupes.append(key)
        seen.add(key)
    return dict(pairs)


def check(path):
    global dupes
    dupes = []
    with open(path, encoding="utf-8") as fh:
        json.load(fh, object_pairs_hook=find_dupes)
    return dupes


