def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start = end = 0
    for i in range(len(s)):
        for lo, hi in ((i, i), (i, i + 1)):
            while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
                lo -= 1
                hi += 1
            lo += 1
            hi -= 1
            if hi - lo > end - start:
                start, end = lo, hi
    return s[start:end + 1]

def parse_line(line):
    fields, buf, in_quotes, i = [], [], False, 0
    while i < len(line):
        c = line[i]
        if in_quotes:
            if c == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    buf.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                buf.append(c)
        elif c == '"':
            in_quotes = True
        elif c == ',':
            fields.append(''.join(buf).strip())
            buf = []
        else:
            buf.append(c)
        i += 1
    fields.append(''.join(buf).strip())
    return fields


def parse(text):
    return [parse_line(l) for l in text.splitlines() if l]

