#pragma once
#include <array>
#include <cstddef>
#include <optional>

template <typename T, std::size_t N>
class Ring {
public:
    bool push(const T& v) {
        if (size_ == N) return false;
        buf_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }
    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T v = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }
    std::size_t size() const { return size_; }
private:
    std::array<T, N> buf_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

#include "ring.h"
#include <cassert>
#include <iostream>

int main() {
    Ring<int, 3> r;
    assert(r.push(1) && r.push(2) && r.push(3));
    assert(!r.push(4));            // full
    assert(r.pop() == 1);          // wrap begins
    assert(r.push(4));
    assert(r.pop() == 2);
    assert(r.pop() == 3);
    assert(r.pop() == 4);
    assert(r.pop() == std::nullopt);
    assert(r.size() == 0);
    std::cout << "ok\n";
    return 0;
}

