fn with_retry<F, T>(mut f: F) -> Result<T>
where F: FnMut() -> Result<T> {
    let mut delay = BASE_DELAY_MS;
    for attempt in 0..=MAX_RETRIES {
        match f() {
            Ok(v) => return Ok(v),
            Err(e) if attempt == MAX_RETRIES => return Err(e),
            Err(_) => { sleep(delay); delay *= 2; }
        }
    }
    unreachable!()
}

