std::unordered_map<std::string, int> word_freq(const std::string& text) {
    std::unordered_map<std::string, int> counts;
    std::string word;
    for (unsigned char ch : text) {
        if (std::isalnum(ch)) {
            word.push_back(static_cast<char>(std::tolower(ch)));
        } else if (!word.empty()) {
            ++counts[word];
            word.clear();
        }
    }
    if (!word.empty()) {
        ++counts[word];
    }
    return counts;
}

void print_top(const std::unordered_map<std::string, int>& counts, std::size_t n) {
    std::vector<std::pair<std::string, int>> items(counts.begin(), counts.end());
    std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });
    for (std::size_t i = 0; i < items.size() && i < n; ++i) {
        std::cout << items[i].first << ": " << items[i].second << '\n';
    }
}

int main() {
    auto counts = word_freq("The cat, the dog! The CAT ran.");
    print_top(counts, 2);
    return 0;
}
