template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (count_ < N) ++count_;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        std::size_t idx = (head_ + N - count_) % N;
        --count_;
        return data_[idx];
    }

    std::size_t size() const { return count_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4); // overwrites 1
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n';
    return 0;
}
