def is_valid_isbn10(raw: str) -> bool:
    digits = [c for c in raw if c != '-']
    if len(digits) != 10:
        return False
    total = 0
    for i, ch in enumerate(digits):
        if ch == 'X' and i == 9:
            value = 10
        elif ch.isdigit():
            value = int(ch)
        else:
            return False
        total += value * (10 - i)
    return total % 11 == 0


