void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = 0;
    while (s[len] != '\0') len++;
    if (len < 2) return;
    size_t i = 0;
    size_t j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

int main(void) {
    char buf[] = "hello";
    reverse_in_place(buf);
    if (strcmp(buf, "olleh") != 0) return 1;

    char single[] = "x";
    reverse_in_place(single);
    if (strcmp(single, "x") != 0) return 1;

    puts("ok");
    return 0;
}
