import sys

def longest_run(nums):
    if not nums:
        return [], 0
    best_start = cur_start = 0
    best_len = cur_len = 1
    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            cur_len += 1
        else:
            cur_start = i
            cur_len = 1
        if cur_len > best_len:
            best_len = cur_len
            best_start = cur_start
    run = nums[best_start:best_start + best_len]
    return run, best_len

def main():
    nums = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        nums.append(int(line))
    run, length = longest_run(nums)
    if length == 0:
        print("empty input: no run")
    else:
        print("length:", length)
        print("run:", " ".join(map(str, run)))

if __name__ == "__main__":
