```rust
use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum ParseError {
    MissingEquals(String),
    DuplicateKey(String),
}

fn parse(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    for pair in input.split(';').map(str::trim).filter(|s| !s.is_empty()) {
        let (k, v) = match pair.split_once('=') {
            Some(kv) => kv,
            None => return Err(ParseError::MissingEquals(pair.to_string())),
        };
        let key = k.trim().to_string();
        if map.contains_key(&key) {
            return Err(ParseError::DuplicateKey(key));
        }
        map.insert(key, v.trim().to_string());
    }
    Ok(map)
}

fn main() {
    match parse("a=1; b=2; c=hello world") {
        Ok(m) => {
            let mut keys: Vec<_> = m.iter().collect();
            keys.sort();
            for (k, v) in keys {
                println!("{k} -> {v}");
            }
        }
        Err(e) => println!("error: {e:?}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_valid() {
        let m = parse("x=1; y=2").unwrap();
        assert_eq!(m["x"], "1");
        assert_eq!(m["y"], "2");
    }

    #[test]
    fn rejects_duplicates() {
        assert_eq!(parse("a=1; a=2"), Err(ParseError::DuplicateKey("a".into())));
    }

    #[test]
    fn rejects_missing_equals() {
        assert_eq!(parse("a=1; bad"), Err(ParseError::MissingEquals("bad".into())));
    }

    #[test]
    fn empty_input_is_empty_map() {
        assert!(parse("  ;  ").unwrap().is_empty());
    }
}
