```python
import re

_OCTET = re.compile(r"^(0|[1-9][0-9]{0,2})$")

def is_valid_ipv4(addr: str) -> bool:
    """True iff addr is a dotted-quad IPv4 with no leading zeros."""
    if not isinstance(addr, str):
        return False
    parts = addr.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not _OCTET.match(part):
            return False
        if int(part) > 255:
            return False
    return True

if __name__ == "__main__":
    cases = ["192.168.0.1", "0.0.0.0", "255.255.255.255",
             "256.1.1.1", "01.2.3.4", "1.2.3", "1.2.3.4.5",
             "", "1.2.3.4 ", "a.b.c.d"]
    for c in cases:
        print(f"{c!r:18} -> {is_valid_ipv4(c)}")
```

The `_OCTET` pattern forbids leading zeros (`01`) while allowing plain `0`. Empty strings fail the length check before any regex. Whitespace fails because no part matches the anchored pattern.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(const char *label, Node *head) {
    printf("%s:", label);
    for (; head; head = head->next) {
        printf(" %d", head->value);
    }
    printf("\n");
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    print_list("empty", head);

    for (int i = 1; i <= 5; i++) {
        head = push(head, i);
    }
    print_list("original", head);
    head = reverse(head);
    print_list("reversed", head);

    free_list(head);
    return 0;
}
```

`push` prepends, so the list reads 5 4 3 2 1; after `reverse` it reads 1 2 3 4 5. The three-pointer walk handles length 0 and 1 without special-casing.

