```cpp
#include <iostream>
#include <utility>

constexpr long long MOD = 1000000007LL;

std::pair<long long, long long> fib_pair(long long n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n / 2);
    long long c = a * ((2 * b - a + MOD) % MOD) % MOD;
    long long d = (a * a + b * b) % MOD;
    if (n % 2 == 0) return {c, d};
    return {d, (c + d) % MOD};
}

long long fib(long long n) {
    return fib_pair(n).first;
}

int main() {
    std::cout << "fib(0) = " << fib(0) << '\n';
    std::cout << "fib(10) = " << fib(10) << '\n';
    std::cout << "fib(100) = " << fib(100) << '\n';
    return 0;
}
```

Fast doubling is O(log n). `(2*b - a + MOD) % MOD` keeps the subtraction non-negative before the modulo. Expected output: `0`, `55`, and `687995182` (fib(100) = 354224848179261915075 mod 1e9+7).

