```cpp
#include <array>
#include <cstddef>
#include <optional>

class RingBuffer {
public:
    static constexpr std::size_t kCapacity = 8;

    bool push(int value) {
        if (size_ == kCapacity) {
            return false;
        }
        data_[(head_ + size_) % kCapacity] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        int value = data_[head_];
        head_ = (head_ + 1) % kCapacity;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<int, kCapacity> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

#include <cassert>

int main() {
    RingBuffer rb;
    for (int i = 0; i < 8; ++i) assert(rb.push(i));
    assert(!rb.push(99));            // full, rejected
    assert(rb.pop().value() == 0);
    assert(rb.size() == 7);
    assert(rb.push(42));             // room after pop
    while (!rb.empty()) rb.pop();
    assert(rb.pop() == std::nullopt);
    return 0;
}
```

The `head_`/`size_` pair means no element shifting; the modulo wraps writes and reads. `std::optional` signals an empty pop without sentinel values.

```c
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) {
        return;
    }
    char *left = s;
    char *right = s + strlen(s);
    if (left == right) {
        return;
    }
    --right;
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        ++left;
        --right;
    }
}

int main(void) {
    char sample[] = "hello, world";
    reverse_in_place(sample);
    printf("%s\n", sample);

    char empty[] = "";
    reverse_in_place(empty);
    printf("[%s]\n", empty);

    char single[] = "x";
    reverse_in_place(single);
    printf("%s\n", single);

    char even[] = "abcd";
    reverse_in_place(even);
    printf("%s\n", even);

    return 0;
}
```

`strlen` gives one past the last character, so `right` steps back before the swap loop. A mutable `char[]` is used rather than a string literal, because writing to a literal is undefined behaviour. Empty and single-character inputs are guarded so the loop does not run off the start.

```rust
use std::collections::HashMap;

fn two_sum(nums: &[i64], target: i64) -> Option<(usize, usize)> {
    let mut seen: HashMap<i64, usize> = HashMap::with_capacity(nums.len());
    for (i, &value) in nums.iter().enumerate() {
        let need = target - value;
        if let Some(&j) = seen.get(&need) {
            return Some((j, i));
        }
        seen.insert(value, i);
    }
    None
}

fn main() {
    assert_eq!(two_sum(&[2, 7, 11, 15], 9), Some((0, 1)));
    assert_eq!(two_sum(&[3, 3], 6), Some((0, 1)));
    assert_eq!(two_sum(&[1, 2, 3], 7), None);
    assert_eq!(two_sum(&[], 0), None);
    assert_eq!(two_sum(&[5], 10), None);

    match two_sum(&[4, 6, 3, 9], 12) {
        Some((a, b)) => println!("indices {a} and {b}"),
        None => println!("no pair"),
