```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {}

    void push(int value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [this] { return queue_.size() < capacity_ || closed_; });
        if (closed_) {
            return;
        }
        queue_.push(value);
        lock.unlock();
        not_empty_.notify_one();
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock, [this] { return !queue_.empty() || closed_; });
        if (queue_.empty()) {
            return std::nullopt;
        }
        int value = queue_.front();
        queue_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::queue<int> queue_;
    std::mutex mutex_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
    std::size_t capacity_;
    bool closed_ = false;
};

#include <cassert>
#include <thread>

int main() {
    BoundedQueue q(2);
    q.push(1);
    q.push(2);
    assert(q.pop().value() == 1);
    q.push(3);
    q.close();
    assert(q.pop().value() == 2);
    assert(q.pop().value() == 3);
    assert(q.pop() == std::nullopt);

    BoundedQueue shared(1);
    std::thread producer([&] { for (int i = 0; i < 5; ++i) shared.push(i); });
    int total = 0;
    for (int i = 0; i < 5; ++i) total += shared.pop().value();
    producer.join();
    assert(total == 0 + 1 + 2 + 3 + 4);
    return 0;
}
```

The wait predicates include `closed_`, so `close()` wakes blocked threads and lets them drain instead of hanging. Unlocking before `notify_one` avoids waking a thread that immediately blocks on the still-held mutex.

