using ull = unsigned long long;

bool lcm_safe(ull a, ull b, ull& out) {
    if (a == 0 || b == 0) { out = 0; return true; }
    ull g = std::gcd(a, b);
    ull x = a / g;
    if (x > ULLONG_MAX / b) return false;
    out = x * b;
    return true;
}

int main() {
    ull r = 0;
    if (lcm_safe(4, 6, r)) std::cout << "lcm(4,6)=" << r << '\n';
    if (lcm_safe(0, 7, r)) std::cout << "lcm(0,7)=" << r << '\n';
    if (lcm_safe(ULLONG_MAX, ULLONG_MAX - 1, r)) std::cout << "big=" << r << '\n';
    else std::cout << "big=overflow\n";
}
