#include <cassert>
#include <iostream>
#include <vector>

using Matrix = std::vector<std::vector<int>>;

bool multiply(const Matrix& a, const Matrix& b, Matrix& out) {
    if (a.empty() || b.empty() || a[0].empty() || b[0].empty()) return false;
    size_t n = a.size(), m = a[0].size(), p = b[0].size();
    if (b.size() != m) return false;
    for (const auto& row : a) if (row.size() != m) return false;
    for (const auto& row : b) if (row.size() != p) return false;
    out.assign(n, std::vector<int>(p, 0));
    for (size_t i = 0; i < n; ++i)
        for (size_t k = 0; k < m; ++k)
            for (size_t j = 0; j < p; ++j)
                out[i][j] += a[i][k] * b[k][j];
    return true;
}

int main() {
    Matrix a = {{1, 2}, {3, 4}};
    Matrix b = {{5, 6}, {7, 8}};
    Matrix c;
    assert(multiply(a, b, c));
    assert((c == Matrix{{19, 22}, {43, 50}}));
    Matrix bad;
    assert(!multiply(a, {{1, 2, 3}}, bad));
    std::cout << "ok\n";
}
