use std::collections::HashMap;

fn fib(n: u64, memo: &mut HashMap<u64, u128>) -> u128 {
    if let Some(&v) = memo.get(&n) {
        return v;
    }
    let v = match n {
        0 => 0,
        1 => 1,
        _ => fib(n - 1, memo) + fib(n - 2, memo),
    };
    memo.insert(n, v);
    v
}

fn main() {
    let mut memo = HashMap::new();
    assert_eq!(fib(0, &mut memo), 0);
    assert_eq!(fib(10, &mut memo), 55);
    assert_eq!(fib(100, &mut memo), 354224848179261915075);
    println!("ok");
