import csv
import sys


def average_score(path):
    scores = []
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.reader(fh)
        for row in reader:
            if not row or all(cell.strip() == "" for cell in row):
                continue
            if len(row) < 2:
                continue
            name, raw = row[0].strip(), row[1].strip()
            if not name or not raw:
                continue
            try:
                scores.append(float(raw))
            except ValueError:
                continue
    if not scores:
        return None
    return sum(scores) / len(scores)


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: average_score.py <file.csv>", file=sys.stderr)
        raise SystemExit(2)
    result = average_score(sys.argv[1])
    if result is None:
        print("no valid scores found", file=sys.stderr)
        raise SystemExit(1)
    print(f"average score: {result:.2f}")
