#include <cstdlib>
#include <iostream>
#include <vector>

std::vector<int> primes_up_to(int limit) {
    std::vector<int> primes;
    if (limit < 2) {
        return primes;
    }
    std::vector<bool> composite(static_cast<std::size_t>(limit) + 1, false);
    for (int n = 2; n <= limit; ++n) {
        if (!composite[static_cast<std::size_t>(n)]) {
            primes.push_back(n);
            for (long long m = static_cast<long long>(n) * n; m <= limit; m += n) {
                composite[static_cast<std::size_t>(m)] = true;
            }
        }
    }
    return primes;
}

int main(int argc, char** argv) {
    long limit = 30;
    if (argc > 1) {
        char* end = nullptr;
        limit = std::strtol(argv[1], &end, 10);
        if (end == argv[1] || *end != '\0' || limit < 0) {
            std::cerr << "usage: " << argv[0] << " [non-negative limit]\n";
            return 2;
        }
    }
    for (int p : primes_up_to(static_cast<int>(limit))) {
        std::cout << p << ' ';
    }
    std::cout << '\n';
    return 0;
}
