```rust
use std::cmp::Ordering;
use std::io::{self, BufRead};

#[derive(Debug)]
struct Version {
    major: u64,
    minor: u64,
    patch: u64,
    pre: String,
}

fn parse(input: &str) -> Option<Version> {
    let (core, pre) = match input.split_once('-') {
        Some((core, pre)) => (core, pre.to_string()),
        None => (input, String::new()),
    };
    let mut parts = core.split('.');
    let major = parts.next()?.parse().ok()?;
    let minor = parts.next()?.parse().ok()?;
    let patch = parts.next()?.parse().ok()?;
    if parts.next().is_some() {
        return None;
    }
    Some(Version { major, minor, patch, pre })
}

fn compare(a: &Version, b: &Version) -> Ordering {
    (a.major, a.minor, a.patch)
        .cmp(&(b.major, b.minor, b.patch))
        .then_with(|| match (a.pre.is_empty(), b.pre.is_empty()) {
            (true, true) => Ordering::Equal,
            (true, false) => Ordering::Greater,
            (false, true) => Ordering::Less,
            (false, false) => a.pre.cmp(&b.pre),
        })
}

fn main() {
    let stdin = io::stdin();
    let mut versions: Vec<(Version, String)> = Vec::new();
    for line in stdin.lock().lines() {
        let line = line.unwrap_or_default();
        let text = line.trim();
        if text.is_empty() {
            continue;
        }
        match parse(text) {
            Some(version) => versions.push((version, text.to_string())),
            None => eprintln!("skipping invalid version: {}", text),
        }
    }
    versions.sort_by(|a, b| compare(&a.0, &b.0));
    for (_, text) in versions {
        println!("{}", text);
    }
}
