static void merge_sort(std::vector<int>& v, std::vector<int>& tmp, int lo, int hi) {
    if (hi - lo <= 1) {
        return;
    }
    int mid = lo + (hi - lo) / 2;
    merge_sort(v, tmp, lo, mid);
    merge_sort(v, tmp, mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        tmp[k++] = (v[i] <= v[j]) ? v[i++] : v[j++];
    }
    while (i < mid) tmp[k++] = v[i++];
    while (j < hi) tmp[k++] = v[j++];
    for (int t = lo; t < hi; ++t) {
        v[t] = tmp[t];
    }
}

int main() {
