import functools
import time


def retry(attempts=3, base_delay=0.1, exceptions=(Exception,)):
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last = None
            for i in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if i < attempts - 1:
                        time.sleep(base_delay * (2 ** i))
            raise last
        return wrapper
    return decorator
