template <typename T, std::size_t N>
class Ring {
    std::array<T, N> buf_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;

public:
    void push(const T& v) {
        buf_[(head_ + size_) % N] = v;
        if (size_ < N) {
            ++size_;
        } else {
            head_ = (head_ + 1) % N;
        }
    }

    const T& front() const {
        if (size_ == 0) throw std::out_of_range("empty");
        return buf_[head_];
    }

    std::size_t size() const { return size_; }
};

int main() {
    Ring<int, 3> r;
    for (int i = 1; i <= 5; ++i) r.push(i);
    std::cout << r.front() << " " << r.size() << "\n";  // 3 3
}
