int first_index(const std::vector<int>& data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size()) - 1;
    int found = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (data[mid] == target) {
            found = mid;
            hi = mid - 1;
        } else if (data[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return found;
}

int main() {
    std::vector<int> data{1, 2, 4, 4, 4, 5, 9};
    if (first_index(data, 4) != 2) return 1;
    if (first_index(data, 1) != 0) return 1;
    if (first_index(data, 9) != 6) return 1;
