def rle_encode(data: str) -> str:
    if not data:
        return ""
    parts = []
    count = 1
    for i in range(1, len(data)):
        if data[i] == data[i - 1]:
            count += 1
        else:
            parts.append(f"{data[i - 1]}{count}")
            count = 1
    parts.append(f"{data[-1]}{count}")
    return "".join(parts)

def rle_decode(encoded: str) -> str:
    out = []
    i = 0
    while i < len(encoded):
        ch = encoded[i]
        i += 1
        num_start = i
        while i < len(encoded) and encoded[i].isdigit():
            i += 1
        if num_start == i:
            raise ValueError(f"missing count at position {num_start}")
        out.append(ch * int(encoded[num_start:i]))
    return "".join(out)

if __name__ == "__main__":
    for source in ["", "aaabbc", "abc", "aaaaaaaaaaaa"]:
        assert rle_decode(rle_encode(source)) == source
    assert rle_encode("aaabbc") == "a3b2c1"
    print("ok")
