#include <cassert>
#include <iostream>
#include <vector>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

std::vector<int> to_vector(Node* head) {
    std::vector<int> out;
    for (Node* cur = head; cur != nullptr; cur = cur->next) out.push_back(cur->value);
    return out;
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(4);
    Node* rev = reverse(head);
    assert(to_vector(rev) == (std::vector<int>{4, 3, 2, 1}));
    assert(reverse(nullptr) == nullptr);
    while (rev) { Node* n = rev->next; delete rev; rev = n; }
    std::cout << "ok\n";
}
