```cpp
#include <algorithm>
#include <iostream>
#include <vector>

// Returns the first index of value, or -1 if it is absent.
template <typename T>
int first_index_of(const std::vector<T>& data, const T& value) {
    auto it = std::lower_bound(data.begin(), data.end(), value);
    if (it == data.end() || *it != value) {
        return -1;
    }
    return static_cast<int>(it - data.begin());
}

int main() {
    std::vector<int> empty;
    std::vector<int> v{1, 3, 3, 3, 7, 9};
    std::cout << first_index_of(empty, 3) << '\n';  // -1
    std::cout << first_index_of(v, 3) << '\n';      // 1
    std::cout << first_index_of(v, 7) << '\n';      // 4
    std::cout << first_index_of(v, 4) << '\n';      // -1
}
