Matrix multiplication with shape checking:

```cpp
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

using Matrix = std::vector<std::vector<long long>>;

Matrix multiply(const Matrix& a, const Matrix& b) {
    if (a.empty()) {
        return {};
    }
    const std::size_t m = b.size();
    if (m == 0) {
        throw std::invalid_argument("right operand is empty");
    }
    const std::size_t p = b[0].size();
    for (const auto& row : a) {
        if (row.size() != m) {
            throw std::invalid_argument("shape mismatch");
        }
    }
    Matrix out(a.size(), std::vector<long long>(p, 0));
    for (std::size_t i = 0; i < a.size(); ++i) {
        for (std::size_t k = 0; k < m; ++k) {
            for (std::size_t j = 0; j < p; ++j) {
                out[i][j] += a[i][k] * b[k][j];
            }
        }
    }
    return out;
}

int main() {
    Matrix a{{1, 2}, {3, 4}};
    Matrix b{{5, 6}, {7, 8}};
    for (const auto& row : multiply(a, b)) {
        for (long long v : row) {
            std::cout << v << ' ';
        }
        std::cout << '\n';
    }
}
