Parse key=value config text with a small error type:

```rust
use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
enum ConfigError {
    MissingEquals(String),
    EmptyKey(usize),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::MissingEquals(line) => write!(f, "missing '=' in {:?}", line),
            ConfigError::EmptyKey(n) => write!(f, "empty key on line {}", n),
        }
    }
}

fn parse_config(input: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut map = HashMap::new();
    for (i, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line
            .split_once('=')
            .ok_or_else(|| ConfigError::MissingEquals(line.to_string()))?;
        let key = key.trim();
        if key.is_empty() {
            return Err(ConfigError::EmptyKey(i + 1));
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let text = "# config\nname = luna\nmode=fast\n";
    let cfg = parse_config(text).unwrap();
    println!("{:?}", cfg.get("name"));
    println!("{:?}", parse_config("oops"));
}
