```rust
fn intersection(a: &[i32], b: &[i32]) -> Vec<i32> {
    let (mut i, mut j) = (0, 0);
    let mut out: Vec<i32> = Vec::new();
    while i < a.len() && j < b.len() {
        match a[i].cmp(&b[j]) {
            std::cmp::Ordering::Less => i += 1,
            std::cmp::Ordering::Greater => j += 1,
            std::cmp::Ordering::Equal => {
                if out.last() != Some(&a[i]) {
                    out.push(a[i]);
                }
                i += 1;
                j += 1;
            }
        }
    }
    out
}

fn main() {
    let a = [1, 2, 2, 3, 5, 8];
    let b = [2, 2, 4, 5, 8, 8, 9];
    println!("{:?}", intersection(&a, &b)); // [2, 5, 8]
    println!("{:?}", intersection(&[], &b)); // []
}
