    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack


if __name__ == "__main__":
    assert brackets_balanced("a(b[c]{d})e") is True
    assert brackets_balanced("([)]") is False
    assert brackets_balanced("(") is False
    assert brackets_balanced("") is True
    print("ok")
