#!/usr/bin/env python3
"""Top-N word frequencies for a UTF-8 text file."""
import re
import sys
import unicodedata
from collections import Counter

WORD_RE = re.compile(r"\w+(?:['-]\w+)*", re.UNICODE)


def normalize(token):
    return unicodedata.normalize("NFKC", token).casefold()


def word_counts(path):
    counts = Counter()
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            for line in fh:
                for token in WORD_RE.findall(line):
                    word = normalize(token)
                    if word:
                        counts[word] += 1
    except FileNotFoundError:
        print("error: no such file:", path, file=sys.stderr)
        raise SystemExit(2)
    return counts


def main(argv):
    if len(argv) != 2:
        print("usage: wordfreq.py <file>", file=sys.stderr)
        return 1
    counts = word_counts(argv[1])
    if not counts:
        print("(no words found)")
        return 0
    width = len(str(max(counts.values())))
    for word, n in counts.most_common(10):
        print(f"{n:>{width}}  {word}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
