#!/usr/bin/env python3
"""Retry decorator with exponential backoff and jitter, stdlib only."""
import functools
import random
import time


def retry(attempts=4, base_delay=0.1, max_delay=5.0, exceptions=(Exception,)):
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt == attempts - 1:
                        break
                    delay = min(max_delay, base_delay * (2 ** attempt))
                    delay += random.uniform(0, delay / 2)
                    time.sleep(delay)
            raise last

        return wrapper

    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=3, base_delay=0.01)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ConnectionError("temporary failure")
        return "ok after {} attempts".format(calls["n"])

    print(flaky())
