#!/usr/bin/env python3
"""Search a rotated sorted array in O(log n) with explicit bounds checks."""
from typing import List, Optional


def search_rotated(nums: List[int], target: int) -> Optional[int]:
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[lo] <= nums[mid]:
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return None


if __name__ == "__main__":
    cases = [
        ([4, 5, 6, 7, 0, 1, 2], 0, 4),
        ([4, 5, 6, 7, 0, 1, 2], 3, None),
        ([], 1, None),
        ([1], 1, 0),
        ([3, 1], 1, 1),
    ]
    for nums, target, expected in cases:
        got = search_rotated(nums, target)
        assert got == expected, (nums, target, got, expected)
    print("all cases pass")
