// run_length.cpp: run-length encode a string and verify the round trip.
#include <cassert>
#include <cctype>
#include <iostream>
#include <string>

std::string encode(const std::string& input) {
    std::string out;
    std::size_t i = 0;
    while (i < input.size()) {
        std::size_t j = i;
        while (j < input.size() && input[j] == input[i]) {
            ++j;
        }
        out += input[i];
        out += std::to_string(j - i);
        i = j;
    }
    return out;
}

std::string decode(const std::string& encoded) {
    std::string out;
    std::size_t i = 0;
    while (i < encoded.size()) {
        const char symbol = encoded[i++];
        std::size_t count = 0;
        while (i < encoded.size() &&
               std::isdigit(static_cast<unsigned char>(encoded[i]))) {
            count = count * 10 + static_cast<std::size_t>(encoded[i] - '0');
            ++i;
        }
        out.append(count, symbol);
    }
    return out;
}

int main() {
    const std::string samples[] = {"", "a", "aaabbbcccd", "xyz"};
    for (const std::string& s : samples) {
        const std::string encoded = encode(s);
        assert(decode(encoded) == s);
        std::cout << s << " -> " << encoded << '\n';
    }
    std::cout << "round-trips ok\n";
    return 0;
}
