// sum_checked.rs: sum integers from stdin, reporting bad tokens and overflow.
use std::io::{self, BufRead};

fn main() {
    let mut total: i64 = 0;
    let mut skipped: usize = 0;
    let stdin = io::stdin();

    for line in stdin.lock().lines() {
        let line = line.unwrap_or_default();
        for token in line.split_whitespace() {
            match token.parse::<i64>() {
                Ok(value) => match total.checked_add(value) {
                    Some(sum) => total = sum,
                    None => {
                        eprintln!("overflow while adding {value}");
                        std::process::exit(3);
                    }
                },
                Err(_) => {
                    eprintln!("skipping non-integer: {token}");
                    skipped += 1;
                }
            }
        }
    }

    println!("total={total} skipped={skipped}");
}
