std::string encode(const std::string& s) {
    std::string out;
    for (std::size_t i = 0; i < s.size();) {
        std::size_t j = i;
        while (j < s.size() && s[j] == s[i]) {
            ++j;
        }
        out += std::to_string(j - i);
        out += s[i];
        i = j;
    }
    return out;
}

std::string decode(const std::string& s) {
    std::string out;
    std::size_t i = 0;
    while (i < s.size()) {
        if (!std::isdigit(static_cast<unsigned char>(s[i]))) {
            throw std::runtime_error("decode: expected a digit");
        }
        long long count = 0;
        while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
            count = count * 10 + (s[i] - '0');
            ++i;
        }
        if (i >= s.size()) {
            throw std::runtime_error("decode: missing character");
        }
        out.append(static_cast<std::size_t>(count), s[i]);
        ++i;
    }
    return out;
}

int main() {
    std::string input = "aaabbbccccd";
    std::string encoded = encode(input);
    std::cout << "encoded: " << encoded << '\n';
    std::cout << "roundtrip ok: " << (decode(encoded) == input) << '\n';
    try {
        decode("3");
    } catch (const std::exception& e) {
        std::cout << "error: " << e.what() << '\n';
    }
    return 0;
}
