import time
import random

def retry(fn, attempts=5, base=0.1, factor=2.0, jitter=0.05):
    if attempts < 1:
        raise ValueError("attempts must be >= 1")
    for i in range(attempts):
        try:
            return fn()
        except Exception:
            if i == attempts - 1:
                raise
            delay = base * (factor ** i) + random.uniform(0, jitter)
            time.sleep(delay)

if __name__ == "__main__":
    calls = {"n": 0}

    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise RuntimeError("boom")
        return "ok"

    print(retry(flaky))
