def rle_encode(s):
    if not s:
        return ""
    out = []
    prev, count = s[0], 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(f"{prev}{count}")
            prev, count = ch, 1
    out.append(f"{prev}{count}")
    return "".join(out)


def rle_decode(s):
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        if start == i:
            raise ValueError(f"missing count after {ch!r}")
        out.append(ch * int(s[start:i]))
    return "".join(out)


if __name__ == "__main__":
    for s in ["", "aaabbc", "abc", "日本語"]:
        enc = rle_encode(s)
        assert rle_decode(enc) == s
        print(repr(s), "->", enc)
