def flatten(items):
    """Flatten arbitrarily nested lists/tuples into a flat list."""
    result = []
    stack = list(reversed(items))
    while stack:
        item = stack.pop()
        if isinstance(item, (list, tuple)):
            stack.extend(reversed(item))
        else:
            result.append(item)
    return result


