```rust
fn partition<T: Ord>(v: &mut [T]) -> usize {
    let len = v.len();
    v.swap(len / 2, len - 1);
    let mut store = 0;
    for i in 0..len - 1 {
        if v[i] <= v[len - 1] {
            v.swap(i, store);
            store += 1;
        }
    }
    v.swap(store, len - 1);
    store
}

fn quicksort<T: Ord>(v: &mut [T]) {
    if v.len() <= 1 {
        return;
    }
    let pivot = partition(v);
    let (left, right) = v.split_at_mut(pivot);
    quicksort(left);
    quicksort(&mut right[1..]);
}

fn main() {
    let mut data = vec![5, 3, 8, 1, 9, 2, 7, 2, 0, -4];
    quicksort(&mut data);
    println!("{:?}", data);
    assert_eq!(data, vec![-4, 0, 1, 2, 2, 3, 5, 7, 8, 9]);
}
