def rle(text):
    if not text:
        return ""
    parts = []
    prev = text[0]
    count = 1
    for char in text[1:]:
        if char == prev:
            count += 1
        else:
            parts.append(f"{prev}{count}")
            prev = char
            count = 1
    parts.append(f"{prev}{count}")
    return "".join(parts)


