#include <iostream>
#include <stack>
#include <string>

bool balanced(const std::string& text) {
    std::stack<char> open;
    for (char c : text) {
        if (c == '(' || c == '[' || c == '{') {
            open.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (open.empty()) return false;
            char top = open.top();
            if ((c == ')' && top != '(') ||
                (c == ']' && top != '[') ||
                (c == '}' && top != '{')) {
                return false;
            }
            open.pop();
        }
    }
    return open.empty();
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::cout << (balanced(line) ? "balanced\n" : "not balanced\n");
    return 0;
}
```

A stack tracks unmatched open brackets; a closing bracket that doesn't match the top, or appears with an empty stack, fails immediately. Anything left on the stack at the end means an unclosed bracket.

```cpp
#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& data, int target) {
    int low = 0;
    int high = static_cast<int>(data.size()) - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (data[mid] == target) return mid;
        if (data[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> data{1, 3, 5, 7, 9};
    std::cout << binary_search(data, 7) << "\n";   // 3
    std::cout << binary_search(data, 4) << "\n";   // -1
    std::cout << binary_search({}, 1) << "\n";      // -1
    return 0;
}
```

`low + (high - low) / 2` avoids the overflow `(low + high) / 2` can hit on large inputs, and the empty-vector case works because `high` becomes -1.

