```rust
fn longest_common_prefix(words: &[String]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = words[0].as_bytes();
    let mut len = first.len();
    for word in &words[1..] {
        let bytes = word.as_bytes();
        len = len.min(bytes.len());
        let mut i = 0;
        while i < len && first[i] == bytes[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            break;
        }
    }
    String::from_utf8_lossy(&first[..len]).into_owned()
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    println!("{}", longest_common_prefix(&args));
}
```

