using Matrix = std::vector<std::vector<double>>;

bool multiply(const Matrix& a, const Matrix& b, Matrix& out) {
    if (a.empty() || b.empty() || a[0].size() != b.size()) return false;
    const size_t n = a.size();
    const size_t m = b[0].size();
    const size_t k = b.size();
    out.assign(n, std::vector<double>(m, 0.0));
    for (size_t i = 0; i < n; ++i) {
        for (size_t t = 0; t < k; ++t) {
            const double v = a[i][t];
            for (size_t j = 0; j < m; ++j) {
                out[i][j] += v * b[t][j];
            }
        }
    }
    return true;
}

int main() {
    Matrix a{{1, 2}, {3, 4}};
    Matrix b{{5, 6}, {7, 8}};
    Matrix out;
    if (!multiply(a, b, out)) {
        std::cerr << "bad dimensions\n";
        return 1;
    }
    for (const auto& row : out) {
        for (double v : row) std::cout << v << ' ';
        std::cout << '\n';
    }
    return 0;
}
