void merge_sort(std::vector<int>& a, std::vector<int>& buf, int lo, int hi) {
    if (hi - lo <= 1) return;
    int mid = lo + (hi - lo) / 2;
    merge_sort(a, buf, lo, mid);
    merge_sort(a, buf, mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) buf[k++] = (a[j] < a[i]) ? a[j++] : a[i++];
    while (i < mid) buf[k++] = a[i++];
    while (j < hi) buf[k++] = a[j++];
    std::copy(buf.begin() + lo, buf.begin() + hi, a.begin() + lo);
}

int main() {
    std::vector<int> data = {5, 2, 9, 1, 5, 6, -3, 0, 9};
    std::vector<int> buf(data.size());
    merge_sort(data, buf, 0, static_cast<int>(data.size()));
    for (int v : data) std::cout << v << ' ';
    std::cout << "\n";
