```python
class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._buf = [None] * capacity
        self._head = 0
        self._size = 0

    def push(self, item):
        index = (self._head + self._size) % len(self._buf)
        self._buf[index] = item
        if self._size < len(self._buf):
            self._size += 1
        else:
            self._head = (self._head + 1) % len(self._buf)

    def pop(self):
        if self._size == 0:
            raise IndexError("buffer is empty")
        item = self._buf[self._head]
        self._buf[self._head] = None
        self._head = (self._head + 1) % len(self._buf)
        self._size -= 1
        return item

    def __len__(self):
        return self._size

if __name__ == "__main__":
    rb = RingBuffer(3)
    for v in (1, 2, 3, 4):
        rb.push(v)
    assert [rb.pop(), rb.pop(), rb.pop()] == [2, 3, 4]
    try:
        rb.pop()
    except IndexError:
        print("empty handled")
