fn longest_common_prefix(words: &[&str]) -> String {
    let first = match words.first() {
        Some(w) => *w,
        None => return String::new(),
    };
    let mut end = first.len();
    for word in &words[1..] {
        let limit = end.min(word.len());
        let bytes = first.as_bytes();
        let other = word.as_bytes();
        let mut i = 0;
        while i < limit && bytes[i] == other[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    first[..end].to_string()
}

fn main() {
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&["dog", "cat"]), "");
    assert_eq!(longest_common_prefix(&[]), "");
    println!("ok");
}
