#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& a, int target) {
    int lo = 0, hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    int target;
    if (!(std::cin >> target)) {
        std::cerr << "usage: target then sorted integers\n";
        return 1;
    }
    std::vector<int> a;
    int x;
    while (std::cin >> x) a.push_back(x);
    int idx = binary_search(a, target);
    if (idx < 0) std::cout << "not found\n";
    else std::cout << "found at " << idx << "\n";
    return 0;
}
