def prime_factors(n):
    if n == 0:
        raise ValueError("zero has no prime factorization")
    n = abs(n)
    factors = []
    divisor = 2
    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1 if divisor == 2 else 2
    if n > 1:
        factors.append(n)
    return factors

