int lower_bound(const std::vector<int>& a, int target) {
    int lo = 0;
    int hi = static_cast<int>(a.size());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

int main() {
    std::vector<int> a = {1, 3, 3, 5, 8};
    for (int t : {0, 3, 4, 8, 9}) {
        std::cout << t << " -> " << lower_bound(a, t) << std::endl;
    }
    return 0;
}
