Bracket-balance checker that validates matching pairs, not just counts:

```cpp
#include <iostream>
#include <string>

bool balanced(const std::string& s) {
    std::string stack;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            stack.push_back(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (stack.empty()) return false;
            char open = stack.back();
            stack.pop_back();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) return false;
        }
    }
    return stack.empty();
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::cout << (balanced(line) ? "balanced" : "unbalanced") << '\n';
    }
    return 0;
}
```

`([)]` returns unbalanced because the closing paren doesn't match the top of the stack.

