#include <cstddef>
#include <iostream>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t cap)
        : data_(new int[cap]), cap_(cap), head_(0), size_(0) {}

    ~RingBuffer() { delete[] data_; }
    RingBuffer(const RingBuffer&) = delete;
    RingBuffer& operator=(const RingBuffer&) = delete;

    void push(int v) {
        if (size_ < cap_) {
            data_[(head_ + size_) % cap_] = v;
            ++size_;
        } else {
            data_[head_] = v;
            head_ = (head_ + 1) % cap_;
        }
    }

    std::size_t size() const { return size_; }

    int at(std::size_t i) const { return data_[(head_ + i) % cap_]; }

private:
    int* data_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    rb.push(1); rb.push(2); rb.push(3); rb.push(4);
    for (std::size_t i = 0; i < rb.size(); ++i) std::cout << rb.at(i) << ' ';
