```cpp
#include <iostream>
#include <sstream>
#include <stack>
#include <string>

bool eval_rpn(const std::string& expr, long long& out, std::string& err) {
    std::istringstream in(expr);
    std::stack<long long> st;
    std::string tok;
    while (in >> tok) {
        if (tok == "+" || tok == "-" || tok == "*" || tok == "/") {
            if (st.size() < 2) { err = "too few operands"; return false; }
            long long b = st.top(); st.pop();
            long long a = st.top(); st.pop();
            if (tok == "/" && b == 0) { err = "division by zero"; return false; }
            if (tok == "+") st.push(a + b);
            else if (tok == "-") st.push(a - b);
            else if (tok == "*") st.push(a * b);
            else st.push(a / b);
        } else {
            try { st.push(std::stoll(tok)); }
            catch (...) { err = "bad token: " + tok; return false; }
        }
    }
    if (st.size() != 1) { err = "leftover operands"; return false; }
    out = st.top();
    return true;
}

int main() {
    std::string err;
    long long v = 0;
    if (eval_rpn("3 4 + 2 *", v, err)) std::cout << v << '\n';   // 14
    if (!eval_rpn("1 0 /", v, err)) std::cout << err << '\n';     // division by zero
    if (!eval_rpn("1 +", v, err)) std::cout << err << '\n';       // too few operands
}
```
