```rust
use std::collections::{HashMap, VecDeque};

struct LruCache {
    cap: usize,
    map: HashMap<i32, i32>,
    order: VecDeque<i32>, // front = most recently used
}

impl LruCache {
    fn new(cap: usize) -> Self {
        LruCache { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    fn touch(&mut self, key: i32) {
        if let Some(pos) = self.order.iter().position(|&k| k == key) {
            self.order.remove(pos);
        }
        self.order.push_front(key);
    }

    fn get(&mut self, key: i32) -> Option<i32> {
        let v = *self.map.get(&key)?;
        self.touch(key);
        Some(v)
    }

    fn put(&mut self, key: i32, value: i32) {
        if self.cap == 0 { return; }
        self.map.insert(key, value);
        self.touch(key);
        while self.order.len() > self.cap {
            if let Some(evicted) = self.order.pop_back() {
                self.map.remove(&evicted);
            }
        }
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 1);
    c.put(2, 2);
    assert_eq!(c.get(1), Some(1)); // 2 becomes least recently used
    c.put(3, 3);                   // evicts key 2
    assert_eq!(c.get(2), None);
    assert_eq!(c.get(3), Some(3));
    let mut z = LruCache::new(0);
    z.put(1, 1);
    assert_eq!(z.get(1), None);
    println!("ok");
}
```
The recency deque is kept in sync by `touch`, and the eviction loop runs after every insert so capacity zero is safe.

