```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) {
        perror("malloc");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

void print(Node *head) {
    for (; head; head = head->next) printf("%d ", head->value);
    putchar('\n');
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; ++i) head = push(head, i);
    head = reverse(head);
    print(head);          /* 1 2 3 4 5 */
    free_list(head);
    free_list(NULL);      /* empty list is safe */
    return 0;
}
```
The three-pointer walk runs in O(n) time and O(1) extra space, and `free_list` handles a NULL head so no branch is needed at the call site.

```python
import heapq


class RunningMedian:
    """Maintain the median of a stream with two heaps: a max-heap for the
    lower half and a min-heap for the upper half."""

    def __init__(self):
        self.low = []   # max-heap (store negatives)
        self.high = []  # min-heap

    def add(self, value: int) -> None:
        if not self.low or value <= -self.low[0]:
            heapq.heappush(self.low, -value)
        else:
            heapq.heappush(self.high, value)

        if len(self.low) > len(self.high) + 1:
            heapq.heappush(self.high, -heapq.heappop(self.low))
        elif len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def median(self) -> float:
        if len(self.low) == len(self.high):
            return (-self.low[0] + self.high[0]) / 2.0
        return float(-self.low[0])


def main() -> None:
    stream = RunningMedian()
    for x in [5, 15, 1, 3, 8, 7, 9, 10, 6, 11]:
        stream.add(x)
        print(f"after {x:>3}: median = {stream.median():.1f}")


if __name__ == "__main__":
    main()
```

`add` keeps the heaps balanced within one element, so `median` is O(1) and each insertion is O(log n). For an even count it averages the two middle values.

```cpp
#include <cstddef>
#include <list>
#include <stdexcept>
#include <unordered_map>
#include <utility>

template <typename Key, typename Value>
class LruCache {
public:
    explicit LruCache(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be positive");
        }
    }

    bool get(const Key& key, Value& out) {
        auto it = index_.find(key);
        if (it == index_.end()) {
            return false;
        }
        order_.splice(order_.begin(), order_, it->second);
        out = it->second->second;
        return true;
    }

    void put(const Key& key, const Value& value) {
        auto it = index_.find(key);
        if (it != index_.end()) {
            it->second->second = value;
            order_.splice(order_.begin(), order_, it->second);
            return;
        }
        if (order_.size() == capacity_) {
            index_.erase(order_.back().first);
            order_.pop_back();
        }
        order_.emplace_front(key, value);
        index_[key] = order_.begin();
    }

    std::size_t size() const { return order_.size(); }

private:
    std::size_t capacity_;
    std::list<std::pair<Key, Value>> order_;  // most-recent at front
    std::unordered_map<Key, typename std::list<std::pair<Key, Value>>::iterator> index_;
};
```

The list holds entries in recency order and the map points into it, so both operations are O(1) on average. `splice` moves a node without copying, which is why `get` can promote an entry in constant time.

```rust
fn merge_sorted<T: Ord + Copy>(left: &[T], right: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(left.len() + right.len());
    let (mut i, mut j) = (0, 0);

    while i < left.len() && j < right.len() {
        if left[i] <= right[j] {
            out.push(left[i]);
            i += 1;
        } else {
            out.push(right[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&left[i..]);
    out.extend_from_slice(&right[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 4, 6, 8, 9];
    let merged = merge_sorted(&a, &b);
    assert_eq!(merged, vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);

    let empty: [i32; 0] = [];
    assert_eq!(merge_sorted(&empty, &b), b.to_vec());
    println!("merged: {merged:?}");
}
```

`with_capacity` reserves the exact final size once, and the two tails are appended with `extend_from_slice`, so there is no reallocation during the merge. `Ord + Copy` keeps the comparison simple; for owned elements you could switch to consuming iterators.

