class FileReader {
public:
    explicit FileReader(const std::string& path) {
        std::ifstream in(path, std::ios::binary);
        if (!in) {
            throw std::runtime_error("cannot open file: " + path);
        }
        in.seekg(0, std::ios::end);
        const auto size = in.tellg();
        if (size < 0) {
            throw std::runtime_error("cannot determine size of: " + path);
        }
        contents_.resize(static_cast<std::size_t>(size));
        in.seekg(0, std::ios::beg);
        if (size > 0) {
            in.read(contents_.data(), size);
        }
        if (in.bad()) {
            throw std::runtime_error("read failed: " + path);
        }
    }

    const std::string& contents() const noexcept { return contents_; }

private:
    std::string contents_;
};

// Usage:
// try { FileReader f("data.bin"); use(f.contents()); }
// catch (const std::runtime_error& e) { report(e.what()); }
