`Arc` gives shared ownership across threads and `Mutex` serializes the writes, so the final value is exactly 8000. If a worker panicked while holding the lock, `unwrap` would surface a poisoned-mutex error instead of silently returning a wrong count. One `lock().unwrap()` per increment is safe here; for very high contention, batching increments into a local variable before locking is faster.

```cpp
#include <cassert>
#include <cstdint>
#include <iostream>
#include <utility>

using u64 = std::uint64_t;
constexpr u64 MOD = 1'000'000'007ULL;

// Returns {F(n), F(n+1)} modulo MOD.
std::pair<u64, u64> fib_pair(u64 n) {
    if (n == 0) {
        return {0, 1};
    }
    auto [a, b] = fib_pair(n >> 1);
    u64 c = a * ((2 * b + MOD - a) % MOD) % MOD;
    u64 d = (a * a + b * b) % MOD;
    if (n & 1ULL) {
        return {d, (c + d) % MOD};
    }
    return {c, d};
}

u64 fib_mod(u64 n) { return fib_pair(n).first; }

u64 fib_iter(u64 n) {
    u64 a = 0, b = 1;
    for (u64 i = 0; i < n; ++i) {
        u64 next = (a + b) % MOD;
        a = b;
        b = next;
    }
    return a;
}

int main() {
    for (u64 n = 0; n < 200; ++n) {
        assert(fib_mod(n) == fib_iter(n));
    }
    std::cout << fib_mod(90) << '\n';  // 2880067194370816120 mod p
}
```

