/* Copy src into dst (size bytes). Always NUL-terminates.
 * Returns the number of bytes copied (excluding the NUL), or -1 on error. */
int safe_copy(char *dst, size_t size, const char *src) {
    if (dst == NULL || src == NULL || size == 0) {
        return -1;
    }
    size_t i = 0;
    while (i + 1 < size && src[i] != '\0') {
        dst[i] = src[i];
        i++;
    }
    dst[i] = '\0';
    return (int)i;
}

int main(void) {
    char buf[8];
    safe_copy(buf, sizeof buf, "hello");
    printf("%s\n", buf);
    safe_copy(buf, sizeof buf, "this string is far too long");
    printf("%s\n", buf);
    return 0;
}
