def fib(n):
    """Return the n-th Fibonacci number, F(0)=0, F(1)=1. O(n) time, O(1) space."""
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n

    prev, curr = 0, 1
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr
    return curr


