import sys
from collections import Counter


def top_words(path, n=10):
    """Read a UTF-8 file and return the n most common words.

    Words are case-folded and stripped of surrounding punctuation.
    Unicode letters and digits are preserved.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        print(f"No such file: {path}", file=sys.stderr)
        return []
    except UnicodeDecodeError as exc:
        print(f"File is not valid UTF-8: {exc}", file=sys.stderr)
        return []

    counts = Counter()
    for raw in text.split():
        word = raw.strip(".,;:!?()[]{}'\"\u201c\u201d").casefold()
        if word:
            counts[word] += 1
    return counts.most_common(n)


if __name__ == "__main__":
    path = sys.argv[1] if len(sys.argv) > 1 else "input.txt"
    for word, freq in top_words(path):
        print(f"{freq:6d}  {word}")
