#include <cstdio>
#include <memory>
#include <string>
#include <utility>

class LineReader {
public:
    explicit LineReader(const std::string& path, std::size_t buf_size = 4096)
        : file_(std::fopen(path.c_str(), "rb")), buffer_(buf_size) {
        if (!file_) {
            throw std::runtime_error("cannot open " + path);
        }
    }

    ~LineReader() {
        if (file_) {
            std::fclose(file_);
        }
    }

    LineReader(const LineReader&) = delete;
    LineReader& operator=(const LineReader&) = delete;

    LineReader(LineReader&& other) noexcept
        : file_(std::exchange(other.file_, nullptr)),
          buffer_(std::move(other.buffer_)) {}

    // Returns false at end of file. Strips a trailing '\n' or '\r\n'.
    bool next(std::string& out) {
        out.clear();
        if (!file_) {
            return false;
        }
        while (std::fgets(buffer_.data(), static_cast<int>(buffer_.size()), file_)) {
            out += buffer_.data();
            if (!out.empty() && out.back() == '\n') {
                out.pop_back();
                if (!out.empty() && out.back() == '\r') {
                    out.pop_back();
                }
                return true;
            }
            // Line longer than the buffer: keep reading.
            if (std::feof(file_)) {
                break;
            }
        }
        return !out.empty();
    }

    bool good() const { return file_ != nullptr; }

private:
    std::FILE* file_;
    std::vector<char> buffer_;
};
```

The destructor guarantees the `FILE*` is closed on every exit path, including exceptions. Move construction transfers ownership with `std::exchange` so only the last live object closes the handle; copy operations are deleted. The `next` loop reassembles lines that exceed the internal buffer.

```rust
/// Returns true if `s` is a valid dotted-decimal IPv4 address.
fn is_valid_ipv4(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return false;
    }
    parts.iter().all(|part| is_octet(part))
}

fn is_octet(part: &str) -> bool {
    if part.is_empty() || part.len() > 3 {
        return false;
    }
    if !part.bytes().all(|b| b.is_ascii_digit()) {
        return false;
    }
    // No leading zeros unless the value is exactly "0".
    if part.len() > 1 && part.starts_with('0') {
        return false;
    }
    part.parse::<u16>().map_or(false, |n| n <= 255)
}

fn main() {
    let cases = [
        ("192.168.0.1", true),
        ("0.0.0.0", true),
        ("255.255.255.255", true),
        ("256.1.1.1", false),
        ("1.2.3", false),
        ("1.2.3.4.5", false),
        ("01.2.3.4", false),
        ("1.2.3.4 ", false),
        ("", false),
        ("a.b.c.d", false),
    ];
    for (input, expected) in &cases {
        assert_eq!(is_valid_ipv4(input), *expected, "failed on {input:?}");
    }
    println!("all {} cases passed", cases.len());
}
```

Each octet must be 1-3 ASCII digits, reject leading zeros (which older parsers treated as octal), and parse to a value at most 255. Rejecting 5-part and trailing-space inputs keeps the check strict. No crate dependency is needed.

```rust
use std::collections::HashMap;

struct Node {
    key: i32,
    value: i32,
    prev: usize,
    next: usize,
}

pub struct LruCache {
    cap: usize,
    map: HashMap<i32, usize>,
    nodes: Vec<Node>,
    head: usize, // most recently used sentinel
    tail: usize, // least recently used sentinel
}

impl LruCache {
    pub fn new(capacity: usize) -> Self {
        let mut c = LruCache {
            cap: capacity.max(1),
            map: HashMap::new(),
            nodes: Vec::new(),
            head: 0,
            tail: 1,
        };
        // Two sentinel nodes; indices 0 and 1 are always present.
        c.nodes.push(Node { key: 0, value: 0, prev: 0, next: 1 });
        c.nodes.push(Node { key: 0, value: 0, prev: 0, next: 1 });
        c
    }

    pub fn get(&mut self, key: i32) -> Option<i32> {
        let idx = *self.map.get(&key)?;
        self.unlink(idx);
        self.push_front(idx);
        Some(self.nodes[idx].value)
    }

    pub fn put(&mut self, key: i32, value: i32) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].value = value;
            self.unlink(idx);
            self.push_front(idx);
            return;
        }
        if self.map.len() == self.cap {
            let lru = self.nodes[self.tail].prev;
            self.unlink(lru);
            self.map.remove(&self.nodes[lru].key);
        }
        let idx = self.nodes.len();
        self.nodes.push(Node { key, value, prev: 0, next: 0 });
        self.map.insert(key, idx);
        self.push_front(idx);
    }

    fn unlink(&mut self, idx: usize) {
        let (p, n) = (self.nodes[idx].prev, self.nodes[idx].next);
        self.nodes[p].next = n;
        self.nodes[n].prev = p;
    }

    fn push_front(&mut self, idx: usize) {
        let first = self.nodes[self.head].next;
        self.nodes[idx].prev = self.head;
        self.nodes[idx].next = first;
        self.nodes[first].prev = idx;
        self.nodes[self.head].next = idx;
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 1);
    c.put(2, 2);
    assert_eq!(c.get(1), Some(1));
    c.put(3, 3); // evicts key 2
    assert_eq!(c.get(2), None);
    c.put(4, 4); // evicts key 1
    assert_eq!(c.get(1), None);
    assert_eq!(c.get(3), Some(3));
    assert_eq!(c.get(4), Some(4));
    println!("ok");
}
```

Nodes live in an arena `Vec` and are linked by index, which sidesteps the borrow-checker pain of `Rc<RefCell<..>>` while keeping both operations O(1). Two sentinel nodes remove the need for null checks at the list ends.

```python
import ast
import operator

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}


def calc(expression: str):
    """Evaluate an arithmetic expression safely.

    Supports + - * / // % ** and unary +/-, plus parentheses.
    Raises ValueError on unsupported syntax or unsafe values.
    """
    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError as exc:
        raise ValueError(f"bad syntax: {exc.msg}") from exc
    return _eval(tree.body)


def _eval(node):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise ValueError("only numbers are allowed")
        return node.value
    if isinstance(node, ast.BinOp):
        op = _BIN_OPS.get(type(node.op))
        if op is None:
            raise ValueError(f"unsupported operator: {type(node.op).__name__}")
        left, right = _eval(node.left), _eval(node.right)
        if isinstance(node.op, ast.Pow) and abs(right) > 100:
            raise ValueError("exponent too large")
        return op(left, right)
    if isinstance(node, ast.UnaryOp):
        op = _UNARY_OPS.get(type(node.op))
        if op is None:
            raise ValueError("unsupported unary operator")
        return op(_eval(node.operand))
    raise ValueError(f"unsupported expression: {type(node).__name__}")


if __name__ == "__main__":
    assert calc("2 + 3 * 4") == 14
    assert calc("(2 + 3) * 4") == 20
    assert calc("-5 + 2 ** 3") == 3
    assert calc("7 // 2") == 3
    for bad in ("__import__('os')", "1 +", "2 ** 999", "a + 1"):
        try:
            calc(bad)
            raise AssertionError(f"should have rejected {bad!r}")
        except ValueError:
            pass
    print("ok")
```

`ast.parse(..., mode="eval")` yields only expressions, so statements and imports are impossible. `_eval` walks a strict allowlist of node types, so names, calls, and subscripts are rejected before execution. The exponent cap prevents a cheap denial-of-service via `2 ** 99999999`.

```rust
/// Merges two ascending slices into one ascending Vec.
///
/// When elements are equal, the one from `a` is placed first, which
/// matches the usual stable-merge convention.
pub fn merge<T: Ord>(a: &[T], b: &[T]) -> Vec<T>
where
    T: Clone,
{
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }

    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 3, 6];
    assert_eq!(merge(&a, &b), vec![1, 2, 3, 3, 5, 6, 7]);

    let empty: [i32; 0] = [];
    assert_eq!(merge(&empty, &b), vec![2, 3, 6]);
    assert_eq!(merge(&a, &empty), vec![1, 3, 5, 7]);
    assert!(merge(&empty, &empty).is_empty());

    let sa = ["a", "c"];
    let sb = ["b", "c"];
    assert_eq!(merge(&sa, &sb), vec!["a", "b", "c", "c"]);

    println!("ok");
}
```

The `<=` comparison is what makes the merge stable: ties take from `a`, preserving the original order across the two inputs. After the loop, at most one input has leftovers, and `extend_from_slice` appends them without further comparisons. Pre-allocating with the summed length avoids reallocations.

