            match (a.next(), b.next()) {
                (Some(x), Some(y)) if x == y => i += 1,
                _ => break,
            }
        }
        if i < end {
            end = i;
        }
    }
    first[..end].to_string()
}

fn main() {
    let cases: [&[&str]; 4] = [
        &[],
        &["alone"],
        &["flower", "flow", "flight"],
        &["caf\u{e9}", "caf\u{e9}s"],
    ];
    let expected = ["", "alone", "fl", "caf\u{e9}"];
    for (case, want) in cases.iter().zip(expected) {
        let owned: Vec<String> = case.iter().map(|s| s.to_string()).collect();
        let got = longest_common_prefix(&owned);
        assert_eq!(got, want, "case {case:?}");
    }
    println!("ok");
}
```
The prefix length is capped to the first string and shrank against each later word; comparing at the byte level still yields a valid slice boundary because a shared prefix of UTF-8 text can only end where both strings encode the same byte.

