from typing import List, Optional

def two_sum(nums: List[int], target: int) -> Optional[tuple]:
    """Return indices (i, j) with nums[i] + nums[j] == target, or None."""
    seen = {}  # value -> index
    for i, n in enumerate(nums):
        need = target - n
        if need in seen:
            return (seen[need], i)
        seen[n] = i
    return None

