import re

_OCTET = re.compile(r"^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$")

def is_valid_ipv4(address: str) -> bool:
    """True if address is a dotted-quad IPv4 with no leading zeros."""
    if not isinstance(address, str):
        return False
    parts = address.split(".")
    if len(parts) != 4:
        return False
    return all(_OCTET.match(p) is not None for p in parts)

if __name__ == "__main__":
    good = ["192.168.0.1", "0.0.0.0", "255.255.255.255", "8.8.8.8"]
    bad = ["256.1.1.1", "192.168.1", "01.2.3.4", "1.2.3.4.5", "", "1.2.3.a"]
    for ip in good:
        assert is_valid_ipv4(ip), ip
    for ip in bad:
        assert not is_valid_ipv4(ip), ip
    print("all checks passed")
