```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <thread>
#include <cassert>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {
        assert(capacity > 0);
    }

    void push(int value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return q_.size() < cap_ || closed_; });
        if (closed_) return;
        q_.push(value);
        lock.unlock();
        not_empty_.notify_one();
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;  // closed and drained
        int value = q_.front();
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::queue<int> q_;
    std::size_t cap_;
    bool closed_ = false;
    std::mutex mu_;
    std::condition_variable not_empty_, not_full_;
};

int main() {
    BoundedQueue q(4);
    std::thread producer([&q] { for (int i = 0; i < 20; ++i) q.push(i); q.close(); });
    long sum = 0;
    while (auto v = q.pop()) sum += *v;
    producer.join();
    assert(sum == 190);  // 0..19
    return 0;
}
```

Each `wait` uses a predicate so spurious wakeups are handled. `close()` wakes every waiter, and `pop()` returns `std::nullopt` once the queue is drained, which terminates the consumer loop safely.

```cpp
#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

std::size_t lcs_length(const std::string& a, const std::string& b) {
    // dp[j] = LCS length of a[0..i) and b[0..j)
    std::vector<std::size_t> dp(b.size() + 1, 0);
    for (char ca : a) {
        std::size_t prev_diag = 0;  // dp[i-1][j-1] before overwrite
        for (std::size_t j = 1; j <= b.size(); ++j) {
            std::size_t old = dp[j];
            if (ca == b[j - 1]) {
                dp[j] = prev_diag + 1;
            } else {
                dp[j] = std::max(dp[j], dp[j - 1]);
            }
            prev_diag = old;
        }
    }
    return dp[b.size()];
}

int main() {
    std::string a, b;
    while (std::getline(std::cin, a) && std::getline(std::cin, b)) {
        std::cout << lcs_length(a, b) << "\n";
    }
    return 0;
}
```

Rolling one-dimensional DP drops memory from O(nm) to O(min(n,m)). `prev_diag` holds the old `dp[j-1]` value so the diagonal term stays correct after the in-place overwrite. Reading line by line lets the binary handle multiple test pairs; EOF ends the loop cleanly.

```rust
fn merge_sorted<T: Ord + Copy>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn merges_basic() {
        assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    }

    #[test]
    fn handles_empty() {
        assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
        assert_eq!(merge_sorted(&[1, 2], &[]), vec![1, 2]);
        assert_eq!(merge_sorted(&[], &[7]), vec![7]);
    }

    #[test]
    fn keeps_duplicates() {
        assert_eq!(merge_sorted(&[1, 1, 2], &[1, 3]), vec![1, 1, 1, 2, 3]);
    }
}

fn main() {
    println!("{:?}", merge_sorted(&[1, 4, 9], &[2, 3, 10]));
}
```

`<=` on the `a` side keeps the merge stable when values tie. The two `extend_from_slice` calls append whatever remains without a second loop, and `with_capacity` avoids reallocation. Run `cargo test` to execute all three cases.

