```cpp
#include <iostream>
#include <vector>

int first_index(const std::vector<int>& arr, int target) {
    int lo = 0;
    int hi = static_cast<int>(arr.size()) - 1;
    int found = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) {
            found = mid;
            hi = mid - 1;          // keep searching left for the first match
        } else if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return found;
}

int main() {
    std::vector<int> data{1, 3, 3, 3, 7, 9};
    std::cout << first_index(data, 3) << "\n";   // 1
    std::cout << first_index(data, 1) << "\n";   // 0
    std::cout << first_index(data, 8) << "\n";   // -1
    std::cout << first_index({}, 5) << "\n";     // -1
}
```

`lo + (hi - lo) / 2` avoids overflow on large arrays. On a match the search continues left rather than stopping, so duplicates yield the first index, and an empty vector leaves `found` at -1.

