def validate(data, schema, path="$"):
    """Yield dotted paths of missing or mistyped fields."""
    errors = []
    if not isinstance(data, dict):
        return [f"{path}: expected object, got {type(data).__name__}"]
    for key, expected in schema.items():
        here = f"{path}.{key}"
        if key not in data:
            errors.append(f"{here}: missing")
        elif isinstance(expected, dict):
            errors.extend(validate(data[key], expected, here))
        elif not isinstance(data[key], expected):
            errors.append(f"{here}: expected {expected.__name__}, got {type(data[key]).__name__}")
    return errors

if __name__ == "__main__":
