fn bsearch<T: Ord>(haystack: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = haystack.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match haystack[mid].cmp(target) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

fn main() {
    let data = [1, 3, 5, 7, 9, 11];
    assert_eq!(bsearch(&data, &7), Some(3));
    assert_eq!(bsearch(&data, &1), Some(0));
    assert_eq!(bsearch(&data, &11), Some(5));
    assert_eq!(bsearch(&data, &4), None);
    assert_eq!(bsearch::<i32>(&[], &1), None);
    println!("ok");
}
```
Uses the half-open range `[lo, hi)` so it never overflows and terminates on empty slices. `mid` is computed as `lo + (hi - lo) / 2` to avoid overflow. All assertions pass.

