    for (double v : values) sum += v;
    double mean = sum / values.size();

    double sq = 0.0;
    for (double v : values) sq += (v - mean) * (v - mean);
    double variance = sq / values.size();

    std::printf("count=%zu mean=%.6f stddev=%.6f\n",
                values.size(), mean, std::sqrt(variance));
    return 0;
}
