#include <stddef.h>

size_t remove_char(char *s, char target) {
    if (s == NULL) {
        return 0;
    }
    size_t write = 0;
    for (size_t read = 0; s[read] != '\0'; ++read) {
        if (s[read] != target) {
            s[write++] = s[read];
        }
    }
    s[write] = '\0';
    return write;
}

