#include <cstdio>
#include <stdexcept>
#include <vector>

namespace xt {

template <typename T>
const T& max_element(const std::vector<T>& v) {
    if (v.empty()) {
        throw std::invalid_argument("max_element: empty vector");
    }
    typename std::vector<T>::size_type best = 0;
    for (typename std::vector<T>::size_type i = 1; i < v.size(); ++i) {
        if (v[best] < v[i]) {
            best = i;
        }
    }
    return v[best];
}

} // namespace xt

int main() {
    std::vector<int> nums{3, 17, 9, 17, 2};
    std::printf("max=%d\n", xt::max_element(nums));

    try {
        std::vector<int> empty;
        xt::max_element(empty);
    } catch (const std::invalid_argument& e) {
        std::printf("caught: %s\n", e.what());
    }
    return 0;
}
