```cpp
#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* merge_sorted(Node* a, Node* b) {
    Node dummy(0);
    Node* tail = &dummy;
    while (a && b) {
        if (a->value <= b->value) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

void print(Node* head) {
    for (; head; head = head->next) std::cout << head->value << ' ';
    std::cout << '\n';
}

int main() {
    Node* a = new Node(1);
    a->next = new Node(3);
    a->next->next = new Node(5);
    Node* b = new Node(2);
    b->next = new Node(4);
    b->next->next = new Node(6);
    print(merge_sorted(a, b));
    print(merge_sorted(nullptr, nullptr));
    print(merge_sorted(new Node(7), nullptr));
}
```

Nodes are linked rather than copied, so it works on empty lists and single-element lists. The `dummy` node avoids a null check for the first merge step.

```rust
use std::collections::HashMap;

/// Case-insensitive word frequency, returning the top `n` pairs sorted by
/// count descending, then alphabetically to make ties deterministic.
fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The quick brown fox the lazy dog THE";
    let top = top_words(text, 2);
    assert_eq!(top, vec![("the".to_string(), 3), ("brown".to_string(), 1)]);
    assert!(top_words("", 5).is_empty());
    println!("{:?}", top);
}
```

`split_whitespace` ignores runs of spaces and tabs, punctuation is stripped by the filter, and lowercasing happens per character so non-ASCII casing is handled. The deterministic tie-break avoids nondeterministic `HashMap` ordering.

