#include <iostream>
#include <stack>
#include <string>

bool is_balanced(const std::string& s) {
    std::stack<char> open;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                open.push(c);
                break;
            case ')': case ']': case '}': {
                char want = (c == ')') ? '(' : (c == ']') ? '[' : '{';
                if (open.empty() || open.top() != want) return false;
                open.pop();
                break;
            }
            default:
                break;
        }
    }
    return open.empty();
}

int main() {
    const std::string tests[] = {"([]){}", "([)]", "", "((", "a(b[c]{d})e"};
    for (const auto& t : tests) {
        std::cout << t << " -> " << (is_balanced(t) ? "balanced" : "unbalanced") << '\n';
    }
}
```

Non-bracket characters are ignored, so mixed text works. `([)]` is correctly rejected because the closing `)` does not match the top of the stack. The empty string returns true.

