class ScopeTimer {
public:
    explicit ScopeTimer(std::string label)
        : label_(std::move(label)), start_(std::chrono::steady_clock::now()) {}

    ~ScopeTimer() {
        const auto end = std::chrono::steady_clock::now();
        const auto us = std::chrono::duration_cast<std::chrono::microseconds>(end - start_).count();
        std::printf("%s: %lld us\n", label_.c_str(), static_cast<long long>(us));
    }

    ScopeTimer(const ScopeTimer&) = delete;
    ScopeTimer& operator=(const ScopeTimer&) = delete;

private:
    std::string label_;
    std::chrono::steady_clock::time_point start_;
};

int main() {
    ScopeTimer t("busy loop");
    volatile long long sum = 0;
    for (int i = 0; i < 1000000; ++i) sum += i;
}
```

`steady_clock` is monotonic, so wall-clock adjustments cannot produce a negative duration. Deleting the copy constructor prevents accidental double-printing, and the destructor prints even if the scope exits via an early return or exception. `volatile` stops the loop from being optimized away.

