#include <string>
#include <vector>
#include <stdexcept>

std::vector<std::string> parse_csv_line(const std::string& line) {
    std::vector<std::string> fields;
    std::string field;
    bool in_quotes = false;
    for (std::size_t i = 0; i < line.size(); ++i) {
        char c = line[i];
        if (in_quotes) {
            if (c == '"') {
                if (i + 1 < line.size() && line[i + 1] == '"') {
                    field.push_back('"');  // escaped quote
                    ++i;
                } else {
                    in_quotes = false;
                }
            } else {
                field.push_back(c);
            }
        } else if (c == ',') {
            fields.push_back(field);
            field.clear();
        } else if (c == '"') {
            in_quotes = true;
        } else {
            field.push_back(c);
        }
    }
    if (in_quotes) {
        throw std::runtime_error("unterminated quoted field");
    }
    fields.push_back(field);
    return fields;
}
```

Doubled quotes inside a quoted field collapse to a single quote, commas inside quotes are preserved, and an unclosed quote raises instead of silently truncating. It assumes the line has no trailing newline; strip it before calling.

```rust
fn second_largest(values: &[i64]) -> Option<i64> {
    let mut first: Option<i64> = None;
    let mut second: Option<i64> = None;
    for &v in values {
        match first {
            None => first = Some(v),
            Some(f) if v > f => {
                second = first;
                first = Some(v);
            }
            Some(f) if v < f => match second {
                None => second = Some(v),
                Some(s) if v > s => second = Some(v),
                _ => {}
            },
            _ => {} // v == f, duplicate of the max
        }
    }
    second
}

fn main() {
    assert_eq!(second_largest(&[3, 1, 4, 4, 5, 5]), Some(4));
    assert_eq!(second_largest(&[7, 7, 7]), None);
    assert_eq!(second_largest(&[]), None);
    assert_eq!(second_largest(&[-2, -5, -1]), Some(-2));
    println!("ok");
}
```

A single pass tracks the two highest *distinct* values. Duplicates of the current maximum are ignored, so `[7, 7, 7]` correctly yields `None`, and it works on negative numbers since `None` is used as the sentinel rather than an integer.

```python
from typing import Iterator, List, Optional


class RingBuffer:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._buf: List[Optional[int]] = [None] * capacity
        self._start = 0
        self._size = 0

    def push(self, value: int) -> None:
        """Append a value, overwriting the oldest when full."""
        index = (self._start + self._size) % self._capacity
        self._buf[index] = value
        if self._size < self._capacity:
            self._size += 1
        else:
            self._start = (self._start + 1) % self._capacity

    def get(self, i: int) -> int:
        if not 0 <= i < self._size:
            raise IndexError(f"index {i} out of range for size {self._size}")
        value = self._buf[(self._start + i) % self._capacity]
        assert value is not None
        return value

    def __len__(self) -> int:
        return self._size

    def __iter__(self) -> Iterator[int]:
        for i in range(self._size):
            yield self.get(i)


if __name__ == "__main__":
    rb = RingBuffer(3)
    for v in range(5):
        rb.push(v)
    assert list(rb) == [2, 3, 4]
    assert rb.get(0) == 2
    print("ok")
```

Oldest-first indexing is handled by treating the buffer as circular: logical index `i` maps to `(start + i) % capacity`. Once full, `push` advances `start` so the oldest entry is overwritten and reads stay in insertion order.

```c
#include <stdio.h>
#include <string.h>

/* Reverse word order in a mutable, NUL-terminated buffer. Collapses
   whitespace runs to single spaces and trims leading/trailing space. */
void reverse_words(char *s) {
    size_t n = strlen(s);
    char tmp[1024];
    size_t t = 0;
    size_t i = n;

    while (i > 0) {
        while (i > 0 && s[i - 1] == ' ') i--;
        size_t end = i;
        while (i > 0 && s[i - 1] != ' ') i--;
        if (t > 0 && t < sizeof(tmp)) tmp[t++] = ' ';
        for (size_t j = i; j < end && t < sizeof(tmp) - 1; j++) {
            tmp[t++] = s[j];
        }
    }
    tmp[t] = '\0';
    strcpy(s, tmp);
}

int main(void) {
    char buf[1024] = "  the   quick brown   fox  ";
    reverse_words(buf);
    printf("[%s]\n", buf);
    return 0;
}
```

It scans from the end, copying each maximal word into a scratch buffer separated by single spaces, which also trims the edges. The output for the sample is `[fox brown quick the]`. The scratch buffer is fixed at 1024 bytes, so inputs at least that long would truncate; size it to `n + 1` if you need arbitrary length.

```rust
use std::collections::HashMap;

pub struct LruCache<K, V> {
    capacity: usize,
    map: HashMap<K, V>,
    order: Vec<K>, // front = least recently used
}

impl<K: std::hash::Hash + Eq + Clone, V> LruCache<K, V> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        LruCache { capacity, map: HashMap::new(), order: Vec::new() }
    }

    fn touch(&mut self, key: &K) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            self.order.remove(pos);
        }
        self.order.push(key.clone());
    }

    pub fn put(&mut self, key: K, value: V) {
        self.touch(&key);
        self.map.insert(key.clone(), value);
        if self.map.len() > self.capacity {
            let evicted = self.order.remove(0);
            self.map.remove(&evicted);
        }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        if self.map.contains_key(key) {
            self.touch(key);
        }
        self.map.get(key)
    }

    pub fn len(&self) -> usize {
        self.map.len()
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put("a", 1);
    c.put("b", 2);
    assert_eq!(c.get(&"a"), Some(&1));
    c.put("c", 3); // evicts "b"
    assert_eq!(c.get(&"b"), None);
    println!("len={}", c.len());
}
```

A `Vec` tracks recency with the least-recently-used key at index 0; `get` and re-`put` move keys to the back. It uses `Vec::remove`/`position`, so operations are O(n) in capacity rather than the O(1) you'd get from a linked list or `indexmap`. `get` takes `&mut self` because it updates recency.

```python
from typing import Dict, List, Optional


def find_cycle(edges: List[tuple[int, int]]) -> Optional[List[int]]:
    """Return one cycle as a node list, or None if the graph is a DAG."""
    graph: Dict[int, List[int]] = {}
    for src, dst in edges:
        graph.setdefault(src, []).append(dst)
        graph.setdefault(dst, [])

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in graph}
    stack: List[int] = []

    def dfs(node: int) -> Optional[List[int]]:
        color[node] = GRAY
        stack.append(node)
        for nxt in graph.get(node, []):
            if color[nxt] == GRAY:
                return stack[stack.index(nxt):] + [nxt]
            if color[nxt] == WHITE:
                found = dfs(nxt)
                if found:
                    return found
        color[node] = BLACK
        stack.pop()
        return None

    for node in graph:
        if color[node] == WHITE:
            cycle = dfs(node)
            if cycle:
                return cycle
    return None


if __name__ == "__main__":
    assert find_cycle([(1, 2), (2, 3), (3, 1)]) == [1, 2, 3, 1]
    assert find_cycle([(1, 2), (2, 3)]) is None
    print("ok")
```

Three-colour DFS distinguishes a back edge (cycle) from a cross edge. A `GRAY` neighbour means we've re-entered the current path, so the slice from that node's position in `stack` is the cycle, closed by repeating the entry node. Recursion depth equals path length, so very deep graphs need an iterative version.

