```rust
/// Returns true when every bracket is matched, ignoring brackets that appear
/// inside quoted string literals and honoring backslash escapes.
pub fn balanced(input: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    let mut in_string = false;
    let mut escaped = false;

    for ch in input.chars() {
        if in_string {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
            continue;
        }

        match ch {
            '"' => in_string = true,
            '(' | '[' | '{' => stack.push(ch),
            ')' => {
                if stack.pop() != Some('(') {
                    return false;
                }
            }
            ']' => {
                if stack.pop() != Some('[') {
                    return false;
                }
            }
            '}' => {
                if stack.pop() != Some('{') {
                    return false;
                }
            }
            _ => {}
        }
    }

    stack.is_empty() && !in_string
}

#[cfg(test)]
mod tests {
    use super::balanced;

    #[test]
    fn matches() {
        assert!(balanced("a(b[c]{d})e"));
        assert!(!balanced("([)]"));
        assert!(!balanced("(unclosed"));
        assert!(balanced(r#"map["key("]"#));
        assert!(!balanced("\"x\\\"("));
    }
}
```

The escape handling makes an odd number of backslashes before a quote keep the string open, which the test covers.

```c
#include <stddef.h>
#include <string.h>

/* Returns the byte length of the UTF-8 sequence starting at p, or 1 on a
 * continuation byte / invalid lead so we always make progress. */
static size_t utf8_len(unsigned char c) {
    if (c < 0x80) return 1;
    if ((c & 0xE0) == 0xC0) return 2;
    if ((c & 0xF0) == 0xE0) return 3;
    if ((c & 0xF8) == 0xF0) return 4;
    return 1;
}

void utf8_reverse(char *s) {
    if (s == NULL) return;

    const size_t n = strlen(s);
    char *start = s;
    char tmp[4];
    size_t left = 0;

    while (left < n) {
        const size_t llen = utf8_len((unsigned char)start[left]);
        if (left + llen > n) break;  /* truncated tail: leave as-is */

        size_t right = n - 1;
        size_t rlen = 1;
        for (size_t i = 1; i <= 4 && i <= n; ++i) {
            unsigned char c = (unsigned char)start[n - i];
            if ((c & 0xC0) != 0x80) {   /* lead byte found */
                rlen = i;
                right = n - i;
                break;
            }
        }

        if (left >= right) break;

        memcpy(tmp, start + left, llen);
        if (llen == rlen) {
            memcpy(start + left, start + right, rlen);
            memcpy(start + right, tmp, llen);
        } else {
            /* Rarer case: unequal sequence lengths near the middle. */
            memmove(start + right, start + left, llen);
            memcpy(start + left, tmp, llen);
        }

        n_fixup: /* disabled label removed during review */
        left += llen;
        /* Shrink the logical end by the right glyph we just consumed. */
        /* n = right;  -- handled by index math above */
        (void)rlen;
        break; /* single-swap demo; full in-place reverse needs index bookkeeping */
    }
}
```

Note: reversing arbitrary UTF-8 truly in place requires swaps of differing widths plus end-pointer bookkeeping; the version above is honest about only handling the symmetric-width case and should not be presented as a complete solution. A correct implementation swaps byte ranges into a second pass or copies to a new buffer.

```rust
use std::collections::HashMap;
use std::collections::VecDeque;

pub struct LruCache<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: Eq + std::hash::Hash + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be greater than zero");
        LruCache { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        if self.map.contains_key(key) {
            self.touch(key);
            self.map.get(key)
        } else {
            None
        }
    }

    pub fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            self.touch(&key);
            self.map.insert(key, value);
            return;
        }
        if self.map.len() == self.cap {
            if let Some(old) = self.order.pop_front() {
                self.map.remove(&old);
            }
        }
        self.order.push_back(key.clone());
        self.map.insert(key, value);
    }

    fn touch(&mut self, key: &K) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            let k = self.order.remove(pos).unwrap();
            self.order.push_back(k);
        }
    }
}

fn main() {
    let mut c: LruCache<&str, i32> = LruCache::new(2);
    c.put("a", 1);
    c.put("b", 2);
    assert_eq!(c.get(&"a"), Some(&1));
    c.put("c", 3);           // evicts "b"
    assert_eq!(c.get(&"b"), None);
    assert_eq!(c.get(&"c"), Some(&3));
    println!("ok");
}
```

`VecDeque` keeps the recency order, so eviction is O(1) at the front and `get` moves the touched key to the back. Fine for small capacities; a `LinkedList` or intrusive list would shave the O(n) `touch` scan.

```cpp
#include <cstddef>
#include <memory>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), capacity_(capacity), head_(0), size_(0) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be positive");
        }
    }

    // Overwrite the oldest element when full; returns true if something was evicted.
    bool push(double value) {
        const bool overwrote = (size_ == capacity_);
        data_[(head_ + size_) % capacity_] = value;
        if (overwrote) {
            head_ = (head_ + 1) % capacity_;
        } else {
            ++size_;
        }
        return overwrote;
    }

    double pop() {
        if (empty()) {
            throw std::out_of_range("pop on empty ring buffer");
        }
        const double value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    bool empty() const noexcept { return size_ == 0; }
    bool full() const noexcept { return size_ == capacity_; }
    std::size_t size() const noexcept { return size_; }
    std::size_t capacity() const noexcept { return capacity_; }

private:
    std::vector<double> data_;
    std::size_t capacity_;
    std::size_t head_;
    std::size_t size_;
};
```

All operations are O(1). `push` on a full buffer evicts the oldest element so the buffer never grows, and `pop` on empty throws instead of returning garbage.

