import hashlib
import os
import sys
from collections import defaultdict

CHUNK = 1 << 20  # 1 MiB


def sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for block in iter(lambda: handle.read(CHUNK), b""):
            digest.update(block)
    return digest.hexdigest()


def find_duplicates(root):
    by_digest = defaultdict(list)
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            full = os.path.join(dirpath, name)
            if not os.path.isfile(full) or os.path.islink(full):
                continue
            try:
                by_digest[sha256_file(full)].append(full)
            except OSError as exc:
                print(f"skip {full}: {exc}", file=sys.stderr)
    return {d: paths for d, paths in by_digest.items() if len(paths) > 1}


if __name__ == "__main__":
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    groups = find_duplicates(target)
    if not groups:
        print("no duplicates found")
    for digest, paths in sorted(groups.items()):
        print(f"{digest}")
        for p in sorted(paths):
            print(f"  {p}")
```

Reads files in 1 MiB chunks so memory stays bounded, skips symlinks and unreadable files, and groups by full hex digest rather than by size alone.

