#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node* next;
} Node;

static Node* push(Node* head, int value) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "allocation failed\n");
        exit(1);
    }
    node->value = value;
    node->next = head;
    return node;
}

static Node* reverse(Node* head) {
    Node* prev = NULL;
    Node* cur = head;
    while (cur) {
        Node* next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

static void print(const Node* head) {
    for (const Node* n = head; n; n = n->next)
        printf("%d%s", n->value, n->next ? " -> " : "\n");
}

static void free_list(Node* head) {
    while (head) {
        Node* next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node* head = NULL;
    for (int i = 1; i <= 5; ++i) head = push(head, i);
    print(head);
    head = reverse(head);
    print(head);
    free_list(head);
    return 0;
}
