const MOD: u64 = 1_000_000_007;

pub fn fib_mod(n: u64) -> u64 {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let next = (a + b) % MOD;
        a = b;
        b = next;
    }
    a
}

fn main() {
    assert_eq!(fib_mod(0), 0);
    assert_eq!(fib_mod(10), 55);
    assert_eq!(fib_mod(90), 2880067194370816120 % MOD);
    for n in [0u64, 1, 2, 50, 1_000_000] {
        println!("fib({n}) mod = {}", fib_mod(n));
    }
}
```

Each addition is reduced mod `MOD` immediately, so `a + b` never exceeds ~2e9 and cannot overflow `u64`. The loop is O(n) time and O(1) space; for very large n you would switch to fast-doubling matrix exponentiation, but this is exact and safe for the stated modulus.

