def ipv4_to_int(addr):
    parts = addr.split('.')
    if len(parts) != 4:
        raise ValueError(f"expected 4 octets, got {len(parts)}")
    value = 0
    for p in parts:
        if not p.isdigit() or (len(p) > 1 and p[0] == '0'):
            raise ValueError(f"invalid octet: {p!r}")
        n = int(p)
        if n > 255:
            raise ValueError(f"octet out of range: {p}")
        value = (value << 8) | n
    return value


