#include <cstddef>
#include <iostream>
#include <vector>

std::vector<int> sieve(int n) {
    std::vector<int> primes;
    if (n < 2) return primes;
    std::vector<bool> composite(static_cast<std::size_t>(n) + 1, false);
    for (int i = 2; i <= n; ++i) {
        if (composite[static_cast<std::size_t>(i)]) continue;
        primes.push_back(i);
        if (static_cast<long long>(i) * i <= n) {
            for (long long j = static_cast<long long>(i) * i; j <= n; j += i)
                composite[static_cast<std::size_t>(j)] = true;
        }
    }
    return primes;
}

int main() {
    auto primes = sieve(100);
    std::cout << "count=" << primes.size() << " last=" << primes.back() << "\n";
}
```

The inner loop starts at `i*i` because smaller multiples were already marked by smaller primes, and the `long long` cast prevents `i*i` from overflowing before the comparison. For N=100 this prints `count=25 last=97`.

