std::vector<int> merge_unique(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    size_t i = 0, j = 0;
    while (i < a.size() || j < b.size()) {
        int v;
        if (j >= b.size() || (i < a.size() && a[i] <= b[j])) {
            v = a[i++];
        } else {
            v = b[j++];
        }
        if (out.empty() || out.back() != v) out.push_back(v);
    }
    return out;
}

int main() {
    assert((merge_unique({}, {}) == std::vector<int>{}));
    assert((merge_unique({}, {2, 2, 3}) == std::vector<int>{2, 3}));
    assert((merge_unique({1, 3, 5}, {2, 3, 6}) == std::vector<int>{1, 2, 3, 5, 6}));
    return 0;
}
