constexpr int64_t MOD = 1000000007;

int64_t fib_mod(int64_t n) {
    if (n < 0) return -1;
    int64_t a = 0, b = 1;
    for (int64_t k = 0; k < n; ++k) {
        int64_t next = (a + b) % MOD;
        a = b;
        b = next;
    }
    return a;
}

