void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;
    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    if (strcmp(a, "olleh") != 0) return 1;

    char b[] = "";
    reverse_in_place(b);
    if (strcmp(b, "") != 0) return 1;

    char c[] = "x";
    reverse_in_place(c);
    if (strcmp(c, "x") != 0) return 1;

    char d[] = "ab";
    reverse_in_place(d);
    if (strcmp(d, "ba") != 0) return 1;

    printf("all ok\n");
    return 0;
}
