DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def to_base36(n):
    if n < 0:
        raise ValueError("negative values are not supported")
    if n == 0:
        return "0"
    out = []
    while n:
        n, rem = divmod(n, 36)
        out.append(DIGITS[rem])
    return "".join(reversed(out))


def from_base36(s):
    if not s or s != s.lower():
        raise ValueError(f"invalid base36 string: {s!r}")
    value = 0
    for ch in s:
        idx = DIGITS.find(ch)
        if idx < 0:
            raise ValueError(f"invalid base36 digit: {ch!r}")
        value = value * 36 + idx
    return value


if __name__ == "__main__":
    for n in (0, 35, 36, 1234567, 2**40):
        assert from_base36(to_base36(n)) == n
    assert to_base36(0) == "0"
    assert from_base36("z") == 35
    for bad in ("", "Z", "abc!", "1 2"):
        try:
            from_base36(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"expected failure for {bad!r}")
    print("all ok")
```
Zero is special-cased because the repeated-division loop would otherwise return an empty string. `from_base36` rejects uppercase and any character outside the digit set, and the round-trip test covers large values.

