#include <cassert>
#include <iostream>
#include <queue>
#include <vector>

class RunningMedian {
public:
    void add(int value) {
        if (max_heap_.empty() || value <= max_heap_.top()) {
            max_heap_.push(value);
        } else {
            min_heap_.push(value);
        }
        // Keep sizes balanced: max_heap may be one larger than min_heap.
        if (max_heap_.size() > min_heap_.size() + 1) {
            min_heap_.push(max_heap_.top());
            max_heap_.pop();
        } else if (min_heap_.size() > max_heap_.size()) {
            max_heap_.push(min_heap_.top());
            min_heap_.pop();
        }
    }

    double median() const {
        if (max_heap_.empty()) return 0.0;
        if (max_heap_.size() == min_heap_.size()) {
            return (max_heap_.top() + min_heap_.top()) / 2.0;
        }
        return max_heap_.top();
    }

private:
    std::priority_queue<int> max_heap_;
    std::priority_queue<int, std::vector<int>, std::greater<int>> min_heap_;
};

int main() {
    RunningMedian rm;
    for (int v : {5, 15, 1, 3}) rm.add(v);
    assert(rm.median() == (3 + 5) / 2.0);
    rm.add(8);
    assert(rm.median() == 5.0);
    RunningMedian empty;
    assert(empty.median() == 0.0);
    std::cout << "all ok\n";
    return 0;
}
```
The lower half lives in a max-heap and the upper half in a min-heap, rebalanced after each insert so the median is always at a top. An empty stream returns 0.0 rather than reading from an empty heap.

