use std::collections::HashMap;
use std::hash::Hash;

fn mode<T: Eq + Hash + Clone>(items: &[T]) -> Option<T> {
    let mut counts: HashMap<&T, usize> = HashMap::new();
    for item in items {
        *counts.entry(item).or_insert(0) += 1;
    }
    // Iterate in slice order so the first-seen element wins a tie.
    let mut best: Option<(&T, usize)> = None;
    for item in items {
        let c = counts[item];
        match best {
            Some((_, bc)) if bc >= c => {}
            _ => best = Some((item, c)),
        }
    }
    best.map(|(item, _)| item.clone())
}

fn main() {
    assert_eq!(mode(&[1, 2, 2, 3, 3]), Some(2));   // tie: 2 appears first
    assert_eq!(mode(&["a", "b", "a"]), Some("a"));
    assert_eq!(mode::<i32>(&[]), None);             // empty input
    assert_eq!(mode(&[7, 7, 7]), Some(7));
    println!("all ok");
}
```
The scan deliberately walks the original slice rather than the `HashMap`, because map iteration order is unspecified and would make ties non-deterministic. An empty slice returns `None`.

