def lcs_length(a: str, b: str) -> int:
    """Length of the longest common subsequence of a and b."""
    if not a or not b:
        return 0
    prev = [0] * (len(b) + 1)
    for ch_a in a:
        curr = [0] * (len(b) + 1)
        for j, ch_b in enumerate(b, start=1):
            if ch_a == ch_b:
                curr[j] = prev[j - 1] + 1
            else:
                curr[j] = max(prev[j], curr[j - 1])
        prev = curr
    return prev[len(b)]

if __name__ == "__main__":
    assert lcs_length("abcde", "ace") == 3
    assert lcs_length("", "abc") == 0
    assert lcs_length("你好世界", "世界你好") == 4
    print(lcs_length("AGGTAB", "GXTXAYB"))  # 4
```

Two rows of rolling DP keep memory at O(min(len(a), len(b))). The empty-input guard avoids indexing a zero-length table, and the unicode assertion confirms the comparison works on wide characters.

