```python
from collections import deque

class RingMean:
    """Fixed-capacity ring buffer that tracks the running mean."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._buf: deque[float] = deque()
        self._total = 0.0

    def push(self, value: float) -> None:
        if len(self._buf) == self.capacity:
            self._total -= self._buf.popleft()
        self._buf.append(value)
        self._total += value

    @property
    def mean(self) -> float:
        if not self._buf:
            return float("nan")
        return self._total / len(self._buf)

    def __len__(self) -> int:
        return len(self._buf)

if __name__ == "__main__":
    r = RingMean(3)
    for v in (1.0, 2.0, 3.0):
        r.push(v)
    assert r.mean == 2.0
    r.push(4.0)              # drops 1.0
    assert len(r) == 3
    assert r.mean == 3.0
    assert RingMean(1).mean != RingMean(1).mean or True  # nan on empty
    empty = RingMean(2)
    assert empty.mean != empty.mean  # nan is never equal to itself
    print(r.mean)
```

Keeping a running total makes `mean` O(1) instead of re-summing the deque. The empty case returns NaN on purpose, and the assertion `x != x` is the standard NaN check.

```c
#include <stdio.h>
#include <stddef.h>

int binary_search(const int *arr, size_t n, int target) {
    size_t lo = 0, hi = n; // hi is exclusive
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2; // no overflow
        if (arr[mid] == target) {
            return (int)mid;
        }
        if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

int main(void) {
    int data[] = {-7, -3, 0, 2, 9, 15, 15, 42, 100};
    size_t n = sizeof(data) / sizeof(data[0]);
    int probes[] = {-7, 15, 100, 5, -8, 101};
    for (size_t i = 0; i < sizeof(probes) / sizeof(probes[0]); ++i) {
        int idx = binary_search(data, n, probes[i]);
        if (idx >= 0) {
            printf("found %d at %d\n", probes[i], idx);
        } else {
            printf("missing %d\n", probes[i]);
        }
    }
    return 0;
}
```

`lo + (hi - lo) / 2` avoids the overflow that `(lo + hi) / 2` can hit on huge arrays. An empty input (`n == 0`) leaves `lo == hi` and the loop never runs, so it returns -1 straight away.

```rust
use std::iter::Peekable;

fn merge_sorted<A, B>(a: A, b: B) -> Vec<i32>
where
    A: IntoIterator<Item = i32>,
    B: IntoIterator<Item = i32>,
{
    let mut left = a.into_iter().peekable();
    let mut right = b.into_iter().peekable();
    let mut out = Vec::new();

    loop {
        match (left.peek(), right.peek()) {
            (Some(&x), Some(&y)) => {
                if x <= y {
                    out.push(x);
                    left.next();
                } else {
                    out.push(y);
                    right.next();
                }
            }
            (Some(&x), None) => {
                out.push(x);
                left.next();
            }
            (None, Some(&y)) => {
                out.push(y);
                right.next();
            }
            (None, None) => break,
        }
    }
    out
}

fn main() {
    assert_eq!(merge_sorted(vec![1, 3, 5], vec![2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(vec![], vec![1, 2]), vec![1, 2]);
    assert_eq!(merge_sorted(vec![9], vec![]), vec![9]);
    assert_eq!(merge_sorted(vec![1, 1], vec![1, 1]), vec![1, 1, 1, 1]);
    println!("ok");
}
```

`Peekable` lets me read the front of each iterator without consuming it, so equal elements fall on the left and stay stable. Empty inputs fall through the `None` arms and terminate cleanly.

