#include <vector>

template <typename T>
std::optional<T> dot(const std::vector<T>& a, const std::vector<T>& b) {
    if (a.size() != b.size()) {
        return std::nullopt;
    }
    T acc{};
    for (std::size_t i = 0; i < a.size(); ++i) {
        acc += a[i] * b[i];
    }
    return acc;
}

int main() {
    std::vector<double> x{1.5, 2.0, -3.0};
    std::vector<double> y{2.0, -1.0, 4.0};
    auto r = dot(x, y);
    if (r) {
        std::cout << "dot = " << *r << '\n'; // 1.5*2 + 2*-1 + -3*4 = -11
    } else {
        std::cout << "size mismatch\n";
    }

    std::vector<double> z{1.0};
    std::cout << (dot(x, z).has_value() ? "ok" : "mismatch") << '\n';

    std::vector<int> empty;
    auto e = dot(empty, empty);
    std::cout << (e.has_value() ? "empty -> 0" : "bad") << '\n';
    return 0;
}
