    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void print(const Node* head) {
    for (; head; head = head->next) std::cout << head->value << ' ';
    std::cout << '\n';
}

int main() {
    Node a{1, nullptr};
    Node b{2, &a};
    Node c{3, &b};
    print(&c);
    std::cout << "reversed: ";
    print(reverse(&c));
    return 0;
}
```

The loop advances `head` while relinking each node to its predecessor, so an empty list (`nullptr`) returns `nullptr` unchanged. No allocation, so nothing to free.

