class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), size_(0) {}

    bool push(int value) {
        if (size_ == cap_) return false;
        buf_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    bool pop(int &out) {
        if (size_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return true;
    }

    bool is_empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    std::vector<int> buf_;
    std::size_t cap_, head_, size_;
};

