```rust
#[derive(Debug)]
pub struct RingBuffer {
    data: Vec<f64>,
    head: usize,
    len: usize,
}

impl RingBuffer {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        RingBuffer { data: vec![0.0; capacity], head: 0, len: 0 }
    }

    pub fn push(&mut self, value: f64) {
        let cap = self.data.len();
        if self.len < cap {
            let idx = (self.head + self.len) % cap;
            self.data[idx] = value;
            self.len += 1;
        } else {
            self.data[self.head] = value;
            self.head = (self.head + 1) % cap;
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Oldest-to-newest snapshot of the retained values.
    pub fn to_vec(&self) -> Vec<f64> {
        let cap = self.data.len();
        (0..self.len).map(|i| self.data[(self.head + i) % cap]).collect()
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    assert!(rb.is_empty());
    for v in [1.0, 2.0] {
        rb.push(v);
    }
    assert_eq!(rb.to_vec(), vec![1.0, 2.0]);
    for v in [3.0, 4.0, 5.0] {
        rb.push(v);
    }
    assert_eq!(rb.len(), 3);
    assert_eq!(rb.to_vec(), vec![3.0, 4.0, 5.0]);
    println!("{:?}", rb);
}
```

While there is spare room the buffer fills from the end; once full the head advances so the oldest sample is overwritten. `to_vec` walks forward from `head`, giving oldest-to-newest order regardless of wrap position.

