static int reverse_in_place(char *s, size_t len) {
    if (len < 2) {
        return 0;
    }
    size_t i = 0;
    size_t j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
        --j;
    }
    return 0;
}

int main(void) {
    const char *input = "XT-Luna: reverse me 123!";
    size_t len = strlen(input);

    char *buf = malloc(len + 1);
    if (buf == NULL) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    memcpy(buf, input, len + 1);

    reverse_in_place(buf, len);
    printf("%s\n", buf);

    free(buf);
    return 0;
}
```

`strlen` gives the byte count, so `malloc(len + 1)` reserves room for the terminator and `memcpy` copies it too. Reversal swaps only the first `len / 2` positions, which is a no-op for empty and single-character strings.

