#include <cassert>
#include <iostream>
#include <string>

std::string compress(const std::string& s) {
    if (s.empty()) return s;
    std::string out;
    std::size_t i = 0;
    while (i < s.size()) {
        char c = s[i];
        std::size_t j = i;
        while (j < s.size() && s[j] == c) ++j;
        out += c;
        out += std::to_string(j - i);
        i = j;
    }
    return out.size() < s.size() ? out : s;
}

int main() {
    assert(compress("aaabbc") == "a3b2c1");
    assert(compress("abc") == "abc");
    assert(compress("") == "");
    assert(compress("aaaaaaaaaa") == "a10");
    std::cout << "ok\n";
    return 0;
}
```
Note the multi-digit count case: `std::to_string` emits two characters for 10, so `"aaaaaaaaaa"` compresses to `"a10"` (length 3), which is shorter and therefore returned.

