```rust
use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<&str, usize> = HashMap::new();
    for word in text.split_whitespace() {
        *counts.entry(word).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts
        .into_iter()
        .map(|(w, c)| (w.to_string(), c))
        .collect();
    // Sort by count descending, then alphabetically for stable output.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let words = top_words("the quick the lazy  the", 2);
    assert_eq!(words, vec![("the".to_string(), 3), ("lazy".to_string(), 1)]);
    assert!(top_words("", 5).is_empty());
    println!("ok");
}
```

`split_whitespace` is Unicode-aware and collapses consecutive separators, so empty fields never appear. Ties break alphabetically, which keeps the result deterministic.

