pub fn check_brackets(s: &str) -> Result<(), usize> {
    let mut stack: Vec<(char, usize)> = Vec::new();
    for (i, ch) in s.chars().enumerate() {
        match ch {
            '(' | '[' | '{' => stack.push((ch, i)),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some((open, _)) if open == expected => {}
                    _ => return Err(i),
                }
            }
            _ => {}
        }
    }
    match stack.first() {
        Some(&(_, i)) => Err(i),
        None => Ok(()),
    }
}

fn main() {
    assert!(check_brackets("a(b[c]{d})e").is_ok());
    assert_eq!(check_brackets("a(b[c)d]"), Err(4));
    assert_eq!(check_brackets("(a[b)"), Err(4));
    assert_eq!(check_brackets("(("), Err(0));
    assert!(check_brackets("café (ok)").is_ok());
}
```

Characters are matched by index of `char`, not byte, so multibyte input reports a character position. An unmatched closing bracket reports its own index; an unclosed opener reports the first one left on the stack.

```c
#include <stdio.h>
#include <ctype.h>

int main(void) {
    unsigned long lines = 0, words = 0, chars = 0;
    int c;
    int in_word = 0;

    while ((c = getchar()) != EOF) {
        chars++;
        if (c == '\n') {
            lines++;
        }
        if (isspace(c)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            words++;
        }
    }

    printf("%lu %lu %lu\n", lines, words, chars);
    return 0;
}
