```rust
#[derive(Debug, PartialEq, Eq)]
pub struct Version {
    pub major: u32,
    pub minor: u32,
    pub patch: u32,
}

pub fn parse_version(s: &str) -> Result<Version, String> {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 3 {
        return Err(format!("expected 3 components, got {}", parts.len()));
    }
    let mut nums = [0u32; 3];
    for (i, p) in parts.iter().enumerate() {
        if p.is_empty() {
            return Err(format!("component {} is empty", i));
        }
        if !p.bytes().all(|b| b.is_ascii_digit()) {
            return Err(format!("component \"{}\" is not numeric", p));
        }
        // leading zeros are ambiguous; allow "0" but reject "01"
        if p.len() > 1 && p.starts_with('0') {
            return Err(format!("component \"{}\" has a leading zero", p));
        }
        nums[i] = p.parse::<u32>().map_err(|e| e.to_string())?;
    }
    Ok(Version { major: nums[0], minor: nums[1], patch: nums[2] })
}

fn main() {
    assert_eq!(parse_version("1.2.3"), Ok(Version { major: 1, minor: 2, patch: 3 }));
    assert_eq!(parse_version("0.0.0"), Ok(Version { major: 0, minor: 0, patch: 0 }));
    assert!(parse_version("1.2").is_err());
    assert!(parse_version("1.2.3.4").is_err());
    assert!(parse_version("1..3").is_err());
    assert!(parse_version("1.2.x").is_err());
    assert!(parse_version("01.2.3").is_err());
    assert!(parse_version("1.2.-3").is_err());
    println!("ok");
}
```

Every failure path returns a `Result` with a human-readable reason, and the leading-zero check stops `01.2.3` from silently parsing as `1.2.3`.

