```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        let mut data = Vec::with_capacity(capacity);
        data.resize_with(capacity, || None);
        RingBuffer { data, head: 0, len: 0 }
    }

    pub fn push(&mut self, item: T) {
        let cap = self.data.len();
        let idx = (self.head + self.len) % cap;
        self.data[idx] = Some(item);
        if self.len == cap {
            self.head = (self.head + 1) % cap;
        } else {
            self.len += 1;
        }
    }

    pub fn iter(&self) -> impl Iterator<Item = &T> {
        let cap = self.data.len();
        (0..self.len).map(move |i| self.data[(self.head + i) % cap].as_ref().unwrap())
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    rb.push(1);
    rb.push(2);
    rb.push(3);
    rb.push(4); // evicts 1
    let seen: Vec<i32> = rb.iter().copied().collect();
    assert_eq!(seen, vec![2, 3, 4]);

    let empty: RingBuffer<i32> = RingBuffer::new(2);
    assert_eq!(empty.iter().count(), 0);
    println!("ok");
}
```

Once full, `push` overwrites the oldest slot and advances `head`, giving FIFO eviction. The iterator walks `len` slots forward from `head` modulo capacity, so it yields elements in insertion order regardless of wrap-around.

```cpp
#include <condition_variable>
#include <iostream>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(size_t capacity) : cap_(capacity) {}

    void push(int v) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [&] { return q_.size() < cap_ || closed_; });
        if (closed_) return;
        q_.push(v);
        not_empty_.notify_one();
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [&] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;
        int v = q_.front();
        q_.pop();
        not_full_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lk(m_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::queue<int> q_;
    size_t cap_;
    bool closed_ = false;
    std::mutex m_;
    std::condition_variable not_empty_, not_full_;
};

int main() {
    BoundedQueue q(2);
    q.push(1);
    q.push(2);
    q.close();
    std::cout << *q.pop() << ' ' << *q.pop() << '\n';  // 1 2
    std::cout << (q.pop().has_value() ? "has value" : "empty") << '\n';
}
```

A single mutex guards the queue; `not_full_` blocks producers when the buffer is at capacity and `not_empty_` blocks consumers when it is empty. `close()` wakes everyone and makes `pop()` return `std::nullopt`, so a consumer drains remaining items and then terminates cleanly instead of deadlocking.

