#include <cassert>
#include <functional>
#include <iostream>
#include <queue>
#include <vector>

class RunningMedian {
public:
    void add(double value) {
        if (low_.empty() || value <= low_.top())
            low_.push(value);
        else
            high_.push(value);

        if (low_.size() > high_.size() + 1) {
            high_.push(low_.top());
            low_.pop();
        } else if (high_.size() > low_.size()) {
            low_.push(high_.top());
            high_.pop();
        }
    }

    double median() const {
        if (low_.empty()) return 0.0;
        if (low_.size() == high_.size())
            return (low_.top() + high_.top()) / 2.0;
        return low_.top();
    }

private:
    std::priority_queue<double> low_;                                 // max-heap
    std::priority_queue<double, std::vector<double>, std::greater<double>> high_; // min-heap
};

int main() {
    RunningMedian rm;
    for (double v : {3.0, 1.0, 4.0})
        rm.add(v);
    assert(rm.median() == 3.0);

    rm.add(2.0);
    assert(rm.median() == 2.5);

    RunningMedian empty;
    assert(empty.median() == 0.0);

