import re

_PATTERN = re.compile(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$")


def normalise_email(raw: str) -> str | None:
    """Return a lowercase, validated address, or None if invalid."""
    if not raw:
        return None
    candidate = raw.strip()
    if len(candidate) > 254:
        return None
    local, _, domain = candidate.rpartition("@")
    if not local or not domain:
        return None
    if candidate.count("@") != 1:
        return None
    if not _PATTERN.match(candidate):
        return None
    return candidate.lower()


