#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse_list(Node *head) {
    Node *prev = NULL;
    Node *curr = head;
    while (curr != NULL) {
        Node *next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) {
        return head;
    }
    n->value = value;
    n->next = head;
    return n;
}

int main(void) {
    Node *head = NULL;
    if (reverse_list(NULL) != NULL) {
        return 1;
    }
    for (int i = 1; i <= 4; i++) {
        head = push(head, i);
    }
    head = reverse_list(head);
    for (Node *p = head; p != NULL; p = p->next) {
        printf("%d ", p->value);
    }
    printf("\n");
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
```

`next` is saved before rewiring `curr->next`, so no node is lost. Empty input returns `NULL` unchanged, and the tail becomes the new head.

