bool is_palindrome(const std::string &text) {
    std::size_t left = 0;
    std::size_t right = text.size();
    if (right == 0) {
        return true;
    }
    --right;
    while (left < right) {
        unsigned char lc = static_cast<unsigned char>(text[left]);
        unsigned char rc = static_cast<unsigned char>(text[right]);
        if (!std::isalnum(lc)) {
            ++left;
            continue;
