template <typename Container>
auto max_element_opt(const Container &items) -> std::optional<typename Container::value_type> {
    if (items.empty()) {
        return std::nullopt;
    }
    auto best = items[0];
    for (const auto &item : items) {
        if (item > best) {
            best = item;
        }
    }
    return best;
}

int main() {
    std::vector<int> empty;
    std::vector<int> values{3, -7, 12, 12, 5};

    std::cout << std::boolalpha;
    std::cout << max_element_opt(empty).has_value() << "\n";
