MOD = 1_000_000_007


def fib_mod(n: int) -> int:
    """Return F(n) mod MOD using fast doubling in O(log n)."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def _pair(k: int):
        if k == 0:
            return (0, 1)
        a, b = _pair(k >> 1)
        c = (a * ((2 * b - a) % MOD)) % MOD
        d = (a * a + b * b) % MOD
        if k & 1:
            return (d, (c + d) % MOD)
        return (c, d)

    return _pair(n)[0]


