#[derive(Debug, PartialEq)]
pub enum WrapError {
    ZeroWidth,
    WordTooLong { word: String, width: usize },
}

pub fn wrap(text: &str, width: usize) -> Result<Vec<String>, WrapError> {
    if width == 0 {
        return Err(WrapError::ZeroWidth);
    }

    let mut lines: Vec<String> = Vec::new();
    let mut current = String::new();

    for word in text.split_whitespace() {
        if word.chars().count() > width {
            return Err(WrapError::WordTooLong { word: word.to_string(), width });
        }
        if current.is_empty() {
            current.push_str(word);
        } else if current.chars().count() + 1 + word.chars().count() <= width {
            current.push(' ');
            current.push_str(word);
        } else {
            lines.push(std::mem::take(&mut current));
            current.push_str(word);
        }
    }
    if !current.is_empty() {
        lines.push(current);
    }
    Ok(lines)
}

fn main() {
    let out = wrap("the quick brown fox jumps", 10).unwrap();
    assert_eq!(out, vec!["the quick", "brown fox", "jumps"]);
    assert!(wrap("hello", 0).is_err());
    assert!(wrap("toolongword here", 4).is_err());
}
