import re

_ALLOWED = re.compile(r"^[+()\-\s0-9]+$")


def to_e164(raw: str, default_cc: str = "1") -> str | None:
    """Return the number in E.164 form, or None if it cannot be normalized."""
    if not raw or not raw.strip():
        return None
    if not _ALLOWED.match(raw):
        return None

    had_plus = raw.lstrip().startswith("+")
    digits = re.sub(r"\D", "", raw)
    if not digits:
        return None

    if had_plus:
        candidate = digits
    elif len(digits) == 10:
        candidate = default_cc + digits
    elif digits.startswith("00"):
        candidate = digits[2:]
    else:
        candidate = digits

    if not (8 <= len(candidate) <= 15):
        return None
    if candidate.startswith("0"):
        return None
    return "+" + candidate


if __name__ == "__main__":
    assert to_e164("+1 (415) 555-0123") == "+14155550123"
    assert to_e164("415-555-0123") == "+14155550123"
    assert to_e164("0044 20 7946 0958") == "+442079460958"
