#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

struct intvec {
    int *data;
    size_t len;
    size_t cap;
};

static int intvec_grow(struct intvec *v, size_t needed) {
    if (needed <= v->cap) return 1;
    size_t cap = v->cap ? v->cap : 4;
    while (cap < needed) {
        if (cap > SIZE_MAX / 2) return 0;  /* overflow guard */
        cap *= 2;
    }
    int *grown = realloc(v->data, cap * sizeof *grown);
    if (grown == NULL) return 0;
    v->data = grown;
    v->cap = cap;
    return 1;
}

int intvec_push(struct intvec *v, int value) {
    if (!intvec_grow(v, v->len + 1)) return 0;
    v->data[v->len++] = value;
    return 1;
}

void intvec_free(struct intvec *v) {
    free(v->data);
    v->data = NULL;
    v->len = v->cap = 0;
}

int main(void) {
    struct intvec v = {0};
    for (int i = 0; i < 100; i++) {
        if (!intvec_push(&v, i * i)) {
            fprintf(stderr, "out of memory at %d\n", i);
            intvec_free(&v);
            return 1;
        }
    }
    printf("len=%zu cap=%zu last=%d\n", v.len, v.cap, v.data[v.len - 1]);
    intvec_free(&v);
    return 0;
}
