def fib(n):
    if n < 0:
        raise ValueError("n must be non-negative")

    def helper(k):
        """Return (F(k), F(k + 1)) using fast doubling."""
        if k == 0:
            return (0, 1)
        a, b = helper(k >> 1)
        c = a * (2 * b - a)
        d = a * a + b * b
        if k & 1:
            return (d, c + d)
        return (c, d)

    return helper(n)[0]


