// Euclid's algorithm. Returns a non-negative gcd.
// gcd(0, 0) == 0 by convention.
long long gcd(long long a, long long b) {
    a = std::llabs(a);
    b = std::llabs(b);
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

