#include <iostream>
#include <vector>

// Returns the index of `target` in sorted `v`, or -1 if absent.
// Uses lo + (hi - lo) / 2 to avoid integer overflow.
int binary_search(const std::vector<int>& v, int target) {
    int lo = 0;
    int hi = static_cast<int>(v.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == target) {
            return mid;
        } else if (v[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    std::vector<int> v = {-9, -2, 0, 3, 7, 7, 11, 42, 100};
    struct Case { int target, expected; };
    Case cases[] = {
        {7, 4},      // first of the duplicate 7s is not guaranteed; check presence below
        {100, 8},
        {-9, 0},
        {42, 7},
        {5, -1},
        {-100, -1},
        {101, -1},
    };

    bool all_ok = true;
    for (const auto& c : cases) {
        int idx = binary_search(v, c.target);
        bool ok;
        if (c.expected == -1) {
            ok = (idx == -1);
        } else if (c.target == 7) {
            // any index holding 7 is acceptable for duplicates
            ok = (idx >= 0 && idx < static_cast<int>(v.size()) && v[idx] == c.target);
        } else {
            ok = (idx == c.expected && v[idx] == c.target);
        }
        all_ok = all_ok && ok;
        std::cout << (ok ? "ok" : "FAIL") << ": search(" << c.target
                  << ") = " << idx << "\n";
    }

    // empty vector must return -1, not crash
    std::vector<int> empty;
    bool ok_empty = (binary_search(empty, 1) == -1);
    all_ok = all_ok && ok_empty;
    std::cout << (ok_empty ? "ok" : "FAIL") << ": empty vector -> -1\n";

    return all_ok ? 0 : 1;
}
