/// Parse comma-separated integers, ignoring empty fields.
/// Returns an error naming the offending token on the first failure.
fn parse_csv_ints(input: &str) -> Result<Vec<i64>, String> {
    let mut out = Vec::new();
    for (i, raw) in input.split(',').enumerate() {
        let token = raw.trim();
        if token.is_empty() {
            continue; // tolerate trailing commas / blank fields
        }
        match token.parse::<i64>() {
            Ok(n) => out.push(n),
            Err(_) => return Err(format!("field {} ({:?}) is not an integer", i, token)),
        }
    }
    Ok(out)
}

fn main() {
    // Success cases
    let ok_cases = [
        ("1,2,3", vec![1, 2, 3]),
        ("1,,3,", vec![1, 3]),
        (" -5 , 10 ", vec![-5, 10]),
        ("", vec![]),
        (",,,", vec![]),
    ];
    for (input, expected) in ok_cases {
        match parse_csv_ints(input) {
            Ok(v) => assert_eq!(v, expected, "input {:?}", input),
            Err(e) => panic!("unexpected error for {:?}: {}", input, e),
        }
        println!("ok: {:?} -> {:?}", input, expected);
    }

    // Failure cases: must be Err, not a silent skip
    for bad in ["1,x,3", "hello", "1,2,"] {
