from typing import List, Optional


class StackOverflow(Exception):
    pass


class BoundedStack:
    """A fixed-capacity LIFO stack."""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._items: List[int] = []

    def push(self, value: int) -> None:
        if len(self._items) >= self._capacity:
            raise StackOverflow(f"stack is full (capacity {self._capacity})")
        self._items.append(value)

    def pop(self) -> int:
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self) -> Optional[int]:
        return self._items[-1] if self._items else None

    def __len__(self) -> int:
        return len(self._items)

    def __repr__(self) -> str:
        return f"BoundedStack({self._items!r}, cap={self._capacity})"


if __name__ == "__main__":
    s = BoundedStack(3)
    assert s.peek() is None
    try:
        s.pop()
        raise AssertionError("pop on empty should have raised")
    except IndexError:
        print("ok: pop on empty raised")

    s.push(10)
    s.push(20)
    s.push(30)
    assert s.peek() == 30 and len(s) == 3
    try:
        s.push(40)
        raise AssertionError("push past capacity should have raised")
    except StackOverflow as e:
        print("ok: overflow raised:", e)

    assert s.pop() == 30
    assert s.pop() == 20
    s.push(99)
    assert s.pop() == 99
    assert len(s) == 1
    print("ok: stack invariants hold, final:", s)
