use std::collections::HashMap;

/// Count lowercase-normalised whitespace-delimited words in `text`
/// and return the top `n` as (word, count), sorted by count descending
/// and, on ties, word ascending.
fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        // Strip simple punctuation from the ends so "dog." and "dog" match.
        let cleaned: String = word
            .trim_matches(|c: char| !c.is_alphanumeric())
            .to_lowercase();
        if cleaned.is_empty() {
            continue;
        }
        *counts.entry(cleaned).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the cat the dog. The dog! a cat the";
    let got = top_words(text, 3);
    let expected = vec![
        ("the".to_string(), 4),
        ("cat".to_string(), 2),
        ("dog".to_string(), 2),
    ];
    assert_eq!(got, expected, "got {:?}", got);
    println!("ok: {:?}", got);

    // Ties broken by word ascending: "ant" before "bee".
    let tied = top_words("bee ant bee ant", 2);
    assert_eq!(tied, vec![("ant".to_string(), 2), ("bee".to_string(), 2)]);
    println!("ok ties: {:?}", tied);

    assert!(top_words("", 5).is_empty());
    assert!(top_words("!!! ...", 5).is_empty());
    println!("ok: empty and punctuation-only inputs");
}
