import re

_PATTERN = re.compile(r"^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$")


def parse_duration(text: str) -> int:
    """Parse a duration like '1h30m15s' into total seconds.

    Raises ValueError for empty or malformed input. Units must appear in
    order h, m, s and each may be omitted; bare '3600s' or '2h' are valid.
    """
    if not text:
        raise ValueError("duration string is empty")
    match = _PATTERN.match(text)
    if match is None or not any(match.groups()):
        raise ValueError(f"invalid duration: {text!r}")
    hours, minutes, seconds = (int(g) if g else 0 for g in match.groups())
    return hours * 3600 + minutes * 60 + seconds


if __name__ == "__main__":
