pub fn is_palindrome(input: &str) -> bool {
    let chars: Vec<char> = input
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();

    let mut left = 0usize;
    let mut right = chars.len();
    while left < right {
        let a = chars[left];
        let b = chars[right - 1];
        if a != b {
            return false;
        }
        left += 1;
        right -= 1;
    }
    true
}

