Iterating `chars()` works on Unicode scalar values, and `to_lowercase()` is flattened because a single character can expand to several (for example `İ`). The two-pointer scan compares the collected vector symmetrically; an empty or single-character input returns `true`.

```python
from collections import OrderedDict
from typing import Any, Optional


class LRUCache:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: "OrderedDict[Any, Any]" = OrderedDict()

    def get(self, key: Any) -> Optional[Any]:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: Any, value: Any) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1
    cache.put("c", 3)          # evicts "b", least recently used
    assert cache.get("b") is None
    assert cache.get("a") == 1
    assert len(cache) == 2
    print("ok")
```

`OrderedDict.move_to_end` marks a key as most recently used on every access, so `popitem(last=False)` evicts the oldest entry only when the capacity is exceeded. `get` returns `None` for a miss, which is why the assertions check identity with `is None`.

```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

template <typename Container>
auto max_element_optional(const Container& c)
    -> std::optional<typename Container::value_type> {
    using T = typename Container::value_type;
    if (c.empty()) {
        return std::nullopt;
    }
    T best = *c.begin();
    for (auto it = ++c.begin(); it != c.end(); ++it) {
        if (*it > best) {
            best = *it;
        }
    }
    return best;
}

int main() {
    std::vector<int> empty_vec;
    std::vector<int> nums{3, 9, 2, 7};

    auto a = max_element_optional(empty_vec);
    auto b = max_element_optional(nums);

    std::cout << (a.has_value() ? "has value" : "empty") << '\n';
    if (b) {
        std::cout << "max=" << *b << '\n';
    }
    return 0;
}
```

The return type is deduced from `Container::value_type`, and `std::optional` makes the empty case explicit instead of returning a dangling sentinel. The loop starts at the second element because `best` is already seeded from the first, so single-element containers work without a special case.

