// Returns nth Fibonacci (F(0)=0, F(1)=1) or nullopt on overflow.
std::optional<unsigned long long> fib(unsigned n) {
    auto a = 0ULL, b = 1ULL;
    for (unsigned i = 0; i < n; ++i) {
        if (a > ULLONG_MAX - b) return std::nullopt; // overflow guard
        auto next = a + b;
        a = b;
        b = next;
    }
    return a;
}

