void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t i = 0, j = strlen(s);
    while (j > 0 && i < --j) {
        char tmp = s[i];
        s[i++] = s[j];
        s[j] = tmp;
    }
}

