use std::collections::HashSet;

fn dedup_preserve_order<T: Eq + std::hash::Hash + Clone>(items: &[T]) -> Vec<T> {
    let mut seen = HashSet::new();
    let mut out = Vec::new();
    for item in items {
        if seen.insert(item.clone()) {
            out.push(item.clone());
        }
    }
    out
}

fn main() {
    let data = vec![3, 1, 3, 2, 1, 4, 2];
    let unique = dedup_preserve_order(&data);
    assert_eq!(unique, vec![3, 1, 2, 4]);

    let words = vec!["b", "a", "b", "c"];
    assert_eq!(dedup_preserve_order(&words), vec!["b", "a", "c"]);

    let empty: Vec<i32> = Vec::new();
    assert_eq!(dedup_preserve_order(&empty), Vec::<i32>::new());

    println!("ok");
}
```

`HashSet::insert` returns `false` when the value was already present, so the order of the output follows the original slice. Keep the `T: Clone` bound; for large owned types you would switch to `Vec<&T>`.

```cpp
#include <iostream>
#include <vector>

using Matrix = std::vector<std::vector<int>>;

void rotate90(Matrix& m) {
    const size_t n = m.size();
    for (size_t i = 0; i < n; ++i) {
        if (m[i].size() != n)
            throw std::invalid_argument("matrix must be square");
    }
    // Transpose.
    for (size_t i = 0; i < n; ++i)
        for (size_t j = i + 1; j < n; ++j)
            std::swap(m[i][j], m[j][i]);
    // Reverse each row.
    for (size_t i = 0; i < n; ++i)
        for (size_t j = 0; j < n / 2; ++j)
            std::swap(m[i][j], m[i][n - 1 - j]);
}

int main() {
    Matrix m = {{1, 2, 3},
                {4, 5, 6},
                {7, 8, 9}};
    rotate90(m);
    for (const auto& row : m) {
        for (int v : row) std::cout << v << ' ';
        std::cout << '\n';
    }
    // 7 4 1
    // 8 5 2
    // 9 6 3
}
```

Transpose plus horizontal mirror equals a 90-degree clockwise rotation. The `j = i + 1` bound in the transpose avoids swapping each pair twice, and the row reversal naturally leaves the middle column of odd sizes alone.

```rust
/// Split one CSV record into fields. Supports double-quoted fields,
/// doubled quotes ("" -> ") and commas inside quotes. Returns Err on
/// an unterminated quote.
pub fn parse_csv_line(line: &str) -> Result<Vec<String>, String> {
    let mut fields = Vec::new();
    let mut field = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();

    while let Some(c) = chars.next() {
        match c {
            '"' if in_quotes && chars.peek() == Some(&'"') => {
                field.push('"');
                chars.next();
            }
            '"' => in_quotes = !in_quotes,
            ',' if !in_quotes => fields.push(std::mem::take(&mut field)),
            _ => field.push(c),
        }
    }
    if in_quotes {
        return Err("unterminated quoted field".into());
    }
    fields.push(field);
    Ok(fields)
}

fn main() {
    let row = parse_csv_line(r#"alice,"Paris, France","say ""hi"""#).unwrap();
    assert_eq!(row, vec!["alice", "Paris, France", "say \"hi\""]);
    assert_eq!(parse_csv_line("a,b").unwrap(), vec!["a", "b"]);
    assert!(parse_csv_line(r#"""unclosed"#).is_err());
    println!("ok");
}
```

The `peekable` iterator lets a quote decide between ending a field and escaping a literal quote. This is a single-record parser; embedded newlines inside quotes need a streaming reader instead.

