use std::cmp::Ordering;

pub fn search<T: Ord>(slice: &[T], target: &T) -> Result<usize, usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            Ordering::Less => lo = mid + 1,
            Ordering::Greater => hi = mid,
            Ordering::Equal => return Ok(mid),
        }
    }
    Err(lo)
}

fn main() {
    let data = [1, 3, 5, 7, 9];
    assert_eq!(search(&data, &5), Ok(2));
    assert_eq!(search(&data, &6), Err(3));
    assert_eq!(search(&[], &1), Err(0));
    println!("ok");
}
```
`Ok(i)` is the found index; `Err(i)` is where the value would be inserted to keep order.

