def is_valid_ipv4(address: str) -> bool:
    """True if address is dotted-quad IPv4 with each octet in 0..255."""
    if not isinstance(address, str):
        return False
    parts = address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":
