#include <iostream>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), size_(0) {}

    bool push(int value) {
        if (size_ == buf_.size()) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % buf_.size();
        ++size_;
        return true;
    }

    bool pop(int& out) {
        if (size_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<int> buf_;
    std::size_t head_, tail_, size_;
};

int main() {
    RingBuffer rb(3);
    rb.push(1);
    rb.push(2);
    rb.push(3);
    if (rb.push(4)) return 1;
    int out = 0;
    rb.pop(out);
    std::cout << out << " size=" << rb.size() << "\n"; // 1 size=2
    return 0;
}
