def reverse_string(s: str) -> str:
    """Reverse a string, keeping combining characters with their base."""
    import unicodedata

    if s is None:
        raise TypeError("s must be a string, got None")
    if not s:
        return ""

    # Group grapheme-ish clusters: base char plus following combining marks.
    clusters = []
    for ch in s:
        if unicodedata.combining(ch) and clusters:
            clusters[-1] += ch
        else:
            clusters.append(ch)
    return "".join(reversed(clusters))


if __name__ == "__main__":
    print(reverse_string(""))              # ""
    print(reverse_string("abc"))           # "cba"
    print(reverse_string("a\u0301b"))      # "ba\u0301"
    print(reverse_string("\U0001F600ab"))  # "ba\U0001F600"
```

Empty input returns `""`, and the loop keeps combining marks (like the accent in `á`) attached to their base character so they reverse as one unit.

