#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::priority_queue<int> maxHeap;                              // lower half
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap; // upper half

    int x;
    while (std::cin >> x) {
        if (maxHeap.empty() || x <= maxHeap.top()) {
            maxHeap.push(x);
        } else {
            minHeap.push(x);
        }
        if (maxHeap.size() > minHeap.size() + 1) {
            minHeap.push(maxHeap.top());
            maxHeap.pop();
        } else if (minHeap.size() > maxHeap.size()) {
            maxHeap.push(minHeap.top());
            minHeap.pop();
        }

        double median;
        if (maxHeap.size() == minHeap.size()) {
            median = (static_cast<double>(maxHeap.top()) + minHeap.top()) / 2.0;
        } else {
            median = maxHeap.top();
        }
        std::cout << median << '\n';
    }
    return 0;
}
```

Two heaps keep the lower half in a max-heap and the upper half in a min-heap, rebalancing so their sizes differ by at most one. The median is the top of the larger heap, or the average of both tops when sizes match.

