```c
#include <stddef.h>
#include <limits.h>

/* Writes a NUL-terminated decimal string of n into buf (size cap).
   Returns the length written (excluding NUL), or 0 if cap is too small. */
size_t int_to_str(int n, char *buf, size_t cap) {
    char tmp[12]; /* enough for -2147483648 */
    int neg = 0;
    unsigned int mag;
    size_t i = 0, len;

    if (buf == NULL || cap == 0) return 0;

    if (n < 0) {
        neg = 1;
        /* Negate via unsigned so INT_MIN does not overflow. */
        mag = (unsigned int)(-(long long)n);
    } else {
        mag = (unsigned int)n;
    }

    do {
        tmp[i++] = (char)('0' + (mag % 10u));
        mag /= 10u;
    } while (mag != 0);

    len = i + (size_t)neg;
    if (len + 1 > cap) return 0;

    size_t pos = 0;
    if (neg) buf[pos++] = '-';
    while (i > 0) buf[pos++] = tmp[--i];
    buf[pos] = '\0';
    return len;
}
```

`INT_MIN` cannot be negated in `int`, so the magnitude is taken through a `long long` and cast to `unsigned int` before the digit loop. The function returns 0 rather than overflowing when the buffer is too small.

