def sum_numbers(line: str) -> float:
    """Sum semicolon-separated numbers in one line, ignoring blanks."""
    if not line or not line.strip():
        return 0.0

    total = 0.0
    for field in line.split(";"):
        field = field.strip()
        if not field:
            continue
        try:
            total += float(field)
        except ValueError:
            raise ValueError(f"not a number: {field!r}")
    return total


