```rust
#[derive(Debug, PartialEq)]
pub enum StackError {
    Overflow,
}

pub struct BoundedStack<T> {
    items: Vec<T>,
    cap: usize,
}

impl<T> BoundedStack<T> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        BoundedStack { items: Vec::with_capacity(cap), cap }
    }

    pub fn push(&mut self, item: T) -> Result<(), StackError> {
        if self.items.len() == self.cap {
            return Err(StackError::Overflow);
        }
        self.items.push(item);
        Ok(())
    }

    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn overflows_without_panic() {
        let mut s = BoundedStack::new(2);
        assert_eq!(s.push(1), Ok(()));
        assert_eq!(s.push(2), Ok(()));
        assert_eq!(s.push(3), Err(StackError::Overflow));
        assert_eq!(s.len(), 2);
        assert_eq!(s.pop(), Some(2));
    }
}
```

`push` checks the length before inserting and returns `Err(StackError::Overflow)` instead of panicking, so a full stack stays intact. `pop` returns `Option` for the empty case.

