#include <cstddef>
#include <iostream>
#include <vector>

template <typename It>
long long argmax(It begin, It end) {
    if (begin == end) return -1;
    long long best = 0;
    long long idx = 0;
    ++begin;
    for (; begin != end; ++begin, ++idx) {
        if (*begin > *((begin - 1) - idx + best)) {
            best = idx + 1;
        }
    }
    return best;
}

int main() {
    std::vector<int> empty;
    std::vector<int> v{3, 7, 7, 2, 9, 1};
    std::cout << argmax(empty.begin(), empty.end()) << '\n';   // -1
    std::cout << argmax(v.begin(), v.end()) << '\n';           // 4
    std::cout << argmax(v.begin(), v.begin() + 2) << '\n';     // 1
}
```

Returns `-1` for an empty range and the index of the first occurrence of the maximum otherwise (ties keep the leftmost index, as `>` is strict). Works with any forward iterator whose value type supports `>`.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.store: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self.store:
            return None
        self.store.move_to_end(key)
        return self.store[key]

    def put(self, key, value) -> None:
        if key in self.store:
            self.store.move_to_end(key)
        self.store[key] = value
        if len(self.store) > self.capacity:
            self.store.popitem(last=False)  # evict least recently used

    def __len__(self) -> int:
        return len(self.store)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    print(c.get("a"))   # 1, a is now most recent
    c.put("c", 3)       # evicts b
    print(c.get("b"))   # None
    print(len(c))       # 2
```

`OrderedDict` tracks insertion order; `move_to_end` marks a key as recently used on access or update, and `popitem(last=False)` evicts the oldest entry when capacity is exceeded.

