// Two-heap median: lower half is a max-heap, upper half is a min-heap.
// Invariant: lower.size() == upper.size() or lower.size() == upper.size() + 1.
int main() {
    std::priority_queue<int> lower;                              // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> upper; // min-heap

    int x;
    while (std::cin >> x) {
        if (lower.empty() || x <= lower.top()) {
            lower.push(x);
        } else {
            upper.push(x);
        }

        // rebalance
        if (lower.size() > upper.size() + 1) {
            upper.push(lower.top());
            lower.pop();
        } else if (upper.size() > lower.size()) {
            lower.push(upper.top());
            upper.pop();
        }

        double median;
        if (lower.size() == upper.size()) {
            median = (static_cast<double>(lower.top()) + upper.top()) / 2.0;
        } else {
            median = lower.top();
        }
        std::cout << median << '\n';
    }

    if (lower.empty()) {
        std::cerr << "no input\n";
        return 1;
    }
    return 0;
}
