#include <stdio.h>
#include <string.h>

/* Reverse a UTF-8 string in place, keeping code points intact.
   Walks from both ends and swaps whole multi-byte sequences. */
static size_t utf8_len(unsigned char c) {
    if (c < 0x80) return 1;
    if ((c & 0xE0) == 0xC0) return 2;
    if ((c & 0xF0) == 0xE0) return 3;
    if ((c & 0xF8) == 0xF0) return 4;
    return 1; /* invalid lead byte: treat as one */
}

void reverse_utf8(char *s) {
    size_t n = strlen(s);
    size_t i = 0, j = n;
    while (i < j) {
        size_t li = utf8_len((unsigned char)s[i]);
        if (i + li > j) li = 1;
        size_t lj = 1;
        if (j > 0) {
            j--;
            /* walk back to the lead byte of the right-hand code point */
            while (j > i && ((unsigned char)s[j] & 0xC0) == 0x80) j--;
            lj = utf8_len((unsigned char)s[j]);
        }
        for (size_t k = 0; k < li && k < lj; k++) {
            char tmp = s[i + k];
            s[i + k] = s[j + lj - 1 - k];
            s[j + lj - 1 - k] = tmp;
        }
        i += li;
    }
}

int main(void) {
    char buf[] = "cafe\u0301 \xE4\xBD\xA0\xE5\xA5\xBD"; /* "cafe<combining acute> <hi><ni>" */
    reverse_utf8(buf);
    printf("%s\n", buf);
    return 0;
}
