namespace detail {

// Leaf case: T is not a vector, so append it directly.
template <typename T, typename Out>
void flatten_into(const T& value, Out& out) {
    out.push_back(value);
}

// Nested case: recurse element by element.
template <typename T, typename Alloc, typename Out>
void flatten_into(const std::vector<T, Alloc>& vec, Out& out) {
    for (const auto& item : vec) {
        flatten_into(item, out);
    }
}

} // namespace detail

template <typename T>
auto flatten(const T& value) {
    // Deduce the innermost element type.
    using value_type = std::decay_t<decltype(value)>;
    using inner = typename value_type::value_type;
    std::vector<inner> out;
    detail::flatten_into(value, out);
    return out;
}

int main() {
    std::vector<std::vector<std::vector<int>>> nested = {
        {{1, 2}, {3}},
        {{4}},
        {{5, 6, 7}},
        {},
    };
    auto flat = flatten(nested);
    for (int v : flat) std::cout << v << ' ';
    std::cout << '\n';
    return 0;
