import hashlib
import sys


def sha256_file(path: str, chunk_size: int = 1 << 16) -> str:
    """Return the hex SHA-256 digest of a file, reading it in chunks."""
    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive")
    digest = hashlib.sha256()
    with open(path, "rb") as fh:
        while True:
            chunk = fh.read(chunk_size)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: sha256_file.py <file>", file=sys.stderr)
        sys.exit(2)
    try:
        print(sha256_file(sys.argv[1]))
    except FileNotFoundError:
        print(f"error: no such file: {sys.argv[1]}", file=sys.stderr)
        sys.exit(1)
    except IsADirectoryError:
        print(f"error: is a directory: {sys.argv[1]}", file=sys.stderr)
        sys.exit(1)
