#include <stdio.h>
#include <stdbool.h>

#define CAP 4

typedef struct {
    int data[CAP];
    size_t head;
    size_t count;
} Ring;

void ring_init(Ring *r) { r->head = 0; r->count = 0; }

bool ring_push(Ring *r, int value) {
    if (r->count == CAP) return false;
    r->data[(r->head + r->count) % CAP] = value;
    r->count++;
    return true;
}

bool ring_pop(Ring *r, int *out) {
    if (r->count == 0) return false;
    *out = r->data[r->head];
    r->head = (r->head + 1) % CAP;
    r->count--;
    return true;
}

int main(void) {
    Ring r;
    ring_init(&r);
    for (int i = 1; i <= 5; i++) {
        printf("push %d -> %s\n", i, ring_push(&r, i) ? "ok" : "full");
    }
    int v;
    while (ring_pop(&r, &v)) printf("pop %d\n", v);
    return 0;
}
