def is_valid_ipv4(s: str) -> bool:
    """Return True for dotted-decimal IPv4 like 192.168.0.1."""
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True


