#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t n = strlen(s);
    if (n < 2) return;
    char *left = s;
    char *right = s + n - 1;
    while (left < right) {
        char tmp = *left;
        *left++ = *right;
        *right-- = tmp;
    }
}

int main(void) {
