    const char *tests[] = {"hello", "a", "", "abcd", "ab"};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); i++) {
        strncpy(buf, tests[i], sizeof(buf) - 1);
        buf[sizeof(buf) - 1] = '\0';
        reverse_in_place(buf);
        printf("%s -> %s\n", tests[i], buf);
    }
    return 0;
}
