#include <iostream>
#include <queue>
#include <functional>

class MedianFinder {
    std::priority_queue<int> low;                             // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high;  // min-heap
public:
    void add(int x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);
        if (low.size() > high.size() + 1) { high.push(low.top()); low.pop(); }
        if (high.size() > low.size()) { low.push(high.top()); high.pop(); }
    }
    double median() const {
        if (low.size() == high.size()) return (low.top() + high.top()) / 2.0;
        return low.top();
    }
};

int main() {
    MedianFinder mf;
    int x;
    while (std::cin >> x) {
        mf.add(x);
        std::cout << mf.median() << '\n';
    }
    return 0;
}
