// Returns 0 on success, -1 on malformed input, -2 on range overflow.
int parse_long(const char *s, long *out) {
    if (s == NULL || *s == '\0') return -1;
    errno = 0;
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (end == s || *end != '\0') return -1;
    if (errno == ERANGE) return -2;
    *out = v;
    return 0;
}

int main(void) {
    struct { const char *s; int want; } cases[] = {
        {"42", 0}, {"-7", 0}, {"99999999999999999999", -2},
        {"12abc", -1}, {"", -1}, {" 5", -1},
    };
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        long v = 0;
        int rc = parse_long(cases[i].s, &v);
        if (rc != cases[i].want) {
            fprintf(stderr, "case %zu failed: got %d want %d\n", i, rc, cases[i].want);
            return 1;
        }
    }
    puts("all cases passed");
    return 0;
}
