use std::sync::{Arc, Mutex};
use std::thread;

struct Counter {
    value: Mutex<u64>,
    limit: u64,
}

impl Counter {
    fn new(limit: u64) -> Self {
        Counter { value: Mutex::new(0), limit }
    }
    /// Increments if below the limit; returns the value after the attempt.
    fn increment(&self) -> u64 {
        let mut v = self.value.lock().unwrap();
        if *v < self.limit {
            *v += 1;
        }
        *v
    }
}

fn main() {
    let counter = Arc::new(Counter::new(1000));
    let mut handles = Vec::new();
    for _ in 0..10 {
        let c = Arc::clone(&counter);
        handles.push(thread::spawn(move || {
            for _ in 0..200 {
                c.increment();
            }
        }));
    }
    for h in handles { h.join().unwrap(); }
    let final_value = *counter.value.lock().unwrap();
    assert_eq!(final_value, 1000, "expected 1000, got {final_value}");
    println!("counter capped at {final_value}");
}
