#include <stdio.h>
#include <string.h>

void reverse(char *s) {
    if (s == NULL) return;
    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) return;
    right--;                        /* last valid index */
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char a[] = "hello";
    reverse(a);
    printf("%s\n", a);             /* olleh */

    char b[] = "";
    reverse(b);
    printf("[%s]\n", b);           /* [] */

    char c[] = "x";
    reverse(c);
    printf("%s\n", c);             /* x */
    return 0;
}
```

Two-index swap from both ends inward. `strlen` gives the length, so `right` starts at the last character. `NULL`, empty, and single-character inputs all return without touching memory.

