#include <iostream>

bool isPalindrome(int x) {
    if (x < 0) return false;              // leading minus never a palindrome
    if (x != 0 && x % 10 == 0) return false; // trailing zero, e.g. 10

    int reversed = 0;
    while (x > reversed) {
        reversed = reversed * 10 + x % 10;
        x /= 10;
    }
    // even length: x == reversed; odd length: x == reversed / 10
    return x == reversed || x == reversed / 10;
}

int main() {
    std::cout << isPalindrome(121) << '\n';    // 1
    std::cout << isPalindrome(-121) << '\n';   // 0
    std::cout << isPalindrome(10) << '\n';     // 0
    std::cout << isPalindrome(0) << '\n';      // 1
    std::cout << isPalindrome(12321) << '\n';  // 1
    return 0;
}
