```c
#include <stdio.h>

int bsearch_int(const int *arr, size_t n, int target) {
    size_t lo = 0;
    size_t hi = n;                 /* exclusive upper bound */
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;   /* no overflow */
        if (arr[mid] == target) return (int)mid;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return -1;
}

int main(void) {
    int data[] = {1, 3, 5, 7, 9, 11};
    size_t n = sizeof data / sizeof data[0];

    printf("%d\n", bsearch_int(data, n, 7));   /* 3 */
    printf("%d\n", bsearch_int(data, n, 1));   /* 0 */
    printf("%d\n", bsearch_int(data, n, 11));  /* 5 */
    printf("%d\n", bsearch_int(data, n, 4));   /* -1 */
    printf("%d\n", bsearch_int(data, 0, 4));   /* -1 */
    return 0;
}
```

Half-open interval `[lo, hi)` keeps the loop invariant simple. `mid` is computed as `lo + (hi - lo) / 2` so it can't overflow on huge arrays, and a zero-length array safely returns -1.

