// Reverses the C string in place. Null-safe; no allocation.
void reverse_in_place(char* s) {
    if (s == nullptr) return;
    std::size_t n = std::strlen(s);
    if (n < 2) return;
    for (std::size_t i = 0, j = n - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

int main() {
    char a[] = "hello";
    reverse_in_place(a);
    std::cout << a << '\n';        // olleh

    char b[] = "";
    reverse_in_place(b);
    std::cout << b << '\n';        // (empty)

    reverse_in_place(nullptr);     // no crash
    return 0;
}
