```cpp
#include <array>
#include <cstddef>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == N) return false;       // full
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt; // empty
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

#include <iostream>
int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    std::cout << rb.push(4) << '\n';       // 0 (full)
    std::cout << rb.pop().value() << '\n'; // 1
    std::cout << rb.push(4) << '\n';       // 1
}
```

Capacity is enforced by `count_`; indices wrap with `% N`, so no reallocation happens. `pop` on empty returns `std::nullopt` instead of reading garbage.

