```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define BUCKETS 1024
#define MAX_WORD 64

typedef struct Entry {
    char word[MAX_WORD];
    int count;
    struct Entry *next;
} Entry;

static Entry *table[BUCKETS];
static Entry *seen[4096];
static int seen_n = 0;

static unsigned hash(const char *s) {
    unsigned h = 5381;
    while (*s) h = h * 33u + (unsigned char)*s++;
    return h % BUCKETS;
}

static void add(const char *w) {
    unsigned i = hash(w);
    for (Entry *e = table[i]; e; e = e->next) {
        if (strcmp(e->word, w) == 0) { e->count++; return; }
    }
    Entry *e = malloc(sizeof(*e));
    if (!e) { perror("malloc"); exit(1); }
    strncpy(e->word, w, MAX_WORD - 1);
    e->word[MAX_WORD - 1] = '\0';
    e->count = 1;
    e->next = table[i];
    table[i] = e;
    if (seen_n < 4096) seen[seen_n++] = e;
}

int main(void) {
    char buf[MAX_WORD];
    int c, n = 0;
    while ((c = getchar()) != EOF) {
        if (isalpha((unsigned char)c)) {
            if (n < MAX_WORD - 1) buf[n++] = (char)tolower((unsigned char)c);
        } else if (n > 0) {
            buf[n] = '\0';
            add(buf);
            n = 0;
        }
    }
    if (n > 0) { buf[n] = '\0'; add(buf); }

    for (int i = 0; i < seen_n; i++)
        printf("%s %d\n", seen[i]->word, seen[i]->count);

    for (int i = 0; i < BUCKETS; i++) {
        Entry *e = table[i];
        while (e) { Entry *nx = e->next; free(e); e = nx; }
    }
    return 0;
}
