    ~RingBuffer() { delete[] buf_; }

    RingBuffer(const RingBuffer&) = delete;
    RingBuffer& operator=(const RingBuffer&) = delete;

    bool push(double v) {
        if (size_ == cap_) return false;   // full, caller's choice
        buf_[(head_ + size_) % cap_] = v;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) return std::nullopt;
        double v = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

    // returns nullptr when out of range
    const double* at(std::size_t i) const {
        if (i >= size_) return nullptr;
        return &buf_[(head_ + i) % cap_];
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return cap_; }

private:
    std::size_t cap_;
    double*     buf_;
    std::size_t head_;
    std::size_t size_;
};

#include <cassert>
int main() {
    RingBuffer rb(3);
    assert(rb.push(1.5) && rb.push(2.5) && rb.push(3.5));
    assert(!rb.push(4.5));
    assert(rb.at(0) && *rb.at(0) == 1.5);
    assert(rb.at(3) == nullptr);
    assert(*rb.pop() == 1.5);
    assert(rb.size() == 2);
}
```

`push` returns `false` when full instead of throwing, `pop` returns `std::optional`, and `at` returns a null pointer past the end. Copying is deleted to avoid a double free.

```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

#[cfg(test)]
mod tests {
    use super::merge_sorted;

    #[test]
    fn basic() {
        assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    }

    #[test]
    fn empty_inputs() {
        assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
        assert_eq!(merge_sorted(&[1, 2], &[]), vec![1, 2]);
        assert_eq!(merge_sorted(&[], &[-3, 0]), vec![-3, 0]);
    }

    #[test]
    fn duplicates_are_kept() {
        assert_eq!(merge_sorted(&[1, 1, 4], &[1, 3]), vec![1, 1, 1, 3, 4]);
    }
}

fn main() {
    println!("{:?}", merge_sorted(&[1, 3, 5], &[2, 4, 6]));
}
```

Both slices are walked by index and the leftover tail of whichever input remains is appended with `extend_from_slice`, so no input is cloned and stability is preserved by the `<=` comparison.

```cpp
#include <array>
#include <cstdint>
#include <optional>
#include <string>

std::optional<std::array<std::uint8_t, 4>> parse_ipv4(const std::string& s) {
    std::array<std::uint8_t, 4> out{};
    int part = 0;      // octet index
    int val = 0;       // value being built
    int digits = 0;    // digits in current octet

    for (std::size_t i = 0; i <= s.size(); ++i) {
        char c = (i == s.size()) ? '.' : s[i];   // sentinel terminator

        if (c == '.') {
            if (digits == 0 || val > 255) return std::nullopt;
            out[part++] = static_cast<std::uint8_t>(val);
            val = 0;
            digits = 0;
            if (part == 4 && i != s.size()) return std::nullopt; // extra chars
            if (part > 4) return std::nullopt;
        } else if (c >= '0' && c <= '9') {
            if (digits == 3) return std::nullopt;   // no 4+ digit octets
            if (digits == 1 && val == 0) return std::nullopt; // leading zero
            val = val * 10 + (c - '0');
            ++digits;
        } else {
            return std::nullopt;
        }
    }
    if (part != 4) return std::nullopt;
    return out;
}

#include <cassert>
int main() {
    auto ok = parse_ipv4("192.168.0.1");
    assert(ok && (*ok)[0] == 192 && (*ok)[3] == 1);
    assert(!parse_ipv4("256.1.1.1"));
    assert(!parse_ipv4("1.2.3"));
    assert(!parse_ipv4("1.2.3.4.5"));
    assert(!parse_ipv4("01.2.3.4"));
    assert(!parse_ipv4("1.2.3.x"));
}
```

A sentinel `.` at the end removes the need to special-case the last octet. Leading zeros, more than three digits, extra parts, and any non-digit all return `std::nullopt`.

```rust
use std::collections::HashMap;

fn top_k_chars(s: &str, k: usize) -> Vec<(char, usize)> {
    let mut counts: HashMap<char, usize> = HashMap::new();
    for c in s.chars() {
        *counts.entry(c).or_insert(0) += 1;
    }

    let mut pairs: Vec<(char, usize)> = counts.into_iter().collect();
    // higher count first; on ties, smaller char first
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(k);
    pairs
}

#[cfg(test)]
mod tests {
    use super::top_k_chars;

    #[test]
    fn orders_by_count_then_char() {
        let got = top_k_chars("aabbc", 2);
        assert_eq!(got, vec![('a', 2), ('b', 2)]);
    }

    #[test]
    fn handles_unicode() {
        let got = top_k_chars("héllo héllo", 1);
        assert_eq!(got, vec![('l', 4)]);
    }

    #[test]
    fn k_larger_than_distinct() {
        assert_eq!(top_k_chars("zzz", 10).len(), 1);
        assert_eq!(top_k_chars("", 3), Vec::new());
    }
}

fn main() {
    println!("{:?}", top_k_chars("mississippi", 3));
}
```

`chars()` iterates Unicode scalar values, so accented input counts per character rather than per byte. Sorting uses `then_with` to make ties deterministic, and `truncate` handles `k` larger than the number of distinct characters.

