use std::collections::HashMap;

fn fib(n: u64, memo: &mut HashMap<u64, u128>) -> u128 {
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return 1;
    }
    if let Some(&v) = memo.get(&n) {
        return v;
    }
    let v = fib(n - 1, memo) + fib(n - 2, memo);
    memo.insert(n, v);
    v
}

fn main() {
    let mut memo = HashMap::new();
    assert_eq!(fib(0, &mut memo), 0);
    assert_eq!(fib(1, &mut memo), 1);
    assert_eq!(fib(10, &mut memo), 55);
    // fib(90) fits comfortably in u128
    println!("fib(90)={}", fib(90, &mut memo));
}
