def parse_csv(text: str, required_fields: tuple[str, ...] = ()) -> list[dict[str, str]]:
    """Parse CSV text into dicts. Raise ValueError on missing columns."""
    reader = csv.DictReader(io.StringIO(text))
    rows = []
    for i, row in enumerate(reader, start=1):
        clean = {(k or ""): (v if v is not None else "") for k, v in row.items()}
        for field in required_fields:
            if not clean.get(field):
                raise ValueError(f"row {i}: missing required field {field!r}")
        rows.append(clean)
    return rows

