import time
import functools

def retry(attempts: int = 3, base: float = 0.5, exceptions=(Exception,)):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            delay = base
            for i in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except exceptions as e:
                    if i == attempts - 1:
                        raise
                    time.sleep(delay)
                    delay *= 2
        return wrapper
    return deco

@retry(attempts=3, base=0.1)
def flaky():
    raise ValueError("nope")

if __name__ == "__main__":
    try:
        flaky()
    except ValueError as e:
        print("gave up after retries:", e)
