#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
    std::array<int, N> buf{};
    std::size_t head = 0;  // next read
    std::size_t tail = 0;  // next write
    std::size_t count = 0;
public:
    bool full()  const { return count == N; }
    bool empty() const { return count == 0; }

    bool push(int v) {
        if (full()) return false;
        buf[tail] = v;
        tail = (tail + 1) % N;
        ++count;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int v = buf[head];
        head = (head + 1) % N;
        --count;
        return v;
    }
};

int main() {
    RingBuffer<3> rb;
    for (int i = 0; i < 3; ++i) std::cout << rb.push(i) << '\n';
    std::cout << "full push: " << rb.push(99) << '\n';
    while (auto v = rb.pop()) std::cout << *v << '\n';
    std::cout << "empty pop has value? " << rb.pop().has_value() << '\n';
    return 0;
}
