std::uint64_t isqrt(std::uint64_t n) {
    if (n < 2) return n;
    std::uint64_t lo = 1, hi = n / 2 + 1, ans = 0;
    while (lo <= hi) {
        std::uint64_t mid = lo + (hi - lo) / 2;
        if (mid <= n / mid) {
            ans = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return ans;
}

