def median(nums):
    if not nums:
        raise ValueError("median of empty list")
    vals = list(nums)
    n = len(vals)
    mid = n // 2
    # Quickselect: partition until the mid element is in final position.
    def select(arr, k):
        while True:
            if len(arr) <= 5:
                return sorted(arr)[k]
            pivot = arr[len(arr) // 2]
            lows = [x for x in arr if x < pivot]
            highs = [x for x in arr if x > pivot]
            if k < len(lows):
                arr = lows
            elif k < len(arr) - len(highs):
                return pivot
            else:
                k -= len(arr) - len(highs)
                arr = highs

    if n % 2 == 1:
        return float(select(vals, mid))
    return (select(vals, mid - 1) + select(vals, mid)) / 2.0


