```python
class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.cap = capacity
        self.map = {}
        self.head = {}  # use node dicts {key, prev, next}
        self.tail = {}

    def _remove(self, node):
        p, n = node['prev'], node['next']
        if p is not None:
            p['next'] = n
        else:
            self.head = n
        if n is not None:
            n['prev'] = p
        else:
            self.tail = p

    def _push_front(self, node):
        node['prev'] = None
        node['next'] = self.head
        if self.head is not None:
            self.head['prev'] = node
        self.head = node
        if self.tail is None:
            self.tail = node

    def get(self, key):
        if key not in self.map:
            return -1
        node = self.map[key]
        self._remove(node)
        self._push_front(node)
        return node['value']

    def put(self, key, value):
        if key in self.map:
            node = self.map[key]
            node['value'] = value
            self._remove(node)
            self._push_front(node)
            return
        if len(self.map) >= self.cap:
            del self.map[self.tail['key']]
            self._remove(self.tail)
        node = {'key': key, 'value': value, 'prev': None, 'next': None}
        self.map[key] = node
        self._push_front(node)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, 1); c.put(2, 2)
    assert c.get(1) == 1
    c.put(3, 3)          # evicts 2
    assert c.get(2) == -1
    assert c.get(3) == 3
    print("ok")
