template <typename T>
T gcd(T a, T b) {
    // Make absolute using unsigned arithmetic to avoid overflow on INT_MIN.
    auto ua = a < 0 ? static_cast<T>(-(a + 1)) + 1 : a;
    auto ub = b < 0 ? static_cast<T>(-(b + 1)) + 1 : b;
    while (ub != 0) {
        T t = ua % ub;
        ua = ub;
        ub = t;
    }
    return ua;
}

int main() {
    std::cout << gcd(48, 18) << '\n';        // 6
    std::cout << gcd(-48, 18) << '\n';       // 6
    std::cout << gcd(0, 7) << '\n';          // 7
    std::cout << gcd(0, 0) << '\n';          // 0
    return 0;
}
