```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) return head;
    n->value = value;
    n->next = head;
    return n;
}

void print_list(const Node *head) {
    for (; head; head = head->next) printf("%d ", head->value);
    printf("\n");
}

int main(void) {
    Node *list = NULL;
    for (int i = 1; i <= 5; i++) list = push(list, i);
    print_list(list);              // 5 4 3 2 1
    list = reverse(list);
    print_list(list);              // 1 2 3 4 5
    list = reverse(NULL);
    printf("%s\n", list == NULL ? "null-safe" : "fail");
    while (list) { Node *n = list->next; free(list); list = n; }
    return 0;
}
```
The loop flips each `next` pointer in place, using three pointers, so it is O(n) time and O(1) space. `reverse(NULL)` returns `NULL`, and the harness frees every node it allocated.

