```cpp
#include <iostream>
#include <vector>

int binary_search(const std::vector<int> &data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;   // avoids overflow
        if (data[mid] == target) return mid;
        if (data[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> data = {-9, -3, 0, 4, 7, 12, 25, 31};
    std::cout << binary_search(data, 7) << '\n';   // 4
    std::cout << binary_search(data, -9) << '\n';  // 0
    std::cout << binary_search(data, 31) << '\n';  // 7
    std::cout << binary_search(data, 5) << '\n';   // -1
    std::cout << binary_search({}, 1) << '\n';     // -1
    return 0;
}
```
`mid = lo + (hi - lo) / 2` avoids integer overflow on large ranges. The loop condition `lo <= hi` handles the single-element case, and an empty vector yields `hi = -1` so it returns -1 immediately.

```cpp
#include <algorithm>
#include <cmath>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

int main() {
    std::string line;
    if (!std::getline(std::cin, line)) return 0;

    std::vector<double> v;
    std::stringstream ss(line);
    std::string token;
    while (std::getline(ss, token, ',')) {
        // Skip empty tokens (leading, trailing, doubled commas).
        if (token.find_first_not_of(" \t\r\n") == std::string::npos) continue;
        try {
            size_t used = 0;
            double x = std::stod(token, &used);
            if (used == token.find_first_not_of(" \t\r\n") || used > 0)
                v.push_back(x);
        } catch (const std::exception&) {
            std::cerr << "skipping invalid token: " << token << '\n';
        }
    }

    if (v.empty()) {
        std::cout << "no numbers\n";
        return 0;
    }

    double sum = 0.0;
    for (double x : v) sum += x;
    double mean = sum / static_cast<double>(v.size());

    std::sort(v.begin(), v.end());
    size_t n = v.size();
    double median = (n % 2) ? v[n / 2] : 0.5 * (v[n / 2 - 1] + v[n / 2]);

    double var = 0.0;
    for (double x : v) var += (x - mean) * (x - mean);
    var /= static_cast<double>(n);

    std::cout << "count=" << n << " mean=" << mean
              << " median=" << median
              << " stddev=" << std::sqrt(var) << '\n';
    return 0;
}
