```c
#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
#include <string.h>
#include <limits.h>

/**
 * Convert value to a NUL-terminated string in the given radix (2..36).
 * Writes at most cap bytes including the terminator.
 * Uses unsigned magnitude to avoid overflow on INT64_MIN.
 * Returns the length written (excluding NUL), or -1 on error/truncation.
 */
int i64_to_base(int64_t value, int radix, char *out, size_t cap) {
    static const char digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";
    char tmp[70];  /* 64 bits in base 2 is 64 digits + sign + NUL */
    size_t n = 0;
    int negative = 0;
    uint64_t mag;

    if (radix < 2 || radix > 36 || cap == 0) return -1;

    if (value < 0) {
        negative = 1;
        /* -(uint64_t)value is INT64_MIN-safe: unsigned wrap yields 2^63. */
        mag = ~(uint64_t)value + 1u;
    } else {
        mag = (uint64_t)value;
    }

    if (mag == 0) {
        tmp[n++] = '0';
    } else {
        while (mag > 0) {
            tmp[n++] = digits[mag % (uint64_t)radix];
            mag /= (uint64_t)radix;
        }
    }
    if (negative) tmp[n++] = '-';

    if (n + 1 > cap) return -1;
    for (size_t i = 0; i < n; ++i) out[i] = tmp[n - 1 - i];
    out[n] = '\0';
    return (int)n;
}

int main(void) {
    char buf[80];
    struct { int64_t v; int r; const char *want; } cases[] = {
        {255, 16, "ff"},
        {0, 2, "0"},
        {-1, 10, "-1"},
        {INT64_MIN, 10, "-9223372036854775808"},
        {INT64_MIN, 16, "-8000000000000000"},
        {INT64_MAX, 36, "3w5e11264sgsf"},
    };
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; ++i) {
        int n = i64_to_base(cases[i].v, cases[i].r, buf, sizeof buf);
        if (n < 0 || strcmp(buf, cases[i].want) != 0) {
            fprintf(stderr, "FAIL %lld base %d -> %s (want %s)\n",
                    (long long)cases[i].v, cases[i].r, buf, cases[i].want);
            return 1;
        }
    }
    printf("all conversions correct\n");
    return 0;
}
