```python
from typing import Iterable, Iterator, Sequence, TypeVar

T = TypeVar("T")


def sliding_windows(seq: Sequence[T], window: int, step: int = 1) -> Iterator[tuple[T, ...]]:
    """Yield tuples of `window` consecutive items, moving `step` each time.

    >>> list(sliding_windows([1, 2, 3, 4], 2))
    [(1, 2), (2, 3), (3, 4)]
    >>> list(sliding_windows([1, 2, 3, 4, 5], 3, 2))
    [(1, 2, 3), (3, 4, 5)]
    """
    if window <= 0:
        raise ValueError(f"window must be positive, got {window}")
    if step <= 0:
        raise ValueError(f"step must be positive, got {step}")

    n = len(seq)
    if window > n:
        return  # empty: no full window fits

    for start in range(0, n - window + 1, step):
        yield tuple(seq[start:start + window])


def sliding_windows_iter(it: Iterable[T], window: int, step: int = 1) -> Iterator[tuple[T, ...]]:
    """Streaming variant that works on one-pass iterables."""
    if window <= 0:
        raise ValueError(f"window must be positive, got {window}")
    if step <= 0:
        raise ValueError(f"step must be positive, got {step}")

    buffer: list[T] = []
    for item in it:
        buffer.append(item)
        if len(buffer) == window:
            yield tuple(buffer)
            del buffer[:step]


if __name__ == "__main__":
    assert list(sliding_windows([1, 2, 3, 4], 2)) == [(1, 2), (2, 3), (3, 4)]
    assert list(sliding_windows([1, 2, 3, 4, 5], 3, 2)) == [(1, 2, 3), (3, 4, 5)]
    assert list(sliding_windows([1, 2], 3)) == []
    assert list(sliding_windows_iter(iter("abcd"), 2)) == [("a", "b"), ("b", "c"), ("c", "d")]
    for bad in (0, -1):
        try:
            list(sliding_windows([1, 2, 3], bad))
        except ValueError as exc:
            assert "window" in str(exc)
    print("all window tests passed")
