#include <sstream>
#include <string>
#include <vector>

// Greedy word wrap. Words longer than width are printed on their own line
// rather than split, so no characters are lost.
static std::vector<std::string> wrap(const std::vector<std::string>& words, size_t width) {
    std::vector<std::string> lines;
    std::string cur;
    for (const auto& w : words) {
        if (w.size() > width) {
            if (!cur.empty()) { lines.push_back(cur); cur.clear(); }
            lines.push_back(w);          // cannot split; emit as-is
            continue;
        }
        if (cur.empty()) {
            cur = w;
        } else if (cur.size() + 1 + w.size() <= width) {
            cur += ' ';
            cur += w;
        } else {
            lines.push_back(cur);
            cur = w;
        }
    }
    if (!cur.empty()) lines.push_back(cur);
    return lines;
}

int main(int argc, char** argv) {
    if (argc < 2) { std::cerr << "usage: wrap FILE [WIDTH]\n"; return 2; }
    size_t width = (argc >= 3) ? std::stoul(argv[2]) : 72;
    if (width == 0) { std::cerr << "width must be > 0\n"; return 2; }

    std::ifstream in(argv[1]);
    if (!in) { std::cerr << "cannot open " << argv[1] << '\n'; return 1; }

    std::vector<std::string> words;
    std::string tok;
    while (in >> tok) words.push_back(tok);

    for (const auto& line : wrap(words, width)) std::cout << line << '\n';
    return 0;
}
