```rust
#[derive(Debug, PartialEq)]
pub enum BracketError {
    UnexpectedClose { pos: usize, found: char },
    Unclosed { pos: usize, found: char },
}

pub fn check_brackets(s: &str) -> Result<(), BracketError> {
    let mut stack: Vec<(char, usize)> = Vec::new();

    for (pos, ch) in s.char_indices() {
        match ch {
            '(' | '[' | '{' => stack.push((ch, pos)),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some((open, _)) if open == expected => {}
                    _ => return Err(BracketError::UnexpectedClose { pos, found: ch }),
                }
            }
            _ => {}
        }
    }

    if let Some((open, pos)) = stack.pop() {
        return Err(BracketError::Unclosed { pos, found: open });
    }
    Ok(())
}
```

Using `char_indices` gives byte offsets that stay correct for multi-byte characters outside the brackets. A mismatched closer pops the stack first, which is fine because we abort on that error anyway. Leftover items mean an opener was never closed, and the error points at it.

```cpp
#include <cstdint>
#include <string>

// FNV-1a style rolling hash over bytes; 64-bit for low collision odds.
std::uint64_t poly_hash(const std::string& s) {
    constexpr std::uint64_t kOffset = 1469598103934665603ULL;
    constexpr std::uint64_t kPrime = 1099511628211ULL;

    std::uint64_t hash = kOffset;
    for (unsigned char c : s) {
        hash ^= static_cast<std::uint64_t>(c);
        hash *= kPrime;
    }
    return hash;
}

// Horner-style base-b hash, useful when you need a specific polynomial.
template <std::uint64_t Base>
std::uint64_t horner_hash(const std::string& s) {
    std::uint64_t h = 0;
    for (unsigned char c : s) {
        h = h * Base + static_cast<std::uint64_t>(c);
    }
    return h;
}
```

Casting through `unsigned char` before widening avoids sign extension on bytes above 127, which is the classic bug in naive hashes. Unsigned overflow is well-defined and wraps, so no UB here. `poly_hash` is good for hash maps; use `horner_hash` only when you genuinely need a polynomial with a chosen base and accept the weaker avalanche.

