```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int v) {
    Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(1); }
    n->value = v;
    n->next = head;
    return n;
}

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(const Node *head) {
    for (const Node *p = head; p; p = p->next) printf("%d ", p->value);
    putchar('\n');
}

static void free_list(Node *head) {
    while (head) { Node *n = head->next; free(head); head = n; }
}

int main(void) {
    Node *head = NULL;
    for (int i = 5; i >= 1; --i) head = push(head, i);
    print_list(head);            // 1 2 3 4 5
    head = reverse(head);
    print_list(head);            // 5 4 3 2 1
    head = reverse(NULL);        // empty list stays empty
    print_list(head);
    free_list(head);
    return 0;
}
```

The three-pointer walk keeps the next node reachable before rewiring `head->next`. Reversing `NULL` returns `NULL` safely, so the empty list is handled without a special case.

