template <typename Container>
auto max_element_opt(const Container& c)
    -> std::optional<typename Container::value_type> {
    using T = typename Container::value_type;
    if (c.empty()) return std::nullopt;
    T best = *c.begin();
    for (const auto& v : c) {
        if (v > best) best = v;
    }
    return best;
