```c
#include <stdbool.h>
#include <stdio.h>

#define RING_CAPACITY 8

typedef struct {
    int data[RING_CAPACITY];
    size_t head;
    size_t count;
} Ring;

static bool ring_push(Ring *r, int value) {
    if (r->count == RING_CAPACITY) return false;
    r->data[(r->head + r->count) % RING_CAPACITY] = value;
    r->count++;
    return true;
}

static bool ring_pop(Ring *r, int *out) {
    if (r->count == 0) return false;
    *out = r->data[r->head];
    r->head = (r->head + 1) % RING_CAPACITY;
    r->count--;
    return true;
}

int main(void) {
    Ring r = {0};
    for (int i = 0; i < RING_CAPACITY; i++) {
        if (!ring_push(&r, i * 10)) { printf("unexpected overflow\n"); return 1; }
    }
    if (ring_push(&r, 99)) { printf("overflow not detected\n"); return 1; }

    int value;
    while (ring_pop(&r, &value)) printf("%d ", value);
    printf("\n");

    if (ring_pop(&r, &value)) { printf("underflow not detected\n"); return 1; }
    return 0;
}
```

Using `head` plus `count` instead of head/tail pointers removes the classic full-vs-empty ambiguity. The modulo indexing wraps without branching. Both operations report failure via a bool so callers can react instead of silently dropping or reusing slots.

