import os
import sys


def collect_sizes(root):
    entries = []
    for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
        for name in filenames:
            path = os.path.join(dirpath, name)
            if os.path.islink(path):
                continue
            try:
                entries.append((path, os.path.getsize(path)))
            except OSError as exc:
                print(f"skipping {path}: {exc}", file=sys.stderr)
    return entries


def main():
    if len(sys.argv) != 2:
        print("usage: sizes.py <directory>", file=sys.stderr)
        sys.exit(2)
    root = sys.argv[1]
    if not os.path.isdir(root):
        print(f"error: {root} is not a directory", file=sys.stderr)
        sys.exit(1)

    entries = collect_sizes(root)
    total = sum(size for _, size in entries)
    entries.sort(key=lambda item: item[1], reverse=True)

    print(f"files: {len(entries)}")
    print(f"total: {total} bytes")
    for path, size in entries[:5]:
        print(f"{size:>12} {path}")


if __name__ == "__main__":
    main()
```

`followlinks=False` keeps the walk from descending into linked directories, and the explicit `islink` check drops linked files. `getsize` on a broken symlink or unreadable file raises `OSError`, which is caught per-file so one bad entry does not abort the scan. The total is summed before sorting so it does not depend on ordering.

