```rust
fn binary_search<T: Ord>(sorted: &[T], target: &T) -> Option<usize> {
    let mut low = 0usize;
    let mut high = sorted.len();
    while low < high {
        let mid = low + (high - low) / 2;
        match sorted[mid].cmp(target) {
            std::cmp::Ordering::Less => low = mid + 1,
            std::cmp::Ordering::Greater => high = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

fn main() {
    let empty: [i32; 0] = [];
    assert_eq!(binary_search(&empty, &3), None);

    let data = [1, 3, 3, 5, 8, 13, 21];
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &21), Some(6));
    assert_eq!(binary_search(&data, &4), None);
    assert!(binary_search(&data, &3).is_some());

    let words = ["apple", "banana", "cherry"];
    assert_eq!(binary_search(&words, &"banana"), Some(1));

    println!("all assertions passed");
}
```

