fn parse_ipv4(s: &str) -> Option<[u8; 4]> {
    if s.is_empty() {
        return None;
    }
    let mut out = [0u8; 4];
    let mut idx = 0;
    for part in s.split('.') {
        if idx == 4 {
            return None;
        }
        if part.is_empty() || part.len() > 3 || !part.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        let value: u32 = part.parse().ok()?;
        if value > 255 {
            return None;
        }
        out[idx] = value as u8;
        idx += 1;
    }
    if idx == 4 { Some(out) } else { None }
}

