```cpp
#include <cstdint>
#include <cstdio>

const std::int64_t MOD = 1000000007LL;

struct Mat {
    std::int64_t a00, a01, a10, a11;
};

Mat mul(const Mat& x, const Mat& y) {
    return Mat{
        (x.a00 * y.a00 + x.a01 * y.a10) % MOD,
        (x.a00 * y.a01 + x.a01 * y.a11) % MOD,
        (x.a10 * y.a00 + x.a11 * y.a10) % MOD,
        (x.a10 * y.a01 + x.a11 * y.a11) % MOD,
    };
}

std::int64_t fib(std::uint64_t n) {
    Mat result{1, 0, 0, 1}; // identity
    Mat base{1, 1, 1, 0};
    while (n > 0) {
        if (n & 1) result = mul(result, base);
        base = mul(base, base);
        n >>= 1;
    }
    return result.a01; // F(n)
}

int main() {
    std::printf("%lld\n", static_cast<long long>(fib(0)));  // 0
    std::printf("%lld\n", static_cast<long long>(fib(1)));  // 1
    std::printf("%lld\n", static_cast<long long>(fib(10))); // 55
    std::printf("%lld\n", static_cast<long long>(fib(50))); // 12586269025 % MOD = 586268941
    return 0;
}
```

Uses the [[1,1],[1,0]]^n identity: the top-right entry equals F(n). Products stay under 2^63 since every factor is below 1e9+7, so no overflow before the modulo. Binary exponentiation keeps it O(log n) even for n up to 1e18.

```rust
use std::collections::HashMap;

pub struct LruCache {
    cap: usize,
    map: HashMap<u32, (u64, u64)>, // key -> (value, recency tick)
    tick: u64,
}

impl LruCache {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache { cap, map: HashMap::new(), tick: 0 }
    }

    pub fn get(&mut self, key: u32) -> Option<u64> {
        self.tick += 1;
        match self.map.get_mut(&key) {
            Some(entry) => {
                entry.1 = self.tick;
                Some(entry.0)
            }
            None => None,
        }
    }

    pub fn put(&mut self, key: u32, value: u64) {
        self.tick += 1;
        if self.map.contains_key(&key) {
            self.map.insert(key, (value, self.tick));
            return;
        }
        if self.map.len() == self.cap {
            if let Some((&victim, _)) = self.map.iter().min_by_key(|(_, &(_, t))| t) {
                self.map.remove(&victim);
            }
        }
        self.map.insert(key, (value, self.tick));
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 10);
    c.put(2, 20);
    assert_eq!(c.get(1), Some(10));
    c.put(3, 30);          // evicts 2 (least recently used)
    assert_eq!(c.get(2), None);
    assert_eq!(c.get(1), Some(10));
    assert_eq!(c.get(3), Some(30));
    println!("ok");
}
```

Uses a monotonic recency tick instead of a linked list: each `get`/`put` stamps the entry, and eviction scans for the smallest tick. Correct for the fixed capacity; the scan is O(cap) per eviction, which is fine for small caches and far simpler than a hand-rolled intrusive list.

