#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <string>

std::size_t count_code_points(const std::string& s) {
    std::size_t count = 0;
    for (std::size_t i = 0; i < s.size(); ) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        std::size_t len;
        if (c < 0x80)            len = 1;
        else if ((c & 0xE0) == 0xC0) len = 2;
        else if ((c & 0xF0) == 0xE0) len = 3;
        else if ((c & 0xF8) == 0xF0) len = 4;
        else                     len = 1; // invalid lead byte, count as one
        if (i + len > s.size()) len = 1; // truncated sequence
        i += len;
        ++count;
    }
    return count;
}

int main() {
    std::printf("%zu\n", count_code_points(""));                    // 0
    std::printf("%zu\n", count_code_points("abc"));               // 3
    std::printf("%zu\n", count_code_points("\xE4\xBD\xA0\xE5\xA5\xBD")); // 2
    std::printf("%zu\n", count_code_points("\xF0\x9F\x98\x80")); // 1
    return 0;
}
