#include <iostream>
#include <string>

bool is_palindrome(const std::string& s) {
    std::size_t i = 0, j = s.size();
    while (i < j) {
        if (i == j) break;
        --j;
        if (i >= j) break;
        if (s[i] != s[j]) return false;
        ++i;
    }
    return true;
}

int main() {
    std::cout << std::boolalpha
              << is_palindrome("racecar") << '\n'   // true
              << is_palindrome("hello") << '\n'     // false
              << is_palindrome("") << '\n'          // true
              << is_palindrome("ab") << '\n';       // false
}
```

The two indices walk toward each other; any mismatch returns `false` immediately. `std::size_t` avoids signed/unsigned warnings, and the `i >= j` guard prevents over-reading on even-length strings.

```cpp
#include <iostream>
#include <vector>

int first_index(const std::vector<int>& a, int target) {
    int lo = 0, hi = static_cast<int>(a.size()) - 1, found = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) {
            found = mid;
            hi = mid - 1;   // keep searching left
        } else if (a[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return found;
}

int main() {
    std::vector<int> a = {1, 2, 2, 2, 3, 5};
    std::cout << first_index(a, 2) << '\n';   // 1
    std::cout << first_index(a, 4) << '\n';   // -1
    std::cout << first_index({}, 7) << '\n';  // -1
}
```

Instead of returning on the first hit, we record it and keep halving left (`hi = mid - 1`), which lands on the leftmost duplicate. `lo + (hi - lo) / 2` avoids overflow for large index ranges.

```rust
fn longest_valid(s: &str) -> usize {
    let bytes = s.as_bytes();
    let mut stack: Vec<usize> = vec![usize::MAX]; // sentinel base index
    let mut best = 0usize;
    for (i, &b) in bytes.iter().enumerate() {
        match b {
            b'(' => stack.push(i),
            b')' => {
                stack.pop();
                if stack.is_empty() {
                    stack.push(i); // this ')' is a new base
                } else {
                    best = best.max(i - stack[stack.len() - 1]);
                }
            }
            _ => {}
        }
    }
    best
}

fn main() {
    assert_eq!(longest_valid("(()"), 2);
    assert_eq!(longest_valid(")()())"), 4);
    assert_eq!(longest_valid(""), 0);
    println!("ok");
}
```

The stack stores indices of unmatched `(`; the sentinel `usize::MAX` gives a base for length math. When an unmatched `)` empties the stack, it becomes the new base. Each valid run length is `i - stack.top()`, tracked in `best`.

```rust
fn fib(n: u32) -> u128 {
    let (mut a, mut b) = (0u128, 1u128);
    for _ in 0..n {
        let next = a.checked_add(b).expect("fib overflowed u128");
        a = b;
        b = next;
    }
    a
}

fn main() {
    println!("{}", fib(0));    // 0
    println!("{}", fib(1));    // 1
    println!("{}", fib(10));   // 55
    println!("{}", fib(93));   // 12200160415121876738
}
```

An iterative loop keeps memory O(1). `u128` holds Fibonacci values up to `fib(186)`; `checked_add` turns overflow into a clear panic instead of silent wrap, which matters if a caller pushes `n` higher.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int v) {
    Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(1); }
    n->value = v;
    n->next = head;
    return n;
}

static void print(Node *head) {
    for (; head; head = head->next) printf("%d ", head->value);
    putchar('\n');
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 1; i <= 4; i++) list = push(list, i);
    print(list);            /* 4 3 2 1 */
    list = reverse(list);
    print(list);            /* 1 2 3 4 */
    free_list(list);
    return 0;
}
```

The three-pointer dance rewires each `next` before advancing. The empty list and single-node cases fall out naturally because the loop never runs and `prev` starts as `NULL`. `free_list` walks the reversed list to avoid leaking nodes.

