void reverse(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    for (size_t i = 0, j = len; i < j && j > 0; i++, j--) {
        char tmp = s[i];
        s[i] = s[j - 1];
        s[j - 1] = tmp;
    }
