```cpp
#include <array>
#include <cstddef>
#include <optional>
#include <iostream>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int v) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int v = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << '\n';
    std::cout << *rb.pop() << ' ' << *rb.pop() << '\n';
    rb.push(5);
    std::cout << rb.size() << '\n';
}
```

`push` returns `false` when full instead of overwriting, and `pop` returns `std::optional` so emptying the buffer is a normal case rather than undefined behaviour.

