def is_valid_isbn10(s):
    cleaned = s.replace("-", "").replace(" ", "").upper()
    if len(cleaned) != 10:
        return False
    total = 0
    for i, ch in enumerate(cleaned):
        if ch == "X":
            if i != 9:
                return False
            total += 10
        elif ch.isdigit():
            total += int(ch) * (10 - i)
        else:
            return False
    return total % 11 == 0


