```cpp
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;                            // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high;  // min-heap
    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);

        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        if (low.size() == high.size())
            std::cout << (low.top() + high.top()) / 2.0 << '\n';
        else
            std::cout << low.top() << '\n';
    }
    return 0;
}
```

Two heaps keep the lower half in a max-heap and the upper half in a min-heap; rebalancing after each insert keeps their sizes within one. Even counts average the two middle values as a double, odd counts read the top of the lower heap. Empty input prints nothing.

```rust
fn merge(mut intervals: Vec<(i64, i64)>) -> Vec<(i64, i64)> {
    intervals.sort_unstable();
    let mut out: Vec<(i64, i64)> = Vec::new();
    for (s, e) in intervals {
        match out.last_mut() {
            Some(last) if s <= last.1 => {
                if e > last.1 {
                    last.1 = e;
                }
            }
            _ => out.push((s, e)),
        }
    }
    out
}

fn main() {
    println!("{:?}", merge(vec![(1, 3), (2, 6), (8, 10), (15, 18)]));
    println!("{:?}", merge(vec![(5, 5), (5, 5)]));
    println!("{:?}", merge(vec![]));
    println!("{:?}", merge(vec![(3, 1), (0, 4)]));
}
```

Sorting by start makes a single pass enough: each interval either extends the last merged one or starts a new one. Empty input yields an empty vector, and the merge handles touching endpoints (`s <= last.1`) as overlap.

```cpp
#include <algorithm>
#include <iostream>
#include <vector>

std::vector<int> merge_unique(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());

    std::size_t i = 0, j = 0;
    while (i < a.size() || j < b.size()) {
        int value;
        if (j >= b.size() || (i < a.size() && a[i] <= b[j])) {
            value = a[i++];
        } else {
            value = b[j++];
        }
        if (out.empty() || out.back() != value) {
            out.push_back(value);
        }
    }
    return out;
}

int main() {
    std::vector<int> a{1, 3, 3, 5};
    std::vector<int> b{2, 3, 6};
    for (int v : merge_unique(a, b)) std::cout << v << ' ';
    std::cout << '\n';  // 1 2 3 5 6

    std::vector<int> empty;
    for (int v : merge_unique(empty, empty)) std::cout << v << ' ';
    std::cout << '\n';  // blank line
    return 0;
}
