from datetime import date, datetime


def weekday_name(iso: str) -> str | None:
    """Return the weekday name for an ISO-8601 date, or None if invalid."""
    if not isinstance(iso, str):
        return None
    text = iso.strip()
    if not text:
        return None
    # Accept both plain dates and full timestamps by replacing trailing Z.
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        try:
            parsed = date.fromisoformat(text[:10])
        except ValueError:
            return None
    return parsed.strftime("%A")


