#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), size_(0) {}

    bool push(double value) {
        if (data_.empty() || size_ == data_.size()) return false;
        data_[(head_ + size_) % data_.size()] = value;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) return std::nullopt;
        double value = data_[head_];
        head_ = (head_ + 1) % data_.size();
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<double> data_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    rb.push(1.5); rb.push(2.5); rb.push(3.5);
    std::cout << rb.push(4.5) << '\n';   // 0 (full)
    std::cout << *rb.pop() << '\n';      // 1.5
    rb.push(4.5);
    std::cout << *rb.pop() << '\n';      // 2.5
    std::cout << rb.size() << '\n';      // 2
    return 0;
}
