long long max_subarray_sum(const std::vector<int>& a) {
    if (a.empty()) return 0;
    long long best = a[0];
    long long cur = a[0];
    for (std::size_t i = 1; i < a.size(); ++i) {
        cur = std::max<long long>(a[i], cur + a[i]);
