constexpr std::int64_t MOD = 1000000007LL;

// returns {F(n), F(n+1)} mod MOD
std::pair<std::int64_t, std::int64_t> fib_pair(std::int64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    std::int64_t c = (a * ((2 * b % MOD - a + MOD) % MOD)) % MOD;
    std::int64_t d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1) {
        return {d, (c + d) % MOD};
    }
    return {c, d};
}

std::int64_t fib(std::int64_t n) {
    return fib_pair(n).first;
}

int main() {
    for (std::int64_t n : {0LL, 1LL, 2LL, 10LL, 50LL, 90LL}) {
        std::cout << "F(" << n << ") = " << fib(n) << '\n';
    }
    return 0;
