import hashlib
import os
import sys
from collections import defaultdict
from pathlib import Path

CHUNK = 1 << 20


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as fh:
        while True:
            block = fh.read(CHUNK)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()


def find_duplicates(root: Path) -> list[list[Path]]:
    by_size: dict[int, list[Path]] = defaultdict(list)
    for dirpath, _dirs, files in os.walk(root):
        for name in files:
            p = Path(dirpath) / name
            try:
                size = p.stat().st_size
            except OSError as exc:
                print(f"skipping {p}: {exc}", file=sys.stderr)
                continue
            if size > 0:
                by_size[size].append(p)

    groups: list[list[Path]] = []
    for candidates in by_size.values():
        if len(candidates) < 2:
            continue
        by_hash: dict[str, list[Path]] = defaultdict(list)
        for p in candidates:
            try:
                by_hash[sha256_file(p)].append(p)
            except OSError as exc:
                print(f"skipping {p}: {exc}", file=sys.stderr)
        groups.extend(paths for paths in by_hash.values() if len(paths) > 1)
    return groups


if __name__ == "__main__":
    target = Path(sys.argv[1] if len(sys.argv) > 1 else ".")
    duplicates = find_duplicates(target)
    if not duplicates:
        print("no duplicates found")
    for group in duplicates:
        print("duplicates:")
        for p in group:
            print(f"  {p}")
