bool is_palindrome(const std::string& s) {
    std::size_t left = 0;
    std::size_t right = s.size();
    while (left < right) {
        unsigned char a = static_cast<unsigned char>(s[left]);
        unsigned char b = static_cast<unsigned char>(s[right - 1]);
        if (!std::isalnum(a)) {
            ++left;
            continue;
        }
        if (!std::isalnum(b)) {
            --right;
            continue;
        }
        if (std::tolower(a) != std::tolower(b)) {
            return false;
        }
        ++left;
        --right;
    }
    return true;
}

int main() {
    std::cout << is_palindrome("A man, a plan, a canal: Panama") << "\n";  // 1
    std::cout << is_palindrome("hello") << "\n";                           // 0
    std::cout << is_palindrome("") << "\n";                                // 1
    return 0;
}
