def single_number(nums):
    """Return the element appearing once; others appear twice.

    Uses XOR: x ^ x == 0 and x ^ 0 == x, so pairs cancel out.
    Raises ValueError if the input cannot contain exactly one singleton.
    """
    if not isinstance(nums, (list, tuple)):
        raise TypeError("nums must be a list or tuple")
    if len(nums) == 0:
        raise ValueError("nums is empty")
    if len(nums) % 2 == 0:
        raise ValueError("length must be odd for exactly one singleton")
    result = 0
    for n in nums:
        if not isinstance(n, int):
            raise TypeError(f"non-integer element: {n!r}")
        result ^= n
    return result


if __name__ == "__main__":
    assert single_number([2, 2, 1]) == 1
    assert single_number([4, 1, 2, 1, 2]) == 4
    assert single_number([7]) == 7
    assert single_number([-3, -3, 5]) == 5
    for bad in ([], [1, 2], "abc"):
        try:
            single_number(bad)
        except (ValueError, TypeError):
            pass
        else:
            raise AssertionError(f"expected rejection of {bad!r}")
    print("all checks passed")
