#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity), buf_{} {}

    bool push(int value) {
        if (size_ == cap_) return false;
        buf_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == cap_; }
    std::size_t size() const { return size_; }

private:
    std::size_t cap_;
    std::array<int, 8> buf_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;                 // full, must reject
    if (!rb.full() || rb.size() != 3) return 1;
    for (int expected : {1, 2, 3}) {
        auto v = rb.pop();
        if (!v || *v != expected) return 1;
    }
    if (!rb.empty()) return 1;
    if (rb.pop().has_value()) return 1;       // empty, must fail

    rb.push(9);
    rb.pop();
    rb.push(10);                              // wrap-around
    auto w = rb.pop();
    if (!w || *w != 10) return 1;

    std::cout << "ring buffer ok\n";
    return 0;
}
