/// Iterative Fibonacci. Returns None if the result would overflow u128.
pub fn fibonacci(n: u32) -> Option<u128> {
    let (mut a, mut b) = (0u128, 1u128);
    for _ in 0..n {
        b = a.checked_add(b)?;
        a = b - a;
    }
    Some(a)
}

fn main() {
    assert_eq!(fibonacci(0), Some(0));
    assert_eq!(fibonacci(1), Some(1));
    assert_eq!(fibonacci(10), Some(55));
    assert_eq!(fibonacci(93), Some(12200160415121876738u128));
    assert_eq!(fibonacci(187), None); // overflows u128

    // Exhaustive sanity: each term is the sum of the previous two.
    let mut prev: Option<u128> = None;
    for n in 0..92 {
        let cur = fibonacci(n).expect("must fit");
        if let Some(p) = prev {
            assert!(cur >= p);
        }
        prev = Some(cur);
    }
    println!("fibonacci checks passed");
}
