use std::collections::HashMap;
use std::io::{self, Read};

fn top_words(text: &str, k: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split(|c: char| !c.is_alphanumeric()) {
        if word.is_empty() {
            continue;
        }
        *counts.entry(word.to_lowercase()).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Ties broken alphabetically so output is deterministic.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(k);
    pairs
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("read stdin");

    let sample = "the quick fox the lazy dog the fox";
    let top = top_words(sample, 3);
    assert_eq!(top[0], ("the".to_string(), 3));
    assert_eq!(top[1], ("fox".to_string(), 2));
    assert_eq!(top.len(), 3);
    assert!(top_words("", 3).is_empty());
    assert!(top_words("!!! ###", 3).is_empty());

    let top = top_words(&input, 3);
    if top.is_empty() {
        println!("no words found");
    } else {
        for (word, count) in top {
