#include <iostream>
#include <map>
#include <sstream>
#include <string>

std::map<std::string, std::string> parse(const std::string& line) {
    std::map<std::string, std::string> out;
    std::istringstream stream(line);
    std::string token;
    while (std::getline(stream, token, ';')) {
        // trim surrounding spaces
        const auto begin = token.find_first_not_of(" \t");
        if (begin == std::string::npos) continue;
        const auto end = token.find_last_not_of(" \t");
        token = token.substr(begin, end - begin + 1);

        const auto eq = token.find('=');
        if (eq == std::string::npos) continue; // no '=' -> skip
        std::string key = token.substr(0, eq);
        std::string value = token.substr(eq + 1);
        if (key.empty()) continue;
        out[key] = value; // last assignment wins
    }
    return out;
}

int main() {
    const std::string input =
        "b=2; a=1 ; c=; a=99; broken; =nokey; d=has space ";
    auto parsed = parse(input);

    if (parsed.size() != 5) { std::cerr << "bad size\n"; return 1; }
    if (parsed["a"] != "99") return 1;
    if (parsed["b"] != "2") return 1;
    if (parsed["c"] != "") return 1;        // empty value kept
    if (parsed["d"] != "has space") return 1;

    for (const auto& [key, value] : parsed) {
        std::cout << key << " -> " << value << '\n';
    }
    return 0;
}
