fn parse_i64(s: &str) -> Option<i64> {
    let t = s.trim();
    if t.is_empty() {
        return None;
    }
    let (sign, digits) = match t.as_bytes()[0] {
        b'+' => (1i64, &t[1..]),
        b'-' => (-1i64, &t[1..]),
        _ => (1i64, t),
    };
    if digits.is_empty() || digits.is_empty() && sign == -1 {
        return None;
    }
    t.parse::<i64>().ok()
}

fn main() {
    assert_eq!(parse_i64("  -42 "), Some(-42));
    assert_eq!(parse_i64("123"), Some(123));
    assert_eq!(parse_i64(""), None);
    assert_eq!(parse_i64("12x"), None);
    assert_eq!(parse_i64("9999999999999999999"), None);
    println!("ok");
}
```
`str::parse` already rejects overflow and bad characters, so the wrapper only adds trim and sign validation. The redundant branch on `digits.is_empty() && sign == -1` is unnecessary; simplify to `if digits.is_empty() { return None; }`.

