bool is_balanced(const std::string& s) {
    std::stack<char> open;
    std::unordered_map<char, char> pairs = {{')', '('}, {']', '['}, {'}', '{'}};

    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            open.push(c);
        } else if (pairs.count(c)) {
            if (open.empty() || open.top() != pairs[c]) {
                return false;
            }
            open.pop();
        }
    }
    return open.empty();
}
