/* Returns true on success. Sets *out; errno is left as ERANGE on overflow,
   EINVAL when the string is empty or has trailing non-numeric characters. */
bool parse_long(const char *text, long *out) {
    if (text == NULL || *text == '\0') {
        errno = EINVAL;
        return false;
    }

    char *end = NULL;
    errno = 0;
    long value = strtol(text, &end, 10);

    if (errno == ERANGE || end == text || *end != '\0') {
        if (errno != ERANGE) {
            errno = EINVAL;
        }
        return false;
    }

    *out = value;
    return true;
}
