#include <cassert>
#include <cstddef>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse_list(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main() {
    assert(reverse_list(nullptr) == nullptr);

    Node a(1), b(2), c(3);
    a.next = &b;
    b.next = &c;
    Node* r = reverse_list(&a);
    assert(r == &c && c.next == &b && b.next == &a && a.next == nullptr);

    Node solo(7);
    assert(reverse_list(&solo) == &solo && solo.next == nullptr);
    return 0;
}
```

Walks the list once, relinking each node to the previous one; a null head and a single-node list are both handled. O(n) time, O(1) extra space. Stack-allocated nodes are fine for the test but heap allocation would be more realistic in production.

