```rust
fn is_palindrome(s: &str) -> bool {
    let chars: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .map(|c| c.to_ascii_lowercase())
        .collect();
    let mut i = 0usize;
    let mut j = chars.len();
    while i < j {
        j -= 1;
        if chars[i] != chars[j] {
            return false;
        }
        i += 1;
    }
    true
}

fn main() {
    assert!(is_palindrome("A man, a plan, a canal: Panama"));
    assert!(is_palindrome(""));
    assert!(is_palindrome("!!"));
    assert!(!is_palindrome("race a car"));
    println!("ok");
}
```

Filtering then two-pointer scanning keeps it clear and avoids index gymnastics over `chars()`. `is_alphanumeric` handles unicode letters, while `to_ascii_lowercase` only folds ASCII — fine for English input; for full unicode case folding you'd use a dedicated crate.

