use std::collections::HashMap;

fn two_sum(nums: &[i64], target: i64) -> Option<(usize, usize)> {
    let mut seen: HashMap<i64, usize> = HashMap::new();
    for (i, &n) in nums.iter().enumerate() {
        if let Some(&j) = seen.get(&(target - n)) {
            return Some((j, i));
        }
        seen.insert(n, i);
    }
    None
}

fn main() {
    assert_eq!(two_sum(&[2, 7, 11, 15], 9), Some((0, 1)));
    assert_eq!(two_sum(&[3, 3], 6), Some((0, 1)));
    assert_eq!(two_sum(&[1, 2, 3], 99), None);
    assert_eq!(two_sum(&[], 0), None);
    println!("ok");
}
```

One pass with a hash map: before inserting each value, check whether its complement was already seen, so an element can't pair with itself. Returns the first valid pair found; `None` for empty input or no solution.

```c
#include <errno.h>
#include <limits.h>
#include <stdio.h>

int parse_uint(const char *s, unsigned long *out) {
    if (s == NULL || *s == '\0') {
        return -1;
    }
    unsigned long value = 0;
    for (const char *p = s; *p != '\0'; ++p) {
        if (*p < '0' || *p > '9') {
            return -1; /* trailing garbage or sign */
        }
        unsigned digit = (unsigned)(*p - '0');
        if (value > (ULONG_MAX - digit) / 10) {
            errno = ERANGE;
            return -1; /* overflow */
        }
        value = value * 10 + digit;
    }
    *out = value;
    return 0;
}

int main(void) {
    unsigned long v;
    if (parse_uint("4294967296", &v) != 0) {
        printf("rejected large value\n");
    }
    if (parse_uint("42", &v) == 0) {
        printf("parsed %lu\n", v);
    }
    if (parse_uint("12x", &v) != 0) {
        printf("rejected trailing garbage\n");
    }
    return 0;
}
```

Rejects empty strings, leading signs, non-digit characters and values above `ULONG_MAX` by checking `value > (ULONG_MAX - digit) / 10` before multiplying, which avoids overflow in the check itself.

