def rle_encode(text: str) -> str:
    if not text:
        return ""
    out = []
    prev = text[0]
    count = 1
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(f"{count}{prev}")
            prev, count = ch, 1
    out.append(f"{count}{prev}")
    return "".join(out)


def rle_decode(encoded: str) -> str:
    out = []
    i = 0
    while i < len(encoded):
        j = i
        while j < len(encoded) and encoded[j].isdigit():
            j += 1
        if j == i or j == len(encoded):
            raise ValueError(f"malformed encoding at index {i}: {encoded!r}")
        out.append(encoded[j] * int(encoded[i:j]))
        i = j + 1
    return "".join(out)


if __name__ == "__main__":
    for s in ["aaabbbcccd", "", "w", "你好你好"]:
        enc = rle_encode(s)
        assert rle_decode(enc) == s
        print(repr(s), "->", repr(enc))
