#include <cstddef>
#include <iostream>
#include <string>

std::string longestPalindrome(const std::string& s) {
    if (s.empty()) return "";
    std::size_t bestStart = 0, bestLen = 1;
    auto expand = [&](std::size_t left, std::size_t right) {
        while (left != std::string::npos && right < s.size() && s[left] == s[right]) {
            if (right - left + 1 > bestLen) {
                bestLen = right - left + 1;
                bestStart = left;
            }
            left = (left == 0) ? std::string::npos : left - 1;
            ++right;
        }
    };
    for (std::size_t i = 0; i < s.size(); ++i) {
        expand(i, i);       // odd length
        expand(i, i + 1);   // even length
    }
    return s.substr(bestStart, bestLen);
}

int main() {
    std::string tests[] = {"", "a", "bb", "babad", "cbbd", "forgeeksskeegfor", "abacdfgdcaba"};
    for (const auto& t : tests)
        std::cout << '[' << t << "] -> [" << longestPalindrome(t) << "]\n";
