#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity) {}

    bool push(int value) {
        if (size_ == cap_) return false;
        data_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == cap_; }
    std::size_t size() const { return size_; }

private:
    static constexpr std::size_t kMax = 64;
    std::array<int, kMax> data_{};
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    for (int v : {1, 2, 3}) std::cout << "push " << v << ": " << rb.push(v) << '\n';
    std::cout << "push 4 (full): " << rb.push(4) << '\n';
    while (auto v = rb.pop()) std::cout << "pop: " << *v << '\n';
    std::cout << "pop empty: " << rb.pop().has_value() << '\n';
    if (rb.empty()) std::cout << "buffer empty\n";
    return 0;
}
