```rust
fn solve_queens(n: usize) -> usize {
    fn backtrack(row: usize, n: usize, cols: &mut Vec<bool>, d1: &mut Vec<bool>, d2: &mut Vec<bool>) -> usize {
        if row == n {
            return 1;
        }
        let mut count = 0;
        for col in 0..n {
            let a = row + col;
            let b = col + n - row; // offset so index stays non-negative
            if cols[col] || d1[a] || d2[b] {
                continue;
            }
            cols[col] = true;
            d1[a] = true;
            d2[b] = true;
            count += backtrack(row + 1, n, cols, d1, d2);
            cols[col] = false;
            d1[a] = false;
            d2[b] = false;
        }
        count
    }

    if n == 0 {
        return 1;
    }
    let mut cols = vec![false; n];
    let mut d1 = vec![false; 2 * n];
    let mut d2 = vec![false; 2 * n];
    backtrack(0, n, &mut cols, &mut d1, &mut d2)
}

fn main() {
    for n in 1..=8 {
        println!("n={} solutions={}", n, solve_queens(n));
    }
}
