        {"anything", ""},      /* -> 0, guard */
    };
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        printf("%s in \"%s\" -> %zu\n",
               cases[i][1], cases[i][0],
               count_occurrences(cases[i][0], cases[i][1]));
    }
    return 0;
}
