```cpp
#include <iostream>
#include <queue>
#include <vector>

class RunningMedian {
    std::priority_queue<int> low;                             // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap
public:
    void add(int x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);
        // rebalance: sizes differ by at most 1, low may hold one extra
        if (low.size() > high.size() + 1) { high.push(low.top()); low.pop(); }
        else if (high.size() > low.size()) { low.push(high.top()); high.pop(); }
    }
    double median() const {
        if (low.size() == high.size())
            return (low.top() + high.top()) / 2.0;
        return static_cast<double>(low.top());
    }
};

int main() {
    RunningMedian rm;
    int x;
    while (std::cin >> x) {
        rm.add(x);
        std::cout << rm.median() << '\n';
    }
    return 0;
}
```

Two heaps keep the lower half in a max-heap and the upper half in a min-heap; after each insert the sizes are rebalanced so the median is either the top of the larger heap or the average of both tops. Runs in O(log n) per element. Empty input simply produces no output.

