```c
#include <stdio.h>

static int bsearch_int(const int *arr, size_t n, int target) {
    size_t lo = 0, hi = n; /* [lo, hi) half-open interval */
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2; /* avoids overflow */
        if (arr[mid] == target) return (int)mid;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return -1;
}

int main(void) {
    const int data[] = {1, 3, 5, 7, 9, 11, 13};
    size_t n = sizeof data / sizeof data[0];
    int targets[] = {7, 1, 13, 4, -5};
    for (size_t i = 0; i < sizeof targets / sizeof targets[0]; i++) {
        printf("%d -> %d\n", targets[i], bsearch_int(data, n, targets[i]));
    }
    return 0;
}
```

The half-open interval `[lo, hi)` keeps the loop terminating, and `lo + (hi - lo) / 2` prevents signed overflow that `(lo + hi) / 2` could hit on very large indices. It returns the exact index on a hit and -1 when the target is absent, as shown for `7`, `1`, `13`, present values and `4`, `-5`, absent ones.

