// top_words.rs
use std::collections::HashMap;

/// Count whitespace-separated words case-insensitively and return the
/// `n` most frequent as `(word, count)` pairs, highest count first.
/// Ties are broken alphabetically for a stable result.
pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();

    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '\'')
            .flat_map(|c| c.to_lowercase())
            .collect();
        if word.is_empty() {
            continue;
        }
        *counts.entry(word).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the quick fox the lazy dog THE fox";
    for (word, count) in top_words(text, 3) {
        println!("{word}: {count}");
    }
}
```

Punctuation is stripped, case is normalized, empty tokens from pure punctuation are skipped, and the alphabetical tiebreak makes output deterministic.

