    while (1) {
        ssize_t n = getline(&buf, &buflen, fp);
        if (n < 0) break;  /* EOF or error */

        /* strip a single trailing newline if present */
        if (n > 0 && buf[n - 1] == '\n') {
            buf[--n] = '\0';
        }

        if (count == cap) {
            size_t newcap = cap ? cap * 2 : 16;
            char **tmp = realloc(lines, newcap * sizeof(*lines));
            if (!tmp) { perror("realloc"); return 1; }
            lines = tmp;
            cap = newcap;
        }

        lines[count] = malloc((size_t)n + 1);
        if (!lines[count]) { perror("malloc"); return 1; }
        memcpy(lines[count], buf, (size_t)n + 1);
        count++;
    }

    for (size_t i = count; i-- > 0; ) {
        puts(lines[i]);
        free(lines[i]);
    }

    free(lines);
    free(buf);
    fclose(fp);
    return 0;
}
```

`getline` grows `buf` as needed so line length is unbounded. The `lines` array doubles in capacity to keep appends amortized O(1).

