// stats_csv.rs
// Compute mean and population standard deviation of the column named by the
// command-line argument, using only the standard library.
use std::env;
use std::fs;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("usage: {} FILE COLUMN", args[0]);
        process::exit(2);
    }
    let (path, column) = (&args[1], &args[2]);

    let data = match fs::read_to_string(path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error reading {path}: {e}");
            process::exit(1);
        }
    };

    let mut lines = data.lines();
    let header: Vec<&str> = match lines.next() {
        Some(h) => h.split(',').map(str::trim).collect(),
        None => {
            eprintln!("empty file");
            process::exit(1);
        }
    };

    let idx = match header.iter().position(|col| col.eq_ignore_ascii_case(column)) {
        Some(i) => i,
        None => {
            eprintln!("column '{column}' not found; available: {header:?}");
            process::exit(1);
        }
    };

    let mut n = 0u64;
    let mut sum = 0.0f64;
    let mut sum_sq = 0.0f64;

    for (lineno, line) in lines.enumerate() {
        let fields: Vec<&str> = line.split(',').collect();
        match fields.get(idx).map(|v| v.trim().parse::<f64>()) {
            Some(Ok(v)) => {
                n += 1;
                sum += v;
                sum_sq += v * v;
            }
            Some(Err(_)) => eprintln!("skipping row {}: not a number", lineno + 2),
            None => eprintln!("skipping row {}: missing field", lineno + 2),
        }
    }

    if n == 0 {
        eprintln!("no numeric values found in column '{column}'");
        process::exit(1);
    }

    let mean = sum / n as f64;
    let variance = (sum_sq / n as f64) - mean * mean;
    let stddev = variance.max(0.0).sqrt();  // clamp tiny negatives from rounding

    println!("count = {n}");
    println!("mean  = {mean:.6}");
    println!("stddev = {stddev:.6}");
}
```

Bad rows are reported to stderr and skipped rather than aborting the run. The variance is clamped at zero so floating-point rounding can't push it negative before `sqrt`.

```cpp
// blocking_queue.hpp
// A fixed-capacity, thread-safe queue. push() blocks while full,
// pop() blocks while empty; close() unblocks all waiters.
#pragma once

#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>

template <typename T>
class BlockingQueue {
public:
    explicit BlockingQueue(std::size_t capacity)
        : capacity_(capacity), closed_(false) {
        if (capacity == 0)
            throw std::invalid_argument("capacity must be > 0");
    }

    // Blocks until space is available or the queue is closed.
    // Returns false if the queue was closed before the item was enqueued.
    bool push(T value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [this] { return closed_ || queue_.size() < capacity_; });
        if (closed_)
            return false;
        queue_.push(std::move(value));
        not_empty_.notify_one();
        return true;
    }

    // Blocks until an item is available or the queue is closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock, [this] { return closed_ || !queue_.empty(); });
        if (queue_.empty())
            return std::nullopt;  // closed and empty
        T value = std::move(queue_.front());
        queue_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.size();
    }

private:
    std::size_t capacity_;
    bool closed_;
    std::queue<T> queue_;
    mutable std::mutex mutex_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
};
```

Predicates on the condition variables guard against spurious wakeups. `close()` sets the flag under the lock, then notifies both groups so no thread stays blocked.

