```python
def rle_encode(text):
    """Encode runs as <count><char>, e.g. 'aaabb' -> '3a2b'."""
    if not text:
        return ""
    parts = []
    count = 1
    for i in range(1, len(text)):
        if text[i] == text[i - 1]:
            count += 1
        else:
            parts.append(f"{count}{text[i - 1]}")
            count = 1
    parts.append(f"{count}{text[-1]}")
    return "".join(parts)


def rle_decode(encoded):
    """Decode '<count><char>' runs. Raises ValueError on malformed input."""
    out = []
    digits = []
    for ch in encoded:
        if ch.isdigit():
            digits.append(ch)
        else:
            if not digits:
                raise ValueError(f"missing count before {ch!r}")
            out.append(ch * int("".join(digits)))
            digits = []
    if digits:
        raise ValueError("trailing count with no character")
    return "".join(out)


if __name__ == "__main__":
    for s in ["", "a", "aaabb", "abcd", "wwwwwwwwwwww", "z"]:
        assert rle_decode(rle_encode(s)) == s, s
    assert rle_encode("aaabb") == "3a2b"
    assert rle_encode("") == ""
    try:
        rle_decode("12")
    except ValueError as e:
        assert "trailing" in str(e)
    try:
        rle_decode("a")
    except ValueError as e:
        assert "missing" in str(e)
    print("ok")
