/* Parse a whole string as long. Returns true on success, false on any
 * error (empty input, trailing junk, overflow). On success *out is set. */
bool parse_long(const char *text, long *out) {
    if (text == NULL || *text == '\0') return false;

    char *end = NULL;
    errno = 0;
    long value = strtol(text, &end, 10);

    if (end == text) return false;          /* no digits consumed */
    if (*end != '\0') return false;         /* trailing characters   */
    if (errno == ERANGE && (value == LONG_MAX || value == LONG_MIN))
        return false;                        /* overflow/underflow   */

    *out = value;
    return true;
}

int main(void) {
    const char *cases[] = {"42", "-7", "", "12x", "99999999999999999999", NULL};
    for (int i = 0; cases[i] != NULL; i++) {
        long v = 0;
        bool ok = parse_long(cases[i], &v);
        if (ok) printf("%-22s -> %ld\n", cases[i], v);
        else    printf("%-22s -> error\n", cases[i]);
    }
    return 0;
}
