use std::env;
use std::fs::File;
use std::io::{self, BufReader, Read};
use std::process::ExitCode;

/// Sum every byte of `path` modulo 2^32. Reads in chunks so large files
/// do not need to fit in memory.
fn sum_bytes(path: &str) -> io::Result<u64> {
    let file = File::open(path)?;
    let mut reader = BufReader::new(file);
    let mut buf = [0u8; 64 * 1024];
    let mut total: u64 = 0;
    loop {
        let n = reader.read(&mut buf)?;
        if n == 0 {
            break;
        }
        for &byte in &buf[..n] {
            total = total.wrapping_add(byte as u64);
        }
    }
    Ok(total)
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("usage: sumcheck <file>");
        return ExitCode::FAILURE;
    }
    match sum_bytes(&args[1]) {
        Ok(total) => {
            println!("{:08x}", total as u32);
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("error: {}", e);
            ExitCode::FAILURE
        }
    }
}
