constexpr std::uint64_t MOD = 1000000007ULL;

// Fast doubling: returns {F(n), F(n+1)} modulo MOD in O(log n).
std::pair<std::uint64_t, std::uint64_t> fib_pair(std::uint64_t n) {
    if (n == 0) return {0ULL, 1ULL};
    auto [a, b] = fib_pair(n >> 1);          // F(k), F(k+1)
    std::uint64_t c = a * ((2ULL * b + MOD - a) % MOD) % MOD; // F(2k)
    std::uint64_t d = (a * a + b * b) % MOD;                  // F(2k+1)
    if (n & 1ULL) return {d, (c + d) % MOD};
    return {c, d};
}

std::uint64_t fib(std::uint64_t n) { return fib_pair(n).first; }

int main() {
    std::cout << fib(0) << "\n";   // 0
    std::cout << fib(1) << "\n";   // 1
    std::cout << fib(10) << "\n";  // 55
    std::cout << fib(90) << "\n";  // 2880067194370816120 mod 1e9+7
    return 0;
}
