#include <stddef.h>
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s)
{
    if (s == NULL)
        return;
    size_t len = strlen(s);
    if (len < 2)
        return;
    for (size_t i = 0, j = len - 1; i < j; i++, j--) {
        char t = s[i];
        s[i] = s[j];
        s[j] = t;
    }
}

int main(void)
{
    char a[] = "hello";
    reverse_in_place(a);
    printf("%s\n", a);              /* olleh */

    char b[] = "";
    reverse_in_place(b);
    printf("[%s]\n", b);            /* [] */

    char c[] = "x";
    reverse_in_place(c);
    printf("%s\n", c);              /* x */

    char d[] = "ab";                 /* even length */
    reverse_in_place(d);
    printf("%s\n", d);              /* ba */

    reverse_in_place(NULL);          /* must not crash */
    return 0;
}
```

Single pass, O(n)/O(1). `strlen` reads only up to the terminator, so embedded data after the null is untouched. A null pointer is a no-op rather than a crash.

