```cpp
#include <array>
#include <cstddef>
#include <cstdio>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity) {}

    bool push(double value) {
        if (size_ == cap_) return false;
        data_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    bool pop(double& out) {
        if (size_ == 0) return false;
        out = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }

private:
    std::array<double, 256> data_{};
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(4);
    for (double v : {1.5, 2.5, 3.5}) {
        if (!rb.push(v)) { std::puts("push failed"); return 1; }
    }
    double x = 0;
    while (rb.pop(x)) std::printf("%.1f\n", x);   /* 1.5 2.5 3.5 */
    if (rb.pop(x)) { std::puts("expected empty"); return 1; }

    RingBuffer full(256);
    for (int i = 0; i < 256; ++i)
        if (!full.push(i)) return 1;
    if (full.push(999)) { std::puts("overflow not caught"); return 1; }
    std::puts("all checks passed");
    return 0;
}
```

Capacity is capped at the `std::array` size so no dynamic allocation is needed. `push` and `pop` return `false` on overflow and underflow instead of silently dropping or corrupting data, and the modular index wraps correctly once the head advances.

