use std::collections::HashMap;

fn parse_pairs(input: &str) -> Result<HashMap<String, String>, String> {
    let mut out = HashMap::new();
    for raw in input.split(';') {
        let entry = raw.trim();
        if entry.is_empty() {
            continue;
        }
        match entry.split_once('=') {
            Some((k, v)) if !k.is_empty() => {
                out.insert(k.to_string(), v.to_string());
            }
            Some(_) => return Err(format!("empty key in {entry:?}")),
            None => return Err(format!("missing '=' in {entry:?}")),
        }
    }
    Ok(out)
}

fn main() {
    let ok = parse_pairs("a=1; b=2 ;;c=hello world").unwrap();
    assert_eq!(ok.get("a").map(String::as_str), Some("1"));
    assert_eq!(ok.get("c").map(String::as_str), Some("hello world"));
    assert!(ok.contains_key("b"));
    assert!(parse_pairs("x=1; broken").is_err());
    assert!(parse_pairs("=noKey").is_err());
    assert_eq!(parse_pairs("").unwrap().len(), 0);
    println!("all checks passed");
}
