use std::collections::HashMap;

pub fn top_words(text: &str, k: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '\'')
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(k);
    pairs
}

fn main() {
    let text = "The cat, the dog. The CAT! the bird";
    let top = top_words(text, 3);
    assert_eq!(top[0], ("the".to_string(), 4));
    assert_eq!(top[1], ("cat".to_string(), 2));
    assert_eq!(top[2], ("bird".to_string(), 1));
    assert_eq!(top_words("", 3).len(), 0);
    println!("{:?}", top);
}
