#include <limits.h>
#include <stdbool.h>
#include <stdio.h>

bool parse_int(const char *s, int *out) {
    if (s == NULL || out == NULL || *s == '\0') return false;

    bool negative = false;
    if (*s == '+' || *s == '-') {
        negative = (*s == '-');
        s++;
    }
    if (*s < '0' || *s > '9') return false;

    long acc = 0;
    while (*s >= '0' && *s <= '9') {
        acc = acc * 10 + (*s - '0');
        long bound = negative ? (long)INT_MAX + 1 : (long)INT_MAX;
        if (acc > bound) return false;
        s++;
    }
    if (*s != '\0') return false;

    *out = negative ? (int)(-acc) : (int)acc;
    return true;
}

int main(void) {
    int v;
    if (!parse_int("2147483647", &v) || v != 2147483647) { puts("fail max"); return 1; }
    if (!parse_int("-2147483648", &v) || v != INT_MIN) { puts("fail min"); return 1; }
    if (parse_int("2147483648", &v)) { puts("overflow not caught"); return 1; }
    if (parse_int("12x", &v)) { puts("trailing not caught"); return 1; }
    if (parse_int("", &v)) { puts("empty not caught"); return 1; }
    if (!parse_int("+7", &v) || v != 7) { puts("fail plus"); return 1; }
    puts("parse_int tests passed");
    return 0;
}
```
`acc` is `long` so the multiply can't overflow before the bound check. `INT_MIN` is handled via its magnitude `INT_MAX + 1`.

