PAIRS = {')': '(', ']': '[', '}': '{'}
OPEN = set('([{')


def balanced(text):
    stack = []
    quote = None
    escaped = False
    for ch in text:
        if quote is not None:
            if escaped:
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == quote:
                quote = None
            continue
        if ch in ('"', "'"):
            quote = ch
        elif ch in OPEN:
            stack.append(ch)
        elif ch in PAIRS:
            if not stack or stack.pop() != PAIRS[ch]:
                return False
    return not stack and quote is None


if __name__ == "__main__":
    assert balanced("([{}])")
    assert balanced("" )
    assert not balanced("([)]")
    assert not balanced("(")
    assert not balanced(")")
    assert balanced("foo(\"]\")bar")
    assert not balanced("foo(\"\")")
    assert not balanced("'unterminated")
    assert balanced("a('b')c")
