import sys
from collections import Counter


def top_words(path: str, n: int) -> list[tuple[str, int]]:
    counts: Counter[str] = Counter()
    with open(path, encoding="utf-8") as f:
        for line in f:
            for word in line.lower().split():
                cleaned = word.strip(".,!?;:\"'()[]")
