```cpp
#include <cassert>
#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main() {
    // Build 1 -> 2 -> 3 -> 4
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(4);

    head = reverse(head);

    int expected[] = {4, 3, 2, 1};
    int i = 0;
    for (Node* p = head; p != nullptr; p = p->next) {
        assert(p->value == expected[i++]);
    }
    assert(i == 4);

    // reverse(nullptr) returns nullptr.
    assert(reverse(nullptr) == nullptr);

    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
    std::cout << "ok\n";
    return 0;
}
```

