```rust
/// Split one CSV record. Commas inside double quotes are kept, and "" is a
/// literal quote inside a quoted field.
pub fn split_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut field = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();

    while let Some(c) = chars.next() {
        match c {
            '"' if in_quotes && chars.peek() == Some(&'"') => {
                field.push('"');
                chars.next();
            }
            '"' => in_quotes = !in_quotes,
            ',' if !in_quotes => {
                fields.push(std::mem::take(&mut field));
            }
            _ => field.push(c),
        }
    }
    fields.push(field);
    fields
}

#[cfg(test)]
mod tests {
    use super::split_csv_line;

    #[test]
    fn plain() {
        assert_eq!(split_csv_line("a,b,c"), vec!["a", "b", "c"]);
    }

    #[test]
    fn quoted_comma() {
        assert_eq!(split_csv_line("a,\"b,c\",d"), vec!["a", "b,c", "d"]);
    }

    #[test]
    fn escaped_quote() {
        assert_eq!(split_csv_line("\"he said \"\"hi\"\"\""), vec!["he said \"hi\""]);
    }

    #[test]
    fn empty_and_trailing() {
        assert_eq!(split_csv_line(""), vec![""]);
        assert_eq!(split_csv_line("a,"), vec!["a", ""]);
    }
}
```

