#include <limits.h>
#include <stddef.h>
#include <stdio.h>

long parse_uint(const char *s) {
    if (s == NULL || *s == '\0') {
        return -1;
    }
    unsigned long acc = 0;
    for (const char *p = s; *p != '\0'; ++p) {
        if (*p < '0' || *p > '9') {
            return -1;
        }
        unsigned long digit = (unsigned long)(*p - '0');
        if (acc > (ULONG_MAX - digit) / 10UL) {
            return -1;
        }
        acc = acc * 10UL + digit;
    }
    if (acc > (unsigned long)LONG_MAX) {
        return -1;
    }
    return (long)acc;
}

int main(void) {
    printf("%ld\n", parse_uint("0"));
    printf("%ld\n", parse_uint("12345"));
    printf("%ld\n", parse_uint("12a"));
    printf("%ld\n", parse_uint(""));
    printf("%ld\n", parse_uint("99999999999999999999"));
    return 0;
}
```

