```cpp
#include <array>
#include <cstddef>
#include <cstdio>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int v) {
        if (count_ == N) {
            return false;
        }
        data_[tail_] = v;
        tail_ = (tail_ + 1) % N;
        ++count_;
        return true;
    }

    std::optional<int> pop() {
        if (count_ == 0) {
            return std::nullopt;
        }
        int v = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return v;
    }

    std::size_t size() const { return count_; }
    static constexpr std::size_t capacity() { return N; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<3> rb;
    std::printf("push %d %d %d %d\n", rb.push(1), rb.push(2), rb.push(3), rb.push(4));
    std::printf("size %zu\n", rb.size());
    while (auto v = rb.pop()) {
        std::printf("pop %d\n", *v);
    }
    return 0;
}
```

The fourth push on a capacity-3 buffer returns `false`; `% N` on both indices keeps it circular, and `std::optional` marks an empty pop without a magic value.

