void reverse_in_place(std::string& s) {
    std::size_t i = 0;
    std::size_t j = s.size();
    while (i < j && j > 0) {
        --j;
        if (i >= j) break;
        std::swap(s[i], s[j]);
        ++i;
    }
}

int main() {
    std::string s = "hello";
    reverse_in_place(s);
    std::cout << s << '\n';  // "olleh"

    std::string empty;
    reverse_in_place(empty);
    std::cout << '[' << empty << "]\n";  // "[]"

    std::string utf8 = "caf\xC3\xA9";
    reverse_in_place(utf8);
    std::cout << utf8 << '\n';  // bytes reversed, not graphemes
}
