Reads character by character so punctuation and whitespace both break words, lowercases with the `unsigned char` cast to avoid undefined behaviour on negative `char` values, and sorts by count descending then alphabetically for a stable result. The final word is flushed after the loop ends.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : data_(capacity), cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be positive");
    }

    bool full() const { return size_ == cap_; }
    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

    void push(double value) {
        data_[tail_] = value;
        tail_ = (tail_ + 1) % cap_;
        if (size_ < cap_) {
            ++size_;
        } else {
            head_ = (head_ + 1) % cap_;  // overwrite oldest
        }
    }

    std::optional<double> pop() {
        if (empty()) return std::nullopt;
        double value = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

    void print() const {
        for (std::size_t i = 0; i < size_; ++i) {
            std::cout << data_[(head_ + i) % cap_] << (i + 1 == size_ ? '\n' : ' ');
        }
    }

private:
    std::vector<double> data_;
    std::size_t cap_ = 0, head_ = 0, tail_ = 0, size_ = 0;
};

int main() {
    RingBuffer rb(3);
    rb.push(1.5);
    rb.push(2.5);
    rb.push(3.5);
    rb.push(4.5);  // overwrites 1.5
    rb.print();    // 2.5 3.5 4.5
    std::cout << *rb.pop() << '\n';  // 2.5
    rb.print();    // 3.5 4.5
    return 0;
}
```

When the buffer is full the write overwrites the oldest element by advancing `head_`, so iteration always starts at the live oldest value. `pop` returns `std::nullopt` on an empty buffer instead of throwing.

```rust
fn decode_rle(input: &str) -> Result<String, String> {
    let mut out = String::new();
    let mut chars = input.chars().peekable();

    while let Some(ch) = chars.next() {
        if ch.is_ascii_digit() {
            return Err(format!("digit '{}' without a preceding character", ch));
        }
        let mut digits = String::new();
        while let Some(&next) = chars.peek() {
            if next.is_ascii_digit() {
                digits.push(next);
                chars.next();
            } else {
                break;
            }
        }
        if digits.is_empty() {
            return Err(format!("character '{}' has no count", ch));
        }
        let count: usize = digits.parse().map_err(|_| format!("bad count '{}'", digits))?;
        for _ in 0..count {
            out.push(ch);
        }
    }
    Ok(out)
}

fn main() {
    assert_eq!(decode_rle("a3b2c1").unwrap(), "aaabbc");
    assert_eq!(decode_rle("z10").unwrap(), "z".repeat(10));
    assert!(decode_rle("3ab").is_err());
    assert!(decode_rle("ab").is_err());
    println!("ok");
}
```

Reads a letter, greedily consumes the following digit run, and expands. A leading digit or a letter with no count is rejected with a descriptive error rather than silently skipped.

