fn fib(n: u32) -> Result<u128, String> {
    let (mut a, mut b): (u128, u128) = (0, 1);
    for _ in 0..n {
        let next = a
            .checked_add(b)
            .ok_or_else(|| format!("overflow computing fib({})", n))?;
        a = b;
        b = next;
    }
    Ok(a)
}

