import os
import sys
from collections import defaultdict


def size_by_extension(root: str) -> list[tuple[str, int]]:
    totals: dict[str, int] = defaultdict(int)
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            ext = os.path.splitext(name)[1].lower() or "<none>"
            full = os.path.join(dirpath, name)
            try:
                totals[ext] += os.path.getsize(full)
            except OSError:
                continue  # unreadable symlink or permission error
    return sorted(totals.items(), key=lambda item: item[1], reverse=True)


def human_bytes(n: int) -> str:
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if n < 1024 or unit == "TB":
            return f"{n:.1f} {unit}" if unit != "B" else f"{n} B"
        n /= 1024
    return f"{n} B"


if __name__ == "__main__":
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    if not os.path.isdir(target):
        print(f"error: not a directory: {target}", file=sys.stderr)
        sys.exit(1)
    for ext, total in size_by_extension(target):
        print(f"{ext:<10} {human_bytes(total):>12}")
```

Sorts by raw byte totals before formatting, so ordering matches the numbers shown. Files that vanish or can't be stat'd are skipped instead of aborting the walk.

