import random


def kth_smallest(nums, k):
    if not nums:
        raise ValueError("empty input")
    if k < 1 or k > len(nums):
        raise ValueError("k out of range")
    arr = list(nums)
    k -= 1

    def partition(lo, hi):
        pivot = arr[hi]
        i = lo
        for j in range(lo, hi):
            if arr[j] < pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[hi] = arr[hi], arr[i]
        return i

    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        p = partition(lo, hi)
        if p == k:
            return arr[p]
        elif p < k:
            lo = p + 1
        else:
            hi = p - 1
    return arr[k]


if __name__ == "__main__":
    data = [7, 2, 9, 4, 1, 8, 3]
    assert kth_smallest(data, 1) == 1
    assert kth_smallest(data, 4) == 4
    assert kth_smallest(data, 7) == 9
    assert kth_smallest([5], 1) == 5
    print("ok")
