```python
def fib_fast(n: int) -> int:
    """Return F(n) using fast doubling; F(0)=0, F(1)=1."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def pair(k: int) -> tuple[int, int]:
        if k == 0:
            return 0, 1
        a, b = pair(k >> 1)
        c = a * (2 * b - a)
        d = a * a + b * b
        if k & 1:
            return d, c + d
        return c, d

    return pair(n)[0]


def fib_iter(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


if __name__ == "__main__":
    for n in range(0, 200):
        fast = fib_fast(n)
        slow = fib_iter(n)
        assert fast == slow, f"mismatch at n={n}: {fast} != {slow}"
    print("verified F(0)..F(199)")
    print("F(100) =", fib_fast(100))
    assert fib_fast(100) == 354224848179261915075
```
Fast doubling runs in O(log n) multiplications and returns exact Python ints (no overflow). The self-check compares every value from 0 to 199 against the O(n) version and pins F(100) to its known value.

```c
#include <stdio.h>
#include <string.h>

#define MAX 1024

static int matches(char open, char close) {
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

int balanced(const char *s) {
    char stack[MAX];
    size_t top = 0;

    for (size_t i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            if (top == MAX) return 0;
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0 || !matches(stack[--top], c)) return 0;
        }
    }
    return top == 0;
}

int main(void) {
    const char *cases[] = {
        "()[]{}", "([{}])", "(]", "([)]", "", "((( )))", "{", "}"
    };
    size_t n = sizeof(cases) / sizeof(cases[0]);
    for (size_t i = 0; i < n; i++) {
        printf("%-10s -> %s\n", cases[i], balanced(cases[i]) ? "balanced" : "unbalanced");
    }
    return 0;
}
```
The stack holds only opening brackets; a closing bracket must match the most recent opener (`matches`) or the function fails immediately. The final `top == 0` catches unclosed openers, and the `MAX` guard prevents a stack overflow on pathological input. Mixed-ordering cases like `([)]` are correctly rejected.

