```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    static constexpr std::size_t capacity() { return N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << "push " << rb.push(1) << rb.push(2) << rb.push(3) << '\n';
    std::cout << "full push -> " << rb.push(4) << '\n';
    while (auto v = rb.pop()) std::cout << "pop " << *v << '\n';
    std::cout << "empty pop -> " << (rb.pop() ? "value" : "nullopt") << '\n';
    std::cout << "size=" << rb.size() << '\n';
}
```
`head_` plus `count_` avoids a full/empty ambiguity: `push` fails only when `count_ == N`, and `pop` returns `std::optional`, so an empty buffer is reported without sentinel values. Indices wrap with modulo and `data_` is stored inline, so there is no allocation.

