    }
    std::optional<int> pop() {
        if (count_ == 0) return std::nullopt;
        int v = buf[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return v;
    }
    std::size_t size() const { return count_; }
};

int main() {
    RingBuffer<3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << "\n"; // 1110
    while (auto v = rb.pop()) std::cout << *v << ' ';                          // 1 2 3
    std::cout << "\n" << (rb.pop().has_value() ? "has" : "empty") << "\n";  // empty
}
