fn second_largest(nums: &[i64]) -> Option<i64> {
    let mut top: Option<i64> = None;
    let mut second: Option<i64> = None;
    for &n in nums {
        if top == Some(n) {
            continue;
        }
        if top.map_or(true, |t| n > t) {
            second = top;
            top = Some(n);
        } else if second.map_or(true, |s| n > s) {
            second = Some(n);
        }
    }
    second
}

