```python
import threading
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self._data = OrderedDict()
        self._lock = threading.Lock()

    def get(self, key):
        with self._lock:
            if key not in self._data:
                return None
            self._data.move_to_end(key)
            return self._data[key]

    def put(self, key, value):
        with self._lock:
            if key in self._data:
                self._data.move_to_end(key)
            self._data[key] = value
            if len(self._data) > self.capacity:
                self._data.popitem(last=False)

    def keys(self):
        with self._lock:
            return list(self._data.keys())


if __name__ == "__main__":
    c = LRUCache(3)
    for k in "abc":
        c.put(k, k.upper())
    assert c.get("a") == "A"
    c.put("d", "D")
    assert c.keys() == ["c", "a", "d"], c.keys()

    shared = LRUCache(50)
    def worker(seed):
        for i in range(1000):
            shared.put((seed + i) % 80, i)
            shared.get((seed * i) % 80)
    threads = [threading.Thread(target=worker, args=(s,)) for s in range(8)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert len(shared.keys()) <= 50
```
Every method holds the same lock, so reads and the OrderedDict reordering can't interleave; `capacity >= 1` is enforced at construction.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        std::size_t idx = (head_ + N - size_) % N;
        T value = data_[idx];
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    static constexpr std::size_t capacity() { return N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 4> rb;
    assert(rb.empty());
    assert(!rb.pop().has_value());
    for (int i = 0; i < 6; ++i) rb.push(i);
    assert(rb.size() == 4);
    assert(rb.pop().value() == 2);
    assert(rb.pop().value() == 3);
    while (!rb.empty()) rb.pop();
    assert(rb.empty());
    rb.push(42);
    assert(rb.pop().value() == 42);
    std::cout << "ok\n";
}
```
Pushing past capacity overwrites the oldest element and `pop` reads in FIFO order because the tail index is derived from `head_` and `size_`.

