    std::istringstream stream(line);
    std::string token;
    while (stream >> token) {
        std::istringstream one(token);
        long long value = 0;
        one >> value;
        if (one.fail() || !one.eof()) {
            result.badTokens.push_back(token);
        } else {
            result.values.push_back(value);
        }
    }
    return result;
}

long long safeSum(const std::vector<long long>& values, bool& overflow) {
    long long total = 0;
    for (long long v : values) {
        if ((v > 0 && total > std::numeric_limits<long long>::max() - v) ||
            (v < 0 && total < std::numeric_limits<long long>::min() - v)) {
            overflow = true;
            return total;
        }
        total += v;
    }
    return total;
}

int main() {
    auto r = parseNumbers("10 -3 42 abc 7 999999999999999999999999");
    assert(r.values.size() == 4);
    assert(r.badTokens.size() == 2);
    bool overflow = false;
    assert(safeSum(r.values, overflow) == 56);
    assert(!overflow);
    assert(parseNumbers("").values.empty());
    std::cout << "ok\n";
}
```
Each token gets its own stream so a bad word can't poison the rest of the line; the sum checks both overflow directions before adding.

```rust
#[derive(Debug, PartialEq)]
pub enum EvalError {
    UnexpectedChar(char),
    MismatchedParen,
    DivideByZero,
    TrailingInput,
}

struct Parser<'a> {
    chars: Vec<char>,
    pos: usize,
    _src: &'a str,
}

impl<'a> Parser<'a> {
    fn new(src: &'a str) -> Self {
        Parser { chars: src.chars().collect(), pos: 0, _src: src }
    }

    fn peek(&self) -> Option<char> { self.chars.get(self.pos).copied() }

    fn parse_expr(&mut self) -> Result<f64, EvalError> {
        let mut value = self.parse_term()?;
        while let Some(c) = self.peek() {
            match c {
                '+' => { self.pos += 1; value += self.parse_term()?; }
                '-' => { self.pos += 1; value -= self.parse_term()?; }
                _ => break,
            }
        }
        Ok(value)
    }

    fn parse_term(&mut self) -> Result<f64, EvalError> {
        let mut value = self.parse_factor()?;
        while let Some(c) = self.peek() {
            match c {
                '*' => { self.pos += 1; value *= self.parse_factor()?; }
                '/' => {
                    self.pos += 1;
                    let rhs = self.parse_factor()?;
                    if rhs == 0.0 { return Err(EvalError::DivideByZero); }
                    value /= rhs;
                }
                _ => break,
            }
        }
        Ok(value)
    }

    fn parse_factor(&mut self) -> Result<f64, EvalError> {
        match self.peek() {
            Some('(') => {
                self.pos += 1;
                let value = self.parse_expr()?;
                if self.peek() == Some(')') { self.pos += 1; Ok(value) }
                else { Err(EvalError::MismatchedParen) }
            }
            Some(c) if c.is_ascii_digit() || c == '.' => {
                let start = self.pos;
                while matches!(self.peek(), Some(c) if c.is_ascii_digit() || c == '.') {
                    self.pos += 1;
                }
                let text: String = self.chars[start..self.pos].iter().collect();
                text.parse::<f64>().map_err(|_| EvalError::UnexpectedChar(text.chars().next().unwrap_or('?')))
            }
            Some(c) => Err(EvalError::UnexpectedChar(c)),
            None => Err(EvalError::MismatchedParen),
        }
    }
}

pub fn evaluate(expr: &str) -> Result<f64, EvalError> {
    let mut p = Parser::new(expr);
    let value = p.parse_expr()?;
    if p.pos != p.chars.len() { return Err(EvalError::TrailingInput); }
    Ok(value)
}

fn main() {
    assert_eq!(evaluate("2 + 3 * (4 - 1)"), Ok(11.0));
    assert_eq!(evaluate("(1 + 2) * (3 + 4)"), Ok(21.0));
    assert_eq!(evaluate("10 / 4"), Ok(2.5));
    assert_eq!(evaluate("1 / 0"), Err(EvalError::DivideByZero));
    assert_eq!(evaluate("(1 + 2"), Err(EvalError::MismatchedParen));
    assert_eq!(evaluate("2 3"), Err(EvalError::TrailingInput));
    println!("ok");
}
```
Recursive descent with `parse_expr`/`parse_term`/`parse_factor` gives `*`,`/` precedence over `+`,`-`; the `pos == len` check at the top level rejects leftover input like `2 3`.

```rust
/// Counts trailing zeros of n! by summing the powers of 5 that divide n!.
pub fn trailing_zeros(mut n: u64) -> u64 {
    let mut count = 0;
    while n >= 5 {
        n /= 5;
        count += n;
    }
    count
}

fn main() {
    assert_eq!(trailing_zeros(0), 0);
    assert_eq!(trailing_zeros(4), 0);
    assert_eq!(trailing_zeros(5), 1);
    assert_eq!(trailing_zeros(10), 2);
    assert_eq!(trailing_zeros(25), 6);
    assert_eq!(trailing_zeros(100), 24);
    assert_eq!(trailing_zeros(1000), 249);
    // u64::MAX overflows the intermediate additions far before the loop ends;
    // the count stays exact only while n/5^k accumulation fits.
    assert_eq!(trailing_zeros(u64::MAX), 4611686018427387844);
    println!("ok");
}
```
Each division strips one factor of 5, so `n/5 + n/25 + n/125 + ...` counts exactly the fives in `n!`; powers of two are always more plentiful, so this is the number of trailing zeros.

