def search_rotated(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[lo] <= nums[mid]:
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1


if __name__ == "__main__":
    base = sorted({3, 1, 4, 1, 5, 9, 2, 6})
    assert search_rotated([4, 5, 6, 7, 0, 1, 2], 0) == 4
    assert search_rotated([4, 5, 6, 7, 0, 1, 2], 3) == -1
    assert search_rotated([1], 0) == -1
    assert search_rotated([1], 1) == 0
    assert search_rotated([], 5) == -1

    for k in range(len(base)):
        rotated = base[k:] + base[:k]
        for i, value in enumerate(rotated):
            assert search_rotated(rotated, value) == i, (rotated, value, i)
        assert search_rotated(rotated, -99) == -1
```
At each step exactly one half is sorted, so the range test targets the sorted side; the rotated-array loop checks every rotation against a linear scan before trusting the binary path.

