int count_vowels(const char *s) {
    static const int is_vowel[256] = {
        ['a'] = 1, ['e'] = 1, ['i'] = 1, ['o'] = 1, ['u'] = 1
    };
    int count = 0;
    for (; *s; ++s) {
        unsigned char c = (unsigned char)tolower((unsigned char)*s);
        count += is_vowel[c];
    }
    return count;
}

int main(void) {
    const char *cases[] = {"hello", "AEIOU", "", "rhythm", "naive"};
    for (int i = 0; i < 5; ++i)
        printf("%s -> %d\n", cases[i], count_vowels(cases[i]));
    return 0;
}
