```cpp
#include <array>
#include <cstddef>
#include <optional>

class RingBuffer {
    std::array<int, 8> data_{};
    std::size_t head_ = 0;  // next read
    std::size_t size_ = 0;

public:
    static constexpr std::size_t capacity() { return 8; }
    std::size_t size() const { return size_; }
    bool full() const { return size_ == capacity(); }
    bool empty() const { return size_ == 0; }

    bool push_back(int value) {
        if (full()) return false;
        data_[(head_ + size_) % capacity()] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop_front() {
        if (empty()) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity();
        --size_;
        return value;
    }
};
```
Fixed capacity of 8; `push_back` fails (returns false) when full instead of overwriting, and `pop_front` returns `nullopt` when empty. The write index is `(head_ + size_) % capacity`.

