import hashlib
import sys
from collections import defaultdict
from pathlib import Path


def sha256(path: Path, chunk: int = 65536) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        while True:
            block = f.read(chunk)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def find_duplicates(root: Path) -> dict[str, list[Path]]:
    by_hash: dict[str, list[Path]] = defaultdict(list)
    for path in sorted(root.rglob("*")):
        if path.is_file():
            try:
                by_hash[sha256(path)].append(path)
            except OSError as exc:
                print(f"skip {path}: {exc}", file=sys.stderr)
    return {d: ps for d, ps in by_hash.items() if len(ps) > 1}


if __name__ == "__main__":
    root = Path(sys.argv[1] if len(sys.argv) > 1 else ".")
    dups = find_duplicates(root)
    if not dups:
        print("no duplicates")
    for digest, paths in sorted(dups.items()):
        print(digest[:12])
        for p in paths:
            print(" ", p)
```
Streams each file in 64 KiB blocks so large files don't load fully into memory, and skips unreadable files with a warning rather than crashing.

