    head = reverse(head);
    assert(head && head->value == 3);
    assert(head->next && head->next->value == 2);
    assert(head->next->next && head->next->next->value == 1);
    assert(head->next->next->next == nullptr);
    assert(reverse(nullptr) == nullptr);

    while (head) { Node* t = head; head = head->next; delete t; }
    std::cout << "ok\n";
    return 0;
}
