pub fn longest_common_prefix(words: &[String]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = words[0].as_bytes();
    let mut end = first.len();
    for w in &words[1..] {
        let b = w.as_bytes();
        let mut i = 0;
        let limit = end.min(b.len());
        while i < limit && first[i] == b[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    String::from_utf8_lossy(&first[..end]).into_owned()
}

fn main() {
    let v: Vec<String> = vec!["flower".into(), "flow".into(), "flight".into()];
    assert_eq!(longest_common_prefix(&v), "fl");
    let empty: Vec<String> = vec![];
    assert_eq!(longest_common_prefix(&empty), "");
    let none: Vec<String> = vec!["dog".into(), "racecar".into()];
    assert_eq!(longest_common_prefix(&none), "");
    println!("ok");
}
