fn fib(n: u64) -> Option<u128> {
    let mut a: u128 = 1; // F(1)
    let mut b: u128 = 0; // F(0)
    let mut m00: u128 = 1;
    let mut m01: u128 = 1;
    let mut m10: u128 = 1;
    let mut m11: u128 = 0;
    let mut e = n;
    while e > 0 {
        if e & 1 == 1 {
            let na = a
                .checked_mul(m00)?
                .checked_add(b.checked_mul(m10)?)?;
            let nb = a
                .checked_mul(m01)?
                .checked_add(b.checked_mul(m11)?)?;
            a = na;
            b = nb;
        }
        let n00 = m00.checked_mul(m00)?.checked_add(m01.checked_mul(m10)?)?;
        let n01 = m00.checked_mul(m01)?.checked_add(m01.checked_mul(m11)?)?;
        let n10 = m10.checked_mul(m00)?.checked_add(m11.checked_mul(m10)?)?;
        let n11 = m10.checked_mul(m01)?.checked_add(m11.checked_mul(m11)?)?;
        m00 = n00;
        m01 = n01;
        m10 = n10;
        m11 = n11;
        e >>= 1;
    }
    Some(b)
}

fn main() {
    assert_eq!(fib(0), Some(0));
    assert_eq!(fib(10), Some(55));
    assert_eq!(fib(100), Some(354224848179261915075));
    println!("{:?}", fib(185)); // None on overflow
}
