template <typename T>
std::optional<double> average(const std::vector<T>& v) {
    if (v.empty()) return std::nullopt;
    double sum = 0.0;
    for (const auto& x : v) sum += static_cast<double>(x);
    return sum / static_cast<double>(v.size());
}

int main() {
    std::cout << average<int>({}) << '\n';                 // prints empty-ish
    auto a = average<int>({1, 2, 3, 4});
    std::cout << (a ? *a : -1) << '\n';                      // 2.5
    auto b = average<double>({1.5, 2.5});
    std::cout << (b ? *b : -1) << '\n';                      // 2.0
    return 0;
}
