void reverse_words(std::string& s) {
    std::reverse(s.begin(), s.end());
    std::size_t n = s.size();
    std::size_t i = 0;
    while (i < n) {
        std::size_t j = i;
        while (j < n && s[j] == ' ') ++j;
        std::size_t k = j;
        while (k < n && s[k] != ' ') ++k;
        std::reverse(s.begin() + j, s.begin() + k);
        i = k;
    }
