```rust
fn longest_common_prefix(strs: &[String]) -> String {
    if strs.is_empty() {
        return String::new();
    }
    // Start with the first string; shrink while it is not a prefix of the next.
    let first = &strs[0];
    let mut end = first.len();

    for s in &strs[1..] {
        // Compare byte by byte up to the current candidate length.
        let mut i = 0;
        let bytes_first = first.as_bytes();
        let bytes_s = s.as_bytes();
        let limit = end.min(s.len());
        while i < limit && bytes_first[i] == bytes_s[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }

    // end always lands on a char boundary because equal bytes imply a shared prefix.
    first[..end].to_string()
}

fn main() {
    let words: Vec<String> = vec![
        "flower".to_string(),
        "flow".to_string(),
        "flight".to_string(),
    ];
    assert_eq!(longest_common_prefix(&words), "fl");

    let none: Vec<String> = vec![];
    assert_eq!(longest_common_prefix(&none), "");

    let has_empty: Vec<String> = vec!["abc".to_string(), "".to_string()];
    assert_eq!(longest_common_prefix(&has_empty), "");

    let unicode: Vec<String> = vec!["café".to_string(), "café au lait".to_string()];
    assert_eq!(longest_common_prefix(&unicode), "café");

    println!("ok");
}
```

Empty slices and any empty string both collapse the prefix to `""`. Comparing bytes is safe here because a byte-equality prefix between valid UTF-8 strings always ends on a char boundary.

