```c
#include <stdio.h>
#include <stddef.h>

static int lc(int c) {
    if (c >= 'A' && c <= 'Z') return c + ('a' - 'A');
    return c;
}

const char *strstr_ci(const char *haystack, const char *needle) {
    if (haystack == NULL || needle == NULL) return NULL;
    if (*needle == '\0') return haystack;

    for (; *haystack != '\0'; ++haystack) {
        const char *h = haystack;
        const char *n = needle;
        while (*h != '\0' && *n != '\0' && lc((unsigned char)*h) == lc((unsigned char)*n)) {
            ++h;
            ++n;
        }
        if (*n == '\0') return haystack;
    }
    return NULL;
}

int main(void) {
    const char *r = strstr_ci("Hello World", "WORLD");
    printf("%s\n", r ? r : "NULL");   /* World */

    printf("%s\n", strstr_ci("abc", "") ? "match" : "NULL");  /* match */
    printf("%s\n", strstr_ci("abc", "d") ? "match" : "NULL");  /* NULL */
    printf("%s\n", strstr_ci("MIXedCASE", "edc") ? "match" : "NULL"); /* match */
    return 0;
}
```

