```rust
use std::collections::HashMap;

// Store nodes in a Vec to avoid a manual pointer graph; indices are cheap.
struct LruCache {
    cap: usize,
    map: HashMap<i32, usize>, // key -> node index
    key: Vec<i32>,
    val: Vec<i32>,
    prev: Vec<usize>,
    next: Vec<usize>,
    head: usize, // most recent
    tail: usize, // least recent
    used: Vec<bool>,
}

impl LruCache {
    fn new(cap: usize) -> Self {
        LruCache {
            cap,
            map: HashMap::new(),
            key: Vec::new(),
            val: Vec::new(),
            prev: Vec::new(),
            next: Vec::new(),
            head: usize::MAX,
            tail: usize::MAX,
            used: Vec::new(),
        }
    }

    fn detach(&mut self, i: usize) {
        let p = self.prev[i];
        let n = self.next[i];
        if p != usize::MAX { self.next[p] = n; } else { self.head = n; }
        if n != usize::MAX { self.prev[n] = p; } else { self.tail = p; }
    }

    fn push_front(&mut self, i: usize) {
        self.prev[i] = usize::MAX;
        self.next[i] = self.head;
        if self.head != usize::MAX { self.prev[self.head] = i; }
        self.head = i;
        if self.tail == usize::MAX { self.tail = i; }
    }

    fn alloc(&mut self, k: i32, v: i32) -> usize {
        let i = self.key.len();
        self.key.push(k);
        self.val.push(v);
        self.prev.push(usize::MAX);
        self.next.push(usize::MAX);
        self.used.push(true);
        i
    }

    fn get(&mut self, k: i32) -> Option<i32> {
        let i = *self.map.get(&k)?;
        self.detach(i);
        self.push_front(i);
        Some(self.val[i])
    }

    fn put(&mut self, k: i32, v: i32) {
        if let Some(&i) = self.map.get(&k) {
            self.val[i] = v;
            self.detach(i);
            self.push_front(i);
            return;
        }
        if self.map.len() == self.cap {
            let lru = self.tail;
            self.detach(lru);
            self.map.remove(&self.key[lru]);
            self.used[lru] = false;
        }
        let i = self.alloc(k, v);
        self.push_front(i);
        self.map.insert(k, i);
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 1);
    c.put(2, 2);
    assert_eq!(c.get(1), Some(1));          // 1 is now most recent
    c.put(3, 3);                            // evicts 2
    assert_eq!(c.get(2), None);
    assert_eq!(c.get(1), Some(1));
    assert_eq!(c.get(3), Some(3));
    println!("ok");
}
```

Nodes live in parallel `Vec`s indexed by `usize`; `usize::MAX` means "no node". `get` and `put` are O(1) average, evicting the tail when the map is at capacity.

```cpp
#include <iostream>
#include <vector>

// Merge two sorted ranges. Equal elements: left wins, preserving left's order.
std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());

    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        // <= rather than < keeps ties stable toward the left sequence.
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5, 5};
    std::vector<int> b{2, 5, 6};
    std::vector<int> r = merge_sorted(a, b);
    for (int v : r) std::cout << v << ' ';
    std::cout << '\n'; // 1 2 3 5 5 5 6

    std::vector<int> empty1, empty2{9};
    std::vector<int> r2 = merge_sorted(empty1, empty2);
    for (int v : r2) std::cout << v << ' ';
    std::cout << '\n'; // 9

    std::vector<int> r3 = merge_sorted(empty1, empty1);
    std::cout << r3.size() << '\n'; // 0
    return 0;
}
```

Linear time, `reserve` avoids reallocations. Using `<=` on the left makes the merge stable for equal keys, which matters when the elements carry more than the key compared.

```python
import string


def _shift(ch: str, k: int, base: str) -> str:
    if ch not in base:
        return ch
    idx = base.index(ch)
    return base[(idx + k) % len(base)]


def caesar(text: str, k: int) -> str:
    """Shift letters by k; keep case; leave digits/punctuation/unicode alone."""
    k %= 26
    upper = string.ascii_uppercase
    lower = string.ascii_lowercase
    out = []
    for ch in text:
        if ch in upper:
            out.append(_shift(ch, k, upper))
        elif ch in lower:
            out.append(_shift(ch, k, lower))
        else:
            out.append(ch)
    return "".join(out)


def encrypt(text: str, k: int) -> str:
    return caesar(text, k)


def decrypt(text: str, k: int) -> str:
    return caesar(text, -k)


if __name__ == "__main__":
    msg = "Attack at Dawn, 5 a.m.! café"
    enc = encrypt(msg, 3)
    print(enc)
    assert decrypt(enc, 3) == msg          # round-trip, incl. unicode
    assert encrypt("abc", 26) == "abc"     # full rotation is identity
    assert encrypt("xyz", 3) == "abc"      # wrap
    assert encrypt("", 5) == ""            # empty input
    print("ok")
```

`k %= 26` normalizes out-of-range and negative keys. Non-ASCII characters (like `é`) are not in the ASCII alphabets so they pass through unchanged, which keeps the round-trip exact.

