bool isPalindrome(int64_t x) {
    if (x < 0) return false;           // leading '-' never mirrors
    if (x < 10) return true;           // single digit
    if (x % 10 == 0) return false;     // trailing zero cannot lead

    int64_t reversed = 0;
    while (x > reversed) {
        reversed = reversed * 10 + x % 10;
        x /= 10;
    }
    // even length: x == reversed; odd length: x == reversed / 10
    return x == reversed || x == reversed / 10;
}

