fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);

    while i < a.len() && j < b.len() {
        // Take from `a` on ties so equal elements keep their left-first order.
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }

    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 3, 6];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 3, 5, 6, 7]);

    let empty: [i32; 0] = [];
    assert_eq!(merge_sorted(&empty, &b), vec![2, 3, 6]);
    assert_eq!(merge_sorted(&a, &empty), vec![1, 3, 5, 7]);
    assert!(merge_sorted(&empty, &empty).is_empty());

    let words = ["ant", "cat"];
    let more = ["bee"];
    assert_eq!(merge_sorted(&words, &more), vec!["ant", "bee", "cat"]);

    println!("all cases passed");
}
```
The two index cursors advance over the smaller remaining head each iteration, and the tail of whichever slice is left over is appended once one side is exhausted. `T: Clone` keeps it general over owned types like `String`; the tie rule (`<=`) makes the merge stable.

```c
#include <stdio.h>
#include <ctype.h>

size_t count_words(const char *s) {
    size_t words = 0;
    int in_word = 0;

    for (; *s != '\0'; ++s) {
        /* isspace takes an int in [0, UCHAR_MAX] or EOF; cast to be safe. */
        unsigned char c = (unsigned char)*s;
        if (isspace(c)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            words++;
        }
    }
    return words;
}

int main(void) {
    const char *cases[] = {
        "",
        "   ",
        "hello world",
        "  one\ttwo\nthree  ",
        "\xe4\xbd\xa0\xe5\xa5\xbd world", /* UTF-8 bytes, one word each */
        "a",
    };
    size_t expected[] = { 0, 0, 2, 3, 2, 1 };

    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        size_t got = count_words(cases[i]);
        if (got != expected[i]) {
            fprintf(stderr, "case %zu: got %zu, expected %zu\n", i, got, expected[i]);
            return 1;
        }
    }

    puts("all cases passed");
    return 0;
}
```
This counts byte runs, so multi-byte UTF-8 characters are handled implicitly — no byte within a UTF-8 sequence is whitespace, so a two-character CJK word still counts as one word. The `unsigned char` cast avoids undefined behaviour when a byte has the high bit set, which `isspace` would otherwise index into a table out of range.

