            .split(',')
            .nth(column)
            .ok_or_else(|| format!("line {}: fewer than {} columns", line_no + 1, column + 1))?
            .trim();

        let value: f64 = field
            .parse()
            .map_err(|_| format!("line {}: '{}' is not a number", line_no + 1, field))?;

        count += 1;
        sum += value;
        if value < min { min = value; }
        if value > max { max = value; }
    }

    if count == 0 {
        return Err("no numeric rows found".to_string());
    }
    Ok((count, sum / count as f64, min, max))
}

fn main() {
    let path = env::args().nth(1).unwrap_or_else(|| {
        eprintln!("usage: {} <file.csv> [column]", env::args().next().unwrap());
        std::process::exit(2);
    });
    let column: usize = env::args().nth(2).and_then(|c| c.parse().ok()).unwrap_or(0);

    let contents = match fs::read_to_string(&path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("error reading '{}': {}", path, e);
            std::process::exit(1);
        }
    };

    match parse_and_summarize(&contents, column) {
        Ok((count, mean, min, max)) => {
            println!("count={} mean={:.4} min={} max={}", count, mean, min, max);
        }
        Err(e) => {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    }
}
```
The parser is deliberately simple: it splits on commas without quoted-field support, which is fine for plain numeric data but would break on embedded commas. Real CSV needs a crate like `csv`. A header row would have to be skipped or the parse will fail with a clear line-numbered error.

```cpp
#include <cstddef>
#include <iostream>
#include <vector>

template <typename T>
std::ptrdiff_t binary_search_index(const std::vector<T>& v, const T& target) {
    std::size_t lo = 0;
    std::size_t hi = v.size();

    while (lo < hi) {
        // Avoid (lo + hi) overflow: compute the midpoint as lo + half the gap.
        std::size_t mid = lo + (hi - lo) / 2;
        if (v[mid] == target) {
            return static_cast<std::ptrdiff_t>(mid);
        } else if (v[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

int main() {
    std::vector<int> v{1, 3, 3, 5, 7, 9, 11};
    if (binary_search_index(v, 5) != 3) { std::cerr << "fail 5\n"; return 1; }
    if (binary_search_index(v, 1) != 0) { std::cerr << "fail 1\n"; return 1; }
    if (binary_search_index(v, 11) != 6) { std::cerr << "fail 11\n"; return 1; }
    if (binary_search_index(v, 4) != -1) { std::cerr << "fail 4\n"; return 1; }

    std::vector<int> empty;
    if (binary_search_index(empty, 0) != -1) { std::cerr << "fail empty\n"; return 1; }

    std::vector<std::string> words{"ant", "bee", "cat"};
    if (binary_search_index(words, std::string("bee")) != 1) { std::cerr << "fail bee\n"; return 1; }

    std::cout << "all cases passed\n";
    return 0;
}
```
The half-open range `[lo, hi)` converges in O(log n). On duplicates it returns whichever matching index the probe lands on, not necessarily the first; the tests avoid asserting a specific duplicate index. `T` only needs `operator<` and `operator==`.

```python
import json
import sys

REQUIRED = ["name", "version", "dependencies"]


def validate(path: str) -> list[str]:
    """Return a list of problem strings; empty list means the file is valid."""
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except FileNotFoundError:
        return [f"file not found: {path}"]
    except json.JSONDecodeError as exc:
        return [f"invalid JSON at line {exc.lineno}, column {exc.colno}: {exc.msg}"]
    except OSError as exc:
        return [f"could not read {path}: {exc}"]

    if not isinstance(data, dict):
        return [f"top-level value must be an object, got {type(data).__name__}"]

    problems = []
    for key in REQUIRED:
        if key not in data:
            problems.append(f"missing required key: {key!r}")

    deps = data.get("dependencies")
    if deps is not None and not isinstance(deps, list):
        problems.append("key 'dependencies' must be a list")
    elif isinstance(deps, list):
        for i, dep in enumerate(deps):
            if not isinstance(dep, str):
                problems.append(f"dependencies[{i}] must be a string")

    return problems


def main() -> int:
    if len(sys.argv) != 2:
        print(f"usage: {sys.argv[0]} <file.json>", file=sys.stderr)
        return 2

    problems = validate(sys.argv[1])
    if problems:
        print(f"{len(problems)} problem(s):")
        for p in problems:
            print(f"  - {p}")
        return 1

    print("OK: all required keys present")
    return 0


if __name__ == "__main__":
    sys.exit(main())
```
The `validate` function returns a list rather than raising, so every failure mode — missing file, malformed JSON, wrong shape — is reported the same way. Type errors are collected instead of short-circuiting so the user sees all problems at once. Exit codes: 0 valid, 1 invalid, 2 bad usage.

