```python
def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring of s (expand around center)."""
    if not s:
        return ""

    def expand(lo: int, hi: int) -> tuple[int, int]:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi  # half-open [start, end)

    start, end = 0, 0
    for i in range(len(s)):
        l1, r1 = expand(i, i)          # odd length
        l2, r2 = expand(i, i + 1)      # even length
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end]


if __name__ == "__main__":
    for text in ["babad", "cbbd", "", "a", "forgeeksskeegfor", "ünïcödé"]:
        print(repr(text), "->", repr(longest_palindrome(text)))
```

Runs in O(n²) time and O(1) extra space. Empty input returns `""`; ties keep the first (leftmost) longest palindrome found.

