from itertools import islice


def primes():
    """Yield primes indefinitely, growing a sieve by chunks."""
    yield 2
    found = [2]
    candidate = 3
    while True:
        limit = int(candidate ** 0.5)
        is_prime = all(candidate % p for p in found if p <= limit)
        if is_prime:
            found.append(candidate)
            yield candidate
        candidate += 2


def first_n_primes(n: int) -> list[int]:
    if n < 0:
        raise ValueError("n must be non-negative")
    return list(islice(primes(), n))


