```cpp
#include <cmath>
#include <cstdio>
#include <stdexcept>

double round_half_away(double value, int places) {
    if (places < 0 || places > 15) {
        throw std::invalid_argument("places must be in [0, 15]");
    }
    const double factor = std::pow(10.0, places);
    const double scaled = value * factor;
    const double rounded = std::trunc(std::abs(scaled) + 0.5) *
                           (scaled < 0 ? -1.0 : 1.0);
    return rounded / factor;
}

int main() {
    const double samples[] = {2.5, -2.5, 1.005, -1.005, 0.0, 123.4567};
    for (double v : samples) {
        std::printf("%.10f -> %.2f\n", v, round_half_away(v, 2));
    }
    return 0;
}
```

`std::trunc(std::abs(x) + 0.5)` handles the half-away case explicitly, and the sign is reapplied so negatives round away from zero too. Note that `1.005` cannot be represented exactly in binary, so it rounds toward `1.00`; that is a floating-point representation limit, not a bug in the rounding logic. Bounds-checking rejects out-of-range `places`.

