```python
import heapq


def dijkstra(graph: dict[str, list[tuple[str, int]]], source: str) -> dict[str, float]:
    """Shortest distances from source. Edge weights must be non-negative."""
    if any(w < 0 for edges in graph.values() for _, w in edges):
        raise ValueError("Dijkstra requires non-negative edge weights")

    dist: dict[str, float] = {node: float("inf") for node in graph}
    if source not in dist:
        raise KeyError(f"unknown source {source!r}")
    dist[source] = 0
    heap: list[tuple[float, str]] = [(0, source)]
    settled: set[str] = set()

    while heap:
        d, node = heapq.heappop(heap)
        if node in settled:
            continue
        settled.add(node)
        for neighbor, weight in graph.get(node, []):
            nd = d + weight
            if nd < dist.get(neighbor, float("inf")):
                dist[neighbor] = nd
                heapq.heappush(heap, (nd, neighbor))
    return dist


if __name__ == "__main__":
    g = {
        "A": [("B", 1), ("C", 4)],
        "B": [("C", 2), ("D", 5)],
        "C": [("D", 1)],
        "D": [],
    }
    print(dijkstra(g, "A"))
```

Output: `{'A': 0, 'B': 1, 'C': 3, 'D': 4}`. The `settled` set skips stale heap entries so each node is finalised once. The algorithm is invalid for negative weights, which is why that case raises instead of returning a wrong answer.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char **lines = NULL;
static size_t count = 0, cap = 0;

static int push(char *line) {
    if (count == cap) {
        size_t next = cap ? cap * 2 : 16;
        char **grown = realloc(lines, next * sizeof *grown);
        if (!grown) return -1;
        lines = grown;
        cap = next;
    }
    lines[count++] = line;
    return 0;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s INPUT OUTPUT\n", argv[0]);
        return 2;
    }
    FILE *in = fopen(argv[1], "r");
    if (!in) { perror("fopen input"); return 1; }

    char *line = NULL;
    size_t n = 0;
    ssize_t len;
    while ((len = getline(&line, &n, in)) != -1) {
        char *copy = malloc((size_t)len + 1);
        if (!copy) { perror("malloc"); free(line); fclose(in); return 1; }
        memcpy(copy, line, (size_t)len + 1);
        if (push(copy) != 0) { perror("realloc"); free(copy); free(line); fclose(in); return 1; }
    }
    free(line);
    fclose(in);

    FILE *out = fopen(argv[2], "w");
    if (!out) { perror("fopen output"); return 1; }
    for (size_t i = count; i-- > 0;) fputs(lines[i], out);
    fclose(out);

    for (size_t i = 0; i < count; ++i) free(lines[i]);
    free(lines);
    return 0;
}
```

Lines are stored with their trailing newline preserved, so the last line keeps its exact terminator and the output round-trips byte-for-byte except for order. The input is opened read-only; nothing is overwritten. `getline` is POSIX, so compile with `-D_POSIX_C_SOURCE=200809L` on strict toolchains.

A template ring buffer with a power-of-two-free index wrap:

```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), count_(0) {}

    bool push(const T& value) {
        if (count_ == buf_.size()) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % buf_.size();
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T value = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }

private:
    std::vector<T> buf_;
    std::size_t head_;
    std::size_t tail_;
    std::size_t count_;
};

int main() {
    RingBuffer<int> rb(3);
    std::cout << std::boolalpha << rb.push(1) << rb.push(2) << rb.push(3)
              << rb.push(4) << '\n';  // true true true false
    auto a = rb.pop();
    auto b = rb.pop();
    std::cout << *a << ' ' << *b << ' ' << rb.size() << '\n';  // 1 2 1
}
```

Using a separate `count_` avoids the classic full-vs-empty ambiguity that bites buffers which rely only on head/tail equality.

