Compare against the first string and shrink the prefix as needed.

```rust
fn longest_common_prefix(words: &[&str]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = words[0];
    let mut end = first.len();
    for w in &words[1..] {
        end = end.min(w.len());
        let mut i = 0;
        let a = first.as_bytes();
        let b = w.as_bytes();
        while i < end && a[i] == b[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    first[..end].to_string()
}

fn main() {
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&["dog", "racecar"]), "");
    assert_eq!(longest_common_prefix(&["same"]), "same");
    assert_eq!(longest_common_prefix(&["", "a"]), "");
    println!("all prefix tests passed");
}
```

Comparing raw bytes and slicing at a byte boundary is safe here because the prefix boundary always lands on a char boundary: a byte mismatch cannot occur inside a shared multibyte sequence, and `end` only shrinks to a position where two byte slices agree.

