def check_balance(s):
    """Return -1 if s is balanced, else the index of the first bad char."""
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set(pairs.values())
    stack = []

    for i, ch in enumerate(s):
        if ch in opens:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return i
            stack.pop()

    return -1 if not stack else len(s)  # unclosed openers reported at end


