static void reverse_in_place(char *s) {
    size_t i = 0;
    size_t j = strlen(s);
    while (i < j) {
        --j;
        if (i >= j) break;
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
    }
}

