constexpr std::uint64_t MOD = 1000000007ULL;

// Returns (F(n), F(n+1)) mod MOD via fast doubling.
std::pair<std::uint64_t, std::uint64_t> fib_pair(std::uint64_t n) {
    if (n == 0) {
        return {0, 1};
    }
    auto [a, b] = fib_pair(n >> 1);
    std::uint64_t c = a * ((2 * b % MOD + MOD - a) % MOD) % MOD;
    std::uint64_t d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1ULL) {
        return {d, (c + d) % MOD};
    }
    return {c, d};
}

int main() {
    std::uint64_t n;
    if (!(std::cin >> n)) {
        std::cerr << "expected an integer n\n";
        return 1;
