#include <algorithm>
#include <cctype>
#include <iostream>
#include <string>

void reverseWords(std::string& s) {
    std::reverse(s.begin(), s.end());          // reverse the whole string
    std::size_t i = 0;
    while (i < s.size()) {
        std::size_t j = i;
        while (j < s.size() && !std::isspace(static_cast<unsigned char>(s[j]))) ++j;
        std::reverse(s.begin() + i, s.begin() + j);  // restore each word
        i = j;
        while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
    }
}

int main() {
    std::string a = "the quick brown fox";
    reverseWords(a);
    std::cout << a << '\n';  // fox brown quick the

    std::string b = "";
    reverseWords(b);         // empty input stays empty
    std::cout << '[' << b << "]\n";

    std::string c = "one";
    reverseWords(c);         // single word unchanged
    std::cout << c << '\n';
}
```

The whole-buffer reverse followed by per-word reverses is the classic two-pass trick; it needs only index variables, so extra space is O(1). The `static_cast<unsigned char>` avoids undefined behaviour when `std::isspace` is handed a negative `char`.

```rust
#[derive(Debug, Default)]
pub struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self {
        Stack { items: Vec::new() }
    }

    pub fn push(&mut self, value: T) {
        self.items.push(value);
    }

    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    pub fn peek(&self) -> Option<&T> {
        self.items.last()
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
}

fn main() {
    let mut stack: Stack<i32> = Stack::new();
    assert!(stack.is_empty());
    assert_eq!(stack.pop(), None);

    stack.push(1);
    stack.push(2);
    assert_eq!(stack.peek(), Some(&2));
    assert_eq!(stack.pop(), Some(2));
    assert_eq!(stack.pop(), Some(1));
    assert!(stack.is_empty());
    println!("all stack assertions passed");
}
```

Backing the stack with `Vec` makes push/pop amortised O(1). `pop` and `peek` return `Option`, so the empty case is part of the type rather than a panic path. `Default` is derived so `Stack::default()` also works.

