import re

# Deliberately pragmatic: one @, a non-empty local part, a dotted domain.
EMAIL_RE = re.compile(
    r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$"
)


def validate_email(addr):
    """Return None if valid, else a human-readable reason."""
    if not isinstance(addr, str):
        return "email must be a string"
    addr = addr.strip()
    if not addr:
        return "email is empty"
    if len(addr) > 254:
        return "email is longer than 254 characters"
    if addr.count("@") != 1:
        return "email must contain exactly one '@'"
    local, _, domain = addr.partition("@")
    if not local:
        return "the part before '@' is empty"
    if len(local) > 64:
        return "the part before '@' is longer than 64 characters"
    if not EMAIL_RE.match(addr):
        return "email does not match the expected name@domain.tld shape"
    return None


if __name__ == "__main__":
    for addr in ["", "nope", "a@b", "user@sub.example.co", "  me@x.com  "]:
        print(repr(addr), "->", validate_email(addr))
```

The regex is intentionally not RFC 5322; a full grammar is unreadable and rejects nothing a real mailer would accept that this misses. Structural checks (count of `@`, length limits, empty local part) run first so the message points at the actual defect. Trailing whitespace is stripped before validation.

