int is_palindrome(const char *s) {
    const unsigned char *left = (const unsigned char *)s;
    const unsigned char *right = (const unsigned char *)s + strlen(s);
    while (left < right) {
        if (*left && !isalnum(*left)) { left++; continue; }
        if (right > (const unsigned char *)s && !isalnum(*(right - 1))) { right--; continue; }
        if (left >= right) break;
        if (tolower(*left) != tolower(*(right - 1))) return 0;
        left++;
        right--;
    }
    return 1;
}

