def is_valid_ipv4(s: str) -> bool:
    """True only for four dot-separated decimal octets, 0-255, no leading zeros."""
    if not isinstance(s, str):
        return False
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not part.isdigit():
            return False
        # reject leading zeros like "01" or "007"
        if len(part) > 1 and part[0] == "0":
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True


