#include <stdio.h>
#include <stddef.h>

static void reverse(char *s) {
    if (s == NULL) return;
    size_t n = 0;
    while (s[n] != '\0') ++n;      /* strlen without the library */
    if (n < 2) return;

    size_t i = 0, j = n - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
        --j;
    }
}

int main(void) {
    char a[] = "hello";
    char b[] = "a";
    char c[] = "";
    char d[] = "ab";

    reverse(a);
    reverse(b);
    reverse(c);
    reverse(d);

    printf("%s|%s|%s|%s\n", a, b, c, d);  /* olleh|a||ba */
    return 0;
}
```
Swapping from both ends inward reverses in place. The `n < 2` guard makes the single-character and empty cases no-ops, so `j = n - 1` is never evaluated with an underflowing `n`. The arrays are mutable (`char a[]`, not `char *a`) because string literals must not be written to. Multi-byte UTF-8 characters will be reversed byte-wise, which corrupts them; this is fine for ASCII only.

