```python
import random


def median(values):
    if not values:
        raise ValueError("median() requires at least one value")

    data = list(values)

    def partition(lo, hi, pivot_index):
        pivot = data[pivot_index]
        data[pivot_index], data[hi] = data[hi], data[pivot_index]
        store = lo
        for i in range(lo, hi):
            if data[i] < pivot:
                data[store], data[i] = data[i], data[store]
                store += 1
        data[store], data[hi] = data[hi], data[store]
        return store

    def select(k):
        lo, hi = 0, len(data) - 1
        while True:
            if lo == hi:
                return data[lo]
            pivot_index = random.randint(lo, hi)
            p = partition(lo, hi, pivot_index)
            if p == k:
                return data[p]
            if p < k:
                lo = p + 1
            else:
                hi = p - 1

    n = len(data)
    if n % 2 == 1:
        return float(select(n // 2))
    return (select(n // 2 - 1) + select(n // 2)) / 2.0


if __name__ == "__main__":
    print(median([3, 1, 2]))        # 2.0
    print(median([4, 2, 9, 7]))     # 5.5
    print(median([5]))              # 5.0
    print(median([-3.5, 0, 2.5]))   # 0.0
```
Quickselect averages O(n) and handles empty input with a clear error, odd/even lengths, and negative floats.

```rust
#[derive(Debug, PartialEq)]
pub enum StackError {
    Full,
}

#[derive(Debug)]
pub struct BoundedStack<T> {
    items: Vec<T>,
    capacity: usize,
}

impl<T> BoundedStack<T> {
    pub fn new(capacity: usize) -> Self {
        BoundedStack { items: Vec::new(), capacity }
    }

    pub fn push(&mut self, value: T) -> Result<(), StackError> {
        if self.items.len() >= self.capacity {
            return Err(StackError::Full);
        }
        self.items.push(value);
        Ok(())
    }

    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    pub fn peek(&self) -> Option<&T> {
        self.items.last()
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }
}

fn main() {
    let mut stack = BoundedStack::new(2);
    assert_eq!(stack.push("a"), Ok(()));
    assert_eq!(stack.push("b"), Ok(()));
    assert_eq!(stack.push("c"), Err(StackError::Full));
    assert_eq!(stack.len(), 2);
    assert_eq!(stack.peek(), Some(&"b"));
    assert_eq!(stack.pop(), Some("b"));
    assert_eq!(stack.pop(), Some("a"));
    assert_eq!(stack.pop(), None);
    assert!(stack.is_empty());
}
```
The cap is enforced on push; pop/peek stay total via Option and the derive gives testable equality.

