```cpp
#include <iostream>
#include <list>
#include <optional>
#include <stdexcept>
#include <string>
#include <unordered_map>

class LruCache {
public:
    explicit LruCache(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    std::optional<std::string> get(const std::string& key) {
        auto it = map_.find(key);
        if (it == map_.end()) return std::nullopt;
        order_.splice(order_.begin(), order_, it->second);
        return it->second->second;
    }

    void put(const std::string& key, const std::string& value) {
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->second = value;
            order_.splice(order_.begin(), order_, it->second);
            return;
        }
        if (order_.size() == capacity_) {
            const std::string& lru = order_.back().first;
            map_.erase(lru);
            order_.pop_back();
        }
        order_.emplace_front(key, value);
        map_[key] = order_.begin();
    }

private:
    std::size_t capacity_;
    std::list<std::pair<std::string, std::string>> order_;
    std::unordered_map<std::string, std::list<std::pair<std::string, std::string>>::iterator> map_;
};

int main() {
    LruCache cache(2);
    cache.put("a", "1");
    cache.put("b", "2");
    cache.get("a");           // refreshes "a"
    cache.put("c", "3");      // evicts "b"
    std::cout << cache.get("b").value_or("missing") << '\n';
    std::cout << cache.get("a").value_or("missing") << '\n';
    std::cout << cache.get("c").value_or("missing") << '\n';
}
```
The list holds recency order (front = newest); the map stores list iterators so every get and put is O(1) via splice.

