            raise ValueError(f"line {lineno}: missing '=' in {stripped!r}")
        key, value = stripped.split("=", 1)
        key, value = key.strip(), value.strip()
        if not key:
            raise ValueError(f"line {lineno}: empty key")
        config[key] = value
    return config


if __name__ == "__main__":
    sample = """
    # server settings
    host=127.0.0.1
    port=8080

    debug = true
    """
    print(parse_config(sample))
    # {'host': '127.0.0.1', 'port': '8080', 'debug': 'true'}
```
Comments and blank lines are skipped, later keys overwrite earlier ones, and malformed lines raise errors that name the line number instead of failing silently.

```cpp
#include <algorithm>
#include <iostream>

struct Rect {
    double x, y, w, h;  // top-left corner plus width and height
};

bool overlaps(const Rect& a, const Rect& b) {
    // strict overlap: edges/corners touching do NOT count
    return a.x < b.x + b.w && b.x < a.x + a.w &&
           a.y < b.y + b.h && b.y < a.y + a.h;
}

bool touches(const Rect& a, const Rect& b) {
    // non-strict: includes edges and corners sharing a boundary
    return a.x <= b.x + b.w && b.x <= a.x + a.w &&
           a.y <= b.y + b.h && b.y <= a.y + a.h;
}

int main() {
    Rect a{0, 0, 2, 2};
    Rect b{2, 2, 2, 2};   // shares only the corner (2,2)
    Rect c{3, 3, 2, 2};   // disjoint
    Rect d{1, 1, 2, 2};   // true overlap

    std::cout << std::boolalpha
              << "overlaps a,b: " << overlaps(a, b) << '\n'   // false
              << "touches  a,b: " << touches(a, b) << '\n'    // true
              << "overlaps a,c: " << overlaps(a, c) << '\n'   // false
              << "overlaps a,d: " << overlaps(a, d) << '\n';  // true
}
```
Using strict `<` for the overlap test treats an exactly shared edge or corner as non-overlapping, while `touches` uses `<=` for callers that need adjacency.

