```rust
fn reverse_bits(mut x: u32) -> u32 {
    let mut result: u32 = 0;
    for _ in 0..32 {
        result = (result << 1) | (x & 1);
        x >>= 1;
    }
    result
}

fn main() {
    assert_eq!(reverse_bits(0b1), 0b1000_0000_0000_0000_0000_0000_0000_0000);
    assert_eq!(reverse_bits(0), 0);
    assert_eq!(reverse_bits(u32::MAX), u32::MAX);
    assert_eq!(reverse_bits(0b1100), 0b0011 << 28);
    println!("{:#034b}", reverse_bits(0b1011));
}
