fn running_max(xs: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(xs.len());
    let mut best = i32::MIN;
    for &x in xs {
        if x > best {
            best = x;
        }
        out.push(best);
    }
    out
}

