#include <algorithm>
#include <cassert>
#include <numeric>
#include <iostream>
#include <vector>

double median(std::vector<int> v) {
    if (v.empty()) return 0.0;
    const size_t mid = v.size() / 2;
    std::nth_element(v.begin(), v.begin() + mid, v.end());
    const int hi = v[mid];
    if (v.size() % 2 == 1) return static_cast<double>(hi);
    const int lo = *std::max_element(v.begin(), v.begin() + mid);
    return (static_cast<double>(lo) + hi) / 2.0;
}

int main() {
    assert(median({5, 1, 3}) == 3.0);
    assert(median({4, 1, 9, 7}) == 5.5);
    assert(median({2}) == 2.0);
    assert(median({}) == 0.0);
    std::cout << median({9, 2, 8, 4, 6}) << "\n";
    return 0;
}
```

`std::nth_element` places the true median at index `mid` without sorting the rest, which is O(n) on average. For even sizes the lower half's maximum sits left of `mid`, so `max_element` recovers the second middle value. Empty input returns 0.0 explicitly.

