template <typename Range>
auto max_or_none(const Range& r) -> std::optional<typename Range::value_type> {
    auto it = r.begin();
    if (it == r.end()) {
        return std::nullopt;
    }
    auto best = *it;
    for (++it; it != r.end(); ++it) {
        if (*it > best) {
            best = *it;
        }
    }
    return best;
}

int main() {
    std::vector<int> empty;
    assert(max_or_none(empty) == std::nullopt);

    std::vector<int> vals{3, 9, 2, 9, 4};
    assert(max_or_none(vals) == 9);

    std::vector<double> d{-1.5, -0.25, -8.0};
    assert(max_or_none(d) == -0.25);

    std::cout << "ok\n";
    return 0;
}
