```c
#include <limits.h>
#include <stdbool.h>
#include <stdio.h>

/* Parse a base-10 signed integer. Returns true on success.
 * On overflow, *out is untouched and false is returned.
 * Leading/trailing spaces are skipped; an empty string fails. */
bool parse_int(const char *s, long long *out) {
    if (s == NULL || out == NULL) return false;
    while (*s == ' ' || *s == '\t' || *s == '\n') s++;

    bool neg = false;
    if (*s == '+' || *s == '-') {
        neg = (*s == '-');
        s++;
    }
    if (*s < '0' || *s > '9') return false;

    unsigned long long acc = 0;
    unsigned long long limit = neg ? (unsigned long long)LLONG_MAX + 1ULL
                                   : (unsigned long long)LLONG_MAX;
    while (*s >= '0' && *s <= '9') {
        unsigned digit = (unsigned)(*s - '0');
        if (acc > (limit - digit) / 10ULL) return false;  /* would overflow */
        acc = acc * 10ULL + digit;
        s++;
    }
    while (*s == ' ' || *s == '\t' || *s == '\n') s++;
    if (*s != '\0') return false;

    *out = neg ? -(long long)acc : (long long)acc;
    return true;
}

int main(void) {
    const char *cases[] = {"  42", "-7", "+0", "9223372036854775807",
                           "99999999999999999999", "", "12abc"};
    for (int i = 0; i < 7; i++) {
        long long v = 0;
        bool ok = parse_int(cases[i], &v);
        printf("%-24s -> %s %lld\n", cases[i], ok ? "ok" : "fail", ok ? v : 0LL);
    }
    return 0;
}
