class File {
public:
    File() noexcept = default;

    static File open(const std::string& path, const char* mode) {
        File f;
        f.fp_ = std::fopen(path.c_str(), mode);
        if (!f.fp_) f.error_ = std::string(std::strerror(errno));
        return f;
    }

    File(const File&) = delete;
    File& operator=(const File&) = delete;

    File(File&& other) noexcept
        : fp_(other.fp_), error_(std::move(other.error_)) {
        other.fp_ = nullptr;
    }
    File& operator=(File&& other) noexcept {
        if (this != &other) {
            close_noexcept();
            fp_ = other.fp_;
            error_ = std::move(other.error_);
            other.fp_ = nullptr;
        }
        return *this;
    }

    ~File() { close_noexcept(); }

    bool ok() const noexcept { return fp_ != nullptr; }
    const std::string& error() const noexcept { return error_; }
    std::FILE* get() const noexcept { return fp_; }

private:
    void close_noexcept() noexcept {
        if (fp_) {
            if (std::fclose(fp_) != 0)
                error_ = std::string(std::strerror(errno));
            fp_ = nullptr;
        }
    }

    std::FILE* fp_ = nullptr;
    std::string error_;
};

int main() {
    File f = File::open("definitely_missing.txt", "r");
    if (!f.ok()) {
        std::cout << "open failed: " << f.error() << '\n';
        return 0;
    }
    std::cout << "opened\n";
}
