#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

std::size_t edit_distance(const std::string& a, const std::string& b) {
    if (a.empty()) return b.size();
    if (b.empty()) return a.size();

    // Keep the shorter string on the inner axis to save memory.
    const std::string& s = (a.size() < b.size()) ? a : b;
    const std::string& t = (a.size() < b.size()) ? b : a;

    std::vector<std::size_t> prev(s.size() + 1), cur(s.size() + 1);
    for (std::size_t i = 0; i <= s.size(); ++i) prev[i] = i;

    for (std::size_t j = 1; j <= t.size(); ++j) {
        cur[0] = j;
        for (std::size_t i = 1; i <= s.size(); ++i) {
            const std::size_t cost = (s[i - 1] == t[j - 1]) ? 0 : 1;
            cur[i] = std::min({prev[i] + 1, cur[i - 1] + 1, prev[i - 1] + cost});
        }
        std::swap(prev, cur);
    }
    return prev[s.size()];
}

int main() {
    std::cout << edit_distance("kitten", "sitting") << '\n';  // 3
    std::cout << edit_distance("", "abc") << '\n';           // 3
    std::cout << edit_distance("same", "same") << '\n';      // 0
    std::cout << edit_distance("flaw", "lawn") << '\n';      // 2
}
