use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
pub enum ConfigError {
    MissingEquals(usize),
    EmptyKey(usize),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::MissingEquals(line) => write!(f, "line {}: no '=' found", line),
            ConfigError::EmptyKey(line) => write!(f, "line {}: empty key", line),
        }
    }
}

pub fn parse(input: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut out = HashMap::new();
    for (idx, raw) in input.lines().enumerate() {
        let line_no = idx + 1;
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            return Err(ConfigError::MissingEquals(line_no));
        };
        let key = key.trim();
        if key.is_empty() {
            return Err(ConfigError::EmptyKey(line_no));
        }
        out.insert(key.to_string(), value.trim().to_string());
    }
    Ok(out)
}

fn main() {
    let good = "# comment\nhost = localhost\nport=8080\n\nname = x\n";
    println!("{:?}", parse(good).unwrap());

    let bad = "host = ok\nbroken line\n";
    println!("{}", parse(bad).unwrap_err());
}
