#include <array>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(size_t capacity) : cap_(capacity), data_(capacity) {}

    bool push(int v) {
        if (size_ == cap_) return false;
        data_[(head_ + size_) % cap_] = v;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int v = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

    size_t size() const { return size_; }

private:
    size_t cap_, head_ = 0, size_ = 0;
    std::vector<int> data_;
};
