// Returns n! as unsigned long long, or -1 (ULLONG_MAX sentinel) on overflow.
unsigned long long factorialOrOverflow(int n) {
    if (n < 0) return static_cast<unsigned long long>(-1);
    if (n <= 1) return 1;
    unsigned long long prev = factorialOrOverflow(n - 1);
    if (prev == static_cast<unsigned long long>(-1)) return prev;
    if (prev > ULLONG_MAX / static_cast<unsigned long long>(n))
        return static_cast<unsigned long long>(-1);
    return prev * static_cast<unsigned long long>(n);
}

#include <cassert>
#include <iostream>
int main() {
    assert(factorialOrOverflow(0) == 1);
    assert(factorialOrOverflow(5) == 120);
    assert(factorialOrOverflow(-3) == static_cast<unsigned long long>(-1));
    assert(factorialOrOverflow(21) == static_cast<unsigned long long>(-1)); // overflows
    std::cout << "ok\n";
