template <typename T>
std::optional<T> parse_int(std::string_view text) {
    static_assert(std::is_integral_v<T>, "T must be an integral type");

    // Trim surrounding ASCII whitespace.
    auto begin = text.find_first_not_of(" \t\n\r\f\v");
    if (begin == std::string_view::npos) return std::nullopt;
    auto end = text.find_last_not_of(" \t\n\r\f\v") + 1;
    std::string_view trimmed = text.substr(begin, end - begin);

    T value{};
    auto [ptr, ec] = std::from_chars(trimmed.data(), trimmed.data() + trimmed.size(), value);
    if (ec != std::errc{} || ptr != trimmed.data() + trimmed.size()) return std::nullopt;
    return value;
}
