```rust
use std::sync::{mpsc, Arc, Mutex};
use std::thread;

type Job = Box<dyn FnOnce() + Send + 'static>;

pub struct ThreadPool {
    workers: Vec<Worker>,
    sender: Option<mpsc::Sender<Job>>,
}

impl ThreadPool {
    pub fn new(size: usize) -> ThreadPool {
        assert!(size > 0, "thread pool needs at least one worker");
        let (sender, receiver) = mpsc::channel::<Job>();
        let receiver = Arc::new(Mutex::new(receiver));
        let workers = (0..size)
            .map(|id| Worker::new(id, Arc::clone(&receiver)))
            .collect();
        ThreadPool { workers, sender: Some(sender) }
    }

    pub fn execute<F: FnOnce() + Send + 'static>(&self, f: F) {
        if let Some(sender) = &self.sender {
            sender.send(Box::new(f)).expect("worker pool is gone");
        }
    }
}

impl Drop for ThreadPool {
    fn drop(&mut self) {
        drop(self.sender.take());
        for worker in self.workers.drain(..) {
            if let Err(e) = worker.handle.join() {
                eprintln!("worker {} panicked: {:?}", worker.id, e);
            }
        }
    }
}

struct Worker {
    id: usize,
    handle: thread::JoinHandle<()>,
}

impl Worker {
    fn new(id: usize, receiver: Arc<Mutex<mpsc::Receiver<Job>>>) -> Worker {
        let handle = thread::spawn(move || loop {
            let job = {
                let guard = receiver.lock().unwrap();
                guard.recv()
            };
            match job {
                Ok(job) => job(),
                Err(_) => break, // sender dropped: shut down
            }
        });
        Worker { id, handle }
    }
}

fn main() {
    let pool = ThreadPool::new(4);
    for i in 0..8 {
        pool.execute(move || println!("job {i} on {:?}", thread::current().id()));
    }
} // pool dropped: joins all workers
```

Dropping the `Sender` closes the channel; each worker's `recv` then returns `Err` and the loop exits. `Drop` joins every handle so no job is lost mid-flight.

