uint64_t fib(int n) {
    if (n < 0) throw std::invalid_argument("n must be >= 0");
    if (n > 92) throw std::overflow_error("n too large for uint64_t");
    static std::vector<uint64_t> memo{0, 1};
    while ((int)memo.size() <= n) {
        memo.push_back(memo[memo.size() - 1] + memo[memo.size() - 2]);
    }
    return memo[n];
}

