```python
import heapq


def running_median(stream):
    """Return a list of medians after each element of the stream."""
    low = []   # max-heap (store negated)
    high = []  # min-heap
    medians = []
    for x in stream:
        if not low or x <= -low[0]:
            heapq.heappush(low, -x)
        else:
            heapq.heappush(high, x)
        if len(low) > len(high) + 1:
            heapq.heappush(high, -heapq.heappop(low))
        elif len(high) > len(low):
            heapq.heappush(low, -heapq.heappop(high))
        if len(low) == len(high):
            medians.append((-low[0] + high[0]) / 2)
        else:
            medians.append(float(-low[0]))
    return medians


if __name__ == "__main__":
    assert running_median([1, 2, 3, 4]) == [1.0, 1.5, 2.0, 2.5]
    assert running_median([]) == []
    assert running_median([5]) == [5.0]
    assert running_median([2, 2, 2, 2]) == [2.0, 2.0, 2.0, 2.0]
    assert running_median([-1, -2, -3]) == [-1.0, -1.5, -2.0]
    print("all tests passed")
```

Each value arrives in O(log n) and the median is read in O(1), so the whole stream costs O(n log n). Empty input yields an empty list rather than an error.

```python
class Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def parse(self):
        value = self.expr()
        self.skip_ws()
        if self.pos != len(self.text):
            raise ValueError(f"unexpected {self.text[self.pos]!r} at {self.pos}")
        return value

    def skip_ws(self):
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1

    def peek(self):
        self.skip_ws()
        return self.text[self.pos] if self.pos < len(self.text) else None

    def expr(self):
        value = self.term()
        while self.peek() in ("+", "-"):
            op = self.text[self.pos]
            self.pos += 1
            rhs = self.term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def term(self):
        value = self.factor()
        while self.peek() in ("*", "/"):
            op = self.text[self.pos]
            self.pos += 1
            rhs = self.factor()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value /= rhs
        return value

    def factor(self):
        if self.peek() == "-":
            self.pos += 1
            return -self.factor()
        if self.peek() == "+":
            self.pos += 1
            return self.factor()
        if self.peek() == "(":
            self.pos += 1
            value = self.expr()
            if self.peek() != ")":
                raise ValueError("missing closing parenthesis")
            self.pos += 1
            return value
        return self.number()

    def number(self):
        start = self.pos
        seen_dot = False
        while self.pos < len(self.text):
            ch = self.text[self.pos]
            if ch.isdigit():
                self.pos += 1
            elif ch == "." and not seen_dot:
                seen_dot = True
                self.pos += 1
            else:
                break
        if start == self.pos:
            raise ValueError(f"expected number at {self.pos}")
        return float(self.text[start:self.pos])


def evaluate(text):
    return Parser(text).parse()


if __name__ == "__main__":
    assert evaluate("1 + 2 * 3") == 7.0
    assert evaluate("(1 + 2) * 3") == 9.0
    assert evaluate("-3 + 4") == 1.0
    assert evaluate("-(2 + 3)") == -5.0
    assert evaluate("10 / 4") == 2.5
    assert evaluate("2 * (3 + (4 - 1))") == 12.0
    print("all tests passed")
```

Recursive descent: `expr` handles addition and subtraction, `term` handles multiplication and division, `factor` handles unary signs and parentheses. Malformed input and division by zero raise rather than returning a wrong number.

