#include <iostream>
#include <vector>

int binarySearch(const std::vector<int>& nums, int target) {
    int lo = 0;
    int hi = static_cast<int>(nums.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;  // avoids overflow
        if (nums[mid] == target) {
            return mid;
        }
        if (nums[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    const std::vector<int> nums = {-9, -3, 0, 2, 5, 7, 11, 42};
    std::cout << binarySearch(nums, 5) << "\n";    // 4
    std::cout << binarySearch(nums, -9) << "\n";   // 0
    std::cout << binarySearch(nums, 42) << "\n";   // 7
    std::cout << binarySearch(nums, 3) << "\n";    // -1

    const std::vector<int> empty;
    std::cout << binarySearch(empty, 1) << "\n";   // -1
    return 0;
}
```

`mid` is computed as `lo + (hi - lo) / 2` to avoid integer overflow on large indices. An empty vector gives `hi = -1`, so the loop never runs and it returns -1.

