use std::collections::HashMap;

fn top_k_words(text: &str, k: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count desc, then word asc for stable output.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(k);
    pairs
}

fn main() {
    let text = "the quick brown fox jumps over the lazy dog The DOG";
    let result = top_k_words(text, 3);
    assert_eq!(result, vec![
        ("dog".to_string(), 2),
        ("the".to_string(), 2),
        ("brown".to_string(), 1),
    ]);

    assert!(top_k_words("", 5).is_empty());
    assert!(top_k_words("   ", 5).is_empty());
    assert_eq!(top_k_words("aaa", 10).len(), 1);
    println!("all tests passed");
}
```

Splitting on `split_whitespace` handles repeated and leading spaces, filtering on `is_alphanumeric` strips punctuation, lowercasing makes the match case-insensitive, and the sort breaks count ties by word so the output order is deterministic. An empty input yields an empty vector.

```rust
struct Scan<I, F, T> {
    iter: I,
    f: F,
    state: T,
    started: bool,
}

impl<I, F, T> Iterator for Scan<I, F, T>
where
    I: Iterator,
    F: FnMut(&mut T, I::Item) -> T,
    T: Clone,
{
    type Item = T;

    fn next(&mut self) -> Option<T> {
        let item = self.iter.next()?;
        if !self.started {
            self.state = (self.f)(&mut self.state, item);
            self.started = true;
        } else {
            self.state = (self.f)(&mut self.state, item);
        }
        Some(self.state.clone())
    }
}

fn scan<I, F, T>(iter: I, init: T, f: F) -> Scan<I, F, T>
where
    I: Iterator,
    F: FnMut(&mut T, I::Item) -> T,
    T: Clone,
{
    Scan { iter, f, state: init, started: false }
}

fn main() {
    let running: Vec<i32> = scan(vec![1, 2, 3, 4].into_iter(), 0, |acc, x| *acc + x).collect();
    assert_eq!(running, vec![1, 3, 6, 10]);

    let empty: Vec<i32> = scan(Vec::<i32>::new().into_iter(), 0, |acc, x| *acc + x).collect();
    assert!(empty.is_empty());

    let running_max: Vec<i32> = scan(vec![-5, 3, 0, 9].into_iter(), i32::MIN, |acc, x| (*acc).max(x)).collect();
    assert_eq!(running_max, vec![-5, 3, 3, 9]);
    println!("all tests passed");
}
```

The adapter is lazy: it holds no buffered output and advances the underlying iterator only when `next` is called, so an infinite source produces a lazy infinite stream of sums. `state.clone()` is sent out while the private accumulator keeps ticking.

