#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) {
        return;
    }
    size_t len = strlen(s);
    if (len < 2) {
        return;
    }
    size_t i = 0;
    size_t j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    printf("%s\n", a);          // olleh

    char b[] = "ab";
    reverse_in_place(b);
    printf("%s\n", b);          // ba

    char c[] = "x";
    reverse_in_place(c);
    printf("%s\n", c);          // x

    char d[] = "";
    reverse_in_place(d);
    printf("[%s]\n", d);        // []

    reverse_in_place(NULL);      // no crash
    printf("done\n");
    return 0;
}
```

Two indices walk toward the middle swapping bytes, which stops naturally on a single character or an empty string. `NULL` and strings shorter than two characters return without touching memory. The buffers in `main` are real arrays (not string literals) so in-place mutation is legal.

