import heapq

def dijkstra(graph, start):
    """graph: {node: {neighbor: weight}}. Returns {node: dist}."""
    dist = {node: float('inf') for node in graph}
    if start not in graph:
        return dist
    dist[start] = 0
    pq = [(0, start)]
    visited = set()

    while pq:
        d, node = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        for neighbor, w in graph[node].items():
            if w < 0:
                raise ValueError("negative weight not supported")
            nd = d + w
            if nd < dist.get(neighbor, float('inf')):
                dist[neighbor] = nd
                heapq.heappush(pq, (nd, neighbor))
    return dist

if __name__ == "__main__":
    g = {
        'A': {'B': 1, 'C': 4},
        'B': {'C': 2, 'D': 5},
        'C': {'D': 1},
        'D': {},
        'E': {'A': 1},
    }
    print(dijkstra(g, 'A'))  # A:0 B:1 C:3 D:4 E:inf
    print(dijkstra(g, 'E'))  # E:0 A:1 B:2 C:4 D:5
