std::optional<int> parse_int(const char* s) {
    if (s == nullptr) return std::nullopt;
    while (std::isspace(static_cast<unsigned char>(*s))) ++s;
    bool neg = false;
    if (*s == '+' || *s == '-') { neg = (*s == '-'); ++s; }
    if (!std::isdigit(static_cast<unsigned char>(*s))) return std::nullopt;

    long long acc = 0;
    while (std::isdigit(static_cast<unsigned char>(*s))) {
        acc = acc * 10 + (*s - '0');
        if (acc > static_cast<long long>(INT_MAX) + 1) return std::nullopt;
        ++s;
    }
    while (std::isspace(static_cast<unsigned char>(*s))) ++s;
    if (*s != '\0') return std::nullopt;

    if (neg) acc = -acc;
    if (acc < INT_MIN || acc > INT_MAX) return std::nullopt;
    return static_cast<int>(acc);
}

