import functools
import random
import time

def retry(exceptions=(Exception,), tries=3, base=0.1, factor=2.0, max_delay=5.0):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            delay = base
            last = None
            for attempt in range(1, tries + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt == tries:
                        break
                    sleep_for = min(delay, max_delay) * (0.5 + random.random())
                    time.sleep(sleep_for)
                    delay *= factor
            raise last
        return wrapper
    return deco

import unittest

class TestRetry(unittest.TestCase):
    def test_succeeds_after_failures(self):
        calls = {"n": 0}
        @retry(exceptions=(ValueError,), tries=4, base=0.0)
        def flaky():
            calls["n"] += 1
            if calls["n"] < 3:
                raise ValueError("boom")
            return "ok"
        self.assertEqual(flaky(), "ok")
        self.assertEqual(calls["n"], 3)

    def test_reraises_other(self):
        @retry(exceptions=(ValueError,), tries=2, base=0.0)
        def other():
            raise KeyError("nope")
        with self.assertRaises(KeyError):
            other()

if __name__ == "__main__":
    # no sleep in the demo path
    print("run with unittest")
    unittest.main(exit=False)
