def normalize_email(raw):
    """Return (normalized, reason). normalized is None when invalid."""
    if not isinstance(raw, str):
        return None, "not a string"
    s = raw.strip()
    if not s:
        return None, "empty"
    if s.count('@') != 1:
        return None, "must contain exactly one @"
    local, _, domain = s.partition('@')
    if not local:
        return None, "empty local part"
    if not domain:
        return None, "empty domain"
    if '.' not in domain:
        return None, "domain has no dot"
    if domain.startswith('.') or domain.endswith('.') or '..' in domain:
        return None, "bad domain dots"
    if any(c.isspace() for c in s):
        return None, "contains whitespace"
