```cpp
#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size()) - 1;

    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (data[mid] == target) {
            return mid;
        } else if (data[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    const std::vector<int> data = {};
    const std::vector<int> nums = {1, 3, 3, 5, 8, 13, 21};

    std::cout << "empty: " << binary_search(data, 5) << "\n";
    std::cout << "first: " << binary_search(nums, 1) << "\n";
    std::cout << "dup:   " << binary_search(nums, 3) << "\n";
    std::cout << "last:  " << binary_search(nums, 21) << "\n";
    std::cout << "miss:  " << binary_search(nums, 4) << "\n";
}
```

`mid` is computed with `lo + (hi - lo) / 2` to avoid overflow on large ranges, and `hi` is `size() - 1` cast to `int`, so an empty vector leaves `hi = -1` and the loop is skipped cleanly.

