def primes_below(n):
    """Yield all primes strictly less than n using a sieve of Eratosthenes."""
    if n < 2:
        return
    sieve = bytearray([1]) * n
    sieve[0] = sieve[1] = 0
    i = 2
    while i * i < n:
        if sieve[i]:
            sieve[i * i:n:i] = bytearray(len(range(i * i, n, i)))
        i += 1
    for value, is_prime in enumerate(sieve):
        if is_prime:
            yield value


