#include <array>
#include <cassert>
#include <cstddef>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    assert(rb.empty());
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(!rb.push(4));
    assert(rb.pop() == 1);
    assert(rb.push(4));
    assert(rb.pop() == 2);
    assert(rb.size() == 2);
    return 0;
}
```

