```rust
use std::thread::sleep;
use std::time::Duration;

fn retry<T, E, F>(mut attempts: u32, mut op: F) -> Result<T, E>
where
    F: FnMut() -> Result<T, E>,
{
    let mut delay = Duration::from_millis(50);
    let cap = Duration::from_millis(800);
    loop {
        match op() {
            Ok(value) => return Ok(value),
            Err(err) => {
                attempts = attempts.saturating_sub(1);
                if attempts == 0 {
                    return Err(err);
                }
                sleep(delay);
                delay = (delay * 2).min(cap);
            }
        }
    }
}

fn main() {
    let mut calls = 0;
    let result: Result<i32, &str> = retry(3, || {
        calls += 1;
        if calls < 3 { Err("boom") } else { Ok(42) }
    });
    assert_eq!(result, Ok(42));
    assert_eq!(calls, 3);

    let mut always = 0;
    let failed: Result<i32, &str> = retry(4, || {
        always += 1;
        Err("nope")
    });
    assert!(failed.is_err());
    assert_eq!(always, 4, "must not retry past the budget");
    println!("ok");
}
```

`attempts` counts total tries, so `retry(3, …)` can run at most 3 times. Backoff doubles from 50 ms and is clamped at 800 ms.

