#[derive(Debug, PartialEq)]
struct Node {
    value: i32,
    next: Option<Box<Node>>,
}

fn reverse(mut head: Option<Box<Node>>) -> Option<Box<Node>> {
    let mut prev: Option<Box<Node>> = None;
    while let Some(mut node) = head {
        head = node.next.take();
        node.next = prev;
        prev = Some(node);
    }
    prev
}

fn build(vals: &[i32]) -> Option<Box<Node>> {
    vals.iter().rev().fold(None, |next, &value| {
        Some(Box::new(Node { value, next }))
    })
}

fn collect(n: &Option<Box<Node>>, out: &mut Vec<i32>) {
    let mut cur = n;
    while let Some(node) = cur {
        out.push(node.value);
        cur = &node.next;
    }
}

fn main() {
    let list = build(&[1, 2, 3]);
    let rev = reverse(list);
    let mut got = Vec::new();
    collect(&rev, &mut got);
    assert_eq!(got, vec![3, 2, 1]);
    assert!(reverse(None).is_none());
    println!("ok");
}
