```cpp
#include <algorithm>
#include <iostream>
#include <string>

std::string reverseWords(std::string s) {
    // Reverse the whole string, then reverse each word back.
    std::reverse(s.begin(), s.end());
    const int n = static_cast<int>(s.size());
    int read = 0, write = 0;
    while (read < n) {
        while (read < n && s[read] == ' ') ++read;
        if (read == n) break;
        if (write > 0) s[write++] = ' ';
        int start = write;
        while (read < n && s[read] != ' ') s[write++] = s[read++];
        std::reverse(s.begin() + start, s.begin() + write);
    }
    s.resize(write);
    return s;
}

int main() {
    std::cout << '[' << reverseWords("  the sky   is blue  ") << ']' << '\n';
    std::cout << '[' << reverseWords("") << ']' << '\n';
    std::cout << '[' << reverseWords("one") << ']' << '\n';
    return 0;
}
```

Reversing the whole string places words in reverse order but each one backwards. The single write pass copies characters forward while skipping runs of spaces, then reverses each word segment `[start, write)` to restore letter order. Edges handled: leading/trailing spaces, multiple spaces, empty and one-word input. Output is `[blue is sky the]`, `[]`, `[one]`.

