    std::ptrdiff_t hi = static_cast<std::ptrdiff_t>(data.size()) - 1;
    while (lo <= hi) {
        const std::ptrdiff_t mid = lo + (hi - lo) / 2;  // no overflow
        if (data[static_cast<std::size_t>(mid)] < target) {
            lo = mid + 1;
        } else if (target < data[static_cast<std::size_t>(mid)]) {
            hi = mid - 1;
        } else {
            return mid;
        }
    }
    return -1;
}

int main() {
    const std::vector<int> v{1, 3, 5, 7, 9, 11};
    std::cout << binarySearch(v, 7) << '\n';   // 3
    std::cout << binarySearch(v, 1) << '\n';   // 0
    std::cout << binarySearch(v, 11) << '\n';  // 5
    std::cout << binarySearch(v, 4) << '\n';   // -1
    const std::vector<int> empty;
    std::cout << binarySearch(empty, 0) << '\n';  // -1
    return 0;
}
```

Using `lo + (hi - lo) / 2` avoids overflow that `(lo + hi) / 2` can hit. The template deduces both the container type and the element type, so it accepts `std::vector`, `std::array`, or anything with `size()` and `operator[]`. An empty container sets `hi` to -1 and the loop never runs, returning -1.

