```rust
use std::collections::HashMap;

struct LruCache<K, V> {
    capacity: usize,
    map: HashMap<K, usize>,
    keys: Vec<Option<K>>,
    values: Vec<Option<V>>,
    prev: Vec<usize>,
    next: Vec<usize>,
    head: usize,
    tail: usize,
    free: Vec<usize>,
}

const NIL: usize = usize::MAX;

impl<K: Eq + std::hash::Hash + Clone, V> LruCache<K, V> {
    fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        LruCache {
            capacity,
            map: HashMap::new(),
            keys: Vec::new(),
            values: Vec::new(),
            prev: Vec::new(),
            next: Vec::new(),
            head: NIL,
            tail: NIL,
            free: Vec::new(),
        }
    }

    fn unlink(&mut self, idx: usize) {
        let (p, n) = (self.prev[idx], self.next[idx]);
        if p != NIL {
            self.next[p] = n;
        } else {
            self.head = n;
        }
        if n != NIL {
            self.prev[n] = p;
        } else {
            self.tail = p;
        }
    }

    fn push_front(&mut self, idx: usize) {
        self.prev[idx] = NIL;
        self.next[idx] = self.head;
        if self.head != NIL {
            self.prev[self.head] = idx;
        }
        self.head = idx;
        if self.tail == NIL {
            self.tail = idx;
        }
    }

    fn touch(&mut self, idx: usize) {
        if self.head == idx {
            return;
        }
        self.unlink(idx);
        self.push_front(idx);
    }

    fn get(&mut self, key: &K) -> Option<&V> {
        match self.map.get(key).copied() {
            Some(idx) => {
                self.touch(idx);
                self.values[idx].as_ref()
            }
            None => None,
        }
    }

    fn put(&mut self, key: K, value: V) {
        if let Some(&idx) = self.map.get(&key) {
            self.values[idx] = Some(value);
            self.touch(idx);
            return;
        }
        let idx = match self.free.pop() {
            Some(i) => {
                self.keys[i] = Some(key.clone());
                self.values[i] = Some(value);
                i
            }
            None => {
                let i = self.keys.len();
                self.keys.push(Some(key.clone()));
                self.values.push(Some(value));
                self.prev.push(NIL);
                self.next.push(NIL);
                i
            }
        };
        self.map.insert(key, idx);
        self.push_front(idx);
        if self.map.len() > self.capacity {
            let victim = self.tail;
            self.unlink(victim);
            if let Some(k) = self.keys[victim].take() {
                self.map.remove(&k);
            }
            self.values[victim] = None;
            self.free.push(victim);
        }
    }

    fn len(&self) -> usize {
        self.map.len()
    }
}

fn main() {
    let mut cache: LruCache<&str, i32> = LruCache::new(2);
    cache.put("a", 1);
    cache.put("b", 2);
    assert_eq!(cache.get(&"a"), Some(&1));
    cache.put("c", 3); // evicts "b"
    assert_eq!(cache.get(&"b"), None);
    assert_eq!(cache.get(&"a"), Some(&1));
    assert_eq!(cache.get(&"c"), Some(&3));
    assert_eq!(cache.len(), 2);
    println!("lru ok");
}
```

Slots are stored in vectors with `prev`/`next` indices forming the recency list; `head` is most recent, `tail` least. On eviction we take the tail key, remove it from the map, clear the value, and push the slot onto `free` for reuse. `touch` only relinks when the item is not already at the head. Capacity is asserted positive so the eviction branch is always safe.

```python
from typing import Iterator, List, Optional


class RingBuffer:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._data: List[Optional[int]] = [None] * capacity
        self._head = 0  # index of oldest element
        self._size = 0

    def append(self, value: int) -> None:
        idx = (self._head + self._size) % self._capacity
        self._data[idx] = value
        if self._size < self._capacity:
            self._size += 1
        else:
            self._head = (self._head + 1) % self._capacity

    def pop_front(self) -> int:
        if self._size == 0:
            raise IndexError("pop from empty ring buffer")
        value = self._data[self._head]
        self._data[self._head] = None
        self._head = (self._head + 1) % self._capacity
        self._size -= 1
        return value  # type: ignore[return-value]

    def __len__(self) -> int:
        return self._size

    def __iter__(self) -> Iterator[int]:
        for i in range(self._size):
            value = self._data[(self._head + i) % self._capacity]
            assert value is not None
            yield value


if __name__ == "__main__":
    rb = RingBuffer(3)
    for v in (10, 20, 30, 40):
        rb.append(v)
    assert list(rb) == [20, 30, 40]
    assert rb.pop_front() == 20
    assert list(rb) == [30, 40]
    rb.append(50)
    assert list(rb) == [30, 40, 50]
    assert len(rb) == 3
    while rb:
        rb.pop_front()
    try:
        rb.pop_front()
        raise AssertionError("expected IndexError")
    except IndexError:
        pass
    print("ring buffer ok")
```

Writes go to `(head + size) % capacity`; once full, the head advances, so the oldest slot is overwritten. `pop_front` clears the slot and advances the head modulo capacity. Iteration walks `size` slots starting at the head, which yields insertion order without copying. An empty pop raises `IndexError`, matching list semantics.

