#include <algorithm>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

std::vector<long long> parseCsv(const std::string& line) {
    std::vector<long long> values;
    std::stringstream ss(line);
    std::string field;
    while (std::getline(ss, field, ',')) {
        const auto first = field.find_first_not_of(" \t");
        const auto last = field.find_last_not_of(" \t");
        if (first == std::string::npos) continue;  // blank field
        const std::string token = field.substr(first, last - first + 1);
        try {
            std::size_t consumed = 0;
            const long long value = std::stoll(token, &consumed);
            if (consumed != token.size()) {
                std::cerr << "warning: skipping malformed field: '" << token << "'\n";
                continue;
            }
            values.push_back(value);
        } catch (const std::exception&) {
            std::cerr << "warning: skipping malformed field: '" << token << "'\n";
        }
    }
    return values;
}

int main() {
    const std::string line = "3, 1 , 4,, 1, 5 ,9,abc,2";
    std::vector<long long> values = parseCsv(line);
    std::sort(values.begin(), values.end());
    values.erase(std::unique(values.begin(), values.end()), values.end());
    for (std::size_t i = 0; i < values.size(); ++i) {
        std::cout << values[i] << (i + 1 == values.size() ? '\n' : ' ');
    }
    return 0;
}
```

`std::getline` with a comma delimiter handles empty fields; trimming uses `find_first_not_of`/`find_last_not_of` so spaces around numbers are ignored. `stoll` with a `consumed` check rejects trailing garbage like `9x`. Sort plus `unique`/`erase` deduplicates. For this input the output is `1 2 3 4 5 9`, and malformed fields are reported to stderr, not silently counted.

