#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

int main() {
    Node* head = nullptr;
    Node* tail = nullptr;
    for (int v : {1, 2, 3, 4}) {
        Node* n = new Node(v);
        if (!head) head = tail = n;
        else { tail->next = n; tail = n; }
    }
    head = reverse(head);
    for (Node* p = head; p; p = p->next) std::cout << p->value << ' ';
    std::cout << '\n';
    while (head) { Node* nxt = head->next; delete head; head = nxt; }
    return 0;
}
```

Three pointers walk the list in place: save `next` before rewiring, point the current node backward, then advance. An empty list returns `nullptr` immediately, so `reverse(nullptr)` is safe. Memory is freed after printing.

