fn is_palindrome(s: &str) -> bool {
    let chars: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();
    let (mut i, mut j) = (0usize, chars.len().saturating_sub(1));
    while i < j {
        if chars[i] != chars[j] {
            return false;
        }
        i += 1;
        j -= 1;
    }
    true
}

fn main() {
    assert!(is_palindrome("A man, a plan, a canal: Panama"));
    assert!(is_palindrome(""));
    assert!(is_palindrome("!!"));
    assert!(!is_palindrome("hello"));
    assert!(is_palindrome("Är det ö"));
    println!("ok");
}
```

`flat_map(c.to_lowercase())` handles multi-character lowercase expansions instead of assuming one-to-one. Filtering before lowering means punctuation is dropped cheaply. `saturating_sub(1)` keeps the empty case from underflowing, and the empty filtered vector yields `true`.

```rust
fn fib(n: u32) -> Option<u128> {
    match n {
        0 => Some(0),
        1 => Some(1),
        _ => {
            let (mut a, mut b) = (0u128, 1u128);
            for _ in 2..=n {
                let next = a.checked_add(b)?;
                a = b;
                b = next;
            }
            Some(b)
        }
    }
}

fn main() {
    assert_eq!(fib(0), Some(0));
    assert_eq!(fib(10), Some(55));
    assert_eq!(fib(100), Some(354224848179261915075));
    assert_eq!(fib(300), None);
    println!("ok");
}
```

It iterates instead of recursing, so it runs in O(n) time and O(1) space, avoiding the exponential blowup a naive recursive version has. `checked_add` returns `None` the moment a Fibonacci value would exceed `u128`, so `fib(300)` reports failure rather than wrapping silently.

```c
#include <stdio.h>
#include <stdlib.h>

int copy_file(const char *src, const char *dst) {
    FILE *in = fopen(src, "rb");
    if (!in) { perror(src); return -1; }
    FILE *out = fopen(dst, "wb");
    if (!out) { perror(dst); fclose(in); return -1; }

    unsigned char buf[8192];
    size_t n;
    while ((n = fread(buf, 1, sizeof buf, in)) > 0) {
        size_t written = 0;
        while (written < n) {
            size_t k = fwrite(buf + written, 1, n - written, out);
            if (k == 0) {
                if (ferror(out)) { perror("write"); fclose(in); fclose(out); return -1; }
                break;
            }
            written += k;
        }
    }
    if (ferror(in)) { perror("read"); fclose(in); fclose(out); return -1; }

    fclose(in);
    if (fclose(out) != 0) { perror("close"); return -1; }
    return 0;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s <src> <dst>\n", argv[0]);
        return 2;
    }
    return copy_file(argv[1], argv[2]) == 0 ? 0 : 1;
}
```

Binary mode (`"rb"`/`"wb"`) avoids newline translation on Windows. The inner loop handles a short `fwrite` by advancing an offset rather than assuming the whole chunk landed at once. `fclose` on the output is checked because buffered write errors often surface only at close.

