fn all_unique(s: &str) -> bool {
    let mut seen_ascii = [0u64; 2];
    let mut seen_uni: Vec<char> = Vec::new();
    for c in s.chars() {
        let u = c as u32;
        if u < 128 {
            let idx = (u / 64) as usize;
            let bit = 1u64 << (u % 64);
            if seen_ascii[idx] & bit != 0 {
                return false;
            }
            seen_ascii[idx] |= bit;
        } else if seen_uni.contains(&c) {
            return false;
        } else {
            seen_uni.push(c);
        }
    }
    true
}

