#include <iostream>
#include <optional>
#include <vector>

template <typename T>
class RingBuffer {
    std::vector<T> buf_;
    std::size_t head_ = 0, tail_ = 0, size_ = 0;
public:
    explicit RingBuffer(std::size_t cap) : buf_(cap) {}

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return buf_.size(); }

    bool push(const T& v) {
        if (size_ == buf_.size()) return false;
        buf_[tail_] = v;
        tail_ = (tail_ + 1) % buf_.size();
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T v = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return v;
    }
};

int main() {
    RingBuffer<int> rb(3);
