void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t i = 0, j = strlen(s);
    while (i + 1 < j) {
        char t = s[i];
        s[i] = s[j - 1];
        s[j - 1] = t;
        i++;
        j--;
    }
