fn fib(n: u32) -> u64 {
    let mut a: u64 = 0;
    let mut b: u64 = 1;
    for _ in 0..n {
        let next = a.wrapping_add(b);
        a = b;
        b = next;
    }
    a
}

fn main() {
    for n in [0u32, 1, 2, 10, 90] {
        println!("fib({}) = {}", n, fib(n));
    }
    // fib(93) exceeds u64::MAX; detect overflow explicitly.
    let n = 93u32;
    let mut a: u64 = 0;
    let mut b: u64 = 1;
    let mut overflow = false;
    for _ in 0..n {
        match a.checked_add(b) {
            Some(next) => { a = b; b = next; }
            None => { overflow = true; break; }
        }
    }
    println!("fib(93) overflows u64: {}", overflow);
}
```

`fib` is O(n) time, O(1) space. `fib(90)` fits in `u64` (max is `fib(93)`), and the second block uses `checked_add` to prove that `fib(93)` overflows rather than silently wrapping.

