template <typename T>
std::vector<T> dedupe_preserving_order(const std::vector<T>& in) {
    std::vector<T> out;
    std::unordered_set<T> seen;
    out.reserve(in.size());
    for (const auto& v : in) {
        if (seen.insert(v).second) {
            out.push_back(v);
        }
    }
    return out;
}

int main() {
    std::vector<int> v = {3, 1, 3, 2, 1, 4};
    auto r = dedupe_preserving_order(v);
    for (size_t i = 0; i < r.size(); ++i) std::cout << r[i] << (i + 1 < r.size() ? ' ' : '\n');
    std::vector<std::string> e;
    std::cout << dedupe_preserving_order(e).size() << '\n';
}
```

`unordered_set::insert` returns a pair whose `second` is true only on first insertion, so `out` keeps the original order and duplicates are skipped in one pass. Average time is O(n); the empty input returns an empty vector.

```python
import ast
import operator

_OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
        ast.Div: operator.truediv, ast.Pow: operator.pow, ast.USub: operator.neg,
        ast.Mod: operator.mod}

def safe_eval(expr):
    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.BinOp) and type(node.op) in _OPS:
            return _OPS[type(node.op)](_eval(node.left), _eval(node.right))
        if isinstance(node, ast.UnaryOp) and type(node.op) in _OPS:
            return _OPS[type(node.op)](_eval(node.operand))
        raise ValueError(f"unsupported expression: {ast.dump(node)}")
    return _eval(ast.parse(expr, mode="eval"))

if __name__ == "__main__":
    for e in ["2 + 3 * 4", "-(5 % 3)", "2 ** 10"]:
        print(e, "=", safe_eval(e))
    for bad in ["__import__('os')", "x + 1", "1 / 0"]:
        try:
            safe_eval(bad)
        except Exception as exc:
            print(bad, "->", type(exc).__name__)
```

Only `Constant`, `BinOp`, and `UnaryOp` nodes are accepted, so names and function calls raise `ValueError`; `1 / 0` still raises `ZeroDivisionError`, which the caller can catch. Never use bare `eval` for this.

