// Returns index of the FIRST occurrence of target, or -1.
int lower_bound_index(const std::vector<int>& a, int target) {
    int lo = 0, hi = static_cast<int>(a.size());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    if (lo < static_cast<int>(a.size()) && a[lo] == target) return lo;
    return -1;
}

int main() {
    std::vector<int> a{1, 2, 2, 2, 3, 5};
    std::cout << lower_bound_index(a, 2) << "\n";  // 1
    std::cout << lower_bound_index(a, 4) << "\n";  // -1
    std::cout << lower_bound_index({}, 7) << "\n";  // -1
    return 0;
}
