#include <stdio.h>
#include <stdlib.h>

struct entry {
    unsigned long count;
    int byte;
};

static int cmp_desc(const void *a, const void *b) {
    const struct entry *x = a;
    const struct entry *y = b;
    if (x->count != y->count) {
        return (x->count < y->count) ? 1 : -1;
    }
    return x->byte - y->byte;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s FILE\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror(argv[1]);
        return 1;
    }

    unsigned long counts[256] = {0};
    int c;
    while ((c = fgetc(f)) != EOF) {
        counts[(unsigned char)c]++;
    }
    fclose(f);

    struct entry table[256];
    for (int i = 0; i < 256; i++) {
        table[i].byte = i;
        table[i].count = counts[i];
    }
    qsort(table, 256, sizeof table[0], cmp_desc);

    for (int i = 0; i < 10 && table[i].count > 0; i++) {
        int b = table[i].byte;
        printf("%3d %-6s %lu\n", b, (b >= 32 && b < 127) ? (char[]){b, 0} : "-", table[i].count);
    }
    return 0;
}
