import functools
import random
import time


def retry(attempts=4, base=0.1, cap=5.0, exceptions=(Exception,)):
    """Retry the wrapped function up to `attempts` times total."""
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    def decorate(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt == attempts - 1:
                        break
                    delay = min(cap, base * (2 ** attempt))
                    time.sleep(delay + random.uniform(0, delay / 2))
            raise last

        return wrapper

    return decorate


@retry(attempts=3, base=0.01)
def flaky(fail_until):
    flaky.calls += 1
    if flaky.calls < fail_until:
        raise RuntimeError(f"attempt {flaky.calls} failed")
    return "ok"


flaky.calls = 0
print(flaky(3))
```

`functools.wraps` keeps the wrapped function's name and docstring. The final failure re-raises the original exception rather than wrapping it.

