Splitting on any non-alphanumeric char handles punctuation, and `to_lowercase` folds case. The empty string yields an empty map. Unicode letters split correctly since `is_alphanumeric` is Unicode-aware.

```python
VALUES = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]


def to_roman(n: int) -> str:
    if not 1 <= n <= 3999:
        raise ValueError(f"out of range: {n}")
    out = []
    for value, symbol in VALUES:
        while n >= value:
            out.append(symbol)
            n -= value
    return "".join(out)


SYMBOLS = {"I": 1, "V": 5, "X": 10, "L": 50,
           "C": 100, "D": 500, "M": 1000}


def from_roman(s: str) -> int:
    s = s.upper()
    if not s:
        raise ValueError("empty numeral")
    total = 0
    prev = 0
    for ch in reversed(s):
        if ch not in SYMBOLS:
            raise ValueError(f"bad symbol: {ch}")
        value = SYMBOLS[ch]
        if value < prev:
            total -= value
        else:
            total += value
            prev = value
    return total


if __name__ == "__main__":
    for n in (1, 4, 9, 14, 40, 90, 400, 1990, 3999):
        assert from_roman(to_roman(n)) == n
    assert to_roman(3999) == "MMMCMXCIX"
    try:
        to_roman(0)
    except ValueError as e:
        print("caught:", e)
```

The greedy `VALUES` list handles subtractive pairs like CM and IX in one pass. The reverse walk subtracts a symbol smaller than the running max so validation and decoding share one loop.

```c
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

#define RB_CAP 8

typedef struct {
    unsigned char data[RB_CAP];
    size_t head;
    size_t tail;
    size_t count;
} Ring;

static void rb_init(Ring *r) {
    memset(r, 0, sizeof *r);
}

static bool rb_push(Ring *r, unsigned char byte) {
    if (r->count == RB_CAP) {
        return false;
    }
    r->data[r->tail] = byte;
    r->tail = (r->tail + 1) % RB_CAP;
    r->count++;
    return true;
}

static bool rb_pop(Ring *r, unsigned char *out) {
    if (r->count == 0) {
        return false;
    }
    *out = r->data[r->head];
    r->head = (r->head + 1) % RB_CAP;
    r->count--;
    return true;
}

int main(void) {
    Ring r;
    rb_init(&r);
    unsigned char b = 0;

    if (rb_pop(&r, &b)) {
        return 1; /* pop on empty must fail */
    }
    for (int i = 0; i < RB_CAP; i++) {
        if (!rb_push(&r, (unsigned char)i)) {
            return 1;
        }
    }
    if (rb_push(&r, 99)) {
        return 1; /* push on full must fail */
    }
    for (int i = 0; i < RB_CAP; i++) {
        if (!rb_pop(&r, &b) || b != (unsigned char)i) {
            return 1;
        }
    }
    if (rb_pop(&r, &b)) {
        return 1;
    }
    puts("ring buffer ok");
    return 0;
}
```

Stores `head`, `tail` and `count`, so full and empty are unambiguous (a count of 0 vs capacity). All state is on the stack: no `malloc`, and the main guards check ordering and wraparound.

```cpp
#include <iostream>
#include <utility>

constexpr long long MOD = 1000000007LL;

// returns (F(n), F(n+1))
std::pair<long long, long long> fib(long long n) {
    if (n == 0) {
        return {0, 1};
    }
    auto [a, b] = fib(n >> 1);
    long long two_b = (2 * b) % MOD;
    long long c = (a * ((two_b - a + MOD) % MOD)) % MOD;
    long long d = ((a * a) % MOD + (b * b) % MOD) % MOD;
    if (n & 1) {
        return {d, (c + d) % MOD};
    }
    return {c, d};
}

int main() {
    std::cout << fib(10).first << "\n";            // 55
    std::cout << fib(90).first << "\n";            // 2880067194370816120 mod p
    std::cout << fib(1000000000000000000LL).first << "\n";
    return 0;
}
```

Fast doubling recurses on `n/2`, so depth is about 60 for n up to 10^18. Each step derives `F(2k)` and `F(2k+1)` from `F(k)` and `F(k+1)` mod p; the `+MOD` guards the subtraction from underflowing.

