def merge_intervals(intervals):
    if not intervals:
        return []
    ordered = sorted(intervals, key=lambda pair: pair[0])
    merged = [list(ordered[0])]
    for start, end in ordered[1:]:
        if start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return [tuple(pair) for pair in merged]


if __name__ == "__main__":
    assert merge_intervals([]) == []
    assert merge_intervals([(1, 3), (2, 6), (8, 10)]) == [(1, 6), (8, 10)]
    assert merge_intervals([(1, 4), (4, 5)]) == [(1, 5)]
    assert merge_intervals([(5, 6), (1, 2), (2, 3)]) == [(1, 3), (5, 6)]
    print(merge_intervals([(1, 2), (3, 4), (2, 3)]))
```

Sorting by start makes a single pass sufficient. `start <= merged[-1][1]` treats touching intervals as overlapping, so `(1,4)` and `(4,5)` collapse to `(1,5)`; an interior interval changes nothing because of the `end >` guard.

