std::pair<int, std::size_t> longest_run(const std::vector<int>& v) {
    if (v.empty()) return {0, 0};
    int best_val = v[0];
    std::size_t best_len = 1;
    int cur_val = v[0];
    std::size_t cur_len = 1;
    for (std::size_t i = 1; i < v.size(); ++i) {
        if (v[i] == cur_val) {
            ++cur_len;
        } else {
            cur_val = v[i];
            cur_len = 1;
        }
        if (cur_len > best_len) {
            best_len = cur_len;
            best_val = cur_val;
        }
    }
    return {best_val, best_len};
}

int main() {
    assert(longest_run({}) == std::make_pair(0, std::size_t{0}));
    assert(longest_run({5}) == std::make_pair(5, std::size_t{1}));
    assert(longest_run({1, 1, 2, 2, 2, 3}) == std::make_pair(2, std::size_t{3}));
    assert(longest_run({7, 7, 2, 9, 9}) == std::make_pair(7, std::size_t{2}));
    std::cout << "longest run ok\n";
    return 0;
}
