fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    None
}

fn main() {
    let data = [1, 3, 5, 7, 9, 11];
    assert_eq!(binary_search(&data, &5), Some(2));
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &11), Some(5));
    assert_eq!(binary_search(&data, &4), None);
    assert_eq!(binary_search::<i32>(&[], &0), None);
    assert_eq!(binary_search(&[42], &42), Some(0));
    println!("binary search ok");
}
```
`lo + (hi - lo) / 2` avoids overflow on huge slices. The `hi = mid` (not `mid - 1`) half-open convention is what makes the empty-slice and single-element cases work without special branches.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push_front(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (!n) {
        perror("malloc");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

static void print_list(const Node *head) {
    for (const Node *p = head; p; p = p->next)
        printf("%d%s", p->value, p->next ? " -> " : "\n");
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; ++i)
        head = push_front(head, i);
    print_list(head);            /* 5 -> 4 -> 3 -> 2 -> 1 */
    head = reverse(head);
    print_list(head);            /* 1 -> 2 -> 3 -> 4 -> 5 */
    free_list(head);

    Node *empty = reverse(NULL); /* must stay NULL */
    print_list(empty);
    return 0;
}
```
