#include <iostream>
#include <string>
#include <stack>
#include <optional>

std::optional<size_t> first_mismatch(const std::string& s) {
    std::stack<std::pair<char, size_t>> st;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push({c, i});
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return i;
            char open = st.top().first;
            bool ok = (open == '(' && c == ')') ||
                      (open == '[' && c == ']') ||
                      (open == '{' && c == '}');
            if (!ok) return i;
            st.pop();
        }
    }
    if (!st.empty()) return st.top().second;
    return std::nullopt;
}

int main() {
    for (const std::string s : {std::string("a(b[c]{d})e"),
                                std::string("([)]"),
                                std::string("abc(")}) {
        auto m = first_mismatch(s);
        if (m) std::cout << s << " -> mismatch at " << *m << "\n";
        else    std::cout << s << " -> balanced\n";
