from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.cap = capacity
        self.data = OrderedDict()

    def get(self, key):
        if key not in self.data:
            return None
        self.data.move_to_end(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.data.move_to_end(key)
        self.data[key] = value
        if len(self.data) > self.cap:
            self.data.popitem(last=False)

if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, "a"); c.put(2, "b")
    print(c.get(1))   # a
    c.put(3, "c")      # evicts 2
    print(c.get(2))   # None
    print(c.get(3))   # c
```
`OrderedDict.move_to_end` gives O(1) recency updates; `popitem(last=False)` evicts the least-recently used entry in O(1).

```c
#include <stdio.h>
#include <stdint.h>
#include <limits.h>

void to_binary(int32_t n, char *out, size_t out_size) {
    // Need 32 bits + NUL.
    if (out_size < 33) { out[0] = '\0'; return; }
    uint32_t u = (uint32_t)n;   // two's complement bit pattern
    for (int i = 31; i >= 0; --i) {
        out[31 - i] = ((u >> i) & 1u) ? '1' : '0';
    }
    out[32] = '\0';
}

int main(void) {
    char buf[33];
    int32_t vals[] = {0, 5, -1, INT32_MIN, INT32_MAX};
    for (size_t i = 0; i < sizeof vals / sizeof vals[0]; ++i) {
        to_binary(vals[i], buf, sizeof buf);
        printf("%11d -> %s\n", vals[i], buf);
    }
    return 0;
}
```
Casting to `uint32_t` avoids UB from right-shifting a negative signed value.

