import os
import sys
from collections import defaultdict
from pathlib import Path

def human(n: int) -> str:
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if n < 1024 or unit == "TB":
            return f"{n:.1f} {unit}"
        n /= 1024
    return str(n)

def sizes(root: str) -> dict:
    totals = defaultdict(int)
    counts = defaultdict(int)
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if not d.startswith(".")]
        for name in filenames:
            path = Path(dirpath) / name
            try:
                size = path.stat().st_size
            except OSError as exc:
                sys.stderr.write(f"skip {path}: {exc}\n")
                continue
            ext = path.suffix.lower() or "(none)"
            totals[ext] += size
            counts[ext] += 1
    return {ext: (totals[ext], counts[ext]) for ext in totals}

if __name__ == "__main__":
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    data = sizes(root)
    for ext, (total, count) in sorted(data.items(), key=lambda kv: -kv[1][0]):
        print(f"{ext:<8} {human(total):>10}  ({count} files)")
```
The walk prunes hidden directories, tolerates per-file `OSError`, and buckets files with no suffix under `(none)`. Output is sorted by total bytes descending with a human-readable size.

```cpp
#include <condition_variable>
#include <deque>
#include <mutex>
#include <optional>
#include <stdexcept>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity)
        : capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(T value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return q_.size() < capacity_ || closed_; });
        if (closed_) throw std::runtime_error("queue is closed");
        q_.push_back(std::move(value));
        not_empty_.notify_one();
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;  // closed and drained
        T value = std::move(q_.front());
        q_.pop_front();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t capacity_;
    std::deque<T> q_;
    bool closed_ = false;
    std::mutex mu_;
    std::condition_variable not_empty_, not_full_;
};
```
`push` blocks while the queue is full, `pop` blocks while it is empty, and both wake correctly on `close()`. After close, pending `pop` calls drain remaining items and then return `std::nullopt`; pending or subsequent `push` calls throw.

