#include <system_error>

struct ParseResult {
    bool ok = false;
    std::int64_t value = 0;
    bool overflow = false;
};

ParseResult parse_i64(std::string_view sv) {
    // trim surrounding ASCII whitespace
    std::size_t b = 0, e = sv.size();
    while (b < e && (sv[b] == ' ' || sv[b] == '\t' || sv[b] == '\n' || sv[b] == '\r')) ++b;
    while (e > b && (sv[e - 1] == ' ' || sv[e - 1] == '\t' || sv[e - 1] == '\n' || sv[e - 1] == '\r')) --e;
    if (b == e) return {};

    std::int64_t out = 0;
    auto res = std::from_chars(sv.data() + b, sv.data() + e, out, 10);
    if (res.ec == std::errc::result_out_of_range) return {false, 0, true};
    if (res.ec != std::errc{} || res.ptr != sv.data() + e) return {};
    return {true, out, false};
}

#include <cassert>
int main() {
    assert(parse_i64("  -42 ").value == -42);
    assert(!parse_i64("12x").ok);
    assert(parse_i64("").ok == false);
    assert(parse_i64("99999999999999999999").overflow);
    assert(parse_i64("9223372036854775807").value == 9223372036854775807LL);
    return 0;
}
```
`std::from_chars` is locale-independent and reports overflow via `result_out_of_range` instead of throwing. Requiring `res.ptr` to land on the end rejects trailing junk like `"12x"`.

```cpp
#include <algorithm>
#include <cstdint>
#include <vector>

std::int64_t largest_rectangle(const std::vector<std::int64_t>& heights) {
    // Sentinel 0 on the right flushes the stack; indices are 0-based heights.
    std::vector<std::int64_t> h = heights;
    h.push_back(0);
    std::vector<std::size_t> stack;  // indices with strictly increasing heights
    std::int64_t best = 0;

    for (std::size_t i = 0; i < h.size(); ++i) {
        while (!stack.empty() && h[stack.back()] >= h[i]) {
            std::int64_t height = h[stack.back()];
            stack.pop_back();
            std::size_t left = stack.empty() ? 0 : stack.back() + 1;
            best = std::max(best, height * static_cast<std::int64_t>(i - left));
        }
        stack.push_back(i);
    }
    return best;
}

#include <cassert>
int main() {
    assert(largest_rectangle({}) == 0);
    assert(largest_rectangle({2, 1, 5, 6, 2, 3}) == 10);
    assert(largest_rectangle({2, 4}) == 4);
    assert(largest_rectangle({5, 5, 5}) == 15);
    return 0;
}
```
Each bar is pushed and popped once, so the loop is amortised O(n). The popped bar is the shortest in `[left, i)`, giving width `i - left`; the sentinel zero forces a final flush. `int64_t` avoids overflow for wide histograms.

```rust
use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
pub enum ConfigError {
    MissingEquals(usize),
    EmptyKey(usize),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::MissingEquals(l) => write!(f, "line {l}: expected key=value"),
            ConfigError::EmptyKey(l) => write!(f, "line {l}: empty key"),
        }
    }
}

pub fn parse(input: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut out = HashMap::new();
    for (idx, raw) in input.lines().enumerate() {
        let line = raw.split('#').next().unwrap_or("").trim();
        if line.is_empty() {
            continue;
        }
        let (key, value) = match line.split_once('=') {
            Some(pair) => pair,
            None => return Err(ConfigError::MissingEquals(idx + 1)),
        };
        let key = key.trim();
        if key.is_empty() {
            return Err(ConfigError::EmptyKey(idx + 1));
        }
        out.insert(key.to_string(), value.trim().to_string());
    }
    Ok(out)
}

pub fn get_or<'a>(
    map: &'a HashMap<String, String>,
    key: &str,
    default: &'a str,
) -> &'a str {
    map.get(key).map(String::as_str).unwrap_or(default)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_and_defaults() {
        let cfg = parse("\n# comment\nname = XT \nport=8080\n").unwrap();
        assert_eq!(cfg["name"], "XT");
        assert_eq!(get_or(&cfg, "host", "localhost"), "localhost");
    }

    #[test]
    fn rejects_bad_lines() {
        assert!(matches!(parse("oops"), Err(ConfigError::MissingEquals(1))));
        assert!(matches!(parse("=x"), Err(ConfigError::EmptyKey(1))));
    }
}
```
Lines are split on the first `#` for comments, blank lines are ignored, and keys/values are trimmed. A missing `=` or empty key yields a line-numbered error; `get_or` supplies defaults without cloning.

```rust
use std::cmp::Ordering;

/// Returns Ok(index) if found, Err(insertion_index) otherwise.
/// `cmp` must be consistent with the slice's ordering (non-decreasing).
pub fn binary_search_by<'a, T, F>(haystack: &'a [T], mut cmp: F) -> Result<usize, usize>
where
    F: FnMut(&'a T) -> Ordering,
{
    let mut lo = 0usize;
    let mut hi = haystack.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match cmp(&haystack[mid]) {
            Ordering::Less => lo = mid + 1,
            Ordering::Greater => hi = mid,
            Ordering::Equal => return Ok(mid),
        }
    }
    Err(lo)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cmp::Ordering;

    #[test]
    fn finds_and_reports_insertion() {
        let data = [1, 3, 3, 5, 7];
        assert_eq!(binary_search_by(&data, |&x| x.cmp(&3)), Ok(1));
        assert_eq!(binary_search_by(&data, |&x| x.cmp(&0)), Err(0));
        assert_eq!(binary_search_by(&data, |&x| x.cmp(&4)), Err(3));
        assert_eq!(binary_search_by(&data, |&x| x.cmp(&9)), Err(5));
        assert_eq!(binary_search_by::<i32, _>(&[], |&x| x.cmp(&1)), Err(0));
    }

    #[test]
    fn custom_ordering() {
        let words = ["apple", "Fig", "pear"];
        let pos = binary_search_by(&words, |w| w.to_lowercase().cmp("fig"));
        assert_eq!(pos, Ok(1));
    }
}
```
Uses the half-open `lo..hi` invariant so `mid = lo + (hi - lo) / 2` cannot overflow and empty slices return `Err(0)`. For duplicates it returns whichever equal element it lands on, matching `slice::binary_search_by` semantics.

