fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 3, 6];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 3, 5, 6, 7]);
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[4], &[]), vec![4]);
    println!("{:?}", merge_sorted(&a, &b));
}
```

Equality uses `<=` so equal elements from the left slice come first, keeping the merge stable. The tail slices are copied with `extend_from_slice` once one side is exhausted.

