#include <iostream>
#include <string>
#include <unordered_map>
#include <stack>

bool balanced(const std::string& s) {
    std::unordered_map<char, char> closing{{')', '('}, {']', '['}, {'}', '{'}};
    std::stack<char> open;

    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            open.push(c);
        } else if (closing.count(c)) {
            if (open.empty() || open.top() != closing[c]) {
                return false;
            }
            open.pop();
        }
    }
    return open.empty();
}

int main() {
    const std::string cases[] = {"", "()", "([{}])", "(]", "((", ")", "{[()]}x"};
    const bool expected[] = {true, true, true, false, false, false, true};
    for (std::size_t i = 0; i < 7; ++i) {
        bool got = balanced(cases[i]);
        std::cout << cases[i] << " -> " << got << '\n';
        if (got != expected[i]) return 1;
    }
    return 0;
}
```

Unmatched closing brackets fail immediately; unmatched openings are caught by the final `open.empty()`. Non-bracket characters are ignored.

