#include <iostream>
#include <string>
#include <limits>

std::string to_binary(long long n) {
    if (n == 0) return "0";
    bool negative = n < 0;
    unsigned long long mag =
        negative ? static_cast<unsigned long long>(-(n + 1)) + 1ULL
                 : static_cast<unsigned long long>(n);
    std::string out;
    while (mag > 0) {
        out.push_back('0' + static_cast<char>(mag & 1ULL));
        mag >>= 1;
    }
    if (negative) out.push_back('-');
    std::string reversed(out.rbegin(), out.rend());
    return reversed;
}

int main() {
    std::cout << to_binary(0) << '\n';
    std::cout << to_binary(10) << '\n';
    std::cout << to_binary(-10) << '\n';
    std::cout << to_binary(std::numeric_limits<long long>::min()) << '\n';
    return 0;
}
```

Magnitude is taken via `-(n + 1) + 1` to avoid signed overflow at `LLONG_MIN`. Bits are emitted least-significant first and reversed at the end, with `-` prefixed for negatives.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)       # odd length
        l2, r2 = expand(i, i + 1)   # even length
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    assert longest_palindrome("") == ""
    assert longest_palindrome("a") == "a"
    assert longest_palindrome("babad") in ("bab", "aba")
    assert longest_palindrome("cbbd") == "bb"
    print("all tests passed")
```

Runs in O(n²) time, O(1) extra space. The `expand` helper walks outward from each center and returns the bounds of the palindrome it found.

