```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.store: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self.store:
            return -1
        self.store.move_to_end(key)   # mark as most-recently used
        return self.store[key]

    def put(self, key, value) -> None:
        if key in self.store:
            self.store.move_to_end(key)
        self.store[key] = value
        if len(self.store) > self.capacity:
            self.store.popitem(last=False)   # evict least-recently used


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put(1, 1)
    cache.put(2, 2)
    assert cache.get(1) == 1      # 2 becomes LRU
    cache.put(3, 3)               # evicts key 2
    assert cache.get(2) == -1
    assert cache.get(3) == 3
    print("ok")
```

`OrderedDict.move_to_end` keeps the recency order; `popitem(last=False)` removes the oldest entry once capacity is exceeded. All operations run in O(1) amortised.

