                if (i + 1 < line.size() && line[i + 1] == '"') {
                    cur += '"';   // escaped quote
                    ++i;
                } else {
                    in_quotes = false;
                }
            } else {
                cur += c;
            }
        } else if (c == '"') {
            in_quotes = true;
        } else if (c == ',') {
            fields.push_back(cur);
            cur.clear();
        } else {
            cur += c;
        }
    }
    fields.push_back(cur);
    return fields;
}

int main() {
    auto a = parse_csv_line("a,b,c");
    assert(a == std::vector<std::string>({"a", "b", "c"}));

    auto b = parse_csv_line("\"hello, world\",2");
    assert(b == std::vector<std::string>({"hello, world", "2"}));

    auto c = parse_csv_line("\"say \"\"hi\"\"\",end");
    assert(c == std::vector<std::string>({"say \"hi\"", "end"}));

    auto d = parse_csv_line("");
    assert(d == std::vector<std::string>({""}));
    std::cout << "ok\n";
}
```

A single stateful pass: `in_quotes` toggles on unescaped quotes, a doubled quote inside quotes emits one `"`, and commas only split when outside quotes. Empty input yields one empty field, matching common CSV behaviour.

