#include <stdio.h>
#include <string.h>
#include <ctype.h>

static void reverse(char *a, char *b) {
    while (a < b) {
        char t = *a; *a++ = *b; *b-- = t;
    }
}

void reverse_words(char *s) {
    size_t n = strlen(s);
    reverse(s, s + n - 1);
    char *word = s;
    for (char *p = s; ; p++) {
        if (*p == '\0' || isspace((unsigned char)*p)) {
            reverse(word, p - 1);
            word = p + 1;
            if (*p == '\0') break;
        }
    }
}

