#include <optional>
#include <string>
#include <cctype>

std::optional<long long> try_parse_int(const std::string& s) {
    size_t i = 0, n = s.size();
    while (i < n && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
    if (i == n) return std::nullopt;

    bool neg = false;
    if (s[i] == '+' || s[i] == '-') {
        neg = (s[i] == '-');
        ++i;
    }
    if (i == n || !std::isdigit(static_cast<unsigned char>(s[i]))) return std::nullopt;

    long long value = 0;
    for (; i < n; ++i) {
        if (!std::isdigit(static_cast<unsigned char>(s[i]))) return std::nullopt;
        int d = s[i] - '0';
        if (value > (9223372036854775807LL - d) / 10) return std::nullopt;
        value = value * 10 + d;
    }
    return neg ? -value : value;
}
