```rust
use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count desc, then word asc for a deterministic tie-break.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The cat, the dog! The CAT sat.";
    for (w, c) in top_words(text, 3) {
        println!("{w}: {c}");
    }
    println!("{:?}", top_words("   ", 5));
}
```

`to_lowercase` is applied per-character inside the filter chain, so non-ASCII words still work. The tie-break on the word itself keeps output stable across runs. Empty or punctuation-only input yields an empty vector.

```rust
pub fn search(haystack: &[i64], needle: i64) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = haystack.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match haystack[mid] {
            v if v == needle => return Some(mid),
            v if v < needle => lo = mid + 1,
            _ => hi = mid,
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::search;

    #[test]
    fn finds_and_misses() {
        let data = [-4, -1, 0, 3, 3, 9, 42];
        assert_eq!(search(&data, 3), Some(3));
        assert_eq!(search(&data, 42), Some(6));
        assert_eq!(search(&data, -4), Some(0));
        assert_eq!(search(&data, 5), None);
        assert_eq!(search(&[], 1), None);
    }
}

fn main() {
    println!("{:?}", search(&[1, 2, 3], 2));
}
```

`mid = lo + (hi - lo) / 2` avoids overflow that `(lo + hi) / 2` could cause. With duplicates it returns whichever matching index the midpoint lands on, which is fine for existence checks.

