#include <array>
#include <cstddef>
#include <iostream>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buffer_{}, capacity_(capacity == 0 ? 1 : capacity), head_(0), size_(0) {}

    void push(int value) {
        buffer_[(head_ + size_) % capacity_] = value;
        if (size_ < capacity_) {
            ++size_;
        } else {
            head_ = (head_ + 1) % capacity_;
        }
    }

    long long sum() const {
        long long total = 0;
        for (std::size_t i = 0; i < size_; ++i) {
            total += buffer_[(head_ + i) % capacity_];
        }
        return total;
    }

    std::size_t size() const { return size_; }

private:
    std::array<int, 64> buffer_;
    std::size_t capacity_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer ring(3);
    if (ring.sum() != 0 || ring.size() != 0) return 1;

    for (int v : {1, 2, 3}) ring.push(v);
    if (ring.sum() != 6) return 1;

    ring.push(4);            // evicts 1
    if (ring.sum() != 9) return 1;

    RingBuffer tiny(0);      // clamps capacity to 1
    tiny.push(-5);
    tiny.push(7);
    if (tiny.sum() != 7) return 1;

    std::cout << "ok\n";
    return 0;
}
