static std::string trim(const std::string& s) {
    const std::string ws = " \t\r\n";
    const auto begin = s.find_first_not_of(ws);
    if (begin == std::string::npos) return "";
    const auto end = s.find_last_not_of(ws);
    return s.substr(begin, end - begin + 1);
}

std::vector<std::string> split_and_trim(const std::string& text, char delim) {
    std::vector<std::string> parts;
    std::size_t start = 0;
    while (true) {
        const std::size_t pos = text.find(delim, start);
        const std::string raw = pos == std::string::npos
            ? text.substr(start)
            : text.substr(start, pos - start);
        parts.push_back(trim(raw));
        if (pos == std::string::npos) break;
        start = pos + 1;
    }
    return parts;
}

int main() {
    const auto a = split_and_trim("  a , b ,c,", ',');
    if (a != std::vector<std::string>{"a", "b", "c", ""}) return 1;

    const auto b = split_and_trim("", ',');
    if (b != std::vector<std::string>{""}) return 1;

    const auto c = split_and_trim("\t1\n", ',');
    if (c != std::vector<std::string>{"1"}) return 1;

    std::cout << "ok\n";
    return 0;
}
