```rust
fn eval_rpn(expression: &str) -> Result<f64, String> {
    let mut stack: Vec<f64> = Vec::new();

    for token in expression.split_whitespace() {
        match token {
            "+" | "-" | "*" | "/" => {
                let rhs = stack.pop().ok_or_else(|| format!("missing operand for {token}"))?;
                let lhs = stack.pop().ok_or_else(|| format!("missing operand for {token}"))?;
                let value = match token {
                    "+" => lhs + rhs,
                    "-" => lhs - rhs,
                    "*" => lhs * rhs,
                    _ => {
                        if rhs == 0.0 {
                            return Err("division by zero".to_string());
                        }
                        lhs / rhs
                    }
                };
                stack.push(value);
            }
            _ => {
                let value: f64 = token
                    .parse()
                    .map_err(|_| format!("invalid token: {token}"))?;
                stack.push(value);
            }
        }
    }

    if stack.len() != 1 {
        return Err(format!("expected 1 value, got {}", stack.len()));
    }
    Ok(stack[0])
}

fn main() {
    assert_eq!(eval_rpn("3 4 + 2 *").unwrap(), 14.0);
    assert_eq!(eval_rpn("5 1 2 + 4 * + 3 -").unwrap(), 14.0);
    assert_eq!(eval_rpn("-7").unwrap(), -7.0);
    assert!(eval_rpn("1 0 /").is_err());
    assert!(eval_rpn("1 +").is_err());
    assert!(eval_rpn("").is_err());
    assert!(eval_rpn("1 2").is_err());
    println!("ok");
}
