#include <stdint.h>
#include <stdio.h>
#include <string.h>

static uint32_t crc32(const unsigned char *data, size_t len, uint32_t crc) {
    crc = ~crc;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; ++bit) {
            const uint32_t mask = (uint32_t)-(int32_t)(crc & 1u);
            crc = (crc >> 1) ^ (0xEDB88320u & mask);
        }
    }
    return ~crc;
}

int main(void) {
    const char *text = "The quick brown fox jumps over the lazy dog";
    const uint32_t got = crc32((const unsigned char *)text, strlen(text), 0u);
    const uint32_t expected = 0x414FA339u;

    if (got != expected) {
        fprintf(stderr, "mismatch: got %08X expected %08X\n", got, expected);
        return 1;
    }

    if (crc32((const unsigned char *)"", 0, 0u) != 0u) {
        fprintf(stderr, "empty input should hash to 0\n");
        return 1;
    }

    printf("CRC32 = %08X\n", got);
    return 0;
}
