#include <cassert>
#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse_iter(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

Node* reverse_rec(Node* head) {
    if (!head || !head->next) return head;
    Node* new_head = reverse_rec(head->next);
    head->next->next = head;
    head->next = nullptr;
    return new_head;
}

void free_list(Node* head) {
    while (head) {
        Node* nxt = head->next;
        delete head;
        head = nxt;
    }
}

int main() {
    for (auto rev : {reverse_iter, reverse_rec}) {
        Node* head = new Node(1);
        head->next = new Node(2);
        head->next->next = new Node(3);
        head = rev(head);
        assert(head->value == 3 && head->next->value == 2 && head->next->next->value == 1);
        assert(head->next->next->next == nullptr);
        free_list(head);
        assert(rev(nullptr) == nullptr);
    }
    std::cout << "ok\n";
    return 0;
}
