import heapq


def dijkstra(graph, source):
    """graph: {node: {neighbor: weight}}. Returns (dist, parent) dicts."""
    dist = {source: 0}
    parent = {source: None}
    heap = [(0, source)]
    while heap:
        d, node = heapq.heappop(heap)
        if d > dist.get(node, float("inf")):
            continue
        for neighbor, weight in graph.get(node, {}).items():
            if weight < 0:
                raise ValueError("Dijkstra requires non-negative weights")
            nd = d + weight
            if nd < dist.get(neighbor, float("inf")):
                dist[neighbor] = nd
                parent[neighbor] = node
                heapq.heappush(heap, (nd, neighbor))
    return dist, parent


def path(parent, target):
    route = []
    while target is not None:
        route.append(target)
        target = parent.get(target)
    return route[::-1]


if __name__ == "__main__":
    g = {"A": {"B": 1, "C": 4}, "B": {"C": 2, "D": 5}, "C": {"D": 1}, "D": {}}
    dist, parent = dijkstra(g, "A")
    assert dist == {"A": 0, "B": 1, "C": 3, "D": 4}, dist
    assert path(parent, "D") == ["A", "B", "C", "D"]
    isolated = {"X": {}}
    d2, _ = dijkstra(isolated, "X")
    assert d2 == {"X": 0}
    print("ok")
