int longest_increasing_run(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int best = 1, cur = 1;
    for (std::size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] > nums[i - 1]) ++cur;
        else cur = 1;
