std::vector<std::string> split_words(const std::string& s) {
    std::vector<std::string> out;
    std::size_t i = 0;
    while (i < s.size()) {
        while (i < s.size() && s[i] == ' ') ++i;
        std::size_t start = i;
        while (i < s.size() && s[i] != ' ') ++i;
        if (start < i) out.push_back(s.substr(start, i - start));
    }
    return out;
}

std::string reverse_words(const std::string& s) {
    auto words = split_words(s);
    std::string out;
    for (std::size_t i = words.size(); i-- > 0;) {
        out += words[i];
        if (i != 0) out += ' ';
    }
    return out;
}

int main() {
