template <typename T, std::size_t N>
class Ring {
public:
    bool push(const T& v) {
        if (size_ == N) return false;
        buf_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }
    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T v = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> buf_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    Ring<int, 3> r;
    for (int i = 1; i <= 4; ++i) std::cout << "push " << i << " -> " << r.push(i) << '\n';
    while (!r.empty()) std::cout << "pop " << *r.pop() << '\n';
    std::cout << "empty: " << r.empty() << '\n';
    return 0;
}
