from typing import List, Optional


def binary_search(nums: List[int], target: int) -> int:
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def first_occurrence(nums: Optional[List[int]], target: int) -> int:
    if not nums:
        return -1
    lo, hi, found = 0, len(nums) - 1, -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            found = mid
            hi = mid - 1
        elif nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return found


if __name__ == "__main__":
    assert binary_search([], 3) == -1
    assert binary_search([2, 2, 2, 5], 2) in (0, 1, 2)
    assert first_occurrence([2, 2, 2, 5], 2) == 0
    assert first_occurrence([1, 3, 5, 7], 30) == -1
    print(binary_search([1, 3, 5, 7], 5))
