#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *join(const char *const *parts, size_t n, const char *sep) {
    size_t seplen = strlen(sep);
    size_t total = 0;
    for (size_t i = 0; i < n; ++i) {
        total += strlen(parts[i]);
        if (i + 1 < n) total += seplen;
    }
    if (n == 0) {
        char *empty = malloc(1);
        if (empty) empty[0] = '\0';
        return empty;
    }
    char *out = malloc(total + 1);
    if (!out) return NULL;
    char *p = out;
    for (size_t i = 0; i < n; ++i) {
        size_t len = strlen(parts[i]);
        memcpy(p, parts[i], len);
        p += len;
        if (i + 1 < n) {
            memcpy(p, sep, seplen);
            p += seplen;
        }
    }
    *p = '\0';
    return out;
}

int main(void) {
    const char *words[] = {"alpha", "beta", "gamma"};
    char *s = join(words, 3, ", ");
    if (!s) return 1;
    puts(s);
    free(s);

    char *empty = join(words, 0, ", ");
    puts(empty);
    free(empty);
    return 0;
}
