from typing import List, Optional, Tuple


def two_sum(nums: List[int], target: int) -> Tuple[int, int]:
    """Return indices (i, j) with nums[i] + nums[j] == target.

    Uses a single pass with a hash map for O(n) time. Raises ValueError
    when no valid pair exists, including the empty/singleton case.
    """
    seen: dict[int, int] = {}
    for i, value in enumerate(nums):
        complement = target - value
        if complement in seen:
            return seen[complement], i
        seen[value] = i
    raise ValueError(f"no two numbers in {nums!r} sum to {target}")


if __name__ == "__main__":
