    assert two_sum([3, 3], 6) == (0, 1)
    assert two_sum([-1, -2, -3, -4], -7) == (2, 3)
    for bad, tgt in ([[], 5], [[1], 1], [[1, 2, 3], 100]):
        try:
            two_sum(bad, tgt)
        except ValueError:
            pass
        else:
            raise AssertionError(f"expected ValueError for {bad} -> {tgt}")
    print("ok")
