fn fib_pair(n: u64) -> (u128, u128) {
    // returns (F(n), F(n+1))
    if n == 0 {
        return (0, 1);
    }
    let (a, b) = fib_pair(n / 2);
    let c = a * (2 * b - a);
    let d = a * a + b * b;
    if n % 2 == 0 {
        (c, d)
    } else {
        (d, c + d)
    }
}

fn fib(n: u64) -> u128 {
    fib_pair(n).0
}

fn fib_loop(n: u64) -> u128 {
    let (mut a, mut b) = (0u128, 1u128);
    for _ in 0..n {
        let next = a + b;
        a = b;
        b = next;
    }
    a
}

fn main() {
    for n in 0..=40 {
        assert_eq!(fib(n), fib_loop(n), "mismatch at n={n}");
    }
    assert_eq!(fib(0), 0);
    assert_eq!(fib(1), 1);
    assert_eq!(fib(10), 55);
    println!("fib(90) = {}", fib(90));
}
