#include <stddef.h>
#include <stdio.h>

void reverse(int *arr, size_t len) {
    if (arr == NULL || len < 2) return;
    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

int main(void) {
    int empty[] = {0};
    reverse(empty, 0);

    int one[] = {42};
    reverse(one, 1);
    printf("%d\n", one[0]);

    int data[] = {1, 2, 3, 4, 5};
    size_t n = sizeof data / sizeof data[0];
    reverse(data, n);
    for (size_t i = 0; i < n; ++i) printf("%d%c", data[i], i + 1 == n ? '\n' : ' ');
    return 0;
}
```
The `len < 2` guard makes empty and single-element arrays no-ops, and the two-index loop swaps toward the middle without an off-by-one.

