The stack records every opener in order; a closer must match the most recent opener, and the final empty check catches leftover openers. Runs in O(n) time.

```cpp
#include <cmath>
#include <cstdio>
#include <vector>

struct Stats { double mean; double stddev; };

Stats welford(const std::vector<double>& xs) {
    double mean = 0.0, m2 = 0.0;
    std::size_t n = 0;
    for (double x : xs) {
        ++n;
        double delta = x - mean;
        mean += delta / static_cast<double>(n);
        m2 += delta * (x - mean);
    }
    double sd = n > 1 ? std::sqrt(m2 / static_cast<double>(n - 1)) : 0.0;
    return {mean, sd};
}

int main() {
    std::vector<double> data = {2.0, 4.0, 4.0, 4.0, 5.0, 5.0, 7.0, 9.0};
    Stats s = welford(data);
    std::printf("mean=%.4f sd=%.4f\n", s.mean, s.stddev);
    // mean=5.0000 sd=2.1381
}
```
Welford's method updates the mean and sum of squared deviations in one pass, avoiding the catastrophic cancellation that the naive `sum(x^2) - n*mean^2` formula suffers on large or nearly-constant inputs. Sample standard deviation divides by `n - 1`.

