```python
def fib_matrix(n):
    if n < 0:
        raise ValueError("n must be non-negative")

    def mat_mul(a, b):
        return (
            (a[0][0] * b[0][0] + a[0][1] * b[1][0],
             a[0][0] * b[0][1] + a[0][1] * b[1][1]),
            (a[1][0] * b[0][0] + a[1][1] * b[1][0],
             a[1][0] * b[0][1] + a[1][1] * b[1][1]),
        )

    def mat_pow(m, p):
        result = ((1, 0), (0, 1))
        base = m
        while p > 0:
            if p & 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            p >>= 1
        return result

    return mat_pow(((1, 1), (1, 0)), n)[0][1]


if __name__ == "__main__":
    naive = [0, 1]
    for _ in range(2, 20):
        naive.append(naive[-1] + naive[-2])
    for i in range(20):
        assert fib_matrix(i) == naive[i], (i, fib_matrix(i), naive[i])
    print(fib_matrix(10))   # 55
    print(fib_matrix(0))    # 0
    print(fib_matrix(50))   # 12586269025
```

Matrix exponentiation gives O(log n) arithmetic operations instead of O(n), which matters once n passes a few hundred. The 20-term cross-check against the iterative list proves the fast path matches the simple definition before trusting it on large n.

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

struct Node *push(struct Node *head, int value) {
    struct Node *n = malloc(sizeof(struct Node));
    if (!n) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

struct Node *reverse(struct Node *head) {
    struct Node *prev = NULL;
    struct Node *cur = head;
    while (cur) {
        struct Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

void print_list(const struct Node *head) {
    for (; head; head = head->next) {
        printf("%d", head->value);
        if (head->next) printf(" -> ");
    }
    printf("\n");
}

void free_list(struct Node *head) {
    while (head) {
        struct Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    struct Node *head = NULL;
    for (int i = 1; i <= 5; i++) {
        head = push(head, i);
    }
    printf("before: ");
    print_list(head);   /* 5 -> 4 -> 3 -> 2 -> 1 */
    head = reverse(head);
    printf("after:  ");
    print_list(head);   /* 1 -> 2 -> 3 -> 4 -> 5 */
    free_list(head);
    return 0;
}
```

The loop saves `next` before rewiring `cur->next`, so nothing is lost as the pointers flip. An empty list returns NULL immediately and prints an empty line; `free_list` releases every node so there is no leak.

