```cpp
#include <iostream>
#include <stack>
#include <string>

bool is_balanced(const std::string &s) {
    std::stack<char> open;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            open.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (open.empty()) return false;
            char top = open.top();
            open.pop();
            bool matches = (c == ')' && top == '(') ||
                           (c == ']' && top == '[') ||
                           (c == '}' && top == '{');
            if (!matches) return false;
        }
    }
    return open.empty();
}

int main() {
    std::string tests[] = {"()[] {}", "([)]", "(((", ")]", ""};
    for (const auto &t : tests) {
        std::cout << '"' << t << "\" -> " << (is_balanced(t) ? "balanced" : "unbalanced") << '\n';
    }
    return 0;
}
```

Non-bracket characters are ignored. A closer with an empty stack or a mismatched top fails immediately, and the final `open.empty()` catches unclosed openers like `(((`. An empty string is balanced, which the loop handles without a special case.

