```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        let mut data = Vec::with_capacity(capacity);
        data.resize_with(capacity, || None);
        RingBuffer { data, head: 0, len: 0 }
    }

    pub fn capacity(&self) -> usize { self.data.len() }
    pub fn len(&self) -> usize { self.len }
    pub fn is_empty(&self) -> bool { self.len == 0 }

    pub fn push(&mut self, value: T) -> Result<(), T> {
        if self.len == self.data.len() {
            return Err(value);
        }
        let idx = (self.head + self.len) % self.data.len();
        self.data[idx] = Some(value);
        self.len += 1;
        Ok(())
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        let value = self.data[self.head].take();
        self.head = (self.head + 1) % self.data.len();
        self.len -= 1;
        value
    }
}

impl<T> Iterator for RingBuffer<T> {
    type Item = T;
    fn next(&mut self) -> Option<T> { self.pop() }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn wraps_and_yields_fifo() {
        let mut rb = RingBuffer::new(3);
        assert!(rb.push(1).is_ok());
        assert!(rb.push(2).is_ok());
        assert!(rb.push(3).is_ok());
        assert_eq!(rb.push(4), Err(4));
        assert_eq!(rb.pop(), Some(1));
        assert!(rb.push(4).is_ok());
        assert_eq!(rb.collect::<Vec<_>>(), vec![2, 3, 4]);
        assert!(rb.is_empty());
    }
}
