```rust
pub fn quicksort<T: Ord>(slice: &mut [T]) {
    if slice.len() <= 1 {
        return;
    }
    let pivot = partition(slice);
    let (left, right) = slice.split_at_mut(pivot);
    quicksort(left);
    quicksort(&mut right[1..]);
}

fn partition<T: Ord>(slice: &mut [T]) -> usize {
    let last = slice.len() - 1;
    let mut i = 0;
    for j in 0..last {
        if slice[j] <= slice[last] {
            slice.swap(i, j);
            i += 1;
        }
    }
    slice.swap(i, last);
    i
}

#[cfg(test)]
mod tests {
