class MedianTracker {
    std::priority_queue<int> low;                              // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high;  // min-heap
public:
    void add(int value) {
        if (low.empty() || value <= low.top()) {
            low.push(value);
        } else {
            high.push(value);
        }
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }
    }

    double median() const {
        if (low.empty()) return 0.0;
        if (low.size() == high.size()) {
            return (static_cast<double>(low.top()) + high.top()) / 2.0;
        }
        return static_cast<double>(low.top());
    }
};

int main() {
    MedianTracker tracker;
    int value;
    bool any = false;
    while (std::cin >> value) {
        tracker.add(value);
        any = true;
        std::cout << "median: " << tracker.median() << '\n';
    }
    if (!any) {
        std::cerr << "no integers provided\n";
        return 1;
    }
    return 0;
