#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const char B64[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/* Caller owns the returned buffer; length is written to *out_len. */
char *base64_encode(const unsigned char *data, size_t len, size_t *out_len) {
    size_t out_size = 4 * ((len + 2) / 3);
    char *out = malloc(out_size + 1);
    if (!out) return NULL;

    size_t i = 0, o = 0;
    while (i + 2 < len) {
        unsigned int n = (data[i] << 16) | (data[i + 1] << 8) | data[i + 2];
        out[o++] = B64[(n >> 18) & 63];
        out[o++] = B64[(n >> 12) & 63];
        out[o++] = B64[(n >> 6) & 63];
        out[o++] = B64[n & 63];
        i += 3;
    }
    if (i < len) {
        unsigned int n = data[i] << 16;
        int remaining = (int)(len - i);
        if (remaining == 2) n |= data[i + 1] << 8;
        out[o++] = B64[(n >> 18) & 63];
        out[o++] = B64[(n >> 12) & 63];
        out[o++] = remaining == 2 ? B64[(n >> 6) & 63] : '=';
        out[o++] = '=';
    }
    out[o] = '\0';
    *out_len = o;
    return out;
}

int main(void) {
    const char *samples[] = {"", "f", "fo", "foo", "hello world"};
    for (size_t i = 0; i < sizeof(samples) / sizeof(samples[0]); i++) {
        size_t n = 0;
        char *enc = base64_encode((const unsigned char *)samples[i], strlen(samples[i]), &n);
        if (!enc) { fprintf(stderr, "oom\n"); return 1; }
        printf("%-12s -> %s\n", samples[i], enc);
        free(enc);
    }
    return 0;
}
```

