#include <stdio.h>
#include <string.h>

static int is_open(char c) { return c == '(' || c == '[' || c == '{'; }

static char closer_for(char c) {
    if (c == '(') return ')';
    if (c == '[') return ']';
    return '}';
}

static int balanced(const char *s) {
    char stack[256];
    int top = 0;
    for (size_t i = 0; s[i]; i++) {
        char c = s[i];
        if (is_open(c)) {
            if (top == sizeof(stack)) {
                fprintf(stderr, "stack overflow at index %zu\n", i);
                return -1;
            }
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) {
                fprintf(stderr, "unmatched '%c' at index %zu\n", c, i);
                return 0;
            }
            char open = stack[--top];
            if (closer_for(open) != c) {
                fprintf(stderr, "mismatch: '%c' closed by '%c' at index %zu\n", open, c, i);
                return 0;
            }
        }
    }
    if (top != 0) {
        fprintf(stderr, "unclosed '%c', %d still open\n", stack[top - 1], top);
        return 0;
    }
    return 1;
}

int main(void) {
    const char *cases[] = {"()", "([{}])", "([)]", "((", ")]", ""};
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
        int r = balanced(cases[i]);
        printf("%-10s -> %s\n", cases[i], r == 1 ? "balanced" : r == 0 ? "unbalanced" : "error");
    }
    return 0;
}
```

The stack tracks the opening type, so `([)]` reports why it fails rather than just returning false. A fixed 256-slot stack bounds memory and reports overflow explicitly.

