template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    const T& at(std::size_t i) const {
        if (i >= size_) throw std::out_of_range("ring buffer index");
        std::size_t start = (head_ + N - size_) % N;
        return data_[(start + i) % N];
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int v = 1; v <= 5; ++v) rb.push(v);
    // Oldest kept values are 3, 4, 5.
