#include <iostream>
#include <string>
#include <vector>

std::string reverse_utf8(const std::string& s) {
    std::vector<std::string> chars;
    for (std::size_t i = 0; i < s.size();) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        std::size_t len = 1;
        if ((c & 0x80) == 0) len = 1;
        else if ((c & 0xE0) == 0xC0) len = 2;
        else if ((c & 0xF0) == 0xE0) len = 3;
        else if ((c & 0xF8) == 0xF0) len = 4;
        if (i + len > s.size()) len = 1;
        chars.push_back(s.substr(i, len));
        i += len;
    }
    std::string out;
    for (auto it = chars.rbegin(); it != chars.rend(); ++it) out += *it;
    return out;
}

int main() {
    std::string s = "a\xC3\xA9\xE2\x82\xACb"; // a, e-acute, euro, b
    std::string r = reverse_utf8(s);
    std::cout << r << "\n";
    std::cout << (reverse_utf8(r) == s ? "roundtrip ok" : "roundtrip broken") << "\n";
}
