```rust
fn eval_rpn(tokens: &[&str]) -> Result<f64, String> {
    let mut stack: Vec<f64> = Vec::new();
    for tok in tokens {
        match *tok {
            "+" | "-" | "*" | "/" => {
                let b = stack.pop().ok_or_else(|| format!("missing operand for {tok}"))?;
                let a = stack.pop().ok_or_else(|| format!("missing operand for {tok}"))?;
                let v = match *tok {
                    "+" => a + b,
                    "-" => a - b,
                    "*" => a * b,
                    _ => {
                        if b == 0.0 {
                            return Err("division by zero".to_string());
                        }
                        a / b
                    }
                };
                stack.push(v);
            }
            other => {
                let n: f64 = other.parse().map_err(|_| format!("bad token: {other}"))?;
                stack.push(n);
            }
        }
    }
    if stack.len() != 1 {
        return Err(format!("leftover operands: {}", stack.len()));
    }
    Ok(stack[0])
}

fn main() {
    assert_eq!(eval_rpn(&["2", "3", "+", "4", "*"]).unwrap(), 20.0);
    assert!(eval_rpn(&["1", "0", "/"]).is_err());
    assert!(eval_rpn(&["+"]).is_err());
    assert!(eval_rpn(&["1", "2"]).is_err());
    println!("{}", eval_rpn(&["5", "1", "2", "+", "4", "*", "+", "3", "-"]).unwrap());
}
```

Operands pop in reverse order, so `a` is the left operand and `b` the right — this matters for `-` and `/`. Parsing falls back to `other.parse()` and every malformed token produces a typed `Err` rather than a panic.

```rust
fn two_largest<T: Ord + Copy>(items: &[T]) -> Option<(T, T)> {
    let mut first: Option<T> = None;
    let mut second: Option<T> = None;
    for &x in items {
        if first.map_or(true, |f| x > f) {
            if first != Some(x) {
                second = first;
                first = Some(x);
            }
        } else if first != Some(x) && second.map_or(true, |s| x > s) {
            second = Some(x);
        }
    }
    match (first, second) {
        (Some(a), Some(b)) => Some((a, b)),
        _ => None,
    }
}

fn main() {
    assert_eq!(two_largest(&[3, 1, 4, 1, 5, 9, 2, 6]), Some((9, 6)));
    assert_eq!(two_largest(&[7, 7, 7]), None);
    assert_eq!(two_largest(&[]), None);
    assert_eq!(two_largest(&[5]), None);
    assert_eq!(two_largest(&["a", "c", "b"]), Some(("c", "b")));
    println!("{:?}", two_largest(&[10, 10, 9]));
}
```

