template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    std::optional<T> at(std::size_t index) const {
        if (index >= size_) return std::nullopt;
        std::size_t start = (head_ + N - size_) % N;
        return data_[(start + index) % N];
    }

    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
