bool parse_int(const std::string& s, int& out) {
    std::size_t i = 0, n = s.size();
    while (i < n && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
    if (i == n) return false;
    std::size_t start = i;
    if (s[i] == '+' || s[i] == '-') ++i;
    bool digit = false;
    for (; i < n && std::isdigit(static_cast<unsigned char>(s[i])); ++i) digit = true;
    if (!digit) return false;
    while (i < n && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
    if (i != n) return false;
    out = std::stoi(s.substr(start, i - start));
    return true;
}

std::vector<int> parse_list(const std::string& line) {
    std::vector<int> out;
    std::stringstream ss(line);
    std::string field;
    while (std::getline(ss, field, ',')) {
        int v;
        if (parse_int(field, v)) out.push_back(v);
    }
    return out;
}

int main() {
    for (int v : parse_list(" 1 , 2 ,, -3 , x , 4 ")) std::cout << v << ' ';
    std::cout << '\n';
}
