```rust
fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    None
}

fn main() {
    let data = [1, 3, 5, 7, 9, 11];
    println!("{:?}", binary_search(&data, &7));
    println!("{:?}", binary_search(&data, &1));
    println!("{:?}", binary_search(&data, &4));
    println!("{:?}", binary_search(&data[..0], &1));
}
```
`lo + (hi - lo) / 2` avoids the overflow the naive `(lo + hi) / 2` can hit. Output is `Some(3)`, `Some(0)`, `None`, `None`. The empty-slice case returns `None` because the loop never runs.

```cpp
#include <cstddef>
#include <stdexcept>
#include <utility>

template <typename T>
class Vec {
public:
    Vec() = default;
    ~Vec() { clear(); }
    Vec(const Vec&) = delete;
    Vec& operator=(const Vec&) = delete;

    void push_back(const T& value) {
        if (size_ == cap_) grow(cap_ ? cap_ * 2 : 1);
        new (data_ + size_) T(value);
        ++size_;
    }

    T& at(std::size_t i) {
        if (i >= size_) throw std::out_of_range("Vec::at");
        return data_[i];
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return cap_; }

private:
    void grow(std::size_t new_cap) {
        T* next = static_cast<T*>(::operator new(new_cap * sizeof(T)));
        for (std::size_t i = 0; i < size_; ++i) {
            new (next + i) T(std::move_if_noexcept(data_[i]));
            data_[i].~T();
        }
        ::operator delete(data_);
        data_ = next;
        cap_ = new_cap;
    }

    void clear() {
        for (std::size_t i = 0; i < size_; ++i) data_[i].~T();
        ::operator delete(data_);
        data_ = nullptr;
        size_ = cap_ = 0;
    }

    T* data_ = nullptr;
    std::size_t size_ = 0;
    std::size_t cap_ = 0;
};

#include <cassert>
#include <string>

int main() {
    Vec<std::string> v;
    v.push_back("a");
    v.push_back("b");
    v.push_back("bb");
    assert(v.size() == 3);
    assert(v.capacity() >= 3);
    assert(v.at(2) == "bb");
    bool threw = false;
    try { v.at(99); } catch (const std::out_of_range&) { threw = true; }
    assert(threw);
}
```

Placement-new keeps raw storage and constructs elements in place; copying is deleted to avoid double frees. `at` throws on out-of-range, indexing beyond bounds is a bug you do not paper over.

