    auto ok = parse("a=1;b=two;c=");
    std::cout << (ok ? "unexpected" : "rejected") << '\n';

    auto good = parse("host=localhost;port=8080");
    std::cout << (good && good->at("host") == "localhost") << '\n';

    auto empty = parse("");
    std::cout << (empty && empty->empty()) << '\n';

    auto bad = parse("no_equals_here");
    std::cout << (bad.has_value() ? "bad" : "nullopt") << '\n';
}
