#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

static struct Node *push(struct Node *head, int value) {
    struct Node *node = malloc(sizeof(*node));
    if (node == NULL) {
        perror("malloc");
        exit(1);
    }
    node->value = value;
    node->next = head;
    return node;
}

static struct Node *reverse(struct Node *head) {
    struct Node *prev = NULL;
    while (head != NULL) {
        struct Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print(const struct Node *head) {
    for (const struct Node *cur = head; cur != NULL; cur = cur->next) {
        printf("%d%s", cur->value, cur->next ? " -> " : "\n");
    }
}

static void free_list(struct Node *head) {
    while (head != NULL) {
        struct Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    struct Node *head = NULL;
    for (int i = 5; i >= 1; --i) {
        head = push(head, i);
    }
    print(head);
    head = reverse(head);
    print(head);
    free_list(head);
    return 0;
}
