template <typename Container, typename T>
std::optional<std::size_t> binary_search_index(const Container& data, const T& target) {
    std::size_t low = 0;
    std::size_t high = data.size();
    while (low < high) {
        const std::size_t mid = low + (high - low) / 2;
        if (data[mid] == target) {
            return mid;
        }
        if (data[mid] < target) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return std::nullopt;
}

