def two_sum(nums, target):
    """Return indices (i, j) such that nums[i] + nums[j] == target.

    Exactly one valid pair is assumed. Each index is used at most once.
    Runs in O(n) time using a lookup table of value -> index.
    """
    seen = {}
    for i, value in enumerate(nums):
        complement = target - value
        if complement in seen:
            return (seen[complement], i)
        seen[value] = i
    raise ValueError("no two indices sum to the target")


if __name__ == "__main__":
