    assert two_sum([3, 3], 6) == (0, 1)
    assert two_sum([-1, 0, 5, 3], 4) == (0, 2)
    assert two_sum([1, 2], 3) == (0, 1)
    try:
        two_sum([1, 2, 3], 100)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for missing pair")
    print("ok")
