import functools
import time


def retry(times=3, base_delay=0.1, backoff=2.0, exceptions=(Exception,)):
    """Retry `times` total attempts, doubling the delay after each failure."""
    if times < 1:
        raise ValueError("times must be at least 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    if attempt == times:
                        raise
                    time.sleep(delay)
                    delay *= backoff
            raise AssertionError("unreachable")
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(times=4, base_delay=0.0)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return calls["n"]

    assert flaky() == 3
    assert calls["n"] == 3

    @retry(times=2, base_delay=0.0)
    def always_fails():
        raise RuntimeError("boom")

    try:
        always_fails()
    except RuntimeError:
        print("raised after retries")
```

`functools.wraps` preserves metadata, and the final attempt re-raises so callers see the real error.

