#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        if (size_ == N) {
            throw std::overflow_error("ring buffer full");
        }
        data_[(head_ + size_) % N] = value;
        ++size_;
    }

    T pop() {
        if (size_ == 0) {
            throw std::underflow_error("ring buffer empty");
        }
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1);
    rb.push(2);
    rb.push(3);
    if (!rb.full()) throw std::logic_error("expected full");
    if (rb.pop() != 1) throw std::logic_error("expected 1");
    rb.push(4);
    if (rb.pop() != 2 || rb.pop() != 3 || rb.pop() != 4)
        throw std::logic_error("wrap order wrong");
    if (!rb.empty()) throw std::logic_error("expected empty");
    std::cout << "ok\n";
}
```

Indices wrap with modulo, so push/pop never need to shift elements. Both full and empty states throw rather than silently discarding data.

```rust
use std::io::{self, BufRead};

fn average_age<R: BufRead>(reader: R) -> Result<f64, String> {
    let mut sum: u64 = 0;
    let mut count: u64 = 0;

    for (line_no, line) in reader.lines().enumerate() {
        let line = line.map_err(|e| format!("read error on line {}: {e}", line_no + 1))?;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let mut parts = trimmed.split(',');
        let name = parts.next().unwrap_or("").trim();
        let age = parts.next().ok_or_else(|| format!("line {}: missing age", line_no + 1))?;
        if name.is_empty() {
            return Err(format!("line {}: missing name", line_no + 1));
        }
        let age: u64 = age
            .trim()
            .parse()
            .map_err(|_| format!("line {}: invalid age {:?}", line_no + 1, age))?;
        sum += age;
        count += 1;
    }

    if count == 0 {
        return Err("no data rows".to_string());
    }
    Ok(sum as f64 / count as f64)
}

fn main() {
    let data = b"name,age\nada,36\nbob,24\n# comment\ncleo,30\n" as &[u8];
    let avg = average_age(data).expect("parse should succeed");
    assert!((avg - 30.0).abs() < 1e-9);

    let bad = b"name,age\nx,abc\n" as &[u8];
    assert!(average_age(bad).is_err());

    let empty = b"" as &[u8];
    assert!(average_age(empty).is_err());

    let _ = io::stdin();
    println!("average age: {avg}");
}
