    assert list(batched([], 3)) == []
    assert list(batched(["a", "b"], 5)) == [("a", "b")]
    assert list(batched("héllo", 2)) == [("h", "é"), ("l", "l"), ("o",)]

    try:
        list(batched([1], 0))
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for size 0")

    print("ok")
