```cpp
#include <cctype>
#include <iostream>
#include <string>

bool is_palindrome(const std::string& s) {
    auto normalize = [](unsigned char c) -> char {
        return static_cast<char>(std::tolower(c));
    };

    std::size_t left = 0;
    std::size_t right = s.size();
    while (left < right) {
        while (left < right && !std::isalnum(static_cast<unsigned char>(s[left]))) {
            ++left;
        }
        while (left < right && !std::isalnum(static_cast<unsigned char>(s[right - 1]))) {
            --right;
        }
        if (left >= right) {
            break;
        }
        if (normalize(s[left]) != normalize(s[right - 1])) {
            return false;
        }
        ++left;
        --right;
    }
    return true;
}

int main() {
    if (!is_palindrome("A man, a plan, a canal: Panama")) return 1;
    if (!is_palindrome("")) return 1;
    if (!is_palindrome("...")) return 1;
    if (is_palindrome("hello")) return 1;
    if (!is_palindrome("No 'x' in Nixon")) return 1;
    std::cout << "ok\n";
    return 0;
}
```

Each character is cast to `unsigned char` before `tolower`/`isalnum` so bytes above 127 are not undefined behaviour.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Encode: each run becomes [count][byte]. count is 1..255. */
static size_t rle_encode(const unsigned char *in, size_t n, unsigned char *out) {
    size_t i = 0, o = 0;
    while (i < n) {
        unsigned char b = in[i];
        size_t run = 1;
        while (i + run < n && in[i + run] == b && run < 255) run++;
        out[o++] = (unsigned char)run;
        out[o++] = b;
        i += run;
    }
    return o;
}

static int rle_decode(const unsigned char *in, size_t n, unsigned char *out, size_t cap, size_t *out_len) {
    size_t i = 0, o = 0;
    while (i + 1 < n) {
        unsigned int count = in[i++];
        unsigned char b = in[i++];
        if (o + count > cap) return -1;
        memset(out + o, b, count);
        o += count;
    }
    *out_len = o;
    return 0;
}

int main(void) {
    const char *s = "aaabbbcccccddddddddddddddd";
    size_t n = strlen(s);
    unsigned char enc[512];
    size_t enc_len = rle_encode((const unsigned char *)s, n, enc);

    unsigned char dec[512];
    size_t dec_len = 0;
    if (rle_decode(enc, enc_len, dec, sizeof dec, &dec_len) != 0) {
        fprintf(stderr, "decode overflow\n");
        return 1;
    }

    printf("input %zu bytes -> encoded %zu bytes\n", n, enc_len);
    if (dec_len != n || memcmp(dec, s, n) != 0) {
        fprintf(stderr, "round-trip failed\n");
        return 1;
    }
    printf("round-trip ok\n");
    return 0;
}
```
Runs longer than 255 are split into multiple `[255][byte]` pairs, so the encoding is lossless for any input length.

```cpp
#include <algorithm>
#include <array>
#include <cctype>
#include <iostream>
#include <string>

bool areAnagrams(std::string a, std::string b) {
    std::array<int, 256> counts{};
    auto fold = [&counts](const std::string &s, int sign) {
        for (unsigned char c : s) {
            counts[static_cast<unsigned char>(std::tolower(c))] += sign;
        }
    };
    fold(a, +1);
    fold(b, -1);
    return std::all_of(counts.begin(), counts.end(), [](int c) { return c == 0; });
}

int main() {
    struct Case { std::string a, b; bool want; };
    Case cases[] = {
        {"Listen", "Silent", true},
        {"hello", "world", false},
        {"", "", true},
        {"a", "", false},
        {"Debit Card", "Bad Credit", false}, // space breaks it
    };
    int failures = 0;
    for (const auto &c : cases) {
        bool got = areAnagrams(c.a, c.b);
        if (got != c.want) {
            std::cerr << "FAIL: '" << c.a << "' vs '" << c.b << "'\n";
            ++failures;
        }
    }
    std::cout << (failures == 0 ? "all passed" : "failures") << "\n";
    return failures == 0 ? 0 : 1;
}
```
Case-folding uses `unsigned char` to avoid undefined behaviour on bytes above 127. Only ASCII case is folded, which is fine for the input class here.

