```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (n == NULL) {
        perror("malloc");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static void print_list(const Node *head) {
    for (const Node *n = head; n != NULL; n = n->next) {
        printf("%d%s", n->value, n->next ? " -> " : "\n");
    }
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++) head = push(head, i);

    print_list(head);                 /* 5 -> 4 -> 3 -> 2 -> 1 */
    head = reverse(head);
    print_list(head);                 /* 1 -> 2 -> 3 -> 4 -> 5 */

    /* edge cases: empty and single node */
    Node *empty = reverse(NULL);
    if (empty != NULL) return 1;
    Node *single = push(NULL, 42);
    single = reverse(single);
    if (single == NULL || single->value != 42 || single->next != NULL) return 1;

    free_list(head);
    free_list(single);
    printf("ok\n");
    return 0;
}
```
The reversal is O(n) time, O(1) space, and handles empty and single-node lists correctly.

```rust
/// Fast doubling: (F(n), F(n+1)) in O(log n) multiplications.
fn fib_pair(n: u64) -> Option<(u64, u64)> {
    if n == 0 {
        return Some((0, 1));
    }
    let (a, b) = fib_pair(n >> 1)?;
    let c = a.checked_mul(b.checked_mul(2)?.checked_sub(a)?)?;
    let d = a.checked_mul(a)?.checked_add(b.checked_mul(b)?)?;
    Some(if n & 1 == 0 { (c, d) } else { (d, c.checked_add(d)?) })
}

pub fn fib(n: u64) -> Option<u64> {
    fib_pair(n).map(|(f, _)| f)
}

fn main() {
    let cases: [(u64, Option<u64>); 8] = [
        (0, Some(0)),
        (1, Some(1)),
        (2, Some(1)),
        (10, Some(55)),
        (20, Some(6765)),
        (50, Some(12586269025)),
        (90, Some(2880067194370816120)),
        (93, None), // 12200160415121876738 > u64::MAX
    ];
    for (n, want) in cases {
        assert_eq!(fib(n), want, "n = {n}");
    }
    println!("all passed");
}
```
All arithmetic is `checked_*`, so overflow returns `None` instead of wrapping. Each recursive step halves `n`, giving O(log n) depth.

