fn longest_common_prefix(words: &[String]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = &words[0];
    let mut end = first.len();
    for w in &words[1..] {
        let mut i = 0;
        let a = first.as_bytes();
        let b = w.as_bytes();
        while i < end && i < b.len() && a[i] == b[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    // byte boundary is safe because a common prefix of UTF-8 is valid UTF-8
    first[..end].to_string()
}

