```python
def fib(n: int) -> int:
    """nth Fibonacci with F(0)=0, F(1)=1. Supports negative n."""
    def _pair(k: int):
        if k == 0:
            return (0, 1)
        a, b = _pair(k >> 1)
        c = a * ((b << 1) - a)
        d = a * a + b * b
        if k & 1:
            return (d, c + d)
        return (c, d)

    if n < 0:
        # F(-n) = (-1)^(n+1) * F(n)
        val = _pair(-n)[0]
        return -val if n % 2 == 0 else val
    return _pair(n)[0]

if __name__ == "__main__":
    print([fib(i) for i in range(10)])
    print(fib(-6))
    print(fib(100))
```

