template <typename T>
std::vector<T> dedupe_stable(const std::vector<T>& in) {
    std::vector<T> out;
    std::unordered_set<T> seen;
    out.reserve(in.size());
    for (const auto& v : in) {
        if (seen.insert(v).second) {
            out.push_back(v);
        }
    }
    return out;
}

int main() {
    std::vector<int> v = {3, 1, 3, 2, 1, 4, 2};
    for (int x : dedupe_stable(v)) std::cout << x << ' ';
    std::cout << '\n';
    std::vector<std::string> s = {"b", "a", "b", "c"};
    for (const auto& x : dedupe_stable(s)) std::cout << x << ' ';
    std::cout << '\n';
}
