static void reverse(int *a, int lo, int hi) {
    while (lo < hi) {
        int t = a[lo];
        a[lo] = a[hi];
        a[hi] = t;
        lo++;
        hi--;
    }
}

void rotate_left(int *a, int n, int k) {
    if (n <= 1) return;
    k %= n;
    if (k < 0) k += n;
    reverse(a, 0, k - 1);
    reverse(a, k, n - 1);
    reverse(a, 0, n - 1);
}

int main(void) {
