def is_balanced(text: str) -> bool:
    """Return True if (), [], {} are correctly balanced and nested.

    Any other character is ignored, so "(a[b]{c})" is balanced.
    """
    pairs = {")": "(", "]": "[", "}": "{"}
    opening = set(pairs.values())
    stack: list[str] = []

    for ch in text:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack


if __name__ == "__main__":
