#include <iostream>
#include <string>

std::string replace_all(const std::string& input,
                        const std::string& from,
                        const std::string& to) {
    if (from.empty()) return input;

    std::string out;
    std::size_t pos = 0;
    while (pos < input.size()) {
        std::size_t hit = input.find(from, pos);
        if (hit == std::string::npos) {
            out.append(input, pos, std::string::npos);
            break;
        }
        out.append(input, pos, hit - pos);
        out += to;
        pos = hit + from.size();  // advance past the match: no re-scan
    }
    return out;
}

int main() {
    // "a" -> "aa" must terminate.
    std::cout << replace_all("aaa", "a", "aa") << '\n';   // aaaaaa
    std::cout << replace_all("hello world", "o", "0") << '\n';
    std::cout << replace_all("abc", "", "x") << '\n';      // abc
    return 0;
}
