import heapq

class RunningMedian:
    def __init__(self):
        self.low = []   # max-heap (negated)
        self.high = []  # min-heap

    def add(self, num):
        heapq.heappush(self.low, -num)
        heapq.heappush(self.high, -heapq.heappop(self.low))
        if len(self.low) < len(self.high):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def median(self):
        if not self.low:
            raise ValueError("empty stream")
        if len(self.low) > len(self.high):
            return float(-self.low[0])
        return (-self.low[0] + self.high[0]) / 2.0

if __name__ == "__main__":
    rm = RunningMedian()
    for v in [5, 15, 1, 3]:
        rm.add(v)
        print(rm.median())  # 5.0, 10.0, 5.0, 4.0
```

`low` keeps the smaller half as a max-heap so its root is the lower median; `high` holds the larger half. Rebalancing keeps `len(low)` equal to or one greater than `len(high)`, which fixes the median at one or two values. Time per insert is O(log n), median lookup is O(1).

