fn is_valid_ipv4(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return false;
    }
    for part in parts {
        if part.is_empty() || part.len() > 3 {
            return false;
        }
        if part.len() > 1 && part.starts_with('0') {
            return false; // no leading zeros except "0"
        }
        if !part.bytes().all(|b| b.is_ascii_digit()) {
            return false;
        }
        match part.parse::<u16>() {
            Ok(n) if n <= 255 => {}
            _ => return false,
        }
    }
    true
}

fn main() {
    for s in ["192.168.0.1", "0.0.0.0", "256.1.1.1", "01.2.3.4", "1.2.3"] {
        println!("{s} -> {}", is_valid_ipv4(s));
    }
}
```

Splitting on `.` must yield exactly four parts; each part rejects leading zeros, non-digits, and values above 255. Parsing into `u16` avoids overflow while still rejecting large numbers.

