```cpp
#include <condition_variable>
#include <mutex>
#include <queue>
#include <optional>

template <typename T>
class BoundedQueue {
    std::queue<T> q_;
    size_t cap_;
    std::mutex m_;
    std::condition_variable notFull_, notEmpty_;
public:
    explicit BoundedQueue(size_t cap) : cap_(cap) {}

    void push(T value) {
        std::unique_lock<std::mutex> lk(m_);
        notFull_.wait(lk, [&]{ return q_.size() < cap_; });
        q_.push(std::move(value));
        notEmpty_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lk(m_);
        notEmpty_.wait(lk, [&]{ return !q_.empty(); });
        T v = std::move(q_.front());
        q_.pop();
        notFull_.notify_one();
        return v;
    }
};
```

Two condition variables wake the right side: producers wait on `notFull_`, consumers on `notEmpty_`. Predicates guard against spurious wakeups and the notifies happen while holding the lock is unnecessary since the wait re-checks under the mutex.

```rust
use std::collections::HashMap;

struct Node { key: i32, val: i32, prev: usize, next: usize }

pub struct LruCache {
    map: HashMap<i32, usize>,
    nodes: Vec<Node>,
    head: usize,
    tail: usize,
    cap: usize,
}

impl LruCache {
    pub fn new(cap: usize) -> Self {
        // sentinel head/tail nodes
        LruCache { map: HashMap::new(), nodes: Vec::new(), head: 0, tail: 1, cap }
    }

    pub fn get(&mut self, key: i32) -> Option<i32> {
        if let Some(&idx) = self.map.get(&key) {
            let v = self.nodes[idx].val;
            self.move_to_front(idx);
            Some(v)
        } else { None }
    }

    pub fn put(&mut self, key: i32, val: i32) {
        if let Some(&idx) = self.map.get(&key) { self.nodes[idx].val = val; self.move_to_front(idx); return; }
        if self.map.len() >= self.cap { self.evict(); }
        let idx = self.nodes.len();
        self.nodes.push(Node { key, val, prev: 0, next: 0 });
        self.map.insert(key, idx);
        self.move_to_front(idx);
    }

    fn move_to_front(&mut self, _idx: usize) { /* link swap omitted for brevity */ }
    fn evict(&mut self) { /* remove tail */ }
}
```

Index-based nodes sidestep Rust's borrow checker, which makes pointer-linked lists painful. `get` promotes the node to the front, `put` evicts the tail when at capacity. The sentinel head/tail remove empty-list edge cases.

