def lower_bound(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo if lo < len(nums) and nums[lo] == target else -1

if __name__ == "__main__":
    print(lower_bound([1, 2, 2, 2, 3, 4], 2))  # 1
    print(lower_bound([1, 2, 3], 5))           # -1
    print(lower_bound([], 1))                  # -1
```

`lo < hi` with `hi = mid` on the else branch converges to the leftmost position where `nums[i] >= target`. A final equality check distinguishes a real hit from an insertion point, and the empty list returns -1.

