    Mat r{1, 0, 0, 1};
    while (e) {
        if (e & 1) r = mul(r, base);
        base = mul(base, base);
        e >>= 1;
    }
    return r;
}

uint64_t fib(uint64_t n) {
    if (n == 0) return 0;
    return power({1, 1, 1, 0}, n - 1).a;
}

int main() {
    std::cout << fib(10) << "\n";  // 55
    std::cout << fib(90) << "\n";  // 2880067194370816120 mod p
    return 0;
}
```

Each multiplication is O(1) on 2x2 matrices, and fast exponentiation gives O(log n). Intermediate products fit in `uint64_t` because entries are below 1e9+7, so a single multiply stays under 1e18.

