constexpr std::uint64_t MOD = 1000000007ULL;

std::uint64_t fib_mod(int n)
{
    if (n < 0) throw std::invalid_argument("n must be >= 0");
    std::uint64_t a = 0, b = 1;
    for (int i = 0; i < n; ++i) {
        std::uint64_t next = (a + b) % MOD;
        a = b;
        b = next;
    }
    return a;
}
