void reverse_bytes(char *buf, size_t len) {
    if (buf == NULL || len < 2) {
        return;
    }
    size_t i = 0, j = len - 1;
    while (i < j) {
        char tmp = buf[i];
        buf[i] = buf[j];
        buf[j] = tmp;
        i++;
        j--;
    }
}

int main(void) {
    char text[] = "ab\0cd";
    size_t len = sizeof(text) - 1; /* 5 bytes, embedded NUL kept */
    reverse_bytes(text, len);
    /* text is now "dc\0ba" */
    if (text[0] != 'd' || text[1] != 'c' || text[2] != '\0' ||
        text[3] != 'b' || text[4] != 'a') {
        fprintf(stderr, "reverse failed\n");
        return 1;
    }
    char empty[1] = {0};
    reverse_bytes(empty, 0); /* no-op, no crash */
    return 0;
}
