#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
class MinHeap {
public:
    void push(const T& value) {
        data_.push_back(value);
        sift_up(data_.size() - 1);
    }

    T pop() {
        if (data_.empty()) throw std::out_of_range("pop on empty heap");
        T top = data_.front();
        data_.front() = data_.back();
        data_.pop_back();
        if (!data_.empty()) sift_down(0);
        return top;
    }

    bool empty() const { return data_.empty(); }
    std::size_t size() const { return data_.size(); }

private:
    void sift_up(std::size_t i) {
        while (i > 0) {
            std::size_t parent = (i - 1) / 2;
            if (data_[parent] <= data_[i]) break;
            std::swap(data_[parent], data_[i]);
            i = parent;
        }
    }

    void sift_down(std::size_t i) {
        const std::size_t n = data_.size();
        while (true) {
            std::size_t smallest = i;
            std::size_t l = 2 * i + 1, r = 2 * i + 2;
            if (l < n && data_[l] < data_[smallest]) smallest = l;
            if (r < n && data_[r] < data_[smallest]) smallest = r;
            if (smallest == i) break;
            std::swap(data_[i], data_[smallest]);
            i = smallest;
        }
    }

    std::vector<T> data_;
};

int main() {
    MinHeap<int> h;
    for (int v : {5, 3, 8, 1, 9, 2}) h.push(v);
    while (!h.empty()) std::cout << h.pop() << ' ';
    std::cout << '\n'; // 1 2 3 5 8 9
    return 0;
}
