template <typename T>
T clamp(const T& value, const T& low, const T& high) {
    if (value < low) return low;
    if (high < value) return high;
    return value;
}

// Overload for C strings: compare by content, not pointer identity.
const char* clamp(const char* value, const char* low, const char* high) {
    if (std::strcmp(value, low) < 0) return low;
    if (std::strcmp(high, value) < 0) return high;
    return value;
}

int main() {
    std::cout << clamp(5, 1, 10) << '\n';          // 5
    std::cout << clamp(-3, 1, 10) << '\n';         // 1
    std::cout << clamp(99, 1, 10) << '\n';         // 10
    std::cout << clamp(2.5, 0.0, 2.0) << '\n';     // 2

    const char* s = clamp("zebra", "apple", "mango");
    std::cout << s << '\n';                        // mango

    std::string a = "kiwi";
    std::cout << clamp(a, std::string("apple"), std::string("mango")) << '\n'; // kiwi

    return 0;
}
