void dedup(char *s) {
    if (s == NULL) return;
    int seen[256] = {0};
    char *write = s;
    for (char *read = s; *read; ++read) {
        unsigned char c = (unsigned char)*read;
        if (!seen[c]) {
            seen[c] = 1;
            *write++ = *read;
        }
    }
    *write = '\0';
}

