def two_sum(nums: list[int], target: int) -> tuple[int, int]:
    seen: dict[int, int] = {}
    for i, n in enumerate(nums):
        want = target - n
        if want in seen:
            return (seen[want], i)
        seen[n] = i
    raise ValueError("no two indices sum to target")

