#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

template <typename Container>
void reverse_in_place(Container& c) {
    // Works for any contiguous or bidirectional container.
    auto first = c.begin();
    auto last = c.end();
    while (first != last && first != --last) {
        std::iter_swap(first, last);
        ++first;
    }
}

int main() {
    std::vector<int> v{1, 2, 3, 4};
    reverse_in_place(v);
    for (int n : v) std::cout << n << ' ';   // 4 3 2 1
    std::cout << '\n';

    std::string s = "hello";
    reverse_in_place(s);
    std::cout << s << '\n';                   // olleh

    std::vector<int> empty;
    reverse_in_place(empty);                  // no-op, safe
    std::cout << empty.size() << '\n';        // 0
}
```
The `first != --last` guard stops before the middle, so both odd and even sizes are handled and an empty container never dereferences.

