#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) {
        perror("malloc");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(const Node *head) {
    for (; head; head = head->next)
        printf("%d%s", head->value, head->next ? " -> " : "\n");
}

int main(void) {
    Node *head = NULL;
    head = push(head, 4);
    head = push(head, 3);
    head = push(head, 2);
    head = push(head, 1);
    print_list(head);
    head = reverse(head);
    print_list(head);
    head = reverse(NULL);
    print_list(head);
    while (head) {
        Node *tmp = head;
        head = head->next;
        free(tmp);
    }
    return 0;
