pub fn lower_bound<T: Ord>(slice: &[T], target: &T) -> usize {
    let mut lo = 0;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if &slice[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
