std::unordered_map<std::string, std::string> parse_pairs(const std::string& input) {
    std::unordered_map<std::string, std::string> out;
    std::stringstream stream(input);
    std::string segment;
    while (std::getline(stream, segment, ';')) {
        auto eq = segment.find('=');
        if (eq == std::string::npos) continue;
        auto trim = [](std::string s) {
            auto not_space = [](unsigned char c) { return !std::isspace(c); };
            s.erase(s.begin(), std::find_if(s.begin(), s.end(), not_space));
            return s;
        };
        std::string key = trim(segment.substr(0, eq));
        std::string value = trim(segment.substr(eq + 1));
        if (key.empty()) continue;
        out[key] = value;
    }
    return out;
}

int main() {
    auto m = parse_pairs(" a = 1 ; b= two ;; bad ; c =");
    for (const auto& kv : m) std::cout << kv.first << " => '" << kv.second << "'\n";
    std::cout << "size=" << m.size() << '\n';
