import functools
import time


def retry(attempts=3, base_delay=0.1, max_delay=2.0, exceptions=(Exception,)):
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    if attempt == attempts:
                        raise
                    time.sleep(min(delay, max_delay))
                    delay *= 2
            raise AssertionError("unreachable")
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=3, base_delay=0.0)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return "done"

    assert flaky() == "done"
    assert calls["n"] == 3
    print("ok")
