#include <stdio.h>
#include <stdint.h>

#define MOD 1000000007ULL

static void fib_pair(unsigned long long n, unsigned long long *a, unsigned long long *b) {
    if (n == 0) { *a = 0; *b = 1; return; }
    unsigned long long x, y;
    fib_pair(n >> 1, &x, &y);
    unsigned long long c = (x * ((2 * y % MOD + MOD - x) % MOD)) % MOD;
    unsigned long long d = (x * x + y * y) % MOD;
    if (n & 1) { *a = d; *b = (c + d) % MOD; }
    else       { *a = c; *b = d; }
}

int main(void) {
    unsigned long long n;
    if (scanf("%llu", &n) != 1) return 1;
    unsigned long long a, b;
    fib_pair(n, &a, &b);
    printf("%llu\n", a);
    return 0;
}
