```rust
use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, BufRead};

fn main() {
    let mut lower = BinaryHeap::new();          // max-heap
    let mut upper: BinaryHeap<Reverse<i64>> = BinaryHeap::new(); // min-heap
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let n: i64 = match line.trim().parse() {
            Ok(v) => v,
            Err(_) => continue,
        };
        if lower.peek().map_or(true, |&m| n <= m) { lower.push(n); } else { upper.push(Reverse(n)); }
        if lower.len() > upper.len() + 1 { upper.push(Reverse(lower.pop().unwrap())); }
        else if upper.len() > lower.len() { lower.push(upper.pop().unwrap().0); }
        let median = if lower.len() == upper.len() {
            (*lower.peek().unwrap() as f64 + upper.peek().unwrap().0 as f64) / 2.0
        } else {
            *lower.peek().unwrap() as f64
        };
        println!("{}", median);
    }
}
```

A max-heap holds the lower half, a min-heap the upper half; after every insert the sizes differ by at most one, so the median is the lower heap's top or the average of both tops. Each element costs O(log n).

