#include <iostream>
#include <vector>

int lower_bound_index(const std::vector<int>& v, int target) {
    int lo = 0, hi = static_cast<int>(v.size());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] < target) lo = mid + 1;
        else                 hi = mid;
    }
    return lo; // first index whose element is >= target
}

int main() {
    std::vector<int> v = {1, 3, 3, 5, 8};
    std::cout << lower_bound_index(v, 3) << '\n'; // 1
    std::cout << lower_bound_index(v, 4) << '\n'; // 3 (insertion point)
    std::cout << lower_bound_index(v, 0) << '\n'; // 0
    std::cout << lower_bound_index(v, 9) << '\n'; // 5
    return 0;
}
```

The loop narrows `[lo, hi)` until it collapses, so `lo` is both the first matching index and the correct insertion point for absent values. `lo + (hi - lo) / 2` avoids overflow on large vectors and the whole search is O(log n).

