// returns {F(n), F(n+1)}
static std::pair<unsigned long long, unsigned long long> fib_pair(unsigned n) {
    if (n == 0) return {0ULL, 1ULL};
    auto p = fib_pair(n >> 1);
    unsigned long long a = p.first;                    // F(k)
    unsigned long long b = p.second;                   // F(k+1)
    unsigned long long c = a * (2 * b - a);            // F(2k)
    unsigned long long d = a * a + b * b;              // F(2k+1)
    if (n & 1ULL) return {d, c + d};
    return {c, d};
}

unsigned long long fib(unsigned n) { return fib_pair(n).first; }

