def rle_decode(s: str) -> str:
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        num_start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        if num_start == i:
            raise ValueError(f"missing count after {ch!r} at {num_start}")
        out.append(ch * int(s[num_start:i]))
    return "".join(out)


