void reverse_in_place(char* s) {
    if (s == nullptr) return;
    std::size_t n = std::strlen(s);
    if (n < 2) return;
    for (std::size_t i = 0; i < n / 2; ++i) {
        char tmp = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = tmp;
    }
