```python
class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = [0.0] * capacity
        self._count = 0
        self._next = 0

    def push(self, value):
        self._data[self._next] = float(value)
        self._next = (self._next + 1) % self.capacity
        if self._count < self.capacity:
            self._count += 1

    def __len__(self):
        return self._count

    def mean(self):
        if self._count == 0:
            return 0.0
        return sum(self._data[: self._count]) / self._count


if __name__ == "__main__":
    rb = RingBuffer(3)
    rb.push(2)
    rb.push(4)
    print(rb.mean())  # 3.0
    rb.push(6)
    rb.push(8)        # overwrites 2
    print(len(rb), rb.mean())
```

Before the buffer is full, the written values occupy indices `0..count`, so `mean` slices only those. Once full, `_count` stays at capacity and `_next` wraps, overwriting the oldest slot.

