#include <array>
#include <cassert>
#include <cstddef>
#include <optional>

template <typename T, std::size_t Cap>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == Cap) return false;
        data_[(head_ + count_) % Cap] = value;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % Cap;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }

private:
    std::array<T, Cap> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(!rb.push(4));           // full
    assert(rb.size() == 3);
    assert(rb.pop() == 1);
    assert(rb.push(4));            // wraps around
    assert(rb.pop() == 2);
    assert(rb.pop() == 3);
    assert(rb.pop() == 4);
    assert(rb.empty());
    assert(!rb.pop().has_value());
    return 0;
}
```
Indices wrap with `% Cap`, and `pop` on an empty buffer returns `std::nullopt` rather than reading stale memory.

