fn find_substring(haystack: &str, needle: &str) -> Option<usize> {
    let h = haystack.as_bytes();
    let n = needle.as_bytes();
    if n.is_empty() {
        return Some(0);
    }
    if n.len() > h.len() {
        return None;
    }
    for start in 0..=(h.len() - n.len()) {
        if &h[start..start + n.len()] == n {
            return Some(start);
        }
    }
    None
}

fn main() {
    assert_eq!(find_substring("hello world", "world"), Some(6));
    assert_eq!(find_substring("aaaa", "aa"), Some(0));
    assert_eq!(find_substring("abc", "d"), None);
    assert_eq!(find_substring("abc", ""), Some(0));
    assert_eq!(find_substring("", "a"), None);
    // byte-safe on multibyte input
    assert_eq!(find_substring("héllo", "llo"), Some(3));
    println!("ok");
}
```
The loop bound `0..=(h.len() - n.len())` avoids an out-of-bounds slice, and byte comparison keeps it correct on UTF-8 without char iteration.

