#include <cassert>
#include <cstddef>
#include <iostream>
#include <vector>

std::size_t removeDuplicates(std::vector<int>& v) {
    if (v.empty()) return 0;
    std::size_t write = 1;
    for (std::size_t read = 1; read < v.size(); ++read) {
        if (v[read] != v[write - 1]) {
            v[write++] = v[read];
        }
    }
    return write;
}

int main() {
    std::vector<int> a{1, 1, 2, 3, 3, 3, 4};
    std::size_t n = removeDuplicates(a);
    assert(n == 4);
    assert((std::vector<int>(a.begin(), a.begin() + n) == std::vector<int>{1, 2, 3, 4}));

    std::vector<int> empty;
    assert(removeDuplicates(empty) == 0);

    std::vector<int> allSame(5, 7);
    assert(removeDuplicates(allSame) == 1);

    std::cout << "ok" << std::endl;
    return 0;
}
```

Uses a read/write index pair, so it is O(n) time and O(1) extra space. Only the first `n` elements are meaningful after the call; the tail is stale, which is why the assertions slice with `a.begin() + n`.

