```rust
use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum ParseError {
    DuplicateKey(String),
}

pub fn parse_pairs(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    for entry in input.split(';') {
        let entry = entry.trim();
        if entry.is_empty() {
            continue;
        }
        let Some((key, value)) = entry.split_once('=') else {
            continue; // malformed: no '='
        };
        let key = key.trim();
        let value = value.trim();
        if key.is_empty() {
            continue;
        }
        if map.insert(key.to_string(), value.to_string()).is_some() {
            return Err(ParseError::DuplicateKey(key.to_string()));
        }
    }
    Ok(map)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_and_trims() {
        let m = parse_pairs("a=1; b = two ;;c=x=y").unwrap();
        assert_eq!(m.get("a").map(String::as_str), Some("1"));
        assert_eq!(m.get("b").map(String::as_str), Some("two"));
        assert_eq!(m.get("c").map(String::as_str), Some("x=y"));
    }

    #[test]
    fn rejects_duplicates() {
        assert_eq!(parse_pairs("a=1;a=2"), Err(ParseError::DuplicateKey("a".into())));
    }

    #[test]
    fn empty_input() {
        assert!(parse_pairs("").unwrap().is_empty());
    }
}
```

`split_once` keeps only the first `=`, so values may contain `=`; malformed fragments without a separator or with an empty key are skipped rather than erroring. The `insert` return value doubles as the duplicate check.

