#include <cstddef>
#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t cap) : data_(cap), cap_(cap) {}

    bool push(int v) {
        if (size_ == cap_) return false;
        data_[(head_ + size_) % cap_] = v;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int v = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<int> data_;
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << '\n';
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n';
    rb.push(9);
    std::cout << *rb.pop() << '\n';
}
