#include <cstddef>
#include <iostream>
#include <vector>

int bsearch(const std::vector<int>& a, int target) {
    int lo = 0, hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

std::size_t lower_bound(const std::vector<int>& a, int target) {
    std::size_t lo = 0, hi = a.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

int main() {
    std::vector<int> a{1, 3, 3, 5, 8};
    std::cout << bsearch(a, 5) << '\n';
    std::cout << bsearch(a, 4) << '\n';
    std::cout << lower_bound(a, 3) << '\n';
}
