Here's an expand-around-center solution. It checks both odd- and even-length centers, runs in O(n²) time and O(1) extra space.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    start, end = 0, 0

    def expand(left: int, right: int) -> tuple[int, int]:
        # Grow while the characters match and stay in bounds.
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        # The last successful window is [left+1, right-1].
        return left + 1, right - 1

    for i in range(len(s)):
        # Odd-length palindrome centered on i.
        l1, r1 = expand(i, i)
        # Even-length palindrome centered between i and i+1.
        l2, r2 = expand(i, i + 1)

        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "abacdfgdcaba"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```

Edge handling: empty string returns `""`, single characters return themselves, and ties keep the first (earliest) longest window since the comparison is strict `>`.

Using a `std::priority_queue` min-heap keeps the top-k selection at O(n log k) time and O(k) extra space.

```cpp
#include <iostream>
#include <queue>
#include <vector>
#include <algorithm>

std::vector<int> kLargest(const std::vector<int>& nums, std::size_t k) {
    if (k == 0 || nums.empty()) return {};
    if (k >= nums.size()) {
        std::vector<int> all = nums;
        std::sort(all.begin(), all.end(), std::greater<int>());
        return all;
    }

    // Min-heap of size k: the smallest of the current top-k is on top.
    std::priority_queue<int, std::vector<int>, std::greater<int>> heap;
    for (int v : nums) {
        if (heap.size() < k) {
            heap.push(v);
        } else if (v > heap.top()) {
            heap.pop();
            heap.push(v);
        }
    }

    std::vector<int> result;
    result.reserve(k);
    while (!heap.empty()) {
        result.push_back(heap.top());
        heap.pop();
    }
    // Heap yields ascending order; reverse for descending.
    std::reverse(result.begin(), result.end());
    return result;
}

int main() {
    std::size_t k;
    if (!(std::cin >> k)) {
        std::cerr << "expected k first\n";
        return 1;
    }
    std::vector<int> nums;
    int x;
    while (std::cin >> x) nums.push_back(x);

    auto top = kLargest(nums, k);
    for (std::size_t i = 0; i < top.size(); ++i) {
        if (i) std::cout << ' ';
        std::cout << top[i];
    }
    std::cout << '\n';
    return 0;
}
```

Empty input yields an empty line; `k` larger than the list returns everything sorted descending. Read errors on `k` are reported to stderr.

A small state machine handles quotes and escaped `""` without pulling in a crate.

```rust
use std::iter::Peekable;
use std::str::Chars;

/// Parse one CSV line. Double-quoted fields may contain commas and "" escapes.
pub fn parse_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut field = String::new();
    let mut chars: Peekable<Chars> = line.chars().peekable();
    let mut in_quotes = false;

    while let Some(c) = chars.next() {
        if in_quotes {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    chars.next();
                    field.push('"'); // escaped quote
                } else {
                    in_quotes = false; // closing quote
                }
            } else {
                field.push(c);
            }
        } else {
            match c {
                '"' => in_quotes = true,
                ',' => {
                    fields.push(std::mem::take(&mut field));
                }
                _ => field.push(c),
            }
        }
    }
    fields.push(field);
    fields
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn plain_and_quoted() {
        assert_eq!(parse_csv_line("a,b,c"), vec!["a", "b", "c"]);
        assert_eq!(
            parse_csv_line("1,\"a,b\",\"say \"\"hi\"\"\""),
            vec!["1", "a,b", "say \"hi\""]
        );
        assert_eq!(parse_csv_line(""), vec![""]);
        assert_eq!(parse_csv_line("\"\""), vec![""]);
    }
}
```

Edge cases: an empty line yields one empty field, `""` yields an empty field, and `""` inside quotes is a literal quote. Embedded newlines aren't handled since this reads a single line.

The midpoint is computed as `lo + (hi - lo) / 2` to avoid overflow on the naive `(lo + hi) / 2`.

```c
#include <stdio.h>
#include <stddef.h>

/* Returns the index of target in arr[0..n), or -1 if absent.
   arr must be sorted ascending. */
int binary_search(const int arr[], size_t n, int target) {
    size_t lo = 0;
    size_t hi = n; // exclusive upper bound

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2; // overflow-safe midpoint
        if (arr[mid] == target) {
            return (int)mid;
        } else if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

int main(void) {
    int arr[] = {1, 3, 3, 5, 8, 13, 21};
    size_t n = sizeof(arr) / sizeof(arr[0]);

    int targets[] = {3, 1, 21, 4, 0};
    for (size_t i = 0; i < sizeof(targets) / sizeof(targets[0]); ++i) {
        int t = targets[i];
        printf("search(%d) = %d\n", t, binary_search(arr, n, t));
    }
    return 0;
}
```

The half-open bound `[lo, hi)` means an empty array (`n == 0`) loops zero times and returns -1. Duplicate values return any matching index, which is fine for a presence search.

