```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <stdexcept>

uint64_t fib(std::size_t n) {
    if (n > 93) {
        throw std::out_of_range("n too large for uint64_t (max 93)");
    }
    static std::vector<uint64_t> memo = {0, 1};
    if (n < memo.size()) return memo[n];

    for (std::size_t i = memo.size(); i <= n; ++i) {
        memo.push_back(memo[i - 1] + memo[i - 2]);
    }
    return memo[n];
}

int main() {
    long long input;
    if (!(std::cin >> input)) {
        std::cerr << "expected an integer\n";
        return 1;
    }
    if (input < 0) {
        std::cerr << "n must be non-negative\n";
        return 1;
    }
    try {
        std::cout << "fib(" << input << ") = " << fib(static_cast<std::size_t>(input)) << '\n';
    } catch (const std::out_of_range& e) {
        std::cerr << "error: " << e.what() << '\n';
        return 1;
    }
    return 0;
}
