```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TOP_N 5

static int cmp_desc(const void *a, const void *b) {
    const unsigned long *x = a, *y = b;
    return (*y > *x) - (*y < *x); // descending
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "rb");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    unsigned long counts[256] = {0};
    unsigned char buf[8192];
    size_t n;
    while ((n = fread(buf, 1, sizeof buf, fp)) > 0) {
        for (size_t i = 0; i < n; ++i) {
            counts[buf[i]]++;
        }
    }
    if (ferror(fp)) {
        perror("fread");
        fclose(fp);
        return 1;
    }
    fclose(fp);

    // Pair each byte value with its count, then sort descending.
    struct { unsigned long count; int byte; } table[256];
    for (int i = 0; i < 256; ++i) {
        table[i].count = counts[i];
        table[i].byte = i;
    }

    // Simple selection of the top N avoids comparing compound structs with qsort.
    for (int k = 0; k < TOP_N && k < 256; ++k) {
        int best = k;
        for (int i = k + 1; i < 256; ++i) {
            if (table[i].count > table[best].count) best = i;
        }
        struct { unsigned long count; int byte; } tmp = table[k];
        table[k] = table[best];
        table[best] = tmp;
        printf("0x%02x  %lu\n", table[k].byte, table[k].count);
    }

    return 0;
}
```

