```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), capacity_(capacity) {}

    void push(int value) {
        if (capacity_ == 0) return;
        buf_[head_] = value;
        head_ = (head_ + 1) % capacity_;
        if (size_ < capacity_) ++size_;
    }

    std::optional<double> average() const {
        if (size_ == 0) return std::nullopt;
        long long sum = 0;
        for (std::size_t i = 0; i < size_; ++i)
            sum += buf_[(head_ + capacity_ - size_ + i) % capacity_];
        return static_cast<double>(sum) / static_cast<double>(size_);
    }

private:
    std::vector<int> buf_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    rb.push(1); rb.push(2); rb.push(3);
    std::cout << *rb.average() << "\n";   // 2
    rb.push(6);
    std::cout << *rb.average() << "\n";   // (2+3+6)/3 = 3.66667
    RingBuffer empty(0);
    std::cout << (empty.average().has_value() ? "has" : "none") << "\n";
    return 0;
}
```

Wraps writes with modulo arithmetic and tracks `size_` separately from capacity, so reads can walk the oldest-to-newest window. `average()` returns `nullopt` when the buffer is empty instead of dividing by zero.

