#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int v) {
    Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(1); }
    n->value = v;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++) head = push(head, i); /* 5 4 3 2 1 */
    head = reverse(head);                              /* 1 2 3 4 5 */
    for (Node *p = head; p; p = p->next) printf("%d%s", p->value, p->next ? " " : "\n");
    while (head) { Node *n = head->next; free(head); head = n; }
    return 0;
}
```

