std::pair<long long,long long> fib_pair(long long n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n / 2);
    long long c = a * ((2 * b % MOD - a + MOD) % MOD) % MOD; // F(2k)
    long long d = (a * a + b * b) % MOD;                     // F(2k+1)
    if (n % 2 == 0) return {c, d};
    return {d, (c + d) % MOD};
}

