def kth_smallest(nums, k):
    """Return the k-th smallest element (1-indexed k) of nums."""
    if not nums:
        raise ValueError("nums is empty")
    if not 1 <= k <= len(nums):
        raise ValueError(f"k must be between 1 and {len(nums)}, got {k}")

    def partition(arr, lo, hi):
        pivot = arr[hi]
        i = lo
        for j in range(lo, hi):
            if arr[j] <= pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[hi] = arr[hi], arr[i]
        return i

    arr = list(nums)
    lo, hi, target = 0, len(arr) - 1, k - 1
    while lo <= hi:
        p = partition(arr, lo, hi)
        if p == target:
            return arr[p]
        if p < target:
            lo = p + 1
        else:
            hi = p - 1


if __name__ == "__main__":
    print(kth_smallest([7, 10, 4, 3, 20, 15], 3))   # 7
    print(kth_smallest([7, 10, 4, 3, 20, 15], 1))   # 3
    print(kth_smallest([1, 1, 1], 2))               # 1
```

