// std::array overload: sizes are checked at compile time.
template <typename T, std::size_t N>
constexpr T dot(const std::array<T, N>& a, const std::array<T, N>& b) {
    T acc = T{};
    for (std::size_t i = 0; i < N; ++i) acc += a[i] * b[i];
    return acc;
}

// std::vector overload: sizes checked at run time.
template <typename T>
T dot(const std::vector<T>& a, const std::vector<T>& b) {
    if (a.size() != b.size()) throw std::invalid_argument("size mismatch");
    T acc = T{};
    for (std::size_t i = 0; i < a.size(); ++i) acc += a[i] * b[i];
    return acc;
}

int main() {
    constexpr std::array<int, 3> x{1, 2, 3};
    constexpr std::array<int, 3> y{4, 5, 6};
    static_assert(dot(x, y) == 32);
    std::cout << dot(x, y) << "\n";

    std::vector<double> u{0.5, 1.5};
    std::vector<double> v{2.0, 4.0};
    std::cout << dot(u, v) << "\n";   // 7
}
```

The `std::array` version is a template on `N`, so `dot(x, z)` for mismatched arrays is a compile error; `dot` is `constexpr` and verified by a `static_assert`. The vector version throws instead.

