```cpp
#include <vector>
#include <stdexcept>
#include <iostream>

template <typename T>
class BoundedStack {
public:
    explicit BoundedStack(std::size_t cap) : cap_(cap) {
        if (cap == 0) throw std::invalid_argument("capacity must be > 0");
    }
    void push(const T& v) {
        if (data_.size() >= cap_) throw std::overflow_error("stack full");
        data_.push_back(v);
    }
    T pop() {
        if (data_.empty()) throw std::underflow_error("stack empty");
        T v = data_.back();
        data_.pop_back();
        return v;
    }
    const T& peek() const {
        if (data_.empty()) throw std::underflow_error("stack empty");
        return data_.back();
    }
    bool empty() const { return data_.empty(); }
    std::size_t size() const { return data_.size(); }
private:
    std::vector<T> data_;
    std::size_t cap_;
};

int main() {
    BoundedStack<int> s(2);
    s.push(1);
    s.push(2);
    std::cout << s.peek() << "\n";
    try { s.push(3); } catch (const std::exception& e) { std::cout << e.what() << "\n"; }
    std::cout << s.pop() << " " << s.pop() << "\n";
    try { s.pop(); } catch (const std::exception& e) { std::cout << e.what() << "\n"; }
    return 0;
}
```
Stores elements in a vector, enforces the capacity on push, and throws `std::out_of_range`-style errors on overflow/underflow. A zero capacity is rejected at construction.

```rust
fn fib(n: u64) -> u64 {
    let mut a: u64 = 0;
    let mut b: u64 = 1;
    for _ in 0..n {
        let next = a + b;
        a = b;
        b = next;
    }
    a
}

fn fib_iter(n: u64) -> impl Iterator<Item = u64> {
    let mut a: u64 = 0;
    let mut b: u64 = 1;
    (0..n).map(move |_| {
        let cur = a;
        let next = a + b;
        a = b;
        b = next;
        cur
    })
}

