```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
} List;

void list_push(List *list, int value) {
    Node *node = malloc(sizeof(Node));
    if (!node) return;
    node->value = value;
    node->next = list->head;
    list->head = node;
}

void list_reverse(List *list) {
    Node *prev = NULL;
    Node *cur = list->head;
    while (cur) {
        Node *next = cur->next;  /* save before relinking */
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    list->head = prev;
}

void list_print(const List *list) {
    for (const Node *n = list->head; n; n = n->next) {
        printf("%d%s", n->value, n->next ? " " : "\n");
    }
}

void list_free(List *list) {
    Node *cur = list->head;
    while (cur) {
        Node *next = cur->next;
        free(cur);
        cur = next;
    }
    list->head = NULL;
}

int main(void) {
    List list = {NULL};
    for (int i = 1; i <= 5; i++) list_push(&list, i);
    list_print(&list);      /* 5 4 3 2 1 */
    list_reverse(&list);
    list_print(&list);      /* 1 2 3 4 5 */

    List empty = {NULL};
    list_reverse(&empty);   /* no crash on empty list */
    printf("empty reversed ok\n");
    list_free(&list);
    return 0;
}
```

The loop saves `cur->next` before overwriting it, so no node is lost. An empty list is safe because the first assignment to `prev` is `NULL` and the loop body never runs.

