use std::collections::HashMap;

fn parse_config(input: &str) -> Result<HashMap<String, i64>, String> {
    let mut map = HashMap::new();
    for raw in input.split(';') {
        let pair = raw.trim();
        if pair.is_empty() {
            continue; // allow trailing or doubled semicolons
        }
        let (key, value) = pair
            .split_once('=')
            .ok_or_else(|| format!("missing '=' in segment: {pair:?}"))?;
        let key = key.trim();
        if key.is_empty() {
            return Err(format!("empty key in segment: {pair:?}"));
        }
        let parsed: i64 = value
            .trim()
            .parse()
            .map_err(|e| format!("bad integer for {key:?}: {e}"))?;
        map.insert(key.to_string(), parsed);
    }
    Ok(map)
}

fn main() {
    let cfg = parse_config("a=1; b=2; c=3; ").unwrap();
    assert_eq!(cfg["a"], 1);
    assert_eq!(cfg.len(), 3);

    assert!(parse_config("x=;y=2").is_err());
    assert!(parse_config("nokey").is_err());
    assert!(parse_config("k=abc").is_err());
    assert!(parse_config("").unwrap().is_empty());
    println!("ok");
}
