fn longest_common_prefix(words: &[&str]) -> String {
    let Some(first) = words.first() else {
        return String::new();
    };
    let mut end = first.len();
    for word in &words[1..] {
        end = end.min(word.len());
        end = first
            .char_indices()
            .zip(word.char_indices())
            .take_while(|((_, a), (_, b))| a == b)
            .take(end)
            .count()
            .min(end);
        // recompute on byte boundary of `first`
        let mut boundary = 0;
        for (idx, (a, b)) in first.char_indices().zip(word.char_indices()) {
            if a != b { break; }
            boundary = idx + a.len_utf8();
        }
        end = end.min(boundary);
    }
    first[..end].to_string()
}

fn main() {
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["dog"]), "dog");
    assert_eq!(longest_common_prefix(&["café", "caféine"]), "café");
    println!("ok");
}
