#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    for (size_t i = 0; i < len / 2; ++i) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "x";
    char d[] = "ab";

    reverse_in_place(a);
    reverse_in_place(b);
    reverse_in_place(c);
    reverse_in_place(d);
    reverse_in_place(NULL);

    printf("%s %s %s %s\n", a, b, c, d);
    return 0;
}
