#include <cctype>
#include <iostream>
#include <optional>
#include <sstream>
#include <string>
#include <vector>

std::vector<std::string> split_trim(const std::string& line) {
    std::vector<std::string> out;
    std::string field;
    std::istringstream ss(line);
    while (std::getline(ss, field, ',')) {
        size_t b = 0, e = field.size();
        while (b < e && std::isspace(static_cast<unsigned char>(field[b]))) ++b;
        while (e > b && std::isspace(static_cast<unsigned char>(field[e - 1]))) --e;
        if (e > b) out.push_back(field.substr(b, e - b));
    }
    return out;
}

std::optional<long long> parse_int(const std::string& s) {
    try {
        size_t used = 0;
        long long v = std::stoll(s, &used, 10);
        if (used != s.size()) return std::nullopt;
        return v;
    } catch (...) {
        return std::nullopt;
    }
}

std::optional<long long> sum_csv(const std::string& line) {
    long long total = 0;
    for (const auto& tok : split_trim(line)) {
        auto v = parse_int(tok);
        if (!v) return std::nullopt;
        total += *v;
    }
    return total;
}

int main() {
    const std::vector<std::pair<std::string, std::optional<long long>>> cases = {
        {"", 0},
        {"1,2,3", 6},
        {" 10 , , 20 ", 30},
        {"5,abc", std::nullopt},
        {"-4,4", 0},
        {"1,,2,", 3},
    };
    for (const auto& [in, want] : cases) {
        auto got = sum_csv(in);
        bool ok = (got == want);
        std::cout << (ok ? "ok " : "FAIL ") << '"' << in << '"';
        if (got) std::cout << " -> " << *got;
        else std::cout << " -> invalid";
        std::cout << '\n';
    }
    return 0;
}
```

`split_trim` uses `std::getline` so an empty final field still produces an empty token, which is dropped. `parse_int` rejects anything with trailing garbage, so `5,abc` returns no value rather than a partial parse. Empty input and trailing commas both resolve to a sum of 0, and negative numbers mix correctly.

