```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *reverse(const char *s, size_t n) {
    char *out = malloc(n + 1);
    if (!out) return NULL;
    for (size_t i = 0; i < n; ++i) out[i] = s[n - 1 - i];
    out[n] = '\0';
    return out;
}

int main(void) {
    char *line = NULL;
    size_t cap = 0;
    ssize_t len;

    while ((len = getline(&line, &cap, stdin)) != -1) {
        size_t n = (size_t)len;
        int had_newline = (n > 0 && line[n - 1] == '\n');
        size_t body = had_newline ? n - 1 : n;

        char *flipped = reverse(line, body);
        if (!flipped) {
            free(line);
            fprintf(stderr, "out of memory\n");
            return 1;
        }
        fputs(flipped, stdout);
        if (had_newline) fputc('\n', stdout);
        free(flipped);
    }

    free(line);
    return ferror(stdin) ? 1 : 0;
}
```

`getline` grows the buffer as needed, so line length is bounded only by memory. The trailing newline is stripped before reversing and re-added after, so a reversed line still ends the line rather than moving the newline to the front. A final line without a newline is handled by the `had_newline` check. Allocation failure and read errors both exit nonzero.

```rust
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 4, 6];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 4, 5, 6, 7]);

    let empty: [i32; 0] = [];
    assert_eq!(merge_sorted(&empty, &[9]), vec![9]);
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());

    let dup = [1, 1, 2];
    let dup2 = [1, 2, 2];
    assert_eq!(merge_sorted(&dup, &dup2), vec![1, 1, 1, 2, 2, 2]);

    println!("all checks passed");
}
```

The loop advances whichever head is smaller, using `<=` so equal elements from `a` come first and stability is preserved. Once one slice is exhausted the remainder of the other is copied with `extend_from_slice` since it is already sorted. Capacity is preallocated to `a.len() + b.len()` so no reallocation happens mid-merge. Empty slices and duplicates are both exercised.

```cpp
#include <iostream>
#include <stdexcept>
#include <vector>

class MinHeap {
public:
    void push(int v) {
        data_.push_back(v);
        sift_up(data_.size() - 1);
    }

    int pop() {
        if (data_.empty()) throw std::out_of_range("pop on empty heap");
        int top = data_.front();
        data_.front() = data_.back();
        data_.pop_back();
        if (!data_.empty()) sift_down(0);
        return top;
    }

    int peek() const {
        if (data_.empty()) throw std::out_of_range("peek on empty heap");
        return data_.front();
    }

    bool empty() const { return data_.empty(); }
    std::size_t size() const { return data_.size(); }

private:
    std::vector<int> data_;

    void sift_up(std::size_t i) {
        while (i > 0) {
            std::size_t parent = (i - 1) / 2;
            if (data_[parent] <= data_[i]) break;
            std::swap(data_[parent], data_[i]);
            i = parent;
        }
    }

    void sift_down(std::size_t i) {
        const std::size_t n = data_.size();
        while (true) {
            std::size_t left = 2 * i + 1, right = 2 * i + 2, best = i;
            if (left < n && data_[left] < data_[best]) best = left;
            if (right < n && data_[right] < data_[best]) best = right;
            if (best == i) break;
            std::swap(data_[i], data_[best]);
            i = best;
        }
    }
};

int main() {
    MinHeap h;
    for (int v : {5, 3, 8, 1, 9, 2}) h.push(v);

    std::vector<int> drained;
    while (!h.empty()) drained.push_back(h.pop());

    const std::vector<int> expected{1, 2, 3, 5, 8, 9};
    std::cout << (drained == expected ? "ok" : "FAIL") << '\n';

    try {
        MinHeap empty;
        empty.pop();
        std::cout << "FAIL no throw\n";
    } catch (const std::out_of_range&) {
        std::cout << "empty pop throws ok\n";
    }
}
```

`push` appends and bubbles up while the parent is larger. `pop` takes the root, moves the last element to the front, shrinks, and sifts down along the smaller child. Array indexing gives the parent at `(i-1)/2` and children at `2i+1` and `2i+2`. Draining the heap yields values in nondecreasing order, which the demo asserts. Both `pop` and `peek` throw on an empty heap.

