```c
#include <stdbool.h>
#include <stdio.h>
#include <stddef.h>

#define CAP 4

typedef struct {
    int data[CAP];
    size_t head;
    size_t count;
} ring_t;

typedef struct { bool ok; int value; } pop_result_t;

static void ring_init(ring_t *r) { r->head = 0; r->count = 0; }

static bool ring_push(ring_t *r, int value) {
    if (r->count == CAP) return false;
    r->data[(r->head + r->count) % CAP] = value;
    r->count++;
    return true;
}

static pop_result_t ring_pop(ring_t *r) {
    pop_result_t res = { false, 0 };
    if (r->count == 0) return res;
    res.ok = true;
    res.value = r->data[r->head];
    r->head = (r->head + 1) % CAP;
    r->count--;
    return res;
}

int main(void) {
    ring_t r;
    ring_init(&r);

    for (int i = 0; i < CAP; i++) printf("%d\n", ring_push(&r, i));       // 1 1 1 1
    printf("%d\n", ring_push(&r, 99));                                    // 0 (full)

    pop_result_t a = ring_pop(&r);
    printf("%d %d\n", a.ok, a.value);                                     // 1 0

    printf("%d\n", ring_push(&r, 42));                                    // 1 (space freed)

    pop_result_t b;
    while ((b = ring_pop(&r)).ok) printf("%d\n", b.value);                // 1 2 3 42

    pop_result_t c = ring_pop(&r);
    printf("%d\n", c.ok);                                                 // 0 (empty)
    return 0;
}
```
Push fails when full, pop reports emptiness through the `ok` flag. The indexes wrap with modulo so no shifting is needed. `pop_result_t` makes the not-found case explicit rather than returning a sentinel value.

