#include <cassert>
#include <vector>

// nums1 has size m + n with only the first m elements valid; nums2 has size n.
void merge(std::vector<int>& nums1, int m, const std::vector<int>& nums2, int n) {
    int i = m - 1;      // tail of valid part of nums1
    int j = n - 1;      // tail of nums2
    int k = m + n - 1;  // tail of full nums1
    while (j >= 0) {
        if (i >= 0 && nums1[i] > nums2[j]) {
            nums1[k--] = nums1[i--];
        } else {
            nums1[k--] = nums2[j--];
        }
    }
}

int main() {
    std::vector<int> a{1, 2, 3, 0, 0, 0};
    std::vector<int> b{2, 5, 6};
    merge(a, 3, b, 3);
    assert((a == std::vector<int>{1, 2, 2, 3, 5, 6}));

    std::vector<int> c{0, 0, 0};
    std::vector<int> d{1, 2, 3};
    merge(c, 0, d, 3);
    assert((c == std::vector<int>{1, 2, 3}));

    std::vector<int> e{1};
    std::vector<int> f{};
    merge(e, 1, f, 0);
    assert((e == std::vector<int>{1}));
    return 0;
}
```

Filling from the back means no element of `nums1` is overwritten before it is read. The loop is driven by `j`, so when `nums2` is exhausted the already-sorted prefix of `nums1` is left untouched.

```cpp
#include <cstdint>
#include <cstdio>
#include <string>

static bool is_valid_utf8(const std::string& s) {
    size_t i = 0;
    const size_t n = s.size();
    while (i < n) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        size_t need;
        uint32_t cp;
        if (c <= 0x7F) {
            i += 1;
            continue;
        } else if ((c & 0xE0) == 0xC0) {
            need = 1;
            cp = c & 0x1F;
        } else if ((c & 0xF0) == 0xE0) {
            need = 2;
            cp = c & 0x0F;
        } else if ((c & 0xF8) == 0xF0) {
            need = 3;
            cp = c & 0x07;
        } else {
            return false;  // continuation byte or 5+ byte lead
        }
        if (i + need >= n) return false;
        for (size_t k = 1; k <= need; ++k) {
            unsigned char cc = static_cast<unsigned char>(s[i + k]);
            if ((cc & 0xC0) != 0x80) return false;
            cp = (cp << 6) | (cc & 0x3F);
        }
        // Reject overlong encodings and out-of-range / surrogate code points.
        if (need == 1 && cp < 0x80) return false;
        if (need == 2 && cp < 0x800) return false;
        if (need == 3 && cp < 0x10000) return false;
        if (cp > 0x10FFFF) return false;
        if (cp >= 0xD800 && cp <= 0xDFFF) return false;
        i += need + 1;
    }
    return true;
}

int main() {
    std::printf("%d\n", is_valid_utf8("hello"));        // 1
    std::printf("%d\n", is_valid_utf8("\xE2\x82\xAC")); // 1 (euro sign)
    std::printf("%d\n", is_valid_utf8("\xC0\xAF"));    // 0 overlong
    std::printf("%d\n", is_valid_utf8("\xE2\x82"));    // 0 truncated
    std::printf("%d\n", is_valid_utf8("\xED\xA0\x80")); // 0 surrogate
    return 0;
}
```

It walks byte by byte, decoding the lead byte to learn the sequence length, then validates every continuation byte and rejects overlong forms, surrogates and anything above U+10FFFF. Truncated tails return false via the bounds check.

