    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(k);
    pairs
}

fn main() {
    let text = "the quick brown fox, the lazy dog! The FOX.";
    let top = top_k_words(text, 3);
    assert_eq!(top[0], ("the".to_string(), 3));
    assert_eq!(top[1], ("fox".to_string(), 2));
    assert_eq!(top[2], ("brown".to_string(), 1));

    assert!(top_k_words("", 5).is_empty());
    assert!(top_k_words("   !!!   ", 5).is_empty());
    assert_eq!(top_k_words("a a a", 10).len(), 1);
    println!("{:?}", top);
}
```

