```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <string>\n", argv[0]);
        return 1;
    }

    const char *input = argv[1];
    size_t n = strlen(input);
    char *buf = malloc(n + 1);
    if (buf == NULL) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    memcpy(buf, input, n + 1);

    /* Reverse all bytes, not just until the first NUL, so UTF-8 works too. */
    for (size_t i = 0; i < n / 2; i++) {
        char tmp = buf[i];
        buf[i] = buf[n - 1 - i];
        buf[n - 1 - i] = tmp;
    }

    printf("%s\n", buf);
    free(buf);
    return 0;
}
