```python
from typing import Iterator


class Parser:
    def __init__(self, text: str) -> None:
        self.tokens: Iterator[str] = iter(_tokenize(text))
        self.current: str | None = None
        self._advance()

    def _advance(self) -> None:
        self.current = next(self.tokens, None)

    def parse(self) -> float:
        value = self._expr()
        if self.current is not None:
            raise ValueError(f"unexpected token: {self.current!r}")
        return value

    def _expr(self) -> float:
        value = self._term()
        while self.current in ("+", "-"):
            op = self.current
            self._advance()
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def _term(self) -> float:
        value = self._factor()
        while self.current in ("*", "/"):
            op = self.current
            self._advance()
            rhs = self._factor()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value /= rhs
        return value

    def _factor(self) -> float:
        tok = self.current
        if tok is None:
            raise ValueError("unexpected end of input")
        if tok == "-":
            self._advance()
            return -self._factor()
        if tok == "(":
            self._advance()
            value = self._expr()
            if self.current != ")":
                raise ValueError("missing closing parenthesis")
            self._advance()
            return value
        self._advance()
        return float(tok)


def _tokenize(text: str) -> Iterator[str]:
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
        elif c in "+-*/":
            yield c
            i += 1
        elif c in "()":
            yield c
            i += 1
        elif c.isdigit() or c == ".":
            j = i
            while j < n and (text[j].isdigit() or text[j] == "."):
                j += 1
            yield text[i:j]
            i = j
        else:
            raise ValueError(f"bad character: {c!r}")


def evaluate(expr: str) -> float:
    return Parser(expr).parse()


if __name__ == "__main__":
    assert evaluate("2+3*4") == 14
    assert evaluate("(2+3)*4") == 20
    assert evaluate("-3 + 10 / 2") == 2
    assert evaluate("2 * (3 + (4 - 1))") == 12
    assert evaluate("0.5*-4") == -2
    for bad in ["2+", "(1+2", "1/0", "2$"]:
        try:
            evaluate(bad)
        except (ValueError, ZeroDivisionError):
            pass
        else:
            raise AssertionError(f"expected failure for {bad!r}")
    print("ok")
```

One recursive-descent function per precedence level (`_expr` → `_term` → `_factor`) gives correct `*` before `+` and handles unary minus and nested parens. Malformed input raises `ValueError`; division by zero raises `ZeroDivisionError`.

