def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_iv = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    merged = [list(sorted_iv[0])]
    for start, end in sorted_iv[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
