```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(T value) {
        std::unique_lock<std::mutex> lock(m_);
        not_full_.wait(lock, [this] { return closed_ || q_.size() < cap_; });
        if (closed_) throw std::runtime_error("queue is closed");
        q_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(m_);
        not_empty_.wait(lock, [this] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;  // closed and drained
        T value = std::move(q_.front());
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(m_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<T> q_;
    std::mutex m_;
    std::condition_variable not_empty_, not_full_;
    bool closed_ = false;
};
```
Both waits use a predicate to survive spurious wakeups. `close()` wakes every waiter; `pop()` then returns `std::nullopt` once the queue drains, so consumers learn to stop. Destruction of the queue while waiters are active is still the caller's responsibility.

