```c
#include <stdbool.h>
#include <stdio.h>

#define RB_CAP 8

typedef struct {
    int data[RB_CAP];
    size_t head;   /* next read */
    size_t tail;   /* next write */
    size_t count;
} RingBuf;

void rb_init(RingBuf *rb) {
    rb->head = rb->tail = rb->count = 0;
}

bool rb_push(RingBuf *rb, int value) {
    if (rb->count == RB_CAP) {
        return false;  /* full */
    }
    rb->data[rb->tail] = value;
    rb->tail = (rb->tail + 1) % RB_CAP;
    rb->count++;
    return true;
}

bool rb_pop(RingBuf *rb, int *out) {
    if (rb->count == 0) {
        return false;  /* empty */
    }
    *out = rb->data[rb->head];
    rb->head = (rb->head + 1) % RB_CAP;
    rb->count--;
    return true;
}

int main(void) {
    RingBuf rb;
    rb_init(&rb);

    int v;
    if (!rb_pop(&rb, &v)) {
        printf("pop on empty: rejected\n");
    }

    for (int i = 0; i < RB_CAP + 2; i++) {
        if (!rb_push(&rb, i)) {
            printf("push %d: full, rejected\n", i);
        }
    }

    while (rb_pop(&rb, &v)) {
        printf("%d ", v);
    }
    printf("\n");
    return 0;
}
```
Separate `head`, `tail` and `count` mean full and empty are distinguishable without wasting a slot. Push and pop both return `bool` so the caller can react to saturation; the `% RB_CAP` arithmetic wraps indices without branching. Expected output lists 0 through 7 after two pushes are rejected.

