#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static void reverse_range(char *s, int start, int end) {
    while (start < end) {
        char tmp = s[start];
        s[start++] = s[end];
        s[end--] = tmp;
    }
}

/* Reverses word order in s (in place). Returns the new logical length. */
static int reverse_words(char *s) {
    int n = (int)strlen(s);

    /* 1. Collapse runs of spaces into a single space, then trim ends. */
    int w = 0;
    int i = 0;
    while (i < n && s[i] == ' ') i++;
    while (i < n) {
        if (s[i] == ' ') {
            if (w > 0 && s[w - 1] != ' ') s[w++] = ' ';
        } else {
            s[w++] = s[i];
        }
        i++;
    }
    if (w > 0 && s[w - 1] == ' ') w--;
    s[w] = '\0';
    n = w;

    /* 2. Reverse whole string, then reverse each word. */
    reverse_range(s, 0, n - 1);

    int start = 0;
    for (i = 0; i <= n; i++) {
        if (i == n || s[i] == ' ') {
            reverse_range(s, start, i - 1);
            start = i + 1;
        }
    }
    return n;
}

int main(void) {
    char buf[512];
    if (fgets(buf, sizeof buf, stdin) == NULL) {
        return 0;
    }
    buf[strcspn(buf, "\n")] = '\0';
    reverse_words(buf);
    puts(buf);
    return 0;
}
