#include <array>
#include <cstddef>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : size_(0), head_(0) {
        cap_ = capacity == 0 ? 1 : capacity;
        data_.fill(0);
    }

    bool push(int value) {
        if (size_ == cap_) return false;
        data_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == cap_; }

private:
    static constexpr std::size_t MAX_CAP = 1024;
    std::array<int, MAX_CAP> data_{};
    std::size_t cap_ = 0;
    std::size_t size_ = 0;
    std::size_t head_ = 0;
};
