#include <cstddef>
#include <iostream>
#include <string>

// Longest run of equal consecutive characters in s.
// Returns 0 for an empty string. O(n) time, O(1) space.
std::size_t longest_run(const std::string& s) {
    if (s.empty()) return 0;

    std::size_t best = 1;
    std::size_t current = 1;
    for (std::size_t i = 1; i < s.size(); ++i) {
        if (s[i] == s[i - 1]) {
            ++current;
            if (current > best) best = current;
        } else {
            current = 1;
        }
    }
    return best;
}

int main() {
    if (longest_run("") != 0) return 1;
    if (longest_run("a") != 1) return 1;
    if (longest_run("aabbbcc") != 3) return 1;
    if (longest_run("abcd") != 1) return 1;
    if (longest_run("aaa") != 3) return 1;
    // Multi-byte UTF-8 bytes are compared byte-wise, which is fine here.
    if (longest_run("\xC3\xA9\xC3\xA9") != 2) return 1;
    std::cout << "all checks passed\n";
    return 0;
