from typing import List, Optional


def binary_search(data: List[int], target: int) -> Optional[int]:
    """Return an index of `target` in ascending `data`, or None.

    Raises ValueError if `data` is not sorted ascending, since binary
    search on unsorted data silently returns wrong answers.
    """
    for i in range(1, len(data)):
        if data[i] < data[i - 1]:
            raise ValueError(f"input not sorted at index {i}: {data[i-1]} > {data[i]}")

    lo, hi = 0, len(data) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if data[mid] == target:
            return mid
        if data[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return None


if __name__ == "__main__":
    assert binary_search([], 5) is None
    assert binary_search([1, 3, 5, 7], 5) == 2
    assert binary_search([1, 3, 5, 7], 4) is None
    assert binary_search([2, 2, 2], 2) is not None
    try:
        binary_search([3, 1, 2], 2)
    except ValueError as exc:
        assert "not sorted" in str(exc)
    else:
        raise AssertionError("expected ValueError")
    print("all checks passed")
