/* Reverse the null-terminated string s in place. Safe for NULL and "". */
void reverse_in_place(char *s) {
    if (s == NULL) return;

    size_t len = strlen(s);
    if (len < 2) return;

    size_t i = 0;
    size_t j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
        --j;
    }
}

int main(void) {
    char a[] = "hello world";
    reverse_in_place(a);
    if (strcmp(a, "dlrow olleh") != 0) return 1;

    char empty[] = "";
    reverse_in_place(empty);
    if (strcmp(empty, "") != 0) return 1;

    char one[] = "x";
    reverse_in_place(one);
    if (strcmp(one, "x") != 0) return 1;

    reverse_in_place(NULL); /* must not crash */
    printf("all checks passed\n");
