/// nth Fibonacci number (F(0) = 0, F(1) = 1) using an iterative
/// u128 accumulator. Returns None if the result would overflow u128.
fn fib(n: u32) -> Option<u128> {
    let mut a: u128 = 0;
    let mut b: u128 = 1;
    for _ in 0..n {
        let next = a.checked_add(b)?;
        a = b;
        b = next;
    }
    Some(a)
}

