#include <functional>
#include <iostream>
#include <queue>
#include <vector>

// Running median with a max-heap for the lower half and a min-heap
// for the upper half. Invariant: lower.size() >= upper.size().
class RunningMedian {
public:
    void add(int value) {
        if (lower_.empty() || value <= lower_.top()) {
            lower_.push(value);
        } else {
            upper_.push(value);
        }
        rebalance();
    }

    double median() const {
        if (lower_.size() == upper_.size()) {
            return (static_cast<double>(lower_.top()) + upper_.top()) / 2.0;
        }
        return static_cast<double>(lower_.top());
    }

private:
    void rebalance() {
        if (lower_.size() > upper_.size() + 1) {
            upper_.push(lower_.top());
            lower_.pop();
        } else if (upper_.size() > lower_.size()) {
            lower_.push(upper_.top());
            upper_.pop();
        }
    }

    std::priority_queue<int> lower_;                              // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> upper_; // min-heap
};

int main() {
    RunningMedian rm;
    int value;
    while (std::cin >> value) {
        rm.add(value);
        std::cout << rm.median() << '\n';
    }
    return 0;
}
