```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) return head;
    n->value = value;
    n->next = head;
    return n;
}

void print_list(const Node *head) {
    for (const Node *p = head; p != NULL; p = p->next)
        printf("%d ", p->value);
    printf("\n");
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++)
        head = push(head, i);
    print_list(head);       /* 5 4 3 2 1 */
    head = reverse(head);
    print_list(head);       /* 1 2 3 4 5 */

    Node *empty = NULL;
    empty = reverse(empty);
    printf("%s\n", empty == NULL ? "empty ok" : "empty bad");

    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
```
The loop rewires each node's `next` to the previous one, so a `NULL` head returns `NULL` unchanged.

