```cpp
#include <array>
#include <cstddef>
#include <iostream>

template <std::size_t N>
class RingBuffer {
public:
    // Returns false if an element was overwritten.
    bool push(int value) {
        bool overwrote = full_;
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (full_ || size_ == 0) {
            tail_ = head_;  // advance tail when we wrapped past it
        }
        if (!full_) {
            ++size_;
        }
        full_ = (size_ == N);
        return !overwrote;
    }

    bool pop(int& out) {
        if (size_ == 0) {
            return false;
        }
        out = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --size_;
        full_ = false;
        return true;
    }

    std::size_t size() const { return size_; }
    bool isEmpty() const { return size_ == 0; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
    bool full_ = false;
};

int main() {
    RingBuffer<3> rb;
    if (!rb.isEmpty()) return 1;
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4);  // overwrites 1
    int v = 0;
    rb.pop(v); std::cout << v << "\n";  // 2
    rb.pop(v); std::cout << v << "\n";  // 3
    rb.pop(v); std::cout << v << "\n";  // 4
    if (!rb.isEmpty()) return 1;
    return 0;
}
