```rust
fn longest_common_prefix<'a>(words: &[&'a str]) -> &'a str {
    if words.is_empty() {
        return "";
    }
    let first = words[0];
    let mut end = first.len();
    for w in &words[1..] {
        end = end.min(w.len());
        let bytes_first = first.as_bytes();
        let bytes_w = w.as_bytes();
        let mut i = 0;
        while i < end && bytes_first[i] == bytes_w[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    // `end` may split a UTF-8 char boundary; clamp down to a safe boundary.
    let mut safe = end;
    while safe > 0 && !first.is_char_boundary(safe) {
        safe -= 1;
    }
    &first[..safe]
}

fn main() {
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&["dog", "cat"]), "");
    assert_eq!(longest_common_prefix(&["café", "café"]), "café");
    println!("ok");
}
