Iterative merge keeps the call stack flat and is safe for very long lists.

```cpp
#include <iostream>

struct Node {
    int value;
    Node* next;
    Node(int v) : value(v), next(nullptr) {}
};

Node* mergeSorted(Node* a, Node* b) {
    Node dummy(0);
    Node* tail = &dummy;
    while (a != nullptr && b != nullptr) {
        if (a->value <= b->value) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = (a != nullptr) ? a : b;
    return dummy.next;
}

static Node* build(const int* vals, int n) {
    Node dummy(0);
    Node* tail = &dummy;
    for (int i = 0; i < n; ++i) {
        tail->next = new Node(vals[i]);
        tail = tail->next;
    }
    return dummy.next;
}

static void print(const Node* head) {
    for (const Node* p = head; p != nullptr; p = p->next) {
        std::cout << p->value;
        if (p->next != nullptr) std::cout << " -> ";
    }
    std::cout << '\n';
}

static void freeList(Node* head) {
    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    const int a[] = {1, 4, 7, 10};
    const int b[] = {2, 3, 8, 8, 12};
    Node* listA = build(a, 4);
    Node* listB = build(b, 5);

    Node* merged = mergeSorted(listA, listB);
    print(merged);

    freeList(merged);
    return 0;
}
```

Output on the demo data: `1 -> 2 -> 3 -> 4 -> 7 -> 8 -> 8 -> 10 -> 12`. The dummy node lets us avoid special-casing the head, and the tail splice at the end handles whichever list still has nodes. Equal values from `a` are placed before equal values from `b` because of `<=`, which keeps the merge stable.

Using `char::is_alphabetic` handles unicode letters correctly, and a stable sort with an alphabetical tie-break keeps output deterministic.

```rust
use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    let mut current = String::new();

    let mut flush = |current: &mut String, counts: &mut HashMap<String, usize>| {
        if !current.is_empty() {
            let word = current.to_lowercase();
            *counts.entry(word).or_insert(0) += 1;
            current.clear();
        }
    };

    for ch in text.chars() {
        if ch.is_alphabetic() {
            current.push(ch);
        } else {
            flush(&mut current, &mut counts);
        }
    }
    flush(&mut current, &mut counts);

    let mut items: Vec<(String, usize)> = counts.into_iter().collect();
    items.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    items.truncate(n);
    items
}

fn main() {
    let text = "the quick brown fox jumps over the lazy dog. The fox!";
    for (word, count) in top_words(text, 3) {
        println!("{word}: {count}");
    }
    println!("---");
    println!("empty -> {:?}", top_words("", 5));
    println!("word count -> {:?}", top_words("Naive nave cafe caf\u{e9}", 2));
}
```

For the main text the top three are `the: 3`, `fox: 2`, `brown: 1` (alphabetical among the count-1 words). Empty input yields an empty vector rather than an error. `is_alphabetic` treats accented letters like `é` as word characters, so `café` stays one word.

No `atoi` here — it cannot report errors. This version uses `strtol` and checks every failure mode.

```c
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

/* Returns 1 on success and stores the value in *out; 0 on failure. */
int parse_int(const char *s, long *out) {
    if (s == NULL || out == NULL) return 0;

    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;

    if (*s == '\0') return 0;

    errno = 0;
    char *end = NULL;
    long value = strtol(s, &end, 10);

    if (end == s) return 0;              /* no digits at all            */
    if (errno == ERANGE) return 0;       /* overflow or underflow       */

    while (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r') end++;
    if (*end != '\0') return 0;          /* trailing garbage            */

    *out = value;
    return 1;
}

int main(void) {
    const char *tests[] = {
        "42", "   -7  ", "0", "", "  ", "12abc", "99999999999999999999",
        "2147483648", "-2147483648", "+5", NULL
    };
    for (int i = 0; tests[i] != NULL; i++) {
        long v = 0;
        int ok = parse_int(tests[i], &v);
        if (ok) printf("%-24s -> ok: %ld\n", tests[i], v);
        else    printf("%-24s -> rejected\n", tests[i]);
    }
    return 0;
}
```

`errno = 0` before the call is required: `strtol` only sets `ERANGE` on overflow, it never clears a stale value. The trailing check rejects strings like `12abc` that `strtol` would otherwise accept while silently stopping at `a`. On a 64-bit `long`, `2147483648` parses fine; use `strtoll` if you must survive 32-bit `long`.

`checked_add` turns overflow into `None` instead of a panic or a wrap, and the memo table is a simple `Vec` because indices are dense.

```rust
pub fn fib(n: u64) -> Option<u64> {
    if n > usize::MAX as u64 {
        return None;
    }
    let mut memo: Vec<u64> = Vec::with_capacity((n as usize).saturating_add(1));
    memo.push(0);
    memo.push(1);

    for i in 2..=n as usize {
        let next = memo[i - 1].checked_add(memo[i - 2])?;
        memo.push(next);
    }
    Some(memo[n as usize])
}

fn main() {
    for n in [0u64, 1, 2, 10, 50, 93, 94] {
        match fib(n) {
            Some(v) => println!("fib({n}) = {v}"),
            None => println!("fib({n}) overflows u64"),
        }
    }
}
```

Output: `fib(0)=0` through `fib(93)`, then `fib(94) overflows u64`. The largest Fibonacci number that fits in `u64` is `fib(93) = 12200160415121876738`; `fib(94)` needs the 64th bit and is correctly rejected by `?` on the `checked_add` result. Cap n if callers can pass huge values, since the table allocates O(n).

A templated dot product with a compile-time type guard, plus an overflow-safe note for integers.

```cpp
#include <iostream>
#include <type_traits>
#include <vector>

template <typename T>
T dot(const std::vector<T>& a, const std::vector<T>& b) {
    static_assert(std::is_arithmetic<T>::value,
                  "dot() requires an arithmetic type");
    if (a.size() != b.size()) {
        throw std::invalid_argument("dot: vectors differ in length");
    }
    T sum = T{};
    for (std::size_t i = 0; i < a.size(); ++i) {
        sum += a[i] * b[i];
    }
    return sum;
}

int main() {
    std::vector<double> x = {1.0, 2.0, 3.0};
    std::vector<double> y = {4.0, -5.0, 6.0};
    std::cout << dot(x, y) << '\n';  // 1*4 + 2*-5 + 3*6 = 12

    std::vector<int> p = {1, 2, 3, 4};
    std::vector<int> q = {1, 1, 1, 1};
    std::cout << dot(p, q) << '\n';  // 10

    // dot(x, std::vector<char>{...}) would not compile unless char counts
    // as arithmetic, which it does. A class type triggers the static_assert.
    return 0;
}
```

`std::is_arithmetic<T>` accepts integral and floating types, so passing a user struct fails at compile time with a readable message. Length mismatch throws rather than reading out of bounds. For large integer inputs the accumulator `T` can overflow silently — promote to `long long` or `__int128` at the call site if that matters. The double demo prints `12`, the int demo prints `10`.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int v) {
    Node *n = malloc(sizeof *n);
    if (n == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = v;
    n->next = head;
    return n;
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++) head = push(head, i);

    head = reverse(head);
    for (Node *cur = head; cur != NULL; cur = cur->next) {
        printf("%d ", cur->value);
    }
    putchar('\n');

    head = reverse(head);
    head = reverse(head);
    printf("empty: %s\n", head == NULL ? "null" : "non-null");

    while (head != NULL) {
        Node *tmp = head;
        head = head->next;
        free(tmp);
    }
    return 0;
}
```
Reversal is O(n) time, O(1) extra space. Reversing an empty list leaves `head` as `NULL`, and reversing twice restores the original order.

