#include <array>
#include <cstddef>
#include <cstdio>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : capacity_(capacity), head_(0), size_(0) {}

    void push(int value) {
        if (capacity_ == 0) return;
        buf_[(head_ + size_) % capacity_] = value;
        if (size_ < capacity_) {
            ++size_;
        } else {
            head_ = (head_ + 1) % capacity_;
        }
    }

    void print() const {
        for (std::size_t i = 0; i < size_; ++i) {
            std::printf("%d ", buf_[(head_ + i) % capacity_]);
        }
        std::printf("(size=%zu)\n", size_);
    }

private:
    static constexpr std::size_t kMax = 64;
    std::array<int, kMax> buf_{};
    std::size_t capacity_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    rb.push(1);
    rb.push(2);
    rb.push(3);
    rb.print();
    rb.push(4);
    rb.push(5);
    rb.print();

    RingBuffer empty(0);
    empty.push(9);
    empty.print();
    return 0;
}
```
Output is `1 2 3 (size=3)`, then `3 4 5 (size=3)` once the buffer wraps, and the zero-capacity buffer ignores pushes safely. The backing store is a fixed `std::array`, so there are no allocations.

```c
#include <ctype.h>
#include <stdio.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 2;
    }

    FILE *f = fopen(argv[1], "rb");
    if (f == NULL) {
        perror(argv[1]);
        return 1;
    }

    unsigned long lines = 0, words = 0, bytes = 0;
    int c, in_word = 0;

    while ((c = fgetc(f)) != EOF) {
        bytes++;
        if (c == '\n') lines++;
        if (isspace((unsigned char)c)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            words++;
        }
    }

    if (ferror(f)) {
        fprintf(stderr, "read error on %s\n", argv[1]);
        fclose(f);
        return 1;
    }

    fclose(f);
    printf("%lu %lu %lu %s\n", lines, words, bytes, argv[1]);
    return 0;
}
```
The file is opened in binary mode so byte counting is exact regardless of platform. `(unsigned char)c` before `isspace` avoids undefined behaviour on high-bit bytes, and a missing file exits non-zero with a clear `perror` message.

```rust
fn two_smallest<T: Ord + Copy>(items: &[T]) -> Option<(T, T)> {
    if items.len() < 2 {
        return None;
    }
    let (mut a, mut b) = (items[0], items[1]);
    if a > b {
        std::mem::swap(&mut a, &mut b);
    }
    for &x in &items[2..] {
        if x < a {
            b = a;
            a = x;
        } else if x < b {
            b = x;
        }
    }
    Some((a, b))
}

fn main() {
    assert_eq!(two_smallest(&[]), None);
    assert_eq!(two_smallest(&[7]), None);
    assert_eq!(two_smallest(&[3, 1, 4, 1, 5]), Some((1, 1)));
    assert_eq!(two_smallest(&[5, 4, 3, 2, 1]), Some((1, 2)));
    assert_eq!(two_smallest(&[2, 2]), Some((2, 2)));
    println!("ok");
}
```
One pass, O(n) time and O(1) extra space. Ties are kept as distinct elements (`[3, 1, 4, 1, 5]` yields `(1, 1)`), and slices shorter than two items return `None` rather than panicking.

```cpp
#include <cstdio>
#include <unordered_map>
#include <vector>

std::vector<int> two_sum(const std::vector<int> &nums, int target) {
    std::unordered_map<int, int> seen;
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        auto it = seen.find(target - nums[i]);
        if (it != seen.end()) {
            return {it->second, i};
        }
        seen.emplace(nums[i], i);
    }
    return {};
}

int main() {
    auto print = [](const std::vector<int> &v) {
        for (int x : v) std::printf("%d ", x);
        std::printf("\n");
    };

    print(two_sum({2, 7, 11, 15}, 9));    // 0 1
    print(two_sum({3, 3}, 6));            // 0 1
    print(two_sum({-1, -2, -3}, -5));     // 1 2
    print(two_sum({1}, 2));               // empty
    print(two_sum({}, 0));                // empty
    return 0;
}
```
Single pass with a hash map, O(n) time and O(n) space. Inserting *after* the lookup lets the same value appear twice (`{3, 3}`) without reusing one index. Empty or single-element input returns an empty vector instead of crashing.

