```cpp
#include <cerrno>
#include <cstdio>
#include <stdexcept>
#include <string>
#include <unistd.h>

class FileHandle {
public:
    explicit FileHandle(const std::string& path) : fd_(::open(path.c_str(), O_RDONLY)) {
        if (fd_ < 0) throw std::runtime_error("open failed: " + path);
    }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fd_(other.fd_) { other.fd_ = -1; }

    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            reset();
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    ~FileHandle() { reset(); }

    int get() const { return fd_; }

private:
    void reset() noexcept {
        if (fd_ >= 0) { ::close(fd_); fd_ = -1; }
    }
    int fd_;
};
```

Destructor does the cleanup through `reset()`, which is idempotent, so a moved-from object holding `-1` does nothing. Copying is deleted; moves transfer ownership and null out the source. The constructor throws instead of storing a bad descriptor, so `get()` is only ever called on a valid fd.

```rust
use std::collections::{HashMap, VecDeque};
use std::hash::Hash;

struct LruCache<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: Eq + Hash + Clone, V> LruCache<K, V> {
    fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    fn get(&mut self, key: &K) -> Option<&V> {
        if !self.map.contains_key(key) {
            return None;
        }
        self.touch(key);
        self.map.get(key)
    }

    fn put(&mut self, key: K, value: V) {
        if self.map.insert(key.clone(), value).is_some() {
            self.touch(&key);
            return;
        }
        self.order.push_back(key);
        if self.map.len() > self.cap {
            if let Some(evicted) = self.order.pop_front() {
                self.map.remove(&evicted);
            }
        }
    }

    fn touch(&mut self, key: &K) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            let k = self.order.remove(pos).unwrap();
            self.order.push_back(k);
        }
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put("a", 1);
    c.put("b", 2);
    assert_eq!(c.get(&"a"), Some(&1));
    c.put("c", 3);        // evicts "b"
    assert_eq!(c.get(&"b"), None);
    assert_eq!(c.get(&"a"), Some(&1));
    assert_eq!(c.get(&"c"), Some(&3));
    println!("all tests passed");
}
```

`VecDeque` holds keys in recency order (back = most recent). `get` moves the key to the back; `put` on an existing key refreshes recency instead of growing the map, and only evicts when the size exceeds capacity. Linear `touch` is fine for small capacities — swap in a `HashMap<K, usize>` index for O(1) if needed.

