```cpp
#include <cstddef>
#include <cstdio>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), count_(0), cap_(capacity) {}

    bool push(int value) {
        if (count_ == cap_) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % cap_;
        ++count_;
        return true;
    }

    bool pop(int& out) {
        if (count_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }

private:
    std::vector<int> buf_;
    std::size_t head_, tail_, count_, cap_;
};

int main() {
    RingBuffer rb(3);
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;  // full: must reject
    int v = 0;
    if (!rb.pop(v) || v != 1) return 1;
    if (!rb.push(4)) return 1; // room again
    std::printf("size=%zu\n", rb.size());
    return 0;
}
```
Capacity 0 is rejected by construction intent here — pass a positive size. Push returns false when full rather than silently overwriting.

