std::optional<std::uint64_t> fib(std::uint64_t n) {
    std::uint64_t a = 0, b = 1;
    for (std::uint64_t i = 0; i < n; ++i) {
        if (b > std::numeric_limits<std::uint64_t>::max() - a) {
            return std::nullopt;  // would overflow
        }
        std::uint64_t next = a + b;
        a = b;
        b = next;
    }
    return a;
}

