    std::uint64_t values[] = {0, 1, 10, 90};
    for (std::uint64_t n : values) {
        if (auto r = fib(n)) {
            std::cout << "fib(" << n << ") = " << *r << '\n';
        } else {
            std::cout << "fib(" << n << ") = overflow\n";
        }
    }
    return 0;
}
