// Binary-search for the integer square root.
// Returns r such that r*r <= n < (r+1)*(r+1), for n >= 0.
static std::uint64_t isqrt(std::uint64_t n) {
    std::uint64_t lo = 0, hi = 1;
    while (hi <= n / hi && hi < (std::uint64_t{1} << 32)) {
        hi <<= 1;
    }
    while (lo + 1 < hi) {
        std::uint64_t mid = lo + (hi - lo) / 2;
        if (mid <= n / mid) {
            lo = mid;
        } else {
            hi = mid;
        }
