static void reverse(char *s) {
    if (s == NULL) {
        return;
    }
    size_t i = 0;
    size_t j = strlen(s);
    /* j is the index just past the last character. */
    while (i + 1 < j) {
        char t = s[i];
        s[i] = s[j - 1];
        s[j - 1] = t;
        i++;
        j--;
    }
}

int main(void) {
    char buf[256];
    if (fgets(buf, sizeof buf, stdin) == NULL) {
        return 0;
    }
    /* Drop a trailing newline if present. */
    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] == '\n') {
        buf[len - 1] = '\0';
    }
    reverse(buf);
    puts(buf);
    return 0;
}
