#include <stdio.h>
#include <string.h>

void reverse_string(char *s) {
    if (s == NULL) {
        return;
    }
    size_t left = 0;
    size_t right = strlen(s);
    while (left + 1 < right) {
        right--;
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
    }
}

int main(void) {
    char empty[] = "";
    reverse_string(empty);
    if (strcmp(empty, "") != 0) return 1;

    char word[] = "hello";
    reverse_string(word);
    if (strcmp(word, "olleh") != 0) return 1;

    char even[] = "abcd";
    reverse_string(even);
    if (strcmp(even, "dcba") != 0) return 1;

    reverse_string(NULL);
    printf("ok\n");
    return 0;
}
