#include <iostream>
#include <stack>
#include <string>
#include <utility>

struct Result {
    bool balanced;
    std::size_t index;  // position of the offending bracket, or npos
};

Result check_balanced(const std::string& s) {
    std::stack<std::pair<char, std::size_t>> open;
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            open.push({c, i});
        } else if (c == ')' || c == ']' || c == '}') {
            if (open.empty()) {
                return {false, i};
            }
            char want = c == ')' ? '(' : c == ']' ? '[' : '{';
            if (open.top().first != want) {
                return {false, i};
            }
            open.pop();
        }
    }
    if (!open.empty()) {
        return {false, open.top().second};
    }
    return {true, std::string::npos};
}

int main() {
    auto a = check_balanced("a(b[c]{d})e");
    std::cout << a.balanced << '\n';
    auto b = check_balanced("(]", );
    std::cout << b.balanced << ' ' << b.index << '\n';
    auto c = check_balanced("(abc");
    std::cout << c.balanced << ' ' << c.index << '\n';
    auto d = check_balanced(")abc");
    std::cout << d.balanced << ' ' << d.index << '\n';
}
```

The stack stores each opener with its index, so a mismatch or an unclosed bracket can point at the exact character. A closer with an empty stack or a mismatched top returns immediately with its own index. At the end, any leftover opener reports the index of the most recent opening bracket, which is the one left dangling.

