```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) {
            ++size_;
            return true;   // stored without dropping anything
        }
        return false;      // capacity reached; oldest element was overwritten
    }

    std::optional<double> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        std::size_t tail = (head_ + N - size_) % N;
        double value = data_[tail];
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    static constexpr std::size_t capacity() { return N; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    std::cout << rb.push(1.0) << rb.push(2.0) << rb.push(3.0) << '\n';
    std::cout << rb.push(4.0) << '\n';  // 0: overwrote 1.0
    std::cout << rb.pop().value() << '\n';  // 2.0
    std::cout << rb.pop().value() << '\n';  // 3.0
    std::cout << rb.pop().value() << '\n';  // 4.0
    std::cout << rb.pop().has_value() << '\n';  // 0
}
```

`head_` is the next write slot and `size_` counts live elements, so the tail index is derived without storing it. `push` returns `false` when the buffer was already full, telling the caller an old value was dropped. `pop` returns `std::optional` so an empty buffer is handled explicitly rather than through an out-parameter.

