#include <ctype.h>
#include <stdio.h>
#include <string.h>

static void reverse(char *s, size_t len) {
    for (size_t i = 0; i < len / 2; i++) {
        char t = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = t;
    }
}

/* Reverses word order in a mutable buffer. */
void reverse_words(char *s) {
    size_t n = strlen(s);
    reverse(s, n);

    size_t w = 0, r = 0; /* w = write index, r = read index */
    while (r < n) {
        if (s[r] == ' ') {
            r++;
            continue;
        }
        if (w > 0) {
            s[w++] = ' ';
        }
        while (r < n && s[r] != ' ') {
            s[w++] = s[r++];
        }
    }
    s[w] = '\0';
}

int main(void) {
    char buf[256];
    if (fgets(buf, sizeof buf, stdin) == NULL) {
