```cpp
#include <array>
#include <cstddef>
#include <stdexcept>

template <std::size_t N>
class RingBuffer {
public:
    void push(double v) {
        if (full()) {
            head_ = (head_ + 1) % N;  // overwrite oldest
        } else {
            ++size_;
        }
        data_[(head_ + size_ - 1) % N] = v;
    }

    double pop() {
        if (empty()) {
            throw std::underflow_error("ring buffer is empty");
        }
        double v = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1.0);
    rb.push(2.0);
    rb.push(3.0);
    rb.push(4.0);  // evicts 1.0
    if (rb.pop() != 2.0 || rb.pop() != 3.0 || rb.pop() != 4.0) {
        return 1;
    }
    return rb.empty() ? 0 : 1;
}
```

Storage is a compile-time `std::array`, so capacity is fixed and there is no heap use. Indexing is modulo `N`, `full()` overwrites the oldest element by advancing `head_`, and popping from an empty buffer throws instead of returning garbage.

