#include <iostream>
#include <vector>
#include <cassert>

static void merge_into(std::vector<int>& a, std::vector<int>& b) {
    int i = static_cast<int>(a.size()) - 1;
    int j = static_cast<int>(b.size()) - 1;
    int k = static_cast<int>(a.size() + b.size()) - 1;
    a.resize(a.size() + b.size());

    while (i >= 0 && j >= 0) {
        a[k--] = (a[i] > b[j]) ? a[i--] : b[j--];
    }
    while (j >= 0) {
        a[k--] = b[j--];
    }
}

