```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1, 1], &[1, 1]), vec![1, 1, 1, 1, 1]);
    assert_eq!(merge_sorted(&[-5, 0], &[-1]), vec![-5, -1, 0]);
    println!("all merge tests passed");
}
```

The merge is a single linear pass, so it is O(n + m) rather than O((n+m) log(n+m)). The trailing `extend_from_slice` calls drain whichever side still has elements. The `<=` comparison keeps the merge stable when equal values appear in both inputs.

