            bad.append((lineno, row, "expected 2 columns"))
            continue
        name, email = (cell.strip() for cell in row)
        if not name:
            bad.append((lineno, row, "empty name"))
        elif not EMAIL_RE.match(email):
            bad.append((lineno, row, "invalid email"))
        else:
            good.append((name, email))
    return {"valid": good, "invalid": bad}


