```rust
fn parse_duration(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err("empty duration".into());
    }
    let mut total: u64 = 0;
    let mut num = String::new();
    let mut saw_any = false;

    for ch in s.chars() {
        if ch.is_ascii_digit() {
            num.push(ch);
            continue;
        }
        if num.is_empty() {
            return Err(format!("missing number before '{}'", ch));
        }
        let value: u64 = num.parse().map_err(|_| "number too large".to_string())?;
        num.clear();
        let mult = match ch {
            'h' => 3600,
            'm' => 60,
            's' => 1,
            other => return Err(format!("unknown unit '{}'", other)),
        };
        total = total
            .checked_add(value.checked_mul(mult).ok_or("overflow")?)
            .ok_or("overflow")?;
        saw_any = true;
    }
    if !num.is_empty() {
        return Err("trailing number without unit".into());
    }
    if !saw_any {
        return Err("no valid components".into());
    }
    Ok(total)
}

fn main() {
    assert_eq!(parse_duration("1h30m15s"), Ok(5415));
    assert_eq!(parse_duration("45s"), Ok(45));
    assert!(parse_duration("10x").is_err());
    assert!(parse_duration("1h30").is_err());
    assert!(parse_duration("").is_err());
    println!("duration parse tests passed");
}
```

Each unit segment returns an error on an unknown letter or a missing number, and `checked_add`/`checked_mul` catch overflow rather than wrapping. A trailing bare number such as `"1h30"` is rejected because a component needs an explicit unit.

