// Prints the exact median of the input integers.
// For an even count the median is the average of the two middle values,
// printed as a reduced fraction (or an integer when the divisor is 1).
int main() {
    std::vector<long long> v;
    long long x;
    while (std::cin >> x) {
        v.push_back(x);
    }
    if (v.empty()) {
        std::cerr << "no input\n";
        return 1;
    }
    std::sort(v.begin(), v.end());
    const std::size_t n = v.size();
    const long long mid = static_cast<long long>(n / 2);
    if (n % 2 == 1) {
        std::cout << v[mid] << "\n";
    } else {
        long long num = v[mid - 1] + v[mid];   // sum of two middles
        long long den = 2;
        long long g = std::gcd(num < 0 ? -num : num, den);
        num /= g;
        den /= g;
        if (den == 1) std::cout << num << "\n";
        else std::cout << num << "/" << den << "\n";
    }
    return 0;
}
