Two-pointer merge into a pre-sized buffer, then appends whichever tail remains. O(n+m) time and O(n+m) space; no sort call with unstable ordering concerns.

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int main(int argc, char **argv) {
    FILE *fp = stdin;
    if (argc > 1) {
        fp = fopen(argv[1], "r");
        if (!fp) die("fopen");
    }

    char **lines = NULL;
    size_t cap = 0, n = 0;
    char *buf = NULL;
    size_t buflen = 0;
    ssize_t got;

    while ((got = getline(&buf, &buflen, fp)) != -1) {
        if (n == cap) {
            cap = cap ? cap * 2 : 64;
            char **tmp = realloc(lines, cap * sizeof *tmp);
            if (!tmp) die("realloc");
            lines = tmp;
        }
        char *copy = malloc((size_t)got + 1);
        if (!copy) die("malloc");
        memcpy(copy, buf, (size_t)got + 1);
        lines[n++] = copy;
    }
    if (ferror(fp)) die("getline");
    free(buf);
    if (fp != stdin) fclose(fp);

    for (size_t i = n; i-- > 0;) {
        fputs(lines[i], stdout);
        free(lines[i]);
    }
    free(lines);
    return 0;
}
```

Reads from a file given as `argv[1]`, or stdin when no argument. `getline` grows the buffer as needed, so there is no fixed line-length limit. Each line is copied and stored, then printed in reverse order. Empty input prints nothing and exits 0.

