#include <cctype>
#include <iostream>
#include <map>
#include <sstream>
#include <string>

struct IniError {
    std::size_t line;
    std::string message;
};

// Parses INI text. Sections map to key/value maps; keys before any
// [section] header live under the empty-string section "".
std::map<std::string, std::map<std::string, std::string>> parse_ini(
    const std::string& text, std::vector<IniError>& errors) {
    std::map<std::string, std::map<std::string, std::string>> result;
    std::istringstream in(text);
    std::string raw;
    std::string section;
    std::size_t lineno = 0;

    while (std::getline(in, raw)) {
        ++lineno;
        std::string line = raw;
        auto start = line.find_first_not_of(" \t\r");
        if (start == std::string::npos) continue;          // blank line
        if (line[start] == ';' || line[start] == '#') continue;  // comment
        auto end = line.find_last_not_of(" \t\r");
        line = line.substr(start, end - start + 1);

        if (line.front() == '[') {
            if (line.back() != ']' || line.size() < 3) {
                errors.push_back({lineno, "malformed section header"});
                continue;
            }
            section = line.substr(1, line.size() - 2);
            if (section.empty()) {
                errors.push_back({lineno, "empty section name"});
            }
            continue;
        }

        auto eq = line.find('=');
        if (eq == std::string::npos) {
            errors.push_back({lineno, "missing '=' in key/value line"});
            continue;
        }
        std::string key = line.substr(0, eq);
        std::string val = line.substr(eq + 1);
        auto trim = [](std::string& s) {
            auto b = s.find_first_not_of(" \t");
            auto e = s.find_last_not_of(" \t");
            s = (b == std::string::npos) ? "" : s.substr(b, e - b + 1);
        };
        trim(key);
        trim(val);
        if (key.empty()) {
            errors.push_back({lineno, "empty key"});
            continue;
        }
        result[section][key] = val;
    }
    return result;
}

int main() {
    const std::string text =
        "name = example\n"
        "[server]\n"
        "host=localhost\n"
        "port = 8080\n"
        "badline\n";
    std::vector<IniError> errors;
    auto parsed = parse_ini(text, errors);
    for (const auto& [sec, kv] : parsed) {
        std::cout << "[" << sec << "]\n";
        for (const auto& [k, v] : kv) std::cout << "  " << k << " = " << v << "\n";
    }
    for (const auto& e : errors) {
        std::cout << "error line " << e.line << ": " << e.message << "\n";
    }
}
```

Trims whitespace, ignores blank lines and `;`/`#` comments, and records every malformed line with its line number instead of throwing. Keys outside a section land under an empty-string section.

