#include <iostream>
#include <string>
#include <cctype>

bool is_palindrome(const std::string& s) {
    std::size_t i = 0, j = s.size();
    while (i < j) {
        if (j == 0) break;
        --j;
        if (!std::isalnum(static_cast<unsigned char>(s[i]))) { ++i; ++j; continue; }
        if (!std::isalnum(static_cast<unsigned char>(s[j]))) { continue; }
        if (std::tolower(static_cast<unsigned char>(s[i])) !=
            std::tolower(static_cast<unsigned char>(s[j]))) {
            return false;
        }
        ++i;
    }
    return true;
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::cout << (is_palindrome(line) ? "yes" : "no") << '\n';
    }
    return 0;
}
```

