```rust
use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '\'')
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

#[cfg(test)]
mod tests {
    use super::top_words;

    #[test]
    fn counts_and_orders() {
        let out = top_words("The cat the CAT dog", 2);
        assert_eq!(out, vec![("cat".to_string(), 2), ("dog".to_string(), 1)]);
    }

    #[test]
    fn empty_input() {
        assert!(top_words("   ", 5).is_empty());
    }
}
```

`split_whitespace` avoids empty tokens, punctuation is stripped per word, and lowercase folding merges `The`/`the`/`CAT`/`cat`. The sort uses count descending, then alphabetical order as the tiebreaker, matching the requested ordering. The two tests cover the normal path and the empty-input edge case.

