#include <iostream>
#include <stack>
#include <string>

bool is_balanced(const std::string& s) {
    std::stack<char> open;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            open.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (open.empty()) return false;
            char top = open.top();
            open.pop();
            if ((c == ')' && top != '(') ||
                (c == ']' && top != '[') ||
                (c == '}' && top != '{')) {
                return false;
            }
        }
    }
    return open.empty();
}

int main() {
    const std::string cases[] = {"()[]{}", "([{}])", "(]", "(", ") ", ""};
    for (const auto& s : cases) {
        std::cout << (is_balanced(s) ? "balanced  " : "broken    ") << s << '\n';
    }
    return 0;
}
```

The stack tracks the most recent unmatched opener, so a closer must match the top of the stack, not just any earlier opener. An empty stack on a closer means extra closing brackets, and a non-empty stack at the end means unclosed openers. Both cases fail, as do empty strings by returning `true` (vacuously balanced).

