```python
from collections import OrderedDict
from typing import Any, Optional


class LRUCache:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict[Any, Any] = OrderedDict()

    def get(self, key: Any) -> Optional[Any]:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: Any, value: Any) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least-recently used

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1     # 'a' is now most-recently used
    cache.put("c", 3)              # evicts 'b'
    assert cache.get("b") is None
    assert cache.get("a") == 1
    assert cache.get("c") == 3
    assert len(cache) == 2
    print("all checks passed")
```

`OrderedDict` preserves insertion order; `move_to_end` marks a key as recently used on both `get` and overwrite, and `popitem(last=False)` evicts the oldest (least-recently used) entry. Operations are O(1) amortized. A capacity below 1 is rejected up front rather than silently behaving oddly.

```c
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;  // empty or single char: nothing to do
    size_t i = 0;
    size_t j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

int main(void) {
    char input[256];
    if (fgets(input, sizeof input, stdin) == NULL) {
        return 0;  // EOF or read error
    }
    input[strcspn(input, "\n")] = '\0';  // strip trailing newline
    reverse_in_place(input);
    printf("%s\n", input);
    return 0;
}
```

The swap loop runs from both ends toward the middle, so the null terminator never moves. `strcspn` removes the newline that `fgets` keeps, otherwise the reversed output would begin with a stray blank line. Inputs shorter than two characters return immediately, which covers the empty-string and single-character cases without any special-casing in `main`.

