class MinHeap:
    def __init__(self):
        self._data = []

    def push(self, value):
        self._data.append(value)
        i = len(self._data) - 1
        while i > 0:
            parent = (i - 1) // 2
            if self._data[parent] <= self._data[i]:
                break
            self._data[parent], self._data[i] = self._data[i], self._data[parent]
            i = parent

    def pop(self):
        if not self._data:
            raise IndexError("pop from empty heap")
        smallest = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            i = 0
            n = len(self._data)
            while True:
                left, right = 2 * i + 1, 2 * i + 2
                smallest_idx = i
                if left < n and self._data[left] < self._data[smallest_idx]:
                    smallest_idx = left
                if right < n and self._data[right] < self._data[smallest_idx]:
                    smallest_idx = right
                if smallest_idx == i:
                    break
                self._data[i], self._data[smallest_idx] = (
                    self._data[smallest_idx], self._data[i])
                i = smallest_idx
        return smallest


if __name__ == "__main__":
    h = MinHeap()
    for v in [5, 3, 8, 1, 9, 2]:
        h.push(v)
    out = [h.pop() for _ in range(6)]
    assert out == [1, 2, 3, 5, 8, 9], out
    print(out)
