#include <array>
#include <optional>
#include <iostream>

template <typename T, std::size_t N>
class CircularQueue {
public:
    bool push(const T& value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    CircularQueue<int, 2> q;
    std::cout << q.push(1) << q.push(2) << q.push(3) << '\n'; // 1 1 0
    std::cout << *q.pop() << ' ' << *q.pop() << '\n';         // 1 2
    std::cout << q.pop().has_value() << '\n';                 // 0
}
