    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main(void) {
    Node *head = NULL;
    for (int i = 3; i >= 1; --i) {
        Node *n = malloc(sizeof(Node));
        if (!n) return 1;
        n->value = i;
        n->next = head;
        head = n;
    }
    head = reverse(head);
    for (Node *cur = head; cur; cur = cur->next) {
        printf("%d ", cur->value);
    }
    printf("\n");
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
