static std::string lower(const std::string& s) {
    std::string out; out.reserve(s.size());
    for (unsigned char c : s) out.push_back(std::tolower(c));
    return out;
}

int main(int argc, char** argv) {
    if (argc != 2) { std::cerr << "usage: " << argv[0] << " <file>\n"; return 1; }
    std::ifstream in(argv[1]);
    if (!in) { std::cerr << "cannot open " << argv[1] << "\n"; return 1; }

    std::unordered_map<std::string, long> counts;
    std::string word;
    while (in >> word) {
        std::string w = lower(word);
        w.erase(std::remove_if(w.begin(), w.end(),
                               [](unsigned char c){ return !std::isalnum(c); }),
                w.end());
        if (!w.empty()) ++counts[w];
    }

    std::vector<std::pair<std::string, long>> v(counts.begin(), counts.end());
    std::sort(v.begin(), v.end(), [](auto& a, auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });

    long limit = std::min<long>(10, v.size());
    for (long i = 0; i < limit; ++i)
        std::cout << v[i].second << ' ' << v[i].first << '\n';
    return 0;
}
