/// Returns Some(true/false) for a valid digit string, None if it contains
/// non-digits or is empty.
pub fn luhn_check(s: &str) -> Option<bool> {
    if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    let mut sum = 0u32;
    let mut double = false;
    for b in s.bytes().rev() {
        let mut d = (b - b'0') as u32;
        if double {
            d *= 2;
            if d > 9 { d -= 9; }
        }
        sum += d;
        double = !double;
    }
    Some(sum % 10 == 0)
}

