def merge_intervals(intervals):
    """Merge [start, end] pairs. Touching endpoints merge; empty input -> []."""
    cleaned = []
    for iv in intervals:
        if len(iv) != 2:
            raise ValueError(f"interval must be a pair: {iv!r}")
        a, b = iv
        if a > b:
            a, b = b, a
        cleaned.append((a, b))

    cleaned.sort(key=lambda p: (p[0], p[1]))
    merged = []
    for a, b in cleaned:
        if merged and a <= merged[-1][1]:
            prev_a, prev_b = merged[-1]
            merged[-1] = (prev_a, max(prev_b, b))
        else:
            merged.append((a, b))
    return merged

if __name__ == "__main__":
    cases = [
        ([[1, 3], [2, 6], [8, 10], [15, 18]], [(1, 6), (8, 10), (15, 18)]),
        ([[5, 5], [4, 4], [5, 6]], [(4, 4), (5, 6)]),
        ([], []),
        ([[3, 1]], [(1, 3)]),
    ]
    for inp, want in cases:
        got = merge_intervals(inp)
        assert got == want, (inp, got, want)
        print(f"{inp} -> {got}")
```

