```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize, // next write position
    len: usize,  // number of live items
}

impl<T: Clone> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        let mut data = Vec::with_capacity(capacity);
        data.resize_with(capacity, || None);
        RingBuffer { data, head: 0, len: 0 }
    }

    pub fn push(&mut self, item: T) {
        let cap = self.data.len();
        self.data[self.head] = Some(item);
        self.head = (self.head + 1) % cap;
        if self.len < cap {
            self.len += 1;
        }
    }

    /// Oldest to newest.
    pub fn to_vec(&self) -> Vec<T> {
        let cap = self.data.len();
        let start = (self.head + cap - self.len) % cap;
        (0..self.len)
            .map(|i| self.data[(start + i) % cap].clone().unwrap())
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn overwrites_oldest() {
        let mut rb = RingBuffer::new(3);
        for x in 1..=5 { rb.push(x); }
        assert_eq!(rb.to_vec(), vec![3, 4, 5]);
    }

    #[test]
    fn partial_fill() {
        let mut rb = RingBuffer::new(4);
        rb.push(10); rb.push(20);
        assert_eq!(rb.to_vec(), vec![10, 20]);
    }
}
```

`head` is the next write slot, and `(head + cap - len) % cap` reconstructs the oldest index, so no separate read pointer is needed. To overwrite older entries the item type must be cloneable for `to_vec`; the buffer itself only requires storage.

```c
#include <stdio.h>
#include <string.h>

/* Reverse a UTF-8 string in place, keeping code points intact. */
static void reverse_utf8(char* s) {
    size_t n = strlen(s);
    size_t i = 0, j = n;
    while (i < j) {
        /* find length of the leading code point at i */
        unsigned char c = (unsigned char)s[i];
        size_t ci = 1;
        if ((c & 0x80) == 0x00) ci = 1;
        else if ((c & 0xE0) == 0xC0) ci = 2;
        else if ((c & 0xF0) == 0xE0) ci = 3;
        else if ((c & 0xF8) == 0xF0) ci = 4;

        /* find length of the trailing code point at j */
        size_t cj = 1;
        size_t k = j - 1;
        while (k > 0 && ((unsigned char)s[k] & 0xC0) == 0x80) { --k; ++cj; }

        if (i + ci <= j - cj) {
            char tmp[4];
            memcpy(tmp, s + i, ci);
            memmove(s + i, s + j - cj, cj);
            memcpy(s + j - cj, tmp, ci);
            i += ci;
            j -= cj;
        } else {
            break;
        }
    }
}

int main(void) {
    char buf[256];
    while (fgets(buf, sizeof buf, stdin)) {
        size_t len = strlen(buf);
        while (len && (buf[len - 1] == '\n' || buf[len - 1] == '\r')) buf[--len] = '\0';
        reverse_utf8(buf);
        puts(buf);
    }
    return 0;
}
```

Code-point boundaries are detected from leading and continuation bytes (0b10xxxxxx), so swapping multi-byte sequences never splits them. It reverses by exchanging whole code points from both ends.

```python
import functools
import random
import time

def retry(attempts=3, base_delay=0.1, cap=5.0, exceptions=(Exception,)):
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last = None
            for n in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if n == attempts - 1:
                        break
                    delay = min(cap, base_delay * (2 ** n))
                    delay *= random.uniform(0.5, 1.0)
                    time.sleep(delay)
            raise last
        return wrapper
    return decorator

if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base_delay=0.01)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError(f"attempt {calls['n']} failed")
        return "ok"

    assert flaky() == "ok"
    assert calls["n"] == 3
    print("succeeded after", calls["n"], "attempts")
```

Backoff is capped before jitter, so the real wait never exceeds `cap`. Only the configured `exceptions` are caught; the last exception is re-raised rather than swallowed, and the decorator preserves the wrapped function's name and docstring.

