#include <fcntl.h>
#include <unistd.h>

#include <iostream>
#include <string>
#include <utility>

class FileHandle {
public:
    explicit FileHandle(int fd) noexcept : fd_(fd) {}

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fd_(other.fd_) { other.fd_ = -1; }

    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            close_if_open();
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    ~FileHandle() { close_if_open(); }

    int get() const noexcept { return fd_; }

private:
    void close_if_open() noexcept {
        if (fd_ >= 0) {
            ::close(fd_);
            fd_ = -1;
        }
    }

    int fd_;
};

int main() {
    const char* path = "/tmp/xt_luna_raii_demo.txt";
    FileHandle out(::open(path, O_CREAT | O_WRONLY | O_TRUNC, 0644));
    if (out.get() < 0) { std::cerr << "open failed\n"; return 1; }
    const std::string msg = "hello from RAII\n";
    ssize_t n = ::write(out.get(), msg.data(), msg.size());
    if (n != static_cast<ssize_t>(msg.size())) { std::cerr << "write failed\n"; return 1; }
    std::cout << "wrote " << n << " bytes\n";
    return 0;
}
```

Copying is deleted so the fd can't be double-closed; moves null out the source (`fd_ = -1`) and the destructor closes only a live descriptor. Move-assignment closes the current fd before adopting the new one.

