#include <charconv>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

struct ParseError {
    std::size_t position;
    std::string token;
};

std::optional<std::vector<int>> parse_int_list(std::string_view input, ParseError& err) {
    std::vector<int> out;
    std::size_t pos = 0;

    while (pos <= input.size()) {
        std::size_t comma = input.find(',', pos);
        std::string_view token = input.substr(pos, comma == std::string_view::npos
                                                     ? std::string_view::npos
                                                     : comma - pos);

        // Trim surrounding spaces.
        while (!token.empty() && token.front() == ' ') token.remove_prefix(1);
        while (!token.empty() && token.back() == ' ') token.remove_suffix(1);

        if (!token.empty()) {
            int value = 0;
            auto [ptr, ec] = std::from_chars(token.data(), token.data() + token.size(), value);
            if (ec != std::errc{} || ptr != token.data() + token.size()) {
                err = ParseError{pos, std::string(token)};
                return std::nullopt;
            }
            out.push_back(value);
        } else if (pos < input.size()) {
            err = ParseError{pos, ""};
            return std::nullopt;
        }

        if (comma == std::string_view::npos) break;
        pos = comma + 1;
    }
    return out;
}
```

`std::from_chars` is used instead of `std::stoi` because it reports errors without throwing and never allocates. Empty tokens between commas are treated as errors, and `ptr` is checked to reject trailing garbage like `12x`.

```rust
/// Merge two ascending slices into one ascending Vec.
///
/// Pre-allocates exactly `a.len() + b.len()` capacity.
pub fn merge_sorted<T: Ord + Copy>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn merges_basic() {
        assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    }

    #[test]
    fn handles_empty() {
        assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
        assert_eq!(merge_sorted(&[1, 2], &[]), vec![1, 2]);
    }

    #[test]
    fn handles_duplicates() {
        assert_eq!(merge_sorted(&[1, 1, 2], &[1, 3]), vec![1, 1, 1, 2, 3]);
    }
}
```

Slices are copied since `T: Copy`; if you need to move non-`Copy` values, change the bound to `T: Ord` and take `Vec<T>` inputs, or return an iterator with `itertools::merge`. Using `<=` on the left keeps the merge stable.

