/* Reverse a NUL-terminated string in place. Safe on empty strings. */
void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;

    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    assert(strcmp(a, "olleh") == 0);

    char empty[] = "";
    reverse_in_place(empty);
    assert(strcmp(empty, "") == 0);

    char one[] = "x";
    reverse_in_place(one);
    assert(strcmp(one, "x") == 0);

    reverse_in_place(NULL); /* must not crash */

    puts("ok");
    return 0;
}
```

The two-index `i < j` condition swaps each pair exactly once and stops correctly at the middle for both odd and even lengths. `len < 2` short-circuits empty and one-character strings before the loop. Note this reverses bytes, not unicode codepoints.

```python
def ipv4_to_int(addr: str) -> int:
    """Convert a dotted-quad IPv4 string to a 32-bit integer.

    Raises ValueError on malformed input.
    """
    if not isinstance(addr, str):
        raise ValueError("address must be a string")

    parts = addr.split(".")
    if len(parts) != 4:
        raise ValueError(f"expected 4 octets, got {len(parts)}")

    octets = []
    for part in parts:
        # Reject empty, non-digit, leading-zero forms like '01', and negatives.
        if not part.isdigit() or (len(part) > 1 and part[0] == "0"):
            raise ValueError(f"invalid octet: {part!r}")
        value = int(part)
        if value > 255:
            raise ValueError(f"octet out of range: {value}")
        octets.append(value)

    result = 0
    for octet in octets:
        result = (result << 8) | octet
    return result


if __name__ == "__main__":
    assert ipv4_to_int("0.0.0.0") == 0
    assert ipv4_to_int("255.255.255.255") == 0xFFFFFFFF
    assert ipv4_to_int("192.168.0.1") == 0xC0A80001
    for bad in ("1.2.3", "1.2.3.4.5", "256.0.0.1", "01.2.3.4", "a.b.c.d", "1.2.3."):
        try:
            ipv4_to_int(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"should have rejected {bad!r}")
    print("ok")
```

`part.isdigit()` returns `False` for `'\u00b2'`-style superscripts in the BMP only when they're not ASCII digits, so combined with the leading-zero rejection this accepts exactly the canonical form. `.isdigit()` alone would accept some unicode digit characters, so the octet check pairs it with the range bound.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <optional>

#include <iostream>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(T value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    // Oldest element first; returns nullopt when empty.
    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        std::optional<T> out = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --size_;
        return out;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.empty());

    rb.push(1);
    rb.push(2);
    rb.push(3);
    assert(rb.full());

    // Overwrite: ring is now {2, 3, 4}.
    rb.push(4);
    assert(rb.pop() == 2);
    assert(rb.pop() == 3);
    assert(rb.pop() == 4);
    assert(rb.pop() == std::nullopt);

    std::cout << "ok\n";
}
```

When the buffer is full, `push` overwrites the slot at `head_`, which is the oldest because `tail_` lags behind. `pop` returns `std::nullopt` on an empty buffer rather than reading uninitialized memory.

```rust
const MOD: u64 = 1_000_000_007;

/// Return F(n) mod 1e9+7 using an O(n) iterative loop with u64 arithmetic.
/// u64 fits values < 2^63, and our intermediate products stay below 1e9+7, so no overflow.
pub fn fib_mod(n: u64) -> u64 {
    if n == 0 {
        return 0;
    }
    let (mut prev, mut curr) = (0u64, 1u64);
    for _ in 1..n {
        let next = (prev + curr) % MOD;
        prev = curr;
        curr = next;
    }
    curr
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn base_cases() {
        assert_eq!(fib_mod(0), 0);
        assert_eq!(fib_mod(1), 1);
        assert_eq!(fib_mod(10), 55);
    }

    #[test]
    fn known_mod_value() {
        // F(90) = 2880067194370816120, which exceeds u64::MAX only slightly; here we only check mod.
        assert_eq!(fib_mod(90), 2880067194370816120 % MOD);
    }
}
```

Only one addition happens per step, and since both operands are already reduced modulo `MOD` (< 2^30), their sum is well under `u64::MAX`. For very large `n`, switch to a 2×2 matrix power in `O(log n)` to avoid the `O(n)` loop.

```c
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

static uint32_t crc_table[256];
static int table_ready = 0;

static void build_table(void) {
    for (uint32_t i = 0; i < 256; ++i) {
        uint32_t crc = i;
        for (int j = 0; j < 8; ++j) {
            crc = (crc & 1u) ? (crc >> 1) ^ 0xEDB88320u : (crc >> 1);
        }
        crc_table[i] = crc;
    }
    table_ready = 1;
}

uint32_t crc32(const uint8_t *data, size_t len) {
    if (!table_ready) build_table();
    uint32_t crc = 0xFFFFFFFFu;
    for (size_t i = 0; i < len; ++i) {
        crc = crc_table[(crc ^ data[i]) & 0xFFu] ^ (crc >> 8);
    }
    return crc ^ 0xFFFFFFFFu;
}

int main(void) {
    const char *s = "123456789";
    uint32_t got = crc32((const uint8_t *)s, 9);
    printf("%08x\n", got);
    /* Standard CRC-32/ISO-HDLC check value for "123456789" is 0xCBF43926. */
    return got == 0xCBF43926u ? 0 : 1;
}
```

The table is built once and cached in a static flag, so repeated calls avoid recomputation. The initial and final XORs with `0xFFFFFFFF` are what turn this into the standard CRC-32/ISO-HDLC variant; the check value `0xCBF43926` verifies it against the canonical test vector.

