#include <stdio.h>
#include <string.h>

int longestCommonPrefix(const char **strs, int n, char *out, int outSize) {
    if (n <= 0) { out[0] = '\0'; return 0; }
    int len = (int)strlen(strs[0]);
    for (int i = 1; i < n; i++) {
        int j = 0;
        while (j < len && strs[i][j] && strs[i][j] == strs[0][j]) j++;
        len = j;
        if (len == 0) break;
    }
    if (len >= outSize) len = outSize - 1;
    memcpy(out, strs[0], len);
    out[len] = '\0';
    return len;
}

int main(void) {
    const char *a[] = {"flower", "flow", "flight"};
    const char *b[] = {"dog", "racecar", "car"};
    char buf[64];
    longestCommonPrefix(a, 3, buf, sizeof buf);
    printf("prefix: '%s'\n", buf);
    longestCommonPrefix(b, 3, buf, sizeof buf);
    printf("prefix: '%s'\n", buf);
    return 0;
}
