    fn v(items: &[&str]) -> Vec<String> {
        items.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn typical() {
        assert_eq!(longest_common_prefix(&v(&["flower", "flow", "flight"])), "fl");
    }

    #[test]
    fn no_common_prefix() {
        assert_eq!(longest_common_prefix(&v(&["dog", "racecar", "car"])), "");
    }

    #[test]
    fn empty_slice() {
        assert_eq!(longest_common_prefix(&[]), "");
    }

    #[test]
    fn unicode_boundary() {
        assert_eq!(longest_common_prefix(&v(&["café", "café au lait"])), "café");
    }
}
```
The prefix shrinks monotonically, so comparing against `first` repeatedly costs at most the first string's length per pass. Bytes are compared directly for speed, but the result is clamped back to a UTF-8 character boundary before slicing, which prevents a panic when the shared bytes stop mid-codepoint. Empty input and immediately-disjoint strings both return `""`.

```python
from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n: int) -> int:
    """Return the n-th Fibonacci number, F(0)=0, F(1)=1."""
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

def fib_fast(n: int) -> tuple[int, int]:
    """Return (F(n), F(n+1)) via fast doubling in O(log n)."""
    if n == 0:
        return 0, 1
    a, b = fib_fast(n >> 1)
    c = a * (2 * b - a)
    d = a * a + b * b
    if n & 1:
        return d, c + d
    return c, d

if __name__ == "__main__":
    for n in [0, 1, 2, 10, 30, 50, 100]:
        memoized = fib(n)
        fast = fib_fast(n)[0]
        assert memoized == fast, (n, memoized, fast)
        print(f"F({n}) = {memoized}")
    # identity: F(n)^2 + F(n+1)^2 == F(2n+1)
    for n in range(0, 25):
        assert fib(n) ** 2 + fib(n + 1) ** 2 == fib(2 * n + 1)
    print("all checks passed")
```
`lru_cache` turns the naive recursion into linear time by caching each `fib(n)` once. `fib_fast` uses the doubling identities `F(2k) = F(k)(2F(k+1) - F(k))` and `F(2k+1) = F(k)² + F(k+1)²`, so each call halves `n` and the recursion depth is logarithmic. The assertions cross-check the two implementations and the addition identity, which catches off-by-one errors in the odd branch. Python's big integers make `F(100)` exact.

```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t cap = 64, len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        fputs("out of memory\n", stderr);
        return 1;
    }

    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (len + 1 >= cap) {           /* leave room for the terminator */
            size_t new_cap = cap * 2;
            char *grown = realloc(buf, new_cap);
            if (grown == NULL) {
                free(buf);
                fputs("out of memory\n", stderr);
                return 1;
            }
            buf = grown;
            cap = new_cap;
        }
        buf[len++] = (char)ch;
    }
    buf[len] = '\0';

    for (size_t i = len; i > 0; i--) {
        putchar(buf[i - 1]);
    }
    putchar('\n');

    free(buf);
    return 0;
}
```
The buffer doubles with `realloc` whenever it is about to fill, so any line length is supported without a compile-time limit. The `len + 1 >= cap` check reserves space for the NUL terminator before each append. Underlying bytes are reversed, so multi-byte UTF-8 input comes out byte-reversed; a codepoint-aware version would need to scan for continuation bytes, which is beyond what a byte-level exercise requires. Input with no trailing newline before EOF is still terminated and printed.

