def fib(n: int) -> int:
    """Return the nth Fibonacci number, F(0)=0, F(1)=1."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def _pair(k: int):
        if k == 0:
            return (0, 1)
        a, b = _pair(k >> 1)
        c = a * (2 * b - a)      # F(2m)   = F(m)*(2F(m+1) - F(m))
        d = a * a + b * b        # F(2m+1) = F(m)^2 + F(m+1)^2
        if k & 1:
            return (d, c + d)    # F(2m+2) = F(2m) + F(2m+1)
        return (c, d)

    return _pair(n)[0]


