```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (!n) { return NULL; }
    n->value = value;
    n->next = head;
    return n;
}

/* Iterative: standard three-pointer walk. */
static Node *reverse_iter(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

/* Recursive: reverse the tail, then fix the two links. */
static Node *reverse_rec(Node *head) {
    if (!head || !head->next) { return head; }
    Node *rest = reverse_rec(head->next);
    head->next->next = head;
    head->next = NULL;
    return rest;
}

static void print_list(const Node *head) {
    for (; head; head = head->next) {
        printf("%d%s", head->value, head->next ? " -> " : "\n");
    }
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 5; i >= 1; --i) {
        list = push(list, i);
    }
    print_list(list);            /* 1 -> 2 -> 3 -> 4 -> 5 */

    list = reverse_iter(list);
    print_list(list);            /* 5 -> 4 -> 3 -> 2 -> 1 */

    list = reverse_rec(list);
    print_list(list);            /* 1 -> 2 -> 3 -> 4 -> 5 */

    free_list(list);
    return 0;
}
```

`push` returns `NULL` on allocation failure, and `main` never dereferences a freed node. The recursive version consumes O(n) stack, so the iterative one is preferred for long lists; both handle the empty and single-node cases.

