```rust
fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

/// Index where `target` is or would be inserted, keeping the slice sorted.
fn lower_bound<T: Ord>(slice: &[T], target: &T) -> usize {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if slice[mid] < *target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

fn main() {
    let data = [1, 3, 3, 5, 9];
    assert_eq!(binary_search(&data, &3), Some(1));
    assert_eq!(binary_search(&data, &4), None);
    assert_eq!(lower_bound(&data, &3), 1);
    assert_eq!(lower_bound(&data, &4), 3);
    assert_eq!(lower_bound(&data, &10), 5);
    assert_eq!(lower_bound(&[0u8; 0], &7), 0);
    println!("ok");
}
```
`lo + (hi - lo) / 2` avoids the overflow `(lo + hi) / 2` can hit, and `lower_bound` on an empty slice returns 0 rather than panicking.

```cpp
#include <cassert>
#include <iostream>
#include <list>
#include <stdexcept>
#include <unordered_map>

template <typename K, typename V>
class LruCache {
public:
    explicit LruCache(std::size_t capacity) : cap_(capacity) {
        if (cap_ == 0) throw std::invalid_argument("capacity must be > 0");
    }

    // Returns a pointer to the value, or nullptr if the key is absent.
    const V* get(const K &key) {
        auto it = map_.find(key);
        if (it == map_.end()) return nullptr;
        order_.splice(order_.begin(), order_, it->second);  // move to front
        return &it->second->second;
    }

    void put(const K &key, const V &value) {
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->second = value;
            order_.splice(order_.begin(), order_, it->second);
            return;
        }
        if (map_.size() == cap_) {
            const K victim = order_.back().first;
            order_.pop_back();
            map_.erase(victim);
        }
        order_.emplace_front(key, value);
        map_[key] = order_.begin();
    }

    std::size_t size() const { return map_.size(); }

private:
    std::size_t cap_;
    std::list<std::pair<K, V>> order_;
    std::unordered_map<K, typename std::list<std::pair<K, V>>::iterator> map_;
};

int main() {
    LruCache<int, int> c(2);
    c.put(1, 10);
    c.put(2, 20);
    assert(*c.get(1) == 10);   // 1 is now most-recent
    c.put(3, 30);              // evicts 2
    assert(c.get(2) == nullptr);
    assert(*c.get(1) == 10);
    assert(*c.get(3) == 30);
    c.put(3, 33);              // update existing
    assert(*c.get(3) == 33);
    assert(c.size() == 2);
    std::cout << "ok\n";
}
```
The list holds keys in recency order (front = MRU), and the map stores iterators so every move is a `splice`, which relinks nodes without copying. Get and put are both O(1).

