def normalize_ipv4(text):
    """Return a canonical 'a.b.c.d' string, or raise ValueError."""
    if not isinstance(text, str):
        raise ValueError("address must be a string")
    parts = text.strip().split(".")
    if len(parts) != 4:
        raise ValueError(f"expected 4 octets, got {len(parts)}")
    octets = []
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"non-numeric octet: {part!r}")
        if len(part) > 1 and part[0] == "0":
            raise ValueError(f"leading zero in octet: {part!r}")
        value = int(part)
        if not 0 <= value <= 255:
            raise ValueError(f"octet out of range: {part!r}")
        octets.append(value)
    return ".".join(str(o) for o in octets)


