```rust
use std::io::{self, Read};

/// CRC32 (IEEE 802.3, reflected polynomial 0xEDB88320), streaming.
struct Crc32 {
    table: [u32; 256],
    state: u32,
}

impl Crc32 {
    fn new() -> Self {
        let mut table = [0u32; 256];
        for i in 0..256u32 {
            let mut c = i;
            for _ in 0..8 {
                c = if c & 1 != 0 { 0xEDB8_8320 ^ (c >> 1) } else { c >> 1 };
            }
            table[i as usize] = c;
        }
        Crc32 { table, state: 0xFFFF_FFFF }
    }

    fn update(&mut self, bytes: &[u8]) {
        for &b in bytes {
            let idx = ((self.state ^ b as u32) & 0xFF) as usize;
            self.state = self.table[idx] ^ (self.state >> 8);
        }
    }

    fn finish(&self) -> u32 {
        self.state ^ 0xFFFF_FFFF
    }
}

fn main() -> io::Result<()> {
    let mut crc = Crc32::new();
    let mut buf = [0u8; 8192];
    let mut stdin = io::stdin().lock();
    loop {
        let n = stdin.read(&mut buf)?;
        if n == 0 {
            break;
        }
        crc.update(&buf[..n]);
    }
    println!("{:08x}", crc.finish());
    Ok(())
}
```

The table is built once, then each byte updates the state in constant time. Piping `printf 'hello' | ./crc32` prints `3610a686`, matching the standard IEEE value.

