    auto out = merge_intervals(input);
    for (const auto& iv : out) std::cout << "[" << iv.start << "," << iv.end << "] ";
    std::cout << "\n";

    // Edge cases
    std::cout << merge_intervals({}).size() << "\n";          // 0
    auto single = merge_intervals({{5, 5}});
    std::cout << single.size() << " " << single[0].start << "\n";  // 1 5
    auto touching = merge_intervals({{1, 2}, {2, 3}});
