#[derive(Debug, PartialEq, Eq)]
struct Node<T> {
    value: T,
    next: Option<Box<Node<T>>>,
}

fn push<T>(head: Option<Box<Node<T>>>, value: T) -> Option<Box<Node<T>>> {
    Some(Box::new(Node { value, next: head }))
}

fn reverse<T>(mut head: Option<Box<Node<T>>>) -> Option<Box<Node<T>>> {
    let mut prev: Option<Box<Node<T>>> = None;
    while let Some(mut node) = head {
        head = node.next.take();
        node.next = prev;
        prev = Some(node);
    }
    prev
}

fn to_vec<T: Clone>(mut head: Option<Box<Node<T>>>) -> Vec<T> {
    let mut out = Vec::new();
    while let Some(node) = head {
        out.push(node.value.clone());
        head = node.next;
    }
    out
}

fn main() {
