#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t len;
    size_t cap;
} Vec;

static int vec_reserve(Vec *v, size_t need) {
    if (need <= v->cap) return 1;
    size_t newcap = v->cap ? v->cap : 4;
    while (newcap < need) {
        if (newcap > (size_t)-1 / 2) return 0; /* overflow guard */
        newcap *= 2;
    }
    int *tmp = realloc(v->data, newcap * sizeof(int));
    if (!tmp) return 0; /* original block still valid */
    v->data = tmp;
    v->cap = newcap;
    return 1;
}

static int vec_push(Vec *v, int value) {
    if (!vec_reserve(v, v->len + 1)) return 0;
    v->data[v->len++] = value;
    return 1;
}

static void vec_maybe_shrink(Vec *v) {
    if (v->cap >= 8 && v->len * 4 <= v->cap) {
        size_t newcap = v->cap / 2;
        int *tmp = realloc(v->data, newcap * sizeof(int));
        if (tmp) {
            v->data = tmp;
            v->cap = newcap;
        }
    }
}

static void vec_pop(Vec *v, int *out) {
    if (v->len == 0) return;
    *out = v->data[--v->len];
    vec_maybe_shrink(v);
}

int main(void) {
    Vec v = {0};
    for (int i = 0; i < 100; ++i) {
        if (!vec_push(&v, i)) { fprintf(stderr, "alloc failed\n"); free(v.data); return 1; }
    }
    /* pop everything back down; capacity should shrink */
    int last = 0;
    while (v.len > 0) vec_pop(&v, &last);
    printf("len=%zu cap=%zu last=%d\n", v.len, v.cap, last); /* len=0 cap<100 last=99 */
    free(v.data);
    return 0;
}
