#include <cstdint>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // max-heap for the lower half, min-heap for the upper half.
    std::priority_queue<std::int64_t> lower;
    std::priority_queue<std::int64_t, std::vector<std::int64_t>,
                        std::greater<std::int64_t>> upper;

    std::int64_t x;
    bool first = true;
    while (std::cin >> x) {
        if (lower.empty() || x <= lower.top()) {
            lower.push(x);
        } else {
            upper.push(x);
        }
        // Rebalance so lower has the same size as upper or one more.
        if (lower.size() > upper.size() + 1) {
            upper.push(lower.top());
            lower.pop();
        } else if (upper.size() > lower.size()) {
            lower.push(upper.top());
            upper.pop();
        }

        if (!first) std::cout << '\n';
        first = false;
        if (lower.size() == upper.size()) {
            std::cout << (lower.top() + upper.top()) / 2.0;
        } else {
            std::cout << lower.top();
        }
    }
    if (!first) std::cout << '\n';
    return 0;
}
```
Two heaps keep insertion O(log n). The lower heap holds the smaller half and is never more than one element larger, so the median is either its top or the average of both tops. The `first` flag avoids a trailing blank line and an empty-output edge case is handled naturally.

```rust
#[derive(Debug, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
}

#[derive(Debug, PartialEq, Eq)]
pub enum ParseError {
    Empty,
    TooFewParts,
    TooManyParts,
    NotANumber(String),
    PreRelease,
}

pub fn parse_version(input: &str) -> Result<Version, ParseError> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err(ParseError::Empty);
    }

    let core = match trimmed.split_once(['-', '+']) {
        Some((core, _suffix)) => core,
        None => trimmed,
    };
    // A suffix means pre-release or build metadata, which we do not accept yet.
    if core.len() != trimmed.len() {
        return Err(ParseError::PreRelease);
    }

    let parts: Vec<&str> = core.split('.').collect();
    match parts.len() {
        0 => return Err(ParseError::Empty),
        1 | 2 => return Err(ParseError::TooFewParts),
        3 => {}
        _ => return Err(ParseError::TooManyParts),
    }

    let mut nums = [0u64; 3];
    for (i, part) in parts.iter().enumerate() {
        if part.is_empty() {
            return Err(ParseError::NotANumber((*part).to_string()));
        }
        nums[i] = part
            .parse::<u64>()
            .map_err(|_| ParseError::NotANumber((*part).to_string()))?;
    }

    Ok(Version { major: nums[0], minor: nums[1], patch: nums[2] })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_plain() {
        assert_eq!(parse_version("1.2.3"), Ok(Version { major: 1, minor: 2, patch: 3 }));
        assert_eq!(parse_version(" 10.0.0 "), Ok(Version { major: 10, minor: 0, patch: 0 }));
    }

    #[test]
    fn rejects_bad() {
        assert_eq!(parse_version(""), Err(ParseError::Empty));
        assert_eq!(parse_version("1.2"), Err(ParseError::TooFewParts));
        assert_eq!(parse_version("1.2.3.4"), Err(ParseError::TooManyParts));
        assert_eq!(parse_version("1.x.3"), Err(ParseError::NotANumber("x".into())));
        assert_eq!(parse_version("1.2.3-beta"), Err(ParseError::PreRelease));
    }
}
```
`split_once` with a char array peels off any suffix, and comparing `core.len()` to `trimmed.len()` detects it without allocating. Every failure mode is a distinct enum variant, and the tests pin each one.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (!n) return NULL;
    n->value = value;
    n->next = head;
    return n;
}

/* Iterative: walk the list, flipping each next pointer. */
Node *reverse_iter(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

/* Recursive: reverse the tail, then attach head to its end. */
Node *reverse_rec(Node *head) {
    if (!head || !head->next) return head;
    Node *new_head = reverse_rec(head->next);
    head->next->next = head;
    head->next = NULL;
    return new_head;
}

static void print_list(const Node *head) {
    for (const Node *p = head; p; p = p->next) {
        printf("%d", p->value);
        if (p->next) printf(" -> ");
    }
    putchar('\n');
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

static Node *build(int *values, size_t n) {
    Node *head = NULL;
    for (size_t i = 0; i < n; i++) {
        Node *n2 = push(head, values[i]);
        if (!n2) { free_list(head); return NULL; }
        head = n2;
    }
    return head;
}

int main(void) {
    int values[] = {1, 2, 3, 4, 5};

    Node *a = build(values, 5);
    if (!a) { fprintf(stderr, "alloc failed\n"); return 1; }
    printf("iterative:  ");
    print_list(reverse_iter(a));

    Node *b = build(values, 5);
    if (!b) { fprintf(stderr, "alloc failed\n"); return 1; }
    printf("recursive:  ");
    print_list(reverse_rec(b));

    /* Edge cases: empty and single-node lists. */
    printf("empty iter: ");
    print_list(reverse_iter(NULL));
    Node *single = build((int[]){42}, 1);
    printf("single rec: ");
    print_list(reverse_rec(single));
    free_list(single);

    return 0;
}
```
Both versions return the new head. The iterative one flips pointers with three cursors; the recursive one bottoms out at the last node and rewires on the way back. `build`, `push` and `free_list` handle allocation failure so there is no leak in the error path, and empty/single-node cases are exercised at the end.

```rust
use std::collections::HashMap;
use std::env;
use std::fs;
use std::thread;

fn count_words(path: &str) -> HashMap<String, usize> {
    let mut counts = HashMap::new();
    let text = match fs::read_to_string(path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("skipping {path}: {e}");
            return counts;
        }
    };
    for word in text.split(|c: char| !c.is_alphanumeric() && c != '\'') {
        let w = word.trim_matches('\'').to_lowercase();
        if !w.is_empty() {
            *counts.entry(w).or_insert(0) += 1;
        }
    }
    counts
}

fn main() {
    let paths: Vec<String> = env::args().skip(1).collect();
    if paths.is_empty() {
        eprintln!("usage: wordcount <file> [file ...]");
        std::process::exit(2);
    }

    let handles: Vec<_> = paths
        .into_iter()
        .map(|p| thread::spawn(move || count_words(&p)))
        .collect();

    let mut total: HashMap<String, usize> = HashMap::new();
    for h in handles {
        let partial = h.join().expect("worker thread panicked");
        for (word, n) in partial {
            *total.entry(word).or_insert(0) += n;
        }
    }

    let mut ranked: Vec<(String, usize)> = total.into_iter().collect();
    // Deterministic: by count desc, then word asc.
    ranked.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    for (word, n) in ranked.iter().take(10) {
        println!("{n:>7}  {word}");
    }
}
```
Each file is parsed on its own thread, then partial maps are merged on the main thread — no locks needed because the workers never share mutable state. Unreadable files are reported to stderr and skipped rather than aborting the run, and the final sort is deterministic for equal counts.

```cpp
#include <cassert>
#include <cstddef>
#include <iostream>
#include <random>
#include <vector>

template <typename T>
using Matrix = std::vector<std::vector<T>>;

template <typename T>
Matrix<T> zeros(std::size_t rows, std::size_t cols) {
    return Matrix<T>(rows, std::vector<T>(cols, T{}));
}

// i-k-j order: the inner loop walks contiguous rows of B and C, so it is
// cache-friendly and still O(n^3).
template <typename T>
Matrix<T> matmul_ikj(const Matrix<T>& a, const Matrix<T>& b) {
    const std::size_t n = a.size();
    const std::size_t m = b[0].size();
    const std::size_t k = b.size();
    Matrix<T> c = zeros<T>(n, m);
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t kk = 0; kk < k; ++kk) {
            const T aik = a[i][kk];
            for (std::size_t j = 0; j < m; ++j) {
                c[i][j] += aik * b[kk][j];
            }
        }
    }
    return c;
}

// Reference implementation: i-j-k order, simple but more cache misses.
template <typename T>
Matrix<T> matmul_naive(const Matrix<T>& a, const Matrix<T>& b) {
    Matrix<T> c = zeros<T>(a.size(), b[0].size());
    for (std::size_t i = 0; i < a.size(); ++i) {
        for (std::size_t j = 0; j < b[0].size(); ++j) {
            T sum{};
            for (std::size_t k = 0; k < b.size(); ++k) {
                sum += a[i][k] * b[k][j];
            }
            c[i][j] = sum;
        }
    }
    return c;
}

int main() {
    std::mt19937 rng(42);
    std::uniform_int_distribution<int> dist(-5, 5);

    const std::size_t n = 7, k = 5, m = 6;
    Matrix<long long> a = zeros<long long>(n, k);
    Matrix<long long> b = zeros<long long>(k, m);
    for (auto& row : a)
        for (auto& x : row) x = dist(rng);
    for (auto& row : b)
        for (auto& x : row) x = dist(rng);

    assert(matmul_ikj(a, b) == matmul_naive(a, b));
    std::cout << "matmul verified: " << n << "x" << k << " * " << k << "x" << m << "\n";
    return 0;
}
```
The i-k-j loop order reuses `a[i][k]` across the whole inner loop and walks `b[k][j]` and `c[i][j]` contiguously. Shapes are taken from the operands, and the seed-42 random matrices give a repeatable cross-check against the straightforward i-j-k version.

