#include <iostream>
#include <climits>

bool isPalindrome(int x) {
    if (x < 0) return false;
    if (x != 0 && x % 10 == 0) return false;
    int rev = 0;
    while (x > rev) {
        rev = rev * 10 + x % 10;
        x /= 10;
    }
    return x == rev || x == rev / 10;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << isPalindrome(121) << "\n";   // true
    std::cout << isPalindrome(-121) << "\n";  // false
    std::cout << isPalindrome(10) << "\n";    // false
    std::cout << isPalindrome(0) << "\n";     // true
    std::cout << isPalindrome(12321) << "\n"; // true
    return 0;
}
