```python
class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._buf = [None] * capacity
        self._cap = capacity
        self._size = 0
        self._head = 0

    def append(self, value):
        idx = (self._head + self._size) % self._cap
        self._buf[idx] = value
        if self._size < self._cap:
            self._size += 1
        else:
            self._head = (self._head + 1) % self._cap

    def __len__(self):
        return self._size

    def __iter__(self):
        for i in range(self._size):
            yield self._buf[(self._head + i) % self._cap]

    def to_list(self):
        return list(self)


if __name__ == "__main__":
    rb = RingBuffer(3)
    for v in (1, 2, 3, 4, 5):
        rb.append(v)
    assert rb.to_list() == [3, 4, 5]
    assert len(rb) == 3
    assert RingBuffer(1).to_list() == []
    print("ok")
```
When the buffer is full, `_head` advances so the oldest value is overwritten while iteration still yields values oldest-to-newest.

