    if (n == 0) {
        printf("no input\n");
        free(arr);
        return 0;
    }
    int mn = arr[0], mx = arr[0];
    for (size_t i = 1; i < n; i++) {
        if (arr[i] < mn) mn = arr[i];
        if (arr[i] > mx) mx = arr[i];
    }
    printf("min=%d max=%d count=%zu\n", mn, mx, n);
