fn longest_run(s: &str) -> usize {
    let mut best = 0usize;
    let mut cur = 0usize;
    let mut prev: Option<char> = None;
    for ch in s.chars() {
        if Some(ch) == prev {
            cur += 1;
        } else {
            cur = 1;
            prev = Some(ch);
        }
        if cur > best {
            best = cur;
        }
    }
    best
}

