def collatz_length(n: int) -> int:
    """Return the number of steps to reach 1 under the Collatz rules."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int")
    if n < 1:
        raise ValueError("n must be a positive integer")
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps


if __name__ == "__main__":
    for value in (1, 2, 3, 6, 27):
        print(value, collatz_length(value))
    try:
        collatz_length(0)
    except ValueError as exc:
        print("caught:", exc)
```
