```c
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

int main(void) {
    int values[] = {1, 2, 3, 4};
    Node *head = NULL;
    for (size_t i = 0; i < sizeof values / sizeof values[0]; i++) {
        Node *n = malloc(sizeof *n);
        if (n == NULL) return 1;
        n->value = values[i];
        n->next = head;
        head = n;
    }

    head = reverse(head);
    for (Node *p = head; p != NULL; p = p->next) {
        printf("%d ", p->value);
    }
    printf("\n");

    while (head != NULL) {
        Node *tmp = head->next;
        free(head);
        head = tmp;
    }
    return 0;
}
```
The loop uses three pointers: `prev` becomes the new tail, `cur` walks forward, and `next` is saved before rewiring so the list is not lost. An empty list or a single node both come out correctly because `prev` starts as `NULL`.

