#include <numeric>
#include <cstdint>

std::uint64_t gcd(std::uint64_t a, std::uint64_t b) {
    while (b != 0) {
        std::uint64_t t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    std::uint64_t a = 0, b = 0;
    std::cin >> a >> b;
    std::uint64_t g = gcd(a, b);
    std::cout << "gcd=" << g << '\n';
    if (g == 0) {
