```python
class MinStack:
    """Stack with O(1) push, pop, top, and get_min."""

    def __init__(self, capacity=None):
        if capacity is not None and capacity < 1:
            raise ValueError("capacity must be positive")
        self._data = []
        self._mins = []
        self._capacity = capacity

    def push(self, value):
        if self._capacity is not None and len(self._data) >= self._capacity:
            raise OverflowError("stack is full")
        self._data.append(value)
        if not self._mins or value <= self._mins[-1]:
            self._mins.append(value)

    def pop(self):
        if not self._data:
            raise IndexError("pop from empty stack")
        value = self._data.pop()
        if value == self._mins[-1]:
            self._mins.pop()
        return value

    def top(self):
        if not self._data:
            raise IndexError("top from empty stack")
        return self._data[-1]

    def get_min(self):
        if not self._mins:
            raise IndexError("min from empty stack")
        return self._mins[-1]

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    s = MinStack(capacity=3)
    s.push(5)
    s.push(3)
    s.push(3)
    print(s.get_min(), s.pop(), s.get_min())
```
The auxiliary `_mins` stack records the running minimum only when a value is `<=` the current minimum. Using `<=` rather than `<` matters with duplicates: two equal minima each push an entry so a single pop cannot erase the minimum for the remaining element.

