```c
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>
#include <ctype.h>

/* Returns 0 on success, -1 on error. Writes the value to *out. */
int parse_long(const char *s, long *out)
{
    if (s == NULL || out == NULL || *s == '\0') return -1;
    const char *p = s;
    while (isspace((unsigned char)*p)) p++;
    if (*p == '\0') return -1;
    errno = 0;
    char *end = NULL;
    long v = strtol(p, &end, 10);
    if (errno == ERANGE) return -1;          /* overflow / underflow */
    if (end == p) return -1;                 /* no digits */
    while (isspace((unsigned char)*end)) end++;
    if (*end != '\0') return -1;             /* trailing junk */
    *out = v;
    return 0;
}

int main(void)
{
    long v;
    printf("%d\n", parse_long("  42 ", &v));   /* 0, v=42 */
    printf("%d\n", parse_long("abc", &v));    /* -1      */
    printf("%d\n", parse_long("12x", &v));    /* -1      */
    unsigned long big = (unsigned long)LONG_MAX + 1UL;
    char buf[32];
    snprintf(buf, sizeof buf, "%lu", big);
    printf("%d\n", parse_long(buf, &v));       /* -1      */
    return 0;
}
```

`strtol` sets `errno = ERANGE` on overflow, and checking `end` catches both empty-digit and trailing-garbage cases. `isspace` is called with an `unsigned char` cast to avoid undefined behaviour on high-bit input.

