#include <iostream>
#include <vector>
#include <unordered_set>

std::vector<int> dedup(const std::vector<int>& in)
{
    std::vector<int> out;
    out.reserve(in.size());
    std::unordered_set<int> seen;
    seen.reserve(in.size() * 2);
    for (int x : in) {
        if (seen.insert(x).second) {
            out.push_back(x);
        }
    }
    return out;
}

int main()
{
    std::vector<int> v{3, 1, 3, 2, 1, 4, 4};
    auto r = dedup(v);
    for (int x : r) std::cout << x << ' ';
    std::cout << '\n';                       // 3 1 2 4
    std::vector<int> empty;
    std::cout << dedup(empty).size() << '\n'; // 0
    return 0;
}
```

`unordered_set::insert` returns a pair whose `.second` is `true` only when the element was new, so the vector keeps first-seen order in a single pass. `reserve` avoids rehashing and reallocation for the common case.

```rust
fn chunk_by_chars(s: &str, n: usize) -> Vec<&str> {
    assert!(n > 0, "chunk size must be positive");
    let mut out = Vec::new();
    let mut start = 0usize;
    for (i, c) in s.char_indices() {
        let byte_len = c.len_utf8();
        if i + byte_len - start > n && i > start {
            out.push(&s[start..i]);
            start = i;
        }
        let _ = i; // index kept for clarity
    }
    if start < s.len() {
        out.push(&s[start..]);
    }
    out
}

fn main() {
    let s = "héllo wörld";
    let parts = chunk_by_chars(s, 4);
    for p in &parts {
        println!("{:?} ({} bytes)", p, p.len());
    }
    let joined: String = parts.concat();
    assert_eq!(joined, s, "reassembly must be lossless");
    println!("lossless ok");
}
```

