fn running_max(xs: &[i64]) -> Vec<i64> {
    let mut out = Vec::with_capacity(xs.len());
    let mut best: Option<i64> = None;
    for &x in xs {
        best = Some(match best {
            Some(b) => b.max(x),
            None => x,
        });
        out.push(best.unwrap());
    }
    out
}

fn main() {
    assert_eq!(running_max(&[]), Vec::<i64>::new());
    assert_eq!(running_max(&[3]), vec![3]);
    assert_eq!(running_max(&[1, 3, 2, 5, 4]), vec![1, 3, 3, 5, 5]);
    assert_eq!(running_max(&[-4, -9, -1]), vec![-4, -4, -1]);
    println!("all checks passed");
}
```

