def is_valid_ipv4(s: str) -> bool:
    if not isinstance(s, str):
        return False
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit() or len(part) > 3:
            return False
        if len(part) > 1 and part[0] == "0":   # reject leading zeros
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True


