```rust
fn binary_search<T: Ord>(hay: &[T], needle: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = hay.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match hay[mid].cmp(needle) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

fn main() {
    let v = [1, 3, 5, 7, 9];
    assert_eq!(binary_search(&v, &1), Some(0));
    assert_eq!(binary_search(&v, &9), Some(4));
    assert_eq!(binary_search(&v, &4), None);
    assert_eq!(binary_search(&[] as &[i32], &0), None);
    println!("{:?}", binary_search(&v, &7));
}
```

`lo + (hi - lo) / 2` avoids overflow that `(lo + hi) / 2` can hit on large slices. The half-open `[lo, hi)` bounds make the empty-slice case fall straight through to `None` without a special check.

