def merge_intervals(intervals):
    if not intervals:
        return []
    ordered = sorted(intervals)
    merged = [list(ordered[0])]
    for start, end in ordered[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return [tuple(iv) for iv in merged]


if __name__ == "__main__":
    assert merge_intervals([]) == []
    assert merge_intervals([(1, 3), (2, 6), (8, 10)]) == [(1, 6), (8, 10)]
    assert merge_intervals([(5, 7), (1, 2)]) == [(1, 2), (5, 7)]
    assert merge_intervals([(1, 10), (2, 3)]) == [(1, 10)]
    print(merge_intervals([(1, 3), (2, 6), (8, 10)]))
```

Sorting by start makes merging a single pass. `start <= merged[-1][1]` catches touching intervals too, and `max` handles a fully contained interval like `(2, 3)` inside `(1, 10)` instead of shrinking the end.

