#include <iostream>
#include <vector>

// Count occurrences of `target` in a sorted range in O(log n).
template <typename T>
std::size_t count_sorted(const std::vector<T>& v, const T& target) {
    auto lo = std::lower_bound(v.begin(), v.end(), target);
    auto hi = std::upper_bound(v.begin(), v.end(), target);
    return static_cast<std::size_t>(hi - lo);
}

int main() {
    std::vector<int> v{1, 2, 2, 2, 3, 3, 5, 8, 8, 8, 8};
    assert(count_sorted(v, 2) == 3);
    assert(count_sorted(v, 3) == 2);
    assert(count_sorted(v, 8) == 4);
    assert(count_sorted(v, 4) == 0);   // absent
    assert(count_sorted(std::vector<int>{}, 1) == 0);  // empty
    std::cout << "ok\n";
    return 0;
}
```

`lower_bound` and `upper_bound` bracket the run of equal elements; the difference is the count. Empty vectors and missing values fall out naturally as `0`.

