#include <cstdio>
#include <stdexcept>
#include <utility>

class File {
public:
    explicit File(const char* path, const char* mode = "rb")
        : fp_(std::fopen(path, mode)) {
        if (fp_ == nullptr) {
            throw std::runtime_error(std::string("cannot open: ") + path);
        }
    }

    ~File() { if (fp_) std::fclose(fp_); }

    File(const File&) = delete;
    File& operator=(const File&) = delete;

    File(File&& other) noexcept : fp_(other.fp_) { other.fp_ = nullptr; }
    File& operator=(File&& other) noexcept {
        if (this != &other) {
            if (fp_) std::fclose(fp_);
            fp_ = other.fp_;
            other.fp_ = nullptr;
        }
        return *this;
    }

    std::FILE* get() const noexcept { return fp_; }

private:
    std::FILE* fp_;
};

int main() {
    File f("/etc/hostname");
    char buf[256];
    if (std::fgets(buf, sizeof buf, f.get())) std::fputs(buf, stdout);
    return 0;
}
