fn longest_palindrome(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    if chars.is_empty() {
        return String::new();
    }
    let mut best_start = 0;
    let mut best_len = 1;

    let mut expand = |mut l: usize, mut r: usize| {
        while r < chars.len() && chars[l] == chars[r] {
            if r - l + 1 > best_len {
                best_len = r - l + 1;
                best_start = l;
            }
            if l == 0 {
                break;
            }
            l -= 1;
            r += 1;
        }
    };

    for i in 0..chars.len() {
        expand(i, i);       // odd length
        expand(i, i + 1);   // even length
    }

    chars[best_start..best_start + best_len].iter().collect()
}

fn main() {
    assert_eq!(longest_palindrome("babad"), "bab");
    assert_eq!(longest_palindrome("cbbd"), "bb");
    assert_eq!(longest_palindrome(""), "");
    assert_eq!(longest_palindrome("ab"), "a");
    assert_eq!(longest_palindrome("\u{4f60}\u{597d}\u{4f60}"), "\u{4f60}\u{597d}\u{4f60}");
    println!("ok");
}
```

Iterating over `chars` means multi-byte characters count as one unit, so the unicode case works. Each centre expands outward once, giving O(n^2) worst case and O(n) extra space.

