#include <cassert>
#include <iostream>
#include <map>
#include <string>

std::map<std::string, std::string> parse_kv(const std::string& line) {
    std::map<std::string, std::string> out;
    std::size_t pos = 0;
    while (pos <= line.size()) {
        std::size_t sep = line.find(';', pos);
        std::string token = line.substr(pos, sep == std::string::npos
                                              ? std::string::npos
                                              : sep - pos);
        auto trim = [](std::string s) {
            const char* ws = " \t\r\n";
            auto b = s.find_first_not_of(ws);
            if (b == std::string::npos) return std::string{};
            auto e = s.find_last_not_of(ws);
            return s.substr(b, e - b + 1);
        };
        token = trim(token);
        if (!token.empty()) {
            std::size_t eq = token.find('=');
            if (eq != std::string::npos) {
                std::string key = trim(token.substr(0, eq));
                std::string val = trim(token.substr(eq + 1));
                if (!key.empty()) out.emplace(key, val);  // first wins
            }
        }
        if (sep == std::string::npos) break;
        pos = sep + 1;
    }
    return out;
}

int main() {
    auto m = parse_kv("a = 1 ; b=2; a=9 ;; c = hello world ");
    assert(m.at("a") == "1");
    assert(m.at("b") == "2");
    assert(m.at("c") == "hello world");
    assert(m.size() == 3);
    std::cout << "ok\n";
    return 0;
}
```

`emplace` only inserts if the key is absent, so the first `a=1` is kept and `a=9` is ignored. Empty tokens and keys with no `=` are skipped, and values may contain spaces.

