#include <algorithm>
#include <iostream>
#include <string>

// Reverses word order: "  the sky  is blue " -> "blue is sky the".
std::string reverse_words(const std::string& input) {
    std::string tokens;
    std::size_t i = 0;
    while (i < input.size()) {
        while (i < input.size() && input[i] == ' ') ++i;
        if (i >= input.size()) break;
        std::size_t start = i;
        while (i < input.size() && input[i] != ' ') ++i;
        if (!tokens.empty()) tokens += ' ';
        tokens.append(input, start, i - start);
    }
    std::reverse(tokens.begin(), tokens.end());
    // Reverse each word back.
    std::size_t n = tokens.size();
    std::size_t begin = 0;
    for (std::size_t end = 0; end <= n; ++end) {
        if (end == n || tokens[end] == ' ') {
            std::reverse(tokens.begin() + begin, tokens.begin() + end);
            begin = end + 1;
        }
    }
    return tokens;
}

int main() {
    std::cout << '[' << reverse_words("  the sky  is blue ") << "]\n";
    std::cout << '[' << reverse_words("") << "]\n";
    std::cout << '[' << reverse_words("   ") << "]\n";
    std::cout << '[' << reverse_words("one") << "]\n";
}
