/// Longest common prefix of `words` (empty string if none).
fn longest_common_prefix(words: &[&str]) -> String {
    let first = match words.first() {
        Some(w) => *w,
        None => return String::new(),
    };

    let mut prefix_len = first.len();
    for word in &words[1..] {
        let mut common = 0usize;
        for (a, b) in first.bytes().zip(word.bytes()) {
            if a == b {
                common += 1;
            } else {
                break;
            }
        }
        if common < prefix_len {
            prefix_len = common;
        }
        if prefix_len == 0 {
            break;
        }
    }

    // prefix_len lands on a char boundary only if the words share whole chars,
    // so slicing here is safe for valid UTF-8 inputs.
    first[..prefix_len].to_string()
}

fn main() {
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&["dog", "racecar", "car"]), "");
    assert_eq!(longest_common_prefix(&["only"]), "only");
    assert_eq!(longest_common_prefix(&["abc", "abc", "abc"]), "abc");
    println!("ok");
}
