import re

_UNITS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_PATTERN = re.compile(r"(\d+)([dhms])")


def parse_duration(text: str) -> int:
    """Convert a duration like '1h30m45s' or '2d4h' to seconds.

    Raises ValueError on empty input, unknown units, duplicate units,
    or leftover characters that the pattern did not consume.
    """
    if not text:
        raise ValueError("empty duration")
    pos = 0
    seen = set()
    total = 0
    for match in _PATTERN.finditer(text):
        if match.start() != pos:
            raise ValueError(f"unexpected text at position {match.start()!r}")
        pos = match.end()
        value, unit = match.group(1), match.group(2)
        if unit in seen:
            raise ValueError(f"duplicate unit {unit!r}")
        seen.add(unit)
        total += int(value) * _UNITS[unit]
    if pos != len(text):
        raise ValueError(f"trailing text: {text[pos:]!r}")
    return total


if __name__ == "__main__":
    assert parse_duration("1h30m45s") == 5445
    assert parse_duration("2d4h") == 187200
    assert parse_duration("90s") == 90
    for bad in ("", "10", "1h1h", "1x", "5s garbage"):
        try:
            parse_duration(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"should have rejected {bad!r}")
    print("ok")
