#include <cstddef>
#include <optional>
#include <stdexcept>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), size_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == buf_.size(); }
    std::size_t size() const { return size_; }

    bool push(const T& value) {
        if (full()) return false;
        std::size_t tail = (head_ + size_) % buf_.size();
        buf_[tail] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return value;
    }

    T& operator[](std::size_t i) {
        if (i >= size_) throw std::out_of_range("index past logical size");
        return buf_[(head_ + i) % buf_.size()];
    }

private:
    std::vector<T> buf_;
    std::size_t head_;
    std::size_t size_;
};

#include <cassert>
#include <iostream>

int main() {
    RingBuffer<int> rb(3);
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(!rb.push(4));                 // full
    assert(rb[0] == 1 && rb[2] == 3);
    assert(rb.pop() == 1);
    assert(rb.push(4));                  // wraps around
    assert(rb[0] == 2 && rb[2] == 4);
    assert(rb.pop() == 2 && rb.pop() == 3 && rb.pop() == 4);
    assert(rb.pop() == std::nullopt);
    std::cout << "ok\n";
}
