    bool in_word = false;
    char ch;
    while (in.get(ch)) {
        ++c.bytes;
        if (ch == '\n') ++c.lines;
        bool space = (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' ||
                      ch == '\f' || ch == '\v');
        if (space) {
            in_word = false;
        } else if (!in_word) {
            in_word = true;
            ++c.words;
        }
    }
    return c;
}

