fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 4, 6, 8, 9];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);
    assert_eq!(merge_sorted(&a[..0], &b), b);
    assert_eq!(merge_sorted(&a, &b[..0]), a);
    let empty: [i32; 0] = [];
    assert!(merge_sorted(&empty, &empty).is_empty());
    let dupes = [1, 1, 2];
    let more = [1, 2, 2];
    assert_eq!(merge_sorted(&dupes, &more), vec![1, 1, 1, 2, 2, 2]);
    println!("ok");
}
