def two_largest(values):
    """Return (largest, second_largest) distinct values, or None."""
    if not values:
        return None
    seen = set()
    top = second = None
    for v in values:
        if v in seen:
            continue
        seen.add(v)
        if top is None or v > top:
            second = top
            top = v
        elif second is None or v > second:
            second = v
    if second is None:
        return None
    return (top, second)


