use std::collections::BTreeMap;

pub fn word_frequencies(text: &str) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for word in text.split(|c: char| !c.is_alphanumeric()) {
        if word.is_empty() {
            continue;
        }
        let key = word.to_lowercase();
        *counts.entry(key).or_insert(0) += 1;
    }
    counts
}

fn main() {
    let text = "The quick, the QUICK! brown fox... the fox";
    let freqs = word_frequencies(text);
    for (word, n) in &freqs {
        println!("{word}: {n}");
    }
    assert_eq!(freqs["the"], 3);
    assert_eq!(freqs["quick"], 2);
    assert_eq!(freqs["fox"], 2);
    assert_eq!(freqs.len(), 4);
}
```

Splitting on non-alphanumeric characters removes punctuation and collapses separators; `to_lowercase` gives case-insensitive keys while the `BTreeMap` yields alphabetical iteration order. Non-ASCII letters pass `is_alphanumeric`, so accented words are counted too.

