            .ok_or_else(|| format!("line {}: missing '=' in {line:?}", idx + 1))?;
        let key = key.trim().to_string();
        if key.is_empty() {
            return Err(format!("line {}: empty key", idx + 1));
        }
        if map.contains_key(&key) {
            return Err(format!("line {}: duplicate key {key:?}", idx + 1));
        }
        map.insert(key, value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let cfg = parse_config("host = localhost\n# comment\nport=8080\n").unwrap();
    assert_eq!(cfg["host"], "localhost");
    assert_eq!(cfg["port"], "8080");
    assert!(parse_config("a=1\na=2").is_err());
    println!("{:?}", cfg);
}
```

`split_once('=')` keeps any extra `=` signs in the value, which is the right behaviour for values like URLs. Error messages carry 1-based line numbers so a failure points at the offending line; duplicate keys are rejected rather than silently overwritten.

```cpp
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : buf_(capacity), cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(double v) {
        buf_[(head_ + size_) % cap_] = v;
        if (size_ < cap_) {
            ++size_;
        } else {
            head_ = (head_ + 1) % cap_;
        }
    }

    std::size_t size() const { return size_; }

    std::vector<double> to_vector() const {
        std::vector<double> out;
        out.reserve(size_);
        for (std::size_t i = 0; i < size_; ++i)
            out.push_back(buf_[(head_ + i) % cap_]);
        return out;
    }

private:
    std::vector<double> buf_;
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    for (double v : {1.0, 2.0, 3.0, 4.0}) rb.push(v);
    for (double v : rb.to_vector()) std::cout << v << ' ';
    std::cout << "\n"; // 2 3 4
}
```

A full buffer writes at the tail slot and then advances `head_`, so the newest value always survives and the oldest is overwritten. `to_vector` walks from `head_` for `size_` steps, giving insertion order regardless of wraparound.

