            low.push(x);
        } else {
            high.push(x);
        }

        // Rebalance: keep sizes within one of each other
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        double median;
        if (low.size() == high.size()) {
            median = (low.top() + high.top()) / 2.0;
        } else {
            median = static_cast<double>(low.top());
        }
