#include <vector>
#include <optional>

// Returns the index of the first occurrence of target in a sorted vector,
// or -1 if absent. Uses lower_bound-style search to find the leftmost match.
template <typename T>
int first_occurrence(const std::vector<T>& v, const T& target) {
    std::size_t lo = 0;
    std::size_t hi = v.size();  // half-open [lo, hi)

    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (v[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    if (lo < v.size() && v[lo] == target) {
        return static_cast<int>(lo);
    }
    return -1;
}

#ifdef UNIT_TEST
#include <cassert>
int main() {
    std::vector<int> v{1, 2, 2, 2, 3, 5, 8};
    assert(first_occurrence(v, 2) == 1);
    assert(first_occurrence(v, 1) == 0);
    assert(first_occurrence(v, 8) == 6);
    assert(first_occurrence(v, 4) == -1);
    assert(first_occurrence(std::vector<int>{}, 7) == -1);
    return 0;
}
#endif
