from collections import deque
from threading import Lock


class BoundedQueue:
    def __init__(self, maxlen: int):
        if maxlen <= 0:
            raise ValueError('maxlen must be positive')
        self._maxlen = maxlen
        self._items = deque()
        self._lock = Lock()

    def push(self, item):
        with self._lock:
            if len(self._items) == self._maxlen:
                self._items.popleft()
            self._items.append(item)

    def pop(self):
        with self._lock:
            if not self._items:
                raise IndexError('pop from empty queue')
            return self._items.popleft()

    def __len__(self):
        with self._lock:
            return len(self._items)


if __name__ == '__main__':
    q = BoundedQueue(3)
    for v in (1, 2, 3, 4):
        q.push(v)
    assert list(q._items) == [2, 3, 4]
    assert q.pop() == 2
    try:
        BoundedQueue(0)
        raise SystemExit('should have raised')
    except ValueError:
        pass
    print('ok')
```

The lock makes push/pop safe across threads; `popleft` discards the oldest entry once capacity is reached. Invalid `maxlen` is rejected up front.

