#include <cstdint>
#include <cassert>
#include <iostream>

static std::uint64_t isqrt(std::uint64_t n) {
    if (n < 2) return n;
    std::uint64_t x = n;
    std::uint64_t y = (x + 1) / 2;
    while (y < x) {
        x = y;
        y = (x + n / x) / 2;
    }
    return x;
}

int main() {
    for (std::uint64_t n = 0; n < 100000; ++n) {
        std::uint64_t r = 0;
        while ((r + 1) * (r + 1) <= n) ++r;
        assert(isqrt(n) == r);
        assert(isqrt(n) * isqrt(n) <= n);
        assert((isqrt(n) + 1) * (isqrt(n) + 1) > n);
    }
    std::cout << isqrt(1000000000000ULL) << "\n";
    return 0;
}
```

Newton's iteration converges when `y >= x`; the loop condition handles `n == 0` and `n == 1` directly. The exhaustive check up to 100000 confirms both correctness and the invariant `r*r <= n < (r+1)*(r+1)`. Output for 10^12 is `1000000`.

