            handle_ = other.handle_;
            other.handle_ = nullptr;
        }
        return *this;
    }

    std::FILE* get() const { return handle_; }
    explicit operator bool() const { return handle_ != nullptr; }

private:
    std::FILE* handle_;
};

int main() {
