```c
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>

typedef struct {
    int *data;
    size_t len;
    size_t cap;
} Vec;

static int vec_reserve(Vec *v, size_t need) {
    if (need <= v->cap) return 1;
    size_t cap = v->cap ? v->cap : 4;
    while (cap < need) cap *= 2;
    int *p = realloc(v->data, cap * sizeof *p);
    if (!p) return 0;
    v->data = p;
    v->cap = cap;
    return 1;
}

static int vec_push(Vec *v, int x) {
    if (!vec_reserve(v, v->len + 1)) return 0;
    v->data[v->len++] = x;
    return 1;
}

static void vec_free(Vec *v) {
    free(v->data);
    v->data = NULL;
    v->len = v->cap = 0;
}

int main(void) {
    Vec v = {0};
    for (int i = 0; i < 1000; ++i) {
        assert(vec_push(&v, i));
    }
    assert(v.len == 1000);
    assert(v.data[0] == 0 && v.data[999] == 999);
    vec_free(&v);
    assert(v.data == NULL && v.len == 0);
    puts("ok");
    return 0;
}
```

`vec_reserve` doubles capacity starting from 4 and returns 0 on allocation failure rather than aborting, so callers can handle OOM. Initial capacity is 0, and `realloc(NULL, ...)` behaves like `malloc`. `vec_free` resets fields to zero, making double-free on a cleared struct a no-op.

