#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define CAP 1024
#define MAX_WORD 64

typedef struct { char key[MAX_WORD]; unsigned count; } Entry;

static unsigned hash(const char *s) {
    unsigned h = 2166136261u;
    for (; *s; ++s) h = (h ^ (unsigned char)*s) * 16777619u;
    return h;
}

static Entry table[CAP];

static void add(const char *w) {
    unsigned i = hash(w) & (CAP - 1);
    while (table[i].count && strcmp(table[i].key, w) != 0)
        i = (i + 1) & (CAP - 1);
    if (!table[i].count) snprintf(table[i].key, MAX_WORD, "%s", w);
    table[i].count++;
}

int main(void) {
    char word[MAX_WORD];
    int ch, n = 0;
    while ((ch = getchar()) != EOF) {
        if (isalpha((unsigned char)ch) || ch == '\'') {
            if (n < MAX_WORD - 1) word[n++] = (char)tolower((unsigned char)ch);
        } else if (n) {
            word[n] = '\0';
            add(word);
            n = 0;
        }
    }
    if (n) { word[n] = '\0'; add(word); }
    for (unsigned i = 0; i < CAP; ++i)
        if (table[i].count) printf("%u %s\n", table[i].count, table[i].key);
    return 0;
}
