```cpp
#include <condition_variable>
#include <iostream>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(size_t cap) : cap_(cap) {}

    void push(int v) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [&] { return q_.size() < cap_; });
        q_.push(v);
        lk.unlock();
        not_empty_.notify_one();
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [&] { return !q_.empty(); });
        int v = q_.front();
        q_.pop();
        lk.unlock();
        not_full_.notify_one();
        return v;
    }

private:
    size_t cap_;
    std::queue<int> q_;
    std::mutex m_;
    std::condition_variable not_full_, not_empty_;
};

int main() {
    BoundedQueue q(2);
    q.push(1);
    q.push(2);
    auto a = q.pop();
    q.push(3);
    auto b = q.pop();
    auto c = q.pop();
    if (!a || !b || !c || *a != 1 || *b != 2 || *c != 3) {
        std::cerr << "queue order broken\n";
        return 1;
    }
    std::cout << "queue ok\n";
    return 0;
}
```
The predicate form of `wait` guards against spurious wakeups, and the lock is released before notifying.

