```rust
use std::cmp::Ordering;

pub fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            Ordering::Less => lo = mid + 1,
            Ordering::Greater => hi = mid,
            Ordering::Equal => return Some(mid),
        }
    }
    None
}

fn main() {
    let data = [1, 3, 5, 7, 9, 11];
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &11), Some(5));
    assert_eq!(binary_search(&data, &6), None);

    let empty: [i32; 0] = [];
    assert_eq!(binary_search(&empty, &3), None);

    let words = ["ant", "bee", "cow"];
    assert_eq!(binary_search(&words, &"bee"), Some(1));
    println!("ok");
}
```

`mid = lo + (hi - lo) / 2` avoids overflow, the half-open `[lo, hi)` range keeps the loop termination clean, and an empty slice returns `None`.

