    i = 0
    while i < len(code):
        ch = code[i]
        i += 1
        num = []
        while i < len(code) and code[i].isdigit():
            num.append(code[i])
            i += 1
        out.append(ch * (int("".join(num)) if num else 1))
    return "".join(out)


