```c
#include <stdio.h>
#include <stdlib.h>

static int cmp_ints(const void* a, const void* b) {
    int x = *(const int*)a;
    int y = *(const int*)b;
    /* Subtracting can overflow; compare instead. */
    return (x > y) - (x < y);
}

int main(void) {
    int values[] = {42, -7, 0, 42, 13, -7, 100};
    size_t n = sizeof(values) / sizeof(values[0]);

    qsort(values, n, sizeof(values[0]), cmp_ints);

    for (size_t i = 0; i < n; ++i) {
        printf("%d%s", values[i], i + 1 == n ? "\n" : " ");
    }

    /* Zero elements is a legal, no-op sort. */
    qsort(values, 0, sizeof(values[0]), cmp_ints);
    return 0;
}
```

The comparator uses the `(x > y) - (x < y)` idiom to dodge signed overflow, and `qsort` with a count of 0 is explicitly allowed.

