        if (value < lo) lo = value;
        if (value > hi) hi = value;
        sum += value;
        ++count;
    }

    if (!any) {
        std::cout << "no input\n";
        return 0;
    }
    std::cout << "min=" << lo << " max=" << hi
              << " mean=" << static_cast<double>(sum) / count << '\n';
    return 0;
}
```

The `any` flag avoids printing garbage sentinels for empty input — without it, `lo` would still hold `LLONG_MAX`. Summing into a `long long` and dividing only at the end keeps integer precision until the final cast to `double`.

```rust
fn parse_duration(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err("empty duration".to_string());
    }
    let mut total: u64 = 0;
    let mut num = String::new();
    let mut saw_unit = false;

    for ch in s.chars() {
        if ch.is_ascii_digit() {
            num.push(ch);
        } else {
            let n: u64 = num
                .parse()
                .map_err(|_| format!("missing number before '{ch}'"))?;
            let mult = match ch {
                'h' => 3600,
                'm' => 60,
                's' => 1,
                _ => return Err(format!("unknown unit '{ch}'")),
            };
            total = total
                .checked_add(n.checked_mul(mult).ok_or("overflow")?)
                .ok_or("overflow")?;
            num.clear();
            saw_unit = true;
        }
    }

    if !num.is_empty() {
        return Err(format!("trailing number '{num}' without unit"));
    }
    if !saw_unit {
        return Err("no unit found".to_string());
    }
    Ok(total)
}

fn main() {
    for s in ["1h30m", "45s", "2h", "", "10x", "5m30"] {
        println!("{s:>6} -> {parse_duration(s):?}");
    }
}
```

`checked_mul`/`checked_add` make overflow an error instead of a panic or wrap. The trailing-digit check catches "5m30", and an empty string is rejected before the loop so the error messages stay precise.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict[str, int] = OrderedDict()

    def get(self, key: str) -> int | None:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: str, value: int) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    print(c.get("a"))   # 1
    c.put("c", 3)        # evicts b
    print(c.get("b"))    # None
    print(c.get("c"))    # 3
```

`OrderedDict` gives O(1) `move_to_end` and `popitem(last=False)`, so both operations are constant time. `get` returns `None` for a miss, and the capacity guard rejects a zero or negative size up front.

