#include <iostream>
#include <string>
#include <vector>

std::string reverse_utf8(const std::string& in) {
    std::vector<std::string> chars;
    for (std::size_t i = 0; i < in.size();) {
        unsigned char c = static_cast<unsigned char>(in[i]);
        std::size_t len = 1;
        if ((c & 0x80) == 0x00) len = 1;
        else if ((c & 0xE0) == 0xC0) len = 2;
        else if ((c & 0xF0) == 0xE0) len = 3;
        else if ((c & 0xF8) == 0xF0) len = 4;
        if (i + len > in.size()) break;          // truncated tail byte
        chars.push_back(in.substr(i, len));
        i += len;
    }
    std::string out;
    for (auto it = chars.rbegin(); it != chars.rend(); ++it)
        out += *it;
    return out;
}

int main() {
    std::string s = "a\xC3\xA9\xE2\x82\xACb"; // a é € b
    std::string r = reverse_utf8(s);
    std::cout << r << '\n';
    return 0;
}
```

The lead-byte mask decides how many continuation bytes belong to each code point, so multi-byte characters stay intact. A truncated trailing sequence is dropped via the bounds check rather than reading past `size()`. Note this does not reorder combining marks – that needs grapheme segmentation.

