```c
#include <stdio.h>
#include <string.h>

/* Copies src into dst of capacity cap, always NUL-terminates.
   Returns the number of characters copied (excluding NUL). */
size_t safe_copy(char *dst, size_t cap, const char *src) {
    if (dst == NULL || src == NULL || cap == 0) {
        return 0;
    }
    size_t n = 0;
    while (n + 1 < cap && src[n] != '\0') {
        dst[n] = src[n];
        ++n;
    }
    dst[n] = '\0';
    return n;
}

int main(void) {
    char buf[8];
    const char *tests[] = {"hi", "exactly", "way too long for this buffer"};

    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); ++i) {
        size_t n = safe_copy(buf, sizeof(buf), tests[i]);
        printf("copied %zu: \"%s\"\n", n, buf);
    }
    return 0;
}
```

The loop stops at `cap - 1` so there is always room for the terminator, and `dst[n] = '\0'` runs on every path that has a buffer. The guard clause covers a NULL pointer or zero capacity, both of which would otherwise be undefined behaviour. Truncation is reported via the return value rather than being hidden.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    tests = ["", "a", "babad", "cbbd", "forgeeksskeegfor", "ñooñ"]
    for t in tests:
        print(repr(t), "->", repr(longest_palindrome(t)))
```

Expand-around-center, O(n^2) time and O(1) extra space. Odd and even centers are both checked; ties keep the earliest occurrence. The unicode case works because indexing is per code point, not byte.

