#include <cstddef>
#include <iostream>
#include <vector>

std::vector<int> merge_sorted(const std::vector<int>& a,
                              const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        // Take from a when equal so the merge is stable.
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5};
    std::vector<int> b{2, 3, 6};
    for (int v : merge_sorted(a, b)) std::cout << v << ' ';
    std::cout << '\n';

    // Empty-input cases.
    std::vector<int> empty;
    std::cout << merge_sorted(empty, b).size() << '\n';
    std::cout << merge_sorted(a, empty).size() << '\n';
    std::cout << merge_sorted(empty, empty).size() << '\n';
    return 0;
}
```

`reserve` avoids repeated reallocation; each element is pushed exactly once, so it is O(n + m). Equal elements take from `a` first, which keeps the merge stable.

