#include <iostream>
#include <stdexcept>

class FixedStack {
public:
    explicit FixedStack(std::size_t capacity)
        : data_(new int[capacity]), cap_(capacity), size_(0) {}

    ~FixedStack() { delete[] data_; }
    FixedStack(const FixedStack&) = delete;
    FixedStack& operator=(const FixedStack&) = delete;

    void push(int value) {
        if (size_ == cap_) throw std::overflow_error("stack full");
        data_[size_++] = value;
    }

    int pop() {
        if (empty()) throw std::underflow_error("stack empty");
        return data_[--size_];
    }

    int top() const {
        if (empty()) throw std::underflow_error("stack empty");
        return data_[size_ - 1];
    }

    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    int* data_;
    std::size_t cap_;
    std::size_t size_;
};

int main() {
    FixedStack s(3);
    s.push(10);
    s.push(20);
    std::cout << s.top() << '\n';   // 20
    std::cout << s.pop() << '\n';   // 20
    std::cout << s.size() << '\n';  // 1
    try {
        FixedStack small(0);
        small.pop();
    } catch (const std::exception& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
