```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) return std::nullopt;
        double value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool full() const { return size_ == N; }
    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1.5);
    rb.push(2.5);
    std::cout << rb.pop().value_or(-1) << '\n';
    return 0;
}
```

`push` returns false when full instead of overwriting, and `pop` returns `std::nullopt` when empty, so neither call can corrupt state. `head_` advances modulo N, and `size_` distinguishes a full buffer from an empty one even though both have `head_` equal to the tail. No dynamic allocation, so N is fixed at compile time.

