def normalize_ipv4(text):
    """Return the canonical dotted form of an IPv4 string, or None."""
    parts = text.split(".")
    if len(parts) != 4:
        return None
    numbers = []
    for part in parts:
        if not part.isdigit() or not part.isascii():
            return None
        value = int(part)
        if value > 255:
            return None
        numbers.append(value)
    return ".".join(str(n) for n in numbers)


if __name__ == "__main__":
    assert normalize_ipv4("192.168.000.1") == "192.168.0.1"
    assert normalize_ipv4("10.0.0") is None
    assert normalize_ipv4("256.1.1.1") is None
    assert normalize_ipv4("1.1.1.1a") is None
    print("ok")
```

