#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (data[mid] == target) return mid;
        if (data[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> data = {2, 4, 6, 8, 10, 12, 14};
    for (int target : {2, 14, 7, 0, 99}) {
        int idx = binary_search(data, target);
        if (idx >= 0) std::cout << target << " found at " << idx << '\n';
        else std::cout << target << " not found\n";
    }
    std::vector<int> empty;
    std::cout << "empty: " << binary_search(empty, 1) << '\n';
    return 0;
}
