```cpp
#include <array>
#include <cstddef>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : capacity_(capacity) {
        data_.resize(capacity);
    }

    bool push(int value) {
        if (size_ == capacity_) {
            return false;
        }
        data_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        int value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == capacity_; }
    std::size_t size() const { return size_; }

private:
    std::vector<int> data_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};
```

`pop` returns `std::optional<int>`, so a full buffer and an empty buffer stay distinguishable without sentinel values. The modulo arithmetic wraps indices without ever shifting elements.

