#include <ctype.h>
#include <stdio.h>
#include <string.h>

static void reverse_range(char *s, size_t lo, size_t hi) {
    while (lo < hi) {
        char t = s[lo];
        s[lo] = s[hi];
        s[hi] = t;
        ++lo;
        --hi;
    }
}

void reverse_words(char *s) {
    size_t n = strlen(s);
    if (n == 0) {
        return;
    }
    reverse_range(s, 0, n - 1);

    size_t i = 0;
    while (i < n) {
        while (i < n && isspace((unsigned char)s[i])) {
            ++i;
        }
        size_t start = i;
        while (i < n && !isspace((unsigned char)s[i])) {
            ++i;
        }
        if (start < i) {
            reverse_range(s, start, i - 1);
        }
    }
}

int main(void) {
    char buf[] = "  hello   world  from c ";
    reverse_words(buf);
    printf("[%s]\n", buf);
    return 0;
}
