#include <functional>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;
    std::priority_queue<int, std::vector<int>, std::greater<int>> high;
    double median = 0.0;

    int value;
    while (std::cin >> value) {
        if (low.empty() || value <= low.top()) {
            low.push(value);
        } else {
            high.push(value);
        }

        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        if (low.size() == high.size()) {
            median = (low.top() + high.top()) / 2.0;
        } else {
            median = low.top();
        }
        std::cout << median << '\n';
    }
    return 0;
}
```

`low` is a max-heap holding the smaller half, `high` a min-heap holding the larger half. Rebalancing after every insert keeps their sizes within one, so the median is always at the top of one heap or the average of both tops.

