#include <algorithm>
#include <iostream>
#include <string>

// Reverse the order of whitespace-separated words in `s` in place.
void reverseWords(std::string& s) {
    std::reverse(s.begin(), s.end());

    std::size_t n = s.size();
    std::size_t start = 0;
    while (start < n) {
        std::size_t end = start;
        while (end < n && s[end] != ' ') ++end;
        std::reverse(s.begin() + start, s.begin() + end);
        start = end + 1; // skip the space
    }
}

int main() {
    std::string a = "the quick brown fox";
    reverseWords(a);
    std::cout << a << '\n'; // fox brown quick the

    std::string b = "hello";
    reverseWords(b);
    std::cout << b << '\n'; // hello

    std::string c = "";
    reverseWords(c);
    std::cout << '[' << c << "]\n"; // []

    std::string d = "  spaced   out  ";
    reverseWords(d);
    std::cout << '[' << d << "]\n"; // [  out   spaced  ]

    return 0;
}
```

