                ++words;
            }
        }
        fclose(fp);

        printf("%7lu %7lu %7lu %s\n", lines, words, chars, argv[i]);
        total_lines += lines;
        total_words += words;
        total_chars += chars;
    }

    if (argc > 2) {
        printf("%7lu %7lu %7lu total\n", total_lines, total_words, total_chars);
    }
    return 0;
}
