int main(int argc, char **argv) {
    int n = argc - 1;
    if (n <= 0) {
        fprintf(stderr, "usage: reverse <int> [int ...]\n");
        return 2;
    }
    int *a = malloc((size_t)n * sizeof *a);
    if (!a) {
        perror("malloc");
        return 1;
    }
    for (int i = 0; i < n; i++) {
        char *end;
        errno = 0;
        long v = strtol(argv[i + 1], &end, 10);
        if (errno != 0 || *end != '\0' || end == argv[i + 1]) {
            fprintf(stderr, "not an integer: %s\n", argv[i + 1]);
            free(a);
            return 2;
        }
        a[i] = (int)v;
    }
    for (int i = 0, j = n - 1; i < j; i++, j--) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
    for (int i = 0; i < n; i++) {
        printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');
    }
    free(a);
    return 0;
}
