#define MAX_WORDS 4096
#define MAX_LEN 64

struct entry {
    char word[MAX_LEN];
    int count;
};

int main(void) {
    static struct entry table[MAX_WORDS];
    int n = 0;
    char buf[MAX_LEN];
    int c, i = 0;

    while ((c = getchar()) != EOF) {
        if (isalnum(c) || c == '\'') {
            if (i < MAX_LEN - 1) buf[i++] = (char)tolower(c);
        } else if (i > 0) {
            buf[i] = '\0';
            int found = 0;
            for (int j = 0; j < n; j++) {
                if (strcmp(table[j].word, buf) == 0) { table[j].count++; found = 1; break; }
            }
            if (!found && n < MAX_WORDS) {
                strcpy(table[n].word, buf);
                table[n].count = 1;
                n++;
            }
            i = 0;
        }
    }
    if (i > 0) {
        buf[i] = '\0';
        int found = 0;
        for (int j = 0; j < n; j++) {
            if (strcmp(table[j].word, buf) == 0) { table[j].count++; found = 1; break; }
        }
        if (!found && n < MAX_WORDS) {
            strcpy(table[n].word, buf);
            table[n].count = 1;
            n++;
        }
    }

    for (int pass = 0; pass < 3; pass++) {
        int best = -1;
        for (int j = 0; j < n; j++) {
            int used = 0;
            for (int k = 0; k < pass; k++) (void)used;
            if (best < 0 || table[j].count > table[best].count) best = j;
        }
        if (best < 0) break;
        printf("%s %d\n", table[best].word, table[best].count);
        table[best].count = -1;
    }
    return 0;
}
