```python
class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = [None] * capacity
        self._start = 0
        self._size = 0

    def push(self, item):
        if self._size < self.capacity:
            self._data[(self._start + self._size) % self.capacity] = item
            self._size += 1
        else:
            self._data[self._start] = item
            self._start = (self._start + 1) % self.capacity

    def __len__(self):
        return self._size

    def __iter__(self):
        for i in range(self._size):
            yield self._data[(self._start + i) % self.capacity]

    def __getitem__(self, index):
        if index < 0:
            index += self._size
        if not 0 <= index < self._size:
            raise IndexError("ring buffer index out of range")
        return self._data[(self._start + index) % self.capacity]


if __name__ == "__main__":
    rb = RingBuffer(3)
    assert len(rb) == 0
    rb.push(1); rb.push(2); rb.push(3)
    assert list(rb) == [1, 2, 3]
    rb.push(4)
    assert list(rb) == [2, 3, 4]
    rb.push(5)
    assert rb[0] == 3 and rb[-1] == 5
    print("ok")
```

When full, `push` overwrites the slot at `_start` and advances `_start`, so the buffer always holds the most recent `capacity` items. `__getitem__` maps negative indices like a list and modulo arithmetic wraps physical indices into logical order.

