#include <iostream>
#include <optional>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(size_t capacity) : buf_(capacity), capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool push(double v) {
        if (size_ == capacity_) return false;
        buf_[(head_ + size_) % capacity_] = v;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) return std::nullopt;
        double v = buf_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return v;
    }

    size_t size() const { return size_; }

private:
    std::vector<double> buf_;
    size_t capacity_, head_ = 0, size_ = 0;
};

int main() {
    RingBuffer rb(3);
    for (double d : {1.0, 2.0, 3.0}) std::cout << rb.push(d) << ' ';
    std::cout << rb.push(4.0) << '\n';
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n';
}
