use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum BracketError {
    UnmatchedCloser(char),
    Unclosed(char),
    Invalid(char),
}

pub fn is_balanced(input: &str) -> Result<(), BracketError> {
    let pairs: HashMap<char, char> =
        [(')', '('), (']', '['), ('}', '{')].into_iter().collect();
    let mut stack: Vec<char> = Vec::new();

    for c in input.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => match stack.pop() {
                Some(open) if open == pairs[&c] => {}
                Some(_) => return Err(BracketError::UnmatchedCloser(c)),
                None => return Err(BracketError::UnmatchedCloser(c)),
            },
            other => return Err(BracketError::Invalid(other)),
        }
    }

    match stack.last() {
        Some(&open) => Err(BracketError::Unclosed(open)),
        None => Ok(()),
    }
}

fn main() {
    assert_eq!(is_balanced(""), Ok(()));
    assert_eq!(is_balanced("{[()]}"), Ok(()));
    assert_eq!(is_balanced("([)]"), Err(BracketError::UnmatchedCloser(')')));
    assert_eq!(is_balanced("(("), Err(BracketError::Unclosed('(')));
    assert_eq!(is_balanced("a"), Err(BracketError::Invalid('a')));
    println!("all assertions passed");
}
```

Run with `cargo run` or `rustc solution.rs -o solution && ./solution`. An empty string is balanced, so the `Vec::new()` stack plus the `None` arm handles it; mismatched closers report the offending character instead of panicking.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *reverse_iterative(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *reverse_recursive(Node *head) {
    if (head == NULL || head->next == NULL) {
        return head;
    }
    Node *new_head = reverse_recursive(head->next);
    head->next->next = head;
    head->next = NULL;
    return new_head;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static void print_list(const char *label, Node *head) {
    printf("%s", label);
    for (Node *cur = head; cur != NULL; cur = cur->next) {
        printf("%d%s", cur->value, cur->next ? " -> " : "\n");
    }
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 4; i >= 1; --i) {
        head = push(head, i);
    }
    print_list("original:  ", head);
    head = reverse_iterative(head);
    print_list("iterative: ", head);
    head = reverse_recursive(head);
    print_list("recursive: ", head);
    free_list(head);
    return 0;
}
