```cpp
#include <iostream>
#include <cstdint>
#include <limits>

// Returns floor(log10(n)) for n >= 1, and -1 for n == 0.
int log10_floor(uint64_t n) {
    if (n == 0) return -1;  // logarithm is undefined; caller decides how to treat it

    int lo = 0, hi = 19;  // 10^19 fits in uint64_t
    while (lo < hi) {
        int mid = lo + (hi - lo + 1) / 2;
        uint64_t power = 1;
        for (int i = 0; i < mid; ++i) power *= 10;
        if (power <= n) {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }
    return lo;
}

int main() {
    struct Case { uint64_t n; int expected; };
    const Case cases[] = {
        {0, -1}, {1, 0}, {9, 0}, {10, 1}, {99, 1}, {100, 2},
        {999, 2}, {1000, 3}, {9999999999ULL, 9},
        {std::numeric_limits<uint64_t>::max(), 19},
    };
    bool ok = true;
    for (const auto& c : cases) {
        int got = log10_floor(c.n);
        if (got != c.expected) {
            std::cerr << "FAIL n=" << c.n << " got=" << got
                      << " expected=" << c.expected << "\n";
            ok = false;
        }
    }
    std::cout << (ok ? "all tests passed" : "failures above") << "\n";
    return ok ? 0 : 1;
}
```

Searching on the exponent `k` with the predicate `10^k <= n` is monotone, so binary search over `[0, 19]` is correct. The `mid = lo + (hi - lo + 1) / 2` form is the upper-biased midpoint that avoids an infinite loop when `lo` and `hi` are adjacent; `n == 0` is special-cased to `-1`.

