#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    size_t i = 0, j = len ? len - 1 : 0;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        if (j == 0) break;
        j--;
    }
}

