    char a[] = "hello";     /* 5 -> "olleh" */
    char b[] = "ab";        /* 2 -> "ba" */
    char c[] = "";          /* empty stays empty */
    char d[] = "x";         /* single char */

    reverse_in_place(a);
    reverse_in_place(b);
    reverse_in_place(c);
    reverse_in_place(d);

    printf("%s\n%s\n%s\n%s\n", a, b, c, d);
    return 0;
}
