```python
def flat_index(shape, index):
    """Return the row-major flat offset for index into an array of shape.

    Raises ValueError on rank mismatch or out-of-bounds coordinates.
    """
    if len(shape) != len(index):
        raise ValueError(
            f'rank mismatch: shape has {len(shape)} dims, index has {len(index)}'
        )
    if any(dim < 0 for dim in shape):
        raise ValueError(f'negative dimension in shape {shape}')

    offset = 0
    for coord, dim in zip(index, shape):
        if not 0 <= coord < dim:
            raise ValueError(f'index {coord} out of range for dim size {dim}')
        offset = offset * dim + coord
    return offset


if __name__ == '__main__':
    assert flat_index((3,), (0,)) == 0
    assert flat_index((3,), (2,)) == 2
    assert flat_index((2, 3), (0, 2)) == 2
    assert flat_index((2, 3), (1, 0)) == 3
    assert flat_index((2, 3, 4), (1, 2, 3)) == 1 * 12 + 2 * 4 + 3

    for bad in [((2, 3), (0,)), ((2, 3), (2, 0)), ((2, 3), (0, -1)), ((2, 3, 4), (1, 4, 0))]:
        try:
            flat_index(*bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f'expected ValueError for {bad}')

    print('all checks passed')
```

Row-major offset is `((i0 * d1 + i1) * d2 + i2) ...`, which the loop builds incrementally. Bounds checks run per coordinate before each multiply, so negative coordinates and coordinates equal to the dimension size are both rejected. Rank is validated before any arithmetic to avoid silently zipping mismatched tuples.

```c
#include <stdio.h>

unsigned long long trailing_zeroes(unsigned long long n) {
    unsigned long long count = 0;
    for (unsigned long long p = 5; p <= n; p *= 5) {
        count += n / p;
        if (p > n / 5) break; /* avoid p *= 5 overflow */
    }
    return count;
}

int main(void) {
    unsigned long long cases[] = {0ULL, 5ULL, 100ULL};
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
        printf("%llu! -> %llu trailing zeroes\n",
               cases[i], trailing_zeroes(cases[i]));
    }
    return 0;
}
```

Each trailing zero comes from a factor of 10, and factors of 2 always outnumber factors of 5, so counting `floor(n/5) + floor(n/25) + ...` suffices. For n=100 that is 20 + 4 + 0 = 24. The `p > n / 5` guard stops the loop before `p *= 5` could overflow.

```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[], &[1, 2]), vec![1, 2]);
    assert_eq!(merge_sorted(&[1, 3, 3], &[2, 3, 4]), vec![1, 2, 3, 3, 3, 4]);
    assert_eq!(merge_sorted(&[-5, 0], &[-10, 10]), vec![-10, -5, 0, 10]);

    println!("{:?}", merge_sorted(&[1, 4, 9], &[2, 3, 10]));
}
```

`<=` on the first slice keeps the merge stable and preserves duplicates. Once either slice is exhausted the remaining tail is already sorted, so `extend_from_slice` appends it in one pass. Time is O(m+n) with no extra comparisons beyond the two pointers.

