T dot_product(const std::vector<T>& a, const std::vector<T>& b) {
    if (a.size() != b.size()) {
        throw std::invalid_argument(
            "dot_product: size mismatch (" + std::to_string(a.size()) +
            " vs " + std::to_string(b.size()) + ")");
