```cpp
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

std::string longest_common_prefix(const std::vector<std::string>& strs) {
    if (strs.empty()) return "";
    std::string prefix = strs[0];
    for (size_t i = 1; i < strs.size(); ++i) {
        size_t j = 0;
        while (j < prefix.size() && j < strs[i].size()
               && prefix[j] == strs[i][j]) {
            ++j;
        }
        prefix.resize(j);
        if (prefix.empty()) break;
    }
    return prefix;
}

int main() {
    std::vector<std::string> a{"flower", "flow", "flight"};
    std::vector<std::string> b{"dog", "racecar", "car"};
    std::vector<std::string> c{};
    std::cout << longest_common_prefix(a) << '\n';
    std::cout << longest_common_prefix(b) << '\n';
    std::cout << longest_common_prefix(c) << '\n';
    return 0;
}
```

Start with the first string as the candidate prefix and shrink it against each subsequent string character by character. `resize(j)` trims to the first mismatch, and an early break once the prefix is empty keeps it linear-ish. The empty vector returns `""`, so `main` prints a blank line for case `c` exactly as specified.

