#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

    // Oldest element first, newest last.
    std::optional<T> get(std::size_t i) const {
        if (i >= size_) return std::nullopt;
        std::size_t start = (head_ + N - size_) % N;
        return data_[(start + i) % N];
    }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

#include <cassert>
#include <iostream>

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    assert(rb.size() == 3);
    rb.push(4);  // overwrites 1
    assert(rb.size() == 3);
    assert(rb.get(0) == 2 && rb.get(2) == 4);
    assert(!rb.get(3).has_value());
    std::cout << "ok\n";
}
