#include <cassert>
#include <iostream>

struct Node {
    int value;
    Node* next;
};

bool has_cycle(const Node* head) {
    const Node* slow = head;
    const Node* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

int main() {
    Node a{1, nullptr};
    Node b{2, nullptr};
    Node c{3, nullptr};
    a.next = &b;
    b.next = &c;
    assert(!has_cycle(&a));

    c.next = &a;  // create a cycle
    assert(has_cycle(&a));

    assert(!has_cycle(nullptr));
    std::cout << "ok\n";
}
```

Floyd's tortoise-and-hare: O(1) space, O(n) time. The loop exits safely when `fast` or `fast->next` is null.

