#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
    std::array<T, N> buf_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
public:
    bool push(const T& value) {
        if (size_ == N) return false;
        buf_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool full() const { return size_ == N; }
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << '\n';
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n' << "empty: " << !rb.pop().has_value() << '\n';
}
