Pushing onto a full buffer returns `false` instead of overwriting; popping an empty buffer returns `std::nullopt` via `std::optional`, so no undefined behaviour on underflow.

```c
#include <stdio.h>
#include <stdlib.h>

#define MAXN 1000000

static int maxh[MAXN];
static int minh[MAXN];
static int maxn = 0, minn = 0;

static void max_push(int v) {
    int i = maxn++;
    maxh[i] = v;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (maxh[p] >= maxh[i]) break;
        int t = maxh[p]; maxh[p] = maxh[i]; maxh[i] = t;
        i = p;
    }
}

static int max_pop(void) {
    int top = maxh[0];
    maxh[0] = maxh[--maxn];
    int i = 0;
    for (;;) {
        int l = 2 * i + 1, r = l + 1, big = i;
        if (l < maxn && maxh[l] > maxh[big]) big = l;
        if (r < maxn && maxh[r] > maxh[big]) big = r;
        if (big == i) break;
        int t = maxh[big]; maxh[big] = maxh[i]; maxh[i] = t;
        i = big;
    }
    return top;
}

static void min_push(int v) {
    int i = minn++;
    minh[i] = v;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (minh[p] <= minh[i]) break;
        int t = minh[p]; minh[p] = minh[i]; minh[i] = t;
        i = p;
    }
}

static int min_pop(void) {
    int top = minh[0];
    minh[0] = minh[--minn];
    int i = 0;
    for (;;) {
        int l = 2 * i + 1, r = l + 1, small = i;
        if (l < minn && minh[l] < minh[small]) small = l;
        if (r < minn && minh[r] < minh[small]) small = r;
        if (small == i) break;
        int t = minh[small]; minh[small] = minh[i]; minh[i] = t;
        i = small;
    }
    return top;
}

int main(void) {
    int v;
    long long count = 0;
    while (scanf("%d", &v) == 1) {
        if (maxn == 0 || v <= maxh[0]) max_push(v);
        else min_push(v);

        if (maxn > minn + 1) min_push(max_pop());
        else if (minn > maxn) max_push(min_pop());

        count++;
        if (maxn > minn) {
            printf("%d\n", maxh[0]);
        } else {
            /* integer-safe average of two ints */
            long long a = maxh[0], b = minh[0];
            long long s = a + b;
            if (s % 2 == 0) printf("%lld\n", s / 2);
            else printf("%lld.5\n", s / 2);
        }
    }
    if (count == 0) fprintf(stderr, "no input\n");
    return count == 0 ? 1 : 0;
}
```

The max-heap holds the lower half, the min-heap the upper half, rebalanced after each insert so their sizes differ by at most one. Reads until EOF; empty input exits with status 1 and a message on stderr. The average avoids overflow by summing as `long long` and prints `.5` when the sum is odd.

```cpp
#include <condition_variable>
#include <iostream>
#include <mutex>
#include <optional>
#include <queue>
#include <thread>
#include <vector>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    void push(T value) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [&] { return closed_ || q_.size() < cap_; });
        if (closed_) return;
        q_.push(std::move(value));
        lk.unlock();
        not_empty_.notify_one();
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;  // closed and drained
        T v = std::move(q_.front());
        q_.pop();
        lk.unlock();
        not_full_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lk(m_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<T> q_;
    std::mutex m_;
    std::condition_variable not_full_, not_empty_;
    bool closed_ = false;
};

int main() {
    constexpr int kItems = 1000;
    BoundedQueue<int> q(16);
    std::atomic<int> produced{0};
    std::mutex out_m;

    std::thread producer([&] {
        for (int i = 0; i < kItems; ++i) {
            q.push(i);
            ++produced;
        }
    });

    std::vector<std::thread> consumers;
    std::atomic<int> sum{0};
    for (int c = 0; c < 4; ++c) {
        consumers.emplace_back([&] {
            while (auto v = q.pop()) sum += *v;
        });
    }

    producer.join();
    q.close();
    for (auto& t : consumers) t.join();

    int expected = kItems * (kItems - 1) / 2;
    std::cout << "produced=" << produced.load() << " sum=" << sum.load()
              << " expected=" << expected << '\n';
    return sum.load() == expected ? 0 : 1;
}
```

`push` blocks while full and returns early if closed; `pop` returns `std::nullopt` once the queue is closed and drained, which lets each consumer loop terminate. `close()` wakes all waiters. The demo checks the sum of 0..999 against the closed-form result and exits non-zero on mismatch.

