use std::collections::HashMap;
use std::fs;
use std::path::Path;

#[derive(Debug, PartialEq)]
pub enum ConfigError {
    Io(String),
    Parse { line: usize, msg: String },
}

#[derive(Debug, Clone)]
pub struct Config {
    pub values: HashMap<String, String>,
}

impl Config {
    pub fn with_defaults() -> Self {
        let mut values = HashMap::new();
        values.insert("host".to_string(), "localhost".to_string());
        values.insert("port".to_string(), "8080".to_string());
        Config { values }
    }

    pub fn get(&self, key: &str) -> Option<&str> {
        self.values.get(key).map(String::as_str)
    }

    pub fn parse_str(input: &str) -> Result<HashMap<String, String>, ConfigError> {
        let mut out = HashMap::new();
        for (i, raw) in input.lines().enumerate() {
            let line_no = i + 1;
            let line = raw.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let Some((key, value)) = line.split_once('=') else {
                return Err(ConfigError::Parse {
                    line: line_no,
                    msg: "missing '='".to_string(),
                });
            };
            let key = key.trim();
            if key.is_empty() {
                return Err(ConfigError::Parse {
                    line: line_no,
                    msg: "empty key".to_string(),
                });
            }
            out.insert(key.to_string(), value.trim().to_string());
        }
        Ok(out)
    }

    pub fn load(path: &Path) -> Result<Config, ConfigError> {
        let text = fs::read_to_string(path)
            .map_err(|e| ConfigError::Io(format!("{}: {e}", path.display())))?;
        let mut cfg = Config::with_defaults();
        for (k, v) in Config::parse_str(&text)? {
            cfg.values.insert(k, v);
        }
        Ok(cfg)
    }
}

fn main() {
    let sample = "# defaults\nhost = example.com\nport=9090\ntimeout = 30s\n";
    match Config::parse_str(sample) {
        Ok(pairs) => {
            let mut cfg = Config::with_defaults();
            for (k, v) in pairs {
                cfg.values.insert(k, v);
            }
            println!("host={:?} port={:?}", cfg.get("host"), cfg.get("port"));
        }
        Err(ConfigError::Parse { line, msg }) => eprintln!("parse error on line {line}: {msg}"),
        Err(ConfigError::Io(e)) => eprintln!("io error: {e}"),
    }

    // Malformed line reports the exact line number.
    assert!(matches!(
        Config::parse_str("a=1\nbroken\n"),
        Err(ConfigError::Parse { line: 2, .. })
    ));
    println!("ok");
}
```

Blank lines and `#` comments are skipped, keys and values are trimmed, and a missing `=` fails with the offending line number. `load` overlays parsed pairs onto the default map, so unspecified keys keep their defaults.

```python
from collections import OrderedDict


class LRUCache:
    """O(1) get/put LRU using an OrderedDict as a dict+linked-list."""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.cap = capacity
        self.data: "OrderedDict[int, int]" = OrderedDict()

    def get(self, key: int) -> int:
        if key not in self.data:
            return -1
        self.data.move_to_end(key)
        return self.data[key]

    def put(self, key: int, value: int) -> None:
        if key in self.data:
            self.data.move_to_end(key)
        self.data[key] = value
        if len(self.data) > self.cap:
            self.data.popitem(last=False)  # evict least-recently used


class BruteLRU:
    """Reference: plain list of keys in recency order."""

    def __init__(self, capacity: int):
        self.cap = capacity
        self.store = {}

    def get(self, key: int) -> int:
        if key not in self.store:
            return -1
        self.store[key] = self.store.pop(key)  # refresh recency
        return self.store[key]

    def put(self, key: int, value: int) -> None:
        self.store.pop(key, None)
        self.store[key] = value
        if len(self.store) > self.cap:
            del self.store[next(iter(self.store))]


def run(cache_cls, ops):
    c = cache_cls(2)
    return [c.get(k) if op == "g" else c.put(k, v) for op, k, v in ops]


if __name__ == "__main__":
    ops = [("p", 1, 1), ("p", 2, 2), ("g", 1, 0), ("p", 3, 3),
           ("g", 2, 0), ("p", 4, 4), ("g", 1, 0), ("g", 3, 0), ("g", 4, 0)]
    fast = LRUCache(2)
    slow = BruteLRU(2)
    for op, k, v in ops:
        if op == "p":
            fast.put(k, v)
            slow.put(k, v)
        else:
            assert fast.get(k) == slow.get(k), (op, k)

    # The canonical LeetCode sequence: expect -1, -1, 3, 4
    checks = [fast.get(2), fast.get(1), fast.get(3), fast.get(4)]
    assert checks == [-1, -1, 3, 4], checks
    print("all checks passed", checks)
```

Each `get` moves the key to the most-recent end; `put` refreshes recency and evicts from the front with `popitem(last=False)`. The brute-force cache uses the same recency convention via dict insertion order, and the test cross-checks every operation plus the canonical eviction sequence `[-1, -1, 3, 4]`.

