#include <ctype.h>
#include <stdio.h>
#include <string.h>

static int rot13_ch(int c) {
    if (c >= 'a' && c <= 'z') return 'a' + (c - 'a' + 13) % 26;
    if (c >= 'A' && c <= 'Z') return 'A' + (c - 'A' + 13) % 26;
    return c;
}

static int rot13(FILE *in) {
    int c;
    while ((c = fgetc(in)) != EOF) putchar(rot13_ch(c));
    return 0;
}

static int hexdump(FILE *in) {
    unsigned char buf[16];
    size_t n, i;
    unsigned long off = 0;
    while ((n = fread(buf, 1, sizeof buf, in)) > 0) {
        printf("%08lx  ", off);
        for (i = 0; i < 16; i++) {
            if (i < n) printf("%02x ", buf[i]);
            else printf("   ");
            if (i == 7) putchar(' ');
        }
        putchar(' ');
        for (i = 0; i < n; i++) {
            putchar(isprint(buf[i]) ? buf[i] : '.');
        }
        putchar('\n');
        off += n;
    }
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s rot13|hexdump [file]\n", argv[0]);
        return 2;
    }
    FILE *in = stdin;
    if (argc >= 3) {
        in = fopen(argv[2], "rb");
        if (!in) {
            fprintf(stderr, "cannot open %s\n", argv[2]);
            return 1;
        }
    }
    int rc;
    if (strcmp(argv[1], "rot13") == 0) rc = rot13(in);
    else if (strcmp(argv[1], "hexdump") == 0) rc = hexdump(in);
    else {
        fprintf(stderr, "unknown mode: %s\n", argv[1]);
        rc = 2;
    }
    if (in != stdin) fclose(in);
    return rc;
}
