`rot13` maps only ASCII letters so digits and punctuation pass through unchanged. `hexdump` reads 16 bytes at a time and prints offset, hex bytes (space after the 8th), then an ASCII gutter where non-printables become `.`. A partial final block prints spaces in the missing hex slots so columns stay aligned. With no file argument both modes read stdin.

```rust
fn tokenize(input: &str) -> Result<Vec<char>, String> {
    let mut out = Vec::new();
    for ch in input.chars() {
        match ch {
            '0'..='9' | '.' | '+' | '-' | '*' | '/' | '(' | ')' => out.push(ch),
            c if c.is_whitespace() => {}
            c => return Err(format!("unexpected character: {c:?}")),
        }
    }
    Ok(out)
}

struct Parser {
    tokens: Vec<char>,
    pos: usize,
}

impl Parser {
    fn peek(&self) -> Option<char> {
        self.tokens.get(self.pos).copied()
    }

    fn expr(&mut self) -> Result<f64, String> {
        let mut value = self.term()?;
        while let Some(op @ ('+' | '-')) = self.peek() {
            self.pos += 1;
            let rhs = self.term()?;
            value = if op == '+' { value + rhs } else { value - rhs };
        }
        Ok(value)
    }

    fn term(&mut self) -> Result<f64, String> {
        let mut value = self.factor()?;
        while let Some(op @ ('*' | '/')) = self.peek() {
            self.pos += 1;
            let rhs = self.factor()?;
            if op == '/' {
                if rhs == 0.0 {
                    return Err("division by zero".to_string());
                }
                value /= rhs;
            } else {
                value *= rhs;
            }
        }
        Ok(value)
    }

    fn factor(&mut self) -> Result<f64, String> {
        let mut sign = 1.0;
        while let Some(op @ ('+' | '-')) = self.peek() {
            if op == '-' {
                sign = -sign;
            }
            self.pos += 1;
        }
        let mut value = match self.peek() {
            Some('(') => {
                self.pos += 1;
                let v = self.expr()?;
                if self.peek() != Some(')') {
                    return Err("missing closing parenthesis".to_string());
                }
                self.pos += 1;
                v
            }
            Some(c) if c.is_ascii_digit() || c == '.' => {
                let start = self.pos;
                while matches!(self.peek(), Some(c) if c.is_ascii_digit() || c == '.') {
                    self.pos += 1;
                }
                let s: String = self.tokens[start..self.pos].iter().collect();
                s.parse::<f64>().map_err(|e| format!("bad number {s:?}: {e}"))?
            }
            other => return Err(format!("unexpected token: {other:?}")),
        };
        value *= sign;
        Ok(value)
    }
}

pub fn eval(input: &str) -> Result<f64, String> {
    let tokens = tokenize(input)?;
    let mut p = Parser { tokens, pos: 0 };
    let v = p.expr()?;
    if p.pos != p.tokens.len() {
        return Err(format!("trailing input at position {}", p.pos));
    }
    Ok(v)
}

fn main() {
    let cases = [("2+3*4", 14.0), ("(2+3)*4", 20.0), ("-3 + 1", -2.0), ("10/4", 2.5)];
    for (src, want) in cases {
        let got = eval(src).expect(src);
        assert!((got - want).abs() < 1e-9, "{src}: got {got}, want {want}");
    }
    assert!(eval("1/0").is_err());
    assert!(eval("(1+2").is_err());
    println!("all expressions ok");
}
```

Grammar: `expr := term (('+'|'-') term)*`, `term := factor (('*'|'/') factor)*`, `factor := sign* (number | '(' expr ')')`. Unary signs are allowed before any factor. Errors cover bad characters, division by zero, missing `)`, and trailing input.

