```python
from functools import lru_cache


def fib_iter(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


@lru_cache(maxsize=None)
def fib_memo(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return fib_memo(n - 1) + fib_memo(n - 2)


if __name__ == "__main__":
    for n in range(50):
        assert fib_iter(n) == fib_memo(n), n
    assert fib_iter(0) == 0 and fib_iter(1) == 1
    assert fib_iter(10) == 55
    try:
        fib_iter(-1)
    except ValueError:
        pass
    else:
        raise AssertionError("negative input should raise")
    print("ok")
```
The iterative version is O(n) time and O(1) space; the memoized recursion is O(n) time with cache overhead. `functools.lru_cache` with `maxsize=None` turns the exponential naive recursion into linear-time by storing each subresult once. Both reject negative input explicitly.

