class Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def peek(self):
        return self.text[self.pos] if self.pos < len(self.text) else ""

    def parse(self):
        value = self.expr()
        if self.pos != len(self.text):
            raise ValueError(f"unexpected {self.text[self.pos]!r} at {self.pos}")
        return value

    def expr(self):
        value = self.term()
        while self.peek() in "+-":
            op = self.text[self.pos]
            self.pos += 1
            rhs = self.term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def term(self):
        value = self.factor()
        while self.peek() in "*/":
            op = self.text[self.pos]
            self.pos += 1
            rhs = self.factor()
            if op == "*":
                value *= rhs
            else:
                value //= rhs
        return value

    def factor(self):
        if self.peek() == "(":
            self.pos += 1
            value = self.expr()
            if self.peek() != ")":
                raise ValueError("missing closing paren")
            self.pos += 1
            return value
        start = self.pos
        while self.peek().isdigit():
            self.pos += 1
        if start == self.pos:
            raise ValueError(f"expected number at {self.pos}")
        return int(self.text[start:self.pos])


def evaluate(text):
    return Parser(text).parse()


if __name__ == "__main__":
    assert evaluate("3+4*2-(1+1)") == 9
    assert evaluate("(2+3)*(4-1)") == 15
    assert evaluate("100/2/5") == 10
    print("ok")
```

