#include <cstddef>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity) {}

    bool push(int value) {
        if (count_ == cap_) return false;
        buf_[(head_ + count_) % cap_] = value;
        ++count_;
        return true;
    }

    std::optional<int> pop() {
        if (count_ == 0) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }

private:
    std::vector<int> buf_;
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};
```

`push` returns `false` once capacity is reached, and `pop` returns `std::nullopt` when empty, so a zero-capacity buffer stays safe.

