use std::collections::HashMap;

fn most_common_char(s: &str) -> Option<char> {
    if s.is_empty() {
        return None;
    }

    let mut counts: HashMap<char, usize> = HashMap::new();
    for c in s.chars() {
        *counts.entry(c).or_insert(0) += 1;
    }

    // Iterate in original order so ties resolve to the first character seen.
    let mut best: Option<(char, usize)> = None;
    for c in s.chars() {
        let n = counts[&c];
        match best {
            Some((_, bn)) if n <= bn => {}
            _ => best = Some((c, n)),
        }
    }
    best.map(|(c, _)| c)
}

