def is_valid_ipv4(s):
    """True if s is four dot-separated decimal octets in 0..255, no leading zeros."""
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False  # reject leading zeros like '01'
        if int(part) > 255:
            return False
    return True


