/* Reverses ASCII bytes in place. Not grapheme-safe for multibyte UTF-8. */
static void reverse(char *s) {
    if (s == NULL) {
        return;
    }

    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) {
        return;
    }
    right -= 1;

    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left += 1;
        right -= 1;
    }
}

