template <typename T, std::size_t N>
class FixedStack {
public:
    bool push(const T& value) {
        if (size_ >= N) return false;
        data_[size_++] = value;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        return data_[--size_];
    }

    std::optional<T> top() const {
        if (size_ == 0) return std::nullopt;
        return data_[size_ - 1];
    }

    std::size_t size() const { return size_; }

private:
    T data_[N]{};
    std::size_t size_ = 0;
};

