long long count_pairs(const std::vector<long long>& nums, long long target) {
    std::unordered_map<long long, long long> seen;
    long long pairs = 0;
    for (long long x : nums) {
        auto it = seen.find(target - x);
        if (it != seen.end()) pairs += it->second;
        seen[x] += 1;
    }
    return pairs;
}

