    std::cout << count_pairs({}, 5) << "\n";                      // 0
    std::cout << count_pairs({0, 0, 0}, 0) << "\n";               // 3
    std::cout << count_pairs({-1, 1, 0}, 0) << "\n";              // 1
    return 0;
}
