bool parse_int(const char *s, int *out) {
    long v = 0;
    int sign = 1;
    if (*s == '-' || *s == '+') { if (*s == '-') sign = -1; s++; }
    if (*s == '\0') return false;
    for (; *s; s++) {
        if (*s < '0' || *s > '9') return false;
        v = v * 10 + (*s - '0');
        if (v > (long)INT_MAX + 1) return false;
    }
    v *= sign;
    if (v < INT_MIN || v > INT_MAX) return false;
    *out = (int)v;
    return true;
}

int main(void) {
    int x;
    printf("%d\n", parse_int("42", &x));        // 1
    printf("%d\n", parse_int("-7", &x));        // 1, x == -7
    printf("%d\n", parse_int("9999999999", &x)); // 0 overflow
    printf("%d\n", parse_int("12a", &x));       // 0 bad char
    printf("%d\n", parse_int("", &x));          // 0 empty
    return 0;
}
