fn merge_unique(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() || j < b.len() {
        let next = if j >= b.len() || (i < a.len() && a[i] <= b[j]) {
            i += 1; a[i - 1]
        } else {
            j += 1; b[j - 1]
        };
        if out.last() != Some(&next) {
            out.push(next);
        }
    }
    out
}

fn main() {
    assert_eq!(merge_unique(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_unique(&[1, 3, 5], &[2, 3, 4]), vec![1, 2, 3, 4, 5]);
    assert_eq!(merge_unique(&[1, 1, 2], &[2, 2, 3]), vec![1, 2, 3]);
    println!("ok");
}
```
The `out.last() != Some(&next)` check deduplicates across both inputs while the two-pointer merge keeps O(n+m) time.

