#include <iostream>
#include <stack>
#include <string>

bool balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char o = st.top(); st.pop();
            if ((c == ')' && o != '(') ||
                (c == ']' && o != '[') ||
                (c == '}' && o != '{')) return false;
        }
    }
    return st.empty();
}

int main() {
    std::cout << balanced("{[()]}") << "\n";  // 1
    std::cout << balanced("([)]") << "\n";    // 0
    std::cout << balanced("") << "\n";        // 1
    std::cout << balanced("(") << "\n";       // 0
    std::cout << balanced("a(b)c") << "\n";   // 1, non-bracket chars ignored
    return 0;
}
```
A stack naturally matches the innermost opener with the next closer; unknown characters are ignored, and the final `st.empty()` rejects unclosed openers.

