bool is_balanced(std::string_view s) {
    std::stack<char> st;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                st.push(c);
                break;
            case ')':
                if (st.empty() || st.top() != '(') return false;
                st.pop();
                break;
            case ']':
                if (st.empty() || st.top() != '[') return false;
                st.pop();
                break;
            case '}':
                if (st.empty() || st.top() != '{') return false;
                st.pop();
                break;
            default:
                break;  // ignore non-bracket characters
        }
    }
    return st.empty();
}

int main() {
    struct { const char* in; bool want; } cases[] = {
        {"()", true},
        {"([{}])", true},
        {"(]", false},
        {"((", false},
        {")", false},
        {"", true},
        {"a(b[c]{d})e", true},
        {"([)]", false},
    };
    for (auto& c : cases) {
        bool got = is_balanced(c.in);
        if (got != c.want) { std::cerr << "FAIL: " << c.in << '\n'; return 1; }
    }
    std::cout << "all ok\n";
    return 0;
