/// Returns the nth Fibonacci number (F(0)=0, F(1)=1), or None on overflow.
/// Iterative, O(n) time, O(1) space.
fn fib(n: u64) -> Option<u64> {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let next = a.checked_add(b)?; // bail out instead of wrapping
        a = b;
        b = next;
    }
    Some(a)
}

