/// Reverse the order of words while keeping each word's surrounding whitespace
/// in place. Words are separated by runs of spaces/tabs.
fn reverse_words(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut out = chars.clone();
    let mut i = 0usize;
    let n = chars.len();

    while i < n {
        if chars[i].is_whitespace() {
            i += 1;
            continue;
        }
        let start = i;
        while i < n && !chars[i].is_whitespace() {
            i += 1;
        }
        let word_len = i - start;
        out[start..i].copy_from_slice(&chars[start..i]);
    }

    // Collect word ranges and reverse their order into the original slots.
    let mut words: Vec<(usize, usize)> = Vec::new();
    let mut j = 0usize;
    while j < n {
        if chars[j].is_whitespace() {
            j += 1;
            continue;
        }
        let start = j;
        while j < n && !chars[j].is_whitespace() {
            j += 1;
        }
        words.push((start, j));
    }

    let mut reversed = vec![' '; n];
    let mut wi = words.len();
    for &(start, end) in &words {
        wi -= 1;
        let (rs, re) = words[wi];
        let len = end - start;
        let src_len = re - rs;
        if len != src_len {
            continue; // differing lengths: keep layout, skip swap
        }
        for k in 0..len {
            reversed[start + k] = chars[rs + k];
        }
    }

    // Preserve original whitespace; overwrite only word positions.
    let mut result = chars.clone();
    for &(start, end) in &words {
        for k in start..end {
            result[k] = reversed[k];
        }
    }
    result.into_iter().collect()
}

fn main() {
    assert_eq!(reverse_words("the quick brown fox"), "fox brown quick the");
    assert_eq!(reverse_words("a  bb   ccc"), "ccc  bb   a");
    assert_eq!(reverse_words("  "), "  ");
    assert_eq!(reverse_words(""), "");
    assert_eq!(reverse_words("one"), "one");
    println!("all ok");
}
