/* Parse a base-10 long from s. Returns true on success and stores the value
 * in *out; returns false on empty input, trailing garbage, or overflow. */
bool parse_long(const char *s, long *out) {
    if (s == NULL || *s == '\0') return false;

    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);

    if (end == s) return false;        /* no digits consumed */
    if (*end != '\0') return false;    /* trailing junk */
    if (errno == ERANGE) return false; /* out of range for long */

    *out = v;
    return true;
}

int main(void) {
    const char *inputs[] = {"42", "-7", "+13", "", " 5", "12abc", "999999999999999999999", NULL};
    for (int i = 0; inputs[i] != NULL; ++i) {
        long v = 0;
        bool ok = parse_long(inputs[i], &v);
        if (ok)
            printf("ok   %-24s -> %ld\n", inputs[i], v);
        else
            printf("fail %-24s\n", inputs[i]);
    }
    return 0;
}
