from collections import defaultdict


def summarize(rows):
    """rows: iterable of (name, score_str) -> dict name -> stats dict."""
    per_name = defaultdict(list)
    for name, score in rows:
        name = name.strip()
        if not name:
            continue
        try:
            per_name[name].append(float(score))
        except ValueError:
            continue  # skip malformed score rows
    out = {}
    for name, vals in per_name.items():
        out[name] = {
            "n": len(vals),
            "mean": statistics.fmean(vals),
            "median": statistics.median(vals),
            "min": min(vals),
            "max": max(vals),
        }
    return out


def main(path):
    with open(path, newline="") as fh:
        # Accept both (name,score) header rows and headerless files.
        sample = fh.read()
        fh.seek(0)
        reader = csv.reader(fh)
        first = next(reader, None)
        rows = []
        if first is not None:
            try:
                float(first[1])
                rows.append((first[0], first[1]))
            except (ValueError, IndexError):
                pass  # treat as header
            rows.extend((r[0], r[1]) for r in reader if len(r) >= 2)

    stats = summarize(rows)
    for name in sorted(stats):
        s = stats[name]
        print(f"{name:<12} n={s['n']:<3} mean={s['mean']:.2f} "
              f"median={s['median']:.2f} min={s['min']:.2f} max={s['max']:.2f}")


if __name__ == "__main__":
