template <typename T>
void insertion_sort(std::vector<T> &v) {
    for (std::size_t i = 1; i < v.size(); ++i) {
        T key = std::move(v[i]);
        std::size_t j = i;
        while (j > 0 && v[j - 1] > key) {
            v[j] = std::move(v[j - 1]);
            --j;
        }
        v[j] = std::move(key);
    }
}

int main() {
    std::vector<int> empty;
    insertion_sort(empty);
    std::cout << empty.size() << '\n';

