#include <stdio.h>
#include <string.h>

static const char *ones[] = {
    "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
    "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
    "seventeen", "eighteen", "nineteen"
};

static const char *tens[] = {
    "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
};

static void append(char *out, size_t cap, const char *text) {
    size_t len = strlen(out);
    if (len > 0 && len + 1 < cap) {
        out[len] = ' ';
        out[len + 1] = '\0';
    }
    strncat(out, text, cap - strlen(out) - 1);
}

static void below_thousand(int n, char *out, size_t cap) {
    if (n >= 100) {
        append(out, cap, ones[n / 100]);
        append(out, cap, "hundred");
        n %= 100;
    }
    if (n >= 20) {
        append(out, cap, tens[n / 10]);
        if (n % 10 != 0) {
            append(out, cap, ones[n % 10]);
        }
    } else if (n > 0) {
        append(out, cap, ones[n]);
    }
}

void number_to_words(long long n, char *out, size_t cap) {
    out[0] = '\0';
    if (n == 0) {
        strncat(out, "zero", cap - 1);
        return;
    }
    const char *scales[] = {"", "thousand", "million", "billion"};
    int group[4] = {0, 0, 0, 0};
    int i = 0;
    while (n > 0 && i < 4) {
        group[i++] = (int)(n % 1000);
        n /= 1000;
    }
    for (int idx = i - 1; idx >= 0; --idx) {
        if (group[idx] == 0) {
            continue;
        }
        char part[128] = {0};
        below_thousand(group[idx], part, sizeof(part));
        append(out, cap, part);
        if (scales[idx][0] != '\0') {
            append(out, cap, scales[idx]);
        }
    }
}

int main(void) {
    long long tests[] = {0, 5, 21, 100, 101, 999, 1000, 12345, 1000000, 2147483647};
    char buf[256];
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); ++i) {
        number_to_words(tests[i], buf, sizeof(buf));
        printf("%lld -> %s\n", tests[i], buf);
    }
    return 0;
}
