```rust
use std::collections::HashMap;

pub fn word_frequencies(text: &str) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();

    for raw in text.split_whitespace() {
        // Keep only alphanumeric characters and lowercase them.
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }

    let mut out: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count descending, then alphabetically for stable output.
    out.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic_counts() {
        let got = word_frequencies("The cat, the CAT! A dog.");
        assert_eq!(
            got,
            vec![
                ("the".to_string(), 2),
                ("a".to_string(), 1),
                ("cat".to_string(), 1),
                ("dog".to_string(), 1),
            ]
        );
    }

    #[test]
    fn empty_input() {
        assert!(word_frequencies("   ").is_empty());
    }
}
```

Each token is reduced to its alphanumeric characters before counting, so `"cat,"` and `"CAT!"` both become `cat`. Filtering on `is_alphanumeric` skips punctuation-only tokens, and the empty-input case yields an empty vector.

```c
#include <stdio.h>
#include <string.h>

static void reverse(char *s) {
    size_t len = strlen(s);
    if (len < 2) {
        return;  /* empty or single char needs no work */
    }
    size_t i = 0;
    size_t j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

int main(void) {
    char buf[] = "hello, world";
    char empty[] = "";
    char odd[] = "abc";

    reverse(buf);
    reverse(empty);
    reverse(odd);

    printf("buf   = '%s'\n", buf);
    printf("empty = '%s'\n", empty);
    printf("odd   = '%s'\n", odd);
    return 0;
}
