use std::env;

fn parse_numbers(line: &str) -> Result<Vec<f64>, String> {
    let mut out = Vec::new();
    for token in line.split(',') {
        let token = token.trim();
        if token.is_empty() {
            return Err("empty token".to_string());
        }
        let value: f64 = token
            .parse()
            .map_err(|_| format!("not a number: '{token}'"))?;
        out.push(value);
    }
    Ok(out)
}

fn stats(values: &[f64]) -> Option<(f64, f64)> {
    if values.is_empty() {
        return None;
    }
    let n = values.len() as f64;
    let mean = values.iter().sum::<f64>() / n;
    if values.len() < 2 {
        return Some((mean, 0.0));
    }
    // Sample (n-1) variance.
    let var = values
        .iter()
        .map(|v| (v - mean).powi(2))
        .sum::<f64>()
        / (n - 1.0);
    Some((mean, var.sqrt()))
}

fn main() {
    let arg = env::args().nth(1).unwrap_or_else(|| "1,2,3,4".to_string());
    match parse_numbers(&arg).and_then(|v| {
        stats(&v).ok_or_else(|| "no values".to_string())
    }) {
        Ok((mean, sd)) => println!("mean={mean:.4} sd={sd:.4}"),
        Err(e) => eprintln!("error: {e}"),
    }
}
