def caesar(text, shift):
    """Shift alphabetic characters by `shift`, wrapping A-Z and a-z."""
    shift %= 26
    out = []
    for ch in text:
        if 'a' <= ch <= 'z':
            out.append(chr((ord(ch) - ord('a') + shift) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            out.append(chr((ord(ch) - ord('A') + shift) % 26 + ord('A')))
        else:
            out.append(ch)
    return ''.join(out)


if __name__ == "__main__":
    message = "Attack at dawn, 5 a.m.!é"
    for shift in (3, -7, 26, 0):
        encoded = caesar(message, shift)
        decoded = caesar(encoded, -shift)
        assert decoded == message, (shift, encoded, decoded)
    assert caesar("xyz", 3) == "abc"
    assert caesar("Hello, World!", 0) == "Hello, World!"
    print("all checks passed")
```

`shift %= 26` normalises negative and large shifts, and the two ASCII branches keep case while wrapping within each alphabet. Any other character — punctuation, digits, `é`, spaces — is appended unchanged. The self-test encodes and decodes with several shifts and confirms the round trip returns the original message.

```python
import heapq


class RunningMedian:
    """Maintains the median of a stream of numbers using two heaps.

    lower holds the smaller half as a max-heap (negated), upper holds the
    larger half as a min-heap. The heaps are kept within one element of
    each other so the median is O(1) to read after each O(log n) insert.
    """

    def __init__(self):
        self.lower = []  # max-heap via negation
        self.upper = []  # min-heap

    def add(self, value):
        if not self.lower or value <= -self.lower[0]:
            heapq.heappush(self.lower, -value)
        else:
            heapq.heappush(self.upper, value)

        # Rebalance so len(lower) == len(upper) or len(lower) == len(upper) + 1
        if len(self.lower) > len(self.upper) + 1:
            heapq.heappush(self.upper, -heapq.heappop(self.lower))
        elif len(self.upper) > len(self.lower):
            heapq.heappush(self.lower, -heapq.heappop(self.upper))

    def median(self):
        if not self.lower:
            raise ValueError("median of an empty stream is undefined")
        if len(self.lower) == len(self.upper):
            return (-self.lower[0] + self.upper[0]) / 2.0
        return float(-self.lower[0])


if __name__ == "__main__":
    stream = RunningMedian()
    for x in [5, 15, 1, 3, 8, 7, 9, 10, 6, 11]:
        stream.add(x)
        print(x, stream.median())
