fn longest_common_prefix(words: &[String]) -> String {
    if words.is_empty() {
        return String::new();
    }

    let first: Vec<char> = words[0].chars().collect();
    let mut end = first.len();

    for word in &words[1..] {
        let chars: Vec<char> = word.chars().collect();
        let limit = end.min(chars.len());
        let mut i = 0;
        while i < limit && first[i] == chars[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }

    first[..end].iter().collect()
