#include <stdio.h>
#include <stdlib.h>

struct node {
    int value;
    struct node *prev;
    struct node *next;
};

static struct node *reverse(struct node *head) {
    struct node *cur = head;
    struct node *tmp = NULL;
    while (cur != NULL) {
        tmp = cur->prev;
        cur->prev = cur->next;
        cur->next = tmp;
        cur = cur->prev; /* move to original next */
    }
    if (tmp != NULL) {
        head = tmp->prev;
    }
    return head;
}

static void print_forward(struct node *head) {
    for (; head != NULL; head = head->next) {
        printf("%d", head->value);
        if (head->next) printf(" -> ");
    }
    printf("\n");
}

int main(void) {
    int values[] = {1, 2, 3, 4};
    struct node *head = NULL;
    struct node *tail = NULL;
    for (size_t i = 0; i < sizeof(values) / sizeof(values[0]); ++i) {
        struct node *n = malloc(sizeof *n);
        if (!n) { perror("malloc"); return 1; }
        n->value = values[i];
        n->prev = tail;
        n->next = NULL;
        if (tail) tail->next = n;
        else head = n;
        tail = n;
    }

    print_forward(head);
    head = reverse(head);
    print_forward(head);

    while (head) {
        struct node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
