```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        let mut data = Vec::with_capacity(capacity);
        data.resize_with(capacity, || None);
        RingBuffer { data, head: 0, len: 0 }
    }

    /// Pushes a value. Returns the overwritten value when the buffer is full,
    /// so callers can see that data was displaced instead of silently losing it.
    pub fn push(&mut self, value: T) -> Option<T> {
        let capacity = self.data.len();
        let index = (self.head + self.len) % capacity;
        let displaced = self.data[index].replace(value);
        if self.len < capacity {
            self.len += 1;
        } else {
            self.head = (self.head + 1) % capacity;
        }
        displaced
    }

    pub fn iter(&self) -> impl Iterator<Item = &T> {
        (0..self.len).filter_map(move |i| {
            self.data[(self.head + i) % self.data.len()].as_ref()
        })
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    for x in [1, 2, 3, 4] {
        println!("push {x} displaced {:?}", rb.push(x));
    }
    let items: Vec<i32> = rb.iter().copied().collect();
    println!("buffer: {items:?}");
}
