// Returns the index of the first element not less than `target`.
// If every element is less, returns vec.size(). Input must be sorted.
template <typename T>
size_t lower_bound_index(const std::vector<T>& vec, const T& target) {
    size_t lo = 0;
    size_t hi = vec.size();
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;   // avoids overflow
        if (vec[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

