    for (int probe : {0, 3, 4, 9}) {
        size_t idx = lower_bound_index(data, probe);
        bool found = idx < data.size() && data[idx] == probe;
        std::cout << "probe=" << probe
                  << " index=" << idx
                  << " found=" << (found ? "yes" : "no") << "\n";
