def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    start, end = 0, 0

    for i in range(len(s)):
        len1 = expand(s, i, i)      # odd-length centers
        len2 = expand(s, i, i + 1)  # even-length centers
        best = max(len1, len2)
        if best > end - start:
            start = i - (best - 1) // 2
            end = i + best // 2

    return s[start:end + 1]


def expand(s: str, left: int, right: int) -> int:
    while left >= 0 and right < len(s) and s[left] == s[right]:
        left -= 1
        right += 1
    return right - left - 1


if __name__ == "__main__":
    cases = ["", "a", "cbbd", "babad", "forgeeksskeegfor", "ünïcödé"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
