Expand-around-center yields O(n²) time and O(1) extra space. The `best > end - start` comparison keeps the first match on ties, and the empty string short-circuits before any indexing.

```cpp
#include <list>
#include <unordered_map>
#include <stdexcept>
#include <iostream>

class LRUCache {
public:
    explicit LRUCache(size_t capacity) : cap(capacity) {
        if (cap == 0) throw std::invalid_argument("capacity must be > 0");
    }

    int get(int key) {
        auto it = index.find(key);
        if (it == index.end()) return -1;
        items.splice(items.begin(), items, it->second);
        return it->second->second;
    }

    void put(int key, int value) {
        auto it = index.find(key);
        if (it != index.end()) {
            it->second->second = value;
            items.splice(items.begin(), items, it->second);
            return;
        }
        if (items.size() == cap) {
            int evict = items.back().first;
            items.pop_back();
            index.erase(evict);
        }
        items.emplace_front(key, value);
        index[key] = items.begin();
    }

private:
    size_t cap;
    std::list<std::pair<int, int>> items;                       // front = MRU
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> index;
};

int main() {
    LRUCache c(2);
    c.put(1, 1);
    c.put(2, 2);
    std::cout << c.get(1) << "\n"; // 1
    c.put(3, 3);                   // evicts key 2
    std::cout << c.get(2) << "\n"; // -1
    std::cout << c.get(3) << "\n"; // 3
}
```

`std::list::splice` moves a node to the front in O(1) without invalidating the stored iterators, which is why the map can cache list iterators safely. Capacity 0 is rejected up front.

