        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = match line.split_once('=') {
            Some(kv) => kv,
            None => {
                return Err(ParseError {
                    line: idx + 1,
                    reason: "missing '='".to_string(),
                })
            }
        };
        let key = key.trim();
        if key.is_empty() {
            return Err(ParseError {
                line: idx + 1,
                reason: "empty key".to_string(),
            });
        }
        map.insert(key.to_string(), value.trim().to_string());
    }

    Ok(map)
}

fn main() {
    let src = "# server\nhost = localhost\nport=8080\n\nmode = dev\n";
    match parse_config(src) {
        Ok(cfg) => println!("{:?}", cfg),
        Err(e) => eprintln!("line {}: {}", e.line, e.reason),
    }
    assert!(parse_config("broken line").is_err());
}
