#include <stdio.h>
#include <limits.h>

/* Writes n as a decimal string plus a NUL into buf.
 * Returns the number of characters written (excluding NUL), or -1 if buf is
 * too small. Needs at most 12 bytes for any int (sign + 10 digits + NUL). */
int int_to_str(int n, char *buf, size_t buflen) {
    if (buf == NULL || buflen == 0) return -1;

    char tmp[12];
    int i = 0;
    int negative = n < 0;

    /* Build digits in reverse using unsigned math to survive INT_MIN. */
    unsigned int u = negative ? (unsigned int)(-(long)n) : (unsigned int)n;
    do {
        tmp[i++] = (char)('0' + (u % 10u));
        u /= 10u;
    } while (u != 0);

    if (negative) tmp[i++] = '-';

    if ((size_t)i + 1 > buflen) return -1;

    for (int j = 0; j < i; j++) {
        buf[j] = tmp[i - 1 - j];
    }
    buf[i] = '\0';
    return i;
}

int main(void) {
    char b[12];
    int vals[] = {0, 42, -7, INT_MAX, INT_MIN};
    for (size_t k = 0; k < sizeof vals / sizeof vals[0]; k++) {
        int n = int_to_str(vals[k], b, sizeof b);
        printf("%d -> %s (%d chars)\n", vals[k], b, n);
    }
    if (int_to_str(123, b, 2) == -1) puts("buffer too small handled");
    return 0;
}
```

The `(long)` cast before negation avoids overflow on `INT_MIN`, whose absolute value does not fit in `int`. Digit reversal happens in a fixed-size temp array, then bounds are checked before writing the caller's buffer.

```rust
/// Returns the index of the first element >= target.
/// Works on any slice whose type is Ord.
pub fn lower_bound<T: Ord>(data: &[T], target: &T) -> usize {
    let mut lo = 0usize;
    let mut hi = data.len();

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if data[mid] < *target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

fn main() {
    let arr = [1, 3, 3, 5, 8];

    assert_eq!(lower_bound(&arr, &0), 0);   // before all
    assert_eq!(lower_bound(&arr, &3), 1);   // first 3
    assert_eq!(lower_bound(&arr, &4), 3);   // between 3 and 5
    assert_eq!(lower_bound(&arr, &9), 5);   // after all
    assert_eq!(lower_bound::<i32>(&[], &1), 0); // empty

    println!("lower_bound(&arr, &4) = {}", lower_bound(&arr, &4));
}
```

The half-open invariant keeps `lo` as the answer when the loop ends: elements before `lo` are `< target`, elements from `lo` on are `>= target`. `lo + (hi - lo) / 2` avoids unsigned overflow on large slices, and the empty slice trivially returns 0.

