import threading
from collections import deque
from typing import Any, Deque, List, Optional


class BoundedQueue:
    """Bounded FIFO queue. put/get block; None is a stop sentinel."""

    def __init__(self, maxsize: int) -> None:
        if maxsize < 1:
            raise ValueError("maxsize must be >= 1")
        self._max = maxsize
        self._items: Deque[Any] = deque()
        self._cond = threading.Condition()
        self._closed = False

    def put(self, item: Any) -> None:
        with self._cond:
            while len(self._items) >= self._max and not self._closed:
                self._cond.wait()
            if self._closed:
                raise RuntimeError("queue is closed")
            self._items.append(item)
            self._cond.notify_all()

    def get(self) -> Optional[Any]:
        with self._cond:
            while not self._items and not self._closed:
                self._cond.wait()
            if self._items:
                item = self._items.popleft()
                self._cond.notify_all()
                return item
            return None  # closed and drained

    def close(self) -> None:
        with self._cond:
            self._closed = True
            self._cond.notify_all()


def worker(q: BoundedQueue, out: List[int]) -> None:
    while True:
        item = q.get()
        if item is None:
            return
        with threading.Lock():
            out.append(item * item)


if __name__ == "__main__":
    q = BoundedQueue(3)
    results: List[int] = []
    threads = [threading.Thread(target=worker, args=(q, results)) for _ in range(4)]
    for t in threads:
        t.start()
    for i in range(10):
        q.put(i)
    q.close()
    for t in threads:
        t.join()
    print(sorted(results))
```

A single `Condition` guards both fullness and emptiness so producers and consumers share one lock and no lost-wakeup is possible. `close()` unblocks every waiter; workers see the `None` sentinel and exit cleanly.

