        x /= 10;
    }
    return reversed == original;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << isPalindrome(121) << '\n';
    std::cout << isPalindrome(-121) << '\n';
    std::cout << isPalindrome(10) << '\n';
    std::cout << isPalindrome(0) << '\n';
    std::cout << isPalindrome(INT_MAX) << '\n';
}
```
The accumulator uses `long long` so reversing `INT_MAX` cannot overflow. Trailing zeros (other than `0` itself) disqualify a number because the reverse would lose them.

