```c
#include <stdio.h>
#include <string.h>

int is_balanced(const char *s) {
    char stack[256];
    int top = 0;
    for (const char *p = s; *p; ++p) {
        char c = *p;
        if (c == '(' || c == '[' || c == '{') {
            if (top >= (int)sizeof(stack)) return 0;
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) return 0;
            char open = stack[--top];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) return 0;
        }
    }
    return top == 0;
}

int main(void) {
    const char *tests[] = {"({[]})", "(]", "", "(((", "a(b)c"};
    for (int i = 0; i < 5; ++i) {
        printf("%s -> %s\n", tests[i], is_balanced(tests[i]) ? "yes" : "no");
    }
    return 0;
}
```
Non-bracket characters are ignored, and the stack is bounded to avoid overflow on pathological inputs. A mismatch is detected as soon as the wrong closer appears.

