def rle_decode(s: str) -> str:
    out = []
    i = 0
    n = len(s)
    while i < n:
        if not s[i].isdigit():
            raise ValueError(f"expected digit at {i}: {s[i]!r}")
        start = i
        while i < n and s[i].isdigit():
            i += 1
        if i == n:
            raise ValueError("trailing count without character")
        count = int(s[start:i])
        out.append(s[i] * count)
        i += 1
    return "".join(out)


