import os
import shutil
import tempfile


def replace_dir(target: str, staging_src: str) -> None:
    """Swap `target` for a fully-populated `staging_src` atomically."""
    target = os.path.abspath(target)
    parent = os.path.dirname(target)
    staging = tempfile.mkdtemp(prefix=".staging-", dir=parent)
    try:
        for name in os.listdir(staging_src):
            shutil.move(os.path.join(staging_src, name), staging)
        old_backup = target + ".old"
        if os.path.exists(old_backup):
            shutil.rmtree(old_backup)
        if os.path.exists(target):
            os.replace(target, old_backup)
        os.rename(staging, target)
        if os.path.exists(old_backup):
            shutil.rmtree(old_backup)
    except BaseException:
        if os.path.isdir(staging):
            shutil.rmtree(staging, ignore_errors=True)
        raise


if __name__ == "__main__":
    import sys
    if len(sys.argv) != 3:
        raise SystemExit("usage: replace_dir.py TARGET STAGING")
    replace_dir(sys.argv[1], sys.argv[2])
```

The new tree is built beside the target on the same filesystem, so the final `rename` is a single metadata operation rather than a copy. The old tree is kept as `.old` until the new one is in place, and any failure unwinds the staging directory and re-raises.

