#include <cstddef>
#include <iostream>
#include <vector>

std::vector<int> merge_unique(const std::vector<int>& a,
                              const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;

    while (i < a.size() || j < b.size()) {
        int next;
        if (j >= b.size() || (i < a.size() && a[i] <= b[j])) {
            next = a[i++];
        } else {
            next = b[j++];
        }
        if (out.empty() || out.back() != next) {
            out.push_back(next);
        }
    }
    return out;
}

int main() {
    std::vector<int> a{1, 2, 2, 5};
    std::vector<int> b{2, 3, 5, 6};
    for (int v : merge_unique(a, b)) {
        std::cout << v << ' ';
    }
    std::cout << '\n';
    return 0;
}
