#[derive(Debug, PartialEq)]
pub enum ParseError {
    Empty,
    BadNumber,
    UnknownUnit(char),
    MissingUnit,
}

pub fn parse_duration(s: &str) -> Result<u64, ParseError> {
    if s.is_empty() {
        return Err(ParseError::Empty);
    }
    let mut total: u64 = 0;
    let mut digits = String::new();
    for ch in s.chars() {
        if ch.is_ascii_digit() {
            digits.push(ch);
            continue;
        }
        if digits.is_empty() {
            return Err(ParseError::MissingUnit);
        }
        let n: u64 = digits.parse().map_err(|_| ParseError::BadNumber)?;
        let mult = match ch {
            'h' => 3600,
            'm' => 60,
            's' => 1,
            other => return Err(ParseError::UnknownUnit(other)),
        };
        total += n * mult;
        digits.clear();
    }
    if !digits.is_empty() {
        return Err(ParseError::MissingUnit);
    }
    Ok(total)
}

fn main() {
    assert_eq!(parse_duration("1h30m"), Ok(5400));
    assert_eq!(parse_duration("45s"), Ok(45));
    assert_eq!(parse_duration("1h"), Ok(3600));
    assert_eq!(parse_duration(""), Err(ParseError::Empty));
    assert_eq!(parse_duration("5x"), Err(ParseError::UnknownUnit('x')));
    assert_eq!(parse_duration("m"), Err(ParseError::MissingUnit));
    println!("all assertions passed");
}
