def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(lo: int, hi: int) -> tuple[int, int]:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - 1

    for i in range(len(s)):
        a, b = expand(i, i)
        if b - a > end - start:
            start, end = a, b
        a, b = expand(i, i + 1)
        if b - a > end - start:
            start, end = a, b

    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "ab"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```

