#include <limits.h>
#include <stdbool.h>
#include <stdio.h>

bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;

    long acc = 0;
    int sign = 1;
    const char *p = s;

    if (*p == '+' || *p == '-') {
        if (*p == '-') sign = -1;
        p++;
    }
    if (*p == '\0') return false;

    for (; *p != '\0'; p++) {
        if (*p < '0' || *p > '9') return false;
        acc = acc * 10 + (*p - '0');
        if (sign * acc > INT_MAX || sign * acc < INT_MIN) return false;
    }

    *out = (int)(sign * acc);
    return true;
}

int main(void) {
    const char *tests[] = {"42", "-17", "+0", "", "12x", "999999999999", "-2147483648"};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); i++) {
        int v = 0;
        bool ok = parse_int(tests[i], &v);
        printf("%-16s -> %s", tests[i], ok ? "ok " : "fail ");
        if (ok) printf("%d", v);
        printf("\n");
    }
    return 0;
}
