#include <array>
#include <cstddef>
#include <optional>
#include <iostream>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }
    std::size_t size() const { return count_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int i = 1; i <= 4; ++i)
        std::cout << "push " << i << ": " << (rb.push(i) ? "ok" : "full") << "\n";

    while (auto v = rb.pop())
        std::cout << "pop: " << *v << "\n";
    std::cout << "pop empty: " << (rb.pop() ? "value" : "none") << "\n";
}
```

Tracking `count_` separately from `head_` makes `full()` and `empty()` unambiguous, which a head/tail-only design cannot do. `std::optional` keeps the pop result type-safe.

