    const long long limit = negative
        ? std::numeric_limits<long long>::min()
        : std::numeric_limits<long long>::max();
    long long acc = 0;
    long long min_safe = limit / 10;

    for (; i < text.size(); ++i) {
        char c = text[i];
        if (c < '0' || c > '9') return std::nullopt;
        int digit = c - '0';
        if (acc < min_safe) return std::nullopt;
        acc *= 10;
        if (negative ? acc < limit + digit : acc > limit - digit) {
            return std::nullopt;
        }
        acc += negative ? -digit : digit;
    }
    return acc;
}

int main() {
    const char* inputs[] = {"0", "-1", "9223372036854775807", "9223372036854775808", "12x", ""};
    for (const char* s : inputs) {
        auto r = parse_ll(s);
        std::cout << '"' << s << '" -> ' << (r ? std::to_string(*r) : "invalid") << '\n';
    }
    return 0;
}
```

The pre-check `acc < min_safe` (equivalently `acc > limit/10`) rejects a magnitude that would overflow before multiplying. The per-digit bound is compared against `LLONG_MAX` or `LLONG_MIN` depending on sign, so `LLONG_MIN` itself parses and `LLONG_MAX + 1` is rejected.

