#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t Capacity>
class RingBuffer {
public:
    static_assert(Capacity > 0, "capacity must be positive");

    void push(int value) {
        data_[head_] = value;
        head_ = (head_ + 1) % Capacity;
        if (size_ < Capacity) {
            ++size_;
        }
    }

    std::optional<int> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        --size_;
        // tail_ points at the oldest element.
        const int value = data_[tail_];
        tail_ = (tail_ + 1) % Capacity;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::array<int, Capacity> data_{};
    std::size_t head_ = 0;  // next write position
    std::size_t tail_ = 0;  // oldest element
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1);
    rb.push(2);
    rb.push(3);
    rb.push(4);  // overwrites 1
    std::cout << *rb.pop() << '\n';  // 2
    std::cout << *rb.pop() << '\n';  // 3
    std::cout << *rb.pop() << '\n';  // 4
    std::cout << (rb.pop() == std::nullopt) << '\n';  // 1 (empty)
}
