/// Merge two ascending slices into one ascending Vec.
/// Duplicates from either side are kept.
pub fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn interleaves() {
        assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    }

    #[test]
    fn duplicates_kept() {
        assert_eq!(merge_sorted(&[1, 1, 2], &[1, 2, 2]), vec![1, 1, 1, 2, 2, 2]);
    }

    #[test]
    fn empty_inputs() {
        assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
        assert_eq!(merge_sorted(&[], &[7]), vec![7]);
        assert_eq!(merge_sorted(&[7], &[]), vec![7]);
    }
