#include <cassert>
#include <iostream>

struct Node {
    int val;
    Node* next;
    explicit Node(int v) : val(v), next(nullptr) {}
};

Node* merge(Node* a, Node* b) {
    Node dummy(0);
    Node* tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) { tail->next = a; a = a->next; }
        else { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

static Node* build(std::initializer_list<int> xs) {
    Node dummy(0);
    Node* t = &dummy;
    for (int x : xs) { t->next = new Node(x); t = t->next; }
    return dummy.next;
}

int main() {
    Node* r = merge(build({1, 3, 5}), build({2, 4, 6}));
    int expected[] = {1, 2, 3, 4, 5, 6};
    int i = 0;
    for (Node* p = r; p; p = p->next) assert(p->val == expected[i++]);
    assert(i == 6);
    assert(merge(nullptr, nullptr) == nullptr);
    assert(merge(nullptr, build({7}))->val == 7);
    std::cout << "ok\n";
}
```
The dummy node removes the head special case; `tail->next` appends whichever list remains without copying.

