                let key = k.trim();
                if key.is_empty() {
                    return Err(format!("empty key on line {}", i + 1));
                }
                map.insert(key.to_string(), v.trim().to_string());
            }
            None => return Err(format!("missing '=' on line {}", i + 1)),
        }
    }
    Ok(map)
}

