size_t copy_bounded(char *dst, size_t cap, const char *src) {
    if (cap == 0) return 0;
    size_t i = 0;
    while (i + 1 < cap && src[i] != '\0') {
        dst[i] = src[i];
        i++;
    }
    dst[i] = '\0';
    return i;
}

int main(void) {
    char buf[8];
    size_t n;

    n = copy_bounded(buf, sizeof buf, "hello");
    if (n != 5 || strcmp(buf, "hello") != 0) return 1;

    n = copy_bounded(buf, sizeof buf, "this is too long");
    if (n != 7 || strcmp(buf, "this is") != 0) return 1;

    n = copy_bounded(buf, 0, "x");
    if (n != 0) return 1;

    n = copy_bounded(buf, sizeof buf, "");
    if (n != 0 || buf[0] != '\0') return 1;

    puts("ok");
    return 0;
}
```
The loop reserves the last byte for the terminator, so the buffer is always a valid C string when `cap > 0`; the returned count lets callers detect truncation.

