    assert((merge_sorted({1, 1, 2}, {}) == std::vector<int>{1, 1, 2}));
    assert((merge_sorted({}, {}) == std::vector<int>{}));
    assert((merge_sorted({2, 2}, {2, 2}) == std::vector<int>{2, 2, 2, 2}));
