fn longest_run<T: PartialEq + Copy>(items: &[T]) -> Option<(T, usize)> {
    if items.is_empty() {
        return None;
    }
    let mut best_val = items[0];
    let mut best_len = 1usize;
    let mut cur_val = items[0];
    let mut cur_len = 1usize;
    for &x in &items[1..] {
        if x == cur_val {
            cur_len += 1;
        } else {
            cur_val = x;
            cur_len = 1;
        }
        if cur_len > best_len {
            best_len = cur_len;
            best_val = cur_val;
        }
    }
    Some((best_val, best_len))
}

fn main() {
    assert_eq!(longest_run(&[1, 1, 2, 2, 2, 3]), Some((2, 3)));
    assert_eq!(longest_run(&[5]), Some((5, 1)));
    assert_eq!(longest_run::<i32>(&[]), None);
    assert_eq!(longest_run(&['a', 'a', 'b', 'a']), Some(('a', 2)));
