```c
#include <stdio.h>
#include <stdint.h>

int popcount_kernighan(uint32_t n) {
    int count = 0;
    while (n) {
        n &= n - 1;  /* clears the lowest set bit */
        count++;
    }
    return count;
}

int main(void) {
    uint32_t samples[] = {0u, 1u, 0xFFFFFFFFu, 0b101101u, 0x80000000u};
    int expected[]      = {0,  1,  32,         4,          1};
    for (size_t i = 0; i < sizeof(samples) / sizeof(samples[0]); i++) {
        int got = popcount_kernighan(samples[i]);
        printf("0x%08X -> %d\n", samples[i], got);
        if (got != expected[i]) {
            fprintf(stderr, "mismatch at index %zu\n", i);
            return 1;
        }
    }
    return 0;
}
```

Each iteration of `n &= n - 1` removes the lowest set bit, so the loop runs exactly popcount times rather than a fixed 32. Zero returns 0 immediately. The check array verifies the boundary cases including all-ones and a single high bit.

