# alphabetic TLD of at least 2 chars. Full RFC 5322 is not worth the regex.
_EMAIL = re.compile(r"^(?P<local>[^@\s]+)@(?P<domain>[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)*\.[A-Za-z]{2,})$")


def validate_email(value: str) -> Tuple[bool, str]:
