void byte_histogram(const unsigned char *data, size_t len, size_t counts[256]) {
    memset(counts, 0, sizeof(size_t) * 256);
    if (data == NULL) {
        return;
    }
    for (size_t i = 0; i < len; ++i) {
        counts[data[i]]++;
    }
}

int main(void) {
    const char *text = "banana";
    size_t counts[256];
    byte_histogram((const unsigned char *)text, strlen(text), counts);

    printf("'a'=%zu 'b'=%zu 'n'=%zu\n", counts['a'], counts['b'], counts['n']);
    printf("'z'=%zu\n", counts['z']);

    byte_histogram(NULL, 0, counts);
    printf("null-buffer 'a'=%zu\n", counts['a']);
    return 0;
}
```
Callers must pass an array of at least 256 `size_t`. A NULL pointer with any length is treated as empty rather than dereferenced, and the function always zero-fills the histogram first so stale values never leak through.

