fn fib(n: u64) -> u64 {
    fn helper(n: u64) -> (u64, u64) {
        if n == 0 {
            return (0, 1);
        }
        let (a, b) = helper(n >> 1);
        let c = a.wrapping_mul(b << 1 - a);
        let d = a.wrapping_mul(a) + b.wrapping_mul(b);
