// Reverse by bytes to preserve UTF-8 multi-byte sequences when they are
// symmetric; for full Unicode correctness see the helper below.
static void reverse_bytes(std::string& s) {
    std::reverse(s.begin(), s.end());
}

// Reverse by code points so UTF-8 sequences stay intact.
static void reverse_utf8(std::string& s) {
    std::vector<std::string> cp;
    for (size_t i = 0; i < s.size();) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        size_t len = (c < 0x80) ? 1 : (c >> 5) == 0x6 ? 2 : (c >> 4) == 0xE ? 3 : 4;
        cp.push_back(s.substr(i, len));
        i += len;
    }
    std::string out;
    for (auto it = cp.rbegin(); it != cp.rend(); ++it) out += *it;
    s = std::move(out);
}

int main() {
    std::string s = "hello world";
    reverse_bytes(s);
    std::cout << s << "\n";        // dlrow olleh

    std::string u = "aé日";
    reverse_utf8(u);
    std::cout << u << "\n";        // 日éa
    return 0;
}
```

`reverse_bytes` is fine for ASCII; `reverse_utf8` splits on lead bytes so multibyte characters are never cut in half.

