#include <iostream>
#include <queue>
#include <vector>

class MedianFinder {
    std::priority_queue<int> lo;                                 // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> hi; // min-heap
public:
    void add(int x) {
        lo.push(x);
        hi.push(lo.top());
        lo.pop();
        if (hi.size() > lo.size()) {
            lo.push(hi.top());
            hi.pop();
        }
    }
    double median() const {
        if (lo.empty()) return 0.0;  // undefined; caller should check
        if (lo.size() == hi.size()) return (lo.top() + hi.top()) / 2.0;
        return lo.top();
    }
};

int main() {
    MedianFinder mf;
    for (int x : {5, 1, 9, 3, 7}) {
        mf.add(x);
        std::cout << mf.median() << "\n";
    }
    return 0;
}
```

The max-heap holds the lower half, the min-heap the upper half; rebalancing keeps their sizes within one, so `median()` is always correct in O(log n) per insert.

