#include <cctype>
#include <cstddef>
#include <iostream>
#include <string>
#include <vector>

std::vector<std::size_t> find_all_ci(const std::string& haystack,
                                     const std::string& needle) {
    std::vector<std::size_t> hits;
    if (needle.empty()) return hits;          // empty needle: no matches
    if (needle.size() > haystack.size()) return hits;

    auto lower = [](unsigned char c) {
        return static_cast<unsigned char>(std::tolower(c));
    };

    const std::size_t last = haystack.size() - needle.size();
    for (std::size_t i = 0; i <= last; ++i) {
        bool match = true;
        for (std::size_t j = 0; j < needle.size(); ++j) {
            if (lower(haystack[i + j]) != lower(needle[j])) {
                match = false;
                break;
            }
        }
        if (match) hits.push_back(i);
    }
    return hits;
}

int main() {
    const std::string text = "Abracadabra ABRA cadabra";
    for (std::size_t pos : find_all_ci(text, "abra")) {
        std::cout << pos << '\n';
    }
    // Overlapping matches are reported: positions 0, 7, 11, 17.
    return 0;
}
```

