```rust
use std::collections::HashSet;
use std::hash::Hash;

/// Remove duplicates, keeping the first occurrence of each value.
/// Works for any `T: Eq + Hash + Clone`.
fn dedup_stable<T>(items: Vec<T>) -> Vec<T>
where
    T: Eq + Hash + Clone,
{
    let mut seen: HashSet<T> = HashSet::with_capacity(items.len());
    let mut out: Vec<T> = Vec::with_capacity(items.len());
    for item in items {
        if seen.insert(item.clone()) {
            out.push(item);
        }
    }
    out
}

fn main() {
    let words = vec!["b", "a", "b", "c", "a", "a"];
    assert_eq!(dedup_stable(words), vec!["b", "a", "c"]);

    let empty: Vec<i32> = Vec::new();
    assert_eq!(dedup_stable(empty), Vec::<i32>::new());

    let unicode = vec!["café", "cafe\u{301}", "café", "naïve"];
    // "café" and the decomposed form are distinct byte sequences: both kept.
    assert_eq!(dedup_stable(unicode).len(), 3);

    println!("ok");
}
```

`HashSet::insert` returns `true` only the first time a value appears, so the order of `out` matches first occurrence.

