```python
import re
from collections import Counter


def word_frequencies(path: str) -> dict:
    """Return a mapping of lowercased word -> count for the file at path.

    Punctuation is stripped and case is ignored. An empty or missing file
    yields an empty dict.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        return {}

    if not text.strip():
        return {}

    words = re.findall(r"[A-Za-z0-9']+", text.lower())
    return dict(Counter(words))


if __name__ == "__main__":
    import sys
    import json

    target = sys.argv[1] if len(sys.argv) > 1 else "sample.txt"
    print(json.dumps(word_frequencies(target), indent=2, sort_keys=True))
```

`re.findall` extracts word tokens; `Counter` does the tallying in one pass. The function catches `FileNotFoundError` and returns `{}` so callers never crash on a missing path, and a whitespace-only file also short-circuits to `{}`. Unicode letters outside ASCII (e.g. accented characters) are treated as separators by this regex; if you need full Unicode word boundaries, swap the pattern for `r"\b\w+\b"` with the `re.UNICODE` default.

```cpp
#include <algorithm>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

struct Interval {
    int start;
    int end;
};

std::vector<Interval> merge(std::vector<Interval> intervals) {
    std::vector<Interval> out;
    if (intervals.empty()) return out;

    std::sort(intervals.begin(), intervals.end(),
              [](const Interval& a, const Interval& b) {
                  return a.start < b.start;
              });

    out.push_back(intervals[0]);
    for (size_t i = 1; i < intervals.size(); ++i) {
        if (intervals[i].start <= out.back().end) {
            out.back().end = std::max(out.back().end, intervals[i].end);
        } else {
            out.push_back(intervals[i]);
        }
    }
    return out;
}

int main() {
    std::vector<Interval> intervals;
    std::string line;
    while (std::getline(std::cin, line)) {
        std::istringstream iss(line);
        int a, b;
        // Skip blank and malformed lines rather than crashing.
        if (iss >> a >> b && a <= b) {
            intervals.push_back({a, b});
        }
    }

    for (const Interval& iv : merge(intervals)) {
        std::cout << iv.start << " " << iv.end << "\n";
    }
    return 0;
}
```

Sorting by start makes the sweep a single linear pass: each new interval either extends the last merged block (`end = max(end, new_end)`) or starts a fresh one. Malformed lines are silently skipped so the program is robust to extra whitespace or a trailing blank line.

```rust
/// Iterative Fibonacci. `n` is 0-indexed: fib(0)=0, fib(1)=1.
/// Returns Err if the result would overflow u128, which happens around n=187.
fn fib(n: u32) -> Result<u128, String> {
    let (mut a, mut b) = (0u128, 1u128);
    for _ in 0..n {
        let next = a
            .checked_add(b)
            .ok_or_else(|| format!("fib({}) overflows u128", n))?;
        a = b;
        b = next;
    }
    Ok(a)
}

fn main() {
    for n in [0u32, 1, 10, 90, 200] {
        match fib(n) {
            Ok(v) => println!("fib({}) = {}", n, v),
            Err(e) => println!("fib({}) error: {}", n, e),
        }
    }
}
```

The loop keeps two adjacent values and rotates them, so it is O(n) time and O(1) space. `checked_add` turns potential overflow into a clean `Err` instead of a panic in release mode: `fib(200)` reports the overflow rather than silently wrapping. `fib(0)` correctly returns 0 because the loop body never runs.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least recently used

    def __contains__(self, key) -> bool:
        return key in self._data

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1     # 'a' becomes most recent
    cache.put("c", 3)              # evicts 'b'
    assert cache.get("b") is None
    assert cache.get("c") == 3
    assert len(cache) == 2
    print("all assertions passed")
```

`OrderedDict` preserves insertion order and `move_to_end` promotes a key on every access, so the front of the dict is always the least recently used entry. `popitem(last=False)` removes exactly that front item once capacity is exceeded. `get` returns `None` for a miss, and the `__main__` block exercises the eviction path so you can verify behaviour immediately.

