#include <stdio.h>
#include <string.h>

void reverse(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;              /* empty or single char: nothing to do */

    char *left = s;
    char *right = s + len - 1;
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        ++left;
        --right;
    }
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "x";
    char d[] = "ab";

    reverse(a);
    reverse(b);
    reverse(c);
    reverse(d);

    printf("[%s] [%s] [%s] [%s]\n", a, b, c, d);
    return 0;
    /* Output: [olleh] [] [x] [ba] */
}
