```cpp
#include <cctype>
#include <iostream>
#include <string>

bool is_palindrome(const std::string& s) {
    size_t left = 0;
    size_t right = s.size();

    while (left < right) {
        // Advance left past non-alphanumerics.
        while (left < right &&
               !std::isalnum(static_cast<unsigned char>(s[left]))) {
            ++left;
        }
        // Retreat right past non-alphanumerics.
        while (left < right &&
               !std::isalnum(static_cast<unsigned char>(s[right - 1]))) {
            --right;
        }
        if (left >= right) break;

        char a = std::tolower(static_cast<unsigned char>(s[left]));
        char b = std::tolower(static_cast<unsigned char>(s[right - 1]));
        if (a != b) return false;

        ++left;
        --right;
    }
    return true;
}

int main() {
    const char* tests[] = {
        "A man, a plan, a canal: Panama",
        "race a car",
        "",
        "a",
        "!!!",
        "No 'x' in Nixon",
    };
    for (const char* t : tests) {
        std::cout << (is_palindrome(t) ? "true  " : "false ") << t << "\n";
    }
    return 0;
}
```

The two pointers skip characters where `isalnum` is false, then compare lowercased pairs. Empty string and a single character are both palindromes, and `"!!!"` collapses to no comparable characters so it returns `true`. Casting each `char` to `unsigned char` before `isalnum`/`tolower` is required: passing a negative `char` to these functions is undefined behaviour for non-ASCII bytes.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

/* Reverses the list and returns the new head. */
Node *reverse_list(Node *head)
{
    Node *prev = NULL;
    Node *cur = head;

    while (cur != NULL) {
        Node *next = cur->next; /* save before rewiring */
        cur->next = prev;
        prev = cur;
        cur = next;
    }

    return prev;
}

static Node *push(Node *head, int v)
{
    Node *n = malloc(sizeof(*n));
    if (n == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = v;
    n->next = head;
    return n;
}

static void print_list(const Node *head)
{
    for (const Node *n = head; n != NULL; n = n->next)
        printf("%d%s", n->value, n->next ? " -> " : "\n");
}

static void free_list(Node *head)
{
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void)
{
    /* Build 1 -> 2 -> 3 -> 4 */
    Node *head = NULL;
    for (int i = 4; i >= 1; --i)
        head = push(head, i);

    print_list(head);
    head = reverse_list(head);
    print_list(head);

    /* Empty list edge case: reverse(NULL) == NULL */
    free_list(head);
    head = reverse_list(NULL);
    print_list(head);

    return 0;
}
```

The loop rewires each `next` pointer to the previously visited node, so a single pass suffices. `reverse_list(NULL)` and a one-element list both fall out naturally: `prev` starts as `NULL`, which becomes the tail's successor. The helper functions manage allocation and cleanup so the example runs under a leak checker without warnings.

