/// Keeps the first occurrence of each value, preserving order.
fn dedup_preserve_order(input: &[i32]) -> Vec<i32> {
    let mut seen = HashSet::with_capacity(input.len());
    let mut out = Vec::with_capacity(input.len());

    for &v in input {
        if seen.insert(v) {
            out.push(v);
        }
    }

    out
}

fn main() {
    let cases: Vec<Vec<i32>> = vec![
        vec![],
        vec![1],
        vec![1, 1, 1],
        vec![3, 1, 3, 2, 1, 2, 4],
        vec![-1, 0, -1, 0, 5],
        vec![i32::MIN, i32::MAX, i32::MIN],
    ];

    for c in &cases {
        println!("{:?} -> {:?}", c, dedup_preserve_order(c));
    }
}
