```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node* next;
} Node;

Node* push(Node* head, int value) {
    Node* n = malloc(sizeof(Node));
    if (!n) { perror("malloc"); exit(1); }
    n->value = value;
    n->next = head;
    return n;
}

Node* reverse(Node* head) {
    Node* prev = NULL;
    while (head) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void print(Node* head) {
    for (; head; head = head->next)
        printf("%d ", head->value);
    printf("\n");
}

void free_list(Node* head) {
    while (head) { Node* n = head->next; free(head); head = n; }
}

int main(void) {
    Node* list = NULL;
    reverse(list);              /* empty list is fine */
    print(list);                /* prints blank line */
    for (int i = 1; i <= 5; i++) list = push(list, i);
    print(list);                /* 5 4 3 2 1 */
    list = reverse(list);
    print(list);                /* 1 2 3 4 5 */
    free_list(list);
    return 0;
}
```

The iterative reverse touches no allocation and works on a NULL head, so the empty case prints just a newline instead of crashing.

