#include <cassert>
#include <cstddef>
#include <cstdio>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity), size_(0), head_(0) {}

    bool push(double v) {
        if (size_ == cap_) return false;
        buf_[(head_ + size_) % cap_] = v;
        ++size_;
        return true;
    }

    bool pop(double& out) {
        if (size_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return true;
    }

    double average() const {
        if (size_ == 0) return 0.0;
        double sum = 0.0;
        for (std::size_t i = 0; i < size_; ++i)
            sum += buf_[(head_ + i) % cap_];
        return sum / static_cast<double>(size_);
    }

    std::size_t size() const { return size_; }

private:
    std::vector<double> buf_;
    std::size_t cap_, size_, head_;
};

int main() {
    RingBuffer rb(3);
    assert(rb.push(1.0) && rb.push(2.0) && rb.push(3.0));
    assert(!rb.push(4.0));            // full
    assert(rb.average() == 2.0);
    double v = 0.0;
    assert(rb.pop(v) && v == 1.0);
    assert(rb.push(4.0));
    assert(rb.average() == 3.0);
    std::printf("size=%zu avg=%.2f\n", rb.size(), rb.average());
    return 0;
}
```

The buffer never allocates after construction; `push` fails when full and `pop` fails when empty. `average` walks at most `cap_` elements and returns 0 for an empty buffer so callers avoid division by zero.

