#include <ctype.h>
#include <limits.h>
#include <stdbool.h>
#include <stdio.h>

bool parse_long(const char* s, long* out) {
    if (!s || !*s) return false;
    const char* p = s;
    bool neg = false;
    if (*p == '+' || *p == '-') {
        neg = (*p == '-');
        ++p;
    }
    if (!isdigit((unsigned char)*p)) return false;

    long value = 0;
    for (; *p; ++p) {
        if (!isdigit((unsigned char)*p)) return false;  /* trailing garbage */
        int digit = *p - '0';
        if (neg) {
            if (value < (LONG_MIN + digit) / 10) return false;
            value = value * 10 - digit;
        } else {
            if (value > (LONG_MAX - digit) / 10) return false;
            value = value * 10 + digit;
        }
    }
    *out = value;
    return true;
}

int main(void) {
    const char* tests[] = {"123", "-42", "007", "12x", "", "99999999999999999999"};
    for (int i = 0; i < 6; ++i) {
        long v = 0;
        printf("%-22s -> %s\n", tests[i], parse_long(tests[i], &v) ? "ok" : "rejected");
        if (parse_long(tests[i], &v)) printf("    value=%ld\n", v);
    }
    return 0;
}
```

Overflow is checked *before* multiplying by ten so it cannot wrap. `isdigit` is called on an `unsigned char` cast to avoid undefined behaviour on negative bytes. Any non-digit after the first digit—including a space—causes rejection.

