struct Stats {
    bool ok = false;
    double mean = 0.0;
    double sd = 0.0;
};

Stats summarize(const std::vector<double>& xs) {
    Stats s;
    if (xs.empty()) return s;
    double sum = 0.0;
    for (double x : xs) sum += x;
    s.mean = sum / static_cast<double>(xs.size());
    if (xs.size() < 2) {
        s.ok = true;          // mean defined, sd not
        s.sd = 0.0;
        return s;
    }
    double sq = 0.0;
    for (double x : xs) sq += (x - s.mean) * (x - s.mean);
    s.sd = std::sqrt(sq / static_cast<double>(xs.size() - 1));
    s.ok = true;
    return s;
}

int main() {
    for (auto v : {std::vector<double>{}, std::vector<double>{5.0},
                   std::vector<double>{2, 4, 4, 4, 5, 5, 7, 9}}) {
        Stats s = summarize(v);
        if (!s.ok) { std::printf("empty -> undefined\n"); continue; }
        std::printf("n=%zu mean=%.4f sd=%.4f\n", v.size(), s.mean, s.sd);
    }
    return 0;
}
