```rust
fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

fn main() {
    let data = [1, 3, 5, 7, 9, 11];
    assert_eq!(binary_search(&data, &7), Some(3));
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &11), Some(5));
    assert_eq!(binary_search(&data, &4), None);
    let empty: [i32; 0] = [];
    assert_eq!(binary_search(&empty, &1), None);
    println!("all assertions passed");
}
```

`mid = lo + (hi - lo) / 2` avoids overflow; `hi` is exclusive so an empty slice exits the loop immediately and returns `None`.

