pub fn dedup_in_place<T: PartialEq>(data: &mut [T]) -> usize {
    if data.is_empty() {
        return 0;
    }
    let mut write = 1usize;
    for read in 1..data.len() {
        if data[read] != data[write - 1] {
            data[write] = data[read];
            write += 1;
        }
    }
    write
}

fn main() {
    let mut a = [1, 1, 2, 3, 3, 3, 4];
    let n = dedup_in_place(&mut a);
    assert_eq!(&a[..n], &[1, 2, 3, 4]);

    let mut b: [i32; 0] = [];
    assert_eq!(dedup_in_place(&mut b), 0);

    let mut c = [7];
    assert_eq!(dedup_in_place(&mut c), 1);
    println!("ok");
}
```
The read pointer scans forward and the write pointer marks where the next kept element goes; writing into `data[write]` is safe because `write <= read` always holds, so no element is overwritten before it is read.

