def is_valid_ipv4(s: str) -> bool:
    """Return True if s is a dotted-quad IPv4 address with no leading zeros."""
    if not isinstance(s, str):
        return False
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        # Reject leading zeros like "01", but allow a bare "0".
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False
    return True


