from typing import Dict, Iterable, List, Set, Tuple

def parse_pairs(lines: Iterable[str]) -> Tuple[Dict[str, str], Set[str]]:
    """Parse 'key=value' lines into a dict.

    Malformed lines (no '=', empty key) are skipped. Duplicate keys are
    reported and the last occurrence wins.
    """
    result: Dict[str, str] = {}
    duplicates: Set[str] = set()
    for raw in lines:
        line = raw.strip()
        if not line or "=" not in line:
            continue
        key, _, value = line.partition("=")
        key = key.strip()
        if not key:
            continue
        if key in result:
            duplicates.add(key)
        result[key] = value.strip()
    return result, duplicates

if __name__ == "__main__":
    data = ["a=1", "b=2", "garbage", "a=9", "=novalue", "c=3", " b = 4 "]
