#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
T median(std::vector<T> values) {
    if (values.empty()) {
        throw std::invalid_argument("median of empty vector");
    }
    std::size_t n = values.size();
    std::size_t mid = n / 2;
    std::nth_element(values.begin(), values.begin() + mid, values.end());
    if (n % 2 == 1) {
        return values[mid];
    }
    T upper = values[mid];
    std::nth_element(values.begin(), values.begin() + mid - 1, values.end());
    T lower = values[mid - 1];
    return static_cast<T>(lower / 2 + upper / 2 + (lower % 2 + upper % 2) / 2);
}

int main() {
    std::cout << median(std::vector<int>{5, 1, 9}) << '\n';        // 5
    std::cout << median(std::vector<int>{1, 2, 3, 4}) << '\n';      // 2
    std::cout << median(std::vector<double>{1.5, 2.5}) << '\n';     // 2.0
    try {
        median(std::vector<int>{});
    } catch (const std::invalid_argument& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
