    for i in range(5):
        buf.append(i)
    assert list(buf) == [2, 3, 4]
    assert buf.pop_oldest() == 2
    assert len(buf) == 2
    try:
        RingBuffer(0)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
