```c
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) return;
    right--;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char buf[] = "hello";
    reverse_in_place(buf);
    printf("%s\n", buf); // olleh

    char empty[] = "";
    reverse_in_place(empty);
    printf("%s\n", empty); // (empty line)
    return 0;
}
```

The two-pointer swap runs in O(n) time and O(1) extra space; `right` is decremented before the loop so it points at the last valid character. On 8-bit bytes this is byte reversal, which is the expected behavior for plain `char` strings.

