    }

    bool full() const { return size_ == capacity_; }
    bool empty() const { return size_ == 0; }

    bool push(const T& value) {
        if (full()) return false;
        data_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

private:
    std::vector<T> data_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};
```

`push` returns false when full and `pop` returns `std::nullopt` when empty, so neither call throws for normal flow. `head_` and `size_` index modulo the capacity, giving O(1) operations without shifting elements.

