def check_brackets(s: str):
    """Return (True, -1) if balanced, else (False, index of first offending char)."""
    pairs = {")": "(", "]": "[", "}": "{"}
    openers = set(pairs.values())
    stack = []
    for i, ch in enumerate(s):
        if ch in openers:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False, i
    if stack:
        return False, len(s)  # unclosed opener stays on stack
    return True, -1


