def parse_int(s: str) -> int:
    """Parse a decimal integer literal. Raises ValueError on any junk."""
    i, n = 0, len(s)
    while i < n and s[i] == " ":
        i += 1
    sign = 1
    if i < n and s[i] in "+-":
        if s[i] == "-":
            sign = -1
        i += 1
    if i >= n or not s[i].isdigit():
        raise ValueError(f"not a number: {s!r}")
    value = 0
    while i < n and s[i].isdigit():
        value = value * 10 + (ord(s[i]) - ord("0"))
        i += 1
    while i < n and s[i] == " ":
        i += 1
    if i != n:
        raise ValueError(f"trailing junk: {s!r}")
    return sign * value


if __name__ == "__main__":
    assert parse_int("0") == 0
    assert parse_int("-42") == -42
    assert parse_int("  +7 ") == 7
    assert parse_int("2147483648") == 2147483647 + 1
    for bad in ["", " ", "+", "1.5", "12x", "--3"]:
        try:
            parse_int(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"should have failed: {bad!r}")
