#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int val; struct Node *next; } Node;

static Node *push(Node *head, int val) {
    Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(1); }
    n->val = val;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(const Node *head) {
    for (; head; head = head->next) printf("%d%s", head->val, head->next ? " " : "\n");
}

static void free_list(Node *head) {
    while (head) { Node *next = head->next; free(head); head = next; }
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++) head = push(head, i); // 5 4 3 2 1
    head = reverse(head);
    print_list(head); // 1 2 3 4 5
    free_list(head);

    head = NULL; // empty list is valid input
    print_list(reverse(head));
    return 0;
}
