def parse(lines):
    sums = defaultdict(float)
    counts = defaultdict(int)
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        parts = line.split(",")
        if len(parts) != 2:
            continue
        name, score = parts[0].strip(), parts[1].strip()
        if not name:
            continue
        try:
            value = float(score)
        except ValueError:
            continue
        sums[name] += value
        counts[name] += 1
    return {n: sums[n] / counts[n] for n in sums}


def main():
