#include <cctype>
#include <iostream>
#include <string>
#include <vector>

bool is_valid_ipv4(const std::string& s) {
    int octets = 0;
    std::size_t i = 0;
    while (i < s.size()) {
        int value = 0;
        int digits = 0;
        while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
            value = value * 10 + (s[i] - '0');
            ++digits;
            ++i;
            if (digits > 3) return false;
        }
        if (digits == 0 || value > 255) return false;
        if (digits > 1 && s[i - digits] == '0') return false;  // no leading zeros
        ++octets;
        if (i == s.size()) break;
        if (s[i] != '.') return false;
        ++i;
        if (i == s.size()) return false;  // trailing dot
    }
    return octets == 4;
}

int main() {
    std::vector<std::string> cases = {
        "192.168.0.1", "0.0.0.0", "255.255.255.255",
        "256.1.1.1", "1.2.3", "1.2.3.4.5", "01.2.3.4", "1.2.3."
    };
    for (const auto& c : cases)
        std::cout << c << " -> " << (is_valid_ipv4(c) ? "valid" : "invalid") << '\n';
    return 0;
}
