    assert_eq!(merge_sorted(&[1, 3, 5], &[]), vec![1, 3, 5]);
    assert_eq!(merge_sorted(&[1, 4, 9], &[2, 3, 10]), vec![1, 2, 3, 4, 9, 10]);
    assert_eq!(merge_sorted(&[2, 2], &[2, 2]), vec![2, 2, 2, 2]);
    println!("ok");
}
