```cpp
#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

 template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& item) {
        if (count_ == N) {
            return false;
        }
        data_[(head_ + count_) % N] = item;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) {
            return std::nullopt;
        }
        T item = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return item;
    }

    std::size_t size() const noexcept { return count_; }
    bool empty() const noexcept { return count_ == 0; }
    bool full() const noexcept { return count_ == N; }

private:
    static_assert(N > 0, "capacity must be positive");
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;                 // full, must reject
    if (rb.pop() != std::optional<int>{1}) return 1;
    if (!rb.push(4)) return 1;                // slot free now
    if (rb.pop() != std::optional<int>{2}) return 1;
    return rb.size() == 2 ? 0 : 1;
}
```

`push` returns `false` when full instead of overwriting; `pop` returns `std::nullopt` when empty. Indexing wraps with modulo, so no shifting is needed. `std::array` stores elements inline, requiring `T` to be default-constructible; the `static_assert` rejects a zero capacity at compile time. The `main` below exercises the wrap-around arithmetic.

