#[derive(Clone, Copy)]
enum Quote {
    Single,
    Double,
}

pub fn brackets_balanced(input: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    let mut quote: Option<Quote> = None;
    let mut chars = input.chars();

    while let Some(ch) = chars.next() {
        match quote {
            Some(q) => {
                if ch == '\\' {
                    chars.next();
                } else if (ch == '\'' && matches!(q, Quote::Single))
                    || (ch == '"' && matches!(q, Quote::Double))
                {
                    quote = None;
                }
            }
            None => match ch {
                '\'' => quote = Some(Quote::Single),
                '"' => quote = Some(Quote::Double),
                '(' | '[' | '{' => stack.push(ch),
                ')' => if stack.pop() != Some('(') { return false; },
                ']' => if stack.pop() != Some('[') { return false; },
                '}' => if stack.pop() != Some('{') { return false; },
                _ => {}
            },
        }
    }
    stack.is_empty() && quote.is_none()
}

#[cfg(test)]
mod tests {
    use super::brackets_balanced;

    #[test]
    fn plain_cases() {
        assert!(brackets_balanced("([{}])"));
        assert!(!brackets_balanced("([)]"));
        assert!(!brackets_balanced("("));
        assert!(brackets_balanced(""));
    }

    #[test]
    fn brackets_inside_quotes_are_ignored() {
        assert!(brackets_balanced("f(\")\")"));
        assert!(brackets_balanced("let s = '(unclosed'"));
    }

    #[test]
    fn unterminated_quote_fails() {
        assert!(!brackets_balanced("f(\"no close"));
    }
}
```

A single stack holds expected openers; each closer must match the top. The quote state machine suppresses bracket handling inside `'...'` or `"..."`, honours backslash escapes, and reports failure if a quote is never closed. `chars.next()` inside the escape branch consumes the escaped character so `\"` does not terminate the string.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(lo: int, hi: int) -> tuple[int, int]:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    print(longest_palindrome("babad"))  # bab
    print(longest_palindrome("cbbd"))   # bb
    print(longest_palindrome(""))       # ''
    print(longest_palindrome("forgeeksskeegfor"))
```

Both odd and even centers are checked, so `"cbbd"` yields `"bb"`. O(n²) time, O(1) space.

