            high.pop();
        }

        double median = (low.size() == high.size())
            ? (low.top() + high.top()) / 2.0
            : double(low.top());
        std::cout << median << '\n';
    }
    return 0;
}
```

The max-heap keeps the lower half and the min-heap the upper half. When sizes differ, the max-heap holds the extra element, so the median is its top; when equal, average both tops.

```rust
fn merge_sorted<T: Ord + Copy>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 4, 6];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 4, 5, 6, 7]);
    let empty: [i32; 0] = [];
    assert_eq!(merge_sorted(&empty, &empty), Vec::<i32>::new());
    println!("ok");
}
```

`T: Copy` lets the slices stay owned by the caller while pushing copied values into the output, and the trailing `extend_from_slice` handles whatever remains after one side is exhausted.

