    for (int i = 1; i <= 5; i++) head = push(head, i); // 5 4 3 2 1
    head = reverse(head);                              // 1 2 3 4 5
    for (Node *p = head; p; p = p->next) printf("%d ", p->value);
    putchar('\n');

    while (head) { Node *t = head->next; free(head); head = t; }
    return 0;
}
