```rust
pub struct RingBuffer {
    data: Vec<f64>,
    head: usize,
    len: usize,
}

impl RingBuffer {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        RingBuffer { data: vec![0.0; capacity], head: 0, len: 0 }
    }

    pub fn push(&mut self, value: f64) {
        let cap = self.data.len();
        let idx = (self.head + self.len) % cap;
        self.data[idx] = value;
        if self.len < cap {
            self.len += 1;
        } else {
            self.head = (self.head + 1) % cap;
        }
    }

    pub fn iter(&self) -> impl Iterator<Item = f64> + '_ {
        let cap = self.data.len();
        (0..self.len).map(move |i| self.data[(self.head + i) % cap])
    }

    pub fn mean(&self) -> Option<f64> {
        if self.len == 0 {
            return None;
        }
        Some(self.iter().sum::<f64>() / self.len as f64)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn wraps_and_averages() {
        let mut rb = RingBuffer::new(3);
        assert_eq!(rb.mean(), None);
        for v in [1.0, 2.0, 3.0, 4.0] {
            rb.push(v);
        }
        assert_eq!(rb.iter().collect::<Vec<_>>(), vec![2.0, 3.0, 4.0]);
        assert_eq!(rb.mean(), Some(3.0));
    }
}
