#include <cassert>
#include <iostream>
#include <algorithm>

template <typename T>
constexpr T clamp_range(T value, T lo, T hi) {
    // If bounds are reversed, normalize them.
    if (hi < lo) std::swap(lo, hi);
    if (value < lo) return lo;
    if (value > hi) return hi;
    return value;
}

int main() {
    assert(clamp_range(5, 0, 10) == 5);
    assert(clamp_range(-3, 0, 10) == 0);
    assert(clamp_range(42, 0, 10) == 10);
    assert(clamp_range(5, 10, 0) == 5);      // reversed bounds
    assert(clamp_range(0, 0, 0) == 0);        // degenerate interval
    assert(clamp_range(2.5, 1.0, 2.0) == 2.0); // double
    assert(clamp_range('z', 'a', 'm') == 'm'); // char

    std::cout << clamp_range(-7, -5, 5) << "\n";
    return 0;
}
```

`std::swap` normalizes reversed bounds so the contract is total rather than undefined. The template works for any type with `<` and `>` — integers, floats, chars.

