pub fn longest_common_prefix(words: &[String]) -> String {
    let Some(first) = words.first() else {
        return String::new();
    };
    let mut end = first.len();
    for w in &words[1..] {
        let mut i = 0;
        let a = first.as_bytes();
        let b = w.as_bytes();
        while i < end && i < b.len() && a[i] == b[i] {
            i += 1;
        }
        // Back off to a char boundary so we never split a UTF-8 sequence.
        while i > 0 && !first.is_char_boundary(i) {
            i -= 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    first[..end].to_string()
}

fn main() {
    let a = vec!["flower".to_string(), "flow".to_string(), "flight".to_string()];
    let b = vec!["café".to_string(), "cafétéria".to_string()];
    let c: Vec<String> = vec![];
    println!("{:?}", longest_common_prefix(&a)); // "fl"
    println!("{:?}", longest_common_prefix(&b)); // "café"
    println!("{:?}", longest_common_prefix(&c)); // ""
}
