```python
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least-recently used

    def __len__(self):
        return len(self._data)

if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1); c.put("b", 2)
    print(c.get("a"))   # 1, and 'a' is now most-recent
    c.put("c", 3)       # evicts 'b'
    print(c.get("b"))   # None
    print(c.get("c"))   # 3
```

OrderedDict preserves insertion order and `move_to_end` marks recency in O(1). `popitem(last=False)` removes the oldest key, which is the least-recently used one. Rejecting non-positive capacity up front avoids a cache that silently discards every insert.

