use std::collections::HashMap;

#[derive(Debug)]
pub struct Config {
    pub sections: HashMap<String, HashMap<String, String>>,
}

impl Config {
    pub fn parse(input: &str) -> Result<Config, String> {
        let mut sections: HashMap<String, HashMap<String, String>> = HashMap::new();
        let mut current = String::from("default");
        sections.entry(current.clone()).or_default();

        for (lineno, raw) in input.lines().enumerate() {
            let line = raw.trim();
            if line.is_empty() || line.starts_with(';') || line.starts_with('#') {
                continue;
            }
            if line.starts_with('[') {
                if !line.ends_with(']') || line.len() < 3 {
                    return Err(format!("line {}: malformed section header", lineno + 1));
                }
                current = line[1..line.len() - 1].trim().to_string();
                sections.entry(current.clone()).or_default();
            } else if let Some((k, v)) = line.split_once('=') {
                let key = k.trim();
                if key.is_empty() {
                    return Err(format!("line {}: empty key", lineno + 1));
                }
                sections
                    .entry(current.clone())
                    .or_default()
                    .insert(key.to_string(), v.trim().to_string());
            } else {
                return Err(format!("line {}: expected 'key = value'", lineno + 1));
            }
        }
        Ok(Config { sections })
    }
}

fn main() {
    let text = "[server]\nhost = localhost\nport = 8080\n\n; comment\n[db]\nname = app\n";
    match Config::parse(text) {
        Ok(c) => println!("{:?}", c.sections.get("server").unwrap().get("port")),
        Err(e) => eprintln!("error: {e}"),
    }
}
```

The parser tracks the current section (defaulting to `"default"`) and returns a line-numbered error for anything that is neither a comment, a section header, nor a `key = value` pair. `split_once` keeps values containing `=` intact, and `.trim()` tolerates ragged whitespace around keys and values.

