#include <iostream>
#include <stack>
#include <string>

std::pair<bool, size_t> check_brackets(const std::string& s) {
    std::stack<std::pair<char, size_t>> st;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push({c, i});
        } else if (c == ')' || c == ']' || c == '}') {
            char want = (c == ')') ? '(' : (c == ']') ? '[' : '{';
            if (st.empty() || st.top().first != want) {
                return {false, i};
            }
            st.pop();
        }
    }
    if (!st.empty()) {
        return {false, st.top().second};
    }
    return {true, s.size()};
}

int main() {
    const char* tests[] = {"a(b[c]{d})e", "(]", "(((", "}{ "};
    for (const char* t : tests) {
        auto [ok, pos] = check_brackets(t);
        if (ok) std::cout << "\"" << t << "\" ok\n";
        else    std::cout << "\"" << t << "\" mismatch at index " << pos << '\n';
    }
