            crc ^= buf[i];
            for (int k = 0; k < 8; ++k) {
                uint32_t mask = -(crc & 1u);
                crc = (crc >> 1) ^ (0xEDB88320u & mask);
            }
        }
    }
    std::fclose(f);
    std::printf("%08x\n", crc ^ 0xFFFFFFFFu);
    return 0;
}
