pub fn merge_unique(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        let v = if a[i] <= b[j] { let x = a[i]; i += 1; x }
                else { let x = b[j]; j += 1; x };
        if out.last() != Some(&v) {
            out.push(v);
        }
    }
    while i < a.len() {
        let v = a[i]; i += 1;
        if out.last() != Some(&v) { out.push(v); }
    }
    while j < b.len() {
        let v = b[j]; j += 1;
        if out.last() != Some(&v) { out.push(v); }
    }
    out
}
