fn lower_bound<T: Ord>(data: &[T], target: &T) -> usize {
    let mut lo = 0usize;
    let mut hi = data.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if &data[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

fn main() {
    let data = [1, 3, 3, 5, 8];
    assert_eq!(lower_bound(&data, &3), 1);
    assert_eq!(lower_bound(&data, &4), 3);
    assert_eq!(lower_bound(&data, &9), 5);
    assert_eq!(lower_bound(&data, &0), 0);
    assert_eq!(lower_bound::<i32>(&[], &5), 0);
    println!("ok");
}
