```python
import functools
import time

def retry(attempts=3, base_delay=0.5, backoff=2.0, exceptions=(Exception,)):
    """Retry the wrapped function, doubling the delay each failure."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            last = None
            for n in range(attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if n == attempts - 1:
                        raise
                    time.sleep(delay)
                    delay *= backoff
            raise last  # unreachable
        return wrapper
    return decorator

@retry(attempts=3, base_delay=0.01)
def flaky():
    raise ConnectionError("boom")

if __name__ == "__main__":
    try:
        flaky()
    except ConnectionError as e:
        print("gave up:", e)
```

The decorator re-raises the final exception, preserving the traceback type. `functools.wraps` keeps the wrapped function's name and docstring intact for introspection.

