```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

template <typename T>
class Queue {
public:
    void push(T value) {
        {
            std::lock_guard<std::mutex> lock(mu_);
            data_.push(std::move(value));
        }
        cv_.notify_one();
    }

    std::optional<T> try_pop() {
        std::lock_guard<std::mutex> lock(mu_);
        if (data_.empty()) return std::nullopt;
        T value = std::move(data_.front());
        data_.pop();
        return value;
    }

    bool wait_pop(T& out) {
        std::unique_lock<std::mutex> lock(mu_);
        cv_.wait(lock, [this] { return !data_.empty() || closed_; });
        if (data_.empty()) return false;
        out = std::move(data_.front());
        data_.pop();
        return true;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mu_);
            closed_ = true;
        }
        cv_.notify_all();
    }

private:
    std::queue<T> data_;
    std::mutex mu_;
    std::condition_variable cv_;
    bool closed_ = false;
};
```

`push` moves the value under the lock and notifies one waiter. `try_pop` is non-blocking and returns `nullopt` when empty. `wait_pop` blocks until data arrives or `close()` is called, and `close()` wakes every waiter so shutdown is clean.

