```rust
/// Returns (F(n), F(n + 1)) using fast doubling in O(log n) multiplications.
fn fib_pair(n: u64) -> (u128, u128) {
    if n == 0 {
        return (0, 1);
    }
    let (a, b) = fib_pair(n >> 1);
    let c = a * (2 * b - a);
    let d = a * a + b * b;
    if n & 1 == 0 {
        (c, d)
    } else {
        (d, c + d)
    }
}

pub fn fib(n: u64) -> u128 {
    fib_pair(n).0
}

#[cfg(test)]
mod tests {
    use super::fib;

    #[test]
    fn base_cases() {
        assert_eq!(fib(0), 0);
        assert_eq!(fib(1), 1);
        assert_eq!(fib(2), 1);
        assert_eq!(fib(10), 55);
        assert_eq!(fib(20), 6765);
    }

    #[test]
    fn large_index_fits_in_u128() {
        // F(186) is the last value that fits in u128.
        assert_eq!(fib(186), 332825110087067562321196029789634457848);
    }
}
```

Fast doubling uses the identities F(2k) = F(k)(2F(k+1) - F(k)) and F(2k+1) = F(k)^2 + F(k+1)^2, so each call halves `n` and runs in O(log n). `u128` tops out at F(186); requesting a larger index overflows and panics in debug builds.

