def is_valid_ipv4(s: str) -> bool:
    """Return True only for dotted-quad IPv4 strings with four numeric
    octets in 0.255, no leading zeros except '0' itself."""
    if not isinstance(s, str):
        return False
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if not (0 <= int(part) <= 255):
            return False
    return True


if __name__ == "__main__":
    good = ["0.0.0.0", "127.0.0.1", "255.255.255.255", "192.168.1.1", "8.8.4.4"]
    bad = ["256.1.1.1", "1.2.3", "1.2.3.4.5", "01.2.3.4", "1.2.3.-1", "", "1.2.3.a", " 1.2.3.4", "1..3.4"]
    for ip in good:
        assert is_valid_ipv4(ip), ip
    for ip in bad:
        assert not is_valid_ipv4(ip), ip
    print("all checks passed")
