        return -1;
    }

    for (long i = 0; i < size / 2; ++i) {
        long j = size - 1 - i;
        unsigned char a, b;

        if (fseek(fp, i, SEEK_SET) != 0) { perror("fseek i"); fclose(fp); return -1; }
        if (fread(&a, 1, 1, fp) != 1) { perror("fread i"); fclose(fp); return -1; }

        if (fseek(fp, j, SEEK_SET) != 0) { perror("fseek j"); fclose(fp); return -1; }
        if (fread(&b, 1, 1, fp) != 1) { perror("fread j"); fclose(fp); return -1; }

        if (fseek(fp, i, SEEK_SET) != 0) { perror("fseek back i"); fclose(fp); return -1; }
        if (fwrite(&b, 1, 1, fp) != 1) { perror("fwrite b"); fclose(fp); return -1; }

        if (fseek(fp, j, SEEK_SET) != 0) { perror("fseek back j"); fclose(fp); return -1; }
        if (fwrite(&a, 1, 1, fp) != 1) { perror("fwrite a"); fclose(fp); return -1; }
    }

    fclose(fp);
    return 0;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 2;
    }
    return reverse_file(argv[1]) == 0 ? 0 : 1;
}
```

The loop swaps the byte at `i` with the byte at `size-1-i` and stops at `size/2`, so for an odd length the middle byte is simply left untouched. `fread` and `fwrite` are checked against 1 byte each and every `fseek` is checked, so a partial or failed I/O reports through `perror` and returns nonzero instead of silently producing a corrupt file. The mode is `"r+b"`, which requires the file to exist and allows both reads and writes.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)

    def keys(self):
        return list(self._data.keys())


if __name__ == "__main__":
    cache = LRUCache(3)
    cache.put("a", 1)
    cache.put("b", 2)
    cache.put("c", 3)
    assert cache.get("a") == 1          # 'a' is now most recent
    cache.put("d", 4)                    # evicts 'b'
    assert cache.keys() == ["c", "a", "d"]
    assert cache.get("b") is None
    cache.put("c", 30)                    # refresh existing key
    assert cache.keys() == ["a", "d", "c"]
    cache.put("e", 5)                     # evicts 'a'
    assert cache.get("a") is None
    assert len(cache) == 3
    print("ok")
```

`OrderedDict.move_to_end` on both `get` and `put` keeps recency ordering in O(1), and `popitem(last=False)` removes the least recently used entry when capacity is exceeded. Calling `put` on an existing key refreshes it before inserting, so an update does not trigger eviction of the wrong entry. The boundary is `len > capacity`, so inserting the `capacity+1`-th distinct key evicts exactly one.

```cpp
#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>

using Interval = std::pair<int, int>;

std::vector<Interval> merge_intervals(std::vector<Interval> intervals) {
    std::vector<Interval> merged;
    if (intervals.empty()) {
        return merged;
    }

    std::sort(intervals.begin(), intervals.end(),
              [](const Interval& a, const Interval& b) {
                  if (a.first != b.first) return a.first < b.first;
                  return a.second < b.second;
              });

    merged.push_back(intervals.front());
    for (std::size_t i = 1; i < intervals.size(); ++i) {
        Interval& back = merged.back();
        const Interval& cur = intervals[i];
        if (cur.first <= back.second) {
            back.second = std::max(back.second, cur.second);
        } else {
            merged.push_back(cur);
        }
    }
    return merged;
}

int main() {
    std::vector<Interval> input = {{1, 3}, {2, 6}, {8, 10}, {15, 18}, {9, 9}};
    auto out = merge_intervals(input);
    for (const auto& [lo, hi] : out) {
        std::cout << "[" << lo << ", " << hi << "]\n";
    }

    std::vector<Interval> empty;
    std::cout << "empty size: " << merge_intervals(empty).size() << "\n";

    std::vector<Interval> single = {{7, 7}};
    std::cout << "single: [" << single[0].first << ", " << merge_intervals(single)[0].second << "]\n";
}
```

Sorting by start (then end) puts every interval in a position where only the previous merged tail can overlap it. The condition `cur.first <= back.second` merges touching or overlapping ranges and uses `std::max` so a nested interval like `{2, 6}` does not shrink the tail it sits inside. Empty input returns early because `merged.front()` would otherwise read an empty vector. Sorting is O(n log n); the merge pass is O(n).

```python
def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring of s (expand-around-center)."""
    if not s:
        return ""

    start, end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1  # last valid bounds

    for i in range(len(s)):
        l1, r1 = expand(i, i)       # odd-length centres
        l2, r2 = expand(i, i + 1)   # even-length centres
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["", "a", "babad", "cbbd", "forgeeksskeegfor", "中文", "ab"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
