        std::cerr << "error: k out of range (1.." << nums.size() << ")\n";
        return 1;
    }

    // Max-heap of size k: top is the k-th smallest after all insertions.
    std::priority_queue<long long> heap;
    for (long long x : nums) {
        heap.push(x);
        if (static_cast<int>(heap.size()) > k) heap.pop();
    }

