    if (!std::getline(std::cin, s)) return 0;

    std::stack<std::pair<char, std::size_t>> st;
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push({c, i});
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) {
                std::cout << "unbalanced: unmatched '" << c << "' at index " << i << '\n';
                return 0;
            }
            if (!matches(st.top().first, c)) {
                std::cout << "unbalanced: '" << st.top().first << "' at index "
                          << st.top().second << " closed by '" << c << "' at index " << i << '\n';
                return 0;
            }
            st.pop();
        }
    }

    if (st.empty()) {
        std::cout << "balanced\n";
    } else {
        std::cout << "unbalanced: '" << st.top().first << "' at index "
                  << st.top().second << " never closed\n";
    }
    return 0;
