use std::io::{self, Read};

const MOD: u64 = 1_000_000_007;

/// Returns (F(n), F(n+1)) modulo MOD using fast doubling.
fn fib_pair(n: u64) -> (u64, u64) {
    if n == 0 {
        return (0, 1);
    }
    let (a, b) = fib_pair(n >> 1);
    let c = (a * ((2 * b + MOD - a) % MOD)) % MOD; // F(2k)
    let d = (a * a + b * b) % MOD;                // F(2k+1)
    if n & 1 == 0 {
        (c, d)
    } else {
        (d, (c + d) % MOD)
    }
}

