static void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; ++i) {
        char tmp = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = tmp;
    }
}

int main(void) {
    char buf[256];

    if (fgets(buf, sizeof buf, stdin) == NULL) {
        return 0; /* empty input: nothing to do */
    }

    /* Strip a trailing newline if present so it is not moved to the front. */
    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] == '\n') {
        buf[len - 1] = '\0';
    }

    reverse_in_place(buf);
    puts(buf);
    return 0;
}
