bool parse_int(const char *s, long *out) {
    if (s == NULL || *s == '\0') return false;

    int sign = 1;
    if (*s == '+' || *s == '-') {
        if (*s == '-') sign = -1;
        s++;
    }
    if (!isdigit((unsigned char)*s)) return false;

    long acc = 0;
    while (isdigit((unsigned char)*s)) {
        int d = *s - '0';
        if (acc > (LONG_MAX - d) / 10) return false;  /* overflow */
        acc = acc * 10 + d;
        s++;
    }
    if (*s != '\0') return false;  /* trailing junk */

    *out = sign * acc;
    return true;
}

