#include <cstdint>
#include <iostream>
#include <queue>
#include <stdexcept>
#include <vector>

int main() {
    std::priority_queue<int> low;                                  // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap

    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) {
            low.push(x);
        } else {
            high.push(x);
        }
        // Rebalance so low.size() == high.size() or low.size() == high.size() + 1.
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        if (low.size() == high.size()) {
            // Both non-empty here because low.size() >= high.size() >= 1.
            std::int64_t sum = static_cast<std::int64_t>(low.top()) + high.top();
            std::cout << sum / 2 << (sum % 2 != 0 ? ".5" : ".0") << '\n';
        } else {
            std::cout << low.top() << '\n';
        }
    }
    return 0;
}
```
The max-heap `low` holds the smaller half and the min-heap `high` the larger half, kept within one element of each other. The running median is `low.top()` when the sizes differ, or the average of the two tops when equal. For an empty input the loop never runs and nothing is printed.

```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    // Blocks while full. Returns false if the queue was shut down.
    bool push(int value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [&] { return closed_ || q_.size() < capacity_; });
        if (closed_) return false;
        q_.push(value);
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }

    // Blocks while empty. Returns nullopt once closed and drained.
    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;  // closed and drained
        int value = q_.front();
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t capacity_;
    std::queue<int> q_;
    bool closed_ = false;
    std::mutex mu_;
    std::condition_variable not_empty_, not_full_;
};
```
Push waits on `not_full_` until there is room or the queue closes, and returns `false` when closed. Pop waits on `not_empty_`, and once `close()` is called drains any remaining items before returning `nullopt`. Notifications happen after unlocking the mutex to avoid waking a waiter that then blocks again.

```rust
use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum ParseError {
    EmptyPair { index: usize },
    MissingEquals { pair: String },
    EmptyKey { index: usize },
}

pub fn parse_pairs(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut out = HashMap::new();
    if input.trim().is_empty() {
        return Ok(out);
    }
    for (index, raw) in input.split(',').enumerate() {
        let pair = raw.trim();
        if pair.is_empty() {
            return Err(ParseError::EmptyPair { index });
        }
        let (key, value) = match pair.split_once('=') {
            Some(kv) => kv,
            None => return Err(ParseError::MissingEquals { pair: pair.to_string() }),
        };
        let key = key.trim();
        if key.is_empty() {
            return Err(ParseError::EmptyKey { index });
        }
        out.insert(key.to_string(), value.trim().to_string());
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_basic() {
        let mut expected = HashMap::new();
        expected.insert("a".to_string(), "1".to_string());
        expected.insert("b".to_string(), "2".to_string());
        assert_eq!(parse_pairs("a=1, b =2"), Ok(expected));
    }

    #[test]
    fn rejects_malformed() {
        assert_eq!(parse_pairs("a=1,broken"), Err(ParseError::MissingEquals { pair: "broken".into() }));
        assert!(matches!(parse_pairs("a=1,"), Err(ParseError::EmptyPair { .. })));
        assert!(matches!(parse_pairs("=1"), Err(ParseError::EmptyKey { .. })));
    }
}
```
`split_once('=')` preserves any `=` inside the value, keys and values are trimmed, and malformed input returns a specific error variant instead of a generic string. Empty input yields an empty map rather than an error.

```rust
use std::collections::HashMap;

struct Node {
    key: u32,
    value: String,
    prev: usize,
    next: usize,
}

pub struct LruCache {
    capacity: usize,
    map: HashMap<u32, usize>,
    nodes: Vec<Node>,
    head: usize, // most recently used
    tail: usize, // least recently used
}

const NIL: usize = usize::MAX;

impl LruCache {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        LruCache { capacity, map: HashMap::new(), nodes: Vec::new(), head: NIL, tail: NIL }
    }

    pub fn get(&mut self, key: u32) -> Option<&str> {
        let idx = *self.map.get(&key)?;
        self.detach(idx);
        self.attach_front(idx);
        Some(&self.nodes[idx].value)
    }

    pub fn put(&mut self, key: u32, value: String) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].value = value;
            self.detach(idx);
            self.attach_front(idx);
            return;
        }
        if self.nodes.len() == self.capacity {
            let evict = self.tail;
            self.detach(evict);
            self.map.remove(&self.nodes[evict].key);
            self.nodes[evict].key = key;
            self.nodes[evict].value = value;
            self.attach_front(evict);
            self.map.insert(key, evict);
        } else {
            let idx = self.nodes.len();
            self.nodes.push(Node { key, value, prev: NIL, next: NIL });
            self.attach_front(idx);
            self.map.insert(key, idx);
        }
    }

    fn detach(&mut self, idx: usize) {
        let (prev, next) = (self.nodes[idx].prev, self.nodes[idx].next);
        if prev != NIL { self.nodes[prev].next = next; } else { self.head = next; }
        if next != NIL { self.nodes[next].prev = prev; } else { self.tail = prev; }
        self.nodes[idx].prev = NIL;
        self.nodes[idx].next = NIL;
    }

    fn attach_front(&mut self, idx: usize) {
        self.nodes[idx].next = self.head;
        self.nodes[idx].prev = NIL;
        if self.head != NIL { self.nodes[self.head].prev = idx; }
        self.head = idx;
        if self.tail == NIL { self.tail = idx; }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn evicts_lru() {
        let mut c = LruCache::new(2);
        c.put(1, "one".into());
        c.put(2, "two".into());
        assert_eq!(c.get(1), Some("one"));
        c.put(3, "three".into()); // evicts 2
        assert_eq!(c.get(2), None);
        assert_eq!(c.get(3), Some("three"));
        assert_eq!(c.get(1), Some("one"));
    }
}
```
Indices in `nodes` replace pointer chasing, so the borrow checker is satisfied without `Rc<RefCell<_>>`. `get` and `put` on an existing key detach and re-attach the node at the front; on overflow the tail node is reused in place, keeping allocation to one `Vec` push per new key.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define EMPTY 0
#define USED 1
#define TOMB 2
#define ABSENT (-1)

typedef struct {
    int key, value;
    unsigned char state;
} Slot;

typedef struct {
    Slot *slots;
    size_t cap, len, tombs;
} Map;

static size_t hash_int(int key, size_t cap) {
    unsigned int x = (unsigned int)key;
    x ^= x >> 16;
    x *= 0x7feb352du;
    x ^= x >> 15;
    return (size_t)x % cap;
}

Map *map_new(size_t cap) {
    Map *m = malloc(sizeof(Map));
    if (!m) return NULL;
    m->cap = cap ? cap : 8;
    m->slots = calloc(m->cap, sizeof(Slot));
    if (!m->slots) { free(m); return NULL; }
    m->len = 0;
    m->tombs = 0;
    return m;
}

void map_free(Map *m) {
    if (m) { free(m->slots); free(m); }
}

static int map_resize(Map *m, size_t newcap) {
    Slot *old = m->slots;
    size_t oldcap = m->cap;
    Slot *fresh = calloc(newcap, sizeof(Slot));
    if (!fresh) return 0;
    m->slots = fresh;
    m->cap = newcap;
    m->len = 0;
    m->tombs = 0;
    for (size_t i = 0; i < oldcap; i++) {
        if (old[i].state == USED) {
            size_t j = hash_int(old[i].key, newcap);
            while (m->slots[j].state == USED) j = (j + 1) % newcap;
            m->slots[j] = old[i];
            m->len++;
        }
    }
    free(old);
    return 1;
}

int map_put(Map *m, int key, int value) {
    if ((m->len + m->tombs) * 4 >= m->cap * 3) {
        if (!map_resize(m, m->cap * 2)) return 0;
    }
    size_t i = hash_int(key, m->cap);
    size_t first_tomb = (size_t)-1;
    for (size_t probes = 0; probes < m->cap; probes++) {
        Slot *s = &m->slots[i];
        if (s->state == USED && s->key == key) { s->value = value; return 1; }
        if (s->state == TOMB && first_tomb == (size_t)-1) first_tomb = i;
        if (s->state == EMPTY) {
            size_t dst = first_tomb != (size_t)-1 ? first_tomb : i;
            if (first_tomb != (size_t)-1) m->tombs--;
            m->slots[dst].key = key;
            m->slots[dst].value = value;
            m->slots[dst].state = USED;
            m->len++;
            return 1;
        }
        i = (i + 1) % m->cap;
    }
    if (first_tomb != (size_t)-1) {
        m->slots[first_tomb].key = key;
        m->slots[first_tomb].value = value;
        m->slots[first_tomb].state = USED;
        m->tombs--;
        m->len++;
        return 1;
    }
    return 0;
}

int map_get(const Map *m, int key) {
    size_t i = hash_int(key, m->cap);
    for (size_t probes = 0; probes < m->cap; probes++) {
        const Slot *s = &m->slots[i];
        if (s->state == EMPTY) return ABSENT;
        if (s->state == USED && s->key == key) return s->value;
        i = (i + 1) % m->cap;
    }
    return ABSENT;
}

int map_del(Map *m, int key) {
    size_t i = hash_int(key, m->cap);
    for (size_t probes = 0; probes < m->cap; probes++) {
        Slot *s = &m->slots[i];
        if (s->state == EMPTY) return 0;
        if (s->state == USED && s->key == key) {
            s->state = TOMB;
            m->len--;
            m->tombs++;
            return 1;
        }
        i = (i + 1) % m->cap;
    }
    return 0;
}

int main(void) {
    Map *m = map_new(4);
    if (!m) return 1;
    for (int i = 0; i < 100; i++) map_put(m, i, i * i);
    for (int i = 0; i < 100; i += 2) map_del(m, i);
    for (int i = 0; i < 100; i++) {
        int got = map_get(m, i);
        if (i % 2 == 0) {
            if (got != ABSENT) { printf("leak at %d\n", i); return 1; }
        } else if (got != i * i) {
            printf("bad value %d -> %d\n", i, got);
            return 1;
        }
    }
    printf("ok len=%zu tombs=%zu\n", m->len, m->tombs);
    map_free(m);
    return 0;
}
```
Linear probing with tombstones: deleted slots become `TOMB` so probe chains stay intact, and `map_put` records the first tombstone to reuse it. Resize is triggered when `(len + tombs)` exceeds 75% of capacity, which keeps probes short even after many deletions. `main` inserts 100 keys and deletes the even ones, checking every lookup.

