#include <string.h>
#include <stdio.h>

char *reverse(char *s) {
    if (s == NULL) return s;
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; i++) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
    return s;
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "a";
    printf("%s\n", reverse(a));  // olleh
    printf("%s\n", reverse(b));  // (empty)
    printf("%s\n", reverse(c));  // a
    return 0;
}
```

Swaps run only up to `n / 2`, so the middle character of odd-length strings is never touched. `NULL`, empty, and single-character inputs are all safe because `strlen` returns 0 and the loop body never executes.

```python
import os

def human(n: int) -> str:
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if n < 1024 or unit == "TB":
            return f"{n:.1f} {unit}"
        n /= 1024

def largest(root: str, top: int = 10) -> list:
    found = []
    for dirpath, _, filenames in os.walk(root):
        for name in filenames:
            path = os.path.join(dirpath, name)
            try:
                size = os.path.getsize(path)
            except OSError:
                continue
            found.append((size, path))
    found.sort(reverse=True)
    return found[:top]

if __name__ == "__main__":
    import sys
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    for size, path in largest(root):
        print(f"{human(size):>10}  {path}")
```

`os.walk` visits every subdirectory; `getsize` is wrapped in `try/except` for broken symlinks. Results sort descending by bytes and slice to the top N before formatting.

