from typing import Optional

PAIRS = {")": "(", "]": "[", "}": "{"}
OPENERS = set(PAIRS.values())

def balanced(s: str) -> bool:
    stack: list[str] = []
    for ch in s:
        if ch in OPENERS:
            stack.append(ch)
        elif ch in PAIRS:
            if not stack or stack[-1] != PAIRS[ch]:
                return False
            stack.pop()
    return not stack


if __name__ == "__main__":
    assert balanced("([]){}")
    assert not balanced("([)]")
    assert not balanced("(")
    assert balanced("")
    assert balanced("a(b)[c]{d}")
    print("ok")
