def fib(n: int) -> int:
    """Return the nth Fibonacci number (F(0)=0, F(1)=1) via fast doubling.

    Runs in O(log n) multiplications. n < 0 raises ValueError.
    """
    if n < 0:
        raise ValueError("n must be non-negative")

    def _pair(k: int) -> tuple[int, int]:
        # returns (F(k), F(k+1))
        if k == 0:
            return (0, 1)
        a, b = _pair(k >> 1)          # a = F(m), b = F(m+1)
        c = a * ((b << 1) - a)        # F(2m)   = F(m)*(2*F(m+1) - F(m))
        d = a * a + b * b             # F(2m+1) = F(m)^2 + F(m+1)^2
        return (d, c + d) if k & 1 else (c, d)

    return _pair(n)[0]


if __name__ == "__main__":
    assert fib(0) == 0
    assert fib(1) == 1
    assert fib(10) == 55
    assert fib(50) == 12586269025
    assert fib(100) == 354224848179261915075
    try:
        fib(-1)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
    print(fib(200))
