        std::cout << '[';
        for (std::size_t i = 0; i < v.size(); ++i)
            std::cout << (i ? "," : "") << '"' << v[i] << '"';
        std::cout << "] size=" << v.size() << '\n';
    };
    show(split("a,b,c", ','));   // 3 tokens
    show(split("a,,c", ','));    // empty middle token kept
    show(split(",", ','));       // two empty tokens
    show(split("", ','));        // one empty token
    show(split("abc", ','));     // no delimiter
