/// Reverse the order of whitespace-separated words but keep each run of
/// whitespace exactly where it is when read left-to-right.
fn reverse_words(s: &str) -> String {
    let words: Vec<&str> = s.split_whitespace().collect();
    if words.is_empty() {
        return String::new();
    }

    let mut out = String::with_capacity(s.len());
    let mut w = words.len();
    let mut in_word = false;

    for ch in s.chars() {
        if ch.is_whitespace() {
            if in_word {
                w -= 1;
                in_word = false;
            }
            out.push(ch);
        } else {
            if !in_word {
                out.push_str(words[w - 1]);
                in_word = true;
            }
        }
    }
    out
}

fn main() {
    assert_eq!(reverse_words("the sky is blue"), "blue is sky the");
    assert_eq!(reverse_words("  hello   world  "), "  world   hello  ");
    assert_eq!(reverse_words(""), "");
    assert_eq!(reverse_words("one"), "one");
    println!("{:?}", reverse_words("a  b\tc"));
}
