#include <iostream>
#include <queue>
#include <vector>
#include <iomanip>

int main() {
    std::priority_queue<int> low;                                  // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap

    int value;
    bool any = false;
    while (std::cin >> value) {
        any = true;

        if (low.empty() || value <= low.top()) {
            low.push(value);
        } else {
            high.push(value);
        }

        // Rebalance so low.size() is high.size() or high.size() + 1
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        double median;
        if (low.size() == high.size()) {
            median = (low.top() + high.top()) / 2.0;
        } else {
            median = low.top();
        }
        std::cout << std::fixed << std::setprecision(1) << median << '\n';
    }

    if (!any) {
        std::cerr << "no input\n";
        return 1;
    }
    return 0;
}
```

Insertion is O(log n) and the median is O(1) per read, so the whole stream is O(n log n). The `low` heap never exceeds `high` by more than one, which is what makes `low.top()` the odd-length median.

```rust
use std::fmt;

#[derive(Debug, PartialEq)]
pub enum ParseErr {
    Empty,
    TooManyParts,
    NotANumber(String),
    OutOfRange(String),
}

impl fmt::Display for ParseErr {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseErr::Empty => write!(f, "empty input"),
            ParseErr::TooManyParts => write!(f, "expected exactly 4 parts"),
            ParseErr::NotANumber(p) => write!(f, "not a number: {p:?}"),
            ParseErr::OutOfRange(p) => write!(f, "out of range 0-255: {p:?}"),
        }
    }
}

pub fn parse_ipv4(s: &str) -> Result<[u8; 4], ParseErr> {
    if s.is_empty() {
        return Err(ParseErr::Empty);
    }

    let mut octets = [0u8; 4];
    let mut count = 0usize;

    for part in s.split('.') {
        if count == 4 {
            return Err(ParseErr::TooManyParts);
        }
        // reject empty parts (e.g. "1..2") and non-digits
        if part.is_empty() || !part.bytes().all(|b| b.is_ascii_digit()) {
            return Err(ParseErr::NotANumber(part.to_string()));
        }
        let n: u32 = part.parse().map_err(|_| ParseErr::NotANumber(part.to_string()))?;
        if n > 255 {
            return Err(ParseErr::OutOfRange(part.to_string()));
        }
        octets[count] = n as u8;
        count += 1;
    }

    if count != 4 {
        return Err(ParseErr::TooManyParts);
    }
    Ok(octets)
}

fn main() {
    let cases = ["192.168.0.1", "0.0.0.0", "255.255.255.255", "1.2.3", "1.2.3.4.5", "1.2.3.256", "", "1..2.3"];
    for c in cases {
        match parse_ipv4(c) {
            Ok(o) => println!("ok   {c:?} -> {o:?}"),
            Err(e) => println!("err  {c:?} -> {e}"),
        }
    }
}
```

`part.bytes().all(is_ascii_digit)` blocks signs, spaces and leading-dot tricks before `parse`, so the only failure left there is overflow, which the `u32` handles cleanly.

```python
from collections import OrderedDict


class LRUCache:
    """Fixed-capacity LRU cache. get/put are O(1) amortised."""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least recently used

    def __len__(self) -> int:
        return len(self._data)

    def __contains__(self, key) -> bool:
        return key in self._data


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1          # 'a' is now most recent
    c.put("c", 3)                   # evicts 'b'
    assert c.get("b") is None
    assert c.get("a") == 1
    assert c.get("c") == 3
    assert len(c) == 2
    print("all assertions passed")
```

`move_to_end` on every hit is what makes recently-used entries survive eviction, and `popitem(last=False)` removes from the front — the least recently used end.

