#include <iostream>
#include <vector>

std::vector<int> merge_unique(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());

    size_t i = 0, j = 0;
    while (i < a.size() || j < b.size()) {
        int v;
        if (j == b.size() || (i < a.size() && a[i] < b[j])) {
            v = a[i++];
        } else if (i == a.size() || b[j] < a[i]) {
            v = b[j++];
        } else {
            v = a[i];   // equal: take once and advance both
            i++;
            j++;
        }
        if (out.empty() || out.back() != v) {
            out.push_back(v);
        }
    }
    return out;
}

int main() {
    std::vector<int> a = {1, 2, 2, 5, 9};
    std::vector<int> b = {2, 3, 5, 5, 10};
