```rust
pub struct Ring{
    buf: Vec<Option<u32>>,
    head: usize,
    len: usize,
}

impl Ring {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        Ring { buf: vec![None; cap], head: 0, len: 0 }
    }

    pub fn push(&mut self, v: u32) {
        let cap = self.buf.len();
        if self.len < cap {
            self.buf[(self.head + self.len) % cap] = Some(v);
            self.len += 1;
        } else {
            self.buf[self.head] = Some(v);
            self.head = (self.head + 1) % cap;
        }
    }

    pub fn iter(&self) -> impl Iterator<Item = u32> + '_ {
        (0..self.len).map(move |i| self.buf[(self.head + i) % self.buf.len()].unwrap())
    }
}

