// first index i with v[i] >= target, or v.size() if none.
template <typename T>
std::size_t lower_bound_idx(const std::vector<T>& v, const T& target) {
    std::size_t lo = 0, hi = v.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (v[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

