def encode(s: str) -> str:
    if not s:
        return ""
    out = []
    prev = s[0]
    run = 1
    for ch in s[1:]:
        if ch == prev:
            run += 1
        else:
            out.append(f"{prev}{run}")
            prev, run = ch, 1
    out.append(f"{prev}{run}")
    return "".join(out)


def decode(s: str) -> str:
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        digits = []
        while i < len(s) and s[i].isdigit():
            digits.append(s[i])
            i += 1
        if not digits:
            raise ValueError(f"malformed input at index {i}: missing count")
        out.append(ch * int("".join(digits)))
    return "".join(out)


