#include <cstdio>
#include <stdexcept>

template <typename T, std::size_t N>
class FixedStack {
public:
    void push(const T& value) {
        if (size_ == N) throw std::overflow_error("stack full");
        data_[size_++] = value;
    }

    T pop() {
        if (size_ == 0) throw std::underflow_error("stack empty");
        return data_[--size_];
    }

    const T& top() const {
        if (size_ == 0) throw std::underflow_error("stack empty");
        return data_[size_ - 1];
    }

    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    T data_[N];
    std::size_t size_ = 0;
};

int main() {
    FixedStack<int, 3> s;
    s.push(1); s.push(2); s.push(3);
    std::printf("top=%d size=%zu\n", s.top(), s.size());
    while (!s.empty()) std::printf("%d ", s.pop());
    std::printf("\n");
    try { s.pop(); } catch (const std::underflow_error& e) { std::printf("caught: %s\n", e.what()); }
    return 0;
}
