struct Fib {
    memo: HashMap<u64, u128>,
}

impl Fib {
    fn new() -> Self {
        let mut memo = HashMap::new();
        memo.insert(0, 0);
        memo.insert(1, 1);
        Fib { memo }
    }

    fn get(&mut self, n: u64) -> u128 {
        if let Some(&v) = self.memo.get(&n) {
            return v;
        }
        let v = self.get(n - 1) + self.get(n - 2);
        self.memo.insert(n, v);
        v
    }
}

