static constexpr std::int64_t MOD = 1000000007;

// Returns {F(n), F(n+1)} mod MOD.
static std::pair<std::int64_t, std::int64_t> fib_pair(std::int64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    std::int64_t c = a * ((2 * b % MOD - a + MOD) % MOD) % MOD; // F(2k)
    std::int64_t d = (a * a % MOD + b * b % MOD) % MOD;         // F(2k+1)
    if (n & 1) return {d, (c + d) % MOD};
    return {c, d};
}

static std::int64_t fib(std::int64_t n) { return fib_pair(n).first; }

int main() {
    std::int64_t n;
    while (std::cin >> n) {
        if (n < 0) {
            std::cerr << "n must be non-negative\n";
            continue;
        }
        std::cout << fib(n) << '\n';
    }
    return 0;
}
