```cpp
#include <array>
#include <cstddef>
#include <optional>

// Fixed-capacity FIFO ring buffer; no heap usage.
template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

    // Returns a copy in insertion order; empty buffer yields an empty vector-free array size 0.
    std::array<T, N> to_array(std::size_t& out_len) const {
        std::array<T, N> out{};
        for (std::size_t i = 0; i < size_; ++i) {
            out[i] = data_[(head_ + i) % N];
        }
        out_len = size_;
        return out;
    }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

// Example use:
// RingBuffer<int, 4> rb;
// rb.push(1); rb.push(2); rb.pop(); rb.push(3);
// std::size_t len; auto a = rb.to_array(len); // {2, 3}
```
`std::array<T, N>` requires `N > 0`; for a runtime capacity you'd need a different container.

