```cpp
#include <cstddef>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(new double[capacity]), cap_(capacity), head_(0), size_(0) {}
    ~RingBuffer() { delete[] buf_; }

    bool push(double v) {
        if (size_ == cap_) return false;
        buf_[(head_ + size_) % cap_] = v;
        ++size_;
        return true;
    }

    bool pop(double& out) {
        if (size_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return true;
    }

    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    double* buf_;
    std::size_t cap_, head_, size_;
};
```
Push fails when full, pop fails when empty, so no overwrite or underflow. The modulo index walks the buffer circularly.

