struct Tracker {
    static int copies;
    static int moves;
    int id;
    explicit Tracker(int i) : id(i) {}
    Tracker(const Tracker& o) : id(o.id) { ++copies; }
    Tracker(Tracker&& o) noexcept : id(o.id) { ++moves; }
};

int Tracker::copies = 0;
int Tracker::moves = 0;

int main() {
    Tracker a(1);
    Tracker b = a;            // copy
    Tracker c = std::move(a); // move
    std::vector<Tracker> v;
    v.reserve(2);
