from collections import Counter

_WORD_RE = re.compile(r"[^\W_]+", re.UNICODE)

def word_frequencies(text: str) -> dict:
    """Return a dict mapping lowercased words to their counts."""
    if not text:
        return {}
    words = _WORD_RE.findall(text.lower())
    return dict(Counter(words))


if __name__ == "__main__":
    sample = "The cat sat on the mat. The CAT! Empty? \u00c9l\u00e8ve caf\u00e9 na\u00efve."
    print(word_frequencies(sample))
    print(word_frequencies(""))  # {}
```

The regex `[^\W_]+` matches runs of letters and digits while dropping underscores and punctuation; `re.UNICODE` makes `\w` cover accented and non-Latin characters, so `Élève` and `café` survive intact after lowercasing. Empty input short-circuits to an empty dict rather than calling `findall`.

```cpp
#include <iostream>
#include <string>
#include <limits>

int main() {
    std::string line;
    bool have = false;
    long long best = 0;
    while (std::getline(std::cin, line)) {
        // Strip surrounding whitespace.
        std::size_t start = line.find_first_not_of(" \t\r\n");
        if (start == std::string::npos) continue; // blank line
        std::size_t end = line.find_last_not_of(" \t\r\n");
        std::string trimmed = line.substr(start, end - start + 1);

        try {
            std::size_t pos = 0;
            long long value = std::stoll(trimmed, &pos);
            if (pos != trimmed.size()) {
                std::cerr << "skip (trailing junk): " << trimmed << "\n";
                continue;
            }
            if (!have || value > best) {
                best = value;
                have = true;
            }
            std::cout << "max=" << best << "\n";
        } catch (const std::exception&) {
            std::cerr << "skip (not a number): " << trimmed << "\n";
        }
    }
    if (!have) std::cout << "no numbers\n";
    return 0;
}
```

`std::stoll` reports how much of the string it consumed via `pos`, so a line like `42abc` is rejected instead of silently becoming 42. Blank lines and non-numeric lines go to stderr and don't disturb the running max. `best` starts unset and is only used once `have` is true, so all-negative input works correctly.

