    if (right == 0) return;
    right--;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char buf[64] = "hello, world";
    reverse_in_place(buf);
    printf("%s\n", buf);

    char empty[1] = "";
    reverse_in_place(empty);
    printf("[%s]\n", empty);

    char *p = NULL;
    reverse_in_place(p); /* safe no-op */

    char unicode[] = "na\xc3\xafve caf\xc3\xa9";
    reverse_in_place(unicode);
    printf("%s\n", unicode); /* bytes reversed, not graphemes */
    return 0;
}
```

`right` starts at `strlen(s) - 1` so the terminating NUL is never touched. A NULL pointer returns immediately, and an empty string (length 0) returns before decrementing. Note the last case: reversing multibyte UTF-8 bytes scrambles the encoding — that is correct byte-level behavior, and a grapheme-aware version would need a UTF-8 decoder.

```rust
fn merge_sorted<T: Ord + Copy>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 4, 6, 8];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 4, 5, 6, 7, 8]);

    let empty: [i32; 0] = [];
    assert_eq!(merge_sorted(&empty, &b), b.to_vec());
    assert_eq!(merge_sorted(&a, &empty), a.to_vec());
    assert_eq!(merge_sorted(&empty, &empty), Vec::<i32>::new());

    // stability check: equal elements from `a` come first
    let c = [1, 2, 2];
    let d = [2, 3];
    assert_eq!(merge_sorted(&c, &d), vec![1, 2, 2, 2, 3]);
    println!("all assertions passed");
}
```

`Vec::with_capacity` avoids repeated reallocation, and `extend_from_slice` bulk-copies the leftover tail instead of looping. Using `<=` when comparing makes the merge stable — ties prefer the left input. The `[T; 0]` cases confirm empty slices are handled without special casing.

```cpp
#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
T dot_product(const std::vector<T>& a, const std::vector<T>& b) {
    if (a.size() != b.size()) {
        throw std::invalid_argument("dot_product: vectors must be the same length");
    }
    T acc{};
    for (std::size_t i = 0; i < a.size(); ++i) {
        acc += a[i] * b[i];
    }
    return acc;
}

int main() {
    std::vector<double> x{1.0, 2.0, 3.0};
    std::vector<double> y{4.0, 5.0, 6.0};
    std::cout << dot_product(x, y) << "\n"; // 32

    std::vector<int> e{}
    std::cout << dot_product(e, e) << "\n"; // 0

    try {
        std::vector<int> z{1};
        dot_product(e, z);
    } catch (const std::invalid_argument& ex) {
        std::cerr << "caught: " << ex.what() << "\n";
    }
    return 0;
}
```

The template works for any arithmetic type, and `acc{}` value-initializes so empty vectors return zero instead of reading garbage. Mismatched lengths throw instead of reading out of bounds, and `main` demonstrates the exception path rather than leaving it untested.

```cpp
#include <iostream>
#include <iomanip>
#include <queue>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // max-heap for the lower half, min-heap for the upper half
    std::priority_queue<int> low;
    std::priority_queue<int, std::vector<int>, std::greater<int>> high;

    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) {
            low.push(x);
        } else {
            high.push(x);
        }
        // Rebalance so low.size() == high.size() or low.size() == high.size() + 1
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        double median;
        if (low.size() == high.size()) {
            median = (low.top() + high.top()) / 2.0;
        } else {
            median = low.top();
        }
        std::cout << std::fixed << std::setprecision(2) << median << '\n';
    }
    return 0;
}
```

Each value enters the lower heap if it is `<=` the current lower max, otherwise the upper heap; the two are then rebalanced. The median is `low.top()` when the lower heap has one extra element, and the mean of the two tops when sizes are equal. `int` addition is promoted to `double` before the divide, so odd/even counts and negative values both come out right. Compile with `g++ -std=c++17 -O2`.

```rust
fn is_palindrome(s: &str) -> bool {
    let chars: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();

    let mut i = 0usize;
    let mut j = chars.len().saturating_sub(1);
    while i < j {
        if chars[i] != chars[j] {
            return false;
        }
        i += 1;
        j -= 1;
    }
    true
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basics() {
        assert!(is_palindrome("A man, a plan, a canal: Panama"));
        assert!(!is_palindrome("race a car"));
        assert!(is_palindrome(""));
        assert!(is_palindrome("   "));
        assert!(is_palindrome("0P")); // '0' treated as alphanumeric, 'p' != '0'
    }

    #[test]
    fn unicode() {
        // 'É' lowercases to 'é'; the accented pair matches.
        assert!(is_palindrome("Éé"));
        // Non-Latin letters are alphanumeric, so this is a palindrome.
        assert!(is_palindrome("Αββα"));
    }
}
```

`to_lowercase` returns an iterator because some Unicode code points lowercase to multiple characters (e.g. 'İ'), so `flat_map` handles them without truncation. `saturating_sub(1)` keeps the empty case from underflowing. Note that `is_alphanumeric` treats digits as keepers; change the filter to `c.is_alphabetic()` if you want letters only.

```c
#include <stdio.h>
#include <string.h>

char *reverse_in_place(char *s) {
    if (s == NULL) return NULL;
    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0) return s;
    j -= 1;               /* last valid index */
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
    return s;
}

int main(void) {
    char buf[] = "hello world";   /* writable array, NOT a literal */
    puts(reverse_in_place(buf));  /* dlrow olleh */

    char empty[] = "";
    puts(reverse_in_place(empty)); /* empty line */

    puts(reverse_in_place(NULL)); /* not reached in practice */
    return 0;
}
```

A string literal like `"hello"` lives in read-only memory; passing it to this function writes through the pointer and is undefined behaviour — typically a segfault. An array, `char buf[] = "hello"`, copies the bytes onto the stack and is safe to modify. Always use `strlen(s)` for the exclusive upper bound and decrement once so the `\0` is never touched.

```cpp
#include <iostream>
#include <string>
#include <cstdint>
#include <stdexcept>

std::string to_binary(std::int64_t value) {
    std::uint64_t bits = static_cast<std::uint64_t>(value);
    std::string out(64, '0');
    for (int i = 0; i < 64; ++i) {
        out[63 - i] = ((bits >> i) & 1ULL) ? '1' : '0';
    }
    // Drop leading zeros but keep at least one digit.
    std::size_t first = out.find('1');
    if (first == std::string::npos) return "0";
    return out.substr(first);
}

int main(int argc, char **argv) {
    std::int64_t v;
    if (argc == 2) {
        try {
            v = std::stoll(argv[1]);
        } catch (const std::exception &) {
            std::cerr << "not an integer: " << argv[1] << '\n';
            return 1;
        }
    } else {
        std::cin >> v;
        if (!std::cin) { std::cerr << "expected an integer\n"; return 1; }
    }
    std::cout << to_binary(v) << '\n';
    return 0;
}
```

Cast to `std::uint64_t` first: converting a negative `int64_t` to unsigned is defined and produces the two's-complement bit pattern. The loop fills from bit 0 upward into the reversed index `63 - i`, so leading zeros appear on the left and are trimmed by `substr`. `-1` prints as sixty-four `1`s, `0` as `0`. `std::stoll` rejects overflow and trailing junk.

