```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), size_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == buf_.size(); }
    std::size_t size() const { return size_; }
    std::size_t capacity() const { return buf_.size(); }

    bool push(const T& value) {
        if (full()) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % buf_.size();
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return value;
    }

private:
    std::vector<T> buf_;
    std::size_t head_, tail_, size_;
};

int main() {
    RingBuffer<int> rb(3);
    std::cout << "push 1: " << rb.push(1) << '\n';
    std::cout << "push 2: " << rb.push(2) << '\n';
    std::cout << "push 3: " << rb.push(3) << '\n';
    std::cout << "push 4 (full): " << rb.push(4) << '\n';
    std::cout << "pop: " << *rb.pop() << '\n';
    std::cout << "push 4: " << rb.push(4) << '\n';
    while (!rb.empty()) std::cout << "drain: " << *rb.pop() << '\n';
    std::cout << "pop empty: " << (rb.pop().has_value() ? "value" : "nullopt") << '\n';
    return 0;
}
