#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

#define RING_CAP 8

typedef struct {
    int data[RING_CAP];
    size_t head;   /* next write */
    size_t tail;   /* next read  */
    size_t count;
} ring_t;

static void ring_init(ring_t *r) { r->head = r->tail = r->count = 0; }

static bool ring_push(ring_t *r, int v) {
    if (r->count == RING_CAP) return false;
    r->data[r->head] = v;
    r->head = (r->head + 1) % RING_CAP;
    r->count++;
    return true;
}

static bool ring_pop(ring_t *r, int *out) {
    if (r->count == 0) return false;
    *out = r->data[r->tail];
    r->tail = (r->tail + 1) % RING_CAP;
    r->count--;
    return true;
}

int main(void) {
    ring_t r; ring_init(&r);
    for (int i = 0; i < 10; ++i)
        printf("push %d -> %s\n", i, ring_push(&r, i) ? "ok" : "full");
    int v;
    while (ring_pop(&r, &v)) printf("pop %d\n", v);
    printf("pop empty -> %s\n", ring_pop(&r, &v) ? "ok" : "empty");
    return 0;
}
