```python
import functools
import logging
import time

log = logging.getLogger(__name__)

def retry(attempts: int = 3, base_delay: float = 0.1, factor: float = 2.0,
          exceptions: tuple = (Exception,)):
    """Retry the wrapped function up to `attempts` times total.
    Sleeps base_delay, base_delay*factor, ... between tries. Re-raises last error."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            delay = base_delay
            for attempt in range(1, attempts + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    if attempt == attempts:
                        log.error("giving up after %d attempts: %s", attempt, exc)
                        raise
                    log.warning("attempt %d failed (%s); retrying in %.2fs",
                                attempt, exc, delay)
                    time.sleep(delay)
                    delay *= factor
        return wrapper
    return decorator


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    calls = {"n": 0}

    @retry(attempts=3, base_delay=0.01)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise RuntimeError("not yet")
        return "ok"

    assert flaky() == "ok" and calls["n"] == 3
    print("passed")
