#include <algorithm>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::vector<int> nums;
    int x;
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    while (std::cin >> x) {
        nums.push_back(x);
    }
    if (nums.empty()) {
        std::cout << "no input\n";
        return 0;
    }

    std::cout << "k> ";
    std::cout.flush();
    long long k = 0;
    if (!(std::cin.clear(), std::cin >> k) || k <= 0) {
        std::cout << "invalid k\n";
        return 1;
    }

    if (static_cast<size_t>(k) > nums.size()) {
        k = static_cast<long long>(nums.size());
    }

    // Min-heap of the k largest values seen so far.
    std::priority_queue<int, std::vector<int>, std::greater<int>> heap;
    for (int v : nums) {
        heap.push(v);
        if (static_cast<long long>(heap.size()) > k) {
            heap.pop();
        }
    }

    std::vector<int> top(heap.size());
    for (size_t i = top.size(); i-- > 0;) {
        top[i] = heap.top();
        heap.pop();
    }

    for (size_t i = 0; i < top.size(); ++i) {
        std::cout << top[i] << (i + 1 == top.size() ? '\n' : ' ');
    }
    return 0;
}
```

Complexity is O(n log k) time and O(k) extra space. When `k` exceeds the number of integers, it prints all of them sorted descending. Empty input prints `no input` and exits 0.

