```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (n == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    n->value = value;
    n->next = head;
    return n;
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 1; i <= 5; ++i) {
        list = push(list, i);  /* builds 5 4 3 2 1 */
    }
    list = reverse(list);      /* now 1 2 3 4 5 */

    for (Node *p = list; p != NULL; p = p->next) {
        printf("%d ", p->value);
    }
    putchar('\n');

    /* Empty list is also safe. */
    Node *empty = reverse(NULL);
    if (empty != NULL) {
        fprintf(stderr, "expected NULL\n");
        return 1;
    }

    free_list(list);
    return 0;
}
```

Three-pointer iterative reversal: O(n) time, O(1) extra space. `reverse(NULL)` returns `NULL`, so the empty list case is covered.

```rust
/// Returns Ok(index) if found, Err(index) with the insertion point otherwise.
pub fn search_sorted(haystack: &[i64], target: i64) -> Result<usize, usize> {
    let mut lo = 0usize;
    let mut hi = haystack.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match haystack[mid].cmp(&target) {
            std::cmp::Ordering::Equal => return Ok(mid),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    Err(lo)
}

fn main() {
    let data = [1i64, 3, 5, 7, 9];
    assert_eq!(search_sorted(&data, 5), Ok(2));
    assert_eq!(search_sorted(&data, 1), Ok(0));
    assert_eq!(search_sorted(&data, 9), Ok(4));
    assert_eq!(search_sorted(&data, 0), Err(0));
    assert_eq!(search_sorted(&data, 6), Err(3));
    assert_eq!(search_sorted(&data, 10), Err(5));
    assert_eq!(search_sorted(&[], 42), Err(0));
    println!("all checks passed");
}
```

The `Err` variant carries the first index where `haystack[i] >= target`, which is exactly where `target` would be inserted to keep the slice sorted. `mid = lo + (hi - lo) / 2` avoids overflow on very large slices. Duplicates return the index of an arbitrary matching element.

