```python
import csv
import io
from collections import defaultdict


def summarize(csv_text, key_col, value_col):
    """Group rows by key_col, summing and averaging value_col.

    Returns {key: {"count": int, "sum": float, "mean": float}}.
    Rows with a non-numeric value are skipped and counted.
    """
    reader = csv.DictReader(io.StringIO(csv_text))
    if reader.fieldnames is None:
        return {}, 0
    if key_col not in reader.fieldnames or value_col not in reader.fieldnames:
        raise KeyError(f"missing column; have {reader.fieldnames}")

    sums = defaultdict(float)
    counts = defaultdict(int)
    skipped = 0

    for row in reader:
        try:
            value = float(row[value_col])
        except (TypeError, ValueError):
            skipped += 1
            continue
        key = row[key_col]
        sums[key] += value
        counts[key] += 1

    out = {
        k: {"count": counts[k], "sum": sums[k], "mean": sums[k] / counts[k]}
        for k in counts
    }
    return out, skipped


if __name__ == "__main__":
    data = "team,score\nalpha,10\nbeta,4\nalpha,20\nbeta,6\nalpha,bad\n"
    result, skipped = summarize(data, "team", "score")
    assert result["alpha"] == {"count": 2, "sum": 30.0, "mean": 15.0}
    assert result["beta"] == {"count": 2, "sum": 10.0, "mean": 5.0}
    assert skipped == 1
    print("all checks passed")
```

Uses `csv.DictReader` so quoted fields and commas inside quotes are handled correctly. `defaultdict` accumulates sums and counts in one pass; non-numeric values are counted in `skipped` rather than crashing the whole summarization.

