from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key, default=None):
        if key not in self._data:
            return default
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least-recently used

    def __len__(self):
        return len(self._data)

if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1
    c.put("c", 3)          # evicts "b"
    assert c.get("b") is None
    assert c.get("a") == 1
    print("ok")
```

`move_to_end` on read makes access recency explicit; `popitem(last=False)` evicts the oldest entry. A capacity below 1 is rejected up front.

```c
#include <stdio.h>
#include <string.h>

/* Copies src into dst (size bytes). Always null-terminates.
   Returns 1 if fully copied, 0 if truncated. */
int safe_copy(char *dst, size_t size, const char *src) {
    if (size == 0) return 0;
    size_t src_len = strlen(src);
    if (src_len < size) {
        memcpy(dst, src, src_len + 1);
        return 1;
    }
    memcpy(dst, src, size - 1);
    dst[size - 1] = '\0';
    return 0;
}

int main(void) {
    char buf[8];
    if (safe_copy(buf, sizeof buf, "hello")) printf("full: %s\n", buf);

    if (!safe_copy(buf, sizeof buf, "this is too long"))
        printf("truncated: %s\n", buf);

    /* size 0 must not write */
    char tiny = 'X';
    (void)safe_copy(&tiny, 0, "ignored");
    printf("untouched: %c\n", tiny);
    return 0;
}
```

The critical case is `size == 0`: no write happens at all. Otherwise it copies at most `size - 1` bytes and writes the terminator itself, so the result is always a valid C string.

