std::string to_roman(int value) {
    if (value < 1 || value > 3999) {
        throw std::out_of_range("value must be in [1, 3999]");
    }

    // Greedy: largest symbol that fits, including subtractive forms.
    const std::vector<std::pair<int, std::string>> table = {
        {1000, "M"},  {900, "CM"}, {500, "D"},  {400, "CD"},
        {100,  "C"},  {90,  "XC"}, {50,  "L"},  {40,  "XL"},
        {10,   "X"},  {9,   "IX"}, {5,   "V"},  {4,   "IV"},
        {1,    "I"},
    };

    std::string out;
    for (const auto& [amount, symbol] : table) {
        while (value >= amount) {
            out += symbol;
            value -= amount;
        }
    }
    return out;
}

int main() {
    const std::vector<int> inputs = {1, 4, 9, 58, 1994, 3999};
    const std::vector<std::string> expected = {
        "I", "IV", "IX", "LVIII", "MCMXCIV", "MMMCMXCIX"};

    for (std::size_t i = 0; i < inputs.size(); ++i) {
        const std::string got = to_roman(inputs[i]);
        if (got != expected[i]) {
            std::cerr << "mismatch for " << inputs[i] << ": " << got << '\n';
            return 1;
        }
    }

    try {
        (void)to_roman(4000);
        std::cerr << "4000 should have thrown\n";
        return 1;
    } catch (const std::out_of_range&) {
        // expected
    }

    std::cout << "ok\n";
    return 0;
}
