use std::collections::HashMap;

/// Count words split on Unicode whitespace and return the `n` most frequent,
/// sorted by count descending then word ascending for stable output.
pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        *counts.entry(word.to_lowercase()).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the quick brown fox jumps over the lazy dog the FOX";
    let result = top_words(text, 2);
    assert_eq!(result, vec![("the".to_string(), 3), ("fox".to_string(), 2)]);

    // Empty input yields no pairs rather than panicking.
    assert!(top_words("", 5).is_empty());

    // Asking for more than distinct words just returns everything.
    assert_eq!(top_words("one", 10).len(), 1);

    println!("ok: {:?}", result);
