#include <stddef.h>
#include <stdio.h>
#include <assert.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

/* Iterative reverse: walks the list once, rewires next pointers. */
Node *reverse_list(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

/* Reverse an array in place. n is a size_t; n == 0 is a no-op. */
void reverse_array(int *arr, size_t n) {
    if (arr == NULL || n < 2) {
        return;
    }
    for (size_t i = 0, j = n - 1; i < j; ++i, --j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

int main(void) {
    Node c = {3, NULL};
    Node b = {2, &c};
    Node a = {1, &b};

    Node *rev = reverse_list(&a);
    assert(rev == &c && rev->next == &b && rev->next->next == &a);
    assert(a.next == NULL);

    int arr[] = {1, 2, 3, 4, 5};   /* odd length */
    reverse_array(arr, 5);
    for (size_t i = 0; i < 5; ++i) assert(arr[i] == (int)(5 - i));

    int empty[1] = {0};
    reverse_array(empty, 0);        /* must not touch memory */
    assert(empty[0] == 0);

    puts("ok");
    return 0;
}
