std::vector<std::string> parse_csv_line(const std::string& line) {
    std::vector<std::string> fields;
    std::string field;
    bool in_quotes = false;

    for (std::size_t i = 0; i < line.size(); ++i) {
        const char c = line[i];

        if (in_quotes) {
            if (c == '"') {
                // A doubled quote inside quotes is a literal quote.
                if (i + 1 < line.size() && line[i + 1] == '"') {
                    field += '"';
                    ++i;
                } else {
                    in_quotes = false;
                }
            } else {
                field += c;
            }
        } else if (c == '"') {
            in_quotes = true;
        } else if (c == ',') {
            fields.push_back(field);
            field.clear();
        } else {
            field += c;
        }
    }

    // An unterminated quote is a malformed line; treat it as an error marker.
    if (in_quotes) {
        return {};
    }

    fields.push_back(field);
    return fields;
}

int main() {
    const auto a = parse_csv_line("a,b,c");
    assert((a == std::vector<std::string>{"a", "b", "c"}));

    const auto b = parse_csv_line("say \"\"hi\"\",x");
    assert((b == std::vector<std::string>{"say \"hi\"", "x"}));

    const auto c = parse_csv_line("");
    assert((c == std::vector<std::string>{""}));

    const auto d = parse_csv_line("\"unterminated");
    assert(d.empty());

    std::cout << "ok\n";
    return 0;
}
