#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} IntVec;

static int vec_grow(IntVec *v) {
    size_t new_cap = v->capacity ? v->capacity * 2 : 4;
    int *tmp = realloc(v->data, new_cap * sizeof(int));
    if (!tmp) return 0;
    v->data = tmp;
    v->capacity = new_cap;
    return 1;
}

int vec_push(IntVec *v, int value) {
    if (v->size == v->capacity && !vec_grow(v)) return 0;
    v->data[v->size++] = value;
    return 1;
}

int vec_get(const IntVec *v, size_t idx, int *out) {
    if (idx >= v->size) return 0;
    *out = v->data[idx];
    return 1;
}

void vec_free(IntVec *v) {
    free(v->data);
    v->data = NULL;
    v->size = 0;
    v->capacity = 0;
}

int main(void) {
    IntVec v = {0};
    for (int i = 0; i < 10; i++) {
        if (!vec_push(&v, i * i)) { fprintf(stderr, "alloc fail\n"); return 1; }
    }
    int got = -1;
    if (vec_get(&v, 9, &got)) printf("v[9]=%d size=%zu\n", got, v.size);
    if (!vec_get(&v, 100, &got)) printf("out of range handled\n");
    vec_free(&v);
    return 0;
}
