/* Reverse a slice [start, end) in place. */
static void reverse_range(char *s, int start, int end) {
    end--;
    while (start < end) {
        char tmp = s[start];
        s[start] = s[end];
        s[end] = tmp;
        start++;
        end--;
    }
}

/* Reverse the order of words in a null-terminated string in place. */
void reverse_words(char *s) {
    int n = (int)strlen(s);
    if (n == 0) return;

    reverse_range(s, 0, n);

    int i = 0;
    while (i < n) {
        if (s[i] != ' ') {
            int j = i;
            while (j < n && s[j] != ' ') j++;
            reverse_range(s, i, j);
            i = j;
        } else {
            i++;
        }
    }
}

int main(void) {
    char a[] = "the quick brown fox";
    reverse_words(a);
    assert(strcmp(a, "fox brown quick the") == 0);

    char b[] = "hello";
    reverse_words(b);
    assert(strcmp(b, "hello") == 0);

    char c[] = "";
    reverse_words(c);
    assert(strcmp(c, "") == 0);

    printf("all tests passed\n");
    return 0;
}
