#include <iostream>
#include <stack>
#include <string>
#include <cassert>

bool balanced(const std::string& s) {
    std::stack<char> st;
    bool in_single = false, in_double = false;
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (in_single) {
            if (c == '\\' && i + 1 < s.size()) { ++i; }
            else if (c == '\'') in_single = false;
            continue;
        }
        if (in_double) {
            if (c == '\\' && i + 1 < s.size()) { ++i; }
            else if (c == '"') in_double = false;
            continue;
        }
        if (c == '\'') { in_single = true; continue; }
        if (c == '"') { in_double = true; continue; }
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top(); st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.empty() && !in_single && !in_double;
}

int main() {
    assert(balanced("{[()()]}"));
    assert(!balanced("{[(])}"));
    assert(!balanced("((("));
    assert(balanced("f(x, ']')"));       // bracket inside quotes is ignored
    assert(balanced("a \"(\" b"));       // quote with parens
    assert(!balanced("f(x]"));
    std::cout << "all tests passed\n";
    return 0;
}
