#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* Reverse s in place. Safe for NULL and empty strings. */
void reverse_string(char *s)
{
    if (s == NULL)
        return;

    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0)
        return;

    j--; /* last valid index */
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

int main(void)
{
    char buf[] = "Hello, world!";
    reverse_string(buf);
    printf("%s\n", buf);   /* !dlrow ,olleH */

    char empty[] = "";
    reverse_string(empty);
    printf("[%s]\n", empty); /* [] */

    reverse_string(NULL);   /* no crash */
    return 0;
}
```

Only a single `char` temporary is used, so the swap is O(1) extra space and the loop is O(n) time. `size_t` avoids signed/unsigned comparison warnings, and the NULL/empty guards prevent an underflow on `j--`.

