#include <iostream>
#include <limits>

bool is_palindrome(int x)
{
    // Negative numbers and any trailing zero (except 0 itself) are not palindromes.
    if (x < 0 || (x % 10 == 0 && x != 0))
        return false;

    int reversed = 0;
    while (x > reversed) {
        reversed = reversed * 10 + x % 10;
        x /= 10;
    }
    // Even digit count: x == reversed.  Odd digit count: drop middle via x == reversed / 10.
    return x == reversed || x == reversed / 10;
}

int main()
{
    for (int v : {121, -121, 10, 0, 12321, 123456, 7}) {
        std::cout << v << " -> " << (is_palindrome(v) ? "true" : "false") << '\n';
    }
    return 0;
}
```

