fn fibonacci(n: u32) -> Result<u64, &'static str> {
    let (mut a, mut b) = (0u64, 1u64);

    for _ in 0..n {
        let next = a.checked_add(b).ok_or("overflow: result exceeds u64")?;
        a = b;
        b = next;
    }

    Ok(a)
}

fn main() {
    assert_eq!(fibonacci(0), Ok(0));
    assert_eq!(fibonacci(1), Ok(1));
    assert_eq!(fibonacci(10), Ok(55));
    assert_eq!(fibonacci(50), Ok(12586269025));
    assert!(fibonacci(100).is_err()); // u64 overflows past ~93
    println!("fib(20) = {:?}", fibonacci(20));
}
