pub fn fib_memo(n: u64) -> u128 {
    fn go(n: u64, memo: &mut HashMap<u64, u128>) -> u128 {
        if n < 2 {
            return n as u128;
        }
        if let Some(&v) = memo.get(&n) {
            return v;
        }
        let v = go(n - 1, memo) + go(n - 2, memo);
        memo.insert(n, v);
        v
    }
    go(n, &mut HashMap::new())
