#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
    std::array<T, N> buf_{};
    std::size_t head_ = 0;  // next write position
    std::size_t count_ = 0;

public:
    void push(const T& value) {
        buf_[head_] = value;
        head_ = (head_ + 1) % N;
        if (count_ < N) ++count_;
    }

    const T& front() const {
        if (count_ == 0) throw std::out_of_range("empty ring buffer");
        return buf_[(head_ + N - count_) % N];
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.empty()) return 1;
    rb.push(1); rb.push(2); rb.push(3);
    if (rb.front() != 1 || rb.size() != 3) return 1;
    rb.push(4);                       // overwrites 1
    if (rb.front() != 2 || rb.size() != 3) return 1;
    std::cout << "ok\n";
    return 0;
}
```

Only `head_` and `count_` are needed: `count_ < N` distinguishes grow phase from overwrite phase. `front()` reconstructs the oldest slot without a separate tail pointer.

```cpp
#include <iostream>
#include <vector>

int bsearch(const std::vector<int>& a, int target) {
    int lo = 0, hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;   // avoid overflow
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

// First index i with a[i] >= target, or a.size() if none.
std::size_t lowerBound(const std::vector<int>& a, int target) {
    std::size_t lo = 0, hi = a.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

int main() {
    std::vector<int> a{1, 3, 3, 5, 8, 8, 9};
    if (bsearch(a, 5) != 3) return 1;
    if (bsearch(a, 4) != -1) return 1;
    if (bsearch({}, 1) != -1) return 1;
    if (lowerBound(a, 3) != 1) return 1;
    if (lowerBound(a, 10) != a.size()) return 1;
    std::cout << "ok\n";
    return 0;
}
```

`lo + (hi - lo) / 2` avoids overflow on huge arrays. The half-open `[lo, hi)` invariant in `lowerBound` is what makes returning `a.size()` correct when all elements are smaller.

