use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let counter = Arc::new(Mutex::new(0u64));
    let threads: usize = 8;
    let per_thread: u64 = 1000;

    let mut handles = Vec::with_capacity(threads);
    for _ in 0..threads {
        let counter = Arc::clone(&counter);
        handles.push(thread::spawn(move || {
            for _ in 0..per_thread {
                let mut guard = counter.lock().unwrap();
                *guard += 1;
            }
        }));
    }

    for h in handles {
        h.join().expect("worker thread panicked");
    }

    let total = *counter.lock().unwrap();
    assert_eq!(total, threads as u64 * per_thread);
    println!("total = {total}");
}
```

Each thread gets its own `Arc` clone so the `move` closure owns a reference. `lock().unwrap()` will panic only if another thread panicked while holding the lock, and `join` propagates that. The final `assert_eq!` proves there is no lost update.

