            return Err(format!("line {}: empty key", lineno + 1));
        }
        if map.insert(key.clone(), value).is_some() {
            duplicates.push(key);
        }
    }
    Ok((map, duplicates))
}

fn main() {
    let text = "# config\nhost = localhost\nport=8080\n\nhost = 127.0.0.1\n";
    let (map, dups) = parse_config(text).expect("valid input");
    assert_eq!(map.get("port").map(String::as_str), Some("8080"));
    assert_eq!(map.get("host").map(String::as_str), Some("127.0.0.1"));
    assert_eq!(dups, vec!["host".to_string()]);
    assert!(parse_config("broken").is_err());
    println!("ok");
