// Reverse a NUL-terminated string in place. NULL or empty is a no-op.
void reverse_cstr(char* s) {
    if (s == nullptr) return;
    std::size_t len = std::strlen(s);
    if (len < 2) return;
    for (std::size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

int main() {
    char a[] = "hello";
    reverse_cstr(a);
    std::cout << a << "\n";        // olleh

    char b[] = "";
    reverse_cstr(b);
    std::cout << b << "\n";        // (empty line)

    reverse_cstr(nullptr);          // must not crash
    std::cout << "safe\n";
    return 0;
}
```

Two indices walk toward the middle, swapping bytes. `strlen` gives the length once; the NUL stays where it is, so no allocation. The null-pointer guard is what keeps the `nullptr` call from segfaulting.

