fn is_palindrome(s: &str) -> bool {
    let cleaned: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();

    let mut left = 0usize;
    let mut right = cleaned.len();
    while left < right {
        right -= 1;
        if cleaned[left] != cleaned[right] {
            return false;
        }
        left += 1;
    }
    true
}

