```rust
use std::collections::HashMap;

fn fib_memo(n: u64, cache: &mut HashMap<u64, u64>) -> u64 {
    if let Some(&v) = cache.get(&n) {
        return v;
    }
    let value = match n {
        0 => 0,
        1 => 1,
        _ => fib_memo(n - 1, cache) + fib_memo(n - 2, cache),
    };
    cache.insert(n, value);
    value
}

fn fib_iter(n: u64) -> u64 {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let next = a + b;
        a = b;
        b = next;
    }
    a
}

fn main() {
    let mut cache = HashMap::new();
    assert_eq!(fib_memo(0, &mut cache), 0);
    assert_eq!(fib_memo(10, &mut cache), 55);
    assert_eq!(fib_memo(30, &mut cache), 832040);

    for n in 0..20 {
        let mut c = HashMap::new();
        assert_eq!(fib_memo(n, &mut c), fib_iter(n));
    }
    println!("ok");
}
```

The memoized version caches each result so recursion stays linear; the iterative one uses two rolling variables and constant memory. Both agree for n < 20, which the loop checks. Values are `u64`, so overflow is the caller's concern past n≈93.

