// Parse an optionally signed decimal integer.
// Returns false on overflow, on empty input, or when no digits follow the sign.
bool parse_int(std::string_view s, int32_t& out) {
    size_t i = 0;
    while (i < s.size() && (s[i] == ' ' || s[i] == '\t' ||
                            s[i] == '\n' || s[i] == '\r')) {
        ++i;
    }
    bool negative = false;
    if (i < s.size() && (s[i] == '+' || s[i] == '-')) {
        negative = (s[i] == '-');
        ++i;
    }
    if (i >= s.size() || s[i] < '0' || s[i] > '9') return false;

    const int64_t limit = negative ? 2147483648LL : 2147483647LL;
    int64_t acc = 0;
    for (; i < s.size() && s[i] >= '0' && s[i] <= '9'; ++i) {
        acc = acc * 10 + (s[i] - '0');
        if (acc > limit) return false;
    }
    out = static_cast<int32_t>(negative ? -acc : acc);
    return true;
}

int main() {
    int32_t v;
    struct Case { const char* in; bool ok; int32_t want; };
    Case cases[] = {
        {"  42", true, 42},
        {"-7", true, -7},
        {"+100", true, 100},
        {"", false, 0},
        {"x12", false, 0},
        {"2147483647", true, 2147483647},
        {"2147483648", false, 0},
        {"-2147483648", true, -2147483648},
    };
    for (const auto& c : cases) {
        bool ok = parse_int(c.in, v);
        if (ok != c.ok || (ok && v != c.want)) {
            std::cerr << "FAIL: " << c.in << "\n";
            return 1;
        }
    }
    std::cout << "all tests passed\n";
}
