pub fn longest_common_prefix(words: &[&str]) -> String {
    let Some(first) = words.first() else {
        return String::new();
    };
    // Walk byte positions until a mismatch, but only over char boundaries
    // of the first word to keep the slice valid UTF-8.
    let mut end = 0usize;
    'outer: for (i, _) in first.char_indices() {
        let ch = first[i..].chars().next().unwrap();
        for other in &words[1..] {
            match other[i..].chars().next() {
                Some(c) if c == ch => {}
                _ => break 'outer,
            }
        }
        end = i + ch.len_utf8();
    }
    first[..end].to_string()
}

fn main() {
