struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse_list(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);

    head = reverse_list(head);
    assert(head->value == 3 && head->next->value == 2 && head->next->next->value == 1);

    Node* empty = reverse_list(nullptr);
    assert(empty == nullptr);

    while (head) {
        Node* nxt = head->next;
        delete head;
        head = nxt;
    }
    std::cout << "ok\n";
    return 0;
}
```

The loop rewires each `next` pointer to the previous node, then advances. Null input returns null, and the test frees the nodes to avoid leaks.

