def fib(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


@lru_cache(maxsize=None)
def fib_rec(n):
    if n < 2:
        return n
    return fib_rec(n - 1) + fib_rec(n - 2)


if __name__ == "__main__":
    assert fib(0) == 0
    assert fib(1) == 1
    assert fib(10) == 55
    assert fib(0) == fib_rec(0)
    assert fib(10) == fib_rec(10)
    big = fib(1000)
    assert len(str(big)) == 209
    try:
        fib(-1)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
    print("ok")
