def merge_intervals(intervals):
    """intervals: iterable of (start, end) with start <= end."""
    cleaned = sorted((s, e) for s, e in intervals if s <= e)
    if not cleaned:
        return []
    merged = [list(cleaned[0])]
    for start, end in cleaned[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return [tuple(m) for m in merged]


def total_coverage(intervals) -> int:
    return sum(e - s for s, e in merge_intervals(intervals))


if __name__ == "__main__":
    data = [(1, 3), (2, 6), (8, 10), (15, 18), (17, 20), (19, 19)]
    print(merge_intervals(data))
    print(total_coverage(data))
