#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *data;
    size_t len;
    size_t cap;
} StrBuf;

int sb_init(StrBuf *sb, size_t cap) {
    sb->data = malloc(cap ? cap : 1);
    if (!sb->data) return 0;
    sb->data[0] = '\0';
    sb->len = 0;
    sb->cap = cap ? cap : 1;
    return 1;
}

int sb_append(StrBuf *sb, const char *s) {
    size_t n = strlen(s);
    if (sb->len + n + 1 > sb->cap) {
        size_t newcap = sb->cap;
        while (newcap < sb->len + n + 1) newcap *= 2;
        char *p = realloc(sb->data, newcap);
        if (!p) return 0;
        sb->data = p;
        sb->cap = newcap;
    }
    memcpy(sb->data + sb->len, s, n + 1);
    sb->len += n;
    return 1;
}

void sb_free(StrBuf *sb) {
    free(sb->data);
    sb->data = NULL;
    sb->len = sb->cap = 0;
}

int main(void) {
    StrBuf sb;
    if (!sb_init(&sb, 4)) return 1;
    for (int i = 0; i < 100; i++) {
        char tmp[16];
        snprintf(tmp, sizeof tmp, "%d,", i);
        if (!sb_append(&sb, tmp)) { sb_free(&sb); return 1; }
    }
    printf("len=%zu cap=%zu\n", sb.len, sb.cap);
    printf("%.30s...\n", sb.data);
    sb_free(&sb);
    return 0;
}
