    if (v.empty()) return std::nullopt;
    T best = v[0];
    for (std::size_t i = 1; i < v.size(); ++i) {
        if (v[i] > best) best = v[i];
    }
    return best;
}

int main() {
    std::vector<int> empty;
    std::vector<int> nums{3, -7, 42, 42, 10};

    auto a = max_element(empty);
    auto b = max_element(nums);
    std::cout << (a ? "has value" : "empty") << '\n';
    if (b) std::cout << *b << '\n';
    return 0;
}
```

Returning `std::optional<T>` makes the empty case explicit at the type level instead of returning a sentinel. The loop starts at index 1, so equal maxima keep the first occurrence but the value is identical either way.

