```rust
#[derive(Debug, PartialEq)]
enum ParseError {
    UnexpectedChar(char),
    UnexpectedEnd,
}

struct Parser<'a> {
    chars: std::iter::Peekable<std::str::Chars<'a>>,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { chars: s.chars().peekable() }
    }

    fn parse_expr(&mut self) -> Result<i64, ParseError> {
        let mut value = self.parse_term()?;
        while let Some('+') = self.chars.peek().copied() {
            self.chars.next();
            value += self.parse_term()?;
        }
        Ok(value)
    }

    fn parse_term(&mut self) -> Result<i64, ParseError> {
        let mut value = self.parse_factor()?;
        while let Some('*') = self.chars.peek().copied() {
            self.chars.next();
            value *= self.parse_factor()?;
        }
        Ok(value)
    }

    fn parse_factor(&mut self) -> Result<i64, ParseError> {
        match self.chars.next() {
            Some(c) if c.is_ascii_digit() => {
                let mut n = c.to_digit(10).unwrap() as i64;
                while let Some(d) = self.chars.peek().and_then(|c| c.to_digit(10)) {
                    n = n * 10 + d as i64;
                    self.chars.next();
                }
                Ok(n)
            }
            Some(c) => Err(ParseError::UnexpectedChar(c)),
            None => Err(ParseError::UnexpectedEnd),
        }
    }
}

fn eval(s: &str) -> Result<i64, ParseError> {
    Parser::new(s).parse_expr()
}

fn main() {
    assert_eq!(eval("2+3*4"), Ok(14));
    assert_eq!(eval("10"), Ok(10));
    assert_eq!(eval("2+"), Err(ParseError::UnexpectedEnd));
    assert_eq!(eval("2%3"), Err(ParseError::UnexpectedChar('%')));
    println!("ok");
}
```

The grammar `expr := term ('+' term)*`, `term := factor ('*' factor)*` gives `*` higher precedence than `+` by construction. Multi-digit numbers are read digit by digit, and any non-digit where a factor is expected becomes `UnexpectedChar`.

```c
#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

enum parse_status { PARSE_OK, PARSE_EMPTY, PARSE_BAD_CHAR, PARSE_OVERFLOW, PARSE_TRAILING };

static enum parse_status parse_ulong(const char *s, unsigned long *out) {
    if (s == NULL || *s == '\0') return PARSE_EMPTY;

    const char *p = s;
    while (isspace((unsigned char)*p)) p++;
    if (*p == '\0') return PARSE_EMPTY;
    if (*p == '-') return PARSE_BAD_CHAR;

    errno = 0;
    char *end = NULL;
    unsigned long value = strtoul(p, &end, 10);
    if (end == p) return PARSE_BAD_CHAR;
    if (errno == ERANGE) return PARSE_OVERFLOW;
    if (*end != '\0') return PARSE_TRAILING;

    *out = value;
    return PARSE_OK;
}

int main(void) {
    unsigned long v;
    enum parse_status st = parse_ulong(" 42 ", &v);
    printf("status=%d value=%lu\n", st, v);
    printf("neg=%d empty=%d bad=%d\n",
           parse_ulong("-5", &v),
           parse_ulong("   ", &v),
           parse_ulong("12x", &v));
    return 0;
}
```

`strtoul` handles the digits and overflow; the wrapper detects the cases it hides: leading sign, empty input, and trailing garbage. `errno` is reset before the call so a stale value cannot be mistaken for overflow.

