#include <iostream>
#include <vector>

std::vector<int> merge_unique(const std::vector<int>& a,
                              const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    size_t i = 0, j = 0;
    auto push = [&out](int v) {
        if (out.empty() || out.back() != v) out.push_back(v);
    };
    while (i < a.size() && j < b.size()) {
        if (a[i] < b[j]) push(a[i++]);
        else if (b[j] < a[i]) push(b[j++]);
        else { push(a[i]); ++i; ++j; }
    }
    while (i < a.size()) push(a[i++]);
    while (j < b.size()) push(b[j++]);
    return out;
}

int main() {
    for (int v : merge_unique({1, 2, 4, 4, 7}, {2, 3, 4, 8}))
        std::cout << v << ' ';
    std::cout << '\n';
    return 0;
}
```

Both inputs are assumed sorted. The `push` lambda drops any value equal to the last emitted one, so duplicates inside a single input and across inputs are removed in linear time.

