#include <string>
#include <string_view>

bool is_balanced(std::string_view s) {
    std::stack<char> st;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{': st.push(c); break;
            case ')':
                if (st.empty() || st.top() != '(') return false;
                st.pop(); break;
            case ']':
                if (st.empty() || st.top() != '[') return false;
                st.pop(); break;
            case '}':
                if (st.empty() || st.top() != '{') return false;
                st.pop(); break;
            default: break;
        }
    }
    return st.empty();
}

int main() {
    std::cout << std::boolalpha
              << is_balanced("a(b[c]{d})e") << '\n'   // true
              << is_balanced("([)]") << '\n'           // false
              << is_balanced("") << '\n';              // true
}
```

Each closer must match the current stack top; a mismatch or leftover opener makes the result false. `st.empty()` at the end catches unclosed opens.

