```cpp
#include <algorithm>
#include <cctype>
#include <iostream>
#include <string>

// Reverse word order; collapse whitespace runs to one space; trim ends.
std::string reverse_words(const std::string& input) {
    std::string s = input;
    // Normalise whitespace in a single pass.
    std::string clean;
    clean.reserve(s.size());
    bool in_space = true;  // start true to skip leading spaces
    for (char c : s) {
        if (std::isspace(static_cast<unsigned char>(c))) {
            if (!in_space) clean.push_back(' ');
            in_space = true;
        } else {
            clean.push_back(c);
            in_space = false;
        }
    }
    while (!clean.empty() && clean.back() == ' ') clean.pop_back();
    // Reverse the whole string, then reverse each word back.
    std::reverse(clean.begin(), clean.end());
    size_t start = 0;
    for (size_t i = 0; i <= clean.size(); ++i) {
        if (i == clean.size() || clean[i] == ' ') {
            std::reverse(clean.begin() + start, clean.begin() + i);
            start = i + 1;
        }
    }
    return clean;
}

int main() {
    std::cout << "[" << reverse_words("  hello   world  ") << "]\n";  // [world hello]
    std::cout << "[" << reverse_words("one") << "]\n";             // [one]
    std::cout << "[" << reverse_words("   ") << "]\n";            // []
    std::cout << "[" << reverse_words("") << "]\n";               // []
    std::cout << "[" << reverse_words("a b c d") << "]\n";        // [d c b a]
    return 0;
}
```
The `isspace` cast to `unsigned char` avoids undefined behaviour on negative `char` values. Reversing twice — whole string, then each word — is the standard O(n) in-place trick.

```cpp
#include <cstddef>
#include <iostream>
#include <vector>

class RingSum {
public:
    explicit RingSum(std::size_t capacity)
        : buf_(capacity), cap_(capacity) {
        if (cap_ == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(int v) {
        if (count_ == cap_) {
            sum_ -= buf_[head_];       // evict oldest still in the sum
        } else {
            ++count_;
        }
        buf_[head_] = v;
        sum_ += v;
        head_ = (head_ + 1) % cap_;
    }

    long long sum() const { return sum_; }
    std::size_t size() const { return count_; }

private:
    std::vector<int> buf_;
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t count_ = 0;
    long long sum_ = 0;
};

int main() {
    RingSum r(3);
    r.push(1); r.push(2); r.push(3);
    if (r.sum() != 6) { std::cerr << "fail 1\n"; return 1; }
    r.push(4);                       // evicts 1
    if (r.sum() != 9 || r.size() != 3) { std::cerr << "fail 2\n"; return 1; }
    r.push(-4);                      // evicts 2
    if (r.sum() != 3) { std::cerr << "fail 3\n"; return 1; }
    std::cout << "ok\n";
    return 0;
}
```
`sum_` is maintained incrementally, so `sum()` is O(1). `head_` always points at the slot to write next, which is also the oldest element once the buffer is full.

