```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[]), vec![1, 3, 5]);
    assert_eq!(merge_sorted(&[], &[2, 4]), vec![2, 4]);
    assert_eq!(merge_sorted(&[1, 2, 3], &[2, 2, 4]), vec![1, 2, 2, 2, 3, 4]);
    assert_eq!(merge_sorted(&[i32::MIN], &[i32::MAX]), vec![i32::MIN, i32::MAX]);
    println!("ok");
}
```
Comparison uses `<=` so equal elements from `a` come first, which is a stable merge. The tail `extend_from_slice` calls copy the remainder without extra branching, and because no arithmetic is done on the values, `i32::MIN` and `i32::MAX` are safe.

