/* Returns true and stores the value on success. On failure *out is untouched. */
bool parse_long(const char *s, long *out) {
    if (s == NULL || *s == '\0') return false;
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (end == s) return false;            /* no digits at all */
    if (errno == ERANGE) return false;     /* overflow/underflow */
    while (*end == ' ' || *end == '\t' || *end == '\n' ||
           *end == '\r' || *end == '\f' || *end == '\v') end++;
    if (*end != '\0') return false;        /* trailing junk */
    *out = v;
    return true;
}

int main(void) {
    long v = 0;
    const char *good[] = {"0", "123", "-42", " 7 ", "9223372036854775807"};
    const char *bad[]  = {"", "   ", "12x", "x12", "--3", NULL};
    for (int i = 0; good[i]; i++)
        if (!parse_long(good[i], &v)) { fprintf(stderr, "rejected good: %s\n", good[i]); return 1; }
    for (int i = 0; bad[i]; i++)
        if (parse_long(bad[i], &v)) { fprintf(stderr, "accepted bad: %s\n", bad[i]); return 1; }
    puts("ok");
    return 0;
}
```
`errno` is reset to 0 before `strtol` because the function only sets `ERANGE` on overflow and never clears it. Checking `end == s` catches strings with no digits; the trailing-whitespace skip makes `" 7 "` valid while `"12x"` stays invalid.

