```python
def rle_encode(text):
    if not text:
        return ""
    parts = []
    prev = text[0]
    count = 1
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            parts.append(f"{count}{prev}")
            prev = ch
            count = 1
    parts.append(f"{count}{prev}")
    return "".join(parts)

def rle_decode(encoded):
    if not encoded:
        return ""
    out = []
    i = 0
    while i < len(encoded):
        j = i
        while j < len(encoded) and encoded[j].isdigit():
            j += 1
        if j == i or j >= len(encoded):
            raise ValueError(f"malformed encoding at index {i}")
        out.append(encoded[j] * int(encoded[i:j]))
        i = j + 1
    return "".join(out)

if __name__ == "__main__":
    for sample in ["", "a", "aaabbbcccd", "wwwwwwwwwwww"]:
        assert rle_decode(rle_encode(sample)) == sample, sample
    print("ok")
```

The count is written as a full decimal number, so runs longer than 9 decode correctly (unlike the single-digit variant). Decoding validates the digit run and raises `ValueError` on truncated input, and the round-trip assertion covers empty, single-char, and long-run cases including Unicode-safe `str` handling.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *make_node(int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = NULL;
    return n;
}

static Node *reverse_iterative(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *reverse_recursive(Node *head) {
    if (!head || !head->next) {
        return head;
    }
    Node *new_head = reverse_recursive(head->next);
    head->next->next = head;
    head->next = NULL;
    return new_head;
}

static void print_list(const Node *head) {
    for (; head; head = head->next) {
        printf("%d%s", head->value, head->next ? " -> " : "\n");
    }
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 5; i >= 1; --i) {
        Node *n = make_node(i);
        n->next = head;
        head = n;
    }
    print_list(head);
    head = reverse_iterative(head);
    print_list(head);
    head = reverse_recursive(head);
    print_list(head);
    free_list(head);
    return 0;
}
```

Both functions return the new head and handle empty and single-node lists. The recursive version recurses only as deep as the list length, so keep it for short lists; the iterative one is the safe default for large inputs.

