#include <iostream>
#include <vector>

int lower_bound_index(const std::vector<int>& data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (data[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

int first_match(const std::vector<int>& data, int target) {
    int idx = lower_bound_index(data, target);
    if (idx < static_cast<int>(data.size()) && data[idx] == target) {
        return idx;
    }
    return -1;
}

int main() {
    std::vector<int> data = {1, 3, 3, 3, 5, 7, 9};
    std::cout << first_match(data, 3) << '\n';
    std::cout << first_match(data, 6) << '\n';
    std::cout << first_match(data, 1) << '\n';
    return 0;
}
```

The `lower_bound_index` helper finds the leftmost position where `target` could sit; `first_match` then checks that slot. Output is `1`, `-1`, `0` — duplicates resolve to the earliest index and missing values return `-1`.

