```cpp
#include <condition_variable>
#include <mutex>
#include <queue>
#include <optional>

template <typename T>
class BoundedQueue {
    std::queue<T> q_;
    std::mutex m_;
    std::condition_variable not_full_, not_empty_;
    size_t cap_;
public:
    explicit BoundedQueue(size_t cap) : cap_(cap) {}

    void push(T value) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [&] { return q_.size() < cap_; });
        q_.push(std::move(value));
        lk.unlock();
        not_empty_.notify_one();
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [&] { return !q_.empty(); });
        T v = std::move(q_.front());
        q_.pop();
        lk.unlock();
        not_full_.notify_one();
        return v;
    }
};
```
Predicates in both waits guard against spurious wakeups, and the lock is released before notifying to avoid waking a thread that immediately blocks on the mutex.

