    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    std::int64_t c = (a * ((2 * b % MOD - a + MOD) % MOD)) % MOD;
    std::int64_t d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1) return {d, (c + d) % MOD};
    return {c, d};
}

int main() {
    std::int64_t n;
    if (!(std::cin >> n) || n < 0) {
        std::cerr << "expected a non-negative integer\n";
        return 1;
    }
    std::cout << fib_pair(n).first << '\n';
    return 0;
}
```
Fast doubling gives O(log n) recursive depth with `int64_t` intermediates; the `+ MOD` before the modulo keeps the subtraction non-negative.

