        let empty: Vec<String> = Vec::new();
        assert_eq!(dedup_preserve_order(&empty), empty);
        let words = vec!["café".to_string(), "thé".to_string(), "café".to_string()];
        assert_eq!(dedup_preserve_order(&words), vec!["café", "thé"]);
