```python
import threading
import time

class BoundedQueue:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._items = []
        self._cond = threading.Condition()

    def put(self, item):
        with self._cond:
            while len(self._items) >= self.capacity:
                self._cond.wait()
            self._items.append(item)
            self._cond.notify_all()

    def get(self):
        with self._cond:
            while not self._items:
                self._cond.wait()
            item = self._items.pop(0)
            self._cond.notify_all()
            return item


def main():
    q = BoundedQueue(3)

    def producer():
        for i in range(10):
            q.put(i)
            print("put", i)

    def consumer():
        for _ in range(10):
            item = q.get()
            print("got", item)
            time.sleep(0.01)

    threads = [threading.Thread(target=producer), threading.Thread(target=consumer)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    print("done")

if __name__ == "__main__":
    main()
```
The `while` loop re-checks the condition after every wakeup, which is required because `wait` can return spuriously. `notify_all` wakes both blocked producers and consumers; each re-evaluates its own predicate.

