fn balanced(s: &str) -> Result<(), usize> {
    let mut stack: Vec<(char, usize)> = Vec::new();
    let pairs = |c: char| match c {
        ')' => Some('('),
        ']' => Some('['),
        '}' => Some('{'),
        _ => None,
    };

    for (i, c) in s.chars().enumerate() {
        match c {
            '(' | '[' | '{' => stack.push((c, i)),
            ')' | ']' | '}' => match stack.pop() {
                Some((open, _)) if Some(open) == pairs(c) => {}
                _ => return Err(i),
            },
            _ => {}
        }
    }
    if let Some((_, i)) = stack.pop() {
        return Err(i);
    }
    Ok(())
}

fn main() {
    assert_eq!(balanced("a(b[c]d)e"), Ok(()));
    assert_eq!(balanced("(]"), Err(1));
    assert_eq!(balanced("(("), Err(1));
    assert_eq!(balanced(""), Ok(()));
    assert_eq!(balanced("())"), Err(2));
    println!("ok");
}
