bool is_palindrome(const std::string& s) {
    std::size_t left = 0;
    std::size_t right = s.size();
    while (left < right) {
        const unsigned char lc =
            static_cast<unsigned char>(s[left]);
        const unsigned char rc =
            static_cast<unsigned char>(s[right - 1]);
        if (!std::isalnum(lc)) {
            ++left;
            continue;
        }
        if (!std::isalnum(rc)) {
            --right;
            continue;
        }
        if (std::tolower(lc) != std::tolower(rc)) return false;
        ++left;
        --right;
    }
    return true;
}
