#include <iostream>
#include <vector>

std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        // <= keeps the merge stable and keeps all duplicates.
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else              out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

static void print(const std::vector<int>& v) {
    std::cout << '[';
    for (std::size_t k = 0; k < v.size(); ++k)
        std::cout << (k ? ", " : "") << v[k];
    std::cout << ']';
}

int main() {
    const std::vector<int> a{1, 3, 3, 7};
    const std::vector<int> b{2, 3, 8};
    const std::vector<int> empty{};

    print(merge_sorted(a, b));       std::cout << '\n';  // [1, 2, 3, 3, 3, 7, 8]
    print(merge_sorted(a, empty));   std::cout << '\n';  // [1, 3, 3, 7]
    print(merge_sorted(empty, empty));std::cout << '\n'; // []
    return 0;
}
