#include <iostream>
#include <cstdint>
#include <limits>
#include <optional>

// Compile-time factorial via template recursion; stops at 0! = 1.
template <unsigned N>
struct Factorial {
    static constexpr uint64_t value = static_cast<uint64_t>(N) * Factorial<N - 1>::value;
};
template <>
struct Factorial<0> { static constexpr uint64_t value = 1; };

// Runtime factorial with an explicit overflow check.
std::optional<uint64_t> factorial(unsigned n) {
    uint64_t result = 1;
    for (unsigned i = 2; i <= n; ++i) {
        if (result > std::numeric_limits<uint64_t>::max() / i) {
            return std::nullopt;  // would overflow
        }
        result *= i;
    }
    return result;
}

int main() {
    std::cout << "5! (constexpr) = " << Factorial<5>::value << '\n';
    for (unsigned n : {0u, 5u, 20u, 21u}) {
        auto r = factorial(n);
        if (r) std::cout << n << "! = " << *r << '\n';
        else   std::cout << n << "! overflows uint64_t\n";
    }
    return 0;
}
```

The template version fails to compile if it overflows `uint64_t`, which is the desired signal. `factorial` checks `result > MAX / i` *before* multiplying, so 20! (2432902008176640000) fits and 21! returns `std::nullopt` instead of wrapping.

```rust
fn binary_search_or_insert(haystack: &[i32], needle: i32) -> Result<usize, usize> {
    let mut lo = 0usize;
    let mut hi = haystack.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;  // no overflow on large slices
        match haystack[mid].cmp(&needle) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Ok(mid),
        }
    }
    Err(lo)  // lo == hi is the insertion point
}

fn main() {
    let data = [1, 3, 5, 7, 9, 11];
    println!("{:?}", binary_search_or_insert(&data, 7));   // Ok(3)
    println!("{:?}", binary_search_or_insert(&data, 8));   // Err(4)
    println!("{:?}", binary_search_or_insert(&data, 0));   // Err(0)
    println!("{:?}", binary_search_or_insert(&data, 12));  // Err(6)
    println!("{:?}", binary_search_or_insert(&[], 42));    // Err(0)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn insertion_points() {
        let v = [2, 4, 6];
        assert_eq!(binary_search_or_insert(&v, 4), Ok(1));
        assert_eq!(binary_search_or_insert(&v, 5), Err(2));
    }
}
```

`Ok(i)` means `needle` sits at index `i`; `Err(i)` means it is absent and `i` is where it belongs. `mid` is computed as `lo + (hi - lo) / 2` to avoid overflow on enormous slices, and the empty case returns `Err(0)`.

