std::optional<double> safe_mean(const std::vector<double>& xs) {
    if (xs.empty()) return std::nullopt;
    double sum = 0.0;
    std::size_t n = 0;
    for (double x : xs) {
        if (std::isnan(x)) continue;   // skip NaN, don't poison the sum
