#include <cctype>
#include <string>

void trim_in_place(std::string& s) {
    const auto not_space = [](unsigned char c) { return !std::isspace(c); };
    auto begin = s.begin();
    while (begin != s.end() && !not_space(static_cast<unsigned char>(*begin))) ++begin;
    auto end = s.end();
    while (end != begin && !not_space(static_cast<unsigned char>(*(end - 1)))) --end;
    if (begin == s.begin() && end == s.end()) return;
    s.assign(begin, end);   // one copy, only of the kept range
}
```

Scanning with iterators keeps both endpoints contiguous, so `assign` makes a single copy of the trimmed range. Casting to `unsigned char` before `isspace` avoids undefined behaviour on negative `char` values.

