```python
from collections import deque
from typing import Deque, Iterable, Optional


class BoundedBuffer:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._cap = capacity
        self._items: Deque[int] = deque()

    def push(self, item: int) -> Optional[int]:
        evicted = None
        if len(self._items) == self._cap:
            evicted = self._items.popleft()
        self._items.append(item)
        return evicted

    def __len__(self) -> int:
        return len(self._items)

    def snapshot(self) -> Iterable[int]:
        return tuple(self._items)


if __name__ == "__main__":
    b = BoundedBuffer(2)
    print(b.push(1), b.push(2), b.push(3))  # None None 1
    print(b.snapshot())                       # (2, 3)
```

`deque` gives O(1) `popleft`, so eviction is cheap even at scale. `push` returns the dropped value (or `None`), letting callers react to overflow instead of losing data silently.

