            name, raw = row[0].strip(), row[1].strip()
            if not name:
                print(f"line {lineno}: empty name", file=sys.stderr)
                continue
            try:
                sums[name] += float(raw)
            except ValueError:
                print(f"line {lineno}: not a number: {raw!r}", file=sys.stderr)
    return dict(sums)


if __name__ == "__main__":
