fn merge(mut intervals: Vec<Interval>) -> Vec<Interval> {
    if intervals.is_empty() {
        return Vec::new();
    }
    intervals.sort_by_key(|iv| (iv.start, iv.end));

    let mut out = Vec::with_capacity(intervals.len());
    let mut cur = intervals[0];

