```rust
use std::collections::{HashMap, VecDeque};

struct BoundedCache<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: Clone + Eq + std::hash::Hash, V> BoundedCache<K, V> {
    fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        Self { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    fn insert(&mut self, key: K, value: V) {
        if self.map.insert(key.clone(), value).is_none() {
            self.order.push_back(key);
        }
        while self.order.len() > self.cap {
            if let Some(oldest) = self.order.pop_front() {
                if oldest != key {
                    self.map.remove(&oldest);
                }
            }
        }
    }

    fn get(&self, key: &K) -> Option<&V> {
        self.map.get(key)
    }

    fn len(&self) -> usize {
        self.map.len()
    }
}

fn main() {
    let mut c = BoundedCache::new(2);
    c.insert("a", 1);
    c.insert("b", 2);
    assert_eq!(c.len(), 2);
    assert_eq!(c.get(&"a"), Some(&1));
    c.insert("c", 3);          // evicts "a"
    assert_eq!(c.get(&"a"), None);
    assert_eq!(c.get(&"c"), Some(&3));
    c.insert("b", 20);         // update without order growth
    assert_eq!(c.get(&"b"), Some(&20));
    assert_eq!(c.len(), 2);
    println!("all pass");
}
