```c
#include <stdio.h>
#include <stdint.h>
#include <inttypes.h>

int main(void) {
    unsigned int n;
    if (scanf("%u", &n) != 1) {
        fprintf(stderr, "expected a non-negative integer\n");
        return 1;
    }

    uint64_t a = 0, b = 1;
    for (unsigned int i = 0; i < n; i++) {
        if (UINT64_MAX - a < b) {
            printf("overflow at n=%u\n", i);
            return 0;
        }
        uint64_t next = a + b;
        a = b;
        b = next;
    }

    printf("fib(%u) = %" PRIu64 "\n", n, a);
    return 0;
}
