fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[]), vec![1, 3, 5]);
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 3]), vec![1, 1, 1, 2, 3]);
    println!("ok");
}
```
The two-pointer loop advances the smaller head each step, so each element is touched once. Duplicates are preserved via `<=`. The `extend_from_slice` tail handles whichever slice still has remaining elements without extra branching.

```cpp
#include <iostream>
#include <vector>

void rotate90(std::vector<std::vector<int>>& m) {
    const int n = static_cast<int>(m.size());
    for (int i = 0; i < n; ++i)
        for (int j = i + 1; j < n; ++j)
            std::swap(m[i][j], m[j][i]);
    for (int i = 0; i < n; ++i)
        for (int j = 0, k = n - 1; j < k; ++j, --k)
            std::swap(m[i][j], m[i][k]);
}

int main() {
    std::vector<std::vector<int>> m = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    rotate90(m);
    for (const auto& row : m) {
        for (size_t j = 0; j < row.size(); ++j)
            std::cout << row[j] << (j + 1 == row.size() ? '\n' : ' ');
    }
    return 0;
}
```
The transform is transpose followed by a horizontal mirror. Both passes swap pairs once, so the rotation is genuinely in place with O(1) extra space. Printing `{{1,2,3},{4,5,6},{7,8,9}}` yields `7 4 1`, `8 5 2`, `9 6 3`.

