template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

    // Oldest element, if any.
    std::optional<T> oldest() const {
        if (size_ == 0) return std::nullopt;
        const std::size_t idx = (head_ + N - size_) % N;
        return data_[idx];
    }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};
