int binary_search(const std::vector<int>& v, int target) {
    std::size_t lo = 0;
    std::size_t hi = v.size();
    while (lo < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (v[mid] == target) return static_cast<int>(mid);
        if (v[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return -1;
}

int main() {
    std::cout << binary_search({}, 5) << "\n";                 // -1
    std::cout << binary_search({7}, 7) << "\n";                // 0
    std::cout << binary_search({7}, 3) << "\n";                // -1
    std::cout << binary_search({1, 3, 5, 7, 9}, 9) << "\n";    // 4
    return 0;
}
