#include <iostream>

struct Node {
    int value;
    Node* prev = nullptr;
    Node* next = nullptr;
};

void reverse_list(Node*& head) {
    Node* current = head;
    Node* tmp = nullptr;
    while (current != nullptr) {
        tmp = current->prev;
        current->prev = current->next;
        current->next = tmp;
        current = current->prev;
    }
    if (tmp != nullptr) head = tmp->prev;
}

int main() {
    Node a{1}, b{2}, c{3};
    a.next = &b; b.prev = &a;
    b.next = &c; c.prev = &b;
    Node* head = &a;
    reverse_list(head);
    for (Node* n = head; n; n = n->next) std::cout << n->value << ' ';
    std::cout << '\n'; // 3 2 1
}
```
Swapping `prev` and `next` on every node reverses direction; `tmp` tracks the old previous so the new head can be recovered after the walk.

