bool is_palindrome(const std::string& s) {
    size_t i = 0, j = s.size();
    while (i < j) {
        if (!std::isalnum(static_cast<unsigned char>(s[i]))) { ++i; continue; }
        if (!std::isalnum(static_cast<unsigned char>(s[j - 1]))) { --j; continue; }
        if (std::tolower(static_cast<unsigned char>(s[i])) !=
            std::tolower(static_cast<unsigned char>(s[j - 1])))
            return false;
        ++i;
        --j;
    }
    return true;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_palindrome("A man, a plan, a canal: Panama") << "\n";
    std::cout << is_palindrome("") << "\n";
    std::cout << is_palindrome("hello") << "\n";
}
```

Two pointers skip non-alphanumeric characters and compare lowercased bytes. Empty string returns true; the unsigned char casts avoid undefined behavior on negative chars.

