char *reverse_in_place(char *s) {
    if (s == NULL) return NULL;
    size_t len = strlen(s);
    size_t i = 0, j = len;
    while (i < j && j > 0) {
        --j;
        if (i >= j) break;
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
    }
    return s;
