#include <iostream>
#include <stack>
#include <string>
#include <string_view>

bool is_balanced(std::string_view s) {
    std::stack<char> st;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{': st.push(c); break;
            case ')':
                if (st.empty() || st.top() != '(') return false;
                st.pop(); break;
            case ']':
                if (st.empty() || st.top() != '[') return false;
                st.pop(); break;
            case '}':
                if (st.empty() || st.top() != '{') return false;
                st.pop(); break;
            default: break;  // ignore non-bracket characters
        }
    }
    return st.empty();
}

int main() {
    struct Case { std::string_view in; bool want; };
    const Case cases[] = {
        {"", true}, {"()", true}, {"{[()]}", true}, {"(]", false},
        {"([)]", false}, {"(((", false}, {")))", false},
        {"a(b)c[d]", true}, {"\u4f60\u597d", true},
    };
    for (const auto& c : cases) {
        bool got = is_balanced(c.in);
        std::cout << '"' << c.in << "\" -> " << (got ? "true" : "false") << '\n';
        if (got != c.want) { std::cerr << "FAIL\n"; return 1; }
    }
    std::cout << "all passed\n";
    return 0;
}
```
A stack matches each closer against the most recent opener; unmatched closers return false immediately, and leftover openers fail the final `empty()` check. Non-bracket and multi-byte characters are ignored safely via `string_view`.

