template <typename T>
std::optional<T> max_element_opt(const std::vector<T>& v) {
    if (v.empty()) return std::nullopt;
    T best = v.front();
    for (const T& x : v)
        if (x > best) best = x;
    return best;
}

int main() {
    std::vector<int> empty;
    std::vector<int> nums = {3, -7, 42, 0, 42};
    std::vector<std::string> words = {"pear", "apple", "zebra"};

    if (auto m = max_element_opt(empty)) std::cout << *m << '\n';
    else std::cout << "empty -> nullopt\n";

    std::cout << *max_element_opt(nums) << '\n';    // 42
    std::cout << *max_element_opt(words) << '\n';   // zebra
}
```
Returning `std::optional<T>` makes the empty case explicit rather than undefined; ties resolve to the first maximum found, and the template works for any type with `operator>` (including `std::string`).

