use std::collections::HashMap;

fn fib_memo(n: u64, cache: &mut HashMap<u64, u128>) -> u128 {
    if n < 2 {
        return n as u128;
    }
    if let Some(&v) = cache.get(&n) {
        return v;
    }
    let v = fib_memo(n - 1, cache) + fib_memo(n - 2, cache);
    cache.insert(n, v);
    v
}

fn fib_iter(n: u64) -> u128 {
    let (mut a, mut b) = (0u128, 1u128);
    for _ in 0..n {
        let next = a + b;
        a = b;
        b = next;
    }
    a
}

fn main() {
    let mut cache = HashMap::new();
    for n in 0..=90 {
        assert_eq!(fib_memo(n, &mut cache), fib_iter(n), "mismatch at {n}");
    }
    println!("fib(50) = {}", fib_memo(50, &mut cache));
    println!("fib(90) = {}", fib_iter(90));
}
```
Memoization stores each result once so recursive lookups are O(1); both paths agree for every `n` in `0..=90`, and `u128` is wide enough to avoid overflow at `fib(90)`.

