def is_valid_ipv4(s: str) -> bool:
    """True iff s is a canonical dotted-decimal IPv4 address."""
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for p in parts:
        if not p or not p.isdigit():
            return False
        if len(p) > 1 and p[0] == "0":   # reject leading zeros like '01'
            return False
        if int(p) > 255:
            return False
    return True


