def merge_sort(items):
    if len(items) <= 1:
        return list(items)

    result = [[x] for x in items]
    while len(result) > 1:
        merged = []
        for i in range(0, len(result), 2):
            if i + 1 < len(result):
                merged.append(_merge(result[i], result[i + 1]))
            else:
                merged.append(result[i])
        result = merged
    return result[0]


def _merge(a, b):
    out = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out


if __name__ == "__main__":
    data = [5, 2, 9, 1, 5, 6, -3]
    sorted_data = merge_sort(data)
    print(sorted_data)
    print("input unchanged:", data)
