int parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return -1;
    char *end;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno == ERANGE || v < INT_MIN || v > INT_MAX) return -1;
    if (*end != '\0') return -1;
    *out = (int)v;
    return 0;
}

int main(void) {
    int v;
    printf("%d\n", parse_int("42", &v));      // 0, v=42
    printf("%d\n", parse_int("4x", &v));      // -1
    printf("%d\n", parse_int("", &v));        // -1
    printf("%d\n", parse_int("9999999999",&v)); // -1
    return 0;
}
