        return v;
    }

    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }
    std::size_t size() const { return count_; }

private:
    std::array<int, N> buf_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    if (!rb.push(4)) std::puts("full");   // full
    std::printf("%d\n", *rb.pop());       // 1
    rb.push(4);
    std::printf("%d\n", *rb.pop());       // 2
    return 0;
}
```
Fixed capacity `N` known at compile time. `count_` distinguishes full from empty (both have `head_ == tail_`), and `pop` on empty returns `nullopt` instead of undefined data.

