def max_pair_product(nums):
    """Return the largest product of two distinct indices, or None if fewer than 2 items."""
    if len(nums) < 2:
        return None
    # Track the two largest and two smallest values: the best pair is
    # either top1*top2 (positive) or min1*min2 (two negatives -> positive).
    top1 = top2 = None
    min1 = min2 = None
    for n in nums:
        if top1 is None or n > top1:
            top1, top2 = n, top1
        elif top2 is None or n > top2:
            top2 = n
        if min1 is None or n < min1:
            min1, min2 = n, min1
        elif min2 is None or n < min2:
            min2 = n
    return max(top1 * top2, min1 * min2)


if __name__ == "__main__":
    assert max_pair_product([1, 2, 3]) == 6
    assert max_pair_product([-10, -20, 4]) == 200
    assert max_pair_product([0, -1]) == 0
    assert max_pair_product([7]) is None
    assert max_pair_product([]) is None
    assert max_pair_product([5, 5]) == 25
