#include <stdio.h>

/* Returns 1 if n is a perfect square, else 0. Iterative integer method
   avoids floating-point precision problems for large values. */
int is_perfect_square(unsigned long long n) {
    if (n < 1) return 0;
    unsigned long long lo = 1, hi = n, mid;
    while (lo <= hi) {
        mid = lo + (hi - lo) / 2;
        unsigned long long sq = mid * mid;
        if (sq == n) return 1;
        if (sq < n) lo = mid + 1;
        else {
            if (mid == 1) break;
            hi = mid - 1;
        }
    }
    return 0;
}

int main(void) {
    unsigned long long cases[] = {1, 4, 9, 16, 25, 26, 2, 1000000, 1000001, 0};
    int expected[]            = {1, 1, 1,  1,  1,  0, 0,       1,       0, 0};
    for (int i = 0; i < 10; i++) {
        int got = is_perfect_square(cases[i]);
        if (got != expected[i]) {
            printf("fail on %llu: got %d\n", cases[i], got);
            return 1;
        }
    }
    printf("ok\n");
    return 0;
