template <typename T>
T second_largest(const std::vector<T>& v) {
    if (v.size() < 2) throw std::invalid_argument("need at least two elements");
    T first = v[0], second = v[0];
    bool have_first = true, have_second = false;
    for (const auto& x : v) {
        if (!have_first) { first = x; have_first = true; continue; }
        if (x > first) { second = first; have_second = true; first = x; }
        else if (x != first && (!have_second || x > second)) { second = x; have_second = true; }
