def bisect_left(seq, target):
    """Return the index where target should be inserted to keep seq sorted;
    if target is present, return the index of its first occurrence."""
    lo, hi = 0, len(seq)
    while lo < hi:
        mid = (lo + hi) // 2
        if seq[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo


