```c
#include <stdio.h>
#include <string.h>

/* Reverse a UTF-8 string in place by reversing the sequence of complete
 * codepoints, never splitting a multibyte character. */
void utf8_reverse(char *s) {
    size_t len = strlen(s);
    size_t i = 0, j = len;
    while (i < j) {
        /* find start of last codepoint before j */
        size_t k = j - 1;
        while (k > i && ((unsigned char)s[k] & 0xC0) == 0x80) k--;
        size_t cplen = j - k;
        /* rotate [i, k) and [k, j) */
        char tmp[8];
        if (cplen > sizeof tmp) return;
        memcpy(tmp, s + k, cplen);
        memmove(s + i + cplen, s + i, k - i);
        memcpy(s + i, tmp, cplen);
        i += cplen;
        j = k;
    }
}

int main(void) {
    char s[] = "he\xC3\xA9llo"; /* he\u00e9llo */
    utf8_reverse(s);
    printf("%s\n", s); /* olla\xC3\xA9eh */
    char t[] = "";
    utf8_reverse(t);
    printf("%s\n", t);
    return 0;
}
```
Detects UTF-8 start bytes via the `0x80` mask and rotates whole codepoints, so multibyte characters stay intact.

