use std::collections::HashMap;

fn longest_unique_substring(s: &str) -> usize {
    let bytes = s.as_bytes();
    let mut last_seen: HashMap<u8, usize> = HashMap::new();
    let mut start = 0usize;
    let mut best = 0usize;

    for (i, &b) in bytes.iter().enumerate() {
        if let Some(&prev) = last_seen.get(&b) {
            if prev >= start {
                start = prev + 1;
            }
        }
        last_seen.insert(b, i);
        best = best.max(i - start + 1);
    }
    best
}

fn main() {
    assert_eq!(longest_unique_substring("abcabcbb"), 3);
    assert_eq!(longest_unique_substring("bbbbb"), 1);
    assert_eq!(longest_unique_substring("pwwkew"), 3);
    assert_eq!(longest_unique_substring(""), 0);
    println!("ok");
}
```

This is the sliding-window approach: `start` only ever moves forward, so the whole scan is O(n) rather than O(n²). The `prev >= start` guard is what prevents a stale index from an earlier window from shrinking the window incorrectly.

