```python
from __future__ import annotations
from typing import Iterator, Optional


class RingBuffer:
    """Fixed-capacity FIFO buffer. Pushing into a full buffer evicts the oldest item."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._items: list[Optional[int]] = [None] * capacity
        self._head = 0
        self._size = 0

    def push(self, value: int) -> Optional[int]:
        evicted: Optional[int] = None
        if self._size == self._capacity:
            evicted = self._items[self._head]
        else:
            self._size += 1
        self._items[(self._head + self._size - 1) % self._capacity] = value
        if evicted is not None:
            self._head = (self._head + 1) % self._capacity
        return evicted

    def pop(self) -> Optional[int]:
        if self._size == 0:
            return None
        value = self._items[self._head]
        self._head = (self._head + 1) % self._capacity
        self._size -= 1
        return value

    def __len__(self) -> int:
        return self._size

    def __iter__(self) -> Iterator[int]:
        for i in range(self._size):
            yield self._items[(self._head + i) % self._capacity]


if __name__ == "__main__":
    rb = RingBuffer(3)
    for x in (1, 2, 3, 4):
        print("push", x, "evicted", rb.push(x))
    assert list(rb) == [2, 3, 4]
    assert rb.pop() == 2
    assert list(rb) == [3, 4]
    print("ok")
```

`push` returns the evicted value (or `None`) so callers can observe dropped items instead of losing them silently.

