    out.reserve(a.size() + b.size());
    std::merge(a.begin(), a.end(), b.begin(), b.end(), std::back_inserter(out));
    out.erase(std::unique(out.begin(), out.end()), out.end());
    return out;
}

int main() {
    std::vector<int> a{1, 3, 3, 5};
    std::vector<int> b{2, 3, 6};
    for (int v : merge_unique(a, b)) {
        std::cout << v << ' ';
    }
    std::cout << '\n';
    for (int v : merge_unique({}, {})) {
        std::cout << v << ' ';
    }
    std::cout << "(empty)\n";
    return 0;
}
```

`std::merge` requires both inputs sorted — which the signature documents — and `std::unique` removes adjacent duplicates, so the merge output must be sorted first. The empty-input case produces an empty result rather than reading past the end.

