fn parse_version(s: &str) -> Result<Version, String> {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 3 {
        return Err(format!("expected 3 components, got {}", parts.len()));
    }
    let mut nums = [0u32; 3];
    for (i, p) in parts.iter().enumerate() {
        if p.is_empty() {
            return Err(format!("component {i} is empty"));
        }
        nums[i] = p
            .parse::<u32>()
            .map_err(|_| format!("component {i} ({p:?}) is not a valid u32"))?;
    }
    Ok(Version { major: nums[0], minor: nums[1], patch: nums[2] })
}

fn main() {
    for input in ["1.2.3", "1.2", "a.2.3", "1.2.3\u{0}"] {
        println!("{input:?} -> {:?}", parse_version(input));
    }
