```python
import re
from itertools import groupby


def rle_encode(text):
    out = []
    for ch, group in groupby(text):
        n = sum(1 for _ in group)
        out.append(f"{n}{ch}")
    return "".join(out)


def rle_decode(encoded):
    out = []
    pos = 0
    while pos < len(encoded):
        m = re.match(r"(\d+)", encoded[pos:])
        if not m:
            raise ValueError(f"expected count at index {pos}")
        n = int(m.group(1))
        pos += m.end()
        if pos >= len(encoded):
            raise ValueError("count with no following character")
        out.append(encoded[pos] * n)
        pos += 1
    return "".join(out)


if __name__ == "__main__":
    for original in ["", "aaabbbcccd", "12x", "z"]:
        enc = rle_encode(original)
        assert rle_decode(enc) == original, (original, enc)
        print(repr(original), "->", repr(enc))
```
Every run is written as decimal count followed by exactly one character, so digits like `12x` (a real character run) decode correctly.

```c
#include <stdbool.h>
#include <stdio.h>

#define RB_CAP 4

typedef struct {
    int data[RB_CAP];
    size_t head;  /* next write */
    size_t tail;  /* next read  */
    size_t count;
} RingBuf;

void rb_init(RingBuf *rb) { rb->head = rb->tail = rb->count = 0; }

bool rb_push(RingBuf *rb, int v) {
    if (rb->count == RB_CAP) return false;
    rb->data[rb->head] = v;
    rb->head = (rb->head + 1) % RB_CAP;
    rb->count++;
    return true;
}

bool rb_pop(RingBuf *rb, int *out) {
    if (rb->count == 0) return false;
    *out = rb->data[rb->tail];
    rb->tail = (rb->tail + 1) % RB_CAP;
    rb->count--;
    return true;
}

int main(void) {
    RingBuf rb;
    rb_init(&rb);
    for (int i = 1; i <= 6; i++)
        printf("push %d -> %s\n", i, rb_push(&rb, i) ? "ok" : "full");
    int v;
    while (rb_pop(&rb, &v)) printf("pop -> %d\n", v);
    return 0;
}
```
Capacity 4 means pushes 5 and 6 report `full`; the mod arithmetic wraps head and tail without moving memory.

