```cpp
#include <iostream>
#include <list>
#include <optional>
#include <unordered_map>

template <typename K, typename V>
class LRUCache {
    size_t cap_;
    std::list<std::pair<K, V>> items_;  // front = most recent
    std::unordered_map<K, typename std::list<std::pair<K, V>>::iterator> index_;

public:
    explicit LRUCache(size_t cap) : cap_(cap) {}

    std::optional<V> get(const K& key) {
        auto it = index_.find(key);
        if (it == index_.end()) return std::nullopt;
        items_.splice(items_.begin(), items_, it->second);
        return it->second->second;
    }

    void put(const K& key, const V& value) {
        if (auto it = index_.find(key); it != index_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (items_.size() == cap_) {
            index_.erase(items_.back().first);
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        index_[key] = items_.begin();
    }
};

int main() {
    LRUCache<int, std::string> c(2);
    c.put(1, "one");
    c.put(2, "two");
    c.get(1);          // 1 is now most recent
    c.put(3, "three"); // evicts 2
    std::cout << (c.get(2) ? *c.get(2) : "<miss>") << '\n';
    std::cout << (c.get(3) ? *c.get(3) : "<miss>") << '\n';
}
```
splice moves the touched node to the front without invalidating the stored iterator, so eviction from the back stays O(1).

