#include <cstddef>
#include <optional>
#include <iostream>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(new int[capacity]), capacity_(capacity), size_(0), head_(0) {}

    RingBuffer(const RingBuffer&) = delete;
    RingBuffer& operator=(const RingBuffer&) = delete;

    ~RingBuffer() { delete[] data_; }

    bool push(int value) {
        if (size_ == capacity_) return false;
        data_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    int* data_;
    std::size_t capacity_;
    std::size_t size_;
    std::size_t head_;
};

int main() {
    RingBuffer rb(3);
    if (rb.pop().has_value()) return 1;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;
    while (auto v = rb.pop()) std::cout << *v << "\n";
    if (rb.pop().has_value()) return 1;
