```rust
pub fn hex_to_bytes(input: &str) -> Result<Vec<u8>, String> {
    if input.len() % 2 != 0 {
        return Err(format!("odd length: {}", input.len()));
    }

    let mut out = Vec::with_capacity(input.len() / 2);
    let bytes = input.as_bytes();
    for (index, pair) in bytes.chunks_exact(2).enumerate() {
        let hi = nibble(pair[0]).ok_or_else(|| {
            format!("bad hex char at byte {}: {:?}", index * 2, pair[0] as char)
        })?;
        let lo = nibble(pair[1]).ok_or_else(|| {
            format!("bad hex char at byte {}: {:?}", index * 2 + 1, pair[1] as char)
        })?;
        out.push((hi << 4) | lo);
    }
    Ok(out)
}

fn nibble(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

fn main() {
    assert_eq!(hex_to_bytes("deadBEEF").unwrap(), vec![0xDE, 0xAD, 0xBE, 0xEF]);
    assert!(hex_to_bytes("abc").is_err());
    assert!(hex_to_bytes("zz").is_err());
    assert_eq!(hex_to_bytes("").unwrap(), Vec::<u8>::new());
    println!("ok");
}
```

Odd length is rejected up front; `nibble` maps a byte to its value or `None`, and the error carries the offending byte position.

```python
import functools
import time
from typing import Callable, Tuple, Type


def retry(
    exceptions: Tuple[Type[BaseException], ...] = (Exception,),
    attempts: int = 4,
    base_delay: float = 0.5,
    max_delay: float = 8.0,
) -> Callable:
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_error = exc
                    if attempt == attempts:
                        break
                    delay = min(base_delay * (2 ** (attempt - 1)), max_delay)
                    time.sleep(delay)
            raise last_error
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(exceptions=(ValueError,), attempts=3, base_delay=0.0)
    def flaky(value: int) -> int:
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return value * 2

    assert flaky(21) == 42
    assert calls["n"] == 3
    print("ok")
```

The wrapper forwards `*args`/`**kwargs`, `functools.wraps` preserves metadata, the delay doubles per attempt capped by `max_delay`, and the final exception is re-raised.

