def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring of s.
    Expands around each center; O(n^2) time, O(1) space."""
    if not s:
        return ""
    best_start, best_end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)       # odd length
        l2, r2 = expand(i, i + 1)   # even length
        if r1 - l1 > best_end - best_start:
            best_start, best_end = l1, r1
        if r2 - l2 > best_end - best_start:
            best_start, best_end = l2, r2

    return s[best_start:best_end + 1]


if __name__ == "__main__":
    cases = ["", "a", "cbbd", "babad", "forgeeksskeegfor", "abacaba"]
    for text in cases:
        print(repr(text), "->", repr(longest_palindrome(text)))
