/* Returns 1 on success, 0 on failure (NULL, empty, trailing junk, overflow). */
int parse_long(const char *s, long *out) {
    if (s == NULL || out == NULL)
        return 0;

    errno = 0;
    char *endptr = NULL;
    long value = strtol(s, &endptr, 10);

    if (endptr == s)            /* no digits at all */
        return 0;
    if (*endptr != '\0')        /* trailing non-numeric characters */
        return 0;
    if (errno == ERANGE)        /* out of long range */
        return 0;

    *out = value;
    return 1;
}

