import hashlib
import os
import sys
from collections import defaultdict

CHUNK = 1 << 20  # 1 MiB


def file_hash(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            block = f.read(CHUNK)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def find_duplicates(root: str):
    groups = defaultdict(list)
    errors = []
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            path = os.path.join(dirpath, name)
            if os.path.islink(path):
                continue
            try:
                groups[file_hash(path)].append(path)
            except OSError as exc:
                errors.append((path, str(exc)))
    return groups, errors


def main():
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    groups, errors = find_duplicates(root)

    dups = {h: paths for h, paths in groups.items() if len(paths) > 1}
    if not dups:
        print("no duplicates found")
    for digest, paths in sorted(dups.items()):
        print(f"{digest[:12]} ({len(paths)} files)")
        for p in sorted(paths):
            print(f"  {p}")

    for path, msg in errors:
        print(f"skipped {path}: {msg}", file=sys.stderr)


if __name__ == "__main__":
    main()
