#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;                            // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high;  // min-heap
    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);

        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        double median = low.size() == high.size()
            ? (low.top() + high.top()) / 2.0
            : low.top();
        std::cout << median << '\n';
    }
    return 0;
}
