#[derive(Debug, PartialEq)]
pub enum BracketError {
    Unmatched(usize),
    Unexpected(usize),
}

pub fn check(s: &str) -> Result<(), BracketError> {
    let mut stack: Vec<(char, usize)> = Vec::new();
    for (i, c) in s.char_indices() {
        match c {
            '(' | '[' | '{' => stack.push((c, i)),
            ')' | ']' | '}' => {
                let want = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some((open, _)) if open == want => {}
                    _ => return Err(BracketError::Unexpected(i)),
                }
            }
            _ => {}
        }
    }
    stack
        .last()
        .map(|&(_, i)| Err(BracketError::Unmatched(i)))
        .unwrap_or(Ok(()))
}

fn main() {
    println!("{:?}", check("a(b[c]{d})"));
    println!("{:?}", check("([)]"));
    println!("{:?}", check("("));
}
```

`char_indices` yields byte offsets so the reported position is valid for slicing. A mismatched closer errors immediately; leftover openers report the position of the last unmatched one.

