```cpp
#include <array>
#include <cstddef>
#include <cassert>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    static_assert(N > 0, "capacity must be positive");

    bool push(const T& item) {
        if (full()) return false;
        data_[tail_] = item;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T item = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return item;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.empty());
    assert(rb.push(1));
    assert(rb.push(2));
    assert(rb.push(3));
    assert(rb.full());
    assert(!rb.push(4));

    assert(rb.pop() == 1);
    assert(rb.pop() == 2);
    assert(!rb.full());
    assert(rb.push(4));
    assert(rb.pop() == 3);
    assert(rb.pop() == 4);
    assert(rb.empty());
    assert(!rb.pop().has_value());

    return 0;
}
```

`push` returns `false` when the buffer is full instead of overwriting, and `pop` returns `std::optional` so an empty pop is explicit. Head, tail, and size are separate so a full buffer is never confused with an empty one.

