fn longest_common_prefix(words: &[String]) -> String {
    let Some(first) = words.first() else {
        return String::new();
    };

    let mut end = first.len();
    for word in &words[1..] {
        // Shrink the prefix until it is a prefix of this word, always
        // staying on a char boundary so slicing cannot panic.
        while end > 0 && !word.starts_with(&first[..end]) {
            end -= 1;
            while end > 0 && !first.is_char_boundary(end) {
                end -= 1;
            }
        }
        if end == 0 {
            return String::new();
        }
    }
    first[..end].to_string()
}

fn main() {
    let cases: Vec<(Vec<String>, &str)> = vec![
        (vec![], ""),
        (vec!["alone".into()], "alone"),
        (vec!["flower".into(), "flow".into(), "flight".into()], "fl"),
        (vec!["dog".into(), "racecar".into(), "car".into()], ""),
        (vec!["café".into(), "cafeteria".into()], "caf"),
        (vec!["\u4f60\u597d\u4e16\u754c".into(), "\u4f60\u597d\u670b\u53cb".into()], "\u4f60\u597d"),
    ];

    for (words, expected) in cases {
        let got = longest_common_prefix(&words);
        assert_eq!(got, expected, "words={words:?}");
    }
    println!("ok");
}
```

The slice stays on char boundaries, so multi-byte UTF-8 never panics with `str` slicing. The empty-input case returns an empty string rather than indexing out of bounds.

```rust
#[derive(Debug)]
struct LruCache<K, V, const N: usize> {
    entries: Vec<(K, V)>,
}

impl<K: PartialEq + Copy, V: Copy, const N: usize> LruCache<K, V, N> {
    fn new() -> Self {
        Self { entries: Vec::with_capacity(N) }
    }

    fn get(&mut self, key: &K) -> Option<V> {
        let idx = self.entries.iter().position(|(k, _)| k == key)?;
        let entry = self.entries.remove(idx);
        let value = entry.1;
        // Move the hit to the back, marking it most recently used.
        self.entries.push(entry);
        Some(value)
    }

    fn put(&mut self, key: K, value: V) {
        if let Some(idx) = self.entries.iter().position(|(k, _)| *k == key) {
            self.entries.remove(idx);
        } else if self.entries.len() == N {
            self.entries.remove(0); // evict least recently used
        }
        self.entries.push((key, value));
    }
}

fn main() {
    let mut cache: LruCache<i32, &str, 4> = LruCache::new();
    cache.put(1, "a");
    cache.put(2, "b");
    cache.put(3, "c");
    cache.put(4, "d");
    assert_eq!(cache.get(&1), Some("a"));  // 1 becomes most recent
    cache.put(5, "e");                      // evicts 2
    assert_eq!(cache.get(&2), None);
    assert_eq!(cache.get(&1), Some("a"));
    assert_eq!(cache.get(&5), Some("e"));
    cache.put(3, "z");                      // update, stays in place logically
    assert_eq!(cache.get(&3), Some("z"));
}
```

`get` removes the hit and re-pushes it so the back of the vector is always the most recently used. `put` evicts from the front once `N` entries are full. The recursive const generic `N` fixes capacity at compile time.

