use std::fmt;

#[derive(Debug, PartialEq)]
struct ParseDurationError(String);

impl fmt::Display for ParseDurationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "invalid duration: {}", self.0)
    }
}

fn parse_duration(input: &str) -> Result<u64, ParseDurationError> {
    if input.is_empty() {
        return Err(ParseDurationError("empty input".into()));
    }

    let mut total: u64 = 0;
    let mut number: Option<u64> = None;
    let mut saw_unit = false;

    for ch in input.chars() {
        if ch.is_ascii_digit() {
            let digit = ch as u64 - b'0' as u64;
            number = Some(number.unwrap_or(0) * 10 + digit);
        } else {
            let multiplier = match ch {
                'h' => 3600,
                'm' => 60,
                's' => 1,
                other => {
                    return Err(ParseDurationError(format!("unknown unit '{other}'")))
                }
            };
            let n = number.take().ok_or_else(|| {
                ParseDurationError(format!("missing number before '{ch}'"))
            })?;
            total = total
                .checked_add(n.checked_mul(multiplier).ok_or_else(|| {
                    ParseDurationError("overflow".into())
                })?)
                .ok_or_else(|| ParseDurationError("overflow".into()))?;
            saw_unit = true;
        }
    }

    if number.is_some() {
        return Err(ParseDurationError("trailing number without unit".into()));
    }
    if !saw_unit {
        return Err(ParseDurationError("no unit found".into()));
    }
    Ok(total)
}

fn main() {
    assert_eq!(parse_duration("2h30m15s"), Ok(2 * 3600 + 30 * 60 + 15));
    assert_eq!(parse_duration("45s"), Ok(45));
    assert_eq!(parse_duration("1h"), Ok(3600));
    assert!(parse_duration("").is_err());
    assert!(parse_duration("10").is_err());
    assert!(parse_duration("2x").is_err());
    assert!(parse_duration("h").is_err());
    assert!(parse_duration("99999999999999999999h").is_err());
    println!("ok");
}
```

`checked_mul` / `checked_add` turn overflow into an error instead of a panic or a silently wrapped value. Units must follow a number, and a trailing bare number is rejected, so `"10"` is an error rather than ten seconds.

```python
import heapq
import random
from typing import Iterable, List


def running_medians(stream: Iterable[float]) -> List[float]:
    """Median after each element, using a max-heap (lower) and min-heap (upper)."""
    lower: List[float] = []  # max-heap via negated values
    upper: List[float] = []  # min-heap
    medians: List[float] = []

    for value in stream:
        if not lower or value <= -lower[0]:
            heapq.heappush(lower, -value)
        else:
            heapq.heappush(upper, value)

        # Rebalance so sizes differ by at most one.
        if len(lower) > len(upper) + 1:
            heapq.heappush(upper, -heapq.heappop(lower))
        elif len(upper) > len(lower):
            heapq.heappush(lower, -heapq.heappop(upper))

        if len(lower) == len(upper):
            medians.append((-lower[0] + upper[0]) / 2.0)
        else:
            medians.append(float(-lower[0]))

    return medians


def median_of(values: List[float]) -> float:
    ordered = sorted(values)
    n = len(ordered)
    if n % 2:
        return float(ordered[n // 2])
    return (ordered[n // 2 - 1] + ordered[n // 2]) / 2.0


if __name__ == "__main__":
    rng = random.Random(1234)
    for size in (1, 2, 3, 8, 101, 500):
        for _ in range(20):
            data = [rng.uniform(-1000, 1000) for _ in range(size)]
            got = running_medians(data)
            want = [median_of(data[: i + 1]) for i in range(size)]
            assert all(abs(a - b) < 1e-9 for a, b in zip(got, want)), data
    empty = running_medians([])
    assert empty == []
    print("ok")
```

The lower half is a max-heap stored as negated values, the upper half a min-heap. Rebalancing after each insert keeps the two halves within one element, so the current median is the top of the larger heap or the average of both tops. Each push is O(log n); the `Random(1234)` seed makes the comparison against `sorted` reproducible.

```c
#include <errno.h>
#include <limits.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

/* Parse a base-10 long. Returns true on success and stores the result
 * in *out. Leading whitespace and an optional sign are accepted; any
 * trailing characters other than a NUL are an error. */
bool parse_long(const char *text, long *out) {
    if (text == NULL || out == NULL) {
        return false;
    }

    const char *cursor = text;
    bool negative = false;

    while (*cursor == ' ' || *cursor == '\t' || *cursor == '\n') {
        cursor++;
    }
    if (*cursor == '+' || *cursor == '-') {
        negative = (*cursor == '-');
        cursor++;
    }
    if (*cursor < '0' || *cursor > '9') {
        return false;
    }

    /* Accumulate in negative space so LONG_MIN is representable. */
    long limit = negative ? LONG_MIN : -LONG_MAX;
    long acc = 0;
    for (; *cursor >= '0' && *cursor <= '9'; cursor++) {
        int digit = *cursor - '0';
        if (acc < (limit + digit) / 10) {
            return false; /* would overflow */
        }
        acc = acc * 10 - digit;
    }

    if (*cursor != '\0') {
        return false; /* trailing junk */
    }

    *out = negative ? acc : -acc;
    return true;
}

int main(void) {
    struct { const char *in; bool ok; long want; } cases[] = {
        { "0",             true,  0L },
        { "  42",          true,  42L },
        { "-7",            true,  -7L },
        { "+123",          true,  123L },
        { "",              false, 0L },
        { "  ",            false, 0L },
        { "12x",           false, 0L },
        { "1 2",           false, 0L },
        { "--5",           false, 0L },
        { "9223372036854775807",  true,  LONG_MAX },
        { "-9223372036854775808", true,  LONG_MIN },
        { "9223372036854775808",  false, 0L },
    };

    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
        long got = 0;
        bool ok = parse_long(cases[i].in, &got);
        if (ok != cases[i].ok || (ok && got != cases[i].want)) {
            fprintf(stderr, "FAIL: %s\n", cases[i].in);
            return 1;
        }
    }
    puts("ok");
    return 0;
}
```

Accumulating in negative space means `LONG_MIN` is reachable while `LONG_MAX` is not exceeded, so the extremes both parse correctly. Overflow is detected with a single comparison before each multiply, and trailing non-digit characters are rejected.

