size_t utoa(unsigned int value, char *buf, size_t size) {
    char tmp[16];
    size_t len = 0;
    if (value == 0) {
        tmp[len++] = '0';
    } else {
        while (value > 0) {
            tmp[len++] = (char)('0' + value % 10);
            value /= 10;
        }
    }
    if (size < len + 1) {
        return 0;
    }
    for (size_t i = 0; i < len; i++) {
        buf[i] = tmp[len - 1 - i];
    }
    buf[len] = '\0';
    return len;
}

