def two_sum(nums, target):
    """Return indices (i, j) of the two numbers in `nums` summing to `target`.
    Single pass, O(n) time and O(n) space. Raises ValueError if none found.
    """
    seen = {}
    for i, n in enumerate(nums):
        need = target - n
        if need in seen:
            return seen[need], i
        seen[n] = i
    raise ValueError("no two numbers sum to the target")


if __name__ == "__main__":
    assert two_sum([2, 7, 11, 15], 9) == (0, 1)
    assert two_sum([3, 3], 6) == (0, 1)
    assert two_sum([-1, -2, -3, -4], -7) == (2, 3)
    try:
        two_sum([], 0)
    except ValueError:
        pass
    else:
        raise AssertionError("empty input should raise")
    try:
        two_sum([1, 2, 3], 100)
    except ValueError:
        pass
    else:
        raise AssertionError("no-pair case should raise")
