#include <algorithm>
#include <iostream>
#include <vector>

static double median(std::vector<long long> v) {
    if (v.empty()) throw std::invalid_argument("empty input");
    std::sort(v.begin(), v.end());
    std::size_t n = v.size();
    if (n % 2 == 1) return static_cast<double>(v[n / 2]);
    // Cast before adding to avoid signed overflow on large values.
    return (static_cast<double>(v[n / 2 - 1]) + static_cast<double>(v[n / 2])) / 2.0;
}

int main() {
    std::vector<long long> nums;
    long long x;
