```c
#include <stdio.h>
#include <stdint.h>

static int popcount32(uint32_t x) {
    int c = 0;
    while (x) { x &= x - 1; ++c; }   /* clear lowest set bit each step */
    return c;
}

static int clz32(uint32_t x) {
    if (x == 0) return 32;           /* undefined for 0; define it as 32 */
    int n = 0;
    while ((x & 0x80000000u) == 0) { x <<= 1; ++n; }
    return n;
}

int main(void) {
    uint32_t values[] = {0u, 1u, 0x80000000u, 0xFFFFFFFFu, 0x0000FFFFu};
    for (size_t i = 0; i < sizeof values / sizeof *values; ++i) {
        printf("%08X popcount=%d clz=%d\n",
               values[i], popcount32(values[i]), clz32(values[i]));
    }
    return 0;
}
```

The `x &= x - 1` trick clears the lowest set bit per iteration, so it runs in O(popcount). `clz32(0)` is explicitly defined as 32 because the hardware count is undefined for zero.

