pub fn check_brackets(s: &str) -> Result<(), usize> {
    let mut stack: Vec<(char, usize)> = Vec::new();
    for (i, ch) in s.char_indices() {
        match ch {
            '(' | '[' | '{' => stack.push((ch, i)),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some((open, _)) if open == expected => {}
                    _ => return Err(i),
                }
            }
            _ => {}
        }
    }
    stack.first().map(|&(_, i)| Err(i)).unwrap_or(Ok(()))
}

fn main() {
    assert_eq!(check_brackets("a(b[c]{d})e"), Ok(()));
    assert_eq!(check_brackets("(]"), Err(1));
    assert_eq!(check_brackets("(()"), Err(0));
    assert_eq!(check_brackets(""), Ok(()));
    assert_eq!(check_brackets("café(ok)"), Ok(()));
    println!("ok");
}
```

Mismatched closers fail immediately with their index; an unclosed opener reports the index of the leftover stack bottom, so `"(()"` points at the first `(`.

