pub fn parse_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut cur = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();

    while let Some(c) = chars.next() {
        if in_quotes {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    cur.push('"');   // escaped quote -> literal quote
                    chars.next();
                } else {
                    in_quotes = false;
                }
            } else {
                cur.push(c);
            }
        } else if c == '"' {
            in_quotes = true;
        } else if c == ',' {
            fields.push(std::mem::take(&mut cur));
        } else {
            cur.push(c);
        }
    }
    fields.push(cur);
    fields
}

fn main() {
    assert_eq!(parse_csv_line("a,b,c"), vec!["a", "b", "c"]);
    assert_eq!(parse_csv_line("\"hello, world\",x"), vec!["hello, world", "x"]);
    assert_eq!(parse_csv_line("\"say \"\"hi\"\"\""), vec!["say \"hi\""]);
    assert_eq!(parse_csv_line(""), vec![""]);
    println!("ok");
}
```

A doubled quote inside a quoted region appends one literal quote; a lone quote toggles the mode. Empty input yields one empty field, matching RFC 4180.

