template <typename T>
std::vector<T> dedupe_ordered(const std::vector<T>& in) {
    std::vector<T> out;
    std::unordered_set<T> seen;
    out.reserve(in.size());
    for (const T& v : in) {
        if (seen.insert(v).second) out.push_back(v);
    }
    return out;
}

int main() {
    auto r = dedupe_ordered(std::vector<int>{3, 1, 3, 2, 1, 4, 2});
    for (int v : r) std::cout << v << ' ';
    std::cout << '\n';   // 3 1 2 4

    auto s = dedupe_ordered(std::vector<std::string>{"a", "b", "a", "c", ""});
    for (const auto& v : s) std::cout << '[' << v << ']';
    std::cout << '\n';   // [a][b][c][]

    auto e = dedupe_ordered(std::vector<int>{});
    std::cout << "empty size " << e.size() << '\n';  // 0
}
