#include <cstdio>
#include <stdexcept>
#include <string>

class FileHandle {
public:
    explicit FileHandle(const std::string& path, const char* mode) {
        fp_ = std::fopen(path.c_str(), mode);
        if (!fp_) {
            throw std::runtime_error("cannot open: " + path);
        }
    }

    ~FileHandle() {
        if (fp_) std::fclose(fp_);
    }

    // Non-copyable: two owners must not both close the same handle.
    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fp_(other.fp_) {
        other.fp_ = nullptr;
    }

    std::FILE* get() const { return fp_; }

private:
    std::FILE* fp_ = nullptr;
};

int main() {
    FileHandle f("out.txt", "w");
    std::fputs("hello\n", f.get());
    return 0;
} // destructor runs here, closing the file
```

