bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;

    long value = 0;
    int sign = 1;
    if (*s == '+' || *s == '-') {
        if (*s == '-') sign = -1;
        s++;
    }
    if (*s == '\0') return false;

    for (; *s != '\0'; s++) {
        if (*s < '0' || *s > '9') return false;
        value = value * 10 + (*s - '0');
        if (value > (long)INT_MAX + 1) return false;
    }

    value *= sign;
    if (value < INT_MIN || value > INT_MAX) return false;
    *out = (int)value;
    return true;
}

