#include <string>

template <typename T>
const T& max3(const T& a, const T& b, const T& c) {
    const T& m = (a < b) ? b : a;
    return (m < c) ? c : m;
}

// Overload that accepts an explicit comparator.
template <typename T, typename Cmp>
const T& max3(const T& a, const T& b, const T& c, Cmp less) {
    const T& m = less(a, b) ? b : a;
    return less(m, c) ? c : m;
}

int main() {
    std::cout << max3(3, 7, 5) << "\n";                 // 7
    std::cout << max3(std::string("ant"),
                      std::string("bee"),
                      std::string("cow")) << "\n";       // cow
    std::cout << max3(3, 7, 5, [](int x, int y){ return x > y; }) << "\n"; // 3
    return 0;
}
