        if (!seen[c]) {
            seen[c] = true;
            s[write++] = s[read];
        }
    }
    s[write] = '\0';
}

int main(void) {
    char buf[64] = "programming";
    printf("before: %s\n", buf);
    dedupe(buf);
    printf("after:  %s\n", buf);
    return 0;
}
