/// Split `data` into `(&data[..at], &data[at..])`.
/// Returns `Err` when `at > data.len()` rather than panicking.
pub fn split_at_checked<T>(data: &[T], at: usize) -> Result<(&[T], &[T]), SplitError> {
    if at > data.len() {
        return Err(SplitError::OutOfRange { index: at, len: data.len() });
    }
    Ok(data.split_at(at))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn splits_inside() {
        let v = [1, 2, 3, 4];
        assert_eq!(split_at_checked(&v, 2), Ok((&v[..2], &v[2..])));
    }

    #[test]
    fn splits_at_ends() {
        let v = [1, 2, 3];
        assert_eq!(split_at_checked(&v, 0), Ok((&v[..0], &v[..])));
        assert_eq!(split_at_checked(&v, 3), Ok((&v[..], &v[3..])));
    }

    #[test]
    fn rejects_out_of_range() {
        let v = [1, 2, 3];
        assert_eq!(
            split_at_checked(&v, 4),
            Err(SplitError::OutOfRange { index: 4, len: 3 })
        );
    }

    #[test]
    fn empty_slice_is_ok() {
        let v: [u8; 0] = [];
        assert_eq!(split_at_checked(&v, 0), Ok((&v[..], &v[..])));
    }
}
