#include <stdio.h>
#include <stdlib.h>

struct node {
    int value;
    struct node *next;
};

/* Reverse the list in place and return the new head. */
struct node *reverse(struct node *head)
{
    struct node *prev = NULL;
    struct node *curr = head;
    while (curr != NULL) {
        struct node *next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

static void print_list(const struct node *head)
{
    for (; head != NULL; head = head->next) {
        printf("%d", head->value);
        if (head->next != NULL)
            printf(" -> ");
    }
    printf("\n");
}

static void free_list(struct node *head)
{
    while (head != NULL) {
        struct node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void)
{
    struct node *head = NULL;
    /* Build 1 -> 2 -> 3 -> 4 by pushing at the front. */
    for (int i = 4; i >= 1; --i) {
        struct node *n = malloc(sizeof *n);
        if (n == NULL)
            return 1;
        n->value = i;
        n->next = head;
        head = n;
    }

    printf("before: ");
    print_list(head);

    head = reverse(head);

    printf("after:  ");
    print_list(head);

    free_list(head);
    return 0;
}
```
Handles the empty list (`head == NULL`) naturally: `reverse` returns `NULL` and both prints show an empty line.

```cpp
#include <array>
#include <cstddef>
#include <cassert>
#include <iostream>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double value) {
        if (count_ == N) {
            return false;  // full: refuse rather than silently overwrite
        }
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    bool pop() {
        if (count_ == 0) {
            return false;
        }
        head_ = (head_ + 1) % N;
        --count_;
        return true;
    }

    // Oldest element, or throws when empty via the assert contract below.
    double front() const {
        assert(count_ > 0 && "front() on empty ring buffer");
        return data_[head_];
    }

    std::size_t size() const { return count_; }
    static constexpr std::size_t capacity() { return N; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<3> rb;
    assert(rb.empty());
    assert(rb.push(1.5) && rb.push(2.5) && rb.push(3.5));
    assert(rb.full());
    assert(!rb.push(4.0));          // rejected while full
    assert(rb.front() == 1.5);
    assert(rb.pop());
    assert(rb.front() == 2.5);      // oldest advanced after pop
    assert(rb.push(4.0));           // room again
    assert(rb.size() == 3);
    std::cout << "ok\n";
}
```
`N` must be at least 1; zero size would make the modulo undefined, so guard it at the call site or add a `static_assert(N > 0)`.

