    for path in &args {
        match counts(path) {
            Ok((l, w, b)) => println!("{:>7} {:>7} {:>7} {}", l, w, b, path),
            Err(err) => {
                eprintln!("rwc: {}: {}", path, err);
                status = 1;
            }
        }
    }
    process::exit(status);
