def flatten(value):
    """Flatten arbitrarily nested lists, tuples and sets into one list."""
    out = []
    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, (list, tuple)):
            stack.extend(reversed(item))
        elif isinstance(item, (set, frozenset)):
            stack.extend(sorted(item, key=repr))
        else:
            out.append(item)
    return out

if __name__ == "__main__":
    print(flatten([1, [2, (3, 4)], {5, 6}, []]))  # 1 2 3 4 5 6 (set order fixed by key)
    print(flatten([]))                            # []
    print(flatten(("a", ["b"])))                 # ['a', 'b']
```
The explicit `stack` avoids recursion limits on deep input; sets are sorted by a stable key so output is deterministic even though sets themselves are unordered.

```python
def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring of s.

    Expands around each of the 2n-1 centers in O(n^2) time, O(1) space.
    Empty input returns the empty string.
    """
    if not s:
        return ""

    start, end = 0, 0

    def expand(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)          # odd length
        l2, r2 = expand(i, i + 1)      # even length
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["", "a", "babad", "cbbd", "abacaba", ""]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
