```python
import threading
import time
import random


class BoundedQueue:
    """A thread-safe queue with a fixed maximum size.

    put() blocks while full, get() blocks while empty. A closed queue
    drains remaining items and then raises on put/get.
    """

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._items = []
        self._lock = threading.Lock()
        self._not_full = threading.Condition(self._lock)
        self._not_empty = threading.Condition(self._lock)
        self._closed = False

    def put(self, item) -> None:
        with self._not_full:
            while len(self._items) == self.capacity and not self._closed:
                self._not_full.wait()
            if self._closed:
                raise RuntimeError("queue is closed")
            self._items.append(item)
            self._not_empty.notify()

    def get(self):
        with self._not_empty:
            while not self._items and not self._closed:
                self._not_empty.wait()
            if self._items:
                item = self._items.pop(0)
                self._not_full.notify()
                return item
            raise RuntimeError("queue is closed")

    def close(self) -> None:
        with self._lock:
            self._closed = True
            self._not_full.notify_all()
            self._not_empty.notify_all()


if __name__ == "__main__":
    q = BoundedQueue(3)
    consumed = []
    lock = threading.Lock()

    def producer(pid):
        for i in range(5):
            q.put((pid, i))
            time.sleep(random.uniform(0, 0.01))

    def consumer():
        while True:
            try:
                item = q.get()
            except RuntimeError:
                return
            with lock:
                consumed.append(item)

    threads = [threading.Thread(target=producer, args=(p,)) for p in range(3)]
    consumers = [threading.Thread(target=consumer) for _ in range(2)]
    for t in consumers:
        t.start()
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    q.close()
    for t in consumers:
        t.join()
    print("consumed", len(consumed), "unique", len(set(consumed)))
    assert len(consumed) == 15 and len(set(consumed)) == 15
