template <std::size_t BlockSize, std::size_t BlockCount>
class Pool {
    static_assert(BlockSize >= sizeof(void*), "block must hold a free-list pointer");

public:
    void* allocate() {
        if (free_list_ == nullptr) return nullptr;
        void* p = free_list_;
        free_list_ = *static_cast<void**>(p);
        return p;
    }

    void deallocate(void* p) {
        if (p == nullptr) return;
        *static_cast<void**>(p) = free_list_;
        free_list_ = p;
    }

    std::size_t used() const { return BlockCount - free_count(); }
    std::size_t free_count() const {
        std::size_t n = 0;
        for (void* p = free_list_; p; p = *static_cast<void**>(p)) ++n;
        return n;
    }

private:
    struct alignas(std::max_align_t) Slot { unsigned char bytes[BlockSize]; };
    Slot storage_[BlockCount];
    void* free_list_ = nullptr;
    bool constructed_ = false;

public:
    Pool() {
        for (std::size_t i = 0; i < BlockCount; ++i) {
            void* p = storage_[i].bytes;
            *static_cast<void**>(p) = free_list_;
            free_list_ = p;
        }
        constructed_ = true;
    }
};

int main() {
    Pool<32, 4> pool;
    assert(pool.free_count() == 4);
    void* a = pool.allocate();
    void* b = pool.allocate();
    assert(a && b && a != b);
    assert(pool.used() == 2);
    pool.deallocate(a);
    assert(pool.used() == 1);
    void* c = pool.allocate();
    assert(c == a);  // freed block reused
    std::cout << "pool OK, used=" << pool.used() << "\n";
}
