use std::num::ParseIntError;

/// Parse a comma-separated list of integers.
///
/// Whitespace around each field is trimmed and empty fields are skipped.
/// Returns the position (1-based) of the first field that fails to parse,
/// together with the underlying error.
#[derive(Debug)]
pub struct ParseListError {
    pub index: usize,
    pub source: ParseIntError,
}

impl std::fmt::Display for ParseListError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "field {}: {}", self.index, self.source)
    }
}

impl std::error::Error for ParseListError {}

pub fn parse_list(input: &str) -> Result<Vec<i64>, ParseListError> {
    let mut out = Vec::new();
    for (i, field) in input.split(',').enumerate() {
        let trimmed = field.trim();
        if trimmed.is_empty() {
            continue;
        }
        match trimmed.parse::<i64>() {
            Ok(v) => out.push(v),
            Err(source) => return Err(ParseListError { index: i + 1, source }),
        }
    }
    Ok(out)
}

fn main() {
    assert_eq!(parse_list("1, 2 ,3").unwrap(), vec![1, 2, 3]);
    assert_eq!(parse_list(" , 7,,8 ").unwrap(), vec![7, 8]);
    assert_eq!(parse_list("").unwrap(), Vec::<i64>::new());
    assert_eq!(parse_list("-5,10").unwrap(), vec![-5, 10]);

    let err = parse_list("1, two, 3").unwrap_err();
    assert_eq!(err.index, 2);
    println!("parsed ok; error case reports field {}", err.index);
}
