/// Binary search over a sorted slice.
///
/// Returns `Ok(index)` if `target` is found, or `Err(insert_index)`
/// giving the position where `target` would need to be inserted to keep
/// the slice sorted. Lower-bound semantics for duplicates.
pub fn search<T: Ord>(slice: &[T], target: &T) -> Result<usize, usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Ok(mid),
        }
    }
    Err(lo)
}

fn main() {
    let data = [1, 3, 5, 7, 9, 11];
    assert_eq!(search(&data, &1), Ok(0));
    assert_eq!(search(&data, &9), Ok(4));
    assert_eq!(search(&data, &0), Err(0));
    assert_eq!(search(&data, &6), Err(3));
    assert_eq!(search(&data, &12), Err(6));

    let empty: [i32; 0] = [];
    assert_eq!(search(&empty, &42), Err(0));

    // Cross-check the insertion point against a stable sort.
    for t in -2..14 {
        let expected = data.iter().filter(|&&x| x < t).count();
        match search(&data, &t) {
            Ok(_) => assert!(data.contains(&t)),
            Err(pos) => assert_eq!(pos, expected),
        }
    }
    println!("binary search OK");
}
