```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <assert.h>

typedef struct {
    char *key;      /* NULL marks an empty slot */
    int value;
    int used;
} Entry;

typedef struct {
    Entry *slots;
    size_t cap;
    size_t count;   /* number of occupied slots */
} Table;

static uint64_t hash_str(const char *s) {
    uint64_t h = 1469598103934665603ULL;  /* FNV-1a */
    for (; *s; ++s) {
        h ^= (unsigned char)*s;
        h *= 1099511628211ULL;
    }
    return h;
}

static void table_init(Table *t, size_t cap) {
    t->cap = cap;
    t->count = 0;
    t->slots = calloc(cap, sizeof(Entry));
    if (!t->slots) { perror("calloc"); exit(1); }
}

static void table_free(Table *t) {
    for (size_t i = 0; i < t->cap; ++i) free(t->slots[i].key);
    free(t->slots);
    t->slots = NULL;
    t->cap = t->count = 0;
}

static void table_put(Table *t, const char *key, int value);

static void table_grow(Table *t) {
    Entry *old = t->slots;
    size_t old_cap = t->cap;
    table_init(t, old_cap * 2);
    for (size_t i = 0; i < old_cap; ++i) {
        if (old[i].key) table_put(t, old[i].key, old[i].value);
        free(old[i].key);
    }
    free(old);
}

static void table_put(Table *t, const char *key, int value) {
    if ((double)(t->count + 1) / (double)t->cap > 0.7) table_grow(t);
    size_t i = hash_str(key) % t->cap;
    while (t->slots[i].key) {
        if (strcmp(t->slots[i].key, key) == 0) {
            t->slots[i].value = value;
            return;
        }
        i = (i + 1) % t->cap;
    }
    t->slots[i].key = strdup(key);
    if (!t->slots[i].key) { perror("strdup"); exit(1); }
    t->slots[i].value = value;
    t->slots[i].used = 1;
    t->count++;
}

static int *table_get(Table *t, const char *key) {
    size_t i = hash_str(key) % t->cap;
    while (t->slots[i].key) {
        if (strcmp(t->slots[i].key, key) == 0) return &t->slots[i].value;
        i = (i + 1) % t->cap;
    }
    return NULL;
}

int main(void) {
    Table t;
    table_init(&t, 4);
    for (int i = 0; i < 1000; ++i) {
        char buf[32];
        snprintf(buf, sizeof buf, "key-%d", i);
        table_put(&t, buf, i * 2);
    }
    assert(t.count == 1000);
    assert(table_get(&t, "key-500") && *table_get(&t, "key-500") == 1000);
    assert(table_get(&t, "key-999") && *table_get(&t, "key-999") == 1998);
    assert(table_get(&t, "missing") == NULL);
    table_put(&t, "key-1", 7);
    assert(*table_get(&t, "key-1") == 7);
    table_free(&t);
    printf("hash table OK\n");
    return 0;
}
