import csv
import io


def group_totals(text: str, amount_col: str, group_col: str) -> dict[str, float]:
    """Sum amount_col grouped by group_col.

    Rows with a missing field or a non-numeric amount are skipped and
    reported on stderr so the caller still gets the valid totals.
    """
    reader = csv.DictReader(io.StringIO(text))
    if reader.fieldnames is None:
        return {}
    if amount_col not in reader.fieldnames or group_col not in reader.fieldnames:
        raise KeyError(f"need columns {group_col!r} and {amount_col!r}")

    totals: dict[str, float] = {}
    bad = 0
    for lineno, row in enumerate(reader, start=2):
        try:
            amount = float(row[amount_col])
        except (TypeError, ValueError, KeyError):
            print(f"line {lineno}: skipping bad amount {row.get(amount_col)!r}")
            bad += 1
            continue
        group = (row.get(group_col) or "unknown").strip() or "unknown"
        totals[group] = totals.get(group, 0.0) + amount

    if bad:
        print(f"skipped {bad} bad row(s)")
    return totals


if __name__ == "__main__":
    data = "group,amount\nA,3.5\nB,2\nA,oops\nC,\nB,4.25\nA,1.5\n"
    print(group_totals(data, "amount", "group"))
    # {'A': 5.0, 'B': 6.25, 'C': 0.0}
