#include <cctype>
#include <iostream>
#include <string>

bool isPalindrome(const std::string& s) {
    std::size_t i = 0, j = s.size();
    while (i < j) {
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[i]))) ++i;
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[j - 1]))) --j;
        if (i < j) {
            char a = static_cast<char>(std::tolower(static_cast<unsigned char>(s[i])));
            char b = static_cast<char>(std::tolower(static_cast<unsigned char>(s[j - 1])));
            if (a != b) return false;
            ++i;
            --j;
        }
    }
    return true;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << isPalindrome("A man, a plan, a canal: Panama") << '\n'; // true
    std::cout << isPalindrome("race a car") << '\n';                     // false
    std::cout << isPalindrome("") << '\n';                               // true
    std::cout << isPalindrome(".,.") << '\n';                            // true
    return 0;
}
