fn rle_encode(input: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        let mut run = 1;
        while i + run < chars.len() && chars[i + run] == c {
            run += 1;
        }
        if run >= 2 {
            out.push_str(&format!("{}{}", c, run));
        } else {
            out.push(c);
        }
        i += run;
    }
    out
}

