struct BoundedStack<T> {
    data: Vec<T>,
    cap: usize,
}

impl<T> BoundedStack<T> {
    fn new(cap: usize) -> Self {
        BoundedStack { data: Vec::new(), cap }
    }
    fn push(&mut self, value: T) -> bool {
        if self.data.len() >= self.cap {
            return false;
        }
        self.data.push(value);
        true
    }
    fn pop(&mut self) -> Option<T> {
        self.data.pop()
    }
    fn len(&self) -> usize {
        self.data.len()
    }
}

