    assert!(s.push(1));
    assert!(s.push(2));
    assert!(!s.push(3)); // full, rejected
    assert_eq!(s.pop(), Some(2));
    assert_eq!(s.pop(), Some(1));
    assert_eq!(s.pop(), None); // empty
    assert_eq!(s.len(), 0);
    println!("ok");
}
