```cpp
#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (full()) {
            return false;
        }
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) {
            return std::nullopt;
        }
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) {
        throw std::runtime_error("push failed");
    }
    if (rb.push(4)) {
        throw std::runtime_error("should be full");
    }
    if (rb.pop() != 1 || rb.size() != 2) {
        throw std::runtime_error("pop mismatch");
    }
    return 0;
}
```

Capacity is a template parameter and the buffer is a plain `std::array`, so no heap allocation happens. `push` returns `false` when full and `pop` returns `std::nullopt` when empty, which keeps both operations total.

