#include <stack>
#include <string>
#include <unordered_map>

bool is_balanced(const std::string& s) {
    static const std::unordered_map<char, char> kPairs = {
        {')', '('}, {']', '['}, {'}', '{'},
    };

    std::stack<char> open;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            open.push(c);
        } else {
            auto it = kPairs.find(c);
            if (it == kPairs.end()) {
                continue;  // ignore other characters
            }
            if (open.empty() || open.top() != it->second) {
                return false;
            }
            open.pop();
        }
    }
    return open.empty();
}
```

Each opening bracket is pushed; each closing bracket must match the most recent unmatched opener. Non-bracket characters are ignored. The final `open.empty()` check catches unclosed openers such as `"(["`.

