```rust
fn encode(input: &str) -> String {
    let mut out = String::new();
    let mut chars = input.chars().peekable();
    while let Some(c) = chars.next() {
        let mut count = 1;
        while chars.peek() == Some(&c) {
            chars.next();
            count += 1;
        }
        out.push(c);
        out.push_str(&count.to_string());
    }
    out
}

fn decode(input: &str) -> String {
    let mut out = String::new();
    let mut count = String::new();
    for c in input.chars() {
        if c.is_ascii_digit() {
            count.push(c);
        } else {
            if !count.is_empty() {
                let n: usize = count.parse().unwrap_or(1);
                if let Some(last) = out.chars().last() {
                    for _ in 0..n {
                        out.push(last);
                    }
                }
                count.clear();
            }
            out.push(c);
        }
    }
    out
}

fn main() {
    let cases = ["", "a", "aabbb", "abcd", "aaab"];
    for s in cases {
        let e = encode(s);
        assert_eq!(decode(&e), s);
        println!("{:?} -> {:?} -> {:?}", s, e, decode(&e));
    }
}
```

The tests round-trip every case, including the empty string, so the encoder and decoder agree on the same format.

