static void rotate_left(int *a, int n, int k) {
    if (n <= 0) return;
    k %= n;
    if (k < 0) k += n;
    if (k == 0) return;
    reverse(a, 0, k - 1);
    reverse(a, k, n - 1);
    reverse(a, 0, n - 1);
}

