def is_valid_utf8(data):
    i = 0
    n = len(data)
    while i < n:
        b = data[i]
        if b < 0x80:
            i += 1
            continue
        if 0xC2 <= b <= 0xDF:
            length = 1
            low, high = 0x80, 0xBF
        elif 0xE0 <= b <= 0xEF:
            length = 2
            low, high = (0xA0, 0xBF) if b == 0xE0 else (0x80, 0xBF)
        elif 0xF0 <= b <= 0xF4:
            length = 3
            low, high = (0x90, 0xBF) if b == 0xF0 else (0x80, 0x8F) if b == 0xF4 else (0x80, 0xBF)
        else:
            return False
        if i + length >= n + 1 and i + length > n:
            return False
        for j in range(1, length + 1):
            if i + j >= n:
                return False
            extra = data[i + j]
            if j == 1:
                if not (low <= extra <= high):
                    return False
            elif not (0x80 <= extra <= 0xBF):
                return False
        i += length + 1
    return True


if __name__ == "__main__":
    assert is_valid_utf8(b"hello")
    assert is_valid_utf8("caf\u00e9".encode("utf-8"))
    assert is_valid_utf8(b"")
    assert not is_valid_utf8(b"\xc0\x80")
    assert not is_valid_utf8(b"\xe0\x80\x80")
    assert not is_valid_utf8(b"\xf5\x80\x80\x80")
    assert not is_valid_utf8("x".encode("utf-8") + b"\x80")
    print("ok")
```

It tracks the lead byte, the minimum/maximum allowed for the first continuation byte (which rules out overlong forms), and rejects stray continuation bytes and truncated sequences.

