```cpp
#include <array>
#include <cstddef>
#include <cassert>
#include <iostream>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), count_(0) {
        assert(capacity > 0);
    }

    bool push(int value) {
        if (count_ == buf_.size()) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % buf_.size();
        ++count_;
        return true;
    }

    bool pop(int& out) {
        if (count_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }

private:
    std::vector<int> buf_;
    std::size_t head_, tail_, count_;
};

int main() {
    RingBuffer rb(3);
    assert(rb.size() == 0);
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(!rb.push(4));                 // full
    assert(rb.size() == 3);
    int v = 0;
    assert(rb.pop(v) && v == 1);
    assert(rb.push(4));                 // wraps around
    assert(rb.pop(v) && v == 2);
    assert(rb.pop(v) && v == 3);
    assert(rb.pop(v) && v == 4);
    assert(!rb.pop(v));                 // empty
    std::cout << "ok\n";
}
```

I used `std::vector` rather than `std::array` so the capacity comes from the constructor; include `<vector>` alongside `<array>` if you keep the array version. `head_`, `tail_`, `count_` are the only state — an empty and a full buffer are distinguished by `count_`, not by pointer equality.

```c
#include <stdio.h>
#include <string.h>
#include <assert.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t i = 0;
    size_t j = strlen(s);
    while (i < j && j > 0) {
        --j;
        if (i >= j) break;
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    assert(strcmp(a, "olleh") == 0);

    char b[] = "";
    reverse_in_place(b);
    assert(strcmp(b, "") == 0);

    char c[] = "x";
    reverse_in_place(c);
    assert(strcmp(c, "x") == 0);

    char d[] = "ab";
    reverse_in_place(d);
    assert(strcmp(d, "ba") == 0);

    reverse_in_place(NULL);  /* must not crash */

    char e[] = "a\x01b";
    reverse_in_place(e);
    assert(e[0] == 'b' && e[1] == 1 && e[2] == 'a');

    printf("ok\n");
    return 0;
}
```

The swap walks inward with `i` rising and `j` falling, and stops before the two cross, so an odd-length string leaves its middle byte untouched. `strlen` is O(n) but the reverse itself touches each byte once. Passing the literals through `char[]` (not `char*`) keeps them writable.

```rust
use std::collections::{HashMap, VecDeque};

pub struct LruCache<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: Clone + Eq + std::hash::Hash, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        Self { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        if !self.map.contains_key(key) {
            return None;
        }
        self.touch(key);
        self.map.get(key)
    }

    pub fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            self.map.insert(key.clone(), value);
            self.touch(&key);
            return;
        }
        if self.map.len() == self.cap {
            if let Some(old) = self.order.pop_back() {
                self.map.remove(&old);
            }
        }
        self.order.push_front(key.clone());
        self.map.insert(key, value);
    }

    fn touch(&mut self, key: &K) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            self.order.remove(pos);
            self.order.push_front(key.clone());
        }
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put("a", 1);
    c.put("b", 2);
    assert_eq!(c.get(&"a"), Some(&1));
    c.put("c", 3);            // evicts "b"
    assert_eq!(c.get(&"b"), None);
    assert_eq!(c.get(&"a"), Some(&1));
    c.put("a", 10);
    assert_eq!(c.get(&"a"), Some(&10));
    println!("ok");
}
```

The deque holds keys front = most recently used, back = least recently used. `get` promotes its key to the front, which is what makes eviction order correct. This is O(n) on `touch` because of the linear `position` scan; swap in a `HashMap<K, usize>` of positions if you need O(1), at the cost of more bookkeeping.

