#include <chrono>
#include <cmath>
#include <cstdint>
#include <iostream>

bool is_prime(std::uint64_t n) {
    if (n < 2) return false;
    if (n < 4) return true;            // 2, 3
    if (n % 2 == 0) return false;
    if (n % 3 == 0) return n == 3;
    for (std::uint64_t d = 5; d * d <= n; d += 6) {
        if (n % d == 0 || n % (d + 2) == 0) return false;
    }
    return true;
}

int main() {
    // correctness spot checks
    const std::uint64_t primes[] = {2, 3, 5, 7, 11, 13, 97, 7919, 104729};
    const std::uint64_t composites[] = {0, 1, 4, 9, 15, 100, 7917, 104730};
    for (auto p : primes)      if (!is_prime(p)) { std::cerr << "missed prime " << p << '\n'; return 1; }
    for (auto c : composites)  if (is_prime(c))  { std::cerr << "wrong composite " << c << '\n'; return 1; }

    auto t0 = std::chrono::steady_clock::now();
    int count = 0;
    for (std::uint64_t n = 2; n < 200000; ++n) count += is_prime(n);
    auto t1 = std::chrono::steady_clock::now();

    std::uint64_t n = 2147483647ULL;   // Mersenne prime 2^31 - 1
    std::cout << "primes < 200000: " << count
              << ", 2147483647 prime: " << is_prime(n)
              << ", elapsed ms: "
              << std::chrono::duration_cast<std::chrono::milliseconds>(t1 - t0).count()
              << '\n';
}
```

`d += 6` steps over the two residues coprime to 6, so it runs at a third of the naive loop's iterations. `d * d <= n` stops at √n; for large inputs watch for overflow on `d * d`, which for `uint64_t` is safe up to about 4.3e9 before it wraps. Trial division is fine up to ~10^12; beyond that you want Miller–Rabin.

