#include <cstdlib>
#include <iostream>
#include <limits>

// Euclidean algorithm. Uses unsigned magnitude so that the most
// negative int (where -x overflows) cannot bite us.
int gcd(int a, int b) {
    using U = unsigned int;
    U x = static_cast<U>(a < 0 ? -(static_cast<long long>(a)) : a);
    U y = static_cast<U>(b < 0 ? -(static_cast<long long>(b)) : b);

    while (y != 0) {
        U t = x % y;
        x = y;
        y = t;
    }
    return static_cast<int>(x);
}

int main() {
    std::cout << gcd(48, 18) << '\n';   // 6
    std::cout << gcd(0, 5) << '\n';     // 5
    std::cout << gcd(0, 0) << '\n';     // 0 by convention
    std::cout << gcd(-24, 18) << '\n';  // 6
    return 0;
}
```
