#include <optional>
#include <string>
#include <string_view>
#include <cstddef>

std::optional<int> parse_int(std::string_view text) {
    if (text.empty()) {
        return std::nullopt;
    }

    std::size_t index = 0;
    bool negative = false;
    if (text[0] == '+' || text[0] == '-') {
        negative = (text[0] == '-');
        index = 1;
    }
    if (index == text.size()) {
        return std::nullopt;
    }

    long long value = 0;
    for (; index < text.size(); ++index) {
        char ch = text[index];
        if (ch < '0' || ch > '9') {
            return std::nullopt;
        }
        value = value * 10 + (ch - '0');
        if (value > 2147483648LL) {
            return std::nullopt;
        }
    }

    if (negative) {
        value = -value;
        if (value < -2147483648LL) {
            return std::nullopt;
        }
    } else if (value > 2147483647LL) {
        return std::nullopt;
    }

    return static_cast<int>(value);
}
```

The `optional` return makes every failure path explicit, so callers decide what to do instead of catching an exception. Parsing accumulates into `long long` and checks the int32 bounds before casting, which rejects `"9999999999999"` rather than silently wrapping. An empty string, a lone sign, and any non-digit character all yield `nullopt`.

