pub fn parse_semver(s: &str) -> Result<(u32, u32, u32), SemverError> {
    let mut parts = s.split('.');
    let major = parts.next().ok_or(SemverError::MissingPart)?;
    let minor = parts.next().ok_or(SemverError::MissingPart)?;
