 * reverses byte order, which is only correct for single-byte text. */
void reverse_bytes(char *s) {
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; ++i) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
}

