```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) return std::nullopt;
        double value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    if (!rb.push(1.5) || !rb.push(2.5) || !rb.push(3.5)) return 1;
    if (rb.push(4.5)) return 1;          // over capacity must fail
    if (rb.pop() != 2.5) return 1;       // FIFO order
    if (!rb.push(4.5)) return 1;         // slot is free again
    std::cout << "size=" << rb.size() << "\n";
    while (auto v = rb.pop()) std::cout << "popped " << *v << "\n";
    if (!rb.empty()) return 1;
    std::cout << "all tests passed\n";
}
```

`head_` plus `size_` models the occupied window, so `(head_ + size_) % N` is the write slot and `(head_ + 1) % N` advances the read point with wraparound. Both mutators return a status (`bool` / `std::optional`) instead of assuming success, so an over-capacity push and an empty pop are handled rather than undefined.

