```c
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) return;      /* empty string: nothing to do */
    right -= 1;                  /* index of the last character */
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char a[] = "hello";
    char b[] = "a";
    char c[] = "";
    char d[] = "ab";
    reverse_in_place(a);
    reverse_in_place(b);
    reverse_in_place(c);
    reverse_in_place(d);
    if (strcmp(a, "olleh") != 0) return 1;
    if (strcmp(b, "a") != 0) return 1;
    if (strcmp(c, "") != 0) return 1;
    if (strcmp(d, "ba") != 0) return 1;
    puts("all tests passed");
    return 0;
}
```

The `right -= 1` step must happen only after the empty-string guard, otherwise `right` would wrap to `SIZE_MAX` and the loop would run off the buffer. The `left < right` condition stops at the middle for both odd and even lengths, so the single test string `"a"` swaps nothing and `"ab"` swaps exactly once. All test buffers are mutable arrays, since a string literal lives in read-only memory.

