        head_ = (head_ + 1) % N;
        if (size_ < N) {
            ++size_;
        }
    }

    std::size_t size() const { return size_; }

    T& operator[](std::size_t i) {
        if (i >= size_) throw std::out_of_range("index");
        const std::size_t start = (head_ + N - size_) % N;
        return data_[(start + i) % N];
    }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int v : {1, 2, 3, 4, 5}) rb.push(v);
    for (std::size_t i = 0; i < rb.size(); ++i) std::cout << rb[i] << ' ';
    std::cout << '\n'; // 3 4 5
}
```

Once full, each `push` overwrites the oldest slot and advances `head_`. `operator[]` recomputes the logical start as `(head_ + N - size_) % N`, so iteration yields insertion order — here the last three values `3 4 5`. The bounds check throws rather than reading past `size_`.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict[str, int] = OrderedDict()

    def get(self, key: str) -> int | None:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: str, value: int) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1      # 'a' is now most-recent
    cache.put("c", 3)               # evicts 'b'
    assert cache.get("b") is None
    assert cache.get("c") == 3
    print("ok")
```

`OrderedDict` preserves recency order: both `get` and updates call `move_to_end`. On overflow `popitem(last=False)` drops the least-recently-used front entry, so inserting `c` evicts `b` because `a` was just refreshed.

