```cpp
#include <iostream>
#include <string>

std::string to_binary(unsigned long long n) {
    if (n == 0) {
        return "0";
    }
    std::string bits;
    while (n > 0) {
        bits.push_back('0' + static_cast<char>(n & 1ULL));
        n >>= 1ULL;
    }
    std::string reversed(bits.rbegin(), bits.rend());
    return reversed;
}

unsigned long long from_binary(const std::string& bits) {
    unsigned long long value = 0;
    for (char c : bits) {
        if (c != '0' && c != '1') {
            throw std::invalid_argument("non-binary digit");
        }
        value = (value << 1ULL) | static_cast<unsigned long long>(c - '0');
    }
    return value;
}

int main() {
    unsigned long long samples[] = {0ULL, 1ULL, 2ULL, 255ULL, 1024ULL, 123456789ULL};
    for (unsigned long long n : samples) {
        std::string bits = to_binary(n);
        unsigned long long back = from_binary(bits);
        std::cout << n << " -> " << bits << " -> " << back
                  << (back == n ? " ok" : " MISMATCH") << '\n';
    }
    return 0;
}
```

`n & 1` extracts the low bit and `n >>= 1` shifts it out, so bits come out least-significant first and are reversed at the end. The unsigned type avoids undefined behaviour on the shift for large inputs. `from_binary` replays the encoding in reverse and `main` checks that the round trip is lossless for every sample.

