int main() {
    // max-heap holds the lower half, min-heap the upper half.
    std::priority_queue<long long> low;                              // max-heap
    std::priority_queue<long long, std::vector<long long>,
                        std::greater<long long>> high;              // min-heap

    long long x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) {
            low.push(x);
        } else {
            high.push(x);
        }

        // Rebalance so sizes differ by at most one, low never smaller than high.
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        double median = low.size() == high.size()
            ? (low.top() + high.top()) / 2.0
            : static_cast<double>(low.top());
        std::cout << std::fixed << std::setprecision(1) << median << '\n';
    }
