```rust
use std::collections::HashMap;

/// Return the `k` most frequent words in `text`, case-insensitive, ignoring
/// punctuation. Ties are broken alphabetically for a stable result.
pub fn top_k_words(text: &str, k: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();

    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count desc, then word asc.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(k);
    pairs
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        let text = "The cat, the CAT! A dog.";
        assert_eq!(
            top_k_words(text, 2),
            vec![("the".to_string(), 3), ("cat".to_string(), 2)]
        );
    }

    #[test]
    fn empty_and_unicode() {
        assert!(top_k_words("", 5).is_empty());
        assert_eq!(top_k_words("Caf\u{e9} caf\u{e9}", 1), vec![("caf\u{e9}".to_string(), 2)]);
    }

    #[test]
    fn k_larger_than_vocab() {
        assert_eq!(top_k_words("a b", 10).len(), 2);
    }
}
```
`split_whitespace` handles multiple spaces; `to_lowercase` on chars covers Unicode case folding. Tie-break on the word keeps output deterministic.

```c
#include <stddef.h>
#include <stdio.h>

static void reverse(int *a, size_t lo, size_t hi) {
    /* Reverse a[lo..hi] inclusive. */
    while (lo < hi) {
        int t = a[lo];
        a[lo] = a[hi];
        a[hi] = t;
        lo++;
        hi--;
    }
}

/* Rotate a[0..n-1] right by k positions, in place. O(n) time, O(1) space. */
void rotate_right(int *a, size_t n, long k) {
    if (n == 0) {
        return;
    }
    k %= (long)n;
    if (k < 0) {
        k += (long)n;
    }
    if (k == 0) {
        return;
    }
    size_t s = (size_t)k;
    reverse(a, 0, n - 1);
    reverse(a, 0, s - 1);
    reverse(a, s, n - 1);
}

int main(void) {
    int a[] = {1, 2, 3, 4, 5, 6, 7};
    size_t n = sizeof a / sizeof a[0];
    rotate_right(a, n, 3);
    for (size_t i = 0; i < n; i++) {
        printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');
    }
    /* {5 6 7 1 2 3 4} */
    return 0;
}
```
`k %= n` normalizes overshoot; negative `k` is folded into the positive range. Empty arrays return immediately before any modulo by zero.

