import ipaddress


def is_valid_ipv4(address: str) -> bool:
    """True if `address` is a syntactically valid IPv4 address.

    Rejects leading zeros (e.g. "192.168.001.1"), out-of-range octets,
    wrong part counts, and non-string input.
    """
    if not isinstance(address, str):
        return False
    parts = address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit() or len(part) > 3:
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False
    try:
        ipaddress.IPv4Address(address)
    except ipaddress.AddressValueError:
        return False
    return True


if __name__ == "__main__":
    good = ["0.0.0.0", "127.0.0.1", "255.255.255.255", "192.168.1.1"]
    bad = ["", "256.1.1.1", "192.168.1", "192.168.1.1.1",
           "192.168.01.1", "a.b.c.d", "1.2.3.-4", " 1.2.3.4"]
    assert all(is_valid_ipv4(x) for x in good)
    assert not any(is_valid_ipv4(x) for x in bad)
    print("ok")
