```cpp
#include <iostream>
#include <string>
#include <vector>
#include <cassert>

// Manacher's algorithm: longest palindromic substring in O(n).
std::string longestPalindrome(const std::string& s) {
    if (s.empty()) return "";
    // Transform "abc" -> "#a#b#c#" so odd/even cases unify.
    std::string t = "#";
    for (char c : s) {
        t += c;
        t += '#';
    }
    const int n = static_cast<int>(t.size());
    std::vector<int> radius(n, 0);
    int center = 0, right = 0;
    int bestLen = 0, bestCenter = 0;
    for (int i = 0; i < n; ++i) {
        if (i < right) {
            radius[i] = std::min(right - i, radius[2 * center - i]);
        }
        int a = i - radius[i] - 1;
        int b = i + radius[i] + 1;
        while (a >= 0 && b < n && t[a] == t[b]) {
            --a;
            ++b;
            ++radius[i];
        }
        if (i + radius[i] > right) {
            center = i;
            right = i + radius[i];
        }
        if (radius[i] > bestLen) {
            bestLen = radius[i];
            bestCenter = i;
        }
    }
    int start = (bestCenter - bestLen) / 2;
    return s.substr(start, bestLen);
}

int main() {
    assert(longestPalindrome("babad") == "bab" || longestPalindrome("babad") == "aba");
    assert(longestPalindrome("cbbd") == "bb");
    assert(longestPalindrome("a") == "a");
    assert(longestPalindrome("") == "");
    assert(longestPalindrome("forgeeksskeegfor") == "geeksskeeg");
    struct { const char* in; const char* out; } cases[] = {
        {"racecar", "racecar"},
        {"abacaba", "abacaba"},
        {"aaaa", "aaaa"},
    };
    for (auto& c : cases) {
        std::string got = longestPalindrome(c.in);
        assert(got == c.out);
    }
    std::cout << "all tests passed\n";
    return 0;
}
```

`radius[i]` is the number of matching characters around center `i` in the transformed string. Mirroring against `2*center - i` reuses prior work while inside the current right boundary, giving linear time. The final `start` maps the transformed center back to original indices.

```rust
use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, BufRead};

struct MedianTracker {
    lower: BinaryHeap<i64>,          // max-heap of the smaller half
    upper: BinaryHeap<Reverse<i64>>, // min-heap of the larger half
}

impl MedianTracker {
    fn new() -> Self {
        MedianTracker { lower: BinaryHeap::new(), upper: BinaryHeap::new() }
    }

    fn insert(&mut self, x: i64) {
        if self.lower.peek().map_or(true, |&m| x <= m) {
            self.lower.push(x);
        } else {
            self.upper.push(Reverse(x));
        }
        // Rebalance so sizes differ by at most one, lower >= upper.
        if self.lower.len() > self.upper.len() + 1 {
            let v = self.lower.pop().unwrap();
            self.upper.push(Reverse(v));
        } else if self.upper.len() > self.lower.len() {
            let Reverse(v) = self.upper.pop().unwrap();
            self.lower.push(v);
        }
    }

    fn median(&self) -> f64 {
        if self.lower.len() > self.upper.len() {
            *self.lower.peek().unwrap() as f64
        } else {
            let a = *self.lower.peek().unwrap() as f64;
            let Reverse(b) = *self.upper.peek().unwrap();
            (a + b as f64) / 2.0
        }
    }
}

fn main() {
    let stdin = io::stdin();
    let mut tracker = MedianTracker::new();
    let mut count = 0usize;
    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(e) => {
                eprintln!("read error: {e}");
                break;
            }
        };
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        match trimmed.parse::<i64>() {
            Ok(v) => {
                tracker.insert(v);
                count += 1;
                println!("median after {count} value(s): {}", tracker.median());
            }
            Err(_) => eprintln!("skipping non-integer line: {trimmed:?}"),
        }
    }
    if count == 0 {
        println!("no numeric input");
    }
}
```

Two heaps keep the lower half as a max-heap and the upper half as a min-heap via `Reverse`. After each insert the rebalance step guarantees `lower.len() == upper.len()` or `lower.len() == upper.len() + 1`, so the median is either the top of `lower` or the average of both tops. Blank lines are ignored and unparsable lines are reported to stderr, so empty input produces `no numeric input`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define TABLE_SIZE 4096
#define MAX_WORD 128

typedef struct Entry {
    char *word;
    long count;
    struct Entry *next;
} Entry;

static Entry *table[TABLE_SIZE];

static unsigned long hash(const char *s) {
    unsigned long h = 5381;
    int c;
    while ((c = (unsigned char)*s++)) {
        h = ((h << 5) + h) + (unsigned long)c;
    }
    return h % TABLE_SIZE;
}

static Entry *lookup_or_add(const char *word, int *created) {
    unsigned long idx = hash(word);
    for (Entry *e = table[idx]; e; e = e->next) {
        if (strcmp(e->word, word) == 0) {
            *created = 0;
            return e;
        }
    }
    Entry *e = malloc(sizeof(Entry));
    if (!e) { perror("malloc"); exit(1); }
    e->word = strdup(word);
    if (!e->word) { perror("strdup"); exit(1); }
    e->count = 0;
    e->next = table[idx];
    table[idx] = e;
    *created = 1;
    return e;
}

static int compare(const void *a, const void *b) {
    const Entry *ea = *(const Entry *const *)a;
    const Entry *eb = *(const Entry *const *)b;
    if (ea->count != eb->count) {
        return ea->count < eb->count ? 1 : -1; // descending count
    }
    return strcmp(ea->word, eb->word);
}

int main(void) {
    char buf[MAX_WORD];
    int len = 0, c;
    while ((c = getchar()) != EOF) {
        if (isalpha((unsigned char)c) || c == '\'') {
            if (len < MAX_WORD - 1) {
                buf[len++] = (char)tolower((unsigned char)c);
            }
            // If longer than MAX_WORD-1, keep consuming but truncate.
        } else if (len > 0) {
            buf[len] = '\0';
            int created;
            Entry *e = lookup_or_add(buf, &created);
            e->count++;
            len = 0;
        }
    }
    if (len > 0) {
        buf[len] = '\0';
        int created;
        Entry *e = lookup_or_add(buf, &created);
        e->count++;
    }

    size_t total = 0;
    for (int i = 0; i < TABLE_SIZE; ++i)
        for (Entry *e = table[i]; e; e = e->next)
            ++total;

    if (total == 0) {
        puts("no words");
        return 0;
    }

    Entry **all = malloc(total * sizeof(*all));
    if (!all) { perror("malloc"); return 1; }
    size_t k = 0;
    for (int i = 0; i < TABLE_SIZE; ++i)
        for (Entry *e = table[i]; e; e = e->next)
            all[k++] = e;

    qsort(all, total, sizeof(*all), compare);

    size_t top = total < 10 ? total : 10;
    for (size_t i = 0; i < top; ++i)
        printf("%s %ld\n", all[i]->word, all[i]->count);

    for (int i = 0; i < TABLE_SIZE; ++i) {
        Entry *e = table[i];
        while (e) {
            Entry *next = e->next;
            free(e->word);
            free(e);
            e = next;
        }
    }
    free(all);
    return 0;
}
```

A DJB2 hash distributes words across a chained table. Words are lowercased and split on any non-letter (apostrophes kept). After counting, entries are collected into an array, `qsort` orders by descending count with `strcmp` breaking ties alphabetically, and the first ten are printed. Empty input prints `no words`, and all allocations are freed before exit.

