fn is_valid_ipv4(s: &str) -> bool {
    let mut parts = 0u8;
    for octet in s.split('.') {
        parts += 1;
        if parts > 4 {
            return false;
        }
        if octet.is_empty() {
            return false;
        }
        // Strict: digits only, no leading zero unless the octet is exactly "0".
        if !octet.bytes().all(|b| b.is_ascii_digit()) {
            return false;
        }
        if octet.len() > 1 && octet.starts_with('0') {
            return false;
        }
        if octet.len() > 3 {
            return false;
        }
        let value: u32 = match octet.parse() {
            Ok(v) => v,
            Err(_) => return false,
        };
        if value > 255 {
            return false;
        }
    }
    parts == 4
}

fn main() {
    let valid = [
        "0.0.0.0",
        "127.0.0.1",
        "255.255.255.255",
        "192.168.1.1",
        "10.0.0.255",
        "1.1.1.1",
    ];
    let invalid = [
        "",
        "256.1.1.1",
        "1.2.3",
        "1.2.3.4.5",
        "01.2.3.4",
        "1..2.3",
        "1.2.3.4\n",
        "a.b.c.d",
        "1.2.3.-4",
        "1.2.3.4 ",
        "0000.1.1.1",
    ];
    for ip in valid {
        assert!(is_valid_ipv4(ip), "expected valid: {ip}");
    }
    for ip in invalid {
        assert!(!is_valid_ipv4(ip), "expected invalid: {ip}");
    }
    println!("all ipv4 checks passed");
}
