The function splits on `'.'` and counts fields so strings with too few or too many octets fail. Each octet must be non-empty, all ASCII digits, at most three characters, and must not have a leading zero unless it is the single character `"0"`. Parsing after those checks is safe, and the final `> 255` guard rejects out-of-range values.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <utility>

template <typename T, std::size_t N>
class RingBuffer {
public:
    static_assert(N > 0, "capacity must be positive");

    RingBuffer() = default;
    RingBuffer(const RingBuffer&) = default;
    RingBuffer& operator=(const RingBuffer&) = default;
    RingBuffer(RingBuffer&&) noexcept = default;
    RingBuffer& operator=(RingBuffer&&) noexcept = default;

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }
    static constexpr std::size_t capacity() { return N; }

    bool push(const T& value) {
        if (full()) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    bool push(T&& value) {
        if (full()) return false;
        data_[(head_ + size_) % N] = std::move(value);
        ++size_;
        return true;
    }

    bool pop(T& out) {
        if (empty()) return false;
        out = std::move(data_[head_]);
        head_ = (head_ + 1) % N;
        --size_;
        return true;
    }

    const T& peek() const {
        if (empty()) throw std::out_of_range("peek on empty ring buffer");
        return data_[head_];
    }

    void clear() {
        head_ = 0;
        size_ = 0;
    }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.empty() || rb.full()) return 1;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (!rb.full() || rb.push(4)) return 1;
    if (rb.peek() != 1) return 1;

    int v = 0;
    if (!rb.pop(v) || v != 1) return 1;
    if (!rb.push(4)) return 1; // wraps around
    if (rb.peek() != 2) return 1;
    if (rb.size() != 3) return 1;

    rb.clear();
    if (!rb.empty()) return 1;
    if (rb.pop(v)) return 1; // nothing to pop

    try {
        (void)rb.peek();
        return 1; // should have thrown
    } catch (const std::out_of_range&) {
    }

    std::cout << "ring buffer ok\n";
    return 0;
}
```

`head_` tracks the oldest element and `size_` the count, so the write index is `(head_ + size_) % N` and no separate tail index is needed. `push`/`pop` return `bool` instead of throwing, while `peek` on a corrupt/empty state throws `std::out_of_range`. Move operations are defaulted and marked `noexcept`, and `clear()` resets the buffer without touching the underlying storage.

```python
import argparse
import hashlib
import os
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed

CHUNK = 1 << 20  # 1 MiB


def file_sha256(path):
    h = hashlib.sha256()
    try:
        with open(path, "rb") as fh:
            while True:
                block = fh.read(CHUNK)
                if not block:
                    break
                h.update(block)
    except OSError as exc:
        return path, None, str(exc)
    return path, h.hexdigest(), None


def main(argv=None):
    parser = argparse.ArgumentParser(description="SHA-256 every file under a directory.")
    parser.add_argument("directory")
    parser.add_argument("-j", "--workers", type=int, default=os.cpu_count() or 4)
    args = parser.parse_args(argv)

    root = os.path.abspath(args.directory)
    if not os.path.isdir(root):
        print(f"error: not a directory: {root}", file=sys.stderr)
        return 1
    if args.workers < 1:
        print("error: workers must be >= 1", file=sys.stderr)
        return 1

    paths = []
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            paths.append(os.path.join(dirpath, name))
    paths.sort()  # deterministic order regardless of completion order

    results = []
    errors = 0
    with ThreadPoolExecutor(max_workers=args.workers) as pool:
        futures = {pool.submit(file_sha256, p): p for p in paths}
        for done, future in enumerate(as_completed(futures), start=1):
            path, digest, err = future.result()
            if err is None:
                results.append((path, digest))
            else:
                errors += 1
                print(f"!! {path}: {err}", file=sys.stderr)
            print(f"[{done}/{len(paths)}]", file=sys.stderr)

    results.sort()
    for path, digest in results:
        print(f"{digest}  {os.path.relpath(path, root)}")

    if not paths:
        print("no files found", file=sys.stderr)
    return 1 if errors else 0


if __name__ == "__main__":
    raise SystemExit(main())
```

Hashing releases the GIL on I/O, so a thread pool helps even without processes. Results are buffered and `sort()`ed after the pool finishes, so output order is independent of which thread completes first. Per-file `OSError`s are reported to stderr and cause a non-zero exit, while the progress counter goes to stderr so stdout stays a clean checksum list. An empty directory reports `no files found`.

