bool is_balanced(const char *s) {
    char stack[4096];
    int top = -1;
    for (size_t i = 0; s[i]; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            if (top == 4095) return false; /* overflow guard */
            stack[++top] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top < 0 || !matches(stack[top], c)) return false;
            top--;
        }
        /* other characters ignored */
    }
    return top == -1;
}

int main(void) {
    const char *cases[] = {"({[]})", "(]", "", "a(b)c[d]", "(((", "][" };
    for (int i = 0; i < 6; i++) {
        printf("%-10s -> %s\n", cases[i], is_balanced(cases[i]) ? "balanced" : "unbalanced");
    }
    return 0;
