fn fib(n: u32) -> Result<u64, String> {
    fn helper(n: u32, memo: &mut HashMap<u32, u64>) -> Result<u64, String> {
        if n < 2 {
            return Ok(n as u64);
        }
        if let Some(&v) = memo.get(&n) {
            return Ok(v);
        }
        let a = helper(n - 1, memo)?;
        let b = helper(n - 2, memo)?;
        let val = a.checked_add(b).ok_or_else(|| format!("overflow at n={}", n))?;
        memo.insert(n, val);
        Ok(val)
    }
    helper(n, &mut HashMap::new())
}

