#include <iostream>
#include <vector>
#include <string>

template <typename T>
int binary_search(const std::vector<T>& v, const T& target) {
    int lo = 0, hi = static_cast<int>(v.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == target) return mid;
        if (v[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> nums{1, 3, 5, 7, 9, 11};
    std::vector<std::string> words{"apple", "banana", "cherry", "date"};

    std::cout << binary_search(nums, 7) << "\n";       // 3
    std::cout << binary_search(nums, 4) << "\n";       // -1
    std::cout << binary_search(words, std::string("cherry")) << "\n"; // 2

    std::vector<int> empty;
    std::cout << binary_search(empty, 1) << "\n";      // -1
    return 0;
}
