long long ipow(long long base, unsigned exp, bool *overflow) {
    long long result = 1;
    *overflow = false;
    while (exp > 0) {
        if (exp & 1u) {
            if (result > LLONG_MAX / base) { *overflow = true; return 0; }
            result *= base;
        }
        exp >>= 1;
        if (exp > 0) {
            if (base > LLONG_MAX / base) { *overflow = true; return 0; }
            base *= base;
        }
    }
    return result;
}

