use std::fmt;

#[derive(Debug, PartialEq)]
struct Version {
    major: u32,
    minor: u32,
    patch: u32,
}

#[derive(Debug, PartialEq)]
enum ParseError {
    WrongParts(usize),
    BadNumber(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::WrongParts(n) => write!(f, "expected 3 parts, got {n}"),
            ParseError::BadNumber(s) => write!(f, "invalid number: {s:?}"),
        }
    }
}

fn parse_version(s: &str) -> Result<Version, ParseError> {
    let parts: Vec<&str> = s.trim().split('.').collect();
    if parts.len() != 3 {
        return Err(ParseError::WrongParts(parts.len()));
    }
    let nums: Result<Vec<u32>, _> = parts.iter().map(|p| p.parse::<u32>()).collect();
    let nums = nums.map_err(|_| {
        let bad = parts
            .iter()
            .find(|p| p.parse::<u32>().is_err())
            .unwrap()
            .to_string();
        ParseError::BadNumber(bad)
    })?;
    Ok(Version { major: nums[0], minor: nums[1], patch: nums[2] })
}

fn main() {
    assert_eq!(parse_version("1.2.3"), Ok(Version { major: 1, minor: 2, patch: 3 }));
    assert!(parse_version("1.2").is_err());
    assert!(parse_version("1.2.x").is_err());
    assert_eq!(parse_version(" 10.0.42 "), Ok(Version { major: 10, minor: 0, patch: 42 }));
    println!("ok");
}
