std::vector<int> dedupe_preserve_order(const std::vector<int>& input) {
    std::vector<int> out;
    std::unordered_set<int> seen;
    out.reserve(input.size());
    for (int value : input) {
        if (seen.insert(value).second) {
            out.push_back(value);
        }
    }
    return out;
}

int main() {
    std::vector<int> data = {3, 1, 3, 2, 1, 5, 2};
    std::vector<int> result = dedupe_preserve_order(data);
    for (int v : result) std::cout << v << ' ';
    std::cout << '\n';  // 3 1 2 5
    return 0;
}
