import csv
import sys
from collections import defaultdict


def running_balance(path):
    """Yield (account, balance) rows after applying each transaction."""
    balances = defaultdict(float)
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        required = {"account", "amount"}
        missing = required - set(reader.fieldnames or [])
        if missing:
            raise ValueError(f"missing columns: {sorted(missing)}")
        for line_no, row in enumerate(reader, start=2):
            account = (row.get("account") or "").strip()
            raw = (row.get("amount") or "").strip()
            if not account:
                raise ValueError(f"line {line_no}: empty account")
            try:
                amount = float(raw)
            except ValueError:
                raise ValueError(f"line {line_no}: bad amount {raw!r}")
            balances[account] += amount
            yield account, balances[account]


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit("usage: running_balance.py <file.csv>")
    for account, balance in running_balance(sys.argv[1]):
        print(f"{account}\t{balance:.2f}")
```

It streams rows so a large file never lands fully in memory, validates the header before iterating, and raises a `ValueError` with the line number when an amount is not numeric instead of silently skipping it.

