            const double median = sum / 2.0;
            std::cout.precision(10);
            std::cout << median << '\n';
        }
    }
    return 0;
}
```

For an even count it prints `(lo + hi) / 2`, keeping it exact as an integer when the sum is even and only falling back to `double` when it is not. `long long` avoids overflow on large inputs, and an empty stream exits with a nonzero status and a message on stderr.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (count_ == N) {
            return false;  // full
        }
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<int> pop() {
        if (count_ == 0) {
            return std::nullopt;  // empty
        }
        const int value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << '\n';  // 1110
    std::cout << rb.size() << '\n';  // 3
    while (auto v = rb.pop()) std::cout << *v;
    std::cout << '\n';  // 123
    std::cout << rb.empty() << '\n';  // 1
    return 0;
}
```

`push` returns `false` when the buffer is full rather than overwriting, and `pop` returns `std::optional<int>` so underflow is representable without sentinel values. `N` is a template parameter, so the storage is a plain `std::array` with no heap allocation.

