fn is_balanced(input: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for ch in input.chars() {
        match ch {
            '(' | '[' | '{' => stack.push(ch),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(expected) {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    assert!(is_balanced(""));
    assert!(is_balanced("{[()]}"));
    assert!(!is_balanced("([)]"));
    assert!(!is_balanced("((("));
    assert!(!is_balanced(")"));
    assert!(is_balanced("ignored text {a} (b)"));
    println!("ok");
}
```

The stack stores opening brackets; each closing bracket must match the most recent unmatched opener, which catches interleavings like `([)]` that a simple counter would miss. Characters that are not brackets are skipped, and the final `stack.is_empty()` catches unbalanced openers.

