def is_valid_ipv4(s):
    """Return True only for dotted-quad IPv4 strings like '192.168.0.1'."""
    if not isinstance(s, str):
        return False
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":
            return False  # reject leading zeros such as '01'
        value = int(part)
        if value > 255:
            return False
    return True


if __name__ == "__main__":
    good = ["0.0.0.0", "255.255.255.255", "192.168.1.1", "10.0.0.1"]
    bad = ["256.1.1.1", "1.2.3", "1.2.3.4.5", "01.2.3.4", "1.2.3.", "", "1.2.3.a", " 1.2.3.4"]
    for ip in good:
        assert is_valid_ipv4(ip), ip
    for ip in bad:
        assert not is_valid_ipv4(ip), ip
    print("ok")
```

`part.isdigit()` rejects empty fields, signs, and spaces, while the leading-zero rule blocks the ambiguous `01` form that some parsers read as octal. Each octet is range-checked against 255, and whitespace is rejected because `isdigit()` is false for `' 1'`.

```python
def rle_encode(text):
    """Encode runs of repeated characters as char + count."""
    if not text:
        return ""
    parts = []
    prev = text[0]
    count = 1
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            parts.append(f"{prev}{count}")
            prev, count = ch, 1
    parts.append(f"{prev}{count}")
    return "".join(parts)


def rle_decode(encoded):
    """Decode char+count pairs produced by rle_encode."""
    out = []
    i = 0
    while i < len(encoded):
        ch = encoded[i]
        i += 1
        start = i
        while i < len(encoded) and encoded[i].isdigit():
            i += 1
        if start == i:
            raise ValueError(f"missing count at position {start}")
        out.append(ch * int(encoded[start:i]))
    return "".join(out)


if __name__ == "__main__":
    for s in ["", "a", "aaabbbcccd", "\u00e9\u00e9\u00e9x", "abc"]:
        assert rle_decode(rle_encode(s)) == s, s
    assert rle_encode("aaabb") == "a3b2"
    assert rle_decode("a3b2") == "aaabb"
    print("round-trip ok")
