class SaturatingCounter {
public:
    explicit SaturatingCounter(std::uint64_t cap = 1000) : cap_(cap), value_(0) {}

    void add(std::uint64_t n) {
        if (n > cap_ - value_) {
            value_ = cap_;
        } else {
            value_ += n;
        }
    }

    void reset() { value_ = 0; }
    std::uint64_t value() const { return value_; }
    bool at_cap() const { return value_ == cap_; }

private:
    std::uint64_t cap_;
    std::uint64_t value_;
};

int main() {
    SaturatingCounter c(10);
    c.add(4);
    c.add(5);
    std::printf("%llu\n", static_cast<unsigned long long>(c.value()));  // 9
    c.add(100);
    std::printf("%llu %d\n", static_cast<unsigned long long>(c.value()),
                c.at_cap() ? 1 : 0);  // 10 1
    c.reset();
    c.add(1000000);
    std::printf("%llu\n", static_cast<unsigned long long>(c.value()));  // 10
    return 0;
}
