fn fib(n: u64) -> Option<u128> {
    fn helper(n: u64) -> Option<(u128, u128)> {
        if n == 0 {
            return Some((0, 1));
        }
        let (a, b) = helper(n / 2)?;
        let c = a.checked_mul(2u128.checked_mul(b)?.checked_sub(a)?)?;
        let d = a.checked_mul(a)?.checked_add(b.checked_mul(b)?)?;
        if n % 2 == 0 {
