int binarySearch(const std::vector<int>& v, int target) {
    int lo = 0, hi = static_cast<int>(v.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;  // avoids overflow
        if (v[mid] == target) return mid;
        if (v[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> v = {-9, -3, 0, 1, 5, 5, 8, 12};
    for (int t : {-9, 5, 12, 7, 100}) {
        std::cout << t << " -> index " << binarySearch(v, t) << "\n";
    }
    std::vector<int> empty;
    std::cout << "empty -> " << binarySearch(empty, 3) << "\n";
    return 0;
}
```

Uses `lo + (hi - lo) / 2` to dodge overflow, and handles the empty vector since `hi` starts at -1. Returns any valid index among duplicates.

