def primes_up_to(limit: int) -> list:
    if limit < 2:
        return []
    sieve = bytearray([1]) * (limit + 1)
    sieve[0] = sieve[1] = 0
    i = 2
    while i * i <= limit:
        if sieve[i]:
            sieve[i * i:limit + 1:i] = b"\x00" * (((limit - i * i) // i) + 1)
        i += 1
    return [x for x, flag in enumerate(sieve) if flag]


