    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, "a")
    c.put(2, "b")
    assert c.get(1) == "a"   # 1 is now most-recent
    c.put(3, "c")             # evicts 2
    assert c.get(2) is None
    assert c.get(3) == "c"
    print("ok")
```

`get` also refreshes recency, `put` on an existing key updates without evicting, and the capacity guard rejects zero or negative sizes up front.

```cpp
#include <cstddef>

struct Node {
    int value;
    Node* next;
    Node(int v, Node* n = nullptr) : value(v), next(n) {}
};

// Reverses the list. Returns false (unchanged) if a cycle is found.
bool reverse_list(Node*& head) {
    Node* prev = nullptr;
    Node* cur = head;
    Node* slow = head;
    Node* fast = head;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return false;  // cycle
    }

    while (cur) {
        Node* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    head = prev;
    return true;
}
```

Floyd's tortoise-and-hare runs first, so a corrupted list returns `false` rather than hanging. On a well-formed list the standard three-pointer reversal gives O(n) time and O(1) space.

