#include <cstdlib>
#include <cstring>
#include <utility>

class Buffer {
public:
    explicit Buffer(std::size_t n) : size_(n), data_(static_cast<char*>(std::malloc(n))) {}

    ~Buffer() { std::free(data_); }

    Buffer(const Buffer& o) : size_(o.size_), data_(static_cast<char*>(std::malloc(o.size_))) {
        if (data_) std::memcpy(data_, o.data_, size_);
    }

    Buffer& operator=(const Buffer& o) {
        if (this != &o) {
            Buffer tmp(o);
            swap(tmp);
        }
        return *this;
    }

    Buffer(Buffer&& o) noexcept : size_(o.size_), data_(o.data_) {
        o.data_ = nullptr;
        o.size_ = 0;
    }

    Buffer& operator=(Buffer&& o) noexcept {
        if (this != &o) {
            std::free(data_);
            data_ = o.data_;
            size_ = o.size_;
            o.data_ = nullptr;
            o.size_ = 0;
        }
        return *this;
    }

    void swap(Buffer& o) noexcept {
        std::swap(size_, o.size_);
        std::swap(data_, o.data_);
    }

    std::size_t size() const { return size_; }
    char* data() { return data_; }

private:
    std::size_t size_;
    char* data_;
};
