static int cmp(const void* a, const void* b) {
    int x = *(const int*)a, y = *(const int*)b;
    return (x > y) - (x < y);
}

static size_t lower_bound(const int* a, size_t n, int v) {
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (a[mid] < v) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

int main(void) {
    size_t cap = 16, n = 0;
    int* a = malloc(cap * sizeof(int));
    if (!a) return 1;

    int v;
    while (scanf("%d", &v) == 1) {
        if (n == cap) {
            cap *= 2;
            int* bigger = realloc(a, cap * sizeof(int));
            if (!bigger) { free(a); return 1; }
            a = bigger;
        }
        size_t pos = lower_bound(a, n, v);
        memmove(a + pos + 1, a + pos, (n - pos) * sizeof(int));
        a[pos] = v;
        n++;

        double median = (n % 2) ? a[n / 2]
                                : (a[n / 2 - 1] + a[n / 2]) / 2.0;
        printf("%.1f\n", median);
    }

    if (n == 0) fprintf(stderr, "no input\n");
    free(a);
    return 0;
}
