#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& v, int target) {
    std::size_t lo = 0, hi = v.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;  // avoids overflow
        if (v[mid] == target) return static_cast<int>(mid);
        if (v[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return -1;
}

int main() {
    std::vector<int> data = {1, 3, 5, 7, 9, 11};
    std::cout << binary_search(data, 7) << '\n';   // 3
    std::cout << binary_search(data, 1) << '\n';   // 0
    std::cout << binary_search(data, 11) << '\n';  // 5
    std::cout << binary_search(data, 4) << '\n';   // -1
    std::cout << binary_search({}, 4) << '\n';      // -1
}
```

Using the half-open range `[lo, hi)` keeps the loop invariant clean and makes the empty vector fall out naturally: `lo == hi == 0`, so it returns -1. `mid = lo + (hi - lo) / 2` never overflows for large `size_t` values.

```rust
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[]), vec![1, 3, 5]);
    assert_eq!(merge_sorted(&[2, 4], &[1, 3, 6]), vec![1, 2, 3, 4, 6]);
    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 2, 2]), vec![1, 1, 1, 2, 2, 2]);
    println!("all merge tests passed");
}
```

`<=` on the left keeps equal elements stable from `a`. The tail `extend_from_slice` calls handle whatever remains after one side is exhausted, so both empty inputs and length-mismatched inputs work without a separate branch.

