```cpp
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

std::vector<int> read_ints(const std::string& path, std::string& error) {
    std::vector<int> out;
    std::ifstream in(path);
    if (!in) {
        error = "cannot open " + path;
        return out;
    }
    int value;
    while (in >> value) {
        out.push_back(value);
    }
    if (!in.eof()) {
        error = "non-integer token in " + path;
        out.clear();
    }
    return out;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "usage: " << argv[0] << " <file>\n";
        return 2;
    }
    std::string error;
    std::vector<int> data = read_ints(argv[1], error);
    if (!error.empty()) {
        std::cerr << "error: " << error << '\n';
        return 1;
    }
    long long sum = 0;
    for (int v : data) sum += v;
    std::cout << "count=" << data.size() << " sum=" << sum << '\n';
}
```

After the extraction loop, `!in.eof()` means extraction stopped for a reason other than end of file — a bad token — so the function clears the partial vector and reports it. The caller checks `error` instead of relying on an empty vector, which a genuinely empty file would also produce.

