use std::sync::mpsc;
use std::thread;

fn parallel_sum(numbers: Vec<u64>) -> u64 {
    if numbers.is_empty() {
        return 0;
    }

    let workers = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1);
    let chunk_size = (numbers.len() + workers - 1) / workers;

    let (tx, rx) = mpsc::channel();
    let mut handles = Vec::new();

    for chunk in numbers.chunks(chunk_size) {
        let tx = tx.clone();
        let part: Vec<u64> = chunk.to_vec();
        handles.push(thread::spawn(move || {
            let subtotal: u64 = part.iter().sum();
            tx.send(subtotal).expect("receiver dropped");
        }));
    }
    drop(tx);

    let mut total = 0u64;
    for handle in handles {
        handle.join().expect("worker panicked");
    }
    for subtotal in rx {
        total += subtotal;
    }
    total
}

fn main() {
    let data: Vec<u64> = (1..=1000).collect();
    assert_eq!(parallel_sum(data), 500500);
    assert_eq!(parallel_sum(vec![]), 0);
    println!("ok");
}
```

Each thread owns its slice and reports one subtotal over a channel; no shared mutable state means no locks and no data race.

```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), capacity_(capacity) {}

    bool full() const { return size_ == capacity_; }
    bool empty() const { return size_ == 0; }

    bool push(const T& value) {
        if (full()) return false;
        data_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

private:
    std::vector<T> data_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int> rb(2);
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << "\n";  // 110
    std::cout << *rb.pop() << *rb.pop() << "\n";                  // 12
    std::cout << rb.empty() << "\n";                              // 1
}
```

Push returns `false` when full and pop returns `std::nullopt` when empty, so both overflow and underflow are explicit rather than undefined.

