```c
#include <stdio.h>
#include <stddef.h>

int binary_search(const int *arr, size_t n, int target) {
    size_t lo = 0, hi = n;  /* search [lo, hi) */
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;  /* no overflow */
        if (arr[mid] == target) {
            return (int)mid;
        } else if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

int main(void) {
    int data[] = {-7, -3, 0, 2, 5, 5, 9, 14, 21};
    size_t n = sizeof(data) / sizeof(data[0]);
    printf("%d\n", binary_search(data, n, 5));
    printf("%d\n", binary_search(data, n, -7));
    printf("%d\n", binary_search(data, n, 21));
    printf("%d\n", binary_search(data, n, 4));
    printf("%d\n", binary_search(data, 0, 4));
    return 0;
}
```

Using a half-open range `[lo, hi)` and `mid = lo + (hi - lo) / 2` avoids the signed overflow of `(lo + hi) / 2` and the infinite loop that a closed range can cause. It returns the index of *a* matching element when duplicates exist. Output is `4`, `0`, `8`, `-1`, `-1`.

