#include <stddef.h>
#include <stdio.h>

/* Copies src into dst of capacity cap. Returns the number of bytes written
 * (excluding the terminator). dst is always null-terminated when cap > 0. */
size_t safe_copy(char *dst, size_t cap, const char *src) {
    if (cap == 0) {
        return 0;
    }
    size_t i = 0;
    while (i + 1 < cap && src[i] != '\0') {
        dst[i] = src[i];
        ++i;
    }
    dst[i] = '\0';
    return i;
}

int main(void) {
    char buf[8];
    size_t n = safe_copy(buf, sizeof buf, "hello world");
    printf("%zu %s\n", n, buf);      /* 7 hello w */

    char empty[1];
    safe_copy(empty, sizeof empty, "something");
    printf("%s\n", empty);           /* prints nothing */

    safe_copy(buf, sizeof buf, "");   /* empty source */
    printf("[%s]\n", buf);           /* [] */
    return 0;
}
```

