```cpp
#include <cstddef>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), tail_(0), size_(0) {}

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == data_.size(); }

    bool push(int value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % data_.size();
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % data_.size();
        --size_;
        return value;
    }

private:
    std::vector<int> data_;
    std::size_t head_, tail_, size_;
};
```

The modulo indexing wraps indices, and `size_` distinguishes full from empty when head equals tail.

