fn two_smallest<T: Ord + Copy>(items: &[T]) -> Option<(T, T)> {
    let mut first: Option<T> = None;
    let mut second: Option<T> = None;

    for &item in items {
        match first {
            None => first = Some(item),
            Some(f) if item < f => {
                second = first;
                first = Some(item);
            }
            Some(_) => {
                if second.map_or(true, |s| item < s) {
                    second = Some(item);
                }
            }
        }
    }

    match (first, second) {
        (Some(a), Some(b)) => Some((a, b)),
        _ => None,
    }
}

