```c
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

/* Returns SIZE_MAX if valid, else the offset of the first invalid byte. */
size_t utf8_first_invalid(const unsigned char *buf, size_t len) {
    size_t i = 0;
    while (i < len) {
        unsigned char c = buf[i];
        size_t need = 0;
        unsigned cp_min = 0x80;

        if (c < 0x80) { i += 1; continue; }
        else if ((c & 0xE0) == 0xC0) { need = 1; cp_min = 0x80; }
        else if ((c & 0xF0) == 0xE0) { need = 2; cp_min = 0x800; }
        else if ((c & 0xF8) == 0xF0) { need = 3; cp_min = 0x10000; }
        else { return i; }

        if (i + need >= len) return i;

        unsigned cp = c & (0xFFu >> (need + 1));
        for (size_t k = 1; k <= need; ++k) {
            unsigned char cc = buf[i + k];
            if ((cc & 0xC0) != 0x80) return i;
            cp = (cp << 6) | (cc & 0x3Fu);
        }
        if (cp < cp_min || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) {
            return i;
        }
        i += need + 1;
    }
    return SIZE_MAX;
}

int main(void) {
    const unsigned char good[] = {'h', 0xC3, 0xA9};
    const unsigned char bad[]  = {0xC3, 0x28};
    const unsigned char trunc[] = {0xE2, 0x82};

    printf("%zu\n", utf8_first_invalid(good, sizeof good));   /* large value */
    printf("%zu\n", utf8_first_invalid(bad, sizeof bad));     /* 0 */
    printf("%zu\n", utf8_first_invalid(trunc, sizeof trunc)); /* 0 */
    return 0;
}
```

It rejects overlong encodings via `cp_min`, surrogate halves, and out-of-range code points. Incomplete sequences return the start offset.

