#include <string.h>

void reverse(char *s) {
    if (s == NULL) return;
    size_t i = 0, j = strlen(s);
    while (i + 1 < j) {
        char tmp = s[i];
        s[i++] = s[j - 1];
        s[j-- - 1] = tmp;
    }
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "x";
    reverse(a);
    reverse(b);
    reverse(c);
    printf("%s\n", a);
    printf("[%s]\n", b);
    printf("%s\n", c);
    return 0;
}
