use std::collections::HashMap;

fn top_n_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let key = word.trim_matches(|c: char| !c.is_alphanumeric()).to_lowercase();
        if key.is_empty() {
            continue;
        }
        *counts.entry(key).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the cat the dog The bird cat";
    let result = top_n_words(text, 2);
    assert_eq!(result[0], ("the".to_string(), 3));
    assert_eq!(result[1], ("cat".to_string(), 2));
    assert!(top_n_words("", 5).is_empty());
    println!("{:?}", result);
}
```

`split_whitespace` ignores runs of spaces. `trim_matches` strips punctuation and `to_lowercase` folds case so `The` and `the` merge. The sort is by descending count, then ascending word for a deterministic tie-break. Empty input yields an empty map, and `truncate` protects against `n` larger than the number of distinct words.

```cpp
#include <array>
#include <cstddef>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        if (size_ == N) {
            throw std::overflow_error("ring buffer full");
        }
        data_[(head_ + size_) % N] = value;
        ++size_;
    }

    T pop() {
        if (size_ == 0) {
            throw std::underflow_error("ring buffer empty");
        }
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};
```

`head_` marks the oldest element and `(head_ + size_) % N` is the next free slot, so no separate tail index is needed. Push throws `overflow_error` when full and pop throws `underflow_error` when empty, leaving state untouched on failure. `N` is a compile-time capacity; `size_` tracks occupancy so `empty()` is O(1).

