WORD_CHARS = "'-\u2019"  # apostrophes inside words, e.g. don't

def tokenize(line: str) -> list[str]:
    word = []
    words = []
    for ch in line.lower():
        if ch.isalnum() or ch in WORD_CHARS:
            word.append(ch)
        elif word:
            w = "".join(word).strip("'-\u2019")
            if w:
                words.append(w)
            word = []
    if word:
        w = "".join(word).strip("'-\u2019")
        if w:
            words.append(w)
    return words

def count_words(path: str, top_n: int = 10) -> list[tuple[str, int]]:
    counts: Counter[str] = Counter()
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            counts.update(tokenize(line))
    return counts.most_common(top_n)

