#include <cctype>
#include <charconv>
#include <optional>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

struct ParseError : std::runtime_error {
    using std::runtime_error::runtime_error;
};

// Trim surrounding ASCII whitespace.
static std::string_view trim(std::string_view s) {
    auto ws = [](char c) { return std::isspace(static_cast<unsigned char>(c)); };
    while (!s.empty() && ws(s.front())) s.remove_prefix(1);
    while (!s.empty() && ws(s.back()))  s.remove_suffix(1);
    return s;
}

std::vector<long long> parse_int_list(std::string_view line) {
    std::vector<long long> out;
    if (trim(line).empty()) return out;  // empty line -> empty list

    std::size_t start = 0;
    while (start <= line.size()) {
        std::size_t comma = line.find(',', start);
        std::string_view field = (comma == std::string_view::npos)
                                     ? line.substr(start)
                                     : line.substr(start, comma - start);
        field = trim(field);
        if (field.empty()) {
            throw ParseError("empty field in list");
        }
        long long value = 0;
        auto [ptr, ec] = std::from_chars(field.data(), field.data() + field.size(), value);
        if (ec != std::errc{} || ptr != field.data() + field.size()) {
            throw ParseError("not an integer: \"" + std::string(field) + "\"");
        }
        out.push_back(value);
        if (comma == std::string_view::npos) break;
        start = comma + 1;
    }
    return out;
}
```

