```cpp
#include <array>
#include <cstddef>
#include <iterator>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
    static_assert(N > 0, "capacity must be positive");

public:
    bool push(const T& value) {
        if (full()) return false;
        buf_[head_] = value;
        head_ = (head_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        std::optional<T> out = std::move(buf_[tail_]);
        buf_[tail_] = T{};
        tail_ = (tail_ + 1) % N;
        --size_;
        return out;
    }

    const T& front() const {
        if (empty()) throw std::out_of_range("front on empty ring");
        return buf_[tail_];
    }

    bool empty() const noexcept { return size_ == 0; }
    bool full()  const noexcept { return size_ == N; }
    std::size_t size() const noexcept { return size_; }
    static constexpr std::size_t capacity() noexcept { return N; }

    class iterator {
    public:
        using iterator_category = std::forward_iterator_tag;
        using value_type = T;
        using difference_type = std::ptrdiff_t;
        using pointer = const T*;
        using reference = const T&;

        reference operator*() const { return *owner_->buf_.data() + index_; }
        pointer operator->() const { return &(*owner_->buf_.data() + index_); }
        iterator& operator++() { index_ = (index_ + 1) % N; ++count_; return *this; }
        bool operator==(const iterator& o) const { return count_ == o.count_; }
        bool operator!=(const iterator& o) const { return !(*this == o); }

    private:
        friend class RingBuffer;
        iterator(const RingBuffer* owner, std::size_t index, std::size_t count)
            : owner_(owner), index_(index), count_(count) {}
        const RingBuffer* owner_;
        std::size_t index_;
        std::size_t count_;
    };

    iterator begin() const { return iterator(this, tail_, 0); }
    iterator end()   const { return iterator(this, head_, size_); }

private:
    std::array<T, N> buf_{};
    std::size_t head_ = 0;  // next write
    std::size_t tail_ = 0;  // next read
    std::size_t size_ = 0;
};
```

Heads-up on two things before you ship this: `std::array<T, N>` default-constructs every slot, so `T` must be default-constructible; and `begin()` on an empty buffer equals `end()`, which is correct, but iterating from `begin()` when `size_ == N` is fine too since the length is tracked separately from the index.

```rust
/// Merge two ascending-sorted slices into one ascending Vec.
/// Stable: on ties, elements from `a` are taken first.
pub fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

