    #[test]
    fn unicode_strings() {
        let a = ["café".to_string(), "zebra".to_string()];
        let b = ["apple".to_string(), "zèbre".to_string()];
        let got = merge_sorted(&a, &b);
        assert_eq!(got, vec!["apple", "café", "zebra", "zèbre"]);
    }
}
