# Longest palindromic substring via expand-around-center, O(n^2) time, O(1) space.

def longest_palindrome(s: str) -> str:
    if not isinstance(s, str):
        raise TypeError("input must be a string")
    if not s:
        return ""

    start = end = 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1  # last valid bounds

    for i in range(len(s)):
        l1, r1 = expand(i, i)       # odd-length centers
        l2, r2 = expand(i, i + 1)   # even-length centers
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


def main() -> None:
    cases = ["babad", "cbbd", "a", "", "abba", "forgeeksskeegfor"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))


if __name__ == "__main__":
    main()
