/// Merge two sorted slices into a new sorted Vec, dropping duplicates.
fn merge_dedup(a: &[i64], b: &[i64]) -> Vec<i64> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);

    while i < a.len() || j < b.len() {
        // Pick the smaller of the two current heads; ties consume both.
        let next = if j >= b.len() || (i < a.len() && a[i] <= b[j]) {
            let v = a[i];
            i += 1;
            v
        } else {
            let v = b[j];
            j += 1;
            v
        };
        // Skip any follow-up values equal to the one just pushed.
        if out.last() != Some(&next) {
            out.push(next);
        }
    }
    out
}

fn main() {
    let a = [1, 3, 3, 5, 9];
    let b = [3, 4, 5, 5, 8];
    println!("{:?}", merge_dedup(&a, &b)); // [1, 3, 4, 5, 8, 9]
    assert_eq!(merge_dedup(&[], &[]), Vec::<i64>::new());
    assert_eq!(merge_dedup(&[7], &[7, 7]), vec![7]);
}
