/* Reverse s in place and return s. Returns NULL if s is NULL. */
char *reverse_string(char *s) {
    if (s == NULL) {
        return NULL;
    }
    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0) {
        return s; /* empty string */
    }
    j -= 1; /* index of last character */
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
    return s;
}

int main(void) {
