use std::collections::HashMap;

/// Count words (split on Unicode whitespace, lowercased) and return the
/// top `n` as (word, count), sorted by count desc then word asc.
fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        // Lowercase and trim surrounding punctuation for a fairer count.
        let cleaned: String = word
            .to_lowercase()
            .chars()
            .filter(|c| c.is_alphanumeric())
            .collect();
        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count desc, then alphabetically for stable ties.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The cat sat on the mat, the CAT!";
    println!("{:?}", top_words(text, 2)); // [("the", 3), ("cat", 2)]
    assert!(top_words("", 5).is_empty());
}
