# bisect_left semantics: returns the index of value if present,
# otherwise the index where it would be inserted to keep the list sorted.

def search_insert(nums, target: int) -> int:
    if not isinstance(target, int):
        raise TypeError("target must be an int")
    # Validation is O(n) but cheap relative to the risk of silent bugs.
    if any(nums[i] > nums[i + 1] for i in range(len(nums) - 1)):
        raise ValueError("input list must be sorted ascending")

    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo


if __name__ == "__main__":
    print(search_insert([1, 3, 5, 6], 5))   # 2 (found)
    print(search_insert([1, 3, 5, 6], 2))   # 1 (insert point)
    print(search_insert([1, 3, 5, 6], 7))   # 4 (append)
    print(search_insert([], 4))             # 0 (empty)
