use std::collections::HashMap;

fn fib_upto(n: u32) -> Vec<u128> {
    let mut memo: HashMap<u32, u128> = HashMap::new();
    let mut out = Vec::new();
    for i in 0..=n {
        let v = if i == 0 {
            0
        } else if i == 1 {
            1
        } else {
            memo[&(i - 1)] + memo[&(i - 2)]
        };
        memo.insert(i, v);
        out.push(v);
    }
    out
}

