```cpp
#include <iostream>
#include <utility>
#include <cstdint>

constexpr std::int64_t MOD = 1000000007;

std::pair<std::int64_t, std::int64_t> fib_pair(std::int64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    std::int64_t c = a * ((2 * b % MOD - a + MOD) % MOD) % MOD;
    std::int64_t d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1) return {d, (c + d) % MOD};
    return {c, d};
}

int main() {
    std::cout << fib_pair(0).first << '\n';
    std::cout << fib_pair(10).first << '\n';
    std::cout << fib_pair(90).first << '\n';
    return 0;
}
```

Fast doubling is O(log n) and keeps every intermediate reduced mod 1e9+7, so 64-bit arithmetic never overflows. `n=0` returns 0 via the base case; `n=90` would overflow the un-reduced Fibonacci but is fine under the modulus. Recursion depth is about 63 for any 64-bit n.

