pub fn longest_common_prefix(words: &[String]) -> String {
    let mut iter = words.iter();
    let first = match iter.next() {
        Some(w) => w,
        None => return String::new(),
    };
    let mut end = first.len();
    for word in iter {
        let n = first
            .bytes()
            .zip(word.bytes())
            .take_while(|(a, b)| a == b)
            .count();
        end = end.min(n);
        if end == 0 {
            break;
        }
    }
    first[..end].to_string()
}

