                    if not head:
                        totals['empty'] += os.path.getsize(path)
                        continue
                totals[f'{head[0]:02x}'] += os.path.getsize(path)
            except OSError:
                continue  # permission denied, broken symlink, race with deletion
    return dict(totals)

