#include <cstdio>
#include <functional>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<long long> lower;                                  // max-heap
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> upper;  // min-heap

    long long x;
    bool first = true;
    while (std::cin >> x) {
        // Insert into the correct half.
        if (lower.empty() || x <= lower.top()) {
            lower.push(x);
        } else {
            upper.push(x);
        }
        // Rebalance so sizes differ by at most one and lower.size() >= upper.size().
        if (lower.size() > upper.size() + 1) {
            upper.push(lower.top());
            lower.pop();
        } else if (upper.size() > lower.size()) {
            lower.push(upper.top());
            upper.pop();
        }

        double median;
        if (lower.size() == upper.size()) {
            median = (lower.top() + upper.top()) / 2.0;
        } else {
            median = static_cast<double>(lower.top());
        }

        if (!first) std::cout << '\n';
        first = false;
        std::cout << median;
    }
    return 0;
}
```

`lower` holds the smaller half as a max-heap so `lower.top()` is the largest of those; `upper` holds the larger half as a min-heap. Keeping their sizes within one element makes the median read off the heap tops. Compile with `g++ -std=c++17 -O2 medians.cpp -o medians`.

