use std::collections::HashMap;
use std::fmt;

#[derive(Debug, PartialEq)]
pub enum ParseError {
    MissingEquals(String),
    EmptyKey,
    DuplicateKey(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::MissingEquals(item) => write!(f, "entry '{}' has no '='", item),
            ParseError::EmptyKey => write!(f, "found an entry with an empty key"),
            ParseError::DuplicateKey(k) => write!(f, "duplicate key '{}'", k),
        }
    }
}

pub fn parse_config(line: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    for item in line.split(';') {
        let item = item.trim();
        if item.is_empty() {
            continue;
        }
        let (key, value) = match item.split_once('=') {
            Some((k, v)) => (k.trim(), v.trim()),
            None => return Err(ParseError::MissingEquals(item.to_string())),
        };
        if key.is_empty() {
            return Err(ParseError::EmptyKey);
        }
        if map.insert(key.to_string(), value.to_string()).is_some() {
            return Err(ParseError::DuplicateKey(key.to_string()));
        }
    }
    Ok(map)
}

fn main() {
    let ok = parse_config("host=localhost ; port = 8080; debug=true").unwrap();
    assert_eq!(ok["host"], "localhost");
    assert_eq!(ok["port"], "8080");
    assert_eq!(ok["debug"], "true");

    assert_eq!(
        parse_config("a=1; a=2"),
        Err(ParseError::DuplicateKey("a".to_string()))
    );
    assert!(parse_config("oops").is_err());
    assert_eq!(parse_config("").unwrap().len(), 0);
    println!("all tests passed");
}
```

`split_once('=')` keeps values that themselves contain `=`. Empty segments between semicolons are skipped, and `HashMap::insert` returns the previous value, which is exactly what duplicate detection needs.

```c
#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* Reverse `s` in place. Returns `s` (NULL if `s` is NULL). */
char *reverse_string(char *s) {
    if (s == NULL) {
        return NULL;
    }
    size_t len = strlen(s);
    if (len < 2) {
        return s;  /* empty or single character: nothing to do */
    }
    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
    return s;
}

int main(void) {
    char a[] = "hello";
    puts(reverse_string(a));                  /* olleh */

    char b[] = "";
    puts(reverse_string(b));                  /* empty line */

    char c[] = "x";
    puts(reverse_string(c));                  /* x */

    if (reverse_string(NULL) != NULL) {
        return 1;
    }

    /* Even length exercises the i < j midpoint condition. */
    char d[] = "abba";
    puts(reverse_string(d));                  /* abba */
    return 0;
}
```

Note the array declarations: `char a[] = "hello"` gives a mutable buffer, whereas `char *a = "hello"` points at read-only storage and would crash on write. The swap loop stops at `i < j`, so the middle character of an odd-length string is left alone.

```cpp
#include <cstdio>
#include <stdexcept>
#include <string>
#include <utility>

class FileHandle {
public:
    FileHandle() noexcept : fp_(nullptr) {}

    explicit FileHandle(const char* path, const char* mode) {
        fp_ = std::fopen(path, mode);
        if (fp_ == nullptr) {
            throw std::runtime_error(std::string("cannot open file: ") + path);
        }
    }

    ~FileHandle() { reset(); }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fp_(other.fp_) {
        other.fp_ = nullptr;
    }

    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            reset();
            fp_ = other.fp_;
            other.fp_ = nullptr;
        }
        return *this;
    }

    FILE* get() const noexcept { return fp_; }
    explicit operator bool() const noexcept { return fp_ != nullptr; }

    void reset() noexcept {
        if (fp_ != nullptr) {
            std::fclose(fp_);
            fp_ = nullptr;
        }
    }

private:
    FILE* fp_;
};

int main() {
    try {
        FileHandle f("scratch.txt", "w");
        std::fputs("hello\n", f.get());

        FileHandle moved = std::move(f);
        if (f) {
            return 1;  // moved-from handle must be empty
        }
        moved.reset();
    } catch (const std::exception& e) {
        std::fprintf(stderr, "%s\n", e.what());
        return 1;
    }

    // Opening a nonexistent path in read mode should throw, not leak.
    try {
        FileHandle bad("does-not-exist-xyz.tmp", "r");
        return 1;
    } catch (const std::runtime_error&) {
    }
    return 0;
}
```

`reset()` is idempotent and is called both by the destructor and on move-assign, so the file is closed exactly once. Deleting the copy operations prevents two handles owning the same `FILE*`.

