use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        // Trim surrounding punctuation, then lowercase for case-insensitive counting.
        let cleaned: String = word
            .trim_matches(|c: char| !c.is_alphanumeric())
            .to_lowercase();
        if cleaned.is_empty() {
            continue;
        }
        *counts.entry(cleaned).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count descending, then alphabetically for a stable result.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The cat sat; the CAT saw a dog. A DOG!";
    let top = top_words(text, 2);
    assert_eq!(top.len(), 2);
    assert_eq!(top[0], ("a".to_string(), 2));
    assert_eq!(top[1], ("cat".to_string(), 2));

    let none = top_words("   ", 5);
    assert!(none.is_empty());

    let single = top_words("hello", 10);
    assert_eq!(single, vec![("hello".to_string(), 1)]);
    println!("all tests passed");
}
```

`trim_matches` strips punctuation only at the edges, so `sat;` becomes `sat`. The tie-break by name means `a` and `cat` (both count 2) come out in a deterministic order, which the assertion relies on.

