/* Reverse only half the digits to avoid any overflow risk. */
bool is_palindrome(unsigned long long n) {
    if (n < 10) {
        return true;  /* single digit is always a palindrome */
    }
    if (n % 10 == 0) {
        return false;  /* trailing zero means the reverse cannot match */
    }

    unsigned long long reversed = 0;
    while (n > reversed) {
        reversed = reversed * 10 + (n % 10);
        n /= 10;
    }
    /* Even digit count: n == reversed. Odd digit count: n == reversed / 10. */
    return n == reversed || n == reversed / 10;
}

int main(void) {
    struct { unsigned long long value; bool expected; } cases[] = {
        {0ULL, true},
        {7ULL, true},
        {10ULL, false},
        {121ULL, true},
        {1221ULL, true},
        {12321ULL, true},
        {12345ULL, false},
        {1000000001ULL, true},
        {ULLONG_MAX, false},
    };

    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; ++i) {
        bool got = is_palindrome(cases[i].value);
        if (got != cases[i].expected) {
            printf("FAIL: %llu -> %d, expected %d\n",
                   cases[i].value, (int)got, (int)cases[i].expected);
            return 1;
        }
    }
    puts("all tests passed");
    return 0;
}
```

Only half the digits are reversed, so `reversed` can never exceed `n` in magnitude and no `unsigned long long` overflow occurs. The early trailing-zero check handles numbers like `10` that would otherwise pass the halving comparison by accident.

