```cpp
#include <cstddef>
#include <optional>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : buf_(capacity), cap_(capacity) {}

    void push(const T& value) {
        buf_[head_] = value;
        head_ = (head_ + 1) % cap_;
        if (size_ < cap_) ++size_;
    }

    std::vector<T> snapshot() const {
        std::vector<T> out;
        out.reserve(size_);
        std::size_t start = (head_ + cap_ - size_) % cap_;
        for (std::size_t i = 0; i < size_; ++i)
            out.push_back(buf_[(start + i) % cap_]);
        return out;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<T> buf_;
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

#include <cassert>
int main() {
    RingBuffer<int> rb(3);
    rb.push(1); rb.push(2); rb.push(3);
    assert((rb.snapshot() == std::vector<int>{1, 2, 3}));
    rb.push(4);
    assert((rb.snapshot() == std::vector<int>{2, 3, 4}));
    assert(rb.size() == 3);
    return 0;
}
```
