```rust
pub fn binary_search<T: Ord>(slice: &[T], needle: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(needle) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::binary_search;

    #[test]
    fn finds_and_misses() {
        let data = [1, 3, 5, 7, 9];
        assert_eq!(binary_search(&data, &3), Some(1));
        assert_eq!(binary_search(&data, &9), Some(4));
        assert_eq!(binary_search(&data, &2), None);
        let empty: [i32; 0] = [];
        assert_eq!(binary_search(&empty, &0), None);
    }
}
```
`lo + (hi - lo) / 2` avoids the overflow that `(lo + hi) / 2` can hit on large slices. The half-open range `[lo, hi)` means an empty slice falls straight through to `None`, and each branch strictly shrinks the range so the loop always terminates.

