Here's a clean two-pass reversal: reverse the whole list of characters, then reverse each word within it. Punctuation stays attached to its word since we only split on spaces.

```python
def reverse_words(chars: list[str]) -> None:
    """Reverse word order in a char list, in place, O(1) extra space."""
    def reverse(lo: int, hi: int) -> None:
        while lo < hi:
            chars[lo], chars[hi] = chars[hi], chars[lo]
            lo += 1
            hi -= 1

    if not chars:
        return

    # Pass 1: reverse the entire buffer.
    reverse(0, len(chars) - 1)

    # Pass 2: reverse each word back to normal orientation.
    word_start = None
    for i, ch in enumerate(chars):
        if ch == ' ':
            if word_start is not None:
                reverse(word_start, i - 1)
                word_start = None
        elif word_start is None:
            word_start = i
    if word_start is not None:
        reverse(word_start, len(chars) - 1)


if __name__ == "__main__":
    tests = [
        "hello world",
        "  leading and trailing  ",
        "one",
        "",
        "Hi, there!",
        "a  b   c",
    ]
    for s in tests:
        buf = list(s)
        reverse_words(buf)
        out = "".join(buf)
        print(repr(s), "->", repr(out))
```

The second pass only reverses the letters of each word, preserving original spacing and punctuation. Empty input and single-word strings fall straight out of the logic.

