```rust
/// Returns the longest common prefix of all strings in `words`.
/// Returns an empty string for an empty slice.
pub fn longest_common_prefix(words: &[String]) -> String {
    let first = match words.first() {
        Some(w) => w,
        None => return String::new(),
    };

    let mut end = first.len();
    for word in &words[1..] {
        // Compare on char boundaries to avoid slicing through a UTF-8 char.
        let mut i = 0;
        let mut prefix_len = 0;
        for (a, b) in first.chars().zip(word.chars()) {
            if a != b {
                break;
            }
            prefix_len += a.len_utf8();
            i += 1;
        }
        if prefix_len < end {
            end = prefix_len;
        }
        if end == 0 {
            return String::new();
        }
    }

    first[..end].to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn v(items: &[&str]) -> Vec<String> {
        items.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn basic() {
        assert_eq!(longest_common_prefix(&v(&["flower", "flow", "flight"])), "fl");
    }

    #[test]
    fn none_shared() {
        assert_eq!(longest_common_prefix(&v(&["dog", "racecar", "car"])), "");
    }

    #[test]
    fn empty_slice() {
        assert_eq!(longest_common_prefix(&v(&[])), "");
    }

    #[test]
