```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity) {}

    bool push(double v) {
        if (size_ == cap_) return false;
        buf_[(head_ + size_) % cap_] = v;
        sum_ += v;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) return std::nullopt;
        double v = buf_[head_];
        head_ = (head_ + 1) % cap_;
        sum_ -= v;
        --size_;
        return v;
    }

    double average() const {
        return size_ == 0 ? 0.0 : sum_ / static_cast<double>(size_);
    }

    std::size_t size() const { return size_; }

private:
    std::vector<double> buf_;
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
    double sum_ = 0.0;
};

int main() {
    RingBuffer rb(3);
    for (double v : {1.0, 2.0, 3.0, 4.0}) {
        std::cout << "push " << v << " -> " << (rb.push(v) ? "ok" : "full") << "\n";
    }
    std::cout << "average=" << rb.average() << "\n";
    while (auto v = rb.pop()) {
        std::cout << "pop " << *v << " -> average=" << rb.average() << "\n";
    }
}
```

A full buffer rejects pushes rather than silently overwriting; use a second variant if you want overwrite semantics. The `sum_` field gives O(1) `average()`. The demo prints `push 4.0 -> full` and ends with an empty buffer average of 0.

