import csv
import json
import sys


def csv_to_json(rows: list[dict[str, str]]) -> str:
    """Serialize cleaned rows to indented JSON."""
    cleaned = []
    for row in rows:
        out = {}
        for key, value in row.items():
            if key is None:  # csv adds None key for ragged rows
                continue
            out[key.strip()] = value.strip() if isinstance(value, str) else value
        if any(v != "" for v in out.values()):
            cleaned.append(out)
    return json.dumps(cleaned, indent=2, ensure_ascii=False)


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print(f"usage: {argv[0]} input.csv output.json", file=sys.stderr)
        return 2

    with open(argv[1], newline="", encoding="utf-8-sig") as fh:
        reader = csv.DictReader(fh)
        rows = list(reader)

    with open(argv[2], "w", encoding="utf-8") as fh:
        fh.write(csv_to_json(rows))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
