```cpp
#include <cctype>
#include <iostream>
#include <string>

bool is_palindrome(const std::string& s) {
    std::size_t i = 0;
    std::size_t j = s.size();
    while (i < j) {
        if (!std::isalnum(static_cast<unsigned char>(s[i]))) {
            ++i;
        } else if (!std::isalnum(static_cast<unsigned char>(s[j - 1]))) {
            --j;
        } else {
            if (std::tolower(static_cast<unsigned char>(s[i])) !=
                std::tolower(static_cast<unsigned char>(s[j - 1]))) {
                return false;
            }
            ++i;
            --j;
        }
    }
    return true;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_palindrome("A man, a plan, a canal: Panama") << "\n";
    std::cout << is_palindrome("race a car") << "\n";
    std::cout << is_palindrome("") << "\n";
    std::cout << is_palindrome("\u00e9\u00e9") << "\n";
    return 0;
}
```

Two indices walk inward, skipping anything `isalnum` rejects and comparing lowercased bytes. Casting to `unsigned char` keeps `isalnum`/`tolower` defined for negative `char` values, which matters for non-ASCII bytes so the loop never reads out of range.

