```rust
type Link = Option<Box<Node>>;

struct Node {
    value: i32,
    next: Link,
}

fn reverse(mut head: Link) -> Link {
    let mut prev: Link = None;
    while let Some(mut node) = head {
        head = node.next.take();
        node.next = prev;
        prev = Some(node);
    }
    prev
}

fn from_slice(values: &[i32]) -> Link {
    let mut head: Link = None;
    for &v in values.iter().rev() {
        head = Some(Box::new(Node { value: v, next: head }));
    }
    head
}

fn to_vec(mut head: &Link) -> Vec<i32> {
    let mut out = Vec::new();
    while let Some(node) = head {
        out.push(node.value);
        head = &node.next;
    }
    out
}

fn main() {
    assert_eq!(to_vec(&reverse(from_slice(&[1, 2, 3, 4]))), vec![4, 3, 2, 1]);
    assert!(reverse(None).is_none());
    println!("ok");
}
```

Three pointers drive the walk: `head` advances, `node.next` is repointed to `prev`, and `prev` trails. `node.next.take()` pulls the next link out before overwriting `node.next`, so nothing is lost. `None` (empty list) falls straight through the loop and returns `None`.

