#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

#define BUF 4096

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 2;
    }
    FILE *f = fopen(argv[1], "r+b");
    if (!f) {
        fprintf(stderr, "open failed: %s\n", strerror(errno));
        return 1;
    }
    if (fseek(f, 0, SEEK_END) != 0) { perror("seek"); fclose(f); return 1; }
    long size = ftell(f);
    if (size < 0) { perror("tell"); fclose(f); return 1; }

    unsigned char a[BUF], b[BUF];
    for (long i = 0, j = size - 1; i < j; i++, j--) {
        long ib = i % BUF, jb = j % BUF;
        if (fseek(f, i, SEEK_SET) || fread(a + ib, 1, 1, f) != 1) { perror("read"); fclose(f); return 1; }
        if (fseek(f, j, SEEK_SET) || fread(b + jb, 1, 1, f) != 1) { perror("read"); fclose(f); return 1; }
        if (fseek(f, i, SEEK_SET) || fwrite(b + jb, 1, 1, f) != 1) { perror("write"); fclose(f); return 1; }
        if (fseek(f, j, SEEK_SET) || fwrite(a + ib, 1, 1, f) != 1) { perror("write"); fclose(f); return 1; }
    }
    fclose(f);
    return 0;
}
