#include <iostream>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
        else tail_ = (tail_ + 1) % N;
    }

    const T& front() const {
        if (size_ == 0) throw std::out_of_range("empty");
        return data_[tail_];
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int i = 1; i <= 5; ++i) rb.push(i);
    std::cout << rb.size() << " " << rb.front() << "\n";  // 3 3
    return 0;
}
```
The buffer overwrites the oldest element once full, so after pushing 1..5 into a size-3 buffer the live window is 3,4,5 and `front()` is 3. `front()` on an empty buffer throws rather than reading garbage.

