class ScopedTimer {
public:
    explicit ScopedTimer(const char* label) : label_(label), start_(clock::now()) {}

    ~ScopedTimer() {
        auto ms = std::chrono::duration_cast<std::chrono::milliseconds>
                  (clock::now() - start_).count();
        std::printf("%s: %lld ms\n", label_, static_cast<long long>(ms));
    }

    ScopedTimer(const ScopedTimer&) = delete;
    ScopedTimer& operator=(const ScopedTimer&) = delete;

private:
    using clock = std::chrono::steady_clock;
    const char* label_;
    clock::time_point start_;
};

int main() {
    ScopedTimer t("loop");
    volatile long long sum = 0;
    for (int i = 0; i < 1000000; ++i) sum += i;
    (void)sum;
    return 0;
}
```
`steady_clock` is monotonic, so it is safe for measuring durations. The destructor prints at scope exit, and the copy operations are deleted so a timer cannot be duplicated and printed twice.

