```rust
use std::cmp::Ordering;

fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let (mut lo, mut hi) = (0usize, slice.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            Ordering::Equal => return Some(mid),
            Ordering::Less => lo = mid + 1,
            Ordering::Greater => hi = mid,
        }
    }
    None
}

fn main() {
    let data = [1, 3, 5, 7, 9, 11];
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &11), Some(5));
    assert_eq!(binary_search(&data, &6), None);
    let empty: [i32; 0] = [];
    assert_eq!(binary_search(&empty, &1), None);
    println!("{:?}", binary_search(&data, &7));
}
```
`mid = lo + (hi - lo) / 2` avoids the overflow that `(lo + hi) / 2` can hit on large slices. The half-open range `[lo, hi)` makes the loop terminate correctly even for empty input.

