from typing import Sequence


def lower_bound(a: Sequence[int], target: int) -> int:
    """Return the first index i where a[i] == target, or -1 if absent.

    Requires a to be sorted ascending.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    if lo < len(a) and a[lo] == target:
        return lo
    return -1


