#include <string>

bool is_balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{': st.push(c); break;
            case ')':
                if (st.empty() || st.top() != '(') return false;
                st.pop(); break;
            case ']':
                if (st.empty() || st.top() != '[') return false;
                st.pop(); break;
            case '}':
                if (st.empty() || st.top() != '{') return false;
                st.pop(); break;
            default: break;
        }
    }
    return st.empty();
}

int main() {
    const char* tests[] = {"", "()", "([{}])", "(]", "((()"};
    for (const char* t : tests)
        std::cout << t << " -> " << (is_balanced(t) ? "balanced" : "unbalanced") << '\n';
    return 0;
}
