```python
class MinHeap:
    def __init__(self):
        self._data = []

    def push(self, value):
        self._data.append(value)
        self._sift_up(len(self._data) - 1)

    def pop(self):
        if not self._data:
            raise IndexError("pop from empty heap")
        root = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            self._sift_down(0)
        return root

    def _sift_up(self, i):
        while i > 0:
            parent = (i - 1) // 2
            if self._data[i] >= self._data[parent]:
                break
            self._data[i], self._data[parent] = self._data[parent], self._data[i]
            i = parent

    def _sift_down(self, i):
        n = len(self._data)
        while True:
            left, right, smallest = 2 * i + 1, 2 * i + 2, i
            if left < n and self._data[left] < self._data[smallest]:
                smallest = left
            if right < n and self._data[right] < self._data[smallest]:
                smallest = right
            if smallest == i:
                return
            self._data[i], self._data[smallest] = self._data[smallest], self._data[i]
            i = smallest


if __name__ == "__main__":
    import random
    heap = MinHeap()
    values = [random.randint(-50, 50) for _ in range(200)]
    for v in values:
        heap.push(v)
    out = [heap.pop() for _ in range(len(values))]
    assert out == sorted(values)
    try:
        MinHeap().pop()
    except IndexError:
        pass
    else:
        raise AssertionError("empty pop should raise")
    print("ok")
```

