    size_t i = 0, j = s.size();
    while (i < j) {
        if (j == 0) return true;
        --j;
        unsigned char a = static_cast<unsigned char>(s[i]);
        unsigned char b = static_cast<unsigned char>(s[j]);
        if (!std::isalnum(a)) { ++i; ++j; continue; }
