#include <array>
#include <cstddef>
#include <optional>
#include <cstdio>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    bool ok = rb.push(4);        // false, full
    while (auto v = rb.pop()) std::printf("%d ", *v);
    std::printf("\nfull-reject=%d\n", ok);
    return 0;
}
```

