enum PortError {
    Empty,
    NotANumber,
    OutOfRange(u32),
}

impl fmt::Display for PortError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PortError::Empty => write!(f, "port string is empty"),
            PortError::NotANumber => write!(f, "port is not a number"),
            PortError::OutOfRange(n) => write!(f, "port {n} is outside 1..=65535"),
        }
    }
