fn parse_port(s: &str) -> Result<u16, PortError> {
    let t = s.trim();
    if t.is_empty() {
        return Err(PortError::Empty);
    }
    let n: u32 = t.parse().map_err(|_| PortError::NotANumber)?;
    if n == 0 || n > 65_535 {
        return Err(PortError::OutOfRange(n));
    }
    Ok(n as u16)
}

fn main() {
    assert_eq!(parse_port("8080"), Ok(8080));
    assert_eq!(parse_port(" 443 "), Ok(443));
    assert_eq!(parse_port(""), Err(PortError::Empty));
    assert_eq!(parse_port("abc"), Err(PortError::NotANumber));
    assert_eq!(parse_port("70000"), Err(PortError::OutOfRange(70000)));
    println!("ok");
}
