#define MOD 1000000007ULL

static unsigned long long fib_mod(unsigned long long n) {
    unsigned long long a = 0, b = 1;
    for (unsigned long long i = 0; i < n; ++i) {
        unsigned long long next = (a + b) % MOD;
        a = b;
        b = next;
    }
    return a;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <n>\n", argv[0]);
        return 1;
    }
    char *end = NULL;
    unsigned long long n = strtoull(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0') {
        fprintf(stderr, "not a number: %s\n", argv[1]);
        return 1;
    }
    printf("%llu\n", fib_mod(n));
    return 0;
}
```

`a + b` stays below `2 * MOD`, so the `%` never overflows a 64-bit value. `strtoull` plus the `*end` check rejects partial parses like `12abc`, and the loop uses O(1) memory.

