    size_t i = 0, j = s.size();
    while (i < j && i < --j) {
        std::swap(s[i++], s[j]);
    }
}

int main() {
    std::string a = "hello";
    reverse_in_place(a);
    std::cout << a << "\n";          // olleh

    std::string b = "";               // empty
    reverse_in_place(b);
    std::cout << "[" << b << "]\n";  // []

    // byte-reverse; may split multi-byte UTF-8 sequences
    std::string c = "a\xC3\xA9";      // "ae" ascii + e-acute
    reverse_in_place(c);
    std::cout << c.size() << " bytes\n";
    return 0;
