#[derive(Debug)]
pub struct RingBuffer {
    buf: Vec<i32>,
    cap: usize,
    write: usize,
    count: usize,
}

impl RingBuffer {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        RingBuffer { buf: vec![0; cap], cap, write: 0, count: 0 }
    }

    pub fn push(&mut self, v: i32) {
        self.buf[self.write] = v;
        self.write = (self.write + 1) % self.cap;
        if self.count < self.cap {
            self.count += 1;
        }
    }

    pub fn len(&self) -> usize { self.count }
    pub fn capacity(&self) -> usize { self.cap }

    pub fn iter(&self) -> impl Iterator<Item = i32> + '_ {
        let start = if self.count == self.cap { self.write } else { 0 };
        (0..self.count).map(move |i| self.buf[(start + i) % self.cap])
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    rb.push(1); rb.push(2); rb.push(3); rb.push(4);
    assert_eq!(rb.len(), 3);
    let v: Vec<i32> = rb.iter().collect();
    assert_eq!(v, vec![2, 3, 4]);
    println!("{:?}", v);
}
