#include <limits.h>
#include <stdbool.h>
#include <stdio.h>

typedef enum { PARSE_OK, PARSE_INVALID, PARSE_OVERFLOW } parse_status;

parse_status parse_long(const char *s, long *out) {
    if (s == NULL || *s == '\0') return PARSE_INVALID;

    bool neg = false;
    if (*s == '+' || *s == '-') {
        neg = (*s == '-');
        ++s;
    }
    if (*s == '\0') return PARSE_INVALID;

    long limit = neg ? LONG_MIN : LONG_MAX;
    long acc = 0;
    for (; *s; ++s) {
        if (*s < '0' || *s > '9') return PARSE_INVALID;
        int digit = *s - '0';
        if (neg) {
            if (acc < (limit + digit) / 10) return PARSE_OVERFLOW;
            acc = acc * 10 - digit;
        } else {
            if (acc > (limit - digit) / 10) return PARSE_OVERFLOW;
            acc = acc * 10 + digit;
        }
    }
    *out = acc;
    return PARSE_OK;
}

int main(void) {
    long v = 0;
    printf("%d\n", parse_long("-42", &v));
    printf("%d\n", parse_long("99999999999999999999", &v));
    printf("%d\n", parse_long("12x", &v));
    return 0;
}
