template <typename T>
T kthSmallest(std::vector<T> v, std::size_t k) {
    if (v.empty() || k == 0 || k > v.size())
        throw std::out_of_range("k out of range");
    std::size_t lo = 0, hi = v.size() - 1, target = k - 1;
    while (true) {
        std::size_t pivot = lo + (hi - lo) / 2;
        std::swap(v[pivot], v[hi]);
        std::size_t store = lo;
        for (std::size_t i = lo; i < hi; ++i)
            if (v[i] < v[hi]) std::swap(v[i], v[store++]);
        std::swap(v[store], v[hi]);
        if (store == target) return v[store];
        if (store < target) lo = store + 1;
        else if (store == 0) return v[0];
        else hi = store - 1;
    }
}

int main() {
    std::vector<int> a{7, 10, 4, 3, 20, 15};
    std::cout << kthSmallest(a, 3) << "\n"; // 7
    std::cout << kthSmallest(a, 1) << "\n"; // 3
    try { kthSmallest(a, 0); } catch (const std::out_of_range& e) { std::cout << e.what() << "\n"; }
}
