#include <queue>
#include <mutex>
#include <condition_variable>
#include <optional>
#include <iostream>

template <typename T>
class BlockingQueue {
    std::queue<T> q_;
    std::mutex m_;
    std::condition_variable cv_;
    bool closed_ = false;
public:
    void push(T value) {
        {
            std::lock_guard<std::mutex> lk(m_);
            if (closed_) throw std::runtime_error("push on closed queue");
            q_.push(std::move(value));
        }
        cv_.notify_one();
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lk(m_);
        cv_.wait(lk, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;
        T v = std::move(q_.front());
        q_.pop();
        return v;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lk(m_);
            closed_ = true;
        }
        cv_.notify_all();
    }
};

int main() {
    BlockingQueue<int> bq;
    bq.push(1);
    bq.push(2);
    bq.close();
    while (auto v = bq.pop()) std::cout << *v << "\n";
    return 0;
}
