    if words.is_empty() {
        return String::new();
    }
    let first = words[0];
    let mut end = first.len();
    for w in &words[1..] {
        let limit = end.min(w.len());
        let mut i = 0;
        while i < limit && first.as_bytes()[i] == w.as_bytes()[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    first[..end].to_string()
