```python
class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._buf = [None] * capacity
        self._count = 0
        self._start = 0

    def append(self, item):
        idx = (self._start + self._count) % self.capacity
        self._buf[idx] = item
        if self._count < self.capacity:
            self._count += 1
        else:
            self._start = (self._start + 1) % self.capacity

    def to_list(self):
        return [self._buf[(self._start + i) % self.capacity]
                for i in range(self._count)]

    def __len__(self):
        return self._count

def main():
    rb = RingBuffer(3)
    for x in ['a', 'π', '中', 'd', 'e']:
        rb.append(x)
    print(rb.to_list())

if __name__ == '__main__':
    main()
```

Elements are stored by reference, so unicode strings pass through untouched. `_start` only advances once the buffer is full, which is what makes the oldest entry fall out; `to_list` walks in logical order regardless of the internal wrap.

```c
#include <stdio.h>
#include <string.h>

void reverse(char *s) {
    size_t n = strlen(s);
    if (n < 2) return;
    for (size_t i = 0, j = n - 1; i < j; ++i, --j) {
        char t = s[i];
        s[i] = s[j];
        s[j] = t;
    }
}

int main(void) {
    char empty[] = "";
    char one[] = "x";
    char word[] = "hello";
    char sentence[] = "a b c";

    reverse(empty);
    reverse(one);
    reverse(word);
    reverse(sentence);

    printf("[%s]\n", empty);
    printf("[%s]\n", one);
    printf("[%s]\n", word);
    printf("[%s]\n", sentence);
    return 0;
}
```

The two-index swap stops at the midpoint, so even- and odd-length strings both work. The `n < 2` guard covers empty and single-character strings without touching them. All string literals are writable arrays, not pointers, so the in-place modification is legal.

