        if (i < 0) break;
        int end = i;
        while (i >= 0 && !std::isspace(static_cast<unsigned char>(sentence[i]))) {
            --i;
        }
        if (!out.empty()) out.push_back(' ');
        out.append(sentence, i + 1, end - i);
