#include <errno.h>
#include <limits.h>
#include <stdlib.h>
#include <string.h>

/* Returns 0 on success and stores the value in *out; -1 on any error. */
int parse_long(const char *text, long *out) {
    if (text == NULL || out == NULL || *text == '\0') {
        return -1;
    }

    errno = 0;
    char *end = NULL;
    long value = strtol(text, &end, 10);

    if (errno == ERANGE || end == text) {
        return -1; /* overflow or no digits */
    }
    while (*end != '\0') {
        if (*end != ' ' && *end != '\t' && *end != '\n') {
            return -1; /* trailing garbage */
        }
        ++end;
    }

    *out = value;
    return 0;
}

int main(void) {
    long v;
    if (parse_long("  -42 ", &v) != 0 || v != -42L) return 1;
    if (parse_long("99999999999999999999", &v) != -1) return 1;
    if (parse_long("12abc", &v) != -1) return 1;
    if (parse_long("", &v) != -1) return 1;
    return 0;
}
