import csv
import math


def column_stats(path: str, column: str):
    """Return (mean, population_stddev, n) for a numeric CSV column."""
    with open(path, newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames is None or column not in reader.fieldnames:
            raise ValueError(f"column not found: {column}")

        values = []
        for row in reader:
            cell = (row.get(column) or "").strip()
            if cell == "":
                continue
            try:
                values.append(float(cell))
            except ValueError:
                raise ValueError(f"non-numeric value in {column}: {cell!r}")

    if not values:
        return (None, None, 0)

    n = len(values)
    mean = sum(values) / n
    variance = sum((v - mean) ** 2 for v in values) / n
    return (mean, math.sqrt(variance), n)


if __name__ == "__main__":
    mean, sd, n = column_stats("data.csv", "score")
    print(f"n={n} mean={mean:.3f} sd={sd:.3f}")
