#include <cstddef>
#include <iostream>
#include <utility>

template <typename T>
class Ref {
    T* ptr_ = nullptr;
    int* count_ = nullptr;

    void release() {
        if (count_ && --(*count_) == 0) {
            delete ptr_;
            delete count_;
        }
        ptr_ = nullptr;
        count_ = nullptr;
    }

public:
    Ref() = default;
    explicit Ref(T* p) : ptr_(p), count_(new int(1)) {}
    Ref(const Ref& o) : ptr_(o.ptr_), count_(o.count_) { if (count_) ++(*count_); }
    Ref& operator=(const Ref& o) {
        if (this != &o) { release(); ptr_ = o.ptr_; count_ = o.count_; if (count_) ++(*count_); }
        return *this;
    }
    ~Ref() { release(); }

    T& operator*() const { return *ptr_; }
    int use_count() const { return count_ ? *count_ : 0; }
};

int main() {
    Ref<int> a(new int(42));
    Ref<int> b = a;
    std::cout << *b << " " << a.use_count() << "\n";
    b = Ref<int>(new int(7));
    std::cout << a.use_count() << "\n";
}
