def longest_common_prefix(strings):
    """Return the longest common prefix of a list of strings.

    Returns '' for an empty list. Raises TypeError if any element is not a str.
    """
    if not isinstance(strings, list):
        raise TypeError("expected a list of strings")
    if not strings:
        return ""
    for s in strings:
        if not isinstance(s, str):
            raise TypeError("all elements must be strings")

    prefix = strings[0]
    for s in strings[1:]:
        # Shrink the candidate prefix until it matches s.
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix


if __name__ == "__main__":
    assert longest_common_prefix(["flower", "flow", "flight"]) == "fl"
    assert longest_common_prefix(["dog", "racecar", "car"]) == ""
    assert longest_common_prefix([]) == ""
    assert longest_common_prefix(["single"]) == "single"
    assert longest_common_prefix(["", "abc"]) == ""
    assert longest_common_prefix(["caf\u00e9", "caf\u00e9teria"]) == "caf\u00e9"
