#include <iostream>
#include <stack>
#include <string>

bool isBalanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top(); st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.empty();
}

int main() {
    std::cout << std::boolalpha;
    std::cout << isBalanced("{[()]}") << '\n';  // true
    std::cout << isBalanced("([)]")   << '\n';  // false
    std::cout << isBalanced("")       << '\n';  // true
    std::cout << isBalanced("(((")    << '\n';  // false
    return 0;
}
