#include <stdexcept>

std::vector<double> parse_doubles(std::string_view input) {
    std::vector<double> out;
    std::size_t i = 0;
    while (i < input.size()) {
        while (i < input.size() &&
               std::isspace(static_cast<unsigned char>(input[i]))) {
            ++i;
        }
        std::size_t start = i;
        while (i < input.size() &&
               !std::isspace(static_cast<unsigned char>(input[i]))) {
            ++i;
        }
        if (start == i) break;
        double value = 0.0;
        auto token = input.substr(start, i - start);
        auto res = std::from_chars(token.data(), token.data() + token.size(),
                                   value, std::chars_format::general);
        if (res.ec == std::errc() && res.ptr == token.data() + token.size()) {
            out.push_back(value);
        }
    }
    return out;
}
