fn fib_checked(n: usize) -> Vec<u64> {
    let mut out = Vec::new();
    if n == 0 {
        return out;
    }
    out.push(0);
    if n == 1 {
        return out;
    }
    out.push(1);
    while out.len() < n {
        let len = out.len();
        match out[len - 1].checked_add(out[len - 2]) {
            Some(next) => out.push(next),
            None => break, // overflow would occur; stop cleanly
        }
    }
    out
}

