```cpp
#include <condition_variable>
#include <functional>
#include <mutex>
#include <optional>
#include <queue>
#include <thread>
#include <vector>
#include <cassert>
#include <cstdio>

class TaskQueue {
public:
    explicit TaskQueue(std::size_t workers)
        : stop_(false) {
        for (std::size_t i = 0; i < workers; ++i) {
            pool_.emplace_back([this] { workerLoop(); });
        }
    }

    TaskQueue(const TaskQueue&) = delete;
    TaskQueue& operator=(const TaskQueue&) = delete;

    ~TaskQueue() {
        {
            std::lock_guard<std::mutex> lock(mu_);
            stop_ = true;
        }
        cv_.notify_all();
        for (auto& t : pool_) {
            if (t.joinable()) t.join();
        }
    }

    void push(std::function<void()> task) {
        {
            std::lock_guard<std::mutex> lock(mu_);
            if (stop_) return;   // refuse work after shutdown
            tasks_.push(std::move(task));
        }
        cv_.notify_one();
    }

private:
    void workerLoop() {
        for (;;) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(mu_);
                cv_.wait(lock, [this] { return stop_ || !tasks_.empty(); });
                if (tasks_.empty()) {
                    if (stop_) return;
                    continue;
                }
                task = std::move(tasks_.front());
                tasks_.pop();
            }
            task();
        }
    }

    std::mutex mu_;
    std::condition_variable cv_;
    std::queue<std::function<void()>> tasks_;
    std::vector<std::thread> pool_;
    bool stop_;
};

int main() {
    TaskQueue q(3);
    std::atomic<int> counter{0};
    for (int i = 0; i < 100; ++i) {
        q.push([&counter] { counter.fetch_add(1, std::memory_order_relaxed); });
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(200));
    assert(counter.load() == 100);
    std::printf("processed %d tasks\n", counter.load());
}
```

The drain logic waits on `stop_ || !tasks_.empty()`, so queued work finishes before threads exit. `push` after shutdown is dropped rather than blocking.

