        const std::string& w = words[i];
        std::size_t maxLen = std::min(prefix.size(), w.size());
        std::size_t j = 0;
        while (j < maxLen && prefix[j] == w[j]) ++j;
        prefix.resize(j);
        if (prefix.empty()) break;
    }
    return prefix;
