    assert(longestCommonPrefix({"dog", "racecar", "car"}) == "");
    assert(longestCommonPrefix({"alone"}) == "alone");
    assert(longestCommonPrefix({}) == "");
    assert(longestCommonPrefix({"", "x"}) == "");
    assert(longestCommonPrefix({"café", "caféteria"}) == "café");
    std::cout << longestCommonPrefix({"ab", "abc", "abcd"}) << "\n";
}
