```rust
use std::collections::HashSet;
use std::hash::Hash;

struct Unique<I: Iterator> {
    inner: I,
    seen: HashSet<I::Item>,
}

impl<I: Iterator> Iterator for Unique<I>
where
    I::Item: Eq + Hash + Clone,
{
    type Item = I::Item;

    fn next(&mut self) -> Option<Self::Item> {
        for item in self.inner.by_ref() {
            if self.seen.insert(item.clone()) {
                return Some(item);
            }
        }
        None
    }
}

trait UniqueExt: Iterator + Sized {
    fn unique(self) -> Unique<Self> {
        Unique { inner: self, seen: HashSet::new() }
    }
}

impl<I: Iterator> UniqueExt for I {}

fn main() {
    let v = vec![3, 1, 3, 2, 1, 4, 4];
    let out: Vec<_> = v.into_iter().unique().collect();
    assert_eq!(out, vec![3, 1, 2, 4]);

    let words = ["a", "b", "a", "c"];
    let uniq: Vec<_> = words.iter().copied().unique().collect();
    assert_eq!(uniq, vec!["a", "b", "c"]);

    let empty: Vec<i32> = Vec::new();
    let none: Vec<_> = empty.into_iter().unique().collect();
    assert!(none.is_empty());

    println!("{:?}", out);
}
```

The adapter is lazy — it pulls from the inner iterator on demand and remembers seen values in a `HashSet`, so an infinite source only allocates for items actually consumed. Order is that of first appearance.

