use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
pub enum ConfigError {
    EmptyKey(String),
    EmptyValue(String),
    MissingEquals(String),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::EmptyKey(l) => write!(f, "empty key on line: {l:?}"),
            ConfigError::EmptyValue(l) => write!(f, "empty value on line: {l:?}"),
            ConfigError::MissingEquals(l) => write!(f, "missing '=' on line: {l:?}"),
        }
    }
}

impl std::error::Error for ConfigError {}

pub fn parse(input: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut map = HashMap::new();
    for raw in input.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (k, v) = line.split_once('=').ok_or_else(|| ConfigError::MissingEquals(line.to_string()))?;
        let key = k.trim();
        let value = v.trim();
        if key.is_empty() {
            return Err(ConfigError::EmptyKey(line.to_string()));
        }
        if value.is_empty() {
            return Err(ConfigError::EmptyValue(line.to_string()));
        }
        map.insert(key.to_string(), value.to_string());
    }
    Ok(map)
}

fn main() {
    let ok = parse("host = localhost\n# comment\nport=8080\n").unwrap();
    assert_eq!(ok.get("host").map(String::as_str), Some("localhost"));
    assert_eq!(ok.get("port").map(String::as_str), Some("8080"));

    assert!(parse("novalue").is_err());
    assert!(parse("key=").is_err());
    assert!(parse("=val").is_err());

    println!("parsed {} entries", ok.len());
}
```

Each failure mode has its own variant so callers can match instead of string-matching an error. Comments and blank lines are skipped rather than treated as errors.

```c
#include <stdarg.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char  *data;
    size_t len;
    size_t cap;
    bool   oom;
} StrBuf;

static bool sb_reserve(StrBuf *sb, size_t extra) {
    if (sb->oom) return false;
    if (extra > SIZE_MAX - sb->len - 1) {   /* would overflow the +1 for NUL */
        sb->oom = true;
        return false;
    }
    size_t need = sb->len + extra + 1;
    if (need <= sb->cap) return true;

    size_t cap = sb->cap ? sb->cap : 32;
    while (cap < need) {
        if (cap > SIZE_MAX / 2) { cap = need; break; }
        cap *= 2;
    }
    char *p = realloc(sb->data, cap);
    if (!p) { sb->oom = true; return false; }
    sb->data = p;
    sb->cap = cap;
    return true;
}

bool sb_append(StrBuf *sb, const char *s, size_t n) {
    if (!sb_reserve(sb, n)) return false;
    memcpy(sb->data + sb->len, s, n);
    sb->len += n;
    sb->data[sb->len] = '\0';
    return true;
}

bool sb_puts(StrBuf *sb, const char *s) {
    return sb_append(sb, s, strlen(s));
}

bool sb_printf(StrBuf *sb, const char *fmt, ...) {
    va_list ap, ap2;
    va_start(ap, fmt);
    va_copy(ap2, ap);
    int n = vsnprintf(NULL, 0, fmt, ap);
    va_end(ap);
    if (n < 0 || !sb_reserve(sb, (size_t)n)) { va_end(ap2); return false; }
    vsnprintf(sb->data + sb->len, sb->cap - sb->len, fmt, ap2);
    va_end(ap2);
    sb->len += (size_t)n;
    return true;
}

void sb_free(StrBuf *sb) {
    free(sb->data);
    sb->data = NULL;
    sb->len = sb->cap = 0;
}

int main(void) {
    StrBuf sb = {0};
    sb_puts(&sb, "items: ");
    for (int i = 0; i < 3; ++i) {
        char buf[16];
        snprintf(buf, sizeof buf, "%d", i);
        sb_puts(&sb, buf);
        if (i != 2) sb_puts(&sb, ", ");
    }
    sb_printf(&sb, " | len=%zu", sb.len);
    puts(sb.data);

    if (sb.oom) {
        fputs("allocation failed\n", stderr);
        sb_free(&sb);
        return 1;
    }
    sb_free(&sb);
    return 0;
}
```

`sb_reserve` checks the `len + extra + 1` sum before it overflows, and the growth loop clamps instead of doubling past `SIZE_MAX`. Every append path sets `oom` rather than silently dropping bytes.

