    pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    pairs.truncate(3);
    pairs
}

fn main() {
    assert_eq!(top_three("aabbbcc"), vec![('b', 3), ('a', 2), ('c', 2)]);
    assert_eq!(top_three(""), Vec::new());
    assert_eq!(top_three("xy"), vec![('x', 1), ('y', 1)]);
    println!("{:?}", top_three("hello world"));
}
```

The sort key puts higher counts first and, on a tie, the smaller `char` first, which is why `a` precedes `c` in the second assertion.

```python
class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = [None] * capacity
        self._head = 0
        self._size = 0

    def __len__(self):
        return self._size

    def push(self, value):
        """Append, evicting the oldest item when full."""
        index = (self._head + self._size) % self.capacity
        self._data[index] = value
        if self._size == self.capacity:
            self._head = (self._head + 1) % self.capacity
        else:
            self._size += 1

    def pop(self):
        """Remove and return the oldest item."""
        if self._size == 0:
            raise IndexError("pop from empty ring buffer")
        value = self._data[self._head]
        self._data[self._head] = None
        self._head = (self._head + 1) % self.capacity
        self._size -= 1
        return value


if __name__ == "__main__":
    rb = RingBuffer(3)
    for v in (1, 2, 3):
        rb.push(v)
    assert len(rb) == 3
    rb.push(4)  # evicts 1
    assert len(rb) == 3
    assert [rb.pop(), rb.pop(), rb.pop()] == [2, 3, 4]
    assert len(rb) == 0
    try:
        rb.pop()
    except IndexError:
        pass
    else:
        raise AssertionError("expected IndexError")
    print("all checks passed")
```

When full, `push` advances the head before incrementing size stays at capacity, so the oldest value is overwritten.

