#include <iostream>
#include <vector>

// Returns the index of target in sorted v, or -1 if absent.
// Uses a half-open [lo, hi) range to avoid overflow in mid.
int binary_search_index(const std::vector<int>& v, int target) {
    std::size_t lo = 0, hi = v.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (v[mid] == target) return static_cast<int>(mid);
        if (v[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return -1;
}

int main() {
    const std::vector<int> v{1, 3, 3, 5, 7, 9, 11};
    struct Case { int target; int want; };
    const Case cases[] = {
        {1, 0}, {3, 2}, {11, 6}, {7, 4}, {0, -1}, {4, -1}, {12, -1}
    };

    for (const auto& c : cases) {
        int got = binary_search_index(v, c.target);
        std::cout << "search(" << c.target << ") = " << got
                  << (got == c.want ? "  ok" : "  FAIL") << '\n';
        if (got != c.want) return 1;
    }

    // Empty vector: always -1, never reads memory.
    std::vector<int> empty;
    std::cout << "empty search(5) = " << binary_search_index(empty, 5) << '\n';
    return 0;
}
