```cpp
#include <cstdio>
#include <stdexcept>
#include <string>

class File {
    std::FILE* f_ = nullptr;
public:
    explicit File(const std::string& path, const char* mode = "r") {
        f_ = std::fopen(path.c_str(), mode);
        if (!f_) throw std::runtime_error("cannot open " + path);
    }
    ~File() { if (f_) std::fclose(f_); }

    File(const File&) = delete;            // no copies
    File& operator=(const File&) = delete;

    File(File&& o) noexcept : f_(o.f_) { o.f_ = nullptr; }  // move only
    File& operator=(File&& o) noexcept {
        if (this != &o) { if (f_) std::fclose(f_); f_ = o.f_; o.f_ = nullptr; }
        return *this;
    }

    std::FILE* get() const { return f_; }
};

int main() {
    File f("/etc/hostname");
    char buf[256];
    if (std::fgets(buf, sizeof buf, f.get())) std::printf("%s", buf);
    return 0;
}
```

Deleting the copy operations prevents double-close, and the move constructor nulls the source so only one owner ever holds the handle. The destructor runs on stack unwind even if `fgets` throws.

