```python
def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring of s (expand around center)."""
    if not s:
        return ""

    best_start = 0
    best_len = 1

    def expand(lo: int, hi: int):
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        # loop stops one step too far; trim back
        return lo + 1, hi - lo - 1

    for i in range(len(s)):
        # odd-length centers
        start, length = expand(i, i)
        if length > best_len:
            best_start, best_len = start, length
        # even-length centers
        start, length = expand(i, i + 1)
        if length > best_len:
            best_start, best_len = start, length

    return s[best_start:best_start + best_len]


if __name__ == "__main__":
    cases = ["", "a", "bb", "forgeeksskeegfor", "cbbd", "abcda"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```

Expanding from each of the `2n-1` centers runs in O(n²) time and O(1) extra space. The `expand` helper walks outward while characters match, then backs off by one so the returned slice is the actual palindrome window.

```cpp
#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* mergeSorted(Node* a, Node* b) {
    Node dummy(0);
    Node* tail = &dummy;
    while (a != nullptr && b != nullptr) {
        if (a->value <= b->value) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = (a != nullptr) ? a : b;
    return dummy.next;
}

Node* fromRange(const int* arr, std::size_t n) {
    Node* head = nullptr;
    Node** tail = &head;
    for (std::size_t i = 0; i < n; ++i) {
        *tail = new Node(arr[i]);
        tail = &((*tail)->next);
    }
    return head;
}

void destroy(Node* head) {
    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    const int lhs[] = {1, 4, 7, 9};
    const int rhs[] = {2, 3, 8, 10, 11};
    Node* a = fromRange(lhs, 4);
    Node* b = fromRange(rhs, 5);

    Node* merged = mergeSorted(a, b);
    for (Node* cur = merged; cur != nullptr; cur = cur->next) {
        std::cout << cur->value << (cur->next ? " " : "\n");
    }

    destroy(merged);
    return 0;
}
```

The merge reuses the existing nodes rather than allocating copies, so destroying the merged head frees both input lists. Stable through the `<=` comparison, and the `dummy` node keeps the tail-pointer logic branch-free.

```rust
use std::collections::HashMap;

/// Split on Unicode whitespace, lowercase each word, count, and return the
/// top `n` entries by count (ties broken alphabetically).
pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let key: String = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if key.is_empty() {
            continue;
        }
        *counts.entry(key).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The quick fox; the FOX jumped, over the lazy dog. Дом дом";
    for (word, count) in top_words(text, 3) {
        println!("{word}: {count}");
    }
}
```

`split_whitespace` already handles Unicode spaces. The `flat_map(|c| c.to_lowercase())` step is what makes this Unicode-correct: a character like `İ` lowercases to two code points, so we can't map one char to one char. Sorting by count descending with an alphabetical tiebreak keeps the output deterministic.

