`scanf` skips leading whitespace and stops at the first non-numeric character, returning 0 or EOF, so the loop exits cleanly on junk. The `count == 0 ||` guards matter because `LLONG_MAX` would otherwise beat any real minimum on the first read. `sum` is `long long` to delay overflow, though it can still overflow on huge inputs; a full fix would accumulate as `long double`.

```python
import threading
from collections import deque


class BoundedQueue:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._items = deque()
        self._lock = threading.Lock()
        self._not_empty = threading.Condition(self._lock)
        self._not_full = threading.Condition(self._lock)

    def put(self, item, timeout=None) -> bool:
        with self._not_full:
            if not self._not_full.wait_for(
                lambda: len(self._items) < self._capacity, timeout
            ):
                return False
            self._items.append(item)
            self._not_empty.notify()
            return True

    def get(self, timeout=None):
        with self._not_empty:
            if not self._not_empty.wait_for(
                lambda: len(self._items) > 0, timeout
            ):
                return None, False
            item = self._items.popleft()
            self._not_full.notify()
            return item, True

    def size(self) -> int:
        with self._lock:
            return len(self._items)
```

Both conditions share one lock, so a `put` wake-up can't race a `get` wake-up. `wait_for` takes a timeout, so a blocked producer or consumer returns `False` instead of hanging forever; `get` returns an `(item, ok)` pair so `None` is a valid payload. `notify()` (not `notify_all`) suffices because each space/slot wakes exactly one waiter.

```rust
use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
pub struct IniError {
    pub line: usize,
    pub message: String,
}

impl fmt::Display for IniError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "line {}: {}", self.line, self.message)
    }
}

pub fn parse_ini(input: &str) -> Result<HashMap<String, HashMap<String, String>>, IniError> {
    let mut sections: HashMap<String, HashMap<String, String>> = HashMap::new();
    let mut current: Option<String> = None;

    for (idx, raw) in input.lines().enumerate() {
        let line_no = idx + 1;
        let line = raw.trim();
        if line.is_empty() || line.starts_with(';') || line.starts_with('#') {
            continue;
        }
        if let Some(name) = line.strip_prefix('[').and_then(|s| s.strip_suffix(']')) {
            let name = name.trim();
            if name.is_empty() {
                return Err(IniError { line: line_no, message: "empty section name".into() });
            }
            sections.entry(name.to_string()).or_default();
            current = Some(name.to_string());
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            return Err(IniError { line: line_no, message: format!("not a key=value line: {line}") });
        };
        let Some(section) = current.as_ref() else {
            return Err(IniError { line: line_no, message: format!("key outside any section: {key}") });
        };
        sections
            .get_mut(section)
            .unwrap()
            .insert(key.trim().to_string(), value.trim().to_string());
    }
    Ok(sections)
}

fn main() {
    let cfg = "[server]\nhost = localhost  ; comment\nport=8080\n\n# section\n[db]\nname = app";
    match parse_ini(cfg) {
        Ok(map) => {
            for (section, kv) in &map {
                println!("[{section}] {kv:?}");
            }
        }
        Err(e) => eprintln!("error: {e}"),
    }
}
```

`split_once('=')` keeps the first `=` as the separator so values may contain `=`. Inline comments are *not* stripped here — I kept the parser honest to the spec you gave; add `line.split(';').next()` before `split_once` if you want them. Errors carry a 1-based line number so the message points at the right spot.

```cpp
#include <array>
#include <cstddef>
#include <stdexcept>

namespace xt {

template <typename T, std::size_t N>
class RingBuffer {
    static_assert(N > 0, "capacity must be positive");

public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (count_ < N) {
            ++count_;
        } else {
            // full: oldest element is now at head_ (we just overwrote it)
            tail_ = (tail_ + 1) % N;
        }
    }

    T pop() {
        if (count_ == 0) {
            throw std::out_of_range("pop from empty ring buffer");
        }
        T value = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --count_;
        return value;
    }

    const T& operator[](std::size_t i) const {
        if (i >= count_) {
            throw std::out_of_range("ring buffer index out of range");
        }
        return data_[(tail_ + i) % N];
    }

    std::size_t size() const { return count_; }
    static constexpr std::size_t capacity() { return N; }
    bool empty() const { return count_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

}  // namespace xt

#include <iostream>
int main() {
    xt::RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3); rb.push(4);  // 4 evicts 1
    std::cout << "size=" << rb.size() << " first=" << rb[0] << "\n";
    std::cout << rb.pop() << " " << rb.pop() << " " << rb.pop() << "\n";
}
```

`head_` is the next write slot and `tail_` the next read slot. On overflow the write to `head_` already clobbered the oldest value, so advancing `tail_` keeps the logical window correct. `operator[]` indexes relative to `tail_`, so `rb[0]` is always the oldest remaining element.

