def canonical_ipv4(address: str):
    """Return the canonical 'a.b.c.d' form of an IPv4 string, or None."""
    if not isinstance(address, str):
        return None
    parts = address.strip().split(".")
    if len(parts) != 4:
        return None

    octets = []
    for part in parts:
        if not part.isdigit():
            return None
        if len(part) > 1 and part[0] == "0":
            return None  # reject leading zeros like 01 or 007
        value = int(part)
        if value > 255:
            return None
        octets.append(str(value))

    return ".".join(octets)


if __name__ == "__main__":
    tests = ["192.168.0.1", "192.168.000.1", " 10.0.0.255 ", "256.1.1.1",
             "1.2.3", "1.2.3.4.5", "a.b.c.d", "0.0.0.0", ""]
    for t in tests:
        print(repr(t), "->", canonical_ipv4(t))
```

Explicitly rejecting leading zeros matters because `int("007")` silently succeeds while real resolvers (and `inet_aton`) disagree on reading that as octal. `isdigit()` on the part rejects signs, spaces inside, and hex. The `strip()` only trims the outer string, not per-octet whitespace — so `"1. 2.3.4"` correctly fails.

