```cpp
#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

void rotateLeft(std::vector<int>& a, int k) {
    int n = static_cast<int>(a.size());
    if (n == 0) return;
    k %= n;
    if (k < 0) k += n;
    std::reverse(a.begin(), a.begin() + k);
    std::reverse(a.begin() + k, a.end());
    std::reverse(a.begin(), a.end());
}

int main() {
    std::vector<int> a{1, 2, 3, 4, 5};
    rotateLeft(a, 2);
    assert((a == std::vector<int>{3, 4, 5, 1, 2}));

    std::vector<int> b{};
    rotateLeft(b, 3);
    assert(b.empty());

    std::vector<int> c{1, 2};
    rotateLeft(c, 7);
    assert((c == std::vector<int>{2, 1}));

    std::cout << "ok\n";
    return 0;
}
```
Reversing the first `k`, then the rest, then the whole array performs a left rotation. `k` is reduced modulo `n`, and a negative `k` is normalised, so out-of-range shifts are safe; the empty-vector guard avoids undefined behaviour.

