fn is_palindrome(s: &str) -> bool {
    let chars: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .map(|c| c.to_lowercase().next().unwrap_or(c))
        .collect();
    let mut i = 0;
    let mut j = chars.len();
    while i + 1 < j {
        j -= 1;
        if chars[i] != chars[j] {
            return false;
        }
        i += 1;
    }
    true
}

fn main() {
    assert!(is_palindrome(""));
    assert!(is_palindrome("A man, a plan, a canal: Panama"));
    assert!(!is_palindrome("race a car"));
    assert!(is_palindrome("Été"));
    assert!(is_palindrome("12321"));
    assert!(!is_palindrome("ab"));
    println!("ok");
}
```
The string is filtered to alphanumeric characters and lowercased, then compared from both ends moving inward. The `while i + 1 < j` form guarantees two distinct indices remain before each decrement, so a one-character or empty collection returns `true` without a spurious comparison.

