from typing import List, Tuple


def merge_intervals(intervals: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    if not intervals:
        return []
    ordered = sorted(intervals)
    merged = [ordered[0]]
    for start, end in ordered[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged


def covered_length(intervals: List[Tuple[int, int]]) -> int:
    return sum(end - start for start, end in merge_intervals(intervals))


if __name__ == "__main__":
    assert merge_intervals([]) == []
    assert merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]
    assert covered_length([(1, 3), (2, 6), (8, 10), (15, 18)]) == 5 + 2 + 3
    assert merge_intervals([(5, 5), (5, 7)]) == [(5, 7)]
    assert covered_length([]) == 0
    print("ok")
```
Sorting by start makes overlap detection a single pass. The condition `start <= last_end` merges touching or overlapping intervals and widens the end with `max`, which also handles a fully contained interval. Total length sums the merged spans, so it counts each covered unit once.

