fn my_atoi(s: &str) -> Result<i64, &'static str> {
    let t = s.trim();
    if t.is_empty() {
        return Err("empty input");
    }
    let (neg, digits) = match t.as_bytes()[0] {
        b'+' => (false, &t[1..]),
        b'-' => (true, &t[1..]),
        _ => (false, t),
    };
    if digits.is_empty() {
        return Err("no digits");
    }
    let mut acc: i64 = 0;
    for c in digits.chars() {
        let d = match c.to_digit(10) {
            Some(d) => d as i64,
            None => return Err("invalid digit"),
        };
        acc = acc.checked_mul(10).ok_or("overflow")?;
        acc = if neg { acc.checked_sub(d) } else { acc.checked_add(d) }
            .ok_or("overflow")?;
    }
    Ok(acc)
}

fn main() {
    assert_eq!(my_atoi("  -42 "), Ok(-42));
    assert_eq!(my_atoi("+7"), Ok(7));
    assert_eq!(my_atoi(""), Err("empty input"));
    assert_eq!(my_atoi("12a"), Err("invalid digit"));
    assert_eq!(my_atoi("+"), Err("no digits"));
    assert!(my_atoi("99999999999999999999").is_err());
    println!("ok");
}
```
Whitespace is trimmed first, then the sign is peeled off; an empty remainder after the sign is diagnosed separately from empty input. Digits accumulate with `checked_mul`/`checked_add`, and negative values subtract during accumulation so the magnitude of `i64::MIN` is representable without a separate negate step that could overflow.

