#include <cctype>
#include <iostream>
#include <string>
#include <string_view>
#include <unordered_map>

std::unordered_map<std::string, int> wordCounts(std::string_view text) {
    std::unordered_map<std::string, int> counts;
    std::size_t i = 0;
    while (i < text.size()) {
        while (i < text.size() && std::isspace(static_cast<unsigned char>(text[i]))) ++i;
        std::size_t start = i;
        while (i < text.size() && !std::isspace(static_cast<unsigned char>(text[i]))) ++i;
        if (i > start) {
            ++counts[std::string(text.substr(start, i - start))];
        }
    }
    return counts;
}

int main() {
    auto c = wordCounts("the quick  brown\tthe\nfox the");
    if (c["the"] != 3 || c["quick"] != 1 || c["fox"] != 1 || c.size() != 4) {
        std::cerr << "unexpected counts\n";
        return 1;
    }
    auto empty = wordCounts("   \t\n  ");
    if (!empty.empty()) {
        std::cerr << "whitespace-only should be empty\n";
        return 1;
    }
    std::cout << "ok\n";
    return 0;
}
```
Two index scans per token let `string_view` refer into the original buffer with zero copies until the final construction of the map key. Casting to `unsigned char` before `std::isspace` avoids undefined behaviour on negative `char` values, and the `i > start` guard skips runs of repeated whitespace.

