```cpp
#include <condition_variable>
#include <iostream>
#include <mutex>
#include <queue>
#include <thread>
#include <vector>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    void push(int value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return q_.size() < cap_ || closed_; });
        if (closed_) return;
        q_.push(value);
        not_empty_.notify_one();
    }

    bool pop(int& out) {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return !q_.empty() || closed_; });
        if (q_.empty()) return false;  // closed and drained
        out = q_.front();
        q_.pop();
        not_full_.notify_one();
        return true;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    bool closed_ = false;
    std::queue<int> q_;
    std::mutex mu_;
    std::condition_variable not_empty_, not_full_;
};

int main() {
    BoundedQueue queue(4);
    const int total = 20;

    std::thread producer([&] {
        for (int i = 0; i < total; ++i) queue.push(i);
        queue.close();
    });

    std::vector<std::thread> consumers;
    std::mutex print_mu;
    for (int c = 0; c < 2; ++c) {
        consumers.emplace_back([&, c] {
            int value;
            while (queue.pop(value)) {
                std::lock_guard<std::mutex> lock(print_mu);
                std::cout << "consumer " << c << " got " << value << '\n';
            }
        });
    }

    producer.join();
    for (auto& t : consumers) t.join();
}
```

`push` waits while full, `pop` waits while empty. `close()` flips a flag and wakes everyone, so consumers stop once the queue is drained — that's how `pop` returns `false` and the threads exit. The output suppresses the queue order because two consumers race, but every value 0..19 appears exactly once.

