use std::collections::HashMap;
use std::env;
use std::fs;
use std::io;

fn word_frequencies(text: &str) -> HashMap<String, u32> {
    let mut counts: HashMap<String, u32> = HashMap::new();

    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '\'')
            .flat_map(|c| c.to_lowercase())
            .collect();

        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }

    counts
}

fn main() -> io::Result<()> {
    let path = env::args().nth(1).unwrap_or_else(|| {
        eprintln!("usage: wordcount <file>");
        std::process::exit(2);
    });

    let text = fs::read_to_string(&path)?;
    let mut entries: Vec<(String, u32)> = word_frequencies(&text).into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    for (word, count) in entries.iter().take(10) {
        println!("{count:>4}  {word}");
    }

    Ok(())
}
