```rust
#[derive(Debug, Default, PartialEq, Eq)]
pub struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self {
        Stack { items: Vec::new() }
    }

    pub fn push(&mut self, item: T) {
        self.items.push(item);
    }

    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    pub fn peek(&self) -> Option<&T> {
        self.items.last()
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
}

pub struct IntoIter<T>(std::vec::IntoIter<T>);

impl<T> Iterator for IntoIter<T> {
    type Item = T;
    fn next(&mut self) -> Option<T> {
        self.0.next()
    }
}

impl<T> IntoIterator for Stack<T> {
    type Item = T;
    type IntoIter = IntoIter<T>;
    fn into_iter(self) -> Self::IntoIter {
        // Pop order would be more stack-like; Vec's natural order is used here.
        IntoIter(self.items.into_iter().rev())
    }
}

fn main() {
    let mut stack: Stack<i32> = Stack::new();
    for n in 1..=4 {
        stack.push(n);
    }

    assert_eq!(stack.peek(), Some(&4));
    assert_eq!(stack.pop(), Some(4));
    assert_eq!(stack.len(), 3);

    let drained: Vec<i32> = stack.into_iter().collect();
    assert_eq!(drained, vec![3, 2, 1]);

    println!("drained: {drained:?}");

    let empty: Stack<i32> = Stack::new();
    assert!(empty.is_empty());
    assert_eq!(empty.peek(), None);
    println!("empty stack ok");
}
```

`IntoIterator` is implemented for the owned stack so consuming iteration yields items top-first (`.rev()` over the backing `Vec`), matching pop semantics. `pop` and `peek` return `Option`, which makes the empty case explicit rather than panicking. `Default` is derived from the empty `Vec`.

```rust
#[derive(Debug, PartialEq, Eq)]
pub struct Ipv4 {
    pub octets: [u8; 4],
}

#[derive(Debug, PartialEq, Eq)]
pub enum ParseError {
    WrongPartCount,
    EmptyPart,
    NonDigit,
    LeadingZero,
    OutOfRange,
}

impl Ipv4 {
    pub fn parse(s: &str) -> Result<Ipv4, ParseError> {
        let parts: Vec<&str> = s.split('.').collect();
        if parts.len() != 4 {
            return Err(ParseError::WrongPartCount);
        }

        let mut octets = [0u8; 4];
        for (i, part) in parts.iter().enumerate() {
            if part.is_empty() {
                return Err(ParseError::EmptyPart);
            }
            if !part.bytes().all(|b| b.is_ascii_digit()) {
                return Err(ParseError::NonDigit);
            }
            if part.len() > 1 && part.starts_with('0') {
                return Err(ParseError::LeadingZero);
            }
            // part.len() <= 3 here, so parse::<u16> is safe.
            let value: u16 = part.parse().map_err(|_| ParseError::OutOfRange)?;
            if value > 255 {
                return Err(ParseError::OutOfRange);
            }
            octets[i] = value as u8;
        }

        Ok(Ipv4 { octets })
    }
}

fn main() {
    let good = ["0.0.0.0", "127.0.0.1", "255.255.255.255"];
    let bad = ["256.0.0.1", "1.2.3", "1.2.3.4.5", "01.2.3.4", "1.2.3.x", "", "1..3.4"];

    for s in good {
        assert!(Ipv4::parse(s).is_ok(), "{s} should parse");
    }
    for s in bad {
        assert!(Ipv4::parse(s).is_err(), "{s} should fail");
    }

    println!("parsed: {:?}", Ipv4::parse("192.168.0.1"));
    println!("rejected: {:?}", Ipv4::parse("192.168.0.256"));
}
```

The parser rejects the subtle cases: leading zeros (`"01"`) which many parsers silently accept, empty parts from `"1..3.4"`, and out-of-range values. Digits are checked before parsing so a huge string can't overflow, and each error variant says exactly what was wrong. `main` finishes with assertions that exercise both the accepted and rejected sets.

```cpp
#include <cctype>
#include <fstream>
#include <iostream>
#include <string>

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "usage: " << argv[0] << " <file>\n";
        return 2;
    }

    std::ifstream in(argv[1], std::ios::binary);
    if (!in) {
        std::cerr << "cannot open: " << argv[1] << '\n';
        return 1;
    }

    std::uint64_t bytes = 0, lines = 0, words = 0;
    bool in_word = false;

    char ch;
    while (in.get(ch)) {
        ++bytes;
        const unsigned char uc = static_cast<unsigned char>(ch);

        if (uc == '\n') {
            ++lines;
        }

        if (std::isspace(uc)) {
            in_word = false;
        } else if (!in_word) {
            in_word = true;
            ++words;
        }
    }

    // A file that does not end in a newline still has a final line.
    if (bytes > 0 && ch != '\n') {
        ++lines;
    }

    std::cout << lines << ' ' << words << ' ' << bytes << ' ' << argv[1] << '\n';
    return 0;
}
```

Reads in binary mode so byte counts are exact on every platform. Words are counted on each transition from whitespace to non-whitespace, using `unsigned char` for `isspace` to avoid UB on high-bit bytes. The trailing check adds a final line when a non-empty file lacks a terminating newline, matching `wc -lwm` behaviour. Exit codes distinguish a usage error (2) from an open failure (1).

