fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let (mut lo, mut hi) = (0usize, slice.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if &slice[mid] == target {
            return Some(mid);
        } else if &slice[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    None
