```rust
fn longest_common_prefix(words: &[String]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = words[0].as_bytes();
    let mut len = first.len();
    for w in &words[1..] {
        let b = w.as_bytes();
        let mut i = 0;
        while i < len && i < b.len() && first[i] == b[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            break;
        }
    }
    // Safe: prefixes of valid UTF-8 are valid because we compare
    // byte-by-byte over a boundary-aligned prefix from `words[0]`.
    match std::str::from_utf8(&first[..len]) {
        Ok(s) => s.to_owned(),
        Err(_) => {
            // Trim back to a char boundary if a multibyte char was
            // split by a shorter neighbour.
            let s = words[0].as_str();
            let mut end = len;
            while end > 0 && !s.is_char_boundary(end) {
                end -= 1;
            }
            s[..end].to_owned()
        }
    }
}

fn main() {
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["car".into(), "cart".into()]), "car");
    assert_eq!(longest_common_prefix(&["".into(), "abc".into()]), "");
    assert_eq!(longest_common_prefix(&["dog".into(), "dove".into()]), "do");
    assert_eq!(longest_common_prefix(&["café".into(), "caféine".into()]), "café");
    println!("ok");
}
```

We scan bytes from the first string, shrinking `len` until every word agrees. The fallback trims to a `char` boundary so a multibyte character can't be sliced apart; without it, `from_utf8` would return an error on inputs like `["café", "caf"]`.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

/* Reverse in place, return the new head. Works for empty and
 * single-node lists without a special branch. */
Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int v) {
    Node *n = malloc(sizeof *n);
    if (!n) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = v;
    n->next = head;
    return n;
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 1; i <= 5; i++) {
        list = push(list, i); /* 5,4,3,2,1 */
    }
    list = reverse(list); /* 1,2,3,4,5 */

    int expected = 1;
    for (Node *p = list; p; p = p->next) {
        if (p->value != expected) {
            fprintf(stderr, "mismatch at %d\n", expected);
            free_list(list);
            return 1;
        }
        expected++;
    }
    if (expected != 6) {
        fprintf(stderr, "wrong length\n");
        free_list(list);
        return 1;
    }

    if (reverse(NULL) != NULL) {
        fprintf(stderr, "empty list must stay NULL\n");
        return 1;
    }

    free_list(list);
    puts("ok");
    return 0;
}
```

The loop rewires three pointers per step, so no recursion stack is used and a million-node list won't overflow. `reverse(NULL)` falls straight through to `return NULL`, which is why the empty case needs no `if`.

