int main(int argc, char** argv) {
    int top = 3;
    if (argc > 1) {
        try {
            top = std::stoi(argv[1]);
        } catch (...) {
            std::cerr << "invalid N\n";
            return 2;
        }
        if (top <= 0) {
            std::cerr << "N must be positive\n";
            return 2;
        }
    }

    std::map<std::string, long> counts;
    std::string word;
    while (std::cin >> word) {
        // Strip surrounding punctuation, keep UTF-8 bytes intact.
        std::size_t b = 0, e = word.size();
        while (b < e && (unsigned char)word[b] < 0x80 &&
               !std::isalnum((unsigned char)word[b])) b++;
        while (e > b && (unsigned char)word[e-1] < 0x80 &&
               !std::isalnum((unsigned char)word[e-1])) e--;
        if (e > b) counts[word.substr(b, e - b)]++;
    }

    std::vector<std::pair<std::string, long>> items(counts.begin(), counts.end());
    std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });

    for (int i = 0; i < top && i < (int)items.size(); ++i) {
        std::cout << items[i].first << ' ' << items[i].second << '\n';
    }
    return 0;
}
