```c
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define MOD 1000000007ULL

static unsigned long long fib_mod(unsigned long long n) {
    unsigned long long a = 0, b = 1;
    for (unsigned long long i = 0; i < n; i++) {
        unsigned long long next = (a + b) % MOD;
        a = b;
        b = next;
    }
    return a;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <n>\n", argv[0]);
        return 2;
    }
    errno = 0;
    char *end = NULL;
    unsigned long long n = strtoull(argv[1], &end, 10);
    if (errno != 0 || end == argv[1] || *end != '\0') {
        fprintf(stderr, "error: '%s' is not a non-negative integer\n", argv[1]);
        return 2;
    }

    printf("%llu\n", fib_mod(n));
    return 0;
}
```

Both running values stay below `MOD`, so the sum fits in `unsigned long long` with plenty of room — no `__int128` needed. `fib(0)=0`, `fib(1)=1` falls out of the loop naturally, and `strtoull` rejects negatives by letting the `-` sign fail the `*end` check.

