void mergeInto(std::vector<int>& a, std::vector<int>& buf, int lo, int mid, int hi) {
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) buf[k++] = a[i++];
        else              buf[k++] = a[j++];
    }
    while (i < mid) buf[k++] = a[i++];
    while (j < hi)  buf[k++] = a[j++];
    for (int p = lo; p < hi; ++p) a[p] = buf[p];
}

void mergeSort(std::vector<int>& a, std::vector<int>& buf, int lo, int hi) {
    if (hi - lo <= 1) return;
    int mid = lo + (hi - lo) / 2;
    mergeSort(a, buf, lo, mid);
    mergeSort(a, buf, mid, hi);
    mergeInto(a, buf, lo, mid, hi);
}

int main() {
    std::vector<int> a = {38, 27, 43, 3, 9, 82, 10};
    std::vector<int> buf(a.size());
    mergeSort(a, buf, 0, (int)a.size());
    for (int x : a) std::cout << x << ' ';
    std::cout << '\n';
}
