```rust
pub fn reverse_string_in_place(s: &mut String) {
    // Safe and efficient: swap the grapheme-free char sequence using
    // char_indices, no new allocation for the characters themselves.
    let mut chars: Vec<char> = s.chars().rev().collect();
    let mut it = chars.drain(..);
    // The simple safe version still allocates the char buffer, so instead
    // mutate via char_indices in place below.
    let _ = it;

    // True in-place version using char boundaries:
    let mut left = 0usize;
    let mut right = s.len();
    while left < right {
        // Move right back to the start of the final character.
        right = match s[..right].char_indices().next_back() {
            Some((i, _)) => i,
            None => break,
        };
        if left >= right {
            break;
        }
        // Find the start byte of the left character.
        let left_char_len = s[left..].chars().next().map(|c| c.len_utf8()).unwrap_or(0);
        if left_char_len == 0 {
            break;
        }
        // Rotate the two characters by rebuilding only the affected slice.
        let left_char: String = s[left..left + left_char_len].to_string();
        let right_char: String = s[right..].to_string();
        let mid_end = right;
        s.replace_range(left..left + left_char_len, &right_char);
        s.replace_range(s.len() - right_char.len().., &left_char);
        left += right_char.len();
        right = mid_end - left_char.len();
        // Guard against crossed boundaries.
        if left >= right {
            break;
        }
    }
}

