std::optional<long long> parse_int(std::string_view sv) {
    // Trim ASCII whitespace.
    auto not_space = [](unsigned char c) { return !std::isspace(c); };
    while (!sv.empty() && !not_space(static_cast<unsigned char>(sv.front()))) sv.remove_prefix(1);
    while (!sv.empty() && !not_space(static_cast<unsigned char>(sv.back()))) sv.remove_suffix(1);
    if (sv.empty()) return std::nullopt;

    long long value = 0;
    auto result = std::from_chars(sv.data(), sv.data() + sv.size(), value);
    if (result.ec == std::errc::result_out_of_range) return std::nullopt;
    if (result.ec != std::errc{} || result.ptr != sv.data() + sv.size()) return std::nullopt;
    return value;
}

