import os
import re

TODO_RE = re.compile(r"#.*\bTODO\b", re.IGNORECASE)

def scan(root):
    hits = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in {".git", "__pycache__", ".venv"}]
        for name in filenames:
            if not name.endswith(".py"):
                continue
            path = os.path.join(dirpath, name)
            try:
                with open(path, encoding="utf-8", errors="replace") as f:
                    for lineno, line in enumerate(f, start=1):
                        if TODO_RE.search(line):
                            hits.append((path, lineno, line.rstrip()))
            except OSError as e:
                print(f"could not read {path}: {e}")
    return hits

def main():
    import sys
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    hits = scan(root)
    if not hits:
        print("no TODO comments found")
        return
    for path, lineno, text in hits:
        print(f"{path}:{lineno}: {text}")

if __name__ == "__main__":
    main()
```

The regex requires `TODO` to appear after a `#`, so string literals containing the word are ignored. Directories like `.git` and `__pycache__` are pruned, and unreadable files are reported instead of aborting the scan. Pass a root path as the first argument; it defaults to the current directory.

