```python
class MinHeap:
    def __init__(self):
        self._data = []

    def __len__(self):
        return len(self._data)

    def push(self, value):
        self._data.append(value)
        self._sift_up(len(self._data) - 1)

    def pop(self):
        if not self._data:
            raise IndexError("pop from empty heap")
        self._swap(0, len(self._data) - 1)
        value = self._data.pop()
        if self._data:
            self._sift_down(0)
        return value

    def peek(self):
        if not self._data:
            raise IndexError("peek on empty heap")
        return self._data[0]

    def _swap(self, i, j):
        self._data[i], self._data[j] = self._data[j], self._data[i]

    def _sift_up(self, i):
        while i > 0:
            parent = (i - 1) // 2
            if self._data[i] >= self._data[parent]:
                break
            self._swap(i, parent)
            i = parent

    def _sift_down(self, i):
        n = len(self._data)
        while True:
            smallest = i
            left, right = 2 * i + 1, 2 * i + 2
            if left < n and self._data[left] < self._data[smallest]:
                smallest = left
            if right < n and self._data[right] < self._data[smallest]:
                smallest = right
            if smallest == i:
                break
            self._swap(i, smallest)
            i = smallest


if __name__ == "__main__":
    import heapq
    import random

    h = MinHeap()
    values = [random.randint(0, 1000) for _ in range(200)]
    for v in values:
        h.push(v)
    assert [h.pop() for _ in values] == sorted(values)
    assert len(h) == 0
    print("heap matches sorted order")
```

`push` sifts the new leaf up against its parent, while `pop` moves the last leaf to the root and sifts it down against the smaller child, so both operations stay O(log n). The test cross-checks every popped value against Python's own `sorted`.

```cpp
#include <iostream>
#include <cassert>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse_iterative(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

Node* reverse_recursive(Node* head) {
    if (!head || !head->next) return head;
    Node* new_head = reverse_recursive(head->next);
    head->next->next = head;
    head->next = nullptr;
    return new_head;
}

static Node* build(const std::initializer_list<int>& vals) {
    Node* head = nullptr;
    Node** tail = &head;
    for (int v : vals) {
        *tail = new Node(v);
        tail = &((*tail)->next);
    }
    return head;
}

static bool equals(const Node* a, const std::initializer_list<int>& vals) {
    for (int v : vals) {
        if (!a || a->value != v) return false;
        a = a->next;
    }
    return a == nullptr;
}

static void free_list(Node* head) {
    while (head) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    Node* a = reverse_iterative(build({1, 2, 3, 4}));
    assert(equals(a, {4, 3, 2, 1}));
    free_list(a);

    Node* b = reverse_recursive(build({7, 8}));
    assert(equals(b, {8, 7}));
    free_list(b);

    assert(reverse_iterative(nullptr) == nullptr);
    assert(reverse_recursive(nullptr) == nullptr);
    std::cout << "all reversals passed\n";
    return 0;
}
```

The iterative version walks the list once while flipping each `next` pointer; the recursive version reverses the tail and then points the old next node back at the head. Both terminate on a null head, and the harness frees every allocation.

