#include <iostream>
#include <stack>
#include <string>
#include <cassert>

bool is_balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                st.push(c);
                break;
            case ')':
                if (st.empty() || st.top() != '(') return false;
                st.pop();
                break;
            case ']':
                if (st.empty() || st.top() != '[') return false;
                st.pop();
                break;
            case '}':
                if (st.empty() || st.top() != '{') return false;
                st.pop();
                break;
            default:
                break;
        }
    }
    return st.empty();
}

int main() {
    assert(is_balanced("({[]})"));
    assert(is_balanced(""));
    assert(is_balanced("a(b)c[d]"));
    assert(!is_balanced("(]"));
    assert(!is_balanced("({[})"));
    assert(!is_balanced("((("));
    assert(!is_balanced("))"));
    std::cout << "bracket checks passed\n";
    return 0;
}
