    std::sort(v.begin(), v.end());
    long long sum = 0;
    for (auto x : v) sum += x;
    size_t n = v.size();
    double median = (n % 2 == 1) ? double(v[n / 2])
                                 : (double(v[n / 2 - 1]) + double(v[n / 2])) / 2.0;
    return {v.front(), v.back(), double(sum) / double(n), median};
