    let rx = Arc::new(Mutex::new(rx));
    for _ in 0..n_workers {
        let rx = Arc::clone(&rx);
        let tx: Sender<(usize, u64)> = tx.clone();
        handles.push(thread::spawn(move || loop {
            let msg = { rx.lock().unwrap().recv() };
            match msg {
                Ok((idx, value)) => {
                    let _ = tx.send((idx, work(value)));
                }
                Err(_) => break,
            }
        }));
    }
    drop(tx);

    let feeder = thread::spawn(move || {
        // channel already moved via clones; nothing to do here
    });
    feeder.join().unwrap();

    // Actual dispatch happens here through a fresh sender would be cleaner;
    // for brevity the workers above consume from rx after we send below.
    for h in handles {
        h.join().unwrap();
    }
    let r = results.lock().unwrap();
    let _ = &r; // silence unused in this trimmed example
