#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *key;
    int value;
    uint8_t used;
} Entry;

typedef struct {
    Entry *entries;
    size_t cap;
    size_t len;
} Map;

static uint64_t hash_str(const char *s) {
    uint64_t h = 1469598103934665603ULL; /* FNV-1a */
    for (; *s; ++s) {
        h ^= (unsigned char)*s;
        h *= 1099511628211ULL;
    }
    return h;
}

static int map_init(Map *m, size_t cap) {
    m->entries = calloc(cap, sizeof(Entry));
    if (!m->entries) return -1;
    m->cap = cap;
    m->len = 0;
    return 0;
}

static void map_free(Map *m) {
    for (size_t i = 0; i < m->cap; ++i) free(m->entries[i].key);
    free(m->entries);
}

static Entry *probe(Entry *entries, size_t cap, const char *key) {
    size_t i = hash_str(key) % cap;
    while (entries[i].used && strcmp(entries[i].key, key) != 0)
        i = (i + 1) % cap;
    return &entries[i];
}

static int map_grow(Map *m);

static int map_put(Map *m, const char *key, int value) {
    if ((m->len + 1) * 10 >= m->cap * 7) { /* load factor 0.7 */
        if (map_grow(m) != 0) return -1;
    }
    Entry *e = probe(m->entries, m->cap, key);
    if (!e->used) {
        e->key = strdup(key);
        if (!e->key) return -1;
        e->used = 1;
        m->len++;
    }
    e->value = value;
    return 0;
}

static int map_get(const Map *m, const char *key, int *out) {
    Entry *e = probe(m->entries, m->cap, key);
    if (!e->used) return 0;
    *out = e->value;
    return 1;
}

static int map_grow(Map *m) {
    Entry *old = m->entries;
    size_t oldcap = m->cap;
    if (map_init(m, oldcap * 2) != 0) return -1;
    for (size_t i = 0; i < oldcap; ++i) {
        if (old[i].used) {
            map_put(m, old[i].key, old[i].value);
            free(old[i].key);
        }
    }
    free(old);
    return 0;
}

int main(void) {
    Map m;
    if (map_init(&m, 4) != 0) return 1;
    for (int i = 0; i < 100; ++i) {
        char buf[32];
        snprintf(buf, sizeof buf, "key%d", i);
        if (map_put(&m, buf, i * 2) != 0) return 1;
    }
    int v;
    if (!map_get(&m, "key42", &v) || v != 84) { fprintf(stderr, "fail\n"); return 1; }
    if (map_get(&m, "missing", &v)) { fprintf(stderr, "unexpected hit\n"); return 1; }
    printf("ok len=%zu cap=%zu\n", m.len, m.cap);
    map_free(&m);
    return 0;
}
