#include <iostream>

struct Node {
    int value;
    Node* next;
    Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    Node* cur = head;
    while (cur != nullptr) {
        Node* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    return prev;
}

void print(Node* head) {
    for (Node* p = head; p != nullptr; p = p->next) {
        std::cout << p->value;
        if (p->next) std::cout << " -> ";
    }
    std::cout << "\n";
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    print(head);
    head = reverse(head);
    print(head);
    // free
    while (head) { Node* n = head->next; delete head; head = n; }
    return 0;
}
