class BoundedStack:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._cap = capacity
        self._items = []

    def push(self, item):
        if self.is_full():
            raise OverflowError("stack is full")
        self._items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError("peek from empty stack")
        return self._items[-1]

    def is_full(self):
        return len(self._items) == self._cap

    def is_empty(self):
        return not self._items

    def __len__(self):
        return len(self._items)


if __name__ == "__main__":
    s = BoundedStack(2)
    s.push(1)
    s.push(2)
    print(s.is_full(), len(s))
    s.pop()
    print(s.peek())
```

Backed by a Python list but gated on an explicit capacity, so `push` raises rather than silently growing. `pop` and `peek` both guard the empty case so callers get a clear exception instead of an `IndexError` from the list.

