#include <iostream>
#include <queue>
#include <vector>
#include <iomanip>

int main() {
    std::priority_queue<long long> low;                              // max-heap
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> high; // min-heap

    long long value;
    bool any = false;
    while (std::cin >> value) {
        any = true;
        if (low.empty() || value <= low.top()) {
            low.push(value);
        } else {
            high.push(value);
        }
        // rebalance: low may have at most one more than high
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        if (low.size() == high.size()) {
            std::cout << std::setprecision(10)
                      << (low.top() + high.top()) / 2.0 << '\n';
        } else {
            std::cout << low.top() << '\n';
        }
    }

    if (!any) {
        std::cerr << "no input\n";
        return 0;
    }
    return 0;
}
```

The two-heap invariant keeps the lower half in a max-heap and the upper half in a min-heap with sizes differing by at most one. The median is `low.top()` when sizes differ, otherwise the mean of the two tops. An empty stream produces no output and a message on stderr.

```rust
#[derive(Debug, PartialEq)]
pub enum IpError {
    WrongParts,
    EmptyOctet,
    NotANumber,
    LeadingZero,
    OutOfRange,
}

pub fn parse_ipv4(s: &str) -> Result<[u8; 4], IpError> {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return Err(IpError::WrongParts);
    }

    let mut out = [0u8; 4];
    for (i, part) in parts.iter().enumerate() {
        if part.is_empty() {
            return Err(IpError::EmptyOctet);
        }
        if part.len() > 1 && part.starts_with('0') {
            return Err(IpError::LeadingZero);
        }
        let value: u16 = part.parse().map_err(|_| IpError::NotANumber)?;
        if value > 255 {
            return Err(IpError::OutOfRange);
        }
        out[i] = value as u8;
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_valid() {
        assert_eq!(parse_ipv4("192.168.0.1"), Ok([192, 168, 0, 1]));
        assert_eq!(parse_ipv4("0.0.0.0"), Ok([0, 0, 0, 0]));
        assert_eq!(parse_ipv4("255.255.255.255"), Ok([255, 255, 255, 255]));
    }

    #[test]
    fn rejects_invalid() {
        assert_eq!(parse_ipv4("1.2.3"), Err(IpError::WrongParts));
        assert_eq!(parse_ipv4("1..2.3"), Err(IpError::EmptyOctet));
        assert_eq!(parse_ipv4("01.2.3.4"), Err(IpError::LeadingZero));
        assert_eq!(parse_ipv4("256.1.1.1"), Err(IpError::OutOfRange));
        assert_eq!(parse_ipv4("a.b.c.d"), Err(IpError::NotANumber));
    }
}
```

Each octet is parsed as `u16` first so `256` can be detected and reported as `OutOfRange` rather than silently wrapping. Leading zeros are rejected explicitly because `std`'s integer parser would otherwise accept `01`.

