int main(int argc, char **argv) {
    FILE *fp = stdin;
    if (argc > 2) {
        fprintf(stderr, "usage: %s [file]\n", argv[0]);
        return 2;
    }
    if (argc == 2) {
        fp = fopen(argv[1], "rb");
        if (fp == NULL) {
            perror(argv[1]);
            return 1;
        }
    }

    unsigned long long bytes = 0, lines = 0, words = 0, maxlen = 0, curlen = 0;
    int in_word = 0;
    int c;

    while ((c = fgetc(fp)) != EOF) {
        bytes++;
        if (c == '\n') {
            lines++;
            if (curlen > maxlen) maxlen = curlen;
            curlen = 0;
        } else {
            curlen++;
        }
        if (isspace((unsigned char)c)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            words++;
        }
    }
    /* final line without trailing newline */
    if (curlen > 0) {
        lines++;
        if (curlen > maxlen) maxlen = curlen;
    }
    if (argc == 2) fclose(fp);

    printf("%llu %llu %llu %llu\n", lines, words, bytes, maxlen);
    return 0;
}
