import hashlib
import os
import time
from pathlib import Path


def load_seen(log_path):
    seen = set()
    if log_path.exists():
        for line in log_path.read_text(encoding='utf-8').splitlines():
            parts = line.split(maxsplit=1)
            if parts:
                seen.add(parts[0])
    return seen


def sha256_of(path, chunk=1 << 20):
    digest = hashlib.sha256()
    with path.open('rb') as fh:
        for block in iter(lambda: fh.read(chunk), b''):
            digest.update(block)
    return digest.hexdigest()


def watch(directory, log_path, interval=1.0):
    directory = Path(directory)
    log_path = Path(log_path)
    seen = load_seen(log_path)
    while True:
        for entry in sorted(directory.iterdir()):
            if not entry.is_file() or entry.name in seen:
                continue
            digest = sha256_of(entry)
            with log_path.open('a', encoding='utf-8') as fh:
                fh.write(f'{entry.name} {digest}\n')
            seen.add(entry.name)
        time.sleep(interval)


if __name__ == '__main__':
    import sys
    watch(sys.argv[1], sys.argv[2] if len(sys.argv) > 2 else 'hashes.log')
```

`load_seen` rebuilds the set of already-processed names from the log on start, so restarting the script does not rehash or re-append. Hashing streams in 1 MiB chunks so large files do not fit into memory, and `iter(lambda: ..., b'')` reads until EOF.`

