    std::stringstream ss(line);
    std::string field;
    while (std::getline(ss, field, ',')) {
        std::size_t b = field.find_first_not_of(" \t");
        if (b == std::string::npos) continue;  // blank field
        std::size_t e = field.find_last_not_of(" \t");
        std::string token = field.substr(b, e - b + 1);
        total += std::stoll(token);
    }
    return total;
