class MinHeap:
    """Array-backed min-heap. Duplicate priorities are allowed."""

    def __init__(self):
        self._data = []

    def __len__(self):
        return len(self._data)

    def push(self, item, priority):
        self._data.append((priority, item))
        self._sift_up(len(self._data) - 1)

    def pop(self):
        if not self._data:
            raise IndexError("pop from empty heap")
        top = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            self._sift_down(0)
        return top[1]

    def _sift_up(self, i):
        while i > 0:
            parent = (i - 1) // 2
            if self._data[parent][0] <= self._data[i][0]:
                break
            self._data[parent], self._data[i] = self._data[i], self._data[parent]
            i = parent

    def _sift_down(self, i):
        n = len(self._data)
        while True:
            left, right, smallest = 2 * i + 1, 2 * i + 2, i
            for child in (left, right):
                if child < n and self._data[child][0] < self._data[smallest][0]:
                    smallest = child
            if smallest == i:
                break
            self._data[i], self._data[smallest] = self._data[smallest], self._data[i]
            i = smallest


if __name__ == "__main__":
    h = MinHeap()
    for item, prio in [("a", 3), ("b", 1), ("c", 3), ("d", 2), ("e", 1)]:
        h.push(item, prio)
    out = [h.pop() for _ in range(len(h))]
    assert sorted(out[:2]) == ["b", "e"], out  # two priority-1 items, any order
    assert out[2:] == ["d", "a", "c"] or sorted(out[2:]) == ["a", "c", "d"]
    try:
        MinHeap().pop()
    except IndexError:
        pass
    else:
        raise AssertionError("expected IndexError")
    print("heap checks pass")
