#define INITIAL_LINES 16

static void die(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

int main(void) {
    char **lines = malloc(INITIAL_LINES * sizeof(*lines));
    if (!lines) die("out of memory");
    size_t cap = INITIAL_LINES, n = 0;

    char *buf = NULL;
    size_t bufsz = 0;
    ssize_t len;
    while ((len = getline(&buf, &bufsz, stdin)) != -1) {
        if (n == cap) {
            cap *= 2;
            char **grown = realloc(lines, cap * sizeof(*lines));
            if (!grown) die("out of memory");
            lines = grown;
        }
        char *copy = malloc((size_t)len + 1);
        if (!copy) die("out of memory");
        memcpy(copy, buf, (size_t)len);
        copy[len] = '\0';
        lines[n++] = copy;
    }
    free(buf);

