/// Parse one `key=value` line. Keys are trimmed and lowercased; values keep
/// internal spaces but are trimmed at the edges. Empty lines are rejected.
fn parse_line(line: &str, seen: &mut HashMap<String, String>) -> Result<(), ConfigError> {
    let trimmed = line.trim();
    if trimmed.is_empty() {
        return Err(ConfigError::Empty);
    }
    let (raw_key, raw_value) = trimmed.split_once('=').ok_or(ConfigError::MissingEquals)?;
    let key = raw_key.trim().to_lowercase();
    if key.is_empty() {
        return Err(ConfigError::BlankKey);
    }
    if seen.contains_key(&key) {
        return Err(ConfigError::DuplicateKey);
    }
    seen.insert(key, raw_value.trim().to_string());
    Ok(())
}

fn main() {
    let mut seen = HashMap::new();
    assert_eq!(parse_line("Host = example.com", &mut seen), Ok(()));
    assert_eq!(seen.get("host").map(String::as_str), Some("example.com"));
    assert_eq!(parse_line("host=again", &mut seen), Err(ConfigError::DuplicateKey));
    assert_eq!(parse_line("", &mut seen), Err(ConfigError::Empty));
    assert_eq!(parse_line("noequals", &mut seen), Err(ConfigError::MissingEquals));
    assert_eq!(parse_line("=nokey", &mut seen), Err(ConfigError::BlankKey));
    println!("config checks pass");
}
