class Rational {
public:
    Rational(long long num, long long den) {
        if (den == 0) throw std::invalid_argument("zero denominator");
        if (den < 0) { num = -num; den = -den; }
        long long g = std::gcd(num < 0 ? -num : num, den);
        if (g == 0) g = 1;  // happens only when num == 0 and den == 0, already excluded
        num_ = num / g;
        den_ = den / g;
    }

    long long num() const { return num_; }
    long long den() const { return den_; }

    Rational operator+(const Rational& other) const {
        return Rational(num_ * other.den_ + other.num_ * den_, den_ * other.den_);
    }

    bool operator==(const Rational& other) const {
        return num_ == other.num_ && den_ == other.den_;
    }

private:
    long long num_;
    long long den_;
};

int main() {
