```python
class Parser:
    """Recursive descent parser for += with precedence: expr -> term (+/- term)*,
    term -> factor (*// factor)*, factor -> number | '(' expr ')' | '-' factor."""

    def __init__(self, text):
        self.tokens = self._tokenize(text)
        self.pos = 0

    @staticmethod
    def _tokenize(text):
        tokens, i = [], 0
        while i < len(text):
            ch = text[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit() or ch == '.':
                j = i
                while j < len(text) and (text[j].isdigit() or text[j] == '.'):
                    j += 1
                tokens.append(float(text[i:j]))
                i = j
            elif ch in "+-*/()":
                tokens.append(ch)
                i += 1
            else:
                raise ValueError(f"unexpected character {ch!r} at {i}")
        return tokens

    def _peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _next(self):
        tok = self._peek()
        if tok is None:
            raise ValueError("unexpected end of input")
        self.pos += 1
        return tok

    def parse(self):
        value = self._expr()
        if self.pos != len(self.tokens):
            raise ValueError(f"trailing input at token {self.pos}")
        return value

    def _expr(self):
        value = self._term()
        while self._peek() in ("+", "-"):
            op = self._next()
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def _term(self):
        value = self._factor()
        while self._peek() in ("*", "/"):
            op = self._next()
            rhs = self._factor()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero in expression")
                value /= rhs
        return value

    def _factor(self):
        tok = self._next()
        if isinstance(tok, float):
            return tok
        if tok == "-":
            return -self._factor()
        if tok == "(":
            value = self._expr()
            if self._next() != ")":
                raise ValueError("expected ')'")
            return value
        raise ValueError(f"unexpected token {tok!r}")


def evaluate(text):
    return Parser(text).parse()


if __name__ == "__main__":
    assert evaluate("1 + 2 * 3") == 7
    assert evaluate("(1 + 2) * 3") == 9
    assert evaluate("-4 + 10 / 2") == 1
    assert evaluate("2 * (3 + (4 - 1))") == 12
    for bad in ("1 +", "(1", "1 2", "$3"):
        try:
            evaluate(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"expected failure for {bad!r}")
    print("parser checks pass")
