void reverse_in_place(char* text) {
    if (text == nullptr) {
        return;
    }
    std::size_t left = 0;
    std::size_t right = std::strlen(text);
    if (right == 0) {
        return;
    }
    --right;
    while (left < right) {
        char tmp = text[left];
        text[left] = text[right];
        text[right] = tmp;
        ++left;
        --right;
    }
}

int main() {
    char buffer[] = "hello world";
    reverse_in_place(buffer);
    std::cout << buffer << '\n';  // dlrow olleh

    char empty[] = "";
    reverse_in_place(empty);
    std::cout << "[" << empty << "]\n";  // []
    return 0;
}
