use std::collections::HashSet;
use std::hash::Hash;

fn dedup_stable<T: Eq + Hash + Clone>(items: &[T]) -> Vec<T> {
    let mut seen = HashSet::new();
    let mut out = Vec::with_capacity(items.len());
    for item in items {
        if seen.insert(item.clone()) {
            out.push(item.clone());
        }
    }
    out
}

fn main() {
    let numbers = vec![3, 1, 3, 2, 1, 5];
    println!("{:?}", dedup_stable(&numbers)); // [3, 1, 2, 5]

    let words = ["a", "b", "a", "c", "b"];
    println!("{:?}", dedup_stable(&words)); // ["a", "b", "c"]

    let empty: Vec<i32> = Vec::new();
    println!("{:?}", dedup_stable(&empty)); // []
}
