def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring using center expansion."""
    if not s:
        return ""
    best_start, best_len = 0, 1
    n = len(s)

    def expand(lo: int, hi: int) -> tuple[int, int]:
        while lo >= 0 and hi < n and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - lo - 1

    for i in range(n):
        start, length = expand(i, i)
        if length > best_len:
            best_start, best_len = start, length
        start, length = expand(i, i + 1)
        if length > best_len:
            best_start, best_len = start, length
    return s[best_start:best_start + best_len]


if __name__ == "__main__":
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "ünün"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```
Expanding around each of the `2n-1` centers runs in O(n²) time and O(1) extra space. Empty input returns `""` and a single character returns itself.

