```cpp
#include <cstddef>
#include <cstdio>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity, 0.0f), capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(float value) {
        buf_[head_] = value;
        head_ = (head_ + 1) % capacity_;
        if (size_ < capacity_) ++size_;
    }

    float average() const {
        if (size_ == 0) return 0.0f;
        float sum = 0.0f;
        for (std::size_t i = 0; i < size_; ++i) sum += buf_[i];
        return sum / static_cast<float>(size_);
    }

    std::size_t size() const { return size_; }

private:
    std::vector<float> buf_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    if (rb.average() != 0.0f) return 1;
    rb.push(1.0f);
    rb.push(2.0f);
    rb.push(3.0f);
    rb.push(4.0f);  // evicts 1.0
    std::printf("size=%zu avg=%.2f\n", rb.size(), rb.average());
    return rb.average() == 3.0f ? 0 : 1;
}
```
`push` overwrites the oldest sample once full. `average` guards the empty case, and the modulo wrap keeps indices in bounds.

