fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 3]), vec![1, 1, 1, 2, 3]);
    assert_eq!(merge_sorted(&[7], &[]), vec![7]);
    println!("all cases passed");
}
```
The `<=` comparison keeps equal elements from `a` first, so the merge is stable. The two tails are appended after one side is exhausted, giving O(n+m) time.

```rust
use std::env;
use std::fs::File;
use std::io::{self, Read};
use std::process;

const FNV_OFFSET: u64 = 0xcbf29ce484222325;
const FNV_PRIME: u64 = 0x100000001b3;

fn fnv1a(bytes: &[u8], mut hash: u64) -> u64 {
    for &b in bytes {
        hash ^= b as u64;
        hash = hash.wrapping_mul(FNV_PRIME);
    }
    hash
}

fn main() {
    let paths: Vec<String> = env::args().skip(1).collect();
    if paths.is_empty() {
        eprintln!("usage: checksum <file>...");
        process::exit(1);
    }
    let mut failed = false;
    for path in &paths {
        match File::open(path) {
            Ok(mut f) => {
                let mut hash = FNV_OFFSET;
                let mut buf = [0u8; 8192];
                loop {
                    match f.read(&mut buf) {
                        Ok(0) => break,
                        Ok(n) => hash = fnv1a(&buf[..n], hash),
                        Err(e) => {
                            eprintln!("{}: read error: {e}", path);
                            failed = true;
                            break;
                        }
                    }
                }
                println!("{hash:016x}  {path}");
            }
            Err(e) => {
                eprintln!("{}: {e}", path);
                failed = true;
            }
        }
    }
    if failed {
        process::exit(1);
    }
}
```
This is FNV-1a, not a cryptographic hash. It streams files in 8 KiB chunks so memory stays flat, and reports per-file errors while continuing with the rest.

