void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; ++i) {
        char tmp = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = tmp;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    if (strcmp(a, "olleh") != 0) return 1;

    char b[] = "";
    reverse_in_place(b);
    if (strcmp(b, "") != 0) return 2;

    char c[] = "a";
    reverse_in_place(c);
    if (strcmp(c, "a") != 0) return 3;

    reverse_in_place(NULL);  /* must be a no-op */

    char d[] = "ab\0cd";  /* embedded terminator */
    reverse_in_place(d);
    if (strcmp(d, "ba") != 0) return 4;

    printf("all cases passed\n");
    return 0;
}
```
Using `strlen` means a `NULL` pointer is guarded and only the bytes up to the first `\0` are touched, so trailing data after an embedded terminator is untouched.

