#include <stdio.h>
#include <stddef.h>

int binary_search(const int *arr, size_t n, int target) {
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) {
            return (int)mid;
        }
        if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

int main(void) {
    const int a[] = {-7, -1, 0, 3, 5, 5, 9, 12, 40};
    const size_t n = sizeof(a) / sizeof(a[0]);
    struct { int target; int want; } cases[] = {
        {-7, 0}, {-1, 1}, {0, 2}, {5, 4}, {40, 8},
        {4, -1}, {-8, -1}, {41, -1},
    };
    if (binary_search(a, 0, 5) != -1) {
        printf("FAIL: empty array should return -1\n");
        return 1;
    }
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
        int got = binary_search(a, n, cases[i].target);
        if (got != cases[i].want) {
            printf("FAIL: target %d -> %d, expected %d\n",
                   cases[i].target, got, cases[i].want);
            return 1;
        }
    }
    printf("all checks passed\n");
    return 0;
}
