def encode(text):
    if not text:
        return ""
    out = []
    prev = text[0]
    count = 1
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(f"{prev}{count}")
            prev = ch
            count = 1
    out.append(f"{prev}{count}")
    return "".join(out)

def decode(code):
    out = []
    i = 0
    while i < len(code):
        ch = code[i]
        i += 1
        num = []
        while i < len(code) and code[i].isdigit():
            num.append(code[i])
            i += 1
        if not num:
            raise ValueError("missing count after %r" % ch)
        out.append(ch * int("".join(num)))
    return "".join(out)

if __name__ == "__main__":
    for s in ["", "a", "aaabbbcccd", "abcd", "zzzzzzzzzzzz"]:
        assert decode(encode(s)) == s, s
    print(encode("aaabbbcccd"))  # a3b3c3d1
    print("round-trip ok")
