#[derive(Debug, PartialEq)]
enum StackError {
    Overflow,
    Underflow,
}

struct BoundedStack<T> {
    data: Vec<T>,
    capacity: usize,
}

impl<T> BoundedStack<T> {
    fn new(capacity: usize) -> Self {
        BoundedStack { data: Vec::with_capacity(capacity), capacity }
    }

    fn push(&mut self, value: T) -> Result<(), StackError> {
        if self.data.len() >= self.capacity {
            return Err(StackError::Overflow);
        }
        self.data.push(value);
        Ok(())
    }

    fn pop(&mut self) -> Result<T, StackError> {
        self.data.pop().ok_or(StackError::Underflow)
    }

    fn peek(&self) -> Option<&T> {
        self.data.last()
    }
}

fn main() {
    let mut s = BoundedStack::new(2);
    assert_eq!(s.push(1), Ok(()));
    assert_eq!(s.push(2), Ok(()));
    assert_eq!(s.push(3), Err(StackError::Overflow));
    assert_eq!(s.pop(), Ok(2));
    assert_eq!(s.peek(), Some(&1));
    assert_eq!(s.pop(), Ok(1));
    assert_eq!(s.pop(), Err(StackError::Underflow));
    println!("stack ok");
}
```

