template <typename T>
T median(std::vector<T> values) {   // copy: caller's vector untouched
    if (values.empty()) {
        throw std::invalid_argument("median of empty vector");
    }
    std::sort(values.begin(), values.end());
    std::size_t n = values.size();
    if (n % 2 == 1) {
        return values[n / 2];
    }
    return (values[n / 2 - 1] + values[n / 2]) / 2;
}

int main() {
    std::vector<int> a = {5, 1, 4, 2, 3};
    std::cout << median(a) << "\n";   // 3
    std::cout << median(std::vector<int>{1, 2, 3, 4}) << "\n";  // 2 (integer)
    std::cout << a.size() << "\n";    // 5, unchanged
}
