```rust
fn is_valid_ipv4(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return false;
    }
    parts.iter().all(|p| {
        if p.is_empty() || p.len() > 3 {
            return false;
        }
        if p.len() > 1 && p.starts_with('0') {
            return false;
        }
        match p.parse::<u32>() {
            Ok(n) => n <= 255,
            Err(_) => false,
        }
    })
}

fn main() {
    let cases = [
        ("192.168.0.1", true),
        ("255.255.255.255", true),
        ("256.0.0.1", false),
        ("01.2.3.4", false),
        ("1.2.3", false),
        ("1.2.3.4.5", false),
        ("", false),
    ];
    for (s, want) in cases {
        assert_eq!(is_valid_ipv4(s), want, "failed on {s:?}");
    }
    println!("ok");
}
```

It rejects leading zeros (so `01.2.3.4` fails), enforces four octets and a 255 ceiling, and treats empty labels as invalid.

```python
import math


def fib_iter(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def fib_closed(n):
    phi = (1 + math.sqrt(5)) / 2
    return round((phi ** n - (-phi) ** (-n)) / math.sqrt(5))


if __name__ == "__main__":
    for n in range(30):
        assert fib_iter(n) == fib_closed(n), n
    assert fib_iter(0) == 0
    assert fib_iter(1) == 1
    assert fib_iter(10) == 55
    try:
        fib_iter(-1)
    except ValueError:
        pass
    else:
        raise AssertionError("negative n should fail")
    print("ok")
```

`round` handles the floating-point wobble in the closed form, and the iterative version stays exact for large `n` where the closed form loses precision.

```c
#include <stdbool.h>
#include <stdio.h>

#define RB_CAP 4

typedef struct {
    int data[RB_CAP];
    size_t head, tail, count;
} ringbuf;

void rb_init(ringbuf *rb) { rb->head = rb->tail = rb->count = 0; }

bool rb_full(const ringbuf *rb) { return rb->count == RB_CAP; }
bool rb_empty(const ringbuf *rb) { return rb->count == 0; }

bool rb_push(ringbuf *rb, int v) {
    if (rb_full(rb)) return false;
    rb->data[rb->tail] = v;
    rb->tail = (rb->tail + 1) % RB_CAP;
    rb->count++;
    return true;
}

bool rb_pop(ringbuf *rb, int *out) {
    if (rb_empty(rb)) return false;
    *out = rb->data[rb->head];
    rb->head = (rb->head + 1) % RB_CAP;
    rb->count--;
    return true;
}

int main(void) {
    ringbuf rb;
    rb_init(&rb);
    for (int i = 0; i < 6; i++) printf("push %d -> %d\n", i, rb_push(&rb, i));
    int v;
    while (rb_pop(&rb, &v)) printf("pop %d\n", v);
    printf("empty: %d\n", rb_empty(&rb));
    return 0;
}
```

`count` disambiguates full from empty so a buffer holding `RB_CAP` items is never mistaken for empty; pushes 4–5 fail because the capacity is 4.

