```cpp
#include <cassert>
#include <iostream>
#include <list>
#include <optional>
#include <unordered_map>

template <typename K, typename V>
class LruCache {
public:
    explicit LruCache(size_t capacity) : cap_(capacity) {}

    std::optional<V> get(const K &key) {
        auto it = map_.find(key);
        if (it == map_.end()) return std::nullopt;
        order_.splice(order_.begin(), order_, it->second);
        return it->second->second;
    }

    void put(const K &key, const V &value) {
        if (cap_ == 0) return;
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->second = value;
            order_.splice(order_.begin(), order_, it->second);
            return;
        }
        if (order_.size() == cap_) {
            map_.erase(order_.back().first);
            order_.pop_back();
        }
        order_.emplace_front(key, value);
        map_[key] = order_.begin();
    }

private:
    size_t cap_;
    std::list<std::pair<K, V>> order_;
    std::unordered_map<K, typename std::list<std::pair<K, V>>::iterator> map_;
};

int main() {
    LruCache<int, std::string> c(2);
    c.put(1, "a");
    c.put(2, "b");
    assert(c.get(1).value() == "a");
    c.put(3, "c");
    assert(!c.get(2).has_value());
    assert(c.get(3).value() == "c");
    assert(c.get(1).value() == "a");
    c.put(4, "d");
    assert(!c.get(3).has_value());
    LruCache<int, int> empty(0);
    empty.put(1, 1);
    assert(!empty.get(1).has_value());
    std::cout << "ok\n";
}
```

`std::list` keeps the recency order while the map stores iterators, so `get` and `put` are O(1); `splice` moves a touched node to the front without invalidating the stored iterator.

