std::string longest_common_prefix(const std::vector<std::string>& words) {
    if (words.empty()) return "";
    std::string prefix = words[0];
    for (const auto& w : words) {
        size_t i = 0;
        while (i < prefix.size() && i < w.size() && prefix[i] == w[i]) ++i;
        prefix.resize(i);
        if (prefix.empty()) break;
    }
    return prefix;
}

