fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 4, 6, 8, 9];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);

    let empty: [i32; 0] = [];
    assert_eq!(merge_sorted(&a, &empty), vec![1, 3, 5, 7]);
    assert_eq!(merge_sorted(&empty, &empty), Vec::<i32>::new());

    let dups = [1, 2, 2];
    let more = [2, 3];
    assert_eq!(merge_sorted(&dups, &more), vec![1, 2, 2, 2, 3]);

    println!("all assertions passed");
}
