#include <cstdint>
#include <string>
#include <optional>
#include <cctype>

std::optional<uint32_t> parse_u32(const std::string& s) {
    if (s.empty()) return std::nullopt;

    size_t i = 0;
    while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
    if (i == s.size()) return std::nullopt;

    uint64_t acc = 0;
    bool any = false;
    for (; i < s.size(); ++i) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        if (c < '0' || c > '9') break;
        any = true;
        acc = acc * 10 + static_cast<uint64_t>(c - '0');
        if (acc > 0xFFFFFFFFull) return std::nullopt;
    }
    if (!any) return std::nullopt;

    while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
    if (i != s.size()) return std::nullopt;

    return static_cast<uint32_t>(acc);
}
```

Accumulating in `uint64_t` before the range check avoids overflow of the accumulator itself. Leading and trailing whitespace are allowed, sign characters are rejected, and any non-digit residue fails the parse.

```rust
pub fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

