Iterative fill up to `n` with `unsigned long long`. F(93) overflows 64 bits, so we cap at 90 as requested.

```cpp
#include <iostream>
#include <vector>
#include <cstdint>

unsigned long long fib_memo(int n) {
    if (n < 0 || n > 90) {
        throw std::out_of_range("n must be in [0, 90]");
    }
    std::vector<unsigned long long> memo(n + 1, 0);
    if (n >= 1) memo[1] = 1;
    for (int i = 2; i <= n; ++i) {
        memo[i] = memo[i - 1] + memo[i - 2];
    }
    return memo[n];
}

int main() {
    for (int n : {0, 1, 2, 10, 50, 90}) {
        std::cout << "F(" << n << ") = " << fib_memo(n) << '\n';
    }
    try {
        fib_memo(91);
    } catch (const std::out_of_range& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
