Two-pass approach: reverse each word, then reverse the whole buffer. The tokenizer skips runs of spaces and trims ends.

```cpp
#include <iostream>
#include <string>
#include <algorithm>

std::string reverse_words(const std::string& input) {
    std::string s;
    s.reserve(input.size());
    size_t i = 0;
    while (i < input.size()) {
        while (i < input.size() && input[i] == ' ') ++i;
        if (i >= input.size()) break;
        size_t start = i;
        while (i < input.size() && input[i] != ' ') ++i;
        if (!s.empty()) s.push_back(' ');
        s.append(input, start, i - start);
    }
    std::reverse(s.begin(), s.end());
    size_t word = 0;
    for (size_t j = 0; j <= s.size(); ++j) {
        if (j == s.size() || s[j] == ' ') {
            std::reverse(s.begin() + word, s.begin() + j);
            word = j + 1;
        }
    }
    return s;
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::cout << reverse_words(line) << '\n';
    }
    return 0;
}
```

Input `"  the quick   brown  fox "` yields `"fox brown quick the"`. Leading, trailing, and repeated spaces are normalized away.

Lowercase, split on non-alphanumeric characters, count into a `HashMap`, then sort by frequency descending and word ascending for stable ties.

```rust
use std::collections::HashMap;

pub fn top_k_words(text: &str, k: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text
        .split(|c: char| !c.is_alphanumeric())
        .filter(|w| !w.is_empty())
    {
        *counts.entry(word.to_lowercase()).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(k);
    pairs
}

fn main() {
    let text = "The quick brown fox. The FOX runs; the fox jumps!";
    for (word, count) in top_k_words(text, 3) {
        println!("{word}: {count}");
    }
    println!("{:?}", top_k_words("", 5));
}
```

