#include <cctype>
#include <iostream>
#include <string>

bool is_palindrome(const std::string& s) {
    std::size_t left = 0;
    std::size_t right = s.size();
    while (left < right) {
        while (left < right && !std::isalnum(static_cast<unsigned char>(s[left]))) ++left;
        while (left < right && !std::isalnum(static_cast<unsigned char>(s[right - 1]))) --right;
        if (left >= right) break;
        char a = static_cast<char>(std::tolower(static_cast<unsigned char>(s[left])));
        char b = static_cast<char>(std::tolower(static_cast<unsigned char>(s[right - 1])));
        if (a != b) return false;
        ++left;
        --right;
    }
    return true;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_palindrome("A man, a plan, a canal: Panama") << '\n';  // true
    std::cout << is_palindrome("race a car") << '\n';                     // false
    std::cout << is_palindrome("") << '\n';                               // true
    std::cout << is_palindrome("!!") << '\n';                             // true
    return 0;
}
