class MinStack:
    def __init__(self):
        self._data = []
        self._mins = []

    def push(self, value):
        self._data.append(value)
        self._mins.append(value if not self._mins else min(value, self._mins[-1]))

    def pop(self):
        if not self._data:
            raise IndexError("pop from empty stack")
        self._mins.pop()
        return self._data.pop()

    def peek(self):
        if not self._data:
            raise IndexError("peek from empty stack")
        return self._data[-1]

    def get_min(self):
        if not self._mins:
            raise IndexError("min from empty stack")
        return self._mins[-1]

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    s = MinStack()
    for v in (5, 3, 7, 3, 2):
        s.push(v)
    assert s.get_min() == 2
    assert s.pop() == 2
    assert s.get_min() == 3
    assert s.pop() == 3
    assert s.get_min() == 3
    assert s.peek() == 7
    assert len(s) == 2
    print("ok")
```

The second list tracks the minimum of all values currently below it, so each operation is one push or pop and no scan is needed.

