fn to_binary(mut n: i64) -> String {
    if n == 0 {
        return "0".to_string();
    }
    let negative = n < 0;
    let mut digits = Vec::new();
    let mut magnitude = (n as i128).unsigned_abs();
    while magnitude > 0 {
        digits.push(b'0' + (magnitude % 2) as u8);
        magnitude /= 2;
    }
    let mut out = String::new();
    if negative {
        out.push('-');
    }
    for d in digits.iter().rev() {
        out.push(*d as char);
    }
    out
}

fn main() {
    assert_eq!(to_binary(0), "0");
    assert_eq!(to_binary(10), "1010");
    assert_eq!(to_binary(-6), "-110");
    assert_eq!(to_binary(255), "11111111");
    println!("ok");
}
```

Casting through `i128` makes `i64::MIN`'s magnitude representable, so the edge value does not overflow; the sign is emitted separately and digits are collected least-significant first, then reversed.

