use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

struct Counter {
    value: AtomicUsize,
}

impl Counter {
    fn new() -> Self {
        Counter { value: AtomicUsize::new(0) }
    }

    fn increment(&self) -> usize {
        self.value.fetch_add(1, Ordering::SeqCst) + 1
    }

    fn get(&self) -> usize {
        self.value.load(Ordering::SeqCst)
    }
}

