template <std::size_t N>
class RingBuffer {
public:
    bool push(int v) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int v = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }

    std::optional<int> front() const {
        if (size_ == 0) return std::nullopt;
        return data_[head_];
    }

    std::size_t size() const { return size_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1);
    rb.push(2);
    rb.push(3);
