#include <algorithm>
#include <array>
#include <iostream>
#include <string>

// Sliding window. last[c] holds the index after the previous occurrence of c.
int longest_unique_substring(const std::string& s) {
    std::array<int, 256> last;
    last.fill(-1);
    int best = 0;
    int start = 0;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        if (last[c] >= start) {
            start = last[c] + 1;
        }
        last[c] = i;
        best = std::max(best, i - start + 1);
    }
    return best;
}

int main() {
    std::cout << longest_unique_substring("abcabcbb") << '\n';  // 3
    std::cout << longest_unique_substring("bbbbb") << '\n';     // 1
    std::cout << longest_unique_substring("") << '\n';          // 0
    return 0;
}
```
The window only moves forward, so the loop is O(n). Casting the byte to `unsigned char` keeps the index safe for non-ASCII input, and empty input returns 0.

