use std::io::{self, Read};

fn parse_and_summarize(input: &str) -> Result<(i64, i64), String> {
    let mut sum: i64 = 0;
    let mut max: Option<i64> = None;
    for token in input.split_whitespace() {
        let value: i64 = token
            .parse()
            .map_err(|_| format!("not an integer: {token:?}"))?;
        sum = sum.checked_add(value).ok_or("integer overflow")?;
        max = Some(max.map_or(value, |m| m.max(value)));
    }
    match max {
        Some(m) => Ok((sum, m)),
        None => Err("no integers provided".to_string()),
    }
}

fn main() {
    let mut raw = String::new();
    io::stdin().read_to_string(&mut raw).expect("read stdin");
    // split_whitespace already treats \r\n as whitespace.
    match parse_and_summarize(&raw) {
        Ok((sum, max)) => println!("sum={sum} max={max}"),
        Err(msg) => eprintln!("error: {msg}"),
    }
}
