#include <cstdio>
#include <stdexcept>
#include <string>
#include <utility>

class File {
public:
    // Throws std::runtime_error if the file cannot be opened.
    File(const std::string& path, const char* mode) {
        handle_ = std::fopen(path.c_str(), mode);
        if (handle_ == nullptr) {
            throw std::runtime_error("cannot open " + path);
        }
    }

    File(const File&) = delete;
    File& operator=(const File&) = delete;

    File(File&& other) noexcept : handle_(other.handle_) {
        other.handle_ = nullptr;
    }

    File& operator=(File&& other) noexcept {
        if (this != &other) {
            close();
            handle_ = std::exchange(other.handle_, nullptr);
        }
        return *this;
    }

    ~File() { close(); }

    std::FILE* get() const noexcept { return handle_; }
    bool valid() const noexcept { return handle_ != nullptr; }

private:
    void close() noexcept {
        if (handle_ != nullptr) {
            std::fclose(handle_);
            handle_ = nullptr;
        }
    }

    std::FILE* handle_ = nullptr;
};
```
Copying is deleted so two owners can't double-close the handle; the move constructor nulls the source and the destructor closes only a non-null handle. `std::exchange` makes the move-assignment self-cleaning in one step.

