int binary_search(const std::vector<int>& a, int target) {
    int lo = 0, hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> a{-7, -1, 0, 3, 9, 42};
    std::cout << binary_search(a, 3) << '\n';
    std::cout << binary_search(a, 100) << '\n';
    std::cout << binary_search({}, 1) << '\n';
    return 0;
}
```
`mid` is computed as `lo + (hi - lo) / 2` to avoid overflow, and an empty vector falls straight to `-1`.

