template <typename T, std::size_t N>
class RingBuffer {
    static_assert(N > 0, "capacity must be positive");
    std::array<T, N> buf_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;

public:
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

    void push(const T& value) {
        if (full()) throw std::overflow_error("ring buffer full");
        buf_[(head_ + size_) % N] = value;
        ++size_;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T out = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return out;
    }
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(10);
    rb.push(20);
    rb.push(30);
    if (rb.full() && rb.pop() == 10 && rb.pop() == 20) {
        rb.push(40);
        return rb.pop() == 30 && rb.pop() == 40 && rb.empty() ? 0 : 1;
    }
    return 1;
}
