#include <vector>

bool is_valid_ipv4(const std::string& s) {
    if (s.empty()) return false;
    std::vector<std::string> parts;
    std::stringstream ss(s);
    std::string part;
    while (std::getline(ss, part, '.')) parts.push_back(part);
    if (parts.size() != 4) return false;
    for (const auto& p : parts) {
        if (p.empty() || p.size() > 3) return false;
        for (char c : p) if (!std::isdigit(static_cast<unsigned char>(c))) return false;
        if (p.size() > 1 && p[0] == '0') return false; // no leading zeros
        int v = std::stoi(p);
        if (v < 0 || v > 255) return false;
    }
    return true;
}

int main() {
    std::cout << std::boolalpha
              << is_valid_ipv4("192.168.0.1") << "\n"
              << is_valid_ipv4("256.1.1.1") << "\n"
              << is_valid_ipv4("1.2.3") << "\n"
              << is_valid_ipv4("01.2.3.4") << "\n";
}
```

The four checks that matter are: exactly four octets, each purely digits, each in 0–255, and no leading zeros. `std::getline` with `'.'` splits the string; a trailing dot yields an empty final part and is rejected.

```cpp
#include <stdexcept>
#include <vector>

class StackEmpty : public std::runtime_error {
public:
    StackEmpty() : std::runtime_error("stack is empty") {}
};

class StackFull : public std::runtime_error {
public:
    StackFull() : std::runtime_error("stack is full") {}
};

template <typename T, std::size_t Max = 1024>
class Stack {
    std::vector<T> data_;
public:
    void push(const T& value) {
        if (data_.size() >= Max) throw StackFull();
        data_.push_back(value);
    }
    T pop() {
        if (data_.empty()) throw StackEmpty();
        T value = data_.back();
        data_.pop_back();
        return value;
    }
    const T& top() const {
        if (data_.empty()) throw StackEmpty();
        return data_.back();
    }
    bool empty() const { return data_.empty(); }
    std::size_t size() const { return data_.size(); }
};
```

`Max` is a non-type template parameter, so `Stack<int, 16>` caps at 16. Separating `StackEmpty` and `StackFull` lets callers catch precisely the failure they hit.

