template <typename T>
class BoundedStack {
public:
    explicit BoundedStack(std::size_t cap) : cap_(cap) {}

    void push(const T& value) {
        if (data_.size() >= cap_) {
            throw std::overflow_error("push on full stack");
        }
        data_.push_back(value);
    }

    T pop() {
        if (data_.empty()) {
            throw std::underflow_error("pop on empty stack");
        }
        T value = data_.back();
        data_.pop_back();
        return value;
    }

private:
    std::size_t cap_;
    std::vector<T> data_;
};

