```cpp
#include <array>
#include <condition_variable>
#include <cstddef>
#include <mutex>
#include <optional>

 template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        not_empty_.notify_one();
        return true;
    }

    std::optional<T> pop() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return size_;
    }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
    mutable std::mutex mutex_;
    std::condition_variable not_empty_;
};

#include <cassert>
#include <thread>

int main() {
    RingBuffer<int, 3> buffer;
    assert(buffer.push(1));
    assert(buffer.push(2));
    assert(buffer.push(3));
    assert(!buffer.push(4));
    assert(buffer.pop() == 1);
    assert(buffer.push(4));
    assert(buffer.pop() == 2);
    assert(buffer.pop() == 3);
    assert(buffer.pop() == 4);
    assert(buffer.pop() == std::nullopt);

    std::thread producer([&] { for (int i = 0; i < 100; ++i) buffer.push(i); });
    std::thread consumer([&] { for (int i = 0; i < 100; ++i) buffer.pop(); });
    producer.join();
    consumer.join();
    return 0;
}
```

The mutex guards `head_`, `size_` and `data_`. `push` returns false when full rather than blocking, and `pop` returns `std::optional` so an empty buffer is representable without sentinel values.

