bool is_palindrome(const std::string& text) {
    std::size_t left = 0;
    std::size_t right = text.size();
    while (left < right) {
        unsigned char l = static_cast<unsigned char>(text[left]);
        unsigned char r = static_cast<unsigned char>(text[right - 1]);
        if (!std::isalnum(l)) {
            ++left;
        } else if (!std::isalnum(r)) {
            --right;
        } else if (std::tolower(l) != std::tolower(r)) {
            return false;
        } else {
            ++left;
            --right;
        }
    }
    return true;
}

