```c
#include <stdio.h>
#include <stdlib.h>

#define INITIAL_CAPACITY 4

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} IntVec;

static int vec_reserve(IntVec *vec, size_t needed) {
    if (needed <= vec->capacity) return 1;
    size_t cap = vec->capacity ? vec->capacity : INITIAL_CAPACITY;
    while (cap < needed) {
        if (cap > (size_t)-1 / 2) return 0;
        cap *= 2;
    }
    int *grown = realloc(vec->data, cap * sizeof(int));
    if (grown == NULL) return 0;
    vec->data = grown;
    vec->capacity = cap;
    return 1;
}

int vec_append(IntVec *vec, int value) {
    if (!vec_reserve(vec, vec->size + 1)) return 0;
    vec->data[vec->size++] = value;
    return 1;
}

int vec_get(const IntVec *vec, size_t index, int *out) {
    if (index >= vec->size) return 0;
    *out = vec->data[index];
    return 1;
}

void vec_free(IntVec *vec) {
    free(vec->data);
    vec->data = NULL;
    vec->size = 0;
    vec->capacity = 0;
}

int main(void) {
    IntVec vec = {NULL, 0, 0};
    for (int i = 0; i < 100; ++i) {
        if (!vec_append(&vec, i * i)) {
            fprintf(stderr, "allocation failed\n");
            vec_free(&vec);
            return 1;
        }
    }
    int value = 0;
    if (!vec_get(&vec, 99, &value) || value != 9801) {
        fprintf(stderr, "unexpected value\n");
        vec_free(&vec);
        return 1;
    }
    if (vec_get(&vec, 100, &value)) {
        fprintf(stderr, "out of range read succeeded\n");
        vec_free(&vec);
        return 1;
    }
    vec_free(&vec);
    puts("ok");
    return 0;
}
```

`vec_get` reports out-of-range reads through its return value instead of asserting. Capacity doubles, the overflow check before multiplication prevents runaway growth, and every failure path frees the buffer.

