// Parses "1,2,3" into {1,2,3}. Empty fields yield nullopt-equivalent markers.
std::optional<std::vector<std::int64_t>> parse_csv_ints(const std::string& input) {
    std::vector<std::int64_t> out;
    std::size_t start = 0;
    while (start <= input.size()) {
        std::size_t comma = input.find(',', start);
        std::string field = input.substr(start, comma == std::string::npos
                                                   ? std::string::npos
                                                   : comma - start);
        if (field.empty()) {
            return std::nullopt;  // reject empty field
        }
        std::int64_t value = 0;
        auto [ptr, ec] = std::from_chars(field.data(), field.data() + field.size(), value);
        if (ec != std::errc() || ptr != field.data() + field.size()) {
            return std::nullopt;  // bad digit or overflow
        }
        out.push_back(value);
        if (comma == std::string::npos) {
            break;
        }
        start = comma + 1;
    }
    return out;
}

