#include <condition_variable>
#include <cstddef>
#include <mutex>
#include <optional>
#include <queue>

// Bounded blocking queue. close() wakes all waiters so they can drain and exit.
template <typename T>
class BlockingQueue {
public:
    explicit BlockingQueue(std::size_t capacity) : cap_(capacity) {}

    bool push(T value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [&] { return closed_ || q_.size() < cap_; });
        if (closed_) return false;
        q_.push(std::move(value));
        not_empty_.notify_one();
        return true;
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;  // closed and drained
        T value = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_full_.notify_all();
        not_empty_.notify_all();
    }

private:
    const std::size_t cap_;
    std::queue<T> q_;
    std::mutex mu_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
    bool closed_ = false;
};

#ifdef UNIT_TEST
#include <cassert>
#include <thread>
#include <vector>
#include <iostream>
int main() {
    BlockingQueue<int> q(2);
    std::vector<int> got;
    std::thread consumer([&] {
        while (auto v = q.pop()) got.push_back(*v);
    });
    for (int i = 0; i < 5; ++i) assert(q.push(i));
    q.close();
    consumer.join();
    assert(got == std::vector<int>({0, 1, 2, 3, 4}));
    assert(!q.push(6));  // closed
    std::cout << "ok\n";
}
#endif
