from typing import List, Tuple

Interval = Tuple[int, int]


def merge_intervals(intervals: List[Interval]) -> List[Interval]:
    """Merge overlapping or touching integer intervals. Half-open [start, end)."""
    if not intervals:
        return []
    ordered = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    merged: List[Interval] = [ordered[0]]
    for start, end in ordered[1:]:
        if start < end and start <= merged[-1][1]:
            last_start, last_end = merged[-1]
            merged[-1] = (last_start, max(last_end, end))
        elif start >= end:
            raise ValueError(f"empty or inverted interval: ({start}, {end})")
        else:
            merged.append((start, end))
    return merged


def covered_length(intervals: List[Interval]) -> int:
    return sum(end - start for start, end in merge_intervals(intervals))


if __name__ == "__main__":
    assert merge_intervals([]) == []
    assert merge_intervals([(1, 4), (2, 6), (8, 10)]) == [(1, 6), (8, 10)]
    assert merge_intervals([(1, 2), (2, 3)]) == [(1, 3)]   # touching merges
    assert covered_length([(0, 5), (3, 8), (20, 22)]) == 10
    try:
        merge_intervals([(5, 5)])
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for empty interval")
    print("ok")
