import hashlib
import os
from collections import defaultdict

CHUNK = 1 << 20


def file_hash(path: str) -> str | None:
    digest = hashlib.sha256()
    try:
        with open(path, "rb") as handle:
            while True:
                block = handle.read(CHUNK)
                if not block:
                    break
                digest.update(block)
    except OSError:
        return None
    return digest.hexdigest()


def find_duplicates(root: str) -> dict[str, list[str]]:
    sizes: dict[int, list[str]] = defaultdict(list)
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            full = os.path.join(dirpath, name)
            try:
                size = os.path.getsize(full)
            except OSError:
                continue
            sizes[size].append(full)

    groups: dict[str, list[str]] = defaultdict(list)
    for size, paths in sizes.items():
        if len(paths) < 2:
            continue
        for path in paths:
            digest = file_hash(path)
            if digest is not None:
                groups[digest].append(path)
    return {h: p for h, p in groups.items() if len(p) > 1}


if __name__ == "__main__":
    import sys

    target = sys.argv[1] if len(sys.argv) > 1 else "."
    for digest, paths in find_duplicates(target).items():
        print(digest[:12], "->")
        for path in paths:
            print("   ", path)
