template <typename T>
long long binary_search_index(const std::vector<T>& data, const T& target) {
    long long low = 0;
    long long high = static_cast<long long>(data.size()) - 1;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (data[mid] == target) {
            return mid;
        }
        if (data[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}

