```rust
fn merge_sorted(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    let mut merged = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            merged.push(a[i]);
            i += 1;
        } else {
            merged.push(b[j]);
            j += 1;
        }
    }
    merged.extend_from_slice(&a[i..]);
    merged.extend_from_slice(&b[j..]);
    merged
}

fn main() {
    assert_eq!(merge_sorted(vec![], vec![]), Vec::<i32>::new());
    assert_eq!(merge_sorted(vec![1, 3, 5], vec![2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(vec![], vec![7, 8]), vec![7, 8]);
    assert_eq!(merge_sorted(vec![1, 1, 2], vec![1, 3]), vec![1, 1, 1, 2, 3]);
    println!("{:?}", merge_sorted(vec![0, 2], vec![1, 3]));
}
