/// A simple rolling hash (FNV-1a 64-bit), suitable for change detection,
/// NOT for cryptographic use.
fn fnv1a64(bytes: &[u8]) -> u64 {
    const OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
    const PRIME: u64 = 0x0000_0100_0000_01b3;
    bytes.iter().fold(OFFSET, |hash, &b| (hash ^ b as u64).wrapping_mul(PRIME))
}

fn main() {
    assert_eq!(fnv1a64(b""), 0xcbf2_9ce4_8422_2325);
    assert_eq!(fnv1a64(b"a"), 0xaf63_dc4c_8601_ec8c);
    assert_eq!(fnv1a64(b"foobar"), 0x85944171f73967e8);
    // Rolling property: changing one byte changes the digest.
    assert_ne!(fnv1a64(b"hello"), fnv1a64(b"hallo"));
    println!("{:016x}", fnv1a64(b"hello world"));
}
```
`wrapping_mul` makes overflow well-defined; the empty slice yields the offset basis. This is FNV-1a, not SHA-256 — it detects accidental changes, not tampering.

