#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size()) - 1;

    while (lo <= hi) {
        // Avoid overflow: (lo + hi) could exceed int range in theory.
        int mid = lo + (hi - lo) / 2;
        if (data[mid] == target) {
            return mid;
        }
        if (data[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    std::vector<int> data = {-7, -2, 0, 3, 9, 14, 21};

    std::cout << binary_search(data, 9) << "\n";    // 4
    std::cout << binary_search(data, -7) << "\n";   // 0
    std::cout << binary_search(data, 21) << "\n";   // 6
    std::cout << binary_search(data, 5) << "\n";    // -1
    std::cout << binary_search({}, 1) << "\n";      // -1
    return 0;
}
```

