```python
from collections import deque


class BoundedQueue:
    """FIFO queue that keeps at most `capacity` items.

    When full, pushing evicts the oldest item and returns it.
    """

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._items = deque()

    def push(self, item):
        """Add an item; return the evicted item, or None if nothing evicted."""
        evicted = None
        if len(self._items) >= self.capacity:
            evicted = self._items.popleft()
        self._items.append(item)
        return evicted

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty queue")
        return self._items.popleft()

    def __len__(self):
        return len(self._items)

    def __iter__(self):
        return iter(self._items)


if __name__ == "__main__":
    q = BoundedQueue(3)
    print(q.push("a"), q.push("b"), q.push("c"))   # None None None
    print(q.push("d"))                              # a  (evicted)
    print(list(q))                                  # b c d
    try:
        BoundedQueue(0)
    except ValueError as exc:
        print(f"rejected: {exc}")
```

`deque.popleft` is O(1), so eviction is cheap even at large capacities. `push` returns the evicted value rather than silently discarding it, which lets a caller decide what to do with overflow. A zero or negative capacity is rejected at construction.

