        char tmp = s[start];
        s[start] = s[end];
        s[end] = tmp;
        start++;
        end--;
    }
}

void reverse_words(char *s) {
    size_t len = strlen(s);
    if (len == 0) return;

    reverse_range(s, 0, len - 1);       /* whole string */

    size_t i = 0;
    while (i < len) {
        if (isspace((unsigned char)s[i])) {
            i++;
            continue;
        }
        size_t j = i;
        while (j < len && !isspace((unsigned char)s[j])) j++;
        reverse_range(s, i, j - 1);     /* each word back */
        i = j;
    }
}

int main(void) {
    char buf[] = "the quick   brown fox";
    reverse_words(buf);
    printf("%s\n", buf);   /* fox brown   quick the */
    return 0;
}
```

The classic two-pass trick: reversing the entire buffer puts words in the right order but each word backwards, then reversing each word individually fixes that. Whitespace runs between words are reversed too, which is why the triple space stays intact in the middle of the output. Everything happens in place with O(1) extra space; `(unsigned char)` casts keep `isspace` safe for values above 127.

```rust
use std::collections::HashMap;

fn word_frequencies(text: &str) -> HashMap<String, usize> {
    let mut counts = HashMap::new();
    for word in text.split(|c: char| !c.is_alphanumeric()) {
        if word.is_empty() {
            continue;
        }
        *counts.entry(word.to_lowercase()).or_insert(0) += 1;
    }
    counts
}

fn top_n(counts: &HashMap<String, usize>, n: usize) -> Vec<(String, usize)> {
    let mut pairs: Vec<_> = counts.iter().map(|(k, v)| (k.clone(), *v)).collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The cat, the CAT; a dog. The dog barks!";
    let counts = word_frequencies(text);
    for (word, count) in top_n(&counts, 3) {
        println!("{word}: {count}");
    }
}
```

Splitting on a predicate closure of non-alphanumerics handles any punctuation without a regex. Keys are lowercased at insert time so `The`, `the` and `CAT` collapse together. The sort is descending by count with an ascending name tie-break, making repeated runs deterministic; ties in count are broken alphabetically.

```cpp
#include <iostream>
#include <stdexcept>

template <typename T, std::size_t Capacity>
class FixedStack {
public:
    void push(const T& value) {
        if (size_ >= Capacity) {
            throw std::overflow_error("stack full");
        }
        data_[size_++] = value;
    }

    T pop() {
        if (size_ == 0) {
            throw std::underflow_error("stack empty");
        }
        return data_[--size_];
    }

    const T& top() const {
        if (size_ == 0) {
            throw std::underflow_error("stack empty");
        }
        return data_[size_ - 1];
    }

    std::size_t size() const { return size_; }
    static constexpr std::size_t capacity() { return Capacity; }
    bool empty() const { return size_ == 0; }

private:
    T data_[Capacity > 0 ? Capacity : 1]{};
    std::size_t size_ = 0;
};

int main() {
    FixedStack<int, 3> s;
    s.push(10);
    s.push(20);
    s.push(30);
    try {
        s.push(40);
    } catch (const std::overflow_error& e) {
        std::cout << "push failed: " << e.what() << '\n';
    }
    std::cout << "top: " << s.top() << " size: " << s.size() << '\n';

    FixedStack<int, 0> zero;
    try {
        zero.pop();
    } catch (const std::underflow_error& e) {
        std::cout << "pop failed: " << e.what() << '\n';
    }
    return 0;
}
```

Capacity is a template parameter so the array is a real member, not a heap allocation. The ternary `Capacity > 0 ? Capacity : 1` keeps a zero-capacity stack legal C++ (a zero-length array is not standard), while `push` still throws because `size_ >= 0`. Both error paths use the standard exception types rather than a custom class.

```cpp
#include <cctype>
#include <iostream>
#include <string>

static bool is_palindrome(const std::string& s) {
    std::size_t i = 0;
    std::size_t j = s.size();
    while (i < j) {
        if (i < j && !std::isalnum(static_cast<unsigned char>(s[i]))) { ++i; continue; }
        if (i < j && !std::isalnum(static_cast<unsigned char>(s[j - 1]))) { --j; continue; }
        if (std::tolower(static_cast<unsigned char>(s[i])) !=
            std::tolower(static_cast<unsigned char>(s[j - 1]))) {
            return false;
        }
        ++i;
        --j;
    }
    return true;
}

int main() {
    const std::string cases[] = {
        "",
        "A man, a plan, a canal: Panama",
        "race a car",
        "No 'x' in Nixon",
        "12321",
        "!!!",
    };
    for (const auto& c : cases) {
        std::cout << '"' << c << "\" -> " << (is_palindrome(c) ? "true" : "false") << '\n';
    }
    return 0;
}
```

Two indices walk inward, skipping non-alphanumerics and comparing lowercased bytes. Casting through `unsigned char` before `isalnum`/`tolower` avoids undefined behaviour on negative `char` values.

```rust
use std::collections::HashMap;

/// Return the `n` most frequent words, ranked by count (ties broken alphabetically).
pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '\'')
            .flat_map(|c| c.to_lowercase())
            .collect();
        if word.is_empty() {
            continue;
        }
        *counts.entry(word).or_insert(0) += 1;
    }

    let mut items: Vec<(String, usize)> = counts.into_iter().collect();
    items.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    items.truncate(n);
    items
}

