Splits on whitespace, strips punctuation apart from apostrophes, lowercases (including Unicode), tallies in a `HashMap`, then sorts by descending count with an alphabetical tiebreak. `truncate` safely handles `n` larger than the number of distinct words.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node* next;
} Node;

static Node* push(Node* head, int value) {
    Node* n = malloc(sizeof(Node));
    if (n == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static Node* reverse(Node* head) {
    Node* prev = NULL;
    while (head != NULL) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(const Node* head) {
    for (const Node* n = head; n != NULL; n = n->next) {
        printf("%d", n->value);
        if (n->next != NULL) printf(" -> ");
    }
    printf("\n");
}

static void free_list(Node* head) {
    while (head != NULL) {
        Node* next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node* list = NULL;
    for (int i = 5; i >= 1; --i) list = push(list, i);
    printf("before: ");
    print_list(list);
    list = reverse(list);
    printf("after:  ");
    print_list(list);
    free_list(list);

    // Empty list edge case.
    list = reverse(NULL);
    printf("empty:  ");
    print_list(list);
    return 0;
}
```

Iterative reversal relinks each node's `next` pointer to the previous node in one pass, O(n) time and O(1) space. The empty list returns `NULL` unchanged, and `free_list` runs after the reversal to release memory.

