```cpp
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <unordered_map>

class Fibonacci {
public:
    // Iterative + memo table so repeated queries are O(1).
    std::uint64_t get(unsigned n) {
        auto it = memo_.find(n);
        if (it != memo_.end()) return it->second;
        std::uint64_t a = 0, b = 1;
        for (unsigned i = 2; i <= n; ++i) {
            std::uint64_t next = a + b;
            if (next < b) {
                throw std::overflow_error("fib value exceeds 64 bits at index " +
                                          std::to_string(i));
            }
            a = b;
            b = next;
        }
        // n == 0 -> 0, n == 1 -> 1
        std::uint64_t result = (n == 0) ? 0 : b;
        memo_[n] = result;
        return result;
    }

private:
    std::unordered_map<unsigned, std::uint64_t> memo_;
};

int main() {
    Fibonacci fib;
    const unsigned cases[] = {0, 1, 2, 10, 50, 90, 93};
    for (unsigned n : cases) {
        try {
            std::cout << "fib(" << n << ") = " << fib.get(n) << '\n';
        } catch (const std::exception& e) {
            std::cout << "fib(" << n << ") -> " << e.what() << '\n';
        }
    }
    return 0;
}
```

It computes bottom-up while filling the memo, which avoids recursion depth issues. The carry check `next < b` detects 64-bit wraparound before it silently corrupts a result, and `fib(93)` is where `unsigned long long` actually overflows.

```python
import re
import sys
from collections import Counter

WORD_RE = re.compile(r"[^\W\d_]+", re.UNICODE)


def top_words(path: str, limit: int = 5) -> list[tuple[str, int]]:
    counts: Counter[str] = Counter()
    with open(path, encoding="utf-8", errors="replace") as fh:
        for line in fh:
            for match in WORD_RE.finditer(line.casefold()):
                counts[match.group()] += 1
    return counts.most_common(limit)


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("usage: word_freq.py <file>")
    for word, n in top_words(sys.argv[1]):
        print(f"{word}\t{n}")
```

`casefold()` is the right fold for unicode (it maps `ß` to `ss` and handles the Turkish dotted-i family better than `lower()`). `[^\W\d_]+` is the unicode-aware "letters only" class: `\W` is the non-word set, so its complement within word characters plus the explicit exclusions of digits and underscore leaves letters. Opening with `errors="replace"` means a stray invalid byte becomes U+FFFD instead of raising mid-scan, which keeps a long run from aborting at byte 900 million.

```cpp
#include <condition_variable>
#include <cstddef>
#include <iostream>
#include <mutex>
#include <optional>
#include <queue>
#include <thread>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    // Blocks while full. Returns false once shutdown was requested and no
    // further items can be pushed.
    bool push(T value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [&] { return closed_ || q_.size() < cap_; });
        if (closed_) return false;
        q_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }

    // Blocks while empty. nullopt means: closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;
        T value = std::move(q_.front());
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mu_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<T> q_;
    std::mutex mu_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
    bool closed_ = false;
};

int main() {
    constexpr int kItems = 20;
    BoundedQueue<int> queue(4);
    long long sum = 0;

    std::thread producer([&] {
        for (int i = 1; i <= kItems; ++i) queue.push(i);
        queue.close();
    });

    std::thread consumer([&] {
        while (auto item = queue.pop()) sum += *item;
    });

    producer.join();
    consumer.join();

    const long long expected = static_cast<long long>(kItems) * (kItems + 1) / 2;
    std::cout << "sum=" << sum << " expected=" << expected << '\n';
    return sum == expected ? 0 : 1;
}
```

Two separate condition variables keep a slow consumer from waking producers that cannot make progress. Both waits use a predicate, so spurious wakeups are handled without extra logic. `pop()` returns `nullopt` only when `closed_` is set *and* the queue is drained, which is what lets the consumer loop terminate cleanly instead of racing on a sentinel value.

```cpp
#include <cstdio>
#include <memory>
#include <stdexcept>
#include <string>

struct FileCloser {
    void operator()(std::FILE* f) const noexcept {
        if (f) std::fclose(f);
    }
};

using FilePtr = std::unique_ptr<std::FILE, FileCloser>;

FilePtr open_file(const std::string& path) {
    if (std::FILE* raw = std::fopen(path.c_str(), "rb"))
        return FilePtr(raw);
    throw std::runtime_error("cannot open: " + path);
}

std::string read_all(const std::string& path) {
    FilePtr file = open_file(path);
    std::string out;
    char buffer[4096];
    std::size_t n;
    while ((n = std::fread(buffer, 1, sizeof buffer, file.get())) > 0)
        out.append(buffer, n);
    if (std::ferror(file.get()))
        throw std::runtime_error("read error on: " + path);
    return out;  // empty file -> empty string, no special case needed
}

int main() {
    try {
        std::string text = read_all("/etc/hostname");
        std::printf("read %zu bytes\n", text.size());
    } catch (const std::exception& e) {
        std::printf("error: %s\n", e.what());
        return 1;
    }
    return 0;
}
```

`fread` returning 0 is the normal end-of-file signal, so the loop handles an empty file naturally: zero iterations, empty string. The `ferror` check after the loop distinguishes "hit EOF" from "hit an I/O error", which a bare `while (fread(...))` would silently conflate. The deleter is `noexcept` as required, and wrapping it in `unique_ptr` means the file closes on every return path including the throw.

```rust
use std::collections::HashMap;

/// LRU cache with O(1) get/put. Nodes live in a Vec; links are indices, so
/// no unsafe pointer chasing is needed.
pub struct LruCache<K, V> {
    map: HashMap<K, usize>,
    nodes: Vec<Node<K, V>>,
    free: Vec<usize>,
    head: Option<usize>, // most recently used
    tail: Option<usize>, // least recently used
    cap: usize,
}

struct Node<K, V> {
    key: K,
    value: V,
    prev: Option<usize>,
    next: Option<usize>,
}

impl<K: std::hash::Hash + Eq + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        Self { map: HashMap::new(), nodes: Vec::new(), free: Vec::new(), head: None, tail: None, cap }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        let idx = *self.map.get(key)?;
        self.unlink(idx);
        self.push_front(idx);
        Some(&self.nodes[idx].value)
    }

    pub fn put(&mut self, key: K, value: V) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].value = value;
            self.unlink(idx);
            self.push_front(idx);
            return;
        }
        if self.map.len() == self.cap {
            if let Some(old_tail) = self.tail {
                self.unlink(old_tail);
                let evicted = std::mem::replace(&mut self.nodes[old_tail].key, key.clone());
                self.map.remove(&evicted);
                self.map.insert(key, old_tail);
                self.nodes[old_tail].value = value;
                self.push_front(old_tail);
                return;
            }
        }
        let idx = if let Some(reused) = self.free.pop() {
            self.nodes[reused].key = key.clone();
            self.nodes[reused].value = value;
            self.nodes[reused].prev = None;
            self.nodes[reused].next = None;
            reused
        } else {
            self.nodes.push(Node { key: key.clone(), value, prev: None, next: None });
            self.nodes.len() - 1
        };
        self.map.insert(key, idx);
        self.push_front(idx);
    }

    fn unlink(&mut self, idx: usize) {
        let (prev, next) = (self.nodes[idx].prev, self.nodes[idx].next);
        match prev {
            Some(p) => self.nodes[p].next = next,
            None => self.head = next,
        }
        match next {
            Some(n) => self.nodes[n].prev = prev,
            None => self.tail = prev,
        }
        self.nodes[idx].prev = None;
        self.nodes[idx].next = None;
    }

    fn push_front(&mut self, idx: usize) {
        self.nodes[idx].prev = None;
        self.nodes[idx].next = self.head;
        if let Some(h) = self.head {
            self.nodes[h].prev = Some(idx);
        }
        self.head = Some(idx);
        if self.tail.is_none() {
            self.tail = Some(idx);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::LruCache;

    #[test]
    fn evicts_least_recently_used() {
        let mut c = LruCache::new(2);
        c.put("a", 1);
        c.put("b", 2);
        assert_eq!(c.get(&"a"), Some(&1)); // "a" is now MRU
        c.put("c", 3);                     // evicts "b"
        assert_eq!(c.get(&"b"), None);
        assert_eq!(c.get(&"a"), Some(&1));
        assert_eq!(c.get(&"c"), Some(&3));
    }

    #[test]
    fn updates_existing_key() {
        let mut c = LruCache::new(2);
        c.put(1, 10);
        c.put(1, 11);
        assert_eq!(c.get(&1), Some(&11));
    }

    #[test]
    fn handles_capacity_one() {
        let mut c = LruCache::new(1);
        c.put(1, 1);
        c.put(2, 2);
        assert_eq!(c.get(&1), None);
        assert_eq!(c.get(&2), Some(&2));
    }
}
```

Using `Vec` indices instead of `Box` pointers keeps the links `Copy` and avoids `unsafe`; the visited index is unlinked then pushed to the front, which is what makes `get` a mutation (the `&mut self` receiver is the honest signature). The eviction path reuses the tail node's storage and swaps in the new key rather than allocating, so a steady-state of misses does not grow the `nodes` vector. Run the tests with `cargo test`.

```rust
use std::thread;

#[derive(Debug, PartialEq)]
pub struct Summary {
    pub words: usize,
    pub longest: String,
}

pub fn analyze(text: &str, threads: usize) -> Summary {
    let threads = threads.max(1);
    let bytes = text.as_bytes();
    let chunk = bytes.len().div_ceil(threads);

    // Cut on ASCII whitespace so no slice splits a UTF-8 codepoint or a word.
    let mut bounds = vec![0usize];
    for i in 1..threads {
        let mut cut = (i * chunk).min(bytes.len());
        while cut < bytes.len() && !bytes[cut].is_ascii_whitespace() {
            cut += 1;
        }
        if cut > *bounds.last().unwrap() {
            bounds.push(cut);
        }
    }
    bounds.push(bytes.len());

    let mut words = 0usize;
    let mut longest = String::new();

    thread::scope(|scope| {
        let handles: Vec<_> = bounds
            .windows(2)
            .map(|pair| {
                let slice = &text[pair[0]..pair[1]];
                scope.spawn(move || {
                    let mut count = 0usize;
                    let mut best = "";
                    for w in slice.split_whitespace() {
                        count += 1;
                        if w.len() > best.len() {
                            best = w;
                        }
                    }
                    (count, best)
                })
            })
            .collect();

        for handle in handles {
            let (count, best) = handle.join().expect("worker panicked");
            words += count;
            if best.len() > longest.len() {
                longest = best.to_owned();
            }
        }
    });

    Summary { words, longest }
}

fn main() {
    let text = "the quick brown fox jumps over the lazy dog ünïcode";
    let s = analyze(text, 4);
    assert_eq!(s.words, text.split_whitespace().count());
    assert_eq!(s.longest, "ünïcode".to_string().max("jumps".to_string()).max("quick".to_string()).max("brown".to_string()));
    println!("{s:?}");
}
```

`thread::scope` lets workers borrow `text` directly, so there is no `Arc` and no cloning of the input. The chunk boundaries are advanced to the next ASCII whitespace before splitting, guaranteeing every slice starts and ends on a code-point boundary *and* on a word boundary, so no word is counted twice. `div_ceil` (stable since 1.73) rounds the chunk size up; distinct topics aside, the correctness hinge is that `bounds` is deduplicated when a cut lands past the last pushed one.

