                for (k=m; k>=j; k--) { vals[k+1]=vals[k]; rows[k+1]=rows[k] }
                if (m < K) m++
                vals[j]=key; rows[j]=payload
                break
            }
        }
    }
    print header
    for (i=1; i<=m; i++) print rows[i]
}'
```

Run it as `cat data.csv | ./top10_by_col3.sh`. The `sub(/\r$/, "", ...)` on every record normalises CRLF input even from a Windows tool, and awk treats a final record with no newline as a normal record, so the missing-trailing-newline case needs no special handling. Rows without a third field are skipped rather than treated as 0, which would otherwise rank junk near the bottom. The insertion sort keeps only the top 10 in memory, so the script stays usable on a stream larger than RAM.

```python
import random
import time
from dataclasses import dataclass


class FetchError(Exception):
    def __init__(self, attempts: int, last: Exception | None):
        super().__init__(f"giving up after {attempts} attempts: {last}")
        self.attempts = attempts
        self.last = last


@dataclass
class RetryPolicy:
    attempts: int = 5
    base: float = 0.1
    cap: float = 2.0
    deadline: float | None = None  # absolute monotonic time

    def delay(self, attempt: int, rng: random.Random) -> float:
        # Full jitter: uniform in [0, min(cap, base * 2**attempt)]
        bound = min(self.cap, self.base * (2 ** attempt))
        return rng.uniform(0.0, bound)


def fetch(call, policy: RetryPolicy | None = None, rng: random.Random | None = None):
    """Call `call()` until it returns, retrying on Exception.

    `call` is any zero-arg callable; the transport is injected so this is
    testable without a socket.
    """
    policy = policy or RetryPolicy()
    rng = rng or random.Random()
    last: Exception | None = None

    for attempt in range(policy.attempts):
        if policy.deadline is not None and time.monotonic() > policy.deadline:
            raise FetchError(attempt, last)
        try:
            return call()
        except Exception as exc:  # noqa: BLE001 - deliberate catch-all for retry
            last = exc
            if attempt == policy.attempts - 1:
                break
            delay = policy.delay(attempt, rng)
            if policy.deadline is not None:
                remaining = policy.deadline - time.monotonic()
                if remaining <= 0:
                    break
                delay = min(delay, remaining)
            time.sleep(delay)

    raise FetchError(policy.attempts, last)


if __name__ == "__main__":
    rng = random.Random(7)
    state = {"n": 0}

    def flaky():
        state["n"] += 1
        if state["n"] < 3:
            raise TimeoutError(f"transient {state['n']}")
        return f"ok on try {state['n']}"

    print(fetch(flaky, RetryPolicy(attempts=5, base=0.0), rng))

    def always_fails():
        raise ConnectionError("refused")

    try:
        fetch(always_fails, RetryPolicy(attempts=3, base=0.0), rng)
    except FetchError as exc:
        print(f"expected failure: {exc}")
```

Full jitter is the AWS-recommended variant and it is what stops a fleet of clients from retrying in lockstep. Injecting `call` and `rng` keeps the helper deterministic under test (`base=0.0` makes the sleeps zero-width), and the deadline is re-checked after every attempt *and* clamped into the sleep, so a long backoff cannot overshoot a caller's budget.

