```c
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse_list(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    assert(n != NULL);
    n->value = value;
    n->next = head;
    return n;
}

int main(void) {
    Node *list = NULL;
    for (int i = 1; i <= 5; ++i) list = push(list, i);

    list = reverse_list(list);

    int expected = 1;
    for (Node *cur = list; cur != NULL; cur = cur->next) {
        assert(cur->value == expected++);
        printf("%d ", cur->value);
    }
    printf("\n");

    assert(reverse_list(NULL) == NULL);

    while (list != NULL) {
        Node *next = list->next;
        free(list);
        list = next;
    }
    return 0;
}
```
The loop rewires each `next` pointer to the previous node and advances, so the list is reversed in O(n) time and O(1) extra space. The NULL case is covered and the harness frees every node.

