def parse_config(text: str) -> dict:
    """Parse 'a.b=1; c=2' into {'a': {'b': '1'}, 'c': '2'}."""
    result: dict = {}
    for chunk in text.split(";"):
        chunk = chunk.strip()
        if not chunk:
            continue
        if "=" not in chunk:
            raise ValueError(f"missing '=' in segment: {chunk!r}")
        key_path, _, value = chunk.partition("=")
        keys = [k.strip() for k in key_path.split(".") if k.strip()]
        if not keys:
            raise ValueError(f"empty key in segment: {chunk!r}")
        node = result
        for key in keys[:-1]:
            child = node.get(key)
            if child is None:
                child = {}
                node[key] = child
            elif not isinstance(child, dict):
                raise ValueError(f"key conflict at {key!r}")
            node = child
        node[keys[-1]] = value.strip()
    return result


if __name__ == "__main__":
    got = parse_config("a.b=1; a.c=2; d=3 ; ;")
    assert got == {"a": {"b": "1", "c": "2"}, "d": "3"}, got
    try:
        parse_config("a.b=1; a=2")
    except ValueError as exc:
        print("expected error:", exc)
    print("ok", got)
```
Dotted keys create nested dicts lazily; empty segments and whitespace are ignored. A later scalar assignment to a key that is already a dict raises `ValueError` instead of silently clobbering the subtree.

