def longest_common_prefix(strs):
    """Return the longest common prefix of a list of strings."""
    if not strs:
        return ""
    first = strs[0]
    for i, ch in enumerate(first):
        for other in strs[1:]:
            if i >= len(other) or other[i] != ch:
                return first[:i]
    return first


