#[derive(Debug)]
struct Node {
    key: i32,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
}

fn insert(root: &mut Option<Box<Node>>, key: i32) {
    match root {
        None => *root = Some(Box::new(Node { key, left: None, right: None })),
        Some(node) => {
            if key < node.key {
                insert(&mut node.left, key);
            } else if key > node.key {
                insert(&mut node.right, key);
            }
        }
    }
}

fn contains(root: &Option<Box<Node>>, key: i32) -> bool {
    let mut cur = root;
    while let Some(node) = cur {
        if key == node.key {
            return true;
        }
        cur = if key < node.key { &node.left } else { &node.right };
    }
    false
}

fn main() {
    let mut root: Option<Box<Node>> = None;
    for k in [8, 3, 10, 1, 6, 14, 4, 7, 13] {
        insert(&mut root, k);
    }
    assert!(contains(&root, 7));
    assert!(!contains(&root, 5));
    println!("ok");
}
