using i64 = long long;
constexpr i64 MOD = 1'000'000'007LL;

// Returns (F(n), F(n+1)) mod MOD.
std::pair<i64, i64> fib_pair(i64 n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n / 2);
    i64 c = (a * ((2 * b - a + MOD) % MOD)) % MOD;
    i64 d = (a * a + b * b) % MOD;
    if (n % 2 == 0) return {c, d};
    return {d, (c + d) % MOD};
}

int main() {
    std::cout << fib_pair(50).first << '\n';
    std::cout << fib_pair(1'000'000'000LL).first << '\n';
    return 0;
}
