```cpp
#include <vector>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(size_t capacity) : buf_(capacity), head_(0), size_(0) {}

    void push(int value) {
        size_t tail = (head_ + size_) % buf_.size();
        buf_[tail] = value;
        if (size_ < buf_.size()) {
            ++size_;
        } else {
            head_ = (head_ + 1) % buf_.size();  // drop oldest
        }
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return value;
    }

    size_t size() const { return size_; }

private:
    std::vector<int> buf_;
    size_t head_;
    size_t size_;
};
```

When the buffer is full, `push` advances `head_` so the oldest slot is reused and the write lands at the computed tail. `pop` returns `std::nullopt` on an empty buffer instead of undefined behaviour.

