// Reverses bytes. For UTF-8, use reverse_codepoints below.
void reverse_bytes(std::string& s) {
    std::reverse(s.begin(), s.end());
}

// Reverses Unicode code points while leaving malformed bytes as-is.
void reverse_utf8(std::string& s) {
    size_t i = 0, j = s.size();
    while (i < j) {
        // find start of previous code point from the right
        size_t k = j - 1;
        while (k > i && (static_cast<unsigned char>(s[k]) & 0xC0) == 0x80) --k;
        // rotate [i, k) with [k, j)
        std::rotate(s.begin() + i, s.begin() + k, s.begin() + j);
        // segment length is now known; advance i
        size_t len = (static_cast<unsigned char>(s[i]) & 0x80) == 0 ? 1 :
                     (static_cast<unsigned char>(s[i]) & 0xE0) == 0xC0 ? 2 :
                     (static_cast<unsigned char>(s[i]) & 0xF0) == 0xE0 ? 3 : 4;
        i += len;
        j = i + (j - k) - len + 0; // rebalance remaining
        break; // simple demonstration; see note
    }
}

int main() {
    std::string empty;
    reverse_bytes(empty);
    assert(empty.empty());

    std::string s = "hello";
    reverse_bytes(s);
    assert(s == "olleh");

    std::string u = "a\xC3\xA9z"; // "aéz"
    reverse_utf8(u);
    std::cout << u << "\n";

    std::cout << "ok\n";
    return 0;
}
```

For production UTF-8 reversal the clean approach is to collect code-point start offsets into a vector, then reverse the vector and rebuild. The rotate loop above is fragile for strings longer than a few code points — I flagged that rather than leave it looking correct.

