fn parse_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();

    while let Some(c) = chars.next() {
        match c {
            '"' if in_quotes => {
                if chars.peek() == Some(&'"') {
                    current.push('"');
                    chars.next();
                } else {
                    in_quotes = false;
                }
            }
            '"' => in_quotes = true,
            ',' if !in_quotes => {
                fields.push(std::mem::take(&mut current));
            }
            _ => current.push(c),
        }
    }
    fields.push(current);
    fields
}

fn main() {
    assert_eq!(parse_line("a,b,c"), vec!["a", "b", "c"]);
    assert_eq!(parse_line("a,\"b,c\",d"), vec!["a", "b,c", "d"]);
    assert_eq!(parse_line("\"he said \"\"hi\"\"\",x"), vec!["he said \"hi\"", "x"]);
    assert_eq!(parse_line(""), vec![""]);
    assert_eq!(parse_line("\"\""), vec![""]);
    println!("ok");
}
```

Doubled quotes inside a quoted field become a literal quote. Empty input yields one empty field, matching common CSV behaviour.

