```python
import functools
import random
import time


def retry(attempts=5, base=0.5, cap=30.0, jitter=0.1,
          exceptions=(Exception,)):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            delay = base
            for attempt in range(1, attempts + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions:
                    if attempt == attempts:
                        raise
                    sleep_for = min(delay, cap)
                    sleep_for += random.uniform(0, sleep_for * jitter)
                    time.sleep(sleep_for)
                    delay *= 2
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=3, base=0.01, exceptions=(ValueError,))
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return "done"

    assert flaky() == "done"
    assert calls["n"] == 3

    @retry(attempts=2, base=0.01, exceptions=(ValueError,))
    def always_fails():
        raise ValueError("nope")

    try:
        always_fails()
    except ValueError:
        pass
    else:
        raise AssertionError("should have raised")
    print("ok")
```

Backoff doubles each try and is capped at `cap` before jitter is added, so worst-case sleep stays close to the cap. Only the listed exception types are retried.

```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TOMBSTONE ((Node *)1)

typedef struct Node {
    char *word;
    unsigned long count;
    struct Node *next;
} Node;

#define BUCKETS 65536
static Node *table[BUCKETS];

static unsigned long hash(const char *s) {
    unsigned long h = 5381UL;
    while (*s) h = ((h << 5) + h) + (unsigned char)*s++;
    return h;
}

static int add(const char *word) {
    unsigned long idx = hash(word) % BUCKETS;
    for (Node *n = table[idx]; n; n = n->next) {
        if (strcmp(n->word, word) == 0) {
            if (n->count == ULONG_MAX) return 1; /* overflow */
            n->count++;
            return 0;
        }
    }
    Node *n = malloc(sizeof *n);
    if (!n) return -1;
    n->word = strdup(word);
    if (!n->word) { free(n); return -1; }
    n->count = 1;
    n->next = table[idx];
    table[idx] = n;
    return 0;
}

static void free_all(void) {
    for (size_t i = 0; i < BUCKETS; i++) {
        Node *n = table[i];
        while (n) {
            Node *next = n->next;
            free(n->word);
            free(n);
            n = next;
        }
        table[i] = NULL;
    }
}

int main(void) {
    char *buf = NULL;
    size_t cap = 0;
    ssize_t len;

    while ((len = getline(&buf, &cap, stdin)) != -1) {
        char *p = buf;
        while (*p) {
            while (*p && !isalpha((unsigned char)*p)) p++;
            if (!*p) break;
            char *start = p;
            while (*p && isalpha((unsigned char)*p)) p++;
            char saved = *p;
            *p = '\0';
            int rc = add(start);
            *p = saved;
            if (rc != 0) {
                fprintf(stderr, "allocation failure\n");
                free(buf);
                free_all();
                return 1;
            }
        }
    }
    free(buf);
    free_all();
    return 0;
}
```

