```cpp
#include <condition_variable>
#include <cstddef>
#include <deque>
#include <mutex>
#include <optional>
#include <stdexcept>
#include <utility>

template <typename T>
class BlockingQueue {
public:
    explicit BlockingQueue(std::size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    BlockingQueue(const BlockingQueue&) = delete;
    BlockingQueue& operator=(const BlockingQueue&) = delete;

    void push(T value) {
        std::unique_lock lock(mu_);
        not_full_.wait(lock, [this] { return closed_ || q_.size() < cap_; });
        if (closed_) throw std::runtime_error("queue is closed");
        q_.push_back(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
    }

    std::optional<T> pop() {
        std::unique_lock lock(mu_);
        not_empty_.wait(lock, [this] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;  // closed and drained
        T value = std::move(q_.front());
        q_.pop_front();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        {
            std::lock_guard lock(mu_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

    std::size_t size() const {
        std::lock_guard lock(mu_);
        return q_.size();
    }

private:
    mutable std::mutex mu_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
    std::deque<T> q_;
    const std::size_t cap_;
    bool closed_ = false;
};
```

`pop` returns `nullopt` only after `close()`, so a consumer loop like `while (auto v = q.pop())` drains everything then exits. `push` after `close()` throws — that's deliberate, so a producer can't hang forever against a dead queue.

```rust
use std::collections::HashMap;
use std::hash::Hash;

struct Entry<K, V> {
    key: K,
    value: V,
    prev: Option<usize>,
    next: Option<usize>,
}

pub struct LruCache<K, V> {
    map: HashMap<K, usize>,
    entries: Vec<Option<Entry<K, V>>>,
    free: Vec<usize>,
    head: Option<usize>,
    tail: Option<usize>,
    capacity: usize,
}

impl<K: Hash + Eq + Clone, V> LruCache<K, V> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        LruCache {
            map: HashMap::with_capacity(capacity),
            entries: Vec::with_capacity(capacity),
            free: Vec::new(),
            head: None,
            tail: None,
            capacity,
        }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        let idx = *self.map.get(key)?;
        self.detach(idx);
        self.push_front(idx);
        Some(&self.entries[idx].as_ref().unwrap().value)
    }

    pub fn put(&mut self, key: K, value: V) {
        if let Some(&idx) = self.map.get(&key) {
            self.entries[idx].as_mut().unwrap().value = value;
            self.detach(idx);
            self.push_front(idx);
            return;
        }

        let idx = if let Some(free_idx) = self.free.pop() {
            free_idx
        } else if self.entries.len() < self.capacity {
            self.entries.push(None);
            self.entries.len() - 1
        } else {
            let old = self.tail.expect("cache is full so tail exists");
            let old_key = self.entries[old].take().unwrap().key;
            self.map.remove(&old_key);
            self.detach(old);
            old
        };

        self.map.insert(key.clone(), idx);
        self.entries[idx] = Some(Entry { key, value, prev: None, next: None });
        self.push_front(idx);
    }

    fn detach(&mut self, idx: usize) {
        let (prev, next) = {
            let e = self.entries[idx].as_ref().unwrap();
            (e.prev, e.next)
        };
        if let Some(p) = prev {
            self.entries[p].as_mut().unwrap().next = next;
        } else {
            self.head = next;
        }
        if let Some(n) = next {
            self.entries[n].as_mut().unwrap().prev = prev;
        } else {
            self.tail = prev;
        }
    }

    fn push_front(&mut self, idx: usize) {
        {
            let e = self.entries[idx].as_mut().unwrap();
            e.prev = None;
            e.next = self.head;
        }
        if let Some(h) = self.head {
            self.entries[h].as_mut().unwrap().prev = Some(idx);
        }
        self.head = Some(idx);
        if self.tail.is_none() {
            self.tail = Some(idx);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::LruCache;

    #[test]
    fn evicts_least_recently_used() {
        let mut c = LruCache::new(2);
        c.put(1, "a");
        c.put(2, "b");
        assert_eq!(c.get(&1), Some(&"a"));
        c.put(3, "c");
        assert_eq!(c.get(&2), None);
        assert_eq!(c.get(&3), Some(&"c"));
    }
}
```

The arena (`entries`) with `free` slots avoids the usual `Rc<RefCell>` pointer soup, so `get`/`put` stay O(1) and the borrow checker is satisfied without unsafe. Losing `assume_init` tricks, this is the least-clever version that compiles cleanly on stable.

```c
#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

typedef struct {
    int *buf;
    size_t cap;
    size_t head;  /* next read */
    size_t count; /* number of live elements */
} Ring;

void ring_init(Ring *r, int *storage, size_t capacity) {
    r->buf = storage;
    r->cap = capacity;
    r->head = 0;
    r->count = 0;
}

bool ring_empty(const Ring *r) { return r->count == 0; }
bool ring_full(const Ring *r)  { return r->count == r->cap; }

bool ring_push(Ring *r, int value) {
    if (ring_full(r)) return false;
    size_t tail = (r->head + r->count) % r->cap;
    r->buf[tail] = value;
    r->count++;
    return true;
}

bool ring_pop(Ring *r, int *out) {
    if (ring_empty(r)) return false;
    *out = r->buf[r->head];
    r->head = (r->head + 1) % r->cap;
    r->count--;
    return true;
}

int main(void) {
    int storage[4];
    Ring r;
    ring_init(&r, storage, 4);

    for (int i = 1; i <= 5; i++) {
        bool ok = ring_push(&r, i);
        if (!ok) printf("push %d rejected: buffer full\n", i);
    }

    int v;
    while (ring_pop(&r, &v)) printf("popped %d\n", v);
    printf("drained; empty=%s\n", ring_empty(&r) ? "true" : "false");
    return 0;
}
```

Expected output: `push 5 rejected: buffer full`, then `popped 1` through `popped 4`, then `drained; empty=true`. No allocation happens after `ring_init`, so capacity is fixed by the caller's array size.

