use std::env;
use std::fs::File;
use std::io::{self, BufRead, BufReader};

struct Counts {
    lines: u64,
    words: u64,
    bytes: u64,
}

fn count<R: BufRead>(mut reader: R) -> io::Result<Counts> {
    let mut counts = Counts { lines: 0, words: 0, bytes: 0 };
    let mut buf = Vec::new();

    loop {
        buf.clear();
        let n = reader.read_until(b'\n', &mut buf)?;
        if n == 0 {
            break;
        }
        counts.bytes += n as u64;
        counts.lines += 1;
        counts.words += buf
            .split(|b| b.is_ascii_whitespace())
            .filter(|chunk| !chunk.is_empty())
            .count() as u64;
    }
    Ok(counts)
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.is_empty() {
        eprintln!("usage: wc-lite <file>...");
        std::process::exit(2);
    }

    for path in &args {
        let result = File::open(path)
            .map(BufReader::new)
            .and_then(count);
        match result {
            Ok(c) => println!("{:>8} {:>8} {:>8} {}", c.lines, c.words, c.bytes, path),
            Err(e) => eprintln!("wc-lite: {}: {}", path, e),
        }
    }
}
