Errors go to stderr and the process still continues to the next file, matching `wc`'s behaviour. Counting bytes from `read_until` handles files without a trailing newline correctly — the last partial line is still counted once.

```python
import functools
import random
import time


def retry(attempts=3, base_delay=0.5, max_delay=30.0, jitter=0.1,
          exceptions=(Exception,)):
    """Retry a function with exponential backoff plus proportional jitter.

    attempts    total tries, including the first (must be >= 1)
    base_delay  seconds to sleep before the second try
    max_delay   upper bound on any single sleep
    jitter      fraction in [0, 1) of each delay added at random
    """
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    if not 0.0 <= jitter < 1.0:
        raise ValueError("jitter must be in [0, 1)")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt == attempts - 1:
                        break
                    delay = min(base_delay * (2 ** attempt), max_delay)
                    delay += delay * jitter * random.random()
                    time.sleep(delay)
            raise last
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=3, base_delay=0.0, jitter=0.0)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise RuntimeError(f"transient {calls['n']}")
        return "ok"

    assert flaky() == "ok"
    assert calls["n"] == 3

    @retry(attempts=2, base_delay=0.0, jitter=0.0)
    def always_fails():
        raise ValueError("nope")

    try:
        always_fails()
    except ValueError as exc:
        assert str(exc) == "nope"
    else:
        raise AssertionError("expected ValueError")

    print("all tests passed")
```

The final exception is re-raised rather than swallowed, so callers keep the real traceback. `base_delay=0` with `jitter=0` makes the test deterministic — in production keep jitter non-zero so retries from many clients don't synchronise into a thundering herd.

