#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define BUCKETS 256

typedef struct Node {
    char *word;
    struct Node *next;
} Node;

static unsigned hash(const char *s) {
    unsigned h = 5381;
    while (*s) h = h * 33u + (unsigned char)tolower(*s++);
    return h % BUCKETS;
}

int main(void) {
    char line[4096];
    if (!fgets(line, sizeof line, stdin)) return 0;

    Node *table[BUCKETS] = {0};
    size_t distinct = 0;
    char *p = line;

    while (*p) {
        while (*p && isspace((unsigned char)*p)) p++;
        if (!*p) break;
        char *start = p;
        while (*p && !isspace((unsigned char)*p)) p++;
        size_t len = (size_t)(p - start);

        char *w = malloc(len + 1);
        if (!w) return 1;
        for (size_t i = 0; i < len; i++) w[i] = (char)tolower((unsigned char)start[i]);
        w[len] = '\0';

        unsigned b = hash(w);
        int found = 0;
        for (Node *n = table[b]; n; n = n->next) {
            if (strcmp(n->word, w) == 0) { found = 1; break; }
        }
        if (found) {
            free(w);
        } else {
            Node *n = malloc(sizeof *n);
            if (!n) return 1;
            n->word = w;
            n->next = table[b];
            table[b] = n;
            distinct++;
        }
    }

    printf("%zu\n", distinct);

    for (int i = 0; i < BUCKETS; i++) {
        Node *n = table[i];
        while (n) { Node *nx = n->next; free(n->word); free(n); n = nx; }
    }
    return 0;
}
