fn dedup_sorted<T: PartialEq>(v: &mut Vec<T>) -> usize {
    if v.is_empty() {
        return 0;
    }
    let mut write = 0usize;
    for read in 1..v.len() {
        if v[read] != v[write] {
            write += 1;
            if write != read {
                v.swap(write, read);
            }
        }
    }
    let new_len = write + 1;
    v.truncate(new_len);
    new_len
}

fn main() {
    let mut a = vec![1, 1, 2, 3, 3, 3, 4];
    assert_eq!(dedup_sorted(&mut a), 4);
    assert_eq!(a, vec![1, 2, 3, 4]);

    let mut b: Vec<i32> = vec![];
    assert_eq!(dedup_sorted(&mut b), 0);

    let mut c = vec![5, 5, 5];
    assert_eq!(dedup_sorted(&mut c), 1);
    assert_eq!(c, vec![5]);
    println!("ok");
}
