        long long g = gcd(a, b);
        if (a == 0 || b == 0) {
            printf("gcd(%lld, %lld) = %lld, lcm undefined for zero\n", a, b, g);
        } else {
            printf("gcd(%lld, %lld) = %lld, lcm = %lld\n", a, b, g, a / g * b);
        }
    }
    return 0;
