// Merge two ascending sorted ranges into a new ascending vector.
// Stable: equal keys keep left-before-right order.
std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        // Use <= on a to prefer the left range on ties.
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else              out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    assert(merge_sorted({}, {}) == std::vector<int>{});
    assert(merge_sorted({}, {1, 2, 3}) == (std::vector<int>{1, 2, 3}));
    assert(merge_sorted({1, 3, 5}, {2, 4, 6}) == (std::vector<int>{1, 2, 3, 4, 5, 6}));
    assert(merge_sorted({1, 1, 1}, {1}) == (std::vector<int>{1, 1, 1, 1}));
    // Negative values and a longer tail on one side.
    assert(merge_sorted({-5, -1}, {-3, 0, 7, 9}) == (std::vector<int>{-5, -3, -1, 0, 7, 9}));
    std::cout << "all tests passed\n";
    return 0;
}
