class InstanceCounter {
public:
    InstanceCounter() : id_(next_id_++) { ++alive_; }
    InstanceCounter(const InstanceCounter& other) : id_(next_id_++) { ++alive_; }
    InstanceCounter(InstanceCounter&& other) noexcept : id_(other.id_) {
        ++alive_;  // the moved-from object is still alive until it is destroyed
    }
    InstanceCounter& operator=(const InstanceCounter&) { return *this; }
    InstanceCounter& operator=(InstanceCounter&&) noexcept { return *this; }
    ~InstanceCounter() { --alive_; }

    unsigned id() const { return id_; }
    static int alive() { return alive_; }

private:
    unsigned id_;
    static inline int alive_ = 0;
    static inline unsigned next_id_ = 0;
};

int main() {
    assert(InstanceCounter::alive() == 0);
    {
        InstanceCounter a;
        InstanceCounter b = a;      // copy ctor: one more alive
        assert(InstanceCounter::alive() == 2);
        InstanceCounter c = std::move(a);  // move ctor: still a live object
        assert(InstanceCounter::alive() == 3);
        assert(c.id() != b.id());
    }
    assert(InstanceCounter::alive() == 0);
    std::cout << "instance counting works\n";
    return 0;
