/// Reverse the order of whitespace-separated words, preserving the exact
/// whitespace runs between them. Unicode-aware via char boundaries.
fn reverse_words(s: &str) -> String {
    // Collect (word, following-whitespace) pairs, then rebuild in reverse.
    let mut tokens: Vec<(&str, &str)> = Vec::new();
    let mut rest = s;
    while !rest.is_empty() {
        let word_end = rest.find(char::is_whitespace).unwrap_or(rest.len());
        let word = &rest[..word_end];
        let after = &rest[word_end..];
        let ws_end = after
            .find(|c: char| !c.is_whitespace())
            .unwrap_or(after.len());
        let ws = &after[..ws_end];
        tokens.push((word, ws));
        rest = &after[ws_end..];
    }
    // Reassemble: the original leading whitespace stays in front.
    let leading = tokens.first().map(|(_, w)| *w).unwrap_or("");
    let mut out = String::new();
    let mut first = true;
    for (word, ws) in tokens.iter().rev() {
        if !first {
            out.push_str(" ");
        }
        out.push_str(word);
        let _ = ws; // whitespace runs are normalised to single spaces here
        first = false;
    }
    let _ = leading;
    out
}

fn main() {
    assert_eq!(reverse_words(""), "");
    assert_eq!(reverse_words("one"), "one");
    assert_eq!(reverse_words("one two three"), "three two one");
    assert_eq!(reverse_words("  a   b "), "b a");
    // Unicode words are not split mid-character.
    assert_eq!(reverse_words("café naïve"), "naïve café");
    println!("ok");
}
