```c
#include <assert.h>
#include <stdio.h>
#include <stddef.h>

/* Insert `value` into the ascending array `a` of `*len` elements.
 * `cap` is the allocated capacity. Returns the new length, or SIZE_MAX on
 * overflow (array already full) so the caller can distinguish it from a
 * legitimate length. Duplicates are allowed and inserted after equals.
 * Stable: equal elements keep their relative order.
 */
size_t sorted_insert(int *a, size_t *len, size_t cap, int value) {
    if (*len >= cap) {
        return SIZE_MAX;
    }
    /* Find the first index where value < a[i]; insert there. */
    size_t i = *len;
    while (i > 0 && a[i - 1] > value) {
        a[i] = a[i - 1];  /* shift right until the window is right */
        i--;
    }
    a[i] = value;
    *len += 1;
    return *len;
}

int main(void) {
    int buf[8] = {1, 3, 5, 7};
    size_t len = 4;

    assert(sorted_insert(buf, &len, 8, 4) == 5);
    assert(buf[0] == 1 && buf[1] == 3 && buf[2] == 4 &&
           buf[3] == 5 && buf[4] == 7);

    /* Insert a duplicate of the smallest value: it must land at index 0. */
    assert(sorted_insert(buf, &len, 8, 1) == 6);
    assert(buf[0] == 1 && buf[1] == 1 && buf[2] == 3);

    /* Insert into an empty array. */
    int empty[2] = {0};
    size_t empty_len = 0;
    assert(sorted_insert(empty, &empty_len, 2, 42) == 1);
    assert(empty[0] == 42);

    /* Overflow is reported, not silently ignored. */
    int full[2] = {1, 2};
    size_t full_len = 2;
    assert(sorted_insert(full, &full_len, 2, 3) == SIZE_MAX);
    assert(full_len == 2 && full[0] == 1 && full[1] == 2);

    puts("sorted_insert ok");
    return 0;
}
