std::string to_binary(long long n) {
    if (n == 0) return "0";
    bool neg = n < 0;
    unsigned long long u = neg ? (unsigned long long)(-n) : (unsigned long long)n;
    std::string out;
    while (u > 0) {
        out.push_back(char('0' + (u & 1)));
        u >>= 1;
    }
    if (neg) out.push_back('-');
    std::string rev(out.rbegin(), out.rend());
    return rev;
}

