#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

#include <cassert>
#include <thread>

template <typename T>
class SafeQueue {
public:
    void push(T value) {
        {
            std::lock_guard<std::mutex> lock(m_mutex);
            if (m_closed) return;
            m_queue.push(std::move(value));
        }
        m_cv.notify_one();
    }

    // Returns std::nullopt once the queue is closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(m_mutex);
        m_cv.wait(lock, [this] { return !m_queue.empty() || m_closed; });
        if (m_queue.empty()) return std::nullopt;
        T value = std::move(m_queue.front());
        m_queue.pop();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(m_mutex);
            m_closed = true;
        }
        m_cv.notify_all();
    }

private:
    std::queue<T> m_queue;
    mutable std::mutex m_mutex;
    std::condition_variable m_cv;
    bool m_closed = false;
};

int main() {
    SafeQueue<int> q;
    q.push(1);
    q.push(2);
    assert(q.pop() == 1);
    q.close();
    assert(q.pop() == 2);
    assert(!q.pop().has_value());
    q.push(99);  // ignored after close
    assert(!q.pop().has_value());
    return 0;
}
