    Buffer& operator=(const Buffer&) = delete;

    char* data() { return data_.get(); }
    std::size_t size() const { return size_; }
    void write(const char* s, std::size_t n) {
        if (n > size_) n = size_;
        std::memcpy(data_.get(), s, n);
        data_[n] = '\0';
    }

private:
    std::size_t size_;
    std::unique_ptr<char[]> data_;
};

