#include <iostream>
#include <queue>
#include <vector>

class RunningMedian {
public:
    void add(int value) {
        if (low_.empty() || value <= low_.top()) {
            low_.push(value);
        } else {
            high_.push(value);
        }
        if (low_.size() > high_.size() + 1) {
            high_.push(low_.top());
            low_.pop();
        } else if (high_.size() > low_.size()) {
            low_.push(high_.top());
            high_.pop();
        }
    }

    double median() const {
        if (low_.size() == high_.size()) {
            return (low_.top() + high_.top()) / 2.0;
        }
        return low_.top();
    }

private:
    std::priority_queue<int> low_;
    std::priority_queue<int, std::vector<int>, std::greater<int>> high_;
};

int main() {
    RunningMedian rm;
    int value;
    bool any = false;
    while (std::cin >> value) {
        any = true;
        rm.add(value);
        std::cout << rm.median() << '\n';
    }
    if (!any) {
        std::cerr << "no input\n";
        return 0;
    }
    return 0;
}
```

Two heaps keep the lower half as a max-heap and the upper half as a min-heap. After each insertion the sizes are rebalanced so the median is either the top of `low_` or the average of both tops. For example, `5 2 9` prints `5`, `3.5`, `5`. An empty stream exits quietly with a message on stderr instead of printing a bogus value.

```rust
fn is_valid_ipv4(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return false;
    }
    parts.iter().all(|part| {
        if part.is_empty() || part.len() > 3 || !part.bytes().all(|b| b.is_ascii_digit()) {
            return false;
        }
        // Reject leading zeros like "01" or "00" unless the part is exactly "0".
        if part.len() > 1 && part.starts_with('0') {
            return false;
        }
        part.parse::<u16>().map(|n| n <= 255).unwrap_or(false)
    })
}

fn main() {
    let cases = [
        ("192.168.0.1", true),
        ("0.0.0.0", true),
        ("255.255.255.255", true),
        ("256.1.1.1", false),
        ("1.2.3", false),
        ("1.2.3.4.5", false),
        ("01.2.3.4", false),
        ("1.2.3.-1", false),
        ("", false),
        ("1.2.3.4 ", false),
    ];
    for (input, expected) in cases {
        assert_eq!(is_valid_ipv4(input), expected, "{input:?}");
    }
    println!("all {} cases passed", cases.len());
}
```

Split on dots and require exactly four parts. Each part must be non-empty, at most three ASCII digits, have no leading zero (so `01` is rejected while `0` is fine), and parse to a value no greater than 255. Parsing as `u16` avoids overflow before the range check.

