OPENERS = set(BRACKETS.values())


def is_balanced(s: str) -> bool:
    stack = []
    for ch in s:
        if ch in OPENERS:
            stack.append(ch)
        elif ch in BRACKETS:
            if not stack or stack.pop() != BRACKETS[ch]:
                return False
    return not stack


if __name__ == "__main__":
    tests = [
        ("", True),
        ("()[]{}", True),
        ("([{}])", True),
        ("(]", False),
        ("((", False),
        (")", False),
        ("a(b[c]d)e", True),
        ("{[()", False),
    ]
    for text, expected in tests:
        assert is_balanced(text) is expected, text
    print("all ok")
```

A stack is the natural fit: push openings, and on a closer pop and compare. An empty string and strings without brackets are balanced; an unmatched closer returns False immediately, and any leftover opener is caught by `not stack` at the end. Non-bracket characters are ignored, so the function works on mixed text.

```c
#include <stdio.h>
#include <stdlib.h>

/* Returns F(n) and F(n+1) via fast doubling. */
static void fib_pair(unsigned long long n, unsigned long long *a, unsigned long long *b) {
    if (n == 0) {
        *a = 0;
        *b = 1;
        return;
    }
    unsigned long long x, y;
    fib_pair(n >> 1, &x, &y);
    unsigned long long c = x * (y * 2 - x);
    unsigned long long d = x * x + y * y;
    if (n & 1) {
        *a = d;
        *b = c + d;
    } else {
        *a = c;
        *b = d;
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s N\n", argv[0]);
        return 1;
    }
    char *end = NULL;
    unsigned long long n = strtoull(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0') {
        fprintf(stderr, "invalid N: %s\n", argv[1]);
        return 1;
    }
    unsigned long long a, b;
    fib_pair(n, &a, &b);
    printf("F(%llu) = %llu\n", n, a);
    return 0;
}
```

Fast doubling uses F(2k) = F(k)(2F(k+1) − F(k)) and F(2k+1) = F(k)² + F(k+1)². It runs in O(log n) multiplications, much faster than the naive loop. Values grow quickly: `F(93)` is the largest that fits in `unsigned long long`, so for larger inputs the result wraps; keep that limit in mind.

```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 2], &[]), vec![1, 2]);
    assert_eq!(merge_sorted(&[], &[7, 8]), vec![7, 8]);
    assert_eq!(merge_sorted(&[2, 2, 2], &[2, 2]), vec![2, 2, 2, 2, 2]);
    println!("all merges ok");
}
```

The `<=` on the comparison keeps the merge stable, so equal elements from `a` come before those from `b`. `with_capacity` sizes the vector once to avoid reallocations, and the two `extend_from_slice` calls append whatever tail remains after one side is exhausted.

