#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t size;
    size_t cap;
} Stack;

static int stack_reserve(Stack *s, size_t need) {
    if (need <= s->cap) return 1;
    size_t newcap = s->cap ? s->cap * 2 : 8;
    while (newcap < need) newcap *= 2;
    int *tmp = realloc(s->data, newcap * sizeof(int));
    if (!tmp) return 0;
    s->data = tmp;
    s->cap = newcap;
    return 1;
}

int stack_init(Stack *s) {
    s->data = NULL;
    s->size = 0;
    s->cap = 0;
    return 1;
}

int stack_push(Stack *s, int v) {
    if (!stack_reserve(s, s->size + 1)) return 0;
    s->data[s->size++] = v;
    return 1;
}

int stack_pop(Stack *s, int *out) {
    if (s->size == 0) return 0;
    *out = s->data[--s->size];
    return 1;
}

void stack_free(Stack *s) {
    free(s->data);
    s->data = NULL;
    s->size = s->cap = 0;
}

int main(void) {
    Stack s;
    stack_init(&s);
    if (!stack_push(&s, 1) || !stack_push(&s, 2)) {
        fprintf(stderr, "alloc failed\n");
        stack_free(&s);
        return 1;
    }
    int v;
    if (stack_pop(&s, &v)) printf("popped %d\n", v);
    stack_free(&s);
    return 0;
}
