// Reverses the order of UTF-8 code points without splitting them.
std::string reverse_utf8(const std::string &s) {
    std::vector<std::string> chars;
    for (size_t i = 0; i < s.size();) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        size_t len = 1;
        if (c >= 0xF0) len = 4;
        else if (c >= 0xE0) len = 3;
        else if (c >= 0xC0) len = 2;
        if (i + len > s.size()) len = 1; // truncated tail, treat as raw byte
        chars.emplace_back(s, i, len);
        i += len;
    }
    std::string out;
    out.reserve(s.size());
    for (auto it = chars.rbegin(); it != chars.rend(); ++it) out += *it;
    return out;
}

int main() {
    std::cout << reverse_utf8("a\u00e9b") << '\n';  // b\u00e9a
