void rotate_right(std::vector<int>& v, std::size_t k) {
    const std::size_t n = v.size();
    if (n == 0) return;
    k %= n;                 // k > n folds into range
    if (k == 0) return;
    std::reverse(v.begin(), v.end());
    std::reverse(v.begin(), v.begin() + k);
    std::reverse(v.begin() + k, v.end());
}

int main() {
    std::vector<int> a{1, 2, 3, 4, 5};
    rotate_right(a, 7);     // 7 % 5 == 2
    for (int x : a) std::cout << x << ' ';
    std::cout << '\n';      // 4 5 1 2 3
    std::vector<int> b;
    rotate_right(b, 3);     // no crash
}
```
The triple-reversal trick is O(n) time and O(1) extra space. Reducing `k` modulo `n` first is what makes `k` larger than the size safe, and the empty-vector early return avoids out-of-range iterators.

