use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The cat, the dog! A dog. THE bird";
    let top = top_words(text, 2);
    assert_eq!(top, vec![("the".to_string(), 3), ("dog".to_string(), 2)]);
    println!("{:?}", top);
}
```
`split_whitespace` handles any run of whitespace, the filter/lowercase step strips punctuation and folds case, and `sort_by` gives the count-descending, word-ascending order. `truncate` caps the result at `n` without panicking when fewer words exist.

