std::vector<int> merge_unique(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> merged;
    merged.reserve(a.size() + b.size());
    std::merge(a.begin(), a.end(), b.begin(), b.end(), std::back_inserter(merged));
    merged.erase(std::unique(merged.begin(), merged.end()), merged.end());
    return merged;
}

int main() {
    std::vector<int> a{1, 2, 2, 5};
    std::vector<int> b{2, 3, 3, 9};
    std::vector<int> out = merge_unique(a, b);
    for (int x : out) std::cout << x << ' ';
    std::cout << '\n';   // 1 2 3 5 9
}
```
`std::merge` is a stable linear merge assuming both inputs are sorted; `std::unique` then compresses equal adjacent runs, which is why merging pre-sorted inputs matters. `reserve` avoids reallocations during the merge.

