#include <array>
#include <cstddef>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(float value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<float> front() const {
        if (count_ == 0) return std::nullopt;
        return data_[head_];
    }

    bool pop() {
        if (count_ == 0) return false;
        head_ = (head_ + 1) % N;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }

private:
    std::array<float, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

#include <cstdio>
int main() {
    RingBuffer<3> rb;
    rb.push(1.5f); rb.push(2.5f); rb.push(3.5f);
    std::printf("full push: %d\n", rb.push(4.5f)); // 0
    std::printf("front: %.1f size: %zu\n", *rb.front(), rb.size()); // 1.5 3
    rb.pop();
    std::printf("front: %.1f size: %zu\n", *rb.front(), rb.size()); // 2.5 2
    return 0;
}
```

The buffer reports full via the `false` return from `push` instead of overwriting, so the caller decides the policy. `front` returns `nullopt` on empty, which the caller must check before dereferencing.

