```rust
pub struct BoundedStack<T> {
    items: Vec<T>,
    cap: usize,
}

impl<T> BoundedStack<T> {
    pub fn new(cap: usize) -> Self {
        Self { items: Vec::new(), cap }
    }

    /// Returns the value back if the stack is full.
    pub fn push(&mut self, item: T) -> Result<(), T> {
        if self.items.len() >= self.cap {
            return Err(item);
        }
        self.items.push(item);
        Ok(())
    }

    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
}

fn main() {
    let mut s = BoundedStack::new(2);
    s.push(10).unwrap();
    s.push(20).unwrap();
    match s.push(30) {
        Err(v) => println!("rejected {v}"), // rejected 30
        Ok(()) => println!("accepted"),
    }
    println!("len = {}", s.len()); // 2
    println!("pop = {:?}", s.pop()); // Some(20)
}
```

On overflow the value is handed back as `Err<T>`, so nothing is silently dropped and the caller can retry or log. `is_empty` is included alongside `len` to satisfy the usual lint pair.

