        return token, ""
    words = []
    for t in tokens:
        core, punct = split_punct(t)
        words.append(core)
        words.append(punct)
    # Reverse only the word cores, leave punctuation slots in place.
    cores = [w for i, w in enumerate(words) if i % 2 == 0]
    cores.reverse()
    out = []
    ci = 0
    for i, w in enumerate(words):
        if i % 2 == 0:
            out.append(cores[ci]); ci += 1
        else:
            out.append(w)
    return " ".join(out)

if __name__ == "__main__":
    print(reverse_words("Hello, world!"))        # world, Hello!
    print(reverse_words("one two three"))         # three two one
    print(reverse_words(""))                      # (empty)
    print(reverse_words("\u4f60\u597d\u4e16\u754c,\u597d\u7684."))  # \u597d\u7684. \u4f60\u597d\u4e16\u754c,
