use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
pub enum ParseListError {
    EmptyInput,
    BadToken { token: String, source: ParseIntError },
}

pub fn parse_list(input: &str) -> Result<Vec<i64>, ParseListError> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err(ParseListError::EmptyInput);
    }
    let mut out = Vec::new();
    for raw in trimmed.split(',') {
        let token = raw.trim();
        if token.is_empty() {
            continue;
        }
        match token.parse::<i64>() {
            Ok(n) => out.push(n),
            Err(source) => {
                return Err(ParseListError::BadToken {
                    token: token.to_string(),
                    source,
                })
            }
        }
    }
    Ok(out)
}

fn main() {
    assert_eq!(parse_list("1, 2 ,,3"), Ok(vec![1, 2, 3]));
    assert_eq!(parse_list("   "), Err(ParseListError::EmptyInput));
    assert!(matches!(parse_list("1,2,oops"), Err(ParseListError::BadToken { .. })));
    println!("ok");
}
