pub fn longest_common_prefix<S: AsRef<str>>(items: &[S]) -> String {
    if items.is_empty() {
        return String::new();
    }
    let first = items[0].as_ref();
    let mut len = first.len();
    for item in &items[1..] {
        let s = item.as_ref();
        let mut i = 0;
        let a = first.as_bytes();
        let b = s.as_bytes();
        while i < len && i < b.len() && a[i] == b[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            break;
        }
    }
    first[..len].to_string()
}

fn main() {
