```cpp
#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
class FixedStack {
    std::vector<T> data_;
    std::size_t cap_;

public:
    explicit FixedStack(std::size_t capacity) : cap_(capacity) {
        data_.reserve(capacity);
    }

    bool empty() const { return data_.empty(); }
    std::size_t size() const { return data_.size(); }

    void push(const T& value) {
        if (data_.size() >= cap_) throw std::overflow_error("stack full");
        data_.push_back(value);
    }

    void pop() {
        if (data_.empty()) throw std::underflow_error("stack empty");
        data_.pop_back();
    }

    const T& top() const {
        if (data_.empty()) throw std::underflow_error("stack empty");
        return data_.back();
    }
};

int main() {
    FixedStack<int> s(2);
    s.push(1);
    s.push(2);
    std::cout << s.top() << "\n";
    try { s.push(3); } catch (const std::overflow_error& e) { std::cout << e.what() << "\n"; }
    s.pop();
    std::cout << s.top() << "\n";
    return 0;
}
```

Bounds are enforced with exceptions rather than undefined behaviour; `top()` on an empty stack also throws.

