template <std::size_t N>
class RingBuffer {
public:
    void push(double value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    double average() const {
        if (size_ == 0) throw std::runtime_error("average on empty buffer");
        double sum = 0.0;
        for (std::size_t i = 0; i < size_; ++i) sum += data_[i];
        return sum / static_cast<double>(size_);
    }

    std::size_t size() const { return size_; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1.0);
    rb.push(2.0);
    rb.push(3.0);
    rb.push(4.0);  // overwrites 1.0
    std::cout << rb.average() << " (size " << rb.size() << ")\n";
