std::optional<std::uint64_t> fib(int n)
{
    if (n < 0) {
        return std::nullopt;
    }
    std::uint64_t a = 0, b = 1;
    for (int i = 0; i < n; ++i) {
        const std::uint64_t next = a + b;
        if (next < a) {
            return std::nullopt;  // wrapped around: overflow
        }
        a = b;
        b = next;
    }
    return a;
}

int main()
