    #[test]
    fn counts_and_ranks() {
        let out = top_words("The cat, the dog. The CAT!", 2);
        assert_eq!(out, vec![("the".to_string(), 3), ("cat".to_string(), 2)]);
    }

    #[test]
    fn empty_input() {
        assert!(top_words("", 5).is_empty());
        assert!(top_words("!!!", 5).is_empty());
    }
}
