```cpp
#include <iostream>
#include <cassert>

struct Node {
    int value;
    Node* next;
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main() {
    Node c{3, nullptr};
    Node b{2, &c};
    Node a{1, &b};

    Node* head = reverse(&a);
    assert(head->value == 3);
    assert(head->next->value == 2);
    assert(head->next->next->value == 1);
    assert(head->next->next->next == nullptr);

    assert(reverse(nullptr) == nullptr);
    std::cout << "ok\n";
    return 0;
}
```

The loop keeps three pointers: `head` is the node being processed, `next` survives the relink, and `prev` becomes the new head. After the loop `prev` points at the original tail, which is the new head. Passing `nullptr` returns `nullptr` without dereferencing.

