    use super::*;

    #[test]
    fn merges() {
        assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
        assert_eq!(merge_sorted(&[], &[1, 2]), vec![1, 2]);
        assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
        assert_eq!(merge_sorted(&[1, 1, 2], &[1, 3]), vec![1, 1, 1, 2, 3]);
    }
}
```

`<=` on equal elements keeps the merge stable, so duplicates from `a` come before those in `b`. When one side runs out, the remaining tail is already sorted and can be copied wholesale with `extend_from_slice`. Slicing `&a[i..]` is safe because `i` never exceeds `a.len()`.

