```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 1;
    }
    FILE *fp = fopen(argv[1], "r+b");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        perror("fseek end");
        fclose(fp);
        return 1;
    }
    long len = ftell(fp);
    if (len < 0) {
        perror("ftell");
        fclose(fp);
        return 1;
    }

    for (long i = 0, j = len - 1; i < j; ++i, --j) {
        unsigned char a, b;
        if (fseek(fp, i, SEEK_SET) != 0 || fread(&a, 1, 1, fp) != 1 ||
            fseek(fp, j, SEEK_SET) != 0 || fread(&b, 1, 1, fp) != 1) {
            perror("read");
            fclose(fp);
            return 1;
        }
        if (fseek(fp, i, SEEK_SET) != 0 || fwrite(&b, 1, 1, fp) != 1 ||
            fseek(fp, j, SEEK_SET) != 0 || fwrite(&a, 1, 1, fp) != 1) {
            perror("write");
            fclose(fp);
            return 1;
        }
    }

    fclose(fp);
    return 0;
}
```

Two cursors walk inward swapping one byte at a time. For an empty or single-byte file the loop condition `i < j` never runs, so the file is left as-is. The file opens `r+b` so it must already exist, and every I/O call is checked.

```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : buf_(capacity), head_(0), size_(0) {}

    bool push(double value) {
        if (size_ == buf_.size()) {
            return false; // overflow
        }
        buf_[(head_ + size_) % buf_.size()] = value;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) {
            return std::nullopt; // underflow
        }
        double value = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<double> buf_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(2);
    if (rb.pop().has_value()) return 1;            // empty
    if (!rb.push(1.5) || !rb.push(2.5)) return 1;  // fills to 2
    if (rb.push(3.5)) return 1;                    // overflow rejected
    if (rb.pop() != 1.5) return 1;                 // FIFO order
    if (!rb.push(3.5)) return 1;                   // room again
    if (rb.pop() != 2.5 || rb.pop() != 3.5) return 1;
    std::cout << "ok\n";
}
```

The buffer stores `size_` live elements starting at `head_`. Capacity zero makes `push` always return false and `pop` always return `nullopt`, so no modulo-by-zero occurs.

