def fib(n: int) -> int:
    """Return the nth Fibonacci number, F(0)=0, F(1)=1, via fast doubling."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def pair(k: int) -> tuple[int, int]:
        if k == 0:
            return (0, 1)
        a, b = pair(k >> 1)
        c = a * (2 * b - a)
        d = a * a + b * b
        if k & 1:
            return (d, c + d)
        return (c, d)

    return pair(n)[0]

