#include <stdio.h>
#include <stdlib.h>

static void reverse(int *a, int lo, int hi) {
    while (lo < hi) {
        int tmp = a[lo];
        a[lo++] = a[hi];
        a[hi--] = tmp;
    }
}

void rotate_left(int *a, int n, int k) {
    if (n <= 0) return;
    k %= n;
    if (k < 0) k += n;
    if (k == 0) return;
    reverse(a, 0, k - 1);
    reverse(a, k, n - 1);
    reverse(a, 0, n - 1);
}

int main(void) {
    int a[] = {1, 2, 3, 4, 5, 6, 7};
    int n = (int)(sizeof a / sizeof a[0]);
    rotate_left(a, n, 3);
    for (int i = 0; i < n; i++) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');

    rotate_left(a, n, 100); /* oversized k wraps via modulo */
    rotate_left(a, 0, 5);  /* zero length is a no-op */
    return 0;
}
