```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* getline is POSIX; on strict C11 declare our own reader. */
static ssize_t read_line(char **buf, size_t *cap, FILE *stream) {
    size_t len = 0;
    int ch;
    if (*buf == NULL || *cap == 0) {
        *cap = 128;
        *buf = malloc(*cap);
        if (*buf == NULL) return -1;
    }
    while ((ch = fgetc(stream)) != EOF) {
        if (len + 1 >= *cap) {
            size_t ncap = *cap * 2;
            char *tmp = realloc(*buf, ncap);
            if (tmp == NULL) { free(*buf); *buf = NULL; return -1; }
            *buf = tmp;
            *cap = ncap;
        }
        (*buf)[len++] = (char)ch;
        if (ch == '\n') break;
    }
    if (len == 0 && ch == EOF) return -1;
    (*buf)[len] = '\0';
    return (ssize_t)len;
}

int main(void) {
    char *line = NULL, *best = NULL;
    size_t cap = 0, best_len = 0;
    ssize_t len;

    while ((len = read_line(&line, &cap, stdin)) >= 0) {
        size_t n = (size_t)len;
        if (n > 0 && line[n - 1] == '\n') line[--n] = '\0';
        if (best == NULL || n > best_len) {
            char *tmp = realloc(best, n + 1);
            if (tmp == NULL) { free(line); free(best); return 1; }
            best = tmp;
            memcpy(best, line, n + 1);
            best_len = n;
        }
    }

    if (best == NULL) {
        puts("(no input)");
    } else {
        printf("%zu: %s\n", best_len, best);
    }

    free(line);
    free(best);
    return 0;
}
```

The reader grows its buffer geometrically with `realloc`, so lines of any length are fine. A line ending in `\n` has that byte stripped before comparison so the printed length matches what the user typed; the final line without a newline is still counted. Ties keep the first-seen longest line because the comparison is strict `>`.

```rust
fn fibonacci(n: u64) -> Option<u128> {
    let (mut a, mut b): (u128, u128) = (0, 1);
    for _ in 0..n {
        let next = a.checked_add(b)?;
        a = b;
        b = next;
    }
    Some(a)
}

fn main() {
    // Known values.
    let known = [(0u64, 0u128), (1, 1), (2, 1), (10, 55), (50, 12586269025)];
    for (n, expected) in known {
        match fibonacci(n) {
            Some(v) if v == expected => {}
            other => {
                println!("FAIL n={n} got={other:?} expected={expected}");
                std::process::exit(1);
            }
        }
    }

    // u128 overflows somewhere past F(186); confirm the detector fires.
    println!("F(186) = {:?}", fibonacci(186));
    println!("F(187) = {:?}", fibonacci(187));
    println!("F(200) = {:?}", fibonacci(200));

    match fibonacci(200) {
        None => println!("overflow detected as expected"),
        Some(_) => {
            println!("FAIL: expected overflow at n=200");
            std::process::exit(1);
        }
    }
    println!("all checks passed");
}
```

`checked_add` returns `None` on overflow, which we thread out with `?` so the caller sees a clean `Option` instead of a wrapping or panicking result. The iteration keeps two accumulators, so it is O(n) time and O(1) space; F(200) exceeds `u128::MAX`, so `fibonacci(200)` correctly yields `None`.

