#include <charconv>
#include <iostream>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

std::vector<int> parseCsvInts(std::string_view input) {
    std::vector<int> out;
    std::size_t pos = 0;
    while (pos <= input.size()) {
        std::size_t comma = input.find(',', pos);
        std::string_view token = (comma == std::string_view::npos)
            ? input.substr(pos)
            : input.substr(pos, comma - pos);

        // Trim surrounding spaces.
        while (!token.empty() && (token.front() == ' ' || token.front() == '\t')) {
            token.remove_prefix(1);
        }
        while (!token.empty() && (token.back() == ' ' || token.back() == '\t')) {
            token.remove_suffix(1);
        }

        if (!token.empty()) {
            int value = 0;
            auto [ptr, ec] = std::from_chars(token.data(), token.data() + token.size(), value);
            if (ec == std::errc() && ptr == token.data() + token.size()) {
                out.push_back(value);
            }
            // otherwise skip: malformed or overflow
        }

        if (comma == std::string_view::npos) break;
        pos = comma + 1;
    }
    return out;
}

int main() {
    auto eq = [](const std::vector<int>& a, const std::vector<int>& b) { return a == b; };
    bool ok = true;

    ok &= eq(parseCsvInts("1,2,3"), {1, 2, 3});
    ok &= eq(parseCsvInts(""), {});
    ok &= eq(parseCsvInts(",,,"), {});
    ok &= eq(parseCsvInts("1, x, 2, 3.5, -4"), {1, 2, -4});
    ok &= eq(parseCsvInts(" 7 , 8 ,"), {7, 8});
    ok &= eq(parseCsvInts("999999999999999999999"), {});  // overflow skipped
    ok &= eq(parseCsvInts("-2147483648"), {-2147483648});

    std::cout << (ok ? "all checks passed" : "failures") << '\n';
    return ok ? 0 : 1;
}
```

Splitting on commas with `string_view::substr` avoids allocation. `std::from_chars` is the fast, non-throwing conversion; it reports overflow via `std::errc::result_out_of_range` and trailing junk by leaving `ptr` before the end, so both cases are skipped. Empty tokens (from `,,` or a trailing comma) fall out because they do not match.

```python
import threading
from collections import deque


class BoundedQueue:
    """Blocking bounded FIFO queue. put blocks when full, get blocks when empty."""

    def __init__(self, max_size: int):
        if max_size <= 0:
            raise ValueError("max_size must be positive")
        self._max = max_size
        self._items = deque()
        self._lock = threading.Lock()
        self._not_full = threading.Condition(self._lock)
        self._not_empty = threading.Condition(self._lock)

    def put(self, item):
        with self._not_full:
            while len(self._items) >= self._max:
                self._not_full.wait()
            self._items.append(item)
            self._not_empty.notify()

    def get(self):
        with self._not_empty:
            while not self._items:
                self._not_empty.wait()
            item = self._items.popleft()
            self._not_full.notify()
            return item

    def __len__(self):
        with self._lock:
            return len(self._items)


if __name__ == "__main__":
    q = BoundedQueue(2)
    out = []

    def producer():
        for i in range(5):
            q.put(i)

    def consumer():
        for _ in range(5):
            out.append(q.get())

    ts = [threading.Thread(target=producer), threading.Thread(target=consumer)]
    for t in ts:
        t.start()
    for t in ts:
        t.join()
    assert sorted(out) == [0, 1, 2, 3, 4]
    print("ok")
