template <typename T, std::size_t N>
class ArrayStack {
public:
    bool push(const T& value) {
        if (size_ == N) return false;   // overflow
        data_[size_++] = value;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;  // underflow
        return data_[--size_];
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

