#define MAX_WORDS 4096
#define MAX_LEN 64

typedef struct {
    char word[MAX_LEN];
    int count;
} Entry;

int main(void) {
    Entry entries[MAX_WORDS];
    int n = 0;
    char buf[MAX_LEN];

    while (scanf("%63s", buf) == 1) {
        int len = 0;
        for (int i = 0; buf[i] != '\0'; i++) {
            if (isalpha((unsigned char)buf[i]))
                buf[len++] = (char)tolower((unsigned char)buf[i]);
        }
        buf[len] = '\0';
        if (len == 0) continue;

        int found = 0;
        for (int i = 0; i < n; i++) {
            if (strcmp(entries[i].word, buf) == 0) {
                entries[i].count++;
                found = 1;
                break;
            }
        }
        if (!found && n < MAX_WORDS) {
            strcpy(entries[n].word, buf);
            entries[n].count = 1;
            n++;
        }
    }

    for (int top = 0; top < 3 && top < n; top++) {
        int best = top;
        for (int i = top + 1; i < n; i++)
            if (entries[i].count > entries[best].count)
                best = i;
        Entry tmp = entries[top];
        entries[top] = entries[best];
        entries[best] = tmp;
        printf("%s %d\n", entries[top].word, entries[top].count);
    }
    return 0;
}
