#include <cstddef>
#include <cassert>
#include <iostream>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(new int[capacity]), cap_(capacity), head_(0), size_(0) {}

    ~RingBuffer() { delete[] buf_; }

    RingBuffer(const RingBuffer&) = delete;
    RingBuffer& operator=(const RingBuffer&) = delete;

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == cap_; }
    std::size_t size() const { return size_; }

    bool push(int value) {
        if (full()) return false;
        buf_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    bool pop(int& out) {
        if (empty()) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return true;
    }

private:
    int* buf_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    assert(rb.empty());
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.full());
    assert(!rb.push(4));
    int v = 0;
    assert(rb.pop(v) && v == 1);
    assert(rb.push(4));
    assert(rb.pop(v) && v == 2);
    assert(rb.pop(v) && v == 3);
    assert(rb.pop(v) && v == 4);
    assert(rb.empty());
    std::cout << "ok\n";
}
```

The buffer is non-copyable to keep ownership unambiguous; `head_` plus `size_` encodes the read window without an extra tail index.

