std::size_t remove_duplicates(std::vector<int>& values) {
    if (values.empty()) return 0;
    std::size_t write = 1;
    for (std::size_t read = 1; read < values.size(); ++read) {
        if (values[read] != values[write - 1]) {
            values[write] = values[read];
            ++write;
        }
    }
    values.resize(write);
    return write;
