bool is_palindrome(const std::string& s) {
    std::size_t i = 0;
    std::size_t j = s.size();
    while (i < j) {
        // Skip characters from the left that are not alphanumeric.
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[i]))) {
            ++i;
        }
        // Skip characters from the right that are not alphanumeric.
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[j - 1]))) {
            --j;
        }
        if (i < j && std::tolower(static_cast<unsigned char>(s[i])) !=
                    std::tolower(static_cast<unsigned char>(s[j - 1]))) {
            return false;
        }
        ++i;
        --j;
    }
    return true;
