// Remove duplicates in-place order-preserving, keeping the first occurrence.
template <typename T>
std::vector<T> dedupe(const std::vector<T>& input) {
    std::unordered_set<T> seen;
    std::vector<T> out;
    out.reserve(input.size());
    for (const auto& value : input) {
        // insert returns {iterator, did_insert}; only keep the first time.
        if (seen.insert(value).second) {
            out.push_back(value);
        }
    }
    return out;
}

