```rust
fn rolling_mean(data: &[f64], k: usize) -> Vec<f64> {
    if k == 0 {
        return vec![f64::NAN; data.len()];
    }
    let mut out = Vec::with_capacity(data.len());
    let mut sum = 0.0;
    for i in 0..data.len() {
        sum += data[i];
        if i >= k {
            sum -= data[i - k];
        }
        if i + 1 >= k {
            out.push(sum / k as f64);
        } else {
            out.push(f64::NAN);
        }
    }
    out
}

fn main() {
    let r = rolling_mean(&[1.0, 2.0, 3.0, 4.0], 2);
    assert!(r[0].is_nan());
    assert_eq!(r[1], 1.5);
    assert_eq!(r[2], 2.5);
    assert_eq!(r[3], 3.5);

    assert!(rolling_mean(&[], 3).is_empty());
    assert!(rolling_mean(&[1.0], 0)[0].is_nan());
    assert_eq!(rolling_mean(&[5.0], 1)[0], 5.0);
