```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict LRU

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1
    c.put("c", 3)          # evicts "b"
    assert c.get("b") is None
    c.put("c", 30)         # update existing, still 2 entries
    assert len(c) == 2 and c.get("c") == 30
    assert LRUCache(1).get("x") is None
    print("ok")
```

`move_to_end` on every hit keeps recency order; `popitem(last=False)` removes the oldest key. Updating an existing key refreshes recency before insertion.

