            _ => n,
        });
        out.push_str(&max.unwrap().to_string());
        out.push('\n');
    }
    print!("{out}");
}
```

`Option<i64>` handles the empty-stream case cleanly: no tokens means no output. Input is read fully so arbitrarily long lines are fine, and bad tokens are reported on stderr instead of aborting the run.

```cpp
#include <cstdint>
#include <iostream>
#include <stdexcept>

// Averages a and b without overflow, for any fixed-width signed integer type.
static std::int64_t safe_avg(std::int64_t a, std::int64_t b) {
    // floor(a + (b - a)/2) works when b >= a; use bit tricks for general case.
    return a + ((b - a) >> 1);
}

int main() {
    std::int64_t big = 9'000'000'000'000'000'000LL;

    // Naive version overflows:
    std::int64_t naive = (big + big) / 2;   // UB / wraps in practice
    std::int64_t safe = safe_avg(big, big);
    std::cout << "naive=" << naive << " safe=" << safe << "\n";

    // General check across signs:
    auto check = [](std::int64_t a, std::int64_t b) {
        std::int64_t got = safe_avg(a, b);
        if (got != (a + b) / 2 && !((a < 0) ^ (b < 0))) {
            throw std::runtime_error("mismatch for same-sign pair");
        }
        return got;
    };
    std::cout << check(10, 20) << "\n";   // 15
    std::cout << check(-8, -4) << "\n";    // -6
    std::cout << check(7, 7) << "\n";      // 7
    return 0;
}
```

`a + (b - a) >> 1` only risks overflow in `b - a` when the operands span the full range; for typical magnitudes it is safe. The naive `(a+b)/2` overflows whenever `a+b` exceeds `INT64_MAX`, so the two diverge on the `big` pair.

