    assert_eq!(merge_sorted(&[], &[1]), vec![1]);
    assert_eq!(merge_sorted(&[7, 7], &[7, 7]), vec![7, 7, 7, 7]);
    assert_eq!(merge_sorted(&[-3, -1], &[-2, 0]), vec![-3, -2, -1, 0]);
    println!("ok");
}
