```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        bool overwrote = full();
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (overwrote) tail_ = head_;      // drop oldest
        else ++count_;
        return overwrote;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T value = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --count_;
        return value;
    }

    bool full() const { return count_ == N; }
    std::size_t size() const { return count_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0, tail_ = 0, count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    bool ow = rb.push(4);            // overwrites 1
    if (!ow || rb.size() != 3) { std::cerr << "fail\n"; return 1; }
    if (*rb.pop() != 2) { std::cerr << "fail\n"; return 1; }
    rb.pop(); rb.pop();
    if (rb.pop().has_value()) { std::cerr << "fail\n"; return 1; }
    std::cout << "ok\n";
}
```

The buffer is a `std::array` of capacity `N` with `head_`, `tail_`, and `count_` indices taken modulo `N`. On overflow the new value lands at `head_` and `tail_` advances to drop the oldest, so `size()` stays at `N`. `pop` returns `std::optional`, so empty is explicit rather than undefined. Push returns whether it overwrote.

```python
def parse_csv(text):
    """Parse CSV text into a list of rows of fields, honouring quotes."""
    rows, row, field = [], [], []
    in_quotes = False
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                field.append(ch)
        else:
            if ch == '"':
                in_quotes = True
            elif ch == ',':
                row.append(''.join(field)); field = []
            elif ch == '\n':
                row.append(''.join(field)); field = []
                rows.append(row); row = []
            else:
                field.append(ch)
        i += 1
    if field or row:
        row.append(''.join(field))
        rows.append(row)
    return rows


if __name__ == "__main__":
    assert parse_csv('a,b\n1,2') == [['a', 'b'], ['1', '2']]
    assert parse_csv('"x,y",z') == [['x,y', 'z']]
    assert parse_csv('"line\nbreak",b') == [['line\nbreak', 'b']]
    assert parse_csv('"say ""hi""",4') == [['say "hi"', '4']]
    assert parse_csv('') == []
    print("ok")
```

A single pass with an `in_quotes` flag: inside quotes, `""` becomes a literal quote and any other character (including commas and newlines) is kept; outside, commas and newlines delimit fields and rows, and `"` opens a quoted field. The trailing `if field or row` flushes a final row that lacks a terminating newline.

```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), tail_(0), size_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool push(const T& value) {
        if (size_ == data_.size()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % data_.size();
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % data_.size();
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::vector<T> data_;
    std::size_t head_, tail_, size_;
};

int main() {
    RingBuffer<int> rb(3);
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;               // full, must fail
    std::cout << *rb.pop() << "\n";          // 1
    if (!rb.push(4)) return 1;
    while (!rb.empty()) std::cout << *rb.pop() << "\n";  // 2 3 4
    std::cout << (rb.pop().has_value() ? "bad" : "empty ok") << "\n";
    return 0;
}
