```rust
fn eval_rpn(input: &str) -> Result<f64, String> {
    let mut stack: Vec<f64> = Vec::new();
    for tok in input.split_whitespace() {
        match tok {
            "+" | "-" | "*" | "/" => {
                let b = stack.pop().ok_or("missing operand")?;
                let a = stack.pop().ok_or("missing operand")?;
                let v = match tok {
                    "+" => a + b,
                    "-" => a - b,
                    "*" => a * b,
                    _ => {
                        if b == 0.0 {
                            return Err("division by zero".to_string());
                        }
                        a / b
                    }
                };
                stack.push(v);
            }
            _ => {
                let n: f64 = tok.parse().map_err(|_| format!("bad token: {tok}"))?;
                stack.push(n);
            }
        }
    }
    if stack.len() != 1 {
        return Err(format!("expected 1 result, got {}", stack.len()));
    }
    Ok(stack[0])
}

fn main() {
    assert_eq!(eval_rpn("3 4 + 2 *").unwrap(), 14.0);
    assert_eq!(eval_rpn("5 1 2 + 4 * + 3 -").unwrap(), 14.0);
    assert!(eval_rpn("1 0 /").is_err());
    assert!(eval_rpn("1 +").is_err());
    assert!(eval_rpn("1 x +").is_err());
    println!("all checks passed");
}
