#include <stdio.h>
#include <ctype.h>
#include <stdbool.h>

bool is_palindrome(const char *s) {
    const char *left = s;
    const char *right = s;
    while (*right) right++;
    if (right == s) return true;
    right--;

    while (left < right) {
        if (!isalnum((unsigned char)*left)) { left++; continue; }
        if (!isalnum((unsigned char)*right)) { right--; continue; }
        if (tolower((unsigned char)*left) != tolower((unsigned char)*right))
            return false;
        left++;
        right--;
    }
    return true;
}

