```cpp
#include <chrono>
#include <mutex>

class TokenBucket {
public:
    TokenBucket(double rate_per_sec, double burst)
        : rate_(rate_per_sec), capacity_(burst), tokens_(burst),
          last_(std::chrono::steady_clock::now()) {}

    bool try_acquire(double n = 1.0) {
        std::lock_guard<std::mutex> lock(mu_);
        refill();
        if (tokens_ >= n) {
            tokens_ -= n;
            return true;
        }
        return false;
    }

private:
    void refill() {
        auto now = std::chrono::steady_clock::now();
        double elapsed = std::chrono::duration<double>(now - last_).count();
        tokens_ = std::min(capacity_, tokens_ + elapsed * rate_);
        last_ = now;
    }

    double rate_;
    double capacity_;
    double tokens_;
    std::chrono::steady_clock::time_point last_;
    std::mutex mu_;
};
```

Each call refills based on elapsed wall time, capped at the burst capacity, then spends tokens. The mutex makes `try_acquire` safe across threads; `n` lets one call consume more than a single token for weighted requests.

