#include <optional>
#include <stdexcept>

template <typename T>
std::optional<T> max_of(const T* data, std::size_t n) {
    if (data == nullptr || n == 0) return std::nullopt;
    T best = data[0];
    for (std::size_t i = 1; i < n; ++i) {
        if (data[i] > best) best = data[i];
    }
    return best;
}

int main() {
    int values[] = {3, 9, 2, 9, 4};
    auto m1 = max_of(values, 5);
    auto m2 = max_of<int>(nullptr, 0);
    if (!m1 || m2.has_value()) {
        std::cerr << "unexpected result\n";
        return 1;
    }
    std::cout << "max=" << *m1 << "\n";  // max=9
    return 0;
}
```

`std::optional` signals the empty case without a sentinel that could collide with real data. The `data == nullptr` guard is checked before any dereference, so an empty array or null pointer never reads out of bounds, and the template works for any type with `operator>`.

