#include <string.h>
#include <stdio.h>
#include <assert.h>

/* Reverse the null-terminated string s in place. */
void reverse_string(char *s) {
    if (s == NULL) {
        return;
    }
    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) {
        return; /* empty string: nothing to do */
    }
    right--; /* index of last real character */
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_string(a);
    assert(strcmp(a, "olleh") == 0);

    char b[] = "";
    reverse_string(b);
    assert(strcmp(b, "") == 0);

    char c[] = "x";
    reverse_string(c);
    assert(strcmp(c, "x") == 0);

    reverse_string(NULL); /* must not crash */

    printf("%s\n", a);
    return 0;
}
