use std::collections::HashMap;

/// Count occurrences of each whitespace-separated word, then return the
/// `n` most frequent as `(word, count)` pairs, sorted by count descending
/// and ties broken alphabetically. Words are lowercased for comparison.
pub fn top_n_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let normalized: String = word
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '\'')
            .flat_map(|c| c.to_lowercase())
            .collect();
        if normalized.is_empty() {
            continue;
        }
        *counts.entry(normalized).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the quick brown fox jumps over the lazy dog the fox";
    let result = top_n_words(text, 3);
    assert_eq!(result[0], ("the".to_string(), 3));
    assert_eq!(result[1], ("fox".to_string(), 2));
    assert_eq!(result.len(), 3);

    let empty = top_n_words("", 5);
    assert!(empty.is_empty());

    let unicode = top_n_words("café CAFÉ café", 1);
    assert_eq!(unicode[0], ("café".to_string(), 3));

    println!("{:?}", result);
}
