#include <cassert>

bool is_palindrome(const std::string& input) {
    std::size_t left = 0;
    std::size_t right = input.size();

    while (left < right) {
        // Skip non-alphanumeric characters from the left.
        while (left < right &&
               !std::isalnum(static_cast<unsigned char>(input[left]))) {
            ++left;
        }
        // Skip non-alphanumeric characters from the right.
        while (left < right &&
               !std::isalnum(static_cast<unsigned char>(input[right - 1]))) {
            --right;
        }
        if (left >= right) {
            break;
        }
        unsigned char a =
            static_cast<unsigned char>(std::tolower(
                static_cast<unsigned char>(input[left])));
        unsigned char b =
            static_cast<unsigned char>(std::tolower(
                static_cast<unsigned char>(input[right - 1])));
        if (a != b) {
            return false;
        }
        ++left;
        --right;
    }
    return true;
}

int main() {
    assert(is_palindrome("A man, a plan, a canal: Panama"));
    assert(!is_palindrome("race a car"));
    assert(is_palindrome(""));
    assert(is_palindrome(".,"));
    assert(is_palindrome("Was it a car or a cat I saw?"));
    std::cout << "all checks passed\n";
    return 0;
}
