/// Return the nth Fibonacci number (F(0) = 0, F(1) = 1).
/// Returns None if the result would overflow u64.
pub fn fib(n: u64) -> Option<u64> {
    let mut a: u64 = 0;
    let mut b: u64 = 1;
    let mut i = 0;
    while i < n {
        let next = a.checked_add(b)?;
        a = b;
        b = next;
        i += 1;
    }
    Some(a)
}

fn main() {
    assert_eq!(fib(0), Some(0));
    assert_eq!(fib(1), Some(1));
    assert_eq!(fib(10), Some(55));
    assert_eq!(fib(20), Some(6765));

    // F(93) is the largest Fibonacci number that fits in u64.
    assert!(fib(93).is_some());
    assert_eq!(fib(94), None);

    println!("fib(30) = {:?}", fib(30));
}
