/* Parse a non-negative integer from s.
 * Returns true and stores the result in *out on success.
 * Returns false for NULL, empty, non-numeric, or out-of-range input. */
bool parse_nonneg_int(const char *s, unsigned int *out) {
    if (s == NULL || out == NULL || s[0] == '\0') {
        return false;
    }
    /* Reject a leading '-' explicitly; strtoul would wrap it. */
    if (s[0] == '-') {
        return false;
    }
    /* Reject leading/trailing whitespace and garbage. */
    for (const char *p = s; *p != '\0'; ++p) {
        if (*p < '0' || *p > '9') {
            return false;
        }
    }

    errno = 0;
    char *end = NULL;
    unsigned long value = strtoul(s, &end, 10);
    if (errno == ERANGE || *end != '\0' || value > UINT_MAX) {
        return false;
    }
    *out = (unsigned int)value;
    return true;
}

int main(void) {
    unsigned int v = 0;
    if (!parse_nonneg_int("42000", &v) || v != 42000) {
        return 1;
    }
    if (parse_nonneg_int("-1", &v)) return 1;
    if (parse_nonneg_int("12x", &v)) return 1;
    if (parse_nonneg_int("", &v)) return 1;
    if (parse_nonneg_int(NULL, &v)) return 1;
    if (parse_nonneg_int("99999999999999999999", &v)) return 1;
    if (!parse_nonneg_int("0", &v) || v != 0) return 1;
    printf("parse tests passed\n");
    return 0;
}
