import heapq


class RunningMedian:
    """Maintain the median of a growing stream of numbers.

    Uses a max-heap (stored as negatives) for the lower half and a
    min-heap for the upper half, keeping their sizes within one.
    """

    def __init__(self):
        self._low = []   # max-heap via negation
        self._high = []  # min-heap

    def add(self, value: float) -> None:
        if not self._low or value <= -self._low[0]:
            heapq.heappush(self._low, -value)
        else:
            heapq.heappush(self._high, value)

        # Rebalance so len(low) == len(high) or len(low) == len(high) + 1.
        if len(self._low) > len(self._high) + 1:
            heapq.heappush(self._high, -heapq.heappop(self._low))
        elif len(self._high) > len(self._low):
            heapq.heappush(self._low, -heapq.heappop(self._high))

    def median(self) -> float:
        if not self._low:
            raise ValueError("median of an empty stream is undefined")
        if len(self._low) == len(self._high):
            return (-self._low[0] + self._high[0]) / 2.0
        return float(-self._low[0])


if __name__ == "__main__":
    rm = RunningMedian()
    assert rm.median.__self__ is rm
    try:
        rm.median()
        raise AssertionError("expected ValueError")
    except ValueError:
        pass

    for value, expected in [(5, 5.0), (3, 4.0), (8, 5.0), (1, 4.0), (9, 5.0)]:
        rm.add(value)
        assert rm.median() == expected, (value, rm.median(), expected)
    print("running median tests passed")
