import random


def kth_smallest(nums, k):
    """Return the k-th smallest element (1-indexed) of nums."""
    if not nums:
        raise ValueError("nums must be non-empty")
    if k < 1 or k > len(nums):
        raise ValueError(f"k={k} out of range for list of length {len(nums)}")

    arr = list(nums)
    target = k - 1  # convert to 0-indexed rank

    def partition(lo, hi):
        pivot_idx = random.randint(lo, hi)
        arr[pivot_idx], arr[hi] = arr[hi], arr[pivot_idx]
        pivot = arr[hi]
        store = lo
        for i in range(lo, hi):
            if arr[i] < pivot:
                arr[store], arr[i] = arr[i], arr[store]
                store += 1
        arr[store], arr[hi] = arr[hi], arr[store]
        return store

    lo, hi = 0, len(arr) - 1
    while True:
        p = partition(lo, hi)
        if p == target:
            return arr[p]
        elif p < target:
            lo = p + 1
        else:
            hi = p - 1


if __name__ == "__main__":
    print(kth_smallest([7, 10, 4, 3, 20, 15], 3))  # 7
    print(kth_smallest([1], 1))                    # 1
    print(kth_smallest([5, 5, 5, 5], 2))           # 5
    try:
        kth_smallest([], 1)
    except ValueError as e:
        print("empty:", e)
    try:
        kth_smallest([1, 2], 5)
    except ValueError as e:
        print("range:", e)
```

Average O(n), worst case O(n²) due to random pivot; the in-place loop avoids recursion depth issues on large inputs.

