from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least-recently used

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1        # a becomes most recent
    c.put("c", 3)                 # evicts b
    assert c.get("b") is None
    assert c.get("a") == 1
    assert c.get("c") == 3
    c.put("a", 10)                # update existing key
    assert c.get("a") == 10
    assert len(c) == 2
    print("ok")
```

Python 3.7+ `dict`/`OrderedDict` preserves insertion order and supports move-to-end, giving O(1) for both operations. Returning `None` for a miss means you can't store `None` as a value; swap to a sentinel `_MISS` if you need that.

```c
#include <stdio.h>
#include <stdint.h>
#include <limits.h>
#include <errno.h>
#include <ctype.h>

/* Returns 1 on success, 0 on failure. Result stored in *out. */
int parse_i64(const char *s, long long *out) {
    if (s == NULL) return 0;

    const char *p = s;
    while (isspace((unsigned char)*p)) p++;

    int neg = 0;
    if (*p == '+' || *p == '-') {
        neg = (*p == '-');
        p++;
    }
    if (!isdigit((unsigned char)*p)) return 0;

    unsigned long long acc = 0;
    const unsigned long long limit =
        neg ? (unsigned long long)(-(LLONG_MIN + 1)) + 1ULL
            : (unsigned long long)LLONG_MAX;

    while (isdigit((unsigned char)*p)) {
        unsigned digit = (unsigned)(*p - '0');
        if (acc > (limit - digit) / 10ULL) return 0; /* overflow */
        acc = acc * 10ULL + digit;
        p++;
    }

    while (isspace((unsigned char)*p)) p++;
    if (*p != '\0') return 0; /* trailing garbage */

    *out = neg ? -(long long)acc : (long long)acc;
    return 1;
}

int main(void) {
    const char *tests[] = {"42", "   -17  ", "9223372036854775807",
                          "9223372036854775808", "-9223372036854775808",
                          "12abc", "", "abc", "-0"};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); i++) {
        long long v;
        int ok = parse_i64(tests[i], &v);
        printf("%-22s -> %s", tests[i][0] ? tests[i] : "(empty)", ok ? "ok " : "fail");
        if (ok) printf(" %lld", v);
        putchar('\n');
    }
    return 0;
}
```

The overflow check `acc > (limit - digit) / 10` is done before multiplying, so it never wraps. `LLONG_MIN` is handled specially since its absolute value is one larger than `LLONG_MAX`.

