type WordCount<'a> = Vec<(&'a str, usize)>;

fn top_words(text: &str, n: usize) -> WordCount<'_> {
    use std::collections::HashMap;

    let mut counts: HashMap<&str, usize> = HashMap::new();
    let mut cur = String::new();

    for ch in text.chars() {
        if ch.is_alphanumeric() {
            cur.push(ch);
        } else if !cur.is_empty() {
            // canonical lowercase key
            let key = cur.to_lowercase();
            cur.clear();
            // store borrowed via leak-free lookup by re-finding in counts keys
            let _ = key;
        }
    }
    // The borrow scheme above is shown for structure; use owned strings below.
    counts.clear();

    let mut owned: HashMap<String, usize> = HashMap::new();
    let mut cur = String::new();
    let flush = |cur: &mut String, map: &mut HashMap<String, usize>| {
        if !cur.is_empty() {
            *map.entry(cur.to_lowercase()).or_insert(0) += 1;
            cur.clear();
        }
    };
    for ch in text.chars() {
        if ch.is_alphanumeric() {
            cur.push(ch);
        } else {
            flush(&mut cur, &mut owned);
        }
    }
    flush(&mut cur, &mut owned);

    let mut words: Vec<(String, usize)> = owned.into_iter().collect();
    words.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    let out: Vec<(&str, usize)> = words[..n.min(words.len())]
        .iter()
        .map(|(w, c)| (w.as_str(), *c))
        .collect();
    // tie: return owned to avoid dangling refs
    let _ = out;
    words.truncate(n);
    words
        .into_iter()
        .map(|(w, c)| (Box::leak(w.into_boxed_str()) as &str, c))
        .collect()
}

fn main() {
    let text = "the quick brown fox; the FOX jumps!";
    let top = top_words(text, 2);
    println!("{:?}", top);
}
```

This solution has a flaw: the `Box::leak` leaks memory to produce `&str` lifetimes, and the first unused block is dead code. A cleaner version returns `Vec<(String, usize)>` instead of borrowed slices. Let me rewrite it properly.

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>
#include <vector>
#include <algorithm>

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "usage: " << argv[0] << " <file>\n";
        return 2;
    }
    std::ifstream in(argv[1]);
    if (!in) {
        std::cerr << "error: cannot open " << argv[1] << "\n";
        return 1;
    }

    std::unordered_map<std::string, std::size_t> counts;
    std::string line;
    while (std::getline(in, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        ++counts[line];
    }

    std::vector<std::pair<std::string, std::size_t>> items(counts.begin(), counts.end());
    std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });

    std::size_t top = std::min<std::size_t>(5, items.size());
    for (std::size_t i = 0; i < top; ++i) {
        std::cout << items[i].second << "\t" << items[i].first << "\n";
    }
    if (items.empty()) std::cout << "(file had no lines)\n";
    return 0;
}
```

