void reverse_in_place(char *s) {
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; i++) {
        char tmp = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = tmp;
    }
}

int main(void) {
    char buffer[] = "hello world";
    reverse_in_place(buffer);
    printf("%s\n", buffer);  /* dlrow olleh */

    char empty[] = "";
    reverse_in_place(empty);
    printf("[%s]\n", empty);  /* [] */
    return 0;
}
