#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;                              // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap

    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) {
            low.push(x);
        } else {
            high.push(x);
        }

        // rebalance: low may hold at most one more than high
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        double median;
        if (low.size() == high.size()) {
            median = (static_cast<double>(low.top()) + high.top()) / 2.0;
        } else {
            median = static_cast<double>(low.top());
        }
        std::cout << median << '\n';
    }
    return 0;
}
