#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (size_ == N) return false;          // full
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;   // empty
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << std::boolalpha;
    std::cout << rb.push(1) << '\n';  // true
    std::cout << rb.push(2) << '\n';  // true
    std::cout << rb.push(3) << '\n';  // true
    std::cout << rb.push(4) << '\n';  // false, full
    std::cout << *rb.pop() << '\n';   // 1
    std::cout << rb.push(5) << '\n';  // true
    std::cout << *rb.pop() << '\n';   // 2
    std::cout << *rb.pop() << '\n';   // 3
    std::cout << *rb.pop() << '\n';   // 5
    std::cout << rb.empty() << '\n';  // true
    return 0;
}
