        match expected {
            None => expected = Some(cols),
            Some(n) if cols != n => {
                return Err(format!("line {}: expected {} columns, found {}", idx + 1, n, cols));
            }
            _ => {}
        }
        rows += 1;
    }

    Ok(rows)
