    reverse_in_place(c);
    reverse_in_place(d);
    reverse_in_place(NULL);   /* must not crash */

    printf("%s\n", a);  /* olleh */
    printf("[%s]\n", b); /* [] */
    printf("%s\n", c);  /* x */
