#include <string.h>

static void reverse(char *s) {
    if (s == NULL) return;
    size_t i = 0, j = strlen(s);
    while (j > i) {
        char tmp = s[i];
        s[i++] = s[--j];
        s[j] = tmp;
    }
}

int main(void) {
    char buf[128];
    const char *tests[] = {"", "a", "ab", "hello", "racecar"};
    for (size_t k = 0; k < sizeof(tests) / sizeof(tests[0]); k++) {
        snprintf(buf, sizeof buf, "%s", tests[k]);
        reverse(buf);
        printf("[%s]\n", buf);
    }
    return 0;
}
