#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T &value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;            // full -> rejected
    if (rb.pop() != 1) return 1;
    if (!rb.push(4)) return 1;
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n';
    return 0;
}
