```python
import functools
import random
import time


def retry(attempts=3, base_delay=0.1, max_delay=2.0, exceptions=(Exception,)):
    """Retry a function with exponential backoff plus jitter."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == attempts:
                        raise
                    delay = min(max_delay, base_delay * (2 ** (attempt - 1)))
                    time.sleep(delay + random.uniform(0, base_delay))
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base_delay=0.0)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("transient")
        return "done"

    assert flaky() == "done"
    assert calls["n"] == 3

    @retry(attempts=2, base_delay=0.0, exceptions=(KeyError,))
    def always():
        raise KeyError("boom")

    try:
        always()
    except KeyError:
        pass
    else:
        raise AssertionError("should have raised")

    print("ok")
