#include <cctype>
#include <iostream>
#include <string>

bool is_palindrome(const std::string &text) {
    std::size_t i = 0;
    std::size_t j = text.size();
    while (true) {
        while (i < j && !std::isalnum(static_cast<unsigned char>(text[i]))) ++i;
        while (i < j && !std::isalnum(static_cast<unsigned char>(text[j - 1]))) --j;
        if (i >= j) return true;
        unsigned char left = static_cast<unsigned char>(std::tolower(static_cast<unsigned char>(text[i])));
        unsigned char right = static_cast<unsigned char>(std::tolower(static_cast<unsigned char>(text[j - 1])));
        if (left != right) return false;
        ++i;
        --j;
    }
}

int main() {
    const char *yes[] = {"", "a", "A man, a plan, a canal: Panama", "No 'x' in Nixon"};
    const char *no[]  = {"ab", "hello", "palindrome? no"};
    for (const char *s : yes) if (!is_palindrome(s)) { std::cerr << "false negative: " << s << '\n'; return 1; }
    for (const char *s : no)  if (is_palindrome(s))  { std::cerr << "false positive: " << s << '\n'; return 1; }
    std::cout << "ok\n";
    return 0;
}
```
The `unsigned char` casts avoid undefined behaviour from negative `char` values on platforms where `char` is signed.

