#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::priority_queue<int> low;                             // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap

    int value;
    bool first_out = true;
    while (std::cin >> value) {
        if (low.empty() || value <= low.top()) {
            low.push(value);
        } else {
            high.push(value);
        }
        // rebalance so low.size() == high.size() or low is one larger
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        double median;
        if (low.size() == high.size()) {
            median = (low.top() + high.top()) / 2.0;
        } else {
            median = low.top();
        }
        if (!first_out) std::cout << '\n';
        std::cout << median;
        first_out = false;
    }
    return 0;
}
