```c
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *node = malloc(sizeof(Node));
    assert(node != NULL);
    node->value = value;
    node->next = head;
    return node;
}

static int length(const Node *head) {
    int n = 0;
    for (; head != NULL; head = head->next) n++;
    return n;
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    /* empty list */
    assert(reverse(NULL) == NULL);

    /* single node */
    Node *one = push(NULL, 1);
    one = reverse(one);
    assert(one->value == 1 && one->next == NULL);
    free_list(one);

    /* three nodes */
    Node *list = NULL;
    for (int i = 3; i >= 1; i--) list = push(list, i);
    assert(length(list) == 3);
    list = reverse(list);
    assert(list->value == 3 && list->next->value == 2 && list->next->next->value == 1);
    assert(list->next->next->next == NULL);
    free_list(list);

    printf("all tests passed\n");
    return 0;
}
```

The loop keeps three pointers: `prev` (already reversed), `head` (current), and `next` (saved before rewiring). Empty and single-node lists are covered, and all allocations are freed.

```rust
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[], &[1, 2, 3]), vec![1, 2, 3]);
    assert_eq!(merge_sorted(&[1, 3, 5], &[]), vec![1, 3, 5]);
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 3]), vec![1, 1, 1, 2, 3]);
    assert_eq!(merge_sorted(&["a", "c"], &["b", "d"]), vec!["a", "b", "c", "d"]);
    println!("ok");
}
```

One pass with two indices is O(n + m). `with_capacity` avoids reallocation, and the two `extend_from_slice` calls drain whichever side has leftovers. Equal elements from the left slice win, so duplicates stay stable relative to input order.

```cpp
#include <cassert>
#include <iostream>
#include <vector>

// Returns the index of value, or the index where it would be inserted
// to keep the vector sorted.
template <typename T>
size_t lower_bound_index(const std::vector<T>& data, const T& value) {
    size_t lo = 0, hi = data.size();
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (data[mid] < value) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

int main() {
    std::vector<int> v{1, 3, 5, 7, 9};

    assert(lower_bound_index(v, 1) == 0);
    assert(lower_bound_index(v, 5) == 2);
    assert(lower_bound_index(v, 9) == 4);
    // absent values map to an insertion point
    assert(lower_bound_index(v, 0) == 0);
    assert(lower_bound_index(v, 4) == 2);
    assert(lower_bound_index(v, 10) == 5);

    // duplicates: first occurrence
    std::vector<int> d{2, 2, 2, 3};
    assert(lower_bound_index(d, 2) == 0);
    assert(lower_bound_index(d, 3) == 3);

    // empty vector
    std::vector<int> e;
    assert(lower_bound_index(e, 42) == 0);

    std::cout << "all tests passed\n";
    return 0;
}
