This is a faithful lower-bound: it returns the first index whose value is not less than the target. `mid = lo + (hi - lo) / 2` avoids overflow for large vectors. On an empty vector `lo == hi == 0`, so the insertion point is 0.

```c
#include <assert.h>
#include <limits.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

/* Returns true on success. Rejects empty input, trailing garbage,
   and values outside [INT_MIN, INT_MAX]. */
bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;

    const char *p = s;
    bool negative = false;
    if (*p == '+' || *p == '-') {
        negative = (*p == '-');
        p++;
    }
    if (*p == '\0') return false;

    long acc = 0;
    for (; *p != '\0'; p++) {
        if (*p < '0' || *p > '9') return false;
        acc = acc * 10 + (*p - '0');
        if (acc > (long)INT_MAX + 1) return false; /* stop early */
    }
    if (negative) acc = -acc;
    if (acc < INT_MIN || acc > INT_MAX) return false;

    *out = (int)acc;
    return true;
}

int main(void) {
    int v = 0;

    assert(parse_int("0", &v) && v == 0);
    assert(parse_int("42", &v) && v == 42);
    assert(parse_int("-42", &v) && v == -42);
    assert(parse_int("+7", &v) && v == 7);
    assert(parse_int("2147483647", &v) && v == INT_MAX);
    assert(parse_int("-2147483648", &v) && v == INT_MIN);

    assert(!parse_int("", &v));
    assert(!parse_int("-", &v));
    assert(!parse_int("+", &v));
    assert(!parse_int("12a", &v));
    assert(!parse_int(" 12", &v));
    assert(!parse_int("2147483648", &v));   /* INT_MAX + 1 */
    assert(!parse_int("-2147483649", &v));  /* INT_MIN - 1 */
    assert(!parse_int("99999999999999", &v));

    printf("all tests passed\n");
    return 0;
}
```

Accumulation happens in `long` so the multiplication itself cannot overflow on typical platforms, and the value is range-checked against `INT_MIN`/`INT_MAX` before being stored. Anything that is not an optional sign followed by only digits is rejected.

