def second_largest(nums):
    """Return the second-largest distinct value, or None if it does not exist."""
    if not nums:
        return None
    largest = second = None
    for n in nums:
        if largest is None or n > largest:
            second, largest = largest, n
        elif n != largest and (second is None or n > second):
            second = n
    return second


