fn merge(mut xs: Vec<Interval>) -> Vec<Interval> {
    if xs.is_empty() {
        return xs;
    }
    xs.sort_by_key(|iv| (iv.start, iv.end));
    let mut out = vec![xs[0]];
    for iv in &xs[1..] {
        let last = out.last_mut().unwrap();
        if iv.start <= last.end {
            if iv.end > last.end {
                last.end = iv.end;
            }
        } else {
            out.push(*iv);
        }
    }
    out
}

