void rotate_left(int *a, int n, int k) {
    if (n <= 1) {
        return;
    }
    k = ((k % n) + n) % n;
    if (k == 0) {
        return;
    }
    reverse(a, 0, k - 1);
    reverse(a, k, n - 1);
    reverse(a, 0, n - 1);
}

int main(void) {
    int a[] = {1, 2, 3, 4, 5};
    int n = 5;
    rotate_left(a, n, 7);
    for (int i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
