```python
import operator

OPS = {
    "+": operator.add,
    "-": operator.sub,
    "*": operator.mul,
    "/": operator.truediv,
}

def rpn(tokens):
    stack = []
    for tok in tokens:
        if tok in OPS:
            if len(stack) < 2:
                raise ValueError(f"operator {tok!r} needs two operands")
            b = stack.pop()
            a = stack.pop()
            try:
                stack.append(OPS[tok](a, b))
            except ZeroDivisionError:
                raise ValueError("division by zero") from None
        else:
            try:
                stack.append(float(tok))
            except ValueError:
                raise ValueError(f"bad token: {tok!r}") from None
    if len(stack) != 1:
        raise ValueError(f"unbalanced expression, {len(stack)} values left")
    return stack[0]

if __name__ == "__main__":
    print(rpn(["3", "4", "+", "2", "*"]))
    for bad in (["1", "+"], ["4", "0", "/"], ["1", "2"]):
        try:
            rpn(bad)
        except ValueError as e:
            print("rejected:", e)
```

Scans tokens left to right: numbers push, operators pop two and push the result. Underflow, bad tokens, division by zero, and leftover values all raise `ValueError` with the reason.

