#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double v) {
        if (full()) return false;
        data_[head_] = v;
        head_ = (head_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) return std::nullopt;
        double v = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --size_;
        return v;
    }

    bool full()  const { return size_ == N; }
    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0, tail_ = 0, size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    std::cout << rb.push(1.5) << "\n";  // 1
    std::cout << rb.push(2.5) << "\n";  // 1
    std::cout << rb.push(3.5) << "\n";  // 1
    std::cout << rb.push(4.5) << "\n";  // 0 (full)
    std::cout << *rb.pop() << "\n";     // 1.5
    std::cout << rb.push(4.5) << "\n";  // 1
    std::cout << *rb.pop() << "\n";     // 2.5
    return 0;
}
