// Returns std::nullopt if any token is not a valid integer.
std::optional<std::vector<int>> parse_ints(const std::string& line) {
    std::istringstream stream(line);
    std::vector<int> out;
    std::string token;
    while (stream >> token) {
        try {
            std::size_t pos = 0;
            int value = std::stoi(token, &pos);
            if (pos != token.size()) return std::nullopt;  // trailing junk like "12x"
            out.push_back(value);
        } catch (const std::exception&) {
            return std::nullopt;  // out of range or not a number
        }
    }
    return out;
}

