```cpp
#include <algorithm>
#include <string>
#include <cstddef>

// Reverse the order of UTF-8 code points in a string, in place.
void reverse_utf8(std::string &s) {
    std::size_t i = 0, j = s.size();
    while (i < j) {
        // Find start of the next code point from the left.
        std::size_t li = i;
        i += 1;
        while (i < s.size() && (static_cast<unsigned char>(s[i]) & 0xC0) == 0x80) {
            ++i;
        }
        // Find start of the previous code point from the right.
        std::size_t rj = j;
        while (rj > 0 && (static_cast<unsigned char>(s[rj - 1]) & 0xC0) == 0x80) {
            --rj;
        }
        if (li >= rj) break;
        std::reverse(s.begin() + li, s.begin() + i);
        std::reverse(s.begin() + rj, s.begin() + j);
        std::reverse(s.begin() + li, s.begin() + j);
        j = rj - 1;
        // Step back over the trailing continuation bytes now sitting at rj-1..
        while (j > li && (static_cast<unsigned char>(s[j]) & 0xC0) == 0x80) --j;
    }
}
```

Each byte's 0xC0 mask identifies a continuation byte; code points are delimited by their lead byte. Swapping uses a three-`reverse` rotation so multi-byte sequences stay intact rather than being byte-reversed.

