#include <stddef.h>
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) {
        return;
    }
    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0) {
        return;
    }
    j--;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

int main(void) {
    char buf[] = "hello world";
    reverse_in_place(buf);
    if (strcmp(buf, "dlrow olleh") != 0) {
        fprintf(stderr, "fail: %s\n", buf);
        return 1;
    }
    char empty[] = "";
    reverse_in_place(empty);
    char one[] = "x";
    reverse_in_place(one);
    reverse_in_place(NULL);
    puts("ok");
    return 0;
}
```

The two indices meet in the middle, so each character is swapped at most once. `j--` after `strlen` avoids writing past the terminator, and the length-0 check prevents `j` underflowing below zero.

