```python
import heapq

class RunningMedian:
    def __init__(self):
        self.low = []   # max-heap via negation
        self.high = []  # min-heap

    def add(self, value: float) -> None:
        heapq.heappush(self.low, -value)
        heapq.heappush(self.high, -heapq.heappop(self.low))
        if len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def median(self):
        if not self.low:
            return None
        if len(self.low) > len(self.high):
            return -self.low[0]
        return (-self.low[0] + self.high[0]) / 2.0

if __name__ == "__main__":
    rm = RunningMedian()
    out = []
    for x in [5, 15, 1, 3]:
        rm.add(x)
        out.append(rm.median())
    assert out == [5, 10.0, 5, 4.0]
    print(out)
```
`low` holds the smaller half as a max-heap so its top is the largest of that half; `high` holds the larger half. After each push the sizes differ by at most one, so the median is either the top of `low` or the average of both tops. Empty stream returns `None`.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) {
            ++size_;
        }
    }

    T& operator[](std::size_t i) {
        if (i >= size_) throw std::out_of_range("index");
        return data_[(head_ + N - size_ + i) % N];
    }

    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int v : {1, 2, 3, 4}) rb.push(v);
    if (rb.size() != 3) return 1;
    if (rb[0] != 2 || rb[1] != 3 || rb[2] != 4) return 1;
    std::cout << "ok\n";
    return 0;
}
```
`head_` is the next write slot and `size_` caps at `N`, so once full every push overwrites the slot that is `size_` positions behind the head. Indexing maps logical position to physical slot using `(head_ + N - size_ + i) % N`, which works whether or not the buffer has wrapped.

```cpp
#include <iostream>

struct Node {
    int value;
    Node* next;
    Node(int v, Node* n = nullptr) : value(v), next(n) {}
};

Node* cycle_entry(Node* head) {
    Node* slow = head;
    Node* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            Node* probe = head;
            while (probe != slow) {
                probe = probe->next;
                slow = slow->next;
            }
            return probe;
        }
    }
    return nullptr;
}

int main() {
    Node* a = new Node(1);
    Node* b = new Node(2);
    Node* c = new Node(3);
    Node* d = new Node(4);
    a->next = b; b->next = c; c->next = d; d->next = b;
    Node* entry = cycle_entry(a);
    if (entry != b) return 1;
    d->next = nullptr;
    if (cycle_entry(a) != nullptr) return 2;
    delete a; delete b; delete c; delete d;
    std::cout << "ok\n";
    return 0;
}
```
Floyd's tortoise and hare meet inside the cycle. The distance from the head to the entry equals the distance from the meeting point to the entry going forward, so advancing one pointer from the head and one from the meeting point lands both on the entry node. Returns `nullptr` when the list terminates.

