fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let expected = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(expected) {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    assert!(is_balanced(""));
    assert!(is_balanced("([{}])"));
    assert!(!is_balanced("([)]"));
    assert!(!is_balanced("))"));
    assert!(!is_balanced("("));
    println!("ok");
}
```
Every opener is pushed; every closer must pop a matching opener, which immediately rejects a stray closer via `None` and rejects wrong nesting like `([)]`. Non-bracket characters are ignored, and the string is balanced only if the stack is empty at the end.

