            sieve[p * p : limit + 1 : p] = bytearray(len(range(p * p, limit + 1, p)))
        p += 1
    for n in range(2, limit + 1):
        if sieve[n]:
            yield n

if __name__ == "__main__":
    assert list(primes_up_to(10)) == [2, 3, 5, 7]
    assert list(primes_up_to(1)) == []
    assert sum(1 for _ in primes_up_to(100)) == 25
    print("ok")
```
The slice assignment marks composites in one pass. The generator never materialises the list of primes, only the sieve array.

