std::optional<long long> max_field(const std::string& line) {
    std::optional<long long> best;
    std::stringstream ss(line);
    std::string token;
    while (std::getline(ss, token, ',')) {
        size_t a = 0, b = token.size();
        while (a < b && std::isspace(static_cast<unsigned char>(token[a]))) ++a;
        while (b > a && std::isspace(static_cast<unsigned char>(token[b - 1]))) --b;
        if (a == b) continue;
        try {
            long long v = std::stoll(token.substr(a, b - a));
            if (!best || v > *best) best = v;
        } catch (const std::exception&) {
            continue;
        }
    }
    return best;
}

