```cpp
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), size_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool push(double value) {
        if (size_ == cap_) return false;
        buf_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    double pop() {
        if (size_ == 0) throw std::out_of_range("pop on empty buffer");
        double value = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::vector<double> buf_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    std::cout << std::boolalpha << rb.push(1.5) << rb.push(2.5) << rb.push(3.5) << "\n";
    std::cout << rb.push(4.5) << "\n";  // false: full
    while (!rb.empty()) std::cout << rb.pop() << " ";
    std::cout << "\n";
    try {
        rb.pop();
    } catch (const std::out_of_range& e) {
        std::cout << "caught: " << e.what() << "\n";
    }
    return 0;
}
```

The modulo index wraps both head and tail. Full pushes return `false`; popping an empty buffer throws `std::out_of_range`, which the test catches.

