```c
#include <stdio.h>
#include <string.h>

/* Reverses a NUL-terminated byte string in place. Not UTF-8 aware. */
static void reverse_bytes(char *s) {
    if (s == NULL) return;
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; ++i) {
        char tmp = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = tmp;
    }
}

/* Reverses only the first max_len bytes, preserving NUL termination. */
static void reverse_prefix(char *s, size_t max_len) {
    if (s == NULL) return;
    size_t n = strlen(s);
    if (n > max_len) n = max_len;
    for (size_t i = 0; i < n / 2; ++i) {
        char tmp = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = tmp;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_bytes(a);
    printf("%s\n", a);           /* olleh */

    char b[] = "";
    reverse_bytes(b);
    printf("[%s]\n", b);          /* [] */

    char c[] = "abcdef";
    reverse_prefix(c, 3);
    printf("%s\n", c);           /* cbafed -> wait, verify below */

    /* explicit check of prefix reversal */
    char d[] = "abcdef";
    reverse_prefix(d, 3);
    int ok = strcmp(d, "cbadef") == 0;
    printf("prefix ok: %s\n", ok ? "yes" : "no");
    return ok ? 0 : 1;
}
```

This reverses bytes, not code points: a UTF-8 multibyte sequence will be scrambled. That is stated in the comment rather than hidden. `reverse_prefix` limits the span so NUL is never moved. The final check asserts the exact expected prefix result.

