fn longest_common_prefix(strs: &[String]) -> String {
    if strs.is_empty() {
        return String::new();
    }
    let first = strs[0].as_bytes();
    let mut len = first.len();
    for s in &strs[1..] {
        let b = s.as_bytes();
        let mut i = 0;
        while i < len && i < b.len() && first[i] == b[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            break;
        }
    }
    while len > 0 && !strs[0].is_char_boundary(len) {
        len -= 1;
    }
    strs[0][..len].to_string()
}

