#include <array>
#include <cstddef>
#include <cstdio>
#include <stdexcept>

 template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    bool pop(T& out) {
        if (size_ == 0) return false;
        out = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return N; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;          // full, must reject
    if (rb.size() != 3) return 1;
    int v = 0;
    if (!rb.pop(v) || v != 1) return 1;
    if (!rb.push(4)) return 1;          // wraparound slot
    while (rb.pop(v)) std::printf("%d ", v);
    std::printf("\n");
    return rb.empty() ? 0 : 1;
}
