def is_valid_ipv4(address):
    """Return True if address is a dotted-quad IPv4 string with 0-255 octets."""
    if not isinstance(address, str):
        return False
    parts = address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":  # reject leading zeros
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True


