static void reverse(char *s)
{
    if (s == NULL) return;
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; i++) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
}

int main(void)
{
    char buf[256];
    if (fgets(buf, sizeof buf, stdin) == NULL) return 0;
    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] == '\n') buf[--len] = '\0';
    reverse(buf);
    puts(buf);
    return 0;
}
