// Fibonacci index is capped where F(n) still fits in uint64_t (F(93)).
uint64_t fib(unsigned n) {
    static std::vector<uint64_t> memo{0, 1};
    if (n >= 94) {
        throw std::out_of_range("F(n) overflows uint64_t for n >= 94");
    }
    while (memo.size() <= n) {
        memo.push_back(memo[memo.size() - 1] + memo[memo.size() - 2]);
    }
    return memo[n];
}

int main() {
    unsigned inputs[] = {0, 1, 10, 50, 93};
    for (unsigned n : inputs) {
        std::cout << "F(" << n << ") = " << fib(n) << '\n';
    }
    try {
        fib(94);
    } catch (const std::out_of_range& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
```
The `static` memo persists across calls, so each value is computed once. The cap at 93 is where `uint64_t` still holds the result; 94 overflows and is rejected.

