// Reverse the whole string, then reverse each word back.
static void reverse_range(std::string& s, std::size_t lo, std::size_t hi) {
    while (lo < hi) {
        std::swap(s[lo], s[hi]);
        ++lo;
        --hi;
    }
}

std::string reverse_words(std::string s) {
    if (s.empty()) return s;
    reverse_range(s, 0, s.size() - 1);
    std::size_t start = 0;
    for (std::size_t i = 0; i <= s.size(); ++i) {
        if (i == s.size() || s[i] == ' ') {
            if (i > start) reverse_range(s, start, i - 1);
            start = i + 1;
        }
    }
    return s;
}

int main() {
    std::cout << '[' << reverse_words("") << "]\n";
    std::cout << '[' << reverse_words("hello") << "]\n";
    std::cout << '[' << reverse_words("the quick brown fox") << "]\n";
    std::cout << '[' << reverse_words("a  b") << "]\n";
    return 0;
}
```
Output is `[]`, `[hello]`, `[fox brown quick the]`, and for `"a  b"` the double space is preserved as `[b  a]`. The bounds check `i > start` avoids trying to reverse an empty word.

