import threading


class BoundedCounter:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.value = 0
        self._cond = threading.Condition()

    def increment(self):
        with self._cond:
            while self.value >= self.capacity:
                self._cond.wait()
            self.value += 1
            self._cond.notify_all()
            return self.value

    def decrement(self):
        with self._cond:
            while self.value <= 0:
                self._cond.wait()
            self.value -= 1
            self._cond.notify_all()
            return self.value

    def snapshot(self):
        with self._cond:
            return self.value


if __name__ == "__main__":
    c = BoundedCounter(3)
    assert c.increment() == 1
    assert c.decrement() == 0
    try:
        BoundedCounter(0)
    except ValueError as e:
        assert "positive" in str(e)
    print("ok", c.snapshot())
