#include <array>
#include <cstddef>
#include <stdexcept>
#include <iostream>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push_back(const T& item) {
        if (size_ == N) {
            return false;
        }
        data_[(head_ + size_) % N] = item;
        ++size_;
        return true;
    }

    T pop_front() {
        if (size_ == 0) {
            throw std::out_of_range("ring buffer is empty");
        }
        T item = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return item;
    }

    T& at(std::size_t i) {
        if (i >= size_) {
            throw std::out_of_range("index out of range");
        }
        return data_[(head_ + i) % N];
    }

    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.push_back(1) || !rb.push_back(2) || !rb.push_back(3)) return 1;
    if (rb.push_back(4)) return 1;            // full, must fail
    if (rb.pop_front() != 1) return 1;        // frees one slot
    if (!rb.push_back(4)) return 1;           // now succeeds
    if (rb.at(2) != 4) return 1;
    std::cout << "ok size=" << rb.size() << "\n";
}
