#include <cstdlib>
#include <iostream>
#include <type_traits>

template <typename T>
constexpr T gcd(T a, T b) {
    static_assert(std::is_integral<T>::value, "integral required");
    a = a < 0 ? -a : a;
    b = b < 0 ? -b : b;
    while (b != 0) {
        T t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    static_assert(gcd(48, 18) == 6);
    static_assert(gcd(-48, 18) == 6);
    static_assert(gcd(0, 5) == 5);
    static_assert(gcd(0, 0) == 0);
    std::cout << gcd(1071, 462) << "\n";
    return 0;
}
```

Takes absolute values first so negatives behave, loops until the remainder is zero, and returns the last nonzero value. `gcd(0,0)` is 0 by the loop not running; constexpr allows the static_asserts at compile time.

