from collections import Counter


def tokenize(text):
    words = []
    buf = []
    for ch in text:
        if ch.isalpha() or ch == "'":
            buf.append(ch)
        else:
            if buf:
                words.append("".join(buf))
                buf = []
    if buf:
        words.append("".join(buf))
    return [w.lower() for w in words]


def top_words(path, n=10):
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    text = unicodedata.normalize("NFKC", text)
    counts = Counter(tokenize(text))
    return counts.most_common(n)


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: python wordfreq.py <file>", file=sys.stderr)
        sys.exit(1)
    for word, count in top_words(sys.argv[1]):
        print(f"{count:5d}  {word}")
```

`str.isalpha()` handles accented and non-Latin letters, and NFKC normalisation folds compatibility forms so visually identical words merge. Ties in `most_common` are broken by first-seen order, which is stable.

