struct ParseResult {
    std::vector<int> values;
    bool ok = true;
    std::size_t bad_token = 0;  // 0-based token index of the first failure
};

ParseResult parse_int_list(std::string_view line) {
    ParseResult out;
    std::size_t token = 0;
    std::size_t start = 0;
    while (start <= line.size()) {
        std::size_t comma = line.find(',', start);
        std::string_view field = (comma == std::string_view::npos)
                                     ? line.substr(start)
                                     : line.substr(start, comma - start);
        // trim surrounding spaces
        while (!field.empty() && field.front() == ' ') field.remove_prefix(1);
        while (!field.empty() && field.back() == ' ') field.remove_suffix(1);

        if (field.empty()) {
            out.ok = false;
            out.bad_token = token;
            return out;
        }
        int value = 0;
        auto [ptr, ec] = std::from_chars(field.data(), field.data() + field.size(), value);
        if (ec != std::errc() || ptr != field.data() + field.size()) {
            out.ok = false;
            out.bad_token = token;
            return out;
        }
        out.values.push_back(value);
        ++token;
        if (comma == std::string_view::npos) break;
        start = comma + 1;
    }
    return out;
}
```

Uses `std::from_chars`, which is locale-free and rejects trailing junk, so `"12x"` fails cleanly. On failure the caller gets the exact token index and the values parsed so far.

