```c
#include <stddef.h>

static int utf8_len(unsigned char b) {
    if (b < 0x80) return 1;
    if ((b & 0xE0) == 0xC0) return 2;
    if ((b & 0xF0) == 0xE0) return 3;
    if ((b & 0xF8) == 0xF0) return 4;
    return 1; /* invalid lead byte: treat as one unit */
}

size_t longest_run(const char *s) {
    if (s == NULL || *s == '\0') return 0;
    size_t best = 1, run = 1;
    const unsigned char *p = (const unsigned char *)s;
    const unsigned char *prev = p;
    p += utf8_len(*p);

    while (*p != '\0') {
        int len = utf8_len(*p);
        int same = 1;
        for (int i = 0; i < len; i++) {
            if (p[i] != prev[i] || p[i] == '\0') { same = 0; break; }
        }
        if (same) {
            run++;
            if (run > best) best = run;
        } else {
            run = 1;
        }
        prev = p;
        p += len;
    }
    return best;
}
```

It walks codepoint by codepoint rather than byte by byte, so a repeated multi-byte emoji or accented letter counts as one character, and invalid lead bytes degrade to length 1 instead of overrunning.

