class Node:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right


def is_valid_bst(root):
    if root is None:
        return True
    stack = [(root, None, None)]
    while stack:
        node, low, high = stack.pop()
        if low is not None and node.value <= low:
            return False
        if high is not None and node.value >= high:
            return False
        if node.left is not None:
            stack.append((node.left, low, node.value))
        if node.right is not None:
            stack.append((node.right, node.value, high))
    return True


if __name__ == "__main__":
    good = Node(10, Node(5, Node(3), Node(8)), Node(15, Node(12), Node(20)))
    dup = Node(10, Node(5, Node(5)), None)
    bad = Node(10, Node(5, Node(3), Node(12)), Node(15))
    print(is_valid_bst(good))  # True
    print(is_valid_bst(dup))   # False
    print(is_valid_bst(bad))   # False
```

Each stack frame carries the open `(low, high)` interval, so a node is checked against the full ancestor constraint rather than just its parent. Strict comparisons reject equal keys.

