struct ParseError {
    index: usize,
    field: String,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "field {} ({:?}) is not an integer", self.index, self.field)
    }
}

fn parse_line(line: &str) -> Result<Vec<i64>, ParseError> {
    if line.trim().is_empty() {
        return Ok(Vec::new());
    }
    line.split(',')
        .enumerate()
        .map(|(i, raw)| {
            let field = raw.trim();
            field.parse::<i64>().map_err(|_: ParseIntError| ParseError {
                index: i,
                field: field.to_string(),
            })
        })
        .collect()
}

fn main() {
    assert_eq!(parse_line("1, 2, 3").unwrap(), vec![1, 2, 3]);
    assert_eq!(parse_line("").unwrap(), Vec::<i64>::new());
    assert!(parse_line("1, x, 3").is_err());
    println!("{:?}", parse_line("4, 5"));
}
```

Each field is trimmed before parsing, so `"1, 2, 3"` works. The error carries the offending index and text instead of a bare `ParseIntError`, and the empty-line case returns an empty vector rather than failing.

```rust
use std::collections::BinaryHeap;

fn top_k<T: Ord + Copy>(items: &[T], k: usize) -> Vec<T> {
    if k == 0 || items.is_empty() {
        return Vec::new();
    }
    let mut heap: BinaryHeap<&T> = BinaryHeap::with_capacity(k);
    for item in items {
        heap.push(item);
        if heap.len() > k {
            heap.pop(); // drops the current smallest
        }
    }
    heap.into_sorted_vec().into_iter().copied().collect()
}

fn main() {
    assert_eq!(top_k(&[3, 1, 4, 1, 5, 9, 2, 6], 3), vec![6, 5, 9]);
    assert_eq!(top_k(&[1, 2], 5), vec![1, 2]);
    assert!(top_k::<i32>(&[], 3).is_empty());
    let words = ["pear", "apple", "fig"];
    println!("{:?}", top_k(&words, 2)); // ["pear", "fig"]
}
```

A max-heap that evicts once it exceeds size `k` keeps memory at O(k) and time at O(n log k). `BinaryHeap<&T>` avoids copying elements, and `Ord + Copy` covers both integers and `&str` here.

