#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;
    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    printf("%s\n", a);  // olleh

    char b[] = "";
    reverse_in_place(b);
    printf("[%s]\n", b);  // []

    char c[] = "x";
    reverse_in_place(c);
    printf("%s\n", c);  // x
    return 0;
}
