#include <array>
#include <optional>
#include <cstddef>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<double> pop() {
        if (count_ == 0) return std::nullopt;
        double value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }
    std::size_t size() const { return count_; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1.0);
    rb.push(2.0);
    rb.push(3.0);
    bool rejected = !rb.push(4.0);
    double first = rb.pop().value();
    return (rejected && first == 1.0 && rb.size() == 2) ? 0 : 1;
}
