```cpp
#include <condition_variable>
#include <deque>
#include <mutex>
#include <optional>
#include <utility>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t cap) : cap_(cap) {}

    bool push(int value) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [this] { return closed_ || q_.size() < cap_; });
        if (closed_) return false;
        q_.push_back(value);
        not_empty_.notify_one();
        return true;
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [this] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;  // closed and drained
        int v = q_.front();
        q_.pop_front();
        not_full_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lk(m_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::mutex m_;
    std::condition_variable not_full_, not_empty_;
    std::deque<int> q_;
    std::size_t cap_;
    bool closed_ = false;
};
```
`pop` returns `nullopt` only after `close()` and full drain, so consumers can distinguish "empty for now" from "finished". Both waits use the predicate form to avoid spurious wakeups.

```cpp
#include <algorithm>
#include <utility>
#include <vector>

class MinHeap {
public:
    void push(int v) {
        data_.push_back(v);
        std::size_t i = data_.size() - 1;
        while (i > 0) {
            std::size_t parent = (i - 1) / 2;
            if (data_[parent] <= data_[i]) break;
            std::swap(data_[parent], data_[i]);
            i = parent;
        }
    }

    int pop() {
        int top = data_.front();
        data_.front() = data_.back();
        data_.pop_back();
        sift_down(0);
        return top;
    }

    bool empty() const { return data_.empty(); }

private:
    void sift_down(std::size_t i) {
        while (true) {
            std::size_t l = 2 * i + 1, r = 2 * i + 2, smallest = i;
            if (l < data_.size() && data_[l] < data_[smallest]) smallest = l;
            if (r < data_.size() && data_[r] < data_[smallest]) smallest = r;
            if (smallest == i) return;
            std::swap(data_[i], data_[smallest]);
            i = smallest;
        }
    }

    std::vector<int> data_;
};

std::vector<int> heap_sort(std::vector<int> in) {
    MinHeap h;
    for (int v : in) h.push(v);
    std::vector<int> out;
    out.reserve(in.size());
    while (!h.empty()) out.push_back(h.pop());
    return out;
}

#ifdef HEAP_DEMO
#include <iostream>
int main() {
    for (int v : heap_sort({5, 3, 9, 1, 3, -4, 0})) std::cout << v << ' ';
    std::cout << '\n';  // -4 0 1 3 3 5 9
}
#endif
```
Build with `g++ -DHEAP_DEMO -std=c++17 heap.cpp -o heap`. Duplicates are preserved; `pop()` assumes the heap is non-empty, so call `empty()` first.

