use std::collections::HashMap;
use std::error::Error;
use std::fmt;

#[derive(Debug)]
struct DuplicateKey(String);

impl fmt::Display for DuplicateKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "duplicate key: {}", self.0)
    }
}

impl Error for DuplicateKey {}

fn parse_config(src: &str) -> Result<HashMap<String, String>, DuplicateKey> {
    let mut map = HashMap::new();
    for (lineno, raw) in src.lines().enumerate() {
        let line = match raw.find('#') {
            Some(idx) => &raw[..idx],
            None => raw,
        }
        .trim();
        if line.is_empty() {
            continue;
        }
        let (key, value) = match line.split_once('=') {
            Some(kv) => kv,
            None => {
                eprintln!("line {}: no '=' in {line:?}, skipping", lineno + 1);
                continue;
            }
        };
        let (key, value) = (key.trim().to_string(), value.trim().to_string());
        if key.is_empty() {
            eprintln!("line {}: empty key, skipping", lineno + 1);
            continue;
        }
        if map.insert(key.clone(), value).is_some() {
            return Err(DuplicateKey(key));
        }
    }
    Ok(map)
}

fn main() {
    let src = "# app config\nhost = 127.0.0.1\n\nport=8080  # inline comment\n";
    let cfg = parse_config(src).expect("valid config");
    assert_eq!(cfg["host"], "127.0.0.1");
    assert_eq!(cfg["port"], "8080");
    assert!(parse_config("a=1\na=2").is_err());
    println!("{:?}", cfg);
}
```
`split_once('=')` keeps values containing `=` intact, and comments work both on their own line and inline. Duplicate keys are a hard error rather than a silent overwrite.

