#!/usr/bin/env bash
set -euo pipefail

dir=${1:-.}
[[ -d "$dir" ]] || { echo "not a directory: $dir" >&2; exit 1; }

# Group by size first (cheap), then hash only size-collisions.
tmp=$(mktemp)
trap 'rm -f "$tmp"' EXIT

find "$dir" -type f -printf '%s\t%p\0' 2>/dev/null \
  | sort -z -k1,1n \
  | awk -v RS='\0' -F'\t' 'NF==2 {print $1"\t"$2}' \
  | while IFS=$'\t' read -r size path; do
      hash=$(sha256sum -- "$path" | cut -d' ' -f1)
      printf '%s\t%s\t%s\n' "$hash" "$size" "$path"
    done > "$tmp"

sort "$tmp" | awk -F'\t' '
  { if ($1 == prev) { if (!shown) { print "dup:"; print "  " prev_path; shown=1 }
                     print "  " $3 }
    else { shown=0 }
    prev=$1; prev_path=$3 }
'
