```python
def rle_encode(text: str) -> str:
    if not text:
        return ""
    out = []
    prev, count = text[0], 0
    for ch in text:
        if ch == prev:
            count += 1
        else:
            out.append(f"{count}{prev}")
            prev, count = ch, 1
    out.append(f"{count}{prev}")
    return "".join(out)


def rle_decode(encoded: str) -> str:
    out = []
    i = 0
    while i < len(encoded):
        if not encoded[i].isdigit():
            raise ValueError(f"expected a count at index {i}, got {encoded[i]!r}")
        j = i
        while j < len(encoded) and encoded[j].isdigit():
            j += 1
        if j == len(encoded):
            raise ValueError("trailing count with no character")
        out.append(encoded[j] * int(encoded[i:j]))
        i = j + 1
    return "".join(out)


if __name__ == "__main__":
    cases = ["", "a", "aaaabbbcc", "\u4f60\u4f60\u4f60\u597d", "\U0001f600\U0001f600\U0001f600x"]
    for original in cases:
        encoded = rle_encode(original)
        assert rle_decode(encoded) == original, (original, encoded)
    try:
        rle_decode("12")
    except ValueError as exc:
        print("rejected:", exc)
    print("round-trips ok")
```
Multi-digit counts let runs exceed length 9, and the decoder walks digit runs so `"12a"` becomes twelve `a`s. Non-ASCII characters are treated as single code points throughout.

```python
import functools
import random
import time


def retry(attempts: int = 4, base_delay: float = 0.5, max_delay: float = 8.0,
          exceptions=(OSError,), no_retry=(ValueError,)):
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except no_retry:
                    raise
                except exceptions as exc:
                    last = exc
                    if attempt == attempts:
                        break
                    delay = min(base_delay * 2 ** (attempt - 1), max_delay)
                    delay = random.uniform(0, delay)  # full jitter
                    time.sleep(delay)
            raise last
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=3, base_delay=0.01)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise OSError("transient")
        return "done"

    assert flaky() == "done" and calls["n"] == 3

    @retry(attempts=3, base_delay=0.01)
    def bad():
        raise ValueError("never retried")

    try:
        bad()
    except ValueError:
        print("ValueError propagated immediately")
```
Jitter is sampled fresh on each retry so a flock of callers doesn't synchronise. After the final attempt the original exception is re-raised unchanged, preserving the traceback.

