#include <limits.h>
#include <stdio.h>
#include <string.h>

static const char digits[] = "0123456789abcdef";

int itoa_base(int value, int base, char *buf, size_t buflen) {
    if (base < 2 || base > 16 || buf == NULL || buflen == 0) return -1;
    char tmp[64];
    int neg = value < 0;
    unsigned int uv = neg ? (unsigned int)(-(long long)value) : (unsigned int)value;
    size_t n = 0;
    do {
        tmp[n++] = digits[uv % (unsigned)base];
        uv /= (unsigned)base;
    } while (uv > 0);
    if (neg) tmp[n++] = '-';
    if (n + 1 > buflen) return -1;
    for (size_t i = 0; i < n; i++) buf[i] = tmp[n - 1 - i];
    buf[n] = '\0';
    return (int)n;
}

int main(void) {
    char buf[64];
    int len = itoa_base(-255, 16, buf, sizeof buf);
    printf("%d %s\n", len, buf);
    return 0;
