// Rotate v right by k positions. Handles empty vectors and k >= n.
template <typename T>
void rotate_right(std::vector<T>& v, std::size_t k) {
    const std::size_t n = v.size();
    if (n == 0) return;
    k %= n;              // k larger than n wraps around
    if (k == 0) return;  // nothing to do
    std::reverse(v.begin(), v.end());
    std::reverse(v.begin(), v.begin() + k);
    std::reverse(v.begin() + k, v.end());
}

int main() {
    std::vector<int> a{1, 2, 3, 4, 5};
    rotate_right(a, 2);
    for (int x : a) std::cout << x << ' ';  // 4 5 1 2 3
    std::cout << '\n';

    std::vector<int> empty;
    rotate_right(empty, 7);                  // no crash
    std::cout << "empty size: " << empty.size() << '\n';

    std::vector<int> b{1, 2, 3};
    rotate_right(b, 4);                      // k = 4 -> 1
    for (int x : b) std::cout << x << ' ';  // 3 1 2
    std::cout << '\n';
    return 0;
}
