```python
def rle_encode(text: str) -> str:
    """Encode runs as <char><count>, e.g. 'aaabb' -> 'a3b2'."""
    if not text:
        return ""
    parts = []
    current = text[0]
    count = 1
    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(f"{current}{count}")
            current, count = ch, 1
    parts.append(f"{current}{count}")
    return "".join(parts)


def rle_decode(encoded: str) -> str:
    """Decode '<char><count>' pairs produced by rle_encode."""
    out = []
    i = 0
    n = len(encoded)
    while i < n:
        ch = encoded[i]
        i += 1
        digits = []
        while i < n and encoded[i].isdigit():
            digits.append(encoded[i])
            i += 1
        if not digits:
            raise ValueError(f"missing count after {ch!r} at index {i - 1}")
        out.append(ch * int("".join(digits)))
    return "".join(out)


if __name__ == "__main__":
    cases = ["", "a", "aaabb", "abc", "\u00e9\u00e9\u00e9\u4e2d\u4e2d"]
    for c in cases:
        enc = rle_encode(c)
        assert rle_decode(enc) == c, (c, enc)
    print(rle_encode("aaabb"))
    print(rle_decode("a3b2"))
```

Working in terms of Python `str` (code points, not bytes) means multi-byte characters like `\u00e9` encode and decode as single units without corruption.

```c
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

bool has_cycle(const Node *head) {
    const Node *slow = head;
    const Node *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

static Node *make(int v) {
    Node *n = malloc(sizeof(Node));
    if (!n) exit(1);
    n->value = v;
    n->next = NULL;
    return n;
}

int main(void) {
    Node *a = make(1), *b = make(2), *c = make(3);
    a->next = b; b->next = c;
    printf("cycle before: %d\n", has_cycle(a));  // 0

    Node *r = reverse(a);
    printf("reversed: %d %d %d\n", r->value, r->next->value, r->next->next->value);

    r->next->next->next = r;  // create a cycle
    printf("cycle after: %d\n", has_cycle(r)); // 1

    r->next->next->next = NULL;
    while (r) { Node *tmp = r; r = r->next; free(tmp); }
    return 0;
}
```

`reverse` runs in O(n) with O(1) extra space, and `has_cycle` uses the slow/fast pointer pair so it needs no extra memory and a NULL check on `fast->next`.

```rust
/// Longest common prefix of `words`, compared by Unicode scalar value.
/// Returns "" for an empty slice or when the first characters differ.
pub fn longest_common_prefix(words: &[&str]) -> String {
    let Some(first) = words.first() else {
        return String::new();
    };
    let mut end = first.len(); // byte length of the current prefix
    for w in &words[1..] {
        let mut i = 0;
        let fb = first.as_bytes();
        let wb = w.as_bytes();
        while i < end && i < wb.len() && fb[i] == wb[i] {
            i += 1;
        }
        end = i;
        // Don't split a multi-byte char: back off to a char boundary.
        while end > 0 && !first.is_char_boundary(end) {
            end -= 1;
        }
        if end == 0 {
            return String::new();
        }
    }
    first[..end].to_string()
}

fn main() {
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&[""]), "");
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&["caf\u00e9", "cafeteria"]), "caf");
    assert_eq!(longest_common_prefix(&["\u00e9", "e"]), "");
    println!("ok");
}
```

The byte comparison is fast, but after each reduction `is_char_boundary` backs `end` off so a shared multi-byte prefix is never cut mid-character, which is why `"\u00e9"` versus `"e"` yields `""` instead of a panic.

