def median_two_sorted(a, b):
    # Merge-only-as-far-as-needed, then index the middle of the combined list.
    i = j = 0
    total = len(a) + len(b)
    if total == 0:
        raise ValueError("median of empty inputs is undefined")
    mid = total // 2
    merged = []
    while len(merged) <= mid and i < len(a) and j < len(b):
        if a[i] <= b[j]:
            merged.append(a[i]); i += 1
        else:
            merged.append(b[j]); j += 1
    if len(merged) <= mid:
        merged.extend(a[i:] if i < len(a) else b[j:])
    if total % 2:
        return float(merged[mid])
    return (merged[mid - 1] + merged[mid]) / 2.0


if __name__ == "__main__":
    assert median_two_sorted([1, 3], [2]) == 2.0
    assert median_two_sorted([1, 2], [3, 4]) == 2.5
    assert median_two_sorted([], [7]) == 7.0
