int lis_length(const std::vector<int>& nums) {
    std::vector<int> tails;  // tails[k] = smallest tail of an LIS of length k+1
    for (int x : nums) {
        auto it = std::lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) tails.push_back(x);
        else *it = x;
    }
    return static_cast<int>(tails.size());
}

int main() {
    std::vector<int> a = {10, 9, 2, 5, 3, 7, 101, 18};
    std::cout << lis_length(a) << "\n"; // 4
    std::vector<int> b = {7, 7, 7};
    std::cout << lis_length(b) << "\n"; // 1 (strictly increasing)
    return 0;
