```cpp
#include <cassert>
#include <iostream>
#include <list>
#include <stdexcept>
#include <unordered_map>

template <typename K, typename V>
class LRUCache {
    size_t cap_;
    std::list<std::pair<K, V>> items_;
    std::unordered_map<K, typename std::list<std::pair<K, V>>::iterator> index_;

public:
    explicit LRUCache(size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool get(const K& key, V& out) {
        auto it = index_.find(key);
        if (it == index_.end()) return false;
        items_.splice(items_.begin(), items_, it->second);
        out = it->second->second;
        return true;
    }

    void put(const K& key, const V& value) {
        auto it = index_.find(key);
        if (it != index_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (items_.size() == cap_) {
            index_.erase(items_.back().first);
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        index_[key] = items_.begin();
    }
};

int main() {
    LRUCache<int, std::string> cache(2);
    int v;
    cache.put(1, "one");
    cache.put(2, "two");
    assert(cache.get(1, v) && v == "one"); // 1 becomes most-recent
    cache.put(3, "three");                   // evicts 2
    assert(!cache.get(2, v));
    assert(cache.get(3, v) && v == "three");
    std::cout << "ok\n";
}
```
`std::list::splice` moves nodes without invalidating iterators, so both operations stay O(1).

```rust
use std::collections::HashMap;
use std::fmt;

#[derive(Debug, PartialEq)]
pub enum ParseError {
    MissingEquals(String),
    EmptyKey(usize),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::MissingEquals(l) => write!(f, "line has no '=': {l}"),
            ParseError::EmptyKey(n) => write!(f, "line {n} has an empty key"),
        }
    }
}

pub fn parse(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    for (idx, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line
            .split_once('=')
            .ok_or_else(|| ParseError::MissingEquals(raw.to_string()))?;
        let key = key.trim();
        if key.is_empty() {
            return Err(ParseError::EmptyKey(idx + 1));
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let text = "# config\nhost = localhost\n\nport=8080\n";
    let cfg = parse(text).unwrap();
    assert_eq!(cfg.get("host").map(String::as_str), Some("localhost"));
    assert_eq!(cfg.get("port").map(String::as_str), Some("8080"));
    assert_eq!(cfg.len(), 2);

    let bad = parse("novalue\n");
    assert!(matches!(bad, Err(ParseError::MissingEquals(_))));
    println!("ok");
}
```
`split_once` keeps values containing `=` intact after the first separator.

