        errno = 0;
        char *end = NULL;
        long value = strtol(token, &end, 10);
        if (errno != 0 || end == token || *end != '\0' ||
            value < INT_MIN || value > INT_MAX) {
            fprintf(stderr, "warning: skipping invalid token '%s'\n", token);
            continue;
        }
        int v = (int)value;
        sum += v;
        if (count == 0 || v > max) max = v;
        count++;
    }

    if (count == 0) {
        puts("no integers provided");
        return 0;
    }
    printf("count=%d sum=%lld max=%d\n", count, sum, max);
    return 0;
}
