class File {
    std::FILE* fp_ = nullptr;

public:
    File(const std::string& path, const char* mode) {
        fp_ = std::fopen(path.c_str(), mode);
        if (!fp_) {
            throw std::runtime_error("open '" + path + "' failed: " + std::strerror(errno));
        }
    }

    ~File() { if (fp_) std::fclose(fp_); }

    File(const File&) = delete;
    File& operator=(const File&) = delete;

    File(File&& other) noexcept : fp_(other.fp_) { other.fp_ = nullptr; }

    File& operator=(File&& other) noexcept {
        if (this != &other) {
            if (fp_) std::fclose(fp_);
            fp_ = other.fp_;
            other.fp_ = nullptr;
        }
        return *this;
    }

    std::size_t write(const void* data, std::size_t n) {
        return std::fwrite(data, 1, n, fp_);
    }

    bool isValid() const { return fp_ != nullptr; }
};

int main() {
    File f("raii_demo.bin", "wb");
    const char msg[] = "hello\n";
    f.write(msg, sizeof msg - 1);

    File moved(std::move(f));
    if (moved.isValid() && !f.isValid()) std::cout << "moved ok\n";

    try {
        File bad("/no/such/dir/x", "rb");
    } catch (const std::exception& e) {
        std::cout << "caught: " << e.what() << "\n";
    }
}
