Destructor closes the handle; move transfers ownership and nulls the source so double-close is impossible; the constructor surfaces `strerror(errno)` for a readable cause.

```python
import threading
import time
from collections import deque
from typing import Generic, List, Optional, TypeVar

T = TypeVar("T")


class BoundedQueue(Generic[T]):
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._items: deque = deque()
        self._cap = capacity
        self._cv = threading.Condition()
        self._closed = False

    def put(self, item: T, timeout: Optional[float] = None) -> bool:
        deadline = None if timeout is None else time.monotonic() + timeout
        with self._cv:
            while len(self._items) >= self._cap and not self._closed:
                if deadline is None:
                    self._cv.wait()
                else:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0 or not self._cv.wait(remaining):
                        return False
            if self._closed:
                return False
            self._items.append(item)
            self._cv.notify_all()
            return True

    def get(self, timeout: Optional[float] = None) -> Optional[T]:
        deadline = None if timeout is None else time.monotonic() + timeout
        with self._cv:
            while not self._items and not self._closed:
                if deadline is None:
                    self._cv.wait()
                else:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0 or not self._cv.wait(remaining):
                        return None
            if not self._items:
                return None
            item = self._items.popleft()
            self._cv.notify_all()
            return item

    def close(self) -> None:
        with self._cv:
            self._closed = True
            self._cv.notify_all()

    def __len__(self) -> int:
        with self._cv:
            return len(self._items)


if __name__ == "__main__":
    q: BoundedQueue[int] = BoundedQueue(2)
    results: List[int] = []

    def producer() -> None:
        for i in range(5):
            assert q.put(i, timeout=1.0)
        q.close()

    def consumer() -> None:
        while True:
            v = q.get(timeout=1.0)
            if v is None:
                break
            results.append(v)

    threads = [threading.Thread(target=producer), threading.Thread(target=consumer)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    assert results == [0, 1, 2, 3, 4]
    empty: BoundedQueue[int] = BoundedQueue(1)
    assert empty.get(timeout=0.01) is None
    print("ok")
```
A single `Condition` guards both ends; `notify_all` avoids missed wakeups when both producers and consumers wait on the same lock, and the loop re-checks the predicate to handle spurious wakeups.

