// Lang: C++17
#include <algorithm>
#include <iostream>
#include <vector>

// In-place merge of a[0..n) and b[0..m) into a, using a's reserved tail.
void merge_into(std::vector<int>& a, std::size_t n,
                const std::vector<int>& b, std::size_t m) {
    std::size_t i = m;      // scratch already stored at the back of a
    std::size_t j = 0;
    std::size_t k = 0;

    // Work backwards from the last slot that will be occupied.
    std::size_t end = n + m - 1;
    while (n > 0 && j < m) {
        if (a[n - 1] > b[j]) {
            a[end--] = a[n - 1];
            --n;
        } else {
            a[end--] = b[j++];
        }
    }
    while (j < m) {
        a[end--] = b[j++];
    }
    (void)i;
    (void)k;
}

static void print(const std::vector<int>& v) {
    for (std::size_t i = 0; i < v.size(); ++i) {
        std::cout << v[i] << (i + 1 == v.size() ? '\n' : ' ');
    }
}

int main() {
    // a has room reserved at the back for b.
    std::vector<int> a{1, 3, 5, 7, 0, 0, 0, 0};
    std::vector<int> b{2, 4, 6, 8};
    merge_into(a, 4, b, b.size());
    print(a);            // 1 2 3 4 5 6 7 8

    std::vector<int> c{0, 0, 0};
    std::vector<int> d{};
    merge_into(c, 0, d, d.size());
    print(c);            // 0 0 0

    return 0;
}
```

Compile with `g++ -std=c++17 -O2 -Wall merge.cpp -o merge`. The merge walks both ranges from the back into the reserved tail, so it needs no extra buffer. Empty `b` leaves `a` untouched; the buffer keeps its reserved size, with the sorted data in the first `n+m` slots.

