#include <cstdint>
#include <iostream>
#include <limits>
#include <stdexcept>

// Returns base^exp, or throws std::overflow_error on int64 overflow.
std::int64_t ipow(std::int64_t base, unsigned exp) {
    std::int64_t result = 1;
    while (exp > 0) {
        if (exp & 1u) {
            if (result != 0 && base != 0) {
                if (result > 0 && base > 0 &&
                    result > std::numeric_limits<std::int64_t>::max() / base)
                    throw std::overflow_error("overflow");
                if (result > 0 && base < 0 &&
                    base < std::numeric_limits<std::int64_t>::min() / result)
                    throw std::overflow_error("overflow");
            }
            result *= base;
        }
        exp >>= 1u;
        if (exp > 0) {
            if (base > 0 && base > std::numeric_limits<std::int64_t>::max() / base)
                throw std::overflow_error("overflow");
            base *= base;
        }
    }
    return result;
}

int main() {
    std::cout << ipow(2, 10) << '\n';   // 1024
    std::cout << ipow(3, 0) << '\n';    // 1
    std::cout << ipow(-2, 3) << '\n';   // -8
    std::cout << ipow(0, 5) << '\n';    // 0
    std::cout << ipow(10, 18) << '\n';  // 1000000000000000000
    try {
        ipow(10, 19);
    } catch (const std::overflow_error& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
```

