```rust
// Lang: Rust
pub fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();

    // Work along the shorter string for O(min) memory.
    let (short, long) = if a.len() <= b.len() { (&a, &b) } else { (&b, &a) };

    let mut prev: Vec<usize> = (0..=short.len()).collect();
    let mut curr: Vec<usize> = vec![0; short.len() + 1];

    for i in 1..=long.len() {
        curr[0] = i;
        for j in 1..=short.len() {
            let cost = if long[i - 1] == short[j - 1] { 0 } else { 1 };
            curr[j] = (prev[j] + 1)
                .min(curr[j - 1] + 1)
                .min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut curr);
    }
    prev[short.len()]
}

#[cfg(test)]
mod tests {
    use super::levenshtein;

    #[test]
    fn basics() {
        assert_eq!(levenshtein("kitten", "sitting"), 3);
        assert_eq!(levenshtein("", "abc"), 3);
        assert_eq!(levenshtein("abc", ""), 3);
        assert_eq!(levenshtein("abc", "abc"), 0);
    }

    #[test]
    fn unicode_uses_chars_not_bytes() {
        assert_eq!(levenshtein("ca", "café"), 2);
        assert_eq!(levenshtein("日本", "日本語"), 1);
    }
}
```

Run with `cargo test`. The two-row dynamic program needs only `O(min(n,m))` space; converting to `char` first makes multi-byte boundaries correct, so `café` counts as four characters, not five bytes. The Hungarian algorithm behind this is the standard Wagner–Fischer formulation.

```python
# Lang: Python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict[int, int] = OrderedDict()

    def get(self, key: int) -> int:
        if key not in self._data:
            return -1
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: int, value: int) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least recently used

    def snapshot(self) -> list[tuple[int, int]]:
        return list(self._data.items())


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, 1)
    c.put(2, 2)
    print(c.get(1))          # 1  -> 1 becomes most recent
    c.put(3, 3)              # evicts 2
    print(c.get(2))          # -1
    print(c.get(3))          # 3
    c.put(4, 4)              # evicts 1
    print(c.get(1))          # -1
    print(c.snapshot())      # [(3, 3), (4, 4)]
```

Both `get` and `put` are O(1) amortized on the `OrderedDict`. A non-positive capacity raises immediately rather than silently misbehaving; a missing `get` returns `-1`, matching the common LeetCode contract.

