bool isBalanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                st.push(c);
                break;
            case ')':
                if (st.empty() || st.top() != '(') return false;
                st.pop();
                break;
            case ']':
                if (st.empty() || st.top() != '[') return false;
                st.pop();
                break;
            case '}':
                if (st.empty() || st.top() != '{') return false;
                st.pop();
                break;
            default:
                return false;  // reject unknown characters
        }
    }
    return st.empty();
}

int main() {
    const char* tests[] = {"()[]{{}}", "([)]", "", "(()", "}{"};
    for (const char* t : tests) {
        std::cout << '\'' << t << "' -> " << (isBalanced(t) ? "true" : "false") << '\n';
    }
}
