fn gcd(mut a: u64, mut b: u64) -> u64 {
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}

fn gcd_all(nums: &[u64]) -> Option<u64> {
    if nums.is_empty() {
        return None;
    }
    let mut acc = nums[0];
    for &n in &nums[1..] {
        acc = gcd(acc, n);
        if acc == 1 {
            break; // can't get smaller than 1
        }
    }
    Some(acc)
}

