int main() {
    std::vector<int> data = {3, 1, 3, 2, 1, 5, 2};
    std::vector<int> result = dedup(data);
    for (size_t i = 0; i < result.size(); ++i) {
        std::cout << result[i] << (i + 1 == result.size() ? '\n' : ' ');
    }
    return 0;
}
```

`insert` returns a pair whose `second` is false when the value was already present, so only the first occurrence is kept. The original vector is untouched and the helper returns a new vector, which keeps it easy to test.

```cpp
#include <iostream>
#include <cstdint>
#include <optional>

static const uint64_t U64_MAX = ~0ULL;

static bool mul_over(uint64_t a, uint64_t b) {
    return a != 0 && b > U64_MAX / a;
}

std::optional<uint64_t> fib(uint64_t n) {
    uint64_t a = 0, b = 1;
    for (uint64_t bit = 1ULL << 63; bit; bit >>= 1) {
        uint64_t c = a * ((b << 1) - a);
        uint64_t d = a * a + b * b;
        if (mul_over(a, (b << 1) - a) || mul_over(a, a) || mul_over(b, b)) return std::nullopt;
        if (n & bit) { a = d; b = c + d; } else { a = c; b = d; }
    }
    return a;
}

int main() {
    for (uint64_t n : {0ULL, 1ULL, 10ULL, 50ULL, 93ULL}) {
        auto r = fib(n);
        if (r) std::cout << n << " -> " << *r << '\n';
        else std::cout << n << " -> overflow\n";
    }
    return 0;
}
```

Fast doubling halves the work per bit instead of iterating n times. The overflow guards check both products before they are used, and the function returns `std::nullopt` rather than wrapping when the result would exceed 64 bits.

