```python
def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


if __name__ == "__main__":
    a = [1, 3, 5, 7, 9, 11]
    for t in [1, 11, 6, 0, 12]:
        print(t, binary_search(a, t))
```

The loop keeps `lo` and `hi` inclusive and exits when the window is empty. `(lo + hi) // 2` is safe in Python because integers are arbitrary precision, so there is no overflow concern. Targets not present return -1, including values outside the range.

```c
#include <stdio.h>
#include <string.h>

static int is_open(char c) { return c == '(' || c == '[' || c == '{'; }

static char matching(char c) {
    if (c == ')') return '(';
    if (c == ']') return '[';
    return '{';
}

int balanced(const char *s) {
    char stack[256];
    int top = 0;
    for (size_t i = 0; s[i] != '\0'; ++i) {
        char c = s[i];
        if (is_open(c)) {
            if (top >= 256) return 0;
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0 || stack[--top] != matching(c)) return 0;
        }
    }
    return top == 0;
}

int main(void) {
    const char *tests[] = {"a(b[c]{d})e", "([)]", "(((", "no brackets", "}{"};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); ++i)
        printf("%s -> %s\n", tests[i], balanced(tests[i]) ? "ok" : "bad");
    return 0;
}
```

A fixed array acts as the stack; each closer must match the most recent opener, which catches cross-nesting like `([)]`. Non-bracket characters are ignored, an empty string is balanced, and the depth guard returns 0 instead of overflowing the 256-slot buffer.

