#[derive(Debug, PartialEq)]
struct Node {
    value: i32,
    next: Option<Box<Node>>,
}

fn reverse(mut head: Option<Box<Node>>) -> Option<Box<Node>> {
    let mut prev: Option<Box<Node>> = None;
    while let Some(mut node) = head {
        head = node.next.take();
        node.next = prev;
        prev = Some(node);
    }
    prev
}

fn from_slice(values: &[i32]) -> Option<Box<Node>> {
    let mut head: Option<Box<Node>> = None;
    for &v in values.iter().rev() {
        head = Some(Box::new(Node { value: v, next: head }));
    }
    head
}

fn values(head: &Option<Box<Node>>) -> Vec<i32> {
    let mut out = Vec::new();
    let mut cur = head;
    while let Some(n) = cur {
        out.push(n.value);
        cur = &n.next;
    }
    out
}

fn main() {
    let list = from_slice(&[1, 2, 3, 4]);
    let rev = reverse(list);
    assert_eq!(values(&rev), vec![4, 3, 2, 1]);
