#include <cstdint>
#include <cstdlib>
#include <iostream>

constexpr std::int64_t MOD = 1000000007;

struct Mat { std::int64_t a, b, c, d; };

Mat mul(const Mat &x, const Mat &y) {
    return {(x.a * y.a + x.b * y.c) % MOD,
            (x.a * y.b + x.b * y.d) % MOD,
            (x.c * y.a + x.d * y.c) % MOD,
            (x.c * y.b + x.d * y.d) % MOD};
}

Mat power(Mat base, std::int64_t e) {
    Mat result{1, 0, 0, 1};
    while (e > 0) {
        if (e & 1) result = mul(result, base);
        base = mul(base, base);
        e >>= 1;
    }
    return result;
}

std::int64_t fib(std::int64_t n) {
    if (n < 0) return -1;
    if (n == 0) return 0;
    Mat m = power({1, 1, 1, 0}, n - 1);
    return m.a;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        std::cerr << "usage: fib <n>\n";
        return 2;
    }
    long long n = std::strtoll(argv[1], nullptr, 10);
    if (n < 0) {
        std::cerr << "n must be non-negative\n";
        return 2;
    }
    std::cout << fib(n) << "\n";
    return 0;
