// Reverse word order. "  foo bar  " -> "bar foo  " (leading spaces become trailing).
std::string reverse_words(const std::string& s) {
    std::vector<std::string> words;
    std::string cur;
    for (char c : s) {
        if (c == ' ' || c == '\t') {
            if (!cur.empty()) { words.push_back(cur); cur.clear(); }
        } else {
            cur.push_back(c);
        }
    }
    if (!cur.empty()) words.push_back(cur);

    std::string out;
    for (auto it = words.rbegin(); it != words.rend(); ++it) {
        if (!out.empty()) out.push_back(' ');
        out += *it;
    }
    // Preserve trailing spaces from the original.
    size_t trail = s.find_last_not_of(" \t");
    if (trail == std::string::npos) return s;
    out.append(s.size() - trail - 1, ' ');
    return out;
}

int main() {
    struct Case { std::string in, want; };
    Case cases[] = {
        {"", ""},
        {"   ", "   "},
        {"hello world", "world hello"},
        {"one   two", "two one   "},
        {"  a b  ", "b a  "},
    };
    for (const auto& c : cases) {
        auto got = reverse_words(c.in);
        if (got != c.want) {
            std::cerr << "fail: [" << c.in << "] -> [" << got
                      << "] want [" << c.want << "]\n";
            return 1;
        }
    }
    std::cout << "ok\n";
}
```
