#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

bool has_cycle(const Node* head) {
    const Node* slow = head;
    const Node* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

int main() {
    // Acyclic: 1 -> 2 -> 3
    Node a(1), b(2), c(3);
    a.next = &b; b.next = &c;
    if (has_cycle(&a)) { std::cerr << "expected no cycle\n"; return 1; }

    // Cyclic: 1 -> 2 -> 3 -> back to 2
    c.next = &b;
    if (!has_cycle(&a)) { std::cerr << "expected cycle\n"; return 1; }

    if (has_cycle(nullptr)) { std::cerr << "null should be acyclic\n"; return 1; }

    std::cout << "ok\n";
}
```
Stack-allocated nodes keep the example dependency-free. `slow` moves one step, `fast` two; if they meet, a cycle exists, and the null checks make the empty-list case safe.

