```c
#include <stdio.h>
#include <string.h>

typedef struct { int ok; char text[35]; } Result;

static Result to_base(long value, int base) {
    static const char digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";
    Result r = {0, {0}};
    if (base < 2 || base > 36) return r;

    int neg = value < 0;
    unsigned long v = neg ? (unsigned long)(-(value + 1)) + 1UL : (unsigned long)value;

    char buf[35];
    int i = 0;
    do {
        buf[i++] = digits[v % (unsigned long)base];
        v /= (unsigned long)base;
    } while (v > 0 && i < (int)sizeof(buf));

    int pos = 0;
    if (neg) r.text[pos++] = '-';
    while (i > 0) r.text[pos++] = buf[--i];
    r.text[pos] = '\0';
    r.ok = 1;
    return r;
}

int main(void) {
    struct { long value; int base; const char* want; } cases[] = {
        {255, 16, "ff"},
        {255, 2, "11111111"},
        {-10, 2, "-1010"},
        {0, 10, "0"},
        {35, 36, "z"},
        {1, 1, NULL},
    };
    for (size_t k = 0; k < sizeof(cases)/sizeof(cases[0]); ++k) {
        Result r = to_base(cases[k].value, cases[k].base);
        if (cases[k].want == NULL) {
            if (r.ok) { fprintf(stderr, "base %d should fail\n", cases[k].base); return 1; }
            continue;
        }
        if (!r.ok || strcmp(r.text, cases[k].want)) {
            fprintf(stderr, "%ld base %d -> %s, want %s\n",
                    cases[k].value, cases[k].base, r.text, cases[k].want);
            return 1;
        }
    }
    printf("ok\n");
    return 0;
}
