Sliding window with a dict of last positions. Empty input returns `""`, and it handles unicode since Python iterates by code point. Expected output includes `"abc"`, `"b"`, `"wke"`, `""`, `"a"`.

```cpp
#include <condition_variable>
#include <mutex>
#include <queue>
#include <cstdio>
#include <thread>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t cap) : cap_(cap) {}

    void push(int v) {
        std::unique_lock<std::mutex> lock(m_);
        not_full_.wait(lock, [&] { return q_.size() < cap_; });
        q_.push(v);
        not_empty_.notify_one();
    }

    bool pop(int& out) {
        std::unique_lock<std::mutex> lock(m_);
        not_empty_.wait(lock, [&] { return !q_.empty() || done_; });
        if (q_.empty()) return false;  // done_ and drained
        out = q_.front();
        q_.pop();
        not_full_.notify_one();
        return true;
    }

    void close() {
        std::lock_guard<std::mutex> lock(m_);
        done_ = true;
        not_empty_.notify_all();
    }

private:
    std::queue<int> q_;
    std::size_t cap_;
    bool done_ = false;
    std::mutex m_;
    std::condition_variable not_empty_, not_full_;
};

int main() {
    BoundedQueue q(4);
    std::thread producer([&] {
        for (int i = 0; i < 10; ++i) q.push(i);
        q.close();
    });
    int val, total = 0;
    while (q.pop(val)) { std::printf("%d\n", val); total += val; }
    producer.join();
    std::printf("total=%d\n", total);
}
```

`wait` with a predicate guards against spurious wakeups. `close()` wakes consumers so a drained queue lets `pop` return `false` instead of blocking forever. Compile with `-std=c++17 -pthread`.

```cpp
#include <string>
#include <cstdint>

static bool parse_octet(const std::string& s, std::size_t start, std::size_t len, int& out) {
    if (len == 0 || len > 3) return false;
    if (len > 1 && s[start] == '0') return false;  // no leading zeros
    int v = 0;
    for (std::size_t i = 0; i < len; ++i) {
        char c = s[start + i];
        if (c < '0' || c > '9') return false;
        v = v * 10 + (c - '0');
    }
    if (v > 255) return false;
    out = v;
    return true;
}

bool is_valid_ipv4(const std::string& s) {
    int octet = 0;
    int count = 0;
    std::size_t i = 0;
    while (i <= s.size()) {
        std::size_t dot = s.find('.', i);
        std::size_t len = (dot == std::string::npos ? s.size() : dot) - i;
        if (!parse_octet(s, i, len, octet)) return false;
        ++count;
        if (dot == std::string::npos) break;
        i = dot + 1;
        if (i == s.size()) return false;  // trailing dot
    }
    return count == 4;
}
```

Rejects leading zeros (`"01.2.3.4"`), values over 255, missing/trailing dots, and the empty string. `count == 4` enforces exactly four octets. No allocations beyond the input.

```rust
use std::collections::{HashMap, VecDeque};
use std::hash::Hash;

pub struct LruCache<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>, // front = most recently used
}

impl<K: Eq + Hash + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        if self.map.contains_key(key) {
            self.touch(key);
            self.map.get(key)
        } else {
            None
        }
    }

    pub fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            self.touch(&key);
            self.map.insert(key, value);
            return;
        }
        if self.map.len() == self.cap {
            if let Some(evicted) = self.order.pop_back() {
                self.map.remove(&evicted);
            }
        }
        self.order.push_front(key.clone());
        self.map.insert(key, value);
    }

    fn touch(&mut self, key: &K) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            let k = self.order.remove(pos).unwrap();
            self.order.push_front(k);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::LruCache;

    #[test]
    fn evicts_least_recently_used() {
        let mut c = LruCache::new(2);
        c.put("a", 1);
        c.put("b", 2);
        assert_eq!(c.get(&"a"), Some(&1)); // a becomes MRU
        c.put("c", 3);                    // should evict b
        assert_eq!(c.get(&"b"), None);
        assert_eq!(c.get(&"a"), Some(&1));
        assert_eq!(c.get(&"c"), Some(&3));
    }
}
```

The `order` deque mirrors insertion/access order while the `HashMap` holds values. `touch` moves a hit to the front in O(n), fine for small caches; the test verifies `b` is evicted after `a` is re-read.

