```python
from typing import List

def binary_search(a: List[int], target: int) -> int:
    """Return any index of target in sorted a, or -1 if absent."""
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def first_index(a: List[int], target: int) -> int:
    """Return the leftmost index of target, or -1."""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo if lo < len(a) and a[lo] == target else -1

if __name__ == "__main__":
    for arr, t in [([1, 3, 5, 7, 9], 5), ([1, 3, 5, 7, 9], 4),
                   ([2, 2, 2, 2], 2), ([], 1), ([0], 0)]:
        print(arr, t, binary_search(arr, t), first_index(arr, t))
```

`mid = lo + (hi - lo) // 2` avoids overflow in languages with fixed ints. `binary_search` returns any match; `first_index` does a lower-bound search so duplicates always resolve to the leftmost occurrence — for `[2,2,2,2]` that's index 0.

```python
import functools
import random
import time

def retry(tries: int = 3, base: float = 0.1, cap: float = 5.0,
          exceptions=(Exception,)):
    """Retry a function with exponential backoff plus full jitter."""
    if tries < 1:
        raise ValueError("tries must be >= 1")

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for attempt in range(tries):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    if attempt == tries - 1:
                        raise
                    delay = min(cap, base * (2 ** attempt))
                    time.sleep(random.uniform(0, delay))  # full jitter
            return None  # unreachable
        return wrapper
    return decorator

if __name__ == "__main__":
    calls = {"n": 0}

    @retry(tries=4, base=0.01, exceptions=(ValueError,))
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return f"ok after {calls['n']} calls"

    print(flaky())
```

Only listed `exceptions` are caught; anything else propagates immediately. Full jitter (`uniform(0, delay)`) spreads retries so clients don't synchronize. The final attempt re-raises rather than sleeping, so the caller sees the original error.

