#include <cassert>
#include <iostream>
#include <string>
#include <vector>

// Returns the byte length of the UTF-8 sequence starting with lead.
static size_t utf8_len(unsigned char lead) {
    if ((lead & 0x80) == 0x00) return 1;
    if ((lead & 0xE0) == 0xC0) return 2;
    if ((lead & 0xF0) == 0xE0) return 3;
    if ((lead & 0xF8) == 0xF0) return 4;
    return 1; // invalid lead byte: treat as single byte
}

std::string reverse_utf8(const std::string& s) {
    std::vector<std::string> cps;
    size_t i = 0;
    while (i < s.size()) {
        size_t len = utf8_len(static_cast<unsigned char>(s[i]));
        if (i + len > s.size()) len = 1; // truncated tail
        cps.emplace_back(s.substr(i, len));
        i += len;
    }
    std::string out;
    for (auto it = cps.rbegin(); it != cps.rend(); ++it) out += *it;
    return out;
}

int main() {
    assert(reverse_utf8("abc") == "cba");
    assert(reverse_utf8("") == "");
    assert(reverse_utf8("a\xC3\xA9b") == "b\xC3\xA9a"); // a, e-acute, b
    assert(reverse_utf8("\xE4\xBD\xA0\xE5\xA5\xBD") == "\xE5\xA5\xBD\xE4\xBD\xA0");
    std::cout << "all tests passed\n";
    return 0;
}
