use std::sync::mpsc::{channel, Sender};
use std::sync::{Arc, Mutex};
use std::thread;

pub struct Pool {
    workers: Vec<thread::JoinHandle<()>>,
    tx: Option<Sender<u64>>,
}

impl Pool {
    pub fn new(size: usize, total: Arc<Mutex<u64>>) -> Self {
        let (tx, rx) = channel::<u64>();
        let rx = Arc::new(Mutex::new(rx));
        let mut workers = Vec::new();
        for _ in 0..size {
            let rx = Arc::clone(&rx);
            let total = Arc::clone(&total);
            workers.push(thread::spawn(move || {
                loop {
                    let job = { rx.lock().unwrap().recv() };
                    match job {
                        Ok(n) => *total.lock().unwrap() += n,
                        Err(_) => break,
                    }
                }
            }));
        }
        Pool { workers, tx: Some(tx) }
    }

    pub fn submit(&self, n: u64) {
        if let Some(tx) = &self.tx { tx.send(n).unwrap(); }
    }

    pub fn shutdown(mut self) {
        drop(self.tx.take());
        for w in self.workers.drain(..) { let _ = w.join(); }
    }
}

fn main() {
    let total = Arc::new(Mutex::new(0u64));
    let pool = Pool::new(4, Arc::clone(&total));
    for i in 0..100 { pool.submit(i); }
    pool.shutdown();
    println!("total = {}", *total.lock().unwrap()); // 4950
}
