/* Copy at most cap-1 chars, always NUL-terminate. Returns chars copied. */
size_t safe_copy(char *dst, size_t cap, const char *src) {
    if (cap == 0) {
        return 0; /* nothing writable; cannot terminate */
    }
    size_t i = 0;
    while (i + 1 < cap && src[i] != '\0') {
        dst[i] = src[i];
        ++i;
    }
    dst[i] = '\0';
    return i;
}

