```rust
use std::collections::HashMap;

struct Node {
    key: i32,
    value: i32,
    prev: Option<usize>,
    next: Option<usize>,
}

pub struct LruCache {
    capacity: usize,
    map: HashMap<i32, usize>,
    nodes: Vec<Node>,
    head: Option<usize>,
    tail: Option<usize>,
}

impl LruCache {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        LruCache { capacity, map: HashMap::new(), nodes: Vec::new(), head: None, tail: None }
    }

    pub fn get(&mut self, key: i32) -> Option<i32> {
        let idx = *self.map.get(&key)?;
        self.move_to_front(idx);
        Some(self.nodes[idx].value)
    }

    pub fn put(&mut self, key: i32, value: i32) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].value = value;
            self.move_to_front(idx);
            return;
        }
        if self.map.len() == self.capacity {
            if let Some(old_tail) = self.tail {
                let old_key = self.nodes[old_tail].key;
                self.detach(self.tail);
                self.map.remove(&old_key);
            }
        }
        let idx = self.nodes.len();
        self.nodes.push(Node { key, value, prev: None, next: None });
        self.map.insert(key, idx);
        self.attach_front(idx);
    }

    fn detach(&mut self, idx: Option<usize>) {
        if let Some(i) = idx {
            let (prev, next) = (self.nodes[i].prev, self.nodes[i].next);
            if let Some(p) = prev { self.nodes[p].next = next; } else { self.head = next; }
            if let Some(n) = next { self.nodes[n].prev = prev; } else { self.tail = prev; }
            self.nodes[i].prev = None;
            self.nodes[i].next = None;
        }
    }

    fn attach_front(&mut self, idx: usize) {
        self.nodes[idx].next = self.head;
        self.nodes[idx].prev = None;
        if let Some(h) = self.head { self.nodes[h].prev = Some(idx); }
        self.head = Some(idx);
        if self.tail.is_none() { self.tail = Some(idx); }
    }

    fn move_to_front(&mut self, idx: usize) {
        if self.head == Some(idx) { return; }
        self.detach(Some(idx));
        self.attach_front(idx);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn evicts_least_recently_used() {
        let mut cache = LruCache::new(2);
        cache.put(1, 1);
        cache.put(2, 2);
        assert_eq!(cache.get(1), Some(1));
        cache.put(3, 3);
        assert_eq!(cache.get(2), None);
        assert_eq!(cache.get(1), Some(1));
        assert_eq!(cache.get(3), Some(3));
    }
}
