#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (size_ == N) {
            return false;
        }
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        T value = std::move(data_[head_]);
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};
```

`pop` returns `std::optional`, so an empty buffer reports failure honestly instead of throwing or returning a default-constructed value. `N` must be nonzero — a zero-capacity buffer is a compile-time misuse here.

