fn median_of_csv(input: &str) -> Option<f64> {
    let mut nums: Vec<i64> = input
        .split(',')
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(|s| s.parse::<i64>())
        .collect::<Result<Vec<_>, _>>()
        .ok()?;

    if nums.is_empty() {
        return None;
    }

    nums.sort_unstable();
    let mid = nums.len() / 2;
    if nums.len() % 2 == 1 {
        Some(nums[mid] as f64)
    } else {
        Some((nums[mid - 1] as f64 + nums[mid] as f64) / 2.0)
    }
