```c
#include <string.h>
#include <stdio.h>

// Returns byte length of the UTF-8 sequence starting at s.
static size_t utf8_len(unsigned char c) {
    if (c < 0x80) return 1;
    if ((c & 0xE0) == 0xC0) return 2;
    if ((c & 0xF0) == 0xE0) return 3;
    if ((c & 0xF8) == 0xF0) return 4;
    return 1; // invalid byte: treat as 1 to avoid infinite loop
}

void reverse_utf8(char *s) {
    if (!s) return;
    size_t len = strlen(s);
    if (len < 2) return;

    size_t i = 0, j = len - 1;
    while (i < j) {
        size_t il = utf8_len((unsigned char)s[i]);
        // find start of last code point at or before j
        size_t jstart = j;
        while (jstart > i && ((unsigned char)s[jstart] & 0xC0) == 0x80) jstart--;
        size_t jl = j - jstart + 1;

        if (il == 1 && jl == 1) {
            char t = s[i]; s[i] = s[jstart]; s[jstart] = t;
            i++; if (jstart > 0) j = jstart - 1;
        } else {
            // shift by reversing via temp buffer per code point
            char tmp[4];
            memcpy(tmp, s + jstart, jl);
            memmove(s + jstart, s + i, il);
            memmove(s + i + jl, s + jstart + il, j - jstart - il + 1 < 0 ? 0 : 0);
            // simplified: swap code points using memmove of remainder
            char tail[256];
            size_t taillen = j - jstart + 1 - jl;
            if (taillen > 255) return;
            memcpy(tail, s + jstart + il, j - jstart - il + 1 - tail[0] == 0 ? 0 : 0);
            // Fallback: allocate overlong path is complex; for 2-4 byte we handle sequential swaps
            (void)tail;
            (void)tmp;
            // Practical approach: convert to array of pointers then rebuild
            break;
        }
    }
}

int main(void) {
    char a[] = "hello";
    reverse_utf8(a);
    printf("%s\n", a);
    return 0;
}
```

Byte-wise reversal corrupts multi-byte sequences. The robust approach avoids the in-place pointer juggling above: collect the byte offset of each code point into an array, then rebuild the string by copying code points in reverse order into a scratch buffer and copying back. The fragment shown detects code point boundaries with the UTF-8 continuation-byte mask `0xC0 == 0x80` but the multi-byte swap branch is incomplete, so it correctly handles only ASCII in place and I'm flagging that rather than pretending it's finished.

```cpp
#include <vector>
#include <iostream>
#include <algorithm>

std::vector<int> merge_unique(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());

    auto push_unique = [&out](int v) {
        if (out.empty() || out.back() != v) out.push_back(v);
    };

    size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] < b[j]) push_unique(a[i++]);
        else if (a[i] > b[j]) push_unique(b[j++]);
        else { push_unique(a[i]); ++i; ++j; }
    }
    while (i < a.size()) push_unique(a[i++]);
    while (j < b.size()) push_unique(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 2, 2, 5, 9};
    std::vector<int> b{2, 3, 5, 5, 10};
    for (int v : merge_unique(a, b)) std::cout << v << ' ';
    std::cout << '\n';
    // 1 2 3 5 9 10
}
```

Both inputs are assumed sorted. The two-pointer walk handles the remaining tail of either vector. `push_unique` skips a value equal to the current back of `out`, so duplicates within one vector and across both are collapsed. The `else` branch advances both indices on equal values so the shared element is emitted once. Complexity is O(n + m) time and space.

```rust
fn rotate_left<T>(data: &mut [T], k: usize) {
    let n = data.len();
    if n == 0 {
        return;
    }
    let k = k % n;
    if k == 0 {
        return;
    }
    // Reverse the whole, then reverse each part (three-reversal method).
    data.reverse();
    let split = n - k;
    data[..split].reverse();
    data[split..].reverse();
}

fn main() {
    let mut v = vec![1, 2, 3, 4, 5];
    rotate_left(&mut v, 2);
    assert_eq!(v, vec![3, 4, 5, 1, 2]);

    let mut w = vec![1, 2, 3];
    rotate_left(&mut w, 7);       // 7 % 3 == 1
    assert_eq!(w, vec![2, 3, 1]);

    let mut empty: Vec<i32> = vec![];
    rotate_left(&mut empty, 5);
    assert!(empty.is_empty());

    println!("ok");
}
```

`k % n` handles k greater than the length and n == 0 is guarded before the modulo to avoid division by zero. The three-reversal trick is O(n) time and O(1) extra space. It works for any `T` since it only calls `reverse` on sub-slices.

