        if (octets == 4) return 0;
        if (!isdigit((unsigned char)*p)) return 0;

        int val = 0, digits = 0;
        while (isdigit((unsigned char)*p)) {
            val = val * 10 + (*p - '0');
            digits++;
            p++;
        }
        if (digits > 3 || val > 255) return 0;
        if (digits > 1 && *(p - digits) == '0') return 0; // no leading zeros
        octets++;

        if (*p == '.') {
            if (octets == 4) return 0; // trailing dot
            p++;
            if (*p == '\0') return 0;  // dot with no following octet
        } else if (*p != '\0') {
            return 0; // junk char
        }
    }
    return octets == 4;
}

int main(void) {
    const char *tests[] = {
        "192.168.0.1", "255.255.255.255", "0.0.0.0",
        "256.1.1.1", "1.2.3", "1.2.3.4.5", "01.2.3.4",
        "1.2.3.", "", "1.2.3.a"
    };
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); i++)
        printf("%-16s -> %d\n", tests[i], is_valid_ipv4(tests[i]));
    return 0;
}
```

Each octet must be 1–3 digits, its value ≤ 255, and have no leading zero unless it is a single `0`. The function counts octets and requires exactly four at the end, so `1.2.3` and `1.2.3.4.5` both fail. A trailing dot fails because the next character after it is `\0`. `isdigit` casts to `unsigned char` to avoid undefined behavior on negative `char`.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

 template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == N) return false;          // full: report overflow
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;   // empty
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool full() const { return count_ == N; }
    bool empty() const { return count_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << '\n'; // 111
    std::cout << rb.push(4) << '\n';                            // 0 (full)
    std::cout << rb.size() << '\n';                             // 3
    while (!rb.empty()) std::cout << *rb.pop() << ' ';          // 1 2 3
    std::cout << '\n';
}
```

`push` returns `false` when the buffer is full instead of silently dropping data, so the caller sees the overflow. `pop` returns `std::optional` to express empty. Head advances modulo `N`, and `count_` distinguishes full from empty without a wasted slot. The `std::array` avoids heap allocation, and elements are overwritten in place.

```cpp
#include <iostream>
#include <queue>
#include <vector>
#include <iomanip>

int main() {
    std::priority_queue<int> low;                              // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap
    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);
        if (low.size() > high.size() + 1) { high.push(low.top()); low.pop(); }
        else if (high.size() > low.size()) { low.push(high.top()); high.pop(); }
        double median = (low.size() == high.size())
            ? (low.top() + high.top()) / 2.0
            : static_cast<double>(low.top());
        std::cout << std::fixed << std::setprecision(1) << median << '\n';
    }
    return 0;
}
```

Each value is pushed to the heap that keeps the ordering, then the sizes are rebalanced so `low` is never more than one element larger than `high`. With an even count the median is the average of the two roots, otherwise it is `low.top()`. Empty input produces no output.

