#[derive(Debug, PartialEq)]
pub struct Semver {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
}

pub fn parse_semver(s: &str) -> Result<Semver, String> {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 3 {
        return Err(format!("expected 3 dot-separated parts, got {}", parts.len()));
    }
    let parse = |label: &str, part: &str| -> Result<u64, String> {
        if part.is_empty() {
            return Err(format!("empty {label} component"));
        }
        part.parse::<u64>().map_err(|_| format!("invalid {label}: {part:?}"))
    };
    Ok(Semver {
        major: parse("major", parts[0])?,
        minor: parse("minor", parts[1])?,
        patch: parse("patch", parts[2])?,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_valid() {
        assert_eq!(parse_semver("1.2.3"), Ok(Semver { major: 1, minor: 2, patch: 3 }));
        assert_eq!(parse_semver("0.0.0"), Ok(Semver { major: 0, minor: 0, patch: 0 }));
    }

    #[test]
    fn rejects_bad_input() {
        assert!(parse_semver("1.2").is_err());
        assert!(parse_semver("1.2.3.4").is_err());
        assert!(parse_semver("1..3").is_err());
        assert!(parse_semver("a.b.c").is_err());
        assert!(parse_semver("-1.2.3").is_err());
    }
}
