```python
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)

if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1        # a is refreshed
    c.put("c", 3)                 # evicts b
    assert c.get("b") is None
    assert c.get("a") == 1
    assert c.get("c") == 3
    assert len(c) == 2
    c.put("c", 30)                # update existing
    assert c.get("c") == 30
    print("ok")
```

`OrderedDict.move_to_end` moves a hit to the most-recent position, and `popitem(last=False)` removes the least-recently used entry, both O(1). Updating an existing key also refreshes its recency.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define BUCKETS 4096
#define MAX_WORD 256

typedef struct Entry {
    char *word;
    long count;
    struct Entry *next;
} Entry;

static unsigned long hash(const char *s) {
    unsigned long h = 5381;
    int c;
    while ((c = (unsigned char)*s++)) h = ((h << 5) + h) + (unsigned long)c;
    return h;
}

static Entry *find(Entry **table, const char *word) {
    for (Entry *e = table[hash(word) % BUCKETS]; e; e = e->next)
        if (strcmp(e->word, word) == 0) return e;
    return NULL;
}

static void add(Entry **table, const char *word) {
    Entry *e = find(table, word);
    if (e) { e->count++; return; }
    unsigned long b = hash(word) % BUCKETS;
    e = malloc(sizeof *e);
    if (!e) { perror("malloc"); exit(1); }
    e->word = strdup(word);
    if (!e->word) { perror("strdup"); exit(1); }
    e->count = 1;
    e->next = table[b];
    table[b] = e;
}

static int cmp(const void *a, const void *b) {
    const Entry *x = *(const Entry *const *)a, *y = *(const Entry *const *)b;
    if (x->count != y->count) return (x->count < y->count) ? 1 : -1;
    return strcmp(x->word, y->word);
}

int main(int argc, char **argv) {
    int top = (argc > 1) ? atoi(argv[1]) : 10;
    if (top < 1) top = 1;
    Entry **table = calloc(BUCKETS, sizeof *table);
    if (!table) { perror("calloc"); return 1; }

    char word[MAX_WORD];
    int ch, len = 0;
    while ((ch = getchar()) != EOF) {
        if (isalnum(ch) || ch == '\'') {
            if (len < MAX_WORD - 1) word[len++] = (char)tolower(ch);
        } else if (len > 0) {
            word[len] = '\0';
            add(table, word);
            len = 0;
        }
    }
    if (len > 0) { word[len] = '\0'; add(table, word); }

    size_t n = 0;
    for (int i = 0; i < BUCKETS; i++)
        for (Entry *e = table[i]; e; e = e->next) n++;
    Entry **all = malloc(n * sizeof *all);
    if (!all && n) { perror("malloc"); return 1; }
    size_t k = 0;
    for (int i = 0; i < BUCKETS; i++)
        for (Entry *e = table[i]; e; e = e->next) all[k++] = e;

    qsort(all, n, sizeof *all, cmp);
    for (size_t i = 0; i < n && (int)i < top; i++)
        printf("%7ld  %s\n", all[i]->count, all[i]->word);

    for (int i = 0; i < BUCKETS; i++) {
        Entry *e = table[i];
        while (e) { Entry *next = e->next; free(e->word); free(e); e = next; }
    }
    free(all);
    free(table);
    return 0;
}
```

A single `getchar` loop streams input, so line length is unbounded; words longer than 255 characters are truncated rather than overflowing the buffer. Ties sort alphabetically via `cmp`. All heap memory is freed before exit.

