```cpp
#include <iostream>
#include <vector>
#include <string>
#include <cstddef>

template <typename T>
std::vector<T> flatten(const std::vector<std::vector<T>>& nested) {
    std::size_t total = 0;
    for (const auto& row : nested) total += row.size();

    std::vector<T> out;
    out.reserve(total);
    for (const auto& row : nested) {
        out.insert(out.end(), row.begin(), row.end());
    }
    return out;
}

int main() {
    std::vector<std::vector<int>> numbers = {{1, 2}, {}, {3, 4, 5}, {6}};
    std::vector<int> flat = flatten(numbers);
    std::vector<int> expected = {1, 2, 3, 4, 5, 6};
    if (flat != expected) { std::cerr << "int flatten failed\n"; return 1; }

    std::vector<std::vector<std::string>> words = {{"a", "bb"}, {"ccc"}, {}};
    std::vector<std::string> joined = flatten(words);
    if (joined != std::vector<std::string>{"a", "bb", "ccc"}) {
        std::cerr << "string flatten failed\n";
        return 1;
    }

    std::vector<std::vector<int>> empty;
    if (!flatten(empty).empty()) { std::cerr << "empty case failed\n"; return 1; }

    std::cout << "all cases passed\n";
    return 0;
}
```

One pass sums the sizes, `reserve` allocates exactly once, and the second pass copies ranges in order. Empty inner vectors and an empty outer vector are handled without special cases.

