#include <stdio.h>
#include <string.h>

#define BUF 66

void to_binary(long value, char *out, size_t size) {
    char tmp[BUF];
    int neg = value < 0;
    unsigned long v = neg ? (unsigned long)(-value) : (unsigned long)value;
    size_t i = 0;

    if (v == 0) tmp[i++] = '0';
    while (v > 0 && i < sizeof(tmp) - 1) {
        tmp[i++] = (char)('0' + (v & 1UL));
        v >>= 1;
    }
    if (neg) tmp[i++] = '-';
    tmp[i] = '\0';

    if (i >= size) i = size - 1;
    for (size_t j = 0; j < i; ++j) out[j] = tmp[i - 1 - j];
    out[i] = '\0';
}

int main(void) {
    char buf[BUF];
    to_binary(0, buf, sizeof buf);      puts(buf);
    to_binary(13, buf, sizeof buf);     puts(buf);
    to_binary(-13, buf, sizeof buf);    puts(buf);
    return 0;
}
