class BoundedStack {
public:
    explicit BoundedStack(std::size_t cap) : cap_(cap) {
        if (cap == 0) throw std::invalid_argument("capacity must be > 0");
        data_.reserve(cap);
    }

    bool push(int value) {
        if (data_.size() >= cap_) return false;
        data_.push_back(value);
        return true;
    }

    int pop() {
        if (data_.empty()) throw std::underflow_error("stack is empty");
        int v = data_.back();
        data_.pop_back();
        return v;
    }

    std::size_t size() const noexcept { return data_.size(); }
    bool empty() const noexcept { return data_.empty(); }

private:
    std::size_t cap_;
    std::vector<int> data_;
};

int main() {
    BoundedStack s(2);
    std::cout << s.push(1) << s.push(2) << s.push(3) << '\n'; // 110
    std::cout << s.pop() << '\n';                            // 2
