```cpp
#include <cstddef>
#include <stdexcept>
#include <utility>
#include <iostream>

class IntVector {
    int *data_ = nullptr;
    std::size_t size_ = 0;
    std::size_t cap_ = 0;

    void grow(std::size_t need) {
        std::size_t nc = cap_ ? cap_ * 2 : 1;
        while (nc < need) nc *= 2;
        int *fresh = new int[nc];
        for (std::size_t i = 0; i < size_; ++i) fresh[i] = data_[i];
        delete[] data_;
        data_ = fresh;
        cap_ = nc;
    }

public:
    IntVector() = default;
    ~IntVector() { delete[] data_; }
    IntVector(const IntVector &) = delete;
    IntVector &operator=(const IntVector &) = delete;

    void push_back(int v) {
        if (size_ == cap_) grow(size_ + 1);
        data_[size_++] = v;
    }
    int &operator[](std::size_t i) {
        if (i >= size_) throw std::out_of_range("index");
        return data_[i];
    }
    std::size_t size() const { return size_; }
    std::size_t capacity() const { return cap_; }
};

int main() {
    IntVector v;
    for (int i = 0; i < 10; ++i) v.push_back(i * i);
