use std::collections::HashMap;

fn two_sum(nums: &[i64], target: i64) -> Option<(usize, usize)> {
    let mut seen: HashMap<i64, usize> = HashMap::new();
    for (i, &n) in nums.iter().enumerate() {
        let want = target - n;
        if let Some(&j) = seen.get(&want) {
            return Some((j, i));
        }
        seen.insert(n, i);
    }
    None
