```rust
struct Debouncer {
    window: u32,
    last_fired: Option<u32>,
    ticks: u32,
}

impl Debouncer {
    fn new(window: u32) -> Self {
        Debouncer { window, last_fired: None, ticks: 0 }
    }

    fn tick<F: FnMut()>(&mut self, mut fire: F) -> bool {
        let now = self.ticks;
        self.ticks += 1;
        let ok = match self.last_fired {
            None => true,
            Some(last) => now - last >= self.window,
        };
        if ok {
            self.last_fired = Some(now);
            fire();
        }
        ok
    }
}

fn main() {
    let mut d = Debouncer::new(3);
    let mut calls = 0;
    let mut out = Vec::new();
    for _ in 0..10 {
        out.push(d.tick(|| calls += 1));
    }
    assert_eq!(calls, 4);
    assert_eq!(out[0], true);
    assert_eq!(out[1], false);
    println!("fired {} times", calls);
}
```
Using tick counts instead of wall-clock time keeps the logic deterministic and testable. The closure is `FnMut` so it can mutate captured state; `last_fired` starts as `None` so the first tick always fires.

