def rotate_right(items, k):
    n = len(items)
    if n == 0:
        return []
    k %= n
    if k == 0:
        return list(items)
    return list(items[-k:]) + list(items[:-k])


def rotate_right_inplace(items, k):
    n = len(items)
    if n == 0:
        return
    k %= n

    def reverse(lo, hi):
        while lo < hi:
            items[lo], items[hi] = items[hi], items[lo]
            lo += 1
            hi -= 1

    reverse(0, n - 1)
    reverse(0, k - 1)
    reverse(k, n - 1)


if __name__ == "__main__":
    base = list(range(1, 8))
    for k in (0, 2, 7, 9):
        print(k, rotate_right(base, k))

    buf = list(range(1, 8))
    rotate_right_inplace(buf, 3)
    print("inplace:", buf)
```

The in-place version is the classic triple-reverse trick and handles `k` larger than the list length via the modulo.

