```rust
#[derive(Debug, PartialEq)]
pub enum BracketError {
    UnexpectedClose(usize),
    UnexpectedEnd(usize),
}

pub fn check_brackets(input: &str) -> Result<(), BracketError> {
    let mut stack: Vec<(char, usize)> = Vec::new();

    for (idx, ch) in input.char_indices() {
        match ch {
            '(' | '[' | '{' => stack.push((ch, idx)),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some((open, _)) if open == expected => {}
                    _ => return Err(BracketError::UnexpectedClose(idx)),
                }
            }
            _ => {}
        }
    }

    match stack.pop() {
        Some((_, idx)) => Err(BracketError::UnexpectedEnd(idx)),
        None => Ok(()),
    }
}

fn main() {
    assert_eq!(check_brackets("([]{})"), Ok(()));
    assert_eq!(check_brackets("(])"), Err(BracketError::UnexpectedClose(1)));
    assert_eq!(check_brackets("(()"), Err(BracketError::UnexpectedEnd(0)));
    println!("ok");
}
```

`char_indices` gives byte offsets for the reported positions, so the error is pinned to the exact character in the original string. Non-bracket characters are ignored, letting the check run over mixed source text.

