#include <functional>
#include <iostream>
#include <queue>
#include <vector>

class RunningMedian {
public:
    void add(int value) {
        if (low_.empty() || value <= low_.top()) {
            low_.push(value);
        } else {
            high_.push(value);
        }
        rebalance();
    }

    double median() const {
        if (low_.size() == high_.size()) {
            return (static_cast<double>(low_.top()) + high_.top()) / 2.0;
        }
        return static_cast<double>(low_.top());
    }

private:
    void rebalance() {
        if (low_.size() > high_.size() + 1) {
            high_.push(low_.top());
            low_.pop();
        } else if (high_.size() > low_.size()) {
            low_.push(high_.top());
            high_.pop();
        }
    }

    std::priority_queue<int> low_;                                  // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high_; // min-heap
};

int main() {
    RunningMedian rm;
    int value;
    while (std::cin >> value) {
        rm.add(value);
        std::cout << rm.median() << '\n';
    }
    return 0;
}
```

The max-heap holds the smaller half and the min-heap the larger half, so the median is always at the tops. Each insertion costs O(log n), and the rebalance keeps the sizes within one of each other.

