use std::collections::HashMap;

struct Fib {
    memo: HashMap<u64, u128>,
}

impl Fib {
    fn new() -> Self {
        Fib { memo: HashMap::new() }
    }

    fn get(&mut self, n: u64) -> u128 {
        if n < 2 {
            return n as u128;
        }
        if let Some(&v) = self.memo.get(&n) {
            return v;
        }
        let result = self.get(n - 1) + self.get(n - 2);
        self.memo.insert(n, result);
        result
    }
}

fn main() {
    let mut fib = Fib::new();
    for n in 0..20 {
        println!("{}: {}", n, fib.get(n));
    }
    assert_eq!(fib.get(20), 6765);
    assert_eq!(fib.get(90), 2880067194370816120);
}
```

`u128` covers Fibonacci values well past n = 90 without overflow. Memoizing in a `HashMap` turns the naive exponential recursion into linear time — each n is computed once and reused.

