bool parse_int(const char *text, int *out) {
    if (text == NULL || out == NULL) {
        return false;
    }
    errno = 0;
    char *end = NULL;
    long value = strtol(text, &end, 10);

    if (end == text || *end != '\0') {
        return false;          // no digits, or trailing garbage
    }
    if (errno == ERANGE || value < INT_MIN || value > INT_MAX) {
        return false;          // overflow
    }
    *out = (int)value;
    return true;
}

int main(void) {
    int value = 0;
    const char *cases[] = {"42", "-7", "0", " 12", "12x", "", "999999999999", "2147483647", NULL};
    for (int i = 0; cases[i] != NULL; i++) {
        bool ok = parse_int(cases[i], &value);
        printf("%-16s -> %s", cases[i], ok ? "ok" : "invalid");
        if (ok) printf(" (%d)", value);
        putchar('\n');
    }
    return 0;
}
