std::vector<int> merge_unique(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());

    std::size_t i = 0, j = 0;
    while (i < a.size() || j < b.size()) {
        int next;
        if (j >= b.size() || (i < a.size() && a[i] <= b[j])) {
            next = a[i++];
        } else {
            next = b[j++];
        }
        if (out.empty() || out.back() != next) {
            out.push_back(next);
        }
    }
    return out;
}

int main() {
    std::vector<int> a{1, 3, 3, 7, 9};
    std::vector<int> b{2, 3, 4, 9, 10, 10};
    std::vector<int> merged = merge_unique(a, b);

    for (int v : merged) std::cout << v << ' ';
    std::cout << '\n';

    const std::vector<int> expected{1, 2, 3, 4, 7, 9, 10};
    if (merged != expected) {
        std::cerr << "unexpected result\n";
        return 1;
    }
    return 0;
}
