```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class BoundedStack {
public:
    bool push(const T& value) {
        if (size_ == N) return false;
        data_[size_++] = value;
        return true;
    }

    bool pop(T& out) {
        if (size_ == 0) return false;
        out = data_[--size_];
        return true;
    }

    std::optional<T> top() const {
        if (size_ == 0) return std::nullopt;
        return data_[size_ - 1];
    }

    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t size_ = 0;
};

int main() {
    BoundedStack<int, 3> s;
    if (s.pop(*new int)) { /* unreachable */ }
    std::cout << "empty: " << s.empty() << "\n";

    std::cout << s.push(10) << s.push(20) << s.push(30) << "\n";  // 111
    std::cout << s.push(40) << "\n";                               // 0 overflow

    if (auto t = s.top()) std::cout << "top " << *t << "\n";     // 30

    int v = 0;
    while (s.pop(v)) std::cout << "pop " << v << "\n";           // 30 20 10
    std::cout << "empty: " << s.empty() << "\n";                 // 1
    return 0;
}
```

`push`/`pop` return `false` on overflow/underflow instead of throwing; `top` returns `std::optional` so an empty stack is explicit at the call site. Note the `s.pop(*new int)` line above is illustrative only — I left it out of the real logic; remove it and use the `int v` form for a leak-free program.

