def two_sum(nums, target):
    """Return indices i, j with nums[i] + nums[j] == target.
    Assumes exactly one valid pair exists (indices must differ)."""
    seen = {}
    for i, n in enumerate(nums):
        need = target - n
        if need in seen:
            return seen[need], i
        seen[n] = i
    raise ValueError("no two indices sum to target")


