    assert two_sum([3, 3], 6) == (0, 1)
    assert two_sum([-1, -2, -3, -4], -7) == (2, 3)
    try:
        two_sum([1, 2], 100)
    except ValueError as e:
        print("expected:", e)
    print("ok")
