#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& a, int target) {
    int lo = 0, hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;   // avoids overflow
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> v = {1, 3, 5, 7, 9, 11};
    std::cout << binary_search(v, 7) << "\n";    // 3
    std::cout << binary_search(v, 1) << "\n";    // 0
    std::cout << binary_search(v, 11) << "\n";   // 5
    std::cout << binary_search(v, 4) << "\n";    // -1
    std::cout << binary_search({}, 4) << "\n";   // -1 (empty safe)
    return 0;
}
```
The midpoint uses `lo + (hi - lo) / 2` so `hi + lo` never overflows for large indices.

