void trim_inplace(std::string& s) {
    const char* ws = " \t\n\r\f\v";
    std::size_t start = s.find_first_not_of(ws);
    if (start == std::string::npos) {
        s.clear();
        return;
    }
    std::size_t end = s.find_last_not_of(ws);
    s = s.substr(start, end - start + 1);
