```cpp
#include <cstdint>
#include <iostream>
#include <vector>

long long count_inversions(std::vector<int>& a, int lo, int hi) {
    if (hi - lo <= 1) return 0;
    int mid = lo + (hi - lo) / 2;
    long long inv = count_inversions(a, lo, mid) +
                    count_inversions(a, mid, hi);
    std::vector<int> merged;
    merged.reserve(hi - lo);
    int i = lo, j = mid;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) merged.push_back(a[i++]);
        else {
            inv += mid - i;      // every remaining left element is > a[j]
            merged.push_back(a[j++]);
        }
    }
    while (i < mid) merged.push_back(a[i++]);
    while (j < hi) merged.push_back(a[j++]);
    for (int k = 0; k < (int)merged.size(); ++k) a[lo + k] = merged[k];
    return inv;
}

int main() {
    std::vector<int> a = {5, 4, 3, 2, 1};
    std::vector<int> b = {1, 2, 3};
    std::vector<int> c = {};
    if (count_inversions(a, 0, a.size()) != 10) return 1;
    if (count_inversions(b, 0, b.size()) != 0) return 1;
    if (count_inversions(c, 0, c.size()) != 0) return 1;
    std::cout << "ok\n";
}
```

Merge sort doubles as the counter: whenever the right half's element is smaller, all remaining left-half elements form inversions with it, so `mid - i` is added at that moment. O(n log n) time, no extra pass.

