```rust
struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
    cap: usize,
}

impl<T> RingBuffer<T> {
    fn new(cap: usize) -> Self {
        assert!(cap > 0);
        let mut data = Vec::with_capacity(cap);
        for _ in 0..cap {
            data.push(None);
        }
        RingBuffer { data, head: 0, len: 0, cap }
    }

    fn push(&mut self, value: T) {
        let slot = (self.head + self.len) % self.cap;
        self.data[slot] = Some(value);
        if self.len == self.cap {
            self.head = (self.head + 1) % self.cap;
        } else {
            self.len += 1;
        }
    }

    fn to_vec(&self) -> Vec<&T> {
        (0..self.len)
            .map(|i| self.data[(self.head + i) % self.cap].as_ref().unwrap())
            .collect()
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    rb.push(1);
    rb.push(2);
    rb.push(3);
    rb.push(4);
    assert_eq!(rb.to_vec(), vec![&2, &3, &4]);
    rb.push(5);
    assert_eq!(rb.to_vec(), vec![&3, &4, &5]);
    assert_eq!(RingBuffer::<i32>::new(1).to_vec(), Vec::<&i32>::new());
    println!("ok");
}
```

The `Some`/`None` slots let a full buffer differ from an empty one; `head` advances only once capacity is reached, and `to_vec` walks logical order using modular arithmetic.

