fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    let mut in_str = false;
    let mut escape = false;

    for c in s.chars() {
        if in_str {
            if escape {
                escape = false;
            } else if c == '\\' {
                escape = true;
            } else if c == '"' {
                in_str = false;
            }
            continue;
        }
        match c {
            '"' => in_str = true,
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let open = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(open) {
                    return false;
                }
            }
            _ => {}
        }
    }
    !in_str && stack.is_empty()
}

fn main() {
    let cases = [
        ("([]){} true", true),
        ("([)]", false),
        ("\"(not counted)\"", true),
        ("\"unterminated", false),
        ("", true),
    ];
    for (input, want) in cases {
        // trims the descriptive suffix on the first case
        let text = input.split_whitespace().next().unwrap();
        assert_eq!(is_balanced(text), want, "failed on {text}");
    }
    println!("all tests passed");
}
