def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    def expand(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    best_start, best_end = 0, 0
    for i in range(len(s)):
        for left, right in (expand(i, i), expand(i, i + 1)):
            if right - left > best_end - best_start:
                best_start, best_end = left, right
    return s[best_start:best_end + 1]


if __name__ == "__main__":
    assert longest_palindrome("") == ""
    assert longest_palindrome("babad") in ("bab", "aba")
    assert longest_palindrome("cbbd") == "bb"
    assert longest_palindrome("a") == "a"
    assert longest_palindrome("😀ab😀") == "😀ab😀"  # astral-plane code points
    print("ok")
```

Expand around each center, tracking the widest window. It is O(n²) time and O(1) space, and the Python slicing treats astral-plane characters as single code points.

