`while (std::cin >> value)` stops cleanly at EOF or bad input. The `seen` flag distinguishes "no input" from a legitimate minimum value, so an empty stream reports an error on stderr instead of printing a bogus maximum.

```rust
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Interval {
    pub start: i64,
    pub end: i64,
}

pub fn merge(mut intervals: Vec<Interval>) -> Vec<Interval> {
    if intervals.is_empty() {
        return Vec::new();
    }

    intervals.sort_by_key(|iv| (iv.start, iv.end));

    let mut merged: Vec<Interval> = Vec::with_capacity(intervals.len());
    for iv in intervals {
        match merged.last_mut() {
            Some(last) if iv.start <= last.end => {
                if iv.end > last.end {
                    last.end = iv.end;
                }
            }
            _ => merged.push(iv),
        }
    }
    merged
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_is_empty() {
        assert!(merge(vec![]).is_empty());
    }

    #[test]
    fn merges_touching_and_overlapping() {
        let out = merge(vec![
            Interval { start: 5, end: 7 },
            Interval { start: 1, end: 3 },
            Interval { start: 2, end: 6 },
            Interval { start: 8, end: 9 },
            Interval { start: 9, end: 10 },
        ]);
        assert_eq!(out, vec![
            Interval { start: 1, end: 7 },
            Interval { start: 8, end: 10 },
        ]);
    }
}
```

Sort by `(start, end)`, then extend the last merged interval when the next one touches or overlaps (`iv.start <= last.end`). Touching intervals like `[5,7]` and `[7,9]` collapse into one, which is the usual convention; drop the `<=` to `<=`-off-by-one if you want half-open semantics.

```python
from collections import OrderedDict
from typing import Optional


class LRUCache:
    def __init__(self, capacity: int) -> None:
        if capacity < 0:
            raise ValueError("capacity must be non-negative")
        self.capacity = capacity
        self._data: "OrderedDict[str, int]" = OrderedDict()

    def get(self, key: str) -> Optional[int]:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: str, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1
    c.put("c", 3)          # evicts "b", the least recently used
    assert c.get("b") is None
    assert c.get("c") == 3

    zero = LRUCache(0)
    zero.put("x", 1)
    assert zero.get("x") is None and len(zero) == 0
    print("ok")
```

`OrderedDict` keeps insertion order; `move_to_end` marks a key recently used, and `popitem(last=False)` evicts the coldest entry. `get` returns `None` for a miss, and capacity 0 stores nothing.

