```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void emit_reversed(const char *buf, size_t len) {
    for (size_t i = len; i-- > 0;) {
        putchar((unsigned char)buf[i]);
    }
}

int main(void) {
    char *line = NULL;
    size_t cap = 0;
    ssize_t len;
    int wrote_any = 0;

    while ((len = getline(&line, &cap, stdin)) != -1) {
        int had_newline = len > 0 && line[len - 1] == '\n';
        size_t body = had_newline ? (size_t)len - 1 : (size_t)len;

        if (wrote_any) {
            putchar('\n');
        }
        emit_reversed(line, body);
        wrote_any = 1;
    }

    if (wrote_any) {
        putchar('\n');
    }

    free(line);
    if (ferror(stdin)) {
        perror("read");
        return 1;
    }
    return 0;
}
```

`getline` grows the buffer as needed, so arbitrarily long lines are safe. The newline is stripped before reversing and re-inserted between lines, which avoids doubling newlines and leaves exactly one terminator at the end. `putchar` operates on `unsigned char` so bytes ≥ 0x80 survive intact.

```cpp
#include <array>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <iostream>
#include <vector>

class Sha256 {
public:
    std::array<uint8_t, 32> digest(std::istream &in) {
        std::vector<uint8_t> data((std::istreambuf_iterator<char>(in)),
                                  std::istreambuf_iterator<char>());
        return hash_buffer(data);
    }

    std::array<uint8_t, 32> hash_buffer(const std::vector<uint8_t> &data) {
        std::vector<uint8_t> msg = data;
        const uint64_t bit_len = static_cast<uint64_t>(msg.size()) * 8;
        msg.push_back(0x80);
        while (msg.size() % 64 != 56) msg.push_back(0);
        for (int i = 7; i >= 0; --i)
            msg.push_back(static_cast<uint8_t>(bit_len >> (i * 8)));

        const uint32_t k[64] = {
            0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
            0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
            0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
            0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
            0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
            0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
            0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
            0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};

        uint32_t h[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                         0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};

        auto rotr = [](uint32_t x, int n) { return (x >> n) | (x << (32 - n)); };

        for (size_t off = 0; off < msg.size(); off += 64) {
            uint32_t w[64];
            for (int i = 0; i < 16; ++i) {
                w[i] = (msg[off + 4*i] << 24) | (msg[off + 4*i + 1] << 16) |
                       (msg[off + 4*i + 2] << 8) | msg[off + 4*i + 3];
            }
            for (int i = 16; i < 64; ++i) {
                uint32_t s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15] >> 3);
                uint32_t s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2] >> 10);
                w[i] = w[i-16] + s0 + w[i-7] + s1;
            }

            uint32_t a=h[0],b=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],hh=h[7];
            for (int i = 0; i < 64; ++i) {
                uint32_t S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
                uint32_t ch = (e & f) ^ (~e & g);
                uint32_t t1 = hh + S1 + ch + k[i] + w[i];
                uint32_t S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
                uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
                uint32_t t2 = S0 + maj;
                hh=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
            }
            h[0]+=a; h[1]+=b; h[2]+=c; h[3]+=d;
            h[4]+=e; h[5]+=f; h[6]+=g; h[7]+=hh;
        }

        std::array<uint8_t,32> out{};
        for (int i = 0; i < 8; ++i) {
            out[4*i]   = static_cast<uint8_t>(h[i] >> 24);
            out[4*i+1] = static_cast<uint8_t>(h[i] >> 16);
            out[4*i+2] = static_cast<uint8_t>(h[i] >> 8);
            out[4*i+3] = static_cast<uint8_t>(h[i]);
        }
        return out;
    }
};

int main(int argc, char **argv) {
    if (argc < 2) {
        std::cerr << "usage: " << argv[0] << " FILE\n";
        return 2;
    }
    std::ifstream in(argv[1], std::ios::binary);
    if (!in) {
        std::cerr << "cannot open: " << argv[1] << "\n";
        return 1;
    }
    Sha256 sha;
    auto d = sha.digest(in);
    static const char *hex = "0123456789abcdef";
    for (uint8_t b : d) {
        std::cout << hex[b >> 4] << hex[b & 0xF];
    }
    std::cout << '\n';
    return 0;
}
```

This is a full FIPS 180-4 implementation: pad with `0x80`, zero-fill to 56 mod 64, append the 64-bit big-endian bit length, then run 64 rounds with message schedule expansion. Missing or unreadable files exit 1 with a clear message. Sanity check: hashing the empty file yields `e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855`.

