def valid(expr):
    """Check balanced parentheses and legal token order for a simple expression."""
    depth = 0
    prev_is_operand = False
    for ch in expr:
        if ch == '(':
            depth += 1
            prev_is_operand = False
        elif ch == ')':
            depth -= 1
            if depth < 0 or not prev_is_operand:
                return False
            prev_is_operand = True
        elif ch.isdigit():
            prev_is_operand = True
        elif ch in '+-*/':
            if not prev_is_operand:
                return False
            prev_is_operand = False
        elif ch.isspace():
            continue
        else:
            return False
    return depth == 0 and prev_is_operand


if __name__ == "__main__":
    assert valid("(1+2)*3")
    assert valid("1")
    assert not valid("")
    assert not valid("(1+")
    assert not valid("1++2")
    assert not valid("()")
    assert not valid("1 + a")
    print("ok")
