// With uint64_t, F(93) is the largest value that fits (F(94) overflows).
std::optional<uint64_t> fib(int n) {
    if (n < 0 || n > 93) return std::nullopt;
    uint64_t a = 0, b = 1;
    for (int i = 0; i < n; ++i) {
        uint64_t next = a + b;
        a = b;
        b = next;
    }
    return a;
}

int main() {
    assert(fib(0).value() == 0);
    assert(fib(1).value() == 1);
    assert(fib(10).value() == 55);
    assert(fib(93).has_value());
    assert(!fib(94).has_value());
    assert(!fib(-1).has_value());
    std::cout << "fib(93) = " << fib(93).value() << "\n";
    return 0;
}
