use std::collections::HashMap;

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .collect::<String>()
            .to_lowercase();
        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Count descending, then word ascending for stable ties.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the quick brown fox the lazy dog The fox";
    let top = top_words(text, 3);
    assert_eq!(top[0], ("the".to_string(), 3));
    assert_eq!(top[1], ("fox".to_string(), 2));
    assert_eq!(top[2].0, "brown");
    assert!(top_words("", 5).is_empty());
    println!("{:?}", top);
}
```

Strips punctuation with `is_alphanumeric`, lowercases for case-insensitive counting, and sorts by count descending then word ascending so ties are deterministic.

