fn parse_csv_ints(input: &str) -> Result<Vec<i64>, String> {
    if input.is_empty() {
        return Err("input is empty".to_string());
    }
    let mut out = Vec::new();
    for (idx, field) in input.split(',').enumerate() {
        let trimmed = field.trim();
        if trimmed.is_empty() {
            return Err(format!("field {} is empty", idx));
        }
        match trimmed.parse::<i64>() {
            Ok(v) => out.push(v),
            Err(_) => return Err(format!("field {} is not an integer: {:?}", idx, trimmed)),
        }
    }
    Ok(out)
}

