        if (scanf("%63s", buf) != 1) {
            break; /* end of input */
        }
        errno = 0;
        value = strtoll(buf, &end, 10);
        if (errno != 0 || *end != '\0') {
            fprintf(stderr, "error: not an integer: %s\n", buf);
            return 1;
        }
        if ((value > 0 && sum > LLONG_MAX - value) ||
            (value < 0 && sum < LLONG_MIN - value)) {
            fprintf(stderr, "error: sum overflow\n");
            return 1;
        }
        sum += value;
        count++;
    }

    printf("count=%d sum=%lld\n", count, sum);
    return 0;
}
```

`%63s` bounds each token so the buffer can't overflow. `strtoll` plus the `*end` check rejects partial parses like `12abc`, and the two overflow guards cover both signs before adding.

