use std::collections::HashMap;

/// Parse lines of `key=value`. Blank lines and `#` comments are skipped.
/// Returns the map plus a list of problems as `(line_number, reason)`.
pub fn parse_config(input: &str) -> (HashMap<String, String>, Vec<(usize, String)>) {
    let mut map = HashMap::new();
    let mut errors = Vec::new();

    for (idx, raw) in input.lines().enumerate() {
        let line_no = idx + 1;
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        match line.split_once('=') {
            None => errors.push((line_no, "missing '='".to_string())),
            Some((k, v)) => {
                let key = k.trim();
                if key.is_empty() {
                    errors.push((line_no, "empty key".to_string()));
                } else {
                    map.insert(key.to_string(), v.trim().to_string());
                }
            }
        }
    }
    (map, errors)
}

