// Returns the index of `target` if present, otherwise the index where it
// would be inserted to keep the vector sorted (the lower_bound).
std::size_t lower_bound_idx(const std::vector<int>& v, int target) {
    std::size_t lo = 0;
    std::size_t hi = v.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;  // no overflow
        if (v[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

int main() {
    const std::vector<int> v{1, 3, 3, 5, 8};
    std::cout << lower_bound_idx(v, 3) << '\n';  // 1
    std::cout << lower_bound_idx(v, 4) << '\n';  // 3
    std::cout << lower_bound_idx(v, 0) << '\n';  // 0
    std::cout << lower_bound_idx(v, 9) << '\n';  // 5
    std::cout << lower_bound_idx({}, 7) << '\n'; // 0
    return 0;
}
