def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)          # odd length
        l2, r2 = expand(i, i + 1)      # even length
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "ünïcödé"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```
The loop runs two expansions per index, so it is O(n²) time and O(1) extra space. Unicode works because indexing is character-based, not byte-based.

