use std::fmt;

#[derive(Debug, PartialEq)]
pub struct Version {
    pub major: u32,
    pub minor: u32,
    pub patch: u32,
}

#[derive(Debug, PartialEq)]
pub struct ParseError(String);

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "invalid version: {}", self.0)
    }
}

pub fn parse_version(s: &str) -> Result<Version, ParseError> {
    let mut parts = s.split('.');
    let major = parts.next().ok_or_else(|| ParseError(s.into()))?;
    let minor = parts.next().ok_or_else(|| ParseError(s.into()))?;
    let patch = parts.next().ok_or_else(|| ParseError(s.into()))?;
    if parts.next().is_some() {
        return Err(ParseError(s.into()));
    }
    let parse = |p: &str| p.parse::<u32>().map_err(|_| ParseError(s.into()));
    Ok(Version {
        major: parse(major)?,
        minor: parse(minor)?,
        patch: parse(patch)?,
    })
}

fn main() {
    assert_eq!(parse_version("1.2.3"), Ok(Version { major: 1, minor: 2, patch: 3 }));
    assert!(parse_version("1.2").is_err());
    assert!(parse_version("1.2.3.4").is_err());
    assert!(parse_version("a.b.c").is_err());
    assert!(parse_version("").is_err());
    println!("all assertions passed");
}
```
