```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

static struct Node *push(struct Node *head, int v) {
    struct Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(1); }
    n->value = v;
    n->next = head;
    return n;
}

static struct Node *reverse(struct Node *head) {
    struct Node *prev = NULL;
    while (head) {
        struct Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(struct Node *head) {
    for (; head; head = head->next)
        printf("%d%s", head->value, head->next ? " -> " : "\n");
    if (!head) puts("(empty)");
}

int main(void) {
    struct Node *head = NULL;
    for (int i = 5; i >= 1; --i) head = push(head, i);
    print_list(head);
    head = reverse(head);
    print_list(head);

    while (head) {
        struct Node *tmp = head;
        head = head->next;
        free(tmp);
    }
    print_list(NULL);
    return 0;
}
```
The iterative reverse swaps `next` pointers with a `prev` cursor, so it is O(n) time and O(1) space. `print_list` on a NULL head prints `(empty)` instead of dereferencing a null pointer.

