constexpr uint64_t MOD = 1'000'000'007ULL;

// Returns (F(n), F(n+1)) modulo MOD.
std::pair<uint64_t, uint64_t> fib_pair(uint64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    uint64_t c = a * ((2 * b % MOD + MOD - a) % MOD) % MOD;
    uint64_t d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1ULL) return {d, (c + d) % MOD};
    return {c, d};
}

int main() {
    uint64_t n;
    if (!(std::cin >> n)) {
        std::cerr << "usage: echo N | fib\n";
        return 1;
    }
    std::cout << fib_pair(n).first << '\n';
    return 0;
}
