#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), size_(0), cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool push(const T& value) {
        if (size_ == cap_) return false;
        buf_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    bool pop(T& out) {
        if (size_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<T> buf_;
    std::size_t head_, size_, cap_;
};

int main() {
    RingBuffer<int> rb(3);
    rb.push(1); rb.push(2); rb.push(3);
    std::cout << "full push: " << rb.push(4) << "\n";
    int v;
    while (rb.pop(v)) std::cout << v << " ";
    std::cout << "\nempty pop: " << rb.pop(v) << "\n";
}
