use std::collections::BinaryHeap;
use std::cmp::Reverse;
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut low: BinaryHeap<i64> = BinaryHeap::new();          // max-heap
    let mut high: BinaryHeap<Reverse<i64>> = BinaryHeap::new(); // min-heap

    for line in stdin.lock().lines() {
        let line = line.expect("read failed");
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let n: i64 = match trimmed.parse() {
            Ok(v) => v,
            Err(_) => {
                eprintln!("skipping non-integer: {}", trimmed);
                continue;
            }
        };

        if low.peek().map_or(true, |&top| n <= top) {
            low.push(n);
        } else {
            high.push(Reverse(n));
        }

        if low.len() > high.len() + 1 {
            high.push(Reverse(low.pop().unwrap()));
        } else if high.len() > low.len() {
            low.push(high.pop().unwrap().0);
        }

        let median = if low.len() == high.len() {
            (low.peek().unwrap() + high.peek().unwrap().0) as f64 / 2.0
        } else {
            *low.peek().unwrap() as f64
        };
        println!("median: {}", median);
    }
}
```

`low` holds the smaller half as a max-heap, `high` the larger half as a min-heap wrapped in `Reverse`. Rebalancing keeps their sizes within one, so the median is the top of `low` or the mean of both tops.

