#include <limits.h>
#include <stdio.h>
#include <ctype.h>

int parse_long_strict(const char *s, long *out) {
    if (s == NULL || out == NULL) return 0;
    while (isspace((unsigned char)*s)) s++;

    int negative = 0;
    if (*s == '+' || *s == '-') {
        negative = (*s == '-');
        s++;
    }
    if (!isdigit((unsigned char)*s)) return 0;

    long acc = 0;
    while (isdigit((unsigned char)*s)) {
        int digit = *s - '0';
        long limit = negative ? -(LONG_MIN + digit) : (LONG_MAX - digit);
        if (acc > limit / 10) return 0;
        acc = acc * 10 + digit;
        s++;
    }
    *out = negative ? -acc : acc;
    return 1;
}

int main(void) {
    long v;
    printf("%d %ld\n", parse_long_strict("  -42xyz", &v), v);
    printf("%d\n", parse_long_strict("999999999999999999999", &v));
    printf("%d %ld\n", parse_long_strict("0", &v), v);
    printf("%d\n", parse_long_strict("", &v));
    return 0;
}
```

The limit check `acc > limit / 10` stops before multiplication can overflow, using `LONG_MIN` asymmetry so `LONG_MIN` itself parses. Trailing non-digits are accepted after the digits (`-42xyz` -> `-42`). Invalid or overflowing input returns `0` and leaves the caller's check.

