    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fp_(other.fp_) { other.fp_ = nullptr; }
    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            close();
            fp_ = other.fp_;
            other.fp_ = nullptr;
        }
        return *this;
    }

    bool is_open() const noexcept { return fp_ != nullptr; }
    FILE* get() const noexcept { return fp_; }

    void close() noexcept {
        if (fp_) {
            std::fclose(fp_);
            fp_ = nullptr;
        }
    }

private:
    FILE* fp_;
};

int main() {
    FileHandle f("/etc/hostname", "r");
    std::cout << "open: " << f.is_open() << "\n";
    FileHandle g = std::move(f);
    std::cout << "after move, f open: " << f.is_open() << ", g open: " << g.is_open() << "\n";
    return 0;
}
