pub struct Semver {
    pub major: u32,
    pub minor: u32,
    pub patch: u32,
}

pub fn parse_semver(s: &str) -> Result<Semver, String> {
    let mut parts = s.split('.');
    let major = parts
        .next()
        .ok_or_else(|| format!("missing major in {s:?}"))?
        .parse::<u32>()
        .map_err(|_| format!("bad major in {s:?}"))?;
    let minor = parts
        .next()
        .ok_or_else(|| format!("missing minor in {s:?}"))?
        .parse::<u32>()
        .map_err(|_| format!("bad minor in {s:?}"))?;
    let patch = parts
        .next()
        .ok_or_else(|| format!("missing patch in {s:?}"))?
        .parse::<u32>()
        .map_err(|_| format!("bad patch in {s:?}"))?;
    if parts.next().is_some() {
        return Err(format!("too many components in {s:?}"));
    }
    Ok(Semver { major, minor, patch })
}

fn main() {
    assert_eq!(parse_semver("1.2.3"), Ok(Semver { major: 1, minor: 2, patch: 3 }));
    assert!(parse_semver("1.2").is_err());
    assert!(parse_semver("1.2.3.4").is_err());
    assert!(parse_semver("1.2.x").is_err());
