from typing import Sequence

def binary_search(values: Sequence[int], target: int) -> int:
    """Return the index of target in sorted values, else -1.
    Raises TypeError if values is a str (common accidental input).
    """
    if isinstance(values, str):
        raise TypeError("values must be a sequence of numbers, not str")
    lo, hi = 0, len(values) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if values[mid] == target:
            return mid
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


if __name__ == "__main__":
    assert binary_search([], 3) == -1
    assert binary_search([1, 3, 5, 7], 5) == 2
    assert binary_search([1, 3, 5, 7], 4) == -1
    try:
        binary_search("abcd", "c")
    except TypeError as e:
        print("guarded:", e)
