#include <cassert>
#include <iostream>
#include <vector>

struct Node {
    int value;
    Node* next;
};

Node* build(const std::vector<int>& values) {
    Node* head = nullptr;
    for (auto it = values.rbegin(); it != values.rend(); ++it) {
        head = new Node{*it, head};
    }
    return head;
}

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

std::vector<int> to_vector(Node* head) {
    std::vector<int> out;
    for (Node* n = head; n; n = n->next) out.push_back(n->value);
    return out;
}

void free_list(Node* head) {
    while (head) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    Node* empty = reverse(build({}));
    assert(to_vector(empty).empty());

    Node* single = reverse(build({7}));
    assert((to_vector(single) == std::vector<int>{7}));
    free_list(single);

    Node* multi = reverse(build({1, 2, 3, 4}));
    assert((to_vector(multi) == std::vector<int>{4, 3, 2, 1}));
    free_list(multi);

    std::cout << "all assertions passed\n";
}
