use std::collections::HashMap;

/// Return the `n` most frequent words, case-insensitive, splitting on
/// non-alphanumeric characters. Ties break alphabetically for determinism.
pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text
        .split(|c: char| !c.is_alphanumeric())
        .filter(|w| !w.is_empty())
    {
        *counts.entry(word.to_lowercase()).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Descending by count, then ascending by word.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the quick brown fox jumps over the lazy dog. The DOG sleeps.";
    for (word, count) in top_words(text, 3) {
        println!("{word}: {count}");
    }
    // Empty input:
    assert!(top_words("", 5).is_empty());
    // Unicode words:
    let unicode = top_words("café café th\u{00e9} th\u{00e9} th\u{00e9}", 1);
    assert_eq!(unicode[0].0, "th\u{00e9}");
    assert_eq!(unicode[0].1, 3);
    // n larger than the vocabulary must not panic.
    assert_eq!(top_words("one", 100).len(), 1);
    println!("all checks passed");
}
```

`split` treats any non-alphanumeric character as a separator, `to_lowercase` folds case, and the sort comparator makes the output deterministic. `truncate` handles `n` larger than the vocabulary safely.

```c
#include <stdio.h>
#include <string.h>

/* Reverse a UTF-8 string in place by reversing whole code points,
   not bytes, so multibyte characters stay intact. */
static void reverse_utf8(char *s) {
    size_t len = strlen(s);
    size_t i = 0;
    size_t j = len;

    while (i < j) {
        /* Find the start and end of the code point at position i. */
        size_t start_i = i;
        i++;
        while (i < len && ((unsigned char)s[i] & 0xC0) == 0x80) i++;

        /* Find the previous code point from the right. */
        size_t end_j = j;
        size_t start_j = end_j;
        do {
            start_j--;
        } while (start_j > 0 && ((unsigned char)s[start_j] & 0xC0) == 0x80);
        j = start_j;

        if (start_i >= j) break;

        /* Swap byte blocks of possibly different length. */
        size_t len_i = i - start_i;
        size_t len_j = end_j - start_j;
        char tmp[4];
        memcpy(tmp, s + start_i, len_i);
        memmove(s + start_i, s + start_j, len_j);
        memmove(s + start_j + (len_i - len_j), tmp, len_i);
        /* Adjust the left pointer for a length mismatch. */
        if (len_i != len_j) {
            i = start_i + len_j;
            j = start_j + len_i;
        }
    }
}

int main(void) {
    char a[] = "hello";
    reverse_utf8(a);
    printf("%s\n", a); /* olleh */

    char b[] = "caf\xc3\xa9"; /* "café" in UTF-8 */
    reverse_utf8(b);
    printf("%s\n", b); /* été-fac spelled backwards */

    char c[] = "";
    reverse_utf8(c);
    printf("[%s]\n", c); /* [] */

    return 0;
}
```

This is a real character-level swap, not `strrev`: multibyte sequences are detected by their leading bytes (`0xC0` continuation mask) and moved as units, so `café` reverses to `éfac`. Only the swap trick for unequal byte widths is subtle, which is why I track `len_i`/`len_j` and reposition the pointers.

```rust
use std::io::{self, BufRead};
use std::collections::BinaryHeap;
use std::cmp::Reverse;

/// Two-heap running median: `lower` is a max-heap, `upper` a min-heap.
struct RunningMedian {
    lower: BinaryHeap<i64>,
    upper: BinaryHeap<Reverse<i64>>,
}

impl RunningMedian {
    fn new() -> Self {
        RunningMedian { lower: BinaryHeap::new(), upper: BinaryHeap::new() }
    }

    fn push(&mut self, x: i64) {
        if self.lower.peek().map_or(true, |&m| x <= m) {
            self.lower.push(x);
        } else {
            self.upper.push(Reverse(x));
        }
        // Rebalance so sizes differ by at most one.
        if self.lower.len() > self.upper.len() + 1 {
            let v = self.lower.pop().unwrap();
            self.upper.push(Reverse(v));
        } else if self.upper.len() > self.lower.len() {
            let Reverse(v) = self.upper.pop().unwrap();
            self.lower.push(v);
        }
    }

    /// Returns the median. With an even count, returns the lower middle value.
    fn median(&self) -> Option<i64> {
        self.lower.peek().copied()
    }
}

fn main() {
    let stdin = io::stdin();
    let mut rm = RunningMedian::new();

    for line in stdin.lock().lines() {
        let line = line.expect("read error");
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        match trimmed.parse::<i64>() {
            Ok(x) => {
                rm.push(x);
                println!("{}", rm.median().unwrap());
            }
            Err(_) => eprintln!("skipping non-integer: {trimmed}"),
        }
    }
}
```

`BinaryHeap<i64>` is a max-heap for the lower half and `BinaryHeap<Reverse<i64>>` is a min-heap for the upper half, so both heaps are standard-library only. Empty input prints nothing and exits cleanly; non-integers are skipped with a warning to stderr rather than crashing.

```cpp
#include <iostream>
#include <vector>
#include <list>
#include <optional>
#include <stdexcept>

// Works for any forward range whose elements are comparable.
// Returns std::nullopt for an empty range instead of dereferencing end().
template <typename Range>
auto safe_max(const Range& r) -> std::optional<typename Range::value_type> {
    using T = typename Range::value_type;
    auto it = r.begin();
    auto end = r.end();
    if (it == end) {
        return std::nullopt;
    }
    T best = *it;
    for (++it; it != end; ++it) {
        if (*it > best) {
            best = *it;
        }
    }
    return best;
}

int main() {
    std::vector<int> v{3, 9, 1, 9, 4};
    std::list<double> l{2.5, -1.0, 7.25};
    std::vector<int> empty;

    std::cout << safe_max(v).value_or(-1) << "\n";      // 9
    std::cout << safe_max(l).value_or(-1) << "\n";      // 7.25
    std::cout << safe_max(empty).value_or(-1) << "\n";  // -1 (no elements)

    // Element type is preserved; no slicing, since we use value_type.
    static_assert(std::is_same_v<decltype(safe_max(v)), std::optional<int>>);
    static_assert(std::is_same_v<decltype(safe_max(l)), std::optional<double>>);
}
```

Using `std::optional` instead of returning a reference avoids dangling-reference bugs and lets the caller choose a default with `value_or`. The template accepts any range exposing `begin`/`end`/`value_type`, and the `static_assert`s pin the deduced element types.

