#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    Node* cur = head;
    while (cur != nullptr) {
        Node* next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);

    head = reverse(head);
    for (Node* n = head; n != nullptr; n = n->next) {
        std::cout << n->value << (n->next ? " -> " : "\n");
    }

    while (head != nullptr) {
        Node* dead = head;
        head = head->next;
        delete dead;
    }
    return 0;
}
```
The loop keeps three pointers: `prev`, `cur`, and a saved `next` so the link can be flipped without losing the rest of the list. An empty list returns `nullptr` because `prev` starts at null.

