#include <limits.h>
#include <stdbool.h>
#include <stdio.h>

bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;
    int sign = 1;
    if (*s == '+' || *s == '-') {
        if (*s == '-') sign = -1;
        s++;
    }
    if (*s == '\0') return false;

    long long acc = 0;
    for (; *s != '\0'; s++) {
        if (*s < '0' || *s > '9') return false;
        acc = acc * 10 + (*s - '0');
        if (sign == 1 && acc > INT_MAX) return false;
        if (sign == -1 && -acc < INT_MIN) return false;
    }
    *out = (int)(sign * acc);
    return true;
}

int main(void) {
    int v;
    printf("%d\n", parse_int("2147483647", &v));
    printf("%d\n", parse_int("999999999999", &v));
    printf("%d\n", parse_int("12x", &v));
    printf("%d\n", parse_int("", &v));
    return 0;
}
