```c
#include <stdio.h>
#include <stddef.h>

static void reverse(int *a, size_t lo, size_t hi) {
    while (lo < hi) {
        int t = a[lo];
        a[lo] = a[hi];
        a[hi] = t;
        lo++;
        hi--;
    }
}

void rotate_right(int *a, size_t n, size_t k) {
    if (n == 0) return;
    k %= n;
    if (k == 0) return;
    reverse(a, 0, n - 1);
    reverse(a, 0, k - 1);
    reverse(a, k, n - 1);
}

int main(void) {
    int a[] = {1, 2, 3, 4, 5};
    size_t n = sizeof(a) / sizeof(a[0]);
    rotate_right(a, n, 7);
    for (size_t i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
```
`k %= n` folds rotations larger than the array; rotating by 7 with length 5 is the same as 2. The triple-reverse trick rotates in place with O(1) extra space and handles `n` of zero by early return.

