    Stats s = computeStats(data);
    std::cout << "mean=" << s.mean << " stddev=" << s.stddev << '\n';
    Stats e = computeStats({});
    std::cout << "empty mean=" << e.mean << " stddev=" << e.stddev << '\n';
}
