```rust
struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T: Copy> RingBuffer<T> {
    fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        RingBuffer { data: vec![None; capacity], head: 0, len: 0 }
    }

    fn push(&mut self, value: T) {
        let idx = (self.head + self.len) % self.data.len();
        self.data[idx] = Some(value);
        if self.len == self.data.len() {
            self.head = (self.head + 1) % self.data.len();
        } else {
            self.len += 1;
        }
    }

    fn iter(&self) -> impl Iterator<Item = T> + '_ {
        (0..self.len).map(move |i| {
            self.data[(self.head + i) % self.data.len()].unwrap()
        })
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    for x in [1, 2, 3, 4, 5] { rb.push(x); }
    let out: Vec<i32> = rb.iter().collect();
    assert_eq!(out, vec![3, 4, 5]);   // oldest two overwritten
    println!("{:?}", out);
}
```
The `% capacity` index math avoids shifting elements; `Copy` keeps the simple `unwrap` path free of clone bookkeeping.

