#include <iostream>
#include <unordered_map>
#include <vector>

long long count_pairs(const std::vector<int>& nums, int target) {
    std::unordered_map<int, long long> seen;
    long long pairs = 0;
    for (int n : nums) {
        int need = target - n;
        auto it = seen.find(need);
        if (it != seen.end()) pairs += it->second;
        seen[n] += 1;
    }
    return pairs;
}

int main() {
    std::cout << count_pairs({1, 2, 3, 4, 3}, 6) << "\n";   // 1+? -> (2,4),(3,3) => 2
    std::cout << count_pairs({-1, 1, 0, 2, -2}, 0) << "\n"; // (-1,1),(2,-2) => 2
    std::cout << count_pairs({5, 5, 5, 5}, 10) << "\n";     // C(4,2)=6
    std::cout << count_pairs({}, 3) << "\n";                // 0
    return 0;
}
```
Each element looks up its complement in the map before inserting itself, so a pair is counted exactly once at `i < j`. Counting prior occurrences with `long long` avoids overflow when many duplicates are present.

