```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.store = OrderedDict()

    def get(self, key):
        if key not in self.store:
            return None
        self.store.move_to_end(key)
        return self.store[key]

    def put(self, key, value):
        if key in self.store:
            self.store.move_to_end(key)
        self.store[key] = value
        if len(self.store) > self.capacity:
            self.store.popitem(last=False)

    def __len__(self):
        return len(self.store)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1
    c.put("c", 3)          # evicts "b"
    assert c.get("b") is None
    assert c.get("a") == 1
    assert c.get("c") == 3
    c.put("d", 4)          # evicts "a"
    assert c.get("a") is None
    assert c.get("d") == 4
    print("lru ok")
```
`move_to_end` marks a key as most-recently used on both `get` and `put`. `popitem(last=False)` removes the least-recently used entry once capacity is exceeded, which is what makes the `b` and `a` evictions happen in the asserts.

```cpp
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;                            // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap
    int x;
    while (std::cin >> x) {
        // insert
        if (low.empty() || x <= low.top()) {
            low.push(x);
        } else {
            high.push(x);
        }
        // rebalance so low.size() == high.size() or low.size() == high.size() + 1
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }
        // report
        if (low.size() > high.size()) {
            std::cout << low.top() << "\n";
        } else {
            std::cout << (low.top() + high.top()) / 2.0 << "\n";
        }
    }
    return 0;
}
```
The two heaps keep the lower half in `low` (max-heap) and the upper half in `high` (min-heap). Rebalancing after each insert guarantees the heap tops are the middle one or two values, so each median is O(log n) and the split point is exact.

```rust
fn first_index(haystack: &[i32], target: i32) -> Option<usize> {
    let (mut lo, mut hi) = (0usize, haystack.len());
    let mut result = None;
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if haystack[mid] < target {
            lo = mid + 1;
        } else {
            if haystack[mid] == target {
                result = Some(mid);
            }
            hi = mid;
        }
    }
    result
}

fn main() {
    let data = [1, 2, 2, 2, 3, 5, 8];
    assert_eq!(first_index(&data, 2), Some(1));
    assert_eq!(first_index(&data, 5), Some(5));
    assert_eq!(first_index(&data, 4), None);
    assert_eq!(first_index(&[], 1), None);
    assert_eq!(first_index(&data, 1), Some(0));
    println!("ok");
}
```
On a hit the code records the candidate and moves `hi` left, so later equal elements can overwrite it and the final result is the leftmost match. `lo + (hi - lo) / 2` avoids an overflow that `(lo + hi) / 2` could hit on large slices.

