#include <stdio.h>
#include <string.h>

/* Reverse a NUL-terminated string in place. Returns the same pointer. */
char *reverse_string(char *s) {
    if (s == NULL) {
        return NULL;
    }

    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) {
        return s; /* empty string: nothing to do */
    }
    right--; /* index of the last character, not the NUL */

    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
    return s;
}

int main(void) {
    char buf[] = "Hello, world!";
    reverse_string(buf);
    printf("%s\n", buf); /* !dlrow ,olleH */

    char empty[] = "";
    reverse_string(empty);
    printf("\"%s\"\n", empty); /* "" */

    return 0;
}
```

The function swaps characters from both ends toward the middle, so it works for odd and even lengths alike and touches each byte at most once.

