        *counts.entry(cleaned).or_insert(0) += 1;
    }

    let mut items: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count desc, then alphabetically asc for deterministic ties.
    items.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    items.truncate(limit);
    items
}

fn main() {
    let text = "the quick brown fox jumps over the lazy dog. The fox was quick!";
    for (word, count) in top_words(text, 3) {
        println!("{word}: {count}");
    }
}
```

Output is `the: 3`, `fox: 2`, `quick: 2` — ties broken alphabetically so runs are reproducible.

```cpp
#include <cstddef>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), count_(0) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be > 0");
        }
    }

    void push(int value) {
        if (count_ == buf_.size()) {
            throw std::overflow_error("ring buffer is full");
        }
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % buf_.size();
        ++count_;
    }

    int pop() {
        if (count_ == 0) {
            throw std::underflow_error("ring buffer is empty");
        }
        int value = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == buf_.size(); }

private:
    std::vector<int> buf_;
    std::size_t head_;
    std::size_t tail_;
    std::size_t count_;
};
```

`push` throws `std::overflow_error` when full, `pop` throws `std::underflow_error` when empty, and constructing with zero capacity throws `std::invalid_argument`.

