def validate(email):
    """Return (True, None) if valid, else (False, reason)."""
    if not isinstance(email, str) or not email:
        return False, "email is empty"
    if email.count("@") != 1:
        return False, "must contain exactly one '@'"
    local, _, domain = email.partition("@")
    if not local:
        return False, "local part is empty"
    if not domain:
        return False, "domain part is empty"
    if local.startswith(".") or local.endswith("."):
        return False, "local part must not start or end with '.'"
    if ".." in local:
        return False, "local part must not contain consecutive dots"
    if "." not in domain:
        return False, "domain must contain a dot"
    if _EMAIL_RE.match(email):
        return True, None
    return False, "does not match the expected pattern"


if __name__ == "__main__":
    for candidate in ["a@b.com", "a.b@sub.example.org", "bad@@x.com", "no-at.com"]:
        ok, reason = validate(candidate)
        print(f"{candidate!r}: {'valid' if ok else 'invalid - ' + reason}")
