#[derive(Debug, PartialEq)]
pub enum ParseError {
    WrongPartCount(usize),
    NotANumber { part: &'static str, value: String },
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::WrongPartCount(n) => {
                write!(f, "expected 3 dot-separated parts, got {n}")
            }
            ParseError::NotANumber { part, value } => {
                write!(f, "{part} is not a number: {value:?}")
            }
        }
    }
}

pub fn parse(input: &str) -> Result<Version, ParseError> {
    let parts: Vec<&str> = input.trim().split('.').collect();
    if parts.len() != 3 {
        return Err(ParseError::WrongPartCount(parts.len()));
    }
    let nums: Result<Vec<u32>, ParseError> = parts
        .iter()
        .zip(["major", "minor", "patch"])
        .map(|(raw, name)| {
            raw.parse::<u32>()
                .map_err(|_| ParseError::NotANumber { part: name, value: raw.to_string() })
        })
        .collect();
    let nums = nums?;
    Ok(Version { major: nums[0], minor: nums[1], patch: nums[2] })
}

fn main() {
    assert_eq!(parse("1.2.3"), Ok(Version { major: 1, minor: 2, patch: 3 }));
    assert_eq!(parse("1.2"), Err(ParseError::WrongPartCount(2)));
    assert_eq!(
        parse("1.x.3"),
        Err(ParseError::NotANumber { part: "minor", value: "x".to_string() })
    );
    println!("ok");
}
