            return false;
        }
        if (octet.size() > 1 && octet[0] == '0') {
            return false; // leading zeros like "01" or "00"
        }
        int value = 0;
        for (char c : octet) {
            value = value * 10 + (c - '0');
        }
        if (value > 255) {
            return false;
        }
    }
    return true;
