void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t i = 0, j = strlen(s);
    while (i < j) {
        --j;
        if (i >= j) break;
        char t = s[i];
        s[i] = s[j];
        s[j] = t;
        ++i;
    }
}

