// Returns index of the first element >= target (lower bound).
template <typename T>
size_t lowerBound(const std::vector<T>& v, const T& target) {
    size_t lo = 0, hi = v.size();
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (v[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

template <typename T>
std::optional<size_t> search(const std::vector<T>& v, const T& target) {
    size_t i = lowerBound(v, target);
    if (i < v.size() && v[i] == target) return i;
    return std::nullopt;
}

int main() {
    std::vector<int> v = {1, 2, 2, 2, 5};
    auto r = search(v, 2);
    assert(r.has_value() && *r == 1);
    assert(!search(v, 3).has_value());
    assert(!search(std::vector<int>{}, 1).has_value());
    std::cout << "ok\n";
}
```
Lower-bound binary search finds the first match, so duplicates return the earliest index; empty vectors safely return nullopt.

