// Returns true and stores F(n) in out, or false if it would overflow uint64_t.
bool fib_u64(unsigned n, std::uint64_t& out) {
    if (n == 0) { out = 0; return true; }
    if (n == 1) { out = 1; return true; }
    std::uint64_t a = 0, b = 1;
    for (unsigned i = 2; i <= n; ++i) {
        if (b > (UINT64_MAX - a)) {
            return false; // would overflow
        }
        std::uint64_t c = a + b;
        a = b;
        b = c;
    }
    out = b;
    return true;
}

int main() {
    std::uint64_t v;
    if (!fib_u64(0, v) || v != 0) return 1;
    if (!fib_u64(10, v) || v != 55) return 1;
    if (!fib_u64(93, v) || v != 12200160415121876738ULL) return 1;
    if (fib_u64(94, v)) return 1; // must report overflow
    std::cout << "ok\n";
    return 0;
}
