            return Err(ParseError {
                line: idx + 1,
                reason: "empty key".to_string(),
            });
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let text = "# comment\n\nhost = localhost\nport=8080\n";
    let cfg = parse_config(text).unwrap();
    assert_eq!(cfg.get("host").map(String::as_str), Some("localhost"));
    assert_eq!(cfg.get("port").map(String::as_str), Some("8080"));

    let err = parse_config("host localhost\n").unwrap_err();
    assert_eq!(err.line, 1);
    assert!(err.reason.contains("key=value"));

    let err2 = parse_config("= empty\n").unwrap_err();
    assert_eq!(err2.reason, "empty key");

