    numbers = []
    skipped = 0
    for row in rows:
        raw = row.get(column, "").strip()
        if raw == "":
            skipped += 1
            continue
        try:
            numbers.append(float(raw))
        except ValueError:
            skipped += 1
    if not numbers:
        return {"count": 0, "skipped": skipped}
    return {
        "count": len(numbers),
        "skipped": skipped,
        "mean": round(mean(numbers), 4),
        "median": round(median(numbers), 4),
        "p95": round(percentile(numbers, 95), 4),
    }


if __name__ == "__main__":
