#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // max-heap for the lower half, min-heap for the upper half.
    std::priority_queue<long long> lower;
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> upper;

    long long x;
    while (std::cin >> x) {
        if (lower.empty() || x <= lower.top()) {
            lower.push(x);
        } else {
            upper.push(x);
        }

        // Rebalance so sizes differ by at most one, lower >= upper.
        if (lower.size() > upper.size() + 1) {
            upper.push(lower.top());
            lower.pop();
        } else if (upper.size() > lower.size()) {
            lower.push(upper.top());
            upper.pop();
        }

        if (lower.size() == upper.size()) {
            std::cout << (lower.top() + upper.top()) / 2.0 << '\n';
        } else {
            std::cout << lower.top() << '\n';
        }
    }
    return 0;
}
