#include <stdio.h>
#include <stdint.h>

/* Kernighan: each iteration clears the lowest set bit. */
int popcount64(uint64_t x) {
    int count = 0;
    while (x != 0) {
        x &= x - 1;   /* drop the lowest set bit */
        count++;
    }
    return count;
}

int main(void) {
    struct { uint64_t in; int expect; } cases[] = {
        {0ULL, 0},
        {1ULL, 1},
        {0xFFULL, 8},
        {UINT64_MAX, 64},
        {0x8000000000000000ULL, 1},
    };
    int n = (int)(sizeof(cases) / sizeof(cases[0]));
    for (int i = 0; i < n; i++) {
        int got = popcount64(cases[i].in);
        if (got != cases[i].expect) {
            printf("FAIL 0x%016llx got %d want %d\n",
                   (unsigned long long)cases[i].in, got, cases[i].expect);
            return 1;
        }
    }
    printf("all %d cases passed\n", n);
    return 0;
}
```

