```cpp
#include <cassert>

struct Node {
    int value;
    Node* next;
    Node(int v) : value(v), next(nullptr) {}
};

// Returns the node where the cycle begins, or nullptr if acyclic.
Node* cycle_entry(Node* head) {
    Node *slow = head, *fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            // Phase 2: walk one pointer from head, one from meeting point.
            Node* p = head;
            while (p != slow) {
                p = p->next;
                slow = slow->next;
            }
            return p;
        }
    }
    return nullptr;
}

int main() {
    // 1 -> 2 -> 3 -> 4 -> 2 (cycle starts at node with value 2)
    Node* a = new Node(1);
    Node* b = new Node(2);
    Node* c = new Node(3);
    Node* d = new Node(4);
    a->next = b; b->next = c; c->next = d; d->next = b;
    assert(cycle_entry(a) == b);

    // Acyclic list
    Node* x = new Node(9);
    x->next = new Node(10);
    assert(cycle_entry(x) == nullptr);
    return 0;
}
```

The first loop is O(n) and detects the collision; phase 2 proves the entry point is where a pointer from the head meets the slow pointer. Both phases together stay O(n) time and O(1) space.

