#include <stddef.h>
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) {
        return;
    }
    size_t len = strlen(s);
    for (size_t i = 0; i + 1 < len; ++i, --len) {
        char tmp = s[i];
        s[i] = s[len - 1];
        s[len - 1] = tmp;
    }
}

int main(void) {
    char buf[64] = "hello world";
    reverse_in_place(buf);
    printf("%s\n", buf);
    char empty[4] = "";
    reverse_in_place(empty);
    printf("[%s]\n", empty);
    return 0;
}
```

It swaps the outer pair and walks inward; the `i + 1 < len` bound stops exactly in the middle for both odd and even lengths, and a NULL pointer is a no-op rather than a crash. It treats bytes, so file-based UTF-8 reversal would need code-point handling.

