class Bitset {
public:
    explicit Bitset(std::size_t n) : words_((n + 7) / 8, 0), size_(n) {}

    bool test(std::size_t i) const {
        check(i);
        return (words_[i / 8] >> (i % 8)) & 1u;
    }

    void set(std::size_t i) {
        check(i);
        words_[i / 8] |= static_cast<unsigned char>(1u << (i % 8));
    }

    void clear(std::size_t i) {
        check(i);
        words_[i / 8] &= static_cast<unsigned char>(~(1u << (i % 8)));
    }

private:
    void check(std::size_t i) const {
        if (i >= size_) {
            throw std::out_of_range("bit index out of range");
        }
    }

    std::vector<unsigned char> words_;
    std::size_t size_;
};

