```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (empty()) return std::nullopt;
        double value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1.5);
    rb.push(2.5);
    rb.push(3.5);
    std::cout << std::boolalpha << "full: " << rb.full() << "\n";  // true
    std::cout << "push on full: " << rb.push(4.5) << "\n";        // false
    while (auto v = rb.pop()) std::cout << *v << "\n";
    std::cout << "empty: " << rb.empty() << "\n";  // true
}
```
