#include <list>
#include <stdexcept>
#include <unordered_map>

using std::list;
using std::pair;
using std::unordered_map;

template <typename K, typename V>
class LRUCache {
public:
    explicit LRUCache(size_t capacity) : cap_(capacity) {
        if (cap_ == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool get(const K& key, V& out) {
        auto it = map_.find(key);
        if (it == map_.end()) return false;
        items_.splice(items_.begin(), items_, it->second);
        out = it->second->second;
        return true;
    }

    void put(const K& key, const V& value) {
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (items_.size() == cap_) {
            map_.erase(items_.back().first);
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        map_[key] = items_.begin();
    }

private:
    size_t cap_;
    list<pair<K, V>> items_;
    unordered_map<K, typename list<pair<K, V>>::iterator> map_;
};

int main() {
    LRUCache<int, int> c(2);
    int v = 0;
    c.put(1, 10);
    c.put(2, 20);
    if (!c.get(1, v) || v != 10) return 1;
    c.put(3, 30);          // evicts key 2
    if (c.get(2, v)) return 2;
    if (!c.get(3, v) || v != 30) return 3;
    return 0;
}
