```c
#include <stddef.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; i++) {
        char tmp = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = tmp;
    }
}

int is_palindrome(const char *s) {
    if (s == NULL) return 0;
    size_t i = 0, j = strlen(s);
    while (j > 0 && i < j - 1) {
        j--;
        if (s[i] != s[j]) return 0;
        i++;
    }
    return 1;
}
```

Both guard against a NULL pointer; `is_palindrome` returns 1 for empty and single-character strings.

