#include <cctype>
#include <iostream>
#include <string>

bool is_palindrome(const std::string& s) {
    std::size_t i = 0, j = s.size();
    while (i < j) {
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[i]))) ++i;
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[j - 1]))) --j;
        if (i >= j) break;
        if (std::tolower(static_cast<unsigned char>(s[i])) !=
            std::tolower(static_cast<unsigned char>(s[j - 1]))) {
            return false;
        }
        ++i;
        --j;
    }
    return true;
}

int main() {
    struct Case { const char* in; bool want; };
    Case cases[] = {
        {"A man, a plan, a canal: Panama", true},
        {"race a car", false},
        {"", true},
        {"!!!", true},
        {"No 'x' in Nixon", true},
    };
    for (const auto& c : cases) {
        bool got = is_palindrome(c.in);
        std::cout << (got ? "true" : "false") << " (expected " << (c.want ? "true" : "false") << ")\n";
    }
}
