#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* Copies src into dst of capacity cap. Always null-terminates when cap > 0.
   Returns the number of characters copied, excluding the terminator. */
size_t safe_copy(char *dst, size_t cap, const char *src) {
    if (cap == 0) return 0;
    size_t i = 0;
    while (i + 1 < cap && src[i] != '\0') {
        dst[i] = src[i];
        ++i;
    }
    dst[i] = '\0';
    return i;
}

int main(void) {
    char buf[8];
    size_t n = safe_copy(buf, sizeof buf, "hello");
    printf("%zu %s\n", n, buf);          /* 5 hello */

    n = safe_copy(buf, sizeof buf, "a very long string");
    printf("%zu %s\n", n, buf);          /* 7 a very  */
    if (n == sizeof buf - 1) puts("truncated");

    char tiny[1];
    n = safe_copy(tiny, sizeof tiny, "abc");
    printf("%zu %s\n", n, tiny);        /* 0 (empty) */
    return 0;
}
