```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        RingBuffer { data: (0..capacity).map(|_| None).collect(), head: 0, len: 0 }
    }

    pub fn capacity(&self) -> usize { self.data.len() }
    pub fn len(&self) -> usize { self.len }
    pub fn is_empty(&self) -> bool { self.len == 0 }

    /// Push a value. If full, the oldest element is overwritten and returned.
    pub fn push(&mut self, value: T) -> Option<T> {
        let cap = self.capacity();
        let idx = (self.head + self.len) % cap;
        let overwritten = self.data[idx].take();
        self.data[idx] = Some(value);
        if self.len == cap {
            self.head = (self.head + 1) % cap;  // drop oldest
        } else {
            self.len += 1;
        }
        overwritten
    }

    /// Iterate oldest-to-newest.
    pub fn iter(&self) -> impl Iterator<Item = &T> {
        let cap = self.capacity();
        (0..self.len).filter_map(move |i| self.data[(self.head + i) % cap].as_ref())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn overwrites_oldest_when_full() {
        let mut rb = RingBuffer::new(3);
        assert_eq!(rb.push(1), None);
        assert_eq!(rb.push(2), None);
        assert_eq!(rb.push(3), None);
        assert_eq!(rb.push(4), Some(1));
        let seen: Vec<_> = rb.iter().copied().collect();
        assert_eq!(seen, vec![2, 3, 4]);
        assert_eq!(rb.len(), 3);
    }

    #[test]
    fn empty_initially() {
        let rb: RingBuffer<i32> = RingBuffer::new(2);
        assert!(rb.is_empty());
        assert_eq!(rb.iter().count(), 0);
    }
}
