/* Parse s as a long. Returns true on success and stores the value in *out.
   Rejects empty input, trailing characters, and out-of-range values. */
bool parse_long(const char *s, long *out) {
    if (s == NULL || *s == '\0') return false;
    errno = 0;
    char *end = NULL;
    long value = strtol(s, &end, 10);
    if (errno == ERANGE) return false;   /* overflow/underflow */
    if (end == s || *end != '\0') return false;  /* nothing parsed or trailing */
    *out = value;
    return true;
}

