        {"42", true}, {"-7", true}, {"", false},
        {"12x", false}, {" 5", false}, {"9999999999999999999999999", false},
    };
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        long v = 0;
        bool ok = parse_long(cases[i].in, &v);
        if (ok != cases[i].ok) {
            printf("MISMATCH for '%s': got %d\n", cases[i].in, ok);
            return 1;
        }
    }
    long v;
    if (!parse_long("12345", &v) || v != 12345) return 1;
    puts("all cases passed");
    return 0;
