#include <cstring>
#include <cassert>
#include <iostream>

// Reverses a NUL-terminated string in place. Safe on empty and length-1
// strings: the two-pointer walk stops before they cross.
void reverse_in_place(char* s) {
    if (s == nullptr) return;
    char* lo = s;
    char* hi = s + std::strlen(s) - 1;
    if (std::strlen(s) == 0) return;
    while (lo < hi) {
        char tmp = *lo;
        *lo = *hi;
        *hi = tmp;
        ++lo;
        --hi;
    }
}

int main() {
    char a[] = "algorithms";
    reverse_in_place(a);
    assert(std::strcmp(a, "smhtirogla") == 0);

    char empty[] = "";
    reverse_in_place(empty);       // must not underflow
    assert(std::strcmp(empty, "") == 0);

    char one[] = "x";
    reverse_in_place(one);
    assert(std::strcmp(one, "x") == 0);

    std::cout << "ok\n";
}
```

The empty-string guard prevents `hi` from pointing before `s`. The loop condition `lo < hi` (not `<=`) keeps the middle character untouched for odd lengths.

