/// Returns the nth Fibonacci number, with fib(0) = 0 and fib(1) = 1.
/// Switches to u128 and fails cleanly on overflow instead of wrapping.
fn fib(n: u32) -> Result<u128, &'static str> {
    let (mut a, mut b): (u128, u128) = (0, 1);
    for _ in 0..n {
        let next = a.checked_add(b).ok_or("fib overflowed u128")?;
        a = b;
        b = next;
    }
    Ok(a)
}

fn main() {
    assert_eq!(fib(0), Ok(0));
    assert_eq!(fib(1), Ok(1));
    assert_eq!(fib(10), Ok(55));
    assert_eq!(fib(30), Ok(832040));

    // fib(187) is the last value that fits in u128; fib(188) must error.
    assert!(fib(187).is_ok());
    assert_eq!(fib(188), Err("fib overflowed u128"));

    println!("fib(100) = {}", fib(100).unwrap());
}
```

The loop runs `n` times, not `n-1`, so `fib(0)` returns the initial `a = 0` correctly. `checked_add` turns a silent wrap into an explicit `Err`.

