```python
import heapq


class RunningMedian:
    """Two-heap running median: max-heap of lows, min-heap of highs."""

    def __init__(self) -> None:
        self._low = []   # negatives, so heapq acts as a max-heap
        self._high = []  # min-heap

    def add(self, value: float) -> None:
        heapq.heappush(self._low, -value)
        heapq.heappush(self._high, -heapq.heappop(self._low))
        # keep sizes within one of each other
        if len(self._high) > len(self._low):
            heapq.heappush(self._low, -heapq.heappop(self._high))

    def median(self) -> float:
        if not self._low:
            raise ValueError("no values added yet")
        if len(self._low) > len(self._high):
            return float(-self._low[0])
        return (-self._low[0] + self._high[0]) / 2.0


if __name__ == "__main__":
    rm = RunningMedian()
    results = []
    for x in [5, 15, 1, 3]:
        rm.add(x)
        results.append(rm.median())
    assert results == [5.0, 10.0, 5.0, 4.0], results

    empty = RunningMedian()
    try:
        empty.median()
        raise AssertionError("expected ValueError")
    except ValueError:
        pass
    print("ok")
```

The two heaps stay balanced within one element; an odd count reads the top of `_low`, an even count averages both tops. `add` is O(log n), `median` is O(1).

