#include <vector>
#include <cassert>
#include <iostream>

// Returns the index of target in the sorted vector, or -1 if absent.
// Uses mid = lo + (hi - lo) / 2 to avoid overflow on huge ranges.
template <typename T>
int binary_search_idx(const std::vector<T>& v, const T& target) {
    size_t lo = 0;
    size_t hi = v.size();          // half-open [lo, hi)
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (v[mid] == target) {
            return static_cast<int>(mid);
        } else if (v[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

int main() {
    std::vector<int> v = {-7, 0, 3, 3, 9, 42};
    assert(binary_search_idx(v, -7) == 0);
    assert(binary_search_idx(v, 42) == 5);
    assert((binary_search_idx(v, 3) == 2 || binary_search_idx(v, 3) == 3));
    assert(binary_search_idx(v, 5) == -1);

    std::vector<int> empty;
    assert(binary_search_idx(empty, 1) == -1);
    std::cout << "ok\n";
}
