class MinStack:
    """Stack with O(1) push/pop/peek and O(1) minimum lookup."""

    def __init__(self) -> None:
        self._data: list[int] = []
        self._mins: list[int] = []

    def push(self, value: int) -> None:
        self._data.append(value)
        # push value only if it is <= current min, keeping mins in sync on pop
        if not self._mins or value <= self._mins[-1]:
            self._mins.append(value)

    def pop(self) -> int:
        if not self._data:
            raise IndexError("pop from empty stack")
        value = self._data.pop()
        if value == self._mins[-1]:
            self._mins.pop()
        return value

    def peek(self) -> int:
        if not self._data:
            raise IndexError("peek from empty stack")
        return self._data[-1]

    def minimum(self) -> int:
        if not self._mins:
            raise IndexError("minimum from empty stack")
        return self._mins[-1]


if __name__ == "__main__":
    s = MinStack()
    for v in [-5, 3, -5, 7]:
        s.push(v)
    assert s.minimum() == -5
    assert s.pop() == 7
    assert s.minimum() == -5
    s.pop()
    assert s.minimum() == -5
    print("ok")
