#include <stddef.h>
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) {
        return;
    }
    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) {
        return;
    }
    right -= 1; /* last valid index */
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left += 1;
        right -= 1;
    }
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "a";
    reverse_in_place(a);
    reverse_in_place(b);
    reverse_in_place(c);
    reverse_in_place(NULL);
    printf("%s|%s|%s\n", a, b, c);
    return 0;
}
```

Two indices walk toward each other swapping bytes until they meet, so each character moves once. `NULL` returns immediately, and the empty string is guarded before computing `right - 1` to avoid underflow. Output is `olleh||a`.

