from functools import lru_cache


@lru_cache(maxsize=None)
def factorial(n: int) -> int:
    """Return n! for a non-negative integer n."""
    if n < 0:
        raise ValueError(f"factorial is undefined for negative n: {n}")
    if n <= 1:
        return 1
    return n * factorial(n - 1)


def fact(value) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"expected int, got {type(value).__name__}")
    return factorial(value)


if __name__ == "__main__":
    assert fact(0) == 1
    assert fact(1) == 1
    assert fact(5) == 120
    assert fact(20) == 2432902008176640000
    for bad in (-1, 2.5, "3", True):
        try:
            fact(bad)
        except (TypeError, ValueError):
            pass
        else:
            raise AssertionError(f"{bad!r} should have failed")
    print("ok")
```

`lru_cache` memoizes each `factorial(n)` so repeated calls reuse results. `fact` is the public entry point: it rejects `bool` explicitly (since `True` is an `int` subclass) and non-integers with `TypeError`, while negative integers raise `ValueError` inside the cached function. Python's arbitrary-precision ints make `fact(20)` exact.

```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), count_(0) {}

    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == buf_.size(); }
    std::size_t size() const { return count_; }

    // Returns false when full; overwriting requires an explicit pop first.
    bool push(int value) {
        if (full()) {
            return false;
        }
        buf_[(head_ + count_) % buf_.size()] = value;
        ++count_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) {
            return std::nullopt;
        }
        int value = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --count_;
        return value;
    }

private:
    std::vector<int> buf_;
    std::size_t head_;
    std::size_t count_;
};

int main() {
    RingBuffer rb(3);
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << "\n";
    while (auto v = rb.pop()) std::cout << *v << " ";
    std::cout << "\n" << rb.pop().has_value() << "\n";
}
```

`head_` is the index of the oldest element; `(head_ + count_) % capacity` gives the write slot. A full buffer refuses to overwrite and returns `false`, so no data is silently lost. `pop` returns `std::optional<int>` — `nullopt` on empty — removing any sentinel ambiguity. Output is `1110`, then `1 2 3`, then `0`.

