pub fn balanced(input: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    let mut in_quotes = false;
    let mut escaped = false;

    for c in input.chars() {
        if in_quotes {
            if escaped {
                escaped = false;
            } else if c == '\\' {
                escaped = true;
            } else if c == '"' {
                in_quotes = false;
            }
            continue;
        }
        match c {
            '"' => in_quotes = true,
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let expected = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(expected) {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty() && !in_quotes
}

fn main() {
    assert!(balanced("a(b[c]{d})e"));
    assert!(!balanced("(]") );
    assert!(balanced("\"(not counted)\""));
    assert!(balanced("\"esc\\\"aped(\""));
    assert!(!balanced("(é"));
    println!("ok");
}
```

A stack holds the open brackets. Inside a quoted string, brackets are skipped and `\"` is honored via the `escaped` flag so a quote can be literal. On a closer, the popped top must be its matching opener or the function returns `false`. At the end both the stack must be empty and no quote may be left open. Non-bracket characters, including non-ASCII ones, are ignored.

