#include <stddef.h>
#include <stdio.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = 0;
    while (s[len] != '\0') ++len;
    if (len < 2) return;

    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
