    char empty[] = "";
    char one[] = "x";
    char even[] = "abcd";
    char odd[] = "abcde";

    reverse_in_place(empty);
    reverse_in_place(one);
    reverse_in_place(even);
    reverse_in_place(odd);
    reverse_in_place(NULL);

    printf("[%s] [%s] [%s] [%s]\n", empty, one, even, odd);
    return 0;
}
```
Edge cases: `NULL` is ignored; empty and single-character strings return unchanged; even lengths swap every mirrored pair; odd lengths leave the middle character alone. The swap stops when `i >= j` so nothing is double-swapped.

