```cpp
#include <array>
#include <cstddef>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity) {}

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == cap_; }
    std::size_t size() const { return size_; }

    bool push(int value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % cap_;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

private:
    static constexpr std::size_t kMax = 1024;
    std::array<int, kMax> data_{};
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

#include <cstdio>
int main() {
    RingBuffer rb(3);
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;               // must reject when full
    if (rb.pop() != std::optional<int>{1}) return 1;
    if (rb.pop() != std::optional<int>{2}) return 1;
    rb.push(4);
    if (rb.pop() != std::optional<int>{3}) return 1;
    if (rb.pop() != std::optional<int>{4}) return 1;
    if (!rb.empty()) return 1;
    std::printf("ok\n");
    return 0;
}
```
Capacity is capped at 1024 by the backing array; `push` returns false instead of overwriting when full, so no data is silently lost.

