#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NBUCKETS 1024
#define MAX_WORD 128

typedef struct Entry {
    char *word;
    int count;
    struct Entry *next;
} Entry;

static unsigned long hash(const char *s) {
    unsigned long h = 5381;
    while (*s) h = h * 33u + (unsigned char)*s++;
    return h;
}

int main(void) {
    Entry *table[NBUCKETS] = {0};
    char buf[MAX_WORD];
    int c, n = 0;

    while ((c = getchar()) != EOF) {
        if (isalpha((unsigned char)c)) {
            if (n < MAX_WORD - 1) buf[n++] = (char)tolower((unsigned char)c);
        } else if (n > 0) {
            buf[n] = '\0';
            unsigned long idx = hash(buf) % NBUCKETS;
            Entry *e = table[idx];
            while (e && strcmp(e->word, buf) != 0) e = e->next;
            if (!e) {
                e = malloc(sizeof *e);
                if (!e) { perror("malloc"); return 1; }
                e->word = strdup(buf);
                e->count = 0;
                e->next = table[idx];
                table[idx] = e;
            }
            e->count++;
            n = 0;
        }
    }

    for (int i = 0; i < NBUCKETS; i++) {
        for (Entry *e = table[i]; e; e = e->next)
            printf("%s %d\n", e->word, e->count);
    }

    for (int i = 0; i < NBUCKETS; i++) {
        Entry *e = table[i];
        while (e) { Entry *nx = e->next; free(e->word); free(e); e = nx; }
    }
    return 0;
}
