```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    // Blocks while full. Returns false once the queue is closed.
    bool push(T value) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [&] { return closed_ || q_.size() < cap_; });
        if (closed_) return false;
        q_.push(std::move(value));
        lk.unlock();
        not_empty_.notify_one();
        return true;
    }

    // Blocks while empty. Returns nullopt once drained and closed.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;
        T out = std::move(q_.front());
        q_.pop();
        lk.unlock();
        not_full_.notify_one();
        return out;
    }

    void close() {
        { std::lock_guard<std::mutex> lk(m_); closed_ = true; }
        not_full_.notify_all();
        not_empty_.notify_all();
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lk(m_);
        return q_.size();
    }

private:
    std::size_t cap_;
    mutable std::mutex m_;
    std::condition_variable not_full_, not_empty_;
    std::queue<T> q_;
    bool closed_ = false;
};
```

`pop` on a closed-but-nonempty queue still drains remaining items before returning `nullopt`, so no work is lost on shutdown.

```c
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    unsigned char *base;
    size_t cap;
    size_t used;
} Arena;

static int arena_init(Arena *a, size_t cap) {
    a->base = malloc(cap);
    if (!a->base) return -1;
    a->cap = cap;
    a->used = 0;
    return 0;
}

static void *arena_alloc(Arena *a, size_t size, size_t align) {
    if (align == 0 || (align & (align - 1)) != 0) return NULL; /* power of two */
    size_t start = (a->used + align - 1) & ~(align - 1);
    if (start > a->cap || size > a->cap - start) return NULL;
    void *p = a->base + start;
    a->used = start + size;
    return p;
}

static void arena_reset(Arena *a) { a->used = 0; }

static void arena_free(Arena *a) { free(a->base); a->base = NULL; a->cap = a->used = 0; }

int main(void) {
    Arena a;
    if (arena_init(&a, 256) != 0) return 1;

    void *p1 = arena_alloc(&a, 10, 8);
    void *p2 = arena_alloc(&a, 20, 8);
    void *p3 = arena_alloc(&a, 4096, 8);

    printf("p1 %% 8 = %zu\n", (size_t)p1 % 8);
    printf("p2 - p1  = %td\n", (unsigned char *)p2 - (unsigned char *)p1);
    printf("p3 = %s\n", p3 == NULL ? "NULL (out of space)" : "allocated");

    arena_free(&a);
    return 0;
}
```

Every block is aligned to a power-of-two boundary, exhausted regions return `NULL` instead of overrunning, and the whole arena is released with one `free`.

