struct Row {
    name: String,
    score: f64,
}

fn top_three(text: &str) -> Result<Vec<Row>, Box<dyn Error>> {
    let mut rows = Vec::new();
    for (lineno, line) in text.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let mut parts = line.split(',');
        let name = parts.next().ok_or_else(|| format!("line {}: missing name", lineno + 1))?;
        let score_field = parts.next().ok_or_else(|| format!("line {}: missing score", lineno + 1))?;
        let score: f64 = score_field
            .trim()
            .parse()
            .map_err(|e| format!("line {}: bad score: {e}", lineno + 1))?;
        rows.push(Row { name: name.trim().to_string(), score });
    }

    rows.sort_by(|a, b| b.score.partial_cmp(&a.score).unwrap_or(std::cmp::Ordering::Equal));
    rows.truncate(3);
    Ok(rows)
}

fn main() -> Result<(), Box<dyn Error>> {
    let data = fs::read_to_string("scores.csv")?;
    for (i, r) in top_three(&data)?.iter().enumerate() {
        println!("{}. {:<12} {:>6.1}", i + 1, r.name, r.score);
    }
    Ok(())
}
```

The early-exit checks name the failing line, and `sort_by` falls back to equal ordering if a score is `NaN` so the sort never panics.

```cpp
#include <cstdint>
#include <cstdio>

static int popcount64(std::uint64_t x) {
    x = x - ((x >> 1) & 0x5555555555555555ULL);
    x = (x & 0x3333333333333333ULL) + ((x >> 2) & 0x3333333333333333ULL);
    x = (x + (x >> 4)) & 0x0F0F0F0F0F0F0F0FULL;
    x = (x * 0x0101010101010101ULL) >> 56;
    return static_cast<int>(x);
}

int main() {
    const std::uint64_t cases[] = {0ULL, 1ULL, 0xFFULL, ~0ULL, 0x8000000000000001ULL};
    const int expected[] = {0, 1, 8, 64, 2};

    for (int i = 0; i < 5; ++i) {
        int got = popcount64(cases[i]);
        if (got != expected[i]) {
            std::printf("FAIL case %d: got %d expected %d\n", i, got, expected[i]);
            return 1;
        }
    }
    std::printf("all %d cases passed\n", 5);
    return 0;
}
```

The SWAR sequence is branch-free and works for the full 64-bit range including `UINT64_MAX`, unlike the obvious `while (x) x &= x - 1;` loop which takes 64 iterations for the worst case.

