#include <stdio.h>
#include <string.h>

static size_t utf8_len(unsigned char c) {
    if ((c & 0x80) == 0) return 1;
    if ((c & 0xE0) == 0xC0) return 2;
    if ((c & 0xF0) == 0xE0) return 3;
    if ((c & 0xF8) == 0xF0) return 4;
    return 1;
}

void reverse_utf8(char *s) {
    size_t n = strlen(s);
    if (n == 0) return;
    size_t i = 0, j = n;
    char tmp[8];
    while (i < j) {
        size_t li = utf8_len((unsigned char)s[i]);
        if (i + li > j) break;
        size_t lj = 1;
        size_t k = j;
        do { --k; } while (k > i && ((unsigned char)s[k] & 0xC0) == 0x80);
        lj = j - k;
        if (i + li == j) break;
        memcpy(tmp, s + i, li);
        memmove(s + i, s + k, lj);
        memcpy(s + j - li + (j - i - li - lj), tmp, li);
        i += lj;
        j -= li;
    }
}

int main(void) {
    char buf[64] = "h\xc3\xa9llo";
    reverse_utf8(buf);
    printf("%s\n", buf);
    return 0;
}
