    rotate_right(b, 7);
    for (int x : b) std::cout << x << ' ';
    std::cout << "\n";

    std::vector<int> empty;
    rotate_right(empty, 3);
    std::cout << "empty handled, size " << empty.size() << "\n";
    return 0;
}
