    for i in range(len(s)):
        odd = expand(i, i)
        even = expand(i, i + 1)
        best = max(odd, even)
        if best > end - start:
            start = i - (best - 1) // 2
            end = i + best // 2
    return s[start:end + 1]


if __name__ == "__main__":
    for case in ["", "a", "babad", "cbbd", "abba", "日本語の日"]:
        print(repr(case), "->", repr(longest_palindrome(case)))
```
Runs in O(n^2) time and O(1) extra space; ties keep the first-found longest run.

