```cpp
#include <cctype>
#include <iostream>
#include <stack>
#include <string>

static int apply(int a, int b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': return b == 0 ? 0 : a / b;
    }
    return 0;
}

int evaluate(const std::string& s) {
    std::stack<int> nums;
    std::stack<char> ops;
    auto precedence = [](char op) { return (op == '+' || op == '-') ? 1 : 2; };
    auto reduce = [&]() {
        char op = ops.top(); ops.pop();
        int b = nums.top(); nums.pop();
        int a = nums.top(); nums.pop();
        nums.push(apply(a, b, op));
    };
    for (size_t i = 0; i < s.size(); ++i) {
        if (std::isspace(static_cast<unsigned char>(s[i]))) continue;
        if (std::isdigit(static_cast<unsigned char>(s[i]))) {
            int val = 0;
            while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
                val = val * 10 + (s[i] - '0');
                ++i;
            }
            --i;
            nums.push(val);
        } else if (s[i] == '(') {
            ops.push('(');
        } else if (s[i] == ')') {
            while (!ops.empty() && ops.top() != '(') reduce();
            if (!ops.empty()) ops.pop();
        } else {
            while (!ops.empty() && ops.top() != '(' && precedence(ops.top()) >= precedence(s[i])) reduce();
            ops.push(s[i]);
        }
    }
    while (!ops.empty()) reduce();
    return nums.empty() ? 0 : nums.top();
}

int main() {
    std::cout << evaluate("3 + 4 * 2 / (1 - 5)") << '\n';
    std::cout << evaluate("10 / 0 + 2") << '\n';
    return 0;
}
```
Division by zero yields 0 rather than crashing; unary minus is not supported, which keeps the parser small.

```rust
#[derive(Debug, PartialEq)]
pub enum BracketError {
    Unexpected(char, usize),
    Unclosed(char, usize),
}

pub fn check(s: &str) -> Result<(), BracketError> {
    let mut stack: Vec<(char, usize)> = Vec::new();
    for (i, c) in s.char_indices() {
        match c {
            '(' | '[' | '{' => stack.push((c, i)),
            ')' | ']' | '}' => {
                let expected = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some((open, _)) if open == expected => {}
                    _ => return Err(BracketError::Unexpected(c, i)),
                }
            }
            _ => {}
        }
    }
    match stack.pop() {
        Some((open, pos)) => Err(BracketError::Unclosed(open, pos)),
        None => Ok(()),
    }
}

fn main() {
    println!("{:?}", check("a(b[c]{d})e"));
    println!("{:?}", check("(]") );
    println!("{:?}", check("( [ "));
    println!("{:?}", check(""));
}
```
Byte offsets from `char_indices` are stable for multi-byte input, and empty strings pass cleanly.

