pub fn sum_valid(input: &str) -> (i64, usize) {
    let mut total: i64 = 0;
    let mut skipped = 0usize;
    for token in input.split_whitespace() {
        match token.parse::<i64>() {
            Ok(n) => total = total.saturating_add(n),
            Err(_) => skipped += 1,
        }
    }
    (total, skipped)
}

