// Two-heap running median. O(n log n) time, O(n) space.
#include <cstdint>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // max-heap for the lower half, min-heap for the upper half.
    std::priority_queue<int64_t> low;
    std::priority_queue<int64_t, std::vector<int64_t>, std::greater<int64_t>> high;

    int64_t x;
    bool first = true;
    while (std::cin >> x) {
        // Insert into the correct half.
        if (low.empty() || x <= low.top()) {
            low.push(x);
        } else {
            high.push(x);
        }

        // Rebalance so low never lags high by more than one.
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        if (!first) std::cout << '\n';
        first = false;

        if (low.size() == high.size()) {
            // Even count: average of the two middles.
            double median = (static_cast<double>(low.top()) + static_cast<double>(high.top())) / 2.0;
            std::cout << median;
        } else {
            std::cout << low.top();
        }
    }
    std::cout << '\n';
    return 0;
}
```

`low` keeps the smaller half as a max-heap and `high` the larger half as a min-heap. After each insert the two heaps differ in size by at most one, so the median is `low.top()` for odd counts or the average of the two tops for even counts. Input like `1 2 3` prints `1` `1.5` `2`.

