use std::collections::HashMap;

/// Returns Ok(()) if every bracket is matched, otherwise Err with a
/// human-readable description of the first offending character.
pub fn check_balanced(s: &str) -> Result<(), String> {
    let pairs: HashMap<char, char> = [(')', '('), (']', '['), ('}', '{')].into_iter().collect();
    let opens = "([{";
    let mut stack: Vec<(char, usize)> = Vec::new();

    for (i, c) in s.char_indices() {
        if opens.contains(c) {
            stack.push((c, i));
        } else if let Some(&expected) = pairs.get(&c) {
            match stack.pop() {
                Some((open, _)) if open == expected => {}
                Some((open, pos)) => {
                    return Err(format!(
                        "mismatched '{}' at byte {}: expected closing for '{}' opened at byte {}",
                        c, i, open, pos
                    ));
                }
                None => return Err(format!("unmatched '{}' at byte {}", c, i)),
            }
        }
    }

    if let Some((open, pos)) = stack.last() {
        return Err(format!("unclosed '{}' opened at byte {}", open, pos));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_valid() {
        assert!(check_balanced("()[]{}").is_ok());
        assert!(check_balanced("a(b[c]{d})e").is_ok());
    }

    #[test]
    fn rejects_wrong_order_and_unmatched() {
        assert!(check_balanced("([)]").is_err());
        assert!(check_balanced("(()").is_err());
        assert!(check_balanced(")").is_err());
    }
}
```

A stack tracks unmatched openers with the byte index where each was seen. Closing brackets must match `stack.pop()`; the error reports the mismatched pair or the unmatched closer. Anything left on the stack at the end is an unclosed opener, reported with its position. (`char_indices` gives byte offsets, so it stays correct with multibyte characters in the surrounding text.)

