// Minimal RFC-4180-ish CSV field parser for a single line.
// Handles: quoted fields, embedded commas, doubled quotes inside quotes.
#include <iostream>
#include <string>
#include <vector>

std::vector<std::string> parse_csv_line(const std::string& line) {
    std::vector<std::string> fields;
    std::string field;
    bool in_quotes = false;

    for (size_t i = 0; i < line.size(); ++i) {
        char c = line[i];

        if (in_quotes) {
            if (c == '"') {
                // A doubled quote is a literal quote; otherwise close the field.
                if (i + 1 < line.size() && line[i + 1] == '"') {
                    field.push_back('"');
                    ++i;
                } else {
                    in_quotes = false;
                }
            } else {
                field.push_back(c);
            }
        } else {
            if (c == '"') {
                in_quotes = true;
            } else if (c == ',') {
                fields.push_back(field);
                field.clear();
            } else {
                field.push_back(c);
            }
        }
    }
    fields.push_back(field);
    return fields;
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        auto fields = parse_csv_line(line);
        for (size_t i = 0; i < fields.size(); ++i) {
            std::cout << (i ? " | " : "") << '[' << fields[i] << ']';
        }
        std::cout << '\n';
    }
    return 0;
}
```

State machine: outside quotes a `"` opens a quoted field and `,` ends a field; inside quotes everything is literal except a `"`, which either closes the field or, when doubled, emits one literal quote. Input `a,"b,c","d""e"` yields `[a] [b,c] [d"e]`. The final `push_back` emits the last field even when the line has only one column.

