use std::collections::HashMap;
use std::env;
use std::fs;
use std::process;

fn tokenize(text: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut cur = String::new();
    for c in text.chars() {
        if c.is_alphanumeric() {
            // to_lowercase can yield multiple chars; append them all.
            for lc in c.to_lowercase() {
                cur.push(lc);
            }
        } else if !cur.is_empty() {
            words.push(std::mem::take(&mut cur));
        }
    }
    if !cur.is_empty() {
        words.push(cur);
    }
    words
}

fn main() {
    let path = match env::args().nth(1) {
        Some(p) => p,
        None => {
            eprintln!("usage: wordfreq <file>");
            process::exit(2);
        }
    };

    let text = match fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {}: {}", path, e);
            process::exit(1);
        }
    };

    let mut counts: HashMap<String, u64> = HashMap::new();
    for w in tokenize(&text) {
        *counts.entry(w).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, u64)> = counts.into_iter().collect();
    // Sort by count desc, then word asc for deterministic output.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    for (word, n) in pairs.into_iter().take(10) {
        println!("{:>7}  {}", n, word);
    }
}
```

Tokenization lowercases each alphanumeric character and treats everything else as a separator, so `Dog, dog!` counts twice. `HashMap` accumulates, then the pairs are sorted by descending count with the word as tiebreaker so equal counts print in a stable order. Missing files print an error to stderr and exit nonzero instead of panicking.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

/* Iterative reversal: O(n) time, O(1) space. */
Node *reverse_iter(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

/* Recursive reversal: O(n) time, O(n) stack. */
Node *reverse_rec(Node *head) {
    if (head == NULL || head->next == NULL) {
        return head;
    }
    Node *new_head = reverse_rec(head->next);
    head->next->next = head;
    head->next = NULL;
    return new_head;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(*n));
    if (!n) {
        perror("malloc");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static void print(Node *head) {
    for (Node *p = head; p; p = p->next) {
        printf("%d%s", p->value, p->next ? " -> " : "\n");
    }
    if (!head) printf("(empty)\n");
}

static void free_all(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 5; i >= 1; --i) {
        list = push(list, i);
    }

    printf("original:  ");
    print(list);

    list = reverse_iter(list);
    printf("iter rev:  ");
    print(list);

    list = reverse_rec(list);
    printf("rec rev:   ");
    print(list);

    /* Edge cases: empty and single-node lists. */
    Node *empty = reverse_iter(NULL);
    printf("empty:     ");
    print(empty);

    free_all(list);
    return 0;
}
```

The iterative version walks with `prev/next` pointers and flips each link; the recursive version recurses to the tail, then fixes links on the way back, with the base cases `NULL` and a single node. `push` adds to the front so the loop builds `1 -> 2 -> 3 -> 4 -> 5`, which both reversals turn into `5 -> 4 -> 3 -> 2 -> 1`. `free_all` prevents leaks.

