#include <array>
#include <cstdint>
#include <iostream>

constexpr uint64_t MOD = 1000000007ULL;

using Mat = std::array<std::array<uint64_t, 2>, 2>;

Mat mul(const Mat& a, const Mat& b) {
    Mat r{};
    for (int i = 0; i < 2; ++i)
        for (int k = 0; k < 2; ++k)
            for (int j = 0; j < 2; ++j)
                r[i][j] = (r[i][j] + a[i][k] * b[k][j]) % MOD;
    return r;
}

Mat power(Mat base, uint64_t exp) {
    Mat result{{{1, 0}, {0, 1}}};
    while (exp > 0) {
        if (exp & 1ULL) result = mul(result, base);
        base = mul(base, base);
        exp >>= 1;
    }
    return result;
}

uint64_t fib(uint64_t n) {
    if (n == 0) return 0;
    Mat m{{{1, 1}, {1, 0}}};
    return power(m, n)[0][1];
}

int main() {
    std::cout << fib(10) << '\n';              // 55
    std::cout << fib(90) << '\n';
    std::cout << fib(1000000000000000000ULL) << '\n';
    return 0;
}
