#include <iostream>
#include <queue>
#include <vector>

// Streaming median with a max-heap for the lower half and a min-heap
// for the upper half. Each number is pushed so the heaps stay within
// one element of each other, and the median is the top of the larger
// heap (odd count) or the average of both tops (even count).
int main() {
    std::priority_queue<int> lower;                         // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> upper;  // min-heap
    int x;
    while (std::cin >> x) {
        if (lower.empty() || x <= lower.top()) {
            lower.push(x);
        } else {
            upper.push(x);
        }
        if (lower.size() > upper.size() + 1) {
            upper.push(lower.top());
            lower.pop();
        } else if (upper.size() > lower.size()) {
            lower.push(upper.top());
            upper.pop();
        }
        double median;
        if (lower.size() == upper.size()) {
            median = (lower.top() + upper.top()) / 2.0;
        } else {
            median = static_cast<double>(lower.top());
        }
        std::cout << median << "\n";
    }
    return 0;
}
