#include <stack>
#include <unordered_map>

bool balanced(const std::string& s, std::size_t& badIndex) {
    std::unordered_map<char, char> opening = {{')', '('}, {']', '['}, {'}', '{'}};
    std::stack<char> st;
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (opening.count(c)) {
            if (st.empty() || st.top() != opening[c]) {
                badIndex = i;
                return false;
            }
            st.pop();
        }
    }
    if (!st.empty()) {
        badIndex = s.size();
        return false;
    }
    return true;
}

int main() {
    for (const std::string s : {"([]{})", "([)]", "((("}) {
        std::size_t bad = 0;
        bool ok = balanced(s, bad);
        std::cout << s << " -> " << (ok ? "ok" : "bad at " + std::to_string(bad)) << "\n";
    }
    return 0;
}
