/// Iterative Fibonacci using u128. Returns None if the result would
/// overflow u128 (n is too large), otherwise Some(fib(n)).
fn fib(n: u32) -> Option<u128> {
    let (mut a, mut b) = (0u128, 1u128);
    for _ in 0..n {
        let next = a.checked_add(b)?;
        a = b;
        b = next;
    }
    Some(a)
}

fn main() {
