    assert_eq!(fib(10), Some(55));
    assert_eq!(fib(100), Some(354_224_848_179_261_915_075));
    // Beyond the u128 range the checked add returns None.
    assert!(fib(200).is_none());
    println!("fib(100) = {:?}", fib(100));
