#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

// Iterative reversal: relink each node to point at its predecessor.
Node* reverseIterative(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

// Recursive reversal: reverse the tail, then attach the current head at the end.
Node* reverseRecursive(Node* head) {
    if (head == nullptr || head->next == nullptr) {
        return head;
    }
    Node* newHead = reverseRecursive(head->next);
    head->next->next = head;
    head->next = nullptr;
    return newHead;
}

void print(Node* head) {
    for (Node* cur = head; cur != nullptr; cur = cur->next) {
        std::cout << cur->value;
        if (cur->next) std::cout << " -> ";
    }
    std::cout << '\n';
}

void freeList(Node* head) {
    while (head) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    // Build 1 -> 2 -> 3 -> 4
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(4);

    Node* a = reverseIterative(head);
    print(a);                 // 4 -> 3 -> 2 -> 1
    Node* b = reverseRecursive(a);
    print(b);                 // 1 -> 2 -> 3 -> 4
    freeList(b);

    // Edge case: empty list.
    print(reverseIterative(nullptr));
    return 0;
}
