    if (argc != 3) {
        std::fprintf(stderr, "usage: %s <src> <dst>\n", argv[0]);
        return 1;
    }
    std::FILE* in = std::fopen(argv[1], "rb");
    if (!in) { std::perror("open src"); return 2; }
    std::FILE* out = std::fopen(argv[2], "wb");
    if (!out) { std::fclose(in); std::perror("open dst"); return 3; }

    unsigned char buf[8192];
    uint64_t total = 0;
    size_t n;
    while ((n = std::fread(buf, 1, sizeof buf, in)) > 0) {
        if (std::fwrite(buf, 1, n, out) != n) {
            std::perror("write");
            std::fclose(in); std::fclose(out);
            return 4;
        }
        total += n;
    }
    if (std::ferror(in)) { std::perror("read"); return 5; }

    std::fclose(in);
    std::fclose(out);
    std::printf("copied %llu bytes\n", (unsigned long long)total);
    return 0;
}
