import heapq


def running_medians(stream):
    """Return a list of medians after each number is added."""
    low = []   # max-heap (negated values), holds the smaller half
    high = []  # min-heap, holds the larger half
    medians = []

    for value in stream:
        # Push onto the correct side.
        if not low or value <= -low[0]:
            heapq.heappush(low, -value)
        else:
            heapq.heappush(high, value)

        # Rebalance so len(low) == len(high) or len(low) == len(high) + 1.
        if len(low) - len(high) > 1:
            heapq.heappush(high, -heapq.heappop(low))
        elif len(high) > len(low):
            heapq.heappush(low, -heapq.heappop(high))

        if len(low) == len(high):
            medians.append((-low[0] + high[0]) / 2.0)
        else:
            medians.append(float(-low[0]))

    return medians


if __name__ == "__main__":
    print(running_medians([5, 15, 1, 3, 8]))   # [5.0, 10.0, 5.0, 4.0, 5.0]
    print(running_medians([]))                 # []
    print(running_medians([2, 2, 2]))          # [2.0, 2.0, 2.0]
