#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), capacity_(capacity) {}

    bool push(const T& value) {
        if (size_ == capacity_) return false;
        data_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    std::optional<T> peek() const {
        if (size_ == 0) return std::nullopt;
        return data_[head_];
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::vector<T> data_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int> buf(3);
    std::cout << std::boolalpha;
    std::cout << buf.push(1) << '\n';  // true
    std::cout << buf.push(2) << '\n';  // true
    std::cout << buf.push(3) << '\n';  // true
    std::cout << buf.push(4) << '\n';  // false (full)
    std::cout << *buf.pop() << '\n';   // 1
    std::cout << buf.push(4) << '\n';  // true (wraps)
    std::cout << *buf.peek() << '\n';  // 2
    std::cout << buf.size() << '\n';   // 3
    return 0;
}
