#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t capacity;
    size_t head;
    size_t size;
} Queue;

Queue *queue_new(size_t capacity) {
    Queue *q = malloc(sizeof(Queue));
    if (!q) return NULL;
    q->data = malloc(capacity * sizeof(int));
    if (!q->data) { free(q); return NULL; }
    q->capacity = capacity;
    q->head = 0;
    q->size = 0;
    return q;
}

void queue_free(Queue *q) {
    if (!q) return;
    free(q->data);
    free(q);
}

bool queue_enqueue(Queue *q, int value) {
    if (q->size == q->capacity) return false;
    q->data[(q->head + q->size) % q->capacity] = value;
    q->size++;
    return true;
}

bool queue_dequeue(Queue *q, int *out) {
    if (q->size == 0) return false;
    *out = q->data[q->head];
    q->head = (q->head + 1) % q->capacity;
    q->size--;
    return true;
}

bool queue_peek(const Queue *q, int *out) {
    if (q->size == 0) return false;
    *out = q->data[q->head];
    return true;
}

int main(void) {
    Queue *q = queue_new(3);
    if (!q) return 1;

    printf("enqueue 1..4: %d %d %d %d\n",
           queue_enqueue(q, 1), queue_enqueue(q, 2),
           queue_enqueue(q, 3), queue_enqueue(q, 4));

    int value;
    printf("peek: %d = %d\n", queue_peek(q, &value), value);
    printf("dequeue: %d = %d\n", queue_dequeue(q, &value), value);
    printf("dequeue: %d = %d\n", queue_dequeue(q, &value), value);

    queue_free(q);
    return 0;
}
