def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring of s."""
    if not s:
        return ""
    best_start, best_len = 0, 1

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - left - 1

    for i in range(len(s)):
        for start, length in (expand(i, i), expand(i, i + 1)):
            if length > best_len:
                best_start, best_len = start, length

    return s[best_start:best_start + best_len]


if __name__ == "__main__":
    cases = ["", "a", "babad", "cbbd", "forgeeksskeegfor", "\u03b1\u03b2\u03b1"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```
This is O(n²) time, O(1) extra space, handles empty and single-character input, and works on any Unicode string since Python compares code points directly.

