#include <condition_variable>
#include <mutex>
#include <queue>
#include <stdexcept>
#include <utility>

 template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {
        if (cap_ == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(T value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return q_.size() < cap_; });
        q_.push(std::move(value));
        not_empty_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return !q_.empty(); });
        T value = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return value;
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mu_);
        return q_.size();
    }

private:
    std::size_t cap_;
    std::queue<T> q_;
    mutable std::mutex mu_;
    std::condition_variable not_full_, not_empty_;
};

#include <cassert>
#include <thread>

int main() {
    BoundedQueue<int> q(4);
    int sum = 0;
    std::thread producer([&] { for (int i = 1; i <= 10; ++i) q.push(i); });
    std::thread consumer([&] { for (int i = 0; i < 10; ++i) sum += q.pop(); });
    producer.join();
    consumer.join();
    assert(sum == 55);
    return 0;
}
```
Locking is via condvars with predicate waits (spurious-wakeup safe). `std::move` avoids copies of `T`, and the zero-capacity constructor rejects a design that would deadlock immediately.

```cpp
#include <cstddef>
#include <cstdint>
#include <new>
#include <vector>

class Arena {
public:
    explicit Arena(std::size_t bytes) : storage_(bytes) {
        base_ = reinterpret_cast<std::uintptr_t>(storage_.data());
        offset_ = (8 - (base_ % 8)) % 8;  // align start to 8 bytes
    }

    void* alloc(std::size_t size, std::size_t align = 8) {
        const std::uintptr_t cur = base_ + offset_;
        const std::size_t pad = (align - (cur % align)) % align;
        if (offset_ + pad + size > storage_.size()) {
            return nullptr;  // caller handles OOM; no exceptions here
        }
        offset_ += pad;
        void* ptr = storage_.data() + offset_;
        offset_ += size;
        return ptr;
    }

    const std::uint8_t* data() const { return storage_.data(); }
    std::size_t used() const { return offset_; }

    void reset() { offset_ = 0; }  // frees everything at once

private:
    std::vector<std::uint8_t> storage_;
    std::uintptr_t base_ = 0;
    std::size_t offset_ = 0;
};

#include <cassert>

int main() {
    Arena a(256);
    void* p1 = a.alloc(16);
    void* p2 = a.alloc(32, 16);
    assert(p1 != nullptr && p2 != nullptr);
    assert(reinterpret_cast<std::uintptr_t>(p2) % 16 == 0);
    void* big = a.alloc(4096);
    assert(big == nullptr);  // capacity exhausted, reported honestly
    a.reset();
    assert(a.used() == 0);
    return 0;
}
```
Every allocation is aligned as requested, the arena returns `nullptr` on exhaustion instead of throwing, and `reset()` reclaims all blocks in O(1) without individual frees.

```rust
use std::collections::VecDeque;
use std::sync::{Arc, Condvar, Mutex};

struct Inner<T> {
    queue: VecDeque<T>,
    capacity: usize,
    closed: bool,
}

pub struct Sender<T> {
    inner: Arc<(Mutex<Inner<T>>, Condvar, Condvar)>,
}

pub struct Receiver<T> {
    inner: Arc<(Mutex<Inner<T>>, Condvar, Condvar)>,
}

pub fn channel<T>(capacity: usize) -> (Sender<T>, Receiver<T>) {
    assert!(capacity > 0, "capacity must be > 0");
    let inner = Arc::new((
        Mutex::new(Inner { queue: VecDeque::new(), capacity, closed: false }),
        Condvar::new(),
        Condvar::new(),
    ));
    (Sender { inner: inner.clone() }, Receiver { inner })
}

impl<T> Sender<T> {
    pub fn send(&self, value: T) -> Result<(), T> {
        let (lock, not_full, not_empty) = &*self.inner;
        let mut g = lock.lock().unwrap();
        while g.queue.len() >= g.capacity {
            if g.closed { return Err(value); }
            g = not_full.wait(g).unwrap();
        }
        g.queue.push_back(value);
        not_empty.notify_one();
        Ok(())
    }
}

impl<T> Receiver<T> {
    pub fn recv(&self) -> Option<T> {
        let (lock, not_full, not_empty) = &*self.inner;
        let mut g = lock.lock().unwrap();
        loop {
            if let Some(v) = g.queue.pop_front() {
                not_full.notify_one();
                return Some(v);
            }
            if g.closed { return None; }
            g = not_empty.wait(g).unwrap();
        }
    }
}

fn main() {
    let (tx, rx) = channel::<i32>(3);
    let handle = std::thread::spawn(move || {
        for i in 1..=10 { tx.send(i).unwrap(); }
    });
    let mut sum = 0;
    for _ in 0..10 { sum += rx.recv().unwrap(); }
    handle.join().unwrap();
    assert_eq!(sum, 55);
}
```
Predicate loops guard against spurious wakeups, a closed flag makes `recv` return `None` instead of hanging, and both sides notify so neither party stalls.

```rust
use std::cmp::Ordering;

/// Returns Ok(index) if found, Err(index) where the value would be inserted.
pub fn binary_search<T: Ord>(slice: &[T], target: &T) -> Result<usize, usize> {
    let (mut lo, mut hi) = (0usize, slice.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;  // avoids overflow
        match slice[mid].cmp(target) {
            Ordering::Less => lo = mid + 1,
            Ordering::Greater => hi = mid,
            Ordering::Equal => return Ok(mid),
        }
    }
    Err(lo)
}

#[cfg(test)]
mod tests {
    use super::binary_search;

    #[test]
    fn finds_present() {
        let v = [1, 3, 5, 7, 9];
        assert_eq!(binary_search(&v, &5), Ok(2));
        assert_eq!(binary_search(&v, &1), Ok(0));
        assert_eq!(binary_search(&v, &9), Ok(4));
    }

    #[test]
    fn reports_insertion_point() {
        let v = [1, 3, 5, 7, 9];
        assert_eq!(binary_search(&v, &0), Err(0));
        assert_eq!(binary_search(&v, &4), Err(2));
        assert_eq!(binary_search(&v, &10), Err(5));
    }

    #[test]
    fn handles_empty() {
        let v: [i32; 0] = [];
        assert_eq!(binary_search(&v, &42), Err(0));
    }
}
```
The mid calculation `lo + (hi - lo) / 2` cannot overflow for large slices, and the result encodes both found and not-found cases so callers can batch-insert without a second scan.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

void print_list(const Node *head) {
    for (const Node *n = head; n != NULL; n = n->next) {
        printf("%d%s", n->value, n->next ? " -> " : "\n");
    }
}

void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    /* empty list */
    if (reverse(NULL) != NULL) {
        fprintf(stderr, "reverse(NULL) should stay NULL\n");
        return 1;
    }

    /* single node */
    Node *one = push(NULL, 42);
    one = reverse(one);
    if (one == NULL || one->value != 42 || one->next != NULL) {
        fprintf(stderr, "single-node reverse failed\n");
        return 1;
    }
    free_list(one);

    /* multi node */
    Node *head = NULL;
    for (int i = 5; i >= 1; --i) {
        head = push(head, i);
    }
    print_list(head);
    head = reverse(head);
    print_list(head);
    free_list(head);
    return 0;
}
```
The loop only rewires `next` pointers, so the reversal is O(n) time and O(1) space. Both edge cases — empty and single-node lists — are checked explicitly, and `free_list` avoids the leak you would get by freeing `head` first.

