#include <algorithm>
#include <cstddef>
#include <iostream>
#include <numeric>
#include <vector>

int main() {
    std::vector<long long> v;
    long long x;
    while (std::cin >> x) v.push_back(x);

    if (v.size() < 3) {
        std::cout << "need at least 3 numbers\n";
        return 0;
    }

    long long lo = *std::min_element(v.begin(), v.end());
    long long hi = *std::max_element(v.begin(), v.end());

    // Remove exactly one occurrence of lo and one of hi.
    std::vector<long long> kept;
    kept.reserve(v.size());
    bool dropped_lo = false, dropped_hi = false;
    for (long long n : v) {
        if (!dropped_lo && n == lo) { dropped_lo = true; continue; }
        if (!dropped_hi && n == hi) { dropped_hi = true; continue; }
        kept.push_back(n);
    }

    if (kept.empty()) {
        std::cout << "no values left\n";
        return 0;
    }

    long long sum = std::accumulate(kept.begin(), kept.end(), 0LL);
    double mean = static_cast<double>(sum) / static_cast<double>(kept.size());
    std::cout << mean << '\n';
    return 0;
}
