/// Luhn check for digit strings. Non-digits make it invalid.
pub fn luhn_ok(number: &str) -> bool {
    let digits: Vec<u32> = match number.chars().map(|c| c.to_digit(10)).collect() {
        Some(d) => d,
        None => return false,
    };
    if digits.is_empty() {
        return false;
    }

    let mut sum = 0u32;
    for (i, &d) in digits.iter().rev().enumerate() {
        let mut val = d;
        if i % 2 == 1 {
            val *= 2;
            if val > 9 {
                val -= 9;
            }
        }
        sum += val;
    }
    sum % 10 == 0
}

fn main() {
    assert!(luhn_ok("79927398713"));
    assert!(!luhn_ok("79927398710"));
    assert!(!luhn_ok(""));
    assert!(luhn_ok("0"));
    assert!(!luhn_ok("12a3"));
    println!("ok");
}
