/// Bounded search for `needle` in a sorted `haystack`.
/// `limit` is the maximum number of probes; returns None if exhausted.
pub fn bounded_search<T: Ord + Copy>(haystack: &[T], needle: T, limit: usize) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = haystack.len(); // exclusive
    let mut probes = 0usize;

    while lo < hi {
        if probes >= limit {
            return None;
        }
        probes += 1;
        let mid = lo + (hi - lo) / 2;
        match haystack[mid].cmp(&needle) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    None
}

fn main() {
    let peers = [3u32, 7, 11, 19, 42, 88];
    assert_eq!(bounded_search(&peers, 42, 10), Some(4));
    assert_eq!(bounded_search(&peers, 4, 10), None);
    assert_eq!(bounded_search(&peers, 3, 0), None);
    assert_eq!(bounded_search(&peers, 88, 1), None);
    println!("ok");
}
```

`limit = 0` always returns `None`; otherwise it stops probing once the budget is spent even if the value is still in range.

