```rust
use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split(|c: char| !c.is_alphanumeric()) {
        if word.is_empty() {
            continue;
        }
        *counts.entry(word.to_lowercase()).or_insert(0) += 1;
    }

    let mut ranked: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count descending, then alphabetically for a stable, deterministic order.
    ranked.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    ranked.truncate(n);
    ranked
}

fn main() {
    let text = "The quick brown fox. The FOX jumps!";
    let top = top_words(text, 2);
    assert_eq!(top[0], ("the".to_string(), 2));
    assert_eq!(top[1], ("fox".to_string(), 2));
    println!("{:?}", top);

    assert!(top_words("", 3).is_empty());
    assert!(top_words("!! ??", 3).is_empty());
}
```

