#include <stdio.h>
#include <ctype.h>
#include <string.h>

static int is_palindrome(const char *s) {
    const char *left = s;
    const char *right = s + strlen(s);
    if (right == s) return 1;
    right--;  /* last real character */

    while (left < right) {
        while (left < right && !isalnum((unsigned char)*left)) left++;
        while (left < right && !isalnum((unsigned char)*right)) right--;
        if (tolower((unsigned char)*left) != tolower((unsigned char)*right)) {
            return 0;
        }
        left++;
        right--;
    }
    return 1;
}

int main(void) {
    const char *cases[] = {
        "",
        "A man, a plan, a canal: Panama",
        "race a car",
        "No 'x' in Nixon",
        "\xe4\xbd\xa0\xe5\xa5\xbd\xe5\xbd\xa0\xe4\xbd\xa0"  /* UTF-8 bytes */
    };
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
        printf("%-35s -> %s\n", cases[i], is_palindrome(cases[i]) ? "yes" : "no");
    }
    return 0;
}
