fn parse_ipv4(s: &str) -> Result<[u8; 4], String> {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return Err(format!("expected 4 octets, got {}", parts.len()));
    }

    let mut octets = [0u8; 4];
    for (i, part) in parts.iter().enumerate() {
        if part.is_empty() || part.len() > 3 {
            return Err(format!("octet {} is empty or too long", i));
        }
        if !part.chars().all(|c| c.is_ascii_digit()) {
            return Err(format!("octet {} is not numeric", i));
        }
        if part.len() > 1 && part.starts_with('0') {
            return Err(format!("octet {} has a leading zero", i));
        }
        octets[i] = part.parse::<u8>().map_err(|_| format!("octet {} out of range", i))?;
    }
    Ok(octets)
}

fn main() {
    assert_eq!(parse_ipv4("192.168.0.1"), Ok([192, 168, 0, 1]));
    assert_eq!(parse_ipv4("0.0.0.0"), Ok([0, 0, 0, 0]));
    assert!(parse_ipv4("256.1.1.1").is_err());
    assert!(parse_ipv4("1.2.3").is_err());
    assert!(parse_ipv4("1.2.3.4.5").is_err());
    assert!(parse_ipv4("01.2.3.4").is_err());
    assert!(parse_ipv4("1.2.3.x").is_err());
    assert!(parse_ipv4("").is_err());
    println!("all tests passed");
}
