#include <iostream>
#include <vector>

std::vector<int> merge_unique(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    size_t i = 0, j = 0;

    auto push = [&out](int v) {
        if (out.empty() || out.back() != v) out.push_back(v);
    };

    while (i < a.size() && j < b.size()) {
        if (a[i] < b[j]) push(a[i++]);
        else if (a[i] > b[j]) push(b[j++]);
        else { push(a[i]); i++; j++; }
    }
    while (i < a.size()) push(a[i++]);
    while (j < b.size()) push(b[j++]);
    return out;
}

int main() {
    auto r = merge_unique({1, 3, 3, 7}, {2, 3, 4, 7, 9});
    for (int v : r) std::cout << v << ' ';
    std::cout << '\n';                       // 1 2 3 4 7 9
    for (size_t k = 1; k < r.size(); k++) assert(r[k - 1] < r[k]);

    assert(merge_unique({}, {}).empty());
    assert(merge_unique({5, 5, 5}, {5}).size() == 1);
    return 0;
}
```

