```python
import re

_TOKEN = re.compile(r"\s*(?:(\d+\.?\d*)|([+\-*/()]))")


def _tokenize(expr: str):
    pos = 0
    tokens = []
    while pos < len(expr):
        m = _TOKEN.match(expr, pos)
        if not m:
            raise ValueError(f"invalid character at position {pos}: {expr[pos]!r}")
        tokens.append(m.group(1) or m.group(2))
        pos = m.end()
    return tokens


def evaluate(expr: str) -> float:
    tokens = _tokenize(expr)
    pos = 0

    def parse_primary() -> float:
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("unexpected end of expression")
        tok = tokens[pos]
        if tok == '(':
            pos += 1
            value = parse_expr()
            if pos >= len(tokens) or tokens[pos] != ')':
                raise ValueError("missing closing parenthesis")
            pos += 1
            return value
        if tok == '-':
            pos += 1
            return -parse_primary()
        if tok in ('+', '*', '/'):
            raise ValueError(f"unexpected operator {tok!r}")
        pos += 1
        return float(tok)

    def parse_term() -> float:
        nonlocal pos
        value = parse_primary()
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            rhs = parse_primary()
            if op == '*':
                value *= rhs
            else:
                value /= rhs
        return value

    def parse_expr() -> float:
        nonlocal pos
        value = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos]!r}")
    return result


if __name__ == "__main__":
    assert evaluate("2 + 3 * 4") == 14
    assert evaluate("(2 + 3) * 4") == 20
    assert evaluate("-3 + 5") == 2
    assert evaluate("10 / 4") == 2.5
    assert evaluate("2 * -3") == -6
    for bad in ["2 +", "(1 + 2", "1 + $2", "1 2"]:
        try:
            evaluate(bad)
            raise AssertionError(f"should have failed: {bad}")
        except ValueError:
            pass
    print("all tests passed")
```

A hand-written recursive-descent parser gives correct precedence without `eval`. Each parse level advances a shared `pos`, and any leftover or malformed token raises `ValueError`.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)       # odd length
        l2, r2 = expand(i, i + 1)   # even length
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    tests = ["", "a", "babad", "cbbd", "forgeeksskeegfor", "한국어"]
    for t in tests:
        print(repr(t), "->", repr(longest_palindrome(t)))
```
`expand` returns the bounds of the palindrome around a center; the loop tries every odd and even center, keeping the widest. Runs in O(n²) time and O(1) extra space. Empty input returns `""`, and Unicode works since Python indexes by code point.

