```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    void push(int value) {
        std::unique_lock<std::mutex> lock(m_);
        not_full_.wait(lock, [this] { return q_.size() < cap_ || closed_; });
        if (closed_) return;
        q_.push(value);
        not_empty_.notify_one();
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(m_);
        not_empty_.wait(lock, [this] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;  // closed and drained
        int v = q_.front();
        q_.pop();
        not_full_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lock(m_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<int> q_;
    std::mutex m_;
    std::condition_variable not_full_, not_empty_;
    bool closed_ = false;
};

#include <iostream>
#include <thread>
int main() {
    BoundedQueue q(2);
    std::thread producer([&] { for (int i = 0; i < 5; ++i) q.push(i); q.close(); });
    std::thread consumer([&] {
        while (auto v = q.pop()) std::cout << *v << '\n';
    });
    producer.join();
    consumer.join();
}
```
`push` blocks while the queue is full, `pop` blocks while empty, and `close()` releases both waiters. The predicate form of `wait` guards against spurious wakeups; the producer sends 0–4 and the consumer prints them in order.

