```rust
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        // `<=` takes from `a` first, so equal elements keep left-before-right order.
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 2, 2], &[2, 3]), vec![1, 2, 2, 2, 3]);
    assert_eq!(merge_sorted(&["a", "c"], &["b"]), vec!["a", "b", "c"]);
    println!("all tests passed");
}
```
`merge_sorted` advances whichever slice holds the smaller current head, choosing `a` on ties to keep stability. Once one side is exhausted the remainder is appended. It works for any `T: Ord + Clone`, including `String` and `&str`.

