#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    void push(int value) {
        if (size_ == N) {
            head_ = (head_ + 1) % N;  // drop oldest
            --size_;
        }
        data_[(head_ + size_) % N] = value;
        ++size_;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4);  // drops 1
    while (!rb.empty()) std::cout << rb.pop().value() << ' ';
    std::cout << '\n';  // 2 3 4
    return 0;
}
```
`head_` points at the oldest element; `push` advances `head_` when full, so insertion never allocates and pop order stays FIFO. `pop` returns `std::optional<int>` so an empty buffer is distinguishable from a stored 0.

