```rust
struct Stack<T> {
    items: Vec<T>,
    capacity: usize,
    max_depth: usize,
}

impl<T> Stack<T> {
    fn new(capacity: usize) -> Self {
        Stack { items: Vec::new(), capacity, max_depth: 0 }
    }

    fn push(&mut self, item: T) -> Result<(), T> {
        if self.items.len() == self.capacity {
            return Err(item);  // return the item so the caller can recover it
        }
        self.items.push(item);
        if self.items.len() > self.max_depth {
            self.max_depth = self.items.len();
        }
        Ok(())
    }

    fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    fn peek(&self) -> Option<&T> {
        self.items.last()
    }

    fn max_depth(&self) -> usize {
        self.max_depth
    }
}

fn main() {
    let mut s = Stack::new(2);
    assert!(s.push(1).is_ok());
    assert!(s.push(2).is_ok());
    assert_eq!(s.push(3), Err(3));
    assert_eq!(s.peek(), Some(&2));
    assert_eq!(s.pop(), Some(2));
    assert_eq!(s.max_depth(), 2);
}
```
Returning the rejected item in `Err` avoids losing user data on overflow, and `max_depth` is updated only on successful pushes so it reflects real occupancy.

