#include <algorithm>
#include <iostream>
#include <vector>

void rotateRight(std::vector<int>& a, int k) {
    int n = static_cast<int>(a.size());
    if (n == 0) return;
    k %= n;
    if (k < 0) k += n;
    std::reverse(a.begin(), a.end());
    std::reverse(a.begin(), a.begin() + k);
    std::reverse(a.begin() + k, a.end());
}

int main() {
    std::vector<int> a = {1, 2, 3, 4, 5, 6, 7};
    rotateRight(a, 3);
    for (int v : a) std::cout << v << ' ';
    std::cout << '\n';
    std::vector<int> b = {1, 2, 3};
    rotateRight(b, 7);
    for (int v : b) std::cout << v << ' ';
    std::cout << '\n';
    return 0;
}
```

`k %= n` folds large rotations down; the three reverses give O(1) extra space. Empty input is a no-op.

