std::optional<uint64_t> fib(unsigned n) {
    std::unordered_map<unsigned, uint64_t> memo;
    memo[0] = 0;
    memo[1] = 1;
    for (unsigned i = 2; i <= n; ++i) {
        uint64_t a = memo[i - 1];
        uint64_t b = memo[i - 2];
        if (a > std::numeric_limits<uint64_t>::max() - b) {
            return std::nullopt; // overflow
        }
        memo[i] = a + b;
    }
    return memo[n];
}

int main() {
    std::cout << fib(10).value() << '\n';  // 55
    std::cout << fib(93).value() << '\n';  // largest n that fits in uint64_t
    std::cout << (fib(94) ? "ok" : "overflow") << '\n'; // overflow
}
