```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *node = malloc(sizeof(Node));
    if (node == NULL) {
        return head;
    }
    node->value = value;
    node->next = head;
    return node;
}

static void print(Node *head) {
    for (; head != NULL; head = head->next) {
        printf("%d%s", head->value, head->next ? " -> " : "\n");
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 5; i >= 1; i--) {
        list = push(list, i);
    }
    print(list);
    list = reverse(list);
    print(list);

    while (list != NULL) {
        Node *next = list->next;
        free(list);
        list = next;
    }
    return 0;
}
```

The loop moves one node at a time: save `next`, point the current node back at `prev`, then advance both pointers. An empty list (or a one-node list) returns correctly without special cases.

