#include <iostream>
#include <stack>
#include <string>
#include <unordered_map>

bool is_balanced(const std::string &s) {
    static const std::unordered_map<char, char> pairs = {
        {')', '('}, {']', '['}, {'}', '{'}
    };
    std::stack<char> open;

    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            open.push(c);
        } else {
            auto it = pairs.find(c);
            if (it == pairs.end()) {
                continue;
            }
            if (open.empty() || open.top() != it->second) {
                return false;
            }
            open.pop();
        }
    }
    return open.empty();
}

int main() {
    const std::string cases[] = {"", "()", "([{}])", "(]", "((", "]", "a(b)c"};
    for (const auto &s : cases) {
        std::cout << (s.empty() ? "<empty>" : s) << " -> "
                  << (is_balanced(s) ? "balanced" : "unbalanced") << '\n';
    }
    return 0;
}
```

Opening brackets are pushed; a closing bracket must match the top of the stack or the string is rejected. Non-bracket characters are ignored, and a leftover stack at the end means unclosed opens. Empty string is balanced by definition.

