import functools
import time


def retry(times=3, delay=0.5):
    def decorate(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    last = exc
                    if attempt < times:
                        time.sleep(delay)
            raise last
        return wrapper
    return decorate


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(times=3, delay=0)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise RuntimeError("not yet")
        return "ok"

    print(flaky(), "after", calls["n"], "attempts")
```

The wrapper retries on any `Exception`, sleeps only between attempts, and re-raises the final error so the caller sees the real failure. `functools.wraps` keeps the decorated function's name and docstring intact.

