#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

static struct Node *push(struct Node *head, int value) {
    struct Node *n = malloc(sizeof *n);
    if (!n) return NULL;
    n->value = value;
    n->next = head;
    return n;
}

static struct Node *reverse(struct Node *head) {
    struct Node *prev = NULL;
    while (head) {
        struct Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print(struct Node *head) {
    for (; head; head = head->next) printf("%d ", head->value);
    putchar('\n');
}

static void free_list(struct Node *head) {
    while (head) {
        struct Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    struct Node *head = NULL;
    for (int i = 1; i <= 5; i++) head = push(head, i);
    print(head);
    head = reverse(head);
    print(head);
    free_list(head);
    return 0;
}
```

The iterative reversal uses the classic three-pointer shuffle and needs no extra allocation. `push` checks `malloc` for failure. `free_list` walks the list and frees each node, so there is no leak at exit.

