```cpp
#include <algorithm>
#include <cstddef>
#include <utility>

template <typename T>
class Stack {
public:
    Stack() = default;

    Stack(const Stack& other) : data_(new T[other.capacity_]), size_(other.size_), capacity_(other.capacity_) {
        std::copy(other.data_, other.data_ + other.size_, data_);
    }

    Stack(Stack&& other) noexcept
        : data_(other.data_), size_(other.size_), capacity_(other.capacity_) {
        other.data_ = nullptr;
        other.size_ = other.capacity_ = 0;
    }

    Stack& operator=(const Stack& other) {
        if (this != &other) {
            Stack tmp(other);
            swap(tmp);
        }
        return *this;
    }

    Stack& operator=(Stack&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = other.data_;
            size_ = other.size_;
            capacity_ = other.capacity_;
            other.data_ = nullptr;
            other.size_ = other.capacity_ = 0;
        }
        return *this;
    }

    ~Stack() { delete[] data_; }

    void push(const T& value) {
        if (size_ == capacity_) grow(capacity_ ? capacity_ * 2 : 1);
        data_[size_++] = value;
    }

    T pop() {
        T value = std::move(data_[--size_]);
        return value;
    }

    std::size_t size() const { return size_; }

    void swap(Stack& other) noexcept {
        std::swap(data_, other.data_);
        std::swap(size_, other.size_);
        std::swap(capacity_, other.capacity_);
    }

private:
    void grow(std::size_t new_cap) {
        T* fresh = new T[new_cap];
        std::move(data_, data_ + size_, fresh);
        delete[] data_;
        data_ = fresh;
        capacity_ = new_cap;
    }

    T* data_ = nullptr;
    std::size_t size_ = 0;
    std::size_t capacity_ = 0;
};
```

Copy-and-swap gives the copy assignment the strong exception guarantee. The move constructor and move assignment null out the source so its destructor is harmless. `grow` uses `std::move` to relocate elements without extra copies.

