```c
#include <stddef.h>

static void reverse_range(int *arr, size_t start, size_t end) {
    while (start < end) {
        int tmp = arr[start];
        arr[start++] = arr[end];
        arr[end--] = tmp;
    }
}

void rotate_left(int *arr, size_t n, size_t k) {
    if (n == 0) return;
    k %= n;
    if (k == 0) return;
    reverse_range(arr, 0, k - 1);
    reverse_range(arr, k, n - 1);
    reverse_range(arr, 0, n - 1);
}
```

The reversal method rotates in O(n) time and O(1) extra space. It normalizes k with `k %= n` so any rotation count is safe. Rotating `{1,2,3,4,5}` left by 2 gives `{3,4,5,1,2}`.

```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let (mut i, mut j) = (0, 0);
    let mut out = Vec::with_capacity(a.len() + b.len());
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}
