```cpp
#include <array>
#include <optional>
#include <cstddef>

template <typename T, std::size_t N>
class RingBuffer {
    std::array<T, N> buf_{};
    std::size_t head_ = 0, tail_ = 0, size_ = 0;
public:
    bool push(const T& value) {
        if (size_ == N) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }
    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }
    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
};
```

Push returns false when full instead of overwriting, so no data is lost silently. Pop returns `std::nullopt` on an empty buffer. Both operations are O(1).

