#include <algorithm>
#include <iostream>
#include <vector>

static std::vector<int> rotateRight(std::vector<int> v, int k) {
    if (v.empty()) return v;
    int n = static_cast<int>(v.size());
    k %= n;
    if (k < 0) k += n;
    std::rotate(v.begin(), v.begin() + (n - k), v.end());
    return v;
}

int main() {
    const std::vector<std::pair<std::vector<int>, int>> cases = {
        {{1, 2, 3, 4, 5, 6, 7}, 3},
        {{1, 2, 3}, 0},
        {{1, 2, 3}, 3},
        {{}, 5},
        {{1, 2}, -1},
    };
    const std::vector<std::vector<int>> expected = {
        {5, 6, 7, 1, 2, 3, 4},
        {1, 2, 3},
        {1, 2, 3},
        {},
        {2, 1},
    };
    for (std::size_t i = 0; i < cases.size(); ++i) {
        auto got = rotateRight(cases[i].first, cases[i].second);
        if (got != expected[i]) {
            std::cerr << "case " << i << " failed\n";
            return 1;
        }
    }
    std::cout << "all cases passed\n";
    return 0;
}
```

