// Returns the index of the first element >= value (std::lower_bound semantics).
// If every element is smaller, returns vec.size().
template <typename T>
std::size_t lowerBoundIndex(const std::vector<T>& vec, const T& value) {
    std::size_t lo = 0;
    std::size_t hi = vec.size();
    while (lo < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (vec[mid] < value) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

int main() {
    const std::vector<int> data{1, 3, 5, 7, 9};
    assert(lowerBoundIndex(data, 5) == 2);   // found at index 2
    assert(lowerBoundIndex(data, 6) == 3);   // would insert before 7
    assert(lowerBoundIndex(data, 0) == 0);   // before everything
    assert(lowerBoundIndex(data, 10) == 5);  // past the end
    assert(lowerBoundIndex(std::vector<int>{}, 4) == 0);  // empty input
    std::cout << "ok" << std::endl;
    return 0;
}
