#include <algorithm>
#include <cassert>
#include <cstddef>
#include <cstring>
#include <iostream>

class FixedBuffer {
public:
    explicit FixedBuffer(std::size_t capacity)
        : size_(capacity), used_(0), data_(new unsigned char[capacity]) {}

    FixedBuffer(const FixedBuffer&) = delete;
    FixedBuffer& operator=(const FixedBuffer&) = delete;

    FixedBuffer(FixedBuffer&& other) noexcept
        : size_(other.size_), used_(other.used_), data_(other.data_) {
        other.data_ = nullptr;
        other.size_ = 0;
        other.used_ = 0;
    }

    FixedBuffer& operator=(FixedBuffer&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = other.data_;
            size_ = other.size_;
            used_ = other.used_;
            other.data_ = nullptr;
            other.size_ = 0;
            other.used_ = 0;
        }
        return *this;
    }

    ~FixedBuffer() { delete[] data_; }

    // Appends up to size_ - used_ bytes; returns how many were written.
    std::size_t append(const unsigned char* src, std::size_t count) {
        const std::size_t room = size_ - used_;
        const std::size_t toWrite = std::min(room, count);
        if (toWrite > 0) {
            std::memcpy(data_ + used_, src, toWrite);
            used_ += toWrite;
        }
        return toWrite;
    }

    std::size_t used() const { return used_; }
    std::size_t capacity() const { return size_; }

private:
    std::size_t size_;
    std::size_t used_;
    unsigned char* data_;
};

int main() {
    FixedBuffer buf(4);
    const unsigned char src[] = {'a', 'b', 'c', 'd', 'e'};
    assert(buf.append(src, 5) == 4);   // clipped to capacity
    assert(buf.used() == 4);
    assert(buf.append(src, 1) == 0);   // already full

    FixedBuffer moved(std::move(buf));
    assert(moved.used() == 4);
    assert(buf.capacity() == 0);       // moved-from is empty
    std::cout << "ok" << std::endl;
    return 0;
}
