use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
pub struct FieldError {
    pub index: usize,
    pub text: String,
}

impl std::fmt::Display for FieldError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "field {} is not an integer: {:?}", self.index, self.text)
    }
}

impl std::error::Error for FieldError {}

/// Splits `line` on commas, ignores empty fields, and parses the rest.
pub fn parse_ints(line: &str) -> Result<Vec<i64>, Box<dyn std::error::Error>> {
    let mut out = Vec::new();
    for (index, raw) in line.split(',').enumerate() {
        let trimmed = raw.trim();
        if trimmed.is_empty() {
            continue;
        }
        match trimmed.parse::<i64>() {
            Ok(n) => out.push(n),
            Err(_: ParseIntError) => {
                return Err(Box::new(FieldError {
                    index,
                    text: trimmed.to_string(),
                }));
            }
        }
    }
    Ok(out)
}

fn main() {
    assert_eq!(parse_ints("1, 2,, 3").unwrap(), vec![1, 2, 3]);
    assert_eq!(parse_ints("").unwrap(), Vec::<i64>::new());
    assert_eq!(parse_ints("-4,5").unwrap(), vec![-4, 5]);
    let err = parse_ints("1, two, 3").unwrap_err().to_string();
    assert!(err.contains("field 1"));
    println!("ok");
}
