use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

pub struct BoundedCounter {
    value: AtomicUsize,
    cap: usize,
}

impl BoundedCounter {
    pub fn new(cap: usize) -> Self {
        Self { value: AtomicUsize::new(0), cap }
    }

    /// Increments if below the cap. Returns true if accepted, false if dropped.
    pub fn try_increment(&self) -> bool {
        let mut current = self.value.load(Ordering::Relaxed);
        loop {
            if current >= self.cap {
                return false;
            }
            match self.value.compare_exchange_weak(
                current,
                current + 1,
                Ordering::AcqRel,
                Ordering::Relaxed,
            ) {
                Ok(_) => return true,
                Err(observed) => current = observed,
            }
        }
    }

    pub fn value(&self) -> usize {
        self.value.load(Ordering::Acquire)
    }
}

fn main() {
    let counter = Arc::new(BoundedCounter::new(1000));
    let mut handles = Vec::new();
    for _ in 0..8 {
        let c = Arc::clone(&counter);
        handles.push(thread::spawn(move || {
            let mut accepted = 0usize;
            for _ in 0..500 {
                if c.try_increment() {
                    accepted += 1;
                }
            }
            accepted
        }));
    }
    let accepted: usize = handles.into_iter().map(|h| h.join().unwrap()).sum();
    assert_eq!(accepted, 1000);       // exactly the cap was accepted
    assert_eq!(counter.value(), 1000);
    assert!(!counter.try_increment()); // full now
    println!("ok");
}
