```cpp
#include <cstdint>
#include <iostream>
#include <limits>

bool is_palindrome(std::int64_t x) {
    if (x < 0) return false;               // negative numbers never match reversed digits
    if (x != 0 && x % 10 == 0) return false; // trailing zero cannot be a leading digit
    std::int64_t rev = 0;
    // Rebuild the reverse and stop when we pass the halfway point to avoid overflow.
    while (x > rev) {
        rev = rev * 10 + x % 10;
        x /= 10;
    }
    // Even length: x == rev. Odd length: drop the middle digit of rev.
    return x == rev || x == rev / 10;
}

int main() {
    const std::int64_t cases[][2] = {
        {121, 1}, {0, 1}, {10, 0}, {-121, 0},
        {12321, 1}, {123321, 1}, {12345, 0},
        {std::numeric_limits<std::int64_t>::max(), 0},
    };
    for (auto& c : cases) {
        bool got = is_palindrome(c[0]);
        if (got != static_cast<bool>(c[1])) {
            std::cerr << "failed on " << c[0] << "\n";
            return 1;
        }
    }
    std::cout << "all cases passed\n";
}
```

The `x > rev` loop stops at the middle, so `rev` never exceeds the input magnitude and cannot overflow. The `x % 10 == 0` guard rejects numbers like `10` whose reverse would drop digits.

