using Interval = std::pair<int, int>;

std::vector<Interval> merge_intervals(std::vector<Interval> in) {
    if (in.empty()) return {};
    std::sort(in.begin(), in.end());
    std::vector<Interval> out{in[0]};
    for (std::size_t i = 1; i < in.size(); ++i) {
        if (in[i].first <= out.back().second) {
            out.back().second = std::max(out.back().second, in[i].second);
        } else {
            out.push_back(in[i]);
        }
    }
    return out;
}

std::vector<Interval> insert_interval(std::vector<Interval> in, Interval add) {
    in.push_back(add);
    return merge_intervals(std::move(in));
}

int main() {
    auto m = merge_intervals({{1, 3}, {2, 6}, {8, 10}, {15, 18}});
    if (m != std::vector<Interval>{{1, 6}, {8, 10}, {15, 18}}) return 1;

    *// Touching intervals (2,4) and (4,5) must join.*/
    auto t = merge_intervals({{2, 4}, {4, 5}});
    if (t != std::vector<Interval>{{2, 5}}) return 1;

    *// Nested: (1,10) swallows (2,3).*/
    auto n = merge_intervals({{1, 10}, {2, 3}});
    if (n != std::vector<Interval>{{1, 10}}) return 1;

    auto ins = insert_interval({{1, 3}, {6, 9}}, {2, 5});
    if (ins != std::vector<Interval>{{1, 5}, {6, 9}}) return 1;

    std::cout << "all cases passed\n";
}
