use std::collections::BTreeMap;

#[derive(Debug, PartialEq)]
pub enum ParseError {
    MissingEquals(String),
    EmptyKey(String),
    DuplicateKey(String),
}

pub fn parse_config(input: &str) -> Result<BTreeMap<String, String>, ParseError> {
    let mut map = BTreeMap::new();
    for raw in input.split(';') {
        let entry = raw.trim();
        if entry.is_empty() {
            continue;
        }
        let (key, value) = entry
            .split_once('=')
            .ok_or_else(|| ParseError::MissingEquals(entry.to_string()))?;
        let key = key.trim();
        if key.is_empty() {
            return Err(ParseError::EmptyKey(entry.to_string()));
        }
        if map.insert(key.to_string(), value.trim().to_string()).is_some() {
            return Err(ParseError::DuplicateKey(key.to_string()));
        }
    }
    Ok(map)
}

fn main() {
    let cfg = parse_config("host=localhost; ;port=8080;host=other").unwrap_err();
    assert_eq!(cfg, ParseError::DuplicateKey("host".to_string()));

    let ok = parse_config("b=2; a=1").unwrap();
    for (k, v) in &ok {
        println!("{k}={v}"); // BTreeMap iterates in sorted key order
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rejects_bad_entries() {
