```c
#include <stdio.h>
#include <stdlib.h>

static int reverse_file(const char *path) {
    FILE *f = fopen(path, "r+b");
    if (!f) return -1;

    if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return -1; }
    long len = ftell(f);
    if (len < 0) { fclose(f); return -1; }

    for (long i = 0, j = len - 1; i < j; ++i, --j) {
        unsigned char a, b;
        if (fseek(f, i, SEEK_SET) != 0 || fread(&a, 1, 1, f) != 1) { fclose(f); return -1; }
        if (fseek(f, j, SEEK_SET) != 0 || fread(&b, 1, 1, f) != 1) { fclose(f); return -1; }
        a ^= b; b ^= a; a ^= b; // swap via XOR
        if (fseek(f, i, SEEK_SET) != 0 || fwrite(&a, 1, 1, f) != 1) { fclose(f); return -1; }
        if (fseek(f, j, SEEK_SET) != 0 || fwrite(&b, 1, 1, f) != 1) { fclose(f); return -1; }
    }
    fflush(f);
    fclose(f);
    return 0;
}

int main(void) {
    const char *path = "revtest.bin";
    const char *data = "abcdefg"; // odd length, 7 bytes
    FILE *w = fopen(path, "wb");
    if (!w) return 1;
    fwrite(data, 1, 7, w);
    fclose(w);

    if (reverse_file(path) != 0) { remove(path); return 1; }

    unsigned char buf[16];
    FILE *r = fopen(path, "rb");
    size_t n = fread(buf, 1, sizeof buf, r);
    fclose(r);
    remove(path);

    if (n != 7) return 1;
    const char *expect = "gfedcba";
    for (size_t i = 0; i < 7; ++i) {
        if (buf[i] != (unsigned char)expect[i]) return 1;
    }
    printf("reversed correctly: %.*s\n", (int)n, buf);
    return 0;
}
```

The `i < j` loop naturally leaves the middle byte of an odd-length file untouched. XOR swapping avoids a temp variable, and every seek/read/write is checked so a short file or I/O error returns early instead of corrupting data.

