/// Encode bytes as (value, run_length) pairs.
fn encode(input: &[u8]) -> Vec<(u8, u32)> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < input.len() {
        let byte = input[i];
        let mut count: u32 = 1;
        while i + (count as usize) < input.len()
            && input[i + count as usize] == byte
            && count < u32::MAX
        {
            count += 1;
        }
        out.push((byte, count));
        i += count as usize;
    }
    out
}

fn decode(pairs: &[(u8, u32)]) -> Vec<u8> {
    let mut out = Vec::new();
    for &(byte, count) in pairs {
        out.extend(std::iter::repeat(byte).take(count as usize));
    }
    out
}

fn main() {
    let data = b"aaabbbccccd";
    let enc = encode(data);
    // Empty input must yield an empty encoding.
    assert!(encode(b"").is_empty());
    assert_eq!(enc, vec![(b'a', 3), (b'b', 3), (b'c', 4), (b'd', 1)]);
    assert_eq!(decode(&enc), data);

    let round = b"\x00\x00\xff\xff\xff";
    assert_eq!(decode(&encode(round)), round);
    println!("pairs={:?}", enc);
}
