use std::mem::MaybeUninit;

/// Fixed-capacity ring buffer. Pushing into a full buffer overwrites
/// the oldest element.
pub struct RingBuffer<T, const N: usize> {
    slots: [MaybeUninit<T>; N],
    head: usize,
    len: usize,
}

impl<T, const N: usize> RingBuffer<T, N> {
    pub fn new() -> Self {
        assert!(N > 0, "capacity must be non-zero");
        Self {
            slots: unsafe { MaybeUninit::uninit().assume_init() },
            head: 0,
            len: 0,
        }
    }

    pub fn push(&mut self, value: T) {
        let tail = (self.head + self.len) % N;
        if self.len == N {
            // Overwrite oldest without dropping the slot we are reusing.
            let old = std::mem::replace(&mut self.slots[self.head], MaybeUninit::new(value));
            unsafe { old.assume_init_drop() };
            self.head = (self.head + 1) % N;
        } else {
            self.slots[tail].write(value);
            self.len += 1;
        }
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        let value = unsafe { self.slots[self.head].assume_init_read() };
        self.head = (self.head + 1) % N;
        self.len -= 1;
        Some(value)
    }
}

impl<T, const N: usize> Drop for RingBuffer<T, N> {
    fn drop(&mut self) {
        while self.pop().is_some() {}
    }
}

fn main() {
    let mut rb: RingBuffer<i32, 3> = RingBuffer::new();
    rb.push(1);
    rb.push(2);
    rb.push(3);
    rb.push(4); // overwrites 1
    assert_eq!(rb.pop(), Some(2));
    assert_eq!(rb.pop(), Some(3));
    assert_eq!(rb.pop(), Some(4));
    assert_eq!(rb.pop(), None);
    println!("ring buffer ok");
}
