#include <cstdint>
#include <iostream>
#include <stdexcept>

constexpr std::int64_t MOD = 1000000007;

// Returns {F(n), F(n+1)} modulo MOD.
std::pair<std::int64_t, std::int64_t> fib_pair(std::uint64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    std::int64_t c = (a * ((2 * b % MOD) - a + MOD)) % MOD;
    std::int64_t d = (a * a + b * b) % MOD;
    if (n & 1) return {d, (c + d) % MOD};
    return {c, d};
}

std::int64_t fib_mod(std::uint64_t n) { return fib_pair(n).first; }

int main() {
    // Cross-check fast doubling against iterative addition.
    std::int64_t x = 0, y = 1;
    for (std::uint64_t i = 0; i < 90; ++i) {
        if (fib_mod(i) != x) {
            std::cerr << "mismatch at n=" << i << "\n";
            return 1;
        }
        std::int64_t next = (x + y) % MOD;
        x = y;
        y = next;
    }
    std::cout << "F(90) mod p = " << fib_mod(90) << "\n";
    return 0;
}
