#include <vector>
#include <cassert>
#include <iostream>

int binarySearch(const std::vector<int>& arr, int target) {
    int lo = 0, hi = static_cast<int>(arr.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;   // avoids overflow
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> a = {1, 3, 5, 7, 9, 11};
    assert(binarySearch(a, 7) == 3);
    assert(binarySearch(a, 1) == 0);
    assert(binarySearch(a, 11) == 5);
    assert(binarySearch(a, 4) == -1);
    assert(binarySearch({}, 5) == -1);
    std::cout << "ok\n";
    return 0;
}
```

`lo + (hi - lo) / 2` prevents integer overflow on large inputs, and the empty vector returns -1 because the loop never runs.

