#include <cmath>
#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

int main() {
    std::vector<long double> values;
    long double x;
    while (std::cin >> x) {
        values.push_back(x);
    }
    if (values.empty()) {
        std::cout << "no data\n";
        return 0;
    }

    long double sum = 0.0L;
    for (long double v : values) sum += v;
    const long double mean = sum / static_cast<long double>(values.size());

    long double sq = 0.0L;
    for (long double v : values) {
        const long double d = v - mean;
        sq += d * d;
    }
    const long double variance = sq / static_cast<long double>(values.size());

    std::cout << std::fixed << std::setprecision(6)
              << "count " << values.size() << '\n'
              << "mean " << mean << '\n'
              << "stddev " << std::sqrt(variance) << '\n';
    return 0;
}
```
Values are accumulated in `long double` to reduce cancellation error on the variance. The stddev uses the two-pass form (`sum of (v-mean)^2`), which is more numerically stable than the `E[x^2] - E[x]^2` shortcut. If the input is empty the program reports `no data` instead of dividing by zero. Compile with `g++ -std=c++17 -O2 -o stats stats.cpp`.

