```python
from collections import OrderedDict
from typing import Any, Optional


class LRUCache:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: "OrderedDict[Any, Any]" = OrderedDict()

    def get(self, key: Any) -> Optional[Any]:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: Any, value: Any) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1        # refreshes 'a'
    c.put("c", 3)                 # evicts 'b'
    assert c.get("b") is None
    assert c.get("c") == 3
    c.put("c", 30)                # update keeps 'c' newest
    assert c.get("c") == 30
    print("ok")
```
`OrderedDict` keeps insertion order and `move_to_end` is O(1), so both operations are constant time. The most-recently-used entry is kept at the end; eviction pops from the front with `last=False`. Updating an existing key also moves it to the end, matching standard LRU semantics. `get` uses the `None` sentinel, which is fine here since no stored value is `None`; if arbitrary values including `None` were expected you'd use a `__contains__` check instead.

```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s FILE\n", argv[0]);
        return 2;
    }

    FILE *fp = fopen(argv[1], "rb");
    if (fp == NULL) {
        perror(argv[1]);
        return 1;
    }

    unsigned long lines = 0, words = 0, bytes = 0;
    int c;
    int in_word = 0;

    while ((c = fgetc(fp)) != EOF) {
        bytes++;
        if (c == '\n') lines++;
        if (isspace((unsigned char)c)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            words++;
        }
    }

    if (ferror(fp)) {
        perror(argv[1]);
        fclose(fp);
        return 1;
    }
    fclose(fp);

    printf("%lu %lu %lu %s\n", lines, words, bytes, argv[1]);
    return 0;
}
```
The file is opened in binary mode so byte counts are exact even on platforms that translate newlines. The word counter uses a `in_word` flag so each run of non-space characters counts once. `c` is cast to `unsigned char` before `isspace` to avoid undefined behavior on negative `char` values. `ferror` is checked after the loop so a mid-read failure is reported rather than silently producing a wrong count. Compile with `gcc -O2 -Wall -o mywc mywc.c`.

```rust
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);

    while i < a.len() && j < b.len() {
        // On ties take from `a` so the left slice is stable/authoritative.
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    }

    #[test]
    fn empty_inputs() {
        assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
        assert_eq!(merge_sorted(&[1], &[]), vec![1]);
    }

    #[test]
    fn ties_prefer_left() {
        assert_eq!(merge_sorted(&[2, 2], &[2]), vec![2, 2, 2]);
    }
}
```
The loop compares with `<=` so an element equal in both slices comes from `a`, giving left-preference on ties. `with_capacity` avoids reallocations; the trailing `extend_from_slice` copies whatever remains in the longer input in one shot, which is correct because both inputs are already sorted. `T: Ord + Clone` is the minimum bound; if you want to move owned values instead you'd take `Vec<T>` by value and use `into_iter`. Run the tests with `cargo test`.

