import os
import sys
import time
from pathlib import Path


def snapshot(root: Path):
    """Return the set of file paths currently under root (recursive)."""
    return {p for p in root.rglob("*") if p.is_file()}


def main() -> int:
    if len(sys.argv) != 2:
        print("usage: watch.py <directory>", file=sys.stderr)
        return 2
    root = Path(sys.argv[1])
    if not root.is_dir():
        print(f"not a directory: {root}", file=sys.stderr)
        return 2

    seen = snapshot(root)
    print(f"watching {root} ({len(seen)} existing files)", flush=True)

    try:
        while True:
            time.sleep(1.0)
            current = snapshot(root)
            for path in sorted(current - seen):
                print(path, flush=True)
            seen = current
    except KeyboardInterrupt:
        print("\nstopped", file=sys.stderr)
        return 0


if __name__ == "__main__":
    raise SystemExit(main())
```
It records the initial set of files and then every second diffs the current recursive listing against it, printing only additions. `flush=True` makes output appear immediately even when piped. This is deliberately minimal: polling misses files created and deleted within a one-second window and, if a file is being written, it may print while the write is still in progress. Bumping the interval trades latency for CPU. For robust event-driven behavior you'd want `watchdog` via inotify/FSEvents, but that's outside the stdlib. Run with `python watch.py ./inbox`.

