std::vector<int> rotate_left(std::vector<int> v, int k) {
    const int n = static_cast<int>(v.size());
    if (n == 0) return v;
    k %= n;
    if (k < 0) k += n;
    std::reverse(v.begin(), v.begin() + k);
    std::reverse(v.begin() + k, v.end());
    std::reverse(v.begin(), v.end());
    return v;
}

