pub fn longest_common_prefix(words: &[String]) -> String {
    let first = match words.first() {
        Some(w) => w,
        None => return String::new(),
    };
    let mut len = first.len();
    for word in &words[1..] {
        while !word.as_bytes().starts_with(&first.as_bytes()[..len]) {
            if len == 0 {
                return String::new();
            }
            len -= 1;
        }
    }
    first[..len].to_string()
}

