class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._data = [None] * capacity
        self._capacity = capacity
        self._size = 0
        self._head = 0  # index of oldest element

    def push(self, value):
        if self._size == self._capacity:
            self._data[self._head] = value
            self._head = (self._head + 1) % self._capacity
        else:
            idx = (self._head + self._size) % self._capacity
            self._data[idx] = value
            self._size += 1

    def pop(self):
        if self._size == 0:
            return None
        value = self._data[self._head]
        self._head = (self._head + 1) % self._capacity
        self._size -= 1
        return value

    def peek(self):
        return None if self._size == 0 else self._data[self._head]


if __name__ == "__main__":
    rb = RingBuffer(3)
    assert rb.pop() is None and rb.peek() is None
    for v in (1, 2, 3, 4):
        rb.push(v)
    assert rb.peek() == 2
    assert [rb.pop(), rb.pop(), rb.pop(), rb.pop()] == [2, 3, 4, None]
    print("ok")
```

