```rust
use std::collections::HashMap;

pub struct LruCache<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    order: Vec<K>, // front = least recently used
}

impl<K: Eq + std::hash::Hash + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache { cap, map: HashMap::new(), order: Vec::new() }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        if self.map.contains_key(key) {
            self.touch(key);
        }
        self.map.get(key)
    }

    pub fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            self.touch(&key);
            self.map.insert(key, value);
            return;
        }
        if self.map.len() == self.cap {
            if let Some(old) = self.order.first().cloned() {
                self.order.remove(0);
                self.map.remove(&old);
            }
        }
        self.order.push(key.clone());
        self.map.insert(key, value);
    }

    fn touch(&mut self, key: &K) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            let k = self.order.remove(pos);
            self.order.push(k);
        }
    }

    pub fn len(&self) -> usize { self.map.len() }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put("a", 1); c.put("b", 2);
    assert_eq!(c.get(&"a"), Some(&1));
    c.put("c", 3);          // evicts "b"
    assert_eq!(c.get(&"b"), None);
    assert_eq!(c.get(&"c"), Some(&3));
    assert_eq!(c.len(), 2);
    println!("ok");
}
```
`put` handles the update-existing case separately so it never evicts on a hit. `Vec::remove` is O(n), fine for small capacities; swap to a doubly linked list if you need O(1).

