#[derive(Debug, PartialEq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub pre: Option<String>,
    pub build: Option<String>,
}

pub fn parse_semver(s: &str) -> Result<Version, String> {
    let (core, build) = match s.split_once('+') {
        Some((c, b)) => (c, Some(b.to_string())),
        None => (s, None),
    };
    let (core, pre) = match core.split_once('-') {
        Some((c, p)) => (c, Some(p.to_string())),
        None => (core, None),
    };

    let nums: Vec<&str> = core.split('.').collect();
    if nums.len() != 3 {
        return Err(format!("expected major.minor.patch, got {core:?}"));
    }
    let mut parts = [0u64; 3];
    for (i, n) in nums.iter().enumerate() {
        parts[i] = n.parse().map_err(|_| format!("bad number {n:?}"))?;
    }

    Ok(Version { major: parts[0], minor: parts[1], patch: parts[2], pre, build })
}

fn main() {
    let v = parse_semver("1.2.3-alpha.1+build.42").unwrap();
    assert_eq!(v.major, 1);
    assert_eq!(v.pre.as_deref(), Some("alpha.1"));
    assert_eq!(v.build.as_deref(), Some("build.42"));
    assert!(parse_semver("1.2").is_err());
    assert!(parse_semver("1.x.3").is_err());
    println!("ok");
}
```
Splitting build first then pre avoids confusing a `-` inside build metadata with the prerelease separator, which matches the spec's precedence: `major.minor.patch-pre+build`.

