#include <stddef.h>
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;
    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    printf("%s\n", a);           /* olleh */

    char b[] = "";
    reverse_in_place(b);          /* no-op, length 0 */
    printf("[%s]\n", b);

    char c[] = "ab";
    reverse_in_place(c);
    printf("%s\n", c);           /* ba */
    return 0;
}
```
The `i < j` condition stops the two indices crossing, so the middle character of an odd-length string is never swapped with itself. `char a[] = "hello"` (not `char *a`) is required because string literals are read-only.

```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

 template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t cap) : cap_(cap) {}

    void push(T value) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [&] { return q_.size() < cap_; });
        q_.push(std::move(value));
        lk.unlock();
        not_empty_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [&] { return !q_.empty(); });
        T value = std::move(q_.front());
        q_.pop();
        lk.unlock();
        not_full_.notify_one();
        return value;
    }

    std::optional<T> try_pop() {
        std::unique_lock<std::mutex> lk(m_);
        if (q_.empty()) return std::nullopt;
        T value = std::move(q_.front());
        q_.pop();
        lk.unlock();
        not_full_.notify_one();
        return value;
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lk(m_);
        return q_.size();
    }

private:
    std::size_t cap_;
    std::queue<T> q_;
    mutable std::mutex m_;
    std::condition_variable not_full_, not_empty_;
};
```
Both waits use a predicate lambda, so spurious wakeups re-check the condition instead of popping an empty queue. `notify_one` is called *after* unlocking, which avoids waking a waiter that then blocks on the still-held mutex.

```python
def fib(n: int) -> int:
    """Return the nth Fibonacci number (F(0)=0, F(1)=1) via fast doubling."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def fd(k: int) -> tuple[int, int]:
        # returns (F(k), F(k+1))
        if k == 0:
            return (0, 1)
        a, b = fd(k >> 1)
        c = a * (2 * b - a)   # F(2k)
        d = a * a + b * b     # F(2k+1)
        if k & 1:
            return (d, c + d)
        return (c, d)

    return fd(n)[0]


if __name__ == "__main__":
    assert fib(0) == 0
    assert fib(1) == 1
    assert fib(10) == 55
    assert fib(50) == 12586269025
    assert fib(100) == 354224848179261915075
    assert fib(300) == 222232244629420445529739893461909967206666939096499764990979600
    for bad in (-1, -7):
        try:
            fib(bad)
        except ValueError:
            pass
        else:
            raise AssertionError("expected ValueError")
    print("ok")
```

`fib` is O(log n) time and O(log n) stack depth, handles huge inputs via Python's arbitrary-precision ints, and rejects negatives with `ValueError`.

```cpp
#pragma once
#include <condition_variable>
#include <deque>
#include <mutex>
#include <optional>
#include <stdexcept>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    BoundedQueue(const BoundedQueue&) = delete;
    BoundedQueue& operator=(const BoundedQueue&) = delete;

    // Blocks while full. Returns false if the queue was closed.
    bool push(T value) {
        std::unique_lock<std::mutex> lk(mu_);
        not_full_.wait(lk, [&] { return closed_ || q_.size() < capacity_; });
        if (closed_) return false;
        q_.push_back(std::move(value));
        lk.unlock();
        not_empty_.notify_one();
        return true;
    }

    // Blocks while empty. nullopt once closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lk(mu_);
        not_empty_.wait(lk, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;
        T value = std::move(q_.front());
        q_.pop_front();
        lk.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lk(mu_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lk(mu_);
        return q_.size();
    }

private:
    mutable std::mutex mu_;
    std::condition_variable not_full_, not_empty_;
    std::deque<T> q_;
    std::size_t capacity_;
    bool closed_ = false;
};
```

`push` blocks on a full queue, `pop` blocks on empty; `close()` wakes everything and lets `pop` drain remaining items before returning `nullopt`. Move-only `T` (e.g. `std::unique_ptr`) is supported.

```cpp
#include <cassert>
#include <iostream>
#include <list>
#include <optional>
#include <stdexcept>
#include <unordered_map>

template <typename K, typename V>
class LruCache {
public:
    explicit LruCache(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    std::optional<V> get(const K& key) {
        auto it = index_.find(key);
        if (it == index_.end()) return std::nullopt;
        order_.splice(order_.begin(), order_, it->second); // move to front
        return it->second->second;
    }

    void put(const K& key, V value) {
        auto it = index_.find(key);
        if (it != index_.end()) {
            it->second->second = std::move(value);
            order_.splice(order_.begin(), order_, it->second);
            return;
        }
        if (order_.size() == capacity_) {
            index_.erase(order_.back().first);
            order_.pop_back();
        }
        order_.emplace_front(key, std::move(value));
        index_[key] = order_.begin();
    }

    std::size_t size() const { return order_.size(); }

private:
    std::size_t capacity_;
    std::list<std::pair<K, V>> order_; // front = most recent
    std::unordered_map<K, typename std::list<std::pair<K, V>>::iterator> index_;
};

int main() {
    LruCache<std::string, int> cache(2);
    cache.put("a", 1);
    cache.put("b", 2);
    assert(cache.get("a") == 1);   // "a" now most recent
    cache.put("c", 3);             // evicts "b"
    assert(!cache.get("b").has_value());
    assert(cache.get("a") == 1);
    assert(cache.get("c") == 3);
    cache.put("a", 10);            // update in place
    assert(cache.get("a") == 10);
    assert(cache.size() == 2);
    std::cout << "ok\n";
}
```

`get` and `put` are O(1) amortized. `get` promotes to most-recent; eviction removes the list tail when capacity is exceeded; re-putting an existing key updates the value without growing the map.

