    #[test]
    fn basic() {
        let c = word_counts("the the THE");
        assert_eq!(c.get("the"), Some(&3));
    }

    #[test]
    fn punctuation_and_empty() {
        assert!(word_counts("").is_empty());
        assert!(word_counts("   ...  ").is_empty());
        let c = word_counts("fox, fox! (fox)");
        assert_eq!(c.get("fox"), Some(&3));
    }

