Use `flat_map(|c| c.to_lowercase())` rather than `to_ascii_lowercase` so accented letters fold correctly. Apostrophes are preserved so `don't` stays one token; everything else non-alphanumeric is dropped. Empty/whitespace-only input yields an empty map.

```rust
use std::collections::VecDeque;

#[derive(Debug, Clone)]
pub struct RingBuffer<T> {
    inner: VecDeque<T>,
    capacity: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        Self { inner: VecDeque::with_capacity(capacity), capacity }
    }

    /// Pushes onto the back; if full, evicts and returns the oldest element.
    pub fn push_back(&mut self, value: T) -> Option<T> {
        let evicted = if self.inner.len() == self.capacity {
            self.inner.pop_front()
        } else {
            None
        };
        self.inner.push_back(value);
        evicted
    }

    pub fn len(&self) -> usize { self.inner.len() }
    pub fn is_empty(&self) -> bool { self.inner.is_empty() }
    pub fn iter(&self) -> impl Iterator<Item = &T> { self.inner.iter() }
}

impl<T> IntoIterator for RingBuffer<T> {
    type Item = T;
    type IntoIter = std::collections::vec_deque::IntoIter<T>;
    fn into_iter(self) -> Self::IntoIter { self.inner.into_iter() }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    assert_eq!(rb.push_back(1), None);
    assert_eq!(rb.push_back(2), None);
    assert_eq!(rb.push_back(3), None);
    assert_eq!(rb.push_back(4), Some(1));
    assert_eq!(rb.iter().copied().collect::<Vec<_>>(), vec![2, 3, 4]);
    println!("ok");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn evicts_oldest() {
        let mut rb = RingBuffer::new(2);
        rb.push_back("a");
        rb.push_back("b");
        assert_eq!(rb.push_back("c"), Some("a"));
        assert_eq!(rb.iter().collect::<Vec<_>>(), vec![&"b", &"c"]);
    }

    #[test]
    fn empty_buffer() {
        let rb: RingBuffer<i32> = RingBuffer::new(4);
        assert!(rb.is_empty());
        assert_eq!(rb.iter().count(), 0);
    }

    #[test]
    fn capacity_one() {
        let mut rb = RingBuffer::new(1);
        assert_eq!(rb.push_back(1), None);
        assert_eq!(rb.push_back(2), Some(1));
        assert_eq!(rb.len(), 1);
    }
}
```

Order is oldest-to-newest. `push_back` returns the evicted element as `Option<T>` so callers can observe loss; `IntoIterator` consumes the buffer while `iter()` borrows it.

```c
#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* Reverses s in place. Returns 0 on success, -1 if s is NULL. */
int reverse_string(char *s) {
    if (s == NULL) {
        return -1;
    }
    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0) {
        return 0;
    }
    j -= 1; /* index of the last character */
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
    return 0;
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "a";

    if (reverse_string(NULL) != -1) {
        puts("failed: NULL should return -1");
        return 1;
    }
    if (reverse_string(a) != 0 || strcmp(a, "olleh") != 0) {
        puts("failed on 'hello'");
        return 1;
    }
    if (reverse_string(b) != 0 || strcmp(b, "") != 0) {
        puts("failed on empty string");
        return 1;
    }
    if (reverse_string(c) != 0 || strcmp(c, "a") != 0) {
        puts("failed on single char");
        return 1;
    }
    puts("ok");
    return 0;
}
```

NULL returns `-1` without dereferencing. `strlen` is called once, so the length can't change mid-swap. Empty and single-character strings are no-ops. Note the test uses `char a[] = "hello"` (a mutable array) because string literals are read-only and must not be passed to an in-place reverse.

