```python
def flatten(items):
    out = []
    stack = [iter(items)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, list):
            stack.append(iter(item))
        else:
            out.append(item)
    return out

if __name__ == "__main__":
    assert flatten([1, [2, [3, [4]], 5], 6]) == [1, 2, 3, 4, 5, 6]
    assert flatten([]) == []
    assert flatten([[], [[]], 1]) == [1]
    assert flatten(["a", ["b", ["c"]]]) == ["a", "b", "c"]
    print("all tests passed")
```

The explicit stack avoids recursion limits on deeply nested input, and only `list` instances recurse — tuples and strings pass through unchanged.

