                    cur.push_back('"');
                    ++i;
                } else {
                    in_quotes = false;
                }
            } else {
                cur.push_back(c);
            }
        } else if (c == '"') {
            in_quotes = true;
        } else if (c == ',') {
            fields.push_back(cur);
            cur.clear();
        } else {
            cur.push_back(c);
        }
    }
    fields.push_back(cur);
    return fields;
}

int main() {
    auto f = split_csv("a,\"b,c\",d\"\"e\"");
    for (auto& s : f) std::cout << '[' << s << "]\n";
    return 0;
}
```

A doubled quote inside a quoted field is unescaped to a single `"`, and the final field is pushed after the loop ends.

