fn longest_common_prefix(strs: &[String]) -> String {
    if strs.is_empty() {
        return String::new();
    }
    let first = &strs[0];
    let mut prefix_len = first.len();
    for s in &strs[1..] {
        let mut i = 0;
        let a = first.as_bytes();
        let b = s.as_bytes();
        while i < prefix_len && i < b.len() && a[i] == b[i] {
            i += 1;
        }
        prefix_len = i;
        if prefix_len == 0 {
            return String::new();
        }
    }
    first[..prefix_len].to_string()
}

fn main() {
    let v: Vec<String> = ["flower", "flow", "flight"]
        .iter().map(|s| s.to_string()).collect();
    assert_eq!(longest_common_prefix(&v), "fl");
    assert_eq!(longest_common_prefix(&[]), "");
    let v2: Vec<String> = ["dog", "racecar", "car"]
        .iter().map(|s| s.to_string()).collect();
    assert_eq!(longest_common_prefix(&v2), "");
}
