```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static void print_list(const Node *head) {
    for (const Node *p = head; p != NULL; p = p->next) {
        printf("%d", p->value);
        if (p->next != NULL) printf(" -> ");
    }
    printf("\n");
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int v = 1; v <= 5; v++) {
        head = push(head, v);
    }
    print_list(head);
    head = reverse(head);
    print_list(head);
    head = reverse(NULL); /* empty list stays NULL */
    print_list(head);
    free_list(head);
    return 0;
}
```

The loop rewires each `next` pointer to the previous node, so the reversal is done in O(n) time and O(1) space. `reverse(NULL)` returns `NULL`, which the empty-list check covers.

