#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> maxHeap;                            // lower half
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap; // upper half
    int x;
    while (std::cin >> x) {
        if (maxHeap.empty() || x <= maxHeap.top()) maxHeap.push(x);
        else minHeap.push(x);

        if (maxHeap.size() > minHeap.size() + 1) {
            minHeap.push(maxHeap.top()); maxHeap.pop();
        } else if (minHeap.size() > maxHeap.size()) {
            maxHeap.push(minHeap.top()); minHeap.pop();
        }

        if (maxHeap.size() == minHeap.size())
            std::cout << (maxHeap.top() + minHeap.top()) / 2.0 << '\n';
        else
            std::cout << maxHeap.top() << '\n';
    }
    return 0;
}
```

The lower half lives in a max-heap and the upper half in a min-heap. After each insert we rebalance so the heaps differ by at most one; the median is the larger heap's top, or the average of both tops when sizes match. Runs in O(n log n).

