```cpp
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <vector>

class RingBuffer {
    std::vector<double> data_;
    size_t head_ = 0;
    size_t size_ = 0;
public:
    explicit RingBuffer(size_t capacity) : data_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(double v) {
        data_[head_] = v;
        head_ = (head_ + 1) % data_.size();
        if (size_ < data_.size()) ++size_;
    }

    double sum() const {
        return std::accumulate(data_.begin(), data_.begin() + size_, 0.0);
    }

    size_t size() const { return size_; }
};

int main() {
    RingBuffer rb(3);
    rb.push(1.0); rb.push(2.0); rb.push(3.0);
    if (rb.sum() != 6.0) return 1;
    rb.push(4.0); // overwrites 1.0
    if (rb.sum() != 9.0) return 1;
    if (rb.size() != 3) return 1;
    std::cout << "ring buffer ok\n";
    return 0;
}
```

Once full, `push` overwrites the oldest slot by wrapping `head_` modulo capacity. Summing only the first `size_` elements of the backing vector gives all live values; before the buffer fills, the trailing slots are never counted.

