template <typename T>
T median(std::vector<T> values) {
    if (values.empty())
        throw std::invalid_argument("median of empty vector");
    auto mid = values.begin() + values.size() / 2;
    std::nth_element(values.begin(), mid, values.end());
    T lo = *mid;
    if (values.size() % 2 == 1)
        return lo;
    auto mid2 = values.begin() + values.size() / 2 - 1;
    std::nth_element(values.begin(), mid2, mid);
    return (lo + *mid2) / T(2);
}

int main() {
