from collections.abc import Iterable

def flatten(obj, _seen=None):
    if _seen is None:
        _seen = set()
    if isinstance(obj, (list, tuple)):
        oid = id(obj)
        if oid in _seen:
            raise ValueError("cycle detected")
        _seen.add(oid)
        try:
            for item in obj:
                yield from flatten(item, _seen)
        finally:
            _seen.discard(oid)
    elif obj is None:
        return
    elif isinstance(obj, str) or not isinstance(obj, Iterable):
        yield obj
    else:
        for item in obj:
            yield from flatten(item, _seen)


if __name__ == "__main__":
    assert list(flatten([1, [2, [3, None]], [], 4])) == [1, 2, 3, 4]
    assert list(flatten(None)) == []
    assert list(flatten("ab")) == ["ab"]
    a = [1]
    a.append(a)
    try:
        list(flatten(a))
    except ValueError as e:
        assert str(e) == "cycle detected"
    print(list(flatten([1, (2, [3]), None, 4])))
