#include <cstddef>
#include <iostream>
#include <list>
#include <stdexcept>
#include <unordered_map>

class LRUCache {
public:
    explicit LRUCache(std::size_t cap) : cap_(cap) {
        if (cap == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool get(int key, int& value) {
        auto it = map_.find(key);
        if (it == map_.end()) return false;
        items_.splice(items_.begin(), items_, it->second);
        value = it->second->second;
        return true;
    }

    void put(int key, int value) {
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (map_.size() == cap_) {
            map_.erase(items_.back().first);
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        map_[key] = items_.begin();
    }

private:
    std::size_t cap_;
    std::list<std::pair<int, int>> items_;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> map_;
};

int main() {
    LRUCache c(2);
    c.put(1, 10); c.put(2, 20);
    int v = 0;
    std::cout << c.get(1, v) << " " << v << "\n"; // 1 10
    c.put(3, 30);
    std::cout << c.get(2, v) << "\n"; // 0
}
