import sys
from datetime import datetime

REQUIRED = {"email", "signup_date"}

def validate(path):
    seen = {}
    errors = []
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        if reader.fieldnames is None:
            raise ValueError("empty CSV")
        missing = REQUIRED - set(reader.fieldnames)
        if missing:
            raise ValueError(f"missing columns: {sorted(missing)}")
        for lineno, row in enumerate(reader, start=2):
            email = (row.get("email") or "").strip().lower()
            if not email or "@" not in email:
                errors.append((lineno, "invalid email", email))
            elif email in seen:
                errors.append((lineno, f"duplicate of line {seen[email]}", email))
            else:
                seen[email] = lineno

            raw = (row.get("signup_date") or "").strip()
            try:
                datetime.strptime(raw, "%Y-%m-%d")
            except ValueError:
                errors.append((lineno, "bad date", raw))
    return errors

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: validate_users.py users.csv", file=sys.stderr)
        sys.exit(2)
    found = validate(sys.argv[1])
    for line, reason, value in found:
        print(f"line {line}: {reason}: {value!r}")
    print(f"{len(found)} problem(s) found")
