#include <vector>
#include <stdexcept>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), tail_(0), size_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(double v) {
        if (size_ == data_.size()) {
            throw std::overflow_error("buffer full");
        }
        data_[tail_] = v;
        tail_ = (tail_ + 1) % data_.size();
        ++size_;
    }

    double pop() {
        if (size_ == 0) throw std::underflow_error("buffer empty");
        double v = data_[head_];
        head_ = (head_ + 1) % data_.size();
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return data_.size(); }

private:
    std::vector<double> data_;
    std::size_t head_, tail_, size_;
};

int main() {
    RingBuffer rb(3);
    rb.push(1.0); rb.push(2.0); rb.push(3.0);
    if (rb.pop() != 1.0) return 1;
    rb.push(4.0);
    return rb.size() == 3 ? 0 : 1;
}
