import functools
import random
import time


def retry(attempts=3, base=0.1, cap=5.0, exceptions=(Exception,)):
    def decorate(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            delay = base
            last = None
            for attempt in range(1, attempts + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt == attempts:
                        break
                    time.sleep(min(delay, cap) * (0.5 + random.random()))
                    delay *= 2
            raise last
        return wrapper
    return decorate


@retry(attempts=3, base=0.001)
def flaky(state={"n": 0}):
    state["n"] += 1
    if state["n"] < 3:
        raise ValueError("boom")
    return "done"


