        end++;
    }
    if (*end != '\0') {
        return -1;
    }
    if (errno == ERANGE || v < INT_MIN || v > INT_MAX) {
        return -2;
    }
    *out = (int)v;
    return 0;
}

int main(void) {
    int v;
    printf("%d\n", parse_int("42", &v));
    printf("%d\n", parse_int("  -7 ", &v));
    printf("%d\n", parse_int("12abc", &v));
    printf("%d\n", parse_int("999999999999", &v));
    printf("%d\n", parse_int("", &v));
    return 0;
}
