bool parse_int(const char *s, int *out) {
    if (s == NULL || out == NULL || *s == '\0') return false;
    long value = 0;
    int sign = 1;
    if (*s == '+' || *s == '-') {
        if (*s == '-') sign = -1;
        s++;
    }
    if (*s == '\0') return false;
    for (; *s != '\0'; s++) {
        if (*s < '0' || *s > '9') return false;
        value = value * 10 + (*s - '0');
        if (sign == 1 && value > INT_MAX) return false;
        if (sign == -1 && -value < INT_MIN) return false;
    }
    *out = (int)(sign * value);
    return true;
}

