template <typename T>
std::vector<T> merge_sorted(const std::vector<T> &a, const std::vector<T> &b) {
    std::vector<T> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    out.insert(out.end(), a.begin() + i, a.end());
    out.insert(out.end(), b.begin() + j, b.end());
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5, 7};
    std::vector<int> b{2, 3, 4, 8};
    auto m = merge_sorted(a, b);
    assert((m == std::vector<int>{1, 2, 3, 3, 4, 5, 7, 8}));
    assert(merge_sorted(std::vector<int>{}, std::vector<int>{1}) == std::vector<int>{1});
    return 0;
}
