fn dedup_consecutive<T: PartialEq>(data: &mut [T]) -> usize {
    if data.is_empty() {
        return 0;
    }
    let mut write = 1;
    for read in 1..data.len() {
        if data[read] != data[write - 1] {
            data.swap(write, read);
            write += 1;
        }
    }
    write
}

fn main() {
    let mut v = vec![1, 1, 2, 2, 2, 3, 1];
    let n = dedup_consecutive(&mut v);
    assert_eq!(&v[..n], &[1, 2, 3, 1]);

    let mut empty: Vec<i32> = vec![];
    assert_eq!(dedup_consecutive(&mut empty), 0);

    let mut unicode: Vec<char> = vec!['é', 'é', 'ü'];
    let m = dedup_consecutive(&mut unicode);
    assert_eq!(&unicode[..m], &['é', 'ü']);
}
