use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum ParseError {
    Empty,
    BadInt { token: String, source: ParseIntError },
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::Empty => write!(f, "no numbers found"),
            ParseError::BadInt { token, source } => {
                write!(f, "cannot parse {token:?}: {source}")
            }
        }
    }
}

