fn parse_ints(input: &str) -> Result<Vec<i64>, ParseError> {
    let tokens: Vec<&str> = input.split_whitespace().collect();
    if tokens.is_empty() {
        return Err(ParseError::Empty);
    }
    tokens
        .iter()
        .map(|t| {
            t.parse::<i64>().map_err(|source| ParseError::BadInt {
                token: (*t).to_string(),
                source,
            })
        })
        .collect()
}

fn main() {
    assert_eq!(parse_ints("1 -2 30").unwrap(), vec![1, -2, 30]);
    assert_eq!(parse_ints("  ").unwrap_err().to_string(), "no numbers found");
    let err = parse_ints("4 oops").unwrap_err().to_string();
    assert!(err.contains("oops"));
    assert!(parse_ints("9223372036854775808").is_err());
    println!("ok");
