```python
import functools
import time


def retry(attempts=3, base_delay=0.01, exceptions=(Exception,)):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt < attempts - 1:
                        time.sleep(base_delay * (2 ** attempt))
            raise last
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return calls["n"]

    assert flaky() == 3

    @retry(attempts=2)
    def always():
        raise RuntimeError("boom")

    try:
        always()
    except RuntimeError as e:
        assert str(e) == "boom"
    else:
        raise AssertionError("expected failure")

    print("ok")
```

Backoff is `base_delay * 2**attempt` so waits grow 1×, 2×, 4×. The final attempt does not sleep, and `raise last` re-raises the real exception instead of a wrapper.

