use std::cmp::Reverse;
use std::collections::HashMap;

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Descending by count, then ascending by word for stable output.
    pairs.sort_by_key(|(w, c)| (Reverse(*c), w.clone()));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The quick brown fox. The FOX, the fox!";
    let out = top_words(text, 2);
    assert_eq!(out, vec![("fox".to_string(), 3), ("the".to_string(), 3)]);
    assert!(top_words("", 5).is_empty());
    println!("{:?}", out);
}
