```c
#include <limits.h>
#include <stdio.h>
#include <string.h>

/* Writes into buf (size >= 35 for base 2 + sign + NUL).
 * Returns buf on success, NULL if base out of range or cap too small. */
char *itoa_base(int value, int base, char *buf, size_t cap)
{
    static const char digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";
    char tmp[36];
    int i = 0, neg = 0;
    unsigned int u;

    if (base < 2 || base > 36) return NULL;

    if (value < 0) {
        neg = 1;
        u = (unsigned int)(-(value + 1)) + 1u;  /* safe for INT_MIN */
    } else {
        u = (unsigned int)value;
    }

    do {
        tmp[i++] = digits[u % (unsigned int)base];
        u /= (unsigned int)base;
    } while (u != 0);

    size_t need = (size_t)i + (size_t)neg + 1u;
    if (need > cap) return NULL;

    size_t k = 0;
    if (neg) buf[k++] = '-';
    while (i > 0) buf[k++] = tmp[--i];
    buf[k] = '\0';
    return buf;
}

int main(void)
{
    char buf[40];
    printf("%s\n", itoa_base(-255, 16, buf, sizeof buf));  /* -ff */
    printf("%s\n", itoa_base(INT_MIN, 10, buf, sizeof buf));
    printf("%s\n", itoa_base(35, 36, buf, sizeof buf));    /* z */
    if (itoa_base(1, 1, buf, sizeof buf) != NULL) return 1;
    return 0;
}
```

The `-(value + 1) + 1` trick avoids signed overflow on `INT_MIN`, which a plain `-value` would trigger.

