fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    let mut quote: Option<char> = None;

    for c in s.chars() {
        match quote {
            Some(q) => {
                if c == q {
                    quote = None;
                }
                continue;
            }
            None => {
                if c == '\'' || c == '"' {
                    quote = Some(c);
                    continue;
                }
            }
        }

        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' => {
                if stack.pop() != Some('(') {
                    return false;
                }
            }
            ']' => {
                if stack.pop() != Some('[') {
                    return false;
                }
            }
            '}' => {
                if stack.pop() != Some('{') {
                    return false;
                }
            }
            _ => {}
        }
    }

    stack.is_empty() && quote.is_none()
}

fn main() {
    assert!(is_balanced("fn f(x: (i32, [i32; 3])) {}"));
    assert!(is_balanced("let s = \"(unbalanced\";"));
    assert!(!is_balanced("([)]"));
    assert!(!is_balanced("unclosed("));
    assert!(!is_balanced("\"open"));
    println!("ok");
}
