#include <fcntl.h>
#include <unistd.h>

#include <cstdio>
#include <utility>

class FileDescriptor {
public:
    FileDescriptor() noexcept : fd_(-1) {}

    explicit FileDescriptor(int fd) noexcept : fd_(fd) {}

    ~FileDescriptor() { close_now(); }

    FileDescriptor(const FileDescriptor&) = delete;
    FileDescriptor& operator=(const FileDescriptor&) = delete;

    FileDescriptor(FileDescriptor&& other) noexcept : fd_(other.fd_) {
        other.fd_ = -1;
    }

    FileDescriptor& operator=(FileDescriptor&& other) noexcept {
        if (this != &other) {
            close_now();
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    int get() const noexcept { return fd_; }
    explicit operator bool() const noexcept { return fd_ >= 0; }

private:
    void close_now() noexcept {
        if (fd_ >= 0) {
            ::close(fd_);
            fd_ = -1;
        }
    }

    int fd_;
};

int main()
{
    FileDescriptor fd(::open("/tmp/raii_demo.txt", O_CREAT | O_WRONLY, 0644));
    if (!fd) {
        std::perror("open");
        return 1;
    }

    FileDescriptor moved(std::move(fd));
    if (::write(moved.get(), "hello\n", 6) != 6) {
        std::perror("write");
        return 1;
    }
    // moved closes the fd at end of scope; fd is left -1 and safe.
    return 0;
}
```

Copying is deleted so two objects can never own the same descriptor. Move assignment closes the current fd before taking ownership, preventing leaks and double-close.

