    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

if __name__ == "__main__":
    assert binary_search([], 3) == -1
    assert binary_search([1, 3, 5, 7], 5) == 2
    assert binary_search([1, 3, 5, 7], 0) == -1
    assert binary_search([1, 3, 5, 7], 8) == -1
    print("ok")
```

`lo + (hi - lo) // 2` avoids overflow in languages with fixed-width ints, though Python doesn't need it. Bounds handled: empty list, target below, target above.

```cpp
#include <condition_variable>
#include <mutex>
#include <queue>

template <typename T>
class BoundedQueue {
    std::queue<T> q_;
    std::mutex m_;
    std::condition_variable not_full_, not_empty_;
    size_t cap_;

public:
    explicit BoundedQueue(size_t cap) : cap_(cap) {}

    void push(T value) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [this] { return q_.size() < cap_; });
        q_.push(std::move(value));
        not_empty_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [this] { return !q_.empty(); });
        T value = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return value;
    }
};
```

Both waits use predicates so spurious wakeups are handled. `notify_one` is enough because each push frees exactly one slot and each pop frees exactly one item.

