```cpp
#include <cstddef>
#include <iostream>
#include <stdexcept>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(new int[capacity]), capacity_(capacity), head_(0), tail_(0), size_(0) {}

    ~RingBuffer() { delete[] data_; }

    RingBuffer(const RingBuffer&) = delete;
    RingBuffer& operator=(const RingBuffer&) = delete;

    bool push(int value) {
        if (size_ == capacity_) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity_;
        ++size_;
        return true;
    }

    int pop() {
        if (size_ == 0) throw std::runtime_error("pop from empty ring");
        int value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    int* data_;
    std::size_t capacity_;
    std::size_t head_, tail_, size_;
};

int main() {
    RingBuffer rb(3);
    if (!rb.push(10) || !rb.push(20) || !rb.push(30)) return 1;
    if (rb.push(40)) return 1;                 // full
    if (rb.pop() != 10 || rb.pop() != 20) return 1;
    if (!rb.push(50)) return 1;                // wraps
    while (rb.size() > 0) std::cout << rb.pop() << '\n';  // 30 50
    return 0;
}
```
`head_`/`tail_` wrap with modulo, `size_` distinguishes full from empty, and copy is deleted to avoid a double free of the raw buffer.

```cpp
#include <array>
#include <cstdint>
#include <iostream>

using Matrix = std::array<std::array<std::int64_t, 2>, 2>;
constexpr std::int64_t MOD = 1000000007;

Matrix multiply(const Matrix& a, const Matrix& b) {
    Matrix r{};
    for (int i = 0; i < 2; ++i)
        for (int k = 0; k < 2; ++k)
            for (int j = 0; j < 2; ++j)
                r[i][j] = (r[i][j] + a[i][k] * b[k][j]) % MOD;
    return r;
}

Matrix power(Matrix base, std::uint64_t exp) {
    Matrix result{{{1, 0}, {0, 1}}};  // identity
    while (exp > 0) {
        if (exp & 1u) result = multiply(result, base);
        base = multiply(base, base);
        exp >>= 1;
    }
    return result;
}

std::int64_t fib(std::uint64_t n) {
    if (n == 0) return 0;
    Matrix m{{{1, 1}, {1, 0}}};
    return power(m, n - 1)[0][0];
}

int main() {
    const std::uint64_t tests[] = {0, 1, 2, 10, 90};
    const std::int64_t expected[] = {0, 1, 1, 55, 2880067194370816120LL % MOD};
    for (std::size_t i = 0; i < 5; ++i)
        if (fib(tests[i]) != expected[i]) return 1;
    std::cout << fib(1000000) << '\n';
    return 0;
}
```
The transform [[1,1],[1,0]]^n maps (F1,F0) to (F_{n+1},F_n); products are taken mod 1e9+7 so 64-bit intermediates stay safe.

