```rust
use std::cmp::Ordering;

fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();  // exclusive
    while lo < hi {
        let mid = lo + (hi - lo) / 2;  // no overflow
        match slice[mid].cmp(target) {
            Ordering::Less => lo = mid + 1,
            Ordering::Greater => hi = mid,
            Ordering::Equal => return Some(mid),
        }
    }
    None
}

fn main() {
    let data = [1, 3, 3, 5, 8, 13];
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &13), Some(5));
    assert!(matches!(binary_search(&data, &3), Some(1) | Some(2)));
    assert_eq!(binary_search(&data, &4), None);
    assert_eq!(binary_search(&([] as [i32; 0]), &0), None);
    let words = ["ant", "bee", "cow"];
    assert_eq!(binary_search(&words, &"bee"), Some(1));
    println!("ok");
}
```
Half-open bounds with `lo < hi` avoid an off-by-one, and `lo + (hi - lo) / 2` never overflows even for very large slices.

