#!/usr/bin/env bash
set -euo pipefail

dir="${1:-.}"

if [[ ! -d "$dir" ]]; then
  echo "not a directory: $dir" >&2
  exit 1
fi

find "$dir" -type f -print0 \
  | xargs -0 du -b 2>/dev/null \
  | sort -rn \
  | head -n 5 \
  | awk '{
      size = $1;
      $1 = "";
      sub(/^ /, "");
      unit = "B";
      if (size >= 1073741824) { size /= 1073741824; unit = "GiB" }
      else if (size >= 1048576) { size /= 1048576; unit = "MiB" }
      else if (size >= 1024)     { size /= 1024; unit = "KiB" }
      printf "%8.1f %-3s  %s\n", size, unit, $0;
    }'
```
