```rust
fn encode(input: &str) -> String {
    let mut out = String::new();
    let mut chars = input.chars().peekable();
    while let Some(ch) = chars.next() {
        let mut count = 1u32;
        while chars.peek() == Some(&ch) {
            chars.next();
            count += 1;
        }
        out.push(ch);
        if count > 1 {
            out.push_str(&count.to_string());
        }
    }
    out
}

fn decode(input: &str) -> Result<String, String> {
    let mut out = String::new();
    let mut chars = input.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch.is_ascii_digit() {
            return Err(format!("digit '{}' without a preceding character", ch));
        }
        let mut count = String::new();
        while let Some(d) = chars.peek() {
            if d.is_ascii_digit() {
                count.push(*d);
                chars.next();
            } else {
                break;
            }
        }
        let n: usize = if count.is_empty() {
            1
        } else {
            count.parse().map_err(|_| format!("bad count '{}'", count))?
        };
        for _ in 0..n {
            out.push(ch);
        }
    }
    Ok(out)
}

fn main() {
    assert_eq!(encode("aaabbc"), "a3b2c");
    assert_eq!(encode(""), "");
    assert_eq!(decode("a3b2c").unwrap(), "aaabbc");
    assert!(decode("3ab").is_err());
    assert_eq!(decode(&encode("wwwwwwwwwwww")).unwrap(), "wwwwwwwwwwww");
    println!("ok");
}
```
Counts above one are stored explicitly, single characters need no digit, and `decode` rejects a leading digit instead of silently producing garbage.

