import sys
from typing import List


def longest_increasing_run(nums: List[int]):
    if not nums:
        return []

    best_start = best_len = 0
    cur_start = cur_len = 1

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            cur_len += 1
        else:
            cur_start = i
            cur_len = 1
        if cur_len > best_len:
            best_len = cur_len
            best_start = cur_start

    return nums[best_start:best_start + best_len]


def main():
    data = sys.stdin.read().split()
    nums = [int(tok) for tok in data]
    run = longest_increasing_run(nums)
    if not run:
        print("no run")
    else:
        print(" ".join(map(str, run)))


if __name__ == "__main__":
    main()
```

Run it with `python run.py <<< '1 2 3 2 5 6 7 1'` and it prints `2 5 6 7`. Empty input prints `no run`. An all-equal list such as `4 4 4` yields a single-element run (`4`), because strict increase is required.

