        return 1;
    }

    unsigned long counts[256] = {0};
    unsigned long total = 0;
    int c;
    while ((c = fgetc(fp)) != EOF) {
        counts[(unsigned char)c]++;
        total++;
    }
    fclose(fp);

    if (total == 0) {
        printf("file is empty\n");
        return 0;
    }

    for (int rank = 0; rank < 5; rank++) {
        int best = -1;
        for (int i = 0; i < 256; i++) {
            if (counts[i] == 0) continue;
            if (best == -1 || counts[i] > counts[best]) best = i;
        }
        if (best == -1) break;
        printf("0x%02X %lu\n", best, counts[best]);
        counts[best] = 0;
    }
    return 0;
}
```

Each pass of the outer loop selects the current maximum and zeroes it, so duplicates naturally fall through to later ranks. The `(unsigned char)c` cast is required: on platforms where `char` is signed, reading byte `0xFF` would otherwise index negatively. An empty file exits with `file is empty` before any ranking.

```cpp
#include <algorithm>
#include <iostream>
#include <vector>

std::vector<int> merge_unique(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());

    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] < b[j]) {
            out.push_back(a[i++]);
        } else if (b[j] < a[i]) {
            out.push_back(b[j++]);
        } else {
            out.push_back(a[i]);
            ++i;
            ++j; // equal boundary consumed from both
        }
    }
    out.insert(out.end(), a.begin() + i, a.end());
    out.insert(out.end(), b.begin() + j, b.end());

    out.erase(std::unique(out.begin(), out.end()), out.end());
    return out;
}

int main() {
    std::vector<int> a{1, 3, 3, 5, 7};
    std::vector<int> b{2, 3, 5, 5, 9};
    for (int v : merge_unique(a, b)) std::cout << v << ' ';
    std::cout << '\n';

    std::vector<int> empty;
    for (int v : merge_unique(empty, b)) std::cout << v << ' ';
    std::cout << '\n';
}
```

Output is `1 2 3 5 7 9` then `2 3 5 9`. The merge walk handles equal elements by advancing both indexes, so a value present in both is emitted once at that boundary; the final `unique` pass collapses duplicates that were already inside a single input, such as the `3 3` in `a`.

