fn fib(n: u32) -> Result<u64, &'static str> {
    let mut a: u64 = 0;
    let mut b: u64 = 1;
    for _ in 0..n {
        let next = a.checked_add(b).ok_or("overflow")?;
        a = b;
        b = next;
