#include <algorithm>
#include <vector>
#include <stdexcept>
#include <cstddef>

template <typename T>
T median(std::vector<T> v) // taken by value so the caller is untouched
{
    if (v.empty())
        throw std::invalid_argument("median of empty vector");

    const std::size_t mid = v.size() / 2;
    std::nth_element(v.begin(), v.begin() + static_cast<std::ptrdiff_t>(mid), v.end());

    if (v.size() % 2 == 1)
        return v[mid];

    // Even size: average the two middle values.
    const T upper = v[mid];
    std::nth_element(v.begin(), v.begin() + static_cast<std::ptrdiff_t>(mid - 1), v.begin() + static_cast<std::ptrdiff_t>(mid));
    const T lower = v[mid - 1];
    return (lower + upper) / static_cast<T>(2);
}

