```python
import functools
import random
import time


def retry(attempts=3, base=0.5, factor=2.0, jitter=0.1, exceptions=(Exception,)):
    """Retry a function with exponential backoff plus small jitter.

    attempts: total tries (>= 1).
    base:     delay before the first retry, seconds.
    factor:   multiplier applied each retry.
    jitter:   random fraction added to each delay to avoid thundering herds.
    """
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            delay = base
            for attempt in range(1, attempts + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    if attempt == attempts:
                        raise
                    sleep_for = delay * (1 + random.uniform(0, jitter))
                    time.sleep(sleep_for)
                    delay *= factor
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base=0.01, exceptions=(ValueError,))
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError(f"fail {calls['n']}")
        return "ok"

    print(flaky(), "after", calls["n"], "calls")
```

The final failed attempt re-raises the original exception rather than swallowing it, so callers still see real errors. `functools.wraps` keeps the wrapped function's name and docstring.

