fn encode(input: &[u8]) -> Vec<(u8, u8)> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < input.len() {
        let byte = input[i];
        let mut run: u8 = 1;
        while i + (run as usize) < input.len()
            && input[i + run as usize] == byte
            && run < u8::MAX
        {
            run += 1;
        }
        out.push((byte, run));
        i += run as usize;
    }
    out
}

fn decode(pairs: &[(u8, u8)]) -> Vec<u8> {
    let mut out = Vec::new();
    for &(byte, count) in pairs {
        for _ in 0..count {
            out.push(byte);
        }
    }
    out
}

