#include <stdlib.h>
#include <string.h>

#define BUCKETS 64

typedef struct Entry {
    char *key;
    int value;
    struct Entry *next;
} Entry;

typedef struct {
    Entry *buckets[BUCKETS];
} HashMap;

static unsigned long fnv1a(const char *s) {
    unsigned long h = 2166136261UL;
    for (; *s; ++s) {
        h ^= (unsigned char)*s;
        h *= 16777619UL;
    }
    return h;
}

static size_t slot(const char *key) {
    return fnv1a(key) % BUCKETS;
}

static int put(HashMap *m, const char *key, int value) {
    size_t i = slot(key);
    for (Entry *e = m->buckets[i]; e; e = e->next) {
        if (strcmp(e->key, key) == 0) {
            e->value = value;
            return 1;
        }
    }
    Entry *e = malloc(sizeof *e);
    if (!e) return 0;
    e->key = strdup(key);
    if (!e->key) { free(e); return 0; }
    e->value = value;
    e->next = m->buckets[i];
    m->buckets[i] = e;
    return 1;
}

static int *get(HashMap *m, const char *key) {
    for (Entry *e = m->buckets[slot(key)]; e; e = e->next)
        if (strcmp(e->key, key) == 0) return &e->value;
    return NULL;
}

static int del(HashMap *m, const char *key) {
    size_t i = slot(key);
    Entry **link = &m->buckets[i];
    while (*link) {
        Entry *e = *link;
        if (strcmp(e->key, key) == 0) {
            *link = e->next;
            free(e->key);
            free(e);
            return 1;
        }
        link = &e->next;
    }
    return 0;
}

int main(void) {
    HashMap m = {0};
    put(&m, "alpha", 1);
    put(&m, "beta", 2);
    put(&m, "alpha", 9);

    int *v = get(&m, "alpha");
    printf("alpha=%d\n", v ? *v : -1);
    printf("gamma=%s\n", get(&m, "gamma") ? "found" : "missing");
    printf("del beta=%d\n", del(&m, "beta"));
    printf("get beta=%s\n", get(&m, "beta") ? "found" : "missing");
    return 0;
}
