fn binary_search<T: Ord>(sorted: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = sorted.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match sorted[mid].cmp(target) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    None
}

fn main() {
    let nums = [1, 3, 3, 5, 8, 13, 21];
    assert_eq!(binary_search(&nums, &1), Some(0));
    assert_eq!(binary_search(&nums, &21), Some(6));
    assert_eq!(binary_search(&nums, &5), Some(3));
    assert!(matches!(binary_search(&nums, &3), Some(1) | Some(2)));
    assert_eq!(binary_search(&nums, &4), None);
    assert_eq!(binary_search(&nums, &0), None);
    assert_eq!(binary_search(&nums, &100), None);

    let empty: [i32; 0] = [];
    assert_eq!(binary_search(&empty, &7), None);

    let words = ["ant", "bee", "cat"];
    assert_eq!(binary_search(&words, &"bee"), Some(1));
    assert_eq!(binary_search(&words, &"dog"), None);

    println!("binary search ok");
}
```

`lo + (hi - lo) / 2` avoids overflow on very large slices that `(lo + hi) / 2` could hit.

