#include <cstddef>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), size_(0) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be > 0");
        }
    }

    void push(int value) {
        std::size_t tail = (head_ + size_) % cap_;
        buf_[tail] = value;
        if (size_ < cap_) {
            ++size_;
        } else {
            head_ = (head_ + 1) % cap_;
        }
    }

    int at(std::size_t i) const {
        if (i >= size_) {
            throw std::out_of_range("index out of range");
        }
        return buf_[(head_ + i) % cap_];
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return cap_; }

private:
    std::vector<int> buf_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t size_;
};
