```cpp
#include <condition_variable>
#include <mutex>
#include <queue>
#include <stdexcept>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(int value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return q_.size() < cap_ || closed_; });
        if (closed_) throw std::runtime_error("queue closed");
        q_.push(value);
        not_empty_.notify_one();
    }

    bool pop(int& out) {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return !q_.empty() || closed_; });
        if (q_.empty()) return false;  // closed and drained
        out = q_.front();
        q_.pop();
        not_full_.notify_one();
        return true;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<int> q_;
    mutable std::mutex mu_;
    std::condition_variable not_full_, not_empty_;
    bool closed_ = false;
};
```

`close()` makes blocked consumers and producers wake and either drain or bail, so shutdown can't deadlock. Use `-pthread` when compiling.

