    const std::size_t mid = v.size() / 2;
    std::nth_element(v.begin(), v.begin() + mid, v.end());
    long long median = v[mid];

    if (v.size() % 2 == 0) {
        std::nth_element(v.begin(), v.begin() + mid - 1, v.end());
        long long lower = v[mid - 1];
        // Print exact value without integer division: (a+b)/2.
        std::cout << lower + median << "/2\n";
    } else {
        std::cout << median << "\n";
    }
    return 0;
}
