`nth_element` is O(n) expected. For even counts the midpoint is kept exact as a fraction so odd/even sums don't lose precision via integer division.

```rust
fn parse_duration(input: &str) -> Result<u64, String> {
    let mut total: u64 = 0;
    let mut num = String::new();
    let mut saw_unit = false;

    for ch in input.chars() {
        if ch.is_ascii_digit() {
            num.push(ch);
        } else if ch == 'h' || ch == 'm' || ch == 's' {
            if num.is_empty() {
                return Err(format!("missing number before '{ch}'"));
            }
            let value: u64 = num.parse().map_err(|_| format!("bad number {num:?}"))?;
            let mult = match ch {
                'h' => 3600,
                'm' => 60,
                _ => 1,
            };
            total += value * mult;
            num.clear();
            saw_unit = true;
        } else {
            return Err(format!("unexpected character {ch:?}"));
        }
    }

    if !num.is_empty() || !saw_unit {
        return Err("trailing number without unit".to_string());
    }
    Ok(total)
}

fn main() {
    assert_eq!(parse_duration("1h30m15s"), Ok(5415));
    assert_eq!(parse_duration("45s"), Ok(45));
    assert_eq!(parse_duration("2h"), Ok(7200));
    assert!(parse_duration("1h30").is_err());
    assert!(parse_duration("").is_err());
    assert!(parse_duration("10x").is_err());
    println!("ok");
}
```

Empty input returns `Err` rather than `Ok(0)` so callers can tell "missing" from "zero". Units may repeat, e.g. `1h1h` sums to 7200.

```rust
use std::collections::{HashMap, VecDeque};
use std::hash::Hash;

pub struct LruCache<K, V> {
    cap: usize,
    order: VecDeque<K>,
    map: HashMap<K, V>,
}

impl<K: Eq + Hash + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be > 0");
        LruCache { cap, order: VecDeque::new(), map: HashMap::new() }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        if self.map.contains_key(key) {
            self.touch(key);
        }
        self.map.get(key)
    }

    pub fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            self.touch(&key);
        } else {
            if self.map.len() == self.cap {
                if let Some(evicted) = self.order.pop_back() {
                    self.map.remove(&evicted);
                }
            }
            self.order.push_front(key.clone());
        }
        self.map.insert(key, value);
    }

    fn touch(&mut self, key: &K) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            let k = self.order.remove(pos).unwrap();
            self.order.push_front(k);
        }
    }

    pub fn len(&self) -> usize { self.map.len() }
}

fn main() {
    let mut c = LruCache::<&str, i32>::new(2);
    c.put("a", 1);
    c.put("b", 2);
    assert_eq!(c.get(&"a"), Some(&1));
    c.put("c", 3);          // evicts "b"
    assert_eq!(c.get(&"b"), None);
    assert_eq!(c.get(&"a"), Some(&1));
    println!("ok");
}
```

Front of `order` is most-recent. `get` refreshes recency, and eviction happens before insert so the cache never exceeds `cap`.

```c
#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* Copy src into dst (size bytes). Always NUL-terminates when size > 0.
 * Returns the number of bytes written excluding the NUL, or 0 if size == 0. */
size_t copy_string(char *dst, size_t size, const char *src) {
    if (dst == NULL || src == NULL || size == 0) {
        return 0;
    }
    size_t i = 0;
    for (; i < size - 1 && src[i] != '\0'; ++i) {
        dst[i] = src[i];
    }
    dst[i] = '\0';
    return i;
}

int main(void) {
    char buf[8];
    size_t n = copy_string(buf, sizeof buf, "hello");
    printf("%zu:%s\n", n, buf);       /* 5:hello */
    n = copy_string(buf, sizeof buf, "truncate-me");
    printf("%zu:%s\n", n, buf);       /* 7:truncate */
    copy_string(buf, sizeof buf, "");
    printf("[%s]\n", buf);            /* [] */
    return 0;
}
```

The loop bound `size - 1` reserves one byte for the terminating NUL, so even an oversized source is safely truncated and the result is always a valid C string.

```c
#include <stdint.h>
#include <stdio.h>

static uint8_t reverse_byte(uint8_t b) {
    b = (uint8_t)((b & 0xF0u) >> 4 | (b & 0x0Fu) << 4);
    b = (uint8_t)((b & 0xCCu) >> 2 | (b & 0x33u) << 2);
    b = (uint8_t)((b & 0xAAu) >> 1 | (b & 0x55u) << 1);
    return b;
}

static uint8_t table[256];

static void init_table(void) {
    for (int i = 0; i < 256; ++i) table[i] = reverse_byte((uint8_t)i);
}

uint32_t reverse_bits(uint32_t x) {
    return ((uint32_t)table[x & 0xFFu] << 24) |
           ((uint32_t)table[(x >> 8) & 0xFFu] << 16) |
           ((uint32_t)table[(x >> 16) & 0xFFu] << 8) |
           ((uint32_t)table[(x >> 24) & 0xFFu]);
}

int main(void) {
    init_table();
    printf("%08X\n", reverse_bits(0x00000001u));  /* 80000000 */
    printf("%08X\n", reverse_bits(0x12345678u));  /* 1E6A2C48 */
    printf("%08X\n", reverse_bits(0xFFFFFFFFu));  /* FFFFFFFF */
    printf("%08X\n", reverse_bits(0x00000000u));  /* 00000000 */
    return 0;
}
```

Shifting with biased types: masks are ANDed before shifts and results cast back to `uint8_t` so no promotion surprises occur. Bytes are read little-endian by nibble position, so the table index and output shift positions line up correctly.

