#include <cctype>
#include <iostream>
#include <string>

bool is_palindrome(const std::string& s) {
    std::size_t lo = 0, hi = s.size();
    while (lo < hi) {
        if (!std::isalnum(static_cast<unsigned char>(s[lo]))) { ++lo; continue; }
        if (!std::isalnum(static_cast<unsigned char>(s[hi - 1]))) { --hi; continue; }
        if (std::tolower(static_cast<unsigned char>(s[lo])) !=
            std::tolower(static_cast<unsigned char>(s[hi - 1])))
            return false;
        ++lo;
        --hi;
    }
    return true;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_palindrome("A man, a plan, a canal: Panama") << '\n';   // true
    std::cout << is_palindrome("No 'x' in Nixon") << '\n';                 // true
    std::cout << is_palindrome("") << '\n';                                // true
    std::cout << is_palindrome("!!!") << '\n';                             // true
    std::cout << is_palindrome("hello") << '\n';                           // false
}
```

Two pointers converge from both ends, skipping any character where `isalnum` is false. Casting to `unsigned char` before `isalnum`/`tolower` avoids undefined behaviour on negative `char` values. Empty and all-punctuation strings are vacuously palindromes.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

 template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& v) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }

    bool pop(T& out) {
        if (size_ == 0) return false;
        out = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }
    constexpr std::size_t capacity() const { return N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << '\n'; // 1110
    int x = 0;
    std::cout << rb.pop(x) << ' ' << x << '\n';  // 1 1
    std::cout << rb.push(5) << '\n';             // 1
    while (rb.pop(x)) std::cout << x << ' ';     // 2 3 5
    std::cout << '\n';
}
```

The buffer stores `size_` live elements starting at `head_`, wrapping modulo `N`. `push` fails when full and `pop` fails when empty, so no exceptions are needed. A zero-capacity buffer is invalid by construction and should not be instantiated.

```rust
use std::collections::HashMap;

fn fib(n: u32) -> Result<u64, String> {
    if n > 92 {
        return Err(format!("fib({n}) exceeds u64 range"));
    }
    let mut memo: HashMap<u32, u64> = HashMap::new();
    Ok(fib_memo(n, &mut memo))
}

fn fib_memo(n: u32, memo: &mut HashMap<u32, u64>) -> u64 {
    if n < 2 {
        return n as u64;
    }
    if let Some(&v) = memo.get(&n) {
        return v;
    }
    let v = fib_memo(n - 1, memo).wrapping_add(fib_memo(n - 2, memo));
    memo.insert(n, v);
    v
}

fn main() {
    assert_eq!(fib(0), Ok(0));
    assert_eq!(fib(1), Ok(1));
    assert_eq!(fib(10), Ok(55));
    assert_eq!(fib(92), Ok(7540113804746346429));
    assert!(fib(93).is_err());
    println!("{:?}", fib(50)); // Ok(12586269025)
}
```

`fib(93)` is the first value past `u64::MAX`, so indices above 92 return an error instead of wrapping. Memoisation is carried in a `HashMap` passed by mutable reference, turning the naive exponential recursion into linear time. The `wrapping_add` inside the memo is safe because the index guard already excludes overflow.

