Blank lines and `#` comments are skipped before parsing. The first `=` splits key from value, so values containing `=` keep their remainder intact. Errors carry the 1-based line number from `enumerate` so the caller can point at the bad line.

```c
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define ARENA_SIZE 256

typedef struct {
    unsigned char buf[ARENA_SIZE];
    size_t offset;
} Arena;

static size_t align_up(size_t n, size_t align) {
    return (n + align - 1) & ~(align - 1);
}

void *arena_alloc(Arena *a, size_t size, size_t align) {
    size_t start = align_up(a->offset, align);
    if (align == 0 || (align & (align - 1)) != 0) return NULL;
    if (start > ARENA_SIZE || size > ARENA_SIZE - start) return NULL;
    a->offset = start + size;
    return a->buf + start;
}

void arena_reset(Arena *a) { a->offset = 0; }

int main(void) {
    Arena a = { .offset = 0 };
    int *ints = arena_alloc(&a, 3 * sizeof(int), _Alignof(int));
    char *msg = arena_alloc(&a, 6, 1);
    if (!ints || !msg) { puts("oom"); return 1; }
    ints[0] = 1; ints[1] = 2; ints[2] = 3;
    memcpy(msg, "hello", 6);
    printf("%d %d %d %s\n", ints[0], ints[1], ints[2], msg);

    arena_reset(&a);
    void *big = arena_alloc(&a, ARENA_SIZE + 1, 1);
    printf("after reset big=%s\n", big == NULL ? "NULL" : "ok");
    return 0;
}
```

Allocations bump an offset, rounding up to the requested alignment first. The capacity check guards both the aligned start and the size against the remaining bytes, so an oversized request returns `NULL` instead of running past the buffer. `arena_reset` frees everything at once by zeroing the offset.

