use std::collections::HashSet;

fn dedup_preserve_order(values: &[i32]) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();
    for &v in values {
        if seen.insert(v) {
            result.push(v);
        }
    }
    result
}

fn main() {
