#include <cctype>
#include <iostream>
#include <string>

bool is_palindrome(const std::string& input) {
    std::size_t left = 0;
    std::size_t right = input.size();

    while (left < right) {
        if (right == 0) break;
        --right;
        while (left < right && !std::isalnum(static_cast<unsigned char>(input[left]))) ++left;
        while (left < right && !std::isalnum(static_cast<unsigned char>(input[right]))) --right;
        if (left >= right) break;
        char a = static_cast<char>(std::tolower(static_cast<unsigned char>(input[left])));
        char b = static_cast<char>(std::tolower(static_cast<unsigned char>(input[right])));
        if (a != b) return false;
        ++left;
    }
    return true;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_palindrome("A man, a plan, a canal: Panama") << "\n"; // true
    std::cout << is_palindrome("race a car") << "\n";                    // false
    std::cout << is_palindrome("") << "\n";                              // true
    std::cout << is_palindrome("!!") << "\n";                            // true
}
