        if lineno == 1 and row and row[0].strip().lower() == "name":
            continue
        if len(row) != 2:
            print(f"skipping malformed row {lineno}: {row}", file=sys.stderr)
            continue
        name = row[0].strip()
        try:
            score = float(row[1])
        except ValueError:
            print(f"skipping non-numeric score on row {lineno}", file=sys.stderr)
            continue
        if not name:
            continue
        rows.append((score, name))

    rows.sort(key=lambda pair: (-pair[0], pair[1]))
    return rows[:3]


if __name__ == "__main__":
    for score, name in top_three(SAMPLE):
        print(f"{name}: {score:g}")
