```cpp
#include <iostream>
#include <vector>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

std::vector<int> to_vector(Node* head) {
    std::vector<int> out;
    for (Node* p = head; p != nullptr; p = p->next) out.push_back(p->value);
    return out;
}

int main() {
    Node* head = nullptr;
    for (int v : {1, 2, 3, 4}) {
        head = new Node(v);
        // build order: 4->3->2->1
        Node* tmp = head;
        (void)tmp;
    }
    // rebuild explicitly to keep it clear
    while (head) { Node* n = head->next; delete head; head = n; }
    head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);

    head = reverse(head);
    std::vector<int> got = to_vector(head);
    bool ok = (got == std::vector<int>{3, 2, 1});
    std::cout << (ok ? "ok" : "fail") << "\n";

    while (head) { Node* n = head->next; delete head; head = n; }
    return ok ? 0 : 1;
}
```

The three-pointer walk (`prev`, `nxt`, `head`) reverses links in place, handles a single node and an empty list, and frees every node at the end.

