    std::cout << (longest_common_prefix({"dog", "racecar", "car"}) == "" ? "ok" : "fail") << "\n";
    std::cout << (longest_common_prefix({}) == "" ? "ok" : "fail") << "\n";
    std::cout << (longest_common_prefix({"single"}) == "single" ? "ok" : "fail") << "\n";
    return 0;
}
