fn merge_intervals(mut intervals: Vec<(i32, i32)>) -> Vec<(i32, i32)> {
    if intervals.is_empty() {
        return vec![];
    }
    intervals.sort_by_key(|iv| iv.0);
    let mut out: Vec<(i32, i32)> = Vec::new();
    let (mut start, mut end) = intervals[0];
    for (s, e) in intervals.into_iter().skip(1) {
        if s <= end {
            if e > end {
                end = e;
            }
        } else {
            out.push((start, end));
            start = s;
            end = e;
        }
    }
    out.push((start, end));
    out
}

fn main() {
    assert_eq!(merge_intervals(vec![]), vec![]);
    assert_eq!(merge_intervals(vec![(1, 3), (2, 6), (8, 10), (15, 18)]),
               vec![(1, 6), (8, 10), (15, 18)]);
    assert_eq!(merge_intervals(vec![(1, 4), (4, 5)]), vec![(1, 5)]);
    assert_eq!(merge_intervals(vec![(5, 6), (1, 2)]), vec![(1, 2), (5, 6)]);
    println!("ok");
}
```

Sorting by start time makes overlaps adjacent. Touching intervals like `(1,4)` and `(4,5)` merge because the check is `s <= end`; disjoint ones close the current run.

