    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

Node *reverse_rec(Node *head) {
    if (!head || !head->next) return head;
    Node *rest = reverse_rec(head->next);
    head->next->next = head;
    head->next = NULL;
    return rest;
}

void print(Node *head) {
    for (Node *cur = head; cur; cur = cur->next) {
        printf("%d", cur->value);
        if (cur->next) printf(" -> ");
    }
    printf("\n");
}

void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 5; i >= 1; i--) {
        Node *n = make_node(i);
        n->next = head;
        head = n;
    }
    print(head);
    head = reverse_iter(head);
    print(head);
    head = reverse_rec(head);
    print(head);
    free_list(head);
    return 0;
}
```

The list prints `1 -> 2 -> 3 -> 4 -> 5`, then the iterative reverse gives `5 -> 4 -> 3 -> 2 -> 1`, then the recursive reverse restores the order. The recursive version stacks one frame per node, so very long lists can overflow the stack.

```rust
fn gcd(a: i64, b: i64) -> i64 {
    let (mut a, mut b) = (a.abs(), b.abs());
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}

fn modular_inverse(a: i64, m: i64) -> Option<i64> {
    if m <= 0 {
        return None;
    }
    let (mut old_r, mut r) = (a.rem_euclid(m), m);
    let (mut old_s, mut s) = (1i64, 0i64);
    while r != 0 {
        let q = old_r / r;
        let new_r = old_r - q * r;
        old_r = r;
        r = new_r;
        let new_s = old_s - q * s;
        old_s = s;
        s = new_s;
    }
    if old_r != 1 {
        None
    } else {
        Some(old_s.rem_euclid(m))
    }
}

fn main() {
    println!("gcd(0, 0) = {}", gcd(0, 0));
    println!("gcd(48, 18) = {}", gcd(48, 18));
    println!("inverse of 3 mod 11 = {:?}", modular_inverse(3, 11));
    println!("inverse of 2 mod 4 = {:?}", modular_inverse(2, 4));
}
```

`gcd(0, 0)` returns 0 by convention. `modular_inverse` returns `None` when the modulus is not positive or when `a` and `m` are not coprime (`2 mod 4` has no inverse). `rem_euclid` keeps negative inputs in range.

