#include <stack>
#include <optional>

struct Result {
    bool ok;
    std::size_t position;
    char found;
};

Result validate(const std::string& s) {
    std::stack<std::pair<char, std::size_t>> st;
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push({c, i});
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return {false, i, c};
            char open = st.top().first;
            bool matches = (open == '(' && c == ')') ||
                           (open == '[' && c == ']') ||
                           (open == '{' && c == '}');
            if (!matches) return {false, i, c};
            st.pop();
        }
    }
    if (!st.empty()) return {false, st.top().second, st.top().first};
    return {true, s.size(), '\0'};
}

int main() {
    std::string tests[] = {"([]){}", "([)]", "(((", "]", ""};
    for (const auto& s : tests) {
        Result r = validate(s);
        if (r.ok) {
            std::cout << "\"" << s << "\" balanced\n";
        } else {
            std::cout << "\"" << s << "\" mismatch at " << r.position
                      << " (char '" << r.found << "')\n";
        }
    }
    return 0;
}
```

`([)]` fails at index 2 because the `]` closes an open `(`. `(((` reports the unmatched opening at index 0. An empty string is balanced.

