```cpp
#include <array>
#include <cstddef>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    const T& front() const {
        if (size_ == 0) throw std::out_of_range("empty ring buffer");
        return data_[(head_ + N - size_) % N];
    }

    const T& back() const {
        if (size_ == 0) throw std::out_of_range("empty ring buffer");
        return data_[(head_ + N - 1) % N];
    }

    std::size_t size() const { return size_; }
    static constexpr std::size_t capacity() { return N; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4); // overwrites 1
    if (rb.front() != 2 || rb.back() != 4 || rb.size() != 3) return 1;
    return 0;
}
```
`head_` points at the next write slot; `front()`/`back()` use modular offsets from it, so no shifting is needed and full behaviour overwrites the oldest element.

```rust
use std::time::Duration;

/// Parse a compact duration such as `1h30m10s` into seconds.
/// Accepted units: h, m, s. Units must appear in order, no repeats.
fn parse_duration(s: &str) -> Result<u64, String> {
    let s = s.trim();
    if s.is_empty() {
        return Err("empty duration".into());
    }
    let (mut total, mut num, mut seen) = (0u64, String::new(), (false, false, false));
    for ch in s.chars() {
        if ch.is_ascii_digit() {
            num.push(ch);
            continue;
        }
        let value: u64 = num.parse().map_err(|_| "missing number before unit")?;
        match ch {
            'h' if !seen.0 => { seen.0 = true; total += value * 3600; }
            'm' if !seen.1 => { seen.1 = true; total += value * 60; }
            's' if !seen.2 => { seen.2 = true; total += value; }
            _ => return Err(format!("unexpected unit or order: {ch}")),
        }
        num.clear();
    }
    if !num.is_empty() {
        return Err("trailing number without unit".into());
    }
    Ok(total)
}

fn main() {
    assert_eq!(parse_duration("1h30m10s"), Ok(5410));
    assert_eq!(parse_duration("45s"), Ok(45));
    assert!(parse_duration("10m5h").is_err());
    assert!(parse_duration("12").is_err());
    let _ = Duration::from_secs(1);
    println!("ok");
}
```
The parser rejects out-of-order or repeated units and numbers with no unit, so `10m5h` and `12` are errors rather than silently summed.

```rust
/// Merge two ascending slices into a single ascending Vec.
fn merge_sorted<T: Ord + Copy>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1], &[1]), vec![1, 1, 1]);
    println!("ok");
}
```
`T: Copy` lets the elements be copied out of the borrowed slices without consuming them, and the leftover tail is appended in one shot after the merge loop.

