#include <string.h>

/* Returns true if `b` is a rotation of `a`. Uses O(n) auxiliary space
   for the doubled string, which is the standard O(n) approach. */
bool is_rotation(const char *a, const char *b) {
    size_t la = strlen(a), lb = strlen(b);
    if (la != lb) return false;
    if (la == 0) return true;

    char *doubled = malloc(2 * la + 1);
    if (!doubled) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    memcpy(doubled, a, la);
    memcpy(doubled + la, a, la);
    doubled[2 * la] = '\0';

    bool found = strstr(doubled, b) != NULL;
    free(doubled);
    return found;
}

int main(void) {
    if (!is_rotation("abcde", "cdeab")) return 1;
    if (is_rotation("abcde", "abced")) return 1;
    if (!is_rotation("", "")) return 1;
    if (is_rotation("a", "aa")) return 1;
    puts("ok");
    return 0;
}
```
If `a` and `b` have equal length and `b` appears in `a + a`, then `b` is a rotation. Unequal lengths and the empty string are handled up front.

