std::vector<std::pair<std::string, int>> top_k_words(const std::string& text, std::size_t k) {
    std::unordered_map<std::string, int> counts;
    std::string word;
    auto flush = [&]() {
        if (!word.empty()) {
            ++counts[word];
            word.clear();
        }
    };
    for (unsigned char ch : text) {
        if (std::isalpha(ch)) {
            word.push_back(static_cast<char>(std::tolower(ch)));
        } else if (ch == '\'') {
            // apostrophe joins parts of a word, e.g. "don't" -> "dont"
            continue;
        } else {
            flush();
        }
    }
    flush();

    std::vector<std::pair<std::string, int>> items(counts.begin(), counts.end());
    std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;  // deterministic tie-break
    });
    if (items.size() > k) items.resize(k);
    return items;
}

int main() {
    auto r = top_k_words("The cat, the dog. The cat's hat!", 2);
    for (const auto& p : r) std::cout << p.first << ' ' << p.second << '\n';
    // the 3, cat 2
    return 0;
}
