void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0) return;
    j--;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

static int check(const char *input, const char *expected) {
    char buf[64];
    size_t n = strlen(input);
    if (n >= sizeof(buf)) {
        fprintf(stderr, "test input too long\n");
        return 1;
    }
    memcpy(buf, input, n + 1);
    reverse_in_place(buf);
    if (strcmp(buf, expected) != 0) {
        fprintf(stderr, "FAIL: %s -> %s (want %s)\n", input, buf, expected);
        return 1;
    }
    return 0;
}

int main(void) {
    int fails = 0;
    fails += check("", "");
    fails += check("a", "a");
    fails += check("ab", "ba");
    fails += check("hello", "olleh");
    if (fails == 0) printf("all tests passed\n");
    return fails ? 1 : 0;
}
