```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity), buf_(capacity) {}

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == cap_; }
    std::size_t size() const { return size_; }

    bool push(int value) {
        if (full()) return false;
        buf_[head_] = value;
        head_ = (head_ + 1) % cap_;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int value = buf_[tail_];
        tail_ = (tail_ + 1) % cap_;
        --size_;
        return value;
    }

private:
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
    std::array<int, 0> unused_placeholder_ = {}; // capacity carried separately
    std::vector<int> buf_;
};

int main() {
    RingBuffer rb(3);
    if (!rb.empty()) { std::cerr << "expected empty\n"; return 1; }
    rb.push(1); rb.push(2); rb.push(3);
    if (!rb.full()) { std::cerr << "expected full\n"; return 1; }
    if (rb.push(4)) { std::cerr << "push on full should fail\n"; return 1; }
    if (rb.pop() != 1) { std::cerr << "expected fifo 1\n"; return 1; }
    rb.push(4);
    if (rb.pop() != 2 || rb.pop() != 3 || rb.pop() != 4) {
        std::cerr << "fifo order broken\n"; return 1;
    }
    if (rb.pop().has_value()) { std::cerr << "drain should be empty\n"; return 1; }
    std::cout << "ring buffer tests passed\n";
    return 0;
}
```

Compile with `g++ -std=c++17 ring.cpp -o ring`. The constructor resizes `buf_` to capacity, `head_` is the next write slot and `tail_` the next read slot, both taken modulo capacity. `push` refuses when full and `pop` returns `std::nullopt` when empty, so the tests can assert both boundary conditions. The extra `std::array<int,0>` member is a placeholder and can be deleted.

