use std::collections::HashMap;

/// Count words (split on ASCII whitespace, lowercased) and return
/// (word, count) pairs sorted by count descending, then word ascending.
fn word_freq(text: &str) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for w in text.split_whitespace() {
        let key = w.to_lowercase();
        *counts.entry(key).or_insert(0) += 1;
    }
    let mut out: Vec<(String, usize)> = counts.into_iter().collect();
    out.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    out
}

fn main() {
    let text = "the cat the dog The bird cat";
    let got = word_freq(text);
    assert_eq!(got[0], ("the".to_string(), 3));
    assert_eq!(got[1], ("cat".to_string(), 2));
    assert_eq!(got[2], ("bird".to_string(), 1));
    assert_eq!(got[3], ("dog".to_string(), 1));
    assert!(word_freq("").is_empty());
    println!("{:?}", got);
}
