    def decorate(fn: Callable[..., T]) -> Callable[..., T]:
        @functools.wraps(fn)
        def wrapper(*args, **kwargs) -> T:
            delay = base_delay
            last = None
            for i in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:  # noqa: PERF203
                    last = exc
                    if i == attempts - 1:
                        break
                    time.sleep(min(delay, max_delay))
                    delay *= 2
            assert last is not None
            raise last
        return wrapper
    return decorate


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=5, base_delay=0.0)
    def flaky() -> str:
        calls["n"] += 1
        if calls["n"] < 3:
            raise RuntimeError("transient")
        return "done"

    assert flaky() == "done"
    assert calls["n"] == 3
    print("ok")
```

