```rust
use std::collections::HashMap;
use std::collections::VecDeque;

pub struct Lru<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: Eq + std::hash::Hash + Clone, V> Lru<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        Lru { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    fn touch(&mut self, key: &K) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            self.order.remove(pos);
        }
        self.order.push_back(key.clone());
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        if self.map.contains_key(key) {
            self.touch(key);
        }
        self.map.get(key)
    }

    pub fn put(&mut self, key: K, val: V) -> Option<V> {
        let old = self.map.insert(key.clone(), val);
        self.touch(&key);
        if self.map.len() > self.cap {
            if let Some(evicted) = self.order.pop_front() {
                if evicted != key {
                    self.map.remove(&evicted);
                }
            }
        }
        old
    }
}

fn main() {
    let mut c = Lru::new(2);
    c.put("a", 1);
    c.put("b", 2);
    assert_eq!(c.get(&"a"), Some(&1));
    c.put("c", 3);
    assert_eq!(c.get(&"b"), None);
    println!("ok");
}
```

`VecDeque` for order makes `get` O(n) because of the linear position scan; swap in a linked list or intrusive order map if you need O(1) eviction at high capacity.

