#include <algorithm>
#include <iostream>
#include <optional>
#include <vector>

std::optional<double> median(std::vector<double> v) {
    if (v.empty()) return std::nullopt;
    size_t mid = v.size() / 2;
    std::nth_element(v.begin(), v.begin() + mid, v.end());
    double hi = v[mid];
    if (v.size() % 2 == 1) return hi;
    std::nth_element(v.begin(), v.begin() + mid - 1, v.end());
    return (v[mid - 1] + hi) / 2.0;
}

int main() {
    std::vector<double> a{3, 1, 2};
    std::cout << *median(a) << '\n';
    std::vector<double> b{1, 2, 3, 4};
    std::cout << *median(b) << '\n';
    std::cout << median({}) .has_value() << '\n';
    // caller's vector is untouched because v is a by-value copy
    assert(a.size() == 3);
}
```

`nth_element` gives expected O(n) instead of a full O(n log n) sort, and taking `v` by value means the caller's vector is never reordered. Empty input returns `std::nullopt` rather than an arbitrary value.

