```rust
use std::collections::{HashMap, VecDeque};
use std::hash::Hash;
use std::sync::Mutex;

pub struct LruCache<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: Eq + Hash + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            let k = self.order.remove(pos).unwrap();
            self.order.push_back(k);
        }
        self.map.get(key)
    }

    pub fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            if let Some(pos) = self.order.iter().position(|k| k == &key) {
                self.order.remove(pos);
            }
        } else if self.map.len() == self.cap {
            if let Some(old) = self.order.pop_front() {
                self.map.remove(&old);
            }
        }
        self.order.push_back(key.clone());
        self.map.insert(key, value);
    }

    pub fn len(&self) -> usize { self.map.len() }
}

pub struct SharedCache<K, V>(Mutex<LruCache<K, V>>);

impl<K: Eq + Hash + Clone, V> SharedCache<K, V> {
    pub fn new(cap: usize) -> Self { SharedCache(Mutex::new(LruCache::new(cap))) }
    pub fn get(&self, key: &K) -> Option<V> where V: Clone {
        let mut g = self.0.lock().unwrap();
        g.get(key).cloned()
    }
    pub fn put(&self, key: K, value: V) {
        self.0.lock().unwrap().put(key, value);
    }
}

fn main() {
    let c = SharedCache::new(2);
    c.put("a", 1); c.put("b", 2);
    assert_eq!(c.get(&"a"), Some(1));
    c.put("c", 3);
    assert_eq!(c.get(&"b"), None); // evicted LRU
    println!("ok");
}
```

`VecDeque` tracks recency; `Mutex` makes it shareable across threads. Assert on `cap > 0` prevents a degenerate cache.

```c
#include <stdio.h>
#include <stdint.h>
#include <string.h>

int parse_ipv4(const char *s, uint32_t *out) {
    if (!s || !out) return -1;
    uint32_t parts[4] = {0};
    int idx = 0;
    const char *p = s;
    while (*p) {
        if (idx == 4) return -1;
        if (*p < '0' || *p > '9') return -1;
        long val = 0;
        int digits = 0;
        while (*p >= '0' && *p <= '9') {
            val = val * 10 + (*p - '0');
            if (++digits > 3 || val > 255) return -1;
            p++;
        }
        if (digits > 1 && parts[idx] == 0 && val != 0 && *(p - digits) == '0') return -1; // leading zero
        parts[idx++] = (uint32_t)val;
        if (*p == '.') {
            p++;
            if (*p == '\0') return -1; // trailing dot
        } else if (*p != '\0') {
            return -1;
        }
    }
    if (idx != 4) return -1;
    *out = (parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3];
    return 0;
}

int main(void) {
    uint32_t ip = 0;
    if (parse_ipv4("192.168.0.1", &ip) == 0)
        printf("0x%08X\n", ip);
    if (parse_ipv4("256.1.1.1", &ip) != 0)
        printf("rejected 256.1.1.1\n");
    if (parse_ipv4("1.2.3", &ip) != 0)
        printf("rejected short\n");
    if (parse_ipv4("1.2.3.4.5", &ip) != 0)
        printf("rejected long\n");
    return 0;
}
```

Each octet is capped at 255, leading zeros and trailing dots are rejected, and exactly four parts are required. Host-order output is `(a<<24)|(b<<16)|(c<<8)|d`.

