```cpp
#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (size_ == N) return false;   // full: caller decides policy
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};
```

`head_` tracks the oldest element and `(head_ + size_) % N` is the next write slot, so the indices wrap without any shifting. `push` returns `false` when full and `pop` returns `std::nullopt` when empty, keeping both operations non-throwing for trivially copyable `T`. `N` must be at least 1; a static assertion can be added if you want to enforce that.

