fn fib_iter(n: u32) -> u64 {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let next = a + b;
        a = b;
        b = next;
    }
    a
}

fn fib_naive(n: u32) -> u64 {
    if n < 2 {
        n as u64
    } else {
        fib_naive(n - 1) + fib_naive(n - 2)
    }
}

fn main() {
    for n in 0..=20 {
        let fast = fib_iter(n);
        let slow = fib_naive(n);
        assert_eq!(fast, slow, "mismatch at n={n}: {fast} != {slow}");
    }
    println!("fib(10) = {}", fib_iter(10));
    println!("fib(90) = {}", fib_iter(90));
}
