```c
#include <stdio.h>
#include <string.h>
#include <stddef.h>

/* Advance to the start of the next UTF-8 code point. */
static const char *next_cp(const char *p) {
    unsigned char c = (unsigned char)*p;
    size_t len = 1;
    if ((c & 0x80) == 0x00) len = 1;
    else if ((c & 0xE0) == 0xC0) len = 2;
    else if ((c & 0xF0) == 0xE0) len = 3;
    else if ((c & 0xF8) == 0xF0) len = 4;
    return p + len;
}

void reverse_utf8(char *s) {
    if (!s || !*s) return;
    const char *end = s + strlen(s);
    char *out = s;
    char buf[4096];
    size_t n = 0;

    /* Collect all code points in order first. */
    for (const char *p = s; p < end; ) {
        const char *q = next_cp(p);
        while (p < q) buf[n++] = *p++;
    }
    /* Write them back in reverse. */
    while (n > 0) {
        /* Find the start of the last code point still buffered. */
        size_t j = n;
        do { --j; } while (j > 0 && ((unsigned char)buf[j] & 0xC0) == 0x80);
        for (size_t k = j; k < n; ++k) *out++ = buf[k];
        n = j;
    }
    *out = '\0';
}

int main(void) {
    char s[] = "héllo";
    reverse_utf8(s);
    printf("%s\n", s);
    return 0;
}
```

Multibyte sequences are copied whole and never split: `next_cp` walks one code point at a time using the leading-byte length, and the write-back scans backwards past continuation bytes (`10xxxxxx`) to find each code point's start. The fixed `buf[4096]` caps input length; for untrusted sizes, allocate with `malloc(strlen(s))` instead.

