```cpp
#include <iostream>
#include <stack>
#include <string>

bool is_balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.empty();
}

int main() {
    const char* tests[] = {"", "()", "([])", "{[()]}", "([)]", "((", ")[", "a(b)c[d]"};
    bool expected[]  = {true, true, true, true, false, false, false, true};
    for (std::size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); ++i) {
        bool got = is_balanced(tests[i]);
        std::cout << tests[i] << " -> " << (got ? "ok" : "bad") << '\n';
        if (got != expected[i]) return 1;
    }
    std::cout << "all bracket tests passed\n";
    return 0;
}
```

Non-bracket characters are ignored, so `a(b)c[d]` passes. An empty string is balanced; a closing bracket with an empty stack — or a leftover open at the end — fails.

```cpp
#include <array>
#include <iostream>

constexpr long long MOD = 1000000007LL;

using Mat = std::array<std::array<long long, 2>, 2>;

Mat mul(const Mat& a, const Mat& b) {
    Mat r{};
    for (int i = 0; i < 2; ++i)
        for (int k = 0; k < 2; ++k)
            for (int j = 0; j < 2; ++j)
                r[i][j] = (r[i][j] + a[i][k] * b[k][j]) % MOD;
    return r;
}

long long fib(long long n) {
    if (n < 0) return -1;
    Mat result{{{1, 0}, {0, 1}}};
    Mat base{{{1, 1}, {1, 0}}};
    while (n > 0) {
        if (n & 1) result = mul(result, base);
        base = mul(base, base);
        n >>= 1;
    }
    return result[0][1];
}

int main() {
    for (long long n = 0; n <= 10; ++n) {
        std::cout << "fib(" << n << ") = " << fib(n) << '\n';
    }
    // fib(90) fits the naive int range but the modulus keeps it exact anyway
    std::cout << "fib(90) mod 1e9+7 = " << fib(90) << '\n';
    if (fib(0) != 0 || fib(1) != 1 || fib(10) != 55) return 1;
    return 0;
}
```

O(log n) time. The identity matrix is the accumulator; squaring `base` each step handles the bits. Negative input returns -1 rather than looping forever.

```rust
fn longest_common_prefix(strs: &[&str]) -> String {
    let first = match strs.first() {
        Some(s) => *s,
        None => return String::new(),
    };

    let mut end = first.len();
    for s in &strs[1..] {
        end = end.min(s.len());
        let mut i = 0;
        let fb = first.as_bytes();
        let sb = s.as_bytes();
        while i < end && fb[i] == sb[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            return String::new();
        }
    }
    first[..end].to_string()
}

fn main() {
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&["dog", "racecar", "car"]), "");
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["alone"]), "alone");
    assert_eq!(longest_common_prefix(&["", "abc"]), "");
    assert_eq!(longest_common_prefix(&["café", "cafés"]), "café");

    println!("all prefix tests passed");
}
