A move-only FD wrapper with clear ownership semantics:

```cpp
#include <unistd.h>
#include <cerrno>
#include <cstring>
#include <fcntl.h>
#include <iostream>
#include <stdexcept>
#include <utility>

class Fd {
public:
    Fd() noexcept : fd_(-1) {}
    explicit Fd(int fd) noexcept : fd_(fd) {}

    // Move constructor: steal the handle, leave source empty.
    Fd(Fd&& other) noexcept : fd_(other.fd_) { other.fd_ = -1; }

    Fd& operator=(Fd&& other) noexcept {
        if (this != &other) {
            close();
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    Fd(const Fd&) = delete;
    Fd& operator=(const Fd&) = delete;

    ~Fd() { close(); }

    int get() const noexcept { return fd_; }
    explicit operator bool() const noexcept { return fd_ >= 0; }

    int release() noexcept { int f = fd_; fd_ = -1; return f; }

    void reset(int fd = -1) noexcept {
        if (fd_ == fd) return;
        close();
        fd_ = fd;
    }

private:
    void close() noexcept {
        if (fd_ >= 0) {
            // Retry EINTR; other errors are unrecoverable here.
            while (::close(fd_) == -1 && errno == EINTR) {}
            fd_ = -1;
        }
    }
    int fd_;
};

int main() {
    Fd in(::open("/etc/hostname", O_RDONLY));
    if (!in) { std::cerr << "open failed: " << std::strerror(errno) << "\n"; return 1; }
    Fd moved(std::move(in));       // in is now -1
    std::cout << "fd=" << moved.get() << " valid_in=" << static_cast<bool>(in) << "\n";
    return 0;
}
```

Double-close is impossible because `close()` resets the handle and `release()` clears it before transferring.

A hand-rolled RFC-4180-ish splitter for a single line:

```rust
/// Splits one CSV record, honouring double-quoted fields and "" escapes.
fn split_csv(line: &str) -> Result<Vec<String>, String> {
    let mut fields = Vec::new();
    let mut cur = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();

    while let Some(c) = chars.next() {
        if in_quotes {
            match c {
                '"' => {
                    if chars.peek() == Some(&'"') {
                        cur.push('"');
                        chars.next();
                    } else {
                        in_quotes = false;
                    }
                }
                other => cur.push(other),
            }
        } else {
            match c {
                ',' => { fields.push(std::mem::take(&mut cur)); }
                '"' => in_quotes = true,
                other => cur.push(other),
            }
        }
    }
    if in_quotes {
        return Err("unterminated quoted field".to_string());
    }
    fields.push(cur);
    Ok(fields)
}

fn main() {
    let line = r#"name,"Doe, John",42,"He said ""hi""""#;
    match split_csv(line) {
        Ok(f) => println!("{:?}", f),
        Err(e) => eprintln!("error: {e}"),
    }
    assert_eq!(split_csv("a,b,c").unwrap(), vec!["a", "b", "c"]);
    assert_eq!(split_csv("\"a,b\",c").unwrap(), vec!["a,b", "c"]);
    assert_eq!(split_csv("\"x\"").is_err(), true);
    println!("ok");
}
```

Escaped `""` collapses to a single quote inside a quoted field, and an unterminated quote is reported as an error rather than silently accepted.

```python
import threading
import time
from collections import deque


class BoundedQueue:
    """A blocking FIFO with a fixed capacity.

    put() blocks while full, get() blocks while empty. Both accept a timeout
    in seconds; None means wait forever. Raises Full/Empty on timeout.
    """

    class Full(Exception):
        pass

    class Empty(Exception):
        pass

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._cap = capacity
        self._q = deque()
        self._cv = threading.Condition()
        self._closed = False

    def put(self, item, timeout=None) -> None:
        deadline = None if timeout is None else time.monotonic() + timeout
        with self._cv:
            while len(self._q) >= self._cap and not self._closed:
                remaining = None
                if deadline is not None:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        raise self.Full()
                self._cv.wait(remaining)
            if self._closed:
                raise self.Full("queue is closed")
            self._q.append(item)
            self._cv.notify()

    def get(self, timeout=None):
        deadline = None if timeout is None else time.monotonic() + timeout
        with self._cv:
            while not self._q and not self._closed:
                remaining = None
                if deadline is not None:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        raise self.Empty()
                self._cv.wait(remaining)
            if not self._q:
                raise self.Empty("queue is closed")
            item = self._q.popleft()
            self._cv.notify()
            return item

    def close(self) -> None:
        with self._cv:
            self._closed = True
            self._cv.notify_all()


if __name__ == "__main__":
    q = BoundedQueue(2)
    seen = []

    def consumer():
        while True:
            try:
                seen.append(q.get(timeout=1.0))
            except BoundedQueue.Empty:
                break

    t = threading.Thread(target=consumer)
    t.start()
    for i in range(5):
        q.put(i)
    q.close()
    t.join()
    assert seen == [0, 1, 2, 3, 4], seen
    print("ok", seen)
```

`Condition` re-acquires the lock across `wait`, and using `time.monotonic()` for the deadline avoids clock-jump bugs. `close()` wakes everyone so consumers exit instead of hanging.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned char *data;
    size_t len;
    size_t cap;
    size_t elem_size;
    void (*destroy)(void *);
} Vec;

static int vec_init(Vec *v, size_t elem_size, void (*destroy)(void *)) {
    if (elem_size == 0) return -1;
    v->data = NULL;
    v->len = v->cap = 0;
    v->elem_size = elem_size;
    v->destroy = destroy;
    return 0;
}

static int vec_reserve(Vec *v, size_t want) {
    if (want <= v->cap) return 0;
    size_t newcap = v->cap ? v->cap * 2 : 8;
    while (newcap < want) newcap *= 2;
    unsigned char *p = realloc(v->data, newcap * v->elem_size);
    if (!p) return -1;
    v->data = p;
    v->cap = newcap;
    return 0;
}

static void *vec_push(Vec *v, const void *elem) {
    if (vec_reserve(v, v->len + 1) != 0) return NULL;
    void *slot = v->data + v->len * v->elem_size;
    memcpy(slot, elem, v->elem_size);
    v->len++;
    return slot;
}

static void *vec_get(const Vec *v, size_t i) {
    if (i >= v->len) return NULL;
    return v->data + i * v->elem_size;
}

static void vec_free(Vec *v) {
    if (v->destroy) {
        for (size_t i = 0; i < v->len; i++)
            v->destroy(v->data + i * v->elem_size);
    }
    free(v->data);
    v->data = NULL;
    v->len = v->cap = 0;
}

int main(void) {
    Vec v;
    if (vec_init(&v, sizeof(int), NULL) != 0) return 1;
    for (int i = 0; i < 100; i++) {
        if (!vec_push(&v, &i)) { fprintf(stderr, "push failed\n"); vec_free(&v); return 1; }
    }
    long sum = 0;
    for (size_t i = 0; i < v.len; i++) sum += *(int *)vec_get(&v, i);
    printf("len=%zu cap=%zu sum=%ld\n", v.len, v.cap, sum);
    if (sum != 4950) { vec_free(&v); return 1; }
    vec_free(&v);
    return 0;
}
```

`elem_size` lets the same code hold any POD type; `destroy` is an optional cleanup hook for types that own memory. Growth doubles so pushes are amortised O(1), and every allocation failure is checked.

```cpp
#include <cstddef>
#include <cstdio>

// --- Template metaprogramming version, O(N) instantiation depth.
template <std::size_t N>
struct FibT {
    static constexpr unsigned long long value =
        FibT<N - 1>::value + FibT<N - 2>::value;
};

template <> struct FibT<0> { static constexpr unsigned long long value = 0; };
template <> struct FibT<1> { static constexpr unsigned long long value = 1; };

// --- constexpr function version, C++17 allows loops in constexpr fns.
constexpr unsigned long long fib(std::size_t n) {
    if (n > 93) return 0; // overflow guard: fib(94) exceeds uint64
    unsigned long long a = 0, b = 1;
    for (std::size_t i = 0; i < n; ++i) {
        unsigned long long t = a + b;
        a = b;
        b = t;
    }
    return a;
}

static_assert(FibT<10>::value == 55, "fib(10) must be 55");
static_assert(fib(20) == 6765, "fib(20) must be 6765");
static_assert(fib(0) == 0 && fib(1) == 1, "base cases");

int main() {
    std::printf("FibT<20>=%llu  fib(20)=%llu  fib(50)=%llu\n",
                FibT<20>::value, fib(20), fib(50));
    return 0;
}
```

Both paths agree: `FibT<20>` and `fib(20)` evaluate to 6765. The template version recurses at compile time (depth equals N), so keep N modest; the `constexpr` function runs in O(N) steps and is the better choice for larger N.

