Padding appends `0x80`, zero-fills to 56 mod 64, then the big-endian 64-bit bit length. The empty-input digest asserts against the standard value so a padding bug can't slip through.

```python
from collections import OrderedDict


class LRUCache:
    """Least-recently-used cache with O(1) lookup, insert and eviction.

    get(key) marks the key as most-recently-used. When capacity is exceeded,
    the least-recently-used key is evicted and counted in `evictions`.
    """

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._cap = capacity
        self._d = OrderedDict()
        self.evictions = 0

    def get(self, key, default=None):
        if key not in self._d:
            return default
        self._d.move_to_end(key)  # O(1) mark as MRU
        return self._d[key]

    def put(self, key, value) -> None:
        if key in self._d:
            self._d.move_to_end(key)
        self._d[key] = value
        if len(self._d) > self._cap:
            self._d.popitem(last=False)  # evict LRU from the front
            self.evictions += 1

    def __contains__(self, key) -> bool:
        return key in self._d

    def __len__(self) -> int:
        return len(self._d)

    def keys_mru_to_lru(self):
        return list(reversed(self._d))


if __name__ == "__main__":
    c = LRUCache(3)
    for k in ("a", "b", "c"):
        c.put(k, k.upper())
    assert c.get("a") == "A"          # a becomes MRU
    c.put("d", "D")                   # evicts b (LRU)
    assert "b" not in c, "b should be evicted"
    assert c.get("b") is None
    assert c.evictions == 1
    assert c.keys_mru_to_lru() == ["d", "a", "c"], c.keys_mru_to_lru()
    c.put("a", "A2")                  # update existing, moves to end
    assert c.get("a") == "A2"
    assert c.evictions == 1
    print("ok, evictions =", c.evictions)
```

`OrderedDict.move_to_end` and `popitem(last=False)` are both O(1), so no manual doubly-linked list is needed. Updating an existing key keeps the eviction count unchanged.

