def two_largest(nums):
    """Return (largest, second_largest) distinct values, or None."""
    if not nums:
        return None
    best = second = None
    for x in nums:
        if best is None or x > best:
            if best != x:
                second = best
            best = x
        elif x != best and (second is None or x > second):
            second = x
    if second is None:
        return None
    return (best, second)


