// Parses "1, 2,,3" -> {1, 2, 3}. Returns nullopt on a non-numeric token.
std::optional<std::vector<long>> parse_ints(const std::string& csv) {
    std::vector<long> out;
    std::stringstream ss(csv);
    std::string token;
    while (std::getline(ss, token, ',')) {
        // trim ASCII whitespace
        size_t b = token.find_first_not_of(" \t\r\n");
        if (b == std::string::npos) continue; // empty field
        size_t e = token.find_last_not_of(" \t\r\n");
        std::string t = token.substr(b, e - b + 1);
        try {
            size_t used = 0;
            long v = std::stol(t, &used);
            if (used != t.size()) return std::nullopt;
            out.push_back(v);
        } catch (...) {
            return std::nullopt;
        }
    }
    return out;
}
