/// Returns Ok(()) if all (), [], {} are balanced and nested correctly,
/// or Err(index) of the first unmatched character.
pub fn check_balance(s: &str) -> Result<(), usize> {
    let mut stack: Vec<(char, usize)> = Vec::new();
    for (i, c) in s.chars().enumerate() {
        match c {
            '(' | '[' | '{' => stack.push((c, i)),
            ')' | ']' | '}' => {
                let want = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some((open, _)) if open == want => {}
                    _ => return Err(i),
                }
            }
            _ => {}
        }
    }
    stack.first().map(|&(_, i)| i).ok_or(()).map_or(Ok(()), Err)
}

fn main() {
    assert_eq!(check_balance("a(b[c]{d})e"), Ok(()));
    assert_eq!(check_balance("([)]"), Err(2));
    assert_eq!(check_balance("("), Err(0));
}
```

