```python
import functools
import time
from typing import Callable, TypeVar

T = TypeVar("T")


def retry(attempts: int = 3, base_delay: float = 0.1,
          exceptions: tuple = (Exception,)) -> Callable[[Callable[..., T]], Callable[..., T]]:
    """Retry a callable up to `attempts` times with exponential backoff."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(fn: Callable[..., T]) -> Callable[..., T]:
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt < attempts - 1:
                        time.sleep(base_delay * (2 ** attempt))
            raise last  # re-raise the final failure
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=3, base_delay=0.0)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return "ok"

    assert flaky() == "ok"
    assert calls["n"] == 3
    print("ok")
```

It re-raises the last exception only after the final attempt, so a genuine failure is never silently swallowed.

```cpp
#include <array>
#include <cstddef>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == N) return false;
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T value = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --count_;
        return value;
    }

    bool full() const { return count_ == N; }
    bool empty() const { return count_ == 0; }
    std::size_t size() const { return count_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    if (rb.push(4)) return 1;          // full
    if (!rb.pop() || !rb.empty()) {}
    rb.pop(); rb.pop();
    return rb.empty() ? 0 : 1;
}
```

Tracking `count_` avoids the classic full/empty ambiguity when `head_ == tail_`, so the buffer can hold all `N` slots.

