import heapq

class MinHeap:
    def __init__(self):
        self._data = []

    def push(self, value):
        heapq.heappush(self._data, value)

    def pop(self):
        if not self._data:
            raise IndexError("pop from empty heap")
        return heapq.heappop(self._data)

    def peek(self):
        if not self._data:
            raise IndexError("peek from empty heap")
        return self._data[0]

    def __len__(self):
        return len(self._data)

h = MinHeap()
for v in [5, 3, 8, 1, 9, 2]:
    h.push(v)
assert h.peek() == 1
assert [h.pop() for _ in range(6)] == [1, 2, 3, 5, 8, 9]
empty = MinHeap()
try:
    empty.pop()
except IndexError:
    pass
else:
