#include <cassert>
#include <climits>
#include <iostream>

bool isPalindrome(int x) {
    if (x < 0) return false;              // negative numbers never match
    if (x != 0 && x % 10 == 0) return false; // trailing zero only ok for 0
    long long rev = 0;
    int n = x;
    while (n > 0) {
        rev = rev * 10 + n % 10;
        n /= 10;
        if (rev > INT_MAX) return false;  // guard overflow before final compare
    }
    return static_cast<int>(rev) == x;
}

int main() {
    assert(isPalindrome(0));
    assert(isPalindrome(121));
    assert(!isPalindrome(-121));
    assert(!isPalindrome(10));
    assert(isPalindrome(2147447412));
    assert(!isPalindrome(2147483647));
    std::cout << std::boolalpha << isPalindrome(12321) << '\n';
    return 0;
}
