use std::env;
use std::fs;
use std::process;

fn parse_numbers(text: &str) -> Result<Vec<f64>, String> {
    let mut values = Vec::new();
    for (i, line) in text.lines().enumerate() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let value: f64 = trimmed
            .parse()
            .map_err(|_| format!("line {}: not a number: {}", i + 1, trimmed))?;
        values.push(value);
    }
    Ok(values)
}

fn main() -> Result<(), String> {
    let path = env::args().nth(1).unwrap_or_else(|| "numbers.txt".to_string());
    let text = fs::read_to_string(&path)
        .map_err(|e| format!("could not read {}: {}", path, e))?;

    let values = parse_numbers(&text)?;
    if values.is_empty() {
        println!("no numbers found");
        return Ok(());
    }

    let n = values.len() as f64;
    let mean = values.iter().sum::<f64>() / n;
    let variance = values.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / n;
    println!("n={} mean={:.4} stddev={:.4}", values.len(), mean, variance.sqrt());
    Ok(())
}

fn main_guard() {
    if let Err(e) = main() {
        eprintln!("error: {}", e);
        process::exit(1);
    }
}
