def parse_config(text: str) -> dict:
    """Parse lines of `key = value`, dropping blanks and # comments.

    Values keep their internal spaces; keys are stripped. A line without
    '=' is an error, so malformed configs fail loudly instead of silently.
    """
    cfg = {}
    for lineno, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ValueError(f"line {lineno}: missing '=' in {line!r}")
        key, _, value = line.partition("=")
        cfg[key.strip()] = value.strip()
    return cfg


if __name__ == "__main__":
    cfg = parse_config("# app\nname = demo\npath=/tmp/a b\n\nport = 8080\n")
    assert cfg == {"name": "demo", "path": "/tmp/a b", "port": "8080"}, cfg
    assert parse_config("") == {}
    try:
        parse_config("oops")
    except ValueError as e:
        assert "line 1" in str(e)
    print("ok")
