```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>

// A fixed-capacity FIFO. push blocks while full; pop blocks while empty.
// close() wakes all waiters and makes further push/pop fail fast.
template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t cap) : cap_(cap) {
        if (cap == 0) throw std::invalid_argument("capacity must be > 0");
    }

    // Returns false once the queue is closed.
    bool push(T value) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [&] { return closed_ || q_.size() < cap_; });
        if (closed_) return false;
        q_.push(std::move(value));
        not_empty_.notify_one();
        return true;
    }

    // Returns std::nullopt when the queue is closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;  // closed and empty
        T v = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lk(m_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lk(m_);
        return q_.size();
    }

private:
    mutable std::mutex m_;
    std::condition_variable not_full_, not_empty_;
    std::queue<T> q_;
    std::size_t cap_;
    bool closed_ = false;
};
```

Each wait uses a predicate so spurious wakeups can't corrupt state; `close()` is the single shutdown path. Compile with `-std=c++17 -pthread`.

