// Owns a FILE*; closes it on destruction. Move-only, not copyable.
class File {
public:
    File(const std::string& path, const char* mode) {
        fp_ = std::fopen(path.c_str(), mode);
        if (!fp_) throw std::runtime_error("cannot open " + path);
        path_ = path;
    }

    ~File() { if (fp_) std::fclose(fp_); }

    File(const File&) = delete;
    File& operator=(const File&) = delete;

    File(File&& other) noexcept : fp_(other.fp_), path_(std::move(other.path_)) {
        other.fp_ = nullptr;
    }

    File& operator=(File&& other) noexcept {
        if (this != &other) {
            if (fp_) std::fclose(fp_);
            fp_ = other.fp_;
            path_ = std::move(other.path_);
            other.fp_ = nullptr;
        }
        return *this;
    }

    std::FILE* get() const { return fp_; }

    // Writes the whole buffer, or throws if any byte is short.
    void write_all(const char* data, std::size_t n) {
        if (std::fwrite(data, 1, n, fp_) != n)
            throw std::runtime_error("short write to " + path_);
    }

private:
    std::FILE* fp_ = nullptr;
    std::string path_;
};
