```rust
/// A fixed-capacity FIFO. Pushing onto a full buffer overwrites the oldest item.
pub struct RingBuffer<T> {
    buf: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        RingBuffer { buf: (0..capacity).map(|_| None).collect(), head: 0, len: 0 }
    }

    pub fn capacity(&self) -> usize { self.buf.len() }
    pub fn len(&self) -> usize { self.len }
    pub fn is_empty(&self) -> bool { self.len == 0 }

    pub fn push(&mut self, value: T) {
        let cap = self.buf.len();
        let idx = (self.head + self.len) % cap;
        self.buf[idx] = Some(value);
        if self.len == cap {
            self.head = (self.head + 1) % cap; // drop oldest
        } else {
            self.len += 1;
        }
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 { return None; }
        let v = self.buf[self.head].take();
        self.head = (self.head + 1) % self.buf.len();
        self.len -= 1;
        v
    }

    pub fn iter(&self) -> impl Iterator<Item = &T> {
        let cap = self.buf.len();
        (0..self.len).filter_map(move |i| self.buf[(self.head + i) % cap].as_ref())
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    for i in 1..=3 { rb.push(i); }
    assert_eq!(rb.iter().copied().collect::<Vec<_>>(), vec![1, 2, 3]);
    rb.push(4); // evicts 1
    assert_eq!(rb.iter().copied().collect::<Vec<_>>(), vec![2, 3, 4]);
    assert_eq!(rb.pop(), Some(2));
    assert_eq!(rb.pop(), Some(3));
    assert_eq!(rb.pop(), Some(4));
    assert_eq!(rb.pop(), None);
    println!("ok");
}
```

Modular indexing keeps head/len consistent; overwrite-on-full means capacity is never exceeded.

