/// Split one CSV logical line into fields.
/// Quoted fields may contain commas and "" for a literal quote.
/// Returns an error on an unterminated quote.
pub fn parse_csv_line(line: &str) -> Result<Vec<String>, String> {
    let mut fields = Vec::new();
    let mut cur = String::new();
    let mut chars = line.chars().peekable();
    let mut in_quotes = false;

    while let Some(c) = chars.next() {
        if in_quotes {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    cur.push('"');
                    chars.next();
                } else {
                    in_quotes = false;
                }
            } else {
                cur.push(c);
            }
        } else if c == '"' {
            in_quotes = true;
        } else if c == ',' {
            fields.push(std::mem::take(&mut cur));
        } else {
            cur.push(c);
        }
    }

    if in_quotes {
        return Err("unterminated quote".to_string());
    }
    fields.push(cur);
    Ok(fields)
}

fn main() {
    let got = parse_csv_line(r#"a,"b,c","say ""hi""",d"#).unwrap();
    assert_eq!(got, vec!["a", "b,c", "say \"hi\"", "d"]);
    assert_eq!(parse_csv_line("").unwrap(), vec![""]);
    assert!(parse_csv_line("\"oops").is_err());
    println!("ok");
}
```

The `peekable` iterator lets a doubled quote consume both characters before deciding whether the field ends.

