struct Node { int value; struct Node *next; };

static struct Node *push(struct Node *head, int v) {
    struct Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(1); }
    n->value = v;
    n->next = head;
    return n;
}

static void print_list(const struct Node *head) {
    for (const struct Node *n = head; n; n = n->next)
        printf("%d%s", n->value, n->next ? " -> " : "\n");
    if (!head) printf("(empty)\n");
}

static struct Node *reverse(struct Node *head) {
    struct Node *prev = NULL;
    while (head) {
        struct Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main(void) {
    struct Node *head = NULL;
    for (int i = 5; i >= 1; --i) head = push(head, i);
    print_list(head);
    head = reverse(head);
    print_list(head);
    while (head) { struct Node *n = head->next; free(head); head = n; }
    return 0;
}
