std::vector<std::string> split_and_trim(const std::string& s, char delim) {
    std::vector<std::string> out;
    std::string current;
    auto flush = [&]() {
        size_t start = current.find_first_not_of(" \t\r\n");
        if (start == std::string::npos) { current.clear(); return; }
        size_t end = current.find_last_not_of(" \t\r\n");
        out.push_back(current.substr(start, end - start + 1));
        current.clear();
    };
    for (char ch : s) {
        if (ch == delim) flush();
        else current += ch;
    }
    flush();
    return out;
}

int main() {
