from typing import List, Optional


def binary_search(nums: Optional[List[int]], target: int) -> int:
    """Return an index of *target* in ascending *nums*, or -1."""
    if not nums:
        return -1

    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2  # avoids overflow-style math in other langs
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


