```cpp
#include <fcntl.h>
#include <unistd.h>

#include <utility>

class FileHandle {
public:
    FileHandle() noexcept = default;

    explicit FileHandle(int fd) noexcept : fd_(fd) {}

    static FileHandle open(const char* path, int flags) noexcept {
        return FileHandle(::open(path, flags));
    }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fd_(other.release()) {}

    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            reset(other.release());
        }
        return *this;
    }

    ~FileHandle() { reset(-1); }

    int get() const noexcept { return fd_; }
    bool valid() const noexcept { return fd_ >= 0; }

    void reset(int new_fd = -1) noexcept {
        if (fd_ >= 0) {
            ::close(fd_);  // retrying close() risks closing a reused fd
        }
        fd_ = new_fd;
    }

private:
    int fd_ = -1;
};
```

Deleting the copy operations makes ownership unique; the move operations steal the descriptor and leave the source at `-1` via `release()` (through `other.release()` setting it in the move constructor — if you prefer, add a private `release()` that zeroes the source). `reset` closes the old descriptor before adopting the new one, so assignment never leaks.

