```c
#include <stddef.h>
#include <stdio.h>
#include <string.h>

char *reverse_in_place(char *s) {
    if (s == NULL) {
        return NULL;
    }
    size_t len = strlen(s);
    if (len < 2) {
        return s;
    }
    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
    return s;
}

int main(void) {
    char empty[] = "";
    char single[] = "a";
    char word[] = "hello";
    char unicode[] = "na\xc3\xafve";  /* naive, UTF-8 bytes */

    printf("[%s]\n", reverse_in_place(empty));
    printf("[%s]\n", reverse_in_place(single));
    printf("[%s]\n", reverse_in_place(word));
    printf("[%s]\n", reverse_in_place(unicode));
    printf("[%s]\n", reverse_in_place(NULL) == NULL ? "(null)" : "?");
    return 0;
}
```

Reversing UTF-8 bytes corrupts multibyte characters, so `naïve` prints as mangled bytes; a code-point-safe version would decode to `uint32_t` before swapping. The swap uses `i < j`, so the middle character of an odd-length string is left alone. A `NULL` argument returns `NULL` instead of dereferencing.

