std::vector<int> sieve(int limit) {
    std::vector<bool> isComposite(limit + 1, false);
    std::vector<int> primes;
    for (int i = 2; i <= limit; ++i) {
        if (!isComposite[i]) {
            primes.push_back(i);
            for (long long j = 1LL * i * i; j <= limit; j += i) {
                isComposite[static_cast<int>(j)] = true;
            }
        }
    }
    return primes;
}

int main(int argc, char** argv) {
    int limit = (argc > 1) ? std::atoi(argv[1]) : 50;
    if (limit < 2) {
        std::cout << "no primes below " << limit << "\n";
        return 0;
    }
    std::vector<int> primes = sieve(limit);
    for (int p : primes) std::cout << p << '\n';
    std::cout << "count=" << primes.size() << "\n";
    return 0;
}
