```cpp
#include <cstddef>
#include <iostream>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), capacity_(capacity), size_(0), next_(0) {}

    void push(int value) {
        if (capacity_ == 0) return;
        buf_[next_] = value;
        next_ = (next_ + 1) % capacity_;
        if (size_ < capacity_) ++size_;
    }

    // Most recent count values, oldest-first. Capped at what is stored.
    std::vector<int> recent(std::size_t count) const {
        if (count > size_) count = size_;
        std::vector<int> out;
        out.reserve(count);
        std::size_t start = (next_ + capacity_ - count) % capacity_;
        for (std::size_t i = 0; i < count; ++i)
            out.push_back(buf_[(start + i) % capacity_]);
        return out;
    }

private:
    std::vector<int> buf_;
    std::size_t capacity_;
    std::size_t size_;
    std::size_t next_;
};

int main() {
    RingBuffer rb(3);
    for (int v : {1, 2, 3, 4, 5}) rb.push(v);
    std::vector<int> last = rb.recent(3);
    for (int v : last) std::cout << v << ' ';  // 3 4 5
    std::cout << "\n";

    RingBuffer empty(0);
    empty.push(7);                            // no-op
    std::cout << empty.recent(5).size() << "\n";  // 0
    return 0;
}
```
`recent` computes the start index modularly so it never reorders entries. A zero capacity is handled without dividing by zero.

```cpp
#include <climits>
#include <iostream>
#include <optional>
#include <string>

std::optional<long long> parse_ll(const std::string& s) {
    std::size_t i = 0, n = s.size();
    if (n == 0) return std::nullopt;

    bool neg = false;
    if (s[i] == '+' || s[i] == '-') {
        neg = (s[i] == '-');
        ++i;
    }
    if (i == n) return std::nullopt;  // sign only

    unsigned long long acc = 0;
    const unsigned long long limit = neg
        ? static_cast<unsigned long long>(LLONG_MAX) + 1ULL
        : static_cast<unsigned long long>(LLONG_MAX);

    for (; i < n; ++i) {
        char c = s[i];
        if (c < '0' || c > '9') return std::nullopt;  // trailing junk
        unsigned d = static_cast<unsigned>(c - '0');
        if (acc > (limit - d) / 10) return std::nullopt;  // would overflow
        acc = acc * 10 + d;
    }

    if (neg) return acc == limit ? LLONG_MIN
                                 : -static_cast<long long>(acc);
    return static_cast<long long>(acc);
}

int main() {
    std::cout << parse_ll("42").value_or(-1) << "\n";           // 42
    std::cout << (parse_ll("12x") ? 1 : 0) << "\n";              // 0
    std::cout << (parse_ll("99999999999999999999") ? 1 : 0) << "\n";  // 0
    std::cout << parse_ll("-9223372036854775808").value_or(0) << "\n";  // LLONG_MIN
    return 0;
}
```
Overflow is checked *before* multiplying, using the exact per-sign limit, so `LLONG_MIN` parses and one past it does not. Any non-digit ends the parse with `nullopt` instead of silently truncating.

