```cpp
#include <cstddef>
#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity ? new int[capacity] : nullptr), cap_(capacity) {}

    ~RingBuffer() { delete[] data_; }

    RingBuffer(const RingBuffer&) = delete;
    RingBuffer& operator=(const RingBuffer&) = delete;

    bool push(int value) {
        if (size_ == cap_) return false;      // full
        data_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt; // empty
        int v = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return cap_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == cap_; }

private:
    int* data_;
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    if (rb.capacity() != 3 || !rb.empty()) return 1;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;                 // must reject, it is full
    if (rb.pop() != 1) return 1;
    if (!rb.push(4)) return 1;                // wrap-around slot is free
    if (rb.pop() != 2 || rb.pop() != 3 || rb.pop() != 4) return 1;
    if (rb.pop().has_value()) return 1;       // empty now
    std::cout << "all checks passed\n";
}
```

Indices wrap with `% cap_`. The buffer stores at `(head_ + size_) % cap_` and reads from `head_`, so push and pop never need to shift elements. A zero-capacity buffer is handled by allocating nothing and treating every push as full. I deleted the copy constructor because the class owns a raw array; add a move constructor and assignment if you want to transfer ownership safely.

