long sum_until_noninteger(std::istream& in) {
    long total = 0;
    long value;
    while (in >> value) {
        total += value;
    }
    return total;
}

int main() {
    // Whole line, stop at the first token that is not an integer.
    std::istringstream line("10 20 30 stop 40");
    if (sum_until_noninteger(line) != 60) return 1;

    // Empty line -> 0, nothing consumed, stream stays usable.
    std::istringstream empty("");
    if (sum_until_noninteger(empty) != 0) return 1;

    // Leading junk: first read fails immediately.
    std::istringstream junk("abc 5");
    if (sum_until_noninteger(junk) != 0) return 1;

    // Negative values and large sums.
    std::istringstream neg("-5 -15 100");
    if (sum_until_noninteger(neg) != 80) return 1;

    std::cout << "all checks passed\n";
}
