use std::collections::HashMap;
use std::io::{self, Read};

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for raw in text.split(|c: char| !c.is_alphanumeric() && c != '\'') {
        let word = raw.to_lowercase();
        if word.is_empty() {
            continue;
        }
        *counts.entry(word).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count descending, then word ascending.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text).expect("failed to read stdin");
    for (word, count) in top_words(&text, 10) {
        println!("{:>6}  {}", count, word);
    }
}

