```python
from collections import OrderedDict
from typing import Optional


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key) -> Optional[int]:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value: int) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)   # evict least-recently used

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, 1)
    c.put(2, 2)
    assert c.get(1) == 1          # 1 is now most recently used
    c.put(3, 3)                   # evicts 2, not 1
    assert c.get(2) is None
    assert c.get(3) == 3
    c.put(1, 10)                  # update existing key, no eviction
    assert c.get(1) == 10
    assert len(c) == 2
    c.put(4, 4)                   # evicts 3
    assert c.get(3) is None
    assert c.get(4) == 4
    try:
        LRUCache(0)
    except ValueError:
        pass
    else:
        raise AssertionError("zero capacity should not be allowed")
    print("all checks passed")
```

A single `OrderedDict` gives O(1) get, put, and eviction. `move_to_end` marks a key as recently used on both `get` and a re-`put`. `popitem(last=False)` removes from the front, which is the least-recently used end. I rejected zero capacity at construction rather than silently doing nothing, so a misconfigured cache fails loudly.

