def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    # Transform: "abba" -> "^#a#b#b#a#$"
    t = "^#" + "#".join(s) + "#$"
    n = len(t)
    p = [0] * n
    center = right = 0
    for i in range(1, n - 1):
        mirror = 2 * center - i
        if i < right:
            p[i] = min(right - i, p[mirror])
        while t[i + p[i] + 1] == t[i - p[i] - 1]:
            p[i] += 1
        if i + p[i] > right:
            center, right = i, i + p[i]
    length, center_idx = max((p[i], i) for i in range(1, n - 1))
    start = (center_idx - length) // 2
    return s[start:start + length]


if __name__ == "__main__":
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "abacaba"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```
The `^` and `$` sentinels never match a real character, so the inner `while` cannot run off the ends. Empty input is handled before the transform. Expected output: `babad -> 'bab'`, `cbbd -> 'bb'`, `'' -> ''`, `a -> 'a'`, `forgeeksskeegfor -> 'geeksskeeg'`, `abacaba -> 'abacaba'`.

