use std::fmt;

#[derive(Debug, PartialEq)]
enum CsvError {
    Empty,
    WrongFieldCount { expected: usize, got: usize },
}

impl fmt::Display for CsvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CsvError::Empty => write!(f, "row is empty"),
            CsvError::WrongFieldCount { expected, got } => {
                write!(f, "expected {expected} fields, got {got}")
            }
        }
    }
}

impl std::error::Error for CsvError {}

fn check_row(row: &str, expected: usize) -> Result<Vec<&str>, CsvError> {
    if row.trim().is_empty() {
        return Err(CsvError::Empty);
    }
    let fields: Vec<&str> = row.split(',').map(str::trim).collect();
    if fields.len() != expected {
        return Err(CsvError::WrongFieldCount { expected, got: fields.len() });
    }
    Ok(fields)
}

fn main() {
    assert_eq!(check_row("a, b, c", 3).unwrap(), vec!["a", "b", "c"]);
    assert_eq!(check_row("", 3), Err(CsvError::Empty));
    assert_eq!(
        check_row("a,b", 3),
        Err(CsvError::WrongFieldCount { expected: 3, got: 2 })
    );
    println!("ok");
}
