#include <array>
#include <cstdint>
#include <iostream>

using u64 = std::uint64_t;
constexpr u64 MOD = 1'000'000'007ULL;

// Returns {F(n), F(n+1)} modulo MOD.
static std::array<u64, 2> fib_pair(u64 n) {
    if (n == 0) return {0ULL, 1ULL};
    auto [a, b] = fib_pair(n >> 1);          // F(k), F(k+1) with k = n/2
    u64 c = a * ((2 * b % MOD + MOD - a) % MOD) % MOD;  // F(2k)
    u64 d = (a * a % MOD + b * b % MOD) % MOD;          // F(2k+1)
    if (n & 1ULL) return {d, (c + d) % MOD};
    return {c, d};
}

u64 fib_mod(u64 n) { return fib_pair(n)[0]; }

int main() {
    std::cout << fib_mod(0) << '\n';
    std::cout << fib_mod(1) << '\n';
    std::cout << fib_mod(10) << '\n';
    std::cout << fib_mod(90) << '\n';
    std::cout << fib_mod(1'000'000) << '\n';
}
```
Fast doubling computes `F(2k)` and `F(2k+1)` from `F(k), F(k+1)` in O(log n). The `+ MOD` before the subtraction keeps the intermediate non-negative under `u64` arithmetic. Expected output starts `0`, `1`, `55`, `2880067194370816120 % MOD = 2880067194370816120` for n=90 (the exact F(90) is 2880067194370816120), and a value for one million. Inputs beyond `u64` range are not handled; callers should clamp `n`.

