#include <algorithm>
#include <iostream>
#include <string>

std::string reverse_words(const std::string& s) {
    std::string out;
    int i = 0;
    int n = static_cast<int>(s.size());
    while (i < n) {
        while (i < n && s[i] == ' ') ++i;
        if (i >= n) break;
        int j = i;
        while (j < n && s[j] != ' ') ++j;
        if (!out.empty()) out += ' ';
        out.append(s, i, j - i);
        i = j;
    }
    std::reverse(out.begin(), out.end());
    for (int a = 0, b = 0; a <= static_cast<int>(out.size()); ++a) {
        if (a == static_cast<int>(out.size()) || out[a] == ' ') {
            std::reverse(out.begin() + b, out.begin() + a);
            b = a + 1;
        }
    }
    return out;
}

int main() {
    std::cout << reverse_words("  the quick   brown fox  ") << '\n';
    std::cout << reverse_words("hello") << '\n';
    return 0;
}
