def fib(n: int) -> int:
    """Return the nth Fibonacci number (F(0)=0, F(1)=1) via fast doubling."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def _fd(k: int):
        if k == 0:
            return (0, 1)
        a, b = _fd(k >> 1)
        c = a * (2 * b - a)        # F(2k)
        d = a * a + b * b          # F(2k+1)
        if k & 1:
            return (d, c + d)
        return (c, d)

    return _fd(n)[0]


