#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;
    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char t = s[i];
        s[i] = s[j];
        s[j] = t;
    }
}

int main(void) {
    char buf1[] = "hello world";
    reverse_in_place(buf1);
    printf("%s\n", buf1);          /* dlrow olleh */

    char buf2[] = "";
    reverse_in_place(buf2);
    printf("[%s]\n", buf2);        /* [] */

    char buf3[] = "a";
    reverse_in_place(buf3);
    printf("%s\n", buf3);          /* a */

    reverse_in_place(NULL);          /* must not crash */
    return 0;
}
```

Two indices walk toward each other and swap until they meet, so a single pass and no extra allocation. The `len < 2` guard covers the empty string and the one-character case, and the `NULL` check makes the function safe when called blindly.

```rust
fn first_index(sorted: &[i32], target: i32) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = sorted.len();          // exclusive upper bound
    let mut found: Option<usize> = None;
    while lo < hi {
        let mid = lo + (hi - lo) / 2;   // avoids overflow
        if sorted[mid] < target {
            lo = mid + 1;
        } else {
            if sorted[mid] == target {
                found = Some(mid);
            }
            hi = mid;                    // keep searching left half
        }
    }
    found
}

fn main() {
    assert_eq!(first_index(&[1, 2, 2, 2, 3, 4], 2), Some(1));
    assert_eq!(first_index(&[1, 3, 5], 0), None);
    assert_eq!(first_index(&[], 7), None);
    assert_eq!(first_index(&[4, 4, 4], 4), Some(0));
    assert_eq!(first_index(&[1, 3, 5], 5), Some(2));
    println!("ok");
}
```

