```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 4096
#define MAX_WORD 64

struct entry {
    char word[MAX_WORD];
    long count;
    struct entry *next;
};

static struct entry *table[TABLE_SIZE];

static unsigned long hash(const char *s) {
    unsigned long h = 5381;
    while (*s) h = h * 33u + (unsigned char)*s++;
    return h % TABLE_SIZE;
}

static void add(const char *word) {
    unsigned long h = hash(word);
    for (struct entry *e = table[h]; e; e = e->next) {
        if (strcmp(e->word, word) == 0) { e->count++; return; }
    }
    struct entry *e = malloc(sizeof *e);
    if (!e) { perror("malloc"); exit(1); }
    snprintf(e->word, sizeof e->word, "%s", word);
    e->count = 1;
    e->next = table[h];
    table[h] = e;
}

static void free_all(void) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        struct entry *e = table[i];
        while (e) { struct entry *n = e->next; free(e); e = n; }
    }
}

int main(void) {
    char buf[MAX_WORD];
    int c, len = 0;
    while ((c = getchar()) != EOF) {
        if (isalpha((unsigned char)c)) {
            if (len < MAX_WORD - 1) buf[len++] = (char)tolower((unsigned char)c);
        } else if (len > 0) {
            buf[len] = '\0';
            add(buf);
            len = 0;
        }
    }
    if (len > 0) { buf[len] = '\0'; add(buf); }

    struct entry *best[3] = {0, 0, 0};
    for (int i = 0; i < TABLE_SIZE; i++) {
        for (struct entry *e = table[i]; e; e = e->next) {
            for (int k = 0; k < 3; k++) {
                if (!best[k] || e->count > best[k]->count) {
                    for (int j = 2; j > k; j--) best[j] = best[j - 1];
                    best[k] = e;
                    break;
                }
            }
        }
    }
    for (int k = 0; k < 3; k++)
        if (best[k]) printf("%s %ld\n", best[k]->word, best[k]->count);

    free_all();
    return 0;
