```python
import functools


class _LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.store = {}
        self.hits = 0
        self.misses = 0

    def get(self, key):
        if key not in self.store:
            self.misses += 1
            return None, False
        value = self.store.pop(key)
        self.store[key] = value  # move to most-recent end
        self.hits += 1
        return value, True

    def put(self, key, value):
        if key in self.store:
            self.store.pop(key)
        elif len(self.store) >= self.capacity:
            oldest = next(iter(self.store))
            del self.store[oldest]
        self.store[key] = value


def lru_cache(capacity: int):
    def decorator(func):
        cache = _LRUCache(capacity)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            value, found = cache.get(key)
            if found:
                return value
            result = func(*args, **kwargs)
            cache.put(key, result)
            return result

        wrapper.cache_info = lambda: {"hits": cache.hits, "misses": cache.misses}
        return wrapper

    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @lru_cache(2)
    def square(x):
        calls["n"] += 1
        return x * x

    assert square(2) == 4
    assert square(2) == 4
    assert square(3) == 9
    assert square(4) == 16  # evicts the entry for 2
    assert square(2) == 4   # recomputed
    assert calls["n"] == 4
    info = square.cache_info()
    assert info == {"hits": 1, "misses": 4}, info
    print("ok")
```

Keyword arguments are normalized into a sorted tuple so hashability is stable and `square(x=2)` shares a key with `square(2)`. Hits and misses live on the closure and are exposed through `cache_info`.

```cpp
#include <cstdint>
#include <iostream>
#include <queue>
#include <vector>

class MedianTracker {
public:
    void add(std::int64_t value) {
        if (lower_.empty() || value <= lower_.top()) {
            lower_.push(value);
        } else {
            upper_.push(value);
        }
        rebalance();
    }

    // Requires at least one element to have been added.
    double median() const {
        if (lower_.size() > upper_.size()) {
            return static_cast<double>(lower_.top());
        }
        return (static_cast<double>(lower_.top()) +
                static_cast<double>(upper_.top())) / 2.0;
    }

private:
    void rebalance() {
        // lower_ holds the smaller half; keep sizes within one.
        if (lower_.size() > upper_.size() + 1) {
            upper_.push(lower_.top());
            lower_.pop();
        } else if (upper_.size() > lower_.size()) {
            lower_.push(upper_.top());
            upper_.pop();
        }
    }

    std::priority_queue<std::int64_t> lower_;                                // max-heap
    std::priority_queue<std::int64_t, std::vector<std::int64_t>,
                        std::greater<std::int64_t>> upper_;                  // min-heap
};

int main() {
    MedianTracker tracker;
    std::int64_t value = 0;
    std::size_t count = 0;
    while (std::cin >> value) {
        tracker.add(value);
        ++count;
    }
    if (count == 0) {
        std::cerr << "no input\n";
        return 1;
    }
    std::cout << tracker.median() << '\n';
    return 0;
}
```

The lower heap stores the smaller half as a max-heap, the upper heap stores the larger half as a min-heap, and they are kept balanced so the median is the lone top or the average of the two tops. `std::int64_t` avoids overflow on wide inputs.

