use std::collections::HashMap;
use std::fmt;

#[derive(Debug, PartialEq)]
pub enum ConfigError {
    MissingEquals(String),
    EmptyKey(String),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::MissingEquals(field) => {
                write!(f, "field `{field}` has no `=`")
            }
            ConfigError::EmptyKey(field) => {
                write!(f, "field `{field}` has an empty key")
            }
        }
    }
}

/// Parse `a=1; b=2;;c=3` into a map. Blank fields are skipped.
pub fn parse_config(line: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut out = HashMap::new();
    for field in line.split(';') {
        let field = field.trim();
        if field.is_empty() {
            continue;
        }
        let (key, value) = field
            .split_once('=')
            .ok_or_else(|| ConfigError::MissingEquals(field.to_string()))?;
        let key = key.trim();
        if key.is_empty() {
            return Err(ConfigError::EmptyKey(field.to_string()));
        }
        out.insert(key.to_string(), value.trim().to_string());
    }
    Ok(out)
}

fn main() {
    let map = parse_config(" host =localhost ; port=8080;; verbose =true ").unwrap();
    assert_eq!(map.get("host").map(String::as_str), Some("localhost"));
    assert_eq!(map.get("port").map(String::as_str), Some("8080"));
    assert_eq!(map.get("verbose").map(String::as_str), Some("true"));
    assert_eq!(map.len(), 3);

    assert_eq!(
        parse_config("good=1;bad field"),
        Err(ConfigError::MissingEquals("bad field".into()))
    );
    assert_eq!(
        parse_config("=nope"),
        Err(ConfigError::EmptyKey("=nope".into()))
    );
    assert!(parse_config("   ;  ; ").unwrap().is_empty());
    println!("ok");
}
```

`split_once('=')` keeps values containing `=` intact, `trim` on each side tolerates padding, blank fields are skipped, and missing `=` or an empty key produce distinct, displayable errors that carry the offending field.

```c
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CHUNK 4096

static int copy_reversed(const char *src, const char *dst) {
    FILE *in = fopen(src, "rb");
    if (!in) {
        fprintf(stderr, "open %s: %s\n", src, strerror(errno));
        return -1;
    }
    FILE *out = fopen(dst, "wb");
    if (!out) {
        fprintf(stderr, "open %s: %s\n", dst, strerror(errno));
        fclose(in);
        return -1;
    }

    if (fseek(in, 0, SEEK_END) != 0) {
        perror("fseek end");
        goto fail;
    }
    long length = ftell(in);
    if (length < 0) {
        perror("ftell");
        goto fail;
    }

    unsigned char buf[CHUNK];
    long remaining = length;
    while (remaining > 0) {
        long piece = remaining < CHUNK ? remaining : CHUNK;
        long start = remaining - piece;
        if (fseek(in, start, SEEK_SET) != 0) {
            perror("fseek set");
            goto fail;
        }
        size_t got = fread(buf, 1, (size_t)piece, in);
        if (got != (size_t)piece) {
            fprintf(stderr, "short read at %ld\n", start);
            goto fail;
        }
        for (long i = piece - 1; i >= 0; --i) {
            if (fputc(buf[i], out) == EOF) {
                perror("fputc");
                goto fail;
            }
        }
        remaining = start;
    }

    if (fclose(out) != 0 || fclose(in) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;

fail:
    fclose(in);
    fclose(out);
    return -1;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s <source> <destination>\n", argv[0]);
        return 2;
    }
    return copy_reversed(argv[1], argv[2]) == 0 ? 0 : 1;
}
```

The file is processed from the tail backwards in 4 KB chunks, so memory use stays constant regardless of file size. An empty file yields an empty output, and each error path closes both handles before returning.

