// Keeps ASCII letters and digits, drops every other byte (including UTF-8
// continuation bytes), so multi-byte code points are removed as a whole.
std::string keep_alnum_ascii(const std::string& input) {
    std::string out;
    out.reserve(input.size());
    for (unsigned char ch : input) {
        if ((ch & 0x80u) == 0 && std::isalnum(ch)) {
            out.push_back(static_cast<char>(ch));
        }
    }
    return out;
}

int main() {
    assert(keep_alnum_ascii("a-b_c 123") == "abc123");
    assert(keep_alnum_ascii("!!!") == "");
    assert(keep_alnum_ascii("") == "");
    // Multi-byte UTF-8 bytes all have the high bit set, so they are dropped.
    assert(keep_alnum_ascii("\xE6\x97\xA5x") == "x");
    std::cout << keep_alnum_ascii("Hello, World! 42") << '\n';
    return 0;
}
