```rust
#[derive(Debug, PartialEq)]
pub enum RleError {
    /// A run length exceeded what a u8 can hold.
    CountOverflow(usize),
}

/// Encode `data` as (count, byte) pairs. Runs longer than 255 are split.
pub fn encode(data: &[u8]) -> Result<Vec<(u8, u8)>, RleError> {
    let mut out = Vec::new();
    let mut iter = data.iter().copied().peekable();
    while let Some(byte) = iter.next() {
        let mut count: usize = 1;
        while iter.peek() == Some(&byte) {
            iter.next();
            count += 1;
            if count > 255 {
                return Err(RleError::CountOverflow(count));
            }
        }
        out.push((count as u8, byte));
    }
    Ok(out)
}

pub fn decode(pairs: &[(u8, u8)]) -> Vec<u8> {
    let mut out = Vec::new();
    for &(count, byte) in pairs {
        out.extend(std::iter::repeat(byte).take(count as usize));
    }
    out
}

fn main() {
    assert_eq!(encode(b"aaabbc").unwrap(), vec![(3, b'a'), (2, b'b'), (1, b'c')]);
    assert_eq!(encode(b"").unwrap(), Vec::new());
    assert_eq!(decode(&encode(b"aaabbc").unwrap()), b"aaabbc");
    let long = vec![7u8; 256];
    assert_eq!(encode(&long), Err(RleError::CountOverflow(256)));
    println!("ok");
}
```

A peekable iterator lets each run stay contiguous without boxing a second loop. The overflow check fires before the count is truncated, so a 256-byte run is rejected instead of silently wrapping to 0, and decoding round-trips on every accepted input.

