#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Reverse the bytes in [lo, hi). */
static void reverse_range(char *s, size_t lo, size_t hi) {
    while (lo < hi) {
        char t = s[lo];
        s[lo++] = s[hi - 1];
        s[hi-- - 1] = t;
    }
}

/* Reverse every word, then reverse the whole string. */
static void reverse_words(char *s) {
    size_t n = strlen(s);
    size_t i = 0;
    while (i < n) {
        while (i < n && isspace((unsigned char)s[i])) i++;
        size_t start = i;
        while (i < n && !isspace((unsigned char)s[i])) i++;
        reverse_range(s, start, i);
    }
    reverse_range(s, 0, n);
}

int main(void) {
    char buf[256];
    if (!fgets(buf, sizeof buf, stdin)) return 0;
    size_t n = strlen(buf);
    /* Drop the trailing newline so it does not become part of the output. */
    if (n > 0 && buf[n - 1] == '\n') buf[--n] = '\0';
    reverse_words(buf);
    puts(buf);
    return 0;
}
