/* Iterative Euclid. gcd(0, n) == n, gcd(0, 0) == 0. */
static unsigned long gcd_iter(unsigned long a, unsigned long b) {
    while (b != 0) {
        unsigned long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

/* Recursive euclid; depth is O(log min(a,b)). */
static unsigned long gcd_rec(unsigned long a, unsigned long b) {
    return b == 0 ? a : gcd_rec(b, a % b);
}

int main(void) {
    unsigned long pairs[][2] = {
        {48, 18}, {0, 5}, {0, 0}, {INT_MAX, 1}, {1071, 462}
    };
    for (size_t i = 0; i < sizeof pairs / sizeof pairs[0]; i++) {
        unsigned long a = pairs[i][0], b = pairs[i][1];
        printf("gcd(%lu, %lu) = iter %lu, rec %lu\n",
               a, b, gcd_iter(a, b), gcd_rec(a, b));
    }
    /* gcd(48,18)=6, gcd(0,5)=5, gcd(0,0)=0, gcd(1071,462)=21 */
    return 0;
}
