```python
from typing import Generic, TypeVar

T = TypeVar("T")

class StackEmpty(Exception):
    """Raised when popping from an empty stack."""

class StackFull(Exception):
    """Raised when pushing onto a full stack."""

class BoundedStack(Generic[T]):
    def __init__(self, capacity: int) -> None:
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._capacity = capacity
        self._items: list[T] = []

    def push(self, item: T) -> None:
        if len(self._items) >= self._capacity:
            raise StackFull(f"stack is full (capacity {self._capacity})")
        self._items.append(item)

    def pop(self) -> T:
        if not self._items:
            raise StackEmpty("pop from empty stack")
        return self._items.pop()

    def peek(self) -> T:
        if not self._items:
            raise StackEmpty("peek on empty stack")
        return self._items[-1]

    def __len__(self) -> int:
        return len(self._items)

    def __bool__(self) -> bool:
        return bool(self._items)

if __name__ == "__main__":
    s: BoundedStack[int] = BoundedStack(2)
    s.push(1)
    s.push(2)
    assert s.peek() == 2 and len(s) == 2
    try:
        s.push(3)
    except StackFull as e:
        print("overflow:", e)
    assert s.pop() == 2 and s.pop() == 1
    try:
        s.pop()
    except StackEmpty as e:
        print("underflow:", e)
```

The two custom exceptions make the failure mode explicit instead of surfacing an `IndexError`. `__bool__` lets callers write `if stack:` idiomatically.

