from collections import deque
from typing import Iterable, Iterator

def rolling_average(stream: Iterable[float], k: int) -> Iterator[float]:
    if k <= 0:
        raise ValueError("window size must be positive")
    window: deque[float] = deque()
    total = 0.0
    for value in stream:
        window.append(value)
        total += value
        if len(window) > k:
            total -= window.popleft()
        if len(window) == k:
            yield total / k


