```cpp
#include <cstddef>
#include <vector>
#include <iostream>

template <typename T>
std::ptrdiff_t binary_search_index(const std::vector<T>& data, const T& target) {
    std::ptrdiff_t lo = 0;
    std::ptrdiff_t hi = static_cast<std::ptrdiff_t>(data.size()) - 1;

    while (lo <= hi) {
        const std::ptrdiff_t mid = lo + (hi - lo) / 2;
        if (data[static_cast<std::size_t>(mid)] == target) {
            return mid;
        }
        if (data[static_cast<std::size_t>(mid)] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    const std::vector<int> values{1, 3, 5, 7, 9, 11};
    std::cout << binary_search_index(values, 7) << '\n';  // 3
    std::cout << binary_search_index(values, 4) << '\n';  // -1
    std::cout << binary_search_index(std::vector<int>{}, 1) << '\n';  // -1
    return 0;
}
```

`mid = lo + (hi - lo) / 2` avoids overflow. Signed `ptrdiff_t` bounds keep the empty-vector case (`hi = -1`) from wrapping, since the loop exits immediately. Returns the first matching index in a sorted range; duplicates are not guaranteed to give the lowest index.

