```c
#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* Copy src into a buffer of dst_size bytes. Always NUL-terminates when
 * dst_size > 0. Returns the number of bytes copied (excluding the NUL).
 * If truncation occurs, the return value equals dst_size - 1. */
size_t safe_copy(char *dst, size_t dst_size, const char *src) {
    if (dst == NULL || dst_size == 0) {
        return 0;
    }
    size_t i = 0;
    while (i + 1 < dst_size && src[i] != '\0') {
        dst[i] = src[i];
        ++i;
    }
    dst[i] = '\0';
    return i;
}

int main(void) {
    char buf[8];
    size_t n = safe_copy(buf, sizeof buf, "hello world");
    printf("%s (%zu)\n", buf, n);   /* hello w (7) */

    safe_copy(buf, sizeof buf, "hi");
    printf("%s\n", buf);            /* hi */

    char tiny[1];
    safe_copy(tiny, sizeof tiny, "x");
    printf("'%s'\n", tiny);         /* '' */
    return 0;
}
```

The loop keeps one byte free for the terminator, so it never overflows. The `dst_size == 0` guard means `tiny` holds just `\0`, which is why it prints empty. Return value signals truncation without relying on `errno`.

```rust
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

struct Counter {
    value: AtomicUsize,
}

impl Counter {
    fn new() -> Self {
        Counter { value: AtomicUsize::new(0) }
    }

    fn increment(&self) -> usize {
        // Relaxed is enough: we only need atomicity, not ordering with
        // other memory. Use SeqCst if you need a global happen-before edge.
        self.value.fetch_add(1, Ordering::Relaxed)
    }

    fn get(&self) -> usize {
        self.value.load(Ordering::Relaxed)
    }
}

fn main() {
    let counter = Arc::new(Counter::new());
    let mut handles = Vec::new();

    for _ in 0..8 {
        let c = Arc::clone(&counter);
        handles.push(thread::spawn(move || {
            for _ in 0..1000 {
                c.increment();
            }
        }));
    }

    for h in handles {
        h.join().unwrap();
    }

    assert_eq!(counter.get(), 8000);
    println!("{}", counter.get());
}
```

`AtomicUsize` gives lock-free increments. `fetch_add` returns the previous value, so the return type is the old count. `Arc` shares ownership across threads; joining all handles before reading guarantees the final `8000` without any extra synchronization.

