#include <functional>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // max-heap for the lower half, min-heap for the upper half.
    std::priority_queue<int> low;
    std::priority_queue<int, std::vector<int>, std::greater<int>> high;

    int value;
    while (std::cin >> value) {
        if (low.empty() || value <= low.top()) {
            low.push(value);
        } else {
            high.push(value);
        }

        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        std::cout << ((low.size() == high.size())
                          ? (low.top() + high.top()) / 2.0
                          : static_cast<double>(low.top()))
                  << '\n';
    }
    return 0;
}
```

Two heaps keep the lower half (max-heap) and upper half (min-heap) balanced to within one element, so the median is `low.top()` (odd count) or the mean of the two tops (even count). Every insertion is O(log n), which is optimal for a streaming median. Input stops cleanly at EOF.

```rust
/// Longest common prefix of `words`.
/// Returns "" if the slice is empty or any string shares no prefix.
fn longest_common_prefix(words: &[&str]) -> String {
    let first = match words.first() {
        Some(s) => *s,
        None => return String::new(),
    };

    let mut end = first.len();
    for word in &words[1..] {
        // Common prefix length can only shrink as we scan.
        let mut i = 0;
        let limit = end.min(word.len());
        // Compare by chars to stay on UTF-8 boundaries.
        let mut a = first.char_indices();
        let mut b = word.char_indices();
        while i < limit {
            match (a.next(), b.next()) {
                (Some((_, ca)), Some((_, cb))) if ca == cb => i += ca.len_utf8(),
                _ => break,
            }
        }
        end = i;
        if end == 0 {
            return String::new();
        }
    }
    first[..end].to_string()
}

fn main() {
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&["dog", "racecar"]), "");
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["caf\u{e9}", "caf\u{e9}x"]), "caf\u{e9}");
    println!("ok");
}
```

Scanning by `char_indices` keeps the cut point on a valid UTF-8 boundary, which naive byte slicing can break for accented characters. `end` only decreases, so the whole scan is O(total input length). `words.first()` handles the empty slice without indexing.

