def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring of s (O(n^2) expand-around-center)."""
    if not s:
        return ""

    start, end = 0, 0

    def expand(l: int, r: int) -> tuple:
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)        # odd length
        l2, r2 = expand(i, i + 1)    # even length
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["", "a", "babad", "cbbd", "abacdfgdcaba", "abba", "日本語のレベル"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
    assert longest_palindrome("") == ""
    assert longest_palindrome("a") == "a"
    assert longest_palindrome("babad") in ("bab", "aba")
    assert longest_palindrome("cbbd") == "bb"
    assert longest_palindrome("abba") == "abba"
```
Empty and one-character input are handled before the loop, and `expand` uses inclusive bounds so a match of length 0 falls back to the current character. Centers are tried for both odd and even palindromes.

