std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else             out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    assert((merge_sorted({}, {}) == std::vector<int>{}));
    assert((merge_sorted({1, 3, 5}, {}) == std::vector<int>{1, 3, 5}));
    assert((merge_sorted({}, {2, 4}) == std::vector<int>{2, 4}));
    assert((merge_sorted({1, 2, 3}, {2, 2, 4}) == std::vector<int>{1, 2, 2, 2, 3, 4}));
    assert((merge_sorted({-5, 0}, {-1, 10}) == std::vector<int>{-5, -1, 0, 10}));

    auto r = merge_sorted({1, 9}, {3, 7, 11});
    for (int v : r) std::cout << v << ' ';
