use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();

    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }

    let mut items: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count desc, then alphabetically for deterministic ties.
    items.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    items.truncate(n);
    items
}

fn main() {
    let text = "The cat sat. The CAT sat! A dog? The dog ran.";
    let top = top_words(text, 3);
    println!("{:?}", top);
    assert_eq!(top[0], ("the".to_string(), 4));
    assert_eq!(top[1], ("cat".to_string(), 2));
    assert_eq!(top[2], ("dog".to_string(), 2));

    let empty = top_words("", 5);
    assert!(empty.is_empty());
}
