def is_valid_ipv4(s: str) -> bool:
    """Strict dotted-quad IPv4 check: four decimal octets, 0-255, no leading zeros."""
    if not isinstance(s, str) or not s:
        return False

    parts = s.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit() or not part.isascii():
            return False
        if len(part) > 1 and part[0] == '0':   # reject 01, 00, etc.
            return False
        if int(part) > 255:
            return False

    return True


