pub fn binary_search<T: Ord>(haystack: &[T], needle: &T) -> Result<usize, usize> {
    let mut lo = 0usize;
    let mut hi = haystack.len(); // exclusive

    while lo < hi {
        let mid = lo + (hi - lo) / 2; // avoids overflow vs (lo + hi) / 2
        match haystack[mid].cmp(needle) {
            Ordering::Less => lo = mid + 1,
            Ordering::Greater => hi = mid,
            Ordering::Equal => return Ok(mid),
        }
    }
    Err(lo) // insertion point
}

fn main() {
    let v = vec![1, 3, 5, 7, 9, 11];
    assert_eq!(binary_search(&v, &7), Ok(3));
    assert_eq!(binary_search(&v, &1), Ok(0));
    assert_eq!(binary_search(&v, &11), Ok(5));
    assert_eq!(binary_search(&v, &4), Err(2));

    let empty: Vec<i32> = vec![];
    assert_eq!(binary_search(&empty, &42), Err(0));

    let words = vec!["ant", "bee", "cat"];
    assert_eq!(binary_search(&words, &"bee"), Ok(1));
    println!("ok, insertion point for 4 is {:?}", binary_search(&v, &4));
}
```
`hi` is exclusive so the loop handles the empty slice naturally. `mid = lo + (hi - lo) / 2` avoids `usize` overflow, and `Err` carries the insertion point, matching the convention in `slice::binary_search`.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    static constexpr std::size_t capacity() { return N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(!rb.push(4));
    assert(rb.size() == 3);
    assert(rb.pop() == 1);
    assert(rb.pop() == 2);
    assert(rb.push(4));
    assert(rb.pop() == 3);
    assert(rb.pop() == 4);
    assert(!rb.pop().has_value());
    assert(rb.size() == 0);
    return 0;
}
```
Writes land at `(head_ + size_) % N`, so no separate tail index is needed. `pop` returns `std::optional` to signal emptiness instead of undefined behaviour, and `static_assert` is unnecessary since a zero-capacity buffer simply rejects every push.

