bool isBalanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.empty();
}

int main() {
    assert(isBalanced(""));
    assert(isBalanced("()[]{}   "));
    assert(isBalanced("{[()]}"));
    assert(!isBalanced("(]"));
    assert(!isBalanced("([)]"));
    assert(!isBalanced("((("));
    assert(!isBalanced(")  "));
    std::cout << "ok\n";
    return 0;
}
