#include <iostream>
#include <vector>
#include <cassert>

int binarySearch(const std::vector<int>& a, int target) {
    int lo = 0;
    int hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;  // avoids overflow
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    assert(binarySearch({}, 5) == -1);
    assert(binarySearch({1}, 1) == 0);
    assert(binarySearch({1}, 0) == -1);
    assert(binarySearch({1, 2, 3, 4, 5}, 5) == 4);
    assert(binarySearch({1, 2, 3, 4, 5}, 1) == 0);
    assert(binarySearch({1, 2, 3, 4, 5}, 3) == 2);
    assert(binarySearch({1, 2, 3, 4, 5}, 6) == -1);
    std::cout << "ok\n";
    return 0;
}
```

`lo + (hi - lo) / 2` avoids overflow on large index ranges, and the `lo <= hi` loop with `mid ± 1` updates has no infinite-loop trap.

