#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) {
        return;
    }
    char *left = s;
    char *right = s + strlen(s) - 1;
    if (strlen(s) == 0) {
        return;
    }
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char buf[] = "hello, world";
    reverse_in_place(buf);
    printf("%s\n", buf);
    return 0;
}
```

`left` points at the first character, `right` at the last. Each iteration swaps the characters they point to, then the pointers step inward until they meet or cross. Because both advance by one, the loop touches each character at most once — O(n) time, O(1) extra space. The empty-string check avoids forming `s - 1`, which is undefined.

