// Returns the nth Fibonacci number (F0=0, F1=1).
// If the value would overflow, returns ULLONG_MAX and sets overflow.
unsigned long long fib(unsigned n, bool &overflow) {
    overflow = false;
    if (n == 0) return 0;
    unsigned long long a = 0, b = 1;
    for (unsigned i = 2; i <= n; ++i) {
        if (a > std::numeric_limits<unsigned long long>::max() - b) {
            overflow = true;
            return std::numeric_limits<unsigned long long>::max();
        }
        unsigned long long c = a + b;
        a = b;
        b = c;
    }
    return b;
}

