#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& v, int target) {
    int lo = 0;
    int hi = static_cast<int>(v.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;  // avoids overflow
        if (v[mid] == target) return mid;
        if (v[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> v = {1, 3, 5, 7, 9, 11};
    for (int t : {1, 7, 11, 4, -3}) {
        std::cout << "search(" << t << ") = " << binary_search(v, t) << "\n";
    }
    return 0;
}
