def validate_email(addr):
    """Return (ok, reason). Checks a reasonable subset of RFC 5322."""
    if not isinstance(addr, str) or not addr:
        return False, "empty or non-string"
    if addr.count("@") != 1:
        return False, "must contain exactly one @"
    local, domain = addr.split("@")
    if not local or len(local) > 64:
        return False, "local part empty or too long"
    if not domain or "." not in domain:
        return False, "domain must have a dot"
    if domain.startswith(".") or domain.endswith("."):
        return False, "domain cannot start or end with a dot"
    if ".." in domain:
        return False, "domain has consecutive dots"
    for ch in local:
        if not (ch.isalnum() or ch in "._%+-"):
            return False, f"illegal local character: {ch!r}"
    for label in domain.split("."):
        if not label or not all(c.isalnum() or c == "-" for c in label):
            return False, f"invalid domain label: {label!r}"
    return True, "ok"


