import sys
import heapq

def running_medians(nums):
    lo = []  # max-heap (negated)
    hi = []  # min-heap
    out = []
    for x in nums:
        if not lo or x <= -lo[0]:
            heapq.heappush(lo, -x)
        else:
            heapq.heappush(hi, x)
        if len(lo) > len(hi) + 1:
            heapq.heappush(hi, -heapq.heappop(lo))
        elif len(hi) > len(lo):
            heapq.heappush(lo, -heapq.heappop(hi))
        if len(lo) == len(hi):
            out.append((-lo[0] + hi[0]) / 2)
        else:
            out.append(float(-lo[0]))
    return out

def main():
    data = sys.stdin.read().split()
    nums = [int(tok) for tok in data]
    for m in running_medians(nums):
        print(f"{m:.1f}")

if __name__ == "__main__":
    assert running_medians([5, 15, 1, 3]) == [5.0, 10.0, 5.0, 4.0]
