bool is_valid_ipv4(const std::string& s) {
    int parts = 0;
    size_t i = 0;
    while (i < s.size()) {
        if (parts == 4) return false;
        size_t j = i;
        while (j < s.size() && s[j] != '.') ++j;
        std::string seg = s.substr(i, j - i);
        if (seg.empty() || seg.size() > 3) return false;
        for (char c : seg)
            if (c < '0' || c > '9') return false;
        if (seg.size() > 1 && seg[0] == '0') return false;
        int val = std::stoi(seg);
        if (val < 0 || val > 255) return false;
        ++parts;
        i = (j < s.size()) ? j + 1 : j;
        if (j == s.size()) break;
    }
    return parts == 4;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_valid_ipv4("192.168.0.1") << "\n";   // true
    std::cout << is_valid_ipv4("256.1.1.1") << "\n";      // false
    std::cout << is_valid_ipv4("01.2.3.4") << "\n";       // false
    std::cout << is_valid_ipv4("1.2.3") << "\n";          // false
    std::cout << is_valid_ipv4("1.2.3.4.5") << "\n";      // false
