```c
#include <errno.h>
#include <limits.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <ctype.h>

/* Returns true and stores the value in *out on success.
 * Rejects: empty input, leading/trailing whitespace, overflow. */
bool parse_i64(const char *s, int64_t *out) {
    if (s == NULL || *s == '\0' || out == NULL) return false;

    const char *p = s;
    bool neg = false;
    if (*p == '+' || *p == '-') {
        neg = (*p == '-');
        p++;
    }
    if (!isdigit((unsigned char)*p)) return false;

    /* Accumulate negatively so INT64_MIN is representable. */
    int64_t acc = 0;
    while (*p) {
        if (!isdigit((unsigned char)*p)) return false;
        int d = *p - '0';
        if (acc < (INT64_MIN + d) / 10) return false; /* overflow */
        acc = acc * 10 - d;
        p++;
    }

    if (!neg) {
        if (acc == INT64_MIN) return false; /* |INT64_MIN| overflows */
        acc = -acc;
    }
    *out = acc;
    return true;
}

#ifdef TEST
#include <stdio.h>
int main(void) {
    const char *cases[] = {"0", "-1", "9223372036854775807",
                           "-9223372036854775808", "12x", "", " 1"};
    for (size_t i = 0; i < sizeof(cases)/sizeof(cases[0]); i++) {
        int64_t v;
        printf("%s -> %s\n", cases[i], parse_i64(cases[i], &v) ? "ok" : "reject");
    }
    return 0;
}
#endif
```

The trick is accumulating into a negative value: `INT64_MIN` has no positive counterpart, so working in the negative domain makes the boundary representable. Each digit subtracts (`acc * 10 - d`), and the overflow guard `acc < (INT64_MIN + d) / 10` fires before the multiply can wrap. Any non-digit character, including a trailing letter or a space, makes the loop return false, so garbage is rejected rather than silently truncated the way `strtoll` would.

```rust
use std::collections::HashMap;
use std::hash::Hash;
use std::sync::Mutex;

struct Inner<K, V> {
    map: HashMap<K, V>,
    order: Vec<K>, // front = least recently used
    cap: usize,
}

pub struct LruCache<K, V> {
    inner: Mutex<Inner<K, V>>,
}

impl<K: Eq + Hash + Clone, V: Clone> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache {
            inner: Mutex::new(Inner { map: HashMap::new(), order: Vec::new(), cap }),
        }
    }

    pub fn get(&self, key: &K) -> Option<V> {
        let mut inner = self.inner.lock().unwrap();
        let value = inner.map.get(key).cloned()?;
        inner.order.retain(|k| k != key);
        inner.order.push(key.clone());
        Some(value)
    }

    pub fn put(&self, key: K, value: V) {
        let mut inner = self.inner.lock().unwrap();
        if inner.map.insert(key.clone(), value).is_some() {
            inner.order.retain(|k| k != &key);
        }
        inner.order.push(key);
        while inner.order.len() > inner.cap {
            let evicted = inner.order.remove(0);
            inner.map.remove(&evicted);
        }
    }

    pub fn len(&self) -> usize {
        self.inner.lock().unwrap().map.len()
    }
}

fn main() {
    let cache: LruCache<&str, i32> = LruCache::new(2);
    cache.put("a", 1);
    cache.put("b", 2);
    assert_eq!(cache.get(&"a"), Some(1)); // 'a' becomes most recent
    cache.put("c", 3);                    // evicts 'b'
    assert_eq!(cache.get(&"b"), None);
    assert_eq!(cache.len(), 2);
    println!("ok");
}
```

The `Vec` is the recency list with the least-recently-used key at index 0. `get` clones the value, moves the key to the back, and returns it; `put` inserts, refreshes position if the key existed, then evicts from the front until the size is back inside capacity. A `Mutex` serialises all access, so this is safe to share via `Arc<LruCache<..>>`. The naive `Vec::retain`/`remove(0)` is O(n), which is fine for small caches; a real high-throughput version would use an intrusive doubly-linked list plus `HashMap<K, *mut Node>`, but that trades clarity for constant factors.

```cpp
#include <iostream>
#include <string>
#include <string_view>
#include <vector>

std::vector<std::string> split(std::string_view input, char delim) {
    std::vector<std::string> out;
    if (input.empty()) return out;

    std::size_t start = 0;
    while (true) {
        std::size_t pos = input.find(delim, start);
        if (pos == std::string_view::npos) {
            out.emplace_back(input.substr(start));
            break;
        }
        out.emplace_back(input.substr(start, pos - start)); // keeps empty fields
        start = pos + 1;
    }
    return out;
}

int main() {
    for (const auto& part : split("a,,b,", ',')) {
        std::cout << '[' << part << "]\n";
    }
    // a [] [] b []

    std::cout << "empty -> " << split("", ',').size() << " fields\n"; // 0
    return 0;
}
```

`emplace_back(input.substr(start, pos - start))` keeps empty fields, so `"a,,b,"` yields `["a", "", "b", ""]` rather than dropping the gaps — different semantics than `getline`, which discards the trailing empty field. The explicit `empty()` guard makes the empty input return an empty vector instead of a vector with one empty string, which is the shape callers usually expect. `string_view` avoids copying the whole input, and the loop terminates because `start` advances past the delimiter each iteration.

```python
import re
import sys
from collections import Counter

WORD_RE = re.compile(r"[a-z0-9']+")

def top_words(path: str, n: int = 10) -> list[tuple[str, int]]:
    try:
        with open(path, encoding="utf-8") as fh:
            text = fh.read()
    except OSError as exc:
        print(f"error reading {path}: {exc}", file=sys.stderr)
        return []

    words = WORD_RE.findall(text.lower())
    return Counter(words).most_common(n)

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("usage: wordcount.py FILE", file=sys.stderr)
        sys.exit(2)
    for word, count in top_words(sys.argv[1]):
        print(f"{count:7d}  {word}")
```

`text.lower()` folds case before matching, and the regex `[a-z0-9']+` keeps apostrophes inside words (`don't`) while dropping other punctuation. `Counter.most_common` returns the highest counts with ties resolved in insertion order, which is deterministic for a given file. File errors are caught and reported on stderr instead of crashing, and the `usage` branch exits with code 2 so a caller can distinguish a bad invocation from a read failure. For very large files you would stream line by line instead of `read()`, but the Counter still works.

```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(void) {
    size_t cap = 8, len = 0;
    long *values = malloc(cap * sizeof *values);
    if (!values) { perror("malloc"); return 1; }

    long x;
    while (scanf("%ld", &x) == 1) {
        if (len == cap) {
            size_t new_cap = cap * 2;
            long *grown = realloc(values, new_cap * sizeof *grown);
            if (!grown) { free(values); perror("realloc"); return 1; }
            values = grown;
            cap = new_cap;
        }
        values[len++] = x;
    }

    if (len == 0) {
        puts("no numbers provided");
        free(values);
        return 0;
    }

    long sum = 0, max = LONG_MIN;
    for (size_t i = 0; i < len; i++) {
        sum += values[i];
        if (values[i] > max) max = values[i];
    }
    printf("count=%zu sum=%ld max=%ld\n", len, sum, max);
    free(values);
    return 0;
}
```

The array doubles when full, giving amortised O(1) appends. `realloc` writes through a temporary `grown` pointer so a failure does not leak the original block. `scanf("%ld")` returns 1 only on a successfully parsed integer, so any non-numeric token ends the loop cleanly. The empty-input branch prints a message instead of reporting a bogus `LONG_MIN` maximum, and `values` is freed on every exit path. Sum can overflow `long` for extreme input, which is why the return type is widened to `long` rather than `int`.

```rust
fn fib_checked(n: u32) -> Option<u64> {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        b = a.checked_add(b)?;
        a = b - a; // old b
    }
    Some(a)
}

fn main() {
    for i in 0.. {
        match fib_checked(i) {
            Some(v) if v % 2 == 0 => println!("fib({i}) = {v}"),
            Some(_) => {}
            None => {
                eprintln!("overflowed at n = {i}");
                break;
            }
        }
    }
}
```

The `?` on `checked_add` short-circuits to `None` the moment `u64` overflows, and `a = b - a` recovers the previous `b` without a third variable. `fib(0) = 0` and `fib(1) = 1`, so `fib(2) = 1` and `fib(3) = 2` — the first even value is `fib(0) = 0`, then `2`, `8`, `34`, and so on. The loop has no upper bound other than overflow, and the `None` arm breaks with a diagnostic on stderr rather than panicking. The `Some(_) => {}` arm is the explicit no-op for odd values, which keeps the match exhaustive without an underscore-everything fallback.

