```rust
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);

    while i < a.len() && j < b.len() {
        // take from `a` on ties so elements from a come first (stable)
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }

    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

#[cfg(test)]
mod tests {
    use super::merge_sorted;

    #[test]
    fn merges_and_keeps_order_on_ties() {
        assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
        assert_eq!(merge_sorted(&[2, 2], &[2, 2]), vec![2, 2, 2, 2]);
        assert_eq!(merge_sorted(&[], &[1]), vec![1]);
        assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    }
}
```

The tie-breaking `<=` makes the merge stable with respect to `a`-before-`b` ordering, which is what you want when each source slice was itself produced by a stable sort. `extend_from_slice` drains the remainder of whichever side still has elements. Run tests with `cargo test`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} IntStack;

static bool stack_init(IntStack *s, size_t initial) {
    if (initial == 0) initial = 1;
    s->data = malloc(initial * sizeof *s->data);
    if (!s->data) return false;
    s->size = 0;
    s->capacity = initial;
    return true;
}

static bool stack_push(IntStack *s, int value) {
    if (s->size == s->capacity) {
        size_t next = s->capacity * 2;
        if (next < s->capacity) return false;  /* overflow */
        int *grown = realloc(s->data, next * sizeof *grown);
        if (!grown) return false;              /* old buffer intact */
        s->data = grown;
        s->capacity = next;
    }
    s->data[s->size++] = value;
    return true;
}

static bool stack_pop(IntStack *s, int *out) {
    if (s->size == 0) return false;
    *out = s->data[--s->size];
    return true;
}

static void stack_free(IntStack *s) {
    free(s->data);
    s->data = NULL;
    s->size = s->capacity = 0;
}

int main(void) {
    IntStack s;
    if (!stack_init(&s, 2)) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }

    for (int i = 1; i <= 20; ++i) {
        if (!stack_push(&s, i * i)) {
            fprintf(stderr, "push failed at %d\n", i);
            stack_free(&s);
            return 1;
        }
    }

    int v;
    while (stack_pop(&s, &v)) {
        printf("%d\n", v);
    }
    printf("empty: %s\n", stack_pop(&s, &v) ? "no" : "yes");

    stack_free(&s);
    return 0;
}
```

The key safety point: `realloc`'s result goes into a temporary, so on failure the original buffer is still valid and is not leaked. The `next < s->capacity` check catches the doubling overflow before calling `realloc`. `pop` reports failure on an empty stack instead of reading out of bounds.

