#include <cstddef>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <vector>

class MovingAverage {
public:
    explicit MovingAverage(std::size_t window)
        : window_(window), sum_(0.0) {
        if (window == 0) {
            throw std::invalid_argument("window must be positive");
        }
        buffer_.reserve(window);
    }

    double push(double value) {
        if (buffer_.size() == window_) {
            sum_ -= buffer_[next_];
            buffer_[next_] = value;
            next_ = (next_ + 1) % window_;
        } else {
            buffer_.push_back(value);
        }
        sum_ += value;
        return sum_ / static_cast<double>(buffer_.size());
    }

    double value() const {
        if (buffer_.empty()) {
            throw std::logic_error("no samples yet");
        }
        return sum_ / static_cast<double>(buffer_.size());
    }

private:
    std::size_t window_;
    std::size_t next_ = 0;
    double sum_;
    std::vector<double> buffer_;
};

int main() {
    MovingAverage ma(3);
    for (double v : {1.0, 2.0, 3.0, 4.0}) {
        std::cout << ma.push(v) << '\n';
    }
    std::cout << "final=" << ma.value() << '\n';
}
