    assert_eq!(binary_search_or_insert(&data, &4), Ok(1));
    assert_eq!(binary_search_or_insert(&data, &5), Err(3));
    assert_eq!(binary_search_or_insert::<i32>(&[], &1), Err(0));
    assert_eq!(binary_search_or_insert(&data, &9), Err(5));
