#include <array>
#include <cstddef>
#include <optional>
#include <iostream>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double v) {
        if (size_ == N) return false;
        data_[tail_] = v;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) return std::nullopt;
        double v = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1.5); rb.push(2.5); rb.push(3.5);
    std::cout << rb.push(4.5) << '\n';   // 0, full
    std::cout << *rb.pop() << '\n';      // 1.5
    std::cout << *rb.pop() << '\n';      // 2.5
    std::cout << rb.push(4.5) << '\n';   // 1, wrap-around
    while (auto v = rb.pop()) std::cout << *v << '\n';
}
