void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t n = strlen(s);
    if (n == 0) return;
    char *left = s;
    char *right = s + n - 1;
    while (left < right) {
        char tmp = *left;
        *left++ = *right;
        *right-- = tmp;
    }
