int eval_postfix(const std::string& expr) {
    std::istringstream in(expr);
    std::vector<int> st;
    std::string tok;
    while (in >> tok) {
        if (tok == "+" || tok == "-" || tok == "*" || tok == "/") {
            if (st.size() < 2) throw std::runtime_error("malformed expression");
            int b = st.back(); st.pop_back();
            int a = st.back(); st.pop_back();
            if (tok == "+") st.push_back(a + b);
            else if (tok == "-") st.push_back(a - b);
            else if (tok == "*") st.push_back(a * b);
            else {
                if (b == 0) throw std::runtime_error("division by zero");
                st.push_back(a / b);
            }
        } else {
            st.push_back(std::stoi(tok));
        }
    }
    if (st.size() != 1) throw std::runtime_error("malformed expression");
    return st.back();
}

int main() {
    std::cout << eval_postfix("3 4 + 2 *") << "\n"; // 14
    return 0;
}
