```c
#include <stddef.h>
#include <string.h>

/*
 * Reverse a NUL-terminated UTF-8 string in place.
 *
 * Because UTF-8 is a variable-width encoding, reversing byte-by-byte would
 * split multibyte sequences. Instead we swap complete codepoints: each start
 * byte has the pattern 0xxxxxxx or 11xxxxxx, and continuation bytes match
 * 10xxxxxx, so codepoint boundaries can be found from the leading byte alone.
 *
 * Returns the string pointer, or NULL if s is NULL.
 */
char *reverse_utf8(char *s)
{
    if (s == NULL)
        return NULL;

    size_t i = 0, j = strlen(s);
    while (i < j) {
        /* Move j back to the start of the last codepoint. */
        j--;
        while (j > i && ((unsigned char)s[j] & 0xC0) == 0x80)
            j--;

        size_t len_j = 1;
        while (j + len_j < strlen(s) &&
               ((unsigned char)s[j + len_j] & 0xC0) == 0x80)
            len_j++;

        if (i + len_j > j + len_j)
            break;
        if (i + len_j > j + len_j)
            break;

        /* Rotate the two codepoints [i, i+len_i) and [j, j+len_j). */
        size_t len_i = 1;
        while (((unsigned char)s[i + len_i] & 0xC0) == 0x80)
            len_i++;

        if (i + len_i <= j) {
            char tmp[4];
            if (len_i > sizeof(tmp) || len_j > sizeof(tmp))
                break;
            memcpy(tmp, &s[i], len_i);
            memmove(&s[i], &s[j], len_j);
            memmove(&s[j], tmp, len_i);
            i += len_j;
            j += len_i;
        } else {
            break;
        }
    }
    return s;
}
