/// Return (F(n), F(n+1)) using the fast-doubling identities:
///   F(2k)   = F(k) * (2*F(k+1) - F(k))
///   F(2k+1) = F(k)^2 + F(k+1)^2
///
/// Returns None if any intermediate product overflows u128.
pub fn fib_pair(n: u128) -> Option<(u128, u128)> {
    if n == 0 {
        return Some((0, 1));
    }
    let (a, b) = fib_pair(n / 2)?;
    let two_b_minus_a = b.checked_mul(2)?.checked_sub(a)?;
    let c = a.checked_mul(two_b_minus_a)?; // F(2k)
    let d = a.checked_mul(a)?.checked_add(b.checked_mul(b)?)?; // F(2k+1)
    if n % 2 == 0 {
        Some((c, d))
    } else {
        Some((d, c.checked_add(d)?))
    }
}

pub fn fib(n: u128) -> Option<u128> {
    fib_pair(n).map(|(f, _)| f)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_values() {
        assert_eq!(fib(0), Some(0));
        assert_eq!(fib(1), Some(1));
        assert_eq!(fib(10), Some(55));
        assert_eq!(fib(50), Some(12586269025));
    }

    #[test]
    fn overflow_is_detected() {
        assert!(fib(u128::MAX).is_none());
    }
}
