#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

// Fixed-capacity FIFO queue over a compile-time-sized array.
// Not thread-safe; capacity must be at least 1.
template <typename T, std::size_t N>
class RingBuffer {
    static_assert(N > 0, "capacity must be positive");

public:
    bool empty() const noexcept { return size_ == 0; }
    bool full() const noexcept { return size_ == N; }
    std::size_t size() const noexcept { return size_; }
    std::size_t capacity() const noexcept { return N; }

    bool push(const T& value) { return push_impl(value); }
    bool push(T&& value) { return push_impl(std::move(value)); }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = std::move(buf_[head_]);
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

private:
    template <typename U>
    bool push_impl(U&& value) {
        if (full()) return false;
        buf_[(head_ + size_) % N] = std::forward<U>(value);
        ++size_;
        return true;
    }

    std::array<T, N> buf_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

#include <cassert>
#include <string>

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.empty());
    assert(rb.push(1));
    assert(rb.push(2));
    assert(rb.push(3));
    assert(rb.full());
    assert(!rb.push(4));           // drop when full
    assert(rb.pop() == std::optional<int>{1});
    assert(rb.pop() == std::optional<int>{2});
    assert(rb.push(4));
    assert(rb.pop() == std::optional<int>{3});
    assert(rb.pop() == std::optional<int>{4});
    assert(!rb.pop().has_value()); // empty

    RingBuffer<std::string, 2> names;
    names.push("luna");
    names.push("xt");
    assert(!names.push("extra"));
    return 0;
}
