/// Split `data` on single-byte `delim` and return borrowed subslices.
///
/// An empty input yields no parts; a trailing delimiter does not produce a
/// final empty part (mirrors `str::split_terminator` for the byte case).
pub fn split_bytes<'a>(data: &'a [u8], delim: u8) -> Vec<&'a [u8]> {
    let mut out = Vec::new();
    let mut start = 0usize;

    for (i, &b) in data.iter().enumerate() {
        if b == delim {
            if i > start {
                out.push(&data[start..i]);
            }
            start = i + 1;
        }
    }
    if start < data.len() {
        out.push(&data[start..]);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        assert_eq!(split_bytes(b"a,b,c", b','), vec![&b"a"[..], &b"b"[..], &b"c"[..]]);
    }

    #[test]
    fn empty_and_trailing() {
        assert!(split_bytes(b"", b',').is_empty());
        assert_eq!(split_bytes(b"a,", b','), vec![&b"a"[..]]);
        assert_eq!(split_bytes(b",a", b','), vec![&b"a"[..]]);
    }

    #[test]
    fn empty_fields_are_dropped() {
        assert_eq!(split_bytes(b"a,,b", b','), vec![&b"a"[..], &b"b"[..]]);
    }
