#include <stdbool.h>
#include <stdio.h>
#include <string.h>

/*
 * Return true when (), [] and {} are correctly nested and balanced.
 * Non-bracket characters are ignored. An empty string is balanced.
 */
bool balanced(const char *s)
{
    if (s == NULL)
        return true;

    char stack[256];
    size_t top = 0;

    for (; *s; s++) {
        char c = *s;
        if (c == '(' || c == '[' || c == '{') {
            if (top == sizeof(stack) / sizeof(stack[0]))
                return false; /* deeper than we can track: reject safely */
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0)
                return false;
            char open = stack[--top];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{'))
                return false;
        }
        /* anything else is ignored */
    }
    return top == 0;
}

int main(void)
{
    const char *cases[] = {
        "(1 + 2) * [3 - {4 / 5}]",   /* balanced   */
        "([)]",                        /* interleaved */
        "((",                          /* unclosed   */
        ")",                           /* stray      */
        "",                            /* empty ok   */
        "no brackets here",            /* ok         */
        NULL
    };
    const bool want[] = { true, false, false, false, true, true };

    for (size_t i = 0; cases[i]; i++) {
        bool got = balanced(cases[i]);
        printf("%-28s %s (expected %s)\n", cases[i],
               got ? "OK" : "BAD", want[i] ? "OK" : "BAD");
        if (got != want[i])
            return 1;
    }
    return 0;
}
