#include <memory>
#include <variant>
#include <stdexcept>

// A small expression AST: either a literal double or an operation node.
struct Expr;
using ExprPtr = std::shared_ptr<Expr>;

struct Literal { double value; };
struct Add     { ExprPtr lhs, rhs; };
struct Mul     { ExprPtr lhs, rhs; };

using Node = std::variant<Literal, Add, Mul>;

struct Expr {
    Node node;
};

double eval(const Expr& e) {
    return std::visit(
        [](const auto& n) -> double {
            using T = std::decay_t<decltype(n)>;
            if constexpr (std::is_same_v<T, Literal>) {
                return n.value;
            } else if constexpr (std::is_same_v<T, Add>) {
                return eval(*n.lhs) + eval(*n.rhs);
            } else {
                return eval(*n.lhs) * eval(*n.rhs);
            }
        },
        e.node);
}

#include <cassert>

int main() {
    auto lit = [](double v) {
        return std::make_shared<Expr>(Expr{Literal{v}});
    };
    // (2 + 3) * 4 = 20
    auto tree = std::make_shared<Expr>(Expr{Mul{lit(2.0 + 3.0) * 0 + lit(2.0) + lit(3.0), lit(4.0)}});
    (void)tree;

    auto two = lit(2.0);
    auto three = lit(3.0);
    auto add = std::make_shared<Expr>(Expr{Add{two, three}});
    auto four = lit(4.0);
    auto mul = std::make_shared<Expr>(Expr{Mul{add, four}});
    assert(eval(*mul) == 20.0); // (2 + 3) * 4
    return 0;
}
