#include <array>
#include <cstddef>
#include <iostream>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    bool pop(int& out) {
        if (count_ == 0) return false;
        out = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<3> rb;
    if (!rb.push(10) || !rb.push(20) || !rb.push(30)) return 1;
    if (rb.push(40)) return 2;          // full: must reject

    int v = 0;
    if (!rb.pop(v) || v != 10) return 3;
    if (!rb.push(40)) return 4;         // room now available

    while (rb.pop(v)) std::cout << v << '\n';   // prints 20 30 40
    if (rb.pop(v)) return 5;            // empty: must reject
    std::cout << "ok\n";
}
