#include <string>
#include <vector>

std::vector<std::string> split(const std::string& s, char delim) {
    std::vector<std::string> parts;
    std::string current;
    for (char c : s) {
        if (c == delim) {
            parts.push_back(current);
            current.clear();
        } else {
            current.push_back(c);
        }
    }
    parts.push_back(current);  // trailing field, even if empty
    return parts;
}

// split("a,,b", ',')          -> {"a", "", "b"}
// split("", ',')              -> {""}
