```rust
use std::collections::HashMap;

struct Node<K, V> {
    key: K,
    val: V,
    prev: Option<usize>,
    next: Option<usize>,
}

pub struct LruCache<K, V> {
    map: HashMap<K, usize>,
    nodes: Vec<Option<Node<K, V>>>,
    free: Vec<usize>,
    head: Option<usize>,
    tail: Option<usize>,
    cap: usize,
}

impl<K: std::hash::Hash + Eq + Clone, V: Clone> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be > 0");
        Self { map: HashMap::new(), nodes: Vec::new(), free: Vec::new(),
               head: None, tail: None, cap }
    }

    fn unlink(&mut self, i: usize) {
        let (p, n) = {
            let node = self.nodes[i].as_ref().unwrap();
            (node.prev, node.next)
        };
        match p { Some(pi) => self.nodes[pi].as_mut().unwrap().next = n, None => self.head = n }
        match n { Some(ni) => self.nodes[ni].as_mut().unwrap().prev = p, None => self.tail = p }
    }

    fn push_front(&mut self, i: usize) {
        {
            let node = self.nodes[i].as_mut().unwrap();
            node.prev = None;
            node.next = self.head;
        }
        if let Some(h) = self.head {
            self.nodes[h].as_mut().unwrap().prev = Some(i);
        }
        self.head = Some(i);
        if self.tail.is_none() {
            self.tail = Some(i);
        }
    }

    pub fn get(&mut self, key: &K) -> Option<V> {
        let i = *self.map.get(key)?;
        self.unlink(i);
        self.push_front(i);
        self.nodes[i].as_ref().map(|n| n.val.clone())
    }

    pub fn put(&mut self, key: K, val: V) {
        if let Some(&i) = self.map.get(&key) {
            self.nodes[i].as_mut().unwrap().val = val;
            self.unlink(i);
            self.push_front(i);
            return;
        }
        if self.map.len() == self.cap {
            if let Some(t) = self.tail {
                let evicted_key = self.nodes[t].as_ref().unwrap().key.clone();
                self.unlink(t);
                self.map.remove(&evicted_key);
                self.nodes[t] = None;
                self.free.push(t);
            }
        }
        let i = self.free.pop().unwrap_or_else(|| { self.nodes.push(None); self.nodes.len() - 1 });
        self.nodes[i] = Some(Node { key: key.clone(), val, prev: None, next: None });
        self.map.insert(key, i);
        self.push_front(i);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn evicts_lru() {
        let mut c = LruCache::new(2);
        c.put("a", 1); c.put("b", 2);
        assert_eq!(c.get(&"a"), Some(1));  // "b" is now LRU
        c.put("c", 3);
        assert_eq!(c.get(&"b"), None);
        assert_eq!(c.get(&"a"), Some(1));
        assert_eq!(c.get(&"c"), Some(3));
    }
}
