/// Build the KMP failure table: fail[i] = length of longest proper
/// prefix of pat[..=i] that is also a suffix.
fn build_failure(pat: &[u8]) -> Vec<usize> {
    let m = pat.len();
    let mut fail = vec![0usize; m];
    let mut k = 0usize;
    for i in 1..m {
        while k > 0 && pat[i] != pat[k] {
            k = fail[k - 1];
        }
        if pat[i] == pat[k] {
            k += 1;
        }
        fail[i] = k;
    }
    fail
}

pub fn find(haystack: &str, needle: &str) -> Option<usize> {
    let (h, n) = (haystack.as_bytes(), needle.as_bytes());
    if n.is_empty() {
        return Some(0);
    }
    if n.len() > h.len() {
        return None;
    }
    let fail = build_failure(n);
    let mut k = 0usize;
    for (i, &b) in h.iter().enumerate() {
        while k > 0 && b != n[k] {
            k = fail[k - 1];
        }
        if b == n[k] {
            k += 1;
        }
        if k == n.len() {
            return Some(i + 1 - n.len());
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn basic() {
        assert_eq!(find("abxabcabcaby", "abcaby"), Some(6));
        assert_eq!(find("aaa", "aa"), Some(0));
        assert_eq!(find("abc", "x"), None);
        assert_eq!(find("anything", ""), Some(0));
        assert_eq!(find("short", "longerneedle"), None);
    }
}
