#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int *data;
    size_t len;
    size_t cap;
} IntVec;

static int vec_reserve(IntVec *v, size_t need) {
    if (need <= v->cap) return 1;
    size_t new_cap = v->cap ? v->cap : 4;
    while (new_cap < need) new_cap *= 2;
    int *p = realloc(v->data, new_cap * sizeof(int));
    if (!p) return 0;
    v->data = p;
    v->cap = new_cap;
    return 1;
}

int vec_push(IntVec *v, int value) {
    if (!vec_reserve(v, v->len + 1)) return 0;
    v->data[v->len++] = value;
    return 1;
}

int vec_pop(IntVec *v, int *out) {
    if (v->len == 0) return 0;
    *out = v->data[--v->len];
    return 1;
}

void vec_free(IntVec *v) {
    free(v->data);
    v->data = NULL;
    v->len = v->cap = 0;
}

int main(void) {
    IntVec v = {0};
    for (int i = 0; i < 100; ++i) {
        if (!vec_push(&v, i * i)) {
            fprintf(stderr, "out of memory\n");
            vec_free(&v);
            return 1;
        }
    }
    int out;
    while (vec_pop(&v, &out)) {
        printf("%d\n", out);
    }
    printf("pop on empty: %d\n", vec_pop(&v, &out));  // 0
    vec_free(&v);
    return 0;
}
