#include <stddef.h>
#include <stdio.h>

/*
 * Copy src into dst (capacity cap, including the NUL). Always
 * NUL-terminates when cap > 0. Returns the number of source bytes
 * copied (not counting the NUL), which may be less than strlen(src)
 * if the buffer was too small.
 */
size_t safe_copy(char *dst, size_t cap, const char *src) {
    if (cap == 0) return 0;
    size_t i = 0;
    while (i + 1 < cap && src[i] != '\0') {
        dst[i] = src[i];
        ++i;
    }
    dst[i] = '\0';
    return i;
}

int main(void) {
    char buf[8];
    size_t n = safe_copy(buf, sizeof buf, "hello world");
    printf("copied=%zu buf=\"%s\"\n", n, buf);   // copied=7 buf="hello w"

    n = safe_copy(buf, sizeof buf, "hi");
    printf("copied=%zu buf=\"%s\"\n", n, buf);   // copied=2 buf="hi"

    char tiny[1];
    n = safe_copy(tiny, sizeof tiny, "x");
    printf("copied=%zu buf=\"%s\"\n", n, tiny);  // copied=0 buf=""
    return 0;
}
