def merge_intervals(intervals):
    if not intervals:
        return 0
    try:
        ordered = sorted((int(a), int(b)) for a, b in intervals)
    except (TypeError, ValueError):
        raise ValueError("intervals must be numeric pairs")
    merged = 1
    _, cur_end = ordered[0]
    for start, end in ordered[1:]:
        if start <= cur_end:
            if end > cur_end:
                cur_end = end
        else:
            merged += 1
            cur_end = end
    return merged

assert merge_intervals([]) == 0
assert merge_intervals([(1, 3), (2, 6), (8, 10)]) == 2
