```c
#include <stdio.h>
#include <stdbool.h>
#include <string.h>

#define CAP 8
typedef struct {
    int data[CAP];
    size_t head, count;
} ring_t;

static void ring_init(ring_t *r) { r->head = 0; r->count = 0; }

static bool ring_push(ring_t *r, int v) {
    if (r->count == CAP) return false;
    r->data[(r->head + r->count) % CAP] = v;
    r->count++;
    return true;
}

static bool ring_pop(ring_t *r, int *out) {
    if (r->count == 0) return false;
    *out = r->data[r->head];
    r->head = (r->head + 1) % CAP;
    r->count--;
    return true;
}

static bool ring_contains(const ring_t *r, int v) {
    for (size_t i = 0; i < r->count; ++i)
        if (r->data[(r->head + i) % CAP] == v) return true;
    return false;
}

int main(void) {
    ring_t r; ring_init(&r);
    int out;
    if (ring_pop(&r, &out)) return 1; // empty guard
    for (int i = 0; i < CAP; ++i) ring_push(&r, i * 10);
    if (ring_push(&r, 99)) return 1; // full guard
    printf("contains 30: %d\n", ring_contains(&r, 30));
    ring_pop(&r, &out);
    printf("popped %d\n", out);
    return 0;
}
```
