#include <iostream>
#include <vector>

template <typename T>
int binary_search(const std::vector<T>& v, const T& key) {
    int lo = 0, hi = static_cast<int>(v.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == key) return mid;
        if (v[mid] < key) lo = mid + 1; else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> v{1, 3, 5, 7, 9, 11};
    std::cout << binary_search(v, 7) << "\n";   // 3
    std::cout << binary_search(v, 4) << "\n";   // -1
    std::vector<int> empty;
    std::cout << binary_search(empty, 1) << "\n"; // -1
    return 0;
}
