    std::unordered_map<std::string, long> freq;
    std::string word;
    while (std::cin >> word) {
        std::string clean;
        clean.reserve(word.size());
        for (unsigned char c : word) {
            if (std::isalpha(c)) clean.push_back(static_cast<char>(std::tolower(c)));
        }
        if (!clean.empty()) ++freq[clean];
    }

    std::vector<std::pair<std::string, long>> items(freq.begin(), freq.end());
    std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;  // stable tie-break for determinism
    });

    size_t limit = std::min<size_t>(items.size(), static_cast<size_t>(topN));
    for (size_t i = 0; i < limit; ++i) {
        std::cout << items[i].first << ' ' << items[i].second << '\n';
    }
    return 0;
}
