/// Return true if every bracket in `s` is properly matched and nested.
/// Non-bracket characters are ignored.
pub fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let expected = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some(open) if open == expected => {}
                    _ => return false,
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

#[cfg(test)]
mod tests {
    use super::is_balanced;

    #[test]
    fn balanced_cases() {
        assert!(is_balanced(""));
        assert!(is_balanced("a(b[c]{d})e"));
        assert!(is_balanced("{{[[(())]]}}"));
        assert!(is_balanced("no brackets here"));
    }

    #[test]
    fn unbalanced_cases() {
        assert!(!is_balanced("("));
        assert!(!is_balanced(")}"));
        assert!(!is_balanced("([)]"));
        assert!(!is_balanced("{"));
    }
}
```

A stack of expected openers handles nesting and mismatches; `([)]` correctly fails because the closing `)` sees `[` on top.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError('capacity must be positive')
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least-recently used

    def __len__(self):
        return len(self._data)


if __name__ == '__main__':
    c = LRUCache(2)
    c.put('a', 1)
    c.put('b', 2)
    assert c.get('a') == 1
    c.put('c', 3)          # evicts 'b'
    assert c.get('b') is None
    assert c.get('c') == 3
    assert len(c) == 2
    print('ok')
```

`OrderedDict.move_to_end` keeps recency ordering, and `popitem(last=False)` removes the oldest entry in constant time.

