void reverse_in_place(char* s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;
    size_t i = 0, j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
        --j;
    }
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "x";
    char d[] = "ab";

    reverse_in_place(a);
    reverse_in_place(b);
    reverse_in_place(c);
    reverse_in_place(d);

    printf("'%s'\n", a);
    printf("'%s'\n", b);
    printf("'%s'\n", c);
    printf("'%s'\n", d);
    return 0;
}
