```rust
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
pub enum ParseError {
    Empty,
    Invalid(ParseIntError),
    OutOfRange { value: i128, min: i64, max: i64 },
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::Empty => write!(f, "input is empty"),
            ParseError::Invalid(e) => write!(f, "not a valid integer: {e}"),
            ParseError::OutOfRange { value, min, max } => {
                write!(f, "{value} is outside [{min}, {max}]")
            }
        }
    }
}

pub fn parse_i64(s: &str) -> Result<i64, ParseError> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        return Err(ParseError::Empty);
    }
    match trimmed.parse::<i64>() {
        Ok(v) => Ok(v),
        Err(e) => {
            // Distinguish overflow (parses as i128) from malformed input.
            if let Ok(big) = trimmed.parse::<i128>() {
                return Err(ParseError::OutOfRange {
                    value: big,
                    min: i64::MIN,
                    max: i64::MAX,
                });
            }
            Err(ParseError::Invalid(e))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn valid() {
        assert_eq!(parse_i64(" 42 ").unwrap(), 42);
        assert_eq!(parse_i64("-7").unwrap(), -7);
    }

    #[test]
    fn errors() {
        assert!(matches!(parse_i64(""), Err(ParseError::Empty)));
        assert!(matches!(parse_i64("abc"), Err(ParseError::Invalid(_))));
        assert!(matches!(
            parse_i64("99999999999999999999"),
            Err(ParseError::OutOfRange { .. })
        ));
    }
}
```

Whitespace is trimmed first; overflow is reported distinctly by re-parsing as `i128` before falling back to an invalid-input error.

```cpp
#include <algorithm>
#include <iostream>
#include <vector>

void reverse_range(std::vector<int>& v, int lo, int hi) {
    while (lo < hi) {
        std::swap(v[lo], v[hi]);
        ++lo;
        --hi;
    }
}

void rotate_left(std::vector<int>& v, int k) {
    const int n = static_cast<int>(v.size());
    if (n == 0) return;
    k %= n;
    if (k < 0) k += n;  // normalise negatives to [0, n)
    if (k == 0) return;

    reverse_range(v, 0, k - 1);      // reverse first k
    reverse_range(v, k, n - 1);      // reverse rest
    reverse_range(v, 0, n - 1);      // reverse whole
}

int main() {
    std::vector<std::vector<int>> in = {{1,2,3,4,5}, {}, {1}, {1,2}};
    std::vector<int> ks = {2, 3, 5, -1};
    for (size_t i = 0; i < in.size(); ++i) {
        rotate_left(in[i], ks[i]);
        for (int x : in[i]) std::cout << x << ' ';
        std::cout << '\n';
    }
    return 0;
}
```

The three-reversal trick rotates in O(n) time and O(1) space; `k` is normalised modulo `n` so empty and single-element vectors are no-ops.

