    while (fgets(line, sizeof line, fp)) {
        char *end;
        errno = 0;
        long v = strtol(line, &end, 10);
        if (end == line || errno != 0) {
            fprintf(stderr, "skipping malformed line: %s", line);
            continue;
        }
        if (!have_value) {
            min = max = v;
            have_value = 1;
        } else {
            if (v < min) min = v;
            if (v > max) max = v;
        }
        sum += (double)v;
        count++;
    }
    fclose(fp);

    if (count == 0) {
        fprintf(stderr, "no valid integers found\n");
        return 1;
    }
    printf("count=%ld min=%ld max=%ld mean=%.3f\n", count, min, max, sum / (double)count);
    return 0;
}
