#[derive(Debug, PartialEq)]
pub enum ParseNumError {
    Empty,
    NotANumber,
    OutOfRange,
}

impl fmt::Display for ParseNumError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let msg = match self {
            ParseNumError::Empty => "input is empty",
            ParseNumError::NotANumber => "input is not a number",
            ParseNumError::OutOfRange => "value out of range",
        };
        write!(f, "{}", msg)
    }
}

pub fn parse_num(s: &str) -> Result<i64, ParseNumError> {
    let t = s.trim();
    if t.is_empty() {
        return Err(ParseNumError::Empty);
    }
    t.parse::<i64>().map_err(|e| match e.kind() {
        std::num::IntErrorKind::PosOverflow | std::num::IntErrorKind::NegOverflow => {
            ParseNumError::OutOfRange
        }
        _ => ParseNumError::NotANumber,
    })
}

fn main() {
    assert_eq!(parse_num(" 42 "), Ok(42));
    assert_eq!(parse_num(""), Err(ParseNumError::Empty));
    assert_eq!(parse_num("abc"), Err(ParseNumError::NotANumber));
    assert_eq!(parse_num("99999999999999999999"), Err(ParseNumError::OutOfRange));
    println!("ok");
}
