fn is_palindrome(input: &str) -> bool {
    let chars: Vec<char> = input
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();

    let mut left = 0usize;
    let mut right = chars.len();
    while left + 1 < right {
        right -= 1;
        if chars[left] != chars[right] {
            return false;
        }
        left += 1;
    }
    true
}

fn main() {
    let cases = [
        ("A man, a plan, a canal: Panama", true),
        ("race a car", false),
        ("", true),
        ("!!!", true),
        ("Ésope", false),
        ("été", true),
    ];
    for (text, want) in cases {
        assert_eq!(is_palindrome(text), want, "failed on {:?}", text);
    }
    println!("all tests passed");
}
```

Filters to alphanumeric characters, lowercases via `flat_map` so multi-char lowercase mappings are handled, then compares from both ends. `(left + 1 < right)` avoids an underflow on the `right` index.

