#include <cstdint>
#include <iostream>
#include <limits>
#include <vector>

int main() {
    long long n;
    if (!(std::cin >> n) || n < 0) {
        std::cerr << "error: need a non-negative integer\n";
        return 1;
    }

    const long long MAX = std::numeric_limits<std::int64_t>::max();
    std::vector<std::uint64_t> memo(static_cast<std::size_t>(n) + 1, 0);
    memo[0] = 0;
    if (n >= 1) memo[1] = 1;

    for (long long i = 2; i <= n; ++i) {
        if (memo[i - 1] > MAX - memo[i - 2]) {
            std::cerr << "overflow at index " << i << "\n";
            return 2;
        }
        memo[i] = memo[i - 1] + memo[i - 2];
    }

    std::cout << memo[n] << '\n';
    return 0;
}
```

Iterative DP, O(n) time and memory. Before each add it checks whether `memo[i-1] + memo[i-2]` can exceed `uint64_t` range and exits with a distinct status code instead of wrapping silently. Negative or non-numeric input is rejected.

