use std::io::{self, Read};

fn mean(values: &[i64]) -> Option<f64> {
    if values.is_empty() {
        return None;
    }
    let sum: i64 = values.iter().sum();
    Some(sum as f64 / values.len() as f64)
}

fn median(values: &[i64]) -> Option<f64> {
    if values.is_empty() {
        return None;
    }
    let mut sorted = values.to_vec();
    sorted.sort_unstable();
    let mid = sorted.len() / 2;
    if sorted.len() % 2 == 1 {
        Some(sorted[mid] as f64)
    } else {
        Some((sorted[mid - 1] as f64 + sorted[mid] as f64) / 2.0)
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("read stdin");

    let mut values = Vec::new();
    for tok in input.split_whitespace() {
        match tok.parse::<i64>() {
            Ok(v) => values.push(v),
            Err(_) => {
                eprintln!("skipping non-integer token: {}", tok);
            }
        }
    }

    match (mean(&values), median(&values)) {
        (Some(m), Some(med)) => println!("mean={:.4} median={:.4}", m, med),
        _ => println!("no data"),
    }
}
```

Returns `Option` for both stats so empty input prints `no data`. Median is O(n log n) via a sorted copy; unparsable tokens are skipped with a warning rather than aborting the whole run.

