#include <stdio.h>
#include <stdlib.h>

static int merge(const int *a, size_t na, const int *b, size_t nb, int *out) {
    size_t i = 0, j = 0, k = 0;
    while (i < na && j < nb) {
        out[k++] = (a[i] <= b[j]) ? a[i++] : b[j++];
    }
    while (i < na) out[k++] = a[i++];
    while (j < nb) out[k++] = b[j++];
    return (int)k;
}

int main(void) {
    const int a[] = {1, 3, 5, 7, 9};
    const int b[] = {2, 4, 6, 8, 10, 12};
    const size_t na = sizeof a / sizeof a[0];
    const size_t nb = sizeof b / sizeof b[0];

    int *out = malloc((na + nb) * sizeof *out);
    if (!out) {
        fputs("allocation failed\n", stderr);
        return 1;
    }

    int n = merge(a, na, b, nb, out);
    for (int i = 0; i < n; ++i) {
        printf("%d%s", out[i], (i + 1 == n) ? "\n" : " ");
    }
    free(out);
    return 0;
}
```

Classic two-pointer merge, O(na+nb). `a[i] <= b[j]` keeps the merge stable for equal elements. The only heap allocation is the output buffer, with a checked `malloc`.

