def parse_ints(s: str) -> list[int]:
    """Parse a comma-separated string into a list of ints.

    Empty fields and surrounding whitespace are ignored. Fields that are
    not valid integers raise ValueError with the offending field named.
    """
    result: list[int] = []
    for field in s.split(","):
        field = field.strip()
        if not field:
            continue
        try:
            result.append(int(field))
        except ValueError as exc:
            raise ValueError(f"invalid integer field: {field!r}") from exc
    return result


