#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

// Reverse a UTF-8 string codepoint-by-codepoint.
std::string reverse_utf8(const std::string& s) {
    std::vector<std::string> glyphs;
    std::size_t i = 0;
    while (i < s.size()) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        std::size_t len = 1;
        if ((c & 0x80u) == 0x00u) len = 1;
        else if ((c & 0xE0u) == 0xC0u) len = 2;
        else if ((c & 0xF0u) == 0xE0u) len = 3;
        else if ((c & 0xF8u) == 0xF0u) len = 4;
        else { len = 1; }  // invalid leading byte: treat as one byte
        if (i + len > s.size()) len = 1;
        glyphs.emplace_back(s.substr(i, len));
        i += len;
    }
    std::string out;
    out.reserve(s.size());
    for (auto it = glyphs.rbegin(); it != glyphs.rend(); ++it) out += *it;
    return out;
}

int main() {
    std::string a = "hell\xc3\xa9";          // "hellé"
    std::cout << reverse_utf8(a) << "\n";     // "élleh"
    std::cout << reverse_utf8("\xf0\x9f\x99\x82ab") << "\n"; // emoji preserved
    std::cout << reverse_utf8("") << "\n";
    return 0;
}
