            fprintf(stderr, "value out of int range: %lld\n", value);
            return 1;
        }
        if (__builtin_add_overflow(sum, value, &sum))
            overflow = 1;
        int v = (int)value;
        if (v < minimum) minimum = v;
        if (v > maximum) maximum = v;
        count++;
    }

    if (ferror(stdin)) {
        perror("stdin");
        return 1;
    }
    if (count == 0) {
        puts("no integers supplied");
        return 0;
    }

    if (overflow)
        printf("count=%zu sum=overflow\n", count);
    else
        printf("count=%zu sum=%lld\n", count, sum);
    printf("min=%d max=%d\n", minimum, maximum);
    return 0;
