#include <algorithm>
#include <iostream>
#include <string>

std::string reverse_words(const std::string& input) {
    std::string out;
    out.reserve(input.size());
    std::size_t i = 0;
    while (i < input.size()) {
        while (i < input.size() && input[i] == ' ') ++i;
        std::size_t start = i;
        while (i < input.size() && input[i] != ' ') ++i;
        if (start == i) break;
        if (!out.empty()) out.push_back(' ');
        out.insert(out.end(), input.begin() + (long)start, input.begin() + (long)i);
    }
    std::reverse(out.begin(), out.end());
    std::size_t b = 0, e = 0;
    while (b < out.size()) {
        while (b < out.size() && out[b] == ' ') ++b;
        e = b;
        while (e < out.size() && out[e] != ' ') ++e;
        std::reverse(out.begin() + (long)b, out.begin() + (long)e);
        b = e;
    }
    return out;
}

int main() {
    for (const std::string& s : {std::string("  hello   world  "), std::string(""), std::string("one")})
        std::cout << '[' << reverse_words(s) << "]\n";
}
