#include <cstdint>
#include <iostream>
#include <queue>
#include <vector>
#include <stdexcept>

class RunningMedian {
public:
    void add(int value) {
        if (low_.empty() || value <= low_.top()) {
            low_.push(value);
        } else {
            high_.push(value);
        }
        // Rebalance: low_ holds ceil(n/2) elements.
        if (low_.size() > high_.size() + 1) {
            high_.push(low_.top());
            low_.pop();
        } else if (high_.size() > low_.size()) {
            low_.push(high_.top());
            high_.pop();
        }
    }

    double median() const {
        if (low_.empty()) {
            throw std::runtime_error("median of empty stream");
        }
        if (low_.size() == high_.size()) {
            return (static_cast<double>(low_.top()) + high_.top()) / 2.0;
        }
        return static_cast<double>(low_.top());
    }

private:
    std::priority_queue<int> low_;                                  // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high_;  // min-heap
};

int main() {
    RunningMedian rm;
    std::int64_t value;
    bool any = false;
    while (std::cin >> value) {
        if (value < INT32_MIN || value > INT32_MAX) {
            std::cerr << "value out of int range: " << value << '\n';
            return 1;
        }
        rm.add(static_cast<int>(value));
        std::cout << rm.median() << '\n';
        any = true;
    }
    if (!any) {
        std::cout << "(no input)\n";
    }
    return 0;
}
```

Two heaps keep the split at the median: a max-heap for the lower half and a min-heap for the upper half, rebalanced after each insert so the size difference never exceeds one. Each insert is O(log n).

