```c
#include <stdio.h>
#include <string.h>

/* Reverse a null-terminated byte string in place. */
void reverse(char *s) {
    if (s == NULL) {
        return;
    }
    size_t len = strlen(s);
    if (len < 2) {
        return;
    }
    size_t i = 0;
    size_t j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

int main(void) {
    char buf[256];
    while (fgets(buf, sizeof buf, stdin) != NULL) {
        size_t n = strlen(buf);
        if (n > 0 && buf[n - 1] == '\n') {
            buf[n - 1] = '\0';
        }
        reverse(buf);
        puts(buf);
    }
    return 0;
}
```

This reverses raw bytes, so a multibyte UTF-8 sequence will come out byte-flipped and no longer valid UTF-8 — that is inherent to in-place byte reversal. If you need character-aware reversal, decode the string into codepoints first (e.g. with a small UTF-8 decoder) and reverse those. The empty string and single characters are returned unchanged.

```rust
fn binary_search_or_insert(slice: &[i32], target: i32) -> usize {
    let (mut lo, mut hi) = (0usize, slice.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if slice[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

fn main() {
    let data = [1, 3, 5, 7, 9];
    assert_eq!(binary_search_or_insert(&data, 5), 2); // found
    assert_eq!(binary_search_or_insert(&data, 0), 0); // before first
    assert_eq!(binary_search_or_insert(&data, 4), 2); // between 3 and 5
    assert_eq!(binary_search_or_insert(&data, 10), 5); // after last
    let empty: [i32; 0] = [];
    assert_eq!(binary_search_or_insert(&empty, 42), 0);
    println!("all tests passed");
}
```

This is the standard lower-bound bisection: it returns the first index where `slice[i] >= target`, which is exactly the insertion point when the value is missing and the exact index when it is present. `lo + (hi - lo) / 2` avoids overflow on large slices.

```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <cstddef>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {}

    // Blocks until there is room. Returns false if the queue was shut down.
    bool push(T value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [&] { return closed_ || queue_.size() < capacity_; });
        if (closed_) return false;
        queue_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }

    // Blocks until an item is available. Returns nullopt when shut down and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock, [&] { return closed_ || !queue_.empty(); });
        if (queue_.empty()) return std::nullopt;  // closed and drained
        T value = std::move(queue_.front());
        queue_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void shutdown() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            closed_ = true;
        }
        not_full_.notify_all();
        not_empty_.notify_all();
    }

private:
    const std::size_t capacity_;
    std::queue<T> queue_;
    std::mutex mutex_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
    bool closed_ = false;
};
```

`pop` wakes blocked producers on shutdown and lets them drain remaining items before returning `nullopt`; `push` returns `false` once closed. Notify calls happen after releasing the lock to avoid waking a thread that immediately blocks on the still-held mutex. The capacity guard is in the predicate so it is re-checked on every wakeup.

