#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (!n) return head;
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_and_free(Node *head) {
    for (Node *cur = head; cur; ) {
        Node *next = cur->next;
        printf("%d ", cur->value);
        free(cur);
        cur = next;
    }
    putchar('\n');
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++) head = push(head, i);
    head = reverse(head);          /* now 1 2 3 4 5 */
    print_and_free(head);
    return 0;
}
