fn two_largest<T: Ord + Copy>(xs: &[T]) -> Option<(T, T)> {
    let mut iter = xs.iter().copied();
    let mut first = iter.next()?;
    let mut second = iter.next()?;
    if second > first {
        std::mem::swap(&mut first, &mut second);
    }
    for x in iter {
        if x > first {
            second = first;
            first = x;
        } else if x > second {
            second = x;
        }
    }
    Some((first, second))
}

