def fib(n: int) -> int:
    """Return F(n) with F(0)=0 and F(1)=1 using fast doubling."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def _pair(k):
        """Return (F(k), F(k+1))."""
        if k == 0:
            return (0, 1)
        a, b = _pair(k // 2)
        c = a * (2 * b - a)
        d = a * a + b * b
        if k % 2 == 0:
            return (c, d)
        return (d, c + d)

    return _pair(n)[0]


if __name__ == "__main__":
    assert fib(0) == 0
    assert fib(1) == 1
    assert fib(2) == 1
    assert fib(10) == 55
    assert fib(20) == 6765
    assert fib(90) == 2880067194370816120
    print("all tests passed")
