bool is_balanced(const std::string& s) {
    std::stack<char> open;
    for (char ch : s) {
        if (ch == '(' || ch == '[' || ch == '{') {
            open.push(ch);
        } else if (ch == ')' || ch == ']' || ch == '}') {
            if (open.empty()) return false;
            char expected = (ch == ')') ? '(' : (ch == ']') ? '[' : '{';
            if (open.top() != expected) return false;
            open.pop();
        }
    }
    return open.empty();
}

int main() {
    assert(is_balanced(""));
    assert(is_balanced("()"));
    assert(is_balanced("{[()]}"));
    assert(is_balanced("a(b[c]d)e"));
    assert(!is_balanced("("));
    assert(!is_balanced(")"));
    assert(!is_balanced("([)]"));
    assert(!is_balanced("(("));
    std::cout << "all tests passed\n";
    return 0;
