def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start = end = 0

    def expand(lo: int, hi: int) -> tuple[int, int]:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - 1

    for i in range(len(s)):
        a, b = expand(i, i)
        if b - a > end - start:
            start, end = a, b
        a, b = expand(i, i + 1)
        if b - a > end - start:
            start, end = a, b
    return s[start:end + 1]
```

Expands around each center in O(n²) time and O(1) extra space. Empty input returns an empty string.

```c
#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

#define RING_CAP 8

typedef struct {
    int data[RING_CAP];
    size_t head;   /* next write index */
    size_t count;  /* number of live elements */
} ring_t;

void ring_init(ring_t *r) {
    r->head = 0;
    r->count = 0;
}

bool ring_push(ring_t *r, int v) {
    if (r->count == RING_CAP) {
        return false;  /* full */
    }
    r->data[r->head] = v;
    r->head = (r->head + 1) % RING_CAP;
    r->count++;
    return true;
}

bool ring_pop(ring_t *r, int *out) {
    if (r->count == 0) {
        return false;  /* empty */
    }
    size_t tail = (r->head + RING_CAP - r->count) % RING_CAP;
    *out = r->data[tail];
    r->count--;
    return true;
}

int main(void) {
    ring_t r;
    ring_init(&r);
    for (int i = 0; i < 10; i++) {
        if (!ring_push(&r, i)) {
            printf("full at %d\n", i);
        }
    }
    int v;
    while (ring_pop(&r, &v)) {
        printf("%d ", v);
    }
    printf("\n");
    return 0;
}
```

The buffer is a fixed array with head/count indices. `ring_push` rejects when full and `ring_pop` rejects when empty, so no overflow or underflow occurs.

