use std::collections::HashMap;

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let key = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect::<String>();
        if key.is_empty() {
            continue;
        }
        *counts.entry(key).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "Café café CAFÉ na\u{ef}ve naive";
    for (word, count) in top_words(text, 3) {
        println!("{} {}", word, count);
    }
    assert!(top_words("", 3).is_empty());
}
```

`to_lowercase` handles Unicode case folding, and `is_alphanumeric` strips punctuation. Words are sorted by count descending, then alphabetically, so ties are deterministic.

```rust
fn parse_duration(s: &str) -> Option<u64> {
    let mut total: u64 = 0;
    let mut num = String::new();
    let mut saw_unit = false;

    for ch in s.chars() {
        if ch.is_ascii_digit() {
            num.push(ch);
        } else {
            let value: u64 = num.parse().ok()?;
            num.clear();
            let mult = match ch {
                'h' => 3600,
                'm' => 60,
                's' => 1,
                _ => return None,
            };
            total = total.checked_add(value.checked_mul(mult)?)?;
            saw_unit = true;
        }
    }
    if !num.is_empty() || !saw_unit {
        return None;
    }
    Some(total)
}

fn main() {
    assert_eq!(parse_duration("1h30m"), Some(5400));
    assert_eq!(parse_duration("45s"), Some(45));
    assert_eq!(parse_duration("2h"), Some(7200));
    assert_eq!(parse_duration("1h30"), None);
    assert_eq!(parse_duration("abc"), None);
    assert_eq!(parse_duration(""), None);
    println!("ok");
}
```

Digits accumulate until a unit letter flushes them. A trailing number with no unit, an unknown unit, or empty input returns `None`; overflow is also caught via `checked_mul`/`checked_add`.

