def rle_encode(s: str) -> str:
    if not s:
        return ""
    parts = []
    prev, count = s[0], 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            parts.append(f"{count}{prev}")
            prev, count = ch, 1
    parts.append(f"{count}{prev}")
    return "".join(parts)


def rle_decode(s: str) -> str:
    out, i = [], 0
    while i < len(s):
        num = 0
        if not s[i].isdigit():
            raise ValueError(f"expected digit at index {i}")
        while i < len(s) and s[i].isdigit():
            num = num * 10 + int(s[i])
            i += 1
        if i >= len(s):
            raise ValueError("missing character after count")
        out.append(s[i] * num)
        i += 1
    return "".join(out)


if __name__ == "__main__":
    for raw in ["aaabbc", "abc", "", "zzzzzzzzzzzz"]:
        enc = rle_encode(raw)
        dec = rle_decode(enc)
        assert dec == raw, (raw, enc, dec)
        print(repr(raw), "->", repr(enc), "->", repr(dec))
