#[derive(Debug, PartialEq, Eq)]
pub enum BracketError {
    UnexpectedClose { index: usize },
    UnclosedOpen { index: usize },
}

pub fn check_brackets(input: &str) -> Result<(), BracketError> {
    let mut stack: Vec<(char, usize)> = Vec::new();
    for (index, ch) in input.char_indices() {
        match ch {
            '(' | '[' | '{' => stack.push((ch, index)),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some((open, _)) if open == expected => {}
                    _ => return Err(BracketError::UnexpectedClose { index }),
                }
            }
            _ => {}
        }
    }
    match stack.last() {
        Some(&(_, index)) => Err(BracketError::UnclosedOpen { index }),
        None => Ok(()),
    }
}

fn main() {
    assert_eq!(check_brackets("([]{})"), Ok(()));
    assert_eq!(check_brackets("(])"), Err(BracketError::UnexpectedClose { index: 1 }));
    assert_eq!(check_brackets("(()"), Err(BracketError::UnclosedOpen { index: 0 }));
    println!("ok");
}
