#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (full()) {
            return false;
        }
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) {
            return std::nullopt;
        }
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    static_assert(N > 0, "capacity must be positive");
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> buffer;
    if (!buffer.push(1) || !buffer.push(2) || !buffer.push(3)) {
        throw std::runtime_error("push failed");
    }
    if (buffer.push(4)) {
        throw std::runtime_error("expected full");
    }
    return buffer.pop() == std::optional<int>(1) ? 0 : 1;
}
