def encode(text: str) -> str:
    parts = []
    for char, group in groupby(text):
        count = sum(1 for _ in group)
        parts.append(f"{count}{char}" if count > 1 else char)
    return "".join(parts)


def decode(encoded: str) -> str:
    out = []
    count = 0
    has_digit = False
    for ch in encoded:
        if ch.isdigit():
            count = count * 10 + int(ch)
            has_digit = True
        else:
            out.append(ch * (count if has_digit else 1))
            count = 0
            has_digit = False
    if has_digit:
        raise ValueError("encoded string ends with a dangling count")
    return "".join(out)


