std::string reverse_words(const std::string& sentence) {
    std::istringstream stream(sentence);
    std::vector<std::string> words;
    std::string word;
    while (stream >> word) {
        words.push_back(word);
    }
    std::string result;
    for (std::size_t i = words.size(); i-- > 0;) {
        result += words[i];
        if (i != 0) result += ' ';
    }
    return result;
}

int main() {
    std::cout << reverse_words("the quick brown fox") << "\n"; // fox brown quick the
    std::cout << reverse_words("") << "\n";                  // empty line
    std::cout << reverse_words("  spaced   out  ") << "\n"; // out spaced
    return 0;
}
