```c
#include <stdbool.h>
#include <stdio.h>
#include <limits.h>

bool is_palindrome(int n) {
    if (n < 0) return false;          /* negatives have a leading '-' */
    if (n != 0 && n % 10 == 0) return false; /* trailing zero can't match */

    long reversed = 0;
    int x = n;
    while (x > reversed) {
        reversed = reversed * 10 + x % 10;
        x /= 10;
    }
    /* even digits: x == reversed; odd digits: x == reversed / 10 */
    return x == reversed || x == reversed / 10;
}

int main(void) {
    printf("%d\n", is_palindrome(121));   /* 1 */
    printf("%d\n", is_palindrome(-121));  /* 0 */
    printf("%d\n", is_palindrome(10));    /* 0 */
    printf("%d\n", is_palindrome(0));     /* 1 */
    printf("%d\n", is_palindrome(INT_MAX)); /* 0 */
    return 0;
}
```

Reversing only half the number avoids overflow for large inputs like `INT_MAX`. The `x > reversed` loop condition is the stopping point, and the final comparison covers both even and odd digit counts.

