```rust
#[derive(Debug, PartialEq)]
struct Node {
    value: i32,
    next: Option<Box<Node>>,
}

fn reverse(mut head: Option<Box<Node>>) -> Option<Box<Node>> {
    let mut prev: Option<Box<Node>> = None;
    while let Some(mut node) = head {
        head = node.next.take();
        node.next = prev;
        prev = Some(node);
    }
    prev
}

fn build(values: &[i32]) -> Option<Box<Node>> {
    let mut head = None;
    for &value in values.iter().rev() {
        head = Some(Box::new(Node { value, next: head }));
    }
    head
}

fn to_vec(mut head: Option<Box<Node>>) -> Vec<i32> {
    let mut out = Vec::new();
    while let Some(mut node) = head {
        out.push(node.value);
        head = node.next.take();
    }
    out
}

fn main() {
    assert_eq!(to_vec(reverse(build(&[1, 2, 3]))), vec![3, 2, 1]);
    assert_eq!(to_vec(reverse(build(&[]))), Vec::<i32>::new());
    assert_eq!(to_vec(reverse(build(&[7]))), vec![7]);
    println!("all tests passed");
}
