fn longest_common_prefix<'a>(words: &[&'a str]) -> &'a str {
    let first = match words.first() {
        Some(w) => *w,
        None => return "",
    };
    let mut end = first.len();
    for w in &words[1..] {
        end = end.min(w.len());
        let common = first
            .char_indices()
            .zip(w.char_indices())
            .take_while(|((_, a), (_, b))| a == b && first.as_bytes().get(0..end).is_some())
            .map(|((i, a), _)| i + a.len_utf8())
            .last()
            .unwrap_or(0);
        end = end.min(common);
        if end == 0 {
            return "";
        }
    }
    &first[..end]
}

fn main() {
    let cases: Vec<Vec<&str>> = vec![
        vec![],
        vec![""],
        vec!["flower", "flow", "flight"],
        vec!["caf\u{e9}", "caf\u{e9}teria"],
        vec!["dog", "cat"],
    ];
