```rust
fn longest_palindrome(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    if chars.is_empty() {
        return String::new();
    }
    let (mut best_start, mut best_len) = (0usize, 1usize);

    let expand = |mut l: isize, mut r: isize| -> (usize, usize) {
        while l >= 0
            && (r as usize) < chars.len()
            && chars[l as usize] == chars[r as usize]
        {
            l -= 1;
            r += 1;
        }
        ((l + 1) as usize, (r - l - 1) as usize)
    };

    for i in 0..chars.len() {
        for &(l, r) in &[(i as isize, i as isize), (i as isize, i as isize + 1)] {
            let (start, len) = expand(l, r);
            if len > best_len {
                best_start = start;
                best_len = len;
            }
        }
    }
    chars[best_start..best_start + best_len].iter().collect()
}

fn main() {
    assert_eq!(longest_palindrome("babad"), "bab");
    assert_eq!(longest_palindrome("cbbd"), "bb");
    assert_eq!(longest_palindrome(""), "");
    assert_eq!(longest_palindrome("éé"), "éé");
    println!("{}", longest_palindrome("forgeeksskeegfor"));
}
