void reverse_in_place(char *s) {
    if (s == NULL) {
        return;
    }
    size_t len = strlen(s);
    if (len < 2) {
        return;
    }
    char *left = s;
    char *right = s + len - 1;
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        ++left;
        --right;
    }
