            case '(': case '[': case '{':
                st.push(c);
                break;
            case ')': case ']': case '}': {
                if (st.empty()) return false;
                char open = st.top();
                st.pop();
                if ((c == ')' && open != '(') ||
                    (c == ']' && open != '[') ||
                    (c == '}' && open != '{')) {
                    return false;
                }
                break;
            }
            default:
                break;  // ignore other characters
        }
    }
    return st.empty();
}

int main() {
    const char* cases[] = {"()[]{}", "([{}])", "(]", "(((", "", "a(b)c"};
    for (const char* c : cases) {
        std::cout << '\"' << c << "\" -> " << (is_balanced(c) ? "true" : "false") << '\n';
    }
    return 0;
}
```
A closing bracket that doesn't match the top of the stack returns false immediately; the final stack must be empty.

