```c
#include <stdio.h>
#include <ctype.h>

int main(void) {
    unsigned long lines = 0, words = 0, chars = 0;
    int c;
    int in_word = 0;

    while ((c = getchar()) != EOF) {
        chars++;
        if (c == '\n')
            lines++;
        if (isspace((unsigned char)c)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            words++;
        }
    }

    printf("%lu %lu %lu\n", lines, words, chars);
    return 0;
}
```

