```cpp
#include <cmath>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

int main() {
    std::string line;
    std::getline(std::cin, line);

    std::vector<double> values;
    std::stringstream ss(line);
    std::string token;
    while (std::getline(ss, token, ',')) {
        if (token.empty())
            continue;
        try {
            values.push_back(std::stod(token));
        } catch (const std::exception&) {
            std::cerr << "bad number: " << token << '\n';
            return 1;
        }
    }

    if (values.empty()) {
        std::cerr << "no numbers\n";
        return 1;
    }

    double sum = 0.0;
    for (double v : values) sum += v;
    double mean = sum / values.size();

    double variance = 0.0;
    for (double v : values) variance += (v - mean) * (v - mean);
    double sd = values.size() > 1 ? std::sqrt(variance / (values.size() - 1)) : 0.0;

    std::cout << "mean=" << mean << " sd=" << sd << "\n";
    return 0;
}
```

Empty tokens between commas are skipped, so trailing commas are tolerated. `std::stod` rejects garbage with an error rather than silently parsing a prefix in this loop only when the whole token is invalid; sample deviation uses `n-1` and degrades to zero for a single value. For very close large values the two-pass formula here avoids the cancellation that a running `mean` update suffers.

