#include <array>
#include <cstddef>
#include <iostream>

template <std::size_t N>
class RingSum {
public:
    void push(int v) {
        if (full_) sum_ -= buf_[head_];
        buf_[head_] = v;
        sum_ += v;
        head_ = (head_ + 1) % N;
        if (head_ == 0) full_ = true;
    }
    long long sum() const { return sum_; }
    bool full() const { return full_; }

private:
    std::array<int, N> buf_{};
    std::size_t head_ = 0;
    long long sum_ = 0;
    bool full_ = false;
};

int main() {
    RingSum<3> r;
    std::cout << r.sum() << '\n';  // 0
    r.push(5);
    r.push(-2);
    r.push(7);
    std::cout << r.sum() << '\n';  // 10
    r.push(1);
    std::cout << r.sum() << '\n';  // 6 (5 evicted)
    return 0;
}
```

`push` evicts the oldest value once the buffer is full, keeping `sum_` O(1) per insert. Output is `0`, `10`, `6`.

