#include <cstddef>
#include <iostream>
#include <vector>

template <typename T>
long long binary_search_index(const std::vector<T>& data, const T& target) {
    long long lo = 0;
    long long hi = static_cast<long long>(data.size()) - 1;
    while (lo <= hi) {
        long long mid = lo + (hi - lo) / 2;
        if (data[static_cast<std::size_t>(mid)] == target) {
            return mid;
        } else if (data[static_cast<std::size_t>(mid)] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    std::vector<int> v{1, 3, 5, 7, 9};
    std::cout << binary_search_index(v, 7) << "\n";   // 3
    std::cout << binary_search_index(v, 2) << "\n";   // -1
    std::cout << binary_search_index<int>({}, 1) << "\n"; // -1
}
```

`mid = lo + (hi - lo) / 2` avoids overflow on large ranges, and the empty vector path returns -1 because `hi` starts at -1.

