```rust
use std::thread;
use std::time::Duration;

fn retry<T, E, F>(attempts: u32, base: Duration, mut op: F) -> Result<T, E>
where
    F: FnMut() -> Result<T, E>,
{
    let mut delay = base;
    let mut last_err = None;
    for _ in 0..attempts.max(1) {
        match op() {
            Ok(value) => return Ok(value),
            Err(e) => {
                last_err = Some(e);
                thread::sleep(delay);
                delay = delay.saturating_mul(2);
            }
        }
    }
    Err(last_err.expect("attempts >= 1 guarantees an error is recorded"))
}

fn main() {
    let mut calls = 0;
    let result = retry(3, Duration::from_millis(1), || {
        calls += 1;
        if calls < 3 { Err("transient") } else { Ok(calls) }
    });
    assert_eq!(result, Ok(3));
}
```

`attempts.max(1)` guarantees at least one call, and `saturating_mul` keeps the backoff from overflowing on a large attempt count.

