#include <cstdio>
#include <stdexcept>
#include <utility>

class FileHandle {
public:
    explicit FileHandle(const char* path, const char* mode) : fp_(std::fopen(path, mode)) {
        if (!fp_) {
            throw std::runtime_error("failed to open file");
        }
    }

    ~FileHandle() {
        if (fp_) {
            std::fclose(fp_);
        }
    }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fp_(other.fp_) {
        other.fp_ = nullptr;
    }

    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            if (fp_) std::fclose(fp_);
            fp_ = other.fp_;
            other.fp_ = nullptr;
        }
        return *this;
    }

    std::FILE* get() const noexcept { return fp_; }

private:
    std::FILE* fp_;
};

int main() {
    FileHandle f("out.txt", "w");
    std::fputs("hello\n", f.get());
    FileHandle g(std::move(f));
    return g.get() ? 0 : 1;
}
