fn fib(n: u64) -> u128 {
    // Iterative to avoid exponential recursion; u128 delays overflow.
    if n == 0 {
        return 0;
    }
    let (mut prev, mut curr): (u128, u128) = (0, 1);
    for _ in 1..n {
        let next = prev + curr;
        prev = curr;
        curr = next;
    }
    curr
}

