def is_balanced(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            # A closer with no matching opener is unbalanced.
            if not stack or stack.pop() != pairs[ch]:
                return False
    # Any leftover opener means it was never closed.
    return not stack


