```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s <src> <dst>\n", argv[0]);
        return 1;
    }
    int in = open(argv[1], O_RDONLY);
    if (in < 0) { perror("open src"); return 1; }
    int out = open(argv[2], O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out < 0) { perror("open dst"); close(in); return 1; }

    char buf[4096];
    ssize_t n;
    while ((n = read(in, buf, sizeof buf)) > 0) {
        ssize_t written = 0;
        while (written < n) {
            ssize_t w = write(out, buf + written, n - written);
            if (w < 0) { perror("write"); close(in); close(out); return 1; }
            written += w;
        }
    }
    if (n < 0) perror("read");
    close(in);
    close(out);
    return n < 0 ? 1 : 0;
}
```
The inner loop retries short writes, which is required because `write` may accept fewer bytes than requested. Every open is paired with a close on the error paths, and the final return reflects whether the read loop hit an error rather than a clean EOF.

