```cpp
#include <cassert>
#include <list>
#include <optional>
#include <unordered_map>

class LRUCache {
public:
    explicit LRUCache(std::size_t capacity) : cap_(capacity) {
        assert(capacity > 0 && "capacity must be positive");
    }

    std::optional<int> get(int key) {
        auto it = index_.find(key);
        if (it == index_.end()) return std::nullopt;
        items_.splice(items_.begin(), items_, it->second);
        return it->second->value;
    }

    void put(int key, int value) {
        auto it = index_.find(key);
        if (it != index_.end()) {
            it->second->value = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (items_.size() == cap_) {
            index_.erase(items_.back().key);
            items_.pop_back();
        }
        items_.push_front({key, value});
        index_[key] = items_.begin();
    }

private:
    struct Entry { int key; int value; };
    std::size_t cap_;
    std::list<Entry> items_;
    std::unordered_map<int, std::list<Entry>::iterator> index_;
};

int main() {
    LRUCache c(2);
    c.put(1, 10);
    c.put(2, 20);
    assert(c.get(1).value() == 10);   // 1 becomes most recent
    c.put(3, 30);                      // evicts 2
    assert(!c.get(2).has_value());
    assert(c.get(3).value() == 30);
    assert(c.get(1).value() == 10);
    c.put(1, 99);
    assert(c.get(1).value() == 99);    // update in place
    return 0;
}
```

The list holds entries front-most-recent; the map points at list nodes so every operation is O(1). Updating an existing key mutates the node and moves it to the front; inserting at capacity evicts the list tail. The asserts exercise eviction, recency promotion and value updates.

