```python
import time
from contextlib import contextmanager
from typing import Iterator, Tuple, Type


@contextmanager
def retry(
    exceptions: Tuple[Type[BaseException], ...],
    attempts: int = 3,
    base_delay: float = 0.1,
    factor: float = 2.0,
) -> Iterator[None]:
    """Re-run the with-block up to `attempts` times on the given exceptions."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")
    delay = base_delay
    for attempt in range(1, attempts + 1):
        try:
            yield
            return
        except exceptions:
            if attempt == attempts:
                raise
            time.sleep(delay)
            delay *= factor


if __name__ == "__main__":
    calls = {"n": 0}

    with retry((ValueError,), attempts=3, base_delay=0.0):
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")

    assert calls["n"] == 3

    try:
        with retry((KeyError,), attempts=2, base_delay=0.0):
            raise KeyError("never caught")
    except KeyError:
        pass
    else:
        raise AssertionError("expected KeyError to propagate")

    print("ok")
```

`@contextmanager` lets the same generator re-enter the `yield` each attempt: the block re-executes, and only the listed exception types are swallowed. The final attempt re-raises so real failures surface, and any type not in `exceptions` propagates immediately. Setting `base_delay=0.0` makes the tests instant while production keeps real backoff.

