#include <cassert>
#include <iostream>
#include <vector>

std::vector<int> intersect(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] < b[j]) {
            ++i;
        } else if (a[i] > b[j]) {
            ++j;
        } else {
            // Emit distinct values only, skipping duplicates in both runs.
            out.push_back(a[i]);
            const int v = a[i];
            while (i < a.size() && a[i] == v) ++i;
            while (j < b.size() && b[j] == v) ++j;
        }
    }
    return out;
}

int main() {
    assert((intersect({}, {1, 2})) == std::vector<int>{});
    assert((intersect({1, 2, 2, 3}, {2, 2, 4})) == std::vector<int>{2});
    assert((intersect({1, 1, 1}, {1, 1})) == std::vector<int>{1});
    assert((intersect({-3, 0, 4}, {-3, 4, 9})) == std::vector<int>({-3, 4}));

    for (int v : intersect({1, 2, 2, 3}, {2, 2, 4})) std::cout << v << '\n';
    return 0;
}
```

Two indices advance in lockstep: the smaller value is skipped, a match is emitted once and all duplicates of it are consumed on both sides. That keeps the result de-duplicated and the whole pass linear. Empty inputs and all-duplicate inputs fall out of the same loop.

