#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* next = head->next;  // save before rewiring
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;  // new head
}

void print(Node* head) {
    for (Node* p = head; p; p = p->next)
        std::cout << p->value << (p->next ? " -> " : "\n");
}

int main() {
    Node* head = nullptr;
    Node* tail = nullptr;
    for (int v : {1, 2, 3, 4}) {
        Node* n = new Node(v);
        if (!head) head = tail = n;
        else { tail->next = n; tail = n; }
    }
    print(head);          // 1 -> 2 -> 3 -> 4
    head = reverse(head); // nullptr head is handled: loop never runs
    print(head);          // 4 -> 3 -> 2 -> 1

    // free
    while (head) { Node* n = head->next; delete head; head = n; }
    return 0;
}
