```c
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>
#include <string.h>

/* Returns 0 on success, -1 on failure. On success *out holds the value. */
int parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return -1;

    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);

    if (errno == ERANGE) return -1;              /* out of long range */
    if (end == s || *end != '\0') return -1;     /* no digits or trailing junk */
    if (v < INT_MIN || v > INT_MAX) return -1;   /* out of int range */

    *out = (int)v;
    return 0;
}

int main(void) {
    const char *tests[] = {"42", "-7", "  5", "12x", "", "999999999999", NULL};
    for (int i = 0; tests[i]; i++) {
        int v;
        if (parse_int(tests[i], &v) == 0)
            printf("%-14s -> %d\n", tests[i], v);
        else
            printf("%-14s -> error\n", tests[i]);
    }
    return 0;
}
```

`strtol` is used instead of `atoi` because `atoi` cannot distinguish `"0"` from `"abc"` and has undefined behaviour on overflow. `errno == ERANGE` catches values beyond `long`, and the `INT_MIN/INT_MAX` check catches values that fit in `long` but not `int`. Trailing junk (`"12x"`) is rejected because `*end` is not the terminator.

