def normalize_path(path):
    absolute = path.startswith('/')
    parts = []
    for seg in path.split('/'):
        if seg == '' or seg == '.':
            continue
        if seg == '..':
            if parts and parts[-1] != '..':
                parts.pop()
            elif not absolute:
                parts.append('..')
            # at root (absolute) '..' is dropped
        else:
            parts.append(seg)
    result = '/'.join(parts)
    return ('/' + result) if absolute else (result or '.')

if __name__ == "__main__":
