```python
class RingBuffer:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._buf = [None] * capacity
        self._cap = capacity
        self._count = 0
        self._head = 0

    def push(self, item) -> None:
        self._buf[(self._head + self._count) % self._cap] = item
        if self._count < self._cap:
            self._count += 1
        else:
            self._head = (self._head + 1) % self._cap

    def get(self, i: int):
        if not 0 <= i < self._count:
            raise IndexError("index out of range")
        return self._buf[(self._head + i) % self._cap]

    def __len__(self) -> int:
        return self._count


if __name__ == "__main__":
    rb = RingBuffer(3)
    for v in range(5):
        rb.push(v)
    print(len(rb), [rb.get(i) for i in range(len(rb))])
```

When full, overwriting the slot and advancing `_head` discards the oldest item, so `[2, 3, 4]` remains; `get` validates against the live count.

