use std::collections::HashSet;
use std::hash::Hash;

pub fn dedup_keep_order<T: Eq + Hash + Clone>(items: &[T]) -> Vec<T> {
    let mut seen = HashSet::new();
    let mut out = Vec::new();
    for item in items {
        if seen.insert(item.clone()) {
            out.push(item.clone());
        }
    }
    out
}

fn main() {
    let v = vec![3, 1, 3, 2, 1, 4];
    println!("{:?}", dedup_keep_order(&v)); // [3, 1, 2, 4]
}
