```c
#include <stdio.h>

int binary_search(const int *arr, int n, int target) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;   /* avoids overflow */
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main(void) {
    int data[] = {1, 3, 5, 7, 9, 11};
    printf("%d\n", binary_search(data, 6, 7));   /* 3 */
    printf("%d\n", binary_search(data, 6, 8));   /* -1 */
    printf("%d\n", binary_search(data, 0, 1));   /* -1 */
    return 0;
}
```
`lo + (hi - lo) / 2` keeps `mid` in range even when `lo` and `hi` are large. The empty array works because `hi` starts at `-1` and the loop never executes. Inputs must be sorted ascending — that precondition is on the caller.

