`yield from` delegates to the recursive call and flattens the generator chain, so nothing is materialized until you consume it. `isinstance` accepts tuples as containers too. A string is intentionally *not* treated as a container, so `"ab"` stays one leaf rather than exploding into characters.

```python
import random


def kth_smallest(nums, k):
    if not nums:
        raise ValueError("nums must be non-empty")
    if k < 1 or k > len(nums):
        raise ValueError("k out of range")

    def select(lo, hi, k):
        if lo == hi:
            return nums[lo]
        pivot = nums[random.randint(lo, hi)]
        lt, gt = lo, hi
        i = lo
        while i <= gt:
            if nums[i] < pivot:
                nums[lt], nums[i] = nums[i], nums[lt]
                lt += 1
                i += 1
            elif nums[i] > pivot:
                nums[gt], nums[i] = nums[i], nums[gt]
                gt -= 1
            else:
                i += 1
        if k < lt:
            return select(lo, lt - 1, k)
        if k > gt:
            return select(gt + 1, hi, k)
        return pivot

    return select(0, len(nums) - 1, k - 1)


if __name__ == "__main__":
    data = [7, 3, 9, 1, 5, 3]
    assert kth_smallest(data[:], 1) == 1
    assert kth_smallest(data[:], 2) == 3
    assert kth_smallest(data[:], 6) == 9
    try:
        kth_smallest([], 1)
    except ValueError:
        pass
    print("ok")
