void reverse_in_place(char* s) {
    if (s == nullptr) {
        return;
    }
    std::size_t n = std::strlen(s);
    if (n < 2) {
        return;
    }
    char* lo = s;
    char* hi = s + n - 1;
    while (lo < hi) {
        std::swap(*lo, *hi);
        ++lo;
        --hi;
    }
}

int main() {
