def merge(left_path, right_path, out=sys.stdout):
    left = load(left_path, "id")
    right = load(right_path, "id")
    shared = sorted(set(left) & set(right), key=str)
    fields = list(left[shared[0]].keys()) if shared else []
    writer = csv.DictWriter(out, fieldnames=fields)
    if fields:
        writer.writeheader()
    for row_id in shared:
        merged = {**left[row_id], **right[row_id]}
        writer.writerow(merged)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise SystemExit("usage: merge.py LEFT.csv RIGHT.csv")
