```rust
pub fn longest_common_prefix(words: &[&str]) -> String {
    if words.is_empty() {
        return String::new();
    }

    let first = words[0];
    let mut prefix_len = first.len();

    for w in &words[1..] {
        let limit = prefix_len.min(w.len());
        let mut i = 0;
        while i < limit && first.as_bytes()[i] == w.as_bytes()[i] {
            i += 1;
        }
        prefix_len = i;
        if prefix_len == 0 {
            break;
        }
    }

    first[..prefix_len].to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
        assert_eq!(longest_common_prefix(&["dog", "racecar", "car"]), "");
        assert_eq!(longest_common_prefix(&[]), "");
        assert_eq!(longest_common_prefix(&["single"]), "single");
    }

    #[test]
    fn unicode_boundary() {
        // "café" and "cafézone" share the first four bytes ("caf" + 'é' 2 bytes)
        assert_eq!(longest_common_prefix(&["café", "cafézone"]), "café");
    }
}
```

Byte comparison is only used to find the common byte run, then it is sliced back to a valid UTF-8 boundary — safe for multibyte input since the shared bytes form a complete prefix.

