fn count(path: &str) -> io::Result<(u64, u64, u64)> {
    let file = File::open(path)?;
    let mut reader = BufReader::new(file);

    let mut bytes: u64 = 0;
    let mut words: u64 = 0;
    let mut lines: u64 = 0;
    let mut in_word = false;
    let mut buf = [0u8; 8192];

    loop {
        let n = reader.read(&mut buf)?;
        if n == 0 {
            break;
        }
        bytes += n as u64;
        for &b in &buf[..n] {
            if b == b'\n' {
                lines += 1;
            }
            let ws = (b as char).is_ascii_whitespace();
            if ws {
                in_word = false;
            } else if !in_word {
                in_word = true;
                words += 1;
            }
        }
    }

    Ok((lines, words, bytes))
}
