#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <cstdint>

static bool parse_ipv4(const std::string& s, uint32_t& out) {
    std::vector<std::string> parts;
    std::string cur;
    std::istringstream ss(s);
    while (std::getline(ss, cur, '.')) {
        parts.push_back(cur);
    }
    // getline drops a trailing empty field on "1.2.3."; catch it explicitly.
    if (!s.empty() && s.back() == '.') return false;
    if (parts.size() != 4) return false;

    uint32_t value = 0;
    for (const auto& p : parts) {
        if (p.empty() || p.size() > 3) return false;
        uint32_t n = 0;
        for (char c : p) {
            if (c < '0' || c > '9') return false;
            n = n * 10 + static_cast<uint32_t>(c - '0');
        }
        if (n > 255) return false;
        // Reject leading zeros like "01" (ambiguous octal) but allow plain "0".
        if (p.size() > 1 && p[0] == '0') return false;
        value = (value << 8) | n;
    }
    out = value;
    return true;
}

int main() {
    const std::vector<std::string> tests = {
        "192.168.0.1", "0.0.0.0", "255.255.255.255",
        "256.1.1.1", "1.2.3", "1.2.3.4.5", "1.2.3.",
        "01.2.3.4", "a.b.c.d", "", "1..2.3"
    };
    for (const auto& t : tests) {
        uint32_t v = 0;
        std::cout << t << " -> " << (parse_ipv4(t, v) ? "valid" : "invalid");
        if (v) std::cout << " (" << v << ")";
        std::cout << '\n';
    }
    return 0;
}
