def is_balanced(s: str) -> bool:
    """Return True if brackets in s are correctly balanced and nested.

    Accepts (), [], {} only; ignores any other character.
    The empty string is balanced by definition.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack


