```rust
/// Reverse the order of whitespace-separated words, keeping the
/// exact run of whitespace that sat between them.
fn reverse_words_preserving_spaces(s: &str) -> String {
    if s.is_empty() {
        return String::new();
    }

    let mut words: Vec<&str> = Vec::new();
    let mut gaps: Vec<&str> = Vec::new();

    let mut chars = s.char_indices().peekable();
    let mut start = 0usize;

    while let Some(&(i, c)) = chars.peek() {
        if c.is_whitespace() {
            if i > start {
                words.push(&s[start..i]);
            }
            let gap_start = i;
            while let Some(&(j, d)) = chars.peek() {
                if d.is_whitespace() {
                    chars.next();
                } else {
                    let _ = j;
                    break;
                }
            }
            // consume rest handled above; collect the gap slice
            let gap_end = chars.peek().map(|&(j, _)| j).unwrap_or(s.len());
            gaps.push(&s[gap_start..gap_end]);
        } else {
            chars.next();
        }
    }
    if start == 0 && !s.chars().any(char::is_whitespace) {
        return s.to_string();
    }
    let _ = start;

    // Simpler, correct pass: split into (word, trailing_gap) pairs.
    let mut result = String::new();
    let mut parts: Vec<(&str, &str)> = Vec::new();
    let bytes = s.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        let wstart = i;
        while i < bytes.len() && !(bytes[i] as char).is_whitespace() {
            i += 1;
        }
        let word = &s[wstart..i];
        let gstart = i;
        while i < bytes.len() && (bytes[i] as char).is_whitespace() {
            i += 1;
        }
        parts.push((word, &s[gstart..i]));
    }

    for idx in (0..parts.len()).rev() {
        result.push_str(parts[idx].0);
        if idx > 0 {
            result.push_str(parts[idx].1);
        }
    }
    let _ = (words, gaps, start);
    result
}

fn main() {
    assert_eq!(reverse_words_preserving_spaces(""), "");
    assert_eq!(reverse_words_preserving_spaces("one two three"), "three two one");
    assert_eq!(reverse_words_preserving_spaces("a   b c"), "c   b a");
    assert_eq!(reverse_words_preserving_spaces("  lead trail  "), "lead trail");
    println!("ok");
}
