/// GCD that works for negatives and returns a non-negative result.
/// gcd(0, 0) is defined here as 0.
fn gcd(mut a: i64, mut b: i64) -> i64 {
    a = a.abs();
    b = b.abs();
    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }
    a
}

