    }
}

std::string strip_vowels(const std::string& s) {
    std::string out;
    out.reserve(s.size());
    for (unsigned char c : s) {
        // Bytes >= 0x80 belong to multi-byte UTF-8 sequences;
        // they can never equal an ASCII vowel, so they pass through.
        if (!is_ascii_vowel(c)) {
            out.push_back(static_cast<char>(c));
        }
    }
    return out;
}

int main() {
    std::cout << strip_vowels("Hello World") << '\n';   // Hll Wrld
    std::cout << strip_vowels("caf\xC3\xA9") << '\n';  // caf\xC3\xA9 (é kept)
