    for raw in text.split():
        word = normalize(raw)
        # keep only words with at least one alphanumeric character
        if any(ch.isalnum() for ch in word):
            counts[word] += 1
    # sort by count desc, then word asc for deterministic output
    for word, count in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:n]:
        print(f"{count:5d}  {word}")
    return 0


