// Parses an optional leading '-' followed by one or more digits.
// Returns std::nullopt on empty input, non-digit characters, or overflow.
std::optional<int> parse_int(std::string_view sv) {
    if (sv.empty()) return std::nullopt;

    bool negative = false;
    std::size_t i = 0;
    if (sv[0] == '+' || sv[0] == '-') {
        negative = (sv[0] == '-');
        i = 1;
        if (i == sv.size()) return std::nullopt;  // lone sign
    }

    // Accumulate in int64 so we can detect overflow past INT_MIN/INT_MAX.
    std::int64_t acc = 0;
    for (; i < sv.size(); ++i) {
        unsigned char c = static_cast<unsigned char>(sv[i]);
        if (c < '0' || c > '9') return std::nullopt;
        acc = acc * 10 + (c - '0');
        if (acc > (std::int64_t)std::numeric_limits<int>::max() + 1) {
            return std::nullopt;  // far past range, bail early
        }
    }

    if (negative) {
        acc = -acc;
        if (acc < std::numeric_limits<int>::min()) return std::nullopt;
    } else if (acc > std::numeric_limits<int>::max()) {
        return std::nullopt;
    }
    return static_cast<int>(acc);
}
```

`-2147483648` (INT_MIN) is accepted because the accumulation stays in `int64_t`; anything outside `[INT_MIN, INT_MAX]` returns `nullopt`.

