/// Returns F(n) with F(0) = 0, F(1) = 1.
/// Panics if the value overflows u128 (roughly F(186) and beyond).
pub fn fib(n: u32) -> u128 {
    let (mut a, mut b) = (0u128, 1u128);
    for _ in 0..n {
        let next = a.checked_add(b).expect("fibonacci overflowed u128");
        a = b;
        b = next;
    }
    a
}

fn main() {
    assert_eq!(fib(0), 0);
    assert_eq!(fib(1), 1);
    assert_eq!(fib(10), 55);
    assert_eq!(fib(90), 2880067194370816120);

    println!("fib(30) = {}", fib(30));

    // Overflow behaviour is explicit: this panics.
    let result = std::panic::catch_unwind(|| fib(200));
    assert!(result.is_err(), "expected overflow panic");
    println!("overflow detected as expected");
}
```

`checked_add` turns silent wrapping into a panic with a clear message. `fib(0)` returns 0 because the loop runs zero times and `a` stays 0.

