/* Returns base^exp, or 0 if the result would overflow a long long. */
long long ipow_checked(long long base, unsigned exp, bool *ok) {
    if (ok) *ok = true;
    long long result = 1;
    long long b = base;
    while (exp > 0) {
        if (exp & 1u) {
            if (b != 0 && result > LLONG_MAX / b) {
                if (ok) *ok = false;
                return 0;
            }
            result *= b;
        }
        exp >>= 1u;
        if (exp > 0) {
            if (b != 0 && b > LLONG_MAX / b) {
                if (ok) *ok = false;
                return 0;
            }
            b *= b;
        }
    }
    return result;
}

#ifdef DEMO
