int main(void) {
    bool ok;
    printf("%lld\n", ipow_checked(2, 10, &ok));   /* 1024 */
    printf("ok=%d\n", ok);
    printf("%lld\n", ipow_checked(2, 63, &ok));   /* overflow -> 0 */
    printf("ok=%d\n", ok);
    return 0;
}
#endif
