class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._cap = capacity
        self._buf = [0.0] * capacity
        self._len = 0
        self._next = 0

    def append(self, value):
        self._buf[self._next] = float(value)
        self._next = (self._next + 1) % self._cap
        if self._len < self._cap:
            self._len += 1

    def latest(self):
        if self._len == 0:
            return None
        return self._buf[(self._next - 1) % self._cap]

    def mean(self):
        if self._len == 0:
            return None
        total = 0.0
        for i in range(self._len):
            total += self._buf[i]
        return total / self._len


if __name__ == "__main__":
    r = RingBuffer(3)
    assert r.latest() is None and r.mean() is None
    for v in (1.0, 2.0, 3.0, 4.0):
        r.append(v)
    assert r.latest() == 4.0
    assert abs(r.mean() - 3.0) < 1e-9
