fn merge_unique(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out: Vec<i32> = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);
    while i < a.len() || j < b.len() {
