class RunningMedian {
public:
    void add(int value) {
        if (low_.empty() || value <= low_.top()) {
            low_.push(value);
        } else {
            high_.push(value);
        }
        // low_ may have at most one more element than high_.
        if (low_.size() > high_.size() + 1) {
            high_.push(low_.top());
            low_.pop();
        } else if (high_.size() > low_.size()) {
            low_.push(high_.top());
            high_.pop();
        }
    }

    double median() const {
        if (low_.empty()) {
            throw std::logic_error("no values");
        }
        if (low_.size() == high_.size()) {
            return (static_cast<double>(low_.top()) + high_.top()) / 2.0;
        }
        return static_cast<double>(low_.top());
    }

private:
    std::priority_queue<int> low_;                                  // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high_;  // min-heap
};

int main() {
    RunningMedian rm;
    long long value;
    while (std::cin >> value) {
        rm.add(static_cast<int>(value));
        std::cout << rm.median() << '\n';
    }
    return 0;
}
