```c
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *curr = head;
    while (curr != NULL) {
        Node *next = curr->next;  // save before rewiring
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (n == NULL) {
        return head;  // allocation failure: leave list unchanged
    }
    n->value = value;
    n->next = head;
    return n;
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 4; i++) {
        head = push(head, i);  // 4 3 2 1
    }
    head = reverse(head);
    for (Node *p = head; p != NULL; p = p->next) {
        printf("%d ", p->value);
    }
    putchar('\n');
    free_list(head);
    return 0;
}
```
Iterative reversal is O(n) time, O(1) extra space. Storing `next` before rewiring `curr->next` is what prevents losing the rest of the list.

