fn merge_unique(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);

    while i < a.len() || j < b.len() {
        let candidate = if j >= b.len() || (i < a.len() && a[i] <= b[j]) {
            let v = a[i];
            i += 1;
            v
        } else {
            let v = b[j];
            j += 1;
            v
        };

        if out.last() != Some(&candidate) {
            out.push(candidate);
        }
    }

    out
}

fn main() {
    assert_eq!(merge_unique(&[1, 3, 5], &[2, 3, 6]), vec![1, 2, 3, 5, 6]);
    assert_eq!(merge_unique(&[], &[7, 7, 8]), vec![7, 8]);
    assert_eq!(merge_unique(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_unique(&[1, 1, 1], &[]), vec![1]);
    println!("ok");
}
