#include <ctype.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

#define MAX_OCTET_CHARS 3

bool parse_ipv4(const char *s, unsigned char out[4]) {
    int part = 0;
    const char *p = s;

    while (part < 4) {
        int value = 0;
        int digits = 0;
        while (isdigit((unsigned char)*p)) {
            if (digits >= MAX_OCTET_CHARS) {
                return false;  // e.g. "1234"
            }
            value = value * 10 + (*p - '0');
            digits++;
            p++;
        }
        if (digits == 0) {
            return false;  // empty octet, e.g. "1..2"
        }
        if (value > 255) {
            return false;
        }
        // Reject leading zeros such as "01".
        if (digits > 1 && s[0] == '0') {
            return false;
        }
        out[part++] = (unsigned char)value;
        if (part == 4) {
            break;
        }
        if (*p != '.') {
            return false;
        }
        p++;
    }

    return *p == '\0';
}

int main(void) {
    unsigned char ip[4];
    const char *tests[] = {"192.168.0.1", "255.255.255.255", "256.1.1.1", "1.2.3", "1.2.3.4.5", "01.2.3.4"};
    for (size_t i = 0; i < sizeof tests / sizeof tests[0]; i++) {
        bool ok = parse_ipv4(tests[i], ip);
        if (ok) {
            printf("%s -> %u.%u.%u.%u\n", tests[i], ip[0], ip[1], ip[2], ip[3]);
        } else {
            printf("%s -> invalid\n", tests[i]);
        }
    }
    return 0;
}
```
The parser checks trailing input with `*p == '\0'`, so addresses with extra octets are rejected. Leading-zero rejection matches the strict textual form used by many tools.

