#include <cctype>
#include <iostream>
#include <string>

bool is_palindrome(const std::string& s) {
    std::size_t i = 0;
    std::size_t j = s.size();
    while (i < j) {
        // Advance i to the next alphanumeric character.
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[i]))) ++i;
        // Retreat j to the previous alphanumeric character.
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[j - 1]))) --j;
        if (i >= j) break;
        char a = std::tolower(static_cast<unsigned char>(s[i]));
        char b = std::tolower(static_cast<unsigned char>(s[j - 1]));
        if (a != b) return false;
        ++i;
        --j;
    }
    return true;
}

int main() {
    const std::string tests[] = {
        "", "a", "Aa", "racecar", "A man, a plan, a canal: Panama",
        "hello", "No 'x' in Nixon"
    };
    const bool expected[] = {true, true, true, true, true, false, true};
    for (std::size_t k = 0; k < sizeof(tests) / sizeof(tests[0]); ++k) {
        bool got = is_palindrome(tests[k]);
        std::cout << (got == expected[k] ? "ok  " : "FAIL") << "  " << tests[k] << "\n";
        if (got != expected[k]) return 1;
    }
    return 0;
}
```

The `unsigned char` casts prevent undefined behavior from negative `char` values passed to `isalnum`/`tolower`. Empty and single-character inputs return true.

