```python
def fib(n):
    """Return the n-th Fibonacci number, with fib(0)=0 and fib(1)=1.

    Uses iterative fast doubling: O(log n) multiplications, no recursion.
    """
    if n < 0:
        raise ValueError("n must be non-negative")

    def _pair(k):
        # Returns (F(k), F(k+1)) in O(log k).
        if k == 0:
            return (0, 1)
        a, b = _pair(k >> 1)
        c = a * ((b << 1) - a)   # F(2m)
        d = a * a + b * b        # F(2m+1)
        if k & 1:
            return (d, c + d)
        return (c, d)

    # Convert the recursive core to an explicit stack so large n
    # does not hit Python's recursion limit.
    stack = []
    k = n
    while k > 1:
        stack.append(k & 1)
        k >>= 1
    a, b = 0, 1
    for bit in reversed(stack):
        c = a * ((b << 1) - a)
        d = a * a + b * b
        if bit:
            a, b = d, c + d
        else:
            a, b = c, d
    return a

if __name__ == "__main__":
    assert fib(0) == 0
    assert fib(1) == 1
    assert fib(10) == 55
    assert fib(50) == 12586269025
    assert fib(100) == 354224848179261915075
    try:
        fib(-1)
    except ValueError:
        pass
    else:
        raise AssertionError("negative input should raise")
    print("all checks passed")
```

The doubling identities are `F(2m) = F(m)*(2*F(m+1) - F(m))` and `F(2m+1) = F(m)^2 + F(m+1)^2`. The bit stack turns the log-depth recursion into a loop, so `fib(10000)` works without a recursion-limit error.

