def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    def expand(left: int, right: int) -> str:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left + 1:right]

    best = ""
    for i in range(len(s)):
        odd = expand(i, i)
        even = expand(i, i + 1)
        if len(odd) > len(best):
            best = odd
        if len(even) > len(best):
            best = even
    return best


if __name__ == "__main__":
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "abacaba"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```

`expand` grows outward from a center while characters match, returning the slice between the final mismatched bounds. Trying every index as both an odd center `(i, i)` and an even center `(i, i+1)` covers all palindromes in O(n²) time, O(1) extra space. The `if not s` guard returns `""` for empty input instead of crashing on `range(0)`.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._store: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._store:
            return -1
        self._store.move_to_end(key)
        return self._store[key]

    def put(self, key, value) -> None:
        if key in self._store:
            self._store.move_to_end(key)
        self._store[key] = value
        if len(self._store) > self.capacity:
            self._store.popitem(last=False)

    def __len__(self) -> int:
        return len(self._store)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, "a")
    c.put(2, "b")
    assert c.get(1) == "a"      # 1 now most recent
    c.put(3, "c")               # evicts 2
    assert c.get(2) == -1
    assert list(c._store) == [1, 3]
    try:
        LRUCache(0)
    except ValueError as e:
        print("rejected:", e)
```

`OrderedDict.move_to_end` marks a hit as most-recently used; `popitem(last=False)` removes the oldest. Because a key access or insert touches exactly one dictionary operation, both `get` and `put` stay O(1) amortized. The constructor guard catches capacity `0` or negative before any state is built.

