def is_valid_ipv4(address: str) -> bool:
    if not isinstance(address, str):
        return False
    parts = address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":   # reject leading zeros
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True


if __name__ == "__main__":
    good = ["0.0.0.0", "127.0.0.1", "255.255.255.255", "192.168.1.1"]
    bad = ["256.1.1.1", "1.2.3", "1.2.3.4.5", "01.2.3.4", "1.2.3.a", "", "1.2.3.-4"]
    for a in good:
        assert is_valid_ipv4(a), a
    for a in bad:
        assert not is_valid_ipv4(a), a
    print("all checks passed")
```

The split must yield exactly four parts. `part.isdigit()` rejects signs, spaces, and letters, so `-4` and `a` fail. The leading-zero check blocks `01` while still allowing `0`. The range test rejects `256` and anything above. Both lists are asserted so a regression fails loudly; the empty string splits to one part and is rejected.

