#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define MAXN 94

static uint64_t memo[MAXN + 1];
static int computed[MAXN + 1];

static uint64_t fib(int n) {
    if (n <= 1) return (uint64_t)n;
    if (computed[n]) return memo[n];
    memo[n] = fib(n - 1) + fib(n - 2);
    computed[n] = 1;
    return memo[n];
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        fprintf(stderr, "invalid input\n");
        return 1;
    }
    if (n < 0) {
        fprintf(stderr, "n must be non-negative\n");
        return 1;
    }
    if (n > MAXN) {
        printf("overflow: fib(%d) exceeds 64-bit range\n", n);
        return 0;
    }
    printf("%llu\n", (unsigned long long)fib(n));
    return 0;
}
