def validate_email(addr: str) -> tuple[bool, str]:
    if not addr:
        return False, "empty address"
    if addr.count("@") != 1:
        return False, "must contain exactly one @"
    local, _, domain = addr.partition("@")
    if not local:
        return False, "local part is empty"
    if not domain:
        return False, "domain is empty"
    if domain.startswith(".") or domain.endswith("."):
        return False, "domain cannot start or end with a dot"
    if ".." in domain or ".." in local:
        return False, "consecutive dots are not allowed"
    labels = domain.split(".")
    if len(labels) < 2:
        return False, "domain must have at least two labels"
    for label in labels:
        if not label:
            return False, "empty domain label"
        if label.startswith("-") or label.endswith("-"):
            return False, "domain label cannot start or end with a hyphen"
        if not all(c.isalnum() or c == "-" for c in label):
            return False, "domain label has invalid characters"
    if not all(c.isalnum() or c in "._%+-'" for c in local):
        return False, "local part has invalid characters"
    return True, "valid"


if __name__ == "__main__":
    for e in ["a@b.co", "bad@", "@bad.com", "a..b@x.com", "x@-bad.com", ""]:
        print(e, validate_email(e))
