```c
#include <stddef.h>
#include <stdio.h>

int binary_search(const int *arr, size_t n, int target) {
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) {
            return (int)mid;
        } else if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

int main(void) {
    int data[] = {1, 3, 5, 7, 9, 11};
    size_t n = sizeof(data) / sizeof(data[0]);
    printf("%d\n", binary_search(data, n, 7));   /* 3 */
    printf("%d\n", binary_search(data, n, 4));   /* -1 */
    printf("%d\n", binary_search(data, 0, 1));   /* -1 */
    return 0;
}
```

Using `size_t` and the half-open interval `[lo, hi)` avoids signed/unsigned mixing and off-by-one errors. `lo + (hi - lo) / 2` prevents `lo + hi` overflow on large arrays.

