```cpp
#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        if (count_ == N) {
            throw std::overflow_error("ring buffer full");
        }
        data_[(head_ + count_) % N] = value;
        ++count_;
    }

    std::optional<T> pop() {
        if (count_ == 0) {
            return std::nullopt;
        }
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    std::size_t capacity() const { return N; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};
```

Push throws on overflow so an accidental overrun is loud instead of silently dropping data.

