        }
        let v = helper(n - 1, memo)
            .checked_add(helper(n - 2, memo))
            .expect("fibonacci overflowed u64");
        memo.insert(n, v);
        v
    }
    helper(n, &mut memo)
}

fn fib_iter(n: u64) -> u64 {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let next = a.checked_add(b).expect("fibonacci overflowed u64");
        a = b;
        b = next;
    }
    a
}

fn main() {
    assert_eq!(fib_memo(0), 0);
    assert_eq!(fib_memo(10), 55);
    assert_eq!(fib_iter(10), 55);
    assert_eq!(fib_iter(90), fib_memo(90));
    println!("fib(90) = {}", fib_iter(90));
}
