#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* Copy src into dst, truncating if needed. dst is always NUL-terminated.
 * Returns the number of bytes copied (excluding the NUL). */
size_t safe_copy(char *dst, size_t dst_size, const char *src) {
    if (dst == NULL || src == NULL || dst_size == 0) {
        return 0;
    }
    size_t i = 0;
    while (i + 1 < dst_size && src[i] != '\0') {
        dst[i] = src[i];
        ++i;
    }
    dst[i] = '\0';
    return i;
}

int main(void) {
    char buf[8];
    size_t n;

    n = safe_copy(buf, sizeof buf, "hello");
    printf("%zu %s\n", n, buf);
    if (n != 5 || strcmp(buf, "hello") != 0) return 1;

    n = safe_copy(buf, sizeof buf, "this is far too long");
    printf("%zu %s\n", n, buf);
    if (n != 7 || strcmp(buf, "this is") != 0) return 1;

    n = safe_copy(buf, 0, "ignored");
    if (n != 0) return 1;

    puts("ok");
