class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), capacity_(capacity), size_(0), head_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(double value) {
        data_[head_] = value;
        head_ = (head_ + 1) % capacity_;
        if (size_ < capacity_) ++size_;
    }

    std::optional<double> latest() const {
        if (size_ == 0) return std::nullopt;
        return data_[(head_ + capacity_ - 1) % capacity_];
    }

    bool empty() const { return size_ == 0; }

private:
    std::vector<double> data_;
    std::size_t capacity_;
    std::size_t size_;
    std::size_t head_;
};

int main() {
    RingBuffer rb(3);
    if (rb.latest().has_value()) return 1;
    rb.push(1.5);
    rb.push(2.5);
    rb.push(3.5);
    rb.push(4.5);
    if (*rb.latest() != 4.5) return 1;
    std::cout << "latest=" << *rb.latest() << "\n";
    return 0;
}
