```rust
pub fn longest_common_prefix(words: &[String]) -> String {
    let Some(first) = words.first() else {
        return String::new();
    };
    let mut end = first.len();
    for w in &words[1..] {
        let mut i = 0;
        let a = first.as_bytes();
        let b = w.as_bytes();
        let max = a.len().min(b.len()).min(end);
        while i < max && a[i] == b[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    // Only slice on a char boundary: bytes match, but UTF-8 continuation
    // bytes must not be split from their leading byte.
    while !first.is_char_boundary(end) {
        end -= 1;
    }
    first[..end].to_string()
}

fn main() {
    assert_eq!(longest_common_prefix(&[]), "");
    let v = vec!["flower".to_string(), "flow".to_string(), "flight".to_string()];
    assert_eq!(longest_common_prefix(&v), "fl");
    let u = vec!["café".to_string(), "café au lait".to_string()];
    assert_eq!(longest_common_prefix(&u), "café");
    println!("ok");
}
```

