```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUCKETS 4096

typedef struct Node {
    char *word;
    long count;
    struct Node *next;
} Node;

static Node *table[BUCKETS];

static unsigned long hash(const char *s) {
    unsigned long h = 5381;
    while (*s) h = ((h << 5) + h) ^ (unsigned char)*s++;
    return h % BUCKETS;
}

static void add(const char *word) {
    unsigned long i = hash(word);
    for (Node *n = table[i]; n; n = n->next) {
        if (strcmp(n->word, word) == 0) { n->count++; return; }
    }
    Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(1); }
    n->word = strdup(word);
    if (!n->word) { perror("strdup"); exit(1); }
    n->count = 1;
    n->next = table[i];
    table[i] = n;
}

int main(void) {
    char buf[256];
    size_t len = 0;
    int c;
    while ((c = getchar()) != EOF) {
        if (isalpha((unsigned char)c) || c == '\'') {
            if (len + 1 < sizeof buf) buf[len++] = (char)c;
        } else if (len > 0) {
            buf[len] = '\0';
            add(buf);
            len = 0;
        }
    }
    if (len > 0) { buf[len] = '\0'; add(buf); }

    for (int i = 0; i < BUCKETS; i++)
        for (Node *n = table[i]; n; n = n->next)
            printf("%ld %s\n", n->count, n->word);
    return 0;
}
```

