#include <iostream>
#include <vector>

template <typename T>
std::vector<T> merge_sorted(const std::vector<T>& a, const std::vector<T>& b) {
    std::vector<T> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (b[j] < a[i]) {
            out.push_back(b[j++]);
        } else {
            out.push_back(a[i++]);
        }
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5};
    std::vector<int> b{2, 4, 6};
    auto m = merge_sorted(a, b);
    if (m != std::vector<int>({1, 2, 3, 4, 5, 6})) return 1;

    std::vector<int> empty;
    if (merge_sorted(a, empty) != a) return 1;
    if (!merge_sorted(empty, empty).empty()) return 1;

    std::vector<int> dup{2, 2, 2};
    if (merge_sorted(dup, dup).size() != 6) return 1;

    std::cout << "ok\n";
    return 0;
}
