#include <stdio.h>
#include <string.h>

static void reverse(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    for (size_t i = 0; i < len / 2; ++i) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <string>...\n", argv[0]);
        return 1;
    }
    for (int i = 1; i < argc; ++i) {
        char *s = strdup(argv[i]);
        if (s == NULL) {
            fprintf(stderr, "out of memory\n");
            return 1;
        }
        reverse(s);
        printf("%s -> %s\n", argv[i], s);
        free(s);
    }
    return 0;
}
```

`strdup` makes a writable copy because `argv` strings are not guaranteed modifiable. The swap loop runs only to `len / 2`, so the middle character of an odd-length string stays put. `strdup` is POSIX; on strict ISO C you can replace it with `malloc(len + 1)` and `memcpy`.

