```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : cap_(capacity), buf_(new double[capacity]), head_(0), size_(0) {}

    ~RingBuffer() { delete[] buf_; }
    RingBuffer(const RingBuffer&) = delete;
    RingBuffer& operator=(const RingBuffer&) = delete;

    bool full() const { return size_ == cap_; }
    bool empty() const { return size_ == 0; }

    bool push(double v) {
        if (full()) return false;
        buf_[(head_ + size_) % cap_] = v;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (empty()) return std::nullopt;
        double v = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

private:
    std::size_t cap_;
    double* buf_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    std::cout << rb.push(1.5) << rb.push(2.5) << rb.push(3.5) << rb.push(4.5) << '\n';
