```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (size_ == N) return false;   // full: refuse, no overwrite
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full()  const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    for (int v : {1, 2, 3}) rb.push(v);
    std::cout << "full: " << rb.full() << "\n";          // 1
    std::cout << "push 4: " << rb.push(4) << "\n";        // 0 (refused)
    while (auto v = rb.pop()) std::cout << *v << " ";     // 1 2 3
    std::cout << "\nempty: " << rb.empty() << "\n";       // 1
    std::cout << "pop empty: " << rb.pop().has_value() << "\n"; // 0
    return 0;
}
```

`head_` plus `size_` avoids the classic "full vs empty" ambiguity you get from head/tail alone. When the buffer is full `push` returns `false` instead of overwriting, and `pop` on empty returns `std::nullopt`, so neither path can crash.

