```rust
#[derive(Debug, PartialEq)]
pub enum RleError {
    DigitWithoutChar,
    ZeroCount,
}

pub fn encode(input: &str) -> String {
    let chars: Vec<char> = input.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        let mut run = 1;
        while i + run < chars.len() && chars[i + run] == c {
            run += 1;
        }
        out.push(c);
        if run > 1 {
            out.push_str(&run.to_string());
        }
        i += run;
    }
    out
}

pub fn decode(input: &str) -> Result<String, RleError> {
    let chars: Vec<char> = input.chars().collect();
    let mut out = String::new();
    let mut pending: Option<char> = None;
    let mut digits = String::new();
    for &c in &chars {
        if c.is_ascii_digit() {
            if pending.is_none() {
                return Err(RleError::DigitWithoutChar);
            }
            digits.push(c);
        } else {
            if let Some(p) = pending.take() {
                push_run(&mut out, p, &digits)?;
            }
            pending = Some(c);
            digits.clear();
        }
    }
    if let Some(p) = pending.take() {
        push_run(&mut out, p, &digits)?;
    }
    Ok(out)
}

fn push_run(out: &mut String, ch: char, digits: &str) -> Result<(), RleError> {
    let n: usize = if digits.is_empty() {
        1
    } else {
        digits.parse().map_err(|_| RleError::ZeroCount)?
    };
    if n == 0 {
        return Err(RleError::ZeroCount);
    }
    for _ in 0..n {
        out.push(ch);
    }
    Ok(())
}

fn main() {
    let encoded = encode("aaabbc");
    println!("{encoded}");                     // a3b2c
    println!("{:?}", decode(&encoded));        // Ok("aaabbc")
    println!("{:?}", decode("3a"));           // Err(DigitWithoutChar)
    println!("{:?}", decode("a0"));           // Err(ZeroCount)
    println!("{:?}", decode(""));             // Ok("")
}
```

`encode` iterates run by run and only writes a count when the run exceeds one, so `"abc"` stays `"abc"`. `decode` buffers digits until the next non-digit and rejects a leading digit or a zero count as explicit `Err` variants rather than panicking. Runs over `char`, so multi-byte inputs work.

```rust
fn second_largest(values: &[i32]) -> Option<i32> {
    let mut first: Option<i32> = None;
    let mut second: Option<i32> = None;
    for &v in values {
        if first == Some(v) || second == Some(v) {
            continue; // keep distinctness
        }
        if first.is_none() || v > first.unwrap() {
            second = first;
            first = Some(v);
        } else if second.is_none() || v > second.unwrap() {
            second = Some(v);
        }
    }
    second
}

fn main() {
    println!("{:?}", second_largest(&[3, 1, 4, 1, 5, 9, 2, 6])); // Some(6)
    println!("{:?}", second_largest(&[5, 5, 5]));               // None
    println!("{:?}", second_largest(&[]));                      // None
    println!("{:?}", second_largest(&[i32::MIN, 0, i32::MAX])); // Some(0)
}
