import string

def caesar(text: str, shift: int, decrypt: bool = False) -> str:
    if decrypt:
        shift = -shift
    out = []
    for ch in text:
        if ch.isascii() and ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            out.append(chr((ord(ch) - base + shift) % 26 + base))
        else:
            out.append(ch)
    return "".join(out)

def _roundtrip(samples, shift):
    ok = True
    for s in samples:
        enc = caesar(s, shift)
        dec = caesar(enc, shift, decrypt=True)
        if dec != s:
            ok = False
            print(f"FAIL: {s!r} -> {enc!r} -> {dec!r}")
    return ok

if __name__ == "__main__":
    samples = ["", "abc", "XYZ", "Hello, World!", "naïve café", "123 中文"]
    for shift in (0, 1, 25, 13, -3):
        print(f"shift={shift:>3}  roundtrip_ok={_roundtrip(samples, shift)}")
    print(caesar("attack at dawn", 3))
    print(caesar("dwwdfn dw gdzq", 3, decrypt=True))
```

`(ord(ch) - base + shift) % 26` handles negative and oversized shifts because Python's `%` always returns a non-negative result. The `isascii()` guard is deliberate: `str.isalpha()` is true for accented and CJK characters, and rotating them by an ASCII offset would corrupt the text, so anything outside A–Z / a–z passes through untouched. The harness encrypts then decrypts each sample and reports any mismatch.

