#include <iostream>
#include <string>
#include <string_view>

template <typename Stack>
bool is_balanced(std::string_view s, Stack& st, std::size_t& bad_pos) {
    auto matches = [](char open, char close) {
        return (open == '(' && close == ')') ||
               (open == '[' && close == ']') ||
               (open == '{' && close == '}');
    };
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push_back(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty() || !matches(st.back(), c)) {
                bad_pos = i;
                return false;
            }
            st.pop_back();
        }
    }
    if (!st.empty()) {
        bad_pos = s.size();
        return false;
    }
    return true;
}

int main() {
    const std::string tests[] = {"()", "([])", "([)]", "(", ")", "{[()]}", ""};
    for (const auto& t : tests) {
        std::string st;
        std::size_t pos = 0;
        bool ok = is_balanced(t, st, pos);
        std::cout << t << " -> " << (ok ? "OK" : "unbalanced") << "\n";
        if (!ok) std::cout << "  first bad: " << pos << "\n";
    }
    return 0;
}
