```cpp
#include <algorithm>
#include <cstddef>
#include <iostream>
#include <string>
#include <vector>

static std::size_t utf8_len(unsigned char lead) {
    if ((lead & 0x80u) == 0) return 1;
    if ((lead & 0xE0u) == 0xC0u) return 2;
    if ((lead & 0xF0u) == 0xE0u) return 3;
    if ((lead & 0xF8u) == 0xF0u) return 4;
    return 1;
}

std::string reverse_utf8(const std::string& s) {
    std::vector<std::string> chunks;
    for (std::size_t i = 0; i < s.size();) {
        std::size_t n = utf8_len(static_cast<unsigned char>(s[i]));
        if (i + n > s.size()) n = s.size() - i;
        chunks.push_back(s.substr(i, n));
        i += n;
    }
    std::reverse(chunks.begin(), chunks.end());
    std::string out;
    out.reserve(s.size());
    for (const auto& c : chunks) out += c;
    return out;
}

int main() {
    std::string sample = "a\xC3\xA9\xE2\x82\xACz"; // a, e-acute, euro sign, z
    std::string rev = reverse_utf8(sample);
    std::cout << rev << "\n";
    return 0;
}
```
