size_t safe_copy(char *dst, size_t cap, const char *src) {
    size_t i = 0;
    if (dst == NULL || cap == 0) return 0;
    if (src != NULL) {
        while (i + 1 < cap && src[i] != '\0') {
            dst[i] = src[i];
            ++i;
        }
    }
    dst[i] = '\0';
    return i;
}

int main(void) {
    char buf[8];
    size_t n = safe_copy(buf, sizeof buf, "abcdefghij");
    printf("%zu [%s]\n", n, buf);   /* 7 [abcdefg] */

    safe_copy(buf, sizeof buf, NULL);
    printf("null src -> [%s]\n", buf); /* [] */

    safe_copy(buf, 0, "x");  /* no write, avoids overflow */
    return 0;
}
```
The loop condition `i + 1 < cap` reserves one byte for the terminator, so a full buffer can never lose its NUL. `cap == 0` returns without touching memory, and a NULL source just yields an empty string.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    print(cache.get("a"))   # 1, refreshes 'a'
    cache.put("c", 3)       # evicts 'b'
    print(cache.get("b"))   # None
    print(cache.get("c"))   # 3
```
`OrderedDict` keeps insertion order; `move_to_end` marks a key as recently used on both `get` and an existing-key `put`, and `popitem(last=False)` evicts the least recently used entry.

