fn rotate_left<T>(data: &mut [T], k: usize) {
    let n = data.len();
    if n == 0 {
        return;
    }
    let k = k % n;
    if k == 0 {
        return;
    }
    data[..k].reverse();
    data[k..].reverse();
    data.reverse();
}

fn main() {
    let mut v = vec![1, 2, 3, 4, 5];
    rotate_left(&mut v, 2);
    assert_eq!(v, vec![3, 4, 5, 1, 2]);

    let mut v = vec![1, 2, 3];
    rotate_left(&mut v, 3);
    assert_eq!(v, vec![1, 2, 3]);

    let mut v: Vec<i32> = vec![];
    rotate_left(&mut v, 7);
    assert!(v.is_empty());

