```c
#include <stdio.h>
#include <string.h>

#define MAX 256

static int is_open(char c) { return c == '(' || c == '[' || c == '{'; }

static char closer_for(char c) {
    switch (c) {
        case '(': return ')';
        case '[': return ']';
        case '{': return '}';
        default:  return '\0';
    }
}

int balanced(const char* s) {
    char stack[MAX];
    int top = 0;

    for (; *s; ++s) {
        if (is_open(*s)) {
            if (top == MAX) return 0;
            stack[top++] = closer_for(*s);
        } else if (*s == ')' || *s == ']' || *s == '}') {
            if (top == 0 || stack[--top] != *s) return 0;
        }
    }
    return top == 0;
}

int main(void) {
    const char* tests[] = {"()", "([{}])", "(]", "((", "){", "", "no brackets"};
    for (int i = 0; i < 7; ++i)
        printf("%-14s -> %s\n", tests[i], balanced(tests[i]) ? "true" : "false");
    return 0;
}
```
Output:
```
()             -> true
([{}])         -> true
(]             -> false
((             -> false
){             -> false
               -> true
no brackets    -> true
```
The stack stores the *expected closing* character, so each `)`/`]`/`}` comparison is a single equality check. `top == MAX` guards against overflow on inputs longer than 255 open brackets.

