```cpp
#include <array>
#include <optional>
#include <cstddef>
#include <iostream>

template <std::size_t N>
class RingBuffer {
    std::array<int, N> buf{};
    std::size_t head = 0; // next read
    std::size_t tail = 0; // next write
    std::size_t count = 0;

public:
    bool push(int v) {
        if (count == N) return false;
        buf[tail] = v;
        tail = (tail + 1) % N;
        ++count;
        return true;
    }

    std::optional<int> pop() {
        if (count == 0) return std::nullopt;
        int v = buf[head];
        head = (head + 1) % N;
        --count;
        return v;
    }

    std::size_t size() const { return count; }
    bool empty() const { return count == 0; }
    bool full() const { return count == N; }
};

int main() {
    RingBuffer<3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << "\n"; // 1110
    std::cout << *rb.pop() << *rb.pop() << "\n"; // 12
    std::cout << rb.push(9) << rb.push(8) << rb.push(7) << "\n"; // 110
    while (!rb.empty()) std::cout << *rb.pop();
    std::cout << "\n"; // 3 9 8 7 -> 3987
}
```
The class keeps a head index, a tail index, and a live count so full and empty are unambiguous even when head == tail. `push` returns false instead of overwriting when the buffer is full.

