fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

fn main() {
    let data = [1, 3, 3, 5, 8, 13, 21];
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &21), Some(6));
    assert_eq!(binary_search(&data, &4), None);
    assert_eq!(binary_search(&data, &3), Some(2));
    assert_eq!(binary_search::<i32>(&[], &1), None);
    println!("ok");
}
```
The half-open range `[lo, hi)` and the midpoint `lo + (hi - lo) / 2` avoid overflow on large slices. Any of the duplicate matches is acceptable; this returns one of them deterministically.

```cpp
#include <condition_variable>
#include <mutex>
#include <queue>
#include <optional>
#include <cstddef>
#include <iostream>
#include <thread>

template <typename T>
class BoundedQueue {
    std::queue<T> q;
    std::size_t cap;
    mutable std::mutex m;
    std::condition_variable not_empty;
    std::condition_variable not_full;
    bool closed = false;

public:
    explicit BoundedQueue(std::size_t capacity) : cap(capacity) {}

    // Returns false if the queue is closed.
    bool push(T v) {
        std::unique_lock<std::mutex> lock(m);
        not_full.wait(lock, [&] { return q.size() < cap || closed; });
        if (closed) return false;
        q.push(std::move(v));
        not_empty.notify_one();
        return true;
    }

    // Blocks until an item is available; nullopt means closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(m);
        not_empty.wait(lock, [&] { return !q.empty() || closed; });
        if (q.empty()) return std::nullopt;
        T v = std::move(q.front());
        q.pop();
        not_full.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lock(m);
        closed = true;
        not_empty.notify_all();
        not_full.notify_all();
    }
};

int main() {
    BoundedQueue<int> bq(2);
    std::thread producer([&] {
        for (int i = 0; i < 5; ++i) bq.push(i);
        bq.close();
    });
    int sum = 0;
    while (auto v = bq.pop()) sum += *v;
    producer.join();
    std::cout << sum << "\n"; // 0+1+2+3+4 = 10
}
```
Wait predicates guard against spurious wakeups, and the `closed` flag lets a consumer exit cleanly instead of blocking forever once the producer is done. `close` wakes both sides so neither waits on a queue that will never change again.

