```cpp
#include <iostream>
#include <vector>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main() {
    std::vector<int> values = {1, 2, 3, 4, 5};
    Node* head = nullptr;
    for (auto it = values.rbegin(); it != values.rend(); ++it) {
        head = new Node(*it);
        Node* tmp = head->next;
        (void)tmp;
    }
    // Build properly: prepend each value.
    while (head) { Node* n = head->next; delete head; head = n; }

    head = nullptr;
    for (auto it = values.rbegin(); it != values.rend(); ++it) {
        Node* n = new Node(*it);
        n->next = head;
        head = n;
    }

    head = reverse(head);
    for (Node* cur = head; cur; cur = cur->next) std::cout << cur->value << ' ';
    std::cout << '\n';

    while (head) { Node* n = head->next; delete head; head = n; }

    std::cout << (reverse(nullptr) == nullptr ? "empty ok\n" : "bad\n");
    return 0;
}
```

Three pointers walk the list: `next` saves the rest, `head->next` flips backward to `prev`, then both advance. Passing `nullptr` returns `nullptr` without dereferencing, so the empty case is safe. All heap nodes are freed.

```c
#include <stdio.h>
#include <limits.h>
#include <stdbool.h>

bool is_palindrome(int x) {
    if (x < 0) return false;
    if (x != 0 && x % 10 == 0) return false;
    long long reversed = 0;
    while (x > reversed) {
        reversed = reversed * 10 + x % 10;
        x /= 10;
    }
    return x == reversed || x == reversed / 10;
}

int main(void) {
    int cases[] = {0, 7, 121, 1221, 12321, -121, 10, 1000021, INT_MAX};
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i)
        printf("%d -> %s\n", cases[i], is_palindrome(cases[i]) ? "yes" : "no");
    return 0;
}
```

Only half the digits are reversed, so overflow is avoided; `long long` guards the multiply on 32-bit ints. Trailing-zero numbers like 10 are rejected early because no palindrome except 0 ends in 0. Even-length inputs match `x == reversed`, odd-length match after dropping the middle digit.

