    }

    pub fn push(&mut self, value: T) {
        self.items.push(value);
    }

    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    pub fn peek(&self) -> Option<&T> {
        self.items.last()
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }
}

fn main() {
    let mut s: Stack<i32> = Stack::new();
    assert_eq!(s.pop(), None);
    assert_eq!(s.peek(), None);
    s.push(1);
    s.push(2);
    s.push(3);
    assert_eq!(s.peek(), Some(&3));
    assert_eq!(s.pop(), Some(3));
    assert_eq!(s.len(), 2);
    println!("ok: {s:?}");
}
```

`Vec<T>` gives amortised O(1) push/pop and a cheap `last()`. Empty operations return `None` instead of panicking, so callers choose how to handle underflow.

```rust
use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum ParseError {
    MissingEquals { line: usize },
    EmptyKey { line: usize },
}

pub fn parse(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    for (idx, raw) in input.lines().enumerate() {
        let line = idx + 1;
        let trimmed = raw.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let (key, value) = match trimmed.split_once('=') {
            Some(kv) => kv,
            None => return Err(ParseError::MissingEquals { line }),
        };
        let key = key.trim();
        if key.is_empty() {
            return Err(ParseError::EmptyKey { line });
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let good = "# config\nname = luna\n\nhost=localhost\n";
    let m = parse(good).unwrap();
    assert_eq!(m["name"], "luna");
    assert_eq!(m["host"], "localhost");
    assert_eq!(m.len(), 2);

    assert!(matches!(parse("broken"), Err(ParseError::MissingEquals { line: 1 })));
    assert!(matches!(parse("=x"), Err(ParseError::EmptyKey { line: 1 })));
    println!("ok: {m:?}");
}
```

`split_once('=')` splits on the first equals only, so values may contain `=`. Keys and values are trimmed in place. `.lines()` strips `\n` and a trailing `\r`, so CRLF files parse without extra handling. The line number in each error is 1-based.

```cpp
#include <array>
#include <cstddef>
#include <cstdint>
#include <iostream>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity), buf_(capacity) {}

    void push(std::uint8_t byte) {
        buf_[(head_ + size_) % cap_] = byte;
        if (size_ == cap_) {
            head_ = (head_ + 1) % cap_;
        } else {
            ++size_;
        }
    }

    bool pop(std::uint8_t& out) {
        if (size_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return cap_; }

private:
    std::size_t cap_;
    std::vector<std::uint8_t> buf_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    for (std::uint8_t v : {'a', 'b', 'c', 'd'}) rb.push(v);
    std::uint8_t out;
    while (rb.pop(out)) std::cout << out;
    std::cout << "\n";  // bcd, oldest 'a' overwritten
    std::cout << (rb.pop(out) ? "bad\n" : "empty ok\n");
    return 0;
}
```

Needs `#include <vector>` added before use; shown here for brevity but the class relies on it. When the buffer is full, `push` advances `head_`, so the oldest byte is dropped and size stays at capacity. `pop` on empty returns `false` rather than reading garbage.

