#include <iostream>
#include <string>

std::string longestPalindrome(const std::string& s) {
    if (s.empty()) return "";
    int bestStart = 0, bestLen = 1;
    for (int center = 0; center < (int)s.size(); ++center) {
        for (int parity = 0; parity < 2; ++parity) {
            int lo = center;
            int hi = center + parity;
            while (lo >= 0 && hi < (int)s.size() && s[lo] == s[hi]) {
                --lo;
                ++hi;
            }
            int len = hi - lo - 1;
            if (len > bestLen) {
                bestLen = len;
                bestStart = lo + 1;
            }
        }
    }
    return s.substr(bestStart, bestLen);
}

int main() {
    std::string line;
    if (!std::getline(std::cin, line)) {
        return 0;
    }
    std::cout << longestPalindrome(line) << '\n';
    return 0;
}
