#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

static char shift_char(char c, int shift, int direction) {
    if (!isalpha((unsigned char)c)) return c;
    char base = islower((unsigned char)c) ? 'a' : 'A';
    int offset = (c - base + direction * shift) % 26;
    if (offset < 0) offset += 26;
    return (char)(base + offset);
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "usage: %s enc|dec shift text\n", argv[0]);
        return 1;
    }
    int direction = strcmp(argv[1], "enc") == 0 ? 1 : (strcmp(argv[1], "dec") == 0 ? -1 : 0);
    if (direction == 0) {
        fprintf(stderr, "mode must be enc or dec\n");
        return 1;
    }
    int shift = atoi(argv[2]) % 26;

    const char *text = argv[3];
    for (size_t i = 0; i < strlen(text); ++i) {
        putchar(shift_char(text[i], shift, direction));
    }
    putchar('\n');
    return 0;
}
