use std::collections::HashMap;
use std::env;

fn fib(n: u32, cache: &mut HashMap<u32, u128>) -> u128 {
    if let Some(&v) = cache.get(&n) {
        return v;
    }
    let value = match n {
        0 => 0,
        1 => 1,
        _ => fib(n - 1, cache).saturating_add(fib(n - 2, cache)),
    };
    cache.insert(n, value);
    value
}

fn main() {
    let n: u32 = match env::args().nth(1).and_then(|s| s.parse().ok()) {
        Some(v) => v,
        None => {
            eprintln!("usage: fib <n>");
            std::process::exit(1);
        }
    };
    let mut cache = HashMap::new();
    println!("fib({}) = {}", n, fib(n, &mut cache));
}
