#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static long parse_signed(const char **p) {
    int sign = 1;
    while (isspace((unsigned char)**p)) (*p)++;
    while (**p == '+' || **p == '-') {
        if (**p == '-') sign = -sign;
        (*p)++;
    }
    long value = 0;
    while (isdigit((unsigned char)**p)) {
        value = value * 10 + (**p - '0');
        (*p)++;
    }
    return sign * value;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s EXPR\n", argv[0]);
        return 1;
    }
    const char *p = argv[1];
    long total = parse_signed(&p);
    while (*p) {
        while (isspace((unsigned char)*p)) p++;
        if (*p == '\0') break;
        if (*p != '+' && *p != '-') {
            fprintf(stderr, "unexpected character: %c\n", *p);
            return 1;
        }
        int sign = (*p == '+') ? 1 : -1;
        p++;
        total += sign * parse_signed(&p);
    }
    printf("%ld\n", total);
    return 0;
}
