```python
def encode(text):
    if not text:
        return ""
    out = []
    prev = text[0]
    run = 1
    for ch in text[1:]:
        if ch == prev:
            run += 1
        else:
            out.append(f"{run}{prev}")
            prev = ch
            run = 1
    out.append(f"{run}{prev}")
    return "".join(out)


def decode(encoded):
    out = []
    count = 0
    seen_digit = False
    for ch in encoded:
        if ch.isdigit():
            count = count * 10 + int(ch)
            seen_digit = True
        else:
            if not seen_digit:
                raise ValueError(f"missing count before {ch!r}")
            out.append(ch * count)
            count = 0
            seen_digit = False
    if seen_digit:
        raise ValueError("dangling count at end of input")
    return "".join(out)


if __name__ == "__main__":
    for sample in ["", "a", "aaabbbcccd", "wwwwwwwwwwww", "abc"]:
        assert decode(encode(sample)) == sample
    print(encode("aaabbbcccd"))
```

The count loop uses `count * 10 + int(ch)` so runs of ten or more decode correctly. `decode` rejects malformed input like `"abc"` or `"3"` instead of silently dropping characters.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1          # a is now most recent
    c.put("c", 3)                   # evicts b
    assert c.get("b") is None
    assert c.get("a") == 1
    assert len(c) == 2
    print("ok")
```

`move_to_end` marks a key as most recently used on both read and overwrite; `popitem(last=False)` evicts the least recently used entry when the cap is exceeded.

