fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    let mut push = |out: &mut Vec<i32>, v: i32| {
        if out.last() != Some(&v) {
            out.push(v);
        }
    };

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] { push(&mut out, a[i]); i += 1; }
        else { push(&mut out, b[j]); j += 1; }
    }
    while i < a.len() { push(&mut out, a[i]); i += 1; }
    while j < b.len() { push(&mut out, b[j]); j += 1; }
    out
}

fn main() {
    assert_eq!(merge_sorted(&[1, 1, 3, 5], &[1, 2, 3, 8]), vec![1, 2, 3, 5, 8]);
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 1, 1], &[1]), vec![1]);
