```c
#include <stdio.h>
#include <stdlib.h>

/* memo[i] holds fib(i); 0 means "not computed yet",
   but fib(0)=0 is valid, so we probe with a sentinel. */
static unsigned long long *memo;
static char *done;

unsigned long long fib(int n) {
    if (n < 0) return 0;
    if (n == 0 || n == 1) return (unsigned long long)n;
    if (done[n]) return memo[n];
    memo[n] = fib(n - 1) + fib(n - 2);
    done[n] = 1;
    return memo[n];
}

int main(int argc, char **argv) {
    int n = (argc > 1) ? atoi(argv[1]) : 10;
    if (n < 0) { printf("n must be >= 0\n"); return 1; }

    memo = calloc((size_t)n + 1, sizeof(*memo));
    done = calloc((size_t)n + 1, sizeof(*done));
    if (!memo || !done) { printf("out of memory\n"); return 1; }

    printf("fib(%d) = %llu\n", n, fib(n));

    free(memo);
    free(done);
    return 0;
}
```

Run `./fib 40` → `fib(40) = 102334155`. The recursion is memoized so it is O(n). `unsigned long long` overflows past fib(93); for larger n switch to a big-integer library or track digits manually.

