```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double v) {
        if (full()) return false;
        data_[tail_] = v;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (empty()) return std::nullopt;
        double v = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }

    bool empty() const { return size_ == 0; }
    bool full()  const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0, tail_ = 0, size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    std::cout << rb.push(1.5) << "\n";   // 1
    std::cout << rb.push(2.5) << "\n";   // 1
    std::cout << rb.push(3.5) << "\n";   // 1
    std::cout << rb.push(4.5) << "\n";   // 0 (full)
    std::cout << (rb.full() ? "full" : "not full") << "\n";
    while (auto v = rb.pop()) std::cout << *v << "\n";  // 1.5 2.5 3.5
    std::cout << (rb.empty() ? "empty" : "not empty") << "\n";
}
```

`head_`/`tail_` wrap with `% N`, and `size_` (not pointer equality) is what distinguishes empty from full — otherwise a wrapped buffer looks empty when it is full. When full, `push` returns `false` rather than overwriting.

