```cpp
#include <cstdlib>
#include <iostream>
#include <string>

static long long gcd(long long a, long long b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static bool parse(long long &out, const char *text) {
    try {
        size_t used = 0;
        std::string s(text);
        long long v = std::stoll(s, &used);
        if (used != s.size()) return false;
        out = v;
        return true;
    } catch (const std::exception &) {
        return false;
    }
}

int main(int argc, char **argv) {
    if (argc != 3) {
        std::cerr << "usage: " << argv[0] << " A B\n";
        return 2;
    }
    long long a, b;
    if (!parse(a, argv[1]) || !parse(b, argv[2])) {
        std::cerr << "both arguments must be integers\n";
        return 2;
    }
    std::cout << gcd(a, b) << '\n';
    return 0;
}
```

The loop performs `a % b` and shifts values each iteration, so the remainder strictly decreases and the algorithm terminates. Negative inputs are normalised with absolute value, and `stoll` reports how many characters it consumed; trailing garbage such as `42x` is rejected instead of silently parsed as 42.

