#include <iostream>
#include <vector>

// Returns the index of the first element equal to target, or -1.
int lower_bound_index(const std::vector<int>& data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size());  // half-open [lo, hi)

    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;  // avoids overflow on large lo+hi
        if (data[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    if (lo < static_cast<int>(data.size()) && data[lo] == target) {
        return lo;
    }
    return -1;
}

int main() {
    std::vector<int> data = {1, 2, 4, 4, 4, 5, 9};
    for (int target : {4, 1, 9, 3, 0, 10}) {
        std::cout << target << " -> " << lower_bound_index(data, target) << '\n';
    }
    return 0;
}
```

The loop converges on the leftmost position where `data[pos] >= target`, then checks for a real match. Duplicates therefore return the first index instead of an arbitrary one, and `lo + (hi - lo) / 2` keeps the midpoint safe for large inputs.

```rust
fn stats(values: &[f64]) -> Option<(f64, f64)> {
    if values.is_empty() {
        return None;
    }

    let n = values.len() as f64;
    let mean = values.iter().sum::<f64>() / n;

    // Sample variance uses n - 1; with a single sample it is undefined.
    if values.len() < 2 {
        return Some((mean, 0.0));
    }

    let variance = values
        .iter()
        .map(|v| {
            let d = v - mean;
            d * d
        })
        .sum::<f64>()
        / (n - 1.0);

    Some((mean, variance.sqrt()))
}

fn main() {
    let samples = [2.0, 4.0, 4.0, 4.0, 5.0, 5.0, 7.0, 9.0];
    match stats(&samples) {
        Some((mean, sd)) => println!("mean = {mean:.4}, sd = {sd:.4}"),
        None => println!("no data"),
    }

    assert_eq!(stats(&[]), None);
    assert!(stats(&[3.0]).is_some());
}
```

