```rust
#[derive(Debug)]
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,  // next write position
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn with_capacity(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be non-zero");
        let mut data = Vec::with_capacity(cap);
        for _ in 0..cap {
            data.push(None);
        }
        RingBuffer { data, head: 0, len: 0 }
    }

    pub fn capacity(&self) -> usize {
        self.data.len()
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn push(&mut self, value: T) -> Option<T> {
        let cap = self.capacity();
        let evicted = self.data[self.head].take();
        self.data[self.head] = Some(value);
        self.head = (self.head + 1) % cap;
        if self.len < cap {
            self.len += 1;
        }
        evicted
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        let cap = self.capacity();
        let index = (self.head + cap - self.len) % cap;
        let value = self.data[index].take();
        self.len -= 1;
        value
    }
}

fn main() {
    let mut rb = RingBuffer::with_capacity(3);
    assert!(rb.push(1).is_none());
    assert!(rb.push(2).is_none());
    assert!(rb.push(3).is_none());
    assert_eq!(rb.push(4), Some(1));  // 1 is overwritten
    assert_eq!(rb.pop(), Some(2));
    assert_eq!(rb.pop(), Some(3));
    assert_eq!(rb.pop(), Some(4));
    assert_eq!(rb.pop(), None);
    println!("ring buffer ok");
}
```

Writes land at `head` and advance modulo the capacity; once full, `push` returns the evicted value instead of silently dropping it. `pop` reads from the oldest slot, derived from `head - len`, so behaviour stays correct when the buffer wraps.

```python
def to_roman(num: int) -> str:
    """Convert 1..3999 to a Roman numeral.

    Uses subtractive pairs so values like 4, 9, 40, 90 come out correct.
    """
    if not isinstance(num, int) or isinstance(num, bool):
        raise TypeError("num must be an int")
    if not 1 <= num <= 3999:
        raise ValueError("num must be in the range 1..3999")

    table = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ]

    parts = []
    for value, symbol in table:
        if num == 0:
            break
        count, num = divmod(num, value)
        parts.append(symbol * count)
    return "".join(parts)


if __name__ == "__main__":
    for n, expected in [(1, "I"), (4, "IV"), (9, "IX"),
                        (14, "XIV"), (40, "XL"), (1987, "MCMLXXXVII"),
                        (3999, "MMMCMXCIX")]:
        got = to_roman(n)
