void reverse(char *s) {
    if (s == NULL) return;
    size_t i = 0;
    size_t j = strlen(s);
    while (i < j && j > 0) {
        --j;
        if (i >= j) break;
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
    }
}

int main(void) {
    char buf[] = "Hello, world!";
    reverse(buf);
    printf("%s\n", buf);

    char even[] = "abcd";
    reverse(even);
    printf("%s\n", even);

    char empty[] = "";
    reverse(empty);
    printf("[%s]\n", empty);

    return 0;
}
