```c
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    const char *input = "10,20,,30,40";
    long long total = 0;
    const char *p = input;

    while (*p) {
        const char *comma = strchr(p, ',');
        size_t len = comma ? (size_t)(comma - p) : strlen(p);
        if (len > 0) {
            char buf[32];
            if (len >= sizeof(buf)) {
                fprintf(stderr, "field too long\n");
                return 1;
            }
            memcpy(buf, p, len);
            buf[len] = '\0';
            errno = 0;
            char *end = NULL;
            long value = strtol(buf, &end, 10);
            if (errno != 0 || *end != '\0') {
                fprintf(stderr, "invalid field: %s\n", buf);
                return 1;
            }
            if (total > LLONG_MAX - value) {
                fprintf(stderr, "overflow\n");
                return 1;
            }
            total += value;
        }
        if (!comma) break;
        p = comma + 1;
    }

    printf("total=%lld\n", total);
    return 0;
}
```
Empty fields between commas are skipped by the `len > 0` guard. `strtol` with `errno` catches non-numeric text, and the pre-add check prevents signed overflow before it happens.

