std::optional<int> parse_int(const std::string& s) {
    if (s.empty()) return std::nullopt;
    std::size_t i = 0;
    bool negative = false;
    if (s[0] == '+' || s[0] == '-') {
        negative = (s[0] == '-');
        i = 1;
        if (i == s.size()) return std::nullopt;
    }
    long long value = 0;
    for (; i < s.size(); ++i) {
        char c = s[i];
        if (c < '0' || c > '9') return std::nullopt;
        value = value * 10 + (c - '0');
        if (value > (long long)INT_MAX + (negative ? 1 : 0)) return std::nullopt;
    }
    if (negative) value = -value;
    if (value < INT_MIN || value > INT_MAX) return std::nullopt;
    return static_cast<int>(value);
}

int main() {
    for (const std::string& s : {"42", "-7", "2147483648", "12x", ""}) {
        auto r = parse_int(s);
        if (r) std::cout << s << " -> " << *r << '\n';
        else std::cout << s << " -> invalid\n";
    }
}
