pub struct Node<T> {
    pub value: T,
    pub next: Option<Box<Node<T>>>,
}

pub fn reverse<T>(head: Option<Box<Node<T>>>) -> Option<Box<Node<T>>> {
    let mut prev: Option<Box<Node<T>>> = None;
    let mut cur = head;
    while let Some(mut node) = cur {
        cur = node.next.take();
        node.next = prev;
        prev = Some(node);
    }
    prev
}

