/// Returns (F(n), F(n+1)) using fast doubling.
fn fib_pair(n: u128) -> Option<(u128, u128)> {
    if n == 0 {
        return Some((0, 1));
    }
    let (a, b) = fib_pair(n >> 1)?;
    let c = a.checked_mul(b.checked_mul(2)? .checked_sub(a)?)?;
    let d = a.checked_mul(a)?.checked_add(b.checked_mul(b)?)?;
    if n & 1 == 0 {
        Some((c, d))
    } else {
        Some((d, d.checked_add(c)?))
    }
}

pub fn fib(n: u128) -> Option<u128> {
    fib_pair(n).map(|(f, _)| f)
}

