#include <iostream>
#include <stdexcept>

class IntVec {
    int* data_ = nullptr;
    size_t size_ = 0;
    size_t cap_ = 0;

    void grow() {
        size_t new_cap = cap_ ? cap_ * 2 : 4;
        int* next = new int[new_cap];
        for (size_t i = 0; i < size_; ++i) next[i] = data_[i];
        delete[] data_;
        data_ = next;
        cap_ = new_cap;
    }

public:
    ~IntVec() { delete[] data_; }

    void push_back(int v) {
        if (size_ == cap_) grow();
        data_[size_++] = v;
    }

    int& at(size_t i) {
        if (i >= size_) throw std::out_of_range("index");
        return data_[i];
    }

    size_t size() const { return size_; }
};

int main() {
    IntVec v;
    for (int i = 0; i < 10; ++i) v.push_back(i * i);
    std::cout << v.at(9) << "\n";
    try { v.at(10); } catch (const std::out_of_range& e) { std::cout << "caught\n"; }
    return 0;
}
