```rust
struct Ring {
    buf: Vec<i32>,
    head: usize,
    len: usize,
}

impl Ring {
    fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        Ring { buf: vec![0; cap], head: 0, len: 0 }
    }

    fn push(&mut self, v: i32) {
        let cap = self.buf.len();
        let idx = (self.head + self.len) % cap;
        self.buf[idx] = v;
        if self.len < cap {
            self.len += 1;
        } else {
            self.head = (self.head + 1) % cap;
        }
    }

    fn to_vec(&self) -> Vec<i32> {
        (0..self.len)
            .map(|i| self.buf[(self.head + i) % self.buf.len()])
            .collect()
    }
}

fn main() {
    let mut r = Ring::new(3);
    for v in [1, 2, 3, 4, 5] { r.push(v); }
    assert_eq!(r.to_vec(), vec![3, 4, 5]);
    println!("ok");
}
```

Once full, `head` advances so the window slides forward. `to_vec` reads in logical order without cloning the backing buffer.

