#include <stdio.h>
#include <string.h>

#define MAXN 90
static long long memo[MAXN + 1];

long long fib_memo(int n) {
    if (n <= 1) return n;
    if (memo[n] != -1) return memo[n];
    return memo[n] = fib_memo(n - 1) + fib_memo(n - 2);
}

long long fib_iter(int n) {
    long long a = 0, b = 1;
    for (int i = 0; i < n; ++i) {
        long long t = a + b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    memset(memo, -1, sizeof(memo));
    for (int n = 0; n <= 30; ++n) {
        if (fib_memo(n) != fib_iter(n)) {
            printf("mismatch at %d\n", n);
            return 1;
        }
    }
    printf("fib(90) = %lld\n", fib_iter(90));
    return 0;
}
```

`memo` is initialized to -1 because 0 is a valid Fibonacci result. Note `fib(90)` fits in a signed 64-bit integer; anything above 92 overflows, which is why `MAXN` is capped there.

