    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the cat the dog the bird cat ";
    let result = top_words(text, 3);
    for (w, c) in &result {
        println!("{} {}", w, c);
    }
    assert_eq!(result[0], ("the".to_string(), 3));
}
