```python
import threading


class OverflowError_(Exception):
    pass


class BoundedCounter:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._value = 0
        self._lock = threading.Lock()

    def increment(self, by: int = 1) -> int:
        if by <= 0:
            raise ValueError("increment must be positive")
        with self._lock:
            if self._value + by > self._capacity:
                raise OverflowError_(
                    f"counter would exceed capacity {self._capacity}"
                )
            self._value += by
            return self._value

    @property
    def value(self) -> int:
        with self._lock:
            return self._value


if __name__ == "__main__":
    c = BoundedCounter(10)
    assert c.increment(4) == 4
    assert c.increment(6) == 10
    try:
        c.increment(1)
        raise AssertionError("expected overflow")
    except OverflowError_:
        pass
    assert c.value == 10
    print("ok")
```

The check and the update happen inside the same lock, so two threads cannot both pass the capacity test and then overshoot. `value` also takes the lock so reads never see a torn update.

