#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

int main(void) {
    Node *head = NULL;
    Node *tail = NULL;
    int value;
    while (scanf("%d", &value) == 1) {
        Node *node = malloc(sizeof(Node));
        if (node == NULL) {
            fprintf(stderr, "out of memory\n");
            return 1;
        }
        node->value = value;
        node->next = NULL;
        if (tail == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    head = reverse(head);
    for (Node *cur = head; cur != NULL; cur = cur->next) {
        printf("%d", cur->value);
        if (cur->next != NULL) {
            putchar(' ');
        }
    }
    putchar('\n');

    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
