#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), cap_(capacity), head_(0), size_(0) {}

    bool push(int value) {
        if (size_ == cap_) return false;
        data_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<int> data_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t size_;
};

