#include <iostream>
#include <vector>
#include <algorithm>

std::vector<int> merge_unique(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());

    std::size_t i = 0, j = 0;
    while (i < a.size() || j < b.size()) {
        int next;
        if (j >= b.size() || (i < a.size() && a[i] <= b[j])) {
            next = a[i++];
        } else {
            next = b[j++];
        }
        // Only push when it differs from the last element written.
        if (out.empty() || out.back() != next) {
            out.push_back(next);
        }
    }
    return out;
}

int main() {
    const std::vector<int> a{1, 3, 3, 5, 9};
    const std::vector<int> b{2, 3, 4, 5, 5, 10};

    const std::vector<int> merged = merge_unique(a, b);

    for (std::size_t k = 0; k < merged.size(); ++k) {
        if (k) std::cout << ' ';
        std::cout << merged[k];
    }
    std::cout << '\n';

    const std::vector<int> expected{1, 2, 3, 4, 5, 9, 10};
    return merged == expected ? 0 : 1;
}
