```cpp
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

class Matrix {
public:
    Matrix(std::size_t rows, std::size_t cols)
        : rows_(rows), cols_(cols), data_(rows * cols, 0.0f) {
        if (rows == 0 || cols == 0) {
            throw std::invalid_argument("Matrix dimensions must be positive");
        }
    }

    float& operator()(std::size_t r, std::size_t c) { return data_[r * cols_ + c]; }
    float operator()(std::size_t r, std::size_t c) const { return data_[r * cols_ + c]; }

    std::size_t rows() const { return rows_; }
    std::size_t cols() const { return cols_; }

    Matrix operator+(const Matrix& other) const {
        if (rows_ != other.rows_ || cols_ != other.cols_) {
            throw std::invalid_argument("Dimension mismatch in operator+");
        }
        Matrix out(rows_, cols_);
        for (std::size_t i = 0; i < data_.size(); ++i) {
            out.data_[i] = data_[i] + other.data_[i];
        }
        return out;
    }

    Matrix operator*(const Matrix& other) const {
        if (cols_ != other.rows_) {
            throw std::invalid_argument("Dimension mismatch in operator*");
        }
        Matrix out(rows_, other.cols_);
        for (std::size_t r = 0; r < rows_; ++r) {
            for (std::size_t k = 0; k < cols_; ++k) {
                const float av = (*this)(r, k);
                if (av == 0.0f) continue;  // skip zero terms
                for (std::size_t c = 0; c < other.cols_; ++c) {
                    out(r, c) += av * other(k, c);
                }
            }
        }
        return out;
    }

private:
    std::size_t rows_;
    std::size_t cols_;
    std::vector<float> data_;
};

int main() {
    Matrix a(2, 3);
    Matrix b(3, 2);
    for (std::size_t r = 0; r < 2; ++r)
        for (std::size_t c = 0; c < 3; ++c)
            a(r, c) = static_cast<float>(r + c);
    for (std::size_t r = 0; r < 3; ++r)
        for (std::size_t c = 0; c < 2; ++c)
            b(r, c) = static_cast<float>(r - c + 1);

    Matrix sum = a + a;
    Matrix prod = a * b;

    assert(sum.rows() == 2 && sum.cols() == 3);
    assert(prod.rows() == 2 && prod.cols() == 2);
    assert(prod(0, 0) == 10.0f);
    assert(prod(0, 1) == 7.0f);

    Matrix mismatched(2, 2);
    bool threw = false;
    try {
        (void)(a + mismatched);
    } catch (const std::invalid_argument&) {
        threw = true;
    }
    assert(threw);

    std::cout << "all matrix tests passed\n";
}
```

The class stores data contiguously so `operator+` is a single flat loop. `operator*` skips zero terms as a small optimization but stays O(rows*cols*other.cols). Dimension mismatches throw rather than silently corrupting memory.

```rust
/// Return the nth Fibonacci number (F0 = 0, F1 = 1), or None on overflow.
fn fibonacci(n: u64) -> Option<u128> {
    let mut a: u128 = 0;
    let mut b: u128 = 1;

    for _ in 0..n {
        let next = a.checked_add(b)?;
        a = b;
        b = next;
    }
    Some(a)
}

fn main() {
    let checks = [(0u64, Some(0u128)), (1, Some(1)), (2, Some(1)),
                  (10, Some(55)), (50, Some(12586269025))];

    for (n, expected) in checks {
        let got = fibonacci(n);
        assert_eq!(got, expected, "fib({n}) = {got:?}, expected {expected:?}");
        println!("fib({n}) = {got:?}");
    }

    // u128 overflows well before F(200) would, so this must be None.
    let overflow = fibonacci(200);
    assert!(overflow.is_none(), "expected overflow at n=200");
    println!("fib(200) overflowed as expected");
}
```

The loop is O(n) time and O(1) space. `checked_add` returns `None` the moment a sum would overflow `u128`, and the `?` propagates that immediately, so no wrapped value can leak out. F(186) is the last value that fits in `u128`.

