#!/usr/bin/env bash
# watch_errors.sh <logfile> <threshold> <window_seconds>
set -euo pipefail

logfile=${1:?usage: $0 <logfile> <threshold> <window_seconds>}
threshold=${2:?missing threshold}
window=${3:?missing window in seconds}
[[ -r $logfile ]] || { echo "cannot read $logfile" >&2; exit 1; }

# tail -F follows rotation; awk holds timestamps of the last N matches.
tail -n0 -F "$logfile" | awk -v thresh="$threshold" -v win="$window" '
/ERROR/ {
    now = systime()
    hits[++n] = now
    # Drop entries older than the window.
    while (n > 0 && now - hits[start + 1] > win) {
        delete hits[++start]
    }
    if (n - start >= thresh) {
        printf "ALERT: %d ERRORs in %ds at %s\n", n - start, win, strftime("%Y-%m-%d %H:%M:%S", now)
        fflush()
        # Reset so we do not fire on every subsequent line.
        delete hits
        n = 0
        start = 0
    }
}'
```

Run it as `./watch_errors.sh /var/log/app.log 5 60` to alert on five ERRORs inside any sixty-second window. `systime()` needs GNU awk (gawk) or mawk with time support; on plain POSIX awk replace it with a `date +%s` call or use `-v now=$(date +%s)` per line. The array is compacted by advancing `start`, so memory stays bounded by the window size, not the log size. It resets after each alert to avoid a storm of duplicate warnings.

