#include <cstddef>
#include <optional>
#include <stdexcept>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), cap_(capacity), head_(0), size_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == cap_; }

    // Push overwrites nothing: returns false when full.
    bool push(int value) {
        if (full()) return false;
        data_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int v = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

private:
    std::vector<int> data_;
    std::size_t cap_, head_, size_;
};

#include <cassert>
#include <vector>

int main() {
    RingBuffer rb(3);
    assert(rb.empty());
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.full() && !rb.push(4));
    assert(rb.pop() == 1);
    assert(rb.push(4));
    assert(rb.pop() == 2 && rb.pop() == 3 && rb.pop() == 4);
    assert(rb.pop() == std::nullopt);
    return 0;
}
