// Lower bound: first index with v[i] >= target; returns v.size() if none.
static std::size_t lower_bound_idx(const std::vector<int>& v, int target) {
    std::size_t lo = 0, hi = v.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (v[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

std::size_t count_occurrences(const std::vector<int>& v, int target) {
    std::size_t first = lower_bound_idx(v, target);
    std::size_t after = lower_bound_idx(v, target + 1);
    return after - first;
}

int main() {
    std::vector<int> v{1, 2, 2, 2, 3, 5};
    assert(count_occurrences(v, 2) == 3);
    assert(count_occurrences(v, 1) == 1);
    assert(count_occurrences(v, 4) == 0);
    assert(count_occurrences({}, 7) == 0);
    return 0;
}
