fn binary_search<T: Ord>(sorted: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = sorted.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match sorted[mid].cmp(target) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

fn main() {
    let data = [1, 3, 3, 5, 8, 13];
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &8), Some(4));
    assert!(binary_search(&data, &4).is_none());
    assert!(binary_search::<i32>(&[], &1).is_none());
