use std::collections::HashMap;

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '\'')
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the quick brown fox jumps over the lazy dog. The fox runs.";
    for (word, count) in top_words(text, 3) {
        println!("{}: {}", word, count);
    }
    assert!(top_words("", 3).is_empty());
    assert_eq!(top_words("a a b", 2), vec![("a".to_string(), 2), ("b".to_string(), 1)]);
}
