#include <stdio.h>
#include <stdint.h>

int popcount(uint64_t value) {
    int count = 0;
    while (value) {
        value &= value - 1;
        count++;
    }
    return count;
}

int main(void) {
    struct { uint64_t in; int want; } cases[] = {
        {0, 0},
        {1, 1},
        {0xFF, 8},
        {UINT64_MAX, 64},
        {0x8000000000000001ULL, 2},
    };
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
        int got = popcount(cases[i].in);
        if (got != cases[i].want) {
            printf("FAIL: 0x%llx got %d want %d\n",
                   (unsigned long long)cases[i].in, got, cases[i].want);
            return 1;
        }
    }
    printf("all %zu cases passed\n", sizeof(cases) / sizeof(cases[0]));
    return 0;
}
```

`value &= value - 1` clears the lowest set bit on each iteration, so the loop runs once per set bit rather than once per bit. The table covers zero, all-ones, a single high bit, and a mixed pattern; `%zu` prints `size_t` portably.

