template <typename T, std::size_t N>
class CircularBuffer {
public:
    bool push(const T& item) {
        if (full()) return false;
        data_[tail_] = item;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T item = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return item;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    CircularBuffer<int, 3> cb;
    for (int i = 1; i <= 4; ++i)
        std::cout << "push " << i << ": " << cb.push(i) << "\n";
    while (auto v = cb.pop())
        std::cout << "pop: " << *v << "\n";
    std::cout << "empty: " << cb.empty() << "\n";
}
```

Uses a size counter so `full()` and `empty()` don't collide when head and tail alias. Push on a full buffer returns `false` without overwriting; pop on empty returns `std::nullopt`.

