def make_change(cents: int, coins=(25, 10, 5, 1)) -> dict:
    """Return the fewest coins summing to `cents` as {denomination: count}.

    Uses greedy, which is optimal for US-style denominations (1,5,10,25).
    """
    if cents < 0:
        raise ValueError("cents must be non-negative")
    if cents == 0:
        return {}

    result = {}
    remaining = cents
    for coin in sorted(coins, reverse=True):
        if coin <= 0:
            raise ValueError("denominations must be positive")
        count, remaining = divmod(remaining, coin)
        if count:
            result[coin] = count
    return result


