/* Greatest common divisor via Euclid's algorithm.
   Normalises negatives; gcd(0,0) is defined as 0. */
static long long gcd(long long a, long long b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

