#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        if (full()) {
            throw std::overflow_error("ring buffer is full");
        }
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        ++size_;
    }

    std::optional<T> pop() {
        if (empty()) {
            return std::nullopt;
        }
        T value = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> buf;
    buf.push(1);
    buf.push(2);
    buf.push(3);
    if (buf.pop() != 1 || buf.pop() != 2) {
        std::cerr << "unexpected order\n";
        return 1;
    }
    buf.push(4);
    std::cout << buf.pop().value_or(-1) << ' ' << buf.pop().value_or(-1) << '\n';
    std::cout << (buf.empty() ? "empty" : "not empty") << '\n';
    return 0;
}
