use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Write};

fn stats(values: &[i64]) -> Option<(f64, f64, i64)> {
    if values.is_empty() {
        return None;
    }
    let sum: i64 = values.iter().sum();
    let mean = sum as f64 / values.len() as f64;

    let mut sorted = values.to_vec();
    sorted.sort_unstable();
    let mid = sorted.len() / 2;
    let median = if sorted.len() % 2 == 0 {
        (sorted[mid - 1] + sorted[mid]) as f64 / 2.0
    } else {
        sorted[mid] as f64
    };

    let mut counts: HashMap<i64, usize> = HashMap::new();
    for &v in values {
        *counts.entry(v).or_insert(0) += 1;
    }
    let mode = counts
        .iter()
        .max_by_key(|(v, c)| (**c, std::cmp::Reverse(**v)))
        .map(|(v, _)| *v)
        .unwrap();

    Some((mean, median, mode))
}

fn main() -> io::Result<()> {
    let path = env::args().nth(1).unwrap_or_else(|| "numbers.txt".to_string());
    let text = fs::read_to_string(&path)?;
    let values: Vec<i64> = text
        .split_whitespace()
        .filter_map(|t| t.parse().ok())
        .collect();

    match stats(&values) {
        Some((mean, median, mode)) => {
            writeln!(io::stdout(), "mean={mean:.2} median={median:.2} mode={mode}")
        }
        None => writeln!(io::stdout(), "no data"),
    }
}
