def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring using expand-around-center."""
    if not s:
        return ""

    def expand(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    best_start, best_end = 0, 0
    for i in range(len(s)):
        # Odd-length palindromes centred on i.
        l1, r1 = expand(i, i)
        # Even-length palindromes centred between i and i+1.
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > best_end - best_start:
            best_start, best_end = l1, r1
        if r2 - l2 > best_end - best_start:
            best_start, best_end = l2, r2

    return s[best_start:best_end + 1]


if __name__ == "__main__":
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "🙂ab🙂"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```

`expand` walks outward while characters match, so it returns the widest palindrome for a given centre; checking both odd and even centres covers every case. Empty input and single characters are handled up front, and the byte-level comparison works unchanged for non-ASCII text like emoji.

