def normalize_ipv4(addr: str) -> str | None:
    """Return the canonical dotted-quad form of addr, or None if invalid.

    Rejects leading zeros and out-of-range octets.
    """
    if not isinstance(addr, str):
        return None
    parts = addr.strip().split(".")
    if len(parts) != 4:
        return None
    octets = []
    for part in parts:
        if not part or not part.isdigit():
            return None
        if len(part) > 1 and part[0] == "0":
            return None  # leading zeros are ambiguous (octal) -> invalid
        value = int(part)
        if value < 0 or value > 255:
            return None
        octets.append(str(value))
    return ".".join(octets)


if __name__ == "__main__":
    good = ["192.168.0.1", "  10.0.0.255 ", "0.0.0.0", "255.255.255.255"]
    bad = ["256.1.1.1", "1.2.3", "1.2.3.4.5", "01.2.3.4", "1.2.3.a", "", "1..2.3"]
    for a in good:
        assert normalize_ipv4(a) is not None, a
    for a in bad:
        assert normalize_ipv4(a) is None, a
    print(normalize_ipv4("  010.0.0.1 "))  # None, leading zero
```

The function trims surrounding whitespace, requires exactly four dot-separated parts, and checks each part with `isdigit()` before converting. The `len(part) > 1 and part[0] == "0"` guard rejects leading zeros, which in some APIs would be read as octal. Values are range-checked against 0–255 and the canonical decimal form is reassembled, so `010.0.0.1` and `256.1.1.1` both come back as `None`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_WORDS 4096
typedef struct { char word[64]; long count; } Entry;

static int cmp_desc(const void *a, const void *b) {
    const Entry *x = a, *y = b;
    if (x->count != y->count) return (x->count < y->count) ? 1 : -1;
    return strcmp(x->word, y->word);
}

int main(int argc, char **argv) {
    long top = (argc > 1) ? strtol(argv[1], NULL, 10) : 10;
    if (top < 1) top = 10;

    Entry entries[MAX_WORDS];
    size_t n = 0;
    char buf[64];
    int c, len = 0;

    while ((c = getchar()) != EOF) {
        if (isalpha((unsigned char)c)) {
            if (len < (int)sizeof(buf) - 1) buf[len++] = (char)tolower((unsigned char)c);
        } else if (len > 0) {
            buf[len] = '\0';
            size_t i;
            for (i = 0; i < n; i++)
                if (strcmp(entries[i].word, buf) == 0) { entries[i].count++; break; }
            if (i == n && n < MAX_WORDS) {
                strncpy(entries[n].word, buf, sizeof(entries[n].word) - 1);
                entries[n].word[sizeof(entries[n].word) - 1] = '\0';
                entries[n].count = 1;
                n++;
            }
            len = 0;
        }
    }
    if (len > 0) {
        buf[len] = '\0';
        for (size_t i = 0; i < n; i++)
            if (strcmp(entries[i].word, buf) == 0) { entries[i].count++; break; }
    }

    qsort(entries, n, sizeof(Entry), cmp_desc);
    for (size_t i = 0; i < n && (long)i < top; i++)
        printf("%s %ld\n", entries[i].word, entries[i].count);
    return 0;
}
```

Words are lowercased with `tolower` (cast through `unsigned char` so negative `char` values don't trigger undefined behaviour). The `buf` guard caps a word at 63 characters so an unbroken token can't overflow. Ties in frequency are broken alphabetically in `cmp_desc`, making the output deterministic. `MAX_WORDS` bounds the table; beyond that, new words are ignored rather than crashing.

```rust
use std::env;

fn fib(n: u32) -> Option<u128> {
    let (mut a, mut b) = (0u128, 1u128);
    for _ in 0..n {
        a = b.checked_add(a)?;
        std::mem::swap(&mut a, &mut b);
    }
    Some(a)
}

fn main() {
    let n: u32 = env::args()
        .nth(1)
        .and_then(|s| s.parse().ok())
        .unwrap_or(10);

    match fib(n) {
        Some(v) => println!("fib({}) = {}", n, v),
        None => {
            eprintln!("fib({}) overflows u128", n);
            std::process::exit(1);
        }
    }

    // Sanity checks.
    assert_eq!(fib(0), Some(0));
    assert_eq!(fib(1), Some(1));
    assert_eq!(fib(10), Some(55));
    assert!(fib(200).is_none()); // exceeds u128 range
}
```

`checked_add` returns `None` the moment the sum would overflow `u128`, and the `?` bubbles that out of the loop, so `fib(200)` reports an overflow instead of wrapping. `std::mem::swap` advances the pair `(a, b)` without any intermediate allocation. The trailing `assert`s pin down the base cases and one known value; note the last assertion is only a sanity check that huge indices do fail, not a claim about the exact threshold.

```python
from collections import OrderedDict
from typing import Any


class LRUCache:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict[Any, Any] = OrderedDict()

    def get(self, key: Any) -> Any:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: Any, value: Any) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, "a")
    c.put(2, "b")
    assert c.get(1) == "a"      # 1 is now most-recent, 2 is LRU
    c.put(3, "c")               # evicts 2
    assert c.get(2) is None
    assert c.get(3) == "c"
    assert c.get(1) == "a"
    c.put(1, "A")               # update in place keeps capacity
    assert len(c) == 2
    print("ok")
```

`OrderedDict` maintains insertion order and `move_to_end` marks a key as recently used in O(1). `popitem(last=False)` removes the oldest entry when the capacity is exceeded. Re-inserting an existing key both refreshes its position and overwrites its value without growing the cache. The constructor rejects a non-positive capacity so the eviction logic can't loop.

