template <typename T>
T dot_product(const std::vector<T>& a, const std::vector<T>& b) {
    if (a.size() != b.size()) {
        throw std::invalid_argument("dot product requires equal-length vectors");
    }
    T acc{};
    for (std::size_t i = 0; i < a.size(); ++i) {
        acc += a[i] * b[i];
    }
    return acc;
}

int main() {
    std::vector<int> a{1, 2, 3};
    std::vector<int> b{4, 5, 6};
