    std::vector<double> y{2.0, 4.0};
    std::cout << dot_product(x, y) << '\n';  // 11

    try {
        dot_product(a, std::vector<int>{1, 2});
    } catch (const std::invalid_argument& e) {
        std::cout << "caught: " << e.what() << '\n';
    }

    std::vector<int> empty;
    std::cout << dot_product(empty, empty) << '\n';  // 0 for empty input
}
