#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;                                  // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap

    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) {
            low.push(x);
        } else {
            high.push(x);
        }
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }
    }

    if (low.empty()) {
        std::cout << "no input\n";
        return 0;
    }

    if (low.size() == high.size()) {
        std::cout << (low.top() + high.top()) / 2.0 << '\n';
    } else {
        std::cout << low.top() << '\n';
    }
    return 0;
}
```

The two heaps keep the lower half in `low` (max-heap) and the upper half in `high` (min-heap), rebalancing so their sizes differ by at most one. The median is the top of `low`, or the average of both tops when the sizes are equal. Empty input prints `no input` instead of dereferencing an empty heap.

