```python
import threading
from collections import deque
from typing import Generic, TypeVar

T = TypeVar("T")


class BoundedQueue(Generic[T]):
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._items: deque[T] = deque()
        self._lock = threading.Lock()
        self._not_full = threading.Condition(self._lock)
        self._not_empty = threading.Condition(self._lock)

    def put(self, item: T) -> None:
        with self._not_full:
            while len(self._items) >= self._capacity:
                self._not_full.wait()
            self._items.append(item)
            self._not_empty.notify()

    def get(self) -> T:
        with self._not_empty:
            while not self._items:
                self._not_empty.wait()
            item = self._items.popleft()
            self._not_full.notify()
            return item

    def __len__(self) -> int:
        with self._lock:
            return len(self._items)


if __name__ == "__main__":
    q: BoundedQueue[int] = BoundedQueue(2)
    out: list[int] = []

    def producer():
        for i in range(5):
            q.put(i)

    def consumer():
        for _ in range(5):
            out.append(q.get())

    ts = [threading.Thread(target=producer), threading.Thread(target=consumer)]
    for t in ts:
        t.start()
    for t in ts:
        t.join()
    assert out == [0, 1, 2, 3, 4]
    print("ok")
```

Both conditions share the same lock, so the `while` re-checks protect against spurious wakeups and lost notifications. Capacity is validated up front, and `deque.popleft` keeps `get` O(1).

```cpp
#include <cassert>

struct Node {
    int value;
    Node* next;
    explicit Node(int v, Node* n = nullptr) : value(v), next(n) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;   // new head, or nullptr for an empty list
}

bool has_cycle(const Node* head) {
    const Node* slow = head;
    const Node* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            return true;
        }
    }
    return false;
}

int main() {
    Node c(3), b(2, &c), a(1, &b);
    assert(reverse(nullptr) == nullptr);
    Node* r = reverse(&a);
    assert(r->value == 3 && r->next->value == 2 && r->next->next->value == 1);
    assert(r->next->next->next == nullptr);
    assert(!has_cycle(r));
    r->next->next->next = r;   // make a cycle
    assert(has_cycle(r));
    return 0;
}
```

`reverse` relinks pointers in one pass and returns the old tail as the new head. `has_cycle` is Floyd's tortoise-and-hare: if the fast pointer catches the slow one, there is a cycle; both run in O(n) time and O(1) space.

```rust
use std::collections::HashMap;

struct LruCache {
    cap: usize,
    map: HashMap<i32, i32>,
    order: Vec<i32>, // least-recently-used first
}

impl LruCache {
    fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache { cap, map: HashMap::new(), order: Vec::new() }
    }

    fn touch(&mut self, key: i32) {
        if let Some(pos) = self.order.iter().position(|&k| k == key) {
            self.order.remove(pos);
        }
        self.order.push(key);
    }

    fn get(&mut self, key: i32) -> Option<i32> {
        let value = *self.map.get(&key)?;
        self.touch(key);
        Some(value)
    }

    fn put(&mut self, key: i32, value: i32) {
        if self.map.contains_key(&key) {
            self.map.insert(key, value);
            self.touch(key);
            return;
        }
        if self.map.len() == self.cap {
            let lru = self.order.remove(0);
            self.map.remove(&lru);
        }
        self.map.insert(key, value);
        self.order.push(key);
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 10);
    c.put(2, 20);
    assert_eq!(c.get(1), Some(10)); // 1 is now most-recent
    c.put(3, 30);                  // evicts 2
    assert_eq!(c.get(2), None);
    assert_eq!(c.get(1), Some(10));
    assert_eq!(c.get(3), Some(30));
    c.put(3, 33);
    assert_eq!(c.get(3), Some(33));
    println!("ok");
}
```

A `Vec` stands in for the linked list here so the logic stays readable: `order` tracks recency, `get` and updates move keys to the back, and `put` removes the front key once capacity is exceeded. The map and order vector stay in sync on every mutation.

