fn last_chunk(bytes: &[u8], chunk_size: usize) -> Option<&[u8]> {
    if bytes.is_empty() || chunk_size == 0 {
        return None;
    }
    let remainder = bytes.len() % chunk_size;
    let start = if remainder == 0 {
        bytes.len() - chunk_size
    } else {
        bytes.len() - remainder
    };
    Some(&bytes[start..])
}

fn main() {
