def normalize(path):
    if not path:
        return ""
    absolute = path.startswith("/")
    parts = []
    for segment in path.split("/"):
        if segment in ("", "."):
            continue
        if segment == ".." and parts and parts[-1] != "..":
            parts.pop()
        elif segment == ".." and not absolute:
            parts.append(segment)
        elif segment != "..":
            parts.append(segment)
    result = "/".join(parts)
    if absolute:
        result = "/" + result
    return result or ("/" if absolute else ".")


