/// Iterative Fibonacci using checked addition; returns None on u64 overflow.
fn fibonacci(n: u32) -> Option<u64> {
    let (mut a, mut b): (u64, u64) = (0, 1);
    for _ in 0..n {
        let next = a.checked_add(b)?;
        a = b;
        b = next;
    }
    Some(a)
