use std::collections::HashMap;

#[derive(Debug, PartialEq, Eq)]
pub enum ParseError {
    MissingEquals(String),
    EmptyKey,
}

pub fn parse_pairs(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    if input.trim().is_empty() {
        return Ok(map);
    }

    for pair in input.split(';') {
        let pair = pair.trim();
        if pair.is_empty() {
            continue;
        }
        let (key, value) = match pair.split_once('=') {
            Some(kv) => kv,
            None => return Err(ParseError::MissingEquals(pair.to_string())),
        };
        let key = key.trim();
        if key.is_empty() {
            return Err(ParseError::EmptyKey);
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_and_rejects() {
        let m = parse_pairs("a=1; b=2 ;c = 3").unwrap();
        assert_eq!(m["a"], "1");
        assert_eq!(m["c"], "3");
        assert_eq!(parse_pairs("a=1;bogus"), Err(ParseError::MissingEquals("bogus".into())));
        assert_eq!(parse_pairs("=5"), Err(ParseError::EmptyKey));
        assert!(parse_pairs("  ").unwrap().is_empty());
    }
}
```

