```cpp
#include <condition_variable>
#include <mutex>
#include <queue>
#include <stdexcept>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(int value) {
        std::unique_lock<std::mutex> lock(m_);
        not_full_.wait(lock, [this] { return q_.size() < cap_; });
        q_.push(value);
        lock.unlock();
        not_empty_.notify_one();
    }

    int pop() {
        std::unique_lock<std::mutex> lock(m_);
        not_empty_.wait(lock, [this] { return !q_.empty(); });
        int value = q_.front();
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

private:
    std::size_t cap_;
    std::queue<int> q_;
    std::mutex m_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
};

#include <cassert>
#include <thread>
int main() {
    BoundedQueue q(2);
    std::thread producer([&] { for (int i = 0; i < 5; ++i) q.push(i); });
    std::thread consumer([&] { for (int i = 0; i < 5; ++i) assert(q.pop() == i); });
    producer.join();
    consumer.join();
    return 0;
}
```

Predicate-based `wait` makes both loops immune to spurious wakeups. The producer blocks when the queue is full and the consumer blocks when it is empty; each notifications is issued after releasing the lock to avoid waking a thread that then stalls on the mutex.

