bool is_anagram(const std::string& a, const std::string& b) {
    std::array<int, 26> counts{};
    auto fold = [&counts](const std::string& s, int sign) {
        for (unsigned char ch : s) {
            if (std::isalpha(ch)) {
                counts[std::tolower(ch) - 'a'] += sign;
            }
        }
    };
    fold(a, +1);
    fold(b, -1);
    for (int c : counts) if (c != 0) return false;
    return true;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_anagram("Listen", "Silent") << "\n";        // true
    std::cout << is_anagram("Dormitory", "dirty room") << "\n"; // true
    std::cout << is_anagram("hello", "world") << "\n";          // false
    std::cout << is_anagram("", "!!!") << "\n";                 // true
    return 0;
}
