use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split(|c: char| !c.is_alphanumeric() && c != '\'') {
        let cleaned: String = word
            .trim_matches('\'')
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '\'')
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count descending, then word ascending for stable output.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The quick, the QUICK brown fox. Don't don't jump!";
    let result = top_words(text, 3);
    for (word, count) in &result {
        println!("{word}: {count}");
    }
    assert_eq!(result[0], ("the".to_string(), 2));
    assert_eq!(result[1], ("don't".to_string(), 2));
}
