```cpp
#include <algorithm>
#include <stdexcept>
#include <vector>

template <typename T>
T kth_smallest(std::vector<T> data, std::size_t k) {
    if (k == 0 || k > data.size()) {
        throw std::out_of_range("k out of range");
    }
    std::size_t target = k - 1;  // 0-based index
    std::size_t lo = 0, hi = data.size() - 1;
    while (lo < hi) {
        // Median-of-three pivot reduces the chance of worst-case splits.
        std::size_t mid = lo + (hi - lo) / 2;
        if (data[mid] < data[lo]) std::swap(data[mid], data[lo]);
        if (data[hi] < data[lo]) std::swap(data[hi], data[lo]);
        if (data[hi] < data[mid]) std::swap(data[hi], data[mid]);
        std::swap(data[mid], data[hi]);
        T pivot = data[hi];

        std::size_t store = lo;
        for (std::size_t i = lo; i < hi; ++i) {
            if (data[i] < pivot) {
                std::swap(data[i], data[store]);
                ++store;
            }
        }
        std::swap(data[store], data[hi]);

        if (store == target) return data[store];
        if (store < target) lo = store + 1;
        else hi = store - 1;
    }
    return data[lo];
}

int main() {
    std::vector<int> v{7, 1, 5, 3, 9, 2};
    for (std::size_t k = 1; k <= v.size(); ++k) {
        std::vector<int> sorted = v;
        std::sort(sorted.begin(), sorted.end());
        if (kth_smallest(v, k) != sorted[k - 1]) return 1;
    }
    return 0;
}
```
Quickselect partitions around a pivot and recurses into only the side containing the target rank, giving average O(n) time. The function takes `data` by value so the caller's vector is untouched, and the median-of-three choice lowers the odds of quadratic behaviour on sorted input. The `main` cross-checks every rank against a full sort.

