#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v, Node* n = nullptr) : value(v), next(n) {}
};

// Iterative reverse: O(n) time, O(1) extra space, no recursion.
Node* reverse_list(Node* head) {
    Node* prev = nullptr;
    Node* current = head;
    while (current != nullptr) {
        Node* next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }
    return prev;
}

void print_list(const Node* head) {
    for (const Node* node = head; node != nullptr; node = node->next) {
        std::cout << node->value;
        if (node->next != nullptr) std::cout << " -> ";
    }
    std::cout << "\n";
}

void free_list(Node* head) {
    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    Node* head = nullptr;
    for (int value : {1, 2, 3, 4, 5}) {
        head = new Node(value, head);  // build 5 -> 4 -> 3 -> 2 -> 1
    }
    print_list(head);
    head = reverse_list(head);
    print_list(head);
    free_list(head);
    return 0;
}
