/// Count set bits using Brian Kernighan's trick.
/// Each iteration clears the lowest set bit, so the loop runs popcount times.
pub fn count_set_bits(mut value: u64) -> u32 {
    let mut count = 0;
    while value != 0 {
        value &= value - 1;
        count += 1;
    }
    count
}

