def is_valid_ipv4(address):
    """Return True if address is four dotted decimal octets in 0-255 with no leading zeros."""
    if not isinstance(address, str):
        return False
    parts = address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not part.isdigit():
            return False
        # Reject leading zeros like "01" but allow a single "0".
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False
    return True


