```c
#include <stdio.h>
#include <string.h>

/* Write the binary representation of n into buf (size >= 66). */
static int to_binary(long long n, char *buf, size_t size) {
    unsigned long long u;
    int negative = 0;
    if (n < 0) {
        negative = 1;
        u = (unsigned long long)(-(n + 1)) + 1ULL; /* avoids overflow for LLONG_MIN */
    } else {
        u = (unsigned long long)n;
    }

    char tmp[64];
    int len = 0;
    if (u == 0) {
        tmp[len++] = '0';
    } else {
        while (u > 0) {
            tmp[len++] = (char)('0' + (u & 1ULL));
            u >>= 1;
        }
    }

    size_t need = (size_t)len + (size_t)negative + 1;
    if (need > size) {
        return -1;
    }

    int pos = 0;
    if (negative) {
        buf[pos++] = '-';
    }
    for (int i = len - 1; i >= 0; --i) {
        buf[pos++] = tmp[i];
    }
    buf[pos] = '\0';
    return pos;
}

int main(void) {
    long long inputs[] = {0, 1, 2, 5, 255, 256, -1, -255, 9223372036854775807LL};
    char buf[80];
    for (size_t i = 0; i < sizeof(inputs) / sizeof(inputs[0]); ++i) {
        if (to_binary(inputs[i], buf, sizeof(buf)) < 0) {
            printf("buffer too small\n");
            continue;
        }
        printf("%lld -> %s\n", inputs[i], buf);
    }
    return 0;
}
```

The two's-complement magnitude for negatives is computed as `-(n+1) + 1` so `LLONG_MIN` does not overflow. Digits are generated low bit first then reversed, so no bit-width assumption is baked in.

```rust
/// Return Some(nth Fibonacci) or None on u128 overflow.
/// fib(0)=0, fib(1)=1.
pub fn fib(n: u32) -> Option<u128> {
    let (mut a, mut b): (u128, u128) = (0, 1);
    for _ in 0..n {
        let next = a.checked_add(b)?;
        a = b;
        b = next;
    }
    Some(a)
}

fn main() {
    assert_eq!(fib(0), Some(0));
    assert_eq!(fib(1), Some(1));
    assert_eq!(fib(10), Some(55));
    assert_eq!(fib(20), Some(6765));
    // fib(185) is the largest term that fits in u128.
    assert!(fib(185).is_some());
    assert_eq!(fib(186), None);
    println!("fib(100) = {:?}", fib(100).unwrap());
    println!("all assertions passed");
}
```

Loop carries two consecutive terms; `checked_add` turns overflow into `None` instead of wrapping or panicking. Because each iteration advances one term, `fib(n)` returns the n-th value. fib(186) exceeds u128, which the test confirms.

