def safe_extract(archive_path, dest):
    """Extract tar to dest, rejecting members that escape dest or are absolute."""
    os.makedirs(dest, exist_ok=True)
    with tarfile.open(archive_path, "r:*") as tar:
        for member in tar.getmembers():
            if member.name.startswith(("/", "\\")) or ".." in member.name.split("/"):
                raise ValueError(f"unsafe member path: {member.name!r}")
            target = os.path.join(dest, member.name)
            if not _is_within(dest, target):
                raise ValueError(f"member escapes destination: {member.name!r}")
            if member.islnk() or member.issym():
                link_target = os.path.join(dest, member.linkname)
                if not _is_within(dest, link_target):
                    raise ValueError(f"unsafe link target: {member.linkname!r}")
        tar.extractall(dest, members=[m for m in tar.getmembers() if m.isreg() or m.isdir()])


if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("usage: extract.py ARCHIVE DEST", file=sys.stderr)
        sys.exit(1)
    safe_extract(sys.argv[1], sys.argv[2])
```

Two layers of defence: a lexical check for absolute paths and `..` components, then a realpath containment check. Symlink/hardlink members are validated because they can redirect writes outside `dest`. Only regular files and directories are extracted, so device/fifo members cannot appear.

