def is_valid_ipv4(s: str) -> bool:
    """Return True if s is a valid dotted-quad IPv4 address."""
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        # Reject leading zeros like "01" (but allow the single digit "0").
        if len(part) > 1 and part[0] == '0':
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True


