use std::collections::HashMap;

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    let mut current = String::new();

    let mut flush = |current: &mut String, counts: &mut HashMap<String, usize>| {
        if !current.is_empty() {
            *counts.entry(current.clone()).or_insert(0) += 1;
            current.clear();
        }
    };

    for ch in text.chars() {
        if ch.is_alphanumeric() {
            for lower in ch.to_lowercase() {
                current.push(lower);
            }
        } else {
            flush(&mut current, &mut counts);
        }
    }
    flush(&mut current, &mut counts);

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count descending, then alphabetically for stable, deterministic output.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the quick brown Fox jumps over the lazy dog. The fox!";
    assert_eq!(
        top_words(text, 3),
        vec![
            ("the".to_string(), 3),
            ("fox".to_string(), 2),
            ("brown".to_string(), 1),
        ]
    );
    assert!(top_words("", 5).is_empty());
    println!("ok");
}
