```python
import functools
import time
from typing import Tuple, Type


def retry(
    times: int = 3,
    delay: float = 0.1,
    backoff: float = 2.0,
    exceptions: Tuple[Type[BaseException], ...] = (Exception,),
):
    if times < 1:
        raise ValueError('times must be >= 1')

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            wait = delay
            last_exc = None
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
                    if attempt == times:
                        break
                    time.sleep(wait)
                    wait *= backoff
            raise last_exc  # type: ignore[misc]

        return wrapper

    return decorator


if __name__ == '__main__':
    calls = {'n': 0}

    @retry(times=4, delay=0.0, exceptions=(ValueError,))
    def flaky():
        calls['n'] += 1
        if calls['n'] < 3:
            raise ValueError('not yet')
        return 'done'

    assert flaky() == 'done'
    assert calls['n'] == 3

    @retry(times=2, delay=0.0, exceptions=(ValueError,))
    def always():
        raise TypeError('nope')

    try:
        always()
    except TypeError:
        pass
    else:
        raise AssertionError('TypeError should not be retried')

    print('ok')
