bool is_prime(std::uint64_t n) {
    if (n < 2) {
        return false;
    }
    if (n % 2 == 0) {
        return n == 2;
    }
    if (n % 3 == 0) {
        return n == 3;
    }
    // All primes above 3 are of the form 6k +/- 1.
    for (std::uint64_t i = 5; i <= n / i; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

int main() {
    const std::uint64_t expected_primes[] = {2, 3, 5, 7, 11, 13, 97, 7919, 104729};
    for (std::uint64_t p : expected_primes) {
        if (!is_prime(p)) {
            std::cerr << p << " should be prime\n";
            return 1;
        }
    }
    const std::uint64_t expected_composites[] = {0, 1, 4, 9, 15, 100, 7917, 104730};
    for (std::uint64_t c : expected_composites) {
        if (is_prime(c)) {
            std::cerr << c << " should be composite\n";
            return 1;
        }
    }
    std::cout << "all checks passed\n";
    return 0;
}
