```cpp
#include <iostream>
#include <vector>

int binarySearch(const std::vector<int>& a, int target) {
    int lo = 0, hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;   // avoids overflow
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> a{1, 3, 5, 7, 9, 11};
    std::cout << binarySearch(a, 1)  << '\n';  // 0
    std::cout << binarySearch(a, 11) << '\n';  // 5
    std::cout << binarySearch(a, 7)  << '\n';  // 3
    std::cout << binarySearch(a, 4)  << '\n';  // -1
    std::cout << binarySearch({}, 4) << '\n';  // -1
    return 0;
}
```

`lo + (hi - lo) / 2` prevents overflow when `lo` and `hi` are large. The loop closes at `lo <= hi`, so both endpoints are checked; an empty vector makes `hi = -1` and skips the loop entirely, returning -1.

