class FileHandle {
public:
    explicit FileHandle(const char* path, const char* mode = "r")
        : fp_(std::fopen(path, mode)) {}

    ~FileHandle() { if (fp_) std::fclose(fp_); }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fp_(other.fp_) { other.fp_ = nullptr; }
    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            if (fp_) std::fclose(fp_);
            fp_ = other.fp_;
            other.fp_ = nullptr;
        }
        return *this;
    }

    bool valid() const { return fp_ != nullptr; }
    FILE* get() const { return fp_; }

private:
    FILE* fp_;
};

int main() {
    FileHandle f("data.txt", "w");
    if (!f.valid()) return 1;
    std::fputs("hello\n", f.get());
    FileHandle g = std::move(f);   // f is now empty, g owns the handle
    return 0;                       // g's destructor closes it
}
```

Copying is deleted so a handle is never closed twice. Move transfers ownership and nulls the source; `valid()` lets callers check the `fopen` result without a separate flag.

