fn second_largest<T: PartialOrd + Copy>(xs: &[T]) -> Option<T> {
    let mut best: Option<T> = None;
    let mut second: Option<T> = None;
    for &x in xs {
        match best {
            None => best = Some(x),
            Some(b) if x > b => {
                second = best;
                best = Some(x);
            }
            Some(b) if x < b => {
                if second.map_or(true, |s| x > s) {
                    second = Some(x);
                }
            }
            _ => {} // equal to best: ignore duplicates
        }
    }
    second
}

fn main() {
    assert_eq!(second_largest(&[3, 1, 4, 1, 5, 9, 2, 6]), Some(6));
    assert_eq!(second_largest(&[5, 5, 5]), None);
    assert_eq!(second_largest(&[1]), None);
    assert_eq!(second_largest(&[] as &[i32]), None);
    println!("ok");
}
```

Two registers track the largest and second-largest distinct values. Equal-to-best values fall through the `_` arm so duplicates never claim the second slot, which is why `[5, 5, 5]` returns `None`.

```python
import functools
import time


def retry(times: int = 3, base_delay: float = 0.1):
    if times < 1:
        raise ValueError("times must be >= 1")

    def decorate(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(times):
                try:
                    return fn(*args, **kwargs)
                except Exception as exc:  # deliberately broad: retry any failure
                    last = exc
                    if attempt < times - 1:
                        time.sleep(base_delay * (2 ** attempt))
            raise last
        return wrapper
    return decorate


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(times=4, base_delay=0.0)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise RuntimeError("not yet")
        return "done"

    assert flaky() == "done"
    assert calls["n"] == 3

    @retry(times=2, base_delay=0.0)
    def always_fail():
        raise ValueError("boom")

    try:
        always_fail()
    except ValueError as exc:
        assert str(exc) == "boom"
    else:
        raise AssertionError("expected failure")
    print("ok")
```

The retry count is validated eagerly. Each failed attempt sleeps `base_delay * 2**attempt`, and the delay is skipped after the final attempt. If every attempt raises, the last exception is re-raised so the caller sees the original error.

