// Reverse the order of words in `s`, collapsing all runs of whitespace to one space.
std::string reverseWords(const std::string& s) {
    std::vector<std::string> words;
    std::string cur;
    for (char c : s) {
        if (std::isspace(static_cast<unsigned char>(c))) {
            if (!cur.empty()) { words.push_back(cur); cur.clear(); }
        } else {
            cur.push_back(c);
        }
    }
    if (!cur.empty()) words.push_back(cur);

    std::string out;
    for (auto it = words.rbegin(); it != words.rend(); ++it) {
        if (!out.empty()) out.push_back(' ');
        out += *it;
    }
    return out;
}

int main() {
    std::cout << "[" << reverseWords("  hello   world  ") << "]\n"; // [world hello]
    std::cout << "[" << reverseWords("") << "]\n";                   // []
    std::cout << "[" << reverseWords("a") << "]\n";                  // [a]
    return 0;
}
```

I tokenize into words first, then rejoin in reverse. Casting `c` to `unsigned char` avoids undefined behaviour when `isspace` sees a negative char value.

