from typing import List

def binary_search(nums: List[int], target: int) -> int:
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

if __name__ == "__main__":
    print(binary_search([], 5))          # -1
    print(binary_search([1, 3, 5, 7], 5)) # 2
    print(binary_search([1, 3, 5, 7], 4)) # -1
