// returns (F(n), F(n+1))
std::pair<long long, long long> fib_pair(int n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n / 2);
    long long c = a * (2 * b - a);
    long long d = a * a + b * b;
    if (n % 2 == 0) return {c, d};
    return {d, c + d};
}

