```rust
use std::collections::HashMap;

struct LruCache {
    cap: usize,
    map: HashMap<i32, i32>,
    order: Vec<i32>, // most-recent last
}

impl LruCache {
    fn new(cap: usize) -> Self {
        LruCache { cap, map: HashMap::new(), order: Vec::new() }
    }

    fn touch(&mut self, key: i32) {
        if let Some(pos) = self.order.iter().position(|&k| k == key) {
            self.order.remove(pos);
        }
        self.order.push(key);
    }

    fn get(&mut self, key: i32) -> Option<i32> {
        if let Some(&v) = self.map.get(&key) {
            self.touch(key);
            Some(v)
        } else {
            None
        }
    }

    fn put(&mut self, key: i32, value: i32) {
        if self.map.contains_key(&key) {
            self.map.insert(key, value);
            self.touch(key);
            return;
        }
        if self.map.len() == self.cap {
            if let Some(old) = self.order.first().copied() {
                self.order.remove(0);
                self.map.remove(&old);
            }
        }
        self.map.insert(key, value);
        self.order.push(key);
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 1);
    c.put(2, 2);
    assert_eq!(c.get(1), Some(1));
    c.put(3, 3);              // evicts 2
    assert_eq!(c.get(2), None);
    assert_eq!(c.get(3), Some(3));
}
```

This is O(n) per touch because `Vec` removal is linear; for a hot path swap in a `LinkedList`+`HashMap` of nodes or use an external crate like `lru`.

