#include <condition_variable>
#include <mutex>
#include <queue>
#include <iostream>
#include <thread>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(size_t cap) : cap_(cap) {}

    void push(T value) {
        std::unique_lock<std::mutex> lock(m_);
        not_full_.wait(lock, [this] { return q_.size() < cap_; });
        q_.push(std::move(value));
        not_empty_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(m_);
        not_empty_.wait(lock, [this] { return !q_.empty(); });
        T value = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return value;
    }

private:
    std::queue<T> q_;
    size_t cap_;
    std::mutex m_;
    std::condition_variable not_full_, not_empty_;
};

int main() {
    BoundedQueue<int> q(4);
    std::thread producer([&] {
        for (int i = 1; i <= 10; ++i) q.push(i);
    });
    for (int i = 0; i < 10; ++i) std::cout << q.pop() << ' ';
    std::cout << '\n';
    producer.join();
    return 0;
}
```
Both waits use predicates so spurious wakeups are handled; each push/pop notifies exactly one waiter on the opposite condition. The bounded size makes the producer block when the queue is full.

