```rust
#[derive(Debug)]
struct Node {
    value: i32,
    next: Option<Box<Node>>,
}

fn push(head: Option<Box<Node>>, value: i32) -> Option<Box<Node>> {
    Some(Box::new(Node { value, next: head }))
}

fn reverse(mut head: Option<Box<Node>>) -> Option<Box<Node>> {
    let mut prev = None;
    while let Some(mut node) = head {
        head = node.next.take();
        node.next = prev;
        prev = Some(node);
    }
    prev
}

fn to_vec(mut head: &Option<Box<Node>>) -> Vec<i32> {
    let mut out = Vec::new();
    while let Some(node) = head {
        out.push(node.value);
        head = &node.next;
    }
    out
}

fn main() {
    let mut list = None;
    for v in [3, 2, 1] {
        list = push(list, v);
    }
    assert_eq!(to_vec(&list), vec![1, 2, 3]);
    let rev = reverse(list);
    assert_eq!(to_vec(&rev), vec![3, 2, 1]);
    assert!(reverse(None).is_none());
    println!("ok");
}
```
