fn search<T: Ord>(haystack: &[T], needle: &T) -> Result<usize, usize> {
    let (mut lo, mut hi) = (0, haystack.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if haystack[mid] < *needle {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if lo < haystack.len() && haystack[lo] == *needle {
        Ok(lo)
    } else {
        Err(lo)
    }
}

