        assert_eq!(search(&data, &5), Ok(2));
        assert_eq!(search(&data, &4), Err(2));
        assert_eq!(search(&data, &0), Err(0));
        assert_eq!(search(&data, &10), Err(5));
        let empty: [i32; 0] = [];
        assert_eq!(search(&empty, &1), Err(0));
    }
}

fn main() {
    let data = [1, 3, 5];
    println!("{:?}", search(&data, &3));
}
