def fib(n):
    """Return the n-th Fibonacci number (F(0)=0, F(1)=1) via fast doubling."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def _fib(k):
        # Returns (F(k), F(k+1)).
        if k == 0:
            return (0, 1)
        a, b = _fib(k >> 1)
        c = a * ((b << 1) - a)   # F(2m)
        d = a * a + b * b        # F(2m+1)
        if k & 1:
            return (d, c + d)
        return (c, d)

    return _fib(n)[0]


if __name__ == "__main__":
    assert fib(0) == 0
    assert fib(1) == 1
    assert fib(10) == 55
    assert fib(50) == 12586269025
    assert fib(200) % 10**9 == 845763490  # large value stays exact
    try:
        fib(-1)
    except ValueError as e:
        print("expected error:", e)
    print("fib(300) has", len(str(fib(300))), "digits")
```

