bool isBalanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            bool match = (c == ')' && open == '(') ||
                         (c == ']' && open == '[') ||
                         (c == '}' && open == '{');
            if (!match) return false;
        }
        // any other character is ignored
    }
    return st.empty();
}

int main() {
    assert(isBalanced(""));
    assert(isBalanced("()[]{} "));
    assert(isBalanced("{[()]}"));
    assert(!isBalanced("(]"));
    assert(!isBalanced("([)]"));
    assert(!isBalanced("("));
    assert(!isBalanced(")"));
    std::cout << "all tests passed\n";
    return 0;
}
