#include <iostream>
#include <queue>
#include <vector>
#include <iomanip>

class MedianFinder {
    std::priority_queue<int> lo;                              // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> hi; // min-heap
public:
    void add(int x) {
        if (lo.empty() || x <= lo.top()) lo.push(x);
        else hi.push(x);
        // keep sizes balanced: lo.size() == hi.size() or lo.size() == hi.size()+1
        if (lo.size() > hi.size() + 1) { hi.push(lo.top()); lo.pop(); }
        else if (hi.size() > lo.size()) { lo.push(hi.top()); hi.pop(); }
    }
    double median() const {
        if (lo.empty()) return 0.0; // no data
        if (lo.size() == hi.size()) return (lo.top() + hi.top()) / 2.0;
        return lo.top();
    }
};

int main() {
    MedianFinder mf;
    int x;
    while (std::cin >> x) {
        mf.add(x);
        std::cout << std::fixed << std::setprecision(1) << mf.median() << "\n";
    }
    if (std::cin.fail() && !std::cin.eof()) {
        std::cerr << "warning: non-integer input ignored\n";
    }
    return 0;
}
```

Splitting values across a max-heap of the lower half and a min-heap of the upper half keeps the median at one or both tops in O(log n) per insert. Rebalancing after every insert guarantees the size invariant. The EOF loop stops cleanly when the stream ends, and `std::cin.fail()` catches malformed input instead of silently misreading.

