    let mut out = Vec::new();
    while let Some(node) = head {
        out.push(node.value);
        head = &node.next;
    }
    out
}

fn main() {
    let list = from_slice(&[1, 2, 3, 4]);
    assert_eq!(to_vec(&list), vec![1, 2, 3, 4]);
    let rev = reverse(list);
    assert_eq!(to_vec(&rev), vec![4, 3, 2, 1]);

    let empty: Option<Box<Node>> = None;
    assert_eq!(to_vec(&reverse(empty)), Vec::<i32>::new());
    assert_eq!(to_vec(&from_slice(&[])), Vec::<i32>::new());
    println!("all tests passed");
}
```

`node.next.take()` moves the tail out before rewiring `node.next = prev`, which satisfies the borrow checker without cloning. The empty and single-element cases fall out of the same loop — reversing an empty list returns `None`. `to_vec` borrows rather than consuming so assertions can inspect the list before and after.

