```c
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

/* Parses a non-negative long from s. Returns 0 on success, -1 on failure,
   writing the value to *out. Rejects empty input, sign characters,
   trailing junk, and overflow. */
static int parse_nonneg(const char *s, long *out) {
    if (s == NULL || *s == '\0') return -1;
    if (!isdigit((unsigned char)*s)) return -1; /* no leading +, -, or space */

    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno == ERANGE || v < 0) return -1;
    if (end == s || *end != '\0') return -1;

    *out = v;
    return 0;
}

int main(void) {
    const char *tests[] = {"0", "42", "", "-3", "7x", " 5", "9999999999999999999"};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); i++) {
        long v = 0;
        if (parse_nonneg(tests[i], &v) == 0)
            printf("%-22s -> %ld\n", tests[i], v);
        else
            printf("%-22s -> invalid\n", tests[i]);
    }
    return 0;
}
```

`strtol` sets `errno` to `ERANGE` on overflow and `end` points at the first unconsumed character, so checking `*end == '\0'` rejects `"7x"` and `" 5"` while `isdigit` on the first byte rejects sign and whitespace prefixes. One caveat: this rejects `" 5"` deliberately; if you wanted leading spaces allowed you would skip them before the `isdigit` check.

```cpp
#include <algorithm>
#include <iostream>
#include <vector>

// Rotates v left by k positions in place using the three-reverse trick.
void rotate_left(std::vector<int>& v, std::size_t k) {
    if (v.empty()) return;
    k %= v.size();
    if (k == 0) return;
    std::reverse(v.begin(), v.begin() + static_cast<std::ptrdiff_t>(k));
    std::reverse(v.begin() + static_cast<std::ptrdiff_t>(k), v.end());
    std::reverse(v.begin(), v.end());
}

int main() {
    for (std::size_t k : {0u, 1u, 3u, 7u}) {
        std::vector<int> v{1, 2, 3, 4, 5};
        rotate_left(v, k);
        std::cout << "k=" << k << ": ";
        for (int x : v) std::cout << x << ' ';
        std::cout << '\n';
    }

    std::vector<int> empty;
    rotate_left(empty, 5);
    std::cout << "empty size: " << empty.size() << '\n';
}
```

The `k %= v.size()` guard handles k greater than the length, and the early return on `k == 0` avoids doing three no-op reversals. The three-reverse approach runs in O(n) time and O(1) extra space. Reversing the first k, then the rest, then the whole vector yields a left rotation.

```rust
use std::collections::HashMap;
use std::env;
use std::fs;
use std::io;

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split(|c: char| !c.is_alphanumeric() && c != '\'') {
        if word.is_empty() {
            continue;
        }
        *counts.entry(word.to_lowercase()).or_insert(0) += 1;
    }

    let mut entries: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by descending count, then ascending word for stable ties.
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    entries.truncate(n);
    entries
}

fn main() -> io::Result<()> {
    let path = env::args().nth(1).unwrap_or_else(|| "input.txt".to_string());
    let text = fs::read_to_string(&path)?;
    for (word, count) in top_words(&text, 5) {
        println!("{:>6}  {}", count, word);
    }
    Ok(())
}
