```c
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007ULL

/* Returns fib(n) mod MOD for n >= 0; returns 0 for invalid negative input
   and sets *ok to 0. */
static uint64_t fib_mod(long n, int *ok) {
    if (n < 0) {
        *ok = 0;
        return 0;
    }
    *ok = 1;
    uint64_t a = 0, b = 1;
    for (long i = 0; i < n; i++) {
        uint64_t next = (a + b) % MOD;
        a = b;
        b = next;
    }
    return a;
}

int main(int argc, char **argv) {
    for (int i = 1; i < argc; i++) {
        char *end = NULL;
        long n = strtol(argv[i], &end, 10);
        if (end == argv[i] || *end != '\0') {
            printf("skipping invalid input: %s\n", argv[i]);
            continue;
        }
        int ok = 0;
        uint64_t r = fib_mod(n, &ok);
        if (ok)
            printf("fib(%ld) mod %llu = %llu\n", n, MOD, (unsigned long long)r);
        else
            printf("fib(%ld): negative input\n", n);
    }
    return 0;
}
```

The loop tracks only the last two values, so it runs in O(n) time and O(1) space and never overflows because each addition is reduced mod `1e9+7` before the next step. `fib(0)` returns 0 via the initial `a`, and negative inputs report an error instead of looping. Passing multiple arguments lets you test several values in one run.

