```cpp
#include <iostream>
#include <vector>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

Node* build(const std::vector<int>& vals) {
    Node* head = nullptr;
    Node** tail = &head;
    for (int v : vals) {
        *tail = new Node(v);
        tail = &(*tail)->next;
    }
    return head;
}

void print(Node* head) {
    for (Node* p = head; p; p = p->next) {
        std::cout << p->value;
        if (p->next) std::cout << " -> ";
    }
    std::cout << '\n';
}

void free_list(Node* head) {
    while (head) {
        Node* nxt = head->next;
        delete head;
        head = nxt;
    }
}

int main() {
    Node* a = build({1, 2, 3, 4, 5});
    print(a);
    a = reverse(a);
    print(a);
    free_list(a);

    Node* empty = build({});
    print(empty);            // prints an empty line
    empty = reverse(empty);
    print(empty);
    free_list(empty);
    return 0;
}
```

The iterative reversal relinks each node's `next` pointer in one pass, so an empty list simply returns `nullptr` and prints nothing.

