```python
import csv
import statistics
from pathlib import Path


def column_stats(path: str, column: str) -> dict:
    """Return {'count', 'mean', 'median'} for `column` in the CSV at `path`.

    Rows where the column is missing, empty, or non-numeric are skipped;
    if no valid values remain, means and medians are None.
    """
    values = []
    with Path(path).open(newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        if reader.fieldnames is None:
            return {"count": 0, "mean": None, "median": None}
        if column not in reader.fieldnames:
            raise KeyError(f"column {column!r} not in {reader.fieldnames}")
        for row in reader:
            raw = (row.get(column) or "").strip()
            if not raw:
                continue
            try:
                values.append(float(raw))
            except ValueError:
                continue

    if not values:
        return {"count": 0, "mean": None, "median": None}
    return {
        "count": len(values),
        "mean": statistics.mean(values),
        "median": statistics.median(values),
    }


if __name__ == "__main__":
    print(column_stats("data.csv", "amount"))
```

`DictReader` maps header names to cells, so a missing column is detected up front, and each row is parsed defensively so blank lines and text like `N/A` are skipped rather than crashing the run.

