    fn handles_empty_sides() {
        assert_eq!(merge_sorted::<i32>(&[], &[1, 2]), vec![1, 2]);
        assert_eq!(merge_sorted(&[1, 2], &[]), vec![1, 2]);
        assert!(merge_sorted::<i32>(&[], &[]).is_empty());
    }
}

fn main() {
