#include <iostream>
#include <stack>
#include <string>

bool is_balanced(const std::string& s) {
    std::stack<char> open;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                open.push(c);
                break;
            case ')': case ']': case '}': {
                if (open.empty()) return false;
                char m = open.top();
                open.pop();
                if ((c == ')' && m != '(') ||
                    (c == ']' && m != '[') ||
                    (c == '}' && m != '{')) {
                    return false;
                }
                break;
            }
            default:
                break;
        }
    }
    return open.empty();
}

int main() {
    std::string tests[] = {
        "(a[b]{c})", "([)]", "(()", "", "no brackets here", "{[()]}", "}"
    };
    for (const auto& t : tests) {
        std::cout << (t.empty() ? "<empty>" : t) << " -> "
                  << (is_balanced(t) ? "balanced" : "unbalanced") << '\n';
    }
    return 0;
}
