def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(lo: int, hi: int):
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end + 1]


if __name__ == "__main__":
    print(longest_palindrome("babad"))   # bab
    print(longest_palindrome("cbbd"))    # bb
    print(longest_palindrome(""))        # (empty)
    print(longest_palindrome("a"))       # a
    print(longest_palindrome("abba"))    # abba
```
`expand` grows outward around a center while characters match, then steps back one. You try both an odd center `(i, i)` and an even center `(i, i+1)`, keeping the widest span. Worst case is O(n²) time, O(1) extra space — note that using `>` (not `>=`) deliberately keeps the first-found longest on ties.

```cpp
#include <array>
#include <cstdint>
#include <iostream>

constexpr std::int64_t MOD = 1'000'000'007;

using Mat = std::array<std::array<std::int64_t, 2>, 2>;

Mat mul(const Mat& a, const Mat& b) {
    Mat c{ { {0, 0}, {0, 0} } };
    for (int i = 0; i < 2; ++i)
        for (int k = 0; k < 2; ++k)
            for (int j = 0; j < 2; ++j)
                c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % MOD;
    return c;
}

std::int64_t fib(std::int64_t n) {
    if (n < 0) throw std::invalid_argument("n must be >= 0");
    Mat result{ { {1, 0}, {0, 1} } };
    Mat base{ { {1, 1}, {1, 0} } };
    while (n > 0) {
        if (n & 1) result = mul(result, base);
        base = mul(base, base);
        n >>= 1;
    }
    return result[0][1];
}

int main() {
    std::cout << fib(0) << '\n';         // 0
    std::cout << fib(10) << '\n';        // 55
    std::cout << fib(1000000) << '\n';   // fast, mod 1e9+7
}
```
The transition matrix `[[1,1],[1,0]]` raised to the power `n` has Fibonacci numbers in row 0. Binary exponentiation makes it O(log n), and every multiply reduces mod `MOD`, so no overflow past `int64`. `fib(0)` correctly returns `0` because the identity matrix is returned with `result[0][1] == 0`.

