```cpp
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

std::vector<int> parse_ints(const std::string& line, std::size_t& parsed) {
    std::vector<int> out;
    std::istringstream ss(line);
    std::string field;
    while (std::getline(ss, field, ',')) {
        // Trim surrounding spaces.
        std::size_t b = field.find_first_not_of(" \t");
        std::size_t e = field.find_last_not_of(" \t");
        if (b == std::string::npos) continue;        // empty field
        std::string tok = field.substr(b, e - b + 1);
        try {
            std::size_t used = 0;
            int v = std::stoi(tok, &used);
            if (used != tok.size()) continue;        // trailing garbage
            out.push_back(v);
        } catch (const std::exception&) {
            // Non-numeric field: skip it.
        }
    }
    parsed = out.size();
    return out;
}

