```rust
/// Fixed-capacity ring buffer. Pushing when full overwrites the oldest item.
pub struct RingBuffer {
    data: Vec<Option<u32>>,
    head: usize, // next write index
    len: usize,  // number of live items
}

impl RingBuffer {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        RingBuffer {
            data: vec![None; capacity],
            head: 0,
            len: 0,
        }
    }

    pub fn push(&mut self, value: u32) {
        self.data[self.head] = Some(value);
        self.head = (self.head + 1) % self.data.len();
        if self.len < self.data.len() {
            self.len += 1;
        }
    }

    /// Oldest-first iteration.
    pub fn iter(&self) -> impl Iterator<Item = u32> + '_ {
        let cap = self.data.len();
        let start = (self.head + cap - self.len) % cap;
        (0..self.len).map(move |i| self.data[(start + i) % cap].unwrap())
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    rb.push(10);
    rb.push(20);
    rb.push(30);
    rb.push(40); // overwrites 10
    let got: Vec<u32> = rb.iter().collect();
    assert_eq!(got, vec![20, 30, 40]);
    println!("{:?}", got);
}
```

The write index wraps with `%`, and iteration starts at the oldest live slot computed from `head` and `len`, so overwrites never expose stale data.

```python
import threading


class Counter:
    """Thread-safe integer counter."""

    def __init__(self, start=0):
        self._value = start
        self._lock = threading.Lock()

    def increment(self, by=1):
        with self._lock:
            self._value += by
            return self._value

    @property
    def value(self):
        with self._lock:
            return self._value

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        with self._lock:
            self._value = 0
        return False


def worker(counter, n):
    for _ in range(n):
        counter.increment()


if __name__ == "__main__":
    c = Counter()
    threads = [threading.Thread(target=worker, args=(c, 10_000)) for _ in range(4)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert c.value == 40_000, c.value
    with c:
        pass
    assert c.value == 0
    print("ok")
```

Every read and write takes the same lock, so the interleaving of four threads cannot lose an increment; the test asserts the full count.

