from collections import OrderedDict


class LRUCache:
    """Least-recently-used cache with a fixed capacity."""

    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)  # mark as most recent
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict oldest

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1        # a is now most recent
    c.put("c", 3)                 # evicts b
    assert c.get("b") is None
    assert c.get("a") == 1
    assert len(c) == 2
    print("ok")
```

`move_to_end` makes reads count as recency, and `popitem(last=False)` removes the least recently used entry only when capacity is exceeded.

```cpp
#include <iostream>
#include <stack>
#include <string>

bool balanced(const std::string& s, std::size_t& bad_index) {
    std::stack<char> st;
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            char want = (c == ')') ? '(' : (c == ']') ? '[' : '{';
            if (st.empty() || st.top() != want) {
                bad_index = i;
                return false;
            }
            st.pop();
        }
    }
    if (!st.empty()) {
        bad_index = s.size(); // unclosed opener
        return false;
    }
    return true;
}

int main() {
    std::size_t at = 0;
    std::cout << balanced("{[()]}", at) << '\n';       // 1
    std::cout << balanced("([)]", at) << " at " << at << '\n';   // 0 at 3
    std::cout << balanced("(((", at) << " at " << at << '\n';    // 0 at 3
    std::cout << balanced("", at) << '\n';              // 1
    return 0;
}
```

`bad_index` points at the offending closer, or at `size()` when an opener is left unclosed. Characters other than brackets are ignored.

