#include <errno.h>
#include <limits.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

bool parse_int(const char *text, int *out) {
    if (text == NULL || out == NULL || *text == '\0') {
        return false;
    }
    char *end = NULL;
    errno = 0;
    long value = strtol(text, &end, 10);
    if (errno == ERANGE || value < INT_MIN || value > INT_MAX) {
        return false;              /* overflow on this platform */
    }
    if (end == text || *end != '\0') {
        return false;              /* no digits, or trailing garbage */
    }
    *out = (int)value;
    return true;
}

int main(void) {
    int v;
    printf("%d\n", parse_int("  -42", &v) ? v : -999);
    printf("%d\n", parse_int("999999999999", &v));   /* 0: overflow */
    printf("%d\n", parse_int("12abc", &v));          /* 0: garbage */
    printf("%d\n", parse_int("", &v));               /* 0: empty */
    return 0;
}
```

The `errno == ERANGE` check catches values beyond `long` on the platform, and the explicit `INT_MIN..INT_MAX` range guards the narrowing cast on 32-bit `int`. Leading whitespace is intentionally accepted because that is `strtol` semantics; everything after the number must be `\0`.

