#include <algorithm>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
double median(std::vector<T>& data) {
    if (data.empty()) {
        throw std::invalid_argument("median of empty vector is undefined");
    }
    const std::size_t mid = data.size() / 2;
    std::nth_element(data.begin(), data.begin() + mid, data.end());
    const T upper = data[mid];
    if (data.size() % 2 == 1) {
        return static_cast<double>(upper);
    }
    // For even size, the lower middle is the max of the left half.
    const T lower = *std::max_element(data.begin(), data.begin() + mid);
    return (static_cast<double>(lower) + static_cast<double>(upper)) / 2.0;
}

int main() {
    std::vector<int> odd{7, 1, 3, 9, 5};
    std::vector<int> even{8, 2, 6, 4};
    std::cout << median(odd) << '\n';    // 5
    std::cout << median(even) << '\n';   // 5
    return 0;
}
```

`nth_element` is O(n) average instead of O(n log n), and it reorders `data` in place — callers who need the original order should pass a copy or a separate index vector. For even sizes we take the max of the lower half rather than calling `nth_element` twice, so the worst case stays linear.

