def two_sum(nums, target):
    """Return (i, j) with nums[i] + nums[j] == target, or None.

    Single pass with a hash map: O(n) time, O(n) space.
    """
    seen = {}
    for i, value in enumerate(nums):
        need = target - value
        if need in seen:
            return (seen[need], i)
        seen[value] = i
    return None


