REQUIRED = {"name", "version"}
ALLOWED = {"name", "version", "debug", "timeout", "tags"}
DEFAULTS: dict[str, Any] = {"debug": False, "timeout": 30, "tags": []}


def normalize(raw: dict[str, Any]) -> dict[str, Any]:
