#include <iostream>
#include <cstdlib>
#include <cstdint>

long long gcd(long long a, long long b) {
    a = std::llabs(a);
    b = std::llabs(b);
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

// Compile-time variant for non-negative integral constants.
template <uint64_t A, uint64_t B>
struct gcd_const {
    static constexpr uint64_t value = gcd_const<B, A % B>::value;
};

template <uint64_t A>
struct gcd_const<A, 0> {
    static constexpr uint64_t value = A;
};

int main() {
