```cpp
#include <cassert>
#include <iostream>
#include <string>

// Reverse all words in `s` in place. Runs of whitespace collapse to a
// single space and leading/trailing whitespace is dropped.
std::string reverse_words(const std::string& s) {
    std::string out;
    out.reserve(s.size());

    std::size_t i = s.size();
    while (i > 0) {
        // Skip trailing whitespace of the current word.
        while (i > 0 && std::isspace(static_cast<unsigned char>(s[i - 1]))) {
            --i;
        }
        if (i == 0) break;

        std::size_t j = i;
        while (j > 0 && !std::isspace(static_cast<unsigned char>(s[j - 1]))) {
            --j;
        }
        if (!out.empty()) out.push_back(' ');
        out.append(s, j, i - j);
        i = j;
    }
    return out;
}

int main() {
    assert(reverse_words("the sky is blue") == "blue is sky the");
    assert(reverse_words("  hello   world  ") == "world hello");
    assert(reverse_words("") == "");
    assert(reverse_words("single") == "single");
    assert(reverse_words("   ") == "");
    std::cout << "all checks passed\n";
    return 0;
}
```

Scanning from the end lets each word be located and appended in one pass without a second buffer of word offsets.

