#include <cassert>
#include <iostream>
#include <stack>
#include <string>

bool is_balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.empty();
}

int main() {
    assert(is_balanced(""));
    assert(is_balanced("()[]{}"));
    assert(is_balanced("a(b[c]{d})e"));
    assert(!is_balanced("(]"));
    assert(!is_balanced("([)]"));
    assert(!is_balanced("("));
    assert(!is_balanced(")"));
    assert(is_balanced("{[()]}"));
    std::cout << "all checks passed\n";
    return 0;
}
```

