use std::collections::HashMap;

/// Count words case-insensitively and return the `n` most frequent,
/// sorted by descending count then ascending word.
fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if cleaned.is_empty() {
            continue;
        }
        *counts.entry(cleaned).or_insert(0) += 1;
    }

    let mut entries: Vec<(String, usize)> = counts.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    entries.truncate(n);
    entries
}

fn main() {
    let text = "The quick brown fox. The FOX! the dog.";
    let got = top_words(text, 2);
    assert_eq!(got, vec![("the".to_string(), 3), ("fox".to_string(), 2)]);
    assert!(top_words("", 5).is_empty());
    assert!(top_words("!!!", 5).is_empty());
    println!("all checks passed");
}
