```rust
use std::collections::HashMap;
use std::fmt;

#[derive(Debug, PartialEq)]
pub struct ParseError {
    pub token: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "malformed token: {:?}", self.token)
    }
}

pub fn parse_pairs(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Ok(map);
    }
    for token in trimmed.split(';') {
        let token = token.trim();
        if token.is_empty() {
            continue;
        }
        let (key, value) = match token.split_once('=') {
            Some(kv) => kv,
            None => return Err(ParseError { token: token.to_string() }),
        };
        let key = key.trim();
        if key.is_empty() {
            return Err(ParseError { token: token.to_string() });
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let m = parse_pairs("a=1; b = 2 ;c=").unwrap();
    assert_eq!(m.get("a").map(String::as_str), Some("1"));
    assert_eq!(m.get("c").map(String::as_str), Some(""));
    assert!(parse_pairs("").unwrap().is_empty());
    assert!(parse_pairs("abc").is_err());
    assert!(parse_pairs("=1").is_err());
    println!("all checks passed");
}
```

Using `split_once('=')` keeps `a=b=c` valid (value `b=c`), and empty segments from trailing semicolons are skipped rather than rejected.

