#include <array>
#include <cstddef>
#include <optional>
#include <iostream>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << "\n";
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << "\n";
    std::cout << rb.push(9) << " size=" << rb.size() << "\n";
    return 0;
}
```

