#include <algorithm>
#include <iostream>
#include <string>

void reverse_words(std::string& s) {
    std::reverse(s.begin(), s.end());
    std::size_t start = 0;
    while (start < s.size()) {
        std::size_t end = s.find(' ', start);
        if (end == std::string::npos) end = s.size();
        std::reverse(s.begin() + static_cast<long>(start),
                     s.begin() + static_cast<long>(end));
        start = end + 1;
    }
}

int main() {
    std::string s = "the quick brown fox";
    reverse_words(s);
    std::cout << s << "\n";
    std::string empty;
    reverse_words(empty);
    std::cout << "[" << empty << "]\n";
    std::string one = "word";
    reverse_words(one);
    std::cout << one << "\n";
}
