#[derive(Debug, PartialEq)]
enum List {
    Cons(i32, Box<List>),
    Nil,
}

fn reverse(list: List) -> List {
    let mut prev = List::Nil;
    let mut current = list;
    while let List::Cons(value, next) = current {
        current = *next;
        prev = List::Cons(value, Box::new(prev));
    }
    prev
}

fn from_slice(values: &[i32]) -> List {
    values.iter().rev().fold(List::Nil, |acc, &v| List::Cons(v, Box::new(acc)))
}

fn main() {
    assert_eq!(reverse(from_slice(&[1, 2, 3])), from_slice(&[3, 2, 1]));
    assert_eq!(reverse(List::Nil), List::Nil);
    assert_eq!(reverse(from_slice(&[7])), from_slice(&[7]));
    println!("ok");
}
