```cpp
#include <cstdint>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int64_t> low;                                  // max-heap
    std::priority_queue<int64_t, std::vector<int64_t>, std::greater<>> high; // min-heap
    int64_t x;
    uint64_t n = 0;

    while (std::cin >> x) {
        ++n;
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);

        // Keep sizes balanced: low may have at most one more element.
        if (low.size() > high.size() + 1) { high.push(low.top()); low.pop(); }
        else if (high.size() > low.size())  { low.push(high.top()); high.pop(); }
    }

    if (n == 0) { std::cout << "count=0 median=n/a\n"; return 0; }

    std::cout << "count=" << n << " median=";
    if (low.size() == high.size()) {
        // Average the two middles as a double.
        std::cout << (static_cast<double>(low.top()) + high.top()) / 2.0;
    } else {
        std::cout << low.top();
    }
    std::cout << '\n';
}
```

Two heaps keep the lower half in a max-heap and the upper half in a min-heap. Rebalancing after each insert keeps the median at the top of one of them, and reading until `std::cin >> x` fails handles EOF cleanly. Empty input is reported explicitly instead of dividing by zero.

