    assert_eq!(parse_line("no_delimiter"), Err(ParseError::MissingDelimiter));
    assert_eq!(parse_line("=v"), Err(ParseError::EmptyKey));
    assert_eq!(parse_line("ключ=значение").unwrap().key, "ключ");
