#include <stddef.h>
#include <stdio.h>
#include <string.h>

size_t longest_run(const char *s) {
    if (s == NULL || *s == '\0') return 0;

    size_t best = 1, cur = 1;
    for (const char *p = s + 1; *p != '\0'; ++p) {
        if (*p == *(p - 1)) {
            ++cur;
        } else {
            cur = 1;
        }
        if (cur > best) best = cur;
    }
    return best;
}

int main(void) {
    struct { const char *in; size_t want; } cases[] = {
        { "aabbbcc", 3 },
        { "abc", 1 },
        { "", 0 },
        { "zzzz", 4 },
        { "aabbaa", 2 },
        { "  \t\t\t", 3 },
    };
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; ++i) {
        size_t got = longest_run(cases[i].in);
        if (got != cases[i].want) {
            fprintf(stderr, "fail: \"%s\" got %zu want %zu\n",
                    cases[i].in, got, cases[i].want);
            return 1;
        }
