```python
from typing import Iterable, Iterator, Optional


class RingBuffer:
    """Fixed-capacity buffer; new writes overwrite the oldest element."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._cap = capacity
        self._data: list[Optional[object]] = [None] * capacity
        self._start = 0
        self._size = 0

    def append(self, item: object) -> None:
        idx = (self._start + self._size) % self._cap
        self._data[idx] = item
        if self._size < self._cap:
            self._size += 1
        else:
            self._start = (self._start + 1) % self._cap  # drop oldest

    def __len__(self) -> int:
        return self._size

    def __iter__(self) -> Iterator[object]:
        for i in range(self._size):
            yield self._data[(self._start + i) % self._cap]

    def __getitem__(self, i: int) -> object:
        if not -self._size <= i < self._size:
            raise IndexError("ring buffer index out of range")
        if i < 0:
            i += self._size
        return self._data[(self._start + i) % self._cap]


if __name__ == "__main__":
    rb = RingBuffer(3)
    for v in (1, 2):
        rb.append(v)
    assert list(rb) == [1, 2]
    rb.append(3)
    rb.append(4)          # overwrites 1
    assert list(rb) == [2, 3, 4]
    assert rb[0] == 2 and rb[-1] == 4
    assert len(rb) == 3
    print("ok")
```

The `(start + size) % cap` write index keeps appends `O(1)` with no shifting. Once full, advancing `start` discards the oldest slot; nothing is ever reallocated.

