#include <algorithm>
#include <cstddef>
#include <iostream>
#include <vector>

// Returns the index of the first element not less than `value`.
// Works for sorted ranges; duplicates resolve to the leftmost match.
template <typename T>
size_t lower_bound_index(const std::vector<T>& v, const T& value) {
    size_t lo = 0, hi = v.size();
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;  // no overflow vs (lo+hi)/2
        if (v[mid] < value) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

int main() {
    std::vector<int> v{1, 3, 3, 5, 8};

    if (lower_bound_index(v, 3) != 1) return 1;   // leftmost duplicate
    if (lower_bound_index(v, 0) != 0) return 1;   // before start
    if (lower_bound_index(v, 9) != 5) return 1;   // past end -> insertion point
    if (lower_bound_index(v, 5) != 3) return 1;

    std::vector<int> empty;
    if (lower_bound_index(empty, 7) != 0) return 1;

    std::cout << "ok\n";
}
