```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static int is_space(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}

int main(void) {
    char *line = NULL;
    size_t cap = 0;
    if (getline(&line, &cap, stdin) < 0) {
        free(line);
        return 0;
    }

    size_t n = strlen(line);
    /* collect word boundaries */
    size_t start[4096], len[4096];
    size_t count = 0;
    size_t i = 0;
    while (i < n) {
        while (i < n && is_space(line[i])) i++;
        if (i >= n) break;
        size_t s = i;
        while (i < n && !is_space(line[i])) i++;
        if (count < 4096) {
            start[count] = s;
            len[count] = i - s;
            count++;
        }
    }

    for (size_t k = count; k > 0; k--) {
        fwrite(line + start[k - 1], 1, len[k - 1], stdout);
        if (k > 1) putchar(' ');
    }
    putchar('\n');
    free(line);
    return 0;
}
```

Splits on spaces, tabs and newline, records each word's start and length, then emits them in reverse order joined by single spaces. The fixed 4096-word cap keeps it allocation-free; extend with a dynamic array if you expect longer input.

