```cpp
#include <iostream>
#include <string>
#include <stack>

static bool matches(char open, char close) {
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

bool balanced(const std::string& s) {
    std::stack<char> st;
    char quote = 0;
    bool escaped = false;

    for (char c : s) {
        if (quote != 0) {
            if (escaped) {
                escaped = false;
            } else if (c == '\\') {
                escaped = true;
            } else if (c == quote) {
                quote = 0;
            }
            continue;
        }
        if (c == '"' || c == '\'') {
            quote = c;
            continue;
        }
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty() || !matches(st.top(), c)) return false;
            st.pop();
        }
    }
    return quote == 0 && st.empty();
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::cout << (balanced(line) ? "true" : "false") << '\n';
    }
    return 0;
}
```

