```c
#include <stdio.h>
#include <stdint.h>

uint32_t rotl32(uint32_t value, unsigned k) {
    k %= 32u;
    if (k == 0u) return value;
    return (value << k) | (value >> (32u - k));
}

int main(void) {
    uint32_t samples[] = {0x80000001u, 0x00000001u, 0xFFFFFFFFu, 0x12345678u};
    unsigned shifts[] = {0, 1, 4, 32, 33};

    for (size_t i = 0; i < sizeof(samples) / sizeof(samples[0]); i++) {
        for (size_t j = 0; j < sizeof(shifts) / sizeof(shifts[0]); j++) {
            printf("rotl32(0x%08X, %u) = 0x%08X\n",
                   samples[i], shifts[j], rotl32(samples[i], shifts[j]));
        }
    }
    return 0;
}
```

Reducing `k` modulo 32 avoids undefined behaviour from shifting by 32 or more, and the `k == 0` early return avoids a shift by 32 on the right side. Output is printed as zero-padded hex for easy inspection.

```rust
fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();

    // Keep the shorter string as the column set to bound memory.
    let (rows, cols) = if a.len() >= b.len() { (a, b) } else { (b, a) };

    let mut prev: Vec<usize> = (0..=cols.len()).collect();
    let mut curr: Vec<usize> = vec![0; cols.len() + 1];

    for i in 1..=rows.len() {
        curr[0] = i;
        for j in 1..=cols.len() {
            let cost = if rows[i - 1] == cols[j - 1] { 0 } else { 1 };
            curr[j] = (prev[j] + 1)
                .min(curr[j - 1] + 1)
                .min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut curr);
    }

    prev[cols.len()]
}

fn main() {
    assert_eq!(levenshtein("kitten", "sitting"), 3);
    assert_eq!(levenshtein("", "abc"), 3);
    assert_eq!(levenshtein("abc", ""), 3);
    assert_eq!(levenshtein("café", "cafe"), 1);
    println!("ok");
}
```

Collects `chars()` so multi-byte Unicode scalars count as one unit, swaps the strings so the column vector is the shorter one, and rolls two rows instead of a full matrix. The `café`/`cafe` case yields 1 because the accented character is a single scalar and substitutes for `e`.

```cpp
#include <iostream>
#include <vector>
#include <stdexcept>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), count_(0), capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(int value) {
        std::size_t tail = (head_ + count_) % capacity_;
        buf_[tail] = value;
        if (count_ < capacity_) {
            ++count_;
        } else {
            head_ = (head_ + 1) % capacity_;
        }
    }

    int pop() {
        if (count_ == 0) throw std::underflow_error("pop from empty buffer");
        int value = buf_[head_];
        head_ = (head_ + 1) % capacity_;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }

private:
    std::vector<int> buf_;
    std::size_t head_;
    std::size_t count_;
    std::size_t capacity_;
};

int main() {
    RingBuffer rb(3);
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4);               // overwrites 1
    std::cout << rb.size() << '\n';   // 3
    while (!rb.empty()) std::cout << rb.pop() << ' ';  // 2 3 4
    std::cout << '\n';
    return 0;
}
```

Uses an index-plus-count model instead of a head/tail pair: `head_` is the oldest slot and `count_` disambiguates empty from full. When full, push advances `head_` so the oldest value is dropped before the new one lands.

