struct ParseResult {
    std::vector<int> values;
    std::vector<std::string> errors;  // malformed tokens, in order
};

static std::string_view trim(std::string_view s) {
    while (!s.empty() && std::isspace(static_cast<unsigned char>(s.front()))) s.remove_prefix(1);
    while (!s.empty() && std::isspace(static_cast<unsigned char>(s.back())))  s.remove_suffix(1);
    return s;
}

ParseResult parse_int_list(std::string_view input) {
    ParseResult out;
    size_t start = 0;
    while (start <= input.size()) {
        size_t comma = input.find(',', start);
        std::string_view token = input.substr(start, comma == std::string_view::npos
                                                        ? std::string_view::npos
                                                        : comma - start);
        token = trim(token);
        if (!token.empty()) {
            int value = 0;
            auto [ptr, ec] = std::from_chars(token.data(), token.data() + token.size(), value);
            if (ec == std::errc() && ptr == token.data() + token.size()) {
                out.values.push_back(value);
            } else {
                out.errors.emplace_back(token);
            }
        }
        if (comma == std::string_view::npos) break;
        start = comma + 1;
    }
    return out;
}

int main() {
    auto r1 = parse_int_list("1, 2 ,3,4");
    std::cout << r1.values.size() << " values, " << r1.errors.size() << " errors\n";

    auto r2 = parse_int_list("7,abc,9,,10");
    for (int v : r2.values) std::cout << v << ' ';
    std::cout << "| bad: ";
    for (const auto& e : r2.errors) std::cout << e << ' ';
    std::cout << '\n';
}
```

Empty fields and surrounding whitespace are skipped; `abc` and out-of-range numbers are reported in `errors` rather than silently coerced. `std::from_chars` avoids locale surprises and rejects trailing junk via the `ptr` check.

```cpp
#include <algorithm>
#include <iostream>
#include <vector>

// Strictly increasing LIS length: tails[i] is the smallest tail of any
// increasing subsequence of length i+1 seen so far.
int lis_length(const std::vector<int>& nums) {
    std::vector<int> tails;
    tails.reserve(nums.size());
    for (int x : nums) {
        auto it = std::lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) {
            tails.push_back(x);
        } else {
            *it = x;
        }
    }
    return static_cast<int>(tails.size());
}

int main() {
    std::vector<std::vector<int>> cases = {
        {10, 9, 2, 5, 3, 7, 101, 18},  // 4
        {},                             // 0
        {7},                            // 1
        {3, 3, 3, 3},                   // 1 (strict)
        {5, 4, 3, 2, 1},                // 1
        {1, 2, 3, 4, 5},                // 5
    };
    for (const auto& c : cases) {
        std::cout << lis_length(c) << '\n';
    }
}
```

`lower_bound` finds the first tail >= `x`, giving strict increase; using `upper_bound` would allow equal values. Each element does one binary search, so the total is O(n log n). Empty input returns 0 naturally.

