use std::collections::HashMap;

/// Count whitespace-separated words (lowercased, punctuation stripped from
/// the ends) and return the `limit` most frequent as (word, count), sorted
/// by descending count then alphabetically.
pub fn top_words(text: &str, limit: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();

    for raw in text.split_whitespace() {
        let word: String = raw
            .trim_matches(|c: char| !c.is_alphanumeric() && c != '\'')
            .to_lowercase();
        if word.is_empty() {
            continue;
        }
        *counts.entry(word).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(limit);
    pairs
}

fn main() {
    let text = "The cat sat on the mat, the CAT!";
    let top = top_words(text, 3);
    assert_eq!(top, vec![
        ("the".to_string(), 3),
        ("cat".to_string(), 2),
        ("mat".to_string(), 1),
    ]);

    assert!(top_words("", 5).is_empty());
    assert!(top_words("!!!", 5).is_empty());
    assert_eq!(top_words("a b c", 0).len(), 0);
    assert_eq!(top_words("don't don't don't", 1),
               vec![("don't".to_string(), 3)]);
    println!("all cases passed");
}
