```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Encoded format: a run is count byte (1..255) followed by the byte value.
 * count==255 means "255 of value" (no continuation; encoded size grows
 * but is always well-defined). Returns malloc'd buffer via *out. */
static unsigned char *rle_encode(const unsigned char *in, size_t n, size_t *out_len) {
    unsigned char *out = malloc(n * 2 + 1);
    if (!out) return NULL;
    size_t o = 0;
    for (size_t i = 0; i < n; ) {
        size_t run = 1;
        while (i + run < n && in[i + run] == in[i] && run < 255) run++;
        out[o++] = (unsigned char)run;
        out[o++] = in[i];
        i += run;
    }
    *out_len = o;
    return out;
}

static unsigned char *rle_decode(const unsigned char *in, size_t n, size_t *out_len) {
    if (n % 2 != 0) return NULL; /* corrupt */
    size_t cap = 0;
    for (size_t i = 0; i < n; i += 2) cap += in[i];
    unsigned char *out = malloc(cap ? cap : 1);
    if (!out) return NULL;
    size_t o = 0;
    for (size_t i = 0; i < n; i += 2) {
        for (unsigned char k = 0; k < in[i]; k++) out[o++] = in[i + 1];
    }
    *out_len = o;
    return out;
}

int main(void) {
    unsigned char src[] = {0x41, 0x41, 0x41, 0x00, 0x00, 0x42, 0xFF, 0xFF, 0xFF, 0xFF};
    size_t src_len = sizeof(src) / sizeof(src[0]);

    size_t enc_len = 0;
    unsigned char *enc = rle_encode(src, src_len, &enc_len);
    if (!enc) { fprintf(stderr, "encode failed\n"); return 1; }

    size_t dec_len = 0;
    unsigned char *dec = rle_decode(enc, enc_len, &dec_len);
    if (!dec) { fprintf(stderr, "decode failed\n"); free(enc); return 1; }

    int ok = (dec_len == src_len) && memcmp(dec, src, src_len) == 0;
    printf("encoded %zu -> %zu bytes, roundtrip: %s\n",
           src_len, enc_len, ok ? "ok" : "FAILED");

    free(enc);
    free(dec);
    return ok ? 0 : 1;
}
```

Runs are capped at 255 so the count fits one byte; longer spans are split into multiple pairs. `rle_encode` allocates `2n+1` bytes which always suffices for the worst case of no runs. `rle_decode` rejects odd-length input as corrupt and sizes its buffer by summing the counts exactly.

