def fib(n: int) -> int:
    """Return the n-th Fibonacci number (F(0)=0, F(1)=1) via fast doubling."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def _pair(k: int):
        if k == 0:
            return (0, 1)
        a, b = _pair(k >> 1)
        c = a * ((b << 1) - a)
        d = a * a + b * b
        return (d, c + d) if k & 1 else (c, d)

    return _pair(n)[0]


