// Returns true if s is a palindrome once case and punctuation are removed.
bool is_palindrome(const std::string& s) {
    std::size_t left = 0;
    std::size_t right = s.size();

    while (left < right) {
        unsigned char lc = static_cast<unsigned char>(s[left]);
        unsigned char rc = static_cast<unsigned char>(s[right - 1]);

        if (!std::isalnum(lc)) {
            ++left;
            continue;
        }
        if (!std::isalnum(rc)) {
            --right;
            continue;
        }
        if (std::tolower(lc) != std::tolower(rc)) {
            return false;
        }
        ++left;
        --right;
    }
    return true;
}

int main() {
    const char* cases[] = {
        "A man, a plan, a canal: Panama",
        "race a car",
        "",
        "Madam",
        "No 'x' in Nixon",
        "12321",
        "12345"
    };
    for (const char* c : cases) {
        bool pal = is_palindrome(std::string(c));
        std::cout << '"' << c << "\" -> " << (pal ? "true" : "false") << '\n';
    }
    // Sanity checks for the known cases.
    if (!is_palindrome("A man, a plan, a canal: Panama")) return 1;
    if (is_palindrome("hello")) return 1;
    return 0;
}
