use std::collections::HashMap;

// Iterative: O(n) time, O(1) space.
fn fib_iter(n: u64) -> u128 {
    let mut a: u128 = 0;
    let mut b: u128 = 1;
    for _ in 0..n {
        let next = a + b;
        a = b;
        b = next;
    }
    a
}

// Memoized recursion: O(n) time, O(n) space.
fn fib_rec(n: u64, memo: &mut HashMap<u64, u128>) -> u128 {
    if n < 2 {
        return n as u128;
    }
    if let Some(&v) = memo.get(&n) {
        return v;
    }
    let v = fib_rec(n - 1, memo) + fib_rec(n - 2, memo);
    memo.insert(n, v);
    v
}

fn main() {
    let n = 30;
    let mut memo = HashMap::new();
    for i in 0..=n {
        let it = fib_iter(i);
        let rc = fib_rec(i, &mut memo);
        assert_eq!(it, rc, "mismatch at n={}", i);
    }
    println!("fib({}) = {}", n, fib_iter(n));
    // Edge cases.
    assert_eq!(fib_iter(0), 0);
    assert_eq!(fib_iter(1), 1);
    assert_eq!(fib_iter(2), 1);
    println!("all checks passed");
}
