// Merge two sorted slices into a single sorted Vec.
// Pre-allocates exactly the needed capacity to avoid reallocation.
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    // Append whatever remains from the side that was not exhausted.
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 3]), vec![1, 1, 1, 2, 3]);
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 2, 3], &[]), vec![1, 2, 3]);
    assert_eq!(merge_sorted(&[], &[4i32]), vec![4]);

    let words = merge_sorted(
        &[String::from("apple"), String::from("cherry")],
        &[String::from("banana")],
    );
    println!("{:?}", words);
    println!("all assertions passed");
}
