#include <cassert>
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

// Fixed-capacity FIFO ring buffer. Overwrites the oldest element when full.
template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), size_(0), capacity_(capacity) {
        assert(capacity > 0 && "capacity must be positive");
    }

    // Push a value; when full, drops the oldest entry.
    void push(const T& value) {
        std::size_t tail = (head_ + size_) % capacity_;
        buf_[tail] = value;
        if (size_ == capacity_) {
            head_ = (head_ + 1) % capacity_;
        } else {
            ++size_;
        }
    }

    // Pop the oldest value, or nothing if empty.
    std::optional<T> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        T value = buf_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::vector<T> buf_;
    std::size_t head_;
    std::size_t size_;
    std::size_t capacity_;
};

int main() {
    RingBuffer<int> rb(3);
    assert(rb.empty());
    assert(!rb.pop().has_value());

    rb.push(1);
    rb.push(2);
    rb.push(3);
    assert(rb.size() == 3);

    rb.push(4);  // overwrites 1
    assert(rb.size() == 3);
    assert(rb.pop() == 2);
    assert(rb.pop() == 3);
    assert(rb.pop() == 4);
    assert(rb.empty());

    std::cout << "all ring buffer checks passed\n";
    return 0;
}
