import csv
import sys

def validate_csv(path: str) -> list[str]:
    """Return a list of human-readable problems; empty list means valid."""
    errors: list[str] = []
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.reader(fh)
        try:
            header = next(reader)
        except StopIteration:
            return ["file is empty"]

        if header is None or not header:
            return ["missing header row"]

        expected = len(header)
        for line_no, row in enumerate(reader, start=2):
            if not row:
                errors.append(f"line {line_no}: blank row")
                continue
            if len(row) != expected:
                errors.append(
                    f"line {line_no}: expected {expected} fields, got {len(row)}"
                )
            for col, value in enumerate(row, start=1):
                if value.strip() == "":
                    errors.append(
                        f"line {line_no}: field {col} ({header[col - 1]!r}) is empty"
                    )
    return errors


def main() -> int:
    if len(sys.argv) != 2:
        print("usage: validate_csv.py FILE.csv", file=sys.stderr)
        return 2
    problems = validate_csv(sys.argv[1])
    if not problems:
        print("valid")
        return 0
    for problem in problems:
        print(problem, file=sys.stderr)
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
```

Usage: `python validate_csv.py data.csv`. Exit status is 0 for a valid file and 1 when problems are found, so it works fine in CI. It handles empty files, blank rows, ragged rows, and empty fields.

