import re


def luhn_ok(number: str) -> bool:
    digits = [int(c) for c in number if c.isdigit()]
    if len(digits) < 12:
        return False
    total = 0
    for i, d in enumerate(reversed(digits)):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0


ISSUERS = [
    (r"^4\d{12}(\d{3})?(\d{3})?$", "Visa"),
    (r"^5[1-5]\d{14}$", "Mastercard"),
    (r"^3[47]\d{13}$", "Amex"),
    (r"^6(?:011|5\d{2})\d{12}$", "Discover"),
]


def classify(raw: str):
    digits = re.sub(r"\D", "", raw)
    if not luhn_ok(digits):
        return "invalid", digits
    for pattern, name in ISSUERS:
        if re.match(pattern, digits):
            return name, digits
    return "unknown", digits


if __name__ == "__main__":
    print(classify("4111 1111 1111 1111"))  # ('Visa', ...)
    print(classify("378282246310005"))        # ('Amex', ...)
    print(classify("1234"))                   # ('invalid', '1234')
```
