std::vector<int> merge_k_sorted(const std::vector<std::vector<int>>& lists) {
    using T = std::tuple<int, std::size_t, std::size_t>; // value, list, index
    std::priority_queue<T, std::vector<T>, std::greater<T>> pq;
    for (std::size_t i = 0; i < lists.size(); ++i) {
        if (!lists[i].empty()) pq.emplace(lists[i][0], i, 0);
    }
    std::vector<int> out;
    while (!pq.empty()) {
        auto [val, li, idx] = pq.top();
        pq.pop();
        out.push_back(val);
        if (idx + 1 < lists[li].size())
            pq.emplace(lists[li][idx + 1], li, idx + 1);
    }
    return out;
}
