pub fn is_balanced(input: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for c in input.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let open = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(open) {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    assert!(is_balanced("a(b[c]{d})e"));
    assert!(!is_balanced("([)]"));
    assert!(is_balanced(""));
    assert!(is_balanced("café(naïve)"));
    println!("ok");
}
