template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<int> pop() {
        if (count_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << '\n';
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n';
    return 0;
}
