#include <cstdint>
#include <iostream>
#include <numeric>
#include <stdexcept>

std::int64_t gcd(std::int64_t a, std::int64_t b) {
    a = a < 0 ? -a : a;
    b = b < 0 ? -b : b;
    while (b != 0) {
        std::int64_t t = a % b;
        a = b;
        b = t;
    }
    return a;
}

bool lcm(std::int64_t a, std::int64_t b, std::int64_t &out) {
    a = a < 0 ? -a : a;
    b = b < 0 ? -b : b;
    if (a == 0 || b == 0) {
        out = 0;
        return true;
    }
    std::int64_t g = gcd(a, b);
    std::int64_t reduced = a / g;
    if (reduced > INT64_MAX / b) return false;  // would overflow
    out = reduced * b;
    return true;
}

int main() {
    std::int64_t r;
    if (!lcm(21, 6, r)) return 1;
    std::cout << "gcd=" << gcd(21, 6) << " lcm=" << r << '\n';
    if (lcm(0, 5, r)) std::cout << "lcm(0,5)=" << r << '\n';
    if (!lcm(INT64_MAX, 2, r)) std::cout << "overflow detected\n";
    return 0;
}
