bool is_palindrome(const std::string& s) {
    size_t i = 0, j = s.size();
    while (i < j) {
        if (!std::isalnum(static_cast<unsigned char>(s[i]))) { ++i; continue; }
        if (!std::isalnum(static_cast<unsigned char>(s[j - 1]))) { --j; continue; }
