```c
#include <stdio.h>
#include <string.h>

static void reverse_range(char *a, char *b) {
    while (a < b) {
        char t = *a;
        *a++ = *b;
        *b-- = t;
    }
}

static void reverse_words(char *s) {
    size_t n = strlen(s);
    if (n == 0) return;

    /* Reverse the whole string. */
    reverse_range(s, s + n - 1);

    /* Reverse each word back into order. */
    char *start = s;
    for (char *p = s; ; ++p) {
        if (*p == ' ' || *p == '\0') {
            if (p > start) reverse_range(start, p - 1);
            if (*p == '\0') break;
            start = p + 1;
        }
    }
}

int main(void) {
    char buf[256];
    while (fgets(buf, sizeof buf, stdin)) {
        size_t len = strlen(buf);
        while (len > 0 && (buf[len - 1] == '\n' || buf[len - 1] == '\r'))
            buf[--len] = '\0';
        reverse_words(buf);
        puts(buf);
    }
    return 0;
}
```

Two reversals: flip the entire buffer, then flip each word individually. Input `the quick brown fox` prints `fox brown quick the`. The `while (len > 0 && ...)` loop strips trailing newlines so `fgets` lines don't leave stray `\r` inside the reversed words. Empty input is handled by the `n == 0` early return.

```cpp
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;                             // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap

    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) {
            low.push(x);
        } else {
            high.push(x);
        }

        // Rebalance so |low.size() - high.size()| <= 1.
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        double median = (low.size() == high.size())
                            ? (low.top() + high.top()) / 2.0
                            : static_cast<double>(low.top());
        std::cout << median << '\n';
    }
    return 0;
}
```

The max-heap `low` holds the smaller half and the min-heap `high` the larger half. After each push the heaps are rebalanced so sizes differ by at most one, which keeps `low.top()` (or the average of both tops) the median. With input `1 2 3`, the output is `1`, `1.5`, `2`. EOF is the loop terminator, so no sentinel value is needed.

```rust
fn dedup_sorted(nums: &mut Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }
    let mut write = 1usize;
    for read in 1..nums.len() {
        if nums[read] != nums[write - 1] {
            nums[write] = nums[read];
            write += 1;
        }
    }
    nums.truncate(write);
    write
}

fn main() {
    let mut empty: Vec<i32> = Vec::new();
    assert_eq!(dedup_sorted(&mut empty), 0);
    assert!(empty.is_empty());

    let mut v = vec![1, 1, 2, 2, 2, 3, 5, 5];
    let n = dedup_sorted(&mut v);
    assert_eq!(n, 4);
    assert_eq!(v, vec![1, 2, 3, 5]);

    let mut single = vec![7];
    assert_eq!(dedup_sorted(&mut single), 1);
    println!("ok");
}
```

`write` marks the end of the deduplicated prefix and `read` scans forward. When `nums[read]` differs from the last kept value, it is copied down to `write` and `write` advances. Because the input is sorted, equal values are always adjacent, so a single scan suffices. `truncate(write)` keeps the returned length and the visible contents consistent.

