#include <limits.h>
#include <stdbool.h>
#include <ctype.h>

bool parse_int(const char *s, int *out) {
    if (s == NULL || out == NULL) return false;

    while (isspace((unsigned char)*s)) ++s;

    bool neg = false;
    if (*s == '+' || *s == '-') {
        neg = (*s == '-');
        ++s;
    }

    if (!isdigit((unsigned char)*s)) return false;

    long acc = 0;
    while (isdigit((unsigned char)*s)) {
        acc = acc * 10 + (*s - '0');
        if (acc > (long)INT_MAX + 1) return false;
        ++s;
    }

    while (isspace((unsigned char)*s)) ++s;
    if (*s != '\0') return false;

    if (neg) {
        if (acc > (long)INT_MAX + 1) return false;
        *out = (int)-acc;
    } else {
        if (acc > INT_MAX) return false;
        *out = (int)acc;
    }
    return true;
}

#include <stdio.h>
#include <assert.h>
int main(void) {
    int v;
    assert(parse_int("  -42 ", &v) && v == -42);
    assert(parse_int("2147483647", &v) && v == 2147483647);
    assert(parse_int("2147483648", &v) == false);
    assert(parse_int("-2147483648", &v) && v == INT_MIN);
    assert(parse_int("12x", &v) == false);
    assert(parse_int("", &v) == false);
    puts("ok");
    return 0;
}
```

The accumulator is `long` so `acc * 10 + digit` cannot itself overflow on typical 64-bit `long` before the range check runs. `acc > (long)INT_MAX + 1` is allowed only for negative values, which is exactly what makes `INT_MIN` parseable while `2147483648` is not. Trailing whitespace is skipped, but any other trailing character fails the parse, so `12x` is rejected. The boolean return separates "not a number" from a legitimate `0`.

```rust
use std::collections::HashMap;

struct LruCache {
    cap: usize,
    map: HashMap<String, (i32, u64)>,
    tick: u64,
}

impl LruCache {
    fn new(cap: usize) -> Self {
        LruCache { cap: cap.max(1), map: HashMap::new(), tick: 0 }
    }

    fn get(&mut self, key: &str) -> Option<i32> {
        self.tick += 1;
        let t = self.tick;
        self.map.get_mut(key).map(|e| {
            e.1 = t;
            e.0
        })
    }

    fn put(&mut self, key: &str, value: i32) {
        self.tick += 1;
        let t = self.tick;
        if self.map.contains_key(key) {
            self.map.insert(key.to_string(), (value, t));
            return;
        }
        if self.map.len() >= self.cap {
            if let Some(old) = self.map.iter().min_by_key(|(_, e)| e.1).map(|(k, _)| k.clone()) {
                self.map.remove(&old);
            }
        }
        self.map.insert(key.to_string(), (value, t));
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put("a", 1);
    c.put("b", 2);
    assert_eq!(c.get("a"), Some(1));   // 'a' now most recent
    c.put("c", 3);                     // evicts 'b'
    assert_eq!(c.get("b"), None);
    assert_eq!(c.get("c"), Some(3));
    println!("ok");
}
```

Each entry stores its value alongside a monotonically increasing `tick`. `get` refreshes the tick so the entry counts as recently used; `put` on a full cache finds the entry with the smallest tick via `min_by_key` and removes it. That makes eviction O(n) per insert rather than O(1), which is the trade-off for not hand-rolling a linked list. `cap.max(1)` avoids a zero-capacity cache that could never hold anything.

```python
from functools import lru_cache


@lru_cache(maxsize=None)
def fib_memo(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return fib_memo(n - 1) + fib_memo(n - 2)


def fib_iter(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


if __name__ == "__main__":
    assert fib_memo(0) == 0
    assert fib_memo(1) == 1
    assert fib_memo(10) == 55
    assert fib_iter(0) == 0
    assert fib_iter(1) == 1
    assert fib_iter(100) == 354224848179261915075
    assert fib_memo(30) == fib_iter(30)
    for n in range(40):
        assert fib_memo(n) == fib_iter(n)
    print("ok")
```

`lru_cache` reduces the recursion from exponential to linear by reusing previously computed values. The iterative version avoids recursion depth limits entirely and stays O(1) in memory, so it reaches `fib_iter(100)` without trouble. The cross-check loop over `range(40)` asserts both implementations agree, which is the real test here rather than any single hardcoded value. Negative input raises `ValueError` instead of silently returning something arbitrary.

```python
import heapq

class RunningMedian:
    def __init__(self):
        # max-heap of the lower half (negated), min-heap of the upper half
        self.low = []
        self.high = []

    def add(self, value):
        if not self.low or value <= -self.low[0]:
            heapq.heappush(self.low, -value)
        else:
            heapq.heappush(self.high, value)
        # rebalance: low may exceed high by at most 1
        if len(self.low) > len(self.high) + 1:
            heapq.heappush(self.high, -heapq.heappop(self.low))
        elif len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def median(self):
        if not self.low:
            return None
        if len(self.low) == len(self.high):
            return (-self.low[0] + self.high[0]) / 2.0
        return float(-self.low[0])


if __name__ == "__main__":
    rm = RunningMedian()
    for n in [5, 2, 9, 2, 7]:
        rm.add(n)
        print(rm.median())
    # 5.0, 3.5, 5.0, 3.5, 5.0
```
Two heaps split the stream so the median is always at their tops. Duplicates push to `low` consistently, and rebalancing keeps the sizes within one, so `median()` is O(1) and `add()` is O(log n). Empty input returns `None` rather than raising.

