use std::collections::VecDeque;

fn merge_intervals(mut input: VecDeque<(i32, i32)>) -> Vec<(i32, i32)> {
    let mut merged: Vec<(i32, i32)> = Vec::new();
    while let Some((start, end)) = input.pop_front() {
        match merged.last_mut() {
            Some(last) if start <= last.1 => {
                if end > last.1 {
                    last.1 = end;
                }
            }
            _ => merged.push((start, end)),
        }
    }
    merged
}

fn main() {
    let cases = vec![
        vec![(1, 3), (2, 6), (8, 10), (15, 18)],
        vec![(1, 4), (4, 5)],
        vec![],
        vec![(5, 5), (5, 7)],
    ];
    for case in cases {
        let deque: VecDeque<_> = case.into_iter().collect();
        println!("{:?}", merge_intervals(deque));
    }
    // [(1, 6), (8, 10), (15, 18)]
    // [(1, 5)]
    // []
    // [(5, 7)]
}
```
Adjacent intervals `(1,4)` and `(4,5)` merge because I use `start <= last.1`. Touching degenerate intervals like `(5,5)` collapse into their neighbor. An empty deque returns an empty Vec of pairs.

```python
def is_balanced(text):
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set(pairs.values())
    stack = []
    for ch in text:
        if ch in openers:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack


if __name__ == "__main__":
    tests = ["([]{})", "([)]", "", "((", "a(b)c[d]"]
    for t in tests:
        print(repr(t), is_balanced(t))
    # '([]{})' True
    # '([)]' False
    # '' True
    # '((' False
    # 'a(b)c[d]' True
```
Openers push; a closer must match the top of the stack or the function returns immediately. Empty string is balanced, and any leftover openers leave the stack non-empty, so the final check `not stack` rejects them. Non-bracket characters are ignored.

```c
#include <stdio.h>
#include <string.h>

#define MAX_LINE 4096
#define MAX_WORDS 1024

int main(void) {
    char line[MAX_LINE];
    char *words[MAX_WORDS];

    while (fgets(line, sizeof line, stdin)) {
        size_t len = strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
            line[--len] = '\0';
        }

        size_t count = 0;
        char *save = NULL;
        for (char *tok = strtok_r(line, " \t", &save); tok != NULL;
             tok = strtok_r(NULL, " \t", &save)) {
            if (count < MAX_WORDS) words[count++] = tok;
        }

        for (size_t i = count; i > 0; --i) {
            fputs(words[i - 1], stdout);
            fputc(i == 1 ? '\n' : ' ', stdout);
        }
        if (count == 0) fputc('\n', stdout);
    }
    return 0;
}
```
`strtok_r` splits on spaces and tabs and collapses runs of whitespace, so `"a   b"` becomes two words. Words are stored in an array and printed in reverse, joined by single spaces. Blank lines emit a newline, and `fgets` bounds each read to `MAX_LINE`.

```rust
fn is_palindrome(mut x: i64) -> bool {
    if x < 0 {
        return false;
    }
    if x % 10 == 0 && x != 0 {
        return false;
    }
    let mut reversed: i64 = 0;
    while x > reversed {
        reversed = reversed * 10 + x % 10;
        x /= 10;
    }
    x == reversed || x == reversed / 10
}

fn main() {
    let tests = [121i64, -121, 10, 0, 1221, 12321];
    for &t in &tests {
        println!("{t}: {}", is_palindrome(t));
    }
    // 121: true
    // -121: false
    // 10: false
    // 0: true
    // 1221: true
    // 12321: true
}
```
The loop reverses only half the digits, so it never overflows a 64-bit integer. The two comparisons cover odd and even lengths: `x == reversed` for `1221`, `x == reversed / 10` for `12321`. Trailing zeros (except zero itself) fail fast because a palindrome can't start with zero.

