#include <optional>
#include <vector>
#include <iostream>

namespace detail {
    template <typename Container>
    std::optional<typename Container::value_type> last_or_none(const Container& c) {
        if (c.empty()) {
            return std::nullopt;
        }
        return c.back();
    }
}

template <typename Container>
std::optional<typename Container::value_type> last_or_none(const Container& c) {
    return detail::last_or_none(c);
}

int main() {
    std::vector<int> empty;
    std::vector<int> data{4, 8, 15, 16};

    std::cout << last_or_none(empty).value_or(-1) << "\n";   // -1
    std::cout << last_or_none(data).value_or(-1) << "\n";    // 16
}
```
Returning `std::optional` makes the empty case explicit instead of undefined, so the caller chooses a default with `value_or`. This works for any container exposing `empty()`, `back()`, and `value_type`, such as `std::vector`, `std::array`, or `std::deque`. The empty vector prints the sentinel `-1`.

