def normalize_ipv4(addr):
    parts = addr.strip().split('.')
    if len(parts) != 4:
        raise ValueError(f"expected 4 octets, got {len(parts)}")
    octets = []
    for p in parts:
        if not p.isdigit():
            raise ValueError(f"non-numeric octet: {p!r}")
        v = int(p)
        if not 0 <= v <= 255:
            raise ValueError(f"octet out of range: {v}")
        octets.append(str(v))
    return '.'.join(octets)


