def longest_common_prefix(strs):
    """Return the longest common prefix shared by every string in strs."""
    if not strs:
        return ""
    shortest = min(strs, key=len)
    for i, ch in enumerate(shortest):
        for other in strs:
            if other[i] != ch:
                return shortest[:i]
    return shortest


if __name__ == "__main__":
