```c
#include <stdio.h>
#include <string.h>

static void reverse(char *s, size_t lo, size_t hi) {
    while (lo < hi) {
        char t = s[lo];
        s[lo++] = s[hi];
        s[hi--] = t;
    }
}

void reverse_words(char *s) {
    size_t len = strlen(s);
    if (len == 0) {
        return;
    }
    reverse(s, 0, len - 1);
    size_t start = 0;
    for (size_t i = 0; i <= len; ++i) {
        if (i == len || s[i] == ' ') {
            reverse(s, start, i - 1);
            start = i + 1;
        }
    }
}

int main(void) {
    char buf[256];
    while (fgets(buf, sizeof buf, stdin)) {
        buf[strcspn(buf, "\n")] = '\0';
        reverse_words(buf);
        puts(buf);
    }
    return 0;
}
```
The whole-buffer reverse followed by per-word reverses handles leading or trailing spaces and an empty line without special-casing, because `start` is only used as an index into the string.

