#include <algorithm>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
double median(std::vector<T> values) {
    if (values.empty()) {
        throw std::invalid_argument("median of empty vector");
    }
    std::size_t mid = values.size() / 2;
    std::nth_element(values.begin(), values.begin() + mid, values.end());
    T lower = values[mid];
    if (values.size() % 2 == 1) {
        return static_cast<double>(lower);
    }
    std::nth_element(values.begin(), values.begin() + mid - 1, values.end());
    T upper = values[mid - 1];
    return (static_cast<double>(lower) + static_cast<double>(upper)) / 2.0;
}

int main() {
    std::cout << median(std::vector<int>{3, 1, 2}) << '\n';       // 2
    std::cout << median(std::vector<int>{4, 1, 3, 2}) << '\n';    // 2.5
    try {
        median(std::vector<int>{});
    } catch (const std::invalid_argument& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
```
`nth_element` is average O(n) instead of O(n log n), the value is taken as a copy so the caller's vector is untouched, and the mid element is read before the second partition because `nth_element` reorders in place.

