/* Largest n with fib(n) fitting in uint64_t is 93. */
uint64_t fibonacci(int n) {
    uint64_t a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        uint64_t next = a + b;
        a = b;
        b = next;
    }
    return a;
}

int main(void) {
    printf("fib(0) = %llu\n", (unsigned long long)fibonacci(0));  /* 0 */
    printf("fib(10) = %llu\n", (unsigned long long)fibonacci(10)); /* 55 */
    int n = 100;
    if (n > 93) {
        fprintf(stderr, "n=%d overflows uint64_t; capped to 93\n", n);
        n = 93;
    }
    printf("fib(93) = %llu\n", (unsigned long long)fibonacci(n));
