import sys

def parse_ranges(lines: list[str]) -> list[int]:
    values: list[int] = []
    for lineno, raw in enumerate(lines, start=1):
        line = raw.strip()
        if not line:
            continue
        if "-" not in line:
            raise ValueError(f"line {lineno}: expected 'low-high', got {line!r}")
        low_s, high_s = line.split("-", 1)
        try:
            low, high = int(low_s), int(high_s)
        except ValueError:
            raise ValueError(f"line {lineno}: non-integer bound in {line!r}")
        if low > high:
            raise ValueError(f"line {lineno}: low {low} exceeds high {high}")
        values.append(high - low + 1)
    return values


