def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int) -> int:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return right - left - 1

    for i in range(len(s)):
        odd = expand(i, i)
        even = expand(i, i + 1)
        best = max(odd, even)
        if best > end - start:
            start = i - (best - 1) // 2
            end = i + best // 2

    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "abacdfgdcaba"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```

`expand` returns the length of the palindrome centered at `(left, right)`; odd lengths start at `(i, i)`, even ones at `(i, i+1)`. The empty string and single characters are handled without special cases beyond the initial guard.

