```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int i = 1; i <= 3; ++i) std::cout << "push " << i << ": " << rb.push(i) << '\n';
    std::cout << "push 4 (full): " << rb.push(4) << '\n';
    while (!rb.empty()) std::cout << "pop: " << *rb.pop() << '\n';
    std::cout << "pop (empty): " << (rb.pop().has_value() ? "value" : "none") << '\n';
    return 0;
}
```

A separate `size_` counter distinguishes full from empty when `head_ == tail_`, avoiding the classic ambiguous-state bug. `pop` returns `std::optional` so callers must handle the empty case.

