#[derive(Debug)]
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T: Copy> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        RingBuffer { data: (0..capacity).map(|_| None).collect(), head: 0, len: 0 }
    }

    pub fn push(&mut self, value: T) {
        let idx = (self.head + self.len) % self.data.len();
        self.data[idx] = Some(value);
        if self.len == self.data.len() {
            self.head = (self.head + 1) % self.data.len();
        } else {
            self.len += 1;
        }
    }

    pub fn iter(&self) -> impl Iterator<Item = T> + '_ {
        (0..self.len).map(move |i| self.data[(self.head + i) % self.data.len()].unwrap())
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    for v in 1..=4 { rb.push(v); }
    assert_eq!(rb.iter().collect::<Vec<_>>(), vec![2, 3, 4]);
    let empty = RingBuffer::<i32>::new(2);
    assert_eq!(empty.iter().count(), 0);
    println!("ok");
}
