#include <stdio.h>
#include <stdlib.h>

static int bsearch_rec(const int *arr, int lo, int hi, int target, int depth) {
    if (lo > hi) return -1;
    if (depth <= 0) return -2; /* signal: fall back */
    int mid = lo + (hi - lo) / 2;
    if (arr[mid] == target) return mid;
    if (arr[mid] < target) return bsearch_rec(arr, mid + 1, hi, target, depth - 1);
    return bsearch_rec(arr, lo, mid - 1, target, depth - 1);
}

static int bsearch_iter(const int *arr, int n, int target) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int bsearch(const int *arr, int n, int target) {
    if (n <= 0) return -1;
    int r = bsearch_rec(arr, 0, n - 1, target, 32);
    return r == -2 ? bsearch_iter(arr, n, target) : r;
}

int main(void) {
    int a[] = {-5, -1, 0, 3, 7, 12, 42, 99};
    int n = (int)(sizeof(a) / sizeof(a[0]));
    if (bsearch(a, n, 7) != 4) return 1;
    if (bsearch(a, n, -5) != 0) return 1;
    if (bsearch(a, n, 100) != -1) return 1;
    if (bsearch(a, 0, 1) != -1) return 1;
    printf("all tests passed\n");
    return 0;
}
