#include <iostream>

struct Node {
    int value;
    Node* next;
    Node(int v) : value(v), next(nullptr) {}
};

Node* merge(Node* a, Node* b) {
    Node dummy(0);
    Node* tail = &dummy;
    while (a && b) {
        if (a->value <= b->value) { tail->next = a; a = a->next; }
        else                     { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

void push(Node*& head, int v) {
    Node* n = new Node(v);
    n->next = head;
    head = n;
}

void print(Node* head) {
    for (Node* p = head; p; p = p->next)
        std::cout << p->value << (p->next ? " -> " : "\n");
}

int main() {
    Node* a = nullptr;
    Node* b = nullptr;
    for (int v : {9, 5, 1}) push(a, v);   // sorted ascending: 1 5 9
    for (int v : {8, 6, 3}) push(b, v);   // sorted ascending: 3 6 8
    Node* merged = merge(a, b);
    print(merged);
    return 0;
}
```

