```c
#include <stdio.h>
#include <limits.h>
#include <string.h>

/* Writes the decimal representation of n into buf. buf must be >= 12 bytes. */
void itoa(int n, char* buf) {
    char tmp[12];
    int i = 0;
    int negative = n < 0;
    /* Work in unsigned to avoid overflow on INT_MIN (-INT_MIN is UB). */
    unsigned int u = negative ? (unsigned int)(-(long long)n) : (unsigned int)n;

    if (u == 0) tmp[i++] = '0';
    while (u > 0) {
        tmp[i++] = (char)('0' + u % 10);
        u /= 10;
    }
    int j = 0;
    if (negative) buf[j++] = '-';
    while (i > 0) buf[j++] = tmp[--i];
    buf[j] = '\0';
}

int main(void) {
    char buf[12];
    int cases[] = {0, 7, -7, 12345, -12345, INT_MAX, INT_MIN};
    for (size_t k = 0; k < sizeof(cases) / sizeof(cases[0]); k++) {
        itoa(cases[k], buf);
        char ref[12];
        snprintf(ref, sizeof(ref), "%d", cases[k]);
        if (strcmp(buf, ref) != 0) {
            printf("MISMATCH: got %s want %s\n", buf, ref);
            return 1;
        }
        printf("%s\n", buf);
    }
    return 0;
}
```

Negating `INT_MIN` in `int` is undefined behavior, so the code casts to `long long` before flipping the sign and does the digit work in `unsigned` — that is the case most naive `itoa` implementations get wrong.

