```cpp
#include <iostream>
#include <vector>

// Returns the index of target, or the index where it should be inserted
// to keep the vector sorted (lower bound).
template <typename T>
std::size_t lowerBound(const std::vector<T>& v, const T& target) {
    std::size_t lo = 0, hi = v.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;  // no overflow
        if (v[mid] < target)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;
}

int main() {
    std::vector<int> v = {1, 3, 5, 7, 9};
    std::cout << lowerBound(v, 5) << '\n';  // 2, found
    std::cout << lowerBound(v, 4) << '\n';  // 2, insertion point
    std::cout << lowerBound(v, 0) << '\n';  // 0
    std::cout << lowerBound(v, 10) << '\n'; // 5
    std::vector<int> empty;
    std::cout << lowerBound(empty, 3) << '\n'; // 0
    return 0;
}
```

This is a lower-bound search: it finds the first position where the element is not less than the target, which is exactly the insertion point when the value is missing. `lo + (hi - lo) / 2` avoids integer overflow on huge index ranges.

