template <std::size_t N>
class RingBuffer {
public:
    void push(double v) {
        buf_[head_] = v;
        head_ = (head_ + 1) % N;
        if (count_ < N) ++count_;
    }
    bool full() const { return count_ == N; }
    double average() const {
        if (count_ == 0) return 0.0;
        double sum = 0.0;
        for (std::size_t i = 0; i < count_; ++i) sum += buf_[i];
        return sum / static_cast<double>(count_);
    }
private:
    std::array<double, N> buf_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<3> rb;
    if (rb.average() != 0.0) return 1;
    rb.push(1.0); rb.push(2.0);
    std::cout << rb.average() << '\n';  // 1.5
    rb.push(3.0); rb.push(4.0);
    std::cout << rb.full() << ' ' << rb.average() << '\n';  // 1 3
    return 0;
}
