#include <iostream>
#include <vector>
#include <functional>

unsigned long long fib(int n) {
    if (n < 0) return 0;
    std::vector<unsigned long long> memo(n + 1, 0);
    std::function<unsigned long long(int)> go = [&](int k) -> unsigned long long {
        if (k <= 1) return static_cast<unsigned long long>(k);
        auto& slot = memo[k];
        if (slot != 0) return slot;
        return slot = go(k - 1) + go(k - 2);
    };
    return go(n);
}

int main() {
    for (int n : {-1, 0, 1, 5, 10, 50}) {
        std::cout << "fib(" << n << ") = " << fib(n) << "\n";
    }
    return 0;
}
