    let mut first: Option<i64> = None;
    let mut second: Option<i64> = None;
    for &v in values {
        match first {
            None => first = Some(v),
            Some(f) if v > f => {
                second = first;
                first = Some(v);
            }
            Some(f) if v == f => {}
            Some(_) => match second {
                None => second = Some(v),
                Some(s) if v > s => second = Some(v),
                _ => {}
            },
        }
