#include <limits.h>
#include <stdbool.h>
#include <stdio.h>
#include <ctype.h>

bool parse_long(const char *s, long *out) {
    if (!s || !*s) return false;
    bool neg = false;
    if (*s == '+' || *s == '-') {
        neg = (*s == '-');
        s++;
    }
    if (!isdigit((unsigned char)*s)) return false;

    long acc = 0;
    for (; *s; s++) {
        if (!isdigit((unsigned char)*s)) return false;
        int d = *s - '0';
        long limit = neg ? (LONG_MIN / 10) : (LONG_MAX / 10);
        if (acc < limit || (acc == limit && d > (neg ? -(LONG_MIN % 10) : LONG_MAX % 10)))
            return false;
        acc = acc * 10 + (neg ? -d : d);
    }
    *out = acc;
    return true;
}

int main(void) {
    long v;
    printf("%d\n", parse_long("123", &v));
    printf("%d\n", parse_long("99999999999999999999", &v));
    printf("%d\n", parse_long("12x", &v));
    printf("%d\n", parse_long("-42", &v));
    return 0;
}
```

Each digit is checked against the limit *before* multiplying, so no intermediate value overflows. Bad input returns false and leaves `*out` untouched.

