char *reverse_in_place(char *s) {
    if (!s) return NULL;
    char *left = s;
    char *right = s + strlen(s);
    if (right == left) return s;
    right--;
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        left++;
        right--;
    }
    return s;
}

int main(void) {
    char buf[] = "hello";
    printf("%s\n", reverse_in_place(buf));
    char empty[] = "";
    printf("[%s]\n", reverse_in_place(empty));
    return 0;
}
