#include <stdio.h>
#include <string.h>

static const int VALUES[] = {1000, 900, 500, 400, 100, 90, 50, 40,
                             10, 9, 5, 4, 1};
static const char *SYMS[] = {"M", "CM", "D", "CD", "C", "XC", "L", "XL",
                             "X", "IX", "V", "IV", "I"};

/* Writes the Roman numeral for n into buf (capacity cap).
   Returns the number of characters written, or -1 if the buffer is too
   small or n is out of range. buf is always NUL-terminated on success. */
int to_roman(int n, char *buf, size_t cap) {
    if (n < 1 || n > 3999) {
        return -1;
    }
    size_t used = 0;
    for (size_t i = 0; i < sizeof(VALUES) / sizeof(VALUES[0]); ++i) {
        while (n >= VALUES[i]) {
            size_t len = strlen(SYMS[i]);
            if (used + len + 1 > cap) {
                return -1;
            }
            memcpy(buf + used, SYMS[i], len);
            used += len;
            n -= VALUES[i];
        }
    }
    buf[used] = '\0';
    return (int)used;
}

int main(void) {
    char buf[32];
    int samples[] = {0, 1, 4, 9, 58, 1994, 3999, 4000};
    for (size_t i = 0; i < sizeof(samples) / sizeof(samples[0]); ++i) {
        int len = to_roman(samples[i], buf, sizeof(buf));
        if (len < 0)
            printf("%d -> error\n", samples[i]);
        else
            printf("%d -> %s (%d chars)\n", samples[i], buf, len);
    }
    return 0;
}
