use std::path::Path;

fn split_file(input: &Path, chunk_size: usize) -> io::Result<usize> {
    let data = fs::read(input)?;
    if data.is_empty() {
        return Ok(0);
    }
    let stem = input.file_name().and_then(|s| s.to_str()).unwrap_or("chunk");
    let dir = input.parent().unwrap_or_else(|| Path::new("."));
    let mut count = 0usize;
    for (i, part) in data.chunks(chunk_size).enumerate() {
        let name = format!("{}.part{:03}", stem, i);
        let out = dir.join(name);
        let mut f = fs::File::create(&out)?;
        f.write_all(part)?;
        count += 1;
    }
    Ok(count)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("usage: {} <file> <chunk_bytes>", args[0]);
        std::process::exit(2);
    }
    let chunk_size: usize = match args[2].parse() {
        Ok(n) if n > 0 => n,
        _ => {
            eprintln!("chunk size must be a positive integer");
            std::process::exit(2);
        }
    };
    match split_file(Path::new(&args[1]), chunk_size) {
        Ok(n) => println!("wrote {n} chunks"),
        Err(e) => eprintln!("failed: {e}"),
    }
