def validate_ipv4(address: str):
    """Return (ok, reason). Rejects leading zeros and out-of-range octets."""
    if not isinstance(address, str) or not address:
        return False, "empty"
    parts = address.split(".")
    if len(parts) != 4:
        return False, f"expected 4 octets, got {len(parts)}"
    for part in parts:
        if not part:
            return False, "empty octet"
        if not part.isdigit():
            return False, f"non-numeric octet {part!r}"
        if len(part) > 1 and part[0] == "0":
            return False, f"leading zero in {part!r}"
        if int(part) > 255:
            return False, f"octet {part!r} > 255"
    return True, "ok"


