import sys
import heapq


def running_medians(values):
    low = []   # max-heap (negated)
    high = []  # min-heap
    medians = []
    for x in values:
        heapq.heappush(low, -x)
        # move largest of low into high if it is out of order
        if high and -low[0] > high[0]:
            heapq.heappush(high, -heapq.heappop(low))
        # keep sizes balanced: len(low) >= len(high), at most +1
        if len(low) > len(high) + 1:
            heapq.heappush(high, -heapq.heappop(low))
        elif len(high) > len(low):
            heapq.heappush(low, -heapq.heappop(high))
        if len(low) == len(high):
            medians.append((-low[0] + high[0]) / 2)
        else:
            medians.append(float(-low[0]))
    return medians


def main():
    data = sys.stdin.read().split()
    values = [int(tok) for tok in data]
    if not values:
        sys.stdout.write("")
        return
    for m in running_medians(values):
        # print 3.0 as 3 to keep output tidy
        print(f"{m:g}")


if __name__ == "__main__":
    main()
