from datetime import datetime, timezone


class UtcTimestamp:
    """Parse and normalize timestamps to canonical ISO-8601 UTC."""

    def __init__(self, value: str):
        if not isinstance(value, str) or not value.strip():
            raise ValueError("timestamp must be a non-empty string")
        text = value.strip()
        # Accept a trailing Z as UTC.
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        try:
            dt = datetime.fromisoformat(text)
        except ValueError as exc:
            raise ValueError(f"invalid timestamp: {value!r}") from exc
        if dt.tzinfo is None:
            raise ValueError("timestamp is missing a timezone offset")
        self._dt = dt.astimezone(timezone.utc)

    @property
    def datetime(self):
        return self._dt

    def canonical(self) -> str:
        """Seconds precision, always ending in Z."""
        return self._dt.strftime("%Y-%m-%dT%H:%M:%SZ")


if __name__ == "__main__":
    ts = UtcTimestamp("2024-03-05T12:30:45+02:00")
    assert ts.canonical() == "2024-03-05T10:30:45Z"
    assert UtcTimestamp("2024-03-05T10:30:45Z").canonical() == ts.canonical()
    try:
        UtcTimestamp("2024-03-05T10:30:45")
    except ValueError:
        pass
    else:
        raise AssertionError("naive timestamps must be rejected")
    print(ts.canonical())
```

It prints `2024-03-05T10:30:45Z`. Naive strings without an offset raise a `ValueError` instead of being silently treated as UTC.

