std::vector<int> merge_sorted(const std::vector<int>& a,
                              const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    assert(merge_sorted({}, {}).empty());
    assert(merge_sorted({1, 3, 5}, {}).size() == 3);
    assert(merge_sorted({}, {2, 4}).size() == 2);
    std::vector<int> got = merge_sorted({1, 3, 5}, {2, 4, 6, 6});
    std::vector<int> want = {1, 2, 3, 4, 5, 6, 6};
    assert(got == want);
    for (int v : got) std::cout << v << ' ';
    std::cout << '\n';
    return 0;
}
