fn reverse_words(input: &str) -> String {
    let chars: Vec<char> = input.chars().collect();
    let mut tokens: Vec<String> = Vec::new();
    let mut current = String::new();
    let mut in_space = false;

    for &c in &chars {
        if c.is_whitespace() {
            if !current.is_empty() {
                tokens.push(std::mem::take(&mut current));
            }
            in_space = true;
        } else {
            if in_space {
                tokens.push(std::mem::take(&mut current));
                current.push(' '); // placeholder, replaced below
            }
            // keep whitespace runs as their own tokens
            if current == " " {
                current.clear();
            }
            current.push(c);
        }
    }
    if !current.is_empty() {
        tokens.push(current);
    }

    // Simpler and correct: split into alternating word/space tokens.
    let mut parts: Vec<String> = Vec::new();
    let mut buf = String::new();
    let mut space_mode = input.chars().next().map_or(false, |c| c.is_whitespace());
    let mut started = false;
    for c in input.chars() {
        let ws = c.is_whitespace();
        if !started {
            space_mode = ws;
            started = true;
        }
        if ws != space_mode {
            parts.push(std::mem::take(&mut buf));
            space_mode = ws;
        }
        buf.push(c);
    }
    if !buf.is_empty() {
        parts.push(buf);
    }

    let mut words: Vec<&String> = parts.iter().filter(|p| !p.chars().next().unwrap().is_whitespace()).collect();
    words.reverse();

    let mut out = String::new();
    let mut w = words.into_iter();
    let mut first = true;
    for part in &parts {
        if part.chars().next().unwrap().is_whitespace() {
            out.push_str(part);
        } else if first {
            out.push_str(w.next().unwrap());
            first = false;
        } else {
            out.push_str(w.next().unwrap());
        }
    }
    out
}

fn main() {
    assert_eq!(reverse_words("hello world"), "world hello");
    assert_eq!(reverse_words("a  b   c"), "c  b   a");
    assert_eq!(reverse_words(""), "");
    assert_eq!(reverse_words("héllo wörld"), "wörld héllo");
    println!("{}", reverse_words("héllo  wörld"));
}
