        *ERROR*|*FATAL*|*CRITICAL*) printf '%s%s%s\n' "$red" "$line" "$reset" ;;
        *WARN*|*WARNING*) printf '%s%s%s\n' "$yellow" "$line" "$reset" ;;
        *INFO*) printf '%s%s%s\n' "$green" "$line" "$reset" ;;
        *) printf '%s\n' "$line" ;;
    esac
done
