        if (end == argv[1] || *end != '\0' || n < 0) {
            fprintf(stderr, "usage: %s [count]\n", argv[0]);
            return 1;
        }
    }

    uint64_t a = 0, b = 1;
    for (long i = 0; i < n; i++) {
        printf("%llu\n", (unsigned long long)a);
        if (UINT64_MAX - a < b) {
            fprintf(stderr, "overflow after %ld terms\n", i + 1);
            return 0;
        }
        uint64_t next = a + b;
        a = b;
        b = next;
    }
    return 0;
}
```

`./fib 10` prints `0` through `34`. `./fib 100` prints 93 terms (the last being the largest fit in 64 bits) then stops with `overflow after 93 terms` on stderr. The pre-add check `UINT64_MAX - a < b` avoids wraparound entirely, and a non-numeric or negative argument exits with status 1.

```python
def median(nums):
    if not nums:
        raise ValueError("median() arg is an empty sequence")
    n = len(nums)
    mid = n // 2
    if n % 2 == 1:
        return _select(nums, mid)
    return (_select(nums, mid - 1) + _select(nums, mid)) / 2.0


def _select(nums, k):
    lo, hi = 0, len(nums) - 1
    while True:
        if lo == hi:
            return nums[lo]
        pivot = _partition(nums, lo, hi)
        if k == pivot:
            return nums[k]
        elif k < pivot:
            hi = pivot - 1
        else:
            lo = pivot + 1


def _partition(nums, lo, hi):
    mid = (lo + hi) // 2
    # median-of-three pivot to avoid worst case on sorted input
    if nums[mid] < nums[lo]:
        nums[lo], nums[mid] = nums[mid], nums[lo]
    if nums[hi] < nums[lo]:
        nums[lo], nums[hi] = nums[hi], nums[lo]
    if nums[hi] < nums[mid]:
        nums[hi], nums[mid] = nums[mid], nums[hi]
    nums[mid], nums[hi - 1] = nums[hi - 1], nums[mid]
    pivot = nums[hi - 1]
    i = lo
    for j in range(lo, hi - 1):
        if nums[j] < pivot:
            nums[i], nums[j] = nums[j], nums[i]
            i += 1
    nums[i], nums[hi - 1] = nums[hi - 1], nums[i]
    return i
```

`median` handles the empty case by raising, odd lengths with one selection, and even lengths by averaging the two central order statistics. The median-of-three pivot keeps the expected runtime linear on already-sorted input, which is the case plain quickselect degrades to quadratic on.

