class ConfigError(ValueError):
    pass


def parse_config(text):
    result = {}
    for lineno, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ConfigError(f"line {lineno}: expected 'key=value', got {raw!r}")
        key, _, value = line.partition('=')
        key = key.strip()
        value = value.strip()
        if not key:
            raise ConfigError(f"line {lineno}: empty key")
        if key in result:
            raise ConfigError(f"line {lineno}: duplicate key {key!r}")
        result[key] = value
    return result


if __name__ == '__main__':
    sample = """
    # app config
    host = localhost
    port=8080

    name = "caf\u00e9"
    """
    print(parse_config(sample))
```

A trailing `#` is treated as part of the value, not a comment, so a value like `url = http://x#frag` survives intact. Comments only count when `#` starts the line after stripping.

```python
def rle_encode(text):
    if not text:
        return ""
    parts = []
    prev = text[0]
    count = 1
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            parts.append(f"{count}{prev}")
            prev = ch
            count = 1
    parts.append(f"{count}{prev}")
    return "".join(parts)


def rle_decode(encoded):
    out = []
    i = 0
    n = len(encoded)
    while i < n:
        if not encoded[i].isdigit():
            raise ValueError(f"expected digit at index {i}, got {encoded[i]!r}")
        j = i
        while j < n and encoded[j].isdigit():
            j += 1
        if j >= n:
            raise ValueError("trailing count with no character")
        count = int(encoded[i:j])
        if count <= 0:
            raise ValueError(f"invalid count {count} at index {i}")
        out.append(encoded[j] * count)
        i = j + 1
    return "".join(out)


if __name__ == '__main__':
    for s in ["", "a", "aaa", "aabbbcc", "\u00e9\u00e9\u00e9\u4e2d"]:
        e = rle_encode(s)
        assert rle_decode(e) == s, (s, e)
    print("ok")
```

`str.isdigit()` is true for non-ASCII digits like `\u06f1`, so `int()` still parses them; the round-trip assertion catches any mismatch. Empty input returns an empty string rather than crashing.

```cpp
#include <cstddef>
#include <cstdio>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(new int[capacity]), cap_(capacity), head_(0), tail_(0), size_(0) {}
    ~RingBuffer() { delete[] buf_; }
    RingBuffer(const RingBuffer&) = delete;
    RingBuffer& operator=(const RingBuffer&) = delete;

    bool push(int value) {
        if (size_ == cap_) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % cap_;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    int* buf_;
    std::size_t cap_, head_, tail_, size_;
};

int main() {
    RingBuffer rb(3);
    if (rb.size() != 0 || !rb.empty()) return 1;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;  // full
    if (rb.pop() != 1) return 1;
    if (!rb.push(4)) return 1;
    if (rb.pop() != 2) return 1;
    if (rb.size() != 2) return 1;
    if (rb.pop() != 3 || rb.pop() != 4 || rb.pop().has_value()) return 1;
    std::printf("ok\n");
    return 0;
}
```

When full, `push` returns false and leaves the buffer intact; `pop` on empty returns `std::nullopt`. The copy constructor is deleted so the owning raw pointer can't be double-freed by an accidental copy.

