```rust
fn longest_common_prefix(words: &[&str]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = words[0];
    let first: Vec<char> = first.chars().collect();
    let mut len = first.len();
    for w in &words[1..] {
        len = w
            .chars()
            .zip(first[..len].iter())
            .take_while(|(a, b)| a == *b)
            .count();
        if len == 0 {
            return String::new();
        }
    }
    first[..len].iter().collect()
}

fn main() {
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["alone"]), "alone");
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&["dog", "racecar", "car"]), "");
    assert_eq!(longest_common_prefix(&["caf\u{e9}", "cafet\u{e9}"]), "caf");
    println!("ok");
}
```

Iterating `chars()` rather than bytes means a shared prefix never cuts a multi-byte UTF-8 sequence in half. `first[..len]` is safe because `len` is a count of chars already matched against `first`.

```rust
fn eval(expr: &str) -> Result<i64, String> {
    let tokens: Vec<&str> = expr.split_whitespace().collect();
    let mut stack: Vec<i64> = Vec::new();
    for tok in tokens {
        match tok {
            "+" | "-" | "*" | "/" => {
                let b = stack.pop().ok_or_else(|| format!("missing operand for {tok}"))?;
                let a = stack.pop().ok_or_else(|| format!("missing operand for {tok}"))?;
                let v = match tok {
                    "+" => a + b,
                    "-" => a - b,
                    "*" => a * b,
                    _ => {
                        if b == 0 {
                            return Err("division by zero".into());
                        }
                        a / b
                    }
                };
                stack.push(v);
            }
            "(" | ")" => {}
            _ => {
                let n: i64 = tok
                    .parse()
                    .map_err(|_| format!("invalid token {tok:?}"))?;
                stack.push(n);
            }
        }
    }
    match stack.len() {
        1 => Ok(stack[0]),
        n => Err(format!("malformed expression: {n} values left")),
    }
}

fn main() {
    assert_eq!(eval("( 3 + ( 4 * 5 ) )"), Ok(23));
    assert_eq!(eval("( 10 / ( 5 - 3 ) )"), Ok(5));
    assert!(eval("( 1 / 0 )").is_err());
    assert!(eval("3 +").is_err());
    assert!(eval("7").is_err());
    println!("ok");
}
```

Because the input is fully parenthesized, precedence is encoded by the parentheses and the parentheses themselves can be ignored. Operands are pushed and an operator pops two; leftover values or a short stack are surfaced as `Err` instead of panicking.

