import heapq


def running_medians(nums):
    low = []   # max-heap (store negatives)
    high = []  # min-heap
    out = []
    for x in nums:
        if not low or x <= -low[0]:
            heapq.heappush(low, -x)
        else:
            heapq.heappush(high, x)
        # rebalance: low may have at most one more than high
        if len(low) - len(high) > 1:
            heapq.heappush(high, -heapq.heappop(low))
        elif len(high) > len(low):
            heapq.heappush(low, -heapq.heappop(high))
        if len(low) == len(high):
            out.append((-low[0] + high[0]) / 2)
        else:
            out.append(float(-low[0]))
    return out


if __name__ == "__main__":
    print(running_medians([1, 2, 3]))       # [1.0, 1.5, 2.0]
    print(running_medians([5, 4, 3, 2, 1])) # [5.0, 4.5, 4.0, 3.5, 3.0]
    print(running_medians([]))              # []
    assert running_medians([1, 2, 3]) == [1.0, 1.5, 2.0]
