    while (i < j) {
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[i]))) ++i;
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[j - 1]))) --j;
        if (i >= j) break;
        if (std::tolower(static_cast<unsigned char>(s[i])) !=
            std::tolower(static_cast<unsigned char>(s[j - 1]))) return false;
        ++i;
        --j;
    }
    return true;
}

int main() {
    std::cout << std::boolalpha
              << is_palindrome("A man, a plan, a canal: Panama") << "\n"  // true
              << is_palindrome("race a car") << "\n"                      // false
              << is_palindrome("") << "\n";                               // true
}
```

Two indices walk inward, skipping past non-alphanumeric bytes. The `static_cast<unsigned char>` prevents undefined behaviour from negative `char` values passed to `isalnum`/`tolower`. Empty input returns true.

