int max_subarray_sum(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    long long best = std::numeric_limits<long long>::min();
    long long cur = 0;
    for (int v : nums) {
        cur = std::max<long long>(v, cur + v);
        best = std::max(best, cur);
    }
    return static_cast<int>(best);
}

