struct Interval {
    int start;
    int end;
};

std::vector<Interval> mergeIntervals(std::vector<Interval> intervals) {
    if (intervals.empty()) return {};
    std::sort(intervals.begin(), intervals.end(),
              [](const Interval& a, const Interval& b) {
                  return a.start < b.start;
              });
    std::vector<Interval> merged;
    merged.push_back(intervals[0]);
    for (std::size_t i = 1; i < intervals.size(); ++i) {
        if (intervals[i].start <= merged.back().end) {
            merged.back().end = std::max(merged.back().end, intervals[i].end);
        } else {
            merged.push_back(intervals[i]);
        }
    }
    return merged;
}

int main() {
    std::vector<Interval> input = {{1, 3}, {2, 6}, {8, 10}, {9, 12}, {15, 18}};
    for (const auto& iv : mergeIntervals(input)) {
        std::cout << "[" << iv.start << ", " << iv.end << "] ";
    }
    std::cout << "\n";
    // Empty input must not crash.
    std::vector<Interval> empty;
    std::cout << mergeIntervals(empty).size() << "\n";
    return 0;
}
```

Sorting by `start` lets one pass merge anything that begins before the current interval ends. `std::max` handles fully contained intervals like `{2,3}` inside `{1,6}`. The empty-input path returns before indexing `intervals[0]`.

