#include <cstddef>
#include <stdexcept>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), size_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == buf_.size(); }
    std::size_t size() const { return size_; }

    bool push(const T& value) {
        if (full()) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % buf_.size();
        ++size_;
        return true;
    }

    bool pop(T& out) {
        if (empty()) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return true;
    }

private:
    std::vector<T> buf_;
    std::size_t head_, tail_, size_;
};

#include <cassert>
int main() {
    RingBuffer<int> rb(3);
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.full() && !rb.push(4));
    int v = 0;
    assert(rb.pop(v) && v == 1);
    assert(rb.pop(v) && v == 2);
    rb.push(4);
    assert(rb.pop(v) && v == 3);
    assert(rb.pop(v) && v == 4);
    assert(rb.empty() && !rb.pop(v));
    return 0;
}
```
Modular arithmetic wraps head and tail; `size_` distinguishes full from empty without wasting a slot.

