fn rotate_left<T>(data: &mut [T], k: usize) {
    let n = data.len();
    if n == 0 {
        return;
    }
    let k = k % n; // normalize so k < n
    data[..k].reverse();
    data[k..].reverse();
    data.reverse();
}

fn main() {
    let mut a = vec![1, 2, 3, 4, 5];
    rotate_left(&mut a, 2);
    assert_eq!(a, vec![3, 4, 5, 1, 2]);

    let mut b = vec![1, 2, 3];
    rotate_left(&mut b, 0);
    assert_eq!(b, vec![1, 2, 3]);

    let mut c = vec![1, 2, 3];
    rotate_left(&mut c, 7); // larger than len
    assert_eq!(c, vec![2, 3, 1]);

    let mut empty: Vec<i32> = vec![];
    rotate_left(&mut empty, 3);
    assert!(empty.is_empty());
    println!("ok");
}
```
Reversing the first `k`, then the rest, then the whole slice rotates left. Taking `k % n` guards against `k >= n` and the `n == 0` early return avoids division by zero.

