def parse_pairs(text):
    """Parse 'k=v;k2=v2' into a dict. Return None on any malformed or duplicate entry."""
    result = {}
    for raw in text.split(';'):
        entry = raw.strip()
        if not entry:
            continue
        if entry.count('=') != 1:
            return None
        key, value = entry.split('=')
        key = key.strip()
        value = value.strip()
        if not key or key in result:
