        return

    print(f"rows:    {len(scores)}")
    print(f"mean:    {sum(scores) / len(scores):.3f}")
    print(f"min:     {min(scores):.3f}")
    print(f"max:     {max(scores):.3f}")
    if skipped:
        print(f"skipped: {skipped}")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit("usage: summarize.py SCORES.csv")
