#include <condition_variable>
#include <cstddef>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be positive");
        }
    }

    // Blocks until there is room. Returns false if the queue is closed.
    bool push(T value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [this] { return closed_ || queue_.size() < capacity_; });
        if (closed_) {
            return false;
        }
        queue_.push(std::move(value));
        not_empty_.notify_one();
        return true;
    }

    // Blocks until an item is available; returns nullopt once closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock, [this] { return closed_ || !queue_.empty(); });
        if (queue_.empty()) {
            return std::nullopt;  // closed and drained
        }
        T value = std::move(queue_.front());
        queue_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.size();
    }

private:
    const std::size_t capacity_;
    mutable std::mutex mutex_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
    std::queue<T> queue_;
    bool closed_ = false;
};

// Example driver
#include <cassert>
#include <iostream>
#include <thread>
#include <vector>

int main() {
    BoundedQueue<int> q(4);
    std::vector<std::thread> workers;

    for (int p = 0; p < 4; ++p) {
        workers.emplace_back([&q, p] {
            for (int i = 0; i < 25; ++i) {
                q.push(p * 1000 + i);
            }
        });
    }

    int received = 0;
    while (std::optional<int> item = q.pop()) {
        ++received;
    }
    for (auto& t : workers) t.join();

    std::cout << "received " << received << " items\n";
    assert(received == 100);
    return 0;
}
