int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "usage: wordcount FILE\n";
        return 1;
    }

    std::ifstream in(argv[1]);
    if (!in) {
        std::cerr << "cannot open " << argv[1] << "\n";
        return 1;
    }

    std::unordered_map<std::string, std::size_t> counts;
    std::string word;
    while (in >> word) {
        // Lowercase, then strip leading/trailing punctuation.
        for (char& c : word) {
            c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        }
        std::size_t begin = word.find_first_not_of("'\".,;:!?()[]{}");
        std::size_t end = word.find_last_not_of("'\".,;:!?()[]{}");
        if (begin == std::string::npos) {
            continue;  // token was all punctuation
        }
        ++counts[word.substr(begin, end - begin + 1)];
    }

    std::vector<std::pair<std::string, std::size_t>> ranked(counts.begin(), counts.end());
    std::sort(ranked.begin(), ranked.end(),
              [](const auto& a, const auto& b) {
                  if (a.second != b.second) return a.second > b.second;
                  return a.first < b.first;  // stable tie-break
              });

    std::size_t limit = std::min<std::size_t>(10, ranked.size());
    for (std::size_t i = 0; i < limit; ++i) {
        std::cout << ranked[i].second << '\t' << ranked[i].first << '\n';
    }
    return 0;
}
