```rust
#[derive(Debug)]
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize, // next write position
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        let mut data = Vec::with_capacity(capacity);
        data.resize_with(capacity, || None);
        Self { data, head: 0, len: 0 }
    }

    pub fn capacity(&self) -> usize {
        self.data.len()
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Push a value, evicting and returning the oldest element when full.
    pub fn push(&mut self, value: T) -> Option<T> {
        let cap = self.capacity();
        let evicted = if self.len == cap {
            self.data[self.head].take()
        } else {
            self.len += 1;
            None
        };
        self.data[self.head] = Some(value);
        self.head = (self.head + 1) % cap;
        evicted
    }

    /// Oldest-to-newest iteration.
    pub fn iter(&self) -> impl Iterator<Item = &T> {
        let cap = self.capacity();
        let start = (self.head + cap - self.len) % cap;
        (0..self.len).map(move |i| self.data[(start + i) % cap].as_ref().unwrap())
    }
}

fn main() {
    let mut ring = RingBuffer::new(3);
    assert!(ring.push(1).is_none());
    assert!(ring.push(2).is_none());
    assert!(ring.push(3).is_none());
    assert_eq!(ring.push(4), Some(1)); // 1 evicted
    assert_eq!(ring.push(5), Some(2)); // 2 evicted
    assert_eq!(ring.iter().copied().collect::<Vec<_>>(), vec![3, 4, 5]);
    println!("ring buffer ok: {:?}", ring.iter().copied().collect::<Vec<_>>());
}
