import re

_SECTION = re.compile(r"^\[([^\]]+)\]$")


def _coerce(raw: str):
    """Turn a raw config value into int/float/bool/str."""
    text = raw.strip()
    if len(text) >= 2 and text[0] == text[-1] and text[0] in "'\"":
        return text[1:-1]  # quoted -> literal string
    lowered = text.lower()
    if lowered in ("true", "yes", "on"):
        return True
    if lowered in ("false", "no", "off"):
        return False
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return text


def parse_ini(text: str) -> dict[str, dict[str, object]]:
    sections: dict[str, dict[str, object]] = {}
    current = None

    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.split("#", 1)[0].split(";", 1)[0].strip()
        if not line:
            continue

        match = _SECTION.match(line)
        if match:
            name = match.group(1).strip()
            if not name:
                raise ValueError(f"line {lineno}: empty section name")
            current = sections.setdefault(name, {})
            continue

        if "=" not in line:
            raise ValueError(f"line {lineno}: expected key=value, got {line!r}")
        key, _, value = line.partition("=")
        key = key.strip()
        if not key:
            raise ValueError(f"line {lineno}: empty key")

        target = current if current is not None else sections.setdefault("", {})
        target[key] = _coerce(value)

    return sections


if __name__ == "__main__":
    sample = """
; global defaults
name = "my app"
verbose = no

[server]
host = 0.0.0.0
port = 8080
ratio = 0.75
tls = true
"""
    cfg = parse_ini(sample)
    assert cfg[""]["name"] == "my app"
    assert cfg[""]["verbose"] is False
    assert cfg["server"]["port"] == 8080
    assert cfg["server"]["ratio"] == 0.75
    assert cfg["server"]["tls"] is True
    print(cfg)
