def encode(text):
    if not text:
        return ""
    parts = []
    prev = text[0]
    count = 1
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            parts.append(f"{count}{prev}")
            prev = ch
            count = 1
    parts.append(f"{count}{prev}")
    return "".join(parts)


def decode(data):
    out = []
    num = ""
    for ch in data:
        if ch.isdigit():
            num += ch
        else:
            if not num:
                raise ValueError(f"missing count before {ch!r}")
            out.append(ch * int(num))
            num = ""
    if num:
        raise ValueError("trailing count with no character")
    return "".join(out)


if __name__ == "__main__":
    for sample in ["", "aaabbc", "ééé世世", "z"]:
        assert decode(encode(sample)) == sample, sample
    assert encode("aaabbc") == "3a2b1c"
    print("ok")
