```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    bool push(T item) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return closed_ || q_.size() < cap_; });
        if (closed_) return false;
        q_.push(std::move(item));
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;
        T item = std::move(q_.front());
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return item;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mu_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    bool closed_ = false;
    std::queue<T> q_;
    std::mutex mu_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
};
```

`push` blocks while the queue is full, `pop` blocks while empty, and `close` wakes every waiter so they can observe `closed_` and return `false`/`nullopt`. Waiting on predicates avoids spurious wakeups, and the notify happens after unlocking to reduce contention.

```rust
use std::cmp::Ordering;

pub fn binary_search<T: Ord>(slice: &[T], target: &T) -> Result<usize, usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            Ordering::Less => lo = mid + 1,
            Ordering::Greater => hi = mid,
            Ordering::Equal => return Ok(mid),
        }
    }
    Err(lo)
}

#[cfg(test)]
mod tests {
    use super::binary_search;

    #[test]
    fn finds_present() {
        let data = [1, 3, 5, 7, 9];
        assert_eq!(binary_search(&data, &7), Ok(3));
    }

    #[test]
    fn reports_insertion_point() {
        let data = [1, 3, 5, 7, 9];
        assert_eq!(binary_search(&data, &4), Err(2));
        assert_eq!(binary_search(&data, &0), Err(0));
        assert_eq!(binary_search(&data, &10), Err(5));
    }

    #[test]
    fn empty_slice() {
        let data: [u8; 0] = [];
        assert_eq!(binary_search(&data, &3), Err(0));
    }
}
```

`mid` is computed as `lo + (hi - lo) / 2` to avoid overflow on large slices. On a miss, `lo` is the index where the target would be inserted to keep the slice sorted, matching `std::slice::binary_search`'s `Err` convention.

```rust
use std::collections::HashMap;
use std::hash::Hash;

pub struct LruCache<K, V> {
    cap: usize,
    order: Vec<K>,
    map: HashMap<K, V>,
}

impl<K: Eq + Hash + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache { cap, order: Vec::new(), map: HashMap::new() }
    }

    fn touch(&mut self, key: &K) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            let k = self.order.remove(pos);
            self.order.push(k);
        }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        if self.map.contains_key(key) {
            self.touch(key);
            self.map.get(key)
        } else {
            None
        }
    }

    pub fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            self.touch(&key);
            self.map.insert(key, value);
            return;
        }
        if self.map.len() == self.cap {
            let oldest = self.order.remove(0);
            self.map.remove(&oldest);
        }
        self.order.push(key.clone());
        self.map.insert(key, value);
    }
}
```

A `HashMap` gives O(1) lookup but no ordering, so it cannot tell which key was used least recently. Here `order` tracks recency: the front is the least recently used, the back the most recently used. Note this `Vec`-based eviction is O(n) on `touch`; a production O(1) version uses a doubly linked list (or an index map) alongside the `HashMap`.

