#include <iostream>
#include <vector>

std::vector<int> merge_sorted(const std::vector<int>& a,
                              const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> r1 = merge_sorted({1, 3, 5}, {2, 4, 6});
    for (int v : r1) std::cout << v << ' ';
    std::cout << '\n';                     // 1 2 3 4 5 6

    std::vector<int> r2 = merge_sorted({}, {});
    std::cout << r2.size() << '\n';        // 0

    std::vector<int> r3 = merge_sorted({}, {7, 8});
    for (int v : r3) std::cout << v << ' ';
    std::cout << '\n';                     // 7 8
    return 0;
