pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        let mut data = Vec::with_capacity(capacity);
        data.resize_with(capacity, || None);
        RingBuffer { data, head: 0, len: 0 }
    }

    pub fn push(&mut self, value: T) -> Option<T> {
        let cap = self.data.len();
        let evicted = if self.len == cap {
            let old = self.data[self.head].take();
            old
        } else {
            None
        };
        let idx = (self.head + self.len) % cap;
        self.data[idx] = Some(value);
        if self.len == cap {
            self.head = (self.head + 1) % cap;
        } else {
            self.len += 1;
        }
        evicted
    }

    pub fn iter(&self) -> impl Iterator<Item = &T> {
        let cap = self.data.len();
        (0..self.len).filter_map(move |i| self.data[(self.head + i) % cap].as_ref())
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    for v in [1, 2, 3, 4, 5] {
        let evicted = rb.push(v);
        println!("push {v} -> evicted {evicted:?}");
    }
    let collected: Vec<_> = rb.iter().copied().collect();
    assert_eq!(collected, vec![3, 4, 5]);
}
```
The oldest element is returned by `push` when the buffer is full, and iteration yields items in insertion order starting from the current head.

