                fputs("out of memory\n", stderr);
                free(nums);
                return 1;
            }
            nums = grown;
            cap = new_cap;
        }
        nums[len++] = value;
    }

    for (size_t i = len; i-- > 0;) {
        printf("%d\n", nums[i]);
    }

    free(nums);
    return 0;
}
```
Input is parsed with `scanf`'s return value so non-numeric tails stop the loop cleanly; `realloc` growth is checked, and empty input produces no output. Compile with `cc -Wall -Wextra -o rev rev.c`.

