def longest_unique_substring(s: str) -> str:
    """Return the longest substring of s with no repeated characters.

    Sliding-window with a last-seen index map. Empty input returns "".
    """
    if not s:
        return ""
    last_seen = {}
    start = 0
    best_start = 0
    best_len = 0
    for i, ch in enumerate(s):
        if ch in last_seen and last_seen[ch] >= start:
            start = last_seen[ch] + 1
        last_seen[ch] = i
        if i - start + 1 > best_len:
            best_len = i - start + 1
            best_start = start
    return s[best_start:best_start + best_len]


