#include <cstddef>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), size_(0), cap_(capacity) {}

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return cap_; }
    bool empty() const { return size_ == 0; }

    void push(int v) {
        buf_[(head_ + size_) % cap_] = v;
        if (size_ == cap_) {
            head_ = (head_ + 1) % cap_;
        } else {
            ++size_;
        }
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int v = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

private:
    std::vector<int> buf_;
    std::size_t head_;
    std::size_t size_;
    std::size_t cap_;
};
