/* Parses a base-10 int from src. Returns true on success and stores the value
 * in *out. On overflow, malformed input or an empty string returns false and
 * sets errno to EINVAL, ERANGE or EOVERFLOW as appropriate. */
bool parse_int(const char *src, int *out) {
    if (src == NULL || out == NULL || *src == '\0') {
        errno = EINVAL;
        return false;
    }

    const char *p = src;
    bool negative = false;
    if (*p == '+' || *p == '-') {
        negative = (*p == '-');
        ++p;
    }
    if (!isdigit((unsigned char)*p)) {
        errno = EINVAL;
        return false;
    }

    long acc = 0;
    for (; *p != '\0'; ++p) {
        if (!isdigit((unsigned char)*p)) {
            errno = EINVAL;
            return false;
        }
        acc = acc * 10 + (*p - '0');
        if (acc > (long)INT_MAX + 1) {  /* +1 allows INT_MIN magnitude */
            errno = EOVERFLOW;
            return false;
        }
    }

    long value = negative ? -acc : acc;
    if (value < INT_MIN || value > INT_MAX) {
        errno = ERANGE;
        return false;
    }

    *out = (int)value;
    return true;
}

int main(void) {
    const char *inputs[] = {"42", "-7", "+0", "2147483648", "", "12x"};
    for (size_t i = 0; i < sizeof inputs / sizeof inputs[0]; ++i) {
        int v;
        errno = 0;
        bool ok = parse_int(inputs[i], &v);
        if (ok) printf("%-12s -> %d\n", inputs[i], v);
        else    printf("%-12s -> error (%s)\n", inputs[i],
                       errno == EOVERFLOW ? "overflow" :
                       errno == ERANGE ? "range" : "invalid");
    }
    return 0;
}
```

