```python
from collections import OrderedDict
from typing import Generic, Optional, TypeVar

K = TypeVar("K")
V = TypeVar("V")


class LRUCache(Generic[K, V]):
    """Fixed-capacity LRU cache. get/put are O(1) amortised."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: "OrderedDict[K, V]" = OrderedDict()

    def get(self, key: K) -> Optional[V]:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: K, value: V) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            evicted, _ = self._data.popitem(last=False)
            self._evicted = evicted  # for inspection in tests

    def __len__(self) -> int:
        return len(self._data)

    def __contains__(self, key: object) -> bool:
        return key in self._data


if __name__ == "__main__":
    cache: LRUCache[str, int] = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1          # 'a' becomes most recent
    cache.put("c", 3)                   # evicts 'b'
    assert "b" not in cache
    assert cache.get("b") is None
    assert len(cache) == 2
    print("ok")
```

`OrderedDict.move_to_end` keeps it O(1) without writing a linked list by hand. Missing keys return `None`, so store a sentinel if you need to cache `None` itself.

```cpp
#include <cstdint>
#include <iostream>

// Newton's method on integers: returns floor(sqrt(n)), exact for all uint64_t.
std::uint64_t isqrt(std::uint64_t n) {
    if (n < 2) return n;

    std::uint64_t x = n;
    std::uint64_t y = (x + 1) / 2;
    while (y < x) {
        x = y;
        y = (x + n / x) / 2;
    }
    return x;
}

int main() {
    const std::uint64_t tests[] = {0, 1, 2, 3, 4, 15, 16, 17, 999999999999ULL};
    for (std::uint64_t v : tests) {
        std::uint64_t r = isqrt(v);
        std::cout << v << " -> " << r
                  << (r * r <= v && (r + 1) * (r + 1) > v ? "  ok" : "  BAD")
                  << '\n';
    }
    return 0;
}
```

The loop terminates because `y` decreases strictly until it drops below `x`; integer division never overflows since `n / x <= n` and `x >= 1` whenever `n >= 2`.

