```cpp
#include <cstddef>
#include <stdexcept>
#include <string>
#include <utility>

template <typename T>
class Stack {
public:
    Stack() = default;

    explicit Stack(std::size_t cap) : cap_(cap ? cap : 1), data_(new T[cap_]) {}

    Stack(const Stack& other) : cap_(other.size_), size_(other.size_),
                                data_(new T[cap_]) {
        for (std::size_t i = 0; i < size_; ++i) data_[i] = other.data_[i];
    }

    Stack(Stack&& other) noexcept
        : cap_(other.cap_), size_(other.size_), data_(other.data_) {
        other.data_ = nullptr;
        other.cap_ = other.size_ = 0;
    }

    Stack& operator=(const Stack& other) {
        if (this != &other) {
            Stack tmp(other);
            swap(tmp);
        }
        return *this;
    }

    Stack& operator=(Stack&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            cap_ = other.cap_;
            size_ = other.size_;
            data_ = other.data_;
            other.data_ = nullptr;
            other.cap_ = other.size_ = 0;
        }
        return *this;
    }

    ~Stack() { delete[] data_; }

    void push(const T& v) { push_impl(v); }
    void push(T&& v) { push_impl(std::move(v)); }

    T pop() {
        if (size_ == 0) throw std::out_of_range("pop on empty stack");
        return std::move(data_[--size_]);
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    void swap(Stack& o) noexcept {
        std::swap(cap_, o.cap_);
        std::swap(size_, o.size_);
        std::swap(data_, o.data_);
    }

    template <typename U>
    void push_impl(U&& v) {
        if (size_ == cap_) grow();
        data_[size_++] = std::forward<U>(v);
    }

    void grow() {
        std::size_t ncap = cap_ * 2;
        T* ndata = new T[ncap];
        for (std::size_t i = 0; i < size_; ++i) ndata[i] = std::move(data_[i]);
        delete[] data_;
        data_ = ndata;
        cap_ = ncap;
    }

    std::size_t cap_ = 0;
    std::size_t size_ = 0;
    T* data_ = nullptr;
};

int main() {
    Stack<std::string> s;
    s.push("a");
    s.push(std::string("b"));
    Stack<std::string> t = std::move(s);
    if (s.size() != 0) return 1;
    if (t.pop() != "b" || t.pop() != "a") return 1;
    return 0;
}
```

All five special members are defined: copy uses copy-and-swap for exception safety, move steals the buffer and nulls the source, and `push` has both lvalue and rvalue overloads plus geometric growth.

