use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum ParseError {
    EmptyKey(usize),
    MissingEquals(String),
}

pub fn parse_kv(line: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    if line.trim().is_empty() {
        return Ok(map);
    }
    for (idx, raw) in line.split(',').enumerate() {
        let pair = raw.trim();
        let mut parts = pair.splitn(2, '=');
        let key = parts.next().unwrap_or("").trim();
        let value = match parts.next() {
            Some(v) => v.trim(),
            None => return Err(ParseError::MissingEquals(pair.to_string())),
        };
        if key.is_empty() {
            return Err(ParseError::EmptyKey(idx));
        }
        map.insert(key.to_string(), value.to_string());
    }
    Ok(map)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ok_and_trim() {
        let m = parse_kv("a=1, b = two ,c=").unwrap();
        assert_eq!(m.get("a").unwrap(), "1");
        assert_eq!(m.get("b").unwrap(), "two");
        assert_eq!(m.get("c").unwrap(), "");
    }

    #[test]
    fn errors() {
        assert_eq!(parse_kv("nope"), Err(ParseError::MissingEquals("nope".into())));
        assert_eq!(parse_kv("=x"), Err(ParseError::EmptyKey(0)));
    }

    #[test]
    fn empty_line() {
        assert!(parse_kv("   ").unwrap().is_empty());
    }
}
```

