```c
#include <stdbool.h>
#include <stdio.h>

#define RB_CAP 8

typedef struct {
    int buf[RB_CAP];
    size_t head;  /* next read index */
    size_t len;
} ringbuf;

static void rb_init(ringbuf *rb) {
    rb->head = 0;
    rb->len = 0;
}

static bool rb_push(ringbuf *rb, int v) {
    if (rb->len == RB_CAP) return false;
    rb->buf[(rb->head + rb->len) % RB_CAP] = v;
    rb->len++;
    return true;
}

static bool rb_pop(ringbuf *rb, int *out) {
    if (rb->len == 0) return false;
    *out = rb->buf[rb->head];
    rb->head = (rb->head + 1) % RB_CAP;
    rb->len--;
    return true;
}

int main(void) {
    ringbuf rb;
    rb_init(&rb);
    int v;

    for (int i = 0; i < RB_CAP; i++)
        if (!rb_push(&rb, i)) return 1;
    if (rb_push(&rb, 99)) return 2;      /* full -> must fail */

    if (!rb_pop(&rb, &v) || v != 0) return 3;
    if (!rb_push(&rb, 100)) return 4;    /* wrap-around push */
    if (!rb_pop(&rb, &v) || v != 1) return 5;

    for (int i = 2; i < RB_CAP; i++)
        if (!rb_pop(&rb, &v) || v != i) return 6;
    if (!rb_pop(&rb, &v) || v != 100) return 7;
    if (rb_pop(&rb, &v)) return 8;       /* empty -> must fail */

    printf("ok\n");
    return 0;
}
```

Fully static storage, `push`/`pop` report success via `bool`, and the modulo index wraps around. The `main` checks cover full, empty, and a wrapping insert after a pop.

