```rust
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::thread;

#[derive(Debug)]
struct Counter {
    value: AtomicU64,
}

impl Counter {
    fn new() -> Self {
        Counter { value: AtomicU64::new(0) }
    }

    fn increment(&self) -> u64 {
        self.value.fetch_add(1, Ordering::Relaxed) + 1
    }

    fn get(&self) -> u64 {
        self.value.load(Ordering::Relaxed)
    }
}

fn main() {
    let counter = Arc::new(Counter::new());
    let threads: Vec<_> = (0..8)
        .map(|_| {
            let counter = Arc::clone(&counter);
            thread::spawn(move || {
                for _ in 0..100_000 {
                    counter.increment();
                }
            })
        })
        .collect();

    for handle in threads {
        handle.join().expect("worker panicked");
    }

    assert_eq!(counter.get(), 8 * 100_000);
    println!("counter = {}", counter.get());
}
```

`fetch_add` is a single atomic read-modify-write, so no lock is needed and no increment is lost. `Relaxed` is sound here because the final `join` plus `load` establishes the happens-before edge; it can be all 8 threads racing with no effect on the total.

Here's an expand-around-center solution, O(n^2) time and O(1) space:

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(lo: int, hi: int):
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi  # last valid bounds

    for i in range(len(s)):
        l1, r1 = expand(i, i)        # odd-length center
        l2, r2 = expand(i, i + 1)    # even-length center
        for l, r in ((l1, r1), (l2, r2)):
            if r - l > end - start:
                start, end = l, r

    return s[start:end]


if __name__ == "__main__":
    cases = {"": "", "a": "a", "babad": "bab", "cbbd": "bb", "forgeeksskeegfor": "geeksskeeg"}
    for text, expected in cases.items():
        got = longest_palindrome(text)
        assert got == expected, (text, got, expected)
        print(repr(text), "->", repr(got))
```

The `expand` helper returns the last matching bounds after stepping one past them, so the slice `s[start:end]` is correct. Even-length centers are covered by the `(i, i+1)` call.

Iterative reversal, one pass, no allocation:

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (!n) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next; /* save before relinking */
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_and_free(Node *head) {
    for (Node *cur = head; cur; ) {
        Node *next = cur->next;
        printf("%d%s", cur->value, next ? " -> " : "\n");
        free(cur);
        cur = next;
    }
}

int main(void) {
    Node *head = NULL;              /* empty list case */
    head = reverse(head);
    printf("empty: %s\n", head ? "non-null" : "null");

    for (int i = 5; i >= 1; --i)
        head = push(head, i);
    printf("before: ");
    for (Node *cur = head; cur; cur = cur->next)
        printf("%d%s", cur->value, cur->next ? " -> " : "\n");

    head = reverse(head);
    printf("after:  ");
    for (Node *cur = head; cur; cur = cur->next)
        printf("%d%s", cur->value, cur->next ? " -> " : "\n");

    print_and_free(head);
    return 0;
}
```

Each node is freed exactly once; the empty list is handled because the loop body never runs when `head` is NULL.

