```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

template <std::size_t N>
class RingBuffer {
public:
    explicit RingBuffer() : head_(0), tail_(0), count_(0) {}

    void push(double value) {
        if (count_ == N) {
            throw std::overflow_error("ring buffer is full");
        }
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++count_;
    }

    std::optional<double> pop_front() {
        if (count_ == 0) {
            return std::nullopt;
        }
        double value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    std::size_t capacity() const { return N; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }

private:
    std::array<double, N> data_{};
    std::size_t head_, tail_, count_;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1.5);
    rb.push(2.5);
    rb.push(3.5);
    std::cout << "size=" << rb.size() << " full=" << rb.full() << '\n';

    try {
        rb.push(4.5);
    } catch (const std::overflow_error& e) {
        std::cout << "expected: " << e.what() << '\n';
    }

    while (auto v = rb.pop_front()) {
        std::cout << "pop " << *v << '\n';
    }
    std::cout << "empty=" << rb.empty() << ", pop on empty="
              << (rb.pop_front().has_value() ? "value" : "nullopt") << '\n';
}
```

The modulo arithmetic wraps both indices without branching; `count_` distinguishes full from empty states that a head/tail comparison alone cannot. Overflow and empty-pop both surface explicitly instead of corrupting data.

