    int distinct = 0;

    for (; *s; ++s) {
        unsigned char c = (unsigned char)*s; /* avoid negative ctype args */
        if (!isalpha(c)) {
            continue;
        }
        int idx = tolower(c) - 'a';
        if (!seen[idx]) {
            seen[idx] = 1;
            ++distinct;
        }
    }
    return distinct == ALPHABET;
}

int main(void) {
    const char *pangram = "The quick brown fox jumps over the lazy dog";
    const char *short_text = "hello, world";
    const char *empty = "";

    printf("pangram: %s\n", is_pangram(pangram) ? "yes" : "no");
    printf("short:   %s\n", is_pangram(short_text) ? "yes" : "no");
    printf("empty:   %s\n", is_pangram(empty) ? "yes" : "no");
    return 0;
}
```

The `(unsigned char)` cast before `isalpha`/`tolower` matters: passing a negative `char` (e.g. a UTF-8 byte) to ctype functions is undefined behaviour. `tolower` then maps everything into the `'a'..'z'` range safely, and empty input returns false as expected.

```rust
use std::cmp::Reverse;
use std::collections::BinaryHeap;

pub fn merge_k_sorted(lists: &[Vec<i32>]) -> Vec<i32> {
    let mut heap: BinaryHeap<Reverse<(i32, usize, usize)>> = BinaryHeap::new();

    for (list_idx, list) in lists.iter().enumerate() {
        if let Some(&first) = list.first() {
            heap.push(Reverse((first, list_idx, 0)));
        }
    }

    let total: usize = lists.iter().map(Vec::len).sum();
    let mut merged = Vec::with_capacity(total);

    while let Some(Reverse((value, list_idx, elem_idx))) = heap.pop() {
        merged.push(value);
        let next = elem_idx + 1;
        if let Some(&value) = lists[list_idx].get(next) {
            heap.push(Reverse((value, list_idx, next)));
        }
    }

    merged
}

fn main() {
    let lists = vec![vec![1, 4, 7], vec![2, 5, 8], vec![3, 6, 9], vec![]];
    let merged = merge_k_sorted(&lists);
    assert_eq!(merged, (1..=9).collect::<Vec<_>>());
    assert!(merge_k_sorted(&[]).is_empty());
    assert_eq!(merge_k_sorted(&[vec![], vec![]]), Vec::<i32>::new());
    println!("{:?}", merged);
}
```

The heap holds one element per non-empty list, so its size is k, not the total. `Reverse` flips the ordering for a min-heap, and the `(value, list_idx, elem_idx)` tuple makes ties deterministic. Total cost is O(N log k).

```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

// Returns the index of `target`, or std::nullopt if absent.
// Precondition: `data` is sorted ascending.
std::optional<std::size_t> binary_search(const std::vector<int>& data, int target) {
    std::size_t lo = 0;
    std::size_t hi = data.size(); // half-open: [lo, hi)

    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2; // avoids overflow, unlike (lo+hi)/2
        if (data[mid] == target) {
            return mid;
        }
        if (data[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return std::nullopt;
}

int main() {
    const std::vector<int> data = {-5, 0, 3, 3, 7, 11, 42};

    auto check = [&](int target, bool present) {
        auto found = binary_search(data, target);
        bool ok = found.has_value() == present;
        if (found && data[*found] != target) ok = false;
        std::cout << "target=" << target << " -> "
                  << (found ? std::to_string(*found) : "absent")
                  << (ok ? "" : "  [FAIL]") << '\n';
    };

    check(-5, true);
    check(42, true);
    check(4, false);
    check(-100, false);
    check(100, false);
    std::cout << "empty -> "
              << (binary_search({}, 1).has_value() ? "found" : "absent") << '\n';
}
```

The half-open interval `[lo, hi)` removes the classic off-by-one bugs at the ends. `lo + (hi - lo) / 2` cannot overflow for large vectors, unlike the naive midpoint. Duplicates are fine: the function returns whichever matching index the search lands on.

```cpp
#include <array>
#include <cstddef>
#include <cstdio>
#include <optional>

template <std::size_t N>
class CircularBuffer {
public:
    bool push(int value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full()  const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    CircularBuffer<3> buf;
    if (!buf.push(10)) std::puts("unexpected full");
    buf.push(20);
    buf.push(30);
    if (buf.push(40)) std::puts("should be full");
    while (auto v = buf.pop()) std::printf("%d\n", *v);
    if (buf.pop() != std::nullopt) std::puts("should be empty");
    std::printf("size=%zu\n", buf.size());
}
