fn reverse_words_in_place(buf: &mut Vec<u8>) {
    fn reverse(slice: &mut [u8]) {
        let mut i = 0;
        let mut j = slice.len();
        while i + 1 < j {
            slice.swap(i, j - 1);
            i += 1;
            j -= 1;
        }
        if slice.len() > 1 && i < j {
            slice.swap(i, j - 1);
        }
    }

    reverse(buf.as_mut_slice());
    let mut start = 0;
    for i in 0..=buf.len() {
        if i == buf.len() || buf[i] == b' ' || buf[i] == b'\t' {
            reverse(&mut buf[start..i]);
            start = i + 1;
        }
    }
}

fn main() {
