    reverse_words_in_place(&mut v);
    assert_eq!(String::from_utf8(v).unwrap(), "rust\tworld hello");

    let mut empty: Vec<u8> = Vec::new();
    reverse_words_in_place(&mut empty);
    assert!(empty.is_empty());

    let mut one = b"solo".to_vec();
    reverse_words_in_place(&mut one);
    assert_eq!(one, b"solo");

