#include <cstdio>

struct Node {
    int value;
    Node* next;
};

Node* merge(Node* a, Node* b) {
    Node dummy{0, nullptr};
    Node* tail = &dummy;
    while (a && b) {
        if (a->value <= b->value) { tail->next = a; a = a->next; }
        else                      { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

static void free_list(Node* head) {
    while (head) { Node* n = head->next; delete head; head = n; }
}

int main() {
    Node* a = new Node{1, new Node{4, new Node{7, nullptr}}};
    Node* b = new Node{2, new Node{3, new Node{9, nullptr}}};
    Node* m = merge(a, b);
    for (Node* p = m; p; p = p->next) std::printf("%d ", p->value);
    std::puts("");           // 1 2 3 4 7 9
    free_list(m);
}
