    assert(head->next->next->next == nullptr);

    assert(reverse_list(nullptr) == nullptr);

    while (head != nullptr) {
        Node* nxt = head->next;
        delete head;
        head = nxt;
    }
    std::cout << "all tests passed\n";
    return 0;
}
