bool isPalindrome(const std::string& s) {
    std::size_t left = 0;
    std::size_t right = s.size();
    while (left < right) {
        if (!std::isalnum(static_cast<unsigned char>(s[left]))) {
            ++left;
            continue;
        }
        if (!std::isalnum(static_cast<unsigned char>(s[right - 1]))) {
            --right;
            continue;
