```python
class BoundedStack:
    """A stack that holds at most `capacity` items."""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._items: list = []

    def push(self, item) -> None:
        if len(self._items) >= self.capacity:
            raise OverflowError(f"stack full (capacity {self.capacity})")
        self._items.append(item)

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self):
        if not self._items:
            raise IndexError("peek from empty stack")
        return self._items[-1]

    def __len__(self) -> int:
        return len(self._items)


if __name__ == "__main__":
    s = BoundedStack(2)
    s.push(10)
    s.push(20)
    assert s.peek() == 20
    try:
        s.push(30)
    except OverflowError:
        pass
    else:
        raise AssertionError("expected OverflowError")
    assert s.pop() == 20
    assert len(s) == 1
    try:
        BoundedStack(0)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
    print("all checks passed")
```

Bounded capacity is enforced at push time, so the invariant `0 <= len <= capacity` always holds. `peek` does not remove, and each failure path raises a distinct, descriptive exception.

