use std::collections::HashMap;

pub fn top_n_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '\'')
            .collect::<String>()
            .to_lowercase();
        if cleaned.is_empty() {
            continue;
        }
        *counts.entry(cleaned).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the quick the Fox; the fox jumped";
    for (word, count) in top_n_words(text, 3) {
        println!("{word}: {count}");
    }
    assert!(top_n_words("", 5).is_empty());
    assert_eq!(top_n_words("a a b", 2)[0], ("a".to_string(), 2));
}
