pub fn fib(n: u64) -> u128 {
    // Returns (F(k), F(k+1)) using fast doubling.
    fn pair(k: u64) -> (u128, u128) {
        if k == 0 {
            return (0, 1);
        }
        let (a, b) = pair(k >> 1);
        let c = a * (2 * b - a);
        let d = a * a + b * b;
        if k & 1 == 0 {
            (c, d)
        } else {
            (d, c + d)
        }
    }
    pair(n).0
}

fn main() {
    assert_eq!(fib(0), 0);
    assert_eq!(fib(1), 1);
    assert_eq!(fib(10), 55);
    assert_eq!(fib(50), 12586269025);
    assert_eq!(fib(90), 2880067194370816120);
    println!("{}", fib(100));
}
```

Fast doubling runs in O(log n) multiplication steps instead of O(n). It is defined recursively here but the depth is only log₂n, so it never risks a deep stack; `u128` holds F(186) before overflowing.

