    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            open.push(c);
        } else if (auto it = closing.find(c); it != closing.end()) {
            if (open.empty() || open.top() != it->second) {
                return false;
            }
            open.pop();
        }
    }
    return open.empty();
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_balanced("{[()]}") << '\n';
    std::cout << is_balanced("([)]") << '\n';
    std::cout << is_balanced("") << '\n';
    std::cout << is_balanced("(((") << '\n';
    return 0;
}
```

A stack tracks unmatched openers; any closer must match the top or the function returns false immediately. The final `open.empty()` catches a leftover unclosed opener, and an empty string is balanced by definition.

