def flatten(nested, _seen=None):
    if _seen is None:
        _seen = set()
    flat = []
    for item in nested:
        if isinstance(item, list):
            ident = id(item)
            if ident in _seen:
                raise ValueError("cycle detected in nested list")
            _seen.add(ident)
            flat.extend(flatten(item, _seen))
            _seen.discard(ident)
        else:
            flat.append(item)
    return flat


