pub fn is_valid_ipv4(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return false;
    }
    for part in parts {
        if part.is_empty() || part.len() > 3 {
            return false;
        }
        if part.len() > 1 && part.starts_with('0') {
            return false;
        }
        if !part.bytes().all(|b| b.is_ascii_digit()) {
            return false;
        }
        match part.parse::<u16>() {
            Ok(n) if n <= 255 => {}
            _ => return false,
        }
    }
    true
}

fn main() {
    let cases = [
        ("192.168.0.1", true),
        ("255.255.255.255", true),
        ("0.0.0.0", true),
        ("256.1.1.1", false),
        ("1.2.3", false),
        ("1.2.3.4.5", false),
        ("01.2.3.4", false),
        ("1.2.3.", false),
        ("", false),
    ];
    for (s, expected) in cases {
        let got = is_valid_ipv4(s);
        assert_eq!(got, expected, "input {s} expected {expected} got {got}");
    }
    println!("all ipv4 tests passed");
}
```

Leading zeros are rejected (`01.2.3.4`) because most parsers treat them as octal ambiguity. `parse::<u16>` avoids overflow on very long all-digit segments, and the length cap keeps behaviour cheap.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) {
        perror("malloc");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static int equals(const Node *a, const int *expected, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        if (a == NULL || a->value != expected[i]) return 0;
        a = a->next;
    }
    return a == NULL;
}

int main(void) {
    if (reverse(NULL) != NULL) return 1;

    Node *list = NULL;
    for (int i = 1; i <= 4; ++i) list = push(list, i);  /* 4,3,2,1 */
    list = reverse(list);                              /* 1,2,3,4 */

    const int expected[] = {1, 2, 3, 4};
    if (!equals(list, expected, 4)) {
        fprintf(stderr, "reverse failed\n");
        return 1;
    }

    while (list != NULL) {
        Node *next = list->next;
        free(list);
        list = next;
    }
    puts("reverse test passed");
    return 0;
}
```

The traversal keeps a `next` pointer before rewiring `head->next`, so no node is lost. `reverse(NULL)` returns `NULL` cleanly, which covers the empty-list case.

```rust
#[derive(Debug, PartialEq)]
pub enum BalanceError {
    UnmatchedClose(usize),
    UnclosedOpen(usize),
    Mismatch { open_index: usize, close_index: usize },
}

pub fn check_balance(s: &str) -> Result<(), BalanceError> {
    let mut stack: Vec<(char, usize)> = Vec::new();
    let pairs = |open: char| match open {
        '(' => ')',
        '[' => ']',
        '{' => '}',
        _ => unreachable!(),
    };

    for (i, c) in s.char_indices() {
        match c {
            '(' | '[' | '{' => stack.push((c, i)),
            ')' | ']' | '}' => match stack.pop() {
                Some((open, open_index)) if pairs(open) == c => {}
                Some((_, open_index)) => {
                    return Err(BalanceError::Mismatch { open_index, close_index: i })
                }
                None => return Err(BalanceError::UnmatchedClose(i)),
            },
            _ => {}
        }
    }

    match stack.last() {
        Some(&(_, open_index)) => Err(BalanceError::UnclosedOpen(open_index)),
        None => Ok(()),
    }
}

fn main() {
    assert_eq!(check_balance("a(b[c]{d})e"), Ok(()));
    assert_eq!(check_balance(""), Ok(()));
    assert_eq!(check_balance("([)]"), Err(BalanceError::Mismatch { open_index: 0, close_index: 2 }));
    assert_eq!(check_balance(")"), Err(BalanceError::UnmatchedClose(0)));
    assert_eq!(check_balance("("), Err(BalanceError::UnclosedOpen(0)));
    println!("all balance tests passed");
}
```

`char_indices` makes the reported offsets correct for multi-byte text, and mismatches report both the offending opener and closer. The final `stack.last()` gives the earliest unclosed opener rather than the most recent.

```cpp
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <utility>

using u64 = std::uint64_t;

// Returns (F(n), F(n+1)).
std::pair<u64, u64> fib_pair(unsigned n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);          // a = F(k), b = F(k+1)
    u64 c = a * (2 * b - a);                 // F(2k)
    u64 d = a * a + b * b;                   // F(2k+1)
    if (n & 1u) return {d, c + d};
    return {c, d};
}

// Iterative reference; overflows at the same points as fib_pair.
u64 fib_iter(unsigned n) {
    u64 a = 0, b = 1;
    for (unsigned i = 0; i < n; ++i) {
        u64 next = a + b;
        a = b;
        b = next;
    }
    return a;
}

int main() {
    if (fib_pair(0).first != 0 || fib_pair(1).first != 1) return 1;

    for (unsigned n = 0; n <= 90; ++n) {
        u64 fast = fib_pair(n).first;
        u64 slow = fib_iter(n);
        if (fast != slow) {
            std::cerr << "mismatch at n=" << n << ": " << fast << " vs " << slow << '\n';
            return 1;
        }
    }
    std::cout << "F(90) = " << fib_pair(90).first << " (checks passed)\n";
}
```

The doubling identities used are F(2k) = F(k)·(2·F(k+1) − F(k)) and F(2k+1) = F(k)² + F(k+1)². The check tops out at n=90 because F(91) exceeds `uint64_t`; past that both methods wrap together and the comparison would be meaningless.

