def parse_ipv4(s: str):
    parts = s.split(".")
    if len(parts) != 4:
        raise ValueError(f"expected 4 octets, got {len(parts)}")
    octets = []
    for p in parts:
        if not p.isdigit():
            raise ValueError(f"non-numeric octet: {p!r}")
        if len(p) > 1 and p[0] == "0":
            raise ValueError(f"leading zero in octet: {p!r}")
        v = int(p)
        if not 0 <= v <= 255:
            raise ValueError(f"octet out of range: {v}")
        octets.append(v)
    return tuple(octets)

