    std::vector<std::string> b{"dog", "racecar", "car"};
    std::cout << '"' << longest_common_prefix(b) << "\"\n"; // ""
    std::vector<std::string> c{};
    std::cout << '"' << longest_common_prefix(c) << "\"\n"; // ""
