```rust
/// A stack with a compile-time capacity, stored inline (no heap).
pub struct Stack<T, const N: usize> {
    buf: [Option<T>; N],
    len: usize,
}

impl<T, const N: usize> Stack<T, N> {
    pub fn new() -> Self {
        // [None; N] requires T: Copy; build with a const-friendly loop.
        let buf: [Option<T>; N] = std::array::from_fn(|_| None);
        Stack { buf, len: 0 }
    }

    pub fn push(&mut self, value: T) -> Result<(), T> {
        if self.len == N {
            return Err(value); // full: hand the value back
        }
        self.buf[self.len] = Some(value);
        self.len += 1;
        Ok(())
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        self.len -= 1;
        self.buf[self.len].take()
    }

    pub fn peek(&self) -> Option<&T> {
        self.buf.get(self.len.checked_sub(1)?)?.as_ref()
    }

    pub fn len(&self) -> usize {
        self.len
    }
}

fn main() {
    let mut s: Stack<i32, 2> = Stack::new();
    assert!(s.push(1).is_ok());
    assert!(s.push(2).is_ok());
    assert_eq!(s.push(3), Err(3));
    assert_eq!(s.peek(), Some(&2));
    assert_eq!(s.pop(), Some(2));
    assert_eq!(s.pop(), Some(1));
    assert_eq!(s.pop(), None);
    println!("stack ok, len={}", s.len());
}
