        raise ValueError("version must be a string")
    m = _SEMVER.match(text.strip())
    if not m:
        raise ValueError(f"invalid semver: {text!r}")
    return (
        int(m["major"]), int(m["minor"]), int(m["patch"]),
        m["pre"], m["build"],
    )

