    for bad in ["1.2", "01.2.3", "1.2.3-", "v1.2.3", ""]:
        try:
            parse_semver(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"should have rejected {bad!r}")
    print("semver tests passed")
