pub fn is_palindrome(mut x: i64) -> bool {
    // Negatives are never palindromes because of the leading '-'
    // (and i64::MIN would overflow when negated).
    if x < 0 {
        return false;
    }
    // Numbers ending in 0 (except 0 itself) cannot be palindromes.
    if x != 0 && x % 10 == 0 {
        return false;
    }
    let mut reversed: i64 = 0;
    // Reverse only until reversed >= x; avoids any overflow.
    while x > reversed {
        reversed = reversed * 10 + x % 10;
        x /= 10;
    }
    // Even length: x == reversed. Odd length: x == reversed / 10.
    x == reversed || x == reversed / 10
}

fn main() {
    assert!(is_palindrome(0));
    assert!(is_palindrome(7));
    assert!(is_palindrome(121));
    assert!(is_palindrome(1221));
    assert!(!is_palindrome(123));
    assert!(!is_palindrome(-121));
    assert!(!is_palindrome(10));
    assert!(!is_palindrome(i64::MAX));
    println!("all palindrome checks passed");
}
```
