```cpp
#include <array>
#include <iostream>
#include <optional>
#include <cstddef>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        if (full()) head = (head + 1) % N;  // overwrite oldest
        else      ++size_;
        data_[tail] = value;
        tail = (tail + 1) % N;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = data_[head];
        head = (head + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full()  const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head = 0, tail = 0, size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int v : {1, 2, 3, 4}) rb.push(v);  // 1 is overwritten
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n';  // prints 2 3 4
    std::cout << "empty: " << std::boolalpha << rb.empty() << '\n';
}
```
Wrapping `head` and `tail` modulo `N` keeps the buffer circular; when full, `push` advances `head` to drop the oldest element, and `size_` distinguishes full from empty when head equals tail.

