    if (!n) { perror("malloc"); exit(1); }
    n->value = v;
    n->next = head;
    return n;
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 4; i++) head = push(head, i);
    head = reverse(head);
    for (Node *n = head; n; n = n->next) printf("%d ", n->value);
    printf("\n");
    while (head) {
        Node *tmp = head->next;
        free(head);
        head = tmp;
    }
    return 0;
}
```

Prints `1 2 3 4` from a list built as `4 3 2 1`. An empty list returns `NULL` cleanly because the loop body never runs.

