```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    def expand(lo: int, hi: int) -> str:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return s[lo + 1:hi]

    best = ""
    for i in range(len(s)):
        odd = expand(i, i)
        even = expand(i, i + 1)
        cand = odd if len(odd) >= len(even) else even
        if len(cand) > len(best):
            best = cand
    return best


if __name__ == "__main__":
    tests = {"babad": {"bab", "aba"}, "cbbd": {"bb"}, "": {""},
             "a": {"a"}, "forgeeksskeegfor": {"geeksskeeg"},
             "abacdfgdcaba": {"aba", "cdc"}}
    for text, expected in tests.items():
        got = longest_palindrome(text)
        assert got in expected, (text, got, expected)
    print("all passed")
```

Expanding around each of `2n-1` centers gives `O(n^2)` worst case with `O(1)` extra memory. The empty string returns `""` and the assertion set allows either valid palindrome on ties.

