```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t len;
    size_t cap;
} Vec;

void vec_init(Vec *v) {
    v->data = NULL;
    v->len = 0;
    v->cap = 0;
}

int vec_push(Vec *v, int value) {
    if (v->len == v->cap) {
        size_t next = v->cap ? v->cap * 2 : 4;
        int *grown = realloc(v->data, next * sizeof(int));
        if (!grown) return -1;
        v->data = grown;
        v->cap = next;
    }
    v->data[v->len++] = value;
    return 0;
}

void vec_free(Vec *v) {
    free(v->data);
    v->data = NULL;
    v->len = v->cap = 0;
}

int main(void) {
    Vec v;
    vec_init(&v);
    for (int i = 0; i < 100; ++i) {
        if (vec_push(&v, i * i) != 0) { fprintf(stderr, "oom\n"); return 1; }
    }
    printf("len=%zu cap=%zu last=%d\n", v.len, v.cap, v.data[v.len - 1]);
    vec_free(&v);
    return 0;
}
