uint64_t fib(int n) {
    if (n < 0) return 0;
    if (n <= 1) return static_cast<uint64_t>(n);
    auto it = memo.find(n);
    if (it != memo.end()) return it->second;
    uint64_t v = fib(n - 1) + fib(n - 2);
    memo[n] = v;
    return v;
