import hashlib
import os


def file_sha256(path):
    """Return the hex SHA-256 of a file, reading in 64 KiB chunks."""
    h = hashlib.sha256()
    try:
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(65536), b""):
                h.update(chunk)
    except FileNotFoundError:
        return None
    except IsADirectoryError:
        return None
    return h.hexdigest()


def find_duplicates(directory):
    """Group files in a directory by content hash and return groups with >1 file."""
    by_hash = {}
    for name in sorted(os.listdir(directory)):
        full = os.path.join(directory, name)
        if not os.path.isfile(full):
            continue
        digest = file_sha256(full)
        if digest is None:
            continue
        by_hash.setdefault(digest, []).append(full)
    return [paths for paths in by_hash.values() if len(paths) > 1]


if __name__ == "__main__":
    import sys
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    if not os.path.isdir(target):
        print(f"not a directory: {target}")
        sys.exit(1)
    groups = find_duplicates(target)
    if not groups:
        print("no duplicate files found")
    else:
        for group in groups:
            print(f"--- {len(group)} identical files ---")
            for path in group:
                print(path)
