// Evaluate a string of single-character additions and subtractions.
// Example: "10+20-5" prints 25. Spaces are ignored; an empty expression
// or a leading operator is rejected with a message.
int main() {
    std::string expr;
    if (!(std::cin >> expr)) {
        std::cerr << "no input\n";
        return 1;
    }
    long long total = 0;
    long long current = 0;
    int sign = 1;
    bool saw_digit = false;
    for (char ch : expr) {
        if (std::isdigit(static_cast<unsigned char>(ch))) {
            current = current * 10 + (ch - '0');
            saw_digit = true;
        } else if (ch == '+' || ch == '-') {
            if (!saw_digit) {
                std::cerr << "malformed expression\n";
                return 1;
            }
            total += sign * current;
            current = 0;
            saw_digit = false;
            sign = (ch == '+') ? 1 : -1;
        } else {
            std::cerr << "invalid character: " << ch << '\n';
            return 1;
        }
    }
    if (!saw_digit) {
        std::cerr << "expression ends with an operator\n";
        return 1;
    }
    total += sign * current;
    std::cout << total << '\n';
    return 0;
}
