// Convert a decimal string to a u64 without panicking on overflow.
fn parse_u64(text: &str) -> Option<u64> {
    let mut value: u64 = 0;
    if text.is_empty() {
        return None;
    }
    for ch in text.chars() {
        let digit = ch.to_digit(10)? as u64;
        value = value.checked_mul(10)?;
        value = value.checked_add(digit)?;
    }
    Some(value)
}

// FizzBuzz for a single number, returning a String.
fn fizzbuzz(n: u64) -> String {
    match (n % 3, n % 5) {
        (0, 0) => "FizzBuzz".to_string(),
        (0, _) => "Fizz".to_string(),
        (_, 0) => "Buzz".to_string(),
        _ => n.to_string(),
    }
}

