static int gcd2(int a, int b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int gcd_array(const int *arr, size_t n) {
    if (n == 0) return 0;       /* define gcd of empty set as 0 */
    int g = arr[0];
    for (size_t i = 1; i < n; i++) {
        g = gcd2(g, arr[i]);
        if (g == 1) break;       /* can't get smaller */
    }
    return g;
}

