    std::cout << (parse_number<int>("4x").has_value() ? "yes" : "no") << '\n'; // no
    std::cout << (parse_number<int>("").has_value() ? "yes" : "no") << '\n';   // no
    std::cout << parse_number<double>("3.14").value_or(0.0) << '\n';   // 3.14
    return 0;
