std::pair<uint64_t, uint64_t> fib_pair(uint64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    uint64_t c = a * (2 * b - a);
    uint64_t d = a * a + b * b;
    if (n & 1) return {d, c + d};
    return {c, d};
