bool is_palindrome(const char *s) {
    if (s == NULL) {
        return false;
    }
    const char *left = s;
    const char *right = s;
    while (*right) {
        ++right;
    }
    if (right != s) {
        --right;
    }
    while (left < right) {
        if (!isalnum((unsigned char)*left)) {
            ++left;
        } else if (!isalnum((unsigned char)*right)) {
            --right;
        } else if (tolower((unsigned char)*left) != tolower((unsigned char)*right)) {
            return false;
        } else {
            ++left;
            --right;
        }
    }
    return true;
}
