import heapq
from typing import Iterable


class RunningMedian:
    """Maintain a running median with two heaps in O(log n) per insert."""

    def __init__(self) -> None:
        self._low: list[float] = []   # max-heap (store negated)
        self._high: list[float] = []  # min-heap

    def add(self, value: float) -> None:
        heapq.heappush(self._low, -value)
        heapq.heappush(self._high, -heapq.heappop(self._low))
        if len(self._high) > len(self._low):
            heapq.heappush(self._low, -heapq.heappop(self._high))

    def median(self) -> float:
        if not self._low:
            raise ValueError("no values added")
        if len(self._low) > len(self._high):
            return -self._low[0]
        return (-self._low[0] + self._high[0]) / 2.0


def medians_stream(values: Iterable[float]) -> list[float]:
    rm = RunningMedian()
    out = []
    for v in values:
        rm.add(v)
        out.append(rm.median())
    return out


if __name__ == "__main__":
    assert medians_stream([1, 2, 3]) == [1.0, 1.5, 2.0]
    assert medians_stream([5, 3, 8]) == [5.0, 4.0, 5.0]
