/* Parse a decimal integer from s.
 * Returns true on success and stores the value in *out.
 * Returns false on empty input, non-numeric input, or overflow. */
bool parse_int(const char *s, long *out) {
    if (s == NULL || *s == '\0') {
        return false;
    }

    const char *p = s;
    bool negative = false;
    if (*p == '+' || *p == '-') {
        negative = (*p == '-');
        p++;
    }
    if (*p == '\0') {
        return false; /* sign only */
    }

    long value = 0;
    for (; *p != '\0'; p++) {
        if (*p < '0' || *p > '9') {
            return false;
        }
        int digit = *p - '0';
        if (value > (LONG_MAX - digit) / 10) {
            return false; /* would overflow */
        }
        value = value * 10 + digit;
    }

    if (negative) {
        value = -value;
    }
    *out = value;
    return true;
}
