from typing import Iterator

LEVELS = ("DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL")


def filter_log(path: str, min_level: str) -> Iterator[str]:
    """Yield lines at or above min_level, streaming one line at a time.

    The file is never fully loaded into memory. Malformed lines are skipped.
    """
    if min_level not in LEVELS:
        raise ValueError(f"unknown level: {min_level}")
    threshold = LEVELS.index(min_level)

    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            parts = line.split(" ", 2)
            if len(parts) < 2:
                continue
            level = parts[1].rstrip(":")
            if level not in LEVELS:
                continue
            if LEVELS.index(level) >= threshold:
                yield line.rstrip("\n")


if __name__ == "__main__":
    for entry in filter_log("server.log", "ERROR"):
        print(entry)
```

`min_level` gates the output, and unknown or malformed lines are dropped rather than raising. Because it is a generator, only one line is resident at a time regardless of file size.

```cpp
#include <cstddef>
#include <optional>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), size_(0), capacity_(capacity) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be > 0");
        }
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == capacity_; }
    std::size_t size() const { return size_; }

    // Returns false if the buffer is full and the value was dropped.
    bool push(double value) {
        if (full()) {
            return false;
        }
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % capacity_;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (empty()) {
            return std::nullopt;
        }
        double value = buf_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

private:
    std::vector<double> buf_;
    std::size_t head_, tail_, size_, capacity_;
};
```

`push` refuses overflow by returning false; `pop` returns an empty `std::optional` when there is nothing to read, so callers never read uninitialised memory.

