            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    assert!(is_balanced("{[()]}"));
    assert!(!is_balanced("{[(])}"));
    assert!(is_balanced(""));
    assert!(!is_balanced("("));
    println!("ok");
}
```

A stack is the standard tool here: each opener is pushed, each closer must match the most recent unmatched opener. The final `stack.is_empty()` catches unclosed openers, and empty input is balanced.

```cpp
#include <iostream>
#include <string>

int main() {
    long long sum = 0;
    std::string token;
    bool overflowed = false;

    while (std::cin >> token) {
        try {
            size_t pos = 0;
            long long v = std::stoll(token, &pos);
            if (pos != token.size()) break;   // trailing junk -> stop
            if (__builtin_add_overflow(sum, v, &sum)) {
                overflowed = true;
                break;
            }
        } catch (const std::exception&) {
            break;                            // not a number -> stop
        }
    }

    if (overflowed) {
        std::cout << "overflow\n";
        return 1;
    }
    std::cout << sum << '\n';
    return 0;
}
```
`std::stoll` rejects out-of-range numbers by throwing, and `__builtin_add_overflow` catches an accumulating overflow before it wraps (GCC/Clang). Example: `1 2 3 x` prints `6`.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
    std::array<T, N> buf_{};
    std::size_t head_ = 0;   // next write
    std::size_t size_ = 0;

public:
    bool full() const { return size_ == N; }
    bool empty() const { return size_ == 0; }

    bool push(const T& v) {
        if (full()) return false;
        buf_[head_] = v;
        head_ = (head_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        std::size_t tail = (head_ + N - size_) % N;
        T v = buf_[tail];
        --size_;
        return v;
    }
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;                 // full -> reject
    if (rb.pop() != std::optional<int>{1}) return 1;
    if (!rb.push(4)) return 1;                 // reuse freed slot
    std::cout << "ok\n";
}
```
`N` must be non-zero. Popping does not clear the slot; capacity is tracked by `size_`, so no sentinel value is needed and any `T` works.

