#include <stdio.h>
#include <stddef.h>
#include <string.h>

static int lower(int c) {
    if (c >= 'A' && c <= 'Z') return c + ('a' - 'A');
    return c;
}

/* Returns index of first case-insensitive occurrence of needle in hay,
   or -1 if absent. needle == "" matches at index 0. */
long ci_find(const char *hay, const char *needle) {
    size_t nlen = strlen(needle);
    if (nlen == 0) return 0;

    for (size_t i = 0; hay[i] != '\0'; ++i) {
        size_t j = 0;
        while (j < nlen && hay[i + j] != '\0' &&
               lower((unsigned char)hay[i + j]) == lower((unsigned char)needle[j])) {
            ++j;
        }
        if (j == nlen) return (long)i;
    }
    return -1;
}

int main(void) {
    if (ci_find("Hello World", "world") != 6) return 1;
    if (ci_find("abc", "ABC") != 0) return 1;
    if (ci_find("abc", "d") != -1) return 1;
    if (ci_find("short", "longer") != -1) return 1;
    if (ci_find("", "") != 0) return 1;
    if (ci_find("", "a") != -1) return 1;
    if (ci_find("h\xC3\xA9llo", "H") != 0) return 1;
    printf("ok\n");
    return 0;
}
```
The inner loop checks `hay[i + j] != '\0'` so it never reads past the end when the needle is longer than the remaining hay. Casting to `unsigned char` before `lower` avoids sign-extension on bytes above 0x7F.

