#include <ctype.h>
#include <stdio.h>
#include <string.h>

int is_palindrome(const char *s) {
    size_t i = 0;
    size_t j = strlen(s);
    while (i < j) {
        while (i < j && !isalnum((unsigned char)s[i])) i++;
        while (i < j && !isalnum((unsigned char)s[j - 1])) j--;
        if (i < j) {
            if (tolower((unsigned char)s[i]) != tolower((unsigned char)s[j - 1]))
                return 0;
            i++;
            j--;
        }
    }
    return 1;
}

int main(void) {
    const char *cases[] = {
        "A man, a plan, a canal: Panama",
        "race a car",
        "",
        "!!!",
        "No 'x' in Nixon",
    };
    for (size_t k = 0; k < sizeof(cases) / sizeof(cases[0]); k++)
        printf("%s -> %d\n", cases[k], is_palindrome(cases[k]));
    return 0;
}
```

Uses two indices closing inward, skipping non-alphanumerics on both ends. Casts to `unsigned char` before `isalnum`/`tolower` so negative char values are safe. Empty and punctuation-only strings count as palindromes.

```python
def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring (first one on ties)."""
    if not s:
        return ""
    start, end = 0, 0

    def expand(l: int, r: int):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - 1

    for i in range(len(s)):
        for l, r in (expand(i, i), expand(i, i + 1)):
            if r - l > end - start:
                start, end = l, r
    return s[start:end + 1]


if __name__ == "__main__":
    cases = [
        ("babad", "bab"),
        ("cbbd", "bb"),
        ("", ""),
        ("a", "a"),
        ("forgeeksskeegfor", "geeksskeeg"),
        ("\u4f60\u597d\u597d\u4f60", "\u4f60\u597d\u597d\u4f60"),
    ]
    for text, expected in cases:
        got = longest_palindrome(text)
        status = "ok" if got == expected else "FAIL"
        print(f"{text!r} -> {got!r} (expected {expected!r}) [{status}]")
