#include <iostream>
#include <stack>
#include <string>

bool isBalanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.empty();
}

int main() {
    const std::string cases[] = {"()[]{}", "([{}])", "(]", "(((", "", "{[]}" };
    for (const auto& s : cases) {
        std::cout << '"' << s << "\" -> "
                  << (isBalanced(s) ? "balanced" : "not balanced") << '\n';
    }
    return 0;
}
