import string


def validate_password(pw: str) -> tuple[bool, list[str]]:
    """Check a password against these rules and return (ok, problems):
      - at least 12 characters
      - at least one lowercase, one uppercase, one digit, one symbol
      - no whitespace characters
      - not a run of a single repeated character
    """
    problems: list[str] = []
    if len(pw) < 12:
        problems.append("must be at least 12 characters")
    if not any(c.islower() for c in pw):
        problems.append("needs a lowercase letter")
    if not any(c.isupper() for c in pw):
        problems.append("needs an uppercase letter")
    if not any(c.isdigit() for c in pw):
        problems.append("needs a digit")
    if not any(c in string.punctuation for c in pw):
        problems.append("needs a symbol")
    if any(c.isspace() for c in pw):
        problems.append("must not contain whitespace")
    if pw and len(set(pw)) == 1:
        problems.append("must not be a single repeated character")
    return (not problems, problems)


