template <typename T>
T kthLargest(const std::vector<T>& v, std::size_t k) {
    if (k == 0 || k > v.size()) {
        throw std::out_of_range("k out of range");
    }
    std::priority_queue<T, std::vector<T>, std::greater<T>> heap;
    for (const T& x : v) {
        heap.push(x);
        if (heap.size() > k) {
            heap.pop();
        }
    }
    return heap.top();
}

