    for (std::size_t k = 1; k <= v.size(); ++k) {
        std::cout << "k=" << k << " -> " << kthLargest(v, k) << '\n';
    }
    try {
        kthLargest(v, 0);
    } catch (const std::out_of_range& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
