#include <stdio.h>

/* Computes base^exp. Negative exponents return 0 for |base| != 1, since the
   result is not an integer; 1 and -1 are handled exactly. */
long long ipow(long long base, long long exp) {
    if (exp < 0) {
        if (base == 1) return 1;
        if (base == -1) return (exp % 2 == 0) ? 1 : -1;
        return 0;
    }
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result *= base;
        base *= base;
        exp >>= 1;
    }
    return result;
}

int main(void) {
    printf("%lld\n", ipow(2, 10));   /* 1024 */
    printf("%lld\n", ipow(3, 0));    /* 1 */
    printf("%lld\n", ipow(5, -2));   /* 0 */
    printf("%lld\n", ipow(-1, 7));   /* -1 */
    printf("%lld\n", ipow(10, 6));   /* 1000000 */
    return 0;
