    size_t count;
} ring_t;

static void ring_init(ring_t *r) { r->head = r->tail = r->count = 0; }

static bool ring_push(ring_t *r, int value) {
    if (r->count == RING_CAP) return false;   /* full */
    r->data[r->head] = value;
    r->head = (r->head + 1) % RING_CAP;
    r->count++;
    return true;
}

static bool ring_pop(ring_t *r, int *out) {
    if (r->count == 0) return false;          /* empty */
    *out = r->data[r->tail];
    r->tail = (r->tail + 1) % RING_CAP;
    r->count--;
    return true;
}

int main(void) {
    ring_t r;
    ring_init(&r);

    for (int i = 0; i < RING_CAP; i++) {
        if (!ring_push(&r, i * 10)) { printf("unexpected full\n"); return 1; }
    }
    if (ring_push(&r, 999)) { printf("should have been full\n"); return 1; }

    int v;
    while (ring_pop(&r, &v)) {
        printf("%d\n", v);   /* 0 10 20 30 40 50 60 70 */
    }
    if (ring_pop(&r, &v)) { printf("should have been empty\n"); return 1; }
    return 0;
}
