#include <condition_variable>
#include <cstddef>
#include <iostream>
#include <mutex>
#include <thread>
#include <vector>

class Semaphore {
public:
    explicit Semaphore(std::size_t permits) : permits_(permits) {}

    Semaphore(const Semaphore&) = delete;
    Semaphore& operator=(const Semaphore&) = delete;

    void acquire() {
        std::unique_lock<std::mutex> lock(mu_);
        cv_.wait(lock, [this] { return permits_ > 0; });
        --permits_;
    }

    void release() {
        {
            std::lock_guard<std::mutex> lock(mu_);
            ++permits_;
        }
        cv_.notify_one();
    }

private:
    std::mutex mu_;
    std::condition_variable cv_;
    std::size_t permits_;
};

int main() {
    Semaphore sem(2);           // at most 2 threads in the section
    std::mutex io;
    auto worker = [&](int id) {
        sem.acquire();
        { std::lock_guard<std::mutex> g(io); std::cout << "worker " << id << " in\n"; }
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
        sem.release();
    };

    std::vector<std::thread> pool;
    for (int i = 0; i < 6; ++i) pool.emplace_back(worker, i);
    for (auto& t : pool) t.join();
    return 0;
}
```

Acquire waits on the predicate, so spurious wakeups are handled; release notifies after unlocking to avoid waking a thread that then blocks.

