// Returns [begin, end) index ranges for each maximal run of equal values.
std::vector<std::pair<std::size_t, std::size_t>> runs(const std::vector<int>& v) {
    std::vector<std::pair<std::size_t, std::size_t>> out;
    std::size_t i = 0;
    while (i < v.size()) {
        std::size_t j = i + 1;
        while (j < v.size() && v[j] == v[i]) ++j;
        out.emplace_back(i, j);   // half-open [i, j)
        i = j;
    }
    return out;
}

int main() {
    for (const auto& vec : std::vector<std::vector<int>>{{1, 1, 2, 2, 2, 3}, {}, {5}, {7, 7, 7}}) {
        auto r = runs(vec);
        std::cout << "[";
        for (std::size_t k = 0; k < r.size(); ++k) {
            std::cout << (k ? ", " : "") << "vals[" << r[k].first << ":" << r[k].second << ")";
        }
        std::cout << "]\n";
    }
    return 0;
}
