use std::fs;
use std::io;
use std::num::ParseIntError;

/// Sum one number per line. Blank lines are skipped.
fn sum_file(path: &str) -> Result<i64, String> {
    let text = fs::read_to_string(path).map_err(|e: io::Error| format!("read {path}: {e}"))?;
    let mut total: i64 = 0;
    for (idx, line) in text.lines().enumerate() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let n: i64 = trimmed
            .parse()
            .map_err(|e: ParseIntError| format!("line {}: {e}", idx + 1))?;
        total = total
            .checked_add(n)
            .ok_or_else(|| format!("overflow at line {}", idx + 1))?;
    }
    Ok(total)
}

fn main() {
    match sum_file("numbers.txt") {
        Ok(sum) => println!("sum = {sum}"),
        Err(msg) => eprintln!("error: {msg}"),
    }
}
