fn partition_refs<'a, T, F>(items: &'a [T], pred: F) -> (Vec<&'a T>, Vec<&'a T>)
where
    F: Fn(&T) -> bool,
{
    let mut yes: Vec<&'a T> = Vec::new();
    let mut no: Vec<&'a T> = Vec::new();
