            yes.push(item);
        } else {
            no.push(item);
        }
    }
    (yes, no)
}

fn main() {
    let data = [1, 2, 3, 4, 5, 6];
    let (evens, odds) = partition_refs(&data, |n| n % 2 == 0);
    println!("evens = {evens:?}");  // [2, 4, 6]
    println!("odds = {odds:?}");    // [1, 3, 5]

    let empty: [i32; 0] = [];
    let (yes, no) = partition_refs(&empty, |n| *n > 0);
    println!("empty: {} {}", yes.len(), no.len());  // 0 0
}
