#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static void print_list(const Node *head) {
    for (const Node *n = head; n != NULL; n = n->next)
        printf("%d%s", n->value, n->next ? " -> " : "\n");
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++)
        head = push(head, i);
    print_list(head);       /* 5 -> 4 -> 3 -> 2 -> 1 */
    head = reverse(head);
    print_list(head);       /* 1 -> 2 -> 3 -> 4 -> 5 */
    free_list(head);
    return 0;
}
