import os
import sys


def total_size(root):
    total = 0
    for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
        # Don't descend into symlinked directories.
        dirnames[:] = [
            d for d in dirnames
            if not os.path.islink(os.path.join(dirpath, d))
        ]
        for name in filenames:
            path = os.path.join(dirpath, name)
            try:
                st = os.lstat(path)
            except OSError as exc:
                print(f"skip {path}: {exc}", file=sys.stderr)
                continue
            if os.path.stat.S_ISREG(st.st_mode):
                total += st.st_size
    return total


if __name__ == "__main__":
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    print(f"{root}: {total_size(root)} bytes")
```
`os.lstat` reports the symlink itself rather than its target, so broken symlinks don't raise and symlink targets aren't double-counted.

