def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    def expand(left: int, right: int) -> str:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left + 1:right]

    best = ""
    for i in range(len(s)):
        odd = expand(i, i)
        even = expand(i, i + 1)
        for cand in (odd, even):
            if len(cand) > len(best):
                best = cand
    return best


if __name__ == "__main__":
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "abcba"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```

Runs in `O(n^2)` time and `O(1)` extra space. `expand` grows outward from a center and returns the substring between the final `left+1` and `right` indices; the empty-input guard avoids an `IndexError` on the first iteration. Unicode works because Python compares code points, so `"éé"` and emoji pairs behave like any other character.

