```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int i = 1; i <= 3; ++i) {
        std::cout << "push " << i << ": " << rb.push(i) << '\n';
    }
    std::cout << "push 4 (full): " << rb.push(4) << '\n';
    while (!rb.empty()) {
        std::cout << "pop: " << *rb.pop() << '\n';
    }
    std::cout << "pop (empty): " << rb.pop().has_value() << '\n';
    return 0;
}
```

Push overwrites nothing — when full it returns `false` and leaves the buffer intact. `pop` returns `std::optional<T>` so an empty pop is explicit instead of undefined. Requires `N > 0`; wrap-around uses modular indexing, so memory stays fixed and all operations are `O(1)`. If you want overwrite-oldest semantics instead, change `push` to advance `head_` when full.

```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 4, 6, 8, 9];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 4, 5, 6, 7, 8, 9]);

    let empty_a: [i32; 0] = [];
    let c = [1, 2, 3];
    assert_eq!(merge_sorted(&empty_a, &c), vec![1, 2, 3]);
    assert_eq!(merge_sorted(&c, &empty_a), vec![1, 2, 3]);
    assert_eq!(merge_sorted(&empty_a, &empty_a), Vec::<i32>::new());

    let dups_a = [1, 1, 3];
    let dups_b = [1, 2, 3];
    assert_eq!(merge_sorted(&dups_a, &dups_b), vec![1, 1, 1, 2, 3, 3]);

    println!("all merge_sorted assertions passed");
}
```

Uses `<=` in the comparison so equal elements take from `a` first, which keeps the merge stable. `extend_from_slice` flushes whichever side has leftovers, so empty inputs and duplicate values fall out correctly. `Vec::with_capacity` avoids reallocation. The function is `O(a.len() + b.len())` in time and allocation.

