    counts
}

fn top_n(counts: &HashMap<String, usize>, n: usize) -> Vec<(&str, usize)> {
    let mut pairs: Vec<(&str, usize)> =
        counts.iter().map(|(k, v)| (k.as_str(), *v)).collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let path = match args.get(1) {
        Some(p) => p.clone(),
        None => {
            eprintln!("usage: wordfreq <file>");
            process::exit(2);
        }
    };

    let text = match fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {path}: {e}");
            process::exit(1);
        }
    };

    let counts = word_counts(&text);
    for (word, count) in top_n(&counts, 10) {
        println!("{:>6}  {}", count, word);
    }
}
```

Lowercases and strips punctuation before counting, so "The" and "the," collapse into one key. Ties break alphabetically for deterministic output. Handles an empty file (prints nothing) and a missing path (exits with code 1 and a message on stderr). Unicode letters count via `is_alphanumeric`, so accented words survive. Build with `cargo run -- file.txt`.

```python
def is_balanced(s: str) -> bool:
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack


if __name__ == "__main__":
    cases = {
        "()": True,
        "()[]{}": True,
        "(]": False,
        "([{}])": True,
        "(((": False,
        "]": False,
        "": True,
        "a(b[c]d)e": True,
        "{[]}": True,
        "{[}]": False,
    }
    for text, expected in cases.items():
        got = is_balanced(text)
        assert got == expected, f"{text!r}: expected {expected}, got {got}"
    print("bracket balance assertions passed")
```

One pass with a stack: openers are pushed, closers must match the top. Non-bracket characters are ignored, which makes it usable on real source lines like `a(b[c]d)e`. Empty input returns `True`. An unmatched closer immediately returns `False` without touching the stack further, and a leftover opener at the end fails the final `not stack` check.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (!n) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(const Node *head) {
    for (const Node *cur = head; cur; cur = cur->next)
        printf("%d%s", cur->value, cur->next ? " -> " : "\n");
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 5; i >= 1; i--)
        list = push(list, i);

    print_list(list);          /* 1 -> 2 -> 3 -> 4 -> 5 */
    list = reverse(list);
    print_list(list);          /* 5 -> 4 -> 3 -> 2 -> 1 */
    free_list(list);
    return 0;
}
