```cpp
#include <iostream>
#include <string>
#include <stack>
#include <cstddef>

static bool balanced(const std::string& s, std::size_t& bad_pos) {
    std::stack<std::pair<char, std::size_t>> st;
    const std::string open = "([{";
    const std::string close = ")]}";

    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (open.find(c) != std::string::npos) {
            st.push({c, i});
        } else if (close.find(c) != std::string::npos) {
            if (st.empty()) {
                bad_pos = i;
                return false;
            }
            char o = st.top().first;
            st.pop();
            if (open.find(o) != close.find(c)) {
                bad_pos = i;
                return false;
            }
        }
    }

    if (!st.empty()) {
        bad_pos = st.top().second;
        return false;
    }
    return true;
}

int main() {
    for (const std::string s : {"([]{})", "(]", "((", "", "a(b)c"}) {
        std::size_t pos = 0;
        if (balanced(s, pos))
            std::cout << "OK   " << s << '\n';
        else
            std::cout << "FAIL " << s << " at index " << pos << '\n';
    }
}
