#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
double median(std::vector<T> values) {
    if (values.empty()) {
        throw std::invalid_argument("median of empty container");
    }

    const std::size_t mid = values.size() / 2;
    std::nth_element(values.begin(), values.begin() + mid, values.end());
    T upper = values[mid];

    if (values.size() % 2 == 1) {
        return static_cast<double>(upper);
    }

    auto lower_it = std::max_element(values.begin(), values.begin() + mid);
    return (static_cast<double>(*lower_it) + static_cast<double>(upper)) / 2.0;
}

int main() {
    std::cout << median<int>({7, 1, 3, 5, 9}) << '\n';   // 5
    std::cout << median<int>({4, 2, 8, 6}) << '\n';      // 5
    std::cout << median<double>({2.5}) << '\n';          // 2.5
    try {
        median<int>({});
    } catch (const std::invalid_argument& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
}
