fn parse_version(input: &str) -> Result<Version, ParseVersionError> {
    let parts: Vec<&str> = input.split('.').collect();
    if parts.len() != 3 {
        return Err(ParseVersionError(format!(
            "expected 3 dot-separated parts, got {}",
            parts.len()
        )));
    }

    let mut nums = [0u32; 3];
    for (i, part) in parts.iter().enumerate() {
        nums[i] = part.parse::<u32>().map_err(|_| {
            ParseVersionError(format!("'{part}' is not a non-negative integer"))
        })?;
    }

    Ok(Version { major: nums[0], minor: nums[1], patch: nums[2] })
}

fn main() {
    assert_eq!(parse_version("1.20.3"), Ok(Version { major: 1, minor: 20, patch: 3 }));
    assert!(parse_version("1.2").is_err());
    assert!(parse_version("1.2.x").is_err());
    assert!(parse_version("1..3").is_err());
    println!("all assertions passed");
