#include <string>
#include <vector>
#include <iostream>

static bool is_continuation(unsigned char c) { return (c & 0xC0) == 0x80; }

std::string reverse_utf8(const std::string& s) {
    std::vector<std::string> chars;
    for (size_t i = 0; i < s.size();) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        size_t len = 1;
        if ((c & 0x80) == 0x00) len = 1;
        else if ((c & 0xE0) == 0xC0) len = 2;
        else if ((c & 0xF0) == 0xE0) len = 3;
        else if ((c & 0xF8) == 0xF0) len = 4;

        // Validate that the declared continuation bytes actually exist.
        if (i + len > s.size()) len = 1;
        for (size_t k = 1; k < len; ++k) {
            if (!is_continuation(static_cast<unsigned char>(s[i + k]))) { len = 1; break; }
        }
        chars.push_back(s.substr(i, len));
        i += len;
    }
    std::string out;
    for (auto it = chars.rbegin(); it != chars.rend(); ++it) out += *it;
    return out;
}

int main() {
    std::string in = "a\xE2\x82\xACb";  // a, euro sign, b
    std::string out = reverse_utf8(in);
    std::cout << out << "\n";
    if (out != "b\xE2\x82\xACa") { std::cerr << "FAIL\n"; return 1; }
    std::cout << "ok\n";
}
```

Collect each codepoint as its own unit, then reverse the units rather than the bytes. Malformed sequences fall back to single bytes so the loop never indexes past the end.

