Drain the smaller head each step, then append whatever remains. Using `<=` keeps equal elements stable from `a` first. Runtime is O(n+m) with one allocation up front.

```cpp
#include <iostream>
#include <cstdint>
#include <limits>

int main() {
    const std::uint64_t n = 90;
    std::uint64_t a = 0, b = 1;
    for (std::uint64_t i = 0; i < n; ++i) {
        std::cout << i + 1 << ": " << a << "\n";
        // Guard the addition so we never wrap around silently.
        if (a > std::numeric_limits<std::uint64_t>::max() - b) {
            std::cerr << "stopping: overflow beyond n=" << i + 1 << "\n";
            break;
        }
        std::uint64_t next = a + b;
        a = b;
        b = next;
    }
    return 0;
}
