```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

int valid_ipv4(const char *s) {
    if (!s || !*s) return 0;
    int octets = 0;
    const char *p = s;
    while (1) {
        if (!isdigit((unsigned char)*p)) return 0;
        int value = 0, digits = 0;
        while (isdigit((unsigned char)*p)) {
            value = value * 10 + (*p - '0');
            digits++;
            if (digits > 3 || value > 255) return 0;
            p++;
        }
        /* Leading zeros like "01" are rejected. */
        if (digits > 1 && *(p - digits) == '0') return 0;
        octets++;
        if (*p == '.') {
            p++;
            continue;
        }
        break;
    }
    return octets == 4 && *p == '\0';
}

int main(void) {
    const char *good[] = {"0.0.0.0", "192.168.1.1", "255.255.255.255"};
    const char *bad[]  = {"256.1.1.1", "1.2.3", "1.2.3.4.5", "01.2.3.4", "a.b.c.d", ""};
    for (size_t i = 0; i < sizeof(good)/sizeof(good[0]); i++)
        if (!valid_ipv4(good[i])) { printf("FAIL good %s\n", good[i]); return 1; }
    for (size_t i = 0; i < sizeof(bad)/sizeof(bad[0]); i++)
        if (valid_ipv4(bad[i])) { printf("FAIL bad %s\n", bad[i]); return 1; }
    printf("ok\n");
    return 0;
}
```

Parse each octet digit by digit and bail once it exceeds 255 or three digits, then require exactly four octets and end-of-string. The digit-count check blocks leading zeros, which some parsers treat as octal.

```cpp
// running_median.cpp
#include <iostream>
#include <queue>
#include <vector>

class MedianTracker {
public:
    void add(int x) {
        if (low_.empty() || x <= low_.top()) low_.push(x);
        else high_.push(x);
        // Rebalance: low_ max-heap may hold at most one more than high_.
        if (low_.size() > high_.size() + 1) { high_.push(low_.top()); low_.pop(); }
        else if (high_.size() > low_.size()) { low_.push(high_.top()); high_.pop(); }
    }

    double median() const {
        if (low_.size() == high_.size())
            return (low_.top() + high_.top()) / 2.0;
        return static_cast<double>(low_.top());
    }

private:
    std::priority_queue<int> low_;                                  // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high_; // min-heap
};

int main() {
    MedianTracker tracker;
    int x;
    while (std::cin >> x) {
        tracker.add(x);
        std::cout << tracker.median() << '\n';
    }
    return 0;
}
```

`low_` keeps the smaller half (max-heap) and `high_` the larger half (min-heap). After each insertion the sizes differ by at most one, so the median is either `low_.top()` or the average of the two tops. Each element costs `O(log n)` and no input is buffered.

```rust
// brackets.rs
#[derive(Debug, PartialEq)]
pub enum BracketError {
    UnexpectedClose(char, usize),
    Mismatch { open: char, close: char, at: usize },
    Unclosed(char, usize),
}

pub fn check_balanced(input: &str) -> Result<(), BracketError> {
    let mut stack: Vec<(char, usize)> = Vec::new();
    for (idx, ch) in input.char_indices() {
        match ch {
            '(' | '[' | '{' => stack.push((ch, idx)),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    None => return Err(BracketError::UnexpectedClose(ch, idx)),
                    Some((open, _)) if open != expected => {
                        return Err(BracketError::Mismatch { open, close: ch, at: idx })
                    }
                    Some(_) => {}
                }
            }
            _ => {}
        }
    }
    match stack.last() {
        Some(&(open, idx)) => Err(BracketError::Unclosed(open, idx)),
        None => Ok(()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_nested_and_ignores_other_chars() {
        assert_eq!(check_balanced("a(b[c]{d})e"), Ok(()));
        assert_eq!(check_balanced(""), Ok(()));
        assert_eq!(check_balanced("no brackets"), Ok(()));
    }

    #[test]
    fn reports_mismatch_position() {
        assert_eq!(
            check_balanced("([)]"),
            Err(BracketError::Mismatch { open: '[', close: ')', at: 2 })
        );
    }

    #[test]
    fn reports_unclosed() {
        assert_eq!(check_balanced("(("), Err(BracketError::Unclosed('(', 1)));
    }
}
```

The stack stores each opener with its byte index, so the index in every error refers to the offending `char_indices` position. Non-bracket characters are skipped, which makes the function safe to run over arbitrary text.

