# running_balance.py
import csv
import sys
from datetime import date


def parse_amount(text: str) -> float:
    """Accept '1,234.50', '$12', ' 3.5 '. Raise ValueError on garbage."""
    cleaned = text.strip().replace("$", "").replace(",", "")
    if not cleaned:
        raise ValueError("empty amount")
    return float(cleaned)


def running_balance(path: str):
    """Yield (date, amount, balance) tuples; log malformed rows to stderr."""
    balance = 0.0
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.reader(fh)
        for line_no, row in enumerate(reader, start=1):
            if not row or all(not c.strip() for c in row):
                continue
            if len(row) < 2:
                print(f"line {line_no}: expected 2 columns, got {len(row)}", file=sys.stderr)
                continue
            raw_date, raw_amount = row[0], row[1]
            try:
                day = date.fromisoformat(raw_date.strip())
            except ValueError:
                print(f"line {line_no}: bad date {raw_date!r}", file=sys.stderr)
                continue
            try:
                amount = parse_amount(raw_amount)
            except ValueError:
                print(f"line {line_no}: bad amount {raw_amount!r}", file=sys.stderr)
                continue
            balance += amount
            yield day, amount, balance


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: running_balance.py <file.csv>", file=sys.stderr)
        raise SystemExit(2)
    for day, amount, balance in running_balance(sys.argv[1]):
        print(f"{day.isoformat()}  {amount:>10.2f}  {balance:>12.2f}")
```

Malformed rows never abort the run: the date is parsed with `date.fromisoformat`, the amount tolerates `$` and thousands separators, and each failure is reported to stderr with its line number. Blank lines are ignored and the balance only advances for rows that fully parse.

```c
// reverse_words.c
#include <stdio.h>
#include <string.h>

static void reverse_range(char *lo, char *hi) {
    while (lo < hi) {
        char tmp = *lo;
        *lo++ = *hi;
        *hi-- = tmp;
    }
}

void reverse_words(char *s) {
    if (s == NULL || *s == '\0') return;
    size_t n = strlen(s);
    reverse_range(s, s + n - 1);          /* 1. reverse whole string */
    char *word = s;
    for (char *p = s;; ++p) {
        if (*p == ' ' || *p == '\0') {
            reverse_range(word, p - 1);    /* 2. re-reverse each word */
            if (*p == '\0') break;
            word = p + 1;
        }
    }
}

int main(void) {
    char a[] = "the quick brown fox";
    char b[] = "  leading and trailing  ";
    char c[] = "single";
    char d[] = "";

    reverse_words(a);
    reverse_words(b);
    reverse_words(c);
    reverse_words(d);

    printf("[%s]\n", a);  /* [fox brown quick the] */
    printf("[%s]\n", b);  /* [  trailing and leading  ] */
    printf("[%s]\n", c);  /* [single] */
    printf("[%s]\n", d);  /* [] */
    return 0;
}
```

The whole-string reversal followed by a per-word reversal is the classic in-place trick. Runs of spaces collapse correctly because each empty word between adjacent spaces is reversed over an empty range, so `"a  b"` becomes `"b  a"` with both spaces preserved. `NULL` and empty input are no-ops.

