struct Cell { int r, c; };

int main() {
    std::vector<std::string> grid;
    std::string line;
    while (std::getline(std::cin, line)) {
        if (!line.empty()) grid.push_back(line);
    }
    if (grid.empty()) return 0;

    const int rows = static_cast<int>(grid.size());
    const int cols = static_cast<int>(grid[0].size());
    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, -1));

    // Find the first open cell ('.') as the start; expected on the grid.
    Cell start{-1, -1};
    for (int r = 0; r < rows && start.r < 0; ++r)
        for (int c = 0; c < cols; ++c)
            if (grid[r][c] == '.') { start = {r, c}; break; }
    if (start.r < 0) { std::cout << "no open cells\n"; return 0; }

    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};
    std::queue<Cell> q;
    dist[start.r][start.c] = 0;
    q.push(start);

    while (!q.empty()) {
        Cell cur = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nr = cur.r + dr[k], nc = cur.c + dc[k];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            if (grid[nr][nc] == '#' || dist[nr][nc] != -1) continue;
            dist[nr][nc] = dist[cur.r][cur.c] + 1;
            q.push({nr, nc});
        }
    }

    for (const auto& row : dist) {
        for (size_t c = 0; c < row.size(); ++c)
            std::cout << (c ? " " : "") << row[c];
        std::cout << '\n';
    }
    return 0;
}
```

Input is rows of `.` (open) and `#` (wall); the first `.` found scanning row-major is the start. The BFS marks `dist` when a node is enqueued, so each cell is pushed once and walls/unreachable cells stay `-1`. Ragged rows shorter than `cols` would read out of bounds, so keep the grid rectangular.

```python
# find_duplicates.py
import hashlib
import os
import sys
from collections import defaultdict

CHUNK = 1 << 20  # 1 MiB


def sha256_of(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        while True:
            block = fh.read(CHUNK)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def find_duplicates(root: str):
    by_digest: dict[str, list[str]] = defaultdict(list)
    skipped = 0
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            path = os.path.join(dirpath, name)
            if not os.path.isfile(path) or os.path.islink(path):
                skipped += 1
                continue
            try:
                by_digest[sha256_of(path)].append(path)
            except (OSError, PermissionError):
                skipped += 1
    return by_digest, skipped


if __name__ == "__main__":
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    if not os.path.isdir(root):
        print(f"error: not a directory: {root}", file=sys.stderr)
        raise SystemExit(1)
    digests, skipped = find_duplicates(root)
    groups = [paths for paths in digests.values() if len(paths) > 1]
    if not groups:
        print("no duplicate files found")
    for paths in sorted(groups):
        print(f"--- {len(paths)} copies ---")
        for path in sorted(paths):
            print(path)
    if skipped:
        print(f"({skipped} file(s) skipped)", file=sys.stderr)
```

Files are hashed in 1 MiB chunks so memory stays flat regardless of file size. Symbolic links are skipped to avoid double-counting, unreadable files are counted and reported, and only digest groups with more than one path are printed, each sorted for stable output.

A linear two-pointer merge. It works for either input empty and for duplicates.

```cpp
#include <vector>
#include <iostream>

std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        // <= keeps the merge stable for equal keys from a first.
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5, 7};
    std::vector<int> b{2, 4, 6};
    for (int v : merge_sorted(a, b)) std::cout << v << ' ';
    std::cout << '\n'; // 1 2 3 4 5 6 7

    std::vector<int> empty;
    std::cout << merge_sorted(empty, b).size() << '\n'; // 3
    std::cout << merge_sorted(empty, empty).size() << '\n'; // 0
    return 0;
}
```

`reserve` avoids reallocations, and the tail loops flush any remainder once one side is exhausted.

