A fixed-capacity ring buffer over a `Vec`. `push` returns `false` when full; `pop` returns `None` when empty.

```rust
pub struct RingQueue<T> {
    buf: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingQueue<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        let mut buf = Vec::with_capacity(capacity);
        buf.resize_with(capacity, || None);
        RingQueue { buf, head: 0, len: 0 }
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn push(&mut self, value: T) -> bool {
        if self.len == self.buf.len() {
            return false;
        }
        let idx = (self.head + self.len) % self.buf.len();
        self.buf[idx] = Some(value);
        self.len += 1;
        true
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        let value = self.buf[self.head].take();
        self.head = (self.head + 1) % self.buf.len();
        self.len -= 1;
        value
    }
}

fn main() {
    let mut q = RingQueue::new(2);
    assert!(q.pop().is_none());
    assert!(q.push(1));
    assert!(q.push(2));
    assert!(!q.push(3)); // full
    assert_eq!(q.pop(), Some(1));
    assert_eq!(q.pop(), Some(2));
    assert_eq!(q.pop(), None);
    println!("ok");
}
```

The modulo arithmetic wraps both `head` and the write index, so the buffer is reused instead of shifting elements.

Buckets scores into ranges of 10 using integer division, sums per bucket, sorted output.

```python
from collections import defaultdict
from typing import Iterable, Tuple, Dict


def score_buckets(rows: Iterable[Tuple[str, int]]) -> Dict[int, int]:
    """Sum scores per decade. Negative scores are bucketed too (floor division).

    Returns {decade_start: total}, e.g. {70: 150, 80: 85}.
    """
    totals: Dict[int, int] = defaultdict(int)
    for _name, score in rows:
        decade = (score // 10) * 10
        totals[decade] += score
    return dict(sorted(totals.items()))


if __name__ == "__main__":
    data = [("ann", 72), ("bo", 78), ("cy", 85), ("di", 80), ("ed", -5)]
    print(score_buckets(data))
    # {-10: -5, 70: 150, 80: 165}
    print(score_buckets([]))  # {}
```

`//` floors toward negative infinity, so `-5 // 10` is `-1` and the bucket is `-10`, which is consistent and avoids a `0` bucket swallowing negatives.

