    std::size_t left = 0;
    std::size_t right = s.size();
    while (left < right) {
        if (left < right && !std::isalnum(static_cast<unsigned char>(s[left]))) {
            ++left;
            continue;
        }
        if (left < right && !std::isalnum(static_cast<unsigned char>(s[right - 1]))) {
            --right;
            continue;
