        unsigned char a = static_cast<unsigned char>(std::tolower(static_cast<unsigned char>(s[left])));
        unsigned char b = static_cast<unsigned char>(std::tolower(static_cast<unsigned char>(s[right - 1])));
        if (a != b) return false;
        ++left;
        --right;
    }
    return true;
}

