```cpp
#include <condition_variable>
#include <mutex>
#include <queue>
#include <thread>
#include <iostream>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t cap) : cap_(cap) {}

    void push(int v) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [&] { return q_.size() < cap_; });
        q_.push(v);
        not_empty_.notify_one();
    }

    bool pop(int& out) {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [&] { return !q_.empty() || closed_; });
        if (q_.empty()) return false;  // closed and drained
        out = q_.front();
        q_.pop();
        not_full_.notify_one();
        return true;
    }

    void close() {
        std::lock_guard<std::mutex> lk(m_);
        closed_ = true;
        not_empty_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<int> q_;
    std::mutex m_;
    std::condition_variable not_full_, not_empty_;
    bool closed_ = false;
};

int main() {
    BoundedQueue q(4);
    std::thread producer([&] {
        for (int i = 0; i < 20; ++i) q.push(i);
        q.close();
    });

    std::thread consumer([&] {
        int v;
        long sum = 0;
        while (q.pop(v)) sum += v;
        std::cout << "sum=" << sum << "\n";  // 0..19 => 190
    });

    producer.join();
    consumer.join();
    return 0;
}
```
The condition variables guard both "full" and "empty" waits. `close()` wakes any blocked consumer; a consumer that sees an empty queue after close returns `false`, ending the loop. Compile with `g++ -std=c++17 -pthread`.

