        assert_eq!(cfg["host"], "localhost");
        assert_eq!(cfg["port"], "8080");
    }

    #[test]
    fn rejects_missing_equals() {
        assert!(matches!(
            parse_config("a=1\nbogus\n"),
            Err(ConfigError::MissingEquals(2))
        ));
    }
}
```
`split_once` keeps only the first `=`, so values may contain `=` (e.g. connection strings). Keys and values are trimmed; duplicates are rejected rather than silently overwritten.

```cpp
#include <algorithm>
#include <iostream>
#include <vector>

// Patient-sort tails: tails[k] is the smallest tail of an increasing
// subsequence of length k+1. The first index where tails[i] >= x is where
// x can extend or replace.
int length_of_lis(const std::vector<int>& nums) {
    std::vector<int> tails;
    for (int x : nums) {
        auto it = std::lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) {
            tails.push_back(x);
        } else {
            *it = x;
        }
    }
    return static_cast<int>(tails.size());
}

int main() {
    std::vector<std::vector<int>> cases = {
        {},
        {5},
        {10, 9, 2, 5, 3, 7, 101, 18},   // 4: 2,3,7,101
        {7, 7, 7, 7},                   // 1 (strict)
        {1, 2, 3, 4, 5},                // 5
        {5, 4, 3, 2, 1},                // 1
    };
    for (const auto& c : cases) {
        std::cout << length_of_lis(c) << "\n";
    }
    return 0;
}
```
`lower_bound` on the `tails` array finds the first element not less than `x`, so strictly increasing runs are handled correctly (equal values replace rather than extend). Runs in O(n log n) time and O(n) space; empty input returns 0.

```rust
struct Slab<T> {
    items: Vec<Option<T>>,
    free: Vec<usize>,
}

impl<T> Slab<T> {
    fn new() -> Self {
        Slab { items: Vec::new(), free: Vec::new() }
    }

    fn insert(&mut self, value: T) -> usize {
        if let Some(idx) = self.free.pop() {
            self.items[idx] = Some(value);
            idx
        } else {
            self.items.push(Some(value));
            self.items.len() - 1
        }
    }

    fn get(&self, idx: usize) -> Option<&T> {
        self.items.get(idx).and_then(|slot| slot.as_ref())
    }

    fn remove(&mut self, idx: usize) -> Option<T> {
        let slot = self.items.get_mut(idx)?;
        let taken = slot.take()?;
        self.free.push(idx);
        Some(taken)
    }

    fn len(&self) -> usize {
        self.items.iter().filter(|s| s.is_some()).count()
    }
}

fn main() {
    let mut slab: Slab<&str> = Slab::new();
    let a = slab.insert("alpha");
    let b = slab.insert("beta");
    assert_eq!(slab.get(a), Some(&"alpha"));
    assert_eq!(slab.remove(a), Some("alpha"));
    assert_eq!(slab.get(a), None);
    let c = slab.insert("gamma");  // reuses slot a
    assert_eq!(c, a);
    assert_eq!(slab.len(), 2);
    assert_eq!(slab.get(b), Some(&"beta"));
    println!("slab ok");
}
```
Indices stay valid until `remove` is called on them; freed slots are reused via the `free` list, so memory does not grow unboundedly under insert/remove churn. `get` on a freed or out-of-range index returns `None` instead of panicking.

```python
import heapq


def dijkstra(graph, start):
    """Shortest paths from `start` in a directed weighted graph.

    graph: {node: [(neighbor, weight), ...]}
    Returns (dist, prev) where dist[v] is the cost and prev[v] the parent.
    Unreachable nodes are omitted from dist.
    """
    if start not in graph:
        return {}, {}

    dist = {start: 0}
    prev = {}
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, float("inf")):
            continue
        for v, w in graph.get(u, ()):
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(pq, (nd, v))
    return dist, prev


def shortest_path(prev, start, goal):
    if goal != start and goal not in prev:
        return None
    path = [goal]
    while path[-1] != start:
        path.append(prev[path[-1]])
    return path[::-1]


if __name__ == "__main__":
    g = {
        "A": [("B", 1), ("C", 4)],
        "B": [("C", 2), ("D", 5)],
        "C": [("D", 1)],
        "D": [],
        "E": [],  # unreachable
    }
    dist, prev = dijkstra(g, "A")
    assert dist["D"] == 4                # A->B->C->D
    assert shortest_path(prev, "A", "D") == ["A", "B", "C", "D"]
    assert "E" not in dist
    dist2, _ = dijkstra({}, "A")
    assert dist2 == {}
    print("all checks passed")
```
The lazy-deletion guard (`if d > dist[u]: continue`) discards stale heap entries. `prev` lets a caller reconstruct the path with `shortest_path`; unreachable nodes stay out of `dist`, and a missing start returns empty dicts.

```c
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *data;
    size_t len;
    size_t cap;   /* includes room for the trailing NUL */
} StrBuf;

bool sb_init(StrBuf *sb) {
    sb->cap = 16;
    sb->len = 0;
    sb->data = malloc(sb->cap);
    if (!sb->data) return false;
    sb->data[0] = '\0';
    return true;
}

void sb_free(StrBuf *sb) {
    free(sb->data);
    sb->data = NULL;
    sb->len = sb->cap = 0;
}

static bool sb_reserve(StrBuf *sb, size_t extra) {
    if (sb->len + extra + 1 <= sb->cap) return true;
    size_t need = sb->len + extra + 1;
    size_t cap = sb->cap;
    while (cap < need) cap *= 2;
    char *p = realloc(sb->data, cap);
    if (!p) return false;
    sb->data = p;
    sb->cap = cap;
    return true;
}

bool sb_append(StrBuf *sb, const char *s) {
    size_t n = strlen(s);
    if (!sb_reserve(sb, n)) return false;
    memcpy(sb->data + sb->len, s, n);
    sb->len += n;
    sb->data[sb->len] = '\0';
    return true;
}

bool sb_appendf(StrBuf *sb, const char *fmt, ...) {
    va_list ap, ap2;
    va_start(ap, fmt);
    va_copy(ap2, ap);
    int n = vsnprintf(NULL, 0, fmt, ap);
    if (n < 0) { va_end(ap); va_end(ap2); return false; }
    if (!sb_reserve(sb, (size_t)n)) { va_end(ap); va_end(ap2); return false; }
    vsnprintf(sb->data + sb->len, (size_t)n + 1, fmt, ap2);
    sb->len += (size_t)n;
    va_end(ap);
    va_end(ap2);
    return true;
}

int main(void) {
    StrBuf sb;
    if (!sb_init(&sb)) return 1;
    if (!sb_append(&sb, "count=")) return 1;
    if (!sb_appendf(&sb, "%d ok=%s", 42, "yes")) return 1;
    printf("%s (len=%zu)\n", sb.data, sb.len);
    /* "count=42 ok=yes (len=15)" */
    sb_free(&sb);
    return 0;
}
```
Capacity doubles on growth and always leaves room for the trailing NUL, so `sb.data` is a valid C string after every call. `sb_appendf` measures the formatted length with `vsnprintf(NULL, 0, ...)` before reserving, avoiding a fixed scratch buffer. Every failure path returns `false` without leaking the old buffer.

