```python
class BoundedStack:
    """A stack with a fixed maximum capacity."""

    def __init__(self, capacity: int) -> None:
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self._capacity = capacity
        self._items: list = []

    def push(self, item) -> None:
        if len(self._items) >= self._capacity:
            raise OverflowError(f"stack is full (capacity {self._capacity})")
        self._items.append(item)

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self):
        if not self._items:
            raise IndexError("peek from empty stack")
        return self._items[-1]

    def is_empty(self) -> bool:
        return not self._items

    def __len__(self) -> int:
        return len(self._items)


if __name__ == "__main__":
    s = BoundedStack(2)
    assert s.is_empty()
    s.push(10)
    s.push(20)
    assert s.peek() == 20
    assert s.pop() == 20
    try:
        s.push(1)
        s.push(2)
        s.push(3)
        raise AssertionError("expected OverflowError")
    except OverflowError:
        pass
    print("ok")
```

I used `OverflowError` for a full push and `IndexError` for empty pop/peek so callers can distinguish the two failure modes. The capacity check is `< 1` rather than `<= 0` to reject nonsensical zero-size stacks.

