#include <stdio.h>
#include <string.h>

static void reverse_bytes(char *s, size_t len) {
    for (size_t i = 0; i < len / 2; i++) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
}

/* Reverse by UTF-8 code points so multibyte chars stay intact. */
static void reverse_utf8(char *s) {
    size_t len = strlen(s);
    size_t i = 0, j = len;
    char tmp[4];
    while (i < j) {
        size_t blen = 1;
        unsigned char c = (unsigned char)s[i];
        if (c >= 0xF0) blen = 4;
        else if (c >= 0xE0) blen = 3;
        else if (c >= 0xC0) blen = 2;

        size_t clen = 1;
        unsigned char d = (unsigned char)s[j - 1];
        while ((d & 0xC0) == 0x80 && clen < 4) { d = (unsigned char)s[j - 1 - clen]; clen++; }

        if (blen != clen) break; /* malformed input: stop rather than corrupt */
        memcpy(tmp, s + i, blen);
        memmove(s + i, s + j - clen, clen);
        memcpy(s + j - clen, tmp, blen);
        i += clen;
        j -= blen;
    }
}

int main(void) {
    char buf[] = "héllo";
    reverse_utf8(buf);
    printf("%s\n", buf);   /* olléh */
    char empty[] = "";
    reverse_utf8(empty);
    printf("[%s]\n", empty);
    return 0;
}
