def sieve(n):
    if n < 2:
        return []
    is_prime = bytearray([1]) * n
    is_prime[0] = is_prime[1] = 0
    for p in range(2, int(n ** 0.5) + 1):
        if is_prime[p]:
            step = p
            start = p * p
            is_prime[start:n:step] = bytearray(len(range(start, n, step)))
    return [i for i, flag in enumerate(is_prime) if flag]


def is_prime_trial(x):
    if x < 2:
        return False
    if x % 2 == 0:
        return x == 2
    d = 3
    while d * d <= x:
        if x % d == 0:
            return False
        d += 2
    return True


if __name__ == "__main__":
    limit = 1000
    fast = set(sieve(limit))
    slow = {x for x in range(limit) if is_prime_trial(x)}
    assert fast == slow, "sieve and trial division disagree"
    print(len(fast), "primes below", limit)
