from typing import List


def rotate(matrix: List[List[int]]) -> None:
    """Rotate an n x n matrix 90 degrees clockwise, in place."""
    n = len(matrix)
    if n == 0 or any(len(row) != n for row in matrix):
        raise ValueError("matrix must be non-empty and square")

    # Transpose, then reverse each row.
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    for row in matrix:
        row.reverse()


if __name__ == "__main__":
    m = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    rotate(m)
    print(m)  # [[7, 4, 1], [8, 5, 2], [9, 6, 3]]
```

The transpose swaps `(i, j)` with `(j, i)`, then each row reversal completes the clockwise turn. It works for any n ≥ 1, including 1x1 (no-op), and raises on ragged input.

```cpp
#include <iostream>
#include <queue>
#include <vector>
#include <iomanip>

int main() {
    std::priority_queue<int> low;                              // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap
    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);

        // Rebalance: low may hold at most one more than high.
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        if (low.size() == high.size())
            std::cout << (low.top() + high.top()) / 2.0 << '\n';
        else
            std::cout << low.top() << '\n';
    }
    return 0;
}
```

Each value joins `low` (smaller half) or `high` (larger half); rebalancing keeps the halves within one element, so the median is the top of `low` or the mean of both tops. Output is a `double` so even-sized runs print correctly, and empty input produces no output.

