```c
#include <stddef.h>
#include <stdint.h>

int utf8_valid(const unsigned char *s, size_t len) {
    size_t i = 0;
    while (i < len) {
        unsigned char c = s[i];
        size_t extra;
        uint32_t cp;

        if (c < 0x80) {
            i += 1;
            continue;
        } else if ((c & 0xE0) == 0xC0) {
            extra = 1;
            cp = c & 0x1F;
        } else if ((c & 0xF0) == 0xE0) {
            extra = 2;
            cp = c & 0x0F;
        } else if ((c & 0xF8) == 0xF0) {
            extra = 3;
            cp = c & 0x07;
        } else {
            return 0; /* 0x80-0xBF lone continuation, or 0xF8+ invalid lead */
        }

        if (i + extra >= len) return 0; /* truncated */
        for (size_t k = 1; k <= extra; k++) {
            unsigned char t = s[i + k];
            if ((t & 0xC0) != 0x80) return 0; /* bad continuation */
            cp = (cp << 6) | (t & 0x3F);
        }

        /* Reject overlong encodings and out-of-range code points. */
        if (extra == 1 && cp < 0x80) return 0;
        if (extra == 2 && cp < 0x800) return 0;
        if (extra == 3 && cp < 0x10000) return 0;
        if (cp > 0x10FFFF) return 0;
        if (cp >= 0xD800 && cp <= 0xDFFF) return 0; /* surrogates */

        i += extra + 1;
    }
    return 1;
}
```

It walks lead/continuation bytes, bounds-checks truncation and bad tails, then rejects overlong forms, surrogates and code points above `0x10FFFF`. `len == 0` is trivially valid.

