```cpp
#include <unistd.h>
#include <utility>

class Fd {
public:
    Fd() noexcept : fd_(-1) {}
    explicit Fd(int fd) noexcept : fd_(fd) {}

    ~Fd() { close(); }

    Fd(const Fd&) = delete;
    Fd& operator=(const Fd&) = delete;

    Fd(Fd&& other) noexcept : fd_(other.fd_) { other.fd_ = -1; }
    Fd& operator=(Fd&& other) noexcept {
        if (this != &other) {
            close();
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    int get() const noexcept { return fd_; }
    explicit operator bool() const noexcept { return fd_ >= 0; }

    void reset(int fd = -1) noexcept {
        close();
        fd_ = fd;
    }

private:
    void close() noexcept {
        if (fd_ >= 0) {
            ::close(fd_);
            fd_ = -1;
        }
    }
    int fd_;
};
```

Copying is deleted; moving transfers ownership and leaves the source at -1 so the destructor is idempotent. `close()` guards against `EBADF` from double-closing, and `reset` is reuse-friendly. If you need stricter behaviour, make the move-assignment self-test `this != &other` even tighter.

```rust
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 1], &[1]), vec![1, 1, 1]);
    println!("ok");
}
```

`with_capacity` reserves exactly the final size so no reallocation occurs, and the tail `extend_from_slice` copies the non-empty remainder after one side is exhausted. `<=` on the left makes the merge stable, and equal elements from both inputs are preserved in order. Generic over `Ord + Clone`.

