fn validate_slug(s: &str) -> Result<(), String> {
    if s.is_empty() {
        return Err("slug is empty".to_string());
    }
    let bytes = s.as_bytes();
    if bytes[0] == b'-' || bytes[bytes.len() - 1] == b'-' {
        return Err("slug must not start or end with a hyphen".to_string());
    }
    for (i, b) in bytes.iter().enumerate() {
        match *b {
            b'a'..=b'z' | b'0'..=b'9' => {}
            b'-' => {
                if i > 0 && bytes[i - 1] == b'-' {
                    return Err("slug has consecutive hyphens".to_string());
                }
            }
            _ => {
                return Err(format!(
                    "invalid character '{}' at byte {}",
                    *b as char, i
                ));
            }
        }
    }
    Ok(())
}

fn main() {
    assert!(validate_slug("hello-world-2").is_ok());
    assert!(validate_slug("").is_err());
    assert!(validate_slug("-lead").is_err());
    assert!(validate_slug("trail-").is_err());
    assert!(validate_slug("a--b").is_err());
    assert!(validate_slug("Uppercase").is_err());
