#include <cctype>
#include <string>

bool is_palindrome(const std::string& text) {
    std::size_t left = 0;
    std::size_t right = text.size();
    while (left < right) {
        unsigned char l = static_cast<unsigned char>(text[left]);
        if (!std::isalnum(l)) {
            ++left;
            continue;
        }
        unsigned char r = static_cast<unsigned char>(text[right - 1]);
        if (!std::isalnum(r)) {
            --right;
            continue;
        }
        if (std::tolower(l) != std::tolower(r)) {
            return false;
        }
        ++left;
        --right;
    }
    return true;
}

