fn roman_to_int(s: &str) -> Option<i32> {
    let chars: Vec<char> = s.chars().collect();
    if chars.is_empty() {
        return None;
    }
    let mut total = 0i32;
    for i in 0..chars.len() {
        let value = roman_value(chars[i])?;
        if i + 1 < chars.len() {
            let next = roman_value(chars[i + 1])?;
            if value < next {
                total -= value;
            } else {
                total += value;
            }
        } else {
            total += value;
        }
    }
    Some(total)
}

