fn fib(n: u64) -> u128 {
    fn fd(n: u64) -> (u128, u128) {
        if n == 0 {
            return (0, 1);
        }
        let (a, b) = fd(n >> 1);
        let c = a * (2 * b - a);
        let d = a * a + b * b;
