void reverse(char *s) {
    if (s == NULL) return;
    size_t i = 0;
    size_t j = strlen(s);
    while (i < j) {
        --j;
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
    }
