pub fn fib_series(limit: usize) -> Vec<u64> {
    let mut out = Vec::with_capacity(limit);
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..limit {
        out.push(a);
        let next = match a.checked_add(b) {
            Some(v) => v,
            None => break,
        };
        a = b;
        b = next;
    }
    out
}

