/* Copies src into dst (size bytes) and always null-terminates.
 * Returns the number of source bytes that did not fit. */
size_t safe_copy(char *dst, size_t size, const char *src) {
    if (dst == NULL || size == 0) {
        return src ? strlen(src) : 0;
    }
    if (src == NULL) {
        dst[0] = '\0';
        return 0;
    }
    size_t len = strlen(src);
    size_t n = (len < size - 1) ? len : size - 1;
    memcpy(dst, src, n);
    dst[n] = '\0';
    return len - n;
}

