#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    std::cout << std::boolalpha << rb.push(1) << " " << rb.push(2) << " " << rb.push(3) << " " << rb.push(4) << "\n";
    while (auto v = rb.pop()) std::cout << *v << " ";
    std::cout << "\nempty pop: " << rb.pop().has_value() << "\n";
    return 0;
}
```

`head_` plus `size_` avoids a separate tail index. `push` returns false when full and `pop` returns `std::nullopt` when empty, so neither case reads uninitialised memory.

