```python
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._store = OrderedDict()

    def get(self, key):
        if key not in self._store:
            return None
        self._store.move_to_end(key)
        return self._store[key]

    def put(self, key, value):
        if key in self._store:
            self._store.move_to_end(key)
        self._store[key] = value
        if len(self._store) > self.capacity:
            self._store.popitem(last=False)

    def __len__(self):
        return len(self._store)

if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1
    cache.put("c", 3)          # evicts "b"
    assert cache.get("b") is None
    assert cache.get("c") == 3
    cache.put("c", 30)
    assert cache.get("c") == 30
    assert len(cache) == 2
    print("checks passed")
```

`OrderedDict.move_to_end` makes the most recently used key the newest entry, so eviction is always the oldest. A missing key returns `None`; if your keys can legitimately be `None`, wrap lookups with a sentinel object instead.

```cpp
#include <iostream>
#include <string>
#include <cctype>

bool isPalindrome(const std::string& text) {
    std::size_t left = 0;
    std::size_t right = text.size();
    while (left < right) {
        unsigned char lc = static_cast<unsigned char>(text[left]);
        if (!std::isalnum(lc)) { ++left; continue; }
        if (right == 0) break;
        unsigned char rc = static_cast<unsigned char>(text[right - 1]);
        if (!std::isalnum(rc)) { --right; continue; }
        if (std::tolower(lc) != std::tolower(rc)) return false;
        ++left;
        --right;
    }
    return true;
}

int main() {
    const char* cases[] = {"A man, a plan, a canal: Panama", "race a car", "", " ,. ", "No 'x' in Nixon"};
    for (const char* c : cases) {
        std::cout << (isPalindrome(c) ? "true  " : "false ") << "\"" << c << "\"\n";
    }
    return 0;
}
```

The two-pointer scan skips punctuation from both ends and compares lowercased chars. The empty string and a string of only punctuation both count as palindromes, since there is nothing to contradict. Casting to `unsigned char` before `isalnum`/`tolower` avoids undefined behaviour on bytes above 127.

