static void reverse_range(char *s, size_t start, size_t end) {
    while (start < end) {
        char tmp = s[start];
        s[start] = s[end];
        s[end] = tmp;
        ++start;
        --end;
    }
}

static void reverse_words(char *line) {
    size_t len = strlen(line);
    reverse_range(line, 0, len - 1);
    size_t i = 0;
    while (i < len) {
        if (isspace((unsigned char)line[i])) { ++i; continue; }
        size_t j = i;
        while (j < len && !isspace((unsigned char)line[j])) ++j;
        reverse_range(line, i, j - 1);
        i = j;
    }
}

int main(void) {
    char buf[512];
    if (!fgets(buf, sizeof buf, stdin)) return 0;
    buf[strcspn(buf, "\n")] = '\0';
    reverse_words(buf);
    printf("%s\n", buf);
    return 0;
}
