I'll back it with `collections.deque` and `maxlen`, which does exactly this and keeps O(1) appends.

```python
from collections import deque
from typing import Iterator, TypeVar, Generic

T = TypeVar("T")


class RingQueue(Generic[T]):
    """Fixed-capacity FIFO. New items evict the oldest when full."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._items: deque[T] = deque(maxlen=capacity)

    def push(self, item: T) -> T | None:
        evicted = None
        if len(self._items) == self.capacity:
            evicted = self._items[0]
        self._items.append(item)
        return evicted

    def pop(self) -> T:
        if not self._items:
            raise IndexError("pop from empty RingQueue")
        return self._items.popleft()

    def __len__(self) -> int:
        return len(self._items)

    def __iter__(self) -> Iterator[T]:
        return iter(self._items)

    def __repr__(self) -> str:
        return f"RingQueue(capacity={self.capacity}, items={list(self._items)})"


if __name__ == "__main__":
    q: RingQueue[int] = RingQueue(3)
    assert q.push(1) is None
    assert q.push(2) is None
    assert q.push(3) is None
    assert q.push(4) == 1
    assert len(q) == 3
    assert list(q) == [2, 3, 4]
    assert q.pop() == 2
    try:
        RingQueue(0)
    except ValueError:
        pass
    print("ok")
```

`deque(maxlen=...)` silently discards from the left on overflow; I capture that value before pushing so callers can see what was evicted.

Three-pointer reversal, then a separate free pass. An empty list returns NULL and the free loop never runs.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *push_front(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (!n) return head;
    n->value = value;
    n->next = head;
    return n;
}

Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; ++i) head = push_front(head, i);

    head = reverse(head);
    for (Node *n = head; n; n = n->next) printf("%d ", n->value);
    printf("\n");

    free_list(head);

    Node *empty = reverse(NULL);
    free_list(empty);
    return 0;
}
```

The list 1..5 built by prepending is 5→4→3→2→1; after reversal it prints 1 2 3 4 5. `reverse(NULL)` returns NULL and the free loop is skipped.

