```cpp
#include <iostream>
#include <stdexcept>
#include <type_traits>

struct DivByZero : std::runtime_error {
    DivByZero() : std::runtime_error("division by zero") {}
};

template <typename T>
T safe_div(T numerator, T denominator) {
    static_assert(std::is_integral_v<T>,
                  "safe_div only supports integral types; use normal / for floating point");
    if (denominator == 0) {
        throw DivByZero{};
    }
    return numerator / denominator;
}

int main() {
    std::cout << safe_div(10, 3) << "\n";
    std::cout << safe_div<long>(10, 3) << "\n";
    try {
        safe_div(5, 0);
    } catch (const DivByZero& e) {
        std::cout << "caught: " << e.what() << "\n";
    }
    // safe_div(1.0, 3.0); // fails to compile, as intended
    return 0;
}
```

`static_assert(std::is_integral_v<T>, ...)` blocks `double`/`float` at compile time; the zero check throws a typed exception. Note that unsigned integers never equal zero-denominator guards incorrectly — `denominator == 0` is still valid for unsigned.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    assert longest_palindrome("") == ""
    assert longest_palindrome("a") == "a"
    assert longest_palindrome("babad") in {"bab", "aba"}
    assert longest_palindrome("cbbd") == "bb"
    assert longest_palindrome("forgeeksskeegfor") == "geeksskeeg"
    print("ok")
```
The expand-around-center approach is O(n²) time and O(1) extra space. Both odd and even centers are checked, so even-length palindromes like `"bb"` are found.

