        buf_[head_] = value;
        head_ = (head_ + 1) % capacity_;
        if (size_ < capacity_) ++size_;
    }

    std::optional<T> at(std::size_t i) const {
        if (i >= size_) return std::nullopt;
        std::size_t idx = (head_ + capacity_ - size_ + i) % capacity_;
        return buf_[idx];
    }

    std::size_t size() const { return size_; }

    void print() const {
        for (std::size_t i = 0; i < size_; ++i) {
            std::cout << *at(i) << (i + 1 == size_ ? '\n' : ' ');
        }
    }

private:
    std::vector<T> buf_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int> rb(3);
    rb.push(1); rb.push(2); rb.push(3); rb.push(4);
    rb.print();  // 2 3 4
    std::cout << rb.size() << '\n';  // 3
    return 0;
}
```
A zero capacity buffer is a no-op rather than a crash. `at` reconstructs logical order from the head and size, so it stays correct after wraps.

```rust
fn merge_intervals(mut intervals: Vec<(i64, i64)>) -> Vec<(i64, i64)> {
    if intervals.is_empty() {
        return Vec::new();
    }
    intervals.sort_by_key(|&(s, _)| s);
    let mut merged: Vec<(i64, i64)> = Vec::new();
    for (start, end) in intervals {
        match merged.last_mut() {
            Some(last) if start <= last.1 => {
                if end > last.1 {
                    last.1 = end;
                }
            }
            _ => merged.push((start, end)),
        }
    }
    merged
}

fn main() {
    let input = vec![(1, 3), (2, 6), (8, 10), (15, 18)];
    assert_eq!(merge_intervals(input), vec![(1, 6), (8, 10), (15, 18)]);
    assert_eq!(merge_intervals(vec![]), Vec::<(i64, i64)>::new());
    assert_eq!(merge_intervals(vec![(5, 5), (5, 6)]), vec![(5, 6)]);
    println!("ok");
}
```
Sorting by start makes a single pass sufficient. Touching intervals like `(5,5)` and `(5,6)` merge because the condition uses `<=`, and empty input returns an empty vector.

