void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0) return;
    j--;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    printf("%s\n", a);  /* olleh */

    char empty[] = "";
    reverse_in_place(empty);
    printf("[%s]\n", empty);  /* [] */

    char single[] = "x";
    reverse_in_place(single);
    printf("%s\n", single);  /* x */

    reverse_in_place(NULL);  /* must not crash */
    return 0;
}
```
Note this reverses **bytes**, so multi-byte UTF-8 sequences come out mangled. For correct character reversal you need to decode code points first — say the word and I'll add a UTF-8-aware version.

```python
from collections import OrderedDict
from typing import Any, Optional


class LRUCache:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict[str, Any] = OrderedDict()

    def get(self, key: str) -> Optional[Any]:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: str, value: Any) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1       # 'a' is now most recent
    cache.put("c", 3)                 # evicts 'b'
    assert cache.get("b") is None
    assert cache.get("a") == 1
    assert cache.get("c") == 3
    assert len(cache) == 2
    print("ok")
```
`move_to_end` marks an entry as most recently used on both `get` and `put`. Eviction via `popitem(last=False)` removes the oldest, giving O(1) operations. A non-positive capacity is rejected up front.

