```cpp
#include <cassert>
#include <algorithm>

template <typename T>
T clamp_value(const T& value, const T& low, const T& high) {
    // If the caller passes bounds backwards, swap them so the result is
    // always within [min(low, high), max(low, high)].
    const T& lo = std::min(low, high);
    const T& hi = std::max(low, high);
    if (value < lo) return lo;
    if (hi < value) return hi;
    return value;
}

int main() {
    assert(clamp_value(5, 1, 10) == 5);
    assert(clamp_value(-3, 0, 4) == 0);
    assert(clamp_value(42, 0, 4) == 4);
    assert(clamp_value(7, 10, 1) == 7);   // reversed bounds
    assert(clamp_value(12, 10, 1) == 10); // reversed bounds, above hi
    assert(clamp_value('m', 'a', 'z') == 'm');
    return 0;
}
```

Using `std::min`/`std::max` on the bounds makes the reversed case uniform with the normal case, so there is one comparison path rather than two. The function only needs `operator<`, which every ordered type provides.

