import re

_EMAIL = re.compile(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$")


def normalize_email(raw):
    """Return a lowercased, stripped email or raise ValueError.

    Rejects empty input, missing @, and obvious malformed domains. This is
    deliberately a check, not a full RFC 5322 parser.
    """
    if raw is None:
        raise ValueError("email is required")
    candidate = raw.strip().lower()
    if len(candidate) > 254:
        raise ValueError("email too long")
    if candidate.count("@") != 1 or not _EMAIL.match(candidate):
        raise ValueError(f"invalid email: {raw!r}")
    local, domain = candidate.split("@")
    if ".." in domain or domain.startswith("-") or domain.endswith("-"):
        raise ValueError(f"invalid domain: {domain!r}")
    return candidate


if __name__ == "__main__":
    assert normalize_email("  User@Example.COM ") == "user@example.com"
    for bad in [None, "", "nodomain@", "@example.com", "a b@c.com", "x@..com"]:
        try:
            normalize_email(bad)
        except ValueError:
            continue
        raise AssertionError(f"should have rejected {bad!r}")
    print("ok")
```

The regex gates the bulk of malformed shapes; the explicit checks afterwards catch the empty-label domain cases the pattern would otherwise allow. Returning the normalized string keeps callers from re-implementing the trim and lowercase.

```c
#include <stdio.h>
#include <stdint.h>

#define MOD 1000000007ULL

static uint64_t fib_mod(unsigned int n) {
    uint64_t a = 0, b = 1;
    for (unsigned int i = 0; i < n; ++i) {
        uint64_t next = (a + b) % MOD;
        a = b;
        b = next;
    }
    // a holds F(n) under the reduction.
    return a;
}

int main(void) {
    if (fib_mod(0) != 0 || fib_mod(1) != 1) {
        fprintf(stderr, "self-check failed\n");
        return 1;
    }
    unsigned int n = 0;
    if (scanf("%u", &n) != 1) {
        fprintf(stderr, "error: expected a non-negative integer\n");
        return 1;
    }
    printf("%llu\n", (unsigned long long)fib_mod(n));
    return 0;
}
```

`unsigned long long` gives 64-bit headroom, and reducing at every step stays far below overflow even though the true Fibonacci numbers grow far past 2^64. The self-check pins F(0)=0 and F(1)=1 before trusting streaming input, and a failed `scanf` reports a usage error rather than printing garbage.

