fn is_palindrome(s: &str) -> bool {
    let filtered: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .map(|c| c.to_ascii_lowercase())
        .collect();
    let mut i = 0;
    let mut j = filtered.len().saturating_sub(1);
    while i < j {
        if filtered[i] != filtered[j] {
            return false;
        }
        i += 1;
        j -= 1;
    }
    true
