#include <cstdint>
#include <iostream>

constexpr std::int64_t MOD = 1000000007;

std::pair<std::int64_t, std::int64_t> fib_pair(std::int64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    std::int64_t c = (a * ((2 * b % MOD - a + MOD) % MOD)) % MOD;
    std::int64_t d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1) return {d, (c + d) % MOD};
    return {c, d};
}

std::int64_t fib_fast(std::int64_t n) { return fib_pair(n).first; }

std::int64_t fib_naive(std::int64_t n) {
    std::int64_t a = 0, b = 1;
    for (std::int64_t i = 0; i < n; i++) {
        std::int64_t t = (a + b) % MOD;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    for (std::int64_t n = 0; n <= 60; n++) {
        if (fib_fast(n) != fib_naive(n)) {
            std::cerr << "mismatch at " << n << "\n";
            return 1;
        }
    }
    std::cout << fib_fast(90) << "\n";
    return 0;
}
