#include <array>
#include <cstddef>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double v) {
        if (count_ == N) return false;
        data_[tail_] = v;
        tail_ = (tail_ + 1) % N;
        ++count_;
        return true;
    }

    std::optional<double> pop() {
        if (count_ == 0) return std::nullopt;
        double v = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return v;
    }

    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0, tail_ = 0, count_ = 0;
};
```
Tracking `count_` separates the full and empty cases that would otherwise share `head_ == tail_`. `std::optional` makes the empty-pop case explicit with no sentinel value.

