```python

def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    start, end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    print(longest_palindrome("babad"))
    print(longest_palindrome("cbbd"))
    print(longest_palindrome(""))
    print(longest_palindrome("a"))
    print(longest_palindrome("abracadabra"))
```

`expand` grows around every centre, so both odd and even palindromes are covered in O(n²) time and O(1) extra space. Empty input returns `""`, and a single character returns itself.

```cpp
#include <condition_variable>
#include <mutex>
#include <queue>
#include <optional>
#include <cstddef>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    void push(T value) {
        std::unique_lock<std::mutex> lock(mtx_);
        not_full_.wait(lock, [this] { return q_.size() < cap_ || closed_; });
        if (closed_) return;
        q_.push(std::move(value));
        not_empty_.notify_one();
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mtx_);
        not_empty_.wait(lock, [this] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;
        T value = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mtx_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<T> q_;
    std::mutex mtx_;
    std::condition_variable not_empty_, not_full_;
    bool closed_ = false;
};
```

`push` blocks when the queue is full, `pop` blocks when empty, and `close` wakes every waiter so shutdown cannot hang. Predicate lambdas guard against spurious wakeups.

