```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 5; i >= 1; --i) {
        Node *n = malloc(sizeof *n);
        if (n == NULL) {
            free_list(head);
            return 1;
        }
        n->value = i;
        n->next = head;
        head = n;
    }

    head = reverse(head);
    for (Node *p = head; p != NULL; p = p->next) {
        printf("%d ", p->value);
    }
    putchar('\n');

    free_list(head);
    return 0;
}
```

The three-pointer walk relinks each node before advancing, so the list is reversed in place. `free_list` walks the reversed chain from the new head and releases every allocation, including on the malloc failure path.

