// Reverses a null-terminated string in place. Safe on nullptr and empty input.
void reverse_in_place(char* s) {
    if (s == nullptr) return;
    std::size_t len = std::strlen(s);
    if (len < 2) return;  // empty or single char: nothing to do
    for (std::size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

