    char empty[] = "";
    reverse_in_place(empty);
    std::printf("[%s]\n", empty);  // []

    char one[] = "x";
    reverse_in_place(one);
    std::printf("[%s]\n", one);  // [x]

    char even[] = "abcd";
    reverse_in_place(even);
    std::printf("[%s]\n", even);  // [dcba]

    char odd[] = "abcde";
    reverse_in_place(odd);
    std::printf("[%s]\n", odd);  // [edcba]
    return 0;
