```rust
/// Fixed-capacity ring buffer. Pushing when full overwrites the oldest item.
#[derive(Debug)]
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize, // index of the oldest element
    len: usize,  // number of live elements (<= capacity)
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        let mut data = Vec::with_capacity(capacity);
        data.resize_with(capacity, || None);
        RingBuffer { data, head: 0, len: 0 }
    }

    pub fn capacity(&self) -> usize {
        self.data.len()
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn push(&mut self, value: T) -> Option<T> {
        let cap = self.data.len();
        if self.len < cap {
            let idx = (self.head + self.len) % cap;
            self.data[idx] = Some(value);
            self.len += 1;
            None
        } else {
            let idx = self.head;
            let evicted = self.data[idx].take();
            self.data[idx] = Some(value);
            self.head = (self.head + 1) % cap;
            evicted
        }
    }

    pub fn iter(&self) -> impl Iterator<Item = &T> {
        let cap = self.data.len();
        (0..self.len).map(move |i| {
            self.data[(self.head + i) % cap]
                .as_ref()
                .expect("live slot must be Some")
        })
    }
}

fn main() {
    let mut rb: RingBuffer<i32> = RingBuffer::new(3);
    assert_eq!(rb.push(1), None);
    assert_eq!(rb.push(2), None);
    assert_eq!(rb.push(3), None);
    assert_eq!(rb.push(4), Some(1)); // overwrites oldest
    assert_eq!(rb.iter().copied().collect::<Vec<_>>(), vec![2, 3, 4]);
    assert_eq!(rb.push(5), Some(2));
    assert_eq!(rb.iter().copied().collect::<Vec<_>>(), vec![3, 4, 5]);
    assert_eq!(rb.len(), 3);
    println!("{:?}", rb);
}
```

