RAII grows by doubling; `at()` throws `std::out_of_range`.

```cpp
#include <cstddef>
#include <stdexcept>
#include <utility>

template <typename T>
class DynArray {
public:
    DynArray() = default;
    ~DynArray() { delete[] data_; }

    DynArray(const DynArray&) = delete;
    DynArray& operator=(const DynArray&) = delete;

    void push_back(const T& v) {
        if (size_ == cap_) grow();
        data_[size_++] = v;
    }

    T& at(std::size_t i) {
        if (i >= size_) throw std::out_of_range("DynArray::at");
        return data_[i];
    }

    std::size_t size() const noexcept { return size_; }

private:
    void grow() {
        std::size_t newCap = cap_ ? cap_ * 2 : 4;
        T* newData = new T[newCap];
        for (std::size_t i = 0; i < size_; ++i) newData[i] = data_[i];
        delete[] data_;
        data_ = newData;
        cap_ = newCap;
    }

    T* data_ = nullptr;
    std::size_t size_ = 0;
    std::size_t cap_ = 0;
};

#include <iostream>
int main() {
    DynArray<int> a;
    for (int i = 0; i < 10; ++i) a.push_back(i * i);
    std::cout << a.at(9) << '\n';   // 81
    try { a.at(100); }
    catch (const std::out_of_range& e) { std::cout << "caught: " << e.what() << '\n'; }
}
```

