Binary search on the smaller array keeps the cost logarithmic. The idea: partition both arrays so the left side holds exactly half the elements, then check the boundary conditions.

```cpp
#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

double median_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    if (a.size() > b.size()) return median_sorted(b, a);
    const int m = static_cast<int>(a.size());
    const int n = static_cast<int>(b.size());
    int lo = 0, hi = m;
    while (lo <= hi) {
        int i = (lo + hi) / 2;
        int j = (m + n + 1) / 2 - i;
        int aL = (i == 0) ? INT_MIN : a[i - 1];
        int aR = (i == m) ? INT_MAX : a[i];
        int bL = (j == 0) ? INT_MIN : b[j - 1];
        int bR = (j == n) ? INT_MAX : b[j];
        if (aL <= bR && bL <= aR) {
            if ((m + n) % 2 == 1) return std::max(aL, bL);
            return (std::max(aL, bL) + std::min(aR, bR)) / 2.0;
        }
        if (aL > bR) hi = i - 1; else lo = i + 1;
    }
    return 0.0;
}

int main() {
    std::vector<int> a{1, 3}, b{2};
    assert(median_sorted(a, b) == 2.0);
    std::vector<int> c{1, 2}, d{3, 4};
    assert(median_sorted(c, d) == 2.5);
    std::vector<int> e{}, f{1};
    assert(median_sorted(e, f) == 1.0);
    std::cout << "ok\n";
}
```

Compile with `g++ -std=c++17 -O2 -o median median.cpp`. The sentinels `INT_MIN`/`INT_MAX` remove the boundary special-cases; a real production version would use `-infinity` for doubles to avoid overflow on the average.

