```cpp
#include <cassert>
#include <iostream>
#include <memory>
#include <variant>
#include <vector>

struct Expr;
using ExprPtr = std::shared_ptr<Expr>;

struct Num {
    double value;
};
struct Add {
    std::vector<ExprPtr> terms;
};

struct Expr {
    std::variant<Num, Add> node;
};

double eval(const Expr& e) {
    return std::visit(
        [](const Num& n) -> double { return n.value; },
        [](const Add& a) -> double {
            double sum = 0.0;
            for (const auto& term : a.terms) sum += eval(*term);
            return sum;
        },
        e.node);
}

ExprPtr make_num(double v) {
    return std::make_shared<Expr>(Expr{Num{v}});
}

int main() {
    // (1 + 2) + 3.5
    auto sum = std::make_shared<Expr>(Expr{Add{{make_num(1), make_num(2), make_num(3.5)}}});
    assert(eval(*sum) == 6.5);
    assert(eval(*make_num(42)) == 42.0);
    std::cout << "ok\n";
}
```

The `Expr` indirection with `shared_ptr` is what lets a variant hold itself indirectly. Adding a `Mul` case only requires a new struct and one more visitor overload — the compiler flags any visitor you forget.

