#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity), buf_(capacity) {}

    bool push(int value) {
        if (size_ == cap_) {
            return false;
        }
        buf_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        int v = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }

private:
    std::size_t cap_;
    std::vector<int> buf_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(2);
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << "\n"; // 110
    std::cout << *rb.pop() << *rb.pop() << "\n";                 // 12
    std::cout << (rb.pop().has_value() ? "x" : "empty") << "\n"; // empty
}
```

`head_` plus `size_` tracks the window without moving elements; a full push returns `false` and an empty pop returns `nullopt` instead of reading garbage.

