from collections import deque
from random import randint

def window_max(nums, k):
    if k <= 0:
        raise ValueError("k must be positive")
    result = []
    dq = deque()  # indices, values decreasing
    for i, x in enumerate(nums):
        while dq and nums[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result

def window_max_brute(nums, k):
    return [max(nums[i:i + k]) for i in range(len(nums) - k + 1)]

def test():
    assert window_max([], 3) == []
    assert window_max([5], 1) == [5]
    assert window_max([1, 2, 3], 5) == []
    assert window_max([1, 3, -1, -3, 5, 3, 6, 7], 3) == [3, 3, 5, 5, 6, 7]
    for _ in range(200):
        n = randint(0, 30)
        nums = [randint(-10, 10) for _ in range(n)]
        k = randint(1, max(1, n))
        if n >= k:
            assert window_max(nums, k) == window_max_brute(nums, k)
    print("all tests passed")

if __name__ == "__main__":
    test()
```

The deque holds indices whose values are strictly decreasing, so the front is always the window max. Each index is pushed and popped at most once — O(n) total. Randomised cross-check catches off-by-one errors.

