```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3)
              << rb.push(4) << "\n";      // 1110
    std::cout << *rb.pop() << *rb.pop() << "\n";  // 12
    std::cout << "size=" << rb.size() << "\n";     // size=1
    rb.push(5);
    rb.push(6);
    std::cout << *rb.pop() << *rb.pop() << *rb.pop() << "\n";  // 356
    return 0;
}
```

