```rust
use std::sync::atomic::{AtomicI64, Ordering};
use std::thread;

fn parallel_sum(data: &[i64], threads: usize) -> i64 {
    if data.is_empty() {
        return 0;
    }
    let workers = threads.max(1).min(data.len());
    let chunk = (data.len() + workers - 1) / workers;
    let total = AtomicI64::new(0);

    thread::scope(|scope| {
        for piece in data.chunks(chunk) {
            let slot = &total;
            scope.spawn(move || {
                let local: i64 = piece.iter().sum();
                slot.fetch_add(local, Ordering::Relaxed);
            });
        }
    });

    total.load(Ordering::Relaxed)
}

fn main() {
    let data: Vec<i64> = (1..=1_000_000).collect();
    println!("{}", parallel_sum(&data, 8));
    println!("{}", parallel_sum(&[], 4));
}
```

This uses scoped threads instead of rayon to stay dependency-free. `chunks` splits work into at most `workers` pieces, each thread sums locally then adds atomically once. Empty input short-circuits to 0. Swap in rayon later by replacing the loop with `data.par_iter().sum()`.

