def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    def expand(l: int, r: int) -> tuple[int, int]:
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - 1

    start = end = 0
    for i in range(len(s)):
        l1, r1 = expand(i, i)       # odd length
        l2, r2 = expand(i, i + 1)   # even length
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "abacaba"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```

An empty string returns `""`, a single character returns itself, and ties resolve to the first-found palindrome.

```cpp
#include <iostream>

struct Node {
    int val;
    Node* next;
    explicit Node(int v) : val(v), next(nullptr) {}
};

Node* merge(Node* a, Node* b) {
    Node dummy(0);
    Node* tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) { tail->next = a; a = a->next; }
        else { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

Node* push(Node* head, int v) { return new Node(v); }

void print(Node* head) {
    for (Node* p = head; p; p = p->next) std::cout << p->val << (p->next ? " -> " : "\n");
}

int main() {
    Node* a = push(nullptr, 1);
    a->next = new Node(4);
    a->next->next = new Node(9);

    Node* b = push(nullptr, 2);
    b->next = new Node(3);
    b->next->next = new Node(7);

    Node* merged = merge(a, b);
    print(merged);  // 1 -> 2 -> 3 -> 4 -> 7 -> 9
}
```

The dummy node lets us splice existing nodes verbatim, so no new allocations happen during the merge. The trailing `tail->next = a ? a : b` appends whatever remains untouched.

