#include <deque>
#include <iostream>
#include <optional>

class BoundedQueue {
public:
    explicit BoundedQueue(size_t cap) : cap_(cap) {}

    bool push(int v) {
        if (q_.size() >= cap_) return false;
        q_.push_back(v);
        return true;
    }

    std::optional<int> pop() {
        if (q_.empty()) return std::nullopt;
        int v = q_.front();
        q_.pop_front();
        return v;
    }

    size_t size() const { return q_.size(); }

private:
    std::deque<int> q_;
    size_t cap_;
};

int main() {
    BoundedQueue bq(2);
    std::cout << bq.push(1) << '\n';          // 1
    std::cout << bq.push(2) << '\n';          // 1
    std::cout << bq.push(3) << '\n';          // 0 (full)
    std::cout << *bq.pop() << '\n';           // 1
    std::cout << bq.pop().value_or(-1) << '\n'; // 2
    std::cout << bq.pop().value_or(-1) << '\n'; // -1 (empty)
}
