#include <iostream>
#include <vector>

std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5}, b{2, 4, 6};
    for (int v : merge_sorted(a, b)) std::cout << v << ' ';
    std::cout << "\n";
    for (int v : merge_sorted({}, {})) std::cout << v << ' ';
    std::cout << "\n";
}
```
The two-pointer merge runs in O(n+m) time, `<=` keeps equal keys stable from `a`, and the trailing loops drain whichever list is left. Output: `1 2 3 4 5 6` then a blank line.

