fn split_csv(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut cur = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        if in_quotes {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    cur.push('"');
                    chars.next();
                } else {
                    in_quotes = false;
                }
            } else {
                cur.push(c);
            }
        } else if c == '"' {
            in_quotes = true;
        } else if c == ',' {
            fields.push(std::mem::take(&mut cur));
        } else {
            cur.push(c);
        }
    }
    fields.push(cur);
    fields
}

fn main() {
    println!("{:?}", split_csv("a,\"b,c\",d"));
    println!("{:?}", split_csv("\"he said \"\"hi\"\"\",2"));
    println!("{:?}", split_csv(""));
}
```
A `peekable` iterator lets a doubled `"` inside quotes emit one literal quote. The final `push` captures the last field; empty input yields `[""]`.

