```c
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

#define CAP 8

typedef struct {
    int buf[CAP];
    size_t head;
    size_t count;
} ring_t;

void ring_init(ring_t *r) {
    r->head = 0;
    r->count = 0;
}

bool ring_push(ring_t *r, int value) {
    if (r->count == CAP) {
        return false;
    }
    r->buf[(r->head + r->count) % CAP] = value;
    r->count++;
    return true;
}

bool ring_pop(ring_t *r, int *out) {
    if (r->count == 0) {
        return false;
    }
    *out = r->buf[r->head];
    r->head = (r->head + 1) % CAP;
    r->count--;
    return true;
}

int main(void) {
    ring_t r;
    ring_init(&r);
    for (int i = 0; i < 10; i++) {
        ring_push(&r, i);
    }
    int v;
    while (ring_pop(&r, &v)) {
        printf("%d ", v);
    }
    printf("\n");
    return 0;
}
```
`head` plus `count` avoids the full/empty ambiguity of head-and-tail alone. Pushing 10 values into a capacity-8 buffer accepts the first 8 and drops the rest; popping prints `0 1 2 3 4 5 6 7`.

