#[derive(Debug, PartialEq, Eq)]
pub struct Version<'a> {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub pre: Option<&'a str>,
    pub build: Option<&'a str>,
}

pub fn parse(input: &str) -> Result<Version<'_>, String> {
    let (core, build) = match input.split_once('+') {
        Some((c, b)) => (c, Some(b)),
        None => (input, None),
    };
    let (core, pre) = match core.split_once('-') {
        Some((c, p)) => (c, Some(p)),
        None => (core, None),
    };
    let mut parts = core.split('.');
    let major = parts.next().ok_or("missing major")?.parse().map_err(|_| "bad major")?;
    let minor = parts.next().ok_or("missing minor")?.parse().map_err(|_| "bad minor")?;
    let patch = parts.next().ok_or("missing patch")?.parse().map_err(|_| "bad patch")?;
    if parts.next().is_some() {
        return Err("too many components".into());
    }
    Ok(Version { major, minor, patch, pre, build })
}

fn main() {
    let v = parse("1.2.3-beta+build.7").unwrap();
    assert_eq!((v.major, v.minor, v.patch), (1, 2, 3));
    assert_eq!(v.pre, Some("beta"));
    assert_eq!(v.build, Some("build.7"));
    assert!(parse("1.2").is_err());
    println!("ok");
}
