        assert_eq!(binary_search(&v, &0), Err(0));
        assert_eq!(binary_search(&v, &10), Err(5));
        assert_eq!(binary_search(&v, &6), Err(3));
        assert_eq!(binary_search(&[] as &[i32], &1), Err(0));
