```rust
use std::collections::HashMap;

struct Node<K, V> {
    key: K,
    value: V,
    prev: usize,
    next: usize,
    in_use: bool,
}

pub struct LruCache<K, V> {
    cap: usize,
    map: HashMap<K, usize>,
    nodes: Vec<Node<K, V>>,
    head: Option<usize>,
    tail: Option<usize>,
}

impl<K: std::hash::Hash + Eq + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        LruCache { cap, map: HashMap::new(), nodes: Vec::new(), head: None, tail: None }
    }
    fn unlink(&mut self, i: usize) {
        let (p, n) = (self.nodes[i].prev, self.nodes[i].next);
        match p { Some(p) => self.nodes[p].next = self.nodes[i].next, None => self.head = self.nodes[i].next }
        match n { Some(n) => self.nodes[n].prev = self.nodes[i].prev, None => self.tail = self.nodes[i].prev }
    }
    fn push_front(&mut self, i: usize) {
        self.nodes[i].prev = None;
        self.nodes[i].next = self.head;
        if let Some(h) = self.head { self.nodes[h].prev = Some(i); }
        self.head = Some(i);
        if self.tail.is_none() { self.tail = Some(i); }
    }
    pub fn get(&mut self, key: &K) -> Option<&V> {
        let i = *self.map.get(key)?;
        self.unlink(i);
        self.push_front(i);
        self.nodes.get(i).map(|n| &n.value)
    }
    pub fn put(&mut self, key: K, value: V) {
        if let Some(&i) = self.map.get(&key) {
            self.nodes[i].value = value;
            self.unlink(i);
            self.push_front(i);
            return;
        }
        if self.map.len() >= self.cap {
            if let Some(t) = self.tail {
                let old = self.nodes[t].key.clone();
                self.map.remove(&old);
                self.unlink(t);
                self.nodes[t].in_use = false;
                // reuse slot t
                self.nodes[t].key = key.clone();
                self.nodes[t].value = value;
                self.nodes[t].in_use = true;
                self.map.insert(key, t);
                self.push_front(t);
                return;
            }
        }
        let i = self.nodes.len();
        let (prev, next) = (None, self.head);
        self.nodes.push(Node { key: key.clone(), value, prev, next, in_use: true });
        if let Some(h) = self.head { self.nodes[h].prev = Some(i); }
        self.head = Some(i);
        if self.tail.is_none() { self.tail = Some(i); }
        self.map.insert(key, i);
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, "a");
    c.put(2, "b");
    assert_eq!(c.get(&1), Some(&"a"));
    c.put(3, "c"); // evicts 2
    assert_eq!(c.get(&2), None);
    assert_eq!(c.get(&3), Some(&"c"));
    println!("ok");
}
