void rotate_left(std::vector<int>& v, std::size_t k) {
    if (v.empty()) return;
    k %= v.size();
    std::rotate(v.begin(), v.begin() + static_cast<std::ptrdiff_t>(k), v.end());
}

int main() {
    std::vector<int> a{1, 2, 3, 4, 5};
    rotate_left(a, 2);
    for (int x : a) std::cout << x << ' ';
    std::cout << '\n';  // 3 4 5 1 2

    std::vector<int> empty;
    rotate_left(empty, 3);  // no crash

    std::vector<int> b{1, 2, 3};
    rotate_left(b, 0);
    rotate_left(b, 6);  // same as 0 after modulo
    for (int x : b) std::cout << x << ' ';
    std::cout << '\n';  // 1 2 3
}
```

The empty-vector guard runs before the modulo, so `k %= v.size()` never divides by zero. `std::rotate` does the work in O(n) time and constant extra space.

