use std::collections::HashMap;

/// Count words case-insensitively, return the `n` most frequent as (word, count),
/// sorted by count desc then word asc.
fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let key = word
            .trim_matches(|c: char| !c.is_alphanumeric())
            .to_lowercase();
        if !key.is_empty() {
            *counts.entry(key).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The cat, the CAT! A dog.";
    assert_eq!(top_words(text, 2), vec![
        ("the".to_string(), 3),
        ("a".to_string(), 1),
    ]);
    assert_eq!(top_words("", 5), vec![]);
    assert_eq!(top_words("!!!", 5), vec![]);
    println!("ok");
}
```

`trim_matches` strips punctuation from both ends, and words that reduce to nothing after trimming are skipped so `"!!!"` yields no entries. The tie break on word makes the output deterministic.

