#include <iostream>
#include <stack>
#include <string>
#include <string_view>

bool balanced(std::string_view s) {
    std::stack<char> st;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                st.push(c);
                break;
            case ')':
                if (st.empty() || st.top() != '(') return false;
                st.pop();
                break;
            case ']':
                if (st.empty() || st.top() != '[') return false;
                st.pop();
                break;
            case '}':
                if (st.empty() || st.top() != '{') return false;
                st.pop();
                break;
            default:
                break;  // ignore anything that is not a bracket
        }
    }
    return st.empty();
}

int main() {
    std::cout << std::boolalpha
              << balanced("a(b[c]{d})e") << '\n'   // true
              << balanced("") << '\n'              // true
              << balanced("(]") << '\n'            // false
              << balanced("((") << '\n'            // false
              << balanced(")") << '\n';            // false
}
```

An unmatched closer returns `false` immediately, and any opener still on the stack at the end makes the result `false`, which together cover both under- and over-closing.

