// Reverses a null-terminated string in place using two pointers.
void reverse_cstr(char* s) {
    if (s == nullptr) return;
    size_t n = std::strlen(s);
    if (n < 2) return;
    char* left = s;
    char* right = s + n - 1;
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        ++left;
        --right;
    }
}

int main() {
    char a[] = "hello";
    reverse_cstr(a);
    assert(std::strcmp(a, "olleh") == 0);

    char b[] = "";
    reverse_cstr(b);
    assert(std::strcmp(b, "") == 0);

    char c[] = "x";
    reverse_cstr(c);
    assert(std::strcmp(c, "x") == 0);

    char d[] = "ab";
    reverse_cstr(d);
    assert(std::strcmp(d, "ba") == 0);

    reverse_cstr(nullptr);  // must not crash

    std::cout << "all cases passed\n";
    return 0;
}
