use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();

    for raw in text.split_whitespace() {
        // Strip surrounding punctuation and lowercase for case-insensitive counting.
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(char::to_lowercase)
            .collect();
        if word.is_empty() {
            continue;
        }
        *counts.entry(word).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Higher count first; ties broken alphabetically for deterministic output.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

#[cfg(test)]
mod tests {
    use super::top_words;

    #[test]
    fn basic_and_punctuation() {
        let text = "The cat, the dog. The CAT! A dog.";
        let got = top_words(text, 3);
        assert_eq!(got, vec![
            ("the".to_string(), 3),
            ("cat".to_string(), 2),
            ("dog".to_string(), 2),
        ]);
    }

    #[test]
    fn empty_and_unicode() {
        assert!(top_words("", 5).is_empty());
        assert!(top_words("   ...  ", 5).is_empty());
        let got = top_words("naïve naïve café", 2);
        assert_eq!(got[0], ("naïve".to_string(), 2));
        assert_eq!(got[1], ("café".to_string(), 1));
    }

    #[test]
    fn n_larger_than_vocab() {
        let got = top_words("one two", 10);
        assert_eq!(got.len(), 2);
    }
}
```

`filter` then `flat_map(char::to_lowercase)` handles Unicode correctly: a char like `İ` may lowercase to multiple chars, and dropping punctuation before lowercasing avoids losing letters. Sorting with a tiebreak makes the result deterministic, which matters for tests.

