#include <stdio.h>
#include <stdint.h>
#include <assert.h>

/* Brian Kernighan's method: clears the lowest set bit each iteration,
 * so the loop runs once per set bit rather than 32 times. */
int popcount32(uint32_t x) {
    int count = 0;
    while (x) {
        x &= (x - 1u);
        ++count;
    }
    return count;
}

int main(void) {
    assert(popcount32(0u)          == 0);
    assert(popcount32(1u)          == 1);
    assert(popcount32(0xFFFFFFFFu) == 32);
    assert(popcount32(0x80000000u) == 1);
    assert(popcount32(0xAAAAAAAAu) == 16);
    assert(popcount32(0x00000003u) == 2);

    printf("all cases passed\n");
    return 0;
}
```

For 32-bit values the result is bounded by 32 and fits in an `int`. If you need it portable to wider integers, change the parameter type — the algorithm is type-agnostic because it never assumes a width.

```rust
use std::cmp::Reverse;
use std::collections::BinaryHeap;
use std::io::{self, BufRead};

/// Two-heap structure: a max-heap for the lower half and a min-heap
/// for the upper half, kept within one element of each other.
struct RunningMedian {
    lower: BinaryHeap<i64>,          // max-heap
    upper: BinaryHeap<Reverse<i64>>, // min-heap
}

impl RunningMedian {
    fn new() -> Self {
        RunningMedian { lower: BinaryHeap::new(), upper: BinaryHeap::new() }
    }

    fn push(&mut self, x: i64) {
        // Insert into the correct half.
        match self.lower.peek() {
            Some(&max_lower) if x > max_lower => self.upper.push(Reverse(x)),
            _ => self.lower.push(x),
        }
        // Rebalance so lower.len() == upper.len() or lower.len() == upper.len() + 1.
        if self.lower.len() > self.upper.len() + 1 {
            let v = self.lower.pop().unwrap();
            self.upper.push(Reverse(v));
        } else if self.upper.len() > self.lower.len() {
            let Reverse(v) = self.upper.pop().unwrap();
            self.lower.push(v);
        }
    }

    fn median(&self) -> f64 {
        if self.lower.len() == self.upper.len() {
            let a = *self.lower.peek().unwrap() as f64;
            let Reverse(b) = *self.upper.peek().unwrap();
            (a + b as f64) / 2.0
        } else {
            *self.lower.peek().unwrap() as f64
        }
    }
}

fn main() {
    let stdin = io::stdin();
    let mut rm = RunningMedian::new();
    for line in stdin.lock().lines() {
        let line = line.expect("failed to read line");
        if line.trim().is_empty() { continue; }
        let x: i64 = line.trim().parse().expect("not an integer");
        rm.push(x);
        println!("{:.1}", rm.median());
    }
}
```

Keeping the lower heap equal or one larger makes the median either its root or the average of the two roots. For input `5 2 8 1 9` it prints `5.0, 3.5, 5.0, 3.5, 5.0`. Empty lines are skipped; parsing errors abort with a message rather than panicking silently.

```cpp
#include <cassert>
#include <iostream>
#include <optional>
#include <vector>

// Fixed-capacity FIFO ring buffer.
template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), size_(0) {
        assert(capacity > 0 && "ring buffer needs capacity >= 1");
    }

    bool empty() const { return size_ == 0; }
    bool full()  const { return size_ == cap_; }
    size_t size() const { return size_; }

    // Returns false if the buffer is full.
    bool push(const T& value) {
        if (full()) return false;
        buf_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    // Returns std::nullopt if the buffer is empty.
    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

private:
    std::vector<T> buf_;
    size_t cap_;
    size_t head_;
    size_t size_;
};

int main() {
    RingBuffer<int> rb(3);
    assert(rb.empty() && !rb.full());

    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.full() && !rb.push(4));       // full: push rejects

    assert(rb.pop() == std::optional<int>(1));
    assert(rb.size() == 2 && !rb.full());

    assert(rb.push(4));                      // wrap-around write
    assert(rb.pop() == std::optional<int>(2));
    assert(rb.pop() == std::optional<int>(3));
    assert(rb.pop() == std::optional<int>(4));
    assert(rb.pop() == std::nullopt);        // empty: pop returns nullopt

    std::cout << "all cases passed\n";
    return 0;
}
```

The modulo arithmetic on `(head_ + size_) % cap_` lets reads and writes wrap without moving elements. `std::optional` makes the empty-pop case explicit instead of returning a sentinel value that could be a valid element.

