#include <iostream>
#include <vector>

static std::vector<unsigned long long> memo;

unsigned long long fib(unsigned n) {
    if (n < memo.size()) return memo[n];
    // Grow the memo table to n+1 entries.
    while (memo.size() <= n) {
        size_t i = memo.size();
        if (i <= 1) {
            memo.push_back(i);
        } else {
            unsigned long long next = memo[i - 1] + memo[i - 2];
            if (next < memo[i - 1]) {
                std::cerr << "overflow at n=" << i << "\n";
                return 0;
            }
            memo.push_back(next);
        }
    }
    return memo[n];
}

int main() {
    std::cout << fib(0) << "\n";   // 0
    std::cout << fib(1) << "\n";   // 1
    std::cout << fib(50) << "\n";  // 12586269025
    std::cout << fib(93) << "\n";  // near limit
    fib(200);                       // triggers overflow message
    return 0;
}
