/* Reverses a NUL-terminated byte string in place.
 * NOTE: this reverses bytes, which is correct for single-byte encodings
 * such as ASCII/Latin-1 but will split multi-byte UTF-8 sequences.
 * For full UTF-8 support you must reverse code points instead. */
static void reverse_bytes(char *s) {
    if (!s) return;
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; i++) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_bytes(a);
    printf("%s\n", a);  // olleh

    char b[] = "";
    reverse_bytes(b);
    printf("%s\n", b);  // empty

    char c[] = "ab";
    reverse_bytes(c);
    printf("%s\n", c);  // ba
    return 0;
}
