#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t i = 0, j = strlen(s);
    if (j == 0) return;
    j--;
    while (i < j) {
        char t = s[i];
        s[i] = s[j];
        s[j] = t;
        i++;
        j--;
    }
}

// Usage:
// char buf[] = "hello";  // must be writable
// reverse_in_place(buf); // buf == "olleh"
