```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <cstddef>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t cap) : cap_(cap) {}

    bool push(T value) {
        std::unique_lock<std::mutex> lk(mu_);
        not_full_.wait(lk, [&] { return closed_ || q_.size() < cap_; });
        if (closed_) return false;
        q_.push(std::move(value));
        not_empty_.notify_one();
        return true;
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lk(mu_);
        not_empty_.wait(lk, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;
        T v = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lk(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<T> q_;
    std::mutex mu_;
    std::condition_variable not_empty_, not_full_;
    bool closed_ = false;
};
```

Push blocks while full and pop blocks while empty; `close()` wakes both waiters and lets in-flight calls return cleanly (`false`/`nullopt`). Guards in the wait predicates make the `closed_` short-circuit safe against spurious wakeups.

