```cpp
#include <utility>
#include <iostream>

class ScopeGuard {
public:
    template <typename F>
    explicit ScopeGuard(F&& f) : cleanup_(std::forward<F>(f)), active_(true) {}

    ScopeGuard(const ScopeGuard&) = delete;
    ScopeGuard& operator=(const ScopeGuard&) = delete;

    ~ScopeGuard() { if (active_) cleanup_(); }

    void dismiss() noexcept { active_ = false; }

private:
    std::function<void()> cleanup_;
    bool active_;
};

void work() {
    ScopeGuard guard([]{ std::cout << "cleanup\n"; });
    throw std::runtime_error("boom"); // cleanup still runs during unwind
}
```

The destructor fires during stack unwinding, so the lambda runs whether the scope exits normally or via an exception. `dismiss()` disables it when you decide cleanup is no longer needed. Copying is deleted to prevent double execution.

