    for (word, count) in ranked.iter().take(10) {
        println!("{count:>4} {word}");
    }
}
```

The sort is explicit about tie-breaking by word, so output is deterministic across runs; bad UTF-8 from stdin would surface as a read error instead of silently dropping bytes.

```cpp
#include <algorithm>
#include <string>
#include <vector>

int edit_distance(const std::string& a, const std::string& b) {
    const std::size_t n = a.size();
    const std::size_t m = b.size();
    std::vector<int> prev(m + 1), cur(m + 1);

    for (std::size_t j = 0; j <= m; ++j) {
        prev[j] = static_cast<int>(j);
    }

    for (std::size_t i = 1; i <= n; ++i) {
        cur[0] = static_cast<int>(i);
        for (std::size_t j = 1; j <= m; ++j) {
            int cost = (a[i - 1] == b[j - 1]) ? 0 : 1;
            cur[j] = std::min({prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost});
        }
        std::swap(prev, cur);
    }
    return prev[m];
}
```

Only two rows of the DP table are kept, so memory is `O(min(n, m))` rather than quadratic; each cell takes the best of deletion, insertion and substitution.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._store = OrderedDict()

    def get(self, key):
        if key not in self._store:
            return None
        self._store.move_to_end(key)
        return self._store[key]

    def put(self, key, value):
        if key in self._store:
            self._store.move_to_end(key)
        self._store[key] = value
        if len(self._store) > self.capacity:
            self._store.popitem(last=False)

    def __len__(self):
        return len(self._store)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1
    cache.put("c", 3)          # evicts "b" because "a" was just used
    assert cache.get("b") is None
    assert cache.get("a") == 1
    assert cache.get("c") == 3
    assert len(cache) == 2
    print("ok")
```

`OrderedDict.move_to_end` marks a key as recently used on both reads and updates, and `popitem(last=False)` evicts the least recently used entry in O(1).

