```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int* data;
    size_t size;
    size_t capacity;
} IntVec;

int vec_init(IntVec* v, size_t initial) {
    if (initial == 0) initial = 4;
    v->data = malloc(initial * sizeof(int));
    if (!v->data) return -1;
    v->size = 0;
    v->capacity = initial;
    return 0;
}

int vec_push(IntVec* v, int value) {
    if (v->size == v->capacity) {
        size_t new_cap = v->capacity * 2;
        int* tmp = realloc(v->data, new_cap * sizeof(int));
        if (!tmp) return -1;
        v->data = tmp;
        v->capacity = new_cap;
    }
    v->data[v->size++] = value;
    return 0;
}

int vec_pop(IntVec* v, int* out) {
    if (v->size == 0) return -1;
    *out = v->data[--v->size];
    return 0;
}

void vec_free(IntVec* v) {
    free(v->data);
    v->data = NULL;
    v->size = v->capacity = 0;
}

int main(void) {
    IntVec v;
    if (vec_init(&v, 0) != 0) { fprintf(stderr, "init failed\n"); return 1; }
    for (int i = 0; i < 100; i++) {
        if (vec_push(&v, i * i) != 0) { fprintf(stderr, "push failed\n"); vec_free(&v); return 1; }
    }
    int x;
    if (vec_pop(&v, &x) != 0 || x != 99 * 99) { fprintf(stderr, "pop failed\n"); vec_free(&v); return 1; }
    printf("size=%zu cap=%zu last=%d\n", v.size, v.capacity, x);
    vec_free(&v);
    return 0;
}
