```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t cap) : data_(cap), cap_(cap) {}

    void push(int v) {
        if (size_ == cap_) throw std::overflow_error("ring buffer full");
        data_[(head_ + size_) % cap_] = v;
        ++size_;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int v = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<int> data_;
    std::size_t cap_, head_ = 0, size_ = 0;
};

int main() {
    RingBuffer rb(3);
    try { rb.push(1); rb.push(2); rb.push(3); rb.push(4); }
    catch (const std::overflow_error& e) { std::cout << "caught: " << e.what() << '\n'; }
    std::cout << rb.pop().value() << ' ' << rb.pop().value() << '\n';
    rb.push(9);
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n';
    return 0;
}
```

Indices wrap modulo capacity, so a full buffer throws instead of silently dropping data; the `optional` return distinguishes "empty" from a stored zero.

```rust
fn longest_common_prefix(words: &[String]) -> String {
    let first = match words.first() {
        Some(w) => w.as_bytes(),
        None => return String::new(),
    };
    let mut end = first.len();
    for w in &words[1..] {
        let b = w.as_bytes();
        end = end.min(b.len());
        let mut i = 0;
        while i < end && first[i] == b[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    String::from_utf8_lossy(&first[..end]).into_owned()
}

fn main() {
    let cases: Vec<Vec<String>> = vec![
        vec!["flower".into(), "flow".into(), "flight".into()],
        vec!["dog".into(), "racecar".into(), "car".into()],
        vec![],
        vec!["same".into()],
    ];
    for c in &cases {
        println!("{:?} -> {:?}", c, longest_common_prefix(c));
    }
    assert_eq!(longest_common_prefix(&cases[0]), "fl");
    assert_eq!(longest_common_prefix(&cases[1]), "");
}
```

The prefix can only shrink, so each comparison is bounded by the current `end`; byte-slicing is valid because a common prefix is always a whole number of leading bytes.

```rust
struct RunningMax<I, T> {
    iter: I,
    current: Option<T>,
}

impl<I, T> RunningMax<I, T>
where
    I: Iterator<Item = T>,
    T: PartialOrd + Clone,
{
    fn new(iter: I) -> Self {
        RunningMax { iter, current: None }
    }
}

impl<I, T> Iterator for RunningMax<I, T>
where
    I: Iterator<Item = T>,
    T: PartialOrd + Clone,
{
    type Item = T;

    fn next(&mut self) -> Option<T> {
        let v = self.iter.next()?;
        let best = match &self.current {
            Some(c) if *c >= v => c.clone(),
            _ => {
                self.current = Some(v.clone());
                v
            }
        };
        Some(best)
    }
}

fn main() {
    let xs = [3, 1, 4, 1, 5, 9, 2];
    let out: Vec<i32> = RunningMax::new(xs.iter().copied()).collect();
    println!("{:?}", out);
    assert_eq!(out, vec![3, 3, 4, 4, 5, 9, 9]);
}
```

Each `next` compares the incoming value with the stored maximum, updating it only on a strict increase, so the output is monotonic non-decreasing.

