#include <iostream>

struct Node {
    int value;
    Node* next;
};

bool has_cycle(Node* head) {
    Node* slow = head;
    Node* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

int main() {
    Node a{1, nullptr}, b{2, nullptr}, c{3, nullptr}, d{4, nullptr};
    a.next = &b; b.next = &c; c.next = &d;
    std::cout << std::boolalpha << has_cycle(&a) << '\n';  // false
    d.next = &b;                                           // cycle b->c->d->b
    std::cout << has_cycle(&a) << '\n';                    // true
    return 0;
}
```

The fast pointer moves twice as fast, so if a cycle exists it must eventually land on the slow pointer inside the loop; the null checks keep tail-only lists terminating cleanly.

