```cpp
#include <algorithm>
#include <stdexcept>
#include <vector>

template <typename T>
double median(std::vector<T> v) {
    if (v.empty()) {
        throw std::invalid_argument("median of empty vector");
    }
    std::sort(v.begin(), v.end());
    std::size_t n = v.size();
    if (n % 2 == 1) {
        return static_cast<double>(v[n / 2]);
    }
    return (static_cast<double>(v[n / 2 - 1]) + static_cast<double>(v[n / 2])) / 2.0;
}
```

The vector is taken by value so the caller's data is not reordered. Odd lengths return the middle element; even lengths average the two middle ones. Empty input throws rather than returning a bogus 0.

