```python
import random

def kth_smallest(nums, k):
    """Return the k-th smallest element (1-indexed k) in nums."""
    if not nums or k < 1 or k > len(nums):
        raise ValueError("k out of range")

    def partition(arr, lo, hi, pivot_idx):
        pivot = arr[pivot_idx]
        arr[pivot_idx], arr[hi] = arr[hi], arr[pivot_idx]
        store = lo
        for i in range(lo, hi):
            if arr[i] < pivot:
                arr[i], arr[store] = arr[store], arr[i]
                store += 1
        arr[store], arr[hi] = arr[hi], arr[store]
        return store

    lo, hi = 0, len(nums) - 1
    while True:
        if lo == hi:
            return nums[lo]
        pivot_idx = random.randint(lo, hi)
        p = partition(nums, lo, hi, pivot_idx)
        if p == k - 1:
            return nums[p]
        elif p < k - 1:
            lo = p + 1
        else:
            hi = p - 1

if __name__ == "__main__":
    print(kth_smallest([7, 10, 4, 3, 20, 15], 3))  # 7
    print(kth_smallest([1], 1))                     # 1
    print(kth_smallest([5, 5, 5], 2))               # 5 (duplicates ok)
```

The guard rejects empty input and out-of-range `k`, duplicates are handled because the partition compares by value, not index.

