/// Return the longest line (by char count) from the file, or None if empty.
/// The trailing newline is stripped. Bytes are counted as chars via `chars()`,
/// so UTF-8 content is measured correctly.
pub fn longest_line<P: AsRef<Path>>(path: P) -> io::Result<Option<String>> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);

    let mut best: Option<String> = None;
    let mut best_len = 0usize;

    for line in reader.lines() {
        let line = line?; // propagate invalid UTF-8 / IO errors
        let len = line.chars().count();
        if len > best_len {
            best_len = len;
            best = Some(line);
        }
    }
    Ok(best)
}

