```python
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, "a")
    c.put(2, "b")
    print(c.get(1))      # a  (1 is now most-recent)
    c.put(3, "c")        # evicts 2
    print(c.get(2))      # None
    print(c.get(3))      # c
    c.put(3, "c2")       # update existing, no evict
    print(c.get(3))      # c2
```

`OrderedDict` gives O(1) move/pop, so both operations are constant time. Recency is maintained by moving touched keys to the end and evicting from the front.

