void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0) return;
    --j;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
        --j;
    }
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "a";

    reverse_in_place(a);
    reverse_in_place(b);
    reverse_in_place(c);
    reverse_in_place(NULL);

    printf("%s\n", a);  /* olleh */
    printf("[%s]\n", b); /* [] */
    printf("%s\n", c);  /* a */
    return 0;
}
