fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let expected = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(expected) {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    let cases = [("([]{})", true), ("([)]", false), ("", true),
                 ("(", false), (")", false), ("{[()]}", true)];
    for (input, want) in cases {
        let got = is_balanced(input);
        println!("{:?} -> {} (want {})", input, got, want);
        assert_eq!(got, want);
    }
}
```

A stack pushes every opening bracket; a closing bracket must match the top or the function returns false early. At the end the stack must be empty, so an unmatched opener like `"("` fails. Non-bracket characters are ignored, and the empty string is balanced.

```cpp
#include <queue>
#include <mutex>
#include <condition_variable>
#include <stdexcept>
#include <optional>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(T value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return q_.size() < cap_ || closed_; });
        if (closed_) return;
        q_.push(std::move(value));
        not_empty_.notify_one();
    }

    // Blocks until an item is available or the queue is closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;  // closed and drained
        T value = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::queue<T> q_;
    size_t cap_;
    bool closed_ = false;
    std::mutex mu_;
    std::condition_variable not_empty_, not_full_;
};
```

The predicate overloads of `wait` guard against spurious wakeups. `close()` wakes every waiter and lets consumers drain then get `nullopt`, so producers and consumers can shut down without deadlock.

```python
import hashlib
import os
import sys
from collections import defaultdict

def file_hash(path, chunk=1 << 20):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            block = f.read(chunk)
            if not block:
                break
            h.update(block)
    return h.hexdigest()

def find_duplicates(root):
    # Bucket by size first: different sizes can never collide, so we skip hashing them.
    by_size = defaultdict(list)
    for dirpath, _dirs, files in os.walk(root):
        for name in files:
            p = os.path.join(dirpath, name)
            if os.path.islink(p) or not os.path.isfile(p):
                continue
            try:
                by_size[os.path.getsize(p)].append(p)
            except OSError as e:
                print(f"skip {p}: {e}", file=sys.stderr)

    by_hash = defaultdict(list)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue
        for p in paths:
            try:
                by_hash[file_hash(p)].append(p)
            except OSError as e:
                print(f"skip {p}: {e}", file=sys.stderr)

    return [sorted(group) for group in by_hash.values() if len(group) > 1]

if __name__ == "__main__":
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    for group in sorted(find_duplicates(root)):
        print("duplicates:")
        for path in group:
            print("  " + path)
```

Hashing is streamed in 1 MiB chunks so large files do not load into memory. Grouping by file size first avoids hashing unique-sized files. Symlinks and unreadable files are skipped with a warning rather than crashing the walk.

