import sys


def validate_ipv4(text: str) -> tuple[bool, str]:
    """Return (ok, reason). Reason is 'valid' when ok is True."""
    if not text:
        return False, "empty string"

    parts = text.split(".")
    if len(parts) != 4:
        return False, f"expected 4 octets, got {len(parts)}"

    for index, part in enumerate(parts, start=1):
        if not part:
            return False, f"octet {index} is empty"
        if not part.isdigit():
            return False, f"octet {index} is not numeric: {part!r}"
        if len(part) > 1 and part[0] == "0":
            return False, f"octet {index} has a leading zero: {part!r}"
        value = int(part)
        if value > 255:
            return False, f"octet {index} out of range: {value}"

    return True, "valid"


