        "0.0.0.0",
        "255.255.255.255",
        "256.1.1.1",
        "1.2.3",
        "1.2.3.04",
        "1.2.3.a",
        "...",
    ]
    for sample in samples:
        ok, reason = validate_ipv4(sample)
        print(f"{sample!r:20} -> {ok} ({reason})")
