#include <cctype>
#include <iostream>
#include <stdexcept>
#include <string>
#include <unordered_map>

static std::string trim(const std::string& s) {
    std::size_t start = 0;
    std::size_t end = s.size();
    while (start < end && std::isspace(static_cast<unsigned char>(s[start]))) ++start;
    while (end > start && std::isspace(static_cast<unsigned char>(s[end - 1]))) --end;
    return s.substr(start, end - start);
}

std::unordered_map<std::string, std::string> parse_pairs(const std::string& line) {
    std::unordered_map<std::string, std::string> out;
    std::size_t pos = 0;

    while (pos <= line.size()) {
        std::size_t sep = line.find(';', pos);
        std::string token = line.substr(pos, sep == std::string::npos ? std::string::npos : sep - pos);
        token = trim(token);

        if (!token.empty()) {
            std::size_t eq = token.find('=');
            if (eq == std::string::npos) {
                throw std::invalid_argument("missing '=' in token: " + token);
            }
            std::string key = trim(token.substr(0, eq));
            std::string value = trim(token.substr(eq + 1));
            if (key.empty()) {
                throw std::invalid_argument("empty key in token: " + token);
            }
            out[key] = value;
        }

        if (sep == std::string::npos) break;
        pos = sep + 1;
    }
    return out;
}

int main() {
    auto result = parse_pairs(" host = localhost ; port=8080 ; note= ; ;");
    if (result.size() != 3) { std::cerr << "bad size\n"; return 1; }
    if (result.at("host") != "localhost") return 1;
    if (result.at("port") != "8080") return 1;
    if (result.at("note") != "") return 1;

    try {
        parse_pairs("broken");
        std::cerr << "expected throw\n";
        return 1;
    } catch (const std::invalid_argument&) {
        // expected
    }

    std::cout << "ok\n";
    return 0;
}
```

Empty tokens between separators are skipped, keys and values are trimmed, and a missing `=` raises `std::invalid_argument`. Empty values are stored as empty strings, which is why `note` is present with size 3.

