#include <stdexcept>
#include <vector>

// Kahan-compensated accumulation: avoids the drift from many small additions.
template <typename T>
T mean(const std::vector<T>& values) {
    if (values.empty()) {
        throw std::invalid_argument("mean of empty vector");
    }

    T sum = T(0);
    T compensation = T(0);
    for (const T& v : values) {
        T y = v - compensation;
        T t = sum + y;
        compensation = (t - sum) - y;
        sum = t;
    }
    return sum / static_cast<T>(values.size());
}

int main() {
    std::vector<double> tiny(100000, 0.1);
    double naive = 0.0;
    for (double v : tiny) naive += v;
    double kahan = mean(tiny);

    std::cout.precision(17);
    std::cout << "naive/1e5 : " << naive / 1e5 << "\n";
    std::cout << "kahan    : " << kahan << "\n";

    std::vector<int> ints = {2, 4, 6};
    if (mean(ints) != 4) return 1;

    std::vector<double> one = {3.5};
    if (mean(one) != 3.5) return 1;

    try {
        mean(std::vector<double>{});
        return 1;  // should have thrown
    } catch (const std::invalid_argument&) {
        // expected
    }

    std::cout << "ok\n";
    return 0;
}
```

For `double` the naive sum of 100000 copies of 0.1 drifts noticeably from 0.1, while the compensated sum lands closer to the true value. For integer `T` there is no compensation benefit and overflow is still possible if the sum exceeds `T`; pair it with a wider accumulator (for example `long long`) when that matters.

