        std::fs::write(&p, "The cat, the CAT! A dog. the end.").unwrap();
        p
    } else {
        std::path::PathBuf::from(path)
    };

    match top_words(target.to_str().unwrap(), 3) {
        Ok(words) => {
            for (w, c) in words {
                println!("{w}: {c}");
            }
        }
        Err(e) => eprintln!("error: {e}"),
    }
}
