```rust
#[derive(Debug, PartialEq)]
pub enum BracketError {
    UnexpectedClose(char, usize),
    Mismatch { expected: char, found: char, index: usize },
    Unclosed(char, usize),
}

pub fn check(input: &str) -> Result<(), BracketError> {
    let mut stack: Vec<(char, usize)> = Vec::new();

    for (index, ch) in input.char_indices() {
        match ch {
            '(' | '[' | '{' => stack.push((ch, index)),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    None => return Err(BracketError::UnexpectedClose(ch, index)),
                    Some((open, _)) if open == expected => {}
                    Some((open, _)) => {
                        return Err(BracketError::Mismatch { expected: open, found: ch, index })
                    }
                }
            }
            _ => {}
        }
    }

    match stack.pop() {
        None => Ok(()),
        Some((open, index)) => Err(BracketError::Unclosed(open, index)),
    }
}

fn main() {
    assert_eq!(check("a(b[c]{d})e"), Ok(()));
    assert_eq!(check(""), Ok(()));
    assert_eq!(check("(])"), Err(BracketError::Mismatch { expected: '(', found: ']', index: 1 }));
    assert_eq!(check("(()"), Err(BracketError::Unclosed('(', 0)));
    assert_eq!(check(")"), Err(BracketError::UnexpectedClose(')', 0)));
    println!("all bracket checks passed");
}
```

`char_indices` gives byte offsets, so reported indices point at the offending byte even for multi-byte characters. Using a stack of `(char, index)` lets the mismatch case name the expected opener and where it sits. Other characters are ignored.

