#include <iostream>
#include <vector>
#include <stdexcept>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), size_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(double value) {
        std::size_t pos = (head_ + size_) % buf_.size();
        buf_[pos] = value;
        if (size_ < buf_.size()) {
            ++size_;
        } else {
            head_ = (head_ + 1) % buf_.size();
        }
    }

    std::vector<double> to_vector() const {
        std::vector<double> out;
        out.reserve(size_);
        for (std::size_t k = 0; k < size_; ++k)
            out.push_back(buf_[(head_ + k) % buf_.size()]);
        return out;
    }

private:
    std::vector<double> buf_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    for (double v : {1.5, 2.5, 3.5, 4.5})
        rb.push(v);
    for (double v : rb.to_vector()) std::cout << v << ' ';
    std::cout << '\n';
    return 0;
}
```
After four pushes into a three-slot buffer the oldest value `1.5` is overwritten, so iteration prints `2.5 3.5 4.5`. The `head_`/`size_` pair avoids ambiguity between full and empty states.

