```python
OPS = {
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '/': lambda a, b: a / b,
}

def rpn_eval(expr):
    stack = []
    for tok in expr.split():
        if tok in OPS:
            if len(stack) < 2:
                raise ValueError(f"operator {tok!r} needs two operands")
            b = stack.pop()
            a = stack.pop()
            if tok == '/' and b == 0:
                raise ZeroDivisionError("division by zero")
            stack.append(OPS[tok](a, b))
        else:
            try:
                stack.append(float(tok))
            except ValueError:
                raise ValueError(f"bad token: {tok!r}")
    if len(stack) != 1:
        raise ValueError("expression left extra values on the stack")
    return stack[0]

if __name__ == "__main__":
    print(rpn_eval("3 4 + 2 *"))
    print(rpn_eval("5 1 2 + 4 * + 3 -"))
```
`3 4 + 2 *` gives 14 and the second expression gives 14 as well. Each malformed case — too few operands, unknown token, leftover values — raises a specific error rather than failing silently.

