```cpp
#include <condition_variable>
#include <mutex>
#include <queue>
#include <optional>

template <typename T>
class BoundedQueue {
    std::queue<T> q_;
    size_t cap_;
    std::mutex m_;
    std::condition_variable not_full_, not_empty_;
public:
    explicit BoundedQueue(size_t cap) : cap_(cap) {}

    bool push(T value) {
        std::unique_lock<std::mutex> lock(m_);
        not_full_.wait(lock, [&]{ return q_.size() < cap_; });
        q_.push(std::move(value));
        not_empty_.notify_one();
        return true;
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(m_);
        not_empty_.wait(lock, [&]{ return !q_.empty(); });
        T v = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return v;
    }
};
```

The predicate form of `wait` guards against spurious wakeups. `notify_one` wakes exactly one waiter, so a single push does not thundering-herd all consumers.

