    size_t n = std::strlen(s);
    for (size_t i = 0; i < n / 2; ++i) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
}

int main() {
    char a[] = "hello";
    reverse_in_place(a);
    std::cout << a << "\n";   // olleh

    char empty[] = "";
    reverse_in_place(empty);
    std::cout << "[" << empty << "]\n";  // []
}
```

Two pointers move toward the middle, `n / 2` iterations, O(1) extra space. The `n == 0` case skips the loop, so the empty string stays empty.

```rust
pub struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self {
        Stack { items: Vec::new() }
    }
    pub fn push(&mut self, value: T) {
        self.items.push(value);
    }
    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }
    pub fn peek(&self) -> Option<&T> {
        self.items.last()
    }
    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
}

impl<T> Default for Stack<T> {
    fn default() -> Self {
        Self::new()
    }
}

fn main() {
    let mut s = Stack::new();
    s.push(1);
    s.push(2);
    assert_eq!(s.peek(), Some(&2));
    assert_eq!(s.pop(), Some(2));
    assert!(s.pop().is_some());
    assert_eq!(s.pop(), None);
}
```

