```cpp
#include <list>
#include <unordered_map>
#include <iostream>

template <typename K, typename V>
class LRUCache {
    size_t cap_;
    std::list<std::pair<K, V>> items_;
    std::unordered_map<K, typename std::list<std::pair<K, V>>::iterator> idx_;
public:
    explicit LRUCache(size_t cap) : cap_(cap) {}

    V* get(const K& key) {
        auto it = idx_.find(key);
        if (it == idx_.end()) return nullptr;
        items_.splice(items_.begin(), items_, it->second);
        return &it->second->second;
    }

    void put(const K& key, const V& value) {
        auto it = idx_.find(key);
        if (it != idx_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (items_.size() == cap_) {
            idx_.erase(items_.back().first);
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        idx_[key] = items_.begin();
    }
};

int main() {
    LRUCache<int, int> c(2);
    c.put(1, 1);
    c.put(2, 2);
    std::cout << *c.get(1) << "\n";  // 1 (now most recent)
    c.put(3, 3);                     // evicts 2
    std::cout << (c.get(2) ? "hit" : "miss") << "\n";  // miss
}
```

The list holds recency order (front = newest); the map stores list iterators so `get` can `splice` in O(1). Eviction removes the back of the list and erases its key from the map.

