fn binary_search(haystack: &[i32], needle: i32) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = haystack.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if haystack[mid] == needle {
            return Some(mid);
        } else if haystack[mid] < needle {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    None
}

