    let data = [-5, -1, 0, 3, 3, 7, 42];
    assert_eq!(binary_search(&data, 7), Some(5));
    assert_eq!(binary_search(&data, -5), Some(0));
    assert_eq!(binary_search(&data, 4), None);
    assert_eq!(binary_search(&[], 1), None);
