        perror("fseek");
        fclose(f);
        return 1;
    }
    long size = ftell(f);
    if (size < 0) {
        perror("ftell");
        fclose(f);
        return 1;
    }
    rewind(f);

    char *buf = malloc((size_t)size + 1);
    if (!buf) {
        perror("malloc");
        fclose(f);
        return 1;
    }

    size_t got = fread(buf, 1, (size_t)size, f);
    buf[got] = '\0';
    printf("%zu\n", got);

    free(buf);
    fclose(f);
    return 0;
}
