void reverse_in_place(char* s) {
    if (s == nullptr) {
        return;
    }
    std::size_t left = 0;
    std::size_t right = std::strlen(s);
    if (right == 0) {
        return;
    }
    --right;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        ++left;
        --right;
    }
}

int main() {
