```c
#include <stdio.h>
#include <string.h>

static int matches(char open, char close) {
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

static int is_balanced(const char *s) {
    char stack[256];
    size_t top = 0;
    for (size_t i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            if (top >= sizeof(stack)) return 0;
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0 || !matches(stack[--top], c)) return 0;
        }
    }
    return top == 0;
}

int main(void) {
    const char *tests[] = {"", "()[]{}", "([{}])", "(]", "(((", "a(b)c"};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); i++) {
        printf("%-10s -> %s\n", tests[i], is_balanced(tests[i]) ? "balanced" : "not balanced");
    }
    return 0;
}
```

A fixed 256-byte stack tracks opening delimiters. Every closing delimiter must match the top of the stack, and any leftover opens at the end mean the string is not balanced. The empty string returns `1`, and non-delimiter characters are ignored.

