def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def next_leap_years(start, count=5):
    result = []
    year = start
    while len(result) < count:
        if is_leap(year):
            result.append(year)
        year += 1
    return result

def main():
    raw = input("Year: ").strip()
    if not raw.isdigit():
        print(f"error: '{raw}' is not a positive year")
        return
    year = int(raw)
    print(f"{year} leap: {is_leap(year)}")
    print("next five:", next_leap_years(year + 1))

if __name__ == "__main__":
    main()
```

