fn check_brackets(s: &str) -> Result<(), (usize, char)> {
    let mut stack: Vec<char> = Vec::new();
    let pairs = [(')', '('), (']', '['), ('}', '{')];

    for (i, c) in s.char_indices() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let expected = pairs.iter().find(|(close, _)| *close == c).unwrap().1;
                match stack.pop() {
                    Some(open) if open == expected => {}
                    _ => return Err((i, c)),
                }
            }
            _ => {}
        }
    }

    if let Some(open) = stack.first() {
        let idx = s.find(*open).unwrap_or(0);
        return Err((idx, *open));
    }
    Ok(())
}

fn main() {
    assert!(check_brackets("a(b[c]{d})e").is_ok());
    assert!(check_brackets("([)]").is_err());
    assert!(check_brackets("(]").is_err());
    assert_eq!(check_brackets("(abc").unwrap_err().1, '(');
    println!("all checks passed");
}
