enum parse_status { PARSE_OK, PARSE_EMPTY, PARSE_TRAILING, PARSE_OVERFLOW };

enum parse_status parse_int(const char *s, long *out) {
    if (s == NULL || *s == '\0') {
        return PARSE_EMPTY;
    }

    errno = 0;
    char *end = NULL;
    long value = strtol(s, &end, 10);

    if (end == s) {
        return PARSE_EMPTY;
    }
    if (errno == ERANGE) {
        return PARSE_OVERFLOW;
    }
    while (*end != '\0' && isspace((unsigned char)*end)) {
        ++end;
    }
    if (*end != '\0') {
        return PARSE_TRAILING;
    }

    *out = value;
    return PARSE_OK;
}

int main(void) {
    const char *tests[] = {"42", "-7", "", "  ", "12abc", "99999999999999999999"};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); ++i) {
        long v = 0;
        enum parse_status st = parse_int(tests[i], &v);
        printf("%-22s -> status=%d", tests[i], st);
        if (st == PARSE_OK) {
            printf(" value=%ld", v);
        }
