def pair_sum(nums, target):
    """Return list of unique index-pairs (i, j), i < j, where nums[i]+nums[j]==target."""
    if not nums:
        return []
    seen = {}
    pairs = []
    for i, n in enumerate(nums):
        need = target - n
        if need in seen:
            for j in seen[need]:
                pairs.append((j, i))
        seen.setdefault(n, []).append(i)
    return pairs


if __name__ == "__main__":
    print(pair_sum([1, 2, 3, 4, 3], 6))   # [(1, 3), (2, 4), (0, 4)? no]
    print(pair_sum([], 5))                # []
    print(pair_sum([2, 2, 2], 4))         # [(0, 1), (0, 2), (1, 2)]
```

Each earlier index of the complement is stored, so every valid pair is emitted exactly once with `i < j`. Empty input returns `[]` without touching the dict.

