```cpp
#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
    std::array<T, N> buf_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
public:
    bool push(const T& v) {
        if (count_ == N) return false;
        buf_[(head_ + count_) % N] = v;
        ++count_;
        return true;
    }
    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T v = buf_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return v;
    }
    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
};

#include <cassert>
int main() {
    RingBuffer<int, 3> rb;
    assert(rb.empty());
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(!rb.push(4));              // full
    assert(rb.pop() == 1);
    assert(rb.push(4));
    assert(rb.size() == 3);
    assert(rb.pop() == 2 && rb.pop() == 3 && rb.pop() == 4);
    assert(rb.empty());
}
```

`head_` marks the oldest slot and `count_` tracks occupancy, so wrap-around needs no sentinel slot. `push` returns `false` when full instead of overwriting; `pop` returns `std::optional` for the empty case.

