#include <stdio.h>
#include <string.h>
#include <stddef.h>

struct kv { char key[64]; char value[192]; };

static int parse_kv(const char *line, struct kv *out) {
    if (!line || !out) return -1;
    const char *eq = strchr(line, '=');
    if (!eq || eq == line) return -1;
    size_t klen = (size_t)(eq - line);
    const char *val = eq + 1;
    size_t vlen = strlen(val);
    if (klen >= sizeof(out->key) || vlen >= sizeof(out->value)) return -1;
    memcpy(out->key, line, klen);
    out->key[klen] = '\0';
    memcpy(out->value, val, vlen);
    out->value[vlen] = '\0';
    return 0;
}

int main(void) {
    const char *lines[] = { "name=XT-Luna", "a=b=c", "=bad", "toolong" };
    for (size_t i = 0; i < sizeof(lines) / sizeof(lines[0]); ++i) {
        struct kv kv = {0};
        if (parse_kv(lines[i], &kv) == 0)
            printf("key='%s' value='%s'\n", kv.key, kv.value);
        else
            printf("skip: '%s'\n", lines[i]);
    }
    return 0;
}
```

The split is on the first `=`, so `a=b=c` keeps `b=c` as the value. Both lengths are checked before `memcpy`, and every copied field is explicitly NUL-terminated. Empty keys and lines with no `=` are rejected with `-1`.

