#include <stdio.h>
#include <stdint.h>
#include <limits.h>

/* Returns 1 on success and stores the result in *out, 0 on invalid input. */
int fib(uint64_t n, uint64_t *out) {
    if (out == NULL) return 0;
    uint64_t a = 0, b = 1;
    for (uint64_t i = 0; i < n; ++i) {
        uint64_t next = a + b;
        if (next < a) return 0; /* overflow detected on unsigned wrap */
        a = b;
        b = next;
    }
    *out = a;
    return 1;
}

int main(void) {
    uint64_t v;
    if (!fib(10, &v)) { printf("error\n"); return 1; }
    printf("fib(10)=%llu\n", (unsigned long long)v);

    if (!fib(50, &v)) { printf("overflow\n"); return 1; }
    printf("fib(50)=%llu\n", (unsigned long long)v);
    return 0;
}
```

