bool is_palindrome(std::int64_t value) {
    if (value < 0) return false;
    if (value % 10 == 0 && value != 0) return false;
    std::int64_t reversed = 0;
    while (value > reversed) {
        if (reversed > (std::numeric_limits<std::int64_t>::max() - value % 10) / 10) return false;
        reversed = reversed * 10 + value % 10;
        value /= 10;
    }
    return value == reversed || value == reversed / 10;
}

