    if (!is_palindrome(12321)) return 1;
    if (is_palindrome(12345)) return 1;
    if (is_palindrome(-121)) return 1;
    if (is_palindrome(10)) return 1;
    if (!is_palindrome(1000000001)) return 1;
    std::cout << "ok" << std::endl;
    return 0;
