use std::collections::HashMap;

fn fib(n: u64) -> u64 {
    let mut memo: HashMap<u64, u64> = HashMap::new();
    fn helper(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {
        if n < 2 {
            return n;
        }
        if let Some(&cached) = memo.get(&n) {
            return cached;
        }
        let value = helper(n - 1, memo) + helper(n - 2, memo);
        memo.insert(n, value);
        value
    }
    helper(n, &mut memo)
}

fn main() {
    assert_eq!(fib(0), 0);
    assert_eq!(fib(1), 1);
    assert_eq!(fib(10), 55);
    assert_eq!(fib(20), 6765);
    println!("ok");
}
