```cpp
#include <array>
#include <cstddef>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : capacity_(capacity) {}

    bool push(int value) {
        if (size_ == capacity_) return false;
        data_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return capacity_; }

private:
    std::size_t capacity_;
    std::array<int, 64> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

#include <cassert>
#include <iostream>

int main() {
    RingBuffer buf(3);
    assert(buf.push(1) && buf.push(2) && buf.push(3));
    assert(!buf.push(4));
    assert(buf.pop() == 1);
    assert(buf.push(4));
    assert(buf.size() == 3);
    assert(buf.pop() == 2);
    assert(buf.pop() == 3);
    assert(buf.pop() == 4);
    assert(!buf.pop().has_value());
    std::cout << "ok\n";
}
```

The modulo arithmetic on `head_` wraps the indices, and `push` refuses with `false` once full instead of silently overwriting, which is the safer default for a queue.

