    let text = fs::read_to_string("data.txt")?;
    let values = parse_numbers(&text)?;
    let (mean, sd) = mean_and_stddev(&values);
    println!("count={} mean={:.4} stddev={:.4}", values.len(), mean, sd);
    Ok(())
}

