    if (!tab) return 1;
    int n = 0;
    char buf[MAX_LEN];
    while (scanf("%63s", buf) == 1) {
        for (char *p = buf; *p; ++p) *p = (char)tolower((unsigned char)*p);
        int found = 0;
        for (int i = 0; i < n; ++i) {
            if (strcmp(tab[i].word, buf) == 0) { tab[i].count++; found = 1; break; }
        }
        if (!found && n < MAX_WORDS) {
            strncpy(tab[n].word, buf, MAX_LEN - 1);
            tab[n].count = 1;
            n++;
        }
    }
    qsort(tab, n, sizeof(Entry), cmp);
    for (int i = 0; i < n && i < 3; ++i)
        printf("%s %d\n", tab[i].word, tab[i].count);
    free(tab);
    return 0;
}
