bool isPalindrome(const std::string& s) {
    size_t i = 0, j = s.size();
    while (i < j) {
        if (j == 0) break;
        --j;
        if (i >= j) break;
        if (!std::isalnum(static_cast<unsigned char>(s[i]))) { ++i; ++j; continue; }
        if (!std::isalnum(static_cast<unsigned char>(s[j]))) { ++i; continue; }
        if (std::tolower(static_cast<unsigned char>(s[i])) !=
            std::tolower(static_cast<unsigned char>(s[j]))) return false;
        ++i;
    }
    return true;
