        return data_.back();
    }

    bool empty() const { return data_.empty(); }
    size_t size() const { return data_.size(); }

private:
    std::vector<int> data_;
};

int main() {
    Stack s;
    s.push(1);
    s.push(2);
    s.push(3);
    std::cout << s.peek() << "\n";   // 3
    std::cout << s.pop() << "\n";    // 3
    std::cout << s.size() << "\n";   // 2
    try {
        Stack empty;
        empty.pop();
    } catch (const std::out_of_range& e) {
        std::cout << "caught: " << e.what() << "\n";
    }
    return 0;
}
```

`push` is amortised O(1) and `pop`/`peek` are O(1). Throwing on empty access makes the failure explicit instead of returning a sentinel that could be a valid value.

