class FileHandle {
public:
    FileHandle() noexcept : fp_(nullptr) {}
    explicit FileHandle(const char* path) : fp_(std::fopen(path, "r")) {}
    ~FileHandle() { if (fp_) std::fclose(fp_); }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fp_(other.fp_) { other.fp_ = nullptr; }
    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            if (fp_) std::fclose(fp_);
            fp_ = other.fp_;
            other.fp_ = nullptr;
        }
        return *this;
    }

    FILE* get() const noexcept { return fp_; }
    bool valid() const noexcept { return fp_ != nullptr; }

private:
    FILE* fp_;
};

int main() {
    FileHandle fh("data.txt");
    if (!fh.valid()) return 1;
    FileHandle other = std::move(fh);
    return other.valid() ? 0 : 1;
}
