fn max_by<T, F>(items: &[T], greater: F) -> Option<&T>
where
    F: Fn(&T, &T) -> bool,
{
    let mut best: Option<&T> = None;
    for item in items {
        best = match best {
            None => Some(item),
            Some(cur) if greater(item, cur) => Some(item),
            Some(cur) => Some(cur),
        };
    }
    best
}

fn main() {
    let nums = [3, 9, 2, 7];
    assert_eq!(max_by(&nums, |a, b| a > b), Some(&9));

    let words = ["pear", "fig", "banana"];
    assert_eq!(max_by(&words, |a, b| a.len() > b.len()), Some(&"banana"));

    let empty: [i32; 0] = [];
    assert_eq!(max_by(&empty, |a, b| a > b), None);

    println!("ok");
}
```
Only a `Fn(&T, &T) -> bool` predicate is required, so callers can rank by length, a key function, or any relation. An empty slice returns `None` instead of panicking.

