#include <iostream>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), count_(0) {}

    bool push(double v) {
        if (count_ == cap_) return false;
        buf_[(head_ + count_) % cap_] = v;
        ++count_;
        return true;
    }

    bool pop(double& out) {
        if (count_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --count_;
        return true;
    }

    size_t size() const { return count_; }

private:
    std::vector<double> buf_;
    size_t cap_, head_, count_;
};

int main() {
    RingBuffer rb(3);
    std::cout << rb.push(1.5) << rb.push(2.5) << rb.push(3.5) << rb.push(4.5) << '\n';
    double v;
    while (rb.pop(v)) std::cout << v << ' ';
    std::cout << "\nempty pop: " << rb.pop(v) << '\n';
    return 0;
}
```

A zero-capacity buffer would make `% cap_` divide by zero, so in production guard the constructor; the boolean returns signal full and empty conditions to the caller.

