#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse_list(Node* head) {
    Node* prev = nullptr;
    Node* curr = head;
    while (curr != nullptr) {
        Node* next = curr->next;  // save before we relink
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;  // new head
}

void print(Node* head) {
    for (Node* n = head; n; n = n->next) std::cout << n->value << ' ';
    std::cout << '\n';
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    print(head);            // 1 2 3
    head = reverse_list(head);
    print(head);            // 3 2 1
    while (head) { Node* n = head->next; delete head; head = n; }
    return 0;
}
```

