import re

_PATTERN = re.compile(r"^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$")


def duration_to_seconds(text):
    """Parse '1h30m45s' style strings into total seconds."""
    if not isinstance(text, str) or not text:
        raise ValueError("empty duration")
    match = _PATTERN.match(text)
    if match is None or all(part is None for part in match.groups()):
        raise ValueError(f"malformed duration: {text!r}")
    hours, minutes, seconds = (int(p or 0) for p in match.groups())
    return hours * 3600 + minutes * 60 + seconds


if __name__ == "__main__":
    cases = {
        "1h30m45s": 5445,
        "2m": 120,
        "45s": 45,
        "1h": 3600,
        "10h5s": 36005,
    }
    for text, expected in cases.items():
        assert duration_to_seconds(text) == expected, text
    for bad in ("", "1x", "h", "30m1h", "1h30m45s7"):
        try:
            duration_to_seconds(bad)
        except ValueError:
            continue
        raise AssertionError(f"expected failure for {bad!r}")
    print("ok")
```

