```cpp
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <vector>

// Rotate right by k positions; k is normalised into [0, size).
void rotate_right(std::vector<int>& data, long long k) {
    const auto n = static_cast<long long>(data.size());
    if (n == 0) return;
    k %= n;
    if (k < 0) k += n;
    if (k == 0) return;
    const auto mid = data.begin() + (n - k);
    std::reverse(data.begin(), mid);
    std::reverse(mid, data.end());
    std::reverse(data.begin(), data.end());
}

int main() {
    std::vector<int> a{1, 2, 3, 4, 5};
    rotate_right(a, 2);
    assert((a == std::vector<int>{4, 5, 1, 2, 3}));

    std::vector<int> b{1, 2, 3};
    rotate_right(b, -1);
    assert((b == std::vector<int>{2, 3, 1}));

    std::vector<int> c{7};
    rotate_right(c, 100);
    assert((c == std::vector<int>{7}));

    std::vector<int> empty;
    rotate_right(empty, 3);
    assert(empty.empty());

    std::vector<int> d{1, 2, 3, 4};
    rotate_right(d, 8);
    assert((d == std::vector<int>{1, 2, 3, 4}));

    std::cout << "ok\n";
    return 0;
}
```

The three-reversal trick rotates in O(n) time and O(1) space. Normalising `k` into `[0, n)` handles negative and oversized shifts; `n == 0` and `k == 0` short-circuit.

