#include <assert.h>
#include <stdio.h>
#include <string.h>

static void reverse_range(char *s, size_t i, size_t j) {
    while (i < j) {
        char t = s[i];
        s[i++] = s[j];
        s[j--] = t;
    }
}

size_t reverse_words(char *s) {
    size_t n = strlen(s);
    if (n == 0) return 0;
    reverse_range(s, 0, n - 1);
    size_t start = 0;
    for (size_t i = 0; i <= n; i++) {
        if (i == n || s[i] == ' ') {
            reverse_range(s, start, i ? i - 1 : 0);
            start = i + 1;
        }
    }
    return n;
}

int main(void) {
    char a[] = "hello world foo";
    assert(reverse_words(a) == 15);
    assert(strcmp(a, "foo world hello") == 0);

    char b[] = "";
    assert(reverse_words(b) == 0);

    char c[] = "one";
    assert(reverse_words(c) == 3);
    assert(strcmp(c, "one") == 0);

    char d[] = "a b c";
    assert(reverse_words(d) == 5);
    assert(strcmp(d, "c b a") == 0);

    printf("ok\n");
    return 0;
}
