            .flat_map(|c| c.to_lowercase())
            .collect();
        if !key.is_empty() {
            *counts.entry(key).or_insert(0) += 1;
        }
    }
    let mut ranked: Vec<(String, usize)> = counts.into_iter().collect();
    ranked.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    ranked.truncate(n);
    ranked
}

fn main() {
    let text = "The cat, the CAT! A dog. the dog";
    let top = top_words(text, 2);
    assert_eq!(top, vec![("the".to_string(), 4), ("dog".to_string(), 2)]);

    assert!(top_words("", 3).is_empty());
    assert_eq!(top_words("only", 5), vec![("only".to_string(), 1)]);
    println!("ok");
}
```

Words are stripped of punctuation and lowercased before counting, so `The` and `the` merge. The comparator ranks by count descending, then lexicographically ascending, and `truncate` caps the result at `n`.

```cpp
#include <condition_variable>
#include <cstddef>
#include <mutex>
#include <optional>
#include <queue>
#include <utility>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {}

    BoundedQueue(const BoundedQueue&) = delete;
    BoundedQueue& operator=(const BoundedQueue&) = delete;

    // Blocks while full. Returns false if the queue was shut down.
    bool push(T value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [this] { return closed_ || items_.size() < capacity_; });
        if (closed_) return false;
        items_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }

    // Blocks while empty. Returns nullopt if closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock, [this] { return closed_ || !items_.empty(); });
        if (items_.empty()) return std::nullopt;
        T value = std::move(items_.front());
        items_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    // Wake all waiters; pop drains remaining items then reports empty.
    void close() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            closed_ = true;
        }
        not_full_.notify_all();
        not_empty_.notify_all();
    }

private:
    const std::size_t capacity_;
    std::queue<T> items_;
    mutable std::mutex mutex_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
    bool closed_ = false;
};
```

Both waits use predicates so spurious wakeups are harmless. Notifications happen after releasing the lock, which avoids waking a thread that then blocks on the mutex we still hold. `close()` sets the flag then wakes everyone; `pop` drains remaining items before returning `nullopt`.

```rust
fn max_subarray_sum(nums: &[i64]) -> i64 {
    let mut best = 0i64;
    let mut current = 0i64;
    for &n in nums {
        current = n.max(current + n);
        best = best.max(current);
    }
    best
}

fn main() {
    assert_eq!(max_subarray_sum(&[]), 0);
    assert_eq!(max_subarray_sum(&[-3, -1, -7]), 0);
    assert_eq!(max_subarray_sum(&[2, -1, 3, -2, 4]), 6);
    assert_eq!(max_subarray_sum(&[1]), 1);
    assert_eq!(max_subarray_sum(&[-1, 5, -1, 5]), 9);
    assert_eq!(max_subarray_sum(&[i64::MAX]), i64::MAX);
    assert_eq!(max_subarray_sum(&[i64::MIN, 1]), 1);
    println!("ok");
}
```

The recurrence is `current = max(n, current + n)`: start fresh at `n` when the running sum would drag it down. `best` starts at 0 so an empty slice and an all-negative slice both yield 0, matching the stated contract. Every step stays within `i64` here since each partial sum is bounded by the element magnitudes in the positive direction.

