```python
class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._buf = [None] * capacity
        self._start = 0
        self._size = 0

    def push(self, item):
        idx = (self._start + self._size) % self.capacity
        self._buf[idx] = item
        if self._size < self.capacity:
            self._size += 1
        else:
            self._start = (self._start + 1) % self.capacity

    def pop(self):
        if self._size == 0:
            raise IndexError("pop from empty ring buffer")
        item = self._buf[self._start]
        self._buf[self._start] = None
        self._start = (self._start + 1) % self.capacity
        self._size -= 1
        return item

    def __len__(self):
        return self._size

    def __iter__(self):
        for i in range(self._size):
            yield self._buf[(self._start + i) % self.capacity]


if __name__ == "__main__":
    rb = RingBuffer(3)
    for x in [1, 2, 3, 4]:
        rb.push(x)
    assert list(rb) == [2, 3, 4]
    assert rb.pop() == 2
    assert list(rb) == [3, 4]
    print("ok")
```

When full, the oldest item is overwritten by advancing `_start`. Iteration walks `_start` to `_start + _size - 1` modulo capacity, so it always reflects insertion order.

