#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v, Node* n = nullptr) : value(v), next(n) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void destroy(Node* head) {
    while (head) {
        Node* n = head->next;
        delete head;
        head = n;
    }
}

int main() {
    Node* head = new Node(1, new Node(2, new Node(3, new Node(4))));
    head = reverse(head);
    for (Node* p = head; p; p = p->next)
        std::cout << p->value << ' ';
    std::cout << "\n";          // prints 4 3 2 1
    destroy(head);
    return 0;
}
```

Iterative reversal is O(n) time, O(1) extra space. `destroy` is separate so the list is freed even though the head pointer moved.

```rust
use std::collections::HashSet;

fn dedup_ordered<T: Eq + std::hash::Hash + Clone>(items: &[T]) -> Vec<T> {
    let mut seen = HashSet::with_capacity(items.len());
    let mut out = Vec::with_capacity(items.len());
    for item in items {
        if seen.insert(item.clone()) {
            out.push(item.clone());
        }
    }
    out
}

fn main() {
    let data = vec!["b", "a", "b", "c", "a"];
    println!("{:?}", dedup_ordered(&data)); // ["b", "a", "c"]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty() {
        let v: Vec<i32> = vec![];
        assert_eq!(dedup_ordered(&v), Vec::<i32>::new());
    }

    #[test]
    fn preserves_first_order() {
        assert_eq!(dedup_ordered(&[3, 1, 3, 2, 1]), vec![3, 1, 2]);
    }

    #[test]
    fn unicode_strings() {
        let v = vec!["é", "ñ", "é"];
        assert_eq!(dedup_ordered(&v), vec!["é", "ñ"]);
    }
}
```

`HashSet::insert` returns false on a repeat, so the first occurrence is kept and later ones are dropped. The generic bound requires `Hash + Eq + Clone`, which covers integers and `&str`.

