```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 2;
    }
    FILE *fp = fopen(argv[1], "rb");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    unsigned long long counts[256] = {0};
    int c;
    while ((c = fgetc(fp)) != EOF) {
        counts[(unsigned char)c]++;
    }
    if (ferror(fp)) {
        perror("read");
        fclose(fp);
        return 1;
    }
    fclose(fp);

    int idx[256];
    int n = 0;
    for (int i = 0; i < 256; i++) {
        if (counts[i] > 0) idx[n++] = i;
    }

    /* simple selection sort on the present bytes, by count desc then value asc */
    for (int i = 0; i < n; i++) {
        int best = i;
        for (int j = i + 1; j < n; j++) {
            unsigned long long a = counts[idx[j]];
            unsigned long long b = counts[idx[best]];
            if (a > b || (a == b && idx[j] < idx[best])) best = j;
        }
        int tmp = idx[i];
        idx[i] = idx[best];
        idx[best] = tmp;
    }

    int limit = n < 10 ? n : 10;
    for (int i = 0; i < limit; i++) {
        printf("%02x %llu\n", idx[i], counts[idx[i]]);
    }
    return 0;
}
```

It reads in binary mode so `0x1A` and `\r\n` are not mangled, uses `unsigned char` for indexing, and breaks count ties by byte value so output is deterministic.

```python
import hashlib
import os
import sys
from collections import defaultdict

CHUNK = 1 << 16


def file_digest(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            block = f.read(CHUNK)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def find_duplicates(root: str) -> dict:
    by_size = defaultdict(list)
    for dirpath, dirnames, filenames in os.walk(root):
        for name in filenames:
            path = os.path.join(dirpath, name)
            try:
                size = os.path.getsize(path)
            except OSError:
                continue
            by_size[size].append(path)

    duplicates = defaultdict(list)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue
        for path in paths:
            try:
                digest = file_digest(path)
            except OSError as exc:
                print(f"skipping {path}: {exc}", file=sys.stderr)
                continue
            duplicates[(size, digest)].append(path)

    return {k: v for k, v in duplicates.items() if len(v) > 1}


if __name__ == "__main__":
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    for (size, digest), paths in sorted(find_duplicates(root).items()):
        print(f"{size} bytes, {digest[:12]}")
        for p in sorted(paths):
            print(f"  {p}")
```

Grouping by size first avoids hashing unique files, and the chunked read keeps memory flat for large files.

