```cpp
#include <cstdint>
#include <numeric>
#include <iostream>
#include <cassert>
#include <limits>
#include <stdexcept>

template <typename T>
T gcd(T a, T b) {
    static_assert(std::is_integral<T>::value, "integral type required");
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        T t = a % b;
        a = b;
        b = t;
    }
    return a;
}

template <typename T>
T lcm(T a, T b) {
    static_assert(std::is_integral<T>::value, "integral type required");
    if (a == 0 || b == 0) return 0;
    T g = gcd(a, b);
    T reduced = a / g;
    const T maxv = std::numeric_limits<T>::max();
    if (reduced > maxv / (b < 0 ? -b : b)) {
        throw std::overflow_error("lcm overflow");
    }
    return reduced * b;
}

int main() {
    assert(gcd(48, 18) == 6);
    assert(gcd(-48, 18) == 6);
    assert(lcm(4, 6) == 12);
    assert(lcm(0, 5) == 0);
    assert(lcm(21, 6) == 42);

    try {
        lcm<int>(std::numeric_limits<int>::max(), 2);
        assert(false && "expected overflow");
    } catch (const std::overflow_error&) {
        std::cout << "all checks passed\n";
    }
    return 0;
}
```

Dividing by the gcd before multiplying keeps the intermediate product small, and the guard throws instead of silently wrapping when the true LCM cannot fit in `T`.

