```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int v) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) {
        return head;
    }
    n->value = v;
    n->next = head;
    return n;
}

static void print_list(const Node *head) {
    for (; head != NULL; head = head->next) {
        printf("%d%s", head->value, head->next ? " -> " : "\n");
    }
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 5; i >= 1; i--) {
        head = push(head, i);
    }
    head = reverse(head);
    print_list(head);  /* 5 -> 4 -> 3 -> 2 -> 1 */
    free_list(head);
    return 0;
}
```
Reversal is O(n) time and O(1) space. `free_list` walks the already-reversed chain, so no node is leaked or double-freed.

