template <typename T>
class RunningMedian {
public:
    void add(T value) {
        if (low_.empty() || value <= low_.top()) {
            low_.push(value);
        } else {
            high_.push(value);
        }
        if (low_.size() > high_.size() + 1) {
            high_.push(low_.top());
            low_.pop();
