    double median() const {
        if (low_.empty()) {
            return 0.0;
        }
        if (low_.size() == high_.size()) {
            return (static_cast<double>(low_.top()) + static_cast<double>(high_.top())) / 2.0;
        }
        return static_cast<double>(low_.top());
    }

private:
    std::priority_queue<T> low_;                                  // max-heap
    std::priority_queue<T, std::vector<T>, std::greater<T>> high_; // min-heap
};

int main() {
    RunningMedian<int> rm;
    for (int v : {5, 2, 8, 1}) {
        rm.add(v);
    }
    assert(rm.median() == 3.5);  // 1,2,5,8
    rm.add(0);
    assert(rm.median() == 2.0);  // 0,1,2,5,8
    assert(RunningMedian<int>{}.median() == 0.0);
    std::cout << "ok\n";
}
```
The max-heap holds the lower half and the min-heap the upper half, rebalanced after each insert so the median is available in O(log n) per insert and O(1) lookup.

