#include <cstddef>
#include <utility>
#include <iostream>

template <typename T>
class RefCounted {
public:
    explicit RefCounted(T* ptr = nullptr) : ptr_(ptr), count_(ptr ? new std::size_t(1) : nullptr) {}

    RefCounted(const RefCounted& other) : ptr_(other.ptr_), count_(other.count_) {
        if (count_) ++*count_;
    }

    RefCounted(RefCounted&& other) noexcept : ptr_(other.ptr_), count_(other.count_) {
        other.ptr_ = nullptr;
        other.count_ = nullptr;
    }

    RefCounted& operator=(RefCounted other) {
        swap(other);
        return *this;
    }

    ~RefCounted() { release(); }

    T& operator*() const { return *ptr_; }
    T* operator->() const { return ptr_; }
    std::size_t use_count() const { return count_ ? *count_ : 0; }

private:
    void release() {
        if (count_ && --*count_ == 0) {
            delete ptr_;
            delete count_;
        }
        ptr_ = nullptr;
        count_ = nullptr;
    }

    void swap(RefCounted& other) noexcept {
        std::swap(ptr_, other.ptr_);
        std::swap(count_, other.count_);
    }

    T* ptr_;
    std::size_t* count_;
};

int main() {
    RefCounted<int> a(new int(42));
    RefCounted<int> b = a;
    std::cout << a.use_count() << " " << *b << "\n";
    b = RefCounted<int>(new int(7));
    std::cout << a.use_count() << " " << *b << "\n";
    return 0;
}
```
The copy-and-swap assignment gives correct self-assignment and exception behaviour; the move constructor nulls the source so its destructor does not release.

