    if (!in) {
        std::cerr << "cannot open " << argv[1] << "\n";
        return 1;
    }

    std::vector<double> values;
    std::string line;
    std::size_t skipped = 0;
    while (std::getline(in, line)) {
        std::stringstream ss(line);
        std::string cell;
        while (std::getline(ss, cell, ',')) {
            try {
                std::size_t used = 0;
                double v = std::stod(cell, &used);
                if (used != cell.size()) throw std::invalid_argument("trailing");
                values.push_back(v);
            } catch (...) {
                ++skipped;
            }
        }
    }

    if (values.empty()) {
        std::cout << "no numeric data (skipped " << skipped << ")\n";
        return 0;
    }

    double sum = 0.0;
    for (double v : values) sum += v;
    double mean = sum / values.size();

    double sq = 0.0;
    for (double v : values) sq += (v - mean) * (v - mean);
    double sd = std::sqrt(sq / values.size());

    std::cout << "n=" << values.size() << " mean=" << mean << " sd=" << sd
              << " skipped=" << skipped << "\n";
    return 0;
}
