#include <iostream>
#include <stdexcept>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity), buf_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(double v) {
        buf_[head_] = v;
        head_ = (head_ + 1) % cap_;
        if (size_ < cap_) ++size_;
    }

    double get(std::size_t i) const {
        if (i >= size_) throw std::out_of_range("index");
        std::size_t start = (head_ + cap_ - size_) % cap_;
        return buf_[(start + i) % cap_];
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return cap_; }

private:
    std::size_t cap_;
    std::vector<double> buf_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    rb.push(1.0);
    rb.push(2.0);
    rb.push(3.0);
    rb.push(4.0);  // overwrites 1.0
    for (std::size_t i = 0; i < rb.size(); ++i)
