```rust
use std::collections::HashMap;
use std::hash::Hash;

struct Node<K, V> {
    key: K,
    value: V,
    prev: Option<usize>,
    next: Option<usize>,
}

pub struct LruCache<K, V> {
    map: HashMap<K, usize>,
    nodes: Vec<Node<K, V>>,
    head: Option<usize>,
    tail: Option<usize>,
    cap: usize,
}

impl<K: Eq + Hash + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache { map: HashMap::new(), nodes: Vec::new(), head: None, tail: None, cap }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        let idx = *self.map.get(key)?;
        self.move_to_front(idx);
        Some(&self.nodes[idx].value)
    }

    pub fn put(&mut self, key: K, value: V) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].value = value;
            self.move_to_front(idx);
            return;
        }
        if self.nodes.len() == self.cap {
            if let Some(t) = self.tail {
                let k = self.nodes[t].key.clone();
                self.map.remove(&k);
                self.detach(t);
                self.nodes[t].prev = None;
                self.nodes[t].next = None;
                self.map.insert(key.clone(), t);
                self.nodes[t] = Node { key, value, prev: None, next: None };
                self.attach_front(t);
                return;
            }
        }
        let idx = self.nodes.len();
        self.nodes.push(Node { key: key.clone(), value, prev: None, next: None });
        self.map.insert(key, idx);
        self.attach_front(idx);
    }

    fn attach_front(&mut self, idx: usize) {
        self.nodes[idx].next = self.head;
        if let Some(h) = self.head {
            self.nodes[h].prev = Some(idx);
        }
        self.head = Some(idx);
        if self.tail.is_none() {
            self.tail = Some(idx);
        }
    }

    fn detach(&mut self, idx: usize) {
        let (p, n) = (self.nodes[idx].prev, self.nodes[idx].next);
        match p {
            Some(p) => self.nodes[p].next = n,
            None => self.head = n,
        }
        match n {
            Some(n) => self.nodes[n].prev = p,
            None => self.tail = p,
        }
    }

    fn move_to_front(&mut self, idx: usize) {
        if self.head == Some(idx) {
            return;
        }
        self.detach(idx);
        self.attach_front(idx);
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put("a", 1);
    c.put("b", 2);
    assert_eq!(c.get(&"a"), Some(&1));
    c.put("c", 3);
    assert_eq!(c.get(&"b"), None);
    assert_eq!(c.get(&"a"), Some(&1));
    println!("ok");
}
```
The index-based list avoids unsafe pointers. Note the eviction path reuses the slot of the old tail; detach must run before re-initialising it.

