#[derive(Debug, PartialEq)]
pub enum BracketError {
    UnexpectedClose(usize),
    UnmatchedOpen(usize),
}

pub fn check_balanced(s: &str) -> Result<(), BracketError> {
    let mut stack: Vec<(char, usize)> = Vec::new();
    let pairs = |c: char| matches!(c, ')' | ']' | '}');

    for (i, c) in s.char_indices() {
        match c {
            '(' | '[' | '{' => stack.push((c, i)),
            _ if pairs(c) => match stack.pop() {
                Some((open, _)) if matches!((open, c), ('(', ')') | ('[', ']') | ('{', '}')) => {}
                _ => return Err(BracketError::UnexpectedClose(i)),
            },
            _ => {}
        }
    }

    match stack.last() {
        Some(&(_, i)) => Err(BracketError::UnmatchedOpen(i)),
        None => Ok(()),
    }
}

fn main() {
    assert_eq!(check_balanced("([]{})"), Ok(()));
    assert_eq!(check_balanced("(]"), Err(BracketError::UnexpectedClose(1)));
    assert_eq!(check_balanced("(()"), Err(BracketError::UnmatchedOpen(0)));
    println!("ok");
}
```
char_indices reports byte offsets, which is correct for reporting positions in a &str even with multi-byte characters.

