#include <algorithm>
#include <iostream>
#include <vector>

struct Interval {
    int start;
    int end;
};

std::vector<Interval> merge(std::vector<Interval> intervals) {
    if (intervals.empty()) return {};
    std::sort(intervals.begin(), intervals.end(),
              [](const Interval& a, const Interval& b) { return a.start < b.start; });
    std::vector<Interval> out{intervals[0]};
    for (std::size_t i = 1; i < intervals.size(); ++i) {
        if (intervals[i].start <= out.back().end) {
            out.back().end = std::max(out.back().end, intervals[i].end);
        } else {
            out.push_back(intervals[i]);
        }
    }
    return out;
}

int main() {
    std::vector<Interval> in{{1, 3}, {2, 6}, {8, 10}, {15, 18}};
    for (const auto& iv : merge(in)) {
        std::cout << '[' << iv.start << ", " << iv.end << "] ";
    }
    std::cout << '\n';
    return 0;
}
