```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

class BlockingQueue {
public:
    explicit BlockingQueue(std::size_t capacity) : capacity_(capacity) {}

    void push(int value) {
        std::unique_lock<std::mutex> lock(m_);
        not_full_.wait(lock, [&] { return q_.size() < capacity_ || closed_; });
        if (closed_) return;
        q_.push(value);
        not_empty_.notify_one();
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(m_);
        not_empty_.wait(lock, [&] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;
        int v = q_.front();
        q_.pop();
        not_full_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lock(m_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::queue<int> q_;
    std::size_t capacity_;
    bool closed_ = false;
    std::mutex m_;
    std::condition_variable not_empty_, not_full_;
};
```

`pop` returns `std::nullopt` only after `close`, so consumers never block forever. Both waits use a predicate to survive spurious wakeups, and each push/pop wakes exactly one waiter on the opposite side.

