use std::collections::HashMap;

fn fib(n: u64, memo: &mut HashMap<u64, u128>) -> Result<u128, String> {
    if n == 0 {
        return Ok(0);
    }
    if n == 1 {
        return Ok(1);
    }
    if let Some(&v) = memo.get(&n) {
        return Ok(v);
    }
    let a = fib(n - 1, memo)?;
    let b = fib(n - 2, memo)?;
    let result = a.checked_add(b).ok_or_else(|| format!("overflow at n={n}"))?;
    memo.insert(n, result);
    Ok(result)
}

fn main() {
    let mut memo = HashMap::new();
    assert_eq!(fib(10, &mut memo).unwrap(), 55);
    assert!(fib(200, &mut memo).is_err());
    println!("{}", fib(90, &mut memo).unwrap());
}
```

`checked_add` turns the silent `u128` wrap into an explicit `Result`, and the memo table stores only values that fit, so a later query near the boundary still reports the error instead of a corrupt number.

