int lowerBound(const std::vector<int>& a, int target) {
    int lo = 0;
    int hi = static_cast<int>(a.size());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

int main() {
    std::vector<int> a{1, 3, 5, 7};
    std::cout << lowerBound(a, 5) << '\n';  // 2 (found)
    std::cout << lowerBound(a, 4) << '\n';  // 2 (insertion point)
    std::cout << lowerBound(a, 0) << '\n';  // 0
    std::cout << lowerBound(a, 9) << '\n';  // 4
    return 0;
}
```

The `mid = lo + (hi - lo) / 2` form avoids overflow on large arrays. The half-open range `[lo, hi)` means the loop ends with `lo` equal to the first index whose element is not less than the target, which is the insertion point.

```cpp
#include <algorithm>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

// Binary search on a sorted vector; returns index or -1.
template <typename T>
std::ptrdiff_t binary_search_idx(const std::vector<T>& v, const T& target) {
    std::size_t lo = 0, hi = v.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (v[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    if (lo < v.size() && v[lo] == target) return static_cast<std::ptrdiff_t>(lo);
    return -1;
}

int main() {
    std::vector<int> v{1, 3, 3, 5, 8};
    if (binary_search_idx(v, 3) != 1) return 1;
    if (binary_search_idx(v, 4) != -1) return 1;
    std::vector<int> empty;
    if (binary_search_idx(empty, 0) != -1) return 1;
    std::cout << "ok\n";
    return 0;
}
