        n %= 100;
        if (n) out += " ";
    }
    if (n >= 20) {
        out += tens[n / 10];
        if (n % 10) out += std::string("-") + ones[n % 10];
    } else if (n > 0) {
        out += ones[n];
    }
    return out;
