    bool neg = n < 0;
    unsigned long long u = neg ? -static_cast<unsigned long long>(n) : static_cast<unsigned long long>(n);
    std::string out;
    if (u >= 1000000) { out += below_thousand(static_cast<int>(u / 1000000)) + " million"; u %= 1000000; if (u) out += " "; }
