use std::thread;

/// Bounded counter with a mutex; each of `threads` increments `per_thread` times.
fn concurrent_sum(threads: usize, per_thread: usize) -> usize {
    let counter = Arc::new(Mutex::new(0usize));
    let mut handles = Vec::with_capacity(threads);
    for _ in 0..threads {
        let c = Arc::clone(&counter);
        handles.push(thread::spawn(move || {
            for _ in 0..per_thread {
                let mut guard = c.lock().unwrap();
                *guard += 1;
            }
        }));
    }
    for h in handles {
        h.join().unwrap();
    }
    let total = *counter.lock().unwrap();
    total
}

fn main() {
    let got = concurrent_sum(4, 1000);
    assert_eq!(got, 4000);
    assert_eq!(concurrent_sum(0, 10), 0);
    assert_eq!(concurrent_sum(3, 0), 0);
    println!("ok");
