// Check whether two strings are anagrams, case-insensitively, ignoring spaces.
bool is_anagram(std::string a, std::string b) {
    std::unordered_map<char, int> diff;
    auto norm = [](std::string& s) {
        std::string out;
        for (char c : s) {
            if (c == ' ') continue;
            out += static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        }
        return out;
    };
    a = norm(a);
    b = norm(b);
    if (a.size() != b.size()) return false;
    for (char c : a) diff[c]++;
    for (char c : b) {
        if (--diff[c] < 0) return false;
    }
    return true;
}

int main() {
    if (!is_anagram("Listen", "Silent")) return 1;
    if (!is_anagram("Eleven plus two", "Twelve plus one")) return 1;
    if (is_anagram("abc", "abd")) return 1;
    if (!is_anagram("", "")) return 1;
    std::cout << "ok\n";
    return 0;
