#include <iostream>

struct Node {
    int value;
    Node* next;
    Node(int v, Node* n = nullptr) : value(v), next(n) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void print(const char* label, Node* head) {
    std::cout << label;
    for (Node* cur = head; cur; cur = cur->next) {
        std::cout << cur->value;
        if (cur->next) std::cout << " -> ";
    }
    std::cout << '\n';
}

int main() {
    Node* head = new Node(1, new Node(2, new Node(3, new Node(4))));
    print("before: ", head);
    head = reverse(head);
    print("after:  ", head);
    while (head) {
        Node* dead = head;
        head = head->next;
        delete dead;
    }
    return 0;
}
```

Three pointers: `prev` trails, `head` is the current node, `next` saves the rest before relinking. The loop is O(n) time, O(1) space. Deletion walks the now-reversed list so every node is freed.

