fn longest_common_prefix(words: &[String]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = words[0].as_bytes();
    let mut end = first.len();
    for word in &words[1..] {
        let bytes = word.as_bytes();
        let mut i = 0;
        while i < end && i < bytes.len() && first[i] == bytes[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            return String::new();
        }
    }
    String::from_utf8(first[..end].to_vec()).unwrap()
}

fn main() {
    let cases: Vec<Vec<String>> = vec![
        vec!["flower".into(), "flow".into(), "flight".into()],
        vec!["dog".into(), "racecar".into()],
        vec![],
        vec!["single".into()],
    ];
    for case in &cases {
        println!("{:?} -> {:?}", case, longest_common_prefix(case));
    }
}
```

Comparing bytes works because all common prefixes of UTF-8 strings are themselves valid edge-aligned strings, so slicing at a byte boundary that all strings share is safe. `end` only ever shrinks, giving O(total length) time. The empty slice and single-string cases are handled up front.

```rust
use std::collections::HashMap;

fn fib_memo(n: u64, cache: &mut HashMap<u64, u128>) -> u128 {
    if let Some(&v) = cache.get(&n) {
        return v;
    }
    let v = if n < 2 {
        n as u128
    } else {
        fib_memo(n - 1, cache) + fib_memo(n - 2, cache)
    };
    cache.insert(n, v);
    v
}

fn main() {
    let mut cache = HashMap::new();
    for n in [0, 1, 2, 10, 50] {
        println!("fib({n}) = {}", fib_memo(n, &mut cache));
    }
    let mut fresh = HashMap::new();
    println!("fib(90) = {}", fib_memo(90, &mut fresh));
}
```

A `HashMap<u64, u128>` memo turns the exponential recursion into linear work: each `n` is computed once and read back in O(1). `u128` holds fib(90) comfortably without overflow. `n < 2` is the base case, so fib(0) is 0 and fib(1) is 1.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least recently used


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    print(c.get("a"))       # 1, marks 'a' recent
    c.put("c", 3)           # evicts 'b'
    print(c.get("b"))       # None
    print(c.get("c"))       # 3
```

`OrderedDict` keeps insertion order and gives O(1) `move_to_end` and `popitem`. Reads and updates call `move_to_end` to refresh recency; an insert past capacity drops the front, which is the least recently used entry. A non-positive capacity fails loudly instead of silently never storing anything.

