bool is_balanced(const std::string& s) {
    std::stack<char> open;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                open.push(c);
                break;
            case ')': case ']': case '}': {
                if (open.empty()) return false;
                char top = open.top();
                open.pop();
                if ((c == ')' && top != '(') ||
                    (c == ']' && top != '[') ||
                    (c == '}' && top != '{')) {
                    return false;
                }
                break;
            }
            default:
                break;  // ignore non-bracket characters
        }
    }
    return open.empty();
}

int main() {
    std::string tests[] = {"()[]{}", "([{}])", "(]", "((", "){", "a(b)c"};
    for (const auto& t : tests) {
        std::cout << '"' << t << "\" -> " << (is_balanced(t) ? "balanced" : "unbalanced") << '\n';
    }
    return 0;
}
```

Opening brackets are pushed; a closing bracket must match the stack top or the string fails immediately. The final `open.empty()` catches unmatched openers like `((`. Non-bracket characters are skipped, so ordinary text passes through as balanced.

```python
def kth_largest(nums, k):
    if not nums:
        raise ValueError("nums must not be empty")
    if k < 1 or k > len(nums):
        raise ValueError(f"k must be between 1 and {len(nums)}")
    pivot = nums[0]
    greater = [x for x in nums[1:] if x > pivot]
    equal = [x for x in nums[1:] if x == pivot]
    less = [x for x in nums[1:] if x < pivot]
    if k <= len(greater):
        return kth_largest(greater, k)
    if k <= len(greater) + len(equal) + 1:
        return pivot
    return kth_largest(less, k - len(greater) - len(equal) - 1)

if __name__ == "__main__":
    data = [3, 1, 4, 1, 5, 9, 2, 6]
    assert kth_largest(data, 1) == 9
    assert kth_largest(data, 3) == 5
    assert kth_largest([7], 1) == 7
    for k in range(1, len(data) + 1):
        assert kth_largest(data, k) == sorted(data, reverse=True)[k - 1]
    try:
        kth_largest([], 1)
        raise AssertionError("expected ValueError")
    except ValueError:
        pass
    print("ok")
