```cpp
#include <cstddef>
#include <iostream>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), size_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(int value) {
        std::size_t tail = (head_ + size_) % buf_.size();
        buf_[tail] = value;
        if (size_ == buf_.size()) {
            head_ = (head_ + 1) % buf_.size();
        } else {
            ++size_;
        }
    }

    bool pop(int& out) {
        if (size_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return buf_.size(); }

private:
    std::vector<int> buf_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    for (int i = 1; i <= 5; ++i) rb.push(i);
    int v;
    std::vector<int> got;
    while (rb.pop(v)) got.push_back(v);
    // Overwrote 1 and 2, so output is 3 4 5
    for (int x : got) std::cout << x << ' ';
    std::cout << "\n";
    return 0;
}
