```cpp
#include <iostream>
#include <string>

std::string to_binary(const std::string& decimal) {
    if (decimal.empty()) throw std::invalid_argument("empty input");
    for (char c : decimal)
        if (c < '0' || c > '9') throw std::invalid_argument("non-digit in input");

    // Repeated division of the decimal string by 2.
    std::string cur = decimal;
    std::string bits;
    bool all_zero = false;
    while (!all_zero) {
        all_zero = true;
        int carry = 0;
        std::string next;
        for (char c : cur) {
            int value = carry * 10 + (c - '0');
            int digit = value / 2;
            carry = value % 2;
            if (digit != 0 || !next.empty()) next.push_back(char('0' + digit));
            if (digit != 0) all_zero = false;
        }
        bits.push_back(char('0' + carry));
        cur = next.empty() ? "0" : next;
    }
    std::reverse(bits.begin(), bits.end());
    return bits.empty() ? "0" : bits;
}

int main() {
    std::cout << to_binary("0") << "\n";        // 0
    std::cout << to_binary("10") << "\n";       // 1010
    std::cout << to_binary("255") << "\n";      // 11111111
    try {
        to_binary("12x");
    } catch (const std::invalid_argument& e) {
        std::cout << "error: " << e.what() << "\n";
    }
    return 0;
}
```
