#include <cstddef>
#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

std::uint32_t crc32(const std::uint8_t* data, std::size_t length) {
    std::uint32_t crc = 0xFFFFFFFFu;
    for (std::size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; ++bit) {
            if (crc & 1u) {
                crc = (crc >> 1) ^ 0xEDB88320u;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc ^ 0xFFFFFFFFu;
}

std::uint32_t crc32(const std::string& text) {
    return crc32(reinterpret_cast<const std::uint8_t*>(text.data()), text.size());
}

int main() {
    // Empty input has CRC 0, matching the usual preconditioned definition.
    if (crc32("") != 0u) {
        std::cerr << "empty input check failed\n";
        return 1;
    }
    const std::string check = "123456789";
    std::cout << std::hex << crc32(check) << "\n";  // cbf43926 for the IEEE CRC-32
    return 0;
}
```

This is the reflected CRC-32 used by zlib/PNG: init `0xFFFFFFFF`, LSB-first shifting with the reversed polynomial `0xEDB88320`, final XOR. The canonical check value is `0xCBF43926` for `"123456789"`, which the program prints as verification. A tiny bitwise loop is used over a 256-entry table for clarity; swap in a table for bulk throughput.

