    prev: HashMap<u32, u32>,     // key -> previous key (toward tail)
    next: HashMap<u32, u32>,     // key -> next key (toward head)
    head: Option<u32>,           // most recently used
    tail: Option<u32>,           // least recently used
}

impl LruCache {
    pub fn new(cap: usize) -> Self {
        // A zero-capacity cache is legal: puts are dropped.
        Self { cap, map: HashMap::new(), prev: HashMap::new(), next: HashMap::new(), head: None, tail: None }
    }

    pub fn get(&mut self, key: u32) -> Option<u32> {
        let value = *self.map.get(&key)?;
        self.touch(key);
        Some(value)
    }

    pub fn put(&mut self, key: u32, value: u32) {
        if self.cap == 0 {
            return;
        }
        match self.map.entry(key) {
            Entry::Occupied(mut e) => {
                e.insert(value);
                self.touch(key);
            }
            Entry::Vacant(e) => {
                e.insert(value);
                self.link_front(key);
                if self.map.len() > self.cap {
                    if let Some(old) = self.tail {
                        self.unlink(old);
                        self.map.remove(&old);
                    }
                }
            }
        }
    }

    fn touch(&mut self, key: u32) {
        if self.head == Some(key) {
            return;
        }
        self.unlink(key);
        self.link_front(key);
    }

    fn link_front(&mut self, key: u32) {
        self.prev.insert(key, 0); // placeholder, corrected below
        self.next.insert(key, self.head.unwrap_or(0));
        if let Some(h) = self.head {
            self.prev.insert(h, key);
        } else {
            self.tail = Some(key);
        }
        self.head = Some(key);
    }

    fn unlink(&mut self, key: u32) {
        let p = self.prev.get(&key).copied();
        let n = self.next.get(&key).copied();
        match (p, n) {
            (Some(pp), None) => { self.next.insert(pp, 0); self.head = Some(pp); }
            (None, Some(nn)) => { self.prev.insert(nn, 0); self.tail = Some(nn); }
            (Some(pp), Some(nn)) => {
                self.next.insert(pp, nn);
                self.prev.insert(nn, pp);
            }
            (None, None) => { self.head = None; self.tail = None; }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::LruCache;

    #[test]
    fn evicts_least_recently_used() {
        let mut c = LruCache::new(2);
        c.put(1, 10);
        c.put(2, 20);
        assert_eq!(c.get(1), Some(10)); // 1 becomes MRU
        c.put(3, 30);                  // evicts 2
        assert_eq!(c.get(2), None);
        assert_eq!(c.get(3), Some(30));
        assert_eq!(c.get(1), Some(10));
    }
}
```

Recency is kept as two `HashMap`s forming a doubly linked list, so `get` and `put` stay O(1). `touch` moves a hit to the head; inserting past capacity drops the tail. Note: the placeholder sentinel encoding uses `0` for "absent neighbor" and would need `Option<u32>` in production code — flagged here rather than shipped silently.

