def two_largest(nums: List[float]) -> Optional[Tuple[float, float]]:
    """Return (largest, second_largest) distinct values, or None if < 2 distinct."""
    if not nums:
        return None
    first: Optional[float] = None
    second: Optional[float] = None
    for n in nums:
        if not isinstance(n, (int, float)):
            raise TypeError(f"non-numeric value: {n!r}")
        if first is None or n > first:
            second = first
            first = n
        elif n != first and (second is None or n > second):
            second = n
    if second is None:
        return None
    return (first, second)


