```cpp
#include <cstdint>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int64_t> low;                              // max-heap
    std::priority_queue<int64_t, std::vector<int64_t>, std::greater<int64_t>> high;  // min-heap

    int64_t x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);

        // Rebalance: low may exceed high by at most 1.
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        if (low.size() == high.size()) {
            std::cout << (static_cast<double>(low.top()) + high.top()) / 2.0 << '\n';
        } else {
            std::cout << static_cast<double>(low.top()) << '\n';
        }
    }
    return 0;
}
```

The max-heap `low` holds the smaller half and the min-heap `high` the larger half. After every insertion the sizes differ by at most one, so the median is either the top of `low` or the average of both tops. Input ends at EOF; an empty stream produces no output.

