```c
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

static char closing_for(char open) {
    switch (open) {
        case '(': return ')';
        case '[': return ']';
        case '{': return '}';
        default:  return '\0';
    }
}

bool is_balanced(const char *s) {
    char stack[1024];
    int top = -1;
    char quote = 0;

    for (size_t i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (quote != 0) {
            if (c == '\\' && s[i + 1] != '\0') { i++; continue; }
            if (c == quote) quote = 0;
            continue;
        }
        if (c == '\'' || c == '"') { quote = c; continue; }
        if (c == '(' || c == '[' || c == '{') {
            if (top >= 1023) return false;
            stack[++top] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top < 0 || closing_for(stack[top]) != c) return false;
            top--;
        }
    }
    return top == -1 && quote == 0;
}

int main(void) {
    const char *tests[] = {
        "(a[b]{c})",
        "([)]",
        "'(' \"{\" )",
        "(\"a\\\"b\")",
        NULL,
    };
    for (int i = 0; tests[i] != NULL; i++) {
        printf("%s -> %s\n", tests[i], is_balanced(tests[i]) ? "balanced" : "unbalanced");
    }
    return 0;
}
```

The stack holds unmatched openers; any mismatch or premature closer returns `false`. The `quote` state machine skips everything inside quotes and honours backslash escapes, so `'('` is not counted. A final non-empty stack or an unterminated quote also fails.

```rust
fn merge_intervals(mut intervals: Vec<(i64, i64)>) -> Vec<(i64, i64)> {
    if intervals.is_empty() {
        return Vec::new();
    }
    intervals.sort_by_key(|&(start, _)| start);

    let mut merged: Vec<(i64, i64)> = Vec::with_capacity(intervals.len());
    merged.push(intervals[0]);

    for &(start, end) in &intervals[1..] {
        let last = merged.last_mut().unwrap();
        if start <= last.1 {
            last.1 = last.1.max(end);   // overlap or touching
        } else {
            merged.push((start, end));
        }
    }
    merged
}

fn main() {
    assert_eq!(merge_intervals(vec![]), Vec::<(i64, i64)>::new());
    assert_eq!(merge_intervals(vec![(1, 3), (2, 6), (8, 10)]), vec![(1, 6), (8, 10)]);
    // Touching endpoints (1,3) and (3,5) merge because start <= last.end.
    assert_eq!(merge_intervals(vec![(1, 3), (3, 5)]), vec![(1, 5)]);
    // Contained interval does not shrink the outer one.
    assert_eq!(merge_intervals(vec![(1, 10), (2, 3)]), vec![(1, 10)]);
    // Degenerate empty-length interval.
    assert_eq!(merge_intervals(vec![(4, 4), (4, 4)]), vec![(4, 4)]);
    println!("{:?}", merge_intervals(vec![(5, 7), (1, 2), (2, 4)]));
}
```

Sorting by start makes a single pass sufficient. The merge condition is `start <= last.1`, so intervals that merely touch merge; the `max` on the end keeps the widest extent when one interval nests inside another. Empty input returns an empty vector without sorting.

```cpp
#include <algorithm>
#include <iostream>
#include <vector>

template <typename T>
void rotate_left(std::vector<T>& v, std::size_t k) {
    const std::size_t n = v.size();
    if (n == 0) return;
    k %= n;                       // k >= n collapses to a no-op
    if (k == 0) return;

    std::reverse(v.begin(), v.begin() + static_cast<std::ptrdiff_t>(k));
    std::reverse(v.begin() + static_cast<std::ptrdiff_t>(k), v.end());
    std::reverse(v.begin(), v.end());
}

int main() {
    std::vector<int> a{1, 2, 3, 4, 5};
    rotate_left(a, 2);
    for (int x : a) std::cout << x << ' ';   // 3 4 5 1 2
    std::cout << '\n';

    rotate_left(a, 5);                        // full cycle -> unchanged
    rotate_left(a, 7);                        // equivalent to k = 2
    for (int x : a) std::cout << x << ' ';
    std::cout << '\n';

    std::vector<int> empty;
    rotate_left(empty, 3);                    // must not crash
    rotate_left(a, 0);
    return 0;
}
```

Reversing the first `k`, then the rest, then the whole vector rotates left by `k` while touching each element a constant number of times. `k %= n` normalises out-of-range shifts and the `n == 0` / `k == 0` guards avoid undefined pointer arithmetic on empty ranges.

