/* Returns the maximum value. If n == 0, returns INT_MIN. */
int max_int(const int *a, size_t n) {
    if (a == NULL || n == 0) {
        return INT_MIN;
    }
    int m = a[0];
    for (size_t i = 1; i < n; i++) {
        if (a[i] > m) {
            m = a[i];
        }
    }
    return m;
