```python
import os
import sys
import time


def watch(path: str, max_events: int = 5, interval: float = 1.0) -> None:
    try:
        last = os.stat(path)
    except FileNotFoundError:
        print(f"no such file: {path}", file=sys.stderr)
        return

    events = 0
    last_stamp = (last.st_mtime, last.st_size)
    try:
        while events < max_events:
            time.sleep(interval)
            try:
                st = os.stat(path)
            except FileNotFoundError:
                print(f"{path} was deleted")
                return
            stamp = (st.st_mtime, st.st_size)
            if stamp != last_stamp:
                events += 1
                print(f"change #{events} at {time.strftime('%H:%M:%S')} size={st.st_size}")
                last_stamp = stamp
    except KeyboardInterrupt:
        print("\nstopped by user")


if __name__ == "__main__":
    watch(sys.argv[1] if len(sys.argv) > 1 else "watched.txt")
```

Comparing the `(mtime, size)` tuple catches edits that change either. Polling is portable but not instant; for filesystems that expose inotify you'd use `watchdog` instead. Deleting the file ends the loop cleanly.

