        while (true) {
            skip_spaces();
            if (pos_ < input_.size() && (input_[pos_] == '+' || input_[pos_] == '-')) {
                char op = input_[pos_++];
                double rhs = term();
                value = (op == '+') ? value + rhs : value - rhs;
            } else {
                return value;
            }
        }
    }

    double term() {
        double value = factor();
        while (true) {
            skip_spaces();
            if (pos_ < input_.size() && (input_[pos_] == '*' || input_[pos_] == '/')) {
                char op = input_[pos_++];
                double rhs = factor();
                if (op == '/' && rhs == 0.0) throw std::runtime_error("division by zero");
                value = (op == '*') ? value * rhs : value / rhs;
            } else {
                return value;
            }
        }
    }

    double factor() {
        skip_spaces();
        if (pos_ >= input_.size()) throw std::runtime_error("unexpected end of input");
        if (input_[pos_] == '(') {
            ++pos_;
            double value = expression();
            skip_spaces();
            if (pos_ >= input_.size() || input_[pos_] != ')')
                throw std::runtime_error("missing closing parenthesis");
            ++pos_;
            return value;
        }
        if (input_[pos_] == '-') {
            ++pos_;
            return -factor();
        }
        std::size_t start = pos_;
        while (pos_ < input_.size() && (std::isdigit(static_cast<unsigned char>(input_[pos_])) || input_[pos_] == '.')) {
            ++pos_;
        }
        if (start == pos_) throw std::runtime_error("expected number");
        return std::stod(input_.substr(start, pos_ - start));
    }

    void skip_spaces() {
        while (pos_ < input_.size() && std::isspace(static_cast<unsigned char>(input_[pos_]))) ++pos_;
    }

    std::string input_;
    std::size_t pos_;
};

int main() {
    for (const std::string& expr : {"1+2*3", "(1+2)*3", "10/(2+3)", "-4+2", "2*"}) {
        try {
            std::cout << expr << " = " << Parser(expr).parse() << '\n';
        } catch (const std::exception& e) {
            std::cout << expr << " -> error: " << e.what() << '\n';
        }
    }
}
```

The grammar layers `expression -> term -> factor`, which gives `*` and `/` higher precedence than `+` and `-` without a precedence table. Unary minus is handled in `factor`. Malformed input throws rather than returning garbage.

