use std::collections::HashMap;

/// Parses `key=value;key2=value2` into a map.
/// Later duplicates win; entries without a non-empty key or `=` are skipped.
fn parse_config(line: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();
    for entry in line.split(';') {
        let entry = entry.trim();
        if entry.is_empty() {
            continue;
        }
        let Some((key, value)) = entry.split_once('=') else {
            eprintln!("skipping entry without '=': {entry:?}");
            continue;
        };
        let key = key.trim();
        if key.is_empty() {
            eprintln!("skipping entry with empty key: {entry:?}");
            continue;
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    map
}

fn main() {
    let line = "host = localhost; port=8080;;broken;=novalue;host=127.0.0.1";
    let config = parse_config(line);
    let mut keys: Vec<_> = config.keys().cloned().collect();
    keys.sort();
    for key in keys {
        println!("{key} => {}", config[&key]);
    }
}
```

Empty segments are ignored, malformed segments are reported to stderr, and a duplicate key overwrites the earlier value (`host` ends up `127.0.0.1`). `split_once("=")` keeps values that themselves contain `=`. Keys are sorted only for deterministic demo output.

