```python
import hashlib
import os
from collections import defaultdict


def file_hash(path, chunk=1 << 16):
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        while True:
            block = fh.read(chunk)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def find_duplicates(root):
    by_size = defaultdict(list)
    for dirpath, _, filenames in os.walk(root):
        for name in filenames:
            path = os.path.join(dirpath, name)
            if os.path.islink(path) or not os.path.isfile(path):
                continue
            try:
                by_size[os.path.getsize(path)].append(path)
            except OSError:
                continue

    duplicates = defaultdict(list)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue
        for path in paths:
            try:
                duplicates[file_hash(path)].append(path)
            except OSError:
                continue
    return {h: p for h, p in duplicates.items() if len(p) > 1}


if __name__ == "__main__":
    for digest, paths in find_duplicates(".").items():
        print(digest[:12], *paths, sep="\n  ")
```

Grouping by size first avoids hashing everything, since files of different sizes cannot be identical. Symlinks are skipped to prevent loops, unreadable files are caught per entry instead of aborting the run, and streaming SHA-256 keeps memory flat for large files.

```cpp
#include <cstddef>
#include <optional>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : buf_(capacity), cap_(capacity) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be > 0");
        }
    }

    void push(double value) {
        buf_[head_] = value;
        head_ = (head_ + 1) % cap_;
        if (size_ < cap_) {
            ++size_;
        } else {
            tail_ = (tail_ + 1) % cap_;  // oldest overwritten
        }
    }

    std::optional<double> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        double value = buf_[tail_];
        tail_ = (tail_ + 1) % cap_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<double> buf_;
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};
```

`push` always writes at `head_`; once the buffer is full, advancing `tail_` discards the oldest slot, which is the overwrite semantics. `pop` returns `std::optional` so an empty buffer is a value, not an exception. All indices use modulo `cap_`, and a zero capacity is rejected at construction.

