fn longest_run(data: &[u8]) -> usize {
    if data.is_empty() {
        return 0;
    }
    let mut best = 1usize;
    let mut current = 1usize;
    for window in data.windows(2) {
        if window[0] == window[1] {
            current += 1;
            if current > best {
                best = current;
            }
        } else {
            current = 1;
        }
    }
    best
}

