def chunked(items, size):
    """Yield lists of at most `size` items, last group may be shorter."""
    if size <= 0:
        raise ValueError("size must be positive")
    it = iter(items)
    while True:
        group = []
        for _ in range(size):
            try:
                group.append(next(it))
            except StopIteration:
                break
        if not group:
            return
        yield group


