```cpp
#include <cstddef>
#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), size_(0) {}

    bool push(int value) {
        if (size_ == data_.size()) return false;
        data_[(head_ + size_) % data_.size()] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % data_.size();
        --size_;
        return value;
    }

    bool is_empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    std::vector<int> data_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    std::cout << (rb.push(1) && rb.push(2) && rb.push(3)) << '\n'; // 1
    std::cout << rb.push(4) << '\n';                               // 0 (full)
    std::cout << *rb.pop() << '\n';                               // 1
    rb.push(4);
    while (!rb.is_empty()) std::cout << *rb.pop() << ' ';         // 2 3 4
    std::cout << '\n';
}
```

`data_` is sized once at construction, so pushing past capacity returns false rather than reallocating. Indexing is modulo capacity, which wraps correctly because `head_ + size_` stays below `2 * capacity`.

