template <typename T>
std::vector<T> running_max(const std::vector<T>& v) {
    std::vector<T> out;
    if (v.empty()) return out;
    out.reserve(v.size());
    T best = v[0];
    out.push_back(best);
    for (std::size_t i = 1; i < v.size(); ++i) {
        if (v[i] > best) best = v[i];
        out.push_back(best);
    }
    return out;
}

int main() {
