    assert((a == std::vector<int>{3, 3, 4, 4, 5}));

    auto b = running_max(std::vector<double>{-1.5, -2.0, -0.5});
    assert((b == std::vector<double>{-1.5, -1.5, -0.5}));

    auto e = running_max(std::vector<int>{});
    assert(e.empty());

    std::cout << "ok\n";
    return 0;
}
