```rust
fn merge_sorted<T: Ord + Copy>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn interleaves() {
        assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    }

    #[test]
    fn handles_empty() {
        assert_eq!(merge_sorted(&[] as &[i32], &[7]), vec![7]);
        assert_eq!(merge_sorted(&[7], &[] as &[i32]), vec![7]);
        assert_eq!(merge_sorted(&[] as &[i32], &[] as &[i32]), Vec::<i32>::new());
    }
}
```

The merge loop advances whichever side has the smaller head; the trailing `extend_from_slice` calls drain the leftover run in one shot. `Ord + Copy` keeps the comparisons cheap and avoids borrow gymnastics.

