```c
#include <stdbool.h>
#include <stdio.h>

#define RB_CAP 4

typedef struct {
    int data[RB_CAP];
    size_t head;   /* next read */
    size_t len;
} ring_t;

void ring_init(ring_t *r) { r->head = 0; r->len = 0; }

bool ring_push(ring_t *r, int value) {
    if (r->len == RB_CAP) return false;  /* full */
    size_t tail = (r->head + r->len) % RB_CAP;
    r->data[tail] = value;
    r->len++;
    return true;
}

bool ring_pop(ring_t *r, int *out) {
    if (r->len == 0) return false;  /* empty */
    *out = r->data[r->head];
    r->head = (r->head + 1) % RB_CAP;
    r->len--;
    return true;
}

int main(void) {
    ring_t r;
    ring_init(&r);
    int v;

    if (ring_pop(&r, &v)) return 1;          /* pop on empty must fail */

    for (int i = 1; i <= RB_CAP; i++)
        if (!ring_push(&r, i)) return 1;
    if (ring_push(&r, 99)) return 1;         /* push on full must fail */

    for (int i = 1; i <= RB_CAP; i++) {
        if (!ring_pop(&r, &v) || v != i) return 1;
    }
    printf("ok\n");
    return 0;
}
```
`head` indexes the oldest item; `len` disambiguates full from empty without wasting a slot. Both operations are O(1), and the module-of-index wrapping keeps the array fixed. `main` returns nonzero if any boundary case misbehaves.

