pub struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self {
        Stack { items: Vec::new() }
    }

    pub fn push(&mut self, value: T) {
        self.items.push(value);
    }

    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    pub fn peek(&self) -> Option<&T> {
        self.items.last()
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }

    pub fn iter(&self) -> impl DoubleEndedIterator<Item = &T> {
        self.items.iter().rev()
    }
}

impl<T> Default for Stack<T> {
    fn default() -> Self {
        Self::new()
    }
}

fn main() {
    let mut s: Stack<i32> = Stack::new();
    assert!(s.pop().is_none());
    assert!(s.is_empty());

    s.push(1);
    s.push(2);
    s.push(3);
    assert_eq!(s.len(), 3);
    assert_eq!(s.peek(), Some(&3));

    let seen: Vec<i32> = s.iter().copied().collect();
    assert_eq!(seen, vec![3, 2, 1]);

    assert_eq!(s.pop(), Some(3));
    assert_eq!(s.pop(), Some(2));
    assert_eq!(s.pop(), Some(1));
    assert_eq!(s.pop(), None);

    println!("ok");
}
```
`iter` yields top-to-bottom using `Vec::iter().rev()`, so it composes with `DoubleEndedIterator`. `pop` on empty returns `None`, and `Default` allows `Stack::default()`.

```cpp
#include <cassert>
#include <iostream>
#include <vector>

// Returns index of first element >= value (lower_bound semantics).
template <typename T>
std::size_t lower_bound_index(const std::vector<T>& v, const T& value) {
    std::size_t lo = 0, hi = v.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;  // avoids overflow on large sizes
        if (v[mid] < value)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;  // == v.size() when value is greater than all elements
}

int main() {
    std::vector<int> empty;
    assert(lower_bound_index(empty, 5) == 0);

    std::vector<int> v{1, 3, 3, 7, 9};
    assert(lower_bound_index(v, 0) == 0);
    assert(lower_bound_index(v, 3) == 1);   // first of the duplicates
    assert(lower_bound_index(v, 4) == 3);   // absent -> insertion point
    assert(lower_bound_index(v, 10) == 5);  // past the end
    assert(lower_bound_index(v, 9) == 4);

    std::cout << "ok\n";
    return 0;
}
```
The loop invariant is `lo <= answer <= hi`. `mid = lo + (hi - lo) / 2` never overflows. On empty input it returns 0, and for a value larger than every element it returns `size()`, the valid insertion point.

