#include <cstdint>
#include <iostream>
#include <limits>
#include <optional>
#include <string>

std::optional<int> parse_int(const std::string& s) {
    if (s.empty()) return std::nullopt;
    std::size_t i = 0;
    bool negative = false;
    if (s[i] == '+' || s[i] == '-') {
        negative = (s[i] == '-');
        ++i;
    }
    if (i == s.size()) return std::nullopt;
    long long acc = 0;
    for (; i < s.size(); ++i) {
        char c = s[i];
        if (c < '0' || c > '9') return std::nullopt;
        acc = acc * 10 + (c - '0');
        if (acc > static_cast<long long>(std::numeric_limits<int>::max()) + 1)
            return std::nullopt;
    }
    if (negative) acc = -acc;
    if (acc < std::numeric_limits<int>::min() || acc > std::numeric_limits<int>::max())
        return std::nullopt;
    return static_cast<int>(acc);
}

int main() {
    std::cout << (parse_int("42").value_or(-1)) << '\n';
    std::cout << (parse_int("-7").value_or(-1)) << '\n';
    std::cout << (parse_int("").has_value() ? 1 : 0) << '\n';
    std::cout << (parse_int("12x").has_value() ? 1 : 0) << '\n';
    std::cout << (parse_int("999999999999").has_value() ? 1 : 0) << '\n';
    return 0;
}
```

The accumulator is `long long` so the multiply never overflows before the bound check. `INT_MIN` is the tricky case: its absolute value exceeds `INT_MAX`, so the guard uses `max + 1` before negating, then range-checks the sign-adjusted value.

```cpp
#include <condition_variable>
#include <cstddef>
#include <mutex>
#include <optional>
#include <queue>
#include <thread>
#include <vector>
#include <iostream>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    void push(T value) {
        std::unique_lock<std::mutex> lock(m_);
        not_full_.wait(lock, [this] { return q_.size() < cap_ || closed_; });
        if (closed_) return;
        q_.push(std::move(value));
        not_empty_.notify_one();
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(m_);
        not_empty_.wait(lock, [this] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;
        T v = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lock(m_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<T> q_;
    std::mutex m_;
    std::condition_variable not_empty_, not_full_;
    bool closed_ = false;
};

int main() {
    BoundedQueue<int> q(4);
    std::vector<std::thread> workers;
    for (int w = 0; w < 3; ++w)
        workers.emplace_back([&q, w] {
            for (int i = 0; i < 5; ++i) q.push(w * 5 + i);
        });
    int sum = 0;
    for (int i = 0; i < 15; ++i)
        if (auto v = q.pop()) sum += *v;
    for (auto& t : workers) t.join();
    q.close();
    std::cout << sum << '\n';
    return 0;
}
```

Each waiter uses a predicate lambda, so it re-checks the condition after every wakeup instead of trusting a single notification. `close()` sets a flag and notifies both conditions, which lets blocked producers and consumers exit rather than hang.

```rust
use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum ParseError {
    Empty,
    BadNumber,
    UnknownUnit(char),
}

pub fn parse_duration(input: &str) -> Result<u64, ParseError> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err(ParseError::Empty);
    }
    let multipliers: HashMap<char, u64> =
        [('h', 3600), ('m', 60), ('s', 1)].iter().cloned().collect();

    let mut total: u64 = 0;
    let mut digits = String::new();
    for c in trimmed.chars() {
        if c.is_ascii_digit() {
            digits.push(c);
        } else {
            if digits.is_empty() {
                return Err(ParseError::BadNumber);
            }
            let value: u64 = digits.parse().map_err(|_| ParseError::BadNumber)?;
            let unit = multipliers.get(&c).ok_or(ParseError::UnknownUnit(c))?;
            total = total
                .checked_add(value.checked_mul(*unit).ok_or(ParseError::BadNumber)?)
                .ok_or(ParseError::BadNumber)?;
            digits.clear();
        }
    }
    if !digits.is_empty() {
        return Err(ParseError::BadNumber);
    }
    Ok(total)
}

fn main() {
    assert_eq!(parse_duration("1h30m"), Ok(5400));
    assert_eq!(parse_duration("45s"), Ok(45));
    assert_eq!(parse_duration("2h"), Ok(7200));
    assert_eq!(parse_duration(" 10m "), Ok(600));
    assert_eq!(parse_duration(""), Err(ParseError::Empty));
    assert_eq!(parse_duration("1x"), Err(ParseError::UnknownUnit('x')));
    assert_eq!(parse_duration("h"), Err(ParseError::BadNumber));
    assert_eq!(parse_duration("5"), Err(ParseError::BadNumber));
    println!("ok");
}
```

Units accumulate left to right, so compound forms like `1h30m` sum correctly. `checked_mul`/`checked_add` mean huge inputs return an error instead of wrapping in release mode. A trailing bare number without a unit is rejected rather than guessed.

```rust
use std::collections::{HashMap, VecDeque};
use std::hash::Hash;

pub struct LruCache<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: Eq + Hash + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        Self { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    fn touch(&mut self, key: &K) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            self.order.remove(pos);
        }
        self.order.push_back(key.clone());
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        if self.map.contains_key(key) {
            self.touch(key);
            self.map.get(key)
        } else {
            None
        }
    }

    pub fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            self.map.insert(key.clone(), value);
            self.touch(&key);
            return;
        }
        if self.map.len() == self.cap {
            if let Some(oldest) = self.order.pop_front() {
                self.map.remove(&oldest);
            }
        }
        self.map.insert(key.clone(), value);
        self.order.push_back(key);
    }
}

fn main() {
    let mut cache = LruCache::new(2);
    cache.put("a", 1);
    cache.put("b", 2);
    assert_eq!(cache.get(&"a"), Some(&1));
    cache.put("c", 3); // evicts "b"
    assert_eq!(cache.get(&"b"), None);
    assert_eq!(cache.get(&"a"), Some(&1));
    assert_eq!(cache.get(&"c"), Some(&3));
    println!("ok");
}
```

The deque front is the least-recently-used key and the back is the most recent. `touch` removes then re-pushes, so a `get` hit also promotes the key. Tests use capacity 2 with three distinct keys to force an eviction and confirm the evicted one is the least recent.

```c
#include <stdio.h>
#include <string.h>
#include <stddef.h>

/* Returns the byte length of the UTF-8 sequence starting at s[0], 0 if invalid. */
static size_t utf8_len(unsigned char c) {
    if (c < 0x80) return 1;
    if ((c & 0xE0) == 0xC0) return 2;
    if ((c & 0xF0) == 0xE0) return 3;
    if ((c & 0xF8) == 0xF0) return 4;
    return 0;
}

/* Reverses codepoints in place. Returns 0 on success, -1 on invalid UTF-8. */
int utf8_reverse(char *s) {
    size_t n = strlen(s);
    size_t i = 0;
    /* Record each codepoint's (start, length) by walking forward. */
    size_t starts[256];
    size_t lens[256];
    size_t count = 0;
    while (i < n) {
        size_t len = utf8_len((unsigned char)s[i]);
        if (len == 0 || i + len > n) return -1;
        if (count >= 256) return -1;
        starts[count] = i;
        lens[count] = len;
        count++;
        i += len;
    }
    char out[1024];
    if (n >= sizeof(out)) return -1;
    size_t w = 0;
    for (size_t k = count; k-- > 0;) {
        memcpy(out + w, s + starts[k], lens[k]);
        w += lens[k];
    }
    memcpy(s, out, n);
    s[n] = '\0';
    return 0;
}

int main(void) {
    char a[] = "hello";
    utf8_reverse(a);
    printf("%s\n", a);

