    assert merged == {"a": 1, "b": {"x": 1, "y": 9, "z": 3}, "c": 4}
    assert left == {"a": 1, "b": {"x": 1, "y": 2}}
    assert right == {"b": {"y": 9, "z": 3}, "c": 4}
    print("ok")
