bool is_palindrome(const std::string& text) {
    std::size_t left = 0;
    std::size_t right = text.size();
    while (left < right) {
        unsigned char a = static_cast<unsigned char>(text[left]);
        unsigned char b = static_cast<unsigned char>(text[right - 1]);
        if (!std::isalnum(a)) { ++left; continue; }
        if (!std::isalnum(b)) { --right; continue; }
        if (std::tolower(a) != std::tolower(b)) return false;
        ++left;
        --right;
    }
    return true;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_palindrome("A man, a plan, a canal: Panama") << "\n";
    std::cout << is_palindrome("") << "\n";
    std::cout << is_palindrome("!!!") << "\n";
    std::cout << is_palindrome("hello") << "\n";
}
