#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int val;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int v) {
    Node *n = malloc(sizeof(Node));
    if (!n) return head;
    n->val = v;
    n->next = head;
    return n;
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; ++i) head = push(head, i);
    head = reverse(head);
    for (Node *c = head; c; c = c->next) printf("%d ", c->val);
    printf("\n");

    while (head) {
        Node *n = head->next;
        free(head);
        head = n;
    }
    return 0;
}
