```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
    std::array<T, N> buf{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
    bool overflowed_ = false;

public:
    bool push(const T& v) {
        if (count_ == N) {
            overflowed_ = true;
            return false;
        }
        buf[(head_ + count_) % N] = v;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T v = buf[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return v;
    }

    bool overflowed() const { return overflowed_; }
    std::size_t size() const { return count_; }
};

int main() {
    RingBuffer<int, 3> r;
    std::cout << r.push(1) << r.push(2) << r.push(3) << r.push(4) << '\n';
    std::cout << r.overflowed() << ' ' << r.size() << '\n';
    while (auto v = r.pop()) std::cout << *v << ' ';
    std::cout << "\n";
}
```
push returns false and sets the overflow flag when the buffer is full; pop returns nullopt when empty.

