#include <array>
#include <cstddef>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity ? new double[capacity] : nullptr),
          cap_(capacity), head_(0), count_(0) {}

    RingBuffer(const RingBuffer&) = delete;
    RingBuffer& operator=(const RingBuffer&) = delete;

    ~RingBuffer() { delete[] data_; }

    bool push(double v) {
        if (count_ == cap_) return false;
        data_[(head_ + count_) % cap_] = v;
        ++count_;
        return true;
    }

    std::optional<double> pop() {
        if (count_ == 0) return std::nullopt;
        double v = data_[head_];
        head_ = (head_ + 1) % cap_;
        --count_;
        return v;
    }

    std::size_t size() const { return count_; }
    std::size_t capacity() const { return cap_; }
    bool empty() const { return count_ == 0; }

private:
    double* data_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t count_;
};

