#include <iostream>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

typedef std::pair<std::string, std::string> Entry;
typedef std::vector<std::string> Errors;

static void parse(const std::string& line, std::vector<Entry>& out, Errors& errors) {
    std::stringstream ss(line);
    std::string token;
    while (std::getline(ss, token, ';')) {
        std::string trimmed = token;
        trimmed.erase(0, trimmed.find_first_not_of(" \t"));
        trimmed.erase(trimmed.find_last_not_of(" \t") + 1);
        if (trimmed.empty()) continue;
        std::size_t eq = trimmed.find('=');
        if (eq == std::string::npos || eq == 0 || eq + 1 == trimmed.size()) {
            errors.push_back(trimmed);
            continue;
        }
        out.push_back(Entry(trimmed.substr(0, eq), trimmed.substr(eq + 1)));
    }
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::vector<Entry> entries;
        Errors errors;
        parse(line, entries, errors);
        for (std::size_t i = 0; i < entries.size(); ++i)
            std::cout << "[" << entries[i].first << "]=" << entries[i].second << '\n';
        for (std::size_t i = 0; i < errors.size(); ++i)
            std::cout << "!bad: " << errors[i] << '\n';
    }
    return 0;
}
```

