use std::collections::BinaryHeap;
use std::cmp::Reverse;
use std::io::{self, BufRead};

fn main() {
    let mut lower: BinaryHeap<i64> = BinaryHeap::new(); // max-heap
    let mut upper: BinaryHeap<Reverse<i64>> = BinaryHeap::new(); // min-heap
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        for tok in line.split_whitespace() {
            let x: i64 = match tok.parse() {
                Ok(v) => v,
                Err(_) => continue,
            };
            lower.push(x);
            if let (Some(&lo), Some(&Reverse(up))) = (lower.peek(), upper.peek()) {
                if lo > up {
                    let v = lower.pop().unwrap();
                    upper.push(Reverse(v));
                }
            }
            if lower.len() > upper.len() + 1 {
                let v = lower.pop().unwrap();
                upper.push(Reverse(v));
            } else if upper.len() > lower.len() {
                let Reverse(v) = upper.pop().unwrap();
                lower.push(v);
            }
            if lower.len() == upper.len() {
                let a = *lower.peek().unwrap() as f64;
                let Reverse(b) = *upper.peek().unwrap();
                println!("{:.1}", (a + b as f64) / 2.0);
            } else {
                println!("{:.1}", *lower.peek().unwrap() as f64);
            }
        }
    }
}
