class StackFull(Exception):
    pass

class StackEmpty(Exception):
    pass

class BoundedStack:
    def __init__(self, max_size):
        if max_size < 1:
            raise ValueError("max_size must be at least 1")
        self._data = []
        self._max = max_size

    def push(self, item):
        if len(self._data) >= self._max:
            raise StackFull(f"stack holds {self._max} items")
        self._data.append(item)

    def pop(self):
        if not self._data:
            raise StackEmpty("pop from empty stack")
        return self._data.pop()

    def peek(self):
        if not self._data:
            raise StackEmpty("peek on empty stack")
        return self._data[-1]

    def __len__(self):
        return len(self._data)

    def __iter__(self):
        return iter(reversed(self._data))

if __name__ == "__main__":
    s = BoundedStack(2)
    s.push(1); s.push(2)
    assert list(s) == [2, 1]
    try:
        s.push(3)
    except StackFull as e:
        assert str(e) == "stack holds 2 items"
