#include <iostream>

struct Node {
    int value;
    Node* next;
    Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void print(Node* head) {
    bool first = true;
    for (Node* n = head; n != nullptr; n = n->next) {
        if (!first) std::cout << ' ';
        std::cout << n->value;
        first = false;
    }
    std::cout << '\n';
}

