    Node* tail = nullptr;
    for (int v : {1, 2, 3, 4, 5}) {
        Node* n = new Node(v);
        if (tail) tail->next = n; else head = n;
        tail = n;
    }
    print(reverse(head));

    // empty list stays empty
    print(reverse(nullptr));

    while (head) {
        Node* next = head->next;
        delete head;
        head = next;
    }
