#include <cctype>
#include <iostream>
#include <stack>
#include <string>
#include <stdexcept>

int evaluate(const std::string& s) {
    std::stack<long long> nums;
    std::stack<char> ops;
    auto apply = [&]() {
        long long b = nums.top(); nums.pop();
        long long a = nums.top(); nums.pop();
        char op = ops.top(); ops.pop();
        switch (op) {
            case '+': nums.push(a + b); break;
            case '-': nums.push(a - b); break;
            case '*': nums.push(a * b); break;
            case '/':
                if (b == 0) throw std::runtime_error("division by zero");
                nums.push(a / b); break;
        }
    };
    int precedence = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (std::isdigit(static_cast<unsigned char>(c))) {
            long long v = 0;
            while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
                v = v * 10 + (s[i] - '0');
                ++i;
            }
            --i;
            nums.push(v);
        } else if (c == '+' || c == '-' || c == '*' || c == '/') {
            int prec = (c == '*' || c == '/') ? 2 : 1;
            while (!ops.empty() && ((ops.top() == '*' || ops.top() == '/') ? 2 : 1) >= prec) {
                apply();
            }
            ops.push(c);
        }
    }
    while (!ops.empty()) apply();
    return static_cast<int>(nums.top());
}

int main() {
    std::cout << evaluate("3+4*2") << "\n";   // 11
    std::cout << evaluate("10-2-3") << "\n";  // 5
    std::cout << evaluate("8/2+3") << "\n";   // 7
    return 0;
}
