def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring of s."""
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)          # odd length
        l2, r2 = expand(i, i + 1)      # even length
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end + 1]


if __name__ == "__main__":
    for text, expected in [("babad", "bab"), ("cbbd", "bb"), ("", ""), ("a", "a"), ("abcda", "a")]:
        got = longest_palindrome(text)
        print(repr(text), "->", repr(got), "OK" if got == expected else f"FAIL expected {expected!r}")
```

Odd palindromes are grown from a single centre, even ones from a pair of centres. The `start`/`end` pair tracks the best window seen so far, so a single linear scan over centres yields O(n²) time and O(1) extra space.

