```python
class Parser:
    def __init__(self, text: str):
        self.tokens = self._tokenize(text)
        self.pos = 0

    @staticmethod
    def _tokenize(text: str):
        tokens = []
        i = 0
        while i < len(text):
            ch = text[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit() or ch == '.':
                j = i
                while j < len(text) and (text[j].isdigit() or text[j] == '.'):
                    j += 1
                tokens.append(float(text[i:j]))
                i = j
            elif ch in "+-*/()":
                tokens.append(ch)
                i += 1
            else:
                raise ValueError(f"unexpected character {ch!r}")
        return tokens

    def parse(self) -> float:
        value = self._expr()
        if self.pos != len(self.tokens):
            raise ValueError("trailing tokens")
        return value

    def _expr(self) -> float:
        value = self._term()
        while self.pos < len(self.tokens) and self.tokens[self.pos] in "+-":
            op = self.tokens[self.pos]
            self.pos += 1
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def _term(self) -> float:
        value = self._factor()
        while self.pos < len(self.tokens) and self.tokens[self.pos] in "*/":
            op = self.tokens[self.pos]
            self.pos += 1
            rhs = self._factor()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value /= rhs
        return value

    def _factor(self) -> float:
        if self.pos >= len(self.tokens):
            raise ValueError("unexpected end of input")
        tok = self.tokens[self.pos]
        if tok == "(":
            self.pos += 1
            value = self._expr()
            if self.pos >= len(self.tokens) or self.tokens[self.pos] != ")":
                raise ValueError("missing closing parenthesis")
            self.pos += 1
            return value
        if tok == "-":
            self.pos += 1
            return -self._factor()
        if isinstance(tok, float):
            self.pos += 1
            return tok
        raise ValueError(f"unexpected token {tok!r}")


def evaluate(text: str) -> float:
    return Parser(text).parse()


if __name__ == "__main__":
    print(evaluate("1 + 2 * (3 - 4)"))          # -1.0
    print(evaluate("-3.5 / 0.5"))               # -7.0
    for bad in ["1 +", "(1 + 2", "1 @ 2"]:
        try:
            evaluate(bad)
        except ValueError as e:
            print("rejected:", bad, "->", e)
```

Precedence comes from the grammar: `_expr` handles `+`/`-`, `_term` handles `*`/`/`, and `_factor` handles numbers, parentheses and unary minus. Every error path raises `ValueError` with a message naming the offending token.

