#include <stdio.h>
#include <string.h>

void reverse(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    for (size_t i = 0; i < len / 2; i++) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
}

int main(void) {
    char buf[] = "hello, world";
    char empty[] = "";

    reverse(buf);
    reverse(empty);

    printf("%s\n", buf);
    printf("[%s]\n", empty);
    return 0;
}
```

The swap loop stops before the midpoint, so for an even or odd length every pair is exchanged exactly once. `char buf[]` is a mutable array, not a string literal, so in-place writes are legal; the empty case swaps zero pairs and stays a valid empty string.

