        line[--n] = '\0';
    }
    if (n == 0) {
        return 0;
    }
    reverse(line, line + n - 1);
    char *word = line;
    for (char *p = line; ; ++p) {
        if (*p == ' ' || *p == '\0') {
            reverse(word, p - 1);
            if (*p == '\0') {
                break;
            }
            word = p + 1;
        }
    }
