template <typename T, std::size_t N>
class RingBuffer {
public:
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }
    std::size_t size() const { return count_; }

    bool push(const T& value) {
        if (full()) {
            return false;
        }
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) {
            return std::nullopt;
        }
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

#include <cassert>
#include <iostream>

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.empty());
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.full() && !rb.push(4));
    assert(rb.pop() == 1);
    assert(rb.push(4));
    assert(rb.pop() == 2 && rb.pop() == 3 && rb.pop() == 4);
    assert(!rb.pop().has_value());
    std::cout << "all tests passed\n";
}
