#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : capacity_(capacity), buf_{} {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool full() const { return size_ == capacity_; }
    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

    bool push(int value) {
        if (full()) return false;
        buf_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

private:
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
    std::array<int, 64> buf_;  // capacity_ <= 64
};
```

`push` returns false instead of throwing when full, and `pop` returns `std::nullopt` on empty, so the caller distinguishes "no data" from real errors. The backing array is fixed at 64; raise the bound or switch to `std::vector<int>` if you need arbitrary capacity.

