fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for ch in s.chars() {
        match ch {
            '(' | '[' | '{' => stack.push(ch),
            ')' | ']' | '}' => {
                let want = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(want) {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    assert!(is_balanced(""));
    assert!(is_balanced("()[]{}"));
    assert!(is_balanced("a(b[c]{d})e"));
    assert!(!is_balanced("(]"));
    assert!(!is_balanced("(()"));
    assert!(!is_balanced(")("));
    println!("ok");
}
