bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;
    bool neg = (*s == '-');
    if (*s == '-' || *s == '+') ++s;
    if (*s == '\0') return false;

    long acc = 0;
    for (; *s; ++s) {
        if (*s < '0' || *s > '9') return false;
        acc = acc * 10 + (*s - '0');
        if (neg ? -acc < INT_MIN : acc > INT_MAX) return false;
    }
    *out = neg ? (int)-acc : (int)acc;
    return true;
}

int main(void) {
    int v;
    if (!parse_int("-42", &v) || v != -42) return 1;
    if (!parse_int("2147483647", &v) || v != INT_MAX) return 1;
    if (parse_int("2147483648", &v)) return 1;   /* overflow */
    if (parse_int("12x", &v)) return 1;         /* bad char */
    if (parse_int("", &v)) return 1;            /* empty */
    printf("ok\n");
    return 0;
}
