std::uint64_t fib(unsigned n) {
    if (n == 0) return 0;
    if (n == 1) return 1;
    static std::unordered_map<unsigned, std::uint64_t> memo{{0, 0}, {1, 1}};
    auto it = memo.find(n);
    if (it != memo.end()) return it->second;
    std::uint64_t value = fib(n - 1) + fib(n - 2);
    memo.emplace(n, value);
    return value;
}

