def median(values):
    """Return the median of a sequence of numbers, or None if empty."""
    n = len(values)
    if n == 0:
        return None
    vals = list(values)
    target = (n - 1) // 2
    # Quickselect partition around a pivot without a full sort.
    lo, hi = 0, n - 1
    while lo < hi:
        pivot = vals[(lo + hi) // 2]
        i, j = lo, hi
        while i <= j:
            while vals[i] < pivot:
                i += 1
            while vals[j] > pivot:
                j -= 1
            if i <= j:
                vals[i], vals[j] = vals[j], vals[i]
                i += 1
                j -= 1
        if target <= j:
            hi = j
        elif target >= i:
            lo = i
        else:
            break
    if n % 2 == 1:
        return float(vals[target])
    # Even length: need the element just above the lower middle too.
    upper = target + 1
    lower_val = vals[target]
    upper_val = min(v for v in vals if v >= lower_val)
    return (lower_val + upper_val) / 2.0


if __name__ == "__main__":
    print(median([]))              # None
    print(median([3, 1, 2]))       # 2.0
    print(median([4, 1, 3, 2]))    # 2.5
    print(median([-5, -1, -3]))    # -3.0
