import time


def retry(operation, attempts=5, base_delay=0.5, factor=2.0, sleep=time.sleep):
    """Call operation() up to `attempts` times with exponential backoff.

    Re-raises the last exception once attempts are exhausted.
    """
    if attempts < 1:
        raise ValueError("attempts must be >= 1")
    delay = base_delay
    last_error = None
    for attempt in range(1, attempts + 1):
        try:
            return operation()
        except Exception as exc:  # noqa: BLE001 - caller decides what to retry
            last_error = exc
            if attempt == attempts:
                break
            sleep(delay)
            delay *= factor
    raise last_error


if __name__ == "__main__":
    calls = {"n": 0}

    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise RuntimeError(f"transient failure {calls['n']}")
        return "ok"

    print(retry(flaky, sleep=lambda s: None))
