#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
    std::array<int, N> buf_{};
    std::size_t head_ = 0;  // read index
    std::size_t size_ = 0;

public:
    // Push always succeeds; if full, the oldest element is dropped.
    void push(int value) {
        static_assert(N > 0, "ring buffer must hold at least one element");
        std::size_t tail = (head_ + size_) % N;
        buf_[tail] = value;
        if (size_ == N) {
            head_ = (head_ + 1) % N;  // evict oldest
        } else {
            ++size_;
        }
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
};

int main() {
    RingBuffer<3> rb;
    for (int i = 1; i <= 4; ++i) rb.push(i * 10);
    // 10 was overwritten; expect 20, 30, 40
    while (auto v = rb.pop()) std::cout << *v << '\n';
    std::cout << "empty=" << rb.empty() << '\n';
    return 0;
}
```
`push` on a full buffer advances `head_` to evict the oldest, keeping `size_` at capacity. All indices are taken modulo `N`, so no bounds arithmetic escapes the array.

