    std::map<std::string, std::string> out;
    std::string_view rest{line};
    while (!rest.empty()) {
        auto pos = rest.find(';');
        std::string_view pair = (pos == std::string_view::npos) ? rest : rest.substr(0, pos);
        rest = (pos == std::string_view::npos) ? std::string_view{} : rest.substr(pos + 1);
        auto eq = pair.find('=');
        if (eq == std::string_view::npos) continue;  // malformed, skip
        auto key = trim(pair.substr(0, eq));
        auto val = trim(pair.substr(eq + 1));
        if (key.empty()) continue;
        out.emplace(std::string(key), std::string(val));
    }
    return out;
