```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    best_start, best_len = 0, 1

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - left - 1

    for i in range(len(s)):
        start, length = expand(i, i)
        if length > best_len:
            best_start, best_len = start, length

        start, length = expand(i, i + 1)
        if length > best_len:
            best_start, best_len = start, length

    return s[best_start:best_start + best_len]


if __name__ == "__main__":
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "abacaba"]
    for text in cases:
        print(repr(text), "->", repr(longest_palindrome(text)))
```

`expand` grows outward while characters match, so each centre costs at most O(n). Trying all 2n-1 centres gives O(n^2) time and O(1) extra space. Empty input and single characters are handled without special-casing the loop.

```cpp
#include <iostream>
#include <vector>

static void merge(std::vector<int>& a, std::vector<int>& buf, int lo, int mid, int hi) {
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        // <= keeps equal elements from the left half first: stable
        if (a[i] <= a[j]) buf[k++] = a[i++];
        else              buf[k++] = a[j++];
    }
    while (i < mid) buf[k++] = a[i++];
    while (j < hi)  buf[k++] = a[j++];
    for (int t = lo; t < hi; ++t) a[t] = buf[t];
}

static void msort(std::vector<int>& a, std::vector<int>& buf, int lo, int hi) {
    if (hi - lo < 2) return;
    int mid = lo + (hi - lo) / 2;
    msort(a, buf, lo, mid);
    msort(a, buf, mid, hi);
    merge(a, buf, lo, mid, hi);
}

void merge_sort(std::vector<int>& a) {
    std::vector<int> buf(a.size());
    if (!a.empty()) msort(a, buf, 0, static_cast<int>(a.size()));
}

int main() {
    std::vector<std::vector<int>> tests = {
        {5, 2, 9, 2, 5, 1},
        {},
        {7},
        {3, 3, 3},
        {10, -1, 0, -1, 10}
    };
    for (auto& v : tests) {
        merge_sort(v);
        for (size_t i = 0; i < v.size(); ++i)
            std::cout << v[i] << (i + 1 < v.size() ? ' ' : '\n');
        if (v.empty()) std::cout << "\n";
    }
    return 0;
}
```

The `<=` comparison on the merge step puts the left run first on ties, which is what makes the sort stable. An empty vector skips the recursion entirely; a single element exits on the `hi - lo < 2` base case.

