import re

EMAIL_RE = re.compile(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$")


def normalize(raw: str):
    """Return (normalized, None) or (None, reason)."""
    if not isinstance(raw, str):
        return None, "not a string"
    addr = raw.strip().lower()
    if addr == "":
        return None, "empty"
    if addr.count("@") != 1:
        return None, "must contain exactly one @"
    local, _, domain = addr.partition("@")
    if local == "" or len(local) > 64:
        return None, "local part length out of range"
    if len(addr) > 254:
        return None, "address too long"
    if not EMAIL_RE.match(addr):
        return None, "syntax invalid"
    if domain.startswith("-") or domain.endswith("-") or ".." in domain:
        return None, "malformed domain"
    return addr, None


def main():
    candidates = [
        "  Alice@Example.COM ",
        "bob@sub.domain.org",
        "not-an-email",
        "double@@x.com",
        "",
        "a@b",
        "a..b@example.com",
        "ok.tag+spam@mail.co",
    ]
    valid, invalid = [], []
    for c in candidates:
        norm, reason = normalize(c)
        if norm is None:
            invalid.append((c, reason))
        else:
            valid.append(norm)

    print("valid:")
    for v in valid:
        print(" ", v)
    print("invalid:")
    for raw, reason in invalid:
        print(" ", repr(raw), "->", reason)


if __name__ == "__main__":
    main()
```

`partition("@")` splits on the only `@` that passed the count check. The regex handles the shape; the extra checks catch length limits, empty local parts, and domains with leading/trailing hyphens or doubled dots. Every rejection returns a reason instead of a bare False, so the report is actionable.

```cpp
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), size_(0), full_(false) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(double v) {
        buf_[tail_] = v;
        tail_ = (tail_ + 1) % buf_.size();
        if (full_) {
            head_ = tail_;          // overwrite oldest: advance head too
        } else {
            ++size_;
            if (tail_ == head_) full_ = true;
        }
    }

    bool empty() const { return size_ == 0 && !full_; }
    std::size_t size() const { return size_; }

    double oldest() const {
        if (empty()) throw std::out_of_range("empty");
        return buf_[head_];
    }

    double newest() const {
        if (empty()) throw std::out_of_range("empty");
        std::size_t idx = (tail_ + buf_.size() - 1) % buf_.size();
        return buf_[idx];
    }

private:
    std::vector<double> buf_;
    std::size_t head_, tail_, size_;
    bool full_;
};

int main() {
    RingBuffer rb(3);
    for (double v : {1.0, 2.0, 3.0}) rb.push(v);
    std::cout << "oldest=" << rb.oldest() << " newest=" << rb.newest() << " size=" << rb.size() << '\n';
    rb.push(4.0);            // evicts 1.0
    std::cout << "oldest=" << rb.oldest() << " newest=" << rb.newest() << '\n';
    rb.push(5.0); rb.push(6.0);
    std::cout << "oldest=" << rb.oldest() << " newest=" << rb.newest() << '\n';
    return 0;
}
```

A separate `full_` flag distinguishes an empty buffer from a full one, since both have `head_ == tail_`. When full, `push` advances `head_` alongside `tail_`, which drops the oldest element without any shifting.

