fn sieve(limit: usize) -> Vec<usize> {
    if limit < 2 {
        return Vec::new();
    }
    let mut is_prime = vec![true; limit + 1];
    is_prime[0] = false;
    is_prime[1] = false;

    let mut p = 2;
    while p * p <= limit {
        if is_prime[p] {
            let mut multiple = p * p;
            while multiple <= limit {
                is_prime[multiple] = false;
                multiple += p;
            }
        }
        p += 1;
    }

    is_prime
        .iter()
        .enumerate()
        .filter_map(|(n, &prime)| if prime { Some(n) } else { None })
        .collect()
}

fn main() {
    for limit in [0usize, 1, 2, 30, 100] {
        let primes = sieve(limit);
        let tail: Vec<usize> = primes.iter().rev().take(5).rev().copied().collect();
        println!("limit={limit:>3} count={:<4} last5={:?}", primes.len(), tail);
    }
}
