Marking composites starts at `p * p` because every smaller multiple was already crossed out by a smaller prime. The `p * p <= limit` bound avoids needless passes. `limit < 2` returns an empty vector, so the zero and one cases work without indexing past the array.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least recently used

    def __contains__(self, key) -> bool:
        return key in self._data

    def __len__(self) -> int:
        return len(self._data)


def main():
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1            # "a" now most recent
    cache.put("c", 3)                     # evicts "b"
    assert cache.get("b") is None
    assert list(cache._data.keys()) == ["a", "c"]
    cache.put("a", 10)                    # update existing
    assert cache.get("a") == 10
    assert len(cache) == 2
    print("all LRU checks passed")


if __name__ == "__main__":
    main()
```

`OrderedDict.move_to_end` marks a key as most recently used in O(1). On insert, `popitem(last=False)` removes the front, which is the least recently used entry. Re-putting an existing key updates the value and refreshes its recency instead of duplicating it.

