void rotateRight(std::vector<int>& a, long long k) {
    int n = static_cast<int>(a.size());
    if (n <= 1) return;
    k %= n;
    if (k < 0) k += n;
    if (k == 0) return;
    std::reverse(a.begin(), a.end());
    std::reverse(a.begin(), a.begin() + k);
    std::reverse(a.begin() + k, a.end());
