template <typename T>
T gcd(T a, T b) {
    static_assert(std::is_integral_v<T>, "gcd requires an integer type");
    auto absv = [](T v) { return v < 0 ? static_cast<T>(-v) : v; };
    a = absv(a);
    b = absv(b);
    while (b != 0) {
        T t = a % b;
        a = b;
        b = t;
    }
    return a;
}

