#include <stdio.h>

char *reverse_in_place(char *s) {
    if (s == NULL) {
        return NULL;
    }
    size_t len = 0;
    while (s[len] != '\0') {
        len++;
    }
    if (len < 2) {
        return s;
    }
    size_t i = 0;
    size_t j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
    return s;
}

