```python
class MinHeap:
    def __init__(self):
        self._data = []

    def __len__(self):
        return len(self._data)

    def peek(self):
        if not self._data:
            raise IndexError("peek from empty heap")
        return self._data[0]

    def push(self, value):
        self._data.append(value)
        self._sift_up(len(self._data) - 1)

    def pop(self):
        if not self._data:
            raise IndexError("pop from empty heap")
        smallest = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            self._sift_down(0)
        return smallest

    def _sift_up(self, i):
        while i > 0:
            parent = (i - 1) // 2
            if self._data[parent] <= self._data[i]:
                break
            self._data[parent], self._data[i] = self._data[i], self._data[parent]
            i = parent

    def _sift_down(self, i):
        n = len(self._data)
        while True:
            left = 2 * i + 1
            right = left + 1
            smallest = i
            if left < n and self._data[left] < self._data[smallest]:
                smallest = left
            if right < n and self._data[right] < self._data[smallest]:
                smallest = right
            if smallest == i:
                break
            self._data[i], self._data[smallest] = self._data[smallest], self._data[i]
            i = smallest


if __name__ == "__main__":
    import random
    heap = MinHeap()
    values = [5, 3, 8, 1, 9, 2, 7, random.randint(0, 100) for _ in range(20)]
    for v in values:
        heap.push(v)
    out = [heap.pop() for _ in range(len(heap))] if False else []
    out = []
    while len(heap):
        out.append(heap.pop())
    assert out == sorted(values), (out, sorted(values))
    try:
        MinHeap().pop()
    except IndexError as e:
        print("caught:", e)
    print("ok")
