```rust
fn lis(seq: &[i32]) -> Vec<i32> {
    if seq.is_empty() {
        return Vec::new();
    }
    let mut tails: Vec<usize> = Vec::new(); // indices into seq
    let mut prev = vec![usize::MAX; seq.len()];

    for i in 0..seq.len() {
        let pos = tails.partition_point(|&t| seq[t] < seq[i]);
        prev[i] = if pos == 0 { usize::MAX } else { tails[pos - 1] };
        if pos == tails.len() {
            tails.push(i);
        } else {
            tails[pos] = i;
        }
    }

    let mut out = Vec::new();
    let mut cur = *tails.last().unwrap();
    while cur != usize::MAX {
        out.push(seq[cur]);
        cur = prev[cur];
    }
    out.reverse();
    out
}

fn main() {
    let r = lis(&[10, 9, 2, 5, 3, 7, 101, 18]);
    assert_eq!(r.len(), 4);
    assert_eq!(r, vec![2, 3, 7, 18]);
    assert_eq!(lis(&[]).len(), 0);
    assert_eq!(lis(&[7, 7, 7]).len(), 1);
    println!("{:?}", lis(&[1, 2, 3]));
}
```

`partition_point` on a strictly-increasing `tails` keeps duplicates out, so equal values never extend the subsequence.

