typedef enum { OK = 0, BAD_CHAR = 1, OVERFLOW = 2, NO_DIGITS = 3 } ParseErr;

ParseErr parse_u64(const char *s, unsigned long long *out) {
    unsigned long long v = 0;
    int any = 0;
    for (; *s; s++) {
        if (*s < '0' || *s > '9') return BAD_CHAR;
        unsigned digit = (unsigned)(*s - '0');
        if (v > (ULLONG_MAX - digit) / 10) return OVERFLOW;
        v = v * 10 + digit;
        any = 1;
    }
    if (!any) return NO_DIGITS;
    *out = v;
    return OK;
}

