    if (parse_u64("18446744073709551615", &v) != OK || v != ULLONG_MAX) return 1;
    if (parse_u64("18446744073709551616", &v) != OVERFLOW) return 2;
    if (parse_u64("12a", &v) != BAD_CHAR) return 3;
