```cpp
#include <cctype>
#include <iostream>
#include <stdexcept>
#include <string>

class Parser {
    const std::string &s;
    std::size_t i = 0;

    void skip() { while (i < s.size() && std::isspace((unsigned char)s[i])) ++i; }

    double expr() {
        double v = term();
        for (;;) {
            skip();
            if (i < s.size() && (s[i] == '+' || s[i] == '-')) {
                char op = s[i++];
                double r = term();
                v = (op == '+') ? v + r : v - r;
            } else return v;
        }
    }

    double term() {
        double v = factor();
        for (;;) {
            skip();
            if (i < s.size() && (s[i] == '*' || s[i] == '/')) {
                char op = s[i++];
                double r = factor();
                if (op == '*') v *= r;
                else {
                    if (r == 0.0) throw std::runtime_error("division by zero");
                    v /= r;
                }
            } else return v;
        }
    }

    double factor() {
        skip();
        if (i < s.size() && s[i] == '(') {
            ++i;
            double v = expr();
            skip();
            if (i >= s.size() || s[i] != ')') throw std::runtime_error("missing )");
            ++i;
            return v;
        }
        if (i < s.size() && s[i] == '-') { ++i; return -factor(); }
        std::size_t start = i;
        while (i < s.size() && (std::isdigit((unsigned char)s[i]) || s[i] == '.')) ++i;
        if (start == i) throw std::runtime_error("expected number");
        return std::stod(s.substr(start, i - start));
    }

public:
    explicit Parser(const std::string &str) : s(str) {}
    double run() {
        double v = expr();
        skip();
        if (i != s.size()) throw std::runtime_error("trailing input");
        return v;
    }
};

int main() {
    Parser p("2 * (3 + 4.5) - 8 / 2");
    std::cout << p.run() << "\n"; // 11
    return 0;
}
```

`expr`→`term`→`factor` gives correct precedence once recursion makes parentheses and unary minus primary-level.

