```rust
use std::collections::VecDeque;

#[derive(Debug)]
struct Node {
    value: i32,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
}

fn level_order(root: &Option<Box<Node>>) -> Vec<Vec<i32>> {
    let mut out = Vec::new();
    let mut queue: VecDeque<&Node> = VecDeque::new();
    if let Some(n) = root {
        queue.push_back(n);
    }
    while !queue.is_empty() {
        let width = queue.len();
        let mut level = Vec::with_capacity(width);
        for _ in 0..width {
            let node = queue.pop_front().unwrap();
            level.push(node.value);
            if let Some(l) = &node.left {
                queue.push_back(l);
            }
            if let Some(r) = &node.right {
                queue.push_back(r);
            }
        }
        out.push(level);
    }
    out
}

fn leaf(value: i32) -> Option<Box<Node>> {
    Some(Box::new(Node { value, left: None, right: None }))
}

fn main() {
    let root = Some(Box::new(Node {
        value: 1,
        left: Some(Box::new(Node { value: 2, left: leaf(4), right: None })),
        right: Some(Box::new(Node { value: 3, left: None, right: leaf(5) })),
    }));
    assert_eq!(level_order(&root), vec![vec![1], vec![2, 3], vec![4, 5]]);
    assert!(level_order(&None).is_empty());
    println!("ok");
}
