Handles integers, `+ - * /`, unary minus, and parentheses; raises on malformed input.

```python
class Parser:
    def __init__(self, text):
        self.tokens = self._tokenize(text)
        self.pos = 0

    @staticmethod
    def _tokenize(text):
        tokens = []
        i = 0
        while i < len(text):
            c = text[i]
            if c.isspace():
                i += 1
            elif c.isdigit():
                j = i
                while j < len(text) and text[j].isdigit():
                    j += 1
                tokens.append(("num", int(text[i:j])))
                i = j
            elif c in "+-*/()":
                tokens.append((c, c))
                i += 1
            else:
                raise ValueError(f"unexpected character: {c!r}")
        return tokens

    def _peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else ("eof", None)

    def _advance(self):
        tok = self._peek()
        self.pos += 1
        return tok

    def parse(self):
        value = self._expr()
        if self._peek()[0] != "eof":
            raise ValueError("trailing input")
        return value

    def _expr(self):
        value = self._term()
        while self._peek()[0] in ("+", "-"):
            op = self._advance()[0]
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def _term(self):
        value = self._factor()
        while self._peek()[0] in ("*", "/"):
            op = self._advance()[0]
            rhs = self._factor()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value /= rhs
        return value

    def _factor(self):
        kind, val = self._advance()
        if kind == "num":
            return val
        if kind == "-":
            return -self._factor()
        if kind == "(":
            value = self._expr()
            if self._advance()[0] != ")":
                raise ValueError("missing closing parenthesis")
            return value
        raise ValueError(f"unexpected token: {kind}")


def evaluate(text):
    return Parser(text).parse()


if __name__ == "__main__":
    assert evaluate("1 + 2 * 3") == 7
    assert evaluate("(1 + 2) * 3") == 9
    assert evaluate("-(3 - 5)") == 2
    assert evaluate("10 / 4") == 2.5
    print("ok")
```

