class FileHandle {
public:
    explicit FileHandle(const std::string& path, const char* mode = "rb") {
        if (fp_ = std::fopen(path.c_str(), mode); !fp_) {
            throw std::runtime_error("failed to open: " + path);
        }
    }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fp_(std::exchange(other.fp_, nullptr)) {}

    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            close();
            fp_ = std::exchange(other.fp_, nullptr);
        }
        return *this;
    }

    ~FileHandle() { close(); }

    FILE* get() const { return fp_; }

private:
    void close() {
        if (fp_) {
            std::fclose(fp_);
            fp_ = nullptr;
        }
    }

    FILE* fp_ = nullptr;
};

int main() {
    FileHandle f("/etc/hostname");
    char buf[128];
    if (std::fgets(buf, sizeof buf, f.get())) {
        std::printf("%s", buf);
    }
    // f closes itself here; moving it transfers ownership.
    FileHandle g = std::move(f);
    return 0;
}
