```cpp
#include <iostream>
#include <vector>

static void merge(std::vector<int>& a, int lo, int mid, int hi) {
    std::vector<int> left(a.begin() + lo, a.begin() + mid);
    std::vector<int> right(a.begin() + mid, a.begin() + hi);
    int i = 0, j = 0, k = lo;
    while (i < (int)left.size() && j < (int)right.size()) {
        a[k++] = (left[i] <= right[j]) ? left[i++] : right[j++];
    }
    while (i < (int)left.size())  a[k++] = left[i++];
    while (j < (int)right.size()) a[k++] = right[j++];
}

static void mergeSort(std::vector<int>& a, int lo, int hi) {
    if (hi - lo <= 1) return;
    int mid = lo + (hi - lo) / 2;
    mergeSort(a, lo, mid);
    mergeSort(a, mid, hi);
    merge(a, lo, mid, hi);
}

static void mergeSort(std::vector<int>& a) {
    mergeSort(a, 0, (int)a.size());
}

int main() {
    std::vector<std::vector<int>> cases = {
        {}, {1}, {2, 1}, {5, 4, 3, 2, 1}, {1, 1, 2, 0, -3, 2}
    };
    for (auto v : cases) {
        mergeSort(v);
        for (size_t i = 1; i < v.size(); ++i)
            if (v[i - 1] > v[i]) { std::cerr << "sort failed\n"; return 1; }
    }
    std::cout << "ok\n";
}
```

Uses half-open ranges `[lo, hi)` so empty and single-element inputs fall out of the base case. `left[i] <= right[j]` keeps the sort stable. Time O(n log n), extra space O(n) for the temporary vectors.

