class Fd {
public:
    Fd() noexcept : fd_(-1) {}
    explicit Fd(int fd) noexcept : fd_(fd) {}

    ~Fd() { close(); }

    Fd(const Fd&) = delete;
    Fd& operator=(const Fd&) = delete;

    Fd(Fd&& other) noexcept : fd_(other.fd_) { other.fd_ = -1; }

    Fd& operator=(Fd&& other) noexcept {
        if (this != &other) {
            close();
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    int get() const noexcept { return fd_; }
    bool valid() const noexcept { return fd_ >= 0; }

    int release() noexcept { int f = fd_; fd_ = -1; return f; }

    void close() noexcept {
        if (fd_ >= 0) {
            while (::close(fd_) == -1 && errno == EINTR) {}
            fd_ = -1;
        }
    }

private:
    int fd_;
};

int main() {
    Fd f(::open("/dev/null", O_RDONLY));
    if (!f.valid()) { std::cerr << "open failed\n"; return 1; }
    Fd g = std::move(f);
    if (f.valid() || !g.valid()) { std::cerr << "move broken\n"; return 1; }
    std::cout << "ok\n";
}
```

Copying is deleted, moving nulls out the source, and the destructor closes only a valid descriptor. `close()` retries on `EINTR`, and `release()` hands ownership to the caller for APIs that take their own ownership.

```rust
#[derive(Debug, PartialEq)]
enum Token {
    Num(f64),
    Plus,
    Minus,
    Star,
    Slash,
    LParen,
    RParen,
}

fn tokenize(input: &str) -> Result<Vec<Token>, String> {
    let mut tokens = Vec::new();
    let mut chars = input.chars().peekable();
    while let Some(&c) = chars.peek() {
        match c {
            ' ' | '\t' => { chars.next(); }
            '+' => { tokens.push(Token::Plus); chars.next(); }
            '-' => { tokens.push(Token::Minus); chars.next(); }
            '*' => { tokens.push(Token::Star); chars.next(); }
            '/' => { tokens.push(Token::Slash); chars.next(); }
            '(' => { tokens.push(Token::LParen); chars.next(); }
            ')' => { tokens.push(Token::RParen); chars.next(); }
            '0'..='9' | '.' => {
                let mut num = String::new();
                while let Some(&d) = chars.peek() {
                    if d.is_ascii_digit() || d == '.' { num.push(d); chars.next(); } else { break; }
                }
                tokens.push(Token::Num(num.parse::<f64>().map_err(|e| e.to_string())?));
            }
            _ => return Err(format!("unexpected character {c:?}")),
        }
    }
    Ok(tokens)
}

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

impl Parser {
    fn peek(&self) -> Option<&Token> { self.tokens.get(self.pos) }
    fn bump(&mut self) -> Option<Token> {
        let t = self.tokens.get(self.pos).cloned();
        if t.is_some() { self.pos += 1; }
        t
    }

    fn expr(&mut self) -> Result<f64, String> {
        let mut value = self.term()?;
        while let Some(t) = self.peek() {
            match t {
                Token::Plus => { self.bump(); value += self.term()?; }
                Token::Minus => { self.bump(); value -= self.term()?; }
                _ => break,
            }
        }
        Ok(value)
    }

    fn term(&mut self) -> Result<f64, String> {
        let mut value = self.factor()?;
        while let Some(t) = self.peek() {
            match t {
                Token::Star => { self.bump(); value *= self.factor()?; }
                Token::Slash => {
                    self.bump();
                    let rhs = self.factor()?;
                    if rhs == 0.0 { return Err("division by zero".into()); }
                    value /= rhs;
                }
                _ => break,
            }
        }
        Ok(value)
    }

    fn factor(&mut self) -> Result<f64, String> {
        match self.bump() {
            Some(Token::Num(n)) => Ok(n),
            Some(Token::Minus) => Ok(-self.factor()?),
            Some(Token::LParen) => {
                let v = self.expr()?;
                match self.bump() {
                    Some(Token::RParen) => Ok(v),
                    _ => Err("expected closing paren".into()),
                }
            }
            other => Err(format!("unexpected token {other:?}")),
        }
    }
}

fn eval(input: &str) -> Result<f64, String> {
    let tokens = tokenize(input)?;
    let mut p = Parser { tokens, pos: 0 };
    let v = p.expr()?;
    if p.pos != p.tokens.len() { return Err("trailing input".into()); }
    Ok(v)
}

fn main() {
    assert_eq!(eval("2 + 3 * 4").unwrap(), 14.0);
    assert_eq!(eval("(2 + 3) * 4").unwrap(), 20.0);
    assert_eq!(eval("-3 + -2").unwrap(), -5.0);
    assert!(eval("1 / 0").is_err());
    assert!(eval("2 +").is_err());
    println!("ok");
}
```

`expr` handles `+`/`-`, `term` handles `*`/`/`, and `factor` handles numbers, unary minus and parentheses — the standard precedence ladder. Tokenize splits numeric literals greedily; division by zero and trailing input are reported as errors instead of silently passing.

```rust
fn longest_common_prefix(strings: &[String]) -> String {
    if strings.is_empty() {
        return String::new();
    }
    let first = &strings[0];
    let mut end = first.len();
    for s in &strings[1..] {
        let mut i = 0;
        let a = first.as_bytes();
        let b = s.as_bytes();
        while i < end && i < b.len() && a[i] == b[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            return String::new();
        }
    }
    first[..end].to_string()
}

fn main() {
    let cases: Vec<(Vec<String>, &str)> = vec![
        (vec![], ""),
        (vec!["flower".into(), "flow".into(), "flight".into()], "fl"),
        (vec!["dog".into(), "racecar".into(), "car".into()], ""),
        (vec!["".into(), "b".into()], ""),
        (vec!["café".into(), "café latte".into()], "café"),
    ];
    for (input, expected) in cases {
        let got = longest_common_prefix(&input);
        assert_eq!(got, expected, "input {input:?}");
    }
    println!("ok");
}
```

Compares bytes against the first string, shrinking `end` at each step. Because it only ever cuts at a byte boundary that all inputs share, slicing `first[..end]` stays on a UTF-8 boundary — the `café` case proves multi-byte prefixes survive. Empty input and a shared empty string both return `""`.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (n == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; ++i) head = push(head, i);

    head = reverse(head);

    int expected = 5;
    for (Node *p = head; p != NULL; p = p->next) {
        if (p->value != expected) {
            fprintf(stderr, "mismatch: got %d, want %d\n", p->value, expected);
            return 1;
        }
        --expected;
    }
    if (expected != 0) { fprintf(stderr, "list too short\n"); return 1; }

    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    puts("ok");
    return 0;
}
```

Iterative reversal with three pointers: `next` is saved before rewiring, `prev` walks backward. `reverse(NULL)` returns `NULL`, so an empty list is a no-op. The cleanup loop frees nodes after the list is re-ordered.

