```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    for text in ["babad", "cbbd", "", "a", "forgeeksskeegfor", "ab😀ba"]:
        print(repr(text), "->", repr(longest_palindrome(text)))
```

Empty input returns `""`; single characters return themselves; the Unicode sample is handled by Python's code-point indexing, so the emoji counts as one character.

