int parse_i64(const char *s, int64_t *out) {
    if (s == NULL || *s == '\0') return -1;
    errno = 0;
    char *end = NULL;
    long long v = strtoll(s, &end, 10);
    if (errno == ERANGE) return -2;          // overflow
    if (end == s || *end != '\0') return -3; // not a clean integer
    *out = (int64_t)v;
    return 0;
}

int main(void) {
    const char *tests[] = {"42", "-9223372036854775808",
                           "9223372036854775808", "12abc", "", NULL};
    for (int i = 0; tests[i] != NULL; i++) {
        int64_t val = 0;
        int rc = parse_i64(tests[i], &val);
        if (rc == 0)
            printf("ok %lld\n", (long long)val);
        else if (rc == -2)
            printf("overflow: %s\n", tests[i]);
        else
            printf("invalid: %s\n", tests[i]);
    }
    return 0;
}
