    let b = [2, 4, 6];
    let merged = merge_sorted(&a, &b);
    println!("{merged:?}");
    assert_eq!(merged, vec![1, 2, 3, 4, 5, 6, 7]);
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    println!("all assertions passed");
}
