#include <cstddef>
#include <iostream>
#include <vector>

class RingBuffer {
    std::vector<double> data_;
    std::size_t head_ = 0;   // next write position
    std::size_t count_ = 0;

public:
    explicit RingBuffer(std::size_t capacity) : data_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(double v) {
        data_[head_] = v;
        head_ = (head_ + 1) % data_.size();
        if (count_ < data_.size()) ++count_;
    }

    void print() const {
        std::size_t start = (head_ + data_.size() - count_) % data_.size();
        for (std::size_t i = 0; i < count_; ++i) {
            std::cout << data_[(start + i) % data_.size()];
            if (i + 1 < count_) std::cout << ' ';
        }
        std::cout << '\n';
    }
};

int main() {
    RingBuffer rb(3);
    rb.push(1.5);
    rb.push(2.5);
    rb.print();          // 1.5 2.5
    rb.push(3.5);
    rb.push(4.5);        // overwrites 1.5
    rb.print();          // 2.5 3.5 4.5
}
```

`head_` is the next write slot and `count_` tracks valid entries, so once the buffer fills, the oldest value is overwritten in order. `print` walks from the oldest live slot forward.

