```python
from typing import List, Optional


class RingBuffer:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._buf: List[Optional[int]] = [None] * capacity
        self._head = 0  # next write position
        self._size = 0

    def push(self, value: int) -> None:
        self._buf[self._head] = value
        self._head = (self._head + 1) % len(self._buf)
        if self._size < len(self._buf):
            self._size += 1

    def get(self, index: int) -> int:
        if index < 0 or index >= self._size:
            raise IndexError("index out of range")
        oldest = (self._head - self._size) % len(self._buf)
        return self._buf[(oldest + index) % len(self._buf)]  # type: ignore[return-value]

    @property
    def full(self) -> bool:
        return self._size == len(self._buf)

    @property
    def empty(self) -> bool:
        return self._size == 0


if __name__ == "__main__":
    rb = RingBuffer(3)
    assert rb.empty
    rb.push(1); rb.push(2); rb.push(3)
    assert rb.full and rb.get(0) == 1 and rb.get(2) == 3
    rb.push(4)  # overwrites 1
    assert rb.get(0) == 2 and rb.get(2) == 4
    print("ok")
```
`get` computes the oldest slot from `head - size`, so logical order survives wraparound. Out-of-range access raises rather than returning `None`.

