#include <sstream>
#include <string>
#include <vector>

std::vector<long long> parse_int_list(const std::string& input) {
    std::vector<long long> out;
    std::stringstream ss(input);
    std::string token;
    while (std::getline(ss, token, ',')) {
        // trim surrounding whitespace
        size_t start = 0, end = token.size();
        while (start < end && std::isspace(static_cast<unsigned char>(token[start]))) ++start;
        while (end > start && std::isspace(static_cast<unsigned char>(token[end - 1]))) --end;
        std::string trimmed = token.substr(start, end - start);
        if (trimmed.empty()) continue;

        try {
            size_t pos = 0;
            long long value = std::stoll(trimmed, &pos);
            if (pos != trimmed.size()) continue;  // trailing junk like "12x"
            out.push_back(value);
        } catch (const std::exception&) {
            // overflow or malformed -> skip
        }
    }
    return out;
}

int main() {
    auto v = parse_int_list(" 1, 2 ,bad,3,999999999999999999999, ,4 ");
    for (long long n : v) std::cout << n << " ";
    std::cout << "\n";  // prints: 1 2 3 4
}
```
Whitespace is trimmed, empty fields are skipped, and `pos != size` rejects trailing junk. `stoll` throwing on overflow is caught and the token is dropped.

