/* Returns 0 on success, -1 on invalid input, -2 on overflow. */
int fib(unsigned long long n, unsigned long long *out) {
    if (out == NULL) return -1;
    unsigned long long a = 0, b = 1;
    for (unsigned long long i = 0; i < n; ++i) {
        if (a > ULLONG_MAX - b) return -2;
        unsigned long long next = a + b;
        a = b;
        b = next;
    }
    *out = a;
    return 0;
}

int main(void) {
    unsigned long long value;
    int rc = fib(90, &value);
    if (rc == 0) {
        printf("fib(90) = %llu\n", value);
    } else if (rc == -2) {
        printf("overflow\n");
    } else {
        printf("invalid input\n");
    }
    return 0;
}
```
The loop runs n times so `fib(0)` is 0 and `fib(1)` is 1. Before each add the guard checks whether `a + b` would wrap, returning `-2` instead of silently corrupting the result.

```python
"""Run-length encoding and decoding with edge handling."""


def rle_encode(s: str) -> str:
    if not s:
        return ""
    out = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(f"{count}{prev}")
            prev = ch
            count = 1
    out.append(f"{count}{prev}")
    return "".join(out)


def rle_decode(s: str) -> str:
    out = []
    i = 0
    n = len(s)
    while i < n:
        if not s[i].isdigit():
            raise ValueError(f"expected digit at index {i}")
        j = i
        while j < n and s[j].isdigit():
            j += 1
        if j == n:
            raise ValueError("run missing character")
        count = int(s[i:j])
        if count == 0:
            raise ValueError(f"zero run length at index {i}")
        out.append(s[j] * count)
        i = j + 1
    return "".join(out)


if __name__ == "__main__":
    cases = ["aaabbbcccd", "", "abc", "a", "ééé中中"]
    for c in cases:
        enc = rle_encode(c)
        assert rle_decode(enc) == c, (c, enc)
        print(repr(c), "->", repr(enc))
