// Bounded fixed-capacity queue with wraparound indexing.
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

 template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        if (size_ == N) throw std::overflow_error("ring buffer full");
        data_[(head_ + size_) % N] = value;
        ++size_;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 4> rb;
    for (int i = 1; i <= 4; ++i) rb.push(i);
    while (!rb.empty()) {
        auto v = rb.pop();
        if (v) std::cout << *v << '\n';
    }
    rb.push(42);
    std::cout << "after refill: " << (rb.pop().value_or(-1)) << '\n';
    return 0;
}
