// Simple heap allocator wrapper with tracking and RAII cleanup.
#include <cstddef>
#include <iostream>
#include <unordered_map>
#include <vector>

class AllocTracker {
public:
    void* allocate(std::size_t bytes) {
        void* p = ::operator new(bytes);
        live_[p] = bytes;
        total_ += bytes;
        return p;
    }

    void deallocate(void* p) {
        auto it = live_.find(p);
        if (it == live_.end()) {
            std::cerr << "double free or unknown pointer\n";
            return;
        }
        total_ -= it->second;
        live_.erase(it);
        ::operator delete(p);
    }

    ~AllocTracker() {
        for (auto& kv : live_) ::operator delete(kv.first);
        live_.clear();
        total_ = 0;
    }

    std::size_t live_bytes() const { return total_; }

private:
    std::unordered_map<void*, std::size_t> live_;
    std::size_t total_ = 0;
};

int main() {
    AllocTracker tracker;
    void* a = tracker.allocate(64);
    void* b = tracker.allocate(128);
    tracker.deallocate(a);
    std::cout << tracker.live_bytes() << '\n';
    tracker.deallocate(b);
    std::cout << tracker.live_bytes() << '\n';
    return 0;
}
