// Caesar cipher with validation and round-trip tests.
fn encrypt(text: &str, shift: u8) -> Result<String, String> {
    if shift > 25 {
        return Err(format!("shift {} must be 0..=25", shift));
    }
    Ok(text
        .chars()
        .map(|c| {
            if c.is_ascii_lowercase() {
                (((c as u8 - b'a' + shift) % 26) + b'a') as char
            } else if c.is_ascii_uppercase() {
                (((c as u8 - b'A' + shift) % 26) + b'A') as char
            } else {
                c
            }
        })
        .collect())
}

fn decrypt(text: &str, shift: u8) -> Result<String, String> {
    encrypt(text, (26 - (shift % 26)) % 26)
}

fn main() {
    let plain = "Attack at Dawn, 07:30!";
    let cipher = encrypt(plain, 3).unwrap();
    assert_eq!(cipher, "Dwwdfn dw Gdzq, 07:30!");
    assert_eq!(decrypt(&cipher, 3).unwrap(), plain);

    assert_eq!(encrypt("a", 0).unwrap(), "a");
    assert_eq!(encrypt("中文", 5).unwrap(), "中文");
    assert!(encrypt("x", 27).is_err());
    println!("{}", cipher);
}
