```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int v) {
    Node *n = malloc(sizeof *n);
    if (n == NULL) return head;
    n->value = v;
    n->next = head;
    return n;
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 1; i <= 5; ++i) list = push(list, i);  /* 5 4 3 2 1 */
    list = reverse(list);                                /* 1 2 3 4 5 */
    for (Node *n = list; n != NULL; n = n->next) printf("%d ", n->value);
    printf("\n");

    Node *empty = reverse(NULL);
    printf("empty reversed: %s\n", empty == NULL ? "NULL" : "non-NULL");

    free_list(list);
    return 0;
}
```

The reversal is iterative and constant-space; the explicit empty-list check confirms `reverse(NULL) == NULL` so callers don't need special-casing.

