import os
from heapq import nlargest


def largest_files(root: str, count: int = 5) -> list[tuple[int, str]]:
    found: list[tuple[int, str]] = []
    for dirpath, _dirnames, filenames in os.walk(root, onerror=lambda e: None):
        for name in filenames:
            path = os.path.join(dirpath, name)
            try:
                size = os.path.getsize(path)
            except OSError:
                continue  # vanished, unreadable symlink, permission denied
            found.append((size, path))
    return nlargest(count, found)


if __name__ == "__main__":
    import sys
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    if not os.path.isdir(target):
        sys.exit(f"not a directory: {target}")
    for size, path in largest_files(target):
        print(f"{size:>12,}  {path}")
```

`os.walk(onerror=...)` swallows directory-level permission errors, and per-file `getsize` failures are skipped, so a single unreadable path can't abort the scan. `nlargest` keeps memory bounded even for huge trees.

