#include <cassert>
#include <cstddef>
#include <stdexcept>
#include <type_traits>
#include <vector>

template <typename T, typename U>
auto dot(const std::vector<T>& a, const std::vector<U>& b) {
    static_assert(std::is_arithmetic_v<T> && std::is_arithmetic_v<U>,
                  "dot requires arithmetic element types");
    if (a.size() != b.size()) {
        throw std::invalid_argument("dot: length mismatch");
    }
    using R = std::common_type_t<T, U>;
    R acc{};
    for (std::size_t i = 0; i < a.size(); ++i) {
        acc += static_cast<R>(a[i]) * static_cast<R>(b[i]);
    }
    return acc;
}

int main() {
    assert(dot<int, int>({1, 2, 3}, {4, 5, 6}) == 32);
    assert(dot<double, int>({1.5, 2.0}, {2, 4}) == 11.0);
    assert(dot<int, int>({}, {}) == 0);
    bool threw = false;
    try {
        dot<int, int>({1, 2}, {1});
    } catch (const std::invalid_argument&) {
        threw = true;
    }
    assert(threw);
    return 0;
}
```

The return type is `std::common_type_t<T,U>`, so mixing `double` and `int` promotes correctly. Length mismatch throws instead of silently misbehaving; empty vectors yield the additive identity.

