use std::collections::HashMap;

pub fn parse_config(input: &str) -> Result<(HashMap<String, String>, Vec<String>), String> {
    let mut map: HashMap<String, String> = HashMap::new();
    let mut duplicates: Vec<String> = Vec::new();

    for (lineno, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line
            .split_once('=')
            .ok_or_else(|| format!("line {}: missing '='", lineno + 1))?;
        let key = key.trim();
        if key.is_empty() {
            return Err(format!("line {}: empty key", lineno + 1));
        }
        let value = value.trim();
        if map.insert(key.to_string(), value.to_string()).is_some() {
            duplicates.push(key.to_string());
        }
    }

    Ok((map, duplicates))
}

fn main() {
    let text = "# config\nhost = localhost\nport=8080\nhost = 127.0.0.1\n";
    match parse_config(text) {
        Ok((map, dups)) => {
            println!("host={}", map["host"]);
            println!("duplicates: {:?}", dups);
        }
        Err(e) => eprintln!("error: {e}"),
    }
}
