```cpp
#include <cstdint>
#include <iostream>

constexpr std::uint64_t MOD = 1000000007ULL;

// returns {F(n), F(n+1)} modulo MOD
std::pair<std::uint64_t, std::uint64_t> fib(std::uint64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib(n >> 1);
    std::uint64_t c = (a * ((2 * b % MOD + MOD - a) % MOD)) % MOD;
    std::uint64_t d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1ULL)
        return {d, (c + d) % MOD};
    return {c, d};
}

int main() {
    std::uint64_t n;
    if (!(std::cin >> n)) {
        std::cerr << "expected an integer\n";
        return 1;
    }
    std::cout << fib(n).first << '\n';
    return 0;
}
```

Fast doubling runs in O(log n). The trick is the identity pair `F(2k) = F(k) * (2*F(k+1) - F(k))` and `F(2k+1) = F(k)^2 + F(k+1)^2`. Input `10` prints `55`.

