```cpp
#include <iostream>
#include <stack>
#include <string>

bool is_balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                st.push(c);
                break;
            case ')':
                if (st.empty() || st.top() != '(') return false;
                st.pop();
                break;
            case ']':
                if (st.empty() || st.top() != '[') return false;
                st.pop();
                break;
            case '}':
                if (st.empty() || st.top() != '{') return false;
                st.pop();
                break;
            default:
                break;
        }
    }
    return st.empty();
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::cout << (is_balanced(line) ? "balanced" : "unbalanced") << '\n';
    }
    return 0;
}
```

The stack holds every open bracket. Each closing bracket must match the top; if it doesn't, or the stack is empty, it fails immediately. At the end the stack must be empty, otherwise something was left open. `([{}])` is balanced, `([)]` is not.

