#include <cstdio>
#include <stdexcept>
#include <string>
#include <utility>

class File {
public:
    explicit File(const std::string& path, const char* mode = "rb")
        : handle_(std::fopen(path.c_str(), mode)) {
        if (handle_ == nullptr)
            throw std::runtime_error("cannot open: " + path);
    }

    ~File() {
        if (handle_ != nullptr)
            std::fclose(handle_);
    }

    File(const File&) = delete;
    File& operator=(const File&) = delete;

    File(File&& other) noexcept : handle_(other.handle_) {
        other.handle_ = nullptr;
    }

    File& operator=(File&& other) noexcept {
        if (this != &other) {
            if (handle_ != nullptr) std::fclose(handle_);
            handle_ = other.handle_;
            other.handle_ = nullptr;
        }
        return *this;
    }

    std::FILE* get() const noexcept { return handle_; }
    bool valid() const noexcept { return handle_ != nullptr; }

private:
    std::FILE* handle_;
};

int main() {
    File f("example.txt", "w");
    std::fputs("hello\n", f.get());
    // file closes automatically when f goes out of scope
    return 0;
}
