def check_balance(s: str) -> tuple[bool, int | None]:
    """Return (True, None) if balanced, else (False, index of first problem)."""
    pairs = {")": "(", "]": "[", "}": "{"}
    openers = set(pairs.values())
    stack: list[tuple[str, int]] = []

    for i, ch in enumerate(s):
        if ch in openers:
            stack.append((ch, i))
        elif ch in pairs:
            if not stack or stack[-1][0] != pairs[ch]:
                return False, i
            stack.pop()

    if stack:
        return False, stack[-1][1]
    return True, None


if __name__ == "__main__":
    assert check_balance("([]{})") == (True, None)
    assert check_balance("") == (True, None)
    assert check_balance("(]") == (False, 1)
    assert check_balance("(()") == (False, 0)
    assert check_balance(")") == (False, 0)
    assert check_balance("a(b[c]d)e") == (True, None)
    print("ok")
