#include <cstddef>
#include <deque>
#include <iostream>
#include <optional>
#include <vector>

class RollingAverage {
public:
    explicit RollingAverage(std::size_t window) : window_(window) {}

    // Returns the average once at least `window` values have arrived.
    std::optional<double> push(int value) {
        buf_.push_back(value);
        sum_ += value;
        if (buf_.size() > window_) {
            sum_ -= buf_.front();
            buf_.pop_front();
        }
        if (buf_.size() < window_) return std::nullopt;
        return static_cast<double>(sum_) / static_cast<double>(buf_.size());
    }

private:
    std::size_t window_;
    std::deque<int> buf_;
    long long sum_ = 0;
};

int main() {
    RollingAverage avg(3);
    const std::vector<int> data{2, 4, 6, 8, 10};
    const std::vector<std::optional<double>> expected{
        std::nullopt, std::nullopt, 4.0, 6.0, 8.0};

    for (std::size_t i = 0; i < data.size(); ++i) {
        const auto result = avg.push(data[i]);
        if (result != expected[i]) return 1;
        if (result) std::cout << *result << '\n';
    }
    return 0;
}
