import csv
from collections.abc import Iterator
from pathlib import Path


def batched_rows(path: str | Path, size: int) -> Iterator[list[dict[str, str]]]:
    """Yield lists of at most `size` row dicts from a CSV file."""
    if size < 1:
        raise ValueError("batch size must be >= 1")

    p = Path(path)
    if not p.is_file():
        raise FileNotFoundError(f"no such file: {p}")

    batch: list[dict[str, str]] = []
    with p.open(newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            batch.append(row)
            if len(batch) == size:
                yield batch
                batch = []
    if batch:
        yield batch


