#include <cctype>
#include <iostream>
#include <string>

static bool is_palindrome(const std::string& s) {
    std::size_t i = 0;
    std::size_t j = s.size();
    while (i < j) {
        if (i < j && !std::isalnum(static_cast<unsigned char>(s[i]))) {
            ++i;
            continue;
        }
        if (i < j && !std::isalnum(static_cast<unsigned char>(s[j - 1]))) {
            --j;
            continue;
        }
        if (i >= j) {
            break;
        }
        unsigned char a = static_cast<unsigned char>(std::tolower(static_cast<unsigned char>(s[i])));
        unsigned char b = static_cast<unsigned char>(std::tolower(static_cast<unsigned char>(s[j - 1])));
        if (a != b) {
            return false;
        }
        ++i;
        --j;
    }
    return true;
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::cout << (is_palindrome(line) ? "yes" : "no") << "\n";
    }
    return 0;
}
