```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
    std::array<T, N> buf{};
    std::size_t head = 0;  // next write index
    std::size_t count = 0; // number of live elements

public:
    bool push(const T& v) {
        bool overwrote = (count == N);
        buf[head] = v;
        head = (head + 1) % N;
        if (!overwrote) ++count;
        return overwrote;
    }

    T pop() {
        if (count == 0) throw std::out_of_range("ring buffer is empty");
        std::size_t idx = (head + N - count) % N;
        T v = buf[idx];
        --count;
        return v;
    }

    std::size_t size() const { return count; }
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    std::cout << rb.push(4) << " size=" << rb.size() << "\n"; // 1 size=3
    for (int i = 0; i < 3; ++i) std::cout << rb.pop() << ' '; // 2 3 4
    std::cout << "\n";
}
```
Return value of `push` tells the caller whether an old element was evicted. `pop` gives the oldest live value by walking back `count` slots from `head`.

