import threading

class Counter:
    def __init__(self, start: int = 0, limit: int | None = None):
        self._lock = threading.Lock()
        self._value = start
        self._limit = limit

    def increment(self, by: int = 1) -> int:
        with self._lock:
            nxt = self._value + by
            if self._limit is not None and nxt > self._limit:
                raise ValueError(f"counter would exceed limit {self._limit}")
            self._value = nxt
            return nxt

    @property
    def value(self) -> int:
        with self._lock:
            return self._value

if __name__ == "__main__":
    c = Counter(limit=1000)
    def worker():
        for _ in range(100):
            c.increment()
    ts = [threading.Thread(target=worker) for _ in range(10)]
    for t in ts: t.start()
    for t in ts: t.join()
    print(c.value)  # 1000
```
The lock covers both the read and the write, so two threads can't read the same old value and overwrite each other. Ten threads doing 100 increments land exactly on 1000.

