#include <stdio.h>
#include <string.h>

/* Stack-based check. Input length up to 255 for this demo. */
static int is_balanced(const char *s) {
    char stack[256];
    int top = 0;

    for (const char *p = s; *p; ++p) {
        char c = *p;
        if (c == '(' || c == '[' || c == '{') {
            if (top >= (int)sizeof(stack) - 1) return 0;
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) return 0;
            char open = stack[--top];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return 0;
            }
        }
    }
    return top == 0;
}

int main(void) {
    const char *tests[] = {"()", "([{}])", "(]", "(((", ") (", "", "{[()]}"};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); ++i) {
        printf("%-8s -> %s\n", tests[i], is_balanced(tests[i]) ? "valid" : "invalid");
    }
    return 0;
}
```
Opening brackets are pushed; a closing bracket must pop the matching opener or the function fails. The final `top == 0` check catches unterminated opens like `(((`. The empty string is balanced.

