```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << std::boolalpha;
    std::cout << rb.push(1) << ' ' << rb.push(2) << ' ' << rb.push(3) << '\n'; // all true
    std::cout << rb.push(4) << '\n';  // false: full
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n' << rb.empty() << '\n'; // true
    return 0;
}
```
`head_`/`tail_` wrap with `% N` and `size_` distinguishes full from empty (a bare head==tail check cannot). `push` returns `false` when full instead of overwriting; `pop` returns `std::nullopt` when empty.

