```python
import threading
from collections import deque


class BoundedQueue:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._items = deque()
        self._capacity = capacity
        self._cond = threading.Condition()

    def put(self, item) -> None:
        with self._cond:
            while len(self._items) >= self._capacity:
                self._cond.wait()
            self._items.append(item)
            self._cond.notify()

    def get(self):
        with self._cond:
            while not self._items:
                self._cond.wait()
            item = self._items.popleft()
            self._cond.notify()
            return item

    def __len__(self) -> int:
        with self._cond:
            return len(self._items)


if __name__ == "__main__":
    q = BoundedQueue(2)
    produced = []
    consumed = []

    def producer():
        for i in range(5):
            q.put(i)
            produced.append(i)

    def consumer():
        for _ in range(5):
            consumed.append(q.get())

    t1 = threading.Thread(target=producer)
    t2 = threading.Thread(target=consumer)
    t1.start(); t2.start()
    t1.join(); t2.join()
    print("produced:", produced)
    print("consumed:", consumed)
```
Every wait sits inside a `while` loop, so a spurious wakeup or a racing thread re-checks the predicate before proceeding. `put` blocks while full, `get` blocks while empty, and each successful operation calls `notify()` to release the opposite side. The `Condition` guards both the deque and the capacity check as one atomic unit.

