```cpp
#include <cstddef>
#include <optional>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), tail_(0), count_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool push(double value) {
        if (count_ == cap_) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % cap_;
        ++count_;
        return true;
    }

    std::optional<double> pop() {
        if (count_ == 0) return std::nullopt;
        double value = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    std::size_t capacity() const { return cap_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == cap_; }

private:
    std::vector<double> buf_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t tail_;
    std::size_t count_;
};
