int main() {
    std::string line;
    if (!std::getline(std::cin, line) || line.empty()) {
        std::cerr << "error: no input\n";
        return 1;
    }

    unsigned long long value = 0;
    try {
        std::size_t pos = 0;
        value = std::stoull(line, &pos, 10);
        if (pos != line.size()) {
            std::cerr << "error: trailing characters\n";
            return 1;
        }
    } catch (const std::exception&) {
        std::cerr << "error: not a valid unsigned integer\n";
        return 1;
    }

    std::string bits;
    for (int i = 63; i >= 0; --i) {
        bits.push_back(((value >> i) & 1ULL) ? '1' : '0');
    }
    // Trim leading zeros but keep at least one digit.
    std::size_t first = bits.find('1');
    if (first == std::string::npos) first = bits.size() - 1;
    bits = bits.substr(first);

    std::size_t pad = (4 - bits.size() % 4) % 4;
    bits = std::string(pad, '0') + bits;

    for (std::size_t i = 0; i < bits.size(); i += 4) {
        if (i) std::cout << ' ';
        std::cout << bits.substr(i, 4);
    }
    std::cout << '\n';
    return 0;
}
