```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next; /* save before relinking */
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (n == NULL) {
        perror("malloc");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++)
        head = push(head, i);   /* list: 5 4 3 2 1 */

    head = reverse(head);       /* list: 1 2 3 4 5 */

    for (Node *p = head; p != NULL; p = p->next)
        printf("%d ", p->value);
    putchar('\n');

    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
```

The classic three-pointer walk: each iteration saves the successor, flips the current node's link, then advances. Empty and single-node lists are handled by the same loop. Compile with `gcc -Wall -Wextra -fsanitize=address` to check for leaks and UAF.

