pub fn parse_semver(input: &str) -> Result<Semver, String> {
    let parts: Vec<&str> = input.split('.').collect();
    if parts.len() != 3 {
        return Err(format!("expected 3 components, got {}", parts.len()));
    }

    fn parse_part(s: &str, name: &str) -> Result<u64, String> {
        if s.is_empty() {
            return Err(format!("{name} is empty"));
        }
        if !s.bytes().all(|b| b.is_ascii_digit()) {
            return Err(format!("{name} '{s}' is not numeric"));
        }
        s.parse::<u64>()
            .map_err(|e| format!("{name} '{s}' out of range: {e}"))
    }

    Ok(Semver {
        major: parse_part(parts[0], "major")?,
        minor: parse_part(parts[1], "minor")?,
        patch: parse_part(parts[2], "patch")?,
    })
}

fn main() {
    assert_eq!(parse_semver("1.2.3"), Ok(Semver { major: 1, minor: 2, patch: 3 }));
    assert!(parse_semver("1.2").is_err());
    assert!(parse_semver("1..3").is_err());
    assert!(parse_semver("1.2.x").is_err());
    assert!(parse_semver("1.2.3.4").is_err());
    println!("all checks passed");
}
