```python
import functools
import time


def retry(attempts=3, delay=0.5, factor=2.0, exceptions=(Exception,)):
    """Retry the wrapped function on `exceptions` with exponential backoff.

    Raises the last exception if every attempt fails.
    """
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            wait = delay
            last_error = None
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_error = exc
                    if attempt == attempts:
                        break
                    time.sleep(wait)
                    wait *= factor
            raise last_error
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, delay=0.01, exceptions=(ValueError,))
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return "ok"

    assert flaky() == "ok"
    assert calls["n"] == 3
    print("succeeded after", calls["n"], "calls")
```

`functools.wraps` keeps the original name and docstring. The final failure re-raises the *last* exception rather than a wrapper, so callers see the real error. Sleeping after the last checked attempt is skipped to avoid a pointless delay.

