#include <stdio.h>
#include <string.h>

void longest_palindrome(const char *s, char *out, size_t out_len) {
    size_t n = strlen(s);
    if (n == 0) { out[0] = '\0'; return; }
    size_t start = 0, max_len = 1;
    for (size_t i = 0; i < n; i++) {
        size_t l = i, r = i;
        while (l < n && r < n && s[l] == s[r]) { l--; r++; }
        l++; r--;
        if (r - l + 1 > max_len) { max_len = r - l + 1; start = l; }
        l = i; r = i + 1;
        while (l < n && r < n && s[l] == s[r]) { l--; r++; }
        l++; r--;
        if (r - l + 1 > max_len) { max_len = r - l + 1; start = l; }
    }
    if (max_len >= out_len) max_len = out_len - 1;
    memcpy(out, s + start, max_len);
    out[max_len] = '\0';
}

int main(void) {
    char buf[64];
    longest_palindrome("babad", buf, sizeof(buf));
    printf("%s\n", buf);
    return 0;
