pub fn first_index<T: Ord>(haystack: &[T], needle: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = haystack.len();

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if &haystack[mid] < needle {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    if lo < haystack.len() && &haystack[lo] == needle {
        Some(lo)
    } else {
        None
    }
}

