Here's a streaming median tracker. The max-heap holds the lower half (negated to reuse heapq's min-heap), the min-heap holds the upper half, and we rebalance after each insert so the sizes never differ by more than one.

```python
import heapq


class RunningMedian:
    def __init__(self):
        self.low = []   # max-heap via negation, holds the smaller half
        self.high = []  # min-heap, holds the larger half

    def add(self, value: int) -> None:
        if not self.low or value <= -self.low[0]:
            heapq.heappush(self.low, -value)
        else:
            heapq.heappush(self.high, value)

        if len(self.low) > len(self.high) + 1:
            heapq.heappush(self.high, -heapq.heappop(self.low))
        elif len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def median(self) -> float | None:
        if not self.low:
            return None
        if len(self.low) == len(self.high):
            return (-self.low[0] + self.high[0]) / 2.0
        return float(-self.low[0])


if __name__ == "__main__":
    stream = RunningMedian()
    results = []
    for x in [5, 15, 1, 3, 8, 7, 9, 10, 6, 11]:
        stream.add(x)
        results.append(stream.median())
    print(results)
    assert results == [5.0, 10.0, 5.0, 4.0, 5.0, 6.0, 7.0, 7.5, 7.0, 7.5]
```

The empty case returns `None` rather than crashing, and even-sized windows average the two middle elements.

This tokenizer lowercases ASCII, treats any non-alphanumeric byte as a separator, and keeps bytes >= 0x80 as word characters so UTF-8 words survive. Ties are broken alphabetically for deterministic output.

```cpp
#include <algorithm>
#include <cctype>
#include <iostream>
#include <map>
#include <string>
#include <vector>

static bool is_word_byte(unsigned char c) {
    return std::isalnum(c) || c >= 0x80;
}

int main() {
    std::map<std::string, long long> freq;
    std::string word;
    int c;
    while ((c = std::getchar()) != EOF) {
        unsigned char uc = static_cast<unsigned char>(c);
        if (is_word_byte(uc)) {
            word.push_back(static_cast<char>(std::tolower(uc)));
        } else if (!word.empty()) {
            ++freq[word];
            word.clear();
        }
    }
    if (!word.empty()) ++freq[word];

    std::vector<std::pair<std::string, long long>> items(freq.begin(), freq.end());
    std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });

    int limit = std::min<int>(10, items.size());
    for (int i = 0; i < limit; ++i) {
        std::cout << items[i].second << ' ' << items[i].first << '\n';
    }
    return 0;
}
```

Empty input produces no output. The comparator is a strict weak ordering, so `std::sort` is safe.

I use an arena-style list to avoid `Rc/RefCell`: `Vec` of nodes with integer prev/next indices, plus a `HashMap<u64, usize>` from key to node index. That keeps everything in safe Rust and O(1) per operation.

```rust
use std::collections::HashMap;

struct Node {
    key: u64,
    value: i64,
    prev: usize,
    next: usize,
}

pub struct LruCache {
    cap: usize,
    map: HashMap<u64, usize>,
    nodes: Vec<Node>,
    head: usize, // most recently used
    tail: usize, // least recently used
    free: Vec<usize>,
}

const NIL: usize = usize::MAX;

impl LruCache {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache { cap, map: HashMap::new(), nodes: Vec::new(), head: NIL, tail: NIL, free: Vec::new() }
    }

    fn detach(&mut self, i: usize) {
        let (p, n) = (self.nodes[i].prev, self.nodes[i].next);
        if p != NIL { self.nodes[p].next = n; } else { self.head = n; }
        if n != NIL { self.nodes[n].prev = p; } else { self.tail = p; }
    }

    fn push_front(&mut self, i: usize) {
        self.nodes[i].prev = NIL;
        self.nodes[i].next = self.head;
        if self.head != NIL { self.nodes[self.head].prev = i; }
        self.head = i;
        if self.tail == NIL { self.tail = i; }
    }

    pub fn get(&mut self, key: u64) -> Option<i64> {
        let idx = *self.map.get(&key)?;
        self.detach(idx);
        self.push_front(idx);
        Some(self.nodes[idx].value)
    }

    pub fn put(&mut self, key: u64, value: i64) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].value = value;
            self.detach(idx);
            self.push_front(idx);
            return;
        }
        if self.map.len() == self.cap {
            let victim = self.tail;
            self.detach(victim);
            self.map.remove(&self.nodes[victim].key);
            self.free.push(victim);
        }
        let idx = if let Some(i) = self.free.pop() {
            self.nodes[i] = Node { key, value, prev: NIL, next: NIL };
            i
        } else {
            self.nodes.push(Node { key, value, prev: NIL, next: NIL });
            self.nodes.len() - 1
        };
        self.map.insert(key, idx);
        self.push_front(idx);
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 1);
    c.put(2, 2);
    assert_eq!(c.get(1), Some(1));
    c.put(3, 3);          // evicts key 2
    assert_eq!(c.get(2), None);
    c.put(4, 4);          // evicts key 1
    assert_eq!(c.get(1), None);
    assert_eq!(c.get(3), Some(3));
    assert_eq!(c.get(4), Some(4));
    println!("ok");
}
```

Repeated `put` on an existing key refreshes recency. Zero capacity is rejected up front, so the eviction branch always has a valid tail.

It swaps byte pairs from the two ends using `pread`/`pwrite`, so memory is O(1). Partial reads are handled with a helper loop, and `ftruncate` isn't needed since length is unchanged.

```c
#define _XOPEN_SOURCE 700
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

static ssize_t read_exact(int fd, unsigned char *buf, size_t n, off_t off) {
    size_t done = 0;
    while (done < n) {
        ssize_t r = pread(fd, buf + done, n - done, off + (off_t)done);
        if (r < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (r == 0) break;
        done += (size_t)r;
    }
    return (ssize_t)done;
}

static ssize_t write_exact(int fd, const unsigned char *buf, size_t n, off_t off) {
    size_t done = 0;
    while (done < n) {
        ssize_t w = pwrite(fd, buf + done, n - done, off + (off_t)done);
        if (w < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        done += (size_t)w;
    }
    return (ssize_t)done;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s FILE\n", argv[0]);
        return 2;
    }
    int fd = open(argv[1], O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }
    off_t len = lseek(fd, 0, SEEK_END);
    if (len < 0) {
        perror("lseek");
        close(fd);
        return 1;
    }
    off_t i = 0, j = len - 1;
    while (i < j) {
        unsigned char a, b;
        if (read_exact(fd, &a, 1, i) != 1 || read_exact(fd, &b, 1, j) != 1) {
            fprintf(stderr, "read failed at offsets %lld/%lld\n", (long long)i, (long long)j);
            close(fd);
            return 1;
        }
        if (write_exact(fd, &b, 1, i) != 1 || write_exact(fd, &a, 1, j) != 1) {
            fprintf(stderr, "write failed\n");
            close(fd);
            return 1;
        }
        i++;
        j--;
    }
    if (fsync(fd) != 0) {
        perror("fsync");
        close(fd);
        return 1;
    }
    close(fd);
    return 0;
}
```

Empty files and single-byte files skip the loop entirely. `EINTR` on either syscall is retried, not treated as failure.

The arena advances a bump pointer, aligning each allocation up to a requested power-of-two alignment. When the region can't satisfy a request, `allocate` returns `nullptr` rather than corrupting memory.

```cpp
#include <cstdint>
#include <cstddef>
#include <iostream>
#include <new>

class Arena {
public:
    Arena(unsigned char* buffer, std::size_t size)
        : buf_(buffer), size_(size), offset_(0) {}

    void* allocate(std::size_t bytes, std::size_t align = alignof(std::max_align_t)) {
        if (align == 0 || (align & (align - 1)) != 0) return nullptr; // power of two only
        std::uintptr_t base = reinterpret_cast<std::uintptr_t>(buf_ + offset_);
        std::uintptr_t aligned = (base + align - 1) & ~(static_cast<std::uintptr_t>(align) - 1);
        std::size_t pad = aligned - base;
        if (bytes > size_ || offset_ + pad + bytes > size_) return nullptr;
        offset_ += pad + bytes;
        return reinterpret_cast<void*>(aligned);
    }

    void reset() { offset_ = 0; }
    std::size_t used() const { return offset_; }
    std::size_t capacity() const { return size_; }

private:
    unsigned char* buf_;
    std::size_t size_;
    std::size_t offset_;
};

struct Vec3 { float x, y, z; };

int main() {
    alignas(64) unsigned char storage[256];
    Arena arena(storage, sizeof(storage));

    void* a = arena.allocate(sizeof(Vec3), alignof(Vec3));
    void* b = arena.allocate(64, 64);
    if (!a || !b) { std::cerr << "unexpected exhaustion\n"; return 1; }

    auto* v = new (a) Vec3{1.0f, 2.0f, 3.0f};
    if (reinterpret_cast<std::uintptr_t>(b) % 64 != 0) {
        std::cerr << "alignment violated\n";
        return 1;
    }

    void* huge = arena.allocate(1024);
    if (huge != nullptr) {
        std::cerr << "exhaustion not reported\n";
        return 1;
    }

    arena.reset();
    if (arena.used() != 0) { std::cerr << "reset failed\n"; return 1; }

    std::cout << "v=(" << v->x << ',' << v->y << ',' << v->z << ") "
              << "capacity=" << arena.capacity() << '\n';
    return 0;
}
```

Non-power-of-two alignments are rejected. The `Vec3` is placement-newed into the arena, so the memory is actually usable, not just reserved.

`BufReader::lines` yields owned `String`s one at a time; the iterator stops at the first error, and we stop reading entirely once we hit the limit. The search lowercases both sides for the case-insensitive match.

```rust
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

pub fn first_matching_lines(
    path: &Path,
    needle: &str,
    limit: usize,
) -> io::Result<Vec<(usize, String)>> {
    if limit == 0 || needle.is_empty() {
        return Ok(Vec::new());
    }
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let lower = needle.to_lowercase();
    let mut out = Vec::with_capacity(limit);

    for (idx, line) in reader.lines().enumerate() {
        let line = line?;
        if line.to_lowercase().contains(&lower) {
            out.push((idx + 1, line));
            if out.len() == limit {
                break;
            }
        }
    }
    Ok(out)
}

fn main() -> io::Result<()> {
    let path = std::env::temp_dir().join("xtluna_lazy_scan.txt");
    std::fs::write(&path, "alpha\nBeta\ngamma beta\nDELTA\nbeta again\n")?;

    let hits = first_matching_lines(&path, "BETA", 3)?;
    for (n, text) in &hits {
        println!("{n}: {text}");
    }
    assert_eq!(hits.len(), 2);
    assert_eq!(hits[0].0, 2);

    let none = first_matching_lines(&path, "zzz", 3)?;
    assert!(none.is_empty());

    let empty = first_matching_lines(&path, "", 3)?;
    assert!(empty.is_empty());

    std::fs::remove_file(&path).ok();
    Ok(())
}
```

The function never reads past the line where `limit` is reached, and line numbers are 1-based. An empty needle or zero limit short-circuits to an empty vector.

```cpp
#include <cstdio>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;  // max-heap, left half
    std::priority_queue<int, std::vector<int>, std::greater<int>> high;  // min-heap, right half
    long long x;
    while (std::cin >> x) {
        int v = static_cast<int>(x);
        if (low.empty() || v <= low.top()) {
            low.push(v);
        } else {
            high.push(v);
        }

        // Rebalance so low.size() == high.size() or low.size() == high.size() + 1
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        double median;
        if (low.size() == high.size()) {
            median = (static_cast<double>(low.top()) + high.top()) / 2.0;
        } else {
            median = static_cast<double>(low.top());
        }

        // Print without trailing zeros: 5 -> "5", 5.5 -> "5.5"
        if (median == static_cast<long long>(median)) {
            std::cout << static_cast<long long>(median) << '\n';
        } else {
            std::cout << median << '\n';
        }
    }
    return 0;
}
```
Input `5 15 1 3` prints `5`, `10`, `5`, `4`. Two heaps keep the lower half in `low` (max-heap) and the upper half in `high` (min-heap); the size invariant makes the median either `low.top()` or the mean of both tops. Insertion is O(log n).

```cpp
#include <iostream>
#include <string>

std::string to_base(long long n, int base) {
    if (base < 2 || base > 36) return "";
    if (n == 0) return "0";

    const char digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";
    bool negative = n < 0;
    // Use unsigned to avoid overflow on LLONG_MIN
    unsigned long long u = negative
        ? static_cast<unsigned long long>(-(n + 1)) + 1ULL
        : static_cast<unsigned long long>(n);

    std::string out;
    while (u > 0) {
        out += digits[u % static_cast<unsigned long long>(base)];
        u /= static_cast<unsigned long long>(base);
    }
    if (negative) out += '-';
    std::reverse(out.begin(), out.end());
    return out;
}

int main() {
    struct { long long n; int b; const char* want; } cases[] = {
        {255, 16, "ff"}, {0, 2, "0"}, {-31, 36, "-v"}, {1000, 8, "1750"},
        {7, 2, "111"}, {-1, 2, "-1"},
    };
    for (auto& c : cases) {
        std::string got = to_base(c.n, c.b);
        std::cout << c.n << " base " << c.b << " = " << got;
        std::cout << (got == c.want ? "  ok" : "  FAIL") << '\n';
    }
}
```
Each case prints `ok`. The digit table gives lowercase letters for bases above 10; negatives are handled by converting the magnitude through `unsigned long long` so `LLONG_MIN` does not overflow.

```rust
/// Remove runs of equal characters, keeping the first of each run.
/// "aabbccd" -> "abcd", "" -> "", "aaa" -> "a".
fn dedup_in_place(s: &mut String) {
    let bytes = unsafe { s.as_mut_vec() };
    let mut w = 0usize;
    for r in 0..bytes.len() {
        if w == 0 || bytes[r] != bytes[w - 1] {
            bytes[w] = bytes[r];
            w += 1;
        }
    }
    bytes.truncate(w);
}

fn main() {
    let cases = [("aabbccd", "abcd"), ("", ""), ("aaa", "a"),
                 ("abc", "abc"), ("aabbaa", "aba")];
    for (input, want) in cases {
        let mut s = input.to_string();
        dedup_in_place(&mut s);
        println!("{:?} -> {:?} {}", input, s, if s == want { "ok" } else { "FAIL" });
    }
}
```
All five cases print `ok`. The write index `w` never overtakes the read index `r`, so the in-place compaction is safe; the run `"aabbaa"` becomes `"aba"` because only adjacent equals collapse.

```rust
fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' => {
                if stack.pop() != Some('(') { return false; }
            }
            ']' => {
                if stack.pop() != Some('[') { return false; }
            }
            '}' => {
                if stack.pop() != Some('{') { return false; }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    let cases = [
        ("", true),
        ("([]{})", true),
        ("([)]", false),
        ("(", false),
        (")", false),
        ("a(b[c]{d})e", true),
        ("{[()]}", true),
        ("(]", false),
    ];
    let mut all_ok = true;
    for (input, want) in cases {
        let got = is_balanced(input);
        if got != want { all_ok = false; }
        println!("{:?} -> {} (want {})", input, got, want);
    }
    println!("{}", if all_ok { "all ok" } else { "FAIL" });
}
```
Every case matches expectations and the program prints `all ok`. A `pop()` returning the wrong opener — or `None` on an empty stack — immediately rejects the string; the final `stack.is_empty()` catches unclosed openers.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *new_node(int v) {
    Node *n = malloc(sizeof *n);
    if (!n) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = v;
    n->next = NULL;
    return n;
}

static Node *reverse_iter(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *reverse_rec(Node *head) {
    if (!head || !head->next) return head;
    Node *rest = reverse_rec(head->next);
    head->next->next = head;
    head->next = NULL;
    return rest;
}

static void print_list(const char *label, Node *head) {
    printf("%s:", label);
    for (Node *p = head; p; p = p->next) printf(" %d", p->value);
    putchar('\n');
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 5; i >= 1; --i) {
        Node *n = new_node(i);
        n->next = list;
        list = n;
    }
    print_list("original", list);              // 1 2 3 4 5
    Node *rev = reverse_iter(list);
    print_list("iterative", rev);              // 5 4 3 2 1
    Node *back = reverse_rec(rev);
    print_list("recursive", back);             // 1 2 3 4 5
    free_list(back);
    return 0;
}
```
The iterative version flips each `next` pointer while walking forward. The recursive version recurses to the tail, then rewires pointers on the way back. Output: `original: 1 2 3 4 5`, `iterative: 5 4 3 2 1`, `recursive: 1 2 3 4 5`. Note the recursive version uses stack depth proportional to list length.

