static void reverse_in_place(char *s, size_t n) {
    if (n < 2) return;
    size_t i = 0, j = n - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

int main(void) {
    char buf[256];

    if (fgets(buf, sizeof buf, stdin) == NULL) {
        puts("");  /* empty input */
        return 0;
    }

    size_t n = strlen(buf);
    if (n > 0 && buf[n - 1] == '\n') {
        buf[--n] = '\0';
    }
    if (n > 0 && buf[n - 1] == '\r') {
        buf[--n] = '\0';
    }

    reverse_in_place(buf, n);
    puts(buf);
    return 0;
}
