```c
#include <stdio.h>
#include <stdint.h>

static void to_binary(uint32_t value, char *out, size_t out_size) {
    size_t i = 0;
    if (value == 0) {
        if (out_size > 1) {
            out[0] = '0';
            out[1] = '\0';
        }
        return;
    }
    char tmp[33];
    while (value > 0 && i < sizeof tmp - 1) {
        tmp[i++] = (char)('0' + (value & 1u));
        value >>= 1;
    }
    size_t n = i < out_size - 1 ? i : out_size - 1;
    for (size_t j = 0; j < n; j++) {
        out[j] = tmp[i - 1 - j];
    }
    out[n] = '\0';
}

static uint32_t from_binary(const char *bits) {
    uint32_t value = 0;
    for (; *bits; ++bits) {
        value = (value << 1) | (uint32_t)(*bits - '0');
    }
    return value;
}

int main(void) {
    uint32_t cases[] = {0u, 1u, 5u, 255u, 1024u, 4294967295u};
    char buf[33];
    for (size_t k = 0; k < sizeof cases / sizeof cases[0]; k++) {
        to_binary(cases[k], buf, sizeof buf);
        uint32_t back = from_binary(buf);
        printf("%u -> %s -> %u %s\n", cases[k], buf, back,
               back == cases[k] ? "ok" : "MISMATCH");
    }
    return 0;
}
```

`to_binary` builds digits least-significant first then reverses into the caller's buffer, so buffer size is checked. `from_binary` only trusts well-formed `0`/`1` input; passing anything else would produce garbage, which is fine for the round-trip check here.

