const long long MOD = 1000000007LL;

// returns {F(n), F(n+1)}
std::pair<long long, long long> fib(long long n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib(n >> 1);
    long long c = a * ((2 * b % MOD - a + MOD) % MOD) % MOD;
    long long d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1) return {d, (c + d) % MOD};
    return {c, d};
}

int main() {
    long long n;
    while (std::cin >> n) {
        if (n < 0) { std::cout << "negative\n"; continue; }
        std::cout << fib(n).first << "\n";
    }
    return 0;
}
