```python
def has_cycle(graph):
    """graph: dict[node, list[node]]. Returns True if a directed cycle exists."""
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in graph}
    for node in graph:
        if color[node] != WHITE:
            continue
        stack = [(node, iter(graph.get(node, ())))]
        color[node] = GRAY
        while stack:
            current, children = stack[-1]
            advanced = False
            for child in children:
                if color.get(child, WHITE) == GRAY:
                    return True
                if color.get(child, WHITE) == WHITE:
                    color[child] = GRAY
                    stack.append((child, iter(graph.get(child, ()))))
                    advanced = True
                    break
            if not advanced:
                color[current] = BLACK
                stack.pop()
    return False


if __name__ == "__main__":
    assert has_cycle({"a": ["b"], "b": ["c"], "c": ["a"]}) is True
    assert has_cycle({"a": ["b"], "b": ["c"], "c": []}) is False
    assert has_cycle({}) is False
    assert has_cycle({"a": ["a"]}) is True
    print("ok")
```

GRAY marks the current DFS path; reaching a GRAY node again means a back edge, i.e. a cycle. The explicit stack avoids recursion depth limits.

