```rust
fn is_balanced(input: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for ch in input.chars() {
        match ch {
            '(' | '[' | '{' => stack.push(ch),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(expected) {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    assert!(is_balanced(""));
    assert!(is_balanced("a(b[c]{d})e"));
    assert!(!is_balanced("([)]"));
    assert!(!is_balanced("("));
    assert!(!is_balanced(")"));
    assert!(is_balanced("{([])}"));
    println!("all balance cases passed");
}
```

A stack is the right structure: every opener is pushed, every closer must match the most recent unmatched opener. Mismatched nesting like `([)]` fails because `)` pops `[` instead of `(`. Non-bracket characters are ignored, so strings containing letters or digits still validate correctly.

