        rows = 0
        for row in reader:
            rows += 1
            for name in columns:
                raw = (row.get(name) or "").strip()
                if not raw:
                    continue
                try:
                    numeric[name].append(float(raw))
                except ValueError:
                    numeric.pop(name, None)

        print(f"rows: {rows}")
        print("columns: " + ", ".join(columns))
        for name in columns:
            values = numeric.get(name)
            if values:
                print(f"  {name}: min={min(values):g} max={max(values):g} n={len(values)}")
            else:
                print(f"  {name}: non-numeric")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: python summarize.py <file.csv>", file=sys.stderr)
        sys.exit(2)
    summarize(sys.argv[1])
```

`utf-8-sig` silently strips a leading BOM so the first column name matches. A column demotes itself to non-numeric the first time a value fails `float()`, so mixed columns are reported honestly rather than crashing.

