#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;
    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

int main(void) {
    char empty[] = "";
    char single[] = "x";
    char word[] = "hello";
    char mixed[] = "a b c";

    reverse_in_place(empty);
    reverse_in_place(single);
    reverse_in_place(word);
    reverse_in_place(mixed);
    reverse_in_place(NULL);

    printf("[%s] [%s] [%s] [%s]\n", empty, single, word, mixed);
    return 0;
}
```

Two pointers meet in the middle, so each pair is swapped once with O(1) extra space. `strlen` gives the byte length; lengths 0 and 1 have nothing to swap, and a NULL pointer is a no-op. The program prints `[] [x] [olleh] [c b a]`.

