```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
    std::array<int, N> data_{};
    std::size_t head_ = 0;  // next write
    std::size_t count_ = 0;

public:
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }
    std::size_t size() const { return count_; }

    bool push(int value) {
        if (full()) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }
};

int main() {
    RingBuffer<3> rb;
    assert(rb.empty() && !rb.full());
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.full() && !rb.push(4));
    assert(rb.pop() == 1);
    assert(rb.push(9));  // wraps into slot 0
    assert(rb.size() == 3);
    while (rb.size()) std::cout << *rb.pop() << ' ';
    std::cout << '\n';
    assert(rb.pop() == std::nullopt);
    std::cout << "ring buffer ok\n";
}
```

`head_` marks the oldest element and `count_` tracks occupancy, so a full buffer is distinguished from an empty one that happens to share the same indices. Wrapping uses modulo `N`; `std::optional` lets `pop` report an empty buffer without sentinel values.

