```cpp
#include <cstring>
#include <iostream>
#include <string>

std::string dedupe(const char* s) {
    bool seen[256] = {false};
    std::string out;
    for (const char* p = s; *p != '\0'; ++p) {
        unsigned char c = static_cast<unsigned char>(*p);
        if (!seen[c]) {
            seen[c] = true;
            out.push_back(*p);
        }
    }
    return out;
}

int main() {
    std::cout << dedupe("banana") << '\n';      // ban
    std::cout << dedupe("a b a") << '\n';       // a b
    std::cout << "[" << dedupe("") << "]\n";   // []
    std::cout << dedupe("abcABC") << '\n';      // abcABC (case-sensitive)
    return 0;
}
```

The `seen` array is indexed by the raw byte, so multi-byte UTF-8 sequences are treated byte-wise and preserved intact; the first byte wins and later identical bytes are dropped, which keeps valid UTF-8 output as long as duplicates are contiguous byte matches.

