template <std::size_t N>
class RingBuffer {
public:
    void push(int v) {
        data_[head_] = v;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    int pop() {
        if (size_ == 0) throw std::underflow_error("empty");
        std::size_t tail = (head_ + N - size_) % N;
        int v = data_[tail];
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }

    void print() const {
        std::size_t tail = (head_ + N - size_) % N;
        for (std::size_t i = 0; i < size_; ++i) {
            std::cout << data_[(tail + i) % N] << (i + 1 == size_ ? '\n' : ' ');
        }
    }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4);              // overwrites 1
    rb.print();              // 2 3 4
    std::cout << rb.pop() << '\n';  // 2
