    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The quick, the QUICK brown fox!";
    let top = top_words(text, 2);
    assert_eq!(top[0], ("the".to_string(), 2));
    assert_eq!(top[1], ("quick".to_string(), 2));
    assert!(top_words("", 3).is_empty());
    println!("{:?}", top);
}
