```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int key, value;
    struct Node *prev, *next;
} Node;

typedef struct {
    int capacity, size;
    Node *head, *tail;       // head = most recent
    Node **buckets;
    int nbuckets;
} LRU;

static unsigned hash_int(int k) { return (unsigned)k * 2654435761u; }

static void detach(LRU *c, Node *n) {
    if (n->prev) n->prev->next = n->next; else c->head = n->next;
    if (n->next) n->next->prev = n->prev; else c->tail = n->prev;
    n->prev = n->next = NULL;
}

static void attach_front(LRU *c, Node *n) {
    n->next = c->head;
    n->prev = NULL;
    if (c->head) c->head->prev = n;
    c->head = n;
    if (!c->tail) c->tail = n;
}

static Node *find(LRU *c, int key) {
    unsigned idx = hash_int(key) % (unsigned)c->nbuckets;
    for (Node *n = c->buckets[idx]; n; n = n->prev) {
        if (n->key == key) return n;
    }
    return NULL;
}

static void insert_bucket(LRU *c, Node *n) {
    unsigned idx = hash_int(n->key) % (unsigned)c->nbuckets;
    n->prev = c->buckets[idx];
    c->buckets[idx] = n;
}

static void remove_bucket(LRU *c, Node *n) {
    unsigned idx = hash_int(n->key) % (unsigned)c->nbuckets;
    Node **cur = &c->buckets[idx];
    while (*cur && *cur != n) cur = &(*cur)->prev;
    if (*cur) *cur = n->prev;
}

LRU *lru_new(int capacity) {
    LRU *c = calloc(1, sizeof(LRU));
    c->capacity = capacity;
    c->nbuckets = capacity * 2 + 1;
    c->buckets = calloc((size_t)c->nbuckets, sizeof(Node *));
    return c;
}

int lru_get(LRU *c, int key, int *out) {
    Node *n = find(c, key);
    if (!n) return 0;
    detach(c, n);
    attach_front(c, n);
    *out = n->value;
    return 1;
}

void lru_put(LRU *c, int key, int value) {
    Node *n = find(c, key);
    if (n) {
        n->value = value;
        detach(c, n);
        attach_front(c, n);
        return;
    }
    n = malloc(sizeof(Node));
    n->key = key;
    n->value = value;
    n->prev = n->next = NULL;
    attach_front(c, n);
    insert_bucket(c, n);
    c->size++;
    if (c->size > c->capacity) {
        Node *victim = c->tail;
        detach(c, victim);
        remove_bucket(c, victim);
        free(victim);
        c->size--;
    }
}

int main(void) {
    LRU *c = lru_new(2);
    lru_put(c, 1, 10);
    lru_put(c, 2, 20);
    int v;
    printf("%d\n", lru_get(c, 1, &v)); // 1
    lru_put(c, 3, 30);                  // evicts 2
    printf("%d\n", lru_get(c, 2, &v)); // 0
    printf("%d\n", lru_get(c, 3, &v)); // 1
    return 0;
}
