import heapq


def dijkstra(adj, source):
    dist = {node: float("inf") for node in adj}
    dist[source] = 0
    pq = [(0, source)]
    settled = set()

    while pq:
        d, node = heapq.heappop(pq)
        if node in settled:
            continue
        settled.add(node)
        for nxt, weight in adj[node]:
            if weight < 0:
                raise ValueError("negative weight not supported")
            nd = d + weight
            if nd < dist.get(nxt, float("inf")):
                dist[nxt] = nd
                heapq.heappush(pq, (nd, nxt))

    return dist


if __name__ == "__main__":
    graph = {
        "A": [("B", 1), ("C", 4)],
        "B": [("C", 2), ("D", 5)],
        "C": [("D", 1)],
        "D": [],
    }
    result = dijkstra(graph, "A")
    assert result == {"A": 0, "B": 1, "C": 3, "D": 4}, result
    print(result)
```

Lazy deletion stands in for real decrease-key: a stale entry is skipped when it is popped after the node is already settled.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;  /* save before rewiring */
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

static Node *push(Node *head, int v) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) {
        return NULL;
    }
    n->value = v;
    n->next = head;
    return n;
}

static void print(Node *head) {
    for (Node *n = head; n; n = n->next) {
        printf("%d%s", n->value, n->next ? " -> " : "\n");
    }
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 5; i >= 1; --i) {
        head = push(head, i);
    }
    print(head);
    head = reverse(head);
    print(head);
    free_list(head);
    return 0;
}
```

`reverse` walks the list once, flipping each `next` pointer to point at the previous node. It handles an empty list (`head == NULL` returns `NULL`) and a single node without special cases. The saved `next` pointer is essential: once `cur->next` is overwritten the rest of the list would otherwise be lost. Output is `1 -> 2 -> 3 -> 4 -> 5` then `5 -> 4 -> 3 -> 2 -> 1`.

```cpp
#include <algorithm>
#include <cctype>
#include <iostream>
#include <map>
#include <string>
#include <vector>

int main() {
    std::map<std::string, long> counts;
    std::string word;
    while (std::cin >> word) {
        // Strip surrounding punctuation and lowercase ASCII letters.
        std::string clean;
        for (unsigned char c : word) {
            if (std::isalpha(c)) {
                clean.push_back(static_cast<char>(std::tolower(c)));
            }
        }
        if (!clean.empty()) {
            ++counts[clean];
        }
    }

    std::vector<std::pair<std::string, long>> items(counts.begin(), counts.end());
    const std::size_t k = std::min<std::size_t>(5, items.size());
    std::partial_sort(items.begin(), items.begin() + k, items.end(),
        [](const auto &a, const auto &b) {
            if (a.second != b.second) return a.second > b.second;
            return a.first < b.first;  // stable, deterministic ties
        });

    for (std::size_t i = 0; i < k; ++i) {
        std::cout << items[i].first << ' ' << items[i].second << '\n';
    }
    return 0;
}
```

Input is read token by token, so it handles arbitrary whitespace and never loads the whole stream into memory. Non-ASCII bytes are dropped rather than misread as letters, which keeps output stable on UTF-8 input. `partial_sort` is O(n log k) instead of a full O(n log n) sort, and the comparator breaks ties by word so equal counts print in a fixed order. An empty stream produces no output and exits cleanly.

```rust
fn is_palindrome(s: &str) -> bool {
    let bytes = s.as_bytes();
    let mut i = 0usize;
    let mut j = bytes.len();

    while i < j {
        // Skip from the left to the next alphanumeric character.
        while i < j && !bytes[i].is_ascii_alphanumeric() {
            i += 1;
        }
        // Skip from the right to the previous alphanumeric character.
        while i < j && !bytes[j - 1].is_ascii_alphanumeric() {
            j -= 1;
        }
        if i < j {
            let a = bytes[i].to_ascii_lowercase();
            let b = bytes[j - 1].to_ascii_lowercase();
            if a != b {
                return false;
            }
            i += 1;
            j -= 1;
        }
    }
    true
}

fn main() {
    let cases = [
        ("A man, a plan, a canal: Panama", true),
        ("race a car", false),
        ("", true),
        ("!!!", true),
        ("Was it a car or a cat I saw?", true),
    ];
    for (input, expected) in cases {
        assert_eq!(is_palindrome(input), expected, "input: {input:?}");
    }
    println!("all passed");
}
```

Two indices converge from both ends, skipping characters that are not ASCII alphanumeric and comparing lowercase bytes, so nothing is allocated and the slice is touched once. Empty strings and strings with no alphanumerics are correctly true because the pointers meet without a mismatch. If you need full Unicode folds instead of ASCII, this fast path should be swapped for `char`-based iteration, which I can show on request.

```c
#include <stdio.h>

/* Returns index of key in sorted arr[0..n-1], or -1 if absent. */
int binary_search(const int *arr, int n, int key) {
    int lo = 0;
    int hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;  /* avoids overflow */
        if (arr[mid] == key) {
            return mid;
        }
        if (arr[mid] < key) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main(void) {
    const int data[] = {-9, -3, 0, 4, 7, 11, 20};
    const int n = (int)(sizeof(data) / sizeof(data[0]));

    printf("%d\n", binary_search(data, n, 0));   /* -> 2 */
    printf("%d\n", binary_search(data, n, 20));  /* -> 6 */
    printf("%d\n", binary_search(data, n, 5));   /* -> -1 */
    printf("%d\n", binary_search(data, n, -9));  /* -> 0 */
    printf("%d\n", binary_search(data, 0, 1));   /* -> -1 */
    return 0;
}
```

`lo <= hi` keeps the loop correct for every size, and `lo + (hi - lo) / 2` cannot overflow the way `(lo + hi) / 2` can for large arrays. A zero-length array is handled because `hi` becomes `-1` and the loop never runs, returning `-1`. The array must be sorted ascending; that precondition is the caller's responsibility, and the tests cover present, absent, first, last, and empty cases.

