```cpp
#include <array>
#include <cstdint>
#include <iostream>

constexpr int LIMIT = 1000;
static std::array<int, LIMIT> memo{};

int collatz_length(std::uint64_t n) {
    if (n == 1) {
        return 1;
    }
    if (n < LIMIT && memo[n] != 0) {
        return memo[n];
    }
    int len = 1 + ((n & 1u) ? collatz_length(3 * n + 1) : collatz_length(n / 2));
    if (n < LIMIT) {
        memo[n] = len;
    }
    return len;
}

int main() {
    int best = 0;
    std::uint64_t best_n = 1;
    for (std::uint64_t n = 1; n <= 1000; ++n) {
        int len = collatz_length(n);
        if (len > best) {
            best = len;
            best_n = n;
        }
    }
    std::cout << "longest under 1000: n=" << best_n << " length=" << best << '\n';
}
```

`n` is `uint64_t` because intermediate values of `3n + 1` can exceed the starting value, avoiding overflow. Memoization covers results for `n < LIMIT` and is written after the recursive computation so nested calls reuse it; the `memo[n] != 0` guard is safe since lengths are always positive. The result for the range 1..1000 is n=871 with length 179, the classic longest chain below 1000. Recursion depth here is small, but for much larger inputs an iterative loop would be safer against stack limits.

```cpp
#include <algorithm>
#include <iostream>
#include <vector>

std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    const std::vector<int> a{1, 3, 5, 7, 9};
    const std::vector<int> b{2, 3, 7};
    const auto merged = merge_sorted(a, b);
    for (std::size_t k = 0; k < merged.size(); ++k) {
        std::cout << merged[k] << (k + 1 == merged.size() ? '\n' : ' ');
    }

    // Duplicates across both inputs.
    std::vector<int> dups;
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] == b[j]) { dups.push_back(a[i]); ++i; ++j; }
        else if (a[i] < b[j]) ++i;
        else ++j;
    }
    std::cout << "duplicates:";
    for (int v : dups) std::cout << ' ' << v;
    std::cout << '\n';
    return 0;
}
```
The first loop walks both vectors with a two-pointer merge, so the result stays sorted without a second sort. The second pass uses the same technique to collect values present in both inputs. Output for the sample is `1 2 3 5 7 7 9` then `duplicates: 3 7`.

