```rust
use std::collections::{HashMap, VecDeque};

pub struct LruCache {
    capacity: usize,
    map: HashMap<String, i64>,
    order: VecDeque<String>,
}

impl LruCache {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        Self { capacity, map: HashMap::new(), order: VecDeque::new() }
    }

    fn touch(&mut self, key: &str) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            self.order.remove(pos);
        }
        self.order.push_back(key.to_string());
    }

    pub fn get(&mut self, key: &str) -> Option<i64> {
        if self.map.contains_key(key) {
            self.touch(key);
        }
        self.map.get(key).copied()
    }

    pub fn put(&mut self, key: &str, value: i64) {
        self.map.insert(key.to_string(), value);
        self.touch(key);
        while self.order.len() > self.capacity {
            if let Some(old) = self.order.pop_front() {
                self.map.remove(&old);
            }
        }
    }
}

fn main() {
    let mut cache = LruCache::new(2);
    cache.put("a", 1);
    cache.put("b", 2);
    assert_eq!(cache.get("a"), Some(1));
    cache.put("c", 3);              // evicts "b"
    assert_eq!(cache.get("b"), None);
    assert_eq!(cache.get("a"), Some(1));
    println!("lru ok");
}
```
`get` refreshes recency via `touch`, and `put` evicts from the front of the deque until the cache is back within capacity. The example confirms that re-reading `a` protects it while the untouched `b` is dropped.

