```python
from collections import deque
from typing import List, Optional, Tuple

Grid = List[str]
Point = Tuple[int, int]


def bfs(grid: Grid, start: Point, goal: Point) -> Optional[int]:
    """Shortest path length in steps from start to goal, or None."""
    if not grid or not grid[0]:
        return None
    rows, cols = len(grid), len(grid[0])

    def ok(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#'

    if not ok(*start) or not ok(*goal):
        return None
    if start == goal:
        return 0

    dist = {start: 0}
    q = deque([start])
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if ok(nr, nc) and (nr, nc) not in dist:
                dist[(nr, nc)] = dist[(r, c)] + 1
                if (nr, nc) == goal:
                    return dist[(nr, nc)]
                q.append((nr, nc))
    return None


if __name__ == "__main__":
    maze = ["S..", ".#.", "..G"]
    assert bfs(maze, (0, 0), (2, 2)) == 4
    assert bfs(maze, (0, 0), (0, 0)) == 0
    assert bfs(maze, (0, 0), (1, 1)) is None
    assert bfs([], (0, 0), (0, 0)) is None
    print("ok")
