```rust
#[derive(Debug)]
struct RingBuffer<T> {
    buf: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingBuffer<T> {
    fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        RingBuffer {
            buf: (0..capacity).map(|_| None).collect(),
            head: 0,
            len: 0,
        }
    }

    fn push(&mut self, value: T) {
        let cap = self.buf.len();
        if self.len == cap {
            self.buf[self.head] = Some(value);
            self.head = (self.head + 1) % cap;
        } else {
            let idx = (self.head + self.len) % cap;
            self.buf[idx] = Some(value);
            self.len += 1;
        }
    }

    fn iter(&self) -> impl Iterator<Item = &T> {
        let cap = self.buf.len();
        (0..self.len).map(move |i| self.buf[(self.head + i) % cap].as_ref().unwrap())
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    for v in [1, 2] {
        rb.push(v);
    }
    assert_eq!(rb.iter().copied().collect::<Vec<_>>(), vec![1, 2]);

    for v in [3, 4] {
        rb.push(v);
    }
    assert_eq!(rb.iter().copied().collect::<Vec<_>>(), vec![2, 3, 4]);
    println!("ok");
}
```

Once full, `push` overwrites the slot at `head` and advances it, so the buffer always holds the most recent `capacity` values in order. The `iter` method walks from `head` for `len` steps, wrapping with `%`.

