def roman_to_int(s):
    if not s:
        raise ValueError("empty numeral")
    total = 0
    prev = 0
    for ch in reversed(s.upper()):
        if ch not in VALUES:
            raise ValueError(f"invalid character: {ch}")
        value = VALUES[ch]
        if value < prev:
            total -= value
        else:
