fn second_largest(values: &[i64]) -> Option<i64> {
    let mut top: Option<i64> = None;
    let mut second: Option<i64> = None;

    for &v in values {
        if Some(v) == top {
            continue;
        }
        if top.is_none() || v > top.unwrap() {
            second = top;
            top = Some(v);
        } else if second.is_none() || v > second.unwrap() {
            second = Some(v);
        }
    }
    second
}

fn main() {
    assert_eq!(second_largest(&[]), None);
    assert_eq!(second_largest(&[5]), None);
    assert_eq!(second_largest(&[3, 3, 3]), None);
    assert_eq!(second_largest(&[1, 9, 4, 9, 7]), Some(7));
    assert_eq!(second_largest(&[-5, -1, -9]), Some(-5));
    println!("ok");
}
```

Single pass, no allocation. Duplicates of the current maximum are skipped so `[3, 3, 3]` correctly yields `None` rather than `Some(3)`. Handles negatives and empty slices through the `Option` return.

```c
#include <stdio.h>
#include <string.h>

/* buf must have room for the digits plus a NUL. Returns buf. */
char *utoa_base(unsigned value, unsigned base, char *buf, size_t bufsize) {
    static const char digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";

    if (base < 2 || base > 36 || bufsize < 2) {
        if (bufsize > 0) buf[0] = '\0';
        return buf;
    }

    char tmp[65];
    size_t n = 0;
    do {
        tmp[n++] = digits[value % base];
        value /= base;
    } while (value != 0);

    if (n + 1 > bufsize) {
        buf[0] = '\0';
        return buf;
    }
    for (size_t i = 0; i < n; ++i) {
        buf[i] = tmp[n - 1 - i];
    }
    buf[n] = '\0';
    return buf;
}

int main(void) {
    char buf[65];
    printf("%s\n", utoa_base(255, 16, buf, sizeof buf));   /* ff */
    printf("%s\n", utoa_base(0, 2, buf, sizeof buf));      /* 0 */
    printf("%s\n", utoa_base(35, 36, buf, sizeof buf));    /* z */
    printf("%s\n", utoa_base(100, 1, buf, sizeof buf));    /* empty: bad base */
    return 0;
}
```

Digits are produced least-significant first, then reversed in place. A 64-bit value needs at most 64 digits in base 2, so `tmp[65]` is safe. Invalid bases and too-small buffers write an empty string instead of overflowing. The `do/while` guarantees `0` renders as `"0"` rather than an empty string.

```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[], &[1, 2]), vec![1, 2]);
    assert_eq!(merge_sorted(&[7], &[]), vec![7]);
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 2]), vec![1, 1, 1, 2, 2]);
    println!("ok");
}
```

Two indices advance while both inputs have elements; the remainder of whichever slice is left is appended after the loop. `<=` keeps the merge stable for equal keys. `Vec::with_capacity` avoids reallocation and the tails are copied with `extend_from_slice`, not element by element.

