```cpp
#include <algorithm>
#include <cctype>
#include <string>

std::string reverseWords(std::string s) {
    // Trim leading/trailing spaces.
    size_t start = s.find_first_not_of(" \t\n");
    if (start == std::string::npos) return "";
    size_t end = s.find_last_not_of(" \t\n");
    s = s.substr(start, end - start + 1);

    // Collapse internal runs of whitespace to a single space.
    std::string compact;
    compact.reserve(s.size());
    bool inSpace = false;
    for (char c : s) {
        if (std::isspace(static_cast<unsigned char>(c))) {
            inSpace = true;
        } else {
            if (inSpace && !compact.empty()) compact.push_back(' ');
            compact.push_back(c);
            inSpace = false;
        }
    }

    // Reverse the whole string, then reverse each word back.
    std::reverse(compact.begin(), compact.end());
    size_t wordStart = 0;
    for (size_t i = 0; i <= compact.size(); ++i) {
        if (i == compact.size() || compact[i] == ' ') {
            std::reverse(compact.begin() + wordStart, compact.begin() + i);
            wordStart = i + 1;
        }
    }
    return compact;
}
```
Reversing everything and then each word individually gives in-place word order reversal; the trim and collapse keep multi-space input from producing empty tokens.

