```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>

class BoundedQueue {
public:
    explicit BoundedQueue(size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(int value) {
        std::unique_lock<std::mutex> lock(m_);
        notFull_.wait(lock, [this] { return q_.size() < cap_ || closed_; });
        if (closed_) return;
        q_.push(value);
        notEmpty_.notify_one();
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(m_);
        notEmpty_.wait(lock, [this] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;
        int v = q_.front();
        q_.pop();
        notFull_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lock(m_);
        closed_ = true;
        notFull_.notify_all();
        notEmpty_.notify_all();
    }

private:
    std::queue<int> q_;
    size_t cap_;
    bool closed_ = false;
    std::mutex m_;
    std::condition_variable notFull_, notEmpty_;
};
```
The condition-variable predicates re-check the state after waking, so spurious wakeups can't push past capacity. `close()` unblocks waiters so consumers can drain and exit.

