template <typename T>
T median(std::vector<T> values) {   // taken by value: sorted locally, caller untouched
    assert(!values.empty());
    std::sort(values.begin(), values.end());
    std::size_t n = values.size();
    if (n % 2 == 1) {
        return values[n / 2];
    }
    return (values[n / 2 - 1] + values[n / 2]) / 2;
}

int main() {
    std::vector<int> odd{5, 1, 3};
    std::vector<int> even{4, 1, 3, 2};
    std::vector<double> frac{1.0, 2.0};

    assert(median(odd) == 3);
    assert(median(even) == 2);          // (2 + 3) / 2
    assert(median(frac) == 1.5);
    assert(odd == (std::vector<int>{5, 1, 3}));  // input unchanged
    std::cout << "ok\n";
}
```

The parameter is by value on purpose: the caller's vector is never reordered, which is usually the surprising part of a median helper. For even sizes the two middle values are averaged; integer division truncates, so `(2 + 3) / 2` is `2`.

