```python
class Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def parse(self):
        value = self.expr()
        self.skip_ws()
        if self.pos != len(self.text):
            raise ValueError(f"unexpected character at {self.pos}: {self.text[self.pos]!r}")
        return value

    def skip_ws(self):
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1

    def peek(self):
        self.skip_ws()
        return self.text[self.pos] if self.pos < len(self.text) else ""

    def expr(self):
        value = self.term()
        while self.peek() in ("+", "-"):
            op = self.text[self.pos]; self.pos += 1
            rhs = self.term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def term(self):
        value = self.factor()
        while self.peek() in ("*", "/"):
            op = self.text[self.pos]; self.pos += 1
            rhs = self.factor()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value /= rhs
        return value

    def factor(self):
        ch = self.peek()
        if ch == "(":
            self.pos += 1
            value = self.expr()
            if self.peek() != ")":
                raise ValueError("missing closing parenthesis")
            self.pos += 1
            return value
        if ch == "-":
            self.pos += 1
            return -self.factor()
        start = self.pos
        self.skip_ws()
        start = self.pos
        while self.pos < len(self.text) and (self.text[self.pos].isdigit() or self.text[self.pos] == "."):
            self.pos += 1
        if start == self.pos:
            raise ValueError(f"expected number at {start}")
        return float(self.text[start:self.pos])


def evaluate(expression):
    if not isinstance(expression, str) or not expression.strip():
        raise ValueError("empty expression")
    return Parser(expression).parse()


if __name__ == "__main__":
    assert evaluate("2 + 3 * 4") == 14.0
    assert evaluate("(2 + 3) * 4") == 20.0
    assert evaluate("-3 + 10 / 2") == 2.0
    assert evaluate("2 * (3 + (4 - 1))") == 12.0
    for bad in ["", "1 +", "(1 + 2", "1 / 0", "2 $ 3"]:
        try:
            evaluate(bad)
        except ValueError:
            continue
        raise AssertionError(f"expected ValueError for {bad!r}")
    print("ok")
```

The grammar is `expr -> term (('+'|'-') term)*`, `term -> factor (('*'|'/') factor)*`, `factor -> number | '(' expr ')' | '-' factor`, which gives `*` and `/` the correct precedence over `+` and `-`. Unknown characters and unbalanced parentheses raise `ValueError` instead of returning a wrong number, and division by zero is caught at the division site.

