/* Reverse s in place. A NULL pointer or empty string is a no-op. */
void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;

    char *left = s;
    char *right = s + len - 1;
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char buf[] = "hello";
    reverse_in_place(buf);
    printf("%s\n", buf); /* olleh */

    char empty[] = "";
    reverse_in_place(empty);
    printf("[%s]\n", empty); /* [] */
    return 0;
}
