pub fn parse_ints(line: &str) -> Result<Vec<i64>, ParseError> {
    let trimmed = line.trim();
    if trimmed.is_empty() {
        return Err(ParseError::Empty);
    }

    let mut out = Vec::new();
    for field in trimmed.split(',') {
        let field = field.trim();
        if field.is_empty() {
            continue;
        }
        match field.parse::<i64>() {
            Ok(v) => out.push(v),
            Err(_) => return Err(ParseError::BadField(field.to_string())),
        }
    }
    Ok(out)
}

