    assert_eq!(parse_ints("1, 2,, 3"), Ok(vec![1, 2, 3]));
    assert_eq!(parse_ints(""), Err(ParseError::Empty));
    assert!(matches!(parse_ints("1,x"), Err(ParseError::BadField(_))));
    println!("ok");
