def flatten(data, *, _str_is_scalar: bool = True):
    """Yield scalars from an arbitrarily nested iterable.

    Strings and bytes are treated as scalars by default so they are not
    split into characters.
    """
    if isinstance(data, (str, bytes)) and _str_is_scalar:
        yield data
        return
    if isinstance(data, Iterable):
        for item in data:
            yield from flatten(item, _str_is_scalar=_str_is_scalar)
    else:
        yield data


