#include <cstdint>
#include <optional>
#include <string>
#include <string_view>

// Parse an optional sign followed by one or more digits.
// Returns std::nullopt on empty input, junk characters, or overflow.
std::optional<int64_t> parse_i64(std::string_view s) {
    if (s.empty()) return std::nullopt;

    bool negative = false;
    std::size_t i = 0;
    if (s[0] == '+' || s[0] == '-') {
        negative = (s[0] == '-');
        i = 1;
        if (i == s.size()) return std::nullopt;
    }

    uint64_t acc = 0;
    const uint64_t limit = negative
        ? static_cast<uint64_t>(INT64_MAX) + 1ULL  // |INT64_MIN|
        : static_cast<uint64_t>(INT64_MAX);

    for (; i < s.size(); ++i) {
        char c = s[i];
        if (c < '0' || c > '9') return std::nullopt;
        uint64_t digit = static_cast<uint64_t>(c - '0');
        if (acc > (limit - digit) / 10ULL) return std::nullopt;
        acc = acc * 10ULL + digit;
    }

    if (negative) {
        // Two's-complement safe negation.
        return static_cast<int64_t>(~acc + 1ULL);
    }
    return static_cast<int64_t>(acc);
}

#include <cassert>
#include <iostream>

int main() {
    assert(parse_i64("0") == 0);
    assert(parse_i64("+42") == 42);
    assert(parse_i64("-42") == -42);
    assert(parse_i64("9223372036854775807") == INT64_MAX);
    assert(parse_i64("9223372036854775808") == std::nullopt);
    assert(parse_i64("-9223372036854775808") == INT64_MIN);
    assert(parse_i64("-9223372036854775809") == std::nullopt);
    assert(parse_i64("") == std::nullopt);
    assert(parse_i64("12a") == std::nullopt);
    assert(parse_i64("+") == std::nullopt);
    std::cout << "ok\n";
}
```
The check `acc > (limit - digit) / 10` is done before each multiply-add, so no intermediate ever wraps. Using the unsigned magnitude for INT64_MIN avoids the undefined `-INT64_MAX - 1`.

```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    BoundedQueue(const BoundedQueue&) = delete;
    BoundedQueue& operator=(const BoundedQueue&) = delete;

    // Blocks while full. Returns false if closed first.
    bool push(T value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [&] { return q_.size() < cap_ || closed_; });
        if (closed_) return false;
        q_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }

    // Blocks while empty. Returns nullopt once closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [&] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;
        T value = std::move(q_.front());
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::queue<T> q_;
    std::size_t cap_;
    bool closed_ = false;
    std::mutex mu_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
};
```
The predicates re-check on every wake, so a spurious wakeup or a consumer stealing a slot cannot overflow the buffer. `close()` wakes both waits, letting producers and consumers exit cleanly after drain.

```rust
/// Edit distance using two rolling rows of the DP table, O(m*n) time and
/// O(min(m,n)) memory. Works on `char` units so it is UTF-8 safe.
pub fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();

    // Iterate over the shorter string as the inner loop.
    let (a, b) = if a.len() < b.len() { (a, b) } else { (b, a) };

    if a.is_empty() {
        return b.len();
    }

    let mut prev: Vec<usize> = (0..=a.len()).collect();
    let mut cur = vec![0usize; a.len() + 1];

    for (j, &cb) in b.iter().enumerate() {
        cur[0] = j + 1;
        for (i, &ca) in a.iter().enumerate() {
            let cost = if ca == cb { 0 } else { 1 };
            cur[i + 1] = (prev[i + 1] + 1)          // deletion
                .min(cur[i] + 1)                    // insertion
                .min(prev[i] + cost);               // substitution
        }
        std::mem::swap(&mut prev, &mut cur);
    }

    prev[a.len()]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basics() {
        assert_eq!(levenshtein("", ""), 0);
        assert_eq!(levenshtein("", "abc"), 3);
        assert_eq!(levenshtein("kitten", "sitting"), 3);
        assert_eq!(levenshtein("flaw", "lawn"), 2);
        assert_eq!(levenshtein("abc", "abc"), 0);
    }

    #[test]
    fn unicode() {
        // Multi-byte characters count as single edits.
        assert_eq!(levenshtein("café", "cafe"), 1);
        assert_eq!(levenshtein("日本", "日"), 1);
    }
}
```
Collecting into `Vec<char>` before comparing makes the multi-byte case count one edit per character, not per byte. Swapping so the inner loop scans the shorter string keeps the aux memory at O(min(m,n)).

```rust
use std::collections::HashMap;

/// A capacity-bounded LRU cache. Keys map to indices into a slab-like
/// arena of nodes so we avoid fighting the borrow checker on a raw list.
pub struct LruCache<K, V> {
    map: HashMap<K, usize>,
    keys: Vec<Option<K>>,
    vals: Vec<Option<V>>,
    prev: Vec<Option<usize>>,
    next: Vec<Option<usize>>,
    free: Vec<usize>,
    head: Option<usize>,
    tail: Option<usize>,
    cap: usize,
}

impl<K: std::hash::Hash + Eq + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache {
            map: HashMap::new(),
            keys: Vec::new(),
            vals: Vec::new(),
            prev: Vec::new(),
            next: Vec::new(),
            free: Vec::new(),
            head: None,
            tail: None,
            cap,
        }
    }

    pub fn len(&self) -> usize {
        self.map.len()
    }

    pub fn is_empty(&self) -> bool {
        self.map.is_empty()
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        let idx = *self.map.get(key)?;
        self.detach(idx);
        self.attach_front(idx);
        self.vals[idx].as_ref()
    }

    pub fn put(&mut self, key: K, value: V) {
        if let Some(&idx) = self.map.get(&key) {
            self.vals[idx] = Some(value);
            self.detach(idx);
            self.attach_front(idx);
            return;
        }
        if self.map.len() == self.cap {
            if let Some(t) = self.tail {
                self.detach(t);
                let old_key = self.keys[t].take().unwrap();
                self.vals[t] = None;
                self.map.remove(&old_key);
                self.free.push(t);
            }
        }
        let idx = self.free.pop().unwrap_or_else(|| {
            self.keys.push(None);
            self.vals.push(None);
            self.prev.push(None);
            self.next.push(None);
            self.keys.len() - 1
        });
        self.keys[idx] = Some(key.clone());
        self.vals[idx] = Some(value);
        self.prev[idx] = None;
        self.next[idx] = None;
        self.attach_front(idx);
        self.map.insert(key, idx);
    }

    fn detach(&mut self, idx: usize) {
        let (p, n) = (self.prev[idx], self.next[idx]);
        match p {
            Some(p) => self.next[p] = n,
            None => self.head = n,
        }
        match n {
            Some(n) => self.prev[n] = p,
            None => self.tail = p,
        }
    }

    fn attach_front(&mut self, idx: usize) {
        self.prev[idx] = None;
        self.next[idx] = self.head;
        if let Some(h) = self.head {
            self.prev[h] = Some(idx);
        }
        self.head = Some(idx);
        if self.tail.is_none() {
            self.tail = Some(idx);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn evicts_lru() {
        let mut c = LruCache::new(2);
        c.put("a", 1);
        c.put("b", 2);
        assert_eq!(c.get(&"a"), Some(&1)); // 'a' becomes most recent
        c.put("c", 3);                    // evicts 'b'
        assert_eq!(c.get(&"b"), None);
        assert_eq!(c.get(&"a"), Some(&1));
        assert_eq!(c.get(&"c"), Some(&3));
    }

    #[test]
    fn updates_in_place() {
        let mut c = LruCache::new(1);
        c.put("x", 1);
        c.put("x", 2);
        assert_eq!(c.get(&"x"), Some(&2));
        assert_eq!(c.len(), 1);
    }
}
```
The arena of `Vec<Option<...>>` plus free-list keeps the Rust borrow checker happy without `Rc<RefCell<>>` or unsafe. `get` promotes on hit; `put` on an existing key updates and promotes, otherwise evicts the tail.

