std::string reverseWords(std::string s) {
    // Normalise: trim outer spaces and collapse internal runs to one space.
    std::string t;
    bool inWord = false;
    for (char c : s) {
        if (std::isspace(static_cast<unsigned char>(c))) {
            inWord = false;
        } else {
            if (!inWord && !t.empty()) t.push_back(' ');
            t.push_back(c);
            inWord = true;
        }
    }

    // Reverse the whole string, then reverse each word back.
    std::reverse(t.begin(), t.end());
    std::size_t i = 0, n = t.size();
    while (i < n) {
        std::size_t j = i;
        while (j < n && t[j] != ' ') ++j;
        std::reverse(t.begin() + static_cast<long>(i), t.begin() + static_cast<long>(j));
        i = j + 1;
    }
    return t;
}

int main() {
    for (const std::string& s : {"the sky is blue", "  hello   world  ", "", "one"}) {
        std::cout << '[' << reverseWords(s) << "]\n";
    }
    return 0;
}
