constexpr std::int64_t MOD = 1000000007;

// Returns {F(n), F(n+1)} mod MOD.
std::pair<std::int64_t, std::int64_t> fibPair(std::int64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fibPair(n >> 1);            // {F(k), F(k+1)}, k = n/2
    std::int64_t c = a * ((2 * b % MOD - a + MOD) % MOD) % MOD; // F(2k)
    std::int64_t d = (a * a % MOD + b * b % MOD) % MOD;         // F(2k+1)
    if (n & 1) return {d, (c + d) % MOD};
    return {c, d};
}

std::int64_t fib(std::int64_t n) { return fibPair(n).first; }

int main() {
    for (std::int64_t n = 0; n <= 10; ++n) std::cout << fib(n) << ' ';
    std::cout << '\n';
    std::cout << fib(90) << '\n'; // fits in int64 before mod
    return 0;
