pub fn longest_common_prefix(strs: &[String]) -> String {
    if strs.is_empty() {
        return String::new();
    }
    let first = strs[0].as_bytes();
    let mut end = first.len();
    for s in &strs[1..] {
        let b = s.as_bytes();
        let mut i = 0;
        while i < end && i < b.len() && first[i] == b[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    String::from_utf8_lossy(&first[..end]).into_owned()
}

