use std::collections::BinaryHeap;
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut low: BinaryHeap<i64> = BinaryHeap::new();          // max-heap
    let mut high: BinaryHeap<Reverse<i64>> = BinaryHeap::new(); // min-heap

