#include <ctype.h>
#include <stdio.h>
#include <string.h>

#define MAX_LINE 512

static char *trim(char *s) {
    while (*s && isspace((unsigned char)*s)) s++;
    char *end = s + strlen(s);
    while (end > s && isspace((unsigned char)end[-1])) *--end = '\0';
    return s;
}

int main(void) {
    const char *cfg =
        "# comment\n"
        "host = example.com\n"
        "\n"
        "port=8080\n"
        "empty=\n";

    char line[MAX_LINE];
    const char *cursor = cfg;
    while (*cursor) {
        const char *nl = strchr(cursor, '\n');
        size_t len = nl ? (size_t)(nl - cursor) : strlen(cursor);
        if (len >= sizeof line) len = sizeof line - 1;
        memcpy(line, cursor, len);
        line[len] = '\0';
        cursor = nl ? nl + 1 : cursor + len;

        char *p = trim(line);
        if (*p == '\0' || *p == '#') continue;
        char *eq = strchr(p, '=');
        if (!eq) {
            fprintf(stderr, "skipping malformed line: %s\n", p);
            continue;
        }
        *eq = '\0';
        char *key = trim(p);
        char *val = trim(eq + 1);
        printf("key=[%s] value=[%s]\n", key, val);
    }
    return 0;
}
