```python
from typing import Generic, Iterator, List, Optional, TypeVar

T = TypeVar("T")


class RingBuffer(Generic[T]):
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._cap = capacity
        self._buf: List[Optional[T]] = [None] * capacity
        self._start = 0
        self._size = 0

    def append(self, item: T) -> None:
        end = (self._start + self._size) % self._cap
        self._buf[end] = item
        if self._size < self._cap:
            self._size += 1
        else:
            self._start = (self._start + 1) % self._cap

    def get(self, index: int) -> T:
        if not 0 <= index < self._size:
            raise IndexError(index)
        value = self._buf[(self._start + index) % self._cap]
        assert value is not None
        return value

    def __len__(self) -> int:
        return self._size

    def __iter__(self) -> Iterator[T]:
        for i in range(self._size):
            yield self.get(i)


if __name__ == "__main__":
    rb: RingBuffer[int] = RingBuffer(3)
    assert len(rb) == 0
    for v in (1, 2, 3):
        rb.append(v)
    assert list(rb) == [1, 2, 3]
    rb.append(4)
    assert list(rb) == [2, 3, 4]
    rb.append(5)
    rb.append(6)
    assert list(rb) == [4, 5, 6]
    assert rb.get(0) == 4 and rb.get(2) == 6
    print("ok")
