```cpp
#include <cctype>
#include <iostream>
#include <string>

bool is_palindrome(const std::string& s) {
    std::size_t i = 0;
    std::size_t j = s.size();
    while (i < j) {
        // Skip non-alphanumeric characters from the left.
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[i]))) ++i;
        // Skip from the right; j is one past the last unexamined char.
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[j - 1]))) --j;
        if (i >= j) break;
        char a = static_cast<char>(std::tolower(static_cast<unsigned char>(s[i])));
        char b = static_cast<char>(std::tolower(static_cast<unsigned char>(s[j - 1])));
        if (a != b) return false;
        ++i;
        --j;
    }
    return true;
}

int main() {
    const char* tests[] = {
        "A man, a plan, a canal: Panama",
        "race a car",
        "",
        "...",
        "Was it a car or a cat I saw?",
    };
    for (const char* t : tests) {
        std::cout << (is_palindrome(t) ? "true  " : "false ") << t << '\n';
    }
    return 0;
}
```

The `unsigned char` casts are required before passing to `isalnum`/`tolower`, since passing a negative `char` is undefined behaviour. Empty and punctuation-only strings return `true` because the two indices cross with nothing to compare.

```cpp
#include <cassert>
#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse_list(Node* head) {
    Node* prev = nullptr;
    Node* cur = head;
    while (cur != nullptr) {
        Node* next = cur->next;  // save before rewiring
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

int main() {
    // Build 1 -> 2 -> 3 -> 4
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(4);

    head = reverse_list(head);
    int expected = 4;
    for (Node* p = head; p != nullptr; p = p->next) {
        assert(p->value == expected);
        --expected;
    }
    assert(expected == 0);

    // Reverse the empty list.
    assert(reverse_list(nullptr) == nullptr);

    while (head != nullptr) {
        Node* dead = head;
        head = head->next;
        delete dead;
    }
    std::cout << "ok\n";
    return 0;
}
```

Saving `cur->next` before rewiring `cur->next = prev` is the key detail: without it the rest of the list would be lost. The loop ends with `prev` pointing at the new head, which becomes the return value.

