#include <cstddef>
#include <iostream>
#include <stdexcept>

template <typename T>
class DynArray {
public:
    DynArray() : data_(nullptr), size_(0), cap_(0) {}
    ~DynArray() { delete[] data_; }

    DynArray(const DynArray&) = delete;
    DynArray& operator=(const DynArray&) = delete;

    void push_back(const T& value) {
        if (size_ == cap_) grow(cap_ == 0 ? 1 : cap_ * 2);
        data_[size_++] = value;
    }

    T& at(std::size_t i) {
        if (i >= size_) throw std::out_of_range("index out of range");
        return data_[i];
    }

    std::size_t size() const { return size_; }

private:
    void grow(std::size_t new_cap) {
        T* fresh = new T[new_cap];
        for (std::size_t i = 0; i < size_; ++i) fresh[i] = data_[i];
        delete[] data_;
        data_ = fresh;
        cap_ = new_cap;
    }

    T* data_;
    std::size_t size_;
    std::size_t cap_;
};

int main() {
    DynArray<int> a;
    for (int i = 0; i < 5; ++i) a.push_back(i * 10);
    std::cout << a.size() << "\n";
    std::cout << a.at(2) << "\n";
    try {
        a.at(5);
    } catch (const std::out_of_range& e) {
        std::cout << e.what() << "\n";
    }
    return 0;
}
