/* Copies src into dst (capacity cap), truncating if needed.
   Returns the number of bytes written excluding the null terminator,
   or -1 on invalid arguments. dst is always null-terminated when cap > 0. */
long safe_copy(char *dst, size_t cap, const char *src) {
    if (dst == NULL || src == NULL || cap == 0) return -1;

    size_t i = 0;
    while (i + 1 < cap && src[i] != '\0') {
        dst[i] = src[i];
        ++i;
    }
    dst[i] = '\0';
    return (long)i;
}

int main(void) {
