    printf("n=%ld str=%s\n", n, buf);

    n = safe_copy(buf, sizeof buf, "hello world");
    printf("n=%ld str=%s\n", n, buf);

    n = safe_copy(buf, sizeof buf, "");
    printf("n=%ld str=%s\n", n, buf);

    printf("zero cap=%ld\n", safe_copy(buf, 0, "x"));
    printf("null src=%ld\n", safe_copy(buf, sizeof buf, NULL));

    if ((size_t)n > sizeof buf) return 1;
    return 0;
