template <typename T>
void dedupe_adjacent(std::vector<T>& v) {
    std::vector<T> out;
    out.reserve(v.size());
    for (const auto& x : v) {
        if (out.empty() || out.back() != x) out.push_back(x);
    }
    v.swap(out);
}

