#include <stdio.h>
#include <string.h>
#include <ctype.h>

static void reverse(char *a, char *b) {
    while (a < b) {
        char t = *a; *a++ = *b; *b-- = t;
    }
}

void reverse_words(char *s) {
    size_t n = strlen(s);
    reverse(s, s + n - 1);              /* whole string */
    char *w = s;
    for (char *p = s; ; ++p) {
        if (*p == ' ' || *p == '\0') {
            reverse(w, p - 1);          /* each word back */
            if (*p == '\0') break;
            w = p + 1;
        }
    }
}

int main(void) {
    char s[] = "  hello   world  ";
    reverse_words(s);
    printf("[%s]\n", s);   /* [  world   hello  ] */
    char e[] = "";
    reverse_words(e);       /* no-op */
    printf("[%s]\n", e);
    return 0;
}
