Two-pass: reverse the whole buffer, then reverse each space-delimited word. Consecutive spaces produce empty runs whose reverse is a no-op, so spacing is preserved. `n == 0` must be excluded before `s + n - 1`; the caller passes non-empty strings here.

Here's an expand-around-center solution in O(n^2) time and O(1) space, plus a self-test:

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(lo: int, hi: int) -> tuple[int, int]:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    cases = [("babad", {"bab", "aba"}), ("cbbd", {"bb"}), ("", {""}),
             ("a", {"a"}), ("abacdfgdcaba", {"aba"}), ("aaaa", {"aaaa"})]
    for text, expected in cases:
        got = longest_palindrome(text)
        assert got in expected, f"{text!r} -> {got!r}, expected one of {expected}"
    print("all tests passed")
```

It handles the empty string, single characters, and even-length centers; ties return the first center found, which is why the test accepts a set of valid answers.

A self-contained word-frequency counter with a basic hash table and qsort:

```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAP 4096
#define MAXWORD 128

typedef struct { char *word; long count; } Entry;

static Entry table[CAP];
static size_t used = 0;

static unsigned long hash(const char *s) {
    unsigned long h = 5381;
    while (*s) h = h * 33 + (unsigned char)*s++;
    return h;
}

static int cmp(const void *a, const void *b) {
    const Entry *x = a, *y = b;
    return strcmp(x->word, y->word);
}

int main(void) {
    char word[MAXWORD];
    int c;
    size_t len = 0;

    while ((c = getchar()) != EOF) {
        if (isalpha(c) || c == '\'') {
            if (len + 1 < MAXWORD) word[len++] = (char)tolower(c);
        } else if (len > 0) {
            word[len] = '\0';
            size_t idx = hash(word) % CAP;
            while (table[idx].word) {
                if (strcmp(table[idx].word, word) == 0) {
                    table[idx].count++;
                    goto next;
                }
                idx = (idx + 1) % CAP;
            }
            table[idx].word = strdup(word);
            table[idx].count = 1;
            used++;
next:
            len = 0;
        }
    }

    Entry out[CAP];
    size_t n = 0;
    for (size_t i = 0; i < CAP; i++)
        if (table[i].word) out[n++] = table[i];

    qsort(out, n, sizeof(Entry), cmp);
    for (size_t i = 0; i < n; i++)
        printf("%s %ld\n", out[i].word, out[i].count);
    return 0;
}
```

Edge handling: empty input prints nothing; words longer than 127 chars are truncated rather than overflowing; apostrophes are kept so "don't" stays one token. Compile with `cc -O2 -Wall -o wf wf.c`.

