```rust
fn eval_rpn(expr: &str) -> Result<f64, String> {
    let mut stack: Vec<f64> = Vec::new();
    for token in expr.split_whitespace() {
        match token {
            "+" | "-" | "*" | "/" => {
                let b = stack.pop().ok_or("missing operand")?;
                let a = stack.pop().ok_or("missing operand")?;
                let v = match token {
                    "+" => a + b,
                    "-" => a - b,
                    "*" => a * b,
                    _ => {
                        if b == 0.0 {
                            return Err("division by zero".into());
                        }
                        a / b
                    }
                };
                stack.push(v);
            }
            _ => {
                let n: f64 = token
                    .parse()
                    .map_err(|_| format!("invalid token: {token}"))?;
                stack.push(n);
            }
        }
    }
    match stack.as_slice() {
        [only] => Ok(*only),
        [] => Err("empty expression".into()),
        _ => Err(format!("{} leftover values on stack", stack.len())),
    }
}

fn main() {
    assert_eq!(eval_rpn("3 4 + 2 *").unwrap(), 14.0);
    assert_eq!(eval_rpn("5").unwrap(), 5.0);
    assert!(eval_rpn("1 2 +").is_ok());
    assert!(eval_rpn("1 +").is_err());
    assert!(eval_rpn("").is_err());
    assert!(eval_rpn("1 0 /").is_err());
    println!("all checks passed");
}
```

Error cases are explicit: missing operands, invalid tokens, division by zero, and leftover stack values. The final match on `stack.as_slice()` catches expressions that never reduce to a single value.

