#include <cassert>
#include <climits>
#include <iostream>
#include <optional>
#include <string>

std::optional<long long> parse_int(const std::string& s) {
    size_t i = 0;
    bool negative = false;
    if (i < s.size() && (s[i] == '+' || s[i] == '-')) {
        negative = s[i] == '-';
        i++;
    }
    if (i == s.size()) return std::nullopt;

    long long value = 0;
    for (; i < s.size(); i++) {
        char c = s[i];
        if (c < '0' || c > '9') return std::nullopt;
        int digit = c - '0';
        if (value > (LLONG_MAX - digit) / 10) return std::nullopt;  // would overflow
        value = value * 10 + digit;
    }
    if (negative) {
        if (value > -(long long)LLONG_MIN) return std::nullopt;
        value = -value;
    }
    return value;
}

int main() {
    assert(parse_int("0") == 0);
    assert(parse_int("-42") == -42);
    assert(parse_int("+17") == 17);
    assert(!parse_int("").has_value());
    assert(!parse_int("-").has_value());
    assert(!parse_int("12x3").has_value());
    assert(!parse_int("\t5").has_value());
    assert(parse_int("9223372036854775807").has_value());
    assert(!parse_int("9223372036854775808").has_value());
    std::cout << "ok\n";
}
```

The overflow guard `value > (LLONG_MAX - digit) / 10` is checked *before* multiplying so it never wraps. Leading/trailing whitespace is rejected rather than silently trimmed, which is a deliberate choice you can loosen with a `trim` if you want.

