    }

    ~FileHandle() { close(); }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fp_(other.fp_) {
        other.fp_ = nullptr;
    }

    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            close();
            fp_ = other.fp_;
            other.fp_ = nullptr;
        }
        return *this;
    }

    std::FILE* get() const { return fp_; }
    explicit operator bool() const { return fp_ != nullptr; }

private:
    void close() {
        if (fp_) {
            std::fclose(fp_);
            fp_ = nullptr;
        }
    }

    std::FILE* fp_ = nullptr;
};
```

Copying is deleted so the handle can't be double-closed. The move constructor and move assignment both null out the source, and `close()` is idempotent, so the destructor is safe after a move.

