#include <cstddef>
#include <iostream>
#include <vector>

std::size_t remove_duplicates(std::vector<int>& nums) {
    if (nums.empty()) return 0;
    std::size_t write = 1;
    for (std::size_t read = 1; read < nums.size(); ++read) {
        if (nums[read] != nums[write - 1]) {
            nums[write++] = nums[read];
        }
    }
    nums.resize(write);
    return write;
}

int main() {
    std::vector<int> a{1, 1, 2, 3, 3, 3, 4};
    std::size_t n = remove_duplicates(a);
    std::cout << n << ":";
    for (int v : a) std::cout << " " << v;
    std::cout << "\n";   // 4: 1 2 3 4

    std::vector<int> empty;
    std::cout << remove_duplicates(empty) << "\n";  // 0
    return 0;
}
```

A single read pointer scans while a write pointer trails behind, copying only values that differ from the last kept one. `resize` trims the tail in place; an empty vector returns 0 without touching memory.

