    reverseInPlace(a);
    std::cout << a << "\n";  // olleh

    std::string b = "";
    reverseInPlace(b);
    std::cout << "[" << b << "]\n";  // []

    std::string c = "ab";
    reverseInPlace(c);
    std::cout << c << "\n";  // ba
    return 0;
}
