```python
def search_rotated(nums: list[int], target: int) -> bool:
    """Return True if target is present in a rotated sorted array (may have dupes)."""
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return True

        if nums[lo] == nums[mid] == nums[hi]:
            # Cannot decide which half is sorted; shrink both ends.
            lo += 1
            hi -= 1
        elif nums[lo] <= nums[mid]:
            # Left half is sorted.
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            # Right half is sorted.
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return False


if __name__ == "__main__":
    print(search_rotated([2, 5, 6, 0, 0, 1, 2], 0))   # True
    print(search_rotated([2, 5, 6, 0, 0, 1, 2], 3))   # False
    print(search_rotated([1, 1, 1, 1], 1))             # True
    print(search_rotated([], 5))                       # False
```

With duplicates you can hit a case where both ends and the middle are equal, so the sorted half is unknown. The algorithm handles that by shrinking the window by one from each side, which keeps it correct and degrades to O(n) only in the worst case.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) {
        perror("malloc");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(const Node *head) {
    for (; head; head = head->next)
        printf("%d%s", head->value, head->next ? " -> " : "\n");
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++)
        head = push(head, i);

    print_list(head);
    head = reverse(head);
    print_list(head);
    free_list(head);
    return 0;
}
```

The reverse walks the list once, flipping each `next` pointer while tracking the previous node. Reversing an empty or single-node list works without special cases, and `free_list` avoids leaks after the final print.

