```cpp
#include <condition_variable>
#include <cstddef>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>
#include <thread>
#include <vector>
#include <iostream>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be > 0");
        }
    }

    // Blocks while the queue is full. Returns false if closed.
    bool push(T value) {
        std::unique_lock<std::mutex> lock(m_);
        not_full_.wait(lock, [this] { return closed_ || q_.size() < capacity_; });
        if (closed_) {
            return false;
        }
        q_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }

    // Blocks while empty. Returns std::nullopt if closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(m_);
        not_empty_.wait(lock, [this] { return closed_ || !q_.empty(); });
        if (q_.empty()) {
            return std::nullopt;  // closed and nothing left
        }
        T value = std::move(q_.front());
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(m_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    const std::size_t capacity_;
    std::queue<T> q_;
    std::mutex m_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
    bool closed_ = false;
};

int main() {
    BoundedQueue<int> queue(4);
    std::vector<int> received;
    std::mutex out_m;

    std::thread producer([&] {
        for (int i = 0; i < 20; ++i) {
            if (!queue.push(i)) break;
        }
        queue.close();
    });

    std::vector<std::thread> consumers;
    for (int c = 0; c < 3; ++c) {
        consumers.emplace_back([&] {
            while (auto v = queue.pop()) {
                std::lock_guard<std::mutex> lock(out_m);
                received.push_back(*v);
            }
        });
    }

    producer.join();
    for (auto& t : consumers) t.join();

    std::cout << "received " << received.size() << " items\n";
    if (received.size() != 20) {
        std::cerr << "expected 20 items\n";
        return 1;
    }
    return 0;
}
```

Design points:

- **Two condition variables** (`not_empty_`, `not_full_`) so a push wakes only a consumer and a pop wakes only a producer — no thundering herd on every operation.
- **Predicate-based `wait`** guards against spurious wakeups; the loop inside `condition_variable::wait` checks `closed_` too, which is what lets `close()` unblock everyone.
- **Unlock before `notify_*`.** The waiting thread has to re-acquire the mutex anyway; notifying while holding it just forces an immediate context switch back to sleep.
- **Shutdown semantics:** `close()` sets the flag and wakes all waiters. `push` returns `false` on a closed queue, `pop` returns `std::nullopt` once drained. That gives producers and consumers a clean exit instead of hanging forever.

Compile with `g++ -std=c++17 -O2 -pthread bounded_queue.cpp -o bounded_queue`.

```cpp
#include <cstdio>
#include <string>
#include <system_error>
#include <iostream>

// Reads an entire file into out. Returns false and sets ec on failure.
bool read_file(const std::string& path, std::string& out, std::error_code& ec) {
    out.clear();
    ec.clear();

    std::FILE* f = std::fopen(path.c_str(), "rb");
    if (f == nullptr) {
        ec = std::error_code(errno, std::generic_category());
        return false;
    }

    // Reserve generously to avoid repeated reallocation on growth.
    std::fseek(f, 0, SEEK_END);
    long size = std::ftell(f);
    std::fseek(f, 0, SEEK_SET);
    if (size > 0) {
        out.reserve(static_cast<std::size_t>(size));
    }

    char buf[1 << 16];
    std::size_t n;
    while ((n = std::fread(buf, 1, sizeof(buf), f)) > 0) {
        out.append(buf, n);
    }

    if (std::ferror(f)) {
        ec = std::error_code(errno, std::generic_category());
        std::fclose(f);
        return false;
    }
    std::fclose(f);
    return true;
}

int main() {
    std::error_code ec;
    std::string content;

    if (!read_file("input.txt", content, ec)) {
        std::cerr << "read failed: " << ec.message() << '\n';
        return 1;
    }
    std::cout << "read " << content.size() << " bytes\n";
    return 0;
}
```

**Buffer growth strategy.** `std::string` doubles its capacity when `append` would exceed the current allocation (the exact factor is implementation-defined, but libstdc++ and libc++ both use 2x for the doubling path). Doubling keeps the amortised cost per byte at O(1): total copying across n bytes of growth is about 2n, not n².

Two guardrails here avoid the worst of it:

1. **`reserve(size)`** — `ftell` after `SEEK_END` gives the file length on regular files, so we allocate once. This is a heuristic: on pipes, `/proc` files, or anything where `ftell` returns negative/zero, the reserve is skipped and we fall back to growth.
2. **Fixed 64 KiB read buffer** — we read in chunks and `append` them, so peak memory is the file size plus one chunk, regardless of file size. Reading straight into a `std::string` of the whole size would need the length to be known and exact up front.

`ftell` is only trustworthy for seekable files; for a growing file or a stream, the doubling path is what you actually rely on. Compile with `g++ -std=c++17 -O2 read_file.cpp -o read_file`.

```rust
use std::error::Error;

/// Parses a comma-separated list of integers.
/// Valid entries are collected in order; invalid ones are counted and skipped.
fn parse_numbers(input: &str) -> (Vec<i64>, usize) {
    let mut numbers = Vec::new();
    let mut skipped = 0usize;

    for field in input.split(',') {
        let trimmed = field.trim();
        if trimmed.is_empty() {
            skipped += 1;
            continue;
        }
        match trimmed.parse::<i64>() {
            Ok(n) => numbers.push(n),
            Err(_) => skipped += 1,
        }
    }

    (numbers, skipped)
}

fn main() -> Result<(), Box<dyn Error>> {
    let cases = [
        ("1,2,3", vec![1, 2, 3], 0),
        (" 10 , 20 ", vec![10, 20], 0),
        ("1,,2,abc,-3,999999999999999999999", vec![1, 2, -3], 3),
        ("", vec![], 1),
        (",,,", vec![], 4),
    ];

    for (input, expected_numbers, expected_skipped) in cases {
        let (numbers, skipped) = parse_numbers(input);
        // The last case has no valid numbers, and the empty string case too.
        assert_eq!(numbers, expected_numbers, "input = {input:?}");
        assert_eq!(skipped, expected_skipped, "input = {input:?}");
        println!("input={input:?} -> {numbers:?} (skipped {skipped})");
    }

    Ok(())
}
```

Behaviour detail worth knowing:

- `"a,b".split(',')` always yields at least one element, even for the empty string — that's why `""` counts as **one** skipped entry, not zero. If you'd rather treat empty input as "no attempts", add an early `if input.is_empty() { return (vec![], 0); }`.
- `i64::from_str` accepts an optional leading `+` or `-` and rejects whitespace, which is why the `trim()` happens first. The overflow case (`999999999999999999999`) returns `Err` and increment the skip counter rather than panicking.
- Returning `(Vec<i64>, usize)` instead of `Result` keeps the "partial success" contract explicit: you get everything that parsed plus a count of what didn't. Callers can decide whether a nonzero skip count is fatal.

`cargo run` prints each case and the asserts guard the edge cases, including the overlong literal.

```rust
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

// Intrusive doubly linked list node.
struct Node<K, V> {
    key: K,
    value: V,
    prev: Option<Rc<RefCell<Node<K, V>>>>,
    next: Option<Rc<RefCell<Node<K, V>>>>,
}

pub struct LruCache<K, V> {
    capacity: usize,
    map: HashMap<K, Rc<RefCell<Node<K, V>>>>,
    head: Option<Rc<RefCell<Node<K, V>>>>, // most recently used
    tail: Option<Rc<RefCell<Node<K, V>>>>, // least recently used
}

impl<K: std::hash::Hash + Eq + Clone, V: Clone> LruCache<K, V> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        Self { capacity, map: HashMap::new(), head: None, tail: None }
    }

    pub fn get(&mut self, key: &K) -> Option<V> {
        match self.map.get(key).cloned() {
            Some(node) => {
                self.detach(&node);
                self.push_front(&node);
                Some(node.borrow().value.clone())
            }
            None => None,
        }
    }

    pub fn put(&mut self, key: K, value: V) {
        if let Some(node) = self.map.get(&key).cloned() {
            node.borrow_mut().value = value;
            self.detach(&node);
            self.push_front(&node);
            return;
        }

        if self.map.len() == self.capacity {
            if let Some(oldest) = self.tail.take() {
                self.detach(&oldest);
                let k = oldest.borrow().key.clone();
                self.map.remove(&k);
            }
        }

        let node = Rc::new(RefCell::new(Node {
            key: key.clone(),
            value,
            prev: None,
            next: None,
        }));
        self.map.insert(key, node.clone());
        self.push_front(&node);
    }

    fn detach(&mut self, node: &Rc<RefCell<Node<K, V>>>) {
        let (prev, next) = {
            let n = node.borrow();
            (n.prev.clone(), n.next.clone())
        };
        match prev.clone() {
            Some(p) => p.borrow_mut().next = next.clone(),
            None => self.head = next.clone(),
        }
        match next.clone() {
            Some(n) => n.borrow_mut().prev = prev.clone(),
            None => self.tail = prev.clone(),
        }
        let mut n = node.borrow_mut();
        n.prev = None;
        n.next = None;
    }

    fn push_front(&mut self, node: &Rc<RefCell<Node<K, V>>>) {
        node.borrow_mut().prev = None;
        node.borrow_mut().next = self.head.clone();
        if let Some(old_head) = self.head.clone() {
            old_head.borrow_mut().prev = Some(node.clone());
        }
        self.head = Some(node.clone());
        if self.tail.is_none() {
            self.tail = Some(node.clone());
        }
    }
}

fn main() {
    let mut cache: LruCache<&str, i32> = LruCache::new(2);
    cache.put("a", 1);
    cache.put("b", 2);
    assert_eq!(cache.get(&"a"), Some(1)); // 'a' is now most recent
    cache.put("c", 3);                   // evicts 'b'
    assert_eq!(cache.get(&"b"), None);
    assert_eq!(cache.get(&"a"), Some(1));
    assert_eq!(cache.get(&"c"), Some(3));
    println!("lru ok");
}
```

Why both structures? The `HashMap` gives O(1) lookup from key to node. The doubly linked list gives O(1) move-to-front and O(1) eviction from the tail — a `VecDeque` or a plain `Vec` would make one of those O(n). `RefCell` is only needed because the list owns nodes through `Rc` and we mutate `prev`/`next` through shared handles; this is single-threaded by construction.

`detach` reads `prev`/`next` into locals before mutating, so the two `borrow_mut` calls never overlap and can't panic with `BorrowMutError`. Putting an existing key updates the value *and* refreshes recency — the common omission that makes a cache subtly wrong.

Caveats: this uses `Rc` so it's not `Send`; for a multi-threaded cache use `Arc<Mutex<...>>` or, in practice, the `lru` crate. `cargo run` exercises eviction and recency.

