    bool push(int value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;              // full
    if (rb.pop() != 1) return 1;
    if (!rb.push(4)) return 1;             // wraps
    if (rb.pop() != 2 || rb.pop() != 3 || rb.pop() != 4) return 1;
    if (rb.pop().has_value()) return 1;    // empty
    std::printf("ok\n");
    return 0;
}
