#include <cstddef>
#include <cstdio>
#include <vector>

int binary_search(const std::vector<int>& a, int target) {
    std::size_t lo = 0, hi = a.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (a[mid] < target) {
            lo = mid + 1;
        } else if (a[mid] > target) {
            hi = mid;
        } else {
            return static_cast<int>(mid);
        }
    }
    return -1;
}

int main() {
    std::vector<int> a = {1, 2, 2, 2, 5, 9};
    int idx = binary_search(a, 2);
    std::printf("idx=%d val=%d\n", idx, a[idx]);
    std::printf("missing=%d\n", binary_search(a, 7));  // -1
    std::printf("empty=%d\n", binary_search(std::vector<int>{}, 3));  // -1
    return 0;
}
```

