```cpp
#include <cstddef>
#include <stdexcept>
#include <iostream>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

    void push(const T& value) {
        if (full()) throw std::overflow_error("ring buffer full");
        data_[(head_ + size_) % N] = value;
        ++size_;
    }

    T pop() {
        if (empty()) throw std::underflow_error("ring buffer empty");
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

private:
    T data_[N]{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1);
    rb.push(2);
    rb.push(3);
    std::cout << rb.full() << '\n';          // 1
    std::cout << rb.pop() << '\n';           // 1
    rb.push(4);
    std::cout << rb.pop() << '\n';           // 2
    std::cout << rb.size() << '\n';          // 2
    return 0;
}
```

The modulo arithmetic on `head_` and `size_` wraps indices without needing a spare sentinel slot. `full()` and `empty()` are distinguished by `size_`, so capacity `N` stores exactly `N` elements.

