use std::collections::HashMap;

fn top_k_words(text: &str, k: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text
        .split(|c: char| !c.is_alphanumeric())
        .filter(|w| !w.is_empty())
    {
        *counts.entry(word.to_lowercase()).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count desc, then word asc for deterministic output.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(k);
    pairs
}

fn main() {
    let text = "The quick brown fox. The FOX, the dog!";
    for (w, c) in top_k_words(text, 2) {
        println!("{}: {}", w, c);
    }
}
```

Output is `the: 3` then `fox: 2`. Splitting on any non-alphanumeric character strips punctuation, `to_lowercase` folds case, and the deterministic tie-break by word keeps output stable.

