        return 1;
    }

    while (src[i] != '\0') {
        if (i + 1 >= cap) {
            truncated = 1;
            break;
        }
        dst[i] = src[i];
        ++i;
    }
    dst[i] = '\0';
    return truncated;
}
```

Compile with `gcc -std=c89 -Wall -Wextra -c safe_copy.c`. The loop stops before the buffer is full so there is always room for the terminating NUL; `cap == 0`, NULL pointers, and an oversized source all return `1` without writing past the buffer.

