bool isPalindrome(const std::string& s) {
    size_t i = 0, j = s.size();
    while (i < j) {
        unsigned char left = static_cast<unsigned char>(s[i]);
        unsigned char right = static_cast<unsigned char>(s[--j]);
        if (!std::isalnum(left)) { ++i; continue; }
        if (!std::isalnum(right)) { continue; }
        if (std::tolower(left) != std::tolower(right)) return false;
        ++i;
    }
    return true;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << isPalindrome("") << '\n';
    std::cout << isPalindrome("A man, a plan, a canal: Panama") << '\n';
    std::cout << isPalindrome("race a car") << '\n';
    std::cout << isPalindrome("No 'x' in Nixon") << '\n';
    return 0;
}
