#include <stdio.h>
#include <string.h>

#define MAX_LINE 4096

static void reverse(char *s, size_t len) {
    for (size_t i = 0; i < len / 2; ++i) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
}

int main(void) {
    char line[MAX_LINE];
    while (fgets(line, sizeof line, stdin)) {
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[len - 1] = '\0';
            --len;
        }
        reverse(line, len);
        puts(line);
    }
    return 0;
}
```

`fgets` keeps the newline, so it is stripped before reversing and restored implicitly by `puts`. The swap loop runs to `len/2`, so a single character is left untouched and an empty line prints as an empty line. `strlen` bounds the reverse, so no overrun occurs on long input within 4096.

