#include <iostream>

const long long MOD = 1000000007LL;

struct Mat {
    long long a, b, c, d;
};

Mat mul(const Mat& x, const Mat& y) {
    return Mat{
        (x.a * y.a + x.b * y.c) % MOD,
        (x.a * y.b + x.b * y.d) % MOD,
        (x.c * y.a + x.d * y.c) % MOD,
        (x.c * y.b + x.d * y.d) % MOD
    };
}

Mat power(Mat base, unsigned long long e) {
    Mat result{1, 0, 0, 1}; // identity
    while (e > 0) {
        if (e & 1ULL) result = mul(result, base);
        base = mul(base, base);
        e >>= 1;
    }
    return result;
}

int main() {
    unsigned long long n;
    if (!(std::cin >> n)) return 0;
    Mat m = power(Mat{1, 1, 1, 0}, n);
    std::cout << m.b % MOD << "\n";
    return 0;
}
```

The matrix {{1,1},{1,0}} raised to the nth power has F(n) in its off-diagonal, and binary exponentiation keeps it O(log n) for n up to 10^18. Values stay reduced mod 1e9+7.

