```cpp
#include <list>
#include <optional>
#include <unordered_map>

class LRUCache {
public:
    explicit LRUCache(std::size_t capacity) : cap_(capacity) {}

    std::optional<int> get(int key) {
        auto it = map_.find(key);
        if (it == map_.end()) return std::nullopt;
        items_.splice(items_.begin(), items_, it->second);
        return it->second->second;
    }

    void put(int key, int value) {
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (cap_ == 0) return;
        if (items_.size() == cap_) {
            map_.erase(items_.back().first);
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        map_[key] = items_.begin();
    }

private:
    std::size_t cap_;
    std::list<std::pair<int, int>> items_;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> map_;
};
```
`splice` moves the node in O(1) without allocation; a zero capacity is handled so `put` never erases when there is nothing to evict.

```c
#include <stdio.h>
#include <stddef.h>

/* Returns 1 if the whole buffer is valid UTF-8, else 0. */
int utf8_valid(const unsigned char *s, size_t n) {
    size_t i = 0;
    while (i < n) {
        unsigned char c = s[i];
        int len;
        unsigned int cp;
        if (c < 0x80) { i++; continue; }
        else if ((c & 0xE0) == 0xC0) { len = 2; cp = c & 0x1F; }
        else if ((c & 0xF0) == 0xE0) { len = 3; cp = c & 0x0F; }
        else if ((c & 0xF8) == 0xF0) { len = 4; cp = c & 0x07; }
        else return 0;

        if (i + (size_t)len > n) return 0;
        for (int j = 1; j < len; j++) {
            if ((s[i + (size_t)j] & 0xC0) != 0x80) return 0;
            cp = (cp << 6) | (s[i + (size_t)j] & 0x3F);
        }

        if (len == 2 && cp < 0x80) return 0;
        if (len == 3 && cp < 0x800) return 0;
        if (len == 4 && cp < 0x10000) return 0;
        if (cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) return 0;

        i += (size_t)len;
    }
    return 1;
}

int main(void) {
    const unsigned char good[] = {0xE2, 0x82, 0xAC};          /* euro sign */
    const unsigned char overlong[] = {0xC0, 0xAF};              /* overlong '/' */
    printf("%d\n", utf8_valid(good, sizeof good));
    printf("%d\n", utf8_valid(overlong, sizeof overlong));
    return 0;
}
```
The code-point range checks reject overlong forms and surrogates, and bounds are verified before every continuation byte is read.

