```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    bool try_push(int value) {
        std::lock_guard<std::mutex> lock(mu_);
        if (q_.size() >= cap_) return false;
        q_.push(value);
        cv_.notify_one();
        return true;
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        cv_.wait(lock, [this] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;
        int v = q_.front();
        q_.pop();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        cv_.notify_all();
    }

private:
    std::size_t cap_;
    bool closed_ = false;
    std::queue<int> q_;
    std::mutex mu_;
    std::condition_variable cv_;
};
```
`close()` wakes every blocked `pop` and makes it return `nullopt`, so shutdown cannot deadlock; `try_push` never blocks and reports failure with `false`.

```c
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

typedef struct {
    unsigned char *base;
    size_t size;
    size_t used;
} Arena;

void arena_init(Arena *a, void *mem, size_t size) {
    a->base = (unsigned char *)mem;
    a->size = size;
    a->used = 0;
}

void *arena_alloc(Arena *a, size_t bytes, size_t align) {
    if (align == 0 || (align & (align - 1)) != 0) return NULL; /* power of two */
    size_t offset = (a->used + align - 1) & ~(align - 1);
    if (offset > a->size || bytes > a->size - offset) return NULL;
    void *p = a->base + offset;
    a->used = offset + bytes;
    return p;
}

void arena_reset(Arena *a) { a->used = 0; }

int main(void) {
    static unsigned char buffer[256];
    Arena a;
    arena_init(&a, buffer, sizeof buffer);

    void *p = arena_alloc(&a, 4, 8);
    void *q = arena_alloc(&a, 64, 16);
    void *r = arena_alloc(&a, 4096, 8);

    printf("aligned: %d\n", ((uintptr_t)p % 8 == 0) && ((uintptr_t)q % 16 == 0));
    printf("oom rejected: %d\n", r == NULL);
    arena_reset(&a);
    printf("reset: %d\n", a.used == 0);
    return 0;
}
```
Alignment must be a power of two; `bytes > a->size - offset` avoids the overflow that `offset + bytes` would wrap on large requests.

