class Money:
    __slots__ = ("_cents",)

    def __init__(self, cents):
        if not isinstance(cents, int):
            raise TypeError("cents must be an int")
        self._cents = cents

    @classmethod
    def parse(cls, text):
        text = text.strip().lstrip("$")
        if "." in text:
            whole, frac = text.split(".", 1)
            frac = (frac + "00")[:2]
        else:
            whole, frac = text, "00"
        sign = -1 if whole.startswith("-") else 1
        whole = whole.lstrip("-+") or "0"
        if not whole.isdigit() or not frac.isdigit():
            raise ValueError(f"bad amount: {text!r}")
        return cls(sign * (int(whole) * 100 + int(frac)))

    def add(self, other):
        return Money(self._cents + other._cents)

    def __str__(self):
        sign = "-" if self._cents < 0 else ""
        c = abs(self._cents)
        return f"{sign}${c // 100}.{c % 100:02d}"


if __name__ == "__main__":
    total = Money.parse("0.10").add(Money.parse("0.20"))
    print(total)                      # $0.30
    print(total == Money.parse("$0.30"))  # True
```
All arithmetic happens on integer cents, so `0.1 + 0.2` cannot drift; `__slots__` keeps instances small.

