bool is_balanced(const std::string& s) {
    std::stack<char> st;
    const std::unordered_map<char, char> open_for{{')', '('}, {']', '['}, {'}', '{'}};
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty() || st.top() != open_for.at(c)) return false;
            st.pop();
        }
    }
    return st.empty();
}

