#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
    std::array<int, N> buf_{};
    std::size_t head_ = 0, size_ = 0;
public:
    bool push(int v) {
        if (size_ == N) return false;            // full, reject
        buf_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }
    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;     // empty
        int v = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }
    std::size_t size() const { return size_; }
};

int main() {
    RingBuffer<3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << "\n"; // 1110
    while (auto v = rb.pop()) std::cout << *v << ' ';  // 1 2 3
    std::cout << "\n" << rb.pop().has_value() << "\n"; // 0
