fn binary_search<T: Ord>(haystack: &[T], needle: &T) -> Option<usize> {
    let mut lo: usize = 0;
    let mut hi: usize = haystack.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match haystack[mid].cmp(needle) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    None
}

fn main() {
    let empty: [i32; 0] = [];
    assert_eq!(binary_search(&empty, &1), None);

    let data = [1, 3, 3, 5, 8, 13];
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &13), Some(5));
    assert!(binary_search(&data, &4).is_none());
    // duplicate: any matching index is acceptable
    assert!(matches!(binary_search(&data, &3), Some(1) | Some(2)));
    println!("all checks passed");
}
