    """
    if not isinstance(strings, list):
        raise TypeError("expected a list of strings")
    if not strings:
        return ""
    for s in strings:
        if not isinstance(s, str):
            raise TypeError(f"non-string element: {s!r}")

    prefix = strings[0]
    for s in strings[1:]:
        limit = min(len(prefix), len(s))
        i = 0
        while i < limit and prefix[i] == s[i]:
            i += 1
        prefix = prefix[:i]
        if not prefix:
            break
    return prefix


if __name__ == "__main__":
    assert longest_common_prefix(["flower", "flow", "flight"]) == "fl"
    assert longest_common_prefix(["dog", "racecar", "car"]) == ""
    assert longest_common_prefix([]) == ""
    assert longest_common_prefix(["abc"]) == "abc"
    assert longest_common_prefix(["café", "caféine"]) == "café"
    try:
        longest_common_prefix(["ok", 3])
    except TypeError:
        pass
    else:
        raise AssertionError("expected TypeError")
    print("all tests passed")
```

Walks the first string down against each remaining string, trimming to the matching prefix. Unicode works because Python compares code points, so `"café"` and `"caféine"` share `"café"`.

```cpp
#include <condition_variable>
#include <cstddef>
#include <mutex>
#include <optional>
#include <queue>
#include <thread>
#include <iostream>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {}

    bool push(T value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [this] { return queue_.size() < capacity_ || closed_; });
        if (closed_) return false;
        queue_.push(std::move(value));
        not_empty_.notify_one();
        return true;
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock, [this] { return !queue_.empty() || closed_; });
        if (queue_.empty()) return std::nullopt;
        T value = std::move(queue_.front());
        queue_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mutex_);
        closed_ = true;
        not_full_.notify_all();
        not_empty_.notify_all();
    }

private:
    std::size_t capacity_;
    std::queue<T> queue_;
    std::mutex mutex_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
    bool closed_ = false;
};

int main() {
    BoundedQueue<int> q(4);
    std::thread producer([&q] {
        for (int i = 0; i < 20; ++i) {
            if (!q.push(i)) break;
        }
        q.close();
    });
    std::thread consumer([&q] {
        int sum = 0, n = 0;
        while (auto v = q.pop()) {
            sum += *v;
            ++n;
        }
        std::cout << "received " << n << " items, sum=" << sum << "\n";
    });
    producer.join();
    consumer.join();
    return 0;
}
```

Both waits use a predicate so spurious wakeups are handled. `close()` drains the queue before `pop()` returns `std::nullopt`, so the consumer never deadlocks on an empty queue after shutdown.

```cpp
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

std::vector<std::string> parseCsvLine(const std::string& line) {
    std::vector<std::string> fields;
    std::string current;
    bool inQuotes = false;

    for (std::size_t i = 0; i < line.size(); ++i) {
        char c = line[i];
        if (inQuotes) {
            if (c == '"') {
                if (i + 1 < line.size() && line[i + 1] == '"') {
                    current.push_back('"');
                    ++i;
                } else {
                    inQuotes = false;
                }
            } else {
                current.push_back(c);
            }
        } else if (c == '"') {
            inQuotes = true;
        } else if (c == ',') {
            fields.push_back(std::move(current));
            current.clear();
        } else {
            current.push_back(c);
        }
    }
    if (inQuotes) throw std::runtime_error("unterminated quoted field");
    fields.push_back(std::move(current));
    return fields;
}

int main() {
    auto fields = parseCsvLine("name,notes,\"Smith, John\",\"He said \"\"hi\"\"\"");
    for (std::size_t i = 0; i < fields.size(); ++i)
        std::cout << i << ": [" << fields[i] << "]\n";
    return 0;
}
```

The state machine toggles `inQuotes` on unescaped quote characters; a doubled quote inside a quoted field becomes a literal `"`. An unterminated quote raises instead of silently returning a malformed row.

```rust
use std::collections::HashMap;

/// Returns F(n) with F(0)=0, F(1)=1. Fails if the result overflows u128.
pub fn fib(n: u64) -> Result<u128, String> {
    if n > 186 {
        // F(186) is the largest Fibonacci number that fits in u128.
        return Err(format!("F({n}) overflows u128"));
    }
    let mut memo: HashMap<u64, u128> = HashMap::new();
    memo.insert(0, 0);
    memo.insert(1, 1);

    fn go(n: u64, memo: &mut HashMap<u64, u128>) -> u128 {
        if let Some(&v) = memo.get(&n) {
            return v;
        }
        let v = go(n - 1, memo).checked_add(go(n - 2, memo)).expect("checked by n <= 186");
        memo.insert(n, v);
        v
    }

    Ok(go(n, &mut memo))
}

fn main() {
    assert_eq!(fib(0).unwrap(), 0);
    assert_eq!(fib(1).unwrap(), 1);
    assert_eq!(fib(10).unwrap(), 55);
    assert_eq!(fib(50).unwrap(), 12586269025);
    assert!(fib(500).is_err());
    println!("F(100) = {}", fib(100).unwrap());
}
```

The recursive helper caches each value the first time it is computed, so the total work is O(n). F(186) is the last Fibonacci value that fits in `u128`, so `n > 186` is rejected up front and the `checked_add` never fires in practice.

