```python
def parse_ipv4(text):
    """Parse a dotted-quad IPv4 string into a 32-bit int, or raise ValueError."""
    if not isinstance(text, str):
        raise ValueError("IPv4 address must be a string")
    parts = text.split(".")
    if len(parts) != 4:
        raise ValueError(f"expected 4 octets, got {len(parts)}")
    value = 0
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"non-numeric octet: {part!r}")
        if len(part) > 1 and part[0] == "0":
            raise ValueError(f"leading zero in octet: {part!r}")
        octet = int(part)
        if octet > 255:
            raise ValueError(f"octet out of range: {octet}")
        value = (value << 8) | octet
    return value


if __name__ == "__main__":
    assert parse_ipv4("0.0.0.0") == 0
    assert parse_ipv4("255.255.255.255") == 0xFFFFFFFF
    assert parse_ipv4("192.168.1.1") == 0xC0A80101
    for bad in ["1.2.3", "1.2.3.4.5", "256.1.1.1", "1.2.3.x", "01.2.3.4", ""]:
        try:
            parse_ipv4(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"expected ValueError for {bad!r}")
    print("all tests passed")
```

Each octet must be all digits, may not have a leading zero, and must be ≤ 255. Valid octets are shifted into a 32-bit integer so `192.168.1.1` maps to `0xC0A80101`.

