#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) return;
    right -= 1;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char a[] = "hello world";
    char b[] = "";
    char c[] = "x";
    char d[] = "caf\xC3\xA9"; /* "café" in UTF-8 bytes */

    reverse_in_place(a);
    reverse_in_place(b);
    reverse_in_place(c);
    reverse_in_place(d);

    printf("[%s]\n", a);
    printf("[%s]\n", b);
    printf("[%s]\n", c);
    printf("[%s]\n", d);
    return 0;
}
```

