std::vector<int> merge(const std::vector<int>& a, const std::vector<int>& b,
                       std::vector<int>& dups) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::set<int> seen;
    for (int v : a) { out.push_back(v); seen.insert(v); }
    for (int v : b) {
        if (seen.count(v)) dups.push_back(v);
        out.push_back(v);
    }
    return out;
}

int main() {
    std::vector<int> dup;
    auto r = merge({1, 3, 5, 7}, {3, 4, 5, 9}, dup);
    for (size_t i = 0; i < r.size(); ++i)
        std::cout << r[i] << (i + 1 < r.size() ? " " : "\n");
    std::cout << "duplicates:";
    for (int v : dup) std::cout << " " << v;
    std::cout << "\n";
    return 0;
}
