```cpp
#include <iostream>
#include <vector>

// Returns index of target, or the index where it would be inserted.
int searchInsert(const std::vector<int>& a, int target) {
    int lo = 0, hi = static_cast<int>(a.size());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

int main() {
    std::vector<int> a = {1, 3, 5, 6};
    std::cout << searchInsert(a, 5) << "\n";  // 2
    std::cout << searchInsert(a, 2) << "\n";  // 1
    std::cout << searchInsert(a, 7) << "\n";  // 4
    std::cout << searchInsert(a, 0) << "\n";  // 0
    std::cout << searchInsert({}, 9) << "\n"; // 0
    return 0;
}
```

The lower-bound loop returns the first index where `a[index] >= target`, which is the match or the insertion point. `mid` uses `lo + (hi - lo) / 2` to avoid overflow on huge vectors. Empty input returns 0.

