        .iter().map(|s| s.to_string()).collect();
    println!("{}", longest_common_prefix(&a)); // fl
    let b: Vec<String> = ["dog", "racecar"].iter()
        .map(|s| s.to_string()).collect();
    println!("{}|{}", longest_common_prefix(&b), longest_common_prefix(&[])); // empty
