```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        if (size_ == N) throw std::overflow_error("ring buffer full");
        data_[(head_ + size_) % N] = value;
        ++size_;
    }
    T pop() {
        if (size_ == 0) throw std::underflow_error("ring buffer empty");
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }
    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }
private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    std::cout << rb.pop() << rb.pop() << "\n"; // 12
    rb.push(4); rb.push(5);
    std::cout << rb.pop() << rb.pop() << rb.pop() << "\n"; // 345
    std::cout << rb.empty() << "\n"; // 1
    return 0;
}
```

Indices wrap with modulo `N`, so no dynamic allocation is needed. Overflow and underflow throw instead of silently corrupting data. Fully wrapped reads after writes are exercised by pushing 4 and 5 after two pops.

```cpp
#include <iostream>
#include <vector>

std::vector<int> merge_sorted(const std::vector<int>& a,
                              const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        // <= keeps equal elements stable relative to a, then b.
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else              out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 3, 7};
    std::vector<int> b{};
    std::vector<int> c{-2, 3, 8};

    auto r1 = merge_sorted(a, b);
    auto r2 = merge_sorted(b, c);
    auto r3 = merge_sorted({}, {});

    for (int v : r1) std::cout << v << ' ';
    std::cout << '\n';
    for (int v : r2) std::cout << v << ' ';
    std::cout << '\n';
    std::cout << r3.size() << '\n';
}
```

Reserving `a.size() + b.size()` avoids reallocations, and the trailing `while` loops handle the leftover tail of whichever input ran out first. Empty inputs are fine on both sides.

