def check_brackets(s):
    """Return None if brackets are balanced, else the index of the first problem."""
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []  # (char, index)
    for i, ch in enumerate(s):
        if ch in "([{":
            stack.append((ch, i))
        elif ch in pairs:
            if not stack:
                return i
            top, _ = stack.pop()
            if top != pairs[ch]:
                return i
    if stack:
        return stack[-1][1]
    return None


