```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t cap;    /* allocated slots */
    size_t head;   /* index of next write */
    size_t count;  /* number of live elements */
} ring_t;

static int ring_grow(ring_t *r) {
    size_t newcap = r->cap ? r->cap * 2 : 4;
    int *buf = malloc(newcap * sizeof *buf);
    if (!buf) return -1;
    for (size_t i = 0; i < r->count; i++)
        buf[i] = r->data[(r->head + i) % r->cap];
    free(r->data);
    r->data = buf;
    r->cap = newcap;
    r->head = 0;
    return 0;
}

int ring_push(ring_t *r, int v) {
    if (r->count == r->cap && ring_grow(r) != 0) return -1;
    r->data[r->head] = v;
    r->head = (r->head + 1) % r->cap;
    r->count++;
    return 0;
}

int ring_pop(ring_t *r, int *out) {
    if (r->count == 0) return -1;
    size_t tail = (r->head + r->cap - r->count) % r->cap;
    *out = r->data[tail];
    r->count--;
    return 0;
}

void ring_free(ring_t *r) {
    free(r->data);
    r->data = NULL;
    r->cap = r->count = r->head = 0;
}

int main(void) {
    ring_t r = {0};
    for (int i = 0; i < 10; i++)
        if (ring_push(&r, i) != 0) { fprintf(stderr, "push failed\n"); return 1; }

    int v;
    for (int i = 0; i < 10; i++) {
        if (ring_pop(&r, &v) != 0) { fprintf(stderr, "pop failed\n"); return 1; }
        if (v != i) { fprintf(stderr, "got %d want %d\n", v, i); return 1; }
    }
    if (ring_pop(&r, &v) != -1)
        fprintf(stderr, "expected empty pop to fail\n");

    ring_free(&r);
    puts("ok");
    return 0;
}
```

Growth copies elements in logical order to the front, resetting `head` to 0, which keeps the modular arithmetic correct after `realloc`-style resizing.

