```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        self.capacity = capacity
        self._data = OrderedDict()  # key -> value, MRU at the end

    def get(self, key):
        if key not in self._data:
            return -1
        self._data.move_to_end(key)  # mark as most recently used
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least recently used

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, 1)
    c.put(2, 2)
    assert c.get(1) == 1
    c.put(3, 3)          # evicts key 2
    assert c.get(2) == -1
    c.put(4, 4)          # evicts key 1
    assert c.get(1) == -1
    assert c.get(3) == 3
    assert c.get(4) == 4
    assert len(c) == 2

    for bad in (0, -1, 2.5, None):
        try:
            LRUCache(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"accepted invalid capacity {bad!r}")
    print("ok")
```

`move_to_end` on a hit is what keeps recency order correct; `popitem(last=False)` discards the front, which is the least recently used entry.

```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <string>
#include <vector>

// Requires: [begin, end) is sorted by operator<.
// Returns index of value if found, else std::nullopt.
template <typename It, typename T>
std::optional<std::size_t> binary_search_index(It begin, It end, const T& value) {
    std::size_t lo = 0;
    std::size_t hi = static_cast<std::size_t>(std::distance(begin, end));
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;  // avoids overflow on huge ranges
        if (*(begin + mid) < value) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo < static_cast<std::size_t>(std::distance(begin, end)) &&
        !(value < *(begin + lo))) {
        return lo;
    }
    return std::nullopt;
}

int main() {
    std::vector<int> v{1, 3, 5, 7, 9};
    if (auto r = binary_search_index(v.begin(), v.end(), 7)) std::cout << *r << '\n';
    if (!binary_search_index(v.begin(), v.end(), 4)) std::cout << "absent\n";

    std::vector<int> empty;
    if (!binary_search_index(empty.begin(), empty.end(), 1)) std::cout << "empty ok\n";

    std::vector<std::string> words{"ant", "bee", "cow"};
    if (auto r = binary_search_index(words.begin(), words.end(), std::string("bee")))
        std::cout << *r << '\n';
}
```

The `!(value < ...)` form compares once and works for types with only `<`, and `lo + (hi - lo) / 2` avoids the classic `(lo + hi) / 2` integer overflow.

