use std::collections::HashMap;
use std::hash::Hash;

pub fn top_k<T: Eq + Hash + Clone>(items: &[T], k: usize) -> Vec<(T, usize)> {
    let mut counts: HashMap<&T, usize> = HashMap::new();
    for item in items {
        *counts.entry(item).or_insert(0) += 1;
    }
    let mut pairs: Vec<(T, usize)> = counts
        .into_iter()
        .map(|(value, count)| (value.clone(), count))
        .collect();
    // Sort by count descending, then by value for a deterministic tie-break.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| format!("{:?}", a.0).cmp(&format!("{:?}", b.0))));
    pairs.truncate(k);
    pairs
}

fn main() {
    let data = vec!['a', 'b', 'a', 'c', 'a', 'b'];
    println!("{:?}", top_k(&data, 2));
    println!("{:?}", top_k::<u8>(&[], 3));
}
