#include <stdio.h>
#include <string.h>

static void reverse_range(char *s, size_t lo, size_t hi) { /* [lo, hi) */
    while (lo + 1 < hi) {
        char t = s[lo];
        s[lo] = s[hi - 1];
        s[hi - 1] = t;
        ++lo;
        --hi;
    }
}

static void reverse_words(char *s) {
    size_t n = strlen(s);
    reverse_range(s, 0, n);
    size_t i = 0;
    while (i < n) {
        while (i < n && s[i] == ' ') ++i;
        size_t j = i;
        while (j < n && s[j] != ' ') ++j;
        reverse_range(s, i, j);
        i = j;
    }
}

int main(void) {
    char line[4096];
    if (!fgets(line, sizeof line, stdin)) return 0;
    size_t n = strlen(line);
    if (n && line[n - 1] == '\n') line[--n] = '\0';
    reverse_words(line);
    puts(line);
    return 0;
}
