```cpp
#include <cctype>
#include <iostream>
#include <stdexcept>
#include <string>

class Parser {
    const std::string& s;
    std::size_t pos = 0;

    void skip_spaces() { while (pos < s.size() && std::isspace((unsigned char)s[pos])) ++pos; }

    double parse_expr();

    double parse_factor() {
        skip_spaces();
        if (pos < s.size() && s[pos] == '(') {
            ++pos;
            double v = parse_expr();
            skip_spaces();
            if (pos >= s.size() || s[pos] != ')')
                throw std::runtime_error("missing )");
            ++pos;
            return v;
        }
        std::size_t start = pos;
        while (pos < s.size() && (std::isdigit((unsigned char)s[pos]) || s[pos] == '.')) ++pos;
        if (start == pos) throw std::runtime_error("expected number");
        return std::stod(s.substr(start, pos - start));
    }

    double parse_term() {
        double v = parse_factor();
        for (;;) {
            skip_spaces();
            if (pos < s.size() && (s[pos] == '*' || s[pos] == '/')) {
                char op = s[pos++];
                double rhs = parse_factor();
                if (op == '*') v *= rhs;
                else {
                    if (rhs == 0.0) throw std::runtime_error("division by zero");
                    v /= rhs;
                }
            } else return v;
        }
    }

    double parse_expr() {
        double v = parse_term();
        for (;;) {
            skip_spaces();
            if (pos < s.size() && (s[pos] == '+' || s[pos] == '-')) {
                char op = s[pos++];
                double rhs = parse_term();
                v = (op == '+') ? v + rhs : v - rhs;
            } else return v;
        }
    }

public:
    explicit Parser(const std::string& src) : s(src) {}
    double run() {
        double v = parse_expr();
        skip_spaces();
        if (pos != s.size()) throw std::runtime_error("trailing input");
        return v;
    }
};

int main() {
    try {
        std::cout << Parser("2 + 3 * (4 - 1)").run() << "\n"; // 11
        std::cout << Parser("10 / 4").run() << "\n";          // 2.5
    } catch (const std::exception& e) {
        std::cerr << "error: " << e.what() << "\n";
        return 1;
    }
    return 0;
}
```

Recursive descent: `expr` handles +/-, `term` handles */, `factor` handles numbers and parentheses. Division by zero and malformed input raise instead of returning garbage.

```rust
pub fn run_length_encode(input: &str) -> String {
    let mut out = String::new();
    let mut chars = input.chars();
    if let Some(first) = chars.next() {
        let mut current = first;
        let mut count = 1usize;
        for c in chars {
            if c == current {
                count += 1;
            } else {
                out.push_str(&count.to_string());
                out.push(current);
                current = c;
                count = 1;
            }
        }
        out.push_str(&count.to_string());
        out.push(current);
    }
    out
}

pub fn run_length_decode(input: &str) -> Result<String, String> {
    let mut out = String::new();
    let mut digits = String::new();
    for c in input.chars() {
        if c.is_ascii_digit() {
            digits.push(c);
        } else {
            let n: usize = digits.parse().map_err(|_| format!("missing count before '{}'", c))?;
            for _ in 0..n {
                out.push(c);
            }
            digits.clear();
        }
    }
    if !digits.is_empty() {
        return Err("trailing count with no character".to_string());
    }
    Ok(out)
}

fn main() {
    let encoded = run_length_encode("aaabbc\u{1F600}\u{1F600}");
    println!("{}", encoded);
    println!("{}", run_length_decode(&encoded).unwrap());
}
```

Iterating over `chars()` means multi-byte emoji are counted as single symbols; the decoder validates missing or dangling counts instead of panicking.

