public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), size_(0), cap_(capacity) {}

    bool push(int value) {
        if (cap_ == 0) return false;
        if (size_ == cap_) {
            data_[head_] = value;
            head_ = (head_ + 1) % cap_;
            return true;
        }
        data_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return cap_; }

    int at(std::size_t i) const { return data_[(head_ + i) % cap_]; }

private:
    std::vector<int> data_;
    std::size_t head_;
    std::size_t size_;
    std::size_t cap_;
};

