                print(f"line {lineno}: bad score {raw!r}, skipping", file=sys.stderr)
                continue
            counts[name] += 1
    return sorted(
        ((n, totals[n] / counts[n]) for n in totals),
        key=lambda pair: pair[1],
        reverse=True,
    )


