#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double v) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) return std::nullopt;
        double v = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }

    std::optional<double> mean() const {
        if (size_ == 0) return std::nullopt;
        double sum = 0.0;
        for (std::size_t i = 0; i < size_; ++i) {
            sum += data_[(head_ + i) % N];
        }
        return sum / static_cast<double>(size_);
    }

    std::size_t size() const { return size_; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    std::cout << rb.pop().value_or(-1) << '\n';   // empty safe
    rb.push(1.0);
    rb.push(2.0);
    rb.push(3.0);
    std::cout << rb.push(4.0) << '\n';           // false, full
    if (auto m = rb.mean()) std::cout << *m << '\n'; // 2
    rb.pop();
    if (auto m = rb.mean()) std::cout << *m << '\n'; // 2.5
    return 0;
}
```

Storage is a fixed `std::array`, so there is no heap traffic. Empty `pop` and `mean` return `std::nullopt` rather than reading junk.

