```c
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

int parse_ipv4(const char *s, uint32_t *out) {
    uint32_t parts[4];
    const char *p = s;

    for (int i = 0; i < 4; ++i) {
        if (*p < '0' || *p > '9') return -1;
        char *end = NULL;
        long v = strtol(p, &end, 10);
        if (v > 255) return -1;
        parts[i] = (uint32_t)v;
        if (i < 3) {
            if (*end != '.') return -1;
            p = end + 1;
        } else {
            if (*end != '\0') return -1;
        }
    }
    *out = (parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3];
    return 0;
}

int main(void) {
    uint32_t v = 0;
    printf("%d %u\n", parse_ipv4("192.168.0.1", &v), v);   // 0 3232235521
    printf("%d\n", parse_ipv4("256.1.1.1", &v));            // -1
    printf("%d\n", parse_ipv4("1.2.3.4.5", &v));            // -1
    printf("%d\n", parse_ipv4("1.2.3", &v));                // -1
    return 0;
}
