```python
import functools
import random
import time


def retry(attempts: int = 3, base: float = 0.5, cap: float = 8.0,
          skip: tuple[type[BaseException], ...] = (), jitter: float = 0.1):
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last = None
            for i in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except skip:
                    raise
                except BaseException as exc:  # noqa: BLE001 - deliberate re-raise below
                    last = exc
                    if i == attempts - 1:
                        break
                    delay = min(cap, base * (2 ** i))
                    delay += random.uniform(0.0, jitter * delay)
                    time.sleep(delay)
            raise last  # type: ignore[misc]
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base=0.01)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ConnectionError("boom")
        return "ok"

    print(flaky(), "after", calls["n"], "calls")
```

Backoff is `base * 2**i` capped at `cap`, with up to `jitter` fraction added. `skip` types are re-raised immediately so `ValueError`-style bugs are not retried.

