class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._buf = [0.0] * capacity
        self._start = 0
        self._size = 0

    def push(self, value):
        value = float(value)
        if self._size < len(self._buf):
            self._buf[(self._start + self._size) % len(self._buf)] = value
            self._size += 1
        else:
            self._buf[self._start] = value
            self._start = (self._start + 1) % len(self._buf)

    def __iter__(self):
        for i in range(self._size):
            yield self._buf[(self._start + i) % len(self._buf)]

    def __len__(self):
        return self._size

if __name__ == "__main__":
    rb = RingBuffer(3)
    for v in [1, 2, 3, 4, 5]:
        rb.push(v)
    assert list(rb) == [3.0, 4.0, 5.0]
    print("ok")
