```rust
fn fib_fast_doubling(n: u32) -> Option<u64> {
    fn helper(n: u32) -> Option<(u64, u64)> {
        if n == 0 {
            return Some((0, 1));
        }
        let (a, b) = helper(n >> 1)?;
        let c = a.checked_mul(b.checked_mul(2)?.checked_sub(a)?)?;
        let d = a.checked_mul(a)?.checked_add(b.checked_mul(b)?)?;
        if n & 1 == 0 {
            Some((c, d))
        } else {
            Some((d, c.checked_add(d)?))
        }
    }
    helper(n).map(|(f, _)| f)
}

fn main() {
    assert_eq!(fib_fast_doubling(0), Some(0));
    assert_eq!(fib_fast_doubling(10), Some(55));
    assert_eq!(fib_fast_doubling(50), Some(12586269025));
    assert_eq!(fib_fast_doubling(93), Some(12200160415121876738));
    assert_eq!(fib_fast_doubling(94), None); // u64 overflow
    println!("fib_fast_doubling passed");
}
```

Fast doubling runs in O(log n) calls: each step derives `(F(k), F(k+1))` for `k = n >> 1` and combines them, returning `Option<u64>` so overflow surfaces as `None` instead of wrapping silently. `F(93)` is the last value that fits in `u64`.

