// Returns index of value, or the position it would be inserted at.
std::size_t search_or_insert(const std::vector<int>& data, int value) {
    std::size_t lo = 0, hi = data.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (data[mid] < value) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

int main() {
    const std::vector<int> v{1, 3, 5, 7, 9};
    assert(search_or_insert(v, 5) == 2);
    assert(search_or_insert(v, 0) == 0);
    assert(search_or_insert(v, 10) == 5);
    assert(search_or_insert(v, 4) == 2);
    assert(search_or_insert({}, 42) == 0);
    std::cout << "search_or_insert passed\n";
    return 0;
}
```

Half-open bounds `[lo, hi)` and `mid = lo + (hi - lo) / 2` avoid overflow on large ranges. The loop converges on the first index whose element is `>= value`, which is the found index or the correct insertion point. Empty input returns 0.

```python
OPEN = {"(": ")", "[": "]", "{": "}"}
CLOSE = {v: k for k, v in OPEN.items()}


def balanced(s):
    """Return True if brackets balance, ignoring quoted literals."""
    stack = []
    quote = None
    escaped = False

    for ch in s:
        if quote is not None:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == quote:
                quote = None
            continue

        if ch in ("'", '"'):
            quote = ch
        elif ch in OPEN:
            stack.append(ch)
        elif ch in CLOSE:
            if not stack or stack.pop() != CLOSE[ch]:
                return False

    return not stack and quote is None


if __name__ == "__main__":
    assert balanced("({[]})")
    assert not balanced("([)]")
    assert not balanced("(")
    assert balanced("")
    assert balanced('"(["')
    assert balanced('foo("a\\"(")')
    assert not balanced('foo("unclosed')
    print("balanced passed")
```

A stack tracks opens; quoted regions are skipped entirely, with backslash escapes handled so `\"` does not end a string. Mismatched closers fail immediately, and a trailing open bracket or unterminated quote on its own line returns False. Empty strings count as balanced.

