// Parses digits of `text` into `out`. Returns false on empty input,
// non-digit characters, or unsigned 64-bit overflow.
bool parse_u64(const std::string& text, std::uint64_t& out) {
    if (text.empty()) return false;
    std::uint64_t value = 0;
    for (char ch : text) {
        if (ch < '0' || ch > '9') return false;
        std::uint64_t digit = static_cast<std::uint64_t>(ch - '0');
        // value * 10 + digit must not exceed UINT64_MAX
        if (value > (std::numeric_limits<std::uint64_t>::max() - digit) / 10) {
            return false;
        }
        value = value * 10 + digit;
    }
    out = value;
    return true;
}

int main() {
    std::uint64_t v = 0;
    if (!parse_u64("12345", v) || v != 12345u) { std::cerr << "case 1 failed\n"; return 1; }
    if (!parse_u64("18446744073709551615", v) || v != UINT64_MAX) { std::cerr << "case 2 failed\n"; return 1; }
    if (parse_u64("", v)) { std::cerr << "case 3 failed\n"; return 1; }
    if (parse_u64("12a", v)) { std::cerr << "case 4 failed\n"; return 1; }
    if (parse_u64("-3", v)) { std::cerr << "case 5 failed\n"; return 1; }
    if (parse_u64("18446744073709551616", v)) { std::cerr << "case 6 failed\n"; return 1; }
    std::cout << "all checks passed\n";
    return 0;
}
