use std::collections::HashMap;

pub fn word_frequencies(text: &str) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let key = word.to_lowercase();
        if key.is_empty() {
            continue;
        }
        *counts.entry(key).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs
}

fn main() {
    assert_eq!(word_frequencies(""), Vec::<(String, usize)>::new());
    assert_eq!(
        word_frequencies("the The THE cat cat dog"),
        vec![
            ("cat".to_string(), 2),
            ("the".to_string(), 3),
            ("dog".to_string(), 1),
        ]
        .into_iter()
        .collect::<Vec<_>>()
        .into_iter()
        .collect::<Vec<_>>()
        .tap_sort()
    );
    // Simpler, direct assertion for the sorted order:
    let got = word_frequencies("the The THE cat cat dog");
    assert_eq!(got, vec![
        ("the".to_string(), 3),
        ("cat".to_string(), 2),
        ("dog".to_string(), 1),
    ]);
    let unicode = word_frequencies("caf\u{e9} CAF\u{e9}\u{2014}bar");
    assert_eq!(unicode, vec![
        ("caf\u{e9}".to_string(), 1),
        ("caf\u{e9}\u{2014}bar".to_string(), 1),
    ]);
    println!("all checks passed");
}

trait TapSort {
    fn tap_sort(self) -> Self;
}
impl TapSort for Vec<(String, usize)> {
    fn tap_sort(self) -> Self {
        self
    }
