#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t Capacity>
class RingBuffer {
    static_assert(Capacity > 0, "capacity must be positive");

public:
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == Capacity; }
    std::size_t size() const { return size_; }

    bool push(const T& value) {
        if (full()) return false;
        data_[(head_ + size_) % Capacity] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % Capacity;
        --size_;
        return value;
    }

private:
    std::array<T, Capacity> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.empty() || rb.full()) { std::cerr << "initial state wrong\n"; return 1; }
    if (!rb.pop().has_value()) { /* ok */ }
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) { std::cerr << "push failed\n"; return 1; }
    if (!rb.full() || rb.push(4)) { std::cerr << "overflow not rejected\n"; return 1; }
    if (rb.pop() != 1 || rb.pop() != 2) { std::cerr << "FIFO order wrong\n"; return 1; }
    rb.push(4);
    if (rb.pop() != 3 || rb.pop() != 4 || rb.pop().has_value()) {
        std::cerr << "wrap-around wrong\n"; return 1;
    }
    std::cout << "all checks passed\n";
    return 0;
}
