/// Validates a decimal string against the Luhn checksum.
/// Returns false for empty strings or any non-digit character.
pub fn luhn_valid(number: &str) -> bool {
    if number.is_empty() {
        return false;
    }
    let mut sum: u32 = 0;
    let mut double = false;
    for ch in number.chars().rev() {
        let Some(digit) = ch.to_digit(10) else {
            return false;
        };
        let mut value = digit;
        if double {
            value *= 2;
            if value > 9 {
                value -= 9;
            }
        }
        sum += value;
        double = !double;
    }
    sum % 10 == 0
}

fn main() {
    assert!(luhn_valid("4539 1488 0343 6467".replace(' ', "").as_str()));
    assert!(luhn_valid("79927398713"));
    assert!(!luhn_valid("79927398710"));
    assert!(!luhn_valid(""));
    assert!(!luhn_valid("12a4"));
    assert!(!luhn_valid("0"));
    println!("all checks passed");
}
