#include <stdio.h>
#include <string.h>

/* Reverses the NUL-terminated string in place. Safe for empty strings. */
static void reverse_in_place(char *text) {
    if (text[0] == '\0') {
        return;
    }
    char *left = text;
    char *right = text;
    while (*right != '\0') {
        ++right;
    }
    --right; /* step back onto the last character */
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        ++left;
        --right;
    }
}

int main(void) {
    struct { const char *input; const char *expected; } cases[] = {
        {"", ""},
        {"a", "a"},
        {"ab", "ba"},
        {"hello", "olleh"},
        {"caf\xC3\xA9", "\xC3\xA9fac"}, /* reverses bytes, not code points */
    };
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        char buffer[64];
        strcpy(buffer, cases[i].input);
        reverse_in_place(buffer);
        if (strcmp(buffer, cases[i].expected) != 0) {
            fprintf(stderr, "case %zu: got %s, want %s\n", i, buffer, cases[i].expected);
            return 1;
        }
        printf("%s\n", buffer);
    }
    return 0;
}
