fn mean(nums: &[i64]) -> Option<f64> {
    if nums.is_empty() {
        return None;
    }
    Some(nums.iter().sum::<i64>() as f64 / nums.len() as f64)
}

fn median(nums: &mut [i64]) -> Option<f64> {
    if nums.is_empty() {
        return None;
    }
    nums.sort_unstable();
    let mid = nums.len() / 2;
    if nums.len() % 2 == 1 {
        Some(nums[mid] as f64)
    } else {
        Some((nums[mid - 1] as f64 + nums[mid] as f64) / 2.0)
    }
}

fn main() {
    let input = "3, 1, 4, 1, 5";
    let mut nums = parse_numbers(input).expect("parse failed");
    println!("mean={:?} median={:?}", mean(&nums), median(&mut nums));
    match parse_numbers("3, x, 4") {
        Ok(_) => println!("unexpected ok"),
        Err(e) => println!("error: {}", e),
    }
}
```
Empty fields are skipped, whitespace is tolerated, and a non-integer token becomes a clear `Err` rather than a panic. Mean returns `None` for an empty list; median handles both odd and even lengths.

```python
import functools


def memoize(func):
    cache = {}
    stats = {"hits": 0, "misses": 0}

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if key in cache:
            stats["hits"] += 1
            return cache[key]
        stats["misses"] += 1
        result = func(*args, **kwargs)
        cache[key] = result
        return result

    wrapper.cache = cache
    wrapper.stats = stats
    return wrapper


@memoize
def slow_square(x):
    return x * x


if __name__ == "__main__":
    for _ in range(3):
        slow_square(4)
    slow_square(5)
    assert slow_square.stats == {"hits": 2, "misses": 2}
    assert slow_square.cache[(4,)] == 16
    print("ok", slow_square.stats)
```
Keys on positional arguments plus sorted keyword items, so `f(1, 2)` and `f(1, b=2)` land in different slots only when the call shape differs. `functools.wraps` preserves the wrapped name and docstring, and the raw cache and stats are exposed for inspection.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["", "a", "babad", "cbbd", "forgeeksskeegfor", "abacaba"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```
`expand` grows outward from each center; two calls per index cover odd and even lengths. Empty input returns an empty string and single characters return themselves.

