PAIRS = {")": "(", "]": "[", "}": "{"}
OPEN = set(PAIRS.values())


def is_balanced(text):
    stack = []
    for ch in text:
        if ch in OPEN:
            stack.append(ch)
        elif ch in PAIRS:
            if not stack or stack.pop() != PAIRS[ch]:
                return False
