```python
import heapq
import sys

def running_medians(stream):
    """Yield the median after each integer is consumed.

    Lower half is a max-heap (negated), upper half a min-heap.
    Invariant: len(low) == len(high) or len(low) == len(high) + 1.
    """
    low = []   # max-heap via negation
    high = []  # min-heap
    for value in stream:
        if not low or value <= -low[0]:
            heapq.heappush(low, -value)
        else:
            heapq.heappush(high, value)
        if len(low) > len(high) + 1:
            heapq.heappush(high, -heapq.heappop(low))
        elif len(high) > len(low):
            heapq.heappush(low, -heapq.heappop(high))
        if len(low) == len(high):
            yield (-low[0] + high[0]) / 2.0
        else:
            yield float(-low[0])


def main() -> None:
    values = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            values.append(int(line))
        except ValueError:
            print(f"skipping non-integer: {line!r}", file=sys.stderr)
    for m in running_medians(values):
        print(f"{m:g}")


if __name__ == "__main__":
    import io
    assert list(running_medians([])) == []
    assert [f"{m:g}" for m in running_medians([5])] == ["5"]
    assert [f"{m:g}" for m in running_medians([1, 2, 3, 4])] == ["1", "1.5", "2", "2.5"]
    assert [f"{m:g}" for m in running_medians([3, 1, 2])] == ["3", "2", "2"]
    print("ok", file=sys.stderr)
```

Each insertion is O(log n), so the whole stream is O(n log n). Non-integer lines are skipped with a warning rather than crashing the run.

```cpp
#include <cctype>
#include <iostream>
#include <string>

bool is_palindrome(const std::string& s) {
    std::size_t i = 0, j = s.size();
    while (i < j) {
        unsigned char a = static_cast<unsigned char>(s[i]);
        unsigned char b = static_cast<unsigned char>(s[j - 1]);
        if (!std::isalnum(a)) { ++i; continue; }
        if (!std::isalnum(b)) { --j; continue; }
        if (std::tolower(a) != std::tolower(b)) return false;
        ++i;
        --j;
    }
    return true;
}

int main() {
    struct Case { std::string in; bool want; };
    const Case cases[] = {
        {"", true},
        {"A man, a plan, a canal: Panama", true},
        {"race a car", false},
        {"No 'x' in Nixon", true},
        {"!!!", true},
        {"ab", false},
    };
    for (const auto& c : cases) {
        bool got = is_palindrome(c.in);
        std::cout << (got == c.want ? "PASS " : "FAIL ") << c.in << '\n';
        if (got != c.want) return 1;
    }
    std::cout << "all passed\n";
    return 0;
}
```

The two-pointer scan skips punctuation and digits on both ends. Casting to `unsigned char` before `isalnum`/`tolower` is required because passing a negative `char` is undefined behaviour. It compares raw bytes, so multi-byte UTF-8 sequences are treated as opaque — correct for ASCII palindromes, and it never reads out of bounds.

```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), size_(0) {}

    bool push(int value) {
        if (size_ == cap_) return false;
        buf_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int v = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::vector<int> buf_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    std::cout << "empty pop: " << (rb.pop() ? "value" : "nullopt") << '\n';
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << '\n';  // 111
    std::cout << rb.push(4) << '\n';                              // 0 (full)
    std::cout << "size=" << rb.size() << '\n';                    // 3
    std::cout << *rb.pop() << *rb.pop() << '\n';                  // 12
    std::cout << rb.push(4) << rb.push(5) << '\n';                // 11
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << "\nsize=" << rb.size() << '\n';                  // 0
}
```

Capacity 0 is a valid construction: `push` then always returns false and `pop` returns `std::nullopt`, since the modulo branch is never reached with `size_ == 0`. Wraparound is handled with modular indexing rather than shifting elements.

```cpp
#include <cstdint>
#include <iostream>

constexpr std::int64_t MOD = 1000000007;

// Returns {F(n), F(n+1)} modulo MOD.
std::pair<std::int64_t, std::int64_t> fib_pair(std::int64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    std::int64_t c = a * ((2 * b % MOD - a + MOD) % MOD) % MOD;  // F(2k)
    std::int64_t d = (a * a % MOD + b * b % MOD) % MOD;          // F(2k+1)
    if (n & 1) return {d, (c + d) % MOD};
    return {c, d};
}

std::int64_t fib_mod(std::int64_t n) { return fib_pair(n).first; }

int main() {
    struct Case { std::int64_t n; std::int64_t want; };
    const Case cases[] = {
        {0, 0}, {1, 1}, {2, 1}, {3, 2}, {10, 55}, {50, 586268941}, {90, 283062378},
    };
    for (const auto& c : cases) {
        auto got = fib_mod(c.n);
        std::cout << "F(" << c.n << ") = " << got << '\n';
        if (got != c.want) { std::cout << "FAIL want " << c.want << '\n'; return 1; }
    }
    std::cout << "all passed\n";
    return 0;
}
```

Fast doubling gives O(log n) time and O(log n) stack. All multiplications stay under `int64` because operands are already reduced below 1e9+7. The expected values for F(50) and F(90) are the true Fibonacci numbers reduced mod 1e9+7.

