use std::collections::HashMap;

fn parse_pairs(input: &str) -> Result<(HashMap<String, String>, Vec<String>), String> {
    let mut map = HashMap::new();
    let mut dupes = Vec::new();
    for (idx, field) in input.split(';').enumerate() {
        let field = field.trim();
        if field.is_empty() {
            continue;
        }
        let (key, value) = field
            .split_once('=')
            .ok_or_else(|| format!("field {idx} missing '=': {field:?}"))?;
        let key = key.trim().to_string();
        if map.insert(key.clone(), value.trim().to_string()).is_some() {
            dupes.push(key);
        }
    }
    Ok((map, dupes))
}

fn main() {
    let (m, d) = parse_pairs(" a = 1 ; b=2 ; a = 3 ;  ; c=").unwrap();
    assert_eq!(m.get("a").map(String::as_str), Some("3"));
    assert_eq!(m.get("c").map(String::as_str), Some(""));
    assert_eq!(m.len(), 3);
    assert_eq!(d, vec!["a".to_string()]);

    assert!(parse_pairs("novalue").is_err());
    assert!(parse_pairs("").unwrap().0.is_empty());

    println!("ok");
}
