class QueueViaStacks:
    """FIFO queue built from two LIFO stacks.

    Each element is pushed once and moved between stacks at most once,
    so the amortized cost per operation is O(1) even though a single
    dequeue can be O(n) when the output stack must be refilled.
    """

    def __init__(self):
        self._inbox = []
        self._outbox = []

    def enqueue(self, item):
        self._inbox.append(item)

    def dequeue(self):
        if not self._outbox:
            while self._inbox:
                self._outbox.append(self._inbox.pop())
        if not self._outbox:
            raise IndexError("dequeue from empty queue")
        return self._outbox.pop()

    def peek(self):
        if not self._outbox:
            while self._inbox:
                self._outbox.append(self._inbox.pop())
        if not self._outbox:
            raise IndexError("peek on empty queue")
        return self._outbox[-1]

    def __len__(self):
        return len(self._inbox) + len(self._outbox)


if __name__ == "__main__":
    q = QueueViaStacks()
    for i in range(1, 6):
        q.enqueue(i)
    assert q.dequeue() == 1
    assert q.peek() == 2
    q.enqueue(6)
    assert [q.dequeue() for _ in range(5)] == [2, 3, 4, 5, 6]
    try:
        q.dequeue()
        raise AssertionError("should have raised")
    except IndexError:
        pass
    print("all checks passed")
