/* Reverse the NUL-terminated string s in place. Safe for empty strings
 * (strlen returns 0, the swap loop never runs). */
void reverse_string(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    for (size_t i = 0; i < len / 2; ++i) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
}

