template <typename T, std::size_t N>
class RingBuffer {
public:
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

    bool push(const T& value) {
        if (full()) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    bool pop(T& out) {
        if (empty()) return false;
        out = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return true;
    }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.empty());
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.full());
    assert(!rb.push(4)); // overflow rejected

    int v = 0;
    assert(rb.pop(v) && v == 1);
    assert(rb.pop(v) && v == 2);
    assert(rb.push(4)); // room again after popping
    assert(rb.pop(v) && v == 3);
    assert(rb.pop(v) && v == 4);
    assert(rb.empty());
    assert(!rb.pop(v));  // underflow rejected
    std::cout << "all checks passed\n";
    return 0;
}
