def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring of s.

    Uses Manacher-style expansion from each center, O(n^2) worst case.
    Empty input returns the empty string.
    """
    if not s:
        return ""

    start, end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        # odd-length center
        l1, r1 = expand(i, i)
        # even-length center
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["", "a", "babad", "cbbd", "forgeeksskeegfor", "\u4f60\u597d\u597d\u4f60"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
