    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


def fib_fast(n: int) -> int:
    """O(log n) fast doubling: F(2k)=F(k)*(2F(k+1)-F(k)), F(2k+1)=F(k+1)^2+F(k)^2."""
    def pair(k: int):
        if k == 0:
            return 0, 1
        a, b = pair(k >> 1)
        c = a * (2 * b - a)
        d = a * a + b * b
        return (d, c + d) if k & 1 else (c, d)
    return pair(n)[0]


if __name__ == "__main__":
    n = 40
    base = [fib(i) for i in range(n)]
    assert all(a == b for a, b in zip(base, (fib_fast(i) for i in range(n))))
    print(base[:10], "...", base[-1])
