fn is_balanced(src: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    let chars: Vec<char> = src.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        match chars[i] {
            '(' | '[' | '{' => stack.push(chars[i]),
            ')' => if stack.pop() != Some('(') { return false; },
            ']' => if stack.pop() != Some('[') { return false; },
            '}' => if stack.pop() != Some('{') { return false; },
            '"' => {
                i += 1;
                while i < chars.len() && chars[i] != '"' {
                    if chars[i] == '\\' { i += 1; }
                    i += 1;
                }
            }
            '/' if i + 1 < chars.len() && chars[i + 1] == '/' => {
                while i < chars.len() && chars[i] != '\n' { i += 1; }
            }
            _ => {}
        }
        i += 1;
    }
    stack.is_empty()
}

fn main() {
    let ok = is_balanced("fn f() { let s = \"{[(\"; } // }");
    let bad = is_balanced("fn f() { let v = vec![1, 2;");
    assert!(ok);
    assert!(!bad);
    assert!(is_balanced(""));
    println!("balanced={ok} unbalanced={bad}");
}
