fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() || j < b.len() {
        let next = if j >= b.len() || (i < a.len() && a[i] <= b[j]) {
            let v = a[i];
            i += 1;
            v
        } else {
            let v = b[j];
            j += 1;
            v
        };

        if out.last() != Some(&next) {
            out.push(next);
        }
    }

    out
}

fn main() {
    assert_eq!(merge_sorted(&[1, 3, 3, 5], &[2, 3, 6]), vec![1, 2, 3, 5, 6]);
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[], &[7, 7, 7]), vec![7]);
    assert_eq!(merge_sorted(&[-2, -1], &[-1, 0]), vec![-2, -1, 0]);
    println!("ok");
}
