```python
from collections import OrderedDict
from typing import Any, Optional


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: "OrderedDict[Any, Any]" = OrderedDict()

    def get(self, key: Any) -> Optional[Any]:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: Any, value: Any) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1        # 'a' is now most-recent
    c.put("c", 3)                 # evicts 'b'
    assert c.get("b") is None
    assert c.get("c") == 3
    c.put("c", 30)                # update in place
    assert c.get("c") == 30
    print("ok")
```

`move_to_end` refreshes recency on both `get` and updates, and `popitem(last=False)` evicts the least-recently used entry in O(1).

```c
#include <stddef.h>
#include <stdio.h>

int binary_search(const int *arr, size_t n, int target) {
    if (arr == NULL || n == 0) {
        return -1;
    }

    size_t lo = 0;
    size_t hi = n;  // exclusive upper bound

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;  // avoids overflow
        if (arr[mid] == target) {
            return (int)mid;
        } else if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

int main(void) {
    int data[] = {-9, -3, 0, 4, 4, 7, 12};
    size_t n = sizeof(data) / sizeof(data[0]);

    if (binary_search(data, n, 7) != 5) return 1;
    if (binary_search(data, n, -9) != 0) return 1;
    if (binary_search(data, n, 12) != 6) return 1;
    if (binary_search(data, n, 5) != -1) return 1;
    if (binary_search(NULL, 0, 1) != -1) return 1;
    puts("ok");
    return 0;
}
```

The half-open `[lo, hi)` range with `lo + (hi - lo) / 2` is overflow-safe and terminates cleanly for empty input and absent targets.

