use std::fmt;

#[derive(Debug, PartialEq)]
struct Record {
    name: String,
    age: u32,
    score: f64,
}

#[derive(Debug, PartialEq)]
enum ParseError {
    WrongFieldCount(usize),
    EmptyName,
    BadAge,
    BadScore,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::WrongFieldCount(n) => write!(f, "expected 3 fields, got {n}"),
            ParseError::EmptyName => write!(f, "name is empty"),
            ParseError::BadAge => write!(f, "age is not a valid u32"),
            ParseError::BadScore => write!(f, "score is not a valid f64"),
        }
    }
}

impl std::error::Error for ParseError {}

fn parse_row(row: &str) -> Result<Record, ParseError> {
    let fields: Vec<&str> = row.split(',').map(str::trim).collect();
    if fields.len() != 3 {
        return Err(ParseError::WrongFieldCount(fields.len()));
    }

    let name = fields[0];
    if name.is_empty() {
        return Err(ParseError::EmptyName);
    }

    let age = fields[1].parse::<u32>().map_err(|_| ParseError::BadAge)?;
    let score = fields[2].parse::<f64>().map_err(|_| ParseError::BadScore)?;

    Ok(Record { name: name.to_string(), age, score })
}

fn main() {
    let r = parse_row(" Ada , 41 , 98.5 ").unwrap();
    assert_eq!(r.name, "Ada");
    assert_eq!(r.age, 41);
    assert_eq!(r.score, 98.5);

    assert_eq!(parse_row("only,name").unwrap_err(), ParseError::WrongFieldCount(2));
    assert_eq!(parse_row(" , 20, 1.0").unwrap_err(), ParseError::EmptyName);
    assert_eq!(parse_row("A, -3, 1.0").unwrap_err(), ParseError::BadAge);
    assert_eq!(parse_row("A, 3, x").unwrap_err(), ParseError::BadScore);
    println!("ok");
}
```

Each failure maps to a specific variant so callers can react programmatically; `?` propagates the first error encountered, and trailing whitespace is trimmed.

