fn longest_common_prefix(words: &[&str]) -> String {
    let first = match words.first() {
        Some(w) => *w,
        None => return String::new(),
    };

    let mut end = first.len();
    for word in &words[1..] {
        end = end.min(word.len());
        while !word.is_char_boundary(end) || &first[..end] != &word[..end] {
            if end == 0 {
                return String::new();
            }
            end -= 1;
        }
    }
    first[..end].to_string()
}

