#include <cstddef>
#include <iostream>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : cap_(capacity), buf_(capacity), head_(0), size_(0) {}

    void push(int value) {
        if (cap_ == 0) return;
        buf_[(head_ + size_) % cap_] = value;
        if (size_ < cap_) {
            ++size_;
        } else {
            head_ = (head_ + 1) % cap_;
        }
    }

    std::vector<int> to_vector() const {
        std::vector<int> out;
        out.reserve(size_);
        for (std::size_t i = 0; i < size_; ++i) {
            out.push_back(buf_[(head_ + i) % cap_]);
        }
        return out;
    }

    void print() const {
        std::cout << '[';
        for (std::size_t i = 0; i < size_; ++i) {
            if (i) std::cout << ", ";
            std::cout << buf_[(head_ + i) % cap_];
        }
        std::cout << "]\n";
    }

private:
    std::size_t cap_, head_, size_;
    std::vector<int> buf_;
};

int main() {
    RingBuffer rb(3);
    rb.push(1); rb.push(2); rb.print();      // [1, 2]
    rb.push(3); rb.push(4); rb.print();      // [2, 3, 4]
    RingBuffer zero(0);
    zero.push(9); zero.print();              // []
    return 0;
}
