```python
def parse_ini(text):
    result = {}
    current = None
    seen = set()
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith((";", "#")):
            continue
        if line.startswith("[") and line.endswith("]"):
            current = line[1:-1].strip()
            if not current:
                raise ValueError(f"line {lineno}: empty section name")
            result.setdefault(current, {})
            continue
        if "=" not in line:
            raise ValueError(f"line {lineno}: missing '='")
        if current is None:
            raise ValueError(f"line {lineno}: key outside any section")
        key, _, value = line.partition("=")
        key = key.strip()
        if not key:
            raise ValueError(f"line {lineno}: empty key")
        marker = (current, key)
        if marker in seen:
            raise ValueError(f"line {lineno}: duplicate key {key!r} in [{current}]")
        seen.add(marker)
        result[current][key] = value.strip()
    return result


if __name__ == "__main__":
