    char *out = s;
    int in_space = 0;
    for (char *p = s; *p; ++p) {
        if (*p == ' ') {
            if (!in_space) *out++ = ' ';
            in_space = 1;
        } else {
            *out++ = *p;
            in_space = 0;
        }
    }
    *out = '\0';
}

