std::optional<long long> parse_integer(const std::string& s) {
    size_t i = 0;
    while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) i++;
    if (i == s.size()) return std::nullopt;
    bool neg = false;
    if (s[i] == '+' || s[i] == '-') {
        neg = (s[i] == '-');
        i++;
    }
    if (i == s.size() || !std::isdigit(static_cast<unsigned char>(s[i]))) return std::nullopt;
    long long value = 0;
    for (; i < s.size() && std::isdigit(static_cast<unsigned char>(s[i])); i++) {
        value = value * 10 + (s[i] - '0');
    }
    while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) i++;
    if (i != s.size()) return std::nullopt;
    return neg ? -value : value;
}

int main() {
    std::cout << parse_integer("  -42 ").value_or(999) << '\n';
    std::cout << (parse_integer("12abc").has_value() ? "yes" : "no") << '\n';
    std::cout << (parse_integer("").has_value() ? "yes" : "no") << '\n';
