class StackFullError(Exception):
    pass


class Stack:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._items = []
        self._capacity = capacity

    def push(self, value):
        if len(self._items) >= self._capacity:
            raise StackFullError(f"stack full ({self._capacity})")
        self._items.append(value)

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self):
        return self._items[-1] if self._items else None

    def __len__(self):
        return len(self._items)


if __name__ == "__main__":
    s = Stack(2)
    s.push("a")
    s.push("b")
    try:
        s.push("c")
    except StackFullError as exc:
        print("caught:", exc)
    assert s.pop() == "b"
    assert s.peek() == "a"
    assert len(s) == 1
```
The constructor rejects a zero or negative capacity. `peek` returns `None` on an empty stack rather than raising, which is a deliberate choice documented by the signature.

```cpp
#include <cassert>
#include <iostream>
#include <list>
#include <stdexcept>
#include <unordered_map>

template <typename Key, typename Value>
class LruCache {
public:
    explicit LruCache(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be > 0");
        }
    }

    bool get(const Key& key, Value& out) {
        auto it = index_.find(key);
        if (it == index_.end()) {
            return false;
        }
        items_.splice(items_.begin(), items_, it->second);
        out = it->second->second;
        return true;
    }

    void put(const Key& key, const Value& value) {
        auto it = index_.find(key);
        if (it != index_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (items_.size() == capacity_) {
            index_.erase(items_.back().first);
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        index_[key] = items_.begin();
    }

    std::size_t size() const { return items_.size(); }

private:
    using Entry = std::pair<Key, Value>;
    using ListIt = typename std::list<Entry>::iterator;

    std::size_t capacity_;
    std::list<Entry> items_;
    std::unordered_map<Key, ListIt> index_;
};

int main() {
    LruCache<int, int> cache(2);
    cache.put(1, 10);
    cache.put(2, 20);

    int v = 0;
    assert(cache.get(1, v) && v == 10);   // touch 1, so 2 is now LRU
    cache.put(3, 30);                      // evicts 2
    assert(!cache.get(2, v));
    assert(cache.get(1, v) && v == 10);
    assert(cache.get(3, v) && v == 30);
    assert(cache.size() == 2);

    cache.put(1, 99);                      // update in place
    assert(cache.get(1, v) && v == 99);
    assert(cache.size() == 2);

    std::cout << "ok\n";
}
```

A `std::list` keeps recency order (front = most recent) and an `unordered_map` points at each node, so both operations are O(1). `splice` moves a hit to the front without reallocating.

