static std::string trim(const std::string& s) {
    std::size_t begin = 0;
    std::size_t end = s.size();
    auto space = [](unsigned char c) { return std::isspace(c) != 0; };
    while (begin < end && space(static_cast<unsigned char>(s[begin]))) ++begin;
    while (end > begin && space(static_cast<unsigned char>(s[end - 1]))) --end;
    return s.substr(begin, end - begin);
}

std::map<std::string, std::string> parseConfig(const std::string& text) {
    std::map<std::string, std::string> config;
    std::istringstream stream(text);
    std::string line;
    while (std::getline(stream, line)) {
        std::string t = trim(line);
        if (t.empty() || t[0] == '#') {
            continue;
        }
        auto eq = t.find('=');
        if (eq == std::string::npos) {
            continue;  // malformed line, ignore
        }
        std::string key = trim(t.substr(0, eq));
        std::string value = trim(t.substr(eq + 1));
        if (!key.empty()) {
            config[key] = value;
        }
    }
    return config;
}

int main() {
    const std::string text =
        "# server config\n"
        "host = 127.0.0.1\n"
        "\n"
        "  port=8080  \n"
        "bogus line\n"
        "empty_value=\n";

    auto cfg = parseConfig(text);
    std::cout << cfg.size() << "\n";          // 3
    std::cout << cfg["host"] << "\n";        // 127.0.0.1
    std::cout << cfg["port"] << "\n";        // 8080
    std::cout << "[" << cfg["empty_value"] << "]\n";  // []
}
