```rust
/// Encode a byte slice as (count, byte) pairs.
pub fn rle_encode(input: &[u8]) -> Vec<(usize, u8)> {
    let mut out = Vec::new();
    let mut iter = input.iter().copied();

    let Some(mut current) = iter.next() else {
        return out;
    };
    let mut run = 1usize;

    for byte in iter {
        if byte == current {
            run += 1;
        } else {
            out.push((run, current));
            current = byte;
            run = 1;
        }
    }
    out.push((run, current));
    out
}

/// Decode (count, byte) pairs. Returns Err on a zero-length run.
pub fn rle_decode(pairs: &[(usize, u8)]) -> Result<Vec<u8>, String> {
    let mut out = Vec::new();
    for &(count, byte) in pairs {
        if count == 0 {
            return Err("run length must be > 0".to_string());
        }
        out.extend(std::iter::repeat(byte).take(count));
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty() {
        assert!(rle_encode(&[]).is_empty());
        assert_eq!(rle_decode(&[]).unwrap(), Vec::<u8>::new());
    }

    #[test]
    fn round_trip() {
        let data = b"aaabbccccd".to_vec();
        let encoded = rle_encode(&data);
        assert_eq!(encoded, vec![(3, b'a'), (2, b'b'), (4, b'c'), (1, b'd')]);
        assert_eq!(rle_decode(&encoded).unwrap(), data);
    }

    #[test]
    fn single_and_no_repeat() {
        assert_eq!(rle_encode(b"x"), vec![(1, b'x')]);
        assert_eq!(rle_encode(b"abc"), vec![(1, b'a'), (1, b'b'), (1, b'c')]);
    }

    #[test]
    fn zero_run_is_error() {
        assert!(rle_decode(&[(0, b'a')]).is_err());
    }
}

fn main() {
    let encoded = rle_encode(b"aaabbccccd");
    println!("{:?}", encoded);
}
```

Decoding a zero-length run is rejected rather than silently dropped, so malformed input can't vanish. The empty slice is handled before the loop so no dummy sentinel is needed.

