import time
from functools import wraps


class RateLimiter:
    """Allow at most `max_calls` per `window_seconds` per key."""

    def __init__(self, max_calls, window_seconds, clock=time.monotonic):
        if max_calls < 1:
            raise ValueError("max_calls must be >= 1")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be > 0")
        self._max_calls = max_calls
        self._window = window_seconds
        self._clock = clock
        self._hits = {}  # key -> list of timestamps inside the window

    def allow(self, key):
        now = self._clock()
        stamps = self._hits.setdefault(key, [])
        cutoff = now - self._window
        while stamps and stamps[0] <= cutoff:
            stamps.pop(0)
        if len(stamps) >= self._max_calls:
            return False
        stamps.append(now)
        return True

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = func.__qualname__
            if not self.allow(key):
                raise RuntimeError(f"rate limit exceeded for {key}")
            return func(*args, **kwargs)

        return wrapper


if __name__ == "__main__":
    fake = [0.0]
    limiter = RateLimiter(2, 10.0, clock=lambda: fake[0])

    assert limiter.allow("k") is True
    assert limiter.allow("k") is True
    assert limiter.allow("k") is False     # window full
    fake[0] = 11.0
    assert limiter.allow("k") is True     # old stamps expired
    assert limiter.allow("other") is True  # separate key unaffected

    @limiter
    def work():
        return "done"

    print(work())
    print("ok")
```

Timestamps for a key are pruned from the front on each call, so only hits inside the window count. The clock is injectable, which makes the test deterministic instead of sleeping.

Two heaps give the median in O(log n) per insert. `low` is a max-heap, `high` a min-heap; we rebalance so `low.size()` is `high.size()` or one larger.

```cpp
#include <cstdio>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<long long> low;                              // max-heap
    std::priority_queue<long long, std::vector<long long>,
                        std::greater<long long>> high;               // min-heap

    long long x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) {
            low.push(x);
        } else {
            high.push(x);
        }
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        if (low.size() == high.size()) {
            std::printf("%.1f\n", (low.top() + high.top()) / 2.0);
        } else {
            std::printf("%lld\n", low.top());
        }
    }
    return 0;
}
```

With input `5 15 1 3`, the medians print as `5.0`, `10.0`, `5.0`, `4.0`. If `low.size()` and `high.size()` are equal, the median is the average of the two tops; otherwise it is `low.top()`. Input that overflows `long long` is not handled.

One pass with a `HashMap<value, index>` is O(n) time and O(n) space. Checking the map before inserting the current element prevents pairing a number with itself.

```rust
use std::collections::HashMap;

/// Return indices (i, j) with i < j such that values[i] + values[j] == target.
fn two_sum(values: &[i64], target: i64) -> Result<(usize, usize), String> {
    let mut seen: HashMap<i64, usize> = HashMap::new();
    for (j, &v) in values.iter().enumerate() {
        let need = target - v;
        if let Some(&i) = seen.get(&need) {
            return Ok((i, j));
        }
        seen.insert(v, j);
    }
    Err(format!("no two values sum to {target}"))
}

fn main() {
    assert_eq!(two_sum(&[2, 7, 11, 15], 9), Ok((0, 1)));
    assert_eq!(two_sum(&[3, 2, 4], 6), Ok((1, 2)));
    assert!(two_sum(&[1, 2, 3], 100).is_err());
    assert!(two_sum(&[], 0).is_err());
    println!("{:?}", two_sum(&[3, 2, 4], 6));
}
```

The self-pair case is avoided because the current index is inserted only after the lookup. The subtraction `target - v` can overflow `i64` on extreme inputs; use `checked_sub` if the values can be near `i64::MAX`.

