#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL || *s == '\0') {
        return;
    }
    char *left = s;
    char *right = s + strlen(s) - 1;
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char empty[] = "";
    char word[] = "hello";
    char even[] = "ab";

    reverse_in_place(empty);
    reverse_in_place(word);
    reverse_in_place(even);
    reverse_in_place(NULL);

    if (strcmp(empty, "") != 0) return 1;
    if (strcmp(word, "olleh") != 0) return 1;
    if (strcmp(even, "ba") != 0) return 1;
    puts("ok");
    return 0;
}
```

Only the two pointers and one `char` temporary are used, so memory is O(1). A single-character string has `left == right` and the loop never runs. The `NULL` check keeps the function safe if a caller passes a null pointer, though a real API might prefer to document that as undefined.

```cpp
#include <iostream>
#include <vector>

template <typename T>
std::vector<T> flatten(const std::vector<std::vector<T>>& nested) {
    std::size_t total = 0;
    for (const auto& inner : nested) {
        total += inner.size();
    }

    std::vector<T> flat;
    flat.reserve(total);
    for (const auto& inner : nested) {
        flat.insert(flat.end(), inner.begin(), inner.end());
    }
    return flat;
}

int main() {
    std::vector<std::vector<int>> input = {{1, 2}, {}, {3}, {4, 5, 6}};
    std::vector<int> out = flatten(input);
    for (int v : out) std::cout << v << ' ';
    std::cout << '\n';

    std::vector<std::vector<int>> empty;
    std::cout << flatten(empty).size() << '\n';   // 0
    return 0;
}
```

Counting sizes first lets `reserve` allocate once, avoiding reallocation during insertion; the total is `sum(inner.size())` which fits the output. Empty inner vectors contribute nothing, and `flatten({})` returns an empty vector. The type `T` must be copyable for `insert`, which is fine for plain integers; move-only types would need a different loop.

