```c
#include <stdio.h>
#include <string.h>

#define MAX_LEN 1024

static int is_balanced(const char *s) {
    char stack[MAX_LEN];
    size_t top = 0;

    for (; *s; s++) {
        char c = *s;
        if (c == '(' || c == '[' || c == '{') {
            if (top >= MAX_LEN) return 0;   // overflow guard
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) return 0;
            char open = stack[--top];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return 0;
            }
        }
    }
    return top == 0;
}

int main(void) {
    const char *cases[] = {"()[]{}", "([{}])", "(]", "((", ")]}", ""};
    for (int i = 0; i < 6; i++) {
        printf("%s -> %s\n", cases[i], is_balanced(cases[i]) ? "yes" : "no");
    }
    return 0;
}
```

A closing bracket with an empty stack (`")]}"`) fails immediately, as does leftover input like `"(("`. Non-bracket characters are ignored. `MAX_LEN` caps the stack; if inputs could exceed it, allocate the stack dynamically from `strlen(s)`.

