```cpp
#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse_list(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);

    head = reverse_list(head);

    int expected[] = {3, 2, 1};
    int i = 0;
    for (Node* cur = head; cur != nullptr; cur = cur->next) {
        if (cur->value != expected[i++]) { std::cout << "FAIL\n"; return 1; }
    }
    std::cout << (i == 3 ? "ok" : "FAIL") << "\n";

    while (head) { Node* nxt = head->next; delete head; head = nxt; }
    return 0;
}
```
Three pointers (`prev`, `head`, `nxt`) walk the list once in O(n) time, relinking each node's `next` backwards; the empty list returns `nullptr` unchanged.

