```rust
use std::cmp::Ordering;

fn binary_search<T: Ord>(slice: &[T], target: &T) -> Result<usize, usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            Ordering::Less => lo = mid + 1,
            Ordering::Greater => hi = mid,
            Ordering::Equal => return Ok(mid),
        }
    }
    Err(lo)
}

fn main() {
    let data = [1, 3, 5, 7, 9];
    assert_eq!(binary_search(&data, &1), Ok(0));
    assert_eq!(binary_search(&data, &9), Ok(4));
    assert_eq!(binary_search(&data, &4), Err(2));

    let empty: [i32; 0] = [];
    assert_eq!(binary_search(&empty, &5), Err(0));
    println!("ok");
}
```

`Err(position)` is the insertion index where the target would go, matching `slice::binary_search`. The midpoint uses `lo + (hi - lo) / 2` to avoid overflow on large ranges.

