```python
def evaluate(expr: str) -> float:
    tokens = list(expr.replace(" ", ""))
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def expr_():
        nonlocal pos
        value = term()
        while peek() in ("+", "-"):
            op = tokens[pos]
            pos += 1
            rhs = term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def term():
        nonlocal pos
        value = factor()
        while peek() in ("*", "/"):
            op = tokens[pos]
            pos += 1
            rhs = factor()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value /= rhs
        return value

    def factor():
        nonlocal pos
        if peek() == "-":
            pos += 1
            return -factor()
        if peek() == "(":
            pos += 1
            value = expr_()
            if peek() != ")":
                raise ValueError("unbalanced parentheses")
            pos += 1
            return value
        start = pos
        while peek() is not None and (peek().isdigit() or peek() == "."):
            pos += 1
        if start == pos:
            raise ValueError(f"unexpected token at {pos}")
        return float("".join(tokens[start:pos]))

    result = expr_()
    if pos != len(tokens):
        raise ValueError("trailing input")
    return result


if __name__ == "__main__":
    assert evaluate("2 + 3 * 4") == 14
    assert evaluate("(2 + 3) * 4") == 20
    assert evaluate("-3 + 1") == -2
    assert evaluate("10 / 4") == 2.5
    print("ok")
```

Operator precedence falls out of the grammar: `term` binds tighter than `expr_`, and parentheses recurse back into `expr_`. Each level consumes its tokens left to right.

