fn integer_sqrt(n: i64) -> Option<u64> {
    if n < 0 {
        return None;
    }
    let n = n as u64;
    if n < 2 {
        return Some(n);
    }
    let (mut low, mut high) = (1u64, n / 2);
    let mut answer = 1u64;
    while low <= high {
        let mid = low + (high - low) / 2;
        match mid.checked_mul(mid) {
            Some(sq) if sq <= n => {
                answer = mid;
                low = mid + 1;
            }
            _ => high = mid - 1,
        }
    }
    Some(answer)
}

fn main() {
    assert_eq!(integer_sqrt(-4), None);
    assert_eq!(integer_sqrt(0), Some(0));
    assert_eq!(integer_sqrt(15), Some(3));
    assert_eq!(integer_sqrt(16), Some(4));
    assert_eq!(integer_sqrt(1000000), Some(1000));
    println!("{:?}", integer_sqrt(100));
}
