import re

_RELEASE_ORDER = {"dev": 0, "alpha": 1, "beta": 2, "rc": 3, "": 4, "post": 5}


def parse_version(text: str) -> tuple:
    """Turn '1.2.3-rc.4' into ('1.2.3', 3, 4, text).

    The trailing raw string keeps equal-numeric versions ordered stably.
    """
    match = re.fullmatch(
        r"(\d+(?:\.\d+)*)(?:-([a-z]+)\.?(\d+)?)?", text.strip(), re.IGNORECASE
    )
    if not match:
        raise ValueError(f"not a version string: {text!r}")
    numeric, label, pre = match.groups()
    label = (label or "").lower()
    if label not in _RELEASE_ORDER:
        raise ValueError(f"unknown release label: {label!r}")
    return (numeric, _RELEASE_ORDER[label], int(pre or 0), text)


