#include <array>
#include <cstddef>
#include <mutex>
#include <optional>

// Fixed-capacity queue. push() overwrites the oldest element when full,
// so no caller ever blocks on a full buffer.
template <typename T, std::size_t Capacity>
class RingBuffer {
public:
    static_assert(Capacity > 0, "Capacity must be positive");

    void push(const T& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        data_[tail_] = value;
        tail_ = (tail_ + 1) % Capacity;
        if (size_ < Capacity) {
            ++size_;
        } else {
            head_ = (head_ + 1) % Capacity;  // evict oldest
        }
    }

    std::optional<T> pop() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % Capacity;
        --size_;
        return value;
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return size_;
    }

private:
    std::array<T, Capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
    mutable std::mutex mutex_;
};

#include <iostream>

int main() {
    RingBuffer<int, 3> buf;
    for (int i = 1; i <= 5; ++i) buf.push(i);  // 1 and 2 evicted
    while (auto v = buf.pop()) std::cout << *v << ' ';  // 3 4 5
    std::cout << '\n';
}
```

`pop()` uses `unique_lock` semantics only conceptually — a `lock_guard` is enough since we always hold the lock. For multi-producer throughput, swap in a `std::atomic` head/tail, but that is a much larger design.

