```rust
/// Merge overlapping or touching half-open intervals `[start, end)`.
/// Returns a new vector, sorted by start.
pub fn merge_intervals(mut intervals: Vec<(i64, i64)>) -> Vec<(i64, i64)> {
    intervals.sort_unstable();
    let mut merged: Vec<(i64, i64)> = Vec::with_capacity(intervals.len());
    for (start, end) in intervals {
        if start >= end {
            continue; // discard empty or inverted spans
        }
        match merged.last_mut() {
            Some(last) if start <= last.1 => last.1 = last.1.max(end),
            _ => merged.push((start, end)),
        }
    }
    merged
}

#[cfg(test)]
mod tests {
    use super::merge_intervals;

    #[test]
    fn merges_overlaps() {
        assert_eq!(merge_intervals(vec![(1, 4), (2, 6), (8, 10)]), vec![(1, 6), (8, 10)]);
    }

    #[test]
    fn keeps_touching_adjacent() {
        assert_eq!(merge_intervals(vec![(1, 2), (2, 3), (3, 4)]), vec![(1, 4)]);
    }

    #[test]
    fn handles_empty_and_inverted() {
        assert_eq!(merge_intervals(vec![]), vec![]);
        assert_eq!(merge_intervals(vec![(5, 5), (7, 6)]), vec![]);
    }
}
```

Adjacency merges because the test is `start <= last.1` (not `<`). If you want `[1,2)` and `[2,3)` to stay separate, change the comparison in the `match` guard.

