#[derive(Debug, PartialEq)]
pub enum ParseError {
    MissingEquals(String),
    EmptyKey,
    DuplicateKey(String),
}

pub fn parse_config(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    for line in input.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line
            .split_once('=')
            .ok_or_else(|| ParseError::MissingEquals(line.to_string()))?;
        let key = key.trim();
        if key.is_empty() {
            return Err(ParseError::EmptyKey);
        }
        let value = value.trim();
        if map.insert(key.to_string(), value.to_string()).is_some() {
            return Err(ParseError::DuplicateKey(key.to_string()));
        }
    }
    Ok(map)
}

fn main() {
    let text = "# app config\nhost = localhost\nport=8080\n";
    println!("{:?}", parse_config(text));
    // Ok({"host": "localhost", "port": "8080"})

    let bad = "a=1\na=2\n";
    println!("{:?}", parse_config(bad));
    // Err(DuplicateKey("a"))
}
