```python
import functools
import random
import time


def retry(attempts: int = 3, base_delay: float = 0.5, max_delay: float = 30.0,
          exceptions: tuple[type[BaseException], ...] = (Exception,)):
    """Retry a callable with exponential backoff plus full jitter.

    Raises the last caught exception once attempts are exhausted.
    """
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_error: BaseException | None = None
            for attempt in range(attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_error = exc
                    if attempt == attempts - 1:
                        break
                    ceiling = min(max_delay, base_delay * 2 ** attempt)
                    time.sleep(random.uniform(0, ceiling))
            assert last_error is not None
            raise last_error
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base_delay=0.01)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ConnectionError("temporary")
        return "ok"

    print(flaky(), calls["n"])   # ok 3
```

`random.uniform(0, ceiling)` is full jitter; use `ceiling / 2 + random.uniform(0, ceiling / 2)` if you want to guarantee a minimum wait. Catching bare `Exception` by default is broad — narrow it per call site.

