fn eval_rpn(expr: &str) -> Result<f64, String> {
    let mut stack: Vec<f64> = Vec::new();
    for token in expr.split_whitespace() {
        match token {
            "+" | "-" | "*" | "/" => {
                let b = stack.pop().ok_or_else(|| format!("missing operand for {token}"))?;
                let a = stack.pop().ok_or_else(|| format!("missing operand for {token}"))?;
                let value = match token {
                    "+" => a + b,
                    "-" => a - b,
                    "*" => a * b,
                    _ => {
                        if b == 0.0 {
                            return Err("division by zero".to_string());
                        }
                        a / b
                    }
                };
                stack.push(value);
            }
            _ => {
                let n: f64 = token
                    .parse()
                    .map_err(|_| format!("invalid token: {token}"))?;
                stack.push(n);
            }
        }
    }
    if stack.len() != 1 {
        return Err(format!("expected 1 result, got {}", stack.len()));
    }
    Ok(stack[0])
}

fn main() {
    assert_eq!(eval_rpn("3 4 + 2 *").unwrap(), 14.0);
    assert_eq!(eval_rpn("5").unwrap(), 5.0);
    assert!(eval_rpn("1 0 /").is_err());
    assert!(eval_rpn("").is_err());
    println!("ok");
}
