```cpp
#include <cassert>
#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v, Node* n = nullptr) : value(v), next(n) {}
};

Node* reverse_iterative(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

Node* reverse_recursive(Node* head) {
    if (head == nullptr || head->next == nullptr) {
        return head;
    }
    Node* new_head = reverse_recursive(head->next);
    head->next->next = head;
    head->next = nullptr;
    return new_head;
}

void push(Node*& head, int value) { head = new Node(value, head); }

bool equals(const Node* a, const Node* b) {
    while (a != nullptr && b != nullptr) {
        if (a->value != b->value) return false;
        a = a->next;
        b = b->next;
    }
    return a == nullptr && b == nullptr;
}

int main() {
    Node* head = nullptr;
    for (int v : {1, 2, 3, 4, 5}) push(head, v);

    Node* iterative = reverse_iterative(head);
    assert(iterative->value == 1);
    assert(iterative->next->value == 2);

    Node* recursive = reverse_recursive(iterative);
    assert(recursive->value == 5);
    assert(recursive->next->value == 4);

    assert(reverse_iterative(nullptr) == nullptr);
    assert(equals(reverse_recursive(nullptr), nullptr));

    std::cout << "all assertions passed\n";
    return 0;
}
```

The iterative version does the work in one pass with three pointers; the recursive one unwinds to the new head and then rewires each pair on the way back. Both handle an empty list and a single node.

```rust
fn is_palindrome(input: &str) -> bool {
    let chars: Vec<char> = input
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();

    let mut left = 0usize;
    let mut right = chars.len();
    while left < right {
        right -= 1;
        if chars[left] != chars[right] {
            return false;
        }
        left += 1;
    }
    true
}

fn main() {
    let cases = [
        ("", true),
        ("A man, a plan, a canal: Panama", true),
        ("race a car", false),
        ("No 'x' in Nixon", true),
        ("Was it a car or a cat I saw?", true),
        ("Straße", false),
    ];

    for (input, expected) in cases {
        let got = is_palindrome(input);
        assert_eq!(got, expected, "{input:?}");
        println!("{input:?} -> {got}");
    }
    println!("all cases passed");
}
```

`flat_map(to_lowercase)` is used instead of `to_ascii_lowercase` so characters whose lowercase form has several `char`s are handled without panicking. Filtering non-alphanumerics first means spaces and punctuation never enter the comparison, and the two-pointer scan avoids allocating a reversed copy.

```rust
use std::env;
use std::fs;
use std::io::{self, BufRead};
use std::process;

#[derive(Default)]
struct Stats {
    lines: u64,
    words: u64,
    bytes: u64,
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.is_empty() {
        eprintln!("usage: {} FILE...", env::args().next().unwrap_or_default());
        process::exit(2);
    }

    let mut failed = false;
    for path in &args {
        match count_file(path) {
            Ok(stats) => println!(
                "{:>8} {:>8} {:>8} {}",
                stats.lines, stats.words, stats.bytes, path
            ),
            Err(err) => {
                eprintln!("{path}: {err}");
                failed = true;
            }
        }
    }
    if failed {
        process::exit(1);
    }
}

fn count_file(path: &str) -> io::Result<Stats> {
    let file = fs::File::open(path)?;
    let mut stats = Stats::default();
    let mut reader = io::BufReader::new(file);
    let mut line = Vec::new();

    loop {
        line.clear();
        let read = reader.read_until(b'\n', &mut line)?;
        if read == 0 {
            break;
        }
        stats.lines += 1;
        stats.bytes += read as u64;
        stats.words += line
            .split(|b| b.is_ascii_whitespace())
            .filter(|chunk| !chunk.is_empty())
            .count() as u64;
    }

    Ok(stats)
}
```

Counting bytes through `read_until` avoids decoding UTF-8 entirely, so binary files won't panic. Each unreadable path is reported to stderr and the loop continues, but the process still exits non-zero so scripts can detect partial failure.

