#include <limits.h>
#include <stdio.h>
#include <string.h>

/* Writes the decimal form of value into buf and returns buf.
   buf must have room for at least 21 bytes (sign + 19 digits + NUL). */
char *int_to_ascii(long long value, char *buf) {
    char tmp[21];
    size_t n = 0;
    int negative = value < 0;

    unsigned long long magnitude;
    if (negative) {
        magnitude = (unsigned long long)(-(value + 1)) + 1ULL;
    } else {
        magnitude = (unsigned long long)value;
    }

    do {
        tmp[n++] = (char)('0' + (int)(magnitude % 10));
        magnitude /= 10;
    } while (magnitude > 0);

    size_t w = 0;
    if (negative) {
        buf[w++] = '-';
    }
    while (n > 0) {
        buf[w++] = tmp[--n];
    }
    buf[w] = '\0';
    return buf;
}

int main(void) {
    long long tests[] = {0, 7, -7, 12345, -12345, LLONG_MIN, LLONG_MAX};
    char buf[21];

    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); ++i) {
        char reference[21];
        snprintf(reference, sizeof reference, "%lld", tests[i]);
        int_to_ascii(tests[i], buf);
        printf("%-22lld -> %-22s %s\n", tests[i], buf,
               strcmp(buf, reference) == 0 ? "ok" : "MISMATCH");
    }
    return 0;
}
```

Negating `LLONG_MIN` overflows a signed type, so the magnitude is built as `-(value + 1) + 1` in `unsigned long long`. The digits are written backwards into a scratch buffer, then reversed into the output; the `do/while` guarantees `0` still prints one digit.

```python
import re
from typing import Iterable

LOCAL_RE = re.compile(r"^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+$")
DOMAIN_LABEL_RE = re.compile(r"^[A-Za-z0-9-]+$")


def validate(email: str) -> tuple[bool, str]:
    if not isinstance(email, str) or not email:
        return False, "empty"
    if email != email.strip():
        return False, "leading or trailing whitespace"
    if email.count("@") != 1:
        return False, "must contain exactly one '@'"

    local, domain = email.split("@")
    if not local or len(local) > 64:
        return False, "local part empty or longer than 64 chars"
    if local.startswith(".") or local.endswith(".") or ".." in local:
        return False, "local part has a misplaced dot"
    if not LOCAL_RE.match(local):
        return False, "local part has invalid characters"

    if not domain or len(domain) > 255 or "." not in domain:
        return False, "domain missing a dot or too long"
    labels = domain.split(".")
    for label in labels:
        if not label or len(label) > 63:
            return False, "domain has an empty or over-long label"
        if label.startswith("-") or label.endswith("-"):
            return False, "domain label starts or ends with '-'"
        if not DOMAIN_LABEL_RE.match(label):
            return False, "domain label has invalid characters"
    if len(labels[-1]) < 2 or not labels[-1].isalpha():
        return False, "top-level domain must be alphabetic"

    return True, "ok"


def report(emails: Iterable[str]) -> None:
    for email in emails:
        ok, reason = validate(email)
        print(f"{'PASS' if ok else 'FAIL'}  {email!r}  {reason}")


if __name__ == "__main__":
    report([
        "user@example.com",
        "first.last@sub.example.co",
        "@example.com",
        "user@@example.com",
        "user@example",
        "user@-example.com",
        "user..name@example.com",
        "  user@example.com",
    ])
```

This is a structural check, not proof the mailbox exists: it verifies shape and returns a specific reason on failure, so callers can log why a row was rejected instead of just a boolean. Each returned reason maps to exactly one branch, which makes the output easy to test.

