def longest_common_prefix(words):
    if not words:
        return ""
    if len(words) == 1:
        return words[0]
    prefix = words[0]
    for word in words[1:]:
        while not word.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

