#include <iostream>
#include <vector>

struct Node {
    int value;
    Node* next;
    Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    Node* curr = head;
    while (curr != nullptr) {
        Node* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

void print(Node* head) {
    for (Node* n = head; n != nullptr; n = n->next)
        std::cout << n->value << (n->next ? " -> " : "");
    std::cout << "\n";
}

int main() {
    // empty list
    print(reverse(nullptr));

    // single node
    Node* one = new Node(7);
    print(reverse(one));

    // multiple nodes
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    Node* rev = reverse(head);
    print(rev);

    while (rev) { Node* t = rev; rev = rev->next; delete t; }
    return 0;
}
```

