#include <cstddef>
#include <iostream>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), capacity_(capacity) {}

    void push(int value) {
        buf_[head_] = value;
        head_ = (head_ + 1) % capacity_;
        if (size_ < capacity_) ++size_;
    }

    void print() const {
        std::size_t start = (head_ + capacity_ - size_) % capacity_;
        for (std::size_t i = 0; i < size_; ++i) {
            std::cout << buf_[(start + i) % capacity_] << ' ';
        }
        std::cout << '\n';
    }

private:
    std::vector<int> buf_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    rb.push(1); rb.print();        // 1
    rb.push(2); rb.push(3);        // 1 2 3
    rb.print();
    rb.push(4); rb.print();        // 2 3 4 (oldest overwritten)
    return 0;
}
```

`head_` is the next slot to write, and printing starts `size_` slots behind it, so the buffer always yields the most recent values in order.

