#include <errno.h>
#include <limits.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

bool parse_int(const char *s, int *out) {
    if (s == NULL || out == NULL) return false;
    while (*s == ' ' || *s == '\t') s++;
    errno = 0;
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (end == s) return false;          /* no digits at all */
    while (*end == ' ' || *end == '\t') end++;
    if (*end != '\0') return false;      /* trailing junk */
    if (errno == ERANGE || v < INT_MIN || v > INT_MAX) return false;
    *out = (int)v;
    return true;
}

int main(void) {
    const char *tests[] = {"42", "-7", " 13 ", "999999999999999", "12x", "", NULL};
    for (int i = 0; tests[i] != NULL; i++) {
        int v = 0;
        printf("%s -> %s", tests[i][0] ? tests[i] : "<empty>",
               parse_int(tests[i], &v) ? "ok" : "fail");
        if (parse_int(tests[i], &v)) printf(" %d", v);
        putchar('\n');
    }
    return 0;
}
