import hashlib
import os
import sys
from collections import defaultdict


def sha256_of(path: str, chunk: int = 1 << 20) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while block := f.read(chunk):
            h.update(block)
    return h.hexdigest()


def main(root: str) -> int:
    if not os.path.isdir(root):
        print(f"not a directory: {root}", file=sys.stderr)
        return 2

    by_size = defaultdict(list)
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if not os.path.islink(os.path.join(dirpath, d))]
        for name in filenames:
            full = os.path.join(dirpath, name)
            if os.path.islink(full):
                continue
            try:
                by_size[os.path.getsize(full)].append(full)
            except OSError as exc:
                print(f"skip {full}: {exc}", file=sys.stderr)

    by_hash = defaultdict(list)
    for size, paths in by_size.items():
        if size == 0 or len(paths) < 2:
            continue
        for p in paths:
            try:
                by_hash[sha256_of(p)].append(p)
            except OSError as exc:
                print(f"skip {p}: {exc}", file=sys.stderr)

    wasted = 0
    for digest, paths in by_hash.items():
        if len(paths) < 2:
            continue
        size = os.path.getsize(paths[0])
        wasted += size * (len(paths) - 1)
        print(digest[:12], size, "bytes each")
        for p in paths:
            print("   ", p)
    print(f"wasted: {wasted} bytes")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1] if len(sys.argv) > 1 else "."))
```

Files are first bucketed by size, so hashing only runs on candidates that could possibly collide. Empty files are skipped because they are trivially identical. Wasted bytes count every copy after the first.

