fn luhn_ok(input: &str) -> bool {
    let digits: Vec<u32> = input
        .chars()
        .filter(|c| !c.is_whitespace())
        .filter_map(|c| c.to_digit(10))
        .collect();

    if digits.is_empty() || input.chars().filter(|c| !c.is_whitespace()).count() != digits.len() {
        return false;
    }

    let sum: u32 = digits
        .iter()
        .rev()
        .enumerate()
        .map(|(idx, &d)| {
            if idx % 2 == 1 {
                let doubled = d * 2;
                if doubled > 9 { doubled - 9 } else { doubled }
            } else {
                d
            }
        })
        .sum();
    sum % 10 == 0
}

fn main() {
    assert!(luhn_ok("4539 1488 0343 6467"));
    assert!(!luhn_ok("4539 1488 0343 6468"));
    assert!(!luhn_ok("abcd"));
    assert!(!luhn_ok(""));
    println!("all checks passed");
}
