```c
#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

#define CAP 8

typedef struct {
    unsigned char buf[CAP];
    size_t head;  /* next write index */
    size_t tail;  /* next read index  */
    size_t count;
} ring_t;

static void ring_init(ring_t *r) {
    r->head = r->tail = r->count = 0;
}

static bool ring_push(ring_t *r, unsigned char v) {
    if (r->count == CAP) return false;
    r->buf[r->head] = v;
    r->head = (r->head + 1) % CAP;
    r->count++;
    return true;
}

static bool ring_pop(ring_t *r, unsigned char *out) {
    if (r->count == 0) return false;
    *out = r->buf[r->tail];
    r->tail = (r->tail + 1) % CAP;
    r->count--;
    return true;
}

int main(void) {
    ring_t r;
    ring_init(&r);

    for (unsigned char c = 'a'; c <= 'h'; ++c) {
        ring_push(&r, c);
    }
    if (!ring_push(&r, 'x')) puts("full as expected");

    unsigned char v;
    while (ring_pop(&r, &v)) putchar(v);
    putchar('\n');              /* abcdefgh */
    if (!ring_pop(&r, &v)) puts("empty as expected");
    return 0;
}
```

`head` and `tail` are reduced modulo `CAP` after every access, so no index ever goes out of range. `count` distinguishes full from empty, which the index equality alone cannot. Both overflow and underflow return `false` instead of corrupting state.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)        # odd length
        l2, r2 = expand(i, i + 1)    # even length
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["", "a", "ab", "babad", "cbbd", "racecar", "abacdfgdcaba"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```

`longest_palindrome("babad")` returns `"bab"`, `"cbbd"` returns `"bb"`, empty string stays empty. Time is O(n^2), space O(1).

```python
def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []
    intervals.sort(key=lambda iv: iv[0])
    merged = [intervals[0][:]]
    for start, end in intervals[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged


if __name__ == "__main__":
    data = [[5, 7], [1, 3], [2, 6], [8, 10], [15, 18]]
    print(merge_intervals(data))      # [[1, 7], [8, 10], [15, 18]]
    print(merge_intervals([]))        # []
    print(merge_intervals([[1, 4], [4, 5]]))  # [[1, 5]]
```

Sorting first makes overlapping intervals adjacent, so a single left-to-right pass is enough. Touching intervals like `[1,4]` and `[4,5]` merge because the comparison uses `<=`.

