#include <iostream>
#include <list>
#include <optional>
#include <unordered_map>

class LRUCache {
public:
    explicit LRUCache(std::size_t cap) : cap_(cap) {}

    std::optional<int> get(int key) {
        auto it = map_.find(key);
        if (it == map_.end()) return std::nullopt;
        items_.splice(items_.begin(), items_, it->second);
        return it->second->second;
    }

    void put(int key, int value) {
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (items_.size() == cap_) {
            int evicted = items_.back().first;
            map_.erase(evicted);
            items_.pop_back();
            std::cout << "evict " << evicted << '\n';
        }
        items_.emplace_front(key, value);
        map_[key] = items_.begin();
    }

private:
    std::size_t cap_;
    std::list<std::pair<int, int>> items_;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> map_;
};

int main() {
    LRUCache cache(2);
    cache.put(1, 10);
    cache.put(2, 20);
    if (auto v = cache.get(1)) std::cout << "get(1)=" << *v << '\n';
    cache.put(3, 30);   // evicts 2
    cache.put(4, 40);   // evicts 1
    return 0;
}
```

The list holds most-recently-used at the front; `get` and `put` splice the touched node to the front. Evictions print `evict 2` then `evict 1`. Compile with `g++ -std=c++17 lru.cpp -o lru`.

