use std::collections::HashMap;
use std::fmt;

#[derive(Debug, PartialEq)]
enum ParseError {
    MissingEquals(String),
    EmptyKey(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::MissingEquals(l) => write!(f, "line has no '=': {:?}", l),
            ParseError::EmptyKey(l) => write!(f, "line has an empty key: {:?}", l),
        }
    }
}

fn parse_config(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    for raw in input.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line
            .split_once('=')
            .ok_or_else(|| ParseError::MissingEquals(line.to_string()))?;
        let key = key.trim();
        if key.is_empty() {
            return Err(ParseError::EmptyKey(line.to_string()));
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let cfg = "host = localhost\nport=8080\n# comment\n";
    match parse_config(cfg) {
        Ok(m) => println!("{:?}", m),
        Err(e) => eprintln!("error: {}", e),
    }
    assert!(parse_config("badline").is_err());
}
```

