#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t cap = 256, len = 0;
    char *buf = malloc(cap);
    if (!buf) {
        fputs("out of memory\n", stderr);
        return 1;
    }

    int c;
    while ((c = getchar()) != EOF && c != '\n') {
        if (len + 1 >= cap) {
            cap *= 2;
            char *grown = realloc(buf, cap);
            if (!grown) {
                free(buf);
                fputs("out of memory\n", stderr);
                return 1;
            }
            buf = grown;
        }
        if (isupper((unsigned char)c)) {
            buf[len++] = (char)tolower((unsigned char)c);
        } else if (islower((unsigned char)c)) {
            buf[len++] = (char)toupper((unsigned char)c);
        } else {
            buf[len++] = (char)c;
        }
    }
    buf[len] = '\0';
    puts(buf);
    free(buf);
    return 0;
}
```

