```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s FILE\n", argv[0]);
        return 2;
    }

    FILE *fp = fopen(argv[1], "r+b");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        perror("fseek end");
        fclose(fp);
        return 1;
    }
    long size = ftell(fp);
    if (size < 0) {
        perror("ftell");
        fclose(fp);
        return 1;
    }

    unsigned char buf[4096];
    long lo = 0, hi = size;
    while (lo < hi) {
        long chunk = (hi - lo) / 2;
        if (chunk > (long)sizeof(buf)) chunk = (long)sizeof(buf);
        if (chunk == 0) break;

        long lo2 = lo + chunk;
        long hi2 = hi - chunk;

        if (fseek(fp, lo, SEEK_SET) != 0) { perror("fseek lo"); fclose(fp); return 1; }
        if (fread(buf, 1, (size_t)chunk, fp) != (size_t)chunk) { perror("fread lo"); fclose(fp); return 1; }

        unsigned char back[4096];
        if (fseek(fp, hi2, SEEK_SET) != 0) { perror("fseek hi"); fclose(fp); return 1; }
        if (fread(back, 1, (size_t)chunk, fp) != (size_t)chunk) { perror("fread hi"); fclose(fp); return 1; }

        for (long i = 0; i < chunk; i++) {
            unsigned char t = buf[i];
            buf[i] = back[chunk - 1 - i];
            back[chunk - 1 - i] = t;
        }

        if (fseek(fp, lo, SEEK_SET) != 0) { perror("fseek w lo"); fclose(fp); return 1; }
        if (fwrite(buf, 1, (size_t)chunk, fp) != (size_t)chunk) { perror("fwrite lo"); fclose(fp); return 1; }
        if (fseek(fp, hi2, SEEK_SET) != 0) { perror("fseek w hi"); fclose(fp); return 1; }
        if (fwrite(back, 1, (size_t)chunk, fp) != (size_t)chunk) { perror("fwrite hi"); fclose(fp); return 1; }

        lo = lo2;
        hi = hi2;
    }

    fclose(fp);
    return 0;
}
```

The two 4 KiB buffers swap equal-length windows from each end inward, so memory stays constant regardless of file size. The middle byte of an odd-length file is left untouched when `lo == hi`.

```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    BoundedQueue(const BoundedQueue&) = delete;
    BoundedQueue& operator=(const BoundedQueue&) = delete;

    // Returns false if the queue is closed and no item can ever be pushed.
    bool push(int value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [&] { return closed_ || q_.size() < cap_; });
        if (closed_) return false;
        q_.push(value);
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;  // closed and drained
        int v = q_.front();
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mu_);
        return q_.empty();
    }

private:
    mutable std::mutex mu_;
    std::condition_variable not_empty_, not_full_;
    std::queue<int> q_;
    std::size_t cap_;
    bool closed_ = false;
};
```

`push` blocks while the queue is full and returns `false` once `close()` has been called; `pop` blocks on an empty queue and returns `nullopt` after close. Notifications happen after unlocking to avoid waking a waiter that then immediately blocks on the still-held mutex.

