// Writes the running maximum of [first, last) into out.
// Returns the number of elements written.
template <typename InputIt, typename OutputIt>
std::size_t running_max(InputIt first, InputIt last, OutputIt out) {
    using T = typename std::iterator_traits<InputIt>::value_type;
    std::size_t n = 0;
    bool seen = false;
    T best{};

    for (; first != last; ++first, ++n) {
        if (!seen) {
            best = *first;
            seen = true;
        } else if (*first > best) {
            best = *first;
        }
        *out = best;
        ++out;
    }
    return n;
}

int main() {
    std::vector<int> in{3, 1, 4, 1, 5, 9, 2, 6};
    std::vector<int> got(in.size());
    std::size_t n = running_max(in.begin(), in.end(), got.begin());

    assert(n == in.size());
    std::vector<int> want{3, 3, 4, 4, 5, 9, 9, 9};
    assert(got == want);

    std::vector<int> empty;
    assert(running_max(empty.begin(), empty.end(), empty.begin()) == 0);
    return 0;
}
```

The `seen` flag initialises `best` from the first element rather than a zero value, so negative-only inputs still work. Empty ranges write nothing and return 0.

```rust
/// Split `data` into consecutive chunks of at most `n` elements.
/// Returns an empty Vec when `n == 0` instead of panicking.
pub fn chunk_by<'a, T>(data: &'a [T], n: usize) -> Vec<&'a [T]> {
    if n == 0 {
        return Vec::new();
    }
    let mut chunks = Vec::with_capacity((data.len() + n - 1) / n);
    let mut start = 0;
    while start < data.len() {
        let end = (start + n).min(data.len());
        chunks.push(&data[start..end]);
        start = end;
    }
    chunks
}

fn main() {
    let data: Vec<u32> = (1..=10).collect();

    let c = chunk_by(&data, 3);
    assert_eq!(c.len(), 4);
    assert_eq!(c[0], &[1, 2, 3]);
    assert_eq!(c[3], &[10]);

    assert!(chunk_by(&data, 0).is_empty());
    assert!(chunk_by::<u32>(&[], 3).is_empty());

    let big = chunk_by(&data, 100);
    assert_eq!(big.len(), 1);
    assert_eq!(big[0].len(), 10);
}
```

`n == 0` yields an empty result instead of division by zero, the final short chunk is naturally handled by `min(len)`, and `chunk_by` borrows the slice so no data is copied.

```rust
pub fn binary_search<T: Ord>(haystack: &[T], needle: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = haystack.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match haystack[mid].cmp(needle) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

fn main() {
    let data = ["apple", "banana", "cherry", "date", "elderberry"];

    assert_eq!(binary_search(&data, &"apple"), Some(0));
    assert_eq!(binary_search(&data, &"cherry"), Some(2));
    assert_eq!(binary_search(&data, &"elderberry"), Some(4));
    assert_eq!(binary_search(&data, &"fig"), None);
    assert_eq!(binary_search::<&str>(&[], &"apple"), None);
}
```

`lo + (hi - lo) / 2` avoids the overflow that `(lo + hi) / 2` can hit on large slices. The half-open range `[lo, hi)` terminates correctly and works for empty input.

