#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) return;
    right--;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char buf[] = "Hello, world!";
    reverse_in_place(buf);
    printf("%s\n", buf);

    char empty[] = "";
    reverse_in_place(empty);
    printf("[%s]\n", empty);

    char single[] = "x";
    reverse_in_place(single);
    printf("[%s]\n", single);

    return 0;
}
