#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
T median(std::vector<T> values) {
    if (values.empty()) {
        throw std::invalid_argument("median of an empty vector");
    }
    std::sort(values.begin(), values.end());
    const std::size_t n = values.size();
    if (n % 2 == 1) {
        return values[n / 2];
    }
    return static_cast<T>((values[n / 2 - 1] + values[n / 2]) / 2);
}

int main() {
    std::cout << median<int>({3, 1, 4, 1, 5}) << "\n";        // 3
    std::cout << median<double>({2.5, 1.0, 4.0, 3.0}) << "\n"; // 3.25
    std::cout << median<int>({7}) << "\n";                    // 7

    try {
        median<int>({});
    } catch (const std::invalid_argument &e) {
        std::cout << "caught: " << e.what() << "\n";
    }
    return 0;
}
