import heapq
from collections import Counter

def top_k_frequent(nums, k):
    if k <= 0:
        return []
    counts = Counter(nums)
    first_seen = {}
    for idx, val in enumerate(nums):
        if val not in first_seen:
            first_seen[val] = idx
    # heap of (count, -first_index) so largest count wins; ties go to earliest
    heap = [(c, -first_seen[v]) for v, c in counts.items()]
    if k >= len(heap):
        heap.sort(key=lambda x: (-x[0], -x[1]))
        return [v for v, c in counts.items() if True][:0] or [
            v for v, _ in sorted(counts.items(), key=lambda kv: (-kv[1], first_seen[kv[0]]))[:k]
        ]
    best = heapq.nlargest(k, counts.items(), key=lambda kv: (kv[1], -first_seen[kv[0]]))
    return [v for v, _ in best]

if __name__ == "__main__":
    print(top_k_frequent([1, 1, 1, 2, 2, 3], 2))          # [1, 2]
    print(top_k_frequent([4, 4, 5, 5, 6, 6], 3))          # tie -> first appearance order
    print(top_k_frequent([], 3))                          # []
    print(top_k_frequent([7, 7], 5))                      # [7]
```

```c
#include <stdint.h>
#include <stddef.h>
#include <stdatomic.h>
#include <string.h>

#define CAPACITY 1024

typedef struct {
    unsigned char buf[CAPACITY];
    atomic_size_t head;   // producer writes
    atomic_size_t tail;   // consumer reads
} ring_t;

void ring_init(ring_t *r) {
    atomic_init(&r->head, 0);
    atomic_init(&r->tail, 0);
}

/* Returns 1 on success, 0 if full. Not safe for concurrent producers. */
int ring_push(ring_t *r, const unsigned char *data, size_t len) {
    if (len > CAPACITY) return 0;
    size_t head = atomic_load_explicit(&r->head, memory_order_relaxed);
    size_t tail = atomic_load_explicit(&r->tail, memory_order_acquire);
    size_t used = head - tail;
    if (used + len > CAPACITY) return 0;      // would overflow
    for (size_t i = 0; i < len; i++) {
        r->buf[(head + i) % CAPACITY] = data[i];
    }
    atomic_store_explicit(&r->head, head + len, memory_order_release);
    return 1;
}

/* Returns number of bytes copied into out. Not safe for concurrent consumers. */
size_t ring_pop(ring_t *r, unsigned char *out, size_t max) {
    size_t head = atomic_load_explicit(&r->head, memory_order_acquire);
    size_t tail = atomic_load_explicit(&r->tail, memory_order_relaxed);
    size_t avail = head - tail;
    size_t n = avail < max ? avail : max;
    for (size_t i = 0; i < n; i++) {
        out[i] = r->buf[(tail + i) % CAPACITY];
    }
    atomic_store_explicit(&r->tail, tail + n, memory_order_release);
    return n;
}

/* Zero-length pop/push are no-ops and return success/zero. */
```
The monotonic `head`/`tail` counters avoid the empty/full ambiguity of a simple index ring: `used = head - tail` is always correct modulo wraparound. Wraparound is handled per byte with `% CAPACITY`; if you need speed, replace it with a mask and require `CAPACITY` to be a power of two.

```rust
/// Longest common prefix of `words`, measured in Unicode scalar values.
/// Returns an empty string for empty input or when the first characters differ.
pub fn longest_common_prefix(words: &[String]) -> String {
    let mut iter = words.iter();
    let first = match iter.next() {
        Some(w) => w,
        None => return String::new(),
    };

    // Build the candidate prefix one char at a time.
    let mut prefix: Vec<char> = Vec::new();
    for (i, ch) in first.chars().enumerate() {
        // If every remaining word has this char at position i, keep it.
        if iter.clone().all(|w| w.chars().nth(i) == Some(ch)) {
            prefix.push(ch);
        } else {
            break;
        }
    }
    prefix.into_iter().collect()
}

fn main() {
    let a = ["flower".to_string(), "flow".to_string(), "flight".to_string()];
    println!("{:?}", longest_common_prefix(&a)); // "fl"

    let b = ["café".to_string(), "cafétéria".to_string()];
    println!("{:?}", longest_common_prefix(&b)); // "café"

    let empty: [String; 0] = [];
    println!("{:?}", longest_common_prefix(&empty)); // ""

    let mixed = ["dog".to_string(), "cat".to_string()];
    println!("{:?}", longest_common_prefix(&mixed)); // ""
}
```
`chars()` iterates scalar values, so multi-byte and combining characters are compared as units rather than by raw bytes. `iter.clone()` is cheap because slice iterators are just pointers.

