#include <cstdint>
#include <string>
#include <optional>
#include <iostream>
#include <cctype>

struct ParseResult {
    enum Status { Ok, Empty, BadChar, Overflow } status = Empty;
    int32_t value = 0;
};

ParseResult parse_int32(const std::string& s) {
    ParseResult r;
    size_t i = 0;
    bool neg = false;

    if (s.empty()) { r.status = ParseResult::Empty; return r; }
    if (s[i] == '+' || s[i] == '-') { neg = (s[i] == '-'); i++; }
    if (i == s.size()) { r.status = ParseResult::BadChar; return r; }

    // Accumulate in 64-bit, then range-check.
    int64_t acc = 0;
    for (; i < s.size(); i++) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        if (!std::isdigit(c)) { r.status = ParseResult::BadChar; return r; }
        acc = acc * 10 + (c - '0');
        if (acc > 2147483648LL) { r.status = ParseResult::Overflow; return r; }
    }

    if (neg) acc = -acc;
    if (acc < -2147483648LL || acc > 2147483647LL) {
        r.status = ParseResult::Overflow;
        return r;
    }
    r.status = ParseResult::Ok;
    r.value = static_cast<int32_t>(acc);
    return r;
}

int main() {
    for (const std::string& t : {"42", "-2147483648", "2147483648", "", "+7x", " 5"}) {
        auto r = parse_int32(t);
        std::cout << '\"' << t << "\" -> ";
        switch (r.status) {
            case ParseResult::Ok:       std::cout << "ok " << r.value << '\n'; break;
            case ParseResult::Empty:    std::cout << "empty\n"; break;
            case ParseResult::BadChar:  std::cout << "bad char\n"; break;
            case ParseResult::Overflow: std::cout << "overflow\n"; break;
        }
    }
}
```
`-2147483648` is accepted because the accumulator reaches `2147483648` before negation, which is exactly `INT32_MIN` after flipping sign. Leading whitespace is rejected on purpose; strip it before calling if you want to allow it.

```python
import threading
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()
        self._lock = threading.RLock()

    def get(self, key):
        with self._lock:
            if key not in self._data:
                return None
            self._data.move_to_end(key)
            return self._data[key]

    def put(self, key, value):
        with self._lock:
            if key in self._data:
                self._data.move_to_end(key)
            self._data[key] = value
            if len(self._data) > self.capacity:
                self._data.popitem(last=False)  # evict least recently used

    def __len__(self):
        with self._lock:
            return len(self._data)

if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    c.get("a")        # 'a' is now most recent
    c.put("c", 3)     # evicts 'b'
    print(c.get("a"), c.get("b"), c.get("c"))  # 1 None 3
```
The `RLock` serializes mutation and reads; `OrderedDict.move_to_end` and `popitem(last=False)` give O(1) recency updates and eviction. `None` is returned for missing keys, so store a sentinel if you need to cache real `None` values.

