use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum ConfigError {
    NoEquals(usize),
    EmptyKey(usize),
    DuplicateKey(String, usize),
}

pub fn parse_config(input: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut map = HashMap::new();
    for (idx, raw) in input.lines().enumerate() {
        let line_no = idx + 1;
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line.split_once('=')
            .ok_or(ConfigError::NoEquals(line_no))?;
        let key = key.trim();
        let value = value.trim();
        if key.is_empty() {
            return Err(ConfigError::EmptyKey(line_no));
        }
        if map.contains_key(key) {
            return Err(ConfigError::DuplicateKey(key.to_string(), line_no));
        }
        map.insert(key.to_string(), value.to_string());
    }
    Ok(map)
}

fn main() {
    let cfg = "# app config\nhost = 127.0.0.1\nport=8080\n\nname = demo\n";
    match parse_config(cfg) {
        Ok(m) => println!("{m:?}"),
        Err(e) => eprintln!("error: {e:?}"),
    }
    // duplicate key case
    assert!(matches!(
        parse_config("a=1\na=2"),
        Err(ConfigError::DuplicateKey(_, 2))
    ));
}
```
`split_once` keeps any `=` inside the value intact (only the first one separates). Trim happens before the empty-key check so `  =x` is rejected. Values containing `#` are kept whole; only whole-line comments are stripped.

