```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 128

typedef struct { char *key; int value; int used; } slot_t;

typedef struct { slot_t slots[TABLE_SIZE]; size_t count; } table_t;

static unsigned long hash(const char *s) {
    unsigned long h = 5381;
    while (*s) h = ((h << 5) + h) ^ (unsigned char)*s++;
    return h;
}

void table_init(table_t *t) {
    memset(t, 0, sizeof(*t));
}

/* Returns 0 on success, 1 if the table is full, 2 on allocation failure. */
int table_put(table_t *t, const char *key, int value) {
    if (t->count >= TABLE_SIZE) return 1;
    size_t idx = hash(key) % TABLE_SIZE;
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        slot_t *s = &t->slots[(idx + i) % TABLE_SIZE];
        if (!s->used) {
            s->key = strdup(key);           // fix: was malloc + memcpy
            if (!s->key) return 2;
            s->value = value;
            s->used = 1;
            t->count++;
            return 0;
        }
        if (strcmp(s->key, key) == 0) {     // update existing
            s->value = value;
            return 0;
        }
    }
    return 1;
}

/* Returns 1 and stores the value if found, else 0. */
int table_get(const table_t *t, const char *key, int *out) {
    size_t idx = hash(key) % TABLE_SIZE;
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        const slot_t *s = &t->slots[(idx + i) % TABLE_SIZE];
        if (!s->used) return 0;             // probe chain ends here
        if (strcmp(s->key, key) == 0) { *out = s->value; return 1; }
    }
    return 0;
}

void table_free(table_t *t) {
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        free(t->slots[i].key);
        t->slots[i].key = NULL;
        t->slots[i].used = 0;
    }
    t->count = 0;
}

int main(void) {
    table_t t; table_init(&t);
    table_put(&t, "alpha", 1);
    table_put(&t, "beta", 2);
    table_put(&t, "alpha", 42);
    int v = 0;
    printf("alpha=%d\n", table_get(&t, "alpha", &v) ? v : -1); // 42
    printf("beta=%d\n", table_get(&t, "beta", &v) ? v : -1);   // 2
    printf("gamma=%d\n", table_get(&t, "gamma", &v) ? v : -1); // -1
    table_free(&t);
    return 0;
}
```
This is a delete-free table: once a slot is used it is never cleared, so lookup can stop at the first free slot without tombstone markers. `table_free` releases every allocated key, so the demo has no leaks under valgrind. A full table returns 1 rather than growing; add rehashing if you need more than 128 keys.

```python
from collections.abc import Iterable

def flatten(items):
    """Yield leaf values from an arbitrarily nested iterable.

    Strings and bytes are treated as leaves, not sequences of characters.
    A recursion guard protects against self-referential containers.
    """
    def walk(node, seen):
        if isinstance(node, (str, bytes)):
            yield node
            return
        if isinstance(node, Iterable):
            ident = id(node)
            if ident in seen:
                raise ValueError("cycle detected in nested structure")
            seen.add(ident)
            try:
                for child in node:
                    yield from walk(child, seen)
            finally:
                seen.discard(ident)
        else:
            yield node

    yield from walk(items, set())

if __name__ == "__main__":
    data = [1, [2, [3, [4, 5]], "ab"], (), 6, ["c", ["de"]]]
    print(list(flatten(data)))
    # [1, 2, 3, 4, 5, 'ab', 6, 'c', 'de']

    print(list(flatten([])))            # []
    a = []; a.append(a)                 # self-referential
    try:
        list(flatten(a))
    except ValueError as e:
        print("caught:", e)
```
The `seen` set is keyed by `id` and discarded on the way out, so it tracks only the current descent path — that correctly allows the same list to appear as two separate siblings while still catching a true cycle. Strings are checked before the `Iterable` branch because `str` is itself iterable.

