#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), size_(0) {}

    void push(int value) {
        if (cap_ == 0) throw std::runtime_error("zero capacity");
        buf_[(head_ + size_) % cap_] = value;
        if (size_ == cap_) {
            head_ = (head_ + 1) % cap_;
        } else {
            ++size_;
        }
    }

    int peek(std::size_t idx) const {
        if (idx >= size_) throw std::out_of_range("index out of range");
        return buf_[(head_ + idx) % cap_];
    }

    std::size_t size() const { return size_; }

private:
    std::vector<int> buf_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    rb.push(10);
    rb.push(20);
    rb.push(30);
    rb.push(40);
    if (rb.size() != 3 || rb.peek(0) != 20 || rb.peek(2) != 40) return 1;
    try { rb.peek(3); return 1; } catch (const std::out_of_range&) {}
    std::cout << "ok\n";
