fn encode(input: &[u8]) -> Vec<(u8, u32)> {
    let mut out: Vec<(u8, u32)> = Vec::new();
    let mut i = 0usize;
    while i < input.len() {
        let byte = input[i];
        let mut count = 0u32;
        while i < input.len() && input[i] == byte {
            count += 1;
            i += 1;
        }
        out.push((byte, count));
    }
    out
}

/// Returns None if any count is zero (a malformed encoding).
fn decode(pairs: &[(u8, u32)]) -> Option<Vec<u8>> {
    let mut out = Vec::new();
    for &(byte, count) in pairs {
        if count == 0 {
            return None;
        }
        out.extend(std::iter::repeat(byte).take(count as usize));
    }
    Some(out)
}

fn main() {
    let cases: &[&[u8]] = &[b"", b"aaaa", b"aabbbcc", b"\x00\x00\xff", b"abc"];
    for input in cases {
        let encoded = encode(input);
        let round_tripped = decode(&encoded).expect("valid encoding");
        assert_eq!(round_tripped.as_slice(), *input);
        println!("{input:?} -> {encoded:?}");
    }
    assert!(decode(&[(1, 0)]).is_none());
    println!("ok");
}
