from typing import Any, Iterator, Tuple


def iter_leaves(obj: Any, path: str = "") -> Iterator[Tuple[str, Any]]:
    """Yield (dotted_path, leaf_value) for every scalar leaf in obj.

    Dictionaries contribute .key, lists contribute [i]. Empty
    containers produce no rows. Scalars are returned as-is.
    """
    if isinstance(obj, dict):
        for key, value in obj.items():
            child = f"{path}.{key}" if path else str(key)
            yield from iter_leaves(value, child)
    elif isinstance(obj, list):
        for i, value in enumerate(obj):
            yield from iter_leaves(value, f"{path}[{i}]")
    else:
        yield path, obj


