```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1
    cache.put("c", 3)          # evicts "b"
    assert cache.get("b") is None
    assert cache.get("c") == 3
    assert len(cache) == 2
    print("ok")
```

`OrderedDict.move_to_end` marks an entry as most-recently used; `popitem(last=False)` evicts the least-recently used one when over capacity. Storing `None` as a value would be ambiguous with a miss, so use a sentinel if your data can contain `None`.

```c
#include <ctype.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

bool is_palindrome(const char *s) {
    if (s == NULL) return false;
    size_t left = 0;
    size_t right = strlen(s);
    while (left < right) {
        if (right == 0) break;
        --right;
        while (left < right && !isalnum((unsigned char)s[left])) ++left;
        while (left < right && !isalnum((unsigned char)s[right])) --right;
        if (left >= right) break;
        if (tolower((unsigned char)s[left]) != tolower((unsigned char)s[right]))
            return false;
        ++left;
    }
    return true;
}

int main(void) {
    const char *cases[] = {
        "A man, a plan, a canal: Panama",
        "race a car",
        "",
        "a",
        "No lemon, no melon",
    };
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i)
        printf("%-32s -> %s\n", cases[i], is_palindrome(cases[i]) ? "true" : "false");
    return 0;
}
```

Casting to `(unsigned char)` before `isalnum`/`tolower` avoids undefined behaviour on negative `char` values. The two-pointer scan skips non-alphanumeric characters; empty and single-character strings return `true`. Output: the first and last lines are `true`, the middle three `false`/`true` as expected.

