#include <algorithm>
#include <iostream>
#include <optional>
#include <stdexcept>
#include <vector>

template <typename T>
std::optional<double> median(const std::vector<T>& values) {
    if (values.empty()) {
        return std::nullopt;
    }
    std::vector<T> sorted = values;  // copy: caller's vector untouched
    std::sort(sorted.begin(), sorted.end());
    const std::size_t n = sorted.size();
    if (n % 2 == 1) {
        return static_cast<double>(sorted[n / 2]);
    }
    return (static_cast<double>(sorted[n / 2 - 1]) +
            static_cast<double>(sorted[n / 2])) / 2.0;
}

int main() {
    std::vector<int> odd{5, 1, 3};
    std::vector<int> even{4, 1, 3, 2};
    std::vector<int> empty;

    std::cout << median(odd).value() << '\n';              // 3
    std::cout << median(even).value() << '\n';             // 2.5
    std::cout << (median(empty) ? "x" : "nullopt") << '\n'; // nullopt
    std::cout << odd[0] << '\n';                           // 5, unchanged
}
```

Returning `std::optional<double>` distinguishes "no median" from a real median of 0. The copy makes the function non-destructive; for very large inputs, pass iterators or index into a copy deliberately. Averaging two middle elements uses `double` math to avoid integer truncation.

