#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* Reverse the bytes of a NUL-terminated string in place.
 * An empty string is left untouched.
 * The function works on raw bytes, so multi-byte UTF-8 sequences
 * are reversed byte-by-byte and will not remain valid UTF-8; it is
 * safe for ASCII and for treating the buffer as opaque data. */
void reverse_string(char *s)
{
    if (s == NULL) {
        return;
    }
    size_t len = strlen(s);
    if (len < 2) {
        return;
    }
    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

int main(void)
{
    char a[] = "";
    reverse_string(a);
    printf("[%s]\n", a);

    char b[] = "hello";
    reverse_string(b);
    printf("%s\n", b);

    char c[] = "a";
    reverse_string(c);
    printf("%s\n", c);

    reverse_string(NULL);
    return 0;
}
```

The `len < 2` guard makes the empty string and single-character cases no-ops, and the NULL check prevents a crash. Byte-level reversal is correct only when the input is ASCII or when the caller does not require valid UTF-8 afterward.

