`split_whitespace` handles any Unicode whitespace and collapses runs of separators, so empty and whitespace-only strings produce no words. Unicode is preserved because splitting happens on `char` boundaries.

```cpp
#include <limits>
#include <stdexcept>
#include <string>
#include <iostream>

enum class ParseStatus { Ok, Invalid, Overflow };

ParseStatus parse_int(const std::string& text, long long& out)
{
    if (text.empty()) {
        return ParseStatus::Invalid;
    }

    std::size_t i = 0;
    bool negative = false;
    if (text[i] == '+' || text[i] == '-') {
        negative = (text[i] == '-');
        ++i;
    }
    if (i == text.size()) {
        return ParseStatus::Invalid;
    }

    long long acc = 0;
    const long long limit = negative
        ? -(std::numeric_limits<long long>::min() / 10)
        :  (std::numeric_limits<long long>::max() / 10);

    for (; i < text.size(); ++i) {
        char c = text[i];
        if (c < '0' || c > '9') {
            return ParseStatus::Invalid;
        }
        int digit = c - '0';
        if (acc > limit) {
            return ParseStatus::Overflow;
        }
        acc = acc * 10 + digit;
        if (acc < 0 && !negative) {
            return ParseStatus::Overflow;
        }
    }

    out = negative ? -acc : acc;
    return ParseStatus::Ok;
}

int main() {
    long long value = 0;
    std::cout << static_cast<int>(parse_int("42", value)) << ' ' << value << '\n';
    std::cout << static_cast<int>(parse_int("-7", value)) << ' ' << value << '\n';
    std::cout << static_cast<int>(parse_int("12a", value)) << '\n';
    std::cout << static_cast<int>(parse_int("", value)) << '\n';
    std::cout << static_cast<int>(parse_int("99999999999999999999", value)) << '\n';
    return 0;
}
```

The `limit` is the largest accumulator that can be multiplied by ten without overflow, computed separately for the negative range so `LLONG_MIN` is handled. The post-multiply negative check catches the final step that wraps past `LLONG_MAX`. Invalid and overflow cases return distinct status values instead of throwing.

```rust
/// Split one CSV record into fields.
/// A field may be quoted with double quotes; a literal quote inside a
/// quoted field is written as "". Commas inside quotes are not separators.
pub fn split_csv_record(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut chars = line.chars().peekable();
    let mut in_quotes = false;

    while let Some(c) = chars.next() {
        if in_quotes {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    chars.next();
                    current.push('"');
                } else {
                    in_quotes = false;
                }
            } else {
                current.push(c);
            }
        } else if c == '"' {
            in_quotes = true;
        } else if c == ',' {
            fields.push(std::mem::take(&mut current));
        } else {
            current.push(c);
        }
    }

    if in_quotes {
        current.push('\u{0}');
    }

    fields.push(current);
    fields
}

fn main() {
    let f = split_csv_record("a,b,c");
    assert_eq!(f, vec!["a", "b", "c"]);

    let f = split_csv_record("");
    assert_eq!(f, vec![""]);

    let f = split_csv_record("\"a,b\",c");
    assert_eq!(f, vec!["a,b", "c"]);

    let f = split_csv_record("\"he said \"\"hi\"\"\",x");
    assert_eq!(f, vec!["he said \"hi\"", "x"]);

    println!("ok");
}
```

`peekable` lets the scanner look ahead for the `""` escape without consuming the outer quote. `std::mem::take` moves the field out and resets `current` in one step, so repeated fields stay owned `String`s. An unterminated quote is surfaced by appending a NUL sentinel rather than silently accepting the partial field.

