bool is_balanced(const std::string& s) {
    std::stack<char> st;
    const std::unordered_map<char, char> match{{')', '('}, {']', '['}, {'}', '{'}};
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else {
            auto it = match.find(c);
            if (it == match.end()) return false;
            if (st.empty() || st.top() != it->second) return false;
            st.pop();
        }
    }
    return st.empty();
}

