def is_valid_ipv4(text):
    """Return True only for strict dotted-quad IPv4 addresses.

    Rejects empty strings, leading zeros, out-of-range octets, extra or
    missing parts, and anything with whitespace or signs.
    """
    if not isinstance(text, str) or not text:
        return False

    parts = text.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        if not part or not part.isdigit():
            return False
        # '007' is not a canonical IPv4 octet.
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False
    return True


if __name__ == "__main__":
    good = ["0.0.0.0", "192.168.1.1", "255.255.255.255", "8.8.8.8"]
    bad = ["", "1.2.3", "1.2.3.4.5", "256.1.1.1", "01.2.3.4",
           "1.2.3.4 ", "a.b.c.d", "1.2.3.-4"]
