/* Reverse bytes in place. Returns the length, or 0 for NULL. */
size_t reverse_in_place(char *s, size_t len) {
    if (s == NULL) {
        return 0;
    }
    if (len == 0) {
        return 0;
    }

    size_t i = 0;
    size_t j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
    return len;
}

int main(void) {
    char buf[] = "hello";          /* mutable copy, not a string literal */
    char empty[] = "";

    size_t n = reverse_in_place(buf, sizeof(buf) - 1);
    printf("%s (%zu bytes)\n", buf, n);

    size_t m = reverse_in_place(empty, 0);
    printf("\"%s\" (%zu bytes)\n", empty, m);

    /* NULL must not crash. */
    printf("null -> %zu\n", reverse_in_place(NULL, 0));
    return 0;
}
