```cpp
#include <array>
#include <optional>
#include <cstddef>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 2> rb;
    if (!rb.push(1) || !rb.push(2) || rb.push(3)) return 1;
    if (rb.pop() != 1 || rb.pop() != 2) return 1;
    if (rb.pop().has_value()) return 1;
    return 0;
}
```

Modulo arithmetic wraps both indices, and `std::optional` makes an empty pop explicit instead of returning garbage. The template enforces the fixed capacity at compile time.

