def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring of s (center expansion, O(n^2))."""
    if not s:
        return ""

    def expand(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    start, end = 0, 0
    for i in range(len(s)):
        l1, r1 = expand(i, i)        # odd length
        l2, r2 = expand(i, i + 1)    # even length
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end + 1]


if __name__ == "__main__":
    cases = {"babad": "bab", "cbbd": "bb", "": "", "a": "a", "forgeeksskeegfor": "geeksskeeg"}
    for text, want in cases.items():
        got = longest_palindrome(text)
        assert len(got) == len(want), (text, got, want)
    print(longest_palindrome("forgeeksskeegfor"))
