from typing import Iterable, Iterator, TypeVar

T = TypeVar("T")


def merge_unique(a: Iterable[T], b: Iterable[T]) -> Iterator[T]:
    """Merge two sorted iterables, yielding each distinct value once."""
    i, j = iter(a), iter(b)
    next_i, next_j = _peek(i), _peek(j)
    sentinel = object()
    last = sentinel
    while next_i is not _EMPTY or next_j is not _EMPTY:
        if next_j is _EMPTY or (next_i is not _EMPTY and next_i <= next_j):
            value = next_i
            next_i = _peek(i)
        else:
            value = next_j
            next_j = _peek(j)
        if value != last:
            yield value
            last = value


class _Empty:
    pass


_EMPTY = _Empty()


def _peek(it: Iterator[T]):
    try:
        return next(it)
    except StopIteration:
        return _EMPTY


if __name__ == "__main__":
    assert list(merge_unique([1, 2, 2, 5], [2, 3, 5, 6])) == [1, 2, 3, 5, 6]
    assert list(merge_unique([], [])) == []
    assert list(merge_unique([4], [1, 4, 4])) == [1, 4]
    print("ok")
