use std::cmp::Ordering;

/// Binary search over a sorted slice. Returns the index of the first element
/// equal to `key`, or the index where `key` would be inserted to keep order.
fn lower_bound<T: Ord>(slice: &[T], key: &T) -> usize {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(key) {
            Ordering::Less => lo = mid + 1,
            Ordering::Equal | Ordering::Greater => hi = mid,
        }
    }
    lo
}

fn main() {
    let sorted = [1, 3, 5, 5, 7, 9];
    assert_eq!(lower_bound(&sorted, &5), 2);
    assert_eq!(lower_bound(&sorted, &6), 4);
    assert_eq!(lower_bound(&sorted, &0), 0);
    assert_eq!(lower_bound(&sorted, &100), sorted.len());

    let empty: [&str; 0] = [];
    assert_eq!(lower_bound(&empty, &"x"), 0);
    println!("ok");
}
