/// Encode runs of the same byte as `<count><byte>` (ASCII decimal count, then byte).
fn encode(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < input.len() {
        let byte = input[i];
        let mut run = 1;
        while i + run < input.len() && input[i + run] == byte && run < 255 {
            run += 1;
        }
        out.extend_from_slice(&format!("{}{}", run, byte as char).into_bytes());
        i += run;
    }
    out
}

/// Decode data produced by `encode`.
fn decode(input: &[u8]) -> Result<Vec<u8>, &'static str> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < input.len() {
        let mut count: u32 = 0;
        while i < input.len() && input[i].is_ascii_digit() {
            count = count * 10 + (input[i] - b'0') as u32;
            i += 1;
        }
        if count == 0 || i >= input.len() {
            return Err("malformed run-length input");
        }
        out.extend(std::iter::repeat(input[i]).take(count as usize));
        i += 1;
    }
    Ok(out)
}

fn main() -> Result<(), &'static str> {
    let original = b"aaabbccccd";
    let encoded = encode(original);
    assert_eq!(&encoded, b"3a2b4c1d");
    assert_eq!(decode(&encoded)?, original);
    assert_eq!(decode(encode(&[]))?, Vec::<u8>::new());
    assert!(decode(b"0a").is_err());
    println!("ok");
    Ok(())
}
