#include <array>
#include <cstddef>
#include <optional>
#include <iostream>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    if (rb.pop()) { std::cout << "unexpected\n"; return 1; }
    for (int i = 1; i <= 3; ++i) {
        if (!rb.push(i)) { std::cout << "push failed\n"; return 1; }
    }
    if (rb.push(4)) { std::cout << "overflow allowed\n"; return 1; }
    int expected = 1;
    while (!rb.empty()) {
        auto v = rb.pop();
        if (!v || *v != expected) { std::cout << "bad pop\n"; return 1; }
        ++expected;
    }
    std::cout << "ring buffer ok\n";
    return 0;
}
