```rust
use std::collections::VecDeque;
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Queue<T> {
    items: Mutex<VecDeque<T>>,
    capacity: usize,
    empty: Condvar,
    full: Condvar,
    closed: Mutex<bool>,
}

impl<T> Queue<T> {
    fn new(capacity: usize) -> Self {
        Queue {
            items: Mutex::new(VecDeque::new()),
            capacity,
            empty: Condvar::new(),
            full: Condvar::new(),
            closed: Mutex::new(false),
        }
    }

    fn push(&self, value: T) {
        let mut items = self.items.lock().unwrap();
        while items.len() == self.capacity {
            items = self.full.wait(items).unwrap();
        }
        items.push_back(value);
        self.empty.notify_one();
    }

    fn pop(&self) -> Option<T> {
        let mut items = self.items.lock().unwrap();
        loop {
            if let Some(v) = items.pop_front() {
                self.full.notify_one();
                return Some(v);
            }
            if *self.closed.lock().unwrap() {
                return None;
            }
            items = self.empty.wait(items).unwrap();
        }
    }

    fn close(&self) {
        *self.closed.lock().unwrap() = true;
        self.empty.notify_all();
    }
}

fn main() {
    let q = Arc::new(Queue::new(4));
    let producer = {
        let q = Arc::clone(&q);
        thread::spawn(move || {
            for i in 0..100 {
                q.push(i);
            }
            q.close();
        })
    };

    let mut sum = 0u64;
    let consumer = {
        let q = Arc::clone(&q);
        thread::spawn(move || {
            while let Some(v) = q.pop() {
                sum += v;
            }
            sum
        })
    };

    producer.join().unwrap();
    let total = consumer.join().unwrap();
    assert_eq!(total, (0..100u64).sum());
    println!("consumed sum {}", total);
}
```

The `while` on push and `loop` on pop guard against spurious wakeups, `close` wakes all waiters so consumers exit, and the assertion checks the exact sum.

