import random
import time
from typing import Callable, TypeVar

T = TypeVar("T")


def retry(fn: Callable[[], T], attempts: int = 5, base: float = 0.5,
          max_delay: float = 30.0,
          retry_on: tuple[type[BaseException], ...] = (Exception,)) -> T:
    if attempts < 1:
        raise ValueError("attempts must be >= 1")
    last: BaseException | None = None
    for i in range(attempts):
        try:
            return fn()
        except retry_on as exc:
            last = exc
            if i == attempts - 1:
                break
            delay = min(max_delay, base * 2 ** i)
            time.sleep(random.uniform(0.0, delay))
    raise RuntimeError(f"all {attempts} attempts failed") from last


if __name__ == "__main__":
    calls = {"n": 0}

    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("boom")
        return calls["n"]

    assert retry(flaky, attempts=5, base=0.001) == 3
    assert calls["n"] == 3
    print("ok")
