#include <mutex>
#include <optional>
#include <queue>
#include <thread>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {}

    bool push(int value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [&] { return closed_ || queue_.size() < capacity_; });
        if (closed_) return false;
        queue_.push(value);
        not_empty_.notify_one();
        return true;
    }

    std::optional<int> try_pop() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (queue_.empty()) return std::nullopt;
        int value = queue_.front();
        queue_.pop();
        not_full_.notify_one();
        return value;
    }

    template <class Rep, class Period>
    std::optional<int> pop_for(const std::chrono::duration<Rep, Period>& timeout) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (!not_empty_.wait_for(lock, timeout, [&] { return closed_ || !queue_.empty(); }))
            return std::nullopt;
        if (queue_.empty()) return std::nullopt;  // closed
        int value = queue_.front();
        queue_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mutex_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t capacity_;
    std::queue<int> queue_;
    bool closed_ = false;
    std::mutex mutex_;
    std::condition_variable not_empty_, not_full_;
};

#include <cassert>
int main() {
    BoundedQueue q(2);
    assert(q.push(1));
    assert(q.push(2));
    assert(q.try_pop() == 1);
    assert(q.pop_for(std::chrono::milliseconds(10)) == 2);
    assert(!q.pop_for(std::chrono::milliseconds(5)).has_value());
    q.close();
    assert(!q.push(3));
}
