use std::fmt;

#[derive(Debug, PartialEq)]
pub enum Ipv4Error {
    WrongParts(usize),
    EmptyPart,
    NotANumber(String),
    LeadingZero,
    OutOfRange(u16),
}

impl fmt::Display for Ipv4Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Ipv4Error::WrongParts(n) => write!(f, "expected 4 octets, got {n}"),
            Ipv4Error::EmptyPart => write!(f, "empty octet"),
            Ipv4Error::NotANumber(s) => write!(f, "not a number: {s}"),
            Ipv4Error::LeadingZero => write!(f, "octet must not have a leading zero"),
            Ipv4Error::OutOfRange(v) => write!(f, "octet out of range: {v}"),
        }
    }
}

pub fn parse_ipv4(input: &str) -> Result<[u8; 4], Ipv4Error> {
    let parts: Vec<&str> = input.split('.').collect();
    if parts.len() != 4 {
        return Err(Ipv4Error::WrongParts(parts.len()));
    }
    let mut out = [0u8; 4];
    for (i, part) in parts.iter().enumerate() {
        if part.is_empty() {
            return Err(Ipv4Error::EmptyPart);
        }
        if !part.chars().all(|c| c.is_ascii_digit()) {
            return Err(Ipv4Error::NotANumber((*part).to_string()));
        }
        if part.len() > 1 && part.starts_with('0') {
            return Err(Ipv4Error::LeadingZero);
        }
        let value: u16 = part.parse().map_err(|_| Ipv4Error::NotANumber((*part).to_string()))?;
        if value > 255 {
            return Err(Ipv4Error::OutOfRange(value));
        }
        out[i] = value as u8;
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn valid() {
        assert_eq!(parse_ipv4("192.168.0.1"), Ok([192, 168, 0, 1]));
        assert_eq!(parse_ipv4("0.0.0.0"), Ok([0, 0, 0, 0]));
    }

    #[test]
    fn invalid() {
        assert_eq!(parse_ipv4("256.1.1.1"), Err(Ipv4Error::OutOfRange(256)));
        assert_eq!(parse_ipv4("1.2.3"), Err(Ipv4Error::WrongParts(3)));
        assert_eq!(parse_ipv4("1.2.3."), Err(Ipv4Error::EmptyPart));
        assert_eq!(parse_ipv4("01.2.3.4"), Err(Ipv4Error::LeadingZero));
        assert_eq!(parse_ipv4("a.b.c.d"), Err(Ipv4Error::NotANumber("a".into())));
    }
}
