```c
#include <stdio.h>
#include <stdlib.h>

#define TABLE_SIZE 128

typedef struct Node {
    int key;
    int value;
    struct Node *prev;
    struct Node *next;
} Node;

typedef struct {
    int capacity;
    int size;
    Node *head; /* most recently used */
    Node *tail; /* least recently used */
    Node *table[TABLE_SIZE];
} LRU;

static unsigned hash(int key) {
    return (unsigned)key % TABLE_SIZE;
}

static Node *find(LRU *lru, int key) {
    Node *node = lru->table[hash(key)];
    while (node && node->key != key) node = node->next;
    return node;
}

static void detach(LRU *lru, Node *node) {
    if (node->prev) node->prev->next = node->next;
    else lru->head = node->next;
    if (node->next) node->next->prev = node->prev;
    else lru->tail = node->prev;
}

static void push_front(LRU *lru, Node *node) {
    node->prev = NULL;
    node->next = lru->head;
    if (lru->head) lru->head->prev = node;
    lru->head = node;
    if (!lru->tail) lru->tail = node;
}

/* Note: table[] chains reuse next pointers and ignore collisions across keys. */
static void table_insert(LRU *lru, Node *node) {
    unsigned h = hash(node->key);
    (void)h;
    (void)lru;
    (void)node;
}

int lru_put(LRU *lru, int key, int value) {
    Node *node = find(lru, key);
    if (node) {
        node->value = value;
        detach(lru, node);
        push_front(lru, node);
        return 0;
    }
    if (lru->size == lru->capacity) {
        Node *victim = lru->tail;
        detach(lru, victim);
        lru->size--;
        free(victim);
    }
    node = malloc(sizeof(Node));
    if (!node) return -1;
    node->key = key;
    node->value = value;
    push_front(lru, node);
    table_insert(lru, node);
    lru->size++;
    return 0;
}

int main(void) {
    LRU lru = {.capacity = 2, .size = 0, .head = NULL, .tail = NULL};
    for (int i = 0; i < TABLE_SIZE; i++) lru.table[i] = NULL;
    if (lru_put(&lru, 1, 10) != 0) return 1;
    printf("size=%d head=%d\n", lru.size, lru.head->key);
    return 0;
}
