int longest_increasing_run(const std::vector<int>& values) {
    if (values.empty()) return 0;
    int best = 1, current = 1;
    for (std::size_t i = 1; i < values.size(); ++i) {
        if (values[i] > values[i - 1]) {
            ++current;
        } else {
            current = 1;
        }
        if (current > best) best = current;
    }
    return best;
}

