```c
#include <stdio.h>

size_t reverse_in_place(char *s) {
    if (s == NULL) return 0;
    size_t length = 0;
    while (s[length] != '\0') ++length;
    for (size_t i = 0; i < length / 2; ++i) {
        char tmp = s[i];
        s[i] = s[length - 1 - i];
        s[length - 1 - i] = tmp;
    }
    return length;
}

int main(void) {
    char text[] = "hello world";
    size_t n = reverse_in_place(text);
    printf("%s (%zu)\n", text, n);

    char empty[] = "";
    printf("[%s] (%zu)\n", empty, reverse_in_place(empty));
    return 0;
}
```

Length is measured by hand to avoid `strlen`. The swap loop stops at the midpoint so the middle character of an odd-length string stays put, and the end pointer is always `length - 1 - i`, which is never out of bounds. A NULL pointer is handled defensively.

