```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    node->value = value;
    node->next = head;
    return node;
}

static void print_list(const Node *head) {
    for (const Node *n = head; n != NULL; n = n->next) {
        printf("%d", n->value);
        if (n->next != NULL) printf(" -> ");
    }
    putchar('\n');
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++) {
        head = push(head, i);
    }
    print_list(head);          /* 5 -> 4 -> 3 -> 2 -> 1 */
    head = reverse(head);      /* 1 -> 2 -> 3 -> 4 -> 5 */
    print_list(head);

    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
```

The in-place loop swaps three pointers per node and returns the new head, which is the old tail. `push` builds the list in reverse so the initial print shows `5 -> 4 -> 3 -> 2 -> 1`. The final loop frees every node. Note `reverse(NULL)` correctly returns `NULL`.

