```cpp
#include <iostream>
#include <unordered_map>
#include <cstdint>

std::unordered_map<int, uint64_t> memo;

uint64_t fib(int n) {
    if (n < 0) return 0;
    if (n <= 1) return static_cast<uint64_t>(n);

    auto it = memo.find(n);
    if (it != memo.end()) return it->second;

    uint64_t value = fib(n - 1) + fib(n - 2);
    memo[n] = value;
    return value;
}

int main() {
    for (int n = 0; n <= 10; ++n) {
        std::cout << "fib(" << n << ") = " << fib(n) << '\n';
    }
    // fib(90) is the largest value that fits in uint64_t.
    std::cout << "fib(90) = " << fib(90) << '\n';
    return 0;
}
```

`n <= 1` returns `n` directly, so `fib(0) == 0` and `fib(1) == 1` without touching the map. Memoization turns the naive O(2^n) recursion into O(n) calls. `uint64_t` overflows around `fib(93)`, which is why 90 is the largest safe print here.

