from collections import defaultdict
from pathlib import Path
import sys


def size_by_extension(root: str) -> list[tuple[str, int]]:
    totals: dict[str, int] = defaultdict(int)
    base = Path(root)

    for path in base.rglob("*"):
        if not path.is_file():
            continue
        ext = path.suffix.lower() or "<none>"
        try:
            totals[ext] += path.stat().st_size
        except OSError as exc:
            print(f"skip {path}: {exc}", file=sys.stderr)

    return sorted(totals.items(), key=lambda item: item[1], reverse=True)


if __name__ == "__main__":
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    for ext, total in size_by_extension(root):
        print(f"{ext:>10}  {total}")
```

`Path.rglob("*")` yields every entry recursively, and `is_file()` filters out directories and special files. `defaultdict(int)` keeps the code compact. `path.stat()` is wrapped so a broken symlink or permission error prints a warning instead of aborting the whole walk. The `lambda` sorts by byte count descending.

