import re

_POSTCODE = re.compile(
    r"^(GIR 0AA|[A-PR-UWYZ][A-HK-Y]?[0-9][0-9A-HJKPSTUW]? ?[0-9][ABD-HJLNP-UW-Z]{2})$"
)

def normalize_postcode(raw: str) -> str:
    if not raw:
        raise ValueError("empty postcode")
    candidate = " ".join(raw.split()).upper()
    m = _POSTCODE.match(candidate)
    if not m:
        raise ValueError(f"invalid postcode: {raw!r}")
    # Insert the canonical single space before the final 3 chars.
    return candidate[:-3].strip() + " " + candidate[-3:]

if __name__ == "__main__":
    for p in ["sw1a1aa", "EC1A 1BB", "not-a-postcode"]:
        try:
            print(p, "->", normalize_postcode(p))
        except ValueError as e:
            print(p, "->", e)
