char *reverse_in_place(char *s) {
    if (s == NULL) {
        return NULL;
    }
    size_t n = strlen(s);
    for (size_t i = 0; i < n / 2; ++i) {
        char tmp = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = tmp;
    }
    return s;
}

int main(void) {
    char buf1[] = "hello";
    char buf2[] = "";
    printf("%s\n", reverse_in_place(buf1));  // olleh
    printf("%s\n", reverse_in_place(buf2));  // (empty)
    printf("%p\n", (void *)reverse_in_place(NULL));  // (nil)
    return 0;
}
