use std::collections::HashMap;

/// Top three characters by frequency. Ties broken by ascending char order.
/// Returns fewer than three entries for short inputs.
pub fn top_three(s: &str) -> Vec<(char, usize)> {
    let mut counts: HashMap<char, usize> = HashMap::new();
    for c in s.chars() {
        *counts.entry(c).or_insert(0) += 1;
    }
    let mut items: Vec<(char, usize)> = counts.into_iter().collect();
    items.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    items.truncate(3);
    items
}

fn main() {
    assert_eq!(top_three("aabbbccdd"), vec![('b', 3), ('a', 2), ('c', 2)]);
    assert_eq!(top_three(""), Vec::new());
    assert_eq!(top_three("éé"), vec![('é', 2)]);
    println!("ok");
}
