use std::fs::File;
use std::io::{self, BufRead, BufReader};

/// Returns Ok(true) if any line contains `needle` as raw bytes.
/// Uses read_until to stay UTF-8 agnostic.
pub fn file_contains_bytes(path: &str, needle: &[u8]) -> io::Result<bool> {
    if needle.is_empty() {
        return Ok(true);
    }
    let file = File::open(path)?;
    let mut reader = BufReader::new(file);
    let mut buf = Vec::new();
    loop {
        buf.clear();
        let n = reader.read_until(b'\n', &mut buf)?;
        if n == 0 {
            break;
        }
        if buf.windows(needle.len()).any(|w| w == needle) {
            return Ok(true);
        }
    }
    Ok(false)
}

fn main() -> io::Result<()> {
    let found = file_contains_bytes("data.bin", b"error")?;
    println!("{found}");
    Ok(())
}
