```c
#include <stddef.h>

/* UTF-8 continuation byte check. */
static int is_cont(unsigned char c) { return (c & 0xC0) == 0x80; }

/* Reverse the UTF-8 string `src` by codepoint into `dst` of capacity `cap`.
 * Returns number of bytes written (excluding NUL) on success, or -1 if the
 * buffer is too small. Always NUL-terminates when cap > 0. */
long utf8_reverse(const char *src, char *dst, size_t cap) {
    if (cap == 0) return -1;

    /* Collect byte offsets of each codepoint start. */
    const unsigned char *s = (const unsigned char *)src;
    size_t starts[256];
    size_t n = 0;
    for (size_t i = 0; s[i] != '\0'; ) {
        if (n >= 256) return -1;
        starts[n++] = i;
        i++;
        while (is_cont(s[i])) i++;
    }

    size_t out = 0;
    for (size_t k = n; k-- > 0; ) {
        size_t start = starts[k];
        size_t end = (k + 1 < n) ? starts[k + 1] : 0;
        if (end == 0) {
            end = start;
            while (s[end] != '\0') end++;
        }
        size_t len = end - start;
        if (out + len + 1 > cap) return -1;
        for (size_t j = 0; j < len; j++) dst[out++] = (char)s[start + j];
    }
    dst[out] = '\0';
    return (long)out;
}
