#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(T value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
        else tail_ = (tail_ + 1) % N;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0, tail_ = 0, size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int v = 1; v <= 5; ++v) rb.push(v);
    while (auto v = rb.pop()) std::cout << *v << ' '; // 3 4 5
    std::cout << '\n';
    return 0;
}
