#[derive(Debug, PartialEq)]
enum ParseError {
    BadToken { token: String, position: usize },
    Parse(ParseIntError),
}

fn parse_list(input: &str) -> Result<Vec<i64>, ParseError> {
    if input.trim().is_empty() {
        return Ok(Vec::new());
    }
    input
        .split(',')
        .enumerate()
        .map(|(i, tok)| {
            let t = tok.trim();
            t.parse::<i64>().map_err(|e| {
                if e.kind() == &std::num::IntErrorKind::InvalidDigit {
                    ParseError::BadToken { token: t.to_string(), position: i }
                } else {
                    ParseError::Parse(e)
                }
            })
        })
        .collect()
}

fn main() {
