    assert_eq!(parse_list("").unwrap(), Vec::<i64>::new());
    match parse_list("1, x, 3") {
        Err(ParseError::BadToken { token, position }) => {
            println!("bad token {:?} at index {}", token, position);
        }
        other => panic!("expected error, got {:?}", other),
    }
