def is_valid_ipv4(address: str) -> bool:
    """Return True iff address is a dotted-quad IPv4 with octets 0-255."""
    if not isinstance(address, str):
        return False
    parts = address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":  # reject leading zeros
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True

if __name__ == "__main__":
    cases = ["192.168.0.1", "0.0.0.0", "256.1.1.1", "1.2.3", "1.2.3.04", "a.b.c.d"]
    for c in cases:
        print(c, is_valid_ipv4(c))
