#include <stdio.h>
#include <stdint.h>

#define MOD 1000000007ULL

// Returns F(n) mod MOD using fast doubling.
static uint64_t fib(uint64_t n) {
    uint64_t a = 0, b = 1; /* F(0), F(1) */
    for (int i = 63; i >= 0; i--) {
        uint64_t c = (a * ((2 * b % MOD + MOD - a) % MOD)) % MOD; /* F(2k) */
        uint64_t d = (a * a % MOD + b * b % MOD) % MOD;           /* F(2k+1) */
        if ((n >> i) & 1ULL) { a = d; b = (c + d) % MOD; }
        else                 { a = c; b = d; }
    }
    return a;
}

int main(void) {
    uint64_t n;
    if (scanf("%llu", (unsigned long long *)&n) != 1) {
        fprintf(stderr, "expected an integer\n");
        return 1;
    }
    printf("%llu\n", (unsigned long long)fib(n));
    return 0;
}
