```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    capacity: usize,
    start: usize,
    len: usize,
}

impl<T: Copy> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        RingBuffer {
            data: vec![None; capacity],
            capacity,
            start: 0,
            len: 0,
        }
    }

    pub fn push(&mut self, value: T) {
        let index = (self.start + self.len) % self.capacity;
        self.data[index] = Some(value);
        if self.len == self.capacity {
            self.start = (self.start + 1) % self.capacity;
        } else {
            self.len += 1;
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn iter(&self) -> impl Iterator<Item = T> + '_ {
        (0..self.len).map(move |offset| {
            let index = (self.start + offset) % self.capacity;
            self.data[index].expect("slot inside len must be filled")
        })
    }
}

fn main() {
    let mut buffer: RingBuffer<i32> = RingBuffer::new(3);
    assert!(buffer.is_empty());
    for value in 1..=5 {
        buffer.push(value);
    }
    assert_eq!(buffer.len(), 3);
    let kept: Vec<i32> = buffer.iter().collect();
    assert_eq!(kept, vec![3, 4, 5]);
    println!("kept: {:?}", kept);
}
```
The buffer writes at `(start + len) % capacity` and advances `start` only once full, so only the newest `capacity` items survive. `T: Copy` keeps iteration simple; for owned types you'd iterate over references instead.

