```c
#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* Copies src into dst (capacity bytes). Always NUL-terminates.
 * Returns the number of bytes copied, excluding the NUL.
 * Sets *truncated to 1 if src did not fit. */
size_t copy_string(char *dst, size_t capacity, const char *src, int *truncated) {
    if (dst == NULL || capacity == 0) {
        if (truncated != NULL) {
            *truncated = (src != NULL && src[0] != '\0');
        }
        return 0;
    }

    size_t i = 0;
    if (src != NULL) {
        while (i + 1 < capacity && src[i] != '\0') {
            dst[i] = src[i];
            i++;
        }
    }
    dst[i] = '\0';

    if (truncated != NULL) {
        *truncated = (src != NULL && src[i] != '\0');
    }
    return i;
}

int main(void) {
    char small[8];
    int trunc = 0;

    copy_string(small, sizeof small, "hello", &trunc);
    printf("'%s' truncated=%d\n", small, trunc);

    copy_string(small, sizeof small, "abcdefghij", &trunc);
    printf("'%s' truncated=%d\n", small, trunc);

    copy_string(small, sizeof small, NULL, &trunc);
    printf("'%s' truncated=%d\n", small, trunc);
    return 0;
}
```
The loop reserves one byte for the terminator (`i + 1 < capacity`), so `dst` is always a valid C string even when truncated. `NULL` sources are treated as empty, and `truncated` is optional.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._items = OrderedDict()

    def get(self, key, default=None):
        if key not in self._items:
            return default
        self._items.move_to_end(key)
        return self._items[key]

    def put(self, key, value):
        if key in self._items:
            self._items.move_to_end(key)
        self._items[key] = value
        if len(self._items) > self.capacity:
            self._items.popitem(last=False)

    def __len__(self):
        return len(self._items)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1          # 'a' is now most recent
    cache.put("c", 3)                   # evicts 'b'
    assert cache.get("b") is None
    assert cache.get("c") == 3
    assert len(cache) == 2
    cache.put("c", 30)
    assert cache.get("c") == 30         # update keeps one entry
    print("ok")
```
`OrderedDict` gives O(1) moves and pops: `move_to_end` marks a hit as recent, and `popitem(last=False)` evicts the least recently used entry when capacity is exceeded.

