```c
#include <stdio.h>

static void reverse(int *a, int lo, int hi) {
    while (lo < hi) {
        int t = a[lo];
        a[lo++] = a[hi];
        a[hi--] = t;
    }
}

void rotate_right(int *a, int n, int k) {
    if (n <= 1) return;
    k %= n;
    if (k < 0) k += n;
    if (k == 0) return;
    reverse(a, 0, n - 1);
    reverse(a, 0, k - 1);
    reverse(a, k, n - 1);
}

int main(void) {
    int a[] = {1, 2, 3, 4, 5, 6, 7};
    int n = sizeof(a) / sizeof(a[0]);
    rotate_right(a, n, 3);
    for (int i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");

    int b[] = {10, 20};
    rotate_right(b, 2, 0);
    printf("%d %d\n", b[0], b[1]);

    rotate_right(b, 2, -1);  /* negative k normalises to 1 */
    printf("%d %d\n", b[0], b[1]);
    return 0;
}
