```cpp
#include <atomic>
#include <condition_variable>
#include <cstddef>
#include <iostream>
#include <mutex>
#include <optional>
#include <queue>
#include <thread>
#include <vector>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    bool try_push(T value) {
        std::lock_guard<std::mutex> lock(m_);
        if (closed_ || q_.size() >= cap_) return false;
        q_.push(std::move(value));
        cv_.notify_one();
        return true;
    }

    std::optional<T> try_pop() {
        std::lock_guard<std::mutex> lock(m_);
        if (q_.empty()) return std::nullopt;
        T v = std::move(q_.front());
        q_.pop();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lock(m_);
        closed_ = true;
        cv_.notify_all();
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(m_);
        return q_.size();
    }

private:
    mutable std::mutex m_;
    std::condition_variable cv_;
    std::queue<T> q_;
    std::size_t cap_;
    bool closed_ = false;
};

int main() {
    BoundedQueue<int> q(3);
    std::atomic<int> produced{0};
    std::vector<std::thread> workers;

    for (int w = 0; w < 2; ++w) {
        workers.emplace_back([&] {
            for (int i = 1; i <= 1000; ++i) {
                while (!q.try_push(i)) std::this_thread::yield();
                produced.fetch_add(1);
            }
        });
    }

    std::atomic<int> consumed{0};
    std::thread reader([&] {
        while (consumed.load() < produced.load() || q.size() > 0) {
            if (auto v = q.try_pop()) consumed.fetch_add(1);
            else std::this_thread::yield();
        }
    });

    for (auto& w : workers) w.join();
    reader.join();
    std::cout << "produced=" << produced.load() << " consumed=" << consumed.load() << "\n";
    return 0;
}
```

Both operations take the mutex and take the non-blocking path, so `try_push`/`try_pop` never stall the caller — callers decide how to back off. `close()` lets a consumer distinguish shutdown from a transient full queue.

