#include <stdbool.h>
#include <stdio.h>
#include <string.h>

static bool is_opener(char c) { return c == '(' || c == '[' || c == '{'; }

static char closing_for(char c) {
    switch (c) {
        case '(': return ')';
        case '[': return ']';
        case '{': return '}';
        default:  return '\0';
    }
}

bool balanced(const char *s) {
    size_t n = strlen(s);
    char stack[256];
    size_t top = 0;
    for (size_t i = 0; i < n; i++) {
        char c = s[i];
        if (is_opener(c)) {
            if (top >= sizeof(stack) / sizeof(stack[0])) return false;
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) return false;
            if (closing_for(stack[--top]) != c) return false;
        }
        /* other characters are ignored */
    }
    return top == 0;
}

int main(void) {
    const char *cases[] = {
        "(a[b]{c})", "([)]", "(((", ")", "", "{[()]}", "no brackets here"
    };
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
        printf("%-18s -> %s\n", cases[i], balanced(cases[i]) ? "balanced" : "not balanced");
    }
    return 0;
}
```

Power-of-two nesting depth up to 256 is stack-bound; an empty string counts as balanced, and `([)]` correctly fails because the innermost closer does not match the top opener.

