#include <array>
#include <iostream>
#include <optional>
#include <cstddef>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << '\n'; // 1110
    std::cout << *rb.pop() << *rb.pop() << '\n';                               // 12
    rb.push(9);
    std::cout << rb.size() << '\n';                                            // 2
}
```

`head_` and `count_` index a circular array; push fails when full and pop returns `std::nullopt` when empty, so the caller always knows the outcome.

