#include <array>
#include <cstddef>
#include <cassert>
#include <iostream>

template <typename T, std::size_t N>
class RingBuffer {
    std::array<T, N> buf_{};
    std::size_t head_ = 0;  // next write
    std::size_t tail_ = 0;  // next read
    std::size_t size_ = 0;

public:
    bool push(const T& value) {
        if (size_ == N) return false;
        buf_[head_] = value;
        head_ = (head_ + 1) % N;
        ++size_;
        return true;
    }

    bool pop(T& out) {
        if (size_ == 0) return false;
        out = buf_[tail_];
        tail_ = (tail_ + 1) % N;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }
};

int main() {
    RingBuffer<int, 3> rb;
    int v = 0;
    assert(rb.pop(v) == false);
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.push(4) == false);          // full
    assert(rb.pop(v) && v == 1);
    assert(rb.push(4));                    // wraps
    assert(rb.pop(v) && v == 2);
    assert(rb.pop(v) && v == 3);
    assert(rb.pop(v) && v == 4);
    assert(rb.pop(v) == false);
    std::cout << "ok\n";
}
