    char a[] = "hello world   \t\n";
    size_t n = rstrip_in_place(a);
    printf("[%s] len=%zu\n", a, n);  /* [hello world] len=11 */

    char b[] = "   ";
    printf("len=%zu\n", rstrip_in_place(b));  /* len=0 */

    char c[] = "";
    printf("len=%zu\n", rstrip_in_place(c));  /* len=0 */
