#include <string>
#include <stack>
#include <unordered_map>
#include <cassert>

bool balanced(const std::string& s) {
    static const std::unordered_map<char, char> match = {
        {')', '('}, {']', '['}, {'}', '{'}
    };
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else {
            auto it = match.find(c);
            if (it == match.end())
                return false;
            if (st.empty() || st.top() != it->second)
                return false;
            st.pop();
        }
    }
    return st.empty();
}

int main() {
    assert(balanced(""));
    assert(balanced("()[]{} "));
    assert(balanced("([{}])"));
    assert(!balanced("([)]"));
    assert(!balanced("("));
    return 0;
}
```

An empty string is trivially balanced. Nesting order is enforced by matching each closer against the stack top rather than just counting brackets.

