```cpp
#include <iostream>
#include <optional>
#include <stdexcept>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), size_(0), capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool push(const T& value) {
        if (full()) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % capacity_;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = buf_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == capacity_; }
    std::size_t size() const { return size_; }

private:
    std::vector<T> buf_;
    std::size_t head_, tail_, size_, capacity_;
};

int main() {
    RingBuffer<int> rb(3);
    rb.push(1); rb.push(2); rb.push(3);
    std::cout << "push on full: " << rb.push(4) << "\n";
    while (auto v = rb.pop()) std::cout << *v << " ";
    std::cout << "\nempty after pop: " << rb.empty() << "\n";
    return 0;
}
```

Push returns `false` on a full buffer and pop returns `std::nullopt` on empty, so callers never read uninitialised memory. Heads and tails wrap with modular arithmetic.

