```cpp
#include <cstddef>
#include <iostream>

struct Node {
    int value;
    Node* next;
    Node(int v, Node* n = nullptr) : value(v), next(n) {}
};

Node* reverse_iter(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

Node* reverse_rec(Node* head) {
    if (!head || !head->next) return head;
    Node* rest = reverse_rec(head->next);
    head->next->next = head;
    head->next = nullptr;
    return rest;
}

void free_list(Node* head) {
    while (head) {
        Node* nxt = head->next;
        delete head;
        head = nxt;
    }
}

void print(Node* head) {
    for (Node* p = head; p; p = p->next)
        std::cout << p->value << (p->next ? " -> " : "\n");
}

int main() {
    Node* head = new Node(1, new Node(2, new Node(3, new Node(4))));
    head = reverse_iter(head);
    print(head);
    head = reverse_rec(head);
    print(head);
    free_list(head);
}
```

Iterative reversal is O(n) time, O(1) space; recursive uses O(n) stack. Empty list returns `nullptr` safely in both.

