fn is_balanced(input: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for ch in input.chars() {
        match ch {
            '(' | '[' | '{' => stack.push(ch),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(expected) {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    let cases = [
        ("()[]{}", true),
        ("([{}])", true),
        ("(]", false),
        ("(((", false),
        ("", true),
        ("a(b)c[d]", true),
    ];
    for (s, want) in cases {
        let got = is_balanced(s);
        println!("{:?} -> {} (expected {})", s, got, want);
        assert_eq!(got, want);
    }
}
