            return false;
        }
        ++i;
        --j;
    }
    return true;
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::cout << (is_palindrome(line) ? "true" : "false") << "\n";
    }
    return 0;
}
```

Two pointers move inward, skipping anything that isn't alphanumeric. Casting to `unsigned char` before passing to `isalnum`/`tolower` avoids undefined behaviour on bytes above 127 (non-ASCII input). An empty string returns true, which is the standard convention.

```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 3, 8];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 3, 5, 7, 8]);
    assert_eq!(merge_sorted::<i32>(&[], &[1, 2]), vec![1, 2]);
    println!("all checks passed");
}
```

The `<=` comparison takes from `a` on ties, which keeps the merge stable. Once one side is exhausted, the remaining slice is copied wholesale with `extend_from_slice`. The generic `merge_sorted::<i32>` turbofish in the empty case just disambiguates the type since both arguments are empty slices. Runtime is O(m+n).

```c
#include <string.h>
#include <stdio.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;
    char *a = s;
    char *b = s + len - 1;
    while (a < b) {
        char tmp = *a;
        *a = *b;
        *b = tmp;
        a++;
        b--;
    }
}

int main(void) {
    char buf1[] = "hello";
    reverse_in_place(buf1);
    printf("%s\n", buf1);   /* olleh */

    char buf2[] = "";
    reverse_in_place(buf2);
    printf("\"%s\"\n", buf2); /* "" */

    reverse_in_place(NULL);  /* must not crash */
    return 0;
}
```

The string must be a writable array (`char buf1[] = "hello"`), never a string literal — modifying a literal is undefined behaviour. `strlen` gives the length excluding the terminator, so `s + len - 1` is the last character. The `len < 2` guard handles empty strings and single characters, and the NULL check protects callers who pass an uninitialised pointer.

