```cpp
#include <array>
#include <cstddef>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    T pop() {
        if (count_ == 0) throw std::underflow_error("ring buffer empty");
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

#include <cassert>
int main() {
    RingBuffer<int, 3> rb;
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(!rb.push(4));       // full
    assert(rb.pop() == 1);     // FIFO
    assert(rb.push(4));
    assert(rb.size() == 3);
    return 0;
}
```

`head_` is the index of the oldest element and `count_` tracks occupancy, so the modulo wraps both the write position and the read position. Popping while empty throws rather than returning garbage. The capacity `N` is a compile-time constant via `std::array`.

