```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) {
        return head;
    }
    n->value = value;
    n->next = head;
    return n;
}

static void print_list(const Node *head) {
    for (const Node *n = head; n != NULL; n = n->next) {
        printf("%d ", n->value);
    }
    printf("\n");
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 1; i <= 5; i++) {
        list = push(list, i);
    }
    print_list(list);          /* 5 4 3 2 1 */
    list = reverse(list);
    print_list(list);          /* 1 2 3 4 5 */

    Node *empty = NULL;
    empty = reverse(empty);
    print_list(empty);         /* blank line */

    free_list(list);
    return 0;
}
