#include <iostream>
#include <sstream>
#include <stack>
#include <string>

int main() {
    std::stack<double> st;
    std::string token;

    while (std::cin >> token) {
        if (token == "+" || token == "-" || token == "*" || token == "/") {
            if (st.size() < 2) {
                std::cerr << "error: not enough operands for " << token << '\n';
                return 1;
            }
            double b = st.top(); st.pop();
            double a = st.top(); st.pop();
            double r = 0.0;
            if (token == "+") r = a + b;
            else if (token == "-") r = a - b;
            else if (token == "*") r = a * b;
            else {
                if (b == 0.0) {
                    std::cerr << "error: division by zero\n";
                    return 1;
                }
                r = a / b;
            }
            st.push(r);
        } else {
            try {
                size_t pos = 0;
                double value = std::stod(token, &pos);
                if (pos != token.size()) throw std::invalid_argument("trailing");
                st.push(value);
            } catch (...) {
                std::cerr << "error: bad token: " << token << '\n';
                return 1;
            }
        }
    }

    if (st.size() != 1) {
        std::cerr << "error: stack has " << st.size() << " values at end\n";
        return 1;
    }
    std::cout << st.top() << '\n';
    return 0;
}
