pub fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' => if stack.pop() != Some('(') { return false; },
            ']' => if stack.pop() != Some('[') { return false; },
            '}' => if stack.pop() != Some('{') { return false; },
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    assert!(is_balanced(""), "empty is balanced");
    assert!(is_balanced("a(b[c]{d})e"));
    assert!(!is_balanced("(]"));
    assert!(!is_balanced("(()"));
    assert!(!is_balanced(")"));
    assert!(is_balanced("no brackets here"));
    println!("ok");
}
```
A stack catches both mismatched types and premature closers. Non-bracket characters are ignored, and the final stack must be empty.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1          # 'a' is now most recent
    c.put("c", 3)                    # evicts 'b'
    assert c.get("b") is None
    assert c.get("c") == 3
    assert len(c) == 2
    try:
        LRUCache(0)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
    print("ok")
```
`OrderedDict.move_to_end` plus `popitem(last=False)` gives O(1) amortised operations. A zero or negative capacity is rejected up front.

