import bisect

def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

if __name__ == "__main__":
    cases = [[], [1], [1, 3], [1, 2, 3, 4, 5], [2, 4, 6, 8, 10, 12]]
    for arr in cases:
        for target in range(0, 14):
            got = binary_search(arr, target)
            idx = bisect.bisect_left(arr, target)
            expected = idx if idx < len(arr) and arr[idx] == target else -1
            assert got == expected, (arr, target, got, expected)
    print("all assertions passed")
```
Self-checking against `bisect`, including empty and single-element arrays.

```cpp
#include <iostream>
#include <vector>

long long fib_memo(unsigned n, std::vector<long long>& memo) {
    if (n < 2) return n;
    if (memo[n] != -1) return memo[n];
    return memo[n] = fib_memo(n - 1, memo) + fib_memo(n - 2, memo);
}

long long fib_loop(unsigned n) {
    long long a = 0, b = 1;
    for (unsigned i = 0; i < n; ++i) {
        long long t = a + b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    const unsigned limit = 50;
    std::vector<long long> memo(limit + 1, -1);
    for (unsigned i = 0; i <= limit; ++i) {
        long long m = fib_memo(i, memo);
        long long l = fib_loop(i);
        if (m != l) {
            std::cerr << "mismatch at " << i << ": " << m << " vs " << l << '\n';
            return 1;
        }
    }
    std::cout << "fib(50) = " << memo[50] << "\n";
    return 0;
}
```
`long long` keeps fib(50) exact; the two methods cross-check every value up to the limit.

Two heaps keep the lower half and upper half balanced; the median is the top of the larger side or the average of both tops.

```cpp
#include <iostream>
#include <queue>
#include <vector>
#include <cstddef>

int main() {
    std::priority_queue<long long> low;                              // max-heap
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> high; // min-heap
    long long value;
    while (std::cin >> value) {
        if (low.empty() || value <= low.top()) {
            low.push(value);
        } else {
            high.push(value);
        }
        // Rebalance so lows.size() == highs.size() or lows.size() == highs.size() + 1
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }
        std::size_t total = low.size() + high.size();
        if (total % 2 == 1) {
            std::cout << low.top() << '\n';
        } else {
            std::cout << (low.top() + high.top()) / 2.0 << '\n';
        }
    }
    return 0;
}
```

Compile with `g++ -std=c++17 -O2 -o median median.cpp`. Non-numeric or malformed input terminates the loop early because the stream enters a fail state; each valid line produces one median output. Empty input produces no output.

The program reads bytes, decodes with `from_utf8_lossy` so invalid sequences become U+FFFD instead of panicking, then uses a HashMap.

```rust
use std::collections::HashMap;
use std::env;
use std::fs;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("usage: {} <file>", args[0]);
        process::exit(2);
    }
    let bytes = match fs::read(&args[1]) {
        Ok(b) => b,
        Err(e) => {
            eprintln!("error reading {}: {}", args[1], e);
            process::exit(1);
        }
    };
    let text = String::from_utf8_lossy(&bytes);
    let mut counts: HashMap<String, u64> = HashMap::new();
    for word in text.split_whitespace() {
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, u64)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    for (word, count) in pairs.iter().take(10) {
        println!("{}\t{}", word, count);
    }
}
```

Build with `cargo build --release` or `rustc -O top_words.rs`. An empty file prints nothing. Non-UTF-8 bytes are replaced with U+FFFD during decoding rather than crashing the program.

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

static struct Node *push(struct Node *head, int value) {
    struct Node *node = malloc(sizeof *node);
    if (!node) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    node->value = value;
    node->next = head;
    return node;
}

static struct Node *reverse(struct Node *head) {
    struct Node *prev = NULL;
    while (head) {
        struct Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_and_free(struct Node *head) {
    while (head) {
        printf("%d ", head->value);
        struct Node *next = head->next;
        free(head);
        head = next;
    }
    putchar('\n');
}

int main(void) {
    struct Node *list = NULL;
    for (int i = 1; i <= 5; ++i) {
        list = push(list, i);
    }
    // list is 5 4 3 2 1
    list = reverse(list);
    print_and_free(list);   // prints 1 2 3 4 5
    return 0;
}
```

Compile with `cc -Wall -Wextra -O2 -o reverse reverse.c`. The reversal rewrites each `next` pointer in place with three cursors, so it is O(n) time and O(1) extra space. `print_and_free` captures the next pointer before freeing to avoid a use-after-free.

A minimal parser for the common `scheme://host[:port]/path` shape, with explicit errors.

```rust
#[derive(Debug, PartialEq)]
pub struct Url<'a> {
    pub scheme: &'a str,
    pub host: &'a str,
    pub port: Option<u16>,
}

#[derive(Debug, PartialEq)]
pub enum UrlError {
    MissingScheme,
    MissingHost,
    InvalidPort,
}

pub fn parse(input: &str) -> Result<Url<'_>, UrlError> {
    let (scheme, rest) = input.split_once("://").ok_or(UrlError::MissingScheme)?;
    if scheme.is_empty() || !scheme.chars().all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.') {
        return Err(UrlError::MissingScheme);
    }
    let authority = rest.split(['/', '?', '#']).next().unwrap_or("");
    let (host, port) = match authority.rsplit_once(':') {
        Some((h, p)) if !h.contains(":") => match p.parse::<u16>() {
            Ok(num) => (h, Some(num)),
            Err(_) => return Err(UrlError::InvalidPort),
        },
        _ => (authority, None),
    };
    if host.is_empty() {
        return Err(UrlError::MissingHost);
    }
    Ok(Url { scheme, host, port })
}

fn main() {
    assert_eq!(
        parse("https://example.com:8443/a?b").unwrap(),
        Url { scheme: "https", host: "example.com", port: Some(8443) }
    );
    assert_eq!(parse("ftp://mirror").unwrap().port, None);
    assert_eq!(parse("example.com"), Err(UrlError::MissingScheme));
    assert_eq!(parse("http://:9000"), Err(UrlError::MissingHost));
    assert_eq!(parse("http://host:notaport"), Err(UrlError::InvalidPort));
    println!("all checks passed");
}
```

Run with `rustc -O url.rs && ./url`. The parser rejects empty schemes and hosts rather than returning a partial struct, and a port above 65535 fails `u16` parsing, surfacing as `InvalidPort`. It does not validate DNS names or percent-encoding — that would need a full URL crate.

