#include <iostream>
#include <vector>
#include <optional>
#include <string>
#include <cmath>

template <typename T>
std::optional<T> dot(const std::vector<T>& a, const std::vector<T>& b) {
    if (a.size() != b.size()) {
        return std::nullopt;
    }
    T sum = T{};
    for (std::size_t i = 0; i < a.size(); ++i) {
        sum += a[i] * b[i];
    }
    return sum;
}

int main() {
    std::vector<double> x{1.0, 2.0, 3.0};
    std::vector<double> y{4.0, 5.0, 6.0};

    if (auto r = dot(x, y)) {
        // Tolerance-based comparison because floating point is not exact.
        if (std::fabs(*r - 32.0) < 1e-9) {
            std::cout << "dot = " << *r << "\n";
        } else {
            std::cout << "unexpected result: " << *r << "\n";
        }
    } else {
        std::cout << "size mismatch\n";
    }

    std::vector<double> short_vec{1.0};
    std::cout << (dot(x, short_vec).has_value() ? "ok" : "size mismatch") << "\n";
    return 0;
}
```

Compile with `g++ -std=c++17 -Wall -Wextra -O2 -o dot dot.cpp`. `std::optional` distinguishes a genuine zero dot product from a size mismatch, which a sentinel like `-1.0` could not. The template also works with `float` or `int`, though integer overflow is the caller's responsibility.

