#include <string.h>

int main(void) {
    char buf[256];
    if (!fgets(buf, sizeof buf, stdin)) {
        return 0;
    }
    size_t len = strlen(buf);
    while (len > 0 && (buf[len - 1] == '\n' || buf[len - 1] == '\r')) {
        buf[--len] = '\0';
    }
    char *left = buf;
    char *right = buf + len - 1;
    while (left < right) {
        char t = *left;
        *left++ = *right;
        *right-- = t;
    }
    puts(buf);
    return 0;
}
