def fib_fast(n: int) -> int:
    """Return the nth Fibonacci number (F(0)=0, F(1)=1) in O(log n)."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def pair(k):
        # returns (F(k), F(k+1))
        if k == 0:
            return (0, 1)
        a, b = pair(k >> 1)
        c = a * ((b << 1) - a)          # F(2m) = F(m)*(2F(m+1)-F(m))
        d = a * a + b * b               # F(2m+1) = F(m)^2 + F(m+1)^2
        if k & 1:
            return (d, c + d)
        return (c, d)

    return pair(n)[0]


def fib_naive(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


if __name__ == "__main__":
    for i in range(31):
        f, s = fib_fast(i), fib_naive(i)
        assert f == s, (i, f, s)
    print(fib_fast(100))
    print("all 0..30 match")
```
Recursion depth is O(log n), so n=10**6 is fine; the check loop confirms both implementations agree on every small input.

