```cpp
#include <condition_variable>
#include <iostream>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>
#include <thread>
#include <vector>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t cap) : cap_(cap) {
        if (cap == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(T value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return closed_ || q_.size() < cap_; });
        if (closed_) throw std::runtime_error("push on closed queue");
        q_.push(std::move(value));
        not_empty_.notify_one();
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;  // closed and drained
        T value = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::queue<T> q_;
    std::size_t cap_;
    bool closed_ = false;
    std::mutex mu_;
    std::condition_variable not_empty_, not_full_;
};

int main() {
    BoundedQueue<int> q(4);
    std::vector<std::thread> consumers;
    for (int c = 0; c < 2; ++c) {
        consumers.emplace_back([&q, c] {
            while (auto v = q.pop()) std::cout << "consumer " << c << ": " << *v << '\n';
        });
    }
    for (int i = 0; i < 20; ++i) q.push(i);
    q.close();
    for (auto& t : consumers) t.join();
}
```
`close()` wakes both waiters so consumers drain the queue and exit instead of hanging, and the predicate forms guard against spurious wakeups.

