#include <cstdint>
#include <iostream>
#include <optional>
#include <sstream>
#include <string>

std::optional<std::uint32_t> parse_ipv4(const std::string& s) {
    std::uint32_t result = 0;
    std::size_t start = 0;
    for (int octet = 0; octet < 4; ++octet) {
        const std::size_t dot = s.find('.', start);
        const bool last = (octet == 3);
        if (last ? (dot != std::string::npos) : (dot == std::string::npos))
            return std::nullopt;
        const std::string part = s.substr(start, (last ? s.size() : dot) - start);
        if (part.empty() || part.size() > 3) return std::nullopt;
        if (part.size() > 1 && part[0] == '0') return std::nullopt;  // no leading zeros
        int value = 0;
        for (char ch : part) {
            if (ch < '0' || ch > '9') return std::nullopt;
            value = value * 10 + (ch - '0');
        }
        if (value > 255) return std::nullopt;
        result = (result << 8) | static_cast<std::uint32_t>(value);
        start = last ? s.size() : dot + 1;
    }
    return result;
}

int main() {
    const char* good[] = {"0.0.0.0", "127.0.0.1", "255.255.255.255", "192.168.1.10"};
    const char* bad[]  = {"256.0.0.1", "1.2.3", "01.2.3.4", "1.2.3.4.5", "1.2.3.", "a.b.c.d", "1.2.3.4 "};
    for (auto ip : good) if (!parse_ipv4(ip)) { std::cerr << "expected ok: " << ip << '\n'; return 1; }
    for (auto ip : bad)  if (parse_ipv4(ip))  { std::cerr << "expected fail: " << ip << '\n'; return 1; }
    std::cout << "all cases passed\n";
}
```
The parser deliberately rejects leading zeros (`"01"`) because in real configs they are ambiguous octal, and the trailing-space case is caught since a space is not a digit.

```rust
use std::collections::HashMap;

struct Node<K, V> {
    key: K,
    value: V,
    prev: Option<usize>,
    next: Option<usize>,
}

pub struct LruCache<K, V> {
    cap: usize,
    map: HashMap<K, usize>,
    nodes: Vec<Node<K, V>>,
    head: Option<usize>, // most recently used
    tail: Option<usize>, // least recently used
    free: Vec<usize>,
}

impl<K: Eq + std::hash::Hash + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be > 0");
        Self { cap, map: HashMap::new(), nodes: Vec::new(), head: None, tail: None, free: Vec::new() }
    }

    fn unlink(&mut self, i: usize) {
        let (prev, next) = (self.nodes[i].prev, self.nodes[i].next);
        match prev { Some(p) => self.nodes[p].next = next, None => self.head = next }
        match next { Some(n) => self.nodes[n].prev = prev, None => self.tail = prev }
    }

    fn push_front(&mut self, i: usize) {
        self.nodes[i].prev = None;
        self.nodes[i].next = self.head;
        if let Some(h) = self.head { self.nodes[h].prev = Some(i); }
        self.head = Some(i);
        if self.tail.is_none() { self.tail = Some(i); }
    }

    fn alloc(&mut self, key: K, value: V) -> usize {
        if let Some(i) = self.free.pop() {
            self.nodes[i] = Node { key, value, prev: None, next: None };
            i
        } else {
            self.nodes.push(Node { key, value, prev: None, next: None });
            self.nodes.len() - 1
        }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        let i = *self.map.get(key)?;
        self.unlink(i);
        self.push_front(i);
        Some(&self.nodes[i].value)
    }

    pub fn put(&mut self, key: K, value: V) {
        if let Some(&i) = self.map.get(&key) {
            self.nodes[i].value = value;
            self.unlink(i);
            self.push_front(i);
            return;
        }
        if self.map.len() == self.cap {
            let victim = self.tail.expect("non-empty when full");
            self.unlink(victim);
            let old_key = self.nodes[victim].key.clone();
            self.map.remove(&old_key);
            self.free.push(victim);
        }
        let i = self.alloc(key.clone(), value);
        self.push_front(i);
        self.map.insert(key, i);
    }
}

#[cfg(test)]
mod tests {
    use super::LruCache;

    #[test]
    fn evicts_least_recently_used() {
        let mut c = LruCache::new(2);
        c.put("a", 1);
        c.put("b", 2);
        assert_eq!(c.get(&"a"), Some(&1));
        c.put("c", 3); // evicts "b"
        assert_eq!(c.get(&"b"), None);
        assert_eq!(c.get(&"a"), Some(&1));
        assert_eq!(c.get(&"c"), Some(&3));
    }
}
```
Using arena indices instead of `Rc<RefCell<...>>` avoids borrow-checker fights and reference cycles; `get` promotes the node to head so recency is updated on reads.

