/// Split one CSV record into fields per RFC 4180-style quoting.
/// "" inside a quoted field means a literal quote.
pub fn parse_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut field = String::new();
    let mut chars = line.chars().peekable();
    let mut in_quotes = false;

    while let Some(ch) = chars.next() {
        if in_quotes {
            if ch == '"' {
                if chars.peek() == Some(&'"') {
                    chars.next();
                    field.push('"');
                } else {
                    in_quotes = false;
                }
            } else {
                field.push(ch);
            }
        } else {
            match ch {
                '"' if field.is_empty() => in_quotes = true,
                ',' => { fields.push(std::mem::take(&mut field)); }
                _ => field.push(ch),
            }
        }
    }
    fields.push(field);
    fields
}

#[cfg(test)]
mod tests {
    use super::parse_csv_line;

    fn v(items: &[&str]) -> Vec<String> { items.iter().map(|s| s.to_string()).collect() }

    #[test]
    fn plain_and_quoted() {
        assert_eq!(parse_csv_line("a,b,c"), v(&["a", "b", "c"]));
        assert_eq!(parse_csv_line("\"a,b\",c"), v(&["a,b", "c"]));
        assert_eq!(parse_csv_line("\"he said \"\"hi\"\"\",x"), v(&["he said \"hi\"", "x"]));
        assert_eq!(parse_csv_line(""), v(&[""]));
        assert_eq!(parse_csv_line("a,"), v(&["a", ""]));
    }
}
```
Empty input yields one empty field, matching how most CSV readers treat a blank line; the doubled-quote branch unescapes inner quotes as RFC 4180 requires.

