#include <iostream>

struct Node {
    int value;
    Node* next;
    Node(int v) : value(v), next(nullptr) {}
};

Node* mergeSorted(Node* a, Node* b) {
    Node dummy(0);
    Node* tail = &dummy;
    while (a != nullptr && b != nullptr) {
        if (a->value <= b->value) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = (a != nullptr) ? a : b;
    return dummy.next;
}

static void print(Node* head) {
    for (Node* p = head; p; p = p->next)
        std::cout << p->value << (p->next ? " " : "\n");
}

int main() {
    Node* a = new Node(1);
    a->next = new Node(4);
    a->next->next = new Node(7);

    Node* b = new Node(2);
    b->next = new Node(3);
    b->next->next = new Node(8);

    print(mergeSorted(a, b));   // 1 2 3 4 7 8

    print(mergeSorted(nullptr, b));  // 2 3 8
    print(mergeSorted(nullptr, nullptr)); // empty line
    return 0;
}
```

The dummy head removes the first-node special case, and the loop stitches nodes in place so no allocation happens during the merge. Ties take from `a`, which keeps the merge stable. The final `tail->next` appends whatever list still has nodes, including the all-null case.

