```python
import functools
import random
import time


def retry(attempts: int = 3, base_delay: float = 0.5,
          max_delay: float = 10.0, jitter: float = 0.1):
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last_exc = None
            for attempt in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except Exception as exc:  # caller chooses what to retry
                    last_exc = exc
                    if attempt == attempts - 1:
                        break
                    delay = min(base_delay * (2 ** attempt), max_delay)
                    delay *= 1 + random.uniform(-jitter, jitter)
                    time.sleep(delay)
            raise last_exc
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base_delay=0.01)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise RuntimeError("not yet")
        return "ok"

    print(flaky(), "after", calls["n"], "calls")
```

Backoff doubles each attempt and is capped at `max_delay`; jitter multiplies the delay by a factor in `[1 - jitter, 1 + jitter]` to avoid synchronized retries. The final exception is re-raised so the caller still sees the real cause, and `functools.wraps` keeps the wrapped function's name and docstring.

