    let negative = x < 0;
    // Work in i64 so -i32::MIN does not overflow during negation.
    let mut n = (x as i64).abs();
    let mut out: i64 = 0;
    while n != 0 {
        out = out * 10 + n % 10;
        if out > i32::MAX as i64 {
            return None;
        }
        n /= 10;
    }
    if negative {
        out = -out;
    }
    if out < i32::MIN as i64 || out > i32::MAX as i64 {
        None
    } else {
        Some(out as i32)
    }
}

fn main() {
    assert_eq!(reverse_i32(123), Some(321));
    assert_eq!(reverse_i32(-456), Some(-654));
    assert_eq!(reverse_i32(0), Some(0));
    assert_eq!(reverse_i32(1_534_236_469), None); // overflows i32
    println!("ok");
}
