def reverse_words(s: str) -> str:
    # Split into tokens while keeping whitespace runs intact.
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        if s[i].isspace():
            while j < n and s[j].isspace():
                j += 1
        else:
            while j < n and not s[j].isspace():
                j += 1
        tokens.append(s[i:j])
        i = j

    words = [t for t in tokens if not t.isspace()]
    words.reverse()

    # Rebuild, substituting reversed words back into word slots.
    out = []
    wi = 0
    for t in tokens:
        if t.isspace():
            out.append(t)
        else:
            out.append(words[wi])
            wi += 1
    return "".join(out)


if __name__ == "__main__":
