// Returns (F(n), F(n+1)) using fast doubling.
static std::pair<uint64_t, uint64_t> fib_pair(unsigned n) {
    if (n == 0) return {0ULL, 1ULL};
    auto [a, b] = fib_pair(n >> 1);          // a = F(k), b = F(k+1)
    uint64_t c = a * ((b << 1) - a);         // F(2k)   = F(k)*(2F(k+1)-F(k))
    uint64_t d = a * a + b * b;              // F(2k+1) = F(k)^2 + F(k+1)^2
    if (n & 1u) return {d, c + d};
    return {c, d};
}

int main() {
    for (unsigned n = 0; n <= 93; ++n) {
        uint64_t f = fib_pair(n).first;
        std::printf("F(%u) = %llu\n", n, static_cast<unsigned long long>(f));
    }
    return 0;
}
