use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum ParseErr {
    Malformed(String),
    Duplicate(char),
    BadNumber(String),
}

pub fn parse_pairs(input: &str) -> Result<HashMap<char, i64>, ParseErr> {
    let mut map = HashMap::new();
    for raw in input.split(';') {
        let entry = raw.trim();
        if entry.is_empty() {
            continue;
        }
        let (k, v) = entry
            .split_once('=')
            .ok_or_else(|| ParseErr::Malformed(entry.to_string()))?;
        let key = k.trim();
        let val = v.trim();
        if key.chars().count() != 1 {
            return Err(ParseErr::Malformed(entry.to_string()));
        }
        let key = key.chars().next().unwrap();
        let num: i64 = val
            .parse()
            .map_err(|_| ParseErr::BadNumber(val.to_string()))?;
        if map.insert(key, num).is_some() {
            return Err(ParseErr::Duplicate(key));
        }
    }
    Ok(map)
}

fn main() {
    assert_eq!(parse_pairs("a=1; b=-2 ;c=3").unwrap().get(&'a'), Some(&1));
    assert_eq!(parse_pairs("a=1;a=2"), Err(ParseErr::Duplicate('a')));
    assert!(parse_pairs("ab=1").is_err());
    assert!(parse_pairs("x=nope").is_err());
    assert_eq!(parse_pairs("").unwrap().len(), 0);
    println!("ok");
}
