// Returns true on success. On success *out holds the value.
// Rejects: empty string, non-digit start, trailing garbage, overflow.
bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;

    const char *p = s;
    bool neg = false;
    if (*p == '+' || *p == '-') {
        neg = (*p == '-');
        p++;
    }
    if (*p < '0' || *p > '9') return false;

    errno = 0;
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (errno == ERANGE || v < INT_MIN || v > INT_MAX) return false;
    if (end == NULL || *end != '\0') return false;  // trailing garbage
    (void)neg;
    *out = (int)v;
    return true;
}

