/// Returns `Ok(index)` if found, else `Err(insertion_point)`,
/// where the insertion point keeps the slice sorted.
pub fn binary_search<T: Ord>(sorted: &[T], target: &T) -> Result<usize, usize> {
    let (mut lo, mut hi) = (0usize, sorted.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match sorted[mid].cmp(target) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Ok(mid),
        }
    }
    Err(lo)
}

fn main() {
    let v = [1, 3, 5, 7, 9];
    assert_eq!(binary_search(&v, &5), Ok(2));
    assert_eq!(binary_search(&v, &1), Ok(0));
    assert_eq!(binary_search(&v, &9), Ok(4));
    assert_eq!(binary_search(&v, &4), Err(2));
    assert_eq!(binary_search(&v, &0), Err(0));
    assert_eq!(binary_search(&v, &10), Err(5));

    let empty: [i32; 0] = [];
    assert_eq!(binary_search(&empty, &1), Err(0));
    println!("ok");
}
