std::int64_t fib(int n, std::unordered_map<int, std::int64_t> &memo) {
    if (n < 0) throw std::invalid_argument("n must be non-negative");
    if (n < 2) return n;
    auto it = memo.find(n);
    if (it != memo.end()) return it->second;
    std::int64_t value = fib(n - 1, memo) + fib(n - 2, memo);
    memo[n] = value;
    return value;
}

