std::optional<std::size_t> binary_search(const std::vector<int>& data, int target) {
    std::size_t lo = 0;
    std::size_t hi = data.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (data[mid] == target) return mid;
        if (data[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return std::nullopt;
}

