def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0
    def expand(lo: int, hi: int) -> int:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return hi - lo - 1
    for i in range(len(s)):
        odd = expand(i, i)
        even = expand(i, i + 1)
        best = max(odd, even)
        if best > end - start + 1:
            start = i - (best - 1) // 2
            end = i + best // 2
    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["", "a", "babad", "cbbd", "forgeeksskeegfor", "😀ab😀"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
