```cpp
#include <iostream>
#include <vector>

int binarySearch(const std::vector<int>& data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (data[mid] == target) return mid;
        if (data[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> data = {1, 3, 5, 7, 9, 11};
    std::cout << binarySearch(data, 7) << "\n";   // 3
    std::cout << binarySearch(data, 4) << "\n";   // -1
    std::cout << binarySearch({}, 1) << "\n";     // -1
    std::cout << binarySearch(data, 1) << "\n";   // 0
    return 0;
}
```

`mid` is computed as `lo + (hi - lo) / 2` to avoid overflow. The loop invariant is that the target, if present, lies inside `[lo, hi]`, so the empty vector case falls out naturally.

