#include <algorithm>
#include <iostream>
#include <map>
#include <string>
#include <utility>
#include <vector>

int main(int argc, char** argv) {
    int top_n = (argc > 1) ? std::stoi(argv[1]) : 5;
    if (top_n < 0) top_n = 0;

    std::map<std::string, int> counts;
    std::string word;
    while (std::cin >> word) {
        // Strip common surrounding punctuation.
        while (!word.empty() && !std::isalnum(static_cast<unsigned char>(word.front())))
            word.erase(word.begin());
        while (!word.empty() && !std::isalnum(static_cast<unsigned char>(word.back())))
            word.pop_back();
        if (word.empty()) continue;
        for (char& c : word) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        ++counts[word];
    }

    std::vector<std::pair<int, std::string>> ranked;
    ranked.reserve(counts.size());
    for (const auto& kv : counts) ranked.emplace_back(kv.second, kv.first);

    // Sort by count desc, then alphabetically for a stable order.
    std::sort(ranked.begin(), ranked.end(), [](const auto& x, const auto& y) {
        if (x.first != y.first) return x.first > y.first;
        return x.second < y.second;
    });

    int shown = std::min<int>(top_n, ranked.size());
    for (int i = 0; i < shown; ++i)
        std::cout << ranked[i].second << ' ' << ranked[i].first << '\n';
    return 0;
}
```

Reading a whitespace-delimited token, trimming non-alphanumerics from both ends, and lowercasing makes `"The"`, `"the,"`, and `"the"` collapse to one bucket. Sorting by count then name avoids random tie order.

