```rust
fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let expected = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(expected) {
                    return false;
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    assert!(is_balanced("()[]{}"));
    assert!(is_balanced("a(b[c]{d})e"));
    assert!(!is_balanced("([)]"));
    assert!(!is_balanced("("));
    assert!(!is_balanced(")"));
    assert!(is_balanced(""));
    println!("all checks pass");
}
```

The stack remembers which opener is currently open. On every closer, popping must yield the matching opener; `([)]` fails because `]` expects `[` but the top of the stack is `(`. A non-empty stack at the end means an unclosed opener.

