// Parses an optional sign followed by digits. Returns std::nullopt on
// empty input, non-digit characters, or overflow of std::int64_t.
std::optional<std::int64_t> parse_int(std::string_view s) {
    if (s.empty()) return std::nullopt;
    bool neg = false;
    std::size_t i = 0;
    if (s[0] == '+' || s[0] == '-') {
        neg = (s[0] == '-');
        i = 1;
    }
    if (i == s.size()) return std::nullopt;

    std::int64_t acc = 0;
    const std::int64_t limit = neg ? std::numeric_limits<std::int64_t>::min()
                                   : std::numeric_limits<std::int64_t>::max();
    for (; i < s.size(); ++i) {
        char c = s[i];
        if (c < '0' || c > '9') return std::nullopt;
        int d = c - '0';
        if (neg) {
            if (acc < (limit + d) / 10) return std::nullopt;
            acc = acc * 10 - d;
        } else {
            if (acc > (limit - d) / 10) return std::nullopt;
            acc = acc * 10 + d;
        }
    }
    return acc;
}
```

The overflow check is done before multiplying, using the sign-specific limit, so `INT64_MIN` is representable while one past it is rejected. Empty strings, a lone sign, and stray characters all return `std::nullopt`.

```rust
/// Yields string slices of a string, each at most `max` bytes, never
/// splitting a UTF-8 character. Returns an empty vector for empty input
/// or `max == 0`.
fn chunk_str(s: &str, max: usize) -> Vec<&str> {
    if s.is_empty() || max == 0 {
        return Vec::new();
    }
    let mut out = Vec::new();
    let mut start = 0;
    while start < s.len() {
        let mut end = (start + max).min(s.len());
        while !s.is_char_boundary(end) {
            end -= 1;
        }
        out.push(&s[start..end]);
        start = end;
    }
    out
}

fn main() {
    assert!(chunk_str("", 4).is_empty());
    assert!(chunk_str("abc", 0).is_empty());
    assert_eq!(chunk_str("abcdef", 4), vec!["abcd", "ef"]);
    // "é" is two bytes, so a 3-byte window must not split it mid-character.
    let parts = chunk_str("ééé", 3);
    assert_eq!(parts.concat(), "ééé");
    for p in &parts {
        assert!(p.len() <= 3);
    }
    println!("ok");
}
```

`is_char_boundary` walks the boundary back until it lands on a valid edge, so a 3-byte window over two-byte characters yields two-byte pieces instead of panicking. The concatenation of all chunks reconstructs the original string exactly.

```rust
/// Euclidean GCD. Accepts negatives and returns a non-negative result.
/// gcd(0, 0) is defined as 0.
fn gcd(mut a: i64, mut b: i64) -> i64 {
    // i64::MIN has no positive counterpart, so reduce it first.
    a = a.wrapping_abs();
    b = b.wrapping_abs();
    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }
    a
}

fn main() {
    assert_eq!(gcd(0, 0), 0);
    assert_eq!(gcd(12, 18), 6);
    assert_eq!(gcd(-12, 18), 6);
    assert_eq!(gcd(-12, -18), 6);
    assert_eq!(gcd(7, 13), 1);
    assert_eq!(gcd(0, 5), 5);
    assert_eq!(gcd(i64::MIN, 2), 2);
    println!("ok");
}
```

`wrapping_abs` avoids the panic that plain `abs` triggers on `i64::MIN`; the result stays correct because the remainder arithmetic never overflows for the values reached here. `gcd(0, 0)` returns 0 by convention.

