def two_largest(nums):
    """Return the two largest distinct values, largest first."""
    first = second = None
    for n in nums:
        if first is None or n > first:
            if n != first:
                second = first
            first = n
        elif n != first and (second is None or n > second):
            second = n
    if second is None:
        return "need at least two distinct values"
    return (first, second)


