```cpp
#include <array>
#include <cstddef>
#include <cstdio>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    if (!rb.empty() || rb.full()) return 1;
    if (!rb.push(10) || !rb.push(20) || !rb.push(30)) return 2;
    if (!rb.full() || rb.push(40)) return 3;          // fourth push rejected
    if (rb.pop() != 10) return 4;
    if (!rb.push(40)) return 5;                        // now a slot is free
    int expected[] = {20, 30, 40};
    for (int e : expected) {
        auto v = rb.pop();
        if (!v || *v != e) return 6;
    }
    if (!rb.empty() || rb.pop().has_value()) return 7;
    std::puts("ok");
    return 0;
}
```

Wraparound is handled with modular indices; `size_` distinguishes the full case from the empty case, which head==tail alone cannot. `std::optional` keeps pop failure explicit and the buffer stays on the stack.

```cpp
#include <cstdio>
#include <vector>

// Returns the index of value, or -1 if absent. Requires nums sorted ascending.
int binary_search_index(const std::vector<int>& nums, int value) {
    std::size_t lo = 0;
    std::size_t hi = nums.size();  // exclusive upper bound
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;  // avoids overflow
        if (nums[mid] == value) return static_cast<int>(mid);
        if (nums[mid] < value) lo = mid + 1;
        else hi = mid;
    }
    return -1;
}

int main() {
    const std::vector<int> empty;
    const std::vector<int> one{42};
    const std::vector<int> many{-7, -2, 0, 3, 3, 5, 11, 40};

    if (binary_search_index(empty, 5) != -1) return 1;
    if (binary_search_index(one, 42) != 0) return 2;
    if (binary_search_index(one, 41) != -1) return 3;
    if (binary_search_index(many, -7) != 0) return 4;      // first element
    if (binary_search_index(many, 40) != 7) return 5;      // last element
    if (binary_search_index(many, 3) != 3) return 6;       // duplicate, any hit ok
    if (binary_search_index(many, 4) != -1) return 7;      // absent between
    if (binary_search_index(many, -100) != -1) return 8;   // below range
    if (binary_search_index(many, 999) != -1) return 9;    // above range
    std::puts("ok");
    return 0;
}
```

Using an exclusive `hi` and computing `mid` as `lo + (hi - lo) / 2` avoids both the classic off-by-one and signed overflow. Empty, single-element, duplicate, and out-of-range values are all asserted.

```rust
use std::fmt::Debug;

/// Longest run of equal elements. Returns None for an empty slice.
fn longest_run<T: PartialEq + Copy>(items: &[T]) -> Option<(T, usize)> {
    let mut iter = items.iter().copied();
    let mut current = iter.next()?;
    let mut best = (current, 1usize);
    let mut run = 1usize;

    for item in iter {
        if item == current {
            run += 1;
        } else {
            if run > best.1 {
                best = (current, run);
            }
            current = item;
            run = 1;
        }
    }
    if run > best.1 {
        best = (current, run);
    }
    Some(best)
}

fn main() {
    assert_eq!(longest_run::<i32>(&[]), None);
    assert_eq!(longest_run(&[5]), Some((5, 1)));
    assert_eq!(longest_run(&[1, 1, 2, 2, 2, 3]), Some((2, 3)));
    assert_eq!(longest_run(&[4, 4, 4, 4]), Some((4, 4)));
    assert_eq!(longest_run(&[1, 2, 3]), Some((1, 1))); // tie keeps the first
    assert_eq!(longest_run(&['a', 'b', 'b', 'a']), Some(('b', 2)));

    let result: Option<(i32, usize)> = longest_run(&[9, 9, 1]);
    println!("{:?}", result);
    assert_eq!(result, Some((9, 2)));
    println!("ok");
}
```

Empty slices return `None`; ties keep the earliest run because the update only fires on a strict `>`. The generic bound `PartialEq + Copy` keeps it usable for ints, chars, and similar scalar types.

