def check_brackets(s):
    """Return (True, None) if balanced, else (False, index)."""
    pairs = {")": "(", "]": "[", "}": "{"}
    closers = set(pairs)
    stack = []
    for i, ch in enumerate(s):
        if ch in "([{":
            stack.append((ch, i))
        elif ch in closers:
            if not stack:
                return False, i
            opener, _ = stack.pop()
            if pairs[ch] != opener:
                return False, i
    if stack:
        _, i = stack[-1]
        return False, i
    return True, None


if __name__ == "__main__":
    assert check_brackets("{[()]}") == (True, None)
    assert check_brackets("") == (True, None)
    assert check_brackets("([)]") == (False, 2)   # ] closes [ not (
    assert check_brackets("(((") == (False, 0)    # innermost unclosed
    assert check_brackets(")first") == (False, 0)
    assert check_brackets("a(b[c]d)e") == (True, None)
    assert check_brackets("text with unicode \u00e9 \u4e2d brackets ()") == (True, None)
    print("ok")
```

Returns the index of the offending close when a closer mismatches or appears with an empty stack, and the index of the innermost unclosed opener when the stack remains non-empty. Non-bracket characters are ignored.

```python
import re


def encode(text):
    """RLE: 'aaabb' -> 'a3b2'."""
    if not text:
        return ""
    out = []
    prev = text[0]
    count = 1
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(prev + str(count))
            prev, count = ch, 1
    out.append(prev + str(count))
    return "".join(out)


_TOKEN = re.compile(r"(.)(\d+)", re.DOTALL)


def decode(encoded):
    """Strict inverse of encode; rejects malformed tokens or zero counts."""
    pos = 0
    out = []
    for m in _TOKEN.finditer(encoded):
        if m.start() != pos:
            raise ValueError(f"malformed input at index {pos}")
        ch, digits = m.group(1), m.group(2)
        count = int(digits)
        if count == 0:
            raise ValueError("run count must be positive")
        out.append(ch * count)
        pos = m.end()
    if pos != len(encoded) or not encoded:
        raise ValueError("malformed or empty input")
    return "".join(out)


if __name__ == "__main__":
    for original in ("", "a", "aaabb", "abcd", "zzzzzzzzzz", "\u00e9\u00e9\u00e9x"):
        assert decode(encode(original)) == original
    try:
        decode("a0")
    except ValueError:
        pass
    else:
        raise AssertionError("a0 should be rejected")
    for bad in ("a", "3a", "a3b"):
        try:
            decode(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"should reject {bad!r}")
    print("ok")
```

`DOTALL` lets a character class match any code point, so multi-byte characters encode correctly. The decoder walks token boundaries with an index so stray characters or a trailing fragment raise instead of being silently dropped.

