def top_words(path, n=5):
    counts = Counter()
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            for word in WORD_RE.findall(line.lower()):
                if word not in STOPWORDS:
                    counts[word] += 1
    return counts.most_common(n)


