```cpp
#include <cctype>
#include <iostream>
#include <string>
#include <string_view>

bool isPalindrome(std::string_view s) {
    std::size_t i = 0;
    std::size_t j = s.size();
    while (i < j) {
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[i]))) ++i;
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[j - 1]))) --j;
        if (i >= j) break;
        unsigned char a = static_cast<unsigned char>(std::tolower(static_cast<unsigned char>(s[i])));
        unsigned char b = static_cast<unsigned char>(std::tolower(static_cast<unsigned char>(s[j - 1])));
        if (a != b) return false;
        ++i;
        --j;
    }
    return true;
}

int main() {
    const char* tests[] = {
        "A man, a plan, a canal: Panama",
        "race a car",
        "",
        ".,",
        "No 'x' in Nixon",
    };
    bool expected[] = {true, false, true, true, true};
    for (std::size_t k = 0; k < std::size(s); ++k) {
        bool got = isPalindrome(tests[k]);
        std::cout << (got == expected[k] ? "PASS " : "FAIL ") << tests[k] << '\n';
    }
}
```

The two inner loops skip non-alphanumerics, and the `if (i >= j) break;` guard handles strings like `".,"` that reduce to nothing. Everything is cast through `unsigned char` before `isalnum`/`tolower` to avoid undefined behaviour on negative `char` values.

