#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    void push(int value) {
        buf_[head_] = value;
        head_ = (head_ + 1) % N;
        if (count_ < N) {
            ++count_;
        } else {
            tail_ = (tail_ + 1) % N;  // overwrote the oldest: advance tail
        }
    }

    std::optional<int> pop() {
        if (count_ == 0) return std::nullopt;
        int value = buf_[tail_];
        tail_ = (tail_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    static constexpr std::size_t capacity() { return N; }

private:
    std::array<int, N> buf_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4);  // drops 1
    std::cout << rb.size() << '\n';            // 3
    std::cout << *rb.pop() << '\n';            // 2
    std::cout << *rb.pop() << '\n';            // 3
    std::cout << (rb.pop().has_value() ? 1 : 0) << '\n';  // 1
    std::cout << (rb.pop().has_value() ? 1 : 0) << '\n';  // 0, empty
}
```

`head_` points at the next write slot and `tail_` at the oldest element. The overflow branch advances `tail_` because the write clobbered that slot, so `size()` stays at capacity and `pop()` returns elements in FIFO order.

