```rust
fn running_averages(values: &[f64]) -> Option<Vec<f64>> {
    if values.is_empty() {
        return None;
    }
    let mut means = Vec::with_capacity(values.len());
    let mut sum = 0.0_f64;
    for (i, &v) in values.iter().enumerate() {
        // Compensated (Kahan) addition keeps the mean stable over long inputs.
        let y = v - compensation;
        let t = sum + y;
        compensation = (t - sum) - y;
        sum = t;
        means.push(sum / (i + 1) as f64);
    }
    Some(means)
}

fn main() {
    assert_eq!(running_averages(&[]), None);
    let avgs = running_averages(&[1.0, 2.0, 3.0, 4.0]).unwrap();
    assert_eq!(avgs, vec![1.0, 1.5, 2.0, 2.5]);
    let big = running_averages(&[1e16, 1.0, -1e16]).unwrap();
    assert!((big[2] - 1.0 / 3.0).abs() < 1e-9);
    println!("ok");
}
```

The Kahan compensation term `(t - sum) - y` recovers the low-order bits lost when `sum` is large, so the third mean stays near `1/3` instead of collapsing to `0` from `1e16` swamping `1.0`.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key, default=None):
        if key not in self._data:
            return default
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __contains__(self, key):
        return key in self._data

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1); c.put("b", 2)
    assert c.get("a") == 1
    c.put("c", 3)                 # evicts "b" (least recently used)
    assert c.get("b") is None
    assert c.get("c") == 3
    assert list(c._data) == ["a", "c"]
    print("ok")
```

`move_to_end` on every hit is what makes an access count as a use. On `put`, a brand-new key is inserted at the end (most recent) and, once over capacity, `popitem(last=False)` drops the front, which is the least recently used entry.

