#include <array>
#include <optional>
#include <cstddef>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<int> pop() {
        if (count_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};
```

`push` refuses when full and returns false rather than overwriting; `pop` returns `std::nullopt` on an empty buffer. The index `(head_ + count_) % N` keeps reads and writes wrapping without ever leaving bounds.

