std::string to_roman(int n) {
    if (n < 1 || n > 3999) throw std::invalid_argument("out of range");
    static const std::vector<std::pair<int, std::string>> table = {
        {1000, "M"}, {900, "CM"}, {500, "D"}, {400, "CD"},
        {100, "C"},  {90, "XC"},  {50, "L"},  {40, "XL"},
        {10, "X"},   {9, "IX"},   {5, "V"},   {4, "IV"}, {1, "I"},
    };
    std::string out;
    for (const auto& [value, sym] : table) {
        while (n >= value) {
            out += sym;
            n -= value;
        }
    }
    return out;
}

