#include <iostream>
#include <vector>

std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5, 7};
    std::vector<int> b{2, 4, 6, 8, 10};
    std::vector<int> m = merge_sorted(a, b);
    for (std::size_t k = 0; k < m.size(); ++k) {
        std::cout << m[k];
        if (k + 1 < m.size()) std::cout << ' ';
    }
    std::cout << '\n';

    // Empty-input edge cases
    std::cout << merge_sorted({}, {}).size() << '\n';          // 0
    std::cout << merge_sorted({1, 2}, {}).size() << '\n';      // 2
    std::cout << merge_sorted({}, {9}).front() << '\n';        // 9
    return 0;
}
```

`reserve` avoids reallocations. The two tail loops drain whichever array still has elements. `<=` keeps the merge stable for equal keys. Empty arrays hit neither loop and produce an empty result correctly.

