import string


def validate_password(pw: str) -> list[str]:
    failures = []
    if len(pw) < 8:
        failures.append("too short: need at least 8 characters")
    if not any(c.isupper() for c in pw):
        failures.append("missing an uppercase letter")
    if not any(c.islower() for c in pw):
        failures.append("missing a lowercase letter")
    if not any(c.isdigit() for c in pw):
        failures.append("missing a digit")
    symbols = set(string.punctuation)
    if not any(c in symbols for c in pw):
        failures.append("missing a symbol")
    return failures


