```python
class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.data: dict = {}

    def get(self, key):
        if key not in self.data:
            return None
        value = self.data.pop(key)
        self.data[key] = value  # reinsert marks it most-recently used
        return value

    def put(self, key, value) -> None:
        if key in self.data:
            self.data.pop(key)
        self.data[key] = value
        if len(self.data) > self.capacity:
            oldest = next(iter(self.data))
            del self.data[oldest]

    def __len__(self) -> int:
        return len(self.data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    c.get("a")          # "a" is now most recent
    c.put("c", 3)       # evicts "b"
    assert c.get("b") is None
    assert c.get("a") == 1
    assert c.get("c") == 3
    print("ok", len(c))
```

Python 3.7+ dicts preserve insertion order, so the first key returned by `iter` is the least recently used. On `get` a hit, popping and reinserting moves the key to the back; on `put`, an existing key is popped first to refresh its position. That makes every operation O(1). Capacity `<= 0` is rejected up front so the eviction branch never misbehaves.

```c
#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int main(void) {
    char line[256];
    long long sum = 0;
    int count = 0;

    while (fgets(line, sizeof line, stdin) != NULL) {
        const char *p = line;
        while (isspace((unsigned char)*p)) p++;
        if (*p == '#' || *p == '\n' || *p == '\0') continue;

        char *end = NULL;
        long v = strtol(p, &end, 10);
        if (end == p) {                     // no digits at start of token
            fprintf(stderr, "skipping malformed line: %s", line);
            continue;
        }
        sum += v;
        count++;
    }

    printf("sum=%lld over %d value(s)\n", sum, count);
    return 0;
}
```

Each line is read whole with `fgets`, so a `#` comment or blank line is skipped before parsing. `strtol` sets `end` to where parsing stopped; if `end == p`, no number was found and the line is reported to stderr and skipped rather than counted as zero. `sum` is `long long` so large inputs do not overflow a 32-bit accumulator. The buffer bounds (256) cap line length; longer lines are read in chunks, which is acceptable for whitespace-separated tokens.

