#include <cassert>
#include <cstddef>
#include <iostream>
#include <vector>

using Matrix = std::vector<std::vector<int>>;

// Rotate an n x n matrix 90 degrees clockwise, in place.
// Transpose, then reverse each row: O(n^2) time, O(1) extra space.
void rotate90(Matrix& m) {
    const std::size_t n = m.size();
    if (n == 0 || m[0].size() != n) return;  // only square matrices
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = i + 1; j < n; ++j) {
            std::swap(m[i][j], m[j][i]);
        }
    }
    for (auto& row : m) {
        for (std::size_t j = 0; j < n / 2; ++j) {
            std::swap(row[j], row[n - 1 - j]);
        }
    }
}

int main() {
    Matrix m = {{1, 2, 3},
                {4, 5, 6},
                {7, 8, 9}};
    rotate90(m);
    Matrix expected = {{7, 4, 1},
                       {8, 5, 2},
                       {9, 6, 3}};
    assert(m == expected);

    Matrix empty;
    rotate90(empty);               // must not crash on 0x0
    assert(empty.empty());

    Matrix one = {{42}};
    rotate90(one);
    assert(one[0][0] == 42);

    std::cout << "rotation verified\n";
    return 0;
}
