#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_WORDS 4096
#define MAX_LEN 64

struct entry {
    char word[MAX_LEN];
    unsigned long count;
};

static int compare(const void *a, const void *b) {
    const struct entry *x = a;
    const struct entry *y = b;
    if (x->count != y->count) return (x->count < y->count) ? 1 : -1;
    return strcmp(x->word, y->word);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 1;
    }
    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    struct entry *table = calloc(MAX_WORDS, sizeof(*table));
    if (!table) {
        fprintf(stderr, "out of memory\n");
        fclose(fp);
        return 1;
    }
    size_t used = 0;
    char buf[MAX_LEN];
    int ch;
    size_t len = 0;

    while ((ch = fgetc(fp)) != EOF) {
        if (isalnum((unsigned char)ch) && len < MAX_LEN - 1) {
            buf[len++] = (char)tolower((unsigned char)ch);
        } else if (len > 0) {
            buf[len] = '\0';
            size_t i;
            for (i = 0; i < used; ++i) {
                if (strcmp(table[i].word, buf) == 0) {
                    table[i].count++;
                    break;
                }
            }
            if (i == used && used < MAX_WORDS) {
                strcpy(table[used].word, buf);
                table[used].count = 1;
                used++;
            }
            len = 0;
        }
    }
    if (len > 0 && used < MAX_WORDS) {
        buf[len] = '\0';
        strcpy(table[used].word, buf);
        table[used].count = 1;
        used++;
    }
    fclose(fp);

    qsort(table, used, sizeof(*table), compare);
    size_t top = used < 3 ? used : 3;
    for (size_t i = 0; i < top; ++i) {
        printf("%s %lu\n", table[i].word, table[i].count);
    }
    free(table);
    return 0;
}
