use std::collections::HashMap;
use std::fmt;

#[derive(Debug, PartialEq)]
enum ConfigError {
    EmptyKey(String),
    MissingValue(String),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::EmptyKey(part) => write!(f, "empty key in {part:?}"),
            ConfigError::MissingValue(part) => write!(f, "missing '=' in {part:?}"),
        }
    }
}

fn parse_config(input: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut map = HashMap::new();
    for raw in input.split(';') {
        let part = raw.trim();
        if part.is_empty() {
            continue;
        }
        let (key, value) = part.split_once('=').ok_or_else(|| ConfigError::MissingValue(part.to_string()))?;
        let key = key.trim();
        if key.is_empty() {
            return Err(ConfigError::EmptyKey(part.to_string()));
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let good = "host=localhost; port=8080 ; name = xt-luna";
    let map = parse_config(good).expect("valid config");
    assert_eq!(map.get("host").map(String::as_str), Some("localhost"));
    assert_eq!(map.get("port").map(String::as_str), Some("8080"));
    assert_eq!(map.get("name").map(String::as_str), Some("xt-luna"));

    assert_eq!(parse_config("a=1;broken"), Err(ConfigError::MissingValue("broken".into())));
    assert_eq!(parse_config("=value"), Err(ConfigError::EmptyKey("=value".into())));
    assert_eq!(parse_config(";;").unwrap().len(), 0);

    println!("parsed {} keys", map.len());
}
