    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 2, 3]), vec![1, 1, 1, 2, 2, 3]);
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[-3, 0], &[-1]), vec![-3, -1, 0]);

