#include <iostream>
#include <optional>
#include <string>
#include <unordered_map>
#include <vector>

struct Mismatch {
    std::size_t index;
    char found;
};

std::optional<Mismatch> first_mismatch(const std::string& s) {
    static const std::unordered_map<char, char> closer{{
        {')', '('}, {']', '['}, {'}', '{'} }};
    std::vector<char> stack;
    for (std::size_t i = 0; i < s.size(); ++i) {
        const char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stack.push_back(c);
        } else if (closer.count(c)) {
            if (stack.empty() || stack.back() != closer.at(c)) {
                return Mismatch{i, c};
            }
            stack.pop_back();
        }
        // Any other character is ignored.
    }
    if (stack.empty()) return std::nullopt;
    return Mismatch{s.size(), stack.back()};  // unclosed opener, reported at end
}

int main() {
    const std::vector<std::string> ok = {"", "()", "{[()]}", "a(b)c[d]", "((()))"};
    for (const auto& s : ok) {
        const auto bad = first_mismatch(s);
        if (bad) {
            std::cerr << "expected balanced: " << s << "\n";
            return 1;
        }
    }
    const auto bad = first_mismatch("([)]");
    if (!bad || bad->index != 2 || bad->found != ')') {
        std::cerr << "mismatch not detected correctly\n";
        return 1;
    }
    std::cout << "brackets verified\n";
    return 0;
}
