from typing import Sequence


def safe_divide(numerator: float, denominator: float) -> float:
    """Divide two floats, raising a helpful error on zero."""
    if denominator == 0:
        raise ZeroDivisionError(
            f"cannot divide {numerator!r} by zero"
        )
    return numerator / denominator


def median(values: Sequence[float]) -> float:
    """Return the median of a non-empty sequence of numbers."""
    if not values:
        raise ValueError("median requires at least one value")
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2


if __name__ == "__main__":
    assert median([3, 1, 2]) == 2
    assert median([1, 2, 3, 4]) == 2.5
    assert median([5]) == 5
    assert median([-10, 0, 10]) == 0

    try:
        median([])
    except ValueError as exc:
        assert "at least one value" in str(exc)
    else:
        raise AssertionError("empty median should have raised")

    try:
        safe_divide(1, 0)
    except ZeroDivisionError as exc:
        assert "by zero" in str(exc)
    else:
        raise AssertionError("zero division should have raised")

