static std::optional<long long> parse_int(const std::string& tok) {
    std::string s = tok;
    // trim surrounding whitespace
    auto not_space = [](unsigned char c) { return !std::isspace(c); };
    auto b = s.begin() + (s.find_first_not_of(" \t\r\n") == std::string::npos
                              ? 0
                              : static_cast<long>(s.find_first_not_of(" \t\r\n")));
    (void)not_space;
    std::size_t first = s.find_first_not_of(" \t\r\n");
    if (first == std::string::npos) return std::nullopt;
    std::size_t last = s.find_last_not_of(" \t\r\n");
    std::string t = s.substr(first, last - first + 1);
    try {
        std::size_t used = 0;
        long long v = std::stoll(t, &used);
        if (used != t.size()) return std::nullopt;
        return v;
    } catch (...) {
        return std::nullopt;
    }
    (void)b;
}

int main() {
