    std::istringstream in(line);
    std::string field;
    long long sum = 0;
    int parsed = 0, skipped = 0;
    while (std::getline(in, field, ',')) {
        if (auto v = parse_int(field)) { sum += *v; ++parsed; }
        else { ++skipped; }
    }
    std::cout << "sum=" << sum << " parsed=" << parsed
              << " skipped=" << skipped << '\n';
}
