#include <iostream>
#include <optional>
#include <vector>

// Returns the index of the first element for which comp(elem) is false,
// i.e. a lower_bound, without needing a separate value type.
template <class T, class Pred>
std::size_t lower_bound_by(const std::vector<T>& v, Pred comp) {
    std::size_t lo = 0, hi = v.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;  // no overflow
        if (comp(v[mid])) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

template <class T>
std::optional<std::size_t> find_sorted(const std::vector<T>& v, const T& target) {
    std::size_t i = lower_bound_by(v, [&](const T& x) { return x < target; });
    if (i < v.size() && !(target < v[i])) return i;
    return std::nullopt;
}

int main() {
    std::vector<int> v{1, 3, 3, 5, 8};
    std::cout << find_sorted(v, 3).value_or(999) << '\n';  // 1 (first match)
    std::cout << find_sorted(v, 4).has_value() << '\n';    // 0
    std::vector<int> empty;
    std::cout << find_sorted(empty, 1).has_value() << '\n'; // 0
}
