#include <stdio.h>
#include <string.h>

/* Reverse complete UTF-8 code points in place. */
static void utf8_reverse(char *s) {
    size_t n = strlen(s);
    size_t i = 0, j = n;
    unsigned char buf[4];

    while (i < j) {
        /* Walk back to the start of the trailing code point. */
        size_t end = j;
        j--;
        while (j > i && ((unsigned char)s[j] & 0xC0) == 0x80) j--;
        size_t len = end - j;
        memcpy(buf, s + j, len);

        /* Shift the leading code point right, then write the copy. */
        memmove(s + i + len, s + i, j - i);
        memcpy(s + i, buf, len);
        i += len;
    }
}

int main(void) {
    char s[] = "hello \xE4\xB8\x96\xE7\x95\x8C"; /* "hello \u4e16\u754c" */
    utf8_reverse(s);
    printf("%s\n", s);
    return 0;
}
