```cpp
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;                                  // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap
    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);
        if (low.size() > high.size() + 1) { high.push(low.top()); low.pop(); }
        else if (high.size() > low.size()) { low.push(high.top()); high.pop(); }
        double med = low.size() == high.size()
            ? (low.top() + high.top()) / 2.0
            : (double)low.top();
        std::cout << med << "\n";
    }
    return 0;
}
```

Each incoming value is routed to the correct heap so the sizes never differ by more than one. The median is the larger heap's top for odd counts, or the average of both tops for even counts. `std::cin >> x` stops cleanly at EOF or invalid input.

