```c
#include <stdio.h>
#include <stdint.h>

int popcount_swar(uint32_t x) {
    x = x - ((x >> 1) & 0x55555555u);
    x = (x & 0x33333333u) + ((x >> 2) & 0x33333333u);
    x = (x + (x >> 4)) & 0x0F0F0F0Fu;
    return (int)((x * 0x01010101u) >> 24);
}

int main(void) {
    printf("%d\n", popcount_swar(0u));           // 0
    printf("%d\n", popcount_swar(1u));           // 1
    printf("%d\n", popcount_swar(0xFFFFFFFFu));  // 32
    printf("%d\n", popcount_swar(0xA5A5A5A5u));  // 16
    return 0;
}
```

The four steps count pairs, then nibbles, then bytes, then multiply-and-shift sums the bytes. No loop is needed and each constant is a 32-bit mask; the final shift by 24 keeps only the byte holding the total.

