#include <iostream>
#include <stack>
#include <string>

bool is_balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top(); st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) return false;
        }
    }
    return st.empty();
}

int main() {
    std::cout << is_balanced("({[]})") << "\n";  // 1
    std::cout << is_balanced("([)]") << "\n";    // 0
    std::cout << is_balanced("") << "\n";        // 1
    std::cout << is_balanced("(((") << "\n";     // 0
    return 0;
}
```

A closing bracket must match the most recent unmatched opener, so the stack top is the only valid candidate; mismatches return false immediately. The final `st.empty()` makes unmatched openers fail.

