# Longest palindromic substring via expand-around-center.
# Time O(n^2), space O(1). Handles empty/None and unicode safely.

def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    start, end = 0, 0  # current best [start, end)

    def expand(left: int, right: int) -> tuple[int, int]:
        # Expand while characters match; indices stay within bounds.
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        # Loop overshoots by one on each side.
        return left + 1, right

    for i in range(len(s)):
        # Odd-length palindrome centered at i.
        l1, r1 = expand(i, i)
        # Even-length palindrome centered between i and i+1.
        l2, r2 = expand(i, i + 1)
        for l, r in ((l1, r1), (l2, r2)):
            if r - l > end - start:
                start, end = l, r

    return s[start:end]


if __name__ == "__main__":
    cases = ["", "a", "bb", "babad", "cbbd", "日本語", "ab⚡ba", "aaaa"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
