// Running median with a max-heap (low half) and min-heap (high half).
// Each insertion is O(log n); each median query is O(1).
#include <cstdint>
#include <iostream>
#include <queue>
#include <vector>

class MedianTracker {
public:
    void add(int64_t value) {
        if (low_.empty() || value <= low_.top()) {
            low_.push(value);
        } else {
            high_.push(value);
        }
        // Rebalance so |low_.size() - high_.size()| <= 1 and low_ >= high_.
        if (low_.size() > high_.size() + 1) {
            high_.push(low_.top());
            low_.pop();
        } else if (high_.size() > low_.size()) {
            low_.push(high_.top());
            high_.pop();
        }
    }

    // Caller must have added at least one value.
    double median() const {
        if (low_.size() == high_.size()) {
            return (static_cast<double>(low_.top()) + high_.top()) / 2.0;
        }
        return static_cast<double>(low_.top());
    }

private:
    std::priority_queue<int64_t> low_;                                  // max-heap
    std::priority_queue<int64_t, std::vector<int64_t>, std::greater<>> high_;  // min-heap
};

int main() {
    MedianTracker tracker;
    int64_t value;
    bool any = false;
    while (std::cin >> value) {
        tracker.add(value);
        any = true;
        std::cout << tracker.median() << '\n';
    }
    if (!any) {
        std::cerr << "no input provided\n";
        return 1;
    }
    return 0;
}
