```rust
// Minimal config parser: `key = value` lines, `#` comments, optional quotes.
use std::collections::HashMap;

#[derive(Debug)]
pub struct ConfigError {
    pub line: usize,
    pub message: String,
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "line {}: {}", self.line, self.message)
    }
}

pub fn parse(input: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut map = HashMap::new();
    for (idx, raw) in input.lines().enumerate() {
        let line_no = idx + 1;
        // Strip comments only when `#` is not inside quotes.
        let line = strip_comment(raw);
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let (key, value) = match line.split_once('=') {
            Some((k, v)) => (k.trim(), v.trim()),
            None => {
                return Err(ConfigError {
                    line: line_no,
                    message: format!("missing '=' in `{line}`"),
                });
            }
        };
        if key.is_empty() {
            return Err(ConfigError {
                line: line_no,
                message: "empty key".to_string(),
            });
        }
        map.insert(key.to_string(), unquote(value, line_no)?);
    }
    Ok(map)
}

fn strip_comment(line: &str) -> String {
    let mut in_quote = false;
    for (i, ch) in line.char_indices() {
        match ch {
            '"' => in_quote = !in_quote,
            '#' if !in_quote => return line[..i].to_string(),
            _ => {}
        }
    }
    line.to_string()
}

fn unquote(value: &str, line: usize) -> Result<String, ConfigError> {
    if value.starts_with('"') || value.ends_with('"') {
        if value.len() < 2 || !value.starts_with('"') || !value.ends_with('"') {
            return Err(ConfigError {
                line,
                message: format!("unbalanced quotes in `{value}`"),
            });
        }
        return Ok(value[1..value.len() - 1].to_string());
    }
    Ok(value.to_string())
}

fn main() {
    let sample = "# app config\nname = \"Luna\"\nport = 8080  # default\n";
    match parse(sample) {
        Ok(cfg) => {
            let mut keys: Vec<_> = cfg.iter().collect();
            keys.sort();
            for (k, v) in keys {
                println!("{k} -> {v}");
            }
        }
        Err(e) => eprintln!("error: {e}"),
    }
}
