```c
// Reverse a singly linked list, iteratively and recursively.
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *node_new(int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = NULL;
    return n;
}

static Node *push(Node *head, int value) {
    Node *n = node_new(value);
    n->next = head;
    return n;
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

static Node *reverse_iter(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *reverse_rec(Node *head) {
    if (head == NULL || head->next == NULL) {
        return head;
    }
    Node *new_head = reverse_rec(head->next);
    head->next->next = head;
    head->next = NULL;
    return new_head;
}

static void print_list(const char *label, const Node *head) {
    printf("%s:", label);
    for (; head != NULL; head = head->next) {
        printf(" %d", head->value);
    }
    printf("\n");
}

int main(void) {
    Node *list = NULL;
    for (int i = 5; i >= 1; --i) {
        list = push(list, i);
    }
    print_list("original", list);

    Node *iter = reverse_iter(list);
    print_list("iter", iter);
    free_list(iter);

    Node *again = NULL;
    for (int i = 3; i >= 1; --i) {
        again = push(again, i);
    }
    Node *rec = reverse_rec(again);
    print_list("rec", rec);
    free_list(rec);

    // Empty list edge case is handled by both functions.
    (void)reverse_rec(NULL);
    (void)reverse_iter(NULL);
    return 0;
}
