// Manual IPv4 validation without std::net.
#[derive(Debug, PartialEq)]
pub enum Ipv4Error {
    Empty,
    TooManyOctets,
    TooFewOctets,
    EmptyOctet(usize),
    NonDigit(usize, char),
    LeadingZero(usize),
    OutOfRange(usize),
}

impl std::fmt::Display for Ipv4Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Ipv4Error::Empty => write!(f, "address is empty"),
            Ipv4Error::TooManyOctets => write!(f, "more than 4 octets"),
            Ipv4Error::TooFewOctets => write!(f, "fewer than 4 octets"),
            Ipv4Error::EmptyOctet(i) => write!(f, "octet {i} is empty"),
            Ipv4Error::NonDigit(i, c) => write!(f, "octet {i} contains non-digit `{c}`"),
            Ipv4Error::LeadingZero(i) => write!(f, "octet {i} has a leading zero"),
            Ipv4Error::OutOfRange(i) => write!(f, "octet {i} exceeds 255"),
        }
    }
}

pub fn validate_ipv4(s: &str) -> Result<[u8; 4], Ipv4Error> {
    if s.is_empty() {
        return Err(Ipv4Error::Empty);
    }
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() > 4 {
        return Err(Ipv4Error::TooManyOctets);
    }
    if parts.len() < 4 {
        return Err(Ipv4Error::TooFewOctets);
    }

    let mut out = [0u8; 4];
    for (i, part) in parts.iter().enumerate() {
        if part.is_empty() {
            return Err(Ipv4Error::EmptyOctet(i));
        }
        if part.len() > 1 && part.starts_with('0') {
            return Err(Ipv4Error::LeadingZero(i));
        }
        let mut value: u32 = 0;
        for ch in part.chars() {
            let digit = ch.to_digit(10).ok_or(Ipv4Error::NonDigit(i, ch))?;
            value = value * 10 + digit;
        }
        if value > 255 {
            return Err(Ipv4Error::OutOfRange(i));
        }
        out[i] = value as u8;
    }
    Ok(out)
}

fn main() {
    for candidate in ["192.168.0.1", "256.1.1.1", "1.2.3", "01.2.3.4", "1.2.3.x", ""] {
        match validate_ipv4(candidate) {
            Ok(v) => println!("{candidate} -> {v:?}"),
            Err(e) => println!("{candidate} -> error: {e}"),
        }
    }
}
