```rust
use std::collections::VecDeque;

pub fn shortest_path(grid: &[Vec<char>]) -> Option<usize> {
    let rows = grid.len();
    if rows == 0 { return None; }
    let cols = grid[0].len();
    let mut start = None;
    for (r, row) in grid.iter().enumerate() {
        for (c, &ch) in row.iter().enumerate() {
            if ch == 'S' { start = Some((r, c)); }
        }
    }
    let (sr, sc) = start?;
    let mut dist = vec![vec![None; cols]; rows];
    let mut q = VecDeque::new();
    dist[sr][sc] = Some(0);
    q.push_back((sr, sc));
    let dirs = [(0isize, 1isize), (0, -1), (1, 0), (-1, 0)];
    while let Some((r, c)) = q.pop_front() {
        let d = dist[r][c].unwrap();
        if grid[r][c] == 'G' { return Some(d); }
        for &(dr, dc) in &dirs {
            let nr = r as isize + dr;
            let nc = c as isize + dc;
            if nr < 0 || nc < 0 { continue; }
            let (nr, nc) = (nr as usize, nc as usize);
            if nr >= rows || nc >= cols { continue; }
            if grid[nr][nc] == '#' || dist[nr][nc].is_some() { continue; }
            dist[nr][nc] = Some(d + 1);
            q.push_back((nr, nc));
        }
    }
    None
}
```

BFS over four-connected cells. Walls and visited cells are skipped, and the answer is the distance when 'G' is dequeued. A missing 'S', an empty grid, or an unreachable goal returns `None`. Unreachable goal is distinctly reported rather than as length 0.

