```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t len;
    size_t cap;
} Stack;

Stack *stack_new(void) {
    Stack *s = malloc(sizeof *s);
    if (!s) return NULL;
    s->cap = 4;
    s->len = 0;
    s->data = malloc(s->cap * sizeof *s->data);
    if (!s->data) { free(s); return NULL; }
    return s;
}

int stack_push(Stack *s, int value) {
    if (s->len == s->cap) {
        size_t cap = s->cap * 2;
        int *p = realloc(s->data, cap * sizeof *p);
        if (!p) return -1;
        s->data = p;
        s->cap = cap;
    }
    s->data[s->len++] = value;
    return 0;
}

int stack_pop(Stack *s, int *out) {
    if (s->len == 0) return -1;
    *out = s->data[--s->len];
    return 0;
}

int stack_peek(const Stack *s, int *out) {
    if (s->len == 0) return -1;
    *out = s->data[s->len - 1];
    return 0;
}

void stack_free(Stack *s) {
    if (!s) return;
    free(s->data);
    free(s);
}

int main(void) {
    Stack *s = stack_new();
    if (!s) return 1;
    for (int i = 1; i <= 10; i++) stack_push(s, i * i);
    int v;
    while (stack_pop(s, &v) == 0) printf("%d\n", v);
    if (stack_pop(s, &v) != 0) printf("empty\n");
    stack_free(s);
    return 0;
}
```

Capacity doubles on overflow; `realloc` failure leaves the original buffer intact and returns -1. Pop and peek distinguish underflow with -1 without leaking. `main` drains the stack, confirms underflow, then frees it.

