bool is_valid_ipv4(const std::string& s) {
    int parts = 0;
    size_t i = 0;
    while (i <= s.size()) {
        size_t j = s.find('.', i);
        if (j == std::string::npos) j = s.size();
        std::string seg = s.substr(i, j - i);
        if (seg.empty() || seg.size() > 3) return false;
        for (char c : seg) if (!std::isdigit(static_cast<unsigned char>(c))) return false;
        if (seg.size() > 1 && seg[0] == '0') return false;
        int v = std::stoi(seg);
        if (v < 0 || v > 255) return false;
        ++parts;
        if (j == s.size()) break;
        i = j + 1;
    }
    return parts == 4;
}
