#include <stdio.h>
#include <string.h>

/* Reverse a NUL-terminated string in place. */
void reverse(char *s) {
    if (s == NULL) return;
    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) return;          /* empty string */
    right--;                         /* last valid index */

    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char tests[][16] = {"hello", "", "a", "ab", "racecar"};
    size_t n = sizeof(tests) / sizeof(tests[0]);

    for (size_t i = 0; i < n; i++) {
        reverse(tests[i]);
        printf("[%s]\n", tests[i]);
    }
    return 0;
}
```

The `right` index starts one past the end and is decremented before use, which avoids the off-by-one that would read the NUL terminator. A single-character string has `left == right` after setup, so the loop body never runs and it is left unchanged.

