// Insert value into a vector that is already sorted ascending.
// Uses lower_bound so equal elements keep insertion order (stable).
template <typename T>
void sorted_insert(std::vector<T>& v, const T& value) {
    auto pos = std::lower_bound(v.begin(), v.end(), value);
    v.insert(pos, value);
}

int main() {
    std::vector<int> v = {1, 3, 3, 7, 9};
    sorted_insert(v, 0);   // front
    sorted_insert(v, 5);   // middle
    sorted_insert(v, 3);   // before existing 3s
    sorted_insert(v, 10);  // back

    for (std::size_t i = 0; i < v.size(); ++i) {
        std::cout << v[i];
        if (i + 1 != v.size()) std::cout << ' ';
    }
    std::cout << '\n';

    std::vector<std::string> words = {"apple", "banana", "date"};
    sorted_insert(words, "cherry");
    for (const auto& w : words) std::cout << w << ' ';
    std::cout << '\n';
}
