```rust
fn is_palindrome(s: &str) -> bool {
    let normalized: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();

    let mut left = 0usize;
    let mut right = normalized.len();
    if right == 0 {
        return true;               // empty after filtering
    }
    right -= 1;

    while left < right {
        if normalized[left] != normalized[right] {
            return false;
        }
        left += 1;
        right -= 1;
    }
    true
}

fn main() {
    let cases = [
        ("A man, a plan, a canal: Panama", true),
        ("race a car", false),
        ("", true),
        ("!!!", true),
        ("Äræ", false),
    ];

    for (input, expected) in cases {
        let got = is_palindrome(input);
        assert_eq!(got, expected, "failed on {:?}", input);
        println!("{:?} -> {}", input, got);
    }
    println!("all tests passed");
}
