```c
#include <limits.h>
#include <stdbool.h>
#include <stdio.h>

/* Parse a signed decimal integer from s.
 * Returns true on success and stores the value in *out.
 * Returns false on empty input, trailing garbage, or overflow. */
bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;

    const char *p = s;
    bool negative = false;
    if (*p == '+' || *p == '-') {
        negative = (*p == '-');
        p++;
    }
    if (*p < '0' || *p > '9') return false;

    long value = 0;
    while (*p >= '0' && *p <= '9') {
        value = value * 10 + (*p - '0');
        if (value > (long)INT_MAX + 1) return false;   /* far overflow */
        p++;
    }
    if (*p != '\0') return false;                      /* trailing junk */

    if (negative) value = -value;
    if (value < INT_MIN || value > INT_MAX) return false;

    *out = (int)value;
    return true;
}

int main(void) {
    const char *inputs[] = {"42", "-7", "", " 1", "12x", "2147483647",
                            "2147483648", "-2147483648", "-2147483649"};
    for (size_t i = 0; i < sizeof(inputs) / sizeof(inputs[0]); i++) {
        int v = 0;
        bool ok = parse_int(inputs[i], &v);
        if (ok) printf("[%s] -> %d\n", inputs[i], v);
        else    printf("[%s] -> error\n", inputs[i]);
    }
    return 0;
}
```

Accumulating in a `long` and checking against `INT_MAX`/`INT_MIN` avoids signed overflow in `int` when parsing `INT_MIN` or values just past the range. Any character that is not a digit after the optional sign makes the parse fail, so `" 1"` and `"12x"` are rejected rather than silently truncated.

```cpp
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <utility>
#include <vector>

template <typename T>
class BoundedStack {
public:
    explicit BoundedStack(std::size_t capacity) : cap_(capacity) {
        data_.reserve(capacity);
    }

    void push(const T& value) {
        if (data_.size() >= cap_) {
            throw std::overflow_error("BoundedStack: capacity exceeded");
        }
        data_.push_back(value);
    }

    T pop() {
        if (data_.empty()) {
            throw std::underflow_error("BoundedStack: empty");
        }
        T value = std::move(data_.back());
        data_.pop_back();
        return value;
    }

    const T& top() const {
        if (data_.empty()) {
            throw std::underflow_error("BoundedStack: empty");
        }
        return data_.back();
    }

    std::size_t size() const noexcept { return data_.size(); }
    bool empty() const noexcept { return data_.empty(); }

private:
    std::size_t cap_;
    std::vector<T> data_;
};

int main() {
    BoundedStack<int> s(3);
    assert(s.empty());
    s.push(1); s.push(2); s.push(3);
    assert(s.size() == 3);
    assert(s.top() == 3);

    bool overflowed = false;
    try { s.push(4); } catch (const std::overflow_error&) { overflowed = true; }
    assert(overflowed);

    assert(s.pop() == 3);
    assert(s.pop() == 2);
    assert(s.pop() == 1);

    bool underflowed = false;
    try { (void)s.pop(); } catch (const std::underflow_error&) { underflowed = true; }
    assert(underflowed);

    std::cout << "all tests passed\n";
}
```

Capacity is enforced in `push` before any mutation, so a failed push leaves the stack unchanged. `pop` moves the value out before shrinking the vector, avoiding an extra copy for non-trivial types, and `top` is a separate bounds-checked accessor.

