    reverse_range(s, 0, s.size() ? s.size() - 1 : 0);
    std::size_t n = s.size();
    std::size_t i = 0;
    while (i < n) {
        while (i < n && s[i] == ' ') ++i;
        std::size_t start = i;
        while (i < n && s[i] != ' ') ++i;
        if (start < i) reverse_range(s, start, i - 1);
    }
    return s;
}

