// "hello world" -> "world hello"; collapses multiple spaces to one.
std::string reverse_words(const std::string& s) {
    // Split on whitespace, reversing order, then rejoin with single spaces.
    std::string out;
    std::size_t i = 0, n = s.size();
    std::vector<std::string> words;
    while (i < n) {
        while (i < n && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
        if (i >= n) break;
        std::size_t start = i;
        while (i < n && !std::isspace(static_cast<unsigned char>(s[i]))) ++i;
        words.push_back(s.substr(start, i - start));
    }
    std::reverse(words.begin(), words.end());
    for (std::size_t k = 0; k < words.size(); ++k) {
        if (k) out += ' ';
        out += words[k];
    }
    return out;
}

int main() {
    std::cout << "[" << reverse_words("  the quick   brown fox ") << "]\n";
    std::cout << "[" << reverse_words("") << "]\n";
    std::cout << "[" << reverse_words("   ") << "]\n";
    return 0;
}
