#include <stdio.h>
#include <string.h>

static int matches(char open, char close) {
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

int is_balanced(const char *s) {
    char stack[256];
    size_t top = 0;
    for (const char *p = s; *p; p++) {
        if (*p == '(' || *p == '[' || *p == '{') {
            if (top == sizeof(stack)) return 0;  /* overflow guard */
            stack[top++] = *p;
        } else if (*p == ')' || *p == ']' || *p == '}') {
            if (top == 0 || !matches(stack[--top], *p)) return 0;
        }
        /* other characters are ignored */
    }
    return top == 0;
}

int main(void) {
    const char *tests[] = { "({[]})", "([)]", "", "(((", "a(b[c]{d}e)" };
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); i++)
        printf("%-12s -> %s\n", tests[i], is_balanced(tests[i]) ? "ok" : "bad");
    return 0;
