use std::fmt;
use std::num::ParseIntError;
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
}

#[derive(Debug, PartialEq, Eq)]
pub enum VersionError {
    MissingPart { index: usize },
    NotANumber { index: usize, source: ParseIntError },
    TooManyParts,
}

impl fmt::Display for VersionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            VersionError::MissingPart { index } => {
                write!(f, "version is missing component {index}")
            }
            VersionError::NotANumber { index, source } => {
                write!(f, "component {index} is not a number: {source}")
            }
            VersionError::TooManyParts => write!(f, "expected exactly three components"),
        }
    }
}

impl std::error::Error for VersionError {}

impl FromStr for Version {
    type Err = VersionError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let parts: Vec<&str> = s.split('.').collect();
        if parts.len() != 3 {
            return Err(VersionError::TooManyParts);
        }

        fn parse_part(text: &str, index: usize) -> Result<u64, VersionError> {
            if text.is_empty() {
                return Err(VersionError::MissingPart { index });
            }
            text.parse::<u64>()
                .map_err(|source| VersionError::NotANumber { index, source })
        }

        Ok(Version {
            major: parse_part(parts[0], 0)?,
            minor: parse_part(parts[1], 1)?,
            patch: parse_part(parts[2], 2)?,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_ok() {
        let v: Version = "1.2.3".parse().unwrap();
        assert_eq!(v, Version { major: 1, minor: 2, patch: 3 });
    }

    #[test]
    fn rejects_empty_and_short() {
        assert_eq!("".parse::<Version>(), Err(VersionError::TooManyParts));
        assert_eq!("1.2".parse::<Version>(), Err(VersionError::TooManyParts));
        assert!(matches!("1..3".parse::<Version>(), Err(VersionError::MissingPart { index: 1 })));
    }
}
