/* Reverse `s` in place. `s` must be a valid null-terminated string. */
void reverse_in_place(char *s) {
    char *left = s;
    char *right = s;

    /* Move `right` to the last character. */
    while (*right != '\0') {
        ++right;
    }
    if (right == s) {
        return; /* empty string */
    }
    --right;

    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        ++left;
        --right;
    }
}

int main(void) {
    const char *cases[] = {"", "a", "ab", "abc", "hello", "a\x01b"};
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        char buf[32];
        strcpy(buf, cases[i]);
        reverse_in_place(buf);
        printf("'%s' -> '%s'\n", cases[i], buf);
    }
    return 0;
}
