// Euclid's algorithm on the absolute values of a and b.
// SFINAE: only integral, non-bool types participate.
template <typename T,
          typename = std::enable_if_t<std::is_integral_v<T> &&
                                      !std::is_same_v<T, bool>>>
T gcd(T a, T b) {
    if (a < 0) a = static_cast<T>(-a);
    if (b < 0) b = static_cast<T>(-b);
    while (b != 0) {
        T tmp = a % b;
        a = b;
        b = tmp;
    }
    return a;
}

int main() {
    std::cout << gcd(48, 18) << '\n';      // 6
    std::cout << gcd(-48, 18) << '\n';     // 6
    std::cout << gcd(0, 5) << '\n';        // 5
    std::cout << gcd(0, 0) << '\n';        // 0

    // Compile error, as intended:
    // gcd(1.5, 2.5);
    // gcd(true, false);
    return 0;
}
