class RingAverage {
public:
    explicit RingAverage(std::size_t capacity)
        : buf_(capacity), head_(0), size_(0), sum_(0.0) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be positive");
        }
    }

    void push(double value) {
        if (size_ == buf_.size()) {
            sum_ -= buf_[head_];
        } else {
            ++size_;
        }
        buf_[head_] = value;
        sum_ += value;
        head_ = (head_ + 1) % buf_.size();
    }

    std::optional<double> average() const {
        if (size_ == 0) {
            return std::nullopt;
        }
        return sum_ / static_cast<double>(size_);
    }

    std::size_t size() const { return size_; }

private:
    std::vector<double> buf_;
    std::size_t head_;
    std::size_t size_;
    double sum_;
};

#include <cassert>
