import functools
import time


def retry(attempts=3, base_delay=0.1, exceptions=(Exception,)):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt == attempts:
                        break
                    time.sleep(base_delay * (2 ** (attempt - 1)))
            raise last
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=3, base_delay=0)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return "done"

    assert flaky() == "done"
    assert calls["n"] == 3
```

Set `base_delay=0` in tests so they run instantly; the real backoff doubles each attempt.

