    for (int i = 1; i <= 4; ++i) {
        Node *n = malloc(sizeof(Node));
        if (!n) return 1;
        n->value = i;
        n->next = head;
        head = n;
    }
    head = reverse(head);
    for (Node *p = head; p != NULL; p = p->next) {
        printf("%d ", p->value);
    }
    printf("\n");
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
