```python
class RingBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._data = [None] * capacity
        self._start = 0
        self._size = 0

    def __len__(self):
        return self._size

    def push(self, value):
        if self._size == self._capacity:
            # overwrite oldest
            self._data[self._start] = value
            self._start = (self._start + 1) % self._capacity
        else:
            idx = (self._start + self._size) % self._capacity
            self._data[idx] = value
            self._size += 1

    def pop_oldest(self):
        if self._size == 0:
            raise IndexError("pop from empty ring buffer")
        value = self._data[self._start]
        self._data[self._start] = None
        self._start = (self._start + 1) % self._capacity
        self._size -= 1
        return value

    def __iter__(self):
        for i in range(self._size):
            yield self._data[(self._start + i) % self._capacity]


if __name__ == "__main__":
    rb = RingBuffer(3)
    for v in (1, 2, 3, 4):
        rb.push(v)
    assert list(rb) == [2, 3, 4]
    assert rb.pop_oldest() == 2
    assert len(rb) == 2
    print("ok")
```

Uses a fixed list plus a start index, so wrap-around never shifts memory. The overwrite on a full buffer discards the oldest element, which is the usual ring-buffer contract.

