const long long MOD = 1000000007LL;

long long fib_mod(long long n) {
    if (n == 0) return 0;
    long long a = 0, b = 1;
    for (long long i = 2; i <= n; ++i) {
        long long c = (a + b) % MOD;
        a = b;
        b = c;
    }
    return b;
}

