std::vector<int> merge_unique(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    size_t i = 0, j = 0;
    while (i < a.size() || j < b.size()) {
        int val;
        if (i == a.size()) val = b[j++];
        else if (j == b.size()) val = a[i++];
        else if (a[i] < b[j]) val = a[i++];
        else val = b[j++];
        if (out.empty() || out.back() != val) out.push_back(val);
    }
    return out;
