        sys.exit("config root must be a JSON object")
    missing = REQUIRED - cfg.keys()
    if missing:
        sys.exit("missing required keys: " + ", ".join(sorted(missing)))
    for key, expected in SCHEMA.items():
        value = cfg[key]
        if expected is int and isinstance(value, bool):
            sys.exit(f"{key}: expected int, got bool")
        if not isinstance(value, expected):
            sys.exit(f"{key}: expected {expected.__name__}, got {type(value).__name__}")
    if not (0 < cfg["port"] < 65536):
        sys.exit("port must be between 1 and 65535")
    if any(not isinstance(t, str) for t in cfg["tags"]):
        sys.exit("tags must all be strings")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit("usage: validate.py <config.json>")
    data = load(sys.argv[1])
    validate(data)
    print("config ok")
