```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<double> pop() {
        if (count_ == 0) return std::nullopt;
        double value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    std::size_t capacity() const { return N; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<3> rb;
    if (rb.pop().has_value()) return 1;
    if (!rb.push(1.5) || !rb.push(2.5) || !rb.push(3.5)) return 1;
    if (rb.push(4.5)) return 1;             // full
    if (rb.pop() != 1.5) return 1;
    if (!rb.push(4.5)) return 1;            // wraps
    if (rb.size() != 3) return 1;
    double expected[] = {2.5, 3.5, 4.5};
    for (double want : expected) {
        auto got = rb.pop();
        if (!got || *got != want) return 1;
    }
    if (rb.size() != 0) return 1;
    std::cout << "ring buffer ok\n";
    return 0;
}
```

`std::optional` makes an empty pop explicit instead of returning a sentinel. The modulus on `(head_ + count_) % N` handles wrap-around for free.

