#[derive(Debug, PartialEq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
}

#[derive(Debug, PartialEq)]
pub enum ParseError {
    EmptyPart,
    NotANumber { part: String },
    WrongPartCount { found: usize },
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ParseError::EmptyPart => write!(f, "version part is empty"),
            ParseError::NotANumber { part } => write!(f, "{part:?} is not a number"),
            ParseError::WrongPartCount { found } => {
                write!(f, "expected 3 parts (major.minor.patch), found {found}")
            }
        }
    }
}

pub fn parse(input: &str) -> Result<Version, ParseError> {
    let parts: Vec<&str> = input.split('.').collect();
    if parts.len() != 3 {
        return Err(ParseError::WrongPartCount { found: parts.len() });
    }
    let mut nums = [0u64; 3];
    for (i, raw) in parts.iter().enumerate() {
        if raw.is_empty() {
            return Err(ParseError::EmptyPart);
        }
        nums[i] = raw.parse().map_err(|_| ParseError::NotANumber {
            part: (*raw).to_string(),
        })?;
    }
    Ok(Version { major: nums[0], minor: nums[1], patch: nums[2] })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_valid() {
        assert_eq!(parse("1.2.3"), Ok(Version { major: 1, minor: 2, patch: 3 }));
    }

    #[test]
    fn rejects_bad() {
        assert!(matches!(parse("1.2"), Err(ParseError::WrongPartCount { found: 2 })));
        assert!(matches!(parse("1..3"), Err(ParseError::EmptyPart)));
        assert!(matches!(parse("a.2.3"), Err(ParseError::NotANumber { .. })));
    }
}
```

The error enum carries the offending part so callers can print an actionable message; `Display` gives human-readable output for free.

```python
from typing import Iterable, Iterator, List, Sequence, TypeVar

T = TypeVar("T")

def batched(items: Sequence[T], size: int, drop_last: bool = False) -> Iterator[List[T]]:
    if size <= 0:
        raise ValueError("size must be positive")
    total = len(items)
    for start in range(0, total, size):
        chunk = list(items[start:start + size])
        if drop_last and len(chunk) < size:
            return
        yield chunk

def batched_stream(items: Iterable[T], size: int, drop_last: bool = False) -> Iterator[List[T]]:
    """Works on generators too, without materialising the whole input."""
    if size <= 0:
        raise ValueError("size must be positive")
    chunk: List[T] = []
    for item in items:
        chunk.append(item)
        if len(chunk) == size:
            yield chunk
            chunk = []
    if chunk and not drop_last:
        yield chunk

if __name__ == "__main__":
    data = [1, 2, 3, 4, 5, 6, 7]
    assert list(batched(data, 3)) == [[1, 2, 3], [4, 5, 6], [7]]
    assert list(batched(data, 3, drop_last=True)) == [[1, 2, 3], [4, 5, 6]]
    assert list(batched([], 3)) == []
    assert list(batched_stream(iter(data), 2)) == [[1, 2], [3, 4], [5, 6], [7]]
    print("ok")
```

`batched` slices sequences directly; `batched_stream` handles one-shot iterators in constant memory. Both validate `size` up front so `range(0, total, 0)` can never be reached.

