                // Broken pipe is normal when piped into `head`.
                if e.kind() == io::ErrorKind::BrokenPipe {
                    return;
                }
                eprintln!("write error: {e}");
                process::exit(1);
            }
        }
    }

    if let Err(e) = out.flush() {
        eprintln!("flush error: {e}");
        process::exit(1);
    }
}
```

Usage: `cat log.txt | unique-lines`. It keeps only line contents, so trailing-newline differences vanish but whitespace inside a line is preserved. Memory is one copy of every distinct line seen; that is the price of first-seen order.

