from itertools import islice


def primes():
    """Yield primes indefinitely via an incremental sieve."""
    yield 2
    composites = {}
    candidate = 3
    while True:
        if candidate not in composites:
            yield candidate
            composites[candidate * candidate] = [candidate]
        else:
            for factor in composites[candidate]:
                composites.setdefault(factor + candidate, []).append(factor)
            del composites[candidate]
        candidate += 2


