def parse_config(text, required=()):
    config = {}
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        for pair in line.split(";"):
            pair = pair.strip()
            if not pair:
                continue
            if "=" not in pair:
                raise ValueError(f"line {lineno}: missing '=' in {pair!r}")
            key, _, value = pair.partition("=")
            key = key.strip()
            if not key:
                raise ValueError(f"line {lineno}: empty key")
            if key in config:
                raise ValueError(f"line {lineno}: duplicate key {key!r}")
            config[key] = value.strip()

    missing = [k for k in required if k not in config]
    if missing:
        raise ValueError("missing required keys: " + ", ".join(missing))
    return config


if __name__ == "__main__":
    cfg = parse_config(
        "# server\nhost = localhost;port = 8080\nname = my app\n",
        required=("host", "port"),
    )
    assert cfg == {"host": "localhost", "port": "8080", "name": "my app"}
    for bad in ("host\n", "host=a;host=b", "=x"):
        try:
            parse_config(bad)
            raise AssertionError(f"expected failure for {bad!r}")
        except ValueError:
            pass
    print("ok")
```

