template <std::size_t N>
class RingBuffer {
    int data[N]{};
    std::size_t head = 0;
    std::size_t count = 0;
public:
    bool push(int value) {
        if (count == N) return false;
        data[(head + count) % N] = value;
        ++count;
        return true;
    }
    std::optional<int> pop() {
        if (count == 0) return std::nullopt;
        int value = data[head];
        head = (head + 1) % N;
        --count;
        return value;
    }
};
