use std::collections::HashMap;

pub fn top_chars(s: &str, k: usize) -> Vec<(char, usize)> {
    let mut counts: HashMap<char, usize> = HashMap::new();
    for ch in s.chars() {
        *counts.entry(ch).or_insert(0) += 1;
    }
    let mut pairs: Vec<(char, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    pairs.truncate(k);
    pairs
}

fn main() {
    let text = "hello, world! \u{1F30D}";
    let top = top_chars(text, 3);
    for (ch, n) in &top {
        println!("{:?}: {}", ch, n);
    }

    assert_eq!(top_chars("", 5), Vec::new());
    assert_eq!(top_chars("aabbc", 1), vec![('a', 2)]);
    // tie between 'a' and 'b' resolves to 'a' first
    assert_eq!(top_chars("ab", 2), vec![('a', 1), ('b', 1)]);
}
