#include <iostream>
#include <stack>
#include <string>

bool balanced(const std::string& s, size_t& badPos) {
    std::stack<std::pair<char, size_t>> st;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push({c, i});
        } else if (c == ')' || c == ']' || c == '}') {
            char want = c == ')' ? '(' : (c == ']' ? '[' : '{');
            if (st.empty() || st.top().first != want) { badPos = i; return false; }
            st.pop();
        }
    }
    if (!st.empty()) { badPos = st.top().second; return false; }
    return true;
}

int main() {
    size_t pos = 0;
    std::cout << balanced("{[()]}", pos) << "\n";   // 1
    std::cout << balanced("{(]}", pos) << " pos=" << pos << "\n"; // 0 pos=2
    std::cout << balanced("((", pos) << " pos=" << pos << "\n";   // 0 pos=1
    std::cout << balanced("hi", pos) << "\n";        // 1
}
