class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), count_(0) {}

    bool push(int value) {
        if (count_ == data_.size()) {
            return false;
        }
        data_[(head_ + count_) % data_.size()] = value;
        ++count_;
        return true;
    }

    std::optional<int> pop() {
        if (count_ == 0) {
            return std::nullopt;
        }
        int value = data_[head_];
        head_ = (head_ + 1) % data_.size();
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }

private:
    std::vector<int> data_;
    std::size_t head_;
    std::size_t count_;
};

int main() {
