```rust
/// True if `s` reads the same forwards and backwards, ignoring nothing but
/// working on Unicode scalar values rather than bytes.
pub fn is_palindrome(s: &str) -> bool {
    let chars: Vec<char> = s.chars().collect();
    let mut left = 0usize;
    let mut right = chars.len();
    while left < right {
        right -= 1;
        if left >= right {
            break;
        }
        if chars[left] != chars[right] {
            return false;
        }
        left += 1;
    }
    true
}

fn main() {
    assert!(is_palindrome(""));
    assert!(is_palindrome("a"));
    assert!(is_palindrome("racecar"));
    assert!(is_palindrome("été"));
    assert!(!is_palindrome("hello"));
    assert!(is_palindrome("日本語語本日"));
    println!("all checks passed");
}
```

Two-pointer scan over `Vec<char>` avoids slicing a multibyte character in half, which a `&str` index would do. The `left >= right` guard handles both even and odd lengths, and the empty string returns `true` correctly.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

template <std::size_t N>
class RingBuffer {
public:
    void push(double value) {
        if (size_ == N) {
            ++overwrites_;
        } else {
            ++size_;
        }
        data_[head_] = value;
        head_ = (head_ + 1) % N;
    }

    std::size_t size() const { return size_; }
    std::size_t overwrites() const { return overwrites_; }

    // Oldest element first; index 0 is the oldest surviving value.
    double at(std::size_t i) const {
        if (i >= size_) {
            throw std::out_of_range("RingBuffer::at");
        }
        const std::size_t start = (head_ + N - size_) % N;
        return data_[(start + i) % N];
    }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
    std::size_t overwrites_ = 0;
};

int main() {
    RingBuffer<3> rb;
    rb.push(1.0);
    rb.push(2.0);
    rb.push(3.0);
    rb.push(4.0);
    rb.push(5.0);
    std::cout << rb.size() << ' ' << rb.overwrites() << '\n'; // 3 2
    std::cout << rb.at(0) << ' ' << rb.at(2) << '\n';          // 3 5
}
```

`head_` points at the next write slot, so the oldest element is `head_ - size_` wrapped around. The overwrite counter increments only once capacity is reached, which is what separates "refused writes" from "data lost".

