```python
import functools
import time
from typing import Callable, TypeVar

T = TypeVar("T")


def retry(attempts: int = 3, base_delay: float = 0.1,
          exceptions: tuple[type[Exception], ...] = (Exception,)) -> Callable:
    """Retry the wrapped function up to `attempts` times total.

    Waits base_delay * 2**(n-1) between tries. Re-raises the last error.
    """
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> T:
            delay = base_delay
            last: Exception | None = None
            for n in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if n == attempts:
                        break
                    time.sleep(delay)
                    delay *= 2
            assert last is not None
            raise last
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base_delay=0.0)
    def flaky() -> str:
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return "ok"

    assert flaky() == "ok"
    assert calls["n"] == 3

    @retry(attempts=2, base_delay=0.0)
    def always() -> None:
        raise RuntimeError("boom")

    try:
        always()
    except RuntimeError as e:
        assert str(e) == "boom"
    else:
        raise AssertionError("should have raised")
    print("ok")
```

`base_delay=0.0` in the tests keeps the suite instant while still exercising the loop. `functools.wraps` preserves the wrapped function's name and docstring, and the final `raise last` re-raises the original exception so callers see the true error type, not a wrapper.

