use std::collections::HashMap;

struct Collatz {
    cache: HashMap<u64, u64>,
}

impl Collatz {
    fn new() -> Self {
        Collatz { cache: HashMap::new() }
    }

    fn length(&mut self, n: u64) -> u64 {
        if n == 1 {
            return 1;
        }
        if let Some(&v) = self.cache.get(&n) {
            return v;
        }
        let next = if n % 2 == 0 { n / 2 } else { 3 * n + 1 };
        let len = 1 + self.length(next);
        self.cache.insert(n, len);
        len
    }
}

fn main() {
