#include <iostream>
#include <stack>
#include <string>

bool balanced(const std::string& s, std::size_t& bad_pos) {
    std::stack<char> st;
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            char want = c == ')' ? '(' : c == ']' ? '[' : '{';
            if (st.empty() || st.top() != want) {
                bad_pos = i;
                return false;
            }
            st.pop();
        }
    }
    if (!st.empty()) {
        bad_pos = s.size();
        return false;
    }
    bad_pos = 0;
    return true;
}

int main() {
    std::size_t pos = 0;
    std::cout << balanced("([]{})", pos) << "\n";
    std::cout << balanced("([)]", pos) << " pos=" << pos << "\n";
    std::cout << balanced("(((", pos) << "\n";
    std::cout << balanced("", pos) << "\n";
    return 0;
