void reverse_string(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    for (size_t i = 0; i < len / 2; i++) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
}

int main(void) {
    char a[] = "hello world";
    char b[] = "";
    char c[] = "x";
    char d[] = "ab";

    reverse_string(a);
    reverse_string(b);
    reverse_string(c);
    reverse_string(d);

    printf("%s\n", a);  /* dlrow olleh */
    printf("[%s]\n", b); /* [] */
    printf("%s\n", c);  /* x */
    printf("%s\n", d);  /* ba */

    if (strcmp(a, "dlrow olleh") != 0) return 1;
    if (strcmp(b, "") != 0) return 1;
    if (strcmp(c, "x") != 0) return 1;
    if (strcmp(d, "ba") != 0) return 1;
    return 0;
}
