bool are_anagrams(const std::string &a, const std::string &b) {
    std::array<int, 26> counts{};
    auto add = [&counts](const std::string &s, int sign) {
        for (unsigned char ch : s) {
            if (std::isalpha(ch)) {
                counts[std::tolower(ch) - 'a'] += sign;
            }
        }
    };
    add(a, 1);
    add(b, -1);
    for (int c : counts) {
        if (c != 0) return false;
    }
    return true;
}

int main() {
    struct Case { std::string a, b; bool expected; };
    Case cases[] = {
        {"Listen", "Silent", true},
        {"Dormitory", "dirty room", true},
        {"hello", "world", false},
        {"", "", true},
        {"Abc", "cba!", true},
    };
    for (const auto &c : cases) {
        bool got = are_anagrams(c.a, c.b);
        if (got != c.expected) {
            std::cerr << "FAIL: " << c.a << " / " << c.b << "\n";
