fn fib(n: u64) -> u128 {
    fn helper(n: u64) -> (u128, u128) {
        if n == 0 {
            return (0, 1);
        }
        let (a, b) = helper(n / 2);
        let c = a * (2 * b - a);
        let d = a * a + b * b;
        if n % 2 == 0 {
            (c, d)
        } else {
            (d, c + d)
        }
    }
    helper(n).0
}

