```c
#include <stdio.h>

#define MAX_W 64

int max_int(int a, int b) { return a > b ? a : b; }

int knapsack(const int *weights, const int *values, int n, int capacity) {
    int dp[MAX_W + 1] = {0};
    for (int i = 0; i < n; i++) {
        for (int w = capacity; w >= weights[i]; w--) {
            dp[w] = max_int(dp[w], dp[w - weights[i]] + values[i]);
        }
    }
    return dp[capacity];
}

int main(void) {
    int weights[] = {2, 3, 4, 5};
    int values[]  = {3, 4, 5, 6};
    int n = 4;
    int capacity = 7;
    int best = knapsack(weights, values, n, capacity);
    printf("max value: %d\n", best);  /* 3 + 4 = 7 using items 0 and 1 */
    if (best != 7) {
        fprintf(stderr, "unexpected result\n");
        return 1;
    }
    return 0;
}
```

The inner loop goes from `capacity` down to `weights[i]`, which is what prevents an item from being counted twice. The array holds the best value for every capacity up to the limit, and the answer sits at `dp[capacity]`. Complexity is O(n · capacity) time and O(capacity) space.

```rust
use std::collections::{HashMap, VecDeque};

struct LruCache {
    capacity: usize,
    map: HashMap<String, i64>,
    order: VecDeque<String>,
}

impl LruCache {
    fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        LruCache { capacity, map: HashMap::new(), order: VecDeque::new() }
    }

    fn touch(&mut self, key: &str) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            self.order.remove(pos);
        }
        self.order.push_back(key.to_string());
    }

    fn get(&mut self, key: &str) -> Option<i64> {
        let value = *self.map.get(key)?;
        self.touch(key);
        Some(value)
    }

    fn put(&mut self, key: &str, value: i64) {
        self.map.insert(key.to_string(), value);
        self.touch(key);
        while self.order.len() > self.capacity {
            if let Some(old) = self.order.pop_front() {
                if old != key {
                    self.map.remove(&old);
                }
            }
        }
    }
}

fn main() {
    let mut cache = LruCache::new(2);
    cache.put("a", 1);
    cache.put("b", 2);
    assert_eq!(cache.get("a"), Some(1));
    cache.put("c", 3);
    assert_eq!(cache.get("b"), None);
    assert_eq!(cache.get("a"), Some(1));
    assert_eq!(cache.get("c"), Some(3));
    println!("all tests passed");
}
```

`order` keeps keys from least to most recently used; `touch` moves an accessed key to the back, and eviction pops from the front and removes the key from the map. Capacity must be at least one, so the eviction loop always has a key to drop. This is O(n) per access because of the deque scan — fine for small caches; a linked list would make it O(1).

