import threading
from collections import deque
from typing import Optional


class BoundedQueue:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._cap = capacity
        self._items: deque = deque()
        self._cv = threading.Condition()

    def put(self, item) -> None:
        with self._cv:
            while len(self._items) >= self._cap:
                self._cv.wait()
            self._items.append(item)
            self._cv.notify_all()

    def get(self) -> object:
        with self._cv:
            while not self._items:
                self._cv.wait()
            item = self._items.popleft()
            self._cv.notify_all()
            return item

    def size(self) -> int:
        with self._cv:
            return len(self._items)


def _test() -> None:
    q = BoundedQueue(2)
    results: list[int] = []

    def producer() -> None:
        for i in range(5):
            q.put(i)

    def consumer() -> None:
        for _ in range(5):
            results.append(q.get())

    ts = [threading.Thread(target=producer), threading.Thread(target=consumer)]
    for t in ts:
        t.start()
    for t in ts:
        t.join()
    assert sorted(results) == [0, 1, 2, 3, 4], results
    assert q.size() == 0
    print("all tests passed")


if __name__ == "__main__":
    _test()
```

Both `put` and `get` use `while` loops around `wait()` so a spurious wakeup re-checks the condition. `notify_all` is used rather than `notify` because waiters on either side may be runnable. The producer blocks once two items are queued, and the two threads drain in order.

