def longest_palindrome_length(s: str) -> int:
    if not s:
        return 0
    best = 1

    def expand(left: int, right: int) -> int:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return right - left - 1

    for i in range(len(s)):
        best = max(best, expand(i, i))
        if i + 1 < len(s):
            best = max(best, expand(i, i + 1))
    return best

