```cpp
#include <cstddef>
#include <iostream>
#include <stdexcept>

 template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (count_ < N) ++count_;
    }

    T pop() {
        if (count_ == 0) throw std::underflow_error("ring buffer empty");
        std::size_t tail = (head_ + N - count_) % N;
        T value = data_[tail];
        --count_;
        return value;
    }

    const T& at(std::size_t index) const {
        if (index >= count_) throw std::out_of_range("ring buffer index");
        std::size_t tail = (head_ + N - count_) % N;
        return data_[(tail + index) % N];
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    static constexpr std::size_t capacity() { return N; }

private:
    T data_[N]{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4);  // evicts 1
    if (rb.size() != 3 || rb.at(0) != 2 || rb.at(2) != 4)
        throw std::runtime_error("overwrite check failed");
    if (rb.pop() != 2 || rb.pop() != 3 || rb.pop() != 4 || !rb.empty())
        throw std::runtime_error("pop order failed");
    std::cout << "ring buffer checks passed\n";
    return 0;
}
```

`head_` is the next write slot and `count_` tracks live elements, so `at(0)` is always the oldest. `pop` computes the tail as `(head_ + N - count_) % N` instead of keeping a second index.

