use std::collections::{HashMap, VecDeque};

struct LruCache {
    capacity: usize,
    map: HashMap<String, i64>,
    order: VecDeque<String>,
}

impl LruCache {
    fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        LruCache { capacity, map: HashMap::new(), order: VecDeque::new() }
    }

    fn touch(&mut self, key: &str) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            self.order.remove(pos);
        }
        self.order.push_front(key.to_string());
    }

    fn get(&mut self, key: &str) -> Option<i64> {
        let value = *self.map.get(key)?;
        self.touch(key);
        Some(value)
    }

    fn put(&mut self, key: &str, value: i64) {
        if self.capacity == 0 {
            return;
        }
        self.map.insert(key.to_string(), value);
        self.touch(key);
        while self.order.len() > self.capacity {
            if let Some(old) = self.order.pop_back() {
                self.map.remove(&old);
            }
        }
    }
}

fn main() {
    let mut cache = LruCache::new(2);
    cache.put("a", 1);
    cache.put("b", 2);
    assert_eq!(cache.get("a"), Some(1));
    cache.put("c", 3);          // evicts "b"
    assert_eq!(cache.get("b"), None);
    assert_eq!(cache.get("a"), Some(1));
    assert_eq!(cache.get("c"), Some(3));
    println!("lru cache checks passed");
}
```

The `order` deque stores most-recent keys at the front. `touch` removes a key before re-adding, so `get` on an existing key refreshes it without duplicating the deque entry.

```python
import math


class InvalidDivisionError(ValueError):
    """Raised when a division cannot produce a finite result."""


def safe_divide(numerator: float, denominator: float) -> float:
    for name, value in (("numerator", numerator), ("denominator", denominator)):
        if not isinstance(value, (int, float)):
            raise InvalidDivisionError(f"{name} must be numeric, got {type(value).__name__}")
        if not math.isfinite(value):
            raise InvalidDivisionError(f"{name} must be finite, got {value!r}")
    if denominator == 0:
        raise InvalidDivisionError("denominator must not be zero")
    result = numerator / denominator
    if not math.isfinite(result):
        raise InvalidDivisionError(f"result is not finite: {result!r}")
    return result


if __name__ == "__main__":
    assert safe_divide(10, 4) == 2.5
    assert safe_divide(-3, 2) == -1.5
    assert safe_divide(0.0, 7) == 0.0

    for bad_args in [(1, 0), (1, 0.0), (math.nan, 2), (2, math.inf), (3, math.nan)]:
        try:
            safe_divide(*bad_args)
        except InvalidDivisionError as exc:
            print(f"rejected {bad_args}: {exc}")
        else:
            raise AssertionError(f"expected rejection for {bad_args}")
    print("all safe_divide checks passed")
```

Zero in either int or float form is caught before the divide, and `math.isfinite` rejects NaN and infinities on both input and output so a huge numerator over a tiny denominator fails loudly instead of silently returning `inf`.

