```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(l: int, r: int) -> tuple[int, int]:
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end + 1]


if __name__ == "__main__":
    print(longest_palindrome("babad"))  # bab
    print(longest_palindrome("cbbd"))   # bb
    print(longest_palindrome(""))       # (empty)
```

Expand around each center, tracking the widest window found. For `"babad"` the centers at index 0 (`b`) and index 2 (`a`) expand to `"bab"`; output is `bab`. Odd and even centers are both checked so single-char and double-char palindromes are covered.

```cpp
#include <iostream>
#include <utility>

constexpr long long MOD = 1000000007LL;

// Returns {F(n), F(n+1)}
std::pair<long long, long long> fib(long long n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib(n >> 1);
    long long c = a * ((2 * b % MOD - a + MOD) % MOD) % MOD;
    long long d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1) return {d, (c + d) % MOD};
    return {c, d};
}

int main() {
    long long n;
    if (!(std::cin >> n) || n < 0) {
        std::cerr << "expected a non-negative integer\n";
        return 1;
    }
    std::cout << fib(n).first << '\n';
    return 0;
}
```

Fast doubling runs in O(log n). For `n = 90` the true value is 2880067194370816120, so mod 1e9+7 the program prints `2880067194370816120 % 1000000007 = 856064934`. It rejects negative input and handles the `n = 0` base case without recursion overflow, since depth is about 60 for realistic inputs.

