```c
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <inttypes.h>

static int popcount_kernighan(uint64_t x) {
    int count = 0;
    while (x) {
        x &= x - 1;  /* clears the lowest set bit */
        count++;
    }
    return count;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <non-negative integer>\n", argv[0]);
        return 2;
    }

    errno = 0;
    char *end = NULL;
    unsigned long long v = strtoull(argv[1], &end, 10);
    if (errno != 0 || end == argv[1] || *end != '\0') {
        fprintf(stderr, "error: '%s' is not a valid integer\n", argv[1]);
        return 1;
    }

    printf("%d\n", popcount_kernighan((uint64_t)v));
    return 0;
}
```

Kernighan's trick `x &= x - 1` clears the lowest set bit each iteration, so the loop runs exactly as many times as there are set bits. `strtoull` with `errno` and `end` checks rejects trailing garbage and values out of `uint64_t` range. `./popcount 255` prints 8; `./popcount abc` exits 1 with a clear message.

```rust
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let x = vec![1, 3, 3, 7];
    let y = vec![2, 3, 8];
    println!("{:?}", merge_sorted(&x, &y)); // [1, 2, 3, 3, 3, 7, 8]

    let empty: Vec<i32> = vec![];
    println!("{:?}", merge_sorted(&x, &empty)); // x unchanged

    let u = vec!["apple".to_string(), "pear".to_string()];
    let v = vec!["café".to_string(), "zebra".to_string()];
    println!("{:?}", merge_sorted(&u, &v));
}
```

The `<=` comparison decides ties in favor of `a`, which preserves duplicate elements from both sides. The trailing `extend_from_slice` flushes whichever slice still has remaining items once one side is exhausted, so an empty side works with no special casing. The generic `T: Ord + Clone` signature works for integers and `String`; `café` sorts by Unicode scalar values.

```cpp
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), size_(0) {}

    bool push(int value) {
        if (size_ == buf_.size()) return false;  // full
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % buf_.size();
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;      // empty
        int v = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<int> buf_;
    std::size_t head_, tail_, size_;
};

int main() {
    RingBuffer rb(3);
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << '\n'; // 111
    std::cout << rb.push(4) << '\n';                            // 0 (full)
    std::cout << *rb.pop() << '\n';                             // 1
    rb.push(5);
    while (auto v = rb.pop()) std::cout << *v << ' ';           // 2 3 5
    std::cout << '\n' << rb.pop().has_value() << '\n';          // 0 (empty)
}
```

`head_`/`tail_` wrap modulo capacity, so storage is reused with no shifting. `push` returns `false` when full and `pop` returns `std::nullopt` when empty, making both failure modes explicit instead of undefined. `size_ == buf_.size()` distinguishes full from empty even though `head_ == tail_` could mean either.

```python
import csv
import io
import re
import sys

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def validate(rows: list[dict[str, str]]) -> list[str]:
    errors: list[str] = []
    if not rows:
        return ["input has no data rows"]
    required = {"id", "email", "age"}
    missing = required - set(rows[0].keys())
    if missing:
        return [f"missing column(s): {', '.join(sorted(missing))}"]

    seen: set[str] = set()
    for lineno, row in enumerate(rows, start=2):
        rid = (row.get("id") or "").strip()
        if not rid:
            errors.append(f"line {lineno}: empty id")
        elif rid in seen:
            errors.append(f"line {lineno}: duplicate id {rid!r}")
        else:
            seen.add(rid)

        email = (row.get("email") or "").strip()
        if not EMAIL_RE.match(email):
            errors.append(f"line {lineno}: invalid email {email!r}")

        try:
            age = int(row.get("age") or "")
            if not 0 <= age <= 150:
                errors.append(f"line {lineno}: age {age} out of range")
        except ValueError:
            errors.append(f"line {lineno}: non-integer age {row.get('age')!r}")
    return errors


if __name__ == "__main__":
    raw = sys.stdin.read()
    if not raw.strip():
        print("no input", file=sys.stderr)
        sys.exit(1)
    reader = csv.DictReader(io.StringIO(raw))
    problems = validate(list(reader))
    if problems:
        for p in problems:
            print(p, file=sys.stderr)
        sys.exit(1)
    print("all rows valid")
```

`DictReader` maps headers to values, so the missing-column check runs against the first row's keys before any indexing. Duplicate detection uses a set for O(1) lookups, and line numbers start at 2 to match a file with a header. Empty input is caught before parsing, and a bad age or email adds one message rather than aborting, so every problem is reported in a single pass.

