bool isPalindrome(const std::string& s) {
    size_t i = 0, j = s.size();
    while (i < j) {
        if (!std::isalnum(static_cast<unsigned char>(s[i]))) { ++i; continue; }
        if (!std::isalnum(static_cast<unsigned char>(s[j - 1]))) { --j; continue; }
        if (std::tolower(static_cast<unsigned char>(s[i])) !=
            std::tolower(static_cast<unsigned char>(s[j - 1]))) {
            return false;
        }
        ++i;
        --j;
    }
    return true;
}

int main() {
    struct Case { std::string in; bool want; };
    Case cases[] = {
        {"A man, a plan, a canal: Panama", true},
        {"race a car", false},
        {"", true},
        {"!!!", true},
        {"No 'x' in Nixon", true},
        {"hello", false},
    };
    for (const auto& c : cases) {
        bool got = isPalindrome(c.in);
        std::cout << (got == c.want ? "ok  " : "FAIL") << " : " << c.in << '\n';
        if (got != c.want) return 1;
    }
    return 0;
}
