}

int main() {
    auto check = [](uint32_t n, uint64_t want) {
        auto r = fib(n);
        if (!r || *r != want) { std::cout << "FAIL at " << n << '\n'; std::exit(1); }
    };
    check(0, 0);
    check(1, 1);
    check(10, 55);
    check(50, 12586269025ULL);
    // F(93) is the largest value fitting in uint64_t; F(94) overflows.
    std::cout << "F(93)=" << *fib(93) << "\n";
    if (fib(94).has_value()) { std::cout << "expected overflow\n"; return 1; }
    std::cout << "all tests passed\n";
}
```
The `next < a` check catches unsigned wraparound; `std::optional` signals overflow instead of returning a bogus number.

```rust
use std::num::NonZeroU64;

/// Returns (gcd, lcm). Panics if either input is zero.
fn gcd_lcm(a: u64, b: u64) -> (u64, u64) {
    let a = NonZeroU64::new(a).expect("a must be non-zero");
    let b = NonZeroU64::new(b).expect("b must be non-zero");
    let (mut x, mut y) = (a.get(), b.get());
    while y != 0 {
        let t = y;
        y = x % y;
        x = t;
    }
    let gcd = x;
    // Divide before multiplying to reduce overflow risk.
    let lcm = (a.get() / gcd).checked_mul(b.get()).expect("lcm overflow");
    (gcd, lcm)
}

fn main() {
    assert_eq!(gcd_lcm(48, 18), (6, 144));
    assert_eq!(gcd_lcm(7, 13), (1, 91));
    assert_eq!(gcd_lcm(1, 1), (1, 1));
    assert_eq!(gcd_lcm(100, 20), (20, 100));
    println!("gcd_lcm(48,18) = {:?}", gcd_lcm(48, 18));
    println!("all tests passed");
}
```
`NonZeroU64` makes the zero-input case explicit; `checked_mul` turns lcm overflow into a clear panic instead of silent wraparound.

```rust
fn reverse_words(s: &str) -> String {
    // Collect each word along with the run of whitespace preceding it.
    let mut out = String::with_capacity(s.len());
    let mut words: Vec<(usize, &str)> = Vec::new();
    let mut start = None;
    for (i, c) in s.char_indices() {
        if c.is_whitespace() {
            if let Some(st) = start.take() {
                words.push((st, &s[st..i]));
            }
        } else if start.is_none() {
            start = Some(i);
        }
    }
    if let Some(st) = start {
        words.push((st, &s[st..]));
    }

    // Rebuild: walk original, substituting words in reverse order.
    let mut wi = words.len();
    let mut i = 0;
    while i < s.len() {
        let c = s[i..].chars().next().unwrap();
        if c.is_whitespace() {
            let end = i + c.len_utf8();
            out.push_str(&s[i..end]);
            i = end;
        } else {
            wi -= 1;
            out.push_str(words[wi].1);
            i += words[wi].1.len();
        }
    }
    out
}

fn main() {
    assert_eq!(reverse_words("hello world"), "world hello");
    assert_eq!(reverse_words("  a  b   c "), "  c  b   a ");
    assert_eq!(reverse_words("one"), "one");
    assert_eq!(reverse_words(""), "");
    println!("{}", reverse_words("the quick  brown fox"));
}
```
Whitespace runs are copied byte-for-byte and only word slices are substituted, so spacing between words is preserved exactly.

```python
from typing import Any, Callable


def validate(config: Any, schema: dict) -> list[str]:
    """Validate config against {key: (type, required, predicate)} and return all errors."""
    errors: list[str] = []
    if not isinstance(config, dict):
        return [f"config must be a dict, got {type(config).__name__}"]

    for key, rule in schema.items():
        typ, required, pred = rule
        if key not in config:
            if required:
                errors.append(f"missing required key: {key}")
            continue
        value = config[key]
        if not isinstance(value, typ):
            errors.append(f"{key}: expected {typ.__name__}, got {type(value).__name__}")
            continue
        if pred is not None and not pred(value):
            errors.append(f"{key}: value {value!r} failed predicate")

    for key in config:
        if key not in schema:
            errors.append(f"unknown key: {key}")
    return errors


SCHEMA = {
    "host": (str, True, lambda v: len(v) > 0),
    "port": (int, True, lambda v: 1 <= v <= 65535),
    "workers": (int, False, lambda v: v > 0),
}

if __name__ == "__main__":
    good = {"host": "localhost", "port": 8080, "workers": 4}
    assert validate(good, SCHEMA) == []

    bad = {"host": "", "port": 70000, "extra": 1}
    for err in validate(bad, SCHEMA):
        print("error:", err)
    # Reports all three problems instead of stopping at the first.
    assert validate([], SCHEMA) == ["config must be a dict, got list"]
    assert validate({}, SCHEMA) == [
        "missing required key: host",
        "missing required key: port",
    ]
    print("all tests passed")
```
Collecting errors in a list instead of raising on the first one lets the caller fix everything in one pass; unknown keys are flagged too so typos don't slip through.

