#include <stdio.h>
#include <stdlib.h>

static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    size_t cap = 16, n = 0;
    int *data = malloc(cap * sizeof *data);
    if (!data) { perror("malloc"); return 1; }

    int value;
    while (scanf("%d", &value) == 1) {
        if (n == cap) {
            cap *= 2;
            int *tmp = realloc(data, cap * sizeof *data);
            if (!tmp) { perror("realloc"); free(data); return 1; }
            data = tmp;
        }
        data[n++] = value;
    }

    if (n == 0) {
        fprintf(stderr, "no integers on stdin\n");
        free(data);
        return 1;
    }

    qsort(data, n, sizeof *data, cmp_int);

    double median = (n % 2 == 1)
        ? (double)data[n / 2]
        : ((double)data[n / 2 - 1] + (double)data[n / 2]) / 2.0;

    printf("count=%zu min=%d max=%d median=%.1f\n",
           n, data[0], data[n - 1], median);

    free(data);
    return 0;
}
```
The comparator returns `(x > y) - (x < y)` to avoid `x - y` overflow. The median handles even counts by averaging the two middle values after sorting. Test with `printf '5 3 9 1\n' | ./sortstats`.

