/* Copy src into buf (size bytes), always NUL-terminating.
 * Returns 1 if fully copied, 0 if truncated. */
int safe_copy(char* buf, size_t size, const char* src) {
    if (buf == NULL || src == NULL || size == 0) {
        return 0;
    }
    size_t i = 0;
    while (i + 1 < size && src[i] != '\0') {
        buf[i] = src[i];
        i++;
    }
    buf[i] = '\0';
    return src[i] == '\0';
}

int main(void) {
    char buf[8];
    if (!safe_copy(buf, sizeof buf, "hi")) {
        printf("unexpected truncation\n");
        return 1;
    }
    if (strcmp(buf, "hi") != 0) {
        printf("bad copy\n");
        return 1;
    }
    char small[4];
    int ok = safe_copy(small, sizeof small, "hello");
    if (ok != 0 || strcmp(small, "hel") != 0) {
        printf("truncation handling wrong: %d %s\n", ok, small);
        return 1;
    }
    if (safe_copy(buf, 0, "x") != 0) {
        printf("zero-size must fail\n");
        return 1;
    }
    printf("ok\n");
    return 0;
}
