// lang: rust
use std::collections::{HashMap, VecDeque};

pub struct LruCache {
    cap: usize,
    map: HashMap<String, i64>,
    order: VecDeque<String>, // front = most recently used
}

impl LruCache {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be > 0");
        LruCache { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    fn touch(&mut self, key: &str) {
        self.order.retain(|k| k != key);
        self.order.push_front(key.to_string());
    }

    pub fn get(&mut self, key: &str) -> Option<i64> {
        let value = *self.map.get(key)?;
        self.touch(key);
        Some(value)
    }

    pub fn put(&mut self, key: &str, value: i64) {
        if self.map.contains_key(key) {
            self.map.insert(key.to_string(), value);
            self.touch(key);
            return;
        }
        if self.map.len() == self.cap {
            if let Some(evicted) = self.order.pop_back() {
                self.map.remove(&evicted);
            }
        }
        self.map.insert(key.to_string(), value);
        self.order.push_front(key.to_string());
    }

    pub fn len(&self) -> usize {
        self.map.len()
    }
}

#[cfg(test)]
mod tests {
    use super::LruCache;

    #[test]
    fn evicts_least_recently_used() {
        let mut c = LruCache::new(2);
        c.put("a", 1);
        c.put("b", 2);
        assert_eq!(c.get("a"), Some(1)); // 'a' now most recent
        c.put("c", 3);                    // should evict 'b'
        assert_eq!(c.get("b"), None);
        assert_eq!(c.get("a"), Some(1));
        assert_eq!(c.get("c"), Some(3));
        assert_eq!(c.len(), 2);
    }

    #[test]
    fn update_existing_key() {
        let mut c = LruCache::new(1);
        c.put("x", 10);
        c.put("x", 20);
        assert_eq!(c.get("x"), Some(20));
        assert_eq!(c.len(), 1);
    }
}
