#include <fstream>
#include <iostream>
#include <optional>
#include <string>
#include <vector>

struct Stats {
    long long minimum;
    long long maximum;
    double mean;
    size_t count;
};

std::optional<Stats> compute(const std::vector<long long>& nums) {
    if (nums.empty()) {
        return std::nullopt;
    }
    long long mn = nums[0];
    long long mx = nums[0];
    long long sum = 0;
    for (long long v : nums) {
        if (v < mn) mn = v;
        if (v > mx) mx = v;
        sum += v;
    }
    return Stats{mn, mx, static_cast<double>(sum) / static_cast<double>(nums.size()), nums.size()};
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "usage: " << argv[0] << " data.txt\n";
        return 2;
    }
    std::ifstream in(argv[1]);
    if (!in) {
        std::cerr << "cannot open " << argv[1] << "\n";
        return 1;
    }
    std::vector<long long> nums;
    long long v;
    while (in >> v) {
        nums.push_back(v);
    }
    auto stats = compute(nums);
    if (!stats) {
        std::cout << "no numbers found\n";
        return 0;
    }
    std::cout << "count=" << stats->count << " min=" << stats->minimum
              << " max=" << stats->maximum << " mean=" << stats->mean << "\n";
    return 0;
}
