#include <vector>
#include <algorithm>
#include <cstddef>

// Rotates an n x n matrix 90 degrees clockwise, in place.
// Works for n == 0 (empty vector) and n == 1.
void rotate90(std::vector<std::vector<int>>& m) {
    const std::size_t n = m.size();
    if (n < 2) return;  // 0x0 or 1x1 needs no work

    // Transpose.
    for (std::size_t i = 0; i < n; ++i)
        for (std::size_t j = i + 1; j < n; ++j)
            std::swap(m[i][j], m[j][i]);

    // Reverse each row.
    for (std::size_t i = 0; i < n; ++i)
        std::reverse(m[i].begin(), m[i].end());
}

// rotate90({{1,2,3},{4,5,6},{7,8,9}})
//  -> {{7,4,1},{8,5,2},{9,6,3}}
```

The two passes leave the matrix in the rotated orientation: transposing moves element (i, j) to (j, i), then reversing every row moves the column back into place. Both loops touch each element once, so it runs in O(n²) time and uses O(1) extra space.

```rust
/// Remove a line comment from C source, ignoring `//` that occurs inside a
/// double-quoted string literal (with backslash escapes).
fn strip_line_comment(line: &str) -> &str {
    let bytes = line.as_bytes();
    let mut in_string = false;
    let mut escaped = false;
    let mut i = 0;

    while i < bytes.len() {
        let b = bytes[i];
        if in_string {
            if escaped {
                escaped = false;
            } else if b == b'\\' {
                escaped = true;
            } else if b == b'"' {
                in_string = false;
            }
        } else if b == b'"' {
            in_string = true;
        } else if b == b'/' && i + 1 < bytes.len() && bytes[i + 1] == b'/' {
            return line[..i].trim_end();
        }
        i += 1;
    }
    line.trim_end()
}

fn main() {
    assert_eq!(strip_line_comment("int a = 1; // init"), "int a = 1;");
    assert_eq!(strip_line_comment(r#"char *s = "http://x";"#), r#"char *s = "http://x";"#);
    assert_eq!(strip_line_comment(r#"char *s = "a\\"; // end"#), r#"char *s = "a\\";"#);
    assert_eq!(strip_line_comment("int a = 1;"), "int a = 1;");
    println!("ok");
}
```

The scan keeps an `in_string` state so a `//` can only terminate the line when the scanner is outside quotes. Backslash escapes are tracked so `\"` does not close the string early. The returned slice borrows from the input, avoiding an allocation, and `trim_end` drops trailing whitespace before the comment.

```c
#include <stdbool.h>
#include <limits.h>

/* Parse a signed decimal integer from `s`.
 * Skips leading whitespace, requires at least one digit, rejects
 * non-digit trailing characters and values outside [INT_MIN, INT_MAX].
 * On success writes the value to *out and returns true. */
bool parse_int(const char *s, int *out) {
    if (s == NULL || out == NULL) return false;

    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;

    bool negative = false;
    if (*s == '+' || *s == '-') {
        negative = (*s == '-');
        s++;
    }
    if (*s < '0' || *s > '9') return false;

    long acc = 0;
    while (*s >= '0' && *s <= '9') {
        acc = acc * 10 + (*s - '0');
        if (negative ? -acc < INT_MIN : acc > INT_MAX) return false;
        s++;
    }
    if (*s != '\0') return false;

    *out = (int)(negative ? -acc : acc);
    return true;
}
```

The accumulator is `long` so a running value can be range-checked after each digit before it is stored into an `int`. An empty sign-only input like `"-"` fails the first digit test, `"12x"` fails the trailing-character check, and `"-2147483649"` trips the negative bound before overflowing. Leading whitespace is consumed explicitly so `" -5 "` (with the usual `\0` terminator) is rejected on the trailing space.

```python
from collections import deque
from typing import Optional

Graph = dict[str, list[str]]

def shortest_path(graph: Graph, start: str, goal: str) -> Optional[list[str]]:
    """Return the shortest path start -> goal as a list of nodes, else None."""
    if start not in graph or goal not in graph:
        return None
    if start == goal:
        return [start]

    parent: dict[str, Optional[str]] = {start: None}
    queue: deque[str] = deque([start])

    while queue:
        node = queue.popleft()
        for nxt in graph[node]:
            if nxt in parent:
                continue
            parent[nxt] = node
            if nxt == goal:
                return _reconstruct(parent, goal)
            queue.append(nxt)

    return None

def _reconstruct(parent: dict[str, Optional[str]], goal: str) -> list[str]:
    path: list[str] = []
    cur: Optional[str] = goal
    while cur is not None:
        path.append(cur)
        cur = parent[cur]
    path.reverse()
    return path


if __name__ == "__main__":
    g = {"a": ["b", "c"], "b": ["d"], "c": ["d"], "d": ["e"], "e": []}
    assert shortest_path(g, "a", "e") == ["a", "b", "d", "e"]
    assert shortest_path(g, "a", "a") == ["a"]
    assert shortest_path(g, "e", "a") is None
```

BFS explores by hop count, so the first time the goal is dequeued its recorded parent chain is a shortest path. Marking a node visited on discovery (via the `parent` dict) means each edge is examined once, giving O(V + E) time. The early `start == goal` return avoids an empty-path ambiguity, and missing nodes answer `None` rather than raising.

```rust
use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let workers = 4usize;
    let per_worker = 25_000usize;

    let counter = Arc::new(Mutex::new(0usize));
    let mut handles = Vec::with_capacity(workers);

    for _ in 0..workers {
        let shared = Arc::clone(&counter);
        handles.push(thread::spawn(move || {
            for _ in 0..per_worker {
                let mut guard = shared.lock().unwrap();
                *guard += 1;
                // guard drops here, releasing the lock each iteration
            }
        }));
    }

    for h in handles {
        h.join().expect("worker thread panicked");
    }

    let total = *counter.lock().unwrap();
    assert_eq!(total, workers * per_worker);
    println!("{total}");
}
```

`Arc` gives all threads shared ownership of the same allocation and `Mutex` serialises the increments, so no update is lost. Taking the lock in a short scope (letting the guard drop at the end of each loop body) keeps contention bounded. A poisoned lock would surface as a panic on `unwrap`, which is the right default here rather than silently reusing a possibly-inconsistent value.

```cpp
#include <vector>
#include <cstddef>
#include <iostream>

// Returns the index of the first element >= key, or container.size() if none.
template <typename T>
std::size_t lower_bound_index(const std::vector<T>& data, const T& key) {
    std::size_t lo = 0, hi = data.size();  // invariant: answer in [lo, hi]
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;  // no overflow
        if (data[mid] < key)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;
}

int main() {
    std::vector<int> v{1, 2, 4, 4, 4, 7, 9};
    assert(lower_bound_index(v, 4) == 2);
    assert(lower_bound_index(v, 0) == 0);
    assert(lower_bound_index(v, 5) == 5);
    assert(lower_bound_index(v, 100) == v.size());
    std::cout << "ok\n";
}
```

The half-open interval `[lo, hi)` shrinks until it holds exactly one candidate, so the loop always terminates and `lo` is the lower bound. Computing `mid` as `lo + (hi - lo) / 2` avoids the overflow that `(lo + hi) / 2` can hit on large vectors. The empty-vector case falls straight through and returns `0`, which equals `size()`.

```python
import re

_LOCAL = re.compile(r"^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*$")
_LABEL = re.compile(r"^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$")

def normalize_email(raw: str) -> str:
    """Lowercase and validate an email address.

    Raises ValueError with a reason on bad input.
    """
    if not isinstance(raw, str):
        raise ValueError("email must be a string")
    addr = raw.strip()
    if addr.count("@") != 1:
        raise ValueError(f"expected exactly one '@' in {raw!r}")

    local, _, domain = addr.partition("@")
    if not local or not _LOCAL.match(local):
        raise ValueError(f"invalid local part {local!r}")
    if len(local) > 64:
        raise ValueError("local part exceeds 64 characters")

    labels = domain.split(".")
    if len(labels) < 2 or any(not _LABEL.match(l) for l in labels):
        raise ValueError(f"invalid domain {domain!r}")
    if len(domain) > 255:
        raise ValueError("domain exceeds 255 characters")

    return f"{local.lower()}@{domain.lower()}"


if __name__ == "__main__":
    assert normalize_email("  Alice@Example.COM ") == "alice@example.com"
    for bad in ["no-at-sign", "a@@b.com", "a@b", "a@-bad.com", "a b@c.com"]:
        try:
            normalize_email(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"accepted bad address {bad!r}")
```

The local part is checked against the RFC 5322 atom set with dot-separated segments, and the domain is split into labels each of which must start and end alphanumerically. Requiring at least two labels enforces the dot while still allowing subdomains. Only the local part and domain are lowercased, so the structural validation runs on the original casing.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

/* Reverse the list whose head is *head, in place, and return the new head. */
Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;  /* save before rewiring */
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

Node *push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (n == NULL) { fprintf(stderr, "out of memory\n"); exit(1); }
    n->value = value;
    n->next = head;
    return n;
}

void print(const Node *head) {
    for (const Node *n = head; n != NULL; n = n->next)
        printf("%d%s", n->value, n->next ? " -> " : "\n");
    if (head == NULL) printf("\n");
}

int main(void) {
    print(NULL);              /* empty list prints a blank line */

    Node *list = NULL;
    for (int i = 1; i <= 4; i++) list = push(list, i);
    print(list);              /* 4 -> 3 -> 2 -> 1 */

    list = reverse(list);
    print(list);              /* 1 -> 2 -> 3 -> 4 */

    while (list != NULL) {
        Node *next = list->next;
        free(list);
        list = next;
    }
    return 0;
}
```

The reversal keeps three pointers (`prev`, `cur`, `next`) so the successor is saved before `cur->next` is overwritten; each node is visited exactly once, giving O(n) time and O(1) extra space. An empty list enters the loop zero times and returns `NULL`, so the head stays valid. The trailing free loop walks the reversed list safely by caching `next` before freeing.

