std::string to_binary(std::int64_t value) {
    if (value == 0) return "0";
    bool negative = value < 0;
    std::uint64_t magnitude =
        negative ? static_cast<std::uint64_t>(-(value + 1)) + 1
                 : static_cast<std::uint64_t>(value);
    std::string bits;
    while (magnitude > 0) {
        bits.push_back('0' + static_cast<char>(magnitude & 1u));
        magnitude >>= 1;
    }
    if (negative) bits.push_back('-');
    return std::string(bits.rbegin(), bits.rend());
}

int main() {
    std::int64_t inputs[] = {0, 1, 5, 255, -42};
    for (std::int64_t v : inputs) {
        std::cout << v << " -> " << to_binary(v) << '\n';
    }
    return 0;
}
