```rust
fn eval_rpn(expr: &str) -> Result<f64, String> {
    let mut stack: Vec<f64> = Vec::new();
    for token in expr.split_whitespace() {
        match token {
            "+" | "-" | "*" | "/" => {
                let b = stack.pop().ok_or_else(|| format!("missing operand for {token}"))?;
                let a = stack.pop().ok_or_else(|| format!("missing operand for {token}"))?;
                let value = match token {
                    "+" => a + b,
                    "-" => a - b,
                    "*" => a * b,
                    _ => {
                        if b == 0.0 {
                            return Err("division by zero".to_string());
                        }
                        a / b
                    }
                };
                stack.push(value);
            }
            _ => {
                let n: f64 = token.parse().map_err(|_| format!("bad token {token}"))?;
                stack.push(n);
            }
        }
    }
    if stack.len() != 1 {
        return Err(format!("malformed expression, {} values left", stack.len()));
    }
    Ok(stack[0])
}

fn main() {
    assert_eq!(eval_rpn("3 4 + 2 *"), Ok(14.0));
    assert_eq!(eval_rpn("5 1 2 + 4 * + 3 -"), Ok(14.0));
    assert!(eval_rpn("1 0 /").is_err());
    assert!(eval_rpn("1 +").is_err());
    println!("{:?}", eval_rpn("8 2 /"));
}
```

Every error path returns a message instead of panicking: missing operands, unknown tokens, division by zero, and leftover values. `5 1 2 + 4 * + 3 -` evaluates to 14 via the standard RPN order.

