```cpp
#include <array>
#include <cstddef>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

#include <cassert>
#include <iostream>

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.empty());
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.full());
    assert(!rb.push(4));
    assert(rb.pop() == 1);
    assert(rb.pop() == 2);
    assert(rb.push(4));
    assert(rb.pop() == 3);
    assert(rb.pop() == 4);
    assert(rb.empty());
    assert(!rb.pop().has_value());
    std::cout << "ok\n";
}
```
The buffer wraps with modular indices and tracks `count_` separately so full and empty are distinguishable. `std::optional` carries the pop-failure case without exceptions.

