fn two_largest<T: Ord + Copy>(items: &[T]) -> Option<(T, T)> {
    let mut first: Option<T> = None;
    let mut second: Option<T> = None;

    for &item in items {
        if first.map_or(true, |f| item > f) {
            second = first;
            first = Some(item);
        } else if item < first.unwrap() && second.map_or(true, |s| item > s) {
            second = Some(item);
        }
    }

    match (first, second) {
        (Some(a), Some(b)) => Some((a, b)),
        _ => None,
    }
}

fn main() {
    assert_eq!(two_largest(&[3, 1, 4, 1, 5, 9, 2, 6]), Some((9, 6)));
    assert_eq!(two_largest(&[7, 7, 7]), None);        // no distinct second
    assert_eq!(two_largest(&[5, 5, 3]), Some((5, 3)));
    assert_eq!(two_largest::<i32>(&[]), None);
    assert_eq!(two_largest(&[2, 1]), Some((2, 1)));
    println!("ok");
}
```
The strict branch `item < first.unwrap()` skips equal-to-max values, so duplicates of the maximum do not count as the distinct second. All comparisons are `Ord`-based, so it works for any orderable type.

