template <std::size_t N>
class RingBuffer {
    std::array<int, N> buf{};
    std::size_t head = 0;
    std::size_t size = 0;
public:
    void push(int v) {
        buf[(head + size) % N] = v;
        if (size < N) ++size;
        else head = (head + 1) % N;
    }
    int operator[](std::size_t i) const { return buf[(head + i) % N]; }
    std::size_t count() const { return size; }
};

