```cpp
#include <iostream>
#include <vector>

template <typename T>
int binary_search(const std::vector<T>& xs, const T& target) {
    int lo = 0;
    int hi = static_cast<int>(xs.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (xs[mid] == target) return mid;
        if (xs[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> xs{1, 3, 5, 7, 9, 11};
    std::cout << binary_search(xs, 7) << "\n";   // 3
    std::cout << binary_search(xs, 4) << "\n";   // -1
    std::cout << binary_search(xs, 1) << "\n";   // 0
    std::vector<int> empty;
    std::cout << binary_search(empty, 5) << "\n"; // -1
    return 0;
}
```

`mid = lo + (hi - lo) / 2` avoids overflow that `(lo + hi) / 2` would hit on large indices. Empty vectors give `hi = -1`, so the loop is skipped and it returns `-1` cleanly.

