```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* Returns true and writes *out on success; false on overflow. */
bool fib(uint64_t n, uint64_t *out) {
    uint64_t a = 0, b = 1;
    for (uint64_t i = 0; i < n; i++) {
        if (a > UINT64_MAX - b) return false; /* a + b would overflow */
        uint64_t next = a + b;
        a = b;
        b = next;
    }
    *out = a;
    return true;
}

int main(void) {
    uint64_t v;
    for (uint64_t n = 0; n <= 10; n++) {
        if (fib(n, &v)) printf("fib(%llu) = %llu\n", (unsigned long long)n, (unsigned long long)v);
    }
    if (!fib(100, &v)) printf("fib(100) overflows uint64_t\n");
    return 0;
}
```

`a + b` is checked against `UINT64_MAX` before it wraps, so the function reports overflow instead of returning a wrong number. Iteration is O(n) time and O(1) space, and `n = 0` correctly yields 0.

