#include <iostream>
#include <vector>

template <typename T>
std::vector<T> merge_sorted(const std::vector<T>& a, const std::vector<T>& b) {
    std::vector<T> out;
    out.reserve(a.size() + b.size());
    size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 4, 7, 10};
    std::vector<int> b{2, 3, 7, 9, 12};
    for (int x : merge_sorted(a, b)) std::cout << x << ' ';
    std::cout << '\n';
    for (int x : merge_sorted<int>({}, {})) std::cout << x << ' ';
    std::cout << '\n';
    return 0;
}
```

The `<=` on ties keeps equal elements in a stable order, the two tail loops drain whichever input is left, and empty vectors produce an empty result. `reserve` avoids reallocation while pushing.

