from collections import OrderedDict


def parse_ini(text: str) -> "OrderedDict[str, OrderedDict[str, str]]":
    result = OrderedDict()
    current = None

    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith('#') or line.startswith(';'):
            continue
        line = _strip_inline_comment(line)
        if line.startswith('[') and line.endswith(']'):
            name = line[1:-1]
            if not name:
                raise ValueError(f"empty section name on line {lineno}")
            current = result.setdefault(name, OrderedDict())
        else:
            if '=' not in line:
                raise ValueError(f"expected key=value on line {lineno}")
            key, _, value = line.partition('=')
            key, value = key.strip(), value.strip()
            if current is None:
                raise ValueError(f"key outside any section on line {lineno}")
            current[key] = value

    return result


def _strip_inline_comment(line: str) -> str:
    quote = None
    for i, ch in enumerate(line):
        if quote:
            if ch == quote:
                quote = None
        elif ch in "'\"":
            quote = ch
        elif ch == '#':
            return line[:i].rstrip()
    return line


if __name__ == "__main__":
    cfg = parse_ini("""
# global
[server]
host = 127.0.0.1  # loopback
port = 8080

[paths]
root = /srv/app
""")
    assert list(cfg.keys()) == ["server", "paths"]
    assert cfg["server"]["host"] == "127.0.0.1"
    assert cfg["server"]["port"] == "8080"
    print("ok")
