        } else if (high.size() > low.size()) {
            low.push(high.top()); high.pop();
        }

        long long median = (low.size() == high.size())
            ? (static_cast<long long>(low.top()) + high.top()) / 2
            : low.top();
        std::cout << median << '\n';
    }
    return 0;
}
```
Both heaps keep every element of `low` ≤ every element of `high`. When the counts are equal the median is the truncated average of the two tops, otherwise it is `low.top()`. Input like `1 5 2 9` prints `1 3 2 3`; an empty stream prints nothing.

```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[]), vec![1, 3, 5]);
    assert_eq!(merge_sorted(&[], &[2, 4]), vec![2, 4]);
    assert_eq!(merge_sorted(&[1, 2, 2], &[2, 3]), vec![1, 2, 2, 2, 3]);
    assert_eq!(merge_sorted(&[-5, 0], &[-3, 9]), vec![-5, -3, 0, 9]);
    println!("ok");
}
```
The `<=` keeps equal elements stable from `a` first. `extend_from_slice` drains whichever slice has leftovers, so empty inputs are handled without special cases.

```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXW 4096
#define WLEN 64

typedef struct { char word[WLEN]; int count; } Entry;

static int cmp(const void *a, const void *b) {
    const Entry *x = a, *y = b;
    if (x->count != y->count) return y->count - x->count;
    return strcmp(x->word, y->word);
}

int main(int argc, char **argv) {
    if (argc != 2) { fprintf(stderr, "usage: %s <file>\n", argv[0]); return 2; }
    FILE *fp = fopen(argv[1], "r");
    if (!fp) { perror("fopen"); return 1; }

    Entry *table = calloc(MAXW, sizeof(Entry));
    if (!table) { fclose(fp); return 1; }
    int n = 0;
    char word[WLEN];
    int c, len = 0;

    while ((c = fgetc(fp)) != EOF) {
        if (isalpha((unsigned char)c) || c == '\'') {
            if (len < WLEN - 1) word[len++] = (char)tolower((unsigned char)c);
        } else if (len > 0) {
            word[len] = '\0';
            int found = 0;
            for (int i = 0; i < n; i++)
                if (strcmp(table[i].word, word) == 0) { table[i].count++; found = 1; break; }
            if (!found && n < MAXW) {
                strcpy(table[n].word, word);
                table[n].count = 1;
                n++;
            }
            len = 0;
        }
    }
    fclose(fp);

    qsort(table, (size_t)n, sizeof(Entry), cmp);
    int top = n < 5 ? n : 5;
    for (int i = 0; i < top; i++)
        printf("%s %d\n", table[i].word, table[i].count);
    free(table);
    return 0;
}
```
`cmp` sorts by descending count then ascending word, so ties break alphabetically. `isalpha` takes an `unsigned char` to avoid undefined behaviour on bytes ≥ 128, and `tolower` folds case. Compile with `gcc -O2 -Wall -o wf wf.c`.

