#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

struct EmptyRange : std::runtime_error {
    EmptyRange() : std::runtime_error("max_of: empty range") {}
};

template <typename T>
const T& max_of(const std::vector<T>& values) {
    if (values.empty()) {
        throw EmptyRange();
    }
    const T* best = &values[0];
    for (const T& v : values) {
        if (v > *best) best = &v;
    }
    return *best;
}

int main() {
    std::vector<int> nums{3, 7, 2, 7, -1};
    std::cout << max_of(nums) << '\n';              // 7
    std::vector<std::string> words{"pear", "apple", "fig"};
    std::cout << max_of(words) << '\n';             // pear
    std::vector<int> empty;
    try {
        max_of(empty);
        std::cout << "should not reach\n";
    } catch (const EmptyRange& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
```
`max_of` returns a const reference into the caller's vector, so the vector must outlive the result — that is why it takes `const std::vector<T>&` rather than returning by value. It works for any `T` with `operator>`, including `std::string`.

