```c
#include <stdio.h>

int main(void) {
    int c, prev = 0;
    int in_string = 0, in_char = 0, in_line = 0, in_block = 0, escaped = 0;

    while ((c = getchar()) != EOF) {
        if (in_line) {
            if (c == '\n') {
                in_line = 0;
                putchar(c);
            }
            prev = c;
            continue;
        }
        if (in_block) {
            if (prev == '*' && c == '/') {
                in_block = 0;
                prev = 0;
                continue;
            }
            prev = c;
            continue;
        }
        if (!in_string && !in_char && prev == '/' && c == '/') {
            in_line = 1;
            prev = c;
            continue;
        }
        if (!in_string && !in_char && prev == '/' && c == '*') {
            in_block = 1;
            prev = c;
            continue;
        }
        if (escaped) {
            escaped = 0;
        } else if (c == '\\' && (in_string || in_char)) {
            escaped = 1;
        } else if (in_string && c == '"') {
            in_string = 0;
        } else if (in_char && c == '\'') {
            in_char = 0;
        } else if (!in_string && !in_char && c == '"') {
            in_string = 1;
        } else if (!in_string && !in_char && c == '\'') {
            in_char = 1;
        }
        if (prev == '/' && (c == '/' || c == '*')) {
            prev = c;
            continue;
        }
        if (prev != 0) putchar(prev);
        prev = c;
    }
    if (prev != 0) putchar(prev);
    return 0;
}
```
It tracks string and character literals and escape sequences, so `"http://x"` is preserved while real comments are removed.

