pub fn search(sorted: &[i32], target: i32) -> Result<usize, usize> {
    let mut lo = 0usize;
    let mut hi = sorted.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match sorted[mid].cmp(&target) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Ok(mid),
        }
    }
    Err(lo)
}

fn main() {
    let data = [1, 3, 5, 7, 9];
    assert_eq!(search(&data, 5), Ok(2));
    assert_eq!(search(&data, 4), Err(2));
    assert_eq!(search(&data, 0), Err(0));
    assert_eq!(search(&data, 10), Err(5));
    assert_eq!(search(&[], 1), Err(0));
    println!("ok");
}
```
The `lo + (hi - lo) / 2` form avoids overflow on large indices, and the error carries the insertion point.

