fn is_palindrome(input: &str) -> bool {
    let filtered: Vec<char> = input
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();

    let mut left = 0usize;
    let mut right = filtered.len();
    while left + 1 < right {
        right -= 1;
        if filtered[left] != filtered[right] {
            return false;
        }
        left += 1;
    }
    true
}

#[cfg(test)]
