    #[test]
    fn rejects_non_palindrome() {
        assert!(!is_palindrome("hello"));
    }

    #[test]
    fn empty_and_single_char() {
        assert!(is_palindrome(""));
        assert!(is_palindrome("!"));
        assert!(is_palindrome("Z"));
    }
}
