```cpp
#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    Node* curr = head;
    while (curr != nullptr) {
        Node* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

void release(Node* head) {
    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    Node* head = nullptr;
    for (int v : {1, 2, 3, 4}) {
        head = new Node(v) == nullptr ? head : head;
    }
    // Build explicitly to keep ownership clear.
    release(head);

    Node* chain = new Node(1);
    chain->next = new Node(2);
    chain->next->next = new Node(3);
    chain = reverse(chain);
    for (Node* p = chain; p != nullptr; p = p->next) {
        std::cout << p->value << ' ';
    }
    std::cout << '\n';
    release(chain);
    return 0;
}
```

The three-pointer loop rewires `next` links one node at a time; on an empty list it returns `nullptr` unchanged. Every `new` is matched by `release` so the demo does not leak.

