    }

    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] == '\n') {
        buf[--len] = '\0';
    }

    size_t i = 0;
    size_t j = len;
    while (i + 1 < j) {
        j--;
        char tmp = buf[i];
        buf[i] = buf[j];
        buf[j] = tmp;
        i++;
    }

    puts(buf);
    return 0;
}
```

`fgets` may leave a newline; we strip it before reversing so the newline does not move to the front. The `i + 1 < j` guard avoids swapping the middle character with itself and handles empty lines safely.

```python
import os
import sys

UNITS = ["B", "KiB", "MiB", "GiB", "TiB"]


def human_size(num_bytes):
    size = float(num_bytes)
    for unit in UNITS:
        if size < 1024.0 or unit == UNITS[-1]:
            if unit == "B":
                return f"{int(size)} {unit}"
            return f"{size:.1f} {unit}"
        size /= 1024.0


def main(root):
    if not os.path.isdir(root):
        print(f"error: '{root}' is not a directory", file=sys.stderr)
        return 1
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort()
        for name in sorted(filenames):
            full = os.path.join(dirpath, name)
            try:
                size = os.path.getsize(full)
            except OSError as exc:
                print(f"{full}\t(unreadable: {exc.strerror})")
                continue
            print(f"{human_size(size)}\t{full}")
    return 0


if __name__ == "__main__":
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    raise SystemExit(main(target))
```

`os.path.getsize` is wrapped so a broken symlink or permission error reports per-file instead of crashing the walk. Sorting `dirnames` and `filenames` keeps output deterministic across filesystems.

```python
def canonicalize(path: str) -> str:
    if not path:
        return "."
    parts = path.split("/")
    stack: list[str] = []
    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            elif not path.startswith("/"):
                stack.append("..")
        else:
            stack.append(part)
    result = "/".join(stack)
    if path.startswith("/"):
        return "/" + result if result else "/"
    return result or "."


if __name__ == "__main__":
    assert canonicalize("/a/b/../c//d/") == "/a/c/d"
    assert canonicalize("a/./b/../../c") == "../c"
    assert canonicalize("/..") == "/"
    assert canonicalize("../../a") == "../../a"
    assert canonicalize("") == "."
    assert canonicalize("/") == "/"
    print("ok")
```

Stack-based, no `os.path` and no I/O. Leading `..` in relative paths is preserved; absolute paths can never escape root.

