std::size_t count_words(const std::string& s) {
    std::size_t count = 0;
    bool in_word = false;
    for (unsigned char c : s) {
        // Bytes >= 0x80 are UTF-8 continuation/lead bytes: part of a word.
        bool space = c < 0x80 && std::isspace(c);
        if (space) {
            in_word = false;
        } else if (!in_word) {
            in_word = true;
            ++count;
        }
    }
    return count;
}

