    assert(count_words("   \t\n") == 0);
    assert(count_words("hello world") == 2);
    assert(count_words("  one   two  three ") == 3);
    assert(count_words("caf\xC3\xA9 au lait") == 3);
    std::cout << "ok\n";
    return 0;
}
