```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <optional>

 template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(!rb.push(4));            // full, rejected
    assert(rb.pop() == 1);
    assert(rb.push(4));             // slot reused
    assert(rb.pop() == 2 && rb.pop() == 3 && rb.pop() == 4);
    assert(rb.pop() == std::nullopt);
    assert(rb.size() == 0);
    return 0;
}
```

Wraparound uses modulo on a fixed `std::array`. Full pushes fail rather than overwrite; empty pops return `std::nullopt`. Compile with `g++ -std=c++17 -Wall -Wextra`.

```rust
use std::collections::HashMap;

struct Node<K, V> {
    key: K,
    value: V,
    prev: Option<usize>,
    next: Option<usize>,
}

pub struct LruCache<K, V> {
    map: HashMap<K, usize>,
    nodes: Vec<Node<K, V>>,
    cap: usize,
    head: Option<usize>,
    tail: Option<usize>,
}

impl<K: std::hash::Hash + Eq + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        LruCache { map: HashMap::new(), nodes: Vec::new(), cap, head: None, tail: None }
    }

    fn detach(&mut self, idx: usize) {
        let (prev, next) = (self.nodes[idx].prev, self.nodes[idx].next);
        match prev { Some(p) => self.nodes[p].next = next, None => self.head = next }
        match next { Some(n) => self.nodes[n].prev = prev, None => self.tail = prev }
    }

    fn push_front(&mut self, idx: usize) {
        self.nodes[idx].prev = None;
        self.nodes[idx].next = self.head;
        if let Some(h) = self.head { self.nodes[h].prev = Some(idx); }
        self.head = Some(idx);
        if self.tail.is_none() { self.tail = Some(idx); }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        let idx = *self.map.get(key)?;
        self.detach(idx);
        self.push_front(idx);
        Some(&self.nodes[idx].value)
    }

    pub fn put(&mut self, key: K, value: V) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].value = value;
            self.detach(idx);
            self.push_front(idx);
            return;
        }
        if self.nodes.len() == self.cap {
            if let Some(t) = self.tail {
                let old = self.nodes[t].key.clone();
                self.map.remove(&old);
            }
        }
        self.nodes.push(Node { key: key.clone(), value, prev: None, next: None });
        let idx = self.nodes.len() - 1;
        self.map.insert(key, idx);
        self.push_front(idx);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn evicts_least_recently_used() {
        let mut c = LruCache::new(2);
        c.put(1, "a");
        c.put(2, "b");
        assert_eq!(c.get(&1), Some(&"a"));
        c.put(3, "c");
        assert_eq!(c.get(&2), None);
        assert_eq!(c.get(&1), Some(&"a"));
        assert_eq!(c.get(&3), Some(&"c"));
    }

    #[test]
    fn updates_in_place() {
        let mut c = LruCache::new(2);
        c.put(1, "a");
        c.put(1, "z");
        assert_eq!(c.get(&1), Some(&"z"));
    }
}
