```rust
use std::collections::HashMap;

pub struct LruCache {
    cap: usize,
    map: HashMap<String, i64>,
    order: Vec<String>,
}

impl LruCache {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        Self { cap, map: HashMap::new(), order: Vec::new() }
    }

    pub fn get(&mut self, key: &str) -> Option<i64> {
        let value = *self.map.get(key)?;
        self.order.retain(|k| k != key);
        self.order.push(key.to_string());
        Some(value)
    }

    pub fn put(&mut self, key: &str, value: i64) {
        if self.map.insert(key.to_string(), value).is_none() {
            self.order.push(key.to_string());
        } else {
            self.order.retain(|k| k != key);
            self.order.push(key.to_string());
        }
        while self.order.len() > self.cap {
            let evicted = self.order.remove(0);
            self.map.remove(&evicted);
        }
    }

    pub fn len(&self) -> usize { self.map.len() }
}

#[cfg(test)]
mod tests {
    use super::LruCache;

    #[test]
    fn evicts_least_recently_used() {
        let mut cache = LruCache::new(2);
        cache.put("a", 1);
        cache.put("b", 2);
        assert_eq!(cache.get("a"), Some(1)); // a is now most recent
        cache.put("c", 3);                  // b is least recent -> evicted
        assert_eq!(cache.get("b"), None);
        assert_eq!(cache.get("a"), Some(1));
        assert_eq!(cache.get("c"), Some(3));
        assert_eq!(cache.len(), 2);
    }
}
```
`get` refreshes recency by moving the key to the back of `order`; `put` evicts from the front until the capacity holds.

