#include <iostream>
#include <optional>
#include <stdexcept>

// Returns std::nullopt when the divisor is zero instead of aborting.
template <typename T>
std::optional<T> safe_div(T numerator, T divisor) {
    if (divisor == T{0}) {
        return std::nullopt;
    }
    return numerator / divisor;
}

int main() {
    if (auto r = safe_div(10, 2)) {
        std::cout << "10 / 2 = " << *r << '\n';
    } else {
        std::cout << "division by zero\n";
    }

    if (auto r = safe_div(1, 0)) {
        std::cout << "unexpected: " << *r << '\n';
    } else {
        std::cout << "1 / 0 refused\n";
    }

    // Integer truncation is preserved for integral types.
    if (auto r = safe_div(7, 2)) {
        std::cout << "7 / 2 = " << *r << " (integer division)\n";
    }
    return 0;
}
```
The zero check is done before the division, so no floating-point `inf` and no undefined behaviour for integers.

