#include <algorithm>
#include <iostream>
#include <vector>

template <typename T>
std::vector<T> merge_sorted(const std::vector<T>& a, const std::vector<T>& b) {
    std::vector<T> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (b[j] < a[i]) {
            out.push_back(b[j++]);
        } else {
            out.push_back(a[i++]);
        }
    }
    out.insert(out.end(), a.begin() + static_cast<std::ptrdiff_t>(i), a.end());
    out.insert(out.end(), b.begin() + static_cast<std::ptrdiff_t>(j), b.end());
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5, 7};
    std::vector<int> b{2, 4, 6};
    for (int v : merge_sorted(a, b)) std::cout << v << ' ';
    std::cout << '\n';

    std::vector<int> c{};
    std::vector<int> d{9};
    for (int v : merge_sorted(c, d)) std::cout << v << ' ';
    std::cout << '\n';
    return 0;
}
```
The `reserve` sizes the result once, so no reallocation happens during the merge. Unequal lengths are handled by the tail inserts.

```c
#include <stdio.h>
#include <stdint.h>
#include <limits.h>
#include <stdbool.h>

/* Reverse the decimal digits of a signed 64-bit integer.
 * Returns false on overflow instead of silently wrapping. */
static bool reverse_i64(int64_t value, int64_t *out)
{
    int64_t result = 0;

    while (value != 0) {
        int64_t digit = value % 10;
        value /= 10;

        if (result > INT64_MAX / 10 ||
            (result == INT64_MAX / 10 && digit > INT64_MAX % 10))
            return false;
        result = result * 10 + digit;
    }

    *out = result;
    return true;
}

int main(void)
{
    const int64_t inputs[] = {12345, -9876, 0, 1000, 1463847412};
    const size_t n = sizeof(inputs) / sizeof(inputs[0]);

    for (size_t i = 0; i < n; ++i) {
        int64_t reversed = 0;
        if (reverse_i64(inputs[i], &reversed))
            printf("%lld -> %lld\n", (long long)inputs[i], (long long)reversed);
        else
            printf("%lld -> overflow\n", (long long)inputs[i]);
    }
    return 0;
}
```
Each digit is peeled off with `% 10` and `/= 10`, then appended with `result * 10 + digit`. Before that multiply, the function checks `INT64_MAX / 10` and the final digit so values that would overflow are reported as `overflow` rather than wrapping.

