```rust
/// Return the nth Fibonacci number (F(0) = 0, F(1) = 1) iteratively.
fn fib(n: u32) -> u128 {
    let (mut a, mut b) = (0u128, 1u128);
    for _ in 0..n {
        let next = a.checked_add(b).expect("fibonacci overflowed u128");
        a = b;
        b = next;
    }
    a
}

fn main() {
    let values: Vec<u128> = (0..20).map(fib).collect();
    for (i, value) in values.iter().enumerate() {
        println!("fib({i}) = {value}");
    }
}
```
