```cpp
#include <iostream>
#include <list>
#include <optional>
#include <stdexcept>
#include <unordered_map>
#include <utility>

class LruCache {
public:
    explicit LruCache(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    std::optional<int> get(int key) {
        auto it = index_.find(key);
        if (it == index_.end()) return std::nullopt;
        items_.splice(items_.begin(), items_, it->second); // move to front
        return it->second->second;
    }

    void put(int key, int value) {
        auto it = index_.find(key);
        if (it != index_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (items_.size() == capacity_) {
            index_.erase(items_.back().first);
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        index_[key] = items_.begin();
    }

private:
    std::size_t capacity_;
    std::list<std::pair<int, int>> items_;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> index_;
};

int main() {
    LruCache cache(2);
    cache.put(1, 10);
    cache.put(2, 20);
    std::cout << "get 1: " << (cache.get(1) ? "hit" : "miss") << '\n';
    cache.put(3, 30); // evicts key 2
    std::cout << "get 2: " << (cache.get(2) ? "hit" : "miss") << '\n';
    std::cout << "get 3: " << (cache.get(3).value_or(-1)) << '\n';
    return 0;
}
```
The list holds entries most-recent-first and the map points into it, so `splice` moves a hit to the front in O(1) without copying. Eviction pops the tail and erases its key from the map; `get` returns `std::nullopt` on a miss.

