#include <stdbool.h>

bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;
    errno = 0;
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (errno == ERANGE || v < INT_MIN || v > INT_MAX) return false;
    if (end == s || *end != '\0') return false;
    *out = (int)v;
    return true;
}

int main(void) {
    int v;
    if (parse_int(" -42 ", &v)) { /* trailing space makes this fail */
        printf("unexpected\n");
    }
    if (parse_int("-42", &v)) printf("%d\n", v);
    if (parse_int("2147483648", &v)) printf("unexpected\n");
    if (parse_int("12x", &v)) printf("unexpected\n");
    if (!parse_int("", &v)) printf("rejected empty\n");
    return 0;
}
