#include <iostream>
#include <unordered_map>

// Compile-time Fibonacci (C++11 friendly).
template <int N>
struct Fib {
    static constexpr long long value = Fib<N - 1>::value + Fib<N - 2>::value;
};
template <> struct Fib<0> { static constexpr long long value = 0; };
template <> struct Fib<1> { static constexpr long long value = 1; };

// Runtime Fibonacci with memoization.
long long fib_memo(int n, std::unordered_map<int, long long>& memo) {
    if (n < 2) return n;
    auto it = memo.find(n);
    if (it != memo.end()) return it->second;
    long long v = fib_memo(n - 1, memo) + fib_memo(n - 2, memo);
    memo[n] = v;
    return v;
}

int main() {
    static_assert(Fib<10>::value == 55, "fib(10) should be 55");
    std::unordered_map<int, long long> memo;
    std::cout << Fib<10>::value << '\n';
    std::cout << fib_memo(50, memo) << '\n';
    return 0;
}
