use std::collections::VecDeque;

pub struct RingBuffer {
    buf: VecDeque<u32>,
    cap: usize,
}

impl RingBuffer {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        RingBuffer { buf: VecDeque::with_capacity(cap), cap }
    }

    /// Pushes a value, returning the evicted value if the buffer was full.
    pub fn push(&mut self, v: u32) -> Option<u32> {
        let evicted = if self.buf.len() == self.cap {
            self.buf.pop_front()
        } else {
            None
        };
        self.buf.push_back(v);
        evicted
    }

    pub fn pop(&mut self) -> Option<u32> {
        self.buf.pop_front()
    }

    pub fn len(&self) -> usize { self.buf.len() }
}

fn main() {
    let mut rb = RingBuffer::new(2);
    assert_eq!(rb.push(1), None);
    assert_eq!(rb.push(2), None);
    assert_eq!(rb.push(3), Some(1));
    assert_eq!(rb.pop(), Some(2));
    assert_eq!(rb.len(), 1);
