class FileHandle {
    std::FILE* fp_ = nullptr;
public:
    FileHandle() = default;
    explicit FileHandle(const char* path, const char* mode) : fp_(std::fopen(path, mode)) {}

    ~FileHandle() { if (fp_) std::fclose(fp_); }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fp_(other.fp_) { other.fp_ = nullptr; }

    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            if (fp_) std::fclose(fp_);
            fp_ = other.fp_;
            other.fp_ = nullptr;
        }
        return *this;
    }

    std::FILE* get() const noexcept { return fp_; }
    explicit operator bool() const noexcept { return fp_ != nullptr; }
};

int main() {
    FileHandle fh("/dev/null", "w");
    if (fh) std::fputs("hello\n", fh.get());
    FileHandle moved = std::move(fh);
    // fh is now empty; moved owns the handle.
    return moved ? 0 : 1;
