#include <iostream>
#include <climits>
#include <cassert>

bool isPalindrome(int x) {
    if (x < 0) return false;
    if (x != 0 && x % 10 == 0) return false;  // trailing zero, e.g. 10
    long long rev = 0;
    while (x > rev) {
        rev = rev * 10 + x % 10;
        x /= 10;
    }
    // even length: x == rev; odd length: x == rev / 10
    return x == rev || x == rev / 10;
}

int main() {
    assert(isPalindrome(0));
    assert(isPalindrome(7));
    assert(isPalindrome(121));
    assert(isPalindrome(1221));
    assert(!isPalindrome(-121));
    assert(!isPalindrome(10));
    assert(!isPalindrome(123));
    assert(isPalindrome(1000000001));
    assert(!isPalindrome(INT_MAX));
    std::cout << "ok\n";
}
```

Only half the digits are reversed, so no overflow occurs; the loop stops once `rev` reaches or passes the remaining `x`. The trailing-zero guard rejects numbers like `10` that would otherwise compare equal after reversal.

