```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Reads a regular file into a NUL-terminated heap buffer.
   Returns NULL on error. Caller must free(). *out_len gets the byte count
   (excluding the terminator) on success. */
char *read_file(const char *path, size_t *out_len) {
    if (!path || !out_len) return NULL;
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;

    if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return NULL; }
    long size = ftell(f);
    if (size < 0) { fclose(f); return NULL; }
    if (fseek(f, 0, SEEK_SET) != 0) { fclose(f); return NULL; }

    size_t n = (size_t)size;
    char *buf = malloc(n + 1);
    if (!buf) { fclose(f); return NULL; }

    size_t got = fread(buf, 1, n, f);
    if (got != n) {
        if (ferror(f)) { free(buf); fclose(f); return NULL; }
    }
    buf[got] = '\0';
    fclose(f);
    *out_len = got;
    return buf;
}

int main(void) {
    size_t len = 0;
    char *p = read_file("/etc/hostname", &len);
    if (!p) { fprintf(stderr, "read failed\n"); return 1; }
    printf("read %zu bytes\n", len);
    free(p);
    return 0;
}
```

Every allocation is checked, `fread` is validated against the size obtained from `ftell`, and the buffer is always NUL-terminated. `got` is used for the terminator index so a short read (file truncated concurrently) still yields a valid string.

