use std::collections::HashMap;

/// Parse lines like `key = value`. Lines starting with `#` or blank are skipped.
/// Returns a map plus the 1-based line numbers that were malformed.
pub fn parse_config(input: &str) -> (HashMap<String, String>, Vec<usize>) {
    let mut map = HashMap::new();
    let mut bad = Vec::new();

    for (i, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        match line.split_once('=') {
            Some((k, v)) => {
                let key = k.trim();
                if key.is_empty() {
                    bad.push(i + 1);
                } else {
                    map.insert(key.to_string(), v.trim().to_string());
                }
            }
            None => bad.push(i + 1),
        }
    }

    (map, bad)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_and_flags_bad_lines() {
        let input = "# comment\n\nname = xt-luna\nversion=1.0\nnovalue\n=orphan\n";
        let (map, bad) = parse_config(input);
        assert_eq!(map.get("name").map(String::as_str), Some("xt-luna"));
        assert_eq!(map.get("version").map(String::as_str), Some("1.0"));
        assert_eq!(bad, vec![5, 6]);
    }

    #[test]
    fn empty_input() {
        let (map, bad) = parse_config("");
        assert!(map.is_empty());
        assert!(bad.is_empty());
    }
}
```

`split_once` keeps any `=` inside the value intact (`split('=')` would not). Malformed lines are collected rather than causing an early return, so the caller sees everything wrong in one pass.

