#include <iostream>
#include <queue>
#include <vector>
#include <cassert>

class MedianStream {
    std::priority_queue<int> low;                              // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap
public:
    void add(int x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);

        if (low.size() > high.size() + 1) { high.push(low.top()); low.pop(); }
        else if (high.size() > low.size()) { low.push(high.top()); high.pop(); }
    }

    double median() const {
        if (low.empty()) throw std::runtime_error("no elements");
        if (low.size() == high.size()) return (low.top() + high.top()) / 2.0;
        return low.top();
    }
};

int main() {
    MedianStream m;
    m.add(5);
    assert(m.median() == 5.0);
    m.add(15);
    assert(m.median() == 10.0);
    m.add(1);
    assert(m.median() == 5.0);
    m.add(3);
    assert(m.median() == 4.0);
    m.add(8);
    assert(m.median() == 5.0);
    std::cout << "ok\n";
}
```

`low` holds the smaller half (max-heap) and `high` the larger half (min-heap), with sizes differing by at most one. After each insert the heaps are rebalanced, so `low.top()` is the median and the even-case average takes `high.top()` as well — all O(log n) per element.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    def expand(lo: int, hi: int) -> tuple[int, int]:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - 1

    start, end = 0, 0
    for i in range(len(s)):
        a, b = expand(i, i)
        if b - a > end - start:
            start, end = a, b
        a, b = expand(i, i + 1)
        if b - a > end - start:
            start, end = a, b
    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["", "a", "babad", "cbbd", "abracadabra", "日本語のテスト語"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```
`expand` treats each index (and each gap) as a center and widens while the characters match. An empty string stays unhandled by the loop and returns `""`. Unicode works because Python indexes code points, so multi-byte characters compare correctly.

