use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if cleaned.is_empty() {
            continue;
        }
        *counts.entry(cleaned).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the quick brown fox, the LAZY dog. The end!";
    for (w, c) in top_words(text, 3) {
        println!("{w}: {c}");
    }
}
```
Words are stripped to alphanumerics and lowercased, so `The` and `the,` collapse. `flat_map` over `to_lowercase` handles characters that expand. Sorting by count descending then key ascending gives a deterministic order; `truncate(n)` keeps the top slice, and an empty or punctuation-only input yields an empty vec.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict[int, int] = OrderedDict()

    def get(self, key: int) -> int:
        if key not in self._data:
            return -1
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: int, value: int) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, 1)
    c.put(2, 2)
    print(c.get(1))  # 1
    c.put(3, 3)
    print(c.get(2))  # -1
    print(c.get(3))  # 3
```
`OrderedDict` keeps insertion order; a hit or an overwrite moves the key to the end (most recently used). When size exceeds capacity we pop from the front, which is the least recently used entry. `get` of a missing key returns `-1` as the conventional sentinel.

