#include <iostream>
#include <stack>
#include <string>

bool is_balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                st.push(c);
                break;
            case ')':
                if (st.empty() || st.top() != '(') return false;
                st.pop();
                break;
            case ']':
                if (st.empty() || st.top() != '[') return false;
                st.pop();
                break;
            case '}':
                if (st.empty() || st.top() != '{') return false;
                st.pop();
                break;
            default:
                break; // ignore other characters
        }
    }
    return st.empty();
}

int main() {
    const char* tests[] = {"({[]})", "([)]", "", "{[", "no brackets"};
    for (const char* t : tests)
        std::cout << '\'' << t << "' -> " << (is_balanced(t) ? "balanced" : "unbalanced") << '\n';
    return 0;
}
```
A stack holds the opening brackets. On a closer we require a matching top, otherwise it's immediately unbalanced. Non-bracket characters are ignored. At the end the stack must be empty; `"([)]"` fails because `]` sees `(`, and the empty string is trivially balanced.

