#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char *line = NULL;
    size_t cap = 0;
    ssize_t len = getline(&line, &cap, stdin);
    if (len < 0) {
        free(line);
        return 0; // EOF or empty read
    }
    if (len > 0 && line[len - 1] == '\n') {
        line[--len] = '\0';
    }
    if (len == 0) {
        putchar('\n');
        free(line);
        return 0;
    }
    for (ssize_t i = len - 1; i >= 0; i--) {
        putchar((unsigned char)line[i]);
    }
    putchar('\n');
    free(line);
    return 0;
}
```
`getline` allocates and grows the buffer, so arbitrarily long lines are safe. We strip a trailing newline by replacing it with `'\0'` and decrementing the length. An empty line prints just a newline; a NULL/EOF from `getline` frees and exits. Reversal casts to `unsigned char` so bytes >= 0x80 print correctly.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity) {}

    bool push(int value) {
        if (size_ == cap_) return false;
        data_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<int, 64> data_{};
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    if (!rb.push(10) || !rb.push(20) || !rb.push(30)) return 1;
    if (rb.push(40)) return 1;                // overflow rejected
    auto a = rb.pop();
    auto b = rb.pop();
    if (!a || !b || *a != 10 || *b != 20) return 1;
    if (!rb.push(40)) return 1;               // room again after pops
    std::cout << "size=" << rb.size() << "\n";
    return 0;
}
```

Capacity is fixed at construction; `push` returns `false` on overflow and `pop` returns `std::nullopt` on underflow, so no exceptions or sentinel values are needed. The modulo index wraps both `head_` and `size_`.

