use std::fmt::Debug;
use std::num::ParseIntError;

/// Flatten `Result<Vec<Result<T, E>>, E>` into `Result<Vec<T>, E>`.
///
/// The outer error short-circuits; the first inner error stops the
/// walk and is returned, so no partial vector is exposed.
fn flatten_results<T, E>(input: Result<Vec<Result<T, E>>, E>) -> Result<Vec<T>, E> {
    let mut out = Vec::new();
    for item in input? {
        out.push(item?);
    }
    Ok(out)
}

fn parse_all(raw: &[&str]) -> Result<Vec<i32>, ParseIntError> {
    let parsed: Vec<Result<i32, ParseIntError>> = raw.iter().map(|s| s.parse()).collect();
    flatten_results(Ok(parsed))
}

fn main() {
    assert_eq!(parse_all(&["1", "2", "3"]).unwrap(), vec![1, 2, 3]);
    assert!(parse_all(&["1", "x", "3"]).is_err());

    let outer_fail: Result<Vec<Result<i32, ParseIntError>>, ParseIntError> =
        Err("outer".parse::<i32>().unwrap_err());
    assert!(flatten_results(outer_fail).is_err());

    let empty: Result<Vec<Result<i32, ParseIntError>>, ParseIntError> = Ok(Vec::new());
    assert_eq!(flatten_results(empty).unwrap(), Vec::<i32>::new());
    println!("ok");
}
```

`input?` propagates the outer error first, then each `item?` propagates the first inner error. Because `out` is built iteratively, a later inner error discards earlier pushes rather than exposing a half-filled vector.

