    const std::vector<std::string> b{"dog", "racecar", "car"};
    const std::vector<std::string> c{"", "abc"};
    const std::vector<std::string> d{"same", "same"};

    if (longest_common_prefix(a) != "fl") return 1;
    if (longest_common_prefix(b) != "") return 1;
    if (longest_common_prefix(c) != "") return 1;
    if (longest_common_prefix(d) != "same") return 1;
    if (longest_common_prefix({}) != "") return 1;
    std::cout << "prefix=" << longest_common_prefix(a) << "\n";
    return 0;
}
```

The outer loop walks characters of the first word; for each character the inner loop checks every word, and the `i >= w.size()` guard prevents out-of-range indexing on a shorter string. If a mismatch is found we return `first.substr(0, i)`, so the returned prefix always excludes the offending character.

