#include <algorithm>
#include <cstddef>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

int main() {
    std::string line;
    if (!std::getline(std::cin, line) || line.empty()) {
        std::cout << "no data\n";
        return 0;
    }

    std::vector<long long> nums;
    std::stringstream ss(line);
    std::string token;
    while (std::getline(ss, token, ',')) {
        try {
            std::size_t pos = 0;
            long long value = std::stoll(token, &pos);
            if (pos != token.size()) {
                std::cerr << "skipping malformed token: " << token << "\n";
                continue;
            }
            nums.push_back(value);
        } catch (const std::exception&) {
            std::cerr << "skipping malformed token: " << token << "\n";
        }
    }
    if (nums.empty()) {
        std::cout << "no data\n";
        return 0;
    }

    std::sort(nums.begin(), nums.end());

    double sum = 0.0;
    for (long long v : nums) sum += static_cast<double>(v);
    double mean = sum / static_cast<double>(nums.size());

    std::size_t n = nums.size();
    double median = (n % 2 == 1)
        ? static_cast<double>(nums[n / 2])
        : (static_cast<double>(nums[n / 2 - 1]) + static_cast<double>(nums[n / 2])) / 2.0;

    std::map<long long, std::size_t> counts;
    for (long long v : nums) ++counts[v];
    long long mode = nums[0];
    std::size_t best = 0;
    for (const auto& [value, count] : counts) {
        if (count > best) {
            best = count;
            mode = value;
        }
    }

    std::cout << "mean=" << mean << " median=" << median << " mode=" << mode << "\n";
    return 0;
}
```

Sorting first makes the median a constant-time lookup and gives the mode scan a deterministic tie-break (lowest value wins). Malformed tokens are reported to stderr and skipped instead of aborting the run, so one typo does not discard the whole line.

