```c
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) {
        return;
    }
    size_t len = strlen(s);
    if (len < 2) {
        return;
    }
    size_t left = 0;
    size_t right = len - 1;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        ++left;
        --right;
    }
}

int main(void) {
    char buf[64];
    printf("enter text: ");
    fflush(stdout);
    if (fgets(buf, sizeof buf, stdin) == NULL) {
        return 0;
    }
    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] == '\n') {
        buf[--len] = '\0';
    }
    reverse_in_place(buf);
    printf("reversed: %s\n", buf);
    return 0;
}
```

Two indices walk toward each other and swap, so it is O(n) time and O(1) extra space. The `len < 2` guard covers empty strings and single characters, and stripping the trailing newline that `fgets` keeps avoids reversing a stray `\n` to the front.

```python
import hashlib
import os
import sys
from collections import defaultdict

BLOCK = 65536


def file_digest(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        while True:
            chunk = fh.read(BLOCK)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root: str) -> dict:
    by_size = defaultdict(list)
    for dirpath, _dirs, files in os.walk(root):
        for name in files:
            path = os.path.join(dirpath, name)
            if os.path.islink(path):
                continue
            try:
                by_size[os.path.getsize(path)].append(path)
            except OSError as exc:
                print(f"skipping {path}: {exc}", file=sys.stderr)

    seen = defaultdict(list)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue  # unique size means unique file: no hashing needed
        for path in paths:
            try:
                seen[file_digest(path)].append(path)
            except OSError as exc:
                print(f"skipping {path}: {exc}", file=sys.stderr)
    return {d: p for d, p in seen.items() if len(p) > 1}


if __name__ == "__main__":
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    groups = find_duplicates(root)
    if not groups:
        print("no duplicates found")
    for digest, paths in groups.items():
        print(f"{digest[:12]}: {len(paths)} copies")
        for p in paths:
            print(f"  {p}")
```

Grouping by file size first means only colliding-size files ever get hashed, which is the main speedup on large trees. Streamed 64 KiB reads keep memory flat regardless of file size, symlinks are skipped to avoid loops, and unreadable files are reported rather than crashing the walk.

```rust
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let left = [1, 3, 5, 7];
    let right = [2, 3, 4, 8, 9];
    let merged = merge_sorted(&left, &right);
    assert_eq!(merged, vec![1, 2, 3, 3, 4, 5, 7, 8, 9]);

    let empty: [i32; 0] = [];
    assert_eq!(merge_sorted(&left, &empty), left.to_vec());
    assert_eq!(merge_sorted(&empty, &right), right.to_vec());
    assert!(merge_sorted(&empty, &empty).is_empty());

    println!("{:?}", merged);
}
```

The `<=` comparison takes from the left slice on ties, which keeps the merge stable. The two-index walk is O(n + m); once one slice is exhausted, `extend_from_slice` appends the remainder in bulk instead of looping. It works for any `T: Ord + Clone`, so strings and structs with `Ord` work too. The empty-slice tests confirm the tail append handles both zero-length inputs correctly.

