#include <iostream>
#include <stack>
#include <string>
#include <vector>

int main() {
    std::string input;
    if (!std::getline(std::cin, input)) {
        std::cout << "no input\n";
        return 0;
    }

    const std::string openers = "([{";
    const std::string closers = ")]}";

    struct Frame { char ch; std::size_t pos; };
    std::stack<Frame> st;

    for (std::size_t i = 0; i < input.size(); ++i) {
        char c = input[i];
        std::size_t open_idx = openers.find(c);
        std::size_t close_idx = closers.find(c);

        if (open_idx != std::string::npos) {
            st.push({c, i});
        } else if (close_idx != std::string::npos) {
            if (st.empty()) {
                std::cout << "unmatched closing '" << c << "' at index " << i << "\n";
                return 1;
            }
            Frame top = st.top();
            st.pop();
            if (openers.find(top.ch) != close_idx) {
                std::cout << "mismatch: '" << top.ch << "' at index " << top.pos
                          << " closed by '" << c << "' at index " << i << "\n";
                return 1;
            }
        }
    }

    if (!st.empty()) {
        Frame top = st.top();
        std::cout << "unclosed '" << top.ch << "' at index " << top.pos << "\n";
        return 1;
    }

    std::cout << "balanced\n";
    return 0;
}
```

Pushing the bracket character and its index together means every error path can name the exact offending position. The stack enforces correct nesting order, so `([)]` is caught as a mismatch, not just a count imbalance. Returns exit status 0 on balanced input and 1 on any defect, which makes it usable in a shell pipeline.

