#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
class Stack {
public:
    void push(const T& value) { data_.push_back(value); }

    T pop() {
        if (data_.empty()) throw std::out_of_range("pop on empty stack");
        T value = data_.back();
        data_.pop_back();
        return value;
    }

    const T& peek() const {
        if (data_.empty()) throw std::out_of_range("peek on empty stack");
        return data_.back();
    }

    bool empty() const { return data_.empty(); }
    std::size_t size() const { return data_.size(); }

private:
    std::vector<T> data_;
};

int main() {
    Stack<int> s;
    for (int i = 1; i <= 3; ++i) s.push(i * 10);
    std::cout << s.peek() << '\n';   // 30
    std::cout << s.pop() << '\n';    // 30
    std::cout << s.size() << '\n';   // 2
    try {
        Stack<int> empty;
        empty.pop();
    } catch (const std::out_of_range& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
}
```

