const MOD: u64 = 1_000_000_007;

fn mat_mul(a: [[u64; 2]; 2], b: [[u64; 2]; 2]) -> [[u64; 2]; 2] {
    let mut c = [[0u64; 2]; 2];
    for i in 0..2 {
        for j in 0..2 {
            for k in 0..2 {
                c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % MOD;
            }
        }
    }
    c
}

fn fib(n: u64) -> u64 {
    if n == 0 { return 0; }
    let mut result = [[1, 0], [0, 1]];      // identity
    let mut base = [[1, 1], [1, 0]];
    let mut e = n;
    while e > 0 {
        if e & 1 == 1 { result = mat_mul(result, base); }
        base = mat_mul(base, base);
        e >>= 1;
    }
    result[0][1]
}

fn main() {
    for n in 0..10 {
        println!("fib({n}) = {}", fib(n));
    }
