```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int has_cycle(const Node *head) {
    const Node *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return 1;
    }
    return 0;
}

static Node *make(int v) {
    Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(1); }
    n->value = v;
    n->next = NULL;
    return n;
}

int main(void) {
    Node *head = make(1);
    head->next = make(2);
    head->next->next = make(3);
    printf("cycle before: %d\n", has_cycle(head));
    head = reverse(head);
    for (Node *p = head; p; p = p->next) printf("%d ", p->value);
    printf("\n");
    return 0;
}
```

`reverse` rewires three pointers per node with no recursion, and `has_cycle` advances fast twice per iteration, so they meet inside a loop if one exists. The list here is acyclic, so it prints `cycle before: 0`.

