// Returns (F(n), F(n+1)) modulo MOD.
static std::pair<long long, long long> fib_pair(unsigned long long n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    long long c = a * ((2 * b % MOD - a + MOD) % MOD) % MOD;
    long long d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1ULL) return {d, (c + d) % MOD};
    return {c, d};
}

