#include <limits.h>
#include <stdio.h>
#include <string.h>

static void emit(long long value, int base, char *out, size_t *pos) {
    if (value == 0) {
        return;
    }
    emit(value / base, base, out, pos);
    int digit = (int)(value % base);
    out[(*pos)++] = digit < 10 ? (char)('0' + digit) : (char)('a' + digit - 10);
}

static int to_base(int value, int base, char *out, size_t cap) {
    if (base < 2 || base > 36) {
        return -1;
    }
    long long v = value;
    size_t pos = 0;
    if (v < 0) {
        if (pos + 1 >= cap) return -1;
        out[pos++] = '-';
        v = -v;
    }
    if (v == 0) {
        if (pos + 2 > cap) return -1;
        out[pos++] = '0';
    } else {
        emit(v, base, out, &pos);
    }
    out[pos] = '\0';
    return (int)pos;
}

int main(void) {
    char buf[128];
    if (to_base(INT_MIN, 16, buf, sizeof buf) >= 0) printf("%s\n", buf);
    if (to_base(255, 2, buf, sizeof buf) >= 0) printf("%s\n", buf);
    if (to_base(0, 10, buf, sizeof buf) >= 0) printf("%s\n", buf);
    if (to_base(10, 37, buf, sizeof buf) < 0) printf("invalid base\n");
    return 0;
}
```

