fn parse_line(line: &str) -> Result<Vec<String>, String> {
    let mut fields = Vec::new();
    let mut cur = String::new();
    let mut quoted = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '"' if quoted && chars.peek() == Some(&'"') => {
                cur.push('"');
                chars.next();
            }
            '"' => quoted = !quoted,
            ',' if !quoted => fields.push(std::mem::take(&mut cur)),
            _ => cur.push(c),
        }
    }
    if quoted {
        return Err("unterminated quote".to_string());
    }
    fields.push(cur);
    Ok(fields)
}

fn main() {
    let csv = "name,amount\n\"Doe, Jane\",12.5\nBob,bad\n\"broken\n";
    for (i, line) in csv.lines().enumerate().skip(1) {
        match parse_line(line) {
            Ok(fields) if fields.len() >= 2 => match fields[1].parse::<f64>() {
                Ok(v) => println!("row {}: {} = {}", i + 1, fields[0], v),
                Err(_) => eprintln!("row {}: non-numeric amount {:?}", i + 1, fields[1]),
            },
            Ok(f) => eprintln!("row {}: expected 2 fields, got {}", i + 1, f.len()),
            Err(e) => eprintln!("row {}: {}", i + 1, e),
        }
    }
}
