static std::string_view trim(std::string_view sv) {
    const auto not_space = [](unsigned char c) { return !std::isspace(c); };
    while (!sv.empty() && !not_space(static_cast<unsigned char>(sv.front()))) sv.remove_prefix(1);
    while (!sv.empty() && !not_space(static_cast<unsigned char>(sv.back()))) sv.remove_suffix(1);
    return sv;
}

static std::vector<std::string> split(const std::string &input, char delim) {
    std::vector<std::string> out;
    std::size_t start = 0;
    for (std::size_t i = 0; i <= input.size(); ++i) {
        if (i == input.size() || input[i] == delim) {
            std::string_view token = trim(std::string_view(input).substr(start, i - start));
            if (!token.empty()) out.emplace_back(token);
            start = i + 1;
        }
    }
    return out;
}

int main() {
    for (const auto &t : split(" a ,, b ; c ", ',')) std::cout << '[' << t << "]\n";
    std::cout << "count=" << split("", ',').size() << '\n';
    return 0;
}
