import re
from collections import deque
from typing import Iterator, Tuple


def grep_stream(path: str, pattern: str, before: int = 0, after: int = 0) -> Iterator[Tuple[int, str]]:
    regex = re.compile(pattern)
    window = deque(maxlen=before) if before > 0 else deque()
    remaining = 0

    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        for lineno, raw in enumerate(fh, start=1):
            line = raw.rstrip("\n")
            matched = bool(regex.search(line))
            if before and (matched or remaining > 0):
                for bl, _ in window:
                    pass
            if matched:
                yield lineno, line
                remaining = after
            elif remaining > 0:
                yield lineno, line
                remaining -= 1
            if before:
                window.append((lineno, line))


if __name__ == "__main__":
    import sys
    for n, line in grep_stream(sys.argv[1], sys.argv[2], before=1, after=1):
        print(f"{n}: {line}")
```

