template <typename T>
T dot_product(const std::vector<T>& a, const std::vector<T>& b) {
    static_assert(std::is_arithmetic_v<T>, "dot_product requires arithmetic element type");
    if (a.size() != b.size()) {
        throw std::invalid_argument("vector size mismatch");
    }
    T sum{};
    for (std::size_t i = 0; i < a.size(); ++i) {
        sum += a[i] * b[i];
    }
    return sum;
}

int main() {
    std::vector<int> x{1, 2, 3};
    std::vector<int> y{4, 5, 6};
    assert(dot_product(x, y) == 32);

    std::vector<double> p{};
    assert(dot_product(p, p) == 0.0);

    std::cout << dot_product(x, y) << "\n";
    return 0;
}
```
The `static_assert` rejects non-arithmetic types like `std::string` at compile time, and the runtime size check turns a silent out-of-range read into a clear exception. Empty vectors return the zero-initialised `sum`, so the empty case is well defined.

