```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) {
            ++size_;
        } else {
            tail_ = (tail_ + 1) % N;   // dropped oldest
        }
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.pop() == std::nullopt);
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4);                       // overwrites 1
    assert(rb.size() == 3);
    assert(rb.pop() == 2);
    assert(rb.pop() == 3);
    assert(rb.pop() == 4);
    assert(rb.empty());
}
```
A separate `size_` counter means the buffer distinguishes full from empty without wasting a slot, and `N` is a template parameter so the capacity is fixed at compile time and `std::array` can live on the stack.

```python
def fib(n: int) -> int:
    """Return the nth Fibonacci number (F(0)=0, F(1)=1) via fast doubling."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def _fib(k: int):
        if k == 0:
            return (0, 1)
        a, b = _fib(k >> 1)
        c = a * (2 * b - a)
        d = a * a + b * b
        if k & 1:
            return (d, c + d)
        return (c, d)

    return _fib(n)[0]


if __name__ == "__main__":
    assert fib(0) == 0
    assert fib(1) == 1
    assert fib(10) == 55
    assert fib(50) == 12586269025
    print(fib(100))
```

`_fib(k)` returns `(F(k), F(k+1))`. The recursion halves `k` each call, so it runs in O(log n) multiplications. `c = F(2m)` and `d = F(2m+1)` come from the doubling identities; the odd branch adds one more step. Python's big ints mean `fib(100)` is exact.

