#include <stdio.h>
#include <string.h>

void reverse(char *s) {
    if (s == NULL) return;
    size_t n = strlen(s);
    if (n < 2) return;  // empty or single char: nothing to do
    for (size_t i = 0, j = n - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

int main(void) {
    char buf[64];

    const char *cases[] = {"", "a", "ab", "hello", "a\x01b"};
    for (size_t k = 0; k < sizeof(cases) / sizeof(cases[0]); ++k) {
        strncpy(buf, cases[k], sizeof(buf) - 1);
        buf[sizeof(buf) - 1] = '\0';
        reverse(buf);
        printf("[%s]\n", buf);
    }
    return 0;
}
```

Two indices walk toward the center and swap bytes; the loop stops when they meet, so odd lengths leave the middle byte untouched. `strlen` on the `char*` works because inputs are NUL-terminated. `strncpy` plus a forced terminator avoids overflow on the fixed 64-byte buffer. Bytes outside ASCII reverse correctly too, since only byte positions move — but note multi-byte UTF-8 sequences would be scrambled, so callers should pass ASCII.

