use std::fmt;

#[derive(Debug, PartialEq)]
enum RangeError {
    Empty,
    OutOfRange { value: i64, min: i64, max: i64 },
    InvertedRange { min: i64, max: i64 },
}

impl fmt::Display for RangeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RangeError::Empty => write!(f, "value list is empty"),
            RangeError::OutOfRange { value, min, max } => {
                write!(f, "value {value} outside [{min}, {max}]")
            }
            RangeError::InvertedRange { min, max } => {
                write!(f, "range [{min}, {max}] is inverted")
            }
        }
    }
}

fn validate(values: &[i64], min: i64, max: i64) -> Result<(), RangeError> {
    if min > max {
        return Err(RangeError::InvertedRange { min, max });
    }
    if values.is_empty() {
        return Err(RangeError::Empty);
    }
    for &v in values {
        if v < min || v > max {
            return Err(RangeError::OutOfRange { value: v, min, max });
        }
    }
    Ok(())
}

fn main() {
    assert_eq!(validate(&[1, 2, 3], 0, 5), Ok(()));
    assert!(matches!(validate(&[], 0, 5), Err(RangeError::Empty)));
    assert!(matches!(validate(&[9], 0, 5), Err(RangeError::OutOfRange { value: 9, .. })));
    assert!(matches!(validate(&[1], 5, 0), Err(RangeError::InvertedRange { .. })));
    println!("{}", validate(&[9], 0, 5).unwrap_err());
}
```

A custom enum beats `Result<(), String>` for matchable error kinds. The `Display` impl turns each variant into readable text. `validate` checks the inverted range first, since `[5, 0]` would otherwise reject every value with a confusing message. Error-first ordering means the caller can distinguish empty input from a genuine out-of-range value.

