#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <vector>

double median(std::vector<double> values) {  // by value: we may reorder
    if (values.empty()) {
        throw std::invalid_argument("median of empty vector");
    }
    const std::size_t n = values.size();
    const std::size_t mid = n / 2;

    std::nth_element(values.begin(), values.begin() + mid, values.end());

    if (n % 2 == 1) {
        return values[mid];
    }
    // even: need max of lower half, so partition it and take its max
    const double upper = values[mid];
    std::nth_element(values.begin(), values.begin() + mid - 1, values.begin() + mid);
    const double lower = values[mid - 1];
    return (lower + upper) / 2.0;
}

int main() {
    std::cout << median({3.0, 1.0, 2.0}) << '\n';        // 2
    std::cout << median({4.0, 1.0, 3.0, 2.0}) << '\n';   // 2.5
    std::cout << median({7.0}) << '\n';                  // 7
    try {
        median({});
    } catch (const std::invalid_argument& e) {
        std::cerr << "error: " << e.what() << '\n';
    }
    return 0;
}
```

`nth_element` is average O(n) and only partially orders, so no full sort is needed. Taking the parameter by value lets us reorder the caller's data in a local copy without another allocation. For even sizes I partition the lower half separately to get the max of the elements below the middle — that is exactly the lower median. The empty case throws rather than returning a garbage value.

