#include <limits>

std::optional<unsigned long long> parse_uint(const std::string& s) {
    if (s.empty()) return std::nullopt;
    unsigned long long value = 0;
    constexpr auto max_v = std::numeric_limits<unsigned long long>::max();
    for (char c : s) {
        if (c < '0' || c > '9') return std::nullopt; // rejects '+', '-', space
        unsigned digit = static_cast<unsigned>(c - '0');
        if (value > (max_v - digit) / 10ULL) return std::nullopt; // overflow
        value = value * 10ULL + digit;
    }
    return value;
}

