    assert(parse_uint("42").value() == 42ULL);
    assert(!parse_uint("").has_value());
    assert(!parse_uint(" 7").has_value());
    assert(!parse_uint("+7").has_value());
    assert(!parse_uint("12a").has_value());
    assert(!parse_uint("18446744073709551616").has_value()); // 2^64 overflows
    std::cout << "ok\n";
}
#endif
