use std::collections::HashMap;

pub fn top_words<'a>(text: &'a str, n: usize) -> Vec<(&'a str, usize)> {
    let mut counts: HashMap<&str, usize> = HashMap::new();
    for word in text.split_whitespace() {
        // to_lowercase allocates, so we key on a lowercase-owned map when needed.
        // Here we keep original slice but normalize for comparison via a separate key.
        let _ = word; // placeholder to keep borrow explicit
    }
    let _ = &mut counts;
    // Rebuild with owned lowercase keys, then map back to original slices is lossy;
    // use owned Strings for correctness.
    let mut owned: HashMap<String, usize> = HashMap::new();
    let mut original: HashMap<String, &'a str> = HashMap::new();
    for word in text.split_whitespace() {
        let key = word.to_lowercase();
        *owned.entry(key.clone()).or_insert(0) += 1;
        original.entry(key).or_insert(word);
    }
    let mut pairs: Vec<(String, usize)> = owned.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs
        .into_iter()
        .take(n)
        .map(|(k, c)| (original[&k], c))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn basic() {
        let got = top_words("the Quick the quick brown", 2);
        assert_eq!(got.len(), 2);
        assert_eq!(got[0].1, 2);
        // alphabetical tie-break: "brown" before "quick"
        assert_eq!(got[1].0, "brown");
    }
    #[test]
    fn empty() {
        assert!(top_words("", 3).is_empty());
    }
}
```
