#include <stddef.h>
#include <stdbool.h>
#include <assert.h>
#include <stdio.h>

#define RING_CAP 8

typedef struct {
    int data[RING_CAP];
    size_t head;  /* next write index */
    size_t tail;  /* next read index */
    size_t count; /* number of stored items */
} ring_t;

static void ring_init(ring_t *r) {
    r->head = r->tail = r->count = 0;
}

static void ring_push(ring_t *r, int value) {
    if (r->count == RING_CAP) {
        /* full: overwrite oldest, advance tail */
        r->tail = (r->tail + 1) % RING_CAP;
        r->count--;
    }
    r->data[r->head] = value;
    r->head = (r->head + 1) % RING_CAP;
    r->count++;
}

static bool ring_pop(ring_t *r, int *out) {
    if (r->count == 0) return false;
    *out = r->data[r->tail];
    r->tail = (r->tail + 1) % RING_CAP;
    r->count--;
    return true;
}

int main(void) {
    ring_t r;
    ring_init(&r);
    int v = 0;
    assert(!ring_pop(&r, &v)); /* empty pop fails */
    for (int i = 0; i < 12; i++) ring_push(&r, i);
    /* capacity 8: stored are 4..11 */
    assert(ring_pop(&r, &v) && v == 4);
    assert(ring_pop(&r, &v) && v == 5);
    printf("ok\n");
    return 0;
}
