#include <vector>
#include <cassert>
#include <iostream>

std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        // `<=` keeps a's element first on ties, a stable choice.
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    out.insert(out.end(), a.begin() + static_cast<std::ptrdiff_t>(i), a.end());
    out.insert(out.end(), b.begin() + static_cast<std::ptrdiff_t>(j), b.end());
    return out;
}

#ifdef MERGE_MAIN
int main() {
    std::vector<int> a{1, 3, 5};
    std::vector<int> b{2, 4, 6};
    assert((merge_sorted(a, b) == std::vector<int>{1, 2, 3, 4, 5, 6}));
    assert(merge_sorted({}, {}) == std::vector<int>{});
    assert((merge_sorted({}, {7, 8}) == std::vector<int>{7, 8}));
    assert((merge_sorted({1, 1, 1}, {1, 1}) == std::vector<int>{1, 1, 1, 1, 1}));
