#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

void print(Node* head) {
    for (Node* p = head; p != nullptr; p = p->next)
        std::cout << p->value << (p->next ? " -> " : "\n");
}

int main() {
    Node* head = nullptr;
    for (int i = 5; i >= 1; --i) head = new Node(i) , head->next = head->next; // placeholder
    // rebuild properly
    while (head) { Node* t = head; head = head->next; delete t; }

    Node* a = new Node(1);
    a->next = new Node(2);
    a->next->next = new Node(3);
    a->next->next->next = new Node(4);
    std::cout << "before: "; print(a);
    a = reverse(a);
    std::cout << "after:  "; print(a);

    while (a) { Node* t = a; a = a->next; delete t; }
    std::cout << "empty:  "; print(reverse(static_cast<Node*>(nullptr)));
    return 0;
}
```

Three-pointer iterative reversal: save `next`, flip the link, advance. Returns the old tail as the new head, and `nullptr` passes through cleanly so empty lists print nothing. O(n) time, O(1) space.

