int vec_push(Vec *v, int x) {
    if (v->len == v->cap) {
        size_t ncap = v->cap * 2;
        int *p = realloc(v->data, ncap * sizeof(int));
        if (!p) return 0;
        v->data = p;
        v->cap = ncap;
    }
    v->data[v->len++] = x;
    return 1;
}

void vec_free(Vec *v) {
    free(v->data);
    v->data = NULL;
    v->len = v->cap = 0;
}

