template <typename T>
std::optional<T> dot_product(const std::vector<T>& a, const std::vector<T>& b) {
    if (a.size() != b.size()) {
        return std::nullopt;
    }
    T total{};
    for (std::size_t i = 0; i < a.size(); ++i) {
        total += a[i] * b[i];
    }
    return total;
}

int main() {
    std::vector<int> a{1, 2, 3};
    std::vector<int> b{4, 5, 6};
    auto ok = dot_product(a, b);
    if (ok) std::cout << *ok << '\n';  // 32

    std::vector<int> c{1};
    auto bad = dot_product(a, c);
    if (!bad) std::cout << "size mismatch\n";
    return 0;
}
