#include <array>
#include <cstddef>
#include <iostream>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& v) {
        if (size_ == N) return false;
        buf_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }

    bool pop(T& out) {
        if (size_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }

private:
    std::array<T, N> buf_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << '\n';
    int v;
    while (rb.pop(v)) std::cout << v << ' ';
    std::cout << '\n';
}
