```c
#include <ctype.h>
#include <limits.h>
#include <stdio.h>

int clamp_atoi(const char *s, const char **end) {
    const char *p = s;
    while (isspace((unsigned char)*p)) p++;
    int neg = 0;
    if (*p == '+' || *p == '-') { neg = (*p == '-'); p++; }
    long acc = 0;
    int overflow = 0;
    while (isdigit((unsigned char)*p)) {
        acc = acc * 10 + (*p - '0');
        if (acc > (long)INT_MAX + 1) { overflow = 1; acc = (long)INT_MAX + 1; }
        p++;
    }
    if (end) *end = p;
    if (overflow) return neg ? INT_MIN : INT_MAX;
    return neg ? (int)-acc : (int)acc;
}

int main(void) {
    const char *e;
    printf("%d\n", clamp_atoi("  42abc", &e));
    printf("rest: %s\n", e);
    printf("%d\n", clamp_atoi("999999999999", NULL));
    printf("%d\n", clamp_atoi("-999999999999", NULL));
    printf("%d\n", clamp_atoi("", NULL));
    return 0;
}
