def to_binary(n):
    if n == 0:
        return "0"
    negative = n < 0
    n = abs(n)
    digits = []
    while n > 0:
        digits.append("1" if n & 1 else "0")
        n >>= 1
    digits.reverse()
    return ("-" if negative else "") + "".join(digits)


