def primes_up_to(limit):
    if limit < 2:
        return
    sieve = bytearray([1]) * (limit + 1)
    sieve[0] = sieve[1] = 0
    n = 2
    while n * n <= limit:
        if sieve[n]:
            step = n
            start = n * n
            sieve[start:limit + 1:step] = b"\x00" * (((limit - start) // step) + 1)
        n += 1
    for candidate in range(2, limit + 1):
        if sieve[candidate]:
            yield candidate

