```c
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    for (size_t i = 0; i < len / 2; i++) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
}

int main(void) {
    char buf[] = "hello world";
    char empty[] = "";

    reverse_in_place(buf);
    reverse_in_place(empty);

    printf("%s\n", buf);    /* dlrow olleh */
    printf("[%s]\n", empty); /* [] */
    return 0;
}
```

`strlen` gives the byte count up to the null terminator, and the loop swaps symmetric pairs, so `len / 2` iterations is enough for both even and odd lengths. `buf` is a writable array, unlike a string literal, which is why `reverse_in_place` is safe here. This operates on bytes, so multi-byte UTF-8 sequences would be reversed incorrectly; a code-point-aware version would need to decode sequences first.

```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(int value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [this] { return closed_ || queue_.size() < capacity_; });
        if (closed_) return;
        queue_.push(value);
        not_empty_.notify_one();
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock, [this] { return closed_ || !queue_.empty(); });
        if (queue_.empty()) return std::nullopt;
        int value = queue_.front();
        queue_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mutex_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t capacity_;
    std::queue<int> queue_;
    std::mutex mutex_;
    std::condition_variable not_empty_, not_full_;
    bool closed_ = false;
};
```

Both waits use a predicate so they are immune to spurious wakeups. `push` returns early if `close()` has run, and `pop` returns `std::nullopt` once the queue is drained and closed. `close()` notifies both condition variables so blocked producers and consumers wake up and observe the flag. In a real program, call `close()` before joining consumer threads to avoid a deadlock.

```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        let mut data = Vec::with_capacity(capacity);
        data.resize_with(capacity, || None);
        RingBuffer { data, head: 0, len: 0 }
    }

    pub fn push(&mut self, value: T) {
        let cap = self.data.len();
        let idx = (self.head + self.len) % cap;
        self.data[idx] = Some(value);
        if self.len == cap {
            self.head = (self.head + 1) % cap; // drop oldest
        } else {
            self.len += 1;
        }
    }

    pub fn get(&self, i: usize) -> Option<&T> {
        if i >= self.len {
            return None;
        }
        self.data[(self.head + i) % self.data.len()].as_ref()
    }

    pub fn len(&self) -> usize {
        self.len
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    rb.push(1);
    rb.push(2);
    rb.push(3);
    rb.push(4); // overwrites 1
    assert_eq!(rb.len(), 3);
    assert_eq!(rb.get(0), Some(&2));
    assert_eq!(rb.get(2), Some(&4));
    assert_eq!(rb.get(3), None);
    println!("ok");
}
```

`head` is the index of the oldest element and `len` the live count. When the buffer is full, `push` writes at the computed slot and advances `head`, discarding the oldest value. `get` maps a logical index to a physical one with modular arithmetic, returning `None` out of bounds. `Vec<Option<T>>` lets arbitrary values be stored without a `Default` bound.

