#include <cmath>
#include <iomanip>
#include <iostream>
#include <vector>

int main() {
    std::vector<double> values;
    double x;
    while (std::cin >> x) {
        values.push_back(x);
    }

    if (values.empty()) {
        std::cout << "no data\n";
        return 0;
    }

    double sum = 0.0;
    for (double v : values) sum += v;
    const double mean = sum / static_cast<double>(values.size());

    double sq = 0.0;
    for (double v : values) {
        const double d = v - mean;
        sq += d * d;
    }
    const double stddev = std::sqrt(sq / static_cast<double>(values.size()));

    std::cout << std::fixed << std::setprecision(6)
              << mean << ' ' << stddev << '\n';
    return 0;
}
```

The input loop ends on EOF or on the first token that fails to parse as a double, matching `operator>>` semantics. The mean is computed first, then a second pass accumulates squared deviations; this single-pass-then-second-pass form is more numerically stable than `E[x^2] - (E[x])^2`, which cancels badly for large means. Population variance divides by `n`, not `n-1`. `setprecision(6)` fixes the output width so results are reproducible.

```python
import operator

OPS = {"+": (1, operator.add), "-": (1, operator.sub),
       "*": (2, operator.mul), "/": (2, operator.truediv)}


def evaluate(expr):
    """Evaluate an arithmetic expression. Raises ValueError on bad input."""
    values, ops = [], []

    def apply():
        if not ops or len(values) < 2:
            raise ValueError("malformed expression")
        fn = OPS[ops.pop()][1]
        b = values.pop()
        a = values.pop()
        values.append(fn(a, b))

    i, n = 0, len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit() or ch == '.':
            j = i
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            values.append(float(expr[i:j]))
            i = j
        elif ch in OPS:
            while ops and ops[-1] != '(' and OPS[ops[-1]][0] >= OPS[ch][0]:
                apply()
            ops.append(ch)
            i += 1
        elif ch == '(':
            ops.append(ch)
            i += 1
        elif ch == ')':
            while ops and ops[-1] != '(':
                apply()
            if not ops:
                raise ValueError("unbalanced parentheses")
            ops.pop()
            i += 1
        else:
            raise ValueError(f"unexpected character {ch!r}")

    while ops:
        if ops[-1] == '(':
            raise ValueError("unbalanced parentheses")
        apply()
    if len(values) != 1:
        raise ValueError("malformed expression")
    return values[0]


if __name__ == "__main__":
    assert evaluate("2 + 3 * 4") == 14.0
    assert evaluate("(2 + 3) * 4") == 20.0
    assert evaluate("10 / 4") == 2.5
    assert evaluate("2 * (3 + (4 - 1))") == 12.0
    try:
        evaluate("(1 + 2")
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
    print("ok")
```

Numbers are pushed onto the value stack; operators wait on an operator stack and are applied when a lower-precedence or equal-precedence operator arrives, giving left associativity. A `(` is a barrier that blocks the pop loop, and `)` drains until its matching `(`. Leftover parens or a value-stack size other than one raise `ValueError`. Division by zero propagates Python's `ZeroDivisionError`; catch it if the caller wants uniform errors.

