fn longest_common_prefix(words: &[String]) -> String {
    let first = match words.first() {
        Some(s) => s,
        None => return String::new(),
    };

    let mut end = first.len();
    for word in &words[1..] {
        let mut i = 0;
        let a = first.as_bytes();
        let b = word.as_bytes();
        while i < end && i < b.len() && a[i] == b[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    first[..end].to_string()
}

