```cpp
#include <cassert>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

bool has_cycle(Node* head) {
    Node* slow = head;
    Node* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            return true;
        }
    }
    return false;
}

int main() {
    Node a(1), b(2), c(3), d(4);
    a.next = &b;
    b.next = &c;
    c.next = &d;
    assert(!has_cycle(&a));

    d.next = &b;   // cycle back to b
    assert(has_cycle(&a));

    assert(!has_cycle(nullptr));
    return 0;
}
```

Floyd's cycle detection: the fast pointer moves two steps per slow step, so if a cycle exists they must eventually meet inside it. If `fast` reaches the end, there is no cycle.

