char *reverse_in_place(char *s) {
    if (s == NULL) {
        return NULL;
    }
    size_t i = 0;
    size_t j = strlen(s);
    while (i < j && j > 0) {
        --j;
        if (i >= j) {
            break;
        }
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
    }
    return s;
}

int main(void) {
    char a[] = "";
    assert(strcmp(reverse_in_place(a), "") == 0);

    char b[] = "x";
    assert(strcmp(reverse_in_place(b), "x") == 0);

    char c[] = "hello";
    assert(strcmp(reverse_in_place(c), "olleh") == 0);

    char d[] = "ab";
    assert(strcmp(reverse_in_place(d), "ba") == 0);

    printf("%s\n", c);
    return 0;
}
```

Swapping only while `i < j` leaves the middle character of an odd-length string untouched, and `strlen` on the empty string gives 0 so no swap occurs.

