def primes_below(n):
    """Yield all primes strictly less than n using a sieve of Eratosthenes."""
    if n <= 2:
        return
    sieve = bytearray([1]) * n
    sieve[0] = sieve[1] = 0
    i = 2
    while i * i < n:
        if sieve[i]:
            sieve[i * i::i] = bytearray(len(sieve[i * i::i]))
        i += 1
    for num in range(2, n):
        if sieve[num]:
            yield num


if __name__ == "__main__":
    assert list(primes_below(2)) == []
    assert list(primes_below(1)) == []
    assert list(primes_below(3)) == [2]
    print(list(primes_below(100))[:10])
```

