```cpp
#include <cstddef>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), count_(0) {}

    bool push(int value) {
        if (count_ == cap_) return false;
        buf_[(head_ + count_) % cap_] = value;
        ++count_;
        return true;
    }

    std::optional<int> pop() {
        if (count_ == 0) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }

private:
    std::vector<int> buf_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t count_;
};
```

A capacity of 0 makes `push` always fail and `pop` always return `nullopt`, so no modulo by zero occurs. Tracking `head_` and `count_` avoids keeping a separate tail index.

