```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return -1
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, 1)
    c.put(2, 2)
    assert c.get(1) == 1
    c.put(3, 3)          # evicts key 2
    assert c.get(2) == -1
    assert c.get(3) == 3
    c.put(4, 4)          # evicts key 1
    assert c.get(1) == -1
    assert c.get(4) == 4
    print("ok")
```

`OrderedDict` keeps insertion order and `move_to_end` is O(1), so both operations touch only constant-time bookkeeping. `popitem(last=False)` removes the least-recently used entry at the front. The `__len__` hook makes the size inspectable in tests and debugging.

```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

template <typename T>
class BlockingQueue {
public:
    explicit BlockingQueue(std::size_t cap) : cap_(cap) {}

    void push(T value) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [&] { return q_.size() < cap_; });
        q_.push(std::move(value));
        not_empty_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [&] { return !q_.empty(); });
        T v = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return v;
    }

    std::optional<T> try_pop() {
        std::unique_lock<std::mutex> lk(m_);
        if (q_.empty()) return std::nullopt;
        T v = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return v;
    }

private:
    std::size_t cap_;
    std::queue<T> q_;
    std::mutex m_;
    std::condition_variable not_full_, not_empty_;
};
```

`push` blocks while the queue is at capacity; `pop` blocks while empty; `try_pop` returns `std::nullopt` instead of blocking. The predicate form of `wait` guards against spurious wakeups. Instantiate with copyable or movable `T`; for move-only types, only rvalue pushes are used.

