#include <stddef.h>
#include <string.h>

/* Copies src into dst (capacity cap, always NUL-terminated).
 * Returns the number of characters actually copied, excluding the NUL.
 * If truncation occurred, the return value is less than strlen(src).
 */
size_t safe_copy(char *dst, size_t cap, const char *src) {
    if (dst == NULL || src == NULL) {
        return 0;
    }
    if (cap == 0) {
        return 0;
    }
    size_t n = 0;
    while (n + 1 < cap && src[n] != '\0') {
        dst[n] = src[n];
        n++;
    }
    dst[n] = '\0';
    return n;
}

#include <stdio.h>
int main(void) {
    char buf[8];
    size_t copied = safe_copy(buf, sizeof buf, "hello world");
    if (copied < strlen("hello world")) {
        printf("truncated: %s\n", buf);
    }
    char small[1];
    safe_copy(small, sizeof small, "x");
    if (small[0] != '\0') return 1;
    return 0;
}
