```python
import functools
import time


def retry(attempts=3, base_delay=0.1, max_delay=2.0, exceptions=(Exception,)):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            delay = base_delay
            last = None
            for attempt in range(1, attempts + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt == attempts:
                        break
                    time.sleep(min(delay, max_delay))
                    delay *= 2
            raise last
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base_delay=0)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("boom")
        return "done"

    assert flaky() == "done"
    assert calls["n"] == 3
    print("ok")
```

It retries up to `attempts` times, sleeping `base_delay`, doubled each time, capped at `max_delay`. The exception type is configurable, and the last error is re-raised if all attempts fail.

