bool balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.empty();
}

int main() {
    std::cout << std::boolalpha;
    std::cout << balanced("()[]{}") << "\n";   // true
    std::cout << balanced("([)]") << "\n";     // false
    std::cout << balanced("hello (world)") << "\n"; // true
    std::cout << balanced("(") << "\n";        // false
    return 0;
}
```

