struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

void print(const Node* head) {
    for (const Node* cur = head; cur != nullptr; cur = cur->next) {
        std::cout << cur->value << (cur->next ? " -> " : "\n");
    }
}

