    for (int v : {1, 2, 3, 4, 5}) {
        head = new Node(v);
    }
    // Build 5 -> 4 -> 3 -> 2 -> 1 in insertion order.
    head = reverse(head);
    print(head);
    while (head != nullptr) {
        Node* tmp = head;
        head = head->next;
        delete tmp;
    }
    return 0;
}
