```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.data = OrderedDict()

    def get(self, key):
        if key not in self.data:
            return None
        self.data.move_to_end(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.data.move_to_end(key)
        self.data[key] = value
        if len(self.data) > self.capacity:
            self.data.popitem(last=False)

    def keys(self):
        return list(self.data.keys())


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1          # a becomes most recent
    c.put("c", 3)                    # evicts b
    assert c.get("b") is None
    assert c.keys() == ["a", "c"]
    c.put("a", 99)                   # update existing
    assert c.get("a") == 99
    print("ok")
```

`OrderedDict` keeps insertion order and `move_to_end` promotes on every access. `popitem(last=False)` evicts the least-recently-used entry in O(1). All operations are O(1) average.

