    char stack[4096];
    int top = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0 || !match(stack[--top], c)) {
                printf("mismatch at index %d\n", i);
                return 1;
            }
        }
    }
    if (top != 0) {
        printf("unclosed bracket at index 0\n");
        return 1;
    }
    printf("balanced\n");
    return 0;
}
