#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;                              // max-heap, holds smaller half
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap, larger half
    int x, n = 0;
    while (std::cin >> x) {
        ++n;
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);

        // Rebalance: low may hold at most one more than high.
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }
    }

    if (n == 0) {
        std::cout << "no input\n";
        return 0;
    }
    if (n % 2 == 1) {
        std::cout << low.top() << "\n";
    } else {
        // Use double to avoid integer truncation on odd sums.
        std::cout << (low.top() + high.top()) / 2.0 << "\n";
    }
    return 0;
}
```

`low.top()` is the median for odd counts. For even counts the two middle values sit on top of each heap, and dividing by `2.0` gives `.5` results correctly.

