```

`flat_map(c.to_lowercase())` matters: a single uppercase char like `İ` can lower-case to more than one code point, so this keeps the mapping correct instead of using `to_ascii_lowercase`.

```python
from collections import OrderedDict
from typing import Optional


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: "OrderedDict[str, int]" = OrderedDict()

    def get(self, key: str) -> Optional[int]:
        if key not in self._data:
            return None
        self._data.move_to_end(key)   # mark as most recently used
        return self._data[key]

    def put(self, key: str, value: int) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least recently used

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1          # 'a' is now freshest, 'b' is next to evict
    c.put("c", 3)                    # evicts 'b'
    assert c.get("b") is None
    assert c.get("a") == 1
    assert c.get("c") == 3
    print("ok")
```

`move_to_end` is the whole trick: OrderedDict reads then keeps the ordering, so eviction is `popitem(last=False)` with no manual bookkeeping.

```c
#include <stdio.h>
#include <string.h>

char *reverse_in_place(char *s) {
    if (s == NULL) return NULL;
    size_t len = strlen(s);
    if (len < 2) return s;
    for (size_t i = 0, j = len - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
    return s;
}

int main(void) {
    char buf[] = "hello";
    printf("%s\n", reverse_in_place(buf));   // olleh

    char empty[] = "";
    printf("[%s]\n", reverse_in_place(empty)); // []

    char odd[] = "abcba";
    printf("%s\n", reverse_in_place(odd));    // abcba

    printf("%s\n", reverse_in_place(NULL));  // (null)
    return 0;
}
```

The loop stops when `i >= j`, so the middle character of an odd-length string is never swapped. `strlen` returns the length excluding the NUL terminator, which is why the last index is `len - 1`.

