use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("failed to read stdin");

    let mut counts: HashMap<String, u64> = HashMap::new();
    for word in input.split_whitespace() {
        let w: String = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !w.is_empty() {
            *counts.entry(w).or_insert(0) += 1;
        }
    }

    let mut pairs: Vec<(String, u64)> = counts.into_iter().collect();
    // Sort by count desc, then word asc.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    for (word, n) in pairs.iter().take(10) {
        println!("{n:>6}  {word}");
    }
}
```

The `.then_with` chained after the descending count comparison is what gives stable alphabetical tie-breaking; without it, equal counts would print in HashMap iteration order, which varies run to run.

```cpp
#include <algorithm>
#include <cassert>
#include <vector>

std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::merge(a.begin(), a.end(), b.begin(), b.end(), std::back_inserter(out));
    return out;
}

// Merges b INTO a, keeping a sorted. Uses extra space to stay O(n+m).
void merge_into(std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out = merge_sorted(a, b);
    a.swap(out);
}

int main() {
    assert(merge_sorted({1, 3, 5}, {2, 4, 6}) == std::vector<int>({1, 2, 3, 4, 5, 6}));
    assert(merge_sorted({}, {1, 2}) == std::vector<int>({1, 2}));
    assert(merge_sorted({}, {}) == std::vector<int>({}));
    assert(merge_sorted({2, 2, 3}, {2, 4}) == std::vector<int>({2, 2, 2, 3, 4}));

    std::vector<int> v{10, 30};
    merge_into(v, {20});
    assert(v == std::vector<int>({10, 20, 30}));
    return 0;
}
```

`std::merge` is stable and handles duplicates and empty ranges correctly. `merge_into` uses `swap` rather than copying so the caller's vector ends up holding the merged result without an extra deep copy.

```python
PAIRS = {')': '(', ']': '[', '}': '{'}

def check_balanced(s: str):
    """Return (True, None) if balanced, else (False, index_of_problem)."""
    stack = []
    for i, ch in enumerate(s):
        if ch in '([{':
            stack.append((ch, i))
        elif ch in PAIRS:
            if not stack or stack[-1][0] != PAIRS[ch]:
                return (False, i)
            stack.pop()
        # any other character is ignored
    if stack:
        return (False, stack[-1][1])   # unmatched opener, points at it
    return (True, None)


if __name__ == "__main__":
    assert check_balanced("") == (True, None)
    assert check_balanced("()[]{}") == (True, None)
    assert check_balanced("{[()]}") == (True, None)
    assert check_balanced("(a + b) * [c]") == (True, None)
    assert check_balanced("(]") == (False, 1)
    assert check_balanced("([)") == (False, 2)
    assert check_balanced("(()") == (False, 0)
    print("ok")
```

Closers must match the *top* of the stack, which catches `([)` at the `)` (index 2). A leftover stack means an opener was never closed, and we report the earliest still-open one, which is index 0 for `"(()"`.

