#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

template <std::size_t N>
class RingBuffer {
public:
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }
    static constexpr std::size_t capacity() { return N; }

    void push(double value) {
        if (full()) {
            throw std::overflow_error("ring buffer full");
        }
        data_[(head_ + size_) % N] = value;
        ++size_;
    }

    std::optional<double> pop() {
        if (empty()) {
            return std::nullopt;
        }
        double value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    if (!rb.empty() || rb.full()) return 1;
    if (rb.pop().has_value()) return 1;
    rb.push(1.5);
    rb.push(2.5);
    rb.push(3.5);
    if (!rb.full()) return 1;
    bool threw = false;
    try { rb.push(4.5); } catch (const std::overflow_error&) { threw = true; }
    if (!threw) return 1;
    if (rb.pop() != 1.5 || rb.pop() != 2.5 || rb.pop() != 3.5) return 1;
    if (!rb.empty()) return 1;
    std::cout << "ok\n";
    return 0;
}
