        std::istringstream in("1 -2\n3 4\n");
        const Stats s = accumulate(in);
        if (s.count != 4 || s.sum != 6) return 1;
        std::cout << std::fixed << std::setprecision(2)
                  << static_cast<double>(s.sum) / static_cast<double>(s.count)
                  << '\n';
    }

    std::istringstream real;
    const Stats s = accumulate(std::cin);
    if (s.count == 0) {
        std::cout << "no input\n";
        return 0;
    }
    std::cout << std::fixed << std::setprecision(2)
