int binary_search(const std::vector<int>& data, int key) {
    std::size_t lo = 0;
    std::size_t hi = data.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (data[mid] == key) {
            return static_cast<int>(mid);
        }
        if (data[mid] < key) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

int main() {
    std::vector<int> data{-7, -3, 0, 5, 9, 12, 40};
    if (binary_search(data, -7) != 0) return 1;
    if (binary_search(data, 40) != 6) return 2;
    if (binary_search(data, 5) != 3) return 3;
    if (binary_search(data, 8) != -1) return 4;

    std::vector<int> one{42};
    if (binary_search(one, 42) != 0) return 5;
    if (binary_search(one, 7) != -1) return 6;

    std::vector<int> none;
    if (binary_search(none, 1) != -1) return 7;

    std::printf("ok\n");
    return 0;
}
```
Using `lo + (hi - lo) / 2` avoids overflow that `(lo + hi) / 2` could hit on large indices, and the half-open range keeps a single-element array correct.

