use std::collections::HashMap;

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for raw in text.split(|c: char| !c.is_alphanumeric()) {
        if raw.is_empty() {
            continue;
        }
        let word = raw.to_lowercase();
        *counts.entry(word).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count descending, then word ascending for a stable order.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The quick brown fox. The FOX, the fox!";
    let got = top_words(text, 2);
    assert_eq!(got, vec![("the".to_string(), 3), ("fox".to_string(), 3)]);

    assert!(top_words("", 5).is_empty());
    assert!(top_words("a a b", 10).len() == 2);

    let unicode = "caf\u{e9} caf\u{e9}";
    assert_eq!(top_words(unicode, 1), vec![("caf\u{e9}".to_string(), 2)]);

    println!("ok");
}
