```rust
#[derive(Debug, PartialEq)]
pub enum PushError {
    Full,
    Empty,
}

pub struct BoundedStack<T> {
    data: Vec<T>,
    cap: usize,
}

impl<T> BoundedStack<T> {
    pub fn new(cap: usize) -> Self {
        BoundedStack { data: Vec::with_capacity(cap), cap }
    }

    pub fn push(&mut self, value: T) -> Result<(), PushError> {
        if self.data.len() >= self.cap {
            return Err(PushError::Full);
        }
        self.data.push(value);
        Ok(())
    }

    pub fn pop(&mut self) -> Result<T, PushError> {
        self.data.pop().ok_or(PushError::Empty)
    }

    pub fn len(&self) -> usize {
        self.data.len()
    }

    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }
}

fn main() {
    let mut stack = BoundedStack::new(2);
    assert!(stack.is_empty());
    assert_eq!(stack.pop(), Err(PushError::Empty));
    assert_eq!(stack.push(1), Ok(()));
    assert_eq!(stack.push(2), Ok(()));
    assert_eq!(stack.push(3), Err(PushError::Full));
    assert_eq!(stack.len(), 2);
    assert_eq!(stack.pop(), Ok(2));
    assert_eq!(stack.pop(), Ok(1));
    assert_eq!(stack.pop(), Err(PushError::Empty));
    println!("ok");
}
```
Capacity is checked before pushing, so overflow returns `Err(Full)` instead of reallocating past the bound. An empty stack never panics on `pop`.

