```rust
use std::collections::HashMap;

/// Count words case-insensitively, strip non-alphanumeric characters,
/// and return the `n` most frequent as (count, word) sorted descending.
pub fn top_words(text: &str, n: usize) -> Vec<(usize, String)> {
    let mut counts: HashMap<String, usize> = HashMap::new();

    for raw in text.split_whitespace() {
        let cleaned: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }

    let mut items: Vec<(usize, String)> =
        counts.into_iter().map(|(w, c)| (c, w)).collect();
    items.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
    items.truncate(n);
    items
}

fn main() {
    let text = "The cat, the CAT! A dog. the bird?";
    let top = top_words(text, 2);
    assert_eq!(top, vec![(3, "the".to_string()), (1, "a".to_string())]);
    assert!(top_words("", 5).is_empty());
    assert_eq!(top_words("one", 10).len(), 1);
    println!("{:?}", top);
}
```

Mapping to `(count, word)` pairs lets the tuple sort handle both keys: count descending, then word ascending as a deterministic tie-break. `truncate(n)` naturally does nothing when `n` exceeds the number of distinct words, and the empty string yields an empty vec.

```python
from collections import OrderedDict
from typing import Any, Optional


class LRUCache:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: "OrderedDict[Any, Any]" = OrderedDict()

    def get(self, key: Any) -> Optional[Any]:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: Any, value: Any) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1
    cache.put("c", 3)          # evicts "b", the least recently used
    assert cache.get("b") is None
    assert cache.get("a") == 1
    cache.put("c", 9)
    assert cache.get("c") == 9
    assert len(cache) == 2
    print("ok")
```

OrderedDict alone gives O(1) updates; `move_to_end` promotes a key on both read and write, and `popitem(last=False)` drops the oldest entry once capacity is exceeded. Re-writing an existing key refreshes its recency.

```c
#include <stdio.h>
#include <stdlib.h>

static int reverse_line(int c) {
    size_t cap = 64;
    size_t len = 0;
    char *buf = malloc(cap);
    if (!buf) {
        perror("malloc");
        exit(1);
    }

    while (c != EOF && c != '\n') {
        if (len == cap) {
            cap *= 2;
            char *grown = realloc(buf, cap);
            if (!grown) {
                free(buf);
                perror("realloc");
                exit(1);
            }
            buf = grown;
        }
        buf[len++] = (char)c;
        c = getchar();
    }

    for (size_t i = len; i > 0; i--) {
        putchar(buf[i - 1]);
    }
    free(buf);

    if (c == '\n') {
        putchar('\n');
        return 0;
    }
    return EOF;
}

int main(void) {
    int c = getchar();
    while (c != EOF) {
        c = reverse_line(c);
    }
    return 0;
}
```

Characters are read one at a time with `getchar`, so `reverse_line` receives the first byte after any prior newline and owns it. The buffer doubles on demand, so there is no fixed line limit. The final line is emitted reversed without appending a newline, and returning `EOF` from the last call ends the outer loop.

