use std::collections::HashMap;
use std::env;
use std::fs;

fn main() -> std::io::Result<()> {
    let path = env::args().nth(1).unwrap_or_else(|| "scores.csv".to_string());
    let content = fs::read_to_string(&path)?;

    let mut totals: HashMap<String, (f64, u32)> = HashMap::new();

    for (lineno, line) in content.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let mut parts = line.split(',');
        let name = parts.next().unwrap_or("").trim();
        let score_text = parts.next().unwrap_or("").trim();
        if name.is_empty() {
            continue;
        }
        let score: f64 = match score_text.parse() {
            Ok(v) => v,
            Err(_) => {
                eprintln!("line {}: skipping bad score {:?}", lineno + 1, score_text);
                continue;
            }
        };
        let entry = totals.entry(name.to_string()).or_insert((0.0, 0));
        entry.0 += score;
        entry.1 += 1;
    }

    let mut averages: Vec<(String, f64)> = totals
        .into_iter()
        .map(|(name, (sum, count))| (name, sum / count as f64))
        .collect();
    averages.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

    for (name, avg) in averages {
        println!("{},{:.2}", name, avg);
    }
    Ok(())
}
