```c
#include <stdio.h>
#include <string.h>

static const char *const ONES[] = {
    "zero", "one", "two", "three", "four", "five", "six",
    "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen",
    "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
};
static const char *const TENS[] = {
    "", "", "twenty", "thirty", "forty", "fifty",
    "sixty", "seventy", "eighty", "ninety"
};

static void append(char *buf, size_t size, const char *text) {
    if (strlen(buf) + strlen(text) < size) {
        strcat(buf, text);
    }
}

static void append_sep(char *buf, size_t size, const char *text) {
    if (buf[0] != '\0') {
        append(buf, size, " ");
    }
    append(buf, size, text);
}

static void under_1000(int n, char *buf, size_t size) {
    if (n >= 100) {
        append_sep(buf, size, ONES[n / 100]);
        append_sep(buf, size, "hundred");
        n %= 100;
    }
    if (n >= 20) {
        append_sep(buf, size, TENS[n / 10]);
        if (n % 10) {
            append_sep(buf, size, ONES[n % 10]);
        }
    } else if (n > 0) {
        append_sep(buf, size, ONES[n]);
    }
}

// buf must hold at least 128 bytes for the largest input.
const char *int_to_words(int value, char *buf, size_t size) {
    buf[0] = '\0';
    if (value == 0) {
        append(buf, size, "zero");
        return buf;
    }

    unsigned int magnitude = (value < 0) ? (unsigned int)(-(long long)value)
                                         : (unsigned int)value;

    if (value < 0) {
        append_sep(buf, size, "minus");
    }

    if (magnitude >= 1000000) {
        under_1000((int)(magnitude / 1000000), buf, size);
        append_sep(buf, size, "million");
        magnitude %= 1000000;
    }
    if (magnitude >= 1000) {
        under_1000((int)(magnitude / 1000), buf, size);
        append_sep(buf, size, "thousand");
        magnitude %= 1000;
    }
    if (magnitude > 0) {
        under_1000((int)magnitude, buf, size);
    }
    return buf;
}

int main(void) {
    char buf[128];
    printf("%s\n", int_to_words(0, buf, sizeof buf));
    printf("%s\n", int_to_words(-7, buf, sizeof buf));
    printf("%s\n", int_to_words(1005, buf, sizeof buf));
    printf("%s\n", int_to_words(-123456789, buf, sizeof buf));
    return 0;
}
```

Converting to `unsigned int` via `long long` avoids undefined behaviour on `INT_MIN`. `append_sep` inserts a space only when the buffer is non-empty, so there are no doubled or leading spaces, and the bounds check in `append` prevents overflow even though 128 bytes is sufficient for this range.

```cpp
#include <cassert>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& v) {
        if (size_ == N) return false;
        buf_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T v = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }

private:
    T buf_[N]{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.push(1));
    assert(rb.push(2));
    assert(rb.push(3));
    assert(!rb.push(4));            // full
    assert(rb.pop() == 1);
    assert(rb.push(4));             // wrap-around
    assert(rb.pop() == 2);
    assert(rb.pop() == 3);
    assert(rb.pop() == 4);
    assert(!rb.pop().has_value());  // empty
    std::cout << "ok\n";
}
```
`push` refuses when full instead of overwriting; `pop` returns `std::nullopt` when empty.

