```rust
use std::collections::{HashMap, VecDeque};

struct LruCache {
    cap: usize,
    map: HashMap<i32, i32>,
    order: VecDeque<i32>,
}

impl LruCache {
    fn new(cap: usize) -> Self {
        LruCache { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    fn touch(&mut self, key: i32) {
        if let Some(pos) = self.order.iter().position(|&k| k == key) {
            self.order.remove(pos);
        }
        self.order.push_back(key);
    }

    fn get(&mut self, key: i32) -> Option<i32> {
        let v = *self.map.get(&key)?;
        self.touch(key);
        Some(v)
    }

    fn put(&mut self, key: i32, value: i32) {
        if self.map.insert(key, value).is_none() && self.map.len() > self.cap {
            if let Some(old) = self.order.pop_front() {
                self.map.remove(&old);
            }
        }
        self.touch(key);
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 1);
    c.put(2, 2);
    assert_eq!(c.get(1), Some(1)); // 1 becomes most recent
    c.put(3, 3);                   // evicts 2
    assert_eq!(c.get(2), None);
    assert_eq!(c.get(3), Some(3));
    println!("ok");
}
```
Eviction happens only on insert of a new key, so `get` never changes the size.

