def parse_config(text: str) -> tuple[dict, str | None]:
    cfg: dict[str, str] = {}
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            return cfg, f"line {lineno}: missing '=' in {raw!r}"
        key, _, value = line.partition("=")
        key = key.strip()
        value = value.strip()
        if not key:
            return cfg, f"line {lineno}: empty key in {raw!r}"
        if key in cfg:
            return cfg, f"line {lineno}: duplicate key {key!r}"
        cfg[key] = value
    return cfg, None


