#include <stdio.h>
#include <string.h>

#define MAX_WORDS 64
#define MAX_LEN 256

static void reverse_words(char *line) {
    char *words[MAX_WORDS];
    int n = 0;

    char *tok = strtok(line, " \t");
    while (tok != NULL && n < MAX_WORDS) {
        words[n++] = tok;
        tok = strtok(NULL, " \t");
    }

    for (int i = n - 1; i >= 0; --i) {
        fputs(words[i], stdout);
        if (i > 0) fputc(' ', stdout);
    }
    fputc('\n', stdout);
}

int main(void) {
    char buf[MAX_LEN];

    if (fgets(buf, sizeof buf, stdin) == NULL) {
        fputc('\n', stdout);
        return 0;
    }
    buf[strcspn(buf, "\n")] = '\0';

    reverse_words(buf);
    return 0;
}
