#include <cstdio>
#include <cstdint>

static int popcount8(std::uint8_t b) {
    // Kernighan's algorithm on a byte.
    int count = 0;
    while (b) {
        b &= static_cast<std::uint8_t>(b - 1);
        ++count;
    }
    return count;
}

int main() {
    unsigned char buf[4096];
    std::size_t n;
    long long total = 0;

    while ((n = std::fread(buf, 1, sizeof(buf), stdin)) > 0) {
        for (std::size_t i = 0; i < n; ++i) {
            total += popcount8(buf[i]);
        }
    }

    std::printf("%lld\n", total);
    return 0;
}
