use std::io::{self, BufRead, Write};

fn reverse_words(line: &str) -> String {
    let mut out = String::with_capacity(line.len());
    let mut token_start: Option<usize> = None;
    let bytes = line.as_bytes();

    for (i, c) in line.char_indices() {
        if c.is_whitespace() {
            if let Some(start) = token_start.take() {
                if is_ascii_range(bytes, start, i) {
                    out.push_str(&line[start..i].chars().rev().collect::<String>());
                } else {
                    out.push_str(&line[start..i]);
                }
            }
            out.push(c);
        } else if token_start.is_none() {
            token_start = Some(i);
        }
    }
    if let Some(start) = token_start {
        out.push_str(&line[start..]);
    }
    out
}

fn is_ascii_range(bytes: &[u8], start: usize, end: usize) -> bool {
    bytes[start..end].iter().all(|b| b.is_ascii())
}

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = stdout.lock();

    for line in stdin.lock().lines() {
        let line = line?;
        writeln!(out, "{}", reverse_words(&line))?;
    }
    Ok(())
