#include <cstdio>
#include <cstdlib>

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s <rows>\n", argv[0]);
        return 2;
    }

    char* end = nullptr;
    long rows = std::strtol(argv[1], &end, 10);
    if (*end != '\0' || rows < 0) {
        std::fprintf(stderr, "rows must be a non-negative integer\n");
        return 2;
    }

    if (rows == 0) {
        return 0;  // empty triangle, no output
    }

    const int max_rows = 1000;  // guard against absurd allocations
    if (rows > max_rows) {
        std::fprintf(stderr, "rows must be <= %d\n", max_rows);
        return 2;
    }

    // Row n has n+1 entries; build bottom-up with additions only.
    for (long n = 0; n < rows; ++n) {
        long* row = static_cast<long*>(std::malloc((n + 1) * sizeof(long)));
        row[0] = 1;
        for (long k = 1; k < n; ++k) {
            row[k] = row[k - 1] * (n - k + 1) / k;  // no factorials used
        }
        row[n] = 1;
        for (long k = 0; k <= n; ++k) {
            std::printf("%ld%s", row[k], k == n ? "\n" : " ");
        }
        std::free(row);
    }
    return 0;
}
