def ipv4_to_int(addr: str) -> int:
    """Convert '192.168.0.1' to an unsigned 32-bit int, or raise ValueError."""
    parts = addr.split(".")
    if len(parts) != 4:
        raise ValueError(f"expected 4 octets, got {len(parts)}")
    value = 0
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"non-numeric octet: {part!r}")
        if len(part) > 1 and part[0] == "0":
            raise ValueError(f"leading zero in octet: {part!r}")
        octet = int(part)
        if octet > 255:
            raise ValueError(f"octet out of range: {octet}")
        value = (value << 8) | octet
    return value


if __name__ == "__main__":
