def fib(n: int) -> int:
    """Return F(n) for n >= 0 using O(log n) fast doubling."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def _pair(k: int) -> tuple[int, int]:
        # returns (F(k), F(k+1))
        if k == 0:
            return (0, 1)
        a, b = _pair(k >> 1)
        c = a * (2 * b - a)          # F(2m)
        d = a * a + b * b            # F(2m+1)
        if k & 1:
            return (d, c + d)
        return (c, d)

    return _pair(n)[0]


def fib_naive(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


if __name__ == "__main__":
    for i in range(30):
        assert fib(i) == fib_naive(i), i
    print(fib(10))    # 55
    print(fib(90))    # 2880067194370816120
