// Byte-level sliding window; multibyte UTF-8 bytes are treated as distinct units.
std::size_t longest_unique_run(const std::string& s) {
    std::array<int, 256> last{};
    last.fill(-1);
    std::size_t best = 0, start = 0;
    for (std::size_t i = 0; i < s.size(); ++i) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        if (last[c] >= 0 && static_cast<std::size_t>(last[c]) >= start) {
            start = static_cast<std::size_t>(last[c]) + 1;
        }
        last[c] = static_cast<int>(i);
        best = std::max(best, i - start + 1);
    }
    return best;
}

int main() {
    std::cout << longest_unique_run("") << '\n';          // 0
    std::cout << longest_unique_run("abcabcbb") << '\n';  // 3
    std::cout << longest_unique_run("bbbbb") << '\n';     // 1
    std::cout << longest_unique_run("pwwkew") << '\n';    // 3
    return 0;
}
