#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), tail_(0), size_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool push(const T& value) {
        if (size_ == buf_.size()) return false;      // full: reject
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % buf_.size();
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;         // empty: no value
        T value = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::vector<T> buf_;
    std::size_t head_, tail_, size_;
};

int main() {
    RingBuffer<int> rb(3);
    std::cout << rb.pop().has_value() << '\n';   // 0
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << '\n';  // 111
    std::cout << rb.push(4) << '\n';             // 0 (full)
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n';                           // 1 2 3
    return 0;
}
