template <typename T>
class Stack {
    std::vector<T> data;
public:
    void push(const T& v) { data.push_back(v); }
    bool empty() const { return data.empty(); }
    T pop() {
        T v = data.back();
        data.pop_back();
        return v;
    }
};

bool balanced(const std::string& s) {
    Stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) return false;
        }
    }
    return st.empty();
}

int main() {
