std::string reverse_words(std::string s) {
    // trim
    size_t start = s.find_first_not_of(' ');
    if (start == std::string::npos) return "";
    size_t end = s.find_last_not_of(' ');
    std::string t = s.substr(start, end - start + 1);

    std::reverse(t.begin(), t.end());
    size_t i = 0;
    while (i < t.size()) {
        size_t j = t.find(' ', i);
        if (j == std::string::npos) j = t.size();
        std::reverse(t.begin() + i, t.begin() + j);
        i = j + 1;
    }
    return t;
}

int main() {
    std::cout << reverse_words("  hello   world  ") << '\n'; // "world hello"
    std::cout << reverse_words("one") << '\n';              // "one"
    std::cout << reverse_words("   ") << '\n';              // ""
    return 0;
}
