#include <vector>
#include <iostream>
#include <cassert>

std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        // <= keeps duplicates from both sides and keeps the merge stable.
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 3, 7};
    std::vector<int> b{2, 3, 8};
    auto merged = merge_sorted(a, b);
    std::vector<int> expected{1, 2, 3, 3, 3, 7, 8};
    assert(merged == expected);

    // Empty inputs are valid.
    assert(merge_sorted({}, b) == b);
    assert(merge_sorted(a, {}).size() == a.size());

    for (int v : merged) std::cout << v << ' ';
    std::cout << '\n';
    return 0;
}
```
`reserve` avoids reallocations. Returning by value relies on move semantics in C++11 and later, so no deep copy happens on return.

