use std::env;

fn mat_mul(a: [[u128; 2]; 2], b: [[u128; 2]; 2]) -> [[u128; 2]; 2] {
    let mut r = [[0u128; 2]; 2];
    for i in 0..2 {
        for j in 0..2 {
            for k in 0..2 {
                r[i][j] = r[i][j].wrapping_add(a[i][k].wrapping_mul(b[k][j]));
            }
        }
    }
    r
}

fn mat_pow(mut base: [[u128; 2]; 2], mut exp: u64) -> [[u128; 2]; 2] {
    let mut result = [[1, 0], [0, 1]];
    while exp > 0 {
        if exp & 1 == 1 {
            result = mat_mul(result, base);
        }
        base = mat_mul(base, base);
        exp >>= 1;
    }
    result
}

fn fib(n: u64) -> u128 {
    if n == 0 {
        return 0;
    }
    // [[1,1],[1,0]]^n has F(n+1) top-left, F(n) top-right.
    mat_pow([[1, 1], [1, 0]], n)[0][1]
}

fn main() {
    let n: u64 = env::args()
        .nth(1)
        .and_then(|s| s.parse().ok())
        .unwrap_or(90);

    assert_eq!(fib(0), 0);
    assert_eq!(fib(1), 1);
    assert_eq!(fib(10), 55);
    assert_eq!(fib(50), 12_586_269_025);
    assert_eq!(fib(90), 2_880_067_194_370_816_120);

    println!("fib({n}) = {}", fib(n));
}
```
`wrapping_*` avoids panicking on overflow for indices past ~186; callers that care should check bounds. The assertions cover F(90), the largest value known-fits in u128 at index 90.

```cpp
#include <list>
#include <unordered_map>
#include <iostream>
#include <optional>

class LRUCache {
public:
    explicit LRUCache(std::size_t capacity) : cap_(capacity) {}

    std::optional<int> get(int key) {
        auto it = index_.find(key);
        if (it == index_.end()) return std::nullopt;
        // Move to front on access.
        order_.splice(order_.begin(), order_, it->second);
        return it->second->second;
    }

    void put(int key, int value) {
        if (auto it = index_.find(key); it != index_.end()) {
            it->second->second = value;
            order_.splice(order_.begin(), order_, it->second);
            return;
        }
        if (order_.size() == cap_) {
            int victim = order_.back().first;
            order_.pop_back();
            index_.erase(victim);
        }
        order_.emplace_front(key, value);
        index_[key] = order_.begin();
    }

private:
    std::size_t cap_;
    std::list<std::pair<int, int>> order_;  // front = most recent
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> index_;
};

int main() {
    LRUCache c(2);
    c.put(1, 1);
    c.put(2, 2);
    std::cout << *c.get(1) << '\n';  // 1, key 1 now most recent
    c.put(3, 3);                      // evicts key 2
    std::cout << (c.get(2) ? "hit" : "miss") << '\n';  // miss
    std::cout << *c.get(3) << '\n';  // 3
    return 0;
}
```
`splice` moves an existing node to the front in O(1), so get and put are O(1). The map stores list iterators, which stay valid across splice and emplace.

