import os
from collections import defaultdict


def ext_sizes(root: str) -> list[tuple[str, int]]:
    totals: dict[str, int] = defaultdict(int)
    for dirpath, dirnames, filenames in os.walk(root):
        for name in filenames:
            path = os.path.join(dirpath, name)
            try:
                size = os.path.getsize(path)
            except OSError:
                # Broken symlink or permission problem: skip, don't crash.
                continue
            # os.path.splitext handles dotfiles like '.gitignore' -> ('.gitignore', '')
            ext = os.path.splitext(name)[1].lower() or "<none>"
            totals[ext] += size
    return sorted(totals.items(), key=lambda kv: kv[1], reverse=True)


def human(n: int) -> str:
    for unit in ("B", "KiB", "MiB", "GiB", "TiB"):
        if n < 1024 or unit == "TiB":
            return f"{n:.1f} {unit}" if unit != "B" else f"{n} B"
        n /= 1024
    return f"{n} B"


if __name__ == "__main__":
    import sys
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    for ext, size in ext_sizes(target):
        print(f"{human(size):>12}  {ext}")
```
Run `python ext_report.py /some/dir`. Files without an extension are bucketed under `<none>`; permission errors and broken symlinks are skipped rather than aborting the walk.

