#include <stdexcept>
#include <string>

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "usage: " << argv[0] << " <int>...\n";
        return 2;
    }
    long long min = 0, max = 0, sum = 0;
    std::size_t count = 0;
    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        try {
            std::size_t pos = 0;
            long long v = std::stoll(arg, &pos);
            if (pos != arg.size()) throw std::invalid_argument(arg);
            if (count == 0) { min = max = v; }
            else { if (v < min) min = v; if (v > max) max = v; }
            sum += v;
            ++count;
        } catch (const std::exception&) {
            std::cerr << "error: '" << arg << "' is not an integer\n";
            return 1;
        }
    }
    std::cout << "min=" << min << " max=" << max
              << " avg=" << (static_cast<double>(sum) / count) << '\n';
    return 0;
}
