#include <iostream>
#include <stack>
#include <string>

bool balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                st.push(c);
                break;
            case ')': case ']': case '}':
                if (st.empty()) return false;
                char open = st.top();
                st.pop();
                if ((c == ')' && open != '(') ||
                    (c == ']' && open != '[') ||
                    (c == '}' && open != '{')) {
                    return false;
                }
                break;
            default:
                break;
        }
    }
    return st.empty();
}

int main() {
    std::cout << balanced("{[()]}") << '\n';  // 1
    std::cout << balanced("([)]") << '\n';    // 0
    std::cout << balanced("(((") << '\n';     // 0
    std::cout << balanced("") << '\n';        // 1
    return 0;
}
