from typing import List, Tuple


def covered_length(intervals: List[Tuple[int, int]]) -> int:
    """Total length covered by a set of possibly overlapping [start, end) intervals."""
    if not intervals:
        return 0

    merged = []
    for start, end in sorted(intervals):
        if end <= start:
            continue
        if merged and start <= merged[-1][1]:
            prev_start, prev_end = merged[-1]
            merged[-1] = (prev_start, max(prev_end, end))
        else:
            merged.append((start, end))

    return sum(end - start for start, end in merged)


if __name__ == "__main__":
    assert covered_length([(1, 3), (2, 6), (8, 10)]) == 7
    assert covered_length([]) == 0
    assert covered_length([(5, 5)]) == 0
    assert covered_length([(0, 10), (2, 3), (4, 5)]) == 10
    assert covered_length([(3, 1)]) == 0
    print("all tests passed")
