#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

template <typename T>
class CircularBuffer {
public:
    explicit CircularBuffer(std::size_t capacity)
        : data_(capacity), head_(0), size_(0) {}

    bool push(const T& value) {
        if (data_.empty()) return false;
        std::size_t tail = (head_ + size_) % data_.size();
        data_[tail] = value;
        if (size_ == data_.size()) {
            head_ = (head_ + 1) % data_.size();
        } else {
            ++size_;
        }
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % data_.size();
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == data_.size() && !data_.empty(); }

private:
    std::vector<T> data_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    CircularBuffer<int> buf(3);
    if (buf.pop().has_value()) { std::cerr << "pop on empty should be nullopt\n"; return 1; }

    for (int i = 1; i <= 4; ++i) {
        if (!buf.push(i)) { std::cerr << "push failed\n"; return 1; }
    }
    // Capacity 3, pushed 4 -> oldest (1) was overwritten.
    if (!buf.full() || buf.size() != 3) { std::cerr << "bad state\n"; return 1; }

    for (int expected = 2; expected <= 4; ++expected) {
        auto v = buf.pop();
        if (!v.has_value() || *v != expected) { std::cerr << "bad order\n"; return 1; }
    }
    if (!buf.empty()) { std::cerr << "buffer should be empty\n"; return 1; }

    std::cout << "all tests passed\n";
    return 0;
}
