// Writes a probe file that intentionally defines a name clashing with std,
// then compiles it to see whether `using namespace std;` causes an ambiguity.
static bool clash_detected(const std::string& compiler) {
    const char* probe = "/tmp/xt_luna_clash_probe.cpp";
    {
        std::ofstream out(probe);
        if (!out) return false;
        out << "#include <cstdio>\n"
               "using namespace std;\n"
               "int count;\n"      // std has std::count
               "int main() { count = 1; printf(\"%d\\n\", count); return 0; }\n";
    }
    std::string cmd = compiler + " -fsyntax-only " + probe + " 2>/dev/null";
    int rc = std::system(cmd.c_str());
    std::remove(probe);
    return rc != 0;
}

int main(int argc, char** argv) {
    const std::string compiler = argc > 1 ? argv[1] : "g++";
    if (clash_detected(compiler)) {
        std::printf("clash detected with %s\n", compiler.c_str());
        return 0;
    }
    std::printf("no clash for %s\n", compiler.c_str());
    return 0;
}
