/// Check whether brackets are balanced. On failure return (position, reason).
pub fn check_balance(input: &str) -> Result<(), (usize, String)> {
    let mut stack: Vec<(char, usize)> = Vec::new();

    for (idx, ch) in input.char_indices() {
        match ch {
            '(' | '[' | '{' => stack.push((ch, idx)),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some((open, _)) if open == expected => {}
                    Some((open, _)) => {
                        return Err((idx, format!("expected '{}' before '{}'",
                            match open { '(' => ')', '[' => ']', _ => '}' }, ch)));
                    }
                    None => return Err((idx, format!("unmatched '{}'", ch))),
                }
            }
            _ => {}
        }
    }

    match stack.pop() {
        Some((open, pos)) => Err((pos, format!("unclosed '{}'", open))),
        None => Ok(()),
    }
}

fn main() {
    assert_eq!(check_balance("a(b[c]{d})e"), Ok(()));
    assert_eq!(check_balance(""), Ok(()));
    assert_eq!(check_balance("([)]").is_err(), true);
    let (pos, _) = check_balance("abc(def").unwrap_err();
    assert_eq!(pos, 3);
    let (pos, _) = check_balance("ab)").unwrap_err();
    assert_eq!(pos, 2);
    println!("all tests passed");
}
