import re

_TOKEN = re.compile(r"\s*(\d+|[-+*/()])")


def evaluate(expr: str) -> float:
    """Evaluate an integer expression with + - * / and parentheses.

    Uses a shunting-yard pass to postfix, then evaluates the postfix form.
    Division is real division. Raises ValueError on malformed input.
    """
    tokens = _tokenize(expr)
    postfix = _to_postfix(tokens)
    return _eval_postfix(postfix)


def _tokenize(expr: str):
    tokens, pos = [], 0
    while pos < len(expr):
        m = _TOKEN.match(expr, pos)
        if not m:
            raise ValueError(f"unexpected character at {pos}: {expr[pos]!r}")
        tokens.append(m.group(1))
        pos = m.end()
    return tokens


def _to_postfix(tokens):
    prec = {"+": 1, "-": 1, "*": 2, "/": 2}
    out, ops = [], []
    for tok in tokens:
        if tok.isdigit():
            out.append(tok)
        elif tok in prec:
            while ops and ops[-1] in prec and prec[ops[-1]] >= prec[tok]:
                out.append(ops.pop())
            ops.append(tok)
        elif tok == "(":
            ops.append(tok)
        elif tok == ")":
            while ops and ops[-1] != "(":
                out.append(ops.pop())
            if not ops:
                raise ValueError("unbalanced ')'")
            ops.pop()
    while ops:
        if ops[-1] == "(":
            raise ValueError("unbalanced '('")
        out.append(ops.pop())
    return out


def _eval_postfix(postfix):
    stack = []
    for tok in postfix:
        if tok.isdigit():
            stack.append(float(tok))
        else:
            if len(stack) < 2:
                raise ValueError("not enough operands")
            b, a = stack.pop(), stack.pop()
            if tok == "+": stack.append(a + b)
            elif tok == "-": stack.append(a - b)
            elif tok == "*": stack.append(a * b)
            else:
                if b == 0:
                    raise ValueError("division by zero")
                stack.append(a / b)
    if len(stack) != 1:
        raise ValueError("leftover operands")
    return stack[0]


if __name__ == "__main__":
    assert evaluate("3 + 4 * 2") == 11
    assert evaluate("(3 + 4) * 2") == 14
    assert evaluate("10 / 4") == 2.5
    assert evaluate("2 * (3 + (4 - 1))") == 12
    try:
        evaluate("(1 + 2")
        raise AssertionError("expected ValueError")
    except ValueError:
        pass
    print("all tests passed")
```

