use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let key = word.to_lowercase();
        *counts.entry(key).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Highest count first; ties broken alphabetically for deterministic output.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basics() {
        let text = "the quick The QUICK brown";
        let got = top_words(text, 2);
        assert_eq!(got, vec![("quick".to_string(), 2), ("the".to_string(), 2)]);
    }

    #[test]
    fn empty() {
        assert!(top_words("", 5).is_empty());
    }
}
```

`to_lowercase` folds case before counting, so "The" and "the" merge. Sorting by count then by word makes the output stable across runs; `truncate` handles `n` larger than the distinct-word count.

```c
#include <stdio.h>
#include <stdint.h>

#define MOD 1000000007ULL

static void fib_pair(unsigned long long n, unsigned long long *a,
                     unsigned long long *b) {
    if (n == 0) {
        *a = 0;
        *b = 1;
        return;
    }
    unsigned long long x, y;
    fib_pair(n >> 1, &x, &y);

    unsigned long long c = (x * ((2 * y % MOD + MOD - x) % MOD)) % MOD;
    unsigned long long d = (x * x % MOD + y * y % MOD) % MOD;

    if (n & 1ULL) {
        *a = d;
        *b = (c + d) % MOD;
    } else {
        *a = c;
        *b = d;
    }
}

int main(void) {
    unsigned long long n;
    while (scanf("%llu", &n) == 1) {
        unsigned long long a, b;
        fib_pair(n, &a, &b);
        printf("F(%llu) mod %llu = %llu\n", n, MOD, a);
    }
    return 0;
}
```

Fast doubling computes F(2k) and F(2k+1) from F(k), F(k+1) in O(log n), so 10^18 needs about 60 steps. The subtraction term `(2*y - x)` is adjusted with `+ MOD` before the final mod to keep the intermediate unsigned value positive.

