```cpp
#include <cstddef>
#include <stdexcept>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), size_(0) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be > 0");
        }
    }

    void push(const T& value) {
        buf_[(head_ + size_) % cap_] = value;
        if (size_ < cap_) {
            ++size_;
        } else {
            head_ = (head_ + 1) % cap_;  // overwrite oldest
        }
    }

    std::vector<T> last_n(std::size_t n) const {
        if (n > size_) n = size_;
        std::vector<T> out;
        out.reserve(n);
        for (std::size_t i = size_ - n; i < size_; ++i) {
            out.push_back(buf_[(head_ + i) % cap_]);
        }
        return out;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<T> buf_;
    std::size_t cap_, head_, size_;
};
```

`head_` points at the oldest element while `size_` tracks occupancy, so `last_n` walks the newest `n` in order. When full, advancing `head_` drops the oldest entry; the modulo keeps indices wrapped without extra branching.

