        print(f"{l:>7} {w:>7} {c:>7} {path}")
        totals[0] += l
        totals[1] += w
        totals[2] += c
    if len(argv) > 1:
        print(f"{totals[0]:>7} {totals[1]:>7} {totals[2]:>7} total")
    return 0

if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
```

