#include <stdio.h>
#include <string.h>

int is_valid_ipv4(const char *s) {
    int parts = 0;
    while (*s) {
        int val = 0, digits = 0;
        while (*s >= '0' && *s <= '9') {
            if (digits == 0 && *s == '0' && s[1] >= '0' && s[1] <= '9') return 0;
            val = val * 10 + (*s - '0');
            ++digits;
            ++s;
            if (digits > 3) return 0;
        }
        if (digits == 0 || val > 255) return 0;
        ++parts;
        if (*s == '.') {
            ++s;
            if (*s == '\0') return 0;
        } else if (*s != '\0') {
            return 0;
        }
    }
    return parts == 4;
}

int main(void) {
    const char *tests[] = {"192.168.0.1", "0.0.0.0", "256.1.1.1",
                           "01.2.3.4", "1.2.3", "1.2.3.4.5", "a.b.c.d"};
    for (int i = 0; i < 7; ++i)
        printf("%s -> %s\n", tests[i], is_valid_ipv4(tests[i]) ? "valid" : "invalid");
    return 0;
}
