use std::collections::HashMap;

struct LruCache {
    cap: usize,
    map: HashMap<i32, usize>, // key -> node index
    nodes: Vec<Node>,
    head: Option<usize>,
    tail: Option<usize>,
}

struct Node {
    key: i32,
    value: i32,
    prev: Option<usize>,
    next: Option<usize>,
}

impl LruCache {
    fn new(cap: usize) -> Self {
        LruCache { cap, map: HashMap::new(), nodes: Vec::new(), head: None, tail: None }
    }

    fn unlink(&mut self, idx: usize) {
        let (p, n) = (self.nodes[idx].prev, self.nodes[idx].next);
        if let Some(p) = p { self.nodes[p].next = n; } else { self.head = n; }
        if let Some(n) = n { self.nodes[n].prev = p; } else { self.tail = p; }
    }

    fn push_front(&mut self, idx: usize) {
        self.nodes[idx].prev = None;
        self.nodes[idx].next = self.head;
        if let Some(h) = self.head { self.nodes[h].prev = Some(idx); }
        self.head = Some(idx);
        if self.tail.is_none() { self.tail = Some(idx); }
    }

    fn get(&mut self, key: i32) -> Option<i32> {
        let idx = *self.map.get(&key)?;
        self.unlink(idx);
        self.push_front(idx);
        Some(self.nodes[idx].value)
    }

    fn put(&mut self, key: i32, value: i32) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].value = value;
            self.unlink(idx);
            self.push_front(idx);
            return;
        }
        if self.map.len() == self.cap {
            if let Some(t) = self.tail {
                let old = self.nodes[t].key;
                self.unlink(t);
                self.map.remove(&old);
            }
        }
        let idx = self.nodes.len();
        self.nodes.push(Node { key, value, prev: None, next: None });
        self.map.insert(key, idx);
        self.push_front(idx);
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 1);
    c.put(2, 2);
    assert_eq!(c.get(1), Some(1));
    c.put(3, 3); // evicts key 2
    assert_eq!(c.get(2), None);
    assert_eq!(c.get(3), Some(3));
    println!("ok");
}
```

