`OrderedDict.move_to_end` marks recent use and `popitem(last=False)` drops the oldest. Both `get` and an overwrite refresh recency, which is what an LRU is supposed to guarantee.

```c
#include <stdio.h>
#include <string.h>

/* Reverse a UTF-8 string in place, keeping codepoints intact. */
static void reverse_utf8(char *s) {
    size_t len = strlen(s);
    for (size_t i = 0, j = len; i + 1 < j; ) {
        /* j points just past the last unprocessed codepoint. */
        size_t a = i;
        size_t b = j - 1;
        while (b > 0 && ((unsigned char)s[b] & 0xC0) == 0x80) --b; /* back to start byte */
        size_t a_len = 1;
        while (a + a_len < len && ((unsigned char)s[a + a_len] & 0xC0) == 0x80) ++a_len;
        size_t b_len = j - b;

        /* Rotate the two codepoint blocks [a,a+a_len) and [b,j). */
        char tmp[4];
        memcpy(tmp, s + b, b_len);
        memmove(s + a + b_len, s + a, j - b - b_len);
        memcpy(s + a, tmp, b_len);
        j = a;
        i = a + b_len;
    }
}

int main(void) {
    char ascii[] = "hello";
    char unicode[] = "caf\xC3\xA9 \xE2\x82\xAC";
    reverse_utf8(ascii);
    reverse_utf8(unicode);
    printf("%s\n", ascii);
    printf("%s\n", unicode);
    return 0;
}
```

Each iteration locates the start byte of the last remaining codepoint using the `0x80` continuation-bit mask, saves it, shifts the middle, and writes it at the front. ASCII fast-paths to one byte per step, so `"hello"` becomes `"olleh"` while the multi-byte `é` and `€` stay intact.

