        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    T pop_front() {
        if (size_ == 0) throw std::underflow_error("pop on empty ring buffer");
        std::size_t idx = (head_ + N - size_) % N;
        --size_;
        return data_[idx];
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    static_assert(N > 0, "capacity must be positive");
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    if (rb.pop_front() != 1 || rb.pop_front() != 2) return 1;
    rb.push(4);
    if (rb.pop_front() != 3 || rb.pop_front() != 4) return 1;
    if (!rb.empty()) return 1;
    std::cout << "ok\n";
    return 0;
}
```

A fixed `std::array` with a moving head and a count gives O(1) push/pop and no allocation. The front index is recovered arithmetically as `(head + N - size) % N`, so overwrites when full also drop the oldest element, which is the ring-buffer contract.

