```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool push(int value) {
        if (size_ == cap_) return false;
        data_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::size_t cap_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
    std::array<int, 1024> data_{};
};

int main() {
    RingBuffer rb(3);
    for (int i = 1; i <= 3; ++i) rb.push(i);
    if (rb.push(4)) { std::cerr << "should have rejected\n"; return 1; }
    if (rb.pop() != 1) { std::cerr << "bad pop\n"; return 1; }
    rb.push(4);
    if (rb.size() != 3) { std::cerr << "bad size\n"; return 1; }
    std::cout << "ok\n";
}
```
Indices wrap with modulo, so pushing after a pop reuses the freed slot. `push` returns false instead of overwriting when full; `pop` returns `std::nullopt` when empty.

