```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity), closed_(false) {}

    // Blocks until space is free, or returns false if the queue is closed.
    bool push(int value) {
        std::unique_lock<std::mutex> lock(m_);
        notFull_.wait(lock, [&] { return closed_ || q_.size() < cap_; });
        if (closed_) return false;
        q_.push(value);
        notEmpty_.notify_one();
        return true;
    }

    // Blocks until an item is available, or returns nullopt if closed and drained.
    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(m_);
        notEmpty_.wait(lock, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;
        int v = q_.front();
        q_.pop();
        notFull_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lock(m_);
        closed_ = true;
        notEmpty_.notify_all();
        notFull_.notify_all();
    }

private:
    std::size_t cap_;
    bool closed_;
    std::queue<int> q_;
    std::mutex m_;
    std::condition_variable notEmpty_, notFull_;
};
```

`close()` sets the flag under the lock, then wakes both groups; a blocked `push` returns `false` and a blocked `pop` returns `nullopt` once the queue is empty. Pushes that beat the close still succeed, so no item is silently dropped.

