use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum ParseErr {
    Empty,
    Malformed(String),
    Duplicate(String),
}

pub fn parse_pairs(input: &str) -> Result<HashMap<String, String>, ParseErr> {
    if input.trim().is_empty() {
        return Err(ParseErr::Empty);
    }
    let mut map = HashMap::new();
    for raw in input.split(',') {
        let entry = raw.trim();
        let (k, v) = entry
            .split_once('=')
            .ok_or_else(|| ParseErr::Malformed(entry.to_string()))?;
        let k = k.trim();
        if k.is_empty() {
            return Err(ParseErr::Malformed(entry.to_string()));
        }
        if map.insert(k.to_string(), v.trim().to_string()).is_some() {
            return Err(ParseErr::Duplicate(k.to_string()));
        }
    }
    Ok(map)
}

fn main() {
    for s in ["a=1, b=2", "a=1,a=2", "oops", "  ", "k="] {
        println!("{s:?} => {:?}", parse_pairs(s));
    }
}
```

`split_once('=')` keeps only the first `=`, so `token=a=b` yields value `a=b`. Whitespace around keys and values is trimmed; `k=` is allowed with an empty value, `oops` and blank input are rejected.

