#include <algorithm>
#include <iostream>
#include <vector>

void merge_sort(std::vector<int>& a) {
    const std::size_t n = a.size();
    std::vector<int> buf(n);
    for (std::size_t width = 1; width < n; width *= 2) {
        for (std::size_t lo = 0; lo < n; lo += 2 * width) {
            std::size_t mid = std::min(lo + width, n);
            std::size_t hi = std::min(lo + 2 * width, n);
            std::size_t i = lo, j = mid, k = lo;
            while (i < mid && j < hi) buf[k++] = (a[j] < a[i]) ? a[j++] : a[i++];
            while (i < mid) buf[k++] = a[i++];
            while (j < hi) buf[k++] = a[j++];
            std::copy(buf.begin() + lo, buf.begin() + hi, a.begin() + lo);
        }
    }
}

int main() {
    std::vector<std::vector<int>> tests = {{}, {1}, {2, 1}, {5, 4, 3, 2, 1}, {1, 3, 2, 3, 1}};
    for (auto v : tests) {
        merge_sort(v);
        std::cout << (std::is_sorted(v.begin(), v.end()) ? "sorted" : "FAIL") << ' ' << v.size() << '\n';
    }
}
```

Doubling `width` merges runs of that size; `buf` avoids per-merge allocation. Empty and single-element inputs fall through the loop untouched, so they are already sorted.

