```rust
use std::collections::{HashMap, VecDeque};

pub struct LruCache {
    cap: usize,
    map: HashMap<String, i32>,
    order: VecDeque<String>,
}

impl LruCache {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        Self { cap, map: HashMap::new(), order: VecDeque::new() }
    }

    pub fn get(&mut self, key: &str) -> Option<i32> {
        if let Some(&v) = self.map.get(key) {
            self.touch(key);
            Some(v)
        } else {
            None
        }
    }

    pub fn put(&mut self, key: &str, value: i32) {
        self.map.insert(key.to_string(), value);
        self.touch(key);
        while self.map.len() > self.cap {
            if let Some(old) = self.order.pop_front() {
                self.map.remove(&old);
            }
        }
    }

    fn touch(&mut self, key: &str) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            self.order.remove(pos);
        }
        self.order.push_back(key.to_string());
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put("a", 1);
    c.put("b", 2);
    assert_eq!(c.get("a"), Some(1)); // a becomes most recent
    c.put("c", 3);                  // evicts b
    assert_eq!(c.get("b"), None);
    assert_eq!(c.get("c"), Some(3));
    println!("ok");
}
```

The deque front is least-recently used; every access moves the key to the back. `put` re-inserts then evicts while over capacity, so it also handles updating an existing key. Lookups are O(n) in capacity due to the deque scan.

