class Fib {
public:
    long long get(int n) {
        if (n < 0) throw std::invalid_argument("n must be non-negative");
        auto it = memo_.find(n);
        if (it != memo_.end()) return it->second;
        long long value = (n < 2) ? n : get(n - 1) + get(n - 2);
        memo_[n] = value;
        return value;
    }

private:
    std::unordered_map<int, long long> memo_;
};

