#include <cstdint>
#include <iostream>
#include <limits>

bool isPalindrome(int64_t x) {
    // Negative numbers never read the same reversed (the '-' sign).
    if (x < 0) return false;
    // Overflow-safe reverse: only build half the number.
    int64_t reverse = 0;
    while (x > reverse) {
        reverse = reverse * 10 + x % 10;
        x /= 10;
    }
    // Even length: x == reverse. Odd length: x == reverse / 10 (drop middle digit).
    return x == reverse || x == reverse / 10;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << isPalindrome(121) << "\n";   // true
    std::cout << isPalindrome(-121) << "\n";  // false
    std::cout << isPalindrome(10) << "\n";    // false
    std::cout << isPalindrome(0) << "\n";     // true
    std::cout << isPalindrome(12321) << "\n"; // true
    return 0;
}
