fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        // Take from a when equal to keep the merge stable.
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 3, 6];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 3, 5, 6, 7]);
    // Empty sides are handled by the tail extends.
    assert_eq!(merge_sorted(&[], &[9]), vec![9]);
    assert_eq!(merge_sorted(&[4], &[]), vec![4]);
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    println!("all assertions passed");
}
