def is_valid_isbn10(raw: str) -> bool:
    """Validate an ISBN-10, ignoring hyphens and spaces."""
    cleaned = raw.replace("-", "").replace(" ", "").upper()
    if len(cleaned) != 10:
        return False
    if not cleaned[:9].isdigit():
        return False
    last = cleaned[9]
    if last != "X" and not last.isdigit():
        return False

    total = sum((i + 1) * (10 if c == "X" else int(c))
                for i, c in enumerate(cleaned))
    return total % 11 == 0


