    bool valid() const noexcept { return file_ != nullptr; }
    std::FILE* get() const noexcept { return file_; }

private:
    void close() noexcept {
        if (file_ != nullptr) {
            std::fclose(file_);
            file_ = nullptr;
        }
    }

    std::FILE* file_ = nullptr;
};
