fn longest_common_prefix(words: &[&str]) -> String {
    let first = match words.first() {
        Some(w) => *w,
        None => return String::new(),
    };
    let mut end = first.len();
    for word in &words[1..] {
        end = end.min(word.len());
        for (i, (a, b)) in first.char_indices().zip(word.char_indices()) {
            if a != b {
                end = end.min(i);
                break;
            }
        }
    }
    let mut boundary = 0;
    for (i, _) in first.char_indices() {
        if i <= end {
            boundary = i;
        } else {
            break;
        }
    }
    boundary = end.min(first.len());
    while !first.is_char_boundary(boundary) {
        boundary -= 1;
    }
    first[..boundary].to_string()
}

fn main() {
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&["caf\u{e9}", "caf\u{e9}x"]), "caf\u{e9}");
    assert_eq!(longest_common_prefix(&[]), "");
    println!("ok");
}
