// Sums bytes modulo 65536. Returns false if the file cannot be opened.
bool file_checksum(const char* path, uint16_t& out) {
    std::ifstream in(path, std::ios::binary);
    if (!in) return false;
    uint32_t sum = 0;
    char buf[4096];
    while (in.read(buf, sizeof(buf)) || in.gcount() > 0) {
        std::streamsize n = in.gcount();
        for (std::streamsize i = 0; i < n; ++i) {
            sum += static_cast<unsigned char>(buf[i]);
        }
    }
    out = static_cast<uint16_t>(sum % 65536u);
    return true;
}

int main(int argc, char** argv) {
    if (argc != 3) {
        std::cerr << "usage: " << argv[0] << " <file> <expected>\n";
        return 2;
    }
    uint16_t actual = 0;
    if (!file_checksum(argv[1], actual)) {
        std::cerr << "cannot open: " << argv[1] << "\n";
        return 2;
    }
    auto expected = static_cast<uint16_t>(std::stoul(argv[2]) % 65536u);
    if (actual == expected) {
        std::cout << "pass (" << actual << ")\n";
        return 0;
    }
    std::cout << "fail: got " << actual << ", expected " << expected << "\n";
    return 1;
}
