#include <cstddef>
#include <iostream>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), count_(0), capacity_(capacity) {}

    void push(int value) {
        std::size_t tail = (head_ + count_) % capacity_;
        data_[tail] = value;
        if (count_ < capacity_) {
            ++count_;
        } else {
            head_ = (head_ + 1) % capacity_;  // overwrite oldest
        }
    }

    bool pop(int& out) {
        if (count_ == 0) return false;
        out = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }

private:
    std::vector<int> data_;
    std::size_t head_;
    std::size_t count_;
    std::size_t capacity_;
};

int main() {
    RingBuffer rb(3);
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4);  // drops 1
    int v = 0;
    while (rb.pop(v)) std::cout << v << '\n';  // 2 3 4
    return 0;
}
```

