```rust
fn longest_palindrome(s: &str) -> String {
    let bytes = s.as_bytes();
    if bytes.is_empty() {
        return String::new();
    }

    let (mut start, mut end) = (0usize, 0usize);

    let expand = |mut left: isize, mut right: isize| -> (usize, usize) {
        while left >= 0
            && right < bytes.len() as isize
            && bytes[left as usize] == bytes[right as usize]
        {
            left -= 1;
            right += 1;
        }
        ((left + 1) as usize, (right - 1) as usize)
    };

    for i in 0..bytes.len() {
        let (l1, r1) = expand(i as isize, i as isize);      // odd length
        let (l2, r2) = expand(i as isize, (i + 1) as isize); // even length
        if r1 - l1 > end - start {
            start = l1;
            end = r1;
        }
        if r2 - l2 > end - start {
            start = l2;
            end = r2;
        }
    }

    s[start..=end].to_string()
}

fn main() {
    assert_eq!(longest_palindrome("babad"), "bab");
    assert_eq!(longest_palindrome("cbbd"), "bb");
    assert_eq!(longest_palindrome(""), "");
    assert_eq!(longest_palindrome("a"), "a");
    println!("{}", longest_palindrome("forgeeksskeegfor"));
}
```

Expand-around-center is O(n^2) time and O(1) extra space. Empty and single-character inputs are handled up front. Index arithmetic uses `isize` so the left pointer can step to -1 before the fix-up.

