    if (n == NULL) {
        return NULL;
    }
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print(const Node *head) {
    for (; head != NULL; head = head->next) {
        printf("%d%s", head->value, head->next ? " -> " : "\n");
    }
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int v = 1; v <= 5; v++) {
        head = push(head, v);
        if (head == NULL) {
            fprintf(stderr, "out of memory\n");
            return 1;
        }
    }

    print(head);            /* 5 -> 4 -> 3 -> 2 -> 1 */
    head = reverse(head);
    print(head);            /* 1 -> 2 -> 3 -> 4 -> 5 */
    free_list(head);
    return 0;
}
```

`reverse` rewires the pointers in a single pass with O(1) extra space. `push` checks `malloc` before dereferencing. Every node is released in `free_list`, and the empty-list case is a no-op in both `reverse` and `print`.

