import csv
import sys


def validate(path):
    errors = []
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return ["file is empty"], 0

        if [h.strip().lower() for h in header] != ["name", "age"]:
            errors.append(f"unexpected header: {header}")

        good = 0
        for lineno, row in enumerate(reader, start=2):
            if len(row) != 2:
                errors.append(f"line {lineno}: expected 2 fields, got {len(row)}")
                continue
            name, age = row[0].strip(), row[1].strip()
            if not name:
                errors.append(f"line {lineno}: empty name")
                continue
            try:
                value = int(age)
            except ValueError:
                errors.append(f"line {lineno}: age not an integer: {age!r}")
                continue
            if not 0 <= value <= 150:
                errors.append(f"line {lineno}: age out of range: {value}")
                continue
            good += 1
    return errors, good


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: validate.py FILE.csv", file=sys.stderr)
        raise SystemExit(2)
    errors, good = validate(sys.argv[1])
    for e in errors:
        print("error:", e)
    print(f"{good} valid rows, {len(errors)} problems")
```

Each bad row is recorded and skipped, so one malformed line never aborts the run. Header comparison is case- and whitespace-insensitive. `encoding="utf-8"` keeps non-ASCII names from raising, and the empty-file case returns a clear message instead of a traceback.

