```rust
fn longest_common_prefix(words: &[String]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = words[0].as_bytes();
    let mut len = first.len();

    for word in &words[1..] {
        let other = word.as_bytes();
        len = len.min(other.len());
        let mut i = 0;
        while i < len && first[i] == other[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            break;
        }
    }
    words[0][..len].to_string()
}

fn main() {
    let words: Vec<String> = ["flower", "flow", "flight"]
        .iter().map(|s| s.to_string()).collect();
    assert_eq!(longest_common_prefix(&words), "fl");

    let empty: Vec<String> = Vec::new();
    assert_eq!(longest_common_prefix(&empty), "");

    let same: Vec<String> = ["abc", "abc"].iter().map(|s| s.to_string()).collect();
    assert_eq!(longest_common_prefix(&same), "abc");
    println!("{}", longest_common_prefix(&words));
}
