#include <stdio.h>
#include <string.h>

static void reverse_in_place(char *s) {
    size_t n = strlen(s);
    if (n < 2) return;
    char *left = s;
    char *right = s + n - 1;
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        left++;
        right--;
    }
}

static void print_reversed(const char *s) {
    const char *end = s + strlen(s);
    while (end != s) {
        putchar(*--end);
    }
    putchar('\n');
}

int main(void) {
    char buf[] = "hello world";
    print_reversed(buf);       /* dlrow olleh */
    reverse_in_place(buf);
    printf("%s\n", buf);      /* dlrow olleh */

    char empty[] = "";
    reverse_in_place(empty);
    printf("[%s]\n", empty);
    return 0;
}
```

The two-pointer swap handles even and odd lengths and the `n < 2` guard covers empty and single-character strings. `print_reversed` walks from the NUL terminator backwards without mutating the buffer.

