#include <stdio.h>
#include <stdbool.h>

#define RING_CAP 4

typedef struct {
    int data[RING_CAP];
    int head;
    int tail;
    int count;
} Ring;

void ring_init(Ring *r) { r->head = 0; r->tail = 0; r->count = 0; }

bool ring_push(Ring *r, int v) {
    if (r->count == RING_CAP) return false;
    r->data[r->tail] = v;
    r->tail = (r->tail + 1) % RING_CAP;
    r->count++;
    return true;
}

bool ring_pop(Ring *r, int *out) {
    if (r->count == 0) return false;
    *out = r->data[r->head];
    r->head = (r->head + 1) % RING_CAP;
    r->count--;
    return true;
}

int main(void) {
    Ring r;
    ring_init(&r);
    int v;
    printf("pop empty: %d\n", ring_pop(&r, &v));
    for (int i = 1; i <= 5; i++) printf("push %d: %d\n", i, ring_push(&r, i));
    while (ring_pop(&r, &v)) printf("popped %d\n", v);
    return 0;
}
