```cpp
#include <cassert>
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), size_(0) {}

    bool full()  const { return size_ == cap_; }
    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

    bool push(int value) {
        if (full()) return false;
        buf_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

private:
    std::vector<int> buf_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    assert(rb.empty() && !rb.full());
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.full() && !rb.push(4));          // rejects when full
    assert(rb.pop() == 1 && rb.pop() == 2);
    assert(rb.push(4) && rb.push(5));          // wraps around
    assert(rb.pop() == 3 && rb.pop() == 4 && rb.pop() == 5);
    assert(rb.empty() && !rb.pop().has_value());
    std::cout << "all ring buffer checks passed\n";
    return 0;
}
```
The buffer uses `head_` plus `size_` rather than separate head/tail indices, which removes the classic full-vs-empty ambiguity. `push` writes at `(head_ + size_) % cap_`; `pop` returns `std::nullopt` when empty and advances `head_` modulo capacity. The test drives the buffer through fill, reject, drain, wrap, and empty cases.

