use std::collections::HashMap;
use std::env;
use std::fs;

fn normalize(word: &str) -> String {
    word.chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect()
}

fn main() -> std::io::Result<()> {
    let path = env::args().nth(1).expect("usage: wordfreq <file>");
    let text = fs::read_to_string(&path)?;

    let mut counts: HashMap<String, u64> = HashMap::new();
    for raw in text.split_whitespace() {
        let w = normalize(raw);
        if !w.is_empty() {
            *counts.entry(w).or_insert(0) += 1;
        }
    }

    let mut ranked: Vec<(String, u64)> = counts.into_iter().collect();
    // Sort by count descending, then word ascending for stable ties.
    ranked.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    for (word, count) in ranked.iter().take(5) {
        println!("{count} {word}");
    }
    Ok(())
}
```
Each token is normalized by keeping only alphanumeric characters (via `is_alphanumeric`, so Unicode letters survive) and lowercasing. Empty tokens from pure-punctuation input are dropped. The vector is sorted with a two-key comparator: count descending, then word ascending, which makes ties deterministic. Only the first five are printed.

```c
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

/* Returns fib(n) mod 2^64, using the fast-doubling identities.
 * Computes the pair (F(k), F(k+1)) recursively in O(log n). */
static void fib_pair(unsigned long long n,
                     unsigned long long *fk,
                     unsigned long long *fk1) {
    if (n == 0) {
        *fk = 0;
        *fk1 = 1;
        return;
    }

    unsigned long long a, b;          /* F(m), F(m+1) with m = n/2 */
    fib_pair(n / 2, &a, &b);

    unsigned long long c = a * (2 * b - a);   /* F(2m)     */
    unsigned long long d = a * a + b * b;     /* F(2m + 1) */

    if (n % 2 == 0) {
        *fk = c;
        *fk1 = d;
    } else {
        *fk = d;
        *fk1 = c + d;
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <n>\n", argv[0]);
        return 1;
    }

    errno = 0;
    char *end = NULL;
    unsigned long long n = strtoull(argv[1], &end, 10);
    if (errno != 0 || end == argv[1] || *end != '\0') {
        fprintf(stderr, "error: '%s' is not a valid non-negative integer\n", argv[1]);
        return 1;
    }

    unsigned long long fk, fk1;
    fib_pair(n, &fk, &fk1);
    printf("fib(%llu) mod 2^64 = %llu\n", n, fk);
    return 0;
}
```
`fib_pair` uses the classic fast-doubling identities: given `F(m)` and `F(m+1)`, `F(2m) = F(m)*(2*F(m+1) - F(m))` and `F(2m+1) = F(m)^2 + F(m+1)^2`. Recursion depth is O(log n), so it handles very large indices. Results are taken mod 2^64 by the machine's unsigned arithmetic, which is stated in the output label rather than hidden. Input is validated with `strtoull`, rejecting non-numeric and negative input via the trailing-character and `errno` checks.

