bool isPerfectSquare(std::uint64_t n) {
    std::uint64_t lo = 0, hi = 1ULL << 32;  // hi^2 > 2^64 for the boundary
    while (lo <= hi) {
        std::uint64_t mid = lo + (hi - lo) / 2;
        std::uint64_t sq = mid * mid;
        if (sq == n) return true;
        if (sq < n)
            lo = mid + 1;
        else {
            if (mid == 0) break;
            hi = mid - 1;
        }
    }
    return false;
}

int main() {
    assert(isPerfectSquare(0));
    assert(isPerfectSquare(1));
    assert(isPerfectSquare(49));
    assert(!isPerfectSquare(50));
    assert(isPerfectSquare(1ULL << 62));  // (2^31)^2
    std::cout << "ok\n";
}
