// Split a UTF-8 string into byte offsets of each code point.
static std::vector<std::size_t> offsets(const std::string& s) {
    std::vector<std::size_t> pos;
    for (std::size_t i = 0; i < s.size();) {
        pos.push_back(i);
        unsigned char c = static_cast<unsigned char>(s[i]);
        i += (c < 0x80) ? 1 : (c < 0xE0) ? 2 : (c < 0xF0) ? 3 : 4;
    }
    pos.push_back(s.size());
    return pos;
}

std::string reverseUtf8(const std::string& s) {
    auto pos = offsets(s);
    std::string out;
    out.reserve(s.size());
    for (std::size_t k = pos.size() - 1; k-- > 0;) {
        out.append(s, pos[k], pos[k + 1] - pos[k]);
    }
    return out;
}

int main() {
    assert(reverseUtf8("") == "");
    assert(reverseUtf8("abc") == "cba");
    assert(reverseUtf8("a\u00e9b") == "b\u00e9a");
    assert(reverseUtf8("\u00e9\u00e8") == "\u00e8\u00e9");
    std::cout << "ok\n";
