#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity) {}

    void push(int value) {
        buf_[write_] = value;
        write_ = (write_ + 1) % cap_;
        if (size_ < cap_) {
            ++size_;
        } else {
            read_ = (read_ + 1) % cap_;
        }
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = buf_[read_];
        read_ = (read_ + 1) % cap_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::vector<int> buf_;
    std::size_t cap_;
    std::size_t read_ = 0;
    std::size_t write_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    for (int i = 1; i <= 5; ++i) rb.push(i * 10);
    while (!rb.empty()) {
        std::cout << *rb.pop() << "\n";
    }
    return 0;
}
