void remove_duplicates(char *s) {
    unsigned char seen[32] = {0};
    size_t write = 0;
    for (size_t read = 0; s[read] != '\0'; ++read) {
        unsigned char c = (unsigned char)s[read];
        unsigned char mask = (unsigned char)(1u << (c & 7));
        if (!(seen[c >> 3] & mask)) {
            seen[c >> 3] |= mask;
            s[write++] = (char)c;
        }
    }
    s[write] = '\0';
}

