fn nth_prime(n: usize) -> u64 {
    assert!(n >= 1, "n must be at least 1");
    // Upper bound for the nth prime (n >= 6): n(ln n + ln ln n).
    let bound = if n < 6 {
        15
    } else {
        let nf = n as f64;
        (nf * (nf.ln() + nf.ln().ln())).ceil() as usize + 2
    };

    let mut sieve = vec![true; bound + 1];
    sieve[0] = false;
    sieve[1] = false;
    let mut i = 2;
    while i * i <= bound {
        if sieve[i] {
            let mut m = i * i;
            while m <= bound {
                sieve[m] = false;
                m += i;
            }
        }
        i += 1;
    }

    let mut count = 0;
    for (p, &is_prime) in sieve.iter().enumerate() {
        if is_prime {
            count += 1;
            if count == n {
                return p as u64;
            }
        }
    }
    unreachable!("sieve bound was too small")
}

fn main() {
    let known = [2u64, 3, 5, 7, 11, 13, 17, 19, 23, 29];
    for (i, &expected) in known.iter().enumerate() {
        assert_eq!(nth_prime(i + 1), expected, "prime #{}", i + 1);
    }
    assert_eq!(nth_prime(100), 541);
    println!("nth_prime(100) = {}", nth_prime(100));
}
