#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (count_ == N) return false;   // full
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;  // empty
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    constexpr std::size_t capacity() const { return N; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) throw std::runtime_error("push failed");
    if (rb.push(4)) throw std::runtime_error("should be full");
    if (rb.pop() != 1) throw std::runtime_error("bad pop");
    if (rb.pop() != 2) throw std::runtime_error("bad pop");
    if (!rb.push(5)) throw std::runtime_error("push after pop failed");
    if (rb.size() != 2) throw std::runtime_error("bad size");
    return 0;
}
