                raw = (row.get("score") or "").strip()
                if not name or not raw:
                    skipped += 1
                    continue
                try:
                    score = float(raw)
                except ValueError:
                    skipped += 1
                    continue
                totals[name] += score
                counts[name] += 1
    except FileNotFoundError:
        print(f"error: file not found: {path}", file=sys.stderr)
        return {}, 0
    except UnicodeDecodeError:
        print(f"error: cannot decode {path} as utf-8", file=sys.stderr)
        return {}, 0

    averages = {name: totals[name] / counts[name] for name in totals}
    return averages, skipped


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: average_scores.py FILE.csv", file=sys.stderr)
        sys.exit(2)
    result, skipped = average_scores(sys.argv[1])
    for name, avg in sorted(result.items()):
        print(f"{name}: {avg:.2f}")
    if skipped:
        print(f"({skipped} row(s) skipped)", file=sys.stderr)
