```cpp
#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

template <typename T>
void rotate_left(std::vector<T>& v, std::size_t k) {
    if (v.empty()) {
        return;
    }
    k %= v.size();
    if (k == 0) {
        return;
    }
    // Three reversals: reverse whole, then each part.
    std::reverse(v.begin(), v.end());
    std::reverse(v.begin(), v.begin() + static_cast<std::ptrdiff_t>(v.size() - k));
    std::reverse(v.begin() + static_cast<std::ptrdiff_t>(v.size() - k), v.end());
}

int main() {
    std::vector<int> a{1, 2, 3, 4, 5};
    rotate_left(a, 2);
    assert((a == std::vector<int>{3, 4, 5, 1, 2}));

    std::vector<int> b{1, 2, 3};
    rotate_left(b, 3);  // k == size, no change
    assert((b == std::vector<int>{1, 2, 3}));

    std::vector<int> c{1, 2, 3};
    rotate_left(c, 7);  // k > size
    assert((c == std::vector<int>{2, 3, 1}));

    std::vector<int> empty;
    rotate_left(empty, 4);
    assert(empty.empty());

    std::cout << "all checks passed\n";
    return 0;
}
```
The three-reversal trick rotates in O(n) time and O(1) extra space. Reducing `k %= size` up front handles `k` larger than the container.

