fn parse_version(s: &str) -> Result<Version, ParseError> {
    let parts: Vec<&str> = s.trim().split('.').collect();
    if parts.len() != 3 {
        return Err(ParseError::WrongPartCount(parts.len()));
    }
    let parse = |p: &str| -> Result<u32, ParseError> {
        p.parse::<u32>()
            .map_err(|_| ParseError::NotANumber(p.to_string()))
    };
    Ok(Version {
        major: parse(parts[0])?,
        minor: parse(parts[1])?,
        patch: parse(parts[2])?,
    })
}

fn main() {
    assert_eq!(
        parse_version("1.2.3"),
        Ok(Version { major: 1, minor: 2, patch: 3 })
    );
    assert_eq!(parse_version(" 1.2.3 "), Ok(Version { major: 1, minor: 2, patch: 3 }));
    assert_eq!(parse_version("1.2"), Err(ParseError::WrongPartCount(2)));
    assert_eq!(parse_version("1.2.3.4"), Err(ParseError::WrongPartCount(4)));
    assert_eq!(parse_version("1.x.3"), Err(ParseError::NotANumber("x".into())));
    assert_eq!(parse_version(""), Err(ParseError::WrongPartCount(1)));
    println!("all checks passed");
}
