```rust
fn longest_common_prefix(words: &[&str]) -> String {
    if words.is_empty() {
        return String::new();
    }
    // Work on bytes; ASCII comparisons are fine, and we slice back at a
    // char boundary so multi-byte input stays valid UTF-8.
    let first = words[0].as_bytes();
    let mut len = first.len();
    for w in &words[1..] {
        let b = w.as_bytes();
        let mut i = 0;
        while i < len && i < b.len() && first[i] == b[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            return String::new();
        }
    }
    // `len` may land mid-codepoint only if bytes matched, which implies
    // the prefixes are equal, so `is_char_boundary` holds for the first word.
    first[..len].iter().map(|&c| c as char).collect()
}

fn main() {
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["alone"]), "alone");
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&["dog", "racecar", "car"]), "");
    assert_eq!(longest_common_prefix(&["test", "test"]), "test");
    println!("all checks passed");
}
```
Comparing bytes and shrinking `len` on the first mismatch is O(total input) and avoids allocating intermediate strings. An empty slice is handled explicitly.

```c
#include <stdio.h>
#include <string.h>

char *reverse_in_place(char *s) {
    if (s == NULL) {
        return s;
    }
    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0) {
        return s;  // empty string
    }
    j--;  // last valid index
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
    return s;
}

int main(void) {
    char a[] = "hello";
    if (strcmp(reverse_in_place(a), "olleh") != 0) {
        return 1;
    }

    char b[] = "";
    if (strcmp(reverse_in_place(b), "") != 0) {
        return 1;
    }

    char c[] = "ab";
    if (strcmp(reverse_in_place(c), "ba") != 0) {
        return 1;
    }

    if (reverse_in_place(NULL) != NULL) {
        return 1;
    }

    printf("all checks passed\n");
    return 0;
}
```
It swaps from both ends inward, O(n) time and O(1) space. A NULL pointer and the empty string are handled explicitly rather than assumed away.

