import re


def rle_decode(text: str) -> str:
    """Decode a run-length encoded string like 'a3b2c1' -> 'aaabbc'."""
    if not text:
        return ""
    parts = re.findall(r"([A-Za-z])(\d+)", text)
    if "".join(ch + num for ch, num in parts) != text:
        raise ValueError(f"invalid RLE sequence: {text!r}")
    out = []
    for ch, num in parts:
        out.append(ch * int(num))
    return "".join(out)


