bool balanced(const std::string& s) {
    std::string stack;
    char quote = 0;
    std::unordered_map<char, char> open = {{')', '('}, {']', '['}, {'}', '{'}};

    for (char c : s) {
        if (quote != 0) {
            if (c == quote) quote = 0;
            continue;
        }
        if (c == '\'' || c == '"') {
            quote = c;
        } else if (c == '(' || c == '[' || c == '{') {
            stack.push_back(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (stack.empty() || stack.back() != open.at(c)) return false;
            stack.pop_back();
        }
    }
    return quote == 0 && stack.empty();
}

int main() {
    std::cout << std::boolalpha;
    std::cout << balanced("{[()]}") << '\n';          // true
    std::cout << balanced("([)]") << '\n';            // false
    std::cout << balanced("\"(\"") << '\n';          // true
    std::cout << balanced("'") << '\n';               // false
    std::cout << balanced("{\"}\"}") << '\n';       // true
    return 0;
}
