fn fib_fast(n: u64) -> u128 {
    fn pair(n: u64) -> (u128, u128) {
        if n == 0 {
            return (0, 1);
        }
        let (a, b) = pair(n >> 1);
        let c = a * (b * 2 - a);
        let d = a * a + b * b;
        if n & 1 == 0 {
            (c, d)
        } else {
            (d, c + d)
        }
    }
    pair(n).0
}

fn fib_memo(n: u64) -> u128 {
    fn helper(n: u64, memo: &mut Vec<u128>) -> u128 {
        if n < 2 {
            return n as u128;
        }
        if memo[n as usize] != 0 {
            return memo[n as usize];
        }
        let v = helper(n - 1, memo) + helper(n - 2, memo);
        memo[n as usize] = v;
        v
    }
    let mut memo = vec![0u128; (n + 1) as usize];
    helper(n, &mut memo)
}

fn main() {
    for n in [0u64, 1, 2, 10, 30, 50, 90] {
        assert_eq!(fib_fast(n), fib_memo(n), "mismatch at {n}");
        println!("fib({n}) = {}", fib_fast(n));
