fn fib(n: u64) -> Option<u128> {
    fn helper(n: u64) -> (u128, u128) {
        if n == 0 {
            return (0, 1);
        }
        let (a, b) = helper(n >> 1);
        let c = a.checked_mul((b << 1).checked_sub(a)?)?;
        let d = a.checked_mul(a)?.checked_add(b.checked_mul(b)?)?;
        if n & 1 == 0 {
            (c, d)
        } else {
            (d, c.checked_add(d)?)
        }
    }
    helper(n).0.into()
}

fn main() {
    assert_eq!(fib(0), Some(0));
    assert_eq!(fib(1), Some(1));
    assert_eq!(fib(10), Some(55));
    assert_eq!(fib(90), Some(2880067194370816120));
    assert_eq!(fib(187), None); // exceeds u128 range
    println!("{:?}", fib(50)); // Some(12586269025)
}
