```cpp
#include <iostream>
#include <queue>
#include <vector>
#include <functional>

class RunningMedian {
public:
    void add(int x) {
        if (low_.empty() || x <= low_.top()) low_.push(x);
        else high_.push(x);
        if (low_.size() > high_.size() + 1) rebalance();
        else if (high_.size() > low_.size()) rebalance();
    }

    double median() const {
        if (low_.empty() && high_.empty()) return 0.0;
        if (low_.size() == high_.size())
            return (low_.top() + high_.top()) / 2.0;
        return low_.size() > high_.size() ? low_.top() : high_.top();
    }

private:
    void rebalance() {
        if (low_.size() > high_.size()) {
            high_.push(low_.top());
            low_.pop();
        } else {
            low_.push(high_.top());
            high_.pop();
        }
    }

    std::priority_queue<int> low_;                                     // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high_; // min-heap
};

int main() {
    std::vector<int> stream{5, 15, 1, 3, 2, 8, 7, 9, 10, 6, 11, 4};
    RunningMedian rm;
    for (int x : stream) {
        rm.add(x);
        std::cout << rm.median() << ' ';
    }
    std::cout << '\n';
    return 0;
}
```

`low_` holds the smaller half as a max-heap and `high_` the larger half as a min-heap. After each insert the sizes differ by at most one, so the median is either a single heap top or the average of the two tops. The empty-stream case returns `0.0` rather than dereferencing an empty heap.

