#include <stdint.h>
#include <stdio.h>

uint32_t reverse_bits(uint32_t x) {
    uint32_t result = 0;
    for (int i = 0; i < 32; i++) {
        result = (result << 1) | (x & 1u);
        x >>= 1;
    }
    return result;
}

int main(void) {
    struct { uint32_t in, expected; } cases[] = {
        {0x00000000u, 0x00000000u},
        {0x00000001u, 0x80000000u},
        {0x80000000u, 0x00000001u},
        {0xFFFFFFFFu, 0xFFFFFFFFu},
        {0x0000FFFFu, 0xFFFF0000u},
        {0x12345678u, 0x1E6A2C48u},
    };

    int failures = 0;
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        uint32_t got = reverse_bits(cases[i].in);
        if (got != cases[i].expected) {
            printf("FAIL %08X -> %08X, expected %08X\n",
                   cases[i].in, got, cases[i].expected);
            failures++;
        }
    }
    printf(failures ? "%d failure(s)\n" : "all passed\n", failures);
    return failures != 0;
}
```

