```cpp
#include <condition_variable>
#include <iostream>
#include <mutex>
#include <optional>
#include <queue>
#include <thread>

template <typename T>
class BlockingQueue {
public:
    void push(T value) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            queue_.push(std::move(value));
        }
        cv_.notify_one();
    }

    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return !queue_.empty() || closed_; });
        if (queue_.empty()) {
            return std::nullopt;
        }
        T value = std::move(queue_.front());
        queue_.pop();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            closed_ = true;
        }
        cv_.notify_all();
    }

private:
    std::queue<T> queue_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool closed_ = false;
};

int main() {
    BlockingQueue<int> q;
    std::thread producer([&q] {
        for (int i = 0; i < 5; ++i) q.push(i);
        q.close();
    });

    while (auto item = q.pop()) {
        std::cout << *item << '\n';
    }
    producer.join();
}
```

The `closed_` flag lets `pop` wake and return `std::nullopt` once the producer is done, so the consumer never blocks forever. `notify_one` on push and `notify_all` on close avoid lost wakeups.

