fn is_balanced(input: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for c in input.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let expected = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some(open) if open == expected => {}
                    _ => return false,
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    assert!(is_balanced("{[()]}"));
    assert!(is_balanced(""));
    assert!(!is_balanced("(]") );
    assert!(!is_balanced("(("));
    println!("{}", is_balanced("a(b[c]{d})e"));  // true
}
```
A mismatch or a closing bracket with an empty stack fails immediately. The final `stack.is_empty()` catches unclosed openers. Non-bracket characters are ignored.

