#include <stdio.h>

static void reverse(int *arr, int lo, int hi) {
    while (lo < hi) {
        int t = arr[lo];
        arr[lo] = arr[hi];
        arr[hi] = t;
        lo++;
        hi--;
    }
}

static void rotate_right(int *arr, int n, int k) {
    if (n <= 0) return;
    k %= n;
    if (k < 0) k += n;
    if (k == 0) return;
    reverse(arr, 0, n - 1);
    reverse(arr, 0, k - 1);
    reverse(arr, k, n - 1);
}

static void print_arr(const int *arr, int n) {
    for (int i = 0; i < n; i++)
        printf("%d%s", arr[i], i + 1 == n ? "\n" : " ");
}

int main(void) {
    int a[] = {1, 2, 3, 4, 5, 6, 7};
    rotate_right(a, 7, 3);
    print_arr(a, 7);  /* 5 6 7 1 2 3 4 */

    int b[] = {1, 2};
    rotate_right(b, 2, 5);
    print_arr(b, 2);  /* 2 1 */

    int c[] = {1, 2, 3};
    rotate_right(c, 3, 0);
    print_arr(c, 3);  /* 1 2 3 */
    return 0;
}
```
Three reversals achieve the rotation in place. Normalizing `k %= n` and adding `n` for negative `k` keeps indexing valid; `k == 0` short-circuits so no work is wasted.

