```cpp
#include <iostream>
#include <vector>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    Node* curr = head;
    while (curr != nullptr) {
        Node* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

void free_list(Node* head) {
    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    Node* head = nullptr;
    for (int v : std::vector<int>{1, 2, 3, 4}) {
        head = new Node(v); // build in reverse
        head->next = nullptr;
    }
    // rebuild properly
    free_list(head);
    head = nullptr;
    for (int v : std::vector<int>{4, 3, 2, 1}) {
        Node* n = new Node(v);
        n->next = head;
        head = n;
    }

    head = reverse(head);
    for (Node* p = head; p != nullptr; p = p->next) {
        std::cout << p->value << ' ';
    }
    std::cout << '\n';

    free_list(head);
    return 0;
}
```

The reversal uses three pointers and no recursion, so it is O(n) time and O(1) stack. `free_list` walks the final list and deletes every node, avoiding a leak.

