import heapq

class RunningMedian:
    def __init__(self):
        self.low = []   # max-heap (negated)
        self.high = []  # min-heap

    def add(self, value):
        heapq.heappush(self.low, -value)
        heapq.heappush(self.high, -heapq.heappop(self.low))
        if len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def median(self):
        if len(self.low) > len(self.high):
            return float(-self.low[0])
        return (-self.low[0] + self.high[0]) / 2.0


def running_medians(values):
    rm = RunningMedian()
    out = []
    for v in values:
        rm.add(v)
        out.append(rm.median())
    return out


if __name__ == "__main__":
    print(running_medians([]))
    print(running_medians([5]))
    print(running_medians([2, 1, 5, 7, 2, 0, 5]))
    print(running_medians([-3, -1, -2]))
