#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) { perror("malloc"); exit(1); }
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print(Node *head) {
    for (Node *cur = head; cur; cur = cur->next)
        printf("%d%s", cur->value, cur->next ? " -> " : "\n");
    if (!head) printf("(empty)\n");
}

static void free_list(Node *head) {
    while (head) { Node *n = head->next; free(head); head = n; }
}

int main(void) {
    Node *head = NULL;
    for (int i = 5; i >= 1; --i) head = push(head, i);
    print(head);
    head = reverse(head);
    print(head);
    free_list(head);

    head = NULL;
    print(head);
    return 0;
}
