pub fn luhn_valid(digits: &str) -> bool {
    let mut sum = 0u32;
    let mut double = false;
    for c in digits.chars().rev() {
        if c == ' ' || c == '-' {
            continue;
        }
        let d = match c.to_digit(10) {
            Some(d) => d,
            None => return false,
        };
        let mut v = d;
        if double {
            v *= 2;
            if v > 9 {
                v -= 9;
            }
        }
        sum += v;
        double = !double;
    }
    sum != 0 && sum % 10 == 0
}

