def solve_n_queens(n):
    if n <= 0:
        return []
    if n in (2, 3):
        return None  # no solution exists

    cols = set()
    diag1 = set()  # r - c
    diag2 = set()  # r + c
    placement = []

    def backtrack(row):
        if row == n:
            return True
        for col in range(n):
            if col in cols or (row - col) in diag1 or (row + col) in diag2:
                continue
            cols.add(col)
            diag1.add(row - col)
            diag2.add(row + col)
            placement.append(col)
            if backtrack(row + 1):
                return True
            placement.pop()
            cols.discard(col)
            diag1.discard(row - col)
            diag2.discard(row + col)
        return False

    return placement if backtrack(0) else None


if __name__ == "__main__":
    for size in (1, 2, 4, 8):
        sol = solve_n_queens(size)
        print(size, sol)
