#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    std::size_t size() const { return size_; }

    const T& operator[](std::size_t i) const {
        if (i >= size_) throw std::out_of_range("ring index");
        std::size_t start = (head_ + N - size_) % N;
        return data_[(start + i) % N];
    }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4);
    for (std::size_t i = 0; i < rb.size(); ++i) std::cout << rb[i] << ' ';
    std::cout << '\n';
    return 0;
}
