fn max_of<T: PartialOrd + Copy>(items: &[T]) -> Option<T> {
    let mut iter = items.iter();
    let first = *iter.next()?;
    Some(iter.fold(first, |best, &x| if x > best { x } else { best }))
}

fn main() {
    assert_eq!(max_of::<i32>(&[]), None);
    assert_eq!(max_of(&[3, 9, 2]), Some(9));
    assert_eq!(max_of(&['a', 'z', 'm']), Some('z'));
    assert_eq!(max_of(&[f64::NAN, 1.0]), Some(1.0));
    println!("ok");
}
```

Using `?` on `iter.next()` short-circuits to `None` for an empty slice; the fold avoids a second bounds check. Note `NaN` comparisons return false, so a leading `NaN` is skipped in favor of the next element.

