    return Counter(tokens).most_common(n)


def main() -> None:
    try:
        n = int(sys.argv[1]) if len(sys.argv) > 1 else 10
    except ValueError:
        print("usage: topwords.py [N]", file=sys.stderr)
        sys.exit(2)

    if n <= 0:
        print("N must be positive", file=sys.stderr)
        sys.exit(2)

    text = sys.stdin.read()
    if not text.strip():
        print("no input", file=sys.stderr)
        return

    for word, count in top_words(text, n):
        print(f"{count:6d}  {word}")


if __name__ == "__main__":
    main()
```

Run it as `python topwords.py 5 < file.txt`. The regex keeps apostrophes so `don't` stays one token, lowercases everything, and ties are broken by first-seen order via `Counter.most_common`.

