    std::size_t mid = n / 2;
    std::nth_element(values.begin(), values.begin() + mid, values.end());

    if (n % 2 == 1) {
        std::cout << values[mid] << '\n';
    } else {
        long long upper = values[mid];
        long long lower = *std::max_element(values.begin(), values.begin() + mid);
        // print the exact average as a decimal when it is not an integer
        long long sum = lower + upper;
        if (sum % 2 == 0) {
            std::cout << sum / 2 << '\n';
        } else {
            std::cout << sum / 2 << ".5\n";
        }
    }
    return 0;
}
