`nth_element` gives O(n) expected time instead of a full sort. For the even case I take the max of the lower half and the middle element as the two central values, which is correct because `nth_element` only guarantees that boundary position. The `.5` path avoids integer truncation on the average.

```cpp
#include <array>
#include <cstddef>
#include <stdexcept>

template <typename T, std::size_t Cap>
class RingBuffer {
public:
    void push(const T& value) {
        if (size_ == Cap) {
            throw std::overflow_error("ring buffer full");
        }
        data_[(head_ + size_) % Cap] = value;
        ++size_;
    }

    T pop() {
        if (size_ == 0) {
            throw std::underflow_error("ring buffer empty");
        }
        T value = data_[head_];
        head_ = (head_ + 1) % Cap;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == Cap; }

    class iterator {
    public:
        iterator(const RingBuffer* buf, std::size_t idx) : buf_(buf), idx_(idx) {}
        const T& operator*() const { return buf_->data_[(buf_->head_ + idx_) % Cap]; }
        iterator& operator++() { ++idx_; return *this; }
        bool operator!=(const iterator& other) const { return idx_ != other.idx_; }
    private:
        const RingBuffer* buf_;
        std::size_t idx_;
    };

    iterator begin() const { return iterator(this, 0); }
    iterator end() const { return iterator(this, size_); }

private:
    std::array<T, Cap> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};
```

