```rust
fn merge_unique<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    // Helper closure pushes a value only if it differs from the last pushed one.
    let push = |out: &mut Vec<T>, v: &T| {
        if out.last().map_or(true, |last| last != v) {
            out.push(v.clone());
        }
    };

    while i < a.len() && j < b.len() {
        if a[i] < b[j] {
            push(&mut out, &a[i]);
            i += 1;
        } else if b[j] < a[i] {
            push(&mut out, &b[j]);
            j += 1;
        } else {
            push(&mut out, &a[i]);
            i += 1;
            j += 1;
        }
    }
    while i < a.len() { push(&mut out, &a[i]); i += 1; }
    while j < b.len() { push(&mut out, &b[j]); j += 1; }

    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn handles_empty_and_duplicates() {
        assert_eq!(merge_unique::<i32>(&[], &[]), Vec::<i32>::new());
        assert_eq!(merge_unique(&[1, 2, 2, 3], &[2, 3, 4]), vec![1, 2, 3, 4]);
        assert_eq!(merge_unique(&[1, 1, 1], &[]), vec![1]);
    }
}
```

The `push` closure compares against the previous element, so duplicates within a single input are removed too, not just across the two slices. Both inputs in the test are already sorted, which is the precondition.

