#include <ctype.h>
#include <stdio.h>
#include <string.h>

static void reverse_range(char *s, size_t start, size_t end) {
    while (start < end) {
        char tmp = s[start];
        s[start] = s[end];
        s[end] = tmp;
        ++start;
        --end;
    }
}

int main(void) {
    char line[4096];
    if (fgets(line, sizeof line, stdin) == NULL) {
        return 0; /* EOF or empty input, nothing to do */
    }

    size_t n = strlen(line);
    while (n > 0 && (line[n - 1] == '\n' || line[n - 1] == '\r')) {
        line[--n] = '\0';
    }

    size_t i = 0;
    while (i < n) {
        if (!isspace((unsigned char)line[i])) {
            size_t start = i;
            while (i < n && !isspace((unsigned char)line[i])) {
                ++i;
            }
            reverse_range(line, start, i - 1);
        } else {
            ++i;
        }
    }

    puts(line);
    return 0;
}
