#include <cassert>
#include <iostream>

std::vector<std::string> split_csv(const std::string& line) {
    std::vector<std::string> fields;
    std::string cur;
    bool in_quotes = false;

    for (std::size_t i = 0; i < line.size(); ++i) {
        char c = line[i];
        if (in_quotes) {
            if (c == '"') {
                if (i + 1 < line.size() && line[i + 1] == '"') {
                    cur.push_back('"'); // escaped quote
                    ++i;
                } else {
                    in_quotes = false;
                }
            } else {
                cur.push_back(c);
            }
        } else if (c == ',') {
            fields.push_back(cur);
            cur.clear();
        } else if (c == '"' && cur.empty()) {
            in_quotes = true;
        } else {
            cur.push_back(c);
        }
    }
    fields.push_back(cur);
    return fields;
}

int main() {
    auto r = split_csv("a,b,\"c,d\",\"e\"\"f\"");
    assert((r == std::vector<std::string>{"a", "b", "c,d", "e\"f"}));
    assert(split_csv("") == std::vector<std::string>{""});
    std::cout << "ok\n";
}
