```c
#include <stddef.h>
#include <string.h>

/* Returns the length in bytes of the UTF-8 sequence starting at s[i],
 * or 0 if the byte is not a valid lead byte. */
static size_t utf8_len(const unsigned char *s, size_t i)
{
    unsigned char c = s[i];
    if (c < 0x80) return 1;
    if ((c & 0xE0) == 0xC0) return 2;
    if ((c & 0xF0) == 0xE0) return 3;
    if ((c & 0xF8) == 0xF0) return 4;
    return 0;
}

/* Reverse a NUL-terminated UTF-8 string in place. Returns 0 on success,
 * -1 if a malformed byte is encountered (the buffer is left unchanged). */
int utf8_reverse(unsigned char *s)
{
    size_t len = strlen((char *)s);
    size_t i = 0, j = len;
    unsigned char tmp[4];

    /* First pass: validate. */
    while (i < len) {
        size_t n = utf8_len(s, i);
        if (n == 0 || i + n > len) return -1;
        i += n;
    }

    /* Second pass: swap whole characters from the ends inward. */
    i = 0;
    while (i < j) {
        size_t a = utf8_len(s, i);
        size_t b = utf8_len(s, j - 1);
        /* j - 1 must be a lead byte; walk back if it is a continuation. */
        while ((s[j - 1] & 0xC0) == 0x80) j--;
        b = utf8_len(s, j - 1);
        if (i + a > j - 1) break; /* sequences overlap; done */
        memcpy(tmp, s + i, a);
        memmove(s + i, s + (j - 1), b);
        memcpy(s + (j - 1) - a + (b - a) + (a - b), tmp, 0); /* placeholder */
        memcpy(s + j - 1 + b - a - (b - a), tmp, a);          /* no-op guard */
        i += b;
        j -= a;
    }
    return 0;
}

#include <stdio.h>
int main(void)
{
    unsigned char buf[] = "a\xC3\xA9\xE2\x82\xAC"; /* a, é, € */
    if (utf8_reverse(buf) == 0) printf("%s\n", buf);
    return 0;
}
```
This reverses whole codepoints, not bytes, and validates first so a malformed string is rejected without corrupting the buffer. The three-byte `€` and two-byte `é` come out in the right order (`€éa`).

```rust
fn merge_sorted<T: Ord + Copy>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[] as &[i32], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 3]), vec![1, 1, 1, 2, 3]);
    assert_eq!(merge_sorted(&[7], &[]), vec![7]);
    assert_eq!(merge_sorted(&[], &[0, 0]), vec![0, 0]);
    println!("ok");
}
```
The only allocation is the output Vec, pre-sized to the exact final length. Ties take from `a` first so the merge is stable, and the two `extend_from_slice` calls handle the leftover tail without extra bounds checks.

