#include <cctype>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

std::vector<double> parse_numbers(const std::string& text) {
    std::vector<double> out;
    std::size_t i = 0;
    const std::size_t n = text.size();
    while (i < n) {
        if (!(std::isdigit(static_cast<unsigned char>(text[i])) ||
              text[i] == '+' || text[i] == '-' || text[i] == '.')) {
            ++i;
            continue;
        }
        // Collect a token that starts with a sign/digit/dot.
        std::size_t start = i;
        ++i;
        while (i < n && (std::isdigit(static_cast<unsigned char>(text[i])) || text[i] == '.')) {
            ++i;
        }
        try {
            std::size_t used = 0;
            double v = std::stod(text.substr(start, i - start), &used);
            if (used == i - start) {
                out.push_back(v);
            }
        } catch (const std::exception&) {
            // Unparseable token (e.g. "+" or "1.2.3"); skip it.
        }
    }
    return out;
}

int main() {
    auto r = parse_numbers("x = 3.5, y = -2, z = 1e3, junk = 1.2.3");
    for (double v : r) std::cout << v << '\n';
    // 3.5 -2
    std::cout << "empty: " << parse_numbers("").size() << '\n'; // 0
    return 0;
}
```
The scanner walks byte by byte and only tries `std::stod` on runs that look like a number, then checks `used` consumed the whole run so `1.2.3` is dropped rather than silently truncated. Empty input returns an empty vector.

