use std::fs::File;
use std::io::{self, Read};

const K: [u32; 64] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

struct Sha256 {
    h: [u32; 8],
    buf: [u8; 64],
    len: usize,
    total: u64,
}

impl Sha256 {
    fn new() -> Self {
        Sha256 {
            h: [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
                0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19],
            buf: [0u8; 64],
            len: 0,
            total: 0,
        }
    }

    fn compress(&mut self, block: &[u8; 64]) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([block[4 * i], block[4 * i + 1], block[4 * i + 2], block[4 * i + 3]]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16].wrapping_add(s0).wrapping_add(w[i - 7]).wrapping_add(s1);
        }
        let (mut a, mut b, mut c, mut d) = (self.h[0], self.h[1], self.h[2], self.h[3]);
        let (mut e, mut f, mut g, mut h) = (self.h[4], self.h[5], self.h[6], self.h[7]);
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ ((!e) & g);
            let t1 = h.wrapping_add(s1).wrapping_add(ch).wrapping_add(K[i]).wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            h = g; g = f; f = e; e = d.wrapping_add(t1);
            d = c; c = b; b = a; a = t1.wrapping_add(t2);
        }
        self.h[0] = self.h[0].wrapping_add(a);
        self.h[1] = self.h[1].wrapping_add(b);
        self.h[2] = self.h[2].wrapping_add(c);
        self.h[3] = self.h[3].wrapping_add(d);
        self.h[4] = self.h[4].wrapping_add(e);
        self.h[5] = self.h[5].wrapping_add(f);
        self.h[6] = self.h[6].wrapping_add(g);
        self.h[7] = self.h[7].wrapping_add(h);
    }

    fn update(&mut self, mut data: &[u8]) {
        self.total = self.total.wrapping_add(data.len() as u64);
        if self.len > 0 {
            let need = 64 - self.len;
            let take = need.min(data.len());
            self.buf[self.len..self.len + take].copy_from_slice(&data[..take]);
            self.len += take;
            data = &data[take..];
            if self.len == 64 {
                let block = self.buf;
                self.compress(&block);
                self.len = 0;
            }
        }
        while data.len() >= 64 {
            let mut block = [0u8; 64];
            block.copy_from_slice(&data[..64]);
            self.compress(&block);
            data = &data[64..];
        }
        if !data.is_empty() {
            self.buf[..data.len()].copy_from_slice(data);
            self.len = data.len();
        }
    }

    fn finish(mut self) -> [u8; 32] {
        let bit_len = self.total.wrapping_mul(8);
        self.update(&[0x80]);
        while self.len != 56 {
            self.update(&[0x00]);
        }
        self.update(&bit_len.to_be_bytes());
        let mut out = [0u8; 32];
        for (i, word) in self.h.iter().enumerate() {
            out[4 * i..4 * i + 4].copy_from_slice(&word.to_be_bytes());
        }
        out
    }
}

fn hash_file(path: &str) -> io::Result<[u8; 32]> {
    let mut hasher = Sha256::new();
    let mut f = File::open(path)?;
    let mut chunk = [0u8; 8192];
    loop {
        let n = f.read(&mut chunk)?;
        if n == 0 {
            break;
        }
        hasher.update(&chunk[..n]);
    }
    Ok(hasher.finish())
}

fn main() -> io::Result<()> {
    let digest = hash_file("Cargo.toml")?;
    let hex: String = digest.iter().map(|b| format!("{:02x}", b)).collect();
    println!("{}", hex);
    Ok(())
}
```
The file is read in 8 KiB chunks, so memory stays constant regardless of file size, and the streaming buffer handles input that doesn't align to the 64-byte block boundary. The padding length is tracked as a bit count in `u64`, which avoids overflow on files up to 2^61 bytes.

```python
import os
import sys
from collections import defaultdict


def human(n):
    for unit in ("B", "KiB", "MiB", "GiB", "TiB"):
        if abs(n) < 1024 or unit == "TiB":
            return f"{n:.1f} {unit}" if unit != "B" else f"{n} B"
        n /= 1024


def top_level_sizes(root):
    """Map each immediate child directory of `root` to its total byte size."""
    totals = defaultdict(int)
    for entry in os.scandir(root):
        if not entry.is_dir(follow_symlinks=False):
            continue
        total = 0
        for dirpath, dirnames, filenames in os.walk(entry.path, followlinks=False):
            for name in filenames:
                try:
                    total += os.path.getsize(os.path.join(dirpath, name))
                except OSError:
                    pass
        totals[entry.name] = total
    return dict(totals)


if __name__ == "__main__":
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    if not os.path.isdir(root):
        sys.exit(f"not a directory: {root}")
    sizes = top_level_sizes(root)
    for name, size in sorted(sizes.items(), key=lambda kv: kv[1], reverse=True):
        print(f"{human(size):>10}  {name}")
```
`follow_symlinks=False` on the scandir check and `followlinks=False` on the walk keep it from double-counting or looping on symlinked trees, and per-file `OSError` is swallowed so an unreadable file doesn't abort the report. Files directly in the root are excluded on purpose — the question is about subdirectory totals.

```c
#include <stdio.h>
#include <stdlib.h>

static int cmp_int(const void *a, const void *b)
{
    long x = *(const long *)a, y = *(const long *)b;
    return (x > y) - (x < y);
}

int main(void)
{
    long *v = NULL;
    size_t n = 0, cap = 0;
    char line[128];

    while (fgets(line, sizeof line, stdin)) {
        char *end;
        long val = strtol(line, &end, 10);
        if (end == line) continue;          /* skip blank / non-numeric lines */
        if (n == cap) {
            cap = cap ? cap * 2 : 16;
            long *tmp = realloc(v, cap * sizeof *v);
            if (!tmp) { fprintf(stderr, "out of memory\n"); free(v); return 1; }
            v = tmp;
        }
        v[n++] = val;
    }

    if (n == 0) {
        fprintf(stderr, "no integers read\n");
        free(v);
        return 1;
    }

    qsort(v, n, sizeof *v, cmp_int);

    double median = (n % 2) ? (double)v[n / 2]
                            : ((double)v[n / 2 - 1] + (double)v[n / 2]) / 2.0;

    long mode = v[0], best_count = 0;
    for (size_t i = 0; i < n; ) {
        size_t j = i;
        while (j < n && v[j] == v[i]) j++;
        long count = (long)(j - i);
        if (count > best_count) { best_count = count; mode = v[i]; }
        i = j;
    }

    printf("median: %g\nmode: %ld\n", median, mode);
    free(v);
    return 0;
}
```
Sorting first makes the median a single index lookup and turns the mode scan into a linear pass over runs. The `strtol` + `end == line` check rejects blank lines instead of reading them as zero, and the array doubles on demand, so there's no fixed input limit.

