#include <algorithm>
#include <cctype>
#include <iostream>
#include <queue>
#include <sstream>
#include <string>
#include <unordered_map>
#include <vector>

static std::string normalize(const std::string& w) {
    std::string out;
    for (unsigned char c : w) {
        if (std::isalnum(c)) out.push_back(static_cast<char>(std::tolower(c)));
    }
    return out;
}

int main(int argc, char** argv) {
    int k = 3;
    if (argc > 1) k = std::max(0, std::atoi(argv[1]));

    std::unordered_map<std::string, int> freq;
    std::string line;
    while (std::getline(std::cin, line)) {
        std::istringstream iss(line);
        std::string tok;
        while (iss >> tok) {
            std::string word = normalize(tok);
            if (!word.empty()) ++freq[word];
        }
    }
    if (k == 0 || freq.empty()) return 0;

    using Pair = std::pair<int, std::string>;  // count, word
    std::priority_queue<Pair, std::vector<Pair>, std::greater<Pair>> heap;
    for (const auto& [word, count] : freq) {
        heap.push({count, word});
        if (static_cast<int>(heap.size()) > k) heap.pop();
    }

    std::vector<Pair> top;
    while (!heap.empty()) { top.push_back(heap.top()); heap.pop(); }
    std::sort(top.begin(), top.end(), [](const Pair& a, const Pair& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second < b.second;
    });
    for (const auto& [count, word] : top) std::cout << word << ' ' << count << '\n';
    return 0;
}
```

