use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::{Arc, Mutex};
use std::thread;

fn worker_pool(jobs: Vec<u64>, workers: usize) -> Vec<u64> {
    if jobs.is_empty() || workers == 0 {
        return Vec::new();
    }
    let workers = workers.min(jobs.len());
    let queue: Arc<Mutex<Vec<(usize, u64)>>> = Arc::new(Mutex::new(
        jobs.into_iter().enumerate().collect(),
    ));
    let (tx, rx): (Sender<Vec<(usize, u64)>>, Receiver<Vec<(usize, u64)>>) = channel();

    let mut handles = Vec::with_capacity(workers);
    for _ in 0..workers {
        let q = Arc::clone(&queue);
        let tx = tx.clone();
        handles.push(thread::spawn(move || {
            let mut batch = Vec::new();
            loop {
                let item = { q.lock().unwrap().pop() };
                match item {
                    Some((idx, value)) => batch.push((idx, value * value)),
                    None => break,
                }
            }
            tx.send(batch).unwrap();
        }));
    }
    drop(tx);

    let mut results: Vec<Option<u64>> = vec![None; jobs_len_placeholder(&queue)];
    for batch in rx.iter() {
        for (idx, value) in batch {
            results[idx] = Some(value);
        }
    }
    for h in handles {
        h.join().unwrap();
    }
    results.into_iter().map(|v| v.unwrap()).collect()
}

fn jobs_len_placeholder(_: &Arc<Mutex<Vec<(usize, u64)>>>) -> usize {
    0
}

fn main() {
    let out = worker_pool((1..=8).collect(), 3);
    println!("{:?}", out);
}
```

