import functools
import random
import time

def retry(exc_types=(Exception,), tries=4, base=0.1, cap=5.0):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(tries):
                try:
                    return fn(*args, **kwargs)
                except exc_types as e:
                    last = e
                    if attempt == tries - 1:
                        break
                    delay = min(cap, base * (2 ** attempt))
                    time.sleep(delay * random.uniform(0.5, 1.5))
            raise last  # exhausted; re-raise the original
        return wrapper
    return deco


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(exc_types=(ValueError,), tries=3, base=0.001)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError(f"boom {calls['n']}")
        return "done"

    print(flaky(), "attempts:", calls["n"])

    @retry(exc_types=(ValueError,), tries=3, base=0.001)
    def wrong_type():
        raise KeyError("not retried")

    try:
        wrong_type()
    except KeyError as e:
        print("KeyError propagated, not retried:", e)
```

Jitter multiplies each backoff by a random 0.5–1.5 factor to avoid thundering-herd retries. Exceptions not in `exc_types` propagate on the first attempt untouched.

```rust
fn split_utf8(s: &str, max_bytes: usize) -> Vec<&str> {
    if max_bytes == 0 || s.is_empty() {
        return Vec::new();
    }
    let mut out = Vec::new();
    let mut start = 0;
    while start < s.len() {
        let mut end = (start + max_bytes).min(s.len());
        // move back until we are on a char boundary
        while end > start && !s.is_char_boundary(end) {
            end -= 1;
        }
        if end == start {
            // max_bytes smaller than the next char; take one full char
            end = start + s[start..].chars().next().unwrap().len_utf8();
        }
        out.push(&s[start..end]);
        start = end;
    }
    out
}

fn main() {
    let s = "héllo 😀 wörld";
    let parts = split_utf8(s, 4);
    for p in &parts {
        assert!(p.len() <= s.len());
        print!("[{}]", p);
    }
    println!();
    assert_eq!(parts.concat(), s);
    assert_eq!(split_utf8("", 4), Vec::<&str>::new());
    assert_eq!(split_utf8("abc", 0), Vec::<&str>::new());
    println!("len ok, all boundaries valid");
}
```

`is_char_boundary(end)` returns false when a multibyte char straddles `end`. The `end == start` fallback handles `max_bytes` smaller than one codepoint (e.g. 1 byte of `😀`), emitting one whole char rather than a broken slice.

```cpp
#include <cassert>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
    T data_[N];
    std::size_t head_ = 0, tail_ = 0, size_ = 0;
public:
    bool empty() const { return size_ == 0; }
    bool full()  const { return size_ == N; }
    std::size_t size() const { return size_; }

    bool push(const T& value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }
    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T v = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }
};

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.empty());
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.full() && !rb.push(4));
    assert(rb.pop().value() == 1);
    assert(!rb.full());
    assert(rb.push(4));
    assert(rb.pop().value() == 2);
    assert(rb.pop().value() == 3);
    assert(rb.pop().value() == 4);
    assert(rb.empty() && !rb.pop().has_value());
    std::cout << "all ring buffer assertions passed\n";
}
```

Capacity `N` is fixed at compile time via the template, so there is no heap allocation. `std::optional` distinguishes an empty pop from a stored default value without sentinels.

