#include <iostream>
#include <string>
#include <algorithm>

void reverseWords(std::string& s) {
    // reverse whole string
    std::reverse(s.begin(), s.end());
    // reverse each word, compact spaces in place
    size_t write = 0;
    for (size_t i = 0; i < s.size(); ) {
        while (i < s.size() && s[i] == ' ') ++i;
        if (i >= s.size()) break;
        if (write > 0) s[write++] = ' ';
        size_t start = i;
        while (i < s.size() && s[i] != ' ') s[write++] = s[i++];
        std::reverse(s.begin() + (write - (i - start)), s.begin() + write);
    }
    s.resize(write);
}

int main() {
    std::string a = "  hello   world  ";
    reverseWords(a);
    std::cout << '[' << a << ']' << '\n';
    std::string b = "";
    reverseWords(b);
    std::cout << '[' << b << ']' << '\n';
}
