#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;                                  // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap
    int x;
    bool first = true;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);

        if (low.size() > high.size() + 1) { high.push(low.top()); low.pop(); }
        else if (high.size() > low.size()) { low.push(high.top()); high.pop(); }

        double median = (low.size() == high.size())
                            ? (low.top() + high.top()) / 2.0
                            : (double)low.top();
        if (!first) std::cout << '\n';
        first = false;
        std::cout << median;
    }
    std::cout << '\n';
    return 0;
}
```
Keeps the lower half in a max-heap and the upper half in a min-heap, rebalancing so their sizes differ by at most one. The median is the top of `low`, or the average of both tops when sizes match; rebalance after every insert keeps it O(log n) per value.

