```cpp
#include <cstddef>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <utility>

template <typename T, std::size_t N>
class FixedStack {
public:
    void push(T value) {
        if (size_ == N) {
            throw std::overflow_error("stack full");
        }
        new (&buf_[size_]) T(std::move(value));
        ++size_;
    }

    T pop() {
        if (size_ == 0) {
            throw std::underflow_error("stack empty");
        }
        --size_;
        T out = std::move(*ptr(size_));
        ptr(size_)->~T();
        return out;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

    ~FixedStack() {
        for (std::size_t i = 0; i < size_; ++i) {
            ptr(i)->~T();
        }
    }

private:
    T* ptr(std::size_t i) {
        return reinterpret_cast<T*>(&buf_[i]);
    }

    alignas(T) unsigned char buf_[N * sizeof(T)]{};
    std::size_t size_ = 0;
};

struct MoveOnly {
    int id;
    explicit MoveOnly(int v) : id(v) {}
    MoveOnly(MoveOnly&&) = default;
    MoveOnly(const MoveOnly&) = delete;
};

int main() {
    FixedStack<MoveOnly, 3> s;
    s.push(MoveOnly(1));
    s.push(MoveOnly(2));
    std::cout << s.pop().id << '\n';  // 2
    std::cout << s.size() << '\n';    // 1
    try {
        s.pop();
        s.pop();
    } catch (const std::underflow_error& e) {
        std::cout << e.what() << '\n';
    }
    return 0;
}
```

Raw storage plus placement-new is what lets the container hold a move-only type; the destructor calls `~T()` only on the constructed prefix, so empty slots are never destroyed. Capacity is a compile-time parameter, and both overflow and underflow throw rather than corrupt state.

