def check_brackets(s):
    """Return None if balanced, else the 0-based index of the offending char."""
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for i, ch in enumerate(s):
        if ch in '([{':
            stack.append((ch, i))
        elif ch in pairs:
            if not stack or stack[-1][0] != pairs[ch]:
                return i
            stack.pop()
    if stack:
        return stack[-1][1]
    return None


