```python
import heapq


class MedianFinder:
    def __init__(self):
        self.low = []   # max-heap via negated values, holds smaller half
        self.high = []  # min-heap, holds larger half

    def add(self, num):
        heapq.heappush(self.low, -num)
        heapq.heappush(self.high, -heapq.heappop(self.low))
        if len(self.low) < len(self.high):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def get_median(self):
        if not self.low and not self.high:
            raise ValueError("no numbers added yet")
        if len(self.low) > len(self.high):
            return -self.low[0]
        return (-self.low[0] + self.high[0]) / 2


if __name__ == "__main__":
    mf = MedianFinder()
    for v in [5, 15, 1, 3]:
        mf.add(v)
    assert mf.get_median() == 4.0
    mf.add(8)
    assert mf.get_median() == 5
    empty = MedianFinder()
    try:
        empty.get_median()
        raise AssertionError("should have raised")
    except ValueError:
        pass
    print("all tests passed")
```
`low` stores the smaller half as negated values so a max-heap comes free from the min-heap, and the size invariant (`low` holds at most one more than `high`) is restored after each insert. Even totals average the two roots; empty state raises instead of returning a fabricated number.

