#include <iostream>
#include <queue>
#include <vector>
#include <functional>

int main() {
    std::priority_queue<int> low;                            // max-heap, lower half
    std::priority_queue<int, std::vector<int>, std::greater<int>> high; // min-heap, upper half

    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);

