        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }
    }

    if (low.empty()) {
        std::cerr << "no numbers\n";
        return 1;
