fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let expected = match c {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(expected) {
                    return false;
                }
            }
            _ => {} // ignore other characters
        }
    }
    stack.is_empty()
}

fn main() {
    let cases = ["()[]{}", "([{}])", "(]", "(()", "{[()]}", ""];
    for c in cases {
        println!("{:?} -> {}", c, is_balanced(c));
    }
    // true, true, false, false, true, true
}
