```python
def lcs(a: str, b: str) -> str:
    """Return one longest common subsequence of a and b."""
    n, m = len(a), len(b)
    # dp[i][j] = LCS length of a[:i] and b[:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct by walking back from dp[n][m].
    out = []
    i, j = n, m
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            out.append(a[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1
    return "".join(reversed(out))


if __name__ == "__main__":
    print(lcs("ABCBDAB", "BDCABA"))  # BCBA
    print(lcs("", "abc"))            # ''
    print(lcs("abc", "abc"))         # abc
```

The table is `(n+1) x (m+1)` so the empty-prefix row/column are the base cases. Reconstruction walks from the bottom-right corner, preferring diagonal matches and otherwise moving toward the larger neighbour. Complexity is O(n*m) time and space.

