#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

// Rotate v right by k positions, in place: [1,2,3,4], k=1 -> [4,1,2,3].
void rotate_right(std::vector<int>& v, std::size_t k) {
    const std::size_t n = v.size();
    if (n == 0) return;
    k %= n;                       // k larger than n wraps around
    if (k == 0) return;
    std::reverse(v.begin(), v.end());
    std::reverse(v.begin(), v.begin() + static_cast<long>(k));
    std::reverse(v.begin() + static_cast<long>(k), v.end());
}

int main() {
    std::vector<int> empty;
    rotate_right(empty, 5);       // must not crash
    assert(empty.empty());

    std::vector<int> a{1, 2, 3, 4, 5};
    rotate_right(a, 2);
    assert((a == std::vector<int>{4, 5, 1, 2, 3}));

    std::vector<int> b{1, 2, 3};
    rotate_right(b, 7);           // 7 % 3 == 1
    assert((b == std::vector<int>{3, 1, 2}));

    std::vector<int> c{1, 2, 3};
    rotate_right(c, 3);           // full turn, unchanged
    assert((c == std::vector<int>{1, 2, 3}));

    std::cout << "all tests passed\n";
    return 0;
}
