/// Greatest common divisor using the Euclidean algorithm.
/// Works for negatives via unsigned magnitude; gcd(0, 0) is defined as 0.
fn gcd(mut a: i64, mut b: i64) -> i64 {
    a = a.wrapping_abs();
    b = b.wrapping_abs();
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}

