Use `char::is_alphanumeric` for Unicode-aware splitting, lowercase keys via `to_lowercase`, and break frequency ties alphabetically so output is deterministic.

```rust
use std::cmp::Reverse;
use std::collections::HashMap;

pub fn top_k(text: &str, k: usize) -> Vec<(String, usize)> {
    if k == 0 {
        return Vec::new();
    }
    let mut counts: HashMap<String, usize> = HashMap::new();
    let mut word = String::new();

    let mut flush = |word: &mut String, counts: &mut HashMap<String, usize>| {
        if !word.is_empty() {
            *counts.entry(std::mem::take(word)).or_insert(0) += 1;
        }
    };

    for ch in text.chars() {
        if ch.is_alphanumeric() {
            word.extend(ch.to_lowercase());
        } else {
            flush(&mut word, &mut counts);
        }
    }
    flush(&mut word, &mut counts);

    let mut ranked: Vec<(String, usize)> = counts.into_iter().collect();
    ranked.sort_by_key(|(w, c)| (Reverse(*c), w.clone()));
    ranked.truncate(k);
    ranked
}

#[cfg(test)]
mod tests {
    use super::*;

