Line-by-line validation so one broken line never aborts the run; problems are collected and reported at the end.

```python
import json
import sys


def validate(path):
    errors = []
    total = 0
    with open(path, "r", encoding="utf-8") as fh:
        for lineno, raw in enumerate(fh, start=1):
            raw = raw.strip()
            if not raw:
                continue
            total += 1
            try:
                rec = json.loads(raw)
            except json.JSONDecodeError as exc:
                errors.append((lineno, f"malformed JSON: {exc.msg}"))
                continue
            if not isinstance(rec, dict):
                errors.append((lineno, "record is not an object"))
                continue
            rid = rec.get("id")
            if not isinstance(rid, str) or not rid:
                errors.append((lineno, "'id' must be a non-empty string"))
            score = rec.get("score")
            if isinstance(score, bool) or not isinstance(score, int):
                errors.append((lineno, "'score' must be an integer"))
            elif not 0 <= score <= 100:
                errors.append((lineno, f"'score' out of range: {score}"))
    return total, errors


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"usage: {sys.argv[0]} <file.jsonl>", file=sys.stderr)
        sys.exit(2)
    count, problems = validate(sys.argv[1])
    for lineno, msg in problems:
        print(f"line {lineno}: {msg}")
    print(f"checked {count} record(s), {len(problems)} problem(s)")
```

`isinstance(score, bool)` is excluded on purpose: in Python `True` is an `int`, and a boolean score is almost certainly a bug.

`VecDeque` with `push_back` and `pop_front` gives O(1) eviction at a fixed capacity. Capacity zero is rejected at construction rather than silently misbehaving.

```rust
use std::collections::VecDeque;

pub struct Ring<T> {
    cap: usize,
    buf: VecDeque<T>,
}

impl<T> Ring<T> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        Ring { cap, buf: VecDeque::with_capacity(cap) }
    }

    pub fn push(&mut self, value: T) -> Option<T> {
        let evicted = if self.buf.len() == self.cap {
            self.buf.pop_front()
        } else {
            None
        };
        self.buf.push_back(value);
        evicted
    }

    pub fn latest(&self) -> Option<&T> {
        self.buf.back()
    }

    pub fn len(&self) -> usize {
        self.buf.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn evicts_oldest() {
        let mut r = Ring::new(3);
        assert_eq!(r.push(1), None);
        assert_eq!(r.push(2), None);
        assert_eq!(r.push(3), None);
        assert_eq!(r.push(4), Some(1));
        assert_eq!(r.len(), 3);
        assert_eq!(r.latest(), Some(&4));
    }
}
```

Welford avoids the cancellation error of the naive sum-of-squares formula, especially for large offsets.

```cpp
#include <cmath>
#include <cstdio>
#include <iostream>

int main() {
    double mean = 0.0, m2 = 0.0;
    long long n = 0;
    double x;
    while (std::cin >> x) {
        ++n;
        double delta = x - mean;
        mean += delta / n;
        m2 += delta * (x - mean);
    }
    if (n == 0) {
        std::cout << "no data\n";
        return 0;
    }
    double variance = m2 / n;            // population variance
    double sd = std::sqrt(variance < 0.0 ? 0.0 : variance);
    std::printf("n=%lld mean=%.2f sd=%.2f\n", n, mean, sd);
    return 0;
}
