A single awk pass keeps the running min and max per key and emits sorted output at END.

```bash
#!/usr/bin/env bash
# usage: user-span.sh <file>
set -euo pipefail

FILE="${1:-}"
if [[ -z "$FILE" || ! -r "$FILE" ]]; then
    echo "usage: $0 <readable-file>" >&2
    exit 2
fi

awk -F: '
    NF < 2 { next }
    {
        user = $1
        ts = $2
        if (!(user in first) || ts < first[user]) first[user] = ts
        if (!(user in last)  || ts > last[user])  last[user]  = ts
        seen[user] = 1
    }
    END {
        n = 0
        for (u in seen) users[++n] = u
        for (i = 1; i < n; i++)
            for (j = i + 1; j <= n; j++)
                if (users[j] < users[i]) { t = users[i]; users[i] = users[j]; users[j] = t }
        for (i = 1; i <= n; i++) {
            u = users[i]
            printf "%s %s %s\n", u, first[u], last[u]
        }
    }
' "$FILE"
