Jitter uses `random.uniform` and the decorator preserves the wrapped function's metadata via `functools.wraps`.

```python
import functools
import random
import time


def retry(attempts=3, base_delay=0.5, max_delay=10.0, factor=2.0,
          jitter=0.1, exceptions=(Exception,)):
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == attempts:
                        raise
                    sleep = min(delay, max_delay)
                    sleep += random.uniform(0, sleep * jitter)
                    time.sleep(sleep)
                    delay *= factor
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base_delay=0.01, exceptions=(ValueError,))
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return "ok"

    assert flaky() == "ok"
    assert calls["n"] == 3
    print("passed after", calls["n"], "attempt(s)")
```

The final attempt re-raises the original exception instead of sleeping one more time, so the total wall-clock cost is bounded.

Reads fixed 16-byte chunks with `fread`; non-printable bytes become `.` in the ASCII column.

```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 2;
    }
    FILE *fp = fopen(argv[1], "rb");
    if (!fp) {
        perror(argv[1]);
        return 1;
    }

    unsigned char buf[16];
    size_t n, offset = 0;
    while ((n = fread(buf, 1, sizeof buf, fp)) > 0) {
        printf("%08zx  ", offset);
        for (size_t i = 0; i < 16; i++) {
            if (i < n) printf("%02x ", buf[i]);
            else        printf("   ");
            if (i == 7) printf(" ");
        }
        printf(" |");
        for (size_t i = 0; i < n; i++)
            putchar(isprint(buf[i]) ? buf[i] : '.');
        printf("|\n");
        offset += n;
    }

    if (ferror(fp)) {
        perror("read");
        fclose(fp);
        return 1;
    }
    fclose(fp);
    return 0;
}
```

`fread` can return short counts, and the loop handles the final partial line by padding the hex column with spaces.

