#include <cstddef>
#include <stdexcept>
#include <unordered_map>
#include <utility>
#include <vector>

std::pair<std::size_t, std::size_t>
find_pair(const std::vector<int>& nums, int target) {
    std::unordered_map<int, std::size_t> seen;
    for (std::size_t i = 0; i < nums.size(); ++i) {
        auto it = seen.find(target - nums[i]);
        if (it != seen.end()) {
            return {it->second, i};
        }
        seen.emplace(nums[i], i);
    }
    throw std::runtime_error("no pair sums to target");
}

