use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
pub enum ParseError {
    Empty,
    Invalid(String),
    Overflow(String),
}

pub fn parse_u8_checked(input: &str) -> Result<u8, ParseError> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err(ParseError::Empty);
    }
    trimmed.parse::<u8>().map_err(|e: ParseIntError| {
        if e.kind() == &std::num::IntErrorKind::PosOverflow {
            ParseError::Overflow(trimmed.to_string())
        } else {
            ParseError::Invalid(trimmed.to_string())
        }
    })
}

