```c
#include <stdio.h>
#include <stdbool.h>

unsigned long long fib(int n, bool *overflowed) {
    *overflowed = false;
    if (n < 0) {
        *overflowed = true;
        return 0;
    }
    unsigned long long a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        if (b > 0 && a > ~0ULL - b) {  /* a + b would wrap */
            *overflowed = true;
            break;
        }
        unsigned long long next = a + b;
        a = b;
        b = next;
    }
    return a;
}

int main(void) {
    bool over;
    for (int n = 0; n <= 93; n++) {
        unsigned long long v = fib(n, &over);
        printf("fib(%d) = %llu%s\n", n, v, over ? " (overflow)" : "");
    }
    return 0;
}
```

