```python
from collections import OrderedDict
from typing import Optional


class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._data: "OrderedDict" = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    print(c.get("a"))   # 1, promotes a
    c.put("c", 3)        # evicts b (least recently used)
    print(c.get("b"))   # None
    print(c.get("c"))   # 3
```

`OrderedDict` gives O(1) promotions via `move_to_end` and O(1) eviction via `popitem(last=False)`. A `get` on an existing key counts as a use, so it moves the entry to the most-recent end before returning the value.

