#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) {
        return;
    }
    char *end = s;
    while (*end != '\0') {
        end++;
    }
    if (end == s) {
        return; /* empty string */
    }
    end--;
    char *start = s;
    while (start < end) {
        char tmp = *start;
        *start = *end;
        *end = tmp;
        start++;
        end--;
    }
}

