bool is_palindrome(long long x) {
    if (x < 0) return false;
    if (x < 10) return true;
    long long original = x;
    long long reversed = 0;
    while (x > 0) {
        reversed = reversed * 10 + (x % 10);
        x /= 10;
    }
    return reversed == original;
