```rust
fn longest_common_prefix(words: &[&str]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = words[0];
    'outer: for (i, ch) in first.char_indices() {
        for w in &words[1..] {
            match w.get(i..i + ch.len_utf8()) {
                Some(part) if part.starts_with(ch) => {}
                _ => break 'outer,
            }
        }
    }
    // rebuild the prefix from char boundaries
    first
        .char_indices()
        .take_while(|(i, ch)| {
            words[1..]
                .iter()
                .all(|w| w.get(*i..*i + ch.len_utf8()) == Some(&w[*i..*i + ch.len_utf8()]))
        })
        .map(|(_, ch)| ch)
        .collect()
}

fn main() {
    println!("{:?}", longest_common_prefix(&[]));
    println!("{:?}", longest_common_prefix(&["flower", "flow", "flight"]));
    println!("{:?}", longest_common_prefix(&["dog", "racecar", "car"]));
}
```

