```python
def balanced_brackets(s: str) -> bool:
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set(pairs.values())
    stack = []
    in_str = None
    escaped = False

    for ch in s:
        if in_str:
            if escaped:
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == in_str:
                in_str = None
            continue
        if ch in ('"', "'"):
            in_str = ch
        elif ch in openers:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False

    return not stack


if __name__ == "__main__":
    tests = ["(a[b]{c})", "(a[b)}", "'{' unbalanced", '"{" ok', "(()"]
    for t in tests:
        print(balanced_brackets(t), repr(t))
```

A stack tracks openers; a small state machine skips any text inside single- or double-quoted literals, honoring backslash escapes. Closing brackets must match the most recent opener, and the string is balanced only if the stack is empty at the end.

