#include <stdio.h>

static void fib_pair(unsigned n, unsigned long long *a, unsigned long long *b) {
    if (n == 0) {
        *a = 0; *b = 1;
        return;
    }
    unsigned long long x, y;
    fib_pair(n >> 1, &x, &y);
    unsigned long long c = x * (2 * y - x);
    unsigned long long d = x * x + y * y;
    if (n & 1) {
        *a = d; *b = c + d;
    } else {
        *a = c; *b = d;
    }
}

unsigned long long fib(unsigned n) {
    unsigned long long a, b;
    fib_pair(n, &a, &b);
    return a;
}

int main(void) {
    printf("%llu\n", fib(0));
    printf("%llu\n", fib(1));
    printf("%llu\n", fib(10));
    printf("%llu\n", fib(50));
    return 0;
}
