std::vector<int> merge_sorted(const std::vector<int>& a,
                              const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else               out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 3, 7};
    std::vector<int> b{2, 3, 8};
    auto merged = merge_sorted(a, b);
    for (int v : merged) std::cout << v << ' ';
    std::cout << '\n';

    std::vector<int> empty;
    auto only_b = merge_sorted(empty, b);
    std::cout << only_b.size() << '\n';
    return 0;
}
