use std::collections::HashMap;

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let clean: String = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if clean.is_empty() {
            continue;
        }
        *counts.entry(clean).or_insert(0) += 1;
    }
    let mut ranked: Vec<(String, usize)> = counts.into_iter().collect();
    ranked.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    ranked.truncate(n);
    ranked
}

fn main() {
    let text = "The the quick Brown brown fox FOx!";
    let top = top_words(text, 2);
    println!("{:?}", top);
    assert_eq!(top_words("", 5).len(), 0);
    assert_eq!(top_words("a A b", 1)[0], ("a".to_string(), 2));
}
