bool balanced(const std::string& line) {
    std::stack<char> open;
    for (char c : line) {
        switch (c) {
            case '(': case '[': case '{': open.push(c); break;
            case ')':
                if (open.empty() || open.top() != '(') return false;
                open.pop(); break;
            case ']':
                if (open.empty() || open.top() != '[') return false;
                open.pop(); break;
            case '}':
                if (open.empty() || open.top() != '{') return false;
                open.pop(); break;
            default: break;
        }
    }
    return open.empty();
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::cout << (balanced(line) ? "yes" : "no") << '\n';
    }
    return 0;
}
