def two_smallest(values):
    """Return the two smallest distinct numbers in values.

    Raises ValueError if fewer than two distinct values exist.
    """
    seen = []
    for v in values:
        if v not in seen:
            seen.append(v)
            if len(seen) == 2:
                break
    if len(seen) < 2:
        raise ValueError("need at least two distinct values")
    first, second = sorted(seen)
    for v in values:
        if v < first:
            second = first
            first = v
        elif first < v < second:
            second = v
    return first, second


