import math


def floyd_warshall(n, edges):
    """edges: list of (u, v, weight). Returns (dist, has_negative_cycle)."""
    dist = [[math.inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        if w < dist[u][v]:
            dist[u][v] = w
    for k in range(n):
        for i in range(n):
            if dist[i][k] == math.inf:
                continue
            for j in range(n):
                cand = dist[i][k] + dist[k][j]
                if cand < dist[i][j]:
                    dist[i][j] = cand
    negative_cycle = any(dist[i][i] < 0 for i in range(n))
    return dist, negative_cycle


if __name__ == "__main__":
    n = 4
    edges = [(0, 1, 3), (0, 3, 7), (1, 2, 1), (2, 3, 2), (3, 1, 2)]
    d, neg = floyd_warshall(n, edges)
    assert d[0][3] == 6  # 0->1->2->3
    assert not neg

    d2, neg2 = floyd_warshall(2, [(0, 1, 1), (1, 0, -3)])
    assert neg2, "expected negative cycle"
    print("ok")
```

The negative-cycle check works because a negative diagonal means a path from a node back to itself with total weight below zero.

