```cpp
#include <cstdint>
#include <iostream>

std::uint64_t isqrt(std::uint64_t n) {
    if (n < 2) return n;
    std::uint64_t lo = 1, hi = n / 2 + 1, ans = 1;
    while (lo <= hi) {
        std::uint64_t mid = lo + (hi - lo) / 2;
        // compare mid*mid <= n without overflow
        if (mid <= n / mid) {
            ans = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return ans;
}

int main() {
    std::cout << isqrt(0) << '\n';                 // 0
    std::cout << isqrt(15) << '\n';                // 3
    std::cout << isqrt(16) << '\n';                // 4
    std::cout << isqrt(18446744073709551615ULL);   // 4294967295
}
```

