    std::unordered_set<T> seen;
    result.reserve(input.size());
    for (const auto& value : input) {
        if (seen.insert(value).second) {
            result.push_back(value);
        }
    }
    return result;
}

int main() {
    std::vector<int> data{3, 1, 3, 2, 1, 4};
    auto out = dedup_preserving_order(data);
    for (size_t i = 0; i < out.size(); ++i) {
        std::cout << out[i] << (i + 1 < out.size() ? ", " : "\n");
    }
    return 0;
}
```

`unordered_set::insert` returns a pair whose `second` is `true` only the first time a value is inserted, so elements are pushed in original order and later duplicates are skipped. Runs in expected O(n) time; requires `operator==` and `std::hash` for `T`.

