```python
from collections import OrderedDict


class FifoCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._store = OrderedDict()
        self.hits = 0
        self.misses = 0

    def get(self, key):
        if key in self._store:
            self.hits += 1
            return self._store[key]
        self.misses += 1
        return None

    def put(self, key, value):
        if key not in self._store:
            if len(self._store) >= self.capacity:
                self._store.popitem(last=False)  # evict oldest
        self._store[key] = value

    @property
    def hit_rate(self):
        total = self.hits + self.misses
        return 0.0 if total == 0 else self.hits / total


if __name__ == "__main__":
    c = FifoCache(2)
    c.put("a", 1); c.put("b", 2); c.put("c", 3)  # evicts a
    assert c.get("a") is None      # miss
    assert c.get("b") == 2         # hit
    assert abs(c.hit_rate - 0.5) < 1e-9
    print("ok")
```

`OrderedDict.popitem(last=False)` removes the oldest inserted key, giving strict FIFO eviction; note that `get` does not move keys, so access order is irrelevant. The hit-rate property guards against division by zero before any lookup happens.

