def rle_encode(s):
    if not s:
        return []
    encoded = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            encoded.append((s[i - 1], count))
            count = 1
    encoded.append((s[-1], count))
    return encoded


def rle_decode(pairs):
    return "".join(ch * count for ch, count in pairs)


if __name__ == "__main__":
    for original in ["", "a", "aaabbbcccd", "abcd", "wwwwwwww"]:
        assert rle_decode(rle_encode(original)) == original
    assert rle_encode("aaabb") == [("a", 3), ("b", 2)]
    print("ok")
