    while (i < n) {
        while (i < n && s[i] == ' ') ++i;
        size_t start = i;
        while (i < n && s[i] != ' ') ++i;
        if (i > start) words.push_back(s.substr(start, i - start));
    }
    std::string out;
    for (size_t k = words.size(); k-- > 0;) {
        if (!out.empty()) out += ' ';
        out += words[k];
    }
    return out;
}

