```cpp
#include <list>
#include <stdexcept>
#include <unordered_map>
#include <iostream>

class LRUCache {
public:
    explicit LRUCache(size_t capacity) : cap_(capacity) {
        if (cap_ == 0) throw std::invalid_argument("capacity must be > 0");
    }

    int get(int key) {
        auto it = map_.find(key);
        if (it == map_.end()) return -1;
        items_.splice(items_.begin(), items_, it->second);
        return it->second->second;
    }

    void put(int key, int value) {
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (items_.size() == cap_) {
            map_.erase(items_.back().first);
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        map_[key] = items_.begin();
    }

private:
    size_t cap_;
    std::list<std::pair<int, int>> items_;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> map_;
};

int main() {
    LRUCache c(2);
    c.put(1, 1);
    c.put(2, 2);
    std::cout << c.get(1) << "\n"; // 1
    c.put(3, 3);                   // evicts key 2
    std::cout << c.get(2) << "\n"; // -1
    c.put(4, 4);                   // evicts key 1
    std::cout << c.get(1) << "\n"; // -1
    std::cout << c.get(3) << "\n"; // 3
    std::cout << c.get(4) << "\n"; // 4
    return 0;
}
```

`splice` moves the node without reallocating, so both operations stay O(1). The map stores list iterators rather than indices, otherwise eviction would be O(n). A zero capacity is rejected up front instead of silently corrupting state.

