    char empty[] = "";
    char one[] = "x";

    reverse_in_place(buf);
    reverse_in_place(empty);
    reverse_in_place(one);
    reverse_in_place(NULL);

    printf("%s|%s|%s\n", buf, empty, one);
    return 0;
}
