    std::vector<long long> out;
    std::stringstream ss(line);
    std::string field;
    while (std::getline(ss, field, ',')) {
        size_t i = 0, n = field.size();
        while (i < n && std::isspace(static_cast<unsigned char>(field[i]))) ++i;
        size_t j = n;
        while (j > i && std::isspace(static_cast<unsigned char>(field[j - 1]))) --j;
        if (i == j) continue;  // empty field
        try {
            size_t pos = 0;
            long long v = std::stoll(field.substr(i, j - i), &pos);
            if (pos != j - i) continue;  // trailing junk -> skip
            out.push_back(v);
        } catch (const std::exception&) {
            // ignore malformed field
        }
    }
    return out;
}

