#[derive(Debug)]
pub struct RingBuffer<const N: usize> {
    data: [f32; N],
    head: usize,
    len: usize,
}

impl<const N: usize> RingBuffer<N> {
    pub fn new() -> Self {
        Self { data: [0.0; N], head: 0, len: 0 }
    }

    pub fn push(&mut self, v: f32) {
        if N == 0 {
            return;
        }
        let idx = (self.head + self.len) % N;
        self.data[idx] = v;
        if self.len == N {
            self.head = (self.head + 1) % N; // overwrite oldest
        } else {
            self.len += 1;
        }
    }

    pub fn iter(&self) -> impl Iterator<Item = &f32> {
        (0..self.len).map(move |i| &self.data[(self.head + i) % N])
    }

    pub fn mean(&self) -> Option<f32> {
        if self.len == 0 {
            return None;
        }
        Some(self.iter().sum::<f32>() / self.len as f32)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn overwrites_oldest() {
        let mut rb = RingBuffer::<3>::new();
        rb.push(1.0);
        rb.push(2.0);
        rb.push(3.0);
        rb.push(4.0);
        let vals: Vec<f32> = rb.iter().copied().collect();
        assert_eq!(vals, vec![2.0, 3.0, 4.0]);
        assert_eq!(rb.mean(), Some(3.0));
    }

    #[test]
    fn empty_mean_is_none() {
        let rb = RingBuffer::<4>::new();
        assert_eq!(rb.mean(), None);
    }
}
