#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <vector>

class Arena {
public:
    explicit Arena(std::size_t bytes) : buf_(bytes) {}

    void* alloc(std::size_t n, std::size_t align = alignof(std::max_align_t)) {
        std::size_t cur = reinterpret_cast<std::uintptr_t>(buf_.data()) + used_;
        std::size_t pad = (align - (cur % align)) % align;
        if (used_ + pad + n > buf_.size()) return nullptr;
        void* p = buf_.data() + used_ + pad;
        used_ += pad + n;
        return p;
    }

    template <typename T, typename... Args>
    T* make(Args&&... args) {
        void* p = alloc(sizeof(T), alignof(T));
        if (!p) return nullptr;
        return new (p) T(static_cast<Args&&>(args)...);
    }

    std::size_t used() const { return used_; }
    std::size_t capacity() const { return buf_.size(); }

private:
    std::vector<std::byte> buf_;
    std::size_t used_ = 0;
};

struct Node {
    int value;
    Node* next;
};

int main() {
    Arena arena(512);
    Node* head = nullptr;
    for (int i = 5; i >= 1; --i) {
        Node* n = arena.make<Node>();
        if (!n) { std::puts("arena full"); return 1; }
        n->value = i;
        n->next = head;
        head = n;
    }
    for (Node* p = head; p; p = p->next) std::printf("%d ", p->value);
    std::printf("\nused=%zu/%zu\n", arena.used(), arena.capacity());
    // No per-node free: the whole arena goes away at once.
}
