def lcs(a, b):
    """Return (length, one longest common subsequence) of strings a and b."""
    n, m = len(a), len(b)
    # dp[i][j] = LCS length of a[:i] and b[:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        ai = a[i - 1]
        for j in range(1, m + 1):
            if ai == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Walk back to recover one subsequence.
    i, j, out = n, m, []
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            out.append(a[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1
    out.reverse()
    return dp[n][m], "".join(out)


if __name__ == "__main__":
    assert lcs("", "abc") == (0, "")
    assert lcs("abc", "") == (0, "")
    assert lcs("abc", "abc") == (3, "abc")
    assert lcs("AGGTAB", "GXTXAYB") == (4, "GTAB")
    length, sub = lcs("héllo", "hllo")
    assert length == 4 and sub == "hllo"
    print("ok")
