import unicodedata

def reverse_graphemes(s: str) -> str:
    """Reverse a string by grapheme clusters using NFC normalization."""
    if not s:
        return ""
    normalized = unicodedata.normalize("NFC", s)
    clusters = []
    for ch in normalized:
        if unicodedata.combining(ch) and clusters:
            clusters[-1] += ch
        else:
            clusters.append(ch)
    return "".join(reversed(clusters))

if __name__ == "__main__":
    tests = ["", "abc", "cafe\u0301", "\U0001F600ab"]
    for t in tests:
        print(repr(t), "->", repr(reverse_graphemes(t)))
```

