```cpp
#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        if (size_ == N) {
            throw std::overflow_error("ring buffer is full");
        }
        data_[(head_ + size_) % N] = value;
        ++size_;
    }

    std::optional<T> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    if (rb.full()) std::cout << "full\n";
    while (auto v = rb.pop()) std::cout << *v << '\n';
}
```

The modulo wrap on `(head_ + size_) % N` keeps push O(1) without shifting elements; `pop` on empty returns `std::nullopt` instead of throwing.

