using Value = std::variant<long long, double, std::string>;

static Value parse_value(const std::string& raw) {
    long long i = 0;
    auto [pi, iec] = std::from_chars(raw.data(), raw.data() + raw.size(), i);
    if (iec == std::errc{} && pi == raw.data() + raw.size()) {
        return i;
    }

    double d = 0.0;
    auto [pd, dec] = std::from_chars(raw.data(), raw.data() + raw.size(), d);
    if (dec == std::errc{} && pd == raw.data() + raw.size()) {
        return d;
    }

    return raw;
}

static void print(const std::string& key, const Value& v) {
    std::cout << key << " = ";
    std::visit([](const auto& x) {
        std::cout << x;
    }, v);
    std::cout << '\n';
}

int main() {
    std::unordered_map<std::string, Value> config;
    std::string line;

    while (std::getline(std::cin, line)) {
        if (line.empty() || line[0] == '#') {
            continue;
        }
        const auto colon = line.find(':');
        if (colon == std::string::npos) {
            std::cerr << "skipping line without ':': " << line << '\n';
            continue;
        }
        std::string key = line.substr(0, colon);
        std::string raw = line.substr(colon + 1);
        // Trim ASCII spaces around both sides.
        auto trim = [](std::string s) {
            const auto not_space = [](unsigned char c) { return !std::isspace(c); };
            s.erase(s.begin(), std::find_if(s.begin(), s.end(), not_space));
            s.erase(std::find_if(s.rbegin(), s.rend(), not_space).base(), s.end());
            return s;
        };
        key = trim(key);
        raw = trim(raw);
        if (key.empty()) {
            std::cerr << "skipping empty key\n";
            continue;
        }
        config[key] = parse_value(raw);
    }

    for (const auto& [key, value] : config) {
        print(key, value);
    }
    return 0;
}
```

