```python
from collections import OrderedDict
from typing import Hashable, Optional


class FIFOCache:
    """Fixed-capacity cache; on overflow, the oldest inserted key is evicted."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._data: "OrderedDict[Hashable, object]" = OrderedDict()

    def get(self, key: Hashable) -> Optional[object]:
        # FIFO: a hit does not refresh insertion order.
        return self._data.get(key)

    def put(self, key: Hashable, value: object) -> Optional[Hashable]:
        """Insert; returns the evicted key, if any."""
        if key in self._data:
            self._data[key] = value
            return None
        self._data[key] = value
        if len(self._data) > self._capacity:
            evicted, _ = self._data.popitem(last=False)
            return evicted
        return None

    def __len__(self) -> int:
        return len(self._data)

    def __contains__(self, key: Hashable) -> bool:
        return key in self._data


if __name__ == "__main__":
    cache = FIFOCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1          # hit does not move 'a'
    assert cache.put("c", 3) == "a"      # 'a' is the oldest, evicted
    assert "a" not in cache and len(cache) == 2
    assert cache.put("b", 20) is None    # update in place, no eviction
    assert cache.get("b") == 20
    print("fifo cache ok")
```

`OrderedDict.popitem(last=False)` removes the oldest insertion in O(1). `get` deliberately does not call `move_to_end`, which is what separates FIFO from LRU. Updating an existing key keeps its original insertion position, matching FIFO semantics, and the capacity guard rejects a useless zero-size cache up front.

