```python
import os
import sys


def total_log_size(root: str) -> tuple:
    """Return (total_bytes, file_count) for *.log files under root.

    Symlinked directories are not descended into, which prevents cycles.
    """
    total = 0
    count = 0
    if not os.path.isdir(root):
        return (0, 0)

    for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
        # Skip symlinked subdirectories entirely.
        dirnames[:] = [
            d for d in dirnames
            if not os.path.islink(os.path.join(dirpath, d))
        ]
        for name in filenames:
            if name.endswith(".log"):
                path = os.path.join(dirpath, name)
                try:
                    total += os.path.getsize(path)
                except OSError:
                    # Broken symlink or permission error: skip silently.
                    continue
                count += 1
    return (total, count)


if __name__ == "__main__":
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    size, n = total_log_size(target)
    print(f"{n} log file(s), {size} bytes total")
```

`os.walk` with `followlinks=False` plus pruning symlinked directories means a loop like `a/link -> a` cannot send the walk into an infinite descent. Unreadable files are skipped rather than crashing, and a missing root returns zeros.

