#include <iostream>
#include <queue>
#include <vector>
#include <iomanip>

int main() {
    std::priority_queue<long long> low;                                   // max-heap
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> high; // min-heap

    long long value;
    while (std::cin >> value) {
        // Insert into the correct half.
        if (low.empty() || value <= low.top()) {
            low.push(value);
        } else {
            high.push(value);
        }

        // Rebalance so sizes differ by at most one.
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        double median;
        if (low.size() == high.size()) {
            median = (low.top() + high.top()) / 2.0;
        } else {
            median = static_cast<double>(low.top());
        }
        std::cout << std::fixed << std::setprecision(1) << median << "\n";
    }
    return 0;
}
```

Two heaps keep the lower half in `low` (max-heap) and the upper half in `high` (min-heap). After each insert the sizes are rebalanced, so the median is either `low.top()` or the mean of both tops. Empty input simply produces no output.

```cpp
#include <string>
#include <optional>
#include <iostream>
#include <cctype>

struct Semver {
    unsigned major = 0, minor = 0, patch = 0;
    std::string prerelease;
    std::string build;
};

static bool parse_number(const std::string& s, size_t& i, unsigned& out) {
    if (i >= s.size() || !std::isdigit(static_cast<unsigned char>(s[i]))) return false;
    unsigned value = 0;
    while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
        if (value > 429496729u) return false; // overflow guard
        value = value * 10u + static_cast<unsigned>(s[i] - '0');
        ++i;
    }
    out = value;
    return true;
}

std::optional<Semver> parse_semver(const std::string& s) {
    Semver v;
    size_t i = 0;
    if (!parse_number(s, i, v.major)) return std::nullopt;
    if (i >= s.size() || s[i++] != '.') return std::nullopt;
    if (!parse_number(s, i, v.minor)) return std::nullopt;
    if (i >= s.size() || s[i++] != '.') return std::nullopt;
    if (!parse_number(s, i, v.patch)) return std::nullopt;

    if (i < s.size() && s[i] == '-') {
        ++i;
        size_t start = i;
        while (i < s.size() && s[i] != '+') ++i;
        if (i == start) return std::nullopt; // empty prerelease
        v.prerelease = s.substr(start, i - start);
    }
    if (i < s.size() && s[i] == '+') {
        ++i;
        size_t start = i;
        while (i < s.size()) ++i;
        if (i == start) return std::nullopt; // empty build
        v.build = s.substr(start);
    }
    return (i == s.size()) ? std::optional<Semver>(v) : std::nullopt;
}

int main() {
    for (const char* in : {"1.2.3-alpha+build", "10.0.0", "1.2", "1.2.3-", "x.y.z"}) {
        auto r = parse_semver(in);
        if (r) std::cout << in << " -> " << r->major << '.' << r->minor << '.' << r->patch
                         << " pre='" << r->prerelease << "' build='" << r->build << "'\n";
        else std::cout << in << " -> invalid\n";
    }
}
```

The parser advances an index, requiring digits for each numeric field and treating `-prerelease` and `+build` as optional suffixes. Trailing garbage after the version is rejected because the final index must reach the end of the string. `parse_number` also guards against overflow by capping the intermediate value.

```rust
/// Return the longest common prefix of all strings in `words`.
///
/// An empty slice yields an empty string.
pub fn longest_common_prefix(words: &[String]) -> String {
    let first = match words.first() {
        Some(w) => w,
        None => return String::new(),
    };

    let mut end = first.chars().count();
    for word in &words[1..] {
        let shared = first
            .chars()
            .zip(word.chars())
            .take_while(|(a, b)| a == b)
            .count();
        if shared < end {
            end = shared;
        }
        if end == 0 {
            break;
        }
    }

    first.chars().take(end).collect()
}

