        assert_eq!(longest_common_prefix(&v(&["flower", "flow", "flight"])), "fl");
        assert_eq!(longest_common_prefix(&v(&["dog", "cat"])), "");
        assert_eq!(longest_common_prefix(&v(&["\u{e9}clair", "\u{e9}cole"])), "\u{e9}");
        assert_eq!(longest_common_prefix(&v(&["same"])), "same");
    }
}
