use std::io::{self, BufRead};

fn longest_run(nums: &[i64]) -> (usize, i64) {
    if nums.is_empty() {
        return (0, 0);
    }

    let mut best_len = 1usize;
    let mut best_sum = nums[0];
    let mut cur_len = 1usize;
    let mut cur_sum = nums[0];

    for pair in nums.windows(2) {
        if pair[1] > pair[0] {
            cur_len += 1;
            cur_sum += pair[1];
        } else {
            cur_len = 1;
            cur_sum = pair[1];
        }
        if cur_len > best_len {
            best_len = cur_len;
            best_sum = cur_sum;
        }
    }

    (best_len, best_sum)
}

