```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Reverse characters in buf[lo..hi] inclusive. */
static void reverse_range(char *buf, size_t lo, size_t hi) {
    while (lo < hi) {
        char tmp = buf[lo];
        buf[lo++] = buf[hi];
        buf[hi--] = tmp;
    }
}

/* Reverse the order of whitespace-separated words, collapsing runs of
 * whitespace to a single space. Returns the new length. */
static size_t reverse_words(char *buf) {
    size_t n = strlen(buf);

    /* First pass: collapse whitespace in place. */
    size_t w = 0;
    int in_space = 1; /* treat leading whitespace as a boundary */
    for (size_t i = 0; i < n; i++) {
        if (isspace((unsigned char)buf[i])) {
            if (!in_space) {
                buf[w++] = ' ';
                in_space = 1;
            }
        } else {
            buf[w++] = buf[i];
            in_space = 0;
        }
    }
    if (w > 0 && buf[w - 1] == ' ') w--; /* drop trailing space */
    buf[w] = '\0';

    /* Second pass: reverse the whole string, then each word. */
    reverse_range(buf, 0, w ? w - 1 : 0);
    size_t start = 0;
    for (size_t i = 0; i <= w; i++) {
        if (i == w || buf[i] == ' ') {
            if (i > start) reverse_range(buf, start, i - 1);
            start = i + 1;
        }
    }
    return w;
}

int main(void) {
    char line[4096];
    if (!fgets(line, sizeof line, stdin)) return 0;
    size_t len = strlen(line);
    if (len && line[len - 1] == '\n') line[--len] = '\0';

    reverse_words(line);
    puts(line);
    return 0;
}
```

The first pass squeezes runs of whitespace down to single spaces and strips the ends. Reversing the whole string and then reversing each word independently yields the reversed word order. An empty or all-whitespace line becomes an empty output line instead of crashing.

