    assert_eq!(top_three("a b a")[0], ("a".to_string(), 2));
    let r = top_three("Zebra apple banana apple zebra");
    assert_eq!(r[0], ("apple".to_string(), 2));
    assert_eq!(r[1], ("zebra".to_string(), 2));
