void reverse_words(std::string& s) {
    std::reverse(s.begin(), s.end());
    size_t i = 0;
    while (i < s.size()) {
        size_t j = s.find(' ', i);
        if (j == std::string::npos) j = s.size();
        std::reverse(s.begin() + i, s.begin() + j);
        i = j + 1;
