```rust
use std::collections::HashMap;

struct LruCache {
    cap: usize,
    map: HashMap<i32, i32>,
    order: Vec<i32>, // front = most recently used
}

impl LruCache {
    fn new(cap: usize) -> Self {
        assert!(cap >= 1, "capacity must be at least 1");
        LruCache { cap, map: HashMap::new(), order: Vec::new() }
    }

    fn touch(&mut self, key: i32) {
        if let Some(pos) = self.order.iter().position(|&k| k == key) {
            self.order.remove(pos);
        }
        self.order.insert(0, key);
    }

    fn get(&mut self, key: i32) -> Option<i32> {
        match self.map.get(&key).copied() {
            Some(v) => {
                self.touch(key);
                Some(v)
            }
            None => None,
        }
    }

    fn put(&mut self, key: i32, value: i32) {
        self.map.insert(key, value);
        self.touch(key);
        if self.order.len() > self.cap {
            if let Some(old) = self.order.pop() {
                self.map.remove(&old);
            }
        }
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 1);
    c.put(2, 2);
    assert_eq!(c.get(1), Some(1));
    c.put(3, 3);
    assert_eq!(c.get(2), None);
    assert_eq!(c.get(3), Some(3));
    println!("ok");
}
```

The recency `Vec` gives O(1) amortized inserts with O(n) removal, which is fine for the test; for strict O(1) under heavy load you'd want a doubly linked list with an arena. Capacity is guarded at construction and eviction pops the back (least recently used).

