def rle_encode(text):
    if not text:
        return ""
    out = []
    prev = text[0]
    count = 1
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(f"{count}{prev}")
            prev = ch
            count = 1
    out.append(f"{count}{prev}")
    return "".join(out)


def rle_decode(encoded):
    out = []
    i = 0
    while i < len(encoded):
        j = i
        while j < len(encoded) and encoded[j].isdigit():
            j += 1
        if j == i or j == len(encoded):
            raise ValueError("malformed encoded string")
        out.append(encoded[j] * int(encoded[i:j]))
        i = j + 1
    return "".join(out)


