int lower_bound_index(const std::vector<int>& v, int target) {
    int lo = 0, hi = static_cast<int>(v.size());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

int main() {
    std::vector<int> v{1, 3, 5, 7};
    assert(lower_bound_index(v, 3) == 1);
    assert(lower_bound_index(v, 4) == 2);
    assert(lower_bound_index(v, 9) == 4);
