#include <stdio.h>
#include <stddef.h>

/* Reverse an array of n integers in place.
 * n == 0 and a == NULL (with n == 0) are safe no-ops. */
void reverse_int_array(int *a, size_t n) {
    if (a == NULL || n < 2) {
        return;
    }
    for (size_t i = 0, j = n - 1; i < j; i++, j--) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }
}

static void print_array(const int *a, size_t n) {
    for (size_t i = 0; i < n; i++) {
        printf("%d%s", a[i], i + 1 < n ? " " : "\n");
    }
}

int main(void) {
    int empty[1] = {0};
    reverse_int_array(NULL, 0);
    reverse_int_array(empty, 0);

    int a[] = {1, 2, 3, 4, 5};
    reverse_int_array(a, 5);
    print_array(a, 5);   /* 5 4 3 2 1 */

    int b[] = {7};
    reverse_int_array(b, 1);
    print_array(b, 1);   /* 7 */

    int c[] = {10, 20};
    reverse_int_array(c, 2);
    print_array(c, 2);   /* 20 10 */

    return 0;
}
```

The two-pointer swap loop runs `n/2` swaps. Cases with `n < 2` return immediately, so a single-element or empty array can't be mis-indexed. `NULL` is tolerated only when `n == 0`, since a non-null pointer with `n == 0` never dereferences either.

