        std::size_t begin = 0, end = token.size();
        while (begin < end &&
               std::ispunct(static_cast<unsigned char>(token[begin]))) {
            ++begin;
        }
        while (end > begin &&
               std::ispunct(static_cast<unsigned char>(token[end - 1]))) {
            --end;
        }
        if (begin == end) {
            continue;  // Token was pure punctuation.
        }
        std::string word = token.substr(begin, end - begin);
        for (char &ch : word) {
            ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        }
        ++counts[word];
    }

    std::vector<std::pair<std::string, std::size_t>> items(counts.begin(),
                                                           counts.end());
    std::sort(items.begin(), items.end(),
              [](const auto &a, const auto &b) {
                  if (a.second != b.second) {
                      return a.second > b.second;
                  }
                  return a.first < b.first;
              });

    constexpr std::size_t kTop = 10;
    std::size_t limit = std::min(kTop, items.size());
    for (std::size_t i = 0; i < limit; ++i) {
        std::cout << items[i].second << ' ' << items[i].first << '\n';
    }
    return 0;
}
