use std::collections::HashMap;

/// Return true if all brackets in `s` are balanced and correctly nested.
/// Non-bracket characters are ignored. Empty input is balanced.
pub fn is_balanced(s: &str) -> bool {
    let pairs: HashMap<char, char> =
        HashMap::from([(')', '('), (']', '['), ('}', '{')]);

    let mut stack: Vec<char> = Vec::new();
    for ch in s.chars() {
        match ch {
            '(' | '[' | '{' => stack.push(ch),
            ')' | ']' | '}' => {
                // The matching open bracket must be exactly on top.
                match stack.pop() {
                    Some(open) if open == pairs[&ch] => {}
                    _ => return false,
                }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

fn main() {
    assert!(is_balanced(""));
    assert!(is_balanced("a(b[c]{d})e"));
    assert!(!is_balanced("(]"));
    assert!(!is_balanced("(("));
    assert!(!is_balanced(")"));
    assert!(!is_balanced("[(])"));
    assert!(is_balanced("😀[😀]{😀}"));
    println!("ok");
}
```

Every closing bracket must match the most recent unmatched opener, which is why `"([)]"` fails even though each pair exists. `stack.pop()` returning `None` on an unmatched close also returns `false`. Trailing opens are caught because the stack must be empty at the end. Non-bracket characters, including unicode, are skipped.

