#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& a, int target) {
    int lo = 0;
    int hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> a = {1, 3, 5, 7, 9, 11};
    std::cout << binary_search(a, 7) << "\n";
    std::cout << binary_search(a, 4) << "\n";
    std::cout << binary_search({}, 1) << "\n";
    return 0;
}
