```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 4096

struct entry {
    char *word;
    int count;
    struct entry *next;
};

static struct entry *table[TABLE_SIZE];

static unsigned hash(const char *s) {
    unsigned h = 5381u;
    while (*s) h = h * 33u + (unsigned char)*s++;
    return h % TABLE_SIZE;
}

static void insert(const char *word) {
    unsigned idx = hash(word);
    for (struct entry *e = table[idx]; e; e = e->next) {
        if (strcmp(e->word, word) == 0) { e->count++; return; }
    }
    struct entry *e = malloc(sizeof *e);
    if (!e) { perror("malloc"); exit(1); }
    e->word = strdup(word);
    if (!e->word) { perror("strdup"); exit(1); }
    e->count = 1;
    e->next = table[idx];
    table[idx] = e;
}

int main(void) {
    char buf[256];
    while (scanf("%255s", buf) == 1) {
        for (char *p = buf; *p; ++p) *p = (char)tolower((unsigned char)*p);
        insert(buf);
    }

    for (int rank = 0; rank < 3; ++rank) {
        struct entry *best = NULL;
        for (int i = 0; i < TABLE_SIZE; ++i)
            for (struct entry *e = table[i]; e; e = e->next)
                if ((!best || e->count > best->count) && e->count > 0)
                    best = e;
        if (!best) break;
        printf("%d. %s (%d)\n", rank + 1, best->word, best->count);
        best->count = 0;
    }
    return 0;
}
```
`%255s` bounds the read so a long token can't overflow `buf`, and words are lowercased before insertion. The top-3 pass zeroes each winner so it isn't picked again. The table is deliberately never freed — the program exits immediately after printing.

