fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 4, 6];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 4, 5, 6, 7]);
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[5], &[]), vec![5]);
    assert_eq!(merge_sorted(&[], &[1, 1, 2]), vec![1, 1, 2]);
    println!("{:?}", merge_sorted(&a, &b));
}
```
The two-pointer loop only advances one index per iteration, then both remainders are appended; at least one of them is empty so nothing is duplicated. `<=` on the left side keeps the merge stable when equal elements appear in both halves.

```python
from collections import OrderedDict


class LRUCache:
    """Bounded LRU cache. get and put are O(1)."""

    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1
    c.put("c", 3)
    assert c.get("b") is None
    assert c.get("a") == 1
    assert c.get("c") == 3
    assert len(c) == 2
    try:
        LRUCache(0)
    except ValueError:
        pass
    print("ok")
```
`OrderedDict` keeps insertion order and `move_to_end` promotes on access, so the front of the dict is always the least-recently-used entry removed by `popitem(last=False)`. `None` doubles as the miss marker, which is fine as long as callers never store `None`.

```cpp
#include <cstddef>
#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : capacity_(capacity), buf_(capacity), head_(0), size_(0) {}

    bool is_full() const { return size_ == capacity_; }
    bool is_empty() const { return size_ == 0; }

    // Returns false and drops the oldest value when full.
    bool push(double value) {
        bool overwrote = is_full();
        buf_[(head_ + size_) % capacity_] = value;
        if (overwrote) {
            head_ = (head_ + 1) % capacity_;
        } else {
            ++size_;
        }
        return !overwrote;
    }

    std::optional<double> pop() {
        if (is_empty()) return std::nullopt;
        double value = buf_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::size_t capacity_;
    std::size_t head_;
    std::size_t size_;
    std::vector<double> buf_;
};

int main() {
    RingBuffer rb(3);
    for (double v : {1.0, 2.0, 3.0}) rb.push(v);
    std::cout << rb.is_full() << '\n';          // 1
    rb.push(4.0);                               // drops 1.0
    std::cout << *rb.pop() << '\n';             // 2
    while (rb.pop()) {}
    std::cout << rb.is_empty() << '\n';         // 1
}
```
`head_` and `size_` describe the live window; the write index is `(head_ + size_) % capacity_`. Push returns `false` when it had to evict, so callers can detect overflow without checking first. Note it needs `#include <vector>`.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start = end = 0

    def expand(lo: int, hi: int) -> tuple:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end + 1]


if __name__ == "__main__":
    for text in ("babad", "cbbd", ""):
        print(repr(text), "->", repr(longest_palindrome(text)))
