#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
    std::array<double, N> buf_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;

public:
    bool push(double v) {
        if (size_ == N) return false;          // full: refuse, drop nothing
        buf_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) return std::nullopt;
        double v = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
};

int main() {
    RingBuffer<3> rb;
    for (double v : {1.5, 2.5, 3.5, 4.5}) {
        std::cout << "push " << v << " -> " << rb.push(v) << '\n';
    }
    while (auto v = rb.pop()) {
        std::cout << "pop " << *v << '\n';
    }
    std::cout << "empty: " << rb.empty() << '\n';
}
```

The fourth push is rejected because the buffer holds three items; `pop` returns `std::nullopt` once drained.

