        self.window = window
        self._samples: deque = deque()
        self._sum = 0.0

    def add(self, value: float) -> float:
        self._samples.append(value)
        self._sum += value
        if len(self._samples) > self.window:
            self._sum -= self._samples.popleft()
        return self.average

    @property
    def average(self) -> float:
        if not self._samples:
            return 0.0
        return self._sum / len(self._samples)

    def __len__(self) -> int:
        return len(self._samples)


if __name__ == "__main__":
    ra = RollingAverage(3)
    for v in (2.0, 4.0, 6.0):
        print(v, "->", ra.add(v))
    print("after 100:", ra.add(100.0), "window size", len(ra))
```

Old samples are evicted from the deque and subtracted from the running sum, so memory stays bounded and each `add` is constant time.

