#include <stdbool.h>
#include <stdio.h>
#include <limits.h>

bool parse_int(const char *text, int *out) {
    if (text == NULL || *text == '\0') {
        return false;
    }

    const char *p = text;
    bool negative = false;
    if (*p == '+' || *p == '-') {
        negative = (*p == '-');
        p++;
    }
    if (*p == '\0') {
        return false; /* sign with no digits */
    }

    long long acc = 0;
    for (; *p != '\0'; p++) {
        if (*p < '0' || *p > '9') {
            return false;
        }
        acc = acc * 10 + (*p - '0');
        if (acc > (long long)INT_MAX + 1) {
            return false; /* overflow guard */
        }
    }

    long long signed_value = negative ? -acc : acc;
    if (signed_value < INT_MIN || signed_value > INT_MAX) {
        return false;
    }
    *out = (int)signed_value;
    return true;
}

int main(void) {
    const char *tests[] = {"42", "-17", "+8", "007", "", "-", "12x", "2147483648"};
    int value;
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); i++) {
        bool ok = parse_int(tests[i], &value);
        if (ok) {
            printf("ok:   %-12s -> %d\n", tests[i], value);
        } else {
            printf("fail: %-12s\n", tests[i]);
        }
    }
    return 0;
}
```

Accumulating in `long long` lets the overflow check compare against `INT_MAX + 1` before narrowing, so `INT_MIN` itself parses correctly while its magnitude on a sign is handled explicitly.

