use std::collections::HashMap;

fn fib(n: u64) -> u128 {
    fn helper(n: u64, memo: &mut HashMap<u64, u128>) -> u128 {
        if let Some(&cached) = memo.get(&n) {
            return cached;
        }
        let value = helper(n - 1, memo) + helper(n - 2, memo);
        memo.insert(n, value);
        value
    }

    match n {
        0 => 0,
        1 => 1,
        _ => {
            let mut memo = HashMap::new();
            memo.insert(0, 0);
            memo.insert(1, 1);
            helper(n, &mut memo)
        }
    }
}

fn main() {
    assert_eq!(fib(0), 0);
    assert_eq!(fib(1), 1);
    assert_eq!(fib(10), 55);
    assert_eq!(fib(50), 12_586_269_025);
    assert_eq!(fib(100), 354_224_848_179_261_915_075);
    println!("fib(100) = {}", fib(100));
}
```

Memoization turns the naive exponential recursion into O(n) time and space. `u128` holds the result up to roughly `n = 186`; beyond that you would need a bignum crate, since `u128` would overflow.

