#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

class CircularBuffer {
public:
    explicit CircularBuffer(std::size_t capacity) : data_(capacity), head_(0), size_(0) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be positive");
        }
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == data_.size(); }
    std::size_t size() const { return size_; }

    // Overwrites the oldest element when full; returns whether it overwrote.
    bool push(int value) {
        bool overwrote = full();
        std::size_t tail = (head_ + size_) % data_.size();
        data_[tail] = value;
        if (overwrote) {
            head_ = (head_ + 1) % data_.size();
        } else {
            ++size_;
        }
        return overwrote;
    }

    std::optional<int> pop() {
        if (empty()) {
            return std::nullopt;
        }
        int value = data_[head_];
        head_ = (head_ + 1) % data_.size();
        --size_;
        return value;
    }

private:
    std::vector<int> data_;
    std::size_t head_;
    std::size_t size_;
};
```

