fn longest_common_prefix(strs: &[&str]) -> String {
    let first = match strs.first() {
        Some(s) => *s,
        None => return String::new(),
    };

    let mut len = first.len();
    for word in strs.iter().skip(1) {
        len = len.min(word.len());
        let mut i = 0;
        let first_bytes = first.as_bytes();
        let word_bytes = word.as_bytes();
        while i < len && first_bytes[i] == word_bytes[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            return String::new();
        }
    }

    // `len` falls on a char boundary because it is a shared prefix length in bytes
    first[..len].to_string()
}

fn main() {
    println!("{}", longest_common_prefix(&["flower", "flow", "flight"])); // fl
    println!("{}", longest_common_prefix(&["dog", "racecar", "car"]));   // ""
    println!("{}", longest_common_prefix(&[]));                            // ""
    println!("{}", longest_common_prefix(&["unis"]));                     // unis
}
