```rust
use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<&str, usize> = HashMap::new();
    for word in text.split_whitespace() {
        *counts.entry(word).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts
        .into_iter()
        .map(|(w, c)| (w.to_string(), c))
        .collect();

    // Sort by descending count, then ascending word for a stable tie-break.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ranks_and_ties() {
        let words = top_words("the cat the dog the cat bird", 2);
        assert_eq!(words, vec![("the".to_string(), 3), ("cat".to_string(), 2)]);
    }

    #[test]
    fn empty_input() {
        assert!(top_words("", 5).is_empty());
    }

    #[test]
    fn n_larger_than_vocab() {
        assert_eq!(top_words("a a b", 10), vec![("a".to_string(), 2), ("b".to_string(), 1)]);
    }
}
```
`split_whitespace` avoids allocating intermediate tokens, and the explicit tie-break on the word makes the ordering deterministic instead of relying on hash order. `truncate` clamps `n` to the available vocabulary.

