#include <iostream>
#include <stack>
#include <string>

bool balanced(const std::string& s) {
    std::stack<char> st;
    bool quoted = false;
    for (char c : s) {
        if (c == '"') { quoted = !quoted; continue; }
        if (quoted) continue;
        if (c == '(' || c == '[' || c == '{') st.push(c);
        else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top(); st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) return false;
        }
    }
    return st.empty() && !quoted;
}

int main() {
    if (!balanced("{[()]}")) return 1;
    if (balanced("([)]")) return 1;
    if (!balanced("a \"(\" b")) return 1;
    if (balanced("unbalanced(")) return 1;
    std::cout << "all tests passed\n";
}
```
