```c
#include <stdio.h>

int trailing_zeros_factorial(int n) {
    int zeros = 0;
    for (long long power = 5; power <= n; power *= 5) {
        zeros += n / power;
    }
    return zeros;
}

int main(void) {
    int inputs[] = {0, 1, 5, 10, 25, 100};
    int expected[] = {0, 0, 1, 2, 6, 24};
    int count = sizeof(inputs) / sizeof(inputs[0]);
    for (int i = 0; i < count; ++i) {
        int got = trailing_zeros_factorial(inputs[i]);
        if (got != expected[i]) {
            printf("FAIL n=%d got=%d expected=%d\n", inputs[i], got, expected[i]);
            return 1;
        }
    }
    printf("all checks passed\n");
    return 0;
}
```

Rather than computing the factorial, we count factors of five, since twos are more plentiful. Summing `n/5 + n/25 + n/125 + ...` accounts for numbers contributing more than one five, which is why 25 yields 6 and 100 yields 24. Using `long long` for the power avoids overflow before the comparison.

