#include <vector>
#include <algorithm>
#include <stdexcept>

double median_of_two(const std::vector<double>& a, const std::vector<double>& b) {
    if (a.size() > b.size()) return median_of_two(b, a);
    const size_t m = a.size(), n = b.size();
    size_t lo = 0, hi = m;
    while (lo <= hi) {
        size_t i = (lo + hi) / 2;
        size_t j = (m + n + 1) / 2 - i;
        double aL = (i == 0) ? -1e300 : a[i - 1];
        double aR = (i == m) ?  1e300 : a[i];
        double bL = (j == 0) ? -1e300 : b[j - 1];
        double bR = (j == n) ?  1e300 : b[j];
        if (aL <= bR && bL <= aR) {
            if ((m + n) % 2 == 1) return std::max(aL, bL);
            return (std::max(aL, bL) + std::min(aR, bR)) / 2.0;
        }
        if (aL > bR) hi = i - 1; else lo = i + 1;
    }
    throw std::runtime_error("inputs must be sorted");
}

int main() {
    std::vector<double> a{1, 3}, b{2};
    if (median_of_two(a, b) != 2.0) return 1;
    std::vector<double> c{1, 2}, d{3, 4};
    if (median_of_two(c, d) != 2.5) return 1;
    std::vector<double> e, f{5};
    if (median_of_two(e, f) != 5.0) return 1;
    return 0;
}
