```cpp
#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

// Reuses existing nodes; returns the head of the merged list.
Node* mergeSorted(Node* a, Node* b) {
    Node dummy(0);
    Node* tail = &dummy;
    while (a != nullptr && b != nullptr) {
        if (a->value <= b->value) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = (a != nullptr) ? a : b;  // the remaining tail is already sorted
    return dummy.next;
}

void printList(const Node* head) {
    for (const Node* p = head; p != nullptr; p = p->next)
        std::cout << p->value << ' ';
    std::cout << '\n';
}

int main() {
    Node* a = new Node(1); a->next = new Node(4); a->next->next = new Node(9);
    Node* b = new Node(2); b->next = new Node(3); b->next->next = new Node(7);

    Node* merged = mergeSorted(a, b);
    printList(merged);          // 1 2 3 4 7 9

    Node* only = mergeSorted(nullptr, b);
    printList(only);            // 2 3 7

    // NOTE: nodes are owned by `a`, `b`, `only`; free them in real code.
    return 0;
}
```
`dummy` is a stack sentinel whose `next` becomes the real head, so the loop never has to special-case the first node. Each iteration appends the smaller current node and advances only that list; when one list runs out, its remainder is spliced in wholesale because it is already sorted. The result is O(n+m) time and O(1) extra space besides the sentinel.

```rust
use std::collections::HashMap;

fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {
    match n {
        0 => 0,
        1 => 1,
        _ => {
            if let Some(&cached) = memo.get(&n) {
                return cached;
            }
            let value = fib(n - 1, memo) + fib(n - 2, memo);
            memo.insert(n, value);
            value
        }
    }
}

fn main() {
    let mut memo = HashMap::new();
    for n in 0..=10 {
        println!("fib({n}) = {}", fib(n, &mut memo));
    }
    assert_eq!(fib(0, &mut memo), 0);
    assert_eq!(fib(1, &mut memo), 1);
    assert_eq!(fib(90, &mut memo), 2880067194370816120);
}
```
Without memoization this is exponential; the map turns it into O(n) time and O(n) space because each distinct `n` is computed once. Passing `memo` as `&mut` keeps a single cache across calls. `u64` overflows after fib(93), so if you need larger values switch to a big-integer crate such as `num-bigint` rather than silently wrapping.

