#include <stdio.h>
#include <string.h>

static void reverse_range(char *s, size_t lo, size_t hi) {
    while (lo < hi) {
        char tmp = s[lo];
        s[lo++] = s[hi];
        s[hi--] = tmp;
    }
}

void reverse_words(char *s) {
    size_t n = strlen(s);
    if (n == 0) return;

    reverse_range(s, 0, n - 1);            /* whole string */

    size_t i = 0;
    while (i < n) {
        size_t start = i;
        while (i < n && s[i] != ' ') i++;
        if (i > start)
            reverse_range(s, start, i - 1);  /* each word back */
        else
            i++;                             /* skip a space run */
    }
}

int main(void) {
    char a[] = "the quick  brown fox";
    reverse_words(a);
    printf("[%s]\n", a);          /* [fox brown  quick the] */

    char b[] = "";
    reverse_words(b);
    printf("[%s]\n", b);          /* [] */

    char c[] = "   ";
    reverse_words(c);
    printf("[%s]\n", c);          /* [   ] */
    return 0;
}
```
The trick is two reversals: flipping the whole string puts the words in the right order but spells each one backward, so a second pass reverses each maximal run of non-space characters. Empty strings and all-space strings are no-ops because `strlen` is 0 or no word run is ever found. The function never allocates and works in O(n) time, and the caller owns the buffer — it must be mutable, so never pass a string literal.

```python
class BoundedStack:
    """A LIFO stack that refuses to grow past `capacity`."""

    class Overflow(Exception):
        pass

    class Underflow(Exception):
        pass

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._items = []
        self.capacity = capacity

    def push(self, item) -> None:
        if len(self._items) >= self.capacity:
            raise BoundedStack.Overflow(f"stack full ({self.capacity})")
        self._items.append(item)

    def pop(self):
        if not self._items:
            raise BoundedStack.Underflow("stack is empty")
        return self._items.pop()

    def peek(self):
        if not self._items:
            raise BoundedStack.Underflow("stack is empty")
        return self._items[-1]

    def __len__(self) -> int:
        return len(self._items)

    def __bool__(self) -> bool:
        return bool(self._items)


if __name__ == "__main__":
    s = BoundedStack(2)
    s.push("a")
    s.push("b")
    assert s.peek() == "b"
    try:
        s.push("c")
    except BoundedStack.Overflow as e:
        print("overflow as expected:", e)
    assert s.pop() == "b"
    assert len(s) == 1
    s.pop()
    try:
        s.pop()
    except BoundedStack.Underflow as e:
        print("underflow as expected:", e)
    print("done")
```
Using nested exception classes keeps `BoundedStack.Overflow` and `BoundedStack.Underflow` namespaced so they don't clash with builtins. `__bool__` makes `if stack:` mean "non-empty", which is handy in loops. The `capacity <= 0` guard rejects a nonsensical bound at construction time rather than failing later on the first push.

