namespace xt {

template <typename T>
T dotProduct(const std::vector<T>& a, const std::vector<T>& b) {
    if (a.size() != b.size())
        throw std::invalid_argument("dot product requires equal sizes");
    T sum = T{};
    for (std::size_t i = 0; i < a.size(); ++i)
        sum += a[i] * b[i];
    return sum;
}

}  // namespace xt

int main() {
    std::vector<double> x{1.5, 2.0, -3.0};
    std::vector<double> y{4.0, 0.5, 2.0};
    std::cout << xt::dotProduct(x, y) << '\n';   // 1.0

    std::vector<int> a{1, 2, 3};
    std::vector<int> b{4, 5, 6};
    std::cout << xt::dotProduct(a, b) << '\n';   // 32

    try {
        std::vector<int> shortVec{1, 2};
        (void)xt::dotProduct(a, shortVec);
    } catch (const std::invalid_argument& e) {
        std::cerr << "caught: " << e.what() << '\n';
    }
    return 0;
}
```
`T{}` gives the additive identity without hardcoding `0`, so the function also works for types like `std::complex` or a custom fixed-point class. Size checking at the top means a mismatch is caught before any element is touched, which avoids silent out-of-bounds reads on `b`. The function is header-inline by virtue of being a template, so no separate source file is needed.

