```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_ENTRIES 32
#define MAX_KEY 64
#define MAX_VAL 256

struct Entry {
    char key[MAX_KEY];
    char value[MAX_VAL];
};

static char *trim(char *s) {
    while (*s && isspace((unsigned char)*s)) s++;
    char *end = s + strlen(s);
    while (end > s && isspace((unsigned char)end[-1])) end--;
    *end = '\0';
    return s;
}

int parse_config(const char *path, struct Entry *out, int max, int *count) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    char line[512];
    int n = 0;
    while (fgets(line, sizeof line, fp)) {
        char *text = trim(line);
        if (*text == '\0' || *text == '#' || *text == ';')
            continue;                /* blank or comment */

        char *eq = strchr(text, '=');
        if (!eq) {
            fprintf(stderr, "skipping malformed line: %s\n", text);
            continue;
        }
        *eq = '\0';
        char *key = trim(text);
        char *val = trim(eq + 1);

        if (key[0] == '\0') {
            fprintf(stderr, "skipping empty key\n");
            continue;
        }
        if (n >= max) {
            fprintf(stderr, "too many entries, stopping at %d\n", max);
            break;
        }

        snprintf(out[n].key, MAX_KEY, "%s", key);
        snprintf(out[n].value, MAX_VAL, "%s", val);
        n++;
    }

    fclose(fp);
    *count = n;
    return 0;
}

int main(void) {
    /* Example file (config.ini):
         # server settings
         host=127.0.0.1
         port = 8080

         name = "my app"   ; inline comment stays in the value
    */
    struct Entry entries[MAX_ENTRIES];
    int count = 0;
    if (parse_config("config.ini", entries, MAX_ENTRIES, &count) != 0)
        return 1;

    for (int i = 0; i < count; i++)
        printf("[%s] -> [%s]\n", entries[i].key, entries[i].value);
    return 0;
}
```
`snprintf` truncates rather than overflows, so an oversized key or value can never smash the struct. Trimming is done in place on the same buffer, and the `=` is replaced by a NUL to split the two halves. Blank lines and lines starting with `#` or `;` are dropped. Anything without `=` is reported and skipped instead of silently ignored. Note that with this simple parser an inline `;` comment is kept as part of the value — strip it separately if you need that behaviour.

