#include <iostream>
#include <vector>

template <typename T>
long long binary_search_index(const std::vector<T>& data, const T& target) {
    long long lo = 0;
    long long hi = static_cast<long long>(data.size()) - 1;
    while (lo <= hi) {
        long long mid = lo + (hi - lo) / 2;
        if (data[mid] == target) return mid;
        if (data[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> v = {1, 3, 5, 7, 9, 11};
    std::cout << binary_search_index(v, 7) << '\n';   // 3
    std::cout << binary_search_index(v, 4) << '\n';   // -1
    std::cout << binary_search_index(v, 11) << '\n';  // 5
    std::vector<int> empty;
    std::cout << binary_search_index(empty, 1) << '\n'; // -1 (size()-1 wraps, so guard below)
    return 0;
}
```

Note: for an empty vector `static_cast<long long>(0) - 1 == -1`, so `lo <= hi` is `0 <= -1` — false, loop never runs, returns -1 correctly.

