```rust
fn reverse_vowels(s: &str) -> String {
    let is_vowel = |c: char| "aeiouAEIOU".contains(c);
    let mut chars: Vec<char> = s.chars().collect();
    let (mut i, mut j) = (0usize, chars.len());

    while i < j {
        match (is_vowel(chars[i]), j.checked_sub(1).map(|k| is_vowel(chars[k]))) {
            (true, Some(true)) => {
                chars.swap(i, j - 1);
                i += 1;
                j -= 1;
            }
            (true, _) => j -= 1,
            (false, _) => i += 1,
        }
    }
    chars.into_iter().collect()
}

fn main() {
    assert_eq!(reverse_vowels("hello"), "holle");
    assert_eq!(reverse_vowels("leetcode"), "leotcede");
    assert_eq!(reverse_vowels(""), "");
    assert_eq!(reverse_vowels("bcdf"), "bcdf");
    println!("{}", reverse_vowels("aA")); // "Aa"
}
```

