```cpp
#include <algorithm>
#include <iostream>
#include <vector>

std::vector<int> merge_sorted(const std::vector<int>& a,
                              const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        // Use <= so equal values keep a stable, left-to-right order.
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    const std::vector<int> a{1, 3, 3, 7};
    const std::vector<int> b{2, 3, 4, 9};
    const auto merged = merge_sorted(a, b);
    for (int v : merged) std::cout << v << ' ';
    std::cout << '\n';

    // Edge cases: one empty, both empty, single elements.
    std::cout << merge_sorted({}, {}).size() << '\n';        // 0
    std::cout << merge_sorted({5}, {}).size() << '\n';       // 1
    std::cout << merge_sorted({}, {1, 2}).size() << '\n';    // 2
    return 0;
}
```
The merge runs in O(n + m) time and handles duplicates and empty inputs without branching outside the main loop.

