#include <iostream>
#include <stack>
#include <string>

bool is_balanced(const std::string& s) {
    std::stack<char> open;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                open.push(c);
                break;
            case ')':
                if (open.empty() || open.top() != '(') return false;
                open.pop();
                break;
            case ']':
                if (open.empty() || open.top() != '[') return false;
                open.pop();
                break;
            case '}':
                if (open.empty() || open.top() != '{') return false;
                open.pop();
                break;
            default:
                break;
        }
    }
    return open.empty();
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_balanced("([{}])") << '\n';  // true
    std::cout << is_balanced("([)]")   << '\n';  // false (wrong nesting)
    std::cout << is_balanced("")       << '\n';  // true
    std::cout << is_balanced("(]")     << '\n';  // false
    std::cout << is_balanced("(()")    << '\n';  // false
    return 0;
}
```
The stack pairs each closing symbol with the most recent unmatched opener, so both count and nesting order are checked in one pass.

