/// Returns the nth Fibonacci number with F(0) = 0, F(1) = 1.
/// Uses u128 so results stay exact far beyond u64 range.
fn fib(n: u32) -> u128 {
    let (mut a, mut b) = (0u128, 1u128);
    for _ in 0..n {
        let next = a.wrapping_add(b);
        a = b;
        b = next;
    }
    a
}

fn main() {
    assert_eq!(fib(0), 0);
    assert_eq!(fib(1), 1);
    assert_eq!(fib(10), 55);
    assert_eq!(fib(20), 6765);

    // Still exact at n = 100, which overflows u64.
    let f100 = fib(100);
    assert_eq!(f100, 354224848179261915075u128);

    for n in 0..=30 {
        println!("fib({n}) = {}", fib(n));
    }
}
```
