#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) {
        return;
    }
    size_t len = strlen(s);
    if (len < 2) {
        return; /* empty or single character: nothing to do */
    }
    size_t i = 0;
    size_t j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    printf("%s\n", a);       /* olleh */

    char b[] = "";
    reverse_in_place(b);
    printf("[%s]\n", b);     /* [] */

    char c[] = "a";
    reverse_in_place(c);
    printf("%s\n", c);       /* a */

    char d[] = "ab";
    reverse_in_place(d);
    printf("%s\n", d);       /* ba */

    return 0;
}
