```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

// A fixed-capacity blocking queue. push() blocks while full,
// try_pop() returns std::nullopt immediately when empty.
template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    bool push(T value) {
        std::unique_lock<std::mutex> lock(mtx_);
        not_full_.wait(lock, [this] { return closed_ || q_.size() < cap_; });
        if (closed_) return false;
        q_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }

    std::optional<T> try_pop() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (q_.empty()) return std::nullopt;
        T value = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mtx_);
            closed_ = true;
        }
        not_full_.notify_all();
        not_empty_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<T> q_;
    std::mutex mtx_;
    std::condition_variable not_full_;
    bool closed_ = false;
    std::condition_variable not_empty_;  // reserved for future blocking pop
};

// Compile: g++ -std=c++17 -Wall -Wextra -pthread queue.cpp
```
`push` waits on `not_full_` until there is room, using the predicate form so spurious wakeups are handled. `try_pop` is non-blocking and returns `std::nullopt` on an empty queue. `close()` wakes both waiters so blocked producers can exit; a zero-capacity queue would deadlock, so callers should pass capacity >= 1.

```rust
use std::collections::HashMap;

/// Parse `key=value` lines. Blank lines and lines starting with '#'
/// (after optional whitespace) are ignored. Returns the map plus a
/// sorted list of keys that appeared more than once.
pub fn parse_config(text: &str) -> (HashMap<String, String>, Vec<String>) {
    let mut map = HashMap::new();
    let mut dupes = Vec::new();

    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            continue; // malformed line, skip
        };
        let key = key.trim().to_string();
        let value = value.trim().to_string();
        if key.is_empty() {
            continue;
        }
        if map.insert(key.clone(), value).is_some() && !dupes.contains(&key) {
            dupes.push(key);
        }
    }

    dupes.sort();
    (map, dupes)
}

fn main() {
    let src = "\n# a comment\nname = luna\nport=8080\nname = xt\nhost=east\n";
    let (cfg, dupes) = parse_config(src);
    assert_eq!(cfg.get("name").map(String::as_str), Some("xt"));
    assert_eq!(cfg.get("port").map(String::as_str), Some("8080"));
    assert_eq!(dupes, vec!["name".to_string()]);
    println!("{:?} dupes={:?}", cfg, dupes);
}
```
Keys and values are trimmed, so `name = luna` and `name=luna` behave the same. `split_once('=')` keeps any `=` inside the value. A later assignment overwrites the earlier one, and the key is recorded as a duplicate only on the second occurrence. Lines without `=` and lines with an empty key are skipped rather than causing a panic.

