// RAII timer: records construction time and prints the elapsed
// duration when it goes out of scope. Non-copyable to avoid double prints.
class ScopedTimer {
public:
    explicit ScopedTimer(std::string label)
        : label_(std::move(label)), start_(std::chrono::steady_clock::now()) {}

    ScopedTimer(const ScopedTimer&) = delete;
    ScopedTimer& operator=(const ScopedTimer&) = delete;

    ~ScopedTimer() {
        auto end = std::chrono::steady_clock::now();
        auto us = std::chrono::duration_cast<std::chrono::microseconds>(end - start_).count();
        std::printf("%s: %.3f ms\n", label_.c_str(), us / 1000.0);
    }

private:
    std::string label_;
    std::chrono::steady_clock::time_point start_;
};

int main() {
    {
        ScopedTimer t("sleep 50ms");
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    {
        ScopedTimer t("repeated work");
        volatile long long acc = 0;
        for (long long i = 0; i < 5'000'000; ++i) acc += i;
        (void)acc;
    }
    return 0;
}

// Compile: g++ -std=c++17 -O2 -Wall -pthread timer.cpp
```
`steady_clock` is monotonic, so the measurement is unaffected by wall-clock adjustments. The destructor prints at scope exit, which is the point of RAII — no explicit stop call to forget. Copy and assignment are deleted so a copied timer cannot print twice. Printing as milliseconds with three decimals keeps short and long scopes readable.

```rust
/// Run-length encode: each run becomes (count, byte). Counts are u32.
fn encode(data: &[u8]) -> Vec<(u32, u8)> {
    let mut out = Vec::new();
    for &b in data {
        match out.last_mut() {
            Some((count, last)) if *last == b => *count += 1,
            _ => out.push((1, b)),
        }
    }
    out
}

/// Decode back to the original bytes. Counts of zero are skipped.
fn decode(runs: &[(u32, u8)]) -> Vec<u8> {
    let mut out = Vec::new();
    for &(count, b) in runs {
        for _ in 0..count {
            out.push(b);
        }
    }
    out
}

fn main() {
    let samples: [&[u8]; 4] = [
        b"",
        b"a",
        b"aaabbbcccd",
        b"\xff\xff\x00\xff",
    ];
    for s in samples {
        let runs = encode(s);
        let back = decode(&runs);
        assert_eq!(back, s, "round trip failed for {:?}", s);
        println!("{:?} -> {:?}", s, runs);
    }

    // Explicit expected encodings.
    assert_eq!(encode(b"aaabbc"), vec![(3, b'a'), (2, b'b'), (1, b'c')]);
    assert_eq!(decode(&[]), Vec::<u8>::new());
    println!("all round trips ok");
}
```
`encode` compares each byte to the last run's byte and either bumps its count or starts a new run, which is a single pass. `decode` just expands each count. The empty input produces an empty run list and decoding it yields empty output, so the round trip holds at the boundary. Bytes are treated as raw `u8`, so values above `0x7f` such as `\xff` are preserved exactly.

