```cpp
#include <cstdio>
#include <deque>
#include <numeric>
#include <vector>

// Fixed-window rolling average. Warm-up phase averages fewer than
// window_ samples; after that the window slides one sample at a time.
class RollingAverage {
public:
    explicit RollingAverage(std::size_t window) : window_(window) {
        if (window == 0) window_ = 1;
    }

    double add(int sample) {
        window_.buf.push_back(sample);
        sum_ += sample;
        if (window_.buf.size() > window_.size) {
            sum_ -= window_.buf.front();
            window_.buf.pop_front();
        }
        return static_cast<double>(sum_) / static_cast<double>(window_.buf.size());
    }

private:
    struct { std::size_t size; std::deque<int> buf; } window_;
    long long sum_ = 0;
};

int main() {
    RollingAverage avg(3);
    std::vector<int> stream = {10, 20, 30, 40, 50, 0, -10};
    for (int v : stream) {
        std::printf("after %4d -> %.3f\n", v, avg.add(v));
    }
    return 0;
}

// Compile: g++ -std=c++17 -Wall -Wextra rolling.cpp
```
During warm-up the divisor is the number of samples seen so far, so the first value averages to itself. Once the deque exceeds the window size, the oldest sample is subtracted and removed before dividing, keeping the sum and the buffer in sync — that is why `sum_` is tracked separately instead of re-summing each step. A window of zero is clamped to one to avoid division by zero.

