def balanced(code: str) -> bool:
    """Check (), [], {} balance, skipping '...' strings and # comments."""
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    in_string = False
    escaped = False
    for ch in code:
        if in_string:
            if escaped:
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == "'":
                in_string = False
            continue
        if ch == '#':
            break
        if ch == "'":
            in_string = True
        elif ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack and not in_string


if __name__ == "__main__":
    assert balanced("")
    assert balanced("a = (1 + [2, 3])")
    assert balanced("x = ')'  # )")
    assert not balanced("(a")
    assert not balanced("a)")
    assert not balanced("x = 'unterminated")
    print("ok")
```

Escaping is handled so `'\\''` does not close the string early. An unterminated string is treated as unbalanced, and mismatched closers fail immediately.

