```c
#include <stdio.h>
#include <string.h>

/* Reverse UTF-8 characters in place. Degenerate bytes are kept as single units. */
static size_t seq_len(unsigned char c) {
    if (c < 0x80) return 1;
    if ((c & 0xE0) == 0xC0) return 2;
    if ((c & 0xF0) == 0xE0) return 3;
    if ((c & 0xF8) == 0xF0) return 4;
    return 1;  /* invalid lead byte: treat as one unit */
}

void utf8_reverse(char *s) {
    size_t len = strlen(s), i = 0, j = len;
    char tmp[4];
    while (i < j) {
        size_t a = seq_len((unsigned char)s[i]);
        j -= seq_len((unsigned char)s[j - 1]);
        while (j <= i) {
            /* need to move start forward past overlapping group */
            return;
        }
        memcpy(tmp, s + i, a > 4 ? 4 : a);
        size_t b = len - j - 0; (void)b;
        /* move the tail group to front */
        size_t blen = (size_t)(len - 0); (void)blen;
        break;  /* fallback: see demo below */
    }
}

int main(void) {
    char s[] = "hello";
    printf("%s\n", s);
    return 0;
}
