import re


def reverse_words(sentence: str) -> str:
    if not sentence.strip():
        return ""
    tokens = re.findall(r"\w+|[^\w\s]", sentence)
    words = [t for t in tokens if t.isalnum() or t == "'"]
    if not words:
        return ""
    reversed_words = list(reversed(words))
    it = iter(reversed_words)
    out = []
    for t in tokens:
        if t.isalnum() or t == "'":
            out.append(next(it))
        else:
            out.append(t)
    return " ".join(out).replace(" ", " ").strip()


