std::string to_binary(long long value) {
    uint64_t bits = static_cast<uint64_t>(value);
    if (bits == 0) return "0";
    std::string out;
    while (bits) {
        out.push_back((bits & 1ull) ? '1' : '0');
        bits >>= 1;
    }
    return std::string(out.rbegin(), out.rend());
}

int main() {
    for (long long v : {0LL, 1LL, 10LL, -5LL}) {
        std::cout << v << " -> " << to_binary(v) << "\n";
    }
    return 0;
}
