```python
OPEN = {"(": ")", "[": "]", "{": "}"}
CLOSE = {v: k for k, v in OPEN.items()}


def first_mismatch(s: str) -> int | None:
    """Return index of first unbalanced bracket, or None if balanced."""
    stack: list[tuple[str, int]] = []
    for i, ch in enumerate(s):
        if ch in OPEN:
            stack.append((ch, i))
        elif ch in CLOSE:
            if not stack or stack[-1][0] != CLOSE[ch]:
                return i
            stack.pop()
    if stack:
        return stack[-1][1]
    return None


if __name__ == "__main__":
    assert first_mismatch("([{}])") is None
    assert first_mismatch("(") == 0
    assert first_mismatch("(]") == 1
    assert first_mismatch("fü(à)") is None
    assert first_mismatch("[a)b") == 2
    print("ok")
```

Unmatched openers report the position of the deepest opener; unmatched closers report their own index.

