#include <cassert>
#include <iostream>
#include <vector>

// Merge two sorted ranges; adjacent duplicates collapse to one copy.
template <typename T>
std::vector<T> merge_unique(const std::vector<T>& a, const std::vector<T>& b) {
    std::vector<T> out;
    out.reserve(a.size() + b.size());
    auto push = [&out](const T& v) {
        if (out.empty() || !(out.back() == v)) out.push_back(v);
    };
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] < b[j])      push(a[i++]);
        else if (b[j] < a[i]) push(b[j++]);
        else { push(a[i]); ++i; ++j; }
    }
    while (i < a.size()) push(a[i++]);
    while (j < b.size()) push(b[j++]);
    return out;
}

int main() {
    using V = std::vector<int>;
    assert(merge_unique(V{}, V{}) == V{});
    assert((merge_unique(V{1, 2, 2, 5}, V{2, 3, 5, 5}) == V{1, 2, 3, 5}));
    assert((merge_unique(V{7}, V{}) == V{7}));
    std::cout << "ok\n";
    return 0;
}
```

Both source ranges must already be sorted; the merge is stable because ties from `a` are emitted before advancing `b`.

