        return true;
    }

    bool good() const noexcept { return fp_ != nullptr; }

private:
    std::FILE* fp_;
};

int main() {
    FileWriter w("out.txt");
    if (!w.good()) { std::cerr << "open failed\n"; return 1; }
    std::string err;
    if (!w.write("hello\n", err)) { std::cerr << "write failed: " << err << '\n'; return 1; }
    std::cout << "ok\n";
