        for _ in range(500):
            c.increment()

    threads = [threading.Thread(target=worker) for _ in range(4)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert c.snapshot() == 1000, c.snapshot()
    assert c.increment() is False
