template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& v) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = v;
        ++count_;
        return true;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T v = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return v;
    }

    std::size_t size() const { return count_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
