def is_balanced(text: str) -> bool:
    """True if (), [], {} are balanced, ignoring content inside ' or " quotes."""
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    quote = None
    escaped = False

    for ch in text:
        if quote is not None:
            if escaped:
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == quote:
                quote = None
            continue
        if ch in "'\"":
            quote = ch
        elif ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != pairs[ch]:
                return False

    return not stack and quote is None


if __name__ == "__main__":
    assert is_balanced("(a[b]{c})")
    assert is_balanced('f("{")')
    assert not is_balanced("([)]")
    assert not is_balanced('"unterminated')
    print("all ok")
