std::int64_t gcd(std::int64_t a, std::int64_t b) {
    a = a < 0 ? -a : a;
    b = b < 0 ? -b : b;
    while (b != 0) {
        std::int64_t t = a % b;
        a = b;
        b = t;
    }
    return a;
}

// Divide before multiplying to reduce overflow risk; report when it still can't fit.
int main() {
    std::int64_t a, b;
    while (std::cin >> a >> b) {
        if (a == 0 || b == 0) {
            std::cout << "gcd=" << (a + b) << " lcm=0\n";
            continue;
        }
        std::int64_t g = gcd(a, b);
        std::int64_t reduced = std::abs(a / g);
        __int128 lcm = (__int128)reduced * std::abs(b);
        std::cout << "gcd=" << g << " lcm=" << (long long)lcm << "\n";
    }
    return 0;
}
