int parse_line(const char *line, long *out, size_t max, size_t *count) {
    char *buf = strdup(line);
    if (!buf) return -1;

    *count = 0;
    char *save = NULL;
    for (char *tok = strtok_r(buf, ",", &save); tok; tok = strtok_r(NULL, ",", &save)) {
        while (*tok == ' ' || *tok == '\t') tok++;
        if (*tok == '\0') { free(buf); return -2; }
        if (*count >= max) { free(buf); return -3; }

        errno = 0;
        char *end = NULL;
        long v = strtol(tok, &end, 10);
        if (errno == ERANGE || *end != '\0') { free(buf); return -2; }
        out[(*count)++] = v;
    }

    free(buf);
    return 0;
}

int main(void) {
    const char *line = "10, -3, 42";
    long values[8];
    size_t n = 0;
    int rc = parse_line(line, values, 8, &n);
    if (rc != 0) {
        fprintf(stderr, "parse error %d\n", rc);
        return 1;
    }
    for (size_t i = 0; i < n; i++) printf("%ld\n", values[i]);
    return 0;
}
