import random


def kth_smallest(nums, k):
    """Return the k-th smallest element (1-indexed) of nums.

    nums: list of comparable values
    k: 1-based index; must satisfy 1 <= k <= len(nums)
    """
    if not nums:
        raise ValueError("list is empty")
    if not 1 <= k <= len(nums):
        raise ValueError("k out of range")
    target = k - 1

    def select(left, right):
        while left < right:
            pivot_idx = random.randint(left, right)
            pivot = nums[pivot_idx]
            nums[left], nums[pivot_idx] = nums[pivot_idx], nums[left]
            store = left
            for i in range(left + 1, right + 1):
                if nums[i] < pivot:
                    store += 1
                    nums[store], nums[i] = nums[i], nums[store]
            nums[left], nums[store] = nums[store], nums[left]
            if store == target:
                return nums[store]
            if store < target:
                left = store + 1
            else:
                right = store - 1
        return nums[left]

    return select(0, len(nums) - 1)


if __name__ == "__main__":
    print(kth_smallest([3, 1, 4, 1, 5, 9, 2, 6], 3))  # 2
    print(kth_smallest([7], 1))                        # 7
    print(kth_smallest([2, 2, 2], 2))                  # 2
```

Quickselect swaps a random pivot to the front, partitions in place, then recurses into the side holding index `k-1`. Duplicates land on the `>=` side, so equal elements are handled without special cases. Average time is O(n); worst case is O(n²) under unlucky pivots, which the randomized choice makes improbable.

