```cpp
#include <condition_variable>
#include <deque>
#include <mutex>
#include <optional>
#include <chrono>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t cap) : cap_(cap) {}

    bool push(int v) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [&] { return q_.size() < cap_ || closed_; });
        if (closed_) return false;
        q_.push_back(v);
        not_empty_.notify_one();
        return true;
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [&] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;
        int v = q_.front();
        q_.pop_front();
        not_full_.notify_one();
        return v;
    }

    template <class Rep, class Period>
    std::optional<int> pop_for(std::chrono::duration<Rep, Period> d) {
        std::unique_lock<std::mutex> lk(m_);
        if (!not_empty_.wait_for(lk, d, [&] { return !q_.empty() || closed_; }))
            return std::nullopt;
        if (q_.empty()) return std::nullopt;
        int v = q_.front();
        q_.pop_front();
        not_full_.notify_one();
        return v;
    }

    void shutdown() {
        std::lock_guard<std::mutex> lk(m_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    std::deque<int> q_;
    bool closed_ = false;
    std::mutex m_;
    std::condition_variable not_empty_, not_full_;
};
```

Each wait uses a predicate so spurious wakeups are safe. `shutdown` sets a flag under the lock and notifies both sides: blocked poppers return `nullopt` once the queue drains, and blocked pushers fail immediately. `push` returns `false` on a closed queue rather than throwing.

```cpp
#include <iostream>
#include <sstream>
#include <string>
#include <unordered_map>

std::unordered_map<std::string, std::string> parse_kv(const std::string& line) {
    std::unordered_map<std::string, std::string> out;
    std::stringstream ss(line);
    std::string pair;
    while (std::getline(ss, pair, ';')) {
        auto eq = pair.find('=');
        if (eq == std::string::npos) continue;          // no '=' -> skip
        std::string key = pair.substr(0, eq);
        std::string val = pair.substr(eq + 1);
        if (key.empty()) continue;                      // empty key -> skip
        out[key] = val;                                 // last one wins
    }
    return out;
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        if (line.empty()) continue;
        auto kv = parse_kv(line);
        for (const auto& [k, v] : kv)
            std::cout << k << " -> " << v << '\n';
        std::cout << "--\n";
    }
    return 0;
}
```

`find('=')` splits only on the first `=`, so values may contain `=` (e.g. base64 padding). Empty keys and pairs without `=` are dropped; empty values like `flag=` are kept. Iteration order is unspecified because it uses `unordered_map`.

```rust
use std::fmt;

#[derive(Debug, PartialEq, Eq)]
pub struct Version {
    pub major: u32,
    pub minor: u32,
    pub patch: u32,
}

#[derive(Debug, PartialEq, Eq)]
pub struct ParseError(String);

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "invalid version: {}", self.0)
    }
}

impl std::str::FromStr for Version {
    type Err = ParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let parts: Vec<&str> = s.split('.').collect();
        if parts.len() != 3 {
            return Err(ParseError(s.to_string()));
        }
        let parse = |p: &str| -> Result<u32, ParseError> {
            p.parse::<u32>().map_err(|_| ParseError(s.to_string()))
        };
        Ok(Version {
            major: parse(parts[0])?,
            minor: parse(parts[1])?,
            patch: parse(parts[2])?,
        })
    }
}

fn main() {
    for s in ["1.2.3", "10.0.42", "1.2", "1.2.x", "1.2.3-beta"] {
        match s.parse::<Version>() {
            Ok(v) => println!("{s} -> {v:?}"),
            Err(e) => println!("{s} -> error ({e})"),
        }
    }
}
```

`split('.')` plus an exact length check rejects both short and over-long inputs, and `1.2.3-beta` fails on the non-numeric `patch` since the `-beta` suffix is not a `u32`. `u32` parsing rejects negatives, signs, and overflow automatically.

```rust
use std::collections::HashSet;
use std::env;
use std::fs;
use std::process;

fn dedupe_preserve(text: &str) -> Vec<i64> {
    let mut seen = HashSet::new();
    let mut out = Vec::new();
    for tok in text.split_whitespace() {
        match tok.parse::<i64>() {
            Ok(n) => {
                if seen.insert(n) {
                    out.push(n);
                }
            }
            Err(_) => {
                eprintln!("skipping non-integer token: {tok:?}");
            }
        }
    }
    out
}

fn main() {
    let mut args = env::args().skip(1);
    let path = match args.next() {
        Some(p) => p,
        None => {
            eprintln!("usage: dedupe FILE");
            process::exit(2);
        }
    };
    let text = match fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {path}: {e}");
            process::exit(1);
        }
    };
    for n in dedupe_preserve(&text) {
        println!("{n}");
    }
}
```

`HashSet::insert` returns `true` only for new values, so the first occurrence sets order and later duplicates are silently dropped. Non-integer tokens go to stderr instead of aborting, and read failures exit nonzero with the OS error.

```c
#include <stdio.h>
#include <stdlib.h>

/* a and b hold decimal digits, most significant first.
   Returns a malloc'd array of n_a + n_b digits, most significant first,
   or NULL on allocation failure. Out length is written to *out_len. */
int *big_mul(const int *a, int n_a, const int *b, int n_b, int *out_len) {
    int n = n_a + n_b;
    int *res = calloc((size_t)n, sizeof(int));
    if (!res) return NULL;

    for (int i = n_a - 1; i >= 0; i--) {
        int carry = 0;
        for (int j = n_b - 1; j >= 0; j--) {
            int pos = i + j + 1;
            int cur = res[pos] + a[i] * b[j] + carry;
            res[pos] = cur % 10;
            carry = cur / 10;
        }
        res[i] += carry;
    }

    int start = 0;
    while (start < n - 1 && res[start] == 0) start++;   /* drop leading zeros */
    if (start > 0) {
        for (int k = 0; k < n - start; k++) res[k] = res[start + k];
        n -= start;
    }
    *out_len = n;
    return res;
}

int main(void) {
    int a[] = {1, 2, 3};
    int b[] = {4, 5};
    int len;
    int *p = big_mul(a, 3, b, 2, &len);
    if (!p) return 1;
    for (int i = 0; i < len; i++) putchar('0' + p[i]);
    putchar('\n');   /* 123 * 45 = 5535 */
    free(p);
    return 0;
}
```

This is schoolbook multiplication: for each digit of `a`, multiply across `b` accumulating into `res[i+j+1]` with a carry. `calloc` zeroes the buffer, so `res[pos]` is safe to add to. The leading-zero trim leaves at least one digit, so `0 * 0` prints `0`.

```cpp
#include <fstream>
#include <stdexcept>
#include <string>

class FileReader {
public:
    static std::string read_all(const std::string& path) {
        std::ifstream in(path, std::ios::binary);
        if (!in) {
            throw std::runtime_error("cannot open file: " + path);
        }

        in.seekg(0, std::ios::end);
        const std::streamoff size = in.tellg();
        if (size < 0) {
            throw std::runtime_error("cannot determine size of: " + path);
        }

        std::string out;
        out.resize(static_cast<std::size_t>(size));

        in.seekg(0, std::ios::beg);
        if (size > 0 && !in.read(out.data(), size)) {
            throw std::runtime_error("short read on: " + path);
        }
        return out;
    }
};
```

Opening in `std::ios::binary` stops newline translation and keeps byte counts exact, so the buffer size matches `tellg`. A `tellg` of `-1` on pipes or unusual streams becomes an explicit error rather than a huge allocation. `read` returns false on a short read, which throws instead of returning a partially filled string.

