class Stack {
    std::vector<int> data_;
    size_t capacity_;
public:
    explicit Stack(size_t capacity) : capacity_(capacity) {}

    void push(int v) {
        if (data_.size() >= capacity_) throw std::overflow_error("stack full");
        data_.push_back(v);
    }

    int pop() {
        if (data_.empty()) throw std::underflow_error("stack empty");
        int v = data_.back();
        data_.pop_back();
        return v;
    }

    bool empty() const { return data_.empty(); }
    size_t size() const { return data_.size(); }
};

