        (vec![1, 3, 5], vec![2, 3, 6], vec![1, 2, 3, 3, 5, 6]),
        (vec![], vec![1, 2], vec![1, 2]),
        (vec![1, 2], vec![], vec![1, 2]),
        (vec![], vec![], vec![]),
    ];

