class RingBuffer:
    """Fixed-size buffer that overwrites the oldest item once full."""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._data = [None] * capacity
        self._start = 0
        self._size = 0

    def append(self, item):
        index = (self._start + self._size) % self._capacity
        self._data[index] = item
        if self._size < self._capacity:
            self._size += 1
        else:
            self._start = (self._start + 1) % self._capacity

    def __len__(self):
        return self._size

    def __iter__(self):
        for i in range(self._size):
            yield self._data[(self._start + i) % self._capacity]

    def __repr__(self):
        return f"RingBuffer({list(self)!r}, capacity={self._capacity})"


def _test():
    rb = RingBuffer(3)
    assert list(rb) == []
    rb.append("a"); rb.append("b")
    assert list(rb) == ["a", "b"]
    rb.append("c"); rb.append("d")  # overwrites "a"
    assert list(rb) == ["b", "c", "d"]
    assert len(rb) == 3
    rb.append("e")
    assert list(rb) == ["c", "d", "e"]
    print("ring buffer tests passed")


if __name__ == "__main__":
