#include <cstddef>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
        else tail_ = (tail_ + 1) % N;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3); rb.push(4);
    if (rb.size() != 3) return 1;
    if (rb.pop() != 2) return 1;
    if (rb.pop() != 3) return 1;
    if (rb.pop() != 4) return 1;
    if (rb.pop().has_value()) return 1;
    return 0;
}
