size_t reverse_string(char *s) {
    if (s == NULL) {
        return 0;
    }
    size_t len = 0;
    while (s[len] != '\0') {
        ++len;
    }
    for (size_t i = 0; i < len / 2; ++i) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
    return len;
