class MinHeap:
    def __init__(self, items=None):
        self._data = []
        if items:
            for it in items:
                self.push(it)

    def __len__(self):
        return len(self._data)

    def push(self, value):
        self._data.append(value)
        i = len(self._data) - 1
        while i > 0:
            parent = (i - 1) // 2
            if self._data[parent] <= self._data[i]:
                break
            self._data[parent], self._data[i] = self._data[i], self._data[parent]
            i = parent

    def pop(self):
        if not self._data:
            raise IndexError("pop from empty heap")
        top = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            i = 0
            n = len(self._data)
            while True:
                left = 2 * i + 1
                right = 2 * i + 2
                smallest = i
                if left < n and self._data[left] < self._data[smallest]:
                    smallest = left
                if right < n and self._data[right] < self._data[smallest]:
                    smallest = right
                if smallest == i:
                    break
                self._data[i], self._data[smallest] = self._data[smallest], self._data[i]
                i = smallest
        return top


if __name__ == "__main__":
    h = MinHeap([5, 3, 8, 1])
    out = [h.pop() for _ in range(len(h))]
    print(out)  # [1, 3, 5, 8]
