from collections import deque

def bfs_order(graph, start):
    if start not in graph:
        return []
    seen = {start}
    order = []
    queue = deque([start])
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph.get(node, ()):
            if neighbor not in seen:
                seen.add(neighbor)
                queue.append(neighbor)
    return order


if __name__ == "__main__":
    tree = {
        "a": ["b", "c"],
        "b": ["d", "e"],
        "c": ["f"],
        "d": [],
        "e": [],
        "f": [],
    }
    print(bfs_order(tree, "a"))  # ['a', 'b', 'c', 'd', 'e', 'f']

    cyclic = {"x": ["y"], "y": ["z"], "z": ["x"]}
    print(bfs_order(cyclic, "x"))  # ['x', 'y', 'z']

    print(bfs_order({}, "nope"))  # []
