```rust
use std::collections::HashMap;

pub fn top_n_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Sort by count desc, then word asc for deterministic output.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_input() {
        assert!(top_n_words("", 3).is_empty());
    }

    #[test]
    fn punctuation_and_case() {
        let got = top_n_words("The cat, the CAT! A dog.", 2);
        assert_eq!(got, vec![("the".to_string(), 3), ("cat".to_string(), 2)]);
    }

    #[test]
    fn n_larger_than_words() {
        assert_eq!(top_n_words("hi hi", 5).len(), 1);
    }
}
```

Non-alphanumeric characters are stripped before lowercasing, ties break alphabetically so output is stable, and `truncate` handles `n` larger than the distinct word count. Run the tests with `cargo test`.

```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1
    c.put("c", 3)          # evicts "b"
    assert c.get("b") is None
    assert c.get("a") == 1
    assert c.get("c") == 3
    c.put("a", 9)          # update keeps recency
    assert c.get("a") == 9
    assert len(c) == 2
    try:
        LRUCache(0)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
    print("all tests passed")
```

`OrderedDict.move_to_end` and `popitem(last=False)` give O(1) recency updates and eviction. `get` returns `None` for a miss, and the constructor rejects non-positive capacity.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(const Node *head) {
    for (const Node *cur = head; cur; cur = cur->next) {
        printf("%d%s", cur->value, cur->next ? " -> " : "\n");
    }
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 5; i >= 1; --i) {
        list = push(list, i);
    }
    printf("original: ");
    print_list(list);
    list = reverse(list);
    printf("reversed: ");
    print_list(list);
    free_list(list);
    return 0;
}
```

Iterative reversal relinks pointers in one pass, so it runs in O(n) time and O(1) extra space — no recursion depth risk on long lists. The program also frees every node before exit.

