fn triangle_iter(n: u64) -> impl Iterator<Item = u64> {
    (0..=n).scan(0u64, |acc, k| {
        *acc += k;
        Some(*acc)
    })
}

fn main() {
    let n: u64 = 1000;
    let mut count = 0u64;
    for (k, t) in (0..=n).zip(triangle_iter(n)) {
        let closed = k * (k + 1) / 2;
        assert_eq!(t, closed, "mismatch at n={k}");
        count += 1;
    }
    println!("verified {count} triangle numbers up to n={n}");

    // Edge case: n = 0 gives a single value, 0.
    assert_eq!(triangle_iter(0).last(), Some(0));
    println!("edge case n=0 ok");
}
```

`scan` carries a running sum so each item is produced in O(1) after the previous, and the loop cross-checks every value against `n(n+1)/2`. Overflows are avoided by keeping `n` at 1000, well inside `u64`. Run with `rustc -O triangles.rs && ./triangles`.

