#include <iostream>
#include <stack>
#include <string>

bool is_balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.empty();   // leftover opens means unbalanced
}

int main() {
    const std::string cases[] = {"", "()", "([{}])", "(]", "(()", ")]}", "{[()()]}"};
    const bool expected[]        = {true, true, true, false, false, false, true};
    for (size_t i = 0; i < std::size(cases); ++i) {
        bool got = is_balanced(cases[i]);
        std::cout << "\"" << cases[i] << "\" -> " << (got ? "balanced" : "unbalanced") << '\n';
        if (got != expected[i]) {
            std::cerr << "test failure at case " << i << '\n';
            return 1;
        }
    }
    return 0;
}
```

The stack pushes openers and matches them on closers; an empty string and a lone closing bracket are both handled. The `return st.empty()` catches unclosed opens like `(()`.

