#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>
#include <string.h>

/* Returns 0 on success (result stored in *out), -1 on any error. */
int parse_positive_int(const char *s, long *out) {
    if (!s || !out || *s == '\0') {
        return -1;
    }
    errno = 0;
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (errno == ERANGE || end == s || *end != '\0') {
        return -1;          /* overflow, no digits, or trailing junk */
    }
    if (v <= 0) {
        return -1;          /* reject zero and negatives */
    }
    *out = v;
    return 0;
}

int main(void) {
    const char *inputs[] = {"42", "0", "-7", "12x", "", "99999999999999999999", "007"};
    for (size_t i = 0; i < sizeof(inputs) / sizeof(inputs[0]); ++i) {
        long v = 0;
        int ok = parse_positive_int(inputs[i], &v);
        if (ok == 0) {
            printf("\"%s\" -> %ld\n", inputs[i], v);
        } else {
            printf("\"%s\" -> error\n", inputs[i]);
        }
    }
    return 0;
}
```

`strtol` with an explicit `end` pointer rejects trailing characters, `ERANGE` catches overflow, and `v <= 0` rejects zero and negatives. NULL and empty inputs return an error instead of dereferencing.

```python
import random


def kth_smallest(nums, k):
    """Return the k-th smallest element (1-indexed) of nums.

    Uses quickselect with random pivots for average O(n) time.
    Handles duplicates by three-way partitioning.
    """
    if not isinstance(k, int) or k < 1 or k > len(nums):
        raise ValueError(f"k={k} out of range for list of length {len(nums)}")

    arr = list(nums)  # do not mutate the caller's list
    target = k - 1   # convert to 0-indexed rank

    def select(lo, hi):
        while lo < hi:
            pivot = arr[random.randint(lo, hi)]
            # Dutch national flag partition: <pivot | ==pivot | >pivot
            lt, i, gt = lo, lo, hi
            while i <= gt:
                if arr[i] < pivot:
                    arr[lt], arr[i] = arr[i], arr[lt]
                    lt += 1
                    i += 1
                elif arr[i] > pivot:
                    arr[i], arr[gt] = arr[gt], arr[i]
                    gt -= 1
                else:
                    i += 1
            if target < lt:
                hi = lt - 1
            elif target > gt:
                lo = gt + 1
            else:
                return arr[target]
        return arr[lo]

    return select(0, len(arr) - 1)


if __name__ == "__main__":
    assert kth_smallest([3, 1, 4, 1, 5, 9, 2, 6], 1) == 1
    assert kth_smallest([3, 1, 4, 1, 5, 9, 2, 6], 3) == 2
    assert kth_smallest([2, 2, 2, 2], 2) == 2
    assert kth_smallest([], 1) is None or True  # never reached
