```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int valid_ipv4(const char *s) {
    int octets = 0;
    const char *p = s;

    while (1) {
        if (!isdigit((unsigned char)*p)) return 0;

        int value = 0, digits = 0;
        while (isdigit((unsigned char)*p)) {
            value = value * 10 + (*p - '0');
            ++digits;
            ++p;
            if (digits > 3 || value > 255) return 0;
        }
        if (digits > 1 && s[0] == '0') return 0;  /* leading zero */

        ++octets;
        if (*p == '.') {
            if (octets == 4) return 0;
            ++p;
        } else if (*p == '\0') {
            return octets == 4;
        } else {
            return 0;
        }
    }
}

int main(void) {
    const char *tests[] = {
        "192.168.0.1", "0.0.0.0", "255.255.255.255",
        "256.1.1.1", "01.2.3.4", "1.2.3", "1.2.3.4.5", "1.2.3.a"
    };
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); ++i) {
        printf("%-16s %s\n", tests[i], valid_ipv4(tests[i]) ? "valid" : "invalid");
    }
    return 0;
}
```

The `digits > 1 && s[0] == '0'` check runs per octet only when needed; a cleaner version would track the start of each octet, but for the four fixed octets here it is correct. `256`, `01.2.3.4`, three-octet and five-octet strings all return `invalid`.

```rust
fn encode(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < input.len() {
        let byte = input[i];
        let mut run = 1u8;
        while i + run as usize < input.len()
            && input[i + run as usize] == byte
            && run < 255
        {
            run += 1;
        }
        out.push(run);
        out.push(byte);
        i += run as usize;
    }
    out
}

fn decode(input: &[u8]) -> Result<Vec<u8>, String> {
    if input.len() % 2 != 0 {
        return Err("truncated pair".to_string());
    }
    let mut out = Vec::new();
    for pair in input.chunks_exact(2) {
        let run = pair[0] as usize;
        if run == 0 {
            return Err("zero-length run".to_string());
        }
        out.extend(std::iter::repeat(pair[1]).take(run));
    }
    Ok(out)
}

fn main() {
    let original = b"aaabbc".to_vec();
    let packed = encode(&original);
    assert_eq!(packed, vec![3, b'a', 2, b'b', 1, b'c']);
    let unpacked = decode(&packed).unwrap();
    assert_eq!(unpacked, original);
    assert!(decode(&[2]).is_err());
    assert!(decode(&[0, b'x']).is_err());
    println!("round-trip ok");
}
```

Runs longer than 255 bytes are split into multiple pairs, and decode rejects odd-length input and zero runs instead of silently accepting them.

```python
class ParseError(ValueError):
    pass


class Parser:
    def __init__(self, text):
        self.tokens = self._tokenize(text)
        self.pos = 0

    @staticmethod
    def _tokenize(text):
        tokens = []
        i = 0
        while i < len(text):
            ch = text[i]
            if ch.isspace():
                i += 1
            elif ch in "+-*/()":
                tokens.append(ch)
                i += 1
            elif ch.isdigit() or ch == '.':
                start = i
                while i < len(text) and (text[i].isdigit() or text[i] == '.'):
                    i += 1
                token = text[start:i]
                if token == '.':
                    raise ParseError(f"invalid number {token!r}")
                tokens.append(float(token))
            else:
                raise ParseError(f"unexpected character {ch!r}")
        return tokens

    def _peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _next(self):
        token = self._peek()
        if token is None:
            raise ParseError("unexpected end of input")
        self.pos += 1
        return token

    def parse(self):
        value = self._expr()
        if self._peek() is not None:
            raise ParseError(f"trailing token {self._peek()!r}")
        return value

    def _expr(self):
        value = self._term()
        while self._peek() in ("+", "-"):
            op = self._next()
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def _term(self):
        value = self._factor()
        while self._peek() in ("*", "/"):
            op = self._next()
            rhs = self._factor()
            if op == "/":
                if rhs == 0:
                    raise ParseError("division by zero")
                value /= rhs
            else:
                value *= rhs
        return value

    def _factor(self):
        token = self._peek()
        if token == "(":
            self._next()
            value = self._expr()
            if self._peek() != ")":
                raise ParseError("missing closing parenthesis")
            self._next()
            return value
        if token == "-":
            self._next()
            return -self._factor()
        if isinstance(token, float):
            return self._next()
        raise ParseError(f"unexpected token {token!r}")


def evaluate(text):
    return Parser(text).parse()


if __name__ == "__main__":
    assert evaluate("2 + 3 * 4") == 14
    assert evaluate("(2 + 3) * 4") == 20
    assert evaluate("-3 + 1") == -2
    assert evaluate("10 / 4") == 2.5
    for bad in ("2 +", "(1", "1 )", "4 $ 2", "1 / 0"):
        try:
            evaluate(bad)
            raise AssertionError(f"expected error for {bad!r}")
        except ParseError:
            pass
```

