#include <cstdint>
#include <numeric>
#include <stdexcept>
#include <utility>
#include <vector>
#include <iostream>

template <typename Container>
std::pair<long long, long long> mean_remainder(const Container& data) {
    if (data.empty()) {
        throw std::invalid_argument("mean of empty container");
    }

    // Accumulate in a signed 128-bit intermediate to dodge overflow on sums
    // of large int64 values, then reduce modulo the count.
    __int128 sum = 0;
    for (const auto& v : data) {
        sum += static_cast<__int128>(v);
    }
    long long n = static_cast<long long>(data.size());

    // C++ integer division truncates toward zero; keep the sign on the remainder.
    __int128 q = sum / n;
    __int128 r = sum % n;
    return {static_cast<long long>(q), static_cast<long long>(r)};
}

int main() {
    std::vector<int> a{1, 2, 3, 4};
    auto [q, r] = mean_remainder(a);
    std::cout << q << " rem " << r << "\n";

    std::vector<long long> big{5'000'000'000LL, 5'000'000'000LL, 5'000'000'000LL};
    auto [bq, br] = mean_remainder(big);
    std::cout << bq << " rem " << br << "\n";

    try {
        mean_remainder(std::vector<int>{});
    } catch (const std::invalid_argument& e) {
        std::cout << "caught: " << e.what() << "\n";
    }
    return 0;
}
```

`__int128` is a GCC/Clang extension that removes the intermediate overflow that a plain `long long` sum would hit for large inputs; if you target MSVC, swap in `long double` accumulation or a checked add. The remainder keeps the sign of the truncated quotient, matching the language's division rule.

