#include <iostream>
#include <string>
#include <vector>

static std::vector<std::string> split_utf8(const std::string& s) {
    std::vector<std::string> out;
    for (size_t i = 0; i < s.size();) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        size_t len = 1;
        if ((c & 0x80) == 0) len = 1;
        else if ((c & 0xE0) == 0xC0) len = 2;
        else if ((c & 0xF0) == 0xE0) len = 3;
        else if ((c & 0xF8) == 0xF0) len = 4;
        if (i + len > s.size()) len = 1;  // malformed tail: treat byte as one unit
        out.push_back(s.substr(i, len));
        i += len;
    }
    return out;
}

int main() {
    std::string s;
    std::getline(std::cin, s);
    auto glyphs = split_utf8(s);
    for (size_t i = 0, j = glyphs.size(); i < j; ++i, --j) {
        std::swap(glyphs[i], glyphs[j - 1]);
    }
    for (const auto& g : glyphs) std::cout << g;
    std::cout << '\n';
    return 0;
}
```

