int is_palindrome(const char *s) {
    size_t i = 0, j = strlen(s);
    if (j == 0) return 1;
    j--;
    while (i < j) {
        if (!isalnum((unsigned char)s[i])) { i++; continue; }
        if (!isalnum((unsigned char)s[j])) { j--; continue; }
        if (tolower((unsigned char)s[i]) != tolower((unsigned char)s[j])) return 0;
        i++; j--;
    }
    return 1;
}

int main(void) {
    const char *cases[] = {
a        "A man, a plan, a canal: Panama",
        "race a car",
        "",
        "Was it a car or a cat I saw?"
    };
    for (int k = 0; k < 4; k++)
        printf("%d\n", is_palindrome(cases[k]));
    return 0;
}
```
Two pointers skip non-alphanumeric characters and compare the rest case-insensitively. Casting to `unsigned char` before `isalnum`/`tolower` avoids undefined behaviour on negative `char` values.

