std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else              out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a = {1, 3, 3, 7};
    std::vector<int> b = {2, 3, 4, 8};
    std::vector<int> m = merge_sorted(a, b);
    for (size_t k = 0; k < m.size(); k++) std::cout << m[k] << (k + 1 < m.size() ? ' ' : '\n');
    return 0;
}
```
The `<=` comparison keeps equal values from `a` first, which makes the merge stable. Tail loops drain whatever remains after one input is exhausted.

