Node* reverse(Node* head) {
    Node* prev = nullptr;
    Node* cur = head;
    while (cur != nullptr) {
        Node* next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

int main() {
    Node* head = nullptr;
    for (int v : {10, 20, 30, 40}) {
        Node* n = new Node(v);
        n->next = head;  // build 40 -> 30 -> 20 -> 10
        head = n;
    }

    head = reverse(head);  // now 10 -> 20 -> 30 -> 40
    for (Node* p = head; p != nullptr; p = p->next) {
        std::cout << p->value;
        if (p->next) std::cout << ' ';
    }
    std::cout << '\n';

    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
    return 0;
