```cpp
#include <cstddef>
#include <deque>
#include <optional>
#include <stdexcept>

template <typename T>
class RollingAverage {
public:
    explicit RollingAverage(std::size_t window)
        : window_(window) {
        if (window == 0) throw std::invalid_argument("window must be > 0");
    }

    void add(T value) {
        if (data_.size() == window_) {
            sum_ -= data_.front();
            data_.pop_front();
        }
        data_.push_back(value);
        sum_ += value;
    }

    std::optional<double> value() const {
        if (data_.empty()) return std::nullopt;
        return static_cast<double>(sum_) / static_cast<double>(data_.size());
    }

private:
    std::size_t window_;
    std::deque<T> data_;
    T sum_{};
};

#include <cassert>
int main() {
    RollingAverage<int> avg(3);
    assert(!avg.value().has_value());
    avg.add(1); avg.add(2); avg.add(3);
    assert(*avg.value() == 2.0);
    avg.add(4);
    assert(*avg.value() == 3.0);
}
```
`sum_` is maintained incrementally so `add` stays O(1); the deque holds at most `window_` samples.

