/* Returns 0 on success, -1 on error. *out holds the value only on success. */
int parse_long(const char *s, long *out) {
    if (s == NULL || *s == '\0') return -1;
    errno = 0;
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (errno == ERANGE) return -1;      /* overflow / underflow */
    if (end == s || *end != '\0') return -1; /* trailing junk or empty */
    *out = v;
    return 0;
}

int main(void) {
    long v;
    if (parse_long("42", &v) == 0) printf("42 -> %ld\n", v);
    if (parse_long("12abc", &v) != 0) puts("rejected 12abc");
    if (parse_long("", &v) != 0) puts("rejected empty");
    if (parse_long("99999999999999999999", &v) != 0) puts("rejected overflow");
    return 0;
}
```
`strtol` sets `errno` to `ERANGE` on overflow and leaves `*end` at the first unparsed byte, which is exactly what the two checks rely on.

