#include <cassert>
#include <cstddef>
#include <string>

std::size_t count_occurrences(const std::string& text,
                              const std::string& pattern,
                              bool allow_overlap) {
    if (pattern.empty() || pattern.size() > text.size()) return 0;
    std::size_t count = 0;
    std::size_t pos = text.find(pattern);
    while (pos != std::string::npos) {
        ++count;
        std::size_t step = allow_overlap ? 1 : pattern.size();
        pos = text.find(pattern, pos + step);
    }
    return count;
}

int main() {
    assert(count_occurrences("aaaa", "aa", false) == 2);
    assert(count_occurrences("aaaa", "aa", true) == 3);
    assert(count_occurrences("abc", "", false) == 0);
    assert(count_occurrences("abc", "abcd", true) == 0);
}
