#include <algorithm>
#include <cctype>
#include <string>
#include <cassert>

namespace {
void reverse_range(std::string& s, std::size_t lo, std::size_t hi) {
    // [lo, hi) half-open
    while (lo < hi && lo < --hi) std::swap(s[lo++], s[hi]);
}

std::size_t compact_spaces(std::string& s) {
    std::size_t w = 0;
    bool pending = false;
    for (char ch : s) {
        if (std::isspace(static_cast<unsigned char>(ch))) {
            pending = w != 0;
            continue;
        }
        if (pending) s[w++] = ' ';
        pending = false;
        s[w++] = ch;
    }
    s.resize(w);
    return w;
}
}  // namespace

std::string reverse_words(std::string s) {
    const std::size_t n = compact_spaces(s);
    reverse_range(s, 0, n);
    std::size_t start = 0;
    for (std::size_t i = 0; i <= n; ++i) {
        if (i == n || s[i] == ' ') {
            reverse_range(s, start, i);
            start = i + 1;
        }
    }
    return s;
}

int main() {
    assert(reverse_words("  the quick   brown fox ") == "fox brown quick the");
    assert(reverse_words("") == "");
    assert(reverse_words("   ") == "");
    assert(reverse_words("one") == "one");
    return 0;
}
