#include <limits.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

/* Write the two's-complement binary of value into buf (size >= 65) and return it. */
char *to_binary(long long value, char *buf, size_t bufsize) {
    if (bufsize < 65) {
        return NULL; /* need 64 bits plus terminator */
    }
    unsigned long long magnitude = (value < 0)
        ? (unsigned long long)(-(value + 1)) + 1ULL
        : (unsigned long long)value;

    size_t pos = 0;
    if (value < 0) {
        buf[pos++] = '-';
    }
    if (magnitude == 0) {
        buf[pos++] = '0';
        buf[pos] = '\0';
        return buf;
    }

    char tmp[64];
    size_t n = 0;
    while (magnitude > 0) {
        tmp[n++] = (char)('0' + (magnitude & 1ULL));
        magnitude >>= 1;
    }
    while (n > 0) {
        buf[pos++] = tmp[--n];
    }
    buf[pos] = '\0';
    return buf;
}

int main(void) {
    char buf[65];
    struct { long long v; const char *want; } cases[] = {
        {0, "0"}, {1, "1"}, {5, "101"}, {255, "11111111"},
        {-1, "-1"}, {-5, "-101"}, {LLONG_MAX, "111111111111111111111111111111111111111111111111111111111111111"},
    };
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; ++i) {
        char *got = to_binary(cases[i].v, buf, sizeof buf);
        if (got == NULL || strcmp(got, cases[i].want) != 0) {
            fprintf(stderr, "fail: %lld -> %s (want %s)\n",
                    cases[i].v, got ? got : "(null)", cases[i].want);
            return 1;
        }
    }
    puts("all tests passed");
    return 0;
}
