`split_at` panics when `mid > len`, so the guard returns `None` first. The boundary cases `mid == 0` and `mid == len` produce empty slices on one side rather than erroring, which is the useful convention.

```c
#include <stdio.h>
#include <limits.h>

int is_palindrome(int x) {
    if (x < 0) return 0;          /* negatives never palindrome here */
    if (x != 0 && x % 10 == 0) return 0; /* trailing zero: can't be reversal unless 0 */

    int reversed = 0;
    while (x > reversed) {
        reversed = reversed * 10 + x % 10;
        x /= 10;
    }
    /* even length: x == reversed; odd length: x == reversed / 10 */
    return x == reversed || x == reversed / 10;
}

int main(void) {
    int tests[] = {121, -121, 10, 0, 12321, 1001, 12345};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); i++) {
        printf("%d -> %d\n", tests[i], is_palindrome(tests[i]));
    }
    return 0;
}
```

Building `reversed` only while `x > reversed` halves the digits, avoiding overflow. The final check covers even-length numbers directly and odd-length by dropping the middle digit. `12321` and `1001` return 1; `10` and `12345` return 0.

```python
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)

cache = LRUCache(2)
cache.put("a", 1); cache.put("b", 2)
assert cache.get("a") == 1          # 'a' now most recent
cache.put("c", 3)                    # evicts 'b'
assert cache.get("b") is None
assert cache.get("c") == 3
assert len(cache) == 2
```

`OrderedDict` remembers insertion order; `move_to_end` promotes on access, and `popitem(last=False)` evicts the least-recently-used entry. Capacity is validated so a zero-capacity cache can't silently drop everything.

```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() || j < b.len() {
        let next = if j >= b.len() || (i < a.len() && a[i] <= b[j]) {
            let v = a[i];
            i += 1;
            v
        } else {
            let v = b[j];
            j += 1;
            v
        };
        if out.last() != Some(&next) {
            out.push(next);
        }
    }
    out
}

fn main() {
    assert_eq!(merge_sorted(&[1, 3, 5, 5], &[2, 3, 6]), vec![1, 2, 3, 5, 6]);
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[], &[4, 4, 4]), vec![4]);
    println!("ok");
}
```

The single `next` value is chosen from whichever head is smaller, then deduplicated by comparing against the last pushed element. This handles empty inputs and repeated values across both vectors in one linear pass.

```cpp
#include <algorithm>
#include <stdexcept>
#include <vector>
#include <iostream>

template <typename T>
double median(std::vector<T> values) {
    if (values.empty()) {
        throw std::invalid_argument("median of empty vector");
    }
    std::sort(values.begin(), values.end());
    size_t n = values.size();
    size_t mid = n / 2;
    if (n % 2 == 1) {
        return static_cast<double>(values[mid]);
    }
    return (static_cast<double>(values[mid - 1]) + static_cast<double>(values[mid])) / 2.0;
}

int main() {
    std::cout << median<int>({3, 1, 2}) << '\n';        // 2
    std::cout << median<int>({4, 1, 3, 2}) << '\n';     // 2.5
    try {
        median<int>({});
    } catch (const std::invalid_argument& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
```

The function takes `values` by copy so the caller's vector isn't reordered. Odd sizes return the middle element; even sizes average the two middles as `double` to avoid integer truncation. Empty input throws rather than dereferencing out of bounds.

