use std::collections::HashMap;

fn parse_duration(s: &str) -> Result<u64, String> {
    let units: HashMap<char, u64> = [('h', 3600), ('m', 60), ('s', 1)].into_iter().collect();
    let mut total: u64 = 0;
    let mut num = String::new();
    let mut saw_unit = false;

    for c in s.chars() {
        if c.is_ascii_digit() {
            num.push(c);
        } else {
            let unit = units.get(&c)
                .ok_or_else(|| format!("unknown unit '{}'", c))?;
            if num.is_empty() {
                return Err(format!("missing value before '{}'", c));
            }
            let value: u64 = num.parse().map_err(|_| "bad number".to_string())?;
            total = total.checked_add(value.checked_mul(*unit)
                .ok_or("overflow")?).ok_or("overflow")?;
            num.clear();
            saw_unit = true;
        }
    }
    if !num.is_empty() || !saw_unit {
        return Err("trailing digits without unit".to_string());
    }
    Ok(total)
}

fn main() {
    for s in ["1h30m10s", "45s", "2m", "1x", "", "10"] {
        println!("{:?} -> {:?}", s, parse_duration(s));
    }
}
