#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Parse a comma-separated list of ints into out[0..cap-1].
 * Returns the number of values parsed, or -1 on malformed input.
 * Empty fields, overflow, and trailing junk are rejected. */
int parse_int_list(const char *s, int *out, size_t cap) {
    if (s == NULL || out == NULL) return -1;
    size_t n = 0;
    const char *p = s;

    if (*p == '\0') return 0; /* empty string -> zero elements */

    while (1) {
        if (n >= cap) return -1;

        char *end = NULL;
        errno = 0;
        long v = strtol(p, &end, 10);

        if (end == p) return -1;                    /* no digits */
        if (errno == ERANGE || v < INT_MIN || v > INT_MAX) return -1;

        out[n++] = (int)v;
        p = end;

        /* Skip trailing spaces before the delimiter. */
        while (*p == ' ' || *p == '\t') p++;
        if (*p == '\0') break;
        if (*p != ',') return -1;                   /* trailing junk */
        p++;
    }
    return (int)n;
}

int main(void) {
    int buf[4];
    int n = parse_int_list("1, 2,3 , 40", buf, 4);
    if (n != 4 || buf[0] != 1 || buf[3] != 40) { puts("fail: basic"); return 1; }

    if (parse_int_list("", buf, 4) != 0) { puts("fail: empty"); return 1; }
    if (parse_int_list("1,2,", buf, 4) != -1) { puts("fail: trailing comma"); return 1; }
    if (parse_int_list("1,,2", buf, 4) != -1) { puts("fail: empty field"); return 1; }
    if (parse_int_list("99999999999999", buf, 4) != -1) { puts("fail: overflow"); return 1; }
    if (parse_int_list("1,2,3,4,5", buf, 4) != -1) { puts("fail: overflow cap"); return 1; }

    puts("all tests passed");
    return 0;
}
