```python
import functools
import random
import time
from typing import Callable, Tuple, Type


def retry(
    attempts: int = 5,
    base: float = 0.1,
    factor: float = 2.0,
    max_delay: float = 5.0,
    exceptions: Tuple[Type[BaseException], ...] = (Exception,),
    jitter: bool = True,
) -> Callable:
    """Retry a function on `exceptions` with exponential backoff.

    attempts  total number of tries (>= 1)
    base      initial delay in seconds
    factor    multiplier applied after each failure
    max_delay upper bound on any single sleep
    jitter    if True, sleep a uniform random time in [delay/2, delay]
    """
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = base
            last_exc: BaseException | None = None
            for i in range(attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:  # noqa: E722
                    last_exc = exc
                    if i == attempts - 1:
                        break
                    sleep_for = min(delay, max_delay)
                    if jitter:
                        sleep_for = random.uniform(sleep_for / 2, sleep_for)
                    time.sleep(sleep_for)
                    delay *= factor
            raise last_exc  # type: ignore[misc]
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base=0.001, exceptions=(ValueError,))
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return "ok"

    assert flaky() == "ok"
    assert calls["n"] == 3

    @retry(attempts=2, base=0.001)
    def always_fails():
        raise RuntimeError("boom")

    try:
        always_fails()
    except RuntimeError:
        print("raised after retries")
    else:
        raise AssertionError("should have raised")
