#include <cassert>
#include <iostream>
#include <list>
#include <optional>
#include <unordered_map>

class LruCache {
public:
    explicit LruCache(std::size_t capacity) : cap_(capacity) {}

    std::optional<int> get(int key) {
        auto it = map_.find(key);
        if (it == map_.end()) return std::nullopt;
        order_.splice(order_.begin(), order_, it->second);
        return it->second->second;
    }

    void put(int key, int value) {
        if (cap_ == 0) return;
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->second = value;
            order_.splice(order_.begin(), order_, it->second);
            return;
        }
        if (order_.size() == cap_) {
            int evicted = order_.back().first;
            order_.pop_back();
            map_.erase(evicted);
        }
        order_.emplace_front(key, value);
        map_[key] = order_.begin();
    }

private:
    std::size_t cap_;
    std::list<std::pair<int, int>> order_;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> map_;
};

int main() {
    LruCache c(2);
    c.put(1, 10);
    c.put(2, 20);
    assert(c.get(1).value() == 10);   // 1 becomes most recently used
    c.put(3, 30);                     // evicts 2
    assert(!c.get(2).has_value());
    assert(c.get(3).value() == 30);
    c.put(3, 99);                     // update existing
    assert(c.get(3).value() == 99);

    LruCache zero(0);
    zero.put(1, 1);
    assert(!zero.get(1).has_value());

    std::cout << "all tests passed\n";
}
