static void reverse_range(char *s, int i, int j) {
    while (i < j) {
        char t = s[i];
        s[i++] = s[j];
        s[j--] = t;
    }
}

void reverse_words(char *s) {
    int n = (int)strlen(s);
    if (n == 0) return;
    reverse_range(s, 0, n - 1);
    int i = 0;
    while (i < n) {
        while (i < n && isspace((unsigned char)s[i])) i++;
        int start = i;
        while (i < n && !isspace((unsigned char)s[i])) i++;
        reverse_range(s, start, i - 1);
    }
}

