#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity), buf_{} {}

    bool isFull() const { return size_ == cap_; }
    bool isEmpty() const { return size_ == 0; }

    bool push(double v) {
        if (isFull()) return false;
        buf_[tail_] = v;
        tail_ = (tail_ + 1) % cap_;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (isEmpty()) return std::nullopt;
        double v = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

private:
    std::size_t cap_ = 0;
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
    std::array<double, 8> buf_;
};

int main() {
    RingBuffer rb(2);
    rb.push(1.5);
    rb.push(2.5);
    std::cout << rb.isFull() << "\n";
    std::cout << *rb.pop() << "\n";
    std::cout << *rb.pop() << "\n";
    std::cout << rb.isEmpty() << "\n";
}
