    while (std::cin >> token) {
        std::string word = normalize(token);
        if (!word.empty()) ++counts[word];
    }

    std::vector<std::pair<std::string, long>> ranked(counts.begin(), counts.end());
    std::stable_sort(ranked.begin(), ranked.end(),
                     [](const auto& a, const auto& b) { return a.second > b.second; });

    const std::size_t limit = std::min<std::size_t>(3, ranked.size());
    for (std::size_t i = 0; i < limit; ++i) {
        std::cout << ranked[i].first << ' ' << ranked[i].second << '\n';
    }
    return 0;
}
