```rust
pub struct RingBuffer {
    data: Vec<f64>,
    capacity: usize,
    head: usize,
    len: usize,
}

impl RingBuffer {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        RingBuffer { data: vec![0.0; capacity], capacity, head: 0, len: 0 }
    }

    pub fn push(&mut self, value: f64) {
        let idx = (self.head + self.len) % self.capacity;
        if self.len == self.capacity {
            self.head = (self.head + 1) % self.capacity;
            self.data[(self.head + self.len - 1) % self.capacity] = value;
        } else {
            self.data[idx] = value;
            self.len += 1;
        }
    }

    pub fn average(&self) -> Option<f64> {
        if self.len == 0 {
            return None;
        }
        let sum: f64 = self.data[..self.len].iter().sum();
        Some(sum / self.len as f64)
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    rb.push(2.0);
    rb.push(4.0);
    rb.push(6.0);
    assert_eq!(rb.average(), Some(4.0));
    rb.push(8.0); // evicts 2.0
    assert_eq!(rb.average(), Some(6.0));
    println!("ok");
}
