```rust
use std::collections::HashMap;

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();

    for word in text.split(|c: char| !c.is_alphanumeric() && c != '\'') {
        if word.is_empty() {
            continue;
        }
        let key = word.to_lowercase();
        *counts.entry(key).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the cat the dog The CAT a";
    let top = top_words(text, 3);
    for (w, c) in &top {
        println!("{} {}", w, c);
    }

    assert_eq!(top_words("", 5), Vec::<(String, usize)>::new());
    assert_eq!(top[0], ("the".to_string(), 3));
    assert_eq!(top[1], ("cat".to_string(), 2));
    assert_eq!(top[2], ("a".to_string(), 1));
}
```

Splitting on non-alphanumerics keeps contractions like `don't` intact, and `to_lowercase` folds `The` into `the`. The sort key is `(reverse count, word)` so higher counts come first while equal counts fall back to alphabetical order. `truncate(n)` handles `n` larger than the vocabulary without panicking.

```cpp
#include <cassert>
#include <cstdint>
#include <iostream>
#include <utility>

constexpr std::int64_t MOD = 1000000007LL;

std::pair<std::int64_t, std::int64_t> fib_pair(std::int64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    std::int64_t c = a * ((2 * b - a + MOD) % MOD) % MOD;
    std::int64_t d = (a * a + b * b) % MOD;
    if (n & 1) return {d, (c + d) % MOD};
    return {c, d};
}

std::int64_t fib_fast(std::int64_t n) { return fib_pair(n).first; }

std::int64_t fib_slow(std::int64_t n) {
    std::int64_t a = 0, b = 1;
    for (std::int64_t i = 0; i < n; ++i) {
        auto t = (a + b) % MOD;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    for (std::int64_t n = 0; n <= 60; ++n) {
        assert(fib_fast(n) == fib_slow(n));
    }
    std::cout << fib_fast(90) << '\n';
    std::cout << "all checks passed\n";
    return 0;
}
```

`fib_pair(n)` returns `(F(n), F(n+1))`. The `2*b - a` term can go negative before the modulus, so `+MOD` keeps it non-negative. Fast doubling runs in O(log n), so `fib_fast(90)` is instant while a naive loop would also be fine at this scale; the brute-force check pins correctness for the first 61 values.

```rust
fn merge_sorted(a: &[i64], b: &[i64]) -> Vec<i64> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b = [2, 3, 6];
    assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 3, 5, 6, 7]);
    assert_eq!(merge_sorted(&[], &b), vec![2, 3, 6]);
    assert_eq!(merge_sorted(&a, &[]), vec![1, 3, 5, 7]);
    assert!(merge_sorted(&[], &[]).is_empty());
    println!("{:?}", merge_sorted(&a, &b));
}
```

`with_capacity` avoids reallocation, which is the real win here rather than avoiding a scratch buffer. When one slice is exhausted, the remaining tail of the other is already sorted, so `extend_from_slice` appends it in one shot. `<=` on the first comparison makes the merge stable, so equal keys keep `a` before `b`.

```c
#include <ctype.h>
#include <stdio.h>
#include <string.h>

static void reverse(char *s, size_t i, size_t j) {
    while (i < j) {
        char t = s[i];
        s[i++] = s[j];
        s[j--] = t;
    }
}

static void reverse_words(char *s) {
    size_t n = strlen(s);
    if (n == 0) return;

    reverse(s, 0, n - 1);

    size_t i = 0;
    while (i < n) {
        while (i < n && isspace((unsigned char)s[i])) i++;
        size_t start = i;
        while (i < n && !isspace((unsigned char)s[i])) i++;
        if (start < i) {
            reverse(s, start, i - 1);
        }
    }
}

int main(void) {
    char buf[256];

    while (fgets(buf, sizeof buf, stdin)) {
        size_t n = strlen(buf);
        while (n > 0 && (buf[n - 1] == '\n' || buf[n - 1] == '\r')) {
            buf[--n] = '\0';
        }
        reverse_words(buf);
        printf("%s\n", buf);
    }
    return 0;
}
```

`echo "the  quick brown" | ./rev` prints `brown quick  the` — the double space survives as a gap. The whole-string reverse followed by per-word reverse is the standard trick. `isspace` is passed an `unsigned char` cast because a negative `char` is undefined behaviour for ctype functions. Trailing `\r\n` from Windows files is stripped, and a final line without a newline is still processed because `fgets` returns a non-NULL buffer.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int) -> tuple:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end + 1]
```

Expand around each center; each palindrome has a center of one or two chars. O(n^2) time, O(1) space. Unicode works because Python strings index by code point.

