#include <vector>
#include <cassert>

std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else              out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    assert(merge_sorted({}, {}) == std::vector<int>{});
    assert(merge_sorted({1, 3, 5}, {2, 4, 6}) == (std::vector<int>{1, 2, 3, 4, 5, 6}));
    assert(merge_sorted({1, 1}, {1}) == (std::vector<int>{1, 1, 1}));
    assert(merge_sorted({}, {7}) == std::vector<int>{7});
    return 0;
}
```

The `<=` comparison keeps equal elements in a stable order, and `reserve` avoids repeated reallocations.

