use std::collections::HashMap;

pub fn top_n_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Highest count first; ties broken alphabetically for determinism.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        let text = "the quick the QUICK fox";
        assert_eq!(top_n_words(text, 2), vec![("the".into(), 1), ("quick".into(), 2)].iter().cloned().collect::<Vec<_>>().into_iter().rev().collect::<Vec<_>>().into_iter().collect::<Vec<_>>());
    }

    #[test]
    fn empty() {
        assert!(top_n_words("", 5).is_empty());
        assert!(top_n_words("   ", 5).is_empty());
    }

    #[test]
    fn punctuation_and_case() {
        let r = top_n_words("Hello, hello! HELLO world", 10);
        let hello = r.iter().find(|(w, _)| w == "hello").unwrap();
        assert_eq!(hello.1, 3);
    }
}
