#include <string.h>
#include <assert.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t n = strlen(s);
    if (n < 2) return;
    for (size_t i = 0, j = n - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    assert(strcmp(a, "olleh") == 0);

    char b[] = "";
    reverse_in_place(b);
    assert(strcmp(b, "") == 0);

    char c[] = "x";
    reverse_in_place(c);
    assert(strcmp(c, "x") == 0);

    char d[] = "ab";
    reverse_in_place(d);
    assert(strcmp(d, "ba") == 0);

    reverse_in_place(NULL); /* must not crash */
    return 0;
}
