```rust
/// Returns (F(n), F(n+1)) for n >= 0 using fast doubling.
fn fib_pair(n: u128) -> (u128, u128) {
    if n == 0 {
        return (0, 1);
    }
    let (a, b) = fib_pair(n / 2);
    let c = a.wrapping_mul(2u128.wrapping_mul(b).wrapping_sub(a));
    let d = a.wrapping_mul(a).wrapping_add(b.wrapping_mul(b));
    if n % 2 == 0 {
        (c, d)
    } else {
        (d, c.wrapping_add(d))
    }
}

pub fn nth_fib(n: u128) -> u128 {
    fib_pair(n).0
}

