class File {
public:
    explicit File(const char* path, const char* mode = "r") : handle_(std::fopen(path, mode)) {
        if (!handle_) throw std::runtime_error("failed to open file");
    }

    ~File() {
        if (handle_) std::fclose(handle_);
    }

    File(const File&) = delete;
    File& operator=(const File&) = delete;

    File(File&& other) noexcept : handle_(other.handle_) {
        other.handle_ = nullptr;
    }

    File& operator=(File&& other) noexcept {
        if (this != &other) {
            if (handle_) std::fclose(handle_);
            handle_ = other.handle_;
            other.handle_ = nullptr;
        }
        return *this;
    }

    std::FILE* get() const { return handle_; }

private:
    std::FILE* handle_;
};
