#include <cstdlib>
#include <iostream>
#include <vector>

std::vector<int> sieve(int n) {
    std::vector<int> primes;
    if (n < 2) return primes;
    std::vector<bool> is_prime(n + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int p = 2; static_cast<long long>(p) * p <= n; ++p) {
        if (!is_prime[p]) continue;
        for (long long m = static_cast<long long>(p) * p; m <= n; m += p) {
            is_prime[static_cast<int>(m)] = false;
        }
    }
    for (int i = 2; i <= n; ++i) {
        if (is_prime[i]) primes.push_back(i);
    }
    return primes;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "usage: sieve N\n";
        return 1;
    }
    int n = std::atoi(argv[1]);
    if (n < 0) {
        std::cerr << "N must be non-negative\n";
        return 1;
    }
    for (int p : sieve(n)) std::cout << p << '\n';
    return 0;
}
```
