#include <iostream>
#include <vector>

std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        // <= keeps stability for equal elements from a.
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5};
    std::vector<int> b{2, 4, 6};
    std::vector<int> merged = merge_sorted(a, b);
    for (int v : merged) std::cout << v << ' ';
    std::cout << '\n';

    // Empty inputs are handled by the reserve/push_back loops.
    std::vector<int> empty;
    std::vector<int> only_b{7, 8};
    for (int v : merge_sorted(empty, only_b)) std::cout << v << ' ';
    std::cout << '\n';
    return 0;
}
