```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

struct Node *reverse(struct Node *head) {
    struct Node *prev = NULL;
    while (head != NULL) {
        struct Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static struct Node *push(struct Node *head, int value) {
    struct Node *n = malloc(sizeof *n);
    if (n == NULL) {
        return head;
    }
    n->value = value;
    n->next = head;
    return n;
}

static void print_list(struct Node *head) {
    for (; head != NULL; head = head->next) {
        printf("%d ", head->value);
    }
    putchar('\n');
}

int main(void) {
    struct Node *head = NULL;
    for (int i = 1; i <= 5; i++) head = push(head, i);
    print_list(head);           /* 5 4 3 2 1 */
    head = reverse(head);
    print_list(head);           /* 1 2 3 4 5 */

    /* Empty list reverses to NULL, not a crash. */
    head = reverse(NULL);
    if (head != NULL) return 1;

    while (head != NULL) {
        struct Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
```

The loop relinks one node per iteration by saving `next` before overwriting it. `reverse(NULL)` returns `NULL` cleanly.

