import hashlib
import os
from collections import defaultdict

def hash_file(path: str, chunk: int = 1 << 20) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as fh:
        while True:
            block = fh.read(chunk)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()

def find_duplicates(root: str):
    by_size = defaultdict(list)
    for dirpath, _dirs, files in os.walk(root):
        for name in files:
            path = os.path.join(dirpath, name)
            try:
                by_size[os.path.getsize(path)].append(path)
            except OSError:
                # Skip files that vanish or are unreadable mid-walk.
                continue

    by_hash = defaultdict(list)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue  # A unique size cannot collide.
        for path in paths:
            try:
                by_hash[hash_file(path)].append(path)
            except OSError:
                continue
    return [sorted(paths) for paths in by_hash.values() if len(paths) > 1]

if __name__ == "__main__":
    import sys
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    for group in find_duplicates(target):
        print("---")
        for path in group:
            print(path)
