```rust
fn binary_search<T: Ord>(haystack: &[T], needle: &T) -> Option<usize> {
    let mut lo: usize = 0;
    let mut hi: usize = haystack.len(); // exclusive upper bound
    while lo < hi {
        let mid = lo + (hi - lo) / 2; // avoids overflow on large slices
        match haystack[mid].cmp(needle) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => return Some(mid),
        }
    }
    None
}

fn main() {
    let data = [1, 3, 5, 7, 9, 11];
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &11), Some(5));
    assert_eq!(binary_search(&data, &7), Some(3));
    assert_eq!(binary_search(&data, &4), None);

    let empty: [i32; 0] = [];
    assert_eq!(binary_search(&empty, &5), None);

    let words = ["apple", "fig", "kiwi"];
    assert_eq!(binary_search(&words, &"fig"), Some(1));
    println!("all assertions passed");
}
```

Using `hi` as an exclusive bound keeps the loop invariant clean. `lo + (hi - lo) / 2` cannot overflow even when `hi` is `usize::MAX`.

```cpp
#include <algorithm>
#include <iostream>
#include <map>
#include <string>

// Counts Unicode code points as bytes of a UTF-8 string, decoded naively.
static void count_codepoints(const std::string& s, std::map<unsigned int, int>& counts) {
    size_t i = 0;
    while (i < s.size()) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        unsigned int cp = 0;
        size_t extra = 0;
        if (c < 0x80) { cp = c; extra = 0; }
        else if ((c & 0xE0) == 0xC0) { cp = c & 0x1F; extra = 1; }
        else if ((c & 0xF0) == 0xE0) { cp = c & 0x0F; extra = 2; }
        else if ((c & 0xF8) == 0xF0) { cp = c & 0x07; extra = 3; }
        else { cp = 0xFFFD; extra = 0; } // invalid byte -> replacement
        for (size_t k = 1; k <= extra && i + k < s.size(); ++k) {
            cp = (cp << 6) | (static_cast<unsigned char>(s[i + k]) & 0x3F);
        }
        counts[cp]++;
        i += extra + 1;
    }
}

bool are_anagrams(const std::string& a, const std::string& b) {
    std::map<unsigned int, int> ca, cb;
    count_codepoints(a, ca);
    count_codepoints(b, cb);
    return ca == cb;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << are_anagrams("listen", "silent") << '\n';      // true
    std::cout << are_anagrams("caf\xC3\xA9", "f\xC3\xA9ac") << '\n'; // true
    std::cout << are_anagrams("abc", "ab") << '\n';            // false
    std::cout << are_anagrams("", "") << '\n';                  // true
    return 0;
}
```

Decoding UTF-8 in the loop lets multibyte characters count as single code points. A proper implementation would use ICU, but this covers the common cases without extra deps.

