```c
#include <stddef.h>
#include <stdio.h>

/* Return the index of target in the sorted array, or -1 if absent. */
int binary_search(const int *arr, size_t n, int target) {
    size_t lo = 0;
    size_t hi = n;                 /* half-open range [lo, hi) */

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;   /* no overflow */
        if (arr[mid] == target) {
            return (int)mid;
        } else if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

int main(void) {
    const int data[] = {-5, 0, 3, 7, 7, 11, 42};
    const size_t n = sizeof data / sizeof data[0];

    printf("%d\n", binary_search(data, n, 7));    /* 3 (first hit) */
    printf("%d\n", binary_search(data, n, -5));   /* 0 */
    printf("%d\n", binary_search(data, n, 100));  /* -1 */
    printf("%d\n", binary_search(data, 0, 1));    /* -1, empty array */
    return 0;
}
```
Using the half-open range `[lo, hi)` and computing `mid` as `lo + (hi - lo) / 2` avoids both off-by-one errors at the boundaries and signed overflow on large indices.

