#include <iostream>
#include <optional>
#include <string_view>
#include <system_error>

// Parse an integral value from text. Returns nullopt on empty input,
// trailing garbage, or overflow.
template <typename T>
std::optional<T> parse_int(std::string_view text) {
    if (text.empty()) {
        return std::nullopt;
    }
    T value{};
    const char* begin = text.data();
    const char* end = begin + text.size();
    auto [ptr, ec] = std::from_chars(begin, end, value);
    if (ec != std::errc{} || ptr != end) {
        return std::nullopt;            // error code or unconsumed chars
    }
    return value;
}

int main() {
    std::cout << parse_int<int>("42").value_or(-1) << '\n';          // 42
    std::cout << parse_int<int>("").has_value() << '\n';            // 0
    std::cout << parse_int<int>("12x").has_value() << '\n';         // 0
    std::cout << parse_int<long>("99999999999999999999").has_value(); // 0
    return 0;
}
```
`std::from_chars` is locale-independent and does not throw, and checking `ptr != end` catches strings like `"12x"` that a naive parser would silently accept as 12.

