```c
#include <stdio.h>
#include <string.h>

/* Reverse the bytes of each UTF-8 code point, leaving continuation
 * bytes adjacent to their lead byte. Returns 0 on invalid UTF-8. */
static int reverse_utf8(char *s) {
    size_t len = strlen(s);
    size_t i = 0, j = len;

    while (i < j) {
        /* find start of the code point at j-1 */
        size_t end = j;
        while (j > i && ((unsigned char)s[j - 1] & 0xC0) == 0x80) {
            j--;   /* skip continuation bytes */
        }
        if (j == i) {
            return -1;   /* malformed: no lead byte */
        }
        size_t start = j - 1;

        if (start < i) {
            return -1;
        }

        /* rotate the [start, end) chunk to the front */
        char tmp[8];
        size_t clen = end - start;
        if (clen > sizeof tmp) {
            return -1;
        }
        memcpy(tmp, s + start, clen);
        memmove(s + i + clen, s + i, start - i);
        memcpy(s + i, tmp, clen);

        i += clen;
        j = len - clen;
        len = j + clen; /* keep len stable for the next iteration */
    }
    return 0;
}

int main(void) {
    char buf[] = "h\xC3\xA9llo \xE2\x82\xAC";  /* héllo € */
    if (reverse_utf8(buf) == 0) {
        printf("%s\n", buf);
    } else {
        fprintf(stderr, "invalid UTF-8\n");
    }
    return 0;
}
```
Reversing bytes alone corrupts UTF-8 because continuation bytes would get separated from their lead byte. This version moves whole code points, and rejects malformed sequences instead of producing garbage.

