#include <stdio.h>
#include <string.h>

/* Reverse a NUL-terminated string in place. Returns s for chaining. */
char *reverse_in_place(char *s)
{
    if (s == NULL)
        return NULL;

    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0)
        return s;          /* empty string is already reversed */
    j--;                    /* point at last character */

    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
    return s;
}

int main(void)
{
    char buf[] = "hello world";
    puts(reverse_in_place(buf));   /* dlrow olleh */

    char empty[] = "";
    puts(reverse_in_place(empty)); /* empty line */

    char one[] = "x";
    puts(reverse_in_place(one));   /* x */
    return 0;
}
