/// Longest common prefix of `words`, compared on Unicode scalar values
/// so multi-byte characters are never split mid-codepoint.
pub fn longest_common_prefix(words: &[&str]) -> String {
    let first = match words.first() {
        Some(w) => *w,
        None => return String::new(),
    };

    let mut end = first.len();
    for other in &words[1..] {
        let common = first
            .chars()
            .zip(other.chars())
            .take_while(|(a, b)| a == b)
            .map(|(a, _)| a.len_utf8())
            .sum::<usize>();
        if common < end {
            end = common;
        }
        if end == 0 {
            break;
        }
    }
    first[..end].to_string()
}

fn main() {
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["café", "café au lait"]), "café");
    assert_eq!(longest_common_prefix(&["", "abc"]), "");
    println!("ok");
}
