#include <stddef.h>

/* classic binary search; returns index of key or -1 if absent */
long binary_search(const int *arr, size_t n, int key)
{
    if (arr == NULL)
        return -1;

    size_t lo = 0;
    size_t hi = n;

    while (lo < hi) {
        /* mid computed without overflow on 32-bit size_t */
        size_t mid = lo + (hi - lo) / 2;
        if (arr[mid] == key)
            return (long)mid;
        if (arr[mid] < key)
            lo = mid + 1;
        else
            hi = mid;
    }
    return -1;
}

#include <stdio.h>
int main(void)
{
    int a[] = {1, 3, 5, 7, 9, 11};
    printf("%ld\n", binary_search(a, 6, 7));   /* 3 */
    printf("%ld\n", binary_search(a, 6, 8));   /* -1 */
    printf("%ld\n", binary_search(a, 6, 1));   /* 0 */
    printf("%ld\n", binary_search(NULL, 0, 5));/* -1 */
