bool parse_ints(const std::string& line, std::vector<int>& out, std::string& err) {
    out.clear();
    std::istringstream ss(line);
    std::string tok;
    while (std::getline(ss, tok, ',')) {
        size_t a = tok.find_first_not_of(" \t");
        size_t b = tok.find_last_not_of(" \t");
        if (a == std::string::npos) { err = "empty token"; return false; }
        std::string t = tok.substr(a, b - a + 1);
        size_t pos = 0;
        try {
            int v = std::stoi(t, &pos);
            if (pos != t.size()) { err = "trailing chars in '" + t + "'"; return false; }
            out.push_back(v);
        } catch (...) {
            err = "not an integer: '" + t + "'";
            return false;
        }
    }
    return true;
}

int main() {
    std::vector<int> v;
    std::string err;
    if (!parse_ints(" 1, 2,3 , 42 ", v, err)) { std::cerr << err << "\n"; return 1; }
    for (int n : v) std::cout << n << " ";
    std::cout << "\n";
    if (parse_ints("1,,2", v, err)) return 1;
    std::cout << "rejected: " << err << "\n";
    return 0;
