#include <stddef.h>
#include <stdio.h>

/* Returns the length of the longest run; writes the repeated byte to *out_byte
   when out_byte is not NULL. Returns 0 for NULL or empty input. */
size_t longest_run(const unsigned char *buf, size_t len, unsigned char *out_byte) {
    if (buf == NULL || len == 0) {
        return 0;
    }
    size_t best = 1, cur = 1;
    unsigned char best_byte = buf[0];
    for (size_t i = 1; i < len; i++) {
        if (buf[i] == buf[i - 1]) {
            cur++;
        } else {
            cur = 1;
        }
        if (cur > best) {
            best = cur;
            best_byte = buf[i];
        }
    }
    if (out_byte) {
        *out_byte = best_byte;
    }
    return best;
}

int main(void) {
    unsigned char b;
    const unsigned char data[] = {1, 7, 7, 7, 2, 2, 3};
    size_t n = longest_run(data, sizeof data, &b);
    if (n != 3 || b != 7) {
        fprintf(stderr, "fail: n=%zu b=%u\n", n, b);
        return 1;
    }
    if (longest_run(NULL, 5, &b) != 0) {
        return 1;
    }
    const unsigned char empty[] = {0};
    if (longest_run(empty, 0, &b) != 0) {
        return 1;
    }
    printf("ok\n");
    return 0;
}
