// Returns the number of characters in the longest palindromic substring.
std::size_t longest_palindrome_length(const std::string& s) {
    if (s.empty()) {
        return 0;
    }
    std::size_t best = 1;
    auto expand = [&](std::size_t left, std::size_t right) {
        while (left < s.size() && right > 0 && s[left] == s[right - 1]) {
            --left;
            ++right;
        }
        return right - left - 2;
    };
    for (std::size_t i = 0; i < s.size(); ++i) {
        best = std::max(best, expand(i, i + 1)); // odd length
        best = std::max(best, expand(i, i + 2)); // even length
    }
    return best;
}

int main() {
    if (longest_palindrome_length("") != 0) return 1;
    if (longest_palindrome_length("a") != 1) return 1;
    if (longest_palindrome_length("forgeeksskeegfor") != 10) return 1;
    if (longest_palindrome_length("abacaba") != 7) return 1;
    std::cout << "ok\n";
    return 0;
}
