#include <stdbool.h>
#include <stdio.h>

typedef struct {
    int *data;
    size_t cap, head, len;
} Ring;

static void ring_init(Ring *r, int *storage, size_t cap) {
    r->data = storage;
    r->cap = cap;
    r->head = 0;
    r->len = 0;
}

static bool ring_push(Ring *r, int v) {
    if (r->len == r->cap) {
        return false;
    }
    r->data[(r->head + r->len) % r->cap] = v;
    r->len++;
    return true;
}

static bool ring_pop(Ring *r, int *out) {
    if (r->len == 0) {
        return false;
    }
    *out = r->data[r->head];
    r->head = (r->head + 1) % r->cap;
    r->len--;
    return true;
}

int main(void) {
    int storage[3];
    Ring r;
    ring_init(&r, storage, 3);
    if (!ring_push(&r, 10) || !ring_push(&r, 20) || !ring_push(&r, 30)) return 1;
    if (ring_push(&r, 40)) return 1; /* full */
    int v;
    if (!ring_pop(&r, &v) || v != 10) return 1;
    if (!ring_push(&r, 40)) return 1;
    if (!ring_pop(&r, &v) || v != 20) return 1;
    if (!ring_pop(&r, &v) || v != 30) return 1;
    if (!ring_pop(&r, &v) || v != 40) return 1;
    if (ring_pop(&r, &v)) return 1; /* empty */
    printf("ok\n");
    return 0;
}
