template <typename T, typename Cmp>
std::optional<std::size_t> binary_search(const std::vector<T>& v, const T& key, Cmp cmp) {
    std::size_t lo = 0, hi = v.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        int c = cmp(v[mid], key);
        if (c == 0) return mid;
        if (c < 0) lo = mid + 1;
        else hi = mid;
    }
    return std::nullopt;
}

int main() {
