    auto asc = [](int a, int b) { return (a < b) ? -1 : (a > b ? 1 : 0); };
    auto r = binary_search(v, 7, asc);
    std::cout << (r ? std::to_string(*r) : "none") << "\n";
    auto miss = binary_search(v, 4, asc);
    std::cout << (miss ? std::to_string(*miss) : "none") << "\n";
