#include <stdio.h>
#include <string.h>
#include <stdbool.h>

static bool is_open(char c) { return c == '(' || c == '[' || c == '{'; }

static char closer_for(char c) {
    switch (c) {
        case '(': return ')';
        case '[': return ']';
        default:  return '}';
    }
}

bool balanced(const char *s) {
    char stack[256];
    size_t top = 0;
    for (; *s; ++s) {
        if (is_open(*s)) {
            if (top == sizeof(stack)) return false;
            stack[top++] = closer_for(*s);
        } else if (*s == ')' || *s == ']' || *s == '}') {
            if (top == 0 || stack[--top] != *s) return false;
        }
    }
    return top == 0;
}

int main(void) {
    const char *tests[] = {"({[]})", "([)]", "", "(((", "a(b)c"};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); ++i)
        printf("%s -> %s\n", tests[i], balanced(tests[i]) ? "ok" : "bad");
    return 0;
}
```

The stack stores the expected closer; a mismatch or leftover entry means `false`. Non-bracket characters are skipped, and the empty string is balanced.

