```cpp
#include <cstddef>
#include <cstdio>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(new int[capacity]), cap_(capacity), head_(0), tail_(0), size_(0) {}
    ~RingBuffer() { delete[] buf_; }

    RingBuffer(const RingBuffer&) = delete;
    RingBuffer& operator=(const RingBuffer&) = delete;

    bool full() const { return size_ == cap_; }
    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

    bool push(int value) {
        if (full()) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % cap_;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

private:
    int* buf_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t tail_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    if (!rb.empty()) return 1;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 2;
    if (rb.push(4)) return 3;                 // must reject when full
    if (rb.pop() != 1 || rb.pop() != 2) return 4;
    if (!rb.push(4) || !rb.push(5)) return 5; // wrap-around
    if (rb.pop() != 3 || rb.pop() != 4 || rb.pop() != 5) return 6;
    if (rb.pop().has_value()) return 7;       // empty again
    std::puts("ok");
    return 0;
}
```
Uses the classic one-slot-of-emptiness-free design with an explicit `size_` counter, so capacity is exactly `capacity` rather than `capacity - 1`.

