#include <cctype>
#include <cerrno>
#include <cstdlib>
#include <iostream>
#include <optional>
#include <string>

std::optional<long long> parse_int(const std::string& s) {
    if (s.empty()) return std::nullopt;
    std::size_t i = 0;
    bool neg = false;
    if (s[i] == '+' || s[i] == '-') {
        neg = (s[i] == '-');
        ++i;
        if (i == s.size()) return std::nullopt;
    }
    long long acc = 0;
    for (; i < s.size(); ++i) {
        char c = s[i];
        if (!std::isdigit(static_cast<unsigned char>(c))) return std::nullopt;
        int d = c - '0';
        // Check before multiplying so overflow is detected exactly.
        if (acc > (9223372036854775807LL - d) / 10) {
            if (neg && acc == (9223372036854775800LL - 7 + 1) / 10) {
                // handled below for LLONG_MIN boundary
            }
            if (neg && (acc == 922337203685477580LL) &&
                (d <= 8)) {
                acc = acc * 10 + d;
                continue;
            }
            return std::nullopt;
        }
        acc = acc * 10 + d;
    }
    return neg ? -acc : acc;
}

int main() {
    if (parse_int("123") != 123) return 1;
    if (parse_int("-42") != -42) return 2;
    if (parse_int("+7") != 7) return 3;
    if (parse_int("0") != 0) return 4;
    if (parse_int("").has_value()) return 5;
    if (parse_int("12a").has_value()) return 6;
    if (parse_int("-").has_value()) return 7;
    if (parse_int("99999999999999999999").has_value()) return 8; // overflow
    std::cout << "ok\n";
}
```
