```rust
fn eval_rpn(tokens: &[&str]) -> Result<i64, String> {
    let mut stack: Vec<i64> = Vec::new();
    for tok in tokens {
        match *tok {
            "+" | "-" | "*" | "/" => {
                let b = stack.pop().ok_or_else(|| format!("missing operand for {tok}"))?;
                let a = stack.pop().ok_or_else(|| format!("missing operand for {tok}"))?;
                let v = match *tok {
                    "+" => a.checked_add(b),
                    "-" => a.checked_sub(b),
                    "*" => a.checked_mul(b),
                    _ => {
                        if b == 0 {
                            return Err("division by zero".to_string());
                        }
                        Some(a / b)
                    }
                }
                .ok_or_else(|| format!("integer overflow on {tok}"))?;
                stack.push(v);
            }
            _ => {
                let n: i64 = tok
                    .parse()
                    .map_err(|_| format!("bad token: {tok}"))?;
                stack.push(n);
            }
        }
    }
    if stack.len() != 1 {
        return Err(format!("leftover operands: stack len {}", stack.len()));
    }
    Ok(stack[0])
}

fn main() {
    assert_eq!(eval_rpn(&["3", "4", "+"]), Ok(7));
    assert_eq!(eval_rpn(&["5", "1", "2", "+", "*"]), Ok(15));
    assert_eq!(eval_rpn(&["10", "3", "-"]), Ok(7));
    assert!(eval_rpn(&["1", "0", "/"]).is_err());
    assert!(eval_rpn(&["+"]).is_err());
    assert!(eval_rpn(&["1", "2"]).is_err()); // leftover
    assert!(eval_rpn(&[]).is_err());
    println!("ok");
}
```
Uses `checked_*` so overflow is an error rather than a silent wrap, and both operand underflow and leftover values are reported distinctly.

