use std::fs;
use std::io;

fn longest_line(path: &str) -> io::Result<Option<String>> {
    let content = fs::read_to_string(path)?;
    let mut best: Option<String> = None;
    let mut best_len = 0usize;
    for line in content.lines() {
        // chars().count() counts code points, not UTF-8 bytes.
        let len = line.chars().count();
        if best.is_none() || len > best_len {
            best = Some(line.to_string());
            best_len = len;
        }
    }
    Ok(best)
}

fn main() -> io::Result<()> {
    // Empty file -> None (no lines at all).
    fs::write("/tmp/xt_empty.txt", "")?;
    assert!(longest_line("/tmp/xt_empty.txt")?.is_none());

    // Unicode: emoji count as 1 char each, not 4 bytes.
    fs::write("/tmp/xt_lines.txt", "hi\n\u{1F98A}\u{1F98A}\u{1F98A}\nbye")?;
    assert_eq!(longest_line("/tmp/xt_lines.txt")?.as_deref(), Some("\u{1F98A}\u{1F98A}\u{1F98A}"));

    // Missing file surfaces the io::Error to the caller.
    assert!(longest_line("/tmp/xt_nope.txt").is_err());
    println!("ok");
    Ok(())
}
