template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << std::boolalpha << rb.empty() << "\n";  // true
    rb.push(10); rb.push(20); rb.push(30);
    std::cout << rb.push(40) << "\n";  // false, full
    std::cout << rb.pop().value_or(-1) << "\n";  // 10
}
