```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t len;
    size_t cap;
} Stack;

static int resize(Stack *s, size_t new_cap) {
    int *tmp = realloc(s->data, new_cap * sizeof(int));
    if (!tmp) return 0;
    s->data = tmp;
    s->cap = new_cap;
    return 1;
}

int push(Stack *s, int v) {
    if (s->len == s->cap) {
        size_t next = s->cap ? s->cap * 2 : 4;
        if (!resize(s, next)) return 0;
    }
    s->data[s->len++] = v;
    return 1;
}

int pop(Stack *s, int *out) {
    if (s->len == 0) return 0;
    *out = s->data[--s->len];
    return 1;
}

int peek(const Stack *s, int *out) {
    if (s->len == 0) return 0;
    *out = s->data[s->len - 1];
    return 1;
}

void destroy(Stack *s) {
    free(s->data);
    s->data = NULL;
    s->len = s->cap = 0;
}

int main(void) {
    Stack s = {0};
    for (int i = 0; i < 10; ++i) push(&s, i * i);
    int v;
    while (pop(&s, &v)) printf("%d\n", v);
    destroy(&s);
    return 0;
}
```
The first push allocates a capacity of 4; later pushes double it, so appends stay amortized O(1). `pop` and `peek` return 0 on an empty stack rather than reading past the buffer.

