#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    void push(T value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return items_.size() < cap_; });
        items_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return !items_.empty(); });
        T value = std::move(items_.front());
        items_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

private:
    std::queue<T> items_;
    std::size_t cap_;
    std::mutex mu_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
};
```
Both waits use a predicate so they correctly re-check the condition after a spurious wakeup. The lock is released before `notify_one` so the woken thread does not immediately block on the mutex.

