```python
import collections
import threading


class BoundedQueue:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._items = collections.deque()
        self._cap = capacity
        self._lock = threading.Condition()

    def put(self, item):
        with self._lock:
            while len(self._items) >= self._cap:
                self._lock.wait()
            self._items.append(item)
            self._lock.notify_all()

    def get(self):
        with self._lock:
            while not self._items:
                self._lock.wait()
            item = self._items.popleft()
            self._lock.notify_all()
            return item

    def __len__(self):
        with self._lock:
            return len(self._items)


if __name__ == "__main__":
    q = BoundedQueue(2)
    q.put(1); q.put(2)
    assert q.get() == 1
    assert len(q) == 1
    try:
        BoundedQueue(0)
    except ValueError:
        pass
    print("ok")
```
`while` loops around `wait()` (not `if`) guard against spurious wakeups, and `notify_all` avoids lost-wakeup stalls when several threads share the queue.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t len;
    size_t cap;
} Vec;

static int vec_grow(Vec *v) {
    size_t new_cap = v->cap ? v->cap * 2 : 4;
    int *tmp = realloc(v->data, new_cap * sizeof(int));
    if (!tmp) return -1;
    v->data = tmp;
    v->cap = new_cap;
    return 0;
}

int vec_push(Vec *v, int value) {
    if (v->len == v->cap && vec_grow(v) != 0) return -1;
    v->data[v->len++] = value;
    return 0;
}

int vec_get(const Vec *v, size_t i, int *out) {
    if (i >= v->len) return -1;
    *out = v->data[i];
    return 0;
}

void vec_free(Vec *v) {
    free(v->data);
    v->data = NULL;
    v->len = v->cap = 0;
}

int main(void) {
    Vec v = {0};
    for (int i = 0; i < 10; i++) {
        if (vec_push(&v, i * i) != 0) { fprintf(stderr, "oom\n"); return 1; }
    }
    int out = 0;
    printf("len=%zu cap>=%zu\n", v.len, v.cap);
    if (vec_get(&v, 9, &out) == 0) printf("v[9]=%d\n", out);
    printf("oob returns %d\n", vec_get(&v, 100, &out));
    vec_free(&v);
    return 0;
}
```
`realloc` into a temporary so a failed allocation does not leak or corrupt the original pointer, and `vec_get` reports out-of-bounds via its return code rather than reading past the end.

```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start = end = 0

    def expand(left: int, right: int) -> int:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return right - left - 1

    for i in range(len(s)):
        odd = expand(i, i)
        even = expand(i, i + 1)
        best = max(odd, even)
        if best > end - start:
            start = i - (best - 1) // 2
            end = i + best // 2

    return s[start:end + 1]
```

Expand around every center, keeping the widest span; empty input returns the empty string.

