fn check(s: &str) -> Result<(), usize> {
    let mut stack: Vec<(char, usize)> = Vec::new();
    for (i, c) in s.char_indices() {
        match c {
            '(' | '[' | '{' => stack.push((c, i)),
            ')' | ']' | '}' => {
                let want = match c { ')' => '(', ']' => '[', _ => '{' };
                match stack.pop() {
                    Some((open, _)) if open == want => {}
                    _ => return Err(i),
                }
            }
            _ => {}
        }
    }
    match stack.first() {
        Some(&(_, i)) => Err(i),
        None => Ok(()),
    }
}

fn main() {
    assert_eq!(check("a(b[c]{d})e"), Ok(()));
    assert_eq!(check("(]"), Err(1));
    assert_eq!(check("(("), Err(0));
    assert_eq!(check(""), Ok(()));
    println!("ok");
}
