use std::cmp::Ordering;

pub fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut low = 0usize;
    let mut high = slice.len();
    while low < high {
        let mid = low + (high - low) / 2;
        match slice[mid].cmp(target) {
            Ordering::Equal => return Some(mid),
            Ordering::Less => low = mid + 1,
            Ordering::Greater => high = mid,
        }
    }
    None
}

fn main() {
    let nums = [1, 3, 3, 3, 7, 9];
    let found = binary_search(&nums, &3).unwrap();
    assert_eq!(nums[found], 3);
    assert_eq!(binary_search(&nums, &1), Some(0));
    assert_eq!(binary_search(&nums, &9), Some(5));
    assert_eq!(binary_search(&nums, &4), None);
    assert_eq!(binary_search::<i32>(&[], &1), None);
    println!("ok");
}
```

`low + (high - low) / 2` avoids overflow on huge slices. The half-open `[low, high)` range keeps the loop simple and terminates when the range empties.

