WHITE, GRAY, BLACK = 0, 1, 2


def has_cycle(graph: dict) -> bool:
    color = {node: WHITE for node in graph}

    def dfs(node: object) -> bool:
        color[node] = GRAY
        for nxt in graph.get(node, ()):
            if color.get(nxt, WHITE) == GRAY:
                return True
            if color.get(nxt, WHITE) == WHITE and dfs(nxt):
                return True
        color[node] = BLACK
        return False

    for node in graph:
        if color[node] == WHITE and dfs(node):
            return True
    return False


if __name__ == "__main__":
    assert has_cycle({0: [1], 1: [2], 2: [0]}) is True
    assert has_cycle({0: [1], 1: [2], 2: []}) is False
    assert has_cycle({}) is False
    assert has_cycle({0: [0]}) is True          # self-loop
    assert has_cycle({"a": ["b"], "b": ["a"]}) is True
    print("ok")
```

A back edge to a GRAY node means a cycle. `color.get(nxt, WHITE)` treats nodes reached through edges but absent from the dict as unvisited.

