    totals = defaultdict(float)
    reader = csv.reader(io.StringIO(text))
    header = next(reader, None)
    if header is None:
        return {}
    if [c.strip().lower() for c in header] != ["name", "amount"]:
        raise ValueError(f"unexpected header: {header}")

    for lineno, row in enumerate(reader, start=2):
        if len(row) != 2:
            print(f"skip line {lineno}: expected 2 fields, got {len(row)}")
            continue
        name, raw = row[0].strip(), row[1].strip()
        if not name:
            print(f"skip line {lineno}: empty name")
            continue
        try:
            totals[name] += float(raw)
        except ValueError:
            print(f"skip line {lineno}: bad amount {raw!r}")
    return dict(totals)


if __name__ == "__main__":
    assert sum_by_name(SAMPLE) == {"alice": 15.0, "bob": 5.0}
    assert sum_by_name("") == {}
    print("ok")
