```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *curr = head;
    while (curr != NULL) {
        Node *next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

void print_list(Node *head) {
    for (Node *n = head; n; n = n->next) {
        printf("%d", n->value);
        if (n->next) printf(" -> ");
    }
    printf("\n");
}

void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 5; i >= 1; i--) head = push(head, i);
    printf("before: ");
    print_list(head);
    head = reverse(head);
    printf("after:  ");
    print_list(head);
    free_list(head);
    return 0;
}
```

`reverse` iterates once, flipping each `next` pointer to point backward and advancing `prev`/`curr`. Memory is fully released by `free_list`, and the empty-list case returns `NULL` correctly since `prev` starts as `NULL`.

