```rust
fn binary_search(nums: &[i64], target: i64) -> Option<usize> {
    let mut low: usize = 0;
    let mut high: usize = nums.len();
    while low < high {
        let mid = low + (high - low) / 2;
        if nums[mid] == target {
            return Some(mid);
        } else if nums[mid] < target {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    None
}

fn main() {
    let data = vec![-9, -3, 0, 4, 7, 7, 12, 30];
    for target in [-9, 0, 7, 31] {
        match binary_search(&data, target) {
            Some(i) => println!("found {} at index {}", target, i),
            None => println!("{} not found", target),
        }
    }
    assert_eq!(binary_search(&[], 1), None);
    println!("all checks passed");
}
```

The loop uses a half-open range `[low, high)` and `low + (high - low) / 2` to avoid overflow, ending when the range is empty. Duplicates are fine: it returns the index of whichever matching element the probe lands on. The empty-slice case returns `None` because the loop never executes.

```python
from functools import lru_cache


@lru_cache(maxsize=None)
def fib(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


def main() -> None:
    terms = [fib(i) for i in range(20)]
    print(terms)

    # Each term from index 2 must equal the sum of the two before it.
    for i in range(2, len(terms)):
        assert terms[i] == terms[i - 1] + terms[i - 2], i

    # fib(n + 1) * fib(n - 1) - fib(n) ** 2 alternates sign as (-1) ** n.
    for n in range(1, 19):
        identity = terms[n + 1] * terms[n - 1] - terms[n] ** 2
        assert identity == (-1) ** n, (n, identity)
    print("all checks passed")


if __name__ == "__main__":
    main()
```

`lru_cache` turns the naive recursion into O(n) since each value is computed once. The first assertion is the defining recurrence; the second is Cassini's identity, which is a strong independent check that catches off-by-one errors. Negative input raises instead of looping forever.

