std::vector<int> merge_unique(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::merge(a.begin(), a.end(), b.begin(), b.end(), std::back_inserter(out));
    out.erase(std::unique(out.begin(), out.end()), out.end());
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5, 7};
    std::vector<int> b{2, 3, 4, 7, 9};
    std::vector<int> merged = merge_unique(a, b);
    for (size_t i = 0; i < merged.size(); ++i) {
        std::cout << merged[i] << (i + 1 == merged.size() ? '\n' : ' ');
    }

    std::vector<int> empty_a;
    std::vector<int> empty_b;
    if (!merge_unique(empty_a, empty_b).empty()) {
        std::cerr << "empty merge should be empty\n";
        return 1;
    }
    return 0;
}
```

`std::merge` requires both inputs sorted, which we guarantee. `std::unique` only collapses adjacent duplicates, and the merge already puts equal values next to each other, so one pass suffices. Output for the sample is `1 2 3 4 5 7 9`.

