    bad = ["", "1.2.3", "1.2.3.4.5", "01.2.3.4", "256.1.1.1", "1.2.3.a", "1.2.3.-1", "1.2.3. 4"]
    assert all(is_valid_ipv4(a) for a in good), [a for a in good if not is_valid_ipv4(a)]
