```c
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) {
        return;
    }
    size_t left = 0;
    size_t right = strlen(s);
    while (right > 0 && left < right - 1) {
        --right;
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        ++left;
    }
}

int main(void) {
    char even[] = "abcd";
    char odd[] = "abcde";
    char single[] = "x";
    char empty[] = "";

    reverse_in_place(even);
    reverse_in_place(odd);
    reverse_in_place(single);
    reverse_in_place(empty);

    printf("%s\n", even);
    printf("%s\n", odd);
    printf("%s\n", single);
    printf("empty len=%zu\n", strlen(empty));

    reverse_in_place(NULL);
    return 0;
}
```

The `left < right - 1` guard stops before the pointers cross, and the `right > 0` check keeps an empty string from underflowing the unsigned index. Because we edit the buffer directly, the inputs must be mutable arrays rather than string literals. Expected output: `dcba`, `edcba`, `x`, `empty len=0`.

