#include <array>
#include <cstdint>
#include <iostream>

// F(90) = 2880067194370816120, fits in uint64_t (max ~1.8e19).
uint64_t fib(int n) {
    static std::array<uint64_t, 91> memo{};
    static std::array<bool, 91> seen{};

    if (n < 0 || n > 90) {
        throw std::out_of_range("n must be in [0, 90]");
    }
    if (n == 0) return 0;
    if (n == 1) return 1;
    if (seen[n]) return memo[n];

    memo[n] = fib(n - 1) + fib(n - 2);
    seen[n] = true;
    return memo[n];
}

