fn longest_common_prefix(words: &[&str]) -> String {
    if words.is_empty() {
        return String::new();
    }
    let first = words[0];
    let mut len = first.len();
    for w in &words[1..] {
        len = len.min(w.len());
        while len > 0 && first.as_bytes()[..len] != w.as_bytes()[..len] {
            len -= 1;
        }
        if len == 0 {
            break;
        }
    }
    first[..len].to_string()
}

fn main() {
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&[]).as_str(), "");
    assert_eq!(longest_common_prefix(&["dog", "racecar"]), "");
