#include <limits>

// Returns {value, ok}; ok is false if n! would overflow unsigned long long.
std::pair<unsigned long long, bool> factorial(unsigned n) {
    static std::vector<unsigned long long> memo{1ULL}; // memo[0] = 0! = 1
    const unsigned long long limit = std::numeric_limits<unsigned long long>::max();

    while (memo.size() <= n) {
        unsigned k = static_cast<unsigned>(memo.size());
        unsigned long long prev = memo.back();
        if (prev > limit / k) {           // prev * k would overflow
            return {0ULL, false};
        }
        memo.push_back(prev * k);
    }
    return {memo[n], true};
}

int main() {
    for (unsigned n : {0u, 1u, 5u, 10u, 20u, 21u}) {
        auto [value, ok] = factorial(n);
        if (ok) {
            std::cout << n << "! = " << value << "\n";
        } else {
            std::cout << n << "! overflows unsigned long long\n";
        }
    }
    return 0;
}
