```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>


template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity), closed_(false) {}

    // Blocks until space is available or the queue is closed.
    bool push(T value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [this] { return closed_ || queue_.size() < capacity_; });
        if (closed_) return false;
        queue_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
        return true;
    }

    // Blocks until an item is available or the queue is closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock, [this] { return closed_ || !queue_.empty(); });
        if (queue_.empty()) return std::nullopt;
        T value = std::move(queue_.front());
        queue_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            closed_ = true;
        }
        not_full_.notify_all();
        not_empty_.notify_all();
    }

private:
    std::size_t capacity_;
    bool closed_;
    std::queue<T> queue_;
    std::mutex mutex_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
};
```

Both waits use predicates to survive spurious wakeups. `close()` wakes every waiter so no thread is left blocked. Move `T` in and out to avoid copies.

```c
#include <stdio.h>
#include <string.h>

/* Reverse a UTF-8 string in place by swapping whole code points.
   Returns the number of code points, or -1 on malformed input. */
static int utf8_len(unsigned char c) {
    if (c < 0x80) return 1;
    if ((c & 0xE0) == 0xC0) return 2;
    if ((c & 0xF0) == 0xE0) return 3;
    if ((c & 0xF8) == 0xF0) return 4;
    return -1;
}

int reverse_utf8(char *s) {
    size_t n = strlen(s);
    size_t i = 0, j = n;
    int count = 0;

    while (i < j) {
        int li = utf8_len((unsigned char)s[i]);
        if (li < 0) return -1;

        size_t wj = j;
        int lj = 0;
        do {
            if (wj == 0) return -1;
            --wj;
            lj = utf8_len((unsigned char)s[wj]);
            if (lj < 0) return -1;
        } while (wj > i && (j - wj) < (size_t)lj);

        /* Rotate the two runs s[i..i+li) and s[wj..j) via a temp buffer. */
        char buf[8];
        size_t block = (size_t)li + (j - wj);
        if (block > sizeof buf) return -1;
        memcpy(buf, s + i, li);
        memcpy(s + i, s + wj, j - wj);
        memcpy(s + wj, buf, li);

        i += (size_t)li;
        j = wj;
        count += 2;
    }
    return count;
}

int main(void) {
    char s[] = "h\xC3\xA9llo"; /* "héllo" */
    if (reverse_utf8(s) < 0) {
        fprintf(stderr, "malformed utf-8\n");
        return 1;
    }
    printf("%s\n", s);
    return 0;
}
```

It determines each code point's byte length, swaps left and right runs, and shrinks the window. Malformed sequences return -1 instead of corrupting memory.

```rust
use std::cmp::Ord;

/// Yields the running maximum of an iterator.
pub struct RunningMax<I, T>
where
    I: Iterator<Item = T>,
    T: Ord + Copy,
{
    iter: I,
    max: Option<T>,
}

impl<I, T> Iterator for RunningMax<I, T>
where
    I: Iterator<Item = T>,
    T: Ord + Copy,
{
    type Item = T;

    fn next(&mut self) -> Option<T> {
        let item = self.iter.next()?;
        self.max = Some(match self.max {
            Some(m) => if item > m { item } else { m },
            None => item,
        });
        self.max
    }
}

pub trait RunningMaxExt: Iterator {
    fn running_max(self) -> RunningMax<Self, Self::Item>
    where
        Self: Sized,
        Self::Item: Ord + Copy;
}

impl<I: Iterator> RunningMaxExt for I {}

fn main() {
    let values = vec![3, 1, 4, 1, 5, 9, 2, 6];
    let maxima: Vec<i32> = values.into_iter().running_max().collect();
    assert_eq!(maxima, vec![3, 3, 4, 4, 5, 9, 9, 9]);

    let empty: Vec<i32> = Vec::new();
    assert_eq!(empty.into_iter().running_max().count(), 0);
    println!("ok");
}
```

The `max` field caches the best value seen so far, so each `next()` is O(1). Empty iterators yield nothing via the `?` short-circuit.

