fn is_balanced(input: &str) -> bool {
    let mut stack = Vec::new();

    for ch in input.chars() {
        match ch {
            '(' | '[' | '{' => stack.push(ch),
            ')' | ']' | '}' => {
                let want = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                if stack.pop() != Some(want) {
                    return false;
                }
            }
            _ => {}
        }
    }

    stack.is_empty()
}

fn main() {
    assert!(is_balanced("a(b[c]{d})e"));
    assert!(is_balanced(""));
    assert!(!is_balanced("(]") );
    assert!(!is_balanced("([)]"));
    assert!(!is_balanced("((("));
    println!("ok");
}
```

Only bracket characters are pushed or matched; everything else is transparent. A non-empty stack at the end means unmatched openers like `(((`.

```cpp
#include <cstdint>
#include <limits>
#include <optional>
#include <iostream>

using u64 = std::uint64_t;

// Returns (F(n), F(n+1)).
static std::pair<u64, u64> fib_pair(unsigned n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    u64 c = a * (2 * b - a);
    u64 d = a * a + b * b;
    if (n & 1u) return {d, c + d};
    return {c, d};
}

// Returns F(n), or nullopt if it would overflow 64 bits.
std::optional<u64> fib(unsigned n) {
    // F(93) is the largest Fibonacci number that fits in 64 bits.
    if (n > 93) return std::nullopt;
    return fib_pair(n).first;
}

int main() {
    if (auto v = fib(10)) std::cout << *v << "\n";   // 55
    if (auto v = fib(93)) std::cout << *v << "\n";   // 12200160415121876738
    std::cout << (fib(94) ? "ok" : "overflow") << "\n";
    return 0;
}
```

Fast doubling computes `(F(n), F(n+1))` from `(F(n/2), F(n/2+1))` in O(log n). The `n > 93` guard is a checked precondition rather than silent wraparound, since `u64` arithmetic would otherwise overflow.

