class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_{}, capacity_(capacity), head_(0), size_(0) {}

    bool push(double value) {
        if (size_ == capacity_) {
            return false;
        }
        data_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    bool pop(double &out) {
        if (size_ == 0) {
            return false;
        }
        out = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return true;
    }

    bool full() const { return size_ == capacity_; }
    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    std::array<double, 64> data_;
    std::size_t capacity_;
    std::size_t head_;
    std::size_t size_;
};
