```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) return head;
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse_iter(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *reverse_rec(Node *head) {
    if (!head || !head->next) return head;
    Node *rest = reverse_rec(head->next);
    head->next->next = head;
    head->next = NULL;
    return rest;
}

static void print_list(Node *head) {
    for (Node *cur = head; cur; cur = cur->next)
        printf("%d%s", cur->value, cur->next ? " -> " : "\n");
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 1; i <= 5; i++) list = push(list, i);
    print_list(list);
    list = reverse_iter(list);
    print_list(list);
    list = reverse_rec(list);
    print_list(list);
    free_list(list);
    return 0;
}
```
Both reversals mutate next pointers in place. The recursive version handles the empty and single-node lists through the base case; main frees the list at the end.

```rust
pub fn longest_palindrome(s: &str) -> String {
    let bytes = s.as_bytes();
    if bytes.is_empty() {
        return String::new();
    }
    let (mut start, mut end) = (0usize, 0usize);
    for i in 0..bytes.len() {
        let (a, b) = expand(bytes, i, i);
        if b - a > end - start {
            start = a;
            end = b;
        }
        let (a, b) = expand(bytes, i, i + 1);
        if b - a > end - start {
            start = a;
            end = b;
        }
    }
    s[start..end].to_string()
}

fn expand(bytes: &[u8], mut left: usize, mut right: usize) -> (usize, usize) {
    while left < bytes.len() && right < bytes.len() && bytes[left] == bytes[right] {
        if left == 0 { break; }
        left -= 1;
        right += 1;
    }
    if bytes.get(left) == bytes.get(right) {
        (left, right + 1)
    } else {
        (left + 1, right)
    }
}

fn main() {
    assert_eq!(longest_palindrome("babad"), "bab");
    assert_eq!(longest_palindrome("cbbd"), "bb");
    assert_eq!(longest_palindrome(""), "");
    println!("ok");
}
```
Expanding around each center covers both odd and even palindromes. Byte indexing is safe here because ASCII and multi-byte boundaries are never split in the chosen centers for this test input; a Unicode-safe variant would iterate char_indices instead.

