#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), capacity_(capacity), head_(0), size_(0) {}

    bool push(int value) {
        if (size_ == capacity_) return false;
        data_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::vector<int> data_;
    std::size_t capacity_, head_, size_;
};

int main() {
    RingBuffer rb(3);
    for (int i = 1; i <= 4; ++i)
        std::cout << "push " << i << ": " << rb.push(i) << '\n';
    while (auto v = rb.pop()) std::cout << "pop " << *v << '\n';
    std::cout << "empty: " << rb.empty() << '\n';
    return 0;
}
```
The buffer uses modulo indexing so it overwrites nothing until full; `push` returns false when capacity is reached and `pop` yields `std::nullopt` when empty.

