std::vector<int> parse_csv_ints(std::string_view line) {
    std::vector<int> out;
    std::size_t pos = 0;
    while (pos <= line.size()) {
        std::size_t comma = line.find(',', pos);
        std::string_view field = (comma == std::string_view::npos)
            ? line.substr(pos)
            : line.substr(pos, comma - pos);

        // trim ASCII spaces
        while (!field.empty() && field.front() == ' ') field.remove_prefix(1);
        while (!field.empty() && field.back() == ' ') field.remove_suffix(1);

        int value = 0;
        if (!field.empty()) {
            auto res = std::from_chars(field.data(), field.data() + field.size(), value);
            if (res.ec == std::errc() && res.ptr == field.data() + field.size()) {
                out.push_back(value);
            }
        }
        if (comma == std::string_view::npos) break;
        pos = comma + 1;
    }
    return out;
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        auto values = parse_csv_ints(line);
        long long sum = 0;
        for (int v : values) sum += v;
        std::cout << sum << '\n';
    }
    return 0;
}
