```python
from collections import OrderedDict


class LRUCache:
    """Fixed-capacity cache that evicts the least recently used key."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1
    cache.put("c", 3)
    assert cache.get("b") is None  # evicted as least recently used
    assert cache.get("a") == 1
    assert cache.get("c") == 3
    try:
        LRUCache(0)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
    print("ok")
```
`move_to_end` on every hit keeps recency order, and `popitem(last=False)` discards the front of the dict, which is the least recently used entry.

```python
def fib_fast(n: int) -> int:
    """Return the nth Fibonacci number (F(0)=0, F(1)=1) via fast doubling."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def _pair(k: int):
        # returns (F(k), F(k+1))
        if k == 0:
            return (0, 1)
        a, b = _pair(k >> 1)
        c = a * (2 * b - a)      # F(2k)
        d = a * a + b * b        # F(2k+1)
        if k & 1:
            return (d, c + d)
        return (c, d)

    return _pair(n)[0]


def fib_iter(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


if __name__ == "__main__":
    for n in range(0, 200):
        assert fib_fast(n) == fib_iter(n), f"mismatch at {n}"
    assert fib_fast(0) == 0
    assert fib_fast(1) == 1
    assert fib_fast(10) == 55
    print(fib_fast(100))
```

Fast doubling runs in O(log n) multiplications; Python's big ints keep the result exact. The `_pair` helper returns `(F(k), F(k+1))` so the doubling identities `F(2k) = F(k)·(2·F(k+1) − F(k))` and `F(2k+1) = F(k)² + F(k+1)²` apply directly. The assertion loop cross-checks every value up to 199 against the iterative version.

