        raise SystemExit(2)

    try:
        with open(sys.argv[1], encoding="utf-8") as fh:
            text = fh.read()
    except OSError as err:
        print(f"could not read file: {err}", file=sys.stderr)
        raise SystemExit(1)

    counts = top_words(text)
    if not counts:
        print("(no words found)")
        return

    width = max(len(w) for w, _ in counts)
    for word, count in counts:
        print(f"{word:<{width}} {count}")


if __name__ == "__main__":
    main()
```

`re.findall` with `[a-z0-9']+` on the lowercased text strips punctuation while keeping contractions like `don't` intact and treats ``don't`` and ``dont`` separately. `Counter.most_common` handles the sorting; ties are broken by first-seen order. Unicode letters outside `a-z0-9` are dropped, so for mixed-script text you would widen the character class (e.g. `re.UNICODE` with `\w`).

```python
from collections import OrderedDict


class LRUCache:
    """Fixed-capacity cache that evicts the least-recently-used key."""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)

    def __contains__(self, key) -> bool:
        return key in self._data


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1          # 'a' now most-recent
    cache.put("c", 3)                   # evicts 'b'
    assert "b" not in cache
    assert cache.get("b") is None
    assert cache.get("a") == 1 and cache.get("c") == 3
    cache.put("a", 10)                  # overwrite, still MRU
    cache.put("d", 4)                   # evicts 'c'
    assert "c" not in cache
    assert len(cache) == 2
    print("all assertions passed")
```

`OrderedDict` keeps insertion order and `move_to_end` promotes a key on every hit; `popitem(last=False)` removes the oldest, which is the LRU entry. All operations are O(1). Overwriting an existing key updates the value without changing capacity.

