#include <iostream>
#include <limits>
#include <optional>
#include <sstream>
#include <string>

static std::optional<long long> parse(const std::string& token) {
    try {
        std::size_t pos = 0;
        long long value = std::stoll(token, &pos);
        if (pos != token.size()) return std::nullopt;  // trailing junk
        return value;
    } catch (const std::exception&) {
        return std::nullopt;
    }
}

int main() {
    long long sum = 0;
    long long mn = std::numeric_limits<long long>::max();
    long long mx = std::numeric_limits<long long>::min();
    std::size_t valid = 0, invalid = 0;

    std::string token;
    while (std::cin >> token) {
        auto value = parse(token);
        if (!value) {
            ++invalid;
            std::cerr << "skipping invalid token: " << token << '\n';
            continue;
        }
        sum += *value;
        mn = std::min(mn, *value);
        mx = std::max(mx, *value);
        ++valid;
    }

    if (valid == 0) {
        std::cout << "no valid integers" << '\n';
        return 0;
    }
    std::cout << "count=" << valid << ' ' << "invalid=" << invalid << '\n'
              << "min=" << mn << ' ' << "max=" << mx << ' ' << "sum=" << sum << '\n';
    return 0;
}
```

`std::stoll` throws on overflow and out-of-range input, and the `pos` check rejects tokens with trailing characters like `12ab`. On an empty (or fully invalid) stream the program prints `no valid integers` rather than emitting garbage from the `numeric_limits` sentinels. Compile with `g++ -std=c++17 -O2 -Wall -o agg agg.cpp` and pipe numbers in.

