#include <cstddef>
#include <cstring>
#include <cassert>
#include <iostream>

// Reverses the C string in place. Returns false for a null pointer.
bool reverse_cstr(char* s) {
    if (s == nullptr) return false;
    std::size_t n = std::strlen(s);
    if (n < 2) return true;  // empty or single char already reversed

    char* left = s;
    char* right = s + n - 1;
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        ++left;
        --right;
    }
    return true;
}

int main() {
    char a[] = "hello world";
    reverse_cstr(a);
    assert(std::strcmp(a, "dlrow olleh") == 0);

    char b[] = "";
    reverse_cstr(b);
    assert(std::strcmp(b, "") == 0);

    char c[] = "x";
    reverse_cstr(c);
    assert(std::strcmp(c, "x") == 0);

    assert(!reverse_cstr(nullptr));
    std::cout << "all assertions passed\n";
}
```

Two pointers start at the ends and walk inward, swapping until they meet — O(n) time, O(1) extra space, and no change to the terminator. The `n < 2` guard short-circuits empty and single-character strings so the loop is never entered with `left == right`. Note the arrays are writable (`char a[]`, not `const char*`) because a string literal is read-only.

