```python
import hashlib
import os
import sys
from collections import defaultdict


def file_hash(path: str, chunk: int = 65536) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as fh:
        while block := fh.read(chunk):
            digest.update(block)
    return digest.hexdigest()


def find_duplicates(root: str) -> dict[str, list[str]]:
    by_size: dict[int, list[str]] = defaultdict(list)
    for dirpath, _dirs, files in os.walk(root):
        for name in files:
            path = os.path.join(dirpath, name)
            if os.path.islink(path) or not os.path.isfile(path):
                continue
            try:
                by_size[os.path.getsize(path)].append(path)
            except OSError as err:
                print(f"skip {path}: {err}", file=sys.stderr)

    by_hash: dict[str, list[str]] = defaultdict(list)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue  # unique size cannot have a duplicate
        for path in paths:
            try:
                by_hash[file_hash(path)].append(path)
            except OSError as err:
                print(f"skip {path}: {err}", file=sys.stderr)

    return {h: ps for h, ps in by_hash.items() if len(ps) > 1}


def main() -> None:
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    groups = find_duplicates(root)
    if not groups:
        print("no duplicates found")
        return
    for digest, paths in sorted(groups.items()):
        print(f"{digest[:12]}:")
        for path in sorted(paths):
            print(f"  {path}")


if __name__ == "__main__":
    main()
```

Grouping by file size first means most files never get hashed, since different sizes cannot collide. Identical content always shares a size and a SHA-256 digest; the hash is streamed in 64 KiB chunks so large files use constant memory. Symlinks are skipped to avoid loops and double-counting, and unreadable files are reported to stderr rather than aborting the scan.

```cpp
#include <condition_variable>
#include <cstddef>
#include <iostream>
#include <mutex>
#include <optional>
#include <queue>
#include <thread>

// A fixed-capacity FIFO that blocks producers when full and consumers when empty.
template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {}

    // Blocks until space is available. Returns false once shut down.
    bool push(T value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return closed_ || q_.size() < capacity_; });
        if (closed_) return false;
        q_.push(std::move(value));
        not_empty_.notify_one();
        return true;
    }

    // Blocks until an item is available or the queue is drained and closed.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;  // closed and drained
        T item = std::move(q_.front());
        q_.pop();
        not_full_.notify_one();
        return item;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t capacity_;
    std::queue<T> q_;
    std::mutex mu_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
    bool closed_ = false;
};

int main() {
    BoundedQueue<int> q(4);
    constexpr int kItems = 20;

    std::thread producer([&q] {
        for (int i = 1; i <= kItems; ++i) q.push(i);
        q.close();
    });

    long long sum = 0;
    int count = 0;
    std::thread consumer([&q, &sum, &count] {
        while (auto v = q.pop()) {
            sum += *v;
            ++count;
        }
    });

    producer.join();
    consumer.join();
    std::cout << "consumed " << count << " items, sum " << sum << '\n';
    return (count == kItems && sum == kItems * (kItems + 1) / 2) ? 0 : 1;
}
```

Why this is safe: both waits take the mutex and re-check the predicate, so spurious wakeups and `close()` races are handled. `notify_one` is enough on push/pop, but `close()` must use `notify_all` to wake every blocked thread.

