#include <fcntl.h>
#include <unistd.h>

#include <cerrno>
#include <cstddef>
#include <cstring>
#include <iostream>
#include <stdexcept>
#include <string>
#include <utility>

// Owns a file descriptor. Copy is deleted; move transfers ownership.
class Fd {
public:
    Fd() noexcept = default;
    explicit Fd(int fd) noexcept : fd_(fd) {}

    ~Fd() { reset(); }

    Fd(const Fd&) = delete;
    Fd& operator=(const Fd&) = delete;

    Fd(Fd&& other) noexcept : fd_(other.release()) {}
    Fd& operator=(Fd&& other) noexcept {
        if (this != &other) reset(other.release());
        return *this;
    }

    int get() const noexcept { return fd_; }
    explicit operator bool() const noexcept { return fd_ >= 0; }

    // Relinquish ownership without closing.
    int release() noexcept {
        int tmp = fd_;
        fd_ = -1;
        return tmp;
    }

    void reset(int fd = -1) noexcept {
        if (fd_ >= 0) {
            // Retry on EINTR; other errors are unrecoverable here.
            while (::close(fd_) == -1 && errno == EINTR) {}
        }
        fd_ = fd;
    }

private:
    int fd_ = -1;
};

static Fd open_read(const std::string& path) {
    int fd = ::open(path.c_str(), O_RDONLY | O_CLOEXEC);
    if (fd < 0) throw std::runtime_error("open failed: " + std::string(std::strerror(errno)));
    return Fd(fd);  // moved out; no double close
}

int main(int argc, char** argv) {
    const std::string path = argc > 1 ? argv[1] : "/etc/hostname";
    try {
        Fd file = open_read(path);
        char buf[4096];
        ssize_t n;
        while ((n = ::read(file.get(), buf, sizeof buf)) > 0) {
            std::cout.write(buf, static_cast<std::size_t>(n));
        }
        if (n < 0 && errno != EINTR) throw std::runtime_error("read failed");
    } catch (const std::exception& e) {
        std::cerr << "error: " << e.what() << '\n';
        return 1;
    }
    return 0;
}
```

The key points: `release()` sets the source to `-1` so its destructor is a no-op, move-assignment closes the current fd before adopting the new one, and `O_CLOEXEC` prevents the fd leaking into child processes.

```rust
use std::cmp::Ordering;

/// Binary search over a sorted slice.
///
/// Returns `Ok(index)` if `needle` is found, otherwise `Err(index)` where
/// `index` is the insertion point that keeps the slice sorted.
fn binary_search<T: Ord>(haystack: &[T], needle: &T) -> Result<usize, usize> {
    let mut lo = 0usize;
    let mut hi = haystack.len(); // exclusive upper bound

    while lo < hi {
        let mid = lo + (hi - lo) / 2; // avoids overflow on huge slices
        match haystack[mid].cmp(needle) {
            Ordering::Equal => return Ok(mid),
            Ordering::Less => lo = mid + 1,
            Ordering::Greater => hi = mid,
        }
    }
    Err(lo)
}

#[cfg(test)]
mod tests {
    use super::binary_search;

    #[test]
    fn empty_slice_inserts_at_zero() {
        let empty: &[i32] = &[];
        assert_eq!(binary_search(empty, &5), Err(0));
    }

    #[test]
    fn integer_slice() {
        let data = [1, 3, 5, 7, 9, 11];
        assert_eq!(binary_search(&data, &7), Ok(3));
        assert_eq!(binary_search(&data, &1), Ok(0));
        assert_eq!(binary_search(&data, &11), Ok(5));
        assert_eq!(binary_search(&data, &4), Err(2));
        assert_eq!(binary_search(&data, &0), Err(0));
        assert_eq!(binary_search(&data, &12), Err(6));
    }

    #[test]
    fn string_slice_uses_lexicographic_order() {
        let names = ["ada", "alan", "grace", "linus"];
        assert_eq!(binary_search(&names, &"grace"), Ok(2));
        assert_eq!(binary_search(&names, &"bjarne"), Err(2));
    }
}

fn main() {
    let data = [10, 20, 30, 40, 50];
    println!("{:?}", binary_search(&data, &30)); // Ok(2)
    println!("{:?}", binary_search(&data, &35)); // Err(3)
}
```

Difference from `slice::binary_search`: this is the general `Ord` form, not the `BinarySearchBy` variant, and it mirrors the standard return convention. `mid = lo + (hi - lo) / 2` is used instead of `(lo + hi) / 2` to stay correct for indices near `usize::MAX`.

