```c
#include <stdio.h>
#include <stdlib.h>

#define STACK_INIT_CAP 4

typedef struct {
    int *items;
    size_t size;
    size_t capacity;
} Stack;

/* Allocate an empty stack. Returns NULL on allocation failure. */
Stack *stack_create(void) {
    Stack *s = malloc(sizeof *s);
    if (!s) return NULL;
    s->items = malloc(STACK_INIT_CAP * sizeof *s->items);
    if (!s->items) {
        free(s);
        return NULL;
    }
    s->size = 0;
    s->capacity = STACK_INIT_CAP;
    return s;
}

void stack_destroy(Stack *s) {
    if (!s) return;
    free(s->items);
    free(s);
}

/* Ensure room for one more element. Returns 0 on success, -1 on failure. */
static int stack_grow(Stack *s) {
    if (s->size < s->capacity) return 0;
    size_t new_cap = s->capacity * 2;
    int *grown = realloc(s->items, new_cap * sizeof *grown);
    if (!grown) return -1;
    s->items = grown;
    s->capacity = new_cap;
    return 0;
}

int stack_push(Stack *s, int value) {
    if (stack_grow(s) != 0) return -1;
    s->items[s->size++] = value;
    return 0;
}

/* Pop into *out. Returns 0 on success, -1 if the stack is empty. */
int stack_pop(Stack *s, int *out) {
    if (s->size == 0) return -1;
    *out = s->items[--s->size];
    return 0;
}

/* Read the top without removing it. Returns 0 on success, -1 if empty. */
int stack_peek(const Stack *s, int *out) {
    if (s->size == 0) return -1;
    *out = s->items[s->size - 1];
    return 0;
}

size_t stack_size(const Stack *s) { return s->size; }

int main(void) {
    Stack *s = stack_create();
    if (!s) {
        fprintf(stderr, "error: could not allocate stack\n");
        return 1;
    }

    int v = 0;
    if (stack_pop(s, &v) != -1) {           /* empty-pop check */
        fprintf(stderr, "FAIL: pop on empty stack returned success\n");
        stack_destroy(s);
        return 1;
    }

    for (int i = 1; i <= 10; ++i) {
        if (stack_push(s, i) != 0) {
            fprintf(stderr, "error: push failed at %d\n", i);
            stack_destroy(s);
            return 1;
        }
    }
    if (stack_peek(s, &v) != 0 || v != 10) {
        fprintf(stderr, "FAIL: peek expected 10, got %d\n", v);
        stack_destroy(s);
        return 1;
    }

    int sum = 0;
    while (stack_pop(s, &v) == 0) sum += v;
    if (sum != 55) {
        fprintf(stderr, "FAIL: sum expected 55, got %d\n", sum);
        stack_destroy(s);
        return 1;
    }

    printf("all checks passed (size=%zu)\n", stack_size(s));
    stack_destroy(s);
    return 0;
}
```

Details worth noting: growth is a separate function so every `push` can report failure; `realloc` result is stored in a temporary so a failure does not leak the old block; the empty-pop path is explicitly tested to confirm the `-1` contract.

