#include <iostream>
#include <vector>

std::vector<int> merge_sorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    const std::vector<std::vector<int>> first = {{1, 3, 5, 7}, {}, {2, 2, 9}};
    const std::vector<std::vector<int>> second = {{2, 4, 6}, {1, 2}, {1, 3}};

    for (std::size_t k = 0; k < first.size(); ++k) {
        const auto merged = merge_sorted(first[k], second[k]);
        std::cout << "merged: ";
        for (int v : merged) std::cout << v << ' ';
        std::cout << '\n';
    }
    return 0;
}
```

The merge loop takes the smaller of the two front elements each step and appends it, so equal values come from `a` first, which keeps the output stable for duplicates. Two drain loops handle the remaining tail. The second test pair exercises two empty-vs-nonempty combinations and the third exercises duplicate handling.

