```python
from typing import Optional, Tuple


VALID = True
INVALID = False


def validate_ipv4(address: str) -> Tuple[bool, Optional[str]]:
    """Return (True, None) for a valid dotted-quad IPv4 address,
    otherwise (False, reason)."""
    if not address:
        return INVALID, "empty string"

    parts = address.split(".")
    if len(parts) != 4:
        return INVALID, f"expected 4 octets, got {len(parts)}"

    for index, part in enumerate(parts):
        if part == "":
            return INVALID, f"octet {index} is empty"
        if not part.isdigit():
            return INVALID, f"octet {index} is not numeric: {part!r}"
        if len(part) > 1 and part[0] == "0":
            return INVALID, f"octet {index} has a leading zero: {part!r}"
        value = int(part)
        if value > 255:
            return INVALID, f"octet {index} is out of range: {value}"
    return VALID, None


if __name__ == "__main__":
    samples = ["192.168.0.1", "10.0.0.256", "1.2.3", " 1.2.3.4", "01.2.3.4", "8.8.8.8"]
    for sample in samples:
        ok, reason = validate_ipv4(sample)
        print(f"{sample!r}: {'valid' if ok else 'invalid - ' + reason}")
```

The check rejects the wrong number of octets first, then empty and non-numeric octets, then leading zeros, then values above 255. A leading space makes `" 1.2.3.4".split(".")` still produce four parts but the first `" 1"` fails `isdigit()`, so it is reported as non-numeric. Leading zeros are rejected because `01.2.3.4` is ambiguous under strict IPv4 rules.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    node->value = value;
    node->next = head;
    return node;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(const Node *head) {
    for (const Node *cur = head; cur; cur = cur->next) {
        printf("%d", cur->value);
        if (cur->next) printf(" -> ");
    }
    printf("\n");
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; ++i) head = push(head, i);

    printf("before: ");
    print_list(head);
    head = reverse(head);
    printf("after:  ");
    print_list(head);

    free_list(head);
    return 0;
}
```

`push` prepends, so the list starts as `5 -> 4 -> 3 -> 2 -> 1`. `reverse` walks it once, flipping each `next` pointer to point at the previous node and returning the old tail as the new head, giving `1 -> 2 -> 3 -> 4 -> 5`. The empty-list case falls out naturally: `reverse(NULL)` returns `NULL`, and `print_list` prints nothing. `free_list` releases every node after the reversal.

