```cpp
#include <iostream>
#include <optional>
#include <vector>

template <typename T>
class FixedStack {
public:
    explicit FixedStack(std::size_t capacity) : capacity_(capacity) { data_.reserve(capacity); }

    bool push(const T& value) {
        if (data_.size() >= capacity_) return false;
        data_.push_back(value);
        return true;
    }

    std::optional<T> pop() {
        if (data_.empty()) return std::nullopt;
        T value = data_.back();
        data_.pop_back();
        return value;
    }

    std::size_t size() const { return data_.size(); }
    bool empty() const { return data_.empty(); }
    std::size_t capacity() const { return capacity_; }

private:
    std::size_t capacity_;
    std::vector<T> data_;
};

int main() {
    FixedStack<int> stack(3);
    std::cout << "push 1: " << stack.push(1) << '\n';
    std::cout << "push 2: " << stack.push(2) << '\n';
    std::cout << "push 3: " << stack.push(3) << '\n';
    std::cout << "push 4: " << stack.push(4) << " (overflow)\n";

    while (auto value = stack.pop()) {
        std::cout << "pop: " << *value << '\n';
    }
    std::cout << "pop on empty: " << (stack.pop().has_value() ? "value" : "nothing") << '\n';
    return 0;
}
```

`push` returns `false` when the stack is full rather than throwing or writing out of bounds, so the fourth push is rejected cleanly. `pop` returns `std::optional<T>` and yields `std::nullopt` on an empty stack, which the `while (auto value = stack.pop())` loop uses as its termination condition. Output shows three successful pushes, one rejected push, three pops in LIFO order, and a final empty pop reporting no value.

