#include <stdio.h>
#include <string.h>

static void reverse_in_place(char *s, size_t len) {
    if (len < 2) return;
    size_t i = 0, j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
        --j;
    }
}

int main(int argc, char **argv) {
