fn fib(n: u32) -> Option<u64> {
    let mut a: u64 = 0;
    let mut b: u64 = 1;
    for _ in 0..n {
        let next = a.checked_add(b)?;
        a = b;
        b = next;
    }
    Some(a)
}

fn main() {
    assert_eq!(fib(0), Some(0));
    assert_eq!(fib(1), Some(1));
    assert_eq!(fib(10), Some(55));
    assert_eq!(fib(50), Some(12586269025));

    // F(94) is the last one that fits in u64; F(95) overflows.
    assert!(fib(94).is_some());
    assert_eq!(fib(95), None);

    println!("ok");
}
