```cpp
#include <cstdlib>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> lower;                              // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> upper;  // min-heap

    int x;
    while (std::cin >> x) {
        if (lower.empty() || x <= lower.top()) {
            lower.push(x);
        } else {
            upper.push(x);
        }

        // Rebalance so sizes differ by at most one.
        if (lower.size() > upper.size() + 1) {
            upper.push(lower.top());
            lower.pop();
        } else if (upper.size() > lower.size()) {
            lower.push(upper.top());
            upper.pop();
        }

        double median = lower.size() == upper.size()
                            ? (lower.top() + upper.top()) / 2.0
                            : static_cast<double>(lower.top());
        std::cout << median << '\n';
    }
    return 0;
}
```

Two heaps: `lower` holds the small half, `upper` the large half. After each insert the rebalance step keeps `lower` one element ahead or equal, so the median is either `lower.top()` or the average of the two tops. Each value is pushed and popped at most once, giving O(n log n) overall.

