```python
import heapq

def merge_sorted(iterables):
    streams = [iter(it) for it in iterables]
    heap = []
    for index, stream in enumerate(streams):
        try:
            value = next(stream)
        except StopIteration:
            continue
        heapq.heappush(heap, (value, index, stream))
    while heap:
        value, index, stream = heapq.heappop(heap)
        yield value
        try:
            nxt = next(stream)
        except StopIteration:
            continue
        heapq.heappush(heap, (nxt, index, stream))

if __name__ == "__main__":
    print(list(merge_sorted([[1, 4, 9], [], [2, 3, 5], [0, 7]])))
```
Each stream advances lazily, so memory stays proportional to the number of inputs rather than their total length. The `index` is the tiebreaker — two equal values never cause a comparison of the iterator objects themselves.

```cpp
#include <cstdint>
#include <stdexcept>
#include <string>

std::string to_binary(std::int64_t value) {
    if (value == 0) return "0";
    bool negative = value < 0;
    std::uint64_t magnitude = negative
        ? static_cast<std::uint64_t>(-(value + 1)) + 1u
        : static_cast<std::uint64_t>(value);
    std::string bits;
    while (magnitude) {
        bits.push_back('0' + (magnitude & 1u));
        magnitude >>= 1u;
    }
    if (negative) bits.push_back('-');
    return std::string(bits.rbegin(), bits.rend());
}

std::int64_t from_binary(const std::string& bits) {
    if (bits.empty()) throw std::invalid_argument("empty binary string");
    std::size_t i = 0;
    bool negative = bits[0] == '-';
    if (negative) i = 1;
    if (i == bits.size()) throw std::invalid_argument("no digits after sign");
    std::int64_t value = 0;
    for (; i < bits.size(); ++i) {
        char c = bits[i];
        if (c != '0' && c != '1') throw std::invalid_argument("non-binary digit");
        value = value * 2 + (c - '0');
    }
    return negative ? -value : value;
}
```
The negative path uses `-(value + 1) + 1` so that the most negative 64-bit value does not overflow when negated. Invalid input raises rather than returning a sentinel.

