#include <iostream>
#include <string>
#include <vector>

bool balanced(const std::string& s) {
    std::vector<char> stack;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                stack.push_back(c);
                break;
            case ')': case ']': case '}': {
                if (stack.empty()) return false;
                char open = stack.back();
                stack.pop_back();
                if ((c == ')' && open != '(') ||
                    (c == ']' && open != '[') ||
                    (c == '}' && open != '{')) return false;
                break;
            }
            default:
                break;
        }
    }
    return stack.empty();
}

int main() {
    for (const char* s : {"()[]{}", "([{}])", "(]", "((", "")}) {
        std::cout << '\'' << s << "' -> " << (balanced(s) ? "ok" : "bad") << '\n';
    }
    return 0;
}
```
A closing bracket must match the most recent unmatched opener, which is exactly what a stack gives. The final `empty()` check rejects unbalanced opens such as `((`, and stray closers fail immediately.

