#include <iostream>
#include <map>
#include <optional>
#include <sstream>
#include <string>

std::optional<std::map<std::string, std::string>>
parse_pairs(const std::string& input, std::string& error) {
    std::map<std::string, std::string> out;
    std::istringstream stream(input);
    std::string token;
    while (std::getline(stream, token, ';')) {
        if (token.empty()) continue;
        auto eq = token.find('=');
        if (eq == std::string::npos || eq == 0) {
            error = "malformed pair: '" + token + "'";
            return std::nullopt;
        }
        std::string key = token.substr(0, eq);
        std::string value = token.substr(eq + 1);
        if (out.count(key)) {
            error = "duplicate key: '" + key + "'";
            return std::nullopt;
        }
        out.emplace(std::move(key), std::move(value));
    }
    return out;
}

int main() {
    const char* inputs[] = {"a=1;b=2;c=3", "x=", "bad", "k=1;k=2", ""};
    for (const char* raw : inputs) {
        std::string error;
        auto result = parse_pairs(raw, error);
        if (result) {
            std::cout << "ok: ";
            for (const auto& [k, v] : *result) std::cout << k << "->" << v << " ";
            std::cout << "\n";
        } else {
            std::cout << "error: " << error << "\n";
        }
    }
    return 0;
}
