```c
#include <stdio.h>
#include <string.h>

static size_t utf8_len(unsigned char c) {
    if (c < 0x80) return 1;
    if ((c & 0xE0) == 0xC0) return 2;
    if ((c & 0xF0) == 0xE0) return 3;
    if ((c & 0xF8) == 0xF0) return 4;
    return 1; /* invalid byte: treat as single */
}

/* Reverse the code points of a NUL-terminated UTF-8 string in place. */
void utf8_reverse(char *s) {
    size_t n = strlen(s);
    if (n < 2) return;
    char *left = s;
    char *right = s + n;
    while (left < right) {
        size_t llen = utf8_len((unsigned char)*left);
        if (left + llen > right) llen = 1;
        right -= llen;
        size_t rlen = utf8_len((unsigned char)*right);
        if (left + llen > right + rlen) { right += llen; break; }
        char tmp[4];
        memcpy(tmp, left, llen);
        memmove(left, right, rlen);
        memmove(right + (rlen - llen), tmp, llen);
        left += rlen;
    }
}

int main(void) {
    char buf[256];
    const char *samples[] = {"hello", "", "a", "caf\xC3\xA9"};
    for (size_t i = 0; i < sizeof(samples) / sizeof(samples[0]); ++i) {
        snprintf(buf, sizeof buf, "%s", samples[i]);
        utf8_reverse(buf);
        printf("'%s'\n", buf);
    }
    return 0;
}
```

Walks from both ends using the leading-byte length so multibyte sequences stay intact. Invalid leading bytes fall back to a single byte rather than reading past the buffer.

