```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (full()) return false;
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << std::boolalpha << rb.empty() << "\n"; // true
    for (int i = 1; i <= 3; ++i) std::cout << rb.push(i * 10) << " ";
    std::cout << "\n" << rb.full() << "\n";            // true
    std::cout << rb.push(40) << "\n";                  // false
    while (auto v = rb.pop()) std::cout << *v << " ";  // 10 20 30
    std::cout << "\n" << rb.pop().has_value() << "\n"; // false
    return 0;
}
```

Uses a separate `size_` counter so full/empty never collide. `push` returns false when full, and `pop` returns `std::nullopt` when empty.

