fn find_subslice(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() {
        return Some(0);
    }
    if needle.len() > haystack.len() {
        return None;
    }
    let last_start = haystack.len() - needle.len();
    for i in 0..=last_start {
        if &haystack[i..i + needle.len()] == needle {
            return Some(i);
        }
    }
    None
}

