    // by the character's position in the string, not hash order.
    let mut best: Option<(char, usize)> = None;
    for c in s.chars() {
        let n = counts[&c];
        if best.map_or(true, |(_, bn)| n > bn) {
            best = Some((c, n));
        }
    }
    best
}

