// Negative numbers are not palindromes. We reverse only the lower half
// so we never overflow, unlike reversing the whole integer.
bool is_palindrome(long long x) {
    if (x < 0) return false;
    if (x % 10 == 0 && x != 0) return false;
    long long half = 0;
    while (x > half) {
        half = half * 10 + x % 10;
        x /= 10;
    }
    return x == half || x == half / 10;
}

