    let text = "the quick brown fox jumps over the lazy dog The DOG";
    let top = top_words(text, 3);
    assert_eq!(top[0], ("the".to_string(), 3));
    assert_eq!(top[1], ("dog".to_string(), 2));
    println!("{:?}", top);
}
