```c
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Returns 1 on success, 0 on failure. */
int parse_ulong(const char *s, unsigned long *out) {
    if (s == NULL || out == NULL || *s == '\0')
        return 0;

    errno = 0;
    char *end = NULL;
    unsigned long v = strtoul(s, &end, 10);

    if (errno == ERANGE)
        return 0;               /* overflow */
    if (end == s || *end != '\0')
        return 0;               /* no digits or trailing garbage */
    if (v > ULONG_MAX)
        return 0;

    *out = v;
    return 1;
}

int main(void) {
    const char *tests[] = {"0", "42", " 7", "12x", "", "999999999999999999999999999"};
    for (int i = 0; i < 6; i++) {
        unsigned long out = 0;
        int ok = parse_ulong(tests[i], &out);
        printf("%-30s -> %s (%lu)\n", tests[i], ok ? "ok" : "bad", out);
    }
    return 0;
}
