```cpp
#include <cstddef>
#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& data, int target) {
    std::size_t lo = 0;
    std::size_t hi = data.size(); // half-open [lo, hi)

    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2; // no overflow
        if (data[mid] == target) {
            return static_cast<int>(mid);
        } else if (data[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

int main() {
    std::vector<int> v{-5, -1, 0, 3, 9, 42};
    std::cout << binary_search(v, 9) << '\n';    // 4
    std::cout << binary_search(v, 7) << '\n';    // -1
    std::cout << binary_search({}, 1) << '\n';   // -1
    return 0;
}
```

The loop uses the half-open interval `[lo, hi)` — `hi` starts at `size()` so the empty-vector case exits immediately. `lo + (hi - lo) / 2` avoids the classic `(lo + hi) / 2` overflow.

