#include <unistd.h>
#include <utility>
#include <iostream>

class SocketFd {
public:
    explicit SocketFd(int fd = -1) noexcept : fd_(fd) {}

    ~SocketFd() { close_now(); }

    SocketFd(const SocketFd&) = delete;
    SocketFd& operator=(const SocketFd&) = delete;

    SocketFd(SocketFd&& other) noexcept : fd_(other.fd_) {
        other.fd_ = -1;
    }

    SocketFd& operator=(SocketFd&& other) noexcept {
        if (this != &other) {
            close_now();
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    int get() const noexcept { return fd_; }
    bool valid() const noexcept { return fd_ >= 0; }
    int release() noexcept { int f = fd_; fd_ = -1; return f; }

private:
    void close_now() noexcept {
        if (fd_ >= 0) {
            ::close(fd_);
            fd_ = -1;
        }
    }
    int fd_;
};

int main() {
    SocketFd a(3);
    std::cout << a.valid() << '\n'; // 1
    SocketFd b = std::move(a);
    std::cout << a.valid() << '\n'; // 0
    std::cout << b.get() << '\n';   // 3
    return 0; // b's dtor closes fd 3
}
```

The move constructor and move assignment set the source `fd_` to `-1`, so only one object ever owns the descriptor. `release()` is the escape hatch for handing ownership to a C API.

