#include <array>
#include <cstddef>
#include <optional>
#include <stdexcept>

class RingBuffer {
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
    int* data_;

public:
    explicit RingBuffer(std::size_t capacity)
        : capacity_(capacity), data_(new int[capacity]) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }
    ~RingBuffer() { delete[] data_; }
    RingBuffer(const RingBuffer&) = delete;
    RingBuffer& operator=(const RingBuffer&) = delete;

    bool push(int value) {
        if (size_ == capacity_) return false;
        data_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
};

#include <cassert>
int main() {
    RingBuffer rb(2);
    assert(!rb.pop().has_value());
    assert(rb.push(1) && rb.push(2));
    assert(!rb.push(3));
    assert(rb.pop() == 1);
    assert(rb.push(3));
    assert(rb.pop() == 2 && rb.pop() == 3);
    return 0;
}
```
The constructor validates capacity before allocating; the class is non-copyable to avoid a double-free, and `push` reports a full buffer instead of silently overwriting.

