#include <algorithm>
#include <cassert>
#include <vector>

template <typename T>
void rotate_left(std::vector<T>& v, std::size_t k) {
    if (v.empty()) return;
    k %= v.size();
    if (k == 0) return;
    std::reverse(v.begin(), v.begin() + k);
    std::reverse(v.begin() + k, v.end());
    std::reverse(v.begin(), v.end());
}

int main() {
    std::vector<int> a{1, 2, 3, 4, 5};
    rotate_left(a, 2);
    assert((a == std::vector<int>{3, 4, 5, 1, 2}));

    std::vector<int> b;
    rotate_left(b, 3);          // empty input is a no-op
    assert(b.empty());

    std::vector<int> c{1, 2};
    rotate_left(c, 7);          // k larger than size wraps
    assert((c == std::vector<int>{2, 1}));

    std::vector<int> d{1, 2, 3};
    rotate_left(d, 3);          // identity rotation
    assert((d == std::vector<int>{1, 2, 3}));
    return 0;
}
```
The three reversals implement the juggling rotation using no auxiliary array. Reducing `k` modulo the size and short-circuiting on empty/zero keeps every reverse range valid.

