void to_binary(int n, char *out, size_t out_size) {
    if (out_size == 0) return;
    if (n == 0) {
        snprintf(out, out_size, "0");
        return;
    }

    unsigned int value = (n < 0) ? (unsigned int)(-(long)n) : (unsigned int)n;
    char tmp[33];
    int i = 0;
    while (value > 0) {
        tmp[i++] = (char)('0' + (value & 1u));
        value >>= 1;
    }
    tmp[i] = '\0';

    size_t pos = 0;
    if (out_size < 2) { out[0] = '\0'; return; }
    if (n < 0) out[pos++] = '-';
    while (i > 0 && pos + 1 < out_size) {
        out[pos++] = tmp[--i];
    }
    out[pos] = '\0';
}

int main(void) {
    char buf[40];
    to_binary(0, buf, sizeof buf); printf("%s\n", buf);
    to_binary(10, buf, sizeof buf); printf("%s\n", buf);
    to_binary(-5, buf, sizeof buf); printf("%s\n", buf);
    to_binary(255, buf, sizeof buf); printf("%s\n", buf);
