bool is_palindrome(const std::string& s) {
    std::size_t i = 0, j = s.size();
    while (i < j) {
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[i]))) ++i;
        while (i < j && !std::isalnum(static_cast<unsigned char>(s[j - 1]))) --j;
        if (i >= j) break;
        if (std::tolower(static_cast<unsigned char>(s[i])) !=
            std::tolower(static_cast<unsigned char>(s[j - 1]))) {
            return false;
        }
        ++i;
        --j;
    }
    return true;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << is_palindrome("") << '\n';
    std::cout << is_palindrome("A man, a plan, a canal: Panama") << '\n';
    std::cout << is_palindrome("race a car") << '\n';
    std::cout << is_palindrome("12321") << '\n';
    return 0;
}
