```cpp
#include <algorithm>
#include <iostream>
#include <vector>

void rotate_left(std::vector<int>& a, int k) {
    const int n = static_cast<int>(a.size());
    if (n == 0) return;
    k %= n;
    if (k < 0) k += n;
    std::reverse(a.begin(), a.begin() + k);
    std::reverse(a.begin() + k, a.end());
    std::reverse(a.begin(), a.end());
}

int main() {
    std::vector<int> a{1, 2, 3, 4, 5};
    rotate_left(a, 2);
    for (int x : a) std::cout << x << ' ';
    std::cout << '\n';

    std::vector<int> b{1, 2, 3};
    rotate_left(b, 5);   // wraps around
    for (int x : b) std::cout << x << ' ';
    std::cout << '\n';

    std::vector<int> empty;
    rotate_left(empty, 3);  // no crash on empty input
    std::cout << empty.size() << '\n';
}
```

The triple-reverse trick is O(n) time and O(1) extra space. `k %= n` plus the negative correction handles any `k`, and the empty check prevents dereferencing `begin()` on a zero-length vector.

```cpp
#include <cstddef>
#include <iostream>

class FixedStack {
public:
    explicit FixedStack(std::size_t capacity)
        : data_(new double[capacity]), cap_(capacity), top_(0) {}
    ~FixedStack() { delete[] data_; }

    FixedStack(const FixedStack&) = delete;
    FixedStack& operator=(const FixedStack&) = delete;

    bool push(double v) {
        if (top_ == cap_) return false;
        data_[top_++] = v;
        return true;
    }

    bool pop(double& out) {
        if (top_ == 0) return false;
        out = data_[--top_];
        return true;
    }

    std::size_t size() const { return top_; }

private:
    double* data_;
    std::size_t cap_;
    std::size_t top_;
};

int main() {
    FixedStack s(2);
    std::cout << s.push(1.5) << "\n";
    std::cout << s.push(2.5) << "\n";
    std::cout << s.push(3.5) << "\n";  // full -> 0
    double v = 0;
    std::cout << s.pop(v) << " " << v << "\n";
    std::cout << s.pop(v) << " " << v << "\n";
    std::cout << s.pop(v) << "\n";     // empty -> 0
}
```

Bounded by `cap_`, so `push` can never write past the buffer. Copying is deleted because the class owns a raw pointer; add a move constructor if you need transfers.

