fn longest_common_prefix(words: &[String]) -> String {
    let first = match words.first() {
        Some(w) => w,
        None => return String::new(),
    };
    let mut len = first.len();
    for w in &words[1..] {
        let mut i = 0;
        let a = first.as_bytes();
        let b = w.as_bytes();
        let max = len.min(b.len());
        while i < max && a[i] == b[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            break;
        }
    }
    first[..len].to_string()
}

