def merge_intervals(intervals):
    if not intervals:
        return []
    ordered = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    merged = [list(ordered[0])]
    for start, end in ordered[1:]:
        if start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return [tuple(iv) for iv in merged]


if __name__ == "__main__":
    assert merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]
    assert merge_intervals([(5, 5), (1, 2)]) == [(1, 2), (5, 5)]
    assert merge_intervals([(1, 4), (2, 3)]) == [(1, 4)]  # contained interval
    assert merge_intervals([]) == []
    assert merge_intervals([(-3, -1), (-1, 0)]) == [(-3, 0)]  # touching
    print("ok")
```

Sorting first makes the sweep linear after the O(n log n) sort. The `end > merged[-1][1]` check keeps a fully contained interval from shrinking the merged end, and touching endpoints (`-1` meets `-1`) merge since the comparison is `<=`.

