#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        std::size_t idx = (head_ + N - size_) % N;
        --size_;
        return data_[idx];
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int i = 1; i <= 5; ++i) rb.push(i);
    std::cout << "size=" << rb.size() << '\n';
    while (auto v = rb.pop()) std::cout << *v << '\n';
