import heapq

class RollingMedian:
    def __init__(self, window: int):
        if window <= 0:
            raise ValueError("window must be positive")
        self.window = window
        self.buffer: list[float] = []
        self.low: list[float] = []   # max-heap via negation
        self.high: list[float] = []  # min-heap

    def add(self, value: float) -> float | None:
        self.buffer.append(value)
        if len(self.buffer) > self.window:
            self._remove(self.buffer.pop(0))
        self._push(value)
        return self.median()

    def _push(self, value: float) -> None:
        if self.low and value <= -self.low[0]:
            heapq.heappush(self.low, -value)
        else:
            heapq.heappush(self.high, value)
        self._rebalance()

    def _remove(self, value: float) -> None:
        if self.low and value <= -self.low[0]:
            self.low.remove(-value)
            heapq.heapify(self.low)
        else:
            self.high.remove(value)
            heapq.heapify(self.high)
        self._rebalance()

    def _rebalance(self) -> None:
        while len(self.low) > len(self.high) + 1:
            heapq.heappush(self.high, -heapq.heappop(self.low))
        while len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def median(self) -> float | None:
        if not self.low:
            return None
        if len(self.low) == len(self.high):
            return (-self.low[0] + self.high[0]) / 2
        return float(-self.low[0])


if __name__ == "__main__":
    rm = RollingMedian(3)
    for x in [1, 3, 2, 8, 5, 4]:
        print(x, "->", rm.add(x))
