use std::collections::HashMap;

/// Return the `n` most frequent words as (word, count), sorted by count
/// descending, then word ascending so ties are deterministic.
pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let key = word
            .trim_matches(|c: char| !c.is_alphanumeric())
            .to_lowercase();
        if !key.is_empty() {
            *counts.entry(key).or_insert(0) += 1;
        }
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    assert!(top_words("", 3).is_empty());
    let text = "the cat and the dog and the bird";
    assert_eq!(top_words(text, 2), vec![("the".to_string(), 3), ("and".to_string(), 2)]);
    assert_eq!(top_words("A a b", 2)[0], ("a".to_string(), 2));
    println!("ok");
}
```

`split_whitespace` ignores repeated spaces, `trim_matches` strips punctuation so `"cat,"` becomes `cat`, and lowercasing before counting makes `A` and `a` the same key.

```cpp
#include <algorithm>
#include <cassert>
#include <iostream>
#include <random>
#include <vector>

// Returns index of target, or -1. Requires v to be sorted ascending.
int binary_search_index(const std::vector<int>& v, int target) {
    int lo = 0;
    int hi = static_cast<int>(v.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == target) return mid;
        if (v[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    assert(binary_search_index({}, 5) == -1);
    assert(binary_search_index({7}, 7) == 0);
    assert(binary_search_index({7}, 8) == -1);

    std::mt19937 rng(42);
    std::uniform_int_distribution<int> dist(-50, 50);
    for (int trial = 0; trial < 1000; ++trial) {
        int n = dist(rng) + 50;
        std::vector<int> v(n);
        for (auto& x : v) x = dist(rng);
        std::sort(v.begin(), v.end());
        int target = dist(rng);
        int got = binary_search_index(v, target);
        bool linear_found = std::find(v.begin(), v.end(), target) != v.end();
        if (linear_found) assert(got >= 0 && v[got] == target);
        else assert(got == -1);
    }
    std::cout << "ok\n";
}
```

`mid = lo + (hi - lo) / 2` avoids overflow on huge vectors. The randomized check compares the index result against `std::find`, so both hits and misses are covered.

```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T: Copy> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        RingBuffer {
            data: (0..capacity).map(|_| None).collect(),
            head: 0,
            len: 0,
        }
    }

    pub fn push(&mut self, value: T) {
        let cap = self.data.len();
        let idx = (self.head + self.len) % cap;
        if self.len == cap {
            // Overwrite oldest and advance head.
            self.data[self.head] = Some(value);
            self.head = (self.head + 1) % cap;
        } else {
            self.data[idx] = Some(value);
            self.len += 1;
        }
    }

    pub fn iter(&self) -> impl Iterator<Item = T> + '_ {
        let cap = self.data.len();
        (0..self.len).map(move |i| {
            self.data[(self.head + i) % cap].expect("slot filled within len")
        })
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    rb.push(1);
    rb.push(2);
    assert_eq!(rb.len, 2);
    rb.push(3);
    rb.push(4); // overwrites 1
    let got: Vec<i32> = rb.iter().collect();
    assert_eq!(got, vec![2, 3, 4]);
    println!("ok");
}
```

Writes go to `(head + len) % cap`. When full, the new value lands on the oldest slot and `head` advances, so iteration always yields the `len` newest values in oldest-first order.

```cpp
#include <cassert>
#include <iostream>
#include <unordered_map>

// Memoized Fibonacci. Returns 0 for n == 0. Values beyond n = 93
// overflow unsigned long long, so callers should stay within that range.
unsigned long long fib(unsigned n, std::unordered_map<unsigned, unsigned long long>& memo) {
    if (n < 2) return n;
    auto it = memo.find(n);
    if (it != memo.end()) return it->second;
    unsigned long long value = fib(n - 1, memo) + fib(n - 2, memo);
    memo.emplace(n, value);
    return value;
}

unsigned long long fib(unsigned n) {
    std::unordered_map<unsigned, unsigned long long> memo;
    return fib(n, memo);
}

int main() {
    assert(fib(0) == 0ULL);
    assert(fib(1) == 1ULL);
    assert(fib(10) == 55ULL);
    assert(fib(50) == 12586269025ULL);
    std::cout << "fib(90) = " << fib(90) << "\n";
    return 0;
}
```

Recursion with a memo map turns the exponential tree into linear work. `fib(90) = 2880067194370816120` fits in 64 bits; `fib(94)` is the first that overflows `unsigned long long`, so the comment caps safe input at 93.

