```cpp
#include <iostream>
#include <queue>
#include <vector>
#include <functional>
#include <iomanip>

class RunningMedian {
public:
    void add(int x) {
        if (lower_.empty() || x <= lower_.top()) lower_.push(x);
        else upper_.push(x);
        // rebalance: lower may have at most one more element than upper
        if (lower_.size() > upper_.size() + 1) {
            upper_.push(lower_.top());
            lower_.pop();
        } else if (upper_.size() > lower_.size()) {
            lower_.push(upper_.top());
            upper_.pop();
        }
    }

    double median() const {
        if (lower_.empty()) return 0.0;
        if (lower_.size() == upper_.size())
            return (lower_.top() + upper_.top()) / 2.0;
        return static_cast<double>(lower_.top());
    }

private:
    std::priority_queue<int> lower_;                                   // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> upper_; // min-heap
};

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    RunningMedian rm;
    int x;
    std::cout << std::fixed << std::setprecision(1);
    bool any = false;
    while (std::cin >> x) {
        rm.add(x);
        std::cout << rm.median() << "\n";
        any = true;
    }
    if (!any) std::cout << "no input\n";
    return 0;
}
```

Each `add` runs in O(log n) so the whole stream is O(n log n). Input like `5 15 1 3` prints `5.0 10.0 5.0 4.0`.

