```c
#include <stdio.h>
#include <stdlib.h>

#define INITIAL_CAP 8

typedef enum { OK = 0, FULL = -1, EMPTY = -2 } status_t;

typedef struct {
    int *data;
    size_t len;
    size_t cap;
} IntStack;

static int stack_init(IntStack *s, size_t cap) {
    s->data = malloc(cap * sizeof *s->data);
    if (!s->data) return 0;
    s->len = 0;
    s->cap = cap;
    return 1;
}

static void stack_free(IntStack *s) {
    free(s->data);
    s->data = NULL;
    s->len = s->cap = 0;
}

static status_t stack_push(IntStack *s, int v) {
    if (s->len == s->cap) {
        size_t ncap = s->cap ? s->cap * 2 : INITIAL_CAP;
        int *tmp = realloc(s->data, ncap * sizeof *tmp);
        if (!tmp) return FULL;
        s->data = tmp;
        s->cap = ncap;
    }
    s->data[s->len++] = v;
    return OK;
}

static status_t stack_pop(IntStack *s, int *out) {
    if (s->len == 0) return EMPTY;
    *out = s->data[--s->len];
    return OK;
}

static status_t stack_peek(const IntStack *s, int *out) {
    if (s->len == 0) return EMPTY;
    *out = s->data[s->len - 1];
    return OK;
}

int main(void) {
    IntStack s;
    if (!stack_init(&s, 0)) { fputs("oom\n", stderr); return 1; }

    int top = 0;
    if (stack_pop(&s, &top) == EMPTY) puts("pop on empty -> EMPTY");

    for (int i = 0; i < 20; i++) stack_push(&s, i * i);
    if (stack_peek(&s, &top) == OK) printf("top = %d\n", top);

    while (stack_pop(&s, &top) == OK) printf("%d ", top);
    putchar('\n');

    stack_free(&s);
    return 0;
}
```

Capacity starts at 0 and doubles on first push, so no fixed limit blocks real workloads. Every failure path returns a distinct status instead of aborting.

```rust
/// Parse a single `KEY=VALUE` line. Returns None for blanks and comments.
fn parse_env_line(line: &str) -> Option<(String, String)> {
    let trimmed = line.trim();
    if trimmed.is_empty() || trimmed.starts_with('#') {
        return None;
    }

    let (raw_key, raw_val) = trimmed.split_once('=')?;
    let key = raw_key.trim();
    if key.is_empty() {
        return None;
    }

    let val = raw_val.trim();
    let value = if let Some(inner) = val.strip_prefix('"') {
        // double-quoted: honor \" and \\, then look for closing quote
        let mut out = String::new();
        let mut chars = inner.chars();
        let mut closed = false;
        while let Some(c) = chars.next() {
            match c {
                '\\' => match chars.next() {
                    Some('"') => out.push('"'),
                    Some('\\') => out.push('\\'),
                    Some(other) => { out.push('\\'); out.push(other); }
                    None => return None,
                },
                '"' => { closed = true; break; }
                other => out.push(other),
            }
        }
        if !closed { return None; }
        out
    } else {
        // unquoted: strip an inline comment that follows whitespace
        let cut = val.find(" #").unwrap_or(val.len());
        val[..cut].trim_end().to_string()
    };

    Some((key.to_string(), value))
}

fn main() {
    let samples = [
        "NAME=xt",
        "QUOTED=\"hello world\"",
        "ESCAPED=\"a\\\"b\"",
        "COMMENT=value # trailing",
        "# whole line",
        "EMPTY=",
        "BAD=\"unterminated",
    ];
    for s in samples {
        println!("{:?} -> {:?}", s, parse_env_line(s));
    }
}
```

Malformed lines (`BAD=` above) return `None` rather than panicking, and escaped quotes survive round-trips.

