#include <iostream>
#include <string>
#include <stack>
#include <unordered_map>

struct Result {
    bool valid;
    size_t index;   // first offending position, only meaningful when !valid
    char expected;  // ')' ']' '}' for an unmatched opener, 0 otherwise
};

Result check(const std::string& s) {
    static const std::unordered_map<char, char> match{{')', '('}, {']', '['}, {'}', '{'}};
    std::stack<std::pair<char, size_t>> st;  // opener + its index

    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push({c, i});
        } else if (auto it = match.find(c); it != match.end()) {
            if (st.empty() || st.top().first != it->second) {
                return {false, i, 0};
            }
            st.pop();
        }
        // any other character is ignored
    }

    if (!st.empty()) {
        return {false, st.top().second, 0};
    }
    return {true, 0, 0};
}

int main() {
    const std::string cases[] = {"([]){}[]", "([)]", "(()", ")", "{[()]}"};
    for (const auto& s : cases) {
        Result r = check(s);
        if (r.valid) {
            std::cout << s << " -> valid\n";
        } else {
            std::cout << s << " -> invalid at index " << r.index << "\n";
        }
    }
    return 0;
}
```

