```python
import functools
import random
import time
from typing import Callable, Tuple, Type


def retry(
    attempts: int = 3,
    base: float = 0.1,
    factor: float = 2.0,
    max_delay: float = 10.0,
    exceptions: Tuple[Type[BaseException], ...] = (Exception,),
) -> Callable:
    """Retry the wrapped callable with exponential backoff + full jitter."""
    def decorator(fn: Callable) -> Callable:
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            delay = base
            for attempt in range(1, attempts + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    if attempt == attempts:
                        raise
                    sleep_for = min(delay, max_delay)
                    sleep_for = random.uniform(0, sleep_for)  # full jitter
                    time.sleep(sleep_for)
                    delay *= factor
        return wrapper
    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base=0.01)
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return "ok"

    print(flaky(), "after", calls["n"], "calls")
```

`functools.wraps` preserves the wrapped function's name. Jitter uses `random.uniform(0, delay)` (full jitter) to avoid thundering-herd retries; the last attempt re-raises rather than sleeping one more time.

