#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur != NULL) {
        Node *nxt = cur->next;  // save before rewiring
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    return prev;  // new head
}

static Node *push(Node *head, int v) {
    Node *n = malloc(sizeof(*n));
    if (!n) { perror("malloc"); exit(1); }
    n->value = v;
    n->next = head;
    return n;
}

static void print(const Node *head) {
    for (; head; head = head->next) printf("%d ", head->value);
    putchar('\n');
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; ++i) head = push(head, i);
    print(head);           // 5 4 3 2 1
    head = reverse(head);
    print(head);           // 1 2 3 4 5

    head = reverse(NULL);  // empty list stays empty
    print(head);
    return 0;
}
```

