```cpp
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (size_ == N) return false;      // full: reject, do not overwrite
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;  // empty
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    constexpr std::size_t capacity() const { return N; }
    bool empty() const { return size_ == 0; }

private:
    T data_[N]{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << "\n"; // 111
    std::cout << rb.push(4) << "\n";                              // 0 (full)
    while (auto v = rb.pop()) std::cout << *v << ' ';            // 1 2 3
    std::cout << "\nempty=" << rb.empty() << "\n";
}
```

Fixed capacity `N` is a template parameter, so the backing array is stack-allocated with no heap use. `push` returns `false` when full instead of silently dropping data, and `pop` returns `std::nullopt` when empty.

