```cpp
#include <condition_variable>
#include <iostream>
#include <mutex>
#include <optional>
#include <queue>
#include <thread>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t cap) : cap_(cap) {}

    void push(int v) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [this] { return q_.size() < cap_ || closed_; });
        if (closed_) return;
        q_.push(v);
        not_empty_.notify_one();
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [this] { return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;  // closed and drained
        int v = q_.front();
        q_.pop();
        not_full_.notify_one();
        return v;
    }

    void close() {
        std::lock_guard<std::mutex> lk(m_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<int> q_;
    std::mutex m_;
    std::condition_variable not_empty_, not_full_;
    bool closed_ = false;
};

int main() {
    BoundedQueue q(4);
    std::thread producer([&] { for (int i = 0; i < 10; ++i) q.push(i); q.close(); });
    int sum = 0, got = 0;
    while (auto v = q.pop()) { sum += *v; ++got; }
    producer.join();
    std::cout << got << " items, sum=" << sum << '\n';  // 10 items, sum=45
    return 0;
}
