#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define RING_CAP 8

typedef struct {
    uint8_t buf[RING_CAP];
    size_t head;   /* next write */
    size_t tail;   /* next read  */
    size_t count;
    size_t overflow;
} ring_t;

static void ring_init(ring_t *r) {
    memset(r, 0, sizeof *r);
}

static bool ring_push(ring_t *r, uint8_t v) {
    if (r->count == RING_CAP) {
        r->overflow++;
        return false;
    }
    r->buf[r->head] = v;
    r->head = (r->head + 1) % RING_CAP;
    r->count++;
    return true;
}

static bool ring_pop(ring_t *r, uint8_t *out) {
    if (r->count == 0) {
        return false;
    }
    *out = r->buf[r->tail];
    r->tail = (r->tail + 1) % RING_CAP;
    r->count--;
    return true;
}

int main(void) {
    ring_t r;
    ring_init(&r);
    for (int i = 0; i < 10; ++i) {
        ring_push(&r, (uint8_t)i);
    }
    printf("overflow=%zu count=%zu\n", r.overflow, r.count);  /* 2, 8 */

    uint8_t v;
    while (ring_pop(&r, &v)) {
        printf("%u ", v);
    }
    putchar('\n');
    return 0;
}
