```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& item) {
        data_[head_] = item;
        head_ = (head_ + 1) % N;
        if (size_ < N) {
            ++size_;
        }
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

    // oldest element is at tail_, newest at (head_ - 1)
    const T& at(std::size_t i) const {
        if (i >= size_) throw std::out_of_range("index");
        std::size_t tail = (head_ + N - size_) % N;
        return data_[(tail + i) % N];
    }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int v : {1, 2, 3, 4, 5}) rb.push(v);
    if (rb.size() != 3) return 1;
    if (rb.at(0) != 3 || rb.at(1) != 4 || rb.at(2) != 5) return 1;
    std::cout << "ok\n";
    return 0;
}
```

Keeps `head_` and `size_` so `at(0)` is the oldest surviving element. `N` must be non-zero at compile time; `std::array<T, 0>` is ill-formed.

