bool balanced(const std::string& s) {
    std::stack<char> st;
    const std::unordered_map<char, char> close_to_open{{
        {')', '('}, {']', '['}, {'}', '{'}}};
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (close_to_open.count(c)) {
            if (st.empty() || st.top() != close_to_open.at(c)) return false;
            st.pop();
        }
        // other characters are ignored
    }
    return st.empty();
}

