#include <iostream>

struct Node {
    int value;
    Node* next;
};

Node* merge(Node* a, Node* b) {
    Node dummy{0, nullptr};
    Node* tail = &dummy;
    while (a && b) {
        if (a->value <= b->value) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

Node* push(Node* head, int v) {
    return new Node{v, head};
}

void print(Node* head) {
    for (Node* n = head; n; n = n->next)
        std::cout << n->value << (n->next ? " " : "\n");
}

void free_list(Node* head) {
    while (head) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    // Build 1->3->5 by pushing in reverse.
    Node* a = nullptr;
    for (int v : {5, 3, 1}) a = push(a, v);

    Node* b = nullptr;
    for (int v : {6, 4, 2}) b = push(b, v);

    Node* merged = merge(a, b);
    print(merged);            // 1 2 3 4 5 6
    free_list(merged);
    return 0;
}
```
Iterative merge with a stack dummy node avoids recursion depth limits. Empty lists fall through the `while` and `tail->next` handles the remainder.

