```python
class BoundedStack:
    """A fixed-capacity LIFO stack."""

    def __init__(self, capacity: int):
        if capacity < 0:
            raise ValueError("capacity must be non-negative")
        self._capacity = capacity
        self._items: list = []

    def push(self, value) -> None:
        if len(self._items) >= self._capacity:
            raise OverflowError(f"stack is full ({self._capacity})")
        self._items.append(value)

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self):
        if not self._items:
            raise IndexError("peek from empty stack")
        return self._items[-1]

    def is_empty(self) -> bool:
        return not self._items

    def __len__(self) -> int:
        return len(self._items)


if __name__ == "__main__":
    s = BoundedStack(2)
    assert s.is_empty()
    s.push("a")
    s.push("b")
    assert s.peek() == "b" and len(s) == 2
    try:
        s.push("c")
        raise AssertionError("expected OverflowError")
    except OverflowError:
        pass
    assert s.pop() == "b" and s.pop() == "a"
    assert s.is_empty()
    try:
        s.pop()
        raise AssertionError("expected IndexError")
    except IndexError:
        pass
    print("ok")
```
Explicit exceptions on full/empty keep the failure visible instead of silently dropping values. Capacity 0 is allowed and every push raises.

