pub fn parse_version(s: &str) -> Result<Version, String> {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 3 {
        return Err(format!("expected 3 dot-separated parts, got {}", parts.len()));
    }
    let nums: Result<Vec<u32>, _> = parts.iter().map(|p| p.parse::<u32>()).collect();
    match nums {
        Ok(v) if v == [v[0], v[1], v[2]] => Ok(Version { major: v[0], minor: v[1], patch: v[2] }),
        Ok(_) => unreachable!(),
        Err(_) => Err(format!("non-numeric component in {s:?}")),
    }
}

fn main() {
    assert_eq!(parse_version("1.20.3").unwrap(), Version { major: 1, minor: 20, patch: 3 });
    assert!(parse_version("1.20").is_err());
    assert!(parse_version("1.20.3.4").is_err());
    assert!(parse_version("1.a.3").is_err());
    assert!(parse_version("").is_err());
    assert_eq!(parse_version("0.0.0").unwrap(), Version { major: 0, minor: 0, patch: 0 });
    println!("ok");
}
