template <typename T>
std::ptrdiff_t index_of(const std::vector<T>& v, const T& target) {
    for (std::size_t i = 0; i < v.size(); ++i) {
        if (v[i] == target) {
            return static_cast<std::ptrdiff_t>(i);
        }
    }
    return -1;
}

