    std::vector<std::string> words{"red", "green", "blue"};
    std::cout << index_of(words, std::string("blue")) << '\n';  // 2

    std::vector<int> empty;
    std::cout << index_of(empty, 1) << '\n';   // -1
    return 0;
}
