#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) {
        perror("malloc");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(const Node *head) {
    for (const Node *n = head; n; n = n->next)
        printf("%d ", n->value);
    putchar('\n');
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; ++i) head = push(head, i);
    print_list(head);
    head = reverse(head);
    print_list(head);

    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
```

`push` prepends, so the list starts as `5 4 3 2 1`. Reversal rewires each `next` pointer in one pass, producing `1 2 3 4 5`, and the final loop frees every node.

```rust
use std::collections::HashMap;

fn collatz_len(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {
    let mut stack: Vec<u64> = Vec::new();
    let mut cur = n;
    while cur != 1 && !memo.contains_key(&cur) {
        stack.push(cur);
        cur = if cur % 2 == 0 { cur / 2 } else { 3 * cur + 1 };
    }
    let mut len = if cur == 1 { 1 } else { memo[&cur] };
    while let Some(v) = stack.pop() {
        len += 1;
        memo.insert(v, len);
    }
    memo[&n]
}

fn main() {
    let mut memo = HashMap::new();
    memo.insert(1, 1);
    let mut best = (0u64, 0u64);
    for n in 1..=1_000_000u64 {
        let len = collatz_len(n, &mut memo);
        if len > best.1 {
            best = (n, len);
        }
    }
    println!("longest: n={} len={}", best.0, best.1);
}
```

The iterative walk records the unknown chain on a stack, stops when it hits a memoized value, then backfills each entry on the way out. This avoids recursion depth issues and prints the longest chain under one million.

