```rust
/// Merges two sorted slices into a single sorted `Vec`.
///
/// # Examples
/// ```
/// let a = [1, 3, 5];
/// let b = [2, 4, 6];
/// assert_eq!(merge_sorted(&a, &b), vec![1, 2, 3, 4, 5, 6]);
/// ```
pub fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a: Vec<i32> = vec![];
    let b = vec![7, 8, 9];
    assert_eq!(merge_sorted(&a, &b), vec![7, 8, 9]);
    assert_eq!(merge_sorted(&b, &a), vec![7, 8, 9]);
    println!("ok");
}
```
The `<=` on line 10 keeps the merge stable: equal elements from `a` are emitted before those from `b`. `extend_from_slice` drains whichever slice still has remaining items in one shot, and the `Vec::with_capacity` call avoids reallocations during the loop. Empty inputs on either side fall through to the two `extend_from_slice` calls.

