import csv
from collections import defaultdict
from pathlib import Path


def totals_by_currency(path: str) -> dict[str, float]:
    """Sum `amount` per `currency` in a CSV with a header.

    Malformed rows (bad number, missing currency) are skipped, not fatal.
    Returns an empty dict if the file does not exist.
    """
    p = Path(path)
    if not p.is_file():
        return {}

    totals: dict[str, float] = defaultdict(float)
    with p.open(newline="", encoding="utf-8-sig") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            currency = (row.get("currency") or "").strip().upper()
            if not currency:
                continue
            try:
                amount = float((row.get("amount") or "").strip())
            except ValueError:
                continue
            totals[currency] += amount
    return dict(totals)


if __name__ == "__main__":
    sample = "date,amount,currency\n2024-01-01,10.5,USD\n2024-01-02,oops,EUR\n2024-01-03,5,EUR\n"
    Path("t.csv").write_text(sample, encoding="utf-8")
    print(totals_by_currency("t.csv"))  # {'USD': 10.5, 'EUR': 5.0}
    print(totals_by_currency("missing.csv"))
```
The `utf-8-sig` encoding strips a byte-order mark so a BOM-prefixed header still matches column names. `DictReader` gives `None` for short rows, hence the `or ""` guards before `.strip()`. `defaultdict(float)` keeps the accumulator simple; the final `dict()` conversion returns a plain dict rather than a defaultdict subclass.

