}

std::optional<std::map<std::string, std::string>> parse(std::string_view input) {
    std::map<std::string, std::string> out;
    std::size_t pos = 0;
    while (pos <= input.size()) {
        auto end = input.find(';', pos);
        if (end == std::string_view::npos) end = input.size();
        auto field = trim(input.substr(pos, end - pos));
        if (!field.empty()) {
            auto eq = field.find('=');
            if (eq == std::string_view::npos) return std::nullopt;
            auto key = trim(field.substr(0, eq));
            if (key.empty()) return std::nullopt;
            if (out.count(std::string(key))) return std::nullopt;  // duplicate
            out.emplace(std::string(key), std::string(trim(field.substr(eq + 1))));
        }
        if (end == input.size()) break;
        pos = end + 1;
    }
    return out;
}

int main() {
    if (auto cfg = parse(" host = localhost ; port=8080 ;; debug = true ")) {
        for (const auto& [k, v] : *cfg) std::cout << k << " -> " << v << '\n';
    } else {
        std::cout << "invalid config\n";
    }
    std::cout << (parse("a=1;a=2") ? "ok" : "dup rejected") << '\n';
}
```
`trim` returns a view, so `parse` only allocates when inserting keys and values into the map. Empty fields between doubled `;` are skipped rather than treated as errors. A field without `=` or an empty key returns `nullopt`; a repeated key is rejected the same way, and the caller decides how to report it.

```python
def longest_palindrome(s: str) -> str:
    """Expand around every center; returns the first longest palindrome found."""
    if not s:
        return ""
    start, end = 0, 0

    def expand(lo: int, hi: int) -> tuple[int, int]:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - 1  # shrink to the last valid bounds

    for i in range(len(s)):
        # odd-length: single character center
        l1, r1 = expand(i, i)
        # even-length: center between i and i+1
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    tests = {"babad": "bab", "cbbd": "bb", "": "", "a": "a",
             "forgeeksskeegfor": "geeksskeeg", "\u4e2d\u6587\u5b57": "\u4e2d\u6587\u5b57"}
    for text, expected in tests.items():
        got = longest_palindrome(text)
        assert len(got) == len(expected), (text, got, expected)
    print("ok")
```
Both odd and even centers are checked at each index, which is what makes a single loop sufficient. The `expand` helper walks outward and returns the last valid `(lo, hi)` after the loop overruns by one on each side. Comparison uses length only, so ties keep the earliest palindrome. Unicode code points work because Python strings index by code point, not byte.

```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUCKETS 4096
#define MAX_WORD 63

typedef struct Entry {
    char word[MAX_WORD + 1];
    unsigned long count;
    struct Entry *next;
} Entry;

static Entry *table[BUCKETS];

static unsigned long hash(const char *s) {
    unsigned long h = 5381;
    while (*s) h = h * 33u + (unsigned char)*s++;
    return h % BUCKETS;
}

static void add(const char *w) {
    unsigned long b = hash(w);
    for (Entry *e = table[b]; e; e = e->next) {
        if (strcmp(e->word, w) == 0) { e->count++; return; }
    }
    Entry *e = malloc(sizeof *e);
    if (!e) { perror("malloc"); exit(1); }
    snprintf(e->word, sizeof e->word, "%s", w);
    e->count = 1;
    e->next = table[b];
    table[b] = e;
}

static int cmp(const void *a, const void *b) {
    const Entry *x = *(const Entry *const *)a, *y = *(const Entry *const *)b;
    if (x->count != y->count) return x->count < y->count ? 1 : -1;
    return strcmp(x->word, y->word);
}

int main(void) {
    char buf[MAX_WORD + 1];
    int c, n = 0;
    while ((c = getchar()) != EOF) {
        if (isalpha((unsigned char)c) || c == '\'') {
            if (n < MAX_WORD) buf[n++] = (char)tolower((unsigned char)c);
        } else if (n > 0) {
            buf[n] = '\0';
            add(buf);
            n = 0;
        }
    }
    if (n > 0) { buf[n] = '\0'; add(buf); }

    size_t total = 0;
    for (int i = 0; i < BUCKETS; i++)
        for (Entry *e = table[i]; e; e = e->next) total++;

    Entry **all = malloc(total * sizeof *all);
    if (!all) { perror("malloc"); return 1; }
    size_t k = 0;
    for (int i = 0; i < BUCKETS; i++)
        for (Entry *e = table[i]; e; e = e->next) all[k++] = e;

    qsort(all, total, sizeof *all, cmp);
    size_t top = total < 10 ? total : 10;
    for (size_t i = 0; i < top; i++)
        printf("%lu %s\n", all[i]->count, all[i]->word);

    free(all);
    for (int i = 0; i < BUCKETS; i++) {
        Entry *e = table[i];
        while (e) { Entry *next = e->next; free(e); e = next; }
    }
    return 0;
}
```
The djb2 hash spread across 4096 buckets keeps lookups near constant time for typical input. Words longer than 63 characters are truncated to the buffer bound instead of overflowing. Ties are broken alphabetically in `cmp` so the output order is deterministic. `getchar` returns `int`, and comparing against `EOF` after casting to `unsigned char` for the ctype calls avoids undefined behavior on negative char values.

