```cpp
#include <atomic>
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

template <std::size_t N>
class RingBuffer {
    static_assert(N >= 2, "capacity must allow one empty slot");
    std::vector<double> buf_{N};
    std::atomic<std::size_t> head_{0};  // next write
    std::atomic<std::size_t> tail_{0};  // next read

public:
    bool push(double v) {
        const std::size_t h = head_.load(std::memory_order_relaxed);
        const std::size_t next = (h + 1) % N;
        if (next == tail_.load(std::memory_order_acquire)) return false;  // full
        buf_[h] = v;
        head_.store(next, std::memory_order_release);
        return true;
    }

    std::optional<double> pop() {
        const std::size_t t = tail_.load(std::memory_order_relaxed);
        if (t == head_.load(std::memory_order_acquire)) return std::nullopt;  // empty
        double v = buf_[t];
        tail_.store((t + 1) % N, std::memory_order_release);
        return v;
    }
};

int main() {
    RingBuffer<4> rb;
    rb.push(1.5);
    rb.push(2.5);
    std::cout << *rb.pop() << '\n';   // 1.5
    std::cout << *rb.pop() << '\n';   // 2.5
    std::cout << (rb.pop() ? "got" : "empty") << '\n';
    rb.push(3.0);
    std::cout << (rb.push(4.0) ? "ok" : "fail") << '\n';
}
```
One slot is intentionally left unused so full and empty are distinguishable without a separate counter. The relaxxed loads on the owning side pair with acquire/release stores so the producer never overwrites unread data and the consumer never reads a half-written slot. `pop` returns `std::optional`, making emptiness explicit rather than overloading a sentinel like `-1.0`. Only one producer and one consumer may call the buffer concurrently; more would need a mutex.

