pub fn is_palindrome(text: &str) -> bool {
    let normalized: Vec<char> = text
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();
    let mut left = 0;
    let mut right = normalized.len();
    while left < right {
        right -= 1;
        if left >= right {
            break;
        }
        if normalized[left] != normalized[right] {
            return false;
        }
        left += 1;
    }
    true
}

