#include <stdio.h>
#include <stddef.h>

static void reverse(int *a, size_t lo, size_t hi) {
    while (lo < hi) {
        int t = a[lo];
        a[lo] = a[hi];
        a[hi] = t;
        ++lo;
        --hi;
    }
}

void rotate_left(int *a, size_t n, size_t k) {
    if (n == 0) return;
    k %= n;
    if (k == 0) return;
    reverse(a, 0, k - 1);
    reverse(a, k, n - 1);
    reverse(a, 0, n - 1);
}

int main(void) {
    int a[] = {1, 2, 3, 4, 5, 6, 7};
    size_t n = sizeof a / sizeof a[0];
    rotate_left(a, n, 3);
    for (size_t i = 0; i < n; ++i) printf("%d%s", a[i], i + 1 == n ? "\n" : " ");
    return 0;
}
```
Reversing three subranges rotates in O(n) time and O(1) extra space. `k %= n` handles k larger than n, and n==0 is guarded.

```rust
use std::collections::HashMap;

struct Node {
    key: u64,
    value: u64,
    prev: Option<usize>,
    next: Option<usize>,
}

pub struct LruCache {
    cap: usize,
    map: HashMap<u64, usize>,
    nodes: Vec<Node>,
    head: Option<usize>,
    tail: Option<usize>,
}

impl LruCache {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        LruCache { cap, map: HashMap::new(), nodes: Vec::new(), head: None, tail: None }
    }

    fn unlink(&mut self, idx: usize) {
        let (prev, next) = (self.nodes[idx].prev, self.nodes[idx].next);
        match prev { Some(p) => self.nodes[p].next = next, None => self.head = next }
        match next { Some(n) => self.nodes[n].prev = prev, None => self.tail = prev }
    }

    fn push_front(&mut self, idx: usize) {
        self.nodes[idx].prev = None;
        self.nodes[idx].next = self.head;
        if let Some(h) = self.head { self.nodes[h].prev = Some(idx); }
        self.head = Some(idx);
        if self.tail.is_none() { self.tail = Some(idx); }
    }

    pub fn get(&mut self, key: u64) -> Option<u64> {
        let idx = *self.map.get(&key)?;
        self.unlink(idx);
        self.push_front(idx);
        Some(self.nodes[idx].value)
    }

    pub fn put(&mut self, key: u64, value: u64) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].value = value;
            self.unlink(idx);
            self.push_front(idx);
            return;
        }
        let idx = self.nodes.len();
        self.nodes.push(Node { key, value, prev: None, next: None });
        self.push_front(idx);
        self.map.insert(key, idx);
        if self.map.len() > self.cap {
            if let Some(t) = self.tail {
                self.unlink(t);
                self.map.remove(&self.nodes[t].key);
            }
        }
    }
}
```
A Vec-backed free list keeps node indices stable so the HashMap can store them. `get` moves a hit to the front; `put` evicts the tail when over capacity.

```cpp
#include <algorithm>
#include <cstddef>
#include <stdexcept>
#include <vector>

template <typename T>
T kth_smallest(std::vector<T> v, std::size_t k) {
    if (k == 0 || k > v.size()) {
        throw std::out_of_range("k out of range");
    }
    std::size_t target = k - 1;
    std::size_t lo = 0, hi = v.size() - 1;
    while (lo < hi) {
        // Median-of-three pivot keeps common cases fast.
        std::size_t mid = lo + (hi - lo) / 2;
        if (v[mid] < v[lo]) std::swap(v[mid], v[lo]);
        if (v[hi] < v[lo]) std::swap(v[hi], v[lo]);
        if (v[hi] < v[mid]) std::swap(v[hi], v[mid]);
        std::swap(v[mid], v[lo]);
        const T pivot = v[lo];
        std::size_t i = lo;
        for (std::size_t j = lo + 1; j <= hi; ++j) {
            if (v[j] < pivot) std::swap(v[++i], v[j]);
        }
        std::swap(v[lo], v[i]);
        if (i == target) return v[i];
        if (i < target) lo = i + 1;
        else hi = (i == 0) ? 0 : i - 1;
    }
    return v[lo];
}
```
Quickselect averages O(n) with a median-of-three pivot to avoid sorted-input degeneration. The input is taken by value, so callers keep their vector intact.

