```c
#include <stdio.h>

int binary_search(const int *a, int n, int key) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;   /* avoids overflow */
        if (a[mid] == key) return mid;
        if (a[mid] < key)  lo = mid + 1;
        else               hi = mid - 1;
    }
    return -1;
}

int main(void) {
    int a[] = {1, 3, 5, 7, 9, 11, 13};
    int n = (int)(sizeof a / sizeof a[0]);
    int probes[] = {1, 7, 13, 8, 0};
    for (size_t i = 0; i < sizeof probes / sizeof probes[0]; i++)
        printf("key=%d index=%d\n", probes[i], binary_search(a, n, probes[i]));
    return 0;
}
```

`lo + (hi - lo) / 2` is the overflow-safe midpoint. The loop condition `lo <= hi` lets the last single-element range be checked, so both endpoints are reached.

