```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        bool overwrote = full();
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (overwrote) {
            tail_ = head_;   // oldest element was overwritten
        } else {
            ++size_;
        }
        return overwrote;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full()  const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    std::cout << "size=" << rb.size() << '\n';   // 3
    std::cout << rb.push(4) << '\n';              // 1 (overwrote)
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n';                            // 2 3 4
    return 0;
}
```

Make the overwrite policy explicit via the bool return. When full, advancing `head_` also advances `tail_`, so the oldest slot is silently dropped rather than the write being rejected.

