#include <iostream>
#include <vector>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse_iterative(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

Node* reverse_recursive(Node* head) {
    if (!head || !head->next) return head;
    Node* rest = reverse_recursive(head->next);
    head->next->next = head;
    head->next = nullptr;
    return rest;
}

std::vector<int> to_vector(Node* head) {
    std::vector<int> out;
    for (Node* p = head; p; p = p->next) out.push_back(p->value);
    return out;
}

Node* build(const std::vector<int>& values) {
    Node* head = nullptr;
    Node** tail = &head;
    for (int v : values) {
        *tail = new Node(v);
        tail = &(*tail)->next;
    }
    return head;
}

void destroy(Node* head) {
    while (head) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    for (const std::vector<int>& values : {std::vector<int>{}, std::vector<int>{1}, std::vector<int>{1, 2, 3, 4, 5}}) {
        Node* a = build(values);
        Node* b = build(values);
        auto ia = to_vector(reverse_iterative(a));
        auto ib = to_vector(reverse_recursive(b));
        if (ia != ib) {
            std::cout << "mismatch\n";
            return 1;
        }
        destroy(reverse_iterative(a));
        destroy(b);
    }
    std::cout << "ok\n";
    return 0;
}
