    const bool expected[] = {true, true, true, true, false, false, false, true};
    for (std::size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        bool got = is_balanced(cases[i]);
        if (got != expected[i]) {
            std::cout << "failed on " << cases[i] << "\n";
            return 1;
        }
    }
    std::cout << "ok\n";
    return 0;
