def fib(n):
    """Return F(n) with F(0)=0, F(1)=1 using fast doubling."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def _fib(k):
        # returns (F(k), F(k+1))
        if k == 0:
            return (0, 1)
        a, b = _fib(k >> 1)
        c = a * (2 * b - a)
        d = a * a + b * b
        if k & 1:
            return (d, c + d)
        return (c, d)

    return _fib(n)[0]


