template <typename T>
T median(std::vector<T> values) {
    if (values.empty()) {
        throw std::invalid_argument("median of empty input");
    }
    std::sort(values.begin(), values.end());
    const std::size_t n = values.size();
    if (n % 2 == 1) {
        return values[n / 2];
    }
    return (values[n / 2 - 1] + values[n / 2]) / static_cast<T>(2);
}

int main() {
    assert(median<int>({3, 1, 2}) == 2);
    assert(median<double>({1.0, 2.0, 3.0, 4.0}) == 2.5);
    std::cout << median<int>({7}) << "\n";
}
