#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

static void print_list(const Node *head) {
    for (const Node *p = head; p; p = p->next)
        printf("%d%s", p->value, p->next ? " -> " : "\n");
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 4; i++)
        head = push(head, i);  /* builds 4 -> 3 -> 2 -> 1 */

    head = reverse(head);       /* becomes 1 -> 2 -> 3 -> 4 */
    print_list(head);

    /* empty list */
    print_list(reverse(NULL));

    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
```

Iterative reversal needs three pointers so you don't lose the rest of the list when you flip `next`. `reverse(NULL)` returns `NULL`, so the empty case is safe.

