// Returns -1 if balanced; otherwise the index of the offending character.
static int first_unbalanced(const std::string& s) {
    std::vector<char> st;
    st.reserve(s.size());
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push_back(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return static_cast<int>(i);
            char open = st.back();
            bool match = (open == '(' && c == ')') ||
                         (open == '[' && c == ']') ||
                         (open == '{' && c == '}');
            if (!match) return static_cast<int>(i);
            st.pop_back();
        }
    }
    return st.empty() ? -1 : -2;  // -2: unclosed openers remain
}

int main() {
    const char* cases[] = {"()[]{}", "([)]", "(", "a(b)c", ")x"};
    for (const char* c : cases) {
        int r = first_unbalanced(c);
        std::printf("%-8s -> %d\n", c, r);
    }
    return 0;
}
