#include <string>

static void reverse_range(std::string& s, std::size_t lo, std::size_t hi) {
    while (lo < hi) std::swap(s[lo++], s[hi--]);
}

std::string reverse_words(const std::string& input) {
    std::string s;
    s.reserve(input.size());
    // collapse whitespace
    bool in_space = false;
    for (char c : input) {
        if (std::isspace(static_cast<unsigned char>(c))) {
            if (!in_space && !s.empty()) s.push_back(' ');
            in_space = true;
        } else {
            s.push_back(c);
            in_space = false;
        }
    }
    while (!s.empty() && s.back() == ' ') s.pop_back();

    reverse_range(s, 0, s.size() ? s.size() - 1 : 0);
    std::size_t start = 0;
    for (std::size_t i = 0; i <= s.size(); ++i) {
        if (i == s.size() || s[i] == ' ') {
            if (i > start) reverse_range(s, start, i - 1);
            start = i + 1;
        }
    }
    return s;
}

int main() {
    std::cout << reverse_words("  hello   world  ") << '\n'; // "world hello"
    std::cout << reverse_words("one") << '\n';               // "one"
    std::cout << reverse_words("   ") << '\n';               // ""
    return 0;
}
