const MOD: u64 = 1_000_000_007;

fn fib_doubling(n: u64) -> u64 {
    // returns (F(n), F(n+1)) mod MOD
    if n == 0 {
        return (0, 1);
    }
    let (a, b) = fib_doubling(n >> 1);
    let c = (a * ((2 * b + MOD - a) % MOD)) % MOD;
    let d = (a * a + b * b) % MOD;
    if n & 1 == 0 {
        (c, d)
    } else {
        (d, (c + d) % MOD)
    }
}

fn fib_naive(n: u64) -> u64 {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let t = (a + b) % MOD;
        a = b;
        b = t;
    }
    a
}

fn main() {
    for n in 0..30u64 {
        assert_eq!(fib_doubling(n).0, fib_naive(n), "mismatch at n={n}");
    }
    println!("fib(90) mod p = {}", fib_doubling(90).0);
