/* Returns true on success, false on error. Result stored in *out. */
bool parse_int(const char *s, int *out) {
    if (s == NULL || out == NULL || *s == '\0') return false;

    const char *p = s;
    bool neg = false;
    if (*p == '+' || *p == '-') {
        neg = (*p == '-');
        p++;
    }
    if (*p == '\0') return false;

    long value = 0;
    for (; *p != '\0'; p++) {
        if (*p < '0' || *p > '9') return false;
        long digit = *p - '0';
        if (value > (LONG_MAX - digit) / 10) return false; /* overflow */
        value = value * 10 + digit;
    }

    value = neg ? -value : value;
    if (value < INT_MIN || value > INT_MAX) return false;
    *out = (int)value;
    return true;
}
