#include <stack>
#include <string>
#include <string_view>
#include <unordered_map>

bool is_balanced(std::string_view s) {
    static const std::unordered_map<char, char> closing{{')', '('}, {']', '['}, {'}', '{'}};
    std::stack<char> open;

    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                open.push(c);
                break;
            case ')': case ']': case '}':
                if (open.empty()) return false;
                if (open.top() != closing.at(c)) return false;
                open.pop();
                break;
            default:
                break; // non-bracket characters are ignored
        }
    }
    return open.empty();
}
