The stack tracks the most recent opener; each closer must match `open.top()` or the string is unbalanced. Leftover openers at the end also fail.

```rust
use std::ffi::CStr;
use std::os::raw::c_char;

/// Reverses the bytes of a NUL-terminated C string in place.
/// Does not handle non-UTF-8 bytes specially; it swaps raw bytes.
///
/// # Safety
/// `ptr` must point to a valid, writable, NUL-terminated byte buffer.
pub unsafe fn reverse_c_string(ptr: *mut c_char) {
    if ptr.is_null() {
        return;
    }
    let len = CStr::from_ptr(ptr).to_bytes().len();
    if len <= 1 {
        return;
    }

    let mut left = 0usize;
    let mut right = len - 1;
    while left < right {
        let l = ptr.add(left);
        let r = ptr.add(right);
        let tmp = *l;
        *l = *r;
        *r = tmp;
        left += 1;
        right -= 1;
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::ffi::CString;

    #[test]
    fn reverses() {
        let mut s = CString::new("abcdef").unwrap().into_bytes_with_nul();
        unsafe { reverse_c_string(s.as_mut_ptr() as *mut c_char) };
        assert_eq!(&s[..s.len() - 1], b"fedcba");
    }

    #[test]
    fn null_is_noop() {
        unsafe { reverse_c_string(std::ptr::null_mut()) };
    }
}
```
The length comes from `CStr::from_ptr` rather than `strlen`, the swap loop uses `CString`-owned mutable bytes in the test, and the explicit null check makes the documented no-op contract hold.

```cpp
#include <array>
#include <cstddef>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    void push(int value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        std::size_t tail = (head_ + N - size_) % N;
        int value = data_[tail];
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    static constexpr std::size_t capacity() { return N; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};
```
`push` always writes and advances `head_`; once `size_ == N` the oldest entry is implicitly overwritten. `pop` computes the tail from `head_ - size_` modulo `N` and returns `std::nullopt` when empty.

```python
import argparse
import hashlib
import sys
from collections import defaultdict
from pathlib import Path

CHUNK = 1 << 20  # 1 MiB


def sha256_of(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as fh:
        for chunk in iter(lambda: fh.read(CHUNK), b""):
            digest.update(chunk)
    return digest.hexdigest()


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Find duplicate files by SHA-256.")
    parser.add_argument("directory", type=Path)
    parser.add_argument("-q", "--quiet", action="store_true")
    args = parser.parse_args(argv)

    if not args.directory.is_dir():
        print(f"not a directory: {args.directory}", file=sys.stderr)
        return 1

    by_hash: dict[str, list[Path]] = defaultdict(list)
    for path in sorted(args.directory.rglob("*")):
        if path.is_file():
            try:
                by_hash[sha256_of(path)].append(path)
            except OSError as exc:
                print(f"skip {path}: {exc}", file=sys.stderr)

    duplicates = {h: ps for h, ps in by_hash.items() if len(ps) > 1}
    if not duplicates:
        if not args.quiet:
            print("no duplicates found")
        return 0

    for digest, paths in duplicates.items():
        print(f"{digest[:12]}  {len(paths)} copies")
        for p in paths:
            print(f"    {p}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
```
Streams each file in 1 MiB chunks so memory stays flat, groups by hex digest, and reports only digests with more than one path. Unreadable files are skipped with a warning rather than crashing the run.

