```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int v) {
    Node *n = malloc(sizeof(Node));
    if (!n) { perror("malloc"); exit(1); }
    n->value = v;
    n->next = head;
    return n;
}

static void print(Node *head) {
    for (Node *c = head; c; c = c->next)
        printf("%d%s", c->value, c->next ? " -> " : "\n");
}

int main(void) {
    Node *list = NULL;                 // empty
    list = reverse(list);
    print(list);                       // prints nothing

    list = push(list, 3);
    list = push(list, 2);
    list = push(list, 1);
    print(list);                       // 1 -> 2 -> 3
    list = reverse(list);
    print(list);                       // 3 -> 2 -> 1

    while (list) {                     // free everything
        Node *next = list->next;
        free(list);
        list = next;
    }
    return 0;
}
```

The classic three-pointer walk flips each `next` to point backward. On an empty list `head` is NULL, the loop is skipped, and NULL is returned, so the caller stays valid.

