```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double v) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = v;
        ++count_;
        return true;
    }

    std::optional<double> pop() {
        if (count_ == 0) return std::nullopt;
        double v = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return v;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    constexpr std::size_t capacity() const { return N; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<3> rb;
    if (!rb.push(1.5)) return 1;
    rb.push(2.5);
    rb.push(3.5);
    if (rb.push(4.5)) { std::cerr << "push should fail when full\n"; return 1; }

    while (auto v = rb.pop()) std::cout << *v << '\n';   // 1.5 2.5 3.5
    if (!rb.empty()) { std::cerr << "should be empty\n"; return 1; }
    if (rb.pop().has_value()) { std::cerr << "pop on empty must fail\n"; return 1; }

    std::cout << "ok\n";
    return 0;
}
```

`push` returns false when full instead of overwriting, so no data is silently lost. `pop` uses `std::optional` to signal empty without sentinel values. The modular index arithmetic wraps both directions and keeps it O(1).

```c
#include <stdio.h>
#include <stdint.h>

static void print_bits(uint32_t v) {
    char buf[32];
    int i = 0;
    if (v == 0) {
        putchar('0');
        return;
    }
    while (v > 0) {
        buf[i++] = (char)('0' + (v & 1u));
        v >>= 1;
    }
    while (i > 0) putchar(buf[--i]);
}

int main(void) {
    long long values[] = {0, 1, 5, 255, 1024, -1, -42};
    for (size_t k = 0; k < sizeof(values)/sizeof(values[0]); ++k) {
        long long n = values[k];
        if (n < 0) {
            printf("-%lld = -", n);
            print_bits((uint32_t)(-n));
        } else {
            printf("%lld = ", n);
            print_bits((uint32_t)n);
        }
        putchar('\n');
    }
    return 0;
}
```

Bits are collected into a buffer least-significant first, then printed in reverse. Zero is special-cased to a single `0` or the loop would emit nothing. For negatives we print a leading minus and convert the magnitude, since two's-complement output would be confusing for a decimal-to-binary display. Magnitudes are held in `uint32_t`, so `-n` is safe even for large `long long` inputs within that range.

