bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;

    bool negative = false;
    if (*s == '+' || *s == '-') {
        negative = (*s == '-');
        s++;
    }
    if (*s == '\0') return false;

    long acc = 0;
    for (; *s; s++) {
