#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

// Single-threaded ring buffer. For multi-threaded use, guard push/pop
// with a mutex or use atomics for head/tail; this class is NOT thread-safe.
template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
        else tail_ = (tail_ + 1) % N; // overwrite oldest
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[tail_];
        tail_ = (tail_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    static constexpr std::size_t capacity() { return N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4); // overwrites 1
    std::cout << *rb.pop() << " " << *rb.pop() << "\n"; // 2 3
    if (rb.pop()) throw std::logic_error("expected empty");
    std::cout << "size=" << rb.size() << "\n";
}
