fn column_sum(contents: &str, col: usize) -> (f64, usize, usize) {
    let mut total = 0.0;
    let mut good = 0usize;
    let mut bad = 0usize;

    for line in contents.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        match line.split(',').nth(col).map(str::trim).and_then(|f| f.parse::<f64>().ok()) {
            Some(v) => {
                total += v;
                good += 1;
            }
            None => bad += 1,
        }
    }

    (total, good, bad)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("usage: {} <file> <column-index>", args[0]);
        process::exit(2);
    }
    let path = &args[1];
    let col: usize = match args[2].parse() {
        Ok(c) => c,
        Err(_) => { eprintln!("column index must be a non-negative integer"); process::exit(2); }
    };

    let contents = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(e) => { eprintln!("cannot read {path}: {e}"); process::exit(1); }
    };

    let (total, good, bad) = column_sum(&contents, col);
    println!("sum: {total}");
    println!("good rows: {good}");
    println!("skipped rows: {bad}");
}
```

Blank lines and `#` comments are ignored; rows missing the column or holding a non-numeric value are counted as skipped rather than aborting the whole file, so one malformed line does not lose the rest of the data.

```python
from collections import OrderedDict


class LRUCache:
    """A fixed-capacity cache that evicts the least recently used key."""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._store: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._store:
            return None
        self._store.move_to_end(key)
        return self._store[key]

    def put(self, key, value) -> None:
        if key in self._store:
            self._store.move_to_end(key)
        self._store[key] = value
        if len(self._store) > self.capacity:
            self._store.popitem(last=False)

    def __len__(self) -> int:
        return len(self._store)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1
    c.put("c", 3)            # evicts "b"
    assert c.get("b") is None
    c.put("a", 9)            # update, "a" stays
    assert c.get("a") == 9
    assert len(c) == 2
    print("all checks passed")
```

`OrderedDict` tracks recency: reads and updates move a key to the end, and eviction pops from the front. Re-inserting an existing key refreshes its position instead of adding a duplicate.

