template <typename T>
std::optional<T> max_element_safe(const std::vector<T>& values) {
    if (values.empty()) {
        return std::nullopt;
    }
    T best = values[0];
    for (std::size_t i = 1; i < values.size(); ++i) {
        if (values[i] > best) {
            best = values[i];
        }
    }
    return best;
}

int main() {
    std::vector<int> nums{3, -7, 12, 0, 5};
    if (auto m = max_element_safe(nums)) {
        std::cout << "max: " << *m << '\n';
    } else {
        std::cout << "empty input\n";
    }

    std::vector<int> empty;
    std::cout << (max_element_safe(empty) ? "has value" : "no value") << '\n';
    return 0;
}
```

Returning `std::optional<T>` makes the empty case explicit instead of relying on a sentinel value or undefined behaviour. The loop starts at index 1 since `best` already holds the first element, and negative values sort correctly because only `>` is used.

