use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();

    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }

    let mut ranked: Vec<(String, usize)> = counts.into_iter().collect();
    ranked.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    ranked.truncate(n);
    ranked
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ranks_by_count_then_name() {
        let text = "The cat, the dog. The DOG!";
        assert_eq!(
            top_words(text, 2),
            vec![("the".to_string(), 3), ("dog".to_string(), 2)]
        );
    }

    #[test]
    fn empty_and_punctuation_only() {
        assert!(top_words("", 5).is_empty());
        assert!(top_words("..., !!!", 5).is_empty());
    }

    #[test]
    fn n_larger_than_distinct() {
        assert_eq!(top_words("a a b", 10), vec![("a".to_string(), 2), ("b".to_string(), 1)]);
    }
}
```

Lowercasing is done per character with `to_lowercase` so multi-byte Unicode letters are handled, and the alphanumeric filter drops punctuation before counting. The sort key uses `b.1.cmp(&a.1)` for descending counts with `then_with` breaking ties alphabetically. An empty string and pure punctuation both yield no words, which the tests pin down.

```c
#include <stdio.h>

void reverse(char *s) {
    if (s == NULL) {
        return;
    }
    size_t len = 0;
    while (s[len] != '\0') {
        ++len;
    }
    if (len < 2) {
        return;
    }

    size_t left = 0;
    size_t right = len - 1;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        ++left;
        --right;
    }
}

static void show(const char *label, char *s) {
    reverse(s);
    printf("%s: %s\n", label, s);
}

int main(void) {
    char empty[] = "";
    char single[] = "a";
    char even[] = "abcd";
    char odd[] = "hello";

    show("empty", empty);
    show("single", single);
    show("even", even);
    show("odd", odd);
    reverse(NULL);
    printf("null handled\n");
    return 0;
}
```

Length is computed with a manual scan, and the swap loop stops when the two indices meet, so odd-length strings leave the middle character untouched while even-length strings swap all pairs. The `NULL` guard covers the degenerate case without masking a real bug. `size_t` is used because the length can never be negative.

```rust
/// Fast doubling: F(2k) = F(k) * (2*F(k+1) - F(k))
///               F(2k+1) = F(k)^2 + F(k+1)^2
fn fib_pair(n: u64) -> (u128, u128) {
    if n == 0 {
        return (0, 1);
    }
    let (a, b) = fib_pair(n / 2);
    let c = a * (2 * b - a);
    let d = a * a + b * b;
    if n % 2 == 0 {
        (c, d)
    } else {
        (d, c + d)
    }
}

pub fn fibonacci(n: u64) -> u128 {
    assert!(n <= 90, "n must be <= 90 to fit u128");
    fib_pair(n).0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn small_values() {
        assert_eq!(fibonacci(0), 0);
        assert_eq!(fibonacci(1), 1);
        assert_eq!(fibonacci(10), 55);
    }

    #[test]
    fn top_of_range() {
        assert_eq!(fibonacci(90), 2880067194370816120);
    }

    #[test]
    #[should_panic]
    fn rejects_too_large() {
        fibonacci(91);
    }
}
```

Fast doubling computes two consecutive values per recursive level, so the depth is logarithmic in `n` rather than linear. The recurrence is exact in `u128` for `n <= 90`; `F(90)` is about 2.88e18 and still fits, while the function asserts rather than silently returning a wrapped value. The odd/even branch picks the pair elements that correspond to `n` itself.

