import csv
import sys
from collections import defaultdict


def average_scores(path):
    """Return {name: average} from a headerless (name, score) CSV."""
    totals = defaultdict(float)
    counts = defaultdict(int)

    with open(path, newline="", encoding="utf-8") as handle:
        reader = csv.reader(handle)
        for lineno, row in enumerate(reader, start=1):
            if not row or all(cell.strip() == "" for cell in row):
                continue
            if len(row) != 2:
                raise ValueError(f"line {lineno}: expected 2 fields, got {len(row)}")
            name, raw_score = row[0].strip(), row[1].strip()
            if not name:
                raise ValueError(f"line {lineno}: empty name")
            try:
                score = float(raw_score)
            except ValueError as exc:
                raise ValueError(f"line {lineno}: bad score {raw_score!r}") from exc
            totals[name] += score
            counts[name] += 1

    return {name: totals[name] / counts[name] for name in totals}


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: python avg_scores.py <file.csv>", file=sys.stderr)
        raise SystemExit(2)

    averages = average_scores(sys.argv[1])
    if not averages:
        print("no rows")
    else:
        for name in sorted(averages):
            print(f"{name}\t{averages[name]:.2f}")
```

Blank lines are skipped, malformed rows raise with the offending line number, and results are keyed by stripped names so trailing spaces do not split a person into two entries. Sorting happens only at print time, which keeps insertion order irrelevant. `csv.reader` handles quoted fields containing commas correctly.

