#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
T dot_product(const std::vector<T>& a, const std::vector<T>& b) {
    if (a.size() != b.size()) {
        throw std::invalid_argument("dot_product: vector sizes differ");
    }
    T acc{};
    for (std::size_t i = 0; i < a.size(); ++i) {
        acc += a[i] * b[i];
    }
    return acc;
}

int main() {
    std::vector<double> u{1.0, 2.0, 3.0};
    std::vector<double> v{4.0, 5.0, 6.0};
    std::cout << "dot = " << dot_product(u, v) << '\n';

    std::vector<double> empty;
    std::cout << "empty dot = " << dot_product(empty, empty) << '\n';

    std::vector<double> shorter{1.0};
    try {
        dot_product(u, shorter);
    } catch (const std::invalid_argument& err) {
        std::cout << "caught: " << err.what() << '\n';
    }
    return 0;
}
```

The template is generic over the element type, so it works for `double`, `float`, or an integral type. The size mismatch is a hard error via `std::invalid_argument` rather than undefined behavior. Two empty vectors produce `0` because the accumulator is value-initialized with `T acc{}`, which is the correct identity for a sum.

