```cpp
#include <string>
#include <algorithm>

std::string longest_palindrome(const std::string& s) {
    if (s.empty()) return "";
    int start = 0, end = 1;

    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        for (int lo : {i, i + 1}) {
            int l = i, r = lo;
            while (l >= 0 && r < static_cast<int>(s.size()) && s[l] == s[r]) {
                --l;
                ++r;
            }
            ++l; // step back into the palindrome
            if (r - l > end - start) {
                start = l;
                end = r;
            }
        }
    }
    return s.substr(start, end - start);
}
```
Expand around each of the `2n-1` centres: `i` covers odd-length palindromes, `i+1` even-length. After the while loop `l` and `r` sit one past the match, so `++l` restores the last valid index. An empty input short-circuits to `""`, and single characters return themselves.

```rust
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }

    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&["x"], &["a", "b"]), vec!["a", "b", "x"]);
    println!("{:?}", merge_sorted(&[1, 1, 2], &[1, 3]));
}
```
The `<=` keeps the merge stable for equal keys. Once one slice is exhausted, `extend_from_slice` copies the remaining tail in one shot, so no index arithmetic can go out of bounds. Empty slices and fully-ordered halves are both handled by the same loop.

