template <typename T>
class Stack {
public:
    void push(const T& value) { data.push_back(value); }

    std::optional<T> pop() {
        if (data.empty()) return std::nullopt;
        T value = data.back();
        data.pop_back();
        return value;
    }

    const T& top() const {
        if (data.empty()) throw std::out_of_range("top on empty stack");
        return data.back();
    }

    std::size_t size() const { return data.size(); }
    bool empty() const { return data.empty(); }

private:
    std::vector<T> data;
};

int main() {
    Stack<int> s;
    if (s.pop().has_value()) { std::cerr << "unexpected value\n"; return 1; }
    s.push(1);
    s.push(2);
    if (s.top() != 2) return 1;
    if (s.pop() != 2) return 1;
    if (s.size() != 1) return 1;
    std::cout << "ok\n";
}
