#include <array>
#include <cstddef>
#include <optional>

 template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

#include <cassert>
int main() {
    RingBuffer<int, 3> rb;
    assert(rb.empty());
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(!rb.push(4));           // full
    assert(rb.pop() == 1);
    assert(rb.push(4));            // wraps
    assert(rb.pop() == 2);
    assert(rb.pop() == 3);
    assert(rb.pop() == 4);
    assert(!rb.pop().has_value());
