def parse_ipv4(text: str):
    """Return a tuple of 4 ints, or raise ValueError with a reason."""
    parts = text.split(".")
    if len(parts) != 4:
        raise ValueError("need exactly 4 octets")
    out = []
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"non-numeric octet: {part!r}")
        if len(part) > 1 and part[0] == "0":
            raise ValueError(f"leading zero not allowed: {part!r}")
        value = int(part)
        if not 0 <= value <= 255:
            raise ValueError(f"octet out of range: {part!r}")
        out.append(value)
    return tuple(out)


if __name__ == "__main__":
