template <typename T>
void rotate_left(std::vector<T>& v, size_t k) {
    if (v.empty()) return;
    k %= v.size();
    if (k == 0) return;
    std::reverse(v.begin(), v.begin() + k);
    std::reverse(v.begin() + k, v.end());
    std::reverse(v.begin(), v.end());
}

#include <iostream>
int main() {
