```rust
fn quickselect(data: &mut [i32], k: usize) -> Option<i32> {
    if k >= data.len() {
        return None;
    }
    let (mut left, mut right) = (0usize, data.len() - 1);
    while left < right {
        let pivot_index = partition(data, left, right);
        if pivot_index == k {
            return Some(data[k]);
        } else if k < pivot_index {
            right = pivot_index - 1;
        } else {
            left = pivot_index + 1;
        }
    }
    Some(data[k])
}

fn partition(data: &mut [i32], left: usize, right: usize) -> usize {
    let pivot = data[right];
    let mut store = left;
    for i in left..right {
        if data[i] < pivot {
            data.swap(store, i);
            store += 1;
        }
    }
    data.swap(store, right);
    store
}

fn main() {
    let mut values = vec![7, 2, 9, 4, 1, 8];
    assert_eq!(quickselect(&mut values, 0), Some(1));
    assert_eq!(quickselect(&mut values, 5), Some(9));
    assert_eq!(quickselect(&mut values, 6), None);
    println!("ok");
}
