```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define TABLE_CAP 4096

typedef struct {
    char *word;
    int count;
} Entry;

static Entry table[TABLE_CAP];

static unsigned long hash(const char *s) {
    unsigned long h = 5381;
    while (*s) {
        h = ((h << 5) + h) + (unsigned char)*s++;
    }
    return h;
}

static void insert(const char *word) {
    unsigned long idx = hash(word) % TABLE_CAP;
    for (size_t probe = 0; probe < TABLE_CAP; probe++) {
        Entry *e = &table[(idx + probe) % TABLE_CAP];
        if (e->word == NULL) {
            e->word = strdup(word);
            if (!e->word) { perror("strdup"); exit(1); }
            e->count = 1;
            return;
        }
        if (strcmp(e->word, word) == 0) {
            e->count++;
            return;
        }
    }
    fprintf(stderr, "hash table full, table too small\n");
    exit(1);
}

int main(void) {
    char buf[128];
    int ch;
    size_t len = 0;

    while ((ch = getchar()) != EOF) {
        if (isalpha((unsigned char)ch)) {
            if (len + 1 < sizeof buf) buf[len++] = (char)tolower((unsigned char)ch);
        } else if (len > 0) {
            buf[len] = '\0';
            insert(buf);
            len = 0;
        }
    }
    if (len > 0) {
        buf[len] = '\0';
        insert(buf);
    }

    for (size_t i = 0; i < TABLE_CAP; i++) {
        if (table[i].word) {
            printf("%s %d\n", table[i].word, table[i].count);
            free(table[i].word);
        }
    }
    return 0;
}
```

Linear probing with no tombstones is fine because nothing is ever deleted. Tokens longer than 127 characters are silently split, which keeps the buffer bounded; lowercase folding means `The` and `the` count together. The table is fixed at 4096 slots — raise `TABLE_CAP` for larger inputs, since a full table aborts instead of silently dropping counts.

