import csv
import re
import sys

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
REQUIRED = ("id", "name", "email")


def validate(path):
    errors = []
    good = 0
    seen_ids = set()

    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        if reader.fieldnames is None:
            return [], 0, "file is empty"
        missing = [c for c in REQUIRED if c not in reader.fieldnames]
        if missing:
            return [], 0, f"missing column(s): {', '.join(missing)}"

        for lineno, row in enumerate(reader, start=2):
            problems = []
            for col in REQUIRED:
                if not (row.get(col) or "").strip():
                    problems.append(f"missing {col}")
            uid = (row.get("id") or "").strip()
            if uid and uid in seen_ids:
                problems.append(f"duplicate id {uid}")
            elif uid:
                seen_ids.add(uid)
            email = (row.get("email") or "").strip()
            if email and not EMAIL_RE.match(email):
                problems.append(f"invalid email {email!r}")
            if problems:
                errors.append((lineno, "; ".join(problems)))
            else:
                good += 1

    return errors, good, None


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: validate_csv.py <file.csv>", file=sys.stderr)
        sys.exit(2)
    errs, good, fatal = validate(sys.argv[1])
    if fatal:
        print(f"error: {fatal}", file=sys.stderr)
        sys.exit(1)
    for lineno, msg in errs:
        print(f"line {lineno}: {msg}")
    print(f"{good} valid row(s), {len(errs)} invalid", file=sys.stderr)
    sys.exit(1 if errs else 0)
```

Line numbers start at 2 because row 1 is the header. The `email!r` shows the offending value with visible quotes so trailing spaces are obvious. Exit code is 1 when any row fails and 2 for usage errors, so the script composes in pipelines. It never writes a corrected file — that should be the caller's explicit choice.

