#include <string>
#include <stdexcept>
#include <cctype>

// Parse strings like "1h30m15s", "45s", "2h", or "90m20s" into total seconds.
// Throws std::invalid_argument on malformed input, unknown units,
// missing units, or an empty string.
long long parse_duration(const std::string& text) {
    if (text.empty()) {
        throw std::invalid_argument("empty duration");
    }

    long long total = 0;
    size_t i = 0;
    bool saw_component = false;

    while (i < text.size()) {
        if (!std::isdigit(static_cast<unsigned char>(text[i]))) {
            throw std::invalid_argument("expected digit at position " + std::to_string(i));
        }
        long long value = 0;
        while (i < text.size() && std::isdigit(static_cast<unsigned char>(text[i]))) {
            value = value * 10 + (text[i] - '0');
            if (value > 100000000) {
                throw std::invalid_argument("component too large");
            }
            ++i;
        }
        if (i >= text.size()) {
            throw std::invalid_argument("missing unit after value");
        }
        char unit = static_cast<char>(std::tolower(static_cast<unsigned char>(text[i++])));
        switch (unit) {
            case 'h': total += value * 3600; break;
            case 'm': total += value * 60;   break;
            case 's': total += value;        break;
            default:  throw std::invalid_argument(std::string("unknown unit '") + unit + "'");
        }
        saw_component = true;
    }

    if (!saw_component) {
        throw std::invalid_argument("no components");
    }
    return total;
}
```

It rejects a bare number with no unit rather than guessing seconds, because guessing hides caller bugs. The per-component cap prevents overflow on absurd input like `999999999999h`. Units are case-insensitive, and components may appear in any order — `30s1h` sums to the same total, which is unusual but harmless and simplest to reason about.

```rust
/// Return the longest common prefix shared by every string in `words`.
///
/// Returns an empty string if `words` is empty or no common prefix exists.
pub fn longest_common_prefix(words: &[&str]) -> String {
    if words.is_empty() {
        return String::new();
    }

    let first = words[0].as_bytes();
    let mut len = first.len();

    for word in &words[1..] {
        let bytes = word.as_bytes();
        let mut i = 0;
        while i < len && i < bytes.len() && first[i] == bytes[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            break;
        }
    }

    String::from_utf8_lossy(&first[..len]).into_owned()
}

fn main() {
    assert_eq!(longest_common_prefix(&[]), "");
    assert_eq!(longest_common_prefix(&["flower", "flow", "flight"]), "fl");
    assert_eq!(longest_common_prefix(&["dog", "cat"]), "");
    assert_eq!(longest_common_prefix(&["caf\u{e9}", "caf\u{e9}x"]), "caf\u{e9}");
    assert_eq!(longest_common_prefix(&["\u{4f60}\u{597d}", "\u{4f60}\u{597d}"]),
               "\u{4f60}\u{597d}");
    println!("all assertions passed");
}
```

Comparing bytes rather than `char`s keeps it O(total bytes) and index-based. Multi-byte UTF-8 is safe here because a shared byte prefix of valid UTF-8 is itself valid UTF-8; `from_utf8_lossy` is a belt-and-braces guard that can't actually trigger on this path. Empty input returns `""` instead of panicking.

```python
import re


def rle_encode(text):
    """Encode runs of identical characters as <char><count>.

    A run of one is written without a count so the encoding stays compact.
    """
    if not text:
        return ""
    out = []
    i = 0
    n = len(text)
    while i < n:
        j = i
        while j < n and text[j] == text[i]:
            j += 1
        run = j - i
        out.append(text[i] if run == 1 else f"{text[i]}{run}")
        i = j
    return "".join(out)


_RUN_RE = re.compile(r"(.)(\d*)")


def rle_decode(encoded):
    """Inverse of rle_encode. Raises ValueError on malformed input."""
    if not encoded:
        return ""
    out = []
    pos = 0
    for match in _RUN_RE.finditer(encoded):
        if match.start() != pos:
            raise ValueError(f"unexpected character at index {match.start()}")
        char, digits = match.group(1), match.group(2)
        count = int(digits) if digits else 1
        if count == 0:
            raise ValueError(f"zero-length run for {char!r}")
        out.append(char * count)
        pos = match.end()
    if pos != len(encoded):
        raise ValueError(f"trailing input at index {pos}")
    return "".join(out)


if __name__ == "__main__":
    samples = ["", "a", "aaabbbcccd", "\u{4f60}\u{4f60}\u{597d}", "ab"]
    for s in samples:
        enc = rle_encode(s)
        assert rle_decode(enc) == s, (s, enc)
    assert rle_encode("aaabbbcccd") == "a3b3c3d"
    assert rle_decode("a3b3c3d") == "aaabbbcccd"
    for bad in ("a0", "3a", "a2b3x"):
        try:
            rle_decode(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"expected ValueError for {bad!r}")
    print("round-trip and error cases passed")
```

Runs of length one are emitted as the bare character, so `"abc"` stays `"abc"` and round-trips exactly. Decoding rejects a zero count and trailing junk instead of quietly producing wrong output. It counts by `str` characters, so astral-plane emoji and CJK round-trip correctly without slicing a code point in half.

