```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), capacity_(capacity) {}

    bool push(int value) {
        if (size_ == capacity_) return false;
        buf_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == capacity_; }
    std::size_t size() const { return size_; }

private:
    std::vector<int> buf_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    std::cout << "empty: " << rb.empty() << '\n';
    rb.push(1); rb.push(2); rb.push(3);
    std::cout << "overflow rejected: " << (rb.push(4) == false) << '\n';
    while (!rb.empty()) std::cout << *rb.pop() << '\n';
    std::cout << "empty after pops: " << rb.empty() << '\n';
}
```

I used `head_` plus a running `size_` rather than two indices, which keeps the full/empty distinction unambiguous. `push` rejects when full instead of silently overwriting, so callers decide the policy; `pop` returns `std::optional` so empty is not a sentinel value.

