#include <algorithm>
#include <cassert>
#include <iostream>
#include <string>

static void reverse_range(std::string& s, std::size_t lo, std::size_t hi) {
    while (lo < hi) {
        std::swap(s[lo], s[hi]);
        ++lo;
        if (lo >= hi) break;
        --hi;
    }
}

std::string reverse_words(std::string s) {
    reverse_range(s, 0, s.empty() ? 0 : s.size() - 1);
    std::size_t i = 0;
    const std::size_t n = s.size();
    while (i < n) {
        std::size_t j = i;
        while (j < n && s[j] != ' ') ++j;
        if (j > i) reverse_range(s, i, j - 1);
        i = j + 1;
    }
    return s;
}

int main() {
    assert(reverse_words("") == "");
    assert(reverse_words("hello") == "hello");
    assert(reverse_words("hello world") == "world hello");
    assert(reverse_words("the quick brown fox") == "fox brown quick the");
    assert(reverse_words("café au lait") == "lait au café");
    std::cout << "ok\n";
}
```

Two reversals give the result: reverse the whole string, then reverse each word back. `reverse_range` avoids `std::reverse` on iterators to keep the in-place swap logic explicit, and the empty-string guard prevents `size() - 1` underflow.

