struct Node {
    int value;
    struct Node *next;
};

static struct Node *reverse(struct Node *head) {
    struct Node *prev = NULL;
    while (head) {
        struct Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(struct Node *head) {
    for (struct Node *n = head; n; n = n->next) {
        printf("%d%s", n->value, n->next ? " -> " : "\n");
    }
    if (!head) printf("(empty)\n");
}

static void free_list(struct Node *head) {
    while (head) {
        struct Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    struct Node *head = NULL;
    for (int i = 5; i >= 1; --i) {
        struct Node *n = malloc(sizeof *n);
        if (!n) return 1;
        n->value = i;
        n->next = head;
        head = n;
    }
    print_list(head);
    head = reverse(head);
    print_list(head);
    free_list(head);

    struct Node *empty = NULL;
    print_list(reverse(empty));
    return 0;
