#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), capacity_(capacity) {}

    bool full() const { return size_ == capacity_; }
    bool empty() const { return size_ == 0; }

    bool push(int value) {
        if (capacity_ == 0 || full()) return false;
        data_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

private:
    std::vector<int> data_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    for (int i = 1; i <= 5; ++i) {
        std::cout << "push " << i << ": " << (rb.push(i) ? "ok" : "full") << '\n';
        if (rb.full()) std::cout << "  popped " << *rb.pop() << '\n';
    }
