```cpp
#include <cstdio>

struct Node {
    int value;
    Node* next;
};

// Reverse in place: prev trails curr, and each step flips one pointer.
Node* reverse(Node* head) {
    Node* prev = nullptr;
    Node* curr = head;
    while (curr != nullptr) {
        Node* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

void print_list(const Node* head) {
    for (const Node* p = head; p != nullptr; p = p->next) {
        std::printf("%d", p->value);
        if (p->next != nullptr) std::printf(" -> ");
    }
    std::printf("\n");
}

void free_list(Node* head) {
    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    Node* head = nullptr;
    for (int i = 5; i >= 1; --i) {
        head = new Node{i, head};
    }
    std::printf("original: ");
    print_list(head);      // 1 -> 2 -> 3 -> 4 -> 5

    head = reverse(head);
    std::printf("reversed: ");
    print_list(head);      // 5 -> 4 -> 3 -> 2 -> 1

    free_list(head);
    return 0;
}
```

`reverse` is O(n) time and O(1) space, handles empty and single-node lists, and `free_list` releases every node once. Compile with `g++ -std=c++17 -Wall -Wextra -fsanitize=address reverse.cpp`.

```cpp
#include <algorithm>
#include <array>
#include <string>
#include <iostream>
#include <cassert>

int length_of_longest_unique(const std::string& s) {
    // last[c] = index just after the most recent occurrence of byte c.
    std::array<int, 256> last;
    last.fill(-1);
    int best = 0;
    int start = 0;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        const unsigned char c = static_cast<unsigned char>(s[i]);
        if (last[c] >= start) {
            start = last[c] + 1;   // shrink window past the duplicate
        }
        last[c] = i;
        best = std::max(best, i - start + 1);
    }
    return best;
}

int main() {
    assert(length_of_longest_unique("abcabcbb") == 3);  // "abc"
    assert(length_of_longest_unique("bbbbb") == 1);     // "b"
    assert(length_of_longest_unique("pwwkew") == 3);    // "wke"
    assert(length_of_longest_unique("") == 0);
    assert(length_of_longest_unique("\xFF\xFE\xFF") == 2);
    std::cout << "all tests passed\n";
}
```

Tracking `last[c]` as a `std::array<int,256>` indexed by the raw byte covers all input bytes including non-UTF-8 data. The window never moves backward because `last[c]` is clamped against `start`. O(n) time, O(1) extra space.

