use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
pub enum ParseError {
    EmptyField(usize),
    BadNumber { index: usize, source: ParseIntError },
}

/// Parse `"1,2,3"` into `vec![1, 2, 3]`, rejecting empty fields.
pub fn parse_list(input: &str) -> Result<Vec<i64>, ParseError> {
    if input.is_empty() {
        return Ok(Vec::new());
    }
    input
        .split(',')
        .enumerate()
        .map(|(i, field)| {
            let trimmed = field.trim();
            if trimmed.is_empty() {
                Err(ParseError::EmptyField(i))
            } else {
                trimmed
                    .parse::<i64>()
                    .map_err(|source| ParseError::BadNumber { index: i, source })
            }
        })
        .collect()
}

fn main() {
    assert_eq!(parse_list("1,2,3").unwrap(), vec![1, 2, 3]);
    assert_eq!(parse_list(" 4 , -5 ").unwrap(), vec![4, -5]);
    assert_eq!(parse_list("").unwrap(), Vec::<i64>::new());
    assert_eq!(parse_list("1,,2"), Err(ParseError::EmptyField(1)));
    assert!(matches!(parse_list("1,x"), Err(ParseError::BadNumber { index: 1, .. })));
    println!("all tests passed");
}
```

`collect` on an iterator of `Result` short-circuits at the first error, so the index of the offending field is preserved. Fields are trimmed, an empty input yields an empty vec, and overflow from `i64` surfaces as `BadNumber`.

