        let read = reader.read_line(&mut line)?;
        if read == 0 {
            break;
        }
        counts.bytes += read as u64;
        counts.lines += 1;
        counts.words += line.split_whitespace().count() as u64;
    }
    Ok(counts)
}

fn main() -> io::Result<()> {
