    let counts = if path == "-" {
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf)?;
        Counts {
            lines: buf.lines().count() as u64,
            words: buf.split_whitespace().count() as u64,
            bytes: buf.len() as u64,
        }
    } else {
        count(&path)?
    };
    println!("{:>7} {:>7} {:>7} {}", counts.lines, counts.words, counts.bytes, path);
    Ok(())
}
