```cpp
#include <array>
#include <cstddef>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity) {}

    bool push(int value) {
        if (size_ == cap_) return false;
        data_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return cap_; }

private:
    static constexpr std::size_t kMax = 1024;
    std::array<int, kMax> data_{};
    std::size_t cap_;    std::size_t head_ = 0;
    std::size_t size_ = 0;
};
```

`head_` marks the oldest element; new items land at `(head_ + size_) % cap_`. Pushing when full returns `false`, and popping an empty buffer returns `std::nullopt` instead of undefined behaviour.

