```cpp
#include <iostream>
#include <stack>
#include <string>

bool isBalanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.empty();
}

int main() {
    if (!isBalanced("{[()]}")) return 1;
    if (isBalanced("{[(])}"))    return 1;
    if (isBalanced(""))           return 1;
    if (isBalanced("(()"))        return 1;
    if (isBalanced("(]") )        return 1;
    std::cout << "ok\n";
    return 0;
}
```
A stack matches each closing bracket against the most recent opener. Any mismatch, an empty stack on a closer, or leftovers at the end means unbalanced. O(n) time, O(n) space.

```cpp
#include <iostream>
#include <vector>

std::vector<int> mergeSorted(const std::vector<int>& a,
                             const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else              out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5, 7};
    std::vector<int> b{2, 4, 6};
    std::vector<int> expect{1, 2, 3, 4, 5, 6, 7};
    if (mergeSorted(a, b) != expect) return 1;
    if (!mergeSorted({}, {}).empty()) return 1;
    if (mergeSorted({}, {9}) != std::vector<int>{9}) return 1;
    std::cout << "ok\n";
    return 0;
}
```
The `<=` on ties keeps the result stable relative to the left vector. Empty inputs flow through the drain loops unchanged. O(m+n) time.

