use std::collections::BTreeSet;

fn intersection(a: &[i32], b: &[i32]) -> Vec<i32> {
    let set: BTreeSet<i32> = b.iter().copied().collect();
    let mut result: BTreeSet<i32> = BTreeSet::new();
