#include <vector>
#include <iostream>

int binary_search(const std::vector<int>& data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (data[mid] == target) return mid;
        if (data[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> v{1, 3, 5, 7, 9, 11};
    std::cout << binary_search(v, 7) << "\n";   // 3
    std::cout << binary_search(v, 4) << "\n";   // -1
    std::cout << binary_search({}, 1) << "\n";  // -1
}
