use std::time::{Duration, Instant};

struct TokenBucket {
    capacity: f64,
    tokens: f64,
    refill_per_sec: f64,
    last: Instant,
}

impl TokenBucket {
    fn new(capacity: f64, refill_per_sec: f64) -> Self {
        TokenBucket { capacity, tokens: capacity, refill_per_sec, last: Instant::now() }
    }

    fn should_throttle(&mut self, cost: f64) -> bool {
        let now = Instant::now();
        let elapsed = now.duration_since(self.last).as_secs_f64();
        self.tokens = (self.tokens + elapsed * self.refill_per_sec).min(self.capacity);
        self.last = now;
        if self.tokens >= cost {
            self.tokens -= cost;
            false
        } else {
            true
        }
    }
}

fn main() {
    let mut bucket = TokenBucket::new(3.0, 1.0);
    for i in 1..=5 {
        println!("request {i} throttled: {}", bucket.should_throttle(1.0));
    }
    std::thread::sleep(Duration::from_secs(2));
    println!("after sleep throttled: {}", bucket.should_throttle(1.0));
}
