Here is a complete solution. The brute-force version checks every substring, while the center-expansion version is the practical one — it runs in O(n²) time and O(1) extra space.

```python
"""Longest palindromic substring: brute force plus center expansion."""


def _is_palindrome(s: str) -> bool:
    return s == s[::-1]


def longest_palindrome_brute(s: str) -> str:
    """Check every substring. O(n^3) time, O(1) space."""
    if not s:
        return ""
    best = ""
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            candidate = s[i:j]
            if len(candidate) > len(best) and _is_palindrome(candidate):
                best = candidate
    return best


def longest_palindrome(s: str) -> str:
    """Center expansion. O(n^2) time, O(1) space.

    Works on unicode because indexing and slicing operate on code points.
    """
    if not s:
        return ""

    def expand(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    start, end = 0, 0
    for i in range(len(s)):
        for left, right in ((i, i), (i, i + 1)):
            l, r = expand(left, right)
            if r - l > end - start:
                start, end = l, r
    return s[start:end + 1]


if __name__ == "__main__":
    assert longest_palindrome("") == ""
    assert longest_palindrome("a") == "a"
    assert longest_palindrome("babad") in {"bab", "aba"}
    assert longest_palindrome("cbbd") == "bb"
    assert longest_palindrome("éé") == "éé"
    assert longest_palindrome("😀a😀") == "😀a😀"
    print(longest_palindrome("forgeeksskeegfor"))
```

Notes: the brute-force helper is only there for cross-checking; the center-expansion function is what you want in production. Emoji work because Python strings index by code point — careful with grapheme clusters if you ever need those.

A small state machine handles quoted fields correctly, including `""` escapes and commas inside quotes.

```cpp
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

std::vector<std::string> parse_csv_line(const std::string& line) {
    std::vector<std::string> fields;
    std::string current;
    bool in_quotes = false;

    for (std::size_t i = 0; i < line.size(); ++i) {
        char c = line[i];
        if (in_quotes) {
            if (c == '"') {
                if (i + 1 < line.size() && line[i + 1] == '"') {
                    current.push_back('"');
                    ++i;               // skip escaped quote
                } else {
                    in_quotes = false;
                }
            } else {
                current.push_back(c);
            }
        } else if (c == '"') {
            in_quotes = true;
        } else if (c == ',') {
            fields.push_back(current);
            current.clear();
        } else {
            current.push_back(c);
        }
    }
    fields.push_back(current);
    return fields;
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        if (line.empty()) {
            std::cout << "(empty line)\n";
            continue;
        }
        auto fields = parse_csv_line(line);
        for (std::size_t i = 0; i < fields.size(); ++i) {
            std::cout << '[' << i << "] " << fields[i] << '\n';
        }
        std::cout << "---\n";
    }
    return 0;
}
```

Sample run:

```
$ printf 'a,b,"c,d"\n\n"say ""hi""",2\n' | ./csvparse
[0] a
[1] b
[2] c,d
---
(empty line)
[0] say "hi"
[1] 2
---
```

If a quoted field is never closed, the parser keeps consuming to end of line — mention this in your caller if malformed input is possible.

