Splitting on `!is_alphanumeric` discards punctuation and whitespace in one pass, so `"Hello, hello!"` counts as two `hello`. Ties are broken alphabetically to keep output deterministic. An empty input prints `(no words)` instead of an empty block.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *push(Node *head, int value) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    node->value = value;
    node->next = head;
    return node;
}

Node *reverse_iterative(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

Node *reverse_recursive(Node *head) {
    if (head == NULL || head->next == NULL) {
        return head;
    }
    Node *new_head = reverse_recursive(head->next);
    head->next->next = head;
    head->next = NULL;
    return new_head;
}

void print_list(const Node *head) {
    for (const Node *cur = head; cur != NULL; cur = cur->next) {
        printf("%d ", cur->value);
    }
    putchar('\n');
}

void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 1; i <= 5; ++i) {
        list = push(list, i);
    }
    print_list(list);                       /* 5 4 3 2 1 */
    list = reverse_iterative(list);
    print_list(list);                       /* 1 2 3 4 5 */
    list = reverse_recursive(list);
    print_list(list);                       /* 5 4 3 2 1 */
    list = reverse_iterative(list);
    list = reverse_iterative(list);
    print_list(list);                       /* 1 2 3 4 5 */
    free_list(list);

    Node *empty = NULL;
    empty = reverse_iterative(empty);
    empty = reverse_recursive(empty);
    print_list(empty);                      /* prints empty line */
    return 0;
}
```

Both reversals return `NULL` unchanged for an empty list; the recursive version's base case also covers a single node, so it never dereferences `head->next->next` on a one-element list.

