```cpp
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), cap_(capacity), head_(0), size_(0) {}

    bool push(int value) {
        if (size_ == cap_) return false;
        data_[(head_ + size_) % cap_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == cap_; }
    std::size_t size() const { return size_; }

private:
    std::vector<int> data_;
    std::size_t cap_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    std::cout << "push 1: " << rb.push(1) << "\n";
    std::cout << "push 2: " << rb.push(2) << "\n";
    std::cout << "push 3: " << rb.push(3) << "\n";
    std::cout << "push 4: " << rb.push(4) << "\n";  // false
    std::cout << "pop: " << *rb.pop() << "\n";     // 1
    std::cout << "pop: " << *rb.pop() << "\n";     // 2
    std::cout << "full: " << rb.full() << "\n";    // false
    while (!rb.empty()) rb.pop();
    std::cout << "empty after drain: " << rb.empty() << "\n";
    return 0;
}
```

`pop` returns `std::optional`, so empty is distinguishable from a stored `0`; capacity 0 would divide by zero, so callers should pass at least 1.

