```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1
    c.put("c", 3)          # evicts "b"
    assert c.get("b") is None
    assert c.get("a") == 1
    assert c.get("c") == 3
    c.put("c", 30)         # update existing, no eviction
    assert len(c) == 2
    assert c.get("c") == 30
    print("all assertions passed")
```

`OrderedDict.move_to_end` marks a key as recently used; `popitem(last=False)` evicts the oldest. `get` on a missing key returns `None`.

```c
#include <stdio.h>
#include <stdint.h>

int popcount_kernighan(uint32_t n) {
    int count = 0;
    while (n) {
        n &= n - 1;  /* clears the lowest set bit */
        ++count;
    }
    return count;
}

int main(void) {
    struct { uint32_t value; int expected; } cases[] = {
        {0u, 0},
        {1u, 1},
        {0xFFFFFFFFu, 32},
        {0x80000000u, 1},
        {0x0000FFFFu, 16},
        {0xAAAAAAAAu, 16},
    };

    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        int got = popcount_kernighan(cases[i].value);
        printf("0x%08X -> %d (expected %d)\n",
               cases[i].value, got, cases[i].expected);
        if (got != cases[i].expected) {
            fprintf(stderr, "mismatch at case %zu\n", i);
            return 1;
        }
    }
    printf("all cases passed\n");
    return 0;
}
```

Kernighan's algorithm runs in O(number of set bits), faster than shifting all 32 positions. `n &= n - 1` clears the least-significant set bit each iteration.

