#include <cassert>
#include <cstdio>

int josephus(int n, int k) {
    if (n <= 0 || k <= 0) return -1;
    int survivor = 0;
    for (int i = 1; i <= n; ++i) {
        survivor = (survivor + k) % i;
    }
    return survivor;
}

