    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1, 1], &[1, 1]), vec![1, 1, 1, 1, 1]);
    assert_eq!(merge_sorted(&[], &[9, 10]), vec![9, 10]);
