#include <assert.h>
#include <stddef.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    for (size_t i = 0; i < len / 2; ++i) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    assert(strcmp(a, "olleh") == 0);

    char b[] = "";
    reverse_in_place(b);
    assert(strcmp(b, "") == 0);

    reverse_in_place(NULL);

    char c[] = "ab";
    reverse_in_place(c);
    assert(strcmp(c, "ba") == 0);

    return 0;
}
```

The swap loop stops at `len / 2`, so odd-length strings leave the middle character in place. `NULL` returns immediately and the empty string executes zero swaps.

