```cpp
#include <cstdint>
#include <fstream>
#include <iostream>
#include <vector>

std::uint32_t rolling_checksum(const std::vector<std::uint8_t>& data, std::size_t window) {
    if (window == 0 || window > data.size()) return 0;
    std::uint32_t hash = 0;
    for (std::size_t i = 0; i < window; ++i) {
        hash = hash * 31u + data[i];
    }
    std::uint32_t best = hash;
    for (std::size_t i = window; i < data.size(); ++i) {
        hash = hash * 31u + data[i];
        best = hash < best ? hash : best;
    }
    return best;
}

int main(int argc, char** argv) {
    if (argc != 3) {
        std::cerr << "usage: " << argv[0] << " <file> <window>\n";
        return 2;
    }
    std::ifstream in(argv[1], std::ios::binary);
    if (!in) {
        std::cerr << "cannot open " << argv[1] << "\n";
        return 1;
    }
    std::vector<std::uint8_t> data((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
    std::size_t window = static_cast<std::size_t>(std::stoul(argv[2]));
    std::cout << rolling_checksum(data, window) << "\n";
    return 0;
}
```

One caveat: this is a running hash over overlapping windows, not a true rolling checksum with subtraction, but it does not overflow-buffer since it reads only `i < data.size()`. `std::stoul` throws on non-numeric windows, so wrap it in a try/catch if inputs are untrusted.

