```c
#include <stdio.h>
#include <ctype.h>
#include <string.h>

int is_palindrome(const char *s) {
    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0) return 1;
    j -= 1;

    while (i < j) {
        while (i < j && !isalnum((unsigned char)s[i])) i++;
        while (i < j && !isalnum((unsigned char)s[j])) j--;
        if (tolower((unsigned char)s[i]) != tolower((unsigned char)s[j])) {
            return 0;
        }
        i++;
        if (j == 0) break;
        j--;
    }
    return 1;
}

int main(void) {
    const char *tests[] = {
        "A man, a plan, a canal: Panama",
        "hello",
        "",
        "...",
        "Was it a car or a cat I saw?"
    };
    for (size_t k = 0; k < sizeof(tests) / sizeof(tests[0]); k++) {
        printf("%d  %s\n", is_palindrome(tests[k]), tests[k]);
    }
    return 0;
}
```

The two index walkers skip non-alphanumeric characters on both ends and compare case-insensitively. Empty strings and punctuation-only strings both return `1` because no mismatching pair is ever found. The `(unsigned char)` casts keep `isalnum`/`tolower` from being called with negative values, which is undefined behaviour.

```python
import hashlib
import os
import sys
from collections import defaultdict


def file_digest(path: str, chunk_size: int = 1 << 20) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        while chunk := fh.read(chunk_size):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root: str) -> dict[str, list[str]]:
    by_size: dict[int, list[str]] = defaultdict(list)
    for dirpath, _dirs, files in os.walk(root):
        for name in files:
            full = os.path.join(dirpath, name)
            try:
                size = os.path.getsize(full)
            except OSError as exc:
                print(f"skipping {full}: {exc}", file=sys.stderr)
                continue
            if size == 0:
                continue
            by_size[size].append(full)

    groups: dict[str, list[str]] = defaultdict(list)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue
        for path in paths:
            try:
                digest = file_digest(path)
            except OSError as exc:
                print(f"skipping {path}: {exc}", file=sys.stderr)
                continue
            groups[(size, digest)].append(path)  # type: ignore[index]

    return {k: v for k, v in groups.items() if len(v) > 1}  # type: ignore[misc]


if __name__ == "__main__":
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    dups = find_duplicates(target)
    for (size, digest), paths in sorted(dups.items()):
        print(f"{digest[:12]}  {size} bytes")
        for p in paths:
            print(f"    {p}")
```

Files are grouped by size first, so only same-size candidates get hashed — that prunes most of the work. Hashing streams in 1 MiB chunks, so a 50 GB file never lands in memory. Zero-byte files are ignored and unreadable paths are reported to stderr and skipped rather than crashing the walk.

