```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
    static_assert(N > 0, "capacity must be positive");

public:
    bool push(const T& value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.empty()) return 1;
    if (!rb.push(1) || !rb.push(2) || !rb.push(3)) return 1;
    if (rb.push(4)) return 1;              // full, must reject
    if (rb.pop() != 1 || rb.pop() != 2) return 1;
    if (!rb.push(5) || !rb.push(6)) return 1;
    while (auto v = rb.pop()) std::cout << *v << '\n';
    if (!rb.empty()) return 1;
    return 0;
}
```

The buffer lives entirely in a `std::array`, so nothing is heap-allocated. `head_`, `tail_` and `size_` are tracked separately, which is what lets `full()` and `empty()` coexist at the same head/tail value. `push` returns `false` when full rather than overwriting; `pop` returns `std::nullopt` when empty. The `% N` wrap is branch-free.

