#include <array>
#include <cstddef>
#include <optional>
#include <iostream>

template <typename T, std::size_t N>
class RingBuffer {
    std::array<T, N> buf_{};
    std::size_t head_ = 0, size_ = 0;

public:
    void push(const T& value) {
        if (size_ == N) {
            buf_[head_] = value;
            head_ = (head_ + 1) % N;
            return;
        }
        buf_[(head_ + size_) % N] = value;
        ++size_;
    }

    std::optional<T> pop() {
        if (size_ == 0)
            return std::nullopt;
        T value = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4);  // overwrites 1
    while (auto v = rb.pop())
        std::cout << *v << '\n';
    std::cout << "empty pop: " << rb.pop().has_value() << '\n';
    return 0;
}
```
On a full buffer `push` overwrites the oldest element by advancing `head_`. `pop` returns `std::nullopt` when empty, so callers never read uninitialised memory.

