    threads = [threading.Thread(target=worker, args=(counter, 10_000)) for _ in range(8)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    print(counter.value)
    assert counter.value == 80_000


if __name__ == "__main__":
    main()
