void reverse_in_place(char *s) {
    if (s == NULL)
        return;
    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0)
        return;
    j -= 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++;
        j--;
    }
}

