#include <optional>
#include <stdexcept>

template <std::size_t N>
class RingBuffer {
public:
    void push(double value) {
        if (count_ == N) {
            throw std::overflow_error("ring buffer full");
        }
        data_[(head_ + count_) % N] = value;
        ++count_;
    }

    std::optional<double> pop() {
        if (count_ == 0) {
            return std::nullopt;
        }
        double value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    std::size_t size() const noexcept { return count_; }
    static constexpr std::size_t capacity() noexcept { return N; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

#include <cassert>
#include <iostream>

int main() {
    RingBuffer<3> rb;
    assert(rb.size() == 0);
    rb.push(1.5);
    rb.push(2.5);
    rb.push(3.5);
    bool threw = false;
    try {
        rb.push(4.5);
    } catch (const std::overflow_error&) {
        threw = true;
    }
    assert(threw);
    assert(rb.pop() == 1.5);
    assert(rb.pop() == 2.5);
    assert(rb.size() == 1);
    std::cout << "remaining size=" << rb.size() << "\n";
}
```

Capacity is a template parameter, so `N` is compile-time known and storage is a plain `std::array`. `pop` returns `std::optional<double>` rather than a sentinel.

