```cpp
#include <cassert>
#include <iostream>
#include <unordered_set>
#include <vector>

std::vector<int> dedupe_preserve_order(const std::vector<int>& input) {
    std::vector<int> out;
    std::unordered_set<int> seen;
    out.reserve(input.size());
    for (int value : input) {
        if (seen.insert(value).second) {
            out.push_back(value);
        }
    }
    return out;
}

// In-place version: overwrites the head of the vector and resizes.
template <typename T>
void dedupe_in_place(std::vector<T>& v) {
    std::unordered_set<T> seen;
    std::size_t write = 0;
    for (std::size_t read = 0; read < v.size(); ++read) {
        if (seen.insert(v[read]).second) {
            v[write++] = v[read];
        }
    }
    v.resize(write);
    v.shrink_to_fit();
}

int main() {
    std::vector<int> v{3, 1, 3, 2, 1, 4, 2};
    auto out = dedupe_preserve_order(v);
    assert((out == std::vector<int>{3, 1, 2, 4}));

    dedupe_in_place(v);
    assert((v == std::vector<int>{3, 1, 2, 4}));

    std::vector<int> empty;
    dedupe_in_place(empty);
    assert(empty.empty());
    std::cout << "ok\n";
}
```

`unordered_set::insert` returns `{iterator, bool}`, so `.second` tells us whether the value was new. The in-place version writes only unique values back into the prefix and then `resize`s.

```python
import functools
import random
import time


def retry(attempts=3, base_delay=0.1, max_delay=2.0, exceptions=(Exception,)):
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            last_exc = None
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
                    if attempt == attempts:
                        break
                    # jitter avoids thundering-herd retries
                    time.sleep(min(delay, max_delay) * (0.5 + random.random() / 2))
                    delay *= 2
            raise last_exc

        return wrapper

    return decorator


if __name__ == "__main__":
    calls = {"n": 0}

    @retry(attempts=4, base_delay=0.001, exceptions=(ValueError,))
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ValueError("not yet")
        return "done"

    assert flaky() == "done"
    assert calls["n"] == 3

    @retry(attempts=2, base_delay=0.001)
    def always_fails():
        raise RuntimeError("boom")

    try:
        always_fails()
    except RuntimeError as exc:
        print("gave up:", exc)
```

`raise last_exc` re-raises the final failure after the last attempt instead of swallowing it. The delay doubles each time and is clamped by `max_delay`; jitter spreads retries.

