use std::collections::HashMap;
use std::fs;
use std::io;

fn parse_kv(contents: &str) -> Result<HashMap<String, String>, String> {
    let mut map = HashMap::new();
    for (idx, raw) in contents.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line
            .split_once('=')
            .ok_or_else(|| format!("line {}: missing '=' in {:?}", idx + 1, line))?;
        let key = key.trim().to_string();
        let value = value.trim().to_string();
        if key.is_empty() {
            return Err(format!("line {}: empty key", idx + 1));
        }
        if let Some(previous) = map.insert(key.clone(), value) {
            return Err(format!(
                "line {}: duplicate key {:?} (previous value {:?})",
                idx + 1,
                key,
                previous
            ));
        }
    }
    Ok(map)
}

fn main() -> io::Result<()> {
    let good = "a=1\n# comment\nb = two\n";
    let map = parse_kv(good).expect("good input should parse");
    assert_eq!(map.get("a").map(String::as_str), Some("1"));
    assert_eq!(map.get("b").map(String::as_str), Some("two"));

    let bad = "a=1\na=2\n";
    let err = parse_kv(bad).unwrap_err();
    assert!(err.contains("duplicate key"), "unexpected: {err}");

    println!("parsed {} keys", map.len());
    Ok(())
}
```

The duplicate branch uses `HashMap::insert` only to *detect* the collision, then returns `Err` — it never accepts the overwrite. Blank lines and `#` comments are skipped.

