def validate_ipv4(addr: str) -> tuple[bool, str]:
    """Return (is_valid, reason). reason is '' when valid."""
    if not isinstance(addr, str):
        return False, "input is not a string"
    if addr == "":
        return False, "empty input"
    parts = addr.split(".")
    if len(parts) != 4:
        return False, f"expected 4 octets, got {len(parts)}"
    for i, part in enumerate(parts, start=1):
        if not part.isdigit():
            return False, f"octet {i} ({part!r}) is not numeric"
        if len(part) > 1 and part[0] == "0":
            return False, f"octet {i} has a leading zero"
        value = int(part)
        if not 0 <= value <= 255:
            return False, f"octet {i} ({value}) is out of range 0-255"
    return True, ""


if __name__ == "__main__":
    cases = ["192.168.1.1", "256.1.1.1", "192.168.1", "192.168.01.1", "a.b.c.d", ""]
