std::vector<std::vector<long long>> pascal(int rows) {
    if (rows < 0) throw std::invalid_argument("rows must be >= 0");
    if (rows > 62) throw std::invalid_argument("rows too large: values overflow 64-bit");
    std::vector<std::vector<long long>> tri;
    tri.reserve(static_cast<std::size_t>(rows));
    for (int r = 0; r < rows; ++r) {
        std::vector<long long> row(r + 1, 1);
        for (int c = 1; c < r; ++c)
            row[c] = tri[r - 1][c - 1] + tri[r - 1][c];
        tri.push_back(std::move(row));
    }
    return tri;
}

int main() {
