            for (std::size_t i = 0; i < row.size(); ++i) {
                if (i) std::cout << ' ';
                std::cout << row[i];
            }
            std::cout << '\n';
        }
    }
    try {
        pascal(-1);
    } catch (const std::exception& e) {
        std::cout << "error: " << e.what() << '\n';
