#include <stdio.h>
#include <ctype.h>

#define MAXLEN 64

int main(void) {
    int counts[MAXLEN + 1] = {0};
    int c, len = 0, in_word = 0, max = 0;

    while ((c = getchar()) != EOF) {
        if (isspace((unsigned char)c)) {
            if (in_word) {
                int bucket = len > MAXLEN ? MAXLEN : len;
                counts[bucket]++;
                if (bucket > max) max = bucket;
                len = 0;
                in_word = 0;
            }
        } else {
            in_word = 1;
            len++;
        }
    }
    if (in_word) {
        int bucket = len > MAXLEN ? MAXLEN : len;
        counts[bucket]++;
        if (bucket > max) max = bucket;
    }

    if (max == 0) {
        puts("no words");
        return 0;
    }

    for (int i = 1; i <= max; i++) {
        if (counts[i] == 0) continue;
        printf("%2d: ", i);
        for (int j = 0; j < counts[i]; j++) putchar('#');
        printf(" (%d)\n", counts[i]);
    }
    return 0;
}
```

Words longer than 64 characters overflow into the last bucket so the program never indexes out of bounds. Whitespace is handled with `isspace` cast to `unsigned char` to avoid undefined behaviour on negative bytes. The empty-input case prints `no words`.

```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : capacity_(capacity) {}

    void push(int value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [this] { return queue_.size() < capacity_; });
        queue_.push(value);
        lock.unlock();
        not_empty_.notify_one();
    }

    std::optional<int> try_pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (queue_.empty()) {
            return std::nullopt;
        }
        int value = queue_.front();
        queue_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

private:
    std::size_t capacity_;
    std::queue<int> queue_;
    std::mutex mutex_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
};
```

`push` blocks while the queue is at capacity; `try_pop` returns `std::nullopt` when empty instead of waiting. Both notify after releasing the lock to avoid waking a thread that then immediately blocks on the mutex.

