def merge_intervals(intervals):
    if not intervals:
        return []
    ordered = sorted(intervals, key=lambda iv: iv[0])
    merged = [list(ordered[0])]
    for lo, hi in ordered[1:]:
        last = merged[-1]
        if lo <= last[1]:
            last[1] = max(last[1], hi)
        else:
            merged.append([lo, hi])
    return [(lo, hi) for lo, hi in merged]


