```cpp
#include <condition_variable>
#include <mutex>
#include <queue>
#include <stdexcept>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(T value) {
        std::unique_lock<std::mutex> lock(m_);
        not_full_.wait(lock, [this] { return q_.size() < cap_ || closed_; });
        if (closed_) throw std::runtime_error("queue closed");
        q_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(m_);
        not_empty_.wait(lock, [this] { return !q_.empty() || closed_; });
        if (q_.empty() && closed_) throw std::runtime_error("queue closed");
        T value = std::move(q_.front());
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(m_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t cap_;
    bool closed_ = false;
    std::queue<T> q_;
    std::mutex m_;
    std::condition_variable not_empty_, not_full_;
};
```

`push` waits while the queue is full, `pop` waits while it is empty, and `close` wakes every waiter so shutdown cannot deadlock. Notify after releasing the lock to avoid waking a thread that immediately blocks again.

