// returns {F(n), F(n+1)} mod MOD
std::pair<std::int64_t, std::int64_t> fib_pair(std::uint64_t n) {
    if (n == 0) return {0, 1};
    auto [a, b] = fib_pair(n >> 1);
    std::int64_t c = a * ((2 * b % MOD - a + MOD) % MOD) % MOD;
    std::int64_t d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1ULL) return {d, (c + d) % MOD};
    return {c, d};
}

int main() {
    for (std::uint64_t n : {0ULL, 1ULL, 10ULL, 40ULL}) {
        std::cout << "F(" << n << ") = " << fib_pair(n).first << '\n';
    }
}
