use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
pub struct ParseError {
    pub line: usize,
    pub message: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "line {}: {}", self.line, self.message)
    }
}

impl std::error::Error for ParseError {}

pub fn parse(input: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut map = HashMap::new();
    for (idx, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line.split_once('=').ok_or_else(|| ParseError {
            line: idx + 1,
            message: format!("missing '=' in {line:?}"),
        })?;
        let key = key.trim();
        if key.is_empty() {
            return Err(ParseError { line: idx + 1, message: "empty key".into() });
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let cfg = "# server\nhost = localhost\nport=8080\n\nname = my app";
    println!("{:?}", parse(cfg).unwrap());
    println!("{:?}", parse("broken line").unwrap_err());
}
```

`split_once` keeps `=` inside values (so `name = a=b` yields `a=b`), blank lines and comments are dropped, and a missing separator reports the 1-based line number. The final line prints the error for the malformed input.

```rust
use std::collections::HashMap;

struct Node {
    key: i32,
    value: i32,
    prev: Option<usize>,
    next: Option<usize>,
}

pub struct LruCache {
    cap: usize,
    map: HashMap<i32, usize>,
    nodes: Vec<Node>,
    head: Option<usize>,
    tail: Option<usize>,
}

impl LruCache {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0, "capacity must be positive");
        Self { cap, map: HashMap::new(), nodes: Vec::new(), head: None, tail: None }
    }

    pub fn get(&mut self, key: i32) -> Option<i32> {
        let idx = *self.map.get(&key)?;
        self.detach(idx);
        self.attach_front(idx);
        Some(self.nodes[idx].value)
    }

    pub fn put(&mut self, key: i32, value: i32) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].value = value;
            self.detach(idx);
            self.attach_front(idx);
            return;
        }
        let idx = self.nodes.len();
        self.nodes.push(Node { key, value, prev: None, next: None });
        self.map.insert(key, idx);
        self.attach_front(idx);
        if self.map.len() > self.cap {
            if let Some(tail) = self.tail {
                self.detach(tail);
                self.map.remove(&self.nodes[tail].key);
            }
        }
    }

    fn detach(&mut self, idx: usize) {
        let (prev, next) = (self.nodes[idx].prev, self.nodes[idx].next);
        match prev {
            Some(p) => self.nodes[p].next = next,
            None => self.head = next,
        }
        match next {
            Some(n) => self.nodes[n].prev = prev,
            None => self.tail = prev,
        }
    }

    fn attach_front(&mut self, idx: usize) {
        self.nodes[idx].prev = None;
        self.nodes[idx].next = self.head;
        if let Some(h) = self.head {
            self.nodes[h].prev = Some(idx);
        }
        self.head = Some(idx);
        if self.tail.is_none() {
            self.tail = Some(idx);
        }
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 1);
    c.put(2, 2);
    println!("{:?}", c.get(1));
    c.put(3, 3);
    println!("{:?}", c.get(2));
}
```

Nodes live in a `Vec` and are addressed by index, which sidesteps the borrow checker headaches of pointer-based lists. `get(1)` returns `Some(1)`, then inserting 3 evicts the least recently used key 2, so `get(2)` is `None`.

