```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 4096
#define MAX_WORD 64

typedef struct Entry {
    char word[MAX_WORD];
    int count;
    struct Entry *next;
} Entry;

static Entry *table[TABLE_SIZE];

static unsigned long hash(const char *s) {
    unsigned long h = 5381;
    for (; *s; s++) h = ((h << 5) + h) + (unsigned char)*s;
    return h % TABLE_SIZE;
}

static void add_word(const char *w) {
    unsigned long idx = hash(w);
    for (Entry *e = table[idx]; e; e = e->next) {
        if (strcmp(e->word, w) == 0) { e->count++; return; }
    }
    Entry *e = malloc(sizeof *e);
    if (!e) { perror("malloc"); exit(1); }
    strncpy(e->word, w, MAX_WORD - 1);
    e->word[MAX_WORD - 1] = '\0';
    e->count = 1;
    e->next = table[idx];
    table[idx] = e;
}

int main(void) {
    char word[MAX_WORD];
    int len = 0, c;
    while ((c = getchar()) != EOF) {
        if (isalpha((unsigned char)c)) {
            if (len < MAX_WORD - 1) word[len++] = (char)tolower((unsigned char)c);
        } else if (len > 0) {
            word[len] = '\0';
            add_word(word);
            len = 0;
        }
    }
    if (len > 0) { word[len] = '\0'; add_word(word); }

    for (int rank = 0; rank < 3; rank++) {
        Entry *best = NULL;
        for (int i = 0; i < TABLE_SIZE; i++)
            for (Entry *e = table[i]; e; e = e->next)
                if (e->count > 0 && (!best || e->count > best->count)) best = e;
        if (!best) break;
        printf("%s %d\n", best->word, best->count);
        best->count = -best->count; /* mark printed */
    }
    return 0;
}
```

The djb2 hash spreads words across 4096 buckets, and each bucket is a linked list so collisions degrade gracefully. Words are lowercased and truncated at 63 chars, and marking a printed entry negative lets the top-three scan avoid a second pass.

