std::vector<int> merge_sorted(const std::vector<int>& a,
                              const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());

    std::size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) {
            out.push_back(a[i++]);
        } else {
            out.push_back(b[j++]);
        }
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5, 9};
    std::vector<int> b{};
    for (int v : merge_sorted(a, b)) std::cout << v << ' ';
    std::cout << '\n';

    std::vector<int> c{2, 4, 4, 6};
    for (int v : merge_sorted(a, c)) std::cout << v << ' ';
    std::cout << '\n';
    return 0;
}
