#include <cstddef>
#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& v, int target) {
    std::size_t lo = 0, hi = v.size();  // half-open [lo, hi)
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (v[mid] == target) return static_cast<int>(mid);
        if (v[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return -1;
}

int main() {
    std::vector<int> v{1, 2, 3, 4, 5};
    std::cout << binary_search(v, 4) << '\n';  // 3
    std::cout << binary_search(v, 6) << '\n';  // -1
    std::cout << binary_search({}, 1) << '\n'; // -1

    std::vector<int> big(1'000'000);
    for (std::size_t i = 0; i < big.size(); ++i) big[i] = static_cast<int>(i);
    std::cout << binary_search(big, 999'999) << '\n';
    return 0;
}
```

The half-open bounds `[lo, hi)` mean `hi = v.size()` is valid and an empty vector is handled without a special case. `mid = lo + (hi - lo) / 2` avoids overflow.

