fn longest_common_prefix<'a>(words: &'a [String]) -> &'a str {
    let first = match words.first() {
        Some(w) => w,
        None => return "",
    };

    let mut len = first.len();
    for w in &words[1..] {
        let max = len.min(w.len());
        let mut i = 0;
        let (a, b) = (first.as_bytes(), w.as_bytes());
        while i < max && a[i] == b[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            return "";
        }
    }
    &first[..len]
}

fn main() {
    let v = vec!["flower".to_string(), "flow".to_string(), "flight".to_string()];
    assert_eq!(longest_common_prefix(&v), "fl");

    let single = vec!["hello".to_string()];
    assert_eq!(longest_common_prefix(&single), "hello");

    let none: Vec<String> = vec![];
    assert_eq!(longest_common_prefix(&none), "");

    let differ = vec!["dog".to_string(), "cat".to_string()];
    assert_eq!(longest_common_prefix(&differ), "");

    println!("ok");
}
