```c
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;

    size_t left = 0;
    size_t right = strlen(s);
    if (right == 0) return;
    right -= 1;  /* index of last character */

    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    printf("%s\n", a);  /* olleh */

    char b[] = "";
    reverse_in_place(b);
    printf("[%s]\n", b);  /* [] */

    char c[] = "x";
    reverse_in_place(c);
    printf("%s\n", c);  /* x */

    reverse_in_place(NULL);  /* no crash */
    return 0;
}
```

Swapping from both ends is O(n) time and O(1) extra space. The `NULL` guard and the empty-string early return cover the edge cases; `strlen` is only called once.

