Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void print(Node* head) {
    bool first = true;
    for (Node* p = head; p; p = p->next) {
        if (!first) std::cout << " -> ";
        std::cout << p->value;
