enum DivError {
    ZeroDivisor,
    NonFinite,
}

impl fmt::Display for DivError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DivError::ZeroDivisor => write!(f, "division by zero"),
            DivError::NonFinite => write!(f, "operand is not finite"),
        }
    }
