fn safe_div(a: f64, b: f64) -> Result<f64, DivError> {
    if !a.is_finite() || !b.is_finite() {
        return Err(DivError::NonFinite);
    }
    if b == 0.0 {
        return Err(DivError::ZeroDivisor);
    }
    Ok(a / b)
}

