from collections.abc import Iterable

def flatten(lst):
    out = []
    stack = [iter(lst)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, Iterable) and not isinstance(item, (str, bytes)):
            stack.append(iter(item))
        elif isinstance(item, int) and not isinstance(item, bool):
