#include <stdbool.h>
#include <stdio.h>

#define RING_CAP 8

typedef struct {
    int buf[RING_CAP];
    size_t head, tail, count;
} ring_t;

void ring_init(ring_t *r) { r->head = r->tail = r->count = 0; }

bool ring_push(ring_t *r, int v) {
    if (r->count == RING_CAP) return false;
    r->buf[r->tail] = v;
    r->tail = (r->tail + 1) % RING_CAP;
    r->count++;
    return true;
}

bool ring_pop(ring_t *r, int *out) {
    if (r->count == 0) return false;
    *out = r->buf[r->head];
    r->head = (r->head + 1) % RING_CAP;
    r->count--;
    return true;
}

int main(void) {
    ring_t r;
    ring_init(&r);
    for (int i = 1; i <= 10; i++) {
        if (!ring_push(&r, i)) printf("full at %d\n", i);
    }
    int v;
    while (ring_pop(&r, &v)) printf("%d ", v);
    printf("\n");
    return 0;
}
