#include <stdio.h>
#include <string.h>

/* Return 1 if byte starts a UTF-8 sequence, 0 if it is a continuation byte. */
static int is_lead(unsigned char c) { return (c & 0xC0) != 0x80; }

/* Reverse a NUL-terminated UTF-8 string in place. */
void utf8_reverse(char *s) {
    size_t n = strlen(s);
    char *left = s;
    char *right = s + n; /* one past the end */

    while (left < right) {
        /* Move right back to the start of the previous codepoint. */
        do {
            right--;
        } while (right > left && !is_lead((unsigned char)*right));

        if (left >= right) break;

        /* Move left forward to the start of the next codepoint. */
        char *lend = left + 1;
        while (lend < right && !is_lead((unsigned char)*lend)) lend++;

        size_t llen = (size_t)(lend - left);
        size_t rlen = 1;
        {
            char *p = right + 1;
            while (p < s + n && !is_lead((unsigned char)*p)) { p++; rlen++; }
        }

        /* Rotate the two chunks by reversing them piecewise. */
        for (size_t i = 0; i < llen / 2; i++) {
            char t = left[i]; left[i] = left[llen - 1 - i]; left[llen - 1 - i] = t;
        }
        for (size_t i = 0; i < rlen / 2; i++) {
            char t = right[i]; right[i] = right[rlen - 1 - i]; right[rlen - 1 - i] = t;
        }
        for (size_t i = 0; i < (llen + rlen) / 2; i++) {
            char *a = left + i;
            char *b = left + llen + rlen - 1 - i;
            char t = *a; *a = *b; *b = t;
        }

        left = lend;
    }
}

int main(void) {
    char sample[] = "h\xC3\xA9llo \xF0\x9F\x8C\x8D"; /* "héllo 🌍" */
    utf8_reverse(sample);
    printf("%s\n", sample);
    return 0;
}
