}

impl Iterator for Fib {
    type Item = u64;

    fn next(&mut self) -> Option<u64> {
        let value = self.a;
        if value > self.limit {
            return None;
        }
        let next = self.a.checked_add(self.b)?;
        self.a = self.b;
        self.b = next;
        Some(value)
    }
}

fn sum_even_terms(limit: u64) -> u64 {
    Fib::new(limit).filter(|n| n % 2 == 0).sum()
}

fn main() {
    assert_eq!(sum_even_terms(0), 0);
    assert_eq!(sum_even_terms(1), 0);
    assert_eq!(sum_even_terms(10), 10); // 2 + 8
    assert_eq!(sum_even_terms(100), 44); // 2 + 8 + 34
    assert_eq!(sum_even_terms(4_000_000), 4613732);
    println!("ok");
}
```

The iterator emits `a` before advancing the pair, so `Fib::new(1)` yields `0` then `1` and stops. `checked_add` makes overflow terminate the sequence instead of panicking or wrapping.

```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T: Copy> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        RingBuffer {
            data: vec![None; capacity],
            head: 0,
            len: 0,
        }
    }

    pub fn push(&mut self, value: T) {
        let cap = self.data.len();
        let tail = (self.head + self.len) % cap;
        if self.len == cap {
            self.data[self.head] = Some(value);
            self.head = (self.head + 1) % cap;
        } else {
            self.data[tail] = Some(value);
            self.len += 1;
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn iter(&self) -> impl Iterator<Item = T> + '_ {
        let cap = self.data.len();
        (0..self.len).map(move |i| self.data[(self.head + i) % cap].unwrap())
    }
}

fn main() {
    let mut buf = RingBuffer::new(3);
    for v in [1, 2, 3, 4] {
        buf.push(v);
    }
    assert_eq!(buf.len(), 3);
    assert_eq!(buf.iter().collect::<Vec<_>>(), vec![2, 3, 4]);

    let mut one = RingBuffer::new(1);
    one.push(7);
    one.push(9);
    assert_eq!(one.iter().collect::<Vec<_>>(), vec![9]);
    println!("ok");
}
```

When full, `push` overwrites the slot at `head` and advances it, which is exactly the overwrite-oldest rule. `iter` walks `len` logical slots from `head` using modulo, so the logical order survives wraparound.

