```cpp
#include <iostream>

struct Node {
    int value;
    Node* next;
    explicit Node(int v, Node* n = nullptr) : value(v), next(n) {}
};

Node* reverse_iter(Node* head) {
    Node* prev = nullptr;
    while (head) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

Node* reverse_rec(Node* head) {
    if (!head || !head->next) return head;
    Node* newHead = reverse_rec(head->next);
    head->next->next = head;
    head->next = nullptr;
    return newHead;
}

void print(Node* head) {
    for (Node* p = head; p; p = p->next)
        std::cout << p->value << (p->next ? " -> " : "\n");
}

int main() {
    Node* head = new Node(1, new Node(2, new Node(3, new Node(4))));
    head = reverse_iter(head);
    print(head);            // 4 -> 3 -> 2 -> 1
    head = reverse_rec(head);
    print(head);            // 1 -> 2 -> 3 -> 4
    while (head) { Node* n = head->next; delete head; head = n; }
}
```
The iterative version is O(n) time, O(1) space; the recursive version is O(n) time, O(n) stack. For a list of a million nodes the recursive form can blow the stack — prefer the iterative one in production. Both handle the empty list and single node.

