use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split(|c: char| !c.is_alphanumeric()) {
        if word.is_empty() {
            continue;
        }
        *counts.entry(word.to_lowercase()).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "the quick brown fox; the lazy dog. The DOG!";
    let top = top_words(text, 3);
    assert_eq!(top[0], ("the".to_string(), 3));
    assert_eq!(top[1], ("dog".to_string(), 2));
    assert_eq!(top.len(), 3);
    println!("{:?}", top);
}
```
Splitting on non-alphanumeric characters drops punctuation, and `to_lowercase` folds case so `The` and `the` merge. The tie-break on the word keeps output deterministic when counts match — important for tests. `truncate(n)` is safe even when there are fewer than `n` distinct words.

```rust
#[derive(Debug, PartialEq)]
pub enum BracketError {
    UnexpectedClose(usize),
    Mismatched { expected: char, found: char, at: usize },
    Unclosed { ch: char, at: usize },
}

pub fn balanced(s: &str) -> Result<(), BracketError> {
    let mut stack: Vec<char> = Vec::new();
    for (i, c) in s.chars().enumerate() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let expected = match c { ')' => '(', ']' => '[', _ => '{' };
                match stack.pop() {
                    Some(open) if open == expected => {}
                    Some(found) => return Err(BracketError::Mismatched { expected: open_match(expected), found, at: i }),
                    None => return Err(BracketError::UnexpectedClose(i)),
                }
            }
            _ => {}
        }
    }
    match stack.pop() {
        Some(ch) => Err(BracketError::Unclosed { ch, at: s.chars().position(|x| x == ch).unwrap_or(0) }),
        None => Ok(()),
    }
}

fn open_match(open: char) -> char {
    match open { '(' => ')', '[' => ']', _ => '}' }
}

fn main() {
    assert!(balanced("a(b[c]{d})e").is_ok());
    assert!(balanced("(]").is_err());
    assert!(balanced(")(").is_err());
    assert!(balanced("(((").is_err());
    println!("ok");
}
```
The stack holds open brackets; each close must match the most recent open, catching interleaving like `(]` that a naive counter misses. `UnexpectedClose` fires on an unmatched closing bracket, and leftover stack entries become `Unclosed`. I included a helper `open_match` to render the expected partner in the error.

