#include <iostream>

struct Node {
    int value;
    Node* next;
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    Node* current = head;

    while (current != nullptr) {
        Node* next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }

    return prev;
}

int main() {
    Node c{3, nullptr};
    Node b{2, &c};
    Node a{1, &b};

    Node* head = reverse(&a);
    for (Node* n = head; n != nullptr; n = n->next) {
        std::cout << n->value << ' ';
    }
    std::cout << '\n';
    return 0;
}
```
Each iteration saves the next node, points the current node backward, then advances; the final `prev` becomes the new head.

