```rust
use std::collections::HashMap;

/// Count words in `text`, returning the top `n` as (word, count) pairs.
/// Words are lowercased and stripped of non-alphanumeric characters.
pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();

    for raw in text.split_whitespace() {
        let word: String = raw
            .chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !word.is_empty() {
            *counts.entry(word).or_insert(0) += 1;
        }
    }

    let mut ranked: Vec<(String, usize)> = counts.into_iter().collect();
    // Higher count first; equal counts fall back to alphabetical order.
    ranked.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    ranked.truncate(n);
    ranked
}

fn main() {
    let text = "the quick brown fox jumps over the lazy dog. The DOG barks!";
    let top = top_words(text, 3);
    assert_eq!(top, vec![
        ("the".to_string(), 3),
        ("dog".to_string(), 2),
        ("barks".to_string(), 1),
    ]);
    println!("{:?}", top);
}
```
`split_whitespace` handles any run of spaces, and `filter` + `to_lowercase` normalizes punctuation and case. The sort closure puts the larger count first and uses the word itself as the tie-breaker.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} Stack;

static int stack_init(Stack *s, size_t capacity) {
    s->data = malloc(capacity * sizeof *s->data);
    if (s->data == NULL) {
        return 0;
    }
    s->size = 0;
    s->capacity = capacity;
    return 1;
}

static int stack_push(Stack *s, int value) {
    if (s->size == s->capacity) {
        size_t new_cap = s->capacity * 2;
        int *grown = realloc(s->data, new_cap * sizeof *grown);
        if (grown == NULL) {
            return 0;
        }
        s->data = grown;
        s->capacity = new_cap;
    }
    s->data[s->size++] = value;
    return 1;
}

static int stack_pop(Stack *s, int *out) {
    if (s->size == 0) {
        return 0;
    }
    *out = s->data[--s->size];
    return 1;
}

static int stack_peek(const Stack *s, int *out) {
    if (s->size == 0) {
        return 0;
    }
    *out = s->data[s->size - 1];
    return 1;
}

static void stack_free(Stack *s) {
    free(s->data);
    s->data = NULL;
    s->size = 0;
    s->capacity = 0;
}

int main(void) {
    Stack s;
    if (!stack_init(&s, 2)) {
        fputs("init failed\n", stderr);
        return 1;
    }

    for (int i = 1; i <= 5; ++i) {
        if (!stack_push(&s, i * 10)) {
            fputs("push failed\n", stderr);
            stack_free(&s);
            return 1;
        }
    }

    int top;
    if (stack_peek(&s, &top)) {
        printf("peek: %d\n", top);   /* 50 */
    }

    int value;
    while (stack_pop(&s, &value)) {
        printf("pop: %d\n", value);
    }

    if (!stack_pop(&s, &value)) {
        puts("stack is empty");
    }

    stack_free(&s);
    return 0;
}
```
The stack doubles its buffer when full and reuses `realloc`. Every failure path frees the buffer, and `pop`/`peek` on an empty stack report failure instead of reading out of bounds.

