/// Return the largest element, or None for an empty slice.
pub fn max_value<T: PartialOrd + Copy>(items: &[T]) -> Option<T> {
    let mut iter = items.iter();
    let mut best = *iter.next()?; // returns None on an empty slice

    for &item in iter {
        if item > best {
            best = item;
        }
    }
    Some(best)
}

fn main() {
    let numbers = [3, 9, 2, 9, 5];
    let words = ["pear", "apple", "fig"];
    let empty: [i32; 0] = [];

    assert_eq!(max_value(&numbers), Some(9));
    assert_eq!(max_value(&words), Some("pear"));
    assert_eq!(max_value(&empty), None);
    assert_eq!(max_value::<i32>(&[]), None);

    println!("{:?}", max_value(&numbers));
}
```
The `?` operator on the first element short-circuits to `None` when the slice is empty, which is cleaner than a length check. The `PartialOrd + Copy` bound lets the function compare and copy values without cloning.

```cpp
#include <cstddef>
#include <iostream>
#include <numeric>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), count_(0), next_(0), total_(0.0) {}

    void add(double value) {
        if (data_.empty()) {
            return; // capacity 0: nothing to store
        }
        if (count_ == data_.size()) {
            total_ -= data_[next_]; // evict the oldest value
        } else {
            ++count_;
        }
        data_[next_] = value;
        total_ += value;
        next_ = (next_ + 1) % data_.size();
    }

    double average() const {
        return count_ == 0 ? 0.0 : total_ / static_cast<double>(count_);
    }

    void reset() {
        count_ = 0;
        next_ = 0;
        total_ = 0.0;
    }

private:
    std::vector<double> data_;
    std::size_t count_;
    std::size_t next_;
    double total_;
};

int main() {
    RingBuffer rb(3);
    rb.add(10.0);
    rb.add(20.0);
    std::cout << rb.average() << '\n'; // 15
    rb.add(30.0);
    rb.add(40.0); // evicts 10
    std::cout << rb.average() << '\n'; // 30
    rb.reset();
    std::cout << rb.average() << '\n'; // 0
}
```
The running `total_` is updated on every add and corrected when the oldest slot is overwritten, so `average()` is O(1). `reset` clears the count and running sum without deallocating the buffer.

