#include <iostream>
#include <stdexcept>
#include <utility>

template <typename T>
class Stack {
public:
    explicit Stack(std::size_t initial_capacity = 4)
        : data_(new T[initial_capacity]), size_(0), capacity_(initial_capacity) {}

    ~Stack() { delete[] data_; }

    Stack(const Stack&) = delete;
    Stack& operator=(const Stack&) = delete;

    void push(const T& value) {
        if (size_ == capacity_) grow();
        data_[size_++] = value;
    }

    T pop() {
        if (size_ == 0) throw std::out_of_range("pop from empty stack");
        return data_[--size_];
    }

    const T& top() const {
        if (size_ == 0) throw std::out_of_range("top of empty stack");
        return data_[size_ - 1];
    }

    bool empty() const { return size_ == 0; }
    std::size_t size() const { return size_; }

private:
    void grow() {
        std::size_t new_cap = capacity_ == 0 ? 1 : capacity_ * 2;
        T* fresh = new T[new_cap];
        for (std::size_t i = 0; i < size_; ++i) fresh[i] = std::move(data_[i]);
        delete[] data_;
        data_ = fresh;
        capacity_ = new_cap;
    }

    T* data_;
    std::size_t size_;
    std::size_t capacity_;
};

int main() {
    Stack<int> s(2);
    for (int i = 1; i <= 10; ++i) s.push(i * i);
    std::cout << "size after pushes: " << s.size() << '\n';
    while (!s.empty()) std::cout << s.pop() << ' ';
    std::cout << '\n';

    try {
        s.pop();
    } catch (const std::out_of_range& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
