#include <iostream>
#include <vector>

bool is_permutation(std::vector<int>& a) {
    const std::size_t n = a.size();
    for (std::size_t i = 0; i < n; ++i) {
        while (a[i] != static_cast<int>(i) + 1) {
            const int value = a[i];
            if (value < 1 || value > static_cast<int>(n)) {
                return false;
            }
            const std::size_t target = static_cast<std::size_t>(value) - 1;
            if (a[target] == value) {
                return false;  // duplicate
            }
            std::swap(a[i], a[target]);
        }
    }
    return true;
}

int main() {
    std::vector<std::vector<int>> cases = {
        {1, 2, 3, 4},
        {4, 3, 2, 1},
        {1, 1, 3},
        {1, 2, 5},
        {},
        {1},
    };
    for (auto& c : cases) {
        std::cout << (is_permutation(c) ? "yes" : "no") << '\n';
    }
    // Restore and verify the in-place version did not lie.
    std::vector<int> ok = {2, 3, 1};
    std::cout << (is_permutation(ok) ? "yes" : "no") << '\n';
}
```

Cycles are fixed in place so the extra space is O(1); out-of-range values and duplicates both return false; the empty array is a valid permutation of nothing and returns true.

