from datetime import date


def parse_iso_date(text: str) -> date:
    """Parse a strict YYYY-MM-DD string into a date.

    Raises ValueError with the failing input on any mismatch, and rejects
    dates that look shaped right but are not real calendar days.
    """
    if not isinstance(text, str):
        raise ValueError(f"expected str, got {type(text).__name__}")
    text = text.strip()
    if len(text) != 10 or text[4] != "-" or text[7] != "-":
        raise ValueError(f"not in YYYY-MM-DD form: {text!r}")

    parts = text.split("-")
    if len(parts) != 3 or not all(p.isdigit() for p in parts):
        raise ValueError(f"non-numeric date fields: {text!r}")

    year, month, day = (int(p) for p in parts)
    return date(year, month, day)  # date() itself rejects 2023-02-30


if __name__ == "__main__":
    assert parse_iso_date("2024-02-29") == date(2024, 2, 29)
    assert parse_iso_date(" 1999-12-31 ") == date(1999, 12, 31)
    for bad in ["2023-02-29", "2024-13-01", "2024-1-1", "hello", "2024/01/01"]:
        try:
            parse_iso_date(bad)
        except ValueError as exc:
            print(f"rejected {bad!r}: {exc}")
        else:
            raise AssertionError(f"{bad!r} should have been rejected")
```

Shape is checked before conversion; `date()` catches impossible days such as 2023-02-29; surrounding whitespace is tolerated while internal separators are strictly enforced.

