    while (*p != '\0') {
        while (*p == ' ' || *p == '\t') p++;
        if (*p == '\0') break;
        const char *start = p;
        while (*p != '\0' && *p != ' ' && *p != '\t') p++;
        if (count < 512) {
            tokens[count] = start;
            lengths[count] = (size_t)(p - start);
            count++;
        }
    }

    for (size_t i = count; i > 0; i--) {
        fwrite(tokens[i - 1], 1, lengths[i - 1], stdout);
        if (i > 1) putchar(' ');
    }
    putchar('\n');
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 2;
    }
    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    char *line = NULL;
    size_t cap = 0;
    ssize_t n;
    while ((n = getline(&line, &cap, fp)) != -1) {
        while (n > 0 && (line[n - 1] == '\n' || line[n - 1] == '\r')) {
            line[--n] = '\0';
        }
        print_reversed_words(line);
    }
    free(line);
    fclose(fp);
    return 0;
}
```

`getline` handles arbitrarily long lines and empty lines yield an empty output line; tokens are stored and emitted in reverse while characters inside each token stay in order; a cap of 512 tokens per line prevents stack overflow on pathological input.

```cpp
#include <cstddef>
#include <iostream>
#include <vector>

// Returns the index of the first element >= target, or v.size() if none.
std::size_t lowerBound(const std::vector<int>& v, int target) {
    std::size_t lo = 0;
    std::size_t hi = v.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;  // avoids overflow on large sizes
        if (v[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

int main() {
    const std::vector<int> v{1, 2, 2, 4, 7, 9};
    const int probes[] = {0, 2, 5, 9, 10};
    for (int t : probes) {
        std::size_t idx = lowerBound(v, t);
        std::cout << "lower_bound(" << t << ") = " << idx << '\n';
    }
    std::cout << "empty: " << lowerBound({}, 3) << '\n';  // 0
    return 0;
}
```

Uses the half-open interval `[lo, hi)` so an empty vector returns `0`. `mid` is computed as `lo + (hi - lo) / 2` to avoid `size_t` overflow on very large arrays.

```cpp
#include <algorithm>
#include <cstddef>
#include <cstring>
#include <iostream>
#include <utility>

class Buffer {
public:
    explicit Buffer(std::size_t size = 0)
        : size_(size), data_(size ? new unsigned char[size]() : nullptr) {}

    ~Buffer() { delete[] data_; }

    // Copy
    Buffer(const Buffer& other)
        : size_(other.size_),
          data_(other.size_ ? new unsigned char[other.size_] : nullptr) {
        std::copy(other.data_, other.data_ + other.size_, data_);
    }

    Buffer& operator=(const Buffer& other) {
        if (this != &other) {
            Buffer tmp(other);      // strong exception safety
            swap(tmp);
        }
        return *this;
    }

    // Move
    Buffer(Buffer&& other) noexcept
        : size_(other.size_), data_(other.data_) {
        other.size_ = 0;
        other.data_ = nullptr;
    }

    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            size_ = other.size_;
            data_ = other.data_;
            other.size_ = 0;
            other.data_ = nullptr;
        }
        return *this;
    }

    void swap(Buffer& other) noexcept {
        std::swap(size_, other.size_);
        std::swap(data_, other.data_);
    }

    std::size_t size() const { return size_; }
    unsigned char* data() { return data_; }

private:
    std::size_t size_;
    unsigned char* data_;
};

int main() {
    Buffer a(16);
    Buffer b = a;            // copy
    Buffer c = std::move(a); // move
    a = Buffer(4);           // move-assign
    b = c;                   // copy-assign
    std::cout << a.size() << ' ' << b.size() << ' ' << c.size() << '\n';
    return 0;
}
```

The destructor frees exactly once, copy-assignment uses copy-and-swap for the strong guarantee, and both move operations leave the source in a valid empty state.

```cpp
#include <functional>
#include <iostream>
#include <queue>
#include <vector>

class RunningMedian {
public:
    void add(int value) {
        if (maxHeap_.empty() || value <= maxHeap_.top()) {
            maxHeap_.push(value);
        } else {
            minHeap_.push(value);
        }
        rebalance();
    }

    double median() const {
        if (maxHeap_.size() == minHeap_.size()) {
            return (static_cast<double>(maxHeap_.top()) + minHeap_.top()) / 2.0;
        }
        return static_cast<double>(maxHeap_.top());
    }

private:
    void rebalance() {
        if (maxHeap_.size() > minHeap_.size() + 1) {
            minHeap_.push(maxHeap_.top());
            maxHeap_.pop();
        } else if (minHeap_.size() > maxHeap_.size()) {
            maxHeap_.push(minHeap_.top());
            minHeap_.pop();
        }
    }

    std::priority_queue<int> maxHeap_;                             // lower half
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap_;  // upper half
};

int main() {
    RunningMedian rm;
    for (int x : {5, 15, 1, 3}) {
        rm.add(x);
        std::cout << rm.median() << '\n';  // 5, 10, 5, 4
    }
    return 0;
}
```

`maxHeap_` holds the lower half, `minHeap_` the upper half, keeping sizes within one. The median is the top of the larger heap, or the average of both tops.

```rust
use std::collections::HashMap;

struct Node {
    key: i32,
    value: i32,
    prev: Option<usize>,
    next: Option<usize>,
}

pub struct LruCache {
    cap: usize,
    map: HashMap<i32, usize>,
    nodes: Vec<Node>,
    head: Option<usize>, // most recent
    tail: Option<usize>, // least recent
}

impl LruCache {
    pub fn new(cap: usize) -> Self {
        LruCache { cap, map: HashMap::new(), nodes: Vec::new(), head: None, tail: None }
    }

    pub fn get(&mut self, key: i32) -> Option<i32> {
        let idx = *self.map.get(&key)?;
        self.move_to_front(idx);
        Some(self.nodes[idx].value)
    }

    pub fn put(&mut self, key: i32, value: i32) {
        if self.cap == 0 {
            return;
        }
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].value = value;
            self.move_to_front(idx);
            return;
        }
        let idx = self.nodes.len();
        self.nodes.push(Node { key, value, prev: None, next: None });
        self.map.insert(key, idx);
        self.push_front(idx);
        if self.map.len() > self.cap {
            if let Some(t) = self.tail {
                self.unlink(t);
                self.map.remove(&self.nodes[t].key);
            }
        }
    }

    fn push_front(&mut self, idx: usize) {
        self.nodes[idx].next = self.head;
        self.nodes[idx].prev = None;
        if let Some(h) = self.head {
            self.nodes[h].prev = Some(idx);
        }
        self.head = Some(idx);
        if self.tail.is_none() {
            self.tail = Some(idx);
        }
    }

    fn unlink(&mut self, idx: usize) {
        let (prev, next) = (self.nodes[idx].prev, self.nodes[idx].next);
        match prev {
            Some(p) => self.nodes[p].next = next,
            None => self.head = next,
        }
        match next {
            Some(n) => self.nodes[n].prev = prev,
            None => self.tail = prev,
        }
    }

    fn move_to_front(&mut self, idx: usize) {
        self.unlink(idx);
        self.push_front(idx);
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 1);
    c.put(2, 2);
    assert_eq!(c.get(1), Some(1));
    c.put(3, 3);            // evicts 2
    assert_eq!(c.get(2), None);
    assert_eq!(c.get(3), Some(3));
    println!("ok");
}
```

Indices into a `Vec<Node>` act as stable pointers, avoiding `Rc<RefCell<...>>`. `capacity == 0` is handled as a no-op rather than panicking.

