use std::collections::HashMap;

fn parse_config(input: &str) -> Result<HashMap<String, String>, String> {
    let mut map = HashMap::new();
    for (i, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line
            .split_once('=')
            .ok_or_else(|| format!("line {}: missing '=' in {:?}", i + 1, line))?;
        let key = key.trim();
        if key.is_empty() {
            return Err(format!("line {}: empty key", i + 1));
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let text = "\n# app config\nhost = localhost\nport=8080\n  debug = true  \nname = a=b\n";
    match parse_config(text) {
        Ok(map) => {
            let mut keys: Vec<_> = map.keys().cloned().collect();
            keys.sort();
            for k in keys {
                println!("{k} -> {}", map[&k]);
            }
        }
        Err(e) => eprintln!("parse error: {e}"),
    }
}
```

`split_once('=')` keeps values containing `=`, and `trim()` on both sides handles surrounding whitespace. Malformed lines produce a line-numbered error instead of being silently dropped.

