#include <iostream>
#include <vector>

std::vector<int> mergeSorted(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out;
    out.reserve(a.size() + b.size());
    size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) out.push_back(a[i++]);
        else out.push_back(b[j++]);
    }
    while (i < a.size()) out.push_back(a[i++]);
    while (j < b.size()) out.push_back(b[j++]);
    return out;
}

int main() {
    std::vector<int> a{1, 3, 5, 7};
    std::vector<int> b{2, 4, 6};
    std::vector<int> c = mergeSorted(a, b);
    for (size_t k = 0; k < c.size(); ++k) {
        std::cout << c[k] << (k + 1 < c.size() ? ' ' : '\n');
    }

    std::vector<int> empty;
    std::vector<int> d = mergeSorted(empty, empty);
    std::cout << "empty size=" << d.size() << '\n';

    std::vector<int> e = mergeSorted({}, {9, 9});
    std::cout << "one-sided=" << e[0] << ',' << e[1] << '\n';
