#include <array>
#include <cstddef>
#include <iostream>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity ? capacity : 1), cap_(capacity) {}

    bool push(int v) {
        if (cap_ == 0 || size_ == cap_) return false;
        buf_[(head_ + size_) % cap_] = v;
        ++size_;
        return true;
    }

    bool pop(int& out) {
        if (size_ == 0) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == cap_; }

private:
    std::array<int, 0> buf_unused_{};
    std::vector<int> buf_;
    std::size_t cap_ = 0;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << '\n';
    int v = 0;
    std::cout << rb.pop(v) << ' ' << v << '\n';
    rb.push(5);
    while (rb.pop(v)) std::cout << v << ' ';
    std::cout << '\n';
    std::cout << "empty=" << rb.empty() << " pop-empty=" << rb.pop(v) << '\n';
    return 0;
}
```
One flaw: mixing `std::array` with `std::vector` in the members is sloppy — drop the unused array and the `#include <array>`. The logic itself is correct: the fourth `push` returns 0 because the buffer is full.

