    Missing file -> defaults. Corrupt JSON -> ValueError with the path.
    """
    p = Path(path)
    if not p.exists():
        return dict(DEFAULTS)

    try:
        raw = json.loads(p.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        raise ValueError(f"invalid JSON in {path}: {e}") from e
    if not isinstance(raw, dict):
        raise ValueError(f"config root must be an object, got {type(raw).__name__}")

    cfg = dict(DEFAULTS)
    for key, value in raw.items():
        if key in DEFAULTS and not isinstance(value, type(DEFAULTS[key])):
            raise ValueError(
                f"{key}: expected {type(DEFAULTS[key]).__name__}, got {type(value).__name__}"
            )
        cfg[key] = value
    return cfg


if __name__ == "__main__":
