```rust
use std::cmp::Reverse;
use std::collections::BinaryHeap;

struct MedianFinder {
    low: BinaryHeap<i32>,          // max-heap, holds the smaller half
    high: BinaryHeap<Reverse<i32>>, // min-heap, holds the larger half
}

impl MedianFinder {
    fn new() -> Self {
        MedianFinder { low: BinaryHeap::new(), high: BinaryHeap::new() }
    }

    fn add(&mut self, x: i32) {
        self.low.push(x);
        if let (Some(&a), Some(&Reverse(b))) = (self.low.peek(), self.high.peek()) {
            if a > b {
                let v = self.low.pop().unwrap();
                self.high.push(Reverse(v));
            }
        }
        if self.low.len() > self.high.len() + 1 {
            let v = self.low.pop().unwrap();
            self.high.push(Reverse(v));
        } else if self.high.len() > self.low.len() {
            let Reverse(v) = self.high.pop().unwrap();
            self.low.push(v);
        }
    }

    fn median(&self) -> Option<f64> {
        if self.low.is_empty() {
            return None;
        }
        if self.low.len() == self.high.len() {
            let a = *self.low.peek().unwrap() as f64;
            let Reverse(b) = *self.high.peek().unwrap();
            Some((a + b as f64) / 2.0)
        } else {
            Some(*self.low.peek().unwrap() as f64)
        }
    }
}

fn main() {
    let mut mf = MedianFinder::new();
    assert_eq!(mf.median(), None);
    for (x, want) in [(1, 1.0), (2, 1.5), (3, 2.0), (4, 2.5), (5, 3.0)] {
        mf.add(x);
        assert_eq!(mf.median(), Some(want));
    }
    println!("ok");
}
```
`Reverse` turns `BinaryHeap` into a min-heap for the upper half. Invariant: `low.len()` is equal to or one greater than `high.len()`, so the median is `low.peek()` or the average of the two peaks.

