pub fn validate_luhn(number: &str) -> Result<(), String> {
    let digits: Vec<u32> = number
        .chars()
        .map(|c| c.to_digit(10).ok_or_else(|| format!("non-digit character: {c}")))
        .collect::<Result<_, _>>()?;

    if digits.is_empty() {
        return Err("input is empty".to_string());
    }

    let mut sum = 0u32;
    let mut double = false;
    for &d in digits.iter().rev() {
        let mut v = d;
        if double {
            v *= 2;
            if v > 9 {
                v -= 9;
            }
        }
        sum += v;
        double = !double;
    }

    if sum % 10 == 0 {
        Ok(())
    } else {
        Err(format!("checksum failed (sum={sum})"))
    }
}

