```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *push_front(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) {
        while (head) {
            Node *tmp = head->next;
            free(head);
            head = tmp;
        }
        return NULL;
    }
    n->value = value;
    n->next = head;
    return n;
}

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

void print_list(const Node *head) {
    for (const Node *n = head; n; n = n->next) {
        printf("%d", n->value);
        if (n->next) printf(" -> ");
    }
    printf("\n");
}

void free_list(Node *head) {
    while (head) {
        Node *tmp = head->next;
        free(head);
        head = tmp;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 5; i >= 1; --i) {
        head = push_front(head, i);
    }
    print_list(head);
    head = reverse(head);
    print_list(head);
    free_list(head);
    return 0;
}
```

On allocation failure `push_front` walks and frees the whole list before returning `NULL`, so the caller never leaks. The reversal is the standard three-pointer walk and works for zero, one, or many nodes.

