pub fn merge_ranges(mut ranges: Vec<(i64, i64)>) -> Vec<(i64, i64)> {
    let normalised: Vec<(i64, i64)> = ranges
        .drain(..)
        .filter_map(|(a, b)| {
            let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
            if lo == hi { None } else { Some((lo, hi)) }
        })
        .collect();

    let mut sorted = normalised;
    sorted.sort_unstable();

    let mut merged: Vec<(i64, i64)> = Vec::new();
    for (lo, hi) in sorted {
        match merged.last_mut() {
            Some(last) if lo <= last.1 => {
                if hi > last.1 {
                    last.1 = hi;
                }
            }
            _ => merged.push((lo, hi)),
        }
    }
    merged
}

fn main() {
    assert_eq!(merge_ranges(vec![(5, 1), (2, 4)]), vec![(1, 5)]);
    assert_eq!(merge_ranges(vec![(1, 2), (3, 4)]), vec![(1, 2), (3, 4)]);
    assert_eq!(merge_ranges(vec![(7, 7)]), vec![]);
    assert_eq!(merge_ranges(vec![]), vec![]);
    println!("ok");
}
```

Ranges are normalised first, then sorted by start. Merging only ever extends the last tuple's end, so touching ranges like `(1,2)` and `(2,4)` collapse to `(1,4)`. Empty input and degenerate `(x,x)` ranges vanish.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(T value) {
        if (size_ == N) {
            head_ = (head_ + 1) % N;
            data_[(head_ + size_ - 1) % N] = std::move(value);
        } else {
            data_[(head_ + size_) % N] = std::move(value);
            ++size_;
        }
    }

    std::size_t size() const { return size_; }

    std::size_t span(const char *label) const {
        std::cout << label << ": ";
        for (std::size_t i = 0; i < size_; ++i) {
            std::cout << data_[(head_ + i) % N] << (i + 1 < size_ ? " " : "");
        }
        std::cout << "\n";
        return size_;
    }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.span("empty");
    rb.push(1);
    rb.push(2);
    rb.span("two");
    rb.push(3);
    rb.push(4);
    if (rb.span("overwritten") != 3) return 1;
    return 0;
}
```

While the buffer is not full, pushes append at `head + size`. Once full, every push advances `head` first, so the oldest slot is overwritten and iteration always starts at the current oldest element. `std::array` gives `N` as a compile-time constant; no heap allocation.

