class FileHandle {
public:
    explicit FileHandle(const char* path, const char* mode) : fp_(std::fopen(path, mode)) {
        if (!fp_) throw std::runtime_error("failed to open file");
    }

    ~FileHandle() { if (fp_) std::fclose(fp_); }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fp_(other.fp_) { other.fp_ = nullptr; }
    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            if (fp_) std::fclose(fp_);
            fp_ = other.fp_;
            other.fp_ = nullptr;
        }
        return *this;
    }

    std::FILE* get() const { return fp_; }

private:
    std::FILE* fp_;
};

int main() {
    try {
        FileHandle f("/etc/hostname", "r");
        char buf[256]{};
        if (std::fgets(buf, sizeof(buf), f.get())) std::printf("%s", buf);
    } catch (const std::exception& e) {
        std::printf("error: %s\n", e.what());
    }
}
