fn check_brackets(input: &str) -> Result<(), String> {
    let mut stack = Vec::new();
    for (i, ch) in input.chars().enumerate() {
        match ch {
            '(' | '[' | '{' => stack.push(ch),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some(open) if open == expected => {}
                    Some(open) => return Err(format!("at {}: '{}' closes '{}'", i, ch, open)),
                    None => return Err(format!("at {}: '{}' has no opener", i, ch)),
                }
            }
            _ => {}
        }
    }
    if let Some(open) = stack.pop() {
        return Err(format!("unclosed '{}'", open));
    }
    Ok(())
}

fn main() {
    for s in ["([]{})", "([)]", "(((", ""] {
        println!("{:?} -> {:?}", s, check_brackets(s));
    }
}
```

Every closing bracket is matched against the exact opener popped off the stack, so `([)]` fails even though the counts balance. The trailing check catches unclosed openers, and an empty string returns `Ok` because the loop body never runs.

