#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    node->value = value;
    node->next = head;
    return node;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print(const Node *head) {
    for (const Node *cur = head; cur != NULL; cur = cur->next) {
        printf("%d%s", cur->value, cur->next ? " -> " : "\n");
    }
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; ++i) {
        head = push(head, i);
    }
    print(head);            /* 5 -> 4 -> 3 -> 2 -> 1 */
    head = reverse(head);
    print(head);            /* 1 -> 2 -> 3 -> 4 -> 5 */
    free_list(head);
    return 0;
}
