#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
double median(std::vector<T> values) {
    if (values.empty()) {
        throw std::invalid_argument("median of empty vector");
    }
    const std::size_t n = values.size();
    const std::size_t mid = n / 2;

    // Partial sort so that values[mid] is the (mid+1)-th smallest.
    std::nth_element(values.begin(), values.begin() + mid, values.end());

    if (n % 2 == 1) {
        return static_cast<double>(values[mid]);
    }

    // For even n, mid is the upper of the two middle elements; the lower
    // is the largest element in [0, mid).
    auto lower = std::max_element(values.begin(), values.begin() + mid);
    return (static_cast<double>(*lower) + static_cast<double>(values[mid])) / 2.0;
}

int main() {
    std::vector<int> odd{5, 1, 4, 2, 3};
    std::vector<int> even{4, 1, 3, 2};
    std::vector<int> one{42};

    std::cout << median(odd) << '\n';   // 3
    std::cout << median(even) << '\n';  // 2.5
    std::cout << median(one) << '\n';   // 42

    try {
        median(std::vector<int>{});
    } catch (const std::invalid_argument& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
