#include <string>
#include <cstddef>

std::string longestPalindrome(const std::string& s) {
    if (s.empty()) return "";
    std::size_t start = 0, maxLen = 1;
    auto expand = [&](std::size_t left, std::size_t right) {
        while (left != std::string::npos && right < s.size() && s[left] == s[right]) {
            if (right - left + 1 > maxLen) {
                start = left;
                maxLen = right - left + 1;
            }
            if (left == 0) break;
            --left;
            ++right;
        }
    };
    for (std::size_t i = 0; i < s.size(); ++i) {
        expand(i, i);       // odd length
        expand(i, i + 1);   // even length
    }
    return s.substr(start, maxLen);
}

#include <iostream>
int main() {
    std::cout << longestPalindrome("") << '\n';
    std::cout << longestPalindrome("babad") << '\n';
    std::cout << longestPalindrome("cbbd") << '\n';
    std::cout << longestPalindrome("a") << '\n';
}
```
The lambda tracks the best window by index rather than building substrings inside the loop, so the scan is O(1) extra space. The `left == 0` guard prevents unsigned underflow when expanding past the left edge.

