#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    T& at(std::size_t i) {
        if (i >= size_) throw std::out_of_range("index out of range");
        std::size_t start = (head_ + N - size_) % N;
        return data_[(start + i) % N];
    }

    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int v : {1, 2, 3, 4, 5}) rb.push(v);
    // capacity 3, last written 5 -> holds {3, 4, 5}
    for (std::size_t i = 0; i < rb.size(); ++i) std::cout << rb.at(i) << ' ';
    std::cout << '\n';
}
```
The `head_` index points at the next write slot; the logical start is derived as `(head_ + N - size_) % N`. The `+ N` keeps the modular arithmetic safe when the buffer wraps and `size_ == N`.

