class RingBuffer:
    """A fixed-capacity buffer that overwrites the oldest item when full."""

    def __init__(self, capacity):
        if not isinstance(capacity, int) or capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        self._capacity = capacity
        self._data = []
        self._start = 0

    def push(self, item):
        if len(self._data) < self._capacity:
            self._data.append(item)
        else:
            self._data[self._start] = item
            self._start = (self._start + 1) % self._capacity

    def to_list(self):
        """Return the contents oldest-first."""
        return self._data[self._start:] + self._data[:self._start]

    def is_full(self):
        return len(self._data) == self._capacity


if __name__ == "__main__":
    rb = RingBuffer(3)
    for n in range(5):
        rb.push(n)
    print(rb.to_list())   # [2, 3, 4]
    print(rb.is_full())   # True
    try:
        RingBuffer(0)
    except ValueError as exc:
        print(exc)        # capacity must be a positive integer
