std::string longestPalindrome(const std::string& s) {
    if (s.empty()) return "";
    int bestStart = 0;
    int bestLen = 1;

    auto expand = [&](int left, int right) {
        while (left >= 0 && right < static_cast<int>(s.size()) &&
               s[left] == s[right]) {
            --left;
            ++right;
        }
        int len = right - left - 1;
        if (len > bestLen) {
            bestLen = len;
            bestStart = left + 1;
        }
    };

    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        expand(i, i);       // odd length
        expand(i, i + 1);   // even length
    }
    return s.substr(bestStart, bestLen);
}

int main() {
    std::cout << longestPalindrome("") << "\n";          // (empty)
    std::cout << longestPalindrome("babad") << "\n";     // bab
    std::cout << longestPalindrome("cbbd") << "\n";      // bb
    std::cout << longestPalindrome("a") << "\n";         // a
