#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    // Blocks while full. Returns false if the queue was shut down first.
    bool push(int value) {
        std::unique_lock<std::mutex> lock(mu_);
        notFull_.wait(lock, [&] { return closed_ || q_.size() < cap_; });
        if (closed_) return false;
        q_.push(value);
        notEmpty_.notify_one();
        return true;
    }

    // Blocks while empty. Returns nullopt if drained and shut down.
    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        notEmpty_.wait(lock, [&] { return closed_ || !q_.empty(); });
        if (q_.empty()) return std::nullopt;
        int value = q_.front();
        q_.pop();
        notFull_.notify_one();
        return value;
    }

    void shutdown() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        notEmpty_.notify_all();
        notFull_.notify_all();
    }

private:
    std::size_t cap_;
    std::queue<int> q_;
    bool closed_ = false;
    std::mutex mu_;
    std::condition_variable notEmpty_;
    std::condition_variable notFull_;
};
