/* Copy src into dst of size dst_size, always NUL-terminating.
 * Returns the number of bytes copied (excluding the NUL).
 * If dst_size is 0 or dst is NULL, nothing is written and 0 is returned. */
size_t safe_copy(char *dst, size_t dst_size, const char *src) {
    if (dst == NULL || dst_size == 0) {
        return 0;
    }
    if (src == NULL) {
        dst[0] = '\0';
        return 0;
    }
    size_t i = 0;
    while (i + 1 < dst_size && src[i] != '\0') {
        dst[i] = src[i];
        ++i;
    }
    dst[i] = '\0';
    return i;
}

int main(void) {
    char buf[8];
    size_t n = safe_copy(buf, sizeof buf, "hello world");
    printf("copied=%zu value=%s\n", n, buf);  /* copied=7 value=hello w */

    n = safe_copy(buf, 0, "ignored");
    printf("copied=%zu\n", n);                /* copied=0 */

    n = safe_copy(buf, sizeof buf, NULL);
    printf("copied=%zu empty=%d\n", n, buf[0] == '\0');  /* copied=0 empty=1 */
    return 0;
}
