        return right - left - 1

    for i in range(len(s)):
        odd = expand(i, i)
        even = expand(i, i + 1)
        length = max(odd, even)
        if length > end - start:
            start = i - (length - 1) // 2
            end = i + length // 2

    return s[start:end + 1]


if __name__ == "__main__":
    cases = {
        "babad": {"bab", "aba"},
        "cbbd": {"bb"},
        "": {""},
        "a": {"a"},
        "forgeeksskeegfor": {"geeksskeeg"},
        "\u4f60\u597d\u4f60": {"\u4f60\u597d\u4f60"},
    }
    for text, expected in cases.items():
        got = longest_palindrome(text)
        assert got in expected, (text, got, expected)
    print("all tests passed")
```

The function expands around each character, handling both odd and even centers, and tracks the longest span. The self-test covers empty input, single characters, ties, and a non-ASCII string.

