fn binary_search<T: Ord>(slice: &[T], target: &T) -> Result<usize, usize> {
    let mut low = 0usize;
    let mut high = slice.len();
    while low < high {
        let mid = low + (high - low) / 2;
        if &slice[mid] < target {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    if low < slice.len() && &slice[low] == target {
        Ok(low)
    } else {
        Err(low)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn finds_present_values() {
        let v = [1, 3, 5, 7, 9];
        assert_eq!(binary_search(&v, &1), Ok(0));
        assert_eq!(binary_search(&v, &9), Ok(4));
        assert_eq!(binary_search(&v, &5), Ok(2));
    }

    #[test]
    fn reports_insertion_points() {
        let v = [1, 3, 5, 7, 9];
        assert_eq!(binary_search(&v, &0), Err(0));
        assert_eq!(binary_search(&v, &4), Err(2));
        assert_eq!(binary_search(&v, &10), Err(5));
    }

    #[test]
    fn handles_empty_and_single() {
        let empty: [i32; 0] = [];
        assert_eq!(binary_search(&empty, &7), Err(0));
        assert_eq!(binary_search(&[42], &42), Ok(0));
        assert_eq!(binary_search(&[42], &41), Err(0));
    }
}
```

The loop narrows `[low, high)` until `low == high`; a final equality check decides `Ok` versus `Err`. `low + (high - low) / 2` avoids overflow on large slices. Tests cover hits, misses, empty, and single-element cases.

