#include <stdio.h>
#include <string.h>
#include <ctype.h>

int is_valid_ipv4(const char *s) {
    int octets = 0;
    const char *p = s;

    while (1) {
        if (!isdigit((unsigned char)*p)) return 0;
        if (*p == '0' && isdigit((unsigned char)*(p + 1))) return 0; /* leading zero */

        int value = 0, digits = 0;
        while (isdigit((unsigned char)*p)) {
            value = value * 10 + (*p - '0');
            digits++;
            if (digits > 3) return 0;
            p++;
        }
        if (value > 255) return 0;
        octets++;

        if (*p == '.') {
            p++;
            if (octets == 4) return 0;
        } else if (*p == '\0') {
            break;
        } else {
            return 0;
        }
    }
    return octets == 4;
}

int main(void) {
    printf("%d\n", is_valid_ipv4("192.168.1.1"));   /* 1 */
    printf("%d\n", is_valid_ipv4("256.1.1.1"));     /* 0 */
    printf("%d\n", is_valid_ipv4("01.2.3.4"));      /* 0 */
    printf("%d\n", is_valid_ipv4("1.2.3"));         /* 0 */
    return 0;
}
