fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {
    if n < 2 {
        return n;
    }
    if let Some(&v) = memo.get(&n) {
        return v;
    }
    let value = fib(n - 1, memo).checked_add(fib(n - 2, memo))
        .expect("fibonacci overflowed u64 (n > 93)");
    memo.insert(n, value);
    value
}

