#include <map>
#include <string>
#include <sstream>
#include <vector>

std::pair<std::map<std::string, std::string>, std::vector<std::string>>
parse_pairs(const std::string& input) {
    std::map<std::string, std::string> result;
    std::vector<std::string> duplicates;
    std::istringstream stream(input);
    std::string token;
    while (std::getline(stream, token, ';')) {
        if (token.empty()) continue;
        auto eq = token.find('=');
        if (eq == std::string::npos || eq == 0) continue; /* malformed, skip */
        std::string key = token.substr(0, eq);
        std::string value = token.substr(eq + 1);
        if (result.count(key)) duplicates.push_back(key);
        result[key] = value;
    }
    return {result, duplicates};
}

int main() {
    auto [pairs, dupes] = parse_pairs("host=db;port=5432;host=backup");
    for (const auto& [k, v] : pairs) std::cout << k << " -> " << v << '\n';
    for (const auto& d : dupes) std::cout << "duplicate: " << d << '\n';
    return 0;
}
