size_t count_substring(const char *haystack, const char *needle) {
    if (haystack == NULL || needle == NULL) return 0;
    size_t nlen = strlen(needle);
    if (nlen == 0) return 0; /* avoid an infinite loop on empty needle */
    size_t count = 0;
    const char *p = haystack;
    while ((p = strstr(p, needle)) != NULL) {
        count++;
        p += 1; /* advance by one to allow overlap */
    }
    return count;
}

