    printf("%zu\n", count_substring("abcabc", "abc")); /* 2 */
    printf("%zu\n", count_substring("abc", "xyz"));  /* 0 */
    printf("%zu\n", count_substring("abc", ""));     /* 0 */
    printf("%zu\n", count_substring("", "a"));       /* 0 */
    return 0;
}
