pub struct Stack<T> {
    items: Vec<T>,
    cap: usize,
}

impl<T> Stack<T> {
    pub fn new(cap: usize) -> Self {
        Stack { items: Vec::with_capacity(cap), cap }
    }

    pub fn push(&mut self, value: T) -> Option<()> {
        if self.items.len() >= self.cap {
            None
        } else {
            self.items.push(value);
            Some(())
        }
    }

    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }
}

