```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        if (size_ == N) {          // full: drop the oldest
            head_ = (head_ + 1) % N;
        } else {
            ++size_;
        }
        data_[(head_ + size_ - 1) % N] = value;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int i = 1; i <= 5; ++i) rb.push(i);
    while (auto v = rb.pop()) std::cout << *v << ' ';  // 3 4 5
    std::cout << '\n';
}
```

`pop` returns `std::optional`, so draining an empty buffer is well-defined and returns `nullopt`. Pushing into a full buffer advances `head_` before writing, which discards the oldest element and keeps the newest `N`.

