fn parse_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut cur = String::new();
    let mut chars = line.chars().peekable();
    let mut in_quotes = false;

    while let Some(c) = chars.next() {
        if in_quotes {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    cur.push('"');
                    chars.next();
                } else {
                    in_quotes = false;
                }
            } else {
                cur.push(c);
            }
        } else if c == '"' {
            in_quotes = true;
        } else if c == ',' {
            fields.push(std::mem::take(&mut cur));
        } else {
            cur.push(c);
        }
    }
    fields.push(cur);
    fields
}

fn main() {
    assert_eq!(parse_line("a,b,c"), vec!["a", "b", "c"]);
    assert_eq!(parse_line("\"a,b\",c"), vec!["a,b", "c"]);
    assert_eq!(parse_line("\"he said \"\"hi\"\"\",x"), vec!["he said \"hi\"", "x"]);
    assert_eq!(parse_line(""), vec![""]);
    println!("ok");
}
```
The `peekable` iterator lets the parser look ahead one char to decide whether `""` is an escaped quote inside a field or a field terminator.

```rust
fn retry<T, E, F>(attempts: usize, mut f: F) -> Result<T, E>
where
    F: FnMut(usize) -> Result<T, E>,
{
    assert!(attempts > 0, "attempts must be positive");
    let mut last_err = None;
    for i in 0..attempts {
        match f(i) {
            Ok(v) => return Ok(v),
            Err(e) => last_err = Some(e),
        }
    }
    Err(last_err.expect("loop ran at least once"))
}

fn main() {
    let mut calls = 0;
    let r = retry(3, |i| {
        calls += 1;
        if i < 2 { Err(format!("fail {}", i)) } else { Ok(i) }
    });
    assert_eq!(r, Ok(2));
    assert_eq!(calls, 3);

    let always = retry(2, |_| Err::<(), _>("nope"));
    assert_eq!(always, Err("nope"));
    println!("ok");
}
```
The closure receives the attempt index, which makes the retry count observable in tests. `last_err` is safe to unwrap because the loop body always runs at least once.

