            char open = st.top();
            st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.empty();
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::string line;
    while (std::getline(std::cin, line)) {
        std::cout << (balanced(line) ? "YES" : "NO") << '\n';
    }
    return 0;
}
```

Compile with `g++ -std=c++17 -O2 -Wall -o brackets brackets.cpp`. Each input line is checked independently; unmatched closers and leftover openers both return false. Blank lines read as balanced (`YES`).

```rust
fn fib_pair(n: u128) -> (u128, u128) {
    // Returns (F(n), F(n+1)) using fast doubling.
    if n == 0 {
        return (0, 1);
    }
    let (a, b) = fib_pair(n >> 1);
    let c = a.checked_mul(2 * b - a).expect("fib overflow");
    let d = a.checked_mul(a).checked_add(b.checked_mul(b)).expect("fib overflow");
    if n & 1 == 0 {
        (c, d)
    } else {
        (d, c + d)
    }
}

fn fib(n: u128) -> u128 {
    fib_pair(n).0
}

fn main() {
    for n in 0..=10 {
        println!("fib({n}) = {}", fib(n));
    }
    assert_eq!(fib(0), 0);
    assert_eq!(fib(1), 1);
    assert_eq!(fib(10), 55);
    assert_eq!(fib(50), 12_586_269_025);
}
```

