#include <stdio.h>
#include <string.h>

static void reverse_in_place(char *s) {
    size_t len = strlen(s);
    if (len < 2) {
        return;
    }
    size_t left = 0;
    size_t right = len - 1;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        ++left;
        --right;
    }
}

int main(void) {
    char buf[] = "hello, world";
    printf("original:  %s\n", buf);
    reverse_in_place(buf);
    printf("reversed:  %s\n", buf);

    char one[] = "x";
    reverse_in_place(one);
    printf("single:    %s\n", one);

    return 0;
}
