Fixed-capacity stack, returns 1 balanced / 0 unbalanced / -1 overflow:

```c
#include <stdio.h>
#include <string.h>

#define CAP 1024

typedef struct { char data[CAP]; int top; } Stack;

void init(Stack *s) { s->top = 0; }
int push(Stack *s, char c) {
    if (s->top >= CAP) return -1;
    s->data[s->top++] = c;
    return 0;
}
int pop(Stack *s, char *out) {
    if (s->top == 0) return -1;
    *out = s->data[--s->top];
    return 0;
}

int balanced(const char *s) {
    Stack st; init(&st);
    for (size_t i = 0; s[i]; i++) {
        char c = s[i], top;
        if (c == '(' || c == '[' || c == '{') {
            if (push(&st, c)) return -1;
        } else if (c == ')' || c == ']' || c == '}') {
            if (pop(&st, &top)) return 0;
            if ((c == ')' && top != '(') ||
                (c == ']' && top != '[') ||
                (c == '}' && top != '{')) return 0;
        }
    }
    return st.top == 0;
}

int main(void) {
    const char *tests[] = { "{[()]}", "([)]", "((", "", "a(b)c[d]{e}" };
    int want[] = { 1, 0, 0, 1, 1 };
    for (int i = 0; i < 5; i++) {
        int got = balanced(tests[i]);
        printf("%-20s -> %d (want %d)\n", tests[i], got, want[i]);
    }
    return 0;
}
```

Non-bracket characters are ignored, so prose with brackets still validates correctly.

A small state machine that handles `""` escapes and embedded commas:

```rust
fn parse_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut cur = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();

    while let Some(c) = chars.next() {
        if in_quotes {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    cur.push('"');
                    chars.next();
                } else {
                    in_quotes = false;
                }
            } else {
                cur.push(c);
            }
        } else if c == '"' && cur.is_empty() {
            in_quotes = true;
        } else if c == ',' {
            fields.push(std::mem::take(&mut cur));
        } else {
            cur.push(c);
        }
    }
    fields.push(cur);
    fields
}

fn main() {
    let line = "a,b\"c,d\"\"e\"", f";
    let got = parse_csv_line(line);
    assert_eq!(got, vec!["a", "bc,d\"e", " f"]);
    assert_eq!(parse_csv_line(""), vec![""]);
    println!("ok");
}
```

A quote only opens a field at its start; commas inside quotes are preserved. Trailing empty fields are kept, matching RFC 4180 behaviour.

