```cpp
#include <iostream>
#include <vector>

// Flatten any number of nested levels using recursive overloads.
template <typename T>
std::vector<T> flatten(const std::vector<T>& v) {
    return v;
}

template <typename T>
std::vector<T> flatten(const std::vector<std::vector<T>>& v) {
    std::vector<T> out;
    for (const auto& inner : v) {
        auto part = flatten(inner);
        out.insert(out.end(), part.begin(), part.end());
    }
    return out;
}

int main() {
    std::vector<std::vector<int>> nested = {{1, 2}, {}, {3}, {4, 5, 6}};
    auto flat = flatten(nested);
    for (int x : flat) std::cout << x << ' ';   // 1 2 3 4 5 6
    std::cout << '\n';

    std::vector<std::vector<std::vector<int>>> deep = {{{1}}, {{2, 3}}, {}};
    for (int x : flatten(deep)) std::cout << x << ' ';  // 1 2 3
    std::cout << '\n';
    return 0;
}
