```cpp
#include <array>
#include <cstddef>
#include <optional>
#include <cassert>

template <typename T, std::size_t N>
class RingBuffer {
    static_assert(N > 0, "capacity must be positive");
    std::array<T, N> buf_{};
    std::size_t head_ = 0;  // next write position
    std::size_t size_ = 0;

public:
    void push(const T& value) {
        buf_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    std::optional<T> back() const {
        if (size_ == 0) return std::nullopt;
        std::size_t idx = (head_ + N - 1) % N;
        return buf_[idx];
    }

    std::size_t size() const { return size_; }
    static constexpr std::size_t capacity() { return N; }
};

int main() {
    RingBuffer<int, 3> rb;
    assert(!rb.back().has_value());
    rb.push(1); rb.push(2); rb.push(3); rb.push(4);  // overwrites 1
    assert(rb.size() == 3);
    assert(rb.back().value() == 4);
    assert(rb.capacity() == 3);
    return 0;
}
```

`head_` advances modulo `N`, so `push` overwrites the oldest slot once full. `back()` recovers the most recent element with `(head_ - 1 + N) % N`; the `+ N` avoids underflow when `head_ == 0`.

