```python
import threading
import time


class BoundedQueue:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._cap = capacity
        self._items = []
        self._lock = threading.Lock()
        self._not_full = threading.Condition(self._lock)
        self._not_empty = threading.Condition(self._lock)

    def put(self, item, timeout=None):
        deadline = None if timeout is None else time.monotonic() + timeout
        with self._not_full:
            while len(self._items) >= self._cap:
                if deadline is not None:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0 or not self._not_full.wait(remaining):
                        return False
                else:
                    self._not_full.wait()
            self._items.append(item)
            self._not_empty.notify()
            return True

    def get(self, timeout=None):
        deadline = None if timeout is None else time.monotonic() + timeout
        with self._not_empty:
            while not self._items:
                if deadline is not None:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0 or not self._not_empty.wait(remaining):
                        return None
                else:
                    self._not_empty.wait()
            item = self._items.pop(0)
            self._not_full.notify()
            return item

    def __len__(self):
        with self._lock:
            return len(self._items)
```

Both conditions share one lock so `notify` is legal. `put` re-checks the predicate in a loop because `wait` can wake spuriously; the deadline is computed once with `time.monotonic()` to stay immune to wall-clock jumps. `put` returns `False` on timeout rather than raising.

```rust
use std::collections::HashMap;

struct Node {
    key: i32,
    value: i32,
    prev: usize,
    next: usize,
}

pub struct LruCache {
    cap: usize,
    map: HashMap<i32, usize>,
    nodes: Vec<Node>,
    head: usize, // most recently used sentinel index
    tail: usize, // least recently used sentinel index
}

const NIL: usize = usize::MAX;

impl LruCache {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        LruCache { cap: capacity, map: HashMap::new(), nodes: Vec::new(), head: NIL, tail: NIL }
    }

    fn detach(&mut self, i: usize) {
        let (p, n) = (self.nodes[i].prev, self.nodes[i].next);
        if p != NIL { self.nodes[p].next = n; } else { self.head = n; }
        if n != NIL { self.nodes[n].prev = p; } else { self.tail = p; }
    }

    fn attach_front(&mut self, i: usize) {
        self.nodes[i].prev = NIL;
        self.nodes[i].next = self.head;
        if self.head != NIL { self.nodes[self.head].prev = i; }
        self.head = i;
        if self.tail == NIL { self.tail = i; }
    }

    pub fn get(&mut self, key: i32) -> Option<i32> {
        let &i = self.map.get(&key)?;
        self.detach(i);
        self.attach_front(i);
        Some(self.nodes[i].value)
    }

    pub fn put(&mut self, key: i32, value: i32) {
        if let Some(&i) = self.map.get(&key) {
            self.nodes[i].value = value;
            self.detach(i);
            self.attach_front(i);
            return;
        }
        if self.map.len() == self.cap {
            let evicted = self.tail;
            self.detach(evicted);
            self.map.remove(&self.nodes[evicted].key);
        }
        let i = self.nodes.len();
        self.nodes.push(Node { key, value, prev: NIL, next: NIL });
        self.attach_front(i);
        self.map.insert(key, i);
    }
}

fn main() {
    let mut c = LruCache::new(2);
    c.put(1, 1); c.put(2, 2);
    assert_eq!(c.get(1), Some(1));   // 2 becomes LRU
    c.put(3, 3);                      // evicts 2
    assert_eq!(c.get(2), None);
    assert_eq!(c.get(3), Some(3));
}
```

Eviction uses the `tail` sentinel; `get` moves the hit to the front so recency is maintained. Indices avoid the borrow-checker friction of `Rc<RefCell>` while keeping all operations O(1).

