import re

_SEMVER = re.compile(
    r"^(?P<major>0|[1-9]\d*)\."
    r"(?P<minor>0|[1-9]\d*)\."
    r"(?P<patch>0|[1-9]\d*)"
    r"(?:-(?P<pre>[0-9A-Za-z.-]+))?"
    r"(?:\+(?P<build>[0-9A-Za-z.-]+))?$"
)


def parse_semver(text):
    m = _SEMVER.match(text)
    if not m:
        raise ValueError(f"invalid semver: {text!r}")
    pre = m.group("pre")
    pre_ids = pre.split(".") if pre else []
    # numeric identifiers sort below alphanumeric ones; keep strings, compare manually
    return (int(m.group("major")), int(m.group("minor")),
            int(m.group("patch")), pre_ids)


def compare(a, b):
    """Compare two parsed versions per semver precedence rules."""
    for x, y in zip(a[:3], b[:3]):
        if x != y:
            return -1 if x < y else 1
    pa, pb = a[3], b[3]
    if not pa and not pb:
        return 0
    if not pa:
        return 1      # a has no prerelease -> higher precedence
    if not pb:
        return -1
    for x, y in zip(pa, pb):
        if x == y:
            continue
        xnum, ynum = x.isdigit(), y.isdigit()
        if xnum and ynum:
            return -1 if int(x) < int(y) else 1
        if xnum:
            return -1
        if ynum:
            return 1
        return -1 if x < y else 1
    return (len(pa) > len(pb)) - (len(pa) < len(pb))


if __name__ == "__main__":
    a = parse_semver("1.2.3-beta.1+build.5")
    assert a == (1, 2, 3, ["beta", "1"])
    assert compare(parse_semver("1.0.0"), parse_semver("1.0.0-alpha")) == 1
    assert compare(parse_semver("1.0.0-alpha.1"), parse_semver("1.0.0-alpha")) == 1
    try:
        parse_semver("1.2")
        raise AssertionError("should have rejected")
    except ValueError:
        pass
    print("ok")
```

The regex enforces no leading zeros on numeric fields and anchors with `$`, so `1.2.3\n` is rejected. Prerelease precedence follows the spec: numeric identifiers rank below alphanumeric, and a version without a prerelease outranks one with.

```python
import sys

def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        if r1 - l1 > end - start:
            start, end = l1, r1
        l2, r2 = expand(i, i + 1)
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end + 1]

if __name__ == "__main__":
    sys.setrecursionlimit(10000)
    cases = ["babad", "cbbd", "", "a", "forgeeksskeegfor", "abacaba"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```

The function grows a palindrome outward from each center (odd and even), tracking the widest span. It handles the empty string, single characters, and mixed odd/even palindromes. Complexity is O(n^2) time, O(1) extra space.

