import csv
import sys
from collections import defaultdict

def compute_balances(path: str) -> dict:
    balances = defaultdict(float)
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        if not {"account", "amount"} <= set(reader.fieldnames or []):
            raise ValueError("CSV must have account and amount columns")
        for lineno, row in enumerate(reader, start=2):
            try:
                account = row["account"].strip()
                amount = float(row["amount"])
            except (KeyError, ValueError, AttributeError) as exc:
                print(f"skipping line {lineno}: {exc}", file=sys.stderr)
                continue
            if not account:
                print(f"skipping line {lineno}: empty account", file=sys.stderr)
                continue
            balances[account] += amount
    return dict(balances)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("usage: balances.py <file.csv>", file=sys.stderr)
        sys.exit(2)
    result = compute_balances(sys.argv[1])
    for account in sorted(result):
        print(f"{account}: {result[account]:.2f}")
```

`DictReader` gives us a header check and line numbers for diagnostics; malformed rows are reported on stderr but do not abort the run. Balances accumulate per account and print sorted by account name.

