#include <algorithm>
#include <cctype>
#include <iostream>
#include <map>
#include <string>
#include <utility>
#include <vector>

std::vector<std::pair<std::string, int>> word_counts(const std::string& text) {
    std::map<std::string, int> freq;
    std::string cur;
    for (unsigned char ch : text) {
        if (std::isalnum(ch)) {
            cur.push_back(static_cast<char>(std::tolower(ch)));
        } else if (!cur.empty()) {
            ++freq[cur];
            cur.clear();
        }
    }
    if (!cur.empty()) ++freq[cur];

    std::vector<std::pair<std::string, int>> out(freq.begin(), freq.end());
    std::sort(out.begin(), out.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });
    return out;
}

int main() {
    std::string text = "The quick brown fox, the lazy dog! The fox.";
    for (const auto& [word, count] : word_counts(text)) {
        std::cout << word << " " << count << "\n";
    }
    return 0;
}
```

`std::isalnum`/`tolower` on `unsigned char` avoid undefined behaviour with non-ASCII bytes. The final partial word is flushed after the loop, so text without trailing punctuation is handled.

```c
#include <stdio.h>

size_t dedup(int *arr, size_t n) {
    size_t write = 0;
    for (size_t i = 0; i < n; ++i) {
        int seen = 0;
        for (size_t j = 0; j < write; ++j) {
            if (arr[j] == arr[i]) {
                seen = 1;
                break;
            }
        }
        if (!seen) arr[write++] = arr[i];
    }
    return write;
}

int main(void) {
    int data[] = {3, 1, 3, 2, 1, 5, 2, 9};
    size_t n = sizeof(data) / sizeof(data[0]);
    size_t m = dedup(data, n);
    for (size_t i = 0; i < m; ++i) {
        printf("%d%s", data[i], i + 1 < m ? " " : "\n");
    }
    printf("count=%zu\n", m);
    return 0;
}
```

Order is preserved because each element is compared only against the already-written prefix. `write` acts as both the result length and the write cursor. Works for an empty array (`n == 0`), returning 0.

