fn fib(n: u32) -> u128 {
    fn fib_pair(n: u32) -> (u128, u128) {
        if n == 0 {
            (0, 1)
        } else {
            let (a, b) = fib_pair(n / 2);
            let c = a * (2 * b - a);
            let d = a * a + b * b;
            if n % 2 == 0 {
                (c, d)
            } else {
                (d, c + d)
            }
        }
    }
    fib_pair(n).0
}

