use std::io::{self, BufRead};

#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
struct Version {
    major: u64,
    minor: u64,
    patch: u64,
}

fn parse(input: &str) -> Result<Version, String> {
    let mut parts = input.trim().splitn(3, '.');
    let mut next = |name: &str| -> Result<u64, String> {
        parts
            .next()
            .ok_or_else(|| format!("missing {name}"))?
            .parse::<u64>()
            .map_err(|_| format!("invalid {name}"))
    };
    Ok(Version {
        major: next("major")?,
        minor: next("minor")?,
        patch: next("patch")?,
    })
}

fn main() {
    let stdin = io::stdin();
    let mut versions = Vec::new();
    for line in stdin.lock().lines() {
        let line = line.expect("read line");
        if line.trim().is_empty() {
            continue;
        }
        match parse(&line) {
            Ok(v) => versions.push(v),
            Err(e) => eprintln!("skip {line:?}: {e}"),
        }
    }
    versions.sort();
    for v in &versions {
        println!("{}.{}.{}", v.major, v.minor, v.patch);
    }
}
```

`Version` derives `Ord`, so sorting is lexicographic on `(major, minor, patch)`. `splitn(3, '.')` keeps a fourth component inside `patch` and lets `patch.parse` fail cleanly. Invalid lines are reported to stderr and skipped; empty lines are ignored.

```rust
use std::net::Ipv4Addr;
use std::str::FromStr;

pub fn parse_ipv4(s: &str) -> Result<Ipv4Addr, String> {
    if s.is_empty() {
        return Err("empty input".into());
    }
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return Err(format!("expected 4 octets, got {}", parts.len()));
    }
    let mut octets = [0u8; 4];
    for (i, part) in parts.iter().enumerate() {
        if part.is_empty() {
            return Err(format!("octet {i} is empty"));
        }
        if part.len() > 1 && part.starts_with('0') {
            return Err(format!("octet {i} has a leading zero: {part}"));
        }
        if !part.bytes().all(|b| b.is_ascii_digit()) {
            return Err(format!("octet {i} is not numeric: {part}"));
        }
        octets[i] = u8::from_str(part)
            .map_err(|_| format!("octet {i} out of range: {part}"))?;
    }
    Ok(Ipv4Addr::from(octets))
}

fn main() {
    for s in ["192.168.0.1", "256.1.1.1", "1.2.3", "01.2.3.4", "1.2.3.4.5", ""] {
        println!("{s:?} -> {:?}", parse_ipv4(s));
    }
}
```

The parser rejects the four common malformed shapes: empty input, wrong octet count, non-numeric or empty octets, and leading-zero forms. `u8::from_str` enforces the 0–255 range. `Ipv4Addr::from` guarantees a canonical result.

