fn binary_search(sorted: &[i32], target: i32) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = sorted.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if sorted[mid] == target {
            return Some(mid);
        } else if sorted[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    None
}

fn main() {
    let data = [1, 3, 5, 7, 9, 11];
    assert_eq!(binary_search(&data, 1), Some(0));
    assert_eq!(binary_search(&data, 11), Some(5));
    assert_eq!(binary_search(&data, 6), None);
    assert_eq!(binary_search(&[], 3), None);
    println!("ok");
}
