```python
class FullStack(Exception):
    pass

class EmptyStack(Exception):
    pass

class BoundedStack:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._cap = capacity
        self._items = []

    def push(self, value):
        if len(self._items) >= self._cap:
            raise FullStack("stack is full")
        self._items.append(value)

    def pop(self):
        if not self._items:
            raise EmptyStack("stack is empty")
        return self._items.pop()

    def peek(self):
        if not self._items:
            raise EmptyStack("stack is empty")
        return self._items[-1]

    def __len__(self):
        return len(self._items)


if __name__ == "__main__":
    s = BoundedStack(2)
    s.push(1); s.push(2)
    assert s.peek() == 2 and len(s) == 2
    assert s.pop() == 2 and s.pop() == 1
    try:
        s.pop()
    except EmptyStack:
        pass
    else:
        raise AssertionError("expected EmptyStack")
    print("ok")
```

```python
import heapq


def median(nums):
    if not nums:
        raise ValueError("median of empty sequence")

    lo = []  # max-heap (negated) for the smaller half
    hi = []  # min-heap for the larger half

    for x in nums:
        heapq.heappush(lo, -x)
        heapq.heappush(hi, -heapq.heappop(lo))
        if len(hi) > len(lo):
            heapq.heappush(lo, -heapq.heappop(hi))

    if len(lo) == len(hi):
        return (-lo[0] + hi[0]) / 2.0
    return float(-lo[0])


if __name__ == "__main__":
    assert median([1, 2, 3]) == 2.0
    assert median([4, 1, 3, 2]) == 2.5
    assert median([7]) == 7.0
    assert median([-5, -1, -3]) == -3.0
    try:
        median([])
    except ValueError as e:
        assert str(e) == "median of empty sequence"
    print("ok")
```

Two heaps keep the lower half in a max-heap and the upper half in a min-heap; rebalancing after each insert gives O(log n) per element and O(1) median lookup. Empty input raises rather than returning a bogus value.

