```rust
struct Pairs<'a, T> {
    slice: &'a [T],
    idx: usize,
}

impl<'a, T> Iterator for Pairs<'a, T> {
    type Item = (&'a T, &'a T);

    fn next(&mut self) -> Option<Self::Item> {
        if self.idx + 1 >= self.slice.len() {
            return None;
        }
        let out = (&self.slice[self.idx], &self.slice[self.idx + 1]);
        self.idx += 1;
        Some(out)
    }
}

fn pairs<T>(slice: &[T]) -> Pairs<'_, T> {
    Pairs { slice, idx: 0 }
}

fn main() {
    let data = [1, 2, 3, 4];
    let got: Vec<(i32, i32)> = pairs(&data).map(|(a, b)| (*a, *b)).collect();
    assert_eq!(got, vec![(1, 2), (2, 3), (3, 4)]);
    assert_eq!(pairs::<i32>(&[]).count(), 0);
    assert_eq!(pairs(&[7]).count(), 0);
    println!("ok");
}
```

The adapter holds only a borrowed slice and an index, so it borrows rather than copies. The bound check `idx + 1 >= len` gracefully handles empty and single-element slices with no special-casing at the call site.

