template <typename Container, typename T>
long index_of(const Container& c, const T& value) {
    using Size = decltype(c.size());
    static_assert(std::is_integral<Size>::value, "container must expose an integral size()");
    for (Size i = 0; i < c.size(); ++i) {
        if (c[i] == value) {
