#include <cstdint>
#include <iostream>
#include <vector>

std::uint64_t fib(int n) {
    static std::vector<std::uint64_t> memo = {0, 1};
    if (n < 0) {
        throw std::invalid_argument("n must be non-negative");
    }
    while (memo.size() <= static_cast<std::size_t>(n)) {
        memo.push_back(memo[memo.size() - 1] + memo[memo.size() - 2]);
    }
    return memo[n];
}

int main() {
    std::cout << fib(10) << '\n';  // 55
    std::cout << fib(50) << '\n';  // 12586269025
    // fib(93) is the largest that fits in uint64_t; fib(94) overflows.
}
