bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') {
        return false;
    }
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno == ERANGE || end == s || *end != '\0') {
        return false;
    }
    if (v < INT_MIN || v > INT_MAX) {
        return false;
    }
    *out = (int)v;
    return true;
}

int main(void) {
    int out;
    printf("%d\n", parse_int("42", &out));       /* 1 */
    printf("%d\n", parse_int("  7", &out));       /* 0: trailing space rejected */
    printf("%d\n", parse_int("99999999999", &out)); /* 0: overflow */
    printf("%d\n", parse_int("", &out));          /* 0 */
    return 0;
}
