```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL) {
        return head;
    }
    n->value = value;
    n->next = head;
    return n;
}

static Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static void print_list(const Node *head) {
    if (head == NULL) {
        printf("(empty)\n");
        return;
    }
    for (; head != NULL; head = head->next) {
        printf("%d", head->value);
        if (head->next != NULL) {
            printf(" -> ");
        }
    }
    printf("\n");
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    print_list(NULL);
    Node *head = NULL;
    for (int i = 5; i >= 1; --i) {
        head = push(head, i);
    }
    print_list(head);
    head = reverse(head);
    print_list(head);
    free_list(head);
    return 0;
}
```

`reverse` rewires `next` pointers with three cursors and returns the new head. An empty list prints `(empty)`; `push` checks `malloc` so allocation failure doesn't crash.

