```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

template <std::size_t N>
class RingBuffer {
public:
    void push(int value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) {
            ++size_;
        }
    }

    int at(std::size_t index) const {
        if (index >= size_) {
            throw std::out_of_range("ring buffer index out of range");
        }
        std::size_t start = (head_ + N - size_) % N;
        return data_[(start + index) % N];
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<3> rb;
    if (!rb.empty()) return 1;
    for (int i = 1; i <= 5; ++i) rb.push(i);
    for (std::size_t i = 0; i < rb.size(); ++i) std::cout << rb.at(i) << "\n";
    try {
        rb.at(9);
    } catch (const std::out_of_range &e) {
        std::cout << "caught: " << e.what() << "\n";
    }
    return 0;
}
```

Capacity 3 after pushing 1..5 holds `3 4 5`. `head_` is the next write slot; logical order starts at `(head_ + N - size_) % N`. Out-of-range reads throw instead of touching stale memory.

```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[], &[1, 2]), vec![1, 2]);
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 3]), vec![1, 1, 1, 2, 3]);
    assert_eq!(merge_sorted(&[i32::MIN], &[i32::MAX]), vec![i32::MIN, i32::MAX]);
    println!("{:?}", merge_sorted(&[1, 4, 9], &[2, 3, 10]));
}
```

`<=` keeps equal elements taking from the left side, so the merge is stable. Remaining tails are appended with `extend_from_slice`. Empty inputs fall out naturally; `i32::MIN`/`MAX` compare without overflow because only copying happens.

