#include <cstddef>
#include <cassert>
#include <cstring>

// Reverses the bytes of a null-terminated string in place.
// Safe for an empty string (first char is '\0'), non-owning.
void reverse_cstr(char* s) {
    if (s == nullptr) {
        return; // nothing to do, do not dereference null
    }

    std::size_t len = 0;
    while (s[len] != '\0') {
        ++len;
    }
    if (len < 2) {
        return; // empty or single character is already reversed
    }

    std::size_t left = 0;
    std::size_t right = len - 1;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        ++left;
        --right;
    }
}

int main() {
    char a[] = "hello";
    reverse_cstr(a);
    assert(std::strcmp(a, "olleh") == 0);

    char b[] = "";
    reverse_cstr(b);
    assert(std::strcmp(b, "") == 0);

    char c[] = "x";
    reverse_cstr(c);
    assert(std::strcmp(c, "x") == 0);

    char d[] = "ab";
    reverse_cstr(d);
    assert(std::strcmp(d, "ba") == 0);

    reverse_cstr(nullptr); // must not crash
    return 0;
}
