/// Binary search a slice sorted in ascending order.
/// Returns the index of *a* matching element, or None if absent.
/// Works for an empty slice and uses overflow-safe midpoint math.
pub fn binary_search<T: Ord>(haystack: &[T], needle: &T) -> Option<usize> {
    let mut low: usize = 0;
    let mut high: usize = haystack.len(); // exclusive bound

    while low < high {
        // Avoid (low + high) overflow and keep the loop strictly shrinking.
        let mid = low + (high - low) / 2;
        match haystack[mid].cmp(needle) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => low = mid + 1,
            std::cmp::Ordering::Greater => high = mid,
        }
    }
    None
}

fn main() {
    let data = [1, 3, 3, 5, 8, 13, 21];
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &21), Some(6));
    assert_eq!(binary_search(&data, &8), Some(4));
    assert!(binary_search(&data, &2).is_none());

    let empty: [i32; 0] = [];
    assert!(binary_search(&empty, &1).is_none());

    // Duplicates: any matching index is acceptable.
    match binary_search(&data, &3) {
        Some(i) => assert_eq!(data[i], 3),
        None => panic!("3 is present"),
    }

    let words = ["apple", "banana", "cherry"];
    assert_eq!(binary_search(&words, &"banana"), Some(1));
    println!("all checks passed");
}
