from collections import deque
from typing import Any


class BoundedQueue:
    """A FIFO queue holding at most `capacity` items.

    Pushing into a full queue evicts the oldest item. The number of
    evictions is tracked in `dropped`.
    """

    def __init__(self, capacity: int) -> None:
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._items: deque[Any] = deque()
        self.dropped = 0

    def push(self, item: Any) -> Any | None:
        """Add `item`; return the evicted oldest item, or None."""
        evicted = None
        if len(self._items) >= self.capacity:
            evicted = self._items.popleft()
            self.dropped += 1
        self._items.append(item)
        return evicted

    def pop(self) -> Any:
        if not self._items:
            raise IndexError("pop from empty BoundedQueue")
        return self._items.popleft()

    def __len__(self) -> int:
        return len(self._items)

    def __bool__(self) -> bool:
        return bool(self._items)


if __name__ == "__main__":
    q = BoundedQueue(2)
    assert q.push("a") is None
    assert q.push("b") is None
    assert q.push("c") == "a"  # capacity reached, oldest evicted
    assert q.dropped == 1
    assert len(q) == 2
    assert q.pop() == "b"
    assert q.pop() == "c"
    assert not q
    try:
        q.pop()
    except IndexError:
        pass
    else:
        raise AssertionError("expected IndexError")
    try:
        BoundedQueue(0)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for capacity 0")
    print("all checks passed")
