import os
import sys
from collections import defaultdict


def size_by_extension(root: str) -> dict:
    totals = defaultdict(int)
    counts = defaultdict(int)

    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort()
        for name in sorted(filenames):
            path = os.path.join(dirpath, name)
            try:
                size = os.path.getsize(path)
            except OSError as exc:
                print(f"skip {path}: {exc}", file=sys.stderr)
                continue
            ext = os.path.splitext(name)[1].lower() or "<none>"
            totals[ext] += size
            counts[ext] += 1

    return {ext: (totals[ext], counts[ext]) for ext in totals}


def human(n: int) -> str:
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if n < 1024 or unit == "TB":
            return f"{n:.1f} {unit}"
        n /= 1024


if __name__ == "__main__":
    target = sys.argv[1] if len(sys.argv) > 1 else "."
    report = size_by_extension(target)
    for ext in sorted(report, key=lambda e: report[e][0], reverse=True):
        total, count = report[ext]
        print(f"{ext:>8}  {human(total):>10}  {count:>5} file(s)")
