```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.data = OrderedDict()

    def get(self, key):
        if key not in self.data:
            return -1
        self.data.move_to_end(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.data.move_to_end(key)
        self.data[key] = value
        if len(self.data) > self.capacity:
            self.data.popitem(last=False)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, 1)
    c.put(2, 2)
    print(c.get(1))   # 1
    c.put(3, 3)       # evicts key 2
    print(c.get(2))   # -1
    print(c.get(3))   # 3
```

`OrderedDict.move_to_end` marks a key as freshly used in constant time, and `popitem(last=False)` evicts the oldest entry when capacity is exceeded. A non-positive capacity raises immediately rather than silently wasting every insert.

