OPEN = "([{"
CLOSE = ")]}"
MATCH = {")": "(", "]": "[", "}": "{"}


def balanced(text):
    stack = []
    quote = None
    for ch in text:
        if quote is not None:
            if ch == quote:
                quote = None
            continue
        if ch in "\"'":
            quote = ch
        elif ch in OPEN:
            stack.append(ch)
        elif ch in CLOSE:
            if not stack or stack[-1] != MATCH[ch]:
                return False
            stack.pop()
    return quote is None and not stack


