    for s in strings[1:]:
        limit = min(len(prefix), len(s))
        i = 0
        while i < limit and prefix[i] == s[i]:
            i += 1
        prefix = prefix[:i]
        if not prefix:
            return 0
    return len(prefix)


if __name__ == "__main__":
    cases = [
        (["flower", "flow", "flight"], 2),
        ([], 0),
        (["caf\u00e9", "caf\u00e9teria"], 4),
        (["abc", "xyz"], 0),
        (["single"], 6),
    ]
    for strings, expected in cases:
        got = longest_common_prefix(strings)
        assert got == expected, (strings, got, expected)
    print("all cases passed")
```

