```c
#include <stdio.h>
#include <string.h>

int is_balanced(const char *s) {
    char stack[256];
    size_t top = 0;
    for (size_t i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == '(' || c == '{' || c == '[') {
            if (top >= sizeof(stack)) {
                return 0;
            }
            stack[top++] = c;
        } else if (c == ')' || c == '}' || c == ']') {
            if (top == 0) {
                return 0;
            }
            char open = stack[--top];
            if ((c == ')' && open != '(') ||
                (c == '}' && open != '{') ||
                (c == ']' && open != '[')) {
                return 0;
            }
        }
    }
    return top == 0;
}

int main(void) {
    const char *ok[] = {"", "()", "{[()]}", "a(b)c[d]"};
    const char *bad[] = {"(", ")]", "([)]", "(()"};
    for (size_t i = 0; i < sizeof(ok) / sizeof(ok[0]); i++) {
        if (!is_balanced(ok[i])) {
            printf("FAIL: %s should be balanced\n", ok[i]);
            return 1;
        }
    }
    for (size_t i = 0; i < sizeof(bad) / sizeof(bad[0]); i++) {
        if (is_balanced(bad[i])) {
            printf("FAIL: %s should not be balanced\n", bad[i]);
            return 1;
        }
    }
    printf("all cases passed\n");
    return 0;
}
```

It pushes openers onto a fixed stack and matches closers against the top; an empty string is balanced.

