```c
#include <stdio.h>

static void reverse(int *a, int lo, int hi) {
    while (lo < hi) {
        int tmp = a[lo];
        a[lo++] = a[hi];
        a[hi--] = tmp;
    }
}

void rotate_left(int *a, int n, int k) {
    if (n <= 1) {
        return;
    }
    k %= n;
    if (k < 0) {
        k += n;
    }
    if (k == 0) {
        return;
    }
    reverse(a, 0, k - 1);
    reverse(a, k, n - 1);
    reverse(a, 0, n - 1);
}

int main(void) {
    int a[] = {1, 2, 3, 4, 5};
    int n = 5;
    rotate_left(a, n, 7);
    int expected[] = {3, 4, 5, 1, 2};
    for (int i = 0; i < n; i++) {
        if (a[i] != expected[i]) {
            printf("FAIL at %d: got %d want %d\n", i, a[i], expected[i]);
            return 1;
        }
    }
    printf("all cases passed\n");
    return 0;
}
```

The triple-reverse trick rotates in place with O(1) extra memory, and `k %= n` handles k larger than the array.

