```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    void push(int value) {
        std::unique_lock<std::mutex> lock(mtx_);
        not_full_.wait(lock, [this] { return q_.size() < cap_; });
        q_.push(value);
        lock.unlock();
        not_empty_.notify_one();
    }

    std::optional<int> try_pop() {
        std::unique_lock<std::mutex> lock(mtx_);
        if (q_.empty()) {
            return std::nullopt;
        }
        int value = q_.front();
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

private:
    std::size_t cap_;
    std::queue<int> q_;
    std::mutex mtx_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
};
```

`push` blocks while the queue is full, `try_pop` returns `std::nullopt` rather than blocking. Notifications are sent after unlocking so a woken thread never races for a mutex the caller still holds.

