```rust
fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match slice[mid].cmp(target) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    None
}

fn main() {
    let data = [1, 3, 3, 5, 8, 13];
    assert_eq!(binary_search(&data, &1), Some(0));
    assert_eq!(binary_search(&data, &13), Some(5));
    assert!(matches!(binary_search(&data, &4), None));
    assert!(matches!(binary_search::<i32>(&[], &7), None));
    // Midpoint formula avoids overflow that (lo + hi) / 2 could cause.
    println!("all tests passed");
}
```

`lo + (hi - lo) / 2` is used instead of `(lo + hi) / 2` so the midpoint can never overflow `usize` on a very large slice.

