// Returns the index of the first occurrence of target, or -1 if absent.
int firstOccurrence(const std::vector<int>& data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size()) - 1;
    int result = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (data[mid] == target) {
            result = mid;
            hi = mid - 1;  // keep searching left for an earlier match
        } else if (data[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return result;
}

