use std::collections::HashMap;

pub fn fib(n: u32) -> Option<u64> {
    let mut memo: HashMap<u32, u64> = HashMap::new();
    fib_memo(n, &mut memo)
}

fn fib_memo(n: u32, memo: &mut HashMap<u32, u64>) -> Option<u64> {
    if let Some(&v) = memo.get(&n) {
        return Some(v);
    }
    let value = match n {
        0 => 0,
        1 => 1,
        _ => {
            let a = fib_memo(n - 1, memo)?;
            let b = fib_memo(n - 2, memo)?;
            a.checked_add(b)?
        }
    };
    memo.insert(n, value);
    Some(value)
}

