std::optional<std::int64_t> parse_int64(const std::string& s) {
    std::size_t i = 0;
    bool negative = false;
    if (i < s.size() && (s[i] == '+' || s[i] == '-')) {
        negative = s[i] == '-';
        ++i;
    }
    if (i == s.size()) return std::nullopt;

    std::int64_t acc = 0;
    for (; i < s.size(); ++i) {
        char c = s[i];
        if (c < '0' || c > '9') return std::nullopt;
        int digit = c - '0';
        if (acc > (std::numeric_limits<std::int64_t>::max() - digit) / 10)
            return std::nullopt;
        acc = acc * 10 + digit;
    }
    if (negative) acc = -acc;
    return acc;
}
```

The overflow check is done *before* multiplying: `acc > (MAX - digit) / 10` guarantees `acc * 10 + digit` cannot exceed the maximum. The sign is applied at the end so the middle value stays non-negative and the bound is simple.

