template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& v) {
        if (count_ == N) return false;
        buf_[(head_ + count_) % N] = v;
        ++count_;
        return true;
    }
    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        T v = buf_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return v;
    }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }
    std::size_t size() const { return count_; }
private:
    std::array<T, N> buf_{};
    std::size_t head_ = 0, count_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    std::cout << rb.push(1) << rb.push(2) << rb.push(3) << rb.push(4) << '\n'; // 1110
    while (!rb.empty()) std::cout << *rb.pop();
