def longest_unique_bruteforce(s: str) -> str:
    """O(n^2) reference: check every substring for uniqueness."""
    best = ""
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            sub = s[i:j]
            if len(set(sub)) == len(sub) and len(sub) > len(best):
                best = sub
    return best


def longest_unique(s: str) -> str:
    """Sliding window, O(n) time and O(min(n, alphabet)) space."""
    last = {}
    start = 0
    best_start = best_len = 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        if i - start + 1 > best_len:
            best_len = i - start + 1
            best_start = start
    return s[best_start:best_start + best_len]


if __name__ == "__main__":
    cases = ["", "a", "abcabcbb", "bbbbb", "pwwkew", "\u00e9\u00e9\u00e9", "abba"]
    for c in cases:
        a, b = longest_unique(c), longest_unique_bruteforce(c)
        assert len(a) == len(b), (c, a, b)
    assert longest_unique("abcabcbb") == "abc"
    assert longest_unique("pwwkew") == "wke"
    assert longest_unique("") == ""
    print("all checks passed")
