#include <array>
#include <cstddef>
#include <cassert>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity), buf_{}, head_(0), size_(0) {
        assert(capacity > 0);
    }

    bool push(double v) {
        if (size_ == cap_) return false;
        buf_[(head_ + size_) % cap_] = v;
        ++size_;
        return true;
    }

    std::optional<double> pop() {
        if (size_ == 0) return std::nullopt;
        double v = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }

private:
    std::size_t cap_;
    std::array<double, 8> buf_;
    std::size_t head_;
    std::size_t size_;
};

int main() {
    RingBuffer rb(3);
    assert(rb.pop() == std::nullopt);
    assert(rb.push(1.5) && rb.push(2.5) && rb.push(3.5));
    assert(!rb.push(4.5));
    assert(rb.pop() == 1.5);
    assert(rb.push(4.5));
    assert(rb.size() == 3);
    return 0;
}
```
