#include <iostream>
#include <limits>
#include <optional>
#include <cstdint>

std::uint64_t gcd(std::uint64_t a, std::uint64_t b) {
    while (b != 0) {
        std::uint64_t t = a % b;
        a = b;
        b = t;
    }
    return a;
}

std::optional<std::uint64_t> lcm(std::uint64_t a, std::uint64_t b) {
    if (a == 0 || b == 0) return 0;
    std::uint64_t g = gcd(a, b);
    std::uint64_t reduced = a / g;
    if (reduced > std::numeric_limits<std::uint64_t>::max() / b) {
        return std::nullopt;  // would overflow
    }
    return reduced * b;
}

int main() {
    if (auto v = lcm(21, 6)) std::cout << *v << '\n';       // 42
    if (auto v = lcm(0, 5)) std::cout << *v << '\n';         // 0
    std::cout << (lcm(1ULL << 63, 2) ? "ok" : "overflow") << '\n';
    return 0;
}
