```rust
fn quickselect(arr: &mut [i64], k: usize) -> Option<i64> {
    if k == 0 || k > arr.len() {
        return None;
    }
    let target = k - 1;
    let (mut lo, mut hi) = (0usize, arr.len() - 1);
    loop {
        if lo == hi {
            return Some(arr[lo]);
        }
        let pivot_index = partition(arr, lo, hi);
        if pivot_index == target {
            return Some(arr[pivot_index]);
        } else if target < pivot_index {
            hi = pivot_index - 1;
        } else {
            lo = pivot_index + 1;
        }
    }
}

fn partition(arr: &mut [i64], lo: usize, hi: usize) -> usize {
    let pivot = arr[hi];
    let mut store = lo;
    for i in lo..hi {
        if arr[i] < pivot {
            arr.swap(i, store);
            store += 1;
        }
    }
    arr.swap(store, hi);
    store
}

fn main() {
    let mut data = vec![7, 10, 4, 3, 20, 15];
    assert_eq!(quickselect(&mut data.clone(), 3), Some(7));
    assert_eq!(quickselect(&mut data.clone(), 4), Some(10));
    assert_eq!(quickselect(&mut data, 0), None);
    println!("ok");
}
```
Quickselect is expected O(n) with random pivots; the last element is used here, so worst case is O(n^2).

