use std::collections::HashMap;
use std::io::{self, BufRead};

fn word_counts(input: &str) -> HashMap<String, usize> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for raw in input.split_whitespace() {
        // Strip surrounding punctuation, keep internal apostrophes/hyphens.
        let trimmed = raw.trim_matches(|c: char| !c.is_alphanumeric() && c != '\'' && c != '-');
        if trimmed.is_empty() {
            continue;
        }
        *counts.entry(trimmed.to_lowercase()).or_insert(0) += 1;
    }
    counts
}

fn main() -> io::Result<()> {
    let mut input = String::new();
    for line in io::stdin().lock().lines() {
        input.push_str(&line?);
        input.push('\n');
    }

    let mut counts: Vec<(String, usize)> = word_counts(&input).into_iter().collect();
    // Count desc, then word asc for deterministic ties.
    counts.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    if counts.is_empty() {
        eprintln!("no words on stdin");
        return Ok(());
    }

    for (word, n) in counts.into_iter().take(5) {
        println!("{n}\t{word}");
    }
    Ok(())
}
```

`trim_matches` removes leading/trailing punctuation while preserving intra-word hyphens and apostrophes. Ties break alphabetically so output is reproducible. `or_insert(0) += 1` is the idiomatic counting pattern; `to_lowercase` makes counting case-insensitive.

```cpp
#include <charconv>
#include <cstdint>
#include <optional>
#include <string_view>

// Returns the address packed big-endian (first octet in the high byte),
// or std::nullopt if the string is not a valid dotted-quad IPv4 address.
std::optional<std::uint32_t> parse_ipv4(std::string_view s) {
    std::uint32_t result = 0;
    int octets = 0;

    while (octets < 4) {
        if (s.empty()) return std::nullopt;

        // Leading zero is invalid except for the literal "0".
        if (s.front() == '0' && s.size() >= 2 && s[1] >= '0' && s[1] <= '9')
            return std::nullopt;

        std::size_t i = 0;
        while (i < s.size() && s[i] >= '0' && s[i] <= '9') ++i;
        if (i == 0 || i > 3) return std::nullopt;  // no digits or > 255 width

        unsigned value = 0;
        auto [ptr, ec] = std::from_chars(s.data(), s.data() + i, value);
        if (ec != std::errc{} || value > 255) return std::nullopt;

        result = (result << 8) | value;
        ++octets;
        s.remove_prefix(i);

        if (octets == 4) return s.empty() ? std::optional{result} : std::nullopt;
        if (s.empty() || s.front() != '.') return std::nullopt;
        s.remove_prefix(1);
    }
    return std::nullopt;
}
```

`from_chars` is locale-independent and does not allocate. Digit-scanning first bounds each octet to three characters, so `> 255` is caught explicitly. Leading zeros like `01` are rejected because they are ambiguous across tools. The result packs octets high-to-low.

```rust
/// Merge two sorted slices into a new sorted Vec.
pub fn merge_new<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

/// In-place merge using `scratch` as workspace for the left half.
/// `scratch` must be at least as long as `a`.
pub fn merge_in_place<T: Ord>(a: &mut [T], b: &mut [T], scratch: &mut [T]) {
    let n = a.len();
    assert!(scratch.len() >= n, "scratch too small");
    scratch[..n].clone_from_slice(a);

    let (mut i, mut j, mut k) = (0, 0, 0);
    while i < n && j < b.len() {
        if scratch[i] <= b[j] {
            a[k] = scratch[i].clone();
            i += 1;
        } else {
            a[k] = b[j].clone();
            j += 1;
        }
        k += 1;
    }
    while i < n {
        a[k] = scratch[i].clone();
        i += 1;
        k += 1;
    }
    while j < b.len() {
        a[k] = b[j].clone();
        j += 1;
        k += 1;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn merge_empty_and_one_sided() {
        assert_eq!(merge_new::<i32>(&[], &[]), Vec::<i32>::new());
        assert_eq!(merge_new(&[1, 3, 5], &[]), vec![1, 3, 5]);
        assert_eq!(merge_new::<i32>(&[], &[2, 4]), vec![2, 4]);
    }

    #[test]
    fn merge_interleaved_with_duplicates() {
        let mut a = [1, 3, 5, 7];
        let mut b = [2, 3, 8];
        assert_eq!(merge_new(&a, &b), vec![1, 2, 3, 3, 5, 7, 8]);
        let mut scratch = [0i32; 4];
        merge_in_place(&mut a, &mut b, &mut scratch);
        assert_eq!(a, [1, 2, 3, 3]);
        assert_eq!(b, [5, 7, 8]);
    }
}
```

`merge_in_place` copies `a` to the scratch buffer, then writes the merged result back over `a` and the left part of `b`, matching Rust's `slice::merge` style. `merge_new` is the straightforward allocating version. Tests cover empty sides, duplicates, and the in-place layout so the two halves stay sorted and contiguous.

