///
/// `alloc` returns a mutable slice whose start is aligned to `align`
/// (a power of two). Returns `None` when the buffer is exhausted.
/// Safe Rust only: the bump pointer is an index, not a raw pointer.
pub struct BumpAlloc<'a> {
    arena: &'a mut [u8],
    offset: usize,
}

impl<'a> BumpAlloc<'a> {
    pub fn new(arena: &'a mut [u8]) -> Self {
        Self { arena, offset: 0 }
    }

    /// Bytes used so far, including alignment padding.
    pub fn used(&self) -> usize {
        self.offset
    }

    /// Bytes still available (upper bound; ignores future alignment).
    pub fn remaining(&self) -> usize {
        self.arena.len() - self.offset
    }

    pub fn alloc(&mut self, size: usize, align: usize) -> Option<&mut [u8]> {
        if !align.is_power_of_two() {
            return None;
        }
        // Round the current offset up to the requested alignment.
        let aligned = match self.offset.checked_add(align - 1) {
            Some(rounded) => rounded & !(align - 1),
            None => return None,
        };
        let end = aligned.checked_add(size)?;
        if end > self.arena.len() {
            return None;
        }

        // Zero the block so callers see deterministic bytes.
        self.arena[aligned..end].fill(0);
        self.offset = end;
        Some(&mut self.arena[aligned..end])
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn alignment_and_exhaustion() {
        let mut buf = [0u8; 16];
        let mut bump = BumpAlloc::new(&mut buf);

        let a = bump.alloc(1, 1).unwrap();
        a[0] = 7;

        let b = bump.alloc(4, 4).unwrap();
        assert_eq!(b.len(), 4);
        // Start of b must be 4-aligned within the buffer.
        let base = buf.as_ptr() as usize;
        assert_eq!((b.as_ptr() as usize - base) % 4, 0);

        assert!(bump.alloc(64, 1).is_none());
        assert_eq!(bump.used(), 8);
    }

    #[test]
    fn rejects_non_power_of_two_align() {
        let mut buf = [0u8; 8];
        let mut bump = BumpAlloc::new(&mut buf);
        assert!(bump.alloc(1, 3).is_none());
    }
}
```

This stays safe by tracking an offset into a borrowed slice and handing out subslices; the test subtracts the arena base pointer to confirm alignment. `align.is_power_of_two()` and `checked_add` guard the shift-and-mask and overflow paths.

```python
def longest_palindrome(s: str) -> str:
    """Return the longest palindromic substring of s."""
    if not s:
        return ""

    start, end = 0, 0

    def expand(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)       # odd-length centers
        l2, r2 = expand(i, i + 1)   # even-length centers
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["", "a", "bb", "babad", "cbbd", "abacaba", "😀ab😀"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```

`expand` grows outward while the characters match and returns the last valid bounds. Running it from every index for both odd and even centers covers all palindromes in O(n²) time and O(1) extra space. It handles the empty string, single characters, Unicode like `😀ab😀` (which is a palindrome by code point), and returns the earliest longest match when there are ties.

