#include <limits.h>
#include <stdio.h>
#include <stdbool.h>

/* Parse a signed long from s. Returns true and stores the value in *out
   only if the whole string is a valid, in-range integer. */
static bool parse_long(const char *s, long *out) {
    if (s == NULL || *s == '\0') {
        return false;
    }

    bool negative = false;
    if (*s == '+' || *s == '-') {
        negative = (*s == '-');
        s++;
    }
    if (*s < '0' || *s > '9') {
        return false;
    }

    unsigned long acc = 0;
    const unsigned long limit = negative
        ? (unsigned long)LONG_MAX + 1UL
        : (unsigned long)LONG_MAX;

    for (; *s != '\0'; s++) {
        if (*s < '0' || *s > '9') {
            return false;
        }
        unsigned digit = (unsigned)(*s - '0');
        if (acc > (limit - digit) / 10UL) {
            return false; /* would overflow */
        }
        acc = acc * 10UL + digit;
    }

    *out = negative ? -(long)acc : (long)acc;
    return true;
}

int main(void) {
    const char *tests[] = {"123", "-42", "+7", "", "12x", " 5",
                           "9223372036854775807", "9223372036854775808",
                           "-9223372036854775808", "-9223372036854775809"};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); i++) {
        long v = 0;
        bool ok = parse_long(tests[i], &v);
        if (ok) {
            printf("%-22s -> %ld\n", tests[i], v);
        } else {
            printf("%-22s -> invalid\n", tests[i]);
        }
    }
    return 0;
}
```

The parser converts into `unsigned long` and checks `acc > (limit - digit) / 10` before each multiply-add, so the overflow test itself cannot overflow. It rejects empty input, spaces, trailing garbage, and out-of-range values on both ends of the `long` range.

