```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

template <typename T, std::size_t N>
class RingBuffer {
    static_assert(N > 0, "capacity must be positive");

    std::array<T, N> data_{};
    std::size_t head_ = 0;  // next slot to write
    std::size_t count_ = 0; // number of live elements

public:
    bool push(const T& value) {
        if (full()) {
            return false; // caller decides whether to drop oldest
        }
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        ++count_;
        return true;
    }

    bool push_overwrite(const T& value) {
        if (full()) {
            // overwrite the oldest element
            std::size_t tail = (head_ + N - count_) % N;
            data_[tail] = value;
            head_ = (head_ + 1) % N;
            return true;
        }
        return push(value);
    }

    std::optional<T> pop() {
        if (empty()) {
            return std::nullopt;
        }
        std::size_t tail = (head_ + N - count_) % N;
        T value = data_[tail];
        count_ -= 1;
        return value;
    }

    const T& at(std::size_t i) const {
        if (i >= count_) {
            throw std::out_of_range("ring buffer index out of range");
        }
        return data_[(head_ + N - count_ + i) % N];
    }

    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }
    std::size_t size() const { return count_; }
    static constexpr std::size_t capacity() { return N; }
};

int main() {
    RingBuffer<int, 3> rb;
    for (int i = 1; i <= 5; ++i) {
        rb.push_overwrite(i);
    }
    for (std::size_t i = 0; i < rb.size(); ++i) {
        std::cout << rb.at(i) << ' ';
    }
    std::cout << '\n';
    while (auto v = rb.pop()) {
        std::cout << *v << ' ';
    }
    std::cout << "\nempty=" << rb.empty() << '\n';
    return 0;
}
```

`head_` advances modulo `N`; the logical tail is derived as `(head_ + N - count_) % N`. `push` returns `false` when full rather than overwriting silently, while `push_overwrite` drops the oldest entry. `pop` returns `std::optional` so an empty buffer is never read, and `at` bounds-checks. Output is `3 4 5` then `3 4 5`.

