```rust
#[derive(Debug, PartialEq)]
pub enum BracketError {
    UnmatchedClose { index: usize, ch: char },
    Unclosed { index: usize, ch: char },
}

pub fn check_brackets(s: &str) -> Result<(), BracketError> {
    let mut stack: Vec<(usize, char)> = Vec::new();

    for (index, ch) in s.char_indices() {
        match ch {
            '(' | '[' | '{' => stack.push((index, ch)),
            ')' | ']' | '}' => {
                let expected = match ch {
                    ')' => '(',
                    ']' => '[',
                    _ => '{',
                };
                match stack.pop() {
                    Some((_, open)) if open == expected => {}
                    _ => return Err(BracketError::UnmatchedClose { index, ch }),
                }
            }
            _ => {}
        }
    }

    match stack.last() {
        Some(&(index, ch)) => Err(BracketError::Unclosed { index, ch }),
        None => Ok(()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn balanced() {
        assert_eq!(check_brackets("a(b[c]{d})e"), Ok(()));
        assert_eq!(check_brackets(""), Ok(()));
    }

    #[test]
    fn mismatches() {
        assert_eq!(
            check_brackets("(]"),
            Err(BracketError::UnmatchedClose { index: 1, ch: ']' })
        );
        assert_eq!(
            check_brackets("([)"),
            Err(BracketError::UnmatchedClose { index: 2, ch: ')' })
        );
        assert_eq!(
            check_brackets("({["),
            Err(BracketError::Unclosed { index: 0, ch: '(' })
        );
    }
}
```

The stack stores the index and opening character of every unmatched opener. A closing bracket must match the most recent opener, otherwise the error points at the closing character's index. If the stack is non-empty at the end, the earliest unclosed opener is reported using `stack.last()`.

