from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict[str, int] = OrderedDict()

    def get(self, key: str) -> int | None:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: str, value: int) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            evicted, _ = self._data.popitem(last=False)
            print(f"evicted: {evicted}")

    def keys(self) -> list[str]:
        return list(self._data.keys())


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    print(cache.get("a"))      # 1, makes 'a' most recent
    cache.put("c", 3)          # evicts 'b'
    print(cache.get("b"))      # None
    cache.put("a", 9)          # update in place
    print(cache.get("a"))      # 9
    print(cache.keys())        # ['c', 'a']
```

`OrderedDict` keeps insertion order and `move_to_end` marks a key as most recently used, so both operations are O(1). On overflow, `popitem(last=False)` removes the least recently used entry, which prints the evicted key. Updating an existing key refreshes its recency before writing the new value.

