size_t reverse_in_place(char *s) {
    size_t len = 0;
    if (s == NULL) {
        return 0;
    }
    while (s[len] != '\0') {
        len++;
    }
    for (size_t i = 0; i < len / 2; i++) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
    return len;
}

int main(void) {
    char a[] = "hello";
    size_t n = reverse_in_place(a);
    printf("%zu %s\n", n, a);
    char empty[] = "";
    reverse_in_place(empty);
    reverse_in_place(NULL);
    return 0;
}
