    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1], &[1]), vec![1, 1, 1]);
    println!("{:?}", merge_sorted(&[0, 9], &[-3, 7]));
}
