#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), tail_(0), count_(0) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be positive");
        }
    }

    bool push(double value) {
        if (count_ == data_.size()) {
            return false;
        }
        data_[tail_] = value;
        tail_ = (tail_ + 1) % data_.size();
        ++count_;
        return true;
    }

    bool pop(double& out) {
        if (count_ == 0) {
            return false;
        }
        out = data_[head_];
        head_ = (head_ + 1) % data_.size();
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }

private:
    std::vector<double> data_;
    std::size_t head_, tail_, count_;
};

int main() {
    RingBuffer rb(2);
    std::cout << rb.push(1.0) << rb.push(2.0) << rb.push(3.0) << '\n';
    double v;
    while (rb.pop(v)) {
        std::cout << v << '\n';
    }
    return 0;
}
```

`push` returns false when full instead of overwriting; `pop` writes through an out-parameter so it can signal an empty buffer without throwing.

