def find_duplicates(items):
    """Return sorted unique values that appear more than once."""
    seen = set()
    dupes = set()
    for item in items:
        if item in seen:
            dupes.add(item)
        else:
            seen.add(item)
    try:
        return sorted(dupes)
    except TypeError:
        return sorted(dupes, key=str)


