#include <string>

enum class ParseStatus { Ok, Empty, Invalid, Overflow };

struct ParseResult {
    ParseStatus status = ParseStatus::Empty;
    long long value = 0;
};

ParseResult parse_int(const std::string& s) {
    ParseResult r;
    std::size_t i = 0;
    bool negative = false;
    if (i < s.size() && (s[i] == '+' || s[i] == '-')) {
        negative = (s[i] == '-');
        ++i;
    }
    if (i >= s.size()) {
        r.status = ParseStatus::Empty;
        return r;
    }
    unsigned long long acc = 0;
    const unsigned long long limit =
        negative ? static_cast<unsigned long long>(LLONG_MAX) + 1ULL
                 : static_cast<unsigned long long>(LLONG_MAX);
    for (; i < s.size(); ++i) {
        char c = s[i];
        if (c < '0' || c > '9') {
            r.status = ParseStatus::Invalid;
            return r;
        }
        unsigned digit = static_cast<unsigned>(c - '0');
        if (acc > (limit - digit) / 10ULL) {
            r.status = ParseStatus::Overflow;
            return r;
        }
        acc = acc * 10ULL + digit;
    }
    r.status = ParseStatus::Ok;
    r.value = negative ? -static_cast<long long>(acc) : static_cast<long long>(acc);
    return r;
}

int main() {
    for (const std::string s : {"42", "-9223372036854775808", "9223372036854775808", "", "12x"}) {
        ParseResult r = parse_int(s);
        std::cout << '"' << s << "\" -> " << static_cast<int>(r.status)
                  << " value=" << r.value << '\n';
    }
    return 0;
}
```
The check `acc > (limit - digit) / 10` rejects the value before the multiplication, so it never wraps.

