fn longest_common_prefix(words: &[String]) -> String {
    let first = match words.first() {
        Some(w) => w,
        None => return String::new(),
    };
    let mut len = first.len();
    for word in &words[1..] {
        let mut i = 0;
        let a = first.as_bytes();
        let b = word.as_bytes();
        while i < len && i < b.len() && a[i] == b[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            break;
        }
    }
    // Trim to a char boundary so we never slice mid-codepoint.
    let mut cut = len;
    while cut > 0 && !first.is_char_boundary(cut) {
        cut -= 1;
    }
    first[..cut].to_string()
}

fn main() {
    let words = vec!["flower".to_string(), "flow".to_string(), "flight".to_string()];
    println!("{}", longest_common_prefix(&words)); // fl
    println!("[{}]", longest_common_prefix(&[]));   // []
    let uni = vec!["café".to_string(), "cafeteria".to_string()];
    println!("{}", longest_common_prefix(&uni));    // café
}
```
Byte comparisons drive the loop, then the result is clamped back to a UTF-8 char boundary so accented text is safe.

```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        let mut data = Vec::with_capacity(capacity);
        data.resize_with(capacity, || None);
        RingBuffer { data, head: 0, len: 0 }
    }

    pub fn capacity(&self) -> usize {
        self.data.len()
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_full(&self) -> bool {
        self.len == self.data.len()
    }

    pub fn push(&mut self, value: T) -> Result<(), T> {
        if self.is_full() {
            return Err(value);
        }
        let idx = (self.head + self.len) % self.data.len();
        self.data[idx] = Some(value);
        self.len += 1;
        Ok(())
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        let slot = self.data[self.head].take();
        self.head = (self.head + 1) % self.data.len();
        self.len -= 1;
        slot
    }
}

fn main() {
    let mut rb = RingBuffer::new(2);
    assert!(rb.push(1).is_ok());
    assert!(rb.push(2).is_ok());
    assert_eq!(rb.push(3), Err(3));
    assert_eq!(rb.pop(), Some(1));
    assert!(rb.push(3).is_ok());
    assert_eq!(rb.pop(), Some(2));
    assert_eq!(rb.pop(), Some(3));
    assert_eq!(rb.pop(), None);
    println!("ok");
}
