fn dedup_in_place<T: PartialEq>(items: &mut Vec<T>) -> usize {
    if items.is_empty() {
        return 0;
    }
    let mut write = 1usize;
    for read in 1..items.len() {
        if items[read] != items[write - 1] {
            items.swap(write, read);
            write += 1;
        }
    }
    items.truncate(write);
    write
}

fn main() {
    let mut v: Vec<i32> = vec![];
    assert_eq!(dedup_in_place(&mut v), 0);

    let mut v = vec![1, 1, 2, 3, 3, 3, 4];
    assert_eq!(dedup_in_place(&mut v), 4);
    assert_eq!(v, vec![1, 2, 3, 4]);

    let mut s = vec!["a", "a", "a"];
    assert_eq!(dedup_in_place(&mut s), 1);
    assert_eq!(s, vec!["a"]);
