std::optional<int> parse_int(const std::string& s) {
    if (s.empty()) return std::nullopt;
    size_t i = 0;
    bool neg = false;
    if (s[i] == '+' || s[i] == '-') {
        neg = (s[i] == '-');
        i++;
    }
    if (i >= s.size()) return std::nullopt;

    long long acc = 0;
    for (; i < s.size(); i++) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        if (!std::isdigit(c)) return std::nullopt;
        acc = acc * 10 + (c - '0');
        if (acc > (long long)std::numeric_limits<int>::max() + 1) return std::nullopt;
    }
    if (neg) acc = -acc;
    if (acc < std::numeric_limits<int>::min() || acc > std::numeric_limits<int>::max())
        return std::nullopt;
    return static_cast<int>(acc);
}

int main() {
    std::cout << parse_int("42").value_or(-1) << "\n";       // 42
    std::cout << parse_int("-17").value_or(-1) << "\n";      // -17
    std::cout << parse_int("").value_or(-1) << "\n";         // -1
    std::cout << parse_int("12x").value_or(-1) << "\n";      // -1
    std::cout << parse_int("999999999999").value_or(-1) << "\n"; // -1
