use tokio::task::JoinSet;

async fn double(n: u64) -> u64 {
    n * 2
}

async fn run_all(seed: u64, count: usize) -> Vec<u64> {
    let mut set = JoinSet::new();
    for i in 0..count {
        set.spawn(double(seed + i as u64));
    }
    let mut out = Vec::with_capacity(count);
    while let Some(res) = set.join_next().await {
        out.push(res.expect("task panicked"));
    }
    out
}

#[tokio::main]
async fn main() {
    let mut got = run_all(10, 3).await;
    got.sort_unstable();
    assert_eq!(got, vec![20, 22, 24]);
    println!("ok");
}
