`JoinSet` owns each spawned future and drives them concurrently, letting results come back in completion order; `join_next` returns `Result` so a panic in a task is surfaced instead of silently lost. `count == 0` yields an empty vector because the `while let` loop never runs. Add `tokio = { version = "1", features = ["full"] }` to `Cargo.toml`.

```c
#include <stddef.h>
#include <stdint.h>

int is_valid_utf8(const unsigned char *s, size_t n) {
    size_t i = 0;
    while (i < n) {
        unsigned char c = s[i];
        if (c <= 0x7F) {            /* 1 byte */
            i += 1;
        } else if ((c & 0xE0) == 0xC0) {  /* 2 bytes */
            if (c < 0xC2 || i + 1 >= n) return 0;
            if ((s[i + 1] & 0xC0) != 0x80) return 0;
            i += 2;
        } else if ((c & 0xF0) == 0xE0) {  /* 3 bytes */
            if (i + 2 >= n) return 0;
            if ((s[i + 1] & 0xC0) != 0x80 || (s[i + 2] & 0xC0) != 0x80) return 0;
            if (c == 0xE0 && s[i + 1] < 0xA0) return 0;
            if (c == 0xED && s[i + 1] >= 0xA0) return 0;
            i += 3;
        } else if ((c & 0xF8) == 0xF0) {  /* 4 bytes */
            if (i + 3 >= n) return 0;
            if ((s[i + 1] & 0xC0) != 0x80 || (s[i + 2] & 0xC0) != 0x80)
                return 0;
            if ((s[i + 3] & 0xC0) != 0x80) return 0;
            if (c == 0xF0 && s[i + 1] < 0x90) return 0;
            if (c > 0xF4 || (c == 0xF4 && s[i + 1] > 0x8F)) return 0;
            i += 4;
        } else {
            return 0;
        }
    }
    return 1;
}
```

The guard clauses reject the traps a naive checker misses: overlong encodings (`C0`/`C1`, `E0 A0`-range, `F0 90`-range), UTF-16 surrogates (`ED A0`–`ED BF`), code points above U+10FFFF (`F4` beyond `8F`), and truncated sequences at the end of the buffer. A zero-length buffer returns `1`. No external dependency is used.

```python
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 0:
            raise ValueError("capacity must be >= 0")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if self.capacity == 0:
            return
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1); c.put("b", 2); c.get("a"); c.put("c", 3)
    assert c.get("b") is None and c.get("a") == 1 and c.get("c") == 3
    z = LRUCache(0)
    z.put("x", 1)
    assert z.get("x") is None
    print("ok")
```

`move_to_end` on every hit keeps the most-recently-used key at the tail; `popitem(last=False)` evicts the least-recently-used head. A zero-capacity cache stores nothing, so `get` always returns `None` without special-casing the read path. Both operations are O(1) amortized.

```cpp
#include <cstddef>
#include <optional>
#include <vector>

class IntSet {
    static constexpr int EMPTY = -1;
    static constexpr int TOMB  = -2;
    std::vector<int> slots_;
    std::size_t size_ = 0;
    std::size_t tombs_ = 0;

    std::size_t hash(int v) const { return static_cast<std::size_t>(v) % slots_.size(); }

    void rehash(std::size_t n) {
        std::vector<int> old = std::move(slots_);
        slots_.assign(n, EMPTY);
        size_ = 0; tombs_ = 0;
        for (int v : old) if (v >= 0) insert(v);
    }

public:
    IntSet() : slots_(8, EMPTY) {}

    bool insert(int v) {
        if (v < 0) throw std::invalid_argument("only non-negative ints");
        if ((size_ + tombs_ + 1) * 4 >= slots_.size() * 3) rehash(slots_.size() * 2);
        std::size_t i = hash(v);
        while (slots_[i] != EMPTY && slots_[i] != TOMB && slots_[i] != v) i = (i + 1) % slots_.size();
        if (slots_[i] == v) return false;
        bool was_tomb = slots_[i] == TOMB;
        slots_[i] = v;
        ++size_; if (was_tomb) --tombs_;
        return true;
    }

    bool contains(int v) const {
        if (v < 0) return false;
        std::size_t i = hash(v);
        for (std::size_t step = 0; step < slots_.size(); ++step) {
            int s = slots_[i];
            if (s == EMPTY) return false;
            if (s == v) return true;
            i = (i + 1) % slots_.size();
        }
        return false;
    }

    bool erase(int v) {
        std::size_t i = hash(v);
        for (std::size_t step = 0; step < slots_.size(); ++step) {
            if (slots_[i] == EMPTY) return false;
            if (slots_[i] == v) { slots_[i] = TOMB; --size_; ++tombs_; return true; }
            i = (i + 1) % slots_.size();
        }
        return false;
    }

    std::size_t size() const { return size_; }
};
```

Load factor is kept under 0.75, counting tombstones, and `rehash` rebuilds the table to purge tombstones, so probe chains stay short. `contains` gives up after a full lap of the table, which is safe because the table never becomes completely full. Negative keys are rejected so `-1`/`-2` stay reserved as sentinels.

