std::optional<uint64_t> factorial(int n) {
    if (n < 0) return std::nullopt;
    uint64_t result = 1;
    for (int i = 2; i <= n; ++i) {
        if (result > std::numeric_limits<uint64_t>::max() / static_cast<uint64_t>(i))
            return std::nullopt;  // would overflow
        result *= static_cast<uint64_t>(i);
    }
    return result;
}

