int is_palindrome(const char *s) {
    if (s == NULL) return -1;
    size_t i = 0;
    size_t j = strlen(s);
    while (i + 1 < j) {
        if (j == 0) break;
        if (!isalnum((unsigned char)s[i])) { ++i; continue; }
        if (!isalnum((unsigned char)s[j - 1])) { --j; continue; }
        if (tolower((unsigned char)s[i]) != tolower((unsigned char)s[j - 1]))
