enum parse_status { PARSE_OK, PARSE_EMPTY, PARSE_INVALID, PARSE_OVERFLOW };

enum parse_status parse_int(const char *s, long *out) {
    if (s == NULL || *s == '\0') return PARSE_EMPTY;
    errno = 0;
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (end == s) return PARSE_INVALID;
    while (*end != '\0') {
        if (!isspace((unsigned char)*end)) return PARSE_INVALID;
        ++end;
    }
    if (errno == ERANGE || v > LONG_MAX || v < LONG_MIN) return PARSE_OVERFLOW;
    *out = v;
    return PARSE_OK;
}

