import hashlib
import os
import time

def scan(root: str) -> dict[str, str]:
    state = {}
    for dirpath, _dirs, files in os.walk(root):
        for name in files:
            path = os.path.join(dirpath, name)
            try:
                with open(path, "rb") as fh:
                    state[path] = hashlib.sha256(fh.read()).hexdigest()
            except OSError:
                state[path] = "<unreadable>"
    return state

def summarize(root: str, interval: float = 1.0, iterations: int | None = None):
    previous = scan(root)
    runs = 0
    while iterations is None or runs < iterations:
        time.sleep(interval)
        current = scan(root)
        added = sorted(current.keys() - previous.keys())
        removed = sorted(previous.keys() - current.keys())
        changed = sorted(
            p for p in current.keys() & previous.keys()
            if current[p] != previous[p]
        )
        if added or removed or changed:
            print(f"added={len(added)} removed={len(removed)} changed={len(changed)}")
            for p in added:
                print("  +", p)
            for p in removed:
                print("  -", p)
            for p in changed:
                print("  ~", p)
        previous = current
        runs += 1

if __name__ == "__main__":
    summarize(".", interval=0.2, iterations=1)
