        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

    const T& at(std::size_t index) const {
        if (index >= size_) throw std::out_of_range("ring buffer index");
        std::size_t start = (head_ + N - size_) % N;
        return data_[(start + index) % N];
    }

    class iterator {
    public:
        iterator(const RingBuffer* buf, std::size_t pos) : buf_(buf), pos_(pos) {}
        const T& operator*() const { return buf_->at(pos_); }
        iterator& operator++() { ++pos_; return *this; }
        bool operator!=(const iterator& o) const { return pos_ != o.pos_; }
    private:
        const RingBuffer* buf_;
        std::size_t pos_;
    };

    iterator begin() const { return iterator(this, 0); }
    iterator end() const { return iterator(this, size_); }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1);
    rb.push(2);
    rb.push(3);
    rb.push(4);          // overwrites 1
    for (int v : rb) std::cout << v << ' ';   // 2 3 4
    std::cout << '\n' << rb.size() << '\n'; // 3
}
```

Iteration walks oldest-to-newest even after wraparound, `N` must be non-zero, and `at` throws on an out-of-range index.

```rust
#[derive(Debug, PartialEq, Clone)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Object(Vec<(String, Json)>),
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { bytes: s.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn parse_value(&mut self) -> Result<Json, String> {
        self.skip_ws();
        match self.bytes.get(self.pos) {
            Some(b'{') => self.parse_object(),
            Some(b'"') => Ok(Json::Str(self.parse_string()?)),
            Some(b't') => { self.expect("true")?; Ok(Json::Bool(true)) }
            Some(b'f') => { self.expect("false")?; Ok(Json::Bool(false)) }
            Some(b'n') => { self.expect("null")?; Ok(Json::Null) }
            Some(_) => self.parse_number(),
            None => Err("unexpected end of input".into()),
        }
    }

    fn expect(&mut self, word: &str) -> Result<(), String> {
        if self.bytes[self.pos..].starts_with(word.as_bytes()) {
            self.pos += word.len();
            Ok(())
        } else {
            Err(format!("expected {}", word))
        }
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.pos += 1; // opening quote
        let mut out = String::new();
        while let Some(&b) = self.bytes.get(self.pos) {
            self.pos += 1;
            match b {
                b'"' => return Ok(out),
                b'\\' => {
                    let esc = *self.bytes.get(self.pos).ok_or("bad escape")?;
                    self.pos += 1;
                    out.push(match esc {
                        b'n' => '\n',
                        b't' => '\t',
                        b'"' => '"',
                        b'\\' => '\\',
                        _ => return Err("unsupported escape".into()),
                    });
                }
                _ => out.push(b as char),
            }
        }
        Err("unterminated string".into())
    }

    fn parse_number(&mut self) -> Result<Json, String> {
        let start = self.pos;
        while let Some(&b) = self.bytes.get(self.pos) {
            if b.is_ascii_digit() || matches!(b, b'-' | b'+' | b'.' | b'e' | b'E') {
                self.pos += 1;
            } else {
                break;
            }
        }
        let slice = std::str::from_utf8(&self.bytes[start..self.pos]).map_err(|_| "bad number")?;
        slice.parse::<f64>().map(Json::Number).map_err(|_| format!("invalid number: {}", slice))
    }

    fn parse_object(&mut self) -> Result<Json, String> {
        self.pos += 1; // '{'
        let mut entries = Vec::new();
        self.skip_ws();
        if self.bytes.get(self.pos) == Some(&b'}') {
            self.pos += 1;
            return Ok(Json::Object(entries));
        }
        loop {
            self.skip_ws();
            if self.bytes.get(self.pos) != Some(&b'"') {
                return Err("expected key string".into());
            }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.bytes.get(self.pos) != Some(&b':') {
                return Err("expected ':'".into());
            }
            self.pos += 1;
            let value = self.parse_value()?;
            entries.push((key, value));
            self.skip_ws();
            match self.bytes.get(self.pos) {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; return Ok(Json::Object(entries)); }
                _ => return Err("expected ',' or '}'".into()),
            }
        }
    }
}

fn main() {
    let input = r#"{"name": "ada", "age": 36, "ok": true, "tags": null}"#;
    let mut parser = Parser::new(input);
    match parser.parse_value() {
        Ok(json) => println!("{:?}", json),
        Err(e) => eprintln!("parse error: {}", e),
    }
}
```

It parses a top-level object with string, number, boolean and null values, rejects malformed input with a message, and keeps duplicate keys in order. It handles the ASCII subset; full Unicode escapes would need additional work.

