```c
#include <stddef.h>
#include <stdio.h>

/* Returns byte length of the UTF-8 code point starting at p (1..4), or 1 on bad lead. */
static size_t utf8_len(unsigned char c) {
    if (c < 0x80) return 1;
    if ((c & 0xE0) == 0xC0) return 2;
    if ((c & 0xF0) == 0xE0) return 3;
    if ((c & 0xF8) == 0xF0) return 4;
    return 1;
}

void reverse_utf8(char *s) {
    size_t i = 0, j = 0;
    while (s[j]) j++;              /* byte length */
    if (j == 0) return;
    j--;                            /* last valid byte index */
    while (i < j) {
        size_t left = utf8_len((unsigned char)s[i]);
        /* walk j back to the start of its code point */
        size_t back = 1;
        while (back < 4 && j >= back &&
               ((unsigned char)s[j - back] & 0xC0) == 0x80) back++;
        size_t right = back;
        char tmp[4];
        for (size_t k = 0; k < right; k++) tmp[k] = s[j - right + 1 + k];
        for (size_t k = 0; k < right; k++) s[j - right + 1 + k] = s[i + k];
        for (size_t k = 0; k < left; k++) s[i + k] = tmp[k];
        if (left != right) break; /* never happens for well-formed UTF-8 */
        i += left;
        if (j < right) break;
        j -= right;
    }
}

int main(void) {
    char s[] = "a\xC3\xA9\xF0\x9F\x98\x80b"; /* a é 😀 b */
    reverse_utf8(s);
    printf("%s\n", s); /* b 😀 é a */
    return 0;
}
```

Swaps whole code points, not bytes, so multibyte sequences stay intact. `utf8_len` computes the lead byte's expected span; the backward walk from `j` locates the start of the right-hand code point.

