#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

std::string longest_common_prefix(const std::vector<std::string>& words) {
    if (words.empty()) return "";
    std::string prefix = words[0];
    for (const auto& w : words) {
        size_t i = 0;
        while (i < prefix.size() && i < w.size() && prefix[i] == w[i]) ++i;
        prefix.resize(i);
        if (prefix.empty()) break;
    }
    return prefix;
}

int main() {
    std::vector<std::string> a{"flower", "flow", "flight"};
    std::vector<std::string> b{"dog", "cat"};
    std::vector<std::string> c{};
    std::cout << longest_common_prefix(a) << "\n"; // fl
    std::cout << longest_common_prefix(b) << "\n"; // empty
    std::cout << longest_common_prefix(c) << "\n"; // empty
    return 0;
}
