fn longest_common_prefix(words: &[String]) -> String {
    if words.is_empty() {
        return String::new();
    }

    let first = words[0].as_bytes();
    let mut len = first.len();

    for w in &words[1..] {
        let b = w.as_bytes();
        let mut i = 0;
        while i < len && i < b.len() && first[i] == b[i] {
            i += 1;
        }
        len = i;
        if len == 0 {
            break;
        }
    }

    String::from_utf8(first[..len].to_vec()).unwrap()
}

