        struct Node *n = malloc(sizeof *n);
        if (n == NULL) { perror("malloc"); return 1; }
        n->value = (int)v;
        n->next = head;
        head = n;
    }

    head = reverse(head);

    for (struct Node *p = head; p != NULL; p = p->next) {
        printf("%d\n", p->value);
    }

    while (head != NULL) {
        struct Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
```
Each node is prepended while parsing, then the whole list is reversed with the standard three-pointer swap; the final loop frees every node to avoid leaking.

