std::uint64_t trailing_zeros(std::uint64_t n) {
    std::uint64_t zeros = 0;
    for (std::uint64_t p = 5; p <= n; p *= 5) {
        zeros += n / p;
        if (p > n / 5) break; // avoid overflow of p
    }
    return zeros;
