#include <array>
#include <cstddef>
#include <iostream>

// Fixed ring buffer. Full/empty are disambiguated by sacrificing one slot.
template <typename T, std::size_t N>
class RingBuffer {
    static_assert(N >= 2, "N must leave room for one empty slot");
public:
    bool empty() const { return head_ == tail_; }
    bool full() const { return (tail_ + 1) % N == head_; }
    std::size_t size() const { return (tail_ - head_ + N) % N; }

    bool push(const T& v) {
        if (full()) return false;
        buf_[tail_] = v;
        tail_ = (tail_ + 1) % N;
        return true;
    }

    bool pop(T& out) {
        if (empty()) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % N;
        return true;
    }

private:
    std::array<T, N> buf_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
};

int main() {
    RingBuffer<int, 4> rb;  // holds 3 elements
    std::cout << "cap " << (4 - 1) << "\n";
    for (int i = 1; i <= 3; ++i)
        std::cout << "push " << i << ": " << rb.push(i) << "\n";
    std::cout << "full " << rb.full() << " size " << rb.size() << "\n";
    std::cout << "push 4: " << rb.push(4) << "\n";  // rejected
    int v;
    while (rb.pop(v)) std::cout << "pop " << v << "\n";
    std::cout << "empty " << rb.empty() << "\n";
}
```

Output: pushes 1..3 succeed, push 4 fails, then pops 1,2,3 and reports empty. Sacrificing one slot removes the head==tail ambiguity between full and empty without a separate counter.

