use std::time::{Duration, Instant};

trait Clock {
    fn now(&self) -> Instant;
}

struct RealClock;
impl Clock for RealClock {
    fn now(&self) -> Instant { Instant::now() }
}

/// Token bucket: `capacity` tokens refill at `rate_per_sec`.
pub struct TokenBucket<C: Clock> {
    clock: C,
    capacity: f64,
    tokens: f64,
    rate: f64,          // tokens per second
    last: Instant,
}

impl<C: Clock> TokenBucket<C> {
    pub fn new(clock: C, capacity: f64, rate: f64, start: Instant) -> Self {
        assert!(capacity > 0.0 && rate > 0.0);
        TokenBucket { clock, capacity, tokens: capacity, rate, last: start }
    }

    fn refill(&mut self) {
        let now = self.clock.now();
        let elapsed = now.saturating_duration_since(self.last).as_secs_f64();
        self.tokens = (self.tokens + elapsed * self.rate).min(self.capacity);
        self.last = now;
    }

    /// Consume one token if available.
    pub fn try_acquire(&mut self) -> bool {
        self.refill();
        if self.tokens >= 1.0 {
            self.tokens -= 1.0;
            true
        } else {
            false
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::Cell;

    struct MockClock(Cell<Instant>);
    impl Clock for MockClock {
        fn now(&self) -> Instant { self.0.get() }
    }
    impl MockClock {
        fn advance(&self, d: Duration) { self.0.set(self.0.get() + d); }
    }

    #[test]
    fn drains_then_refills() {
        let t0 = Instant::now();
        let clock = MockClock(Cell::new(t0));
        let mut b = TokenBucket::new(&clock, 2.0, 1.0, t0); // 1 token/sec
        assert!(b.try_acquire());
        assert!(b.try_acquire());
        assert!(!b.try_acquire()); // empty
        clock.advance(Duration::from_secs(2));
        assert!(b.try_acquire());
        assert!(b.try_acquire());
        assert!(!b.try_acquire());
    }
}
```

The `Clock` trait lets tests advance time deterministically instead of sleeping. `Instant::saturating_duration_since` guards against a clock moving backwards. Capacity caps the bucket so tokens cannot accumulate forever.

```python
from typing import Iterator


def encode(s: str) -> str:
    """Run-length encode s. Each run becomes <count><char>."""
    out = []
    for ch, run in _runs(s):
        out.append(f"{run}{ch}")
    return "".join(out)


def _runs(s: str) -> Iterator[tuple]:
    if not s:
        return
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            yield prev, count
            prev, count = ch, 1
    yield prev, count


def decode(s: str) -> str:
    """Decode RLE produced by encode. Raises ValueError on bad input."""
    out = []
    i, n = 0, len(s)
    while i < n:
        if not s[i].isdigit():
            raise ValueError(f"expected digit at index {i}: {s[i]!r}")
        j = i
        while j < n and s[j].isdigit():
            j += 1
        if j >= n:
            raise ValueError("trailing count without character")
        count = int(s[i:j])
        if count == 0:
            raise ValueError("count must be positive")
        out.append(s[j] * count)
        i = j + 1
    return "".join(out)


if __name__ == "__main__":
    for s in ["", "a", "aaabbbcccd", "wwwwwwwwwwww"]:
        e = encode(s)
        assert decode(e) == s, (s, e)
        print(repr(s), "->", repr(e))
    for bad in ["3", "x2", "0a"]:
        try:
            decode(bad)
            raise AssertionError(f"expected failure for {bad!r}")
        except ValueError as ex:
            print("rejected", repr(bad), ex)
```

Encode groups consecutive equal characters and emits count then char; `wwwwwwwwwwww` becomes `12w`, exercising multi-digit counts on decode. Decode walks digit runs, rejects a missing character, a non-digit start, and a zero count. Round-trips are asserted for every sample.

```python
import re

_TOKEN = re.compile(r"\s*(?:(\d+(?:\.\d+)?)|([()+\-*/]))")


class ParseError(ValueError):
    pass


def tokenize(s: str):
    pos = 0
    tokens = []
    while pos < len(s):
        m = _TOKEN.match(s, pos)
        if not m:
            raise ParseError(f"bad token at {pos}: {s[pos]!r}")
        tokens.append(m.group(1) or m.group(2))
        pos = m.end()
    return tokens


class Parser:
    def __init__(self, tokens):
        self.toks = tokens
        self.i = 0

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None

    def eat(self, expected=None):
        t = self.peek()
        if t is None:
            raise ParseError("unexpected end of input")
        if expected is not None and t != expected:
            raise ParseError(f"expected {expected!r}, got {t!r}")
        self.i += 1
        return t

    def expr(self):        # expr := term (('+'|'-') term)*
        value = self.term()
        while self.peek() in ("+", "-"):
            op = self.eat()
            rhs = self.term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def term(self):        # term := factor (('*'|'/') factor)*
        value = self.factor()
        while self.peek() in ("*", "/"):
            op = self.eat()
            rhs = self.factor()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ParseError("division by zero")
                value /= rhs
        return value

    def factor(self):      # factor := number | '(' expr ')' | '-' factor
        t = self.peek()
        if t == "(":
            self.eat("(")
            value = self.expr()
            self.eat(")")
            return value
        if t == "-":
            self.eat("-")
            return -self.factor()
        if t is not None and re.fullmatch(r"\d+(?:\.\d+)?", t):
            self.eat()
            return float(t)
        raise ParseError(f"unexpected token {t!r}")


def evaluate(s: str) -> float:
    p = Parser(tokenize(s))
    value = p.expr()
    if p.peek() is not None:
        raise ParseError(f"trailing input: {p.peek()!r}")
    return value


if __name__ == "__main__":
    tests = {"1+2*3": 7.0, "(1+2)*3": 9.0, "10/4": 2.5, "-(2+3)": -5.0,
             "2*(3+4)-5": 9.0}
    for expr, want in tests.items():
        got = evaluate(expr)
        assert got == want, (expr, got, want)
        print(expr, "=", got)
    for bad in ["1+", "(1+2", "1/0", "2 2"]:
        try:
            evaluate(bad)
            print("ERROR: accepted", bad)
        except ParseError as e:
            print("rejected", repr(bad), "->", e)
```

The grammar is `expr -> term (('+'|'-') term)*`, `term -> factor (('*'|'/') factor)*`, `factor -> number | '(' expr ')' | '-' factor`. Precedence falls out of the call depth. Division by zero, unbalanced parens, trailing tokens, and malformed numbers all raise `ParseError`.

