    int c;
    unsigned long total = 0;
    while ((c = fgetc(fp)) != EOF) {
        freq[(unsigned char)c]++;
        total++;
    }

    if (ferror(fp)) {
        perror("fgetc");
        fclose(fp);
        return 1;
    }
    fclose(fp);

    if (total == 0) {
        printf("file is empty\n");
        return 0;
    }

    for (int rank = 0; rank < 5; rank++) {
        int best = -1;
        for (int i = 0; i < 256; i++) {
            if (freq[i] > 0 && (best < 0 || freq[i] > freq[best]))
                best = i;
        }
        if (best < 0)
            break;
        unsigned char b = (unsigned char)best;
        printf("%lu/%.4f%% byte 0x%02X", freq[best],
               100.0 * (double)freq[best] / (double)total, b);
        if (b >= 32 && b < 127)
            printf(" '%c'", b);
        printf("\n");
        freq[best] = 0; // remove so next rank picks the next-best
    }
    return 0;
