std::string dedup(const std::string& s) {
    std::array<bool, 256> seen{};
    std::string out;
    out.reserve(s.size());
    for (unsigned char c : s) {
        if (!seen[c]) {
            seen[c] = true;
            out.push_back(static_cast<char>(c));
        }
    }
    return out;
