```cpp
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), capacity_(capacity) {}

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == capacity_; }
    std::size_t size() const { return size_; }

    void push(const T& value) {
        if (full()) throw std::overflow_error("ring buffer full");
        buf_[(head_ + size_) % capacity_] = value;
        ++size_;
    }

    T pop() {
        if (empty()) throw std::underflow_error("ring buffer empty");
        T value = buf_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

private:
    std::vector<T> buf_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int> rb(3);
    rb.push(1); rb.push(2); rb.push(3);
    if (rb.size() != 3 || !rb.full()) return 1;
    if (rb.pop() != 1 || rb.pop() != 2) return 1;
    rb.push(4);
    if (rb.pop() != 3 || rb.pop() != 4 || !rb.empty()) return 1;
    try { rb.pop(); return 1; } catch (const std::underflow_error&) {}
    std::cout << "ok\n";
}
```

`std::vector<T>` value-initialises the slots, so the "uninitialized" case is avoided for non-trivial `T`; the wrap arithmetic uses `size_` so a full buffer never overwrites unread data.

