import functools


def memoize(func):
    cache = {}

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if key in cache:
            wrapper.hits += 1
            return cache[key]
        wrapper.misses += 1
        cache[key] = result = func(*args, **kwargs)
        return result

    wrapper.hits = 0
    wrapper.misses = 0
    wrapper.cache = cache

    def cache_info():
        total = wrapper.hits + wrapper.misses
        rate = wrapper.hits / total if total else 0.0
        return {'hits': wrapper.hits, 'misses': wrapper.misses, 'hit_rate': rate}

    wrapper.cache_info = cache_info
    return wrapper


@memoize
def slow_add(a: int, b: int) -> int:
    return a + b


if __name__ == '__main__':
    assert slow_add(1, 2) == 3
    assert slow_add(1, 2) == 3   # hit
    assert slow_add(2, 1) == 3   # miss: different key order
    print(slow_add.cache_info())  # {'hits': 1, 'misses': 2, 'hit_rate': 0.333...}
```
