def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, end = 0, 0

    def expand(lo: int, hi: int):
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i + 1)
        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2
    return s[start:end + 1]


if __name__ == "__main__":
    cases = ["", "a", "abba", "babad", "cbbd", "forgeeksskeegfor"]
    for c in cases:
        print(repr(c), "->", repr(longest_palindrome(c)))
```
The expand-around-center approach is O(n^2) time and O(1) extra space, which is fine for typical inputs and avoids the memory overhead of a DP table.

