template <typename T>
T max_element(const std::vector<T> &values) {
    if (values.empty()) {
        throw std::invalid_argument("max_element: empty vector");
    }
    T best = values.front();
    for (std::size_t i = 1; i < values.size(); ++i) {
        if (values[i] > best) {
            best = values[i];
        }
    }
    return best;
