```python
from collections import deque
from typing import Iterator, Iterable

class RingBuffer:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._data: deque = deque(maxlen=capacity)

    def push(self, item) -> None:
        self._data.append(item)

    def pop(self):
        if not self._data:
            raise IndexError("pop from empty buffer")
        return self._data.popleft()

    def __iter__(self) -> Iterator:
        return iter(self._data)

    def __len__(self) -> int:
        return len(self._data)

if __name__ == "__main__":
    rb = RingBuffer(3)
    for x in range(5):
        rb.push(x)
    assert list(rb) == [2, 3, 4]
    assert rb.pop() == 2
    assert len(rb) == 2
```
`deque(maxlen=capacity)` drops the oldest element automatically once full, so `push` never needs explicit eviction. Iteration yields items in insertion order, and `pop` removes from the front.

