#include <iostream>
#include <stack>
#include <string>

bool isBalanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{': st.push(c); break;
            case ')':
                if (st.empty() || st.top() != '(') return false;
                st.pop(); break;
            case ']':
                if (st.empty() || st.top() != '[') return false;
                st.pop(); break;
            case '}':
                if (st.empty() || st.top() != '{') return false;
                st.pop(); break;
            default: break;
        }
    }
    return st.empty();
}

int main() {
    std::cout << std::boolalpha;
    std::cout << isBalanced("{[()]}") << '\n';
    std::cout << isBalanced("([)]") << '\n';
    std::cout << isBalanced("") << '\n';
    std::cout << isBalanced("(((") << '\n';
}
```
Openers are pushed; closers must match `st.top()` and pop it. A closer with an empty stack or a mismatched top returns `false`. The final `st.empty()` rejects strings with unclosed openers, and the empty string is balanced.

