#include <assert.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

#define CAP 4

typedef struct {
    int buf[CAP];
    size_t head;
    size_t tail;
    size_t count;
} Ring;

void ring_init(Ring* r) {
    r->head = r->tail = r->count = 0;
}

bool ring_push(Ring* r, int value) {
    if (r->count == CAP) return false;
    r->buf[r->tail] = value;
    r->tail = (r->tail + 1) % CAP;
    r->count++;
    return true;
}

bool ring_pop(Ring* r, int* out) {
    if (r->count == 0) return false;
    *out = r->buf[r->head];
    r->head = (r->head + 1) % CAP;
    r->count--;
    return true;
}

int main(void) {
    Ring r;
    ring_init(&r);
    for (int i = 0; i < CAP; ++i) assert(ring_push(&r, i));
    assert(!ring_push(&r, 99));      /* full */

    int v;
    for (int i = 0; i < CAP; ++i) {
        assert(ring_pop(&r, &v));
        assert(v == i);
    }
    assert(!ring_pop(&r, &v));       /* empty */
    printf("ok\n");
    return 0;
}
