#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t cap) : buf_(cap), head_(0), tail_(0), size_(0) {}

    bool push(int value) {
        if (size_ == buf_.size()) return false;
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % buf_.size();
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::vector<int> buf_;
    std::size_t head_, tail_, size_;
};

int main() {
    RingBuffer rb(3);
    if (rb.pop()) return 1;          // empty pop
    rb.push(1); rb.push(2); rb.push(3);
    if (rb.push(4)) return 2;        // full push rejected
    if (*rb.pop() != 1) return 3;
    rb.push(4);
    if (*rb.pop() != 2 || *rb.pop() != 3 || *rb.pop() != 4) return 4;
    if (!rb.empty()) return 5;
    std::cout << "ok\n";
}
