from typing import List, Optional


"""Binary search on a sorted list of ints; returns index or -1."""


def binary_search(items: List[int], target: int) -> int:
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def linear_search(items: List[int], target: int) -> int:
    for i, value in enumerate(items):
        if value == target:
            return i
    return -1


