static void reverse(char *s) {
    if (!s) return;
    char *left = s;
    char *right = s + strlen(s) - 1;
    while (left < right) {
        char tmp = *left;
        *left++ = *right;
        *right-- = tmp;
    }
}

int main(void) {
    char buf[256];
    printf("enter a string: ");
    if (!fgets(buf, sizeof buf, stdin)) {
        fprintf(stderr, "no input\n");
        return 1;
    }
    buf[strcspn(buf, "\n")] = '\0';
    reverse(buf);
    printf("%s\n", buf);
    return 0;
}
