class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : cap_(capacity), size_(0), head_(0) {}

    void push(int value) {
        data_[head_] = value;
        head_ = (head_ + 1) % cap_;
        if (size_ < cap_) ++size_;
    }

    int sum() const {
        int total = 0;
        for (std::size_t i = 0; i < size_; ++i) total += data_[i];
        return total;
    }

private:
    static const std::size_t MAX_CAP = 64;
    std::array<int, MAX_CAP> data_{};
    std::size_t cap_;
    std::size_t size_;
    std::size_t head_;
};

int main() {
