#include <iostream>
#include <queue>
#include <vector>

class RunningMedian {
public:
    void add(int value) {
        if (low_.empty() || value <= low_.top()) {
            low_.push(value);
        } else {
            high_.push(value);
        }
        // Keep sizes balanced: low may exceed high by at most 1.
        if (low_.size() > high_.size() + 1) {
            high_.push(low_.top());
            low_.pop();
        } else if (high_.size() > low_.size()) {
            low_.push(high_.top());
            high_.pop();
        }
    }

    double median() const {
        if (low_.size() == high_.size()) {
            return (static_cast<double>(low_.top()) + high_.top()) / 2.0;
        }
        return static_cast<double>(low_.top());
    }

private:
    std::priority_queue<int> low_;                                  // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high_;  // min-heap
};

int main() {
    RunningMedian rm;
    int value = 0;
    while (std::cin >> value) {
        rm.add(value);
    }
    if (std::cin.bad()) {
        std::cerr << "input error\n";
        return 1;
    }
    if (!std::cin.eof()) {
        std::cerr << "non-integer input\n";
        return 1;
    }
    if (rm.median() == 0.0 && std::cin.peek() == EOF) {
        return 0;  // nothing read
    }
    std::cout << rm.median() << '\n';
    return 0;
}
