void dedupe(char *s) {
    if (s == NULL) return;
    int seen[256] = {0};
    size_t write = 0;
    for (size_t read = 0; s[read] != '\0'; read++) {
        unsigned char c = (unsigned char)s[read];
        if (!seen[c]) {
            seen[c] = 1;
            s[write++] = s[read];
        }
    }
    s[write] = '\0';
}

