static std::string trim(const std::string& s) {
    size_t start = 0, end = s.size();
    while (start < end && std::isspace(static_cast<unsigned char>(s[start]))) ++start;
    while (end > start && std::isspace(static_cast<unsigned char>(s[end - 1]))) --end;
    return s.substr(start, end - start);
}

std::optional<std::map<std::string, std::string>> parse(const std::string& input) {
    std::map<std::string, std::string> out;
    if (trim(input).empty()) return out;
    std::stringstream ss(input);
    std::string pair;
    while (std::getline(ss, pair, ';')) {
        auto eq = pair.find('=');
        if (eq == std::string::npos) return std::nullopt;
        std::string key = trim(pair.substr(0, eq));
        std::string value = trim(pair.substr(eq + 1));
        if (key.empty()) return std::nullopt;
        out[key] = value;
    }
    return out;
}

int main() {
    auto a = parse("a=1; b = two ;c=3");
    if (!a || a->size() != 3 || (*a)["b"] != "two" || (*a)["c"] != "3") return 1;
    auto empty = parse("   ");
    if (!empty || !empty->empty()) return 1;
    if (parse("noequals").has_value()) return 1;
    if (parse("=v").has_value()) return 1;
    std::cout << "ok\n";
    return 0;
}
