    """Return the n most common lowercase words in the file at path."""
    counter: Counter[str] = Counter()
    with open(path, "r", encoding="utf-8") as fh:
        for line in fh:
            counter.update(line.lower().split())
    return counter.most_common(n)


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("usage: wordcount.py FILE [N]", file=sys.stderr)
        sys.exit(1)
    n = int(sys.argv[2]) if len(sys.argv) > 2 else 10
    for word, count in top_words(sys.argv[1], n):
        print(f"{count:6d}  {word}")
```

`Counter` handles the accumulation; empty files simply print nothing.

