struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

int main() {
    std::vector<int> values = {1, 2, 3, 4, 5};
    Node* head = nullptr;
    for (auto it = values.rbegin(); it != values.rend(); ++it) {
        head = new Node(*it);
        head->next = nullptr; // placeholder, fixed below
    }
    // Rebuild cleanly to avoid the placeholder hack:
    head = nullptr;
    for (auto it = values.rbegin(); it != values.rend(); ++it) {
        Node* n = new Node(*it);
        n->next = head;
        head = n;
    }

    head = reverse(head);
    for (Node* cur = head; cur != nullptr; cur = cur->next) {
        std::cout << cur->value << (cur->next ? " -> " : "\n");
    }

    while (head != nullptr) {
        Node* nxt = head->next;
        delete head;
        head = nxt;
    }
    return 0;
}
