bool balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                return false;
            }
        }
    }
    return st.empty();
}

int main() {
    std::string cases[] = {"", "()", "([{}])", "(]", "((("};
    for (const std::string& s : cases) {
        std::cout << (balanced(s) ? "yes" : "no") << "  " << s << "\n";
    }
    return 0;
}
