char *reverse_in_place(char *s) {
    if (s == NULL || *s == '\0') {
        return s;
    }
    char *left = s;
    char *right = s;
    while (*right != '\0') {
        right++;
    }
    right--;
    while (left < right) {
        char tmp = *left;
        *left = *right;
        *right = tmp;
        left++;
        right--;
    }
    return s;
