use std::io::{self, BufRead};

pub fn is_palindrome(s: &str) -> bool {
    let chars: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();
    let mut i = 0;
    let mut j = chars.len();
    while i < j {
        if i + 1 >= j {
            break;
        }
        j -= 1;
        if chars[i] != chars[j] {
            return false;
        }
        i += 1;
    }
    true
}

fn main() {
    let stdin = io::stdin();
    let line = stdin.lock().lines().next();
    match line {
        Some(Ok(text)) => println!("{}", is_palindrome(&text)),
        _ => println!("false"),
    }
}
```

