#include <iostream>
#include <sstream>
#include <string>
#include <vector>
#include <stdexcept>

int main() {
    std::string line;
    if (!std::getline(std::cin, line)) {
        std::cerr << "no input\n";
        return 1;
    }
    std::vector<double> nums;
    std::stringstream ss(line);
    std::string token;
    while (std::getline(ss, token, ',')) {
        if (token.empty()) {
            continue;
        }
        try {
            size_t used = 0;
            double value = std::stod(token, &used);
            if (used != token.size()) {
                throw std::invalid_argument("trailing garbage");
            }
            nums.push_back(value);
        } catch (const std::exception &) {
            std::cerr << "skipping malformed token: " << token << "\n";
        }
    }
    if (nums.empty()) {
        std::cout << "sum=0 average=n/a\n";
        return 0;
    }
    double sum = 0.0;
    for (double v : nums) {
        sum += v;
    }
    std::cout << "sum=" << sum << " average=" << sum / nums.size() << "\n";
    return 0;
}
