#include <iostream>
#include <string>
#include <limits>
#include <optional>

std::optional<int> parse_int(const std::string& s) {
    if (s.empty()) return std::nullopt;
    long long acc = 0;
    bool neg = false;
    size_t i = 0;
    if (s[0] == '+' || s[0] == '-') {
        neg = (s[0] == '-');
        i = 1;
    }
    if (i == s.size()) return std::nullopt;
    for (; i < s.size(); ++i) {
        if (s[i] < '0' || s[i] > '9') return std::nullopt;
        acc = acc * 10 + (s[i] - '0');
        if (acc > std::numeric_limits<int>::max()) return std::nullopt;
    }
    return neg ? -acc : acc;
}

int main() {
    for (const auto& t : {"42", "-7", "+13", "", "12x", "9999999999"}) {
        auto r = parse_int(t);
        std::cout << t << " -> " << (r ? std::to_string(*r) : "invalid") << '\n';
    }
    return 0;
}
