```python
from typing import Iterator, Optional


class RingBuffer:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._buf = [None] * capacity
        self._start = 0
        self._size = 0

    def push(self, item):
        idx = (self._start + self._size) % len(self._buf)
        self._buf[idx] = item
        if self._size == len(self._buf):
            self._start = (self._start + 1) % len(self._buf)
        else:
            self._size += 1

    def pop(self) -> Optional[object]:
        if self._size == 0:
            return None
        item = self._buf[self._start]
        self._buf[self._start] = None
        self._start = (self._start + 1) % len(self._buf)
        self._size -= 1
        return item

    def __iter__(self) -> Iterator:
        for i in range(self._size):
            yield self._buf[(self._start + i) % len(self._buf)]

    def __len__(self) -> int:
        return self._size


if __name__ == "__main__":
    rb = RingBuffer(3)
    for x in [1, 2, 3, 4]:
        rb.push(x)
    assert list(rb) == [2, 3, 4]
    assert rb.pop() == 2
    assert len(rb) == 2
    print("ok")
```

When full, `push` overwrites the oldest element and advances `_start`, so the buffer always keeps the most recent `capacity` items in insertion order.

