```c
#include <ctype.h>
#include <stdio.h>
#include <string.h>

static void reverse(char* s, size_t i, size_t j) {
    while (i < j) {
        char t = s[i]; s[i] = s[j]; s[j] = t;
        ++i; --j;
    }
}

static size_t compact(char* s) {
    size_t w = 0;
    for (size_t r = 0; s[r]; ++r) {
        if (!isspace((unsigned char)s[r])) {
            s[w++] = s[r];
        } else if (w > 0 && s[w - 1] != ' ') {
            s[w++] = ' ';
        }
    }
    while (w > 0 && s[w - 1] == ' ') --w;
    s[w] = '\0';
    return w;
}

int main(void) {
    char buf[256];
    while (fgets(buf, sizeof buf, stdin)) {
        buf[strcspn(buf, "\n")] = '\0';
        size_t len = compact(buf);
        reverse(buf, 0, len ? len - 1 : 0);
        size_t start = 0;
        for (size_t i = 0; i <= len; ++i) {
            if (i == len || buf[i] == ' ') {
                if (i > start) reverse(buf, start, i - 1);
                start = i + 1;
            }
        }
        puts(buf);
    }
    return 0;
}
```

Spaces are collapsed first, then the whole buffer is reversed and each word reversed back. The `unsigned char` cast avoids undefined behaviour from `isspace` on negative values, and the empty-string case is guarded before reversing.

