class FileHandle {
public:
    explicit FileHandle(const char* path, const char* mode) : fp_(std::fopen(path, mode)) {}

    ~FileHandle() {
        if (fp_) std::fclose(fp_);
    }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    FileHandle(FileHandle&& other) noexcept : fp_(other.fp_) {
        other.fp_ = nullptr;
    }

    FileHandle& operator=(FileHandle&& other) noexcept {
        if (this != &other) {
            if (fp_) std::fclose(fp_);
            fp_ = other.fp_;
            other.fp_ = nullptr;
        }
        return *this;
    }

    bool valid() const { return fp_ != nullptr; }
    std::FILE* get() const { return fp_; }

private:
    std::FILE* fp_;
};

int main() {
    FileHandle f("data.txt", "r");
    if (!f.valid()) return 1;
    FileHandle g = std::move(f);   // f no longer owns the handle
    return f.valid() ? 1 : 0;
}
