struct RunningMax<I> {
    iter: I,
    current: Option<i64>,
}

impl<I: Iterator<Item = i64>> Iterator for RunningMax<I> {
    type Item = i64;

    fn next(&mut self) -> Option<i64> {
        let next = self.iter.next()?;
        let max = match self.current {
            Some(prev) => prev.max(next),
            None => next,
        };
