fn is_vowel(c: char) -> bool {
    matches!(c, 'a' | 'e' | 'i' | 'o' | 'u' | 'A' | 'E' | 'I' | 'O' | 'U')
}

pub fn reverse_vowels(s: &str) -> String {
    let mut chars: Vec<char> = s.chars().collect();
    let mut i = 0usize;
    let mut j = chars.len().saturating_sub(1);

    while i < j {
        if !is_vowel(chars[i]) {
            i += 1;
            continue;
        }
        if !is_vowel(chars[j]) {
            j -= 1;
            continue;
        }
        chars.swap(i, j);
        i += 1;
        j -= 1;
    }

    chars.into_iter().collect()
}

