    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    if (!rb.empty()) return 1;
    rb.push(1); rb.push(2); rb.push(3); rb.push(4);
    if (rb.size() != 3) return 1;
    if (rb[0] != 2 || rb[1] != 3 || rb[2] != 4) return 1;
    rb.push(5);
    if (rb[0] != 3 || rb[2] != 5) return 1;
    std::cout << "ok\n";
    return 0;
}
```

When full, `push` advances the head so the oldest value is overwritten. `operator[]` maps logical index 0 to the oldest surviving element.

```cpp
#include <cstdint>
#include <fstream>
#include <iostream>
#include <string>

// FNV-1a 64-bit over the raw bytes of a file, streamed in chunks.
uint64_t file_checksum(const std::string& path) {
    constexpr uint64_t kOffset = 1469598103934665603ULL;
    constexpr uint64_t kPrime = 1099511628211ULL;
    std::ifstream in(path, std::ios::binary);
    if (!in) throw std::runtime_error("cannot open: " + path);

    uint64_t hash = kOffset;
    char buf[8192];
    while (in) {
        in.read(buf, sizeof(buf));
        std::streamsize n = in.gcount();
        for (std::streamsize i = 0; i < n; ++i) {
            hash ^= static_cast<unsigned char>(buf[i]);
            hash *= kPrime;
        }
    }
    return hash;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "usage: checksum <file>\n";
        return 2;
    }
    try {
        std::cout << std::hex << file_checksum(argv[1]) << "\n";
    } catch (const std::exception& e) {
        std::cerr << e.what() << "\n";
        return 1;
    }
    return 0;
}
```

Streams 8 KiB chunks so memory use is constant regardless of file size. Missing files exit with a message rather than crashing.

