use std::collections::HashMap;

/// Parse "KEY=VALUE" lines. Lines starting with '#' and blank lines are skipped.
/// Values may contain '=' beyond the first one.
fn parse_config(input: &str) -> Result<HashMap<String, String>, String> {
    let mut map = HashMap::new();
    for (i, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        match line.split_once('=') {
            Some((k, v)) => {
                let key = k.trim();
                if key.is_empty() {
                    return Err(format!("line {}: empty key", i + 1));
                }
                map.insert(key.to_string(), v.trim().to_string());
            }
            None => return Err(format!("line {}: missing '='", i + 1)),
        }
    }
    Ok(map)
}

fn main() {
    let text = "# config\nhost = localhost\nport=8080\nurl = a=b&c=d\n";
    let cfg = parse_config(text).expect("valid config");
    assert_eq!(cfg.get("host").map(String::as_str), Some("localhost"));
    assert_eq!(cfg.get("port").map(String::as_str), Some("8080"));
    assert_eq!(cfg.get("url").map(String::as_str), Some("a=b&c=d"));
    assert_eq!(cfg.len(), 3);
    println!("ok");
}
```

