```rust
use std::collections::HashMap;

fn top_k_words(text: &str, k: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let cleaned: String = word
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '\'')
            .flat_map(|c| c.to_lowercase())
            .collect();
        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    // Higher count first; on ties, alphabetical ascending.
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(k);
    pairs
}

fn main() {
    let text = "the quick fox. The FOX! a a";
    let result = top_k_words(text, 3);
    assert_eq!(result[0], ("a".to_string(), 2));
    assert_eq!(result[1], ("fox".to_string(), 2));
    assert_eq!(result[2], ("the".to_string(), 2));
    assert!(top_k_words("", 5).is_empty());
    for (w, c) in &result {
        println!("{w}: {c}");
    }
}
```

`split_whitespace` handles arbitrary spacing, filtering strips punctuation, and `to_lowercase` inside `flat_map` handles Unicode case-folding that can expand to multiple chars. Sorting by count descending then name ascending gives the required tie-break, and `truncate(k)` is safe even when `k` exceeds the number of distinct words.

