#include <unistd.h>
#include <fcntl.h>
#include <utility>
#include <stdexcept>
#include <string>
#include <iostream>

class FileDesc {
public:
    FileDesc() noexcept = default;

    explicit FileDesc(const char* path, int flags = O_RDONLY) {
        fd_ = ::open(path, flags);
        if (fd_ < 0) {
            throw std::runtime_error(std::string("open failed: ") + path);
        }
    }

    ~FileDesc() { reset(); }

    FileDesc(const FileDesc&) = delete;
    FileDesc& operator=(const FileDesc&) = delete;

    FileDesc(FileDesc&& other) noexcept : fd_(other.fd_) { other.fd_ = -1; }

    FileDesc& operator=(FileDesc&& other) noexcept {
        if (this != &other) {
            reset();
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    int get() const noexcept { return fd_; }
    explicit operator bool() const noexcept { return fd_ >= 0; }

    void reset(int new_fd = -1) noexcept {
        if (fd_ >= 0) {
            ::close(fd_);
        }
        fd_ = new_fd;
    }

private:
    int fd_ = -1;
};

int main() {
    FileDesc f("/etc/hostname");
    FileDesc moved = std::move(f);
    std::cout << "valid after move: " << (bool)moved << "\n";
    std::cout << "source now invalid: " << (bool)f << "\n";
}
```

Copying is deleted so two owners can't close the same descriptor. The move constructor and move assignment transfer ownership and set the source to `-1`, so the destructor's `reset()` becomes a no-op. `reset()` closes any current handle before adopting a new one, which makes it safe for `dup2`-style re-assignment.

