```cpp
#include <iostream>
#include <cstdint>

constexpr std::int64_t MOD = 1000000007;

std::int64_t fib_mod(std::uint64_t n) {
    std::int64_t a = 0, b = 1;
    for (std::uint64_t i = 0; i < n; ++i) {
        std::int64_t next = (a + b) % MOD;
        a = b;
        b = next;
    }
    return a;
}

int main() {
    std::cout << fib_mod(0) << '\n';   // 0
    std::cout << fib_mod(1) << '\n';   // 1
    std::cout << fib_mod(10) << '\n';  // 55
    std::cout << fib_mod(90) << '\n';  // 2880067194370816120 % MOD
    return 0;
}
```

Iteration avoids the exponential recursion and its stack growth. Each addition is taken modulo `1e9+7` immediately, so values stay below `2 * MOD` — well inside 64-bit range — and `n` is `uint64_t` so large counts don't overflow the counter. `fib_mod(0) == 0` and `fib_mod(1) == 1` fall out of the loop naturally.

