#include <iostream>
#include <queue>
#include <vector>
#include <limits>

using Edge = std::pair<int, int>; // (node, weight)
const int INF = std::numeric_limits<int>::max();

std::vector<int> dijkstra(const std::vector<std::vector<Edge>>& g, int src) {
    const int n = static_cast<int>(g.size());
    std::vector<int> dist(n, INF);
    std::priority_queue<Edge, std::vector<Edge>, std::greater<Edge>> pq;
    dist[src] = 0;
    pq.push({src, 0});

    while (!pq.empty()) {
        auto [u, d] = pq.top();
        pq.pop();
        if (d > dist[u]) continue; // stale entry
        for (auto [v, w] : g[u]) {
            if (dist[u] != INF && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({v, dist[v]});
            }
        }
    }
    return dist;
}

int main() {
    int n = 5;
    std::vector<std::vector<Edge>> g(n);
    g[0].push_back({1, 4}); g[0].push_back({2, 1});
    g[2].push_back({1, 2}); g[1].push_back({3, 5});
    g[2].push_back({3, 8}); g[3].push_back({4, 3});

    auto dist = dijkstra(g, 0);
    for (int i = 0; i < n; ++i)
        std::cout << "node " << i << ": "
                  << (dist[i] == INF ? -1 : dist[i]) << '\n';
    return 0;
}
```

The `d > dist[u]` check discards outdated heap entries so each edge relaxes at most twice. `-1` marks unreachable nodes.

