```rust
/// Splits one CSV record. Double quotes wrap a field; `""` inside quotes is a
/// literal quote. Returns None if quotes are unbalanced.
fn parse_csv_line(line: &str) -> Option<Vec<String>> {
    let mut fields = Vec::new();
    let mut cur = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();

    while let Some(c) = chars.next() {
        match c {
            '"' if in_quotes => {
                if chars.peek() == Some(&'"') {
                    cur.push('"');
                    chars.next();
                } else {
                    in_quotes = false;
                }
            }
            '"' => in_quotes = true,
            ',' if !in_quotes => {
                fields.push(std::mem::take(&mut cur));
            }
            _ => cur.push(c),
        }
    }
    if in_quotes {
        return None;
    }
    fields.push(cur);
    Some(fields)
}

fn main() {
    let line = r#"name,age,"city, state",note"#;
    match parse_csv_line(line) {
        Some(f) => println!("{:?}", f),
        None => println!("unbalanced quotes"),
    }
}
```

`mem::take` avoids cloning the field buffer. Unbalanced quotes return `None` instead of silently producing garbage.

