```cpp
#include <array>
#include <cstddef>
#include <optional>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : capacity_(capacity), buf_(capacity) {}

    bool push(int value) {
        if (size_ == capacity_)
            return false;
        buf_[(head_ + size_) % capacity_] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0)
            return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return value;
    }

    std::optional<int> front() const {
        if (size_ == 0)
            return std::nullopt;
        return buf_[head_];
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return capacity_; }
    bool empty() const { return size_ == 0; }

private:
    std::size_t capacity_;
    std::vector<int> buf_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};
