#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head != NULL) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (n == NULL)
        return head;
    n->value = value;
    n->next = head;
    return n;
}

void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; ++i)
        head = push(head, i);

    head = reverse(head);
    for (Node *p = head; p != NULL; p = p->next)
        printf("%d ", p->value);
    printf("\n");

    free_list(head);
    return 0;
}
