```cpp
#include <cstdint>
#include <iostream>
#include <sstream>
#include <string>

bool is_valid_ipv4(const std::string& s) {
    int octets = 0;
    std::string part;
    std::stringstream ss(s);
    while (std::getline(ss, part, '.')) {
        if (part.empty() || part.size() > 3) return false;
        for (char c : part) {
            if (c < '0' || c > '9') return false;
        }
        if (part.size() > 1 && part[0] == '0') return false; // no leading zeros
        int value = std::stoi(part);
        if (value > 255) return false;
        ++octets;
    }
    // Must end exactly after the last part, no trailing dot.
    return octets == 4 && !s.empty() && s.back() != '.';
}

int main() {
    const char* good[] = {"0.0.0.0", "255.255.255.255", "192.168.1.1"};
    const char* bad[]  = {"256.1.1.1", "1.2.3", "1.2.3.4.5", "01.2.3.4", "a.b.c.d", "1.2.3."};
    for (auto ip : good) {
        if (!is_valid_ipv4(ip)) { std::cerr << "expected valid: " << ip << "\n"; return 1; }
    }
    for (auto ip : bad) {
        if (is_valid_ipv4(ip)) { std::cerr << "expected invalid: " << ip << "\n"; return 1; }
    }
    std::cout << "all cases passed\n";
    return 0;
}
```
