```cpp
#include <functional>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::priority_queue<int> low;                              // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high;  // min-heap
    int x;
    while (std::cin >> x) {
        if (low.empty() || x <= low.top()) low.push(x);
        else high.push(x);

        // Rebalance so sizes differ by at most one.
        if (low.size() > high.size() + 1) {
            high.push(low.top());
            low.pop();
        } else if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }

        if (low.size() == high.size())
            std::cout << (low.top() + high.top()) / 2.0 << "\n";
        else
            std::cout << low.top() << "\n";
    }
    return 0;
}
```
The max-heap `low` holds the smaller half and the min-heap `high` the larger half. After each insert the heaps are rebalanced so the median is either `low.top()` or the average of the two tops. Input is read until EOF, and the output prints one value per line.

```rust
fn encode(input: &str) -> String {
    let mut out = String::new();
    let mut chars = input.chars().peekable();
    while let Some(c) = chars.next() {
        let mut count = 1usize;
        while chars.peek() == Some(&c) {
            chars.next();
            count += 1;
        }
        if count > 1 {
            out.push_str(&count.to_string());
        }
        out.push(c);
    }
    out
}

fn decode(input: &str) -> Result<String, String> {
    let mut out = String::new();
    let mut count = 0usize;
    for c in input.chars() {
        if c.is_ascii_digit() {
            count = count * 10 + c.to_digit(10).unwrap() as usize;
        } else {
            let n = if count == 0 { 1 } else { count };
            for _ in 0..n {
                out.push(c);
            }
            count = 0;
        }
    }
    if count != 0 {
        return Err("trailing digits without a character".to_string());
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip() {
        assert_eq!(encode("aaabbc"), "3a2bc");
        assert_eq!(decode("3a2bc").unwrap(), "aaabbc");
        assert_eq!(encode(""), "");
        assert_eq!(decode("").unwrap(), "");
    }

    #[test]
    fn rejects_bad_input() {
        assert!(decode("12").is_err());
    }
}

fn main() {
    let s = "aaabbcaaaa";
    let e = encode(s);
    println!("{}", e);
    assert_eq!(decode(&e).unwrap(), s);
}
```
The encoder collapses runs of identical characters and only emits a count for runs longer than one. The decoder accumulates multi-digit counts and rejects a trailing count with no character, which would otherwise silently drop data.

```rust
const MOD: u64 = 1_000_000_007;

// Returns (F(n), F(n+1)) mod MOD.
fn fib_pair(n: u64) -> (u64, u64) {
    if n == 0 {
        return (0, 1);
    }
    let (a, b) = fib_pair(n >> 1);
    let c = a * ((2 * b + MOD - a) % MOD) % MOD;
    let d = (a * a + b * b) % MOD;
    if n & 1 == 0 {
        (c, d)
    } else {
        (d, (c + d) % MOD)
    }
}

fn fib_mod(n: u64) -> u64 {
    fib_pair(n).0
}

fn main() {
    assert_eq!(fib_mod(0), 0);
    assert_eq!(fib_mod(1), 1);
    assert_eq!(fib_mod(10), 55);
    assert_eq!(fib_mod(50), 12586269025 % MOD);
    println!("fib(1000000) mod 1e9+7 = {}", fib_mod(1_000_000));
}
```
Fast doubling halves `n` each recursion, giving O(log n) multiplications. The `+ MOD - a` term keeps the subtraction non-negative before the modulo, and all products use `u64` so no intermediate overflows for this modulus.

