Handles INT_MIN via unsigned magnitude, validates the base, and requires a buffer of at least 34 bytes.

```c
#include <limits.h>
#include <stddef.h>

static char digit_ch(unsigned v) {
    return (char)(v < 10 ? '0' + v : 'a' + (v - 10));
}

/* buf must hold at least 34 bytes (33 digits + NUL). Returns buf. */
char *itoa_base(int value, int base, char *buf) {
    if (base < 2 || base > 36 || buf == NULL) return NULL;

    char tmp[34];
    size_t n = 0;
    unsigned int mag = (value < 0)
        ? (unsigned int)(-(value + 1)) + 1u   /* safe for INT_MIN */
        : (unsigned int)value;

    if (mag == 0) tmp[n++] = '0';
    while (mag > 0) {
        tmp[n++] = digit_ch(mag % (unsigned int)base);
        mag /= (unsigned int)base;
    }

    size_t k = 0;
    if (value < 0) buf[k++] = '-';
    while (n > 0) buf[k++] = tmp[--n];
    buf[k] = '\0';
    return buf;
}

#include <assert.h>
#include <string.h>
int main(void) {
    char b[34];
    assert(strcmp(itoa_base(255, 16, b), "ff") == 0);
    assert(strcmp(itoa_base(0, 2, b), "0") == 0);
    assert(strcmp(itoa_base(INT_MIN, 10, b), "-2147483648") == 0);
    assert(itoa_base(5, 1, b) == NULL);
    return 0;
}
```

`-(value + 1) + 1` avoids undefined behaviour when `value == INT_MIN`.

