```python
import sys
from collections import Counter


def parse_args(argv):
    nums = []
    for token in argv:
        try:
            nums.append(float(token))
        except ValueError:
            print(f"skipping non-numeric: {token}", file=sys.stderr)
    return nums


def mean(nums):
    return sum(nums) / len(nums)


def median(nums):
    s = sorted(nums)
    n = len(s)
    mid = n // 2
    if n % 2:
        return s[mid]
    return (s[mid - 1] + s[mid]) / 2


def mode(nums):
    counts = Counter(nums)
    top = max(counts.values())
    return sorted(v for v, c in counts.items() if c == top)


if __name__ == "__main__":
    data = parse_args(sys.argv[1:])
    if not data:
        print("no numbers supplied")
        sys.exit(1)
    print(f"mean:   {mean(data):.4f}")
    print(f"median: {median(data):.4f}")
    print(f"mode:   {mode(data)}")
