```c
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

bool copy_truncating(char *dst, size_t dst_size, const char *src) {
    if (dst == NULL || dst_size == 0) {
        return src != NULL; // nothing copied, report truncation
    }
    if (src == NULL) {
        dst[0] = '\0';
        return true;
    }
    size_t i = 0;
    while (i + 1 < dst_size && src[i] != '\0') {
        dst[i] = src[i];
        i++;
    }
    bool truncated = src[i] != '\0';
    dst[i] = '\0';
    return truncated;
}

int main(void) {
    char buf[5];
    printf("%d %s\n", copy_truncating(buf, sizeof buf, "hello"), buf); // 1 hell
    printf("%d %s\n", copy_truncating(buf, sizeof buf, "hi"), buf);    // 0 hi
    return 0;
}
