def stats(values):
    n = len(values)
    if n == 0:
        return None
    mean = sum(values) / n
    ordered = sorted(values)
    if n % 2:
        median = ordered[n // 2]
    else:
        median = (ordered[n // 2 - 1] + ordered[n // 2]) / 2
    var = sum((x - mean) ** 2 for x in values) / n
