```cpp
#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& v, int target) {
    int lo = 0;
    int hi = static_cast<int>(v.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == target) {
            return mid;
        } else if (v[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    std::vector<int> v = {1, 3, 3, 5, 7, 9, 11};
    std::cout << binary_search(v, 7) << '\n';
    std::cout << binary_search(v, 4) << '\n';
    return 0;
}
```

`lo + (hi - lo) / 2` avoids overflow when indices are large. Because duplicates can appear at any position among equal values, returning the first hit is valid; callers wanting the lowest index should continue searching left after a match. `lo <= hi` handles empty vectors as -1 since `hi` becomes -1.

