class MedianFinder {
    std::priority_queue<int> low;                                   // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> high;  // min-heap
public:
    void add(int x) {
        low.push(x);
        high.push(low.top());
        low.pop();
        if (high.size() > low.size()) {
            low.push(high.top());
            high.pop();
        }
    }
    double median() const {
        if (low.empty()) return 0.0;  // no data yet
        if (low.size() > high.size()) return low.top();
        return (low.top() + high.top()) / 2.0;
    }
};

int main() {
    MedianFinder mf;
    for (int x : {5, 15, 1, 3, 8, 7, 9, 10, 6, 11, 4}) {
        mf.add(x);
        std::cout << mf.median() << "\n";
    }
    return 0;
}
