#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t len;
    size_t cap;
} Vec;

static int vec_init(Vec *v) {
    v->len = 0;
    v->cap = 4;
    v->data = malloc(v->cap * sizeof(int));
    return v->data != NULL;
}

static int vec_push(Vec *v, int x) {
    if (v->len == v->cap) {
        size_t ncap = v->cap * 2;
        int *tmp = realloc(v->data, ncap * sizeof(int));
        if (!tmp) return 0;
        v->data = tmp;
        v->cap = ncap;
    }
    v->data[v->len++] = x;
    return 1;
}

static int vec_get(const Vec *v, size_t i) {
    return v->data[i];
}

static void vec_free(Vec *v) {
    free(v->data);
    v->data = NULL;
    v->len = v->cap = 0;
}

int main(void) {
    Vec v;
    if (!vec_init(&v)) return 1;
    for (int i = 0; i < 20; i++) {
        if (!vec_push(&v, i * i)) { vec_free(&v); return 1; }
    }
    printf("len=%zu cap=%zu last=%d\n", v.len, v.cap, vec_get(&v, v.len - 1));
    vec_free(&v);
    return 0;
}
