// Parse a decimal int. Returns false on bad input or overflow.
bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;

    bool negative = false;
    if (*s == '+' || *s == '-') {
        negative = (*s == '-');
        ++s;
    }
    if (*s == '\0') return false;

    long long acc = 0;
    for (; *s != '\0'; ++s) {
        if (*s < '0' || *s > '9') return false;
        acc = acc * 10 + (*s - '0');
        // Clamp check against the stricter limit as we go.
        if (acc > (long long)INT_MAX + 1) return false;
    }
    if (negative) {
        acc = -acc;
        if (acc < INT_MIN) return false;
    } else if (acc > INT_MAX) {
        return false;
    }
    *out = (int)acc;
    return true;
}
