/// Merge two sorted slices into a single sorted Vec.
/// Runs in O(n + m) time and O(n + m) space.
fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);

    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let a = [1, 3, 5, 7];
    let b: [i32; 0] = [];
    assert_eq!(merge_sorted(&a, &b), vec![1, 3, 5, 7]);

    let c = [2, 4, 6];
    assert_eq!(merge_sorted(&a, &c), vec![1, 2, 3, 4, 5, 6, 7]);

    let empty: [i32; 0] = [];
    assert_eq!(merge_sorted(&empty, &empty), Vec::<i32>::new());

    println!("all merges ok");
}
```

