def is_valid_email(addr: str) -> bool:
    """Conservative RFC-5321-ish validation without regex."""
    if not isinstance(addr, str) or len(addr) > 254:
        return False
    if addr.count("@") != 1:
        return False

    local, _, domain = addr.partition("@")
    if not local or len(local) > 64 or not domain:
        return False

    # Local part: printable ASCII except controls, space and .,@; no leading/trailing/consecutive dots.
    if local.startswith(".") or local.endswith(".") or ".." in local:
        return False
    allowed_local = set("!#$%&'*+-/=?^_`{|}~.")
    for ch in local:
        if not (ch.isalnum() or ch in allowed_local):
            return False

    # Domain: labels separated by dots, each 1..63 alnum or hyphen, no leading/trailing hyphen.
    if len(domain) > 253:
        return False
    labels = domain.split(".")
    if len(labels) < 2:
        return False
    for label in labels:
        if not 1 <= len(label) <= 63:
            return False
        if label.startswith("-") or label.endswith("-"):
            return False
        if not all(c.isalnum() or c == "-" for c in label):
            return False
    if not labels[-1].isalpha():
        return False
    return True


if __name__ == "__main__":
    cases = {
        "user@example.com": True,
        "a..b@example.com": False,
        ".lead@example.com": False,
        "user@-bad.com": False,
        "user@example": False,
        "user@@example.com": False,
        "": False,
    }
    for addr, expected in cases.items():
        got = is_valid_email(addr)
        assert got == expected, (addr, got, expected)
    print("all cases pass")
```

