#include <array>
#include <cstddef>
#include <optional>

// Fixed-capacity ring buffer. push() returns false when full (overwrite is opt-in).
template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& value) {
        if (size_ == N) {
            ++overflows_;
            return false;
        }
        buf_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        std::optional<T> out = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return out;
    }

    // Push, dropping the oldest element if full.
    void push_overwrite(const T& value) {
        if (size_ == N) {
            buf_[head_] = value;
            head_ = (head_ + 1) % N;
            ++overflows_;
        } else {
            push(value);
        }
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t overflows() const { return overflows_; }

private:
    std::array<T, N> buf_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
    std::size_t overflows_ = 0;
};
```

`N` must be at least 1 (a zero-capacity buffer would divide by zero). `push_overwrite` is the bounded-loss path; plain `push` reports the drop instead.

