```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) exit(1);
    n->value = value;
    n->next = head;
    return n;
}

static void print_list(const Node *head) {
    for (; head; head = head->next) printf("%d ", head->value);
    putchar('\n');
}

static void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    for (int i = 1; i <= 5; i++) head = push(head, i);
    print_list(head);
    head = reverse(head);
    print_list(head);
    head = reverse(NULL);
    print_list(head);
    free_list(head);
    return 0;
}
```

`reverse` walks the list once, flipping each `next` pointer while remembering the next node; it returns `prev`, which is the old tail. Passing `NULL` returns `NULL`, so the empty list is safe. `free_list` releases every node after the final reversal.

