```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,  // next write position
    len: usize,   // number of live elements
}

impl<T> RingBuffer<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        let mut data = Vec::with_capacity(capacity);
        data.resize_with(capacity, || None);
        RingBuffer { data, head: 0, len: 0 }
    }

    pub fn push(&mut self, value: T) {
        let cap = self.data.len();
        self.data[self.head] = Some(value);
        self.head = (self.head + 1) % cap;
        if self.len < cap {
            self.len += 1;
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn iter(&self) -> impl Iterator<Item = &T> {
        let cap = self.data.len();
        let start = if self.len < cap { 0 } else { self.head };
        (0..self.len).filter_map(move |i| {
            self.data[(start + i) % cap].as_ref()
        })
    }
}

fn main() {
    let mut rb = RingBuffer::new(3);
    for v in [1, 2, 3, 4, 5] {
        rb.push(v);
    }
    let seen: Vec<i32> = rb.iter().copied().collect();
    println!("{seen:?}");  // [3, 4, 5]
    assert_eq!(seen, vec![3, 4, 5]);
    assert_eq!(rb.len(), 3);
}
```

`Option<T>` lets us overwrite slots without unsafe code. `head` tracks the next write, and once the buffer has wrapped the oldest element is exactly at `head`, so iteration starts there.

