#include <cstdio>

struct Node {
    int value;
    Node* next;
};

Node* merge_sorted(Node* a, Node* b) {
    Node dummy{0, nullptr};
    Node* tail = &dummy;
    while (a != nullptr && b != nullptr) {
        if (a->value <= b->value) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = (a != nullptr) ? a : b;
    return dummy.next;
}

void free_list(Node* head) {
    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    Node* a = new Node{1, new Node{4, new Node{7, nullptr}}};
    Node* b = new Node{2, new Node{3, new Node{9, nullptr}}};
    Node* merged = merge_sorted(a, b);
    for (Node* p = merged; p != nullptr; p = p->next) {
        std::printf("%d ", p->value);
    }
    std::printf("\n");
    free_list(merged);
    return 0;
}
