#define MOD 1000000007ULL

static uint64_t fib_mod(uint64_t n) {
    uint64_t a = 0, b = 1;
    for (uint64_t i = 0; i < n; ++i) {
        uint64_t next = (a + b) % MOD;
        a = b;
        b = next;
    }
    return a;
}

