    printf("fib(0)=%llu\n", (unsigned long long)fib_mod(0));
    printf("fib(10)=%llu\n", (unsigned long long)fib_mod(10));
    printf("fib(90)=%llu\n", (unsigned long long)fib_mod(90));
    return 0;
}
