```cpp
#include <cstdio>
#include <vector>

int lower_bound_index(const std::vector<int>& v, int target) {
    int lo = 0;
    int hi = static_cast<int>(v.size());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo < static_cast<int>(v.size()) && v[lo] == target) {
        return lo;
    }
    return -1;
}

int main() {
    std::vector<int> v{1, 2, 4, 4, 4, 7, 9};
    std::printf("%d\n", lower_bound_index(v, 4));   // 2
    std::printf("%d\n", lower_bound_index(v, 5));   // -1
    std::printf("%d\n", lower_bound_index({}, 1));  // -1
    std::printf("%d\n", lower_bound_index(v, 1));   // 0
    return 0;
}
```

`mid = lo + (hi - lo) / 2` avoids integer overflow, and the half-open `[lo, hi)` loop invariant is what makes `lo` land on the first matching element. An empty vector returns -1 without reading out of bounds.

