int parse_int(const char *s, long *out) {
    if (s == NULL || *s == '\0') return -1;
    errno = 0;
    char *end = NULL;
    long v = strtol(s, &end, 10);
    if (errno == ERANGE) return -2;       // overflow / underflow
    if (end == s || *end != '\0') return -3; // trailing junk
    if (v < INT_MIN || v > INT_MAX) return -2;
    *out = v;
    return 0;
}

