        if (rc == 1) {
            sum += value;
            count++;
        } else if (rc == EOF) {
            break;
        } else {
            int ch;
            while ((ch = getchar()) != EOF && ch != '\n' && ch != ' ' && ch != '\t') {
                /* discard the junk token */
            }
        }
