`scanf("%ld")` returns `1` on success, `0` when the next token is not an integer, and `EOF` at end of input. The junk branch consumes characters up to the next whitespace so a line like `hello 12` skips `hello` without stalling, and the `count == 0` guard avoids dividing or printing meaningless output for empty input.

```rust
use std::collections::HashMap;

pub fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for raw in text.split(|c: char| !c.is_alphanumeric()) {
        if raw.is_empty() {
            continue;
        }
        let word = raw.to_lowercase();
        *counts.entry(word).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The cat and the Cat sat; the DOG barked!";
    for (w, c) in top_words(text, 3) {
        println!("{w}: {c}");
    }
    assert!(top_words("", 5).is_empty());
    // the: 3, cat: 2, and: 1
}
```

Splitting on any non-alphanumeric character handles punctuation and newlines in one pass, and `to_lowercase` normalizes case so `Cat` and `cat` merge. The sort is descending by count then ascending by word, which makes ties deterministic; `truncate(n)` keeps the result bounded even when `n` exceeds the vocabulary, and an empty string produces an empty vector.

```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    void push(int value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return q_.size() < cap_; });
        q_.push(value);
        lock.unlock();
        not_empty_.notify_one();
    }

    int pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return !q_.empty(); });
        int value = q_.front();
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

private:
    std::size_t cap_;
    std::queue<int> q_;
    std::mutex mu_;
    std::condition_variable not_full_;
    std::condition_variable not_empty_;
};

#include <cassert>
#include <thread>

int main() {
    BoundedQueue q(2);
    std::thread producer([&] {
        for (int i = 0; i < 5; ++i) q.push(i);
    });
    int sum = 0;
    for (int i = 0; i < 5; ++i) sum += q.pop();
    producer.join();
    assert(sum == 0 + 1 + 2 + 3 + 4);
}
```

Each wait uses a predicate so spurious wakeups are handled without an extra loop. The mutex is unlocked *before* notifying, which avoids waking a thread that then blocks again on the still-held lock. A capacity of `2` with five items exercises the full path, and the assertion checks the producer/consumer totals agree.

```python
import re

LOCAL = re.compile(r"^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+$")
DOMAIN = re.compile(r"^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)+$")


def normalize(email: str):
    """Return (normalized, None) or (None, reason)."""
    if not isinstance(email, str):
        return None, "not a string"
    email = email.strip()
    if not email:
        return None, "empty"
    if email.count("@") != 1:
        return None, "expected exactly one @"
    local, domain = email.rsplit("@", 1)
    if not local or len(local) > 64:
        return None, "bad local part length"
    if local.startswith(".") or local.endswith(".") or ".." in local:
        return None, "bad dot placement"
    if not LOCAL.match(local):
        return None, "invalid local characters"
    domain = domain.lower()
    if len(domain) > 255 or not DOMAIN.match(domain):
        return None, "invalid domain"
    if local.count(".") and local.startswith("."):
        return None, "leading dot"
    return f"{local}@{domain}", None


if __name__ == "__main__":
    raw = [" Alice@Example.COM ", "bob@@x.com", "a..b@x.com", "", "bad", "ok@sub.example.org"]
    for item in raw:
        norm, reason = normalize(item)
        print(repr(item), "->", norm if norm else f"rejected: {reason}")
```

The split is done with `rsplit("@", 1)` after confirming exactly one `@`, so `bob@@x.com` is rejected rather than misparsed. The domain is lowercased while the local part is preserved, since local parts are case-sensitive in principle. Empty input, bad dot placement, oversized parts, and malformed domains each return a distinct reason so the caller can log why a value was dropped.

```c
#include <stddef.h>
#include <string.h>

/* Copies src into dst (capacity cap), always NUL-terminating when cap > 0.
   Returns strlen(src) (bytes that WOULD be copied), like snprintf. */
size_t safe_copy(char *dst, size_t cap, const char *src) {
    if (dst == NULL || cap == 0) {
        return src ? strlen(src) : 0;
    }
    size_t i = 0;
    while (i + 1 < cap && src[i] != '\0') {
        dst[i] = src[i];
        i++;
    }
    dst[i] = '\0';
    return strlen(src);
}

#include <stdio.h>

int main(void) {
    char buf[8];
    size_t needed = safe_copy(buf, sizeof buf, "hello world");
    printf("stored=\"%s\" needed=%zu\n", buf, needed);
    /* stored="hello w" needed=11 */
    char empty[1];
    safe_copy(empty, 1, "");
    return 0;
}
```

The loop keeps one byte in reserve for the terminator, so `buf` of size 8 holds 7 characters plus `'\0'`. Returning `strlen(src)` mirrors `snprintf` and lets a caller detect truncation by comparing the return value against `cap`. The `cap == 0` and `NULL` cases are handled up front so the function cannot write through a zero-length buffer.

