```cpp
#include <iostream>
#include <optional>
#include <unordered_map>
#include <utility>
#include <vector>

std::optional<std::pair<int, int>> two_sum(const std::vector<int>& nums, int target) {
    std::unordered_map<int, int> seen;  // value -> index
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        int need = target - nums[i];
        auto it = seen.find(need);
        if (it != seen.end()) {
            return std::make_pair(it->second, i);
        }
        seen.emplace(nums[i], i);
    }
    return std::nullopt;
}

int main() {
    std::vector<int> nums{2, 7, 11, 15};
    if (auto r = two_sum(nums, 9)) {
        std::cout << r->first << ", " << r->second << "\n";  // 0, 1
    } else {
        std::cout << "no pair\n";
    }

    if (!two_sum({1, 2, 3}, 100)) {
        std::cout << "no pair for 100\n";
    }
    return 0;
}
```

The map stores each value with the index where it was first seen, so a single pass finds a complement in `O(1)` average lookup, giving `O(n)` time and `O(n)` space. The complement is checked *before* inserting the current element, which prevents using the same index twice when `nums[i] * 2 == target`. The missing-pair case returns `std::nullopt` rather than a garbage index.

