```cpp
#include <cstddef>
#include <cstdint>
#include <optional>
#include <stdexcept>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), tail_(0), count_(0) {
        if (capacity == 0)
            throw std::invalid_argument("capacity must be positive");
    }

    bool push(std::int32_t value) {
        if (count_ == data_.size())
            return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % data_.size();
        ++count_;
        return true;
    }

    std::optional<std::int32_t> pop() {
        if (count_ == 0)
            return std::nullopt;
        std::int32_t value = data_[head_];
        head_ = (head_ + 1) % data_.size();
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }

private:
    std::vector<std::int32_t> data_;
    std::size_t head_, tail_, count_;
};
```

`pop()` on an empty buffer returns `std::nullopt` instead of undefined behaviour, and a zero capacity throws at construction. Wrap-around uses modulo on both indices so no element is ever read before being written.

