```cpp
#include <cstddef>
#include <optional>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), size_(0) {}

    bool push(const T& item) {
        if (size_ == data_.size()) {
            return false;
        }
        data_[(head_ + size_) % data_.size()] = item;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        T item = data_[head_];
        head_ = (head_ + 1) % data_.size();
        --size_;
        return item;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == data_.size(); }
    std::size_t size() const { return size_; }

private:
    std::vector<T> data_;
    std::size_t head_;
    std::size_t size_;
};
```

`push` returns `false` when full and `pop` returns `std::nullopt` when empty, so callers never read stale slots.

