```c
#include <stddef.h>
#include <string.h>

/*
 * Copy src into dst (capacity dst_size), always NUL-terminating when
 * dst_size > 0. Returns the length of src, like snprintf: if the return
 * value is >= dst_size, the copy was truncated and the caller knows by
 * how much. Returns 0 and writes an empty string when dst_size == 0.
 */
size_t safe_copy(char *dst, size_t dst_size, const char *src) {
    size_t len = strlen(src);
    if (dst_size == 0) {
        return len;
    }
    size_t copy = len < dst_size - 1 ? len : dst_size - 1;
    memcpy(dst, src, copy);
    dst[copy] = '\0';
    return len;
}

#include <stdio.h>
int main(void) {
    char buf[8];
    size_t need = safe_copy(buf, sizeof buf, "hello world");
    printf("truncated: %s (needed %zu)\n", buf, need);

    char exact[12];
    safe_copy(exact, sizeof exact, "hello world");
    printf("exact: %s\n", exact);
    return 0;
}
```

The return value follows the `snprintf` convention: equal to the full source length when it fits, larger when truncated. `copy` is clamped to `dst_size - 1`, leaving room for the terminator, and the `dst_size == 0` branch avoids underflow without dereferencing the buffer.

```rust
pub struct RingBuffer<T> {
    data: Vec<Option<T>>,
    head: usize,
    len: usize,
    cap: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(cap: usize) -> Self {
        let mut data = Vec::with_capacity(cap);
        data.resize_with(cap, || None);
        RingBuffer { data, head: 0, len: 0, cap }
    }

    pub fn push(&mut self, value: T) -> Result<(), T> {
        if self.len == self.cap {
            return Err(value);
        }
        let idx = (self.head + self.len) % self.cap;
        self.data[idx] = Some(value);
        self.len += 1;
        Ok(())
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        let value = self.data[self.head].take();
        self.head = (self.head + 1) % self.cap;
        self.len -= 1;
        value
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
}

fn main() {
    let mut rb = RingBuffer::new(2);
    assert!(rb.is_empty());
    assert!(rb.push(1).is_ok());
    assert!(rb.push(2).is_ok());
    assert_eq!(rb.push(3), Err(3)); // full, value returned back
    assert_eq!(rb.pop(), Some(1));
    assert_eq!(rb.pop(), Some(2));
    assert_eq!(rb.pop(), None);
    assert!(rb.is_empty());
    println!("ok");
}
```

A `Vec<Option<T>>` pre-sized to capacity makes the modulo indexing simple and avoids shifting. `push` returns the rejected value when full instead of silently dropping it, and `pop` returns `None` on an empty buffer, so the type stays panic-free for these operations. Capacity is normalized by `% self.cap`, keeping the indices in range.

```cpp
#include <list>
#include <unordered_map>
#include <utility>

class LruCache {
public:
    explicit LruCache(size_t capacity) : cap_(capacity) {}

    // Returns -1 when the key is absent.
    int get(int key) {
        auto it = map_.find(key);
        if (it == map_.end()) return -1;
        items_.splice(items_.begin(), items_, it->second); // move to front
        return it->second->second;
    }

    void put(int key, int value) {
        if (cap_ == 0) return;
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (items_.size() == cap_) {
            map_.erase(items_.back().first);
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        map_[key] = items_.begin();
    }

private:
    size_t cap_;
    std::list<std::pair<int, int>> items_;             // most recent at front
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> map_;
};

#include <cassert>
int main() {
    LruCache c(2);
    c.put(1, 1);
    c.put(2, 2);
    assert(c.get(1) == 1);   // marks 1 as most recent
    c.put(3, 3);             // evicts 2
    assert(c.get(2) == -1);
    assert(c.get(3) == 3);
    assert(c.get(1) == 1);
    LruCache empty(0);
    empty.put(9, 9);
    assert(empty.get(9) == -1); // zero capacity stores nothing
    return 0;
}
```

`splice` moves an existing node to the front without invalidating its iterator, so `get` and `put` both stay O(1). The map holds list iterators, letting eviction erase the exact back node. Capacity 0 is a no-op rather than undefined behavior.

