 template <typename T, std::size_t N>
 class RingBuffer {
 public:
     bool push(const T& value) {
         if (count_ == N) return false;
         data_[(head_ + count_) % N] = value;
         ++count_;
         return true;
     }

     T pop() {
         if (count_ == 0) throw std::underflow_error("empty ring buffer");
         T value = data_[head_];
         head_ = (head_ + 1) % N;
         --count_;
         return value;
     }

     std::size_t size() const noexcept { return count_; }
     std::size_t capacity() const noexcept { return N; }

 private:
     std::array<T, N> data_{};
     std::size_t head_ = 0;
     std::size_t count_ = 0;
 };
