bool isPalindrome(const std::string& s) {
    int i = 0, j = static_cast<int>(s.size()) - 1;
    while (i < j) {
        if (!std::isalnum(static_cast<unsigned char>(s[i]))) { ++i; continue; }
        if (!std::isalnum(static_cast<unsigned char>(s[j]))) { --j; continue; }
