    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 1], &[1]), vec![1, 1, 1]);
    assert_eq!(merge_sorted(&["b"], &["a"]), vec!["a", "b"]);
