```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int *data;
    size_t cap, len, head;
} Ring;

int ring_init(Ring *r, size_t cap) {
    if (cap == 0) return -1;
    r->data = malloc(cap * sizeof(int));
    if (!r->data) return -1;
    r->cap = cap;
    r->len = 0;
    r->head = 0;
    return 0;
}

void ring_free(Ring *r) { free(r->data); r->data = NULL; }

int ring_push(Ring *r, int v) {
    if (r->len < r->cap) {
        r->data[(r->head + r->len) % r->cap] = v;
        r->len++;
        return 0;
    }
    r->data[r->head] = v;
    r->head = (r->head + 1) % r->cap;
    return 0;
}

int ring_pop(Ring *r, int *out) {
    if (r->len == 0) return -1;
    *out = r->data[r->head];
    r->head = (r->head + 1) % r->cap;
    r->len--;
    return 0;
}

int main(void) {
    Ring r;
    if (ring_init(&r, 3) != 0) return 1;
    for (int i = 0; i < 5; i++) ring_push(&r, i * 10);
    int v;
    while (ring_pop(&r, &v) == 0) printf("%d ", v);
    printf("\n");
    ring_free(&r);
    return 0;
}
```
Prints `20 30 40` — the three most recent values, oldest first. `ring_pop` on an empty buffer returns -1 so callers can distinguish.

```rust
#[derive(Debug, PartialEq)]
struct Version {
    major: u64,
    minor: u64,
    patch: u64,
    pre: Option<String>,
}

fn parse_semver(s: &str) -> Result<Version, String> {
    let (core, pre) = match s.split_once('-') {
        Some((c, p)) => {
            if p.is_empty() || !p.chars().all(|ch| ch.is_ascii_alphanumeric() || ch == '.' || ch == '-') {
                return Err(format!("invalid pre-release: {p}"));
            }
            (c, Some(p.to_string()))
        }
        None => (s, None),
    };

    let parts: Vec<&str> = core.split('.').collect();
    if parts.len() != 3 {
        return Err(format!("expected 3 numeric parts, got {}", parts.len()));
    }

    let mut nums = [0u64; 3];
    for (i, p) in parts.iter().enumerate() {
        if p.is_empty() || !p.chars().all(|c| c.is_ascii_digit()) {
            return Err(format!("non-numeric component: {p}"));
        }
        nums[i] = p.parse().map_err(|_| format!("overflow in {p}"))?;
        if p.len() > 1 && p.starts_with('0') {
            return Err(format!("leading zero in {p}"));
        }
    }

    Ok(Version { major: nums[0], minor: nums[1], patch: nums[2], pre })
}

fn main() {
    assert_eq!(parse_semver("1.2.3").unwrap(), Version { major: 1, minor: 2, patch: 3, pre: None });
    assert_eq!(parse_semver("1.0.0-rc.1").unwrap().pre.as_deref(), Some("rc.1"));
    assert!(parse_semver("1.2").is_err());
    assert!(parse_semver("01.2.3").is_err());
    assert!(parse_semver("1.2.3-beta!").is_err());
    println!("all assertions passed");
}
```
The parser splits the pre-release first, then validates the three numeric components including the no-leading-zero rule from the semver spec.

