    Node* b = new Node(2, new Node(4, new Node(6)));
    Node* m = merge_sorted(a, b);
    for (Node* p = m; p; p = p->next) std::cout << p->val << ' ';
    std::cout << '\n';
    while (m) { Node* n = m->next; delete m; m = n; }
    return 0;
}
