class File {
public:
    explicit File(const char* path, int flags = O_RDONLY) : fd_(open(path, flags)) {}
    File(const File&) = delete;
    File& operator=(const File&) = delete;

    File(File&& other) noexcept : fd_(other.fd_) { other.fd_ = -1; }

    File& operator=(File&& other) noexcept {
        if (this != &other) {
            reset();
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    ~File() { reset(); }

    [[nodiscard]] int get() const { return fd_; }
    [[nodiscard]] bool valid() const { return fd_ >= 0; }
    explicit operator bool() const { return valid(); }

private:
    void reset() noexcept {
        if (fd_ >= 0) { ::close(fd_); fd_ = -1; }
    }
    int fd_;
};

int main() {
    File f("/etc/hostname");
    if (f) std::cout << "fd=" << f.get() << '\n';
    File g = std::move(f);
    std::cout << "original valid after move: " << std::boolalpha << f.valid() << '\n';
    return 0;
}
