def flatten(nested):
    out = []
    stack = [iter(nested)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if item is None:
            continue
        if isinstance(item, (list, tuple)):
            stack.append(iter(item))
        else:
            out.append(item)
