/// Return the index of the first element >= target (lower bound).
/// If every element is < target, returns `data.len()`.
/// `data` must be sorted ascending; empty slices are handled.
pub fn lower_bound<T: Ord>(data: &[T], target: &T) -> usize {
    let mut lo = 0usize;
    let mut hi = data.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if &data[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

