def fib_matrix(n):
    """Return the nth Fibonacci number, F(0)=0, F(1)=1, in O(log n)."""
    if n < 0:
        raise ValueError("n must be non-negative")

    def mul(a, b):
        return (
            (a[0] * b[0] + a[1] * b[2], a[0] * b[1] + a[1] * b[3]),
            (a[2] * b[0] + a[3] * b[2], a[2] * b[1] + a[3] * b[3]),
        )

    result = (1, 0, 0, 1)  # identity
    base = (1, 1, 1, 0)
    while n:
        if n & 1:
            result = mul(result, base)
        base = mul(base, base)
        n >>= 1
    return result[1]


