This computes true Damerau-Levenshtein distance, including transpositions of adjacent characters. The DP table is (m+1) x (n+1); the extra `da` map tracks the last row where each character appeared, which is what lets an adjacent swap cost 1 instead of 2.

```python
def damerau_levenshtein(a: str, b: str) -> int:
    """Optimal string alignment is not enough; this is the full algorithm."""
    if a == b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)

    # 1-indexed grid: d[i][j] is the distance for a[:i], b[:j]
    d = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a) + 1):
        d[i][0] = i
    for j in range(len(b) + 1):
        d[0][j] = j

    last_row = {}
    for i in range(1, len(a) + 1):
        last_match_col = 0
        for j in range(1, len(b) + 1):
            i1 = last_row.get(b[j - 1], 0)
            j1 = last_match_col
            cost = 0 if a[i - 1] == b[j - 1] else 1
            if cost == 0:
                last_match_col = j
            dist = min(
                d[i - 1][j] + 1,        # deletion
                d[i][j - 1] + 1,        # insertion
                d[i - 1][j - 1] + cost, # substitution
            )
            if i1 and j1:
                dist = min(dist, d[i1 - 1][j1 - 1] + (i - i1 - 1) + 1 + (j - j1 - 1))
            d[i][j] = dist
        last_row[a[i - 1]] = i

    return d[len(a)][len(b)]


if __name__ == "__main__":
    cases = [
        ("kitten", "sitting"),
        ("ca", "abc"),
        ("ab", "ba"),
        ("caf\u00e9", "cafe"),
        ("", "abc"),
        ("flaw", "lawn"),
    ]
    for x, y in cases:
        print(f"{x!r} -> {y!r}: {damerau_levenshtein(x, y)}")
```

`kitten`/`sitting` gives 3, `ab`/`ba` gives 1 via the transposition rule, and the unicode case handles `café` vs `cafe` as a single substitution because Python strings index by code point.

Bit rotation by an arbitrary count is easiest when you normalize the shift first. Here the array is treated as one big-endian bit string, so a left rotate by `n` moves the top `n % (8*len)` bits to the tail.

```c
#include <stddef.h>
#include <stdint.h>
#include <string.h>

/*
 * Rotate buf[0..len) left by n bits, in place.
 * Returns the effective shift used (n modulo total bits).
 * len may be 0; n may be any unsigned value.
 */
size_t rotl_bytes(uint8_t *buf, size_t len, size_t n) {
    if (len == 0) return 0;

    size_t total = len * 8;
    size_t shift = n % total;
    if (shift == 0) return 0;

    size_t whole_bytes = shift / 8;
    size_t rem_bits = shift % 8;

    uint8_t tmp[256];
    if (len > sizeof(tmp)) return 0; /* caller must chunk larger buffers */

    for (size_t i = 0; i < len; i++) {
        size_t src = (i + whole_bytes) % len;
        tmp[i] = buf[src];
    }

    if (rem_bits == 0) {
        memcpy(buf, tmp, len);
        return shift;
    }

    for (size_t i = 0; i < len; i++) {
        uint8_t hi = tmp[i];
        uint8_t lo = tmp[(i + 1) % len];
        buf[i] = (uint8_t)((hi << rem_bits) | (lo >> (8 - rem_bits)));
    }
    return shift;
}
```

The `rem_bits` loop is the only subtle part: each output byte pulls its low bits from the next byte's high bits, wrapping at the end of the buffer. `len == 0` returns without touching memory, and `shift == 0` is a no-op so repeated calls stay idempotent.

The two-sum map approach reports each unordered pair once by insisting on `i < j` and skipping duplicate combinations when the complement equals the current value. Using `unordered_map<int, vector<size_t>>` keeps positions so duplicates like `[3,3,3]` target 6 don't collapse into a single pair.

```cpp
#include <iostream>
#include <unordered_map>
#include <vector>

std::vector<std::pair<int, int>> two_sum_pairs(const std::vector<int>& nums, int target) {
    std::unordered_map<int, std::vector<std::size_t>> seen;
    std::vector<std::pair<int, int>> out;

    for (std::size_t j = 0; j < nums.size(); ++j) {
        int need = target - nums[j];
        auto it = seen.find(need);
        if (it != seen.end()) {
            for (std::size_t i : it->second) {
                out.emplace_back(nums[i], nums[j]);
            }
        }
        seen[nums[j]].push_back(j);
    }
    return out;
}

int main() {
    std::vector<int> data = {1, 3, 2, 2, 4, -1, 5};
    int target = 4;
    auto pairs = two_sum_pairs(data, target);
    for (const auto& p : pairs) {
        std::cout << p.first << " + " << p.second << " = " << target << '\n';
    }
    std::cout << "pairs: " << pairs.size() << '\n';
    return 0;
}
```

A pair is only emitted when its smaller index is already in the map, so `(3,1)` and `(1,3)` never both appear. For `{1,3,2,2,4,-1,5}` and target 4 the output is `-1+5`, `1+3`, `2+2`, `2+2` — the two distinct index pairs of the equal-valued 2s.

The parser ignores blank lines and `#` comments, splits on the first `=`, trims key and value, and reports the line number for malformed entries instead of panicking. Keys are sorted with a `BTreeMap` view so output is deterministic.

```rust
use std::collections::HashMap;

fn parse_ini(input: &str) -> Result<HashMap<String, String>, String> {
    let mut map = HashMap::new();
    for (idx, raw) in input.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') || line.starts_with(';') {
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            return Err(format!("line {}: missing '=' in {:?}", idx + 1, raw));
        };
        let key = key.trim();
        if key.is_empty() {
            return Err(format!("line {}: empty key", idx + 1));
        }
        map.insert(key.to_string(), value.trim().to_string());
    }
    Ok(map)
}

fn main() {
    let cfg = "# app config\nhost = 127.0.0.1\n\nport=8080   \ndebug = true\n";
    match parse_ini(cfg) {
        Ok(map) => {
            let mut keys: Vec<_> = map.keys().collect();
            keys.sort();
            for k in keys {
                println!("{k} -> {}", map[k]);
            }
        }
        Err(e) => eprintln!("config error: {e}"),
    }
}
```

`split_once` keeps values that themselves contain `=`, which a naive `split('=')` would lose. Trailing whitespace on `"8080   "` is trimmed, and duplicates silently overwrite with the last value, matching common INI behaviour.

A `Vec<Option<u128>>` serves as the memo table; `checked_add` turns silent wraparound into a `Result` so callers get an explicit overflow error rather than a wrong number.

```rust
use std::collections::HashMap;

fn fib(n: u32, memo: &mut HashMap<u32, u128>) -> Result<u128, String> {
    if let Some(&v) = memo.get(&n) {
        return Ok(v);
    }
    let value = match n {
        0 => 0,
        1 => 1,
        _ => {
            let a = fib(n - 1, memo)?;
            let b = fib(n - 2, memo)?;
            a.checked_add(b)
                .ok_or_else(|| format!("fib({n}) overflows u128"))?
        }
    };
    memo.insert(n, value);
    Ok(value)
}

fn main() {
    let mut memo = HashMap::new();
    for n in 0..=186u32 {
        match fib(n, &mut memo) {
            Ok(v) => println!("fib({n}) = {v}"),
            Err(e) => {
                eprintln!("stopped: {e}");
                break;
            }
        }
    }
}
```

Rust's recursion depth is fine up to `n = 186` here because the memo cache makes each call return in O(1) after the first fill, so the stack stays shallow. The first overflow surfaces around `n = 187`, which is where the loop stops instead of printing a wrapped value.

Two-phase renaming avoids collisions: first copy to a temp prefix, then strip it. Even better is `mv -n` (no-clobber) plus a dry-run flag so you can inspect before touching anything.

```bash
#!/usr/bin/env bash
set -euo pipefail

new_prefix=${1:-2024-trip}
dir=${2:-.}
dry=${DRY_RUN:-0}

shopt -s nullglob nocaseglob
for f in "$dir"/IMG_*.JPG; do
    base=$(basename "$f")
    num=${base#IMG_}
    num=${num^}
    num=${num%.JPG}
    ext=${base##*.}
    ext=${ext,,}
    target=$(printf '%s-%04d.%s' "$new_prefix" "$((10#$num))" "$ext")

    if [[ -e $dir/$target ]]; then
        printf 'skip (exists): %s\n' "$target" >&2
        continue
    fi
    if (( dry )); then
        printf 'would rename: %s -> %s\n' "$base" "$target"
    else
        mv -n -- "$f" "$dir/$target"
        printf 'renamed: %s -> %s\n' "$base" "$target"
    fi
done
```

`10#$num` forces base-10 parsing so `IMG_0008` doesn't turn into an octal error. `nocaseglob` catches `img_0001.jpg` too, and the `-e $target` check skips rather than overwrites when two source files would map to the same destination.

When full, the oldest element is dropped before the new one is stored. Head points at the next write slot, tail at the oldest live element; when the buffer wraps a full lap, tail advances to match.

```cpp
#include <cstddef>
#include <optional>
#include <stdexcept>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : buf_(capacity), head_(0), tail_(0), full_(false) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(const T& value) {
        buf_[head_] = value;
        if (full_) {
            tail_ = (tail_ + 1) % buf_.size();
        }
        head_ = (head_ + 1) % buf_.size();
        full_ = head_ == tail_;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = buf_[tail_];
        tail_ = (tail_ + 1) % buf_.size();
        full_ = false;
        return value;
    }

    bool empty() const { return !full_ && head_ == tail_; }
    bool full() const { return full_; }
    std::size_t size() const {
        if (full_) return buf_.size();
        return (head_ + buf_.size() - tail_) % buf_.size();
    }

private:
    std::vector<T> buf_;
    std::size_t head_;
    std::size_t tail_;
    bool full_;
};
```

The `full_` flag distinguishes "empty" from "exactly full", since both look like `head_ == tail_`. Copying `T` on `push` keeps it simple; a production version would add a move overload, but the overwrite semantics are what matter here.

A single-pass state machine is the only safe way to do this — regexes break on `"//"` inside a string and on escaped quotes. States are NORMAL, LINE_COMMENT, BLOCK_COMMENT, STRING, and CHAR.

```c
#include <stdio.h>

enum state { NORMAL, LINE_COMMENT, BLOCK_COMMENT, STRING, CHAR_LIT };

int main(void) {
    enum state st = NORMAL;
    int c, prev = 0;

    while ((c = getchar()) != EOF) {
        switch (st) {
        case NORMAL:
            if (c == '/' && prev == '/') {
                /* we already wrote the first '/'; undo by not having written it */
                st = LINE_COMMENT;
            } else if (c == '*' && prev == '/') {
                st = BLOCK_COMMENT;
            } else {
                putchar(c);
            }
            break;

        case LINE_COMMENT:
            if (c == '\n') { putchar(c); st = NORMAL; }
            break;

        case BLOCK_COMMENT:
            if (c == '/' && prev == '*') st = NORMAL;
            break;

        case STRING:
            putchar(c);
            if (c == '\\') { putchar(getchar()); }
            else if (c == '"') st = NORMAL;
            break;

        case CHAR_LIT:
            putchar(c);
            if (c == '\\') { putchar(getchar()); }
            else if (c == '\'') st = NORMAL;
            break;
        }

        if (st == NORMAL && (c == '"' || c == '\'')) {
            st = (c == '"') ? STRING : CHAR_LIT;
        }
        prev = c;
    }
    return 0;
}
```

One caveat worth stating: this version writes the leading `/` of a comment before recognising it, so a two-character lookbehind would be cleaner. The escape handling in `STRING` and `CHAR_LIT` re-reads the next byte with `getchar()`, which correctly skips `\"` so a string like `"a\\" // not a comment` stays intact.

```python
from collections import Counter


def kth_most_frequent(items, k):
    if not items:
        raise ValueError("items must be non-empty")
    counts = Counter(items)
    # order of first appearance
    first_seen = {}
    for i, x in enumerate(items):
        first_seen.setdefault(x, i)
    ranked = sorted(counts, key=lambda x: (-counts[x], first_seen[x]))
    if not 1 <= k <= len(ranked):
        raise IndexError(f"k={k} out of range 1..{len(ranked)}")
    return ranked[k - 1]


if __name__ == "__main__":
