        if (p.size() > 1 && p[0] == '0') return false;
        for (char c : p) {
            if (!std::isdigit(static_cast<unsigned char>(c))) return false;
        }
        int n = std::stoi(p);
        if (n < 0 || n > 255) return false;
    }
    return true;
}

