```c
#include <stdio.h>
#include <stdlib.h>

#define MAXN 100000

static int lower[MAXN];  /* max-heap */
static int upper[MAXN];  /* min-heap */
static int ln = 0, un = 0;

static void push_lower(int x) {
    int i = ln++;
    lower[i] = x;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (lower[p] >= lower[i]) break;
        int t = lower[p]; lower[p] = lower[i]; lower[i] = t;
        i = p;
    }
}

static int pop_lower(void) {
    int top = lower[0];
    lower[0] = lower[--ln];
    int i = 0;
    for (;;) {
        int l = 2 * i + 1, r = 2 * i + 2, m = i;
        if (l < ln && lower[l] > lower[m]) m = l;
        if (r < ln && lower[r] > lower[m]) m = r;
        if (m == i) break;
        int t = lower[i]; lower[i] = lower[m]; lower[m] = t;
        i = m;
    }
    return top;
}

static void push_upper(int x) {
    int i = un++;
    upper[i] = x;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (upper[p] <= upper[i]) break;
        int t = upper[p]; upper[p] = upper[i]; upper[i] = t;
        i = p;
    }
}

static int pop_upper(void) {
    int top = upper[0];
    upper[0] = upper[--un];
    int i = 0;
    for (;;) {
        int l = 2 * i + 1, r = 2 * i + 2, m = i;
        if (l < un && upper[l] < upper[m]) m = l;
        if (r < un && upper[r] < upper[m]) m = r;
        if (m == i) break;
        int t = upper[i]; upper[i] = upper[m]; upper[m] = t;
        i = m;
    }
    return top;
}

static void rebalance(void) {
    if (ln > un + 1) {
        push_upper(pop_lower());
    } else if (un > ln + 1) {
        push_lower(pop_upper());
    }
}

int main(void) {
    int x;
    while (scanf("%d", &x) == 1) {
        if (ln == 0 || x <= lower[0]) {
            push_lower(x);
        } else {
            push_upper(x);
        }
        rebalance();
        if (ln == un) {
            printf("%.1f\n", (lower[0] + upper[0]) / 2.0);
        } else if (ln > un) {
            printf("%.1f\n", (double)lower[0]);
        } else {
            printf("%.1f\n", (double)upper[0]);
        }
    }
    return 0;
}
