#include <stdio.h>
#include <string.h>
#include <ctype.h>

static void reverse(char *a, char *b) {
    while (a < b) {
        char t = *a; *a++ = *b; *b-- = t;
    }
}

static void reverse_words(char *s) {
    size_t n = strlen(s);
    /* collapse spaces, trim ends */
    size_t w = 0;
    int in_space = 1;
    for (size_t r = 0; r < n; r++) {
        if (isspace((unsigned char)s[r])) {
            if (!in_space) s[w++] = ' ';
            in_space = 1;
        } else {
            s[w++] = s[r];
            in_space = 0;
        }
    }
    if (w > 0 && s[w - 1] == ' ') w--;
    s[w] = '\0';

    reverse(s, s + w - 1);
    char *start = s;
    for (char *p = s; ; p++) {
        if (*p == ' ' || *p == '\0') {
            reverse(start, p - 1);
            if (*p == '\0') break;
            start = p + 1;
        }
    }
}

int main(void) {
    char buf[] = "  the   quick  brown   fox  ";
    reverse_words(buf);
    printf("[%s]\n", buf);
    return 0;
