from collections import Counter
from typing import Iterator


def iter_lines(path: str, encoding: str = "utf-8") -> Iterator[str]:
    with open(path, "r", encoding=encoding, errors="replace") as fh:
        for line in fh:
            yield line.rstrip("\n")


def word_frequencies(path: str) -> Counter:
    counts: Counter = Counter()
    table = str.maketrans("", "", string.punctuation)
    for line in iter_lines(path):
        for word in line.translate(table).lower().split():
            if word:
                counts[word] += 1
    return counts


if __name__ == "__main__":
    import sys
    path = sys.argv[1] if len(sys.argv) > 1 else "sample.txt"
    try:
        freq = word_frequencies(path)
    except FileNotFoundError:
        print(f"missing: {path}")
        sys.exit(1)
    for word, n in freq.most_common(10):
        print(f"{n:6d}  {word}")
