#include <iostream>
#include <stack>
#include <string>
#include <cstdlib>

int main(int argc, char **argv) {
    std::stack<long long> st;
    for (int i = 1; i < argc; ++i) {
        std::string tok = argv[i];
        if (tok == "+" || tok == "-" || tok == "*" || tok == "/") {
            if (st.size() < 2) { std::cerr << "malformed: not enough operands\n"; return 1; }
            long long b = st.top(); st.pop();
            long long a = st.top(); st.pop();
            if (tok == "+") st.push(a + b);
            else if (tok == "-") st.push(a - b);
            else if (tok == "*") st.push(a * b);
            else {
                if (b == 0) { std::cerr << "division by zero\n"; return 1; }
                st.push(a / b);
            }
        } else {
            char *end = nullptr;
            long long v = std::strtoll(tok.c_str(), &end, 10);
            if (end == tok.c_str() || *end != '\0') { std::cerr << "bad token: " << tok << "\n"; return 1; }
            st.push(v);
        }
    }
    if (st.size() != 1) { std::cerr << "malformed: leftover operands\n"; return 1; }
    std::cout << st.top() << "\n";
    return 0;
}
