        let mut parts = line.split_whitespace();
        let a = match parts.next().and_then(|s| s.parse::<u64>().ok()) {
            Some(v) => v,
            None => continue,
        };
        let b = match parts.next().and_then(|s| s.parse::<u64>().ok()) {
            Some(v) => v,
            None => continue,
        };
        println!("{}", gcd(a, b));
    }
}

