void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;
    for (size_t i = 0, j = len - 1; i < j; i++, j--) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "x";
    char d[] = "ab";
    reverse_in_place(a); reverse_in_place(b);
    reverse_in_place(c); reverse_in_place(d);
    if (strcmp(a, "olleh") != 0) return 1;
    if (strcmp(b, "") != 0) return 1;
    if (strcmp(c, "x") != 0) return 1;
    if (strcmp(d, "ba") != 0) return 1;
    reverse_in_place(NULL); /* must not crash */
    printf("ok\n");
    return 0;
}
