```rust
fn second_largest(values: &[i64]) -> Option<i64> {
    let mut largest: Option<i64> = None;
    let mut second: Option<i64> = None;
    for &v in values {
        match largest {
            None => largest = Some(v),
            Some(l) if v > l => {
                second = Some(l);
                largest = Some(v);
            }
            Some(l) if v < l => {
                if second.map_or(true, |s| v > s) {
                    second = Some(v);
                }
            }
            Some(_) => {} // duplicate of the current largest
        }
    }
    second
}

fn main() {
    assert_eq!(second_largest(&[3, 1, 4, 1, 5, 9, 2, 6]), Some(6));
    assert_eq!(second_largest(&[7, 7, 7]), None);
    assert_eq!(second_largest(&[1]), None);
    assert_eq!(second_largest(&[]), None);
    assert_eq!(second_largest(&[-5, -2, -9]), Some(-5));
    assert_eq!(second_largest(&[2, 2, 3]), Some(2));
    println!("ok");
}
