PAIRS = {")": "(", "]": "[", "}": "{"}
OPEN = set(PAIRS.values())

def is_balanced(s: str) -> bool:
    stack = []
    for ch in s:
        if ch in OPEN:
            stack.append(ch)
        elif ch in PAIRS:
            if not stack or stack.pop() != PAIRS[ch]:
                return False
    return not stack

if __name__ == "__main__":
    cases = {
        "()": True,
        "([{}])": True,
        "([])": True,
        "(": False,
        ")": False,
        "([)]": False,
        "": True,
        "a(b[c]{d})": True,
        "(((": False,
        "}{ ": False,
    }
    for s, want in cases.items():
        got = is_balanced(s)
        assert got == want, (s, got, want)
    print("all checks passed")
