```rust
fn fib_naive(n: u64) -> u128 {
    let (mut a, mut b) = (0u128, 1u128);
    for _ in 0..n {
        let next = a + b;
        a = b;
        b = next;
    }
    a
}

fn fib_pair(n: u64) -> (u128, u128) {
    // returns (F(n), F(n+1))
    if n == 0 {
        return (0, 1);
    }
    let (a, b) = fib_pair(n >> 1);
    let c = a * (2 * b - a);
    let d = a * a + b * b;
    if n & 1 == 0 {
        (c, d)
    } else {
        (d, c + d)
    }
}

fn fib_fast(n: u64) -> u128 {
    fib_pair(n).0
}

fn main() {
    for n in 0..=60u64 {
        assert_eq!(fib_fast(n), fib_naive(n), "mismatch at {n}");
    }
    assert_eq!(fib_fast(90), 2880067194370816120);
    println!("ok");
}
```

Fast doubling uses `F(2k) = F(k)*(2*F(k+1) - F(k))` and `F(2k+1) = F(k)^2 + F(k+1)^2`, recursing on `n >> 1` so it is O(log n). `u128` avoids overflow through n=90, and the loop cross-checks every value against the naive O(n) version.

