#include <limits.h>
#include <stdbool.h>
#include <stdio.h>

bool parse_int(const char *s, int *out) {
    if (s == NULL || out == NULL) return false;
    const char *p = s;
    while (*p == ' ' || *p == '\t') p++;
    bool neg = false;
    if (*p == '+' || *p == '-') { neg = (*p == '-'); p++; }
    if (*p < '0' || *p > '9') return false;
    long long acc = 0;
    for (; *p >= '0' && *p <= '9'; p++) {
        acc = acc * 10 + (*p - '0');
        if (!neg && acc > INT_MAX) return false;
        if (neg && -acc < INT_MIN) return false;
    }
    if (*p != '\0') return false;
    *out = neg ? (int)-acc : (int)acc;
    return true;
}

int main(void) {
    int v;
    if (!parse_int("42", &v) || v != 42) return 1;
    if (!parse_int("  -7", &v) || v != -7) return 1;
    if (!parse_int("+0", &v) || v != 0) return 1;
    if (parse_int("", &v)) return 1;
    if (parse_int("12x", &v)) return 1;
    if (parse_int("x12", &v)) return 1;
    if (parse_int("99999999999999999999", &v)) return 1;
    if (parse_int("2147483648", &v)) return 1;
    if (!parse_int("2147483647", &v) || v != 2147483647) return 1;
    printf("ok\n");
    return 0;
}
```

Accumulation is done in `long long` and bounds-checked against `INT_MAX`/`INT_MIN` after each digit, so overflow can't wrap. Requiring `*p == '\0'` after the digits rejects trailing garbage, and the leading-char check rejects anything that isn't a digit after an optional sign.

