fn kth_smallest(values: &[i32], k: usize) -> Option<(i32, usize)> {
    if k == 0 || k > values.len() {
        return None;
    }
    let mut pool: Vec<i32> = values.to_vec();
    let mut comparisons = 0usize;
    for position in 0..k {
        let mut best = position;
        for i in position + 1..pool.len() {
            comparisons += 1;
            if pool[i] < pool[best] {
                best = i;
            }
        }
        pool.swap(position, best);
    }
    Some((pool[k - 1], comparisons))
}

fn main() {
    assert_eq!(kth_smallest(&[5, 1, 4, 2, 3], 2), Some((2, 9)));
    assert_eq!(kth_smallest(&[], 1), None);
    assert_eq!(kth_smallest(&[7], 1), Some((7, 0)));
    assert_eq!(kth_smallest(&[1, 2], 3), None);
