#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(double value) {
        if (count_ == N) return false;
        data_[(head_ + count_) % N] = value;
        ++count_;
        return true;
    }

    std::optional<double> pop() {
        if (count_ == 0) return std::nullopt;
        double value = data_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return value;
    }

    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == N; }

private:
    std::array<double, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

int main() {
    RingBuffer<2> rb;
    std::cout << rb.empty() << "\n";       // 1
    std::cout << rb.push(1.5) << "\n";     // 1
    std::cout << rb.push(2.5) << "\n";     // 1
    std::cout << rb.full() << "\n";        // 1
    std::cout << rb.push(3.5) << "\n";     // 0
    std::cout << *rb.pop() << "\n";        // 1.5
    std::cout << rb.pop().has_value() << "\n";  // 1
    std::cout << rb.empty() << "\n";       // 1
