```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define BUCKETS 256
#define MAX_WORD 64

typedef struct Entry {
    char word[MAX_WORD];
    unsigned long count;
    struct Entry *next;
} Entry;

static Entry *table[BUCKETS];

static unsigned long hash_word(const char *s) {
    unsigned long h = 5381;
    while (*s) h = h * 33u + (unsigned char)*s++;
    return h % BUCKETS;
}

static void add_word(const char *w) {
    unsigned long idx = hash_word(w);
    for (Entry *e = table[idx]; e; e = e->next) {
        if (strcmp(e->word, w) == 0) { e->count++; return; }
    }
    Entry *e = malloc(sizeof *e);
    if (!e) { perror("malloc"); exit(1); }
    snprintf(e->word, MAX_WORD, "%s", w);
    e->count = 1;
    e->next = table[idx];
    table[idx] = e;
}

int main(void) {
    char buf[MAX_WORD];
    int c, n = 0;
    while ((c = getchar()) != EOF) {
        if (isalpha((unsigned char)c)) {
            if (n < MAX_WORD - 1) buf[n++] = (char)tolower(c);
        } else if (n > 0) {
            buf[n] = '\0';
            add_word(buf);
            n = 0;
        }
    }
    if (n > 0) { buf[n] = '\0'; add_word(buf); }

    const char *best = NULL;
    unsigned long best_n = 0;
    for (int i = 0; i < BUCKETS; i++) {
        for (Entry *e = table[i]; e; e = e->next) {
            if (e->count > best_n) { best_n = e->count; best = e->word; }
        }
    }
    if (best) printf("%s %lu\n", best, best_n);
    return 0;
}
