#[derive(Debug, PartialEq)]
pub enum VersionError {
    Empty,
    NotANumber(String),
    TooFewParts,
    TooManyParts,
}

pub fn parse_version(input: &str) -> Result<(u64, u64, u64), VersionError> {
    let text = input.trim();
    if text.is_empty() {
        return Err(VersionError::Empty);
    }
    let parts: Vec<&str> = text.split('.').collect();
    if parts.len() < 3 {
        return Err(VersionError::TooFewParts);
    }
    if parts.len() > 3 {
        return Err(VersionError::TooManyParts);
    }
    let mut nums = [0u64; 3];
    for (i, part) in parts.iter().enumerate() {
        nums[i] = part
            .parse::<u64>()
            .map_err(|_| VersionError::NotANumber((*part).to_string()))?;
    }
    Ok((nums[0], nums[1], nums[2]))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_valid() {
        assert_eq!(parse_version("1.20.3"), Ok((1, 20, 3)));
        assert_eq!(parse_version(" 0.0.0 "), Ok((0, 0, 0)));
    }

    #[test]
    fn rejects_bad() {
        assert_eq!(parse_version("1.2"), Err(VersionError::TooFewParts));
        assert_eq!(parse_version("a.b.c"), Err(VersionError::NotANumber("a".into())));
        assert_eq!(parse_version(""), Err(VersionError::Empty));
    }
}
```
