template <typename T>
T kth_smallest(std::vector<T> values, std::size_t k) {
    if (values.empty() || k >= values.size()) {
        throw std::out_of_range("k out of range");
    }
    std::nth_element(values.begin(), values.begin() + static_cast<std::ptrdiff_t>(k), values.end());
    return values[k];
}

