int main() {
    std::vector<int> data{9, 1, 8, 2, 7, 3};
    std::cout << kth_smallest(data, 0) << '\n';
    std::cout << kth_smallest(data, 3) << '\n';
    try {
        kth_smallest(data, 99);
    } catch (const std::out_of_range& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
}
