    reverse_in_place(c);
    reverse_in_place(NULL);

    printf("[%s] [%s] [%s]\n", a, b, c);
    return 0;
}
```
Halting the loop at `len / 2` means odd-length strings leave the middle byte untouched, and the `NULL` guard makes the call safe.

```rust
#[derive(Debug, PartialEq)]
pub enum BracketError {
    UnexpectedClose { index: usize, ch: char },
    Mismatch { index: usize, expected: char, found: char },
    Unclosed { open_index: usize, ch: char },
}

pub fn check_brackets(input: &str) -> Result<(), BracketError> {
    let mut stack: Vec<(usize, char)> = Vec::new();
    let close_for = |c: char| match c {
        '(' => Some(')'),
        '[' => Some(']'),
        '{' => Some('}'),
        _ => None,
    };

    for (i, ch) in input.char_indices() {
        match ch {
            '(' | '[' | '{' => stack.push((i, ch)),
            ')' | ']' | '}' => match stack.pop() {
                None => return Err(BracketError::UnexpectedClose { index: i, ch }),
                Some((open_i, open_ch)) => {
                    let expected = close_for(open_ch).unwrap();
                    if expected != ch {
                        return Err(BracketError::Mismatch { index: i, expected, found: ch });
                    }
                }
            },
            _ => {}
        }
    }
    match stack.last() {
        Some(&(open_index, ch)) => Err(BracketError::Unclosed { open_index, ch }),
        None => Ok(()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn cases() {
        assert_eq!(check_brackets("a(b[c]{d})e"), Ok(()));
        assert_eq!(check_brackets("])x"), Err(BracketError::UnexpectedClose { index: 0, ch: ']' }));
        assert_eq!(check_brackets("(])"), Err(BracketError::Mismatch { index: 1, expected: ')', found: ']' }));
    }
}
```
`char_indices` keeps indexes in byte offsets and correct through multibyte characters, and `pop` returns the most recent opener so nesting order is enforced.

```cpp
#include <functional>
#include <iostream>
#include <queue>
#include <vector>

class MedianTracker {
public:
    void add(int value) {
        if (low_.empty() || value <= low_.top()) {
            low_.push(value);
        } else {
            high_.push(value);
        }
        rebalance();
    }

    double median() const {
        if (low_.size() == high_.size()) {
            return (low_.top() + high_.top()) / 2.0;
        }
        return low_.size() > high_.size() ? low_.top() : high_.top();
    }

private:
    std::priority_queue<int> low_;
    std::priority_queue<int, std::vector<int>, std::greater<int>> high_;

    void rebalance() {
        while (low_.size() > high_.size() + 1) {
            high_.push(low_.top());
            low_.pop();
        }
        while (high_.size() > low_.size()) {
            low_.push(high_.top());
            high_.pop();
        }
    }
};

int main() {
    MedianTracker tracker;
    int value;
    while (std::cin >> value) {
        tracker.add(value);
        std::cout << tracker.median() << '\n';
    }
    return 0;
}
```
`low_` is a max-heap holding the smaller half; `high_` a min-heap holding the larger half. `rebalance` keeps their sizes within one, so the median is always at one of the tops and each insertion costs O(log n).

