bool balanced(const std::string& s) {
    const std::unordered_map<char, char> pairs = {{
        {')', '('}, {']', '['}, {'}', '{'}
    }};
    std::stack<char> open;
    for (char c : s) {
        auto it = pairs.find(c);
        if (it != pairs.end()) {
            if (open.empty() || open.top() != it->second) return false;
            open.pop();
        } else if (c == '(' || c == '[' || c == '{') {
            open.push(c);
        }
    }
    return open.empty();
}

