int binary_search(const std::vector<int>& data, int target) {
    std::size_t lo = 0, hi = data.size();
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;  // no overflow
        if (data[mid] == target) return static_cast<int>(mid);
        if (data[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return -1;
}

int main() {
    std::vector<int> v = {1, 3, 5, 8, 13, 21};
    std::cout << binary_search(v, 8) << '\n';   // 3
    std::cout << binary_search(v, 4) << '\n';   // -1
    std::cout << binary_search({}, 1) << '\n';  // -1
    return 0;
