        *counts.entry(word).or_insert(0) += 1;
    }
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    pairs
}

fn main() {
    let text = "The cat, the dog. The DOG!";
    let counts = word_counts(text);
    assert_eq!(counts[0], ("the".to_string(), 3));
    assert_eq!(counts[1], ("dog".to_string(), 2));
    assert_eq!(counts[2], ("cat".to_string(), 1));
    for (word, n) in counts {
        println!("{} {}", word, n);
    }
}
```
`split` on non-alphanumerics drops punctuation, `to_lowercase` normalises case, and the comparator orders by count descending with a tie-break on the word.

