fn search(sorted: &[i32], target: i32) -> Result<usize, usize> {
    let mut lo = 0usize;
    let mut hi = sorted.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if sorted[mid] == target {
            return Ok(mid);
        } else if sorted[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    Err(lo)
}

fn main() {
    let data = [1, 3, 5, 7];
    assert_eq!(search(&data, 5), Ok(2));
    assert_eq!(search(&data, 0), Err(0));
    assert_eq!(search(&data, 6), Err(3));
    assert_eq!(search(&data, 9), Err(4));
    assert_eq!(search(&[], 1), Err(0));
    println!("ok");
}
```
The loop halves a `[lo, hi)` range; on failure `lo` is exactly the index where the target belongs.

