#include <algorithm>
#include <string>

void reverse_words(std::string& text) {
    std::reverse(text.begin(), text.end());
    size_t write = 0, read = 0;
    while (read < text.size()) {
        while (read < text.size() && text[read] == ' ') ++read;
        if (read >= text.size()) break;
        if (write > 0) text[write++] = ' ';
        size_t start = read;
        while (read < text.size() && text[read] != ' ') ++read;
        std::reverse(text.begin() + start, text.begin() + read);
        for (size_t i = start; i < read; ++i) text[write++] = text[i];
    }
    text.resize(write);
}
