#include <iostream>
#include <stdexcept>
#include <vector>

class CircularQueue {
public:
    explicit CircularQueue(size_t capacity)
        : buf_(capacity), head_(0), tail_(0), size_(0), cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == cap_; }

    void enqueue(int value) {
        if (full()) throw std::runtime_error("queue is full");
        buf_[tail_] = value;
        tail_ = (tail_ + 1) % cap_;
        ++size_;
    }

    int dequeue() {
        if (empty()) throw std::runtime_error("queue is empty");
        int value = buf_[head_];
        head_ = (head_ + 1) % cap_;
        --size_;
        return value;
    }

private:
    std::vector<int> buf_;
    size_t head_, tail_, size_, cap_;
};

int main() {
    CircularQueue q(3);
    q.enqueue(1);
    q.enqueue(2);
    q.enqueue(3);
    std::cout << q.full() << '\n';      // 1
    std::cout << q.dequeue() << '\n';   // 1
    std::cout << q.dequeue() << '\n';   // 2
    q.enqueue(4);
    std::cout << q.dequeue() << '\n';   // 3
    std::cout << q.dequeue() << '\n';   // 4
    std::cout << q.empty() << '\n';     // 1
    return 0;
}
