#include <cstdint>
#include <iostream>
#include <stdexcept>

constexpr std::int64_t MOD = 1000000007;

std::int64_t fib_mod(std::int64_t n) {
    if (n < 0) throw std::invalid_argument("n must be non-negative");
    std::int64_t a = 0, b = 1;
    for (std::int64_t i = 0; i < n; ++i) {
        std::int64_t next = (a + b) % MOD;
        a = b;
        b = next;
    }
    return a;
}

int main() {
    if (fib_mod(0) != 0) return 1;
    if (fib_mod(1) != 1) return 1;
    if (fib_mod(10) != 55) return 1;
    if (fib_mod(90) != 2880067194370816120LL % MOD) return 1;
    std::cout << fib_mod(1000000) << "\n";
    return 0;
}
```

The naive recursion overflows the stack around n≈50 and recomputes exponentially. Iteration is O(n) time, O(1) space, and each addition stays under `MOD` so `int64` never overflows. `n < 0` throws instead of looping forever.

```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>

class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    bool push(int value) {
        std::unique_lock<std::mutex> lock(mu_);
        not_full_.wait(lock, [this] { return closed_ || queue_.size() < cap_; });
        if (closed_) return false;
        queue_.push(value);
        not_empty_.notify_one();
        return true;
    }

    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(mu_);
        not_empty_.wait(lock, [this] { return closed_ || !queue_.empty(); });
        if (queue_.empty()) return std::nullopt;
        int value = queue_.front();
        queue_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        closed_ = true;
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::mutex mu_;
    std::condition_variable not_empty_, not_full_;
    std::queue<int> queue_;
    std::size_t cap_;
    bool closed_ = false;
};
```

Predicate-based `wait` guards against spurious wakeups, and `close()` wakes every waiter so producers and consumers can exit cleanly rather than deadlocking on a full/empty queue.

