    pub fn get(&mut self, key: &K) -> Option<&V> {
        if self.map.contains_key(key) {
            let pos = self.order.iter().position(|k| k == key).unwrap();
            let k = self.order.remove(pos).unwrap();
            self.order.push_back(k);
        }
        self.map.get(key)
    }

    pub fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            let pos = self.order.iter().position(|k| k == &key).unwrap();
            self.order.remove(pos);
        } else if self.map.len() == self.cap {
            if let Some(evicted) = self.order.pop_front() {
                self.map.remove(&evicted);
            }
        }
        self.order.push_back(key.clone());
        self.map.insert(key, value);
    }
}
```

Eviction pops the least-recently-used key from the front of the deque and removes it from the map, keeping the two structures consistent. This is O(n) per `get` because of the linear scan; a linked list of indices would make it O(1).

