#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* Reverses s in place. Returns 0 on success, -1 on a null pointer. */
int reverse_string(char *s) {
    if (s == NULL) return -1;
    size_t len = strlen(s);
    for (size_t i = 0; i < len / 2; ++i) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
    return 0;
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "a";
    if (reverse_string(a) != 0 || strcmp(a, "olleh") != 0) return 1;
    if (reverse_string(b) != 0 || strcmp(b, "") != 0) return 1;
    if (reverse_string(c) != 0 || strcmp(c, "a") != 0) return 1;
    if (reverse_string(NULL) != -1) return 1;
    printf("ok\n");
    return 0;
}
```

The swap loop stops at `len / 2`, so the middle character of an odd-length string is untouched and no out-of-bounds read occurs. `strlen` gives the length once; empty and single-character strings are no-ops.

```c
#include <stddef.h>
#include <stdio.h>
#include <string.h>

/* Returns 1 if a and b are anagrams (byte-wise), 0 otherwise. */
int is_anagram(const char *a, const char *b) {
    if (a == NULL || b == NULL) return 0;
    if (strlen(a) != strlen(b)) return 0;

    int counts[256] = {0};
    for (size_t i = 0; a[i] != '\0'; ++i) {
        counts[(unsigned char)a[i]]++;
        counts[(unsigned char)b[i]]--;
    }
    for (size_t i = 0; i < 256; ++i) {
        if (counts[i] != 0) return 0;
    }
    return 1;
}

int main(void) {
    if (!is_anagram("listen", "silent")) return 1;
    if (is_anagram("abc", "abd")) return 1;
    if (!is_anagram("", "")) return 1;
    if (is_anagram("aab", "ab")) return 1;
    printf("ok\n");
    return 0;
}
```

