from typing import Any


def parse_line(line: str) -> dict[str, Any] | None:
    fields: dict[str, Any] = {}
    for token in line.split():
        if "=" not in token:
            continue
        key, _, raw = token.partition("=")
        if not key:
            continue
        if raw.isdigit():
            fields[key] = int(raw)
        else:
