```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

static void reverse_range(char *s, int lo, int hi) {
    while (lo < hi) {
        char t = s[lo];
        s[lo++] = s[hi];
        s[hi--] = t;
    }
}

void reverse_words(char *s) {
    if (s == NULL || *s == '\0') return;
    int n = (int)strlen(s);

    reverse_range(s, 0, n - 1);

    int start = 0;
    for (int i = 0; i <= n; i++) {
        if (i == n || s[i] == ' ') {
            reverse_range(s, start, i - 1);
            start = i + 1;
        }
    }
}

int main(void) {
    char a[] = "the quick brown fox";
    reverse_words(a);
    printf("%s\n", a);          /* fox brown quick the */

    char b[] = "hello";
    reverse_words(b);
    printf("%s\n", b);          /* hello */

    char c[] = "";
    reverse_words(c);
    printf("[%s]\n", c);        /* [] */
    return 0;
}
```

The whole string is reversed first, then each word within it is reversed back, which restores word order while flipping the sentence direction. Two passes plus the inner flips give O(n) time and O(1) space. The empty string and single-word cases fall out naturally because `reverse_range` does nothing when `lo >= hi`.

