fn popcount(mut x: u64) -> u32 {
    let mut count = 0u32;
    while x != 0 {
        x &= x - 1; // clears the lowest set bit
        count += 1;
    }
    count
}

fn main() {
    let cases: [u64; 6] = [0, 1, 2, 7, u64::MAX, 0xFFFF_0000_FFFF_0001];
    for &v in &cases {
        println!("popcount({v:#018x}) = {}", popcount(v));
    }

    assert_eq!(popcount(0), 0);
    assert_eq!(popcount(1), 1);
    assert_eq!(popcount(7), 3);
    assert_eq!(popcount(u64::MAX), 64);
}
```

The `x &= x - 1` idiom clears the lowest set bit on each iteration, so the loop runs exactly once per set bit — O(number of set bits), better than scanning all 64 positions. `u64::MAX` is the edge case that must return 64. In stable Rust you could also use `x.count_ones()`, which compiles to the same `popcnt` instruction on x86-64.

```python
from collections import deque
from typing import Any


class BoundedQueue:
    """FIFO queue that evicts the oldest item once capacity is exceeded."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._items: deque[Any] = deque()

    def push(self, item: Any) -> Any | None:
        """Append item; return the evicted oldest item, or None if none."""
        evicted = None
        if len(self._items) == self._capacity:
            evicted = self._items.popleft()
        self._items.append(item)
        return evicted

    def pop(self) -> Any:
        if not self._items:
            raise IndexError("pop from empty queue")
        return self._items.popleft()

    def __len__(self) -> int:
        return len(self._items)

    def __repr__(self) -> str:
        return f"BoundedQueue(capacity={self._capacity}, items=list(self._items))"


if __name__ == "__main__":
    q = BoundedQueue(3)
    assert q.push(1) is None
    q.push(2)
    q.push(3)
    assert q.push(4) == 1          # 1 is evicted
    assert list(q._items) == [2, 3, 4]
    assert q.pop() == 2
    assert len(q) == 2
    try:
        BoundedQueue(0)
    except ValueError as e:
        print("rejected capacity:", e)
    print("ok")
```

`deque.popleft()` is O(1), so both `push` and `pop` are O(1) amortised, unlike a list where removing the front is O(n). The eviction path only triggers when `len == capacity`, so the queue never grows past its bound, and `ValueError` guards against a nonsensical zero capacity.

