```cpp
#include <algorithm>
#include <iostream>
#include <string>

// Reverse the characters in [begin, end).
static void reverseRange(std::string& s, std::size_t begin, std::size_t end) {
    while (begin < end) {
        std::swap(s[begin], s[--end]);
        ++begin;
    }
}

std::string reverseWords(std::string s) {
    // 1. Reverse the whole string.
    reverseRange(s, 0, s.size());
    // 2. Reverse each word back into order.
    std::size_t i = 0;
    while (i < s.size()) {
        std::size_t j = i;
        while (j < s.size() && s[j] != ' ') ++j;
        reverseRange(s, i, j);
        i = j + 1;
    }
    return s;
}

int main() {
    std::string input;
    std::getline(std::cin, input);
    std::cout << reverseWords(input) << '\n';
    return 0;
}
```

Reversing the whole string puts the words in reverse order with each word backwards; a second pass over each space-delimited token fixes the characters inside them. Empty input produces an empty line. Run: `echo "hello world" | ./a.out` → `world hello`.

