#include <iostream>
#include <stack>
#include <string>

bool isValid(const std::string& s) {
    std::stack<char> open;
    for (char c : s) {
        switch (c) {
            case '(': case '[': case '{':
                open.push(c);
                break;
            case ')': case ']': case '}': {
                if (open.empty()) return false;
                char top = open.top();
                open.pop();
                if ((c == ')' && top != '(') ||
                    (c == ']' && top != '[') ||
                    (c == '}' && top != '{')) {
                    return false;
                }
                break;
            }
            default:
                break;
        }
    }
    return open.empty();
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::cout << (isValid(line) ? "balanced" : "unbalanced") << '\n';
    }
    return 0;
}
```

