fn fib_mod(n: u64) -> u64 {
    if n == 0 {
        return 0;
    }
    let (mut a, mut b) = (0u64, 1u64);
    let mut m = n;
    while m > 0 {
        if m & 1 == 1 {
            let t = (a + b) % MOD;
            a = b;
            b = t;
        } else {
            let t = (a + b) % MOD;
            a = (a * 2 % MOD + MOD - t) % MOD;
            b = (b * 2 % MOD + t) % MOD;
