#include <iostream>
#include <vector>

int binarySearch(const std::vector<int>& a, int target) {
    int lo = 0, hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;  // avoids overflow
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> a = {-5, -1, 0, 3, 7, 9, 12};
    std::cout << binarySearch(a, 7) << "\n";    // 4
    std::cout << binarySearch(a, -5) << "\n";   // 0
    std::cout << binarySearch(a, 12) << "\n";   // 6
    std::cout << binarySearch(a, 4) << "\n";    // -1
    std::cout << binarySearch({}, 1) << "\n";   // -1
    return 0;
}
