#include <string>

std::pair<bool, size_t> balancedBrackets(const std::string& s) {
    std::stack<std::pair<char, size_t>> st;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st.push({c, i});
        } else if (c == ')' || c == ']' || c == '}') {
            char open = c == ')' ? '(' : c == ']' ? '[' : '{';
            if (st.empty() || st.top().first != open) return {false, i};
            st.pop();
        }
    }
    if (!st.empty()) return {false, st.top().second};
    return {true, 0};
}

int main() {
    auto r1 = balancedBrackets("a(b[c]{d})e");
    std::cout << r1.first << "\n";                 // 1
    auto r2 = balancedBrackets("a(b[c)d]");
    std::cout << r2.first << " " << r2.second << "\n"; // 0 6
    auto r3 = balancedBrackets("(((");
    std::cout << r3.first << " " << r3.second << "\n"; // 0 0
    return 0;
}
```
The stack pairs each opener with its index, a mismatched closer reports the closer, and leftover openers report the earliest unclosed one.

