use std::slice;

/// Split `data` into chunks of at most `n` elements.
/// Returns an empty iterator if `data` is empty or `n == 0`.
pub fn chunks_of<T>(data: &[T], n: usize) -> slice::Chunks<'_, T> {
    let size = if n == 0 { usize::MAX } else { n };
    data.chunks(size)
}

fn main() {
    let empty: &[i32] = &[];
    assert_eq!(chunks_of(empty, 3).count(), 0);

    let digits = [1, 2, 3, 4, 5];
    let got: Vec<Vec<i32>> = chunks_of(&digits, 2)
        .map(|c| c.to_vec())
        .collect();
    assert_eq!(got, vec![vec![1, 2], vec![3, 4], vec![5]]);

    assert_eq!(chunks_of(&digits, 0).count(), 1);

    let words = ["a", "b"];
    let joined: Vec<&str> = chunks_of(&words, 1).map(|c| c[0]).collect();
    assert_eq!(joined, vec!["a", "b"]);

    println!("ok");
}
```

Using `usize::MAX` when `n == 0` makes the zero case yield one chunk containing every element instead of panicking; callers who want zero chunks can special-case it. The generic signature keeps it usable for any `T` without copying.

