def is_simple_email(s: str) -> bool:
    """Return True for a single local part, one '@', and one dot in the domain."""
    if not isinstance(s, str) or not s:
        return False
    if s.count("@") != 1:
        return False
    local, _, domain = s.partition("@")
    if not local or not domain:
        return False
    if any(c.isspace() for c in s):
        return False
    labels = domain.split(".")
    if len(labels) < 2:
        return False
    return all(labels) and all(label != "" for label in labels)


if __name__ == "__main__":
