#include <cstddef>
#include <iostream>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), size_(0), head_(0) {}

    void push(double value) {
        data_[head_] = value;
        head_ = (head_ + 1) % data_.size();
        if (size_ < data_.size()) {
            ++size_;
        }
    }

    std::vector<double> lastN(std::size_t n) const {
        if (n > size_) {
            n = size_;
        }
        std::vector<double> out;
        out.reserve(n);
        for (std::size_t i = 0; i < n; ++i) {
            std::size_t idx = (head_ + data_.size() - n + i) % data_.size();
            out.push_back(data_[idx]);
        }
        return out;
    }

private:
    std::vector<double> data_;
    std::size_t size_;
    std::size_t head_;
};

int main() {
    RingBuffer rb(3);
    rb.push(1.0);
    rb.push(2.0);
    rb.push(3.0);
    rb.push(4.0);
    for (double v : rb.lastN(2)) {
        std::cout << v << ' ';
    }
    std::cout << '\n';
    return 0;
}
```

`head_` points at the next slot to overwrite, and `size_` caps at capacity so reads never touch uninitialised slots. `lastN` clamps `n` to the number of stored values and indexes backwards from the head with a modular offset, producing chronological order.

```rust
fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1], &[1]), vec![1, 1, 1]);
    assert_eq!(merge_sorted(&[], &[7]), vec![7]);
    println!("ok");
}
```

The `<=` comparison keeps equal elements stable relative to `a`, and the tail `extend_from_slice` calls drain whichever slice still has elements after one side runs out. `with_capacity` avoids reallocation for the worst case.

