```python
def longest_unique_substring(s: str) -> int:
    last_seen = {}
    start = 0
    best = 0
    for i, ch in enumerate(s):
        if ch in last_seen and last_seen[ch] >= start:
            start = last_seen[ch] + 1
        last_seen[ch] = i
        best = max(best, i - start + 1)
    return best


if __name__ == "__main__":
    cases = [("", 0), ("abcabcbb", 3), ("bbbbb", 1), ("pwwkew", 3), ("\u00e9\u00e9ab", 3)]
    for s, expected in cases:
        got = longest_unique_substring(s)
        assert got == expected, (s, got, expected)
    print("ok")
```

The window start only moves forward, so each character is visited once. The `last_seen[ch] >= start` check is what keeps a stale earlier index from shrinking the window incorrectly.

