```cpp
#include <iostream>
#include <vector>

struct Node {
    int value;
    Node* next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    while (head != nullptr) {
        Node* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

int main() {
    for (const auto& input : std::vector<std::vector<int>>{{}, {1}, {1, 2, 3, 4}}) {
        Node* head = nullptr;
        Node** tail = &head;
        for (int v : input) {
            *tail = new Node(v);
            tail = &(*tail)->next;
        }
        head = reverse(head);
        std::vector<int> got;
        for (Node* p = head; p; p = p->next) got.push_back(p->value);
        std::vector<int> expected(input.rbegin(), input.rend());
        if (got != expected) {
            std::cerr << "mismatch\n";
            return 1;
        }
        while (head) {
            Node* nxt = head->next;
            delete head;
            head = nxt;
        }
    }
    std::cout << "ok\n";
    return 0;
}
```

Three pointers walk the list once: `nxt` saves the rest, the link flips, then both pointers advance. The empty list and single element both fall out correctly with no special cases, and every node is freed.

```cpp
#include <cassert>
#include <cstddef>
#include <iostream>
#include <optional>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), capacity_(capacity) {}

    void push(int v) {
        if (capacity_ == 0) return;
        if (size_ == capacity_) {
            buf_[head_] = v;
            head_ = (head_ + 1) % capacity_;
            return;
        }
        buf_[(head_ + size_) % capacity_] = v;
        ++size_;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int v = buf_[head_];
        head_ = (head_ + 1) % capacity_;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }

private:
    std::vector<int> buf_;
    std::size_t capacity_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer rb(3);
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4); // overwrites 1
    assert(rb.pop() == 2);
    assert(rb.pop() == 3);
    assert(rb.pop() == 4);
    assert(rb.pop() == std::nullopt);
    RingBuffer empty(0);
    empty.push(9);
    assert(empty.pop() == std::nullopt);
    std::cout << "ok\n";
}
```

When full, the write goes to `head_` and then advances `head_`, which is exactly the "drop the oldest" behaviour. Zero capacity is treated as a sink rather than dividing by zero.

