    let cfg = parse_config(text).unwrap();
    assert_eq!(cfg.get("port").map(String::as_str), Some("8080"));
    assert_eq!(cfg.get("name").map(String::as_str), Some("a=b"));
    assert!(parse_config("oops\n").is_err());
    println!("ok");
}
