def rle_encode(s):
    if not s:
        return ""
    out = []
    prev, count = s[0], 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(f"{prev}{count}")
            prev, count = ch, 1
    out.append(f"{prev}{count}")
    return "".join(out)


def rle_decode(s):
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        num = []
        while i < len(s) and s[i].isdigit():
            num.append(s[i])
            i += 1
        if not num:
            raise ValueError(f"missing count after {ch!r} at index {i - 1}")
        out.append(ch * int("".join(num)))
    return "".join(out)


if __name__ == "__main__":
    for s in ["", "a", "aaabbbcccd", "abcd", "wwwwwwwwwwww"]:
        assert rle_decode(rle_encode(s)) == s, s
