use std::collections::HashMap;

/// Length of the longest substring of `s` with no repeated character.
/// Characters are compared by Unicode scalar value.
pub fn longest_unique_substring(s: &str) -> usize {
    let chars: Vec<char> = s.chars().collect();
    let mut last_seen: HashMap<char, usize> = HashMap::new();
    let mut best = 0usize;
    let mut start = 0usize;

    for (i, &c) in chars.iter().enumerate() {
        if let Some(&prev) = last_seen.get(&c) {
            if prev >= start {
                start = prev + 1;
            }
        }
        last_seen.insert(c, i);
        best = best.max(i - start + 1);
    }
    best
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn edge_cases() {
        assert_eq!(longest_unique_substring(""), 0);
        assert_eq!(longest_unique_substring("a"), 1);
        assert_eq!(longest_unique_substring("aaaa"), 1);
    }

    #[test]
    fn typical_cases() {
        assert_eq!(longest_unique_substring("abcabcbb"), 3); // "abc"
        assert_eq!(longest_unique_substring("bbbbb"), 1);
        assert_eq!(longest_unique_substring("pwwkew"), 3); // "wke"
    }

    #[test]
    fn unicode_is_scalar_based() {
        assert_eq!(longest_unique_substring("\u{00e9}\u{00e9}"), 1);
        assert_eq!(longest_unique_substring("\u{4e00}\u{4e01}\u{4e00}"), 2);
    }
}

fn main() {
    for s in ["", "abcabcbb", "pwwkew", "\u{00e9}\u{00e9}"] {
        println!("{:?} -> {}", s, longest_unique_substring(s));
    }
