use std::io::{self, Write};

fn eval(tokens: &[&str]) -> Result<f64, String> {
    let mut stack: Vec<f64> = Vec::new();
    for tok in tokens {
        match *tok {
            "+" | "-" | "*" | "/" => {
                if stack.len() < 2 {
                    return Err(format!("'{tok}' needs two operands"));
                }
                let b = stack.pop().unwrap();
                let a = stack.pop().unwrap();
                let value = match *tok {
                    "+" => a + b,
                    "-" => a - b,
                    "*" => a * b,
                    _ => {
                        if b == 0.0 {
                            return Err("division by zero".to_string());
                        }
                        a / b
                    }
                };
                stack.push(value);
            }
            _ => match tok.parse::<f64>() {
                Ok(n) => stack.push(n),
                Err(_) => return Err(format!("bad token: {tok:?}")),
            },
        }
    }
    if stack.len() != 1 {
        return Err(format!("left {} value(s) on the stack", stack.len()));
    }
    Ok(stack[0])
}

fn main() {
    let stdin = io::stdin();
    print!("rpn> ");
    io::stdout().flush().unwrap();
    for line in stdin.lock().lines() {
        let line = line.unwrap_or_default();
        let tokens: Vec<&str> = line.split_whitespace().collect();
        if tokens.is_empty() {
            continue;
        }
        match eval(&tokens) {
            Ok(v) => println!("= {v}"),
            Err(e) => eprintln!("error: {e}"),
        }
        print!("rpn> ");
        io::stdout().flush().unwrap();
    }
}
