            word.push_back(static_cast<char>(std::tolower(uc)));
        } else if (!word.empty()) {
            ++counts[word];
            word.clear();
        }
    }
    if (!word.empty()) ++counts[word];

    std::vector<std::pair<std::string, int>> ranked(counts.begin(), counts.end());
    std::sort(ranked.begin(), ranked.end(),
              [](const auto& a, const auto& b) {
                  if (a.second != b.second) return a.second > b.second;
                  return a.first < b.first;
              });

    for (std::size_t i = 0; i < ranked.size() && i < 3; ++i)
        std::cout << ranked[i].first << ' ' << ranked[i].second << '\n';
    return 0;
}
```

Reads byte by byte so separators split words correctly, lowercases with `std::tolower` on `unsigned char` to avoid UB on high bytes, and breaks ties alphabetically. Empty input prints nothing.

```rust
fn merge_sorted(a: &[i64], b: &[i64]) -> Vec<i64> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0usize, 0usize);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[], &[]), Vec::<i64>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 3]), vec![1, 1, 1, 2, 3]);
    assert_eq!(merge_sorted(&[-5], &[]), vec![-5]);
    println!("ok");
}
```

The `<=` comparison takes from `a` first so equal elements keep a stable order. `extend_from_slice` drains whichever slice has residue, so duplicates and unequal lengths are handled for free.

```c
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s FILE\n", argv[0]);
        return 2;
    }
    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    char line[256];
    long long min = 0, max = 0, sum = 0, n = 0;
    int bad = 0, have = 0;
    while (fgets(line, sizeof line, fp)) {
        char *end;
        errno = 0;
        long long v = strtoll(line, &end, 10);
        while (*end == ' ' || *end == '\t' || *end == '\r' || *end == '\n') end++;
        if (end == line || *end != '\0' || errno != 0) {
            bad = 1;
            continue;
        }
        if (!have) { min = max = v; have = 1; }
        if (v < min) min = v;
        if (v > max) max = v;
        sum += v;
        n++;
    }
    fclose(fp);

    if (n == 0) {
        printf("no valid integers%s\n", bad ? " (malformed lines present)" : "");
        return 0;
    }
    printf("min=%lld max=%lld mean=%.4f malformed=%s\n",
           min, max, (double)sum / (double)n, bad ? "yes" : "no");
    return 0;
}
```

`strtoll` with an `end` pointer rejects trailing junk, and whitespace is trimmed before checking `*end`. Empty files and files with only bad lines print an explicit message rather than dividing by zero.

