            Err(_) => { eprintln!("skipping malformed line: {line}"); continue; }
        };

        if lo.peek().map_or(true, |&top| v <= top) {
            lo.push(v);
        } else {
            hi.push(Reverse(v));
        }
        if lo.len() > hi.len() + 1 {
            hi.push(Reverse(lo.pop().unwrap()));
        } else if hi.len() > lo.len() {
            lo.push(hi.pop().unwrap().0);
        }

        let median = if lo.len() == hi.len() {
            (*lo.peek().unwrap() + hi.peek().unwrap().0) as f64 / 2.0
        } else {
            *lo.peek().unwrap() as f64
        };
        println!("{median}");
    }
}
