```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    void push(const T& value) {
        data_[head_] = value;
        head_ = (head_ + 1) % N;
        if (size_ < N) ++size_;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        std::size_t idx = (head_ + N - size_) % N;
        T value = data_[idx];
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    rb.push(1); rb.push(2); rb.push(3);
    rb.push(4);                       // overwrites 1
    while (auto v = rb.pop()) std::cout << *v << ' ';
    std::cout << '\n';                // prints 2 3 4
    std::cout << std::boolalpha << rb.empty() << '\n';
    return 0;
}
```

`head_` is the next write slot and `size_` distinguishes an empty buffer from a full one, which `head_ == tail` alone cannot. Push past capacity overwrites the oldest element; pop returns `std::nullopt` when empty.

