use std::collections::HashMap;

fn fib(n: u64, memo: &mut HashMap<u64, u128>) -> u128 {
    if let Some(&v) = memo.get(&n) {
        return v;
    }
    let v = match n {
        0 => 0,
        1 => 1,
        _ => fib(n - 1, memo) + fib(n - 2, memo),
    };
    memo.insert(n, v);
    v
}

fn main() {
    let mut memo = HashMap::new();
    let limit: u128 = 1_000_000;

    let mut first_over = None;
    for n in 0..200u64 {
        let v = fib(n, &mut memo);
        println!("fib({n}) = {v}");
        if v > limit && first_over.is_none() {
            first_over = Some(n);
        }
    }

    match first_over {
        Some(n) => println!("first fib above {limit} is fib({n}) = {}", fib(n, &mut memo)),
        None => println!("no fib below index 200 exceeds {limit}"),
    }
}
```

Memoization turns the exponential recursion into linear time. `u128` avoids overflow well past index 180, and the loop captures the first index that exceeds the limit instead of assuming one exists.

