template <typename T>
T gcd(T a, T b) {
    static_assert(std::is_integral<T>::value, "gcd requires an integral type");
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        T t = a % b;
        a = b;
        b = t;
    }
    return a;
}

