    std::cout << gcd(-48, 18) << '\n';       // 6
    std::cout << gcd(0, 5) << '\n';          // 5
    std::cout << gcd(0, 0) << '\n';          // 0
    std::cout << gcd<int64_t>(123456789, 987654321) << '\n'; // 9
    return 0;
}
