```cpp
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <stdexcept>

class BlockingQueue {
public:
    explicit BlockingQueue(std::size_t capacity) : capacity_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    // Blocks while full. Returns false if the queue was shut down.
    bool push(int value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [this] { return closed_ || queue_.size() < capacity_; });
        if (closed_) return false;
        queue_.push(value);
        not_empty_.notify_one();
        return true;
    }

    // Blocks while empty. Returns nullopt once empty AND closed.
    std::optional<int> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock, [this] { return closed_ || !queue_.empty(); });
        if (queue_.empty()) return std::nullopt;  // closed and drained
        int value = queue_.front();
        queue_.pop();
        not_full_.notify_one();
        return value;
    }

    void close() {
        std::lock_guard<std::mutex> lock(mutex_);
        closed_ = true;
        not_full_.notify_all();
        not_empty_.notify_all();
    }

private:
    std::size_t capacity_;
    std::queue<int> queue_;
    mutable std::mutex mutex_;
    std::condition_variable not_full_, not_empty_;
    bool closed_ = false;
};
```

`push` waits until there is room or the queue closes; `pop` waits until an item exists or the queue is closed and empty. `close()` wakes both waiters so no thread is stranded, and the predicate loops guard against spurious wakeups.

