#include <array>
#include <cstddef>
#include <optional>

class RingBuffer {
public:
    static constexpr std::size_t kCapacity = 8;

    // Overwrites oldest when full. Returns true if an element was dropped.
    bool push(double value) {
        bool overwrote = full();
        buffer_[tail_] = value;
        tail_ = (tail_ + 1) % kCapacity;
        if (overwrote) head_ = (head_ + 1) % kCapacity;
        else ++size_;
        return overwrote;
    }

    std::optional<double> peek() const {
        if (size_ == 0) return std::nullopt;
        return buffer_[head_];
    }

    std::size_t size() const { return size_; }
    bool full() const { return size_ == kCapacity; }

private:
    std::array<double, kCapacity> buffer_{};
    std::size_t head_ = 0, tail_ = 0, size_ = 0;
};
```

The ring is fully stack-allocated, so after construction `push`/`peek` touch no heap. On overflow the oldest element drops and `head_` advances, keeping `peek()` pointed at the oldest surviving value.

```rust
/// Split `data` on b'\n', stripping one trailing b'\r' per line.
/// The final line has no trailing newline. Empty input yields one empty slice.
pub fn split_lines(data: &[u8]) -> Vec<&[u8]> {
    let mut lines = Vec::new();
    let mut start = 0;
    for idx in 0..data.len() {
        if data[idx] == b'\n' {
            let mut end = idx;
            if end > start && data[end - 1] == b'\r' {
                end -= 1;
            }
            lines.push(&data[start..end]);
            start = idx + 1;
        }
    }
    let mut end = data.len();
    if end > start && data[end - 1] == b'\r' {
        end -= 1;
    }
    lines.push(&data[start..end]);
    lines
}

fn main() {
    assert_eq!(split_lines(b""), vec![&b""[..]]);
    assert_eq!(split_lines(b"a\nb\n"), vec![&b"a"[..], &b"b"[..], &b""[..]]);
    assert_eq!(split_lines(b"a\r\nb\r"), vec![&b"a"[..], &b"b"[..]]);
    assert_eq!(split_lines(b"x"), vec![&b"x"[..]]);
    println!("ok");
}
```

The function returns borrowed slices into the input, so it allocates only the `Vec` of slice headers, never the line contents. CR stripping happens before the slice is stored, and the tail line is pushed after the loop.

```rust
use std::collections::HashMap;

/// Return (i, j) with i < j and nums[i] + nums[j] == target, or None.
pub fn two_sum(nums: &[i64], target: i64) -> Option<(usize, usize)> {
    let mut seen: HashMap<i64, usize> = HashMap::with_capacity(nums.len());
    for (j, &value) in nums.iter().enumerate() {
        let need = target - value;
        if let Some(&i) = seen.get(&need) {
            return Some((i, j));
        }
        seen.insert(value, j);
    }
    None
}

fn main() {
    assert_eq!(two_sum(&[2, 7, 11, 15], 9), Some((0, 1)));
    assert_eq!(two_sum(&[3, 3], 6), Some((0, 1)));
    assert_eq!(two_sum(&[1, 2, 3], 100), None);
    assert_eq!(two_sum(&[], 0), None);
    assert_eq!(two_sum(&[5], 5), None);
    println!("ok");
}
```

One pass over the slice: for each element we look up its complement before inserting, so an element can't pair with itself. Duplicates like `[3, 3]` still work because the earlier index is already in the map.

```c
#include <limits.h>
#include <stdio.h>
#include <stddef.h>

/* Write value as decimal into buf (NUL-terminated). Returns chars written.
 * buf must hold at least 12 bytes for a 32-bit int. */
size_t itoa_buf(int value, char *buf) {
    char tmp[12];
    size_t n = 0;
    unsigned int mag;
    int negative = value < 0;

    /* Cast to unsigned via two's complement to survive INT_MIN. */
    mag = negative ? (unsigned int)(-(value + 1)) + 1u : (unsigned int)value;

    do {
        tmp[n++] = (char)('0' + (mag % 10u));
        mag /= 10u;
    } while (mag != 0u);

    size_t out = 0;
    if (negative) buf[out++] = '-';
    while (n > 0) buf[out++] = tmp[--n];
    buf[out] = '\0';
    return out;
}

int main(void) {
    char buf[16];
    itoa_buf(0, buf);     printf("%s\n", buf);
    itoa_buf(-42, buf);   printf("%s\n", buf);
    itoa_buf(INT_MIN, buf); printf("%s (len=%zu)\n", buf, itoa_buf(INT_MIN, buf));
    itoa_buf(INT_MAX, buf); printf("%s\n", buf);
    return 0;
}
```

Digits are produced least-significant first into a temp, then reversed into the caller buffer. Negating through `-(value + 1) + 1` in unsigned arithmetic avoids signed overflow at `INT_MIN`, whose magnitude is not representable as `int`.

```c
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define EMPTY 0
#define LIVE 1
#define DEAD 2

typedef struct {
    char *key;
    int value;
    uint8_t state;
} Slot;

typedef struct {
    Slot *slots;
    size_t cap;
    size_t size;
} Map;

static uint64_t hash_str(const char *s) {
    uint64_t h = 1469598103934665603ULL; /* FNV-1a */
    for (; *s; ++s) { h ^= (unsigned char)*s; h *= 1099511628211ULL; }
    return h;
}

static int map_grow(Map *m);

static size_t probe(const Map *m, const char *key) {
    size_t mask = m->cap - 1;
    size_t i = (size_t)(hash_str(key) & mask);
    while (m->slots[i].state == LIVE && strcmp(m->slots[i].key, key) != 0) {
        i = (i + 1) & mask;
    }
    return (m->slots[i].state == LIVE) ? i : SIZE_MAX;
}

Map *map_new(size_t initial) {
    size_t cap = 8;
    while (cap < initial) cap <<= 1;
    Map *m = calloc(1, sizeof *m);
    if (!m) return NULL;
    m->slots = calloc(cap, sizeof(Slot));
    if (!m->slots) { free(m); return NULL; }
    m->cap = cap;
    return m;
}

int map_put(Map *m, const char *key, int value) {
    if (m->size * 4 >= m->cap * 3) {   /* load factor 0.75 */
        if (map_grow(m) != 0) return -1;
    }
    size_t mask = m->cap - 1;
    size_t i = (size_t)(hash_str(key) & mask);
    size_t first_dead = SIZE_MAX;
    while (m->slots[i].state != EMPTY) {
        if (m->slots[i].state == LIVE && strcmp(m->slots[i].key, key) == 0) {
            m->slots[i].value = value;
            return 0;
        }
        if (m->slots[i].state == DEAD && first_dead == SIZE_MAX) first_dead = i;
        i = (i + 1) & mask;
    }
    if (first_dead != SIZE_MAX) i = first_dead;
    char *copy = strdup(key);
    if (!copy) return -1;
    m->slots[i].key = copy;
    m->slots[i].value = value;
    m->slots[i].state = LIVE;
    m->size++;
    return 0;
}

int map_get(const Map *m, const char *key, int *out) {
    size_t i = probe(m, key);
    if (i == SIZE_MAX) return 0;
    *out = m->slots[i].value;
    return 1;
}

int map_del(Map *m, const char *key) {
    size_t i = probe(m, key);
    if (i == SIZE_MAX) return 0;
    free(m->slots[i].key);
    m->slots[i].key = NULL;
    m->slots[i].state = DEAD;
    m->size--;
    return 1;
}

static int map_grow(Map *m) {
    Map bigger = {0};
    bigger.cap = m->cap << 1;
    bigger.slots = calloc(bigger.cap, sizeof(Slot));
    if (!bigger.slots) return -1;
    for (size_t i = 0; i < m->cap; ++i) {
        if (m->slots[i].state == LIVE) {
            map_put(&bigger, m->slots[i].key, m->slots[i].value);
            free(m->slots[i].key);
        }
    }
    free(m->slots);
    *m = bigger;
    return 0;
}

void map_free(Map *m) {
    if (!m) return;
    for (size_t i = 0; i < m->cap; ++i)
        if (m->slots[i].state == LIVE) free(m->slots[i].key);
    free(m->slots);
    free(m);
}

int main(void) {
    Map *m = map_new(4);
    for (int i = 0; i < 100; ++i) {
        char key[16];
        snprintf(key, sizeof key, "key%d", i);
        if (map_put(m, key, i * 3) != 0) return 1;
    }
    int v = 0;
    if (!map_get(m, "key42", &v) || v != 126) return 1;
    if (map_del(m, "key42") != 1) return 1;
    if (map_get(m, "key42", &v)) return 1;
    if (map_del(m, "key42") != 0) return 1;
    map_free(m);
    puts("ok");
    return 0;
}
```

Open addressing with linear probing and tombstones: deletes mark a slot `DEAD` so probe chains stay intact, and inserts reuse the first dead slot. The table doubles when load passes 0.75, and rehashing skips tombstones while freeing their keys.

