long long gcd_recursive(long long a, long long b) {
    return b == 0 ? std::llabs(a) : gcd_recursive(b, a % b);
}

long long gcd_iterative(long long a, long long b) {
    a = std::llabs(a);
    b = std::llabs(b);
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
