bool parse_int(const char *s, int *out) {
    if (s == NULL || *s == '\0') return false;

    long long acc = 0;
    int sign = 1;

    if (*s == '-' || *s == '+') {
        if (*s == '-') sign = -1;
        ++s;
    }
    if (*s == '\0') return false;

    for (; *s != '\0'; ++s) {
        if (*s < '0' || *s > '9') return false;
        acc = acc * 10 + (*s - '0');
        if (acc > (long long)INT_MAX + 1) return false;
    }

    acc *= sign;
    if (acc < INT_MIN || acc > INT_MAX) return false;

    *out = (int)acc;
    return true;
}

