```c
#include <stdio.h>
#include <stdlib.h>

/* Two heaps: a max-heap for the lower half and a min-heap for the upper
   half, kept within one element of each other so the median is their top. */
typedef struct { int *a; int n; int cap; } Heap;

static void init(Heap *h, int cap) { h->a = malloc(sizeof(int) * cap); h->n = 0; h->cap = cap; }
static void free_heap(Heap *h) { free(h->a); h->a = NULL; h->n = 0; }

static void push(Heap *h, int v, int is_max)
{
    h->a[h->n++] = v;                 /* append then sift up */
    int i = h->n - 1;
    while (i > 0) {
        int parent = (i - 1) / 2;
        int better = is_max ? (h->a[i] > h->a[parent]) : (h->a[i] < h->a[parent]);
        if (!better) break;
        int tmp = h->a[i]; h->a[i] = h->a[parent]; h->a[parent] = tmp;
        i = parent;
    }
}

static int pop(Heap *h, int is_max)
{
    int top = h->a[0];
    h->a[0] = h->a[--h->n];            /* move last element to root */
    int i = 0;
    for (;;) {
        int l = 2 * i + 1, r = 2 * i + 2, best = i;
        if (l < h->n) {
            int better = is_max ? (h->a[l] > h->a[best]) : (h->a[l] < h->a[best]);
            if (better) best = l;
        }
        if (r < h->n) {
            int better = is_max ? (h->a[r] > h->a[best]) : (h->a[r] < h->a[best]);
            if (better) best = r;
        }
        if (best == i) break;
        int tmp = h->a[i]; h->a[i] = h->a[best]; h->a[best] = tmp;
        i = best;
    }
    return top;
}

int main(void)
{
    Heap low, high;
    init(&low, 1 << 20);   /* max-heap, lower half */
    init(&high, 1 << 20);  /* min-heap, upper half */
    int v, ok = 1;

    while (ok != 0) {
        ok = (scanf("%d", &v) == 1);
        if (ok == 0) break;

        if (low.n == 0 || v <= low.a[0]) push(&low, v, 1);
        else                             push(&high, v, 0);

        /* Rebalance: difference never exceeds 1. */
        if (low.n > high.n + 1)            push(&high, pop(&low, 1), 0);
        else if (high.n > low.n)           push(&low, pop(&high, 0), 1);

        if (low.n == high.n)
            printf("%.1f\n", (low.a[0] + high.a[0]) / 2.0);
        else
            printf("%d\n", low.a[0]);
    }

    free_heap(&low);
    free_heap(&high);
    return 0;
}
```

Every new value lands on a side, then the heaps are rebalanced so the lower max-heap holds the median or the two medians. The integer half is printed for an odd count and the average for an even count.

```cpp
#include <algorithm>
#include <cctype>
#include <iostream>
#include <map>
#include <stdexcept>
#include <string>

// Split a single line of key=value pairs on commas that are NOT inside quotes.
static std::vector<std::string> split_pairs(const std::string &line)
{
    std::vector<std::string> out;
    std::string cur;
    bool in_quotes = false;
    for (char c : line) {
        if (c == '"') {
            in_quotes = !in_quotes;
            cur += c;
        } else if (c == ',' && !in_quotes) {
            if (!cur.empty()) out.push_back(cur);
            cur.clear();
        } else {
            cur += c;
        }
    }
    if (!cur.empty()) out.push_back(cur);
    if (in_quotes)
        throw std::runtime_error("unterminated quoted value");
    return out;
}

// key=value, value optionally wrapped in double quotes.
static std::pair<std::string, std::string> parse_pair(const std::string &tok)
{
    auto eq = tok.find('=');
    if (eq == std::string::npos)
        throw std::runtime_error("missing '=' in token: " + tok);
    std::string key = tok.substr(0, eq);
    std::string val = tok.substr(eq + 1);
    while (!key.empty() && std::isspace(static_cast<unsigned char>(key.front()))) key.erase(key.begin());
    while (!key.empty() && std::isspace(static_cast<unsigned char>(key.back())))  key.pop_back();
    while (!val.empty() && std::isspace(static_cast<unsigned char>(val.front()))) val.erase(val.begin());
    while (!val.empty() && std::isspace(static_cast<unsigned char>(val.back())))  val.pop_back();
    if (val.size() >= 2 && val.front() == '"' && val.back() == '"')
        val = val.substr(1, val.size() - 2);   // drop the surrounding quotes
    if (key.empty())
        throw std::runtime_error("empty key");
    return {key, val};
}

int main()
{
    std::string line;
    if (!std::getline(std::cin, line)) {
        std::cerr << "no input\n";
        return 1;
    }
    try {
        std::map<std::string, std::string> kv;   // std::map keeps keys sorted
        for (const auto &tok : split_pairs(line)) {
            auto [k, v] = parse_pair(tok);
            kv[k] = v;
        }
        for (const auto &[k, v] : kv)
            std::cout << k << " = " << v << '\n';
    } catch (const std::exception &e) {
        std::cerr << "error: " << e.what() << '\n';
        return 1;
    }
    return 0;
}
```

The quote-aware splitter keeps `note="hi, there"` intact, and `std::map` gives sorted output for free. An unterminated quote is reported as an error rather than silently accepted.

