// Returns std::nullopt for an empty range so callers cannot read a garbage value.
template <typename T>
std::optional<T> max_or_none(const std::vector<T> &v)
{
    if (v.empty())
        return std::nullopt;
    T best = v[0];
    for (const T &x : v)
        if (x > best)
            best = x;
    return best;
}

int main()
