        std::cout << "max int: " << *m << '\n';
    else
        std::cout << "no numbers\n";

    if (auto m = max_or_none(words))
        std::cout << "max word: " << *m << '\n';

    if (auto m = max_or_none(empty))
        std::cout << "max empty: " << *m << '\n';
    else
        std::cout << "empty input has no maximum\n";
}
