fn is_palindrome(s: &str) -> bool {
    // Collect only the alphanumeric characters, lowercased, into a Vec<char>.
    let chars: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();

    let mut i = 0usize;
    let mut j = chars.len();
    while i + 1 < j {
        j -= 1;
        if chars[i] != chars[j] {
            return false;
        }
        i += 1;
    }
    true
}

fn main() {
    let cases = [
        ("A man, a plan, a canal: Panama", true),
        ("race a car", false),
        ("", true),
        ("一人で", false),
        ("Aa", true),
    ];
    for (input, expected) in cases {
        let got = is_palindrome(input);
        println!("{:>4}  {:?}", got, input);
        assert_eq!(got, expected, "case {:?}", input);
    }
    println!("all cases passed");
}
```

`chars()` iterates over whole Unicode scalar values, `is_alphanumeric` drops punctuation and spaces, and `flat_map(to_lowercase)` handles any character whose lowercase form expands to several `char`s. The `i + 1 < j` loop bound keeps the middle element of an odd-length list from comparing with itself.

