        reversed = reversed * 10 + x % 10;
        x /= 10;
    }
    x == reversed || x == reversed / 10
}

fn main() {
    assert!(is_palindrome(0));
    assert!(is_palindrome(121));
    assert!(is_palindrome(12321));
    assert!(!is_palindrome(-121));
    assert!(!is_palindrome(10));
    println!("ok");
}
```
Reversing only half the number avoids overflow. Negative numbers and trailing-zero positives are rejected before the loop, and the `reversed/10` compare covers odd digit counts.

