struct Node {
    int value;
    std::unique_ptr<Node> next;
    explicit Node(int v) : value(v), next(nullptr) {}
};

std::unique_ptr<Node> reverse(std::unique_ptr<Node> head) {
    std::unique_ptr<Node> prev;
    while (head) {
        auto next = std::move(head->next);
        head->next = std::move(prev);
        prev = std::move(head);
        head = std::move(next);
    }
    return prev;
}

void print(const std::unique_ptr<Node>& head) {
    for (const Node* n = head.get(); n != nullptr; n = n->next.get()) {
        std::cout << n->value;
        if (n->next) std::cout << " -> ";
    }
    std::cout << '\n';
}

int main() {
