    for (int v : {5, 4, 3, 2, 1}) {
        auto n = std::make_unique<Node>(v);
        n->next = std::move(head);
        head = std::move(n);
    }
    print(head);
    head = reverse(std::move(head));
    print(head);
    head = reverse(std::move(head));
    print(head);
    return 0;
