from collections import deque


class RollingAverage:
    """Incremental mean over the last `window` values.

    push() returns the current mean (or None while empty). Non-numeric input
    raises TypeError; a window smaller than 1 raises ValueError.
    """

    def __init__(self, window: int):
        if window < 1:
            raise ValueError("window must be >= 1")
        self.window = window
        self._values = deque()
        self._sum = 0.0

    def push(self, value: float):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("value must be a number")
        self._values.append(float(value))
        self._sum += float(value)
        if len(self._values) > self.window:
            self._sum -= self._values.popleft()
        return self.mean()

    def mean(self):
        if not self._values:
            return None
        return self._sum / len(self._values)

    def __len__(self):
        return len(self._values)


if __name__ == "__main__":
    ra = RollingAverage(3)
    assert ra.mean() is None
    assert ra.push(1) == 1.0
    assert ra.push(2) == 1.5
    assert ra.push(3) == 2.0
    assert ra.push(4) == 3.0
    assert ra.push(5) == 4.0
    try:
        ra.push("x")
    except TypeError as e:
        print("rejected:", e)
