std::string to_binary(long long n) {
    if (n == 0) return "0";

    bool negative = n < 0;
    // Work with the magnitude without overflowing on LLONG_MIN.
    unsigned long long mag = negative
        ? static_cast<unsigned long long>(-(n + 1)) + 1ULL
        : static_cast<unsigned long long>(n);

    std::string bits;
    while (mag > 0) {
        bits.push_back((mag & 1ULL) ? '1' : '0');
        mag >>= 1;
    }
    if (negative) bits.push_back('-');

    std::string out(bits.rbegin(), bits.rend());
    return out;
}

