```python
import threading
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int, on_evict=None):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.on_evict = on_evict
        self._data = OrderedDict()
        self._lock = threading.RLock()

    def get(self, key):
        with self._lock:
            if key not in self._data:
                return None
            self._data.move_to_end(key)
            return self._data[key]

    def put(self, key, value):
        with self._lock:
            if key in self._data:
                self._data.move_to_end(key)
                self._data[key] = value
                return
            self._data[key] = value
            while len(self._data) > self.capacity:
                evicted_key, evicted_value = self._data.popitem(last=False)
                if self.on_evict is not None:
                    self.on_evict(evicted_key, evicted_value)

    def __len__(self):
        with self._lock:
            return len(self._data)
```

`OrderedDict` gives O(1) move-to-end and pop-from-front; the `RLock` makes `get`, `put`, and `len` atomic. The evict callback runs while the lock is held, so keep it fast or dispatch work to a queue if it does I/O.

