    fn valid() {
        assert!(is_balanced("([]{})"));
        assert!(is_balanced(""));
        assert!(is_balanced("abc(def)[ghi]{j}"));
    }

    #[test]
    fn invalid() {
        assert!(!is_balanced("(]"));
        assert!(!is_balanced("((("));
        assert!(!is_balanced(")"));
        assert!(!is_balanced("[(])"));
    }

