```python
#!/usr/bin/env python3
"""Write a sha256 manifest of a directory tree."""
import hashlib
import os
import sys
from pathlib import Path


def file_sha256(path: Path, chunk_size: int = 1 << 20) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        while chunk := f.read(chunk_size):
            h.update(chunk)
    return h.hexdigest()


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        print("usage: manifest.py <directory>", file=sys.stderr)
        return 2
    root = Path(argv[1])
    if not root.is_dir():
        print(f"error: not a directory: {root}", file=sys.stderr)
        return 2

    entries = []
    skipped = 0
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            path = Path(dirpath) / name
            try:
                digest = file_sha256(path)
            except OSError as exc:
                print(f"skipping {path}: {exc}", file=sys.stderr)
                skipped += 1
                continue
            entries.append((str(path.relative_to(root)), digest))

    entries.sort()
    for rel, digest in entries:
        print(f"{digest}  {rel}")

    if skipped:
        print(f"# {skipped} file(s) skipped", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
```

Streams in 1 MiB chunks so large files don't blow memory, walks with `os.walk`, and catches `OSError` per file (permissions, dangling symlinks) to keep going. Output is the standard `hash  path` format, sorted by path.

```cpp
#include <cstddef>
#include <iterator>
#include <stdexcept>
#include <vector>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : buf_(capacity), cap_(capacity), head_(0), size_(0) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push_back(const T& value) {
        std::size_t pos = (head_ + size_) % cap_;
        buf_[pos] = value;
        if (size_ == cap_) {
            head_ = (head_ + 1) % cap_;  // overwrite oldest
        } else {
            ++size_;
        }
    }

    T& at(std::size_t i) {
        if (i >= size_) throw std::out_of_range("ring buffer index");
        return buf_[(head_ + i) % cap_];
    }

    const T& at(std::size_t i) const {
        if (i >= size_) throw std::out_of_range("ring buffer index");
        return buf_[(head_ + i) % cap_];
    }

    std::size_t size() const noexcept { return size_; }
    std::size_t capacity() const noexcept { return cap_; }
    bool empty() const noexcept { return size_ == 0; }

    class Iterator {
    public:
        using iterator_category = std::forward_iterator_tag;
        using value_type = T;
        using difference_type = std::ptrdiff_t;
        using pointer = T*;
        using reference = T&;

        Iterator(RingBuffer* owner, std::size_t index) : owner_(owner), index_(index) {}
        T& operator*() const { return owner_->buf_[(owner_->head_ + index_) % owner_->cap_]; }
        Iterator& operator++() { ++index_; return *this; }
        bool operator==(const Iterator& o) const { return owner_ == o.owner_ && index_ == o.index_; }
        bool operator!=(const Iterator& o) const { return !(*this == o); }
    private:
        RingBuffer* owner_;
        std::size_t index_;
    };

    Iterator begin() { return Iterator(this, 0); }
    Iterator end() { return Iterator(this, size_); }

private:
    std::vector<T> buf_;
    std::size_t cap_, head_, size_;
};
```

When full, `push_back` overwrites the oldest element and advances `head_`. `at` is bounds-checked against logical size and throws `std::out_of_range`; indexing wraps modulo capacity. Iterators yield elements oldest-to-newest. Note: invalidated by further pushes, so use them within a snapshot.

