#include <array>
#include <optional>
#include <cstddef>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (full()) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % N;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (empty()) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }
    std::size_t size() const { return size_; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

