from datetime import datetime, timezone


def seconds_until(target_iso: str, now_iso: str) -> int:
    """Return whole seconds from now_iso to target_iso.

    Both inputs must be ISO-8601 with an explicit offset, e.g.
    '2024-05-01T12:00:00+00:00'.
    """
    def parse(value: str, label: str) -> datetime:
        if not isinstance(value, str) or not value:
            raise ValueError(f"{label} must be a non-empty string")
        try:
            dt = datetime.fromisoformat(value)
        except ValueError as exc:
            raise ValueError(f"{label} is not ISO-8601: {value!r}") from exc
        if dt.tzinfo is None:
            raise ValueError(f"{label} must include a timezone offset: {value!r}")
        return dt.astimezone(timezone.utc)

    target = parse(target_iso, "target")
    now = parse(now_iso, "now")
    return int((target - now).total_seconds())


if __name__ == "__main__":
    assert seconds_until("2024-05-01T12:00:10+00:00", "2024-05-01T12:00:00+00:00") == 10
    assert seconds_until("2024-05-01T11:59:50+00:00", "2024-05-01T12:00:00+00:00") == -10
    assert seconds_until("2024-05-01T14:00:00+02:00", "2024-05-01T12:00:00+00:00") == 0
    for bad in ["", "not-a-date", "2024-05-01T12:00:00"]:
        try:
            seconds_until(bad, "2024-05-01T12:00:00+00:00")
        except ValueError:
            pass
        else:
            raise AssertionError(f"expected ValueError for {bad!r}")
    print("all tests passed")
