#include <vector>

template <typename T>
class BlockingQueue {
public:
    explicit BlockingQueue(std::size_t capacity) : capacity_(capacity) {}

    // Returns false if the queue is closed (no space will free up).
    bool push(T value) {
        std::unique_lock<std::mutex> lock(mutex_);
        not_full_.wait(lock, [this] { return closed_ || queue_.size() < capacity_; });
        if (closed_) return false;
        queue_.push_back(std::move(value));
        not_empty_.notify_one();
        return true;
    }

    // Returns nullopt once the queue is closed and drained.
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        not_empty_.wait(lock, [this] { return closed_ || !queue_.empty(); });
        if (queue_.empty()) return std::nullopt;
        T value = std::move(queue_.front());
        queue_.pop_front();
        not_full_.notify_one();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::size_t capacity_;
    std::deque<T> queue_;
    bool closed_ = false;
    std::mutex mutex_;
    std::condition_variable not_empty_, not_full_;
};

int main() {
    BlockingQueue<int> q(4);
    std::vector<int> received;

    std::thread producer([&] {
        for (int i = 1; i <= 50; ++i) q.push(i);
        q.close();
    });

    std::thread consumer([&] {
        while (auto v = q.pop()) received.push_back(*v);
    });

    producer.join();
    consumer.join();

    if (received.size() != 50) {
        std::cerr << "wrong count: " << received.size() << "\n";
        return 1;
    }
    for (std::size_t i = 0; i < received.size(); ++i) {
        if (received[i] != static_cast<int>(i) + 1) {
            std::cerr << "order violated at " << i << "\n";
            return 1;
        }
    }
    std::cout << "all tests passed\n";
    return 0;
}
