// Levenshtein distance over UTF-8 code points.
// Encoding-agnostic if both inputs use the same encoding (compare by code point).
#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

// Decode UTF-8 to a vector of code points; invalid bytes become 0xFFFD.
static std::vector<uint32_t> decode_utf8(const std::string& s) {
    std::vector<uint32_t> out;
    for (std::size_t i = 0; i < s.size();) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        uint32_t cp; int extra;
        if (c < 0x80)        { cp = c;        extra = 0; }
        else if ((c >> 5) == 0x6) { cp = c & 0x1F; extra = 1; }
        else if ((c >> 4) == 0xE) { cp = c & 0x0F; extra = 2; }
        else if ((c >> 3) == 0x1E){ cp = c & 0x07; extra = 3; }
        else                 { out.push_back(0xFFFD); ++i; continue; }
        if (i + extra >= s.size()) { out.push_back(0xFFFD); break; }
        for (int k = 0; k < extra; ++k) {
            unsigned char cc = static_cast<unsigned char>(s[i + 1 + k]);
            if ((cc >> 6) != 0x2) { cp = 0xFFFD; break; }
            cp = (cp << 6) | (cc & 0x3F);
        }
        out.push_back(cp);
        i += extra + 1;
    }
    return out;
}

static std::size_t levenshtein(const std::string& a, const std::string& b) {
    auto x = decode_utf8(a);
    auto y = decode_utf8(b);
    std::vector<std::size_t> prev(y.size() + 1), cur(y.size() + 1);
    for (std::size_t j = 0; j <= y.size(); ++j) prev[j] = j;
    for (std::size_t i = 1; i <= x.size(); ++i) {
        cur[0] = i;
        for (std::size_t j = 1; j <= y.size(); ++j) {
            std::size_t cost = (x[i - 1] == y[j - 1]) ? 0 : 1;
            cur[j] = std::min({prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost});
        }
        std::swap(prev, cur);
    }
    return prev[y.size()];
}

int main() {
    struct Case { const char* a; const char* b; std::size_t want; };
    std::vector<Case> cases = {
        {"kitten", "sitting", 3},
        {"", "abc", 3},
        {"abc", "", 3},
        {"", "", 0},
        {"caf\xC3\xA9", "cafe", 1},   // café vs cafe -> 1 substitution
        {"\xE6\x97\xA5\xE6\x9C\xAC", "\xE6\x97\xA5\xE6\x9C\xA8", 1}, // 日本 vs 日本-ish
    };
    for (auto& c : cases) {
        auto got = levenshtein(c.a, c.b);
        if (got != c.want) {
            std::cerr << "fail: dist(" << c.a << ", " << c.b << ") = " << got
                      << ", want " << c.want << "\n";
            return 1;
        }
    }
    std::cout << "all tests passed\n";
    return 0;
}
