// Recursive-descent expression evaluator.
// Grammar:
//   expr   := term (('+' | '-') term)*
//   term   := factor (('*' | '/') factor)*
//   factor := number | '(' expr ')' | ('+'|'-') factor

pub fn eval(input: &str) -> Result<f64, String> {
    let bytes: Vec<char> = input.chars().collect();
    let mut pos = 0usize;
    let value = parse_expr(&bytes, &mut pos)?;
    skip_ws(&bytes, &mut pos);
    if pos != bytes.len() {
        return Err(format!("unexpected character {:?} at {}", bytes[pos], pos));
    }
    Ok(value)
}

fn skip_ws(b: &[char], p: &mut usize) {
    while *p < b.len() && b[*p].is_whitespace() {
        *p += 1;
    }
}

fn parse_expr(b: &[char], p: &mut usize) -> Result<f64, String> {
    let mut acc = parse_term(b, p)?;
    loop {
        skip_ws(b, p);
        match b.get(*p) {
            Some('+') => { *p += 1; acc += parse_term(b, p)?; }
            Some('-') => { *p += 1; acc -= parse_term(b, p)?; }
            _ => return Ok(acc),
        }
    }
}

fn parse_term(b: &[char], p: &mut usize) -> Result<f64, String> {
    let mut acc = parse_factor(b, p)?;
    loop {
        skip_ws(b, p);
        match b.get(*p) {
            Some('*') => { *p += 1; acc *= parse_factor(b, p)?; }
            Some('/') => {
                *p += 1;
                let rhs = parse_factor(b, p)?;
                if rhs == 0.0 {
                    return Err("division by zero".to_string());
                }
                acc /= rhs;
            }
            _ => return Ok(acc),
        }
    }
}

fn parse_factor(b: &[char], p: &mut usize) -> Result<f64, String> {
    skip_ws(b, p);
    match b.get(*p) {
        Some('+') => { *p += 1; parse_factor(b, p) }
        Some('-') => { *p += 1; Ok(-parse_factor(b, p)?) }
        Some('(') => {
            *p += 1;
            let v = parse_expr(b, p)?;
            skip_ws(b, p);
            if b.get(*p) == Some(&')') {
                *p += 1;
                Ok(v)
            } else {
                Err("missing closing ')'".to_string())
            }
        }
        Some(c) if c.is_ascii_digit() || *c == '.' => {
            let start = *p;
            while *p < b.len() && (b[*p].is_ascii_digit() || b[*p] == '.') {
                *p += 1;
            }
            let s: String = b[start..*p].iter().collect();
            s.parse::<f64>().map_err(|_| format!("bad number {s:?}"))
        }
        Some(c) => Err(format!("unexpected character {c:?}")),
        None => Err("unexpected end of input".to_string()),
    }
}

#[cfg(test)]
mod tests {
    use super::eval;

    #[test]
    fn basic() {
        assert!((eval("1 + 2 * 3").unwrap() - 7.0).abs() < 1e-9);
        assert!((eval("(1 + 2) * 3").unwrap() - 9.0).abs() < 1e-9);
        assert!((eval("-4 + 10 / 2").unwrap() - 1.0).abs() < 1e-9);
        assert!((eval("2 * (3 + (4 - 1))").unwrap() - 12.0).abs() < 1e-9);
    }

    #[test]
    fn errors() {
        assert!(eval("1 / 0").is_err());
        assert!(eval("(1 + 2").is_err());
        assert!(eval("1 + * 2").is_err());
        assert!(eval("").is_err());
    }
}

fn main() {
    let cases = ["1 + 2 * 3", "(1 + 2) * 3", "-4 + 10 / 2", "2 * (3 + (4 - 1))"];
    for c in cases {
        println!("{c} = {}", eval(c).unwrap());
    }
    println!("1 / 0 -> {:?}", eval("1 / 0"));
}
