// Cycle detection with the tortoise-and-hare algorithm.
use std::collections::HashSet;

#[derive(Debug)]
struct Node<T> {
    value: T,
    next: Option<Box<Node<T>>>,
}

pub struct List<T> {
    head: Option<Box<Node<T>>>,
    len: usize,
}

impl<T> List<T> {
    pub fn new() -> Self {
        List { head: None, len: 0 }
    }

    pub fn push_front(&mut self, value: T) {
        let node = Box::new(Node { value, next: self.head.take() });
        self.head = Some(node);
        self.len += 1;
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    // Floyd's algorithm: O(n) time, O(1) space. Consumes nothing.
    pub fn has_cycle(&self) -> bool {
        let mut slow = self.head.as_deref();
        let mut fast = self.head.as_deref();
        loop {
            fast = match fast.and_then(|n| n.next.as_deref()) {
                Some(n) => Some(n),
                None => return false,
            };
            fast = match fast.and_then(|n| n.next.as_deref()) {
                Some(n) => Some(n),
                None => return false,
            };
            slow = slow.and_then(|n| n.next.as_deref());
            if std::ptr::eq(slow.unwrap(), fast.unwrap()) {
                return true;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::List;

    #[test]
    fn acyclic() {
        let mut l = List::new();
        for i in 0..5 {
            l.push_front(i);
        }
        assert_eq!(l.len(), 5);
        assert!(!l.has_cycle());
    }

    #[test]
    fn empty() {
        let l: List<i32> = List::new();
        assert!(l.is_empty());
        assert!(!l.has_cycle());
    }
}

fn main() {
    let mut l = List::new();
    for i in 0..6 {
        l.push_front(i);
    }
    println!("len = {}, has_cycle = {}", l.len(), l.has_cycle());
    // Because the list is owned by Box, creating a real cycle in safe Rust
    // requires interior mutability; Floyd's check above stays valid either way.
    let _ = HashSet::<i32>::new();
}
