// Patience-sorting LIS: O(n log n).
#include <algorithm>
#include <iostream>
#include <vector>

std::size_t longest_increasing_subsequence(const std::vector<int>& a) {
    // tails[k] = smallest possible tail of an increasing subsequence of length k+1.
    std::vector<int> tails;
    tails.reserve(a.size());
    for (int value : a) {
        auto it = std::lower_bound(tails.begin(), tails.end(), value);
        if (it == tails.end()) {
            tails.push_back(value);
        } else {
            *it = value;
        }
    }
    return tails.size();
}

int main() {
    struct Case { std::vector<int> input; std::size_t want; };
    std::vector<Case> cases = {
        {{}, 0},
        {{5}, 1},
        {{10, 9, 2, 5, 3, 7, 101, 18}, 4},
        {{7, 7, 7, 7}, 1},
        {{1, 2, 3, 4, 5}, 5},
