long long sum_csv(const std::string& line) {
    long long total = 0;
    std::stringstream ss(line);
    std::string token;
    while (std::getline(ss, token, ',')) {
        try {
            size_t pos = 0;
            long long value = std::stoll(token, &pos);
            if (pos != token.size()) continue;  // trailing junk
            total += value;
        } catch (const std::exception&) {
            // skip malformed token
        }
    }
    return total;
}

