fn encode(data: &[u8]) -> Vec<(u8, u32)> {
    let mut out = Vec::new();
    let mut iter = data.iter().copied();
    if let Some(mut cur) = iter.next() {
        let mut run = 1u32;
        for b in iter {
            if b == cur {
                run += 1;
            } else {
                out.push((cur, run));
                cur = b;
                run = 1;
            }
        }
        out.push((cur, run));
    }
    out
}

fn decode(encoded: &[(u8, u32)]) -> Vec<u8> {
    let mut out = Vec::new();
    for &(b, n) in encoded {
        for _ in 0..n {
            out.push(b);
        }
    }
    out
}

fn main() {
    let data: &[u8] = b"aaabbbcccd";
    assert_eq!(encode(data), vec![(b'a', 3), (b'b', 3), (b'c', 3), (b'd', 1)]);
    assert_eq!(decode(&encode(data)), data.to_vec());
    assert_eq!(encode(&[]), Vec::new());
    assert_eq!(decode(&[]), Vec::new());
    println!("round-trip ok");
}
