int reverse_in_place(char *s) {
    if (s == NULL) {
        return 0;
    }
    size_t len = strlen(s);
    for (size_t i = 0; i < len / 2; ++i) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
    return 1;
