`std::from_chars` is the clean way — it doesn't throw and tells you exactly where parsing stopped.

```cpp
#include <charconv>
#include <optional>
#include <string_view>
#include <iostream>

std::optional<int> parse_int(std::string_view s) {
    if (s.empty()) return std::nullopt;
    int value = 0;
    auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), value);
    if (ec != std::errc() || ptr != s.data() + s.size()) {
        return std::nullopt;
    }
    return value;
}

int main() {
    for (std::string_view s : {"42", "-7", "", "12x", "999999999999"}) {
        auto v = parse_int(s);
        std::cout << '"' << s << "\" -> "
                  << (v ? std::to_string(*v) : "invalid") << '\n';
    }
}
```

Overflow sets `ec` to `result_out_of_range`, so `999999999999` is rejected rather than wrapped. Trailing junk like `12x` also fails because `ptr` must reach the end.

Using checked arithmetic keeps it honest about overflow instead of silently wrapping.

```rust
fn fib(n: u32) -> Result<u64, &'static str> {
    let mut a: u64 = 0;
    let mut b: u64 = 1;
    for _ in 0..n {
        let next = a.checked_add(b).ok_or("fibonacci overflowed u64")?;
        a = b;
        b = next;
    }
    Ok(a)
}

fn main() {
    for n in [0u32, 1, 10, 93, 94] {
        match fib(n) {
            Ok(v) => println!("fib({n}) = {v}"),
            Err(e) => println!("fib({n}) error: {e}"),
        }
    }
}
```

`fib(0)` is `0`, `fib(1)` is `1`, and `fib(93)` fits in `u64` while `fib(94)` overflows and returns the error.

