/* Returns 1 if the string was truncated, 0 if it fit. */
int copy_into(char *dst, size_t dst_size, const char *src) {
    if (dst_size == 0) {
        return src[0] != '\0';
    }
    size_t i = 0;
    while (i + 1 < dst_size && src[i] != '\0') {
        dst[i] = src[i];
        i++;
    }
    dst[i] = '\0';
    return src[i] != '\0';
}

int main(void) {
    char buf[8];
    const char *tests[] = {"hi", "abcdefg", "abcdefghij", ""};
