```cpp
#include <cassert>
#include <cstdint>
#include <iostream>
#include <utility>

constexpr std::int64_t MOD = 1'000'000'007;

std::pair<std::int64_t, std::int64_t> fib_pair(std::int64_t n) {
    if (n == 0) {
        return {0, 1};
    }
    auto [a, b] = fib_pair(n >> 1);
    std::int64_t c = a * ((2 * b - a + MOD) % MOD) % MOD;
    std::int64_t d = (a * a + b * b) % MOD;
    if (n & 1) {
        return {d, (c + d) % MOD};
    }
    return {c, d};
}

std::int64_t fib_mod(std::int64_t n) {
    return fib_pair(n).first;
}

int main() {
    assert(fib_mod(0) == 0);
    assert(fib_mod(1) == 1);
    assert(fib_mod(10) == 55);
    assert(fib_mod(50) == 586268941);
    assert(fib_mod(100) == 687995182);
    std::cout << "ok\n";
}
```
