```python
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self) -> int:
        return len(self._data)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put("a", 1)
    c.put("b", 2)
    assert c.get("a") == 1
    c.put("c", 3)          # evicts "b"
    assert c.get("b") is None
    c.put("a", 99)         # update, refresh recency
    assert c.get("a") == 99
    c.put("d", 4)          # evicts "c"
    assert c.get("c") is None
    assert len(c) == 2
    print("ok")
```
`OrderedDict.move_to_end` marks a key as most-recently used on every access, and `popitem(last=False)` removes the least-recently used in O(1). Updating an existing key also refreshes its position before inserting the new value.

