fn longest_common_prefix(words: &[String]) -> String {
    let first = match words.first() {
        Some(w) => w,
        None => return String::new(),
    };
    let mut end = first.len();
    for word in &words[1..] {
        end = end.min(word.len());
        let mut i = 0;
        let bytes_a = first.as_bytes();
        let bytes_b = word.as_bytes();
        while i < end && bytes_a[i] == bytes_b[i] {
            i += 1;
        }
        end = i;
        if end == 0 {
            break;
        }
    }
    first[..end].to_string()
}

fn main() {
    let words = vec!["flower".to_string(), "flow".to_string(), "flight".to_string()];
    assert_eq!(longest_common_prefix(&words), "fl");
    assert_eq!(longest_common_prefix(&[]), "");
    println!("{}", longest_common_prefix(&words));
}
