    std::size_t i = 0;
    std::size_t j = text.size();
    while (i < j) {
        if (j == 0) break;
        --j;
        char left = text[i];
        char right = text[j];
        if (!std::isalnum(static_cast<unsigned char>(left))) { ++i; ++j; continue; }
        if (!std::isalnum(static_cast<unsigned char>(right))) { ++i; continue; }
        char l = static_cast<char>(std::tolower(static_cast<unsigned char>(left)));
        char r = static_cast<char>(std::tolower(static_cast<unsigned char>(right)));
        if (l != r) return false;
        ++i;
    }
    return true;
}

