def fib_fast(n):
    """Return (F(n), F(n+1)) using fast doubling."""
    if n == 0:
        return (0, 1)
    a, b = fib_fast(n >> 1)
    c = a * (2 * b - a)
    d = a * a + b * b
    if n & 1:
        return (d, c + d)
    return (c, d)


def fib_naive(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


if __name__ == "__main__":
    for n in range(30):
        assert fib_fast(n)[0] == fib_naive(n)
    assert fib_fast(100)[0] == 354224848179261915075
