```cpp
#include <cstddef>
#include <optional>
#include <vector>

class CircularBuffer {
public:
    explicit CircularBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), size_(0) {}

    bool push(int value) {
        if (size_ == buf_.size()) return false;
        buf_[(head_ + size_) % buf_.size()] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return value;
    }

    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == buf_.size(); }
    std::size_t size() const { return size_; }

private:
    std::vector<int> buf_;
    std::size_t head_;
    std::size_t size_;
};
```
I use a `size_` counter instead of head/tail equality, so a full buffer and an empty one are distinguishable. `pop` on empty returns `std::nullopt` rather than an undefined read. Zero capacity means `push` always fails and `pop` always returns empty, which is consistent.

