type Link = Option<Box<Node>>;

struct Node {
    value: i32,
    next: Link,
}

fn reverse(mut head: Link) -> Link {
    let mut prev: Link = None;
    while let Some(mut node) = head {
        head = node.next.take();
        node.next = prev;
        prev = Some(node);
    }
    prev
}

#[cfg(test)]
mod tests {
    use super::*;

    fn build(vals: &[i32]) -> Link {
        let mut head: Link = None;
        for &v in vals.iter().rev() {
            head = Some(Box::new(Node { value: v, next: head }));
        }
        head
    }

    fn collect(mut head: Link) -> Vec<i32> {
        let mut out = Vec::new();
        while let Some(node) = head {
            out.push(node.value);
            head = node.next;
        }
        out
    }

    #[test]
    fn reverses() {
        assert_eq!(collect(reverse(build(&[1, 2, 3, 4]))), vec![4, 3, 2, 1]);
        assert_eq!(collect(reverse(build(&[]))), Vec::<i32>::new());
        assert_eq!(collect(reverse(build(&[7]))), vec![7]);
    }
}
