#include <stdio.h>
#include <ctype.h>

int is_palindrome(const char *s) {
    if (s == NULL) return 0;
    const char *left = s;
    const char *right = s;
    while (*right) right++;          // point one past the last char
    if (right == left) return 1;     // empty string is a palindrome
    right--;

    while (left < right) {
        while (left < right && !isalnum((unsigned char)*left)) left++;
        while (left < right && !isalnum((unsigned char)*right)) right--;
        if (tolower((unsigned char)*left) != tolower((unsigned char)*right))
            return 0;
        left++;
        right--;
    }
    return 1;
}

int main(void) {
    const char *tests[] = {
        "A man, a plan, a canal: Panama",
        "race a car",
        "",
        "!!!",
        "No 'x' in Nixon",
    };
    for (int i = 0; i < 5; i++)
        printf("%-35s -> %d\n", tests[i], is_palindrome(tests[i]));
    return 0;
}
```
Casting to `unsigned char` before `isalnum`/`tolower` avoids undefined behaviour with high-bit bytes. Two pointers skip punctuation and compare lowercased alphanumerics; an empty or all-punctuation string returns 1, which is the usual convention.

```python
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 0:
            raise ValueError("capacity must be >= 0")
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return -1
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value) -> None:
        if self.capacity == 0:
            return
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)  # evict least-recently used

if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, 1)
    c.put(2, 2)
    assert c.get(1) == 1
    c.put(3, 3)              # evicts key 2
    assert c.get(2) == -1
    assert list(c._data) == [1, 3]
    assert LRUCache(0).get(5) == -1
    print("ok")
```
`OrderedDict.move_to_end` on every access keeps the ordering as recency, so eviction is just `popitem(last=False)`. A capacity of zero makes `put` a no-op and `get` always miss, which matches the standard contract.

```cpp
#include <queue>
#include <mutex>
#include <condition_variable>
#include <optional>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {}

    void push(T value) {
        std::unique_lock<std::mutex> lock(m_);
        not_full_.wait(lock, [this] { return q_.size() < cap_; });
        q_.push(std::move(value));
        lock.unlock();
        not_empty_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(m_);
        not_empty_.wait(lock, [this] { return !q_.empty(); });
        T value = std::move(q_.front());
        q_.pop();
        lock.unlock();
        not_full_.notify_one();
        return value;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(m_);
        return q_.empty();
    }

private:
    std::queue<T> q_;
    std::size_t cap_;
    mutable std::mutex m_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
};
```
Both waits use a predicate so they re-check the condition after spurious wakeups. The `notify_*` calls happen after `lock.unlock()` to avoid waking a thread that immediately re-blocks on the still-held mutex. `empty()` takes the mutex because `std::queue` is not safe for concurrent reads during mutation.

