use std::fs::File;
use std::io::{self, Read};

fn count_pattern(path: &str, pattern: &[u8]) -> io::Result<usize> {
    if pattern.is_empty() {
        return Ok(0);
    }
    let mut file = File::open(path)?;
    let mut buf = Vec::new();
    file.read_to_end(&mut buf)?;
    let mut count = 0;
    let window = pattern.len();
    if buf.len() >= window {
        for i in 0..=buf.len() - window {
            if &buf[i..i + window] == pattern {
                count += 1;
            }
        }
    }
    Ok(count)
}

fn main() -> io::Result<()> {
    let path = "sample.bin";
    std::fs::write(path, b"abcabcabcdabc")?;
    assert_eq!(count_pattern(path, b"abc")?, 4);
    assert_eq!(count_pattern(path, b"z")?, 0);
    assert_eq!(count_pattern(path, b"")?, 0);
    std::fs::remove_file(path)?;
    println!("ok");
    Ok(())
}
```
The whole file is read into a `Vec<u8>` so the byte window can compare slices directly, and matches are allowed to overlap (the next start is `i + 1`). An empty pattern returns 0 instead of looping forever, and short files are guarded by the `buf.len() >= window` check.

