// Reverse [lo, hi) in place.
static void reverse_range(std::vector<int>& v, std::size_t lo, std::size_t hi) {
    while (lo < hi) {
        --hi;
        if (lo >= hi) break;
        std::swap(v[lo], v[hi]);
        ++lo;
    }
}

void rotate_right(std::vector<int>& v, int k) {
    const std::size_t n = v.size();
    if (n == 0) return;
    std::size_t shift = static_cast<std::size_t>(((k % static_cast<int>(n)) + static_cast<int>(n)) % static_cast<int>(n));
    if (shift == 0) return;
    reverse_range(v, 0, n);
    reverse_range(v, 0, shift);
    reverse_range(v, shift, n);
}

int main() {
    std::vector<int> a{1, 2, 3, 4, 5};
    rotate_right(a, 2);
    for (int x : a) std::cout << x << ' ';
    std::cout << '\n';  // 4 5 1 2 3

    std::vector<int> empty;
    rotate_right(empty, 7);
    std::cout << "empty size=" << empty.size() << '\n';
}
