/// Return the n-th Fibonacci number (F(0) = 0, F(1) = 1).
///
/// Swap-free iterative accumulation: O(n) time, O(1) space.
/// Panics via checked arithmetic once the result exceeds u64::MAX
/// (F(93) is the largest value that fits in u64).
fn fibonacci(n: u32) -> u64 {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let next = a.checked_add(b).expect("fibonacci overflows u64");
        a = b;
        b = next;
    }
    a
}

fn main() {
    assert_eq!(fibonacci(0), 0);
    assert_eq!(fibonacci(1), 1);
    assert_eq!(fibonacci(10), 55);
    assert_eq!(fibonacci(93), 12200160415121876738);
    println!("{} {} {}", fibonacci(0), fibonacci(1), fibonacci(93));
}
