            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 2]), vec![1, 1, 1, 2, 2]);
    assert_eq!(merge_sorted(&[-5, 0], &[-3]), vec![-5, -3, 0]);
    assert_eq!(merge_sorted(&[7], &[]), vec![7]);
    println!("all merges ok");
}
```

Using `<=` on ties keeps equal elements stable left-to-right. The two `extend_from_slice` calls drain whichever input still has items, so no bounds check runs past the end. Empty vectors on either side work, and the capacity hint avoids reallocation for the common case.

```rust
fn fib_checked(n: u32) -> Result<u64, String> {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let next = a.checked_add(b).ok_or_else(|| format!("overflow at step {}", n))?;
        a = b;
        b = next;
    }
    Ok(a)
}

fn main() {
    assert_eq!(fib_checked(0), Ok(0));
    assert_eq!(fib_checked(1), Ok(1));
    assert_eq!(fib_checked(10), Ok(55));
    assert_eq!(fib_checked(93), Ok(12200160415121876738));
    assert!(fib_checked(94).is_err());
    println!("fib_checked(93) = {:?}", fib_checked(93));
    println!("fib_checked(94) = {:?}", fib_checked(94));
}
```

`checked_add` returns `None` the moment the sum would exceed `u64::MAX`, so `fib_checked(93)` is the last representable value and 94 fails cleanly. The error carries the step number rather than a bare "overflow" string, which makes debugging easier. Using `ok_or_else` avoids building the message on the success path.

```c
#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    if (len < 2) return;
    size_t i = 0;
    size_t j = len - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        ++i;
        --j;
    }
}

int main(void) {
    char a[] = "hello";
    reverse_in_place(a);
    printf("%s\n", a);

    char b[] = "a";
    reverse_in_place(b);
    printf("%s\n", b);

    char c[] = "";
    reverse_in_place(c);
    printf("[%s]\n", c);

    return 0;
}
```

The `len < 2` guard skips the empty string and single characters, so `j = len - 1` never underflows. The swap loop stops when the pointers cross, which avoids reversing the middle character twice for odd lengths. Callers must pass a mutable buffer; a string literal would be read-only and segfault on write.

