    {
        std::vector<int> a{7};
        merge_sorted(a, {});                   // empty source
        assert((a == std::vector<int>{7}));
    }
    {
        std::vector<int> a{1, 1, 2};
        merge_sorted(a, std::vector<int>{1, 2, 2});
        assert((a == std::vector<int>{1, 1, 1, 2, 2, 2}));
