#include <ctype.h>
#include <stdio.h>
#include <string.h>

int is_palindrome(const char *s) {
    size_t i = 0, j = strlen(s);
    while (i < j) {
        while (i < j && !isalnum((unsigned char)s[i])) i++;
        while (i < j && !isalnum((unsigned char)s[j - 1])) j--;
        if (i >= j) break;
        if (tolower((unsigned char)s[i]) != tolower((unsigned char)s[j - 1]))
            return 0;
        i++;
        j--;
    }
    return 1;
}

int main(void) {
    const char *cases[][2] = {
        {"A man, a plan, a canal: Panama", "1"},
        {"", "1"},
        {"!!!", "1"},
        {"race a car", "0"},
        {"No 'x' in Nixon", "1"},
        {"\xc3\xa9\xc3\xa9", "1"}, /* UTF-8 bytes are not ASCII alnum -> skipped */
    };
    for (size_t k = 0; k < sizeof(cases) / sizeof(cases[0]); k++) {
        int got = is_palindrome(cases[k][0]);
        if (got != (cases[k][1][0] == '1')) {
            fprintf(stderr, "FAIL: %s\n", cases[k][0]);
            return 1;
        }
    }
    puts("ok");
    return 0;
}
```

The `(unsigned char)` casts are required: passing a negative `char` to `isalnum`/`tolower` is undefined behaviour. UTF-8 multi-byte sequences fall outside `isalnum` in the C locale, so accented text is ignored rather than misread.

```rust
fn fib_mod(n: u64, m: u64) -> u64 {
    assert!(m > 0, "modulus must be positive");
    // Returns (F(k), F(k+1)) mod m.
    fn fd(k: u64, m: u64) -> (u64, u64) {
        if k == 0 {
            return (0, 1 % m);
        }
        let (a, b) = fd(k >> 1, m);
        let c = a * ((2 * b % m + m - a) % m) % m; // F(2k)
        let d = (a * a % m + b * b % m) % m;       // F(2k+1)
        if k & 1 == 0 {
            (c, d)
        } else {
            (d, (c + d) % m)
        }
    }
    fd(n, m).0
}

fn main() {
    assert_eq!(fib_mod(0, 1000), 0);
    assert_eq!(fib_mod(1, 1000), 1);
    assert_eq!(fib_mod(10, 1000), 55);
    assert_eq!(fib_mod(1_000_000, 1_000_000_007), 195023205);
    println!("ok");
}
```

Fast doubling is O(log n) and touches only products below `m*m`, so it stays within `u64` for moduli under about 4 billion. `1 % m` guards the `m == 1` case, where every result is 0.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <optional>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& v) {
        if (size_ == N) return false;
        data_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }

    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T v = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    assert(rb.empty());
    assert(rb.pop() == std::nullopt);
    assert(rb.push(1) && rb.push(2) && rb.push(3));
    assert(rb.full() && !rb.push(4));           // overflow rejected
    assert(rb.pop() == 1);
    assert(rb.push(4));                          // space reused after pop
    assert(rb.pop() == 2 && rb.pop() == 3 && rb.pop() == 4);
    assert(rb.empty() && !rb.push(5));
    assert(rb.pop() == 5);
    std::cout << "ok\n";
}
```

The wrap uses `(head_ + size_) % N` for the write slot rather than a second index, so head and tail stay consistent even after many overflow-and-drain cycles. `std::optional` makes "empty" explicit instead of returning a sentinel value.

