#include <optional>
#include <vector>
#include <limits>

template <typename T>
std::optional<T> second_largest_distinct(const std::vector<T>& v) {
    if (v.size() < 2) return std::nullopt;
    bool have_max = false;
    T max{}, second{};
    for (const T& x : v) {
        if (!have_max || x > max) {
            if (have_max && max != x) second = max;
            max = x;
            have_max = true;
        } else if (x != max && (!second || x > second)) {
            second = x;
        }
    }
    if (!have_max || second == max) return std::nullopt;
    return second;
}
```
The `x != max` guard ensures duplicates of the largest value never become the second largest.

