use std::env;
use std::fs;

#[derive(Debug)]
pub struct Stats {
    pub n: usize,
    pub mean: f64,
    pub variance: f64,
    pub stddev: f64,
}

pub fn compute(values: &[f64]) -> Option<Stats> {
    if values.is_empty() {
        return None;
    }
    let n = values.len();
    let mean = values.iter().sum::<f64>() / n as f64;
    // Two-pass: numerically stable for the sample variance (denominator n-1).
    let variance = if n > 1 {
        values.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / (n - 1) as f64
    } else {
        0.0
    };
    Some(Stats { n, mean, variance, stddev: variance.sqrt() })
}

fn main() {
    let path = env::args().nth(1).unwrap_or_else(|| "data.txt".into());
    let text = fs::read_to_string(&path).expect("cannot read file");
    let values: Vec<f64> = text
        .split_whitespace()
        .filter_map(|tok| tok.parse::<f64>().ok())
        .collect();
    match compute(&values) {
        Some(s) => println!("n={} mean={:.4} var={:.4} sd={:.4}", s.n, s.mean, s.variance, s.stddev),
        None => println!("no numeric input"),
    }
}
