#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <new>

class Arena {
public:
    explicit Arena(std::size_t bytes) : size_(bytes) {
        base_ = static_cast<unsigned char*>(std::malloc(bytes));
        if (!base_) throw std::bad_alloc();
        offset_ = 0;
    }
    ~Arena() { std::free(base_); }
    Arena(const Arena&) = delete;
    Arena& operator=(const Arena&) = delete;

    // Returns a block whose address is a multiple of `align` (power of two).
    void* alloc(std::size_t bytes, std::size_t align = alignof(std::max_align_t)) {
        std::size_t pad = (-reinterpret_cast<std::uintptr_t>(base_ + offset_)) & (align - 1);
        if (offset_ + pad + bytes > size_) return nullptr;
        void* p = base_ + offset_ + pad;
        offset_ += pad + bytes;
        ++allocs_;
        return p;
    }

    void reset() { offset_ = 0; allocs_ = 0; }
    std::size_t used() const { return offset_; }
    std::size_t liveAllocations() const { return allocs_; }

private:
    unsigned char* base_ = nullptr;
    std::size_t size_ = 0;
    std::size_t offset_ = 0;
    std::size_t allocs_ = 0;
};

int main() {
    Arena a(1024);
    int* p = static_cast<int*>(a.alloc(sizeof(int), alignof(int)));
    if (p) *p = 42;
    double* d = static_cast<double*>(a.alloc(sizeof(double), alignof(double)));
    if (d) *d = 3.5;
    std::printf("used=%zu after two allocs, p=%d d=%f\n", a.used(), p ? *p : -1, d ? *d : -1.0);
    a.reset();
    std::printf("used after reset=%zu\n", a.used());
    return 0;
}
```
Bump-pointer allocation is O(1) with no per-object bookkeeping; `reset()` reclaims everything at once. Alignment is enforced by rounding the cursor up to a multiple of `align`, so over-aligned types work too.

