#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

/* Reverse the list in place and return the new head. */
Node *reverse_list(Node *head) {
    Node *prev = NULL;
    Node *curr = head;
    while (curr != NULL) {
        Node *next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

static Node *push(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    if (!n) return head;
    n->value = value;
    n->next = head;
    return n;
}

int main(void) {
    Node *head = NULL;
    for (int i = 5; i >= 1; i--) head = push(head, i);

    head = reverse_list(head);
    if (head == NULL) { printf("empty list ok\n"); return 0; }

    for (Node *n = head; n; n = n->next) printf("%d ", n->value);
    printf("\n");

    Node *n = head;
    while (n) { Node *tmp = n; n = n->next; free(tmp); }
    return 0;
}
```
The three-pointer walk (`prev`, `curr`, `next`) reverses each link before advancing. `reverse_list(NULL)` returns `NULL`, so empty input is handled without a special case. Output: `5 4 3 2 1`.

