fn merge_sorted<T: Ord + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i].clone());
            i += 1;
        } else {
            out.push(b[j].clone());
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    assert_eq!(merge_sorted(&[1, 3, 5], &[2, 4, 6]), vec![1, 2, 3, 4, 5, 6]);
    assert_eq!(merge_sorted::<i32>(&[], &[]), Vec::<i32>::new());
    assert_eq!(merge_sorted(&[1, 1, 2], &[1, 3]), vec![1, 1, 1, 2, 3]);
    assert_eq!(merge_sorted(&["a", "c"], &["b"]), vec!["a", "b", "c"]);
    println!("all assertions passed");
}
```
The two-pointer walk appends the smaller head each step; once one slice is exhausted, `extend_from_slice` copies the remaining tail. `T: Ord + Clone` covers integers and strings. `with_capacity` avoids reallocation, and equal elements keep left-before-right for stable ordering.

```cpp
#include <iostream>
#include <cstdlib>

template <typename T>
T gcd(T a, T b) {
    // Work with absolute values; gcd is sign-independent.
    a = a < 0 ? -a : a;
    b = b < 0 ? -b : b;
    while (b != 0) {
        T t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    static_assert(std::is_same<decltype(gcd(1, 1)), int>::value, "int in, int out");
    if (gcd(48, 18) != 6) return 1;
    if (gcd(-48, 18) != 6) return 1;
    if (gcd(48, -18) != 6) return 1;
    if (gcd(-48, -18) != 6) return 1;
    if (gcd(0, 5) != 5) return 1;
    if (gcd(0, 0) != 0) return 1;
    if (gcd(17, 5) != 1) return 1;
    if (gcd(1071, 462) != 21) return 1;
    std::cout << "all checks passed\n";
    return 0;
}
```
Euclid's algorithm replaces `(a, b)` with `(b, a % b)` until `b` is zero. Taking absolute values up front makes the result sign-independent, and `gcd(0, 0)` returns 0 by convention since the loop body never executes.

