struct Node {
    int value;
    struct Node *next;
};

struct Node *reverse(struct Node *head) {
    struct Node *prev = NULL;
    while (head) {
        struct Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main(void) {
    struct Node *head = NULL;
    for (int i = 5; i >= 1; --i) {
        struct Node *n = malloc(sizeof *n);
        if (!n) return 1;
        n->value = i;
        n->next = head;
        head = n;
    }

    head = reverse(head);

    for (struct Node *p = head; p; p = p->next) printf("%d%c", p->value, p->next ? ' ' : '\n');

    while (head) {
        struct Node *n = head->next;
        free(head);
        head = n;
    }
    return 0;
}
