#include <stdio.h>
#include <string.h>

void reverse_in_place(char *s) {
    if (s == NULL) return;
    size_t len = strlen(s);
    for (size_t i = 0; i < len / 2; i++) {
        char tmp = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = tmp;
    }
}

int main(void) {
    char buf[] = "hello world";
    reverse_in_place(buf);
    printf("%s\n", buf);

    char empty[] = "";
    reverse_in_place(empty);
    printf("[%s]\n", empty);

    char one[] = "x";
    reverse_in_place(one);
    printf("%s\n", one);
    return 0;
}
```

The loop swaps only up to `len / 2`, so the middle character of an odd-length string stays put and no double-swap occurs. `strlen` is used for length only; the swap itself is manual as requested.

