fn longest_common_prefix(strings: &[&str]) -> String {
    if strings.is_empty() {
        return String::new();
    }

    // Start with the first string, then shrink the prefix until every
    // other string starts with it. Unicode-safe because we compare bytes
    // only via slice boundaries produced by char boundaries below.
    let first = strings[0];
    let mut end = first.len();

    for s in &strings[1..] {
        while end > 0 && !s.as_bytes().starts_with(&first.as_bytes()[..end]) {
            end -= 1;
        }
        if end == 0 {
            return String::new();
        }
    }

    // `end` may land inside a multi-byte char; back it off to a char boundary.
    while !first.is_char_boundary(end) {
        end -= 1;
    }
    first[..end].to_string()
}

fn main() {
    let words = ["flourish", "flow", "flour"];
    println!("{}", longest_common_prefix(&words)); // "flo"
    let non_ascii = ["café", "cafeteria"];
    println!("{}", longest_common_prefix(&non_ascii)); // "caf"
    println!("{}", longest_common_prefix(&[])); // ""
}
