```cpp
#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& data, int target) {
    int lo = 0;
    int hi = static_cast<int>(data.size()) - 1;

    while (lo <= hi) {
        // Avoid (lo + hi) / 2, which can overflow for huge vectors.
        int mid = lo + (hi - lo) / 2;
        if (data[mid] == target) {
            return mid;
        } else if (data[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    std::vector<int> nums = {1, 3, 5, 7, 9, 11};
    std::cout << binary_search(nums, 7) << "\n";   // 3
    std::cout << binary_search(nums, 8) << "\n";   // -1
    std::cout << binary_search({}, 5) << "\n";      // -1
    return 0;
}
```

`lo + (hi - lo) / 2` is the standard overflow-safe midpoint. An empty vector gives `hi = -1`, so the loop never runs and it returns -1. `mid` is `int` because the container is indexed by signed size here; for very large inputs you'd switch to `std::size_t` and a do-while variant.

