from math import isqrt


def primes(segment: int = 1024):
    if segment < 2:
        raise ValueError("segment must be at least 2")

    # Yield the base primes up to the first segment directly.
    small = []
    for n in range(2, segment):
        if all(n % p for p in small if p * p <= n):
            small.append(n)
            yield n

    base = small
    low = segment
    while True:
        high = low + segment
        sieve = bytearray(b"\x01") * (high - low)
        for p in base:
            if p * p >= high:
                break
            start = max(p * p, ((low + p - 1) // p) * p)
            for m in range(start, high, p):
                sieve[m - low] = 0
        for i, flag in enumerate(sieve):
            if flag:
                yield low + i
        low = high


if __name__ == "__main__":
    import itertools

    print(list(itertools.islice(primes(64), 15)))
