#include <algorithm>
#include <iostream>
#include <string>

void reverse_words(std::string& s) {
    // First reverse every character.
    std::reverse(s.begin(), s.end());

    // Then reverse each word back, and collapse whitespace.
    std::string out;
    out.reserve(s.size());

    size_t i = 0;
    while (i < s.size()) {
        while (i < s.size() && s[i] == ' ') ++i;
        if (i >= s.size()) break;

        size_t j = i;
        while (j < s.size() && s[j] != ' ') ++j;

        if (!out.empty()) out.push_back(' ');
        out.append(s, i, j - i);
        i = j;
    }

    s.swap(out);
}

int main() {
    std::string s = "  the quick   brown fox  ";
    reverse_words(s);
    std::cout << "[" << s << "]\n"; // [fox brown quick the]
}
```

Double reversal keeps words in order while flipping sentence order. The second pass skips runs of blanks and inserts exactly one separator, so multiple, leading, and trailing spaces all collapse correctly. `reserve` avoids repeated reallocation.

