    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(n);
    pairs
}

fn main() {
    let text = "The cat and the hat, the CAT sat.";
    assert_eq!(
        top_words(text, 3),
        vec![("the".to_string(), 3), ("cat".to_string(), 2), ("and".to_string(), 1)]
    );
    assert_eq!(top_words("", 5), Vec::<(String, usize)>::new());
    println!("ok");
}
```

Words are lowercased and stripped of punctuation before counting, so `CAT` and `cat` merge. The comparator sorts by descending count then ascending word, giving deterministic tie-breaking; `truncate` caps the result at `n`.

```c
#include <stdio.h>
#include <string.h>

char *reverse_string(char *s) {
    if (s == NULL) {
        return NULL;
    }
    size_t len = strlen(s);
    if (len < 2) {
        return s;
    }
    size_t left = 0;
    size_t right = len - 1;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
    return s;
}

int main(void) {
    char a[] = "hello";
    char b[] = "";
    char c[] = "x";

    printf("%s\n", reverse_string(a));
    printf("%s\n", reverse_string(b));
    printf("%s\n", reverse_string(c));
    printf("%s\n", reverse_string(NULL) == NULL ? "(null)" : "bad");
    return 0;
}
```

Two indices walk toward the center swapping bytes until they meet, which is O(n) and touches each character once. Empty strings and one-character strings are returned untouched, and `NULL` is handled before any dereference.

```cpp
#include <iostream>
#include <vector>

template <typename T>
int binary_search_index(const std::vector<T>& data, const T& target) {
    int low = 0;
    int high = static_cast<int>(data.size()) - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (data[mid] < target) {
            low = mid + 1;
        } else if (target < data[mid]) {
            high = mid - 1;
        } else {
            return mid;
        }
    }
    return -1;
}

int main() {
    std::vector<int> nums = {1, 3, 5, 7, 9, 11};
    std::cout << binary_search_index(nums, 7) << '\n';
    std::cout << binary_search_index(nums, 2) << '\n';
    std::cout << binary_search_index(std::vector<int>{}, 4) << '\n';
    return 0;
}
```

`low + (high - low) / 2` avoids the overflow that `(low + high) / 2` can hit on large vectors. Comparing with `<` in both directions keeps the code generic for any type that defines a strict weak ordering, including custom structs.

