```c
#include <stdio.h>

#define MOD 1000000007ULL

static unsigned long long fib_mod(unsigned long long n) {
    unsigned long long a = 0;
    unsigned long long b = 1;
    for (unsigned long long i = 0; i < n; i++) {
        unsigned long long next = (a + b) % MOD;
        a = b;
        b = next;
    }
    return a;
}

int main(void) {
    unsigned long long n;
    if (scanf("%llu", &n) != 1) {
        fprintf(stderr, "error: expected a non-negative integer\n");
        return 1;
    }
    printf("%llu\n", fib_mod(n));
    return 0;
}
```

Two rolling values hold consecutive Fibonacci numbers; each step reduces modulo `1e9+7` so the sums never overflow 64 bits. `fib_mod(0)` returns 0 and `fib_mod(1)` returns 1. Bad input is reported on stderr with a non-zero exit instead of printing garbage.

