```cpp
#include <array>
#include <cstddef>
#include <optional>

template <std::size_t N>
class RingBuffer {
public:
    bool push(int value) {
        if (size_ == N) {
            return false;
        }
        data_[(head_ + size_) % N] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        int value = data_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

private:
    std::array<int, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};
```

`push` refuses when full and `pop` returns `std::nullopt` when empty, so callers never read garbage. Wrap-around uses modulo on the head plus current size.

