std::optional<double> median(std::vector<T> v) {
    if (v.empty()) return std::nullopt;
    std::sort(v.begin(), v.end());
    const size_t n = v.size();
    if (n % 2 == 1) {
        return static_cast<double>(v[n / 2]);
