bool isPalindrome(const std::string& s) {
    size_t i = 0;
    size_t j = s.size();
    while (i < j) {
        if (j == 0) break;
        --j;
        if (i >= j) break;
        unsigned char li = static_cast<unsigned char>(s[i]);
        unsigned char rj = static_cast<unsigned char>(s[j]);
        if (!std::isalnum(li)) { ++i; continue; }
        if (!std::isalnum(rj)) { continue; }
        if (std::tolower(li) != std::tolower(rj)) return false;
        ++i;
    }
    return true;
}

