    s.chars().count()
}

/// Approximate grapheme count: a char is a new cluster unless it is a
/// combining mark or a zero-width joiner following the previous char.
fn grapheme_approx(s: &str) -> usize {
    fn is_extend(c: char) -> bool {
        matches!(c as u32,
            0x0300..=0x036F | 0x1AB0..=0x1AFF | 0x1DC0..=0x1DFF |
            0x20D0..=0x20FF | 0xFE20..=0xFE2F | 0x200D)
    }
    let mut n = 0usize;
    for c in s.chars() {
        if !is_extend(c) {
            n += 1;
        }
    }
    n
}

fn main() {
    for s in ["hello", "e\u{0301}te", "\u{1F1FA}\u{1F1F8}", ""] {
        println!("{:?}: scalars={} graphemes~={}", s, scalar_count(s), grapheme_approx(s));
    }
}
```

For production, use `unicode-segmentation`; the above is an honest approximation and says so.

```python
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError('capacity must be positive')
        self.capacity = capacity
        self._data: OrderedDict = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        return len(self._data)

if __name__ == '__main__':
    c = LRUCache(2)
    c.put('a', 1); c.put('b', 2)
    assert c.get('a') == 1
    c.put('c', 3)              # evicts 'b'
    assert c.get('b') is None
    assert c.get('a') == 1 and c.get('c') == 3
    print('all checks passed')
```

`OrderedDict.move_to_end` gives O(1) recency updates and `popitem(last=False)` evicts the oldest.

```c
#include <stdio.h>
#include <ctype.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s FILE\n", argv[0]);
        return 2;
    }
    FILE *f = fopen(argv[1], "r");
    if (!f) {
        perror("fopen");
        return 1;
    }

    unsigned long bytes = 0, lines = 0, words = 0;
    int in_word = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        bytes++;
        if (c == '\n') lines++;
        if (isspace(c)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            words++;
        }
    }
    /* a non-empty final line without a trailing newline still counts */
    if (in_word) { /* already counted word; add the line */ }
    int last = 0;
    if (bytes > 0) {
        /* re-open cheaply to check trailing newline */
        fseek(f, -1, SEEK_END);
        last = fgetc(f);
    }
    fclose(f);
    if (bytes > 0 && last != '\n') lines++;

    printf("bytes=%lu lines=%lu words=%lu\n", bytes, lines, words);
    return 0;
}
```

Note the last-line handling: GNU `wc -l` does *not* count a final line lacking `\n`, while `wc -c`/`wc -w` do; this version matches that convention after the fixup.

