template <typename T>
std::optional<double> average(const std::vector<T>& v) {
    if (v.empty()) return std::nullopt;
    double sum = std::accumulate(v.begin(), v.end(), 0.0);
    return sum / static_cast<double>(v.size());
}

int main() {
    std::vector<int> ints{1, 2, 3, 4};
    std::vector<int> empty{};
    std::vector<double> dbl{1.5, 2.5};

    if (auto a = average(ints)) std::cout << *a << '\n';       // 2.5, not 2
    if (auto a = average(dbl))  std::cout << *a << '\n';       // 2.0
    std::cout << (average(empty).has_value() ? "ok" : "empty") << '\n';
}
