std::vector<int> sieve(int limit) {
    std::vector<int> primes;
    if (limit < 2) return primes;
    std::vector<bool> composite(static_cast<std::size_t>(limit) + 1, false);
    for (int i = 2; i <= limit; ++i) {
        if (composite[static_cast<std::size_t>(i)]) continue;
        primes.push_back(i);
        if (static_cast<long long>(i) * i <= limit) {
            for (long long j = static_cast<long long>(i) * i; j <= limit; j += i) {
                composite[static_cast<std::size_t>(j)] = true;
            }
        }
    }
    return primes;
}

int main(int argc, char** argv) {
    int limit = 50;
    if (argc > 1) {
        try {
            limit = std::stoi(argv[1]);
        } catch (...) {
            std::cerr << "invalid limit: " << argv[1] << '\n';
            return 1;
        }
    }
    if (limit < 0) {
        std::cerr << "limit must be non-negative\n";
        return 1;
    }
    const auto primes = sieve(limit);
    std::cout << primes.size() << " primes <= " << limit << '\n';
    for (int p : primes) std::cout << p << ' ';
    std::cout << '\n';
    return 0;
