std::vector<int> primes_up_to(int n) {
    std::vector<int> out;
    if (n < 2) return out;
    std::vector<bool> composite(n + 1, false);
    for (int p = 2; p * p <= n; ++p) {
        if (!composite[p]) {
            for (int m = p * p; m <= n; m += p) composite[m] = true;
        }
    }
    for (int p = 2; p <= n; ++p)
        if (!composite[p]) out.push_back(p);
    return out;
