fn shift(c: char, n: u32) -> char {
    if c.is_ascii_lowercase() {
        (((c as u8 - b'a' + (n % 26) as u8) % 26) + b'a') as char
    } else if c.is_ascii_uppercase() {
        (((c as u8 - b'A' + (n % 26) as u8) % 26) + b'A') as char
    } else {
        c
    }
}

fn caesar(s: &str, n: u32) -> String {
    s.chars().map(|c| shift(c, n)).collect()
