Fixed-capacity ring buffer that reports overflow instead of clobbering live data.

```cpp
#include <array>
#include <cstddef>
#include <optional>
#include <iostream>

template <typename T, std::size_t N>
class RingBuffer {
public:
    bool push(const T& v) {
        if (size_ == N) return false;
        buf_[(head_ + size_) % N] = v;
        ++size_;
        return true;
    }
    std::optional<T> pop() {
        if (size_ == 0) return std::nullopt;
        T v = buf_[head_];
        head_ = (head_ + 1) % N;
        --size_;
        return v;
    }
    std::size_t size() const { return size_; }
private:
    std::array<T, N> buf_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

int main() {
    RingBuffer<int, 3> rb;
    for (int i = 1; i <= 4; ++i)
        std::cout << i << " -> " << (rb.push(i) ? "ok" : "full") << '\n';
    while (auto v = rb.pop())
        std::cout << "pop " << *v << '\n';
}
```

The contents live in `buf_` with `head_` and `size_` as cursors, so `pop` is O(1) without shifting. The fourth push returns `false` rather than clobbering the oldest element, and `pop` on an empty buffer returns `std::nullopt`.

