Round-trips simple run-length encoding:

```python
def rle_encode(s: str) -> str:
    if not s:
        return ""
    parts = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            parts.append(f"{count}{prev}")
            prev = ch
            count = 1
    parts.append(f"{count}{prev}")
    return "".join(parts)

def rle_decode(s: str) -> str:
    out = []
    num = ""
    for ch in s:
        if ch.isdigit():
            num += ch
        else:
            out.append(ch * int(num or "1"))
            num = ""
    if num:
        raise ValueError("trailing count with no character")
    return "".join(out)

if __name__ == "__main__":
    assert rle_encode("aaabbc") == "3a2b1c"
    assert rle_decode("3a2b1c") == "aaabbc"
    assert rle_encode("") == ""
    print(rle_encode("wwwwaaadexxxxxx"))
