```python
import sys

OPS = {
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '/': lambda a, b: a / b,
}


def evaluate(tokens):
    stack = []
    for tok in tokens:
        if tok in OPS:
            if len(stack) < 2:
                raise ValueError(f"'{tok}' needs two operands")
            b = stack.pop()
            a = stack.pop()
            if tok == '/' and b == 0:
                raise ValueError("division by zero")
            stack.append(OPS[tok](a, b))
        else:
            try:
                stack.append(float(tok))
            except ValueError:
                raise ValueError(f"not a number or operator: {tok}")
    if len(stack) != 1:
        raise ValueError("expression left extra values on the stack")
    return stack[0]


def main():
    expr = sys.argv[1] if len(sys.argv) > 1 else "3 4 + 2 *"
    try:
        result = evaluate(expr.split())
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    print(result)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
