Matrix multiply(const Matrix& a, const Matrix& b) {
    if (a.empty() || b.empty() || a[0].size() != b.size()) {
        throw std::invalid_argument("incompatible dimensions");
    }
    const std::size_t n = a.size();
    const std::size_t k = b.size();
    const std::size_t m = b[0].size();
    for (const auto& row : a)
        if (row.size() != k) throw std::invalid_argument("ragged matrix a");
    for (const auto& row : b)
        if (row.size() != m) throw std::invalid_argument("ragged matrix b");

    Matrix out(n, std::vector<long long>(m, 0));
    for (std::size_t i = 0; i < n; ++i)
        for (std::size_t j = 0; j < m; ++j)
            for (std::size_t p = 0; p < k; ++p)
                out[i][j] += a[i][p] * b[p][j];
    return out;
}

int main() {
