std::string caesar(const std::string& text, int shift) {
    shift = ((shift % 26) + 26) % 26;
    std::string out = text;
    for (char& c : out) {
        if (std::isupper(static_cast<unsigned char>(c)))
            c = static_cast<char>('A' + (c - 'A' + shift) % 26);
        else if (std::islower(static_cast<unsigned char>(c)))
            c = static_cast<char>('a' + (c - 'a' + shift) % 26);
    }
    return out;
}

int main(int argc, char** argv) {
    std::string text = argc > 1 ? argv[1] : "Attack at Dawn!";
    int shift = 3;
    if (argc > 2) {
        try {
            shift = std::stoi(argv[2]);
        } catch (...) {
            std::cerr << "shift must be an integer\n";
            return 1;
        }
    }
    const std::string encoded = caesar(text, shift);
    const std::string decoded = caesar(encoded, -shift);
    std::cout << "plain:   " << text << '\n';
    std::cout << "encoded: " << encoded << '\n';
    std::cout << "decoded: " << decoded << '\n';
    return decoded == text ? 0 : 1;
}
