int lower_bound_index(const std::vector<int>& data, int target) {
    std::size_t lo = 0;
    std::size_t hi = data.size();
    while (lo < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (data[mid] < target)
            lo = mid + 1;
        else
            hi = mid;
    }
    return static_cast<int>(lo);
}

int main() {
    const std::vector<int> data = {1, 3, 3, 5, 8, 13};
    for (int target : {0, 3, 4, 13, 20}) {
        const int idx = lower_bound_index(data, target);
        const bool found = idx < static_cast<int>(data.size()) && data[idx] == target;
        std::cout << target << " -> index " << idx
                  << (found ? " (found)" : " (absent)") << '\n';
    }
    return 0;
}
