    assert bsearch([1, 3, 5, 7], 1) == 0
    assert bsearch([1, 3, 5, 7], 7) == 3
    assert bsearch([1, 3, 5, 7], 5) == 2
    assert bsearch([1, 3, 5, 7], 4) == -1
