def encode(text):
    if not text:
        return ""
    out = []
    count = 1
    for i in range(1, len(text)):
        if text[i] == text[i - 1]:
            count += 1
        else:
            out.append(f"{count}{text[i - 1]}")
            count = 1
    out.append(f"{count}{text[-1]}")
    return "".join(out)


def decode(data):
    out = []
    i = 0
    while i < len(data):
        if not data[i].isdigit():
            raise ValueError(f"expected count at index {i}")
        j = i
        while j < len(data) and data[j].isdigit():
            j += 1
        if j == len(data):
            raise ValueError("missing character after count")
        out.append(data[j] * int(data[i:j]))
        i = j + 1
    return "".join(out)


if __name__ == "__main__":
    sample = "aaabbc\U0001F600\U0001F600"
    encoded = encode(sample)
    print(encoded)
    assert decode(encoded) == sample
    assert encode("") == ""
    assert decode("1z") == "z"
    try:
        decode("12")
    except ValueError as exc:
        print("rejected:", exc)
    print("roundtrip ok")
