#include <iostream>
#include <vector>

using Matrix = std::vector<std::vector<long long>>;

bool multiply(const Matrix& a, const Matrix& b, Matrix& out) {
    if (a.empty() || b.empty() || a[0].empty() || b[0].empty()) return false;
    const std::size_t n = a.size(), m = a[0].size();
    const std::size_t p = b.size(), q = b[0].size();
    for (const auto& row : a)
        if (row.size() != m) return false;
    for (const auto& row : b)
        if (row.size() != q) return false;
    if (m != p) return false;

    out.assign(n, std::vector<long long>(q, 0));
    for (std::size_t i = 0; i < n; ++i)
        for (std::size_t k = 0; k < m; ++k)
            for (std::size_t j = 0; j < q; ++j)
                out[i][j] += a[i][k] * b[k][j];
    return true;
}

int main() {
    Matrix a = {{1, 2}, {3, 4}};
    Matrix b = {{5, 6}, {7, 8}};
    Matrix c;
    if (!multiply(a, b, c)) {
        std::cerr << "bad dimensions\n";
        return 1;
    }
    for (const auto& row : c) {
        for (std::size_t j = 0; j < row.size(); ++j)
            std::cout << (j ? " " : "") << row[j];
        std::cout << '\n';
    }
    return 0;
}
