#include <iostream>
#include <memory>
#include <string>

struct Node {
    std::unique_ptr<Node> next[26];
    bool end = false;
};

void insert(Node& root, const std::string& word) {
    Node* cur = &root;
    for (char ch : word) {
        if (ch < 'a' || ch > 'z') continue;
        int i = ch - 'a';
        if (!cur->next[i]) cur->next[i] = std::make_unique<Node>();
        cur = cur->next[i].get();
    }
    cur->end = true;
}

bool contains(const Node& root, const std::string& word) {
    const Node* cur = &root;
    for (char ch : word) {
        if (ch < 'a' || ch > 'z') return false;
        int i = ch - 'a';
        if (!cur->next[i]) return false;
        cur = cur->next[i].get();
    }
    return cur->end;
}

int main() {
    Node root;
    insert(root, "cat");
    insert(root, "car");
    std::cout << std::boolalpha
              << contains(root, "cat") << ' '
              << contains(root, "ca") << ' '
              << contains(root, "dog") << '\n';
    return 0;
}
