```python
def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start = end = 0

    def expand(lo: int, hi: int) -> tuple[int, int]:
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return lo + 1, hi - 1  # backed off last mismatch

    for i in range(len(s)):
        a, b = expand(i, i)        # odd length
        c, d = expand(i, i + 1)    # even length
        if b - a > end - start:
            start, end = a, b
        if d - c > end - start:
            start, end = c, d

    return s[start:end + 1]
```

