static void heapSort(std::vector<T>& a, int lo, int hi) {
    for (int i = lo + (hi - lo) / 2 - 1; i >= lo; --i) siftDown(a, i, hi);
    for (int i = hi - 1; i > lo; --i) { std::swap(a[lo], a[i]); siftDown(a, lo, i); }
