int parse_int(const char *s, int *out) {
    if (s == NULL || out == NULL || *s == '\0') return 0;
    char *end = NULL;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno == ERANGE || v < INT_MIN || v > INT_MAX) return 0;
    if (*end != '\0') return 0;   /* trailing garbage */
    *out = (int)v;
    return 1;
}

int main(void) {
    const char *tests[] = {"42", "-7", "9999999999", "12abc", ""};
    for (int i = 0; i < 5; i++) {
        int value;
        if (parse_int(tests[i], &value)) {
            printf("%s -> %d\n", tests[i], value);
        } else {
            printf("%s -> invalid\n", tests[i]);
        }
    }
    return 0;
}
```

